UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: catiyeh@mymailroom.au\", \"vi\": \"Đến: catiyeh@mymailroom.au\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: achen@mutamark.au\", \"vi\": \"Từ: achen@mutamark.au\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 1 July\", \"vi\": \"Ngày: 1 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Mutamark conference\", \"vi\": \"Chủ đề: Hội nghị Mutamark\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Atiyeh,\", \"vi\": \"Kính gửi Bà Atiyeh,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"To follow up on our phone conversation earlier today, I would like to extend to you a formal written invitation to speak at the eighth annual Mutamark conference, scheduled to take place this year from 17 to 20 September in Zagros.\", \"vi\": \"Để tiếp theo cuộc điện thoại của chúng ta vào đầu ngày hôm nay, tôi muốn gửi đến bà lời mời chính thức bằng văn bản để phát biểu tại hội nghị thường niên lần thứ tám của Mutamark, dự kiến diễn ra trong năm nay từ ngày 17 đến 20 tháng 9 tại Zagros.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Because you drew a sizeable crowd when you appeared at the conference in the past, we will be making special arrangements for your visit this time.\", \"vi\": \"Vì bà từng thu hút lượng lớn khán giả khi tham dự hội nghị trước đây, chúng tôi sẽ sắp xếp đặc biệt cho chuyến thăm của bà lần này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The Blue Room at the Debeljak Hotel holds only 120, so this year we are also booking the Koros Hall, which has a capacity of 270.\", \"vi\": \"Phòng Blue tại Khách sạn Debeljak chỉ chứa được 120 người, vì vậy năm nay chúng tôi cũng đặt thêm Hội trường Koros với sức chứa 270 người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We can offer you a 40-to-50-minute slot on the last day of the conference, when attendance should be at its peak.\", \"vi\": \"Chúng tôi có thể sắp xếp cho bà một khung giờ từ 40 đến 50 phút vào ngày cuối cùng của hội nghị, thời điểm mà lượng người tham dự dự kiến sẽ đạt mức cao nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please e-mail me to confirm your acceptance and to let me know more about your audiovisual requirements.\", \"vi\": \"Vui lòng gửi email cho tôi để xác nhận sự đồng ý của bà và cho tôi biết thêm về các yêu cầu thiết bị nghe nhìn của bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We can provide overhead projection for still images if you will be using them again.\", \"vi\": \"Chúng tôi có thể cung cấp máy chiếu hắt để chiếu hình ảnh tĩnh nếu bà sẽ tiếp tục sử dụng chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Very best regards,\", \"vi\": \"Trân trọng nhất,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Alex Chen, Conference Planning\", \"vi\": \"Alex Chen, Bộ phận Lập kế hoạch Hội nghị\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Mutamark Headquarters, Melbourne\", \"vi\": \"Trụ sở chính Mutamark, Melbourne\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '00188823-c39d-49da-917a-29026b478029';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"May 5—Boston law firm Warner and Ames announced this morning that it is merging with the Philadelphia law firm Hamilton Jones to create Warner, Hamilton, and Associates.\", \"vi\": \"Ngày 5 tháng 5—Công ty luật Warner and Ames tại Boston đã thông báo sáng nay rằng họ đang hợp nhất với công ty luật Hamilton Jones tại Philadelphia để thành lập Warner, Hamilton, and Associates.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"With more than 655 attorneys, the merger will make this the largest law firm in the northeastern United States.\", \"vi\": \"Với hơn 655 luật sư, vụ sáp nhập này sẽ biến đây thành công ty luật lớn nhất ở vùng đông bắc Hoa Kỳ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"\\\"This is a welcome merger of two well-managed firms who share similar corporate cultures and philosophies,\\\" said Andrea Warner, codirector of the former Warner and Ames, who will serve as managing partner of Warner, Hamilton, and Associates.\", \"vi\": \"\\\"Đây là sự sáp nhập đáng hoan nghênh của hai công ty được quản lý tốt, có chung nền văn hóa và triết lý doanh nghiệp tương đồng,\\\" Andrea Warner, đồng giám đốc của công ty Warner and Ames trước đây, người sẽ đảm nhận vai trò đối tác quản lý của Warner, Hamilton, and Associates cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"\\\"Our combined expertise makes Warner, Hamilton, and Associates uniquely placed to provide clients even higher levels of counsel and service.\", \"vi\": \"\\\"Chuyên môn kết hợp của chúng tôi giúp Warner, Hamilton, and Associates có vị thế độc tôn trong việc cung cấp cho khách hàng mức độ tư vấn và dịch vụ thậm chí còn cao hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We look forward to continuing our practices in Boston and Philadelphia and expect to open yet another office in Hartford within the next twelve months.\\\"\", \"vi\": \"Chúng tôi mong muốn tiếp tục hoạt động hành nghề tại Boston và Philadelphia, đồng thời dự kiến mở thêm một văn phòng khác tại Hartford trong mười hai tháng tới.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"According to a press release, Ms. Warner has garnered attention through her representation of clients across the country in prominent cases involving workers\' rights, equal pay, and social justice.\", \"vi\": \"Theo thông cáo báo chí, bà Warner đã thu hút sự chú ý thông qua việc đại diện cho khách hàng trên toàn quốc trong các vụ án nổi bật liên quan đến quyền lợi của người lao động, trả lương công bằng và công bằng xã hội.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The firm expects to keep all of its current lawyers and staff and will \\\"combine management teams made up of partners from each firm to ensure a seamless transition,\\\" the release said.\", \"vi\": \"Công ty dự kiến giữ lại tất cả các luật sư và nhân viên hiện tại của mình, đồng thời sẽ \\\"kết hợp các đội ngũ quản lý gồm các đối tác từ mỗi công ty để đảm bảo quá trình chuyển đổi diễn ra suôn sẻ,\\\" thông cáo cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '003c4fe2-3082-464d-a219-b68a920ecf8f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Pinnacle Sports Club Membership Agreement\", \"vi\": \"Thoả thuận hội viên Câu lạc bộ Thể thao Pinnacle\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Member Name: Mary Swansone\", \"vi\": \"Tên hội viên: Mary Swansone\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Membership Type: 12 months\", \"vi\": \"Loại hội viên: 12 tháng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Begin Date: September 5\", \"vi\": \"Ngày bắt đầu: Ngày 5 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Enrollment Fee: $25\", \"vi\": \"Phí gia nhập: $25\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Monthly Dues: $32 per month\", \"vi\": \"Phí hội viên hàng tháng: $32 mỗi tháng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Payment Method: Credit card\", \"vi\": \"Phương thức thanh toán: Thẻ tín dụng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Thank you for joining Pinnacle Sports Club.\", \"vi\": \"Cảm ơn bạn đã tham gia Câu lạc bộ Thể thao Pinnacle.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As a club member, you have unlimited access to all gym equipment, fitness classes, and the swimming pool.\", \"vi\": \"Là một hội viên của câu lạc bộ, bạn có quyền truy cập không giới hạn vào tất cả các thiết bị tập thể hình, lớp học thể dục và hồ bơi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please present your membership card to the front-desk attendant upon entry.\", \"vi\": \"Vui lòng xuất trình thẻ hội viên của bạn cho nhân viên lễ tân khi vào cửa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"If for any reason you need to discontinue your membership before the 12-month contract period has expired, you must write a letter and send it by mail to the Pinnacle Sports Club, 171 Aqua Street, Germantown, California 95913.\", \"vi\": \"Nếu vì bất kỳ lý do gì mà bạn cần chấm dứt tư cách hội viên trước khi thời hạn hợp đồng 12 tháng kết thúc, bạn phải viết thư và gửi qua đường bưu điện đến Câu lạc bộ Thể thao Pinnacle, số 171 Phố Aqua, Germantown, California 95913.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"A penalty will apply.\", \"vi\": \"Sẽ có khoản phí phạt được áp dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Signed: Mary Swansone\", \"vi\": \"Ký tên: Mary Swansone\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '007da362-687f-4eee-bab0-1f93bb1aaa39';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Attention, Alden-Apner Industries Employees:\", \"vi\": \"Kính gửi Nhân viên Công ty Alden-Apner Industries:\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Please remember that the switch to our new e-mail software will begin at 11:00 P.M. on Sunday, May 2.\", \"vi\": \"Xin vui lòng ghi nhớ rằng việc chuyển đổi sang phần mềm email mới của chúng ta sẽ bắt đầu vào lúc 11:00 tối Chủ Nhật, ngày 2 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"All ______[135] information in your account, including contacts and calendar events, will be moved to the new system by 4:00 A.M. on Monday, May 3.\", \"vi\": \"Tất cả thông tin ______[135] trong tài khoản của bạn, bao gồm danh bạ và các sự kiện lịch, sẽ được chuyển sang hệ thống mới trước 4:00 sáng Thứ Hai, ngày 3 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"Though we are working diligently to anticipate and provide solutions for all potential issues, some employees may experience difficulty ______[136] attempting to log in to their accounts after the switch.\", \"vi\": \"Mặc dù chúng tôi đang nỗ lực làm việc để lường trước và đưa ra giải pháp cho mọi vấn đề tiềm ẩn, một số nhân viên có thể gặp khó khăn ______[136] khi cố gắng đăng nhập vào tài khoản của họ sau khi chuyển đổi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"In addition, there is a remote possibility that some information may be lost.\", \"vi\": \"Ngoài ra, có một khả năng nhỏ là một số thông tin có thể bị mất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[137], be sure to back up any critical e-mail files as soon as possible.\", \"vi\": \"______[137], hãy nhớ sao lưu mọi tệp email quan trọng càng sớm càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [137]}, {\"en\": \"______[138].\", \"vi\": \"______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [138]}, {\"en\": \"A training session will be scheduled next week to familiarize employees with key functions of the new software.\", \"vi\": \"Một buổi đào tạo sẽ được lên lịch vào tuần tới để giúp nhân viên làm quen với các chức năng chính của phần mềm mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '00853caa-77ef-46c6-ae56-f3a077b37326';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Birch Hill Center for the Arts Committee\\nSupporters\' Newsletter\", \"vi\": \"Ủy ban Trung tâm Nghệ thuật Birch Hill\\nBản tin dành cho Người ủng hộ\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The committee has been hard at work this year!\", \"vi\": \"Ủy ban đã làm việc rất chăm chỉ trong năm nay!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We are close to reaching our goal of building a community arts center that will serve all the people of our lovely town of Birch Hill.\", \"vi\": \"Chúng ta đang đến gần việc đạt được mục tiêu xây dựng một trung tâm nghệ thuật cộng đồng phục vụ tất cả người dân ở thị trấn Birch Hill xinh đẹp của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Here is what we have accomplished so far.\", \"vi\": \"Dưới đây là những gì chúng ta đã đạt được cho đến nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"In January, we completed a community survey about what activities to offer in the new Birch Hill Center for the Arts.\", \"vi\": \"Vào tháng Giêng, chúng tôi đã hoàn thành một cuộc khảo sát cộng đồng về các hoạt động sẽ cung cấp tại Trung tâm Nghệ thuật Birch Hill mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"In February, we completed a feasibility report and narrowed the potential building sites to three possibilities.\", \"vi\": \"Vào tháng Hai, chúng tôi đã hoàn thành báo cáo tính khả thi và thu hẹp các địa điểm xây dựng tiềm năng xuống còn ba khả năng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In April, we submitted our project budget proposal to the city council for approval.\", \"vi\": \"Vào tháng Tư, chúng tôi đã nộp đề xuất ngân sách dự án lên hội đồng thành phố để phê duyệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In May, we interviewed several candidates for the managing director position.\", \"vi\": \"Vào tháng Năm, chúng tôi đã phỏng vấn một số ứng viên cho vị trí giám đốc điều hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"During the next two months, we will:\", \"vi\": \"Trong hai tháng tới, chúng tôi sẽ:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Select our new managing director\", \"vi\": \"Lựa chọn giám đốc điều hành mới của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Choose the location for the center\", \"vi\": \"Chọn địa điểm cho trung tâm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Complete the construction blueprints\", \"vi\": \"Hoàn thành bản vẽ thiết kế xây dựng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Finalize the construction budget and timeline\", \"vi\": \"Hoàn thiện ngân sách và tiến độ xây dựng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Draft our events calendar\", \"vi\": \"Lên dự thảo lịch sự kiện của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"And this fall, we should begin construction on the Birch Hill Center for the Arts!\", \"vi\": \"Và vào mùa thu này, chúng ta nên bắt đầu xây dựng Trung tâm Nghệ thuật Birch Hill!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"As always, we welcome your input on the process.\", \"vi\": \"Như mọi khi, chúng tôi hoan nghênh mọi ý kiến đóng góp của bạn về quá trình này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Please send questions or comments to our committee at project@bhca.org.\", \"vi\": \"Vui lòng gửi câu hỏi hoặc nhận xét đến ủy ban của chúng tôi theo địa chỉ project@bhca.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"If you are interested in serving on the committee, please call 952-555-0128.\", \"vi\": \"Nếu bạn quan tâm đến việc tham gia phục vụ trong ủy ban, vui lòng gọi số 952-555-0128.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '00c9f5ed-101b-43e9-995a-d2df901e18bd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"DISTRICT SALES MANAGER\", \"vi\": \"TRƯỞNG PHÒNG KINH DOANH KHU VỰC\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Eason Technologies, a premier provider of energy-efficient air-conditioning systems for offices and retail facilities, is seeking a sales manager for our southwest district.\", \"vi\": \"Eason Technologies, nhà cung cấp hàng đầu về hệ thống điều hòa không khí tiết kiệm năng lượng cho văn phòng và các cơ sở bán lẻ, đang tìm kiếm một trưởng phòng kinh doanh cho khu vực tây nam của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The position is based in Barrow.\", \"vi\": \"Vị trí này làm việc tại Barrow.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"👤 Responsibilities:\", \"vi\": \"👤 Trách nhiệm công việc:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"overseeing the activities of the district sales team\", \"vi\": \"giám sát các hoạt động của đội ngũ kinh doanh khu vực\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"identifying potential customers and acquiring their business\", \"vi\": \"xác định khách hàng tiềm năng và giành được hợp đồng kinh doanh của họ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"forecasting and tracking sales accurately\", \"vi\": \"dự báo và theo dõi doanh số bán hàng một cách chính xác\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"monitoring customer satisfaction to ensure retention\", \"vi\": \"theo dõi sự hài lòng của khách hàng để đảm bảo tỷ lệ giữ chân khách hàng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"👤 Required qualifications:\", \"vi\": \"👤 Yêu cầu năng lực:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"a degree in business or a technical field\", \"vi\": \"bằng cấp về kinh doanh hoặc một lĩnh vực kỹ thuật\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"five years of experience in a sales leadership role\", \"vi\": \"năm năm kinh nghiệm ở vai trò lãnh đạo kinh doanh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"excellent public speaking skills\", \"vi\": \"kỹ năng thuyết trình trước công chúng xuất sắc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"willingness to travel frequently\", \"vi\": \"sẵn sàng đi công tác thường xuyên\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To apply, send your résumé and a cover letter to hiring@easontech.com.\", \"vi\": \"Để ứng tuyển, hãy gửi sơ yếu lý lịch và thư xin việc của bạn tới hiring@easontech.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"From: So-Won Na\", \"vi\": \"Từ: So-Won Na\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To: Brandon Fisher\", \"vi\": \"Đến: Brandon Fisher\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Subject: Potential candidate\", \"vi\": \"Chủ đề: Ứng viên tiềm năng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date: January 30\", \"vi\": \"Ngày: 30 tháng 1\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Hello Brandon,\", \"vi\": \"Chào Brandon,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I wanted to let you know about someone who may be a good candidate for the southwest district sales manager position.\", \"vi\": \"Tôi muốn thông báo cho bạn về một người có thể là ứng viên phù hợp cho vị trí trưởng phòng kinh doanh khu vực tây nam.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"His name is Edgar Malone, and he’s a sales representative at Levya Corporation.\", \"vi\": \"Tên anh ấy là Edgar Malone, và anh ấy là đại diện kinh doanh tại Tập đoàn Levya.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"We became friends after running into each other at trade shows around the country.\", \"vi\": \"Chúng tôi trở thành bạn sau khi tình cờ gặp nhau tại các hội chợ thương mại trên khắp cả nước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I saw him give sales pitches a couple of times at them, and he’s very good at it.\", \"vi\": \"Tôi đã thấy anh ấy thuyết trình bán hàng vài lần tại đó, và anh ấy làm việc đó rất giỏi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I believe he’s been at Levya for at least five years and has a degree in mechanical engineering.\", \"vi\": \"Tôi tin rằng anh ấy đã làm việc tại Levya ít nhất năm năm và có bằng cử nhân kỹ thuật cơ khí.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Shall I send him an e-mail sharing the job advertisement and suggesting that he apply?\", \"vi\": \"Tôi có nên gửi cho anh ấy một email chia sẻ thông báo tuyển dụng và gợi ý anh ấy ứng tuyển không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Thân ái,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"So-Won\", \"vi\": \"So-Won\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Tin nhắn email\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '00d7c5da-29b0-4b34-b72b-a53621e542e1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Saral Malik <smalik@bristek.co.uk>\", \"vi\": \"Đến: Saral Malik <smalik@bristek.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Juna Schirmer <jschirmer@diedrichindustries.de>\", \"vi\": \"Từ: Juna Schirmer <jschirmer@diedrichindustries.de>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 11 May\", \"vi\": \"Ngày: 11 tháng 5\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: RE: Information update\", \"vi\": \"Chủ đề: V/v: Cập nhật thông tin\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Brochure\", \"vi\": \"Đính kèm: Tập tài liệu giới thiệu\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Malik:\", \"vi\": \"Kính gửi ông Malik:\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for your e-mail.\", \"vi\": \"Cảm ơn email của ông.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I can confirm that your shipment is now in transit.\", \"vi\": \"Tôi có thể xác nhận rằng lô hàng của ông hiện đang trên đường vận chuyển.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I apologise for the longer-than-expected wait.\", \"vi\": \"Tôi thành thật xin lỗi vì thời gian chờ đợi kéo dài hơn dự kiến.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We recently started working with a new packaging supply company, and unfortunately, we experienced a miscommunication with them.\", \"vi\": \"Chúng tôi gần đây đã bắt đầu hợp tác với một công ty cung cấp vật liệu đóng gói mới, và thật không may, chúng tôi đã gặp sự cố hiểu lầm với họ.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The company supplied us with boxes that were too small to fulfill your order.\", \"vi\": \"Công ty đó đã cung cấp cho chúng tôi các hộp đựng quá nhỏ để hoàn thành đơn hàng của ông.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Since we have now cleared up the problem, you should receive your items within the next five business days.\", \"vi\": \"Vì chúng tôi đã giải quyết xong vấn đề này, ông sẽ nhận được các mặt hàng của mình trong vòng năm ngày làm việc tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"In addition, I have taken the liberty to attach a brochure of our new products with a detailed price list.\", \"vi\": \"Ngoài ra, tôi xin phép đính kèm một tập tài liệu giới thiệu về các sản phẩm mới của chúng tôi kèm theo bảng giá chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I think you may be interested in some of our latest offerings.\", \"vi\": \"Tôi nghĩ ông có thể quan tâm đến một số sản phẩm mới nhất của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 5, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Juna Schirmer\", \"vi\": \"Juna Schirmer\", \"type\": \"sign_off\", \"doc_index\": 5, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Diedrich Industries\", \"vi\": \"Diedrich Industries\", \"type\": \"sign_off\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '00ead2ee-ca6f-43ef-8e8e-8074fcfaa4ec';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.newstarthome.org/donations\", \"vi\": \"http://www.newstarthome.org/donations\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"New Start Home\", \"vi\": \"New Start Home\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"New Start Home stores accept donations of new or used furniture, appliances, housewares, and building materials.\", \"vi\": \"Các cửa hàng New Start Home nhận quyên góp đồ nội thất mới hoặc đã qua sử dụng, thiết bị gia dụng, đồ dùng nhà bếp và vật liệu xây dựng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Items should be in good condition.\", \"vi\": \"Các mặt hàng phải ở trong tình trạng tốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Items that require repair or are stained or ripped cannot be accepted.\", \"vi\": \"Những mặt hàng cần sửa chữa hoặc bị bẩn hoặc rách sẽ không thể được nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Proceeds from the sale of our goods are used to fund community projects, such as educational programs, housing renovations, and neighborhood park beautification.\", \"vi\": \"Số tiền thu được từ việc bán hàng hóa của chúng tôi được sử dụng để tài trợ cho các dự án cộng đồng, chẳng hạn như các chương trình giáo dục, cải tạo nhà ở và làm đẹp công viên khu 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"How to donate:\", \"vi\": \"Cách thức quyên góp:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Using our home screen, find the New Start Home nearest you by entering your address into the search box.\", \"vi\": \"Sử dụng màn hình chính của chúng tôi, hãy tìm cửa hàng New Start Home gần bạn nhất bằng cách nhập địa chỉ của bạn vào hộp tìm kiếm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Drop off your unneeded goods yourself or contact your nearest location to schedule pickup of large items or bulk donations from your home or business.\", \"vi\": \"Tự mang hàng hóa không cần thiết đến hoặc liên hệ với địa điểm gần nhất của bạn để sắp xếp việc thu gom các mặt hàng lớn hoặc các khoản quyên góp số lượng lớn từ nhà riêng hoặc doanh nghiệp của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please check our Web site for the hours of each store location.\", \"vi\": \"Vui lòng kiểm tra trang Web của chúng tôi để biết giờ mở cửa của từng địa điểm cửa hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"From: bmorris@morriscountryinn.com\", \"vi\": \"Từ: bmorris@morriscountryinn.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: aperez@newstarthome.org\", \"vi\": \"Đến: aperez@newstarthome.org\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Date: March 27\", \"vi\": \"Ngày: 27 tháng 3\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Re: Donation\", \"vi\": \"V/v: Quyên góp\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Dear Mr. Perez,\", \"vi\": \"Kính gửi ông Perez,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I am the owner of the Morris Country Inn in Canton.\", \"vi\": \"Tôi là chủ sở hữu của Morris Country Inn ở Canton.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"It will be closing permanently when I retire next month.\", \"vi\": \"Nó sẽ đóng cửa vĩnh viễn khi tôi nghỉ hưu vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I have many pieces of furniture in excellent condition—beds, desks, easy chairs, and more.\", \"vi\": \"Tôi có nhiều món đồ nội thất ở tình trạng tuyệt vời—giường, bàn làm việc, ghế bành và nhiều thứ khác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"A friend suggested that this inventory could be donated to your organization.\", \"vi\": \"Một người bạn đã gợi ý rằng số hàng tồn kho này có thể được quyên góp cho tổ chức của ông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"The New Start Home branch in Hartford seems to be the closest to my inn, and I see that you are the store manager there.\", \"vi\": \"Chi nhánh New Start Home ở Hartford có vẻ là gần nhất với nhà trọ của tôi, và tôi thấy rằng ông là quản lý cửa hàng ở đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We are located almost 35 miles away.\", \"vi\": \"Chúng tôi nằm cách đó gần 35 dặm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Can I arrange a pickup of these goods at my establishment?\", \"vi\": \"Tôi có thể sắp xếp việc thu gom những hàng hóa này tại cơ sở của tôi không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Brenda Morris\", \"vi\": \"Brenda Morris\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Morris Country Inn\", \"vi\": \"Morris Country Inn\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Morris Country Inn Shutting Its Doors\", \"vi\": \"Morris Country Inn đóng cửa\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"CANTON (April 27)—Brenda Morris watched the New Start Home truck drive away, full of furnishings from the Morris Country Inn.\", \"vi\": \"CANTON (27 tháng 4)—Brenda Morris nhìn chiếc xe tải của New Start Home lái đi, chở đầy đồ nội thất từ Morris Country Inn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"She has been the owner-operator of the inn, a local landmark, for 40 years.\", \"vi\": \"Bà đã là chủ kiêm điều hành của nhà trọ, một địa danh địa phương, trong 40 năm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"\\\"I am happy to be heading to Seaview Point, with its beaches and warm weather,\\\" remarked Ms. Morris.\", \"vi\": \"\\\"Tôi rất vui khi được hướng đến Seaview Point, với những bãi biển và thời tiết ấm áp,\\\" bà Morris nhận xét.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"\\\"And I now plan to spend time volunteering and just relaxing.\", \"vi\": \"\\\"Và bây giờ tôi dự định dành thời gian làm tình nguyện và chỉ để thư giãn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"But the inn has been a big part of my life, and it will be hard leaving this community.\\\"\", \"vi\": \"Nhưng nhà trọ đã là một phần lớn trong cuộc sống của tôi, và sẽ rất khó khăn khi rời bỏ cộng đồng này.\\\"\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"The property that the Morris Country Inn currently stands on has been sold to the Brent Valley Development Group, which plans to convert the building into apartment units over the coming year.\", \"vi\": \"Khu đất mà Morris Country Inn hiện đang tọa lạc đã được bán cho Tập đoàn Phát triển Thung lũng Brent, dự định chuyển đổi tòa nhà thành các căn hộ trong năm tới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}]' WHERE `id` = '00f54007-35a3-4cb6-9481-d88fa25ab8b7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Bradely Jackson <bjackson@cambridgestar.com>\", \"vi\": \"Đến: Bradely Jackson <bjackson@cambridgestar.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: promotions@moonlight-bedding.com\", \"vi\": \"Từ: promotions@moonlight-bedding.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: February 10\", \"vi\": \"Ngày: 10 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Grab a bedding bargain!\", \"vi\": \"Chủ đề: Săn ngay món hời chăn ga gối đệm!\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Customer:\", \"vi\": \"Kính gửi Quý khách hàng:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Don\'t miss Moonlight Bedding\'s Annual Clearance Sale, which starts tomorrow!\", \"vi\": \"Đừng bỏ lỡ Chương trình Siêu giảm giá Thường niên của Moonlight Bedding, sẽ bắt đầu vào ngày mai!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It\'s the perfect time to stock up on sheets, pillowcases, and mattress covers.\", \"vi\": \"Đây là thời điểm hoàn hảo để mua sắm tích trữ ga giường, áo gối và ga bọc nệm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Normally we hold our sale for just one week, but we\'re running it for two weeks this year, from February 11 to 24.\", \"vi\": \"Thông thường chúng tôi chỉ tổ chức giảm giá trong một tuần, nhưng năm nay chúng tôi kéo dài trong hai tuần, từ ngày 11 đến 24 tháng 2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"A wide range of patterns, colors, and fabric types is available.\", \"vi\": \"Có rất nhiều mẫu mã, màu sắc và loại vải khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"And whether you have a small twin bed, a king-sized bed, or anything in between, we\'re sure you\'ll find something you love.\", \"vi\": \"Và cho dù bạn có giường đơn nhỏ, giường cỡ lớn (king-size), hay bất kỳ kích cỡ nào ở giữa, chúng tôi chắc chắn bạn sẽ tìm thấy món đồ mình yêu thích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Anyone who places an order on the first day of the sale will receive a free 50 ml.\", \"vi\": \"Bất kỳ ai đặt hàng vào ngày đầu tiên của đợt giảm giá sẽ nhận được một chai xịt thơm quần áo và gối ngủ hoa oải hương (Lavender Sleep Spray)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"bottle of our new Lavender Sleep Spray, so be sure to shop tomorrow and use code THX05.\", \"vi\": \"dung tích 50 ml miễn phí, vì vậy hãy nhớ mua sắm vào ngày mai và sử dụng mã THX05.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"In addition, customers who spend $50 or more will receive free shipping.\", \"vi\": \"Ngoài ra, khách hàng chi tiêu từ 50 đô la trở lên sẽ được miễn phí vận chuyển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The inventory in our online catalog is available only while supplies last.\", \"vi\": \"Hàng tồn kho trong danh mục trực tuyến của chúng tôi chỉ có sẵn chừng nào hàng vẫn còn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We hope to serve you soon!\", \"vi\": \"Chúng tôi hy vọng được phục vụ bạn sớm!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Billy Elwood\", \"vi\": \"Billy Elwood\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Promotions Team, Moonlight Bedding\", \"vi\": \"Bộ phận Khuyến mãi, Moonlight Bedding\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Please note: This e-mail has been sent to customers who have made frequent purchases in the past year.\", \"vi\": \"Xin lưu ý: Email này đã được gửi đến những khách hàng đã mua hàng thường xuyên trong năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"You can unsubscribe at any time.\", \"vi\": \"Bạn có thể hủy đăng ký bất cứ lúc nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"To: bjackson@cambridgestar.com\", \"vi\": \"Đến: bjackson@cambridgestar.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"From: orders@moonlight-bedding.com\", \"vi\": \"Từ: orders@moonlight-bedding.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Date: February 11\", \"vi\": \"Ngày: 11 tháng 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Subject: Order confirmation\", \"vi\": \"Chủ đề: Xác nhận đơn hàng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Item# - Description - Quantity - Total\", \"vi\": \"Mã SP - Mô tả - Số lượng - Tổng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"3950 - Blue checkered sheet set (queen) - 1 - $15.99\", \"vi\": \"3950 - Bộ ga trải giường kẻ caro xanh dương (cỡ queen) - 1 - $15.99\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"3210 - Blue checkered pillowcase (set of 2) - 1 - $3.75\", \"vi\": \"3210 - Vỏ gối kẻ caro xanh dương (bộ 2 chiếc) - 1 - $3.75\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"9442 - Beige flat sheet (queen) - 2 - $13.98\", \"vi\": \"9442 - Ga trải giường phẳng màu be (cỡ queen) - 2 - $13.98\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"8674 - Blue flat sheet (twin) - 1 - $4.95\", \"vi\": \"8674 - Ga trải giường phẳng màu xanh dương (giường đơn) - 1 - $4.95\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"1041 - Lavender sleep spray (promo: THX05) - 1 - $0.00\", \"vi\": \"1041 - Xịt gối ngủ hoa oải hương (mã ưu đãi: THX05) - 1 - $0.00\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Subtotal: $38.67\", \"vi\": \"Tạm tính: $38.67\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Shipping fee: $5.00\", \"vi\": \"Phí vận chuyển: $5.00\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Total: $43.67\", \"vi\": \"Tổng cộng: $43.67\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Dear Mr. Jackson,\", \"vi\": \"Kính gửi Ông Jackson,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Thank you for participating in Moonlight Bedding\'s Annual Clearance Sale!\", \"vi\": \"Cảm ơn bạn đã tham gia Chương trình Siêu giảm giá Thường niên của Moonlight Bedding!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Your items will be shipped within three business days.\", \"vi\": \"Các mặt hàng của bạn sẽ được vận chuyển trong vòng ba ngày làm việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Please note that the items in this order are subject to a stricter return policy than regular purchases.\", \"vi\": \"Xin lưu ý rằng các mặt hàng trong đơn hàng này tuân theo chính sách đổi trả nghiêm ngặt hơn so với các giao dịch mua thông thường.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Be sure to visit our Web site again soon, as we release new patterns frequently!\", \"vi\": \"Hãy nhớ ghé thăm trang web của chúng tôi sớm nhé, vì chúng tôi thường xuyên ra mắt các mẫu mã mới!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}]' WHERE `id` = '01030241-0f4d-496e-b0eb-28d1bab20f65';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Clearhaven Chamber of Commerce\", \"vi\": \"Phòng Thương mại Clearhaven\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Breakfast Club\", \"vi\": \"Câu lạc bộ Ăn sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Guest Speaker Philippa Dixton of Dixton Advertising\", \"vi\": \"Diễn giả khách mời Philippa Dixton từ Dixton Advertising\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"\\\"Social Media Trends for Business Success\\\"\", \"vi\": \"\\\"Xu hướng Truyền thông Xã hội vì Sự thành công trong Kinh doanh\\\"\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Wednesday, September 26\", \"vi\": \"Thứ Tư, ngày 26 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"7:30–9:00 A.M.\", \"vi\": \"7:30–9:00 Sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Kelly\'s Café\", \"vi\": \"Quán cà phê Kelly\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"17 Richards Street\", \"vi\": \"17 Phố Richards\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Clearhaven, Virginia 20101\", \"vi\": \"Clearhaven, Virginia 20101\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"$8.00 per person\", \"vi\": \"8,00 đô la mỗi người\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Includes full breakfast buffet\", \"vi\": \"Bao gồm tiệc buffet sáng thị soạn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Registration required, limited seating available\", \"vi\": \"Yêu cầu đăng ký, số lượng chỗ ngồi có hạn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"RSVP by September 20\", \"vi\": \"Xác nhận tham dự trước ngày 20 tháng 9\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Clearhaven Chamber of Commerce, 540-555-0112\", \"vi\": \"Phòng Thương mại Clearhaven, số điện thoại 540-555-0112\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '0104dca2-cf99-4a79-8064-5d348a49d527';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Michiko Saunders [8:06 A.M.]\", \"vi\": \"Michiko Saunders [8:06 A.M.]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Jacob. Are you on your way to the office?\", \"vi\": \"Chào Jacob. Bạn đang trên đường đến văn phòng phải không?\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Jacob Kwon [8:08 A.M.]\", \"vi\": \"Jacob Kwon [8:08 A.M.]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Yes.\", \"vi\": \"Đúng vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I should be there in about 25 minutes.\", \"vi\": \"Tôi chắc sẽ có mặt ở đó trong khoảng 25 phút nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Michiko Saunders [8:10 A.M.]\", \"vi\": \"Michiko Saunders [8:10 A.M.]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I was just starting to print out the design proposal for the Dansby Group, but we\'ve run out of paper.\", \"vi\": \"Tôi vừa bắt đầu in bản đề xuất thiết kế cho Tập đoàn Dansby, nhưng chúng ta đã hết giấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"And we don\'t have another delivery of it coming until Wednesday.\", \"vi\": \"Và chúng ta sẽ không có đợt giao giấy tiếp theo cho đến tận thứ Tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Jacob Kwon [8:12 A.M.]\", \"vi\": \"Jacob Kwon [8:12 A.M.]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I see an office supply store across the street.\", \"vi\": \"Tôi thấy một cửa hàng bán đồ dùng văn phòng ở bên kia đường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It just opened for the day.\", \"vi\": \"Nó vừa mở cửa vào sáng nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Michiko Saunders [8:13 A.M.]\", \"vi\": \"Michiko Saunders [8:13 A.M.]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Fantastic.\", \"vi\": \"Tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Three packs of paper should be enough.\", \"vi\": \"Ba tập giấy chắc là đủ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Jacob Kwon [8:15 A.M.]\", \"vi\": \"Jacob Kwon [8:15 A.M.]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"By the way, when will the representatives from the Dansby Group be coming to our office?\", \"vi\": \"Nhân tiện, khi nào các đại diện từ Tập đoàn Dansby sẽ đến văn phòng chúng ta?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I could also pick up some coffee and snacks for that meeting.\", \"vi\": \"Tôi cũng có thể mua sẵn một ít cà phê và đồ ăn nhẹ cho cuộc họp đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '016ce448-7067-4380-8a84-c06402e4521b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Client Name - Project Description - Date Completed - Time\", \"vi\": \"Tên khách hàng - Mô tả dự án - Ngày hoàn thành - Thời gian\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Eddie Kent - University thesis editing - 5 September - 2 hours\", \"vi\": \"Eddie Kent - Chỉnh sửa luận văn đại học - 5 tháng 9 - 2 giờ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Ben Gallagher - Grant proposal editing - 9 September - 10 hours\", \"vi\": \"Ben Gallagher - Chỉnh sửa đề xuất tài trợ - 9 tháng 9 - 10 giờ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Lydia Quinn of Hyden Interiors - Marketing copy editing - 17 September - 8.5 hours\", \"vi\": \"Lydia Quinn thuộc Hyden Interiors - Chỉnh sửa bản thảo tiếp thị - 17 tháng 9 - 8,5 giờ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Winona Rogers - Journal article editing - 22 September - 2 hours\", \"vi\": \"Winona Rogers - Chỉnh sửa bài báo tạp chí - 22 tháng 9 - 2 giờ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Tony Withers - CV and cover letter editing - 28 September - 2.5 hours\", \"vi\": \"Tony Withers - Chỉnh sửa sơ yếu lý lịch và thư xin việc - 28 tháng 9 - 2,5 giờ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Brit-Revision Editing Services Invoice\", \"vi\": \"Hóa đơn dịch vụ chỉnh sửa Brit-Revision\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Freelance Editor: Lisa Yamashita\", \"vi\": \"Biên tập viên tự do: Lisa Yamashita\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Invoice Date: 30 September\", \"vi\": \"Ngày hóa đơn: 30 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Address:\", \"vi\": \"Địa chỉ:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"178 Upsala Road\", \"vi\": \"178 Upsala Road\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"LONDON\", \"vi\": \"LONDON\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"E16 1DJ\", \"vi\": \"E16 1DJ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Contact:\", \"vi\": \"Liên hệ:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"(020) 7946 0612\", \"vi\": \"(020) 7946 0612\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"lisa.yamashita@bluesun.co.uk\", \"vi\": \"lisa.yamashita@bluesun.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Stashcash ID: Lisa.Yamashita8\", \"vi\": \"Mã định danh Stashcash: Lisa.Yamashita8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"To: Lisa Yamashita <lisa.yamashita@bluesun.co.uk>\", \"vi\": \"Đến: Lisa Yamashita <lisa.yamashita@bluesun.co.uk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"From: Claudio Aguilar <caguilar@britrevision.co.uk>\", \"vi\": \"Từ: Claudio Aguilar <caguilar@britrevision.co.uk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Date: 1 October\", \"vi\": \"Ngày: 1 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Subject: Your recent invoice\", \"vi\": \"Chủ đề: Hóa đơn gần đây của bạn\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Dear Lisa,\", \"vi\": \"Lisa thân mến,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Thank you for sending your invoice for services rendered in the month of September.\", \"vi\": \"Cảm ơn bạn đã gửi hóa đơn cho các dịch vụ đã thực hiện trong tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I want to commend you on your superb start as one of our independent freelance editors.\", \"vi\": \"Tôi muốn ca ngợi khởi đầu tuyệt vời của bạn với tư cách là một trong những biên tập viên tự do độc lập của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Our clients had nothing but positive things to say about your work.\", \"vi\": \"Khách hàng của chúng tôi chỉ có những nhận xét tích cực về công việc của bạn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"As you know, we do not dictate how you structure your workday; instead, Brit-Revision (BRV) guidelines require simply that deadlines be met and that work quality be maintained.\", \"vi\": \"Như bạn biết đấy, chúng tôi không áp đặt cách bạn sắp xếp ngày làm việc của mình; thay vào đó, các hướng dẫn của Brit-Revision (BRV) chỉ yêu cầu đáp ứng thời hạn và duy trì chất lượng công việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"You have done both admirably.\", \"vi\": \"Bạn đã làm rất xuất sắc cả hai điều đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Also, we will pay you for an additional 30 minutes of work that you did for Mr. Kent.\", \"vi\": \"Ngoài ra, chúng tôi sẽ trả tiền cho bạn thêm 30 phút làm việc mà bạn đã thực hiện cho ông Kent.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"He reported that you did consulting work for him over the phone on a short oral presentation that he created.\", \"vi\": \"Ông ấy báo cáo rằng bạn đã thực hiện công việc tư vấn cho ông ấy qua điện thoại về một bài thuyết trình miệng ngắn mà ông ấy đã chuẩn bị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"As for the work that you did for our long-standing corporate client Lydia Quinn, you will see on your receipt that we have paid you at a higher hourly rate.\", \"vi\": \"Đối với công việc bạn đã thực hiện cho khách hàng doanh nghiệp lâu năm của chúng tôi là Lydia Quinn, bạn sẽ thấy trên biên nhận của mình rằng chúng tôi đã trả cho bạn mức lương theo giờ cao hơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I have initiated the transfer of £750 into your Stashcash account.\", \"vi\": \"Tôi đã bắt đầu chuyển khoản 750 bảng Anh vào tài khoản Stashcash của bạn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"The funds should appear in your account by tomorrow morning.\", \"vi\": \"Số tiền này sẽ xuất hiện trong tài khoản của bạn vào sáng mai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Claudio Aguilar\", \"vi\": \"Claudio Aguilar\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Accounts Payable, Brit-Revision Editing Services\", \"vi\": \"Phòng Khoản phải trả, Dịch vụ Chỉnh sửa Brit-Revision\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '0178c951-5bc2-4c0c-ac4a-942015f21101';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"WH\", \"vi\": \"WH\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Westerly Hotel\", \"vi\": \"Khách sạn Westerly\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"295 Prudence Ave.\", \"vi\": \"295 Prudence Ave.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Atlanta, GA 30317\", \"vi\": \"Atlanta, GA 30317\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Guest,\", \"vi\": \"Kính gửi Quý khách,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Welcome to Atlanta.\", \"vi\": \"Chào mừng quý khách đến với Atlanta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We are pleased you have chosen the Westerly Hotel.\", \"vi\": \"Chúng tôi rất vui vì quý khách đã chọn Khách sạn Westerly.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"A complimentary breakfast is served daily from 6:00 A.M. to 10:30 A.M. in our dining area located in the lobby.\", \"vi\": \"Bữa sáng miễn phí được phục vụ hàng ngày từ 6:00 sáng đến 10:30 sáng tại khu vực ăn uống của chúng tôi nằm ở tầng sảnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Enjoy an array of selections including eggs, oatmeal, pastries, fresh fruit, cereal, juice, coffee, and tea.\", \"vi\": \"Thưởng thức đa dạng các món ăn bao gồm trứng, cháo yến mạch, bánh ngọt, trái cây tươi, ngũ cốc, nước ép, cà phê và trà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please be aware, however, that on May 2 breakfast will be served in the Fin Restaurant, located on the third floor, to accommodate a private event.\", \"vi\": \"Tuy nhiên, xin lưu ý rằng vào ngày 2 tháng 5, bữa sáng sẽ được phục vụ tại Nhà hàng Fin, nằm ở tầng ba, để phục vụ một sự kiện riêng tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Malcolm Anderson, Manager\", \"vi\": \"Malcolm Anderson, Quản lý\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Westerly Hotel\", \"vi\": \"Khách sạn Westerly\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '018c5cc1-29cf-463c-8c0e-5f1ebd161f75';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: <Customer List>\", \"vi\": \"Đến: <Customer List>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: info@rapidrailways.com\", \"vi\": \"Từ: info@rapidrailways.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: February 1\", \"vi\": \"Ngày: Ngày 1 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: News\", \"vi\": \"Chủ đề: Tin tức\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Rapid Railways would like to reward its loyal customers with a special discount on travel during the month of April.\", \"vi\": \"Rapid Railways muốn tri ân những khách hàng thân thiết của mình bằng một mức giảm giá đặc biệt cho các chuyến đi trong suốt tháng Tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Purchase an adult round-trip ticket over $60 and receive 50 percent off a second adult fare for a companion.\", \"vi\": \"Mua vé khứ hồi dành cho người lớn có giá trị trên 60 đô la và nhận giảm giá 50 phần trăm cho giá vé người lớn thứ hai dành cho người đi kèm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Use code RAIL when booking online.\", \"vi\": \"Sử dụng mã RAIL khi đặt vé trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This promotion is not valid for Rapid Railways Express trains.\", \"vi\": \"Chương trình khuyến mãi này không áp dụng cho các đoàn tàu Rapid Railways Express.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Customers cannot exchange previously purchased tickets to obtain the offer.\", \"vi\": \"Khách hàng không thể đổi vé đã mua trước đó để nhận ưu đãi này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Tickets must be purchased by March 1.\", \"vi\": \"Vé phải được mua trước ngày 1 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '018f931b-d30b-4b5b-99f4-630c8b2f3f45';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"The Bryant Foyer is one of the premier event spaces in our area.\", \"vi\": \"The Bryant Foyer là một trong những không gian tổ chức sự kiện hàng đầu trong khu vực của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Set on a hill, it has expansive windows that provide sweeping views of the adjacent botanical gardens and the river.\", \"vi\": \"Tọa lạc trên một ngọn đồi, nơi đây có các cửa sổ rộng lớn mang đến tầm nhìn bao quát ra khu vườn bách thảo bên cạnh và con sông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Built in 1897, it was the home of the Francona Charitable Trust until its renovation just over a year ago.\", \"vi\": \"Được xây dựng vào năm 1897, nơi đây từng là trụ sở của Quỹ Từ thiện Francona cho đến khi được cải tạo cách đây hơn một năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Today, the space can accommodate up to 200 guests and is ideal for wedding receptions, office parties, and panel presentations.\", \"vi\": \"Ngày nay, không gian này có thể đón tiếp tới 200 khách và rất lý tưởng cho các buổi tiệc cưới, tiệc công ty và các buổi thuyết trình hội panel.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"With its marble floors, cathedral ceiling, and stunning artwork, the Bryant Foyer is the ideal location for your next gathering.\", \"vi\": \"Với sàn lát đá cẩm thạch, trần nhà cao và các tác phẩm nghệ thuật tuyệt đẹp, The Bryant Foyer là địa điểm lý tưởng cho buổi họp mặt tiếp theo của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The on-site restaurant, Andito\'s, caters our events and also operates as its own business.\", \"vi\": \"Nhà hàng trong khuôn viên, Andito\'s, phục vụ ăn uống cho các sự kiện của chúng tôi và đồng thời hoạt động như một doanh nghiệp độc lập.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This farm-to-table restaurant, headed by chef Michaela Rymond, meets all dietary needs and has revolutionized the local food scene.\", \"vi\": \"Nhà hàng phục vụ món ăn từ nông trại đến bàn ăn này, do đầu bếp Michaela Rymond phụ trách, đáp ứng mọi nhu cầu ăn kiêng và đã cách mạng hóa nền ẩm thực địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Area residents know to plan far in advance to get a seat.\", \"vi\": \"Cư dân trong khu vực đều biết phải lên kế hoạch từ trước thật lâu để có được chỗ ngồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"To reserve the event space or to make a dinner reservation, give us a call at 216-555-0157.\", \"vi\": \"Để đặt không gian sự kiện hoặc đặt bàn ăn tối, hãy gọi cho chúng tôi theo số 216-555-0157.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '01df6ee4-6209-45cb-957b-6f830d8efaf8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Avani Mehta (8:57 A.M.)\", \"vi\": \"Avani Mehta (8:57 Sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Ed.\", \"vi\": \"Chào Ed.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I’m on the bus on my way to the warehouse.\", \"vi\": \"Tôi đang ở trên xe buýt trên đường đến nhà kho.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Remember that mobile app I told you about—the one for finding available storage locations?\", \"vi\": \"Bạn có nhớ ứng dụng di động mà tôi đã kể cho bạn nghe không—ứng dụng dùng để tìm các địa điểm lưu trữ trống ấy?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I’m using it now, and I think I’ve found something for us at 10 Maple Street.\", \"vi\": \"Tôi đang sử dụng nó đây, và tôi nghĩ mình đã tìm được một chỗ cho chúng ta ở số 10 đường Maple.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Ed Beiger (8:59 A.M.)\", \"vi\": \"Ed Beiger (8:59 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Great.\", \"vi\": \"Tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Are you sure it’s not just an event space?\", \"vi\": \"Bạn có chắc đó không phải là một không gian tổ chức sự kiện không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Avani Mehta (9:01 A.M.)\", \"vi\": \"Avani Mehta (9:01 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The description says it’s ideal for retailers needing storage space, and it offers temporary rental terms.\", \"vi\": \"Phần mô tả nói rằng nó rất lý tưởng cho các nhà bán lẻ cần không gian lưu trữ, và nó cung cấp các điều khoản cho thuê ngắn hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Ed Beiger (9:02 A.M.)\", \"vi\": \"Ed Beiger (9:02 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"That could work.\", \"vi\": \"Điều đó có vẻ khả thi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Let’s check out the particulars together later today after we complete our inventory work.\", \"vi\": \"Hãy cùng nhau xem xét các chi tiết cụ thể vào chiều nay sau khi chúng ta hoàn thành công việc kiểm kê nhé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Avani Mehta (9:04 A.M.)\", \"vi\": \"Avani Mehta (9:04 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sure.\", \"vi\": \"Chắc chắn rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Our van is already loaded with our overstocked items.\", \"vi\": \"Xe tải của chúng ta đã được chất đầy các mặt hàng tồn kho.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"You could drive it over.\", \"vi\": \"Bạn có thể lái nó đến đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"If the location turns out to be a good fit, we can use the app to book the space and unload the van right there and then.\", \"vi\": \"Nếu địa điểm đó thực sự phù hợp, chúng ta có thể sử dụng ứng dụng để đặt không gian và dỡ hàng hóa trên xe ngay tại chỗ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Ed Beiger (9:05 A.M.)\", \"vi\": \"Ed Beiger (9:05 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"That’s exactly what I was thinking.\", \"vi\": \"Đó chính xác là những gì tôi đang nghĩ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Avani Mehta (9:06 A.M.)\", \"vi\": \"Avani Mehta (9:06 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Wonderful.\", \"vi\": \"Tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"See you soon.\", \"vi\": \"Hẹn gặp lại bạn sớm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '0243b922-3654-41d8-b777-3eae67ec53cb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MEMO\", \"vi\": \"THÔNG BÁO\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Leah Achen, Head of Technology Resources\", \"vi\": \"Từ: Leah Achen, Trưởng phòng Tài nguyên Công nghệ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To: All Employees\", \"vi\": \"Đến: Tất cả nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: June 28\", \"vi\": \"Ngày: 28 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Video-editing software change\", \"vi\": \"Chủ đề: Thay đổi phần mềm chỉnh sửa video\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Effective July 20, employees will no longer have access to the Zipvid app for creating animated videos.\", \"vi\": \"Từ ngày 20 tháng 7, nhân viên sẽ không còn quyền truy cập vào ứng dụng Zipvid để tạo video hoạt hình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We will instead be using Curtain Call, which we trust will prove to be a more reliable program that is less likely to crash.\", \"vi\": \"Thay vào đó, chúng ta sẽ sử dụng Curtain Call, chương trình mà chúng tôi tin tưởng sẽ chứng minh là một phần mềm đáng tin cậy hơn và ít có khả năng bị sự cố hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Employees who need to convert their videos from the format Zipvid uses to a format compatible with Curtain Call should install the converter utility to their work computers.\", \"vi\": \"Nhân viên nào cần chuyển đổi video của họ từ định dạng mà Zipvid sử dụng sang định dạng tương thích với Curtain Call nên cài đặt tiện ích chuyển đổi vào máy tính làm việc của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"This utility can be found in our company\'s online software library.\", \"vi\": \"Tiện ích này có thể được tìm thấy trong thư viện phần mềm trực tuyến của công ty chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"For assistance with this process, please contact Manuel Costa in Technology Support.\", \"vi\": \"Để được hỗ trợ về quy trình này, vui lòng liên hệ với Manuel Costa tại bộ phận Hỗ trợ Công nghệ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '025b7071-8130-4c80-8aa0-b61baefe9b09';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Customer Name: Robert Palomino\", \"vi\": \"Tên khách hàng: Robert Palomino\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Customer Phone: (704) 555-0189\", \"vi\": \"Điện thoại khách hàng: (704) 555-0189\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date of Order: October 26\", \"vi\": \"Ngày đặt hàng: Ngày 26 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date of Delivery: October 28\", \"vi\": \"Ngày giao hàng: Ngày 28 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Delivery: Grand Uptown Hotel\", \"vi\": \"Địa điểm giao: Khách sạn Grand Uptown\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Delivery by: Renu Bhatti\", \"vi\": \"Người giao hàng: Renu Bhatti\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Two kg chocolate cake (round) $75.00\", \"vi\": \"Bánh kem sô-cô-la 2 kg (tròn) $75.00\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Chocolate icing free\", \"vi\": \"Kem phủ sô-cô-la miễn phí\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Strawberry filling $20.00\", \"vi\": \"Nhân dâu tây $20.00\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Message on cake: \\\"Congratulations on your retirement, Mary Ellen!\\\"\", \"vi\": \"Lời nhắn trên bánh: \\\"Chúc mừng bạn đã về hưu, Mary Ellen!\\\"\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"free\", \"vi\": \"miễn phí\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Special instructions: Decorate cake with yellow icing flowers $15.00\", \"vi\": \"Hướng dẫn đặc biệt: Trang trí bánh bằng hoa kem phủ màu vàng $15.00\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Delivery Fee $15.00\", \"vi\": \"Phí giao hàng $15.00\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Grand Total $125.00\", \"vi\": \"Tổng cộng $125.00\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '026bc430-f6b9-460e-82ef-0ba4371148ec';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.dealdirect.co.ke/buyerforum\", \"vi\": \"http://www.dealdirect.co.ke/buyerforum\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Thread>Order not received\", \"vi\": \"Chủ đề>Đơn hàng chưa nhận được\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Posted on 15 May 11:49 AM by Frederick Wambu\", \"vi\": \"Đăng vào ngày 15 tháng 5 lúc 11:49 sáng bởi Frederick Wambu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Two weeks ago I ordered a shipment of books through dealdirect.co.ke.\", \"vi\": \"Hai tuần trước, tôi đã đặt một lô sách thông qua dealdirect.co.ke.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I did not receive the shipment, which was scheduled for 20 April.\", \"vi\": \"Tôi vẫn chưa nhận được lô hàng vốn được lên lịch giao vào ngày 20 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I called the shipping company, and the representative said that she has a record of someone accepting the package, but the signature is not legible.\", \"vi\": \"Tôi đã gọi cho công ty vận chuyển và nhân viên đại diện cho biết họ có ghi nhận việc có người đã nhận bưu kiện, nhưng chữ ký không rõ ràng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I called Deal Direct to make sure that the address they have on file for me is correct, and it was.\", \"vi\": \"Tôi đã gọi cho Deal Direct để đảm bảo rằng địa chỉ họ lưu trữ trong hồ sơ của tôi là chính xác, và đúng là như vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I\'m trying to figure out what my next step should be.\", \"vi\": \"Tôi đang cố gắng tìm hiểu xem bước tiếp theo của mình nên là gì.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I\'m open to your ideas.\", \"vi\": \"Tôi rất cởi mở đón nhận các ý kiến của các bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"So far, I\'ve put up notices in my apartment building, but no one has responded.\", \"vi\": \"Cho đến nay, tôi đã dán thông báo ở tòa nhà chung cư của mình, nhưng không có ai phản hồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I wonder if I should just forget about it and reorder books from a different company or spend more time trying to resolve the matter.\", \"vi\": \"Tôi tự hỏi liệu mình nên quên chuyện này đi và đặt mua lại sách từ một công ty khác hay dành thêm thời gian để cố gắng giải quyết vụ việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '028a9081-a7c8-4d9c-8eab-49f8a30778fd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: skim@jigyeapartments.com\", \"vi\": \"Đến: skim@jigyeapartments.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: larue@waterservices.org\", \"vi\": \"Từ: larue@waterservices.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Water Shut-off\", \"vi\": \"Chủ đề: Cắt nước\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 7 January\", \"vi\": \"Ngày: 7 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Kim,\", \"vi\": \"Kính gửi ông Kim,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Because of a maintenance project, the water to Jigye Apartments will be turned off for several hours next Wednesday, 12 January.\", \"vi\": \"Do dự án bảo trì, nguồn nước cung cấp cho Căn hộ Jigye sẽ bị ngắt trong vài giờ vào thứ Tư tuần tới, ngày 12 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The interruption will begin at 11:00 A.M. Water service will be restored by 5:00 P.M. Please inform all of your building\'s tenants in advance about the interruption, as well as these general guidelines:\", \"vi\": \"Việc ngắt nước sẽ bắt đầu vào lúc 11:00 sáng. Dịch vụ cấp nước sẽ được khôi phục trước 5:00 chiều. Vui lòng thông báo trước cho tất cả người thuê nhà trong tòa nhà của ông về việc ngắt nước này, cũng như các hướng dẫn chung sau đây:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"1.\", \"vi\": \"1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"After the water is turned back on, air in the pipes may cause sudden bursts of water.\", \"vi\": \"Sau khi nước được mở lại, không khí trong đường ống có thể gây ra hiện tượng nước phun đột ngột.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You can fix this problem by running water slowly at first.\", \"vi\": \"Ông có thể khắc phục sự cố này bằng cách xả nước từ từ lúc đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"2.\", \"vi\": \"2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"For any other issues that occur after water service is returned, call our Customer Service desk at the number listed on our Web site for your specific area.\", \"vi\": \"Đối với bất kỳ vấn đề nào khác phát sinh sau khi dịch vụ cấp nước được khôi phục, hãy gọi cho bàn Chăm sóc Khách hàng của chúng tôi theo số điện thoại được liệt kê trên trang web của chúng tôi dành cho khu vực cụ thể của ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"3.\", \"vi\": \"3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Maintenance workers do their best to work quickly and finish as scheduled.\", \"vi\": \"Các nhân viên bảo trì luôn cố gắng hết sức để làm việc nhanh chóng và hoàn thành theo đúng lịch trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"This service interruption is necessary to improve the quality of your water service in the future.\", \"vi\": \"Việc gián đoạn dịch vụ này là cần thiết để cải thiện chất lượng dịch vụ cấp nước của ông trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We apologize for any inconvenience and thank you for your patience.\", \"vi\": \"Chúng tôi thành thật xin lỗi vì bất kỳ sự bất tiện nào và cảm ơn sự kiên nhẫn của ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Pierrick de la Rue\", \"vi\": \"Pierrick de la Rue\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '02e15093-dca3-4044-a644-24d7fff4e3f0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"As my company\'s regional training manager, I am often making presentations to groups of people and rarely in the same place.\", \"vi\": \"Với tư cách là quản lý đào tạo khu vực của công ty, tôi thường xuyên phải thuyết trình trước các nhóm người và hiếm khi ở cùng một địa điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I needed a portable projector to display what\'s on my computer screen, and the Veruvatron 800 is perfect because it is slim and light.\", \"vi\": \"Tôi cần một chiếc máy chiếu di động để hiển thị nội dung trên màn hình máy tính của mình, và Veruvatron 800 là sự lựa chọn hoàn hảo vì nó mỏng và nhẹ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I did quite a bit of research comparing different brands in terms of image resolution and other specifications.\", \"vi\": \"Tôi đã tìm hiểu rất kỹ để so sánh các thương hiệu khác nhau về độ phân giải hình ảnh và các thông số kỹ thuật khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Many were comparable in terms of those specifications, but the Veruvatron 800 is especially easy to bring to all my presentations, and that is ultimately why I chose this one.\", \"vi\": \"Nhiều sản phẩm có chất lượng tương đương về các thông số kỹ thuật đó, nhưng Veruvatron 800 lại cực kỳ dễ mang theo trong mọi buổi thuyết trình của tôi, và đó cuối cùng là lý do tại sao tôi chọn sản phẩm này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"One flaw is that both the power cord and the VGA cord are surprisingly short.\", \"vi\": \"Một điểm hạn chế là cả dây nguồn và cáp VGA đều ngắn một cách đáng ngạc nhiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I have needed to use an extension cord pretty much every time I use it, so be prepared to do the same.\", \"vi\": \"Tôi đã phải dùng dây nối dài hầu như mỗi khi sử dụng, vì vậy hãy chuẩn bị tinh thần để làm điều tương tự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"- Horace Offerman\", \"vi\": \"- Horace Offerman\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '02f000e3-52bb-4593-be56-a1a1e48cc497';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"SEEKING FULL-TIME LINE COOK\", \"vi\": \"TUYỂN ĐẦU BẾP LÀM VIỆC TOÀN THỜI GIAN\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Delphine Street Grill is a high-profile restaurant serving New Orleans since 1924.\", \"vi\": \"Nhà hàng Delphine Street Grill là một nhà hàng nổi tiếng phục vụ thực khách tại New Orleans từ năm 1924.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We are seeking a line cook to prepare select sautéed items and sauces under the supervision of the executive chef.\", \"vi\": \"Chúng tôi đang tìm kiếm một đầu bếp phụ trách chuẩn bị một số món xào và nước sốt được chọn lọc dưới sự giám sát của bếp trưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The ideal candidate will have at least one year of related cooking experience or will have completed a two-year apprenticeship in a well-established restaurant.\", \"vi\": \"Ứng viên lý tưởng sẽ có ít nhất một năm kinh nghiệm nấu ăn liên quan hoặc đã hoàn thành chương trình học nghề hai năm tại một nhà hàng có uy tín lâu năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Demonstrated ability to prepare innovative dishes as well as classic Cajun-style cuisine is required.\", \"vi\": \"Yêu cầu phải có khả năng chuẩn bị các món ăn sáng tạo cũng như ẩm thực phong cách Cajun cổ điển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"To apply, go to www.delphinestreetgrill.com/careers.\", \"vi\": \"Để ứng tuyển, hãy truy cập www.delphinestreetgrill.com/careers.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Employer / Title - Time Employed\", \"vi\": \"Nhà tuyển dụng / Chức vụ - Thời gian làm việc\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"River Ferry Café, Line Cook (Current) - Six months\", \"vi\": \"Quán cà phê River Ferry Café, Đầu bếp (Hiện tại) - Sáu tháng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Hotel Lenoir, Apprentice - Two years\", \"vi\": \"Khách sạn Hotel Lenoir, Người học việc - Hai năm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Picard Seafood, Intern - Three months\", \"vi\": \"Nhà hàng Picard Seafood, Thực tập sinh - Ba tháng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"www.delphinestreetgrill.com/careers/line_cook/apply\", \"vi\": \"www.delphinestreetgrill.com/careers/line_cook/apply\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Name: Anton Hoang\", \"vi\": \"Họ tên: Anton Hoang\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"E-mail: antonh94@textmail.com\", \"vi\": \"E-mail: antonh94@textmail.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Phone: 504.555.0177\", \"vi\": \"Điện thoại: 504.555.0177\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Related education: Associates degree in culinary arts, Boudreau Community College\", \"vi\": \"Học vấn liên quan: Bằng cao đẳng nghệ thuật ẩm thực, Cao đẳng cộng đồng Boudreau\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Résumé: ☑ Attached\", \"vi\": \"Hồ sơ năng lực (Résumé): ☑ Đã đính kèm\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Reference list: ☑ Attached\", \"vi\": \"Danh sách người tham khảo: ☑ Đã đính kèm\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Cover letter:\", \"vi\": \"Thư xin việc:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I am very interested in the position of line cook at the Delphine Street Grill.\", \"vi\": \"Tôi rất quan tâm đến vị trí đầu bếp tại nhà hàng Delphine Street Grill.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"For the past six months, I have been the line cook for a café serving traditional Cajun meals.\", \"vi\": \"Trong sáu tháng qua, tôi là đầu bếp tại một quán cà phê chuyên phục vụ các món ăn truyền thống kiểu Cajun.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Since the café has only recently been opened, I am responsible for preparing nearly all menu items.\", \"vi\": \"Vì quán cà phê chỉ mới khai trương gần đây, tôi chịu trách nhiệm chuẩn bị hầu như tất cả các món trong thực đơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I completed my apprenticeship at the famous Hotel Lenoir, working side-by-side with Celebrity Chef Eugénie Mirone.\", \"vi\": \"Tôi đã hoàn thành chương trình học nghề tại Khách sạn Hotel Lenoir nổi tiếng, làm việc sát cánh cùng Bếp trưởng nổi tiếng Eugénie Mirone.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"In addition, as Ted Overbeck (my mentor and instructor at Boudreau Community College) can confirm, I am able to develop creative new recipes.\", \"vi\": \"Ngoài ra, như ông Ted Overbeck (cố vấn và giảng viên của tôi tại Cao đẳng cộng đồng Boudreau) có thể xác nhận, tôi có khả năng phát triển các công thức nấu ăn mới mang tính sáng tạo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"In fact, while at the college, I was awarded the Excellence in Innovation Prize for a Vietnamese-style sandwich recipe I crafted, which is now on the menu at the college\'s cafeteria.\", \"vi\": \"Thực tế, khi còn ở trường cao đẳng, tôi đã được trao Giải thưởng Xuất sắc trong Đổi mới cho một công thức làm bánh mì kiểu Việt Nam do chính tôi tạo ra, hiện đang có trong thực đơn tại căn tin của trường.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"SUBMIT APPLICATION\", \"vi\": \"GỬI HỒ SƠ ỨNG TUYỂN\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"BOUDREAU COMMUNITY COLLEGE\", \"vi\": \"TRƯỜNG CAO ĐẲNG CỘNG ĐỒNG BOUDREAU\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"School of Culinary Arts\", \"vi\": \"Khoa Nghệ thuật Ẩm thực\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Marie Beaumont\", \"vi\": \"Marie Beaumont\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Delphine Street Grill\", \"vi\": \"Nhà hàng Delphine Street Grill\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"3248 Delphine Street\", \"vi\": \"3248 Phố Delphine\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"New Orleans, LA 70117\", \"vi\": \"New Orleans, LA 70117\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Dear Ms. Beaumont:\", \"vi\": \"Kính gửi bà Beaumont:\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I am writing in regard to Anton Hoang\'s application for employment.\", \"vi\": \"Tôi viết thư này liên quan đến đơn xin việc của Anton Hoang.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Since Mr. Overbeck is on leave this semester, he asked me to respond in his place.\", \"vi\": \"Vì ông Overbeck đang nghỉ phép trong học kỳ này, ông ấy đã nhờ tôi trả lời thay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Mr. Hoang, who graduated in the top five of his class, demonstrated exceptional culinary skill and a strong desire to learn.\", \"vi\": \"Anh Hoang, người đã tốt nghiệp trong top 5 của lớp, đã thể hiện kỹ năng ẩm thực đặc biệt và mong muốn học hỏi mạnh mẽ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"He received a glowing review from Sabine Riou, the renowned chef who supervised his three-month internship.\", \"vi\": \"Anh ấy đã nhận được đánh giá rất tích cực từ Sabine Riou, đầu bếp nổi tiếng đã giám sát thời gian thực tập ba tháng của anh ấy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"I am confident Mr. Hoang will be a valuable asset to your establishment.\", \"vi\": \"Tôi tin chắc anh Hoang sẽ là một tài sản giá trị cho cơ sở kinh doanh của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Liz Flores\", \"vi\": \"Liz Flores\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Associate Director of Culinary Arts\", \"vi\": \"Phó Giám đốc Khoa Nghệ thuật Ẩm thực\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}]' WHERE `id` = '03389fdd-db07-481e-9b40-d8038cb0c865';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Green\'s Athletic Shoes\", \"vi\": \"Giày Thể Thao Green\'s\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"18502 Oriole Avenue\", \"vi\": \"18502 Đại lộ Oriole\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Chicago, IL  60800\", \"vi\": \"Chicago, IL 60800\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"(312) 555-0132\", \"vi\": \"(312) 555-0132\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"August 5, 11:27 A.M.\", \"vi\": \"Ngày 5 tháng 8, 11:27 sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Receipt number: 5926\", \"vi\": \"Số hóa đơn: 5926\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Lunarwave running shoes\", \"vi\": \"Giày chạy bộ Lunarwave\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Style: Fleetfoot, men\'s size 10 - $119.00\", \"vi\": \"Kiểu dáng: Fleetfoot, cỡ nam 10 - $119.00\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Suresocks cotton running socks\", \"vi\": \"Tất chạy bộ bằng cotton Suresocks\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"men\'s size large - $4.99\", \"vi\": \"cỡ lớn dành cho nam - $4.99\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Coolbreeze T-shirt\", \"vi\": \"Áo thun Coolbreeze\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"men\'s size medium\", \"vi\": \"cỡ trung dành cho nam\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Regularly $14.00, now 15% off - $11.90\", \"vi\": \"Giá thông thường $14.00, nay giảm 15% - $11.90\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Subtotal - $135.89\", \"vi\": \"Thành tiền - $135.89\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sales tax (6.25%) - $8.49\", \"vi\": \"Thuế doanh thu (6.25%) - $8.49\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Total - $144.38\", \"vi\": \"Tổng cộng - $144.38\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thank you for shopping at Green\'s Athletic Shoes!\", \"vi\": \"Cảm ơn quý khách đã mua sắm tại Giày Thể Thao Green\'s!\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Please fill out a customer survey at www.greensathletic.com.\", \"vi\": \"Vui lòng điền vào bảng khảo sát khách hàng tại www.greensathletic.com.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"All returns must be made within 30 days.\", \"vi\": \"Tất cả các mặt hàng trả lại phải được thực hiện trong vòng 30 ngày.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"A receipt is required to make a return.\", \"vi\": \"Hóa đơn là bắt buộc để thực hiện việc trả hàng.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '03634443-ce77-41ee-a09b-e98bec39abb2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"We are pleased to announce that the installation of the new manufacturing equipment in our main plant has been completed.\", \"vi\": \"Chúng tôi rất vui mừng thông báo rằng việc lắp đặt thiết bị sản xuất mới tại nhà máy chính của chúng ta đã hoàn tất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The new machines ______[131] work flow by allowing for flexibility in production.\", \"vi\": \"Các máy móc mới ______[131] quy trình làm việc bằng cách cho phép sự linh hoạt trong sản xuất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"With six mixing tanks of ______[132] sizes, we expect to be able to fill a wider range of orders, from small to very large.\", \"vi\": \"Với sáu bồn trộn có các kích cỡ ______[132], chúng tôi kỳ vọng sẽ có thể đáp ứng một loạt các đơn hàng rộng hơn, từ nhỏ đến rất lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132]}, {\"en\": \"This ______[133] is an important way to ensure that Balm Manufacturing continues to be a leader in the fragrance industry.\", \"vi\": \"Điều này ______[133] là một cách quan trọng để đảm bảo rằng công ty Balm Manufacturing tiếp tục giữ vị thế dẫn đầu trong ngành công nghiệp nước hoa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [133]}, {\"en\": \"______[134].\", \"vi\": \"______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [134]}, {\"en\": \"Jim Martel, who is organizing this effort, will contact each of you soon with details.\", \"vi\": \"Jim Martel, người đang tổ chức nỗ lực này, sẽ sớm liên hệ với mỗi quý vị để cung cấp thông tin chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '0372fa2b-e2e5-435d-b703-4a7e33a755f8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Leann Oliver (9:20 A.M.)\", \"vi\": \"Leann Oliver (9:20 Sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Rafael.\", \"vi\": \"Chào Rafael.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Will you be coming to the hiring committee meeting this afternoon?\", \"vi\": \"Bạn sẽ đến dự cuộc họp hội đồng tuyển dụng vào chiều nay chứ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Rafael Sauceda (9:21 A.M.)\", \"vi\": \"Rafael Sauceda (9:21 Sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I wasn\'t planning to.\", \"vi\": \"Tôi không có kế hoạch tham gia.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Do you need me there?\", \"vi\": \"Bạn có cần tôi có mặt ở đó không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Leann Oliver (9:22 A.M.)\", \"vi\": \"Leann Oliver (9:22 Sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We had more candidates apply for the job than we anticipated.\", \"vi\": \"Chúng ta có nhiều ứng viên nộp đơn cho công việc này hơn dự kiến.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We need to decide who to interview, and your expertise would be very helpful.\", \"vi\": \"Chúng ta cần quyết định ai sẽ được phỏng vấn, và chuyên môn của bạn sẽ rất hữu ích.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Rafael Sauceda (9:23 A.M.)\", \"vi\": \"Rafael Sauceda (9:23 Sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I\'ll be happy to help.\", \"vi\": \"Tôi rất vui được giúp đỡ.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It\'s at 4, right?\", \"vi\": \"Cuộc họp diễn ra lúc 4 giờ phải không?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Leann Oliver (9:24 A.M.)\", \"vi\": \"Leann Oliver (9:24 Sáng)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Exactly.\", \"vi\": \"Chính xác.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"In conference room B. I\'ll see you there.\", \"vi\": \"Ở phòng họp B. Hẹn gặp bạn ở đó.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thanks.\", \"vi\": \"Cảm ơn.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '042828a1-7ded-4575-b24e-512fa583a54a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"The Oakville Horticulture Club ___135___ a plant sale on Saturday, 9 September.\", \"vi\": \"Câu lạc bộ Làm vườn Oakville ___135___ một buổi bán cây cảnh vào Thứ Bảy, ngày 9 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [135]}, {\"en\": \"The sale will be held from 9:00 A.M. to 4:00 P.M. at the Oakville Community Centre at 478 Hill Avenue.\", \"vi\": \"Buổi bán hàng sẽ diễn ra từ 9:00 sáng đến 4:00 chiều tại Trung tâm Cộng đồng Oakville số 478 Đại lộ Hill.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"There will be great deals on hanging baskets, grasses, and herbs.\", \"vi\": \"Sẽ có rất nhiều ưu đãi lớn đối với giỏ cây treo, cỏ cảnh và các loại thảo mộc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"___136___ .\", \"vi\": \"___136___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"We ___137___ have a delicious selection of fruits and vegetables available for purchase.\", \"vi\": \"Chúng tôi ___137___ có một sự lựa chọn phong phú các loại trái cây và rau củ tươi ngon để bán.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [137]}, {\"en\": \"Enjoy live talks and demonstrations ___138___ the day.\", \"vi\": \"Thưởng thức các buổi trò chuyện và biểu diễn trực tiếp ___138___ trong ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [138]}, {\"en\": \"For more information, visit the Oakville Horticulture Web site: www.oakvillehorticultureclub.co.uk/events.\", \"vi\": \"Để biết thêm thông tin, hãy truy cập trang web của Hội Làm vườn Oakville: www.oakvillehorticultureclub.co.uk/events.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '0461ab67-5edd-4d83-95d5-63d4d17ab03d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Katsunori Sanu\", \"vi\": \"Katsunori Sanu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"860 Cottonwood Avenue, Apartment 5A\", \"vi\": \"860 Cottonwood Avenue, Apartment 5A\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Walkerton, ON N0G 2V0\", \"vi\": \"Walkerton, ON N0G 2V0\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"January 3\", \"vi\": \"Ngày 3 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Gisel Valdez\", \"vi\": \"Gisel Valdez\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"3758 Fallon Drive\", \"vi\": \"3758 Fallon Drive\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Ottawa, ON K1Z 7B5\", \"vi\": \"Ottawa, ON K1Z 7B5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Dear Ms. Valdez,\", \"vi\": \"Kính gửi Bà Valdez,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Per my lease agreement, this letter constitutes written notice that I will be moving out of my apartment on February 28, the day my lease expires.\", \"vi\": \"Theo hợp đồng thuê nhà của tôi, bức thư này cấu thành thông báo bằng văn bản rằng tôi sẽ chuyển khỏi căn hộ của mình vào ngày 28 tháng 2, ngày hợp đồng thuê của tôi hết hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I have accepted a job offer in Toronto and will be relocating.\", \"vi\": \"Tôi đã nhận được lời mời làm việc tại Toronto và sẽ chuyển đến đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please let me know when I can expect the return of my security deposit.\", \"vi\": \"Vui lòng cho tôi biết khi nào tôi có thể nhận lại tiền đặt cọc bảo đảm của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I have enjoyed my three years living here.\", \"vi\": \"Tôi rất thích ba năm sống ở đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I will gladly recommend the Cottonwood Apartments to anyone looking to rent in the area.\", \"vi\": \"Tôi sẽ sẵn sàng giới thiệu Căn hộ Cottonwood cho bất kỳ ai muốn thuê nhà trong khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"One thing I have really liked is that I have never had to wait long to use a washer or dryer in the laundry room since there are plenty of machines available.\", \"vi\": \"Một điều tôi thực sự thích là tôi chưa bao giờ phải đợi lâu để sử dụng máy giặt hoặc máy sấy trong phòng giặt vì có rất nhiều máy móc sẵn có.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Most impressive, though, is your maintenance service.\", \"vi\": \"Tuy nhiên, ấn tượng nhất là dịch vụ bảo trì của quý công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The crew members quickly addressed all issues, replacing smoke detectors, changing filters in my furnace, and weatherproofing windows before the cold season set in.\", \"vi\": \"Các thành viên trong đội ngũ đã nhanh chóng giải quyết tất cả các vấn đề, thay thế thiết bị báo khói, thay bộ lọc trong lò sưởi của tôi và cách nhiệt cửa sổ trước khi mùa lạnh đến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I will let you know my new address as soon as I have one.\", \"vi\": \"Tôi sẽ cho bạn biết địa chỉ mới của mình ngay khi có.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"You can always reach me on my mobile phone, 613-555-0129.\", \"vi\": \"Bạn luôn có thể liên hệ với tôi qua số điện thoại di động của tôi, 613-555-0129.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Katsunori Sanu\", \"vi\": \"Katsunori Sanu\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}]' WHERE `id` = '046abf5b-0f37-4e26-bee8-1e835e5c7770';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"More Improvements Ahead\", \"vi\": \"Nhiều cải tiến hơn nữa sắp diễn ra\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"At its meeting on Tuesday, the Eldonbury Town Council voted to explore options for additional work to be done on town facilities.\", \"vi\": \"Tại cuộc họp vào thứ Ba, Hội đồng Thị trấn Eldonbury đã bỏ phiếu nghiên cứu các phương án cho công việc bổ sung sẽ được thực hiện tại các cơ sở của thị trấn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"According to Charles Gruber, town clerk, the renovation of the Eldonbury Community Centre came in well under budget.\", \"vi\": \"Theo Charles Gruber, thư ký thị trấn, việc cải tạo Trung tâm Cộng đồng Eldonbury đã hoàn thành với chi phí thấp hơn nhiều so với ngân sách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The council, therefore, decided to compile a list of smaller improvement projects that could be done with the leftover funds.\", \"vi\": \"Do đó, hội đồng đã quyết định lập một danh sách các dự án cải thiện nhỏ hơn có thể được thực hiện bằng số tiền còn lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Some suggested projects include adding a covered entryway to the Eldonbury Public Library, improving lighting in Westfall Park, and replacing floors in the Town Hall.\", \"vi\": \"Một số dự án được đề xuất bao gồm thêm lối vào có mái che cho Thư viện Công cộng Eldonbury, cải thiện hệ thống chiếu sáng tại Công viên Westfall, và thay thế sàn nhà ở Tòa thị chính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"According to Mr. Gruber, the council will solicit ideas from members of the public.\", \"vi\": \"Theo ông Gruber, hội đồng sẽ lấy ý kiến từ các thành viên công chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Interested parties may voice their opinions at the council\'s meeting on Tuesday, 20 March, at 4:00 P.M. or send an e-mail to the council office before 31 March.\", \"vi\": \"Các bên quan tâm có thể bày tỏ ý kiến của mình tại cuộc họp của hội đồng vào thứ Ba, ngày 20 tháng 3, lúc 4:00 chiều hoặc gửi email tới văn phòng hội đồng trước ngày 31 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"After the period of public comment, the planning committee will put forth a final list for the council to discuss, with a decision expected by 15 April.\", \"vi\": \"Sau giai đoạn lấy ý kiến công chúng, ban quy hoạch sẽ đưa ra danh sách cuối cùng để hội đồng thảo luận, với quyết định dự kiến vào ngày 15 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"From: mccaffrey32@citymail.co.uk\", \"vi\": \"Từ: mccaffrey32@citymail.co.uk\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To: towncouncil@eldonbury.org.uk\", \"vi\": \"Đến: towncouncil@eldonbury.org.uk\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Date: 25 March\", \"vi\": \"Ngày: 25 tháng 3\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Subject: Additional Project\", \"vi\": \"Chủ đề: Dự án bổ sung\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Dear Town Council Members,\", \"vi\": \"Kính gửi các Thành viên Hội đồng Thị trấn,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I read that you are accepting suggestions for the use of the leftover money from the Community Centre renovation.\", \"vi\": \"Tôi đọc được rằng quý vị đang tiếp nhận các đề xuất về việc sử dụng số tiền còn lại từ đợt cải tạo Trung tâm Cộng đồng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Because of a previously scheduled appointment, I was not able to attend the council meeting, but I would like to express my support for the idea of expanding the lighting in the park.\", \"vi\": \"Do có lịch hẹn từ trước, tôi không thể tham dự cuộc họp hội đồng, nhưng tôi muốn bày tỏ sự ủng hộ đối với ý tưởng mở rộng hệ thống chiếu sáng trong công viên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"While the cost of that project is likely to be reasonable compared to that of the other possibilities, the improved lighting would increase the usability of Westfall Park and would benefit many people, especially in the dark winter months.\", \"vi\": \"Mặc dù chi phí của dự án đó có khả năng ở mức hợp lý so với các phương án khác, nhưng hệ thống chiếu sáng được cải thiện sẽ làm tăng khả năng sử dụng của Công viên Westfall và mang lại lợi ích cho nhiều người, đặc biệt là trong những tháng mùa đông tối tăm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"A well-lit, nicely maintained park is an obvious source of civic pride, and something we could all appreciate.\", \"vi\": \"Một công viên được chiếu sáng tốt và được bảo trì đẹp mắt là nguồn tự hào chung rõ ràng của người dân, và là điều mà tất cả chúng ta có thể trân trọng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I hope the council will seriously consider this project.\", \"vi\": \"Tôi hy vọng hội đồng sẽ nghiêm túc xem xét dự án này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Heather McCaffrey\", \"vi\": \"Heather McCaffrey\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"From: sunil.pai@hgnetworks.co.uk\", \"vi\": \"Từ: sunil.pai@hgnetworks.co.uk\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"To: towncouncil@eldonbury.org.uk\", \"vi\": \"Đến: towncouncil@eldonbury.org.uk\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Date: 27 March\", \"vi\": \"Ngày: 27 tháng 3\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Subject: Town Projects\", \"vi\": \"Chủ đề: Các dự án của thị trấn\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Dear Mr. Gruber,\", \"vi\": \"Kính gửi ông Gruber,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I was glad to hear that the latest renovation project was completed with money to spare.\", \"vi\": \"Tôi rất vui khi nghe tin dự án cải tạo mới nhất đã hoàn thành mà vẫn còn dư tiền.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Although the Community Centre does sponsor activities for citizens of all ages, it is, for the most part, visited by adolescents and parents with children.\", \"vi\": \"Mặc dù Trung tâm Cộng đồng tài trợ các hoạt động cho công dân ở mọi lứa tuổi, nhưng phần lớn nơi đây được ghé thăm bởi thanh thiếu niên và các bậc phụ huynh có con nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Therefore, I would like to suggest that the next project focus on a place more often used by Eldonbury\'s older people.\", \"vi\": \"Do đó, tôi muốn đề xuất rằng dự án tiếp theo nên tập trung vào một địa điểm được người cao tuổi của Eldonbury sử dụng thường xuyên hơn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"The public library is a natural gathering place for older adults, and a new entryway would provide a dry, protected place for people to chat or wait for transportation.\", \"vi\": \"Thư viện công cộng là một nơi tụ họp tự nhiên cho người lớn tuổi, và lối vào mới sẽ cung cấp một không gian khô ráo, được che chắn để mọi người trò chuyện hoặc chờ phương tiện đi lại.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"It would be a noticeable improvement, likely to be applauded by citizens who did not feel that they gained much from the improvements to the Community Centre.\", \"vi\": \"Đó sẽ là một sự cải thiện đáng chú ý, có khả năng được hoan nghênh bởi những người dân cảm thấy họ không thu được nhiều lợi ích từ việc cải tạo Trung tâm Cộng đồng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"In April, when the votes are cast, please consider this suggestion to balance the interests of all members of the Eldonbury public.\", \"vi\": \"Vào tháng Tư, khi các lá phiếu được bỏ, xin hãy cân nhắc đề xuất này để cân bằng lợi ích của tất cả các thành viên công chúng Eldonbury.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Sunil Pai\", \"vi\": \"Sunil Pai\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '04bebd4d-48c1-4364-8b35-1197af50f7a5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"We\'re Doing Something Right\", \"vi\": \"Chúng Ta Đang Làm Rất Tốt\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"by Ariel Garman\", \"vi\": \"bởi Ariel Garman\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"SUSTERN (November 8)—According to a recent study conducted by the Mid-Atlantic Hotel Association, tourism at our beaches improved significantly this past summer, and the hotel industry showed greater profits this year than last.\", \"vi\": \"SUSTERN (Ngày 8 tháng 11)—Theo một nghiên cứu gần đây được thực hiện bởi Hiệp hội Khách sạn Mid-Atlantic, ngành du lịch tại các bãi biển của chúng ta đã cải thiện đáng kể trong mùa hè vừa qua, và ngành công nghiệp khách sạn cho thấy lợi nhuận cao hơn trong năm nay so với năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Hotel occupancy averaged 94 percent during the peak summer months.\", \"vi\": \"Tỷ lệ phòng khách sạn được lấp đầy đạt trung bình 94 phần trăm trong những tháng cao điểm mùa hè.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Sustern saw the opening of the area\'s largest hotel, The Glaston, last spring.\", \"vi\": \"Sustern chứng kiến sự khai trương của khách sạn lớn nhất khu vực, The Glaston, vào mùa xuân năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The new hotel was at full capacity nearly every weekend during the summer.\", \"vi\": \"Khách sạn mới đã đạt công suất tối đa gần như vào mọi cuối tuần trong suốt mùa hè.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Weekday occupancy also exceeded expectations.\", \"vi\": \"Tỷ lệ lấp đầy phòng vào các ngày trong tuần cũng vượt quá mong đợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The hotel\'s manager, Anika Bastien, said, \\\"Tourists were thrilled with the array of amenities offered, including 24-hour dining options, a free shuttle to nearby beaches, and free Wi-Fi.\", \"vi\": \"Quản lý của khách sạn, Anika Bastien, cho biết, \\\"Khách du lịch vô cùng hào hứng với hàng loạt tiện nghi được cung cấp, bao gồm các lựa chọn ăn uống 24 giờ, xe đưa đón miễn phí đến các bãi biển gần đó và Wi-Fi miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In fact, many have already reserved rooms for next summer.\", \"vi\": \"Trên thực tế, nhiều người đã đặt trước phòng cho mùa hè năm sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [2] —.\\\"\", \"vi\": \"— [2] —.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Sustern has become the most popular tourist destination in the region, with about 20 percent more beachgoers than the Delmire shore, its biggest competitor.\", \"vi\": \"Sustern đã trở thành điểm đến du lịch phổ biến nhất trong khu vực, với lượng người đi biển nhiều hơn khoảng 20 phần trăm so với bờ biển Delmire, đối thủ lớn nhất của nó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Experts attribute this to the growing number of outlet stores in Sustern, overall lower prices, and an abundance of new restaurants, hotels, and community events.\", \"vi\": \"Các chuyên gia quy điều này là do số lượng cửa hàng giảm giá ngày càng tăng ở Sustern, mức giá nhìn chung thấp hơn, và sự phong phú của các nhà hàng, khách sạn và sự kiện cộng đồng mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Tourists continue to visit the area after the prime beach months, keeping hotel rooms occupied longer.\", \"vi\": \"Khách du lịch vẫn tiếp tục đến thăm khu vực này sau những tháng cao điểm đi biển, giúp các phòng khách sạn được lấp đầy lâu hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '04c8f9f6-e3df-4afb-b57b-637ec1dfc5b4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"●  ●  ●\", \"vi\": \"●  ●  ●\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Soraya Channa 8:45 A.M.\", \"vi\": \"Soraya Channa 8:45 Sáng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Hi, Ru.\", \"vi\": \"Chào Ru.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I\'m supposed to greet the new marketing interns at 9:00 and begin the first training session, but my train just left the station.\", \"vi\": \"Tôi phải chào đón các thực tập sinh bộ phận tiếp thị mới lúc 9:00 và bắt đầu buổi đào tạo đầu tiên, nhưng tàu của tôi vừa rời ga.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Ru Liao 8:46 A.M.\", \"vi\": \"Ru Liao 8:46 Sáng\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"What happened?\", \"vi\": \"Có chuyện gì vậy?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Soraya Channa 8:47 A.M.\", \"vi\": \"Soraya Channa 8:47 Sáng\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I think it was a weather-related delay.\", \"vi\": \"Tôi nghĩ đó là sự chậm trễ do thời tiết.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Maybe there was ice on the tracks?\", \"vi\": \"Có thể có băng trên đường ray chăng?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In any event, I\'m not going to be able to make it to the office in time.\", \"vi\": \"Dù thế nào đi nữa, tôi sẽ không thể đến văn phòng kịp giờ.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Ru Liao  8:48 A.M\", \"vi\": \"Ru Liao 8:48 Sáng\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"In that case, I\'ll greet the interns and lead the first session, and you can join us when you arrive.\", \"vi\": \"Trong trường hợp đó, tôi sẽ chào đón các thực tập sinh và dẫn dắt buổi đầu tiên, và bạn có thể tham gia cùng chúng tôi khi bạn đến.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Then you could lead the session on our demographic research in the afternoon.\", \"vi\": \"Sau đó, bạn có thể hướng dẫn buổi học về nghiên cứu nhân khẩu học của chúng ta vào buổi chiều.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Soraya Channa 8:49 A.M.\", \"vi\": \"Soraya Channa 8:49 Sáng\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Yes, that definitely works.\", \"vi\": \"Vâng, cách đó hoàn toàn ổn.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thanks!\", \"vi\": \"Cảm ơn bạn!\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"● ● ● ● ●\", \"vi\": \"● ● ● ● ●\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '04dc8a33-418a-4c0a-b6e0-e71bf518d7ea';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.stylero.com/printers/RD525\", \"vi\": \"http://www.stylero.com/printers/RD525\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Home | Computers | Printers | Ink & Toner | Accessories | Support\", \"vi\": \"Trang chủ | Máy tính | Máy in | Mực & Hộp mực | Phụ kiện | Hỗ trợ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Product: Stylero RD525 Three-in-One Printer\", \"vi\": \"Sản phẩm: Máy in đa chức năng Stylero RD525\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Price: Regularly $120.00 Now $99.99 (Offer valid March 1–March 15)\", \"vi\": \"Giá: Giá gốc $120.00 Nay còn $99.99 (Ưu đãi có hiệu lực từ ngày 1 tháng 3 đến ngày 15 tháng 3)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Includes one complimentary Stylero-01 (black) ink cartridge with purchase!\", \"vi\": \"Bao gồm một hộp mực đen Stylero-01 đi kèm miễn phí khi mua sản phẩm!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Stylero color ink cartridges sold separately.\", \"vi\": \"Hộp mực màu Stylero được bán riêng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The RD525 is one of our most popular models: a wireless color printer, scanner, and photocopier in one.\", \"vi\": \"RD525 là một trong những mẫu máy phổ biến nhất của chúng tôi: máy in màu không dây, máy quét và máy photocopy tích hợp trong một.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It\'s perfect for everyday printing needs in homes, classrooms, and small offices.\", \"vi\": \"Sản phẩm hoàn hảo cho nhu cầu in ấn hàng ngày tại nhà, lớp học và văn phòng nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Though compatible with many brands of ink cartridges, we recommend our own Stylero-brand ink, which lasts up to twice as long as other products.\", \"vi\": \"Mặc dù tương thích với nhiều nhãn hiệu hộp mực khác nhau, chúng tôi khuyên dùng mực mang thương hiệu Stylero của riêng mình, có độ bền lâu gấp đôi so với các sản phẩm khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"A three-year warranty is available for $7.95.\", \"vi\": \"Bảo hành ba năm có sẵn với giá $7.95.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"http://www.loveitornot.com/productreviews/stylero/RD525\", \"vi\": \"http://www.loveitornot.com/productreviews/stylero/RD525\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"(April 3) I bought the Stylero RD525 last month for my home office.\", \"vi\": \"(Ngày 3 tháng 4) Tôi đã mua chiếc máy Stylero RD525 vào tháng trước cho văn phòng tại nhà của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I give digital photography lessons out of my home several nights per week and need easy access to color prints for my students\' work in my classes.\", \"vi\": \"Tôi dạy các lớp nhiếp ảnh kỹ thuật số tại nhà vài đêm mỗi tuần và cần truy cập dễ dàng vào các bản in màu cho bài tập của học viên trong các lớp học của tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I haven\'t had any trouble with the photocopier or scanner, and the quality of the prints is excellent in both color and in black and white.\", \"vi\": \"Tôi chưa gặp bất kỳ sự cố nào với máy photocopy hoặc máy quét, và chất lượng bản in rất xuất sắc ở cả bản in màu lẫn đen trắng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"However, I\'ve been experiencing delays with the printer feature at times.\", \"vi\": \"Tuy nhiên, đôi khi tôi gặp phải tình trạng chậm trễ với tính năng máy in.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"There is a five-minute lag between sending my prints from the computer and when the printing actually begins.\", \"vi\": \"Có khoảng thời gian chờ năm phút giữa việc gửi lệnh in từ máy tính và thời điểm máy bắt đầu in thực tế.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I can\'t use this device for instant prints in class, or I lose valuable class time.\", \"vi\": \"Tôi không thể sử dụng thiết bị này để in ngay lập tức trong lớp, nếu không tôi sẽ mất thời gian quý giá của lớp học.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I wish I\'d bought a different printer, or at least bought the warranty to get it repaired!\", \"vi\": \"Tôi ước gì mình đã mua một chiếc máy in khác, hoặc ít nhất là mua gói bảo hành để sửa chữa nó!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Alicia Boisvert\", \"vi\": \"Alicia Boisvert\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"http://www.loveitornot.com/productreviews/stylero/RD525\", \"vi\": \"http://www.loveitornot.com/productreviews/stylero/RD525\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"(April 5) I bought this printer for my classroom and noticed the same issue that Ms. Boisvert described.\", \"vi\": \"(Ngày 5 tháng 4) Tôi đã mua chiếc máy in này cho lớp học của mình và nhận thấy vấn đề tương tự như cô Boisvert đã mô tả.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"There is a relatively simple fix though.\", \"vi\": \"Tuy nhiên, có một cách khắc phục tương đối đơn giản.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Most printers go into \\\"sleep mode\\\" to conserve energy between prints.\", \"vi\": \"Hầu hết các máy in đều chuyển sang chế độ \\\"ngủ\\\" để tiết kiệm năng lượng giữa các lần in.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"If the length of time before entering sleep mode is set for too short a time, there will be a delay between sending the photos from the computer and the actual printing because the printer will need to warm up each time.\", \"vi\": \"Nếu khoảng thời gian trước khi chuyển sang chế độ ngủ được đặt quá ngắn, sẽ có độ trễ giữa việc gửi ảnh từ máy tính và việc in thực tế vì máy in sẽ cần khởi động lại mỗi lần.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Make sure you adjust the sleep mode feature to wait at least an hour before going to sleep.\", \"vi\": \"Hãy chắc chắn rằng bạn điều chỉnh tính năng chế độ ngủ để đợi ít nhất một giờ trước khi chuyển sang chế độ ngủ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"The instructions are in the manual.\", \"vi\": \"Các hướng dẫn có trong sách hướng dẫn sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I always turn the printer on a few minutes before class and it doesn\'t pose an issue.\", \"vi\": \"Tôi luôn bật máy in trước lớp vài phút và nó không gây ra vấn đề gì cả.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"It\'s an easy adjustment and I think the RD525 is a good product for the price.\", \"vi\": \"Đó là một sự điều chỉnh dễ dàng và tôi nghĩ RD525 là một sản phẩm tốt so với mức giá.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Antonio Thompson\", \"vi\": \"Antonio Thompson\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}]' WHERE `id` = '05146ae6-2f2f-4e4d-a376-2ee1dd77e0f2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Field Trip Coordinator Needed\", \"vi\": \"Cần Tuyển Điều Phối Viên Chuyến Đi Thực Tế\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Somerset Falls Parks Department is looking for an outdoor enthusiast to lead our Environmental Education School Field Trip Program.\", \"vi\": \"Sở Công viên Somerset Falls đang tìm kiếm một người yêu thích hoạt động ngoài trời để dẫn dắt Chương trình Chuyến đi Thực tế Trường học Giáo dục Môi trường của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The job description includes researching and preparing field trip lessons, evaluating each program after facilitation, and assisting in the coordination and scheduling of all field trip groups.\", \"vi\": \"Mô tả công việc bao gồm nghiên cứu và chuẩn bị các bài học cho chuyến đi thực tế, đánh giá từng chương trình sau khi tổ chức, và hỗ trợ điều phối và lên lịch cho tất cả các nhóm tham gia chuyến đi thực tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Qualifications include a degree in biology, environmental science, or a related subject.\", \"vi\": \"Yêu cầu tuyển dụng bao gồm bằng cấp về sinh học, khoa học môi trường, hoặc một môn học có liên quan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Qualified applicants must also have previous experience in managing teams and should be familiar with the parks, nature organizations, and environmental resources in the city.\", \"vi\": \"Các ứng viên đủ điều kiện cũng phải có kinh nghiệm trước đây trong việc quản lý các nhóm và nên quen thuộc với các công viên, tổ chức thiên nhiên, và tài nguyên môi trường trong thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The ability to assist in marketing and outreach is a plus, though not required.\", \"vi\": \"Khả năng hỗ trợ trong công tác tiếp thị và quảng bá là một lợi thế, mặc dù không bắt buộc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To apply, e-mail a cover letter, résumé, and professional references to jobs@somersetfallsparks.com by March 25.\", \"vi\": \"Để ứng tuyển, hãy gửi thư xin việc, sơ yếu lý lịch và các thư giới thiệu chuyên môn qua email tới jobs@somersetfallsparks.com trước ngày 25 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Visit www.somersetfallsparks.com/jobs/FAQs for a list of frequently asked questions about available positions and our hiring process.\", \"vi\": \"Hãy truy cập www.somersetfallsparks.com/jobs/FAQs để xem danh sách các câu hỏi thường gặp về các vị trí tuyển dụng và quy trình tuyển dụng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '05225fd3-42f0-4094-8a47-906565329b9b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Pocheva\", \"vi\": \"Pocheva\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Official partner of the Mahoney Triathlon\", \"vi\": \"Đối tác chính thức của Cuộc thi ba môn phối hợp Mahoney\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Drinking Pocheva nutritional shakes during training helps many Mahoney Triathlon participants build the muscle they need to conquer the slopes of the course\'s infamous peaks.\", \"vi\": \"Việc uống thức uống dinh dưỡng dạng lắc Pocheva trong quá trình tập luyện giúp nhiều vận động viên tham gia Cuộc thi ba môn phối hợp Mahoney xây dựng cơ bắp cần thiết để chinh phục các sườn dốc của những ngọn núi nổi tiếng trong đường đua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Each 60-gram serving of the shake powder contains an incredible 25 grams of protein, along with more than 85 nutrients.\", \"vi\": \"Mỗi khẩu phần 60 gram bột lắc chứa lượng protein đáng kinh ngạc là 25 gram, cùng với hơn 85 chất dinh dưỡng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Once blended with ice and water, it makes a delicious, energizing treat.\", \"vi\": \"Khi được xay nhuyễn với đá và nước, nó tạo ra một món ăn nhẹ thơm ngon, đầy năng lượng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Stop by our booth at the triathlon expo in Mahoney Square for a free sample while supplies last, or visit www.gopocheva.com to learn more.\", \"vi\": \"Hãy ghé thăm gian hàng của chúng tôi tại triển lãm ba môn phối hợp ở Quảng trường Mahoney để nhận mẫu thử miễn phí khi quà tặng vẫn còn, hoặc truy cập www.gopocheva.com để tìm hiểu thêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"POCHEVA\", \"vi\": \"POCHEVA\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '05698bec-e7d2-4c02-bd65-3536e90f7e26';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Frieda Jung (9:16 A.M.) I have to be out of the office starting on Wednesday until next Monday.\", \"vi\": \"Frieda Jung (9:16 A.M.) Tôi phải vắng mặt ở văn phòng bắt đầu từ thứ Tư cho đến thứ Hai tuần sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I need to present a funding request at the regional legislature office.\", \"vi\": \"Tôi cần trình bày một yêu cầu cấp vốn tại văn phòng cơ quan lập pháp khu vực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Would you both feel comfortable giving the presentation about the new Riverwalk to the urban development committee on Friday?\", \"vi\": \"Cả hai bạn có thấy thoải mái khi thuyết trình về dự án Riverwalk mới trước ủy ban phát triển đô thị vào thứ Sáu không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Cassie Alswith (9:18 A.M.) I think we could handle that.\", \"vi\": \"Cassie Alswith (9:18 A.M.) Tôi nghĩ chúng ta có thể đảm nhận việc đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Right, Austin?\", \"vi\": \"Phải không, Austin?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Austin Everett (9:20 A.M.) Definitely.\", \"vi\": \"Austin Everett (9:20 A.M.) Chắc chắn rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I\'m not sure how available you will be, Ms. Jung, but we could send you an overview of the presentation on Thursday if you\'d like.\", \"vi\": \"Tôi không chắc cô sẽ rảnh rỗi như thế nào, cô Jung, nhưng chúng tôi có thể gửi cho cô bản tổng quan về bài thuyết trình vào thứ Tư nếu cô muốn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Frieda Jung (9:22 A.M.) I don\'t think that\'s necessary.\", \"vi\": \"Frieda Jung (9:22 A.M.) Tôi không nghĩ điều đó là cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please be sure to highlight the revenue that we think will be brought into the region by the new businesses, as well as the positive environmental impacts our research group noted.\", \"vi\": \"Hãy nhớ nêu bật doanh thu mà chúng ta cho rằng sẽ mang lại cho khu vực nhờ các doanh nghiệp mới, cũng như các tác động tích cực đến môi trường mà nhóm nghiên cứu của chúng ta đã ghi nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Austin Everett (9:23 A.M.) Got it.\", \"vi\": \"Austin Everett (9:23 A.M.) Tôi hiểu rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We will make sure to do that.\", \"vi\": \"Chúng tôi sẽ chắc chắn làm điều đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Cassie Alswith (9:25 A.M.) Would it be okay if I submit the weekly progress report on Monday instead of Friday?\", \"vi\": \"Cassie Alswith (9:25 A.M.) Liệu có ổn không nếu tôi nộp báo cáo tiến độ hàng tuần vào thứ Hai thay vì thứ Sáu?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"That way I\'ll have a little more time to prepare for the presentation.\", \"vi\": \"Bằng cách đó, tôi sẽ có thêm chút thời gian để chuẩn bị cho bài thuyết trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Frieda Jung (9:26 A.M.) Yes, that\'s a good idea.\", \"vi\": \"Frieda Jung (9:26 A.M.) Vâng, đó là một ý hay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Cassie Alswith (9:26 A.M.) Great.\", \"vi\": \"Cassie Alswith (9:26 A.M.) Tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thank you!\", \"vi\": \"Cảm ơn bạn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Frieda Jung (9:27 A.M.) I might not respond to e-mail as frequently while I\'m gone, but feel free to call me or text me if there\'s anything urgent that comes up.\", \"vi\": \"Frieda Jung (9:27 A.M.) Tôi có thể không trả lời email thường xuyên trong thời gian tôi vắng mặt, nhưng cứ gọi điện hoặc nhắn tin cho tôi nếu có bất kỳ việc khẩn cấp nào phát sinh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '057bc389-566e-46d9-849a-4a83480f9593';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Vimalo Brands Enters a New Era\", \"vi\": \"Vimalo Brands Bước Vào Kỷ Nguyên Mới\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"By Yvette Maurer\", \"vi\": \"Bởi Yvette Maurer\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"VANCOUVER (2 August)—Vimalo Brands, the large consumer goods company that markets popular nutritional-support and personal-care products, including Powerburst breakfast drinks and Honeysoft soaps and lotions, will soon offer something new for its customers: frozen foods.\", \"vi\": \"VANCOUVER (Ngày 2 tháng 8)—Vimalo Brands, công ty hàng tiêu dùng lớn chuyên tiếp thị các sản phẩm hỗ trợ dinh dưỡng và chăm sóc cá nhân nổi tiếng, bao gồm đồ uống buổi sáng Powerburst và xà phòng lẫn sữa dưỡng thể Honeysoft, sẽ sớm cung cấp một sản phẩm mới cho khách hàng của mình: thực phẩm đông lạnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"“Our new Nutridinna line is not just about convenience,” CEO Danitza Martens said during a press conference earlier today.\", \"vi\": \"Giám đốc điều hành Danitza Martens cho biết trong một cuộc họp báo diễn ra hồi đầu ngày hôm nay: “Dòng sản phẩm Nutridinna mới của chúng tôi không chỉ mang lại sự tiện lợi”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"“Frozen foods are not a new concept, but our method of flash-freezing fresh produce and meats ensures that our products retain their texture and flavour as well as their healthy vitamins and minerals.\", \"vi\": \"“Thực phẩm đông lạnh không phải là một khái niệm mới, nhưng phương pháp cấp đông nhanh nông sản và thịt tươi sống của chúng tôi đảm bảo rằng sản phẩm của mình vẫn giữ được kết cấu và hương vị cũng như các loại vitamin và khoáng chất có lợi cho sức khỏe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Now our customers can enjoy the convenience of frozen food without sacrificing quality.”\", \"vi\": \"Giờ đây, khách hàng của chúng tôi có thể tận hưởng sự tiện lợi của thực phẩm đông lạnh mà không phải hy sinh chất lượng.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Vimalo Brands has partnered with Vancouver-area farms to obtain produce and meat for the Nutridinna line.\", \"vi\": \"Vimalo Brands đã hợp tác với các trang trại trong khu vực Vancouver để thu mua nông sản và thịt cho dòng sản phẩm Nutridinna.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"“By keeping our operations local, we avoid shipping delays and can flash-freeze freshly harvested vegetables at their peak of ripeness,” Martens said.\", \"vi\": \"Martens cho biết: “Bằng cách duy trì hoạt động tại địa phương, chúng tôi tránh được tình trạng chậm trễ trong vận chuyển và có thể cấp đông nhanh các loại rau củ vừa được thu hoạch vào độ chín rộ nhất”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"“Our customers benefit further, since our products can be kept in the freezer for up to six months.”\", \"vi\": \"“Khách hàng của chúng tôi còn nhận được thêm lợi ích, vì sản phẩm của chúng tôi có thể được bảo quản trong tủ đông lên đến sáu tháng.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Nutridinna foods will be available in supermarkets beginning in November.\", \"vi\": \"Thực phẩm Nutridinna sẽ có mặt tại các siêu thị bắt đầu từ tháng Mười Một.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Frozen fish and other seafood will be added early next year.\", \"vi\": \"Cá đông lạnh và các loại hải sản khác sẽ được bổ sung vào đầu năm tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '05b0bab3-b74b-4bae-874a-ff86cc08c172';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Tolley Praises Local Farms\", \"vi\": \"Tolley Ca ngợi Các Trang Trại Địa Phương\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"MANCHESTER (June 2)—Local horticulture expert Cassandra Tolley is scheduled to deliver a lecture Friday night at the Burton Auditorium in Manchester.\", \"vi\": \"MANCHESTER (Ngày 2 tháng 6)—Chuyên gia làm vườn địa phương Cassandra Tolley dự kiến sẽ có bài phát biểu vào tối thứ Sáu tại Hội trường Burton ở Manchester.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The owner of Green Ridge Farm in nearby Windham County, Ms. Tolley will discuss the importance of supporting and promoting local farmers.\", \"vi\": \"Là chủ sở hữu của Trang trại Green Ridge tại hạt Windham gần đó, bà Tolley sẽ thảo luận về tầm quan trọng của việc hỗ trợ và quảng bá cho nông dân địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"A strong advocate for small-scale farmers and a small-scale farmer herself, Ms. Tolley has traveled extensively over the past few years to deliver her message of \\\"eating locally.\\\"\", \"vi\": \"Là một người ủng hộ mạnh mẽ cho nông dân quy mô nhỏ và bản thân cũng là một nông dân quy mô nhỏ, bà Tolley đã đi lại rất nhiều trong vài năm qua để truyền tải thông điệp \\\"ăn thực phẩm địa phương.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"If we make an effort to source our ingredients locally, we not only sustain and assist the local economy, we also encourage variety in the marketplace,\\\" says Ms. Tolley.\", \"vi\": \"Bà Tolley cho biết: \\\"Nếu chúng ta nỗ lực tìm nguồn cung ứng nguyên liệu tại địa phương, chúng ta không chỉ duy trì và hỗ trợ nền kinh tế địa phương mà còn khuyến khích sự đa dạng trên thị trường.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"\\\"And that is beneficial to consumers.\\\"\", \"vi\": \"\\\"Và điều đó có lợi cho người tiêu dùng.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"\\\"Everyone should spend their weekends browsing the regional farmers\' markets,\\\" she adds.\", \"vi\": \"Bà cho biết thêm: \\\"Mọi người nên dành các ngày cuối tuần để ghé thăm các chợ nông sản khu vực.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"\\\"It\'s the best place to get your groceries during the summer.\\\"\", \"vi\": \"\\\"Đó là nơi tốt nhất để mua thực phẩm vào mùa hè.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Friday night\'s lecture begins at 7 P.M. It is free, but seating is limited.\", \"vi\": \"Bài phát biểu tối thứ Sáu bắt đầu lúc 7 giờ tối. Buổi nói chuyện hoàn toàn miễn phí, nhưng số lượng chỗ ngồi có hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please arrive early.\", \"vi\": \"Vui lòng đến sớm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To view a comprehensive listing of statewide summer farmers\' markets, visit www.vermontfarmersmarkets.org.\", \"vi\": \"Để xem danh sách toàn diện các chợ nông sản mùa hè trên toàn tiểu bang, hãy truy cập www.vermontfarmersmarkets.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: Cook Today Writing Staff\", \"vi\": \"Đến: Nhân viên Viết bài Cook Today\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From: Zack Hernandez, Editor-in-Chief\", \"vi\": \"Từ: Zack Hernandez, Tổng Biên tập\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Re: Cassandra Tolley talk\", \"vi\": \"V/v: Buổi nói chuyện của Cassandra Tolley\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date: June 8\", \"vi\": \"Ngày: 8 tháng 6\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To all staff,\", \"vi\": \"Gửi tất cả nhân viên,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Cassandra Tolley is giving a talk on Friday.\", \"vi\": \"Cassandra Tolley sẽ có một bài phát biểu vào thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Please let me know if you can go.\", \"vi\": \"Vui lòng cho tôi biết nếu bạn có thể tham gia.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I\'m confident she\'ll provide some good material for an article on local growers.\", \"vi\": \"Tôi tin chắc rằng cô ấy sẽ cung cấp một số tài liệu hay cho bài viết về những người trồng trọt địa phương.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I had a chance to hear her speak last year at Green Ridge Farm.\", \"vi\": \"Tôi đã có cơ hội nghe cô ấy phát biểu vào năm ngoái tại Trang trại Green Ridge.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I found her not only brilliant but funny as well.\", \"vi\": \"Tôi thấy cô ấy không chỉ xuất sắc mà còn rất hài hước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Zack\", \"vi\": \"Zack\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Features Outline for the August Issue of Cook Today Magazine\", \"vi\": \"Đề cương Chuyên mục cho Số tháng 8 của Tạp chí Cook Today\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Feature Title - Topic - Writer\", \"vi\": \"Tiêu đề Chuyên mục - Chủ đề - Tác giả\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Local Made Good - Sourcing and showcasing local producers and ingredients - Ira Newton\", \"vi\": \"Sản phẩm Địa phương Chất lượng - Tìm nguồn cung ứng và giới thiệu các nhà sản xuất và nguyên liệu địa phương - Ira Newton\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Herbs All Year - Growing and maintaining an indoor kitchen herb garden - Makalah Young\", \"vi\": \"Thảo mộc Quanh năm - Trồng và duy trì vườn thảo mộc trong nhà - Makalah Young\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Vegan Delicious - Modern, nutritious, organic vegan recipes - Keyon Davis\", \"vi\": \"Món Thuần Chay Ngon - Các công thức món thuần chay hiện đại, bổ dưỡng, hữu cơ - Keyon Davis\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Amazing August - A calendar of events in August - Jae-eun Park\", \"vi\": \"Tháng 8 Tuyệt vời - Lịch các sự kiện trong tháng 8 - Jae-eun Park\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '05b26859-e389-433e-ad72-874f34744e60';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Carmen Sanchez <c.sanchez@flutteringwings.com.mx>\", \"vi\": \"Đến: Carmen Sanchez <c.sanchez@flutteringwings.com.mx>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: James Norville <jnorville@itiaworld.org>\", \"vi\": \"Từ: James Norville <jnorville@itiaworld.org>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: June 12\", \"vi\": \"Ngày: 12 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: International Travel Industry Association Guardian Award\", \"vi\": \"Chủ đề: Giải thưởng Guardian của Hiệp hội Công nghiệp Du lịch Quốc tế\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Fluttering Wings Resort - INVOICE\", \"vi\": \"Khu nghỉ dưỡng Fluttering Wings - HÓA ĐƠN\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Fluttering Wings Resort\", \"vi\": \"Khu nghỉ dưỡng Fluttering Wings\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"https://www.flutteringwings.com.mx\", \"vi\": \"https://www.flutteringwings.com.mx\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Located just minutes from the entrance to the Tall Trees Monarch Butterfly Sanctuary, Fluttering Wings Resort is Mexico\'s finest eco-friendly destination.\", \"vi\": \"Nằm cách lối vào Khu bảo tồn Bướm Vua Tall Trees chỉ vài phút, Khu nghỉ dưỡng Fluttering Wings là điểm đến thân thiện với môi trường tuyệt vời nhất của Mexico.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Open year-round, our facilities include a full-service restaurant, a relaxing swimming pool, and a rooftop deck with an amazing view.\", \"vi\": \"Mở cửa quanh năm, các tiện ích của chúng tôi bao gồm một nhà hàng đầy đủ dịch vụ, một hồ bơi thư giãn và một sân hiên trên mái nhà với tầm nhìn tuyệt đẹp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Butterfly season is from mid-November to early March, and millions of monarch butterflies pass the winter at the Tall Trees sanctuary.\", \"vi\": \"Mùa bướm kéo dài từ giữa tháng 11 đến đầu tháng 3, và hàng triệu con bướm chúa trải qua mùa đông tại khu bảo tồn Tall Trees.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Visitors can hike up the mountain on foot, but most prefer to participate in our guided horseback tours.\", \"vi\": \"Du khách có thể leo núi đi bộ, nhưng hầu hết đều thích tham gia các chuyến tham quan cưỡi ngựa có hướng dẫn viên của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Our expert guides, who escort visitors up the mountain, are all local villagers.\", \"vi\": \"Các hướng dẫn viên chuyên nghiệp của chúng tôi, những người đồng hành cùng du khách lên núi, đều là những người dân làng địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"They continuously scout the sanctuary for the best viewing locations.\", \"vi\": \"Họ liên tục thám sát khu bảo tồn để tìm ra những địa điểm ngắm cảnh đẹp nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"At all times of the year, we offer hiking trails, bird-watching, and horseback riding.\", \"vi\": \"Vào mọi thời điểm trong năm, chúng tôi cung cấp các tuyến đường đi bộ đường dài, ngắm chim và cưỡi ngựa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Electric vehicle tours of the villages and farms outside the sanctuary are also available.\", \"vi\": \"Các tour tham quan bằng xe điện đến các ngôi làng và trang trại bên ngoài khu bảo tồn cũng có sẵn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Congratulations, Carmen Sanchez!\", \"vi\": \"Xin chúc mừng, Carmen Sanchez!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Fluttering Wings Resort has been named a recipient of an International Travel Industry Association Guardian Award.\", \"vi\": \"Khu nghỉ dưỡng Fluttering Wings đã được xướng tên là một trong những đơn vị nhận Giải thưởng Guardian của Hiệp hội Công nghiệp Du lịch Quốc tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The ITIA Guardian Award includes a $5,000 cash award and one year of free support from our advisory team.\", \"vi\": \"Giải thưởng Guardian của ITIA bao gồm tiền thưởng 5.000 đô la và một năm hỗ trợ miễn phí từ đội ngũ cố vấn của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"ITIA experts can advise Fluttering Wings on ways to operate your business more efficiently and to use the Web to promote your services to potential visitors.\", \"vi\": \"Các chuyên gia của ITIA có thể tư vấn cho Fluttering Wings về các cách vận hành doanh nghiệp hiệu quả hơn và sử dụng Web để quảng bá dịch vụ của bạn đến các du khách tiềm năng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"A member of our advisory team, Rosa Del Vio, would like to present the award to you and visit your resort in July or August.\", \"vi\": \"Một thành viên trong đội ngũ cố vấn của chúng tôi, Rosa Del Vio, muốn trao giải thưởng cho bạn và đến thăm khu nghỉ dưỡng của bạn vào tháng 7 hoặc tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"She will be in touch with you before the end of the month.\", \"vi\": \"Cô ấy sẽ liên lạc với bạn trước cuối tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"James Norville\", \"vi\": \"James Norville\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Executive Director, International Travel Industry Association\", \"vi\": \"Giám đốc Điều hành, Hiệp hội Công nghiệp Du lịch Quốc tế\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"About UsReservationsFAQContact Us\", \"vi\": \"Về chúng tôi Đặt phòng Câu hỏi thường gặp Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"King-size room: two nights at $95/night - $190.00\", \"vi\": \"Phòng cỡ lớn: hai đêm với giá 95$/đêm - 190,00$\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Guided butterfly sanctuary tour: $40 x 2 - $80.00\", \"vi\": \"Tour tham quan khu bảo tồn bướm có hướng dẫn viên: 40$ x 2 - 80,00$\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Total - $270.00\", \"vi\": \"Tổng cộng - 270,00$\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Name: Julio and Lisa Bardom\", \"vi\": \"Họ tên: Julio và Lisa Bardom\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Prepayment received on: February 1\", \"vi\": \"Khoản trả trước nhận được vào: Ngày 1 tháng 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Dates of stay: February 25–27\", \"vi\": \"Ngày lưu trú: Ngày 25–27 tháng 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Amount Paid: $270.00\", \"vi\": \"Số tiền đã thanh toán: 270,00$\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Balance Due: $0.00\", \"vi\": \"Số dư còn lại: 0,00$\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Note: Regarding your question, don\'t worry—the butterflies don\'t depart the reserve until early March.\", \"vi\": \"Lưu ý: Về câu hỏi của bạn, đừng lo lắng—bọn bướm không rời khỏi khu bảo tồn cho đến đầu tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '05d93182-1fef-45e6-ae82-a1dbd0060ac5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Samuel Archerson <sarcherson@vona.co.uk>\", \"vi\": \"Đến: Samuel Archerson <sarcherson@vona.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: James Darrers <jdarrers@sky.co.uk>\", \"vi\": \"Từ: James Darrers <jdarrers@sky.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 10 January\", \"vi\": \"Ngày: 10 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Cost Accountant position\", \"vi\": \"Chủ đề: Vị trí Kế toán chi phí\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Archerson,\", \"vi\": \"Ông Archerson kính mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for taking the time to meet with me today.\", \"vi\": \"Cảm ơn ông đã dành thời gian gặp mặt tôi ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I ______[135] our conversation, and I remain very interested in the position of cost accountant.\", \"vi\": \"Tôi ______[135] cuộc trò chuyện của chúng ta, và tôi vẫn rất quan tâm đến vị trí kế toán chi phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [135]}, {\"en\": \"I would welcome the opportunity to return for the third and final round of ______[136].\", \"vi\": \"Tôi rất hoan nghênh cơ hội được quay lại tham gia vòng phỏng vấn thứ ba và cũng là vòng cuối cùng ______[136].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [136]}, {\"en\": \"I am confident my years of accounting experience would benefit your firm.\", \"vi\": \"Tôi tự tin rằng nhiều năm kinh nghiệm kế toán của mình sẽ mang lại lợi ích cho công ty ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"As discussed, over the last ten years, I have helped many companies save a ______[137] amount of money.\", \"vi\": \"Như đã thảo luận, trong mười năm qua, tôi đã giúp nhiều công ty tiết kiệm được một khoản tiền ______[137].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [137]}, {\"en\": \"I am especially adept at analysing the day-to-day operations of a business and helping to determine more cost-effective methods.\", \"vi\": \"Tôi đặc biệt có thế mạnh trong việc phân tích các hoạt động hàng ngày của doanh nghiệp và giúp xác định các phương pháp hiệu quả về mặt chi phí hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I checked regarding your question about a potential start date.\", \"vi\": \"Tôi đã kiểm tra về câu hỏi của ông liên quan đến ngày bắt đầu làm việc có thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"______[138].\", \"vi\": \"______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [138]}, {\"en\": \"I hope to hear from you in the near future.\", \"vi\": \"Tôi rất mong sớm nhận được phản hồi từ ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"James Darrers\", \"vi\": \"James Darrers\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '0633c813-daaa-4ccd-a49c-bb219d29ade4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From - Chae-Won Yoo\", \"vi\": \"Từ - Chae-Won Yoo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To - Karen Adkins\", \"vi\": \"Đến - Karen Adkins\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject - News\", \"vi\": \"Chủ đề - Tin tức\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date - November 28\", \"vi\": \"Ngày - 28 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment - 📎 Lee\", \"vi\": \"Đính kèm - 📎 Lee\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Adkins,\", \"vi\": \"Kính gửi bà Adkins,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I have found someone who is a promising match for your company\'s Business Development Representative opening.\", \"vi\": \"Tôi đã tìm được một ứng viên có triển vọng phù hợp cho vị trí Đại diện Phát triển Kinh doanh đang tuyển dụng của công ty bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"His name is Conrad Lee, and he has been working in sales for Dawson Health for the past three years.\", \"vi\": \"Anh ấy tên là Conrad Lee, và anh ấy đã làm việc trong lĩnh vực kinh doanh cho công ty Dawson Health trong ba năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As with your opening at Azora Science, this is Seoul-based work that involves selling American products to Korean companies, and Conrad has been successful at it.\", \"vi\": \"Giống như vị trí tuyển dụng của bà tại Azora Science, đây là công việc tại Seoul liên quan đến việc bán các sản phẩm của Mỹ cho các công ty Hàn Quốc, và Conrad đã đạt được thành công trong công việc này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"He was promoted from associate to junior manager last year.\", \"vi\": \"Anh ấy đã được thăng chức từ nhân viên lên trợ lý quản lý vào năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I also confirmed myself in a phone call that he speaks both English and Korean with native-level fluency.\", \"vi\": \"Tôi cũng đã tự xác nhận qua một cuộc điện thoại rằng anh ấy nói thành thạo cả tiếng Anh và tiếng Hàn như người bản xứ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Conrad has a bachelor\'s degree in biology and is scheduled to earn his MBA degree from Larson University\'s online program in December.\", \"vi\": \"Conrad có bằng cử nhân ngành sinh học và dự kiến sẽ nhận bằng Thạc sĩ Quản trị Kinh doanh (MBA) từ chương trình trực tuyến của Đại học Larson vào tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"He even has the passion for science education you are looking for, as he volunteers at a local science museum on the weekends.\", \"vi\": \"Anh ấy thậm chí còn có niềm đam mê với giáo dục khoa học mà bà đang tìm kiếm, vì anh ấy làm tình nguyện viên tại một bảo tàng khoa học địa phương vào các ngày cuối tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Conrad\'s résumé is attached to this e-mail.\", \"vi\": \"Hồ sơ xin việc (résumé) của Conrad được đính kèm trong email này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Please respond to this e-mail if you would like me to connect you with him.\", \"vi\": \"Vui lòng phản hồi email này nếu bà muốn tôi kết nối bà với anh ấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Chae-Won Yoo\", \"vi\": \"Chae-Won Yoo\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Hermann Korea, Inc.\", \"vi\": \"Hermann Korea, Inc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '063ae41c-fd75-4792-ab07-462cc2a74097';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Jessica Marpone <jmarpone@halecityca.gov>\", \"vi\": \"Đến: Jessica Marpone <jmarpone@halecityca.gov>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Greg Tanner <gtanner@halecitynews.com>\", \"vi\": \"Từ: Greg Tanner <gtanner@halecitynews.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: July 1\", \"vi\": \"Ngày: 1 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Community comments\", \"vi\": \"Chủ đề: Ý kiến đóng góp của cộng đồng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Marpone,\", \"vi\": \"Kính gửi bà Marpone,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"My last article about East Core Park attracted quite a few online comments.\", \"vi\": \"Bài viết gần đây của tôi về Công viên East Core đã thu hút khá nhiều bình luận trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The comments were from residents complaining about overgrown weeds and fallen branches on the Blue Trail.\", \"vi\": \"Các bình luận đến từ cư dân phàn nàn về cỏ dại mọc rậm rạp và cành cây gãy đổ trên Đường mòn Blue Trail.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"They say the Red Trail is in good condition, but maintenance issues have persisted on the Blue Trail for quite some time.\", \"vi\": \"Họ cho biết Đường mòn Red Trail đang ở tình trạng tốt, nhưng các vấn đề bảo trì đã kéo dài trên Đường mòn Blue Trail trong một thời gian khá lâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As the newest member of the city council, you might not have heard many complaints yet.\", \"vi\": \"Là thành viên mới nhất của hội đồng thành phố, có thể bạn chưa nghe nhiều lời phàn nàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"However, if you do get briefings regarding the situation, I would be grateful for any updates you can pass along.\", \"vi\": \"Tuy nhiên, nếu bạn nhận được thông tin tóm tắt về tình hình này, tôi sẽ rất biết ơn mọi thông tin cập nhật mà bạn có thể chuyển tiếp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I reached out to parks commissioner Oscar Lunes for comments about this, but he hasn’t responded.\", \"vi\": \"Tôi đã liên hệ với ủy viên ban quản lý công viên Oscar Lunes để xin ý kiến về việc này, nhưng ông ấy vẫn chưa phản hồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Someone mentioned he might be busy preparing for retirement.\", \"vi\": \"Có người nhắc đến việc ông ấy có thể đang bận chuẩn bị nghỉ hưu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Greg Tanner\", \"vi\": \"Greg Tanner\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Hale City News\", \"vi\": \"Hale City News\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"City Parks Department Launches Volunteer Initiative\", \"vi\": \"Bộ phận Công viên Thành phố Phát động Sáng kiến Tình nguyện\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"By Greg Tanner\", \"vi\": \"Bởi Greg Tanner\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Hale City (July 12)—In response to residents’ concerns about conditions on the hiking paths at East Core Park, the Hale City Parks Department offers an explanation and an outline of its plans for trail upkeep.\", \"vi\": \"Hale City (Ngày 12 tháng 7)—Để đáp lại những lo ngại của cư dân về tình trạng các tuyến đường đi bộ đường dài tại Công viên East Core, Bộ phận Công viên Thành phố Hale đưa ra lời giải thích và phác thảo các kế hoạch bảo trì đường mòn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"“Trail maintenance is transitioning from being performed by city employees to an all-volunteer model,” said newly appointed parks commissioner Helen Yancey.\", \"vi\": \"Ủy viên ban quản lý công viên mới được bổ nhiệm Helen Yancey cho biết: “Công tác bảo trì đường mòn đang chuyển từ việc do nhân viên thành phố đảm nhiệm sang mô hình hoàn toàn dựa vào tình nguyện viên”.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"“Before my predecessor stepped down after twenty years of service to the city, he began this shift.\", \"vi\": \"“Trước khi người tiền nhiệm của tôi rời nhiệm sở sau hai mươi năm cống hiến cho thành phố, ông ấy đã bắt đầu sự thay đổi này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"The result was a temporary suspension of maintenance on the Blue Trail.”\", \"vi\": \"Kết quả là việc bảo trì Đường mòn Blue Trail đã bị tạm dừng trong thời gian ngắn”.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Ms. Yancey added that the volunteer model will save money and allow residents greater involvement with the park system.\", \"vi\": \"Bà Yancey cho biết thêm rằng mô hình tình nguyện sẽ giúp tiết kiệm tiền và cho phép cư dân tham gia nhiều hơn vào hệ thống công viên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Accordingly, the Hale City Parks Department has scheduled its first volunteer cleanup event, Trail Cleanup Day, on August 12, from 9:00 A.M. to 2:00 P.M. Those interested in volunteering may register online at www.halecityparks.org/events.\", \"vi\": \"Theo đó, Bộ phận Công viên Thành phố Hale đã lên lịch cho sự kiện dọn dẹp tình nguyện đầu tiên, Ngày Dọn dẹp Đường mòn, vào ngày 12 tháng 8, từ 9:00 sáng đến 2:00 chiều. Những ai quan tâm đến việc tham gia tình nguyện có thể đăng ký trực tuyến tại www.halecityparks.org/events.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Hale City Parks Department\", \"vi\": \"Bộ phận Công viên Thành phố Hale\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"August Announcements\", \"vi\": \"Thông báo tháng 8\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"The Hale City Parks Department’s inaugural Trail Cleanup Day, held on August 8, was a great success.\", \"vi\": \"Ngày Dọn dẹp Đường mòn đầu tiên của Bộ phận Công viên Thành phố Hale, được tổ chức vào ngày 8 tháng 8, đã diễn ra rất thành công.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"An enthusiastic group of volunteers cleared debris and weeds from the Blue Trail at East Core Park and had the path clean and usable just before noon on the bright, warm day.\", \"vi\": \"Một nhóm tình nguyện viên đầy nhiệt huyết đã dọn sạch rác vụn và cỏ dại khỏi Đường mòn Blue Trail tại Công viên East Core và làm cho lối đi sạch sẽ, có thể sử dụng được ngay trước buổi trưa trong ngày có thời tiết tươi sáng, ấm áp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Special thanks go to the following participants.\", \"vi\": \"Lời cảm ơn đặc biệt xin gửi tới những người tham gia sau đây.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Amy Harris, for coordinating volunteer efforts and bringing beverages\", \"vi\": \"Amy Harris, vì đã điều phối các hoạt động tình nguyện và mang theo đồ uống\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Jason Skoda, resident of the adjacent East Heights neighborhood, for lending his power trimmer, pruning shears, and rakes to our crew of volunteers\", \"vi\": \"Jason Skoda, cư dân của khu phố lân cận East Heights, vì đã cho đội ngũ tình nguyện viên mượn máy tỉa cây cầm tay, kéo cắt tỉa và cào\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"We encourage residents to visit this page often to learn about upcoming volunteer events.\", \"vi\": \"Chúng tôi khuyến khích cư dân thường xuyên truy cập trang này để tìm hiểu về các sự kiện tình nguyện sắp diễn ra.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = '065362aa-cdfe-4620-ad9b-f1144683b659';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Outbox <customer_service@outbox.com>\", \"vi\": \"Từ: Outbox <customer_service@outbox.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Waris Duale <warisduale@mailinsights.com>\", \"vi\": \"Đến: Waris Duale <warisduale@mailinsights.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: September 1\", \"vi\": \"Ngày: Ngày 1 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Store news\", \"vi\": \"Chủ đề: Tin tức cửa hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Great news, Ms. Duale.\", \"vi\": \"Tin tuyệt vời, thưa cô Duale.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Outbox, the number one office supply store in the Grindstone River Valley region, has expanded its store on Lakeview Avenue to include an office furniture department.\", \"vi\": \"Outbox, cửa hàng cung cấp văn phòng phẩm số một tại khu vực thung lũng Grindstone River, đã mở rộng cửa hàng trên đại lộ Lakeview để bổ sung thêm một khu vực bán đồ nội thất văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To mark this occasion, members of our rewards club will receive a 20% discount on all office furniture.\", \"vi\": \"Để đánh dấu dịp này, các thành viên câu lạc bộ khách hàng thân thiết của chúng tôi sẽ được giảm giá 20% cho tất cả các mặt hàng nội thất văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Additionally, they will earn double rewards points during this sales event.\", \"vi\": \"Ngoài ra, họ sẽ nhận được gấp đôi điểm thưởng trong đợt khuyến mãi này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Orders are accepted in all stores as well as on our Web site, www.outbox.com.\", \"vi\": \"Các đơn hàng được chấp nhận tại tất cả các cửa hàng cũng như trên trang web của chúng tôi, www.outbox.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Use this opportunity to update your business office, and, in the process, save some money and accumulate rewards points.\", \"vi\": \"Hãy tận dụng cơ hội này để nâng cấp văn phòng làm việc của bạn, đồng thời tiết kiệm tiền bạc và tích lũy điểm thưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Hurry, offer ends September 30.\", \"vi\": \"Nhanh tay lên, ưu đãi kết thúc vào ngày 30 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '068ee8d5-4deb-48c2-a8f6-edb3abc71522';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Contempo Spaces\", \"vi\": \"Contempo Spaces\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Window Treatment Package\", \"vi\": \"Gói Trang Trí Cửa Sổ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"If you are considering redecorating the windows of your living room, dining room, or bedroom, Contempo Spaces has the perfect treatment design package for you.\", \"vi\": \"Nếu bạn đang cân nhắc việc trang trí lại cửa sổ cho phòng khách, phòng ăn hoặc phòng ngủ của mình, Contempo Spaces có gói thiết kế trang trí hoàn hảo dành cho bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We will help you put together the right combination of shades, panels, drapes, and valances—all perfectly tailored to fit your windows.\", \"vi\": \"Chúng tôi sẽ giúp bạn kết hợp các loại rèm cuốn, rèm phẳng, rèm vải và rèm trang trí một cách phù hợp nhất—tất cả đều được may đo hoàn hảo để vừa vặn với cửa sổ nhà bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Here\'s how it works:\", \"vi\": \"Quy trình thực hiện như sau:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"• First, one of our style representatives will come to your home and measure and photograph the windows in each room.\", \"vi\": \"• Đầu tiên, một đại diện phong cách của chúng tôi sẽ đến nhà bạn để đo đạc và chụp ảnh cửa sổ ở mỗi phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"• During that visit, our representative will show you samples of the many styles of fabrics and hardware available in our product line.\", \"vi\": \"• Trong chuyến thăm đó, đại diện của chúng tôi sẽ cho bạn xem các mẫu về nhiều kiểu dáng vải và phụ kiện có sẵn trong dòng sản phẩm của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Or, you can opt to visit our showroom after the home visit and make your selections there.\", \"vi\": \"Hoặc, bạn có thể chọn đến thăm phòng trưng bày của chúng tôi sau chuyến thăm nhà và đưa ra lựa chọn của mình tại đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"• One or two days after you\'ve made your window treatment decisions, we will send you an invoice, listing the cost for materials, installation, and labor.\", \"vi\": \"• Một hoặc hai ngày sau khi bạn đưa ra quyết định về việc trang trí cửa sổ, chúng tôi sẽ gửi cho bạn một hóa đơn, liệt kê chi phí cho vật liệu, việc lắp đặt và nhân công.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The quoted price is valid for thirty days.\", \"vi\": \"Mức giá được báo có hiệu lực trong vòng ba mươi ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Upon receipt of payment, materials will be ordered.\", \"vi\": \"Ngay khi nhận được thanh toán, vật liệu sẽ được đặt hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"It usually takes from seven to fourteen days for them to reach our store.\", \"vi\": \"Thường mất từ bảy đến mười bốn ngày để chúng về đến cửa hàng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"• Finally, we will contact you to schedule the date and time of installation.\", \"vi\": \"• Cuối cùng, chúng tôi sẽ liên hệ với bạn để lên lịch ngày giờ lắp đặt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Depending on the size of the project, installation can take two to eight hours.\", \"vi\": \"Tùy thuộc vào quy mô của dự án, việc lắp đặt có thể mất từ hai đến tám giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '06d08d1a-a222-4f4c-8b5d-b2d51a4bc839';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"(3 September)-Five years ago, Brian Trang signed a five-year lease to open his restaurant,\", \"vi\": \"(3 tháng 9) - Năm năm trước, Brian Trang đã ký hợp đồng thuê mặt bằng thời hạn 5 năm để mở nhà hàng của mình,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Trang\'s Bistro, at 30 Luray Place.\", \"vi\": \"Trang\'s Bistro, tại số 30 phố Luray Place.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Mr. Trang admits that the first two years of operation were quite ______[131].\", \"vi\": \"Ông Trang thừa nhận rằng hai năm hoạt động đầu tiên khá là ______[131].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [131]}, {\"en\": \"\\\"We offer spicy food from Vietnam\'s central region,\\\" he explains.\", \"vi\": \"\\\"Chúng tôi phục vụ các món ăn cay đến từ vùng miền Trung Việt Nam,\\\" ông giải thích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"We didn\'t do well at first ______[132] the cuisine is based on unfamiliar herbs and hot flavors.\", \"vi\": \"\\\"Chúng tôi đã không đạt kết quả tốt lúc đầu ______[132] ẩm thực dựa trên các loại rau thơm lạ và hương vị cay nồng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [132]}, {\"en\": \"It took a while to catch on with customers.\\\"\", \"vi\": \"Phải mất một thời gian để khách hàng đón nhận.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"But Mr. Trang was confident the food would gain in popularity, and he was correct.\", \"vi\": \"Nhưng ông Trang tự tin rằng món ăn sẽ ngày càng trở nên phổ biến, và ông đã đúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"______[133] Mr. Trang has just signed another five-year lease, and he is planning ______[134] the space next year\", \"vi\": \"______[133] Ông Trang vừa ký thêm một hợp đồng thuê 5 năm nữa, và ông ấy đang lên kế hoạch ______[134] không gian vào năm tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [133, 134]}]' WHERE `id` = '07348394-b7d4-4c25-9c02-1f1f990c10f6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Nicole Fernandez [12:23 P.M.]\", \"vi\": \"Nicole Fernandez [12:23 P.M.]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Tad, this is just to let you know I\'ll be in Amherst next Monday.\", \"vi\": \"Tad, tôi chỉ muốn báo cho bạn biết là tôi sẽ đến Amherst vào thứ Hai tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Tad Yates [12:25 P.M.]\", \"vi\": \"Tad Yates [12:25 P.M.]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"What\'s going on?\", \"vi\": \"Có chuyện gì thế?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Nicole Fernandez [12:26 P.M.]\", \"vi\": \"Nicole Fernandez [12:26 P.M.]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our Amherst office requested a training session.\", \"vi\": \"Văn phòng Amherst của chúng ta đã yêu cầu một buổi đào tạo.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Their instructor has to take an unexpected trip, and they need a substitute.\", \"vi\": \"Giảng viên của họ phải đi công tác đột xuất, và họ cần người dạy thay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Tad Yates [12:26 P.M.]\", \"vi\": \"Tad Yates [12:26 P.M.]\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Did you manage to book a flight?\", \"vi\": \"Bạn đã đặt được vé máy bay chưa?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Nicole Fernandez [12:27 P.M.]\", \"vi\": \"Nicole Fernandez [12:27 P.M.]\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Not on such short notice.\", \"vi\": \"Không kịp với thời gian thông báo gấp như vậy đâu.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I\'ll drive.\", \"vi\": \"Tôi sẽ lái xe đi.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Tad Yates [12:28 P.M.]\", \"vi\": \"Tad Yates [12:28 P.M.]\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"OK, good luck!\", \"vi\": \"Được rồi, chúc may mắn nhé!\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '07399248-4103-48af-b40e-973a9efa614d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Power Outage Scheduled at City Hall\", \"vi\": \"Lịch Cắt Điện Tại Tòa Nhà Thành Phố\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"On Friday, April 14, the city hall\'s electricity is scheduled to be shut down at 7 A.M. and restored at 6 P.M. The building ______[131] for the day.\", \"vi\": \"Vào thứ Sáu, ngày 14 tháng 4, hệ thống điện của tòa nhà thành phố dự kiến sẽ bị cắt lúc 7 giờ sáng và có lại lúc 6 giờ chiều. Tòa nhà sẽ ______[131] trong ngày hôm đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"During the power outage, the emergency lighting system will be upgraded.\", \"vi\": \"Trong thời gian mất điện, hệ thống chiếu sáng khẩn cấp sẽ được nâng cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"______[132], all circuit panels will be replaced to bring them into compliance with current safety codes.\", \"vi\": \"______[132], tất cả các bảng mạch sẽ được thay thế để đảm bảo tuân thủ các quy định an toàn hiện hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [132]}, {\"en\": \"______[133] exiting city hall offices on Thursday, please disconnect all desktop computers, wireless servers, and other computer-related equipment.\", \"vi\": \"______[133] khi rời khỏi các văn phòng của tòa nhà thành phố vào thứ Năm, vui lòng ngắt kết nối tất cả máy tính để bàn, máy chủ không dây và các thiết bị liên quan đến máy tính khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [133]}, {\"en\": \"Furthermore, employees are asked to remove any personal contents from the kitchenette.\", \"vi\": \"Hơn nữa, nhân viên được yêu cầu dọn dẹp mọi vật dụng cá nhân khỏi khu vực bếp nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[134].\", \"vi\": \"______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [134]}, {\"en\": \"Please direct questions or concerns to the director of building maintenance.\", \"vi\": \"Vui lòng gửi các câu hỏi hoặc thắc mắc cho giám đốc bộ phận bảo trì tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '07445d6d-a4e3-4835-9a04-ee49ac777822';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Max Aurinen <maurinen@edwildurables.com>\", \"vi\": \"Đến: Max Aurinen <maurinen@edwildurables.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Jessica Seung <jseung@edwildurables.com>\", \"vi\": \"Từ: Jessica Seung <jseung@edwildurables.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: April 21\", \"vi\": \"Ngày: 21 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Shadowing appointments\", \"vi\": \"Chủ đề: Các lịch hẹn đi kèm quan sát thực tế (shadowing)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Name - Title and Division - Building and Office - Phone Extension\", \"vi\": \"Tên - Chức vụ và Bộ phận - Tòa nhà và Văn phòng - Số máy lẻ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Shane Faraci - Director, Information Systems - Ardmore, Room 210 - 022\", \"vi\": \"Shane Faraci - Giám đốc, Hệ thống Thông tin - Ardmore, Phòng 210 - 022\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Margery Gazda - Sr. Director, Retail Department - Ardmore, Room 323 - 023\", \"vi\": \"Margery Gazda - Giám đốc Cấp cao, Bộ phận Bán lẻ - Ardmore, Phòng 323 - 023\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Patricia Nesbit - Director, Small Appliance Division - Winston West, Room 07 - 333\", \"vi\": \"Patricia Nesbit - Giám đốc, Bộ phận Thiết bị Nhỏ - Winston West, Phòng 07 - 333\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Latisha Lake - Director, Large Appliance Division - Winston East, Room 102 - 145\", \"vi\": \"Latisha Lake - Giám đốc, Bộ phận Thiết bị Lớn - Winston East, Phòng 102 - 145\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Orville Martin - Sr. Director, Electronics Division - Meisner, Room 410 - 254\", \"vi\": \"Orville Martin - Giám đốc Cấp cao, Bộ phận Điện tử - Meisner, Phòng 410 - 254\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"May 6 - 9 A.M. to noon - Complete documentation, benefits presentation, and enrollment\", \"vi\": \"Ngày 6 tháng 5 - 9 giờ sáng đến 12 giờ trưa - Hoàn thiện hồ sơ tài liệu, giới thiệu phúc lợi và đăng ký\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Noon to 1 P.M. - Lunch\", \"vi\": \"12 giờ trưa đến 1 giờ chiều - Nghỉ trưa\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"1 P.M. to 3 P.M. - Meet with assigned department head\", \"vi\": \"1 giờ chiều đến 3 giờ chiều - Gặp gỡ trưởng bộ phận được phân công\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"3 P.M. to 5 P.M. - Meet with Information Systems staff for laptop and profile setup\", \"vi\": \"3 giờ chiều đến 5 giờ chiều - Gặp gỡ nhân viên Hệ thống Thông tin để thiết lập máy tính xách tay và hồ sơ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"May 7 - 9 A.M. to 5 P.M. - Latisha Lake\", \"vi\": \"Ngày 7 tháng 5 - 9 giờ sáng đến 5 giờ chiều - Latisha Lake\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"May 8 - 9 A.M. to 5 P.M. - Orville Martin\", \"vi\": \"Ngày 8 tháng 5 - 9 giờ sáng đến 5 giờ chiều - Orville Martin\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"May 9 - 9 A.M. to 5 P.M. - Amos Hillman\", \"vi\": \"Ngày 9 tháng 5 - 9 giờ sáng đến 5 giờ chiều - Amos Hillman\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"May 10 - 9 A.M. to 5 P.M. - Margery Gazda\", \"vi\": \"Ngày 10 tháng 5 - 9 giờ sáng đến 5 giờ chiều - Margery Gazda\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Edwil Durables, Inc.\", \"vi\": \"Công ty TNHH Edwil Durables\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Contact List of Department Leaders\", \"vi\": \"Danh bạ Liên hệ của các Trưởng bộ phận\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Onboarding Schedule for David Rein\", \"vi\": \"Lịch trình Hội nhập cho David Rein\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Hello, Max,\", \"vi\": \"Chào Max,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"On May 6, we will welcome Mr. David Rein for his first day as a new employee.\", \"vi\": \"Vào ngày 6 tháng 5, chúng ta sẽ chào đón ông David Rein trong ngày làm việc đầu tiên với tư cách là nhân viên mới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Mr. Rein is a graduate of Northburg University and has worked at Zelehost, Inc., and Dorfax Industries.\", \"vi\": \"Ông Rein là cựu sinh viên tốt nghiệp Đại học Northburg và từng làm việc tại Zelehost, Inc. và Dorfax Industries.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Mr. Rein will fulfill the role of an assistant manufacturing supervisor in our Large Appliance Division.\", \"vi\": \"Ông Rein sẽ đảm nhận vai trò trợ lý giám sát sản xuất tại Bộ phận Thiết bị Lớn của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Please prepare his initial onboarding paperwork and arrange a schedule for his first two weeks with Edwil Durables, Inc.\", \"vi\": \"Vui lòng chuẩn bị thủ tục giấy tờ hội nhập ban đầu của ông ấy và sắp xếp lịch trình cho hai tuần đầu tiên tại Edwil Durables, Inc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"As part of his training for his new position, let’s have him shadow our team leaders in several areas for a couple of days.\", \"vi\": \"Như một phần trong quá trình đào tạo cho vị trí mới của ông ấy, hãy để ông ấy đi theo quan sát các trưởng nhóm của chúng ta ở một số lĩnh vực trong vài ngày.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"This will allow him to learn more about the various departments he will eventually be interacting with.\", \"vi\": \"Điều này sẽ giúp ông ấy tìm hiểu thêm về các bộ phận khác nhau mà sau này ông ấy sẽ làm việc cùng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Also, assuming Amos Hillman returns on the expected date from his vacation in Thailand, please schedule a day for Mr. Rein to learn how prototypes are developed in the product labs.\", \"vi\": \"Ngoài ra, giả sử Amos Hillman trở lại vào đúng ngày dự kiến sau chuyến đi nghỉ ở Thái Lan, vui lòng sắp xếp một ngày để ông Rein tìm hiểu cách các nguyên mẫu được phát triển trong phòng thí nghiệm sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Jessica Seung, Human Resources Director\", \"vi\": \"Jessica Seung, Giám đốc Nhân sự\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Paper Work and Orientation\", \"vi\": \"Thủ tục Giấy tờ và Định hướng\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Shadowing\", \"vi\": \"Quan sát thực tế (Shadowing)\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '077d665a-cd9d-44a3-9569-3615900c2844';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Completely Unsatisfied - Somewhat Unsatisfied - Neutral - Somewhat Satisfied - Very Satisfied\", \"vi\": \"Hoàn toàn không hài lòng - Hơi không hài lòng - Bình thường - Hơi hài lòng - Rất hài lòng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Overall customer experience - ☐ - ☐ - ☑ - ☐ - ☐\", \"vi\": \"Trải nghiệm của khách hàng nói chung - ☐ - ☐ - ☑ - ☐ - ☐\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Customer service - ☐ - ☑ - ☐ - ☐ - ☐\", \"vi\": \"Dịch vụ khách hàng - ☐ - ☑ - ☐ - ☐ - ☐\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Product options - ☐ - ☐ - ☑ - ☐ - ☐\", \"vi\": \"Tùy chọn sản phẩm - ☐ - ☐ - ☑ - ☐ - ☐\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Product value - ☐ - ☐ - ☐ - ☑ - ☐\", \"vi\": \"Giá trị sản phẩm - ☐ - ☐ - ☐ - ☑ - ☐\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Web site organization - ☐ - ☐ - ☐ - ☐ - ☑\", \"vi\": \"Bố cục trang web - ☐ - ☐ - ☐ - ☐ - ☑\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Customer Survey Feedback Report\", \"vi\": \"Báo cáo Phản hồi Khảo sát Khách hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Generated for: Floorsy, Inc.\", \"vi\": \"Được tạo cho: Công ty Floorsy, Inc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Conducted by: Gwyneth Gupta\", \"vi\": \"Thực hiện bởi: Gwyneth Gupta\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Medallion Marketing Consultants\", \"vi\": \"Công ty Tư vấn Tiếp thị Medallion\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Comments: The results of Medallion\'s survey are compiled above.\", \"vi\": \"Nhận xét: Kết quả khảo sát của Medallion đã được tổng hợp ở trên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We had 923 responses.\", \"vi\": \"Chúng tôi đã nhận được 923 phản hồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"There are several areas where Floorsy could improve its services to grow the business.\", \"vi\": \"Có một số lĩnh vực mà Floorsy có thể cải thiện dịch vụ để phát triển kinh doanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"First, customers had issues getting adequate customer service—this was due to slow e-mail response times, especially when making changes to orders.\", \"vi\": \"Đầu tiên, khách hàng gặp vấn đề trong việc nhận dịch vụ chăm sóc khách hàng thỏa đáng—điều này là do thời gian phản hồi qua email chậm, đặc biệt là khi thực hiện thay đổi đối với đơn hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Medallion recommends investing in a chat window for the Web site and training customer representatives to use it.\", \"vi\": \"Medallion khuyên bạn nên đầu tư vào một cửa sổ chat cho trang web và đào tạo nhân viên chăm sóc khách hàng cách sử dụng nó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Customers enjoyed the Web site, and the chat feature would allow customers to get immediate service.\", \"vi\": \"Khách hàng rất thích trang web, và tính năng chat sẽ cho phép khách hàng nhận được dịch vụ ngay lập tức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"One general comment stood out regarding product options.\", \"vi\": \"Một ý kiến đóng góp chung đã nổi bật liên quan đến các tùy chọn sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Customers appreciated the wide variety of low-pile carpets with short fibers.\", \"vi\": \"Khách hàng đánh giá cao sự đa dạng của các loại thảm lông ngắn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"They appreciated their high durability for areas where people frequently walk.\", \"vi\": \"Họ đánh giá cao độ bền cao của thảm đối với những khu vực có lượng người qua lại thường xuyên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"However, they were also interested in thicker shag rugs for lounge areas like living rooms.\", \"vi\": \"Tuy nhiên, họ cũng quan tâm đến các loại thảm lông xù dày hơn dành cho các khu vực tiếp khách như phòng khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Floorsy Discount Coupon\", \"vi\": \"Phiếu Giảm Giá Floorsy\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Thank you for responding to our customer survey!\", \"vi\": \"Cảm ơn bạn đã tham gia khảo sát khách hàng của chúng tôi!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"As a reward for your support, get 20% off your next online purchase from May 1 to 31!\", \"vi\": \"Như một phần thưởng cho sự hỗ trợ của bạn, hãy nhận giảm giá 20% cho lần mua hàng trực tuyến tiếp theo từ ngày 1 đến ngày 31 tháng 5!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Enter the code REWARD20 at checkout.\", \"vi\": \"Nhập mã REWARD20 khi thanh toán.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Note: Floorsy.com offers free shipping and handling on all orders.\", \"vi\": \"Lưu ý: Floorsy.com miễn phí vận chuyển và xử lý cho tất cả các đơn hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Hendesia Low-Pile Rug in Ruby Red (6 x 9) - x 1 - $180.00\", \"vi\": \"Thảm lông ngắn Hendesia màu đỏ ruby (6 x 9) - x 1 - $180,00\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Verenia Shag Rug in Blue (6 x 9) - x 1 - $250.00\", \"vi\": \"Thảm lông xù Verenia màu xanh dương (6 x 9) - x 1 - $250,00\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Subtotal - $430.00\", \"vi\": \"Tạm tính - $430,00\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Discount - $86.00 (Code: REWARD20)\", \"vi\": \"Giảm giá - $86,00 (Mã: REWARD20)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Total - $344.00\", \"vi\": \"Tổng cộng - $344,00\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Paid in full\", \"vi\": \"Đã thanh toán toàn bộ\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Thank You For Your Order\", \"vi\": \"Cảm ơn Bạn Đã Đặt Hàng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Dear Mr. Lindsay,\", \"vi\": \"Kính gửi Ông Lindsay,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Thank you for your phone order.\", \"vi\": \"Cảm ơn bạn đã đặt hàng qua điện thoại.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"The following items from your order #104850 have been delivered.\", \"vi\": \"Các mặt hàng sau đây từ đơn hàng số #104850 của bạn đã được giao.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"As a growing business, we take all reviews and comments seriously.\", \"vi\": \"Là một doanh nghiệp đang phát triển, chúng tôi rất coi trọng mọi đánh giá và nhận xét.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Please visit www.floorsy.com/comments to submit a review, and receive 10% off your next purchase.\", \"vi\": \"Vui lòng truy cập www.floorsy.com/comments để gửi đánh giá và nhận giảm giá 10% cho lần mua hàng tiếp theo của bạn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"If you need assistance with your purchase, please e-mail customerservice@floorsy.com.\", \"vi\": \"Nếu bạn cần hỗ trợ với giao dịch mua hàng của mình, vui lòng gửi email đến customerservice@floorsy.com.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}]' WHERE `id` = '07836886-d96c-48dc-b28f-d3055f30aa17';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Staff\", \"vi\": \"Đến: Nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Amy Henwith\", \"vi\": \"Từ: Amy Henwith\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 15 January\", \"vi\": \"Ngày: 15 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Exciting news\", \"vi\": \"Chủ đề: Tin vui\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Staff,\", \"vi\": \"Gửi toàn thể nhân viên,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thanks for a great year!\", \"vi\": \"Cảm ơn vì một năm tuyệt vời!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In case you haven\'t heard, Henwith Home Supply will be ______[135] our second store this spring.\", \"vi\": \"Trong trường hợp bạn chưa nghe tin, Henwith Home Supply sẽ ______[135] cửa hàng thứ hai của chúng ta vào mùa xuân này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [135]}, {\"en\": \"This additional retail site will be located in the shopping centre at the corner of Aberton Parkway and Sutton Avenue in Derbyshire.\", \"vi\": \"Địa điểm bán lẻ bổ sung này sẽ nằm trong trung tâm mua sắm tại góc đường Aberton Parkway và đại lộ Sutton ở Derbyshire.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We will be accepting applications for cashiers and sales positions ______[136] 1 April.\", \"vi\": \"Chúng tôi sẽ nhận đơn ứng tuyển cho các vị trí thu ngân và nhân viên bán hàng ______[136] ngày 1 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [136]}, {\"en\": \"The personnel director will review applicants\' qualifications from 2 April to 6 April, and ______[137] is scheduled to begin one week later.\", \"vi\": \"Giám đốc nhân sự sẽ xem xét năng lực của các ứng viên từ ngày 2 tháng 4 đến ngày 6 tháng 4, và ______[137] dự kiến bắt đầu một tuần sau đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [137]}, {\"en\": \"______[138].\", \"vi\": \"______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [138]}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Amy Henwith, CEO\", \"vi\": \"Amy Henwith, Giám đốc điều hành\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Henwith Home Supply\", \"vi\": \"Henwith Home Supply\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '083738ca-b221-4c53-a974-a89f0791a59a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"I have spent most of my life in the woods of rural Colorado, where I have always looked to the beauty of nature for inspiration.\", \"vi\": \"Tôi đã dành phần lớn cuộc đời mình ở vùng rừng núi Colorado nông thôn, nơi tôi luôn tìm kiếm vẻ đẹp của thiên nhiên để lấy cảm hứng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"My plates, bowls, and cutting boards are hand carved from pieces of wood that were foraged from fallen trees that I discovered while on various hikes through the forest.\", \"vi\": \"Các sản phẩm đĩa, bát và thớt của tôi được chạm khắc thủ công từ các khúc gỗ được nhặt từ những cây bị đổ mà tôi phát hiện ra trong các chuyến đi bộ đường dài khác nhau qua khu rừng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Each object in my wooden kitchenware collection is one of a kind and has been carved to bring out the natural curves and grain patterns of the wood.\", \"vi\": \"Mỗi đồ vật trong bộ sưu tập đồ dùng nhà bếp bằng gỗ của tôi đều là độc nhất vô nhị và được chạm khắc để làm nổi bật các đường cong tự nhiên và hoa văn vân gỗ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"These unique pieces can last a lifetime if stored and treated properly.\", \"vi\": \"Những món đồ độc đáo này có thể bền bỉ suốt đời nếu được bảo quản và xử lý đúng cách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"They should never be left to soak in water, as prolonged exposure to water will cause them to warp.\", \"vi\": \"Chúng không bao giờ được để ngâm trong nước, vì việc tiếp xúc lâu với nước sẽ khiến chúng bị cong vênh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"It is also a good idea to apply a light coat of mineral oil from time to time to prevent the colors from fading.\", \"vi\": \"Đồng thời, bạn cũng nên thoa một lớp mỏng dầu khoáng thỉnh thoảng để ngăn chặn màu sắc bị phai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"For more tips on how to best protect your natural wood product from deterioration, visit www.hollyhollingsworth.com.\", \"vi\": \"Để biết thêm mẹo về cách bảo vệ tốt nhất sản phẩm gỗ tự nhiên của bạn khỏi bị hư hỏng, hãy truy cập www.hollyhollingsworth.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Thank you for purchasing my products!\", \"vi\": \"Cảm ơn bạn đã mua các sản phẩm của tôi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— Holly Hollingsworth\", \"vi\": \"— Holly Hollingsworth\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '084538b2-8bd3-46c1-8450-14db6f5c11d8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.camsfurniture.ca/about_us\", \"vi\": \"https://www.camsfurniture.ca/about_us\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"About Us - Catalogue - Reviews - Contact Us\", \"vi\": \"Về chúng tôi - Danh mục - Đánh giá - Liên hệ với chúng tôi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Cam\'s Furniture has been a fixture in Ottawa for more than 50 years.\", \"vi\": \"Cửa hàng nội thất Cam\'s Furniture đã gắn bó lâu năm tại Ottawa trong hơn 50 năm qua.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"With our focus on exceptional customer service, we guarantee that your time in our store will be both pleasant and worthwhile!\", \"vi\": \"Với sự tập trung vào dịch vụ khách hàng xuất sắc, chúng tôi đảm bảo rằng thời gian của bạn tại cửa hàng của chúng tôi sẽ vừa dễ chịu vừa đáng giá!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Our daily business operations are overseen by George Meara, the eldest son of founder Cam Meara.\", \"vi\": \"Các hoạt động kinh doanh hàng ngày của chúng tôi được giám sát bởi George Meara, con trai trưởng của nhà sáng lập Cam Meara.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"George is joined by his sister, Elise Meara, and an enthusiastic team of sales associates who will help you choose the best furniture for your needs.\", \"vi\": \"Cùng đồng hành với George là em gái của anh ấy, Elise Meara, và một đội ngũ nhân viên bán hàng nhiệt tình, những người sẽ giúp bạn chọn lựa những món đồ nội thất phù hợp nhất với nhu cầu của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our enormous showroom features a broad selection of high-quality furniture arranged in different types of residential rooms and office spaces.\", \"vi\": \"Phòng trưng bày khổng lồ của chúng tôi có rất nhiều lựa chọn nội thất chất lượng cao được sắp xếp theo các loại không gian phòng ở và không gian văn phòng khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"And, along with all the top brands of furniture, we are proud to carry unique and environmentally friendly items sourced from the Green Directions Trade Fair.\", \"vi\": \"Và bên cạnh tất cả các thương hiệu nội thất hàng đầu, chúng tôi tự hào cung cấp các mặt hàng độc đáo và thân thiện với môi trường có nguồn gốc từ Hội chợ Thương mại Green Directions.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Our head buyer, Debbie Sarno, attends this event annually to choose fantastic new products for our store.\", \"vi\": \"Trưởng bộ phận thu mua của chúng tôi, Debbie Sarno, tham dự sự kiện này hàng năm để chọn ra các sản phẩm mới tuyệt vời cho cửa hàng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We offer complimentary delivery and setup for all customers whose home or business is within the boundaries of the city of Ottawa.\", \"vi\": \"Chúng tôi cung cấp dịch vụ giao hàng và lắp đặt miễn phí cho tất cả khách hàng có nhà riêng hoặc doanh nghiệp nằm trong ranh giới thành phố Ottawa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Linda Fei (1:57 P.M.)\", \"vi\": \"Linda Fei (1:57 Chiều)\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Toby, I\'m at Cam\'s Furniture.\", \"vi\": \"Toby, tôi đang ở cửa hàng nội thất Cam\'s Furniture.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The items you chose for our reception area look great!\", \"vi\": \"Những món đồ mà bạn đã chọn cho khu vực lễ tân của chúng ta trông rất tuyệt!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The salesperson told me the bill is going to be a little more than expected because there will be a charge for delivery and setup.\", \"vi\": \"Nhân viên bán hàng đã nói với tôi rằng hóa đơn sẽ cao hơn dự kiến một chút vì sẽ có phí giao hàng và lắp đặt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The crew can come out to our office on Friday, so we\'ll definitely be able to have everything in place before our clients arrive on Monday.\", \"vi\": \"Đội ngũ nhân viên có thể đến văn phòng của chúng ta vào thứ Sáu, vì vậy chúng ta chắc chắn sẽ có thể sắp xếp mọi thứ ngăn nắp trước khi khách hàng đến vào thứ Hai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Toby Pesenti (1:59 P.M.)\", \"vi\": \"Toby Pesenti (1:59 Chiều)\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Great!\", \"vi\": \"Tuyệt vời!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The slightly higher cost shouldn\'t be a problem.\", \"vi\": \"Chi phí cao hơn một chút không nên là vấn đề lớn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We have enough in our budget.\", \"vi\": \"Chúng ta có đủ ngân sách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Online Reviews\", \"vi\": \"Đánh giá trực tuyến\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Customer review posted by Linda Fei on 23 July at 5:32 P.M.\", \"vi\": \"Đánh giá của khách hàng được đăng bởi Linda Fei vào ngày 23 tháng 7 lúc 5:32 chiều.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"The staff at Cam\'s Furniture is extraordinarily helpful and professional.\", \"vi\": \"Nhân viên tại Cam\'s Furniture cực kỳ nhiệt tình và chuyên nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I was pleased that we could get eco-friendly pieces for our company\'s reception area.\", \"vi\": \"Tôi rất hài lòng khi chúng tôi có thể mua được những món đồ thân thiện với môi trường cho khu vực lễ tân của công ty.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"The furniture is beautiful—we\'ve been receiving many compliments.\", \"vi\": \"Đồ nội thất rất đẹp — chúng tôi đã nhận được rất nhiều lời khen ngợi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Cam\'s delivery team spent extra time at our new office space to make sure that the furniture was arranged in exactly the right way.\", \"vi\": \"Đội ngũ giao hàng của Cam\'s đã dành thêm thời gian tại không gian văn phòng mới của chúng tôi để đảm bảo rằng đồ nội thất được sắp xếp theo đúng cách hoàn hảo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"We look forward to shopping at Cam\'s again!\", \"vi\": \"Chúng tôi mong muốn sẽ mua sắm tại Cam\'s một lần nữa!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '08caf6d4-d14f-44e5-ad98-2a3379e96960';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Big Strike Lanes\", \"vi\": \"Khu Bowling Big Strike Lanes\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"20 Fortune Way, Glasgow, G41 4LM\", \"vi\": \"20 Fortune Way, Glasgow, G41 4LM\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"(0141) 496 0184\", \"vi\": \"(0141) 496 0184\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The excitement is all around you at Big Strike Lanes!\", \"vi\": \"Niềm vui ngập tràn xung quanh bạn tại Big Strike Lanes!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Bring your family and friends to bowl, play video games, try out our unique virtual-reality station, and savour delicious meals at our own restaurant.\", \"vi\": \"Hãy đưa gia đình và bạn bè đến để chơi bowling, chơi trò chơi điện tử, trải nghiệm trạm thực tế ảo độc đáo của chúng tôi, và thưởng thức những bữa ăn ngon tại nhà hàng riêng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"With 18 bowling lanes, state-of-the-art gaming consoles, and award-winning food, Big Strike Lanes has something for everyone.\", \"vi\": \"Với 18 làn bowling, các máy chơi game tối tân, và món ăn đạt giải thưởng, Big Strike Lanes có những dịch vụ phù hợp cho tất cả mọi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Visit us for one of our deals today; they will not be available after 31 May!\", \"vi\": \"Hãy đến thăm chúng tôi để tận hưởng một trong các ưu đãi ngay hôm nay; chúng sẽ không còn hiệu lực sau ngày 31 tháng 5!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Gold Deal\", \"vi\": \"Gói Ưu Đãi Vàng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Enjoy one hour of bowling and a £25 gaming credit.\", \"vi\": \"Tận hưởng một giờ chơi bowling và 25 bảng tiền chơi game.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"A £40 value for only £30!\", \"vi\": \"Giá trị 40 bảng chỉ với 30 bảng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Platinum Deal\", \"vi\": \"Gói Ưu Đãi Bạch Kim\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Enjoy two hours of bowling and two virtual-reality experiences.\", \"vi\": \"Tận hưởng hai giờ chơi bowling và hai trải nghiệm thực tế ảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"A £50 value for only £40!\", \"vi\": \"Giá trị 50 bảng chỉ với 40 bảng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"🎳\", \"vi\": \"🎳\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Big Strike Lanes: Plenty To Enjoy\", \"vi\": \"Big Strike Lanes: Rất nhiều điều để tận hưởng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"16 May\", \"vi\": \"Ngày 16 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I was very sad when Freeside Bowling shut its doors last year.\", \"vi\": \"Tôi đã rất buồn khi Freeside Bowling đóng cửa vào năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Rustic, quaint, and run by the same family for three generations, it had the type of charm that only an old establishment can provide.\", \"vi\": \"Mang nét mộc mạc, cổ kính, và được điều hành bởi cùng một gia đình qua ba thế hệ, nơi đây có loại sức hút mà chỉ một cơ sở lâu đời mới có thể mang lại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I have many happy memories of good times there.\", \"vi\": \"Tôi có rất nhiều kỷ niệm vui về những khoảng thời gian tuyệt vời ở đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Then Big Strike Lanes opened a few months ago, and I wondered how it would compare.\", \"vi\": \"Sau đó, Big Strike Lanes mở cửa cách đây vài tháng, và tôi tự hỏi nó sẽ sánh ngang ra sao.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"A few friends and I decided to visit and take advantage of a promotional offer, and I\'m happy to say that our experience was better than expected.\", \"vi\": \"Tôi và vài người bạn quyết định ghé thăm và tận dụng một chương trình ưu đãi khuyến mại, và tôi rất vui khi nói rằng trải nghiệm của chúng tôi tốt hơn mong đợi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"The bowling was great, and I really enjoyed the virtual reality, which I had never tried before.\", \"vi\": \"Hoạt động chơi bowling rất tuyệt, và tôi thực sự thích thực tế ảo, thứ mà tôi chưa từng thử trước đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"At the restaurant, our servers were friendly, and the food was delicious.\", \"vi\": \"Tại nhà hàng, nhân viên phục vụ của chúng tôi rất thân thiện, và đồ ăn thì ngon.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"My only criticism of the place is the location.\", \"vi\": \"Lời chỉ trích duy nhất của tôi về địa điểm này là vị trí.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Big Strike Lanes is situated in a large shopping centre next to a busy motorway, so the surroundings are not exactly inviting.\", \"vi\": \"Big Strike Lanes nằm trong một trung tâm mua sắm lớn cạnh một tuyến đường cao tốc đông đúc, vì vậy khung cảnh xung quanh không hề hấp dẫn chút nào.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"—Sophie Shaw\", \"vi\": \"—Sophie Shaw\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '08d213a1-4c8b-4e50-ba06-b29e1bd00293';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Grace Wu\", \"vi\": \"Đến: Grace Wu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Carlos Garcia\", \"vi\": \"Từ: Carlos Garcia\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Employee of the Month\", \"vi\": \"Chủ đề: Nhân viên của tháng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: July 25\", \"vi\": \"Ngày: 25 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Grace:\", \"vi\": \"Grace thân mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am writing to nominate a member of our production team, Dwight Clinton, as a candidate for Franklin Appliances\' Employee of the Month.\", \"vi\": \"Tôi viết thư này để đề cử một thành viên trong đội ngũ sản xuất của chúng tôi, Dwight Clinton, làm ứng viên cho danh hiệu Nhân viên của tháng tại Franklin Appliances.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We have been working diligently to complete the design of a more energy-efficient air-conditioning unit by our July 31 deadline, and Mr. Clinton\'s participation on the team has made it possible for us to meet our challenging targets.\", \"vi\": \"Chúng tôi đã làm việc chăm chỉ để hoàn thành thiết kế mẫu máy điều hòa tiết kiệm năng lượng hơn kịp thời hạn ngày 31 tháng 7, và sự tham gia của ông Clinton trong nhóm đã giúp chúng tôi đạt được các mục tiêu đầy thử thách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In his eight years at Franklin Appliances, Mr. Clinton has demonstrated the capacity to grow both professionally and personally.\", \"vi\": \"Trong tám năm làm việc tại Franklin Appliances, ông Clinton đã thể hiện năng lực phát triển cả về mặt chuyên môn lẫn cá nhân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"He began as an apprentice and has steadily worked his way up to Testing Engineer.\", \"vi\": \"Ông bắt đầu với tư cách là một kỹ học việc và đã nỗ lực thăng tiến vững vàng để trở thành Kỹ sư Kiểm định.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Mr. Clinton has been instrumental in helping us realize the company\'s mission of designing high-quality energy-saving refrigerators, ovens, washing machines, and cooling systems.\", \"vi\": \"Ông Clinton đã đóng vai trò quan trọng trong việc giúp chúng tôi hiện thực hóa sứ mệnh của công ty là thiết kế tủ lạnh, lò nướng, máy giặt và hệ thống làm mát tiết kiệm năng lượng, chất lượng cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"It would be difficult to envision meeting our product deadlines without his contribution to every project he is assigned to.\", \"vi\": \"Sẽ rất khó khăn để hình dung việc đáp ứng các thời hạn sản phẩm nếu thiếu đi đóng góp của ông trong mọi dự án mà ông được giao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Thank you for your consideration.\", \"vi\": \"Cảm ơn sự xem xét của bạn.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Carlos\", \"vi\": \"Carlos\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To: All employees\", \"vi\": \"Đến: Tất cả nhân viên\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"From: Grace Wu\", \"vi\": \"Từ: Grace Wu\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Date: August 1\", \"vi\": \"Ngày: 1 tháng 8\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Subject: Employee of the Month\", \"vi\": \"Chủ đề: Nhân viên của tháng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"It is my privilege to announce that Dwight Clinton has been chosen to be our July Employee of the Month.\", \"vi\": \"Tôi rất vinh dự được thông báo rằng Dwight Clinton đã được chọn làm Nhân viên của tháng 7 của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Franklin Appliances promotes an environment of creative collaboration, and Mr. Clinton has demonstrated the leadership and support necessary to help make this mission a reality.\", \"vi\": \"Franklin Appliances thúc đẩy một môi trường cộng tác sáng tạo, và ông Clinton đã thể hiện khả năng lãnh đạo cũng như sự hỗ trợ cần thiết để biến sứ mệnh này thành hiện thực.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Thanks in large part to his commendable efforts, we are pleased to announce that our newest product, the Eco-Cool Wave, was successfully launched yesterday.\", \"vi\": \"Phần lớn nhờ vào những nỗ lực đáng khen ngợi của ông, chúng tôi rất vui mừng thông báo rằng sản phẩm mới nhất của chúng tôi, Eco-Cool Wave, đã được ra mắt thành công vào ngày hôm qua.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Mr. Clinton has dedicated a large part of his professional life to rising through the ranks at Franklin Appliances.\", \"vi\": \"Ông Clinton đã cống hiến phần lớn cuộc đời sự nghiệp của mình để thăng tiến qua các cấp bậc tại Franklin Appliances.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"His story is indicative of the supportive environment that the company offers by promoting internally and providing professional growth as well as development opportunities.\", \"vi\": \"Câu chuyện của ông là minh chứng cho môi trường hỗ trợ mà công ty mang lại bằng cách thúc đẩy tuyển dụng nội bộ và cung cấp các cơ hội phát triển nghề nghiệp cũng như phát triển bản thân.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Franklin Appliances is honored to present Mr. Clinton with two paid personal days to use at his discretion.\", \"vi\": \"Franklin Appliances rất vinh dự khi tặng ông Clinton hai ngày nghỉ phép có lương để sử dụng theo ý muốn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"The next time you see Dwight, please offer your congratulations!\", \"vi\": \"Lần tới khi bạn gặp Dwight, hãy gửi lời chúc mừng đến anh ấy nhé!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}]' WHERE `id` = '090267ea-d49d-4987-847b-b0e49f661781';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Do you fancy playing games with your mates?\", \"vi\": \"Bạn có thích chơi trò chơi cùng những người bạn của mình không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Do you enjoy tasty tea and snacks?\", \"vi\": \"Bạn có thích trà và đồ ăn nhẹ ngon miệng không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"If so, you won\'t want to miss Game Night at Chez Tournoi.\", \"vi\": \"Nếu có, bạn sẽ không muốn bỏ lỡ Đêm Trò Chơi tại Chez Tournoi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Each Friday from 6 to 10 P.M., Chez Tournoi welcomes you to its 44 Broad Avenue, Kingston, location for some fun and ------- (131).\", \"vi\": \"Vào mỗi thứ Sáu từ 6 đến 10 giờ tối, Chez Tournoi chào đón bạn tại cơ sở ở số 44 phố Broad, Kingston, để tham gia các hoạt động giải trí và ------- (131).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [131]}, {\"en\": \"Choose from our collection of board games, card games, trivia games, and more.\", \"vi\": \"Hãy chọn từ bộ sưu tập các trò chơi cờ bàn, trò chơi bài, trò chơi đố vui và nhiều hơn nữa của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"------- (132).\", \"vi\": \"------- (132).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [132]}, {\"en\": \"While you play, you can savour our freshly brewed tea, coffee, and hot chocolate ------- (133) our mouthwatering pastries.\", \"vi\": \"Trong khi chơi, bạn có thể thưởng thức trà pha tươi, cà phê và sô-cô-la nóng ------- (133) các loại bánh ngọt hấp dẫn của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [133]}, {\"en\": \"Game Night at Chez Tournoi is the perfect opportunity ------- (134) and socialise.\", \"vi\": \"Đêm Trò Chơi tại Chez Tournoi là cơ hội hoàn hảo ------- (134) và giao lưu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [134]}, {\"en\": \"Reserve your spot by ringing 01555-672212 or visiting www.cheztournoi.co.uk/gamenight.\", \"vi\": \"Hãy đặt chỗ của bạn bằng cách gọi số 01555-672212 hoặc truy cập www.cheztournoi.co.uk/gamenight.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '09428234-6532-4b0f-b952-8b8344c98f28';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Lisa Dominguez (3:24 P.M.)\", \"vi\": \"Lisa Dominguez (3:24 CH)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Travis.\", \"vi\": \"Chào Travis.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I’m at the market shopping for tomatoes, but none of them are ripe.\", \"vi\": \"Em đang ở chợ mua cà chua, nhưng không có quả nào chín cả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Can you check to see if we have any frozen tomato sauce on hand from last week?\", \"vi\": \"Anh xem lại hộ em xem chúng ta có sẵn sốt cà chua đông lạnh nào từ tuần trước không nhé?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Otherwise, I guess I could get some canned tomatoes.\", \"vi\": \"Nếu không, chắc em mua tạm cà chua đóng hộp vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Travis Farley (3:27 P.M.)\", \"vi\": \"Travis Farley (3:27 CH)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I’m afraid we are all out.\", \"vi\": \"Anh sợ là chúng ta hết sạch rồi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Let me speak to the chef.\", \"vi\": \"Để anh hỏi đầu bếp xem sao.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Lisa Dominguez (3:28 P.M.)\", \"vi\": \"Lisa Dominguez (3:28 CH)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"That would be great.\", \"vi\": \"Vậy thì tốt quá.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Travis Farley (3:32 P.M.)\", \"vi\": \"Travis Farley (3:32 CH)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"She says that you can pick up red peppers instead.\", \"vi\": \"Cô ấy bảo em có thể mua ớt chuông đỏ thay thế.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We will need to make a small change to the menu description, but the other ingredients can stay the same.\", \"vi\": \"Chúng ta sẽ cần điều chỉnh một chút trong phần mô tả thực đơn, nhưng các nguyên liệu khác vẫn giữ nguyên.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Lisa Dominguez (3:34 P.M.)\", \"vi\": \"Lisa Dominguez (3:34 CH)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Vâng.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I’ve got it.\", \"vi\": \"Em hiểu rồi.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thank you!\", \"vi\": \"Em cảm ơn!\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '095d6064-c261-4a3f-8c8c-174095f1b4f8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mei Kim (10:02 A.M.)\", \"vi\": \"Mei Kim (10:02 Sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Stan. Do you have lunch plans?\", \"vi\": \"Chào Stan. Bạn có kế hoạch đi ăn trưa chưa?\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Stan Snyder (10:05 A.M.)\", \"vi\": \"Stan Snyder (10:05 Sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I was just going to grab a sandwich from the company café and eat at my desk.\", \"vi\": \"Tôi định ra quán cà phê của công ty mua một cái bánh mì kẹp rồi ăn tại bàn làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Why do you ask?\", \"vi\": \"Sao bạn lại hỏi vậy?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Mei Kim (10:06 A.M.)\", \"vi\": \"Mei Kim (10:06 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"How about joining me at the Sunny Owl Restaurant?\", \"vi\": \"Hay là đi ăn cùng tôi ở Nhà hàng Sunny Owl nhé?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I\'d love to talk to you about the McMillan project before we meet with the client this afternoon.\", \"vi\": \"Tôi rất muốn bàn với bạn về dự án McMillan trước khi chúng ta gặp khách hàng vào chiều nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Stan Snyder (10:09 A.M.)\", \"vi\": \"Stan Snyder (10:09 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"That\'s a good idea.\", \"vi\": \"Đó là một ý kiến hay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I have some questions too—about the project\'s budget.\", \"vi\": \"Tôi cũng có vài thắc mắc về ngân sách của dự án.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Maybe we should ask Maria Trujillo to join us as well?\", \"vi\": \"Có lẽ chúng ta nên rủ cả Maria Trujillo đi cùng không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Mei Kim (10:10 A.M.)\", \"vi\": \"Mei Kim (10:10 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I\'ll handle it.\", \"vi\": \"Để tôi lo việc đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Shall we meet in the lobby at 11:45?\", \"vi\": \"Chúng ta gặp nhau ở sảnh lúc 11:45 nhé?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Stan Snyder (10:11 A.M.)\", \"vi\": \"Stan Snyder (10:11 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"That\'s perfect.\", \"vi\": \"Tuyệt quá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I\'ll see you then.\", \"vi\": \"Hẹn gặp bạn lúc đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '097f968f-9617-4a0e-ac2e-3f40c977b767';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Kristina Tursi <ktursi@fratellitursi.com>\", \"vi\": \"Đến: Kristina Tursi <ktursi@fratellitursi.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Steven Bracchio <sbracchio@worldsmail.net>\", \"vi\": \"Từ: Steven Bracchio <sbracchio@worldsmail.net>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: August 24\", \"vi\": \"Ngày: 24 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Thank you\", \"vi\": \"Chủ đề: Cảm ơn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Tursi,\", \"vi\": \"Kính gửi bà Tursi,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for your time today.\", \"vi\": \"Cảm ơn bà vì thời gian dành cho tôi ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I ______[139] enjoyed meeting and interviewing with your team.\", \"vi\": \"Tôi ______[139] rất thích thú khi được gặp gỡ và phỏng vấn với đội ngũ của công ty bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [139]}, {\"en\": \"It is clear to me that Fratelli Tursi is a dynamic company ______[140] for great success.\", \"vi\": \"Đối với tôi, rõ ràng Fratelli Tursi là một công ty năng động ______[140] để đạt được thành công lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [140]}, {\"en\": \"______[141].\", \"vi\": \"______[141].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [141]}, {\"en\": \"As we discussed, I am comfortable conducting business in the Italian language, and beyond that, I believe my marketing skills would strongly support Fratelli Tursi\'s efforts to grow internationally.\", \"vi\": \"Như chúng ta đã thảo luận, tôi cảm thấy thoải mái khi giao dịch kinh doanh bằng tiếng Ý, và hơn thế nữa, tôi tin rằng các kỹ năng tiếp thị của mình sẽ hỗ trợ mạnh mẽ cho nỗ lực phát triển vươn tầm quốc tế của Fratelli Tursi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I understand that the partners will be considering whom to call in to the office for ______[142] interviews.\", \"vi\": \"Tôi hiểu rằng các đối tác sẽ xem xét nên mời ai đến văn phòng để phỏng vấn ______[142].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [142]}, {\"en\": \"Please let me know if you require additional information about me.\", \"vi\": \"Xin vui lòng cho tôi biết nếu bà cần thêm thông tin gì về tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I very much look forward to hearing from you.\", \"vi\": \"Tôi rất mong sớm nhận được phản hồi từ bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Steven Bracchio\", \"vi\": \"Steven Bracchio\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '09d87eb8-d7a9-41be-9460-b26db9b4c628';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"15 October\", \"vi\": \"Ngày 15 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"GPO Box 985\", \"vi\": \"GPO Box 985\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"CANBERRA ACT 6512\", \"vi\": \"CANBERRA ACT 6512\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Dear Ms. Wilson,\", \"vi\": \"Kính gửi bà Wilson,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"On behalf of the Australia Wildlife Park Association, thank you for your donation of 40 AUD to our national park.\", \"vi\": \"Thay mặt cho Hiệp hội Công viên Động vật hoang dã Australia, cảm ơn quý vị vì khoản đóng góp 40 đô-la Australia cho công viên quốc gia của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[143].\", \"vi\": \"______[143].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [143]}, {\"en\": \"Individual contributions have helped it stay open to visitors for more than 50 years.\", \"vi\": \"Các khoản đóng góp cá nhân đã giúp nơi này tiếp tục mở cửa đón khách tham quan trong hơn 50 năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Our goal is to keep the park system running effectively for future ______[144] to enjoy.\", \"vi\": \"Mục tiêu của chúng tôi là duy trì hệ thống công viên hoạt động hiệu quả để các thế hệ ______[144] tương lai có thể tận hưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [144]}, {\"en\": \"Enclosed please find a copy of our brochure, which lists various programmes ______[145] to benefit both park visitors and our wildlife habitats.\", \"vi\": \"Đính kèm đây là một bản tài liệu quảng cáo của chúng tôi, liệt kê các chương trình khác nhau ______[145] nhằm mang lại lợi ích cho cả khách tham quan công viên lẫn môi trường sống của động vật hoang dã.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [145]}, {\"en\": \"Please consider ______[146] one of these programmes in the future.\", \"vi\": \"Xin hãy cân nhắc ______[146] một trong những chương trình này trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [146]}, {\"en\": \"The money would be used wisely and would be deeply appreciated.\", \"vi\": \"Số tiền này sẽ được sử dụng một cách khôn ngoan và chúng tôi vô cùng biết ơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Sincerely, Akosua Masika, Membership Chair\", \"vi\": \"Trân trọng, Akosua Masika, Trưởng ban Hội viên\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '09db6461-8bf2-4802-bb66-dcfb777154e2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Pedro Alamilla\", \"vi\": \"Đến: Pedro Alamilla\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Emma Golding\", \"vi\": \"Từ: Emma Golding\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 16 April\", \"vi\": \"Ngày: 16 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Labels\", \"vi\": \"Chủ đề: Nhãn dán\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Pedro,\", \"vi\": \"Pedro thân mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Per your request, below is the text for the labels for the new \\\"Think Green Paper\\\" line.\", \"vi\": \"Theo yêu cầu của bạn, dưới đây là phần nội dung văn bản cho nhãn dán của dòng sản phẩm giấy mới \\\"Think Green Paper\\\".\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The labels will be placed on the edge of the packaged reams of paper, so their size should not exceed 3 cm by 8 cm.\", \"vi\": \"Các nhãn dán sẽ được dán ở cạnh của các tập giấy đóng gói, vì vậy kích thước của chúng không được vượt quá 3 cm nhân 8 cm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The design should include the tree graphic we discussed yesterday.\", \"vi\": \"Thiết kế nên bao gồm hình ảnh đồ họa cây xanh mà chúng ta đã thảo luận ngày hôm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The text should read as follows:\", \"vi\": \"Nội dung văn bản nên được thể hiện như sau:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Think Green Paper\", \"vi\": \"Think Green Paper\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"100% from recycled products\", \"vi\": \"100% từ các sản phẩm tái chế\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"90 g/m2 bond\", \"vi\": \"Giấy viết chất lượng 90 g/m2\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Bright white\", \"vi\": \"Trắng sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please create a true-to-size and true-to-color sample version of the label by Wednesday, 21 April, and send it to the attention of my assistant, Dora Kensington.\", \"vi\": \"Vui lòng tạo một phiên bản mẫu của nhãn dán đúng kích thước và đúng màu sắc trước thứ Tư, ngày 21 tháng 4, và gửi nó cho trợ lý của tôi, Dora Kensington.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I will be out of the office on Wednesday, but I will review the sample and approve it as soon as I am back in the office on Thursday morning.\", \"vi\": \"Tôi sẽ vắng mặt ở văn phòng vào thứ Tư, nhưng tôi sẽ xem xét mẫu và phê duyệt ngay khi tôi quay lại văn phòng vào sáng thứ Năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Emma\", \"vi\": \"Emma\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '09df539d-9605-418c-bc9f-58c61b43b349';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"On Saturday, August 1, the Durhamtown Symphony Orchestra will be giving a free educational performance at the Cardona Culture Center, 498 Mahogany Ave. Among other things, the musicians will discuss the origins and development of their instruments as well as some musical styles.\", \"vi\": \"Vào thứ Bảy, ngày 1 tháng 8, Dàn nhạc Giao hưởng Durhamtown sẽ có một buổi biểu diễn giáo dục miễn phí tại Trung tâm Văn hóa Cardona, số 498 đại lộ Mahogany. Trong số các hoạt động khác, các nhạc công sẽ thảo luận về nguồn gốc và sự phát triển của các nhạc cụ của họ cũng như một số phong cách âm nhạc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Audience members will have an opportunity to ask questions.\", \"vi\": \"Khán giả sẽ có cơ hội đặt câu hỏi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The event will conclude with the orchestra performing works by some of today\'s well-known musicians and song writers.\", \"vi\": \"Sự kiện sẽ kết thúc bằng việc dàn nhạc biểu diễn các tác phẩm của một số nhạc sĩ và nhạc sĩ sáng tác nổi tiếng hiện nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}]' WHERE `id` = '09fc8542-64e6-48a2-bda1-ccdc7dda049c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Kate Millerson\", \"vi\": \"Đến: Kate Millerson\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Daniel Friedman\", \"vi\": \"Từ: Daniel Friedman\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: January 25\", \"vi\": \"Ngày: 25 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Upcoming focus group\", \"vi\": \"Chủ đề: Nhóm tập trung sắp tới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hi, Kate,\", \"vi\": \"Chào Kate,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The next focus group to test the new fruit-flavored beverage ideas will be held on February 1 in the Greenville office.\", \"vi\": \"Nhóm tập trung tiếp theo để thử nghiệm các ý tưởng đồ uống có hương vị trái cây mới sẽ được tổ chức vào ngày 1 tháng 2 tại văn phòng Greenville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Mari Kobayashi will be leading it.\", \"vi\": \"Mari Kobayashi sẽ phụ trách dẫn dắt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please design a questionnaire to collect the group\'s feedback using the one you created last month as a template and send it over to Mari.\", \"vi\": \"Vui lòng thiết kế một bảng câu hỏi để thu thập ý kiến đóng góp của nhóm bằng cách sử dụng bảng câu hỏi bạn đã tạo tháng trước làm mẫu và gửi cho Mari.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"After the focus group takes place, please tally the results in the form of a chart.\", \"vi\": \"Sau khi buổi nhóm tập trung diễn ra, vui lòng tổng hợp kết quả dưới dạng biểu đồ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I need to incorporate this information into my monthly report to the chief marketing officer.\", \"vi\": \"Tôi cần đưa thông tin này vào báo cáo hàng tháng gửi cho giám đốc tiếp thị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Daniel\", \"vi\": \"Daniel\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To: Daniel Friedman\", \"vi\": \"Đến: Daniel Friedman\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"From: Kate Millerson\", \"vi\": \"Từ: Kate Millerson\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date: February 3\", \"vi\": \"Ngày: 3 tháng 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Subject: Results of Greenville focus group\", \"vi\": \"Chủ đề: Kết quả của nhóm tập trung Greenville\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Greenville Results\", \"vi\": \"Đính kèm: 📎 Kết quả Greenville\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Hi, Daniel,\", \"vi\": \"Chào Daniel,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"According to Mari Kobayashi, 25 of the 30 registered participants for Greenville took the taste test and completed the questionnaire.\", \"vi\": \"Theo Mari Kobayashi, 25 trong số 30 người tham gia đã đăng ký ở Greenville đã tham gia bài kiểm tra vị giác và hoàn thành bảng câu hỏi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"The results are mostly in line with the results from last month\'s focus group.\", \"vi\": \"Kết quả hầu như tương đồng với kết quả từ nhóm tập trung của tháng trước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"However, Mari did note that the Greenville group\'s most popular flavor was unexpected.\", \"vi\": \"Tuy nhiên, Mari đã lưu ý rằng hương vị được ưa chuộng nhất của nhóm Greenville lại là một điều bất ngờ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Per your request, the tabulated results are attached.\", \"vi\": \"Theo yêu cầu của bạn, kết quả được lập bảng đã được đính kèm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Please let me know if you will need additional information for your report to Ms. Acosta or if she wants to see the comments on the questionnaires.\", \"vi\": \"Vui lòng cho tôi biết nếu bạn cần thêm thông tin cho báo cáo gửi cho cô Acosta hoặc nếu cô ấy muốn xem các ý kiến đóng góp trên bảng câu hỏi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Kate\", \"vi\": \"Kate\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Type of drink: - Carbonated (8) - Noncarbonated (17)\", \"vi\": \"Loại đồ uống: - Có ga (8) - Không có ga (17)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Highest price willing to pay: - $1.25 (5)    $1.50 (12) - $2.00 (5)    $2.50 (3)\", \"vi\": \"Mức giá cao nhất sẵn sàng trả: - $1,25 (5)   $1,50 (12) - $2,00 (5)   $2,50 (3)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Flavor: - Cherry (2)    Lemon (7) - Lime (13)    Orange (3)\", \"vi\": \"Hương vị: - Anh đào (2)   Chanh vàng (7) - Chanh xanh (13)   Cam (3)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"GREENVILLE FOCUS GROUP\", \"vi\": \"NHÓM TẬP TRUNG GREENVILLE\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"February 1\", \"vi\": \"Ngày 1 tháng 2\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"(Numbers indicate how many participants preferred each option.)\", \"vi\": \"(Các con số cho biết có bao nhiêu người tham gia thích mỗi lựa chọn.)\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}]' WHERE `id` = '0a461409-d095-405e-8944-41eaacf9b5e3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Sedwick Electronics Hiring Event\", \"vi\": \"Sự kiện tuyển dụng của Sedwick Electronics\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"March 2, 10 A.M.–5 P.M.\", \"vi\": \"Ngày 2 tháng 3, từ 10 giờ sáng đến 5 giờ chiều\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"22 Myer Street, Hanover, PA 17331\", \"vi\": \"22 Phố Myer, Hanover, PA 17331\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Sedwick Electronics is opening a new manufacturing facility in Hanover, Pennsylvania, and we need to fill many positions.\", \"vi\": \"Sedwick Electronics đang mở một cơ sở sản xuất mới tại Hanover, Pennsylvania, và chúng tôi cần tuyển dụng cho nhiều vị trí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We offer a wonderful work environment and great benefits to our employees.\", \"vi\": \"Chúng tôi cung cấp một môi trường làm việc tuyệt vời và các phúc lợi hấp dẫn cho nhân viên của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Come to the event and hear from employees from our Lancaster facility about their experience, learn about the open positions, and speak with our recruiters.\", \"vi\": \"Hãy đến tham gia sự kiện và lắng nghe chia sẻ từ các nhân viên tại cơ sở Lancaster của chúng tôi về trải nghiệm của họ, tìm hiểu về các vị trí đang tuyển dụng, và trò chuyện với các nhà tuyển dụng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"No RSVP is necessary.\", \"vi\": \"Không cần đăng ký trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Bring copies of your résumé.\", \"vi\": \"Hãy mang theo các bản sơ yếu lý lịch của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '0a5f1c7e-a8d0-4bf6-a3aa-b7d6b8f760fc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Senior executive staff\", \"vi\": \"Đến: Ban điều hành cấp cao\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Seok Kang\", \"vi\": \"Từ: Seok Kang\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 15 September\", \"vi\": \"Ngày: 15 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: App update\", \"vi\": \"Chủ đề: Cập nhật ứng dụng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: App_specs; Press_release\", \"vi\": \"Đính kèm: Thong_so_ung_dung; Thong_cao_bao_chi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As you all know, to coincide with the upcoming launch of the restaurant\'s new menu, we have made several changes to our mobile app.\", \"vi\": \"Như tất cả các bạn đã biết, để trùng với thời điểm ra mắt thực đơn mới sắp tới của nhà hàng, chúng tôi đã thực hiện một số thay đổi đối với ứng dụng di động của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"------- (139), we have corrected several issues with the previous version.\", \"vi\": \"------- (139), chúng tôi đã khắc phục một số vấn đề của phiên bản trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [139]}, {\"en\": \"------- (140).\", \"vi\": \"------- (140).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [140]}, {\"en\": \"I am delighted to report that our focus group members gave the redesigned app great reviews.\", \"vi\": \"Tôi rất vui mừng thông báo rằng các thành viên nhóm tập trung của chúng tôi đã đánh giá rất cao ứng dụng được thiết kế lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In particular, ------- (141) commented on how simple it is to use the different features.\", \"vi\": \"Đặc biệt, ------- (141) đã nhận xét về mức độ đơn giản khi sử dụng các tính năng khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [141]}, {\"en\": \"I have attached the app\'s specifications and a draft of the press release to this e-mail.\", \"vi\": \"Tôi đã đính kèm thông số kỹ thuật của ứng dụng và bản nháp thông cáo báo chí vào email này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"If you have any questions or suggestions, please let me know by 17 September.\", \"vi\": \"Nếu bạn có bất kỳ câu hỏi hoặc đề xuất nào, vui lòng cho tôi biết trước ngày 17 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The official launch for the app and menu ------- (142) on Thursday, 25 September.\", \"vi\": \"Lễ ra mắt chính thức cho ứng dụng và thực đơn ------- (142) vào thứ Năm, ngày 25 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [142]}]' WHERE `id` = '0a8a850c-3eea-4b81-a83a-e0bbdb628a5c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Sehelec Announces Wind-Solar Hybrid Project\", \"vi\": \"Sehelec Công Bố Dự Án Năng Lượng Lai Gió - Mặt Trời\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"MUMBAI (15 March)—Sehelec Ltd. announced it will begin construction on a 500-megawatt wind-solar hybrid power ___143___ outside of Bangalore, India.\", \"vi\": \"MUMBAI (Ngày 15 tháng 3)—Công ty TNHH Sehelec thông báo họ sẽ bắt đầu thi công một dự án điện lai gió - mặt trời công suất 500 megawatt ___143___ bên ngoài thành phố Bangalore, Ấn Độ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [143]}, {\"en\": \"___144___.\", \"vi\": \"___144___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [144]}, {\"en\": \"Sehelec expects to begin operations within 24 months, and it will sell the power to Indian energy giant Novaseon Industries.\", \"vi\": \"Sehelec dự kiến bắt đầu hoạt động trong vòng 24 tháng và sẽ bán điện cho tập đoàn năng lượng lớn của Ấn Độ Novaseon Industries.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"Our contract with Novaseon to provide ___145___ power moves us closer to our long-term corporate goal,\\\" said Sumit Varma, CEO of Sehelec.\", \"vi\": \"\\\"Hợp đồng của chúng tôi với Novaseon nhằm cung cấp nguồn điện ___145___ giúp chúng tôi tiếnใกล้ hơn tới mục tiêu dài hạn của công ty,\\\" Sumit Varma, Giám đốc điều hành của Sehelec cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [145]}, {\"en\": \"\\\"Our objective is to achieve a capacity of 20 gigawatts within five years.\", \"vi\": \"\\\"Mục tiêu của chúng tôi là đạt được công suất 20 gigawatt trong vòng năm năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Doing so will make us one of India\'s largest green power companies.\", \"vi\": \"Làm như vậy sẽ biến chúng tôi thành một trong những công ty năng lượng xanh lớn nhất Ấn Độ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"And that, in turn, will help the country ___146___ its carbon-reduction target.\\\"\", \"vi\": \"Và điều đó, đổi lại, sẽ giúp đất nước ___146___ mục tiêu giảm phát thải carbon của mình.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [146]}]' WHERE `id` = '0ac01cff-b5c6-4082-8b7d-d3dfe8622ec3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: vendors@grovecenterfleamarket.org\", \"vi\": \"Đến: vendors@grovecenterfleamarket.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: alanc@spicebest.com\", \"vi\": \"Từ: alanc@spicebest.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: October 22\", \"vi\": \"Ngày: 22 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Parking issue\", \"vi\": \"Chủ đề: Vấn đề đậu xe\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Vendors,\", \"vi\": \"Kính gửi các nhà cung cấp,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Starting next month, the owners of the Grove Center Flea Market will charge a flat daily rate of $10 to use the onsite parking deck.\", \"vi\": \"Bắt đầu từ tháng tới, chủ sở hữu của Chợ phiên Grove Center sẽ tính mức phí cố định hàng ngày là 10 đô la để sử dụng khu vực đậu xe trong khuôn viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This means customers who drive to our weekly flea market will no longer enjoy free parking.\", \"vi\": \"Điều này có nghĩa là những khách hàng lái xe đến chợ phiên hàng tuần của chúng ta sẽ không còn được hưởng quyền lợi đậu xe miễn phí nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I\'m concerned that this might ___139___ some shoppers from coming, which will hurt our businesses.\", \"vi\": \"Tôi lo ngại rằng điều này có thể ___139___ một số người mua sắm đến chợ, điều này sẽ làm tổn hại đến việc kinh doanh của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [139]}, {\"en\": \"As president of the Grove Center Flea Market, I have asked the owners to consider waiving or reducing the fee.\", \"vi\": \"Với tư cách là chủ tịch của Chợ phiên Grove Center, tôi đã yêu cầu các chủ sở hữu xem xét việc miễn hoặc giảm phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"___140___ .\", \"vi\": \"___140___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [140]}, {\"en\": \"The nearest other large-scale parking facility is at city hall, three long blocks from our site.\", \"vi\": \"Bãi đậu xe quy mô lớn khác gần nhất nằm ở tòa nhà thành phố, cách địa điểm của chúng ta ba dãy nhà dài.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Street parking is available but can be ___141___ to find.\", \"vi\": \"Việc đậu xe trên đường phố có sẵn nhưng có thể sẽ ___141___ để tìm kiếm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [141]}, {\"en\": \"Please reply to all if you have any thoughts on alternative ___142___ .\", \"vi\": \"Vui lòng trả lời tất cả (reply to all) nếu bạn có bất kỳ ý kiến nào về các ___142___ thay thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [142]}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Alan Coleman\", \"vi\": \"Alan Coleman\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '0ac2ea60-6fe7-4dd4-8a73-403e093539ce';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"With Global Strength Gym\'s 30-day trial period, you get the opportunity to try out our classes, equipment, and facilities.\", \"vi\": \"Với thời gian dùng thử 30 ngày của Global Strength Gym, bạn có cơ hội trải nghiệm các lớp học, trang thiết bị và cơ sở vật chất của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"______[131].\", \"vi\": \"______[131].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"It\'s completely risk-free!\", \"vi\": \"Hoàn toàn không có rủi ro!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"To sign up, we require your contact information and payment details, but you will only be charged if you are a member for ______[132] 30 days.\", \"vi\": \"Để đăng ký, chúng tôi yêu cầu thông tin liên hệ và chi tiết thanh toán của bạn, nhưng bạn sẽ chỉ bị tính phí nếu bạn là thành viên trong ______[132] 30 ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [132]}, {\"en\": \"If you decide within this time that you no longer want to be a member of Global Strength, ______[133] visit our Web site at www.gsgym.com.\", \"vi\": \"Nếu bạn quyết định trong khoảng thời gian này rằng bạn không còn muốn làm thành viên của Global Strength nữa, ______[133] hãy truy cập trang web của chúng tôi tại www.gsgym.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [133]}, {\"en\": \"On the Membership page, elect to ______[134] your membership and enter the necessary information.\", \"vi\": \"Trên trang Thành viên, hãy chọn ______[134] tư cách thành viên của bạn và nhập thông tin cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [134]}, {\"en\": \"It\'s that easy!\", \"vi\": \"Thật dễ dàng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '0b161eb0-a3bc-410c-bf1f-6d564ba23446';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Darway City Park Project Updates\", \"vi\": \"Cập nhật Dự án Công viên Thành phố Darway\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Darway City Park management strives to keep all visitor trails ___131___ while improvement projects are underway.\", \"vi\": \"Ban quản lý Công viên Thành phố Darway luôn nỗ lực giữ cho tất cả các lối đi dành cho khách tham quan luôn ___131___ trong khi các dự án cải tạo đang được tiến hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"Currently, crews are trimming vegetation around directional signs along the park’s Woodmor bike path, so cyclists should ride carefully in this area.\", \"vi\": \"Hiện tại, các đội thi công đang cắt tỉa thảm thực vật quanh các biển báo chỉ dẫn dọc theo đường xe đạp Woodmor của công viên, vì vậy người đi xe đạp nên lái xe cẩn thận trong khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Note that ___132___ possible, renovation work is scheduled to take place during off-peak times because fewer people use the park then.\", \"vi\": \"Lưu ý rằng ___132___ có thể, công việc cải tạo được lên lịch diễn ra vào thời gian ít cao điểm vì khi đó ít người sử dụng công viên hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [132]}, {\"en\": \"New informational signs that highlight specific features of the surrounding natural environment will also be installed along sections of the trail.\", \"vi\": \"Các biển báo thông tin mới làm nổi bật các đặc điểm cụ thể của môi trường tự nhiên xung quanh cũng sẽ được lắp đặt dọc theo các đoạn đường mòn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"___133___ .\", \"vi\": \"___133___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [133]}, {\"en\": \"This phase of the project will be completed next month, and there is expected to be little ___134___ to park users as it progresses.\", \"vi\": \"Giai đoạn này của dự án sẽ được hoàn thành vào tháng tới và dự kiến sẽ có ít ___134___ đối với những người sử dụng công viên khi dự án tiến triển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [134]}, {\"en\": \"The city’s Department of Parks makes every effort to avoid trail closures and detours during work projects.\", \"vi\": \"Sở Công viên của thành phố nỗ lực hết sức để tránh việc đóng cửa đường mòn và chuyển hướng đi trong các dự án thi công.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '0b4e4ca8-3fb1-4b46-897c-6272f9eeae5f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Improve Your Office Environment Now!\", \"vi\": \"Hãy Cải Thiện Môi Trường Văn Phòng Của Bạn Ngay Bây Giờ!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Alberta Business Matters\", \"vi\": \"Tạp chí Alberta Business Matters\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"April issue\", \"vi\": \"Số tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Today\'s office environment, featuring numerous corridors, unexciting beige or white walls, and often rows of identical, windowless cubicles, might not inspire comfort, beauty, and energy.\", \"vi\": \"Môi trường văn phòng ngày nay, với nhiều hành lang, những bức tường màu be hoặc trắng tẻ nhạt, và thường là các hàng ô làm việc giống hệt nhau, không có cửa sổ, có thể không mang lại sự thoải mái, vẻ đẹp và năng lượng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"However, there are some easy, inexpensive ways to make your office space more inviting.\", \"vi\": \"Tuy nhiên, có một số cách dễ dàng và không tốn kém để làm cho không gian văn phòng của bạn trở nên hấp dẫn hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Air quality\", \"vi\": \"Chất lượng không khí\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Add some green plants to the décor.\", \"vi\": \"Thêm một số cây xanh vào cách bài trí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Plants offer a natural filtration system, increasing oxygen levels.\", \"vi\": \"Cây xanh cung cấp hệ thống lọc tự nhiên, giúp tăng lượng oxy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Nonflowering plants should be preferred, as they will not scatter pollen.\", \"vi\": \"Nên ưu tiên các loại cây không ra hoa vì chúng sẽ không phát tán phấn hoa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"A small, tabletop air purifier helps improve stale air and removes dust.\", \"vi\": \"Một chiếc máy lọc không khí để bàn nhỏ giúp cải thiện không khí tù đọng và loại bỏ bụi bẩn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Light quality\", \"vi\": \"Chất lượng ánh sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Take breaks and go outdoors.\", \"vi\": \"Hãy nghỉ giải lao và đi ra ngoài trời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Even just five minutes before or after lunch break will provide your eyes with a respite from artificial light sources.\", \"vi\": \"Chỉ cần năm phút trước hoặc sau giờ nghỉ trưa cũng sẽ giúp đôi mắt của bạn có thời gian nghỉ ngơi khỏi các nguồn sáng nhân tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Use desktop lamps with full-spectrum lightbulbs.\", \"vi\": \"Sử dụng đèn để bàn với bóng đèn quang phổ đầy đủ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Install double-glazed windows instead of blinds to reduce glare while maintaining natural light.\", \"vi\": \"Lắp đặt cửa sổ hai lớp thay vì rèm cửa để giảm chói mắt trong khi vẫn duy trì ánh sáng tự nhiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Stress relief\", \"vi\": \"Giảm căng thẳng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Earplugs or noise-cancelling headphones can block distracting noise in an open office floor plan.\", \"vi\": \"Nút bịt tai hoặc tai nghe chống ồn có thể chặn tiếng ồn gây xao nhãng trong thiết kế văn phòng không gian mở.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Photographs of loved ones and places we have visited for vacation are reminders of our life away from the office.\", \"vi\": \"Những bức ảnh về những người thân yêu và những nơi chúng ta từng đến nghỉ mát là những lời nhắc nhở về cuộc sống của chúng ta ngoài văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Select a few favorite pictures as important decorative elements.\", \"vi\": \"Hãy chọn một vài bức ảnh yêu thích làm yếu tố trang trí quan trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Dear readers, if you have tips to add to this list, send them in and they will be published in next month\'s issue.\", \"vi\": \"Kính gửi quý độc giả, nếu bạn có các mẹo muốn bổ sung vào danh sách này, hãy gửi đến chúng tôi và chúng sẽ được đăng trong số báo của tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Letters to the Editor\", \"vi\": \"Thư gửi Tòa soạn\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Alberta Business Matters\", \"vi\": \"Tạp chí Alberta Business Matters\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"It may interest your readers to know about the company I work for, called Moveable, Inc. We aspire to make dull offices more comfortable and convenient for workers, especially for today\'s on-the-move employees.\", \"vi\": \"Bạn đọc có thể quan tâm khi biết về công ty tôi đang làm việc, có tên là Moveable, Inc. Chúng tôi mong muốn làm cho các văn phòng tẻ nhạt trở nên thoải mái và tiện lợi hơn cho người lao động, đặc biệt là đối với nhân viên năng động ngày nay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"For example, say you work two days a week at your headquarters in Edmonton, and the rest of the week you are in a satellite office.\", \"vi\": \"Ví dụ, giả sử bạn làm việc hai ngày một tuần tại trụ sở chính ở Edmonton, và phần còn lại của tuần bạn ở văn phòng vệ tinh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Our \\\"Can-Do Case\\\" ensures that your favorite office supplies always travel with you.\", \"vi\": \"Chiếc \\\"Can-Do Case\\\" của chúng tôi đảm bảo rằng các vật dụng văn phòng yêu thích của bạn luôn đồng hành cùng bạn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Our \\\"Modular Décor Kit,\\\" weighing just 1.75 kg, contains a portable reading lamp, a miniature silk plant, and a folding photo frame with space for four pictures.\", \"vi\": \"\\\"Bộ trang trí mô-đun\\\" của chúng tôi, nặng chỉ 1,75 kg, bao gồm một đèn đọc sách di động, một chậu cây lụa thu nhỏ và một khung ảnh gấp có không gian cho bốn bức ảnh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Look us up online and follow us on social media, as we offer new items frequently!\", \"vi\": \"Hãy tìm kiếm chúng tôi trực tuyến và theo dõi chúng tôi trên mạng xã hội, vì chúng tôi thường xuyên cung cấp các mặt hàng mới!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Thân ái,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Maria Testa\", \"vi\": \"Maria Testa\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}]' WHERE `id` = '0b7e2a87-9a8b-430b-9f89-8c69f6831952';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Gallery manager at Richard Lahiri Gallery in Cromwood\", \"vi\": \"Quản lý phòng tranh tại Richard Lahiri Gallery ở Cromwood\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Applicants for this full-time position must have experience in retail art with an established history of successfully attracting patrons interested in purchasing original works of art.\", \"vi\": \"Các ứng viên cho vị trí toàn thời gian này phải có kinh nghiệm kinh doanh nghệ thuật bán lẻ với bề dày thành tích trong việc thu hút thành công khách hàng quan tâm đến việc mua các tác phẩm nghệ thuật gốc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Experience managing a social media account is also desired.\", \"vi\": \"Kinh nghiệm quản lý tài khoản mạng xã hội cũng là một lợi thế mong muốn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The position will be primarily on-site; however, some remote hours can be scheduled.\", \"vi\": \"Vị trí này chủ yếu làm việc trực tiếp tại văn phòng; tuy nhiên, một số giờ làm việc từ xa có thể được sắp xếp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Candidates must be available to start work on or before April 1.\", \"vi\": \"Ứng viên phải có khả năng bắt đầu làm việc vào hoặc trước ngày 1 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Qualified applicants should contact gallery director Richard Lahiri at rlahiri@richardlahirigallery.com.\", \"vi\": \"Các ứng viên đủ điều kiện nên liên hệ với giám đốc phòng tranh Richard Lahiri tại địa chỉ rlahiri@richardlahirigallery.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Summer Scene Arts Program\", \"vi\": \"Chương trình Nghệ thuật Cảnh Mùa hè\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Starting on May 1, five art galleries in Cromwood will be hosting open houses every Friday from May through August.\", \"vi\": \"Bắt đầu từ ngày 1 tháng 5, năm phòng tranh ở Cromwood sẽ tổ chức ngày hội tham quan mở cửa vào mỗi thứ Sáu từ tháng 5 đến tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Come enjoy live music, refreshments, artist talks, and more on the Cromwood boardwalk.\", \"vi\": \"Hãy đến thưởng thức âm nhạc sống, đồ ăn thức uống nhẹ, các buổi trò chuyện với nghệ sĩ và nhiều hoạt động khác trên lối đi dạo ven biển Cromwood.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Activities start at 4:00 P.M. and continue until 9:30 P.M., rain or shine.\", \"vi\": \"Các hoạt động bắt đầu lúc 4:00 chiều và kéo dài cho đến 9:30 tối, dù trời mưa hay nắng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Participating galleries are listed below.\", \"vi\": \"Các phòng tranh tham gia được liệt kê bên dưới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Rita Blake Art • Siitva Gallery • Richard Lahiri Gallery\", \"vi\": \"Rita Blake Art • Siitva Gallery • Richard Lahiri Gallery\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Patricia Dolivo Painting • Ashland Pottery and Crafts\", \"vi\": \"Patricia Dolivo Painting • Ashland Pottery and Crafts\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Funded by the Cromwood City Council and Regents Bank\", \"vi\": \"Được tài trợ bởi Hội đồng Thành phố Cromwood và Ngân hàng Regents\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Summer Activities in Middleton County\", \"vi\": \"Các hoạt động mùa hè tại hạt Middleton\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Compiled by Lisa Yu-Seaver\", \"vi\": \"Được tổng hợp bởi Lisa Yu-Seaver\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Cromwood Art Nights\", \"vi\": \"Đêm nghệ thuật Cromwood\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Residents of Elmhurst, Melbridge, and Cromwood are invited to explore the local art scene in Cromwood this summer.\", \"vi\": \"Cư dân của Elmhurst, Melbridge và Cromwood được mời khám phá nền nghệ thuật địa phương tại Cromwood vào mùa hè này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The five galleries on the boardwalk overlooking the Wye River are holding special events each Friday as part of the Summer Scene Arts Program.\", \"vi\": \"Năm phòng tranh trên lối đi dạo nhìn ra sông Wye đang tổ chức các sự kiện đặc biệt vào mỗi thứ Sáu như một phần của Chương trình Nghệ thuật Cảnh Mùa hè.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"This Friday, Richard Lahiri and his gallery manager, Geetu Gelang, will use a giant screen to demonstrate software for creating virtual art.\", \"vi\": \"Thứ Sáu này, Richard Lahiri và người quản lý phòng tranh của ông, Geetu Gelang, sẽ sử dụng một màn hình khổng lồ để biểu diễn phần mềm tạo ra nghệ thuật ảo.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"The event will also feature craft vendors, food trucks, and live music.\", \"vi\": \"Sự kiện cũng sẽ có sự góp mặt của các nhà cung cấp đồ thủ công, xe bán đồ ăn lưu động và âm nhạc sống.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"See www.cromwood.gov/things-to-do for more information.\", \"vi\": \"Xem trang web www.cromwood.gov/things-to-do để biết thêm thông tin.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Movies in Brady Park\", \"vi\": \"Phim chiếu tại Công viên Brady\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"The popular summer movie series in Herrontown returns on June 16!\", \"vi\": \"Chuỗi phim mùa hè phổ biến tại Herrontown sẽ quay trở lại vào ngày 16 tháng 6!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Each Saturday evening, a classic film will be projected on Brady Park’s Grand Lawn.\", \"vi\": \"Vào mỗi tối thứ Sáu, một bộ phim kinh điển sẽ được chiếu trên Bãi cỏ lớn của Công viên Brady.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Bring your picnic basket and a blanket and get comfortable!\", \"vi\": \"Hãy mang theo giỏ dã ngoại và một chiếc chăn để tận hưởng sự thoải mái!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"The schedule of films is available at www.bradypark.org/activities.\", \"vi\": \"Lịch chiếu phim có sẵn tại www.bradypark.org/activities.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '0b982d49-755e-4e55-aa5e-4cb4b865d57b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Madalyn Kerluke <mkerluke@karabel.ca>\", \"vi\": \"Từ: Madalyn Kerluke <mkerluke@karabel.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Omar Niklaus <oniklaus@karabel.ca>, Jay Toncic <jtoncic@karabel.ca>\", \"vi\": \"Đến: Omar Niklaus <oniklaus@karabel.ca>, Jay Toncic <jtoncic@karabel.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: Friday, 3 February 2:16 P.M.\", \"vi\": \"Ngày: Thứ Sáu, ngày 3 tháng 2, 2:16 chiều\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Taste-test results\", \"vi\": \"Chủ đề: Kết quả dùng thử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Fatior Labs survey results\", \"vi\": \"Tệp đính kèm: 📎 Kết quả khảo sát của Fatior Labs\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Hi, Team.\", \"vi\": \"Chào cả đội.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I just received the 24–26 January survey results from Fatior Labs for our new ice-cream taste test.\", \"vi\": \"Tôi vừa nhận được kết quả khảo sát từ ngày 24–26 tháng 1 từ Fatior Labs cho cuộc thử nghiệm hương vị kem mới của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As you can see from the attached document, the results are very disappointing.\", \"vi\": \"Như các bạn có thể thấy từ tài liệu đính kèm, kết quả rất đáng thất vọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We sent the four flavours that we considered to be the best, but none of them received high enough ratings to advance to the next stage of development.\", \"vi\": \"Chúng ta đã gửi bốn hương vị mà chúng ta cho là ngon nhất, nhưng không có hương vị nào nhận được điểm đánh giá đủ cao để tiến vào giai đoạn phát triển tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Most of the reviews were consistent among the 92 taste-test participants in our target market of consumers ages 25 through 40.\", \"vi\": \"Hầu hết các đánh giá đều đồng nhất giữa 92 người tham gia dùng thử thuộc thị trường mục tiêu của chúng ta là người tiêu dùng từ 25 đến 40 tuổi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"It\'s not a big problem if a product gets low scores in colour in the testing phase, since we can easily adjust that in the laboratory.\", \"vi\": \"Không phải là vấn đề lớn nếu một sản phẩm đạt điểm thấp về màu sắc trong giai đoạn thử nghiệm, vì chúng ta có thể dễ dàng điều chỉnh điều đó trong phòng thí nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"But we should never be sending out samples that are getting scores lower than 3 in the taste category.\", \"vi\": \"Nhưng chúng ta tuyệt đối không bao giờ được gửi đi các mẫu đạt điểm thấp hơn 3 ở danh mục hương vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I would like to meet at 9 A.M. on Monday (6 February) to figure out how to proceed.\", \"vi\": \"Tôi muốn chúng ta họp lúc 9 giờ sáng thứ Hai (ngày 6 tháng 2) để tìm ra cách tiến hành tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"There is one flavour we may be able to work with if we make a few adjustments, as suggested by most of our taste testers.\", \"vi\": \"Có một hương vị mà chúng ta có thể phát triển tiếp nếu thực hiện một vài điều chỉnh, theo đề xuất của phần lớn những người tham gia dùng thử.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We will also need to get some new flavours to Fatior Labs no later than 1 March if we are going to get a new ice cream on the Preston Grocers freezer shelves by the beginning of June.\", \"vi\": \"Chúng ta cũng cần gửi một số hương vị mới đến Fatior Labs chậm nhất vào ngày 1 tháng 3 nếu chúng ta muốn đưa một loại kem mới lên các kệ tủ đông của Preston Grocers trước đầu tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Madalyn Kerluke\", \"vi\": \"Madalyn Kerluke\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Flavour - Taste - Texture - Sweetness - Colour\", \"vi\": \"Hương vị - Vị - Kết cấu - Độ ngọt - Màu sắc\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Lemon - 2 - 3 - 2 - 4\", \"vi\": \"Chanh - 2 - 3 - 2 - 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Mango - 3 - 3 - 2 - 1\", \"vi\": \"Xoài - 3 - 3 - 2 - 1\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Salted Caramel - 2 - 1 - 1 - 5\", \"vi\": \"Karamel Muối - 2 - 1 - 1 - 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Peanut Brittle - 3 - 4 - 2 - 2\", \"vi\": \"Kẹo Đậu Phộng Giòn - 3 - 4 - 2 - 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Fatior Labs Consumer Taste-Testing Survey\", \"vi\": \"Khảo sát Thử nghiệm Hương vị Người tiêu dùng của Fatior Labs\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Date: 24 January\", \"vi\": \"Ngày: 24 tháng 1\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Company: Karabel Industries\", \"vi\": \"Công ty: Karabel Industries\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Participant number: 54\", \"vi\": \"Số người tham gia: 54\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Directions: You will be given a 45 g sample of 4 different ice creams.\", \"vi\": \"Hướng dẫn: Bạn sẽ được cung cấp một mẫu 45 g của 4 loại kem khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Please rate the taste, texture, sweetness, and colour of each ice cream on a scale of 1 (very unpleasant) to 5 (very pleasant).\", \"vi\": \"Vui lòng đánh giá hương vị, kết cấu, độ ngọt và màu sắc của từng loại kem theo thang điểm từ 1 (rất khó chịu) đến 5 (rất dễ chịu).\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Please write any additional comments below.\", \"vi\": \"Vui lòng viết bất kỳ nhận xét bổ sung nào bên dưới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Comments: The fruit-flavoured ice creams were surprisingly sour.\", \"vi\": \"Nhận xét: Các loại kem có hương vị trái cây có vị chua đến ngạc nhiên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I did not care for them\", \"vi\": \"Tôi không hề thích chúng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"at all.\", \"vi\": \"chút nào.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I think the Peanut Brittle has the most potential, but it\'s missing something.\", \"vi\": \"Tôi nghĩ vị Kẹo Đậu Phộng Giòn có nhiều tiềm năng nhất, nhưng nó còn thiếu một thứ gì đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I bet\", \"vi\": \"Tôi cá là\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"that adding chocolate swirls or brownie bits would make it a winner.\", \"vi\": \"việc thêm các đường xoắn sô-cô-la hoặc vụn bánh brownie sẽ biến nó thành một sản phẩm thành công.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '0ba09de3-b51c-411e-8906-e1ecacb76872';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"The Mayan Joy Cocoa Process\", \"vi\": \"Quy trình sản xuất ca cao Mayan Joy\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From our organic fields to your kitchen table!\", \"vi\": \"Từ các nông trại hữu cơ của chúng tôi đến bàn ăn nhà bạn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"1.\", \"vi\": \"1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We plant and cultivate the seeds following ancient traditions.\", \"vi\": \"Chúng tôi gieo trồng và chăm sóc hạt theo các truyền thống cổ xưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"↓\", \"vi\": \"↓\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"2.\", \"vi\": \"2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We dry, clean, and prepare the seeds naturally.\", \"vi\": \"Chúng tôi phơi khô, làm sạch và sơ chế hạt một cách tự nhiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"↓\", \"vi\": \"↓\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"3.\", \"vi\": \"3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We toast the cocoa beans and remove the shells by hand.\", \"vi\": \"Chúng tôi rang hạt ca cao và bóc vỏ bằng tay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"↓\", \"vi\": \"↓\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"4.\", \"vi\": \"4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We grind the shelled beans to produce 100% pure cocoa powder.\", \"vi\": \"Chúng tôi nghiền các hạt đã bóc vỏ để tạo ra bột ca cao nguyên chất 100%.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"↓\", \"vi\": \"↓\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"5.\", \"vi\": \"5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"YOU enjoy our Mexican cocoa, a rich, sensational, delicious superfood!\", \"vi\": \"BẠN thưởng thức ca cao Mexico của chúng tôi, một loại siêu thực phẩm đậm đà, tuyệt vời và ngon miệng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Mayan Joy Cocoa\", \"vi\": \"Ca cao Mayan Joy\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Av Tulum Plaza Galerias\", \"vi\": \"Av Tulum Plaza Galerias\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Cancun, Quintana Roo 97655\", \"vi\": \"Cancun, Quintana Roo 97655\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Mexico\", \"vi\": \"Mexico\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"March 24\", \"vi\": \"Ngày 24 tháng 3\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"James Grigio\", \"vi\": \"James Grigio\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"39 Lansford Lane\", \"vi\": \"39 Lansford Lane\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Valley Falls, Kansas 66088\", \"vi\": \"Valley Falls, Kansas 66088\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"United States\", \"vi\": \"Hoa Kỳ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Mayan Joy Cocoa Representative:\", \"vi\": \"Kính gửi Đại diện Ca cao Mayan Joy:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"When I was recently in Mexico, I purchased a block of your fine cocoa.\", \"vi\": \"Khi tôi ở Mexico gần đây, tôi đã mua một khối ca cao hảo hạng của các bạn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"It was the best I ever had!\", \"vi\": \"Đó là loại ngon nhất mà tôi từng dùng!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I did some research on your products, and I was very impressed with your process.\", \"vi\": \"Tôi đã tìm hiểu thêm về các sản phẩm của các bạn, và tôi rất ấn tượng với quy trình sản xuất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I especially appreciate that your workers take care to remove the shells from the beans by hand.\", \"vi\": \"Tôi đặc biệt đánh giá cao việc công nhân của các bạn cẩn thận bóc vỏ hạt bằng tay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I would like to purchase some more to make my own chocolates at home.\", \"vi\": \"Tôi muốn mua thêm một ít để tự làm sô-cô-la tại nhà.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Please send me information and pricing.\", \"vi\": \"Vui lòng gửi cho tôi thông tin và bảng giá.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I would prefer to purchase a one-pound block of pure, unsweetened Yucatan cocoa.\", \"vi\": \"Tôi muốn mua một khối ca cao Yucatan nguyên chất, không đường nặng một pao.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"I will be sweetening the candy myself, so I am not looking for sweetened cocoa.\", \"vi\": \"Tôi sẽ tự làm ngọt kẹo, nên tôi không tìm kiếm loại ca cao đã pha đường.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Xin cảm ơn.\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"James Grigio\", \"vi\": \"James Grigio\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"James Grigio\", \"vi\": \"James Grigio\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"House Blend - Artisan Block - Block Gift - Mountain Bag\", \"vi\": \"Hỗn hợp truyền thống - Khối thủ công - Khối quà tặng - Túi vùng núi\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Half-pound bag $25 - 1 pound $40 - 2 pounds $98 - 1 pound $65\", \"vi\": \"Túi nửa pao $25 - 1 pao $40 - 2 pao $98 - 1 pao $65\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Item: D-23 - Item: C-100 - Item: C-200 - Item: M-42\", \"vi\": \"Mặt hàng: D-23 - Mặt hàng: C-100 - Mặt hàng: C-200 - Mặt hàng: M-42\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Rich, bittersweet, blended powder - Pure cocoa from the Yucatan - Pure cocoa from the Yucatan - Mountain grown in the highlands of Guatemala\", \"vi\": \"Bột pha trộn đậm đà, vị đắng ngọt - Ca cao nguyên chất từ Yucatan - Ca cao nguyên chất từ Yucatan - Trồng ở vùng cao nguyên Guatemala\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Ready for making steamy, frothy, hot drinks - Perfect for drinks, cooking, baking, and confections - Beautifully displayed in a handcrafted wooden gift box - Unsweetened cocoa in bag designed with artwork from Guatemala\", \"vi\": \"Sẵn sàng để pha các món uống nóng sủi bọt, nghi ngút khói - Hoàn hảo cho đồ uống, nấu ăn, làm bánh và bánh kẹo - Trưng bày đẹp mắt trong hộp quà bằng gỗ thủ công - Ca cao không đường trong túi được thiết kế với họa tiết từ Guatemala\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Cocoa, white and brown sugar, cinnamon, ancho, allspice, anise, and cayenne - 100% pure cocoa in block form - 100% pure cocoa in block form - 100% pure cocoa in block form\", \"vi\": \"Ca cao, đường trắng và đường nâu, quế, ớt ancho, nhục đậu khấu, đại hồi và ớt cayenne - Ca cao nguyên chất 100% dạng khối - Ca cao nguyên chất 100% dạng khối - Ca cao nguyên chất 100% dạng khối\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Mayan Joy Cocoa Products Chart\", \"vi\": \"Bảng sản phẩm ca cao Mayan Joy\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}]' WHERE `id` = '0badde02-de54-454b-8e9d-55ede78052e3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Tatiana Schwartz <orders@georgestreetsweets.co.uk>\", \"vi\": \"Từ: Tatiana Schwartz <orders@georgestreetsweets.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Alejandro Ordaz <aordaz@brooksidestationery.co.uk>\", \"vi\": \"Đến: Alejandro Ordaz <aordaz@brooksidestationery.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 28 April\", \"vi\": \"Ngày: 28 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Confirmation of order number 47892\", \"vi\": \"Chủ đề: Xác nhận đơn hàng số 47892\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Order receipt\", \"vi\": \"Tệp đính kèm: 📎 Biên nhận đơn hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"George Street Sweets\", \"vi\": \"George Street Sweets\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Mr. Ordaz,\", \"vi\": \"Kính gửi ông Ordaz,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Thank you for placing an order with George Street Sweets.\", \"vi\": \"Cảm ơn ông đã đặt hàng tại George Street Sweets.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This e-mail is to confirm that we have received your request.\", \"vi\": \"Email này nhằm xác nhận rằng chúng tôi đã nhận được yêu cầu của ông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Your receipt has been attached to this e-mail.\", \"vi\": \"Biên nhận của ông đã được đính kèm trong email này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"If you have any questions or need to make any changes to your order, please reply to this message or phone us at (091) 498 0172.\", \"vi\": \"Nếu ông có bất kỳ câu hỏi nào hoặc cần thực hiện bất kỳ thay đổi nào đối với đơn hàng của mình, vui lòng phản hồi lại tin nhắn này hoặc gọi cho chúng tôi theo số (091) 498 0172.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Note that we are unable to accommodate order changes that are submitted less than 48 hours before your scheduled pickup time.\", \"vi\": \"Xin lưu ý rằng chúng tôi không thể đáp ứng các thay đổi đơn hàng được gửi ít hơn 48 giờ trước thời gian nhận hàng dự kiến của ông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"If picking up your order, we are located at 29 George Street.\", \"vi\": \"Nếu đến nhận đơn hàng của mình, cửa hàng chúng tôi nằm ở số 29 George Street.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Parking is available next door, directly behind Spike\'s Cycle Shop.\", \"vi\": \"Chỗ đậu xe có sẵn ở tòa nhà bên cạnh, ngay phía sau cửa hàng xe đạp Spike\'s Cycle Shop.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We offer delivery to customers within 10 kilometres of our shop for a fee of £2.50.\", \"vi\": \"Chúng tôi cung cấp dịch vụ giao hàng cho khách hàng trong bán kính 10 km tính từ cửa hàng với mức phí là 2,50 bảng Anh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Please note that cancellations within 24 hours of your pickup or delivery time will not be refunded.\", \"vi\": \"Xin lưu ý rằng các đơn hàng hủy trong vòng 24 giờ trước thời gian nhận hàng hoặc giao hàng sẽ không được hoàn lại tiền.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Tatiana Schwartz\", \"vi\": \"Tatiana Schwartz\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Order: 47892\", \"vi\": \"Đơn hàng: 47892\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Date of Order: 28 April\", \"vi\": \"Ngày đặt hàng: 28 tháng 4\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Pickup Date and Time: N/A\", \"vi\": \"Ngày và giờ nhận hàng: Không áp dụng\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Delivery Date and Time: 2 May, 11:30 A.M.\", \"vi\": \"Ngày và giờ giao hàng: Ngày 2 tháng 5, 11:30 sáng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Delivery Location: 2 Spen Lane, Business Suite 202\", \"vi\": \"Địa điểm giao hàng: số 2 Spen Lane, Phòng họp doanh nghiệp 202\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Payment Method: Credit Card—Alejandro Ordaz\", \"vi\": \"Phương thức thanh toán: Thẻ tín dụng—Alejandro Ordaz\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Customisation Instructions: None\", \"vi\": \"Hướng dẫn tùy chỉnh: Không có\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Item - Cost\", \"vi\": \"Mặt hàng - Chi phí\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"18-inch round cake (chocolate with vanilla icing) - £32.00\", \"vi\": \"Bánh kem tròn 18 inch (vị sô-cô-la với lớp kem phủ vani) - 32,00 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"1 set of candles - £5.00\", \"vi\": \"1 bộ nến - 5,00 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Delivery - £2.50\", \"vi\": \"Giao hàng - 2,50 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Total - £39.50\", \"vi\": \"Tổng cộng - 39,50 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"From: Alejandro Ordaz <aordaz@brooksidestationery.co.uk>\", \"vi\": \"Từ: Alejandro Ordaz <aordaz@brooksidestationery.co.uk>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"To: Tatiana Schwartz <orders@georgestreetsweets.co.uk>\", \"vi\": \"Đến: Tatiana Schwartz <orders@georgestreetsweets.co.uk>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Date: 29 April\", \"vi\": \"Ngày: 29 tháng 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Subject: RE: Confirmation of order number 47892\", \"vi\": \"Chủ đề: RE: Xác nhận đơn hàng số 47892\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Dear Ms. Schwartz,\", \"vi\": \"Kính gửi bà Schwartz,\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"I received my order confirmation e-mail and receipt, and I noticed an error.\", \"vi\": \"Tôi đã nhận được email xác nhận đơn hàng và biên nhận của mình, và tôi nhận thấy có một lỗi sai.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"It seems that the person to whom I spoke on the phone while placing my order did not copy down the message I requested.\", \"vi\": \"Có vẻ như người mà tôi đã nói chuyện qua điện thoại khi đặt hàng đã không ghi lại lời nhắn mà tôi yêu cầu.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"The customisation I specified was that \\\"Happy Retirement\\\" be written on top.\", \"vi\": \"Phần tùy chỉnh mà tôi đã chỉ định là dòng chữ \\\"Happy Retirement\\\" được viết ở mặt trên.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"I hope it will still be possible to include this message despite the timing.\", \"vi\": \"Tôi hy vọng việc đưa lời nhắn này vào vẫn khả thi bất chấp thời điểm hiện tại.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Please respond to this e-mail to confirm.\", \"vi\": \"Vui lòng trả lời email này để xác nhận.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Also, there will be more guests than I originally expected, so I might contact your business again to place an additional order.\", \"vi\": \"Ngoài ra, sẽ có nhiều khách mời hơn dự kiến ban đầu của tôi, vì vậy tôi có thể sẽ liên hệ lại với cửa hàng để đặt thêm một đơn hàng nữa.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Thân ái,\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Alejandro Ordaz\", \"vi\": \"Alejandro Ordaz\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 43, \"question_numbers\": []}]' WHERE `id` = '0bfc1cee-4000-4b35-995f-e23f3ac4836d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Product Number - Quantity Options - Formulated For\", \"vi\": \"Mã sản phẩm - Tùy chọn số lượng - Dành cho\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"R350 - 10L, 30L, 60L - Clothing (breathable)\", \"vi\": \"R350 - 10L, 30L, 60L - Trang phục (thoáng khí)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"R370 - 10L, 30L, 60L - Outerwear (non-breathable)\", \"vi\": \"R370 - 10L, 30L, 60L - Áo khoác ngoài (không thoáng khí)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"T125 - 10L, 30L - Shoes and hiking boots\", \"vi\": \"T125 - 10L, 30L - Giày và giày ống leo núi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Ocalox is at the forefront of manufacturing textile treatments.\", \"vi\": \"Ocalox dẫn đầu trong lĩnh vực sản xuất các chất xử lý vải.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our revolutionary products can be used on a wide range of fabrics, creating a waterproof layer that stops the absorption of water.\", \"vi\": \"Các sản phẩm mang tính cách mạng của chúng tôi có thể được sử dụng trên nhiều loại vải, tạo ra một lớp chống thấm nước ngăn chặn sự hấp thụ nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The application process is easy.\", \"vi\": \"Quy trình ứng dụng rất đơn giản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"A solution of Ocalox and warm water is prepared according to the instructions.\", \"vi\": \"Một dung dịch gồm Ocalox và nước ấm được chuẩn bị theo hướng dẫn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The fabric is then soaked in the mixture for a duration of 20 minutes.\", \"vi\": \"Sau đó, vải được ngâm trong hỗn hợp này trong thời gian 20 phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Then, the fabric should be extended on a flat surface and left to air-dry for at least 6 hours.\", \"vi\": \"Sau đó, vải nên được trải phẳng trên một bề mặt và để khô tự nhiên trong ít nhất 6 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The item is then ready for use without further laundering.\", \"vi\": \"Sản phẩm sau đó đã sẵn sàng để sử dụng mà không cần giặt lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Select the right high-performance treatment to address your specific needs:\", \"vi\": \"Chọn phương pháp xử lý hiệu suất cao phù hợp để giải quyết nhu cầu cụ thể của bạn:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Contact our customer service line at 1-800-555-2626 to inquire about bulk rates.\", \"vi\": \"Hãy liên hệ với bộ phận dịch vụ khách hàng của chúng tôi theo số 1-800-555-2626 để hỏi về giá mua sỉ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"□□ X\", \"vi\": \"□□ X\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Our Products\", \"vi\": \"Sản phẩm của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"In the News\", \"vi\": \"Tin tức\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Contact\", \"vi\": \"Liên hệ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To: customerservice@ocalox.com\", \"vi\": \"Đến: customerservice@ocalox.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: chosusan@steltzermfg.com\", \"vi\": \"Từ: chosusan@steltzermfg.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date: September 22\", \"vi\": \"Ngày: 22 tháng 9\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subject: Product issue\", \"vi\": \"Chủ đề: Vấn đề về sản phẩm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Dear Customer Service Team:\", \"vi\": \"Kính gửi Nhóm Dịch vụ Khách hàng,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"We have been using your T125 product in our manufacturing process for the past six months.\", \"vi\": \"Chúng tôi đã sử dụng sản phẩm T125 của các bạn trong quy trình sản xuất của mình trong sáu tháng qua.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Overall, we have been pleased with the results, and both customer feedback and quality-control testing have been positive.\", \"vi\": \"Nhìn chung, chúng tôi rất hài lòng với kết quả, và cả phản hồi của khách hàng lẫn việc kiểm tra chất lượng đều rất tích cực.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"However, recently we started noticing some kind of sticky substance remaining on the fabric\'s surface after the drying time.\", \"vi\": \"Tuy nhiên, gần đây chúng tôi bắt đầu nhận thấy một số loại chất dính còn lại trên bề mặt vải sau thời gian phơi khô.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"The container is from the same batch as others that we used without any issues, so I think it may be a problem with the way we were storing the product.\", \"vi\": \"Thùng chứa này thuộc cùng một lô với các thùng khác mà chúng tôi đã sử dụng mà không gặp sự cố nào, vì vậy tôi nghĩ đó có thể là vấn đề với cách chúng tôi bảo quản sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Could you please let me know how this should be done properly?\", \"vi\": \"Bạn có thể vui lòng cho tôi biết việc này nên được thực hiện đúng cách như thế nào không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I didn\'t see any information about this matter in the instructions.\", \"vi\": \"Tôi không thấy bất kỳ thông tin nào về vấn đề này trong phần hướng dẫn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Many thanks,\", \"vi\": \"Chân thành cảm ơn,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Susan Cho\", \"vi\": \"Susan Cho\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Steltzer Manufacturing\", \"vi\": \"Công ty Sản xuất Steltzer\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Tin nhắn email\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '0c1435a1-b02f-4e90-8e02-afd8c93b746f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"💬 👤\", \"vi\": \"💬 👤\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"⎯ ◻ ✕\", \"vi\": \"⎯ ◻ ✕\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Yurino Saiki 1:54 P.M.\", \"vi\": \"Yurino Saiki 1:54 CH.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"What did you think of the applicant Ruby Fleming?\", \"vi\": \"Bạn nghĩ gì về ứng viên Ruby Fleming?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Aziz Miri 1:55 P.M.\", \"vi\": \"Aziz Miri 1:55 CH.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"She really impressed me in the interview.\", \"vi\": \"Cô ấy thực sự đã gây ấn tượng với tôi trong buổi phỏng vấn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I think her artwork would be a great addition to our children\'s series.\", \"vi\": \"Tôi nghĩ các tác phẩm nghệ thuật của cô ấy sẽ là một sự bổ sung tuyệt vời cho series sách thiếu nhi của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Yurino Saiki 1:56 P.M.\", \"vi\": \"Yurino Saiki 1:56 CH.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"If we hire her, I thought Levi could teach her how to use our on-site file-sharing program.\", \"vi\": \"Nếu chúng ta tuyển dụng cô ấy, tôi nghĩ Levi có thể hướng dẫn cô ấy cách sử dụng chương trình chia sẻ tệp nội bộ của công ty.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"It wouldn\'t be software she\'s worked with before.\", \"vi\": \"Đó không phải là phần mềm mà cô ấy từng làm việc trước đây.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Levi, would that be an issue for you?\", \"vi\": \"Levi, điều đó có phải là vấn đề đối với bạn không?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Aziz Miri 1:57 P.M.\", \"vi\": \"Aziz Miri 1:57 CH.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Of everyone we\'ve interviewed, I think she would be the best fit for the team.\", \"vi\": \"Trong số tất cả những người chúng ta đã phỏng vấn, tôi nghĩ cô ấy sẽ là người phù hợp nhất với đội ngũ.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Levi Weiler 1:58 P.M.\", \"vi\": \"Levi Weiler 1:58 CH.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Of course not.\", \"vi\": \"Tất nhiên là không rồi.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Yurino Saiki 2:00 P.M.\", \"vi\": \"Yurino Saiki 2:00 CH.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thanks a lot!\", \"vi\": \"Cảm ơn rất nhiều!\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I also see from her cover letter that she has built up a following on social media.\", \"vi\": \"Tôi cũng thấy từ thư xin việc rằng cô ấy đã tạo dựng được một lượng người theo dõi trên mạng xã hội.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Levi Weiler 2:01 P.M.\", \"vi\": \"Levi Weiler 2:01 CH.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"That would help to boost sales.\", \"vi\": \"Điều đó sẽ giúp thúc đẩy doanh số bán hàng.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"So, are we ready to make her a job offer?\", \"vi\": \"Vậy, chúng ta đã sẵn sàng đưa ra lời mời làm việc cho cô ấy chưa?\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Aziz Miri 2:02 P.M.\", \"vi\": \"Aziz Miri 2:02 CH.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Mr. Gilliam wants to have a follow-up interview by teleconference first to talk about how she might handle the role.\", \"vi\": \"Ông Gilliam muốn có một buổi phỏng vấn tiếp theo qua hội nghị truyền hình trước để thảo luận về cách cô ấy có thể đảm nhận vai trò này.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"He says it\'s essential that the person can cope with being assigned numerous tasks.\", \"vi\": \"Ông ấy nói rằng điều quan trọng là ứng viên phải có khả năng đương đầu với việc được giao nhiều nhiệm vụ.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Yurino Saiki 2:04 P.M.\", \"vi\": \"Yurino Saiki 2:04 CH.\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Aziz, are you setting up that meeting?\", \"vi\": \"Aziz, bạn có đang sắp xếp cuộc họp đó không?\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Aziz Miri 2:05 P.M.\", \"vi\": \"Aziz Miri 2:05 CH.\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Yes, I\'ll take care of everything.\", \"vi\": \"Vâng, tôi sẽ lo liệu mọi thứ.\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '0c930fed-f3a8-49f5-9786-dcef72711548';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"KENT (26 February)—Stellar Chocolates is a local business offering a wide selection of handcrafted delicacies.\", \"vi\": \"KENT (26 tháng 2)—Stellar Chocolates là một doanh nghiệp địa phương cung cấp nhiều loại sản phẩm thủ công tinh tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"With two shops in Kent, the business is well-known in the area.\", \"vi\": \"Với hai cửa hàng tại Kent, doanh nghiệp này rất nổi tiếng trong khu vực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Recently, however, Stellar Chocolates gained national recognition by earning top awards from the Chocolate Council last month.\", \"vi\": \"Tuy nhiên, gần đây Stellar Chocolates đã đạt được sự công nhận trên toàn quốc bằng cách giành được các giải thưởng hàng đầu từ Hội đồng Sô-cô-la vào tháng trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Stephanie Davidson, who co-owns the shops with Brian Markus, emphasises the sources and quality of Stellar Chocolates.\", \"vi\": \"Stephanie Davidson, đồng sở hữu các cửa hàng cùng với Brian Markus, nhấn mạnh nguồn gốc và chất lượng của Stellar Chocolates.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"Before launching the business, Brian and I spent several months travelling to areas of the world known for quality cacao-bean production.\", \"vi\": \"\\\"Trước khi thành lập doanh nghiệp, Brian và tôi đã dành vài tháng để đi đến các khu vực trên thế giới nổi tiếng với việc sản xuất hạt ca cao chất lượng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We inspected the plants and learned about traditional harvesting and roasting processes,\\\" she said.\", \"vi\": \"Chúng tôi đã kiểm tra các cây trồng và tìm hiểu về các quy trình thu hoạch và rang truyền thống,\\\" cô ấy nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In fact, production started only after the co-owners had secured the finest ingredients for their products.\", \"vi\": \"Trên thực tế, việc sản xuất chỉ bắt đầu sau khi các đồng sở hữu đã đảm bảo được các nguyên liệu tốt nhất cho sản phẩm của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"They now incorporate a variety of other ingredients such as chili, basil, and even wasabi, to create a unique line of chocolates.\", \"vi\": \"Họ hiện kết hợp nhiều loại nguyên liệu khác nhau như ớt, húng quế, và thậm chí cả mù tạt wasabi, để tạo ra một dòng sô-cô-la độc đáo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Demand for Stellar\'s line has continued to grow, and the firm expects to open a third shop in Bath later this year.\", \"vi\": \"Nhu cầu đối với dòng sản phẩm của Stellar tiếp tục tăng trưởng và công ty dự kiến sẽ khai trương cửa hàng thứ ba tại Bath vào cuối năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Ms. Davidson noted that they have found additional space in an old mill to be converted for retail use.\", \"vi\": \"Bà Davidson lưu ý rằng họ đã tìm thấy thêm không gian trong một nhà máy xay bột cũ để chuyển đổi thành mục đích bán lẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"\\\"The new shop will be our largest, and we plan to establish a mail-order business so that we can ship not just domestically but also internationally,\\\" she said.\", \"vi\": \"\\\"Cửa hàng mới sẽ là cửa hàng lớn nhất của chúng tôi và chúng tôi có kế hoạch thiết lập dịch vụ đặt hàng qua thư để chúng tôi có thể vận chuyển không chỉ trong nước mà còn quốc tế,\\\" cô ấy nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"http://www.stellarchocolates.co.uk/reviews\", \"vi\": \"http://www.stellarchocolates.co.uk/reviews\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Today I visited the new Stellar Chocolates shop that opened a few weeks ago in the former mill, expecting to see an ordinary candy store.\", \"vi\": \"Hôm nay tôi đã đến thăm cửa hàng Stellar Chocolates mới khai trương vài tuần trước tại nhà máy cũ, với mong đợi sẽ thấy một cửa hàng kẹo thông thường.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"What a surprise!\", \"vi\": \"Thật là bất ngờ!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I was delighted to taste some free samples while watching the chocolates being made by hand.\", \"vi\": \"Tôi rất vui mừng khi được nếm thử một số mẫu miễn phí trong khi ngắm nhìn những viên sô-cô-la được làm bằng tay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I even had a chance to chat with one of the owners, who told me about the origin of their business.\", \"vi\": \"Tôi thậm chí còn có cơ hội trò chuyện với một trong những chủ cửa hàng, người đã kể cho tôi nghe về nguồn gốc của doanh nghiệp họ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"She met her co-owner ten years ago in a class at university, and they came up with the business idea for an assignment.\", \"vi\": \"Cô ấy đã gặp người đồng sở hữu của mình mười năm trước trong một lớp học ở trường đại học, và họ đã nảy ra ý tưởng kinh doanh cho một bài tập.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"They got such positive comments from their professor and fellow students that they decided to turn their idea into a career project.\", \"vi\": \"Họ nhận được những lời khen ngợi tích cực từ giáo viên và các bạn học đến mức họ quyết định biến ý tưởng của mình thành một dự án sự nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I look forward to many future visits, as the shop is just around the corner from my home.\", \"vi\": \"Tôi mong chờ sẽ có nhiều lần ghé thăm trong tương lai, vì cửa hàng nằm ngay sát góc đường nhà tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Cynthia Ragusa\", \"vi\": \"Cynthia Ragusa\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Our Product Line\", \"vi\": \"Dòng sản phẩm của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Customer Reviews\", \"vi\": \"Đánh giá của khách hàng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Contact\", \"vi\": \"Liên hệ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}]' WHERE `id` = '0cdf685b-0c12-4094-9cca-b9a76e7dc4cb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.riverthamestours.uk/order/confirmation\", \"vi\": \"https://www.riverthamestours.uk/order/confirmation\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"River Thames Tours\", \"vi\": \"River Thames Tours\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Thank you for reserving a River Thames tour with us.\", \"vi\": \"Cảm ơn bạn đã đặt tour tham quan Sông Thames cùng chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We are eager to welcome you aboard.\", \"vi\": \"Chúng tôi rất mong được chào đón bạn lên tàu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Each tour lasts 3 hours.\", \"vi\": \"Mỗi chuyến tham quan kéo dài 3 tiếng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Your tour includes a luncheon served at 1:00 p.m. Please consult our Web site for a menu.\", \"vi\": \"Chuyến tham quan của bạn bao gồm một bữa trưa được phục vụ lúc 1:00 chiều. Vui lòng tham khảo trang web của chúng tôi để xem thực đơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Should you have any dietary restrictions and like to request a special meal, please contact our customer experience manager, Martin Torma, at least 48 hours prior to your tour.\", \"vi\": \"Nếu bạn có bất kỳ hạn chế nào về chế độ ăn uống và muốn yêu cầu một bữa ăn đặc biệt, vui lòng liên hệ với quản lý trải nghiệm khách hàng của chúng tôi, Martin Torma, ít nhất 48 giờ trước chuyến tham quan của bạn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This reservation also entitles you to a 10 percent discount on a walking tour by Edgerton Walking Tours—just provide your confirmation code when booking.\", \"vi\": \"Đặt chỗ này cũng giúp bạn được giảm giá 10% cho chuyến tham quan đi bộ của Edgerton Walking Tours—chỉ cần cung cấp mã xác nhận của bạn khi đặt chỗ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Name: Lewis Califf\", \"vi\": \"Họ tên: Lewis Califf\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Purchase Date: 18 April\", \"vi\": \"Ngày mua: 18 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Confirmation Code: H102057\", \"vi\": \"Mã xác nhận: H102057\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Tour Start: 1 May, 11:30 a.m.\", \"vi\": \"Thời gian bắt đầu tour: 1 tháng 5, 11:30 sáng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Quantity: 4\", \"vi\": \"Số lượng: 4\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Total: £180.00\", \"vi\": \"Tổng cộng: £180.00\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Payment: Credit card ending in 1037\", \"vi\": \"Thanh toán: Thẻ tín dụng có số kết thúc bằng 1037\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Please note: Boarding ends 10 minutes before departure time.\", \"vi\": \"Lưu ý: Việc lên tàu kết thúc 10 phút trước giờ khởi hành.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Tours cannot be rescheduled.\", \"vi\": \"Các tour tham quan không thể dời lại lịch.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '0d2d94c5-cc71-4e74-9518-4232a19fbeb6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Dana Paulwell\", \"vi\": \"Đến: Dana Paulwell\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Silas Laveau\", \"vi\": \"Từ: Silas Laveau\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: August 22\", \"vi\": \"Ngày: 22 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: My input\", \"vi\": \"Chủ đề: Ý kiến đóng góp của tôi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Article\", \"vi\": \"Đính kèm: Bài báo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Dr. Paulwell,\", \"vi\": \"Kính gửi Tiến sĩ Paulwell,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This message is in response to yesterday\'s staff meeting, particularly the discussion on how certain aspects of the clinic may affect our work and mission.\", \"vi\": \"Tin nhắn này là để phản hồi cuộc họp nhân viên ngày hôm qua, đặc biệt là cuộc thảo luận về cách một số khía cạnh của phòng khám có thể ảnh hưởng đến công việc và sứ mệnh của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"___143___.\", \"vi\": \"___143___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [143]}, {\"en\": \"Currently, the vending machines in the hall outside our waiting room are stocked with sugary and salty products such as soft drinks and chips.\", \"vi\": \"Hiện tại, các máy bán hàng tự động ở sảnh bên ngoài phòng chờ của chúng ta được cung cấp đầy các sản phẩm nhiều đường và muối như nước ngọt và khoai tây chiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"As a health care provider, we ___144___ beverages and snacks that show our commitment to wellness.\", \"vi\": \"Là một nhà cung cấp dịch vụ chăm sóc sức khỏe, chúng ta ___144___ đồ uống và đồ ăn nhẹ thể hiện cam kết của chúng ta đối với sự lành mạnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [144]}, {\"en\": \"___145___, our mission is focused on good health.\", \"vi\": \"___145___, sứ mệnh của chúng ta tập trung vào sức khỏe tốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [145]}, {\"en\": \"I have attached an article about actions that medical centers like ours are taking to improve their hospitality stations.\", \"vi\": \"Tôi đã đính kèm một bài báo về các hành động mà các trung tâm y tế như của chúng ta đang thực hiện để cải thiện các khu vực tiếp đón của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I hope you find it ___146___.\", \"vi\": \"Tôi hy vọng bạn thấy nó ___146___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [146]}, {\"en\": \"It details some easy and cost-effective changes we could consider.\", \"vi\": \"Nó trình bày chi tiết một số thay đổi dễ dàng và tiết kiệm chi phí mà chúng ta có thể cân nhắc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Silas Laveau\", \"vi\": \"Silas Laveau\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '0da53709-65f8-4d05-92a0-1de134d14549';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Charlie Tran <Charlie.Tran@mailcrate.com>\", \"vi\": \"Đến: Charlie Tran <Charlie.Tran@mailcrate.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Grace Drance <GDrance@hoppersmedicalcenter.org>\", \"vi\": \"Từ: Grace Drance <GDrance@hoppersmedicalcenter.org>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: January 10\", \"vi\": \"Ngày: 10 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Missed appointment\", \"vi\": \"Chủ đề: Cuộc hẹn bị lỡ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Tran,\", \"vi\": \"Ông Tran kính mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am contacting you because you did not appear for your 1:00 p.m. appointment for your annual physical exam at Hopper\'s Medical Center (HMC) today.\", \"vi\": \"Tôi liên hệ với ông vì ông đã không đến tham gia buổi hẹn khám sức khỏe định kỳ lúc 1:00 chiều tại Trung tâm Y tế Hopper\'s (HMC) vào ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As you know, it is our policy to charge the full appointment fee for missed appointments unless the patient notifies us at least 24 hours in advance of the scheduled visit.\", \"vi\": \"Như ông đã biết, chính sách của chúng tôi là tính toàn bộ phí khám đối với các cuộc hẹn bị lỡ trừ khi bệnh nhân thông báo cho chúng tôi trước ít nhất 24 giờ so với thời gian đã lên lịch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"However, we are waiving the fee because this is your first missed appointment in fifteen years of being a patient at the center.\", \"vi\": \"Tuy nhiên, chúng tôi quyết định miễn khoản phí này vì đây là lần đầu tiên ông lỡ lịch hẹn trong suốt mười lăm năm là bệnh nhân tại trung tâm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please contact the office as soon as possible to reschedule your appointment.\", \"vi\": \"Vui lòng liên hệ với văn phòng càng sớm càng tốt để đặt lịch hẹn lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Your physician, Dr. Ramanathan, has created additional appointment times this month because he will be on vacation in February.\", \"vi\": \"Bác sĩ phụ trách của ông, Bác sĩ Ramanathan, đã sắp xếp thêm các khung giờ hẹn trong tháng này vì ông ấy sẽ đi nghỉ mát vào tháng Hai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Grace Drance, Scheduling Assistant\", \"vi\": \"Grace Drance, Trợ lý Xếp lịch\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '0da6a27f-228e-40a4-a982-1672fa471ba1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Attention Conference Centre Staff:\", \"vi\": \"Kính gửi Nhân viên Trung tâm Hội nghị:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Geylang Conference Centre is hosting the Singapore Banking Conference on 20 April.\", \"vi\": \"Trung tâm Hội nghị Geylang sẽ tổ chức Hội nghị Ngân hàng Singapore vào ngày 20 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The welcome desk will be open from 8:00 A.M. to 10:00 A.M. When checking in, conference attendees will need to present a valid form of identification.\", \"vi\": \"Bàn đón tiếp sẽ mở cửa từ 8:00 sáng đến 10:00 sáng. Khi làm thủ tục check-in, những người tham dự hội nghị sẽ cần xuất trình một loại giấy tờ tùy thân hợp lệ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Acceptable forms of identification include a passport, a driver\'s license, or a company-issued photo ID.\", \"vi\": \"Các loại giấy tờ tùy thân được chấp nhận bao gồm hộ chiếu, bằng lái xe, hoặc thẻ nhân viên có ảnh do công ty cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"After checking in, attendees will be handed a welcome packet, which includes a conference schedule, a map of the facility, and their ticket to the evening banquet.\", \"vi\": \"Sau khi làm thủ tục check-in, người tham dự sẽ được trao một gói tài liệu chào mừng, bao gồm lịch trình hội nghị, sơ đồ cơ sở vật chất, và vé tham dự buổi tiệc tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"If attendees arrive after 10:00 A.M., they should be directed to the security desk, where someone will check them in.\", \"vi\": \"Nếu người tham dự đến sau 10:00 sáng, họ nên được hướng dẫn đến quầy an ninh, nơi sẽ có người làm thủ tục cho họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Please note that some attendees will be staying at the conference centre\'s hotel.\", \"vi\": \"Xin lưu ý rằng một số người tham dự sẽ lưu trú tại khách sạn của trung tâm hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"They should be directed to the hotel lobby, where they can leave their luggage.\", \"vi\": \"Họ nên được hướng dẫn đến sảnh khách sạn, nơi họ có thể gửi hành lý của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Hotel personnel will bring the luggage to the appropriate guest rooms when the rooms are ready.\", \"vi\": \"Nhân viên khách sạn sẽ mang hành lý đến các phòng nghỉ phù hợp khi phòng đã sẵn sàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"If you have any questions about your duties for the day, please contact Jia-Wei Teo at extension 231.\", \"vi\": \"Nếu bạn có bất kỳ câu hỏi nào về nhiệm vụ của mình trong ngày, vui lòng liên hệ với Jia-Wei Teo theo số máy nhánh 231.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '0db1dca8-1f9e-402a-8853-53a95a25cd4f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Bai Chang <bchang@lexrg.com>\", \"vi\": \"Đến: Bai Chang <bchang@lexrg.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: customerservice@sprtech.com\", \"vi\": \"Từ: customerservice@sprtech.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: September 28\", \"vi\": \"Ngày: 28 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Order 255646\", \"vi\": \"Chủ đề: Đơn hàng 255646\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Chang:\", \"vi\": \"Kính gửi bà Chang,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for your purchase on September 27.\", \"vi\": \"Cảm ơn quý khách đã mua hàng vào ngày 27 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Your package has shipped and is due to arrive on October 1.\", \"vi\": \"Gói hàng của quý khách đã được gửi đi và dự kiến sẽ đến nơi vào ngày 1 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"______[131].\", \"vi\": \"______[131].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [131]}, {\"en\": \"Simply visit www.sprtech.com/shipping/status, enter your order number, and press \\\"Search.\\\"\", \"vi\": \"Quý khách chỉ cần truy cập www.sprtech.com/shipping/status, nhập số đơn hàng của mình và nhấn \\\"Tìm kiếm\\\".\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"When you receive your package, we ______[132] you to take a short survey at www.sprtech.com/survey.\", \"vi\": \"Khi nhận được gói hàng, chúng tôi ______[132] quý khách thực hiện một khảo sát ngắn tại www.sprtech.com/survey.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [132]}, {\"en\": \"It is through customer feedback that we are ______[133] to monitor our level of service.\", \"vi\": \"Chính nhờ những phản hồi của khách hàng mà chúng tôi mới ______[133] theo dõi được chất lượng dịch vụ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [133]}, {\"en\": \"Upon ______[134] of the survey, you will receive a 10% discount toward your next order.\", \"vi\": \"Khi ______[134] khảo sát, quý khách sẽ nhận được mã giảm giá 10% cho đơn hàng tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [134]}, {\"en\": \"Sprtech.com Customer Service\", \"vi\": \"Bộ phận Chăm sóc Khách hàng Sprtech.com\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '0db7ce50-6882-4dc3-a569-6ea90d13215d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Madalena Navas\", \"vi\": \"Đến: Madalena Navas\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Hugo Jones\", \"vi\": \"Từ: Hugo Jones\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: April 2\", \"vi\": \"Ngày: Ngày 2 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Thank you\", \"vi\": \"Chủ đề: Cảm ơn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Navas,\", \"vi\": \"Kính gửi chị Navas,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I enjoyed speaking with you about the associate manager position last week, and as I mentioned, I am very excited about the possibility of working with you at Cordova Creations.\", \"vi\": \"Tôi rất thích trò chuyện với chị về vị trí quản lý liên kết vào tuần trước, và như tôi đã đề cập, tôi rất hào hứng với viễn cảnh được làm việc cùng chị tại Cordova Creations.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I wanted to let you know that I have received a job offer from another company, and I have to respond to that hiring manager soon.\", \"vi\": \"Tôi muốn thông báo cho chị biết rằng tôi đã nhận được lời mời làm việc từ một công ty khác và tôi phải trả lời người quản lý tuyển dụng đó sớm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I realize it has only been a few days since my interview, but if it is at all possible for you to update me on the status of my application before the end of the week, that would be very helpful.\", \"vi\": \"Tôi hiểu rằng mới chỉ vài ngày trôi qua kể từ buổi phỏng vấn của tôi, nhưng nếu chị có thể cập nhật cho tôi về tình trạng hồ sơ ứng tuyển của tôi trước cuối tuần này, thì điều đó sẽ rất hữu ích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I have long admired Cordova Creations and would really like to be a part of it.\", \"vi\": \"Tôi đã ngưỡng mộ Cordova Creations từ lâu và thực sự rất muốn trở thành một phần của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I am hoping to hear positive news from you.\", \"vi\": \"Tôi rất hy vọng sẽ nhận được tin vui từ chị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Hugo Jones\", \"vi\": \"Hugo Jones\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '0dc4a2a4-c6d7-4cfb-b512-7879ea443d19';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Unit Name - Almora Q1 - Almora S1 - Belma Q1 - Belma S1\\n(under development)\", \"vi\": \"Tên Đơn Vị - Almora Q1 - Almora S1 - Belma Q1 - Belma S1\\n(đang phát triển)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Height - 950 mm - 930 mm - 356 mm - 256 mm\", \"vi\": \"Chiều cao - 950 mm - 930 mm - 356 mm - 256 mm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Width - 530 mm - 500 mm - 1,150 mm - 856 mm\", \"vi\": \"Chiều rộng - 530 mm - 500 mm - 1.150 mm - 856 mm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Speed - 4.2 km/h - 4 km/h - 2.5 km/h - 2.3 km/h\", \"vi\": \"Tốc độ - 4,2 km/h - 4 km/h - 2,5 km/h - 2,3 km/h\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Ingani Robotics\", \"vi\": \"Công ty Robot Ingani\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"http://www.inganirobotics.co.uk ▶\", \"vi\": \"http://www.inganirobotics.co.uk ▶\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In today\'s mail-order industry, turnaround time is key.\", \"vi\": \"Trong ngành công nghiệp đặt hàng qua thư tín ngày nay, thời gian hoàn thành đơn hàng là yếu tố then chốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Ingani\'s machines can take the physical labour out of item retrieval.\", \"vi\": \"Các cỗ máy của Ingani có thể loại bỏ sức lao động chân tay trong việc tìm kiếm hàng hóa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Our self-navigating, fully rechargeable freight movers can increase your efficiency without the need for extra staff.\", \"vi\": \"Các thiết bị vận chuyển hàng hóa tự điều hướng và hoàn toàn có thể sạc lại của chúng tôi có thể nâng cao hiệu suất làm việc của bạn mà không cần thêm nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"They function safely in shared environments with people.\", \"vi\": \"Chúng hoạt động an toàn trong môi trường làm việc chung với con người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"All machines are equipped with tethering hooks to secure pallets or boxes.\", \"vi\": \"Tất cả các cỗ máy đều được trang bị móc buộc để cố định pallet hoặc hộp đựng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"See below for measurements and speed of our popular and upcoming models.\", \"vi\": \"Xem phần bên dưới để biết kích thước và tốc độ của các mẫu máy phổ biến và sắp ra mắt của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To: edwinraster@inganirobotics.co.uk\", \"vi\": \"Đến: edwinraster@inganirobotics.co.uk\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"From: aalmansouri@vemta.co.uk\", \"vi\": \"Từ: aalmansouri@vemta.co.uk\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date: 3 April\", \"vi\": \"Ngày: 3 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Subject: Upcoming order\", \"vi\": \"Chủ đề: Đơn hàng sắp tới\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Dear Mr. Raster,\", \"vi\": \"Kính gửi ông Raster,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Thank you for updating me on the status of the Belma S1.\", \"vi\": \"Cảm ơn ông đã cập nhật cho tôi về tình trạng của dòng máy Belma S1.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Our facilities expansion will not be complete until next month, so I will wait until then to place the order.\", \"vi\": \"Việc mở rộng cơ sở của chúng tôi sẽ chưa hoàn thành cho đến tháng tới, vì vậy tôi sẽ đợi đến lúc đó để đặt hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"As you know, we have been loyal customers for several years, having purchased two of the narrowest Almora units three years ago and an additional four last year.\", \"vi\": \"Như ông đã biết, chúng tôi là những khách hàng trung thành trong nhiều năm qua, đã mua hai thiết bị Almora hẹp nhất vào ba năm trước và thêm bốn chiếc nữa vào năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I wanted to inquire whether we might be eligible for a discount on bulk orders similar to the one we received for last year\'s order.\", \"vi\": \"Tôi muốn hỏi liệu chúng tôi có đủ điều kiện nhận được mức chiết khấu cho các đơn hàng số lượng lớn tương tự như mức chúng tôi đã nhận được cho đơn hàng năm ngoái hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"We are planning to buy six of the new units but could be persuaded to purchase more.\", \"vi\": \"Chúng tôi đang lên kế hoạch mua sáu thiết bị mới nhưng có thể sẽ được thuyết phục để mua nhiều hơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Please let me know, and thank you again for following up.\", \"vi\": \"Xin vui lòng cho tôi biết, và cảm ơn ông một lần nữa vì đã theo sát vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Aliya Almansouri\", \"vi\": \"Aliya Almansouri\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Senior Purchasing Manager, Vemta Ltd.\", \"vi\": \"Trưởng phòng Mua hàng, Công ty TNHH Vemta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '0de50e80-c21b-4529-8fbf-65243cd53d70';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Marsha Zalen <mzalen@mansfield.com>\", \"vi\": \"Đến: Marsha Zalen <mzalen@mansfield.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Kaymar PCP <info@kaymarpcp.com>\", \"vi\": \"Từ: Kaymar PCP <info@kaymarpcp.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: September 8\", \"vi\": \"Ngày: Ngày 8 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Your recent office visit\", \"vi\": \"Chủ đề: Chuyến thăm văn phòng gần đây của bạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Zalen,\", \"vi\": \"Kính gửi Bà Zalen,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for your recent visit to Kaymar Primary Care Practice.\", \"vi\": \"Cảm ơn bạn vì chuyến thăm gần đây đến Phòng khám Chăm sóc Sức khỏe Ban đầu Kaymar.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We hope you found our services ------- (143), and we welcome suggestions for improvement.\", \"vi\": \"Chúng tôi hy vọng bạn thấy các dịch vụ của chúng tôi ------- (143), và chúng tôi luôn hoan nghênh các đóng góp để cải thiện chất lượng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [143]}, {\"en\": \"We have posted a ------- (144) of your consultation on our portal.\", \"vi\": \"Chúng tôi đã đăng một bản ------- (144) về buổi tư vấn của bạn lên cổng thông tin điện tử của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [144]}, {\"en\": \"Please take a moment to go through it and let us know if you have any questions.\", \"vi\": \"Vui lòng dành chút thời gian để xem qua và cho chúng tôi biết nếu bạn có bất kỳ câu hỏi nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"As a reminder, you can log in to the portal for various activities.\", \"vi\": \"Như một lời nhắc nhở, bạn có thể đăng nhập vào cổng thông tin để thực hiện các hoạt động khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"------- (145), you can make appointments and payments, view your medical history, review lab results, and request medication refills.\", \"vi\": \"------- (145), bạn có thể đặt lịch hẹn và thanh toán, xem lịch sử y tế, xem lại kết quả xét nghiệm, và yêu cầu cấp lại đơn thuốc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [145]}, {\"en\": \"------- (146).\", \"vi\": \"------- (146).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [146]}, {\"en\": \"Rest assured that your personal information is safe and secure.\", \"vi\": \"Hãy yên tâm rằng thông tin cá nhân của bạn hoàn toàn được bảo mật và an toàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We thank you for your business and look forward to serving you again.\", \"vi\": \"Chúng tôi cảm ơn sự tin tưởng của bạn và rất mong được phục vụ bạn một lần nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Kaymar Primary Care Practice\", \"vi\": \"Phòng khám Chăm sóc Sức khỏe Ban đầu Kaymar\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '0e05dc71-5acf-4cf8-8bf3-50897d0d7ef8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Grecian Terrace Hotel\", \"vi\": \"Khách sạn Grecian Terrace\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Host your next business conference at our five-star hotel on the beautiful Messenian Gulf.\", \"vi\": \"Tổ chức hội nghị kinh doanh tiếp theo của bạn tại khách sạn năm sao của chúng tôi bên vịnh Messenian xinh đẹp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Our facility has spacious meeting rooms overlooking the sea and the picturesque beach.\", \"vi\": \"Cơ sở của chúng tôi có các phòng họp rộng rãi hướng ra biển và bãi biển nên thơ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The hotel is the perfect setting for a corporate retreat for your staff.\", \"vi\": \"Khách sạn là bối cảnh hoàn hảo cho chuyến nghỉ dưỡng kết hợp công việc của nhân viên bạn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Enjoy a team bonding experience while taking advantage of gourmet meals, great views, and first-rate entertainment.\", \"vi\": \"Tận hưởng trải nghiệm gắn kết đội ngũ đồng thời tận dụng các bữa ăn cao cấp, tầm nhìn tuyệt đẹp và dịch vụ giải trí hàng đầu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Contact: Helena Samaras, Hospitality Manager\", \"vi\": \"Liên hệ: Helena Samaras, Quản lý Dịch vụ Khách hàng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"hsamaras@grecianterrace.com.gr\", \"vi\": \"hsamaras@grecianterrace.com.gr\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"+30 2721 093365\", \"vi\": \"+30 2721 093365\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '0e2dd737-7b65-4486-995c-5cfbef837f17';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: mcrane@doodlemail.com\", \"vi\": \"Từ: mcrane@doodlemail.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: jkumar@baxterartsupplies.com\", \"vi\": \"Đến: jkumar@baxterartsupplies.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: October 14\", \"vi\": \"Ngày: 14 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Application\", \"vi\": \"Chủ đề: Đơn ứng tuyển\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Résumé\", \"vi\": \"Đính kèm: Sơ yếu lý lịch\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Kumar,\", \"vi\": \"Kính gửi bà Kumar,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am writing in response to the advertisement posted in the window of Baxter Art Supplies.\", \"vi\": \"Tôi viết thư này để phản hồi về thông báo tuyển dụng được dán ở cửa sổ của cửa hàng Baxter Art Supplies.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As a frequent visitor to your ______[143], I have found it an invaluable source of inspiration over the years.\", \"vi\": \"Là một khách hàng thường xuyên đến ______[143] của quý vị, tôi nhận thấy đây là một nguồn truyền cảm hứng vô giá trong suốt những năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [143]}, {\"en\": \"I would be ______[144] to display my artwork.\", \"vi\": \"Tôi rất ______[144] được trưng bày các tác phẩm nghệ thuật của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [144]}, {\"en\": \"I would also enjoy running workshops to help inspire your customers.\", \"vi\": \"Tôi cũng sẽ rất hào hứng khi được điều hành các buổi hội thảo để góp phần truyền cảm hứng cho khách hàng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I believe I would be well suited for this role because I am both enthusiastic and friendly.\", \"vi\": \"Tôi tin rằng mình rất phù hợp với vị trí này vì tôi là người vừa nhiệt tình lại vừa thân thiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"______[145], I have led successful workshops at various locations in the area.\", \"vi\": \"______[145], tôi đã từng dẫn dắt thành công các buổi hội thảo tại nhiều địa điểm khác nhau trong khu vực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [145]}, {\"en\": \"I have attached a copy of my résumé, which includes more details about these workshops.\", \"vi\": \"Tôi đã đính kèm một bản sơ yếu lý lịch của mình, trong đó bao gồm nhiều chi tiết hơn về các buổi hội thảo này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"______[146].\", \"vi\": \"______[146].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": [146]}, {\"en\": \"I look forward to hearing from you after you have reviewed my application and work.\", \"vi\": \"Tôi rất mong nhận được phản hồi từ quý vị sau khi quý vị đã xem xét đơn ứng tuyển và các tác phẩm của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Melania Crane\", \"vi\": \"Melania Crane\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '0e566d50-6a9f-4cc3-915d-4755db996113';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: He-Ran Kim, Wheeling Travel Associates\", \"vi\": \"Từ: He-Ran Kim, Wheeling Travel Associates\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Mihir Sukbara\", \"vi\": \"Đến: Mihir Sukbara\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Travel Plans for Sports Trade Show\", \"vi\": \"Chủ đề: Kế hoạch du lịch cho Triển lãm Thương mại Thể thao\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Sent: 3 July\", \"vi\": \"Ngày gửi: 3 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Sydney-Perth Itinerary\", \"vi\": \"Tệp đính kèm: Hành trình Sydney-Perth\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Sukbara,\", \"vi\": \"Kính gửi ông Sukbara,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Per your request, I have reserved your round-trip ticket to Perth.\", \"vi\": \"Theo yêu cầu của ông, tôi đã đặt vé khứ hồi đi Perth cho ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Departure from Sydney is 20 July, and return from Perth is 24 July, which should perfectly accommodate your 21–23 July Trade Show.\", \"vi\": \"Chuyến đi từ Sydney là ngày 20 tháng 7, và chuyến về từ Perth là ngày 24 tháng 7, điều này hoàn toàn phù hợp với Triển lãm Thương mại từ ngày 21 đến 23 tháng 7 của ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The itinerary is attached.\", \"vi\": \"Lịch trình chi tiết được đính kèm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In reply to your question whether your samples can be brought along, the skis and snowboards can be checked as luggage.\", \"vi\": \"Để trả lời cho câu hỏi của ông liệu có thể mang theo các mẫu sản phẩm hay không, ván trượt tuyết và ván trượt tuyết lớn có thể được ký gửi làm hành lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"My contact at Canberra Airways tells me there is a $75 AUD fee for each piece of oversized luggage.\", \"vi\": \"Người liên hệ của tôi tại Canberra Airways cho biết có một khoản phí 75 đô la Úc cho mỗi kiện hành lý quá khổ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"If this fee is paid in advance, oversized items can be dropped at the express drop-off kiosk when you check in.\", \"vi\": \"Nếu khoản phí này được thanh toán trước, các vật phẩm quá khổ có thể được gửi tại ki-ốt gửi hành lý nhanh khi ông làm thủ tục.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Make sure that your items do not exceed the airline\'s maximum allowable weight and size requirements.\", \"vi\": \"Hãy đảm bảo rằng các vật phẩm của ông không vượt quá yêu cầu về trọng lượng và kích thước tối đa cho phép của hãng hàng không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please let me know how many items you wish to check so that I can make the prepayment for you.\", \"vi\": \"Vui lòng cho tôi biết có bao nhiêu vật phẩm ông muốn ký gửi để tôi có thể thanh toán trước cho ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"He-Ran Kim\", \"vi\": \"He-Ran Kim\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Wheeling Travel Associates\", \"vi\": \"Wheeling Travel Associates\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Canberra Airways\", \"vi\": \"Canberra Airways\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Express Luggage Drop-Off Service—Instructions\", \"vi\": \"Dịch vụ Gửi Hành lý Nhanh — Hướng dẫn\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Upon arrival at the airport, please follow these simple steps:\", \"vi\": \"Khi đến sân bay, vui lòng thực hiện theo các bước đơn giản sau:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Print out your boarding pass at any of our check-in kiosks as you enter the terminal.\", \"vi\": \"In thẻ lên máy bay của ông tại bất kỳ ki-ốt làm thủ tục nào của chúng tôi khi ông bước vào nhà ga.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Follow directions to the express drop-off kiosk and place your items on the scales.\", \"vi\": \"Làm theo hướng dẫn đến ki-ốt gửi hành lý nhanh và đặt các vật phẩm của ông lên cân.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Show your photo ID and boarding pass to one of our agents, who will ask how many bags you are checking.\", \"vi\": \"Xuất trình giấy tờ tùy thân có ảnh và thẻ lên máy bay cho một nhân viên của chúng tôi, người sẽ hỏi ông muốn ký gửi bao nhiêu túi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Our agent will tag your bags and return your papers so you can proceed to Security without delay.\", \"vi\": \"Nhân viên của chúng tôi sẽ dán thẻ lên túi của ông và trả lại giấy tờ để ông có thể tiến về khu vực An ninh mà không bị chậm trễ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"NOTE: Express drop-off service is currently available only in Sydney, Melbourne, and Brisbane.\", \"vi\": \"LƯU Ý: Dịch vụ gửi hành lý nhanh hiện chỉ có sẵn tại Sydney, Melbourne và Brisbane.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '0e9d932b-111a-46fa-bc79-2bd49e3e7b0f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Virens\", \"vi\": \"Virens\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Come to Virens for the best televisions, phones, tablets, and more!\", \"vi\": \"Hãy đến với Virens để sở hữu những chiếc tivi, điện thoại, máy tính bảng tốt nhất và nhiều hơn thế nữa!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Grand Opening Celebration\", \"vi\": \"Lễ kỷ niệm khai trương\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"featuring comedian and DJ Declan Gibb from radio station KYX 93.8\", \"vi\": \"có sự góp mặt của diễn viên hài kiêm DJ Declan Gibb từ đài phát thanh KYX 93.8\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Saturday, October 2, 10:00 A.M.–8:00 P.M.\", \"vi\": \"Thứ Bảy, ngày 2 tháng 10, từ 10:00 sáng đến 8:00 tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"234 Morris Avenue, next to Mike\'s Pizza\", \"vi\": \"234 Đại lộ Morris, cạnh cửa hàng Pizza của Mike\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Complimentary snacks from Sarah\'s Bakery—home of Sarah\'s delicious pastries!\", \"vi\": \"Đồ ăn nhẹ miễn phí từ Tiệm bánh Sarah—quê hương của những chiếc bánh ngọt ngon tuyệt của Sarah!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Bring this ad for $5 off a purchase of $10 or more.\", \"vi\": \"Mang theo quảng cáo này để được giảm 5 đô la cho hóa đơn mua hàng từ 10 đô la trở lên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Valid throughout October.\", \"vi\": \"Có giá trị trong suốt tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '0ee95414-0826-4c44-8a27-9364e522e961';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"💬 👤\", \"vi\": \"💬 👤\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"— ▢ X\", \"vi\": \"— ▢ X\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Harry Alvarez   [3:22 P.M.]\", \"vi\": \"Harry Alvarez   [3:22 P.M.]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Good afternoon, and welcome to DC Interiors.\", \"vi\": \"Xin chào buổi chiều và chào mừng quý khách đến với DC Interiors.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Cora Baldwin [3:23 P.M.]\", \"vi\": \"Cora Baldwin [3:23 P.M.]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Hi, my name is Cora Baldwin, and I\'m having difficulty canceling some items.\", \"vi\": \"Xin chào, tên tôi là Cora Baldwin, và tôi đang gặp khó khăn trong việc hủy một số mặt hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Harry Alvarez [3:24 P.M.]\", \"vi\": \"Harry Alvarez [3:24 P.M.]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Hi, Ms. Baldwin.\", \"vi\": \"Chào cô Baldwin.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Did you make your purchase online or through the app?\", \"vi\": \"Cô đã mua hàng trực tuyến hay qua ứng dụng vậy ạ?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Cora Baldwin [3:25 P.M.]\", \"vi\": \"Cora Baldwin [3:25 P.M.]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Through my online account.\", \"vi\": \"Qua tài khoản trực tuyến của tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I ordered the wrong color, so I need to cancel it.\", \"vi\": \"Tôi đã đặt nhầm màu nên cần hủy đơn đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I don\'t want to be charged for this because I already purchased replacements elsewhere.\", \"vi\": \"Tôi không muốn bị tính phí cho đơn này vì tôi đã mua sản phẩm thay thế ở nơi khác rồi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Harry Alvarez [3:27 P.M.]\", \"vi\": \"Harry Alvarez [3:27 P.M.]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I understand.\", \"vi\": \"Tôi hiểu rồi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I can help you.\", \"vi\": \"Tôi có thể giúp cô.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"It\'s the purchase of three 10-liter cans of the Dark Forest latex paint, right?\", \"vi\": \"Đó là đơn mua ba thùng sơn mủ (latex) màu Dark Forest loại 10 lít phải không ạ?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I can cancel the request and refund you.\", \"vi\": \"Tôi có thể hủy yêu cầu và hoàn tiền cho cô.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Cora Baldwin [3:28 P.M.]\", \"vi\": \"Cora Baldwin [3:28 P.M.]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"You got it.\", \"vi\": \"Đúng vậy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Harry Alvarez [3:29 P.M.]\", \"vi\": \"Harry Alvarez [3:29 P.M.]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Alright.\", \"vi\": \"Vâng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"That cancellation has gone through.\", \"vi\": \"Yêu cầu hủy đó đã được xử lý xong.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"You should expect to see a refund of £53.85 on your credit card account in three to five working days.\", \"vi\": \"Cô sẽ thấy khoản tiền hoàn lại là £53.85 trong tài khoản thẻ tín dụng của mình trong vòng ba đến năm ngày làm việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Can I help you with anything else?\", \"vi\": \"Tôi có thể giúp gì thêm cho cô không ạ?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Cora Baldwin [3:31 P.M.]\", \"vi\": \"Cora Baldwin [3:31 P.M.]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"That\'s all.\", \"vi\": \"Thế là đủ rồi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Thank you!\", \"vi\": \"Cảm ơn bạn!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '0fc7c06d-06fe-43b4-99a3-060c21ddb3db';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Bishwa Poudel [9:27 A.M.]\", \"vi\": \"Bishwa Poudel [9:27 A.M.]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I missed my train to Jaipur.\", \"vi\": \"Tôi đã lỡ chuyến tàu đi Jaipur.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Apparently it leaves from another station.\", \"vi\": \"Hình như nó khởi hành từ một nhà ga khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"No other trains can get me to the business forum in time for my keynote address.\", \"vi\": \"Không có chuyến tàu nào khác có thể đưa tôi đến diễn đàn doanh nghiệp kịp giờ phát biểu khai mạc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Any ideas?\", \"vi\": \"Có cao kiến gì không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Shraddha Kher [9:32 A.M.]\", \"vi\": \"Shraddha Kher [9:32 A.M.]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"No problem.\", \"vi\": \"Không có gì.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I\'ll send a car for you.\", \"vi\": \"Tôi sẽ cử một chiếc xe đến đón bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Bishwa Poudel [9:33 A.M.]\", \"vi\": \"Bishwa Poudel [9:33 A.M.]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"What a relief!\", \"vi\": \"Thật nhẹ nhõm biết bao!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Cảm ơn bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The dinner begins at 7 P.M., so if I leave New Delhi within two hours, I should arrive on time.\", \"vi\": \"Bữa tối bắt đầu lúc 7 giờ tối, vì vậy nếu tôi rời New Delhi trong vòng hai tiếng nữa, tôi sẽ đến đúng giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Shraddha Kher [9:34 A.M.]\", \"vi\": \"Shraddha Kher [9:34 A.M.]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Where shall the driver collect you?\", \"vi\": \"Tài xế sẽ đón bạn ở đâu?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Bishwa Poudel [9:35 A.M.]\", \"vi\": \"Bishwa Poudel [9:35 A.M.]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"At the Safdarjung station, Entrance 1.\", \"vi\": \"Tại nhà ga Safdarjung, Lối vào 1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Please confirm when the car is on the way.\", \"vi\": \"Hãy xác nhận khi xe đang trên đường đến nhé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '0fe7ae39-b201-4a23-ada5-ebc2e9317fd5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Akio Nishi [3:35 P.M.]: Did you both see the e-mail from Barbara with furniture options for the lobby?\", \"vi\": \"Akio Nishi [3:35 P.M.]: Cả hai bạn đã xem email từ Barbara về các lựa chọn nội thất cho sảnh chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Isidora Basque [3:37 P.M.]: Look at the brown leather chairs with wheels.\", \"vi\": \"Isidora Basque [3:37 P.M.]: Hãy nhìn những chiếc ghế da màu nâu có bánh xe kìa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"They are so much more stylish than the current chairs.\", \"vi\": \"Chúng trông thời trang hơn rất nhiều so với những chiếc ghế hiện tại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Akio Nishi [3:38 P.M.]: They are attractive, but they don\'t seem sturdy.\", \"vi\": \"Akio Nishi [3:38 P.M.]: Chúng đẹp đấy, nhưng có vẻ không được chắc chắn cho lắm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"What do you think of the big green ones with the plush seats?\", \"vi\": \"Bạn nghĩ gì về những chiếc ghế màu xanh lá lớn có đệm ngồi êm ái?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Kriya Patel [3:39 P.M.]: I am opening it now.\", \"vi\": \"Kriya Patel [3:39 P.M.]: Tôi đang mở email đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Isidora Basque [3:40 P.M.]: They look comfortable.\", \"vi\": \"Isidora Basque [3:40 P.M.]: Trông chúng có vẻ thoải mái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"But space is limited, and we need at least four chairs in the lobby.\", \"vi\": \"Nhưng không gian có hạn, và chúng ta cần ít nhất bốn chiếc ghế ở sảnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Those green chairs are really big.\", \"vi\": \"Những chiếc ghế màu xanh đó thực sự rất lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Kriya Patel [3:42 P.M.]: Are you still looking at the Premium Office section?\", \"vi\": \"Kriya Patel [3:42 P.M.]: Các bạn vẫn đang xem phần Văn phòng Cao cấp (Premium Office) phải không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Akio Nishi [3:43 P.M.]: No, we\'re discussing the Budget Office options now.\", \"vi\": \"Akio Nishi [3:43 P.M.]: Không, chúng ta đang thảo luận về các lựa chọn ở phần Văn phòng Tiết kiệm (Budget Office) bây giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Kriya Patel [3:44 P.M.]: Oh, good.\", \"vi\": \"Kriya Patel [3:44 P.M.]: Ồ, tốt quá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Those choices are more affordable.\", \"vi\": \"Những sự lựa chọn đó có giá cả phải chăng hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Akio Nishi [3:46 P.M.]: We should probably select a reception desk before the chairs.\", \"vi\": \"Akio Nishi [3:46 P.M.]: Có lẽ chúng ta nên chọn bàn lễ tân trước khi chọn ghế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Do you like the second one, the yellow desk?\", \"vi\": \"Bạn có thích cái thứ hai, chiếc bàn màu vàng không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I do.\", \"vi\": \"Tôi thì có đấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Kriya Patel [3:47 P.M.]: I think it would fit nicely in that space.\", \"vi\": \"Kriya Patel [3:47 P.M.]: Tôi nghĩ nó sẽ vừa vặn hoàn hảo trong không gian đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"It is the same size as the current desk.\", \"vi\": \"Nó có kích thước tương đương với chiếc bàn hiện tại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Isidora Basque [3:48 P.M.]: I think it\'s perfect.\", \"vi\": \"Isidora Basque [3:48 P.M.]: Tôi nghĩ nó thật hoàn hảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I\'ll tell Barbara now that we all like that desk.\", \"vi\": \"Tôi sẽ nói với Barbara ngay bây giờ rằng tất cả chúng ta đều thích chiếc bàn đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Let\'s touch base about the chairs after we have had the chance to look at all the choices.\", \"vi\": \"Chúng ta hãy thảo luận lại về những chiếc ghế sau khi đã có cơ hội xem qua tất cả các lựa chọn nhé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '1006c29e-7425-4151-9768-d74a240e7682';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Thank you for purchasing tickets for a tour of the historic Walton Steamship.\", \"vi\": \"Cảm ơn bạn đã mua vé tham quan tàu hơi nước lịch sử Walton.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"If you need to cancel or change your appointment, please be aware of our cancellation policy.\", \"vi\": \"Nếu bạn cần hủy hoặc thay đổi lịch hẹn, vui lòng lưu ý chính sách hủy vé của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Cancellations up to one day before the scheduled tour will receive a refund of 50% per ticket.\", \"vi\": \"Việc hủy vé trước chuyến tham quan theo lịch trình tối đa một ngày sẽ được hoàn tiền 50% mỗi vé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Canceling on the same day or failing to appear at the time of your scheduled tour will result in no refund.\", \"vi\": \"Hủy vé vào cùng ngày hoặc không có mặt vào thời điểm chuyến tham quan theo lịch trình của bạn sẽ không được hoàn tiền.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"All refunds will be credited to the card used to purchase the tickets.\", \"vi\": \"Tất cả các khoản tiền hoàn lại sẽ được chuyển vào thẻ đã sử dụng để mua vé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Please note that tours are conducted both inside the ship and outside on deck.\", \"vi\": \"Xin lưu ý rằng các chuyến tham quan được tổ chức cả ở bên trong tàu và bên ngoài boong tàu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Tours are rarely canceled due to weather.\", \"vi\": \"Các chuyến tham quan hiếm khi bị hủy do thời tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please wear appropriate clothing in case we experience cold or wet weather.\", \"vi\": \"Vui lòng mặc trang phục phù hợp trong trường hợp thời tiết lạnh hoặc ẩm ướt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '101d3078-c2c2-4ab1-aaa9-31b1cf378084';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Delta City Art Museum—Current Exhibits\", \"vi\": \"Bảo tàng Nghệ thuật Thành phố Delta—Các triển lãm hiện tại\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"https://www.deltacityartmuseum.org/exhibits\", \"vi\": \"https://www.deltacityartmuseum.org/exhibits\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The Impressionists, May 1–June 30, Main Gallery\", \"vi\": \"Trường phái Ấn tượng, Ngày 1 tháng 5 – Ngày 30 tháng 6, Phòng trưng bày chính\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Paintings from this well-known nineteenth-century art movement will be on display, including works by both famous and lesser-known artists.\", \"vi\": \"Các bức tranh từ trường phái nghệ thuật thế kỷ XIX nổi tiếng này sẽ được trưng bày, bao gồm các tác phẩm của cả những nghệ sĩ nổi tiếng và ít tên tuổi hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Native American Pottery, May 15–July 16, Shawe Memorial Gallery\", \"vi\": \"Đồ gốm của người Mỹ bản địa, Ngày 15 tháng 5 – Ngày 16 tháng 7, Phòng trưng bày tưởng niệm Shawe\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Visitors to this exhibit will learn about the wide range of pottery-related techniques developed and utilized by Indigenous peoples across North America.\", \"vi\": \"Khách tham quan triển lãm này sẽ tìm hiểu về nhiều loại kỹ thuật liên quan đến đồ gốm được phát triển và sử dụng bởi các dân tộc bản địa trên khắp Bắc Mỹ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Classical Greece and Beyond, May 22–August 21, Techtmann Gallery\", \"vi\": \"Hy Lạp cổ đại và hơn thế nữa, Ngày 22 tháng 5 – Ngày 21 tháng 8, Phòng trưng bày Techtmann\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This exhibit features statues of human subjects from classical Greece, along with modern pieces influenced by the classical style.\", \"vi\": \"Triển lãm này trưng bày các bức tượng về con người từ thời Hy Lạp cổ đại, cùng với các tác phẩm hiện đại mang ảnh hưởng của phong cách cổ điển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Artists of Delta City, Permanent Exhibit, Zhang Atrium\", \"vi\": \"Các nghệ sĩ của Thành phố Delta, Triển lãm thường trực, Sảnh chính Zhang\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This popular exhibit showcases contemporary works by local artists in various media, including oil and watercolor paintings, photographs, fiber art, and mixed-media works.\", \"vi\": \"Triển lãm phổ biến này giới thiệu các tác phẩm đương đại của các nghệ sĩ địa phương trên nhiều chất liệu khác nhau, bao gồm tranh sơn dầu và tranh màu nước, ảnh chụp, nghệ thuật dệt và các tác phẩm đa chất liệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Although the exhibit is ongoing, individual pieces are displayed on a rotating basis and are on view for a limited time only.\", \"vi\": \"Mặc dù triển lãm vẫn đang diễn ra, các tác phẩm riêng lẻ được trưng bày theo hình thức xoay vòng và chỉ được trưng bày trong một thời gian giới hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: Delta City Art Museum <info@deltacityartmuseum.org>\", \"vi\": \"Đến: Bảo tàng Nghệ thuật Thành phố Delta <info@deltacityartmuseum.org>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From: Lorelei Desnoyers <lorelei.desnoyers@klarsenuniversity.edu>\", \"vi\": \"Từ: Lorelei Desnoyers <lorelei.desnoyers@klarsenuniversity.edu>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: May 2\", \"vi\": \"Ngày: Ngày 2 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Subject: Inquiry\", \"vi\": \"Chủ đề: Yêu cầu thông tin\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Good morning,\", \"vi\": \"Kính chào buổi sáng,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I am a new art instructor at Klarsen University.\", \"vi\": \"Tôi là một giảng viên nghệ thuật mới tại Đại học Klarsen.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"One of my colleagues told me that the Delta City Art Museum provides tours for local art students.\", \"vi\": \"Một trong những đồng nghiệp của tôi cho biết Bảo tàng Nghệ thuật Thành phố Delta có cung cấp các chuyến tham quan dành cho sinh viên nghệ thuật địa phương.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I am interested in bringing my Art 103 class to view and sketch some of the pieces you have on display.\", \"vi\": \"Tôi rất quan tâm đến việc đưa lớp Nghệ thuật 103 của mình đến xem và phác thảo một số tác phẩm mà quý bảo tàng đang trưng bày.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Since Art 103 focuses on studying and drawing the human form, the statues will be getting most of our attention.\", \"vi\": \"Vì môn Nghệ thuật 103 tập trung vào việc nghiên cứu và vẽ hình họa cơ thể người, các bức tượng sẽ thu hút phần lớn sự chú ý của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"However, I\'m hoping that we could have a brief tour of the whole museum before we begin our work.\", \"vi\": \"Tuy nhiên, tôi hy vọng rằng chúng tôi có thể có một chuyến tham quan ngắn toàn bộ bảo tàng trước khi bắt đầu công việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Please let me know if this could be arranged.\", \"vi\": \"Xin vui lòng cho tôi biết nếu điều này có thể sắp xếp được.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Thank you in advance for your assistance!\", \"vi\": \"Xin cảm ơn sự hỗ trợ của quý bảo tàng trước!\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Lorelei Desnoyers\", \"vi\": \"Lorelei Desnoyers\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"School of Art & Design\", \"vi\": \"Khoa Nghệ thuật & Thiết kế\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Klarsen University\", \"vi\": \"Đại học Klarsen\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"504-555-0177\", \"vi\": \"504-555-0177\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"To: Lorelei Desnoyers <lorelei.desnoyers@klarsenuniversity.edu>\", \"vi\": \"Đến: Lorelei Desnoyers <lorelei.desnoyers@klarsenuniversity.edu>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"From: Jocelyn Grady <jgrady@deltacityartmuseum.org>\", \"vi\": \"Từ: Jocelyn Grady <jgrady@deltacityartmuseum.org>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Date: May 3\", \"vi\": \"Ngày: Ngày 3 tháng 5\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Subject: RE: Inquiry\", \"vi\": \"Chủ đề: V/v: Yêu cầu thông tin\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Dear Ms. Desnoyers,\", \"vi\": \"Kính gửi Cô Desnoyers,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Thank you for your e-mail.\", \"vi\": \"Cảm ơn cô đã gửi thư điện tử.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Your colleague was correct: the museum does indeed provide that service.\", \"vi\": \"Đồng nghiệp của cô đã nói đúng: bảo tàng thực sự cung cấp dịch vụ đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"We would likely schedule you on a Tuesday, since that is typically our least busy day.\", \"vi\": \"Chúng tôi có thể sẽ xếp lịch cho cô vào một ngày Thứ Ba, vì đó thường là ngày ít khách nhất của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"I have forwarded your message to our office of public programs.\", \"vi\": \"Tôi đã chuyển tiếp tin nhắn của cô đến văn phòng chương trình công cộng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"A staff member will contact you by phone with more details.\", \"vi\": \"Một nhân viên sẽ liên hệ với cô qua điện thoại để cung cấp thêm chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Please note that the use of paints, including watercolors, is prohibited in all museum galleries.\", \"vi\": \"Xin lưu ý rằng việc sử dụng chất liệu sơn, bao gồm cả màu nước, bị cấm ở tất cả các phòng trưng bày của bảo tàng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Pencils and charcoal are permitted, although visitors are asked to take care not to leave smudges on museum surfaces.\", \"vi\": \"Bút chì và than vẽ được phép sử dụng, mặc dù khách tham quan được yêu cầu cẩn thận để tránh để lại vết bẩn trên các bề mặt của bảo tàng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"We also allow photography and video recording as long as patrons are considerate of other visitors.\", \"vi\": \"Chúng tôi cũng cho phép chụp ảnh và quay video miễn là khách tham quan lịch sự và ý thức với những người khác.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"We are grateful for your interest in Delta City Art Museum and look forward to hosting your class.\", \"vi\": \"Chúng tôi rất biết ơn vì sự quan tâm của cô đối với Bảo tàng Nghệ thuật Thành phố Delta và mong sớm được đón tiếp lớp học của cô.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Jocelyn Grady\", \"vi\": \"Jocelyn Grady\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Information and Community Outreach\", \"vi\": \"Ban Thông tin và Tiếp cận Cộng đồng\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Delta City Art Museum\", \"vi\": \"Bảo tàng Nghệ thuật Thành phố Delta\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}]' WHERE `id` = '102359d8-ac82-4572-84f1-1ec39e750746';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mehan Motors Appoints New CEO\", \"vi\": \"Mehan Motors Bổ Nhiệm Giám Đốc Điều Hành Mới\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"By Jonas Schulz\", \"vi\": \"Bởi Jonas Schulz\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"DETROIT (January 2)—This will be a year of firsts at Mehan Motors.\", \"vi\": \"DETROIT (Ngày 2 tháng 1)—Đây sẽ là một năm của những dấu mốc đầu tiên tại Mehan Motors.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"For the first time in its 35-year history, the company is changing its top leadership; Mehan will soon welcome the first American and the first woman to hold the title of CEO.\", \"vi\": \"Lần đầu tiên trong lịch sử 35 năm hoạt động, công ty đang thay đổi bộ máy lãnh đạo cấp cao; Mehan sẽ sớm chào đón vị Giám đốc điều hành là người Mỹ đầu tiên và cũng là phụ nữ đầu tiên giữ chức vụ này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dana Loeb will begin her tenure at Mehan Motors on February 1, the company announced yesterday.\", \"vi\": \"Dana Loeb sẽ bắt đầu nhiệm kỳ của mình tại Mehan Motors vào ngày 1 tháng 2, công ty đã thông báo vào ngày hôm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Ms. Loeb graduated with top honors from Clover University of Technology in Boston, where she completed a degree in electrical engineering.\", \"vi\": \"Bà Loeb tốt nghiệp thủ khoa tại Đại học Công nghệ Clover ở Boston, nơi bà hoàn thành bằng kỹ sư điện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"She eventually rose to lead the electric vehicle (EV) division at Tafts Motors in Detroit.\", \"vi\": \"Cuối cùng, bà đã thăng tiến để lãnh đạo bộ phận xe điện (EV) tại Tafts Motors ở Detroit.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Within two years, the company promoted her to the position of chief operating officer.\", \"vi\": \"Trong vòng hai năm, công ty đã thăng chức cho bà lên vị trí giám đốc vận hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Ms. Loeb eventually left her position at Tafts Motors to become CEO of the British car company Norana, where she spearheaded the introduction of its popular subcompact EV, the Radar.\", \"vi\": \"Bà Loeb sau đó đã rời bỏ vị trí của mình tại Tafts Motors để trở thành Giám đốc điều hành của công ty ô tô Anh Quốc Norana, nơi bà đi đầu trong việc giới thiệu dòng xe điện cỡ nhỏ rất được ưa chuộng của hãng, chiếc Radar.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Within its category, this vehicle achieved a stunning 20% higher range on a single charge than its nearest EV competitor.\", \"vi\": \"Trong cùng phân khúc, chiếc xe này đạt được phạm vi hoạt động chỉ với một lần sạc cao hơn đáng kể 20% so với đối thủ cạnh tranh xe điện gần nhất của nó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Ms. Loeb summarized her vision for Mehan Motors in a recent interview.\", \"vi\": \"Bà Loeb đã tóm tắt tầm nhìn của mình đối với Mehan Motors trong một cuộc phỏng vấn gần đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"“I look forward to leveraging the company’s abundant talent to build EVs that are affordable to a mass market.\", \"vi\": \"“Tôi rất mong được tận dụng nguồn nhân tài phong phú của công ty để chế tạo ra những chiếc xe điện có giá cả phải chăng cho thị trường đại chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The vehicles must be offered at a price that is reasonable for the average consumer.”\", \"vi\": \"Các phương tiện phải được cung cấp ở mức giá hợp lý đối với người tiêu dùng trung bình.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '102d8fb1-2294-4b48-8419-2aa0913eef8f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"New Theatre Almost Ready\", \"vi\": \"Nhà hát mới sắp hoàn thành\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"By Nigel Smith\", \"vi\": \"Bởi Nigel Smith\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"LIVERPOOL (15 August)—Work is nearing completion on a new theatre, which will become the first new theatre in the city for the past 20 years.\", \"vi\": \"LIVERPOOL (15 tháng 8)—Công việc đang tiến gần đến giai đoạn hoàn thành tại một nhà hát mới, nơi sẽ trở thành nhà hát mới đầu tiên trong thành phố trong 20 năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The Cricket Theatre, which is being built on the site of the former Fletcher shoe factory, will have an auditorium that can seat 400 patrons.\", \"vi\": \"Nhà hát Cricket, được xây dựng trên khu đất của nhà máy giày Fletcher cũ, sẽ có một phòng khán giả có sức chứa 400 khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The theatre will be operated by the Watts-Spicer Group, which owns three other theatres, two in London and one in York.\", \"vi\": \"Nhà hát sẽ do Tập đoàn Watts-Spicer vận hành, tập đoàn hiện sở hữu ba nhà hát khác, hai ở Luân Đôn và một ở York.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The venue is expected to open in October, said Watts-Spicer\'s chairperson, Colin Watts.\", \"vi\": \"Địa điểm này dự kiến sẽ mở cửa vào tháng 10, ông Colin Watts, chủ tịch của Watts-Spicer cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"\\\"We have just completed the longest stage of the project, which was slower than expected due to back-ordered seats from Australia.\", \"vi\": \"\\\"Chúng tôi vừa hoàn thành giai đoạn dài nhất của dự án, vốn chậm hơn dự kiến do những chiếc ghế đặt hàng từ Úc bị giao hàng chậm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We are expecting to open with the musical Backup on 30 October.\\\"\", \"vi\": \"Chúng tôi dự kiến mở màn với vở nhạc kịch Backup vào ngày 30 tháng 10.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The Cricket Theatre will host a variety of productions, from traditional plays to special engagements with artists of all kinds.\", \"vi\": \"Nhà hát Cricket sẽ tổ chức nhiều chương trình biểu diễn đa dạng, từ các vở kịch truyền thống cho đến các buổi biểu diễn đặc biệt với các nghệ sĩ đủ mọi thể loại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Cricket Theatre\'s Backup Is Wonderful\", \"vi\": \"Vở Backup của Nhà hát Cricket thật tuyệt vời\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"By Clara Kennedy\", \"vi\": \"Bởi Clara Kennedy\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"LIVERPOOL (2 December)—The Cricket Theatre\'s first production, Backup, opened last night to a full house.\", \"vi\": \"LIVERPOOL (2 tháng 12)—Buổi biểu diễn đầu tiên của Nhà hát Cricket, Backup, đã mở màn tối qua với khán phòng kín chỗ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Theatregoers were clearly delighted by this new musical, which is based on a true story.\", \"vi\": \"Những người đi xem kịch tỏ ra vô cùng thích thú với vở nhạc kịch mới này, vốn được dựa trên một câu chuyện có thật.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Backup follows Babette Jones, a young backup singer for famous musical acts, through her 23-year struggle to become a successful solo act.\", \"vi\": \"Backup kể về Babette Jones, một ca sĩ hát bè trẻ tuổi cho các nghệ sĩ âm nhạc nổi tiếng, trong hành trình 23 năm chật vật để trở thành một ca sĩ solo thành công.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Liverpool native Tami McClure, as Ms. Jones, thrilled the audience with her wide-ranging vocals.\", \"vi\": \"Người gốc Liverpool Tami McClure, trong vai cô Jones, đã làm say đắm khán giả với chất giọng đa dạng của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Paul Robinson, who played her fearless manager, also put in a strong performance.\", \"vi\": \"Paul Robinson, người thủ vai người quản lý đầy quyết đoán của cô, cũng có một màn thể hiện vô cùng ấn tượng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Costume designer Sophie Wright\'s fashions were exquisite.\", \"vi\": \"Các thiết kế trang phục của nhà thiết kế Sophie Wright rất tinh tế.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Backup\'s strong production values and the Cricket Theatre\'s reasonable ticket prices point to a long and successful future for this new theatre.\", \"vi\": \"Giá trị sản xuất vững chắc của Backup và giá vé hợp lý của Nhà hát Cricket cho thấy một tương lai lâu dài và thành công đối với nhà hát mới này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Backup runs until 5 February at the Cricket Theatre.\", \"vi\": \"Vở Backup được công diễn cho đến ngày 5 tháng 2 tại Nhà hát Cricket.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '1031659c-2d9a-4d3b-ab83-16034fa5e9b4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Teksheen Supply >> Products >> Natural Hand Soap\", \"vi\": \"Teksheen Supply >> Sản phẩm >> Xà phòng rửa tay từ thiên nhiên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Many brands of hand soap contain unnecessary chemicals.\", \"vi\": \"Nhiều thương hiệu xà phòng rửa tay chứa các hóa chất không cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"For those who ------- (135) a soap with no added artificial substances, Teksheen Supply\'s natural hand soap is the ideal choice.\", \"vi\": \"Đối với những ai ------- (135) một loại xà phòng không có các chất nhân tạo bổ sung, xà phòng rửa tay tự nhiên của Teksheen Supply là sự lựa chọn lý tưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"This unscented soap is packaged in a handy dispenser bottle.\", \"vi\": \"Loại xà phòng không mùi này được đóng gói trong chai vòi xịt tiện dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"------- (136) patented formula is designed to keep your hands clean yet soft with a mix of natural vitamins and oils.\", \"vi\": \"------- (136) công thức được cấp bằng sáng chế được thiết kế để giữ cho đôi tay của bạn sạch sẽ nhưng vẫn mềm mại với sự kết hợp của các loại vitamin và dầu tự nhiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [136]}, {\"en\": \"------- (137).\", \"vi\": \"------- (137).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [137]}, {\"en\": \"Do you operate a business and want a safe and effective hand soap manufactured through sustainable processes?\", \"vi\": \"Bạn đang điều hành một doanh nghiệp và muốn tìm một loại xà phòng rửa tay an toàn, hiệu quả được sản xuất thông qua các quy trình bền vững?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If so, you may purchase this ------- (138) in bulk at discounted prices.\", \"vi\": \"Nếu có, bạn có thể mua sản phẩm ------- (138) này với số lượng lớn theo giá ưu đãi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [138]}, {\"en\": \"Visit our Ordering page for details.\", \"vi\": \"Hãy truy cập trang Đặt hàng của chúng tôi để biết chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '10648874-eea1-4877-8f92-af7a4032c102';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Shipping Disruptions\", \"vi\": \"Gián đoạn vận chuyển\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"SINGAPORE (6 June)—Recently, the demand for international freight space has been outpacing the availability of shipping containers.\", \"vi\": \"SINGAPORE (Ngày 6 tháng 6)—Gần đây, nhu cầu về không gian vận chuyển hàng hóa quốc tế đang vượt quá số lượng container vận chuyển có sẵn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This container shortage has led to higher costs for goods being shipped out of Asian ports.\", \"vi\": \"Tình trạng thiếu hụt container này đã dẫn đến chi phí cao hơn đối với hàng hóa được vận chuyển ra khỏi các cảng của châu Á.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"A drop in the production of rolls of steel, the raw material that containers are made from, has further complicated the situation.\", \"vi\": \"Sự sụt giảm trong sản lượng cuộn thép, nguyên liệu thô dùng để chế tạo container, càng làm tình hình thêm phức tạp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Some exporters have considered the more expensive option of air freight, but companies are still faced with a difficult choice.\", \"vi\": \"Một số nhà xuất khẩu đã cân nhắc phương án vận chuyển hàng không tốn kém hơn, nhưng các công ty vẫn phải đối mặt với một lựa chọn khó khăn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"They must either ask their customers to accept shipment delays, or substantially raise customer prices to cover the costs of expedited shipping.\", \"vi\": \"Họ hoặc phải yêu cầu khách hàng chấp nhận việc giao hàng chậm trễ, hoặc tăng đáng kể giá bán cho khách hàng để bù đắp chi phí vận chuyển nhanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Either way, suppliers risk triggering customer dissatisfaction.\", \"vi\": \"Dù theo cách nào, các nhà cung cấp cũng có nguy cơ làm khách hàng bất满.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"\\\"We are working with business partners, investors, and government officials to discuss solutions to this problem,\\\" said Henry Lam, a spokesperson for the household goods producer QET Group.\", \"vi\": \"\\\"Chúng tôi đang làm việc với các đối tác kinh doanh, nhà đầu tư và các quan chức chính phủ để thảo luận các giải pháp cho vấn đề này,\\\" Henry Lam, người phát ngôn của nhà sản xuất hàng gia dụng QET Group cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"\\\"It\'s going to take total cooperation of all stakeholders to find a solution.\\\"\", \"vi\": \"\\\"Sẽ cần sự hợp tác toàn diện của tất cả các bên liên quan để tìm ra giải pháp.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Not all companies are suffering, though.\", \"vi\": \"Tuy nhiên, không phải tất cả các công ty đều chịu thiệt hại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"For example, Fezker, the producer of athletic apparel and footwear, has implemented strategies to better overcome this situation.\", \"vi\": \"Ví dụ, Fezker, nhà sản xuất trang phục và giày dép thể thao, đã thực hiện các chiến lược để vượt qua tình hình này tốt hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Fezker has successfully refocused its efforts away from exports to western countries and toward expanding its domestic and regional markets.\", \"vi\": \"Fezker đã chuyển hướng thành công các nỗ lực của mình khỏi việc xuất khẩu sang các nước phương Tây và hướng tới việc mở rộng thị trường nội địa và khu vực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"\\\"We moved quickly, so the shipping container shortage has not caused a significant impact on our profits,\\\" said Fezker CEO Nuwa Lee.\", \"vi\": \"\\\"Chúng tôi đã hành động nhanh chóng, vì vậy tình trạng thiếu hụt container vận chuyển đã không gây ra tác động đáng kể đến lợi nhuận của chúng tôi,\\\" Giám đốc điều hành Fezker, Nuwa Lee cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '10819da1-59cb-4a55-bec2-4502a6551d00';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Before making travel arrangements, all Saffler Bank employees ______[139] authorization.\", \"vi\": \"Trước khi sắp xếp việc đi lại, tất cả nhân viên của Saffler Bank ______[139] sự cho phép.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [139]}, {\"en\": \"Only after approval has been granted can travel plans be made.\", \"vi\": \"Chỉ sau khi được phê duyệt thì các kế hoạch đi lại mới có thể được thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To request authorization, fill out the first side of the Travel Reimbursement Form.\", \"vi\": \"Để yêu cầu cấp phép, hãy điền vào mặt đầu tiên của Mẫu đơn Hoàn chi phí Đi lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Here you will provide the reason for your ______[140].\", \"vi\": \"Tại đây, bạn sẽ cung cấp lý do cho chuyến ______[140] của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [140]}, {\"en\": \"Next, submit the form ______[141] an estimate for the cost of travel to your destination.\", \"vi\": \"Tiếp theo, hãy nộp mẫu đơn ______[141] bảng ước tính chi phí đi lại tới điểm đến của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [141]}, {\"en\": \"Upon returning, do not forget to fill out the second side of the form, where you will report mileage and expenses.\", \"vi\": \"Khi trở về, đừng quên điền vào mặt thứ hai của mẫu đơn, nơi bạn sẽ báo cáo số dặm đã đi và các khoản chi phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Inclusion of receipts is required.\", \"vi\": \"Việc đính kèm hóa đơn là bắt buộc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Expenses for which you cannot show a receipt, such as parking meters and tips, are also reimbursable.\", \"vi\": \"Các chi phí mà bạn không thể xuất trình hóa đơn, chẳng hạn như phí đỗ xe và tiền boa, cũng được hoàn lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[142].\", \"vi\": \"______[142].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [142]}]' WHERE `id` = '10985c6b-293b-4c80-a439-7535ef2927c5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Monorail Coming to Sudbury\", \"vi\": \"Tàu điện một ray sắp đến Sudbury\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"(4 Feb.)—Ottawa-based Saenger, Inc., has been selected by the city of Sudbury to build a monorail system that will connect the city\'s commercial district to the airport.\", \"vi\": \"(4 Th.2) — Công ty Saenger, Inc. có trụ sở tại Ottawa đã được thành phố Sudbury lựa chọn để xây dựng một hệ thống tàu điện một ray kết nối khu thương mại của thành phố với sân bay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Funding for the system is drawn from a combination of public agencies and private investors.\", \"vi\": \"Kinh phí cho hệ thống được lấy từ sự kết hợp giữa các cơ quan nhà nước và các nhà đầu tư tư nhân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Ticket sales for the monorail will also provide a new source of revenue for the city.\", \"vi\": \"Doanh thu bán vé tàu điện một ray cũng sẽ mang lại một nguồn thu nhập mới cho thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Construction is slated to begin in early June and is expected to be completed within four years.\", \"vi\": \"Việc xây dựng dự kiến bắt đầu vào đầu tháng Sáu và hoàn thành trong vòng bốn năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '10f53eda-ac82-4b39-ae96-48ef033973f6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Chloe Willis\", \"vi\": \"Đến: Chloe Willis\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Steven Emery\", \"vi\": \"Từ: Steven Emery\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: August 19\", \"vi\": \"Ngày: 19 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Wonder Luggage\", \"vi\": \"Chủ đề: Wonder Luggage\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Willis,\", \"vi\": \"Kính gửi bà Willis,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"It was a pleasure meeting you when I stopped in earlier today.\", \"vi\": \"Thật là vinh hạnh khi được gặp bà lúc tôi ghé qua vào đầu ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As we discussed, I am looking for a new location for my luggage store.\", \"vi\": \"Như chúng ta đã thảo luận, tôi đang tìm kiếm một địa điểm mới cho cửa hàng bán vali của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We are currently operating from a small retail unit in the Sandway Mall, but I would like to move to a larger space in its own building.\", \"vi\": \"Hiện tại chúng tôi đang hoạt động tại một cửa hàng bán lẻ nhỏ trong Trung tâm thương mại Sandway, nhưng tôi muốn chuyển đến một không gian rộng rãi hơn trong một tòa nhà riêng biệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"A spacious display area is required, and on-site parking for customers would be a bonus.\", \"vi\": \"Cần có khu vực trưng bày rộng rãi và bãi đậu xe tại chỗ cho khách hàng sẽ là một điểm cộng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The maximum I prefer to spend on rent per month is $5,500.\", \"vi\": \"Mức giá thuê tối đa mỗi tháng mà tôi ưu tiên là 5.500 USD.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I would like to have the business open at the new location by November 20, as that would allow our store to participate in the launch of Mizara’s new Eco-Max luggage line.\", \"vi\": \"Tôi muốn cửa hàng được khai trương tại địa điểm mới trước ngày 20 tháng 11, vì điều đó sẽ cho phép cửa hàng của chúng tôi tham gia vào lễ ra mắt dòng vali Eco-Max mới của Mizara.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please let me know if you find anything that would suit my needs.\", \"vi\": \"Vui lòng cho tôi biết nếu bà tìm thấy bất kỳ địa điểm nào phù hợp với nhu cầu của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I am available any day next week to view possible sites.\", \"vi\": \"Tôi rảnh vào bất kỳ ngày nào trong tuần tới để đi xem các địa điểm tiềm năng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Warmest regards,\", \"vi\": \"Trân trọng nhất,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Steven Emery\", \"vi\": \"Steven Emery\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Owner, Wonder Luggage\", \"vi\": \"Chủ cửa hàng Wonder Luggage\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"To: Steven Emery\", \"vi\": \"Đến: Steven Emery\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"From: Chloe Willis\", \"vi\": \"Từ: Chloe Willis\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Date: August 20\", \"vi\": \"Ngày: 20 tháng 8\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Subject: Re: Wonder Luggage\", \"vi\": \"Chủ đề: V/v: Wonder Luggage\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Dear Mr. Emery,\", \"vi\": \"Kính gửi ông Emery,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I have done some research on retail units that would be appropriate for your business.\", \"vi\": \"Tôi đã thực hiện một số nghiên cứu về các mặt bằng bán lẻ phù hợp cho việc kinh doanh của ông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Please see the list below and let me know if there are any that you would like to visit in person.\", \"vi\": \"Vui lòng xem danh sách dưới đây và cho tôi biết nếu có địa điểm nào ông muốn đến tham quan trực tiếp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"1.\", \"vi\": \"1.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Address: 1258 Tolliver Street\", \"vi\": \"Địa chỉ: 1258 Tolliver Street\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Square Footage: 7,512 / Monthly Rent: $5,500\", \"vi\": \"Diện tích: 7.512 foot vuông / Giá thuê hàng tháng: 5.500 USD\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Notes: This unit was previously owned by a clothing store, and the display area has been recently renovated.\", \"vi\": \"Ghi chú: Đơn vị này trước đây thuộc sở hữu của một cửa hàng quần áo, và khu vực trưng bày đã được cải tạo gần đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"2.\", \"vi\": \"2.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Address: 908 Braxton Avenue\", \"vi\": \"Địa chỉ: 908 Braxton Avenue\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Square Footage: 8,940 / Monthly Rent: $5,000\", \"vi\": \"Diện tích: 8.940 foot vuông / Giá thuê hàng tháng: 5.000 USD\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Notes: The building owner requires the rental of the adjoining parking lot in a separate lease at $450 per month.\", \"vi\": \"Ghi chú: Chủ tòa nhà yêu cầu thuê bãi đậu xe liền kề theo một hợp đồng cho thuê riêng với giá 450 USD mỗi tháng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"3.\", \"vi\": \"3.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Address: 446 Cabell Street\", \"vi\": \"Địa chỉ: 446 Cabell Street\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Square Footage: 9,650 / Monthly Rent: $6,000\", \"vi\": \"Diện tích: 9.650 foot vuông / Giá thuê hàng tháng: 6.000 USD\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Notes: The foot traffic in this area is very high.\", \"vi\": \"Ghi chú: Lưu lượng người qua lại ở khu vực này rất cao.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"There is a public parking area across the street.\", \"vi\": \"Có một bãi đậu xe công cộng nằm ở bên kia đường.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Chloe Willis\", \"vi\": \"Chloe Willis\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"487-555-0149\", \"vi\": \"487-555-0149\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Wonder Luggage Finds New Home\", \"vi\": \"Wonder Luggage Tìm Được Địa Điểm Mới\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"by Katheryn Clark\", \"vi\": \"bởi Katheryn Clark\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"STRAFFORD (November 10)—Wonder Luggage—an independently owned business selling a range of suitcases, roller bags, carry-on luggage, and more—held its grand re-opening yesterday at its new location.\", \"vi\": \"STRAFFORD (10 tháng 11)—Wonder Luggage—một doanh nghiệp độc lập chuyên bán các loại vali, túi kéo, hành lý xách tay và nhiều sản phẩm khác—đã tổ chức lễ khai trương lại vào ngày hôm qua tại địa điểm mới của mình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Previously operating from the Sandway Mall, the store has found a new home at 908 Braxton Avenue.\", \"vi\": \"Trước đây hoạt động tại Trung tâm thương mại Sandway, cửa hàng đã tìm thấy một địa điểm mới tại số 908 đại lộ Braxton.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"It is open daily from 9 A.M. to 8 P.M.\", \"vi\": \"Cửa hàng mở cửa hàng ngày từ 9 giờ sáng đến 8 giờ tối.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"Most of the staff members remain the same, and they can advise customers on what sort of bag to purchase.\", \"vi\": \"Hầu hết các nhân viên vẫn giữ nguyên và họ có thể tư vấn cho khách hàng loại túi nào nên mua.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"Owner Steven Emery says that he is excited about the new location and that the store will continue to sell high-quality luggage that can endure rough handling.\", \"vi\": \"Chủ cửa hàng Steven Emery cho biết ông rất hào hứng với địa điểm mới và cửa hàng sẽ tiếp tục bán những sản phẩm hành lý chất lượng cao có thể chịu được việc va đập mạnh.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 46, \"question_numbers\": []}, {\"en\": \"Shoppers will love not only the products but also the atmosphere, as the new location has large windows, so it isn’t as dark as the mall unit.\", \"vi\": \"Người mua sắm sẽ không chỉ yêu thích các sản phẩm mà còn cả bầu không khí ở đây, vì địa điểm mới có những ô cửa sổ lớn, nhờ đó không gian không bị tối như ở khu cửa hàng trong trung tâm thương mại.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 47, \"question_numbers\": []}, {\"en\": \"If you are looking for a long-lasting bag and excellent customer service, I highly recommend stopping by Wonder Luggage.\", \"vi\": \"Nếu bạn đang tìm kiếm một chiếc túi bền lâu và dịch vụ chăm sóc khách hàng tuyệt vời, tôi thực sự khuyên bạn nên ghé qua Wonder Luggage.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 48, \"question_numbers\": []}]' WHERE `id` = '10f54a3f-7825-4f5e-871d-f39b6146507c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Artie Jeffers [5:40 P.M.]\", \"vi\": \"Artie Jeffers [5:40 P.M.]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Sun Jung, the overhead lights in the conference room are blinking oddly.\", \"vi\": \"Sun Jung ơi, các bóng đèn trần trong phòng họp đang nhấp nháy một cách lạ thường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I called the maintenance hotline, but no one answered.\", \"vi\": \"Tôi đã gọi đến đường dây nóng bảo trì nhưng không ai trả lời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Is anyone from maintenance still in for the day?\", \"vi\": \"Có nhân viên bảo trì nào vẫn còn ở lại trong ngày hôm nay không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Sun Jung Park [5:41 P.M.]\", \"vi\": \"Sun Jung Park [5:41 P.M.]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Oh no!\", \"vi\": \"Ôi không!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We have a meeting there in 20 minutes with the Larkspur executives.\", \"vi\": \"Chúng ta có một cuộc họp ở đó sau 20 phút nữa với các giám đốc điều hành của Larkspur.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Try sending a message to Patty Grant.\", \"vi\": \"Hãy thử gửi tin nhắn cho Patty Grant xem.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"She is the head of maintenance and usually works late.\", \"vi\": \"Cô ấy là trưởng bộ phận bảo trì và thường làm việc muộn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Artie Jeffers [5:45 P.M.]\", \"vi\": \"Artie Jeffers [5:45 P.M.]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Good news!\", \"vi\": \"Tin vui đây!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Patty has already responded.\", \"vi\": \"Patty đã phản hồi rồi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"A crew is on the way now to address the problem.\", \"vi\": \"Một đội ngũ đang trên đường đến để giải quyết vấn đề ngay bây giờ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '11093009-bb02-42ad-9566-da9d8a1dbab4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Monday, October 16: Wollaston St.\", \"vi\": \"Thứ Hai, ngày 16 tháng 10: Phố Wollaston.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Tuesday, October 17: Moringa Rd.\", \"vi\": \"Thứ Ba, ngày 17 tháng 10: Đường Moringa.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Wednesday, October 18: Blackwood St.\", \"vi\": \"Thứ Tư, ngày 18 tháng 10: Phố Blackwood.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Thursday, October 19: Satinwood Ave.\", \"vi\": \"Thứ Năm, ngày 19 tháng 10: Đại lộ Satinwood.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Friday, October 20: No work scheduled (national holiday)\", \"vi\": \"Thứ Sáu, ngày 20 tháng 10: Không có lịch làm việc (ngày lễ quốc gia)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"City to Upgrade Aging Gas Pipes\", \"vi\": \"Thành phố nâng cấp các đường ống dẫn khí đốt cũ kỹ\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"GAS SYSTEM UPGRADE SCHEDULE\", \"vi\": \"LỊCH TRÌNH NÂNG CẤP HỆ THỐNG KHÍ ĐỐT\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"(September 1)—During the month of October, Nairobi Energy Services, Inc., (NESI) plans to replace two kilometers of cast-iron underground gas pipes with plastic-coated steel pipes as part of its commitment to maintaining the city\'s energy infrastructure.\", \"vi\": \"(Ngày 1 tháng 9)—Trong suốt tháng 10, Công ty Dịch vụ Năng lượng Nairobi (NESI) lên kế hoạch thay thế hai ki-lô-mét đường ống dẫn khí đốt ngầm bằng gang bằng các ống thép phủ nhựa như một phần trong cam kết duy trì cơ sở hạ tầng năng lượng của thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"The increase in pressure provided by the new pipes will better support today\'s high-efficiency furnaces, water heaters, clothes dryers, and other gas appliances,\\\" said Ms. Esther Cheptumo, the gas company\'s vice president.\", \"vi\": \"Bà Esther Cheptumo, phó chủ tịch công ty khí đốt, cho biết: \\\"Sự gia tăng áp suất được cung cấp bởi các đường ống mới sẽ hỗ trợ tốt hơn cho các lò sưởi hiệu suất cao, máy nước nóng, máy sấy quần áo và các thiết bị gas khác ngày nay.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"\\\"The new system will ensure safe and reliable gas delivery for years to come.\\\"\", \"vi\": \"\\\"Hệ thống mới sẽ đảm bảo cung cấp khí đốt an toàn và đáng tin cậy trong nhiều năm tới.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Some streets in Nairobi will be closed to traffic between 9:00 A.M. and 4:00 P.M. while pipes are replaced.\", \"vi\": \"Một số đường phố ở Nairobi sẽ bị cấm phương tiện qua lại từ 9:00 sáng đến 4:00 chiều trong khi các đường ống được thay thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The gas company is working with city officials to develop a schedule that will minimize the inconvenience.\", \"vi\": \"Công ty khí đốt đang làm việc với các quan chức thành phố để xây dựng một lịch trình nhằm giảm thiểu sự bất tiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The schedule will be updated daily on the company\'s Web site as well as in all local newspapers.\", \"vi\": \"Lịch trình sẽ được cập nhật hàng ngày trên trang web của công ty cũng như trên tất cả các tờ báo địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Customers who experience a significant problem due to the work schedule should contact the gas company with their concerns.\", \"vi\": \"Những khách hàng gặp sự cố đáng kể do lịch trình công việc nên liên hệ với công ty khí đốt để trình bày các thắc mắc của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"When work on your street has been completed, a NESI technician will come to your house to connect your service line.\", \"vi\": \"Khi công việc trên đường phố của bạn hoàn tất, một kỹ thuật viên của NESI sẽ đến nhà bạn để kết nối đường ống dịch vụ của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To: Peter Abonyo <pabonyo@mailergrip.com>\", \"vi\": \"Đến: Peter Abonyo <pabonyo@mailergrip.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"From: Judith Kamau <jkamau@nesi.co.ke>\", \"vi\": \"Từ: Judith Kamau <jkamau@nesi.co.ke>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date: October 12\", \"vi\": \"Ngày: 12 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Re: Account No. A0194\", \"vi\": \"V/v: Tài khoản số A0194\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Dear Mr. Abonyo,\", \"vi\": \"Kính gửi ông Abonyo,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Your street is scheduled for gas pipe replacement on Tuesday, October 17.\", \"vi\": \"Đường phố của bạn có lịch thay thế đường ống dẫn khí đốt vào thứ Ba, ngày 17 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Technicians will be available to reconnect your gas lines between 3:00 P.M. and 8:00 P.M. Please call us at 555-0181 to schedule a time for the work to be completed.\", \"vi\": \"Các kỹ thuật viên sẽ có mặt để kết nối lại các đường ống dẫn khí đốt của bạn trong khoảng thời gian từ 3:00 chiều đến 8:00 tối. Vui lòng gọi cho chúng tôi theo số 555-0181 để sắp xếp thời gian hoàn thành công việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Gas service to your home will be interrupted for about one hour while the reconnection work is done.\", \"vi\": \"Dịch vụ cung cấp khí đốt cho ngôi nhà của bạn sẽ bị gián đoạn khoảng một giờ trong khi công việc kết nối lại được thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Xin cảm ơn.\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Judith Kamau\", \"vi\": \"Judith Kamau\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '1140ed20-3755-451b-88d4-85149ac73381';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Joseph Morgan <joseph.morgan@peltergraphics.com>\", \"vi\": \"Đến: Joseph Morgan <joseph.morgan@peltergraphics.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: administrator@costaseminars.org\", \"vi\": \"Từ: administrator@costaseminars.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 31\", \"vi\": \"Ngày: 31 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Book order\", \"vi\": \"Chủ đề: Đơn đặt sách\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Quantity - Title - Price - Discounted Price - Total Price\", \"vi\": \"Số lượng - Tiêu đề - Giá - Giá đã giảm - Tổng giá\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"1 - Perfected Figures: Making Data Visually Appealing - $22.00 - $17.60 - $17.60\", \"vi\": \"1 - Perfected Figures: Making Data Visually Appealing - $22.00 - $17.60 - $17.60\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"1 - Logos in the Information Age - $18.00 - $14.40 - $14.40\", \"vi\": \"1 - Logos in the Information Age - $18.00 - $14.40 - $14.40\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"1 - Branding Strategies in Graphic Design - $20.00 - $16.00 - $16.00\", \"vi\": \"1 - Branding Strategies in Graphic Design - $20.00 - $16.00 - $16.00\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"2 - Best Practices in Web Design: A European Perspective - $28.00 - $22.40 - $44.80\", \"vi\": \"2 - Best Practices in Web Design: A European Perspective - $28.00 - $22.40 - $44.80\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"TOTAL DUE: $92.80\", \"vi\": \"TỔNG TIỀN THANH TOÁN: $92.80\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Dear Mr. Morgan,\", \"vi\": \"Kính gửi Ông Morgan,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Thank you for registering for Emilio Costa\'s seminar on June 11 at the Rothford Business Center.\", \"vi\": \"Cảm ơn ông đã đăng ký tham gia hội thảo của Emilio Costa vào ngày 11 tháng 6 tại Trung tâm Kinh doanh Rothford.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We are glad you took advantage of the opportunity for conference participants to purchase some of Emilio Costa\'s graphic-design books at a discounted price.\", \"vi\": \"Chúng tôi rất vui vì ông đã tận dụng cơ hội dành cho người tham gia hội nghị để mua một số sách thiết kế đồ họa của Emilio Costa với mức giá ưu đãi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The information below is a confirmation of your order.\", \"vi\": \"Thông tin dưới đây là xác nhận cho đơn hàng của ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The books will be waiting for you at the check-in desk on the day of the seminar.\", \"vi\": \"Sách sẽ được chuẩn bị sẵn cho ông tại quầy đăng ký vào ngày diễn ra hội thảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Please note that we will accept any major credit card for payment.\", \"vi\": \"Xin lưu ý rằng chúng tôi sẽ chấp nhận bất kỳ thẻ tín dụng chính nào để thanh toán.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"We are looking forward to seeing you on June 11.\", \"vi\": \"Chúng tôi rất mong được gặp ông vào ngày 11 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Attention, Seminar Participants:\", \"vi\": \"Thông báo dành cho những người tham gia hội thảo:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Unfortunately, we do not have copies of Emilio Costa\'s book Branding Strategies in Graphic Design with us today.\", \"vi\": \"Rất tiếc, chúng tôi không có sẵn các bản sao cuốn sách Branding Strategies in Graphic Design của Emilio Costa ở đây ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"For those of you who have ordered it, please give your mailing address to the volunteer at the check-in desk, and the book will be mailed to your home at no cost to you.\", \"vi\": \"Đối với những ai đã đặt mua, vui lòng cung cấp địa chỉ gửi thư của quý vị cho tình nguyện viên tại quầy đăng ký, và cuốn sách sẽ được gửi qua bưu điện đến nhà quý vị hoàn toàn miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We will charge your credit card upon shipment.\", \"vi\": \"Chúng tôi sẽ tính phí vào thẻ tín dụng của quý vị khi giao hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"We are sorry for the inconvenience.\", \"vi\": \"Chúng tôi thành thật xin lỗi vì sự bất tiện này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"To: roberta.tsu@peltergraphics.com\", \"vi\": \"Đến: roberta.tsu@peltergraphics.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"From: joseph.morgan@peltergraphics.com\", \"vi\": \"Từ: joseph.morgan@peltergraphics.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Date: June 22\", \"vi\": \"Ngày: 22 tháng 6\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Sent: Costa book\", \"vi\": \"Chủ đề: Sách của Costa\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Dear Roberta,\", \"vi\": \"Roberta thân mến,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I\'m looking forward to finishing up our brochure design for Entchen Financial Consultants.\", \"vi\": \"Tôi đang mong chờ hoàn thành thiết kế tập gấp cho công ty Tư vấn Tài chính Entchen.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Before we submit our final draft, I would like to rethink how we are presenting our data.\", \"vi\": \"Trước khi chúng ta nộp bản thảo cuối cùng, tôi muốn suy nghĩ lại về cách chúng ta trình bày dữ liệu của mình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Have you had a chance to look through the Costa book I showed you?\", \"vi\": \"Bạn đã có cơ hội xem qua cuốn sách của Costa mà tôi đưa cho bạn xem chưa?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"He gives great advice on improving the clarity of financial information in marketing materials.\", \"vi\": \"Ông ấy đưa ra những lời khuyên tuyệt vời về việc cải thiện tính rõ ràng của thông tin tài chính trong tài liệu tiếp thị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Anyway, let\'s talk about it at lunch tomorrow.\", \"vi\": \"Dù sao đi nữa, hãy thảo luận về nó vào bữa trưa ngày mai nhé.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Thân ái,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Joseph\", \"vi\": \"Joseph\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '118e15b7-a972-42de-a605-18aed5a6072d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Jobomatch.co.uk\\nEmployment Search Platform\", \"vi\": \"Jobomatch.co.uk\\nNền tảng tìm kiếm việc làm\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.jobomatch.co.uk\", \"vi\": \"http://www.jobomatch.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Hello, Charlotte Rigby\", \"vi\": \"Xin chào, Charlotte Rigby\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Manage your job preferences\", \"vi\": \"Quản lý sở thích công việc của bạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Sharing your preferences will help us to match you with your ideal employers.\", \"vi\": \"Việc chia sẻ sở thích của bạn sẽ giúp chúng tôi kết nối bạn với những nhà tuyển dụng lý tưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"What are your desired job areas?\", \"vi\": \"Lĩnh vực công việc mong muốn của bạn là gì?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Customer support, customer service, technical support\", \"vi\": \"Hỗ trợ khách hàng, dịch vụ khách hàng, hỗ trợ kỹ thuật\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"What type of work are you looking for?\", \"vi\": \"Bạn đang tìm kiếm loại hình công việc nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Full-time\", \"vi\": \"Toàn thời gian\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Where do you live?\", \"vi\": \"Bạn sống ở đâu?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Provide postal code\", \"vi\": \"Cung cấp mã bưu chính\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"L22 3AB\", \"vi\": \"L22 3AB\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"How far are you willing to commute?\", \"vi\": \"Bạn sẵn sàng di chuyển đi làm cách bao xa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"☑ Within a 15 km radius\", \"vi\": \"☑ Trong bán kính 15 km\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"☐ Within a 25 km radius\", \"vi\": \"☐ Trong bán kính 25 km\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"☐ Within a 60 km radius\", \"vi\": \"☐ Trong bán kính 60 km\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Would you consider relocation?\", \"vi\": \"Bạn có cân nhắc việc chuyển đến nơi ở mới không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"No\", \"vi\": \"Không\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Jobomatch.co.uk\\nEmployment Search Results\", \"vi\": \"Jobomatch.co.uk\\nKết quả tìm kiếm việc làm\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"http://www.jobomatch.co.uk\", \"vi\": \"http://www.jobomatch.co.uk\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Hello, Charlotte Rigby\", \"vi\": \"Xin chào, Charlotte Rigby\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Jobs Based On Your Preferences\", \"vi\": \"Việc làm dựa trên sở thích của bạn\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Customer Service Associate\", \"vi\": \"Nhân viên dịch vụ khách hàng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Quisco Ltd., Liverpool\", \"vi\": \"Quisco Ltd., Liverpool\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Responsibilities include receiving and recording feedback and complaints from customers and responding in a courteous manner.\", \"vi\": \"Trách nhiệm bao gồm tiếp nhận và ghi nhận các phản hồi và khiếu nại từ khách hàng và phản hồi một cách lịch sự.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Must have strong customer service skills.\", \"vi\": \"Phải có kỹ năng dịch vụ khách hàng tốt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Shift schedule is variable.\", \"vi\": \"Lịch làm việc theo ca thay đổi linh hoạt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Required to be available evenings, weekends, and holidays.\", \"vi\": \"Yêu cầu có thể làm việc vào buổi tối, cuối tuần và ngày lễ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Customer Service Attendant\", \"vi\": \"Nhân viên chăm sóc khách hàng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Denville Telecom, Liverpool\", \"vi\": \"Denville Telecom, Liverpool\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Responsibilities include opening and processing repair requests from clients.\", \"vi\": \"Trách nhiệm bao gồm mở và xử lý các yêu cầu sửa chữa từ khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Must be fluent in English and one additional language.\", \"vi\": \"Phải thành thạo tiếng Anh và một ngôn ngữ bổ sung.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Customer service staff will attend seminars on using electronic database programs to file repair progress reports.\", \"vi\": \"Nhân viên dịch vụ khách hàng sẽ tham gia các buổi hội thảo về cách sử dụng các chương trình cơ sở dữ liệu điện tử để lập báo cáo tiến độ sửa chữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"From: crigby@zifmail.co.uk\", \"vi\": \"Từ: crigby@zifmail.co.uk\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"To: office@quiscoltd.co.uk\", \"vi\": \"Đến: office@quiscoltd.co.uk\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Date: 2 March\", \"vi\": \"Ngày: Ngày 2 tháng 3\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Subject: Customer Support Position\", \"vi\": \"Chủ đề: Vị trí Hỗ trợ Khách hàng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Rigby_CV\", \"vi\": \"Tệp đính kèm: 📎 Rigby_CV\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"To Whom It May Concern,\", \"vi\": \"Kính gửi bộ phận liên quan,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"I am very interested in the Customer Service Associate position that is available at Quisco Ltd. As my attached CV shows, this opportunity is an excellent match for my qualifications.\", \"vi\": \"Tôi rất quan tâm đến vị trí Nhân viên Dịch vụ Khách hàng hiện đang trống tại Quisco Ltd. Như CV đính kèm của tôi cho thấy, cơ hội này hoàn toàn phù hợp với trình độ chuyên môn của tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"I have worked in customer support positions for companies in Dublin and Lancaster, and I graduated from the Powell School in York.\", \"vi\": \"Tôi đã làm việc ở các vị trí hỗ trợ khách hàng cho các công ty ở Dublin và Lancaster, và tôi tốt nghiệp trường Powell School ở York.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"I am fully able to meet all the requirements of the available position.\", \"vi\": \"Tôi hoàn toàn có khả năng đáp ứng tất cả các yêu cầu của vị trí tuyển dụng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Thank you for your consideration.\", \"vi\": \"Cảm ơn quý công ty đã xem xét.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"Charlotte Rigby\", \"vi\": \"Charlotte Rigby\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}]' WHERE `id` = '11951772-5266-426c-8b1f-6fc2619f9f9a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"New Conference Scholarships from Wenford Technologies\", \"vi\": \"Học bổng Hội nghị mới từ Wenford Technologies\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"(Jan. 2)—Wenford Technologies, an industry leader in Internet services, has announced that it will offer six scholarships to qualified candidates to attend the Breakthroughs in Computer Science Conference in Newark, New Jersey, from April 21 to 23.\", \"vi\": \"(Ngày 2 tháng 1)—Wenford Technologies, công ty dẫn đầu ngành dịch vụ Internet, đã thông báo rằng họ sẽ cung cấp sáu suất học bổng cho các ứng viên đủ điều kiện để tham dự Hội nghị Những đột phá trong Khoa học Máy tính tại Newark, New Jersey, từ ngày 21 đến 23 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To encourage a greater global perspective among conference participants, two individuals each from Latin America, Africa, and Asia will be selected as scholarship recipients.\", \"vi\": \"Để khuyến khích góc nhìn toàn cầu lớn hơn trong số các đại biểu tham dự hội nghị, mỗi khu vực Mỹ Latinh, Châu Phi và Châu Á sẽ chọn ra hai cá nhân nhận học bổng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"\\\"We believe that a variety of perspectives is what helps our industry grow and thrive,\\\" explained Wenford Technologies\' CEO Dale Kelvin.\", \"vi\": \"\\\"Chúng tôi tin rằng sự đa dạng về góc nhìn là điều giúp ngành của chúng tôi phát triển và thịnh vượng,\\\" Dale Kelvin, Giám đốc điều hành của Wenford Technologies, giải thích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"To this end, we would like to extend this opportunity to professionals from certain geographic regions.\\\"\", \"vi\": \"\\\"Vì mục đích này, chúng tôi muốn mở rộng cơ hội này cho các chuyên gia từ một số khu vực địa lý nhất định.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Applicants must be employed full-time in computer science for a period of between one and five years in order to be eligible.\", \"vi\": \"Các ứng viên phải làm việc toàn thời gian trong lĩnh vực khoa học máy tính trong khoảng thời gian từ một đến năm năm mới đủ điều kiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"For more information about the scholarships, visit wenfordtech.com/scholarships.\", \"vi\": \"Để biết thêm thông tin về học bổng, hãy truy cập wenfordtech.com/scholarships.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"8:30 A.M.–9:00 A.M. - Continental breakfast—Food will be available in the reception hall.\", \"vi\": \"8:30 Sáng – 9:00 Sáng - Bữa sáng kiểu lục địa—Đồ ăn sẽ được phục vụ tại sảnh đón tiếp.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"9:00 A.M.–9:30 A.M. - Announcements\", \"vi\": \"9:00 Sáng – 9:30 Sáng - Thông báo\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"9:40 A.M.–Noon - Presentations\", \"vi\": \"9:40 Sáng – 12:00 Trưa - Thuyết trình\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Noon–1:00 P.M. - Lunch break—Conference attendees will be on their own. There are many reasonably priced dining establishments within walking distance of the conference venue.\", \"vi\": \"12:00 Trưa – 1:00 Chiều - Giờ nghỉ trưa—Người tham dự hội nghị sẽ tự túc. Có rất nhiều nhà hàng có giá cả phải chăng trong khoảng cách đi bộ từ địa điểm tổ chức hội nghị.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"1:00 P.M.–4:00 P.M. - Workshops\", \"vi\": \"1:00 Chiều – 4:00 Chiều - Hội thảo chuyên đề\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"4:00 P.M.–5:15 P.M. - Panel discussions and session evaluations\", \"vi\": \"4:00 Chiều – 5:15 Chiều - Thảo luận nhóm và đánh giá phiên họp\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Breakthroughs in Computer Science Conference\", \"vi\": \"Hội nghị Những đột phá trong Khoa học Máy tính\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Preliminary Schedule, April 21–23\", \"vi\": \"Lịch trình Dự kiến, ngày 21–23 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Below is an outline of activities for the conference.\", \"vi\": \"Dưới đây là phác thảo các hoạt động cho hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Each day will follow the same format.\", \"vi\": \"Mỗi ngày sẽ tuân theo cùng một định dạng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"A final schedule with speakers\' names and their affiliations will be available two months prior to the event.\", \"vi\": \"Lịch trình chính thức với tên của các diễn giả và đơn vị công tác của họ sẽ có sẵn hai tháng trước sự kiện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To: Cindy Connelly <cconnelly@wenfordtech.com>\", \"vi\": \"Đến: Cindy Connelly <cconnelly@wenfordtech.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: Adamu Adebayo <aadebayo@spmail.co.za>\", \"vi\": \"Từ: Adamu Adebayo <aadebayo@spmail.co.za>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date: 3 February\", \"vi\": \"Ngày: 3 tháng 2\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subject: Scholarship thanks\", \"vi\": \"Chủ đề: Cảm ơn học bổng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Dear Ms. Connelly,\", \"vi\": \"Kính gửi bà Connelly,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Sincere thanks to Wenford Technologies for supporting my attendance at the Breakthroughs conference.\", \"vi\": \"Chân thành cảm ơn Wenford Technologies đã hỗ trợ tôi tham gia hội nghị Đột phá.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"It is an exciting opportunity for me, and I am really looking forward to learning from others in the same field who work in different parts of the world.\", \"vi\": \"Đây là một cơ hội tuyệt vời đối với tôi, và tôi rất mong được học hỏi từ những người khác trong cùng lĩnh vực làm việc ở các nơi khác nhau trên thế giới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I would like to mention that I lead a daily client conference call at 2:30 P.M. (the time in Johannesburg) that I am unable to cancel.\", \"vi\": \"Tôi xin phép được đề cập rằng tôi chủ trì một cuộc gọi hội nghị hàng ngày với khách hàng vào lúc 2:30 chiều (giờ ở Johannesburg) mà tôi không thể hủy bỏ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"This task would start at 9:30 A.M. in Newark, and it will require my attention for 30 minutes or so.\", \"vi\": \"Công việc này sẽ bắt đầu lúc 9:30 sáng ở Newark, và nó sẽ đòi hỏi sự tập trung của tôi trong khoảng 30 phút.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Otherwise, I hope to participate fully in all conference proceedings.\", \"vi\": \"Ngoài thời gian đó, tôi hy vọng sẽ tham gia đầy đủ vào tất cả các hoạt động của hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Please let me know if there is any information you might still need from me.\", \"vi\": \"Vui lòng cho tôi biết nếu có bất kỳ thông tin nào bạn vẫn cần từ tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Adamu Adebayo\", \"vi\": \"Adamu Adebayo\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = '11c8cc82-622f-4276-b4bf-b2b5e1bc8a07';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: dianepaxton@lamail.com\", \"vi\": \"Đến: dianepaxton@lamail.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: customerservice@lenfordfinancial.co.uk\", \"vi\": \"Từ: customerservice@lenfordfinancial.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Online Account\", \"vi\": \"Chủ đề: Tài khoản trực tuyến\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 22 June\", \"vi\": \"Ngày: 22 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Paxton,\", \"vi\": \"Kính gửi Bà Paxton,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for your interest in Lenford Financial.\", \"vi\": \"Cảm ơn quý khách đã quan tâm đến Lenford Financial.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We have received your online inquiry and have issued a temporary username and password.\", \"vi\": \"Chúng tôi đã nhận được yêu cầu trực tuyến của quý khách và đã cấp tên đăng nhập cùng mật khẩu tạm thời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To activate your online account, please follow these steps.\", \"vi\": \"Để kích hoạt tài khoản trực tuyến của mình, vui lòng làm theo các bước sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"1.\", \"vi\": \"1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Go to our Web site and select \\\"New Registration.\\\"\", \"vi\": \"Truy cập trang web của chúng tôi và chọn \\\"Đăng ký mới\\\".\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"2.\", \"vi\": \"2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Log in using username DPAXTON and password XA098T.\", \"vi\": \"Đăng nhập bằng tên đăng nhập DPAXTON và mật khẩu XA098T.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"You will be prompted to create a new username and password.\", \"vi\": \"Quý khách sẽ được nhắc tạo tên đăng nhập và mật khẩu mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"3.\", \"vi\": \"3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"A new-customer survey will pop up.\", \"vi\": \"Một bảng khảo sát dành cho khách hàng mới sẽ hiện lên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Fill out the survey with information about your financial profile.\", \"vi\": \"Điền vào bảng khảo sát các thông tin về hồ sơ tài chính của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"4.\", \"vi\": \"4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"After you submit the survey, one of our account representatives will call you within 24 hours to discuss your portfolio and future investments.\", \"vi\": \"Sau khi quý khách gửi bảng khảo sát, một trong số các đại diện tài khoản của chúng tôi sẽ gọi cho quý khách trong vòng 24 giờ để thảo luận về danh mục đầu tư và các khoản đầu tư trong tương lai của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We look forward to helping you attain your financial goals.\", \"vi\": \"Chúng tôi rất mong được hỗ trợ quý khách đạt được các mục tiêu tài chính của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Kent Rawlin\", \"vi\": \"Kent Rawlin\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Customer Account Representative\", \"vi\": \"Đại diện Quản lý Tài khoản Khách hàng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '11e43f5c-f8b9-4241-8dc5-5b1b20ee4a58';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Don\'t have time to go to your local Songmin clinic for a minor medical issue?\", \"vi\": \"Bạn không có thời gian đến phòng khám Songmin địa phương để xử lý một vấn đề y tế nhỏ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"E-visits are a convenient way to get help wherever you are.\", \"vi\": \"Khám trực tuyến là một cách thuận tiện để nhận trợ giúp dù bạn ở bất cứ đâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Simply follow these steps:\", \"vi\": \"Chỉ cần làm theo các bước sau:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Go to our Web site (www.songminhealth.com) and sign in.\", \"vi\": \"Truy cập trang web của chúng tôi (www.songminhealth.com) và đăng nhập.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hover your mouse over the \\\"E-visits\\\" tab and select \\\"Start an E-visit\\\" from the drop-down menu.\", \"vi\": \"Di chuyển chuột qua tab \\\"E-visits\\\" và chọn \\\"Start an E-visit\\\" từ menu thả xuống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Answer the questions on the resulting form about your symptoms and concerns.\", \"vi\": \"Trả lời các câu hỏi trên biểu mẫu hiện ra về các triệu chứng và mối lo ngại của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Be as clear and specific as possible.\", \"vi\": \"Hãy rõ ràng và cụ thể nhất có thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Submit the form.\", \"vi\": \"Gửi biểu mẫu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Check your e-mail inbox for the response from a Songmin doctor.\", \"vi\": \"Kiểm tra hộp thư điện tử của bạn để xem phản hồi từ bác sĩ Songmin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"It may include advice, a referral for testing, or a prescription for medication.\", \"vi\": \"Phản hồi có thể bao gồm lời khuyên, giấy giới thiệu xét nghiệm hoặc đơn thuốc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"If you do not receive a response within two business hours, or if there is a change in your symptoms, please call our assistance line at 1-800-555-0138.\", \"vi\": \"Nếu bạn không nhận được phản hồi trong vòng hai giờ làm việc, hoặc nếu có sự thay đổi về triệu chứng của bạn, vui lòng gọi đến đường dây hỗ trợ của chúng tôi theo số 1-800-555-0138.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"SONGMIN HEALTH\", \"vi\": \"Y TẾ SONGMIN\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '120eea13-0f29-4dae-9a53-b26a0a0aa7ee';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Lovitt Real Estate\", \"vi\": \"Lovitt Real Estate\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Helping Manitoba Families Find their Dream Homes\", \"vi\": \"Giúp các gia đình ở Manitoba tìm ngôi nhà mơ ước\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Manuel Lovitt, ___135___ of Lovitt Real Estate, has been selling real estate for over 17 years.\", \"vi\": \"Manuel Lovitt, ___135___ của Lovitt Real Estate, đã hoạt động trong lĩnh vực môi giới bất động sản hơn 17 năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"Mr. Lovitt and his award-winning team --___136___ in homes for families in the Winnipeg, Brandon, and Dauphin areas.\", \"vi\": \"Ông Lovitt và đội ngũ từng đạt giải thưởng của mình --___136___ chuyên về nhà ở cho các gia đình tại khu vực Winnipeg, Brandon và Dauphin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"They know about the schools, parks, services, transportation, and activities that enhance family life in the area where you want to reside.\", \"vi\": \"Họ nắm rõ về trường học, công viên, dịch vụ, giao thông và các hoạt động làm phong phú thêm đời sống gia đình tại khu vực bạn muốn sinh sống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"___137___.\", \"vi\": \"___137___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [137]}, {\"en\": \"Contact Lovitt Real Estate today and let the team guide you ___138___ the home of your dreams.\", \"vi\": \"Hãy liên hệ với Lovitt Real Estate ngay hôm nay và để đội ngũ hướng dẫn bạn ___138___ ngôi nhà mơ ước của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [138]}, {\"en\": \"They will listen to your needs, negotiate on your behalf, and get you the best home for your hard-earned money.\", \"vi\": \"Họ sẽ lắng nghe nhu cầu của bạn, đàm phán thay cho bạn và giúp bạn có được ngôi nhà tốt nhất xứng đáng với số tiền kiếm được bằng mồ hôi công sức của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Call 431-555-0168 to speak to an agent or visit www.lovittrealestate.ca for more information.\", \"vi\": \"Hãy gọi số 431-555-0168 để nói chuyện với một nhân viên môi giới hoặc truy cập www.lovittrealestate.ca để biết thêm thông tin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '122afe01-7dc0-40d5-bb00-ff8d9f549785';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Special Announcement by Geoff Clifford, President of Moon Glow Airways\", \"vi\": \"Thông báo đặc biệt bởi Geoff Clifford, Chủ tịch của Moon Glow Airways\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.moonglowairways.com.au\", \"vi\": \"http://www.moonglowairways.com.au\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"As many of you are aware, there was a problem with Pelman Technology, the system that handles our airline reservations.\", \"vi\": \"Như nhiều quý vị đã biết, đã có một sự cố xảy ra với Pelman Technology, hệ thống xử lý các đặt chỗ chuyến bay của hãng hàng không chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"This outage has affected several airlines.\", \"vi\": \"Sự cố gián đoạn này đã ảnh hưởng đến một số hãng hàng không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"It\'s been a rough week, but the good news is that it has been repaired, and we are re-setting our system.\", \"vi\": \"Đó là một tuần khó khăn, nhưng tin vui là sự cố đã được khắc phục và chúng tôi đang thiết lập lại hệ thống của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"However, Moon Glow passengers may still face delays for a day or two.\", \"vi\": \"Tuy nhiên, hành khách đi hãng Moon Glow có thể vẫn sẽ phải đối mặt với tình trạng chậm chuyến trong một hoặc hai ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This most likely will include longer lines at airports.\", \"vi\": \"Điều này rất có thể sẽ bao gồm việc xếp hàng dài hơn tại các sân bay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We have added more on-site customer service representatives at airports in all of our destination cities to assist customers with their flights and information.\", \"vi\": \"Chúng tôi đã bổ sung thêm nhiều nhân viên dịch vụ khách hàng tại chỗ ở các sân bay tại tất cả các thành phố điểm đến của chúng tôi để hỗ trợ khách hàng về các chuyến bay và thông tin của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We appreciate your understanding and patience.\", \"vi\": \"Chúng tôi đánh giá cao sự thông cảm và kiên nhẫn của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '12c3e96c-1d9b-4c67-9286-81589968961b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Acadetech\", \"vi\": \"Acadetech\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Over ten years serving individuals\", \"vi\": \"Hơn mười năm phục vụ các cá nhân\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"as well as small- and mid-sized businesses\", \"vi\": \"cũng như các doanh nghiệp vừa và nhỏ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"What we do:\", \"vi\": \"Chúng tôi làm gì:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Responsive Web site design with secure e-commerce functionality\", \"vi\": \"Thiết kế trang web tương thích với mọi thiết bị cùng tính năng thương mại điện tử bảo mật\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Multilingual content development and management\", \"vi\": \"Phát triển và quản lý nội dung đa ngôn ngữ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Branding and marketing\", \"vi\": \"Xây dựng thương hiệu và tiếp thị\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Prices begin at $200 for a basic five-page Web site in English.\", \"vi\": \"Giá khởi điểm từ 200 đô la cho một trang web cơ bản gồm năm trang bằng tiếng Anh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Expedited design available.\", \"vi\": \"Có dịch vụ thiết kế nhanh theo yêu cầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Call or e-mail us today for a consultation!\", \"vi\": \"Hãy gọi điện hoặc gửi email cho chúng tôi ngay hôm nay để được tư vấn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Customer reviews:\", \"vi\": \"Đánh giá của khách hàng:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"\\\"My business has had a boost since the launch of the great new Web site designed by Mr. Alexander.\", \"vi\": \"\\\"Việc kinh doanh của tôi đã khởi sắc kể từ khi ra mắt trang web mới tuyệt vời do ông Alexander thiết kế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The super-secure e-commerce tools make shopping easy and safe for my customers.\\\"\", \"vi\": \"Các công cụ thương mại điện tử cực kỳ bảo mật giúp việc mua sắm trở nên dễ dàng và an toàn cho khách hàng của tôi.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"—Juliu Melo, Flowers To Go\", \"vi\": \"—Juliu Melo, Flowers To Go\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"\\\"Acadetech is the best!\", \"vi\": \"\\\"Acadetech là tuyệt vời nhất!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I needed to accommodate a large variety of customers, and they listened.\", \"vi\": \"Tôi cần phục vụ rất nhiều đối tượng khách hàng khác nhau, và họ đã lắng nghe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thanks to their responsive design, my site is just as functional on mobile phones and tablets as on big desktop screens.\\\"\", \"vi\": \"Nhờ thiết kế tương thích, trang web của tôi hoạt động hiệu quả trên điện thoại di động và máy tính bảng cũng như trên màn hình máy tính để bàn lớn.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"—Erik Schroeder, Jamestown Catering\", \"vi\": \"—Erik Schroeder, Jamestown Catering\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '12cf7ccd-a523-484f-ab08-fe1930ce8d81';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Personal Statements\", \"vi\": \"Tuyên bố cá nhân\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Personal statements are brief pieces of writing that showcase a job applicant\'s most notable talents, accomplishments, and qualities.\", \"vi\": \"Tuyên bố cá nhân là những bài viết ngắn gọn thể hiện những tài năng, thành tựu và phẩm chất nổi bật nhất của người ứng tuyển công việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Personal statements are evaluated both for the facts and details they offer and for the way the writer conveys this information.\", \"vi\": \"Tuyên bố cá nhân được đánh giá cả về các sự kiện và chi tiết mà chúng cung cấp lẫn cách thức người viết truyền tải thông tin này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Therefore, when you are composing a personal statement, it is important to be thoughtful about issues such as word choice and tone.\", \"vi\": \"Do đó, khi bạn soạn thảo một bản tuyên bố cá nhân, điều quan trọng là phải suy nghĩ kỹ lưỡng về các vấn đề như lựa chọn từ ngữ và phong cách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Though there is no set length for personal statements, employers sometimes offer guidelines.\", \"vi\": \"Mặc dù không có độ dài cố định cho các tuyên bố cá nhân, các nhà tuyển dụng đôi khi đưa ra các hướng dẫn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If the employer does not provide a word count, aim for between 300 and 500 words.\", \"vi\": \"Nếu nhà tuyển dụng không cung cấp số lượng từ, hãy hướng tới độ dài từ 300 đến 500 từ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"One page is generally considered the maximum length.\", \"vi\": \"Một trang thường được coi là độ dài tối đa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"When crafting a personal statement, provide concrete examples of times when you had to rely on your unique qualities.\", \"vi\": \"Khi soạn thảo một bản tuyên bố cá nhân, hãy đưa ra các ví dụ cụ thể về những thời điểm bạn phải dựa vào những phẩm chất độc đáo của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"This can be an effective way of demonstrating to a prospective employer your ability to overcome challenges.\", \"vi\": \"Điều này có thể là một cách hiệu quả để chứng minh cho nhà tuyển dụng tiềm năng khả năng vượt qua thử thách của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It is also a good idea to give examples of how you work with or learn from others.\", \"vi\": \"Cũng nên đưa ra các ví dụ về cách bạn làm việc cùng hoặc học hỏi từ những người khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Do not forget to mention the specific job you are applying for and explain why you would be a good fit.\", \"vi\": \"Đừng quên đề cập đến công việc cụ thể mà bạn đang ứng tuyển và giải thích lý do tại sao bạn là người phù hợp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Your final paragraph is an ideal place for this information, as you can create a separate version of this paragraph for each position you apply for.\", \"vi\": \"Đoạn văn cuối cùng của bạn là nơi lý tưởng cho thông tin này, vì bạn có thể tạo một phiên bản riêng của đoạn văn này cho mỗi vị trí bạn ứng tuyển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Finally, ensure that you have carefully proofread your statement before submitting it.\", \"vi\": \"Cuối cùng, hãy đảm bảo rằng bạn đã đọc kỹ lại bản tuyên bố của mình trước khi nộp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '12ee5a5b-94ac-49a9-ba28-3c3249e3062d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Clarke-Ellis Construction\", \"vi\": \"Công ty Xây dựng Clarke-Ellis\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"#20 Murphy Industrial Park\", \"vi\": \"Khu công nghiệp Murphy #20\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"St. Michael BB23028\", \"vi\": \"St. Michael BB23028\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"1-246-555-0126\", \"vi\": \"1-246-555-0126\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Full-service commercial contractor serving all of Barbados\", \"vi\": \"Nhà thầu xây dựng thương mại toàn diện phục vụ toàn bộ Barbados\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"4 June\", \"vi\": \"Ngày 4 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Ida Gutierrez\", \"vi\": \"Ida Gutierrez\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Darling Cove Inn\", \"vi\": \"Nhà trọ Darling Cove\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Mango Drive\", \"vi\": \"Đường Mango\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Folkestone BB24017\", \"vi\": \"Folkestone BB24017\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Dear Ms. Gutierrez,\", \"vi\": \"Kính gửi bà Gutierrez,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Thank you for contacting Clarke-Ellis Construction for your roofing project.\", \"vi\": \"Cảm ơn bà đã liên hệ với Công ty Xây dựng Clarke-Ellis cho dự án lợp mái của bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"After inspecting the property, I have confirmed that the inn\'s main roof is in good condition and requires no repairs at this time.\", \"vi\": \"Sau khi kiểm tra tài sản, tôi đã xác nhận rằng phần mái chính của nhà trọ đang ở tình trạng tốt và không cần sửa chữa vào lúc này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"However, the roof of the inn\'s porch appears to be at least twenty years old and is worn beyond repair.\", \"vi\": \"Tuy nhiên, phần mái hiên của nhà trọ có vẻ đã ít nhất hai mươi năm tuổi và đã cũ hỏng không thể sửa chữa được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Clarke-Ellis Construction can remove and dispose of the existing porch roof and install a new one.\", \"vi\": \"Công ty Xây dựng Clarke-Ellis có thể tháo dỡ và xử lý phần mái hiên hiện tại và lắp đặt một mái hiên mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The replacement will be comparable to the quality, style, and colour of the inn\'s main roof.\", \"vi\": \"Phần thay thế sẽ có chất lượng, kiểu dáng và màu sắc tương đương với phần mái chính của nhà trọ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We will use only commercial-grade leak barriers, insulation, and shingles manufactured by West Indies Weatherproofing, Inc. The estimated total cost, inclusive of labour and materials, is $3,260.\", \"vi\": \"Chúng tôi sẽ chỉ sử dụng các vật liệu chống thấm, vật liệu cách nhiệt và ngói lợp đạt chuẩn thương mại do công ty West Indies Weatherproofing, Inc. sản xuất. Tổng chi phí ước tính, bao gồm cả nhân công và vật liệu, là 3.260 USD.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Additional fees would apply should you want us to make other improvements, such as painting the porch or replacing porch screens.\", \"vi\": \"Các chi phí bổ sung sẽ được áp dụng nếu bà muốn chúng tôi thực hiện các cải tạo khác, chẳng hạn như sơn hiên nhà hoặc thay thế lưới chống côn trùng ở hiên nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Please call me at the number above to discuss scheduling or any questions you have about the work.\", \"vi\": \"Vui lòng gọi cho tôi theo số điện thoại ở trên để thảo luận về lịch trình hoặc bất kỳ câu hỏi nào bà có về công việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I hope to hear from you soon.\", \"vi\": \"Tôi mong sớm nhận được phản hồi từ bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Grayson Clarke\", \"vi\": \"Grayson Clarke\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Grayson Clarke, Co-owner, Clarke-Ellis Construction\", \"vi\": \"Grayson Clarke, Đồng sở hữu, Công ty Xây dựng Clarke-Ellis\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '12fd2ad8-92ec-4c30-9ea6-2e5ce0d7cab4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Attention: All Randall-Humboldt Employees\", \"vi\": \"Thông báo: Tất cả nhân viên của Randall-Humboldt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Randall-Humboldt recently experienced a reduction in mail-room staffing.\", \"vi\": \"Randall-Humboldt gần đây đã trải qua việc cắt giảm nhân sự phòng thư tín.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"------- (143), starting on October 7, mail will no longer be delivered to employees\' desks.\", \"vi\": \"------- (143), bắt đầu từ ngày 7 tháng 10, thư sẽ không còn được giao đến bàn làm việc của nhân viên nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [143]}, {\"en\": \"Departments will be responsible for picking up and distributing their own mail.\", \"vi\": \"Các phòng ban sẽ chịu trách nhiệm nhận và phân phối thư của chính mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Each department ------- (144) one employee to handle mail duties.\", \"vi\": \"Mỗi phòng ban ------- (144) một nhân viên để xử lý các nhiệm vụ về thư tín.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [144]}, {\"en\": \"It is up to the department head to determine how best to assign this responsibility.\", \"vi\": \"Trưởng phòng có trách nhiệm quyết định cách tốt nhất để phân công trách nhiệm này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Mail will be available for pickup by 10:00 A.M. each morning.\", \"vi\": \"Thư sẽ có sẵn để nhận trước 10:00 sáng mỗi ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It is strongly recommended ------- (145) employees contact senders of unwanted or junk mail and ask to be removed from those mailing lists.\", \"vi\": \"Chúng tôi đặc biệt khuyến nghị ------- (145) nhân viên liên hệ với người gửi thư rác hoặc thư không mong muốn và yêu cầu xóa tên khỏi các danh sách gửi thư đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [145]}, {\"en\": \"------- (146).\", \"vi\": \"------- (146).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [146]}, {\"en\": \"It will also benefit the environment by reducing waste.\", \"vi\": \"Điều này cũng sẽ mang lại lợi ích cho môi trường bằng cách giảm thiểu rác thải.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '135abb36-7d7b-4dcf-880c-ca869e662477';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Home      About Us      Products      Testimonials\", \"vi\": \"Trang chủ     Về chúng tôi     Sản phẩm     Đánh giá của khách hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dannla Brothers can help you make the most of your screen time.\", \"vi\": \"Dannla Brothers có thể giúp bạn tận dụng tối đa thời gian sử dụng màn hình của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Computers are an important part of our lives, and laptops in particular have become the default type of computer in the workplace.\", \"vi\": \"Máy tính là một phần quan trọng trong cuộc sống của chúng ta, và máy tính xách tay nói riêng đã trở thành loại máy tính mặc định tại nơi làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"They enable users to work not only from home or the office but virtually anywhere.\", \"vi\": \"Chúng cho phép người dùng làm việc không chỉ từ nhà hoặc văn phòng mà hầu như ở bất kỳ đâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"No matter where you choose to work, Dannla Brothers has products to maximize your productivity in front of the screen.\", \"vi\": \"Dù bạn chọn làm việc ở đâu, Dannla Brothers luôn có các sản phẩm giúp tối đa hóa năng suất của bạn trước màn hình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We manufacture ergonomic laptop stands, comfortable chairs, and adjustable standing desks, among other products.\", \"vi\": \"Chúng tôi sản xuất giá đỡ laptop công thái học, ghế ngồi thoải mái và bàn đứng có thể điều chỉnh, cùng các sản phẩm khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Because you use our products all day every business day, we constantly strive to improve their design.\", \"vi\": \"Vì bạn sử dụng sản phẩm của chúng tôi cả ngày vào mọi ngày làm việc, chúng tôi không ngừng nỗ lực cải tiến thiết kế của chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Built to last, every item we sell is backed by a ten-year guarantee on construction and finish.\", \"vi\": \"Được chế tạo để sử dụng lâu dài, mọi mặt hàng chúng tôi bán đều được hỗ trợ bởi chế độ bảo hành mười năm về kết cấu và lớp phủ hoàn thiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We invite you to visit our Testimonials page to review independent assessments of our products by noted business and technology publications.\", \"vi\": \"Chúng tôi mời bạn truy cập trang Đánh giá của khách hàng để xem xét các đánh giá độc lập về sản phẩm của chúng tôi từ các ấn phẩm kinh doanh và công nghệ nổi tiếng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To view our offerings and their features, visit our Products page.\", \"vi\": \"Để xem các dịch vụ và tính năng của chúng tôi, hãy truy cập trang Sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Note that we offer free standard shipping on all orders over $150.\", \"vi\": \"Xin lưu ý rằng chúng tôi cung cấp dịch vụ vận chuyển tiêu chuẩn miễn phí cho tất cả các đơn hàng trên 150 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Expedited delivery is available for an extra fee.\", \"vi\": \"Dịch vụ giao hàng nhanh có sẵn với một khoản phí bổ sung.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"If you represent a business organization seeking to provide ergonomic solutions to your entire staff, we can offer a substantial volume discount.\", \"vi\": \"Nếu bạn đại diện cho một tổ chức doanh nghiệp đang tìm kiếm giải pháp công thái học cho toàn bộ nhân viên của mình, chúng tôi có thể cung cấp mức chiết khấu theo số lượng đáng kể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To receive a free price quote for a bulk order, please e-mail us at info@dannlabrothers.com.\", \"vi\": \"Để nhận báo giá miễn phí cho đơn hàng số lượng lớn, vui lòng gửi email cho chúng tôi theo địa chỉ info@dannlabrothers.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We will respond to your inquiry within 24 hours.\", \"vi\": \"Chúng tôi sẽ phản hồi yêu cầu của bạn trong vòng 24 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"https://www.dannlabrothers.com/about\", \"vi\": \"https://www.dannlabrothers.com/about\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '13d55838-da58-427d-8e8f-f6cc891ea8f5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Pink Begonia Farms\", \"vi\": \"Pink Begonia Farms\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.pinkbegoniafarms.com\", \"vi\": \"http://www.pinkbegoniafarms.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Pink Begonia Farms is your one-stop shop for all your plant-related needs.\", \"vi\": \"Pink Begonia Farms là điểm đến lý tưởng cho mọi nhu cầu liên quan đến cây trồng của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Whether you are a landscape professional, a backyard gardener, or a houseplant enthusiast, we have just about everything you need!\", \"vi\": \"Dù bạn là một chuyên gia cảnh quan, người làm vườn tại gia, hay người đam mê cây cảnh trong nhà, chúng tôi đều có hầu hết mọi thứ bạn cần!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Some seeds, fertilizer, and equipment can be ordered online, but please come visit our nursery in person for a much larger selection.\", \"vi\": \"Một số hạt giống, phân bón và dụng cụ có thể được đặt hàng trực tuyến, nhưng vui lòng đến thăm vườn ươm của chúng tôi trực tiếp để có sự lựa chọn phong phú hơn rất nhiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our sizable facility is divided into four distinct sections as follows:\", \"vi\": \"Khuôn viên rộng lớn của chúng tôi được chia thành bốn khu vực riêng biệt như sau:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"North Gate\", \"vi\": \"Cổng Bắc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"– indoor houseplants, tropical plants, exotics\", \"vi\": \"– cây cảnh trồng trong nhà, cây nhiệt đới, cây ngoại lai\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"South Gate\", \"vi\": \"Cổng Nam\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"– plants and landscaping products sold in bulk quantities at wholesale prices\", \"vi\": \"– cây trồng và sản phẩm cảnh quan được bán với số lượng lớn theo giá sỉ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"East Gate\", \"vi\": \"Cổng Đông\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"– local landscape plants that grow well in our area and require little maintenance\", \"vi\": \"– cây cảnh quan bản địa phát triển tốt ở khu vực của chúng tôi và ít cần chăm sóc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"West Gate\", \"vi\": \"Cổng Tây\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"– herbs, vegetable plants, fruit and nut trees, and other edibles\", \"vi\": \"– các loại thảo mộc, cây rau, cây ăn quả và cây lấy hạt, cùng các loại cây có thể ăn được khác\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Attention Pink Begonia Farms Customers!\", \"vi\": \"Thông báo gửi đến khách hàng của Pink Begonia Farms!\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We are changing to new ownership on April 1.\", \"vi\": \"Chúng tôi sẽ chuyển sang chủ sở hữu mới vào ngày 1 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Several other changes will follow, most notably renovation work that will cause the area where we service our bulk-order customers to be closed from April 1 through May 5.\", \"vi\": \"Một số thay đổi khác sẽ theo sau, đáng chú ý nhất là công việc cải tạo sẽ khiến khu vực phục vụ khách hàng mua sỉ phải đóng cửa từ ngày 1 tháng 4 đến hết ngày 5 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Also, we would kindly request that if you use our baskets or wagons to move your purchased items to your car, please do not leave them in the middle of the parking area.\", \"vi\": \"Ngoài ra, chúng tôi kính đề nghị nếu quý khách sử dụng giỏ hoặc xe đẩy của chúng tôi để chuyển các mặt hàng đã mua ra xe của mình, xin vui lòng không để chúng ở giữa khu vực đậu xe.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thanks!\", \"vi\": \"Cảm ơn!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"http://www.retaileropinion.com/reviews/pinkbegoniafarms\", \"vi\": \"http://www.retaileropinion.com/reviews/pinkbegoniafarms\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I had a wonderful experience shopping at Pink Begonia Farms.\", \"vi\": \"Tôi đã có một trải nghiệm mua sắm tuyệt vời tại Pink Begonia Farms.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Recently I was preparing a client\'s property for sale, and I needed extensive landscaping work to be done.\", \"vi\": \"Gần đây tôi đang chuẩn bị bất động sản cho một khách hàng để bán, và tôi cần thực hiện các công việc cảnh quan quy mô lớn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"The front entryway needed extra color and greenery before I could show the house to potential buyers.\", \"vi\": \"Lối vào phía trước cần thêm màu sắc và cây xanh trước khi tôi có thể dẫn người mua tiềm năng đến xem nhà.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Knowing nothing about plants, I asked the store staff to help me pick out an assortment of local favorites that would require very little manual watering or care.\", \"vi\": \"Không biết gì về cây cối, tôi đã nhờ nhân viên cửa hàng giúp chọn ra một bộ sưu tập các loại cây ưa chuộng tại địa phương mà đòi hỏi rất ít công tưới nước hoặc chăm sóc thủ công.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"When finished, the house looked so much more inviting.\", \"vi\": \"Khi hoàn thành, ngôi nhà trông thu hút hơn rất nhiều.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Thanks Pink Begonia Farms for your excellent service!\", \"vi\": \"Cảm ơn Pink Begonia Farms vì dịch vụ tuyệt vời của các bạn!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"— Daphne Weigand\", \"vi\": \"— Daphne Weigand\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"April 15\", \"vi\": \"Ngày 15 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '14406de4-1f5a-41f7-88a6-95b6645aaefc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Joan Chi (12:39 P.M.)\", \"vi\": \"Joan Chi (12:39 CH)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hello Mina.\", \"vi\": \"Chào Mina.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Are you almost finished with the field measurements?\", \"vi\": \"Bạn đã gần đo đạc thực tế xong chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I\'m getting hungry.\", \"vi\": \"Tôi bắt đầu thấy đói rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Mina Evers (12:40 P.M.)\", \"vi\": \"Mina Evers (12:40 CH)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Sorry, Joan.\", \"vi\": \"Xin lỗi, Joan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I\'m afraid you and Ms. Lim will have to go to lunch without me today.\", \"vi\": \"Tôi e rằng cô và cô Lim sẽ phải đi ăn trưa mà không có tôi hôm nay rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"There\'s a problem with the site coordinates.\", \"vi\": \"Đang có vấn đề với tọa độ của công trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This is going to take some time.\", \"vi\": \"Việc này sẽ mất thêm ít thời gian.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Joan Chi (12:51 P.M.)\", \"vi\": \"Joan Chi (12:51 CH)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Oh no. Should we bring something back for you?\", \"vi\": \"Ồ không. Chúng tôi có nên mua món gì mang về cho bạn không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Mina Evers (12:59 P.M.)\", \"vi\": \"Mina Evers (12:59 CH)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Get me a chicken sandwich.\", \"vi\": \"Mua cho tôi một chiếc bánh mì kẹp thịt gà nhé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Joan Chi (1:00 P.M.)\", \"vi\": \"Joan Chi (1:00 CH)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sure thing, Mina.\", \"vi\": \"Chắc chắn rồi, Mina.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"See you in a while.\", \"vi\": \"Hẹn gặp lại bạn sau một lát nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '14516463-16f9-42f2-a0ef-581defff32ac';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Gamer Arcades Joins Forces with Frankie\'s Burgers Franchises\", \"vi\": \"Gamer Arcades Hợp Tác với Chuỗi Cửa Hàng Frankie\'s Burgers\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"LEEDS (9 July)—Gamer Arcades and fast-food franchise Frankie\'s Burgers have announced a new partnership, which will formally start at the beginning of August.\", \"vi\": \"LEEDS (9 tháng 7)—Gamer Arcades và chuỗi cửa hàng đồ ăn nhanh Frankie\'s Burgers đã công bố một mối quan hệ đối tác mới, sẽ chính thức bắt đầu vào đầu tháng Tám.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"At that time, all Gamer Arcades will introduce a Frankie\'s Burgers to their locations.\", \"vi\": \"Vào thời điểm đó, tất cả các cơ sở của Gamer Arcades sẽ giới thiệu một cửa hàng Frankie\'s Burgers tại các địa điểm của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The president of Gamer Arcades, Allen Ingram, expressed his excitement about the possibilities of this strategic partnership.\", \"vi\": \"Chủ tịch của Gamer Arcades, ông Allen Ingram, đã bày tỏ sự hào hứng của mình về những khả năng mà mối quan hệ đối tác chiến lược này mang lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"The outstanding quality of Frankie\'s Burgers will enhance customers\' enjoyment of our arcades,\\\" said Mr. Ingram.\", \"vi\": \"\\\"Chất lượng vượt trội của Frankie\'s Burgers sẽ nâng cao sự tận hưởng của khách hàng tại các khu trò chơi của chúng tôi,\\\" ông Ingram cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"\\\"Until now, there have been no food options on the premises.\", \"vi\": \"\\\"Cho đến nay, chưa có lựa chọn đồ ăn nào tại các cơ sở.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"With this partnership, however, customers will be able to take a break for a delicious meal and then get back to enjoying our state-of-the-art gaming centers.\\\"\", \"vi\": \"Tuy nhiên, với mối quan hệ đối tác này, khách hàng sẽ có thể nghỉ ngơi để thưởng thức một bữa ăn ngon miệng và sau đó tiếp tục tận hưởng các trung tâm trò chơi hiện đại của chúng tôi.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This is not the first major change Mr. Ingram has made to the company since he took over from Justine Beckerman last November.\", \"vi\": \"Đây không phải là thay đổi lớn đầu tiên mà ông Ingram thực hiện đối với công ty kể từ khi ông tiếp quản vị trí từ bà Justine Beckerman vào tháng Mười Nhì năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"A month after assuming the role of president, he brought virtual reality games to Gamer Arcades.\", \"vi\": \"Một tháng sau khi đảm nhận vai trò chủ tịch, ông đã mang các trò chơi thực tế ảo đến với Gamer Arcades.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Since that time, he has also expanded the company into Germany and Belgium, and he has launched several charity initiatives associated with Gamer Arcades.\", \"vi\": \"Kể từ thời điểm đó, ông cũng đã mở rộng công ty sang Đức và Bỉ, đồng thời khởi動 một số sáng kiến từ thiện liên quan đến Gamer Arcades.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '14915fef-ec57-49fc-951c-c652dfd683e8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Colin Wikander (10:23 A.M.) I have reviewed the draft of the new client questionnaire, and it looks great overall.\", \"vi\": \"Colin Wikander (10:23 A.M.) Tôi đã xem xét bản thảo của bảng câu hỏi dành for khách hàng mới, và nhìn chung nó rất tuyệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I would make the question about bookkeeping strategies more open-ended, though.\", \"vi\": \"Tuy nhiên, tôi muốn câu hỏi về các chiến lược ghi chép kế toán mang tính mở hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"As written, it may lead respondents to give simple yes or no answers.\", \"vi\": \"Như được viết, nó có thể khiến những người trả lời đưa ra câu trả lời có hoặc không đơn giản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Midori Sakai (10:24 A.M.) That\'s a good point.\", \"vi\": \"Midori Sakai (10:24 A.M.) Đó là một ý kiến hay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We\'ll need to fix that.\", \"vi\": \"Chúng ta sẽ cần phải sửa điều đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I also want to add a couple of questions about how financial and tax reports have been handled in the past.\", \"vi\": \"Tôi cũng muốn thêm một vài câu hỏi về cách các báo cáo tài chính và thuế đã được xử lý trong quá khứ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Ela Hamidah (10:24 A.M.) I could look at the bookkeeping question to see what I can come up with.\", \"vi\": \"Ela Hamidah (10:24 A.M.) Tôi có thể xem xét câu hỏi về kế toán để xem mình có thể nghĩ ra gì không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Colin Wikander (10:25 A.M.) Well, it\'s four pages already.\", \"vi\": \"Colin Wikander (10:25 A.M.) Chà, nó đã dài bốn trang rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Midori Sakai (10:27 A.M.) That\'s true.\", \"vi\": \"Midori Sakai (10:27 A.M.) Đúng vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I\'ll just wait for Ela\'s revision of the third question.\", \"vi\": \"Tôi sẽ đợi bản sửa đổi câu hỏi thứ ba của Ela.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Then Jack Neligan can put a draft of the form up on our Web site.\", \"vi\": \"Sau đó Jack Neligan có thể đưa bản nháp của biểu mẫu lên trang web của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Colin Wikander (10:28 A.M.) Is it true that we are not planning to collect any paper forms?\", \"vi\": \"Colin Wikander (10:28 A.M.) Có phải chúng ta không có kế hoạch thu thập bất kỳ biểu mẫu giấy nào không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Midori Sakai (10:30 A.M.) We might do that, but digital collection is preferable to avoid the lag time of waiting for our clients to print, fill out, and scan the forms to send them back.\", \"vi\": \"Midori Sakai (10:30 A.M.) Chúng ta có thể làm điều đó, nhưng việc thu thập kỹ thuật số được ưu tiên hơn để tránh thời gian chờ đợi khách hàng in, điền và quét các biểu mẫu để gửi lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '1494a70c-2461-4f1a-add6-aa53a8701e8c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Seo-Yun Jang <s_jang@lazulinamail.com>\", \"vi\": \"Đến: Seo-Yun Jang <s_jang@lazulinamail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Travel Today <team@traveltoday.com>\", \"vi\": \"Từ: Travel Today <team@traveltoday.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 18\", \"vi\": \"Ngày: 18 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Price alert\", \"vi\": \"Chủ đề: Cảnh báo giá vé\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Trip 1: Seattle to Chicago\\nJuly 28\\nOne way, 1 adult, economy seat\", \"vi\": \"Chuyến đi 1: Seattle đi Chicago\\nNgày 28 tháng 7\\nMột chiều, 1 người lớn, ghế phổ thông\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Nomata Airlines\\n1 stop (Denver)\\n2:42 P.M.–11:05 P.M. - Average price: $401\\nCurrent price: $315\", \"vi\": \"Hàng không Nomata\\n1 điểm dừng (Denver)\\n2:42 Chiều–11:05 Tối - Giá trung bình: $401\\nGiá hiện tại: $315\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Blue Range Airways\\nNonstop\\n4:40 P.M.–10:40 P.M. - Average price: $439\\nCurrent price: $376\", \"vi\": \"Hàng không Blue Range\\nBay thẳng\\n4:40 Chiều–10:40 Tối - Giá trung bình: $439\\nGiá hiện tại: $376\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Trip 2: Los Angeles to New York\\nAugust 15\\nOne way, 1 adult, comfort-plus seat\", \"vi\": \"Chuyến đi 2: Los Angeles đi New York\\nNgày 15 tháng 8\\nMột chiều, 1 người lớn, ghế hạng phổ thông đặc biệt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Nomata Airlines\\n1 stop (Houston)\\n6:00 A.M.–5:32 P.M. - Average price: $465\\nCurrent price: $385\", \"vi\": \"Hàng không Nomata\\n1 điểm dừng (Houston)\\n6:00 Sáng–5:32 Chiều - Giá trung bình: $465\\nGiá hiện tại: $385\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Blue Range Airways\\nNonstop\\n11:30 A.M.–8:00 P.M. - Average price: $518\\nCurrent price: $436\", \"vi\": \"Hàng không Blue Range\\nBay thẳng\\n11:30 Sáng–8:00 Tối - Giá trung bình: $518\\nGiá hiện tại: $436\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Hello, Travel Today Subscriber,\", \"vi\": \"Xin chào Người đăng ký Travel Today,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You recently signed up for airfare notifications.\", \"vi\": \"Bạn gần đây đã đăng ký nhận thông báo giá vé máy bay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Please see the information below for price cuts on your preferred trips.\", \"vi\": \"Vui lòng xem thông tin bên dưới về các đợt giảm giá cho các chuyến đi ưa thích của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Remember that airlines usually offer a limited number of the lowest fares, so you may want to make a reservation soon to take advantage of these prices.\", \"vi\": \"Xin lưu ý rằng các hãng hàng không thường cung cấp số lượng vé có mức giá thấp nhất rất hạn chế, vì vậy bạn nên tiến hành đặt chỗ sớm để tận dụng các mức giá này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If you have questions or need assistance making reservations, please contact us at 210-555-0137.\", \"vi\": \"Nếu bạn có thắc mắc hoặc cần hỗ trợ đặt chỗ, vui lòng liên hệ với chúng tôi theo số 210-555-0137.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Cảm ơn bạn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Your Travel Today Team\", \"vi\": \"Đội ngũ Travel Today của bạn\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '14c1188d-d611-4f7e-981c-b713835f23d6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Small Business Costs: An Overview for Beginners\", \"vi\": \"Chi phí doanh nghiệp nhỏ: Tổng quan dành cho người mới bắt đầu\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Article\", \"vi\": \"Bài báo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"There are two main kinds of costs.\", \"vi\": \"Có hai loại chi phí chính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Variable costs are one kind; they include staff wages or the cost of supplies.\", \"vi\": \"Chi phí biến đổi là một loại; chúng bao gồm tiền lương nhân viên hoặc chi phí vật tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [139] — costs are considered fixed.\", \"vi\": \"— [139] — chi phí được coi là cố định.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [139]}, {\"en\": \"These include such things as rent payments and property taxes.\", \"vi\": \"Những chi phí này bao gồm các khoản như tiền thuê mặt bằng và thuế tài sản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"A third kind of cost is called an opportunity cost.\", \"vi\": \"Loại chi phí thứ ba được gọi là chi phí cơ hội.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You incur an opportunity cost whenever you make a decision to do one specific thing — [140] — choosing some alternative option.\", \"vi\": \"Bạn phải chịu chi phí cơ hội bất cứ khi nào bạn đưa ra quyết định làm một việc cụ thể — [140] — thay vì chọn một phương án thay thế nào đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [140]}, {\"en\": \"This cost refers to the lost opportunities you could have benefited from had you made a different choice.\", \"vi\": \"Chi phí này đề cập đến những cơ hội bị bỏ lỡ mà bạn có thể đã hưởng lợi nếu bạn đưa ra một lựa chọn khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Careful consideration of potential opportunity costs is important.\", \"vi\": \"Việc cân nhắc kỹ lưỡng các chi phí cơ hội tiềm ẩn là rất quan trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Ideally this should — [141] — decision making.\", \"vi\": \"Lý tưởng nhất là điều này nên — [141] — quá trình ra quyết định.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [141]}, {\"en\": \"— [142] —.\", \"vi\": \"— [142] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [142]}, {\"en\": \"You should consult a licensed accountant for a more complete understanding.\", \"vi\": \"Bạn nên tham khảo ý kiến của một kế toán viên có chứng chỉ để có được sự hiểu biết đầy đủ hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '14ce01b4-48e6-4da6-90a3-11795ae3f140';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Erica Pittman <contact@pittmansolutions.com>\", \"vi\": \"Từ: Erica Pittman <contact@pittmansolutions.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Jessica Chambers <jchambers@jessicachambers.com>\", \"vi\": \"Đến: Jessica Chambers <jchambers@jessicachambers.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Pittman Solutions and your Web site\", \"vi\": \"Chủ đề: Pittman Solutions và trang web của bạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: April 19\", \"vi\": \"Ngày: 19 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachments: 📎 Rates_and_portfolio\", \"vi\": \"Tệp đính kèm: 📎 Rates_and_portfolio\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Chambers,\", \"vi\": \"Kính gửi bà Chambers,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am contacting you to offer my services in improving your Web site.\", \"vi\": \"Tôi liên hệ với bạn để cung cấp dịch vụ cải thiện trang web của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I visited the site after receiving one of your silver necklaces as a gift last month and was sorry to see that the texts accompanying your product photos contain typos and confusing wording.\", \"vi\": \"Tôi đã truy cập trang web sau khi nhận được một chiếc vòng cổ bạc của bạn làm quà vào tháng trước và rất tiếc khi thấy rằng các đoạn văn bản đi kèm với hình ảnh sản phẩm của bạn có chứa lỗi đánh máy và cách dùng từ gây bối rối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I would be happy to revise this content so that it properly highlights your lovely designs.\", \"vi\": \"Tôi rất sẵn lòng chỉnh sửa nội dung này để nó làm nổi bật một cách phù hợp các thiết kế đáng yêu của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You can see my rates and previous work in the attachment to this e-mail.\", \"vi\": \"Bạn có thể xem mức phí và các công việc trước đây của tôi trong tệp đính kèm của email này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Please take a look and let me know if you are interested.\", \"vi\": \"Vui lòng xem qua và cho tôi biết nếu bạn quan tâm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Erica Pittman\", \"vi\": \"Erica Pittman\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Pittman Solutions\", \"vi\": \"Pittman Solutions\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '14cf0ad5-de92-4248-a965-3df5d58bb4c5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ashley Montaine 8:54 A.M.: How did the interview with Mr. Erickson go?\", \"vi\": \"Ashley Montaine 8:54 Sáng: Buổi phỏng vấn với ông Erickson diễn ra thế nào rồi?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dan Campbell 8:55 A.M.: I really enjoyed meeting him.\", \"vi\": \"Dan Campbell 8:55 Sáng: Tôi rất thích khi được gặp anh ấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I think he\'d be a great reporter here.\", \"vi\": \"Tôi nghĩ anh ấy sẽ là một phóng viên tuyệt vời ở đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"He seems smart and organized, and his samples show that he\'s a great writer.\", \"vi\": \"Anh ấy có vẻ thông minh và ngăn nắp, và các bài mẫu của anh ấy cho thấy anh ấy là một cây bút xuất sắc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Ashley Montaine 8:57 A.M.: Brooke, can you contact Mr. Erickson to set up the next interview?\", \"vi\": \"Ashley Montaine 8:57 Sáng: Brooke, bạn có thể liên hệ với ông Erickson để sắp xếp buổi phỏng vấn tiếp theo không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Is that a problem?\", \"vi\": \"Có vấn đề gì sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dan Campbell 8:58 A.M.: I\'d really like to work with him.\", \"vi\": \"Dan Campbell 8:58 Sáng: Tôi rất muốn được làm việc cùng anh ấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It is very important that he impress Mr. Peters.\", \"vi\": \"Điều rất quan trọng là anh ấy phải gây ấn tượng với ông Peters.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Brooke Randolph 8:59 A.M.: Not at all.\", \"vi\": \"Brooke Randolph 8:59 Sáng: Không có gì đâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Ashley Montaine 9:00 A.M.: Thanks.\", \"vi\": \"Ashley Montaine 9:00 Sáng: Cảm ơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I also see that he has a varied work history.\", \"vi\": \"Tôi cũng thấy rằng anh ấy có lịch sử làm việc khá phong phú.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"That will make him a well-rounded reporter.\", \"vi\": \"Điều đó sẽ giúp anh ấy trở thành một phóng viên toàn diện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Brooke Randolph 9:02 A.M.: When would you like to meet with him again?\", \"vi\": \"Brooke Randolph 9:02 Sáng: Khi nào anh muốn gặp lại anh ấy?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Dan Campbell 9:03 A.M.: Ashley, I believe you will participate in the next interview.\", \"vi\": \"Dan Campbell 9:03 Sáng: Ashley, tôi tin là cô sẽ tham gia buổi phỏng vấn tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Note that Mr. Peters is probably going to ask why Mr. Erickson wants to transition from freelance writing to in-house news reporting.\", \"vi\": \"Lưu ý rằng ông Peters có lẽ sẽ hỏi lý do tại sao ông Erickson muốn chuyển từ viết tự do sang làm phóng viên tin tức toàn thời gian tại tòa soạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Also, Mr. Peters will want assurances that he\'s committed and will stick around for several years.\", \"vi\": \"Ngoài ra, ông Peters sẽ muốn có sự đảm bảo rằng anh ấy tận tâm và sẽ gắn bó lâu dài trong vài năm tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Ashley Montaine 9:04 A.M.: Brooke, Mr. Peters and I are both free Friday morning.\", \"vi\": \"Ashley Montaine 9:04 Sáng: Brooke, cả ông Peters và tôi đều rảnh vào sáng thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Brooke Randolph 9:06 A.M.: Great.\", \"vi\": \"Brooke Randolph 9:06 Sáng: Tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I\'ll write an e-mail shortly.\", \"vi\": \"Tôi sẽ viết một email ngay đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '14ecffd5-b9c0-49b7-8711-4eab0212bb88';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Bindu Gil\", \"vi\": \"Đến: Bindu Gil\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Neela Balay\", \"vi\": \"Từ: Neela Balay\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: June 18\", \"vi\": \"Ngày: 18 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Follow-up\", \"vi\": \"Chủ đề: Thảo luận tiếp theo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Gil,\", \"vi\": \"Kính gửi chị Gil,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Regarding our telephone conversation earlier today, here in writing is the change I would like to make to Saturday\'s delivery.\", \"vi\": \"Liên quan đến cuộc điện thoại của chúng ta đầu ngày hôm nay, tôi xin gửi lại bằng văn bản những thay đổi mà tôi muốn thực hiện đối với đơn hàng giao vào thứ Bảy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am requesting that you now deliver the flowers to the Grand Dining Room at the Kaltan Hotel instead of the Saji Banquet Hall.\", \"vi\": \"Tôi muốn yêu cầu chị chuyển hoa đến Phòng Tiệc lớn (Grand Dining Room) tại Khách sạn Kaltan thay vì Phòng khánh tiết Saji.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I apologize for this last-minute switch, but the banquet hall manager contacted me just last night to inform me about an electrical system malfunction that will require a weekend repair.\", \"vi\": \"Tôi xin lỗi vì sự thay đổi vào phút chót này, nhưng quản lý phòng khánh tiết đã liên hệ với tôi ngay tối qua để thông báo về sự cố hệ thống điện sẽ phải sửa chữa vào cuối tuần này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Since the office party I am planning cannot be postponed, I have had to reserve this other venue.\", \"vi\": \"Vì bữa tiệc của công ty mà tôi đang lên kế hoạch không thể hoãn lại, tôi đã phải đặt địa điểm khác này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I would appreciate receiving the delivery by 4:00 P.M.\", \"vi\": \"Tôi sẽ rất cảm kích nếu nhận được hàng trước 4 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Neela Balay\", \"vi\": \"Neela Balay\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '14f56452-7c14-4435-a92b-f76452541550';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Native Plant Society Headquarters\", \"vi\": \"Trụ sở chính Hiệp hội Thực vật Bản địa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"161 Sussex Street\", \"vi\": \"161 Phố Sussex\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Sydney, NSW 2001\", \"vi\": \"Sydney, NSW 2001\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"15 April\", \"vi\": \"Ngày 15 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Yasmine Harabi\", \"vi\": \"Yasmine Harabi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"247 Kooljak Road\", \"vi\": \"247 Đường Kooljak\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Perth, Western Australia 6280\", \"vi\": \"Perth, Tây Australia 6280\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Membership number 4290\", \"vi\": \"Mã số hội viên 4290\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Dear Ms. Harabi,\", \"vi\": \"Kính gửi bà Harabi,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Thank you for your continued support as a society member.\", \"vi\": \"Cảm ơn sự ủng hộ lâu năm của bà với tư cách là hội viên của hiệp hội.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Given your recent move, your membership has been transferred to the chapter located in the city of Perth.\", \"vi\": \"Do việc chuyển chỗ ở gần đây của bà, tư cách hội viên của bà đã được chuyển sang chi hội đặt tại thành phố Perth.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We will be mailing a replacement member identification card within a few days.\", \"vi\": \"Chúng tôi sẽ gửi thẻ nhận diện hội viên thay thế qua đường bưu điện trong vòng vài ngày tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Unlike the chapter in the city of Canberra, the Perth branch meets the first Saturday of every month, so your next meeting will be in three weeks.\", \"vi\": \"Không giống như chi hội ở thành phố Canberra, chi nhánh Perth họp vào thứ Bảy đầu tiên của mỗi tháng, vì vậy buổi họp tiếp theo của bà sẽ diễn ra sau ba tuần nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"If you have any questions, please contact us weekdays between 8:00 a.m. and 4:00 p.m. at (08) 5555 0145.\", \"vi\": \"Nếu bà có bất kỳ câu hỏi nào, vui lòng liên hệ với chúng tôi vào các ngày trong tuần từ 8:00 sáng đến 4:00 chiều theo số (08) 5555 0145.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Leticia Davis\", \"vi\": \"Leticia Davis\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Leticia Davis\", \"vi\": \"Leticia Davis\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Membership Department\", \"vi\": \"Bộ phận Hội viên\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '14f5bb6f-cb12-4690-a4d1-c4b756d5747d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"HAMILTON (3 February)—The Ruakura Training Centre (RTC) is relocating to the Springdale Industrial Park.\", \"vi\": \"HAMILTON (3 tháng 2)—Trung tâm Đào tạo Ruakura (RTC) đang chuyển dời đến Khu công nghiệp Springdale.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Spokesperson Jax Wu said RTC hopes for a grand opening in May, with only a slight interruption of the usual course schedule.\", \"vi\": \"Người phát ngôn Jax Wu cho biết RTC hy vọng sẽ có lễ khai trương hoành tráng vào tháng 5, chỉ với sự gián đoạn nhỏ đối với lịch học thông thường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The new facility, which offers training and accreditation for work in a variety of fields, including roadwork, mining, and construction, is opening at the right time, according to Mr. Wu.\", \"vi\": \"Cơ sở mới, nơi cung cấp đào tạo và cấp chứng chỉ cho công việc trong nhiều lĩnh vực khác nhau bao gồm công đường, khai khoáng và xây dựng, đang mở cửa vào thời điểm thích hợp, theo ông Wu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"\\\"There are numerous job openings now in these specialized fields, especially around Hamilton,\\\" Mr. Wu stated.\", \"vi\": \"\\\"Hiện có rất nhiều cơ hội việc làm trong các lĩnh vực chuyên môn này, đặc biệt là quanh khu vực Hamilton,\\\" ông Wu phát biểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The new location will be more convenient for people to reach than RTC\'s current building on Clarkston Road.\", \"vi\": \"Địa điểm mới sẽ thuận tiện hơn cho mọi người tiếp cận so với tòa nhà hiện tại của RTC trên đường Clarkston.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"There is a public transit stop directly in front of the industrial park, and there is free parking as well.\", \"vi\": \"Có một trạm phương tiện giao thông công cộng ngay trước khu công nghiệp, và cũng có bãi đậu xe miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"For more information, visit RTC\'s Web site at www.ruakuratc.co.nz.\", \"vi\": \"Để biết thêm thông tin, hãy truy cập trang web của RTC tại www.ruakuratc.co.nz.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"https://www.ruakuratc.co.nz ▶\", \"vi\": \"https://www.ruakuratc.co.nz ▶\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Ruakura Training Centre (RTC) Grand Opening\", \"vi\": \"Lễ Khai Trương Trung Tâm Đào Tạo Ruakura (RTC)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Sunday, 16 August, 1:00 P.M. to 4:00 P.M.\", \"vi\": \"Chủ nhật, ngày 16 tháng 8, từ 1:00 chiều đến 4:00 chiều\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Join us on Sunday, 16 August, as we open our new centre at Springdale Industrial Park.\", \"vi\": \"Hãy tham gia cùng chúng tôi vào Chủ nhật, ngày 16 tháng 8, khi chúng tôi khai trương trung tâm mới tại Khu công nghiệp Springdale.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Courses will begin on Monday, 17 August.\", \"vi\": \"Các khóa học sẽ bắt đầu vào Thứ Hai, ngày 17 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"See below for our first week\'s offerings.\", \"vi\": \"Xem bên dưới để biết các dịch vụ đào tạo trong tuần đầu tiên của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To register for any of these courses, go to the Register tab.\", \"vi\": \"Để đăng ký bất kỳ khóa học nào trong số này, hãy truy cập tab Đăng ký (Register).\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If you have questions, e-mail our registrar, Ms. Phoebe Gordon, at pgordon@ruakuratc.co.nz.\", \"vi\": \"Nếu bạn có thắc mắc, hãy gửi email cho nhân viên ghi danh của chúng tôi, cô Phoebe Gordon, tại địa chỉ pgordon@ruakuratc.co.nz.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"RTC can also train on-site at your location; for further details see the Course Offerings tab.\", \"vi\": \"RTC cũng có thể đào tạo trực tiếp tại địa điểm của bạn; để biết thêm chi tiết, hãy xem tab Các khóa học (Course Offerings).\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"17 August: Work Safety Refresher, Mr. Jenkins, Instructor\", \"vi\": \"Ngày 17 tháng 8: Ôn tập An toàn Lao động, Giảng viên: Ông Jenkins\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"18–19 August: Basic Worksite Traffic Management, Ms. Agarwal, Instructor\", \"vi\": \"Ngày 18–19 tháng 8: Quản lý Giao thông Công trường Cơ bản, Giảng viên: Cô Agarwal\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"19 August: Work Safety Refresher, Ms. McKenzie, Instructor\", \"vi\": \"Ngày 19 tháng 8: Ôn tập An toàn Lao động, Giảng viên: Cô McKenzie\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"20–21 August: Heavy Equipment Licensing, Mr. Waipuka, Instructor\", \"vi\": \"Ngày 20–21 tháng 8: Cấp phép Vận hành Thiết bị Nặng, Giảng viên: Ông Waipuka\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"21–22 August: Basic Worksite Traffic Management, Mr. Yeo, Instructor\", \"vi\": \"Ngày 21–22 tháng 8: Quản lý Giao thông Công trường Cơ bản, Giảng viên: Ông Yeo\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"News\", \"vi\": \"Tin tức\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Course Offerings\", \"vi\": \"Các khóa học\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Register\", \"vi\": \"Đăng ký\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Thư điện tử*\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"To: Phoebe Gordon <pgordon@ruakuratc.co.nz>\", \"vi\": \"Đến: Phoebe Gordon <pgordon@ruakuratc.co.nz>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"From: Abraham Lutui <alutui@bluemills.co.nz>\", \"vi\": \"Từ: Abraham Lutui <alutui@bluemills.co.nz>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Subject: Request\", \"vi\": \"Chủ đề: Yêu cầu\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Date: 14 August\", \"vi\": \"Ngày: 14 tháng 8\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Dear Ms. Gordon:\", \"vi\": \"Kính gửi cô Gordon,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I am registered for the 17 August work safety refresher course.\", \"vi\": \"Tôi đã đăng ký tham gia khóa học ôn tập an toàn lao động vào ngày 17 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"However, I am currently in Tonga on business, and my return flight arrives on that date.\", \"vi\": \"Tuy nhiên, tôi hiện đang ở Tonga để công tác, và chuyến bay trở về của tôi hạ cánh vào đúng ngày đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Would it be possible for you to switch my registration to the 19 August course instead?\", \"vi\": \"Liệu cô có thể chuyển lịch đăng ký của tôi sang khóa học ngày 19 tháng 8 thay thế được không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Abraham Lutui\", \"vi\": \"Abraham Lutui\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}]' WHERE `id` = '14f7e096-b79e-4682-8546-5e399a9fa00d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"New Addition to Shadeside Plaza\", \"vi\": \"Sự bổ sung mới cho Quảng trường Shadeside\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"BIRCH CITY (November 12)—Design Glory, a jewelry business operated by lifelong Birch City resident Tamara Banda, has set up a brick and- mortar store in the city’s Shadeside Plaza shopping area.\", \"vi\": \"BIRCH CITY (12 tháng 11)—Design Glory, một doanh nghiệp trang sức do Tamara Banda, cư dân lâu năm tại Birch City điều hành, đã thành lập một cửa hàng truyền thống tại khu mua sắm Shadeside Plaza của thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Ms. Banda said the shop, which opened on November 9, features her entire line of handmade jewelry along with a selection of beautiful natural crystals that can become the centerpiece of any room.\", \"vi\": \"Bà Banda cho biết cửa hàng khai trương vào ngày 9 tháng 11, trưng bày toàn bộ dòng sản phẩm trang sức làm bằng tay của bà cùng với một tuyển tập các viên pha lê tự nhiên tuyệt đẹp có thể trở thành điểm nhấn cho bất kỳ căn phòng nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Ms. Banda emphasizes that she sets her jewelry brand apart from others by offering handmade designs at price points that won’t break a budget.\", \"vi\": \"Bà Banda nhấn mạnh rằng bà tạo sự khác biệt cho thương hiệu trang sức của mình so với những hãng khác bằng cách cung cấp các thiết kế thủ công với mức giá phù hợp với túi tiền.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"To keep her overhead costs in check, she says she sources materials creatively from a variety of local metal suppliers.\", \"vi\": \"Để kiểm soát chi phí chung, bà cho biết mình tìm nguồn nguyên liệu một cách sáng tạo từ nhiều nhà cung cấp kim loại địa phương khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Although managing the store, which is open Tuesday through Saturday from 11:00 A.M. to 5:00 P.M., will occupy much of her time, Ms. Banda said she still intends to operate booths at regional arts festivals.\", \"vi\": \"Mặc dù việc quản lý cửa hàng mở cửa từ thứ Ba đến thứ Bảy, từ 11:00 sáng đến 5:00 chiều sẽ chiếm phần lớn thời gian của bà, bà Banda cho biết bà vẫn có ý định điều hành các gian hàng tại các lễ hội nghệ thuật khu vực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"She will also continue to serve on the planning committee for the annual art show at Central Arts University, where she learned her jewelry-making techniques.\", \"vi\": \"Bà cũng sẽ tiếp tục tham gia ban tổ chức cho triển lãm nghệ thuật thường niên tại Đại học Nghệ thuật Trung tâm, nơi bà đã học các kỹ thuật chế tác trang sức của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The idea of opening a physical store came to Ms. Banda when a friend, Brad Machado, told her of his positive experience in operating his retail bookshop on the opposite side of Shadeside Plaza from where Design Glory is now.\", \"vi\": \"Ý tưởng mở một cửa hàng vật lý đến với bà Banda khi một người bạn, Brad Machado, kể cho bà nghe về trải nghiệm tích cực của anh ấy trong việc điều hành cửa hàng sách bán lẻ ở phía đối diện của Quảng trường Shadeside so với vị trí của Design Glory hiện tại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The shopping area, he said, benefits from the heavy foot traffic nearby.\", \"vi\": \"Khu vực mua sắm này, anh ấy cho biết, được hưởng lợi từ lượng người qua lại đông đúc ở gần đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '1502a3be-a67a-42ef-9165-8c9b16a2f2d6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Connelly\'s Parking Garage\", \"vi\": \"Nhà để xe Connelly\'s\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Parking is $10 per hour unless you get your parking validated at a ------- (135) store.\", \"vi\": \"Phí gửi xe là 10 đô la một giờ trừ khi bạn được xác thực vé gửi xe tại một cửa hàng ------- (135).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [135]}, {\"en\": \"Stores that can validate your parking include Raymond\'s Department Store, Lola\'s Fine Dining, Monique\'s Boutique, and Gretsch Chocolatiers.\", \"vi\": \"Các cửa hàng có thể xác thực vé gửi xe của bạn bao gồm Cửa hàng bách hóa Raymond\'s, Nhà hàng cao cấp Lola\'s, Cửa hàng thời trang Monique\'s và Cửa hàng sô-cô-la Gretsch Chocolatiers.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Just bring your entrance ticket to ------- (136) of these establishments.\", \"vi\": \"Chỉ cần mang vé vào cửa của bạn đến ------- (136) trong số các cơ sở này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"------- (137).\", \"vi\": \"------- (137).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [137]}, {\"en\": \"You will get your first hour of parking at no charge.\", \"vi\": \"Bạn sẽ được miễn phí giờ gửi xe đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"------- (138), the fee will be $5 per hour.\", \"vi\": \"------- (138), mức phí sẽ là 5 đô la một giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [138]}]' WHERE `id` = '15191b3d-d452-4f43-a55a-91ce535531f8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Nibora XC-35 Sport Utility Vehicle (SUV)\", \"vi\": \"Xe thể thao đa dụng (SUV) Nibora XC-35\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Wherever you want to go, from the beach to the backwoods, the Nibora XC-35 can take you there!\", \"vi\": \"Bất cứ nơi nào bạn muốn đến, từ bãi biển cho đến vùng rừng núi sâu thẳm, Nibora XC-35 đều có thể đưa bạn đến đó!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The XC-35\'s powerful engine provides up to 275 horsepower, while the redesigned body gives this SUV a sleek and sporty look.\", \"vi\": \"Động cơ mạnh mẽ của XC-35 cung cấp công suất lên tới 275 mã lực, trong khi phần thân xe được thiết kế lại mang lại cho dòng xe SUV này vẻ ngoài sang trọng và thể thao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"With significant clearance from the ground and strong stabilization to protect from bumps, the Nibora XC-35 offers a smooth ride even on the roughest terrain and will give you the confidence to take it on any wilderness adventure.\", \"vi\": \"Với khoảng sáng gầm xe đáng kể và hệ thống giảm xóc vững chắc để bảo vệ khỏi các va đập, Nibora XC-35 mang lại cảm giác lái êm ái ngay cả trên những địa hình gồ ghề nhất và sẽ cho bạn sự tự tin để tham gia vào bất kỳ cuộc phiêu lưu hoang dã nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The Nibora XC-35 is available as a gas-powered vehicle or a hybrid.\", \"vi\": \"Nibora XC-35 có sẵn phiên bản chạy bằng xăng hoặc xe hybrid.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Customers may also choose between manual and automatic transmissions.\", \"vi\": \"Khách hàng cũng có thể lựa chọn giữa hộp số sàn và hộp số tự động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"All vehicles come standard with all-wheel drive and a navigation system with phone pairing.\", \"vi\": \"Tất cả các xe đều được trang bị tiêu chuẩn hệ thống dẫn động bốn bánh và hệ thống định vị tích hợp kết nối điện thoại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Options available for the XC-35 include a sunroof, a Sonic Boom stereo system, cruise control, a roof rack, and more.\", \"vi\": \"Các tùy chọn có sẵn cho XC-35 bao gồm cửa sổ trời, hệ thống âm thanh Sonic Boom, hệ thống kiểm soát hành trình, giá nóc và nhiều tính năng khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"To save on the options you love, visit your nearby Nibora dealer to see what kinds of value packages they offer.\", \"vi\": \"Để tiết kiệm chi phí cho các tùy chọn mà bạn yêu thích, hãy ghé thăm đại lý Nibora gần nhất để xem họ cung cấp những loại gói ưu đãi giá trị nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"And before you visit, go to www.nibora.com/build and customize the look of your new Nibora XC-35 by choosing exterior color, upholstery style, and graphic decals.\", \"vi\": \"Và trước khi bạn ghé thăm, hãy truy cập www.nibora.com/build và tùy chỉnh diện mạo chiếc Nibora XC-35 mới của bạn bằng cách chọn màu sơn ngoại thất, phong cách bọc nội thất và decal trang trí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Buy your new Nibora XC-35 today!\", \"vi\": \"Hãy mua chiếc Nibora XC-35 mới của bạn ngay hôm nay!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '15c7881f-ce81-4275-9b40-f0556ffad85e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Janet Hubschmann\", \"vi\": \"Đến: Janet Hubschmann\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: customerservice@readymadeofficesupplies.net\", \"vi\": \"Từ: customerservice@readymadeofficesupplies.net\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: September 3\", \"vi\": \"Ngày: Ngày 3 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Thank you\", \"vi\": \"Chủ đề: Cảm ơn bạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Hubschmann,\", \"vi\": \"Kính gửi Cô Hubschmann,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We here at Readymade Office Supplies are excited to welcome you to our Customers Count rewards program.\", \"vi\": \"Chúng tôi tại Readymade Office Supplies rất hào hứng chào đón bạn đến với chương trình phần thưởng Customers Count của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Your account number 41120 is now registered.\", \"vi\": \"Số tài khoản 41120 của bạn hiện đã được đăng ký.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Be sure to enter your account number to earn points on all your purchases from our Web site.\", \"vi\": \"Hãy nhớ nhập số tài khoản của bạn để tích điểm cho tất cả các giao dịch mua hàng từ trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"You will earn one point for every dollar you spend on qualifying purchases.\", \"vi\": \"Bạn sẽ kiếm được một điểm cho mỗi đô la bạn chi tiêu cho các giao dịch mua hàng đủ điều kiện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Redeem your points on your account page for rewards, including free two-day expedited shipping, special discounts, and more.\", \"vi\": \"Đổi điểm của bạn trên trang tài khoản của bạn để nhận phần thưởng, bao gồm miễn phí vận chuyển nhanh hai ngày, giảm giá đặc biệt và nhiều hơn nữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"You can still order via mail from our print catalog, over the telephone from one of our helpful representatives, or by visiting our retail locations across the United States and Canada.\", \"vi\": \"Bạn vẫn có thể đặt hàng qua đường bưu điện từ danh mục in của chúng tôi, qua điện thoại từ một trong những đại diện hữu ích của chúng tôi, hoặc bằng cách ghé thăm các địa điểm bán lẻ của chúng tôi trên khắp Hoa Kỳ và Canada.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"However, those purchases do not currently qualify for the rewards program.\", \"vi\": \"Tuy nhiên, các giao dịch mua đó hiện không đủ điều kiện tham gia chương trình phần thưởng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Have questions?\", \"vi\": \"Bạn có câu hỏi?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please visit https://www.readymadeofficesupplies.net/customerservice.\", \"vi\": \"Vui lòng truy cập https://www.readymadeofficesupplies.net/customerservice.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '15e97dea-5795-44f0-9d34-444593319ffc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Notice of Public Meeting\", \"vi\": \"Thông báo về cuộc họp công khai\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Fallberg City Library will hold its monthly board meeting on August 19 at 6 P.M. Members of the community are encouraged to ______[131].\", \"vi\": \"Thư viện Thành phố Fallberg sẽ tổ chức cuộc họp ban quản trị hàng tháng vào ngày 19 tháng 8 lúc 6 giờ chiều. Các thành viên trong cộng đồng được khuyến khích ______[131].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"The agenda, ______[132] available on the library\'s Web site, includes an information session about the proposed library building on the city\'s east side.\", \"vi\": \"Chương trình nghị sự, ______[132] có sẵn trên trang web của thư viện, bao gồm một phiên thông tin về tòa nhà thư viện được đề xuất ở phía đông thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132]}, {\"en\": \"Project Manager Andre Cazal will share design concepts for the building.\", \"vi\": \"Giám đốc Dự án Andre Cazal sẽ chia sẻ các ý tưởng thiết kế cho tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"______[133], he will lead a discussion about how construction should be funded.\", \"vi\": \"______[133], ông ấy sẽ dẫn dắt một cuộc thảo luận về cách thức tài trợ cho việc xây dựng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [133]}, {\"en\": \"There will be a period for public comment following the regular agenda items.\", \"vi\": \"Sẽ có khoảng thời gian dành cho ý kiến đóng góp của công chúng sau các nội dung trong chương trình nghị sự thông thường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[134].\", \"vi\": \"______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [134]}]' WHERE `id` = '16d13aa2-3ab0-4206-9aa9-ee7a429ecb50';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: shinju.kaneko@zipmail.com\", \"vi\": \"Đến: shinju.kaneko@zipmail.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: s.armstrong@oknet.com\", \"vi\": \"Từ: s.armstrong@oknet.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: October 14\", \"vi\": \"Ngày: 14 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: RE: Visit\", \"vi\": \"Chủ đề: V/v: Chuyến thăm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Kaneko,\", \"vi\": \"Kính gửi cô Kaneko,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"My family would be delighted to welcome you into 195 Strickland Boulevard.\", \"vi\": \"Gia đình tôi rất vinh hạnh được chào đón cô đến số 195 đại lộ Strickland.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We are indeed quite proud to live in one of the few residences designed by Basma Itani.\", \"vi\": \"Chúng tôi thực sự rất tự hào khi được sống trong một trong số ít các dinh thự được thiết kế bởi Basma Itani.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It would be a pleasure to share our home’s unique beauty with others through the photographs in your book.\", \"vi\": \"Thật là một niềm vinh hạnh khi được chia sẻ vẻ đẹp độc đáo của ngôi nhà chúng tôi với mọi người thông qua những bức ảnh trong cuốn sách của cô.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"It is easy to reach 195 Strickland Boulevard by public transportation from Harrington Airport.\", \"vi\": \"Rất dễ dàng để đến số 195 đại lộ Strickland bằng phương tiện công cộng từ sân bay Harrington.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You simply take either Bus 412 or Bus 462 and get off at the final stop.\", \"vi\": \"Cô chỉ cần bắt Xe buýt 412 hoặc Xe buýt 462 và xuống ở trạm cuối cùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The house is about one block back in the direction the bus came from.\", \"vi\": \"Ngôi nhà cách đó khoảng một dãy nhà ngược lại hướng xe buýt vừa đi tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"In fact, you are quite likely to see it from the window shortly before arriving.\", \"vi\": \"Trên thực tế, cô rất có thể sẽ nhìn thấy nó từ cửa sổ ngay trước khi đến nơi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"If you have any problems finding it, you can call me at 555-0185.\", \"vi\": \"Nếu cô gặp bất kỳ vấn đề gì khi tìm đường, cô có thể gọi cho tôi theo số 555-0185.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I look forward to meeting you next week.\", \"vi\": \"Tôi rất mong được gặp cô vào tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Shane Armstrong\", \"vi\": \"Shane Armstrong\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"*E-Mail*\", \"vi\": \"*Thư điện tử*\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"# - Route - First Bus - Last Bus\", \"vi\": \"# - Tuyến đường - Chuyến xe đầu tiên - Chuyến xe cuối cùng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"410 - Airport → Downtown - 6:20 A.M. - 9:50 P.M.\", \"vi\": \"410 - Sân bay → Trung tâm thành phố - 6:20 Sáng - 9:50 Tối\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"412 - Airport → Downtown → Belmont - 6:05 A.M. - 10:05 P.M.\", \"vi\": \"412 - Sân bay → Trung tâm thành phố → Belmont - 6:05 Sáng - 10:05 Tối\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"437 - Airport → Riverfront → Abbott Heights - 6:25 A.M. - 9:55 P.M.\", \"vi\": \"437 - Sân bay → Bờ sông → Abbott Heights - 6:25 Sáng - 9:55 Tối\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"450 - Airport → Edgewood - 6:15 A.M. - 9:45 P.M.\", \"vi\": \"450 - Sân bay → Edgewood - 6:15 Sáng - 9:45 Tối\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"462 - Airport → Market District → Belmont - 6:10 A.M. - 10:10 P.M.\", \"vi\": \"462 - Sân bay → Khu thương mại → Belmont - 6:10 Sáng - 10:10 Tối\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"470 - Airport → Abbott Heights - 6:30 A.M. - 10:00 P.M.\", \"vi\": \"470 - Sân bay → Abbott Heights - 6:30 Sáng - 10:00 Tối\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Harrington Airport Bus Schedule\", \"vi\": \"Lịch trình xe buýt sân bay Harrington\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Seven days per week, year-round\", \"vi\": \"Bảy ngày một tuần, quanh năm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"HARRINGTON AIRPORT BUSES\", \"vi\": \"XE BUÝT SÂN BAY HARRINGTON\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Today (October 19), the airport bus to Edgewood will stop on Bishop Street instead of Yeager Avenue.\", \"vi\": \"Hôm nay (ngày 19 tháng 10), xe buýt sân bay đi Edgewood sẽ dừng ở phố Bishop thay vì đại lộ Yeager.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"This change is necessary because of road closures for the Fall Festival.\", \"vi\": \"Sự thay đổi này là cần thiết do việc đóng cửa đường phục vụ Lễ hội mùa thu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"For details, visit the tourism desk.\", \"vi\": \"Để biết chi tiết, vui lòng ghé thăm quầy thông tin du lịch.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"All bus passengers should be advised that, as always, your baggage cannot be placed on a seat unless you have bought the ticket for that specific seat.\", \"vi\": \"Tất cả hành khách đi xe buýt cần lưu ý rằng, như mọi khi, hành lý của quý vị không được đặt lên ghế trừ khi quý vị đã mua vé cho chỗ ngồi cụ thể đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Otherwise, the baggage must be stored underneath the bus.\", \"vi\": \"Nếu không, hành lý phải được cất ở khoang bên dưới xe buýt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"The bus driver will help you load and unload it safely.\", \"vi\": \"Tài xế xe buýt sẽ giúp quý vị chất và dỡ hành lý một cách an toàn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '16f2cab9-b437-4436-b7ae-30109069201a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Trust Elektroproof Repair to get your computer running right again!\", \"vi\": \"Hãy tin tưởng Dịch vụ Sửa chữa Elektroproof Repair để máy tính của bạn hoạt động bình thường trở lại!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Elektroproof Repair’s no-surprises policy offers flat fees for labor at three price points: $145, $200, and $350.\", \"vi\": \"Chính sách minh bạch của Elektroproof Repair đưa ra mức phí cố định cho nhân công ở ba mức giá: 145 USD, 200 USD và 350 USD.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"These fees do not include the cost of software or replacement parts.\", \"vi\": \"Các mức phí này không bao gồm chi phí phần mềm hoặc linh kiện thay thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The majority of our repairs incur the $200 fee.\", \"vi\": \"Phần lớn các dịch vụ sửa chữa của chúng tôi tính mức phí 200 USD.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"NOTE: Because of a dramatic increase in demand, we now require appointments for all services.\", \"vi\": \"LƯU Ý: Do nhu cầu tăng đột biến, chúng tôi hiện yêu cầu phải đặt lịch hẹn trước cho tất cả các dịch vụ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"For an initial consultation with one of our highly qualified technicians, simply select from the available time slots on our schedule page.\", \"vi\": \"Để được tư vấn ban đầu với một trong các kỹ thuật viên có trình độ chuyên môn cao của chúng tôi, bạn chỉ cần chọn từ các khung giờ trống trên trang lịch của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"When you schedule your appointment, we require a $60 nonrefundable deposit which will be credited toward the cost of services rendered.\", \"vi\": \"Khi bạn đặt lịch hẹn, chúng tôi yêu cầu khoản đặt cọc 60 USD không hoàn lại, khoản tiền này sẽ được trừ vào chi phí dịch vụ đã cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If you have any questions, please e-mail us at inquiries@elektroproofrepair.com.\", \"vi\": \"Nếu bạn có bất kỳ câu hỏi nào, vui lòng gửi email cho chúng tôi theo địa chỉ inquiries@elektroproofrepair.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Whenever possible, we will contact you the same day or on the following business day.\", \"vi\": \"Bất cứ khi nào có thể, chúng tôi sẽ liên hệ lại với bạn trong cùng ngày hoặc vào ngày làm việc tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Most repairs are completed within three to five business days.\", \"vi\": \"Hầu hết các dịch vụ sửa chữa được hoàn thành trong vòng từ ba đến năm ngày làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"https://www.elektroproofrepair.com/about\", \"vi\": \"https://www.elektroproofrepair.com/about\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: Jessica Nelson\", \"vi\": \"Đến: Jessica Nelson\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From: Arthur Jacquet\", \"vi\": \"Từ: Arthur Jacquet\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: January 14\", \"vi\": \"Ngày: 14 tháng 1\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Subject: Re: Tea spill, please help!\", \"vi\": \"Chủ đề: V/v: Tràn trà, hãy giúp tôi với!\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dear Ms. Nelson,\", \"vi\": \"Kính gửi chị Nelson,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thank you for contacting Elektroproof Repair.\", \"vi\": \"Cảm ơn chị đã liên hệ với Elektroproof Repair.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"You asked if you could bring in your laptop for inspection tomorrow, January 15.\", \"vi\": \"Chị đã hỏi liệu mình có thể mang máy tính xách tay đến để kiểm tra vào ngày mai, ngày 15 tháng 1 hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Unfortunately, we are currently booked solid through January 18.\", \"vi\": \"Thật không may, hiện tại chúng tôi đã kín lịch đến hết ngày 18 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"The earliest available time slot is 8:00 A.M. on January 19.\", \"vi\": \"Khung giờ trống sớm nhất là 8:00 sáng ngày 19 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Please let me know if you would like to book that slot or if you have any questions.\", \"vi\": \"Vui lòng cho tôi biết nếu chị muốn đặt khung giờ đó hoặc nếu chị có bất kỳ câu hỏi nào.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Arthur Jacquet, Elektroproof Repair\", \"vi\": \"Arthur Jacquet, Elektroproof Repair\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"E-Mail Message\", \"vi\": \"Tin nhắn Email\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"★★★★★\", \"vi\": \"★★★★★\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Elektroproof Repair\", \"vi\": \"Elektroproof Repair\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I spilled tea on the keyboard of my faithful old laptop, and while I dried the exterior rather quickly, I was afraid the internal components might have been ruined.\", \"vi\": \"Tôi vô tình làm đổ trà lên bàn phím của chiếc máy tính xách tay cũ thân thiết của mình, và mặc dù tôi đã lau khô bên ngoài khá nhanh chóng, tôi vẫn lo sợ các linh kiện bên trong có thể đã bị hỏng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Luckily for me, Elektroproof Repair came to the rescue!\", \"vi\": \"Thật may mắn cho tôi, Elektroproof Repair đã đến giải cứu!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"After booking my consultation on the Web site, I waited anxiously for a reply.\", \"vi\": \"Sau khi đặt lịch tư vấn trên trang web, tôi đã hồi hộp chờ đợi phản hồi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Within an hour, I got an e-mail directly from the owner.\", \"vi\": \"Trong vòng một giờ, tôi nhận được một email trực tiếp từ chủ cửa hàng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Although the time slot I had requested was not available, when I responded to his e-mail to express how urgently I needed my laptop, the owner said they had an unexpected cancellation and asked if I could bring it in that very morning, which I did.\", \"vi\": \"Mặc dù khung giờ tôi yêu cầu không có sẵn, nhưng khi tôi trả lời email của anh ấy để bày tỏ mức độ khẩn cấp mà tôi cần máy tính xách tay, chủ cửa hàng cho biết họ có một lịch hủy bất ngờ và hỏi liệu tôi có thể mang máy đến ngay sáng hôm đó không, và tôi đã làm vậy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Since my computer was not turned on at the time of the accident, an Elektroproof Repair technician was able to dry the computer\'s insides and prevent damage to the hard drive or internal circuits.\", \"vi\": \"Vì máy tính của tôi không được bật vào thời điểm xảy ra tai nạn, kỹ thuật viên của Elektroproof Repair đã có thể làm khô bên trong máy tính và ngăn ngừa hư hỏng cho ổ cứng hoặc các mạch điện bên trong.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Other than a new battery, no other part was needed, and Elektroproof Repair had my laptop fully functional and back in my hands within 24 hours.\", \"vi\": \"Ngoại trừ viên pin mới, không cần thêm bộ phận nào khác, và Elektroproof Repair đã giúp máy tính xách tay của tôi hoạt động hoàn hảo trở lại và trao lại vào tay tôi trong vòng 24 giờ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"—Jessica Nelson\", \"vi\": \"—Jessica Nelson\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"https://www.buyertobuyerintel.com/repair_services/electronics/computer_devices\", \"vi\": \"https://www.buyertobuyerintel.com/repair_services/electronics/computer_devices\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '1700e474-f73b-49b2-bb8b-e412023c90b4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Protecto Umbrella Wrapping Machines\", \"vi\": \"Máy bọc ô dù Protecto\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Visitors entering and walking through a building with wet umbrellas unintentionally create wet and slippery floors.\", \"vi\": \"Những khách tham quan bước vào và đi qua tòa nhà với những chiếc ô bị ướt sẽ vô tình tạo ra sàn nhà ướt và trơn trượt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The Protecto Umbrella Wrapping machine (PUW machine) provides a simple and convenient way to address this problem.\", \"vi\": \"Máy bọc ô dù Protecto (máy PUW) cung cấp một cách đơn giản và tiện lợi để giải quyết vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The machine is best placed in the entryway of your building.\", \"vi\": \"Chiếc máy này tốt nhất nên được đặt ở lối ra vào của tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Upon entry, visitors insert their wet umbrellas into the machine.\", \"vi\": \"Khi bước vào, khách tham quan sẽ đưa những chiếc ô ướt của họ vào máy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"It automatically wraps the umbrella in a clear plastic bag, after which visitors can take their umbrellas.\", \"vi\": \"Máy sẽ tự động bọc chiếc ô trong một túi nhựa trong suốt, sau đó khách tham quan có thể lấy ô của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Upon leaving, they can discard the used bags in any nearby trash can.\", \"vi\": \"Khi rời đi, họ có thể vứt những chiếc túi đã qua sử dụng vào bất kỳ thùng rác gần đó nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"PUW machines are available with one or two umbrella-wrapping devices and come in stainless steel or black.\", \"vi\": \"Máy PUW có sẵn loại một hoặc hai thiết bị bọc ô và có chất liệu bằng thép không gỉ hoặc màu đen.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The machine wraps umbrellas in 1.5 seconds.\", \"vi\": \"Máy bọc ô trong vòng 1,5 giây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The stand is mobile and thus can be rolled around to different locations.\", \"vi\": \"Giá đỡ có tính cơ động và do đó có thể được lăn đến các địa điểm khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Purchase a PUW machine throughout November and receive a lightweight umbrella featuring our company logo.\", \"vi\": \"Hãy mua máy PUW trong suốt tháng 11 và nhận ngay một chiếc ô nhẹ có in logo công ty của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Product Number - Description - Price per Unit\", \"vi\": \"Mã sản phẩm - Mô tả - Giá mỗi đơn vị\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"143 - PUW machine with two umbrella-wrapping devices. Price includes 2,000 bags. Perfect for large, high-foot-traffic areas. Available in stainless steel or black. - $450\", \"vi\": \"143 - Máy PUW với hai thiết bị bọc ô. Giá đã bao gồm 2.000 túi. Hoàn hảo cho các khu vực rộng lớn, có lượng người qua lại cao. Có sẵn bằng thép không gỉ hoặc màu đen. - $450\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"144 - PUW machine with one umbrella-wrapping device. Price includes 1,000 bags. Available in stainless steel or black. - $350\", \"vi\": \"144 - Máy PUW với một thiết bị bọc ô. Giá đã bao gồm 1.000 túi. Có sẵn bằng thép không gỉ hoặc màu đen. - $350\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"192 - Box of 3,000 plastic bags for refilling any of our units. Available online only. - $100\", \"vi\": \"192 - Hộp 3.000 túi nhựa dùng để nạp đầy cho bất kỳ thiết bị nào của chúng tôi. Chỉ có sẵn trực tuyến. - $100\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"194 - Box of 1,000 plastic bags for refilling any of our units. Available online only. - $35\", \"vi\": \"194 - Hộp 1.000 túi nhựa dùng để nạp đầy cho bất kỳ thiết bị nào của chúng tôi. Chỉ có sẵn trực tuyến. - $35\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Protecto Products Price List\", \"vi\": \"Bảng giá sản phẩm Protecto\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"https://www.setterlyproductreviews.com/officeequipment\", \"vi\": \"https://www.setterlyproductreviews.com/officeequipment\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Office Equipment Review: Protecto Umbrella Wrapping Machines\", \"vi\": \"Đánh giá thiết bị văn phòng: Máy bọc ô dù Protecto\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I love our new PUW machine!\", \"vi\": \"Tôi rất thích chiếc máy PUW mới của chúng tôi!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"As the facilities manager of a medium-sized office building, I often have to deal with the inconvenience of wet floors caused by visitors entering with umbrellas.\", \"vi\": \"Là quản lý cơ sở của một tòa nhà văn phòng quy mô vừa, tôi thường xuyên phải đối mặt với sự bất tiện do sàn nhà bị ướt do khách tham quan mang ô đi vào.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"We used to have a large umbrella stand in the lobby where visitors could leave umbrellas, but only a few people used it.\", \"vi\": \"Chúng tôi từng có một giá để ô lớn ở sảnh để khách tham quan có thể để ô, nhưng chỉ có vài người sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Then we tried an umbrella stand that included disposable plastic bags that visitors could tear off and put their umbrellas in.\", \"vi\": \"Sau đó, chúng tôi đã thử một giá để ô có kèm theo các túi nhựa dùng một lần mà khách tham quan có thể xé ra và đặt ô của họ vào.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"However, this method was ineffective because the bags were rather flimsy, thus failing to prevent water leakage.\", \"vi\": \"Tuy nhiên, phương pháp này không hiệu quả vì túi khá mỏng, do đó không thể ngăn được tình trạng rò rỉ nước.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"So, in November, we decided to try a PUW machine.\", \"vi\": \"Vì vậy, vào tháng 11, chúng tôi quyết định dùng thử máy PUW.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Because we have many visitors, we purchased the PUW machine with two devices and ordered it in stainless steel to match our modern-looking lobby.\", \"vi\": \"Vì chúng tôi có rất nhiều khách tham quan, chúng tôi đã mua máy PUW với hai thiết bị và đặt làm bằng thép không gỉ để phù hợp với sảnh có thiết kế hiện đại của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Since then, the entranceway has been safer and cleaner.\", \"vi\": \"Kể từ đó, lối vào đã trở nên an toàn và sạch sẽ hơn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Visitors love that it is automatic, and everyone is grateful that the lobby is no longer wet and slippery because of umbrellas dripping with water!\", \"vi\": \"Khách tham quan rất thích tính năng tự động của máy, và mọi người đều biết ơn vì sảnh không còn bị ướt và trơn trượt do những chiếc ô nhỏ giọt nước!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"—Andrew Barr\", \"vi\": \"—Andrew Barr\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}]' WHERE `id` = '1721e4ce-5bf2-4584-9cd7-6efcd6f39b0d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Gorman Unveils Newest\", \"vi\": \"Gorman Ra Mắt Mẫu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Smartphone Model\", \"vi\": \"Điện Thoại Thông Minh Mới Nhất\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"LONDON (20 April)—Gorman Mobile unveiled its newest smartphone to an eager reception at the annual Technobrit Conference.\", \"vi\": \"LONDON (20 tháng 4)—Gorman Mobile đã giới thiệu mẫu điện thoại thông minh mới nhất của mình trong sự đón nhận hào hứng tại Hội nghị Technobrit thường niên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The Pro Phone 4, which includes 512 GB of storage, a 7-inch screen display, and an optional stylus pen, will hit the shelves on 11 June.\", \"vi\": \"Chiếc Pro Phone 4, bao gồm bộ nhớ 512 GB, màn hình hiển thị 7 inch và bút cảm ứng tùy chọn, sẽ lên kệ vào ngày 11 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Unlike its predecessor—the Pro Phone 3—it features a larger screen, an ultrawide camera lens, and 8K-resolution filming capability.\", \"vi\": \"Không giống như phiên bản tiền nhiệm—Pro Phone 3—nó sở hữu màn hình lớn hơn, ống kính máy ảnh siêu rộng và khả năng quay phim độ phân giải 8K.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The £999 starting price is £100 more than that of the previous model.\", \"vi\": \"Mức giá khởi điểm 999 bảng Anh cao hơn 100 bảng Anh so với mẫu máy trước đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Add-ons, such as the stylus pen, protective case, and wireless headphones, cost an additional £39, £59, and £79, respectively.\", \"vi\": \"Các phụ kiện bổ sung, chẳng hạn như bút cảm ứng, ốp lưng bảo vệ và tai nghe không dây, có giá lần lượt là 39 bảng Anh, 59 bảng Anh và 79 bảng Anh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Gorman Product Manager Ian Hill doesn\'t believe the price increase will dissuade customers.\", \"vi\": \"Giám đốc Sản phẩm của Gorman, Ian Hill, không tin rằng việc tăng giá sẽ làm khách hàng nản lòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"“The Pro Phone 4 is a game changer in terms of its picture quality and sleek design,” said Hill.\", \"vi\": \"\\\"Pro Phone 4 là một bước đột phá về chất lượng hình ảnh và thiết kế tinh xảo,\\\" Hill cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"“Improvements were based on direct customer feedback, which cited the poor camera functionality as the biggest drawback of prior models.\", \"vi\": \"\\\"Các cải tiến dựa trên phản hồi trực tiếp của khách hàng, trong đó chức năng máy ảnh kém được coi là nhược điểm lớn nhất của các mẫu máy trước đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Our clients spoke, and we listened and adapted accordingly.”\", \"vi\": \"Khách hàng của chúng tôi đã lên tiếng, và chúng tôi đã lắng nghe và điều chỉnh cho phù hợp.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [3] —\", \"vi\": \"— [3] —\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"One similarity that the Pro Phone 4 has with previous models is the charger.\", \"vi\": \"Một điểm tương đồng mà Pro Phone 4 có so với các mẫu trước đó là bộ sạc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Going against the trend of competing wireless companies, Gorman is instead focusing on convenience.\", \"vi\": \"Đi ngược lại xu hướng của các công ty viễn thông cạnh tranh, Gorman thay vào đó tập trung vào sự tiện lợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"“We want to afford our customers the ability to reuse elements of the other Gorman devices they’ve already purchased,” said Hill.\", \"vi\": \"\\\"Chúng tôi muốn mang lại cho khách hàng khả năng tái sử dụng các bộ phận của các thiết bị Gorman khác mà họ đã mua,\\\" Hill nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"“Why add to the overload of cables already in circulation?”\", \"vi\": \"\\\"Tại sao lại làm tăng thêm tình trạng quá tải cáp sạc đang lưu hành?\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '173344ee-3313-405d-ae2f-a51a2d33e7cc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"New Garden Coming Soon to\\nRaxford Park\", \"vi\": \"Vườn mới sắp ra mắt tại\\nCông viên Raxford\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"ELBART CITY (March 30)—Local community group Friends of Green Spaces (FGS) is raising funds to build a new garden in Raxford Park.\", \"vi\": \"THÀNH PHỐ ELBART (Ngày 30 tháng 3)—Nhóm cộng đồng địa phương Friends of Green Spaces (FGS) đang gây quỹ để xây dựng một khu vườn mới trong Công viên Raxford.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The group, which relies entirely on donations, collaborates with the city parks department on restoration and enhancement.\", \"vi\": \"Nhóm này, hoạt động hoàn toàn dựa vào tiền quyên góp, hợp tác với sở quản lý công viên thành phố về công tác trùng tu và tôn tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"It also offers guided nature tours and other educational programs.\", \"vi\": \"Nhóm cũng cung cấp các chuyến tham quan thiên nhiên có hướng dẫn viên và các chương trình giáo dục khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"“The goal of the current project,” said FGS director Carol Reynoso, “is to create an attractive space to draw in more of the region’s abundant birdlife.”\", \"vi\": \"Giám đốc FGS Carol Reynoso cho biết: “Mục tiêu của dự án hiện tại là tạo ra một không gian hấp dẫn để thu hút nhiều loài chim phong phú trong vùng hơn.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Ms. Reynoso, a 25-year member of the FGS, is a lifelong resident of Elbart City.\", \"vi\": \"Bà Reynoso, người đã có 25 năm là thành viên của FGS, là cư dân lâu năm của Thành phố Elbart.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"She is especially enthusiastic about the project because the city’s elementary school borders the park.\", \"vi\": \"Bà đặc biệt nhiệt tình với dự án vì trường tiểu học của thành phố nằm giáp với công viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This means that the schoolchildren will be able to enjoy the garden every day.\", \"vi\": \"Điều này có nghĩa là các em học sinh sẽ có thể tận hưởng khu vườn mỗi ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Ms. Reynoso said that enough funds have already been secured to enable the FGS to begin garden construction in mid-April.\", \"vi\": \"Bà Reynoso cho biết đã có đủ số tiền gây quỹ được bảo đảm để cho phép FGS bắt đầu xây dựng khu vườn vào giữa tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The selection of plants will be made by Elbart University faculty.\", \"vi\": \"Việc lựa chọn các loại cây sẽ do giảng viên Đại học Elbart thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"FGS volunteers will do the planting after parks department crews have laid fresh topsoil on the area designated for the garden.\", \"vi\": \"Các tình nguyện viên của FGS sẽ tiến hành trồng cây sau khi các đội ngũ nhân viên sở công viên rải lớp đất mặt mới lên khu vực được chỉ định cho khu vườn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"An opening ceremony is planned for May.\", \"vi\": \"Lễ khai trương được lên kế hoạch vào tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '1751dc47-cf7d-42a8-823d-ff127daa0f52';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Keep Cool Service Contractors:\", \"vi\": \"Nhà thầu Dịch vụ Keep Cool:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"67 Main Road, Edinburgh Village\", \"vi\": \"67 Main Road, Edinburgh Village\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Chaguanas, Trinidad and Tobago\", \"vi\": \"Chaguanas, Trinidad và Tobago\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Keep Cool Service Contractors can bring you peace of mind.\", \"vi\": \"Nhà thầu Dịch vụ Keep Cool có thể mang lại cho bạn sự an tâm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"As part of an annual contract, we will service your air-conditioning system, ensuring your _____135_____ and comfort.\", \"vi\": \"Là một phần của hợp đồng hàng năm, chúng tôi sẽ bảo dưỡng hệ thống điều hòa không khí của bạn, đảm bảo _____135_____ và sự thoải mái cho bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [135]}, {\"en\": \"This includes inspecting the system, making repairs as needed, and professionally cleaning your air ducts.\", \"vi\": \"Điều này bao gồm việc kiểm tra hệ thống, thực hiện sửa chữa khi cần thiết và vệ sinh chuyên nghiệp các ống dẫn khí của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"_____136_____, if necessary, we can replace your old air-conditioning system with a new, cost-efficient one.\", \"vi\": \"_____136_____, nếu cần thiết, chúng tôi có thể thay thế hệ thống điều hòa cũ của bạn bằng một hệ thống mới, tiết kiệm chi phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [136]}, {\"en\": \"Our workers are highly qualified licensed technicians who stay up-to-date with ongoing training.\", \"vi\": \"Nhân viên của chúng tôi là các kỹ thuật viên có giấy phép và trình độ chuyên môn cao, luôn cập nhật các khóa đào tạo liên tục.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"_____137_____ .\", \"vi\": \"_____137_____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [137]}, {\"en\": \"We promise you fair prices and professional work, _____138_____ by our Keep Cool guarantee.\", \"vi\": \"Chúng tôi cam kết mức giá hợp lý và công việc chuyên nghiệp, _____138_____ được đảm bảo bởi cam kết Keep Cool của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [138]}, {\"en\": \"Call 1-868-555-0129 for a free quote today.\", \"vi\": \"Hãy gọi 1-868-555-0129 để nhận báo giá miễn phí ngay hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '17989ae1-6855-43aa-b09a-1f5cf5b765e2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: mstoch@hesidionclinic.com\", \"vi\": \"Từ: mstoch@hesidionclinic.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: lstawinski@nostilde.com\", \"vi\": \"Đến: lstawinski@nostilde.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 20\", \"vi\": \"Ngày: 20 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Hesidion Clinic\'s Health Awareness Day\", \"vi\": \"Chủ đề: Ngày hội Nâng cao Nhận thức Sức khỏe của Phòng khám Hesidion\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Stawinski,\", \"vi\": \"Kính gửi Chị Stawinski,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"In appreciation of your loyalty as a long-time patient of Hesidion Clinic, we are pleased to invite you to our clinic\'s Health Awareness Day to be held at the clinic on Saturday, April 10.\", \"vi\": \"Để tri ân sự gắn bó của chị với tư cách là bệnh nhân lâu năm của Phòng khám Hesidion, chúng tôi trân trọng kính mời chị tham gia Ngày hội Nâng cao Nhận thức Sức khỏe của phòng khám diễn ra tại đây vào thứ Bảy, ngày 10 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We would be delighted to see you attend, as we will offer a number of activities designed to promote health awareness in our community.\", \"vi\": \"Chúng tôi rất hân hạnh được đón tiếp chị tham dự, vì chúng tôi sẽ tổ chức nhiều hoạt động nhằm thúc đẩy nhận thức về sức khỏe trong cộng đồng của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If you sign up for this special event by responding to this e-mail by March 31, you will receive a code to present at the clinic for a surprise benefit.\", \"vi\": \"Nếu chị đăng ký tham gia sự kiện đặc biệt này bằng cách phản hồi lại email này trước ngày 31 tháng 3, chị sẽ nhận được một mã để trình bày tại phòng khám nhằm nhận một phần quà bất ngờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Martin Stoch, Communications Director, Hesidion Clinic\", \"vi\": \"Martin Stoch, Giám đốc Truyền thông, Phòng khám Hesidion\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Hesidion Clinic Health Awareness Day, April 10\\nTasks and Responsibilities\", \"vi\": \"Ngày hội Nâng cao Nhận thức Sức khỏe Phòng khám Hesidion, Ngày 10 tháng 4\\nNhiệm vụ và Trách nhiệm\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Communications: Martin Stoch\", \"vi\": \"Truyền thông: Martin Stoch\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Advertising: Adilene Walker\", \"vi\": \"Quảng cáo: Adilene Walker\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Presentations: Jillian Opala (Nutrition), Lance Verhoeven (Fitness)\", \"vi\": \"Bài thuyết trình: Jillian Opala (Dinh dưỡng), Lance Verhoeven (Thể hình)\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Kids\' Health Game: Susan Hayashi\", \"vi\": \"Trò chơi Sức khỏe Trẻ em: Susan Hayashi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Health Checkups/Talks: Anne Spillane, Rami Al-Araj, Kurt Yin, Thierry Daumas\", \"vi\": \"Khám sức khỏe/Tư vấn: Anne Spillane, Rami Al-Araj, Kurt Yin, Thierry Daumas\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Health Day at Hesidion Clinic\", \"vi\": \"Ngày hội Sức khỏe tại Phòng khám Hesidion\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"by Shai Herzog on April 14\", \"vi\": \"bởi Shai Herzog vào ngày 14 tháng 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Hesidion Clinic hosted a successful Health Awareness Day this past Saturday.\", \"vi\": \"Phòng khám Hesidion đã tổ chức Ngày hội Nâng cao Nhận thức Sức khỏe thành công vào thứ Bảy vừa qua.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The event was held as a way to thank the community for supporting the clinic over the past 15 years.\", \"vi\": \"Sự kiện được tổ chức như một cách để cảm ơn cộng đồng vì đã hỗ trợ phòng khám trong suốt 15 năm qua.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"It was well attended by both Hesidion Clinic patients and members of the general public.\", \"vi\": \"Sự kiện thu hút đông đảo cả bệnh nhân của Phòng khám Hesidion lẫn công chúng tham dự.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Attendees participated in a variety of presentations and everyone received free water bottles, notepads, and other items from event sponsors.\", \"vi\": \"Những người tham gia đã trải nghiệm nhiều bài thuyết trình đa dạng và tất cả mọi người đều nhận được bình nước miễn phí, sổ tay và các vật phẩm khác từ nhà tài trợ sự kiện.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Participants who provided a special code were offered a complimentary physical checkup from the team of clinic physicians.\", \"vi\": \"Những người tham gia cung cấp mã đặc biệt đã được tặng một buổi khám tổng quát miễn phí từ đội ngũ bác sĩ của phòng khám.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"During the event, a sizable line formed at Dr. Thierry Daumas\' table.\", \"vi\": \"Trong suốt sự kiện, một hàng người khá dài đã xếp tại bàn của Tiến sĩ Thierry Daumas.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"\\\"I came out today to learn about skin care and advances in eye-care technology.\", \"vi\": \"\\\"Hôm nay tôi đến đây để tìm hiểu về chăm sóc da và những tiến bộ trong công nghệ chăm sóc mắt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"But Dr. Daumas\' talk about how to prevent cavities and improve oral health provided me with the most helpful information,\\\" said attendee Liana Stawinski.\", \"vi\": \"Nhưng bài nói chuyện của Tiến sĩ Daumas về cách phòng ngừa sâu răng và cải thiện sức khỏe răng miệng lại cung cấp cho tôi nhiều thông tin hữu ích nhất,\\\" người tham dự Liana Stawinski chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"By far the most popular event was nutritionist Jillian Opala\'s presentation on healthy eating habits.\", \"vi\": \"Sự kiện thu hút lượng người quan tâm đông đảo nhất chính là bài thuyết trình về thói quen ăn uống lành mạnh của chuyên gia dinh dưỡng Jillian Opala.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"More than 100 people, many of them retirees, flocked to hear the latest on super foods.\", \"vi\": \"Hơn 100 người, phần lớn là người cao tuổi về hưu, đã đổ xô đến để nghe những thông tin mới nhất về siêu thực phẩm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"The event took nearly twice as long as expected, as Ms. Opala answered a steady stream of participant questions.\", \"vi\": \"Sự kiện kéo dài gần gấp đôi thời gian dự kiến do cô Opala phải liên tục trả lời hàng loạt câu hỏi từ người tham gia.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Children were delighted to take part in a health contest involving questions about general health and hygiene.\", \"vi\": \"Trẻ em vô cùng hào hứng khi được tham gia một cuộc thi sức khỏe bao gồm các câu hỏi về sức khỏe tổng quát và vệ sinh.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"The winners received toys and certificates from the game host.\", \"vi\": \"Những người chiến thắng đã nhận được đồ chơi và giấy chứng nhận từ người dẫn chương trình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"The day was such a success that Hesidion Clinic director, Lance Verhoeven, is already considering making it an annual event.\", \"vi\": \"Sự kiện thành công rực rỡ đến mức giám đốc Phòng khám Hesidion, ông Lance Verhoeven, đang cân nhắc biến đây thành sự kiện thường niên.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = '179d9a7c-10b0-4ac6-b86d-eae17969a666';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Visiting Carlin County? Don\'t miss these points of interest!\", \"vi\": \"Bạn đang ghé thăm Quận Carlin? Đừng bỏ lỡ những điểm tham quan thú vị này!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Avevo Botanical Garden\", \"vi\": \"Vườn Bách thảo Avevo\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Rever Concert Hall\", \"vi\": \"Nhà hát Hòa nhạc Rever\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Carlin County Museum of Art\", \"vi\": \"Bảo tàng Nghệ thuật Quận Carlin\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The Maritime Museum\", \"vi\": \"Bảo tàng Hàng hải\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Open daily, 9 A.M.-6 P.M.; $8 admission\", \"vi\": \"Mở cửa hàng ngày, 9 giờ sáng - 6 giờ chiều; phí vào cửa 8 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"With stunning views of Gull Bay, the Avevo Botanical Garden is a beautiful place to examine and learn about the region\'s abundant and diverse plant life.\", \"vi\": \"Với tầm nhìn tuyệt đẹp ra Vịnh Gull, Vườn Bách thảo Avevo là một nơi tuyệt vời để ngắm nhìn và tìm hiểu về hệ thực vật phong phú và đa dạng của vùng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Open to the public Monday to Friday, 10 A.M.-4 P.M.\", \"vi\": \"Mở cửa đón khách công cộng từ Thứ Hai đến Thứ Sáu, 10 giờ sáng - 4 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Designed by renowned architect Ang Zhao, the Rever Concert Hall has striking architecture and is well worth a visit.\", \"vi\": \"Được thiết kế bởi kiến trúc sư nổi tiếng Ang Zhao, Nhà hát Hòa nhạc Rever có kiến trúc nổi bật và rất đáng để ghé thăm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Guided tours are available for $2 per person.\", \"vi\": \"Có các tour tham quan có hướng dẫn với giá 2 USD mỗi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Open daily, 10 A.M.-7 P.M.; $5 admission\", \"vi\": \"Mở cửa hàng ngày, 10 giờ sáng - 7 giờ tối; phí vào cửa 5 USD\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"This lovely art museum focuses on works by local artists.\", \"vi\": \"Bảo tàng nghệ thuật đáng yêu này tập trung vào các tác phẩm của các nghệ sĩ địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Special exhibits rotate monthly.\", \"vi\": \"Các cuộc triển lãm đặc biệt thay đổi hàng tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Open Wednesday to Sunday, 9 A.M.-4 P.M.; no fee, but donations are welcome\", \"vi\": \"Mở cửa từ Thứ Tư đến Chủ Nhật, 9 giờ sáng - 4 giờ chiều; miễn phí, nhưng rất hoan nghênh các khoản đóng góp\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"An impressive collection of historical artifacts makes the Maritime Museum a wonderful place to learn about the region\'s seafaring history.\", \"vi\": \"Bộ sưu tập ấn tượng các hiện vật lịch sử biến Bảo tàng Hàng hải thành một nơi tuyệt vời để tìm hiểu về lịch sử đi biển của vùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"This museum is located on a retired ship on East Beach.\", \"vi\": \"Bảo tàng này nằm trên một con tàu đã ngừng hoạt động tại Bãi biển Đông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '17b7b659-99d9-44d1-a954-cf346120d646';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Uncle Pete\'s Marionette Theater Presents\", \"vi\": \"Nhà hát Rối cạn Uncle Pete\'s Giới thiệu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Moose Lake\", \"vi\": \"Hồ Sừng Tấm (Moose Lake)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"March 27-May 7\", \"vi\": \"Ngày 27 tháng 3 - Ngày 7 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Ever since the founding of Uncle Pete\'s Marionette Theater, our adaptation of the well-known ballet Moose Lake has been one of our most beloved shows.\", \"vi\": \"Kể từ khi thành lập Nhà hát Rối cạn Uncle Pete\'s, vở kịch chuyển thể của chúng tôi từ vở ba-lê nổi tiếng Hồ Sừng Tấm vẫn luôn là một trong những chương trình được yêu thích nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Our 100 handcrafted marionettes will take you on a thrilling adventure into the world of Moose Lake.\", \"vi\": \"100 con rối làm thủ công của chúng tôi sẽ đưa bạn bước vào một cuộc phiêu lưu ly kỳ trong thế giới của Hồ Sừng Tấm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As our skilled puppeteers pull the strings and make the puppets move, you will cheer for Maria and the Moose Prince.\", \"vi\": \"Khi những nghệ sĩ múa rối tài năng của chúng tôi kéo dây và làm cho các con rối chuyển động, bạn sẽ cổ vũ cho Maria và Hoàng tử Sừng Tấm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"You may be unhappy with the Lizard King and his minions.\", \"vi\": \"Bạn có thể cảm thấy bất bình với Vua Thằn Lằn và đám tay sai của hắn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You will be enthralled by the Drifting Dragonflies!\", \"vi\": \"Bạn sẽ bị cuốn hút bởi những chú Chuồn chuồn Bay lượn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Uncle Pete\'s version of Moose Lake has been delighting viewers of all ages for more than 30 years.\", \"vi\": \"Phiên bản Hồ Sừng Tấm của Uncle Pete\'s đã làm say lòng khán giả ở mọi lứa tuổi trong hơn 30 năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Shows sell out every year, so get your tickets today.\", \"vi\": \"Các suất diễn đều kín chỗ mỗi năm, vì vậy hãy mua vé của bạn ngay hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Tickets are available at the box office, 521 Perry Avenue, Fenton.\", \"vi\": \"Vé được bán tại phòng vé, số 521 Đại lộ Perry, Fenton.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '17f0df4f-1030-495c-8bd8-03f7a29950b0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Do You Want to Perfect Your Garden?\", \"vi\": \"Bạn Có Muốn Hoàn Thiện Khu Vườn Của Mình Không?\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"This spring, let Rutherford Garden Center help you create the garden of your dreams!\", \"vi\": \"Mùa xuân này, hãy để Trung tâm Làm vườn Rutherford giúp bạn tạo nên khu vườn trong mơ của mình!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Choose from among our ample collection of flowers, vegetables, herbs, shrubs, and more.\", \"vi\": \"Lựa chọn từ bộ sưu tập phong phú của chúng tôi gồm hoa, rau, thảo mộc, cây bụi và nhiều hơn thế nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"______[135] pick up the appropriate supplies, from rich fertilizer to gardening implements.\", \"vi\": \"______[135] mua các vật dụng phù hợp, từ phân bón giàu dinh dưỡng đến dụng cụ làm vườn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [135]}, {\"en\": \"We even have unique decorative items!\", \"vi\": \"Chúng tôi thậm chí còn có các mặt hàng trang trí độc đáo!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[136] Our friendly, knowledgeable employees are happy to advise you ______[137] what to buy and how to tend your new plants.\", \"vi\": \"______[136] Nhân viên thân thiện, am hiểu của chúng tôi rất sẵn lòng tư vấn cho bạn ______[137] những gì nên mua và cách chăm sóc cây trồng mới của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [136, 137]}, {\"en\": \"All seedlings and starter plants at Rutherford Garden Center have received all ______[138] care and nourishment.\", \"vi\": \"Tất cả cây con và cây giống tại Trung tâm Làm vườn Rutherford đều đã nhận được sự chăm sóc và dưỡng chất ______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [138]}, {\"en\": \"We will not sell you a plant that is less than 100% healthy.\", \"vi\": \"Chúng tôi sẽ không bán cho bạn một cây nào có độ khỏe mạnh dưới 100%.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Visit us today to see for yourself!\", \"vi\": \"Hãy đến thăm chúng tôi ngay hôm nay để tận mắt chứng kiến!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '1809fe2e-d2dd-4c34-8b31-ba85291e2e8c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Shipping Team\", \"vi\": \"Đến: Đội ngũ Vận chuyển\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Martina West\", \"vi\": \"Từ: Martina West\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: February 21\", \"vi\": \"Ngày: 21 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Exciting news\", \"vi\": \"Chủ đề: Tin vui\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Team,\", \"vi\": \"Kính gửi Đội ngũ,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am excited to share the news that Winnie Liu, our longtime team captain, will be moving on.\", \"vi\": \"Tôi rất vui được chia sẻ tin tức rằng Winnie Liu, đội trưởng lâu năm của chúng ta, sẽ chuyển công tác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Fortunately, she will not be leaving the company.\", \"vi\": \"May mắn thay, cô ấy sẽ không rời khỏi công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"------- (135), Winnie will serve as our new regional distribution manager.\", \"vi\": \"------- (135), Winnie sẽ đảm nhận vị trí quản lý phân phối khu vực mới của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [135]}, {\"en\": \"We are thrilled about her ------- (136).\", \"vi\": \"Chúng tôi vô cùng vui mừng về ------- (136) của cô ấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [136]}, {\"en\": \"We would like to show our appreciation for everything Winnie has done for our department, especially for our team.\", \"vi\": \"Chúng tôi muốn bày tỏ lòng biết ơn đối với mọi thứ Winnie đã làm cho bộ phận của chúng ta, đặc biệt là cho đội ngũ của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We will be hosting a party for Winnie in the break room at 3:00 P.M. on February 28, her ------- (137) day with us.\", \"vi\": \"Chúng tôi sẽ tổ chức một bữa tiệc chia tay Winnie tại phòng nghỉ vào lúc 3:00 chiều ngày 28 tháng 2, ngày làm việc ------- (137) của cô ấy với chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [137]}, {\"en\": \"------- (138).\", \"vi\": \"------- (138).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [138]}, {\"en\": \"We look forward to seeing you there.\", \"vi\": \"Chúng tôi rất mong được gặp các bạn ở đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Martina West, Shipping Manager, Croce Company\", \"vi\": \"Martina West, Trưởng phòng Vận chuyển, Công ty Croce\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '181579f4-2f2e-4058-94a3-fa36fdf32c52';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mary Figueredo (10:03 A.M.)\", \"vi\": \"Mary Figueredo (10:03 Sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Ben.\", \"vi\": \"Chào Ben.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Has your team started repairing the fences at the warehouse?\", \"vi\": \"Nhóm của anh đã bắt đầu sửa chữa các hàng rào ở nhà kho chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Benjamin Hunter (10:05 A.M.)\", \"vi\": \"Benjamin Hunter (10:05 Sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hello, Mary.\", \"vi\": \"Xin chào Mary.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We\'ll get to it soon.\", \"vi\": \"Chúng tôi sẽ tiến hành việc đó sớm thôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We had some standing water in the entryway to clean up first.\", \"vi\": \"Chúng tôi phải dọn dẹp lượng nước đọng ở lối vào trước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Mary Figueredo (10:06 A.M.)\", \"vi\": \"Mary Figueredo (10:06 Sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Do you think the roof might have sustained some damage during the rainstorm?\", \"vi\": \"Anh có nghĩ là mái nhà có thể đã bị hư hại trong trận mưa bão không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Benjamin Hunter (10:08 A.M.)\", \"vi\": \"Benjamin Hunter (10:08 Sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We actually located the source.\", \"vi\": \"Thực ra chúng tôi đã tìm ra nguyên nhân rồi.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It was a clogged drainpipe in the supply closet.\", \"vi\": \"Đó là một ống thoát nước bị tắc trong phòng chứa vật dụng.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"As soon as that\'s cleared up, we\'ll take care of the fence.\", \"vi\": \"Ngay khi việc đó được giải quyết xong, chúng tôi sẽ xử lý phần hàng rào.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The roof seems fine.\", \"vi\": \"Mái nhà có vẻ vẫn ổn.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Mary Figueredo (10:11 A.M.)\", \"vi\": \"Mary Figueredo (10:11 Sáng)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"OK, sounds good, Ben.\", \"vi\": \"Được rồi, nghe được đấy, Ben.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thank you!\", \"vi\": \"Cảm ơn anh!\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '189b28f9-deb7-40ab-bfbe-8e112e79837b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Hiroaki Yoneya <hyoneya@westernstatesmilling.net>\", \"vi\": \"Từ: Hiroaki Yoneya <hyoneya@westernstatesmilling.net>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Clay Crosby <ccrosby@westernstatesmilling.net>\", \"vi\": \"Đến: Clay Crosby <ccrosby@westernstatesmilling.net>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: June 1\", \"vi\": \"Ngày: 1 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Baseball night\", \"vi\": \"Chủ đề: Đêm xem bóng chày\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Clay,\", \"vi\": \"Clay,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"You may remember that we recently discussed ideas for an outing for the employees and their families.\", \"vi\": \"Anh có thể nhớ rằng chúng ta gần đây đã thảo luận về các ý tưởng cho một buổi dã ngoại dành cho nhân viên và gia đình của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I think the best idea is to go to a baseball game.\", \"vi\": \"Tôi nghĩ ý tưởng hay nhất là đi xem một trận đấu bóng chày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I have always enjoyed taking my family to see the Billington Buffaloes, our local team.\", \"vi\": \"Tôi vẫn luôn thích đưa gia đình đi xem đội Billington Buffaloes, đội bóng địa phương của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"You might have noticed that several of the photos in my office were taken at the stadium!\", \"vi\": \"Anh có thể đã nhận thấy rằng một số bức ảnh trong văn phòng của tôi được chụp tại sân vận động!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"And since I usually see other staff members at the games, I think this will appeal to most of our group.\", \"vi\": \"Và vì tôi thường gặp các nhân viên khác tại các trận đấu, tôi nghĩ điều này sẽ thu hút phần lớn nhóm của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Could you please set this up for June 28?\", \"vi\": \"Anh có thể vui lòng sắp xếp việc này cho ngày 28 tháng 6 được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I believe it can all be done online if you prefer.\", \"vi\": \"Tôi tin rằng tất cả có thể được thực hiện trực tuyến nếu anh thích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"By my calculations, we will need 45 tickets in total, but please double-check this number.\", \"vi\": \"Theo tính toán của tôi, chúng ta sẽ cần tổng cộng 45 vé, nhưng xin hãy kiểm tra lại con số này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Also, I would like food to be provided.\", \"vi\": \"Ngoài ra, tôi muốn có đồ ăn được cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Let\'s limit our cost to under $20 per person and make sure the seating is covered just in case the weather is poor.\", \"vi\": \"Hãy giới hạn chi phí của chúng ta dưới 20 đô la mỗi người và đảm bảo khu vực chỗ ngồi có mái che đề phòng trường hợp thời tiết xấu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Please send me the details as soon as the tickets are purchased.\", \"vi\": \"Vui lòng gửi cho tôi các chi tiết ngay sau khi vé được mua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Hiroaki Yoneya, Associate Manager\", \"vi\": \"Hiroaki Yoneya, Trợ lý Giám đốc\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Western States Milling, Inc.\", \"vi\": \"Western States Milling, Inc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Group Areas - Maximum Capacity - Price - Covered Seating\", \"vi\": \"Khu vực nhóm - Sức chứa tối đa - Giá - Chỗ ngồi có mái che\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Home Run Pavilion - 60 people - $17 per person - Yes\", \"vi\": \"Home Run Pavilion - 60 người - 17 đô la mỗi người - Có\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"First Base Dugout Den - 50 people - $19 per person - No\", \"vi\": \"First Base Dugout Den - 50 người - 19 đô la mỗi người - Không\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"North Side Party Deck - 60 people - $25 per person - No\", \"vi\": \"North Side Party Deck - 60 người - 25 đô la mỗi người - Không\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Deluxe Suites - 50 people - $30 per person - Yes\", \"vi\": \"Deluxe Suites - 50 người - 30 đô la mỗi người - Có\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"http://www.billingtonbuffaloes.com/grouptickets\", \"vi\": \"http://www.billingtonbuffaloes.com/grouptickets\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Group Ticket Policies\", \"vi\": \"Chính sách vé theo nhóm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Each group member in the Home Run Pavilion, First Base Dugout Den, and North Side Party Deck areas will receive a hot dog, chips, and a soda.\", \"vi\": \"Mỗi thành viên trong nhóm ở các khu vực Home Run Pavilion, First Base Dugout Den và North Side Party Deck sẽ nhận được một bánh mì xúc xích (hot dog), khoai tây chiên và một chai nước ngọt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"The Deluxe Suites include an all-you-can-eat buffet for each guest.\", \"vi\": \"Khu Deluxe Suites bao gồm tiệc tự chọn (buffet) ăn thỏa thích cho mỗi khách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Each group will receive a special visit from the mascot, Bobby Buffalo.\", \"vi\": \"Mỗi nhóm sẽ nhận được một chuyến thăm đặc biệt từ linh vật, Bobby Buffalo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Groups will be welcomed to the stadium over the announcement system.\", \"vi\": \"Các nhóm sẽ được chào đón tại sân vận động qua hệ thống phát thanh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Everyone in the group will receive 10% off team merchandise (on game day only).\", \"vi\": \"Mọi người trong nhóm sẽ được giảm giá 10% các mặt hàng lưu niệm của đội (chỉ trong ngày thi đấu).\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"A 25% deposit is required when booking.\", \"vi\": \"Khoản đặt cọc 25% là bắt buộc khi đặt vé.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"The remaining balance is due no later than two weeks in advance of the date booked.\", \"vi\": \"Số dư còn lại phải được thanh toán chậm nhất là hai tuần trước ngày đã đặt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Tickets will be mailed when the balance is paid.\", \"vi\": \"Vé sẽ được gửi qua bưu điện khi số dư được thanh toán.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Please call the box office at (406) 555-0192 with any questions.\", \"vi\": \"Vui lòng gọi cho phòng bán vé theo số (406) 555-0192 nếu có bất kỳ câu hỏi nào.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '18eeea42-b155-4647-a324-4f5819060804';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Confirmation #: 9035768\", \"vi\": \"Mã xác nhận: 9035768\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Date: Saturday, June 25\", \"vi\": \"Ngày: Thứ Bảy, ngày 25 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Time: 7 P.M.\", \"vi\": \"Thời gian: 7 giờ tối\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Event: Monterrey Medallions at Mayville Dodgers\", \"vi\": \"Sự kiện: Monterrey Medallions đấu với Mayville Dodgers\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Venue: Alonso Reyes Stadium\", \"vi\": \"Địa điểm: Sân vận động Alonso Reyes\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Order: 1 ticket; bleachers – uncovered; regular season baseball\", \"vi\": \"Đơn hàng: 1 vé; khán đài ngoài trời – không có mái che; bóng chày mùa giải chính thức\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Total: $25 (price includes a $3 building fee)\", \"vi\": \"Tổng cộng: $25 (giá đã bao gồm phí cơ sở vật chất $3)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Notes: Participate in the burger and hot dog buffet for $15 on-site.\\nFor corporate ticket purchases, contact service@stubmaster.com.\", \"vi\": \"Ghi chú: Tham gia tiệc buffet bánh mì kẹp thịt và xúc xích với giá $15 tại chỗ.\\nĐối với việc mua vé doanh nghiệp, hãy liên hệ service@stubmaster.com.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Stub Master—Your Ticket Source for Concerts, Sports, and Theater\", \"vi\": \"Stub Master—Nguồn cung cấp vé cho các buổi hòa nhạc, thể thao và kịch nghệ của bạn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Hello, Mr. Sato,\", \"vi\": \"Xin chào ông Sato,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Thanks for your purchase!\", \"vi\": \"Cảm ơn quý khách đã mua hàng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Your mobile ticket is ready and available in the Stub Master account you created online.\", \"vi\": \"Vé điện tử trên thiết bị di động của bạn đã sẵn sàng và có trong tài khoản Stub Master mà bạn đã tạo trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"All Stub Master tickets contain a unique barcode and may not be printed, copied, or shared.\", \"vi\": \"Tất cả vé của Stub Master đều chứa mã vạch duy nhất và không được phép in ra, sao chép hoặc chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please use the Stub Master app on your phone to access your ticket so that it can be scanned electronically for entry to the event.\", \"vi\": \"Vui lòng sử dụng ứng dụng Stub Master trên điện thoại của bạn để truy cập vé nhằm mục đích quét điện tử khi vào cổng sự kiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '1951e9a1-3b92-47b6-82e9-a2e41fbd66cc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ervin Porter (10:04 A.M.)\", \"vi\": \"Ervin Porter (10:04 Sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hello, Mindy.\", \"vi\": \"Xin chào Mindy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I\'m preparing the paperwork for tomorrow\'s open house at 431 Oakdale Lane.\", \"vi\": \"Tôi đang chuẩn bị giấy tờ cho buổi tham quan nhà mẫu vào ngày mai tại số 431 Oakdale Lane.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Is there anything else I need to prepare?\", \"vi\": \"Còn điều gì khác tôi cần chuẩn bị nữa không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Mindy Warner (10:06 A.M.)\", \"vi\": \"Mindy Warner (10:06 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Could you buy the pastries we want to provide to potential buyers?\", \"vi\": \"Bạn có thể mua bánh ngọt mà chúng ta muốn đãi những người mua tiềm năng được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I\'ve already bought some bottles of water, but I won\'t have time to stop by the bakery tomorrow.\", \"vi\": \"Tôi đã mua sẵn một vài chai nước rồi, nhưng ngày mai tôi sẽ không có thời gian ghé qua tiệm bánh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Ervin Porter (10:08 A.M.)\", \"vi\": \"Ervin Porter (10:08 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Consider it done.\", \"vi\": \"Cứ để đó cho tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Mindy Warner (10:09 A.M.)\", \"vi\": \"Mindy Warner (10:09 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Thanks! See you tomorrow.\", \"vi\": \"Cảm ơn nhé! Hẹn gặp lại bạn vào ngày mai.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '198a3041-2e40-451d-8605-64f116db5f49';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Jamaica National Tourist Organization Offers Free Cultural Passes\", \"vi\": \"Tổ chức Du lịch Quốc gia Jamaica Cung cấp Thẻ Văn hóa Miễn phí\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Jamaica National Tourist Organization (JAMTO) announces an exciting new program that provides free entry to a variety of cultural attractions.\", \"vi\": \"Tổ chức Du lịch Quốc gia Jamaica (JAMTO) thông báo một chương trình mới thú vị cung cấp quyền vào cửa miễn phí cho nhiều điểm tham quan văn hóa khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The program is sponsored by the JAMTO ______[143] the hotels and businesses listed on the back of this flyer.\", \"vi\": \"Chương trình được tài trợ bởi JAMTO ______[143] các khách sạn và doanh nghiệp được liệt kê ở mặt sau của tờ rơi này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [143]}, {\"en\": \"Together we ______[144] you to take advantage of some of the finest cultural and educational experiences that Jamaica has to offer.\", \"vi\": \"Cùng nhau, chúng tôi ______[144] bạn tận dụng một số trải nghiệm văn hóa và giáo dục tốt nhất mà Jamaica mang lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [144]}, {\"en\": \"______[145] attractions include the Caribbean National Gardens, Montego Bay Potters Gallery, Jamaican Music Experience, and many others.\", \"vi\": \"______[145] các điểm tham quan bao gồm Vườn Quốc gia Caribbean, Phòng trưng bày Gốm sứ Montego Bay, Trải nghiệm Âm nhạc Jamaica và nhiều nơi khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [145]}, {\"en\": \"To obtain your pass, visit our Web site at www.jamto.org/freepass or stop by any JAMTO office.\", \"vi\": \"Để nhận thẻ của bạn, hãy truy cập trang web của chúng tôi tại www.jamto.org/freepass hoặc ghé qua bất kỳ văn phòng nào của JAMTO.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"One pass is valid for up to five people.\", \"vi\": \"Một thẻ có giá trị cho tối đa năm người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"______[146].\", \"vi\": \"______[146].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [146]}]' WHERE `id` = '198dfb8e-e76b-4d6e-b2b1-6c3fbb527e6a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"FOR IMMEDIATE RELEASE\", \"vi\": \"THÔNG CÁO BÁO CHÍ PHÁT HÀNH NGAY\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Contact: Nadia Khumalo, nadia_khumalo@gulfbrookcreations.co.za\", \"vi\": \"Liên hệ: Nadia Khumalo, nadia_khumalo@gulfbrookcreations.co.za\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"CAPE TOWN (20 August)—Gulfbrook Creations today announced the appointment of Ms. Candace Masondo as the company’s chief design officer (CDO), effective 1 September.\", \"vi\": \"CAPE TOWN (Ngày 20 tháng 8)—Gulfbrook Creations hôm nay đã công bố việc bổ nhiệm bà Candace Masondo làm giám đốc thiết kế (CDO) của công ty, có hiệu lực từ ngày 1 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Most recently, Ms. Masondo headed the materials development division at Deavora Dynamix, based in Durban.\", \"vi\": \"Gần đây nhất, bà Masondo là người đứng đầu bộ phận phát triển vật liệu tại Deavora Dynamix, có trụ sở tại Durban.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"She was the driving force behind that company’s mission to develop accessibility products to enhance independent living in South Africa’s domestic market.\", \"vi\": \"Bà là động lực đằng sau sứ mệnh của công ty đó nhằm phát triển các sản phẩm dễ tiếp cận nhằm nâng cao cuộc sống tự lập tại thị trường nội địa Nam Phi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Mr. Jonathan Ngobeni, Gulfbrook’s president, acknowledges Ms. Masondo’s skills and resourcefulness.\", \"vi\": \"Ông Jonathan Ngobeni, chủ tịch của Gulfbrook, công nhận các kỹ năng và sự tháo vát của bà Masondo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"“In her three-decades-long design career, Ms. Masondo has designed numerous products that reflect inclusiveness and self-sufficiency.\", \"vi\": \"\\\"Trong sự nghiệp thiết kế kéo dài ba thập kỷ của mình, bà Masondo đã thiết kế nhiều sản phẩm phản ánh tính hòa nhập và sự tự lực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Throughout those years, she has emphasized and demonstrated the importance of collaboration between engineers, designers, and consumers.\", \"vi\": \"Trong suốt những năm đó, bà đã nhấn mạnh và chứng minh tầm quan trọng của việc cộng tác giữa các kỹ sư, nhà thiết kế và người tiêu dùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"She has won several prestigious awards for her work.\", \"vi\": \"Bà đã giành được một số giải thưởng uy tín cho công việc của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Her achievements demonstrate her commitment to colleagues and product users.\", \"vi\": \"Những thành tựu của bà thể hiện cam kết của bà đối với các đồng nghiệp và người dùng sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We are excited that she will be joining our team.”\", \"vi\": \"Chúng tôi rất vui mừng khi bà sẽ gia nhập đội ngũ của chúng tôi.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"“It is a tremendous honour and privilege to be appointed Gulfbrook’s CDO,” Ms. Masondo said.\", \"vi\": \"\\\"Thật là một vinh dự và đặc quyền lớn lao khi được bổ nhiệm làm CDO của Gulfbrook,\\\" bà Masondo cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"“I will do my best to advance the company’s mission and strengthen its industry presence.”\", \"vi\": \"\\\"Tôi sẽ làm hết sức mình để thúc đẩy sứ mệnh của công ty và củng cố sự hiện diện của công ty trong ngành.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Gulfbrook Creations is headquartered in Johannesburg.\", \"vi\": \"Gulfbrook Creations có trụ sở chính tại Johannesburg.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"For 45 years, the company has been manufacturing equipment that facilitates independent living, including ergonomic furniture, audio- and visual-enhancement devices, and motorized mobility aids.\", \"vi\": \"Trong 45 năm qua, công ty đã sản xuất thiết bị hỗ trợ cuộc sống tự lập, bao gồm đồ nội thất công thái học, thiết bị tăng cường âm thanh và hình ảnh, cùng các thiết bị hỗ trợ di chuyển có động cơ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Its products are marketed mainly in Africa.\", \"vi\": \"Các sản phẩm của công ty được tiếp thị chủ yếu ở Châu Phi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '19d34737-f191-423f-946d-1a3244e36bb3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Trail Ride Associate Needed\", \"vi\": \"Cần tuyển Nhân viên Hỗ trợ Cưỡi ngựa Thám hiểm\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Morris Falls Guest Ranch is seeking a horseback riding enthusiast to assist with our popular trail ride program for guests.\", \"vi\": \"Morris Falls Guest Ranch đang tìm kiếm một người đam mê cưỡi ngựa để hỗ trợ chương trình cưỡi ngựa thám hiểm phổ biến dành cho khách của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Duties of this full-time position include teaching guests how to prepare horses for rides, leading small groups of riders along trails on and near the ranch, and handling general horse-care tasks in our barn.\", \"vi\": \"Nhiệm vụ của vị trí toàn thời gian này bao gồm hướng dẫn khách cách chuẩn bị cho ngựa đi cưỡi, dẫn dắt các nhóm người cưỡi ngựa nhỏ dọc theo các con đường mòn trong và gần trang trại, và xử lý các công việc chăm sóc ngựa chung trong chuồng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Applicants must be able to demonstrate high-level horseback riding skills.\", \"vi\": \"Ứng viên phải có khả năng thể hiện kỹ năng cưỡi ngựa cấp độ cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Other qualifications include having done at least six months of paid or volunteer work in a horse barn and possession of a cheerful, friendly personality.\", \"vi\": \"Các tiêu chuẩn khác bao gồm việc đã có ít nhất sáu tháng làm việc có lương hoặc tình nguyện trong chuồng ngựa và sở hữu một tính cách vui vẻ, thân thiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Weekend availability is a must, and the successful candidate should expect to be scheduled for at least one weekend shift per week.\", \"vi\": \"Khả năng làm việc vào cuối tuần là bắt buộc, và ứng viên trúng tuyển nên chuẩn bị tinh thần được xếp lịch làm việc ít nhất một ca cuối tuần mỗi tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To apply, send an e-mail entitled \\\"Trail Ride Associate Application – (your name)\\\" to contact@morrisfalls.com with your résumé and a short cover letter attached.\", \"vi\": \"Để ứng tuyển, hãy gửi một email có tiêu đề \\\"Trail Ride Associate Application – (tên của bạn)\\\" đến địa chỉ contact@morrisfalls.com kèm theo sơ yếu lý lịch (résumé) và một thư xin việc ngắn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"For details and photographs of our horse barn and horseback-riding trails, visit www.morrisfalls.com/riding.\", \"vi\": \"Để biết chi tiết và xem hình ảnh về chuồng ngựa và các tuyến đường mòn cưỡi ngựa của chúng tôi, hãy truy cập www.morrisfalls.com/riding.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '1a039065-9f4d-4caf-9aa0-749f29c0a345';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Darius Wilkins (11:09 A.M.)\", \"vi\": \"Darius Wilkins (11:09 Sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Ms. Clarke.\", \"vi\": \"Xin chào cô Clarke.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This is Darius from Roto Bicycle.\", \"vi\": \"Tôi là Darius từ Cửa hàng Xe đạp Roto.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I promised to check with you before servicing your bicycle.\", \"vi\": \"Tôi đã hứa sẽ hỏi ý kiến cô trước khi bảo dưỡng xe đạp của cô.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Lauren Clarke (11:14 A.M.)\", \"vi\": \"Lauren Clarke (11:14 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thanks. So, what do you think?\", \"vi\": \"Cảm ơn. Vậy anh nghĩ sao?\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Darius Wilkins (11:15 A.M.)\", \"vi\": \"Darius Wilkins (11:15 Sáng)\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In addition to the regular maintenance service, I suggest a drivetrain cleaning and new brake mechanisms.\", \"vi\": \"Ngoài dịch vụ bảo dưỡng thông thường, tôi đề xuất vệ sinh hệ thống truyền động và thay mới cơ cấu phanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Lauren Clarke (11:16 A.M.)\", \"vi\": \"Lauren Clarke (11:16 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"What does that come to?\", \"vi\": \"Tổng chi phí là bao nhiêu?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Darius Wilkins (11:18 A.M.)\", \"vi\": \"Darius Wilkins (11:18 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"An extensive maintenance service, which includes the same gear and brake adjustments as a regular maintenance service, plus the drivetrain cleaning, is $140.\", \"vi\": \"Dịch vụ bảo dưỡng toàn diện, bao gồm việc điều chỉnh bộ số và phanh tương tự như dịch vụ bảo dưỡng thông thường, cộng với việc vệ sinh hệ thống truyền động, có giá 140 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Add $70 for two new brake mechanisms and pads and another $30 for labor charges.\", \"vi\": \"Thêm 70 đô la cho hai cơ cấu và má phanh mới và thêm 30 đô la tiền công.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"So it should come to around $240 altogether.\", \"vi\": \"Vì vậy tổng cộng sẽ khoảng 240 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Shall I move forward?\", \"vi\": \"Tôi có nên tiến hành không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Lauren Clarke (11:21 A.M.)\", \"vi\": \"Lauren Clarke (11:21 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Wow!\", \"vi\": \"Ôi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"That much?\", \"vi\": \"Nhiều vậy sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Darius Wilkins (11:22 A.M.)\", \"vi\": \"Darius Wilkins (11:22 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Especially with that major bicycle race you have ahead of you.\", \"vi\": \"Đặc biệt là với cuộc đua xe đạp lớn mà cô sắp tham gia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Lauren Clarke (11:24 A.M.)\", \"vi\": \"Lauren Clarke (11:24 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I know.\", \"vi\": \"Tôi biết chứ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I guess we have to do it.\", \"vi\": \"Tôi đoán chúng ta phải làm thôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Please let me know when it\'s ready.\", \"vi\": \"Xin vui lòng cho tôi biết khi nào xe làm xong nhé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '1a198db3-a1d3-4f89-8b02-0348f1948ec7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MEMO\", \"vi\": \"THÔNG BÁO NỘI BỘ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All Staff\", \"vi\": \"Đến: Toàn thể nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Amaya Sodhi\", \"vi\": \"Từ: Amaya Sodhi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Online Portal\", \"vi\": \"Chủ đề: Cổng thông tin trực tuyến\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Date: 22 August\", \"vi\": \"Ngày: 22 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The online portal is now up and running.\", \"vi\": \"Cổng thông tin trực tuyến hiện đã chính thức hoạt động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To use it, patients must first obtain an activation number from a staff member here.\", \"vi\": \"Để sử dụng, bệnh nhân trước tiên phải lấy mã kích hoạt từ một nhân viên tại đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Patients will then be able to register to access their records, get lab results, and book appointments.\", \"vi\": \"Sau đó, bệnh nhân sẽ có thể đăng ký để truy cập hồ sơ bệnh án của họ, nhận kết quả xét nghiệm và đặt lịch hẹn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We had also planned to launch a payment option within the portal.\", \"vi\": \"Chúng tôi cũng từng lên kế hoạch ra mắt tính năng thanh toán trong cổng thông tin này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"However, the Web developers are still dealing with issues with the billing system.\", \"vi\": \"Tuy nhiên, các nhà phát triển web vẫn đang giải quyết các sự cố với hệ thống thanh toán.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"As a result, that part of the system will be implemented at a later time.\", \"vi\": \"Do đó, phần đó của hệ thống sẽ được triển khai vào một thời điểm sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It will take some time for all of us to learn how to work with the portal.\", \"vi\": \"Sẽ mất một thời gian để tất cả chúng ta làm quen với cách làm việc với cổng thông tin này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"If you have any questions, please contact Marie at extension 244.\", \"vi\": \"Nếu bạn có bất kỳ câu hỏi nào, vui lòng liên hệ với Marie theo số máy lẻ 244.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '1a410946-565d-4e19-95db-04114c093861';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"8 February\", \"vi\": \"Ngày 8 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Ms. Mala Chelvi\", \"vi\": \"Bà Mala Chelvi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"60 Jalan Tun Razak\", \"vi\": \"60 Jalan Tun Razak\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"54200 Kuala Lumpur\", \"vi\": \"54200 Kuala Lumpur\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Chelvi,\", \"vi\": \"Bà Chelvi kính mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We are delighted to inform you that you have been nominated as a finalist for the Small Business Challenge competition this year.\", \"vi\": \"Chúng tôi rất vui mừng thông báo rằng bà đã được đề cử là một trong những ứng cử viên lọt vào vòng chung kết của cuộc thi Thử thách Doanh nghiệp Nhỏ năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Now in its fifth year, this competition is designed to highlight innovative products and services launched by young entrepreneurs.\", \"vi\": \"Đang bước sang năm thứ năm, cuộc thi này được thiết kế nhằm tôn vinh các sản phẩm và dịch vụ đổi mới do các doanh nhân trẻ khởi xướng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The Web application that you developed, which provides a means of matching charitable organizations with volunteers, earned one of the top scores from our panel of judges.\", \"vi\": \"Ứng dụng web do bà phát triển, cung cấp giải pháp kết nối các tổ chức từ thiện với các tình nguyện viên, đã giành được một trong số điểm cao nhất từ ban giám khảo của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In the next round of the challenge, you will participate in a live presentation about your product before a panel of expert judges.\", \"vi\": \"Trong vòng tiếp theo của cuộc thi, bà sẽ tham gia một bài thuyết trình trực tiếp về sản phẩm của mình trước hội đồng giám khảo chuyên môn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The three people with the best presentations will receive one-time grants of MYR 10,000 each to invest in their businesses.\", \"vi\": \"Ba cá nhân có bài thuyết trình xuất sắc nhất sẽ nhận được khoản tài trợ một lần trị giá 10.000 MYR mỗi người để đầu tư vào doanh nghiệp của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Please go to sbc.org/competition and submit an outline of your presentation, a brief video that clearly illustrates the use of your application, and a passport-sized photograph of yourself.\", \"vi\": \"Vui lòng truy cập trang web sbc.org/competition và nộp một dàn ý bài thuyết trình, một đoạn video ngắn minh họa rõ ràng cách sử dụng ứng dụng của bà, và một bức ảnh cỡ hộ chiếu của chính bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You will also need to sign a consent form allowing us to use your name and photo, if needed, in promotional materials on our Web site.\", \"vi\": \"Bà cũng sẽ cần ký vào một mẫu đơn đồng thuận cho phép chúng tôi sử dụng tên và hình ảnh của bà, nếu cần thiết, trong các tài liệu quảng cáo trên trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The deadline for submission of these materials is 10 March.\", \"vi\": \"Hạn chót để nộp các tài liệu này là ngày 10 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Felix Pang\", \"vi\": \"Felix Pang\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Felix Pang\", \"vi\": \"Felix Pang\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Chairperson, Small Business Challenge Committee\", \"vi\": \"Chủ tịch Ủy ban Thử thách Doanh nghiệp Nhỏ\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '1a678330-5265-4592-ae5c-f185bd0785ca';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MEMO\", \"vi\": \"THÔNG BÁO\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Swansea Spotlight Theatre staff\", \"vi\": \"Đến: Nhân viên Nhà hát Swansea Spotlight\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Rhian Griffud, Chief Executive\", \"vi\": \"Từ: Rhian Griffud, Giám đốc điều hành\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 7 September\", \"vi\": \"Ngày: 7 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: What\'s happening\", \"vi\": \"Chủ đề: Những cập nhật sắp tới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Staff:\", \"vi\": \"Kính gửi toàn thể nhân viên,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am thrilled about the imminent reopening of our theatre, and I hope you are too.\", \"vi\": \"Tôi vô cùng phấn khởi trước việc nhà hát của chúng ta sắp mở cửa trở lại, và tôi hy vọng các bạn cũng vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It has been a long process, and audiences will undoubtedly appreciate all the renovations, including the newly upholstered seats and the updated heating and air-conditioning system.\", \"vi\": \"Đây là một quá trình dài, và khán giả chắc chắn sẽ đánh giá cao tất cả các hạng mục cải tạo, bao gồm những chiếc ghế được bọc đệm mới và hệ thống sưởi cũng như điều hòa không khí đã được nâng cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I believe that all of us who work in the theatre will enjoy the changes as well.\", \"vi\": \"Tôi tin rằng tất cả chúng ta, những người làm việc tại nhà hát, cũng sẽ tận hưởng những thay đổi này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I know you must be eager to rehearse in the newly refurbished building next week.\", \"vi\": \"Tôi biết các bạn hẳn rất háo hức được tập luyện trong tòa nhà mới được tân trang lại vào tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"One of the more visible updates to the space is the Swansea Spotlight Bistro, a new restaurant with a large seating area that replaces our previous concession stand.\", \"vi\": \"Một trong những thay đổi dễ nhận thấy nhất đối với không gian này là Quán ăn nhanh Swansea Spotlight, một nhà hàng mới với khu vực chỗ ngồi rộng lớn thay thế cho quầy giải khát trước đây của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The bistro faces the street and will be open to the public even when no performances are scheduled.\", \"vi\": \"Quán ăn này hướng ra phố và sẽ mở cửa phục vụ công chúng ngay cả khi không có lịch biểu diễn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The menu will feature a wide selection of beverages, snacks, and meals, and it will change with the seasons to highlight locally available products.\", \"vi\": \"Thực đơn sẽ bao gồm nhiều loại đồ uống, đồ ăn nhẹ và bữa ăn phong phú, đồng thời sẽ thay đổi theo mùa để làm nổi bật các sản phẩm có sẵn tại địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"On 2 October, we will celebrate the theatre\'s grand reopening with a one-night musical showcase starring some of the best actors and singers in Wales.\", \"vi\": \"Vào ngày 2 tháng 10, chúng ta sẽ kỷ niệm lễ khai trương lại của nhà hát bằng một buổi biểu diễn ca nhạc đặc biệt kéo dài một đêm với sự góp mặt của một số diễn viên và ca sĩ xuất sắc nhất xứ Wales.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"One week later, we will begin the run of Blake\'s River.\", \"vi\": \"Một tuần sau, chúng ta sẽ bắt đầu công chiếu vở kịch Blake\'s River.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I appreciate all your hard work and patience as we start this new chapter in the history of Swansea Spotlight Theatre, and I look forward to our exciting future together.\", \"vi\": \"Tôi đánh giá cao mọi sự chăm chỉ và kiên nhẫn của các bạn khi chúng ta bước sang chương mới này trong lịch sử của Nhà hát Swansea Spotlight, và tôi rất mong chờ một tương lai tươi sáng cùng nhau của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '1a6ecc59-a6a0-4f0e-93ad-2a8fc5e7aeac';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"(October 23)—Law firm Malley Turnbull Partners is proud to announce that Soo-Yeon Ko has been promoted to the rank of senior partner.\", \"vi\": \"(Ngày 23 tháng 10)—Công ty luật Malley Turnbull Partners tự hào thông báo rằng Soo-Yeon Ko đã được thăng chức lên cấp bậc luật sư cấp cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"She ______[143] managing partner Gerald Malley and four other senior partners as a partial owner of the firm.\", \"vi\": \"Cô ấy ______[143] cùng với đối tác quản lý Gerald Malley và bốn đối tác cấp cao khác với tư cách là một chủ sở hữu một phần của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [143]}, {\"en\": \"\\\"This recognition is well deserved,\\\" said Mr. Malley.\", \"vi\": \"\\\"Sự công nhận này hoàn toàn xứng đáng,\\\" ông Malley cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"\\\"Ms. Ko has made ______[144] contributions to our success over the past several years.\\\"\", \"vi\": \"\\\"Cô Ko đã có những đóng góp ______[144] cho thành công của chúng tôi trong vài năm qua.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [144]}, {\"en\": \"Malley Turnbull Partners hired Ms. Ko five years ago as a senior associate concentrating on environmental law.\", \"vi\": \"Công ty luật Malley Turnbull Partners đã tuyển dụng cô Ko năm năm trước với tư cách là một luật sư liên kết cao cấp chuyên về luật môi trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[145], the firm has won some important cases in that area.\", \"vi\": \"______[145], công ty đã thắng một số vụ kiện quan trọng trong lĩnh vực đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [145]}, {\"en\": \"\\\"Ms. Ko possesses not only a very sharp legal mind but also an inspiring dedication to helping our junior lawyers grow professionally,\\\" said Mr. Malley.\", \"vi\": \"\\\"Cô Ko không chỉ sở hữu tư duy pháp lý sắc bén mà còn có sự cống hiến đầy cảm hứng trong việc giúp đỡ các luật sư cấp dưới của chúng ta phát triển nghề nghiệp,\\\" ông Malley nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"\\\"______[146].\\\"\", \"vi\": \"\\\"______[146].\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [146]}]' WHERE `id` = '1aa14acc-c0c5-4fb3-b708-3d603e91256f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Tanyalog Industries Policy 4-02\", \"vi\": \"Chính sách số 4-02 của Tanyalog Industries\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The cafeteria (3rd floor) is open to all employees and guests from 8:00 A.M. to 2:30 P.M. Food from the cafeteria may be eaten there or brought on trays to the following conference rooms: Chestnut Room (1st floor), Burnside Room (2nd floor), Smith Room (3rd floor), and Danville Room (4th floor).\", \"vi\": \"Căng-tin (tầng 3) mở cửa đón tiếp tất cả nhân viên và khách từ 8:00 sáng đến 2:30 chiều. Thức ăn từ căng-tin có thể được dùng tại chỗ hoặc mang bằng khay đến các phòng họp sau đây: Phòng Chestnut (tầng 1), Phòng Burnside (tầng 2), Phòng Smith (tầng 3) và Phòng Danville (tầng 4).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Using the rooms at lunchtime does not require a reservation.\", \"vi\": \"Việc sử dụng các phòng vào giờ ăn trưa không cần phải đặt trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"However, please do not enter the room if it is already occupied by staff members for a business meeting.\", \"vi\": \"Tuy nhiên, vui lòng không vào phòng nếu phòng đã có nhân viên sử dụng để họp công việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The room schedule is displayed on a digital panel by the door of each conference room.\", \"vi\": \"Lịch trình sử dụng phòng được hiển thị trên bảng điện tử cạnh cửa của mỗi phòng họp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"All food items and trash must be removed from the conference room after use.\", \"vi\": \"Tất cả đồ ăn và rác thải phải được dọn khỏi phòng họp sau khi sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Bins are located directly outside each of the conference rooms.\", \"vi\": \"Thùng rác được đặt ngay bên ngoài mỗi phòng họp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"No food or drink is allowed in the Essex Room (3rd floor) or the Martinelli Room (4th floor).\", \"vi\": \"Không được phép mang đồ ăn hoặc thức uống vào Phòng Essex (tầng 3) hoặc Phòng Martinelli (tầng 4).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"From: Eugene Lasich\", \"vi\": \"Từ: Eugene Lasich\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To: All Expansion Committee Members\", \"vi\": \"Đến: Tất cả thành viên Ủy ban Mở rộng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Subject: Tanyalog Industries Expansion Meeting\", \"vi\": \"Chủ đề: Cuộc họp về việc mở rộng của Tanyalog Industries\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Date: September 10\", \"vi\": \"Ngày: 10 tháng 9\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Committee Members,\", \"vi\": \"Gửi các thành viên Ủy ban,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please join me for the first meeting of the Expansion Committee on Monday, September 17.\", \"vi\": \"Vui lòng tham gia cùng tôi trong buổi họp đầu tiên của Ủy ban Mở rộng vào thứ Hai, ngày 17 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"All attendees should arrive at the Martinelli Room at 10:00 A.M. Then, at 12:00 P.M., we will break for lunch and you can visit the cafeteria to receive a complimentary meal.\", \"vi\": \"Tất cả những người tham dự có mặt tại Phòng Martinelli lúc 10:00 sáng. Sau đó, vào lúc 12:00 trưa, chúng ta sẽ nghỉ trưa và quý vị có thể đến căng-tin để nhận một suất ăn miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Just show your visitor\'s badge at Window 4.\", \"vi\": \"Chỉ cần xuất trình thẻ ra vào của khách tại Ô số 4.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"All committee members should bring their trays to the conference room on the third floor right beside the cafeteria, where we will continue our meeting from 12:45 P.M. until 4:00 P.M.\", \"vi\": \"Tất cả các thành viên ủy ban nên mang khay đựng thức ăn của mình đến phòng họp ở tầng ba ngay bên cạnh căng-tin, nơi chúng ta sẽ tiếp tục cuộc họp từ 12:45 trưa đến 4:00 chiều.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Thank you. We look forward to your input at the meeting.\", \"vi\": \"Cảm ơn quý vị. Chúng tôi rất mong nhận được những đóng góp của quý vị tại cuộc họp.\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Eugene Lasich, Expansion Committee Chair\", \"vi\": \"Eugene Lasich, Chủ tịch Ủy ban Mở rộng\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Tanyalog Industries\", \"vi\": \"Tanyalog Industries\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '1abbd029-b2b5-46b9-8240-90224cb2f29f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Klein Print Shop Staff\", \"vi\": \"Đến: Nhân viên Cửa hàng In ấn Klein\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Leslie Klein\", \"vi\": \"Từ: Leslie Klein\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Document shredding\", \"vi\": \"Chủ đề: Tiêu hủy tài liệu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: January 18\", \"vi\": \"Ngày: 18 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Staff:\", \"vi\": \"Kính gửi toàn thể nhân viên,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I\'m proud to announce that Neil and I have obtained a professional ______[135] in secure document destruction from the National Data Management Association.\", \"vi\": \"Tôi tự hào thông báo rằng Neil và tôi đã đạt được ______[135] chuyên nghiệp về tiêu hủy tài liệu bảo mật từ Hiệp hội Quản lý Dữ liệu Quốc gia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [135]}, {\"en\": \"We\'re ______[136] authorized to shred documents classified by the government as containing sensitive information.\", \"vi\": \"Chúng tôi đã được ______[136] ủy quyền để tiêu hủy các tài liệu được chính phủ phân loại là chứa thông tin nhạy cảm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [136]}, {\"en\": \"In the past, you were told to refer government customers ______[137] other businesses for this service.\", \"vi\": \"Trước đây, các bạn đã được yêu cầu giới thiệu khách hàng là cơ quan chính phủ ______[137] các doanh nghiệp khác để sử dụng dịch vụ này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [137]}, {\"en\": \"______[138].\", \"vi\": \"______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [138]}, {\"en\": \"Finally, if we consistently receive high volumes of work, I may consider paying for some of you to receive this qualification as well.\", \"vi\": \"Cuối cùng, nếu chúng ta liên tục nhận được khối lượng công việc lớn, tôi có thể cân nhắc chi trả để một số bạn cũng nhận được chứng chỉ này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Leslie Klein\", \"vi\": \"Leslie Klein\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Owner & Operator\", \"vi\": \"Chủ sở hữu & Giám đốc vận hành\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Klein Print Shop\", \"vi\": \"Cửa hàng In ấn Klein\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '1b2fcc76-e58b-45f6-afc3-790166e9fdf1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"29 August\", \"vi\": \"Ngày 29 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Alvin Mangubat\", \"vi\": \"Alvin Mangubat\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Director of Human Resources\", \"vi\": \"Giám đốc Nhân sự\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Farsten Products, Ltd.\", \"vi\": \"Farsten Products, Ltd.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"549 Castor Boulevard\", \"vi\": \"549 Castor Boulevard\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Winnipeg MB R3E 2S2\", \"vi\": \"Winnipeg MB R3E 2S2\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Mr. Mangubat,\", \"vi\": \"Kính gửi ông Mangubat,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I am writing to apply for the mechanical engineer position advertised on your Web site.\", \"vi\": \"Tôi viết thư này để ứng tuyển vào vị trí kỹ sư cơ khí được đăng tuyển trên trang web của quý công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I think I have much to offer Farsten Products\' design ______[135] as an employee.\", \"vi\": \"Tôi nghĩ rằng tôi có rất nhiều điều để cống hiến cho đội ngũ thiết kế của Farsten Products ______[135] với tư cách là một nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [135]}, {\"en\": \"______[136].\", \"vi\": \"______[136].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [136]}, {\"en\": \"I am currently an engineer at Yount Systems, where I have worked on machine and engine designs for the last six years.\", \"vi\": \"Hiện tại tôi là kỹ sư tại Yount Systems, nơi tôi đã làm việc về thiết kế máy móc và động cơ trong sáu năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"______[137] that, I was employed by Zelenka Industries, where I helped develop efficient methods for recycling scrap steel.\", \"vi\": \"______[137] điều đó, tôi từng làm việc tại Zelenka Industries, nơi tôi đã giúp phát triển các phương pháp hiệu quả để tái chế thép phế liệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [137]}, {\"en\": \"I have enclosed my résumé, which ______[138] more details about my work history and my educational background.\", \"vi\": \"Tôi đã đính kèm sơ yếu lý lịch của mình, tài liệu này ______[138] cung cấp thêm chi tiết về lịch sử làm việc và nền tảng học vấn của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [138]}, {\"en\": \"I look forward to meeting with you to discuss how my skills and experience can benefit Farsten Products.\", \"vi\": \"Tôi rất mong có cơ hội gặp mặt quý ông để thảo luận về cách các kỹ năng và kinh nghiệm của tôi có thể mang lại lợi ích cho Farsten Products.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Gail Paek\", \"vi\": \"Gail Paek\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Encl.\", \"vi\": \"Tài liệu đính kèm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '1b37d472-c1d2-43c6-a216-045ecce82d19';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"About - Certification - Registration - Student Log-in - Contact\", \"vi\": \"Giới thiệu - Chứng chỉ - Đăng ký - Đăng nhập học viên - Liên hệ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"https://forklifttrainingacademy.com/certification\", \"vi\": \"https://forklifttrainingacademy.com/certification\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Forklift Operation Training and Certifications\", \"vi\": \"Đào tạo và cấp chứng chỉ vận hành xe nâng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The Forklift Training Academy’s one-day courses satisfy all requirements for certification in Canada and the United States.\", \"vi\": \"Các khóa học một ngày của Học viện Đào tạo Xe nâng đáp ứng mọi yêu cầu về chứng chỉ tại Canada và Hoa Kỳ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We offer courses for first timers needing initial certification and for experienced operators needing recertification.\", \"vi\": \"Chúng tôi cung cấp các khóa học dành cho người mới bắt đầu cần cấp chứng chỉ lần đầu và cho những người vận hành có kinh nghiệm cần cấp lại chứng chỉ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"A passing score on a final examination is required for certification.\", \"vi\": \"Cần đạt điểm đậu trong bài kiểm tra cuối khóa để được cấp chứng chỉ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Certification is valid for three years.\", \"vi\": \"Chứng chỉ có giá trị trong vòng ba năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We have recently transitioned from in-person to online courses only, available on mobile devices, tablets, or computers.\", \"vi\": \"Gần đây chúng tôi đã chuyển đổi từ hình thức học trực tiếp sang các khóa học hoàn toàn trực tuyến, có sẵn trên thiết bị di động, máy tính bảng hoặc máy tính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Visit our registration page for more information or to sign up.\", \"vi\": \"Hãy truy cập trang đăng ký của chúng tôi để biết thêm thông tin hoặc để đăng ký.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"All reservations must be booked and paid for at least three days in advance of the selected course date.\", \"vi\": \"Tất cả các chỗ phải được đặt và thanh toán ít nhất ba ngày trước ngày khóa học đã chọn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"About - Certification - Registration - Student Log-in - Contact\", \"vi\": \"Giới thiệu - Chứng chỉ - Đăng ký - Đăng nhập học viên - Liên hệ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"https://forklifttrainingacademy.com/registration\", \"vi\": \"https://forklifttrainingacademy.com/registration\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Registration Form\", \"vi\": \"Phiếu đăng ký\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Name: Philippe Durand\", \"vi\": \"Họ tên: Philippe Durand\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"E-mail: philippe.durand@silkmail.com\", \"vi\": \"Email: philippe.durand@silkmail.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Select your preferred course date:\", \"vi\": \"Chọn ngày khóa học ưa thích của bạn:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"• Certification—Instructor: Mr. Harris / April 4, 8:00 A.M.–4:00 P.M. [ ]\", \"vi\": \"• Cấp chứng chỉ—Giảng viên: Ông Harris / Ngày 4 tháng 4, 8:00 sáng–4:00 chiều [ ]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"• Recertification—Instructor: Ms. Gogh / April 7, 8:30 A.M.–2:30 P.M. [ ]\", \"vi\": \"• Cấp lại chứng chỉ—Giảng viên: Bà Gogh / Ngày 7 tháng 4, 8:30 sáng–2:30 chiều [ ]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"• Certification—Instructor: Ms. Baldwin / April 10, 8:00 A.M.–4:00 P.M. [X]\", \"vi\": \"• Cấp chứng chỉ—Giảng viên: Bà Baldwin / Ngày 10 tháng 4, 8:00 sáng–4:00 chiều [X]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"• Recertification—Instructor: Ms. Baldwin / April 14, 8:30 A.M.–2:30 P.M. [ ]\", \"vi\": \"• Cấp lại chứng chỉ—Giảng viên: Bà Baldwin / Ngày 14 tháng 4, 8:30 sáng–2:30 chiều [ ]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"• Certification—Instructor: Mr. Minors / April 21, 8:00 A.M.–4:00 P.M. [ ]\", \"vi\": \"• Cấp chứng chỉ—Giảng viên: Ông Minors / Ngày 21 tháng 4, 8:00 sáng–4:00 chiều [ ]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Review: Forklift Training Classes\", \"vi\": \"Đánh giá: Các lớp đào tạo lái xe nâng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"By Julie Dye\", \"vi\": \"Bởi Julie Dye\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"May 18\", \"vi\": \"Ngày 18 tháng 5\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"★★★★☆\", \"vi\": \"★★★★☆\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I took the forklift training class for recertification for my job at Able Industries last month.\", \"vi\": \"Tôi đã tham gia lớp đào tạo lái xe nâng để cấp lại chứng chỉ cho công việc của mình tại công ty Able Industries vào tháng trước.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I was concerned about taking the course online; however, it covered all the material from the on-site training that I had for my original certification—and more.\", \"vi\": \"Tôi từng lo ngại về việc tham gia khóa học trực tuyến; tuy nhiên, khóa học đã bao trùm toàn bộ tài liệu từ buổi đào tạo trực tiếp mà tôi đã tham gia cho chứng chỉ ban đầu của mình—và hơn thế nữa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"It was also great that I did not have to travel to take the course and that I received my recertification that very same day!\", \"vi\": \"Thật tuyệt vời khi tôi không phải di chuyển để tham gia khóa học và tôi đã nhận được chứng chỉ mới ngay trong ngày hôm đó!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"The trainer, Ms. Gogh, was excellent.\", \"vi\": \"Giảng viên, bà Gogh, rất xuất sắc.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"She answered all my questions and was attuned to the challenges that forklift operators face.\", \"vi\": \"Bà ấy đã giải đáp mọi thắc mắc của tôi và rất thấu hiểu những thử thách mà những người vận hành xe nâng phải đối mặt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"My only recommendation for the Forklift Training Academy is that they offer more variety in course days and times.\", \"vi\": \"Đề xuất duy nhất của tôi dành cho Học viện Đào tạo Xe nâng là họ nên cung cấp sự đa dạng hơn về ngày và giờ học.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = '1b6d03bf-bae5-4fa6-889c-562af6c2ace5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"PROPOSAL\", \"vi\": \"BẢN ĐỀ XUẤT\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Customer Information:\\nGreenway Accounting\\n689 Robinette Drive, Unit 1\\nBankstown, NSW 2200 - Contractor Information:\\nWindham Movers\\n1150 Worthy Street\\nBankstown, NSW 2200\", \"vi\": \"Thông tin khách hàng:\\nGreenway Accounting\\n689 Robinette Drive, Unit 1\\nBankstown, NSW 2200 - Thông tin nhà thầu:\\nWindham Movers\\n1150 Worthy Street\\nBankstown, NSW 2200\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Project:\\nLoading/Unloading of all items in customer\'s office space into/from truck by two-person crew, plus transport of this cargo approximately 5.2 kilometres. Furniture disassembly/assembly service included. Moving boxes and bubble wrap provided, but packing of small items must be done by client in advance.\", \"vi\": \"Dự án:\\nBốc xếp toàn bộ đồ đạc tại văn phòng khách hàng lên/xuống xe tải bởi đội ngũ gồm hai người, cộng với việc vận chuyển số hàng hóa này khoảng 5,2 km. Đã bao gồm dịch vụ tháo lắp đồ đạc. Cung cấp hộp chuyển nhà và màng bọc bong bóng khí, nhưng việc đóng gói các vật dụng nhỏ phải do khách hàng thực hiện trước.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Contractor Proposal:\\nContractor will carry out the above project for the amount of $1,850 plus tax. Customer will pay full amount immediately upon completion of project. Price expires 30 days after proposal submission.\", \"vi\": \"Đề xuất của nhà thầu:\\nNhà thầu sẽ thực hiện dự án trên với số tiền 1.850 đô la cộng với thuế. Khách hàng sẽ thanh toán toàn bộ số tiền ngay sau khi hoàn thành dự án. Giá có hiệu lực trong 30 ngày kể từ khi nộp bản đề xuất.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Acceptance of Proposal\", \"vi\": \"Chấp thuận bản đề xuất\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Contractor Representative: Ah-Young Hahm\\nDate: 13 September\", \"vi\": \"Đại diện nhà thầu: Ah-Young Hahm\\nNgày: 13 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Customer Representative: ___________________________\\nDate: _______________\", \"vi\": \"Đại diện khách hàng: ___________________________\\nNgày: _______________\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"NIELSON RELOCATIONS: PROPOSAL\\n560 Puckett Street\\nYagoona, NSW 2199\", \"vi\": \"NIELSON RELOCATIONS: BẢN ĐỀ XUẤT\\n560 Puckett Street\\nYagoona, NSW 2199\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Proposal for: Greenway Accounting\\n689 Robinette Drive, Unit 1\\nBankstown, NSW 2200\", \"vi\": \"Đề xuất cho: Greenway Accounting\\n689 Robinette Drive, Unit 1\\nBankstown, NSW 2200\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Issued: 15 September\", \"vi\": \"Ngày phát hành: 15 tháng 9\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Valid through: 14 October\", \"vi\": \"Có hiệu lực đến: 14 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Nielson Relocations proposes to move the entire contents of customer\'s current office to 77 Earls Drive, Revesby via truck. Customer must disassemble furniture and complete necessary packing before date of move. Loan of cardboard boxes and protective padding included.\", \"vi\": \"Nielson Relocations đề xuất chuyển toàn bộ đồ đạc trong văn phòng hiện tại của khách hàng đến 77 Earls Drive, Revesby bằng xe tải. Khách hàng phải tháo dỡ đồ đạc và hoàn thành việc đóng gói cần thiết trước ngày chuyển đi. Đã bao gồm việc cho mượn thùng các-tông và đệm bảo vệ.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Cost: $1,490 (tax not included)\\nCustomer must submit deposit of 50% ($745) at acceptance of proposal, with remainder to be paid once move is completed.\", \"vi\": \"Chi phí: 1.490 đô la (chưa bao gồm thuế)\\nKhách hàng phải đặt cọc 50% (745 đô la) khi chấp thuận bản đề xuất, số tiền còn lại sẽ được thanh toán sau khi hoàn tất việc chuyển nhà.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Proposal prepared by: William Bernier\", \"vi\": \"Bản đề xuất được chuẩn bị bởi: William Bernier\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Customer signature: ___________________________\", \"vi\": \"Chữ ký khách hàng: ___________________________\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Date: _______________\", \"vi\": \"Ngày: _______________\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"To: Greenway Accounting staff\", \"vi\": \"Đến: Nhân viên Greenway Accounting\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"From: Rosario Valles, President\", \"vi\": \"Từ: Rosario Valles, Giám đốc điều hành\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Subject: Upcoming move\", \"vi\": \"Chủ đề: Việc chuyển văn phòng sắp tới\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date: 29 September\", \"vi\": \"Ngày: 29 tháng 9\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I have finalized the schedule for the relocation to our new office.\", \"vi\": \"Tôi đã hoàn tất lịch trình chuyển đến văn phòng mới của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Packing materials will be made available on Monday.\", \"vi\": \"Vật liệu đóng gói sẽ được cung cấp vào thứ Hai.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Please have small items packed up by noon on Wednesday.\", \"vi\": \"Vui lòng đóng gói xong các vật dụng nhỏ trước 12 giờ trưa thứ Tư.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"A few employees have volunteered to spend the rest of the day taking apart the desks, filing cabinets, and bookshelves so that everything is ready to be loaded up when the movers arrive.\", \"vi\": \"Một số nhân viên đã tình nguyện dành phần còn lại của ngày để tháo dỡ bàn làm việc, tủ hồ sơ và giá sách để mọi thứ sẵn sàng được bốc lên xe khi đội chuyển nhà đến.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"All other staff may rest that afternoon.\", \"vi\": \"Tất cả nhân viên khác có thể nghỉ ngơi vào chiều hôm đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"However, everyone should plan to work from home on Thursday during the move.\", \"vi\": \"Tuy nhiên, mọi người nên lên kế hoạch làm việc tại nhà vào thứ Năm trong suốt quá trình chuyển nhà.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Finally, please report to the new office on Friday morning to help with unpacking and setup.\", \"vi\": \"Cuối cùng, vui lòng có mặt tại văn phòng mới vào sáng thứ Sáu để hỗ trợ việc dọn đồ ra và sắp xếp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '1c3e61ea-d617-405f-97ec-e469ca69df7e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear staff,\", \"vi\": \"Kính gửi toàn thể nhân viên,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I really appreciate the hard work you’re doing to prepare for our upcoming symposium.\", \"vi\": \"Tôi rất trân trọng sự chăm chỉ mà các bạn đang bỏ ra để chuẩn bị cho hội nghị sắp tới của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I know that it can be a struggle to keep up with the extra workload it involves.\", \"vi\": \"Tôi biết rằng việc theo kịp khối lượng công việc bổ sung đi kèm có thể là một thử thách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"That said, I’d like to remind you that our employee handbook strictly prohibits working more than 40 hours per week without getting approval from a supervisor beforehand.\", \"vi\": \"Mặc dù vậy, tôi muốn nhắc nhở các bạn rằng sổ tay nhân viên của chúng ta nghiêm cấm làm việc quá 40 giờ một tuần mà không có sự chấp thuận trước từ quản lý trực tiếp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We’re legally required to pay you at a higher rate for any overtime hours, and as a nonprofit organization, we don’t have the resources to cover extra expenses in this area.\", \"vi\": \"Chúng ta có nghĩa vụ pháp lý phải trả lương cho các bạn theo mức cao hơn đối với bất kỳ giờ làm thêm nào, và là một tổ chức phi lợi nhuận, chúng ta không có nguồn lực để chi trả các khoản chi phí phát sinh trong lĩnh vực này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"If you’re unable to complete an assignment within your regular hours, you must leave it to your supervisor to decide whether to allow overtime work or to push the deadline back.\", \"vi\": \"Nếu bạn không thể hoàn thành một nhiệm vụ trong giờ làm việc thông thường, bạn phải để quản lý của mình quyết định có cho phép làm thêm giờ hay lùi thời hạn lại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Going forward, failure to follow this policy will be reflected in your performance evaluation.\", \"vi\": \"Từ nay về sau, việc không tuân thủ chính sách này sẽ được phản ánh trong đánh giá hiệu suất làm việc của bạn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Xin cảm ơn.\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Patricia Chilton\", \"vi\": \"Patricia Chilton\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Executive Director\", \"vi\": \"Giám đốc điều hành\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Proactive Network for Women in Engineering\", \"vi\": \"Mạng lưới Chủ động vì Nữ giới trong Ngành Kỹ thuật\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '1c7e3503-3303-407e-a2bc-b9d1835fdbc7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Loffler Mobile Banking\", \"vi\": \"Dịch vụ Ngân hàng Di động Loffler\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"In the coming weeks, Loffler Bank will be making upgrades to its mobile application to provide a more secure and user-friendly experience.\", \"vi\": \"Trong những tuần tới, Ngân hàng Loffler sẽ tiến hành nâng cấp ứng dụng di động của mình nhằm mang lại trải nghiệm an toàn hơn và thân thiện với người dùng hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Customers will now be able to view all their Loffler accounts simultaneously and enjoy ______[143] security through a fingerprint identification scan.\", \"vi\": \"Khách hàng giờ đây sẽ có thể xem tất cả các tài khoản Loffler của mình cùng một lúc và tận hưởng mức độ bảo mật ______[143] thông qua quá trình quét nhận diện vân tay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [143]}, {\"en\": \"______[144], users may now customize their online dashboard to track their expenses and budgets.\", \"vi\": \"______[144], người dùng giờ đây có thể tùy chỉnh bảng điều khiển trực tuyến của họ để theo dõi các khoản chi phí và ngân sách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [144]}, {\"en\": \"Changes can prove to be challenging for individuals, particularly in light of rapid technological advancement.\", \"vi\": \"Sự thay đổi có thể gây ra nhiều thách thức cho các cá nhân, đặc biệt là trong bối cảnh tiến bộ công nghệ diễn ra nhanh chóng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[145].\", \"vi\": \"______[145].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [145]}, {\"en\": \"Therefore, should you ever need assistance ______[146] any of the features of our app, call us at 555-0133 or visit us online at www.lofflerbank.com/faq.\", \"vi\": \"Do đó, nếu quý vị cần hỗ trợ ______[146] bất kỳ tính năng nào của ứng dụng chúng tôi, hãy gọi cho chúng tôi theo số 555-0133 hoặc truy cập trực tuyến tại www.lofflerbank.com/faq.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [146]}]' WHERE `id` = '1c7ef4af-08ae-4cf4-98a1-63284c01f633';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"BLISSFUL HORSE STABLES\", \"vi\": \"TRẠI NGỰA BLISSFUL\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Part-time worker needed to feed, wash, and groom horses.\", \"vi\": \"Cần tuyển nhân viên bán thời gian để cho ngựa ăn, tắm rửa và chải chuốt cho ngựa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Must be able to work a minimum of eight hours a week, including occasional weekend hours.\", \"vi\": \"Phải có khả năng làm việc tối thiểu tám giờ một tuần, bao gồm cả số giờ làm việc vào cuối tuần không thường xuyên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Although training is available, applicants who have experience working with horses are preferred.\", \"vi\": \"Mặc dù có chương trình đào tạo, các ứng viên có kinh nghiệm làm việc với ngựa sẽ được ưu tiên hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"To apply, send an e-mail to Dorothy Lu, dlu@blissfulhorsestables.com.au, and attach your résumé.\", \"vi\": \"Để ứng tuyển, hãy gửi email cho Dorothy Lu tại địa chỉ dlu@blissfulhorsestables.com.au và đính kèm sơ yếu lý lịch của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Blissful Horse Stables is the region’s largest horse-boarding facility.\", \"vi\": \"Trại ngựa Blissful là cơ sở chăm sóc và nuôi giữ ngựa lớn nhất trong vùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It has been owned and operated by one family since 1988.\", \"vi\": \"Nơi đây đã được sở hữu và điều hành bởi một gia đình kể từ năm 1988.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Our business offers both long- and short-term boarding contracts.\", \"vi\": \"Doanh nghiệp của chúng tôi cung cấp cả hợp đồng nuôi giữ ngựa ngắn hạn và dài hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We have state-of-the-art indoor and outdoor exercise rings and a five-acre grazing pasture for our equine friends.\", \"vi\": \"Chúng tôi có các sân tập trong nhà và ngoài trời hiện đại cùng với một bãi cỏ chăn thả rộng năm mẫu Anh dành cho những người bạn ngựa của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"A veterinarian is always on call.\", \"vi\": \"Luôn có bác sĩ thú y túc trực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"From: ota.kyle@opalmail.com.au\", \"vi\": \"Từ: ota.kyle@opalmail.com.au\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: dlu@blissfulhorsestables.com.au\", \"vi\": \"Đến: dlu@blissfulhorsestables.com.au\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Subject: Part-time position\", \"vi\": \"Chủ đề: Vị trí bán thời gian\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: 1 August\", \"vi\": \"Ngày: 1 tháng 8\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 ota.rfg\", \"vi\": \"Tệp đính kèm: 📎 ota.rfg\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dear Ms. Lu,\", \"vi\": \"Kính gửi bà Lu,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"This e-mail is in response to the advertisement that appeared in yesterday\'s edition of the Colby Today.\", \"vi\": \"Email này là để phản hồi lại quảng cáo đã xuất hiện trên số báo ngày hôm qua của tờ Colby Today.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"At this time, I work for Ness Large Animal Clinic as a technician\'s assistant, but only three days a week.\", \"vi\": \"Vào thời điểm này, tôi đang làm việc cho Phòng khám Động vật Lớn Ness với tư cách là trợ lý kỹ thuật viên, nhưng chỉ ba ngày một tuần.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The part-time position you are advertising would enable me to do something I enjoy while increasing my working hours.\", \"vi\": \"Vị trí bán thời gian mà quý công ty đang quảng cáo sẽ giúp tôi có thể làm công việc mình yêu thích đồng thời tăng số giờ làm việc của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I am happy to provide references upon request.\", \"vi\": \"Tôi rất sẵn lòng cung cấp người giới thiệu theo yêu cầu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"All the best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Kyle Ota\", \"vi\": \"Kyle Ota\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '1c96fc0f-0698-4e88-8f22-16573eece429';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Sky-High Roofing\", \"vi\": \"Công ty Lợp mái Sky-High\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dress for safety.\", \"vi\": \"Ăn mặc vì sự an toàn.\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Use personal protective equipment.\", \"vi\": \"Sử dụng thiết bị bảo vệ cá nhân.\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Begin the day right.\", \"vi\": \"Bắt đầu ngày mới một cách đúng đắn.\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Workers doing construction or repair work on roofs face multiple potential hazards.\", \"vi\": \"Công nhân thực hiện công việc xây dựng hoặc sửa chữa trên mái nhà phải đối mặt với nhiều mối nguy hiểm tiềm ẩn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Ladders, skylights, and physical exposure to the natural elements involve risks.\", \"vi\": \"Thang, cửa sổ trần và sự tiếp xúc thể chất với các yếu tố tự nhiên đều tiềm ẩn rủi ro.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Stay safe by using commonsense practices.\", \"vi\": \"Giữ an toàn bằng cách áp dụng các biện pháp thực tế thông thường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Follow these guidelines.\", \"vi\": \"Hãy tuân theo các hướng dẫn sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Wear long-sleeved shirts, even in warm weather, and keep your wrist cuffs buttoned\", \"vi\": \"Mặc áo dài tay, ngay cả trong thời tiết ấm áp, và giữ cho cổ tay áo được cài cúc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Wear long pants without cuffs, as they can snag on roofing material and catch debris\", \"vi\": \"Mặc quần dài không có gấu quần, vì chúng có thể vướng vào vật liệu lợp mái và bám rác vụn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Wear work boots that cover the ankles, and replace boots when the soles show excessive wear\", \"vi\": \"Mang giày bảo hộ che kín cổ chân, và thay giày mới khi đế giày cho thấy dấu hiệu mòn quá mức\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Wear gloves that cover the wrists, making sure there is no gap between the top of the gloves and the bottom of the sleeve cuffs\", \"vi\": \"Mang găng tay che kín cổ tay, đảm bảo không có khoảng trống giữa phần trên của găng tay và phần dưới của cổ tay áo\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Use protective eyewear\", \"vi\": \"Sử dụng thiết bị bảo vệ mắt\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Review the work plan with all members of the team\", \"vi\": \"Xem xét lại kế hoạch công việc với tất cả các thành viên trong nhóm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Check the condition of ladders and all safety equipment\", \"vi\": \"Kiểm tra tình trạng của thang và tất cả các thiết bị an toàn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I confirm that I have reviewed and understood these guidelines.\", \"vi\": \"Tôi xác nhận rằng tôi đã đọc kỹ và hiểu rõ các hướng dẫn này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Signature: __________________ Date: __________________\", \"vi\": \"Chữ ký: __________________ Ngày: __________________\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '1cb41112-dcb1-41b2-bf15-ffd5552ffa31';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Brycen Bodine [1:07 P.M.]\", \"vi\": \"Brycen Bodine [1:07 CH]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Avichai.\", \"vi\": \"Chào Avichai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I finished the upholstery on the sofa and chairs for Ms. Levin.\", \"vi\": \"Tôi đã bọc xong ghế sofa và ghế bành cho cô Levin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"They look great!\", \"vi\": \"Trông chúng tuyệt lắm!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"It’s such a nice fabric.\", \"vi\": \"Đó là một chất liệu vải rất đẹp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Which order should I work on next?\", \"vi\": \"Tôi nên làm đơn hàng nào tiếp theo?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Avichai Rosen [1:14 P.M.]\", \"vi\": \"Avichai Rosen [1:14 CH]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Glad to hear it.\", \"vi\": \"Rất vui khi nghe điều đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I promised the Chens their dining chairs by Saturday.\", \"vi\": \"Tôi đã hứa với gia đình Chen là sẽ giao những chiếc ghế ăn của họ trước thứ Bảy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"By the way, the Metropolitan Design Show on June 14 has been postponed to July 7.\", \"vi\": \"Nhân tiện, Triển lãm Thiết kế Metropolitan vào ngày 14 tháng 6 đã bị hoãn sang ngày 7 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Brycen Bodine [1:19 P.M.]\", \"vi\": \"Brycen Bodine [1:19 CH]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Oh, then I can’t make it.\", \"vi\": \"Ồ, vậy thì tôi không thể tham gia rồi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Avichai Rosen [1:22 P.M.]\", \"vi\": \"Avichai Rosen [1:22 CH]\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"That’s too bad.\", \"vi\": \"Tiếc quá nhỉ.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I’ll need at least two employees to come help.\", \"vi\": \"Tôi sẽ cần ít nhất hai nhân viên đến giúp.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We’ll be showing our office desks and bookshelves.\", \"vi\": \"Chúng ta sẽ trưng bày bàn làm việc văn phòng và giá sách của mình.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Brycen Bodine [1:24 P.M.]\", \"vi\": \"Brycen Bodine [1:24 CH]\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I’ll ask Rita and Tom if they are available on that day.\", \"vi\": \"Tôi sẽ hỏi Rita và Tom xem họ có rảnh vào ngày hôm đó không.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Unfortunately, I have a family commitment out of town that day.\", \"vi\": \"Thật không may, tôi có việc gia đình ở ngoài tỉnh vào ngày hôm đó.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I’ll get started on the Chens’ order now.\", \"vi\": \"Tôi sẽ bắt đầu làm đơn hàng của gia đình Chen ngay bây giờ.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Avichai Rosen [1:25 P.M.]\", \"vi\": \"Avichai Rosen [1:25 CH]\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Sounds good.\", \"vi\": \"Được đấy.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Thank you!\", \"vi\": \"Cảm ơn bạn!\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '1cc82f53-c91e-4643-a4cf-d4067e5efc7a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"★ ★ ★ ★ ★ ★ ATTENTION ★ ★ ★ ★ ★ ★\", \"vi\": \"★ ★ ★ ★ ★ ★ XIN LƯU Ý ★ ★ ★ ★ ★ ★\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"As part of our transition to new ownership, the Wesselman Hotel is in the process of making some landscaping improvements, including adding flower beds along the walkways.\", \"vi\": \"Là một phần trong quá trình chuyển giao chủ sở hữu mới, Khách sạn Wesselman đang tiến hành cải tạo cảnh quan, bao gồm việc bổ sung các bồn hoa dọc theo các lối đi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We apologize for the current unsightly condition of the grounds, but soon we will have an impressive floral display.\", \"vi\": \"Chúng tôi thành thật xin lỗi vì tình trạng chưa đẹp mắt hiện tại của khuôn viên, nhưng chẳng bao lâu nữa chúng tôi sẽ có một khu vực trưng bày hoa rực rỡ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Thank you for your patience, and we hope you will return to see our grounds once our gardeners have completed their work.\", \"vi\": \"Cảm ơn sự kiên nhẫn của quý khách và chúng tôi hy vọng quý khách sẽ quay lại để ngắm nhìn khuôn viên của chúng tôi sau khi các thợ làm vườn hoàn thành công việc của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}]' WHERE `id` = '1d3680dd-c0a0-4058-930c-039de12e3ed5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.copychaser.com ▶\", \"vi\": \"https://www.copychaser.com ▶\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Our Services\", \"vi\": \"Dịch vụ của chúng tôi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"At Copychaser, we understand that skillfully written content is essential to a thriving business.\", \"vi\": \"Tại Copychaser, chúng tôi hiểu rằng nội dung được viết khéo léo là điều thiết yếu đối với một doanh nghiệp phát triển thịnh vượng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"That\'s why over the past three decades we have continued to increase our pool of skilled staff and freelance writers representing a wide range of expertise.\", \"vi\": \"Đó là lý do tại sao trong ba thập kỷ qua, chúng tôi đã không ngừng tăng cường đội ngũ nhân viên lành nghề và các cây bút tự do đại diện cho nhiều lĩnh vực chuyên môn đa dạng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"And now we offer you the opportunity to complement your text with artwork developed by our team of graphic artists.\", \"vi\": \"Và giờ đây, chúng tôi mang đến cho bạn cơ hội kết hợp văn bản của mình với các tác phẩm nghệ thuật do đội ngũ họa sĩ đồ họa của chúng tôi phát triển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Let Copychaser take care of all your company\'s communication needs.\", \"vi\": \"Hãy để Copychaser lo liệu mọi nhu cầu truyền thông của công ty bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Service 1: Marketing Copy.\", \"vi\": \"Dịch vụ 1: Văn bản tiếp thị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We will craft the perfect message to promote your products and services, putting your company ahead of the competition.\", \"vi\": \"Chúng tôi sẽ soạn thảo thông điệp hoàn hảo để quảng bá sản phẩm và dịch vụ của bạn, giúp công ty bạn vượt lên trên đối thủ cạnh tranh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Service 2: Content Development.\", \"vi\": \"Dịch vụ 2: Phát triển nội dung.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Whether you need general informational or technical articles, we will match you with the expert writer you need.\", \"vi\": \"Dù bạn cần các bài viết thông tin chung hay bài viết kỹ thuật, chúng tôi sẽ kết nối bạn với chuyên gia viết lách mà bạn cần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Service 3: Translation.\", \"vi\": \"Dịch vụ 3: Dịch thuật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We work with international translation agencies that will give your Web site content the local flavor you need in order to sell to diverse markets and populations.\", \"vi\": \"Chúng tôi hợp tác với các cơ quan dịch thuật quốc tế mang lại cho nội dung trang web của bạn sắc thái địa phương cần thiết để kinh doanh tại các thị trường và nhóm dân cư đa dạng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Service 4: Training in Writing.\", \"vi\": \"Dịch vụ 4: Đào tạo viết lách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We provide in-person workshops and webinars on general writing skills as well as coaching sessions for individuals or small groups on a specific type of writing or project.\", \"vi\": \"Chúng tôi cung cấp các hội thảo trực tiếp và hội thảo trực tuyến về kỹ năng viết chung cũng như các buổi huấn luyện cho cá nhân hoặc nhóm nhỏ về một loại hình viết lách hoặc dự án cụ thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Fill out our project description form and we will get back to you within 24 hours with a service proposal to suit your needs.\", \"vi\": \"Hãy điền vào biểu mẫu mô tả dự án của chúng tôi và chúng tôi sẽ phản hồi bạn trong vòng 24 giờ với một đề xuất dịch vụ phù hợp với nhu cầu của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Our Services\", \"vi\": \"Dịch vụ của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Project Description Form\", \"vi\": \"Biểu mẫu mô tả dự án\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Client Reviews\", \"vi\": \"Đánh giá của khách hàng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Project Description Form\", \"vi\": \"Biểu mẫu mô tả dự án\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Name:  Yuna Takahashi\", \"vi\": \"Tên: Yuna Takahashi\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Submitted: 11 January\", \"vi\": \"Đã gửi: Ngày 11 tháng 1\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Project Description:\", \"vi\": \"Mô tả dự án:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I\'m looking for an expert who can write articles related to the petroleum business.\", \"vi\": \"Tôi đang tìm kiếm một chuyên gia có thể viết các bài báo liên quan đến ngành kinh doanh dầu mỏ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"This would be for an online periodical that I edit and publish.\", \"vi\": \"Việc này dành cho một ấn phẩm định kỳ trực tuyến mà tôi biên tập và xuất bản.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"The ideal writer has an established background in petrochemicals or in economics as it relates to the international oil market.\", \"vi\": \"Người viết lý tưởng có nền tảng vững chắc về hóa dầu hoặc kinh tế học liên quan đến thị trường dầu mỏ quốc tế.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"A degree in a field related to fossil fuels or economics is preferred.\", \"vi\": \"Ưu tiên bằng cấp trong lĩnh vực liên quan đến nhiên liệu hóa thạch hoặc kinh tế học.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I need someone who can communicate complex topics clearly while maintaining scientific accuracy.\", \"vi\": \"Tôi cần một người có thể truyền达 các chủ đề phức tạp một cách rõ ràng đồng thời đảm bảo tính chính xác về mặt khoa học.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Name - Degree and Expertise\", \"vi\": \"Tên - Bằng cấp và Chuyên môn\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Analia Almeida - Master of Business Administration. Experience in agricultural commodity pricing. Consultant in food packaging.\", \"vi\": \"Analia Almeida - Thạc sĩ Quản trị Kinh doanh. Có kinh nghiệm về định giá hàng hóa nông sản. Tư vấn viên về đóng gói thực phẩm.\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Cara Ponti - Doctorate in Physics. Expert in subatomic particle theory and light spectrum analysis of distant space objects.\", \"vi\": \"Cara Ponti - Tiến sĩ Vật lý. Chuyên gia về lý thuyết hạt hạ nguyên tử và phân tích phổ ánh sáng của các vật thể không gian xa xôi.\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Armand Mkhaliphi - Master of Science in Mechanical Engineering. Experience in aircraft design and quality control. Expert in adhesives used in aircraft assembly.\", \"vi\": \"Armand Mkhaliphi - Thạc sĩ Khoa học Kỹ thuật Cơ khí. Có kinh nghiệm về thiết kế máy bay và kiểm soát chất lượng. Chuyên gia về chất kết dính được sử dụng trong lắp ráp máy bay.\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Wayne Bryfield - Doctorate in Chemical Engineering. Expert in fuel and lubricant formulation. Presenter on topics related to the oil and gas industries.\", \"vi\": \"Wayne Bryfield - Tiến sĩ Kỹ thuật Hóa học. Chuyên gia về công thức nhiên liệu và chất bôi trơn. Diễn giả về các chủ đề liên quan đến ngành công nghiệp dầu khí.\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Copychaser search results for Project 981:\", \"vi\": \"Kết quả tìm kiếm của Copychaser cho Dự án 981:\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '1d8afc8e-9b7a-4355-9eeb-5667b60d6557';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"New Policy for Remote Participation\", \"vi\": \"Chính sách mới về việc tham gia từ xa\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"On Monday, the board of directors of Heart & Health Charity adopted a remote participation policy for committees, boards, and working groups operating under the organization\'s umbrella.\", \"vi\": \"Vào thứ Hai, hội đồng quản trị của Tổ chức Từ thiện Heart & Health đã thông qua chính sách tham gia từ xa dành cho các ủy ban, ban hội đồng và nhóm công tác hoạt động dưới sự bảo trợ của tổ chức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The policy authorizes the chairperson of the particular committee to permit a member to participate by telephone or videoconference when the member cannot physically attend the meeting.\", \"vi\": \"Chính sách này ủy quyền cho chủ tịch của ủy ban cụ thể cho phép một thành viên tham gia qua điện thoại hoặc hội nghị truyền hình khi thành viên đó không thể trực tiếp tham dự cuộc họp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"There are forms to fill out and procedures to follow, so check the Web site for details on how to take advantage of this new policy.\", \"vi\": \"Có các biểu mẫu cần điền và thủ tục phải tuân theo, vì vậy hãy kiểm tra trang web để biết chi tiết về cách tận dụng chính sách mới này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}]' WHERE `id` = '1d90d4be-172c-467f-990a-5f43e597d0de';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Crescent Moon Bistro\", \"vi\": \"Nhà hàng Crescent Moon Bistro\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.cmb.com\", \"vi\": \"http://www.cmb.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Located along the eastern shore of Canawap Bay, the Crescent Moon Bistro is a unique venue for birthday parties, weddings, corporate gatherings, and a host of other social events.\", \"vi\": \"Nằm dọc theo bờ phía đông của Vịnh Canawap, Crescent Moon Bistro là một địa điểm độc đáo dành cho các buổi tiệc sinh nhật, đám cưới, hội họp công ty và nhiều sự kiện xã hội khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Our chefs work with you to craft a perfect menu, while our coordinators will see to it that your event is superbly organized.\", \"vi\": \"Các đầu bếp của chúng tôi sẽ làm việc cùng bạn để thiết kế một thực đơn hoàn hảo, trong khi các điều phối viên của chúng tôi sẽ đảm bảo rằng sự kiện của bạn được tổ chức tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Rental pricing is based on the date, type of event, and number of attendees.\", \"vi\": \"Giá thuê được tính dựa trên ngày, loại sự kiện và số lượng người tham dự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"You are welcome to tour our facility on October 10 from 11:00 A.M. to 2:00 P.M. Meet with our coordinators and culinary staff, and sample items from our creative menu.\", \"vi\": \"Bạn được chào đón đến tham quan cơ sở của chúng tôi vào ngày 10 tháng 10 từ 11:00 sáng đến 2:00 chiều. Gặp gỡ các điều phối viên và đội ngũ nhân viên ẩm thực của chúng tôi, đồng thời nếm thử các món ăn từ thực đơn sáng tạo của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Admission is free, but registration is required.\", \"vi\": \"Vào cửa miễn phí, nhưng bắt buộc phải đăng ký.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We are offering 25% off on any booking made during this open house on October 10.\", \"vi\": \"Chúng tôi đang ưu đãi giảm giá 25% cho bất kỳ lượt đặt chỗ nào được thực hiện trong buổi tham quan mở cửa này vào ngày 10 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '1e34fa08-14a0-4729-a4fd-b98179c35a1a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Date: February 19\", \"vi\": \"Ngày: Ngày 19 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All employees\", \"vi\": \"Đến: Tất cả nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Corporate headquarters\", \"vi\": \"Từ: Trụ sở chính công ty\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"As part of Employee Appreciation Week, Seaside Coffee management would like to remind employees of the variety of perks available to them year-round.\", \"vi\": \"Như một phần của Tuần lễ Tri ân Nhân viên, ban quản lý Seaside Coffee muốn nhắc nhở nhân viên về các loại phúc lợi đa dạng dành cho họ quanh năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Employees may have one free food item and one free drink from the café per shift.\", \"vi\": \"Nhân viên có thể nhận được một món ăn miễn phí và một thức uống miễn phí từ quán cà phê trong mỗi ca làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"When not working, employees may receive a 25% discount on any product at all Seaside locations by giving their employee number at checkout.\", \"vi\": \"Khi không làm việc, nhân viên có thể nhận được mức giảm giá 25% cho bất kỳ sản phẩm nào tại tất cả các cơ sở của Seaside bằng cách cung cấp mã số nhân viên của họ tại quầy thanh toán.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This is the number that you clock in and out with.\", \"vi\": \"Đây là mã số mà bạn dùng để chấm công vào và ra ca.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Finally, we offer benefits at partner businesses ranging from grocery stores to music streaming services through the \\\"Work Plus\\\" platform.\", \"vi\": \"Cuối cùng, chúng tôi cung cấp các phúc lợi tại các doanh nghiệp đối tác, từ cửa hàng tạp hóa đến dịch vụ phát trực tuyến âm nhạc thông qua nền tảng \\\"Work Plus\\\".\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"If you have not already done so, visit www.workplus.com/seaside to sign up and begin taking advantage of those.\", \"vi\": \"Nếu bạn chưa làm việc đó, hãy truy cập www.workplus.com/seaside để đăng ký và bắt đầu tận dụng những ưu đãi đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"As always, thank you for being a part of the Seaside family.\", \"vi\": \"Như mọi khi, cảm ơn bạn vì đã là một phần của gia đình Seaside.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Reid Walden\", \"vi\": \"Reid Walden\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Vice President of Human Resources\", \"vi\": \"Phó Chủ tịch Nhân sự\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"MEMO\", \"vi\": \"BẢN NỘI BỘ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '1e38a922-e1ce-4c6b-8100-457e97ef6ef4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Marcus Witt <mwitt@bmail.com>\", \"vi\": \"Đến: Marcus Witt <mwitt@bmail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Julie Mendell <contracts@nevycorp.com>\", \"vi\": \"Từ: Julie Mendell <contracts@nevycorp.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 1 June\", \"vi\": \"Ngày: 1 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Your contract with Nevy\", \"vi\": \"Chủ đề: Hợp đồng của bạn với Nevy\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Renewal form\", \"vi\": \"Đính kèm: Biểu mẫu gia hạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Witt:\", \"vi\": \"Ông Witt kính mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Greetings from the Nevy Corporation.\", \"vi\": \"Lời chào từ Tập đoàn Nevy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I hope this message finds you well.\", \"vi\": \"Tôi hy vọng bạn vẫn khỏe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As I mentioned on our recent call, we are conducting a review of our current ____135___ .\", \"vi\": \"Như tôi đã đề cập trong cuộc gọi gần đây của chúng ta, chúng tôi đang tiến hành xem xét ____135___ hiện tại của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [135]}, {\"en\": \"This includes your agency.\", \"vi\": \"Điều này bao gồm cả công ty của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"___136____ the difficult year, we have been impressed with your agency\'s professionalism and positive results.\", \"vi\": \"___136____ một năm đầy khó khăn, chúng tôi rất ấn tượng với sự chuyên nghiệp và kết quả tích cực của công ty bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [136]}, {\"en\": \"___137____ .\", \"vi\": \"___137____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [137]}, {\"en\": \"Please sign the attached document and return it to us at your earliest convenience.\", \"vi\": \"Vui lòng ký vào tài liệu đính kèm và gửi lại cho chúng tôi vào thời gian sớm nhất có thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We ___138____ forward to strengthening our relationship with you and your team.\", \"vi\": \"Chúng tôi ___138____ mong muốn củng cố mối quan hệ với bạn và đội ngũ của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": [138]}, {\"en\": \"If you have any questions or concerns, please let us know.\", \"vi\": \"Nếu bạn có bất kỳ câu hỏi hoặc thắc mắc nào, vui lòng cho chúng tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Julie Mendell\", \"vi\": \"Julie Mendell\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Partner Relations Manager\", \"vi\": \"Trưởng phòng Quan hệ Đối tác\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '1e467144-2c36-48b7-80f7-b0a7c6074304';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Zippy Petrol Mart\", \"vi\": \"Trạm Xăng Dầu Zippy\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"M64 Motorway\", \"vi\": \"Đường cao tốc M64\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Leicester\", \"vi\": \"Leicester\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"0113 4960423\", \"vi\": \"0113 4960423\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"23 May\", \"vi\": \"Ngày 23 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Biscuits £2.00\", \"vi\": \"Bánh quy £2.00\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Fruit cup £0.95\", \"vi\": \"Cốc trái cây £0.95\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Crisps £1.10\", \"vi\": \"Khoai tây chiên giòn £1.10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"VAT Inclusive £0.81\", \"vi\": \"Đã bao gồm thuế VAT £0.81\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Total £4.86\", \"vi\": \"Tổng cộng £4.86\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Sign up for our Zippy Club rewards card.\", \"vi\": \"Đăng ký thẻ thành viên thưởng Zippy Club của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You could have earned 4 Zippy Club points on this transaction.\", \"vi\": \"Bạn có thể đã tích lũy được 4 điểm Zippy Club cho giao dịch này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Points can be used for discounted merchandise, car products, phone accessories, and more!\", \"vi\": \"Điểm thưởng có thể được sử dụng để mua hàng hóa giảm giá, sản phẩm ô tô, phụ kiện điện thoại và nhiều thứ khác!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '1e967e08-1f08-4ac7-8395-d54e44b0286a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Job Posted: April 10\", \"vi\": \"Ngày đăng tuyển: 10 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Seeking: Highly Experienced Finance Director\", \"vi\": \"Tuyển dụng: Giám đốc Tài chính có nhiều kinh nghiệm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Employer: Vimaxo Financial Services (VFS)\", \"vi\": \"Nhà tuyển dụng: Dịch vụ Tài chính Vimaxo (VFS)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Duties include:\", \"vi\": \"Nhiệm vụ bao gồm:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Setting annual financial targets\", \"vi\": \"Thiết lập các mục tiêu tài chính hàng năm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Managing the duties of accounting staff\", \"vi\": \"Quản lý nhiệm vụ của nhân viên kế toán\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Overseeing investments and cash flow\", \"vi\": \"Giám sát các khoản đầu tư và dòng tiền\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Developing sound financial strategies\", \"vi\": \"Phát triển các chiến lược tài chính vững chắc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Prerequisites:\", \"vi\": \"Yêu cầu tiên quyết:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"5 years of experience as a finance director\", \"vi\": \"5 năm kinh nghiệm làm giám đốc tài chính\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"A university degree in economics or similar field\", \"vi\": \"Bằng đại học ngành kinh tế hoặc lĩnh vực tương đương\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Excellent communication skills\", \"vi\": \"Kỹ năng giao tiếp xuất sắc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Outstanding analytical skills\", \"vi\": \"Kỹ năng phân tích vượt trội\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To apply: Send application and supporting documents to our director of Human Resources, Celeste Zomorodi, at zomorodi.c@vfs.com by May 15.\", \"vi\": \"Cách ứng tuyển: Gửi hồ sơ và các tài liệu hỗ trợ cho giám đốc Nhân sự của chúng tôi, Celeste Zomorodi, tại địa chỉ zomorodi.c@vfs.com trước ngày 15 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We aim to hire the ideal applicant by June 21 and have him/her begin work on July 1.\", \"vi\": \"Chúng tôi đặt mục tiêu tuyển dụng ứng viên lý tưởng trước ngày 21 tháng 6 và để người đó bắt đầu làm việc vào ngày 1 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From: Noritaka Hosokawa\", \"vi\": \"Từ: Noritaka Hosokawa\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"To: Celeste Zomorodi\", \"vi\": \"Đến: Celeste Zomorodi\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date: April 11\", \"vi\": \"Ngày: 11 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Subject: Finance director\", \"vi\": \"Chủ đề: Giám đốc tài chính\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Dear Celeste,\", \"vi\": \"Celeste thân mến,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I wanted to ask you about the finance director job posting released by our department just yesterday.\", \"vi\": \"Tôi muốn hỏi bạn về thông tin tuyển dụng giám đốc tài chính vừa được phòng ban chúng ta công bố hôm qua.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I have a friend named Michaela Shabiby who I think may be a good fit for this position.\", \"vi\": \"Tôi có một người bạn tên là Michaela Shabiby, người mà tôi nghĩ có thể rất phù hợp với vị trí này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"May I encourage her to apply?\", \"vi\": \"Tôi có thể khuyến khích cô ấy nộp đơn ứng tuyển không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Michaela graduated with a Master\'s degree in Finance from the University of Grenada three years ago and has worked since then as finance director at Southside Investment Bank.\", \"vi\": \"Michaela tốt nghiệp Thạc sĩ ngành Tài chính tại Đại học Grenada ba năm trước và kể từ đó đã làm việc với tư cách là giám đốc tài chính tại Ngân hàng Đầu tư Southside.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"She is an experienced trainer, and her analytical skills are unparalleled.\", \"vi\": \"Cô ấy là một chuyên gia đào tạo có kinh nghiệm và kỹ năng phân tích của cô ấy là không ai sánh kịp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Please let me know.\", \"vi\": \"Hãy cho tôi biết ý kiến của bạn nhé.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Noritaka Hosokawa\", \"vi\": \"Noritaka Hosokawa\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '1ea6a743-50eb-4953-81fa-4900face93c9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Mark Schroeder\", \"vi\": \"Đến: Mark Schroeder\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Ashley Nguyen\", \"vi\": \"Từ: Ashley Nguyen\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 5\", \"vi\": \"Ngày: Ngày 5 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Seasonal hiring\", \"vi\": \"Chủ đề: Tuyển dụng thời vụ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hi, Mark,\", \"vi\": \"Chào Mark,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I hope you can take care of our summer hiring this year.\", \"vi\": \"Tôi hy vọng bạn có thể đảm nhận việc tuyển dụng nhân sự mùa hè của chúng ta năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Last year, Nancy Adams put an advertisement in the Shoreline Observer, and we had applicants right away.\", \"vi\": \"Năm ngoái, Nancy Adams đã đăng một quảng cáo trên tờ Shoreline Observer, và chúng ta đã có ứng viên ngay lập tức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I suggest using that paper again.\", \"vi\": \"Tôi đề xuất sử dụng lại tờ báo đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We should hire the same number of workers as last year, but this time, all four should be full-time.\", \"vi\": \"Chúng ta nên tuyển số lượng nhân viên bằng năm ngoái, nhưng lần này, cả bốn người đều phải làm việc toàn thời gian.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please write a new advertisement, and we can look at it together next week before sending it out.\", \"vi\": \"Vui lòng viết một quảng cáo mới, và chúng ta có thể cùng nhau xem xét nó vào tuần tới trước khi gửi đi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"And by the way, thanks for your work getting the Gravel Road store ready to open.\", \"vi\": \"Và nhân tiện, cảm ơn công sức của bạn trong việc chuẩn bị cho cửa hàng đường Gravel Road mở cửa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I know you will be a great store manager when it is operational next month.\", \"vi\": \"Tôi biết bạn sẽ là một quản lý cửa hàng xuất sắc khi cửa hàng đi vào hoạt động vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"One of your first responsibilities will be to put together a terrific staff.\", \"vi\": \"Một trong những trách nhiệm đầu tiên của bạn sẽ là xây dựng một đội ngũ nhân viên tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Ashley Nguyen, General Manager\", \"vi\": \"Ashley Nguyen, Tổng Giám đốc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Surf Bird Beachwear\", \"vi\": \"Surf Bird Beachwear\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Surf Bird Beachwear is Hiring for the Summer!\", \"vi\": \"Surf Bird Beachwear Đang Tuyển Dụng Cho Mùa Hè!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Surf Bird Beachwear, Jaxon Shore\'s best shop for casual clothing and beach supplies, has openings for four full-time workers.\", \"vi\": \"Surf Bird Beachwear, cửa hàng quần áo thông thường và đồ dùng bãi biển tốt nhất tại Jaxon Shore, đang có vị trí trống cho bốn nhân viên toàn thời gian.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"These seasonal positions will be available from the beginning of June until the end of August.\", \"vi\": \"Các vị trí theo mùa này sẽ có sẵn từ đầu tháng 6 cho đến cuối tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Duties include handling sales, stocking shelves, assisting customers, and setting up displays.\", \"vi\": \"Nhiệm vụ bao gồm xử lý việc bán hàng, sắp xếp hàng lên kệ, hỗ trợ khách hàng và thiết lập các trưng bày.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Some early morning and weekend work is required.\", \"vi\": \"Cần phải làm việc một số buổi sáng sớm và cuối tuần.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"We offer a competitive salary and excellent working conditions.\", \"vi\": \"Chúng tôi cung cấp mức lương cạnh tranh và điều kiện làm việc xuất sắc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Surf Bird Beachwear has two locations in Jaxon Shore: the original Pelican Inlet store and, opening in June, our new Gravel Road location.\", \"vi\": \"Surf Bird Beachwear có hai cơ sở tại Jaxon Shore: cửa hàng Pelican Inlet ban đầu và cơ sở mới tại đường Gravel Road sẽ khai trương vào tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"All interviews will be conducted at the Gravel Road store.\", \"vi\": \"Tất cả các buổi phỏng vấn sẽ được tiến hành tại cửa hàng đường Gravel Road.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Go to www.surfbirdbeachwear.com/jobs to apply.\", \"vi\": \"Truy cập www.surfbirdbeachwear.com/jobs để ứng tuyển.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '1ebc6de7-c19b-400e-aef9-d4492703ebfd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"BOSTON (January 3)—According to a recent survey by the National Dentifrice Council, the United States toothpaste packaging market is expected to grow by more than 3 percent over the next decade.\", \"vi\": \"BOSTON (Ngày 3 tháng 1)—Theo một cuộc khảo sát gần đây của Hội đồng Nha khoa Quốc gia, thị trường bao bì kem đánh răng tại Hoa Kỳ dự kiến sẽ tăng trưởng hơn 3% trong thập kỷ tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Collapsible toothpaste tubes continue to lead the market overall, but because they are composed of multiple layers, it is nearly impossible to recycle them.\", \"vi\": \"Các tuýp kem đánh răng có thể xẹp vẫn tiếp tục dẫn đầu thị trường nói chung, nhưng do chúng được cấu thành từ nhiều lớp, việc tái chế chúng là gần như không thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"They are beginning to lose a small part of their market share to recyclable forms of packaging, including jars, bottles, and refillable pump dispensers.\", \"vi\": \"Chúng đang bắt đầu mất đi một phần nhỏ thị phần vào tay các dạng bao bì có thể tái chế, bao gồm hũ, chai và vòi bơm có thể nạp lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Green Globe\", \"vi\": \"Green Globe\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"550 Industrial Parkway\", \"vi\": \"550 Đại lộ Industrial\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Silver Hills, KY 40502\", \"vi\": \"Silver Hills, KY 40502\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"March 7\", \"vi\": \"Ngày 7 tháng 3\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Rohit Patel\", \"vi\": \"Rohit Patel\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Director of Operations\", \"vi\": \"Giám đốc Vận hành\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Macker Drugstores\", \"vi\": \"Hệ thống nhà thuốc Macker Drugstores\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"536 Herald Street, Suite 202\", \"vi\": \"536 Phố Herald, Phòng 202\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Columbus, OH 43004\", \"vi\": \"Columbus, OH 43004\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Dear Mr. Patel,\", \"vi\": \"Ông Patel kính mến,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Thank you for allowing me to speak with you and your team about Green Globe All-Natural Toothpaste.\", \"vi\": \"Cảm ơn ông đã tạo điều kiện cho tôi được trao đổi với ông và đội ngũ của ông về sản phẩm Kem đánh răng hoàn toàn tự nhiên Green Globe.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"As I explained during our meeting, I founded Green Globe ten years ago to offer an alternative to the nonrecyclable packaging used by nearly every other toothpaste brand.\", \"vi\": \"Như tôi đã giải thích trong cuộc họp của chúng ta, tôi đã thành lập Green Globe mười năm trước để cung cấp một giải pháp thay thế cho loại bao bì không thể tái chế được sử dụng bởi hầu hết mọi thương hiệu kem đánh răng khác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Our toothpaste is packaged in 100-milliliter glass jars.\", \"vi\": \"Kem đánh răng của chúng tôi được đóng gói trong các hũ thủy tinh dung tích 100 mililit.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"It is currently sold in stores throughout the United States and Canada.\", \"vi\": \"Sản phẩm hiện đang được bán tại các cửa hàng trên khắp Hoa Kỳ và Canada.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I hope that shoppers will soon be able to buy the product in all the stores in the Macker Drugstores chain.\", \"vi\": \"Tôi hy vọng rằng người mua sắm sẽ sớm có thể mua sản phẩm tại tất cả các cửa hàng trong chuỗi nhà thuốc Macker Drugstores.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I understand that you would like to purchase two cases initially to test sales in a single store.\", \"vi\": \"Tôi hiểu rằng ban đầu ông muốn mua hai thùng để thử nghiệm doanh số tại một cửa hàng duy nhất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Let me emphasize that, as soon as you are ready, we can immediately ship cases to all Macker Drugstores—and, of course, we will offer you a significant discount on all orders over ten cases.\", \"vi\": \"Tôi muốn nhấn mạnh rằng, ngay khi ông sẵn sàng, chúng tôi có thể giao hàng ngay lập tức đến tất cả các cửa hàng Macker Drugstores—và tất nhiên, chúng tôi sẽ dành cho ông mức chiết khấu đáng kể cho mọi đơn hàng trên mười thùng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Thank you again for taking the time to meet with me.\", \"vi\": \"Xin cảm ơn ông một lần nữa vì đã dành thời gian gặp gỡ tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I look forward to working with you.\", \"vi\": \"Tôi rất mong được hợp tác với ông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Sincere regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Verna Brown\", \"vi\": \"Verna Brown\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Item - Quantity - Price per unit - Amount\", \"vi\": \"Mặt hàng - Số lượng - Giá đơn vị - Thành tiền\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Green Globe All-Natural Toothpaste - 2 cases - $145.00 - $290.00\", \"vi\": \"Kem đánh răng hoàn toàn tự nhiên Green Globe - 2 thùng - 145,00 USD - 290,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Shipping - $26.00\", \"vi\": \"Phí vận chuyển - 26,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Subtotal - $316.00\", \"vi\": \"Tổng phụ - 316,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Tax - $19.00\", \"vi\": \"Thuế - 19,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Discount - $0.00\", \"vi\": \"Chiết khấu - 0,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"TOTAL - $335.00\", \"vi\": \"TỔNG CỘNG - 335,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"INVOICE\", \"vi\": \"HÓA ĐƠN\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Green Globe • 550 Industrial Parkway • Silver Hills, KY 40502\", \"vi\": \"Green Globe • 550 Đại lộ Industrial • Silver Hills, KY 40502\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Order 673348\", \"vi\": \"Đơn hàng 673348\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"March 15\", \"vi\": \"Ngày 15 tháng 3\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Ship to:\", \"vi\": \"Giao đến:\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Macker Drugstores Distribution Center\", \"vi\": \"Trung tâm Phân phối Macker Drugstores\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"4000 Highway 36\", \"vi\": \"4000 Cao tốc 36\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Logan, OH 43138\", \"vi\": \"Logan, OH 43138\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}]' WHERE `id` = '1ee8cc96-1c20-4be1-959d-a91272da1d99';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Central Train Service makes it ___143___ than ever to give the gift of travel.\", \"vi\": \"Central Train Service giúp việc tặng món quà du lịch trở nên dễ dàng ___143___ bao giờ hết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [143]}, {\"en\": \"Our gift cards are the perfect way to give someone special an unforgettable journey.\", \"vi\": \"Thẻ quà tặng của chúng tôi là cách hoàn hảo để dành tặng một người đặc biệt một chuyến đi khó quên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Traveling by train can provide passengers with a worry-free experience.\", \"vi\": \"Du lịch bằng tàu hỏa có thể mang lại cho hành khách những trải nghiệm hoàn toàn thảnh thơi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"___144___.\", \"vi\": \"___144___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [144]}, {\"en\": \"Enjoy visiting amazing cities and beautiful national parks.\", \"vi\": \"Hãy tận hưởng chuyến tham quan các thành phố tuyệt vời và những công viên quốc gia đẹp mắt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Central Train Service gift cards never ___145___ .\", \"vi\": \"Thẻ quà tặng của Central Train Service không bao giờ ___145___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [145]}, {\"en\": \"They can be redeemed online or at any major train station.\", \"vi\": \"Chúng có thể được sử dụng trực tuyến hoặc tại bất kỳ nhà ga xe lửa lớn nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Cards can be purchased in amounts up to $500.\", \"vi\": \"Thẻ có thể được mua với mệnh giá lên tới 500 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"There are no additional ___146___ .\", \"vi\": \"Không có bất kỳ khoản ___146___ nào bổ sung.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [146]}, {\"en\": \"The full value of the gift card can be applied to any ticket purchase.\", \"vi\": \"Toàn bộ giá trị của thẻ quà tặng có thể được áp dụng cho bất kỳ giao dịch mua vé nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '1f28fbc7-aba4-4eaf-bbe1-f27a7b4f22cb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Giraffe toy organizer shelving unit\", \"vi\": \"Kệ đựng đồ chơi hình hươu cao cổ\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dimensions: 46 centimeters (width) x 30 centimeters (depth) x 95 centimeters (height)\", \"vi\": \"Kích thước: 46 cm (rộng) x 30 cm (sâu) x 95 cm (cao)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Pine wood painted white, with giraffe illustration on both sides\", \"vi\": \"Gỗ thông sơn trắng, có hình minh họa hươu cao cổ ở cả hai mặt\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Plastic guide rails hold three green, removable plastic bins\", \"vi\": \"Thanh ray dẫn hướng bằng nhựa giữ ba thùng nhựa màu xanh lá cây có thể tháo rời\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Package includes all hardware and instructions for at-home assembly\", \"vi\": \"Gói sản phẩm bao gồm tất cả phụ kiện và hướng dẫn lắp ráp tại nhà\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Get 15% off when you order at least three items from the Zoo Bedroom Set.\", \"vi\": \"Nhận ngay giảm giá 15% khi bạn đặt mua ít nhất ba sản phẩm từ Bộ nội thất phòng ngủ Zoo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Offer available online only.\", \"vi\": \"Ưu đãi chỉ áp dụng trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Valid through August 10.\", \"vi\": \"Có hiệu lực đến hết ngày 10 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"◀\", \"vi\": \"◀\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"▶\", \"vi\": \"▶\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"www.prillenhome.com\", \"vi\": \"www.prillenhome.com\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"▼\", \"vi\": \"▼\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '1fa4ef38-326f-4ffd-b584-3faeb1ced32d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Home Style Clothing Line Debuts\", \"vi\": \"Dòng thời trang Home Style ra mắt\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"MANILA (September 18)—Inspired by the handmade crafts of the Philippines, local designer Maritess Bautista has introduced Home Style, a clothing brand that features fabrics woven by area artisans using traditional practices.\", \"vi\": \"MANILA (18 tháng 9)—Lấy cảm hứng từ các sản phẩm thủ công mỹ nghệ của Philippines, nhà thiết kế địa phương Maritess Bautista đã giới thiệu Home Style, một thương hiệu quần áo nổi bật với các loại vải được dệt bởi các nghệ nhân trong vùng sử dụng phương pháp truyền thống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Bautista first learned basic weaving techniques from her mother and aunts in her youth and built on that knowledge as she studied at the Manila School of Fashion Design.\", \"vi\": \"Bautista lần đầu tiên học các kỹ thuật dệt cơ bản từ mẹ và các dì của mình khi còn trẻ và phát triển dựa trên kiến thức đó khi cô học tại Trường Thiết kế Thời trang Manila.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"She then spent the next ten years working as a junior designer for Trendy Today.\", \"vi\": \"Sau đó, cô dành mười năm tiếp theo làm nhà thiết kế cấp dưới cho Trendy Today.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Finally, she returned to her hometown of San Jacinto to found Home Style.\", \"vi\": \"Cuối cùng, cô trở về quê hương San Jacinto để thành lập Home Style.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Home Style’s debut collection includes clothing and hair accessories that utilize the weaving techniques and designs that the area is known for.\", \"vi\": \"Bộ sưu tập ra mắt của Home Style bao gồm quần áo và phụ kiện tóc sử dụng các kỹ thuật dệt và thiết kế mà khu vực này nổi tiếng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Ms. Bautista purchases all the textiles she uses from local craftspeople.\", \"vi\": \"Bà Bautista mua tất cả các loại vải mà cô sử dụng từ các thợ thủ công địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Currently, Home Style merchandise is available only in select San Jacinto-area stores.\", \"vi\": \"Hiện tại, các sản phẩm của Home Style chỉ có sẵn tại một số cửa hàng được chọn ở khu vực San Jacinto.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"“I want to keep production local,” said Ms. Bautista.\", \"vi\": \"“Tôi muốn giữ việc sản xuất ở địa phương,” bà Bautista cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"“That’s good for the artisans, and it’s authentic.\", \"vi\": \"“Điều đó tốt cho các nghệ nhân, và nó mang tính chân thực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"But I don’t want the *products* to remain local.\", \"vi\": \"Nhưng tôi không muốn các sản phẩm chỉ ở lại địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I want to bring our designs to the whole country—maybe even the world.\", \"vi\": \"Tôi muốn mang các thiết kế của chúng tôi ra toàn quốc—thậm chí có thể là cả thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '1ff0c3a0-95b6-4854-93b0-3f8373ab021e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"This season\'s excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for.\", \"vi\": \"Thời tiết tuyệt vời của mùa này đã mang lại vụ thu hoạch trái cây và rau củ bội thu, trong nhiều trường hợp vượt quá mức mà người trồng có thể tìm được người mua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden\'s Web site (www.vfgrdn.org), where you will find our list of drop-off locations.\", \"vi\": \"Những ai trong số quý vị muốn quyên góp nông sản dư thừa cho các tổ chức cộng đồng có thể làm như vậy bằng cách truy cập trang web của Vosey Farm and Garden (www.vfgrdn.org), nơi quý vị sẽ tìm thấy danh sách các địa điểm tiếp nhận của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"If you need us to come to you instead, please contact us.\", \"vi\": \"Nếu quý vị cần chúng tôi đến tận nơi thay vào đó, vui lòng liên hệ với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and quickly distribute your food donations to vetted groups that need it.\", \"vi\": \"Chúng tôi sẽ liên hệ với một trong số nhiều tài xế xe tải độc lập, những người đã nhiệt tình tình nguyện vận chuyển và nhanh chóng phân phối các khoản quyên góp thực phẩm của quý vị cho các nhóm đã được kiểm duyệt cần đến chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Check our Web site for more information about this service as well as for insights into topics related to farming and gardening in the Northern Great Plains region.\", \"vi\": \"Hãy truy cập trang web của chúng tôi để biết thêm thông tin về dịch vụ này cũng như để có thêm thông tin chi tiết về các chủ đề liên quan đến việc làm nông và làm vườn ở khu vực Northern Great Plains.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}]' WHERE `id` = '2031ca3c-ad3d-4bf5-8338-2cd3ddcdccb0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"CLAREGAL TOURS 🚌\", \"vi\": \"CÔNG TY DU LỊCH CLAREGAL 🚌\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Claregal Tours has been showing visitors Western Ireland\'s most iconic sights for the past fifteen years.\", \"vi\": \"Claregal Tours đã giới thiệu đến du khách những thắng cảnh mang tính biểu tượng nhất của miền Tây Ireland trong mười lăm năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Our buses are comfortable, air-conditioned, and include Wi-Fi.\", \"vi\": \"Xe buýt của chúng tôi thoải mái, có máy lạnh và được trang bị Wi-Fi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Our experienced drivers and guides are well versed in Ireland\'s history and culture.\", \"vi\": \"Các tài xế và hướng dẫn viên giàu kinh nghiệm của chúng tôi rất am hiểu về lịch sử và văn hóa Ireland.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"All excursions are day-long tours and leave from the bus terminal in Galway.\", \"vi\": \"Tất cả các chuyến tham quan đều là tour trọn ngày và khởi hành từ bến xe buýt ở Galway.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Aran Islands (ARI423)\", \"vi\": \"Quần đảo Aran (ARI423)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Spend the day island hopping between these three beautiful islands where you will see ancient ruins, visit a local farm, and have a chance to explore by bicycle.\", \"vi\": \"Dành cả ngày tham quan các hòn đảo giữa ba hòn đảo xinh đẹp này, nơi bạn sẽ ngắm nhìn các di tích cổ, thăm một trang trại địa phương và có cơ hội khám phá bằng xe đạp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Ferry transportation fees included.\", \"vi\": \"Đã bao gồm phí vận chuyển bằng phà.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Adult: €30, University Student: €25, Child: €20\", \"vi\": \"Người lớn: €30, Sinh viên đại học: €25, Trẻ em: €20\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Aran Islands and Cliffs of Moher (AIM523)\", \"vi\": \"Quần đảo Aran và Vách đá Moher (AIM523)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Take your time exploring one of the scenic Aran Islands, Inisheer, and then take a ferry to get up close to the Cliffs of Moher.\", \"vi\": \"Dành thời gian khám phá một trong những hòn đảo Aran đầy phong cảnh, Inisheer, và sau đó đi phà để đến gần hơn với Vách đá Moher.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Ferry transportation fees included.\", \"vi\": \"Đã bao gồm phí vận chuyển bằng phà.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Adult: €40, University Student: €35, Child: €30\", \"vi\": \"Người lớn: €40, Sinh viên đại học: €35, Trẻ em: €30\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Connemara (CON234)\", \"vi\": \"Connemara (CON234)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"See the beautiful national park of Connemara, where nature is at its finest.\", \"vi\": \"Chiêm ngưỡng công viên quốc gia xinh đẹp Connemara, nơi thiên nhiên đẹp tuyệt mỹ.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Choose from several hiking options with varying degrees of difficulty.\", \"vi\": \"Lựa chọn từ nhiều hình thức đi bộ đường dài với các mức độ khó khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Adult: €35, University Student: €30, Child: €25\", \"vi\": \"Người lớn: €35, Sinh viên đại học: €30, Trẻ em: €25\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Thư điện tử*\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To: Alan Trippier; Siobhan Canney\", \"vi\": \"Đến: Alan Trippier; Siobhan Canney\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: Helen Doyle\", \"vi\": \"Từ: Helen Doyle\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date: 8 July\", \"vi\": \"Ngày: 8 tháng 7\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subject: Tomorrow\'s tour\", \"vi\": \"Chủ đề: Chuyến tham quan ngày mai\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 9 July Trip\", \"vi\": \"Tệp đính kèm: 📎 Chuyến đi ngày 9 tháng 7\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"To: Yerri Sliti <yerri.sliti@icmail.com>\", \"vi\": \"Đến: Yerri Sliti <yerri.sliti@icmail.com>\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"From: Claregal Tours <info@claregaltours.co.ie>\", \"vi\": \"Từ: Claregal Tours <info@claregaltours.co.ie>\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Date: 8 July\", \"vi\": \"Ngày: 8 tháng 7\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Subject: Tour confirmation\", \"vi\": \"Chủ đề: Xác nhận tour\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Galway (GAL324)\", \"vi\": \"Galway (GAL324)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Get off the bus and into the city with this walking tour of Galway.\", \"vi\": \"Rời xe buýt và hòa mình vào thành phố với chuyến tham quan đi bộ ở Galway này.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Along the way, you will have the chance to hear traditional music, visit a pub, and see an Irish step dancing performance.\", \"vi\": \"Trên đường đi, bạn sẽ có cơ hội thưởng thức âm nhạc truyền thống, ghé thăm một quán rượu và xem biểu diễn khiêu vũ truyền thống Ireland.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Adult: €20, University Student: €18, Child: €15\", \"vi\": \"Người lớn: €20, Sinh viên đại học: €18, Trẻ em: €15\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Hi Alan and Siobhan,\", \"vi\": \"Chào Alan và Siobhan,\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I have attached the final list of passengers for tomorrow\'s tour with its itinerary.\", \"vi\": \"Tôi đã đính kèm danh sách hành khách cuối cùng cho chuyến tham quan ngày mai cùng với lịch trình của nó.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Alan will be the driver/guide, and Siobhan will be doing passenger check-in.\", \"vi\": \"Alan sẽ làm tài xế kiêm hướng dẫn viên, và Siobhan sẽ làm thủ tục điểm danh hành khách.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"The clients have requested that you drive them to a café to get breakfast before going to Inisheer, which is different from our usual itinerary, but I agreed.\", \"vi\": \"Khách hàng đã yêu cầu bạn lái xe đưa họ đến một quán cà phê để ăn sáng trước khi đến Inisheer, điều này khác với lịch trình thông thường của chúng ta, nhưng tôi đã đồng ý.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"It should take one hour.\", \"vi\": \"Việc đó sẽ mất một tiếng.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Just a reminder that last month we changed the departure time from 9:30 A.M. to 9:15 A.M. Alan, when you are finished with the tour today, please come by my office.\", \"vi\": \"Xin nhắc lại rằng tháng trước chúng ta đã đổi giờ khởi hành từ 9:30 sáng sang 9:15 sáng. Alan, khi bạn hoàn thành chuyến tham quan hôm nay, vui lòng ghé qua văn phòng của tôi.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"I would like to set your schedule for August.\", \"vi\": \"Tôi muốn lên lịch làm việc cho tháng 8 của bạn.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"See you tomorrow,\", \"vi\": \"Hẹn gặp lại ngày mai,\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Helen Doyle\", \"vi\": \"Helen Doyle\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Tour Manager, Claregal Tours\", \"vi\": \"Quản lý Tour, Claregal Tours\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Dear Mr. Sliti,\", \"vi\": \"Kính gửi ông Sliti,\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Your Claregal Tours day trip for twenty guests is confirmed for tomorrow at 9:15 A.M. Please make sure to be at the Galway Bus Terminal fifteen minutes before your departure.\", \"vi\": \"Chuyến đi trong ngày của Claregal Tours dành cho đoàn hai mươi khách của ông đã được xác nhận vào lúc 9:15 sáng ngày mai. Vui lòng đảm bảo có mặt tại Bến xe buýt Galway mười lăm phút trước giờ khởi hành.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"All guests should give their €40 fee directly to your guide.\", \"vi\": \"Tất cả khách nên gửi khoản phí €40 trực tiếp cho hướng dẫn viên của bạn.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"Enjoy your trip!\", \"vi\": \"Chúc quý khách có một chuyến đi vui vẻ!\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"Claregal Tours\", \"vi\": \"Claregal Tours\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 46, \"question_numbers\": []}]' WHERE `id` = '20ce31c9-c44d-430f-ba90-9821c6c77b0e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"KARLINGA BEACH\", \"vi\": \"BÃI BIỂN KARLINGA\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"(December 4)—More resources need to be allocated to promote cultural tourism to the region, officials from the Karlinga Beach Tourism Department (KBTD) concluded at a planning meeting held yesterday.\", \"vi\": \"(Ngày 4 tháng 12)—Cần phân bổ thêm nguồn lực để thúc đẩy du lịch văn hóa đến khu vực này, các quan chức từ Sở Du lịch Bãi biển Karlinga (KBTD) đã kết luận tại một cuộc họp lập kế hoạch được tổ chức vào ngày hôm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The department also drafted a new marketing campaign, titled “Connect with Karlinga Beach,” that will highlight the region’s rich history and culture.\", \"vi\": \"Sở này cũng đã phác thảo một chiến dịch tiếp thị mới mang tên “Kết nối với Bãi biển Karlinga,” nhằm làm nổi bật lịch sử và văn hóa phong phú của vùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"“Everyone agreed that, moving forward, we should focus less on advertising traditional beach activities and more on new eco-friendly tourist activities,” said Tourism Director Arnold Bhatt.\", \"vi\": \"“Mọi người đều đồng ý rằng, trong thời gian tới, chúng ta nên ít tập trung hơn vào việc quảng bá các hoạt động tắm biển truyền thống và tập trung nhiều hơn vào các hoạt động du lịch sinh thái mới,” Giám đốc Du lịch Arnold Bhatt cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"During the meeting, Mr. Bhatt gave a presentation in which he analyzed the results from an online questionnaire designed by students from the region’s university.\", \"vi\": \"Trong cuộc họp, ông Bhatt đã có bài thuyết trình, trong đó ông phân tích kết quả từ một bảng câu hỏi trực tuyến được thiết kế bởi các sinh viên từ trường đại học của vùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Respondents included both local residents and tourists.\", \"vi\": \"Những người trả lời bao gồm cả cư dân địa phương và khách du lịch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In one key result, more than 80 percent of all respondents agreed that there should be more emphasis on promoting eco-friendly tourism.\", \"vi\": \"Trong một kết quả quan trọng, hơn 80 phần trăm tổng số người trả lời đồng ý rằng cần chú trọng hơn nữa vào việc quảng bá du lịch sinh thái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In another finding, more than 75 percent of surveyed tourists indicated they would like to see a wider selection of locally sourced, organic food options.\", \"vi\": \"Trong một phát hiện khác, hơn 75 phần trăm khách du lịch được khảo sát cho biết họ muốn thấy nhiều lựa chọn thực phẩm hữu cơ, có nguồn gốc tại địa phương hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"“For me, the tourists’ response was unexpected,” said Mr. Bhatt.\", \"vi\": \"“Đối với tôi, phản hồi của khách du lịch là điều bất ngờ,” ông Bhatt nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"“But, looking at the full picture, it makes sense, as there are many family farms on the land near the beach.”\", \"vi\": \"“Nhưng, nhìn vào bức tranh toàn cảnh, điều đó hoàn toàn hợp lý, vì có rất nhiều trang trại gia đình trên phần đất gần bãi biển.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The insights from the survey are welcome news for Kathy Li, who operates the KLP Organic Farm.\", \"vi\": \"Những thông tin chi tiết từ cuộc khảo sát là tin vui đối với Kathy Li, người điều hành Trang trại Hữu cơ KLP.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Its grocery store, located on the farm property, is stocked year- round with fresh, seasonal, organically grown produce.\", \"vi\": \"Cửa hàng tạp hóa của trang trại này, nằm trong khuôn viên trang trại, luôn có sẵn các sản phẩm nông nghiệp tươi sống, theo mùa và được trồng theo phương pháp hữu cơ quanh năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"In the future, if tourist visits increase, Ms. Li plans to offer prepared foods and beverages.\", \"vi\": \"Trong tương lai, nếu lượng khách du lịch tăng lên, bà Li dự định sẽ cung cấp các món ăn và đồ uống được chuẩn bị sẵn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '20df73eb-ef48-41d3-a222-11b3a60a0fb5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Retro Crafters focuses on furniture designs from the 1950s through the 1970s.\", \"vi\": \"Retro Crafters tập trung vào các thiết kế nội thất từ thập niên 1950 đến thập niên 1970.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Our products are crafted to highlight the beauty of natural ------- (131).\", \"vi\": \"Các sản phẩm của chúng tôi được chế tác để tôn lên vẻ đẹp của tự nhiên ------- (131).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"To us, small knots, tiny nicks, and color variations are not imperfections.\", \"vi\": \"Đối với chúng tôi, các mắt gỗ nhỏ, vết nứt li ti và sự biến đổi màu sắc không phải là khuyết điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"------- (132).\", \"vi\": \"------- (132).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [132]}, {\"en\": \"Our latest collection features a wall-mounted oak shelving system with narrow rails.\", \"vi\": \"Bộ sưu tập mới nhất của chúng tôi có hệ thống kệ gỗ sồi gắn tường với các thanh ray hẹp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The rails can support shelves, cabinets, drawers, and even a desktop to create a customizable system.\", \"vi\": \"Các thanh ray có thể đỡ các kệ, tủ, ngăn kéo, và thậm chí cả mặt bàn để tạo ra một hệ thống có thể tùy chỉnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"------- (133), the wall-mounted design frees up floor space.\", \"vi\": \"------- (133), thiết kế gắn tường giúp tiết kiệm không gian sàn nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [133]}, {\"en\": \"Our products are carried by furniture ------- (134) in many urban centers around the country.\", \"vi\": \"Các sản phẩm của chúng tôi được bày bán bởi các ------- (134) nội thất tại nhiều trung tâm đô thị trên khắp cả nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [134]}, {\"en\": \"Furniture stores interested in offering our products should contact Nya Fernaut, sales director.\", \"vi\": \"Các cửa hàng nội thất quan tâm đến việc phân phối sản phẩm của chúng tôi nên liên hệ với Nya Fernaut, giám đốc kinh doanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '2118eb1b-ef54-4bb5-8a34-4cc8a401e0c9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Medical and Research Space for Lease\", \"vi\": \"Cho thuê không gian y tế và nghiên cứu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Etoile Centre, in the city of Brussels, is an outstanding place to work.\", \"vi\": \"Trung tâm Etoile, tại thành phố Brussels, là một nơi làm việc tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Its ideal location ___143____ on-site staff unbeatable access to public parks and local amenities.\", \"vi\": \"Vị trí lý tưởng của nó ___143____ giúp cho nhân viên làm việc tại chỗ có quyền tiếp cận tuyệt vời với các công viên công cộng và tiện ích địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [143]}, {\"en\": \"Etoile Centre\'s campus is also in close proximity to top medical and academic institutions.\", \"vi\": \"Khuôn viên của Trung tâm Etoile cũng nằm ở vị trí gần các cơ sở y tế và học thuật hàng đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Consequently, tenants report how easy it is to nurture collaborations with leading ___144____ who live and work in the area.\", \"vi\": \"Do đó, khách thuê báo cáo rằng việc thúc đẩy hợp tác với những ___144____ hàng đầu sống và làm việc trong khu vực này thật dễ dàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [144]}, {\"en\": \"___145____ , Etoile Centre\'s campus itself offers access to large conference rooms, several cafés, and two cafeterias.\", \"vi\": \"___145____ , bản thân khuôn viên Trung tâm Etoile cung cấp quyền sử dụng các phòng hội nghị lớn, một số quán cà phê và hai quán ăn tự phục vụ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [145]}, {\"en\": \"While Etoile Centre\'s North Tower is currently fully occupied, much of the soon-to-be-opened South Tower is still available.\", \"vi\": \"Trong khi Tòa tháp Bắc của Trung tâm Etoile hiện đã được lấp đầy hoàn toàn, phần lớn Tòa tháp Nam sắp khai trương vẫn còn trống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"___146____ .\", \"vi\": \"___146____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [146]}]' WHERE `id` = '212d0cdd-c9f4-4745-9c82-fa2cb9fe79a2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Bingo Imprint creates designs for promotional products such as notebooks, refrigerator magnets, and apparel.\", \"vi\": \"Bingo Imprint tạo ra các thiết kế cho các sản phẩm quảng cáo như sổ tay, nam châm tủ lạnh và trang phục.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"We allow our clients to determine their level of involvement in the design process.\", \"vi\": \"Chúng tôi cho phép khách hàng quyết định mức độ tham gia của họ trong quá trình thiết kế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"------- (143), some submit a detailed sketch of the design.\", \"vi\": \"------- (143), một số người gửi bản phác thảo chi tiết về thiết kế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [143]}, {\"en\": \"Others are ------- (144) content to leave the development and creation of the design up to our graphic artists.\", \"vi\": \"Những người khác ------- (144) hài lòng khi để việc phát triển và tạo ra thiết kế cho các họa sĩ đồ họa của chúng tôi đảm nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [144]}, {\"en\": \"Once the invention has been finalized, it will be shared with the client for approval.\", \"vi\": \"Khi thiết kế được hoàn thiện, nó sẽ được chia sẻ với khách hàng để phê duyệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"------- (145).\", \"vi\": \"------- (145).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [145]}, {\"en\": \"We guarantee that all work will be completed within five business days from when the order is placed.\", \"vi\": \"Chúng tôi đảm bảo rằng tất cả công việc sẽ được hoàn thành trong vòng năm ngày làm việc kể từ khi đơn hàng được đặt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You can count ------- (146) Bingo Imprint for unique designs, competitive pricing, and timely delivery.\", \"vi\": \"Bạn có thể tin cậy ------- (146) Bingo Imprint để có các thiết kế độc đáo, giá cả cạnh tranh và giao hàng đúng hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [146]}]' WHERE `id` = '215eaa76-9504-423c-83e3-f8e345872be6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Gary Wendel (7:40 A.M.)\", \"vi\": \"Gary Wendel (7:40 Sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Good morning, team.\", \"vi\": \"Chào buổi sáng mọi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Can you share the current status of your projects, please?\", \"vi\": \"Mọi người có thể chia sẻ tình trạng hiện tại của các dự án được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Jing Yu (7:42 A.M.)\", \"vi\": \"Jing Yu (7:42 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I met with the client last week to confirm the start date for Phase B of the Palisade project.\", \"vi\": \"Tôi đã gặp khách hàng vào tuần trước để xác nhận ngày bắt đầu cho Giai đoạn B của dự án Palisade.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Robbie Zuniga (7:43 A.M.)\", \"vi\": \"Robbie Zuniga (7:43 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am headed to the job site now for the Riverview project.\", \"vi\": \"Tôi đang trên đường đến công trường ngay bây giờ cho dự án Riverview.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The rain last week delayed pouring the concrete for the sidewalks.\", \"vi\": \"Cơn mưa tuần trước đã làm chậm trễ việc đổ bê tông cho các lối đi bộ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I will check the conditions this morning to see if the situation has improved.\", \"vi\": \"Tôi sẽ kiểm tra tình hình vào sáng nay để xem tình hình đã cải thiện chưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Gary Wendel (7:44 A.M.)\", \"vi\": \"Gary Wendel (7:44 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"When will Phase B of the Palisade project begin?\", \"vi\": \"Khi nào Giai đoạn B của dự án Palisade sẽ bắt đầu?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Jing Yu (7:46 A.M.)\", \"vi\": \"Jing Yu (7:46 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We will break ground in March and plan to have the building completed by November.\", \"vi\": \"Chúng tôi sẽ khởi công vào tháng Ba và dự định hoàn thành tòa nhà trước tháng Mười Một.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Gary Wendel (7:47 A.M.)\", \"vi\": \"Gary Wendel (7:47 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"That\'s good news about the March start date.\", \"vi\": \"Đó là tin vui về ngày khởi công vào tháng Ba.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I am sure the client is happy about that.\", \"vi\": \"Tôi chắc chắn khách hàng rất hài lòng về điều đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Gary Wendel (7:50 A.M.)\", \"vi\": \"Gary Wendel (7:50 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Robbie, let me know what you find out about the site conditions.\", \"vi\": \"Robbie, hãy cho tôi biết những gì bạn tìm hiểu được về điều kiện công trường nhé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Perhaps Nathan Burry can help at the site.\", \"vi\": \"Có lẽ Nathan Burry có thể giúp đỡ tại công trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"He\'s our most knowledgeable concrete finisher.\", \"vi\": \"Anh ấy là thợ hoàn thiện bê tông am hiểu nhất của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Robbie Zuniga (7:55 A.M.)\", \"vi\": \"Robbie Zuniga (7:55 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Actually, I\'m meeting Nathan at the site this morning, so I\'ll get his opinion on when we can pour the concrete.\", \"vi\": \"Thực ra, tôi sẽ gặp Nathan tại công trường sáng nay, vì vậy tôi sẽ lấy ý kiến của anh ấy về thời điểm chúng ta có thể đổ bê tông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"The rest of the project is on hold until we can do this.\", \"vi\": \"Phần còn lại của dự án đang phải tạm dừng cho đến khi chúng ta có thể làm việc này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Gary Wendel (7:57 A.M.)\", \"vi\": \"Gary Wendel (7:57 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Keep me posted.\", \"vi\": \"Hãy cập nhật tình hình cho tôi nhé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I don\'t want to rush it if it\'s still too wet.\", \"vi\": \"Tôi không muốn vội vàng nếu trời vẫn còn quá ẩm ướt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"At the same time, the Riverview project is already behind schedule because of equipment problems and late delivery of building materials.\", \"vi\": \"Đồng thời, dự án Riverview đã bị chậm tiến độ do các vấn đề về thiết bị và việc giao vật liệu xây dựng bị muộn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Robbie Zuniga (7:58 A.M.)\", \"vi\": \"Robbie Zuniga (7:58 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Will do.\", \"vi\": \"Tôi sẽ làm vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 29, \"question_numbers\": []}]' WHERE `id` = '2166e0d8-babb-4a5e-8432-b749842df74f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Company name: Castillo Landscape Design\", \"vi\": \"Tên công ty: Castillo Landscape Design\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Contact name: Valia Castillo\", \"vi\": \"Tên liên hệ: Valia Castillo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Phone: 302-555-0198\", \"vi\": \"Điện thoại: 302-555-0198\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"E-mail: vcastillo@castillold.com\", \"vi\": \"E-mail: vcastillo@castillold.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Web site: www.castillold.com\", \"vi\": \"Trang web: www.castillold.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"62nd Annual Samsville Home and Garden Show\", \"vi\": \"Triển lãm Nhà và Vườn Samsville thường niên lần thứ 62\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"March 31 to April 2, Samsville Conference Pavilion\", \"vi\": \"Từ ngày 31 tháng 3 đến ngày 2 tháng 4, Khu vực Triển lãm Samsville\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Exhibitor Application\", \"vi\": \"Đơn đăng ký tham gia trưng bày\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Items/services to be exhibited:\", \"vi\": \"Các mặt hàng/dịch vụ sẽ trưng bày:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I will display photographs, plans, and models of available outdoor design services that my company offers.\", \"vi\": \"Tôi sẽ trưng bày các bức ảnh, bản vẽ và mô hình về các dịch vụ thiết kế ngoại thất mà công ty tôi cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Additional information or requests:\", \"vi\": \"Thông tin hoặc yêu cầu bổ sung:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I would like to request a second parking pass since one of my employees will also be attending and helping to transport materials.\", \"vi\": \"Tôi muốn yêu cầu thêm một thẻ đỗ xe thứ hai vì một nhân viên của tôi cũng sẽ tham gia và hỗ trợ vận chuyển vật liệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"NOTE: This application is not a contract and does not guarantee a booth at the show.\", \"vi\": \"LƯU Ý: Đơn đăng ký này không phải là hợp đồng và không đảm bảo có gian hàng tại buổi triển lãm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Space is available on a first-come basis.\", \"vi\": \"Không gian sẽ được cung cấp theo thứ tự đăng ký trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Once your completed application is received, a coordinator will contact you within five business days to finalize your reservation and payment.\", \"vi\": \"Ngay khi nhận được đơn đăng ký đã hoàn thành của bạn, điều phối viên sẽ liên hệ với bạn trong vòng năm ngày làm việc để hoàn tất việc đặt chỗ và thanh toán.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Discounts for members of Samsville Home and Garden will be automatically applied at the time of payment.\", \"vi\": \"Giảm giá dành cho thành viên của Hiệp hội Nhà và Vườn Samsville sẽ được áp dụng tự động tại thời điểm thanh toán.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Any questions can be directed to our exhibition organizer, Ms. Faye Li, at fli@samsvillehg.org.\", \"vi\": \"Mọi thắc mắc có thể được gửi tới người tổ chức triển lãm của chúng tôi, cô Faye Li, qua địa chỉ fli@samsvillehg.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"All applications are due by January 31.\", \"vi\": \"Tất cả các đơn đăng ký phải được nộp trước ngày 31 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To: vcastillo@castillold.com\", \"vi\": \"Đến: vcastillo@castillold.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: rconway@samsvillehg.org\", \"vi\": \"Từ: rconway@samsvillehg.org\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date: February 1\", \"vi\": \"Ngày: 1 tháng 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subject: Home and Garden Show\", \"vi\": \"Chủ đề: Triển lãm Nhà và Vườn\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Contract and Invoice\", \"vi\": \"Tệp đính kèm: 📎 Hợp đồng và Hóa đơn\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Dear Ms. Castillo:\", \"vi\": \"Kính gửi Cô Castillo,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"We have received your exhibitor application for the 62nd Annual Samsville Home and Garden Show.\", \"vi\": \"Chúng tôi đã nhận được đơn đăng ký trưng bày của bạn cho Triển lãm Nhà và Vườn Samsville thường niên lần thứ 62.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I am attaching your contract for a booth space and your invoice at the discounted member rate.\", \"vi\": \"Tôi xin gửi kèm hợp đồng thuê không gian gian hàng và hóa đơn của bạn theo mức giá ưu đãi dành cho hội viên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Please return a signed copy of your contract by February 10.\", \"vi\": \"Vui lòng gửi lại một bản hợp đồng đã ký trước ngày 10 tháng 2.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Your reservation includes one walled booth with an electrical outlet, exhibitor ID tags for you and a colleague, and two parking passes, as your request for a second parking pass was approved.\", \"vi\": \"Việc đặt chỗ của bạn bao gồm một gian hàng có vách ngăn với ổ cắm điện, thẻ nhận dạng nhà trưng bày cho bạn và một đồng nghiệp, cùng với hai thẻ đỗ xe, vì yêu cầu về thẻ đỗ xe thứ hai của bạn đã được phê duyệt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Passes are typically limited to one per booth but we will make an exception in this case, as you are a longtime member and exhibitor at our event.\", \"vi\": \"Thẻ đỗ xe thường được giới hạn ở mức một thẻ cho mỗi gian hàng nhưng chúng tôi sẽ phá lệ trong trường hợp này, vì bạn là hội viên lâu năm và là nhà trưng bày thường xuyên tại sự kiện của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"We appreciate your continued participation and support.\", \"vi\": \"Chúng tôi đánh giá cao sự tham gia và hỗ trợ lâu dài của bạn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Rylan Conway, Vendor Coordinator\", \"vi\": \"Rylan Conway, Điều phối viên Nhà cung cấp\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Samsville Home and Garden\", \"vi\": \"Samsville Home and Garden\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '216d7ce9-3ee5-46a6-942d-c6cb278622bc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Home - About - Exhibits - Summer Program - Contact\", \"vi\": \"Trang chủ - Giới thiệu - Triển lãm - Chương trình Mùa hè - Liên hệ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"After viewing our world-class art exhibits, come and enjoy some free music during Cheverly Art Museum\'s tenth annual Summer Concert Series.\", \"vi\": \"Sau khi tham quan các triển lãm nghệ thuật đẳng cấp thế giới của chúng tôi, hãy đến và tận hưởng âm nhạc miễn phí trong Chuỗi Hòa nhạc Mùa hè thường niên lần thứ mười của Bảo tàng Nghệ thuật Cheverly.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From July 14 through August 4, musical performances will be held either on our Atrium Stage near the main entrance or on our Chillum Stage in the outdoor plaza.\", \"vi\": \"Từ ngày 14 tháng 7 đến ngày 4 tháng 8, các buổi biểu diễn âm nhạc sẽ được tổ chức tại Sân khấu Atrium gần lối đi chính hoặc tại Sân khấu Chillum ở quảng trường ngoài trời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Concerts are held from 7–9 P.M. Tickets are $10 in advance or $15 at the door, if still available.\", \"vi\": \"Các buổi hòa nhạc diễn ra từ 7-9 giờ tối. Vé có giá 10 đô la khi mua trước hoặc 15 đô la khi mua tại cửa, nếu vẫn còn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"July 14 Atrium Stage\", \"vi\": \"Ngày 14 tháng 7 - Sân khấu Atrium\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Local trio Killaloe Sounds will start our series off with lively traditional Irish music.\", \"vi\": \"Bộ ba nghệ sĩ địa phương Killaloe Sounds sẽ mở màn chuỗi chương trình của chúng tôi bằng âm nhạc truyền thống Ireland sôi động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"July 21 Atrium Stage\", \"vi\": \"Ngày 21 tháng 7 - Sân khấu Atrium\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Renowned jazz pianist Lillian Cathey will play soulful songs from her Keyboard Sway recording, which has been a best seller for over five years.\", \"vi\": \"Nghệ sĩ dương cầm jazz nổi tiếng Lillian Cathey sẽ biểu diễn các bài hát đầy cảm xúc từ bản ghi âm Keyboard Sway của cô ấy, vốn là đĩa bán chạy nhất trong hơn năm năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"July 28 Chillum Stage\", \"vi\": \"Ngày 28 tháng 7 - Sân khấu Chillum\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The nationally renowned Tulla Stompers play traditional American folk music.\", \"vi\": \"Ban nhạc nổi tiếng toàn quốc Tulla Stompers chơi nhạc dân gian truyền thống của Mỹ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The performance will feature Rhianon Lewis on lead vocals, Hector Freeman on banjo, Lynn Truman on mandolin, and Wyatt Davenport on fiddle.\", \"vi\": \"Buổi biểu diễn sẽ có sự góp mặt của Rhianon Lewis hát chính, Hector Freeman chơi đàn banjo, Lynn Truman chơi đàn mandolin và Wyatt Davenport chơi đàn vĩ cầm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"August 4 Chillum Stage\", \"vi\": \"Ngày 4 tháng 8 - Sân khấu Chillum\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The Hennessy String Quartet will play selections from their recent recording, Summertime Classics.\", \"vi\": \"Tứ tấu đàn dây Hennessy sẽ biểu diễn các trích đoạn từ bản thu âm gần đây của họ, Summertime Classics.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"http://www.cheverlyartmuseum.com\", \"vi\": \"http://www.cheverlyartmuseum.com\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To: Rhianon Lewis <rhianon.lewis@tgd.com>\", \"vi\": \"Đến: Rhianon Lewis <rhianon.lewis@tgd.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From: James Sabo <j.sabo@cheverlyartmuseum.com>\", \"vi\": \"Từ: James Sabo <j.sabo@cheverlyartmuseum.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Subject: Summer concert performance\", \"vi\": \"Chủ đề: Buổi biểu diễn hòa nhạc mùa hè\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date: July 17\", \"vi\": \"Ngày: 17 tháng 7\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Dear Ms. Lewis:\", \"vi\": \"Kính gửi Cô Lewis:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I am the program coordinator for the Cheverly Art Museum.\", \"vi\": \"Tôi là điều phối viên chương trình của Bảo tàng Nghệ thuật Cheverly.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We are so excited to have you perform with us this season.\", \"vi\": \"Chúng tôi rất vui mừng khi có cô biểu diễn cùng chúng tôi trong mùa này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Our concerts are always well received and well attended.\", \"vi\": \"Các buổi hòa nhạc của chúng tôi luôn nhận được phản hồi tốt và lượng khán giả tham gia đông đảo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Please note that we run a sound check onstage an hour before each performance to make sure that all equipment is working properly, so we recommend that musicians arrive by at least two hours before the scheduled start time.\", \"vi\": \"Xin lưu ý rằng chúng tôi tiến hành kiểm tra âm thanh trên sân khấu một tiếng trước mỗi buổi biểu diễn để đảm bảo tất cả thiết bị hoạt động bình thường, vì vậy chúng tôi khuyên các nghệ sĩ nên đến trước giờ bắt đầu dự kiến ít nhất hai tiếng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Also, if you or your bandmates need tickets for friends or family members, please let me know, and I will be happy to coordinate it.\", \"vi\": \"Ngoài ra, nếu cô hoặc các thành viên trong ban nhạc cần vé cho bạn bè hoặc người thân, vui lòng cho tôi biết, và tôi sẽ rất vui lòng sắp xếp việc đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Tickets are no longer available, but we have a few seats reserved that I can offer you.\", \"vi\": \"Vé hiện không còn bán, nhưng chúng tôi có giữ lại một vài chỗ ngồi mà tôi có thể cung cấp cho cô.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I look forward to meeting you!\", \"vi\": \"Tôi rất mong được gặp cô!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"James Sabo\", \"vi\": \"James Sabo\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Program Coordinator, Cheverly Art Museum\", \"vi\": \"Điều phối viên Chương trình, Bảo tàng Nghệ thuật Cheverly\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"To: James Sabo <j.sabo@cheverlyartmuseum.com>\", \"vi\": \"Đến: James Sabo <j.sabo@cheverlyartmuseum.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"From: Rhianon Lewis <rhianon.lewis@tgd.com>\", \"vi\": \"Từ: Rhianon Lewis <rhianon.lewis@tgd.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Subject: RE: Summer concert performance\", \"vi\": \"Chủ đề: V/v: Buổi biểu diễn hòa nhạc mùa hè\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Date: July 17\", \"vi\": \"Ngày: 17 tháng 7\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Hi, James,\", \"vi\": \"Chào James,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Thanks for the information.\", \"vi\": \"Cảm ơn vì thông tin.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"I will be driving with the group from Arlington, so we are all set for transportation.\", \"vi\": \"Tôi sẽ lái xe cùng nhóm từ Arlington, nên chúng tôi đã chuẩn bị xong xuôi về việc di chuyển.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"We plan to arrive at 5:30 p.m.\", \"vi\": \"Chúng tôi dự định đến lúc 5:30 chiều.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"On a separate matter, I hope it is not too late to request a change in venue.\", \"vi\": \"Về một vấn đề khác, tôi hy vọng là chưa quá muộn để yêu cầu thay đổi địa điểm biểu diễn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"I came to see the July 14 performance, and the group that performed then showed a video on the screen behind them as they played.\", \"vi\": \"Tôi đã đến xem buổi biểu diễn ngày 14 tháng 7, và nhóm biểu diễn hôm đó đã chiếu video trên màn hình phía sau khi họ chơi nhạc.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"My group also has images and videos that we would like to display during our performance.\", \"vi\": \"Nhóm của chúng tôi cũng có hình ảnh và video muốn hiển thị trong buổi biểu diễn của mình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"I\'ve spoken with the stage manager, and he said that our scheduled space would not allow for such a setup.\", \"vi\": \"Tôi đã nói chuyện với quản lý sân khấu, và anh ấy nói rằng không gian dự kiến của chúng tôi không đủ điều kiện cho một thiết lập như vậy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"While these elements are not a necessary part of our show, our audiences have found them to be very powerful; thus, we would love to incorporate them if we can.\", \"vi\": \"Mặc dù những yếu tố này không phải là phần bắt buộc trong chương trình của chúng tôi, nhưng khán giả của chúng tôi đã thấy chúng rất ấn tượng; do đó, chúng tôi rất muốn kết hợp chúng nếu có thể.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Cảm ơn bạn,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Rhianon\", \"vi\": \"Rhianon\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}]' WHERE `id` = '21ba9f35-1ba3-498e-b0bd-5012ab167fd4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Conference Room 120 can be booked for meetings and conference calls.\", \"vi\": \"Phòng họp 120 có thể được đặt cho các cuộc họp và cuộc gọi hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"First, make a reservation request online at www.gzpoffice.com/confroom.\", \"vi\": \"Đầu tiên, hãy gửi yêu cầu đặt phòng trực tuyến tại www.gzpoffice.com/confroom.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"When your request ______[135], the system automatically checks for availability.\", \"vi\": \"Khi yêu cầu của bạn ______[135], hệ thống sẽ tự động kiểm tra tình trạng trống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"Your request will be accepted if no other event is scheduled at that time.\", \"vi\": \"Yêu cầu của bạn sẽ được chấp nhận nếu không có sự kiện nào khác được lên lịch vào thời gian đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The system will then immediately send you an e-mail message to ______[136] your reservation.\", \"vi\": \"Hệ thống sau đó sẽ ngay lập tức gửi cho bạn một tin nhắn email để ______[136] đặt phòng của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [136]}, {\"en\": \"However, if another meeting is scheduled that conflicts with yours, you will be notified that the request has been declined.\", \"vi\": \"Tuy nhiên, nếu một cuộc họp khác được lên lịch trùng với lịch của bạn, bạn sẽ được thông báo rằng yêu cầu đã bị từ chối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[137].\", \"vi\": \"______[137].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [137]}, {\"en\": \"It is therefore ______[138] that you schedule your event well ahead of time.\", \"vi\": \"Do đó, việc bạn lên lịch cho sự kiện của mình từ trước là vô cùng ______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [138]}, {\"en\": \"This way, if a given time slot is already reserved, you will be able to reschedule your meeting.\", \"vi\": \"Bằng cách này, nếu khung thời gian đã định đã được đặt trước, bạn sẽ có thể sắp xếp lại lịch cuộc họp của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '21bd1343-3611-46bc-a9bd-42f09970b590';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: tkhan@smolermanufacturing.co.uk\", \"vi\": \"Đến: tkhan@smolermanufacturing.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: lpreston@emmetestate.co.uk\", \"vi\": \"Từ: lpreston@emmetestate.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 9 March\", \"vi\": \"Ngày: 9 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: 1161 Coral Lane\", \"vi\": \"Chủ đề: 1161 Coral Lane\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Khan,\", \"vi\": \"Kính gửi bà Khan,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for asking about the 200-square-metre warehouse space at 1161 Coral Lane.\", \"vi\": \"Cảm ơn bà đã quan tâm đến không gian nhà kho rộng 200 mét vuông tại 1161 Coral Lane.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I checked my real estate database, and ______[143] this property has been taken off the market.\", \"vi\": \"Tôi đã kiểm tra cơ sở dữ liệu bất động sản của mình, và ______[143] bất động sản này đã được rút khỏi thị trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [143]}, {\"en\": \"If you would like to give me an idea of what specifically you are looking for, I ______[144] you in finding something else.\", \"vi\": \"Nếu bà muốn cho tôi biết ý tưởng cụ thể về những gì bà đang tìm kiếm, tôi ______[144] bà trong việc tìm kiếm một không gian khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [144]}, {\"en\": \"Just respond to this e-mail with your price range, size needs, preferred area of town, and any other important requirements.\", \"vi\": \"Chỉ cần trả lời email này với mức giá, nhu cầu diện tích, khu vực ưa thích trong thị trấn và bất kỳ yêu cầu quan trọng nào khác của bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"______[145].\", \"vi\": \"______[145].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [145]}, {\"en\": \"If you wish, you may also sign up for ______[146].\", \"vi\": \"Nếu muốn, bà cũng có thể đăng ký ______[146].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [146]}, {\"en\": \"This way you will receive instant e-mail or text-message notifications whenever new property listings become available.\", \"vi\": \"Bằng cách này, bà sẽ nhận được thông báo tức thì qua email hoặc tin nhắn văn bản bất cứ khi nào có danh sách bất động sản mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Lloyd Preston\", \"vi\": \"Lloyd Preston\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Emmet Estate Agents\", \"vi\": \"Công ty Môi giới Bất động sản Emmet\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '21e0b1d8-2626-4648-8faa-3ab8b9aacc4e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Meeting of the Chelmsbury Civic Association\", \"vi\": \"Cuộc họp của Hiệp hội Dân cư Chelmsbury\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Where: Alvar Madsen Community Center, 4141 Hoover Road\", \"vi\": \"Địa điểm: Trung tâm Cộng đồng Alvar Madsen, 4141 Hoover Road\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"When: Tuesday, June 14, 7:00 P.M.–8:30 P.M.\", \"vi\": \"Thời gian: Thứ Ba, ngày 14 tháng 6, 7:00 tối – 8:30 tối\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Agenda\", \"vi\": \"Chương trình nghị sự\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Introduce new neighbors\", \"vi\": \"Giới thiệu những người hàng xóm mới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Update on road construction\", \"vi\": \"Cập nhật về việc thi công đường xá\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Election of vice president\", \"vi\": \"Bầu cử phó chủ tịch\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Refreshments\", \"vi\": \"Đồ ăn nhẹ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please note:\", \"vi\": \"Xin lưu ý:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We are currently collecting dues for the year.\", \"vi\": \"Chúng tôi hiện đang thu hội phí cho năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The dues are $25.\", \"vi\": \"Mức hội phí là 25 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"If you have not yet paid your dues, please do so.\", \"vi\": \"Nếu bạn vẫn chưa đóng hội phí, vui lòng hoàn thành việc đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"You may pay at the meeting, or you may send your payment to Bob Robsen at 595 Shelton Drive.\", \"vi\": \"Bạn có thể thanh toán tại cuộc họp, hoặc bạn có thể gửi khoản thanh toán của mình cho Bob Robsen tại số 595 Shelton Drive.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We hope to see you at the meeting!\", \"vi\": \"Chúng tôi hy vọng được gặp bạn tại cuộc họp!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Susan Wolfe, President, Chelmsbury Civic Association\", \"vi\": \"Susan Wolfe, Chủ tịch, Hiệp hội Dân cư Chelmsbury\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"784 Harmony Drive\", \"vi\": \"784 Harmony Drive\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '222e350a-1c2b-4b14-b6e2-9bc34525e6c8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Learn about Woodworking\", \"vi\": \"Tìm hiểu về Nghề mộc\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Multonia Hardware, Inc., is offering an online video course about basic woodworking.\", \"vi\": \"Multonia Hardware, Inc. đang cung cấp một khóa học video trực tuyến về nghề mộc cơ bản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The course is fun and can be completed at your own pace, and, best of all, it’s free!\", \"vi\": \"Khóa học rất thú vị, có thể hoàn thành theo tốc độ riêng của bạn và trên hết là hoàn toàn miễn phí!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"It is divided into four prerecorded sections.\", \"vi\": \"Khóa học được chia thành bốn phần đã được quay trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Section 1 is an introduction to woodworking equipment, tools, and safety.\", \"vi\": \"Phần 1 là phần giới thiệu về thiết bị, dụng cụ và an toàn trong nghề mộc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Section 2 describes various types of wood and their appropriate uses.\", \"vi\": \"Phần 2 mô tả các loại gỗ khác nhau và công dụng phù hợp của chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Section 3 introduces the fundamentals of cabinet and furniture repair.\", \"vi\": \"Phần 3 giới thiệu các nguyên tắc cơ bản về sửa chữa tủ và đồ nội thất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The final section describes the preparation of wood surfaces and a variety of popular and beautiful finishing techniques.\", \"vi\": \"Phần cuối cùng mô tả cách chuẩn bị bề mặt gỗ và nhiều kỹ thuật hoàn thiện phổ biến và đẹp mắt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The course includes a downloadable instruction guide and an online chat feature that can connect participants with an experienced woodworking artisan.\", \"vi\": \"Khóa học bao gồm một hướng dẫn bằng văn bản có thể tải xuống và tính năng trò chuyện trực tuyến giúp kết nối những người tham gia với một nghệ nhân làm mộc giàu kinh nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sign up today at multoniahardware.com/tips/basicwoodworking.\", \"vi\": \"Đăng ký ngay hôm nay tại multoniahardware.com/tips/basicwoodworking.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '22f6fc1d-47aa-4277-b3df-b74c69e9dc1a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MEMO\", \"vi\": \"THÔNG BÁO NỘI BỘ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Greegan Electronics warehouse staff\", \"vi\": \"Đến: Nhân viên kho hàng Greegan Electronics\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Kiriko Ishii, Warehouse Manager\", \"vi\": \"Từ: Kiriko Ishii, Quản lý Kho\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: September 24, 2:30 P.M.\", \"vi\": \"Ngày: 24 tháng 9, 2:30 chiều\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Warehouse inventory process\", \"vi\": \"Chủ đề: Quy trình kiểm kê kho hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The recent increase in the range of stock we carry has made our current way of taking inventory inefficient and inadequate.\", \"vi\": \"Sự gia tăng gần đây về chủng loại hàng hóa trong kho đã khiến phương pháp kiểm kê hiện tại của chúng ta trở nên kém hiệu quả và không còn phù hợp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Therefore, we will no longer shut down the entire warehouse for a full inventory twice a year.\", \"vi\": \"Do đó, chúng ta sẽ không còn đóng cửa toàn bộ kho hàng để kiểm kê toàn diện hai lần một năm nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Instead, we will begin taking inventories of defined groups of products either once a quarter, twice a year, or once a year.\", \"vi\": \"Thay vào đó, chúng ta sẽ bắt đầu kiểm kê các nhóm sản phẩm được xác định theo quý, nửa năm một lần, hoặc một năm một lần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This will allow the warehouse to remain at least partially operational year-round and focus our attention on keeping track of our most valuable stock.\", \"vi\": \"Điều này sẽ cho phép kho hàng duy trì hoạt động ít nhất là một phần trong suốt cả năm và tập trung sự chú ý của chúng ta vào việc theo dõi số lượng hàng tồn kho có giá trị nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"A project team is currently determining the classifications of each product.\", \"vi\": \"Một nhóm dự án hiện đang xác định phân loại của từng sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Group A will comprise the top 20% of products based on a combination of cost per unit and order frequency, with the next 40% in Group B and the final 40% in Group C. Once the classifications have been assigned, the first inventory of Group A will begin.\", \"vi\": \"Nhóm A sẽ bao gồm 20% sản phẩm hàng đầu dựa trên sự kết hợp giữa chi phí trên mỗi đơn vị và tần suất đặt hàng, với 40% tiếp theo thuộc Nhóm B và 40% cuối cùng thuộc Nhóm C. Ngay sau khi các phân loại được ấn định, đợt kiểm kê đầu tiên của Nhóm A sẽ bắt đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '23571c07-b2c2-4e43-b73e-833d6b01be66';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Macaw Store Managers\", \"vi\": \"Đến: Tất cả các Quản lý Cửa hàng Macaw\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Mary Van Vliet, Chief Technology Officer\", \"vi\": \"Từ: Mary Van Vliet, Giám đốc Công nghệ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 22 May\", \"vi\": \"Ngày: 22 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Re: Payment system upgrade\", \"vi\": \"V/v: Nâng cấp hệ thống thanh toán\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Next week new payment processing terminals will be installed at each sales register in Macaw stores located in St. Thomas.\", \"vi\": \"Tuần tới, các thiết bị đầu cuối xử lý thanh toán mới sẽ được lắp đặt tại mỗi quầy tính tiền ở các cửa hàng Macaw tọa lạc tại St. Thomas.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Payment System 4.0 ______[139] in our stores in Puerto Rico for several months.\", \"vi\": \"Hệ thống Thanh toán 4.0 ______[139] tại các cửa hàng của chúng tôi ở Puerto Rico trong vài tháng qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [139]}, {\"en\": \"So far, no issues with the system have been reported by ______[140] customers or managers there.\", \"vi\": \"Cho đến nay, chưa có vấn đề nào với hệ thống được báo cáo bởi ______[140] khách hàng hoặc quản lý ở đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [140]}, {\"en\": \"______[141].\", \"vi\": \"______[141].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [141]}, {\"en\": \"It is faster and handles more transaction types than the current payment system.\", \"vi\": \"Nó nhanh hơn và xử lý nhiều loại giao dịch hơn so với hệ thống thanh toán hiện tại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"It also eliminates the need for ______[142] verification of transactions under $25.00.\", \"vi\": \"Nó cũng loại bỏ nhu cầu ______[142] xác minh các giao dịch dưới 25,00 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [142]}, {\"en\": \"Please feel free to contact me with any questions about the installation.\", \"vi\": \"Vui lòng liên hệ với tôi nếu có bất kỳ câu hỏi nào về việc lắp đặt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '23ad0dfb-4736-4f00-b273-857cc5d593c6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Britta Gehring <bgehring@gehringaccounting.com>\", \"vi\": \"Đến: Britta Gehring <bgehring@gehringaccounting.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Mikel Zubiondo <mikel@zubiondodesign.com>\", \"vi\": \"Từ: Mikel Zubiondo <mikel@zubiondodesign.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: December 12\", \"vi\": \"Ngày: 12 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Logo sketches\", \"vi\": \"Chủ đề: Bản phác thảo logo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Gehring_sketches\", \"vi\": \"Tập đính kèm: Gehring_sketches\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Gehring,\", \"vi\": \"Kính gửi bà Gehring,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for entrusting me with the design of the logo for your business.\", \"vi\": \"Cảm ơn bà đã tin tưởng giao cho tôi thiết kế logo cho doanh nghiệp của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I took ------- (139) notes during our meeting last week, and I feel that I understand the business values you want the logo to convey.\", \"vi\": \"Tôi đã ghi chép ------- (139) trong cuộc họp của chúng ta tuần trước, và tôi cảm thấy rằng mình hiểu các giá trị doanh nghiệp mà bà muốn logo truyền tải.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [139]}, {\"en\": \"I have attached five sketches for you.\", \"vi\": \"Tôi đã đính kèm năm bản phác thảo dành cho bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"------- (140) represents your business in a slightly different way.\", \"vi\": \"------- (140) thể hiện doanh nghiệp của bà theo một cách hơi khác biệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [140]}, {\"en\": \"Two have a classic, timeless look, while the others are minimalist and modern.\", \"vi\": \"Hai bản mang vẻ cổ điển, vượt thời gian, trong khi những bản khác thì tối giản và hiện đại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"------- (141).\", \"vi\": \"------- (141).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [141]}, {\"en\": \"Once you review the sketches, let me know which you like and what changes I should make, if any.\", \"vi\": \"Sau khi bà xem xét các bản phác thảo, hãy cho tôi biết bà thích bản nào và tôi nên thực hiện những thay đổi gì, nếu có.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I look forward to ------- (142) the design with you.\", \"vi\": \"Tôi rất mong được ------- (142) thiết kế này cùng bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": [142]}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Mikel Zubiondo, Zubiondo Design\", \"vi\": \"Mikel Zubiondo, Zubiondo Design\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '244d76e5-e847-408f-8e60-a3ed4580d91e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Jorge Avila 10:18 A.M.\", \"vi\": \"Jorge Avila 10:18 Sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"You may have noticed that the air-conditioning is not functioning in parts of the building.\", \"vi\": \"Các bạn có thể đã nhận thấy hệ thống điều hòa không khí không hoạt động ở một số khu vực trong tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Simon Miano 10:19 A.M.\", \"vi\": \"Simon Miano 10:19 Sáng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I noticed.\", \"vi\": \"Tôi có nhận ra.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The temperature and humidity are rising fast in here.\", \"vi\": \"Nhiệt độ và độ ẩm đang tăng lên nhanh chóng ở trong này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Jorge Avila 10:20 A.M.\", \"vi\": \"Jorge Avila 10:20 Sáng\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"A condenser is down, and the fix is not quick or cheap.\", \"vi\": \"Một thiết bị ngưng tụ bị hỏng, và việc sửa chữa không hề nhanh chóng hay rẻ tiền.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The last time one broke it took a week to get a replacement.\", \"vi\": \"Lần trước khi một chiếc bị hỏng, phải mất một tuần mới có đồ thay thế.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I\'m glad that it\'s not too hot this week.\", \"vi\": \"Tôi rất mừng là tuần này trời không quá nóng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The technician is on the way, but for now, feel free to plug in a fan.\", \"vi\": \"Kỹ thuật viên đang trên đường đến, nhưng tạm thời, mọi người cứ cắm điện dùng quạt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Simon Miano 10:24 A.M.\", \"vi\": \"Simon Miano 10:24 Sáng\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I\'m afraid the computer servers may overheat.\", \"vi\": \"Tôi sợ các máy chủ máy tính có thể bị quá nhiệt.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Do we have any portable units we could set up in the Information Technology office?\", \"vi\": \"Chúng ta có đơn vị di động nào có thể lắp đặt ở văn phòng Công nghệ Thông tin không?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"April Denner 10:25 A.M.\", \"vi\": \"April Denner 10:25 Sáng\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We really can\'t afford to lose them.\", \"vi\": \"Chúng ta thực sự không thể để mất chúng được.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Jorge Avila 10:26 A.M.\", \"vi\": \"Jorge Avila 10:26 Sáng\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Not in this building.\", \"vi\": \"Không có ở tòa nhà này.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"With Ms. Denner\'s OK, we could use the van to pick up the ones in the warehouse in Mindones.\", \"vi\": \"Với sự đồng ý của cô Denner, chúng ta có thể dùng xe van để lấy những chiếc ở kho hàng ở Mindones.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I think we have 3 or 4 there.\", \"vi\": \"Tôi nghĩ chúng ta có 3 hoặc 4 chiếc ở đó.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"But the earliest I could get back is tonight.\", \"vi\": \"Nhưng thời gian sớm nhất tôi có thể quay lại là tối nay.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"April Denner 10:28 A.M.\", \"vi\": \"April Denner 10:28 Sáng\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Jorge, I\'m authorizing you to make an emergency purchase of portable AC units for the IT office right away.\", \"vi\": \"Jorge, tôi ủy quyền cho anh tiến hành mua gấp các máy điều hòa di động cho văn phòng IT ngay lập tức.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Please decide on the number of units needed, determine the cost, and report back to me as soon as you have set up the purchase.\", \"vi\": \"Vui lòng quyết định số lượng thiết bị cần thiết, xác định chi phí và báo cáo lại cho tôi ngay khi anh đã hoàn tất việc mua hàng.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Jorge Avila 10:28 A.M.\", \"vi\": \"Jorge Avila 10:28 Sáng\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I\'ll get started on that now.\", \"vi\": \"Tôi sẽ bắt đầu việc đó ngay bây giờ.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"April Denner 10:29 A.M.\", \"vi\": \"April Denner 10:29 Sáng\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"If you can\'t get a local appliance outlet to deliver by the afternoon, send someone in the delivery van to pick them up.\", \"vi\": \"Nếu anh không thể yêu cầu một cửa hàng thiết bị gia dụng địa phương giao hàng trước buổi chiều, hãy cử người lái xe giao hàng đến lấy chúng.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '2474bfec-119a-4d39-9c1d-48e6e739b3f0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"All-Italy Pass\", \"vi\": \"Thẻ All-Italy Pass\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Italy has so much to offer—museums, gardens, beautiful scenery, and great food.\", \"vi\": \"Ý có rất nhiều điều để khám phá—các bảo tàng, khu vườn, phong cảnh tuyệt đẹp và ẩm thực tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"For one low price, the All-Italy Pass provides access to more than a hundred popular attractions across the country.\", \"vi\": \"Chỉ với một mức giá thấp, thẻ All-Italy Pass cho phép bạn tham quan hơn một trăm điểm đến nổi tiếng trên khắp cả nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The more you ______[131] it, the better value you will get.\", \"vi\": \"Bạn càng ______[131] nó nhiều bao nhiêu, bạn càng nhận được giá trị tốt bấy nhiêu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [131]}, {\"en\": \"______[132].\", \"vi\": \"______[132].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [132]}, {\"en\": \"Passes must be purchased online before you leave your home country and are activated when you visit your first attraction.\", \"vi\": \"Thẻ phải được mua trực tuyến trước khi bạn rời quê nhà và sẽ được kích hoạt khi bạn đến thăm địa điểm tham quan đầu tiên của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"They will remain ______[133] for 21 days.\", \"vi\": \"Chúng sẽ vẫn ______[133] trong vòng 21 ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [133]}, {\"en\": \"Purchase of the pass ______[134] includes a decorative travel pin and full-color souvenir guidebook.\", \"vi\": \"Việc mua thẻ ______[134] bao gồm một huy hiệu du lịch trang trí và một cuốn sách hướng dẫn lưu niệm đầy màu sắc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [134]}]' WHERE `id` = '2488401e-c4cc-43b4-9291-d66c08aa7473';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Chakia Brown [3:32 P.M.]\", \"vi\": \"Chakia Brown [3:32 P.M.]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Ziva.\", \"vi\": \"Xin chào Ziva.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I just met with the Han board of directors, and they\'re interested in our redesign proposal for their downtown office buildings.\", \"vi\": \"Tôi vừa có cuộc họp với hội đồng quản trị của Han, và họ quan tâm đến đề xuất thiết kế lại của chúng ta cho các tòa nhà văn phòng ở trung tâm thành phố của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Amy Han asked for another work sample, but I didn\'t have the right portfolio with me.\", \"vi\": \"Amy Han đã yêu cầu một mẫu công việc khác, nhưng tôi lại không mang theo danh mục đầu tư phù hợp bên mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I\'m heading to another meeting, so please have a messenger deliver a copy of the Grainger Centre files to her.\", \"vi\": \"Tôi chuẩn bị đi dự một cuộc họp khác, vì vậy phiền bạn nhờ người giao hàng mang một bản sao các tài liệu về Trung tâm Grainger đến cho cô ấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Include the full set of plans.\", \"vi\": \"Hãy bao gồm toàn bộ bộ bản vẽ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thanks!\", \"vi\": \"Cảm ơn bạn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '2496586a-2b26-4f3f-8470-47bcfcabd478';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Calbo Cuts\", \"vi\": \"Calbo Cuts\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"★★★☆☆\", \"vi\": \"★★★☆☆\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"My visit to Calbo Cuts as a first-time customer was disappointing.\", \"vi\": \"Lần đầu tiên tôi đến tiệm Calbo Cuts với tư cách là khách hàng đã để lại cho tôi sự thất vọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"When I arrived, the sign on the door said \\\"Walk-ins welcome,\\\" but the receptionist bluntly told me that I would need to wait about an hour for my haircut, even though only one other customer was in the shop and three stylists were there.\", \"vi\": \"Khi tôi đến, biển báo trên cửa ghi \\\"Chào đón khách hàng ghé qua không cần đặt lịch\\\", nhưng nhân viên lễ tân lại thẳng thừng nói với tôi rằng tôi sẽ phải đợi khoảng một tiếng cho lần cắt tóc của mình, mặc dù trong tiệm chỉ có một khách hàng khác và có đến ba thợ làm tóc ở đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The quality of the work was fine; the haircut was fairly priced at just $15, and I was happy with my standard men\'s cut.\", \"vi\": \"Chất lượng công việc thì ổn; kiểu tóc nam tiêu chuẩn của tôi có giá khá hợp lý chỉ 15 đô la, và tôi hài lòng với nó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The stylist, though, cut my hair without saying a word.\", \"vi\": \"Tuy nhiên, thợ cắt tóc lại cắt tóc cho tôi mà không nói một lời nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I understand that not everyone likes to make small talk, but I found my stylist\'s total silence to be rude.\", \"vi\": \"Tôi hiểu rằng không phải ai cũng thích trò chuyện phiếm, nhưng tôi thấy sự im lặng hoàn toàn của thợ cắt tóc cho tôi là bất lịch sự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"When she finished my haircut, she removed the haircutting cape without even offering to blow-dry my hair.\", \"vi\": \"Khi cô ấy cắt tóc xong cho tôi, cô ấy đã tháo áo choàng cắt tóc ra mà thậm chí không hề đề nghị sấy khô tóc cho tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"– Martin Silver, Bishopville\", \"vi\": \"– Martin Silver, Bishopville\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Calbo Cuts · 678 Seventh Street · Lamar, South Carolina · 29069\", \"vi\": \"Calbo Cuts · 678 Seventh Street · Lamar, South Carolina · 29069\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Martin Silver\", \"vi\": \"Martin Silver\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"51 Oak Street\", \"vi\": \"51 Oak Street\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Bishopville, South Carolina 29010\", \"vi\": \"Bishopville, South Carolina 29010\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Dear Mr. Silver,\", \"vi\": \"Ông Silver thân mến,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Thank you for taking the time to leave us a review.\", \"vi\": \"Cảm ơn ông đã dành thời gian để lại đánh giá cho chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We always try to provide the best service available.\", \"vi\": \"Chúng tôi luôn cố gắng cung cấp dịch vụ tốt nhất có thể.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"If you feel that any of our staff were unaccommodating or unprofessional, then I would like to hear more details regarding your complaint.\", \"vi\": \"Nếu ông cảm thấy bất kỳ nhân viên nào của chúng tôi không niềm nở hoặc thiếu chuyên nghiệp, thì tôi rất muốn lắng nghe thêm chi tiết liên quan đến khiếu nại của ông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Feel free to call me directly at 803-555-0110.\", \"vi\": \"Hãy thoải mái gọi trực tiếp cho tôi theo số 803-555-0110.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"At Calbo Cuts, we are serious about earning your continued business.\", \"vi\": \"Tại Calbo Cuts, chúng tôi rất coi trọng việc tiếp tục giữ vững sự ủng hộ của ông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I would be happy to schedule an appointment for you for a haircut and blow-dry with Marissa Lopez, as I believe she can provide you with the haircut experience you are looking for.\", \"vi\": \"Tôi rất vui lòng được sắp xếp một lịch hẹn cho ông để cắt tóc và sấy khô với Marissa Lopez, vì tôi tin rằng cô ấy có thể mang lại cho ông trải nghiệm cắt tóc mà ông đang tìm kiếm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"In addition, on your next visit to Calbo Cuts, we would like to offer you a complimentary bottle of our all-natural shampoo, one of our best-selling products.\", \"vi\": \"Ngoài ra, trong lần ghé thăm tiếp theo của ông tới Calbo Cuts, chúng tôi muốn gửi tặng ông một chai dầu gội hoàn toàn tự nhiên, một trong những sản phẩm bán chạy nhất của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"We hope you will come back to Calbo Cuts in the future whenever you need a trim.\", \"vi\": \"Chúng tôi hy vọng ông sẽ quay lại Calbo Cuts trong tương lai bất cứ khi nào ông có nhu cầu cắt tỉa tóc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Jenna Makowski\", \"vi\": \"Jenna Makowski\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Jenna Makowski\", \"vi\": \"Jenna Makowski\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Owner, Calbo Cuts\", \"vi\": \"Chủ tiệm Calbo Cuts\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '24aa7542-0d3c-42dd-9d07-26a565c2a723';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"A New Season at the Farmers Market\", \"vi\": \"Mùa giải mới tại Chợ nông sản\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Lee Valley Farmers Market is ____131___ exciting changes.\", \"vi\": \"Chợ nông sản Thung lũng Lee đang trải qua những thay đổi thú vị ____131___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"Jerry Carver, who has been the market\'s ___132____ for the last three years, stepped down last week.\", \"vi\": \"Jerry Carver, người đã giữ chức vụ ___132____ của khu chợ trong ba năm qua, đã từ chức vào tuần trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132]}, {\"en\": \"He was replaced by Paul Frankson, who oversaw operations at Garden Haven Farm.\", \"vi\": \"Ông đã được thay thế bởi Paul Frankson, người từng giám sát các hoạt động tại Trang trại Garden Haven.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The main market area is expanding from ten to fifteen booths to include more than just produce.\", \"vi\": \"Khu chợ chính đang được mở rộng từ mười lên mười lăm gian hàng để bao gồm nhiều mặt hàng hơn là chỉ nông sản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"___133____.\", \"vi\": \"___133____.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [133]}, {\"en\": \"There are also plans for a coffee stand and a craft section.\", \"vi\": \"Ngoài ra còn có các kế hoạch cho một quầy cà phê và một khu vực bán đồ thủ công.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"\\\"We really appreciate our loyal customers who have been purchasing produce from us for many years,\\\" said Frankson.\", \"vi\": \"\\\"Chúng tôi thực sự đánh giá cao những khách hàng trung thành, những người đã mua nông sản từ chúng tôi trong nhiều năm,\\\" Frankson cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"We hope that by offering a ____134___ range of products, we can encourage more people to shop locally.\\\"\", \"vi\": \"\\\"Chúng tôi hy vọng rằng bằng cách cung cấp một loạt các sản phẩm ____134___, chúng tôi có thể khuyến khích nhiều người mua sắm tại địa phương hơn.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [134]}, {\"en\": \"Lee Valley Farmers Market is open year-round, seven days a week, from 8:00 Α.Μ.\", \"vi\": \"Chợ nông sản Thung lũng Lee mở cửa quanh năm, bảy ngày một tuần, từ 8 giờ sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"to 6:00 P.M.\", \"vi\": \"đến 6 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '24bd6e2e-cd67-4f25-ba92-e9e033107a5e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"This notice ______[131] your reservation for two double rooms, with check-in on Sunday, March 5, and checkout on Thursday, March 9.\", \"vi\": \"Thông báo này ______[131] đặt phòng của quý khách gồm hai phòng đôi, nhận phòng vào Chủ Nhật, ngày 5 tháng 3, và trả phòng vào Thứ Năm, ngày 9 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [131]}, {\"en\": \"I see here that you have a special request for one extra set of blankets and two extra pillows in each room; please note ______[132] the items will be placed in each room, on top of the dresser.\", \"vi\": \"Tôi thấy ở đây quý khách có yêu cầu đặc biệt về một bộ chăn phụ và hai chiếc gối phụ trong mỗi phòng; xin lưu ý rằng ______[132] các vật dụng này sẽ được đặt trong mỗi phòng, ở phía trên tủ đựng đồ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [132]}, {\"en\": \"There will be no extra charge for this request.\", \"vi\": \"Sẽ không có phí phụ thu cho yêu cầu này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"______[133], check-in time is at 3:00 P.M., and checkout is at noon.\", \"vi\": \"______[133], thời gian nhận phòng là 3:00 chiều và thời gian trả phòng là vào buổi trưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [133]}, {\"en\": \"Some people wish to check in at an earlier time or check out at a later time.\", \"vi\": \"Một số người muốn nhận phòng sớm hơn hoặc trả phòng muộn hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[134].\", \"vi\": \"______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [134]}, {\"en\": \"This will help us ensure that we can accommodate your scheduling needs.\", \"vi\": \"Điều này sẽ giúp chúng tôi đảm bảo rằng chúng tôi có thể đáp ứng nhu cầu về thời gian của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We look forward to having you stay with us.\", \"vi\": \"Chúng tôi rất mong được đón tiếp quý khách lưu trú tại cơ sở của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '24dafd4e-d302-40fb-bcc6-548cbdf3d014';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Try our new product!\", \"vi\": \"Hãy thử sản phẩm mới của chúng tôi!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"A Great Way to Save Time\", \"vi\": \"Một Cách Tuyệt Vời Để Tiết Kiệm Thời Gian\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"With its stainless-steel finish and hidden control panel, the Kemper 25 is an elegant addition to any household.\", \"vi\": \"Với lớp hoàn thiện bằng thép không gỉ và bảng điều khiển ẩn, Kemper 25 là một sự bổ sung thanh lịch cho bất kỳ hộ gia đình nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"It can wash a full load in as little as one hour—no more waiting for clean dishes!\", \"vi\": \"Nó có thể rửa sạch một mẻ đầy chỉ trong vòng một giờ—không còn phải chờ đợi bát đĩa sạch!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"In addition to this speedy “One-Hour” setting, the Kemper 25 offers a “Normal” setting with high water efficiency, and a “Heavy” setting useful for items like greasy pots and pans.\", \"vi\": \"Ngoài chế độ “Một Giờ” nhanh chóng này, Kemper 25 còn cung cấp chế độ “Bình Thường” với hiệu quả sử dụng nước cao và chế độ “Nặng” hữu ích cho các vật dụng như nồi và chảo dính dầu mỡ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"No matter which setting you choose, the heated drying system ensures your dishes will be table-ready at the end of the cycle.\", \"vi\": \"Bất kể bạn chọn chế độ nào, hệ thống sấy khô bằng nhiệt đảm bảo bát đĩa của bạn sẽ sẵn sàng để sử dụng vào cuối chu trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Even large dishes such as serving platters can be cleaned with ease thanks to the Kemper 25’s removable top rack.\", \"vi\": \"Ngay cả những món ăn lớn như đĩa bày thức ăn cũng có thể được làm sạch dễ dàng nhờ giá trên có thể tháo rời của Kemper 25.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Visit your local Kemper dealership to learn more!\", \"vi\": \"Hãy ghé thăm đại lý Kemper địa phương của bạn để tìm hiểu thêm!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '25ba0041-9e75-4360-8d4e-70eddfc4fffb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Clearhold Coating is a newly developed, transparent waterproofing system that is superior to traditional pigmented coatings.\", \"vi\": \"Clearhold Coating là một hệ thống chống thấm trong suốt, mới được phát triển, vượt trội hơn so với các lớp phủ có màu truyền thống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Clearhold is ideal for application to masonry-block constructions—both new and existing—as well as to interior and exterior decorative elements.\", \"vi\": \"Clearhold rất lý tưởng để thi công lên các công trình bằng khối xây—cả mới lẫn cũ—cũng như các yếu tố trang trí nội và ngoại thất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Clearhold can also be applied to concrete and masonry subfloors, which is not possible with our competitors\' waterproofing materials.\", \"vi\": \"Clearhold cũng có thể được áp dụng cho sàn phụ bằng bê tông và khối xây, điều mà các vật liệu chống thấm của đối thủ cạnh tranh của chúng tôi không thể làm được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Clearhold will stop humidity from seeping up through subfloors and can be applied before installation of adhesive and floor coverings such as carpet, tile, laminate, or hardwood.\", \"vi\": \"Clearhold sẽ ngăn chặn độ ẩm thấm ngược qua sàn phụ và có thể được thi công trước khi lắp đặt keo dán và các vật liệu lót sàn như thảm, gạch men, sàn gỗ công nghiệp hoặc sàn gỗ tự nhiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Clearhold will be available in stores starting in January.\", \"vi\": \"Clearhold sẽ có mặt tại các cửa hàng bắt đầu từ tháng Giêng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"For more information, visit www.clearholdcoating.com.\", \"vi\": \"Để biết thêm thông tin, hãy truy cập www.clearholdcoating.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '25d68c95-915c-4d73-b4db-cbdd32f701f7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"This manual provides guidelines for inventory control at Malanta facilities.\", \"vi\": \"Sách hướng dẫn này cung cấp các nguyên tắc kiểm soát hàng tồn kho tại các cơ sở của Malanta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Our advancedmanufacturing procedures depend on ______[135] inventory control.\", \"vi\": \"Quy trình sản xuất tiên tiến của chúng tôi phụ thuộc vào việc kiểm soát hàng tồn kho ______[135].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [135]}, {\"en\": \"Only by maintaining a precise flow of inventory.\", \"vi\": \"Chỉ bằng cách duy trì dòng chảy hàng tồn kho chính xác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"______[136] minimize costs and ensure prompt shipments.\", \"vi\": \"______[136] giảm thiểu chi phí và đảm bảo các lô hàng giao đúng hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"To achieve this goal, we must avoid shortages.\", \"vi\": \"Để đạt được mục tiêu này, chúng ta phải tránh tình trạng thiếu hụt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"When stock is in the correct location at the time it is ordered, shipments are made at regular shipping costs and within estimated time frames .______[137] Therefore, the\", \"vi\": \"Khi hàng hóa nằm ở đúng vị trí vào thời điểm được đặt hàng, các lô hàng sẽ được thực hiện với chi phí vận chuyển thông thường và trong khung thời gian ước tính .______[137] Do đó, các\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [137]}, {\"en\": \"procedures in this manual must always be faithfully______[138].\", \"vi\": \"quy trình trong sổ tay này phải luôn được tuân thủ nghiêm ngặt ______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [138]}]' WHERE `id` = '25dc7287-8117-4a4b-8ad8-253eb3fcc420';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: melissa@grandgrainsbakery.com\", \"vi\": \"Từ: melissa@grandgrainsbakery.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: elinorotero@webmail.com\", \"vi\": \"Đến: elinorotero@webmail.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: October 28\", \"vi\": \"Ngày: 28 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Re: Desserts\", \"vi\": \"V/v: Các món tráng miệng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Otero,\", \"vi\": \"Kính gửi bà Otero,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I just followed up with our baker about your request to have an assortment of desserts instead of one large cake for the party you are hosting at your home on November 7.\", \"vi\": \"Tôi vừa trao đổi với thợ làm bánh của chúng tôi về yêu cầu của bạn là chọn một mâm các món tráng miệng đa dạng thay vì một chiếc bánh lớn cho bữa tiệc mà bạn tổ chức tại nhà vào ngày 7 tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We suggest ordering three dessert pieces per person.\", \"vi\": \"Chúng tôi đề xuất đặt ba phần tráng miệng cho mỗi người.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The cost for three desserts is between $10 and $12 per person.\", \"vi\": \"Chi phí cho ba món tráng miệng là từ 10 đến 12 đô la mỗi người.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Our most popular desserts are the mini cheesecakes, the berry tartlets, and the brownies.\", \"vi\": \"Các món tráng miệng phổ biến nhất của chúng tôi là bánh phô mai nhỏ, bánh tart quả mọng và bánh brownie.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I know you are using a separate caterer for the lunch, and they will help serve and clean up after the party.\", \"vi\": \"Tôi biết bạn đang sử dụng một dịch vụ tiệc riêng cho bữa trưa, và họ sẽ giúp phục vụ cũng như dọn dẹp sau bữa tiệc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"You also mentioned that you were considering whether to put the dessert table in your backyard or inside your house.\", \"vi\": \"Bạn cũng đề cập rằng bạn đang cân nhắc việc nên đặt bàn tráng miệng ở sân sau hay bên trong nhà.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Just keep in mind that if you order the cheesecakes, they should not be left out for more than two hours.\", \"vi\": \"Xin lưu ý rằng nếu bạn đặt bánh phô mai, chúng không nên để ngoài trời quá hai giờ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"If you give us very specific instructions about where to set up the desserts, our staff can leave them in the appropriate place without disturbing the party.\", \"vi\": \"Nếu bạn cung cấp cho chúng tôi các hướng dẫn rất cụ thể về nơi bày trí các món tráng miệng, nhân viên của chúng tôi có thể để chúng ở đúng vị trí mà không làm phiền bữa tiệc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Once you make your dessert choices, simply let us know how many guests you expect, and we can take care of the rest.\", \"vi\": \"Khi bạn đã chọn xong món tráng miệng, chỉ cần cho chúng tôi biết bạn dự kiến có bao nhiêu khách, và chúng tôi có thể lo phần còn lại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Melissa Luhya\", \"vi\": \"Melissa Luhya\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Grand Grains Bakery\", \"vi\": \"Tiệm bánh Grand Grains\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '2600a1a4-6509-4a0a-9952-1175af12dba9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Marcus Steuber [10:41 A.M.] Are we still planning to have the author video conference today?\", \"vi\": \"Marcus Steuber [10:41 A.M.] Chúng ta vẫn có kế hoạch tổ chức buổi hội thảo trực tuyến với tác giả vào ngày hôm nay chứ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I haven\'t yet received a meeting invitation.\", \"vi\": \"Tôi vẫn chưa nhận được lời mời họp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Brinda Rajan [10:42 A.M.] I do have the meeting on my calendar.\", \"vi\": \"Brinda Rajan [10:42 A.M.] Tôi có lịch cuộc họp này trong lịch của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Let me forward it to you; it appears our editorial assistant didn\'t include you.\", \"vi\": \"Để tôi chuyển tiếp nó cho bạn; có vẻ như trợ lý biên tập của chúng ta đã quên thêm bạn vào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Marcus Steuber [10:43 A.M.] Thanks, I just received it.\", \"vi\": \"Marcus Steuber [10:43 A.M.] Cảm ơn, tôi vừa nhận được nó rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The timing doesn\'t work for me, though.\", \"vi\": \"Tuy nhiên, thời gian đó lại không phù hợp với tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I have an appointment with Hazel Luong to discuss the printing issues at our Singapore plant.\", \"vi\": \"Tôi có cuộc hẹn với Hazel Luong để thảo luận về các vấn đề in ấn tại nhà máy ở Singapore của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Brinda Rajan [10:44 A.M.] Could you postpone that?\", \"vi\": \"Brinda Rajan [10:44 A.M.] Bạn có thể hoãn cuộc hẹn đó lại không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The new author we\'re working with really needs your guidance on the final book design and formatting.\", \"vi\": \"Tác giả mới mà chúng ta đang hợp tác thực sự cần sự hướng dẫn của bạn về thiết kế và định dạng sách hoàn chỉnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You\'re our most knowledgeable production editor.\", \"vi\": \"Bạn là biên tập viên sản xuất am hiểu nhất của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Marcus Steuber [10:45 A.M.] Let me check with my supervisor.\", \"vi\": \"Marcus Steuber [10:45 A.M.] Để tôi hỏi ý kiến người quản lý của tôi xem sao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I\'ll add Mr. Borg to our chat.\", \"vi\": \"Tôi sẽ thêm ông Borg vào đoạn chat của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Joshua Borg [10:47 A.M.] Hi, team.\", \"vi\": \"Joshua Borg [10:47 A.M.] Chào mọi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Marcus, you should prioritize your appointment with Hazel.\", \"vi\": \"Marcus, bạn nên ưu tiên cuộc hẹn với Hazel.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I\'ll be visiting the plant next week, and we need to have some viable solutions before then.\", \"vi\": \"Tôi sẽ đến thăm nhà máy vào tuần tới và chúng ta cần có một số giải pháp khả thi trước thời điểm đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Brinda Rajan [10:48 A.M.] OK, I\'ll contact Ms. Benoit to find out if she can meet later in the day, then.\", \"vi\": \"Brinda Rajan [10:48 A.M.] Được rồi, vậy tôi sẽ liên hệ với cô Benoit để xem liệu cô ấy có thể họp vào cuối ngày hôm nay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Marcus Steuber [10:48 A.M.] That would work.\", \"vi\": \"Marcus Steuber [10:48 A.M.] Như vậy thì được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I\'m free between 4 and 6 P.M.\", \"vi\": \"Tôi rảnh trong khoảng thời gian từ 4 đến 6 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '2661e08d-9af4-4c1f-921e-d80b345df81e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: noreply@vacationsiteseer.com\", \"vi\": \"Từ: noreply@vacationsiteseer.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: vneuman@gzetmail.com\", \"vi\": \"Đến: vneuman@gzetmail.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: July 16, 2:52 P.M.\", \"vi\": \"Ngày: 16 tháng 7, 2:52 Chiều\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Your upcoming trip\", \"vi\": \"Chủ đề: Chuyến đi sắp tới của bạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Mr. Neuman:\", \"vi\": \"Ông Neuman:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Your trip to Milan is only a week away.\", \"vi\": \"Chuyến đi của bạn đến Milan chỉ còn một tuần nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Your room at the Classico Hotel has been confirmed.\", \"vi\": \"Phòng của bạn tại Khách sạn Classico đã được xác nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Check-in is on July 23 at 2 P.M., and checkout is on July 28 at 11 A.M. There is no need to pay now, as payment is not required until you have checked out.\", \"vi\": \"Nhận phòng vào ngày 23 tháng 7 lúc 2 giờ chiều, và trả phòng vào ngày 28 tháng 7 lúc 11 giờ sáng. Không cần thanh toán ngay bây giờ, vì thanh toán chỉ được yêu cầu sau khi bạn đã trả phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We urge you to plan ahead regarding car rentals.\", \"vi\": \"Chúng tôi khuyến khích bạn lên kế hoạch trước cho việc thuê xe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"As a Vacation Siteseer customer, you are entitled to a discount of 20% if you book your car now.\", \"vi\": \"Là khách hàng của Vacation Siteseer, bạn được hưởng chiết khấu 20% nếu đặt xe ngay bây giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Our car rental partners are offering this special deal only until July 20, so do not wait.\", \"vi\": \"Các đối tác cho thuê xe của chúng tôi chỉ đưa ra ưu đãi đặc biệt này cho đến ngày 20 tháng 7, vì vậy đừng chần chừ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Thank you for choosing Vacation Siteseer to book your stay in Milan.\", \"vi\": \"Cảm ơn bạn đã chọn Vacation Siteseer để đặt kỳ nghỉ của bạn tại Milan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Enjoy your journey!\", \"vi\": \"Chúc bạn có một chuyến đi vui vẻ!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Vacation Siteseer Team\", \"vi\": \"Đội ngũ Vacation Siteseer\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '26a1f058-786e-4482-9171-1933aca6388a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"25 May\", \"vi\": \"Ngày 25 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Ms. Deborah Kiernan\", \"vi\": \"Bà Deborah Kiernan\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Sonicboom Distribution Agency\", \"vi\": \"Hãng Phân phối Sonicboom\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"84 Arthur Road\", \"vi\": \"84 Arthur Road\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"London N7 6DR\", \"vi\": \"London N7 6DR\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Kiernan:\", \"vi\": \"Kính gửi Bà Kiernan,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Earthsky Films International is seeking a distributor for our latest production, Project Aerial.\", \"vi\": \"Earthsky Films International đang tìm kiếm nhà phân phối cho tác phẩm mới nhất của chúng tôi, Project Aerial.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Having premiered in April at the North Brabant Film Festival in Eindhoven, the Netherlands, the film received strong reviews from critics and was honored with the Diamond Pen Award for best screenplay.\", \"vi\": \"Sau khi công chiếu vào tháng Tư tại Liên hoan Phim Bắc Brabant ở Eindhoven, Hà Lan, bộ phim đã nhận được nhiều đánh giá tích cực từ các nhà phê bình và vinh dự nhận Giải thưởng Bút Kim Cương cho kịch bản xuất sắc nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Our film, Project Aerial, examines an exciting period in aviation history that began more than 150 years ago.\", \"vi\": \"Bộ phim của chúng tôi, Project Aerial, xem xét một giai đoạn thú vị trong lịch sử hàng không bắt đầu từ hơn 150 năm trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The aviation industry owes its development to a number of brilliant and enterprising people.\", \"vi\": \"Ngành công nghiệp hàng không mang ơn sự phát triển của mình đối với nhiều người xuất chúng và đầy tinh thần doanh nhân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The film highlights the major innovators as well as those who were lesser known.\", \"vi\": \"Bộ phim làm nổi bật những nhà đổi mới lớn cũng như những người ít được biết đến hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The two lead roles are played by Winston Halsey and Virgil Golding, figures that are familiar to international audiences.\", \"vi\": \"Hai vai diễn chính do Winston Halsey và Virgil Golding đảm nhận, những gương mặt quen thuộc với khán giả quốc tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Mr. Golding is known for his role in, among others, The Rigby Conspiracy, and Mr. Halsey is recognized for his performance in Whereabouts Unknown.\", \"vi\": \"Ông Golding được biết đến qua vai diễn trong bộ phim The Rigby Conspiracy, trong số những phim khác, và ông Halsey được công nhận qua màn thể hiện trong Whereabouts Unknown.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"If you are interested in marketing our film, I would be happy to e-mail you a secure link so that you can view it.\", \"vi\": \"Nếu quý vị quan tâm đến việc tiếp thị bộ phim của chúng tôi, tôi rất sẵn lòng gửi email cho quý vị một đường liên kết bảo mật để quý vị có thể xem nó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I hope to hear from you soon.\", \"vi\": \"Tôi hy vọng sớm nhận được phản hồi từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Jayesh Chaudhari, CEO\", \"vi\": \"Jayesh Chaudhari, Giám đốc điều hành\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Earthsky Films International\", \"vi\": \"Earthsky Films International\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '26d6bf36-c631-4185-934f-a88d526449d0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Valeria Sanchez <vsanchez@mellowbayresort.com>\", \"vi\": \"Từ: Valeria Sanchez <vsanchez@mellowbayresort.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Seo-Jun Hak <seo-junhak2390@amail.com>\", \"vi\": \"Đến: Seo-Jun Hak <seo-junhak2390@amail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Arrival at Mellow Bay Resort\", \"vi\": \"Chủ đề: Đến Khu nghỉ dưỡng Mellow Bay\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: June 4\", \"vi\": \"Ngày: Ngày 4 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Hak,\", \"vi\": \"Ông Hak thân mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Your stay at Mellow Bay Resort is coming soon!\", \"vi\": \"Kỳ nghỉ của ông tại Khu nghỉ dưỡng Mellow Bay sắp đến gần!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The check-in time is between 3:00 p.m. and 8:00 p.m. Please call us at (305) 555-0125 if you plan to arrive before or after these hours.\", \"vi\": \"Thời gian nhận phòng là từ 3:00 chiều đến 8:00 tối. Vui lòng gọi cho chúng tôi theo số (305) 555-0125 nếu ông dự định đến trước hoặc sau những giờ này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Your room may be given to another guest if you arrive after 8:00 p.m. without ____135____ .\", \"vi\": \"Phòng của ông có thể sẽ được giao cho vị khách khác nếu ông đến sau 8:00 tối mà không ____135____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [135]}, {\"en\": \"When checking in, you will receive complimentary tickets for the breakfast buffet, ____136____ is located down the hall from the lobby.\", \"vi\": \"Khi nhận phòng, ông sẽ nhận được các vé ăn sáng tự chọn miễn phí, ____136____ nằm dọc theo hành lang từ sảnh đợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [136]}, {\"en\": \"You may also want to make dinner reservations at Lookout Restaurant on the top floor of the hotel with ____137____ views of the ocean and town.\", \"vi\": \"Ông cũng có thể muốn đặt chỗ ăn tối tại Nhà hàng Lookout trên tầng cao nhất của khách sạn với ____137____ nhìn ra đại dương và thị trấn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [137]}, {\"en\": \"Also be sure to stop at our guest services desk for information about local attractions.\", \"vi\": \"Ngoài ra, hãy chắc chắn ghé qua quầy dịch vụ khách hàng của chúng tôi để biết thông tin về các điểm tham quan địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"____138____ .\", \"vi\": \"____138____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [138]}, {\"en\": \"There is so much in the bay area to explore!\", \"vi\": \"Có rất nhiều điều ở khu vực vịnh đang chờ đón bạn khám phá!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We look forward to welcoming you as our guest.\", \"vi\": \"Chúng tôi rất mong được chào đón ông đến với tư cách là khách của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Valeria\", \"vi\": \"Valeria\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '26dfc019-b549-4534-807a-797e907ccc26';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Staff\", \"vi\": \"Đến: Toàn thể nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Liza Pacurar\", \"vi\": \"Từ: Liza Pacurar\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Special issue\", \"vi\": \"Chủ đề: Số đặc biệt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: November 12\", \"vi\": \"Ngày: 12 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear All,\", \"vi\": \"Kính gửi toàn thể,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Once again, I\'d like to express my gratitude for the great efforts you have made to help us meet the publication deadline for our annual special issue of Best Design Insights magazine.\", \"vi\": \"Một lần nữa, tôi muốn bày tỏ lòng biết ơn đối với những nỗ lực tuyệt vời mà các bạn đã bỏ ra để giúp chúng tôi hoàn thành thời hạn xuất bản cho số đặc biệt hàng năm của tạp chí Best Design Insights.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"What follows is a summary of the main points we discussed at today\'s meeting.\", \"vi\": \"Dưới đây là tóm tắt các điểm chính chúng ta đã thảo luận trong cuộc họp hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"• Karine Xu reported that advertisers have expressed heightened interest in the issue, so the deadline for submitting advertisements will be extended one week.\", \"vi\": \"• Karine Xu báo cáo rằng các nhà quảng cáo đã bày tỏ sự quan tâm cao hơn đối với số này, vì vậy thời hạn nộp quảng cáo sẽ được gia hạn thêm một tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"• For this issue, we will use our alternate printing service, Sklarr Press, to meet our tight delivery deadline.\", \"vi\": \"• Đối với số này, chúng ta sẽ sử dụng dịch vụ in ấn thay thế của mình, Sklarr Press, để đáp ứng thời hạn giao hàng gấp rút của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"• We\'ve gotten approval to increase the budget so that Mark Janskee\'s team can work overtime to review the pages with special layout components, in particular multiple photographs arranged in a photomontage.\", \"vi\": \"• Chúng ta đã nhận được sự chấp thuận để tăng ngân sách để đội của Mark Janskee có thể làm thêm giờ để xem xét các trang có các thành phần bố cục đặc biệt, đặc biệt là nhiều ảnh được sắp xếp theo kiểu ghép ảnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Mark will then submit a custom design request to the printer.\", \"vi\": \"Sau đó, Mark sẽ gửi yêu cầu thiết kế tùy chỉnh cho nhà in.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"• The draft of the special issue is longer than we want.\", \"vi\": \"• Bản nháp của số đặc biệt dài hơn chúng ta mong muốn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"So, we reduced the page total by condensing the text of our interview with animation artist Bret Lusk.\", \"vi\": \"Vì vậy, chúng tôi đã giảm tổng số trang bằng cách cô đọng nội dung bài phỏng vấn của chúng tôi với nghệ sĩ hoạt hình Bret Lusk.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Liza Pacurar, Editor\", \"vi\": \"Liza Pacurar, Biên tập viên\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Best Design Publications\", \"vi\": \"Best Design Publications\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To: Liza Pacurar\", \"vi\": \"Đến: Liza Pacurar\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"From: Karine Xu\", \"vi\": \"Từ: Karine Xu\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Subject: RE: Special issue\", \"vi\": \"Chủ đề: V/v: Số đặc biệt\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Date: November 14\", \"vi\": \"Ngày: 14 tháng 11\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Hi Liza,\", \"vi\": \"Chào Liza,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I\'m happy with the plan to use Sklarr Press to print our magazine\'s special issue, just as we did last year.\", \"vi\": \"Tôi hài lòng với kế hoạch sử dụng Sklarr Press để in số đặc biệt của tạp chí, giống như chúng ta đã làm năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I\'m confident they can meet our publication deadline.\", \"vi\": \"Tôi tin rằng họ có thể đáp ứng thời hạn xuất bản của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Our customization request will probably incur an extra fee, but any added expense should be offset by the expected boost in advertising revenue.\", \"vi\": \"Yêu cầu tùy chỉnh của chúng tôi có thể sẽ phát sinh thêm phí, nhưng bất kỳ chi phí bổ sung nào cũng sẽ được bù đắp bởi sự gia tăng doanh thu quảng cáo dự kiến.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Next on my agenda is to remind our subscribers that they have this extra issue to look forward to.\", \"vi\": \"Tiếp theo trong danh sách công việc của tôi là nhắc nhở các thuê bao của chúng ta rằng họ có số đặc biệt này để mong đợi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I\'ll let them know via e-mail.\", \"vi\": \"Tôi sẽ thông báo cho họ qua e-mail.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Karine Xu, Marketing Coordinator\", \"vi\": \"Karine Xu, Điều phối viên Tiếp thị\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Best Design Publications\", \"vi\": \"Best Design Publications\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '2726d7bc-6e58-48c3-b99b-66671e11839c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Memo\", \"vi\": \"Thông báo nội bộ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All employees\", \"vi\": \"Đến: Tất cả nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Marcus Sindhu, IT Director\", \"vi\": \"Từ: Marcus Sindhu, Giám đốc Công nghệ Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: June 1\", \"vi\": \"Ngày: 1 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Web site maintenance\", \"vi\": \"Chủ đề: Bảo trì trang web\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Please note that routine maintenance of the server will be performed this weekend, affecting the content of our company Web site.\", \"vi\": \"Xin lưu ý rằng việc bảo trì định kỳ máy chủ sẽ được thực hiện vào cuối tuần này, gây ảnh hưởng đến nội dung trang web của công ty chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The server — [135] — down for approximately eight hours from 11 P.M. on Saturday, June 6, to 7 A.M. on Sunday, June 7.\", \"vi\": \"Máy chủ sẽ — [135] — ngừng hoạt động trong khoảng tám giờ từ 11 giờ tối thứ Bảy, ngày 6 tháng 6, đến 7 giờ sáng Chủ nhật, ngày 7 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [135]}, {\"en\": \"— [136] — this time, access to the Web site will be restricted, and e-mail delivery will be paused.\", \"vi\": \"— [136] — thời gian này, quyền truy cập vào trang web sẽ bị hạn chế và việc gửi nhận email sẽ tạm dừng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [136]}, {\"en\": \"— [137] —.\", \"vi\": \"— [137] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [137]}, {\"en\": \"Once the server is back up, please take some time to explore the — [138] — features on the Web site.\", \"vi\": \"Khi máy chủ hoạt động trở lại, vui lòng dành chút thời gian để khám phá các tính năng — [138] — trên trang web.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [138]}, {\"en\": \"These include a new scheduler and a more user-friendly search tool.\", \"vi\": \"Các tính năng này bao gồm một lịch trình mới và công cụ tìm kiếm thân thiện với người dùng hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Your patience is greatly appreciated.\", \"vi\": \"Chúng tôi rất biết ơn sự kiên nhẫn của các bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Please direct any questions to me.\", \"vi\": \"Vui lòng gửi mọi thắc mắc trực tiếp cho tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '276c1134-0826-431e-ac62-c0230fe6a3fa';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Flavor - Designed for Ages - Size\", \"vi\": \"Hương vị - Thiết kế theo độ tuổi - Kích cỡ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Peach - 18 months to 3 years - 5 and 6 ounce\", \"vi\": \"Đào - 18 tháng đến 3 tuổi - 5 và 6 ounce\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Strawberry - 3 to 4 years - 4, 5, and 6 ounce\", \"vi\": \"Dâu - 3 đến 4 tuổi - 4, 5 và 6 ounce\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Vanilla - 4 to 7 years - 4 and 5 ounce\", \"vi\": \"Vani - 4 đến 7 tuổi - 4 và 5 ounce\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Mint - 7 years and up - 4 and 6 ounce\", \"vi\": \"Bạc hà - 7 tuổi trở lên - 4 và 6 ounce\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"https://www.aci.com/childrens-oral-care/availableoptions\", \"vi\": \"https://www.aci.com/childrens-oral-care/availableoptions\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Available Options - Toothbrushes - Mouthwash - Other Products\", \"vi\": \"Các Lựa Chọn Có Sẵn - Bàn chải đánh răng - Nước súc miệng - Các Sản Phẩm Khác\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Artemis Consolidated Industries (ACI) is the country\'s leading manufacturer of a range of oral hygiene products for children and adults.\", \"vi\": \"Artemis Consolidated Industries (ACI) là nhà sản xuất hàng đầu cả nước về các sản phẩm vệ sinh răng miệng dành cho trẻ em và người lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Among our best sellers is Oraglitz, the nation\'s most popular children\'s toothpaste.\", \"vi\": \"Trong số các sản phẩm bán chạy nhất của chúng tôi là Oraglitz, loại kem đánh răng trẻ em phổ biến nhất cả nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"It has won various industry awards, including the Product Excellence Prize.\", \"vi\": \"Sản phẩm đã giành được nhiều giải thưởng ngành, bao gồm cả Giải thưởng Sản phẩm Xuất sắc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"In addition to being available on this Web site, Oraglitz can also be purchased at supermarkets, pharmacies, and health food stores nationwide.\", \"vi\": \"Ngoài việc có sẵn trên trang web này, Oraglitz còn có thể được mua tại các siêu thị, nhà thuốc và cửa hàng thực phẩm tốt cho sức khỏe trên toàn quốc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Some Basic Facts About Oraglitz\", \"vi\": \"Một số Thông Tin Cơ Bản Về Oraglitz\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '277ffb71-5651-43ec-bc1e-6aa579060d5e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"JUNE\", \"vi\": \"THÁNG SÁU\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Monday\\n7 - Tuesday\\n8 - Wednesday\\n9 - Thursday\\n10 - Friday\\n11\", \"vi\": \"Thứ Hai\\n7 - Thứ Ba\\n8 - Thứ Tư\\n9 - Thứ Năm\\n10 - Thứ Sáu\\n11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"9:00 A.M. - Out of office (traveling from eyewear seminar in Boston) - Data security training - Out of office (personal appointments) - Weekly planning and review\", \"vi\": \"9:00 SÁNG - Ngoài văn phòng (đi dự hội thảo kính mắt tại Boston) - Đào tạo bảo mật dữ liệu - Ngoài văn phòng (lịch hẹn cá nhân) - Lập kế hoạch và xem xét hàng tuần\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"10:00 A.M. - Budget meeting - E-mail review and cleanup\", \"vi\": \"10:00 SÁNG - Họp ngân sách - Xem lại và dọn dẹp email\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"11:00 A.M.\", \"vi\": \"11:00 SÁNG\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"12:00 P.M.\", \"vi\": \"12:00 TRƯA\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"1:00 P.M. - Applicant interviews - Human resources meeting - Sales review meeting\", \"vi\": \"1:00 CHIỀU - Phỏng vấn ứng viên - Họp nhân sự - Họp xem xét bán hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"2:00 P.M. - Technology updates\", \"vi\": \"2:00 CHIỀU - Cập nhật công nghệ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"3:00 P.M.\", \"vi\": \"3:00 CHIỀU\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To: Cindy Weaver\", \"vi\": \"Đến: Cindy Weaver\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"From: Sarah Moreland\", \"vi\": \"Từ: Sarah Moreland\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Date: June 7, 6:31 A.M.\", \"vi\": \"Ngày: 7 tháng 6, 6:31 SÁNG\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Subject: Delayed return\", \"vi\": \"Chủ đề: Trở về trễ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Hi, Cindy,\", \"vi\": \"Chào Cindy,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"My return flight has just been canceled, and the next available one is tomorrow morning.\", \"vi\": \"Chuyến bay trở về của tôi vừa bị hủy, và chuyến sớm nhất có sẵn là vào sáng mai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I expect to return to the office just in time for the data security training, but I need your help rearranging my calendar.\", \"vi\": \"Tôi dự kiến sẽ trở lại văn phòng kịp buổi đào tạo bảo mật dữ liệu, nhưng tôi cần bạn giúp sắp xếp lại lịch của tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"• The budget meeting needs to occur this week, so please contact the team to schedule another time.\", \"vi\": \"• Cuộc họp ngân sách cần diễn ra trong tuần này, vì vậy vui lòng liên hệ với nhóm để lên lịch thời gian khác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"You can use my Friday morning planning time but not my personal time on Thursday morning.\", \"vi\": \"Bạn có thể sử dụng thời gian lập kế hoạch sáng thứ Sáu của tôi nhưng không phải thời gian cá nhân của tôi vào sáng thứ Năm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"• I\'d like to interview our selected applicants later this week, maybe on Friday afternoon if the candidates are amenable; please call them to check.\", \"vi\": \"• Tôi muốn phỏng vấn các ứng viên đã chọn vào cuối tuần này, có thể vào chiều thứ Sáu nếu các ứng viên đồng ý; vui lòng gọi cho họ để kiểm tra.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"In connection with this, I need to meet with human resources staff only after all the interviews are done; please reschedule that meeting to sometime early next week.\", \"vi\": \"Liên quan đến việc này, tôi cần gặp nhân viên nhân sự chỉ sau khi tất cả các cuộc phỏng vấn hoàn tất; vui lòng dời cuộc họp đó sang đầu tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"• I have some important news for the marketing team about new eyewear promoted at the seminar.\", \"vi\": \"• Tôi có một số tin tức quan trọng cho đội ngũ marketing về kính mắt mới được quảng bá tại hội thảo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Could you see if they can meet on Wednesday afternoon?\", \"vi\": \"Bạn có thể xem liệu họ có thể gặp vào chiều thứ Tư không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Many thanks,\", \"vi\": \"Cảm ơn rất nhiều,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Sarah Moreland\", \"vi\": \"Sarah Moreland\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"To: Sarah Moreland\", \"vi\": \"Đến: Sarah Moreland\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"From: Cindy Weaver\", \"vi\": \"Từ: Cindy Weaver\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date: June 7, 2:31 P.M.\", \"vi\": \"Ngày: 7 tháng 6, 2:31 CHIỀU\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Subject: Re: Delayed return\", \"vi\": \"Chủ đề: V/v: Trở về trễ\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Good afternoon, Ms. Moreland,\", \"vi\": \"Chào buổi chiều, cô Moreland,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I have been working on your calendar per your request.\", \"vi\": \"Tôi đã xử lý lịch của cô theo yêu cầu của cô.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I have rescheduled your budget meeting for 10:00 A.M. on Friday.\", \"vi\": \"Tôi đã sắp xếp lại cuộc họp ngân sách của cô vào 10:00 SÁNG thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Eric Kim says that he has no critical new information to share with you at his 2:00 P.M. meeting with you on Friday, so I can postpone that.\", \"vi\": \"Eric Kim nói rằng anh ấy không có thông tin mới quan trọng nào để chia sẻ với cô trong cuộc họp lúc 2:00 CHIỀU với cô vào thứ Sáu, vì vậy tôi có thể hoãn cuộc họp đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Fortunately, all job candidates have agreed to have their interviews on Friday afternoon, and I have moved your human resources meeting to 9:00 A.M. next Monday.\", \"vi\": \"May mắn thay, tất cả các ứng viên đã đồng ý phỏng vấn vào chiều thứ Sáu, và tôi đã chuyển cuộc họp nhân sự của cô sang 9:00 SÁNG thứ Hai tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"I have been unable to get through to every marketing team member to set up a meeting to discuss the new eyewear.\", \"vi\": \"Tôi đã không thể liên lạc được với mọi thành viên của đội ngũ marketing để sắp xếp một cuộc họp thảo luận về kính mắt mới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"I will keep trying.\", \"vi\": \"Tôi sẽ tiếp tục cố gắng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Cindy\", \"vi\": \"Cindy\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}]' WHERE `id` = '27853daa-bb57-4aa8-9277-a73211457cca';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Christie Moroff (9:47 A.M.)\", \"vi\": \"Christie Moroff (9:47 Sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Good morning, Ren.\", \"vi\": \"Chào buổi sáng, Ren.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I just stopped by your office.\", \"vi\": \"Tôi vừa ghé qua văn phòng của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Ren Nomura (9:48 A.M.)\", \"vi\": \"Ren Nomura (9:48 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Then you already know that I am not there today.\", \"vi\": \"Vậy là bạn đã biết hôm nay tôi không có ở đó rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Christie Moroff (9:48 A.M.)\", \"vi\": \"Christie Moroff (9:48 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Yes, your new office mate—I can\'t remember her name—told me that you just started working remotely on Tuesdays.\", \"vi\": \"Vâng, bạn cùng phòng mới của bạn — tôi không nhớ tên cô ấy — đã nói với tôi rằng bạn bắt đầu làm việc từ xa vào các ngày thứ Ba.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I was looking for some empty binders.\", \"vi\": \"Tôi đang tìm một vài bìa hồ sơ trống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Ren Nomura (9:49 A.M.)\", \"vi\": \"Ren Nomura (9:49 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"That\'s Cheryl.\", \"vi\": \"Đó là Cheryl.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I thought you had already met her.\", \"vi\": \"Tôi tưởng bạn đã gặp cô ấy rồi chứ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Are there any binders in the supply closet?\", \"vi\": \"Có bìa hồ sơ nào trong tủ đồ dùng không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Christie Moroff (9:50 A.M.)\", \"vi\": \"Christie Moroff (9:50 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"No, I just looked.\", \"vi\": \"Không, tôi vừa kiểm tra rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Frank has ordered some more, but they won\'t be in until next week.\", \"vi\": \"Frank đã đặt thêm một ít, nhưng chúng sẽ không về cho đến tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I need two or three of them now.\", \"vi\": \"Tôi cần hai hoặc ba cái bây giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Ren Nomura (9:51 A.M.)\", \"vi\": \"Ren Nomura (9:51 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Check with Cheryl.\", \"vi\": \"Hãy hỏi Cheryl.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"She is really helpful.\", \"vi\": \"Cô ấy rất nhiệt tình giúp đỡ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Christie Moroff (9:52 A.M.)\", \"vi\": \"Christie Moroff (9:52 Sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I will.\", \"vi\": \"Tôi sẽ làm vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '2808deb1-db2d-47d7-b112-9220bdd653e9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Aussie Coffee Fair This Weekend\", \"vi\": \"Hội Chợ Cà Phê Úc Cuối Tuần Này\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"SYDNEY (4 June)—Coffee will be the main attraction this weekend at the Aussie Coffee Fair hosted by Homewares, the country’s top kitchen appliance manufacturer.\", \"vi\": \"SYDNEY (4 tháng 6)—Cà phê sẽ là điểm thu hút chính vào cuối tuần này tại Hội Chợ Cà Phê Úc do Homewares, nhà sản xuất thiết bị nhà bếp hàng đầu cả nước, tổ chức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The event will be held at the Harbour Expo Centre.\", \"vi\": \"Sự kiện sẽ được tổ chức tại Trung Tâm Triển Lãm Harbour.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The two-day event will feature a variety of coffee-oriented presentations by coffee growers and roasters, food writers, makers of kitchen equipment, and chefs.\", \"vi\": \"Sự kiện kéo dài hai ngày sẽ có nhiều bài thuyết trình về cà phê của các nhà trồng và rang xay cà phê, các nhà văn ẩm thực, các nhà sản xuất thiết bị nhà bếp và các đầu bếp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Foods and beverages will be available to view, taste, and buy at booths throughout the centre.\", \"vi\": \"Thực phẩm và đồ uống sẽ có sẵn để xem, nếm thử và mua tại các gian hàng trong trung tâm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Sessions will feature demonstrations on cooking with coffee and tips for brewing the best cup of coffee, as well as information on nonfood uses for coffee.\", \"vi\": \"Các buổi hội thảo sẽ có các buổi trình diễn về nấu ăn với cà phê và các mẹo pha tách cà phê ngon nhất, cũng như thông tin về các công dụng khác của cà phê ngoài thực phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In addition, culinary experts will be on hand to meet with coffee enthusiasts for discussions designed to help them create a true coffeehouse experience in their own homes.\", \"vi\": \"Ngoài ra, các chuyên gia ẩm thực sẽ có mặt để trao đổi với những người đam mê cà phê nhằm giúp họ tạo ra trải nghiệm cà phê đích thực ngay tại nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Entry to the Aussie Coffee Fair is free.\", \"vi\": \"Vào cửa Hội Chợ Cà Phê Úc miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"However, registration is required as space is limited.\", \"vi\": \"Tuy nhiên, cần phải đăng ký vì số lượng chỗ có hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"For information and to register online, go to www.aussiecoffeefair.com.\", \"vi\": \"Để biết thông tin và đăng ký trực tuyến, hãy truy cập www.aussiecoffeefair.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '285a5a8d-834c-4647-a146-12ed3f0a276c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Philadelphia\'s PH11-TV invites you to download our new traffic app for your mobile device.\", \"vi\": \"Đài PH11-TV của Philadelphia kính mời bạn tải xuống ứng dụng giao thông mới của chúng tôi cho thiết bị di động của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The app ______[131] the station\'s traffic coverage.\", \"vi\": \"Ứng dụng này ______[131] tin tức cập nhật giao thông của đài.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"Use it to get traffic news if you are away from your television and are unable to watch our traffic reports.\", \"vi\": \"Hãy sử dụng nó để nhận thông tin giao thông nếu bạn đang ở xa ti vi và không thể xem các bản tin giao thông của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"______[132].\", \"vi\": \"______[132].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [132]}, {\"en\": \"Plus, you can program your daily commute into the app to receive personalized alerts ______[133] on your mobile device when any traffic-related event occurs along your route.\", \"vi\": \"Ngoài ra, bạn có thể lập trình lộ trình đi lại hàng ngày của mình vào ứng dụng để nhận các cảnh báo cá nhân hóa ______[133] trên thiết bị di động khi có bất kỳ sự cố giao thông nào xảy ra dọc theo tuyến đường của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [133]}, {\"en\": \"Avoid traffic delays by downloading the PH11-TV traffic app today, ______[134] tune in to our live broadcast beginning at 5:00 A.M. and 4:00 P.M. daily.\", \"vi\": \"Tránh tình trạng chậm trễ do giao thông bằng cách tải xuống ứng dụng giao thông của PH11-TV ngay hôm nay, ______[134] theo dõi chương trình phát sóng trực tiếp của chúng tôi bắt đầu từ 5:00 sáng và 4:00 chiều hàng ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [134]}]' WHERE `id` = '287663bb-d53f-469d-a13b-9efcfb1426f1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Brice\'s Ice Creamery\", \"vi\": \"Tiệm Kem Brice\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"June 29, 2:02 P.M.\", \"vi\": \"Ngày 29 tháng 6, 2:02 Chiều\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Thank you, Nathan Thielen, for joining Brice\'s Ice Creamery\'s rewards program.\", \"vi\": \"Cảm ơn anh Nathan Thielen đã tham gia chương trình khách hàng thân thiết của Tiệm Kem Brice.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"You have earned your first points just by signing up for our program.\", \"vi\": \"Anh đã kiếm được những điểm đầu tiên chỉ bằng cách đăng ký chương trình của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"For every $1.00 you spend in one of our ice cream shops, you earn 1 point.\", \"vi\": \"Với mỗi 1 đô la Mỹ anh chi tiêu tại một trong những tiệm kem của chúng tôi, anh sẽ kiếm được 1 điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Every 100 points you earn can be redeemed for $5.00 off your purchase of ice cream or store merchandise, including T-shirts and tote bags.\", \"vi\": \"Cứ mỗi 100 điểm anh kiếm được có thể đổi lấy phiếu giảm giá 5 đô la Mỹ cho lần mua kem hoặc hàng hóa của cửa hàng, bao gồm áo phông và túi vải.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"You are even entitled to a free scoop at any Brice\'s Ice Creamery on your birthday.\", \"vi\": \"Anh còn được hưởng một phần kem miễn phí tại bất kỳ Tiệm Kem Brice nào vào ngày sinh nhật của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You have earned: 20 points.\", \"vi\": \"Anh đã kiếm được: 20 điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"You are 80 points away from earning your next reward.\", \"vi\": \"Anh còn thiếu 80 điểm nữa để nhận phần thưởng tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '2877930a-7b30-48fe-9036-a9e3081cea1c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"*E-mail*\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: teamleaders@carfield.co.uk\", \"vi\": \"Đến: teamleaders@carfield.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: fjacobs@carfield.co.uk\", \"vi\": \"Từ: fjacobs@carfield.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Workshops\", \"vi\": \"Chủ đề: Các buổi hội thảo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Date: 13 November\", \"vi\": \"Ngày: 13 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Team Leaders,\", \"vi\": \"Kính gửi các Trưởng nhóm,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thanks to you and your team members for attending our latest monthly workshop last week.\", \"vi\": \"Xin cảm ơn bạn và các thành viên trong nhóm đã tham dự buổi hội thảo hàng tháng gần đây nhất của chúng tôi vào tuần trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"These workshops are a key feature of our employee training program, as we consider it fundamental that our employees continue to learn new skills and perfect existing ones.\", \"vi\": \"Các buổi hội thảo này là một phần quan trọng trong chương trình đào tạo nhân viên của chúng tôi, vì chúng tôi coi việc nhân viên tiếp tục học hỏi các kỹ năng mới và hoàn thiện các kỹ năng hiện có là điều cơ bản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I know everyone has already completed their workshop evaluations, but we would like to obtain some more specific feedback to ensure that interesting and instructive workshops continue to be offered.\", \"vi\": \"Tôi biết mọi người đã hoàn thành đánh giá hội thảo của mình, nhưng chúng tôi muốn thu thập thêm phản hồi cụ thể để đảm bảo rằng các buổi hội thảo thú vị và mang tính hướng dẫn sẽ tiếp tục được cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please answer the following questions.\", \"vi\": \"Vui lòng trả lời các câu hỏi sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"• Were the exercises presented at the workshop related to employees\' responsibilities?\", \"vi\": \"• Các bài tập được trình bày tại hội thảo có liên quan đến trách nhiệm công việc của nhân viên không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Have your team members been using the ideas presented?\", \"vi\": \"Các thành viên trong nhóm của bạn đã áp dụng những ý tưởng được trình bày chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"• What, if anything, would you leave out in future workshops?\", \"vi\": \"• Bạn sẽ loại bỏ nội dung gì, nếu có, trong các buổi hội thảo tương lai?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"What could be done better?\", \"vi\": \"Có thể cải thiện những gì?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"• Were the facilitators knowledgeable and engaging?\", \"vi\": \"• Những người điều phối có kiến thức và lôi cuốn không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Do you think your team would respond well to the same facilitators for other workshops?\", \"vi\": \"Bạn có nghĩ rằng nhóm của bạn sẽ phản hồi tốt với cùng những người điều phối đó cho các hội thảo khác không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Your perspectives on our workshops are invaluable.\", \"vi\": \"Quan điểm của bạn về các buổi hội thảo của chúng tôi là vô giá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We would appreciate a response by the end of this week, as we are planning to discuss any information you can provide at our next management meeting next Tuesday.\", \"vi\": \"Chúng tôi sẽ đánh giá cao nếu nhận được phản hồi trước cuối tuần này, vì chúng tôi dự định thảo luận về bất kỳ thông tin nào bạn có thể cung cấp tại cuộc họp quản lý tiếp theo vào thứ Ba tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thanks for your cooperation,\", \"vi\": \"Cảm ơn sự hợp tác của bạn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Frank Jacobs\", \"vi\": \"Frank Jacobs\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '28d6598d-db5e-4db4-882b-f9395e40fbb8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Welcome!\", \"vi\": \"Chào mừng!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"www.sergeyparksandrec.gov/survey\", \"vi\": \"www.sergeyparksandrec.gov/survey\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"You have been directed to this survey through a page on the Sergey Parks and Recreation Department\'s Web site, from one of Ecology Alive\'s most recent online newsletters, or from a friend\'s social media page.\", \"vi\": \"Bạn đã được dẫn đến khảo sát này thông qua một trang trên trang web của Sở Công viên và Giải trí Sergey, từ một trong những bản tin trực tuyến gần đây nhất của Ecology Alive, hoặc từ trang mạng xã hội của một người bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Regardless of how you got here, we appreciate your taking the time to complete it.\", \"vi\": \"Bất kể bạn đến đây bằng cách nào, chúng tôi đánh giá cao việc bạn dành thời gian hoàn thành nó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"This survey aims to help local wildlife organizations find practical approaches to attracting a dedicated and reliable volunteer base.\", \"vi\": \"Khảo sát này nhằm mục đích giúp các tổ chức động vật hoang dã địa phương tìm ra các phương pháp thực tế để thu hút một lực lượng tình nguyện viên tận tâm và đáng tin cậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The survey takes about 15 minutes to complete, and your participation is completely optional.\", \"vi\": \"Khảo sát này mất khoảng 15 phút để hoàn thành, và sự tham gia của bạn hoàn toàn tùy chọn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"If you do not wish to answer a particular question, you can move on to the next one.\", \"vi\": \"Nếu bạn không muốn trả lời một câu hỏi cụ thể, bạn có thể chuyển sang câu hỏi tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If you have any questions regarding how this survey will be used, please contact Stefan McHann at stefan_mchann@sergeyparksandrec.gov.\", \"vi\": \"Nếu bạn có bất kỳ câu hỏi nào liên quan đến việc khảo sát này sẽ được sử dụng như thế nào, vui lòng liên hệ Stefan McHann tại stefan_mchann@sergeyparksandrec.gov.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Survey #4123\", \"vi\": \"Khảo sát số 4123\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Name: Kenshawn Odeyemi\", \"vi\": \"Tên: Kenshawn Odeyemi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '295b5801-adb9-47b0-98a8-57de81920bd9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: South Street Bank staff\", \"vi\": \"Đến: Nhân viên Ngân hàng South Street\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: William Rees-Yates, Chief Executive Officer\", \"vi\": \"Từ: William Rees-Yates, Tổng Giám đốc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 12\", \"vi\": \"Ngày: 12 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I am pleased to announce that our bank is expanding.\", \"vi\": \"Tôi vui mừng thông báo rằng ngân hàng của chúng ta đang mở rộng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Thanks to our creative marketing and award-winning customer service, the demand for our services has been growing.\", \"vi\": \"Nhờ hoạt động tiếp thị sáng tạo và dịch vụ khách hàng đoạt giải thưởng, nhu cầu về dịch vụ của chúng ta đã và đang tăng lên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We will therefore be opening a branch in Leesburg this year.\", \"vi\": \"Do đó, chúng ta sẽ mở một chi nhánh tại Leesburg trong năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Although the new branch will not be in operation until July 1, it is already virtually ready to open.\", \"vi\": \"Mặc dù chi nhánh mới sẽ chưa đi vào hoạt động cho đến ngày 1 tháng 7, nhưng nó đã gần như sẵn sàng để mở cửa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"There remain, however, a couple of job openings to be filled that can be viewed at www.southstreetbank.com/jobs.\", \"vi\": \"Tuy nhiên, vẫn còn một vài vị trí tuyển dụng cần được lấp đầy có thể xem tại www.southstreetbank.com/jobs.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"If any of our current staff are interested in transferring to the Leesburg branch, we encourage you to review the vacancies soon and apply at the Web site listed above.\", \"vi\": \"Nếu bất kỳ nhân viên hiện tại nào của chúng ta quan tâm đến việc chuyển đến chi nhánh Leesburg, chúng tôi khuyến khích bạn xem xét các vị trí tuyển dụng sớm và nộp đơn tại trang web được liệt kê ở trên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please contact Human Resources with any questions.\", \"vi\": \"Vui lòng liên hệ Bộ phận Nhân sự nếu có bất kỳ câu hỏi nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Meanwhile, our business continues to thrive and grow in other ways.\", \"vi\": \"Trong khi đó, hoạt động kinh doanh của chúng ta tiếp tục phát triển và tăng trưởng theo những cách khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We have recently been nominated for the Business of the Year award by the Chamber of Commerce.\", \"vi\": \"Chúng tôi gần đây đã được Phòng Thương mại đề cử cho giải thưởng Doanh nghiệp của năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"This is a significant achievement, due in no small part to the dedicated work of our outstanding team.\", \"vi\": \"Đây là một thành tựu đáng kể, phần lớn là nhờ vào sự cống hiến của đội ngũ xuất sắc của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"On behalf of our management team, thank you very much and congratulations.\", \"vi\": \"Thay mặt ban quản lý, xin chân thành cảm ơn và chúc mừng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '298ae59e-3cee-446f-bfaa-05cb1176fdf4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"INVITATION\", \"vi\": \"THƯ MỜI\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To Whom It May Concern:\", \"vi\": \"Kính gửi:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We at the Villiers Entrepreneurs Network would like to invite your company to participate in the Villiers Venture Capital Conference (VVCC) to be held at Torres Mill on Thursday, April 7 at 2 P.M.\", \"vi\": \"Chúng tôi tại Mạng lưới Doanh nhân Villiers muốn kính mời quý công ty tham gia Hội nghị Vốn đầu tư mạo hiểm Villiers (VVCC) được tổ chức tại Torres Mill vào Thứ Năm, ngày 7 tháng 4 lúc 2 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The first, private half of the conference will introduce participants to ______[131] opportunities in the Villiers region.\", \"vi\": \"Nửa đầu mang tính riêng tư của hội nghị sẽ giới thiệu cho những người tham gia về các cơ hội ______[131] tại khu vực Villiers.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [131]}, {\"en\": \"Representatives from six promising area start-ups will give short presentations on their companies\' funding needs.\", \"vi\": \"Đại diện từ sáu công ty khởi nghiệp đầy triển vọng trong khu vực sẽ có các bài thuyết trình ngắn về nhu cầu gây quỹ của công ty họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[132].\", \"vi\": \"______[132].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [132]}, {\"en\": \"You are also welcome to ______[133] the public half of the VVCC, which will run from 4 p.m. to 6 p.m. However, this section is targeted more ______[134] local businesses and entrepreneurs.\", \"vi\": \"Quý vị cũng được chào đón để ______[133] nửa phần công khai của VVCC, diễn ra từ 4 giờ chiều đến 6 giờ chiều. Tuy nhiên, phần này hướng đến mục tiêu ______[134] nhiều hơn đối với các doanh nghiệp và doanh nhân địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [133, 134]}, {\"en\": \"Please respond to this invitation to reserve your place at the VVCC.\", \"vi\": \"Vui lòng phản hồi lại lời mời này để giữ chỗ của quý vị tại VVCC.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Elias Barlow, Chair\", \"vi\": \"Elias Barlow, Chủ tịch\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Villiers Entrepreneurs Network\", \"vi\": \"Mạng lưới Doanh nhân Villiers\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '298eb519-42b6-4f5c-9235-a551b27c250a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Item Number - Description - Price\", \"vi\": \"Số mặt hàng - Mô tả - Giá\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"7563 - Countertop Electric Grill - $49\", \"vi\": \"7563 - Bếp nướng điện để bàn - 49 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"7564 - Egg Beater - $14\", \"vi\": \"7564 - Máy đánh trứng - 14 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"7565 - Tea Kettle - $27\", \"vi\": \"7565 - Ấm đun nước - 27 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"7566 - Toaster - $56\", \"vi\": \"7566 - Máy nướng bánh mì - 56 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"7567 - Cheese Grater - $16\", \"vi\": \"7567 - Dụng cụ bào phô mai - 16 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"24-hour Express Shipping - $20\", \"vi\": \"Giao hàng nhanh 24 giờ - 20 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"TOTAL - $182\", \"vi\": \"TỔNG CỘNG - 182 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Ready Barn\", \"vi\": \"Ready Barn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Order #   #13565\", \"vi\": \"Đơn hàng số #13565\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Date:   June 3\", \"vi\": \"Ngày: 3 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Delivery:   24-hour Express Shipping\", \"vi\": \"Giao hàng: Giao hàng nhanh 24 giờ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Shipping Address:   Helen Kang\", \"vi\": \"Địa chỉ giao hàng: Helen Kang\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"45 Skyrise Road\", \"vi\": \"45 Skyrise Road\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Newten, NY 12039\", \"vi\": \"Newten, NY 12039\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Payment Method:   Credit Card–Jay Shim\", \"vi\": \"Phương thức thanh toán: Thẻ tín dụng–Jay Shim\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"To: customerservice@readybarn.com\", \"vi\": \"Đến: customerservice@readybarn.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"From: jayshim@silyex.com\", \"vi\": \"Từ: jayshim@silyex.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Subject: Order #13565\", \"vi\": \"Chủ đề: Đơn hàng #13565\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Date: June 6\", \"vi\": \"Ngày: 6 tháng 6\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Kính gửi,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I recently placed an order (#13565) with Ready Barn.\", \"vi\": \"Gần đây tôi đã đặt một đơn hàng (#13565) với Ready Barn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"The items I purchased are housewarming gifts for my niece, Helen Kang, who recently purchased a new home.\", \"vi\": \"Các mặt hàng tôi đã mua là quà tân gia cho cháu gái tôi, Helen Kang, người vừa mua một căn nhà mới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Therefore, her address was provided as the delivery destination.\", \"vi\": \"Do đó, địa chỉ của cô ấy đã được cung cấp làm địa điểm giao hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I paid higher shipping fees for 24-hour delivery, as I wanted the items to arrive well ahead of the housewarming party being held tomorrow evening.\", \"vi\": \"Tôi đã trả phí vận chuyển cao hơn để được giao hàng trong 24 giờ, vì tôi muốn các mặt hàng đến trước bữa tiệc tân gia sẽ được tổ chức vào tối mai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Several days have passed, and my niece has yet to receive these items.\", \"vi\": \"Đã vài ngày trôi qua, và cháu gái tôi vẫn chưa nhận được những mặt hàng này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I would appreciate it if you could find out what has happened and let me know when my niece can expect delivery.\", \"vi\": \"Tôi sẽ rất cảm kích nếu quý vị có thể tìm hiểu xem chuyện gì đã xảy ra và cho tôi biết khi nào cháu gái tôi có thể nhận được hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Also, I would like to ask you to return the money I paid for expedited shipping.\", \"vi\": \"Ngoài ra, tôi muốn yêu cầu quý vị hoàn lại số tiền tôi đã trả cho dịch vụ vận chuyển nhanh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Additionally, I do not recognize item number 7564 that I was charged $14 for on my receipt.\", \"vi\": \"Thêm vào đó, tôi không nhận ra mặt hàng số 7564 mà tôi đã bị tính phí 14 đô la trên hóa đơn của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Please let me know how to send it back.\", \"vi\": \"Xin hãy cho tôi biết cách gửi trả lại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I am a longtime customer of Ready Barn, and I am usually very satisfied with your products and services.\", \"vi\": \"Tôi là một khách hàng lâu năm của Ready Barn, và tôi thường rất hài lòng với các sản phẩm và dịch vụ của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Please reply as soon as possible.\", \"vi\": \"Xin hãy trả lời sớm nhất có thể.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Jay Shim\", \"vi\": \"Jay Shim\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '299cf4bd-aa6e-4da7-9590-118127eecc02';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Brody Dimmick <bdimmick@greerscoffee.com.au>\", \"vi\": \"Đến: Brody Dimmick <bdimmick@greerscoffee.com.au>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Fawzia Gurmani <fgurmani@greerscoffee.com.au>\", \"vi\": \"Từ: Fawzia Gurmani <fgurmani@greerscoffee.com.au>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Following up on your recent call\", \"vi\": \"Chủ đề: Theo dõi cuộc gọi gần đây của bạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 17 September\", \"vi\": \"Ngày: 17 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Proposal\", \"vi\": \"Đính kèm: 📎 Đề xuất\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Dimmick,\", \"vi\": \"Kính gửi ông Dimmick,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for your recent call.\", \"vi\": \"Cảm ơn ông về cuộc gọi gần đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We are always pleased to hear from one of our many local store managers.\", \"vi\": \"Chúng tôi luôn vui mừng khi nhận được tin từ một trong số nhiều quản lý cửa hàng địa phương của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I think your idea to reinstate the Greer\'s Coffee Club is excellent, and I am also pleased to know your customers have been asking about the club punch cards.\", \"vi\": \"Tôi nghĩ ý tưởng của ông về việc khôi phục Câu lạc bộ Cà phê Greer\'s là tuyệt vời, và tôi cũng rất vui khi biết khách hàng của ông đã hỏi về thẻ tích điểm của câu lạc bộ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I agree that this is a good time to bring back the program, as we are working on rebranding the company.\", \"vi\": \"Tôi đồng ý rằng đây là thời điểm tốt để đưa chương trình trở lại, vì chúng tôi đang thực hiện việc tái định vị thương hiệu công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I have drawn up your proposal and will forward it to Ms. So-Ra Oh, vice president of marketing, tomorrow.\", \"vi\": \"Tôi đã soạn thảo đề xuất của ông và sẽ chuyển tiếp nó cho bà So-Ra Oh, phó chủ tịch tiếp thị, vào ngày mai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Before I do that, can you please look it over and let me know if I have missed any details?\", \"vi\": \"Trước khi tôi làm điều đó, ông vui lòng xem xét và cho tôi biết nếu tôi có bỏ sót bất kỳ chi tiết nào không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Please send me your feedback by the end of the day.\", \"vi\": \"Vui lòng gửi phản hồi của ông cho tôi trước cuối ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Trân trọng cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Fawzia Gurmani\", \"vi\": \"Fawzia Gurmani\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Regional Director\", \"vi\": \"Giám đốc khu vực\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"http://www.greerscoffee.com.au/rewards\", \"vi\": \"http://www.greerscoffee.com.au/rewards\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Greer\'s, the place for coffee, conversation, and snacks, is now even better!\", \"vi\": \"Greer\'s, nơi dành cho cà phê, trò chuyện và đồ ăn nhẹ, giờ đây còn tuyệt vời hơn nữa!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We have brought back the Greer\'s Coffee Club, but with an update: it is now even easier to use!\", \"vi\": \"Chúng tôi đã mang Câu lạc bộ Cà phê Greer\'s trở lại, nhưng với một bản cập nhật: giờ đây nó thậm chí còn dễ sử dụng hơn!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Simply download our new mobile app and register.\", \"vi\": \"Chỉ cần tải xuống ứng dụng di động mới của chúng tôi và đăng ký.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Use the app to scan your receipt every time you visit any Greer\'s Coffee location, and you will earn points.\", \"vi\": \"Sử dụng ứng dụng để quét biên lai của bạn mỗi khi bạn ghé thăm bất kỳ địa điểm nào của Greer\'s Coffee, và bạn sẽ kiếm được điểm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Each time you accrue 100 points, you can redeem the points for discounts on coffee, food, and other items.\", \"vi\": \"Mỗi khi bạn tích lũy được 100 điểm, bạn có thể đổi điểm để được giảm giá cà phê, đồ ăn và các mặt hàng khác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '29a5b3a5-8712-49e1-99f5-0f49faaccdf7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Annette Schreiber <aschreiber@www.aschreiber.net>\", \"vi\": \"Đến: Annette Schreiber <aschreiber@www.aschreiber.net>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Herbert Peraino, General Manager <hperaino@partyon.com>\", \"vi\": \"Từ: Herbert Peraino, Tổng Giám đốc <hperaino@partyon.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 5\", \"vi\": \"Ngày: Ngày 5 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Private Party\", \"vi\": \"Chủ đề: Tiệc riêng tư\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hello Ms. Schreiber,\", \"vi\": \"Xin chào cô Schreiber,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for considering Partyon for your upcoming event.\", \"vi\": \"Cảm ơn cô đã cân nhắc lựa chọn Partyon cho sự kiện sắp tới của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We welcome the opportunity to inform you about the areas we have available.\", \"vi\": \"Chúng tôi rất hoan nghênh cơ hội được thông tin cho cô về các khu vực mà chúng tôi hiện có.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"______[135].\", \"vi\": \"______[135].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [135]}, {\"en\": \"Our patio, for instance, can hold up to 15 people.\", \"vi\": \"Ví dụ, khu vực hiên ngoài trời của chúng tôi có thể chứa tới 15 người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This space is ______[136] for small get-togethers.\", \"vi\": \"Không gian này rất ______[136] cho các buổi họp mặt quy mô nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [136]}, {\"en\": \"Our lounge area can fit up to 40 people.\", \"vi\": \"Khu vực sảnh chờ của chúng tôi có thể chứa tối đa 40 người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It is best suited for informal ______[137].\", \"vi\": \"Nó phù hợp nhất cho các buổi ______[137] mang tính thân mật, không trang trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [137]}, {\"en\": \"Then there\'s our grand dining room, intended for more formal parties.\", \"vi\": \"Ngoài ra còn có phòng ăn lớn của chúng tôi, dành cho các bữa tiệc trang trọng hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"It offers accommodations for up to 60 guests.\", \"vi\": \"Khu vực này có sức chứa lên đến 60 khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Moreover, we can ______[138] design either a lunch or dinner menu for you according to your specifications.\", \"vi\": \"Hơn nữa, chúng tôi có thể ______[138] thiết kế thực đơn bữa trưa hoặc bữa tối cho cô theo đúng các yêu cầu cụ thể của cô.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": [138]}, {\"en\": \"If you have any further questions, please do not hesitate to contact us.\", \"vi\": \"Nếu cô có bất kỳ câu hỏi nào khác, xin vui lòng liên hệ với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Herbert Peraino\", \"vi\": \"Herbert Peraino\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '29b8d85c-6b6e-48fa-b408-7f39f6783b9f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Krista Nocera\", \"vi\": \"Từ: Krista Nocera\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All Staff\", \"vi\": \"Đến: Toàn thể nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: February 11\", \"vi\": \"Ngày: 11 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Re: Flooring\", \"vi\": \"V/v: Sàn nhà\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Staff,\", \"vi\": \"Kính gửi Quý nhân viên,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"A crew from Trevino Contractors will visit our office this weekend to renovate the main hallway.\", \"vi\": \"Một đội ngũ từ Trevino Contractors sẽ đến văn phòng của chúng ta vào cuối tuần này để cải tạo hành lang chính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Because of the location of the work, it won’t be necessary to move furniture or personal belongings in your office or other shared rooms.\", \"vi\": \"Do vị trí làm việc, sẽ không cần thiết phải di chuyển đồ đạc hoặc vật dụng cá nhân trong văn phòng của bạn hoặc các phòng chung khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"However, if you need to work over the weekend, we ask that you do so remotely.\", \"vi\": \"Tuy nhiên, nếu bạn cần làm việc vào cuối tuần, chúng tôi yêu cầu bạn làm việc từ xa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We understand that some of you need specialized software to complete your tasks, so please see David Rogowski in the IT department to request the use of a company laptop.\", \"vi\": \"Chúng tôi hiểu rằng một số bạn cần phần mềm chuyên dụng để hoàn thành công việc, vì vậy vui lòng gặp David Rogowski tại phòng IT để yêu cầu sử dụng máy tính xách tay của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"If you plan to work late on Friday, please let the security team know if your car is by the Boyd Street entrance.\", \"vi\": \"Nếu bạn dự định làm việc muộn vào thứ Sáu, vui lòng thông báo cho đội bảo vệ nếu xe của bạn đậu gần lối vào phố Boyd.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The crew needs the first row of the lot clear to unload their materials on Saturday morning.\", \"vi\": \"Đội ngũ cần hàng xe đầu tiên của bãi đậu xe trống để dỡ vật liệu vào sáng thứ Bảy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thank you for your cooperation!\", \"vi\": \"Cảm ơn sự hợp tác của bạn!\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Krista Nocera\", \"vi\": \"Krista Nocera\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '29e0fc76-1eac-4810-a52a-532b9bf7caa4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: fcontini@attmail.com\", \"vi\": \"Đến: fcontini@attmail.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: btakemoto@arolischems.co.uk\", \"vi\": \"Từ: btakemoto@arolischems.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 15 July\", \"vi\": \"Ngày: 15 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Your first day at Arolis\", \"vi\": \"Chủ đề: Ngày đầu tiên của bạn tại Arolis\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Contini,\", \"vi\": \"Ông Contini kính mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Welcome to Arolis Chemicals!\", \"vi\": \"Chào mừng bạn đến với Arolis Chemicals!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for ______[139] the full-time, permanent position of laboratory assistant.\", \"vi\": \"Cảm ơn bạn vì đã ______[139] vị trí trợ lý phòng thí nghiệm chính thức, toàn thời gian.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [139]}, {\"en\": \"We look forward to your arrival on 1 August in the Harris Building.\", \"vi\": \"Chúng tôi rất mong chờ sự có mặt của bạn vào ngày 1 tháng 8 tại Tòa nhà Harris.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please report to the front desk and ask for Jack McNolan.\", \"vi\": \"Vui lòng trình diện tại quầy lễ tân và hỏi gặp Jack McNolan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"He ______[140] you to the Human Resources office.\", \"vi\": \"Ông ấy sẽ ______[140] bạn đến văn phòng Nhân sự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [140]}, {\"en\": \"There, you will obtain your employee badge ______[141] all documents necessary to start work.\", \"vi\": \"Tại đó, bạn sẽ nhận được thẻ nhân viên của mình ______[141] tất cả các tài liệu cần thiết để bắt đầu công việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [141]}, {\"en\": \"Note that because of its large size, the Leicester campus of Arolis can be difficult to navigate.\", \"vi\": \"Xin lưu ý rằng do có quy mô lớn, khuôn viên Leicester của Arolis có thể khó di chuyển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Studying a campus map will help orient you to the location of the different buildings.\", \"vi\": \"Việc nghiên cứu bản đồ khuôn viên sẽ giúp bạn định hướng vị trí của các tòa nhà khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"______[142].\", \"vi\": \"______[142].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": [142]}, {\"en\": \"Should you have any questions, please do not hesitate to contact me.\", \"vi\": \"Nếu bạn có bất kỳ câu hỏi nào, xin đừng ngần ngại liên hệ với tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Brandon Takemoto\", \"vi\": \"Brandon Takemoto\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"HR Administrative Officer\", \"vi\": \"Nhân viên Hành chính Nhân sự\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '29fca686-7437-4f28-8220-71a70f7eee75';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Meeting Minutes—August 10\", \"vi\": \"Biên bản cuộc họp—ngày 10 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"In attendance: Miguel Luna, Jennifer Lin, Amal Taylor, Vladimir Ikram, Nevena Ivanova\", \"vi\": \"Người tham dự: Miguel Luna, Jennifer Lin, Amal Taylor, Vladimir Ikram, Nevena Ivanova\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Amal Taylor, the product manager, opened the meeting.\", \"vi\": \"Amal Taylor, quản lý sản phẩm, đã khai mạc cuộc họp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"She reported that our new line of herbal teas will be on local store shelves and in restaurants starting September 25.\", \"vi\": \"Cô ấy báo cáo rằng dòng trà thảo mộc mới của chúng ta sẽ có mặt trên kệ các cửa hàng địa phương và trong các nhà hàng bắt đầu từ ngày 25 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The initial launch includes three flavors: peppermint, lemon ginger, and hibiscus flower.\", \"vi\": \"Đợt ra mắt ban đầu bao gồm ba hương vị: bạc hà, chanh gừng và hoa dâm bụt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"More varieties are expected to be added next year.\", \"vi\": \"Nhiều loại hơn dự kiến sẽ được bổ sung vào năm tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Next, Miguel Luna shared his prototypes of the tea boxes and discussed the sustainability of the materials used to produce them.\", \"vi\": \"Tiếp theo, Miguel Luna đã chia sẻ các mẫu thử hộp trà của anh ấy và thảo luận về tính bền vững của các vật liệu được sử dụng để sản xuất chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The colorful designs received positive feedback from meeting attendees.\", \"vi\": \"Các thiết kế đầy màu sắc đã nhận được phản hồi tích cực từ những người tham dự cuộc họp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"After that, Jennifer Lin provided a brief overview of the marketing budget for the product launch.\", \"vi\": \"Sau đó, Jennifer Lin đã cung cấp một cái nhìn tổng quan ngắn gọn về ngân sách tiếp thị cho việc ra mắt sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Funds are currently limited to one advertising campaign.\", \"vi\": \"Nguồn vốn hiện tại bị giới hạn chỉ trong một chiến dịch quảng cáo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"For more detailed information about the marketing budget, contact Ms. Lin directly.\", \"vi\": \"Để biết thêm thông tin chi tiết về ngân sách tiếp thị, hãy liên hệ trực tiếp với cô Lin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Finally, Vladimir Ikram led a discussion about advertising options.\", \"vi\": \"Cuối cùng, Vladimir Ikram đã chủ trì một cuộc thảo luận về các lựa chọn quảng cáo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Radio advertisements have been successful in the past and are cheaper than television.\", \"vi\": \"Quảng cáo trên đài phát thanh đã thành công trong quá khứ và rẻ hơn quảng cáo trên truyền hình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Digital advertisements were also considered.\", \"vi\": \"Quảng cáo kỹ thuật số cũng đã được xem xét.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The final decision was to start with print advertisements in The Southtown Times.\", \"vi\": \"Quyết định cuối cùng là bắt đầu với quảng cáo in trên tờ The Southtown Times.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The next meeting will be on August 17.\", \"vi\": \"Cuộc họp tiếp theo sẽ diễn ra vào ngày 17 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '2a0028f1-dd26-4c3e-a38f-1f2fa4674583';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Lindsay Pokora (2:15 P.M.) Hello, Mr. Kopalinski.\", \"vi\": \"Lindsay Pokora (2:15 CH) Chào ông Kopalinski.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I need to place the monthly office supplies order.\", \"vi\": \"Tôi cần đặt hàng văn phòng phẩm hàng tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"In addition to the regular items, can you let me know if anything extra is needed?\", \"vi\": \"Ngoài các mặt hàng thông thường, ông có thể cho tôi biết nếu cần thêm bất cứ thứ gì không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Craig Kopalinski (2:17 P.M.) Let me check with the other managers.\", \"vi\": \"Craig Kopalinski (2:17 CH) Để tôi kiểm tra với các quản lý khác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Kaitlyn and Jeffrey, do you have any requests for office supplies in your departments?\", \"vi\": \"Kaitlyn và Jeffrey, các bạn có yêu cầu gì về văn phòng phẩm cho phòng ban của mình không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Kaitlyn Daley (2:18 P.M.) Yes, we need more whiteboard markers.\", \"vi\": \"Kaitlyn Daley (2:18 CH) Vâng, chúng tôi cần thêm bút dạ bảng trắng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Craig Kopalinski (2:19 P.M.) And how about accounting?\", \"vi\": \"Craig Kopalinski (2:19 CH) Còn phòng kế toán thì sao?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Jeffrey Carden (2:20 P.M.) Nothing here.\", \"vi\": \"Jeffrey Carden (2:20 CH) Không có gì ở đây.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Lindsay Pokora (2:22 P.M.) Markers?\", \"vi\": \"Lindsay Pokora (2:22 CH) Bút dạ ư?\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I just checked our inventory and we still have a box in the supply room.\", \"vi\": \"Tôi vừa kiểm tra kho và chúng ta vẫn còn một hộp trong phòng vật tư.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Do you need a special kind?\", \"vi\": \"Bạn có cần loại đặc biệt không?\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Kaitlyn Daley (2:23 P.M.) No, just regular black markers.\", \"vi\": \"Kaitlyn Daley (2:23 CH) Không, chỉ là bút dạ đen thông thường thôi.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Three boxes should be enough.\", \"vi\": \"Ba hộp là đủ rồi.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I tried some markers from the box we have, but they seem to have dried up.\", \"vi\": \"Tôi đã thử một vài cây bút dạ từ hộp chúng ta có, nhưng chúng có vẻ đã bị khô mực.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"A group of new employees will be starting next week, and we\'ll need markers for the orientation and training sessions.\", \"vi\": \"Một nhóm nhân viên mới sẽ bắt đầu vào tuần tới, và chúng tôi sẽ cần bút dạ cho các buổi định hướng và đào tạo.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Craig Kopalinski (2:24 P.M.) OK.\", \"vi\": \"Craig Kopalinski (2:24 CH) Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Lindsay, in addition to those markers, could you please order a new chair for the second-floor conference room to replace the one that is broken?\", \"vi\": \"Lindsay, ngoài những cây bút dạ đó, bạn có thể vui lòng đặt một chiếc ghế mới cho phòng họp tầng hai để thay thế chiếc ghế bị hỏng không?\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"You\'ll need to look up the model number.\", \"vi\": \"Bạn sẽ cần tra cứu số hiệu mẫu.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thanks.\", \"vi\": \"Cảm ơn.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '2a27c967-64c4-4a36-8ea3-b27c96b28674';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Date: 12 October\", \"vi\": \"Ngày: 12 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Name: Marzena Majewska\", \"vi\": \"Tên: Marzena Majewska\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Local Address: Hotel Dantes, Rua Jau, 1300 Lisbon, Portugal\", \"vi\": \"Địa chỉ tại địa phương: Khách sạn Dantes, Rua Jau, 1300 Lisbon, Bồ Đào Nha\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Telephone: +44 1632 812110\", \"vi\": \"Điện thoại: +44 1632 812110\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Flight Number: J77FG2\", \"vi\": \"Số hiệu chuyến bay: J77FG2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Quantity - Description\", \"vi\": \"Số lượng - Mô tả\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"☑ Suitcase - 1 - small black suitcase with wheels; \\\"Marzena Majewska\\\" on the name tag\", \"vi\": \"☑ Vali - 1 - vali nhỏ màu đen có bánh xe; có ghi \\\"Marzena Majewska\\\" trên thẻ tên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"☐ Backpack\", \"vi\": \"☐ Ba lô\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"☐ Purse\", \"vi\": \"☐ Ví\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"☑ Box - 1 - small cardboard box with \\\"Marzena Majewska, Saltoni Foods\\\" written on it\", \"vi\": \"☑ Hộp - 1 - hộp bìa cứng nhỏ có ghi \\\"Marzena Majewska, Saltoni Foods\\\"\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"☐ Other\", \"vi\": \"☐ Khác\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"TAHARA AIR ✈\", \"vi\": \"TAHARA AIR ✈\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Delayed Luggage Form\", \"vi\": \"Mẫu đơn hành lý bị trễ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Dear Tahara Air Customer,\", \"vi\": \"Kính gửi Quý khách hàng của Tahara Air,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We regret that the arrival of your luggage has been delayed.\", \"vi\": \"Chúng tôi rất tiếc thông báo rằng hành lý của quý khách đã bị trễ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Please provide the following details to help us track down and return your luggage more quickly.\", \"vi\": \"Vui lòng cung cấp các thông tin chi tiết sau để giúp chúng tôi tìm kiếm và trả lại hành lý của quý khách nhanh hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"A Tahara Air representative will contact you by phone as soon as your luggage is located.\", \"vi\": \"Đại diện của Tahara Air sẽ liên hệ với quý khách qua điện thoại ngay khi tìm thấy hành lý của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Should your luggage remain missing for more than three days, please visit www.tahara-air.com/baggage for further instructions.\", \"vi\": \"Nếu hành lý của quý khách vẫn bị thất lạc quá ba ngày, vui lòng truy cập www.tahara-air.com/baggage để biết thêm hướng dẫn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Delayed Luggage Information\", \"vi\": \"Thông tin hành lý bị trễ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: hgilbert@saltonifoods.co.uk\", \"vi\": \"Từ: hgilbert@saltonifoods.co.uk\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"To: mmajewska@saltonifoods.co.uk\", \"vi\": \"Đến: mmajewska@saltonifoods.co.uk\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subject: Re: Sauce samples\", \"vi\": \"Chủ đề: V/v: Mẫu nước sốt\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Date: 12 October, 2:03 P.M.\", \"vi\": \"Ngày: 12 tháng 10, 2:03 CH\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Dear Marzena,\", \"vi\": \"Marzena thân mến,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I\'m sorry to hear about your luggage.\", \"vi\": \"Tôi rất tiếc khi nghe về hành lý của bạn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"At least the airline has located your suitcase.\", \"vi\": \"Ít nhất thì hãng hàng không đã tìm thấy vali của bạn rồi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Since it\'s impossible to determine when the rest of your luggage will be found and returned, I\'ve sent you more samples by overnight shipping.\", \"vi\": \"Vì không thể xác định khi nào phần hành lý còn lại của bạn sẽ được tìm thấy và trả lại, tôi đã gửi thêm mẫu cho bạn bằng dịch vụ giao hàng qua đêm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"That way, you will not have to go empty-handed to tomorrow\'s meeting with the clients.\", \"vi\": \"Bằng cách đó, bạn sẽ không phải đến cuộc họp ngày mai với khách hàng mà không có gì.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"There are five packets of each flavour as well as two small sauce jars with labels.\", \"vi\": \"Có năm gói mỗi hương vị cũng như hai lọ nước sốt nhỏ có nhãn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I sent the items by BDW Shipping to your hotel.\", \"vi\": \"Tôi đã gửi các mặt hàng này qua BDW Shipping đến khách sạn của bạn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"The package will be delivered by 8:30 a.m. so that you are sure to have the sauce samples and packaging to show when you speak at the meeting at 11.\", \"vi\": \"Gói hàng sẽ được giao trước 8:30 sáng để bạn chắc chắn có các mẫu nước sốt và bao bì để trình bày khi bạn phát biểu tại cuộc họp lúc 11 giờ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Take care,\", \"vi\": \"Giữ gìn sức khỏe nhé,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Harry Gilbert\", \"vi\": \"Harry Gilbert\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Ship from: Saltoni Foods, 27 Aston Street, Oxford OX1 1HD, UK\", \"vi\": \"Gửi từ: Saltoni Foods, 27 Aston Street, Oxford OX1 1HD, UK\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Ship to: Hotel Dantes, Rua Jau, 1300 Lisbon, Portugal\", \"vi\": \"Gửi đến: Khách sạn Dantes, Rua Jau, 1300 Lisbon, Bồ Đào Nha\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Weight: 0.75 kg\", \"vi\": \"Trọng lượng: 0.75 kg\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"BDW Early Morning - Delivery by 8:30 A.M. tomorrow - £52 Ship Now\", \"vi\": \"BDW Sáng sớm - Giao hàng trước 8:30 sáng mai - 52 bảng Anh Gửi ngay\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"BDW Morning - Delivery by 11:00 A.M. tomorrow - £45 Ship Now\", \"vi\": \"BDW Buổi sáng - Giao hàng trước 11:00 sáng mai - 45 bảng Anh Gửi ngay\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"BDW Afternoon - Delivery by 2:00 P.M. tomorrow - £39 Ship Now\", \"vi\": \"BDW Buổi chiều - Giao hàng trước 2:00 chiều mai - 39 bảng Anh Gửi ngay\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"BDW Evening - Delivery by 8:00 P.M. tomorrow - £31 Ship Now\", \"vi\": \"BDW Buổi tối - Giao hàng trước 8:00 tối mai - 31 bảng Anh Gửi ngay\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"https://www.bdwshipping.co.uk/overnight\", \"vi\": \"https://www.bdwshipping.co.uk/overnight\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"BDW Shipping\", \"vi\": \"BDW Shipping\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"The Fast and Reliable Delivery Corporation\", \"vi\": \"Tập đoàn Giao hàng Nhanh chóng và Đáng tin cậy\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Submit an Overnight Shipment\", \"vi\": \"Gửi một lô hàng qua đêm\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"Your shipment information:\", \"vi\": \"Thông tin lô hàng của bạn:\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"☐ Envelope    ☑ Box    ☐ Custom packaging\", \"vi\": \"☐ Phong bì    ☑ Hộp    ☐ Bao bì tùy chỉnh\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 46, \"question_numbers\": []}, {\"en\": \"Your overnight shipment options:\", \"vi\": \"Các lựa chọn vận chuyển qua đêm của bạn:\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 47, \"question_numbers\": []}]' WHERE `id` = '2a2fc510-f1bf-43e5-a998-bbcf432284ad';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Member list\", \"vi\": \"Đến: Danh sách thành viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Otis Community Center\", \"vi\": \"Từ: Trung tâm Cộng đồng Otis\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: February 3\", \"vi\": \"Ngày: Ngày 3 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Cooking classes\", \"vi\": \"Chủ đề: Các lớp học nấu ăn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Flyer\", \"vi\": \"Đính kèm: 📎 Tờ rơi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As part of our ongoing efforts to celebrate cultural diversity, Otis Community Center will hold a series of one-time cooking classes on Asian dishes this spring.\", \"vi\": \"Trong nỗ lực không ngừng nhằm tôn vinh sự đa dạng văn hóa, Trung tâm Cộng đồng Otis sẽ tổ chức một loạt các lớp học nấu ăn một lần về các món ăn châu Á vào mùa xuân này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The classes will be held on the first Wednesday evening of each month from March through June.\", \"vi\": \"Các lớp học sẽ được tổ chức vào tối thứ Tư đầu tiên của mỗi tháng từ tháng 3 đến tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In order, the dishes covered will be Vietnamese chicken curry, Korean kimchi stew, Thai spring rolls, and Cantonese stir-fry beef.\", \"vi\": \"Theo thứ tự, các món ăn được giới thiệu sẽ là cà ri gà Việt Nam, canh kim chi Hàn Quốc, gỏi cuốn Thái Lan và bò xào kiểu Quảng Đông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Guest instructors from Roark Culinary Academy will teach the classes in our dedicated cooking classroom.\", \"vi\": \"Các giảng viên khách mời từ Học viện Ẩm thực Roark sẽ giảng dạy các lớp học tại phòng học nấu ăn chuyên dụng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Advance registration and payment are required, and participants will be asked to show proof of registration to their instructor.\", \"vi\": \"Yêu cầu đăng ký và thanh toán trước, và những người tham gia sẽ được yêu cầu xuất trình bằng chứng đăng ký cho giảng viên của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Registration can be completed at our front desk from February 15 for all classes.\", \"vi\": \"Việc đăng ký có thể được hoàn tất tại quầy lễ tân của chúng tôi từ ngày 15 tháng 2 cho tất cả các lớp học.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Those who are not members of Otis Community Center will be required to pay a $5 registration fee.\", \"vi\": \"Những người không phải là thành viên của Trung tâm Cộng đồng Otis sẽ phải trả phí đăng ký 5 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Please see the attached flyer for details including materials fees, which vary by class.\", \"vi\": \"Vui lòng xem tờ rơi đính kèm để biết chi tiết bao gồm phí vật liệu, phí này thay đổi tùy theo lớp học.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Questions about the classes may be directed to Heather Tate, our programming specialist.\", \"vi\": \"Các câu hỏi về các lớp học có thể được gửi đến Heather Tate, chuyên viên lập trình của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Akio Hayashi, Director\", \"vi\": \"Akio Hayashi, Giám đốc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Otis Community Center\", \"vi\": \"Trung tâm Cộng đồng Otis\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"CLASS REGISTRATION CONFIRMATION FORM\", \"vi\": \"MẪU XÁC NHẬN ĐĂNG KÝ LỚP HỌC\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Name: Kayla Shull\", \"vi\": \"Tên: Kayla Shull\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Membership Number: 499560\", \"vi\": \"Số thành viên: 499560\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Class Title: Thai Spring Rolls\", \"vi\": \"Tên lớp học: Gỏi cuốn Thái Lan\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Instructor: David Somsri\", \"vi\": \"Giảng viên: David Somsri\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Date & Time: May 6, 5 P.M.\", \"vi\": \"Ngày & Giờ: Ngày 6 tháng 5, 5 giờ chiều\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Registration Fee: WAIVED\", \"vi\": \"Phí đăng ký: MIỄN PHÍ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Materials Fee: $15 Paid ☑\", \"vi\": \"Phí vật liệu: 15 đô la Đã thanh toán ☑\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Processed by: Eric Woodard\", \"vi\": \"Xử lý bởi: Eric Woodard\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Note:\", \"vi\": \"Lưu ý:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Refunds of class fees are only issued for cancellations made at least one week before the class date.\", \"vi\": \"Phí lớp học chỉ được hoàn trả đối với các trường hợp hủy bỏ được thực hiện ít nhất một tuần trước ngày diễn ra lớp học.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"To cancel your registration, please visit the center or call our front desk at 555-0195.\", \"vi\": \"Để hủy đăng ký của bạn, vui lòng đến trung tâm hoặc gọi cho quầy lễ tân của chúng tôi theo số 555-0195.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '2a794b22-b7f4-46d6-be05-795f16c1be92';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Priscilla Yamaguchi\", \"vi\": \"Priscilla Yamaguchi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Falkenweg 19\", \"vi\": \"Falkenweg 19\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"10719 Berlin\", \"vi\": \"10719 Berlin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"23 March\", \"vi\": \"Ngày 23 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Yamaguchi,\", \"vi\": \"Kính gửi bà Yamaguchi,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am writing to you to share the exciting news that Aqua Voyage Cruise Lines will be expanding its fleet next July.\", \"vi\": \"Tôi viết thư này để chia sẻ tin tức thú vị rằng Aqua Voyage Cruise Lines sẽ mở rộng đội tàu của mình vào tháng 7 tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As part of our plan, we would welcome the opportunity to form a partnership with you.\", \"vi\": \"Là một phần trong kế hoạch của chúng tôi, chúng tôi rất mong muốn có cơ hội hợp tác với bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You have established a solid reputation regarding your restaurant chain, Saffron Moon.\", \"vi\": \"Bà đã tạo dựng được danh tiếng vững chắc cho chuỗi nhà hàng của mình, Saffron Moon.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Your commitment to offering your customers across Europe unique and delicious menu items aligns with our vision for providing cruise-ship passengers with distinct restaurant options.\", \"vi\": \"Cam kết của bà trong việc cung cấp cho khách hàng trên khắp châu Âu những món ăn độc đáo và ngon miệng phù hợp với tầm nhìn của chúng tôi về việc mang đến cho hành khách trên tàu du lịch những lựa chọn nhà hàng đặc biệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"There are several benefits of entering into a partnership with us.\", \"vi\": \"Có một số lợi ích khi hợp tác với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Since our cruise excursions attract a diverse group of people, an even more extensive group will become familiar with your restaurant chain.\", \"vi\": \"Vì các chuyến du ngoạn bằng tàu của chúng tôi thu hút nhiều đối tượng khách hàng đa dạng, nên một nhóm khách hàng thậm chí còn lớn hơn sẽ biết đến chuỗi nhà hàng của bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Aqua Voyage Cruise Lines will mention your top-rated chain in our brochures and feature it on our Web site.\", \"vi\": \"Aqua Voyage Cruise Lines sẽ đề cập đến chuỗi nhà hàng được đánh giá cao của bà trong các tài liệu quảng cáo của chúng tôi và giới thiệu nó trên trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Through our network of suppliers, we can help negotiate exceptionally low rates for recipe ingredients and restaurant equipment, thereby reducing your expenses.\", \"vi\": \"Thông qua mạng lưới nhà cung cấp của chúng tôi, chúng tôi có thể giúp đàm phán mức giá cực kỳ thấp cho các nguyên liệu công thức và thiết bị nhà hàng, từ đó giảm chi phí cho bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"If you are interested in pursuing this proposition and wish to discuss the details, you can reach me at kbasrawi@aquavoyagecruiselines.de or by phone at 30-23125 032.\", \"vi\": \"Nếu bà quan tâm đến đề xuất này và muốn thảo luận chi tiết, bà có thể liên hệ với tôi qua địa chỉ kbasrawi@aquavoyagecruiselines.de hoặc qua điện thoại theo số 30-23125 032.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Khalid Basrawi\", \"vi\": \"Khalid Basrawi\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Khalid Basrawi, Vice President of Corporate Development\", \"vi\": \"Khalid Basrawi, Phó Chủ tịch Phát triển Doanh nghiệp\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Aqua Voyage Cruise Lines\", \"vi\": \"Aqua Voyage Cruise Lines\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '2acd5d40-0479-49d0-935a-793e4aca9282';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.musiclinkplus.ie/home\", \"vi\": \"https://www.musiclinkplus.ie/home\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Music Link Plus (MLP) supports job seekers and recruiters in the music industry.\", \"vi\": \"Music Link Plus (MLP) hỗ trợ người tìm việc và nhà tuyển dụng trong ngành công nghiệp âm nhạc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"For Job Seekers: Start by creating a free MLP profile.\", \"vi\": \"Đối với Người tìm việc: Bắt đầu bằng cách tạo một hồ sơ MLP miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"You will then receive full access to employment opportunities on our Job Listings page.\", \"vi\": \"Sau đó, bạn sẽ có toàn quyền truy cập vào các cơ hội việc làm trên trang Danh sách việc làm của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Our Resources page provides sheet music and singers\' recordings to help you prepare for an audition.\", \"vi\": \"Trang Tài nguyên của chúng tôi cung cấp bản nhạc và các bản ghi âm của ca sĩ để giúp bạn chuẩn bị cho buổi thử giọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The page also features complete instructions on how to create and upload a video recording to our Web site if a recruiter requests a video sample from you.\", \"vi\": \"Trang này cũng có hướng dẫn đầy đủ về cách tạo và tải bản ghi video lên trang web của chúng tôi nếu nhà tuyển dụng yêu cầu bạn gửi một video mẫu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"For Recruiters: Begin by opening an account by paying an initial fee of €300, after which you will be charged €150 annually.\", \"vi\": \"Đối với Nhà tuyển dụng: Bắt đầu bằng cách mở tài khoản với khoản phí ban đầu là 300 euro, sau đó bạn sẽ bị tính phí 150 euro hàng năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Your account entitles you to list unlimited job postings.\", \"vi\": \"Tài khoản của bạn cho phép bạn đăng không giới hạn các tin tuyển dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"You will also be able to select the pieces you want your candidates to perform from a wide menu that we provide.\", \"vi\": \"Bạn cũng sẽ có thể chọn các tác phẩm mà bạn muốn ứng viên của mình biểu diễn từ một danh mục rộng lớn mà chúng tôi cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Candidates will be able to upload their audition videos right on this Web site.\", \"vi\": \"Các ứng viên sẽ có thể tải video thử giọng của họ trực tiếp lên trang web này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"HomeJob ListingsMusician ProfilesResources\", \"vi\": \"Trang chủDanh sách việc làmHồ sơ nhạc sĩTài nguyên\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: Janice Trapani, Choir Director\", \"vi\": \"Đến: Janice Trapani, Giám đốc Hợp xướng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From: Kevin Ellis, General Manager\", \"vi\": \"Từ: Kevin Ellis, Tổng Giám đốc\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: 7 July\", \"vi\": \"Ngày: 7 tháng 7\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Subject: Planning for autumn\", \"vi\": \"Chủ đề: Lập kế hoạch cho mùa thu\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Hello, Janice,\", \"vi\": \"Chào Janice,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I need to update you on a couple of issues affecting our autumn schedule.\", \"vi\": \"Tôi cần cập nhật cho bạn về một vài vấn đề ảnh hưởng đến lịch trình mùa thu của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"• The arts commission has asked our Gradey City Choir to debut a special piece of music in November, the oratorio By the Meadow by Gradey City\'s own Jeffrey Stolartz.\", \"vi\": \"• Ủy ban nghệ thuật đã yêu cầu Dàn hợp xướng Gradey City của chúng ta ra mắt một tác phẩm âm nhạc đặc biệt vào tháng 11, bản oratorio By the Meadow của chính Jeffrey Stolartz đến từ Gradey City.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"It is such an honour to be selected to perform this composition!\", \"vi\": \"Thật vinh dự khi được chọn để biểu diễn tác phẩm này!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"This addition to our schedule completes our autumn lineup.\", \"vi\": \"Việc bổ sung này vào lịch trình của chúng ta hoàn thiện đội hình mùa thu của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"• Unfortunately, I learned late last week that two singers need to be replaced before rehearsals begin in August.\", \"vi\": \"• Thật không may, cuối tuần trước tôi đã biết rằng cần phải thay thế hai ca sĩ trước khi các buổi tập bắt đầu vào tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Since we are already one week into July, I opened an account with Music Link Plus (MLP) this morning to expedite our search.\", \"vi\": \"Vì chúng ta đã bước sang tuần thứ hai của tháng 7, sáng nay tôi đã mở một tài khoản với Music Link Plus (MLP) để đẩy nhanh quá trình tìm kiếm của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Tomorrow, I plan to post our positions on their Job Listings page.\", \"vi\": \"Ngày mai, tôi dự định đăng các vị trí của chúng ta lên trang Danh sách việc làm của họ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Using this Web site will allow us to reach countless potential applicants.\", \"vi\": \"Sử dụng trang web này sẽ cho phép chúng ta tiếp cận vô số ứng viên tiềm năng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Additionally, MLP gives us the option of having candidates audition by providing video recordings.\", \"vi\": \"Ngoài ra, MLP cung cấp cho chúng ta tùy chọn để các ứng viên thử giọng bằng cách cung cấp các bản ghi video.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Given our time constraints, we should consider having auditions done this way.\", \"vi\": \"Với những hạn chế về thời gian của chúng ta, chúng ta nên cân nhắc việc thử giọng theo cách này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"However, if you feel that in-person auditions are necessary, please let me know by the end of the day today.\", \"vi\": \"Tuy nhiên, nếu bạn cảm thấy rằng các buổi thử giọng trực tiếp là cần thiết, vui lòng cho tôi biết trước cuối ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Kevin\", \"vi\": \"Kevin\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"https://www.musiclinkplus.ie/joblistings\", \"vi\": \"https://www.musiclinkplus.ie/joblistings\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Vocalist Positions (Gradey City Choir)\", \"vi\": \"Vị trí Ca sĩ (Dàn hợp xướng Gradey City)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Posted on: 8 July\", \"vi\": \"Đăng vào: 8 tháng 7\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Application deadline: 21 July\", \"vi\": \"Hạn chót nộp đơn: 21 tháng 7\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Gradey City Choir seeks two singers for its autumn season: an alto and a tenor.\", \"vi\": \"Dàn hợp xướng Gradey City đang tìm kiếm hai ca sĩ cho mùa thu của mình: một giọng nữ trầm (alto) và một giọng nam cao (tenor).\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Successful candidates will join our dynamic choir under the direction of Janice Trapani and will be expected to report to Neufried Auditorium on 11 August for autumn performance rehearsals.\", \"vi\": \"Các ứng viên thành công sẽ tham gia dàn hợp xướng năng động của chúng tôi dưới sự chỉ đạo của Janice Trapani và dự kiến sẽ có mặt tại Thính phòng Neufried vào ngày 11 tháng 8 để tập luyện cho buổi biểu diễn mùa thu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Applicants must supply an audition video.\", \"vi\": \"Ứng viên phải cung cấp một video thử giọng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Simply follow the instructions on the Resources page.\", \"vi\": \"Chỉ cần làm theo hướng dẫn trên trang Tài nguyên.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"We have selected a portion from Franka Berman\'s Still Waters Cantata for candidates to sing.\", \"vi\": \"Chúng tôi đã chọn một đoạn từ bản Cantata Still Waters của Franka Berman để các ứng viên hát.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Hiring decision notifications will be sent to your personal e-mail address on 4 August.\", \"vi\": \"Thông báo quyết định tuyển dụng sẽ được gửi đến địa chỉ email cá nhân của bạn vào ngày 4 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"HomeJob ListingsMusician ProfilesResources\", \"vi\": \"Trang chủDanh sách việc làmHồ sơ nhạc sĩTài nguyên\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}]' WHERE `id` = '2af412fd-1abf-4e0e-8101-8a9acdaec4bd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Bridget Morandi\", \"vi\": \"Đến: Bridget Morandi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Marybeth Wright\", \"vi\": \"Từ: Marybeth Wright\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 23\", \"vi\": \"Ngày: 23 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Refund request\", \"vi\": \"Chủ đề: Yêu cầu hoàn tiền\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hi Bridget,\", \"vi\": \"Chào Bridget,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I was wondering if you have heard from Sujata Reddy.\", \"vi\": \"Tôi tự hỏi không biết bạn đã nhận được tin tức gì từ Sujata Reddy chưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"She was enrolled in the painting class I teach on Tuesday and Thursday.\", \"vi\": \"Cô ấy đã đăng ký lớp vẽ mà tôi dạy vào thứ Ba và thứ Năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"She was only able to attend for the first week because another commitment came up.\", \"vi\": \"Cô ấy chỉ có thể tham gia trong tuần đầu tiên vì có một cam kết khác phát sinh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"She said she asked someone in the Tucson Adult School office if she could drop the class, and she has requested a refund of the course tuition.\", \"vi\": \"Cô ấy nói rằng cô ấy đã hỏi một người nào đó ở văn phòng Trường Người lớn Tucson liệu cô ấy có thể bỏ lớp học không, và cô ấy đã yêu cầu hoàn lại học phí khóa học.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"She said she hasn\'t received her refund yet.\", \"vi\": \"Cô ấy nói rằng cô ấy vẫn chưa nhận được tiền hoàn lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Did she contact you?\", \"vi\": \"Cô ấy có liên hệ với bạn không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Marybeth Wright\", \"vi\": \"Marybeth Wright\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To: Marybeth Wright\", \"vi\": \"Đến: Marybeth Wright\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"From: Bridget Morandi\", \"vi\": \"Từ: Bridget Morandi\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Date: March 24\", \"vi\": \"Ngày: 24 tháng 3\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Subject: Re: Refund request\", \"vi\": \"Chủ đề: V/v: Yêu cầu hoàn tiền\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Hi Marybeth,\", \"vi\": \"Chào Marybeth,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The name is familiar, but Ms. Reddy hasn\'t been in touch with me personally.\", \"vi\": \"Cái tên này nghe quen, nhưng cô Reddy chưa liên hệ trực tiếp với tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Actually, I\'m not the person she should contact.\", \"vi\": \"Thực ra, tôi không phải là người mà cô ấy nên liên hệ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I just handle the scheduling as well as ordering supplies for the art classes.\", \"vi\": \"Tôi chỉ phụ trách việc lên lịch cũng như đặt mua vật tư cho các lớp học nghệ thuật.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I don\'t know who Ms. Reddy spoke to.\", \"vi\": \"Tôi không biết cô Reddy đã nói chuyện với ai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"According to our refund policy on the Tucson Adult School Web site, refunds are only granted if they are requested before the class begins or if there is a documented health reason for dropping the class.\", \"vi\": \"Theo chính sách hoàn tiền của chúng tôi trên trang web của Trường Người lớn Tucson, tiền hoàn lại chỉ được cấp nếu yêu cầu được thực hiện trước khi lớp học bắt đầu hoặc nếu có lý do sức khỏe được chứng minh để bỏ lớp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"In the case of a health reason, the amount of the refund will be based on the number of classes completed.\", \"vi\": \"Trong trường hợp có lý do sức khỏe, số tiền hoàn lại sẽ dựa trên số buổi học đã hoàn thành.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Maybe Ms. Reddy can attend your second semester class instead of this semester\'s.\", \"vi\": \"Có lẽ cô Reddy có thể tham gia lớp học học kỳ hai của bạn thay vì lớp học kỳ này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"That would be my suggestion.\", \"vi\": \"Đó sẽ là đề xuất của tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Bridget Morandi\", \"vi\": \"Bridget Morandi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '2b2b970a-705e-407a-8009-b60a0111b5f8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: lcho@cuvacorporatetraining.com\", \"vi\": \"Từ: lcho@cuvacorporatetraining.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: all_staff@cuvacorporatetraining.com\", \"vi\": \"Đến: all_staff@cuvacorporatetraining.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: Monday, April 12, 10:53 A.M.\", \"vi\": \"Ngày: Thứ Hai, ngày 12 tháng 4, 10:53 SA.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Special notice\", \"vi\": \"Chủ đề: Thông báo đặc biệt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear colleagues,\", \"vi\": \"Kính gửi các đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Please be advised that the Customer Security System (CSS) installed on your computer will be automatically updated this weekend.\", \"vi\": \"Xin lưu ý rằng Hệ thống bảo mật khách hàng (CSS) được cài đặt trên máy tính của quý vị sẽ được tự động cập nhật vào cuối tuần này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Specifically, the update will be taking place from midnight, Saturday, April 17, to midnight, Sunday, April 18.\", \"vi\": \"Cụ thể, bản cập nhật sẽ diễn ra từ nửa đêm Thứ Bảy, ngày 17 tháng 4, đến nửa đêm Chủ Nhật, ngày 18 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Your device will restart after the update has been completed.\", \"vi\": \"Thiết bị của quý vị sẽ khởi động lại sau khi bản cập nhật hoàn tất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The purpose of the update is twofold.\", \"vi\": \"Mục đích của bản cập nhật có hai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"First, it will increase the security of our client information.\", \"vi\": \"Thứ nhất, nó sẽ tăng cường bảo mật thông tin khách hàng của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Moreover, it will improve overall system performance.\", \"vi\": \"Ngoài ra, nó sẽ cải thiện hiệu suất hệ thống tổng thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"As a result, you should notice improved processing speeds and less unplanned system downtime.\", \"vi\": \"Kết quả là, quý vị sẽ nhận thấy tốc độ xử lý được cải thiện và ít thời gian ngừng hoạt động hệ thống ngoài kế hoạch hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Please note that following the update there will be a change in the appearance of the CSS log-in screen, but this change will not affect the log-in procedures.\", \"vi\": \"Xin lưu ý rằng sau bản cập nhật sẽ có sự thay đổi về giao diện màn hình đăng nhập CSS, nhưng sự thay đổi này sẽ không ảnh hưởng đến quy trình đăng nhập.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The tech support team will be available to answer any questions you may have before and after the update.\", \"vi\": \"Đội ngũ hỗ trợ kỹ thuật sẽ sẵn sàng trả lời bất kỳ câu hỏi nào quý vị có thể có trước và sau bản cập nhật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"By Thursday, you will receive a link to a training video with explanations of the new features that will become available with the update.\", \"vi\": \"Trước thứ Năm, quý vị sẽ nhận được một liên kết đến video đào tạo với các giải thích về các tính năng mới sẽ có sẵn với bản cập nhật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Leana Cho\", \"vi\": \"Leana Cho\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Manager, Technical Support Team\", \"vi\": \"Quản lý, Đội ngũ Hỗ trợ Kỹ thuật\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '2b389ca0-0f33-46bb-9015-bef6ae2a059a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"App Review: Forward Path\", \"vi\": \"Đánh giá ứng dụng: Forward Path\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"In the world of ______[143] apps, those developed by Arvedlon, Inc., stand out for their innovation and ease of use.\", \"vi\": \"Trong thế giới của các ứng dụng ______[143], những ứng dụng được phát triển bởi Arvedlon, Inc. nổi bật nhờ tính đổi mới và sự dễ sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [143]}, {\"en\": \"The newly released Forward Path app ______[144] tablets and smartphones is no exception.\", \"vi\": \"Ứng dụng Forward Path mới được phát hành ______[144] máy tính bảng và điện thoại thông minh cũng không ngoại lệ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [144]}, {\"en\": \"Forward Path connects with home exercise equipment such as stationary bicycles and rowing machines.\", \"vi\": \"Forward Path kết nối với các thiết bị tập thể dục tại nhà như xe đạp tập cố định và máy chèo thuyền.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Users can select video footage of dozens of real-world routes.\", \"vi\": \"Người dùng có thể chọn các đoạn video ghi lại hàng chục tuyến đường trong thế giới thực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Then they can choose from several speed options ______[145] the video to the pace of their workouts.\", \"vi\": \"Sau đó, họ có thể chọn từ một số tùy chọn tốc độ ______[145] video phù hợp với nhịp độ tập luyện của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [145]}, {\"en\": \"______[146].\", \"vi\": \"______[146].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [146]}, {\"en\": \"While nothing can replace an outdoor workout, Forward Path comes closer than any other app currently on the market.\", \"vi\": \"Mặc dù không gì có thể thay thế một buổi tập luyện ngoài trời, Forward Path lại mang lại trải nghiệm gần gũi hơn bất kỳ ứng dụng nào khác hiện có trên thị trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Our testers highly recommend it.\", \"vi\": \"Các thử nghiệm viên của chúng tôi đánh giá rất cao ứng dụng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '2bad2abc-2045-4ead-85ff-2d7b4479b827';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Monday, April 5, 10:00 A.M.–4:00 P.M.\", \"vi\": \"Thứ Hai, ngày 5 tháng 4, 10:00 SA–4:00 CH.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Wednesday, April 7, 11:00 A.M.–4:30 P.M.\", \"vi\": \"Thứ Tư, ngày 7 tháng 4, 11:00 SA–4:30 CH.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Friday, April 9, 6:30 P.M.–10:00 P.M.\", \"vi\": \"Thứ Sáu, ngày 9 tháng 4, 6:30 CH–10:00 CH.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Saturday, April 10, 9:00 A.M.–5:00 P.M.\", \"vi\": \"Thứ Bảy, ngày 10 tháng 4, 9:00 SA–5:00 CH.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attention Line 75 Riders\", \"vi\": \"Thông báo dành cho hành khách tuyến xe buýt số 75\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"All Metrowestern passengers should be aware of the following temporary changes for bus line 75.\", \"vi\": \"Tất cả hành khách của Metrowestern nên lưu ý những thay đổi tạm thời sau đây đối với tuyến xe buýt số 75.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Due to construction, service on Eighth Avenue between Taylor Street and Forbes Boulevard will be suspended during the following periods.\", \"vi\": \"Do công trình xây dựng, dịch vụ trên Đại lộ số Tám giữa Phố Taylor và Đại lộ Forbes sẽ bị tạm ngừng trong các khoảng thời gian sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We apologize for any inconvenience.\", \"vi\": \"Chúng tôi xin lỗi vì bất kỳ sự bất tiện nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As usual, all Metrowestern bus service ends at 11:30 P.M. All buses begin running again at 5:45 A.M. daily.\", \"vi\": \"Như thường lệ, tất cả các dịch vụ xe buýt của Metrowestern kết thúc vào 11:30 CH. Tất cả các xe buýt bắt đầu chạy lại vào 5:45 SA hàng ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '2bafc3fc-4db4-45c0-8ba7-a8dc235ae79d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Harding Environmental Group\", \"vi\": \"Tập đoàn Môi trường Harding\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"September 6\", \"vi\": \"Ngày 6 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Jelani Campbell\", \"vi\": \"Jelani Campbell\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Norden Water Commission\", \"vi\": \"Ủy ban Nước Norden\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"329 Route 15\", \"vi\": \"329 Tuyến đường 15\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Norden City, AZ 86310\", \"vi\": \"Thành phố Norden, AZ 86310\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Mr. Campbell,\", \"vi\": \"Kính gửi ông Campbell,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I appreciate the Norden Water Commission\'s interest in my serving as a member of your board of directors.\", \"vi\": \"Tôi rất trân trọng sự quan tâm của Ủy ban Nước Norden đối với việc tôi tham gia với tư cách là thành viên trong ban giám đốc của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As we discussed, I am currently unable to assume any additional responsibilities.\", \"vi\": \"Như chúng ta đã thảo luận, hiện tại tôi không thể đảm nhận thêm bất kỳ trách nhiệm nào khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"However, I would like to take this opportunity to voice my support for Ms. Lauren Birrell to serve as a board member.\", \"vi\": \"Tuy nhiên, tôi muốn nhân cơ hội này để bày tỏ sự ủng hộ của mình đối với bà Lauren Birrell cho vị trí thành viên ban giám đốc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Ms. Birrell, the Director of Development at Harding Environmental Group, began her career here as a water analyst.\", \"vi\": \"Bà Birrell, Giám đốc Phát triển tại Tập đoàn Môi trường Harding, đã bắt đầu sự nghiệp của mình tại đây với tư cách là một nhà phân tích nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"She was quickly promoted to multiple supervisory roles as her expert knowledge and skills became apparent.\", \"vi\": \"Bà đã nhanh chóng được thăng chức lên nhiều vai trò giám sát khi kiến thức chuyên môn và kỹ năng của bà được thể hiện rõ nét.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"For example, a recent research study led by Ms. Birrell found deficiencies with Norden City\'s water pumping system.\", \"vi\": \"Ví dụ, một nghiên cứu gần đây do bà Birrell dẫn đầu đã phát hiện ra những thiếu sót trong hệ thống bơm nước của Thành phố Norden.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"She provided guidance on necessary upgrades in a timely and cost-effective manner.\", \"vi\": \"Bà đã đưa ra hướng dẫn về các nâng cấp cần thiết một cách kịp thời và tiết kiệm chi phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The upgraded system, which requires much less maintenance, has saved Norden City thousands of dollars over the past five years.\", \"vi\": \"Hệ thống được nâng cấp, vốn đòi hỏi ít bảo trì hơn nhiều, đã giúp Thành phố Norden tiết kiệm hàng ngàn đô la trong năm năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Additionally, Ms. Birrell has built strong relationships with the Great Valley Watershed, the Norden Department of Environmental Protection, and other government agencies.\", \"vi\": \"Ngoài ra, bà Birrell đã xây dựng được mối quan hệ bền chặt với Lưu vực sông Great Valley, Sở Bảo vệ Môi trường Norden và các cơ quan chính phủ khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Ms. Birrell would be an invaluable contributor to your organization.\", \"vi\": \"Bà Birrell sẽ là một người đóng góp vô giá cho tổ chức của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Should you have any questions, please contact me directly at 928-555-0176.\", \"vi\": \"Nếu quý vị có bất kỳ câu hỏi nào, vui lòng liên hệ trực tiếp với tôi theo số 928-555-0176.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Saniya Mathur\", \"vi\": \"Saniya Mathur\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Saniya Mathur\", \"vi\": \"Saniya Mathur\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"President, Harding Environmental Group\", \"vi\": \"Chủ tịch, Tập đoàn Môi trường Harding\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '2bb1563e-2250-4ea8-95f6-ca8d795b028c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Casey Willard (7:43 A.M.)\", \"vi\": \"Casey Willard (7:43 sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Can either of you come in to work this morning?\", \"vi\": \"Một trong hai bạn có thể đến làm việc sáng nay được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We have a huge order to fill, and two of the forklift drivers scheduled for today have called in sick.\", \"vi\": \"Chúng ta có một đơn hàng lớn cần hoàn thành, và hai trong số các tài xế xe nâng có lịch làm việc hôm nay đã xin nghỉ ốm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"So, we only have one working.\", \"vi\": \"Vì vậy, chúng ta chỉ có một người đang làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"One or two more would be really helpful.\", \"vi\": \"Có thêm một hoặc hai người nữa thì thực sự rất hữu ích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The shipping clerks can\'t get the products out fast enough.\", \"vi\": \"Các nhân viên giao nhận không thể chuyển sản phẩm ra đủ nhanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Kazuko Yoneda (7:46 A.M.)\", \"vi\": \"Kazuko Yoneda (7:46 sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Sorry, I wish I could, but I have other commitments today.\", \"vi\": \"Xin lỗi, tôi rất muốn giúp nhưng hôm nay tôi có việc bận khác rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Maybe try Claudia Kwon?\", \"vi\": \"Hay là thử hỏi Claudia Kwon xem?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"She is usually very flexible.\", \"vi\": \"Cô ấy thường rất linh hoạt về thời gian.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Casey Willard (7:47 A.M.)\", \"vi\": \"Casey Willard (7:47 sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"She has the weekend off and went to Ford Harbor to visit her family.\", \"vi\": \"Cô ấy được nghỉ cuối tuần và đã đến Cảng Ford để thăm gia đình rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"It\'s too bad because she always appreciates an opportunity to earn overtime pay.\", \"vi\": \"Thật tiếc vì cô ấy luôn trân trọng cơ hội để kiếm thêm tiền lương làm thêm giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Lucas Suarez (7:51 A.M.)\", \"vi\": \"Lucas Suarez (7:51 sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I\'m busy until about 10 A.M., but I could come in after that.\", \"vi\": \"Tôi bận cho đến khoảng 10 giờ sáng, nhưng sau đó tôi có thể đến được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Casey Willard (7:52 A.M.)\", \"vi\": \"Casey Willard (7:52 sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thank you, Lucas.\", \"vi\": \"Cảm ơn cậu, Lucas.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We need all the help we can get!\", \"vi\": \"Chúng ta cần tất cả sự trợ giúp có thể!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"If the order is not on the truck by 6 tonight, it won\'t go out for delivery until Monday.\", \"vi\": \"Nếu đơn hàng không được xếp lên xe tải trước 6 giờ tối nay, nó sẽ không được vận chuyển đi giao cho đến thứ Hai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Lucas Suarez (7:54 A.M.)\", \"vi\": \"Lucas Suarez (7:54 sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Got it.\", \"vi\": \"Tôi hiểu rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I\'ll be there as soon as I can.\", \"vi\": \"Tôi sẽ đến đó ngay khi có thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '2bba05b0-4af5-4faf-ab52-2f4f0704df7b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Kitchenware Utopia Food Processor - Model C3\", \"vi\": \"Máy chế biến thực phẩm Kitchenware Utopia - Mẫu C3\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"You will never need to buy another food processor!\", \"vi\": \"Bạn sẽ không bao giờ cần phải mua một chiếc máy chế biến thực phẩm nào khác!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Our best-selling model, the C3, is made of high-quality plastic and easy-to-clean stainless steel.\", \"vi\": \"Mẫu máy bán chạy nhất của chúng tôi, C3, được làm bằng nhựa chất lượng cao và thép không gỉ dễ lau chùi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"FEATURES: The unique blade design and powerful motor make this a professional-grade appliance, ideal for busy restaurants of any size.\", \"vi\": \"TÍNH NĂNG: Thiết kế lưỡi dao độc đáo và động cơ mạnh mẽ giúp đây trở thành một thiết bị cấp chuyên nghiệp, lý tưởng cho các nhà hàng bận rộn với mọi quy mô.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"WARRANTY: We include a seven-year warranty on all parts and labor - a reassurance to you that our food processor will last a long time.\", \"vi\": \"BẢO HÀNH: Chúng tôi cung cấp gói bảo hành 7 năm cho tất cả các linh kiện và công sửa chữa - một sự đảm bảo cho bạn rằng máy chế biến thực phẩm của chúng tôi sẽ hoạt động bền bỉ trong thời gian dài.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Special purchase price: $319.00\", \"vi\": \"Giá mua đặc biệt: $319.00\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"KU Club Members: $299.00\", \"vi\": \"Thành viên KU Club: $299.00\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"www.kitchenwareutopia.com/C3/reviews/454\", \"vi\": \"www.kitchenwareutopia.com/C3/reviews/454\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Rating: *****\", \"vi\": \"Đánh giá: *****\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Review: This product is amazing!\", \"vi\": \"Nhận xét: Sản phẩm này thật tuyệt vời!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I work as a caterer, and I\'ve used a lot of different food processors.\", \"vi\": \"Tôi làm nghề cung cấp dịch vụ ăn uống (caterer), và tôi đã sử dụng rất nhiều loại máy chế biến thực phẩm khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Kitchenware Utopia\'s C3 is by far the best I\'ve found.\", \"vi\": \"Dòng C3 của Kitchenware Utopia cho đến nay là chiếc máy tốt nhất mà tôi từng tìm thấy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Its motor is very powerful, and the many different blades and settings make it extremely versatile.\", \"vi\": \"Động cơ của nó rất mạnh mẽ, cùng với nhiều lưỡi dao và chế độ cài đặt khác nhau giúp nó cực kỳ đa năng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The settings are also straightforward.\", \"vi\": \"Các chế độ cài đặt cũng rất dễ hiểu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"It\'s expensive but well worth the investment, and since I\'m a loyalty club member, the price was reasonable.\", \"vi\": \"Nó đắt tiền nhưng rất đáng để đầu tư, và vì tôi là thành viên câu lạc bộ khách hàng thân thiết nên mức giá này khá hợp lý.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"My only complaint would be that it\'s very heavy and therefore not as portable as I\'d hoped.\", \"vi\": \"Điểm phàn nàn duy nhất của tôi là nó rất nặng và do đó không dễ mang đi lại như tôi mong đợi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Overall, though, I\'m exceptionally satisfied with this product.\", \"vi\": \"Tuy nhiên, nhìn chung, tôi đặc biệt hài lòng với sản phẩm này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Posted by Eli Perles on March 27\", \"vi\": \"Được đăng bởi Eli Perles vào ngày 27 tháng 3\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We are very glad to hear you are happy with our C3 food processor.\", \"vi\": \"Chúng tôi rất vui khi biết bạn hài lòng với máy chế biến thực phẩm C3 của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Customer satisfaction is our number one priority.\", \"vi\": \"Sự hài lòng của khách hàng là ưu tiên số một của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We would like to respond to your complaint and provide a suggestion regarding your concerns.\", \"vi\": \"Chúng tôi muốn phản hồi lại lời phàn nàn của bạn và đưa ra một gợi ý liên quan đến những lo ngại của bạn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Our C2 processor might be better suited to your professional needs.\", \"vi\": \"Máy chế biến C2 của chúng tôi có thể phù hợp hơn với nhu cầu chuyên nghiệp của bạn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"The C2 offers the same motor size as the C3, but it is much smaller than the C3 in general.\", \"vi\": \"Dòng C2 có cùng kích thước động cơ như C3, nhưng nhìn chung nó nhỏ hơn nhiều so với C3.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"However, this model does cost slightly more than the C3.\", \"vi\": \"Tuy nhiên, mẫu máy này có giá cao hơn một chút so với C3.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"You can view the product description by visiting www.kitchenwareutopia.com/C2.\", \"vi\": \"Bạn có thể xem mô tả sản phẩm bằng cách truy cập www.kitchenwareutopia.com/C2.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Posted by Kitchenware Utopia Customer Service on March 28\", \"vi\": \"Được đăng bởi Bộ phận Chăm sóc Khách hàng của Kitchenware Utopia vào ngày 28 tháng 3\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '2bd6f112-5ef6-43a6-8f75-0127516a3340';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"NEW BAKERY COMING TO TOWN\", \"vi\": \"TIỆM BÁNH MỚI SẮP XUẤT HIỆN TRONG THÀNH PHỐ\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"OREVALE CITY (October 14)—A Cresson\'s Bakery is opening soon at the corner of Canton Avenue and Ridley Street.\", \"vi\": \"THÀNH PHỐ OREVALE (Ngày 14 tháng 10)—Một tiệm bánh Cresson\'s Bakery sắp sửa khai trương tại góc đường Canton Avenue và Ridley Street.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The location will be the national chain\'s first within the city limits.\", \"vi\": \"Địa điểm này sẽ là chi nhánh đầu tiên của chuỗi cửa hàng quốc gia này nằm trong phạm vi thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Like all Cresson\'s Bakery stores, it will operate seven days a week.\", \"vi\": \"Giống như tất cả các cửa hàng Cresson\'s Bakery khác, cửa hàng này sẽ hoạt động bảy ngày một tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The only similar business in the vicinity is the Donut Station on the Kupperman University campus.\", \"vi\": \"Doanh nghiệp tương tự duy nhất ở khu vực lân cận là Donut Station nằm trong khuôn viên trường Đại học Kupperman.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Cresson\'s Bakery will offer breakfast sandwiches and fruit juices in addition to its signature coffee and baked goods.\", \"vi\": \"Cresson\'s Bakery sẽ phục vụ bánh mì kẹp ăn sáng và nước trái cây bên cạnh cà phê và các loại bánh nướng đặc trưng của hãng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The company is following its revised business model to open compact facilities rather than sit-down eateries.\", \"vi\": \"Công ty đang tuân theo mô hình kinh doanh đã được sửa đổi của mình là mở các cơ sở nhỏ gọn thay vì các quán ăn có chỗ ngồi tại chỗ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This means the Orevale City location will offer takeout and drive-through service only.\", \"vi\": \"Điều này có nghĩa là địa điểm tại Thành phố Orevale sẽ chỉ cung cấp dịch vụ mua mang đi và mua hàng trực tiếp trên xe (drive-through).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The bakery will occupy Canton Avenue\'s smallest vacant lot.\", \"vi\": \"Tiệm bánh sẽ tọa lạc trên khu đất trống nhỏ nhất của Đại lộ Canton.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Approval for the project followed a public hearing where area residents voiced mixed opinions.\", \"vi\": \"Việc phê duyệt dự án được đưa ra sau một buổi điều trần công khai, nơi người dân trong khu vực đã bày tỏ nhiều ý kiến trái chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Gina Holton, who lives on Paxton Road, said she liked the idea of having a new bakery in her neighborhood but worries about traffic congestion on Ridley Street.\", \"vi\": \"Gina Holton, một người dân sống trên đường Paxton Road, cho biết bà thích ý tưởng có một tiệm bánh mới trong khu phố của mình nhưng lo ngại về tình trạng ùn tắc giao thông trên đường Ridley Street.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"As evidence, she presented pictures of heavy vehicle traffic there.\", \"vi\": \"Để làm bằng chứng, bà đã trình bày những bức ảnh chụp lượng phương tiện giao thông đông đúc tại đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Wofford Drive resident Steven Lu said he would enjoy having a convenient place to grab a quick snack.\", \"vi\": \"Steven Lu, một cư dân ở đường Wofford Drive, cho biết ông sẽ rất thích thú khi có một nơi thuận tiện để ghé qua mua đồ ăn nhẹ nhanh chóng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Cresson\'s Bakery is slated to welcome its first customers in early March.\", \"vi\": \"Cresson\'s Bakery dự kiến sẽ chào đón những khách hàng đầu tiên vào đầu tháng Ba.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Dear Editor,\", \"vi\": \"Kính gửi Biên tập viên,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"As a lifelong resident of Orevale City, I appreciate your coverage of Cresson\'s Bakery.\", \"vi\": \"Là một cư dân gắn bó cả đời với Thành phố Orevale, tôi đánh giá cao việc quý báo đưa tin về Cresson\'s Bakery.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Unfortunately, the October 14 article contained some inaccurate information.\", \"vi\": \"Thật không may, bài báo ngày 14 tháng 10 có chứa một số thông tin không chính xác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The photos that I shared during the public hearing captured images of traffic congestion in front of my house.\", \"vi\": \"Những bức ảnh mà tôi chia sẻ trong buổi điều trần công khai là ghi lại hình ảnh ùn tắc giao thông ở trước cửa nhà tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Also, as a member of the city\'s Historic Preservation Committee, I was primarily concerned about the bakery\'s architecture.\", \"vi\": \"Ngoài ra, với tư cách là thành viên Ủy ban Bảo tồn Di tích Lịch sử của thành phố, mối quan tâm chính của tôi là về kiến trúc của tiệm bánh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"The initial building design for Cresson\'s Bakery was contemporary.\", \"vi\": \"Thiết kế tòa nhà ban đầu của Cresson\'s Bakery mang phong cách đương đại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I am pleased to report that the chain has agreed to modify the exterior so that it blends in better with the older structures surrounding it.\", \"vi\": \"Tôi rất vui mừng được thông báo rằng chuỗi cửa hàng đã đồng ý sửa đổi phần ngoại thất để nó hài hòa hơn với các công trình kiến trúc cổ kính xung quanh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Gina Holton\", \"vi\": \"Gina Holton\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '2bfe51a6-a412-44ec-87ec-7fb7edaf7c8a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Course ID - Class Time - Instructor - Room\", \"vi\": \"Mã khóa học - Thời gian học - Giảng viên - Phòng học\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"249800:01 - Tuesday 5:30–7:30 P.M. - Patrick McCann - 211\", \"vi\": \"249800:01 - Thứ Ba, 5:30–7:30 chiều - Patrick McCann - Phòng 211\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"249800:02 - Saturday 1:00–3:00 P.M. - Nora Farid - 166\", \"vi\": \"249800:02 - Thứ Bảy, 1:00–3:00 chiều - Nora Farid - 166\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Course ID - Class Time - Instructor - Room\", \"vi\": \"Mã môn học - Thời gian học - Giảng viên - Phòng học\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"225810:01 - Thursday 5:30–8:30 P.M. - Remi Sanders - 118\", \"vi\": \"225810:01 - Thứ Năm, 5 giờ 30 – 8 giờ 30 tối - Remi Sanders - 118\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"225810:02 - Sunday 1:00–4:00 P.M. - Nora Farid - 315\", \"vi\": \"225810:02 - Chủ nhật, 1:00–4:00 chiều - Nora Farid - 315\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Springfield Community School\", \"vi\": \"Trường Cộng đồng Springfield\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Computer Courses\", \"vi\": \"Các khóa học về máy tính\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Internet Safety\", \"vi\": \"An toàn trên Internet\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This course teaches students everything they need to navigate the Web safely.\", \"vi\": \"Khóa học này hướng dẫn học viên mọi kiến thức cần thiết để lướt web một cách an toàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Spreadsheet Basics\", \"vi\": \"Kiến thức cơ bản về bảng tính\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"This course teaches the basics of online spreadsheets.\", \"vi\": \"Khóa học này giới thiệu những kiến thức cơ bản về bảng tính trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Students will learn how to create effective charts for calculating and analyzing data clearly and easily.\", \"vi\": \"Học sinh sẽ được học cách tạo các biểu đồ hiệu quả để tính toán và phân tích dữ liệu một cách rõ ràng và dễ dàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '2c103d75-f7d6-44cf-8a8e-7dc7f577e5fe';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All staff\", \"vi\": \"Đến: Tất cả nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Leonard Villalobos, Vice President of Product Development\", \"vi\": \"Từ: Leonard Villalobos, Phó Chủ tịch Bộ phận Phát triển Sản phẩm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: August 27\", \"vi\": \"Ngày: 27 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Atzeret game (Product #DS8192)\", \"vi\": \"Chủ đề: Trò chơi Atzeret (Sản phẩm #DS8192)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Due to the results from our trial customer testing, we have decided to postpone the launch of the Atzeret video game.\", \"vi\": \"Do kết quả từ quá trình thử nghiệm với khách hàng, chúng tôi đã quyết định hoãn việc ra mắt trò chơi điện tử Atzeret.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Customer surveys indicated that the game was less ______[131] than we anticipated.\", \"vi\": \"Các cuộc khảo sát khách hàng chỉ ra rằng trò chơi này ít ______[131] hơn so với chúng tôi dự đoán.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [131]}, {\"en\": \"Over the next few months, the game development team will introduce several ______[132] to make the product more attractive.\", \"vi\": \"Trong vài tháng tới, đội ngũ phát triển trò chơi sẽ giới thiệu một số ______[132] để làm cho sản phẩm hấp dẫn hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [132]}, {\"en\": \"______[133].\", \"vi\": \"______[133].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [133]}, {\"en\": \"If the changes are successful, we hope to launch the game by next January ______[134] February.\", \"vi\": \"Nếu các thay đổi thành công, chúng tôi hy vọng sẽ ra mắt trò chơi vào tháng Giêng ______[134] tháng Hai tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [134]}]' WHERE `id` = '2c661c40-e5b0-40df-803e-4cfb66af2ddb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Type - Description - Minimum Order\", \"vi\": \"Loại - Mô tả - Số lượng đặt hàng tối thiểu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Matte-M1 - Standard card stock, reduces glare - 50 cards\", \"vi\": \"Matte-M1 - Giấy bìa tiêu chuẩn, giảm chói - 50 thẻ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Glossy-G4 - Shiny, enhances colors and details - 100 cards\", \"vi\": \"Glossy-G4 - Bề mặt bóng loáng, làm nổi bật màu sắc và chi tiết - 100 thẻ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Textured-T3 - Unique grid-like pattern, interesting to the touch - 100 cards\", \"vi\": \"Textured-T3 - Hoa văn dạng lưới độc đáo, mang lại cảm giác thú vị khi chạm vào - 100 lá bài\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Metallic-M2 - Extra shiny, unique, captures one’s attention - 200 cards\", \"vi\": \"Metallic-M2 - Bóng loáng vượt trội, độc đáo, thu hút mọi ánh nhìn - 200 lá bài\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Get Business Cards Custom Made by You\", \"vi\": \"Đặt làm danh thiếp theo thiết kế riêng của quý vị\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Loretti Printing Co. is proud to announce loretticardprint.com, our new online platform for creating customized business cards.\", \"vi\": \"Công ty In ấn Loretti hân hạnh giới thiệu loretticardprint.com – nền tảng trực tuyến mới của chúng tôi dành cho việc thiết kế danh thiếp theo yêu cầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"While our customers can still place orders in person, as they’ve done for nearly a decade, we now have a system that makes ordering business cards especially quick and easy.\", \"vi\": \"Mặc dù quý khách hàng vẫn có thể đặt hàng trực tiếp tại cửa hàng, như quý vị đã làm trong gần một thập kỷ qua, nhưng hiện nay chúng tôi đã có một hệ thống giúp việc đặt hàng danh thiếp trở nên đặc biệt nhanh chóng và dễ dàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Choose from hundreds of easy-to-use templates, include your own text and images, and create professional-quality business cards within minutes.\", \"vi\": \"Hãy lựa chọn từ hàng trăm mẫu thiết kế dễ sử dụng, thêm nội dung văn bản và hình ảnh của riêng quý vị, và tạo ra những tấm danh thiếp chất lượng chuyên nghiệp chỉ trong vài phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We offer four different paper options:\", \"vi\": \"Chúng tôi cung cấp bốn loại giấy khác nhau:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Contact us before placing an online order if you’d like us to send you a sample of each type of paper.\", \"vi\": \"Vui lòng liên hệ với chúng tôi trước khi đặt hàng trực tuyến nếu quý vị muốn chúng tôi gửi mẫu thử của từng loại giấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: hello@loretticardprint.com\", \"vi\": \"Gửi tới: hello@loretticardprint.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From: felix@thibaultautoworks.com\", \"vi\": \"Nguồn: felix@thibaultautoworks.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: Tuesday, May 22\", \"vi\": \"Ngày: Thứ Ba, ngày 22 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Subject: Order 28191 - Follow-up\", \"vi\": \"Chủ đề: Lệnh số 28191 – Theo dõi\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Attachment: Logo_autoworks\", \"vi\": \"Tệp đính kèm: Logo_autoworks\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thanks for pausing my order right away and explaining how to make the necessary changes.\", \"vi\": \"Xin cảm ơn quý công ty đã tạm dừng đơn hàng của tôi ngay lập tức và hướng dẫn cách thực hiện các thay đổi cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I’m so glad I was able to get in touch before my business cards went off to print.\", \"vi\": \"Tôi thực sự rất vui vì đã kịp liên hệ trước khi danh thiếp của tôi được đưa đi in.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"It would have been such a shame to have printed 50 cards I can’t use.\", \"vi\": \"Thật là đáng tiếc nếu tôi in ra 50 tấm thiệp mà lại không thể sử dụng được.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"As I mentioned over the phone, I had accidentally uploaded an older version of my logo to the Web site.\", \"vi\": \"Như tôi đã đề cập qua điện thoại, tôi đã vô tình tải lên trang web một phiên bản cũ hơn của logo của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I’ve since replaced it with the current one in the same file size, and I’m hoping you can confirm that this change reflects the image I’ve included here.\", \"vi\": \"Từ đó đến nay, tôi đã thay thế nó bằng hình ảnh hiện tại có cùng kích thước tệp, và tôi hy vọng quý vị có thể xác nhận rằng sự thay đổi này phản ánh đúng hình ảnh mà tôi đã đính kèm ở đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"If so, please go ahead and submit my order now.\", \"vi\": \"Nếu vậy, xin vui lòng tiến hành gửi đơn hàng của tôi ngay bây giờ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Xin cảm ơn.\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Felix Thibault\", \"vi\": \"Felix Thibault\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}]' WHERE `id` = '2c81b4dc-ca68-40ec-9a94-680ba7a6184c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.sunnywelcomehotel.co.in\", \"vi\": \"https://www.sunnywelcomehotel.co.in\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"At the Sunny Welcome Hotel in Kolkata, we work hard to ensure that you enjoy your stay.\", \"vi\": \"Tại Khách sạn Sunny Welcome ở Kolkata, chúng tôi luôn nỗ lực hết mình để đảm bảo quý khách có một kỳ nghỉ thật thoải mái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Please note:\", \"vi\": \"Xin lưu ý:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"• Each room has a coffeemaker and complimentary coffee and tea.\", \"vi\": \"• Mỗi phòng đều được trang bị máy pha cà phê cùng cà phê và trà miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Guests may purchase snacks and other beverages in the vending areas located on each floor.\", \"vi\": \"Quý khách có thể mua đồ ăn nhẹ và các loại đồ uống khác tại các khu vực máy bán hàng tự động đặt ở mỗi tầng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"• Guests with small children may request a rollaway bed or crib for their rooms for no additional charge.\", \"vi\": \"• Quý khách có trẻ nhỏ có thể yêu cầu cung cấp giường gấp hoặc cũi trong phòng mà không phải trả thêm phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"• The business center is open from 9:00 A.M. to 5:00 P.M. each day.\", \"vi\": \"• Trung tâm dịch vụ doanh nghiệp mở cửa từ 9 giờ sáng đến 5 giờ chiều hàng ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"• The swimming pool and children\'s playground are open during daylight hours.\", \"vi\": \"• Hồ bơi và khu vui chơi dành cho trẻ em mở cửa trong giờ ban ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Children must always be supervised by an adult.\", \"vi\": \"Trẻ em phải luôn có người lớn trông coi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"• A deposit is necessary to guarantee a room reservation.\", \"vi\": \"• Quý khách cần đặt cọc để đảm bảo việc đặt phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The deposit will only be refunded if the reservation is cancelled or changed more than 24 hours prior to arrival.\", \"vi\": \"Khoản đặt cọc sẽ chỉ được hoàn lại nếu việc đặt phòng bị hủy hoặc thay đổi trước ít nhất 24 giờ so với thời điểm đến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"• Guests may check in as early as 2:00 P.M. Checkout after noon on the day of departure is subject to an additional charge.\", \"vi\": \"• Quý khách có thể làm thủ tục nhận phòng sớm nhất từ 2 giờ chiều. Nếu quý khách trả phòng sau 12 giờ trưa vào ngày rời khách sạn, quý khách sẽ phải trả thêm phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"• Guests are required to present a passport or driver\'s license at the time of check-in.\", \"vi\": \"• Quý khách vui lòng xuất trình hộ chiếu hoặc giấy phép lái xe tại thời điểm làm thủ tục nhận phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"• We offer free shuttle service to the airport.\", \"vi\": \"• Chúng tôi cung cấp dịch vụ đưa đón miễn phí đến sân bay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Guests can make arrangements at the front desk.\", \"vi\": \"Quý khách có thể liên hệ với quầy lễ tân để sắp xếp các thủ tục.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"• Our reception desk is staffed 24 hours a day.\", \"vi\": \"• Quầy lễ tân của chúng tôi có nhân viên túc trực 24 giờ mỗi ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"To: generalmanager@sunnywelcomehotel.co.in\", \"vi\": \"Gửi tới: generalmanager@sunnywelcomehotel.co.in\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"From: samuelramon@myemail.co.uk\", \"vi\": \"Nguồn: samuelramon@myemail.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Date: 13 May\", \"vi\": \"Ngày: 13 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Subject: Reservation number EX52417\", \"vi\": \"Chủ đề: Số đặt chỗ EX52417\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Xin chào\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"My family and I were very comfortable in the family suite at the Sunny Welcome Hotel in Kolkata last year, and we were looking forward to returning this year for a week starting on 17 April.\", \"vi\": \"Năm ngoái, gia đình tôi và tôi đã có một kỳ nghỉ rất thoải mái tại phòng suite dành cho gia đình của Khách sạn Sunny Welcome ở Kolkata, và chúng tôi rất mong được quay lại đây vào năm nay để nghỉ dưỡng trong một tuần, bắt đầu từ ngày 17 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Unfortunately, we suddenly had to postpone our trip until June, so I called the hotel on the morning of 17 April to change our reservation dates.\", \"vi\": \"Thật không may, chúng tôi bất ngờ phải hoãn chuyến đi đến tháng 6, vì vậy sáng ngày 17 tháng 4, tôi đã gọi điện cho khách sạn để thay đổi ngày đặt phòng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I thought everything was in order, but when I opened my credit card statement this month, I discovered an additional charge from the Sunny Welcome Hotel.\", \"vi\": \"Tôi tưởng mọi việc đều đã ổn thỏa, nhưng khi mở bản sao kê thẻ tín dụng của tháng này, tôi phát hiện ra một khoản phí bổ sung từ Khách sạn Sunny Welcome.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Could you please look into the matter?\", \"vi\": \"Xin quý vị vui lòng xem xét vấn đề này được không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I believe that an error has been made and that I should be reimbursed.\", \"vi\": \"Tôi cho rằng đã xảy ra một sai sót và tôi nên được hoàn lại tiền.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I would appreciate having the money credited to my account.\", \"vi\": \"Tôi rất mong số tiền này sẽ được chuyển vào tài khoản của tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"We still plan to return to Kolkata later this year and anticipate an enjoyable stay at your hotel.\", \"vi\": \"Chúng tôi vẫn dự định sẽ quay trở lại Kolkata vào cuối năm nay và mong rằng sẽ có một kỳ nghỉ thú vị tại khách sạn của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Yours sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Samuel Ramon\", \"vi\": \"Samuel Ramon\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}]' WHERE `id` = '2cca8b0e-e7c2-413b-97a8-21298f040fb2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"New Home for Theatre Group\", \"vi\": \"Ngôi nhà mới của nhóm kịch\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"AUCKLAND (11 July)—The south end of Darby Street is dominated by the imposing Victorian building that formerly held the main branch of Pacific Trade Bank.\", \"vi\": \"AUCKLAND (ngày 11 tháng 7) — Phía nam đường Darby Street nổi bật với tòa nhà kiến trúc Victoria uy nghi, nơi trước đây từng là trụ sở chính của Ngân hàng Pacific Trade.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"That building is now the home of the Cornata Theatre Company.\", \"vi\": \"Tòa nhà đó hiện là trụ sở của Đoàn kịch Cornata.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"After a grand-opening ceremony on Tuesday, tours of the new theatre were given to attendees.\", \"vi\": \"Sau lễ khai trương long trọng diễn ra vào thứ Ba, các vị khách tham dự đã được hướng dẫn tham quan nhà hát mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The debut show is Relax, a comedy by Mi-Sun Yeo about a popular tourist site.\", \"vi\": \"Vở diễn ra mắt là *Relax*, một vở hài kịch của Mi-Sun Yeo xoay quanh một địa điểm du lịch nổi tiếng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Performances are scheduled to begin on Saturday, 16 July, and run until the end of the month.\", \"vi\": \"Các buổi biểu diễn dự kiến sẽ bắt đầu vào thứ Bảy, ngày 16 tháng 7, và kéo dài đến hết tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"According to Noah Larkins, the artistic director of the Cornata Theatre Company \\\"talk-backs\\\" will immediately follow every performance.\", \"vi\": \"Theo ông Noah Larkins, Giám đốc nghệ thuật của Công ty Sân khấu Cornata, các buổi “trao đổi sau buổi diễn” sẽ diễn ra ngay sau mỗi buổi biểu diễn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Talk-backs allow the director and cast members to share their thoughts about the play, and audience members can ask them questions.\", \"vi\": \"Các buổi thảo luận sau buổi diễn giúp đạo diễn và các diễn viên chia sẻ suy nghĩ của mình về vở kịch, đồng thời khán giả cũng có thể đặt câu hỏi cho họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"We want to be part of the artistic communities in both Auckland and the larger community around us,\\\" said Mr. Larkins.\", \"vi\": \"\\\"Chúng tôi mong muốn trở thành một phần của các cộng đồng nghệ thuật tại cả Auckland lẫn cộng đồng rộng lớn hơn xung quanh chúng tôi,\\\" ông Larkins phát biểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The building houses a main stage theatre that seats approximately 325 people and a smaller studio theatre upstairs.\", \"vi\": \"Tòa nhà này có một nhà hát sân khấu chính với sức chứa khoảng 325 chỗ ngồi và một nhà hát studio nhỏ hơn ở tầng trên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The company will also offer acting classes for children and adults.\", \"vi\": \"Công ty cũng sẽ tổ chức các lớp học diễn xuất dành cho trẻ em và người lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"For more information or to buy tickets, visit the company\'s Web page at www.cornatatheatre.nz.\", \"vi\": \"Để biết thêm thông tin hoặc mua vé, quý vị vui lòng truy cập trang web của công ty tại địa chỉ www.cornatatheatre.nz.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you for attending Relax.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã tham dự sự kiện Relax.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please take a few moments to tell us about your experience.\", \"vi\": \"Xin quý vị dành một chút thời gian để chia sẻ với chúng tôi về trải nghiệm của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Name and e-mail address: Julia Cruz <jcruz@northwing.nz>\", \"vi\": \"Họ tên và địa chỉ email: Julia Cruz <jcruz@northwing.nz>\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"1.\", \"vi\": \"1.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"How would you rate the performance you saw?\", \"vi\": \"Quý vị đánh giá thế nào về vở diễn mà quý vị vừa xem?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Excellent X___ Good ____ Fair ____ Did not enjoy ____\", \"vi\": \"Xuất sắc X___ Tốt ____ Khá ____ Không thích ____\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"2.\", \"vi\": \"2.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"How would you rate your overall theatre experience?\", \"vi\": \"Quý vị đánh giá thế nào về trải nghiệm xem kịch nói chung của mình?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Excellent ____ Good X___ Fair ____ Did not enjoy ____\", \"vi\": \"Xuất sắc ____ Tốt X___ Khá ____ Không thích ____\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"3.\", \"vi\": \"3.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"How did you hear about us?\", \"vi\": \"Quý vị đã biết đến chúng tôi qua đâu?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"(Check all that apply.)\", \"vi\": \"(Vui lòng đánh dấu vào tất cả các lựa chọn phù hợp.)\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Print advertisement X___ Social media X___ Television ____ E-mail ____\", \"vi\": \"Quảng cáo trên báo in X___ Mạng xã hội X___ Truyền hình ____ Email ____\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Comments: The play was a fascinating story, and the acting was brilliant.\", \"vi\": \"Nhận xét: Vở kịch kể một câu chuyện vô cùng hấp dẫn, và diễn xuất của các diễn viên thật xuất sắc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I\'m delighted to be a subscribing member of the theatre this season.\", \"vi\": \"Tôi rất vui mừng khi trở thành thành viên đăng ký của nhà hát trong mùa diễn này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"If all the shows are this good, I\'ll be very happy.\", \"vi\": \"Nếu tất cả các chương trình đều hay như thế này, tôi sẽ rất vui.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"There did seem to be a problem with the concession stand.\", \"vi\": \"Quả thực dường như có một vấn đề gì đó xảy ra với quầy bán đồ ăn nhẹ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"There was a long line for food and drinks, and it did not move very quickly.\", \"vi\": \"Có một hàng người dài chờ mua đồ ăn và đồ uống, và hàng người này di chuyển không nhanh lắm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}]' WHERE `id` = '2cebf28e-ba0e-416e-8f2a-d2e674979368';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Your upgraded Impala card is in the mail!\", \"vi\": \"Thẻ Impala đã được nâng cấp của quý vị đang được gửi qua đường bưu điện!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"At Impala Credit Union, your safety and convenience are paramount.\", \"vi\": \"Tại Impala Credit Union, sự an toàn và sự thuận tiện của quý khách luôn là ưu tiên hàng đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"That is why we are introducing contactless technology for all our member credit and debit cards.\", \"vi\": \"Chính vì lý do đó, chúng tôi xin giới thiệu công nghệ thanh toán không tiếp xúc cho tất cả các thẻ tín dụng và thẻ ghi nợ của các thành viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"With this new development, you will no longer have to swipe or insert your card in a chip reader at checkout.\", \"vi\": \"Với sự phát triển mới này, quý vị sẽ không còn phải quẹt thẻ hay đưa thẻ vào đầu đọc chip khi thanh toán nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"In fact, you will not even need to remove your card from a physical wallet; simply hold it near a point of sale for it to be read!\", \"vi\": \"Thực tế, quý vị thậm chí không cần phải lấy thẻ ra khỏi ví vật lý; chỉ cần đưa thẻ lại gần thiết bị thanh toán là thẻ sẽ được đọc ngay!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"There are a few important things to keep in mind.\", \"vi\": \"Có một số điều quan trọng cần lưu ý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"First, your current card will be deactivated on October 31.\", \"vi\": \"Trước hết, thẻ hiện tại của quý vị sẽ bị vô hiệu hóa vào ngày 31 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You may continue to use it until that time.\", \"vi\": \"Quý vị có thể tiếp tục sử dụng nó cho đến thời điểm đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Second, the upgraded card may arrive before your current one expires.\", \"vi\": \"Thứ hai, thẻ nâng cấp có thể sẽ được gửi đến trước khi thẻ hiện tại của quý vị hết hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Once you activate the new card, the old one will automatically be deactivated and no longer be valid for use.\", \"vi\": \"Ngay sau khi quý vị kích hoạt thẻ mới, thẻ cũ sẽ tự động bị vô hiệu hóa và không còn giá trị sử dụng nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"You will need to manually activate your new card by following the instructions on the attached sticker.\", \"vi\": \"Quý vị sẽ cần kích hoạt thẻ mới của mình theo cách thủ công bằng cách làm theo hướng dẫn trên nhãn dán kèm theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Third, your contactless technology card will have a new card number, expiration date, and security number.\", \"vi\": \"Thứ ba, thẻ công nghệ không tiếp xúc của quý vị sẽ có số thẻ, ngày hết hạn và mã bảo mật mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"When activating, you will be prompted to choose a PIN (personal identification number).\", \"vi\": \"Khi kích hoạt, quý vị sẽ được yêu cầu chọn một mã PIN (mã số nhận dạng cá nhân).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The PIN from your current card will not automatically transfer over.\", \"vi\": \"Mã PIN của thẻ hiện tại của quý vị sẽ không được chuyển sang tự động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Be sure to update your card on file for all preferred online retailers and app subscriptions to ensure continued access.\", \"vi\": \"Hãy nhớ cập nhật thông tin thẻ thanh toán đã đăng ký của quý vị tại tất cả các nhà bán lẻ trực tuyến và dịch vụ đăng ký ứng dụng mà quý vị ưa thích để đảm bảo quyền truy cập liên tục.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We hope that you enjoy your new card.\", \"vi\": \"Chúng tôi hy vọng quý vị sẽ hài lòng với thẻ mới của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"For any questions regarding your contactless technology Impala card, feel free to contact customer service at 1-610-555-0168.\", \"vi\": \"Nếu có bất kỳ thắc mắc nào liên quan đến thẻ Impala công nghệ không tiếp xúc của quý vị, xin vui lòng liên hệ với bộ phận dịch vụ khách hàng theo số 1-610-555-0168.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '2cfd1708-3d90-4a31-908e-8da76dfd66f5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Haruka Maeda <hmaeda@frantaexports.co.uk>\", \"vi\": \"Gửi tới: Haruka Maeda <hmaeda@frantaexports.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Jerome Lennox <j.lennox@silkmail.co.uk>\", \"vi\": \"Từ: Jerome Lennox <j.lennox@silkmail.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 7 May\", \"vi\": \"Ngày: 7 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Job 3723\", \"vi\": \"Chủ đề: Vị trí tuyển dụng số 3723\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: lennox_résumé\", \"vi\": \"Tệp đính kèm: lennox_tóm tắt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Ms. Maeda,\", \"vi\": \"Kính gửi bà Maeda,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I am writing regarding the open office manager position (job 3723) at Franta Exports here in my hometown of Liverpool.\", \"vi\": \"Tôi viết thư này để ứng tuyển vào vị trí Quản lý văn phòng đang tuyển dụng (mã việc làm 3723) tại công ty Franta Exports, tọa lạc tại thành phố Liverpool – quê hương của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"With eight years of experience in office management and administration, I am confident that I have the skills and expertise required to excel in this role.\", \"vi\": \"Với tám năm kinh nghiệm trong lĩnh vực quản lý và điều hành văn phòng, tôi tin tưởng rằng mình có đủ kỹ năng và chuyên môn cần thiết để hoàn thành xuất sắc vai trò này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In my current position as office manager at Wyler International, I am responsible for managing all aspects of office operations, including budgeting, scheduling, and staff management.\", \"vi\": \"Trong cương vị hiện tại là Trưởng phòng Hành chính tại Wyler International, tôi chịu trách nhiệm quản lý mọi khía cạnh của hoạt động văn phòng, bao gồm lập ngân sách, lập lịch trình và quản lý nhân sự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"My résumé is attached.\", \"vi\": \"Tôi xin đính kèm sơ yếu lý lịch của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I am excited about the possibility of bringing my skills and experience to Franta Exports.\", \"vi\": \"Tôi rất hào hứng trước cơ hội được đóng góp những kỹ năng và kinh nghiệm của mình cho Franta Exports.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I look forward to hearing from you soon.\", \"vi\": \"Tôi mong sớm nhận được phản hồi từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Jerome Lennox\", \"vi\": \"Jerome Lennox\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To: Jerome Lennox <j.lennox@silkmail.co.uk>\", \"vi\": \"Gửi: Jerome Lennox <j.lennox@silkmail.co.uk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"From: Haruka Maeda <hmaeda@frantaexports.co.uk>\", \"vi\": \"Từ: Haruka Maeda <hmaeda@frantaexports.co.uk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date: 23 May\", \"vi\": \"Ngày: 23 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Subject: Upcoming interview\", \"vi\": \"Chủ đề: Buổi phỏng vấn sắp tới\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Dear Mr. Lennox,\", \"vi\": \"Kính gửi ông Lennox,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Please respond to this e-mail to verify your intention to participate in a telephone interview with Franta Exports.\", \"vi\": \"Kính mong Quý vị trả lời email này để xác nhận ý định tham gia buổi phỏng vấn qua điện thoại với Franta Exports.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"You are scheduled for an interview with Alisha Scott at 11 A.M. on 28 May for the office manager position.\", \"vi\": \"Quý vị đã được sắp xếp một buổi phỏng vấn với bà Alisha Scott vào lúc 11 giờ sáng ngày 28 tháng 5 cho vị trí Trưởng phòng hành chính.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Your initial interview is scheduled as an online telephone appointment.\", \"vi\": \"Buổi phỏng vấn đầu tiên của quý vị đã được sắp xếp dưới hình thức cuộc hẹn qua điện thoại trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"You may call from a smartphone or a computer.\", \"vi\": \"Quý vị có thể gọi điện từ điện thoại thông minh hoặc máy tính.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"However, please ensure that you have a stable Internet connection.\", \"vi\": \"Tuy nhiên, xin vui lòng đảm bảo rằng quý vị có kết nối Internet ổn định.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"We will send you a text message 30 minutes before your scheduled interview with further instructions.\", \"vi\": \"Chúng tôi sẽ gửi cho quý vị một tin nhắn văn bản 30 phút trước giờ phỏng vấn đã hẹn kèm theo các hướng dẫn chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Within two days following your online interview, we will inform you whether we would like to schedule a follow-up in-person appointment at our headquarters in Portsmouth.\", \"vi\": \"Trong vòng hai ngày sau buổi phỏng vấn trực tuyến của quý vị, chúng tôi sẽ thông báo cho quý vị biết liệu chúng tôi có muốn sắp xếp một cuộc hẹn tiếp theo trực tiếp tại trụ sở chính của chúng tôi ở Portsmouth hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Haruka Maeda, Human Resources Associate\", \"vi\": \"Haruka Maeda, Chuyên viên Nhân sự\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Welcome to the Franta Exports Liverpool Office!\", \"vi\": \"Chào mừng quý vị đến với Văn phòng Franta Exports tại Liverpool!\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Office hours: Monday to Saturday from 8 A.M. to 4 P.M.\", \"vi\": \"Giờ làm việc: Từ thứ Hai đến thứ Bảy, từ 8 giờ sáng đến 4 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Office manager: Jerome Lennox\", \"vi\": \"Trưởng phòng hành chính: Jerome Lennox\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Franta Exports has eighteen offices worldwide, including five in the United Kingdom at the following convenient locations.\", \"vi\": \"Franta Exports hiện có mười tám văn phòng trên toàn thế giới, trong đó có năm văn phòng tại Vương quốc Anh, tọa lạc tại các địa điểm thuận tiện sau đây.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"732 Park Avenue, Portsmouth PO5 3QQ (U.K. Headquarters)\", \"vi\": \"732 Park Avenue, Portsmouth PO5 3QQ (Trụ sở chính tại Vương quốc Anh)\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"10 Donegal Lane, Belfast BT1 3JF\", \"vi\": \"10 Donegal Lane, Belfast BT1 3JF\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"660 Richmond Avenue, Cardiff CF24 2PX\", \"vi\": \"660 Richmond Avenue, Cardiff CF24 2PX\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"42 Church Road, Edinburgh EH4 6DU\", \"vi\": \"42 Church Road, Edinburgh EH4 6DU\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"9233 Victoria Street, Liverpool CH44 6PX\", \"vi\": \"9233 Victoria Street, Liverpool CH44 6PX\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}]' WHERE `id` = '2d091176-eb28-4033-8962-970a026b16c4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"HILLSIDE MANOR\\n222 Jackson Rd.\\nFeatures:\\n\\n2- and 3-bedroom units with washer and dryer\\nSwimming pool plus basketball and tennis courts\\nChildren\'s park nearby\\nTop-rated schools in the area\\nFive minutes from the business district\\nPet-friendly environment - LAKEVIEW OAKS\\n119 E. Corfu St.\\nFeatures:\\n\\n1-bedroom units with large kitchens and baths\\nHardwood floors\\nCommunity laundry room on each floor\\nFitness center and outdoor swimming pool\\nTen minutes from business district\\nAccess to multiple bus lines right outside your door\\nPet-friendly environment\", \"vi\": \"HILLSIDE MANOR\\n222 Jackson Rd.\\nTiện ích:\\n\\nCác căn hộ 2 và 3 phòng ngủ, trang bị máy giặt và máy sấy\\nHồ bơi cùng sân bóng rổ và sân quần vợt\\nCông viên trẻ em gần đó\\nCác trường học được đánh giá cao nhất trong khu vực\\nCách khu thương mại 5 phút\\nMôi trường thân thiện với thú cưng - LAKEVIEW OAKS\\n119 E. Corfu St.\\nTính năng:\\n\\nCác căn hộ 1 phòng ngủ với nhà bếp và phòng tắm rộng rãi\\nSàn gỗ cứng\\nPhòng giặt ủi chung trên mỗi tầng\\nTrung tâm thể dục và hồ bơi ngoài trời\\nCách khu thương mại 10 phút\\nTiếp cận nhiều tuyến xe buýt ngay trước cửa nhà\\nMôi trường thân thiện với thú cưng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"WESTWOOD PROPERTIES, INC.\", \"vi\": \"CÔNG TY CỔ PHẦN WESTWOOD PROPERTIES\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Residential Communities\", \"vi\": \"Các khu dân cư\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Westwood Properties, Inc. (WPI), has two residential apartment communities in the city of Kentville.\", \"vi\": \"Công ty Westwood Properties, Inc. (WPI) hiện đang sở hữu hai khu chung cư tại thành phố Kentville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Visit our Web site at www.westwoodproperties.com to view floor plans or to schedule a personal tour.\", \"vi\": \"Hãy truy cập trang web của chúng tôi tại địa chỉ www.westwoodproperties.com để xem sơ đồ mặt bằng hoặc đặt lịch tham quan riêng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Sales agents are available at our offices to answer your questions Monday through Friday from 9:00 A.M. to 5:00 P.M., and on Saturday and Sunday from 12:00 noon to 5:00 P.M.\", \"vi\": \"Các nhân viên kinh doanh tại văn phòng của chúng tôi sẵn sàng giải đáp thắc mắc của quý khách từ thứ Hai đến thứ Sáu, từ 9 giờ sáng đến 5 giờ chiều, và vào thứ Bảy và Chủ Nhật, từ 12 giờ trưa đến 5 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"WPI Announces Expansion\", \"vi\": \"WPI công bố kế hoạch mở rộng\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"KENTVILLE (March 16)—Westwood Properties, Inc. (WPI), in partnership with the Kentville city government, will be constructing its third residential development in Kentville.\", \"vi\": \"KENTVILLE (ngày 16 tháng 3) — Công ty Westwood Properties, Inc. (WPI), phối hợp với chính quyền thành phố Kentville, sẽ triển khai dự án phát triển khu dân cư thứ ba tại Kentville.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The new development, Green Valley Court, will consist of 150 freestanding homes.\", \"vi\": \"Dự án mới mang tên Green Valley Court sẽ bao gồm 150 căn nhà biệt lập.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Work will begin in April and is expected to be completed in eighteen months.\", \"vi\": \"Công việc sẽ bắt đầu vào tháng Tư và dự kiến sẽ hoàn thành trong mười tám tháng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"WPI will bear 60 percent of the costs, while the remainder will be borne by the city government.\", \"vi\": \"WPI sẽ chi trả 60% chi phí, trong khi phần còn lại sẽ do chính quyền thành phố chi trả.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"WPI has built a reputation for providing comfortable living at affordable prices.\", \"vi\": \"WPI đã tạo dựng được danh tiếng nhờ mang đến cuộc sống tiện nghi với mức giá phải chăng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Its current residential developments, Hillside Manor and Lakeview Oaks, were built five years ago and are much in demand, with long waiting lists.\", \"vi\": \"Các dự án nhà ở hiện tại của công ty, bao gồm Hillside Manor và Lakeview Oaks, được xây dựng cách đây năm năm và đang rất được ưa chuộng, với danh sách chờ kéo dài.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"According to Helen Hart, a marketing executive for WPI, Green Valley Court will be located twenty minutes from the business district.\", \"vi\": \"Theo bà Helen Hart, một giám đốc tiếp thị của WPI, khu Green Valley Court sẽ tọa lạc cách khu thương mại khoảng hai mươi phút đi xe.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Ms. Hart went on to say that \\\"Green Valley Court will be ideal for retirees and those longing for some rest and relaxation after a hard day\'s work.\\\"\", \"vi\": \"Bà Hart tiếp tục cho biết: “Green Valley Court sẽ là nơi lý tưởng dành cho những người đã nghỉ hưu và những ai mong muốn được nghỉ ngơi, thư giãn sau một ngày làm việc vất vả.”\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '2d0ab7d4-c290-4093-9570-e8c104ecb1e4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Sumner Woodcrafting\", \"vi\": \"Sumner Woodcrafting\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Sumner Woodcrafting of Memphis, Tennessee, was established nearly 45 years ago by Kiran Sumner, with the goal of providing personalized service to customers seeking high-quality, handmade furniture.\", \"vi\": \"Công ty Sumner Woodcrafting tại Memphis, Tennessee, được thành lập cách đây gần 45 năm bởi ông Kiran Sumner, với mục tiêu mang đến dịch vụ cá nhân hóa cho những khách hàng đang tìm kiếm đồ nội thất thủ công chất lượng cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Now semiretired, Mr. Sumner still takes orders and responds to questions himself through the company\'s customer-service telephone line at 901-555-0185 on Thursdays and Fridays.\", \"vi\": \"Dù hiện đã nghỉ hưu một phần, ông Sumner vẫn trực tiếp nhận đơn đặt hàng và giải đáp thắc mắc qua đường dây điện thoại chăm sóc khách hàng của công ty theo số 901-555-0185 vào các ngày thứ Năm và thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Sumner Woodcrafting offers a wide selection of custom-made bedroom sets, tables, desks, cabinetry, and more—all made from high-quality solid woods.\", \"vi\": \"Sumner Woodcrafting cung cấp nhiều lựa chọn đa dạng về các bộ đồ nội thất phòng ngủ, bàn, bàn làm việc, tủ kệ và nhiều sản phẩm khác được chế tác theo yêu cầu — tất cả đều được làm từ gỗ nguyên khối chất lượng cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Prices for handcrafted furniture are naturally higher than for furniture that is mass-produced in a factory.\", \"vi\": \"Giá của đồ nội thất làm thủ công đương nhiên cao hơn so với đồ nội thất được sản xuất hàng loạt tại nhà máy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Because our master crafters do exceptionally fine work, our customers never regret spending a bit more for pieces built to last for generations.\", \"vi\": \"Chính nhờ tay nghề điêu luyện của các nghệ nhân bậc thầy mà những sản phẩm của chúng tôi được chế tác vô cùng tinh xảo, nên quý khách hàng chưa bao giờ hối tiếc khi chi trả thêm một chút chi phí để sở hữu những tác phẩm được chế tác để tồn tại qua nhiều thế hệ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Note that it can take up to two months to create a piece of furniture once it is ordered.\", \"vi\": \"Xin lưu ý rằng quá trình chế tác một món đồ nội thất có thể mất tới hai tháng kể từ khi nhận được đơn đặt hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Delivery fees are based on distance from our workshop.\", \"vi\": \"Phí giao hàng được tính dựa trên khoảng cách từ xưởng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Unpacking and placing the item is available for an additional $50.\", \"vi\": \"Dịch vụ mở hộp và sắp xếp sản phẩm có sẵn với chi phí thêm 50 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"For photos of our workshop, artisan biographies, customer reviews, and ordering information, please visit us online at www.sumnerwoodcrafting.com.\", \"vi\": \"Để xem hình ảnh về xưởng sản xuất của chúng tôi, tiểu sử các nghệ nhân, đánh giá của khách hàng và thông tin đặt hàng, xin vui lòng truy cập trang web của chúng tôi tại www.sumnerwoodcrafting.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '2d3027da-fdb3-48b6-9e4e-4879ae252dc3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Callum Stevenson\", \"vi\": \"Callum Stevenson\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"42 Leicester Road\", \"vi\": \"42 Leicester Road\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Girvaton, P24 9QS\", \"vi\": \"Girvaton, P24 9QS\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"3 January\", \"vi\": \"Ngày 3 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Stevenson,\", \"vi\": \"Kính gửi ông Stevenson,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We are happy to have you as part of the Kendinburgh Transit team.\", \"vi\": \"Chúng tôi rất vui mừng chào đón quý vị gia nhập đội ngũ Kendinburgh Transit.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Prior to your receiving training on the vehicle you will be assigned to, we must first ensure that your medical documentation is up-to-date.\", \"vi\": \"Trước khi quý vị tham gia khóa huấn luyện về phương tiện mà quý vị sẽ được phân công điều khiển, chúng tôi cần đảm bảo rằng hồ sơ y tế của quý vị đã được cập nhật đầy đủ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The main priority of public transport is the safety of passengers and other motorists.\", \"vi\": \"Ưu tiên hàng đầu của giao thông công cộng là sự an toàn của hành khách và những người tham gia giao thông khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Your ability to safely operate a bus in city traffic and changing weather conditions depends in part on your good health.\", \"vi\": \"Khả năng của quý vị trong việc điều khiển xe buýt một cách an toàn trong điều kiện giao thông đô thị và thời tiết thay đổi phần nào phụ thuộc vào tình trạng sức khỏe tốt của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"For this purpose, you will need to undergo a pre-employment physical checkup.\", \"vi\": \"Với mục đích này, quý vị sẽ cần phải thực hiện một cuộc kiểm tra sức khỏe trước khi nhận việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To make an appointment, please call (0500) 555 0140.\", \"vi\": \"Để đặt lịch hẹn, xin vui lòng gọi số (0500) 555 0140.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Your examination will be performed by a physician selected by Kendinburgh Transit, and you will not be charged for it.\", \"vi\": \"Việc khám sức khỏe của quý vị sẽ do một bác sĩ do Kendinburgh Transit chỉ định thực hiện, và quý vị sẽ không phải trả phí cho việc này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Please present the physician\'s report to your supervisor on your first day.\", \"vi\": \"Xin vui lòng trình bản báo cáo y tế cho cấp trên của quý vị vào ngày làm việc đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We look forward to working with you.\", \"vi\": \"Chúng tôi rất mong được hợp tác với quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Kristine Yerkes\", \"vi\": \"Kristine Yerkes\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Kristine Yerkes\", \"vi\": \"Kristine Yerkes\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Kendinburgh Transit\", \"vi\": \"Hệ thống Giao thông Công cộng Kendinburgh\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Kendinburgh Transit\", \"vi\": \"Hệ thống Giao thông Công cộng Kendinburgh\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"64 Ponteland Rd\", \"vi\": \"64 Ponteland Rd\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Kendinburgh, TD9 5UW\", \"vi\": \"Kendinburgh, TD9 5UW\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '2d61a75e-9b33-4b01-beaa-580aafe5816d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Bower Technical Institute to Host Guest Students\", \"vi\": \"Học viện Kỹ thuật Bower sẽ tiếp nhận sinh viên trao đổi\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"(April 27)—According to a recent government report, the demand for diesel mechanics is expected to increase by 15 percent in the next ten years.\", \"vi\": \"(Ngày 27 tháng 4) — Theo một báo cáo gần đây của chính phủ, nhu cầu về thợ sửa chữa động cơ diesel dự kiến sẽ tăng 15% trong mười năm tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"There is a growing need for diesel mechanics in the construction, oil, and power industries.\", \"vi\": \"Nhu cầu về thợ cơ khí chuyên về động cơ diesel trong các ngành xây dựng, dầu khí và năng lượng đang ngày càng gia tăng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Most of the positions pay very well and only require a high school diploma and technical training.\", \"vi\": \"Hầu hết các vị trí này đều có mức lương rất hấp dẫn và chỉ yêu cầu bằng tốt nghiệp trung học phổ thông cùng với khóa đào tạo kỹ thuật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Bower Technical Institute in Centerville provides that training.\", \"vi\": \"Trường Cao đẳng Kỹ thuật Bower tại Centerville cung cấp chương trình đào tạo này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"On May 1, Bower Technical Institute invites you to be a guest student from 9 A.M. to 2 P.M. After a question-and-answer session about the profession, guest students will observe actual diesel mechanic classes that focus on power trains and engine management systems.\", \"vi\": \"Vào ngày 1 tháng 5, Học viện Kỹ thuật Bower trân trọng mời quý vị tham gia chương trình học viên khách mời từ 9 giờ sáng đến 2 giờ chiều. Sau phần hỏi đáp về nghề nghiệp, các học viên khách mời sẽ tham quan các lớp học thực tế về kỹ thuật sửa chữa động cơ diesel, tập trung vào hệ thống truyền động và hệ thống quản lý động cơ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Later, guest students can participate in hands-on sessions to experience some of the day-to-day tasks involved in the field.\", \"vi\": \"Sau đó, các sinh viên khách mời có thể tham gia các buổi thực hành để trải nghiệm một số công việc thường ngày trong lĩnh vực này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The event is free, but space is limited.\", \"vi\": \"Sự kiện này miễn phí, nhưng số lượng chỗ ngồi có hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Participants must have a high school diploma or equivalent credential.\", \"vi\": \"Người tham gia phải có bằng tốt nghiệp trung học phổ thông hoặc bằng cấp tương đương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"E-mail Taneisha Hill at thill@bowertech.com to reserve a spot.\", \"vi\": \"Vui lòng gửi email cho Taneisha Hill theo địa chỉ thill@bowertech.com để đăng ký chỗ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '2da2a5c5-75c2-4a78-b589-a7ee13200f4e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"(CAPE TOWN, 26 October)—Locally based Roebling Vision announced yesterday that it will be merging with Novianto Technology, headquartered in Nairobi, Kenya.\", \"vi\": \"(CAPE TOWN, ngày 26 tháng 10) — Công ty Roebling Vision có trụ sở tại địa phương đã thông báo hôm qua rằng họ sẽ sáp nhập với công ty Novianto Technology, có trụ sở chính tại Nairobi, Kenya.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"This action will allow Roebling Vision to expand its research division to include a team that specializes in cutting-edge vision technology.\", \"vi\": \"Động thái này sẽ giúp Roebling Vision mở rộng bộ phận nghiên cứu của mình để bao gồm một đội ngũ chuyên về công nghệ thị giác tiên tiến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"\\\"There is no doubt that we will be releasing new eyewear solutions in the upcoming year,\\\" said Roebling Vision CEO Obakeng Van Dyk.\", \"vi\": \"\\\"Không còn nghi ngờ gì nữa, chúng tôi sẽ ra mắt các giải pháp kính mắt mới trong năm tới,\\\" ông Obakeng Van Dyk, Tổng giám đốc của Roebling Vision, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"\\\"With our joint efforts, there will be no limit to what we can do.\\\"\", \"vi\": \"\\\"Với sự nỗ lực chung của chúng ta, không có gì là không thể thực hiện được.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Before the two companies join forces, Roebling Vision\'s laboratories in Johannesburg will be expanded to be able to accommodate a much larger workforce.\", \"vi\": \"Trước khi hai công ty hợp tác, các phòng thí nghiệm của Roebling Vision tại Johannesburg sẽ được mở rộng để có thể đáp ứng nhu cầu về một đội ngũ nhân viên đông đảo hơn nhiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Headquartered here in Cape Town, Roebling Vision has centres throughout the country.\", \"vi\": \"Có trụ sở chính đặt tại Cape Town, Roebling Vision hiện có các trung tâm trên khắp cả nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Its popularity grew about ten years ago, after several South African celebrities began wearing Roebling glasses.\", \"vi\": \"Sự phổ biến của thương hiệu này bắt đầu gia tăng cách đây khoảng mười năm, sau khi một số người nổi tiếng Nam Phi bắt đầu đeo kính Roebling.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The company is best known for manufacturing eyeglasses and contact lenses.\", \"vi\": \"Công ty này được biết đến nhiều nhất với hoạt động sản xuất kính mắt và kính áp tròng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Less known is the fact that it also has a small division devoted to research and technology located in Johannesburg.\", \"vi\": \"Một điều ít người biết là công ty này còn có một bộ phận nhỏ chuyên về nghiên cứu và công nghệ, đặt trụ sở tại Johannesburg.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '2dbedbc5-1946-4890-989d-e694d8ac6a94';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Address - Bedrooms - Bathrooms - Model\", \"vi\": \"Địa chỉ - Số phòng ngủ - Số phòng tắm - Mẫu nhà\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"126 Hickory Drive - Three - Two - Grand Barron\", \"vi\": \"126 Hickory Drive - Ba - Hai - Grand Barron\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"912 Birch Place - Two - One - Andover\", \"vi\": \"912 Birch Place - Hai - Một - Andover\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"21 Lilac Lane - Two - One - Mickala\", \"vi\": \"21 Lilac Lane - Hai - Một - Mickala\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"108 Pine Avenue - Three - One - Lalique\", \"vi\": \"108 Đại lộ Pine - Ba - Một - Lalique\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Properties Currently Available for Sale\", \"vi\": \"Các bất động sản hiện đang được rao bán\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Listing Type: Single-family properties\", \"vi\": \"Loại bất động sản: Bất động sản nhà ở riêng lẻ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Location: Bonatra Acres in Windham County\", \"vi\": \"Địa điểm: Bonatra Acres, Hạt Windham\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Last updated: October 28\", \"vi\": \"Cập nhật lần cuối: ngày 28 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Bonatra Acres is a lovely residential community in Windham County featuring two-, three-, and four-bedroom single-family homes near schools, public transportation, and beautiful parks.\", \"vi\": \"Bonatra Acres là một khu dân cư xinh đẹp tại Hạt Windham, với các căn nhà riêng lẻ có hai, ba và bốn phòng ngủ, tọa lạc gần các trường học, hệ thống giao thông công cộng và những công viên tuyệt đẹp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The Lalique and Grand Barron models feature an eat-in kitchen, a large living area, and a garage.\", \"vi\": \"Các mẫu nhà Lalique và Grand Barron được trang bị bếp kết hợp phòng ăn, khu vực phòng khách rộng rãi và nhà để xe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The Andover model, the most affordable home, is a one-story home with a patio in the rear.\", \"vi\": \"Mẫu nhà Andover, mẫu nhà có giá cả phải chăng nhất, là một ngôi nhà một tầng có sân hiên phía sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The Mickala is a uniquely-styled home featuring upstairs bedrooms with oversized windows.\", \"vi\": \"Mickala là một ngôi nhà có phong cách độc đáo, với các phòng ngủ ở tầng trên được trang bị những ô cửa sổ cỡ lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The Harrison is a two-story model with modern upgrades.\", \"vi\": \"Mẫu nhà Harrison là mẫu nhà hai tầng được trang bị các tiện nghi hiện đại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To: Valerie Sidkoff <v.sidkoff@emikproperties.com>\", \"vi\": \"Gửi tới: Valerie Sidkoff <v.sidkoff@emikproperties.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From: Chun Lai <chunlai@anymail.com>\", \"vi\": \"From: Chun Lai <chunlai@anymail.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Date: October 30\", \"vi\": \"Ngày: 30 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Subject: New place to live\", \"vi\": \"Chủ đề: Nơi ở mới\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Dear Ms. Sidkoff,\", \"vi\": \"Kính gửi bà Sidkoff,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"EMIK Properties comes highly recommended by my manager, David Mwabili, who worked with you to find his business property.\", \"vi\": \"Công ty EMIK Properties đã nhận được lời giới thiệu nồng nhiệt từ người quản lý của tôi, ông David Mwabili, người đã hợp tác với quý công ty để tìm kiếm bất động sản kinh doanh cho mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I am wondering whether you also sell residential properties in the area.\", \"vi\": \"Tôi đang thắc mắc không biết quý công ty có kinh doanh bất động sản nhà ở trong khu vực này hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"My wife and I are looking to move to Windham County with our children to be closer to our jobs.\", \"vi\": \"Vợ chồng tôi đang có ý định chuyển đến Hạt Windham cùng các con để được gần nơi làm việc hơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"We will need easy access to public transportation.\", \"vi\": \"Chúng tôi cần có điều kiện thuận lợi để sử dụng phương tiện giao thông công cộng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I would be grateful if you could recommend some listings for reasonably priced homes in that area, ideally with two or more bedrooms and at least two bathrooms.\", \"vi\": \"Tôi sẽ rất biết ơn nếu quý vị có thể giới thiệu cho tôi một số thông tin rao bán về những căn nhà có giá cả hợp lý trong khu vực đó, tốt nhất là có từ hai phòng ngủ trở lên và ít nhất hai phòng tắm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I am available to visit homes on Wednesday mornings and Thursday afternoons.\", \"vi\": \"Tôi có thể đến thăm các hộ gia đình vào sáng thứ Tư và chiều thứ Năm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Chun Lai\", \"vi\": \"Chun Lai\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"June Preston, October 16\", \"vi\": \"June Preston, ngày 16 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I recently purchased a home from EMIK Properties and had the pleasure of working with Valerie Sidkoff, the company\'s owner.\", \"vi\": \"Gần đây, tôi đã mua một căn nhà từ công ty EMIK Properties và rất hân hạnh được hợp tác với bà Valerie Sidkoff, chủ sở hữu của công ty.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"She patiently showed me many houses in my preferred area and was attentive to my needs.\", \"vi\": \"Cô ấy đã kiên nhẫn giới thiệu cho tôi rất nhiều căn nhà trong khu vực mà tôi ưa thích và luôn quan tâm đến nhu cầu của tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"My only concern about EMIK Properties is that it seems to prioritize commercial clients over residential ones.\", \"vi\": \"Mối lo ngại duy nhất của tôi về EMIK Properties là công ty này dường như ưu tiên khách hàng thương mại hơn so với khách hàng dân cư.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"The agency reserves Thursday and Friday afternoons to show exclusively commercial properties.\", \"vi\": \"Công ty dành riêng các buổi chiều thứ Năm và thứ Sáu để tổ chức các buổi tham quan dành riêng cho các bất động sản thương mại.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"While this did not affect me, it could be a problem for others looking to buy a home.\", \"vi\": \"Mặc dù điều này không ảnh hưởng đến cá nhân tôi, nhưng nó có thể trở thành vấn đề đối với những người khác đang có ý định mua nhà.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '2de4ded4-6b23-4d38-951c-fb83bb281869';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Donald Haroway <dharoway@indomail.co.nz>\", \"vi\": \"Đến: Donald Haroway <dharoway@indomail.co.nz>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Fix-It Plumbing\", \"vi\": \"Từ: Fix-It Plumbing\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 4 August\", \"vi\": \"Ngày: 4 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Service request\", \"vi\": \"Chủ đề: Yêu cầu dịch vụ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Mr. Haroway,\", \"vi\": \"Ông Haroway,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This e-mail serves as confirmation that Fix-It Plumbing will be able to ______[139] a gas line at your residence at 458 Heron Street.\", \"vi\": \"Email này dùng để xác nhận rằng công ty Fix-It Plumbing sẽ có thể ______[139] một đường ống dẫn gas tại nơi ở của ông tại số 458 đường Heron.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [139]}, {\"en\": \"We ______[140] Bradley Burns, a certified and licensed master plumber, to do this on Monday, 10 August, between 10:00 A.M. and 11:00 A.M. It should take about an hour to put in the line.\", \"vi\": \"Chúng tôi ______[140] Bradley Burns, một thợ sửa ống nước chính có chứng chỉ và giấy phép, để thực hiện việc này vào thứ Hai, ngày 10 tháng 8, trong khoảng thời gian từ 10:00 sáng đến 11:00 sáng. Sẽ mất khoảng một tiếng để lắp đặt đường ống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [140]}, {\"en\": \"______[141].\", \"vi\": \"______[141].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [141]}, {\"en\": \"Should you need to cancel the ______[142], please contact us right away.\", \"vi\": \"Nếu ông cần hủy ______[142], vui lòng liên hệ với chúng tôi ngay lập tức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [142]}, {\"en\": \"This is a particularly busy time of year, and our schedules are quite full.\", \"vi\": \"Đây là thời điểm rất bận rộn trong năm, và lịch làm việc của chúng tôi khá kín.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Elna Dlamini\", \"vi\": \"Elna Dlamini\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Fix-It Plumbing\", \"vi\": \"Fix-It Plumbing\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '2e03b19c-3bae-49b5-bf7b-a5e5397470c8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Harbour View Apartment—Porthmadog, Wales\", \"vi\": \"Căn hộ Harbour View — Porthmadog, xứ Wales\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"This one-bedroom apartment is perfect for a holiday escape!\", \"vi\": \"Căn hộ một phòng ngủ này là lựa chọn lý tưởng cho một kỳ nghỉ thư giãn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Located in a quiet area, it boasts a patio with a lovely view of the harbour.\", \"vi\": \"Tọa lạc tại một khu vực yên tĩnh, nơi đây tự hào có một sân hiên với khung cảnh tuyệt đẹp hướng ra bến cảng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Recently renovated, the unit includes an eat-in kitchen with stove, refrigerator, microwave, and coffeepot; bathroom with walk-in shower; and a living room with a large-screen TV.\", \"vi\": \"Căn hộ này vừa được tân trang lại gần đây, bao gồm một nhà bếp kết hợp phòng ăn với bếp nấu, tủ lạnh, lò vi sóng và bình pha cà phê; phòng tắm có buồng tắm đứng; cùng phòng khách trang bị tivi màn hình lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Other amenities of the property include:\", \"vi\": \"Các tiện nghi khác của khu nghỉ dưỡng bao gồm:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Short distance to restaurants and shops\", \"vi\": \"Cách các nhà hàng và cửa hàng chỉ một quãng đường ngắn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Five-minute walk to the beach\", \"vi\": \"Chỉ mất năm phút đi bộ để đến bãi biển\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Public gardens and historic sites within a 20-minute drive\", \"vi\": \"Các công viên công cộng và di tích lịch sử nằm trong phạm vi 20 phút lái xe\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Heat and electricity included\", \"vi\": \"Đã bao gồm chi phí sưởi ấm và điện\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Towels and bed linens provided on-site\", \"vi\": \"Khăn tắm và bộ chăn ga gối được cung cấp ngay tại chỗ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Daily cleaning service available (extra fee)\", \"vi\": \"Có dịch vụ dọn dẹp hàng ngày (phụ phí)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Wireless Internet access (extra fee)\", \"vi\": \"Dịch vụ truy cập Internet không dây (có tính phí thêm)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Reserve this lovely gem now!\", \"vi\": \"Hãy đặt trước “viên ngọc quý” tuyệt vời này ngay bây giờ!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Signing a contract by March 30 will reduce the rental cost by 10 percent.\", \"vi\": \"Nếu ký hợp đồng trước ngày 30 tháng 3, quý vị sẽ được giảm 10 phần trăm chi phí thuê.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To sign a contract, contact Dylan Barrett at dbarrett@telarentals.co.uk.\", \"vi\": \"Để ký hợp đồng, xin vui lòng liên hệ với ông Dylan Barrett qua địa chỉ email dbarrett@telarentals.co.uk.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '2e0dd9a3-45b5-4f31-8ec8-a43de249c478';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Corelli\'s Bakery, 15 Middlemass Street, Youngstown, Ohio 44515\", \"vi\": \"Tiệm bánh Corelli\'s Bakery, 15 Middlemass Street, Youngstown, Ohio 44515\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear Valued Customer:\", \"vi\": \"Kính gửi Quý khách hàng,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"For the last three years we have charged the same wholesale prices for our baked goods, including cakes, pies, cookies, and brownies.\", \"vi\": \"Trong ba năm qua, chúng tôi vẫn giữ nguyên giá sỉ cho các sản phẩm bánh nướng của mình, bao gồm bánh ngọt, bánh nướng trái cây, bánh quy và bánh brownie.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We regret that sharply rising prices for our raw ingredients, such as sugar and fruit, have forced us to raise our prices by 5 percent ______[135].\", \"vi\": \"Chúng tôi rất tiếc khi giá nguyên liệu thô tăng mạnh, chẳng hạn như đường và trái cây, đã buộc chúng tôi phải tăng giá 5 phần trăm ______[135].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [135]}, {\"en\": \"August 1.\", \"vi\": \"Ngày 1 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We have made every attempt to avoid this price increase.\", \"vi\": \"Chúng tôi đã nỗ lực hết sức để tránh đợt tăng giá này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[136], we refuse to compromise on the quality of our products.\", \"vi\": \"______[136], chúng tôi từ chối thỏa hiệp về chất lượng sản phẩm của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [136]}, {\"en\": \"Using the best ingredients available will allow us to provide the delicious desserts your restaurant guests have come to expect.\", \"vi\": \"Việc sử dụng những nguyên liệu tốt nhất hiện có sẽ cho phép chúng tôi cung cấp những món tráng miệng ngon miệng mà thực khách tại nhà hàng của quý vị luôn mong đợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[137].\", \"vi\": \"______[137].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [137]}, {\"en\": \"We appreciate your ______[138] and look forward to continuing to serve you.\", \"vi\": \"Chúng tôi đánh giá cao sự ______[138] của quý vị và mong muốn tiếp tục được phục vụ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [138]}, {\"en\": \"Sincerely, Tony Corelli, Owner\", \"vi\": \"Trân trọng, Tony Corelli, Chủ sở hữu\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '2e0e0efa-98a9-4053-9e82-7cfb04985061';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Twinkle Media – Production Services\", \"vi\": \"Twinkle Media – Dịch vụ sản xuất\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"In addition to recording live events, Twinkle Media can assist with the production of scripted commercial and corporate videos.\", \"vi\": \"Ngoài việc quay phim các sự kiện trực tiếp, Twinkle Media còn có thể hỗ trợ sản xuất các video quảng cáo và video doanh nghiệp theo kịch bản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We offer four service packages:\", \"vi\": \"Chúng tôi cung cấp bốn gói dịch vụ:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Bronze – We film content that you plan and perform, and we provide the basic post-production services of editing and, if needed, adding titles and licensed or royalty-free music.\", \"vi\": \"Gói Đồng – Chúng tôi sẽ quay phim các nội dung do quý vị lên kế hoạch và thực hiện, đồng thời cung cấp các dịch vụ hậu kỳ cơ bản bao gồm chỉnh sửa và, nếu cần, chèn phụ đề cùng nhạc có bản quyền hoặc nhạc miễn phí bản quyền.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Silver – In addition to the bronze package services, we create simple animations to add visual interest to your video or illustrate difficult concepts.\", \"vi\": \"Gói Bạc – Bên cạnh các dịch vụ trong gói Đồng, chúng tôi sẽ tạo ra các đoạn hoạt hình đơn giản nhằm tăng thêm sự hấp dẫn về mặt hình ảnh cho video của quý vị hoặc minh họa các khái niệm phức tạp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Gold – Adding some of the pre-production tasks to our plate, we provide advice on structuring your video and animations and write the script.\", \"vi\": \"Gold – Bên cạnh việc đảm nhận một số công việc trong giai đoạn tiền sản xuất, chúng tôi còn tư vấn về cách xây dựng cấu trúc cho video và các đoạn hoạt hình của quý vị, đồng thời soạn thảo kịch bản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Platinum – For an especially professional presentation, we cast actors to appear in your video to complement our top-notch videography, post-production, animation, and scriptwriting.\", \"vi\": \"Gói Platinum – Để mang đến một bản trình bày đặc biệt chuyên nghiệp, chúng tôi sẽ tuyển chọn các diễn viên tham gia vào video của quý vị, nhằm bổ sung cho các dịch vụ quay phim, hậu kỳ, hoạt hình và viết kịch bản đẳng cấp hàng đầu của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Fill out our contact form to get started!\", \"vi\": \"Hãy điền vào biểu mẫu liên hệ của chúng tôi để bắt đầu!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"◀\", \"vi\": \"◀\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"▶\", \"vi\": \"▶\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"http://www.twinklemedia.com/ps\", \"vi\": \"http://www.twinklemedia.com/ps\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"From - Jeong-Ho Woo <jeonghow@twinklemedia.com>\", \"vi\": \"Từ - Jeong-Ho Woo <jeonghow@twinklemedia.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To - Savannah Braswell <s.braswell@accounti.com>\", \"vi\": \"Gửi tới - Savannah Braswell <s.braswell@accounti.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Subject - RE: Update\", \"vi\": \"Tiêu đề - RE: Cập nhật\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date - September 15\", \"vi\": \"Ngày - 15 tháng 9\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dear Ms. Braswell,\", \"vi\": \"Kính gửi bà Braswell,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thank you for the update on the budget limit for your product tutorial videos.\", \"vi\": \"Xin cảm ơn quý vị đã cung cấp thông tin cập nhật về giới hạn ngân sách dành cho các video hướng dẫn sử dụng sản phẩm của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"In accordance with your wishes, we will reduce the scope of our services to be provided.\", \"vi\": \"Theo mong muốn của quý vị, chúng tôi sẽ thu hẹp phạm vi các dịch vụ sẽ cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Since your project is still in its early stages, we have not begun the casting process, so you can rest assured that this change will not inconvenience anyone.\", \"vi\": \"Vì dự án của quý vị vẫn đang ở giai đoạn đầu, chúng tôi chưa bắt đầu quá trình tuyển chọn diễn viên, do đó quý vị có thể hoàn toàn yên tâm rằng sự thay đổi này sẽ không gây bất tiện cho bất kỳ ai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I was also glad to learn that you have finished mapping out the basic points you want each video to cover.\", \"vi\": \"Tôi cũng rất vui khi biết rằng quý vị đã hoàn tất việc vạch ra những nội dung cơ bản mà quý vị muốn mỗi video đề cập đến.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Please send us that information and give us access to Accounti.\", \"vi\": \"Kính mong Quý vị gửi cho chúng tôi thông tin đó và cấp quyền truy cập vào Accounti.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"To produce the scripts, our team will need to try out the software\'s features ourselves and then meet with you or another Accounti employee who can answer any questions we have about it.\", \"vi\": \"Để lập các tập lệnh, nhóm của chúng tôi sẽ cần tự mình thử nghiệm các tính năng của phần mềm, sau đó sẽ có cuộc họp với quý vị hoặc một nhân viên khác của Accounti có thể giải đáp mọi thắc mắc của chúng tôi liên quan đến phần mềm này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"We have availability on the morning of Thursday, September 18 or the afternoon of Monday, September 22.\", \"vi\": \"Chúng tôi còn chỗ trống vào sáng Thứ Năm, ngày 18 tháng 9 hoặc chiều Thứ Hai, ngày 22 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Please let us know which period would work best for you.\", \"vi\": \"Xin vui lòng cho chúng tôi biết khoảng thời gian nào là thuận tiện nhất đối với quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Jeong-Ho Woo\", \"vi\": \"Jeong-Ho Woo\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Account Manager\", \"vi\": \"Chuyên viên Quản lý Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Twinkle Media\", \"vi\": \"Twinkle Media\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Twinkle Media\", \"vi\": \"Twinkle Media\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Meeting Summary\", \"vi\": \"Tóm tắt cuộc họp\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Project: Accounti Product Tutorial Videos\", \"vi\": \"Dự án: Video hướng dẫn sử dụng sản phẩm Accounti\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"September 22, 1:30–4:00 p.m.\", \"vi\": \"Ngày 22 tháng 9, từ 1 giờ 30 đến 4 giờ chiều\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Attendees: Jeong-Ho Woo; Yvette Rodriguez; Shaun Freeman (client representative)\", \"vi\": \"Những người tham dự: Jeong-Ho Woo; Yvette Rodriguez; Shaun Freeman (đại diện khách hàng)\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Mr. Freeman answered questions about Accounti\'s features (see attached notes).\", \"vi\": \"Ông Freeman đã trả lời các câu hỏi liên quan đến các tính năng của Accounti (xin xem các ghi chú đính kèm).\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"We promised to submit video scripts for client approval on the following schedule:\", \"vi\": \"Chúng tôi đã cam kết sẽ gửi kịch bản video để quý khách hàng duyệt theo lịch trình như sau:\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"\\\"Getting Started\\\" – September 24\", \"vi\": \"\\\"Bắt đầu\\\" – Ngày 24 tháng 9\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"\\\"Important Settings\\\" – September 26\", \"vi\": \"\\\"Các cài đặt quan trọng\\\" – Ngày 26 tháng 9\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"\\\"Sales and Invoices\\\" – September 30\", \"vi\": \"\\\"Doanh số và Hóa đơn\\\" – Ngày 30 tháng 9\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"\\\"Expenses\\\" – October 2\", \"vi\": \"\\\"Chi phí\\\" – Ngày 2 tháng 10\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"It was decided that animations and voice-over are more suitable than an on-camera presenter for \\\"Important Settings,\\\" so its production can begin as soon as the script is approved.\", \"vi\": \"Ban lãnh đạo đã quyết định rằng việc sử dụng hình ảnh động và lồng tiếng sẽ phù hợp hơn so với việc có người dẫn chương trình xuất hiện trước ống kính trong phần “Các cài đặt quan trọng”, do đó quá trình sản xuất có thể bắt đầu ngay sau khi kịch bản được phê duyệt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Mr. Freeman will call us by Friday regarding the filming schedule for the other videos.\", \"vi\": \"Ông Freeman sẽ liên hệ với chúng ta trước thứ Sáu để thông báo về lịch quay các video còn lại.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}]' WHERE `id` = '2e7cd8ac-8112-4696-a382-ef313cbc0020';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: programs@freewheeloasis.com\", \"vi\": \"Gửi tới: programs@freewheeloasis.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Nicola Johnson <njohnson92@rapidonet.com>\", \"vi\": \"Từ: Nicola Johnson <njohnson92@rapidonet.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: November 2\", \"vi\": \"Ngày: 2 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Appointment request\", \"vi\": \"Chủ đề: Yêu cầu sắp xếp cuộc hẹn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"https://www.freewheeloasis.com/trade-in-and-consignment\", \"vi\": \"https://www.freewheeloasis.com/trade-in-and-consignment\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Home | Service and Repair | Trade-in and Consignment | Accessories\", \"vi\": \"Trang chủ | Dịch vụ và Sửa chữa | Chương trình đổi cũ lấy mới và bán hàng ký gửi | Phụ kiện\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Freewheel Oasis offers two programs that make selling your bicycle easier: trade-in and consignment.\", \"vi\": \"Freewheel Oasis cung cấp hai chương trình giúp quý khách bán xe đạp dễ dàng hơn: chương trình đổi cũ lấy mới và chương trình bán hàng ký gửi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If you select our trade-in program, you give us your bicycle, and, in exchange, we give you credit toward the purchase of a new one.\", \"vi\": \"Nếu quý vị lựa chọn chương trình đổi cũ lấy mới của chúng tôi, quý vị sẽ giao lại chiếc xe đạp của mình cho chúng tôi, và đổi lại, chúng tôi sẽ cấp cho quý vị một khoản tín dụng để mua một chiếc xe đạp mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"If you opt for our consignment program, we will sell your bicycle for you.\", \"vi\": \"Nếu quý vị lựa chọn chương trình bán hàng ký gửi của chúng tôi, chúng tôi sẽ thay mặt quý vị bán chiếc xe đạp của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To take advantage of either option, e-mail us at programs@freewheeloasis.com to schedule an appointment.\", \"vi\": \"Để tận dụng một trong hai lựa chọn trên, xin vui lòng gửi email cho chúng tôi theo địa chỉ programs@freewheeloasis.com để đặt lịch hẹn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"In your e-mail, you should also indicate whether you wish to trade in your bicycle or place it on consignment.\", \"vi\": \"Trong email của quý vị, quý vị cũng nên cho biết liệu quý vị muốn đổi chiếc xe đạp của mình hay gửi bán theo hình thức ký gửi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You will receive a response from our customer service manager.\", \"vi\": \"Quý vị sẽ nhận được phản hồi từ Trưởng bộ phận Chăm sóc Khách hàng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We take appointments during regular business hours, Monday through Saturday from 9:00 A.M. to 5:00 P.M.\", \"vi\": \"Chúng tôi nhận đặt lịch hẹn trong giờ làm việc thông thường, từ thứ Hai đến thứ Bảy, từ 9 giờ sáng đến 5 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"When you come in for your appointment, a technician will assess the condition of your bicycle, and a sales associate will determine its current value.\", \"vi\": \"Khi quý khách đến theo lịch hẹn, một kỹ thuật viên sẽ kiểm tra tình trạng chiếc xe đạp của quý khách, và một nhân viên bán hàng sẽ xác định giá trị hiện tại của chiếc xe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If the value specified is acceptable to you and you wish to trade in your bicycle, we deduct that amount from the purchase price of your new bicycle.\", \"vi\": \"Nếu mức giá được đề xuất phù hợp với quý khách và quý khách có nhu cầu đổi chiếc xe đạp hiện tại, chúng tôi sẽ khấu trừ số tiền đó vào giá mua chiếc xe đạp mới của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"If you prefer a consignment arrangement, we will sell your bicycle for the agreed-upon amount.\", \"vi\": \"Nếu quý vị muốn áp dụng hình thức bán hàng ký gửi, chúng tôi sẽ bán chiếc xe đạp của quý vị với mức giá đã thỏa thuận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Note that we will withhold a service fee equal to 15 percent of this amount at the time your bicycle is sold, while the rest of the earnings will be sent to you.\", \"vi\": \"Xin lưu ý rằng chúng tôi sẽ khấu trừ một khoản phí dịch vụ tương đương 15 phần trăm của số tiền này vào thời điểm chiếc xe đạp của quý vị được bán, trong khi phần thu nhập còn lại sẽ được chuyển cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Xin chào\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I have a mountain bicycle that is now six years old.\", \"vi\": \"Tôi có một chiếc xe đạp địa hình đã được sáu năm tuổi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"However, I only used it for the first three years.\", \"vi\": \"Tuy nhiên, tôi chỉ sử dụng nó trong ba năm đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I have tried to sell it myself but was not successful, so I would like to place it on consignment with you.\", \"vi\": \"Tôi đã tự mình thử bán món đồ này nhưng không thành công, vì vậy tôi muốn gửi bán hàng theo hình thức ký gửi tại cửa hàng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Therefore, I would like to schedule an appointment.\", \"vi\": \"Vì vậy, tôi xin được đặt lịch hẹn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Also, I recently accepted a job in Kuwait and will be leaving on November 30.\", \"vi\": \"Ngoài ra, gần đây tôi đã nhận một công việc tại Kuwait và sẽ lên đường vào ngày 30 tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Do you expect that the bicycle will be sold by then?\", \"vi\": \"Quý vị có dự kiến chiếc xe đạp đó sẽ được bán vào thời điểm đó không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"If not, how can I receive my portion of the selling price?\", \"vi\": \"Nếu không, làm thế nào để tôi có thể nhận được phần tiền bán hàng của mình?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Nicola Johnson\", \"vi\": \"Nicola Johnson\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"E-Mail Message\", \"vi\": \"Thông điệp email\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"To: Nicola Johnson <njohnson92@rapidonet.com>\", \"vi\": \"Gửi tới: Nicola Johnson <njohnson92@rapidonet.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"From: programs@freewheeloasis.com\", \"vi\": \"Nguồn: programs@freewheeloasis.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Date: November 2\", \"vi\": \"Ngày: 2 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Subject: RE: Appointment request\", \"vi\": \"Chủ đề: TRẢ LỜI: Yêu cầu sắp xếp cuộc hẹn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Hi, Nicola,\", \"vi\": \"Xin chào, Nicola,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Thanks for your interest in placing your bicycle on consignment with Freewheel Oasis.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã quan tâm đến dịch vụ gửi bán xe đạp tại Freewheel Oasis.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Your appointment is scheduled for Friday, November 4, at 3:00 P.M. Let me know if this arrangement works for you.\", \"vi\": \"Cuộc hẹn của quý vị đã được sắp xếp vào thứ Sáu, ngày 4 tháng 11, lúc 3 giờ chiều. Xin vui lòng cho tôi biết liệu thời gian này có phù hợp với quý vị hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Our consignment policy stipulates that once the sale of a bicycle has been finalized, the money owed to the customer must be paid into the person\'s bank account.\", \"vi\": \"Chính sách bán hàng ký gửi của chúng tôi quy định rằng, ngay sau khi giao dịch bán xe đạp được hoàn tất, số tiền phải thanh toán cho khách hàng phải được chuyển vào tài khoản ngân hàng của người đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Please note that Freewheel Oasis cannot guarantee the sale of a bicycle by a date specified by the bicycle owner.\", \"vi\": \"Xin lưu ý rằng Freewheel Oasis không thể đảm bảo việc bán được chiếc xe đạp vào ngày do chủ sở hữu xe đạp chỉ định.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Best of luck with your new endeavor!\", \"vi\": \"Chúc quý vị may mắn trong hành trình mới này!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Peter Moran\", \"vi\": \"Peter Moran\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 41, \"question_numbers\": []}]' WHERE `id` = '2e9ad9ff-3ed2-467c-80f0-e2bc6f8345f2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Adam Silva [10:49 A.M.]\", \"vi\": \"Từ: Adam Silva [10 giờ 49 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Frida Landvik\", \"vi\": \"Gửi: Frida Landvik\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Good morning!\", \"vi\": \"Chào buổi sáng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The ventilation consultants and I are doing our on-site walk-through of the restaurant now.\", \"vi\": \"Hiện tại, các chuyên gia tư vấn về hệ thống thông gió và tôi đang tiến hành kiểm tra thực địa tại nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"They\'re saying that the structure of the building will actually make it pretty easy to set up a kitchen that complies with city regulations.\", \"vi\": \"Người ta cho rằng chính cấu trúc của tòa nhà sẽ giúp việc bố trí một nhà bếp tuân thủ các quy định của thành phố trở nên khá dễ dàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We won\'t have to route the exhaust duct all the way to the roof as we feared.\", \"vi\": \"Chúng ta sẽ không phải dẫn ống thoát khí lên tận mái nhà như những gì chúng ta từng lo ngại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"So, the $10,000 we set aside for this part of the project will be more than enough to cover the work.\", \"vi\": \"Vì vậy, số tiền 10.000 đô la mà chúng ta đã dành riêng cho phần này của dự án sẽ là hơn đủ để chi trả cho công việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I wanted to tell you right away since I know you were concerned about that.\", \"vi\": \"Tôi muốn thông báo ngay cho quý vị biết vì tôi biết quý vị đã lo lắng về vấn đề đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I\'ll call you with details once we\'re finished.\", \"vi\": \"Khi chúng tôi hoàn tất công việc, tôi sẽ gọi điện cho quý vị để thông báo chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"●▮▮▮▮▮●\", \"vi\": \"●▮▮▮▮▮●\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"●\", \"vi\": \"●\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"New Restaurant to Take Over Sherman Street Landmark\", \"vi\": \"Nhà hàng mới sẽ tiếp quản địa điểm mang tính biểu tượng trên đường Sherman\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"GLADNEY (7 August)—Reeves House, the 130-year-old home located at 560 Sherman Street, is being converted into a restaurant set to open later this month.\", \"vi\": \"GLADNEY (ngày 7 tháng 8) — Ngôi nhà Reeves, ngôi nhà có tuổi đời 130 năm tọa lạc tại số 560 đường Sherman, hiện đang được cải tạo thành một nhà hàng dự kiến sẽ khai trương vào cuối tháng này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The restaurant\'s co-owners, Frida Landvik and Adam Silva, purchased the property from Marian Reeves, the last descendant of the family that built the home.\", \"vi\": \"Hai chủ sở hữu chung của nhà hàng, bà Frida Landvik và ông Adam Silva, đã mua lại bất động sản này từ bà Marian Reeves, người con cháu cuối cùng của gia đình đã xây dựng ngôi nhà này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Their eatery will be named \\\"The Oak Bistro\\\" after the large tree that stands on the front lawn.\", \"vi\": \"Quán ăn của họ sẽ được đặt tên là “The Oak Bistro”, lấy cảm hứng từ cây sồi lớn đang sừng sững trên bãi cỏ phía trước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The graceful gray house and its grounds have been well-maintained during their long history.\", \"vi\": \"Ngôi nhà màu xám trang nhã cùng khuôn viên xung quanh đã được bảo quản cẩn thận trong suốt chặng đường lịch sử dài đằng đẵng của nó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Mr. Silva says the structure has needed some upgrades to satisfy restaurant regulations but few repairs.\", \"vi\": \"Ông Silva cho biết công trình này cần một số cải tạo để đáp ứng các quy định về nhà hàng, nhưng chỉ cần rất ít sửa chữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"When it opens, The Oak Bistro will serve lunch and dinner dishes inspired by Ms. Landvik\'s childhood in Norway.\", \"vi\": \"Khi chính thức khai trương, nhà hàng The Oak Bistro sẽ phục vụ các món ăn trưa và tối lấy cảm hứng từ quãng thời gian thơ ấu của bà Landvik tại Na Uy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Indoor seating for 25 people will be available year-round, with additional seating on the front lawn offered from June through September.\", \"vi\": \"Khu vực chỗ ngồi trong nhà dành cho 25 người sẽ mở cửa phục vụ quanh năm; ngoài ra, từ tháng 6 đến tháng 9, quý vị còn có thể tận hưởng thêm các chỗ ngồi trên bãi cỏ phía trước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"More information can be found at www.theoakbistro.com.\", \"vi\": \"Quý vị có thể tìm thêm thông tin tại địa chỉ www.theoakbistro.com.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"http://www.you-review.com\", \"vi\": \"http://www.you-review.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"The Oak Bistro (Gladney)\", \"vi\": \"Nhà hàng The Oak Bistro (Gladney)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"★★★★☆\", \"vi\": \"★★★★☆\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Reviewer: Keith Owens\", \"vi\": \"Người đánh giá: Keith Owens\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Some friends and I stopped by The Oak Bistro for lunch at the end of October.\", \"vi\": \"Vào cuối tháng Mười, tôi cùng một số người bạn đã ghé qua nhà hàng The Oak Bistro để dùng bữa trưa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"It has a lovely, old-fashioned atmosphere, and the service is excellent.\", \"vi\": \"Nơi đây mang một bầu không khí cổ kính, đầy duyên dáng, và dịch vụ tại đây rất tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Our server, Joyce, was happy to answer all of our questions about the menu.\", \"vi\": \"Cô Joyce, nhân viên phục vụ của chúng tôi, đã rất vui lòng giải đáp tất cả các thắc mắc của chúng tôi về thực đơn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"This was important, because none of us was familiar with Norwegian food.\", \"vi\": \"Điều này rất quan trọng, bởi vì không ai trong chúng tôi quen thuộc với ẩm thực Na Uy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Luckily, we were happy to find that it is quite good.\", \"vi\": \"May mắn thay, chúng tôi rất vui khi thấy rằng nó thực sự khá tốt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I especially recommend the fish soup, which is creamy and delicious.\", \"vi\": \"Tôi đặc biệt xin giới thiệu món canh cá, có vị béo ngậy và rất ngon.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"The only reason I\'m not giving the place a five-star rating is that the portion sizes are a bit small.\", \"vi\": \"Lý do duy nhất khiến tôi không chấm năm sao cho quán này là vì khẩu phần ăn hơi ít.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"HOME\", \"vi\": \"TRANG CHỦ\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"RESTAURANTS\", \"vi\": \"NHÀ HÀNG\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"HOME SERVICES\", \"vi\": \"DỊCH VỤ TẠI NHÀ\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"MORE\", \"vi\": \"XEM THÊM\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '2eabffd4-0ea8-4ce8-bcb8-60ac78146246';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Attention All Employees\", \"vi\": \"Kính gửi toàn thể nhân viên\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"At 7:30 A.M. today, the main server facility lost power during regular security testing.\", \"vi\": \"Vào lúc 7 giờ 30 sáng hôm nay, trung tâm máy chủ chính đã bị mất điện trong quá trình tiến hành kiểm tra an ninh định kỳ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Power was restored less than one hour later, and the company Web site is now fully functional.\", \"vi\": \"Điện đã được khôi phục chưa đầy một giờ sau đó, và trang web của công ty hiện đã hoạt động bình thường trở lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"However, many services are still down.\", \"vi\": \"Tuy nhiên, nhiều dịch vụ vẫn đang gặp sự cố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Among these are the main database and all desktop phone services, including voice mail.\", \"vi\": \"Trong số đó có cơ sở dữ liệu chính và tất cả các dịch vụ điện thoại cố định, bao gồm cả thư thoại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"At this time, you can access e-mail from mobile devices but not from your office computers.\", \"vi\": \"Hiện tại, quý vị có thể truy cập email từ các thiết bị di động nhưng không thể truy cập từ máy tính tại văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Our technicians are working to bring all systems back online.\", \"vi\": \"Các kỹ thuật viên của chúng tôi hiện đang nỗ lực khôi phục hoạt động cho tất cả các hệ thống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"However, it may take until this afternoon for everything to resume working normally.\", \"vi\": \"Tuy nhiên, có thể phải đến chiều nay mọi thứ mới trở lại hoạt động bình thường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We understand the importance of these services to your work, and we will issue updates as more information becomes available.\", \"vi\": \"Chúng tôi thấu hiểu tầm quan trọng của các dịch vụ này đối với công việc của quý vị, và chúng tôi sẽ cập nhật thông tin ngay khi có thêm thông tin mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '2eb76a16-89c5-4723-bcc3-1d2385568d19';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Let\'s Use our Fitness Center Properly!\", \"vi\": \"Hãy Sử Dụng Trung Tâm Thể Dục của Chúng Ta Đúng Cách!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"In order to keep enjoying the perk of having an onsite company fitness center, ______[131] must agree to use it neatly and respectfully.\", \"vi\": \"Để tiếp tục tận hưởng tiện ích có trung tâm thể dục ngay tại công ty, ______[131] phải đồng ý sử dụng một cách gọn gàng và tôn trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"______[132] While exercising, kindly ______[133] your gym bag in the locker room.\", \"vi\": \"______[132] Trong khi tập luyện, vui lòng ______[133] túi tập gym của bạn trong phòng thay đồ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132, 133]}, {\"en\": \"Do not bring in any food or drinks other than bottled water, and wear headphones to listen to audio content.\", \"vi\": \"Không mang theo bất kỳ đồ ăn hoặc thức uống nào ngoài nước đóng chai, và hãy đeo tai nghe khi nghe nội dung âm thanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Use the provided paper towels and cleaning spray to wipe down ______[134] immediately after use.\", \"vi\": \"Sử dụng khăn giấy và xịt vệ sinh được cung cấp để lau sạch ______[134] ngay sau khi sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [134]}, {\"en\": \"Finally, if you are the last one to use the fitness room in the evening, please turn off the lights afterward.\", \"vi\": \"Cuối cùng, nếu bạn là người cuối cùng sử dụng phòng tập thể dục vào buổi tối, vui lòng tắt đèn sau khi rời đi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Xin cảm ơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '2ec789f6-070f-497d-85d0-4cd0bc5d4519';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Jane McNally <jmcnally@aap.org.ie>\", \"vi\": \"Gửi: Jane McNally <jmcnally@aap.org.ie>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Yoko Nara <ynara@insleyhotel.com.ie>\", \"vi\": \"Từ: Yoko Nara <ynara@insleyhotel.com.ie>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 3 February\", \"vi\": \"Ngày: 3 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Vouchers\", \"vi\": \"Chủ đề: Phiếu mua hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hi, Ms. McNally.\", \"vi\": \"Xin chào, bà McNally.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The water heater servicing the kitchen at the hotel is broken.\", \"vi\": \"Máy nước nóng phục vụ khu bếp của khách sạn hiện đang bị hỏng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We cannot serve meals because there is no hot water for washing pots and dishes.\", \"vi\": \"Chúng tôi không thể phục vụ bữa ăn vì không có nước nóng để rửa nồi và bát đĩa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Technicians are diligently working on this issue.\", \"vi\": \"Các kỹ thuật viên đang nỗ lực khắc phục sự cố này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I am offering vouchers to all guests that can be used for breakfast or lunch at Sarah’s Café next door.\", \"vi\": \"Tôi xin tặng phiếu ưu đãi cho tất cả quý khách, có thể sử dụng để dùng bữa sáng hoặc bữa trưa tại quán Sarah’s Café ngay bên cạnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"If there is no resolution by tomorrow, the evening’s dinner will be moved to Maury’s Restaurant.\", \"vi\": \"Nếu đến ngày mai vẫn chưa có quyết định nào, bữa tối tối nay sẽ được chuyển sang Nhà hàng Maury’s.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I have already discussed this with owner Maury Roebling, and he is preparing to welcome your professional group.\", \"vi\": \"Tôi đã trao đổi về vấn đề này với ông Maury Roebling, chủ sở hữu, và ông ấy đang chuẩn bị để đón tiếp đoàn chuyên gia của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please accept my apologies for any inconvenience.\", \"vi\": \"Kính xin quý vị thông cảm về những bất tiện có thể xảy ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Yoko Nara\", \"vi\": \"Nghe này, Nara\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"★★★★☆\", \"vi\": \"★★★★☆\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"“The place was charming.”\", \"vi\": \"“Nơi đó thật quyến rũ.”\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I enjoyed a soup and sandwich special at Sarah’s Café this afternoon because I received a voucher from my hotel.\", \"vi\": \"Chiều nay, tôi đã thưởng thức một suất đặc biệt gồm súp và bánh mì tại Sarah’s Café vì tôi đã nhận được một phiếu giảm giá từ khách sạn của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I arrived just at noon and had to wait almost 25 minutes for a table.\", \"vi\": \"Tôi đến đúng vào lúc trưa và phải đợi gần 25 phút mới có bàn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I would recommend visiting at a less busy time because the café is relatively small.\", \"vi\": \"Tôi xin khuyên quý vị nên ghé thăm vào những khung giờ vắng khách hơn vì quán cà phê này có diện tích khá nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Other than that, even if my meal had not been free, I would still recommend the café.\", \"vi\": \"Ngoài ra, ngay cả khi bữa ăn của tôi không được miễn phí, tôi vẫn sẽ giới thiệu quán cà phê này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"The atmosphere is warm and inviting and their homemade soup is delicious.\", \"vi\": \"Không khí ở đây ấm cúng và thân thiện, và món súp tự nấu của họ rất ngon.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"–Stefan Nichols, 3 February\", \"vi\": \"– Stefan Nichols, ngày 3 tháng 2\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Guest speaker\\n5:30 P.M., Room 213, Insley Hotel - Mr. Ian Bagley, chief financial officer at Colford International, will discuss “Old Concerns and Current Trends in the Accounting Profession.”\", \"vi\": \"Diễn giả khách mời\\n17 giờ 30, Phòng 213, Khách sạn Insley – Ông Ian Bagley, Giám đốc Tài chính của Colford International, sẽ trình bày về chủ đề “Những vấn đề tồn tại từ lâu và các xu hướng hiện nay trong ngành kế toán.”\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Networking dinner\\n7:00 P.M. Maury’s Restaurant - Enjoy a gourmet dinner and relax with your colleagues at this popular eatery.\", \"vi\": \"Bữa tối giao lưu\\n19:00 tại Nhà hàng Maury’s – Hãy thưởng thức bữa tối cao cấp và thư giãn cùng các đồng nghiệp tại nhà hàng nổi tiếng này.\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Job Fair\\n11:00 A.M. to 5:00 P.M. - Looking for a new opportunity? The job fair is for you. Meet with representatives from companies around the region. Bring copies of your résumé.\", \"vi\": \"Hội chợ việc làm\\nTừ 11 giờ sáng đến 5 giờ chiều – Quý vị đang tìm kiếm cơ hội mới? Hội chợ việc làm này chính là dành cho quý vị. Hãy đến gặp gỡ các đại diện từ các công ty trong khu vực. Xin vui lòng mang theo bản sao sơ yếu lý lịch của quý vị.\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Tour of Dublin\\n1:00 P.M. to 4:00 P.M. - Visit some interesting sites in our host city. Wear comfortable shoes, as tour participants will cover approximately two miles.\", \"vi\": \"Chuyến tham quan Dublin\\n13:00 đến 16:00 – Tham quan một số địa điểm thú vị tại thành phố chủ nhà của chúng ta. Xin quý vị mang giày dép thoải mái, vì các thành viên tham gia tour sẽ đi bộ khoảng hai dặm.\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Association of Accounting Professionals\\nAnnual meeting–Scheduled events\", \"vi\": \"Hiệp hội các Chuyên gia Kế toán\\nHội nghị thường niên – Các sự kiện đã được lên lịch\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"https://www.app.org.ie/annualmeeting/schedule\", \"vi\": \"https://www.app.org.ie/annualmeeting/schedule\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Friday, 4 February\", \"vi\": \"Thứ Sáu, ngày 4 tháng 2\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Saturday, 5 February\", \"vi\": \"Thứ Bảy, ngày 5 tháng 2\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}]' WHERE `id` = '2f2b64b7-a0a5-4724-b701-710af3583736';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.junctiontours.ca\", \"vi\": \"http://www.junctiontours.ca\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Make your trip to Toronto memorable with help from Junction Tours!\", \"vi\": \"Hãy biến chuyến đi của quý vị đến Toronto thành một kỷ niệm đáng nhớ với sự hỗ trợ từ Junction Tours!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We offer a variety of tour packages to suit everyone\'s tastes.\", \"vi\": \"Chúng tôi cung cấp nhiều gói tour đa dạng để phù hợp với sở thích của mọi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Tour 1: Full-day tour for sports fans!\", \"vi\": \"Chuyến tham quan số 1: Chuyến tham quan cả ngày dành cho những người hâm mộ thể thao!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Take a tour of Rogers Centre and the Hockey Hall of Fame.\", \"vi\": \"Hãy tham quan Trung tâm Rogers và Bảo tàng Danh vọng Khúc côn cầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"You may even spot your favorite player!\", \"vi\": \"Thậm chí, quý vị còn có thể bắt gặp cầu thủ yêu thích của mình nữa!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Lunch provided.\", \"vi\": \"Có phục vụ bữa trưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Tour 2: Full-day hop-on, hop-off tour for visiting all of Toronto\'s major tourist attractions.\", \"vi\": \"Chuyến tham quan số 2: Chuyến tham quan cả ngày theo hình thức lên xuống tự do để khám phá tất cả các điểm tham quan nổi bật của Toronto.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Board the bus anywhere on the circuit and get off at the places that interest you most.\", \"vi\": \"Quý vị có thể lên xe buýt tại bất kỳ điểm nào dọc tuyến đường và xuống xe tại những địa điểm mà quý vị quan tâm nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Stay as long as you like at each site!\", \"vi\": \"Quý vị có thể ở lại bao lâu tùy thích tại mỗi địa điểm!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Tour 3: Half-day tour of the best shopping sites that Toronto has to offer.\", \"vi\": \"Chuyến tham quan số 3: Chuyến tham quan nửa ngày đến những địa điểm mua sắm hấp dẫn nhất tại Toronto.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Participants get exclusive discounts at the Eaton Centre.\", \"vi\": \"Quý vị tham gia sẽ được hưởng các ưu đãi giảm giá dành riêng tại Trung tâm Eaton.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Tour 4: Full-day Toronto Island tour with a scenic ferry ride that will give you amazing views of the Toronto skyline.\", \"vi\": \"Chuyến tham quan số 4: Chuyến tham quan đảo Toronto trọn ngày với hành trình đi phà ngắm cảnh, mang đến cho quý vị những góc nhìn tuyệt vời về đường chân trời của Toronto.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Lunch provided.\", \"vi\": \"Có phục vụ bữa trưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Tour 5: Half-day tour of the CN Tower, Toronto\'s most iconic building.\", \"vi\": \"Chuyến tham quan số 5: Chuyến tham quan nửa ngày tại Tháp CN, công trình kiến trúc biểu tượng nhất của Toronto.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Get your camera ready for the highest observation platform in the Western Hemisphere!\", \"vi\": \"Hãy chuẩn bị máy ảnh của quý vị để chiêm ngưỡng đài quan sát cao nhất ở Tây Bán Cầu!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"All of our tours are available daily, excluding national holidays.\", \"vi\": \"Tất cả các tour du lịch của chúng tôi đều được tổ chức hàng ngày, trừ các ngày lễ quốc gia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Participants can meet at our downtown office or we can pick you up from the Emery Hotel or Hotel Cruz at no extra charge.\", \"vi\": \"Quý vị có thể đến gặp chúng tôi tại văn phòng ở trung tâm thành phố, hoặc chúng tôi có thể đón quý vị tại Khách sạn Emery hoặc Khách sạn Cruz mà không tính thêm phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Meals are not included unless otherwise specified.\", \"vi\": \"Các bữa ăn không được bao gồm trừ khi có quy định khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Winston Hart\\n★★★★★ - → Review of Junction Tours\\n\\nThe booking process for Junction Tours was straightforward, and I was kept well informed about all related details along the way. I was really impressed with the thorough preparations of our tour guide, Stephen. I started feeling seasick while crossing the water, due to rough waves. Stephen took me up to the deck for some fresh air and gave me some chilled bottled water. He was also extremely knowledgeable about Toronto\'s history and amenities. We wanted to bring home some Toronto-themed gifts to help us remember our trip, and Stephen made some very helpful suggestions about what to buy and where. We had so much fun meeting other participants in our group, including a family that was visiting all the way from Japan. The only downside of this tour was that the portion size for the lunch was quite small. Despite this, I would highly recommend Junction Tours to everyone.\", \"vi\": \"Winston Hart\\n★★★★★ - → Đánh giá về Junction Tours\\n\\nQuy trình đặt tour tại Junction Tours rất đơn giản, và tôi luôn được cập nhật đầy đủ mọi thông tin liên quan trong suốt quá trình. Tôi thực sự ấn tượng với sự chuẩn bị kỹ lưỡng của hướng dẫn viên du lịch của chúng tôi, anh Stephen. Khi đang di chuyển trên mặt nước, do sóng lớn nên tôi bắt đầu cảm thấy say sóng. Stephen đã dẫn tôi lên boong tàu hít thở không khí trong lành và đưa cho tôi một chai nước mát lạnh. Anh ấy cũng rất am hiểu về lịch sử và các điểm tham quan nổi bật của Toronto. Chúng tôi muốn mua một số món quà mang đậm dấu ấn Toronto để lưu giữ kỷ niệm về chuyến đi, và Stephen đã đưa ra những gợi ý vô cùng hữu ích về những món nên mua cũng như địa điểm mua. Chúng tôi đã có những giây phút vô cùng thú vị khi làm quen với các thành viên khác trong đoàn, trong đó có một gia đình đến từ tận Nhật Bản. Điểm trừ duy nhất của chuyến tham quan này là khẩu phần bữa trưa khá ít. Mặc dù vậy, tôi vẫn xin nhiệt liệt giới thiệu Junction Tours đến tất cả mọi người.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '2fb07a36-ac2b-4860-9dd4-05ae30e870b9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"TASTE! SHARE! WIN!\", \"vi\": \"HÃY THƯỞNG THỨC! HÃY CHIA SẺ! HÃY GIÀNH GIẢI THƯỞNG!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Here at Sawadee World Bistro, our talented chefs bring the world to you by serving flavorful specialties from around the globe.\", \"vi\": \"Tại Sawadee World Bistro, các đầu bếp tài năng của chúng tôi sẽ mang cả thế giới đến với quý khách thông qua những món ăn đặc sắc và đậm đà hương vị từ khắp nơi trên thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Now with the click of a button, you can share your dining experience with the world!\", \"vi\": \"Giờ đây, chỉ với một cú nhấp chuột, quý vị có thể chia sẻ trải nghiệm ẩm thực của mình với cả thế giới!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Just take a picture of your meal and post it on our Web site.\", \"vi\": \"Quý vị chỉ cần chụp ảnh món ăn của mình và đăng lên trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"You will automatically be entered for a chance to win a $100 gift card.\", \"vi\": \"Quý vị sẽ tự động được tham gia chương trình bốc thăm trúng thưởng để có cơ hội nhận được một thẻ quà tặng trị giá 100 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"What are you waiting for?\", \"vi\": \"Còn chần chừ gì nữa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"www.sawadeeworldbistro.com/tastesharewin\", \"vi\": \"www.sawadeeworldbistro.com/tastesharewin\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '2fb8caeb-1a4e-4833-b49a-e616b42701e7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Driverless Buses in Swansea?\", \"vi\": \"Xe buýt không người lái tại Swansea?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"SWANSEA (12 May)—A consortium of city government officials and local business leaders is considering the purchase of driverless buses for some city routes.\", \"vi\": \"SWANSEA (ngày 12 tháng 5) — Một nhóm gồm các quan chức chính quyền thành phố và các nhà lãnh đạo doanh nghiệp địa phương đang xem xét việc mua các xe buýt không người lái để phục vụ một số tuyến đường trong thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Commissioned with exploring options to improve transportation in Swansea and surrounding areas, the group recently sent three members to Malaga, Spain, where driverless buses run an eight-kilometre loop several times a day.\", \"vi\": \"Được giao nhiệm vụ nghiên cứu các phương án nhằm cải thiện hệ thống giao thông tại Swansea và các khu vực lân cận, nhóm này gần đây đã cử ba thành viên đến Malaga, Tây Ban Nha, nơi các xe buýt không người lái đang vận hành trên một tuyến vòng dài tám kilômét nhiều lần mỗi ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Consortium member Gareth Elias was impressed by what he learned.\", \"vi\": \"Ông Gareth Elias, thành viên của liên minh, đã rất ấn tượng với những điều mình được biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Despite concerns about safety and traffic regulations, Mr. Elias could see driverless buses becoming a reality before long, but only in specific cases.\", \"vi\": \"Dù còn những lo ngại về an toàn và quy định giao thông, ông Elias nhận định rằng xe buýt tự lái có thể sớm trở thành hiện thực, nhưng chỉ trong một số trường hợp cụ thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"“I believe they would be particularly useful during festivals and special events,” he said.\", \"vi\": \"“Tôi tin rằng chúng sẽ đặc biệt hữu ích trong các lễ hội và sự kiện đặc biệt,” ông nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"“I can’t imagine them being on the roads every day.”\", \"vi\": \"“Tôi không thể hình dung được cảnh họ phải lưu thông trên đường mỗi ngày.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Anisha Deepak, an engineer specialising in transportation innovation, served as a technical consultant on the trip.\", \"vi\": \"Bà Anisha Deepak, một kỹ sư chuyên về đổi mới trong lĩnh vực giao thông, đã đảm nhiệm vai trò cố vấn kỹ thuật trong chuyến đi này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"She was struck by the complexity of the buses\' artificial intelligence system, which allows them to learn as they collect data on every trip.\", \"vi\": \"Cô đã vô cùng ấn tượng trước sự phức tạp của hệ thống trí tuệ nhân tạo trên các chiếc xe buýt, hệ thống này cho phép chúng tự học hỏi trong quá trình thu thập dữ liệu trên mỗi chuyến đi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"\\\"Artificial intelligence makes these buses very safe in real-world situations,\\\" she said.\", \"vi\": \"\\\"Trí tuệ nhân tạo giúp những chiếc xe buýt này trở nên rất an toàn trong các tình huống thực tế,\\\" bà nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"\\\"Nevertheless, it\'s best to have a human operator on board at all times in case of emergencies.\\\"\", \"vi\": \"\\\"Tuy nhiên, tốt nhất là luôn có một nhân viên điều khiển trực tiếp trên tàu để đề phòng các trường hợp khẩn cấp.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"A public community forum is scheduled for 2 June to discuss the benefits and drawbacks of driverless buses.\", \"vi\": \"Một diễn đàn cộng đồng mở sẽ được tổ chức vào ngày 2 tháng 6 nhằm thảo luận về những lợi ích và hạn chế của xe buýt không người lái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Visit the Swansea Town Council\'s Web site at www.swanseatowncouncil.gov.uk to learn more.\", \"vi\": \"Quý vị vui lòng truy cập trang web của Hội đồng Thành phố Swansea tại địa chỉ www.swanseatowncouncil.gov.uk để tìm hiểu thêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '300f20be-3305-40ff-b274-4bafe6cef589';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Tracy Felsenthal\", \"vi\": \"Từ: Tracy Felsenthal\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Jon Davies\", \"vi\": \"Gửi: Jon Davies\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: December 8\", \"vi\": \"Ngày: 8 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Letter\", \"vi\": \"Tài liệu đính kèm: Thư\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Davies:\", \"vi\": \"Kính gửi ông Davies:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Attached please find the details for your trip to Bratislava, Slovakia.\", \"vi\": \"Xin vui lòng xem chi tiết đính kèm về chuyến đi của quý vị đến Bratislava, Slovakia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It includes your itinerary, hotel confirmation, and confirmation of your participation in the conference of the World Federation of Flight Attendants (WFFA).\", \"vi\": \"Tài liệu này bao gồm lịch trình của quý vị, thư xác nhận đặt phòng khách sạn và thư xác nhận việc quý vị tham dự hội nghị của Liên đoàn Tiếp viên Hàng không Thế giới (WFFA).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"There are also instructions for requesting reimbursement for any expenses you incur.\", \"vi\": \"Ngoài ra, còn có hướng dẫn về cách yêu cầu hoàn trả các khoản chi phí mà quý vị đã phải chi trả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please print and sign a copy of the attached letter and return it to me at your earliest convenience; it serves as acknowledgment that you have received the information.\", \"vi\": \"Kính mong Quý vị in ra và ký tên vào một bản sao của lá thư đính kèm, sau đó gửi lại cho tôi ngay khi có thể; bản sao này sẽ được coi là xác nhận rằng Quý vị đã nhận được thông tin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"You may wish to print a copy for your records as well.\", \"vi\": \"Quý vị cũng có thể in một bản để lưu giữ làm tài liệu tham khảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"If you have any questions, please let me know.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Tracy Felsenthal\", \"vi\": \"Tracy Felsenthal\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Staff Development Coordinator\", \"vi\": \"Điều phối viên Phát triển Nhân sự\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Aileron Airways\", \"vi\": \"Hãng hàng không Aileron Airways\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '30300aff-aec0-48e6-ae4f-c3f09fd18313';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Welcome to Rosen Valley Bank!\", \"vi\": \"Chào mừng quý khách đến với Ngân hàng Rosen Valley!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To activate your debit card online, follow these steps:\", \"vi\": \"Để kích hoạt thẻ ghi nợ của quý vị trực tuyến, vui lòng thực hiện theo các bước sau:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Go to www.rosenvalleybank.com and click on the \\\"Debit Card\\\" tab.\", \"vi\": \"Vui lòng truy cập trang www.rosenvalleybank.com và nhấp vào tab “Thẻ ghi nợ”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Enter your full, 16-digit debit card number.\", \"vi\": \"Vui lòng nhập số thẻ ghi nợ đầy đủ gồm 16 chữ số của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Type in your temporary PIN number.\", \"vi\": \"Vui lòng nhập mã PIN tạm thời của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"For security purposes, a 4-digit number should have been mailed to you in a separate letter to serve as a temporary password for card activation purposes.\", \"vi\": \"Vì lý do bảo mật, một mã gồm 4 chữ số đã được gửi đến quý vị qua thư riêng để dùng làm mật khẩu tạm thời nhằm kích hoạt thẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"If you have not received this letter, please contact your local branch.\", \"vi\": \"Nếu quý vị chưa nhận được thư này, xin vui lòng liên hệ với chi nhánh địa phương của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You will be prompted to create your own unique 4-digit debit card PIN.\", \"vi\": \"Quý vị sẽ được yêu cầu tạo mã PIN 4 chữ số riêng cho thẻ ghi nợ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"You will be required to provide this number each time you use your card for purchases or to access cash.\", \"vi\": \"Quý vị sẽ phải cung cấp số này mỗi khi sử dụng thẻ để mua hàng hoặc rút tiền mặt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Click the \\\"Activate\\\" icon at the bottom of the screen.\", \"vi\": \"Vui lòng nhấp vào biểu tượng “Kích hoạt” ở phía dưới màn hình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"You may now begin using your Rosen Valley debit card.\", \"vi\": \"Quý vị hiện đã có thể bắt đầu sử dụng thẻ ghi nợ Rosen Valley của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Rosen Valley Bank\", \"vi\": \"Ngân hàng Rosen Valley\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '303f2a7c-568b-4af0-8551-6a227ca91125';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"December 2\", \"vi\": \"Ngày 2 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Paul Reggar, Manager\", \"vi\": \"Ông Paul Reggar, Giám đốc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Pelder Opticians\", \"vi\": \"Cửa hàng Kính mắt Pelder\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"930 Main Street\", \"vi\": \"930 Phố Main\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Tamisville VT 05003\", \"vi\": \"Tamisville, VT 05003\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Reggar,\", \"vi\": \"Kính gửi ông Reggar,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I recently visited your store and was unable to find eyeglass frames that were the right size for me.\", \"vi\": \"Gần đây, tôi đã ghé thăm cửa hàng của quý vị nhưng không tìm được gọng kính có kích thước phù hợp với tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Ms. Morgan waited on me and was very helpful, but you had virtually no adult styles that fit my small, narrow face.\", \"vi\": \"Cô Morgan đã phục vụ tôi và rất nhiệt tình, nhưng tại đây hầu như không có mẫu trang phục dành cho người lớn nào phù hợp với khuôn mặt nhỏ và hẹp của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I hope that in the future you will have more petite frames for women.\", \"vi\": \"Tôi hy vọng rằng trong tương lai, quý công ty sẽ có thêm nhiều mẫu trang phục dành cho phụ nữ có vóc dáng nhỏ nhắn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I found a pretty pair of glasses online at Your Best Frames that are a petite size.\", \"vi\": \"Tôi đã tìm thấy một cặp kính rất đẹp trên trang web Your Best Frames, có kích thước nhỏ nhắn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I plan to purchase them this week.\", \"vi\": \"Tôi dự định sẽ mua chúng trong tuần này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"If I buy the frames, could I have them shipped directly to your store for you to make and insert the lenses?\", \"vi\": \"Nếu tôi mua gọng kính, liệu tôi có thể yêu cầu gửi hàng trực tiếp đến cửa hàng của quý vị để quý vị tiến hành lắp kính không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I look forward to hearing back from you promptly.\", \"vi\": \"Tôi mong sớm nhận được phản hồi từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Stephanie Potts\", \"vi\": \"Stephanie Potts\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Stephanie Potts\", \"vi\": \"Stephanie Potts\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Date: December 5\", \"vi\": \"Ngày: 5 tháng 12\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Customer: Stephanie Potts\\n201 Broad Street, Tamisville VT 05003\", \"vi\": \"Khách hàng: Stephanie Potts\\n201 Broad Street, Tamisville, VT 05003\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Ship to: Manager, Pelder Opticians\\nRE: Order for S. Potts\\n930 Main Street, Tamisville VT 05003\", \"vi\": \"Gửi tới: Quản lý, Pelder Opticians\\nV/v: Đơn đặt hàng cho ông S. Potts\\n930 Main Street, Tamisville, VT 05003\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Order number: 28734T2\\nOrder details: 1 pair women\'s frames by Sue Lane\\nColor/Style: Black/Petite frame 9374-87\", \"vi\": \"Số đơn hàng: 28734T2\\nChi tiết đơn hàng: 1 cặp gọng kính nữ của thương hiệu Sue Lane\\nMàu sắc/Kiểu dáng: Đen/Gọng kính cỡ nhỏ 9374-87\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Price: $127.00\\nCredit card: LANA Bank **** **** **** 7872\", \"vi\": \"Giá: 127,00 USD\\nThẻ tín dụng: Ngân hàng LANA **** **** **** 7872\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Processed by: Simon Gyula\", \"vi\": \"Người xử lý: Simon Gyula\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Notes: Ship directly to Pelder Opticians, per Ms. Potts. Expected delivery by December 12. Paid in full.\", \"vi\": \"Ghi chú: Vui lòng gửi hàng trực tiếp đến Pelder Opticians, theo yêu cầu của bà Potts. Dự kiến hàng sẽ được giao trước ngày 12 tháng 12. Đã thanh toán đầy đủ.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"YOUR BEST FRAMES\", \"vi\": \"NHỮNG GỐC ẢNH TUYỆT VỜI NHẤT CỦA QUÝ VỊ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"www.yourbestframes.com\", \"vi\": \"www.yourbestframes.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '30979e21-94bd-416f-a2e0-a58b4f3bef32';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All Farrington Integrated Logistics Staff <staff@farringtonil.com>\", \"vi\": \"Gửi: Toàn thể nhân viên Công ty Farrington Integrated Logistics <staff@farringtonil.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Venkata Nayar <v.nayar@farringtonil.com>\", \"vi\": \"Từ: Venkata Nayar <v.nayar@farringtonil.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: February 13\", \"vi\": \"Ngày: 13 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Upcoming Plans\", \"vi\": \"Chủ đề: Các kế hoạch sắp tới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Attachment: Confirmed schedule\", \"vi\": \"Tệp đính kèm: Lịch trình đã được xác nhận\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Staff,\", \"vi\": \"Kính gửi quý đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Throughout the month of March, Farrington Integrated Logistics (FIL) will begin offering several sessions to help our employees enhance their skills and network with people from other departments.\", \"vi\": \"Trong suốt tháng 3, Công ty Farrington Integrated Logistics (FIL) sẽ bắt đầu tổ chức một số buổi đào tạo nhằm giúp các nhân viên của chúng tôi nâng cao kỹ năng và mở rộng mạng lưới quan hệ với các đồng nghiệp từ các phòng ban khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We hope you will find them informative and worthwhile.\", \"vi\": \"Chúng tôi hy vọng quý vị sẽ thấy những tài liệu này mang tính thông tin và hữu ích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please note that the sessions for new hires and department managers are mandatory.\", \"vi\": \"Xin lưu ý rằng các buổi đào tạo dành cho nhân viên mới và các trưởng phòng là bắt buộc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"If you expect to be absent, please let me know, and I will assess the situation on a case-by-case basis.\", \"vi\": \"Nếu quý vị dự kiến sẽ vắng mặt, xin vui lòng thông báo cho tôi biết; tôi sẽ xem xét từng trường hợp cụ thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"For the sessions open to all staff, there is no need to sign up for those held on site at lunchtime, but you do need to register in advance for the evening one.\", \"vi\": \"Đối với các buổi dành cho toàn thể nhân viên, quý vị không cần đăng ký tham gia các buổi được tổ chức tại cơ quan vào giờ ăn trưa, nhưng quý vị cần đăng ký trước để tham gia buổi vào buổi tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Venkata Nayar\", \"vi\": \"Tôi e rằng mình đã thất bại\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Operations Manager, Farrington Integrated Logistics\", \"vi\": \"Giám đốc Vận hành, Farrington Integrated Logistics\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Date - Time - Details - Participants\", \"vi\": \"Ngày - Giờ - Chi tiết - Những người tham gia\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Mon., March 3 - 12:30 p.m. - Company cafeteria, Lunch - New Hires\", \"vi\": \"Thứ Hai, ngày 3 tháng 3 – 12 giờ 30 phút trưa – Nhà ăn công ty, Bữa trưa – Nhân viên mới\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Thurs., March 13 - 12:30 p.m. - Company cafeteria, Lunch - FIL\", \"vi\": \"Thứ Năm, ngày 13 tháng 3 – 12 giờ 30 phút trưa – Căng-tin công ty, Bữa trưa – FIL\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Tues., March 18 - 7:00 p.m. - Sunshine Café, Dinner - Department Managers\", \"vi\": \"Thứ Ba, ngày 18 tháng 3 – 19:00 – Sunshine Café, Bữa tối – Các Trưởng phòng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Fri., March 21 - 6:30 p.m. - Victoria\'s Bistro, Dinner - FIL\", \"vi\": \"Thứ Sáu, ngày 21 tháng 3 – 18h30 – Victoria\'s Bistro, Bữa tối – FIL\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Mon., March 24 - 11:30 a.m. - Company cafeteria, Lunch - FIL\", \"vi\": \"Thứ Hai, ngày 24 tháng 3 – 11 giờ 30 phút sáng – Nhà ăn công ty, Bữa trưa – FIL\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Farrington Integrated Logistics March Sessions\", \"vi\": \"Các buổi hội thảo tháng 3 của Farrington Integrated Logistics\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"To: Venkata Nayar <v.nayar@farringtonil.com>\", \"vi\": \"Gửi tới: Venkata Nayar <v.nayar@farringtonil.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"From: Komaki Inaba <inabakomaki@mkmail.com>\", \"vi\": \"Từ: Komaki Inaba <inabakomaki@mkmail.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Date: April 2\", \"vi\": \"Ngày: 2 tháng 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Subject: March event\", \"vi\": \"Chủ đề: Sự kiện tháng 3\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Dear Mr. Nayar,\", \"vi\": \"Kính gửi ông Nayar,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Thank you so much for inviting me to lead a session at your office.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã mời tôi dẫn dắt một buổi thảo luận tại văn phòng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"The participants were fully engaged, and I found the discussions to be fruitful.\", \"vi\": \"Các đại biểu đã tham gia rất tích cực, và tôi thấy các cuộc thảo luận đã mang lại nhiều kết quả hữu ích.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I enjoyed chatting with all of your staff over dinner at the Sunshine Café and found Ms. McCormack\'s insights to be particularly interesting.\", \"vi\": \"Tôi đã rất vui khi được trò chuyện với toàn thể nhân viên của quý công ty trong bữa tối tại Sunshine Café và thấy những chia sẻ của bà McCormack đặc biệt thú vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I am planning to branch out into consulting full time, so I am working on content for my Web site, which will be available to visitors from the end of next month.\", \"vi\": \"Tôi đang có kế hoạch chuyển sang làm việc toàn thời gian trong lĩnh vực tư vấn, vì vậy hiện tại tôi đang chuẩn bị nội dung cho trang web của mình; trang web này sẽ chính thức mở cửa cho quý vị truy cập vào cuối tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I\'m wondering if you or one of your colleagues would be willing to provide a testimonial to be used on the site.\", \"vi\": \"Tôi đang tự hỏi liệu quý vị hoặc một trong các đồng nghiệp của quý vị có sẵn lòng cung cấp lời chứng thực để sử dụng trên trang web hay không.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"I would appreciate it if you could let me know if this is possible.\", \"vi\": \"Tôi sẽ rất cảm kích nếu quý vị có thể cho tôi biết liệu điều này có khả thi hay không.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"It would be very helpful to me.\", \"vi\": \"Điều đó sẽ giúp ích rất nhiều cho tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Warmest regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Komaki Inaba\", \"vi\": \"Trở thành Inaba\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}]' WHERE `id` = '310b43ee-7737-4ba3-aaf6-fb793e4c50a3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Kurt Webber (4:30 P.M.)\", \"vi\": \"Kurt Webber (4 giờ 30 chiều)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Jake and I are grabbing a bite to eat after work, around 5:30.\", \"vi\": \"Jake và tôi sẽ đi ăn nhẹ sau giờ làm việc, khoảng 5 giờ 30.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Anyone care to join us?\", \"vi\": \"Có ai muốn tham gia cùng chúng tôi không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Davi Avril (4:31 P.M.)\", \"vi\": \"Davi Avril (4 giờ 31 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Maybe.\", \"vi\": \"Có lẽ vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I still have some work to do on the midyear report.\", \"vi\": \"Tôi vẫn còn một số việc cần hoàn thành liên quan đến báo cáo giữa năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Where are you planning to go?\", \"vi\": \"Quý vị dự định đi đâu vậy?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Kurt Webber (4:32 P.M.)\", \"vi\": \"Kurt Webber (4 giờ 32 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We\'re thinking of trying the new Mexican place on Slate Road.\", \"vi\": \"Chúng tôi đang có ý định thử quán ăn Mexico mới mở trên đường Slate.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"It\'s called Ocho Coronas.\", \"vi\": \"Tên của nó là Ocho Coronas.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Tim Foxx (4:33 P.M.)\", \"vi\": \"Tim Foxx (4:33 P.M.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You\'re out of luck.\", \"vi\": \"Quý vị thật không may mắn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"That place closed a few days ago.\", \"vi\": \"Nơi đó đã đóng cửa cách đây vài ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Kurt Webber (4:34 P.M.)\", \"vi\": \"Kurt Webber (4 giờ 34 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"That\'s too bad.\", \"vi\": \"Thật đáng tiếc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I heard great things about it.\", \"vi\": \"Tôi đã nghe nhiều lời khen ngợi về nó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Tim Foxx (4:36 P.M.)\", \"vi\": \"Tim Foxx (4:36 P.M.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"How about Lotus Tacos around the corner?\", \"vi\": \"Quán Lotus Tacos ngay góc phố kia thì sao ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"They always have a special menu on Fridays.\", \"vi\": \"Vào các ngày thứ Sáu, họ luôn có thực đơn đặc biệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Kurt Webber (4:37 P.M.)\", \"vi\": \"Kurt Webber (4 giờ 37 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"That would be great.\", \"vi\": \"Điều đó thật tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Do you want to go to Lotus Tacos, Jake?\", \"vi\": \"Anh có muốn đến Lotus Tacos không, Jake?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Davi Avril (4:38 P.M.)\", \"vi\": \"Davi Avril (4 giờ 38 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"OK, but I won\'t be able to get there till about six.\", \"vi\": \"Được rồi, nhưng tôi sẽ không thể đến đó trước khoảng sáu giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Jake Rivas (4:39 P.M.)\", \"vi\": \"Jake Rivas (4 giờ 39 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Sounds good to me.\", \"vi\": \"Tôi thấy ý kiến đó hay đấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"And Davi, I just sent you the updated figures for the report.\", \"vi\": \"Và Davi, tôi vừa gửi cho anh những số liệu cập nhật cho bản báo cáo rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '31231af0-fef4-4677-b393-97bb4fb35cbd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Tin Prices May Improve\", \"vi\": \"Giá thiếc có thể sẽ tăng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"LONDON (12 September)—Prices for tin rose to a record high in August.\", \"vi\": \"LONDON (ngày 12 tháng 9) — Giá thiếc đã tăng lên mức cao kỷ lục trong tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"International inventories are unusually low at this time, and problems with availability persist.\", \"vi\": \"Hiện tại, lượng hàng tồn kho trên thị trường quốc tế đang ở mức thấp bất thường, và tình trạng khan hiếm hàng hóa vẫn tiếp diễn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The price increases are driven by reduced supply in countries that produce the metal, coupled with increasing worldwide demand for and manufacturing of electronics, whose components are joined together with tin compounds.\", \"vi\": \"Sự gia tăng giá cả xuất phát từ việc nguồn cung tại các quốc gia sản xuất kim loại này bị sụt giảm, kết hợp với nhu cầu ngày càng tăng trên toàn cầu đối với các sản phẩm điện tử cũng như hoạt động sản xuất các sản phẩm này, trong đó các linh kiện được kết nối với nhau bằng các hợp chất thiếc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Chilean Smelting, Inc., a major producer, has invested in improved equipment and aims to increase production.\", \"vi\": \"Công ty Chilean Smelting, Inc., một nhà sản xuất lớn, đã đầu tư vào việc nâng cấp thiết bị và đặt mục tiêu tăng sản lượng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As a result, tin traders predict some moderation in prices as supplies rise.\", \"vi\": \"Do đó, các nhà kinh doanh thiếc dự báo giá sẽ có xu hướng giảm nhẹ khi nguồn cung tăng lên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '3129301c-35b8-46c1-971b-a3c268540308';
