UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Titanium Gym\", \"vi\": \"Phòng tập Titanium Gym\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"450 Third Street, Creville\", \"vi\": \"Số 450 Đường số 3, Creville\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"555-0177\", \"vi\": \"555-0177\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"25% Off a 3-month Membership\", \"vi\": \"Giảm giá 25% cho Gói thành viên 3 tháng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Present this coupon upon sign-up to receive three months of membership at Titanium Gym for just $135!\", \"vi\": \"Hãy xuất trình phiếu giảm giá này khi đăng ký để nhận ba tháng làm thành viên tại Titanium Gym chỉ với giá 135 USD!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Members are entitled to a monthly session with a certified personal trainer and unlimited access to classes including kickboxing, aerobics, and Pilates.\", \"vi\": \"Hội viên có quyền tham gia một buổi tập hàng tháng với huấn luyện viên cá nhân được cấp chứng chỉ và không giới hạn số lần tham gia các lớp học bao gồm kickboxing, thể dục nhịp điệu (aerobics) và Pilates.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Offer available only to new members.\", \"vi\": \"Ưu đãi chỉ áp dụng cho hội viên mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Sign-up fee not included.\", \"vi\": \"Chưa bao gồm phí đăng ký.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Membership period must begin by March 31.\", \"vi\": \"Thời hạn thẻ thành viên phải bắt đầu trước ngày 31 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '3187255a-971e-42a1-9eb4-b2d7fa1e74d2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.clarrellestate.com.au/about\", \"vi\": \"https://www.clarrellestate.com.au/about\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"About - Events - Photos - The Foundation\", \"vi\": \"Giới thiệu - Các sự kiện - Hình ảnh - Quỹ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Welcome to the Clarrell Estate—Ballarton’s premier centre for the arts!\", \"vi\": \"Chào mừng quý vị đến với Khu bất động sản Clarrell — trung tâm nghệ thuật hàng đầu của Ballarton!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The exquisite grounds of the estate are situated on 60 hectares of hilly terrain featuring lush English gardens and an impressive manor house that was designed by noted architect Owen Barton.\", \"vi\": \"Khuôn viên tuyệt đẹp của khu bất động sản này tọa lạc trên diện tích 60 héc-ta địa hình đồi núi, nổi bật với những khu vườn kiểu Anh tươi tốt và một dinh thự hoành tráng do kiến trúc sư nổi tiếng Owen Barton thiết kế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Ten years ago, the Clarrell Foundation decided to transform the estate into an arts centre.\", \"vi\": \"Mười năm trước, Quỹ Clarrell đã quyết định chuyển đổi khu bất động sản này thành một trung tâm nghệ thuật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Initially, the foundation opened the manor house to the public, highlighting the Clarrell family art collection.\", \"vi\": \"Ban đầu, quỹ này đã mở cửa dinh thự cho công chúng tham quan, nhằm giới thiệu bộ sưu tập nghệ thuật của gia đình Clarrell.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In the last three years, a large, multiuse complex was built near the property entrance, complete with art studios and a theatre.\", \"vi\": \"Trong ba năm qua, một khu phức hợp quy mô lớn, đa chức năng đã được xây dựng gần lối vào khu bất động sản này, bao gồm các xưởng nghệ thuật và một nhà hát.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The Clarrell Estate’s museum and gardens are open to the public free of charge.\", \"vi\": \"Bảo tàng và khu vườn của Khu bất động sản Clarrell mở cửa miễn phí cho công chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In addition, the theatre hosts public lectures as well as musical performances, and the studios showcase individual artists’ curated works.\", \"vi\": \"Bên cạnh đó, nhà hát còn tổ chức các buổi diễn thuyết công khai cũng như các buổi biểu diễn âm nhạc, trong khi các xưởng nghệ thuật trưng bày các tác phẩm được tuyển chọn kỹ lưỡng của các nghệ sĩ cá nhân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"For a complete schedule, a list of current artists, and information on admission fees for the theatre and studios, please visit the Events page.\", \"vi\": \"Để xem lịch trình đầy đủ, danh sách các nghệ sĩ hiện tại cũng như thông tin về giá vé vào cửa nhà hát và các phòng thu, xin vui lòng truy cập trang Sự kiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Join the Clarrell Foundation to enjoy members-only special events and discounts on performances.\", \"vi\": \"Hãy gia nhập Quỹ Clarrell để được tham gia các sự kiện đặc biệt dành riêng cho hội viên và hưởng các ưu đãi khi tham dự các buổi biểu diễn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Members also have the opportunity to reserve the gardens for private events.\", \"vi\": \"Các thành viên cũng có cơ hội đặt trước khu vườn để tổ chức các sự kiện riêng tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To become a member, contact Alicia Ji at aji@clarrellestate.com.au.\", \"vi\": \"Để trở thành thành viên, xin vui lòng liên hệ với Alicia Ji qua địa chỉ email aji@clarrellestate.com.au.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '31aecd5b-beb5-45e0-9617-23fd3fc49e3e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Jack Elling (10:35 A.M.)\", \"vi\": \"Jack Elling (10 giờ 35 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, everyone.\", \"vi\": \"Xin chào quý vị và các bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Would anyone be able to come into the shop to work tonight?\", \"vi\": \"Có ai có thể đến cửa hàng làm việc vào tối nay không ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Kelly is having car problems and can\'t work her shift.\", \"vi\": \"Kelly đang gặp sự cố với xe ô tô nên không thể đi làm ca của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Emily Chin (10:37 A.M.)\", \"vi\": \"Emily Chin (10 giờ 37 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I can\'t, sorry.\", \"vi\": \"Tôi không thể, xin lỗi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"But aren\'t Maria and Koji also working?\", \"vi\": \"Nhưng chẳng phải Maria và Koji cũng đang làm việc sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Don\'t we usually have two people in the evenings?\", \"vi\": \"Thường thì vào buổi tối chúng ta không phải có hai người sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Jack Elling (10:39 A.M.)\", \"vi\": \"Jack Elling (10 giờ 39 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Yes, we usually have two people, and those two are working tonight.\", \"vi\": \"Vâng, thông thường chúng tôi có hai người, và hai người đó đang làm việc tối nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"But we are having our special promotion, giving away samples of our new ice cream flavors.\", \"vi\": \"Tuy nhiên, hiện tại chúng tôi đang triển khai chương trình khuyến mãi đặc biệt, tặng miễn phí các mẫu thử các hương vị kem mới của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I need a third person to help with that.\", \"vi\": \"Tôi cần có một người thứ ba để giúp đỡ việc đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Emily Chin (10:40 A.M.)\", \"vi\": \"Emily Chin (10 giờ 40 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I\'m attending a birthday party this afternoon, so I can\'t do it.\", \"vi\": \"Chiều nay tôi có dự một bữa tiệc sinh nhật, nên tôi không thể làm việc đó được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Cameron Stein (10:42 A.M.)\", \"vi\": \"Cameron Stein (10 giờ 42 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I could stay on after my day shift is over.\", \"vi\": \"Tôi có thể ở lại làm việc sau khi ca ngày của mình kết thúc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Emily Chin (10:43 A.M.)\", \"vi\": \"Emily Chin (10 giờ 43 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Actually, I could work 6–9 P.M. if you don\'t want to stay.\", \"vi\": \"Thực ra, nếu quý vị không muốn ở lại, tôi có thể làm việc từ 6 giờ tối đến 9 giờ tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"My party is only a few hours.\", \"vi\": \"Bữa tiệc của tôi chỉ kéo dài vài giờ thôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"What do you think?\", \"vi\": \"Quý vị nghĩ sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Cameron Stein (10:44 A.M.)\", \"vi\": \"Cameron Stein (10 giờ 44 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Well, I could really use the overtime hours.\", \"vi\": \"Thật ra thì, tôi rất cần những giờ làm thêm này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Emily Chin (10:45 A.M.)\", \"vi\": \"Emily Chin (10 giờ 45 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Jack Elling (10:46 A.M.)\", \"vi\": \"Jack Elling (10 giờ 46 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Thanks, Cameron!\", \"vi\": \"Cảm ơn anh, Cameron!\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '31af424d-28c5-4593-bf44-9ed8ea8d84c1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.qualitekkresearch.com/aboutus\", \"vi\": \"https://www.qualitekkresearch.com/aboutus\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Home | About Us | Register | Testimonials\", \"vi\": \"Trang chủ | Giới thiệu | Đăng ký | Lời chứng thực\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Thousands of large companies use surveys to measure customer satisfaction with the goal of improving their business.\", \"vi\": \"Hàng nghìn doanh nghiệp lớn sử dụng các cuộc khảo sát để đánh giá mức độ hài lòng của khách hàng, với mục tiêu nâng cao chất lượng hoạt động kinh doanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Qualitekk Research serves its client companies by analyzing survey results and producing detailed reports containing insights about customers\' preferences.\", \"vi\": \"Qualitekk Research phục vụ các doanh nghiệp khách hàng bằng cách phân tích kết quả khảo sát và lập các báo cáo chi tiết, trong đó nêu rõ những thông tin sâu sắc về sở thích của khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Over twelve years of operation, Qualitekk Research has built a strong reputation for providing valuable data.\", \"vi\": \"Trong hơn mười hai năm hoạt động, Qualitekk Research đã xây dựng được uy tín vững chắc nhờ việc cung cấp những dữ liệu có giá trị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Every day, consumers complete more than 20,000 online surveys that provide feedback on hundreds of different products.\", \"vi\": \"Hàng ngày, người tiêu dùng hoàn thành hơn 20.000 cuộc khảo sát trực tuyến nhằm cung cấp ý kiến phản hồi về hàng trăm sản phẩm khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We connect consumers with surveys about products that may interest them.\", \"vi\": \"Chúng tôi kết nối người tiêu dùng với các cuộc khảo sát về những sản phẩm mà họ có thể quan tâm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Participants who submit a survey that we facilitate will earn reward points from us.\", \"vi\": \"Những người tham gia gửi bản khảo sát do chúng tôi tổ chức sẽ nhận được điểm thưởng từ chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"After as few as five surveys, points can be redeemed for a gift card usable at many stores.\", \"vi\": \"Chỉ cần hoàn thành tối thiểu năm cuộc khảo sát, quý vị đã có thể đổi điểm lấy thẻ quà tặng để sử dụng tại nhiều cửa hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"If you would like to join, visit our Register page and complete the member profile questionnaire.\", \"vi\": \"Nếu quý vị muốn tham gia, vui lòng truy cập trang Đăng ký của chúng tôi và điền vào bảng câu hỏi về hồ sơ thành viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"This information will help us identify surveys that match your interests.\", \"vi\": \"Thông tin này sẽ giúp chúng tôi xác định các cuộc khảo sát phù hợp với sở thích của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We will then send you links to those surveys to complete at your leisure.\", \"vi\": \"Sau đó, chúng tôi sẽ gửi cho quý vị các liên kết đến các bản khảo sát này để quý vị có thể hoàn thành vào thời gian rảnh rỗi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"If your interests change, simply update your profile.\", \"vi\": \"Nếu sở thích của quý vị có thay đổi, quý vị chỉ cần cập nhật hồ sơ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"All responses in Qualitekk Research surveys are confidential, and you will never be personally identified with survey data.\", \"vi\": \"Tất cả các câu trả lời trong các cuộc khảo sát của Qualitekk Research đều được bảo mật, và quý vị sẽ không bao giờ bị xác định danh tính cá nhân thông qua dữ liệu khảo sát.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '31dfbc47-9264-465a-961f-ae2059f356d4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Katrina Finton (1:46 P.M.)\", \"vi\": \"Katrina Finton (1 giờ 46 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hey, Steven.\", \"vi\": \"Xin chào, Steven.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I am hoping to move into a new apartment soon, and the landlord requires a letter verifying my place of employment and my income.\", \"vi\": \"Tôi đang hy vọng sẽ sớm chuyển đến một căn hộ mới, và chủ nhà yêu cầu một lá thư xác nhận nơi làm việc cũng như mức thu nhập của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I have written up the letter.\", \"vi\": \"Tôi đã soạn xong lá thư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Would you be willing to sign it today as proof that I work here at Carrino Agency?\", \"vi\": \"Xin hỏi quý vị có thể ký vào đây ngay hôm nay để làm bằng chứng rằng tôi đang làm việc tại Công ty Carrino được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Steven Khen (1:48 P.M.)\", \"vi\": \"Steven Khen (1 giờ 48 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Double-check with Ariana Seltzer first.\", \"vi\": \"Trước tiên, xin vui lòng xác nhận lại với Ariana Seltzer.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The human resources department usually has a form they can provide for you.\", \"vi\": \"Phòng Nhân sự thường có sẵn một mẫu đơn để cung cấp cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Katrina Finton (1:49 P.M.)\", \"vi\": \"Katrina Finton (1 giờ 49 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I tried that.\", \"vi\": \"Tôi đã thử cách đó rồi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"They don\'t have a set form.\", \"vi\": \"Chúng không có hình thức cố định.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Steven Khen (1:50 P.M.)\", \"vi\": \"Steven Khen (1:50 P.M.)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"No problem then.\", \"vi\": \"Vậy thì không có vấn đề gì cả.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Bring your document over.\", \"vi\": \"Xin vui lòng mang tài liệu của quý vị đến đây.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Steven Khen (1:51 P.M.)\", \"vi\": \"Steven Khen (1:51 P.M.)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"By the way, the meeting about the Zaine Company Web site was moved to 3:00 P.M. You already have all your designs for their Web site ready, right?\", \"vi\": \"Nhân tiện, cuộc họp về trang web của Công ty Zaine đã được dời sang lúc 3 giờ chiều. Anh đã chuẩn bị xong tất cả các bản thiết kế cho trang web của họ rồi, phải không ạ?\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Katrina Finton (1:52 P.M.)\", \"vi\": \"Katrina Finton (1 giờ 52 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I\'m all set.\", \"vi\": \"Tôi đã chuẩn bị xong rồi.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '3203765c-eac4-48c4-a823-d4c065df2760';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"WINNIPEG (10 May)—Manitoba-based satellite manufacturer Alita Technology has been awarded a $9 million grant to develop an airborne sensing instrument to be used in the collection of climate data.\", \"vi\": \"WINNIPEG (ngày 10 tháng 5) — Công ty sản xuất vệ tinh Alita Technology có trụ sở tại Manitoba vừa được cấp khoản tài trợ trị giá 9 triệu đô la để phát triển một thiết bị cảm biến trên không nhằm thu thập dữ liệu khí hậu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The device will be engineered to calculate the density and depth of snowpack throughout Canada.\", \"vi\": \"Thiết bị này sẽ được thiết kế để tính toán mật độ và độ sâu của lớp tuyết trên toàn lãnh thổ Canada.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Alita Technology is collaborating with the Microwave Engineering Lab at the University of Southam on the initiative.\", \"vi\": \"Công ty Alita Technology đang hợp tác với Phòng Thí nghiệm Kỹ thuật Vi sóng thuộc Đại học Southam trong khuôn khổ sáng kiến này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Dr. Hugh Jaris, director of the lab’s Remote Sensing Unit, will lead the effort to test one or more prototypes by collecting and analysing data next winter.\", \"vi\": \"Tiến sĩ Hugh Jaris, Trưởng đơn vị Viễn thám thuộc phòng thí nghiệm, sẽ chủ trì công tác thử nghiệm một hoặc nhiều mẫu thử nghiệm thông qua việc thu thập và phân tích dữ liệu vào mùa đông tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Snowpack data is used to measure year-to-year snow trends and fluctuations as well as to help determine how much water from snowmelt will be available in key areas of the country.\", \"vi\": \"Dữ liệu về lớp tuyết tích tụ được sử dụng để đo lường các xu hướng và biến động của lượng tuyết qua từng năm, đồng thời giúp xác định lượng nước từ tuyết tan sẽ có sẵn tại các khu vực trọng điểm của đất nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}]' WHERE `id` = '32398c0e-c017-452b-8df7-6b393e77b68e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dan\'s Specialty Bicycles\", \"vi\": \"Cửa hàng Xe đạp Đặc biệt của Dan\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"60 Everett Way, London, SW11 1AH\", \"vi\": \"60 Everett Way, London, SW11 1AH\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Hours: Monday–Sunday 10 A.M.–6 P.M.\", \"vi\": \"Giờ mở cửa: Thứ Hai–Chủ Nhật, từ 10 giờ sáng đến 6 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Tenth Annual Sale of Secondhand Bicycles!\", \"vi\": \"Chương trình bán xe đạp đã qua sử dụng thường niên lần thứ mười!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We are known for our stock of high-end racing bicycles, but for a limited time every year, we offer a wide selection of secondhand mountain, road, and hybrid bicycles for all ages and abilities.\", \"vi\": \"Chúng tôi được biết đến với kho hàng gồm các mẫu xe đạp đua cao cấp, nhưng vào một khoảng thời gian nhất định hàng năm, chúng tôi cung cấp nhiều lựa chọn xe đạp địa hình, xe đạp đường trường và xe đạp lai đã qua sử dụng, phù hợp với mọi lứa tuổi và trình độ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Each bicycle has been refurbished by a certified technician to ensure a smooth, safe ride.\", \"vi\": \"Mỗi chiếc xe đạp đều đã được một kỹ thuật viên có chứng chỉ tân trang lại để đảm bảo trải nghiệm lái xe êm ái và an toàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Prices range from £15 to £50.\", \"vi\": \"Giá dao động từ 15 đến 50 bảng Anh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The sale runs from 9 May to 22 May.\", \"vi\": \"Chương trình khuyến mãi diễn ra từ ngày 9 tháng 5 đến ngày 22 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Show or mention this advertisement to receive ten percent off the price of any secondhand or new bicycle.\", \"vi\": \"Xin vui lòng xuất trình hoặc đề cập đến quảng cáo này để được giảm 10% giá mua bất kỳ chiếc xe đạp nào, dù là xe đạp đã qua sử dụng hay xe đạp mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"For more information, visit www.dansspecialtybicycles.co.uk.\", \"vi\": \"Để biết thêm thông tin, xin vui lòng truy cập trang web www.dansspecialtybicycles.co.uk.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '326e8181-db6d-463d-8fe1-a3bf12a73ee6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Donovan Auto Lube\", \"vi\": \"Donovan Auto Lube\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Donavan Auto Lube (DAL) is the first choice for residents of Knebworth who want to keep their cars running smoothly.\", \"vi\": \"Donavan Auto Lube (DAL) là lựa chọn hàng đầu dành cho cư dân Knebworth mong muốn giữ cho chiếc xe của mình luôn vận hành trơn tru.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We provide oil changes, tyre rotations, and routine inspections.\", \"vi\": \"Chúng tôi cung cấp các dịch vụ thay dầu, xoay lốp và kiểm tra định kỳ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Our team of certified auto technicians can service all vehicle makes and models.\", \"vi\": \"Đội ngũ kỹ thuật viên ô tô được chứng nhận của chúng tôi có thể bảo dưỡng tất cả các thương hiệu và mẫu xe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Customers may schedule an appointment or simply drive up to any DAL location during our business hours of 8:00 A.M. to 8:00 P.M., Monday to Saturday, and 11:00 A.M. to 5:00 P.M. on Sunday.\", \"vi\": \"Quý khách có thể đặt lịch hẹn hoặc đơn giản là ghé qua bất kỳ chi nhánh nào của DAL trong giờ làm việc của chúng tôi: từ 8 giờ sáng đến 8 giờ tối từ Thứ Hai đến Thứ Bảy, và từ 11 giờ sáng đến 5 giờ chiều vào Chủ Nhật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This summer, DAL offers a special promotion: a 5-quart oil change, oil filter replacement, and comprehensive maintenance check for just £15.\", \"vi\": \"Mùa hè này, DAL mang đến chương trình khuyến mãi đặc biệt: dịch vụ thay dầu 5 quart, thay bộ lọc dầu và kiểm tra bảo dưỡng toàn diện với mức giá chỉ 15 bảng Anh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This offer is available at all DAL locations throughout Herfordshire but may not be combined with any other promotional offer.\", \"vi\": \"Ưu đãi này áp dụng tại tất cả các chi nhánh của DAL trên toàn khu vực Herfordshire, nhưng không được kết hợp với bất kỳ chương trình khuyến mãi nào khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The quoted price does not include value-added tax and does not cover any additional maintenance, repairs, and parts that a vehicle inspection may call for.\", \"vi\": \"Giá niêm yết không bao gồm thuế giá trị gia tăng và không bao gồm các chi phí bảo dưỡng, sửa chữa cũng như phụ tùng bổ sung mà quá trình kiểm tra xe có thể yêu cầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Visit DAL for all your automotive needs.\", \"vi\": \"Hãy ghé thăm DAL để đáp ứng mọi nhu cầu liên quan đến ô tô của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '327155cf-1a18-45f5-b20c-b6de0bc1b9b9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Thank you for your purchase of an Ajaz Water Filter Pitcher.\", \"vi\": \"Cảm ơn bạn vì đã mua Bình Lọc Nước Ajaz.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"It is a wonderful solution for water that tastes great!\", \"vi\": \"Đây là một giải pháp tuyệt vời để có nguồn nước ngon tuyệt!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To improve the effectiveness of the Ajaz Water Filter Pitcher, we ___135___ priming the filter before the first use.\", \"vi\": \"Để nâng cao hiệu quả của Bình Lọc Nước Ajaz, chúng tôi ___135___ việc mồi nước cho bộ lọc trước lần sử dụng đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"___136___ .\", \"vi\": \"___136___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"Then screw the filter clockwise into the lid of the pitcher until it fits ___137___ .\", \"vi\": \"Sau đó, vặn bộ lọc theo chiều kim đồng hồ vào nắp bình cho đến khi khớp ___137___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [137]}, {\"en\": \"As you use the pitcher, remember that ___138___ water flow is a signal that the filter is becoming clogged and will need to be replaced soon.\", \"vi\": \"Khi bạn sử dụng bình, hãy nhớ rằng dòng chảy nước ___138___ là tín hiệu cho thấy bộ lọc đang bị tắc và sẽ cần được thay thế sớm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [138]}]' WHERE `id` = '3274fb79-0ed3-44df-bb53-cc36a279295b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"The Egmont\", \"vi\": \"Egmont\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Situated in Wellington\'s Central Business District, The Egmont is one of the city\'s most popular venues for private celebrations, corporate meetings, fund-raisers, and more.\", \"vi\": \"Tọa lạc tại Khu Thương mại Trung tâm của Wellington, The Egmont là một trong những địa điểm được ưa chuộng nhất thành phố để tổ chức các buổi tiệc riêng tư, hội nghị doanh nghiệp, các sự kiện gây quỹ và nhiều hoạt động khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Its convenient location is just a short walk away from numerous hotels, several bus stops, and a train station.\", \"vi\": \"Vị trí thuận tiện của nơi đây chỉ cách một quãng đường đi bộ ngắn đến nhiều khách sạn, một số trạm xe buýt và một ga tàu hỏa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The Egmont offers two spacious multi-purpose event rooms.\", \"vi\": \"Khách sạn Egmont cung cấp hai phòng tổ chức sự kiện đa năng với không gian rộng rãi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The Manuka Room is best for groups of between 100 and 200, while our grandest space, the Kauri Room, can hold up to 300 guests comfortably.\", \"vi\": \"Phòng Manuka là lựa chọn lý tưởng nhất cho các nhóm từ 100 đến 200 người, trong khi không gian hoành tráng nhất của chúng tôi, Phòng Kauri, có thể đón tiếp thoải mái tối đa 300 khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We also have two dedicated conference rooms, the Rata Room and the Pikao Room, which have maximum capacities of 35 and 70 people, respectively.\", \"vi\": \"Chúng tôi còn có hai phòng hội nghị chuyên dụng là Phòng Rata và Phòng Pikao, với sức chứa tối đa lần lượt là 35 và 70 người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"State-of-the-art projectors, speakers, and other multimedia equipment are available for all of our rooms, supported by convenient in-house technical assistance.\", \"vi\": \"Tất cả các phòng của chúng tôi đều được trang bị máy chiếu, loa và các thiết bị đa phương tiện hiện đại nhất, cùng với sự hỗ trợ kỹ thuật nội bộ thuận tiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In addition, The Egmont\'s catering service can make delicious, custom fare for a variety of situations, from light refreshments to multiple-course dinners.\", \"vi\": \"Bên cạnh đó, dịch vụ ẩm thực của The Egmont có thể chế biến những món ăn ngon miệng, được thiết kế riêng cho nhiều dịp khác nhau, từ những món ăn nhẹ đến bữa tối nhiều món.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"First-time clients who reserve rooms for certain days and times are eligible for a 10% discount.\", \"vi\": \"Khách hàng lần đầu tiên đặt phòng vào những ngày và khung giờ nhất định sẽ được hưởng mức giảm giá 10%.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Visit www.theegmont.co.nz for details.\", \"vi\": \"Vui lòng truy cập www.theegmont.co.nz để biết thêm chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To: Aaron Jones\", \"vi\": \"Gửi: Aaron Jones\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"From: Ruth Henare\", \"vi\": \"Từ: Ruth Henare\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Date: 12 October\", \"vi\": \"Ngày: 12 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Subject: Awards dinner venue\", \"vi\": \"Chủ đề: Địa điểm tổ chức tiệc trao giải\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Hi Aaron,\", \"vi\": \"Xin chào Aaron,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"This morning I called The Egmont about hosting our annual awards dinner.\", \"vi\": \"Sáng nay, tôi đã gọi điện cho The Egmont để thảo luận về việc tổ chức buổi tiệc trao giải thường niên của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"They do have the space and catering capacity to accommodate our entire guest list, which has grown beyond 200 people.\", \"vi\": \"Họ thực sự có đủ không gian và năng lực phục vụ ẩm thực để đáp ứng nhu cầu của toàn bộ danh sách khách mời của chúng tôi, vốn đã tăng lên hơn 200 người.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"However, the room we\'d need is already booked for every Saturday evening in November, so 11 November is no longer an option.\", \"vi\": \"Tuy nhiên, phòng mà chúng ta cần đã được đặt trước cho tất cả các tối thứ Bảy trong tháng 11, do đó ngày 11 tháng 11 không còn là lựa chọn nữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"That Sunday, 12 November, is open, though, as is Friday, 17 November.\", \"vi\": \"Tuy nhiên, Chủ nhật ngày 12 tháng 11 vẫn còn chỗ trống, cũng như thứ Sáu ngày 17 tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Also, Thursday, 16 November is available at a discounted rate.\", \"vi\": \"Ngoài ra, ngày thứ Năm, 16 tháng 11 cũng có mức giá ưu đãi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I think we should take it.\", \"vi\": \"Tôi nghĩ chúng ta nên nhận lấy nó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Our attendees will understand the date change if we explain that our original venue shut down unexpectedly.\", \"vi\": \"Nếu chúng tôi giải thích rằng địa điểm tổ chức ban đầu đã phải đóng cửa đột ngột, quý vị tham dự sẽ hiểu lý do thay đổi ngày tổ chức.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I hope you\'ll let me know your decision soon, as all of these dates are approaching quickly and there are many preparations still to be made.\", \"vi\": \"Tôi hy vọng quý vị sẽ sớm thông báo cho tôi biết quyết định của mình, vì tất cả các mốc thời gian này đang đến rất gần và vẫn còn nhiều việc cần chuẩn bị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Ruth\", \"vi\": \"Ruth\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"To: Ruth Henare\", \"vi\": \"Kính gửi: Ruth Henare\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"From: Aaron Jones\", \"vi\": \"Từ: Aaron Jones\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Date: 12 October\", \"vi\": \"Ngày: 12 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Subject: Awards dinner venue\", \"vi\": \"Chủ đề: Địa điểm tổ chức tiệc trao giải\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Hi Ruth,\", \"vi\": \"Xin chào Ruth,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I agree with you that The Egmont is a good choice.\", \"vi\": \"Tôi đồng ý với quý vị rằng The Egmont là một lựa chọn tốt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"With our budget in mind, I\'ve decided that I\'d like you to make the reservation for the discounted date.\", \"vi\": \"Xét đến ngân sách của chúng ta, tôi đã quyết định rằng tôi mong quý vị tiến hành đặt chỗ vào ngày được giảm giá.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Xin cảm ơn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Aaron Jones\", \"vi\": \"Aaron Jones\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"President, Wellington Commerce Council\", \"vi\": \"Chủ tịch Hội đồng Thương mại Wellington\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '328922de-bfa6-4ec5-9787-691dc48ef023';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"GREENWAY (December 15)—The country\'s employment rose by over 40,000 jobs during October and November, ______[139] government statistics just released.\", \"vi\": \"GREENWAY (Ngày 15 tháng 12)—Việc làm của đất nước đã tăng hơn 40.000 việc làm trong tháng 10 và tháng 11, ______[139] theo số liệu thống kê của chính phủ vừa được công bố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [139]}, {\"en\": \"The biggest increase was in the retail sector, with 9,000 new jobs created.\", \"vi\": \"Mức tăng lớn nhất là ở lĩnh vực bán lẻ, với 9.000 việc làm mới được tạo ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The service sector came in ______[140] in overall activity with 8,400 added jobs.\", \"vi\": \"Lĩnh vực dịch vụ đứng ______[140] về tổng thể hoạt động với 8.400 việc làm được bổ sung.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [140]}, {\"en\": \"Professional and business services gained jobs as well.\", \"vi\": \"Các dịch vụ chuyên nghiệp và kinh doanh cũng có thêm việc làm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Health services and education each saw strong gains with 4,200 jobs.\", \"vi\": \"Dịch vụ y tế và giáo dục đều ghi nhận mức tăng mạnh với 4.200 việc làm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[141].\", \"vi\": \"______[141].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [141]}, {\"en\": \"By company size, medium-sized businesses of 50 to 499 employees hired the most workers.\", \"vi\": \"Xét theo quy mô công ty, các doanh nghiệp vừa với từ 50 đến 499 nhân viên đã tuyển dụng nhiều lao động nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Large businesses of 500 or more employees hired 12,000 workers.\", \"vi\": \"Các doanh nghiệp lớn từ 500 nhân viên trở lên đã tuyển dụng 12.000 lao động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"The job market remains robust, and we ______[142] it to continue,\\\" said economist Keisha Hou.\", \"vi\": \"\\\"Thị trường việc làm vẫn mạnh mẽ và chúng tôi ______[142] nó sẽ tiếp tục duy trì,\\\" nhà kinh tế học Keisha Hou cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [142]}]' WHERE `id` = '32e12cf6-0e3a-431c-9719-1d6872621b2a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MEMO\", \"vi\": \"BẢN GHI NHỚ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All Staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Donaldo Mata, Facilities Supervisor\", \"vi\": \"Từ: Donaldo Mata, Trưởng bộ phận Quản lý Cơ sở vật chất\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: July 22\", \"vi\": \"Ngày: 22 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Drilling process\", \"vi\": \"Chủ đề: Quy trình khoan\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As I reported at last week\'s staff meeting, we are now in the final planning stages for the new addition to our headquarters building.\", \"vi\": \"Như tôi đã báo cáo tại cuộc họp nhân viên tuần trước, hiện tại chúng ta đang ở giai đoạn lập kế hoạch cuối cùng cho phần mở rộng mới của tòa nhà trụ sở chính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As part of the process, contractors will be drilling holes tomorrow in the north, east, and west sides of the building to do structural analysis.\", \"vi\": \"Trong khuôn khổ quá trình này, các nhà thầu sẽ tiến hành khoan các lỗ vào ngày mai tại các mặt phía bắc, phía đông và phía tây của tòa nhà nhằm thực hiện phân tích kết cấu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The drilling is expected to take several hours, and the work will be very noisy.\", \"vi\": \"Quá trình khoan dự kiến sẽ kéo dài vài giờ, và công việc này sẽ gây ra tiếng ồn rất lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I realize that this type of noise can be very distracting to employees who are trying to speak with customers or conduct meetings.\", \"vi\": \"Tôi nhận thấy rằng loại tiếng ồn này có thể gây xao nhãng rất nhiều cho các nhân viên đang cố gắng trao đổi với khách hàng hoặc tiến hành các cuộc họp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I have requested that the contractors begin drilling on the east side, closest to the Customer Service Office, so that drilling can be finished before peak service hours.\", \"vi\": \"Tôi đã yêu cầu các nhà thầu bắt đầu khoan ở phía đông, gần Văn phòng Dịch vụ Khách hàng nhất, để công việc khoan có thể hoàn tất trước giờ cao điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please keep windows on all sides of the building shut to minimize the noise and prevent any exhaust fumes from the drilling rig from entering the building.\", \"vi\": \"Kính mong quý vị đóng chặt các cửa sổ ở tất cả các mặt của tòa nhà để giảm thiểu tiếng ồn và ngăn không cho khí thải từ giàn khoan xâm nhập vào tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I will be here all day supervising the process and will be available to answer any questions.\", \"vi\": \"Tôi sẽ có mặt tại đây suốt cả ngày để giám sát quá trình này và sẵn sàng giải đáp mọi thắc mắc của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I sincerely apologize for the inconvenience.\", \"vi\": \"Tôi xin chân thành xin lỗi vì sự bất tiện này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '32e45a10-167b-4950-9511-ffa0ce4fbdcf';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Creative Tech Conference\", \"vi\": \"Hội nghị Công nghệ Sáng tạo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Join us for the Tenth Annual Creative Tech Conference.\", \"vi\": \"Kính mời quý vị tham dự Hội nghị Công nghệ Sáng tạo Thường niên lần thứ mười.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Explore the latest technologies with the top innovators in their fields.\", \"vi\": \"Hãy cùng khám phá những công nghệ mới nhất cùng các nhà đổi mới hàng đầu trong lĩnh vực của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Enjoy a full day of presentations, workshops, discussions, and exhibitions, culminating with a keynote address by Ayana Gonzalez, the founder of Grutenhur Tech.\", \"vi\": \"Hãy cùng tham gia một ngày trọn vẹn với các bài thuyết trình, hội thảo, buổi thảo luận và triển lãm, với điểm nhấn là bài phát biểu chính của bà Ayana Gonzalez, người sáng lập Grutenhur Tech.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"May 12, 9 A.M.–6 P.M.\", \"vi\": \"Ngày 12 tháng 5, từ 9 giờ sáng đến 6 giờ chiều\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Bondal University\", \"vi\": \"Đại học Bondal\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"22 Markus Street\", \"vi\": \"Số 22 đường Markus\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Ione, California\", \"vi\": \"Ione, California\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Purchase tickets online at www.creativetechcon.com/tickets.\", \"vi\": \"Quý vị có thể mua vé trực tuyến tại địa chỉ www.creativetechcon.com/tickets.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Interested in being a sponsor?\", \"vi\": \"Quý vị có quan tâm đến việc trở thành nhà tài trợ không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"See the attached sponsor benefits brochure.\", \"vi\": \"Kính mời quý vị tham khảo tài liệu giới thiệu các quyền lợi dành cho nhà tài trợ đính kèm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Creative Tech Conference\\nSponsor Benefits\", \"vi\": \"Hội nghị Công nghệ Sáng tạo\\nCác lợi ích dành cho nhà tài trợ\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We couldn\'t run the Creative Tech Conference without the help of sponsors.\", \"vi\": \"Chúng tôi không thể tổ chức Hội nghị Công nghệ Sáng tạo nếu không có sự hỗ trợ từ các nhà tài trợ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"In addition to supporting entrepreneurs and innovators, sponsorship is a great way to get the name of your business out to our 500+ attendees in various tech fields.\", \"vi\": \"Bên cạnh việc hỗ trợ các doanh nhân và nhà đổi mới, hoạt động tài trợ còn là một cách tuyệt vời để quảng bá thương hiệu doanh nghiệp của quý vị đến hơn 500 khách tham dự thuộc nhiều lĩnh vực công nghệ khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"See below for sponsorship levels.\", \"vi\": \"Xin vui lòng tham khảo các mức tài trợ dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Innovator—$5,000\", \"vi\": \"Giải thưởng “Nhà sáng tạo” — 5.000 đô la\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Your company\'s logo on a large banner displayed during the keynote address\", \"vi\": \"Logo của công ty quý vị trên một tấm băng rôn lớn được trưng bày trong suốt bài phát biểu chính\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Free four-hour exhibitor booth\", \"vi\": \"Gian hàng triển lãm miễn phí trong bốn giờ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Your company\'s logo featured on our Web site and conference program\", \"vi\": \"Logo của quý công ty sẽ được đăng tải trên trang web và chương trình hội nghị của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Half-price tickets for all employees that attend the conference\", \"vi\": \"Vé giảm giá một nửa dành cho tất cả các nhân viên tham dự hội nghị\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Creator—$3,000\", \"vi\": \"Người sáng tạo — 3.000 USD\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Your company\'s logo on a large banner displayed during the final reception\", \"vi\": \"Logo của quý công ty trên một tấm băng rôn lớn được trưng bày trong buổi tiệc chiêu đãi bế mạc\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Free four-hour exhibitor booth\", \"vi\": \"Gian hàng triển lãm miễn phí trong bốn giờ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Your company\'s logo featured on our Web site and conference program\", \"vi\": \"Logo của quý công ty sẽ được giới thiệu trên trang web và chương trình hội nghị của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Entrepreneur—$2,000\", \"vi\": \"Doanh nhân — 2.000 đô la\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Your company\'s logo featured on our Web site and conference program\", \"vi\": \"Logo của quý công ty sẽ được đăng tải trên trang web và chương trình hội nghị của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Free four-hour exhibitor booth\", \"vi\": \"Gian hàng triển lãm miễn phí trong bốn giờ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Patron—$1,000\", \"vi\": \"Nhà tài trợ — 1.000 đô la\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Your company\'s logo featured on our Web site and conference program\", \"vi\": \"Logo của quý công ty sẽ được giới thiệu trên trang web và chương trình hội nghị của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Please contact sponsors@creativetechconference.com for more information.\", \"vi\": \"Vui lòng liên hệ với sponsors@creativetechconference.com để biết thêm thông tin.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"To: All Orlavel Analytics Staff\", \"vi\": \"Kính gửi: Toàn thể nhân viên bộ phận Phân tích dữ liệu của Orlavel\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"From: Edsel Skyers\", \"vi\": \"Từ: Edsel Skyers\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Subject: Creative Tech Conference\", \"vi\": \"Chủ đề: Hội nghị Công nghệ Sáng tạo\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Date: May 2\", \"vi\": \"Ngày: 2 tháng 5\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Dear Staff,\", \"vi\": \"Kính gửi quý đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"I hope you will attend the Creative Tech Conference on May 12.\", \"vi\": \"Tôi hy vọng quý vị sẽ tham dự Hội nghị Công nghệ Sáng tạo vào ngày 12 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"It is taking place nearby at Bondal University.\", \"vi\": \"Sự kiện này đang diễn ra tại Đại học Bondal, ngay gần đây.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"I have gone the past two years, and it is a great way to network and stay informed about the newest trends in our field.\", \"vi\": \"Tôi đã tham dự sự kiện này trong hai năm qua, và đây là một cách tuyệt vời để mở rộng mạng lưới quan hệ cũng như cập nhật những xu hướng mới nhất trong lĩnh vực của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"And because we are a sponsor of the event, our employees receive a discount on tickets.\", \"vi\": \"Và bởi vì chúng tôi là nhà tài trợ của sự kiện này, nên nhân viên của chúng tôi được hưởng mức giảm giá khi mua vé.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Plus, as some of you may know, the keynote speaker is a former employee!\", \"vi\": \"Hơn nữa, như một số quý vị có thể đã biết, diễn giả chính là một cựu nhân viên của công ty!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Let me know if you have any questions.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Edsel Skyers\", \"vi\": \"Edsel Skyers\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Product Development Director\", \"vi\": \"Giám đốc Phát triển Sản phẩm\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Orlavel Analytics\", \"vi\": \"Orlavel Analytics\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}]' WHERE `id` = '330bcb74-149a-481b-bbaf-94c250332696';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"TERMINAL C TO REOPEN\", \"vi\": \"NHÀ GA C SẼ MỞ CỬA TRỞ LẠI\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"(May 23) Harrison City Airport\'s Terminal C will reopen to the public on June 1 following a two-year renovation project.\", \"vi\": \"(Ngày 23 tháng 5) Nhà ga C của Sân bay Harrison City sẽ mở cửa trở lại cho công chúng vào ngày 1 tháng 6, sau hai năm thực hiện dự án cải tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The project added eleven new gates, allowing the terminal to accommodate more flights.\", \"vi\": \"Dự án này đã bổ sung thêm mười một cổng mới, giúp nhà ga có thể phục vụ nhiều chuyến bay hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The three major airlines that used Terminal C before the renovation will now be back in operation there.\", \"vi\": \"Ba hãng hàng không lớn từng sử dụng Nhà ga C trước khi cải tạo nay sẽ tiếp tục hoạt động tại đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Also at Terminal C will be newcomer Paik Airways, a regional carrier that is expanding its routes.\", \"vi\": \"Cũng tại Nhà ga C sẽ có sự xuất hiện của hãng hàng không mới Paik Airways, một hãng hàng không khu vực đang mở rộng mạng lưới đường bay của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The terminal\'s new lobby features an efficient check-in process and a state-of-the-art baggage-handling system.\", \"vi\": \"Sảnh mới của nhà ga được trang bị quy trình làm thủ tục lên máy bay hiệu quả cùng hệ thống xử lý hành lý hiện đại nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Passengers will enjoy free Wi-Fi in the waiting area, which also contains shops and restaurants.\", \"vi\": \"Hành khách sẽ được sử dụng Wi-Fi miễn phí tại khu vực chờ, nơi cũng có các cửa hàng và nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"At one point during the renovations, it looked as if the construction team would miss its deadline.\", \"vi\": \"Có một thời điểm trong quá trình cải tạo, dường như đội thi công sẽ không kịp hoàn thành đúng thời hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"An environmental impact review conducted by the city questioned the placement of a parking lot.\", \"vi\": \"Một cuộc đánh giá tác động môi trường do thành phố tiến hành đã đặt ra nghi vấn về vị trí xây dựng bãi đỗ xe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The planners solved the problem by moving the parking lot to the other side of the airport and instituting a shuttle bus service.\", \"vi\": \"Các nhà quy hoạch đã giải quyết vấn đề này bằng cách di dời bãi đỗ xe sang phía bên kia sân bay và triển khai dịch vụ xe buýt đưa đón.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"\\\"Thanks to the cooperative efforts of all stakeholders, the project was completed by the deadline with no budget overage,\\\" said Arturo Benetti, the airport\'s chief operating officer.\", \"vi\": \"\\\"Nhờ sự hợp tác chặt chẽ của tất cả các bên liên quan, dự án đã được hoàn thành đúng hạn mà không vượt quá ngân sách,\\\" ông Arturo Benetti, Giám đốc điều hành sân bay, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"\\\"The improvements to Terminal C will enable us to continue providing Harrison City with safe, comfortable air travel.\\\"\", \"vi\": \"\\\"Những cải tiến tại Nhà ga C sẽ giúp chúng tôi tiếp tục mang đến cho thành phố Harrison những chuyến bay an toàn và thoải mái.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From: Thomasina Yee <thomasina.yee@cooverbrothers.com>\", \"vi\": \"Từ: Thomasina Yee <thomasina.yee@cooverbrothers.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To: Sven Paulsen <sven.paulsen@cooverbrothers.com>\", \"vi\": \"Gửi tới: Sven Paulsen <sven.paulsen@cooverbrothers.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date: July 6\", \"vi\": \"Ngày: 6 tháng 7\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Subject: Meeting with Slonim Company buyers\", \"vi\": \"Chủ đề: Cuộc họp với các khách hàng của Công ty Slonim\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Hello, Sven,\", \"vi\": \"Xin chào, Sven,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I\'m at the Harrison City Airport to catch the 3:30 flight home, but I want to give you a quick update.\", \"vi\": \"Hiện tôi đang có mặt tại Sân bay Harrison City để đón chuyến bay lúc 3 giờ 30 về nhà, nhưng tôi muốn gửi đến quý vị một vài thông tin cập nhật ngắn gọn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The meeting at Slonim went well.\", \"vi\": \"Cuộc họp tại Slonim đã diễn ra tốt đẹp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"They are very pleased with Coover Brothers products and expect to double their orders next year.\", \"vi\": \"Quý vị rất hài lòng với các sản phẩm của Coover Brothers và dự kiến sẽ tăng gấp đôi khối lượng đặt hàng vào năm tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"In fact, they offered to feature our bedroom and dining room sets at the upcoming Home and Garden Exposition.\", \"vi\": \"Thực tế, họ đã đề nghị trưng bày các bộ sản phẩm phòng ngủ và phòng ăn của chúng tôi tại Triển lãm Nhà và Vườn sắp tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I\'ll give you all the details tomorrow.\", \"vi\": \"Ngày mai tôi sẽ cung cấp cho quý vị tất cả các chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Thomasina\", \"vi\": \"Thomasina\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Airline - Flight - Gate - Time - Destination - Status\", \"vi\": \"Hãng hàng không - Chuyến bay - Cổng lên máy bay - Thời gian - Điểm đến - Tình trạng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Brightway - BR417 - 11 - 1:25 - Detroit - ON TIME\", \"vi\": \"Brightway - BR417 - 11 - 1:25 - Detroit - ĐÚNG GIỜ\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Planet Z - PL700 - 3 - 2:06 - Omaha - CANCELED\", \"vi\": \"Planet Z - PL700 - 3 - 2:06 - Omaha - ĐÃ BỊ HỦY BỎ\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Paik - PA069 - 24 - 3:00 - Cleveland - ON TIME\", \"vi\": \"Chuyến bay - PA069 - 24 - 3:00 - Cleveland - ĐÚNG GIỜ\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Windrover - WI645 - 6 - 3:30 - Chicago - DELAYED\", \"vi\": \"Windrover - WI645 - 6 - 3:30 - Chicago - BỊ TRỄ\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"HARRISON CITY AIRPORT–TERMINAL C\", \"vi\": \"SÂN BAY THÀNH PHỐ HARRISON – NHÀ GA C\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"DEPARTURES\", \"vi\": \"CHUYẾN ĐI\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = '334f9986-c03f-41b6-ad28-8b21ea1d9eb6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Alex Gulin <alex.gulin@senmail.ca>\", \"vi\": \"Gửi: Alex Gulin <alex.gulin@senmail.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Kohek Apparel <orders@kohekapparel.com>\", \"vi\": \"Từ: Kohek Apparel <orders@kohekapparel.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: August 27\", \"vi\": \"Ngày: 27 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Kohek Apparel order confirmation\", \"vi\": \"Chủ đề: Xác nhận đơn hàng của Kohek Apparel\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Description - Item Number - Color - Size - Price\", \"vi\": \"Mô tả - Mã sản phẩm - Màu sắc - Kích thước - Giá\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Jogging suit - P394 - Charcoal gray - Large - $78.00\", \"vi\": \"Bộ đồ chạy bộ - P394 - Màu xám than - Cỡ L - 78,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Cotton shirt - S963 - Bright white - Large - $36.00\", \"vi\": \"Áo sơ mi cotton - S963 - Màu trắng sáng - Cỡ L - 36,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Wool sweater - SW852 - Sky blue - Large - $45.00\", \"vi\": \"Áo len - SW852 - Màu xanh da trời - Cỡ L - 45,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Fleece jacket - J109 - Moss green - Large - $65.00\", \"vi\": \"Áo khoác nỉ - J109 - Màu xanh rêu - Cỡ L - 65,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Total $224.00\", \"vi\": \"Tổng cộng: 224,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Dear Alex:\", \"vi\": \"Kính gửi Alex:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Thank you for your online order from Kohek Apparel!\", \"vi\": \"Xin chân thành cảm ơn quý khách đã đặt hàng trực tuyến tại Kohek Apparel!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Your order should arrive within 5–10 business days.\", \"vi\": \"Đơn hàng của quý khách dự kiến sẽ được giao trong vòng 5–10 ngày làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"See below for details:\", \"vi\": \"Xin vui lòng xem chi tiết dưới đây:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Order Number: 96781\", \"vi\": \"Số đơn hàng: 96781\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Deliver To: 22 Exeter Street, Toronto, M4B 1B3 CANADA\", \"vi\": \"Gửi đến: 22 Exeter Street, Toronto, M4B 1B3 CANADA\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Order Summary:\", \"vi\": \"Tóm tắt đơn hàng:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We appreciate your repeated business!\", \"vi\": \"Chúng tôi xin chân thành cảm ơn quý khách đã luôn tin tưởng và ủng hộ chúng tôi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To receive a coupon for 10 percent off your next order, visit our website and enter the promotional code RC008.\", \"vi\": \"Để nhận phiếu giảm giá 10% cho đơn hàng tiếp theo của quý khách, vui lòng truy cập trang web của chúng tôi và nhập mã khuyến mãi RC008.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Kohek Apparel—Return Policy\", \"vi\": \"Kohek Apparel — Chính sách đổi trả\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"http://www.kohekapparel.com/returns\", \"vi\": \"http://www.kohekapparel.com/returns\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Kohek Apparel strives to create high-quality, great-fitting items at a reasonable price.\", \"vi\": \"Kohek Apparel luôn nỗ lực tạo ra những sản phẩm chất lượng cao, vừa vặn hoàn hảo với mức giá hợp lý.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"We want you to be completely satisfied with your order and would like to make the return process as easy as possible.\", \"vi\": \"Chúng tôi mong muốn quý khách hoàn toàn hài lòng với đơn hàng của mình và mong muốn quy trình đổi trả diễn ra một cách thuận tiện nhất có thể.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"To return an item, request a shipping label by emailing customersupport@kohekapparel.com.\", \"vi\": \"Để trả lại hàng, quý khách vui lòng gửi email đến địa chỉ customersupport@kohekapparel.com để yêu cầu tem vận chuyển.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"A printable shipping label will be emailed to you.\", \"vi\": \"Một nhãn vận chuyển có thể in được sẽ được gửi qua email cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Once you receive it, place the item in the same box it arrived in, along with a completed return request form (found on the back of your invoice), and tape the shipping label to the box.\", \"vi\": \"Khi nhận được hàng, xin vui lòng đặt sản phẩm vào chính chiếc hộp mà quý khách đã nhận được, kèm theo phiếu yêu cầu trả hàng đã điền đầy đủ thông tin (nằm ở mặt sau hóa đơn của quý khách), và dán nhãn vận chuyển lên hộp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"If you no longer have the original box, place the item in a different box.\", \"vi\": \"Nếu quý vị không còn giữ hộp đựng ban đầu, xin vui lòng đặt mặt hàng vào một chiếc hộp khác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Your purchase will be fully refunded once we receive the package.\", \"vi\": \"Chúng tôi sẽ hoàn lại toàn bộ số tiền quý khách đã thanh toán ngay sau khi nhận được gói hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Returns within the United States are completely free.\", \"vi\": \"Việc trả hàng trong phạm vi Hoa Kỳ hoàn toàn miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"For returns from Canada, a $6 shipping charge will be deducted from your refund.\", \"vi\": \"Đối với các đơn hàng trả lại từ Canada, khoản phí vận chuyển 6 đô la sẽ được khấu trừ từ số tiền hoàn lại của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"From all other countries, the shipping charge is $12.\", \"vi\": \"Đối với tất cả các quốc gia khác, phí vận chuyển là 12 đô la.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Kohek Apparel—Return Request\", \"vi\": \"Kohek Apparel — Yêu cầu đổi trả\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Name: Alex Gulin\", \"vi\": \"Họ tên: Alex Gulin\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Customer ID: A.Gul370\", \"vi\": \"Mã khách hàng: A.Gul370\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Order Number: 96781\", \"vi\": \"Số đơn hàng: 96781\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Returning Item Number: J109\", \"vi\": \"Mã sản phẩm trả lại: J109\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Reason for the return: Item was too large.\", \"vi\": \"Lý do trả hàng: Sản phẩm quá cồng kềnh.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Order a different size?\", \"vi\": \"Quý vị có muốn đặt hàng với kích cỡ khác không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"No Size ____\", \"vi\": \"Không có kích cỡ ____\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Comments:\", \"vi\": \"Bình luận:\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"I\'ve been ordering the same size from Kohek Apparel for years.\", \"vi\": \"Đã nhiều năm nay, tôi vẫn luôn đặt mua cùng một cỡ quần áo tại Kohek Apparel.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"I was surprised that this time the sizing was off.\", \"vi\": \"Tôi đã rất ngạc nhiên khi lần này kích cỡ lại không chuẩn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"But I\'m happy with my other items.\", \"vi\": \"Tuy nhiên, tôi rất hài lòng với những món đồ còn lại của mình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}]' WHERE `id` = '3352c270-7b5c-44b4-ac6f-3ead86839366';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Fausto Forletti [11:02 A.M.]\", \"vi\": \"Từ: Fausto Forletti [11:02 sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Steffan Griffiths <029 2018 0743>\", \"vi\": \"Gửi tới: Steffan Griffiths <029 2018 0743>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Hi, Steffan.\", \"vi\": \"Xin chào, Steffan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I\'m with the electrical contractors at the former Millway train station site now.\", \"vi\": \"Hiện tại, tôi đang làm việc cùng các nhà thầu điện tại khu vực từng là ga tàu Millway.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The electrical system was in worse shape than we had originally thought.\", \"vi\": \"Hệ thống điện lại ở trong tình trạng tồi tệ hơn so với những gì chúng tôi đã nghĩ ban đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The rewiring and upgrades are going to cost more than expected because we want to modernise while still retaining the historical integrity of the building.\", \"vi\": \"Việc lắp đặt lại hệ thống dây điện và nâng cấp sẽ tốn kém hơn dự kiến vì chúng tôi muốn hiện đại hóa công trình mà vẫn giữ nguyên giá trị lịch sử của tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I\'ll send over the estimate as soon as I receive it.\", \"vi\": \"Tôi sẽ gửi bản dự toán cho quý vị ngay khi nhận được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I\'m hoping that all the work will be completed so that we can open as planned in May.\", \"vi\": \"Tôi hy vọng rằng tất cả các công việc sẽ được hoàn tất để chúng ta có thể khai trương vào tháng 5 như dự kiến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"New Hotel to Open in South Wales\", \"vi\": \"Khách sạn mới sẽ khai trương tại Nam xứ Wales\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"CARDIFF (18 April)—The Millway Road Hotel is scheduled to open on 14 May.\", \"vi\": \"CARDIFF (ngày 18 tháng 4) — Khách sạn Millway Road dự kiến sẽ khai trương vào ngày 14 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The building was once a busy train station that was designed by Arthur Lewison over 150 years ago.\", \"vi\": \"Tòa nhà này từng là một ga tàu hỏa nhộn nhịp, do Arthur Lewison thiết kế cách đây hơn 150 năm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"For almost three decades the building had been left unoccupied.\", \"vi\": \"Trong gần ba thập kỷ qua, tòa nhà này đã bị bỏ trống.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"It was purchased two years ago by Steffan Griffiths, president of Griffiths Hoteliers.\", \"vi\": \"Cơ sở này đã được ông Steffan Griffiths, Chủ tịch Tập đoàn Griffiths Hoteliers, mua lại cách đây hai năm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"According to project coordinator Fausto Forletti, the old building required extensive renovation not only to turn it into a hotel but also to update the electrical, heating, and plumbing systems.\", \"vi\": \"Theo ông Fausto Forletti, điều phối viên dự án, tòa nhà cũ cần phải được cải tạo quy mô lớn, không chỉ để biến nó thành một khách sạn mà còn nhằm nâng cấp các hệ thống điện, sưởi ấm và cấp thoát nước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The hotel has 25 guest rooms, a meeting room, and a restaurant with banquet facilities.\", \"vi\": \"Khách sạn có 25 phòng nghỉ, một phòng họp và một nhà hàng có cơ sở vật chất phục vụ tiệc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"All of Mr. Griffiths\' facilities are noted for their world-class dining experiences.\", \"vi\": \"Tất cả các cơ sở của ông Griffiths đều nổi tiếng với những trải nghiệm ẩm thực đẳng cấp thế giới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The hotel\'s Bayside Café has award-winning Welsh chef Mal Davies to create a menu and oversee the restaurant.\", \"vi\": \"Quán cà phê Bayside Café của khách sạn có sự góp mặt của đầu bếp người xứ Wales từng đoạt giải thưởng, ông Mal Davies, người sẽ phụ trách xây dựng thực đơn và điều hành nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"In the near future, Mr. Griffiths plans to expand the property\'s garden.\", \"vi\": \"Trong tương lai gần, ông Griffiths có kế hoạch mở rộng khu vườn của khu bất động sản này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"For information and reservations, visit www.millwayroadhotel.co.uk.\", \"vi\": \"Để biết thêm thông tin và đặt chỗ, vui lòng truy cập trang web www.millwayroadhotel.co.uk.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"http://www.cardifftravels.co.uk/reviews\", \"vi\": \"http://www.cardifftravels.co.uk/reviews\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"★★★★\", \"vi\": \"★★★★\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Millway Road Hotel\", \"vi\": \"Khách sạn Millway Road\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Review posted by Mi-Yeon Ko\", \"vi\": \"Bài đánh giá do Mi-Yeon Ko đăng tải\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I recently attended a small conference at the Millway Road Hotel, which opened in June.\", \"vi\": \"Gần đây, tôi đã tham dự một hội nghị quy mô nhỏ tại Khách sạn Millway Road, nơi vừa khai trương vào tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"As a computer technician, I was pleasantly surprised to find that it had such up-to-date facilities.\", \"vi\": \"Với tư cách là một kỹ thuật viên máy tính, tôi đã vô cùng ngạc nhiên khi thấy nơi đây được trang bị những thiết bị hiện đại đến vậy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Both my room and the meeting room had more than enough electrical outlets to plug in equipment and charge mobile phones and computers.\", \"vi\": \"Cả phòng của tôi lẫn phòng họp đều có số lượng ổ cắm điện dồi dào, đủ để cắm các thiết bị cũng như sạc điện thoại di động và máy tính.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"The complimentary wireless Internet service was easy to access.\", \"vi\": \"Dịch vụ Internet không dây miễn phí rất dễ sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"On top of that, the food was delicious and the guest rooms were beautiful.\", \"vi\": \"Hơn nữa, đồ ăn rất ngon và các phòng nghỉ cũng rất đẹp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Attractions\", \"vi\": \"Các điểm tham quan\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Reviews\", \"vi\": \"Các đánh giá\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}]' WHERE `id` = '3360d2d2-41b8-4cdc-98df-87d368fdfa2b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Slide Ace <contact@slideace.com>\", \"vi\": \"Từ: Slide Ace <contact@slideace.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To: Roy Thornton <roy.thornton@gannitt.com>\", \"vi\": \"Gửi: Roy Thornton <roy.thornton@gannitt.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Opportunity\", \"vi\": \"Chủ đề: Cơ hội\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Date: July 10\", \"vi\": \"Ngày: 10 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Thornton,\", \"vi\": \"Kính gửi ông Thornton,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As valued users of Slide Ace 2.2, you and your staff are invited to participate in beta testing of Slide Ace 2.3.\", \"vi\": \"Với tư cách là những người dùng quý báu của Slide Ace 2.2, quý vị và các nhân viên của quý vị được mời tham gia thử nghiệm phiên bản beta của Slide Ace 2.3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This new version of Slide Ace, which we hope to release widely by the end of year, features ReadyGo, a library of sophisticated slide templates created by design professionals.\", \"vi\": \"Phiên bản mới này của Slide Ace, mà chúng tôi hy vọng sẽ phát hành rộng rãi vào cuối năm nay, tích hợp tính năng ReadyGo – một thư viện các mẫu slide tinh tế do các chuyên gia thiết kế tạo ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Other major changes include dashboard reporting of helpful statistics on your team\'s use of stored slides and a brand management tool that enables easy updating of your logo and preferred color schemes and fonts across all of your presentations.\", \"vi\": \"Các thay đổi quan trọng khác bao gồm tính năng báo cáo trên bảng điều khiển với các số liệu thống kê hữu ích về việc đội ngũ của quý vị sử dụng các slide đã lưu, cùng với công cụ quản lý thương hiệu cho phép cập nhật dễ dàng logo, bảng màu và phông chữ ưa thích trên tất cả các bản trình bày của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Slide Ace 2.3 can be downloaded here.\", \"vi\": \"Quý vị có thể tải xuống Slide Ace 2.3 tại đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We hope you will agree to be part of this exciting step forward for the platform.\", \"vi\": \"Chúng tôi hy vọng quý vị sẽ đồng ý tham gia vào bước tiến đầy hứa hẹn này của nền tảng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Slide Ace\", \"vi\": \"Slide Ace\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"User: Roy Thornton\", \"vi\": \"Người dùng: Roy Thornton\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"This is the final page of the survey.\", \"vi\": \"Đây là trang cuối cùng của bản khảo sát.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Please add any comments here that could help explain your answers to previous questions.\", \"vi\": \"Xin vui lòng ghi thêm bất kỳ nhận xét nào tại đây để giúp giải thích rõ hơn cho các câu trả lời của quý vị đối với các câu hỏi trước đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I gave the dashboard a \\\"2\\\" because it feels too cluttered.\", \"vi\": \"Tôi đã chấm bảng điều khiển điểm “2” vì nó trông có vẻ quá lộn xộn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Perhaps you could make it possible to customize the types of data that are shown on the dashboard.\", \"vi\": \"Có lẽ quý vị có thể cho phép tùy chỉnh các loại dữ liệu được hiển thị trên bảng điều khiển.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The new brand management tool is a great idea that will be really helpful for our company as a quickly-evolving startup.\", \"vi\": \"Công cụ quản lý thương hiệu mới này là một ý tưởng tuyệt vời, chắc chắn sẽ mang lại nhiều lợi ích cho công ty chúng tôi – một công ty khởi nghiệp đang phát triển nhanh chóng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"The only reason I didn\'t give it a perfect score is that Slide Ace crashed the first time I tried it.\", \"vi\": \"Lý do duy nhất khiến tôi không chấm điểm tối đa cho ứng dụng này là vì Slide Ace đã bị treo ngay lần đầu tiên tôi thử dùng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Thank you for your participation!\", \"vi\": \"Xin chân thành cảm ơn sự tham gia của quý vị!\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"From: Miriam Cassidy <miriam.cassidy@slideace.com>\", \"vi\": \"Từ: Miriam Cassidy <miriam.cassidy@slideace.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"To: Nicole Liu <nicole.liu@slideace.com>\", \"vi\": \"Gửi tới: Nicole Liu <nicole.liu@slideace.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Subject: News\", \"vi\": \"Chủ đề: Tin tức\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Date: August 2\", \"vi\": \"Ngày: 2 tháng 8\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Aug 2 Feedback\", \"vi\": \"Tài liệu đính kèm: 📎 Phản hồi ngày 2 tháng 8\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Hi Nicole,\", \"vi\": \"Xin chào Nicole,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"The latest batch of feedback on Slide Ace 2.3 has confirmed that ReadyGo is a big hit!\", \"vi\": \"Những phản hồi mới nhất về Slide Ace 2.3 đã khẳng định rằng ReadyGo thực sự là một sản phẩm rất được ưa chuộng!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I\'ve attached a breakdown of the numbers to this e-mail.\", \"vi\": \"Tôi đã đính kèm bảng phân tích chi tiết các con số vào email này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Take a look and let me know if you have any questions about the data.\", \"vi\": \"Xin vui lòng xem qua và cho tôi biết nếu quý vị có bất kỳ thắc mắc nào về dữ liệu này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I think it\'s now clear that it would be wise for us to invest further in ReadyGo.\", \"vi\": \"Tôi cho rằng giờ đây đã rõ ràng rằng việc chúng ta tiếp tục đầu tư vào ReadyGo là một quyết định sáng suốt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Specifically, we should make plans to add to it consistently over the long term.\", \"vi\": \"Cụ thể, chúng ta nên lập kế hoạch để liên tục bổ sung vào đó trong dài hạn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Can we meet this week to talk about the staffing that this would require?\", \"vi\": \"Chúng ta có thể gặp nhau trong tuần này để thảo luận về nhu cầu nhân sự liên quan đến vấn đề này không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Miriam\", \"vi\": \"Miriam\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}]' WHERE `id` = '339cedc0-92b4-4529-85b2-699a8904299e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mission Statement\", \"vi\": \"Tuyên bố sứ mệnh\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Hulani Harbor Neighborhood Association (HHNA) is a self-governing organization that strives to promote a safe, vibrant, and enjoyable community for all.\", \"vi\": \"Hiệp hội Khu dân cư Cảng Hulani (HHNA) là một tổ chức tự quản, luôn nỗ lực xây dựng một cộng đồng an toàn, sôi động và đáng sống cho tất cả mọi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Members live in the Hulani Harbor area and are committed to the following goals:\", \"vi\": \"Các thành viên sinh sống tại khu vực Cảng Hulani và cam kết thực hiện các mục tiêu sau đây:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Ensuring that the Hulani Harbor area maintains a range of housing types and price levels\", \"vi\": \"Đảm bảo khu vực Cảng Hulani duy trì sự đa dạng về các loại hình nhà ở và mức giá\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Preserving the architectural character of historic homes\", \"vi\": \"Bảo tồn nét đặc trưng kiến trúc của các ngôi nhà cổ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Planning seasonal gatherings and events for residents\", \"vi\": \"Lên kế hoạch tổ chức các buổi tụ họp và sự kiện theo mùa dành cho cư dân\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Promoting open discussion of local issues and initiatives\", \"vi\": \"Thúc đẩy việc thảo luận cởi mở về các vấn đề và sáng kiến tại địa phương\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"📎\", \"vi\": \"📎\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The Hulani Harbor Neighborhood Association Quarterly Meeting\", \"vi\": \"Cuộc họp định kỳ hàng quý của Hiệp hội Cư dân Khu vực Cảng Hulani\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Scheduled for Thursday, April 20, at 7:00 P.M.\", \"vi\": \"Dự kiến diễn ra vào thứ Năm, ngày 20 tháng 4, lúc 7 giờ tối.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"New topics added to the meeting agenda:\", \"vi\": \"Các nội dung mới được bổ sung vào chương trình nghị sự của cuộc họp:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"• The Chenaux Company seeks rezoning for 3912 Bennett Avenue, a residential structure built in 1909.\", \"vi\": \"• Công ty Chenaux đang đề nghị điều chỉnh quy hoạch đối với địa chỉ 3912 Bennett Avenue, một công trình nhà ở được xây dựng vào năm 1909.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The company is requesting that the property be approved for commercial use, after which the house would be completely remodeled.\", \"vi\": \"Công ty đang đề nghị cấp phép sử dụng bất động sản này cho mục đích thương mại; sau đó, ngôi nhà sẽ được cải tạo hoàn toàn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We invite residents to attend the city council meeting on Monday, April 17, to learn more about the company\'s request and then be prepared to discuss further at the HHNA meeting on Thursday evening.\", \"vi\": \"Chúng tôi kính mời quý cư dân tham dự phiên họp Hội đồng thành phố vào thứ Hai, ngày 17 tháng 4, để tìm hiểu thêm về đề nghị của công ty và từ đó chuẩn bị sẵn sàng để thảo luận sâu hơn tại cuộc họp của HHNA vào tối thứ Năm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"•The leadership committee for the Brazoria Creek sector announces a position opening.\", \"vi\": \"•Ủy ban lãnh đạo khu vực Brazoria Creek xin thông báo về một vị trí tuyển dụng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Duties include serving as point of contact for residents, distributing the monthly newsletter, and sharing information with other leaders of the HHNA.\", \"vi\": \"Các nhiệm vụ bao gồm đóng vai trò là đầu mối liên lạc cho các cư dân, phát hành bản tin hàng tháng và chia sẻ thông tin với các lãnh đạo khác của HHNA.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Individuals who are interested in representing Brazoria Creek will each be asked to speak briefly before a vote will take place.\", \"vi\": \"Mỗi cá nhân quan tâm đến việc đại diện cho Brazoria Creek sẽ được mời phát biểu ngắn gọn trước khi tiến hành bỏ phiếu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The HHNA is pleased to announce that Elena Redman has been selected as the next representative to the HHNA for the Brazoria Creek sector.\", \"vi\": \"HHNA hân hạnh thông báo rằng bà Elena Redman đã được bầu chọn làm đại diện tiếp theo của HHNA cho khu vực Brazoria Creek.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Ms. Redman has held various roles in local public interest organizations.\", \"vi\": \"Bà Redman đã đảm nhiệm nhiều chức vụ khác nhau tại các tổ chức vì lợi ích công cộng ở địa phương.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"She stated, \\\"Although I am retired professionally, the focus of my career has been supporting people and communities through advocacy and education.\", \"vi\": \"Bà cho biết: “Dù tôi đã nghỉ hưu về mặt nghề nghiệp, nhưng trọng tâm trong sự nghiệp của tôi luôn là hỗ trợ mọi người và các cộng đồng thông qua các hoạt động vận động và giáo dục.”\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I look forward to helping the community where I have been living for over 25 years.\\\"\", \"vi\": \"Tôi rất mong được đóng góp cho cộng đồng nơi tôi đã sinh sống trong hơn 25 năm qua.”\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '33f38444-d7e1-44d8-aeef-65ab30d9dd49';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"31 July\", \"vi\": \"Ngày 31 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dr. Shamalie Mowatt\", \"vi\": \"Tiến sĩ Shamalie Mowatt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Cornwall University Hospital\", \"vi\": \"Bệnh viện Đại học Cornwall\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"22-28 Victoria Avenue\", \"vi\": \"22-28 Đại lộ Victoria\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Kingston 6\", \"vi\": \"Kingston 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Dr. Mowatt,\", \"vi\": \"Kính gửi Tiến sĩ Mowatt,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It is a pleasure to recommend Mr. Renaldo Silva for your nursing programme.\", \"vi\": \"Tôi rất hân hạnh được giới thiệu ông Renaldo Silva cho chương trình đào tạo điều dưỡng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Mr. Silva has served as an assistant to our two on-site registered nurses at Summer Camp West, four days a week for the past two summers.\", \"vi\": \"Trong hai mùa hè vừa qua, ông Silva đã đảm nhiệm vai trò trợ lý cho hai điều dưỡng viên có chứng chỉ hành nghề đang làm việc tại Trại hè West, bốn ngày mỗi tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The young campers here have grown quite fond of Mr. Silva.\", \"vi\": \"Các trại viên nhí ở đây đã rất quý mến ông Silva.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"They appreciate his kind but dedicated approach to wellness.\", \"vi\": \"Họ đánh giá cao cách tiếp cận vừa ân cần vừa tận tâm của ông đối với sức khỏe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"He is patient and nurturing, and I am confident that he will succeed in a nursing programme such as yours.\", \"vi\": \"Anh ấy là người kiên nhẫn và biết quan tâm, và tôi tin chắc rằng anh ấy sẽ thành công khi theo học một chương trình đào tạo điều dưỡng như của quý trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"As a nurse myself for more than three decades, I have worked with young professionals in various settings, including large hospitals, small clinics, schools, and, for the past several years, exclusively at Summer Camp West.\", \"vi\": \"Với tư cách là một điều dưỡng viên với hơn ba thập kỷ kinh nghiệm, tôi đã làm việc cùng các chuyên gia trẻ trong nhiều môi trường khác nhau, bao gồm các bệnh viện lớn, phòng khám nhỏ, trường học và, trong vài năm gần đây, chỉ làm việc tại Trại hè West.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I therefore strongly believe that Mr. Silva will be an active and successful programme participant.\", \"vi\": \"Do đó, tôi tin tưởng vững chắc rằng ông Silva sẽ là một học viên tích cực và đạt được nhiều thành công trong chương trình này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"If you have any questions about Mr. Silva, please feel free to call me at (876) 555-0140.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào về ông Silva, xin vui lòng liên hệ với tôi qua số điện thoại (876) 555-0140.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Yours sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Benita Oliveira\", \"vi\": \"Benita Oliveira\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Benita Oliveira\", \"vi\": \"Benita Oliveira\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '34474103-a93e-4f7b-bafd-fd7621a9bd05';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Harbis Stationery Store Clearance Sale\", \"vi\": \"Chương trình thanh lý hàng tồn kho tại Cửa hàng Văn phòng phẩm Harbis\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Prices indicated are for in-store purchases only.\", \"vi\": \"Các mức giá được niêm yết chỉ áp dụng cho các giao dịch mua hàng tại cửa hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"500 Pinstone Street / SHEFFIELD / S12ΗΝ\", \"vi\": \"500 Pinstone Street / SHEFFIELD / S12ΗΝ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Seasonal items\", \"vi\": \"Các mặt hàng theo mùa\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Box of ten preprinted seasonal cards (25% off) £ 8.99\", \"vi\": \"Hộp gồm mười tấm thiệp theo chủ đề mùa lễ đã in sẵn (giảm giá 25%) £ 8,99\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Box of five customizable seasonal cards or invitations (50% off) £ 11.99\", \"vi\": \"Hộp gồm năm tấm thiệp hoặc thiệp mời theo mùa có thể tùy chỉnh (giảm giá 50%) 11,99 bảng Anh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"All school supplies 10% off\", \"vi\": \"Tất cả các mặt hàng đồ dùng học tập được giảm giá 10%\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Box of 24 pens £ 1.79\", \"vi\": \"Hộp gồm 24 cây bút, giá 1,79 bảng Anh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Desk lamp £ 19.99\", \"vi\": \"Đèn bàn 19,99 bảng Anh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Wireless mouse £ 17.99\", \"vi\": \"Chuột không dây 17,99 bảng Anh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Backpack £ 29.99\", \"vi\": \"Ba lô 29,99 bảng Anh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Visit Harbis Stationery at www.harbisstationery.uk\", \"vi\": \"Hãy truy cập trang web của Harbis Stationery tại địa chỉ www.harbisstationery.uk\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '3478755b-7cc8-423b-a6c7-6dcd338ea553';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"www.kateweicommunications.com\", \"vi\": \"www.kateweicommunications.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Marketing your business can be confusing.\", \"vi\": \"Việc tiếp thị doanh nghiệp của bạn có thể gây bối rối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Newspapers and magazines are ______[135] useful venues for advertising.\", \"vi\": \"Báo và tạp chí là những kênh quảng cáo hữu ích ______[135].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"______[136], social media platforms have become even more critical marketing outlets.\", \"vi\": \"______[136], các nền tảng mạng xã hội đã trở thành các kênh tiếp thị thậm chí còn quan trọng hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"Kate Wei Communications utilizes both traditional outlets and the latest communication platforms.\", \"vi\": \"Kate Wei Communications tận dụng cả các kênh truyền thống lẫn các nền tảng truyền thông mới nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[137].\", \"vi\": \"______[137].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [137]}, {\"en\": \"In addition to exceptional print services, Kate Wei Communications has the expertise to help you ______[138] your online presence.\", \"vi\": \"Ngoài các dịch vụ in ấn xuất sắc, Kate Wei Communications có chuyên môn để giúp bạn ______[138] sự hiện diện trực tuyến của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [138]}, {\"en\": \"Why wait?\", \"vi\": \"Còn chần chừ gì nữa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Choose our award-winning firm to strengthen your company\'s image today!\", \"vi\": \"Hãy chọn công ty từng đạt giải thưởng của chúng tôi để củng cố hình ảnh công ty bạn ngay hôm nay!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '347c0766-3c4c-45db-89a2-bac1a34b74fb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Liz Yuen (8:58 A.M.)\", \"vi\": \"Liz Yuen (8 giờ 58 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, all.\", \"vi\": \"Xin chào quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Thank you for your prompt feedback on the Web site content I sent out in the group e-mail.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã nhanh chóng phản hồi về nội dung trang web mà tôi đã gửi trong email chung của nhóm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Everyone agrees that the photos and the accompanying content do not seem to market the calendars strongly enough.\", \"vi\": \"Mọi người đều đồng ý rằng những bức ảnh và nội dung đi kèm dường như chưa quảng bá đủ mạnh mẽ cho các cuốn lịch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Helen Black (8:59 A.M.)\", \"vi\": \"Helen Black (8 giờ 59 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Right.\", \"vi\": \"Đúng vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"But, to confirm that we’re looking at the same material—there are several photos showing our desktop calendar each with the caption “The promise of a new year with a calendar from Stenmex Stationery.”\", \"vi\": \"Tuy nhiên, để xác nhận rằng chúng ta đang xem cùng một tài liệu — có một số bức ảnh chụp lịch để bàn của chúng tôi, mỗi bức đều kèm theo chú thích: “Lời hứa của một năm mới cùng chiếc lịch từ Stenmex Stationery.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Liz Yuen (9:01 A.M.)\", \"vi\": \"Liz Yuen (9 giờ 01 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"That’s correct.\", \"vi\": \"Đúng vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"But the main problem is that the photos and the content that accompanies them need to be more engaging and interactive.\", \"vi\": \"Tuy nhiên, vấn đề chính là các bức ảnh và nội dung đi kèm cần phải hấp dẫn và mang tính tương tác hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Jeff Spina (9:02 A.M.)\", \"vi\": \"Jeff Spina (9 giờ 02 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I agree.\", \"vi\": \"Tôi đồng ý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"What if we ask customers to send us their written comments on how they use our calendars to help them organize their home offices?\", \"vi\": \"Nếu chúng ta đề nghị quý khách gửi cho chúng tôi những ý kiến bằng văn bản về cách họ sử dụng lịch của chúng tôi để giúp họ sắp xếp văn phòng tại nhà thì sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"They could also send us a picture of their home office with our calendar in the image.\", \"vi\": \"Họ cũng có thể gửi cho chúng tôi một bức ảnh về văn phòng tại nhà của họ, trong đó có in lịch của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Helen Black (9:04 A.M.)\", \"vi\": \"Helen Black (9 giờ 04 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I’d be happy to share a photo of my own setup—from one of the days that I’m working from home.\", \"vi\": \"Tôi rất hân hạnh được chia sẻ một bức ảnh về không gian làm việc của riêng mình — được chụp vào một trong những ngày tôi làm việc tại nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"And I could write an explanation of how using the calendar helps me keep track of things.\", \"vi\": \"Và tôi có thể viết một bài giải thích về việc sử dụng lịch giúp tôi theo dõi các công việc như thế nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We could use that as an example for customers to follow.\", \"vi\": \"Chúng ta có thể lấy điều đó làm ví dụ để quý khách hàng tham khảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Liz Yuen (9:05 A.M.)\", \"vi\": \"Liz Yuen (9 giờ 05 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Great idea.\", \"vi\": \"Ý tưởng thật tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"And what about the problems with the functionality of the Web site?\", \"vi\": \"Vậy còn những vấn đề liên quan đến tính năng của trang web thì sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Jeff Spina (9:06 A.M.)\", \"vi\": \"Jeff Spina (9 giờ 06 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"That would be great, Helen.\", \"vi\": \"Như vậy thì thật tuyệt, thưa bà Helen.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Helen Black (9:07 A.M.)\", \"vi\": \"Helen Black (9 giờ 07 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I saw those.\", \"vi\": \"Tôi đã thấy những thứ đó rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Jeff Spina (9:08 A.M.)\", \"vi\": \"Jeff Spina (9 giờ 08 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I’ll speak with Ryeo Jee about that.\", \"vi\": \"Tôi sẽ trao đổi với Ryeo Jee về vấn đề đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Her team should be able to get the pop-up window and social media links working again soon.\", \"vi\": \"Đội ngũ của cô ấy sẽ sớm khắc phục được sự cố để cửa sổ bật lên và các liên kết mạng xã hội hoạt động trở lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Liz Yuen (9:09 A.M.)\", \"vi\": \"Liz Yuen (9 giờ 09 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Thanks, Jeff.\", \"vi\": \"Cảm ơn anh, Jeff.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Once the site is functional and we have our content finalized, her team can update the home page with what we have decided.\", \"vi\": \"Khi trang web đã đi vào hoạt động và chúng ta đã hoàn thiện nội dung, nhóm của cô ấy có thể cập nhật trang chủ theo những gì chúng ta đã thống nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = '34cf4d85-1c7b-498c-8151-eab8278364cc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Manuel Torres <m.torres@opalmail.co.uk>\", \"vi\": \"Gửi: Manuel Torres <m.torres@opalmail.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Anya Patel <a.patel@support.harlund.co.uk>\", \"vi\": \"Từ: Anya Patel <a.patel@support.harlund.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 3 May\", \"vi\": \"Ngày: 3 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Auto insurance\", \"vi\": \"Chủ đề: Bảo hiểm ô tô\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Torres,\", \"vi\": \"Kính gửi ông Torres,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Welcome to Harlund Ltd. We are pleased to provide you with comprehensive automobile insurance for your new vehicle.\", \"vi\": \"Chào mừng quý khách đến với Harlund Ltd. Chúng tôi hân hạnh cung cấp cho quý khách gói bảo hiểm ô tô toàn diện dành cho chiếc xe mới của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We have received your first payment of £36.00, and your coverage is now in effect.\", \"vi\": \"Chúng tôi đã nhận được khoản thanh toán đầu tiên trị giá 36,00 bảng Anh của quý vị, và gói bảo hiểm của quý vị hiện đã có hiệu lực.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Your policy number is M413927.\", \"vi\": \"Số hợp đồng bảo hiểm của quý vị là M413927.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Your billing schedule is based on an annual premium of £432.00.\", \"vi\": \"Lịch thanh toán của quý vị được tính dựa trên mức phí bảo hiểm hàng năm là 432,00 bảng Anh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The remaining payments of £36.00 per month are due on the fifteenth day of each month starting in June.\", \"vi\": \"Các khoản thanh toán còn lại, mỗi tháng 36,00 bảng Anh, phải được thanh toán vào ngày mười lăm của mỗi tháng, bắt đầu từ tháng Sáu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"You can visit us online at www.harlund.co.uk to pay bills and manage your policy.\", \"vi\": \"Quý vị có thể truy cập trang web của chúng tôi tại địa chỉ www.harlund.co.uk để thanh toán hóa đơn và quản lý hợp đồng bảo hiểm của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Our Web site offers easy options for managing your account information and for making payments with scheduled transfers directly from your bank.\", \"vi\": \"Trang web của chúng tôi cung cấp các tùy chọn thuận tiện để quản lý thông tin tài khoản của quý vị cũng như thực hiện thanh toán thông qua các giao dịch chuyển khoản định kỳ trực tiếp từ ngân hàng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Should you have any questions or wish to change your policy, call the customer support centre at 020 7946 0516.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào hoặc muốn thay đổi hợp đồng bảo hiểm của mình, vui lòng gọi đến trung tâm hỗ trợ khách hàng theo số 020 7946 0516.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"In the event of a vehicle incident, please contact an agent as soon as possible at 020 7946 0520.\", \"vi\": \"Trong trường hợp xảy ra sự cố liên quan đến phương tiện, xin vui lòng liên hệ với nhân viên của chúng tôi càng sớm càng tốt theo số 020 7946 0520.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Be sure to have your policy number at hand.\", \"vi\": \"Xin vui lòng chuẩn bị sẵn số hợp đồng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thank you for trusting Harlund Ltd. We look forward to providing you with superior service.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã tin tưởng Harlund Ltd. Chúng tôi rất mong được mang đến cho quý khách những dịch vụ chất lượng cao nhất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Anya Patel, Harlund Ltd. Customer Support Agent\", \"vi\": \"Bà Anya Patel, Nhân viên Hỗ trợ Khách hàng tại Công ty Harlund Ltd.\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"To: Anya Patel <a.patel@support.harlund.co.uk>\", \"vi\": \"Gửi tới: Anya Patel <a.patel@support.harlund.co.uk>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"From: Manuel Torres <m.torres@opalmail.co.uk>\", \"vi\": \"Từ: Manuel Torres <m.torres@opalmail.co.uk>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Date: 4 May\", \"vi\": \"Ngày: 4 tháng 5\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Subject: RE: Auto insurance\", \"vi\": \"Chủ đề: RE: Bảo hiểm ô tô\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Dear Ms. Patel,\", \"vi\": \"Kính gửi bà Patel,\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Thank you for the confirmation.\", \"vi\": \"Xin cảm ơn quý vị đã xác nhận.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I\'m happy to have insurance from a trustworthy company.\", \"vi\": \"Tôi rất vui vì được tham gia bảo hiểm tại một công ty đáng tin cậy.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"For your reference, the new car is now registered in my name.\", \"vi\": \"Xin thông báo cho quý vị biết, chiếc xe mới hiện đã được đăng ký dưới tên tôi.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Although I made the initial payment to you by credit card, I plan to follow the process outlined in your e-mail for future payments.\", \"vi\": \"Mặc dù tôi đã thực hiện khoản thanh toán ban đầu cho quý vị bằng thẻ tín dụng, nhưng tôi dự định sẽ tuân thủ quy trình được nêu trong email của quý vị cho các khoản thanh toán trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I also wanted to let you know that I have not yet received the insurance certificate.\", \"vi\": \"Tôi cũng muốn thông báo với quý vị rằng tôi vẫn chưa nhận được giấy chứng nhận bảo hiểm.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I looked for one that I could download from your Web site, but I could not find anything.\", \"vi\": \"Tôi đã tìm kiếm một bản có thể tải xuống từ trang web của quý vị, nhưng không tìm thấy gì cả.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Could you please send me a copy of the certificate?\", \"vi\": \"Xin quý vị vui lòng gửi cho tôi một bản sao của chứng chỉ được không?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 3, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Manuel Torres\", \"vi\": \"Manuel Torres\", \"type\": \"sign_off\", \"doc_index\": 3, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '351b822b-8ded-4714-8fa1-5e4e901d64b4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Eric Ozawa (12:06 P.M.)\", \"vi\": \"Eric Ozawa (12 giờ 06 phút trưa)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi Kara.\", \"vi\": \"Xin chào Kara.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I wanted to let you know that my train is going to be late.\", \"vi\": \"Tôi muốn thông báo với quý vị rằng chuyến tàu của tôi sẽ bị trễ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Kara Murato (12:10 P.M.)\", \"vi\": \"Kara Murato (12 giờ 10 phút trưa)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Oh, that’s too bad.\", \"vi\": \"Ôi, thật đáng tiếc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Will you make it to the 3:00 meeting?\", \"vi\": \"Quý vị có thể đến dự cuộc họp lúc 3 giờ không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Eric Ozawa (12:11 P.M.)\", \"vi\": \"Eric Ozawa (12 giờ 11 phút trưa)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I’m not sure.\", \"vi\": \"Tôi không chắc lắm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The conductor thinks it will be at least another hour before we leave.\", \"vi\": \"Người chỉ huy cho rằng phải ít nhất một giờ nữa chúng ta mới khởi hành.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Kara Murato (12:12 P.M.)\", \"vi\": \"Kara Murato (12 giờ 12 phút trưa)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Should we postpone the meeting?\", \"vi\": \"Chúng ta có nên hoãn cuộc họp không?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Eric Ozawa (12:14 P.M.)\", \"vi\": \"Eric Ozawa (12 giờ 14 phút trưa)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I think you should get started.\", \"vi\": \"Tôi nghĩ quý vị nên bắt đầu đi.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The plans for the new hospital wing are on my desk.\", \"vi\": \"Bản vẽ thiết kế cho khu mới của bệnh viện hiện đang nằm trên bàn làm việc của tôi.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"You know everything about the changes to the original design.\", \"vi\": \"Quý vị đã nắm rõ mọi thông tin về những thay đổi so với thiết kế ban đầu.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"You can call me if the client has any questions that you are unable to answer.\", \"vi\": \"Nếu khách hàng có bất kỳ thắc mắc nào mà quý vị không thể giải đáp, xin vui lòng gọi cho tôi.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Kara Murato (12:15 P.M.)\", \"vi\": \"Kara Murato (12 giờ 15 phút trưa)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Sounds good.\", \"vi\": \"Nghe có vẻ hay đấy.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Let me know when you have an update on your arrival time.\", \"vi\": \"Xin vui lòng thông báo cho tôi khi quý vị có thông tin cập nhật về thời gian đến.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Eric Ozawa (12:16 P.M.)\", \"vi\": \"Eric Ozawa (12 giờ 16 phút trưa)\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Sure.\", \"vi\": \"Được chứ.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Thanks.\", \"vi\": \"Cảm ơn.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '358f14db-a8e8-4546-ac54-76985eafb2e7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Aparna Kothari, Media Contact\", \"vi\": \"Aparna Kothari, Người liên hệ về truyền thông\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Kitchen Swifts\", \"vi\": \"Chim én nhà bếp\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"akothari@kitchenswifts.com.au\", \"vi\": \"akothari@kitchenswifts.com.au\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"FOR IMMEDIATE RELEASE\", \"vi\": \"THÔNG CÁO BÁO CHÍ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"SYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience.\", \"vi\": \"SYDNEY (ngày 4 tháng 6) — Kitchen Swifts và đầu bếp Darius Cordero đang hợp tác để mang đến cho các đầu bếp tại gia một trải nghiệm ẩm thực mới mẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua’s.\", \"vi\": \"Vị đầu bếp từng đoạt giải thưởng này là chủ sở hữu của các nhà hàng tại cả Philippines và Úc, trong đó có nhà hàng Enriqua’s vừa mới khai trương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"He says his cooking reflects his Filipino heritage, which is a blend of many cultures.\", \"vi\": \"Ông cho biết ẩm thực của mình phản ánh nguồn gốc Philippines của ông, vốn là sự hòa trộn của nhiều nền văn hóa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"“I’ve designed these simplified recipes for Kitchen Swifts so that cooks at home can enjoy new and exciting flavours with ease,” he said.\", \"vi\": \"“Tôi đã thiết kế những công thức nấu ăn đơn giản này cho Kitchen Swifts để những người nấu ăn tại nhà có thể dễ dàng thưởng thức những hương vị mới mẻ và hấp dẫn,” ông nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"“While preparing and eating these meals, you can feel like you are travelling the world with me.”\", \"vi\": \"“Trong lúc chuẩn bị và thưởng thức những bữa ăn này, quý vị sẽ có cảm giác như đang cùng tôi du hành khắp thế giới vậy.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Zahra Chambers, vice president of Kitchen Swifts, says she is pleased to work with Chef Cordero and to offer delicious new recipes to their customers.\", \"vi\": \"Bà Zahra Chambers, Phó chủ tịch của Kitchen Swifts, cho biết bà rất vui mừng được hợp tác cùng Bếp trưởng Cordero và mang đến những công thức nấu ăn mới ngon miệng cho quý khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections.\", \"vi\": \"Kitchen Swifts cung cấp thực đơn, công thức nấu ăn và nguyên liệu dành cho hai người, bốn người hoặc sáu người, bao gồm nhiều lựa chọn món chay đa dạng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Customers choose the most appropriate meal options, and then a box is delivered weekly.\", \"vi\": \"Khách hàng sẽ lựa chọn các thực đơn phù hợp nhất, sau đó một hộp thực phẩm sẽ được giao đến hàng tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Current customers will see no price increase with the partnership.\", \"vi\": \"Với sự hợp tác này, các khách hàng hiện tại sẽ không phải chịu bất kỳ sự tăng giá nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To find out more, visit the Kitchen Swifts Web site at www.kitchenswifts.com.au.\", \"vi\": \"Để tìm hiểu thêm, quý vị vui lòng truy cập trang web của Kitchen Swifts tại địa chỉ www.kitchenswifts.com.au.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"https://www.sydneyrestaurants.com.au\", \"vi\": \"https://www.sydneyrestaurants.com.au\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"A colleague arranged for us to eat at Enriqua\'s while I was at a conference in Sydney.\", \"vi\": \"Trong thời gian tôi tham dự hội nghị tại Sydney, một đồng nghiệp đã sắp xếp cho chúng tôi dùng bữa tại nhà hàng Enriqua\'s.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"It is usually fully booked for dinner; you may need to call months in advance for a table.\", \"vi\": \"Thường thì nhà hàng đã kín chỗ vào bữa tối; quý vị có thể cần phải gọi điện đặt bàn trước vài tháng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We had a wonderful lunch there instead.\", \"vi\": \"Thay vào đó, chúng tôi đã có một bữa trưa tuyệt vời tại đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Everything was delicious, and the bread and desserts are baked on-site!\", \"vi\": \"Mọi món ăn đều rất ngon, và bánh mì cùng các món tráng miệng đều được nướng ngay tại quán!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"It was a worthwhile treat before I flew back to Hong Kong.\", \"vi\": \"Đó thực sự là một trải nghiệm đáng nhớ trước khi tôi bay trở về Hồng Kông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"—Meili Guan\", \"vi\": \"—Meili Guan\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '35d9cff7-2b33-4805-b944-bd597f736360';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"New Vietnamese Restaurant Opens\", \"vi\": \"Nhà hàng Việt Nam mới khai trương\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"SAN FRANCISCO (November 5)—Celebrity chef Eric Hoang ------- (131) his first restaurant, Ngon Mieng.\", \"vi\": \"SAN FRANCISCO (5 tháng 11)—Đầu bếp nổi tiếng Eric Hoang ------- (131) nhà hàng đầu tiên của anh ấy, Ngon Mieng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"It opened last week in the North Beach neighborhood.\", \"vi\": \"Nó đã mở cửa vào tuần trước tại khu phố North Beach.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Ngon Mieng serves authentic Vietnamese cuisine and some innovative dishes developed by Chef Hoang.\", \"vi\": \"Ngon Mieng phục vụ các món ăn Việt Nam chính thống và một số món ăn sáng tạo do Đầu bếp Hoang phát triển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The restaurant took over the space once occupied by the restaurant Plantains, ------- (132) closed last year.\", \"vi\": \"Nhà hàng đã tiếp quản không gian từng là nhà hàng Plantains, ------- (132) đã đóng cửa vào năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [132]}, {\"en\": \"Chef Hoang won first place on the reality television show Best Chefs in the U.S. two years ago.\", \"vi\": \"Đầu bếp Hoang đã giành vị trí quán quân trong chương trình truyền hình thực tế Best Chefs in the U.S. cách đây hai năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"------- (133).\", \"vi\": \"------- (133).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [133]}, {\"en\": \"\\\"After receiving the award, opening a restaurant became my dream,\\\" he said.\", \"vi\": \"\\\"Sau khi nhận giải thưởng, việc mở một nhà hàng đã trở thành ước mơ của tôi,\\\" anh ấy nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"I am excited to bring my culinary creations to the North Beach area.\\\"\", \"vi\": \"\\\"Tôi rất hào hứng được mang những sáng tạo ẩm thực của mình đến khu vực North Beach.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"At the grand opening, diners echoed Chef Hoang\'s enthusiasm for the ------- (134).\", \"vi\": \"Tại buổi lễ khai trương, thực khách đã bày tỏ sự nhiệt tình đối với Đầu bếp Hoang về ------- (134).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [134]}, {\"en\": \"\\\"Without a doubt, it was some of the best I\'ve ever eaten,\\\" said customer Judy Blackburn.\", \"vi\": \"\\\"Không còn nghi ngờ gì nữa, đây là một trong những món ngon nhất mà tôi từng ăn,\\\" khách hàng Judy Blackburn cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '3630d96d-1506-4ec4-8f20-89cf9b2b5437';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Verita Model JX41Ci—Instructions for Use\", \"vi\": \"Mẫu Verita JX41Ci — Hướng dẫn sử dụng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Ensure that the electrical cord is untangled and then plug it into a nearby wall outlet.\", \"vi\": \"Hãy đảm bảo rằng dây điện không bị rối, sau đó cắm dây vào ổ cắm trên tường gần đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Choose the appropriate setting (floor, low carpet, high carpet) by using the dial on top of the machine.\", \"vi\": \"Vui lòng chọn chế độ phù hợp (sàn trần, thảm mỏng, thảm dày) bằng cách xoay núm điều chỉnh ở phía trên máy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Turn the machine on by pushing the power button at the base of the handle.\", \"vi\": \"Hãy bật máy bằng cách nhấn nút nguồn ở phần chân tay cầm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Run slowly and steadily over an area two or three times to pick up dirt and debris.\", \"vi\": \"Hãy di chuyển chậm rãi và đều đặn qua khu vực đó hai hoặc ba lần để thu gom bụi bẩn và các mảnh vụn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"If there is still debris in corners or other hard-to-reach areas, connect the appropriate attachment and use it on the specified area.\", \"vi\": \"Nếu vẫn còn các mảnh vụn ở các góc hoặc những khu vực khó tiếp cận khác, xin vui lòng lắp phụ kiện phù hợp và sử dụng nó tại khu vực được chỉ định.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '365594d1-977e-4eb0-a8b3-47e96abb78fb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Gasgo Propane Tank Exchange\", \"vi\": \"Dịch vụ đổi bình khí propan Gasgo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"You have chosen a safe and ___135___ way to obtain fuel for your stoves, grills, heaters, fireplaces, or other devices.\", \"vi\": \"Bạn đã chọn một cách an toàn và ___135___ để có được nhiên liệu cho bếp, lò nướng, máy sưởi, lò sưởi hoặc các thiết bị khác của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [135]}, {\"en\": \"Simply follow the directions ___136___.\", \"vi\": \"Chỉ cần làm theo các hướng dẫn ___136___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [136]}, {\"en\": \"When your tank runs out of propane, take it to our store and leave it on one of the clearly marked green shelves outside the store.\", \"vi\": \"Khi bình của bạn hết khí propan, hãy mang nó đến cửa hàng của chúng tôi và để nó lên một trong các kệ màu xanh lá cây được đánh dấu rõ ràng bên ngoài cửa hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"___137___ .\", \"vi\": \"___137___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [137]}, {\"en\": \"Then, pay the cashier inside the store for a fresh tank of propane.\", \"vi\": \"Sau đó, hãy thanh toán tiền cho nhân viên thu ngân bên trong cửa hàng để lấy một bình khí propan mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Next, the cashier or another staff member will accompany you to the outdoor exchange area.\", \"vi\": \"Tiếp theo, nhân viên thu ngân hoặc nhân viên khác sẽ đi cùng bạn ra khu vực đổi bình bên ngoài.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The staff person will give you a full tank to take home and provide help if you have multiple tanks to carry.\", \"vi\": \"Nhân viên sẽ đưa cho bạn một bình đầy để mang về nhà và hỗ trợ nếu bạn có nhiều bình cần mang theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Follow the instructions on the tank to connect it to your device.\", \"vi\": \"Hãy làm theo hướng dẫn trên bình để kết nối nó với thiết bị của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Be sure to visit us again when you need a ___138___.\", \"vi\": \"Hãy chắc chắn ghé thăm lại chúng tôi khi bạn cần một ___138___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [138]}]' WHERE `id` = '36632966-70f7-459f-9edf-b000c3c94985';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"GHI Production & Operations Management Conference\", \"vi\": \"Hội nghị Quản lý Sản xuất và Hoạt động của GHI\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"www.gipomcon.com\", \"vi\": \"www.gipomcon.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Call for Seminar Proposals\", \"vi\": \"Thông báo mời gửi đề xuất tổ chức hội thảo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Goh Heavy Industries (GHI) will convene the first-ever GHI Production & Operations Management Conference on 21–22 June at the Singapore Convention Centre.\", \"vi\": \"Công ty Goh Heavy Industries (GHI) sẽ tổ chức Hội nghị Quản lý Sản xuất và Hoạt động GHI lần đầu tiên vào ngày 21–22 tháng 6 tại Trung tâm Hội nghị Singapore.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We are calling for proposals from production and operations experts to lead seminars on their organizations\' successful actions in response to business challenges.\", \"vi\": \"Chúng tôi kêu gọi các chuyên gia trong lĩnh vực sản xuất và vận hành gửi đề xuất để chủ trì các buổi hội thảo về những biện pháp thành công mà tổ chức của họ đã áp dụng nhằm ứng phó với các thách thức kinh doanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The ideal seminar topic will relate to the conference theme of \\\"Advances in the Age of Analytics,\\\" but other topics will also be accepted.\", \"vi\": \"Chủ đề hội thảo lý tưởng sẽ liên quan đến chủ đề của hội nghị là “Những tiến bộ trong kỷ nguyên phân tích dữ liệu”, tuy nhiên các chủ đề khác cũng sẽ được chấp nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Proposals must be between 100 and 200 words long and accompanied by a summary of the submitter\'s qualifications.\", \"vi\": \"Các đề xuất phải có độ dài từ 100 đến 200 từ và kèm theo bản tóm tắt về trình độ chuyên môn của người nộp đề xuất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Roughly 30 proposals will be chosen for presentation in seminar form; if many more submissions are received, additional submitters may be invited to participate in themed 90-minute panel discussions instead.\", \"vi\": \"Khoảng 30 đề xuất sẽ được lựa chọn để trình bày dưới hình thức hội thảo; nếu số lượng đề xuất nhận được nhiều hơn dự kiến, các tác giả khác có thể sẽ được mời tham gia vào các phiên thảo luận theo chủ đề kéo dài 90 phút thay thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Submitters should be aware that proposals chosen for seminars must then be submitted to the Production & Operations Management Society (POMS) for approval so that each seminar will count as an hour of professional development for POMS members in attendance.\", \"vi\": \"Các tác giả cần lưu ý rằng các đề xuất được chọn để tổ chức hội thảo sau đó phải được gửi đến Hiệp hội Quản lý Sản xuất và Hoạt động (POMS) để xin phê duyệt, nhằm đảm bảo rằng mỗi hội thảo sẽ được tính là một giờ phát triển chuyên môn cho các thành viên POMS tham dự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please use this online form to submit your proposal to the conference\'s organizing committee by 15 November.\", \"vi\": \"Kính mong quý vị sử dụng mẫu đơn trực tuyến này để gửi đề xuất của mình đến Ban tổ chức hội nghị trước ngày 15 tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"From: Wei Chua\", \"vi\": \"Từ: Wei Chua\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: Leslie Briggs\", \"vi\": \"Gửi: Leslie Briggs\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Subject: Conference submission\", \"vi\": \"Chủ đề: Bài tham luận hội nghị\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: 11 December\", \"vi\": \"Ngày: 11 tháng 12\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Dear Ms. Briggs,\", \"vi\": \"Kính gửi Bà Briggs,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"On behalf of the GHI Production & Operations Management Conference organizing committee, it is my pleasure to invite you to lead a seminar on your proposed topic, \\\"Using Machine Learning to Optimize Backup Crew Scheduling in Airlines.\\\"\", \"vi\": \"Thay mặt Ban tổ chức Hội nghị Quản lý Sản xuất và Hoạt động của GHI, tôi rất hân hạnh được mời quý vị chủ trì một buổi hội thảo về chủ đề mà quý vị đã đề xuất, đó là “Ứng dụng Học máy để tối ưu hóa việc lập lịch làm việc cho đội ngũ dự phòng tại các hãng hàng không.”\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Please respond to this e-mail by 20 December to confirm your intention to participate in the conference.\", \"vi\": \"Kính mong quý vị trả lời email này trước ngày 20 tháng 12 để xác nhận ý định tham dự hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Once you do, I will send you information about how to begin the process of POMS accreditation.\", \"vi\": \"Khi quý vị đã thực hiện xong, tôi sẽ gửi cho quý vị thông tin về cách bắt đầu quy trình công nhận POMS.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Wei Chua\", \"vi\": \"Wei Chua\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Organizing Committee\", \"vi\": \"Ban Tổ chức\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"GHI Production & Operations Management Conference\", \"vi\": \"Hội nghị Quản lý Sản xuất và Hoạt động của GHI\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '3663dac9-4527-43be-bb03-d1f07f44dfbe';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Webmarch Still Going Strong After Fifteen Years\", \"vi\": \"Webmarch vẫn duy trì phong độ vững vàng sau mười lăm năm\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"(November 20)—Webmarch revolutionized video consumption when it first launched its Internet streaming service.\", \"vi\": \"(Ngày 20 tháng 11) — Webmarch đã tạo ra một cuộc cách mạng trong lĩnh vực tiêu thụ nội dung video khi lần đầu tiên ra mắt dịch vụ phát trực tuyến trên Internet.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"For a monthly fee, customers could watch as many movies as they liked online.\", \"vi\": \"Chỉ với một khoản phí hàng tháng, quý khách có thể xem bao nhiêu bộ phim tùy thích trên mạng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Fifteen years later, the company continues to grow and expand.\", \"vi\": \"Mười lăm năm sau, công ty vẫn tiếp tục phát triển và mở rộng quy mô.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Webmarch now not only streams movies and television shows but also produces its own critically acclaimed content.\", \"vi\": \"Hiện nay, Webmarch không chỉ phát trực tuyến phim và chương trình truyền hình mà còn tự sản xuất những nội dung của riêng mình, vốn đã nhận được nhiều lời khen ngợi từ giới phê bình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"There are other services, such as Movieriver, with similar business models, but what makes Webmarch unique is its global reach.\", \"vi\": \"Còn có những dịch vụ khác, chẳng hạn như Movieriver, với mô hình kinh doanh tương tự, nhưng điều khiến Webmarch trở nên độc đáo chính là phạm vi hoạt động trên toàn cầu của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"While currently available in 40 countries, Webmarch announced that it will be expanding its service to an additional 46 countries by February 8.\", \"vi\": \"Mặc dù hiện đã có mặt tại 40 quốc gia, Webmarch đã thông báo rằng công ty sẽ mở rộng dịch vụ của mình sang thêm 46 quốc gia nữa trước ngày 8 tháng 2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The service has content available in sixteen languages, with subtitles available in an additional fourteen languages so that people from all over the world can enjoy the same programs.\", \"vi\": \"Dịch vụ này cung cấp nội dung bằng mười sáu ngôn ngữ, kèm theo phụ đề bằng thêm mười bốn ngôn ngữ nữa, nhằm giúp người xem trên khắp thế giới có thể thưởng thức cùng các chương trình này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '3688c0d3-c7d2-4b65-b150-d40d887e2982';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"You are receiving this e-mail ______[131] you have contacted Brell Home in the past about our houseware products or have visited our Web site.\", \"vi\": \"Bạn nhận được email này ______[131] bạn đã từng liên hệ với Brell Home về các sản phẩm đồ gia dụng của chúng tôi hoặc đã truy cập trang Web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [131]}, {\"en\": \"If you no longer wish to receive our e-mails, you can be removed from our list.\", \"vi\": \"Nếu bạn không còn muốn nhận email của chúng tôi nữa, bạn có thể được xóa khỏi danh sách của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"______[132].\", \"vi\": \"______[132].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132]}, {\"en\": \"But do you really want to miss out on discount offers for products that will help you turn your house into an ______[133] home?\", \"vi\": \"Nhưng bạn có thực sự muốn bỏ lỡ các ưu đãi giảm giá cho các sản phẩm sẽ giúp bạn biến ngôi nhà của mình thành một ngôi nhà ______[133] không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [133]}, {\"en\": \"We hope you will choose to remain a subscriber so that we can continue to send ______[134] for the most popular new products for your home.\", \"vi\": \"Chúng tôi hy vọng bạn sẽ chọn tiếp tục đăng ký để chúng tôi có thể tiếp tục gửi ______[134] cho các sản phẩm mới phổ biến nhất cho ngôi nhà của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [134]}]' WHERE `id` = '36d1e95b-3c72-4abf-bc76-9349c1a1f558';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Customers\", \"vi\": \"Đến: Tất cả khách hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: asquires@lightidea.com\", \"vi\": \"Từ: asquires@lightidea.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 6\", \"vi\": \"Ngày: Ngày 6 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Light Idea Customers,\", \"vi\": \"Kính gửi khách hàng của Light Idea,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Light Idea is enacting a price increase on select energy-efficient products, effective April 17.\", \"vi\": \"Light Idea đang thực hiện việc tăng giá đối với một số sản phẩm tiết kiệm năng lượng được lựa chọn, có hiệu lực từ ngày 17 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Specific product pricing will _____139_____ .\", \"vi\": \"Giá sản phẩm cụ thể sẽ _____139_____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [139]}, {\"en\": \"Please contact your sales representative for details and questions.\", \"vi\": \"Vui lòng liên hệ với đại diện bán hàng của bạn để biết chi tiết và các thắc mắc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The last date for ordering at current prices is April 16.\", \"vi\": \"Ngày cuối cùng để đặt hàng theo mức giá hiện tại là ngày 16 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"All orders _____140_____ after this date will follow the new price list.\", \"vi\": \"Tất cả các đơn hàng _____140_____ sau ngày này sẽ tuân theo bảng giá mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [140]}, {\"en\": \"_____141_____ .\", \"vi\": \"_____141_____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [141]}, {\"en\": \"Customers will be able to find this on our Web site.\", \"vi\": \"Khách hàng sẽ có thể tìm thấy thông tin này trên trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We will continue to provide quality products and _____142_____ service to our valued customers.\", \"vi\": \"Chúng tôi sẽ tiếp tục cung cấp các sản phẩm chất lượng và dịch vụ _____142_____ cho những khách hàng quý giá của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [142]}, {\"en\": \"Thank you for your business.\", \"vi\": \"Cảm ơn quý khách đã hợp tác kinh doanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Arvin Squires\", \"vi\": \"Arvin Squires\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Head of Sales, Light Idea\", \"vi\": \"Trưởng phòng Kinh doanh, Light Idea\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '36e76840-e255-4708-86a5-d76900a34624';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Akim Diallo (10:47 A.M.)\", \"vi\": \"Akim Diallo (10 giờ 47 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Nicolette.\", \"vi\": \"Xin chào, Nicolette.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Is your e-mail working?\", \"vi\": \"Hộp thư điện tử của quý vị có hoạt động bình thường không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I just reset my password, and now I\'m having trouble connecting to the network.\", \"vi\": \"Tôi vừa đặt lại mật khẩu, và hiện tại tôi đang gặp khó khăn khi kết nối với mạng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Is it just me?\", \"vi\": \"Chỉ có mình tôi cảm thấy như vậy thôi sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I don\'t want to miss any important e-mails.\", \"vi\": \"Tôi không muốn bỏ lỡ bất kỳ email quan trọng nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Nicolette Kone (10:49 A.M.)\", \"vi\": \"Nicolette Kone (10 giờ 49 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"No, mine is down too.\", \"vi\": \"Không, của tôi cũng bị ngắt kết nối rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Akim Diallo (10:52 A.M.)\", \"vi\": \"Akim Diallo (10 giờ 52 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Any idea what\'s going on?\", \"vi\": \"Quý vị có biết chuyện gì đang xảy ra không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Nicolette Kone (10:52 A.M.)\", \"vi\": \"Nicolette Kone (10 giờ 52 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"No, but let me see what I can find out.\", \"vi\": \"Không, nhưng để tôi xem có thể tìm hiểu được gì.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Nicolette Kone (10:58 A.M.)\", \"vi\": \"Nicolette Kone (10 giờ 58 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I just checked with the tech support team.\", \"vi\": \"Tôi vừa liên hệ với đội ngũ hỗ trợ kỹ thuật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"It seems to be a global issue with the provider.\", \"vi\": \"Có vẻ như đây là một vấn đề mang tính toàn cầu liên quan đến nhà cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Akim Diallo (10:59 A.M.)\", \"vi\": \"Akim Diallo (10 giờ 59 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Let\'s hope it gets resolved soon.\", \"vi\": \"Chúng ta hãy hy vọng rằng vấn đề này sẽ sớm được giải quyết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Our clients don\'t wait-if we don\'t respond to their requests immediately, they move on to the next supplier.\", \"vi\": \"Khách hàng của chúng tôi không bao giờ chờ đợi — nếu chúng tôi không đáp ứng ngay lập tức các yêu cầu của họ, họ sẽ chuyển sang nhà cung cấp khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Nicolette Kone (11:02 A.M.)\", \"vi\": \"Nicolette Kone (11 giờ 02 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"That\'s true.\", \"vi\": \"Điều đó đúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I\'ll let you know if I get any updates.\", \"vi\": \"Nếu có thông tin mới nào, tôi sẽ thông báo cho quý vị biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '36f7132a-9bb0-4d44-8743-3f170b619474';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Pop Superstar Coming Home\", \"vi\": \"Siêu sao nhạc pop trở về quê hương\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"LAFONT (May 23)—Sonia Benitez is coming back to where it all started, and she\'s giving back.\", \"vi\": \"LAFONT (ngày 23 tháng 5) — Sonia Benitez đang trở lại nơi mà mọi chuyện bắt đầu, và cô đang đóng góp cho cộng đồng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The international pop superstar announced that she has added a free concert in Lafont to her Long Road Tour, which begins on June 2.\", \"vi\": \"Siêu sao nhạc pop quốc tế này đã thông báo rằng cô đã bổ sung một buổi biểu diễn miễn phí tại Lafont vào chuyến lưu diễn “Long Road Tour” của mình, dự kiến bắt đầu vào ngày 2 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Benitez will perform in Lafont on July 17.\", \"vi\": \"Benitez sẽ biểu diễn tại Lafont vào ngày 17 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Born in nearby Ollender, Benitez moved to Lafont with her family when she was five years old.\", \"vi\": \"Sinh ra tại thị trấn Ollender gần đó, cô Benitez đã cùng gia đình chuyển đến Lafont khi cô mới năm tuổi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"She graduated from Jasper High School, where she first caught the attention of peers and teachers by winning the schoolwide talent show at the age of fourteen, the first time she ever set foot on a stage.\", \"vi\": \"Cô tốt nghiệp Trường Trung học Jasper, nơi cô lần đầu tiên thu hút sự chú ý của bạn bè và thầy cô khi giành chiến thắng trong cuộc thi tài năng toàn trường ở tuổi mười bốn – cũng là lần đầu tiên cô bước lên sân khấu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Since then, she has embarked on a professional career that has taken her to five continents and has won her millions of fans all over the world.\", \"vi\": \"Kể từ đó, cô đã bắt đầu sự nghiệp chuyên nghiệp, đưa cô đến năm châu lục và giúp cô có được hàng triệu người hâm mộ trên khắp thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Benitez made the decision to add a concert in Lafont when her manager, Jeremy Hampton, brought to her attention a three-day break after a show in Chicago.\", \"vi\": \"Bà Benitez đã quyết định thêm một buổi biểu diễn tại Lafont khi người quản lý của bà, Jeremy Hampton, thông báo cho bà biết rằng bà sẽ có ba ngày nghỉ sau buổi diễn tại Chicago.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"It was obvious to both of us,\\\" Benitez said in a phone call from her recording studio in Los Angeles.\", \"vi\": \"\\\"Điều đó là hiển nhiên đối với cả hai chúng tôi,\\\" bà Benitez chia sẻ trong một cuộc điện thoại từ phòng thu âm của bà tại Los Angeles.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"\\\"To be so close to Lafont with an extra three days and not do a show would be unthinkable.\", \"vi\": \"\\\"Khi đã ở rất gần Lafont và còn thêm ba ngày nữa mà lại không tổ chức một buổi biểu diễn thì quả là điều không thể tưởng tượng nổi.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"It was a very easy decision to make.\\\"\", \"vi\": \"\\\"Đó là một quyết định vô cùng dễ dàng.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The only challenge was finding a venue that would accommodate all of Benitez\' hometown fans.\", \"vi\": \"Thách thức duy nhất là tìm được một địa điểm đủ sức chứa tất cả các cổ động viên quê nhà của Benitez.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The town\'s largest theater seats only 1,200.\", \"vi\": \"Rạp chiếu phim lớn nhất thị trấn này chỉ có sức chứa 1.200 chỗ ngồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Lafont Mayor Ellis Swanson came up with a creative solution.\", \"vi\": \"Ông Ellis Swanson, Thị trưởng thành phố Lafont, đã đưa ra một giải pháp sáng tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"\\\"He suggested an outdoor concert,\\\" said Benitez.\", \"vi\": \"\\\"Ông ấy đã đề xuất tổ chức một buổi hòa nhạc ngoài trời,\\\" ông Benitez nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"\\\"Not at a stadium, but at a local farm outside of town.\", \"vi\": \"\\\"Không phải tại một sân vận động, mà là tại một trang trại địa phương nằm ở ngoại ô.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"That way there won\'t be a limit on how many people can attend.\", \"vi\": \"Như vậy, sẽ không có giới hạn về số lượng người tham dự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We\'ll just set up a stage in the middle of a huge field.\\\"\", \"vi\": \"\\\"Chúng tôi sẽ dựng một sân khấu ngay giữa một cánh đồng rộng lớn.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Local radio DJ Taylor Wendel estimates that as many as 8,000 fans might turn out for the concert.\", \"vi\": \"DJ đài phát thanh địa phương Taylor Wendel ước tính có thể có tới 8.000 người hâm mộ tham dự buổi hòa nhạc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"\\\"Considering how popular Sonia is around here, and considering the concert is free, I think that\'s a conservative estimate,\\\" says Wendel.\", \"vi\": \"\\\"Xét đến việc Sonia rất được yêu mến ở khu vực này, và xét đến việc buổi hòa nhạc này miễn phí, tôi cho rằng đó là một con số ước tính khá thận trọng,\\\" ông Wendel nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"\\\"It\'s going to be a memorable event.\\\"\", \"vi\": \"\\\"Đây hứa hẹn sẽ là một sự kiện đáng nhớ.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Benitez Plays to Big Crowd\", \"vi\": \"Benitez thi đấu trước đông đảo khán giả\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"LAFONT (July 18)—Sonia Benitez\' homecoming concert last night in a field at Gingham Hills Farm was nothing short of phenomenal.\", \"vi\": \"LAFONT (ngày 18 tháng 7) — Buổi hòa nhạc chào mừng Sonia Benitez trở về quê hương vào tối qua, diễn ra tại một cánh đồng thuộc trang trại Gingham Hills, thực sự là một sự kiện vô cùng ấn tượng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"The crowd of 10,000-plus was delighted to welcome the hometown hero, who was making her first trip back to Lafont in more than 12 years.\", \"vi\": \"Hơn 10.000 khán giả đã vô cùng phấn khích khi được chào đón người hùng quê nhà, người lần đầu tiên trở lại Lafont sau hơn 12 năm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Benitez put on quite a show, extending her usual two-hour set of songs by another hour with an additional eight songs.\", \"vi\": \"Benitez đã mang đến một màn trình diễn vô cùng ấn tượng, kéo dài phần biểu diễn thường lệ kéo dài hai giờ của cô thêm một giờ nữa với tám ca khúc bổ sung.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"The evening\'s most memorable moment (of which there were many) came when Benitez was joined onstage by pianist Genevieve Parker, another native of Lafont and friend of Sonia\'s since the age of six.\", \"vi\": \"Khoảnh khắc đáng nhớ nhất trong buổi tối hôm đó (mặc dù có rất nhiều khoảnh khắc như vậy) là khi Benitez được nữ nghệ sĩ piano Genevieve Parker – cũng là người gốc Lafont và là bạn thân của Sonia từ khi cả hai mới sáu tuổi – cùng lên sân khấu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"While perhaps not as well known as Benitez, Parker is an equally accomplished musician, having studied classical piano in Vienna and having toured internationally with the Vienna Touring Orchestra.\", \"vi\": \"Dù có lẽ không nổi tiếng bằng Benitez, Parker cũng là một nhạc sĩ tài năng không kém, từng theo học piano cổ điển tại Vienna và tham gia các chuyến lưu diễn quốc tế cùng Dàn nhạc lưu diễn Vienna.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"\\\"The Butterfly Song\\\" - Sonia\'s first composition, cowritten with her sister when she was eleven years old\", \"vi\": \"\\\"Bài hát về con bướm\\\" – tác phẩm đầu tay của Sonia, được sáng tác cùng với chị gái khi cô mới mười một tuổi\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"\\\"Dinner by the Riverbank\\\" - A song about the Walton River, which runs through Lafont, with backing vocals by the Jasper High School Choir\", \"vi\": \"\\\"Bữa tối bên bờ sông\\\" – Một ca khúc về con sông Walton, con sông chảy qua thị trấn Lafont, với phần đệm giọng của Dàn hợp xướng Trường Trung học Jasper\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"\\\"A Single Morning\\\" - Sung by Sonia at her first-ever performance during high school\", \"vi\": \"\\\"Một buổi sáng\\\" – Bài hát do Sonia trình bày trong buổi biểu diễn đầu tiên của cô tại trường trung học\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"\\\"Everybody Smiles\\\" - Sonia will be accompanied by a childhood friend on the piano\", \"vi\": \"\\\"Everybody Smiles\\\" - Sonia sẽ được một người bạn thuở nhỏ đệm đàn piano\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Sonia Benitez in Lafont\\nSpecial Notes\", \"vi\": \"Sonia Benitez tại Lafont\\nNhững lưu ý đặc biệt\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Gingham Hills Farm is proud to host Sonia Benitez\' homecoming concert.\", \"vi\": \"Trang trại Gingham Hills hân hạnh được tổ chức buổi hòa nhạc chào mừng Sonia Benitez trở về quê hương.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Among the songs that Sonia will perform tonight are those listed below, which have special significance for Sonia and the Lafont community.\", \"vi\": \"Trong số các ca khúc mà Sonia sẽ trình bày vào tối nay có những bài được liệt kê dưới đây, vốn mang ý nghĩa đặc biệt đối với Sonia và cộng đồng Lafont.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '36fa9af4-e2c5-4ba0-aefd-45cb28661949';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.Lloydtouringcompany.co.uk\", \"vi\": \"http://www.Lloydtouringcompany.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Choose one of Lloyd Touring Company\'s (LTC) most popular outings to see the best that London has to offer!\", \"vi\": \"Hãy lựa chọn một trong những chuyến tham quan được ưa chuộng nhất của Công ty Lloyd Touring (LTC) để khám phá những điều tuyệt vời nhất mà London mang lại!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Tour 1: Full-day tour of the most popular tourist sites on one of our famous red double-decker buses.\", \"vi\": \"Chuyến tham quan số 1: Chuyến tham quan cả ngày đến các điểm du lịch nổi tiếng nhất trên một trong những chiếc xe buýt hai tầng màu đỏ nổi tiếng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"See the Changing of the Guard and conclude the day with a river cruise.\", \"vi\": \"Quý vị hãy đến xem nghi thức đổi gác và kết thúc ngày với một chuyến du thuyền trên sông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Tour 2: Full-day walking tour of London\'s best shopping areas.\", \"vi\": \"Chuyến tham quan số 2: Chuyến tham quan đi bộ trọn ngày khám phá các khu mua sắm nổi tiếng nhất tại London.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Explore London\'s famous department stores and wander along fashionable Bond and Oxford Streets.\", \"vi\": \"Hãy khám phá các trung tâm thương mại nổi tiếng của London và dạo bước trên các con phố thời trang Bond và Oxford.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Tour 3: Half-day tour on a red double-decker bus, including private tour of the Tower of London and lunch at a nearby café.\", \"vi\": \"Chuyến tham quan số 3: Chuyến tham quan nửa ngày trên xe buýt hai tầng màu đỏ, bao gồm chuyến tham quan riêng tại Tháp London và bữa trưa tại một quán cà phê gần đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Tour 4: Half-day tour of Buckingham Palace, including the Changing of the Guard.\", \"vi\": \"Chuyến tham quan số 4: Chuyến tham quan nửa ngày tại Cung điện Buckingham, bao gồm nghi thức đổi gác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Tour ends with a traditional fish-and-chips lunch.\", \"vi\": \"Chuyến tham quan kết thúc bằng bữa trưa truyền thống với món cá và khoai tây chiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Tour 5: Full-day walking tour featuring London\'s top highlights.\", \"vi\": \"Chuyến tham quan số 5: Chuyến tham quan đi bộ cả ngày khám phá những điểm tham quan nổi bật nhất của London.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Complete the day with a medieval banquet.\", \"vi\": \"Hãy khép lại một ngày với một bữa tiệc thời Trung cổ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"LTC\'s knowledgeable local staff members personally guide each one of our tours.\", \"vi\": \"Các nhân viên địa phương giàu kinh nghiệm của LTC sẽ trực tiếp hướng dẫn từng chuyến tham quan của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Meals are not covered, except when noted in the tour description.\", \"vi\": \"Chi phí ăn uống không được bao gồm, trừ khi có ghi rõ trong phần mô tả chương trình du lịch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Participants are responsible for meeting at chosen departure destination.\", \"vi\": \"Các thành viên tham gia có trách nhiệm tập trung tại điểm khởi hành đã chọn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"LTC does not provide pickup from hotels.\", \"vi\": \"LTC không cung cấp dịch vụ đón khách tại khách sạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"All tours can be upgraded for an additional fee to include an open-date ticket to the London Eye, London\'s famous observation wheel.\", \"vi\": \"Tất cả các tour du lịch đều có thể được nâng cấp với một khoản phí bổ sung để bao gồm vé không giới hạn ngày tham quan London Eye, vòng quay ngắm cảnh nổi tiếng của London.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"★★★★★ —Ella Bouton\", \"vi\": \"★★★★★ —Ella Bouton\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Lloyd Touring Company Review\", \"vi\": \"Đánh giá về Công ty Lloyd Touring\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"This was my first trip to London.\", \"vi\": \"Đây là chuyến đi đầu tiên của tôi đến London.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I decided to see all the major tourist sites on my own, but I wanted someone to help me discover the most interesting places to shop in London.\", \"vi\": \"Tôi đã quyết định tự mình tham quan tất cả các điểm du lịch nổi tiếng, nhưng tôi mong có ai đó giúp tôi khám phá những địa điểm mua sắm thú vị nhất tại London.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"My LTC tour guide, Larissa, was wonderful.\", \"vi\": \"Hướng dẫn viên du lịch LTC của tôi, cô Larissa, thật tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"She is an avid shopper herself, and at the beginning of the tour, she tried to get to know the participants.\", \"vi\": \"Bản thân cô cũng là một người rất đam mê mua sắm, và ngay từ đầu chuyến tham quan, cô đã cố gắng làm quen với các thành viên tham gia.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"She was able to guide everyone to the shops that they were most interested in.\", \"vi\": \"Cô ấy đã dẫn mọi người đến những cửa hàng mà họ quan tâm nhất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"It was such a personalized tour!\", \"vi\": \"Đó quả thực là một chuyến tham quan được thiết kế riêng cho từng du khách!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"And it was a bonus that Larissa also speaks French.\", \"vi\": \"Và một điểm cộng nữa là Larissa còn nói được tiếng Pháp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"My daughter and I were visiting from Paris, and we appreciated being able to communicate in two languages.\", \"vi\": \"Con gái tôi và tôi đang đến thăm từ Paris, và chúng tôi rất cảm kích vì có thể giao tiếp bằng hai ngôn ngữ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"The tour was very reasonably priced, too.\", \"vi\": \"Chuyến tham quan này cũng có mức giá rất hợp lý.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I would highly recommend it.\", \"vi\": \"Tôi xin chân thành khuyên quý vị nên thử.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"The only unpleasant part of the tour was that Oxford Street was extremely crowded when we visited, and it was difficult to walk around easily.\", \"vi\": \"Điểm duy nhất khiến chúng tôi cảm thấy không thoải mái trong chuyến tham quan là đường Oxford Street lúc chúng tôi ghé thăm đã vô cùng đông đúc, khiến việc đi lại trở nên khó khăn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}]' WHERE `id` = '3732d391-549c-4769-ad43-8f4326927900';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Crawford and Duval Opens Brick-and-Mortar Stores\", \"vi\": \"Crawford và Duval chính thức khai trương các cửa hàng truyền thống\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"HONG KONG (18 February)—Crawford and Duval, the online retailer known for its handcrafted blankets, decorative pillows, and other household goods, has established four brick-and-mortar stores in Hong Kong.\", \"vi\": \"HỒNG KÔNG (ngày 18 tháng 2) — Crawford and Duval, nhà bán lẻ trực tuyến nổi tiếng với các sản phẩm chăn dệt tay, gối trang trí và các mặt hàng gia dụng khác, đã mở bốn cửa hàng truyền thống tại Hồng Kông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Last Monday, the company celebrated the grand opening of boutique stores in Causeway Bay, Discovery Bay, and Sheung Wan in addition to a large department store in Central District.\", \"vi\": \"Thứ Hai tuần trước, công ty đã tổ chức lễ khai trương hoành tráng các cửa hàng boutique tại Causeway Bay, Discovery Bay và Sheung Wan, bên cạnh một trung tâm thương mại quy mô lớn tại Quận Central.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"While the boutique stores carry the most popular of the small household goods for which Crawford and Duval is famous, the Central District location also boasts an indoor plant department and an on-site café that features specialty coffees, teas, and light snacks.\", \"vi\": \"Bên cạnh việc các cửa hàng boutique bày bán những mặt hàng gia dụng nhỏ được ưa chuộng nhất – vốn là điểm nổi tiếng của Crawford and Duval – chi nhánh tại Khu Trung tâm còn tự hào sở hữu khu vực bán cây cảnh trong nhà cùng một quán cà phê ngay tại cửa hàng, chuyên phục vụ các loại cà phê đặc sản, trà và các món ăn nhẹ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Moreover, it has a much more extensive selection of the merchandise than what is available through the company\'s Web site.\", \"vi\": \"Hơn nữa, nơi đây có danh mục sản phẩm phong phú hơn rất nhiều so với những gì được cung cấp trên trang web của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Crawford and Duval comes to our loyal shoppers in Hong Kong!\", \"vi\": \"Crawford và Duval chính thức có mặt dành cho quý khách hàng thân thiết của chúng tôi tại Hồng Kông!\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Crawford and Duval is pleased to announce the opening of its first brick-and-mortar stores in the following locations: Causeway Bay, Discovery Bay, Sheung Wan, and Central District.\", \"vi\": \"Crawford and Duval hân hạnh thông báo về việc khai trương các cửa hàng truyền thống đầu tiên tại các địa điểm sau: Causeway Bay, Discovery Bay, Sheung Wan và Khu Trung tâm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Since the launch of our online store five years ago, we have helped you to create the living space of your dreams.\", \"vi\": \"Kể từ khi ra mắt cửa hàng trực tuyến cách đây năm năm, chúng tôi đã đồng hành cùng quý khách trong việc tạo dựng không gian sống như mơ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Now we make it even easier to decorate your home.\", \"vi\": \"Giờ đây, chúng tôi giúp việc trang trí ngôi nhà của quý vị trở nên dễ dàng hơn bao giờ hết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Each location has an interior designer on staff, so you can consult with an expert in person while you browse our popular items.\", \"vi\": \"Mỗi chi nhánh đều có chuyên viên thiết kế nội thất làm việc tại chỗ, do đó quý khách có thể trực tiếp trao đổi với chuyên gia trong khi tham quan các sản phẩm được ưa chuộng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"All locations are convenient to public transportation.\", \"vi\": \"Tất cả các địa điểm đều thuận tiện cho việc đi lại bằng phương tiện giao thông công cộng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Our Central District location offers free parking in its attached car park.\", \"vi\": \"Cơ sở của chúng tôi tại Quận Trung tâm cung cấp dịch vụ đỗ xe miễn phí tại bãi đỗ xe liền kề.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"As part of our grand-opening celebration, shoppers who visit one of our stores before 1 March will receive a gift card for HK$70 to use during their visit.\", \"vi\": \"Nhân dịp lễ khai trương trọng đại này, quý khách hàng ghé thăm một trong các cửa hàng của chúng tôi trước ngày 1 tháng 3 sẽ nhận được một thẻ quà tặng trị giá 70 HK$ để sử dụng trong lần mua sắm này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Members of our online Frequent Purchase Club will receive the same benefits in our stores, including a 10 percent discount on purchases of HK$500 or more.\", \"vi\": \"Các thành viên của Câu lạc bộ Khách hàng Thường xuyên mua sắm trực tuyến của chúng tôi sẽ được hưởng những ưu đãi tương tự tại các cửa hàng của chúng tôi, bao gồm mức giảm giá 10% khi mua hàng từ 500 HK$ trở lên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"https://www.crawfordandduval.com.hk\", \"vi\": \"https://www.crawfordandduval.com.hk\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Best Sellers\", \"vi\": \"Các sản phẩm bán chạy nhất\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Full Catalogue\", \"vi\": \"Danh mục sản phẩm đầy đủ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Shopping Cart\", \"vi\": \"Giỏ hàng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Item - Price\", \"vi\": \"Sản phẩm - Giá\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Bamboo table lamp - HK$1,450.00\", \"vi\": \"Đèn bàn bằng tre - 1.450,00 HK$\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Decorative cushions, set of two - HK$750.00\", \"vi\": \"Bộ hai chiếc gối trang trí - 750,00 HK$\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Aloe plant in a 7.5-litre planter - HK$300.00\", \"vi\": \"Cây lô hội trong chậu 7,5 lít - 300,00 HK$\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Machine-washable wool blanket - HK$2,000.00\", \"vi\": \"Chăn len có thể giặt bằng máy - 2.000,00 HK$\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Sub Total - HK$4,500.00\", \"vi\": \"Tổng phụ - 4.500,00 HK$\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Less 10% - HK$450.00\", \"vi\": \"Giảm 10% - 450,00 HK$\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"TOTAL - HK$4,050.00\", \"vi\": \"TỔNG CỘNG - 4.050,00 HK$\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Crawford and Duval\", \"vi\": \"Crawford và Duval\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Customer Receipt\", \"vi\": \"Phiếu thu của khách hàng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Date: 23 February\", \"vi\": \"Ngày: 23 tháng 2\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"☐ Cash\", \"vi\": \"☐ Tiền mặt\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"☐ Gift card number:\", \"vi\": \"☐ Số thẻ quà tặng:\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"☑ Credit card number: *************5598\", \"vi\": \"☑ Số thẻ tín dụng: *************5598\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Name on the credit card: Mei-Lin Fong\", \"vi\": \"Tên trên thẻ tín dụng: Mei-Lin Fong\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Stop at our in-store café for a treat!\", \"vi\": \"Hãy ghé qua quán cà phê ngay trong cửa hàng của chúng tôi để thưởng thức một món ngon nhé!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '373ae892-b279-4f00-add0-f6a42b103521';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"In a commercial kitchen, all refrigerators are required to have a thermometer that ___143___ from 0°F (-18°C) to 220°F (104°C).\", \"vi\": \"Trong một nhà bếp thương mại, tất cả các tủ lạnh được yêu cầu phải có một nhiệt kế có thể ___143___ từ 0°F (-18°C) đến 220°F (104°C).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [143]}, {\"en\": \"To prevent the growth of bacteria, refrigerated foods must be stored at 41°F (5°C) or below.\", \"vi\": \"Để ngăn chặn sự phát triển của vi khuẩn, thực phẩm bảo quản lạnh phải được lưu trữ ở nhiệt độ 41°F (5°C) hoặc thấp hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The head chef is responsible for checking these thermometers throughout the day to ensure that the kitchen is in compliance at all times.\", \"vi\": \"Bếp trưởng chịu trách nhiệm kiểm tra các nhiệt kế này suốt cả ngày để đảm bảo rằng nhà bếp luôn tuân thủ quy định vào mọi thời điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Also important to consider is ___144___ .\", \"vi\": \"Điều quan trọng cần lưu ý nữa là ___144___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [144]}, {\"en\": \"Thermometers should always be located in the warmest spot in the refrigerator.\", \"vi\": \"Nhiệt kế phải luôn được đặt ở vị trí ấm nhất trong tủ lạnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"___145___ .\", \"vi\": \"___145___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [145]}, {\"en\": \"This location is also appropriate because it allows the thermometer to be easily ___146___ as soon as the door is opened.\", \"vi\": \"Vị trí này cũng phù hợp vì nó cho phép nhiệt kế có thể dễ dàng được ___146___ ngay khi cửa mở.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [146]}]' WHERE `id` = '37703869-b0a2-4ee4-897a-6e2d400bd6fc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"✉ ◯\", \"vi\": \"✉ ◯\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Harry Matthews (11:19 A.M.)\", \"vi\": \"Harry Matthews (11 giờ 19 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Hi Linhan.\", \"vi\": \"Xin chào Linhan.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Did you already e-mail me the list of this week\'s invoices?\", \"vi\": \"Quý vị đã gửi cho tôi danh sách các hóa đơn của tuần này qua email chưa?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Linhan Xu (11:24 A.M.)\", \"vi\": \"Linhan Xu (11 giờ 24 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Yes.\", \"vi\": \"Vâng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I sent it over earlier today with the sales-calls records.\", \"vi\": \"Tôi đã gửi tài liệu đó cho quý vị vào sáng nay cùng với hồ sơ các cuộc gọi bán hàng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Harry Matthews (11:25 A.M.)\", \"vi\": \"Harry Matthews (11 giờ 25 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Really?\", \"vi\": \"Thật vậy sao?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I hope I didn\'t delete it.\", \"vi\": \"Tôi hy vọng là mình chưa xóa nó.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Did you accidently send the e-mail to Harvey Mattson?\", \"vi\": \"Có phải quý vị đã vô tình gửi email cho ông Harvey Mattson không?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Linhan Xu (11:28 A.M.)\", \"vi\": \"Linhan Xu (11 giờ 28 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Oh, wait – it looks like I forgot to attach it!\", \"vi\": \"Ồ, khoan đã – có vẻ như tôi đã quên đính kèm nó rồi!\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I\'ll send it over now.\", \"vi\": \"Tôi sẽ gửi cho quý vị ngay bây giờ.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Harry Matthews (11:30 A.M.)\", \"vi\": \"Harry Matthews (11 giờ 30 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Just got it.\", \"vi\": \"Tôi vừa mới nhận được rồi.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thanks!\", \"vi\": \"Cảm ơn!\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '37d5b0d8-7e91-470e-9905-15a7bf9b018b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Business Happenings\", \"vi\": \"Các sự kiện trong lĩnh vực kinh doanh\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"By Harriet Mellors\", \"vi\": \"Tác giả: Harriet Mellors\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"LONDON (1 April)—It is often hard for managers or team leaders to learn the best way to give feedback to employees and colleagues.\", \"vi\": \"LONDON (ngày 1 tháng 4) — Các nhà quản lý hay trưởng nhóm thường gặp khó khăn trong việc tìm ra cách tốt nhất để đưa ra phản hồi cho nhân viên và đồng nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Samia Bishara’s new book, Facts on Feedback (Fox Mill Press), offers advice on this subject.\", \"vi\": \"Cuốn sách mới của Samia Bishara, *Facts on Feedback* (Nhà xuất bản Fox Mill Press), đưa ra những lời khuyên về chủ đề này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Ms. Bishara is an expert consultant on company management problems and solutions.\", \"vi\": \"Bà Bishara là chuyên gia tư vấn về các vấn đề và giải pháp liên quan đến quản lý doanh nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"She advises managers to give facts and reactions, rather than advice and criticism.\", \"vi\": \"Bà khuyên các nhà quản lý nên đưa ra các sự kiện và phản ứng, thay vì đưa ra lời khuyên và chỉ trích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Ms. Bishara will be speaking at Stonecliff Bookstore on Monday, 6 April at 2:00 P.M. For more details, visit www.stonecliff.co.uk.\", \"vi\": \"Bà Bishara sẽ có buổi nói chuyện tại Hiệu sách Stonecliff vào thứ Hai, ngày 6 tháng 4 lúc 2 giờ chiều. Để biết thêm chi tiết, vui lòng truy cập www.stonecliff.co.uk.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To: Oscar Burton <oburton@harstonindustries.com.hk>\", \"vi\": \"Gửi tới: Oscar Burton <oburton@harstonindustries.com.hk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"From: Mi-Sook Pan <mpan@harstonindustries.kr>\", \"vi\": \"Từ: Mi-Sook Pan <mpan@harstonindustries.kr>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Subject: Suggestion\", \"vi\": \"Chủ đề: Đề xuất\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Date: 10 April\", \"vi\": \"Ngày: 10 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Hello Oscar,\", \"vi\": \"Xin chào Oscar,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I understand that we have not yet booked all of the workshop leaders for our upcoming professional development program at the Onyx Hotel.\", \"vi\": \"Tôi được biết rằng chúng ta vẫn chưa xác nhận được toàn bộ các giảng viên cho chương trình phát triển chuyên môn sắp tới tại Khách sạn Onyx.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I was in London a few days ago working on the Phillips account.\", \"vi\": \"Vài ngày trước, tôi có mặt tại London để làm việc cho dự án của công ty Phillips.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"While there, on 6 April, I had a chance to meet Samia Bishara and hear her speak on the topic of her new book, Facts on Feedback.\", \"vi\": \"Trong thời gian ở đó, vào ngày 6 tháng 4, tôi đã có cơ hội gặp gỡ bà Samia Bishara và lắng nghe bà trình bày về chủ đề cuốn sách mới của bà, *Facts on Feedback*.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I believe she would be an excellent choice to lead one of our workshops.\", \"vi\": \"Tôi tin rằng cô ấy sẽ là sự lựa chọn tuyệt vời để dẫn dắt một trong những buổi hội thảo của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I will gather further details about Ms. Bishara’s background and availability and send that to you shortly.\", \"vi\": \"Tôi sẽ thu thập thêm thông tin chi tiết về lý lịch và thời gian rảnh rỗi của bà Bishara, và sẽ gửi cho quý vị trong thời gian sớm nhất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I look forward to joining you during Thursday’s teleconference planning meeting.\", \"vi\": \"Tôi rất mong được tham gia cùng quý vị trong cuộc họp lập kế hoạch qua điện thoại vào thứ Năm tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Mi-Sook Pan\", \"vi\": \"Mi-Sook Pan\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '37dc4efe-4a0e-4993-ab9f-26341ff280ce';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: amal.abboud@bunzifoundation.org\", \"vi\": \"Gửi tới: amal.abboud@bunzifoundation.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: maria_mcfarland@myemail.com\", \"vi\": \"Nguồn: maria_mcfarland@myemail.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: Thursday, August 22\", \"vi\": \"Ngày: Thứ Năm, ngày 22 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Project Coordinator Position\", \"vi\": \"Chủ đề: Vị trí Điều phối viên dự án\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: résumé_m.mcfarland.pdf\", \"vi\": \"Tệp đính kèm: tóm_tắt_m.mcfarland.pdf\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Abboud,\", \"vi\": \"Kính gửi ông Abboud,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"My friend Josiah Wilkins told me that you are seeking a project coordinator for your company.\", \"vi\": \"Bạn tôi, ông Josiah Wilkins, đã cho tôi biết rằng quý công ty đang tìm kiếm một điều phối viên dự án.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I have a degree in business administration and am attaching my résumé as I think I am an excellent fit for your needs.\", \"vi\": \"Tôi có bằng cử nhân Quản trị kinh doanh và xin gửi kèm theo sơ yếu lý lịch của mình, vì tôi tin rằng mình là ứng viên rất phù hợp với yêu cầu của quý công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As you will see, I have experience using several cloud-based project-management programs.\", \"vi\": \"Như quý vị sẽ thấy, tôi có kinh nghiệm sử dụng một số phần mềm quản lý dự án dựa trên nền tảng đám mây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Furthermore, my organizational skills enable me to coordinate multiple activities simultaneously, and I can convey expectations clearly to team members involved in each phase of a project.\", \"vi\": \"Hơn nữa, nhờ khả năng tổ chức của mình, tôi có thể điều phối nhiều hoạt động cùng một lúc và truyền đạt rõ ràng các yêu cầu đến các thành viên trong nhóm tham gia vào từng giai đoạn của dự án.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"My current role as project coordinator for an international engineering firm, where I have worked for the past five years, has also afforded me ample experience managing teams, schedules, and budgets.\", \"vi\": \"Vị trí hiện tại của tôi với tư cách là điều phối viên dự án tại một công ty kỹ thuật quốc tế – nơi tôi đã làm việc trong suốt năm năm qua – cũng đã mang lại cho tôi nhiều kinh nghiệm trong việc quản lý đội ngũ, tiến độ và ngân sách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"While I enjoy the kind of work I do, it has become clear to me that I need motivation from a strong mission.\", \"vi\": \"Dù tôi rất thích công việc mình đang làm, nhưng tôi đã nhận ra rằng mình cần có động lực từ một sứ mệnh cao cả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The goal of your company to create sustainable housing projects is something that I strongly support and would be delighted to work on.\", \"vi\": \"Mục tiêu của quý công ty trong việc phát triển các dự án nhà ở bền vững là điều mà tôi hết sức ủng hộ và sẽ rất hân hạnh được tham gia thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Through my work and volunteer activities, I have spent many months abroad in various countries throughout Asia and the Middle East.\", \"vi\": \"Thông qua công việc và các hoạt động tình nguyện của mình, tôi đã có dịp dành nhiều tháng sinh sống tại nước ngoài ở nhiều quốc gia khác nhau trên khắp châu Á và Trung Đông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"This seems particularly relevant to mention, as I am comfortable leading geographically and culturally diverse teams.\", \"vi\": \"Điều này có vẻ đặc biệt đáng được đề cập, bởi tôi hoàn toàn tự tin trong việc lãnh đạo các đội ngũ đa dạng về mặt địa lý và văn hóa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thank you for your attention, and I look forward to speaking with you soon.\", \"vi\": \"Xin chân thành cảm ơn sự quan tâm của quý vị, và tôi mong được trao đổi với quý vị trong thời gian sớm nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Maria McFarland\", \"vi\": \"Maria McFarland\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '37e2e70e-c254-4fb6-a926-26239140bb4b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Deelish Barbecue Catering Menu\", \"vi\": \"Thực đơn dịch vụ tiệc nướng Deelish\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"BBQ and Fixings Buffet: $17.95 per person\", \"vi\": \"Bữa tiệc tự chọn BBQ và các món ăn kèm: 17,95 USD/người\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Choose two meats and two side dishes.\", \"vi\": \"Xin vui lòng chọn hai món thịt và hai món ăn kèm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Meats: Beef, chicken, pork, sausage\", \"vi\": \"Các loại thịt: Thịt bò, thịt gà, thịt lợn, xúc xích\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Sides: Green beans and onions, potato salad, macaroni and cheese, baked beans\", \"vi\": \"Món ăn kèm: Đậu que và hành tây, salad khoai tây, mì ống phô mai, đậu hầm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Comes with salad, drink (soft drink, coffee, or tea), and bread (cornbread or dinner roll).\", \"vi\": \"Đi kèm với salad, đồ uống (nước ngọt, cà phê hoặc trà) và bánh mì (bánh ngô hoặc bánh mì cuộn).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Extra sides available by the pound\", \"vi\": \"Có sẵn các món ăn kèm bổ sung, tính theo pound\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"$6.50: Green beans and onions\", \"vi\": \"6,50 USD: Đậu que và hành tây\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"$6.00: Potato salad\", \"vi\": \"6,00 USD: Salad khoai tây\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"$5.00: Macaroni and cheese\", \"vi\": \"5,00 USD: Mì ống phô mai\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"$4.00: Baked beans\", \"vi\": \"4,00 USD: Đậu hầm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Breakfast Buffet (priced per person)\", \"vi\": \"Bữa sáng tự chọn (giá tính theo từng người)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Choice A ($8.95): Assorted pastries and fresh fruit plus drink (coffee, tea, milk, or fruit juice)\", \"vi\": \"Lựa chọn A (8,95 USD): Các loại bánh ngọt và trái cây tươi kèm đồ uống (cà phê, trà, sữa hoặc nước ép trái cây)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Choice B ($10.95): Pancakes with syrup and all of Choice A\", \"vi\": \"Lựa chọn B (10,95 USD): Bánh kếp kèm xi-rô và tất cả các món trong Lựa chọn A\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Choice C ($13.95): Assorted omelets and all of Choice A\", \"vi\": \"Lựa chọn C (13,95 USD): Các loại trứng tráng đa dạng và tất cả các món trong Lựa chọn A\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Contact our events manager with any questions or issues with your order.\", \"vi\": \"Vui lòng liên hệ với người phụ trách sự kiện của chúng tôi nếu quý vị có bất kỳ thắc mắc hoặc vấn đề nào liên quan đến đơn hàng của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Item - Unit Cost - Quantity - Amount\", \"vi\": \"Mặt hàng - Giá đơn vị - Số lượng - Tổng số tiền\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"BBQ and Fixings Buffet - $17.95 - 30 - $538.50\", \"vi\": \"Bữa tiệc tự chọn BBQ và các món ăn kèm - 17,95 USD - 30 phần - 538,50 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Extra side - $6.00 - 3 - $18.00\", \"vi\": \"Món ăn kèm thêm - 6,00 USD - 3 món - 18,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Delivery charge - $20.00\", \"vi\": \"Phí vận chuyển - 20,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"(Order to be delivered June 23)\", \"vi\": \"(Đơn hàng sẽ được giao vào ngày 23 tháng 6)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Breakfast Choice C - $13.95 - 30 - $418.50\", \"vi\": \"Gói bữa sáng C - 13,95 USD - 30 suất - 418,50 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Delivery charge - $20.00\", \"vi\": \"Phí vận chuyển - 20,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"(Order to be delivered June 24)\", \"vi\": \"(Đơn hàng sẽ được giao vào ngày 24 tháng 6)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Subtotal - $1,015.00\", \"vi\": \"Tổng phụ - 1.015,00 Bảng Anh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Tasting fee - $14.00\", \"vi\": \"Phí nếm thử - 14,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Sales tax (6%) - $61.74\", \"vi\": \"Thuế bán hàng (6%) - 61,74 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Total Due Now - $1,090.74\", \"vi\": \"Tổng số tiền phải thanh toán ngay - 1.090,74 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"INVOICE\", \"vi\": \"HÓA ĐƠN\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Deelish Barbecue Catering\", \"vi\": \"Dịch vụ Ẩm thực Nướng ngoài trời Deelish\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"To: Derrick Arnaud <darnaud@deelishbbq.com>\", \"vi\": \"Gửi: Derrick Arnaud <darnaud@deelishbbq.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"From: Marissa Keum <mkeum@keumaccountancy.com>\", \"vi\": \"Từ: Marissa Keum <mkeum@keumaccountancy.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Date: June 3\", \"vi\": \"Ngày: 3 tháng 6\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Subject: Invoice\", \"vi\": \"Chủ đề: Hóa đơn\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Dear Mr. Arnaud,\", \"vi\": \"Kính gửi ông Arnaud,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Thank you for sending the invoice.\", \"vi\": \"Xin cảm ơn quý vị đã gửi hóa đơn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"I just have a few questions about the invoice and was hoping you could help.\", \"vi\": \"Tôi chỉ có một vài câu hỏi liên quan đến hóa đơn và mong rằng quý vị có thể giúp đỡ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"When we spoke by phone last week, you mentioned that you would deduct our tasting fee ($14.00 for two people) from our total purchase price, but the invoice does not show this.\", \"vi\": \"Khi chúng ta trao đổi qua điện thoại vào tuần trước, quý vị đã đề cập rằng quý vị sẽ khấu trừ phí nếm thử (14,00 đô la cho hai người) vào tổng giá mua hàng của chúng tôi, nhưng hóa đơn lại không thể hiện điều này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"I also had asked if I could pay half the balance now and the other half when the food is delivered.\", \"vi\": \"Tôi cũng đã hỏi xem liệu tôi có thể thanh toán một nửa số tiền còn lại ngay bây giờ và nửa còn lại khi thực phẩm được giao hay không.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Would this arrangement still work?\", \"vi\": \"Cách sắp xếp này liệu vẫn còn hiệu quả không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"If so, I will make the deposit payment once I receive the new invoice.\", \"vi\": \"Nếu vậy, tôi sẽ thanh toán khoản đặt cọc ngay khi nhận được hóa đơn mới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Marissa Keum\", \"vi\": \"Marissa Keum\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}]' WHERE `id` = '37e9d808-b0fe-49de-a08b-6ee8d02962fa';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Euroful Glass\", \"vi\": \"Euroful Glass\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.euroful.it/glasscontainers\", \"vi\": \"http://www.euroful.it/glasscontainers\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Euroful is celebrating 125 years of providing quality glass containers to Italy and beyond!\", \"vi\": \"Euroful đang kỷ niệm 125 năm cung cấp các sản phẩm bình chứa bằng thủy tinh chất lượng cao cho thị trường Ý và các khu vực khác trên thế giới!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Glass bottles and jars have long been the standard for beautiful, functional containers.\", \"vi\": \"Từ lâu, chai và lọ thủy tinh đã trở thành tiêu chuẩn cho những loại bình đựng vừa đẹp mắt vừa tiện dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Consider all the desirable attributes of this useful material.\", \"vi\": \"Hãy xem xét tất cả các đặc tính ưu việt của vật liệu hữu ích này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"1.\", \"vi\": \"1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Neutrality — Glass containers do not interact with the products they hold.\", \"vi\": \"Tính trung tính — Các bình chứa bằng thủy tinh không phản ứng với các sản phẩm được đựng bên trong.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Glass has no flavor or odor and is thus ideal for storing food or personal care products.\", \"vi\": \"Thủy tinh không có mùi vị hay mùi đặc trưng, do đó rất lý tưởng để bảo quản thực phẩm hoặc các sản phẩm chăm sóc cá nhân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"2.\", \"vi\": \"2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Impermeability — Glass is impermeable to air and water.\", \"vi\": \"Tính không thấm — Thủy tinh không thấm không khí và nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Products stored in glass containers are well protected and remain fresh longer.\", \"vi\": \"Các sản phẩm được bảo quản trong hộp thủy tinh sẽ được bảo vệ tốt và giữ được độ tươi ngon lâu hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"3.\", \"vi\": \"3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Environmentally Responsible — Glass is made of sand, limestone, and soda ash—natural ingredients that do not harm the Earth.\", \"vi\": \"Thân thiện với môi trường — Thủy tinh được làm từ cát, đá vôi và tro soda — những nguyên liệu tự nhiên không gây hại cho Trái Đất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Glass can be reused and recycled.\", \"vi\": \"Thủy tinh có thể được tái sử dụng và tái chế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"4.\", \"vi\": \"4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Convenience — Glass is easy to clean and dishwasher safe.\", \"vi\": \"Tính tiện lợi — Chất liệu thủy tinh rất dễ lau chùi và có thể rửa bằng máy rửa chén.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"5.\", \"vi\": \"5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Style — Glass has endless design possibilities.\", \"vi\": \"Phong cách — Kính mang đến vô vàn khả năng thiết kế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Choose from our catalog or work with our Euroful designers who can assist you in customizing a vessel for your product.\", \"vi\": \"Quý vị có thể lựa chọn từ danh mục sản phẩm của chúng tôi hoặc hợp tác với các nhà thiết kế của Euroful, những người sẽ hỗ trợ quý vị trong việc thiết kế riêng một loại bao bì phù hợp với sản phẩm của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"To: Tommaso Luzzatto <tluzzatto@euroful.it>\", \"vi\": \"Gửi tới: Tommaso Luzzatto <tluzzatto@euroful.it>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"From: Birgit Villadsen <bvilladsen@bivilla.co.dk>\", \"vi\": \"Từ: Birgit Villadsen <bvilladsen@bivilla.co.dk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Date: 16 February\", \"vi\": \"Ngày: 16 tháng 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Subject: New jars\", \"vi\": \"Chủ đề: Các lọ mới\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Dear Mr. Luzzatto:\", \"vi\": \"Kính gửi ông Luzzatto:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Thank you for your call during which you went over the details of the design of the jars with us.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã gọi điện và cùng chúng tôi thảo luận chi tiết về thiết kế của các lọ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"The containers are quite unique and will certainly make Bivilla\'s cosmetic products stand out from those of our competitors.\", \"vi\": \"Các loại bao bì này khá độc đáo và chắc chắn sẽ giúp các sản phẩm mỹ phẩm của Bivilla nổi bật so với các đối thủ cạnh tranh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"After talking with my team, I have one more question.\", \"vi\": \"Sau khi trao đổi với đội ngũ của tôi, tôi còn một câu hỏi nữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"We ship throughout Europe and occasionally to Asia.\", \"vi\": \"Chúng tôi giao hàng trên toàn châu Âu và thỉnh thoảng đến châu Á.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Do you have recommendations regarding packing methods and filling materials for cases in which the jars are packaged?\", \"vi\": \"Quý vị có đề xuất nào về phương pháp đóng gói và vật liệu lót cho các trường hợp đóng gói lọ không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"We are looking for a filling material that offers substantial protection for our product, but does minimal damage, if any, to the surroundings.\", \"vi\": \"Chúng tôi đang tìm kiếm một loại vật liệu đệm có khả năng bảo vệ sản phẩm của chúng tôi một cách hiệu quả, nhưng lại gây ra tác động tối thiểu, nếu có, đối với môi trường xung quanh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Birgit Villadsen\", \"vi\": \"Birgit Villadsen\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Bivilla Cosmetics\", \"vi\": \"Bivilla Cosmetics\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Filler - Protection - Earth friendly\", \"vi\": \"Chất làm đầy - Bảo vệ - Thân thiện với môi trường\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Recycled paper strips - light - + +\", \"vi\": \"Dải giấy tái chế - màu sáng - + +\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Plastic air pillows - high - –\", \"vi\": \"Gối khí bằng nhựa - cao - –\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Styrofoam packing peanuts - medium - – –\", \"vi\": \"Hạt xốp Styrofoam dùng làm vật liệu đệm – cỡ trung bình – – –\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Expanding bio foam - high - + +\", \"vi\": \"Bọt sinh học giãn nở - cao - + +\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Tips for shipping products in glass containers\", \"vi\": \"Một số lưu ý khi vận chuyển sản phẩm trong bao bì thủy tinh\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Overpacking is the safest method of transporting delicate items.\", \"vi\": \"Đóng gói kỹ lưỡng là phương pháp an toàn nhất để vận chuyển các mặt hàng dễ vỡ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Overpacking simply means packing the box containing the product inside another larger box.\", \"vi\": \"“Đóng gói nhiều lớp” đơn giản là việc đặt hộp chứa sản phẩm vào bên trong một hộp khác có kích thước lớn hơn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"An absorbent filling material is inserted between the two boxes, cushioning the smaller box from vibrations and movement during transit.\", \"vi\": \"Một lớp vật liệu đệm có khả năng hấp thụ được lót vào giữa hai thùng hàng, giúp bảo vệ thùng hàng nhỏ hơn khỏi các rung động và chuyển động trong quá trình vận chuyển.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Depending on your specific needs, any of the following materials could be used as filler.\", \"vi\": \"Tùy thuộc vào nhu cầu cụ thể của quý vị, bất kỳ vật liệu nào trong số các vật liệu sau đây đều có thể được sử dụng làm chất độn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}]' WHERE `id` = '37fbb177-8391-4577-ac7e-4f9f8a0f2379';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Staff\", \"vi\": \"Đến: Tất cả nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Yoreli Costa\", \"vi\": \"Từ: Yoreli Costa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: February 15\", \"vi\": \"Ngày: 15 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Florence Shawn\", \"vi\": \"Chủ đề: Florence Shawn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hi Everyone,\", \"vi\": \"Chào mọi người,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I have news to share about a ___131___ in the human resources department.\", \"vi\": \"Tôi có thông tin để chia sẻ về một ___131___ trong phòng nhân sự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [131]}, {\"en\": \"After nearly twenty years with Cometti Creative, Florence Shawn has decided to retire from the position of director of human resources.\", \"vi\": \"Sau gần hai mươi năm gắn bó với Cometti Creative, Florence Shawn đã quyết định nghỉ hưu khỏi vị trí giám đốc nhân sự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Our current senior manager of human resources, Makoto Ichise, will replace Ms. Shawn when she retires.\", \"vi\": \"Quản lý cấp cao hiện tại của chúng ta về nhân sự, Makoto Ichise, sẽ thay thế cô Shawn khi cô nghỉ hưu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Ms. Shawn ___132___ Mr. Ichise since he joined the company five years ago.\", \"vi\": \"Cô Shawn ___132___ ông Ichise kể từ khi ông gia nhập công ty năm năm trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [132]}, {\"en\": \"Ms. Shawn\'s ___133___ day will be February 22.\", \"vi\": \"Ngày làm việc ___133___ của cô Shawn sẽ là ngày 22 tháng 2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [133]}, {\"en\": \"A retirement party will be held for her on that day at 4:00 P.M. in the Terey Lobby.\", \"vi\": \"Một buổi tiệc chia tay nghỉ hưu sẽ được tổ chức cho cô ấy vào ngày hôm đó lúc 4:00 chiều tại sảnh Terey.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"___134___.\", \"vi\": \"___134___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [134]}, {\"en\": \"Best,\", \"vi\": \"Thân ái,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Yoreli Costa\", \"vi\": \"Yoreli Costa\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Director of Operations, Cometti Creative\", \"vi\": \"Giám đốc Vận hành, Cometti Creative\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '3801c02e-74fc-4023-be1b-599b0b60a98d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MARIGOLD CITY (11 May)—The Marigold City Council has received a draft of the plans to build a new sports arena in outer Marigold.\", \"vi\": \"THÀNH PHỐ MARIGOLD (ngày 11 tháng 5) — Hội đồng Thành phố Marigold đã nhận được bản dự thảo kế hoạch xây dựng một sân vận động thể thao mới tại khu vực ngoại ô Marigold.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The arena, which will host both sporting events and concerts, will be built on the site of the former Marigold Furniture Factory.\", \"vi\": \"Sân vận động này, nơi sẽ tổ chức cả các sự kiện thể thao lẫn các buổi hòa nhạc, sẽ được xây dựng trên khu đất của Nhà máy Đồ nội thất Marigold trước đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The building has remained empty since Marigold Furniture moved production to another location over five years ago.\", \"vi\": \"Tòa nhà này vẫn bỏ trống kể từ khi công ty Marigold Furniture chuyển hoạt động sản xuất sang một địa điểm khác cách đây hơn năm năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The arena\'s designers now need to send the construction plans to the city\'s planning commission for acceptance.\", \"vi\": \"Các nhà thiết kế của sân vận động hiện cần gửi bản vẽ thi công đến Ủy ban Quy hoạch thành phố để được phê duyệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Building can begin once the plans, and any revisions, are accepted.\", \"vi\": \"Việc xây dựng có thể bắt đầu ngay sau khi bản vẽ thiết kế và mọi bản sửa đổi được chấp thuận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Construction is expected to start early next year and take approximately two years.\", \"vi\": \"Dự kiến công trình sẽ khởi công vào đầu năm tới và kéo dài khoảng hai năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '3812ac78-7dbd-470c-a518-8e75e6c1cae6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Spotlight on Geiger Travel\", \"vi\": \"Giới thiệu về Geiger Travel\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Wanting to combine his passion for exploring places and cultures with his career as a corporate travel consultant, Marcus Geiger founded Geiger Travel Management (GTM).\", \"vi\": \"Với mong muốn kết hợp niềm đam mê khám phá các địa điểm và nền văn hóa với sự nghiệp của mình trong vai trò chuyên gia tư vấn du lịch doanh nghiệp, ông Marcus Geiger đã thành lập công ty Geiger Travel Management (GTM).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Now, ten years later, the company has offices in the United States, Canada, and several South American nations.\", \"vi\": \"Hiện nay, sau mười năm, công ty đã có các văn phòng tại Hoa Kỳ, Canada và một số quốc gia ở Nam Mỹ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"It crafts itineraries and facilitates travel and accommodation arrangements for business professionals.\", \"vi\": \"Công ty này chuyên lập các lịch trình và hỗ trợ các thủ tục liên quan đến việc đi lại và chỗ ở cho các chuyên gia trong lĩnh vực kinh doanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"GTM also offers its clients secure, high-speed computers, conference call systems, and file management software through an agreement with Balefire Electronics, located in Mumbai.\", \"vi\": \"GTM cũng cung cấp cho khách hàng các hệ thống máy tính an toàn, tốc độ cao, hệ thống hội nghị truyền hình và phần mềm quản lý tệp thông qua thỏa thuận hợp tác với công ty Balefire Electronics, có trụ sở tại Mumbai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"\\\"We owe a lot of our success to Balefire,\\\" says Mr. Geiger, \\\"because their services enable our clients to work efficiently wherever they are.\\\"\", \"vi\": \"\\\"Chúng tôi nợ Balefire rất nhiều trong thành công của mình,\\\" ông Geiger cho biết, \\\"bởi vì các dịch vụ của họ giúp khách hàng của chúng tôi có thể làm việc hiệu quả dù họ đang ở đâu.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Mr. Geiger is optimistic that further growth is on the horizon for GTM.\", \"vi\": \"Ông Geiger bày tỏ sự lạc quan rằng GTM sẽ tiếp tục tăng trưởng trong thời gian tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Two additional businesses, Apura Airways, based in Paramaribo, Suriname, and the restaurant chain Triggerfish, headquartered in Bridgetown, Barbados, have agreed to enter into strategic partnerships with GTM in August.\", \"vi\": \"Hai doanh nghiệp khác, đó là hãng hàng không Apura Airways có trụ sở tại Paramaribo, Suriname, và chuỗi nhà hàng Triggerfish có trụ sở chính tại Bridgetown, Barbados, đã đồng ý thiết lập quan hệ đối tác chiến lược với GTM vào tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"And looking to launch operations in Europe, the company is currently in discussions with Krokushaus AG, a hospitality company with locations throughout Germany.\", \"vi\": \"Bên cạnh đó, với mục tiêu mở rộng hoạt động sang châu Âu, công ty hiện đang tiến hành các cuộc đàm phán với Krokushaus AG – một tập đoàn hoạt động trong lĩnh vực khách sạn và nhà hàng có các cơ sở trải rộng khắp nước Đức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"For more information about Geiger Travel Management, visit www.gtm.com.\", \"vi\": \"Để biết thêm thông tin về Geiger Travel Management, xin vui lòng truy cập trang web www.gtm.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '3825e777-9087-4b4a-945b-e5ac5895e413';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Teleteknic Unveils New Phone Models\", \"vi\": \"Teleteknic ra mắt các mẫu điện thoại mới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"SYDNEY (21 March)—Electronics giant Teleteknic announced that it is launching three new models of its popular smartphone: the Strato, the Alto, and the Cirro.\", \"vi\": \"SYDNEY (ngày 21 tháng 3) — Tập đoàn điện tử hàng đầu Teleteknic đã thông báo về việc ra mắt ba mẫu điện thoại thông minh mới thuộc dòng sản phẩm được ưa chuộng của hãng: Strato, Alto và Cirro.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"In terms of physical dimensions and data storage, the Strato is the smallest model, the Alto is in the middle, and the Cirro is the largest.\", \"vi\": \"Về kích thước vật lý và dung lượng lưu trữ dữ liệu, mẫu Strato là mẫu nhỏ nhất, mẫu Alto nằm ở mức trung bình, còn mẫu Cirro là mẫu lớn nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The Cirro model also includes an electronic stylus for writing or drawing on the screen.\", \"vi\": \"Mẫu Cirro còn được trang bị một bút cảm ứng điện tử để viết hoặc vẽ trên màn hình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Most of the changes from Teleteknic’s previous phone models are minor.\", \"vi\": \"Hầu hết các thay đổi so với các mẫu điện thoại trước đây của Teleteknic đều chỉ là những thay đổi nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"However, users will be impressed by a significant improvement to the camera.\", \"vi\": \"Tuy nhiên, người dùng sẽ rất ấn tượng trước sự cải tiến đáng kể về camera.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"All new models include an upgraded camera with advanced zoom features and automatic focus.\", \"vi\": \"Tất cả các mẫu máy mới đều được trang bị camera cải tiến với các tính năng zoom tiên tiến và tính năng lấy nét tự động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It also allows users to take better photos in lower light conditions.\", \"vi\": \"Ngoài ra, tính năng này còn giúp người dùng chụp được những bức ảnh đẹp hơn trong điều kiện ánh sáng yếu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Another advancement is in the batteries: the latest phones have a longer battery life and charge faster.\", \"vi\": \"Một bước tiến khác nằm ở lĩnh vực pin: các mẫu điện thoại mới nhất có thời lượng pin lâu hơn và sạc nhanh hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Consumers can get a glimpse of the phones in a promotional video posted on the company’s Web site at www.teleteknic.com.au, or they can see the models in person at next month’s technical trade show.\", \"vi\": \"Quý vị có thể xem qua các mẫu điện thoại này qua video quảng cáo được đăng tải trên trang web của công ty tại địa chỉ www.teleteknic.com.au, hoặc trực tiếp chiêm ngưỡng các mẫu sản phẩm này tại triển lãm công nghệ diễn ra vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Preorders are now being accepted at Teleteknic’s online shop.\", \"vi\": \"Hiện tại, cửa hàng trực tuyến của Teleteknic đang nhận đặt hàng trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The new phones are expected to be on store shelves in November.\", \"vi\": \"Dự kiến các mẫu điện thoại mới sẽ có mặt tại các cửa hàng vào tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '383bf42a-a5d2-4410-a83e-51c5e1fbd001';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: k.wells@rivera-grill.com\", \"vi\": \"Nguồn: k.wells@rivera-grill.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: service@boisvertsuppliers.com\", \"vi\": \"Gửi tới: service@boisvertsuppliers.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: October 16\", \"vi\": \"Ngày: 16 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Plates (Item #L8916)\", \"vi\": \"Chủ đề: Tấm (Mã sản phẩm #L8916)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Xin chào\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I\'ve been making a series of upgrades to our restaurant\'s interior under the direction of our new proprietor, and I ordered a new set of dishes from your company as part of these improvements.\", \"vi\": \"Dưới sự chỉ đạo của chủ sở hữu mới, tôi đã tiến hành một loạt các cải tiến đối với nội thất nhà hàng của chúng tôi, và trong khuôn khổ các cải tiến này, tôi đã đặt mua một bộ đồ dùng ăn uống mới từ công ty quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Unfortunately, when the order arrived this morning, I was disappointed to see that no fewer than 11 of the Lund Square Dinner Plates (Item #L8916) had cracks, chips, or both.\", \"vi\": \"Thật không may, khi đơn hàng được giao vào sáng nay, tôi đã rất thất vọng khi phát hiện ra rằng có tới 11 chiếc đĩa ăn Lund Square (Mã sản phẩm #L8916) bị nứt, sứt mẻ hoặc cả hai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I must ask that Boisvert Suppliers send 11 undamaged plates of the same type at no additional charge, and expedite the shipment so that it arrives by Wednesday.\", \"vi\": \"Tôi xin yêu cầu Công ty Boisvert Suppliers gửi 11 tấm cùng loại, không bị hư hỏng, mà không tính thêm phí, đồng thời khẩn trương sắp xếp việc vận chuyển để lô hàng có thể đến nơi trước thứ Tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"It is not fair to expect us to wait another two weeks for useable plates.\", \"vi\": \"Thật không công bằng khi mong đợi chúng tôi phải chờ thêm hai tuần nữa mới có được những tấm bản in có thể sử dụng được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"If you cannot meet this deadline, please refund the cost of two packs of the plates so that I can take our business elsewhere.\", \"vi\": \"Nếu quý vị không thể đáp ứng thời hạn này, xin vui lòng hoàn lại tiền cho hai gói đĩa để tôi có thể chuyển sang mua hàng ở nơi khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Kenneth Wells, General Manager\", \"vi\": \"Ông Kenneth Wells, Tổng Giám đốc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Rivera Grill\", \"vi\": \"Rivera Grill\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"EMERY RESTAURANT WAREHOUSE\", \"vi\": \"KHO HÀNG NHÀ HÀNG EMERY\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"http://www.emeryrestaurantwarehouse.com/dishware/348923\", \"vi\": \"http://www.emeryrestaurantwarehouse.com/dishware/348923\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Lund Square Dinner Plates\", \"vi\": \"Đĩa ăn tối Lund Square\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Lund is known for high-quality porcelain dishware, and its Square Dinner Plates are no exception.\", \"vi\": \"Lund nổi tiếng với các sản phẩm bộ đồ ăn bằng sứ chất lượng cao, và những chiếc đĩa ăn hình vuông của hãng cũng không phải là ngoại lệ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The bold angles and bright white color of these plates provide an eye-catching frame that complements any entrée.\", \"vi\": \"Những đường nét góc cạnh mạnh mẽ cùng màu trắng sáng của những chiếc đĩa này tạo nên một khung hình bắt mắt, góp phần tôn lên vẻ đẹp của bất kỳ món chính nào.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Dishwasher-safe, they are a great asset to lively restaurants.\", \"vi\": \"Có thể rửa bằng máy rửa chén, những sản phẩm này là một tài sản quý giá đối với các nhà hàng sôi động.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Plates come in packs of six, and four convenient sizes are available.\", \"vi\": \"Các đĩa được đóng gói thành từng bộ sáu chiếc và có sẵn bốn kích cỡ tiện dụng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"9 inches (Item Code 5031S), $25.25\", \"vi\": \"9 inch (Mã sản phẩm 5031S), 25,25 USD\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"10 inches (Item Code 5033R), $27.40\", \"vi\": \"10 inch (Mã sản phẩm 5033R), 27,40 USD\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"11 inches (Item Code 5043L), $29.70\", \"vi\": \"11 inch (Mã sản phẩm 5043L), 29,70 USD\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"12 inches (Item Code 5053XL), $32.05\", \"vi\": \"12 inch (Mã sản phẩm 5053XL), 32,05 USD\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Product Categories\", \"vi\": \"Danh mục sản phẩm\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"About\", \"vi\": \"Giới thiệu\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Help Center\", \"vi\": \"Trung tâm trợ giúp\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Order Date: October 17\\nOrder #: 45731 - Ship to/Bill to: Kenneth Wells\\nRivera Grill\\n280 Switzer Drive\\nBernier, TX 78046\", \"vi\": \"Ngày đặt hàng: 17 tháng 10\\nSố đơn hàng: 45731 - Địa chỉ giao hàng/Địa chỉ thanh toán: Kenneth Wells\\nRivera Grill\\n280 Switzer Drive\\nBernier, TX 78046\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Item Code - Item Name - Quantity - Unit Price - Total\", \"vi\": \"Mã hàng - Tên hàng - Số lượng - Giá đơn vị - Tổng cộng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"5033R - Lund Square Dinner Plates - 2 - $27.40 - $54.80\", \"vi\": \"5033R - Đĩa ăn tối Lund Square - 2 chiếc - 27,40 USD - 54,80 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Express Shipping: $20.00\", \"vi\": \"Vận chuyển nhanh: 20,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Subtotal: $74.80\", \"vi\": \"Tổng phụ: 74,80 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Tax (8%): $5.98\", \"vi\": \"Thuế (8%): 5,98 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Total: $80.78\", \"vi\": \"Tổng cộng: 80,78 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"EMERY RESTAURANT WAREHOUSE\", \"vi\": \"KHO HÀNG NHÀ HÀNG EMERY\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"INVOICE\", \"vi\": \"HÓA ĐƠN\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}]' WHERE `id` = '389a525d-8309-48e6-9601-9d41cc7291d3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Valley Road Bed and Breakfast <info@valleyroadbandb.com>\", \"vi\": \"Gửi: Valley Road Bed and Breakfast <info@valleyroadbandb.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Maya Rodriguez <m.rodriguez@intermountaingraphics.com>\", \"vi\": \"Từ: Maya Rodriguez <m.rodriguez@intermountaingraphics.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 30\", \"vi\": \"Ngày: 30 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Breakfast schedule\", \"vi\": \"Chủ đề: Lịch trình bữa sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Date - Category - Description - Total\", \"vi\": \"Ngày - Danh mục - Mô tả - Tổng cộng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"April 10 - Transportation - Flight to/from San Jose International Airport - $230.00\", \"vi\": \"Ngày 10 tháng 4 - Vận chuyển - Chuyến bay đến/từ Sân bay Quốc tế San Jose - 230,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"April 10 - Transportation - Taxi to Valley Road Bed and Breakfast - $31.00\", \"vi\": \"Ngày 10 tháng 4 - Phương tiện đi lại - Đi taxi đến Valley Road Bed and Breakfast - 31,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"April 11 - Transportation - Taxi to the Ivor Hotel and Conference Center - $22.50\", \"vi\": \"Ngày 11 tháng 4 – Phương tiện đi lại – Đi taxi đến Khách sạn và Trung tâm Hội nghị Ivor – 22,50 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"April 11 - Meals - Breakfast at Eileen\'s Diner - $23.85\", \"vi\": \"Ngày 11 tháng 4 - Bữa ăn - Bữa sáng tại Eileen\'s Diner - 23,85 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"April 11 - Other - Conference Registration - $175.00\", \"vi\": \"Ngày 11 tháng 4 - Mục khác - Đăng ký tham dự hội nghị - 175,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"April 11 - Meals - Dinner at Antonio\'s - $48.67\", \"vi\": \"Ngày 11 tháng 4 - Bữa ăn - Bữa tối tại Antonio\'s - 48,67 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"April 12 - Lodging - Valley Road Bed and Breakfast, two nights - $299.00\", \"vi\": \"Ngày 12 tháng 4 – Chỗ ở – Valley Road Bed and Breakfast, hai đêm – 299,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"April 12 - Transportation - Taxi to the San Jose International Airport - $31.00\", \"vi\": \"Ngày 12 tháng 4 - Phương tiện đi lại - Đi taxi đến Sân bay Quốc tế San Jose - 31,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Total amount to be reimbursed - $861.02\", \"vi\": \"Tổng số tiền cần được hoàn trả - 861,02 đô la\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Intermountain Graphics Travel Expense Reimbursement Form\", \"vi\": \"Mẫu đơn xin hoàn trả chi phí đi lại của Intermountain Graphics\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Eileen\'s Diner\", \"vi\": \"Quán ăn Eileen\'s\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Xin chào\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I have a reservation to stay at your bed and breakfast next week.\", \"vi\": \"Tuần tới, tôi đã đặt phòng để lưu trú tại nhà nghỉ của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I wanted to inquire about breakfast times.\", \"vi\": \"Tôi muốn hỏi về giờ phục vụ bữa sáng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I need to leave before 7 A.M. on Saturday morning, April 11, for my conference at the Ivor Hotel and Conference Center.\", \"vi\": \"Tôi cần phải khởi hành trước 7 giờ sáng Thứ Bảy, ngày 11 tháng 4, để tham dự hội nghị tại Khách sạn và Trung tâm Hội nghị Ivor.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Will breakfast be available before then?\", \"vi\": \"Trước thời điểm đó, liệu có phục vụ bữa sáng không ạ?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"If not, what restaurants near the conference would you recommend that would be open at that time?\", \"vi\": \"Nếu không, xin hỏi quý vị có thể giới thiệu những nhà hàng nào gần địa điểm hội nghị mà sẽ mở cửa vào thời điểm đó không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Maya Rodriguez\", \"vi\": \"Maya Rodriguez\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"All Intermountain Graphics employees who travel on official company business must fill out a Travel Expense Reimbursement Form and upload their receipts within 30 days of travel in TravelNow, our electronic travel reimbursement system.\", \"vi\": \"Tất cả nhân viên của Intermountain Graphics đi công tác theo nhiệm vụ chính thức của công ty đều phải điền vào “Mẫu đơn yêu cầu hoàn trả chi phí đi lại” và tải lên các hóa đơn trong vòng 30 ngày kể từ ngày kết thúc chuyến công tác trên TravelNow, hệ thống hoàn trả chi phí đi lại điện tử của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"All forms must be approved and signed by the employee\'s department manager.\", \"vi\": \"Tất cả các mẫu đơn đều phải được người quản lý bộ phận của nhân viên phê duyệt và ký tên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Employee: Maya Rodriguez Date: April 28\", \"vi\": \"Nhân viên: Maya Rodriguez Ngày: 28 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Purpose of Trip: To attend the Digital Graphic Designers Conference\", \"vi\": \"Mục đích của chuyến đi: Tham dự Hội nghị các nhà thiết kế đồ họa kỹ thuật số\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Approved by Eun Park Signature Eun Park\", \"vi\": \"Được phê duyệt bởi Eun Park. Chữ ký: Eun Park\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Located in the Ivor Hotel and Conference Center\", \"vi\": \"Tọa lạc tại Khách sạn và Trung tâm Hội nghị Ivor\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Family-owned and operated for over two decades!\", \"vi\": \"Doanh nghiệp do gia đình sở hữu và điều hành trong hơn hai thập kỷ qua!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"1000 Mission Rico Blvd.\", \"vi\": \"1000 Mission Rico Blvd.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Santa Clara, CA 95054\", \"vi\": \"Santa Clara, CA 95054\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"(408) 555-0126\", \"vi\": \"(408) 555-0126\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Saturday, April 11, 6:46 A.M.\", \"vi\": \"Thứ Bảy, ngày 11 tháng 4, 6 giờ 46 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Breakfast Sandwich $14.99\", \"vi\": \"Bánh mì kẹp bữa sáng 14,99 USD\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Coffee $3.50\", \"vi\": \"Cà phê $3,50\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Subtotal $18.49\", \"vi\": \"Tổng phụ: 18,49 USD\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Tax $1.11\", \"vi\": \"Số tiền đó là 1,11 đô la\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Total owed: $19.60\", \"vi\": \"Tổng số tiền phải trả: 19,60 USD\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Tip $4.25\", \"vi\": \"Loại $4,25\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Total paid: $23.85\", \"vi\": \"Tổng số tiền đã thanh toán: 23,85 USD\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Credit Card: XXXXXXXXXXXX5348\", \"vi\": \"Thẻ tín dụng: XXXXXXXXXXXX5348\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Customer Name: Maya Rodriguez\", \"vi\": \"Tên khách hàng: Maya Rodriguez\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"***Customer Copy***\", \"vi\": \"***Bản dành cho khách hàng***\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 45, \"question_numbers\": []}]' WHERE `id` = '38c9a491-1610-491a-a8ad-d868805d6cfd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Cleaning Services\", \"vi\": \"Dịch vụ vệ sinh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Living room - 5 - 4 - 3 - 2 - 1 - NP\", \"vi\": \"Phòng khách - 5 - 4 - 3 - 2 - 1 - NP\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Kitchen - 5 - 4 - 3 - 2 - 1 - NP\", \"vi\": \"Bếp - 5 - 4 - 3 - 2 - 1 - Tầng trệt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Dining room - 5 - 4 - 3 - 2 - 1 - NP\", \"vi\": \"Phòng ăn - 5 - 4 - 3 - 2 - 1 - NP\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Bedroom(s) - 5 - 4 - 3 - 2 - 1 - NP\", \"vi\": \"Số phòng ngủ - 5 - 4 - 3 - 2 - 1 - Tầng trệt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Lobby - 5 - 4 - 3 - 2 - 1 - NP\", \"vi\": \"Sảnh - 5 - 4 - 3 - 2 - 1 - NP\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Conference room(s) - 5 - 4 - 3 - 2 - 1 - NP\", \"vi\": \"Phòng hội nghị - 5 - 4 - 3 - 2 - 1 - Không có\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Other Information\", \"vi\": \"Thông tin khác\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Was it easy to make an appointment? - 5 - 4 - 3 - 2 - 1\", \"vi\": \"Việc đặt lịch hẹn có dễ dàng không? - 5 - 4 - 3 - 2 - 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Did our staff follow your specific instructions? - 5 - 4 - 3 - 2 - 1\", \"vi\": \"Nhân viên của chúng tôi có tuân thủ đúng các hướng dẫn cụ thể của quý vị không? - 5 - 4 - 3 - 2 - 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Did our staff provide information before the visit? - 5 - 4 - 3 - 2 - 1\", \"vi\": \"Nhân viên của chúng tôi có cung cấp thông tin trước chuyến thăm không? - 5 - 4 - 3 - 2 - 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Was the cost of the service what you expected? - 5 - 4 - 3 - 2 - 1\", \"vi\": \"Chi phí của dịch vụ có đúng như quý vị mong đợi không? - 5 - 4 - 3 - 2 - 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Crystal Brothers\", \"vi\": \"Anh em nhà Crystal\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Satisfaction Survey\", \"vi\": \"Khảo sát mức độ hài lòng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Thank you for hiring Crystal Brothers to clean your building.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã tin tưởng lựa chọn Crystal Brothers để thực hiện dịch vụ vệ sinh tòa nhà của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Please circle the appropriate numbers, ranging from 5, \\\"Excellent,\\\" to 1, \\\"Poor.\\\"\", \"vi\": \"Xin vui lòng khoanh tròn các số tương ứng, từ 5, “Xuất sắc”, đến 1, “Kém”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Circle \\\"NP\\\" for a type of room that is not present in the location that was cleaned.\", \"vi\": \"Hãy khoanh tròn chữ “NP” để chỉ loại phòng không có tại địa điểm đã được vệ sinh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Customer: Geraldine Hwang Date: February 22\", \"vi\": \"Khách hàng: Geraldine Hwang Ngày: 22 tháng 2\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '38ca2cf2-7738-46e2-886f-b1bf73834642';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Blossom Sales Systems\", \"vi\": \"Hệ thống Bán hàng Blossom\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Blossom Sales Systems (BSS) makes running your business a breeze with its sleek, intuitive point-of-sale devices.\", \"vi\": \"Blossom Sales Systems (BSS) giúp việc điều hành doanh nghiệp của quý vị trở nên vô cùng dễ dàng nhờ các thiết bị điểm bán hàng (POS) hiện đại và dễ sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"As a small business owner, you have many responsibilities and a reputation to build.\", \"vi\": \"Với tư cách là chủ doanh nghiệp nhỏ, quý vị phải gánh vác nhiều trách nhiệm và cần xây dựng uy tín cho doanh nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"BSS has all the tools needed to make transactions safe, seamless, and hassle-free.\", \"vi\": \"BSS sở hữu đầy đủ các công cụ cần thiết để đảm bảo các giao dịch diễn ra an toàn, suôn sẻ và thuận tiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Enjoy the convenience of a system that has you covered wherever you conduct your business.\", \"vi\": \"Hãy tận hưởng sự tiện lợi của một hệ thống luôn sẵn sàng hỗ trợ quý vị bất kể quý vị đang tiến hành hoạt động kinh doanh ở đâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Whether you sell in a store, over the phone, or online, BSS simplifies the transaction process while backing you with 24-7 technical expertise.\", \"vi\": \"Dù quý vị bán hàng tại cửa hàng, qua điện thoại hay trực tuyến, BSS sẽ giúp đơn giản hóa quy trình giao dịch đồng thời hỗ trợ quý vị bằng đội ngũ chuyên gia kỹ thuật hoạt động 24 giờ mỗi ngày, 7 ngày mỗi tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our innovative devices enable you to accept a variety of payment types—from magnetic-stripe and chip readers for credit cards to digital scanners for checks to popular mobile app payment services—ensuring that no potential sales are missed.\", \"vi\": \"Các thiết bị tiên tiến của chúng tôi cho phép quý vị chấp nhận nhiều hình thức thanh toán khác nhau — từ đầu đọc thẻ tín dụng có dải từ và chip đến máy quét séc kỹ thuật số, cho đến các dịch vụ thanh toán qua ứng dụng di động phổ biến — nhằm đảm bảo không bỏ lỡ bất kỳ cơ hội bán hàng tiềm năng nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Sign up for BSS today and enjoy a free ten-day trial.\", \"vi\": \"Hãy đăng ký sử dụng BSS ngay hôm nay để tận hưởng 10 ngày dùng thử miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Registration takes just fifteen minutes to complete.\", \"vi\": \"Quá trình đăng ký chỉ mất mười lăm phút là hoàn tất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Once approved, save $50 on the purchase of any BSS device that connects to your phone or tablet.\", \"vi\": \"Sau khi được phê duyệt, quý vị sẽ được giảm 50 USD khi mua bất kỳ thiết bị BSS nào có thể kết nối với điện thoại hoặc máy tính bảng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Call 931-555-0148 to schedule a demonstration and see how BSS can make your sales bloom!\", \"vi\": \"Hãy gọi số 931-555-0148 để đặt lịch tham quan trình diễn và tìm hiểu cách BSS có thể giúp doanh số bán hàng của quý vị tăng trưởng mạnh mẽ!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '38d4fa98-6b0a-4f5b-839e-cbd87a85fd7b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Grotel Corporation\", \"vi\": \"Tập đoàn Grotel\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"EVENT SPEAKER AGREEMENT\", \"vi\": \"THỎA THUẬN VỚI DIỄN GIẢ TẠI SỰ KIỆN\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This agreement is between Grotel Corporation and Jack Kolman (Event Speaker).\", \"vi\": \"Thỏa thuận này được ký kết giữa Công ty Grotel và ông Jack Kolman (Diễn giả sự kiện).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The parties agree that the Event Speaker shall deliver a speech lasting 60 minutes for the following:\", \"vi\": \"Các bên thống nhất rằng Diễn giả của Sự kiện sẽ trình bày một bài phát biểu kéo dài 60 phút về các nội dung sau đây:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Name: Annual Employee Recognition and Honors\", \"vi\": \"Tên: Chương trình vinh danh và trao giải thưởng thường niên cho nhân viên\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Date and Time: September 12, 7:00–8:00 P.M.\", \"vi\": \"Ngày và giờ: Ngày 12 tháng 9, từ 7 giờ đến 8 giờ tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Location: Millar Conference Hall\", \"vi\": \"Địa điểm: Hội trường Millar\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"1.\", \"vi\": \"1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Compensation and Expenses.\", \"vi\": \"Tiền thù lao và các khoản chi phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Upon fulfillment of the agreement, Grotel Corporation agrees to pay the Event Speaker a fee of $1,250.\", \"vi\": \"Khi thỏa thuận được thực hiện đầy đủ, Công ty Grotel cam kết thanh toán cho Diễn giả của sự kiện khoản thù lao trị giá 1.250 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Grotel Corporation will reimburse the Event Speaker for lodging and transportation up to $500, provided that original receipts are submitted.\", \"vi\": \"Công ty Grotel Corporation sẽ hoàn trả chi phí ăn ở và đi lại cho Diễn giả của sự kiện với mức tối đa là 500 đô la, với điều kiện phải xuất trình các hóa đơn gốc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"2.\", \"vi\": \"2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Equipment.\", \"vi\": \"Thiết bị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Grotel Corporation will provide the Event Speaker with the following equipment: projector, large screen, Internet connection, microphone.\", \"vi\": \"Công ty Grotel sẽ cung cấp cho Diễn giả của sự kiện các thiết bị sau đây: máy chiếu, màn hình lớn, kết nối Internet, micro.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"(Please see accompanying document for specific information.)\", \"vi\": \"(Kính mời quý vị tham khảo tài liệu kèm theo để biết thông tin cụ thể.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"3.\", \"vi\": \"3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Cancellation.\", \"vi\": \"Việc hủy bỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Either party may cancel the agreement without obligation to the other as long as written notice of intent to cancel is provided at least 30 days before the date of the event.\", \"vi\": \"Bất kỳ bên nào cũng có thể hủy bỏ thỏa thuận mà không phải chịu bất kỳ nghĩa vụ nào đối với bên kia, miễn là đã gửi thông báo bằng văn bản về ý định hủy bỏ ít nhất 30 ngày trước ngày diễn ra sự kiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Event Speaker Signature: Jack Kolman Date: June 2\", \"vi\": \"Chữ ký của diễn giả tại sự kiện: Jack Kolman Ngày: 2 tháng 6\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Grotel Corporation Representative: Ezra Tan Date: June 4\", \"vi\": \"Đại diện Công ty Grotel: Ezra Tan Ngày: 4 tháng 6\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '38e05491-55b7-436c-8ae2-c68422b67bef';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Cornelia Payne <cpayne@roughwing.co.uk>\", \"vi\": \"Gửi tới: Cornelia Payne <cpayne@roughwing.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Pragya Mehta <pmehta@airsky.in>\", \"vi\": \"Từ: Pragya Mehta <pmehta@airsky.in>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Lecture\", \"vi\": \"Chủ đề: Buổi giảng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 18 January\", \"vi\": \"Ngày: 18 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Notes\", \"vi\": \"Tệp đính kèm: 📎 Ghi chú\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Cornelia,\", \"vi\": \"Kính gửi Cornelia,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am sorry for the late notice, but I will not be able to join you for the lecture.\", \"vi\": \"Tôi xin lỗi vì đã thông báo muộn, nhưng tôi sẽ không thể tham dự buổi giảng của quý vị được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"My new position at the university in Mumbai requires me to remain on campus.\", \"vi\": \"Vị trí công tác mới của tôi tại trường đại học ở Mumbai đòi hỏi tôi phải ở lại trong khuôn viên trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Although I know you are fully prepared to deliver the lecture on your own, I have attached a copy of the notes I had prepared for the presentation.\", \"vi\": \"Mặc dù tôi biết quý vị đã chuẩn bị rất kỹ lưỡng để tự mình trình bày bài giảng, nhưng tôi vẫn đính kèm bản sao các ghi chú mà tôi đã chuẩn bị cho buổi thuyết trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"After you review them, let me know if there is anything else I can add.\", \"vi\": \"Sau khi quý vị xem xét các nội dung này, xin vui lòng cho tôi biết nếu còn điều gì khác mà tôi có thể bổ sung.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I had very much looked forward to traveling to Freeport, The Bahamas, for the first time and to seeing you again.\", \"vi\": \"Tôi đã rất mong chờ chuyến đi đầu tiên đến Freeport, Bahamas, và được gặp lại quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I certainly miss working with you at the City University.\", \"vi\": \"Tôi thực sự rất nhớ những ngày được làm việc cùng quý vị tại Đại học Thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Good luck with the lecture.\", \"vi\": \"Chúc quý vị thành công trong buổi giảng bài.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Pragya\", \"vi\": \"Pragya\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To: Ezra Halton <ehalton@ansonhouse.org>\", \"vi\": \"Gửi tới: Ezra Halton <ehalton@ansonhouse.org>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From: Cornelia Payne <cpayne@roughwing.co.uk>\", \"vi\": \"Từ: Cornelia Payne <cpayne@roughwing.co.uk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date: 20 January\", \"vi\": \"Ngày: 20 tháng 1\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Dear Mr. Halton,\", \"vi\": \"Kính gửi ông Halton,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I am pleased to confirm that 19 March works well for the lecture at the Anson House.\", \"vi\": \"Tôi rất vui được xác nhận rằng ngày 19 tháng 3 là thời điểm phù hợp để tổ chức buổi thuyết trình tại Anson House.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"As I had mentioned to you over the phone, I will be giving the lecture on my own.\", \"vi\": \"Như tôi đã đề cập với quý vị qua điện thoại, tôi sẽ tự mình trình bày bài giảng này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"My publisher, Alphagamma Press, will be sending 30 copies of my most recent work, coauthored with Dr. Pragya Mehta, to your institution.\", \"vi\": \"Nhà xuất bản của tôi, Alphagamma Press, sẽ gửi 30 bản cuốn sách mới nhất của tôi, được đồng tác giả với Tiến sĩ Pragya Mehta, đến cơ quan của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"You and I will both receive an e-mail confirmation from Alphagamma when the books ship.\", \"vi\": \"Khi sách được gửi đi, cả quý vị và tôi đều sẽ nhận được một email xác nhận từ Alphagamma.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"They should arrive at least a week before the lecture.\", \"vi\": \"Họ nên có mặt ít nhất một tuần trước khi buổi giảng bắt đầu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I look forward to meeting you soon.\", \"vi\": \"Tôi rất mong được gặp quý vị trong thời gian tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Cornelia Payne\", \"vi\": \"Cornelia Payne\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"The Anson House\", \"vi\": \"Ngôi nhà Anson\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"https://www.theansonhouse.bs\", \"vi\": \"https://www.theansonhouse.bs\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Freeport, The Bahamas\", \"vi\": \"Freeport, Bahamas\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Speaker Series\", \"vi\": \"Chuỗi buổi diễn thuyết\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Tickets for lectures are $35 each or may be purchased at a reduced rate of $90 for the series of three.\", \"vi\": \"Vé tham dự các buổi thuyết trình có giá 35 đô la mỗi vé hoặc quý vị có thể mua trọn bộ ba buổi với mức giá ưu đãi là 90 đô la.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Complimentary refreshments will be served.\", \"vi\": \"Các món ăn nhẹ miễn phí sẽ được phục vụ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Reservations are not required but are recommended.\", \"vi\": \"Không bắt buộc phải đặt chỗ trước, nhưng quý vị nên đặt trước.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"7 March, 7:00–8:30 P.M., Ms. Janelle Pears\", \"vi\": \"Ngày 7 tháng 3, từ 7:00 đến 8:30 tối, bà Janelle Pears\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Go behind the scenes of Anson House with historian Janelle Pears, who is a lifelong resident of Freeport.\", \"vi\": \"Hãy cùng nhà sử học Janelle Pears – người đã sinh sống tại Freeport suốt cuộc đời – khám phá hậu trường của Anson House.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Ms. Pears describes the daily life of the original residents of Anson House.\", \"vi\": \"Bà Pears mô tả cuộc sống hàng ngày của những cư dân đầu tiên tại Anson House.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"12 March, 7:00–8:30 P.M., Mr. Gregory Li\", \"vi\": \"Ngày 12 tháng 3, từ 7 giờ đến 8 giờ 30 tối, ông Gregory Li\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Our master gardener speaks about the challenges of restoring historic gardens.\", \"vi\": \"Chuyên gia làm vườn hàng đầu của chúng tôi chia sẻ về những thách thức trong việc phục hồi các khu vườn lịch sử.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"He has worked in gardens in Charleston, South Carolina, and Paris, France.\", \"vi\": \"Ông đã từng làm việc tại các khu vườn ở Charleston, Nam Carolina, và Paris, Pháp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"19 March, 7:00–8:30 P.M., Dr. Cornelia Payne\", \"vi\": \"Ngày 19 tháng 3, 19:00–20:30, Tiến sĩ Cornelia Payne\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Dr. Payne discusses her most recently published book, The Transatlantic World of the Nineteenth Century, coauthored with Dr. Pragya Mehta.\", \"vi\": \"Tiến sĩ Payne trình bày về cuốn sách mới nhất của bà, *Thế giới xuyên Đại Tây Dương của thế kỷ XIX*, được đồng tác giả cùng Tiến sĩ Pragya Mehta.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Dr. Payne has taught at the City University of Stoke-on-Trent in England for nearly 25 years.\", \"vi\": \"Tiến sĩ Payne đã giảng dạy tại Đại học Thành phố Stoke-on-Trent ở Anh trong gần 25 năm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Visit\", \"vi\": \"Hãy ghé thăm\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Exhibitions\", \"vi\": \"Triển lãm\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"Speaker Series\", \"vi\": \"Chuỗi chương trình diễn giả\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 46, \"question_numbers\": []}]' WHERE `id` = '3928b10c-0f62-48bf-a014-2a23726e7b85';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mark Chandler is Back!\", \"vi\": \"Mark Chandler đã trở lại!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Administrative Services Division welcomes back to headquarters Associate Director Mark Chandler.\", \"vi\": \"Phòng Dịch vụ Hành chính xin chào mừng Phó Giám đốc Mark Chandler trở lại trụ sở chính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Mark spent the last month in Ottawa attending an advanced training session about corporate information security.\", \"vi\": \"Trong tháng vừa qua, ông Mark đã có mặt tại Ottawa để tham dự một khóa đào tạo nâng cao về an ninh thông tin doanh nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Corporate-security training allows a company to safeguard its sensitive, confidential, and proprietary information.\", \"vi\": \"Chương trình đào tạo về an ninh doanh nghiệp giúp công ty bảo vệ các thông tin nhạy cảm, bí mật và độc quyền của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Mark is among a growing number of corporate executives who have successfully graduated from this rigorous course.\", \"vi\": \"Ông Mark là một trong số ngày càng nhiều giám đốc điều hành doanh nghiệp đã hoàn thành xuất sắc khóa học đầy thách thức này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"A member of the National Organization of Corporate Security Officers (NOCSO), Mark was formally recognized by the organization for his part in developing software that keeps electronic documents safe.\", \"vi\": \"Là thành viên của Tổ chức Quốc gia các Cán bộ An ninh Doanh nghiệp (NOCSO), ông Mark đã được tổ chức này chính thức vinh danh vì những đóng góp của ông trong việc phát triển phần mềm nhằm bảo vệ an toàn cho các tài liệu điện tử.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Well done, Mark!\", \"vi\": \"Làm tốt lắm, Mark!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '392e1e7d-4300-46ea-a032-fd1bef2da79a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Kristin Burton (8:16 A.M.)\", \"vi\": \"Kristin Burton (8 giờ 16 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"This is my first time posting on this small-business forum.\", \"vi\": \"Đây là lần đầu tiên tôi đăng bài trên diễn đàn dành cho các doanh nghiệp nhỏ này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Has anyone here experienced problems when ordering one of Atlara\'s credit card readers?\", \"vi\": \"Có ai ở đây từng gặp phải vấn đề khi đặt mua một trong các đầu đọc thẻ tín dụng của Atlara không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Marcos Menke (9:04 A.M.)\", \"vi\": \"Marcos Menke (9 giờ 04 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Are you referring to the little unit that attaches to your mobile phone or the larger, stand-alone tablet model?\", \"vi\": \"Quý vị đang đề cập đến thiết bị nhỏ gắn vào điện thoại di động hay mẫu máy tính bảng độc lập có kích thước lớn hơn?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Kristin Burton (9:30 A.M.)\", \"vi\": \"Kristin Burton (9 giờ 30 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The phone unit.\", \"vi\": \"Thiết bị điện thoại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I started an online shop using the Atlara Web hosting service and added pictures of the necklaces and rings I create.\", \"vi\": \"Tôi đã mở một cửa hàng trực tuyến bằng dịch vụ lưu trữ web Atlara và đăng tải các hình ảnh về những chiếc vòng cổ và nhẫn do chính tay tôi chế tác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"But most of my sales are still in person.\", \"vi\": \"Tuy nhiên, phần lớn doanh số bán hàng của tôi vẫn đến từ việc bán hàng trực tiếp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"So I just need a way to accept in-person payments when I\'m out at fairs or markets.\", \"vi\": \"Vì vậy, tôi chỉ cần một phương thức để nhận thanh toán trực tiếp khi tham gia các hội chợ hoặc chợ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Marcos Menke (10:19 A.M.)\", \"vi\": \"Marcos Menke (10 giờ 19 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Just go to www.atlara.com/pos/hardware and add what you want to your cart.\", \"vi\": \"Quý vị chỉ cần truy cập www.atlara.com/pos/hardware và thêm những sản phẩm quý vị muốn vào giỏ hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Kristin Burton (11:21 A.M.)\", \"vi\": \"Kristin Burton (11 giờ 21 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"That\'s the problem.\", \"vi\": \"Đó chính là vấn đề.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The system won\'t let me order it.\", \"vi\": \"Hệ thống không cho phép tôi đặt hàng món này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I get the error message \\\"Your account cannot be verified.\\\"\", \"vi\": \"Tôi nhận được thông báo lỗi: “Không thể xác minh tài khoản của quý vị.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Suzanne Shroer (11:42 A.M.)\", \"vi\": \"Suzanne Shroer (11 giờ 42 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I think I know.\", \"vi\": \"Tôi nghĩ là tôi biết rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"You have to upload scans of your business registration, a government photo ID, and a statement from your business bank account.\", \"vi\": \"Quý vị cần tải lên bản scan Giấy chứng nhận đăng ký kinh doanh, giấy tờ tùy thân có ảnh do cơ quan nhà nước cấp và bản sao kê tài khoản ngân hàng của doanh nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Kristin Burton (12:23 P.M.)\", \"vi\": \"Kristin Burton (12 giờ 23 phút trưa)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I already did all that, and I still got the error message.\", \"vi\": \"Tôi đã thực hiện tất cả những bước đó rồi, nhưng vẫn nhận được thông báo lỗi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Suzanne Shroer (12:33 P.M.)\", \"vi\": \"Suzanne Shroer (12 giờ 33 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"If that is the case, try logging back in and following the process again.\", \"vi\": \"Nếu đúng như vậy, xin vui lòng thử đăng nhập lại và thực hiện lại quy trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Cindy Acosta (1:05 P.M.)\", \"vi\": \"Cindy Acosta (1 giờ 05 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"You probably need to call the support line.\", \"vi\": \"Có lẽ quý vị cần gọi đến đường dây hỗ trợ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I found them to be very helpful with my issues a few months ago.\", \"vi\": \"Vài tháng trước, tôi thấy họ đã hỗ trợ tôi rất nhiều trong việc giải quyết các vấn đề của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Kristin Burton (1:10 P.M.)\", \"vi\": \"Kristin Burton (1 giờ 10 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I\'ve spoken with three people already.\", \"vi\": \"Tôi đã nói chuyện với ba người rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '39970674-8789-4099-beb3-01dd422412fd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"In the Kitchen\", \"vi\": \"Trong nhà bếp\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Reviewed by Peter Gottlieb\", \"vi\": \"Được biên tập bởi Peter Gottlieb\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Qi Chien understands how restaurants work.\", \"vi\": \"Ông Qi Chien hiểu rõ cách thức hoạt động của các nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Her new book, In the Kitchen: How to Thrive in the Restaurant Business, expertly advises restaurant managers on handling challenges in the industry, from creating reasonable schedules for chefs to appeasing picky diners.\", \"vi\": \"Cuốn sách mới của bà, *In the Kitchen: How to Thrive in the Restaurant Business*, đưa ra những lời khuyên chuyên sâu dành cho các nhà quản lý nhà hàng về cách xử lý những thách thức trong ngành, từ việc lập lịch làm việc hợp lý cho các đầu bếp cho đến việc làm hài lòng những thực khách khó tính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Throughout the book, Chien offers concise, practical suggestions with easy-to-understand concepts.\", \"vi\": \"Trong suốt cuốn sách, ông Chien đưa ra những gợi ý súc tích, thiết thực cùng những khái niệm dễ hiểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Overall, the book offers a colorful snapshot of the various tasks involved in the day-to-day operations of a restaurant.\", \"vi\": \"Nhìn chung, cuốn sách này mang đến một bức tranh sinh động về những công việc đa dạng trong hoạt động hàng ngày của một nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Chien\'s book is unique among other industry guides in that she interviewed restaurant owners, managers, and customers as part of her research.\", \"vi\": \"Cuốn sách của bà Chien có điểm độc đáo so với các cẩm nang ngành khác ở chỗ bà đã phỏng vấn các chủ nhà hàng, quản lý và khách hàng trong quá trình nghiên cứu của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"She even spoke to journalists who write restaurant reviews to get a good sense of what they most prize in a dining experience.\", \"vi\": \"Cô thậm chí còn trò chuyện với các nhà báo chuyên viết bài đánh giá nhà hàng để hiểu rõ hơn về những yếu tố mà họ coi trọng nhất trong một trải nghiệm ẩm thực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"My only criticism is that the book should have also included the perspective of chefs, especially since their role is crucial to a restaurant\'s success.\", \"vi\": \"Lời phê bình duy nhất của tôi là cuốn sách lẽ ra cũng nên đề cập đến quan điểm của các đầu bếp, nhất là khi vai trò của họ đóng vai trò then chốt đối với sự thành công của một nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This caveat aside, In the Kitchen is an insightful and instructive read.\", \"vi\": \"Bỏ qua điểm cần lưu ý này, cuốn sách *In the Kitchen* là một tác phẩm mang tính thấu hiểu và giàu giá trị giáo dục.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To: editor@lakecountyherald.com\", \"vi\": \"Gửi tới: editor@lakecountyherald.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"From: qichien@rapidonline.com\", \"vi\": \"Nguồn: qichien@rapidonline.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Date: August 5\", \"vi\": \"Ngày: 5 tháng 8\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Subject: In the Kitchen\", \"vi\": \"Chủ đề: Trong nhà bếp\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To the Editor:\", \"vi\": \"Kính gửi Ban Biên tập:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I was delighted to read Peter Gottlieb\'s review of my latest book, In the Kitchen, in your newspaper.\", \"vi\": \"Tôi vô cùng vui mừng khi được đọc bài phê bình của ông Peter Gottlieb về cuốn sách mới nhất của tôi, *In the Kitchen*, trên tờ báo của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I have appreciated his thoughtful comments about my works over the years, even if they are sometimes negative.\", \"vi\": \"Trong suốt những năm qua, tôi luôn trân trọng những nhận xét chu đáo của ông về các tác phẩm của tôi, dù đôi khi chúng mang tính tiêu cực.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"In this case, I was especially glad that he liked the chapter about restaurant reviewers, since initially I had been reluctant to interview journalists for the book.\", \"vi\": \"Trong trường hợp này, tôi đặc biệt vui mừng khi anh ấy thích chương nói về các nhà phê bình ẩm thực, bởi ban đầu tôi đã khá do dự khi phải phỏng vấn các nhà báo cho cuốn sách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"It is true that I could have included a greater variety of insights, but unfortunately the people whose views he most wanted to hear were just too busy to speak with me before the publishing deadline.\", \"vi\": \"Đúng là tôi có thể đã đưa vào nhiều góc nhìn đa dạng hơn, nhưng thật không may, những người mà ông ấy mong muốn lắng nghe ý kiến nhất lại quá bận rộn nên không thể trao đổi với tôi trước thời hạn xuất bản.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Perhaps this is something I can address in an updated edition of the book.\", \"vi\": \"Có lẽ đây là vấn đề mà tôi có thể đề cập đến trong một ấn bản cập nhật của cuốn sách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Qi Chien\", \"vi\": \"Qi Chien\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '39a6a346-8dc2-40b1-896c-248e49d0243b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"E-Mail Message\", \"vi\": \"Thông điệp email\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To:          Ramdeo Khemradj\", \"vi\": \"Gửi:          Ramdeo Khemradj\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From:      Kerensa Mayne\", \"vi\": \"Từ:      Kerensa Mayne\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date:       17 August\", \"vi\": \"Ngày:       17 tháng 8\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject:   Information\", \"vi\": \"Chủ đề:   Thông tin\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Attachment: Latest draft\", \"vi\": \"Tệp đính kèm: Bản thảo mới nhất\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Hi, Ramdeo.\", \"vi\": \"Xin chào, Ramdeo.\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please take a look at the latest draft and let me know what you think.\", \"vi\": \"Kính mong Quý vị vui lòng xem qua bản thảo mới nhất và cho tôi biết ý kiến của Quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I changed the layout—desserts are now on the inside back cover—and provided descriptions of the additional dinner dishes that you and your kitchen staff will be introducing next month.\", \"vi\": \"Tôi đã điều chỉnh bố cục — các món tráng miệng hiện được đặt ở trang bìa sau bên trong — đồng thời bổ sung phần mô tả về các món ăn chính mới mà quý vị cùng đội ngũ nhân viên bếp sẽ giới thiệu vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I haven\'t updated the prices yet though, as I haven\'t decided whether we will need to increase some of them.\", \"vi\": \"Tuy nhiên, tôi vẫn chưa cập nhật giá cả, vì tôi vẫn chưa quyết định liệu chúng ta có cần tăng một số mức giá hay không.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I\'m sure you agree with me that the design firm did a great job upgrading the kitchen and making the dining room brighter and more inviting.\", \"vi\": \"Tôi tin chắc quý vị cũng đồng ý với tôi rằng công ty thiết kế đã làm rất tốt trong việc nâng cấp nhà bếp và khiến phòng ăn trở nên sáng sủa và ấm cúng hơn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Kerensa\", \"vi\": \"Kerensa\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '39cb9ffa-d9b8-410b-b7b1-013d0f189b15';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Shu Jiang <sjiang@rowanatech.ca>\", \"vi\": \"Đến: Shu Jiang <sjiang@rowanatech.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Maxwell Baschet <mbaschet@mapleroadstorage.ca>\", \"vi\": \"Từ: Maxwell Baschet <mbaschet@mapleroadstorage.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 4 April\", \"vi\": \"Ngày: 4 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Your contract\", \"vi\": \"Chủ đề: Hợp đồng của bạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Jiang contract\", \"vi\": \"Tệp đính kèm: Hợp đồng của Jiang\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Jiang,\", \"vi\": \"Kính gửi bà Jiang,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We are pleased you ___143___ Maple Road Storage for your storage needs.\", \"vi\": \"Chúng tôi rất vui vì bạn ___143___ Maple Road Storage cho các nhu cầu lưu trữ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [143]}, {\"en\": \"I have attached a copy of your signed contract.\", \"vi\": \"Tôi đã đính kèm một bản sao hợp đồng đã ký của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"___144___ .\", \"vi\": \"___144___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [144]}, {\"en\": \"Do you know about our referral program?\", \"vi\": \"Bạn có biết về chương trình giới thiệu khách hàng của chúng tôi không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"You will receive one free month of storage if someone you recommend signs a contract with us.\", \"vi\": \"Bạn sẽ nhận được một tháng lưu trữ miễn phí nếu người mà bạn giới thiệu ký hợp đồng với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The new tenant will receive a free month ___145___ .\", \"vi\": \"Người thuê mới sẽ nhận được một tháng miễn phí ___145___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [145]}, {\"en\": \"You can find more information about this program and all our special ___146___ on our Web site at www.mapleroadstorage.ca.\", \"vi\": \"Bạn có thể tìm thêm thông tin về chương trình này và tất cả các chương trình đặc biệt ___146___ của chúng tôi trên trang web tại www.mapleroadstorage.ca.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [146]}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Maxwell Baschet, Site Manager\", \"vi\": \"Maxwell Baschet, Quản lý khu vực\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '39f94f28-625f-4a06-93fb-18a874e0e96f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"FOR IMMEDIATE RELEASE\", \"vi\": \"THÔNG CÁO BÁO CHÍ PHÁT HÀNH NGAY LẬP TỨC\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Media contact: Andrea Óladóttir / +613 555 0124\", \"vi\": \"Liên hệ báo chí: Andrea Óladóttir / +613 555 0124\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Babson Vehicles Ltd. Enthusiastically Implements Deluxident\'s Newest Product\", \"vi\": \"Công ty Babson Vehicles Ltd. đang nhiệt tình triển khai sản phẩm mới nhất của Deluxident\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"OTTAWA (10 June)—Babson Vehicles Ltd., a leading Canadian manufacturer, has just adopted a new fingerprint entry system aimed at improving company security.\", \"vi\": \"OTTAWA (ngày 10 tháng 6) — Công ty Babson Vehicles Ltd., một nhà sản xuất hàng đầu của Canada, vừa triển khai hệ thống kiểm soát ra vào bằng vân tay mới nhằm nâng cao mức độ an ninh cho công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Created by Icelandic firm Deluxident, the system enables employees to enter campus buildings simply by scanning their fingerprints.\", \"vi\": \"Được phát triển bởi công ty Deluxident của Iceland, hệ thống này cho phép nhân viên vào các tòa nhà trong khuôn viên trường chỉ bằng cách quét dấu vân tay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"According to Babson\'s CEO Daniel Deems, Deluxident\'s fingerprint-scanning system is a significant improvement over other security products the company has tried in the past.\", \"vi\": \"Theo ông Daniel Deems, Giám đốc điều hành của Babson, hệ thống quét vân tay của Deluxident là một bước cải tiến đáng kể so với các sản phẩm bảo mật khác mà công ty đã từng thử nghiệm trong quá khứ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"\\\"Deluxident\'s fingerprint scanner has been a tremendous asset.\", \"vi\": \"\\\"Máy quét vân tay của Deluxident thực sự là một tài sản vô cùng quý giá.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In the past, we always accessed our buildings by using photographic and electronic identification badges,\\\" said Deems.\", \"vi\": \"“Trước đây, chúng tôi luôn sử dụng thẻ nhận dạng có ảnh và thẻ nhận dạng điện tử để ra vào các tòa nhà,” ông Deems cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"Producing and replacing lost badges, however, was expensive.\", \"vi\": \"\\\"Tuy nhiên, việc sản xuất và thay thế các thẻ bị mất lại tốn kém.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In addition, they posed a significant security threat.\", \"vi\": \"Bên cạnh đó, chúng còn gây ra một mối đe dọa an ninh đáng kể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Employees sometimes forgot their badges, adding to traffic through our security office.\", \"vi\": \"Đôi khi các nhân viên quên mang theo thẻ nhân viên, khiến lượng người qua lại tại phòng an ninh của chúng tôi tăng lên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"All in all, the badges were costly and risky.\\\"\", \"vi\": \"Nói chung, những huy hiệu này vừa tốn kém vừa tiềm ẩn nhiều rủi ro.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"For the past decade, Deluxident has been offering high-tech workplace solutions with its innovative digital products.\", \"vi\": \"Trong thập kỷ qua, Deluxident đã cung cấp các giải pháp công nghệ cao cho môi trường làm việc thông qua các sản phẩm kỹ thuật số sáng tạo của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Headquartered in Reykjavík, Deluxident delivers items worldwide and offers 24-hour technical assistance by telephone.\", \"vi\": \"Có trụ sở chính tại Reykjavík, Deluxident cung cấp sản phẩm trên toàn thế giới và cung cấp dịch vụ hỗ trợ kỹ thuật qua điện thoại 24 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"For further details about the new fingerprint-scanning entry system, visit www.deluxident.is.\", \"vi\": \"Để biết thêm chi tiết về hệ thống kiểm soát ra vào bằng quét vân tay mới, vui lòng truy cập www.deluxident.is.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '39fa0418-59d1-490c-bb70-83d6c332e390';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: minjunlee@alto.com\", \"vi\": \"Đến: minjunlee@alto.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: contest@asianaturemag.org\", \"vi\": \"Từ: contest@asianaturemag.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 7 September\", \"vi\": \"Ngày: 7 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Tenth annual contest\", \"vi\": \"Chủ đề: Cuộc thi thường niên lần thứ mười\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Asia Nature magazine wants to thank you for your ___135____ .\", \"vi\": \"Tạp chí Asia Nature muốn cảm ơn bạn vì ___135____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [135]}, {\"en\": \"Your participation in our tenth annual amateur photography contest is appreciated.\", \"vi\": \"Sự tham gia của bạn trong cuộc thi nhiếp ảnh nghiệp dư thường niên lần thứ mười của chúng tôi rất được trân trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Each photograph we receive is judged by our panel of experts.\", \"vi\": \"Mỗi bức ảnh chúng tôi nhận được đều được đánh giá bởi hội đồng chuyên gia của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"___136____ .\", \"vi\": \"___136____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [136]}, {\"en\": \"Their works have been displayed in galleries around the world.\", \"vi\": \"Các tác phẩm của họ đã được trưng bày tại các phòng trưng bày trên khắp thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Asia Nature magazine depends on people like you who care about the environment and ____137___ nature\'s beauty.\", \"vi\": \"Tạp chí Asia Nature phụ thuộc vào những người như bạn, những người quan tâm đến môi trường và ____137___ vẻ đẹp của thiên nhiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [137]}, {\"en\": \"We ask that you visit our Web site and make a contribution today.\", \"vi\": \"Chúng tôi đề nghị bạn truy cập trang web của chúng tôi và đóng góp ngay hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Without ___138____ readers like you, we would not be able to continue our work.\", \"vi\": \"Nếu không có ___138____ những độc giả như bạn, chúng tôi sẽ không thể tiếp tục công việc của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [138]}]' WHERE `id` = '3a08e115-41fc-4cea-b253-d6828fda17f0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Survey: Consumers Prefer Physical Stores\", \"vi\": \"Kết quả khảo sát: Người tiêu dùng ưa chuộng các cửa hàng truyền thống\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"A recent consumer survey has shown that 33% of respondents prefer to touch the products they intend to purchase.\", \"vi\": \"Một cuộc khảo sát người tiêu dùng gần đây cho thấy 33% số người được hỏi thích được sờ tận tay vào những sản phẩm mà họ dự định mua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Moreover, 61% of those surveyed said they are likely to spend more when shopping at a brick-and-mortar store rather than at an online store.\", \"vi\": \"Hơn nữa, 61% số người được khảo sát cho biết họ có xu hướng chi tiêu nhiều hơn khi mua sắm tại cửa hàng truyền thống so với khi mua sắm tại cửa hàng trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"These data, backed up by other consumer preference studies, are causing many merchants who generate all their revenue from online sales to open physical stores as a supplement to their online presence.\", \"vi\": \"Những dữ liệu này, được củng cố bởi các nghiên cứu khác về sở thích của người tiêu dùng, đang khiến nhiều doanh nghiệp – vốn thu toàn bộ doanh thu từ bán hàng trực tuyến – phải mở các cửa hàng thực tế nhằm bổ sung cho hoạt động kinh doanh trực tuyến của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The advantage of a physical space is that it helps retail owners build brand loyalty.\", \"vi\": \"Ưu điểm của không gian thực là giúp các chủ cửa hàng bán lẻ xây dựng lòng trung thành với thương hiệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"“In terms of convenience, nothing beats online,” says Marlene Fitzroy, who owns Toddles, a children’s store in Shelburn, and an online site, toddles.com.\", \"vi\": \"“Về mặt sự tiện lợi, không gì sánh bằng mua sắm trực tuyến,” bà Marlene Fitzroy, chủ cửa hàng đồ trẻ em Toddles tại Shelburn và trang web toddles.com, chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"“But a physical space fosters a sense of community that keeps local customers coming back and attracts new ones.”\", \"vi\": \"“Tuy nhiên, một không gian thực tế sẽ nuôi dưỡng tinh thần cộng đồng, giúp giữ chân khách hàng địa phương và thu hút thêm những khách hàng mới.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Ms. Fitzroy, a frequent speaker at local business events, is not only a strong supporter and promoter of customer engagement; she also practices what she preaches.\", \"vi\": \"Bà Fitzroy, một diễn giả thường xuyên tại các sự kiện kinh doanh địa phương, không chỉ là người ủng hộ và thúc đẩy mạnh mẽ việc tương tác với khách hàng; bà còn thực hành đúng những gì mình đã chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"“Four times a year, we host a special sales event during which children can enjoy themselves with a variety of activities,” she said.\", \"vi\": \"“Bốn lần mỗi năm, chúng tôi tổ chức một sự kiện bán hàng đặc biệt, trong đó các em nhỏ có thể vui chơi thỏa thích với nhiều hoạt động đa dạng,” cô nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"“These events are a hit with both the children and their parents.\", \"vi\": \"“Các sự kiện này rất được lòng cả trẻ em lẫn các bậc phụ huynh.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"And even if the parents don’t buy anything on such occasions, the next time they need a children’s toy, game, book, or puzzle, they’ll probably think of us.”\", \"vi\": \"“Và ngay cả khi các bậc phụ huynh không mua gì trong những dịp như vậy, thì lần tới khi họ cần đồ chơi, trò chơi, sách hay trò ghép hình cho trẻ em, họ có lẽ sẽ nghĩ đến chúng tôi.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Shelburn Business Coalition (SBC)\", \"vi\": \"Liên minh Doanh nghiệp Shelburn (SBC)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Businesspeople from Shelburn and the surrounding area are invited to join us at the Shelburn Convention Center on October 8 for our annual Business Summit.\", \"vi\": \"Kính mời các doanh nhân đến từ Shelburn và các khu vực lân cận tham dự Hội nghị Thượng đỉnh Doanh nghiệp thường niên của chúng tôi tại Trung tâm Hội nghị Shelburn vào ngày 8 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Our keynote speaker this year will be Mr. Hansraj Deshpande, founder and CEO of Wintereden Hoteliers.\", \"vi\": \"Diễn giả chính của chúng tôi trong năm nay sẽ là ông Hansraj Deshpande, người sáng lập kiêm Giám đốc điều hành của Wintereden Hoteliers.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Other speakers, all local business owners, are Ms. Omodele Akindjo, Ms. Marlene Fitzroy, Mr. Jasper Klinkhamer, and Mr. Alvin Liu.\", \"vi\": \"Các diễn giả khác, đều là các chủ doanh nghiệp địa phương, bao gồm bà Omodele Akindjo, bà Marlene Fitzroy, ông Jasper Klinkhamer và ông Alvin Liu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Topics to be covered include building a strong workforce, establishing a line of credit, engaging with customers, and attracting venture capital.\", \"vi\": \"Các chủ đề sẽ được đề cập bao gồm xây dựng đội ngũ nhân lực vững mạnh, thiết lập hạn mức tín dụng, tương tác với khách hàng và thu hút vốn đầu tư mạo hiểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"By registering for this event, you will automatically be added to our e-mail list.\", \"vi\": \"Khi đăng ký tham gia sự kiện này, quý vị sẽ tự động được thêm vào danh sách nhận email của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Please visit our Web site, www.shelburnbusinesscoalition.org, for the full schedule.\", \"vi\": \"Kính mời quý vị truy cập trang web của chúng tôi, www.shelburnbusinesscoalition.org, để xem lịch trình đầy đủ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"To:          Vaughn Sgammato\", \"vi\": \"Gửi:          Vaughn Sgammato\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"From:      Irene Warga\", \"vi\": \"Từ:      Irene Warga\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Date:       September 15\", \"vi\": \"Ngày:       15 tháng 9\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Subject:   Your confirmation\", \"vi\": \"Chủ đề:   Xác nhận của quý vị\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Dear Mr. Sgammato,\", \"vi\": \"Kính gửi ông Sgammato,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Shelburn Business Coalition thanks you for registering for our Business Summit.\", \"vi\": \"Liên minh Doanh nghiệp Shelburn xin chân thành cảm ơn quý vị đã đăng ký tham dự Hội nghị Thượng đỉnh Doanh nghiệp của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Your confirmation number is R56690.\", \"vi\": \"Số xác nhận của quý vị là R56690.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"As a reminder, please note that the convention center underground garage will be closed for maintenance on October 8.\", \"vi\": \"Xin nhắc lại, xin quý vị lưu ý rằng bãi đỗ xe ngầm của trung tâm hội nghị sẽ tạm ngừng hoạt động để bảo trì vào ngày 8 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Therefore, please park your car in the public parking area across the street.\", \"vi\": \"Do đó, xin quý vị vui lòng đỗ xe tại bãi đỗ xe công cộng bên kia đường.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"At the end of the summit, you will receive a voucher to cover the parking fee.\", \"vi\": \"Khi kết thúc hội nghị thượng đỉnh, quý vị sẽ nhận được một phiếu giảm giá để thanh toán phí đỗ xe.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"We look forward to seeing you.\", \"vi\": \"Chúng tôi rất mong được gặp quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"If you have any questions, please contact me at 555-0138.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào, xin vui lòng liên hệ với tôi theo số 555-0138.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Yours very truly,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Irene Warga, Event Coordinator\", \"vi\": \"Bà Irene Warga, Điều phối viên sự kiện\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '3a38b00f-8c3b-476e-b02c-608280b4ce27';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Joan Trivers [10:34 A.M.]\", \"vi\": \"Joan Trivers [10 giờ 34 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Yuji, my train is delayed by one hour, and I might be late for my presentation.\", \"vi\": \"Yuji ạ, chuyến tàu của tôi bị trễ một giờ, và có lẽ tôi sẽ đến muộn buổi thuyết trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Would you be able to set up and start for me if I am not there before 2:00?\", \"vi\": \"Nếu tôi không có mặt trước 2 giờ, quý vị có thể giúp tôi chuẩn bị và khởi động mọi thứ được không ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Yuji Okada [10:35 A.M.]\", \"vi\": \"Yuji Okada [10 giờ 35 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Sure.\", \"vi\": \"Được chứ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"When are you due in?\", \"vi\": \"Khi nào quý vị dự kiến sinh?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Joan Trivers [10:37 A.M.]\", \"vi\": \"Joan Trivers [10 giờ 37 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I won\'t make it to Oakville station until 1:20.\", \"vi\": \"Tôi sẽ không đến được ga Oakville trước 1 giờ 20 phút.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I\'ll try to get the first bus from there to the office.\", \"vi\": \"Tôi sẽ cố gắng đi chuyến xe buýt đầu tiên từ đó đến văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Yuji Okada [10:39 A.M.]\", \"vi\": \"Yuji Okada [10 giờ 39 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"No need.\", \"vi\": \"Không cần đâu.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I\'ll pick you up.\", \"vi\": \"Tôi sẽ đến đón quý vị.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We\'ll be at the office before 2.\", \"vi\": \"Chúng tôi sẽ có mặt tại văn phòng trước 2 giờ.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Joan Trivers [10:41 A.M.]\", \"vi\": \"Joan Trivers [10 giờ 41 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Great, thank you!\", \"vi\": \"Tuyệt quá, cảm ơn quý vị!\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"But do set up the computer with the presentation.\", \"vi\": \"Tuy nhiên, xin quý vị hãy chuẩn bị sẵn máy tính cùng với bản trình chiếu.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '3a96f5dd-e485-4740-8f22-28af93f9b520';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Kimfor\\nMarketing\\nSolutions\", \"vi\": \"Kimfor\\nTiếp thị\\nGiải pháp\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Thank you for your purchase of Kimfor Marketing Solutions e-mail software.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã mua phần mềm email của Kimfor Marketing Solutions.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We are confident that this product will help you to develop your business.\", \"vi\": \"Chúng tôi tin tưởng rằng sản phẩm này sẽ giúp quý vị phát triển hoạt động kinh doanh của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"As an added bonus, we are pleased to announce that free training is offered for all of our products.\", \"vi\": \"Ngoài ra, chúng tôi rất vui mừng thông báo rằng tất cả các sản phẩm của chúng tôi đều đi kèm với chương trình đào tạo miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"These short but effective online seminars are a great opportunity for businesses that are new to our products to ensure that they are utilizing the software to its full potential.\", \"vi\": \"Các buổi hội thảo trực tuyến ngắn gọn nhưng hiệu quả này là cơ hội tuyệt vời dành cho các doanh nghiệp mới làm quen với sản phẩm của chúng tôi, giúp quý vị đảm bảo rằng mình đang khai thác phần mềm một cách tối đa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our instructors are professionals who have used our tools to grow their own businesses.\", \"vi\": \"Các giảng viên của chúng tôi là những chuyên gia đã sử dụng các công cụ của chúng tôi để phát triển doanh nghiệp của chính họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"For more information and to make a reservation for a seminar, please visit our Web site at kimformarketingsolutions.com/seminarsignup.\", \"vi\": \"Để biết thêm thông tin và đăng ký tham dự hội thảo, xin vui lòng truy cập trang web của chúng tôi tại địa chỉ kimformarketingsolutions.com/seminarsignup.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '3ab484e0-0f8f-4efd-83f8-5ecc056b8035';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"In-home delivery takes approximately one week after an order is shipped from our warehouse.\", \"vi\": \"Dịch vụ giao hàng tận nhà mất khoảng một tuần sau khi đơn hàng được gửi đi từ kho của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The actual time may vary based on the location of your ___135___ and your availability for accepting the item.\", \"vi\": \"Thời gian thực tế có thể thay đổi tùy thuộc vào vị trí của ___135___ bạn và thời gian bạn có thể nhận hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [135]}, {\"en\": \"Vernico Furniture will work with a carrier ___136___ an appointment that is convenient for you.\", \"vi\": \"Vernico Furniture sẽ làm việc với đơn vị vận chuyển ___136___ một cuộc hẹn thuận tiện cho bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [136]}, {\"en\": \"Typical hours are Monday through Friday between 8 A.M. and 5 P.M., ___137___ evening appointments can often be arranged.\", \"vi\": \"Giờ làm việc thông thường là từ thứ Hai đến thứ Sáu trong khoảng từ 8 giờ sáng đến 5 giờ chiều, ___137___ các cuộc hẹn vào buổi tối thường có thể được sắp xếp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [137]}, {\"en\": \"Upon arrival at your home, the item will be placed in the location you desire.\", \"vi\": \"Khi đến nhà bạn, món đồ sẽ được đặt tại vị trí bạn muốn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"___138___ .\", \"vi\": \"___138___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [138]}, {\"en\": \"Assembly is included as well.\", \"vi\": \"Dịch vụ lắp ráp cũng được bao gồm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '3afd48c4-6ac7-4f93-b7ab-bff70877de89';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Country Gardening Today\", \"vi\": \"Nghệ thuật làm vườn nông thôn ngày nay\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Growing plants can be easy.\", \"vi\": \"Việc trồng cây có thể rất đơn giản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"It just takes knowing the right tips and tricks.\", \"vi\": \"Chỉ cần nắm được những mẹo và bí quyết phù hợp là được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"That\'s why our award-winning Country Gardening Today is the most widely read gardening magazine in all of New Zealand.\", \"vi\": \"Đó chính là lý do tại sao tạp chí “Country Gardening Today” – từng đoạt giải thưởng – của chúng tôi là tạp chí về làm vườn được đọc nhiều nhất trên toàn New Zealand.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Most of our readers say they had never planted a single seed before ordering our magazine, and now they take pride in their beautiful flowers and scrumptious vegetables.\", \"vi\": \"Hầu hết độc giả của chúng tôi đều cho biết trước khi đặt mua tạp chí của chúng tôi, họ chưa từng gieo một hạt giống nào, và giờ đây, họ cảm thấy tự hào về những bông hoa xinh đẹp và những loại rau củ ngon miệng của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our articles cover every aspect of gardening, and they are written by expert landscape designers, horticulturalists, and botanists.\", \"vi\": \"Các bài viết của chúng tôi đề cập đến mọi khía cạnh của nghệ thuật làm vườn, và được viết bởi các chuyên gia thiết kế cảnh quan, các nhà làm vườn và các nhà thực vật học.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This fun and practical magazine also offers do-it-yourself landscaping ideas, product recommendations (no ads!), and step-by-step guides.\", \"vi\": \"Tạp chí thú vị và thiết thực này còn mang đến những ý tưởng tự tay thiết kế cảnh quan, các gợi ý về sản phẩm (không có quảng cáo!) cùng các hướng dẫn từng bước cụ thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Don\'t miss this spectacular offer!\", \"vi\": \"Đừng bỏ lỡ ưu đãi đặc biệt này!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Subscribe before the end of February and save 25% off the retail cover price!\", \"vi\": \"Hãy đăng ký trước khi kết thúc tháng Hai để được giảm 25% so với giá bìa bán lẻ!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Just go to www.countrygardeningtoday.com.\", \"vi\": \"Quý vị chỉ cần truy cập vào địa chỉ www.countrygardeningtoday.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '3b394a8a-9f4c-4b34-a348-42f325b0fd78';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.thecentervilletimes.com\", \"vi\": \"http://www.thecentervilletimes.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Centerville Times, June 1, \\\"Music on the Water\\\"\", \"vi\": \"Tờ Centerville Times, ngày 1 tháng 6, “Âm nhạc trên mặt nước”\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The magical melody of a violin wafts into downtown Centerville.\", \"vi\": \"Giai điệu huyền diệu của tiếng vĩ cầm lan tỏa khắp trung tâm thành phố Centerville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The sound of a cello joins in.\", \"vi\": \"Tiếng đàn cello hòa vào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Curious tourists look around, trying to figure out the source of the music.\", \"vi\": \"Các du khách tò mò nhìn ngó xung quanh, cố gắng tìm hiểu nguồn gốc của bản nhạc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"They gradually realize that members of an orchestra are in plain sight, seated on a boat docked in the Centerville harbor.\", \"vi\": \"Họ dần nhận ra rằng các thành viên của dàn nhạc đang ở ngay trước mắt, ngồi trên một chiếc thuyền đang neo đậu tại cảng Centerville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"\\\"Music on the Water\\\" began 30 years ago when Brigitta Carlson had an old cargo boat renovated and then performed the first musical performance from the boat\'s deck.\", \"vi\": \"Chương trình “Music on the Water” ra đời cách đây 30 năm, khi bà Brigitta Carlson cho tu sửa một chiếc tàu chở hàng cũ và sau đó tổ chức buổi biểu diễn âm nhạc đầu tiên ngay trên boong tàu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Today, \\\"Music on the Water,\\\" a chamber orchestra, offers weekend performances on the original boat in the same harbor location.\", \"vi\": \"Hôm nay, dàn nhạc thính phòng “Music on the Water” sẽ mang đến các buổi biểu diễn vào cuối tuần trên chính con thuyền nguyên bản tại cùng vị trí bến cảng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The musicians are currently led by Maestro Arthur Silverman, an acclaimed violinist, who plays in the performances each week.\", \"vi\": \"Hiện tại, dàn nhạc đang được dẫn dắt bởi Nhạc trưởng Arthur Silverman, một nghệ sĩ vĩ cầm nổi tiếng, người trực tiếp tham gia biểu diễn trong các buổi diễn hàng tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"\\\"We have expanded our schedule to offer a record number of concerts—over 50 each year,\\\" explains Maestro Silverman.\", \"vi\": \"\\\"Chúng tôi đã mở rộng lịch trình để tổ chức một số lượng buổi hòa nhạc kỷ lục — hơn 50 buổi mỗi năm,\\\" Nhạc trưởng Silverman giải thích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"\\\"Certain programs are now tailored to specific audiences, like young listeners.\\\"\", \"vi\": \"\\\"Hiện nay, một số chương trình đã được thiết kế riêng cho các đối tượng cụ thể, chẳng hạn như thính giả trẻ.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"\\\"Music on the Water\\\" performs on many Friday and Saturday evenings at 6:00 P.M. Tickets can be purchased online at www.musiconthewater.org.\", \"vi\": \"Chương trình “Music on the Water” diễn ra vào nhiều buổi tối thứ Sáu và thứ Bảy lúc 6 giờ chiều. Quý vị có thể mua vé trực tuyến tại địa chỉ www.musiconthewater.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Family concerts are scheduled on Sundays at 2:00 P.M. No tickets are needed for family concerts, but patrons are encouraged to arrive early to ensure seats are available.\", \"vi\": \"Các buổi hòa nhạc dành cho gia đình được tổ chức vào Chủ nhật lúc 2 giờ chiều. Quý vị không cần vé để tham dự các buổi hòa nhạc dành cho gia đình, nhưng chúng tôi khuyến khích quý vị đến sớm để đảm bảo có chỗ ngồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"http://www.thecentervilletimes.com/musiconthewater/comments\", \"vi\": \"http://www.thecentervilletimes.com/musiconthewater/comments\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I have enjoyed \\\"Music on the Water\\\" ever since I was a child.\", \"vi\": \"Từ khi còn nhỏ, tôi đã rất yêu thích chương trình “Music on the Water”.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"In fact, I will never forget listening to the founder\'s very first performance, with the melody of her flute floating up to my family\'s third-floor apartment facing the harbor.\", \"vi\": \"Thực ra, tôi sẽ không bao giờ quên khoảnh khắc được lắng nghe buổi biểu diễn đầu tiên của người sáng lập, khi giai điệu từ cây sáo của bà văng vẳng bay lên căn hộ tầng ba của gia đình tôi, nơi nhìn ra bến cảng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"When I was a little older, I used to save my coins so that I could purchase my own ticket to a concert on the boat.\", \"vi\": \"Khi lớn hơn một chút, tôi thường tiết kiệm những đồng xu của mình để có thể tự mua vé đi xem buổi hòa nhạc trên thuyền.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"\\\"Music on the Water\\\" has had a wonderful impact on the harbor area.\", \"vi\": \"Chương trình “Âm nhạc trên mặt nước” đã mang lại những tác động tích cực cho khu vực cảng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I wonder if The Centerville Times would consider publishing a piece on the history of this neighborhood, which I am still proud to call home.\", \"vi\": \"Tôi tự hỏi liệu tờ The Centerville Times có cân nhắc đăng tải một bài viết về lịch sử của khu phố này hay không, nơi mà tôi vẫn luôn tự hào coi là quê hương của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Roberto Padilla\", \"vi\": \"Roberto Padilla\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '3be4c392-3c4e-485a-9f91-f7d939625340';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Wayan Cahyo\", \"vi\": \"Gửi: Wayan Cahyo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Adi Athletic Club\", \"vi\": \"Từ: Câu lạc bộ Thể thao Adi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 10\", \"vi\": \"Ngày: 10 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Acknowledgment\", \"vi\": \"Chủ đề: Lời cảm ơn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Cahyo,\", \"vi\": \"Kính gửi ông Cahyo,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This is to acknowledge receipt of your letter dated March 5.\", \"vi\": \"Thư này nhằm xác nhận đã nhận được thư của quý vị ngày 5 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Your request has been processed.\", \"vi\": \"Yêu cầu của quý vị đã được xử lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Your athletic club membership is scheduled to end on the date indicated below.\", \"vi\": \"Thẻ thành viên câu lạc bộ thể thao của quý vị dự kiến sẽ hết hạn vào ngày được ghi dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"You are welcome to use our facilities and attend group classes until then.\", \"vi\": \"Cho đến lúc đó, quý vị hoàn toàn có thể sử dụng các tiện nghi của chúng tôi và tham gia các lớp học nhóm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please be sure to clear out your locker of any personal belongings by this deadline.\", \"vi\": \"Xin vui lòng đảm bảo dọn sạch mọi vật dụng cá nhân ra khỏi tủ của quý vị trước thời hạn này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Termination effective: March 31\", \"vi\": \"Ngày chấm dứt có hiệu lực: 31 tháng 3\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Xin cảm ơn.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Jordi Sommers, Customer Service Representative\", \"vi\": \"Jordi Sommers, Nhân viên Dịch vụ Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '3c1a84b3-83e8-4cbf-8536-45e4eceb362f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Travel with Confidence—the Simple Trip Way!\", \"vi\": \"Du lịch với sự tự tin — theo phong cách Simple Trip!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Does your travel plan include taking one or more flights?\", \"vi\": \"Kế hoạch du lịch của quý vị có bao gồm một hoặc nhiều chuyến bay không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Save time and avoid inconvenience with Simple Trip.\", \"vi\": \"Hãy tiết kiệm thời gian và tránh những rắc rối với Simple Trip.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Recommended by leading companies in the travel industry, the award-winning Simple Trip application allows Web check-in at the airport and keeps you up-to-date regarding local weather conditions and any changes to departure and arrival times.\", \"vi\": \"Được các công ty hàng đầu trong ngành du lịch khuyến nghị, ứng dụng Simple Trip từng đoạt giải thưởng cho phép quý vị làm thủ tục trực tuyến tại sân bay và luôn cập nhật cho quý vị về tình hình thời tiết tại địa phương cũng như mọi thay đổi liên quan đến giờ khởi hành và giờ đến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Download Simple Trip from any app store onto your mobile phone.\", \"vi\": \"Hãy tải ứng dụng Simple Trip từ bất kỳ cửa hàng ứng dụng nào về điện thoại di động của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Simple Trip is completely secure, with multiple layers of encryption to keep your personal information hidden from hackers.\", \"vi\": \"Simple Trip hoàn toàn an toàn, với nhiều lớp mã hóa nhằm bảo vệ thông tin cá nhân của quý vị khỏi sự xâm nhập của tin tặc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Once your documentation has been successfully loaded into the app, Simple Trip provides you with digital passes that can be scanned at security checkpoints, check-in kiosks, and boarding gates.\", \"vi\": \"Sau khi các tài liệu của quý khách đã được tải thành công vào ứng dụng, Simple Trip sẽ cung cấp cho quý khách các thẻ lên máy bay điện tử có thể được quét tại các điểm kiểm tra an ninh, quầy làm thủ tục tự động và cửa lên máy bay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Bypass the ticket counter and check in to your flight through the app.\", \"vi\": \"Quý vị không cần phải đến quầy bán vé mà có thể làm thủ tục lên chuyến bay của mình thông qua ứng dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Stay up-to-date with the latest entry requirements at your destination.\", \"vi\": \"Hãy thường xuyên cập nhật các yêu cầu nhập cảnh mới nhất tại điểm đến của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Make your journey a breeze with Simple Trip!\", \"vi\": \"Hãy biến chuyến đi của quý vị trở nên thật dễ dàng cùng Simple Trip!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '3c44ce24-878f-4445-ab44-2f1560509c73';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Product - Revenue - Notes\", \"vi\": \"Sản phẩm - Doanh thu - Ghi chú\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Coffee, whole bean, one-pound bags - $14,000 - Overall, sales revenue was higher. Bags of whole-bean Misty Heights Blend were a top seller, bringing in just over $3,000.\", \"vi\": \"Cà phê hạt nguyên hạt, đóng gói theo túi 1 pound – 14.000 đô la – Nhìn chung, doanh thu bán hàng đã tăng cao hơn. Các túi cà phê hạt nguyên hạt Misty Heights Blend là mặt hàng bán chạy nhất, mang lại doanh thu hơn 3.000 đô la.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Coffee, prepared drinks - $18,200 - A number of drinks were not offered while the espresso machine was being serviced. Sales should recover in April.\", \"vi\": \"Cà phê, đồ uống pha chế - 18.200 USD - Một số loại đồ uống đã không được phục vụ trong thời gian máy pha cà phê espresso đang được bảo trì. Doanh số bán hàng dự kiến sẽ phục hồi vào tháng Tư.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Tea, prepared drinks - $5,500 - Sales are comparable with previous months.\", \"vi\": \"Trà, đồ uống pha chế – 5.500 USD – Doanh số bán hàng tương đương với các tháng trước.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Bottled drinks - $2,200 - Sales are comparable with previous months.\", \"vi\": \"Đồ uống đóng chai - 2.200 đô la - Doanh số bán hàng tương đương với các tháng trước.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Baked goods - $3,400 - This is a 7 percent increase from last month.\", \"vi\": \"Các sản phẩm bánh kẹo - 3.400 đô la - Con số này tăng 7% so với tháng trước.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Retail (nonperishable goods) - $750 - Placid Moon Coffee mugs are still out of stock as our vendor has not yet fulfilled our order.\", \"vi\": \"Bán lẻ (hàng hóa không dễ hư hỏng) - 750 đô la - Các cốc cà phê Placid Moon hiện vẫn đang hết hàng do nhà cung cấp của chúng tôi chưa giao hàng theo đơn đặt hàng.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"March Promotion\", \"vi\": \"Chương trình khuyến mãi tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Customer loyalty program - N/A - Few loyalty discount cards were distributed to customers this month. We should better train staff in promoting this benefit.\", \"vi\": \"Chương trình khách hàng thân thiết - Không áp dụng - Trong tháng này, số lượng thẻ giảm giá dành cho khách hàng thân thiết được phát cho khách hàng còn rất ít. Chúng ta cần đào tạo nhân viên kỹ lưỡng hơn về việc quảng bá lợi ích này.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Placid Moon Coffee\", \"vi\": \"Cà phê Placid Moon\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"March Sales Report—Prepared April 4 by Cora Lin, Store Manager\", \"vi\": \"Báo cáo doanh số tháng 3 — Được lập ngày 4 tháng 4 bởi Cora Lin, Quản lý cửa hàng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"In-Store Sales of All Products\", \"vi\": \"Bán hàng tại cửa hàng đối với tất cả các sản phẩm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To: coralin@placidmooncoffee.com\", \"vi\": \"Gửi tới: coralin@placidmooncoffee.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"From: tyrellharris@placidmooncoffee.com\", \"vi\": \"Nguồn: tyrellharris@placidmooncoffee.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date: April 4, 6:23 P.M.\", \"vi\": \"Ngày: 4 tháng 4, 6 giờ 23 phút chiều\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Subject: Re: March sales report\", \"vi\": \"Chủ đề: Trả lời: Báo cáo doanh số tháng 3\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thank you for promptly submitting your March report.\", \"vi\": \"Xin cảm ơn quý vị đã nhanh chóng gửi báo cáo tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I\'m pleased with the strong sales of the new whole-bean product we introduced last month.\", \"vi\": \"Tôi rất hài lòng với kết quả bán hàng khả quan của sản phẩm hạt cà phê nguyên hạt mới mà chúng tôi đã ra mắt vào tháng trước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Let\'s keep a close eye on sales of this coffee blend through April.\", \"vi\": \"Chúng ta hãy theo dõi sát sao doanh số bán hàng của loại cà phê pha trộn này trong suốt tháng Tư.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"We may be able to add it to our regular lineup.\", \"vi\": \"Chúng tôi có thể sẽ đưa sản phẩm này vào danh mục sản phẩm thường xuyên của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I like your suggestion regarding the customer loyalty program.\", \"vi\": \"Tôi rất thích đề xuất của quý vị về chương trình khách hàng thân thiết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"In addition, I propose putting up a poster advertising the cards by the registers and another one in the employee lounge.\", \"vi\": \"Ngoài ra, tôi đề xuất treo một tấm áp phích quảng cáo các thẻ này bên cạnh các quầy thu ngân và một tấm khác tại phòng nghỉ của nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Please inform me at the end of the month if these efforts have an impact.\", \"vi\": \"Xin vui lòng thông báo cho tôi vào cuối tháng xem những nỗ lực này có mang lại kết quả hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Finally, I have good news to share.\", \"vi\": \"Cuối cùng, tôi có một tin vui muốn chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Yukihiro Asakawa began serving our Bold Macaw variety at his flagship restaurant in December, and he now wants Placid Moon to be the exclusive provider for all his restaurants.\", \"vi\": \"Ông Yukihiro Asakawa đã bắt đầu phục vụ món “Bold Macaw” tại nhà hàng chính của mình vào tháng 12, và hiện ông mong muốn Placid Moon trở thành nhà cung cấp độc quyền cho tất cả các nhà hàng của ông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"This expansion of our business is all thanks to you, since you introduced Mr. Asakawa to our coffee not long ago.\", \"vi\": \"Sự mở rộng hoạt động kinh doanh của chúng tôi lần này hoàn toàn là nhờ quý vị, bởi chính quý vị đã giới thiệu ông Asakawa với sản phẩm cà phê của chúng tôi cách đây không lâu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Tyrell Harris\", \"vi\": \"Tyrell Harris\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Placid Moon Coffee, Owner\", \"vi\": \"Placid Moon Coffee, Chủ sở hữu\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '3c67c8b3-a612-42e8-89b0-e4cf6ff5cb80';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"ORANGE LIGHT GYM\", \"vi\": \"PHÒNG TẬP THỂ DỤC ORANGE LIGHT\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"GRAND OPENING WEEK\", \"vi\": \"TUẦN LỄ KHAI TRƯƠNG HOÀNH TRÁNG\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Orange Light Gym is coming to Singapore!\", \"vi\": \"Orange Light Gym sắp có mặt tại Singapore!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Join us as we open our newest and best gym in April.\", \"vi\": \"Hãy cùng chúng tôi tham dự lễ khai trương phòng tập thể dục mới nhất và tốt nhất của chúng tôi vào tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"This will be our first location in Singapore, and we will add two other locations later this year.\", \"vi\": \"Đây sẽ là cơ sở đầu tiên của chúng tôi tại Singapore, và chúng tôi sẽ mở thêm hai cơ sở nữa vào cuối năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"10 percent off for new Orange Light Gym members who sign up during our Orchard Road grand opening event from 4 April until 8 April\", \"vi\": \"Giảm giá 10% dành cho các thành viên mới của Orange Light Gym đăng ký tham gia trong khuôn khổ sự kiện khai trương hoành tráng tại Orchard Road, diễn ra từ ngày 4 tháng 4 đến ngày 8 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Singapore bodybuilding legend Ronny Cho appearing on 5 April\", \"vi\": \"Huyền thoại thể hình Singapore Ronny Cho sẽ xuất hiện vào ngày 5 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"World-famous trainer Lina Sitaman appearing on 6 April\", \"vi\": \"Huấn luyện viên nổi tiếng toàn cầu Lina Sitaman sẽ xuất hiện vào ngày 6 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"ORANGE LIGHT GYM · 1140 Orchard Road · Singapore\", \"vi\": \"ORANGE LIGHT GYM · 1140 Orchard Road · Singapore\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Orange Light Gym Marina South - 183 Reviews\", \"vi\": \"Orange Light Gym Marina South - 183 đánh giá\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"2 October\", \"vi\": \"Ngày 2 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Max Halle\", \"vi\": \"Max Halle\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"★★★\", \"vi\": \"★★★\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I have been a regular Orange Light Gym member for ten years and generally like their service.\", \"vi\": \"Tôi đã là hội viên thường xuyên của Orange Light Gym được mười năm và nhìn chung rất hài lòng với dịch vụ của họ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I live in Dubai but travel to Singapore for work regularly, so it\'s great to belong to a gym with locations in both countries!\", \"vi\": \"Tôi hiện đang sinh sống tại Dubai nhưng thường xuyên phải sang Singapore công tác, vì vậy thật tuyệt vời khi được là thành viên của một câu lạc bộ thể hình có chi nhánh tại cả hai quốc gia!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The Marina South gym in Singapore is very clean and well designed, but there are two areas that need improvement.\", \"vi\": \"Phòng tập thể dục Marina South tại Singapore rất sạch sẽ và được thiết kế hợp lý, tuy nhiên vẫn có hai điểm cần được cải thiện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"There are not enough machines, especially compared to the much larger Orchard Road location.\", \"vi\": \"Số lượng máy móc hiện tại chưa đủ, đặc biệt là so với chi nhánh tại đường Orchard Road, nơi có quy mô lớn hơn rất nhiều.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Also, I have visited the gym about ten times and on nearly half of those occasions, the pool was not available for use.\", \"vi\": \"Ngoài ra, tôi đã đến phòng tập thể dục khoảng mười lần và trong gần một nửa số lần đó, bể bơi không thể sử dụng được.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I will still use this gym because of the global membership, but I hope they address the cause of the pool closures.\", \"vi\": \"Tôi vẫn sẽ tiếp tục tập luyện tại phòng tập này nhờ chế độ thành viên toàn cầu, nhưng tôi hy vọng họ sẽ giải quyết triệt để nguyên nhân dẫn đến việc đóng cửa bể bơi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"To: Sam Adawi\", \"vi\": \"Người gửi: Sam Adawi\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"From: Ani Wayanti\", \"vi\": \"Từ: Ani Wayanti\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Date: 14 October\", \"vi\": \"Ngày: 14 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Subject: Stokner Service\", \"vi\": \"Chủ đề: Dịch vụ Stokner\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Mr. Adawi,\", \"vi\": \"Ông Adawi\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I know we have a one-year contract with Stokner Service, but I am very concerned.\", \"vi\": \"Tôi biết chúng ta có hợp đồng một năm với Công ty Dịch vụ Stokner, nhưng tôi rất lo ngại.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"The problems that we have had at the Orange Light Gyms in Singapore are due to improper maintenance.\", \"vi\": \"Các vấn đề mà chúng tôi đã gặp phải tại các phòng tập Orange Light Gyms ở Singapore là do việc bảo trì không đúng cách.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Quite simply, I don\'t think the workers that Stokner employs are trained well enough to do their jobs.\", \"vi\": \"Nói một cách đơn giản, tôi không cho rằng các nhân viên mà ông Stokner tuyển dụng đã được đào tạo đủ tốt để thực hiện công việc của mình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Can we meet to discuss this?\", \"vi\": \"Chúng ta có thể gặp nhau để thảo luận về vấn đề này không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"The sooner we resolve this issue, the better.\", \"vi\": \"Chúng ta giải quyết vấn đề này càng sớm thì càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Ms. Wayanti\", \"vi\": \"Bà Wayanti\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Regional Manager\", \"vi\": \"Giám đốc khu vực\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Orange Light Gym\", \"vi\": \"Phòng tập thể dục Orange Light\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}]' WHERE `id` = '3c77ef95-060e-4f90-a265-16a61684fabe';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Watford Shredding Day\", \"vi\": \"Ngày xử lý tài liệu tại Watford\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Do you need to safely dispose of piles of confidential paperwork?\", \"vi\": \"Quý vị có cần xử lý một cách an toàn những đống tài liệu mật không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Come to Watford Community Shredding Day on April 8 from 8:00 A.M. to 11:00 A.M.\", \"vi\": \"Kính mời quý vị tham dự Ngày hủy tài liệu cộng đồng tại Watford vào ngày 8 tháng 4, từ 8 giờ sáng đến 11 giờ sáng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"A number of Security Too shredders will be conveniently located behind the Watford municipal parking garage.\", \"vi\": \"Một số máy hủy tài liệu của Security Too sẽ được đặt tại vị trí thuận tiện phía sau bãi đỗ xe công cộng thành phố Watford.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Bring any unneeded bank statements, tax documents, and bills.\", \"vi\": \"Xin vui lòng mang theo các bản sao kê ngân hàng, tài liệu thuế và hóa đơn mà quý vị không còn cần đến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"They will be securely shredded and recycled on the spot.\", \"vi\": \"Các tài liệu này sẽ được xé nhỏ một cách an toàn và tái chế ngay tại chỗ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please note that the event is open to Watford Township residents only, and there is a five-kilo limit per household.\", \"vi\": \"Xin lưu ý rằng sự kiện này chỉ dành riêng cho cư dân của Watford Township, và mỗi hộ gia đình chỉ được nhận tối đa năm kilôgam.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Security Too representatives will be on hand to talk about ways to protect your private information.\", \"vi\": \"Các đại diện của Security Too sẽ có mặt tại đây để trao đổi về các biện pháp bảo vệ thông tin cá nhân của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Community Shredding Day is brought to you by radio station 82.9 WQYX and Security Too.\", \"vi\": \"Ngày tiêu hủy tài liệu cộng đồng do đài phát thanh 82.9 WQYX và Security Too tổ chức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"For more information, visit www.watfordtownship/shreddingday.org.\", \"vi\": \"Để biết thêm thông tin, vui lòng truy cập trang web www.watfordtownship/shreddingday.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '3cbfcd60-6c18-44d5-bdbc-3b2c162ba288';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Barbara Treloar <btreloar@questor.ca>\", \"vi\": \"Gửi tới: Barbara Treloar <btreloar@questor.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Amy Dunstan <adunstan@bluetern.co.nz>\", \"vi\": \"Từ: Amy Dunstan <adunstan@bluetern.co.nz>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Cover\", \"vi\": \"Chủ đề: Bìa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 20 April\", \"vi\": \"Ngày: 20 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Barbara:\", \"vi\": \"Kính gửi bà Barbara:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"You will be receiving an e-mail from the Blue Tern marketing team before the end of the week.\", \"vi\": \"Quý vị sẽ nhận được một email từ đội ngũ tiếp thị của Blue Tern trước khi kết thúc tuần này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The e-mail describes the marketing process, and it gives you a link to an online questionnaire for authors.\", \"vi\": \"Bức thư điện tử này trình bày về quy trình tiếp thị và cung cấp cho quý vị một liên kết đến bảng câu hỏi trực tuyến dành cho các tác giả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Although the design team will have the final say on your book\'s cover, you do have some input.\", \"vi\": \"Mặc dù đội ngũ thiết kế sẽ có quyền quyết định cuối cùng về bìa cuốn sách của quý vị, nhưng quý vị vẫn có thể đóng góp ý kiến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Do you feel strongly about anything that you do or do not want to see on the cover?\", \"vi\": \"Quý vị có ý kiến mạnh mẽ nào về những nội dung mà quý vị muốn hoặc không muốn thấy xuất hiện trên bìa không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please let me know.\", \"vi\": \"Xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Amy Dunstan\", \"vi\": \"Amy Dunstan\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Senior Developmental Editor\", \"vi\": \"Biên tập viên cao cấp phụ trách phát triển nội dung\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '3cef2333-15f4-4318-bc5d-1c3eaf6b0307';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Jee-Wah Cho <cho8876@sunmail.com>\", \"vi\": \"Đến: Jee-Wah Cho <cho8876@sunmail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Ken Belfant <kenbelfant@fluffytimeindustries.com>\", \"vi\": \"Từ: Ken Belfant <kenbelfant@fluffytimeindustries.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 6 April\", \"vi\": \"Ngày: 6 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Recipe contest\", \"vi\": \"Chủ đề: Cuộc thi nấu ăn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Cho,\", \"vi\": \"Kính gửi chị Cho,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for ------- (139) your interesting recipe that uses our low-fat, sugar-free Fluffy Time Whipped Topping.\", \"vi\": \"Cảm ơn chị đã ------- (139) công thức món ăn thú vị của mình, trong đó sử dụng sản phẩm kem đánh bông ít béo, không đường Fluffy Time Whipped Topping của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [139]}, {\"en\": \"------- (140) has been entered into our upcoming contest.\", \"vi\": \"------- (140) đã được đăng ký tham gia cuộc thi sắp tới của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [140]}, {\"en\": \"The winning recipes will appear on our product\'s packaging.\", \"vi\": \"Các công thức chiến thắng sẽ xuất hiện trên bao bì sản phẩm của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"------- (141).\", \"vi\": \"------- (141).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [141]}, {\"en\": \"In the meantime, I will be sending you a coupon for 25 percent off your next purchase of any Fluffy Time product via a separate e-mail that you should receive ------- (142).\", \"vi\": \"Trong thời gian này, tôi sẽ gửi cho chị một phiếu giảm giá 25 phần trăm cho lần mua hàng tiếp theo đối với bất kỳ sản phẩm Fluffy Time nào qua một email riêng biệt mà chị sẽ nhận được ------- (142).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [142]}, {\"en\": \"We are so glad you enjoy our products.\", \"vi\": \"Chúng tôi rất vui vì chị yêu thích các sản phẩm của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Best of luck in the contest!\", \"vi\": \"Chúc chị gặp nhiều may mắn trong cuộc thi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"With gratitude,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Ken Belfant, Promotions Coordinator\", \"vi\": \"Ken Belfant, Điều phối viên Chương trình Khuyến mãi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Fluffy Time Industries\", \"vi\": \"Fluffy Time Industries\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '3e15cb76-52c2-4505-b118-f32317d4fb08';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Washington State to Introduce Its Very Own Apple\", \"vi\": \"Bang Washington sẽ giới thiệu giống táo riêng của mình\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"By Julia Richards for The Agri Monthly\", \"vi\": \"Bài viết của Julia Richards đăng trên tạp chí The Agri Monthly\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Scientists at Scales University reported last month that they have completed the development of the \\\"Shiner Crisp,\\\" the first apple that Washington state farmers will have trademarked all to themselves.\", \"vi\": \"Các nhà khoa học tại Đại học Scales đã báo cáo vào tháng trước rằng họ đã hoàn tất việc phát triển giống táo “Shiner Crisp” – giống táo đầu tiên mà các nông dân bang Washington sẽ sở hữu độc quyền nhãn hiệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The first Shiner Crisp is expected to become available to consumers as early as next year.\", \"vi\": \"Dự kiến, sản phẩm Shiner Crisp đầu tiên sẽ được đưa ra thị trường sớm nhất là vào năm tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Apple breeders design new apples especially to better compete with such traditional apple varieties as Reds and Juiceys.\", \"vi\": \"Các nhà lai tạo táo đã thiết kế ra những giống táo mới nhằm cạnh tranh hiệu quả hơn với các giống táo truyền thống như Reds và Juiceys.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The development process involves a considerable investment of time and money in repeated taste tests for their new fruits.\", \"vi\": \"Quá trình phát triển đòi hỏi một khoản đầu tư đáng kể về thời gian và tiền bạc vào các đợt thử nếm lặp đi lặp lại đối với các loại trái cây mới của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Whereas Reds and Juiceys average $1.29 per pound, new types of apples (such as the hugely popular Branburs and Honey-Sweets) are raking in at least three times as much.\", \"vi\": \"Trong khi giá trung bình của các giống táo Reds và Juiceys là 1,29 đô la mỗi pound, thì các giống táo mới (chẳng hạn như Branburs và Honey-Sweets – những giống đang rất được ưa chuộng) lại có giá cao gấp ít nhất ba lần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"These additions have major long-term impacts on the market, too.\", \"vi\": \"Những yếu tố mới này cũng có những tác động lâu dài đáng kể đến thị trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Two decades ago, Reds and Juiceys comprised over 50 percent of all apple sales; now their sales are less than 25 percent of the market.\", \"vi\": \"Hai thập kỷ trước, các giống táo Reds và Juiceys chiếm hơn 50 phần trăm tổng doanh số bán táo; hiện nay, doanh số của hai giống này chỉ chiếm chưa đến 25 phần trăm thị trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"It is no wonder that apple breeders are racing to come up with the next popular apple!\", \"vi\": \"Không có gì ngạc nhiên khi các nhà lai tạo táo đang đua nhau để tạo ra giống táo được ưa chuộng tiếp theo!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '3e37bc55-1b9c-4cb2-b266-596af726b322';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Thank you for sending me another of your company\'s food blenders in exchange for my product feedback.\", \"vi\": \"Xin chân thành cảm ơn quý công ty đã gửi tặng tôi một chiếc máy xay thực phẩm khác của quý công ty để đổi lấy phản hồi của tôi về sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The motor of the Lumtik IB-8900 seems to be a bit more powerful than the motors of the two blenders I reviewed previously.\", \"vi\": \"Động cơ của máy xay Lumtik IB-8900 dường như mạnh hơn một chút so với động cơ của hai chiếc máy xay mà tôi đã đánh giá trước đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This one does a great job, especially on the high-speed setting.\", \"vi\": \"Chiếc máy này hoạt động rất hiệu quả, đặc biệt là ở chế độ tốc độ cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"One thing that is disappointing is that the measurement lines were not easy to decipher and seem to fade and become less legible after several washings.\", \"vi\": \"Một điều đáng tiếc là các vạch đo không dễ nhận biết và dường như bị mờ dần, trở nên khó đọc hơn sau vài lần giặt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"This may be a problem with the imprinting on the device.\", \"vi\": \"Đây có thể là vấn đề liên quan đến phần in trên thiết bị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The measurement lines need to be engraved or permanently marked to be clearer.\", \"vi\": \"Các vạch đo cần được khắc hoặc đánh dấu vĩnh viễn để dễ nhìn hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Needless to say, this is important for recipes that require precisely measured ingredients.\", \"vi\": \"Không cần phải nói, điều này rất quan trọng đối với các công thức nấu ăn đòi hỏi phải đo lường nguyên liệu một cách chính xác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Hannah Daley\", \"vi\": \"Hannah Daley\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '3e825218-7135-4811-a7ff-5981b4a6dcc4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Staff <allstaff@sielendgroup.co.za>\", \"vi\": \"Gửi: Toàn thể nhân viên <allstaff@sielendgroup.co.za>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Orson Stanley <ostanley@sielendgroup.co.za>\", \"vi\": \"Từ: Orson Stanley <ostanley@sielendgroup.co.za>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 1 February\", \"vi\": \"Ngày: 1 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Farewell party\", \"vi\": \"Chủ đề: Buổi tiệc chia tay\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Colleagues,\", \"vi\": \"Kính gửi các đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As you may have heard, our friend and colleague Gerard Clegg will be leaving Sielend Group at the end of February after 22 years.\", \"vi\": \"Có lẽ quý vị đã nghe nói rằng, người bạn và đồng nghiệp của chúng ta, ông Gerard Clegg, sẽ rời Tập đoàn Sielend vào cuối tháng 2 sau 22 năm công tác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"During his tenure as CFO, Gerard implemented state-of-the-art budget-management software and presided over a threefold growth in company revenues.\", \"vi\": \"Trong thời gian đảm nhiệm chức vụ Giám đốc Tài chính (CFO), ông Gerard đã triển khai phần mềm quản lý ngân sách tiên tiến nhất và góp phần đưa doanh thu của công ty tăng gấp ba lần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Gerard has expressed mixed feelings about departing but says that he plans to work part-time alongside his brother at the local firm Chartera Consultants.\", \"vi\": \"Ông Gerard đã bày tỏ những cảm xúc lẫn lộn về việc rời đi, nhưng cho biết ông dự định sẽ làm việc bán thời gian cùng với anh trai mình tại công ty địa phương Chartera Consultants.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Gerard will also continue to be involved with youth five hours a week at the nonprofit Reach-Out Durban League.\", \"vi\": \"Gerard cũng sẽ tiếp tục dành năm giờ mỗi tuần để làm việc với các bạn trẻ tại tổ chức phi lợi nhuận Reach-Out Durban League.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please join us in attending Gerard\'s farewell party at 7:00 P.M. on Friday, 28 February, at Longres Ballroom here in Durban.\", \"vi\": \"Kính mời quý vị cùng tham dự tiệc chia tay của Gerard vào lúc 7 giờ tối Thứ Sáu, ngày 28 tháng 2, tại sảnh tiệc Longres ở Durban.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Light refreshments will be served, and the company president will present Gerard with a plaque to show our appreciation for his many contributions to the company.\", \"vi\": \"Tại buổi lễ sẽ có phục vụ một số món ăn nhẹ, và Chủ tịch công ty sẽ trao tặng ông Gerard một tấm bảng kỷ niệm để bày tỏ lòng biết ơn của chúng tôi đối với những đóng góp to lớn của ông dành cho công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"If you plan to attend, please e-mail my assistant Seojung Lee to let her know.\", \"vi\": \"Nếu quý vị có ý định tham dự, xin vui lòng gửi email cho trợ lý của tôi, cô Seojung Lee, để thông báo cho cô ấy biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We would like to know in advance how many people to expect.\", \"vi\": \"Chúng tôi mong muốn được biết trước số lượng người tham dự dự kiến là bao nhiêu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We look forward to seeing you there.\", \"vi\": \"Chúng tôi rất mong được gặp quý vị tại đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Orson Stanley\", \"vi\": \"Orson Stanley\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Chartera Consultants\", \"vi\": \"Công ty Tư vấn Chartera\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"http://www.chartera.co.za  —  □  ✕\", \"vi\": \"http://www.chartera.co.za  —  □  ✕\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Chartera Consultants offers professional financial guidance and expert accounting services.\", \"vi\": \"Chartera Consultants cung cấp các dịch vụ tư vấn tài chính chuyên nghiệp và dịch vụ kế toán chuyên sâu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Staff News\", \"vi\": \"Tin tức về đội ngũ nhân viên\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We are happy to introduce Chartera Consultants\' newest team member, Gerard Clegg.\", \"vi\": \"Chúng tôi hân hạnh giới thiệu thành viên mới nhất của Chartera Consultants, ông Gerard Clegg.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Mr. Clegg has a wealth of experience in all aspects of corporate finance.\", \"vi\": \"Ông Clegg có nhiều năm kinh nghiệm trong tất cả các lĩnh vực của tài chính doanh nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"For over two decades he worked as CFO for a successful medical equipment manufacturing firm.\", \"vi\": \"Trong hơn hai thập kỷ, ông đã đảm nhiệm chức vụ Giám đốc Tài chính tại một công ty sản xuất thiết bị y tế thành công.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Mr. Clegg holds a master of business administration in finance from Stolz Institute.\", \"vi\": \"Ông Clegg có bằng Thạc sĩ Quản trị Kinh doanh chuyên ngành Tài chính do Viện Stolz cấp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"About Us\", \"vi\": \"Giới thiệu về chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Services\", \"vi\": \"Dịch vụ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"News\", \"vi\": \"Tin tức\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Reach-Out Durban League\'s Annual Fundraiser\", \"vi\": \"Chương trình gây quỹ thường niên của Liên đoàn Reach-Out Durban\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Saturday, 14 July, at 10 A.M.\", \"vi\": \"Thứ Bảy, ngày 14 tháng 7, lúc 10 giờ sáng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Join us for a fun-filled day and help raise money for an important cause at Paxton Community Center.\", \"vi\": \"Hãy cùng chúng tôi tham gia một ngày tràn ngập niềm vui và chung tay gây quỹ cho một mục đích ý nghĩa tại Trung tâm Cộng đồng Paxton.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Compete for a number of prizes, including the top prize, a dinner for two at the award-winning Port St. Johns Restaurant.\", \"vi\": \"Hãy tham gia tranh tài để giành lấy nhiều giải thưởng, trong đó có giải nhất là một bữa tối dành cho hai người tại nhà hàng Port St. Johns – nhà hàng từng đoạt giải thưởng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Last year\'s event raised over ZAR20,000 toward our critical mission.\", \"vi\": \"Sự kiện năm ngoái đã quyên góp được hơn 20.000 ZAR để hỗ trợ sứ mệnh quan trọng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Reach-Out Durban League is a 100% volunteer-run organisation, and all event proceeds go toward providing academic development opportunities to Durban area youth.\", \"vi\": \"Reach-Out Durban League là một tổ chức được điều hành hoàn toàn bởi các tình nguyện viên, và toàn bộ số tiền thu được từ các sự kiện sẽ được dùng để tạo cơ hội phát triển học tập cho thanh thiếu niên khu vực Durban.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Register for our annual fundraiser at www.rodl.org.za.\", \"vi\": \"Quý vị vui lòng đăng ký tham gia sự kiện gây quỹ thường niên của chúng tôi tại địa chỉ www.rodl.org.za.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}]' WHERE `id` = '3e9d5a7e-a984-4921-91c1-9fbe486023f2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dear Small-Business Owner:\", \"vi\": \"Kính gửi Chủ doanh nghiệp nhỏ:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Do you change your opening and closing times depending on the season?\", \"vi\": \"Bạn có thay đổi giờ mở cửa và đóng cửa tùy thuộc vào mùa trong năm không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"According to market research, a quarter of all small businesses periodically ______[143] their operating hours.\", \"vi\": \"Theo nghiên cứu thị trường, một phần tư tổng số doanh nghiệp nhỏ định kỳ ______[143] giờ hoạt động của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [143]}, {\"en\": \"However, such changes are not always accurately reflected in the search engine results and on the many Web sites that show your operating hours to your customers.\", \"vi\": \"Tuy nhiên, những thay đổi như vậy không phải lúc nào cũng được phản ánh chính xác trên kết quả của công cụ tìm kiếm và trên nhiều trang web hiển thị giờ hoạt động của bạn cho khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Inaccurate information can lead to customer frustration, which can drive them to do business with your competitors.\", \"vi\": \"Thông tin không chính xác có thể dẫn đến sự thất vọng của khách hàng, điều này có thể thúc đẩy họ chuyển sang giao dịch với các đối thủ cạnh tranh của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[144].\", \"vi\": \"______[144].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [144]}, {\"en\": \"One of our services is designed to help you monitor ______[145] your operating hours are being shown on the Web.\", \"vi\": \"Một trong những dịch vụ của chúng tôi được thiết kế để giúp bạn theo dõi ______[145] giờ hoạt động của bạn đang được hiển thị trên mạng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [145]}, {\"en\": \"To learn more about our tools and services, please see the enclosed brochure.\", \"vi\": \"Để tìm hiểu thêm về các công cụ và dịch vụ của chúng tôi, vui lòng xem tài liệu đính kèm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We would be happy to work with you ______[146] your business\'s opportunities.\", \"vi\": \"Chúng tôi rất vui được hợp tác với bạn ______[146] các cơ hội kinh doanh của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [146]}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Richard N. Batterman\", \"vi\": \"Richard N. Batterman\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Account Representative\", \"vi\": \"Đại diện Quản lý Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Muros Solutions\", \"vi\": \"Muros Solutions\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Enclosure\", \"vi\": \"Tài liệu đính kèm\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '3f052e58-11f8-43be-b532-869934c22f3c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.coltonhotels.com.au/accommodations\", \"vi\": \"http://www.coltonhotels.com.au/accommodations\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The Melbourne Colton Hotel is pleased to announce that construction of the new Yarra River wing is now completed.\", \"vi\": \"Khách sạn Melbourne Colton hân hạnh thông báo rằng công trình xây dựng khu mới hướng ra sông Yarra hiện đã hoàn tất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"This new section offers extended-stay apartments, which are ideal for executives who are relocating or for people on company travel for more than a week.\", \"vi\": \"Khu vực mới này cung cấp các căn hộ dành cho lưu trú dài hạn, rất lý tưởng cho các giám đốc điều hành đang chuyển công tác hoặc những người đi công tác của công ty trong thời gian trên một tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We offer furnished one- and two-bedroom apartments with a living room, work space, and full kitchen.\", \"vi\": \"Chúng tôi cung cấp các căn hộ một và hai phòng ngủ đã được trang bị nội thất, bao gồm phòng khách, không gian làm việc và bếp đầy đủ tiện nghi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We offer:\", \"vi\": \"Chúng tôi cung cấp:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Different levels of pricing for housekeeping\", \"vi\": \"Các mức giá khác nhau cho dịch vụ dọn dẹp\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"A variety of low-cost Internet and phone plans\", \"vi\": \"Nhiều gói cước Internet và điện thoại với mức giá phải chăng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Conference facilities that can be booked for a minimal fee\", \"vi\": \"Các cơ sở hội nghị có thể đặt trước với mức phí tối thiểu\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Short-term gym memberships at several nearby fitness centers\", \"vi\": \"Các gói thành viên tập gym ngắn hạn tại một số trung tâm thể dục thể hình lân cận\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Complimentary coffee served each morning in the lobby\", \"vi\": \"Mỗi buổi sáng, chúng tôi đều phục vụ cà phê miễn phí tại sảnh khách sạn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The Melbourne Colton Hotel is close to transportation, tourist sites, and shopping.\", \"vi\": \"Khách sạn Melbourne Colton nằm gần các phương tiện giao thông, các điểm tham quan du lịch và các khu mua sắm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Contact reservations@coltonhotels.com.au for more information or call 61 3 7010 9921.\", \"vi\": \"Vui lòng liên hệ qua địa chỉ email reservations@coltonhotels.com.au để biết thêm thông tin hoặc gọi số 61 3 7010 9921.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '3f0e6be4-aea3-4efc-a9c5-bb8f72d30581';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Bywater and Sons\", \"vi\": \"Bywater và Các Con\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"https://www.bywaterandsons.com/testimonial\", \"vi\": \"https://www.bywaterandsons.com/testimonial\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Client Testimonial\", \"vi\": \"Lời chứng thực từ khách hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Please share your thoughts about the quality of our work at your home by submitting your name, e-mail address, and comments.\", \"vi\": \"Kính mong quý vị chia sẻ ý kiến của mình về chất lượng công việc mà chúng tôi đã thực hiện tại nhà quý vị bằng cách cung cấp họ tên, địa chỉ email và ý kiến phản hồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Name: Gina Tyler\", \"vi\": \"Họ và tên: Gina Tyler\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Email: gtyler@mailzinebox.com (this will not be posted with your review)\", \"vi\": \"Email: gtyler@mailzinebox.com (thông tin này sẽ không được đăng kèm cùng bài đánh giá của quý vị)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for your excellent painting work.\", \"vi\": \"Xin chân thành cảm ơn quý vị về tác phẩm hội họa xuất sắc này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It was completed efficiently and priced as in the initial quote.\", \"vi\": \"Công việc đã được hoàn thành một cách hiệu quả và mức giá cũng đúng như trong báo giá ban đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"My home looks as good as when it was new.\", \"vi\": \"Ngôi nhà của tôi trông vẫn đẹp như lúc mới xây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I will plan to use your services again in the future, and I am happy to recommend you to anyone considering a remodeling project.\", \"vi\": \"Tôi dự định sẽ tiếp tục sử dụng dịch vụ của quý công ty trong tương lai, và tôi rất sẵn lòng giới thiệu quý công ty đến bất kỳ ai đang cân nhắc thực hiện một dự án cải tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"—Gina T.\", \"vi\": \"—Gina T.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '3f261dff-4f52-4bb1-ba9f-c78edd9326b0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Kramer\'s Emporium\", \"vi\": \"Cửa hàng Kramer\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"2323 Raleigh Street • Houston, TX 77021\", \"vi\": \"2323 Đường Raleigh • Houston, TX 77021\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"After 25 years in business, our store is closing.\", \"vi\": \"Sau 25 năm hoạt động, cửa hàng của chúng tôi sẽ đóng cửa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Everything must go!\", \"vi\": \"Tất cả phải bán hết!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"From refrigerators to washing machines, we have hundreds of brand-new appliances for your home or office.\", \"vi\": \"Từ tủ lạnh đến máy giặt, chúng tôi có hàng trăm thiết bị gia dụng hoàn toàn mới dành cho gia đình hoặc văn phòng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Most items have been marked down by 30 percent.\", \"vi\": \"Hầu hết các mặt hàng đều đã được giảm giá 30%.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Delivery is available within 60 miles of our store for a flat fee of $50.00.\", \"vi\": \"Chúng tôi cung cấp dịch vụ giao hàng trong phạm vi 60 dặm tính từ cửa hàng của chúng tôi với mức phí cố định là 50,00 USD.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We are open daily from 9:00 A.M. to 7:00 P.M.\", \"vi\": \"Chúng tôi mở cửa hàng ngày từ 9 giờ sáng đến 7 giờ tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Don\'t wait!\", \"vi\": \"Đừng chần chừ!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Merchandise is selling fast!\", \"vi\": \"Hàng hóa đang bán rất chạy!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '3f3eb771-4a85-4fa0-8d49-1df982d81e9d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Poor - Fair - Good - Excellent - N/A\", \"vi\": \"Kém - Trung bình - Tốt - Xuất sắc - Không áp dụng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Quality of food - X\", \"vi\": \"Chất lượng thực phẩm - X\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Quantity of food - X\", \"vi\": \"Lượng thực phẩm - X\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Friendliness of staff - X\", \"vi\": \"Sự thân thiện của nhân viên - X\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Room setup/atmosphere - X\", \"vi\": \"Bố trí phòng/bầu không khí - X\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Overnight accommodations - X\", \"vi\": \"Chỗ ở qua đêm - X\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Pernely Hotel\", \"vi\": \"Khách sạn Pernely\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Thank you for choosing Pernely Hotel for your recent event!\", \"vi\": \"Xin chân thành cảm ơn quý khách đã lựa chọn Khách sạn Pernely để tổ chức sự kiện gần đây của quý khách!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please take a moment to fill out this survey.\", \"vi\": \"Kính mong quý vị dành chút thời gian để điền vào bản khảo sát này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We hope you will share your positive experience with associates and friends.\", \"vi\": \"Chúng tôi hy vọng quý vị sẽ chia sẻ những trải nghiệm tích cực của mình với các đồng nghiệp và bạn bè.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"If we receive a booking based on your referral, we will give you a 5% discount on the cost of your next event.\", \"vi\": \"Nếu chúng tôi nhận được một đơn đặt chỗ nhờ sự giới thiệu của quý vị, chúng tôi sẽ giảm giá 5% cho chi phí của sự kiện tiếp theo của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Customer name and e-mail: Aika Otani, a.otani@bipmail.com\", \"vi\": \"Tên và địa chỉ email của khách hàng: Aika Otani, a.otani@bipmail.com\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Event date: April 6\", \"vi\": \"Ngày diễn ra sự kiện: 6 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Event location: Oakwood Dining Room\", \"vi\": \"Địa điểm tổ chức sự kiện: Phòng ăn Oakwood\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Please rate the following aspects of your experience with us.\", \"vi\": \"Kính mong Quý khách đánh giá các khía cạnh sau đây về trải nghiệm của Quý khách khi sử dụng dịch vụ của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"(N/A = not applicable)\", \"vi\": \"(N/A = không áp dụng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Comments/Suggestions:\", \"vi\": \"Ý kiến/Đề xuất:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The Pernely event coordinator provided excellent support in putting this annual event together.\", \"vi\": \"Đơn vị điều phối sự kiện Pernely đã hỗ trợ rất đắc lực trong việc tổ chức sự kiện thường niên này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The food was delicious—the guests raved about the roast chicken!\", \"vi\": \"Món ăn thật ngon — các vị khách đã hết lời khen ngợi món gà nướng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"The dining room got quite noisy as it filled up.\", \"vi\": \"Khi khách dần đông lên, phòng ăn trở nên khá ồn ào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We will plan to use Pernely again next year, though we will definitely request a different room.\", \"vi\": \"Chúng tôi dự định sẽ tiếp tục lựa chọn Pernely vào năm tới, tuy nhiên chắc chắn chúng tôi sẽ yêu cầu một phòng khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '3f88aa35-9658-412f-b5c3-70b6b180b3e6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"REGULATIONS\", \"vi\": \"QUY ĐỊNH\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Per state law, all employees at this facility are required to wear long pants, long sleeves, socks, and steel-toe shoes.\", \"vi\": \"Theo luật của tiểu bang, tất cả nhân viên tại cơ sở này đều phải mặc quần dài, áo dài tay, tất và giày có mũi thép.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Employees who work with chemicals are also required to wear masks and safety gloves.\", \"vi\": \"Những nhân viên làm việc với hóa chất cũng bắt buộc phải đeo khẩu trang và găng tay bảo hộ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Eating and drinking are prohibited except in the cafeteria.\", \"vi\": \"Nghiêm cấm ăn uống, trừ tại căng-tin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}]' WHERE `id` = '3f8d6cbf-1f8f-4daa-9d2b-47e33b83d1f4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Win Free Juice for the Summer!\", \"vi\": \"Nhận nước ép miễn phí cho mùa hè này!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Here at Fresh Burst we want to celebrate the approaching summer!\", \"vi\": \"Tại Fresh Burst, chúng tôi muốn cùng quý vị chào đón mùa hè đang đến gần!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We\'ll reward the customer who comes up with a juice flavour that is brand-new.\", \"vi\": \"Chúng tôi sẽ trao thưởng cho khách hàng nào đề xuất được một hương vị nước ép hoàn toàn mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The lucky winner will receive a case of twenty-four 250 ml.\", \"vi\": \"Người may mắn trúng thưởng sẽ nhận được một thùng gồm hai mươi bốn chai, mỗi chai 250 ml.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"bottles of the new juice every month from 1 July through 30 September!\", \"vi\": \"mỗi tháng sẽ nhận được những chai nước ép mới từ ngày 1 tháng 7 đến hết ngày 30 tháng 9!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We\'ll also take photographs of you with your new juice to use in our advertising campaigns.\", \"vi\": \"Chúng tôi cũng sẽ chụp ảnh quý vị cùng ly nước ép mới của quý vị để sử dụng trong các chiến dịch quảng cáo của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"All you have to do is leave a comment describing your idea for a new flavour on our Fresh Burst social media page, then share your post with your friends.\", \"vi\": \"Tất cả những gì quý vị cần làm là để lại bình luận mô tả ý tưởng về một hương vị mới trên trang mạng xã hội Fresh Burst của chúng tôi, sau đó chia sẻ bài đăng của quý vị với bạn bè.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In your post, don\'t forget to include the creative name you\'ve invented for your new juice!\", \"vi\": \"Trong bài đăng của quý vị, xin đừng quên đề cập đến cái tên sáng tạo mà quý vị đã nghĩ ra cho loại nước ép mới của mình!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The contest runs from 6 January until 14 February.\", \"vi\": \"Cuộc thi diễn ra từ ngày 6 tháng 1 đến ngày 14 tháng 2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The winner will be notified by 25 April.\", \"vi\": \"Người chiến thắng sẽ được thông báo trước ngày 25 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Please note that the competition is only open to people aged 18 and over.\", \"vi\": \"Xin lưu ý rằng cuộc thi chỉ dành cho những người từ 18 tuổi trở lên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please also note that we cannot accept entries that include logos, product names, or other materials that are copyrighted by other companies.\", \"vi\": \"Xin lưu ý thêm rằng chúng tôi không thể chấp nhận các tác phẩm dự thi có chứa logo, tên sản phẩm hoặc các tài liệu khác thuộc bản quyền của các công ty khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '3fa84638-4d10-4f52-a024-6e796e2646f2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Bumbleberry Farm\", \"vi\": \"Trang trại Bumbleberry\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"8715 71st Street NW, Stanfurt, Oregon 97074\", \"vi\": \"8715 Đường 71 NW, Stanfurt, Oregon 97074\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"(971) 555-0144\", \"vi\": \"(971) 555-0144\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Pick your own blueberries!\", \"vi\": \"Hãy tự tay hái quả việt quất nhé!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Bumbleberry Farm is known for its sweet, juicy blueberries.\", \"vi\": \"Trang trại Bumbleberry nổi tiếng với những quả việt quất ngọt ngào và mọng nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Come and enjoy an afternoon in our blueberry fields picking your own.\", \"vi\": \"Hãy đến và tận hưởng một buổi chiều tại những cánh đồng việt quất của chúng tôi để tự tay hái quả nhé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We cater to families, but everyone is welcome!\", \"vi\": \"Chúng tôi phục vụ chủ yếu cho các gia đình, nhưng tất cả quý vị đều được chào đón!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Enjoy fresh blueberries as a healthy snack, or use them in homemade jams and baked goods.\", \"vi\": \"Hãy thưởng thức quả việt quất tươi như một món ăn nhẹ tốt cho sức khỏe, hoặc sử dụng chúng để làm mứt tự làm và các món bánh nướng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"They are also great for adding to your favorite cereal in the morning.\", \"vi\": \"Chúng cũng là lựa chọn tuyệt vời để trộn vào món ngũ cốc yêu thích của quý vị vào buổi sáng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Picking season this year is set to run from July 1 to September 15.\", \"vi\": \"Mùa thu hoạch năm nay dự kiến sẽ diễn ra từ ngày 1 tháng 7 đến ngày 15 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Our fields are open Tuesday through Sunday from 10:00 a.m. to 3:00 p.m.\", \"vi\": \"Các sân của chúng tôi mở cửa từ thứ Ba đến Chủ Nhật, từ 10 giờ sáng đến 3 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Admission to the fields is $2.00 per person, with a cost of $2.50 for each half liter of berries picked.\", \"vi\": \"Phí vào cửa các vườn là 2,00 đô la mỗi người, và phí thu hoạch là 2,50 đô la cho mỗi nửa lít quả mọng hái được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Groups of up to 8 persons are welcome.\", \"vi\": \"Chúng tôi hoan nghênh các nhóm có tối đa 8 người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Limit 1 liter per person.\", \"vi\": \"Giới hạn 1 lít cho mỗi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"For more information, visit our Web site at www.bumbleberryfarm.com.\", \"vi\": \"Để biết thêm thông tin, xin vui lòng truy cập trang web của chúng tôi tại địa chỉ www.bumbleberryfarm.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '3fc7e092-0125-4e53-93dd-685d90f41813';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Nate Hopkins <nate.hopkins@genmail.com>\", \"vi\": \"Đến: Nate Hopkins <nate.hopkins@genmail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Akari Kaneko <a.kaneko@flurry.com>\", \"vi\": \"Từ: Akari Kaneko <a.kaneko@flurry.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: July 27\", \"vi\": \"Ngày: 27 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Announcement\", \"vi\": \"Chủ đề: Thông báo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Hopkins,\", \"vi\": \"Gửi ông Hopkins,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am sorry to announce that the Flurry app will cease ______[139] on September 1.\", \"vi\": \"Tôi rất tiếc phải thông báo rằng ứng dụng Flurry sẽ ngừng ______[139] vào ngày 1 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [139]}, {\"en\": \"From that date, it will not be possible to stream, download, or listen to podcasts through Flurry.\", \"vi\": \"Từ ngày đó, sẽ không thể phát trực tuyến, tải xuống hoặc nghe podcast thông qua Flurry được nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Also, you will no longer have access to data associated with ______[140] Flurry account, such as downloaded episodes, lists of favorite shows, and listening preferences.\", \"vi\": \"Ngoài ra, bạn sẽ không còn quyền truy cập vào dữ liệu liên quan đến tài khoản Flurry ______[140], chẳng hạn như các tập đã tải xuống, danh sách chương trình yêu thích và sở thích nghe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [140]}, {\"en\": \"If you would like to save this information and export it to another podcast app, please ______[141] the instructions at www.flurry.com/help/394.\", \"vi\": \"Nếu bạn muốn lưu thông tin này và xuất sang một ứng dụng podcast khác, vui lòng ______[141] theo hướng dẫn tại www.flurry.com/help/394.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [141]}, {\"en\": \"______[142].\", \"vi\": \"______[142].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [142]}, {\"en\": \"Questions may be directed to the Flurry customer service center, which will remain open through September 1.\", \"vi\": \"Các câu hỏi có thể được gửi đến trung tâm dịch vụ khách hàng của Flurry, nơi sẽ tiếp tục mở cửa cho đến hết ngày 1 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We apologize again, and thank you for using Flurry until now.\", \"vi\": \"Chúng tôi chân thành xin lỗi một lần nữa và cảm ơn bạn đã sử dụng Flurry cho đến nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Akari Kaneko\", \"vi\": \"Akari Kaneko\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"President, Flurry, Inc.\", \"vi\": \"Chủ tịch, Flurry, Inc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '3fd5ff2f-369b-4cd0-b827-fbdb05cca19f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Feature - Satisfaction Level - Change from May\", \"vi\": \"Đặc điểm - Mức độ hài lòng - So với tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Guest room - 91% - +8% ↑\", \"vi\": \"Phòng khách - 91% - +8% ↑\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Breakfast - 82% - +10% ↑\", \"vi\": \"Bữa sáng - 82% - +10% ↑\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Reception - 80% - -5% ↓\", \"vi\": \"Mức độ đón nhận - 80% - -5% ↓\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Overall experience - 87% - +7% ↑\", \"vi\": \"Đánh giá tổng thể - 87% - +7% ↑\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Superb Hotels—Lisbon\", \"vi\": \"Các khách sạn đẳng cấp — Lisbon\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Customer Survey Results / June\", \"vi\": \"Kết quả khảo sát khách hàng / Tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Collected and analysed by Naomi Akdemir, Customer Solutions, Exelrate\", \"vi\": \"Thông tin được thu thập và phân tích bởi Naomi Akdemir, Bộ phận Giải pháp Khách hàng, Exelrate\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Exelrate Relocates Main Office\", \"vi\": \"Exelrate chuyển trụ sở chính\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"TORONTO (3 July)—Consumer analysis giant Exelrate will soon begin construction of its new headquarters in Toronto.\", \"vi\": \"TORONTO (ngày 3 tháng 7) — Exelrate, tập đoàn hàng đầu trong lĩnh vực phân tích người tiêu dùng, sẽ sớm khởi công xây dựng trụ sở chính mới tại Toronto.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Many well-known businesses use Exelrate\'s services to obtain an accurate understanding of their customers\' experiences.\", \"vi\": \"Nhiều doanh nghiệp nổi tiếng đang sử dụng dịch vụ của Exelrate để có được cái nhìn chính xác về trải nghiệm của khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The company\'s entry into North American markets is a promising sign of expected growth in the coming years.\", \"vi\": \"Việc công ty thâm nhập vào các thị trường Bắc Mỹ là một tín hiệu đầy hứa hẹn về triển vọng tăng trưởng trong những năm tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The recently promoted vice president of development, Rosa Martin, will be directing this expansion once she wraps up her work running the Customer Solutions Team at Exelrate\'s current headquarters in Frankfurt at the end of this month.\", \"vi\": \"Bà Rosa Martin, Phó Chủ tịch phụ trách Phát triển vừa được thăng chức, sẽ chịu trách nhiệm chỉ đạo đợt mở rộng này ngay sau khi bà hoàn tất công việc điều hành Nhóm Giải pháp Khách hàng tại trụ sở hiện tại của Exelrate ở Frankfurt vào cuối tháng này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The new office building was designed by Frank Tsudama, whose latest project involved Seoul\'s futurist Global Trade Centre.\", \"vi\": \"Tòa nhà văn phòng mới này do Frank Tsudama thiết kế; dự án gần đây nhất của ông là Trung tâm Thương mại Toàn cầu mang phong cách tương lai tại Seoul.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Exelrate\'s building will feature a ground-level courtyard with seating areas for public use, symbolising its insertion into the community.\", \"vi\": \"Tòa nhà của Exelrate sẽ có một khoảng sân ở tầng trệt với các khu vực ghế ngồi dành cho công chúng, thể hiện sự hòa nhập của tòa nhà vào cộng đồng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The establishment of companies like Exelrate will help cement Toronto\'s fame as a centre for data and management consulting.\", \"vi\": \"Sự ra đời của các công ty như Exelrate sẽ góp phần củng cố danh tiếng của Toronto với tư cách là một trung tâm tư vấn về dữ liệu và quản lý.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '3fd83f8f-5813-46b5-bcd7-754b6ff5d552';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Stefan Fonsman\", \"vi\": \"Từ: Stefan Fonsman\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Rita Palore\", \"vi\": \"Kính gửi: Rita Palore\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Palore Cement\", \"vi\": \"Chủ đề: Xi măng Palore\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: March 2\", \"vi\": \"Ngày: 2 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Palore,\", \"vi\": \"Kính gửi Bà Palore,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for sending your estimate for the cement work on our apartment project in Smithville.\", \"vi\": \"Xin chân thành cảm ơn Quý vị đã gửi bản dự toán cho công việc thi công bê tông trong dự án căn hộ của chúng tôi tại Smithville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The narrative accompanying your bid answered all of our questions, and my team was impressed by your firm\'s previous work and references.\", \"vi\": \"Bản trình bày kèm theo hồ sơ dự thầu của quý công ty đã giải đáp đầy đủ mọi thắc mắc của chúng tôi, và đội ngũ của tôi rất ấn tượng với những thành tích trước đây cũng như các tài liệu tham khảo của quý công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Your company is my first choice to take on the project.\", \"vi\": \"Công ty của quý vị là sự lựa chọn hàng đầu của tôi để đảm nhận dự án này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Nonetheless, I still need budget approval from my director, Anita Cho.\", \"vi\": \"Tuy nhiên, tôi vẫn cần được giám đốc của tôi, bà Anita Cho, phê duyệt ngân sách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Your proposed price is a bit steeper than anticipated.\", \"vi\": \"Mức giá mà quý vị đề xuất cao hơn một chút so với dự kiến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I will be speaking with Ms. Cho about this tomorrow morning.\", \"vi\": \"Sáng mai, tôi sẽ trao đổi với bà Cho về vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Based on your company\'s reputation for outstanding work, I am confident that she will sign off on your bid.\", \"vi\": \"Dựa trên danh tiếng về chất lượng công việc xuất sắc của công ty quý vị, tôi tin chắc rằng bà ấy sẽ chấp thuận đề xuất của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I expect to get back to you by March 4.\", \"vi\": \"Tôi dự kiến sẽ liên hệ lại với quý vị trước ngày 4 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Stefan Fonsman\", \"vi\": \"Stefan Fonsman\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Kaybun Construction\", \"vi\": \"Kaybun Xây dựng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '3fdd4e1b-7ca8-4cd2-b073-792dcc676054';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"FOR IMMEDIATE RELEASE\", \"vi\": \"THÔNG CÁO BÁO CHÍ NGAY LẬP TỨC\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Contact: Eloise Bassett, bassett@edmond.com.jm\", \"vi\": \"Liên hệ: Eloise Bassett, bassett@edmond.com.jm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Montego Bay (23 July)—Edmond Limited is pleased to announce the completion of its latest project, South Montego Bay Court.\", \"vi\": \"Montego Bay (ngày 23 tháng 7) — Công ty Edmond Limited vui mừng thông báo về việc hoàn thành dự án mới nhất của mình, South Montego Bay Court.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The complex has only 200 townhouses still available; most of the units were presold when construction first began.\", \"vi\": \"Khu phức hợp này hiện chỉ còn 200 căn nhà phố đang được chào bán; phần lớn các căn đã được bán trước ngay từ khi bắt đầu thi công.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Each townhouse features a well-equipped kitchen, a spacious family room, two to three comfortable bedrooms, and two full bathrooms.\", \"vi\": \"Mỗi căn nhà phố đều được trang bị một nhà bếp đầy đủ tiện nghi, một phòng khách rộng rãi, từ hai đến ba phòng ngủ tiện nghi và hai phòng tắm đầy đủ tiện nghi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The family room opens to a patio, so residents can enjoy the peaceful setting.\", \"vi\": \"Phòng sinh hoạt gia đình thông ra sân hiên, nhờ đó các cư dân có thể tận hưởng khung cảnh yên bình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Every unit also includes modern amenities, such as central air conditioning and an energy-efficient oven, dishwasher, and clothes washer/dryer.\", \"vi\": \"Mỗi căn hộ đều được trang bị các tiện nghi hiện đại, chẳng hạn như hệ thống điều hòa không khí trung tâm, lò nướng tiết kiệm năng lượng, máy rửa chén và máy giặt/sấy quần áo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The South Montego Bay Court complex is ideally situated close to shops and restaurants as well as several popular beaches.\", \"vi\": \"Khu phức hợp Tòa án South Montego Bay tọa lạc tại vị trí lý tưởng, gần các cửa hàng và nhà hàng cũng như một số bãi biển nổi tiếng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Additionally, residents have access to an outdoor pool and a playground on the property.\", \"vi\": \"Ngoài ra, cư dân còn được sử dụng hồ bơi ngoài trời và khu vui chơi dành cho trẻ em ngay trong khuôn viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"You are welcome to drop in at South Montego Court and visit any of the available units.\", \"vi\": \"Quý vị vui lòng ghé thăm South Montego Court và tham quan bất kỳ căn hộ nào hiện đang có sẵn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If you wish to schedule a private tour, you may do so by calling 876-555-0176.\", \"vi\": \"Nếu quý vị muốn đặt lịch tham quan riêng, quý vị có thể liên hệ qua số điện thoại 876-555-0176.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '402404ae-7b29-4d8b-8416-78025b4ba1b5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Coffer Digital Management Steering Committee\", \"vi\": \"Ủy ban Chỉ đạo Quản lý Kỹ thuật số Coffer\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Meeting Minutes\", \"vi\": \"Biên bản cuộc họp\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"November 12\", \"vi\": \"Ngày 12 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Re-pitch is ready to be pilot tested.\", \"vi\": \"Bản đề xuất sửa đổi đã sẵn sàng để tiến hành thử nghiệm thí điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The pilot test will be carried out during the first quarter of the fiscal year, January 3–March 31.\", \"vi\": \"Chương trình thử nghiệm thí điểm sẽ được triển khai trong quý đầu tiên của năm tài chính, từ ngày 3 tháng 1 đến ngày 31 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Five existing clients will use the experimental version of Re-pitch during the pilot test.\", \"vi\": \"Năm khách hàng hiện tại sẽ sử dụng phiên bản thử nghiệm của Re-pitch trong quá trình thử nghiệm thí điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"They will then take a survey to rate the software\'s effectiveness, ease of use, and affordability.\", \"vi\": \"Sau đó, quý vị sẽ tham gia một cuộc khảo sát để đánh giá mức độ hiệu quả, tính dễ sử dụng và mức giá phải chăng của phần mềm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If the Re-pitch pilot is successful, a large dollar investment will be needed to design and run an extensive marketing campaign.\", \"vi\": \"Nếu chương trình thí điểm “Re-pitch” thành công, sẽ cần một khoản đầu tư lớn bằng đô la để thiết kế và triển khai một chiến dịch tiếp thị quy mô rộng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Our company president will explore potential funding sources for this campaign.\", \"vi\": \"Chủ tịch công ty chúng tôi sẽ tìm hiểu các nguồn tài trợ tiềm năng cho chiến dịch này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To: sales@coffer.com\", \"vi\": \"Gửi tới: sales@coffer.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"From: tcao@ewest-taipei.com.tw\", \"vi\": \"Nguồn: tcao@ewest-taipei.com.tw\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Date: 13 April\", \"vi\": \"Ngày: 13 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Subject: Pilot test\", \"vi\": \"Chủ đề: Thử nghiệm thí điểm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Dear Coffer Digital,\", \"vi\": \"Kính gửi Coffer Digital,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I wanted to follow up after having just submitted our thoughts regarding your Re-pitch marketing software.\", \"vi\": \"Tôi muốn liên hệ lại với quý vị sau khi vừa gửi ý kiến của chúng tôi về phần mềm tiếp thị Re-pitch của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"You will find that our pilot-test feedback is overwhelmingly positive, which is why we would like to be notified immediately upon the rollout of this product.\", \"vi\": \"Quý vị sẽ thấy rằng các phản hồi từ đợt thử nghiệm ban đầu của chúng tôi đều rất tích cực; chính vì vậy, chúng tôi mong được thông báo ngay lập tức khi sản phẩm này chính thức được ra mắt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"We are very eager to add Re-pitch to our permanent digital marketing efforts.\", \"vi\": \"Chúng tôi rất mong muốn đưa Re-pitch vào các hoạt động tiếp thị kỹ thuật số thường xuyên của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Ting Cao, Director of Global Internet Marketing\", \"vi\": \"Ông Ting Cao, Giám đốc Tiếp thị Internet Toàn cầu\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Ewest Clothing Ltd., Taipei\", \"vi\": \"Công ty TNHH Ewest Clothing, Đài Bắc\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Business Briefs\", \"vi\": \"Tin tức kinh doanh ngắn gọn\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Coffer Digital closed a deal yesterday with GPZ Capital.\", \"vi\": \"Hôm qua, Coffer Digital đã ký kết một thỏa thuận với GPZ Capital.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"GPZ will make a significant investment in Coffer Digital, enabling the funding of a new online marketing application called Re-pitch.\", \"vi\": \"GPZ sẽ thực hiện một khoản đầu tư đáng kể vào Coffer Digital, qua đó tạo điều kiện tài trợ cho một ứng dụng tiếp thị trực tuyến mới mang tên Re-pitch.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"This sales-boosting software works by generating a pop-up window that reminds online shoppers of products they have already viewed, after they have navigated away from the product page.\", \"vi\": \"Phần mềm thúc đẩy doanh số này hoạt động bằng cách hiển thị một cửa sổ bật lên để nhắc nhở người mua hàng trực tuyến về những sản phẩm mà họ đã xem trước đó, sau khi họ đã rời khỏi trang sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"GPZ\'s knowledge of data and marketing has enabled them to make successful investments in three other software development firms in the past five years.\", \"vi\": \"Nhờ kiến thức chuyên sâu về dữ liệu và tiếp thị, GPZ đã thực hiện thành công các khoản đầu tư vào ba công ty phát triển phần mềm khác trong vòng năm năm qua.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Coffer Digital\'s strong company reputation and top-notch employees easily support GPZ\'s decision to invest.\", \"vi\": \"Danh tiếng vững chắc của Công ty Coffer Digital cùng đội ngũ nhân viên xuất sắc đã dễ dàng củng cố quyết định đầu tư của GPZ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"\\\"Coffer Digital has a solid plan for distributing Re-pitch, so it was an easy decision to invest with them,\\\" said Jessica Gould, spokesperson for GPZ.\", \"vi\": \"\\\"Coffer Digital có một kế hoạch phân phối Re-pitch rất vững chắc, vì vậy việc quyết định đầu tư cùng họ là điều hoàn toàn dễ dàng,\\\" bà Jessica Gould, người phát ngôn của GPZ, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '4027d1b3-9a90-4663-9140-78161e9d8aef';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Yong-Sun Che <ysche@buztech.com>\", \"vi\": \"Gửi tới: Yong-Sun Che <ysche@buztech.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Ginny Redman <gredman@silvervaleair.com>\", \"vi\": \"Từ: Ginny Redman <gredman@silvervaleair.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: RE: Seat problem\", \"vi\": \"Chủ đề: RE: Vấn đề về chỗ ngồi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: February 12\", \"vi\": \"Ngày: 12 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Voucher\", \"vi\": \"Tệp đính kèm: 📎 Phiếu giảm giá\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Che:\", \"vi\": \"Kính gửi ông Che:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for contacting us regarding your recent flight.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã liên hệ với chúng tôi về chuyến bay gần đây của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We apologize for the discomfort you experienced during your flight because of the nonfunctioning air-conditioning vent above your seat.\", \"vi\": \"Chúng tôi xin chân thành xin lỗi về sự bất tiện mà quý khách đã gặp phải trong suốt chuyến bay do lỗ thông gió điều hòa phía trên ghế ngồi của quý khách không hoạt động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We value you as a customer and want to make sure your experience with Silvervale Air is positive, so we have attached Voucher 789798 in the amount of $200.\", \"vi\": \"Chúng tôi luôn coi trọng quý khách và mong muốn đảm bảo quý khách có những trải nghiệm tích cực khi sử dụng dịch vụ của Silvervale Air; vì vậy, chúng tôi xin gửi kèm Phiếu giảm giá số 789798 với giá trị 200 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This may be applied to a future domestic flight with us.\", \"vi\": \"Quý khách có thể sử dụng ưu đãi này cho một chuyến bay nội địa trong tương lai với hãng hàng không của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The voucher expires after twelve months.\", \"vi\": \"Phiếu giảm giá này sẽ hết hạn sau mười hai tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Thank you for choosing Silvervale Air.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã lựa chọn Silvervale Air.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Ginny Redman\", \"vi\": \"Ginny Redman\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Silvervale Air Customer Service\", \"vi\": \"Bộ phận Dịch vụ Khách hàng của Silvervale Air\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Flight - Departs - Arrives - Seat\", \"vi\": \"Chuyến bay - Khởi hành - Đến - Chỗ ngồi\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Silvervale Air 29 - Atlanta, GA (ATL)\\nMon., May 6\\n11:43 A.M. - Los Angeles, CA (LAX)\\nMon., May 6\\n1:35 P.M. - 36D\", \"vi\": \"Chuyến bay Silvervale Air 29 - Atlanta, GA (ATL)\\nThứ Hai, ngày 6 tháng 5\\n11:43 sáng - Los Angeles, CA (LAX)\\nThứ Hai, ngày 6 tháng 5\\n1:35 chiều - Ghế 36D\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Passenger:   Mr. Yong-Sun Che\", \"vi\": \"Hành khách:   Ông Yong-Sun Che\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Ticket number:   0272125899649\", \"vi\": \"Số vé:   0272125899649\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Confirmation code:   CMOAAB\", \"vi\": \"Mã xác nhận:   CMOAAB\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Summary of airfare charges\", \"vi\": \"Tóm tắt các khoản phí vé máy bay\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Base fare         $259.54\", \"vi\": \"Giá cơ bản:         259,54 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Taxes and fees   $33.76\", \"vi\": \"Thuế và lệ phí   33,76 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Voucher 789798   –$200.00\", \"vi\": \"Phiếu giảm giá 789798   – 200,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Total               $93.30\", \"vi\": \"Tổng cộng               93,30 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"All passengers are entitled to travel with one complimentary carry-on and one checked bag.\", \"vi\": \"Tất cả hành khách đều được phép mang theo một kiện hành lý xách tay miễn phí và một kiện hành lý ký gửi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '402b50f9-8bfd-4dbe-9fe3-dbdf60ddc6e0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Iwoni Media in the News\", \"vi\": \"Iwoni Media trên các phương tiện truyền thông\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"TORONTO (1 May)—Publisher Iwoni Media announced on Friday morning that new issues of Energy Run would not be released according to the book\'s regular monthly publishing schedule.\", \"vi\": \"TORONTO (ngày 1 tháng 5) — Nhà xuất bản Iwoni Media đã thông báo vào sáng thứ Sáu rằng các số mới của tạp chí Energy Run sẽ không được phát hành theo lịch xuất bản hàng tháng thông thường của ấn phẩm này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The company\'s decision is connected to plans to modernize its printing facility by replacing the now-obsolete machinery on which the legendary comic book is printed.\", \"vi\": \"Quyết định của công ty có liên quan đến kế hoạch hiện đại hóa nhà máy in bằng cách thay thế các thiết bị đã lỗi thời hiện nay, vốn được sử dụng để in cuốn truyện tranh huyền thoại này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As the word spread on Friday of the decision to halt publication, fans rushed to buy what many feared might be the last issue.\", \"vi\": \"Khi tin tức về quyết định ngừng xuất bản lan truyền vào thứ Sáu, các độc giả đã đổ xô đi mua số báo mà nhiều người lo ngại có thể là số cuối cùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Iwoni Media\'s online store is reportedly the only place where the publication is still available.\", \"vi\": \"Theo thông tin, cửa hàng trực tuyến của Iwoni Media là nơi duy nhất hiện nay vẫn còn bán ấn phẩm này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Iwoni Media\'s spokesperson, Jon Emanuel, stated that the new printing facility should be up and running within four months and that the next issue of Energy Run will arrive on newsstands shortly after that.\", \"vi\": \"Người phát ngôn của Iwoni Media, ông Jon Emanuel, cho biết nhà máy in mới dự kiến sẽ đi vào hoạt động trong vòng bốn tháng và số tiếp theo của tạp chí Energy Run sẽ có mặt tại các quầy báo ngay sau đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"\\\"Fans should not worry,\\\" Mr. Emanuel said.\", \"vi\": \"\\\"Quý vị người hâm mộ không nên lo lắng,\\\" ông Emanuel nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"\\\"Their favourite characters will be back soon.\\\"\", \"vi\": \"\\\"Những nhân vật mà các em yêu thích sẽ sớm trở lại.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '406c32ac-b4a0-4e52-bd29-8fda97976e09';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Handmade Silk Blouse by Coreopsis Textiles, Size Medium, £45\", \"vi\": \"Áo sơ mi lụa làm thủ công của Coreopsis Textiles, Cỡ M, 45 bảng Anh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Coreopsis Textiles\' silk blouses are created from vintage fabrics and other recycled components that we sew together in a patchwork fashion.\", \"vi\": \"Những chiếc áo sơ mi lụa của Coreopsis Textiles được tạo ra từ các loại vải cổ điển và các thành phần tái chế khác mà chúng tôi may lại với nhau theo kiểu chắp vá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Because all ___139___ garments are handcrafted, each is one of a kind.\", \"vi\": \"Vì tất cả các trang phục ___139___ đều được làm thủ công nên mỗi chiếc đều là độc nhất vô nhị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [139]}, {\"en\": \"___140___ .\", \"vi\": \"___140___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [140]}, {\"en\": \"Unique variations within each piece are part of the charm of Coreopsis Textiles\' products.\", \"vi\": \"Những biến thể độc đáo trong từng sản phẩm là một phần sức hấp dẫn của các sản phẩm thuộc Coreopsis Textiles.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The blouse you receive will be similar in style but not identical to the one pictured.\", \"vi\": \"Chiếc áo bạn nhận được sẽ có kiểu dáng tương tự nhưng không hoàn toàn giống với chiếc trong hình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Please note that this garment is ___141___ .\", \"vi\": \"Xin lưu ý rằng trang phục này ___141___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [141]}, {\"en\": \"It is recommended that you either hand-wash it or wash it in cold water on the gentle cycle in a mesh bag.\", \"vi\": \"Bạn nên giặt tay hoặc giặt bằng nước lạnh ở chế độ giặt nhẹ trong một chiếc túi lưới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"While the item has been prewashed, dryer heat may cause it to shrink.\", \"vi\": \"Mặc dù mặt hàng đã được giặt trước, nhưng nhiệt độ từ máy sấy có thể làm nó bị co lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"___142___ , it is important that it be hung to air dry.\", \"vi\": \"___142___ , điều quan trọng là phải treo nó lên để khô tự nhiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [142]}]' WHERE `id` = '4089c701-716b-47b9-9b71-d93359f5586c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Thank you for choosing the River Street Hotel!\", \"vi\": \"Xin chân thành cảm ơn quý khách đã lựa chọn Khách sạn River Street!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"In an effort to bring our guests the very best experience, we\'ve extended our complimentary shuttle bus service to include the city\'s downtown area.\", \"vi\": \"Với mong muốn mang đến cho quý khách trải nghiệm tuyệt vời nhất, chúng tôi đã mở rộng dịch vụ xe buýt đưa đón miễn phí để bao gồm cả khu vực trung tâm thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The shuttle loops around the downtown\'s most popular tourist attractions with several stops, including all historic sites, the outdoor market, and the theater district.\", \"vi\": \"Xe buýt đưa đón này chạy vòng quanh các điểm tham quan du lịch nổi tiếng nhất tại trung tâm thành phố với nhiều điểm dừng, bao gồm tất cả các di tích lịch sử, chợ ngoài trời và khu nhà hát.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"While these destinations are all within walking distance from the hotel, the shuttle will allow you to reach them more quickly.\", \"vi\": \"Mặc dù tất cả các điểm đến này đều nằm trong phạm vi có thể đi bộ từ khách sạn, nhưng dịch vụ xe đưa đón sẽ giúp quý khách đến đó nhanh hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The route is ideal for first-time and regular visitors.\", \"vi\": \"Tuyến đường này rất lý tưởng cho cả những du khách lần đầu ghé thăm lẫn những du khách thường xuyên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The shuttle will also make additional stops during special events and festivals.\", \"vi\": \"Xe đưa đón cũng sẽ dừng thêm tại một số điểm trong các sự kiện đặc biệt và lễ hội.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Shuttle schedules are posted in the hotel lobby.\", \"vi\": \"Lịch trình xe đưa đón được niêm yết tại sảnh khách sạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As with our airport service, rewards club members can book a shuttle ahead of time.\", \"vi\": \"Tương tự như dịch vụ tại sân bay của chúng tôi, các thành viên câu lạc bộ khách hàng thân thiết có thể đặt xe đưa đón trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '412ed251-826a-4ecc-8d23-2941c3ddec8e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Jake Taera <jtaera@tritmail.com>\", \"vi\": \"Gửi tới: Jake Taera <jtaera@tritmail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Natalie Satter <nsatter@coldings.com>\", \"vi\": \"Từ: Natalie Satter <nsatter@coldings.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 30 September\", \"vi\": \"Ngày: 30 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Coldings1\", \"vi\": \"Tệp đính kèm: Coldings1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Taera:\", \"vi\": \"Kính gửi ông Taera:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Welcome to the Coldings Home Store family!\", \"vi\": \"Chào mừng quý vị gia nhập đại gia đình Coldings Home Store!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You have been hired as a sales associate.\", \"vi\": \"Quý vị đã được tuyển dụng vào vị trí nhân viên bán hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Your training session begins on 8 October at 8:30 A.M. at the Auckland store, 42 Crossbill Road.\", \"vi\": \"Buổi đào tạo của quý vị sẽ bắt đầu vào ngày 8 tháng 10 lúc 8 giờ 30 sáng tại cửa hàng ở Auckland, số 42 Crossbill Road.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please report to Human Resources to begin your orientation as a Coldings Home Store team member.\", \"vi\": \"Kính mời quý vị đến bộ phận Nhân sự để bắt đầu chương trình định hướng dành cho thành viên đội ngũ của Coldings Home Store.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"During your first two weeks with our company, you will learn about our team approach and the many benefits of working at Coldings Home Store.\", \"vi\": \"Trong hai tuần đầu tiên làm việc tại công ty chúng tôi, quý vị sẽ được tìm hiểu về phương thức làm việc theo nhóm của chúng tôi cũng như những lợi ích phong phú khi làm việc tại Coldings Home Store.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You will be working from 8:30 A.M. to 5:00 P.M. After training, you might be assigned to a different work shift and you will be eligible for benefits including flexible days off, sick days, and our employee discount.\", \"vi\": \"Quý vị sẽ làm việc từ 8 giờ 30 phút sáng đến 5 giờ chiều. Sau khi hoàn thành khóa đào tạo, quý vị có thể được phân công vào một ca làm việc khác và sẽ được hưởng các chế độ phúc lợi bao gồm ngày nghỉ linh hoạt, ngày nghỉ ốm và chương trình giảm giá dành cho nhân viên của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Please sign and return the attached document indicating your willingness to accept the position as sales associate.\", \"vi\": \"Kính mong Quý vị ký tên và gửi lại tài liệu đính kèm để xác nhận sự đồng ý nhận vị trí nhân viên bán hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please let me know if you have any questions or need directions.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào hoặc cần hướng dẫn, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I look forward to seeing you at the Auckland store on 8 October.\", \"vi\": \"Tôi rất mong được gặp quý vị tại cửa hàng ở Auckland vào ngày 8 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Natalie Satter\", \"vi\": \"Natalie Satter\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Human Resources Coordinator\", \"vi\": \"Điều phối viên Nhân sự\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '4151aa2f-98be-4b7d-a467-564c39bf14d4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"The DC Analytics management team is aware that some files were permanently erased due to the recent system malfunction.\", \"vi\": \"Ban quản lý DC Analytics nhận thức được rằng một số tệp đã bị xóa vĩnh viễn do sự cố hệ thống gần đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"We ask that you back up your work to external hard drives regularly.\", \"vi\": \"Chúng tôi yêu cầu quý vị thường xuyên sao lưu công việc của mình vào các ổ đĩa cứng di động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This will help us avoid a similar ______[143] in the future.\", \"vi\": \"Điều này sẽ giúp chúng ta tránh được một sự cố tương tự ______[143] trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [143]}, {\"en\": \"Unfortunately, we are unable to use automatic cloud storage due to security issues.\", \"vi\": \"Thật không may, chúng tôi không thể sử dụng bộ nhớ đám mây tự động do các vấn đề bảo mật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"______[144].\", \"vi\": \"______[144].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [144]}, {\"en\": \"You can sign up by contacting the IT office on extension 14.\", \"vi\": \"Quý vị có thể đăng ký bằng cách liên hệ với văn phòng CNTT qua số máy lẻ 14.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Each day at 4:45 p.m., the IT team ______[145] an e-mail with a reminder about file backups.\", \"vi\": \"Mỗi ngày vào lúc 4:45 chiều, đội ngũ CNTT ______[145] một email nhắc nhở về việc sao lưu tệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [145]}, {\"en\": \"If this is too frequent for you, you can arrange ______[146] the messages on a weekly basis instead.\", \"vi\": \"Nếu tần suất này quá nhiều đối với bạn, bạn có thể sắp xếp ______[146] các tin nhắn này theo tuần thay thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [146]}]' WHERE `id` = '415b99a6-3f41-4591-8ed5-73094314f45e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Commercial relocation may at first appear ______[131], but Mester Movers will work with you to make the process as simple as possible.\", \"vi\": \"Việc di dời văn phòng kinh doanh thoạt đầu có vẻ ______[131], nhưng Mester Movers sẽ hợp tác với bạn để làm cho quá trình này trở nên đơn giản nhất có thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [131]}, {\"en\": \"Whether you are relocating an office, factory, or laboratory across town or across the country, we have the people, technology, and resources to ______[132] your move with efficiency.\", \"vi\": \"Cho dù bạn đang chuyển văn phòng, nhà máy hoặc phòng thí nghiệm qua một góc phố hay khắp cả nước, chúng tôi có nhân lực, công nghệ và nguồn lực để ______[132] việc chuyển dời của bạn một cách hiệu quả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [132]}, {\"en\": \"We take special care when packing small and delicate objects.\", \"vi\": \"Chúng tôi chăm sóc đặc biệt khi đóng gói các vật dụng nhỏ và dễ vỡ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"______[133], we make sure that large items such as desks, filing cabinets, and chairs are also ready for the move by providing you with special tags.\", \"vi\": \"______[133], chúng tôi đảm bảo rằng các vật dụng lớn như bàn làm việc, tủ hồ sơ và ghế cũng sẵn sàng cho việc chuyển đi bằng cách cung cấp cho bạn các thẻ đánh dấu đặc biệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [133]}, {\"en\": \"______[134].\", \"vi\": \"______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [134]}]' WHERE `id` = '4198f386-f57d-4c6a-ac82-27c8dfbab7e2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Holly Grenier <grenierh@duvalmail.com>\", \"vi\": \"Gửi tới: Holly Grenier <grenierh@duvalmail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Bryce Jarvis <b.jarvis@literaryquarterly.com>\", \"vi\": \"Từ: Bryce Jarvis <b.jarvis@literaryquarterly.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: August 15\", \"vi\": \"Ngày: 15 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: RE: Submission for upcoming edition\", \"vi\": \"Chủ đề: RE: Bài gửi cho số tiếp theo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 lquarterly_guidelines\", \"vi\": \"Tệp đính kèm: 📎 lquarterly_guidelines\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Grenier,\", \"vi\": \"Kính gửi Bà Grenier,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for your interest in submitting your work to be considered for publication in Literary Quarterly.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã quan tâm đến việc gửi tác phẩm của mình để được xem xét đăng tải trên tạp chí Literary Quarterly.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please note that we charge a nonrefundable submission fee of $5.00 for each piece of work, which does not affect whether or not the piece is published.\", \"vi\": \"Xin lưu ý rằng chúng tôi thu một khoản phí nộp bài không hoàn lại là 5,00 đô la cho mỗi tác phẩm, và khoản phí này không phụ thuộc vào việc tác phẩm đó có được đăng tải hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Along with the main text, you should include a paragraph that briefly describes your work.\", \"vi\": \"Bên cạnh phần nội dung chính, quý vị nên bổ sung một đoạn văn mô tả ngắn gọn về công trình của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"This will help us to assess the suitability of your writing for our magazine when we review your submission.\", \"vi\": \"Điều này sẽ giúp chúng tôi đánh giá mức độ phù hợp của bài viết của quý vị với tạp chí của chúng tôi khi xem xét bài gửi của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"If you subscribe to the magazine, you will have a better understanding of our preferences.\", \"vi\": \"Nếu quý vị đăng ký nhận tạp chí, quý vị sẽ hiểu rõ hơn về sở thích của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Also, as we exclusively consider texts that have never been published elsewhere, your submission should not have been shared with other publishers previously.\", \"vi\": \"Ngoài ra, do chúng tôi chỉ xem xét các bài viết chưa từng được xuất bản ở bất kỳ nơi nào khác, nên bài viết của quý vị không được gửi cho các nhà xuất bản khác trước đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Prior to submitting your work, please read the attached guidelines carefully and follow the style and layout precisely.\", \"vi\": \"Trước khi nộp bài, xin vui lòng đọc kỹ các hướng dẫn đính kèm và tuân thủ chính xác các quy định về phong cách và cách trình bày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"There is a sample essay included for your reference.\", \"vi\": \"Trong tài liệu này có kèm theo một bài luận mẫu để quý vị tham khảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We are always in need of short stories, but we receive an overwhelming amount of poetry.\", \"vi\": \"Chúng tôi luôn cần các truyện ngắn, nhưng lại nhận được một lượng thơ quá lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"So, please understand that even excellent manuscripts may be rejected due to the high volume, and we hope this will not discourage you.\", \"vi\": \"Vì vậy, mong quý vị thông cảm rằng ngay cả những bản thảo xuất sắc cũng có thể bị từ chối do số lượng bài gửi quá lớn, và chúng tôi hy vọng điều này sẽ không làm quý vị nản lòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We wish you the best of luck with your submission,\", \"vi\": \"Chúng tôi xin chúc quý vị may mắn với bài dự thi của mình,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Bryce Jarvis\", \"vi\": \"Bryce Jarvis\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '41ad21f4-9b84-4321-85e4-01811c3c654d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.runklefencing.co.uk\", \"vi\": \"https://www.runklefencing.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Temporary Fencing Service\", \"vi\": \"Dịch vụ lắp đặt hàng rào tạm thời\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Need a temporary fence installed at your residence, workplace, or special event?\", \"vi\": \"Quý vị có nhu cầu lắp đặt hàng rào tạm thời tại nơi ở, nơi làm việc hoặc tại một sự kiện đặc biệt nào đó không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Our expert team will deliver and install chain-link fencing on the booked date and time.\", \"vi\": \"Đội ngũ chuyên gia của chúng tôi sẽ giao và lắp đặt hàng rào lưới thép vào ngày và giờ đã đặt trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"When the fence is no longer needed, we will take it down and haul it away.\", \"vi\": \"Khi hàng rào không còn cần thiết nữa, chúng tôi sẽ tháo dỡ và vận chuyển đi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Like our residential and commercial fencing, our temporary fences are obtained from the best manufacturers using the finest materials.\", \"vi\": \"Cũng giống như các sản phẩm hàng rào dân dụng và thương mại của chúng tôi, các loại hàng rào tạm thời của chúng tôi được nhập từ những nhà sản xuất hàng đầu và sử dụng những vật liệu chất lượng cao nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our fences have a tidy, sturdy, professional appearance that local residents and businesses appreciate.\", \"vi\": \"Hàng rào của chúng tôi có vẻ ngoài gọn gàng, chắc chắn và chuyên nghiệp, được người dân và các doanh nghiệp địa phương đánh giá cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We also see to all legally required inspections and certifications.\", \"vi\": \"Chúng tôi cũng đảm bảo thực hiện đầy đủ các cuộc kiểm tra và cấp chứng nhận theo quy định của pháp luật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Ready for a price quote?\", \"vi\": \"Quý vị đã sẵn sàng nhận báo giá chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Contact us today via our Online Quote service.\", \"vi\": \"Hãy liên hệ với chúng tôi ngay hôm nay thông qua dịch vụ Báo giá Trực tuyến của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Be sure to provide the following information so we can provide an accurate estimate:\", \"vi\": \"Xin vui lòng cung cấp đầy đủ các thông tin sau đây để chúng tôi có thể đưa ra báo giá chính xác:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The preferred height of your fence (Be aware that local regulations commonly allow a maximum height of three metres.)\", \"vi\": \"Chiều cao lý tưởng cho hàng rào của quý vị (Xin lưu ý rằng các quy định địa phương thường cho phép chiều cao tối đa là ba mét.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The perimeter of the area you need to enclose\", \"vi\": \"Chu vi của khu vực mà quý vị cần rào lại\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The number of gated entrances needed\", \"vi\": \"Số lượng cổng ra vào có rào chắn cần thiết\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The number of days the fence needs to be up\", \"vi\": \"Số ngày cần duy trì hàng rào\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Temporary\", \"vi\": \"Tạm thời\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Residential\", \"vi\": \"Dân cư\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Commercial\", \"vi\": \"Thương mại\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Name: Marguerite Carhart - Phone: (0117) 555-9102\", \"vi\": \"Họ tên: Marguerite Carhart - Số điện thoại: (0117) 555-9102\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Installation Address: 438 Stretford Way, Bristol BS5 7TB\", \"vi\": \"Địa chỉ lắp đặt: 438 Stretford Way, Bristol BS5 7TB\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"E-mail: mcarhart@stockporteventcentre.co.uk\", \"vi\": \"Email: mcarhart@stockporteventcentre.co.uk\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Today\'s date: 8 August\", \"vi\": \"Ngày hôm nay: 8 tháng 8\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Fence Details:\", \"vi\": \"Thông tin chi tiết về hàng rào:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I need a temporary three-metre-tall fence installed around the Stockport Event Centre within the next two weeks.\", \"vi\": \"Tôi cần lắp đặt một hàng rào tạm thời cao ba mét xung quanh Trung tâm Sự kiện Stockport trong vòng hai tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"This is to prevent the public from entering while we make renovations from 18 to 30 August.\", \"vi\": \"Thông báo này nhằm ngăn chặn người dân vào khu vực trong thời gian chúng tôi tiến hành cải tạo từ ngày 18 đến ngày 30 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Two gates are needed so that workers and vehicles may enter and leave the location.\", \"vi\": \"Cần có hai cổng để công nhân và phương tiện có thể ra vào khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"To: mcarhart@stockporteventcentre.co.uk\", \"vi\": \"Gửi tới: mcarhart@stockporteventcentre.co.uk\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"From: hmontalbo@runklefencing.co.uk\", \"vi\": \"Nguồn: hmontalbo@runklefencing.co.uk\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Date: 9 August\", \"vi\": \"Ngày: 9 tháng 8\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Subject: Quote Number 080817\", \"vi\": \"Chủ đề: Số báo giá 080817\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 fencequote_mcarhart\", \"vi\": \"Tệp đính kèm: 📎 fencequote_mcarhart\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Dear Ms. Carhart,\", \"vi\": \"Kính gửi bà Carhart,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Thank you for your enquiry.\", \"vi\": \"Xin cảm ơn quý vị đã gửi yêu cầu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Please see the attached estimate for the work you requested.\", \"vi\": \"Kính mời Quý vị tham khảo bản dự toán đính kèm cho công việc mà Quý vị đã yêu cầu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Note that the price of delivery is included at no further charge unless a rush order—one providing less than three weeks\' notice—is required.\", \"vi\": \"Xin lưu ý rằng chi phí giao hàng đã được tính vào giá và quý khách sẽ không phải trả thêm bất kỳ khoản phí nào, trừ khi quý khách có yêu cầu đơn hàng gấp — tức là đơn hàng được đặt với thời gian thông báo dưới ba tuần.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"This is a rough estimate based on the information you provided.\", \"vi\": \"Đây là một ước tính sơ bộ dựa trên thông tin mà quý vị đã cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"If you ring us at (0117) 555-2938 and provide us with a missing detail, I can give you a more accurate quote.\", \"vi\": \"Nếu quý vị gọi cho chúng tôi theo số (0117) 555-2938 và cung cấp thêm thông tin còn thiếu, tôi có thể đưa ra báo giá chính xác hơn cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"You might also consider including a plastic curtain with your order.\", \"vi\": \"Quý vị cũng có thể cân nhắc thêm một tấm rèm nhựa vào đơn hàng của mình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"This would be wrapped around and fastened to the fence, hiding the construction site from the view of pedestrians.\", \"vi\": \"Vật liệu này sẽ được quấn quanh và buộc chặt vào hàng rào, nhằm che khuất công trường khỏi tầm nhìn của người đi bộ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"If this interests you, we can include it in the revised quote.\", \"vi\": \"Nếu quý vị quan tâm đến điều này, chúng tôi có thể đưa nội dung này vào bản báo giá sửa đổi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Best Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Howard Montalbo\", \"vi\": \"Howard Montalbo\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}]' WHERE `id` = '41c9f58a-9545-48be-9a10-c80c8a6a8acb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Asherton Garden Fair\", \"vi\": \"Hội chợ Vườn Asherton\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The City of Asherton proudly presents a Garden Fair\", \"vi\": \"Thành phố Asherton hân hạnh giới thiệu Hội chợ Vườn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"on the grounds of Asherton Manor\", \"vi\": \"trong khuôn viên của Asherton Manor\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Saturday, June 10\", \"vi\": \"Thứ Bảy, ngày 10 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"11:00 A.M. to 5:00 P.M.\", \"vi\": \"Từ 11 giờ sáng đến 5 giờ chiều\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Free admission includes\", \"vi\": \"Vé vào cửa miễn phí bao gồm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Children\'s games, crafts, and local bands\", \"vi\": \"Các trò chơi dành cho trẻ em, các hoạt động thủ công và các ban nhạc địa phương\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Shuttle buses from nearby Asherton Train and Bus Station\", \"vi\": \"Xe buýt đưa đón từ Ga Tàu và Xe buýt Asherton gần đó\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Plants and seeds for sale\", \"vi\": \"Cây trồng và hạt giống đang được bán\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Refreshments for purchase—hot and cold beverages, cakes, sandwiches, and more!\", \"vi\": \"Các món ăn nhẹ có bán tại đây — đồ uống nóng và lạnh, bánh ngọt, bánh mì kẹp và nhiều món khác nữa!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Tours of Asherton Manor available for a small fee\", \"vi\": \"Quý vị có thể tham quan Asherton Manor với một khoản phí nhỏ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Parking available at the manor for $10 per vehicle\", \"vi\": \"Có chỗ đỗ xe tại khu biệt thự với mức phí 10 đô la cho mỗi phương tiện\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"For more information:\", \"vi\": \"Để biết thêm thông tin:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"416-555-0187\", \"vi\": \"416-555-0187\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '41ca5b47-6bd2-4a7b-a603-f82476f847e6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Axel Thorne (9:13 A.M.)\", \"vi\": \"Axel Thorne (9 giờ 13 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi everyone.\", \"vi\": \"Xin chào quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Our staff meeting scheduled for 3 P.M. today has been postponed until next week.\", \"vi\": \"Cuộc họp nội bộ dự kiến diễn ra vào lúc 3 giờ chiều hôm nay đã được hoãn lại đến tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Deanna Dahl (9:14 A.M.)\", \"vi\": \"Deanna Dahl (9 giờ 14 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Will it be at the same time next Tuesday?\", \"vi\": \"Liệu vào thứ Ba tuần sau có phải vào cùng khung giờ đó không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Axel Thorne (9:15 A.M.)\", \"vi\": \"Axel Thorne (9 giờ 15 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"That\'s right, and the same place, in the conference room on the first floor.\", \"vi\": \"Đúng vậy, và cũng chính tại địa điểm đó, trong phòng hội nghị ở tầng một.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Deanna Dahl (9:16 A.M.)\", \"vi\": \"Deanna Dahl (9 giờ 16 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I\'m going to be on vacation next week.\", \"vi\": \"Tuần tới tôi sẽ đi nghỉ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Could you send me the meeting minutes, please?\", \"vi\": \"Xin quý vị vui lòng gửi cho tôi biên bản cuộc họp được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Axel Thorne (9:17 A.M.)\", \"vi\": \"Axel Thorne (9 giờ 17 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"No problem.\", \"vi\": \"Không sao đâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I\'ll take care of that.\", \"vi\": \"Tôi sẽ lo việc đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Enjoy your vacation.\", \"vi\": \"Chúc quý vị có một kỳ nghỉ vui vẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Deanna Dahl (9:19 A.M.)\", \"vi\": \"Deanna Dahl (9 giờ 19 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thanks!\", \"vi\": \"Cảm ơn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I\'ll review everything you talked about when I get back.\", \"vi\": \"Khi tôi trở về, tôi sẽ xem xét lại tất cả những điều mà quý vị đã đề cập.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '41ebf3f3-fe16-4f26-84fd-56ea979fef73';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Make your mark with your logo on our products!\", \"vi\": \"Hãy để lại dấu ấn của quý vị bằng cách in logo lên các sản phẩm của chúng tôi!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"https://www.brandmarkproductsinc.com\", \"vi\": \"https://www.brandmarkproductsinc.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"About - Products - Start Here - Contact Us\", \"vi\": \"Giới thiệu - Sản phẩm - Bắt đầu từ đây - Liên hệ với chúng tôi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"There is no better way to advertise your organization than with our attractive fashion apparel featuring your logo or company slogan.\", \"vi\": \"Không có cách nào tốt hơn để quảng bá tổ chức của quý vị bằng những sản phẩm thời trang bắt mắt của chúng tôi, trên đó in logo hoặc khẩu hiệu của công ty quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Provide us with your logo file, and Brandmark Products, Inc., will adorn selected items and deliver your order within four business days.\", \"vi\": \"Xin vui lòng cung cấp cho chúng tôi tệp logo của quý vị; Brandmark Products, Inc. sẽ in logo lên các mặt hàng đã chọn và giao đơn hàng của quý vị trong vòng bốn ngày làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We will produce your order with color printing or embroidery of the highest quality.\", \"vi\": \"Chúng tôi sẽ gia công đơn hàng của quý khách bằng phương pháp in màu hoặc thêu với chất lượng cao nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our 25 years in operation have revealed one important fact about developing name recognition.\", \"vi\": \"25 năm hoạt động của chúng tôi đã cho thấy một thực tế quan trọng liên quan đến việc xây dựng độ nhận diện thương hiệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Forget water bottles and key chains—items that are frequently put aside or misplaced.\", \"vi\": \"Hãy quên đi những chiếc bình nước và móc chìa khóa — những vật dụng thường xuyên bị bỏ xó hoặc thất lạc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Your message will be more effective and longer lasting with our quality shirts, sweatshirts, jackets, and hats.\", \"vi\": \"Thông điệp của quý vị sẽ trở nên hiệu quả hơn và để lại ấn tượng lâu dài hơn nhờ những chiếc áo thun, áo nỉ, áo khoác và mũ chất lượng cao của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To place an order, use the “Start Here” tab or call 1-800-555-0155 to speak with a customer service representative.\", \"vi\": \"Để đặt hàng, quý khách vui lòng nhấp vào tab “Bắt đầu tại đây” hoặc gọi đến số 1-800-555-0155 để được nhân viên chăm sóc khách hàng tư vấn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '421a9ecc-a832-4269-ad99-4705206b43d1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Welcome to the Westover Zoo!\", \"vi\": \"Chào mừng quý vị đến với Vườn thú Westover!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Admission tickets are required for all visitors, including infants.\", \"vi\": \"Tất cả du khách, kể cả trẻ sơ sinh, đều phải có vé vào cửa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Tickets may be printed or presented electronically.\", \"vi\": \"Quý vị có thể in vé hoặc xuất trình vé dưới dạng điện tử.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Your ticket is good only on the date indicated.\", \"vi\": \"Vé của quý vị chỉ có giá trị vào ngày được ghi trên vé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Exchanges may be requested up to 24 hours before the date on your ticket.\", \"vi\": \"Quý vị có thể yêu cầu đổi vé chậm nhất là 24 giờ trước ngày ghi trên vé của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"For exchanges and other information, visit our Web site, westoverzoo.org.\", \"vi\": \"Để biết thêm thông tin về các chương trình trao đổi và các nội dung khác, xin vui lòng truy cập trang web của chúng tôi tại westoverzoo.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our parking area is free but fills quickly.\", \"vi\": \"Bãi đỗ xe của chúng tôi miễn phí nhưng thường nhanh chóng hết chỗ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We encourage visitors to take public transportation.\", \"vi\": \"Chúng tôi khuyến khích quý khách sử dụng phương tiện giao thông công cộng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Buses on both the orange and the blue routes stop at the zoo entrance.\", \"vi\": \"Các xe buýt trên cả tuyến màu cam và tuyến màu xanh đều dừng tại cổng vào vườn thú.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"During the summer months, extra buses run on these routes to accommodate visitors.\", \"vi\": \"Trong những tháng mùa hè, các tuyến xe buýt này sẽ tăng cường thêm chuyến để phục vụ du khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '423b2fe7-4763-4e80-a485-012c18e2c578';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mayor Kowalik Announces Bus Driver Appreciation Day\", \"vi\": \"Thị trưởng Kowalik công bố “Ngày tri ân tài xế xe buýt”\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"FRECOSTA (April 2)—Mayor Ed Kowalik has declared April 21 the city\'s first ever Bus Driver Appreciation Day.\", \"vi\": \"FRECOSTA (ngày 2 tháng 4) — Thị trưởng Ed Kowalik đã tuyên bố ngày 21 tháng 4 là “Ngày Tri ân Tài xế Xe buýt” đầu tiên trong lịch sử thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Bus riders are asked to greet drivers with a warm hello and one of the city\'s specially designed thank-you cards, which can be printed out from www.frecosta.gov/transitappreciation.\", \"vi\": \"Quý hành khách đi xe buýt được đề nghị chào hỏi tài xế bằng một lời chào nồng nhiệt cùng một trong những tấm thiệp cảm ơn do thành phố thiết kế riêng, mà quý vị có thể in ra từ trang web www.frecosta.gov/transitappreciation.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"As an added gesture of gratitude, Mayor Kowalik will invite bus drivers to attend a sporting event free of charge next month.\", \"vi\": \"Để thể hiện thêm lòng biết ơn, Thị trưởng Kowalik sẽ mời các tài xế xe buýt tham dự một sự kiện thể thao miễn phí vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Because the city\'s population has increased over the past two years, Frecosta\'s bus drivers have had to cope with frequent changes to bus routes.\", \"vi\": \"Do dân số thành phố đã tăng lên trong hai năm qua, các tài xế xe buýt của Frecosta đã phải thích ứng với những thay đổi thường xuyên về lộ trình xe buýt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"However, next year\'s long-anticipated opening of the Frecosta subway line is expected to alleviate some of the stress on drivers while creating more jobs.\", \"vi\": \"Tuy nhiên, việc khai trương tuyến tàu điện ngầm Frecosta vào năm tới – vốn được mong đợi từ lâu – dự kiến sẽ giúp giảm bớt phần nào áp lực cho các tài xế, đồng thời tạo ra thêm nhiều việc làm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The subway line will connect the Bargain Town Shopping Center on the western end of the city with Frecosta Stadium, which is located on the eastern end.\", \"vi\": \"Tuyến tàu điện ngầm này sẽ kết nối Trung tâm thương mại Bargain Town ở phía tây thành phố với Sân vận động Frecosta, tọa lạc ở phía đông thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"YOU\'RE INVITED!\", \"vi\": \"XIN MỜI QUÝ VỊ!\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Who: Frecosta Public Transit Services Employees\", \"vi\": \"Đối tượng: Nhân viên Dịch vụ Giao thông Công cộng Frecosta\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"What: Frecosta Kickers Football Game\", \"vi\": \"Sự kiện: Trận đấu bóng đá của đội Frecosta Kickers\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Where: Frecosta Stadium\", \"vi\": \"Địa điểm: Sân vận động Frecosta\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"When: May 7 at 2:00 P.M.\", \"vi\": \"Thời gian: Ngày 7 tháng 5, lúc 2 giờ chiều\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"In honor of your hard work for the city, we are pleased to offer FREE tickets to the Frecosta Kickers football game on May 7.\", \"vi\": \"Để tri ân những nỗ lực của quý vị dành cho thành phố, chúng tôi hân hạnh gửi tặng quý vị vé MIỄN PHÍ để tham dự trận đấu bóng đá của đội Frecosta Kickers vào ngày 7 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To download your e-tickets, visit www.frecostakickers.com/tickets and enter the discount code \\\"FPTS OFFER\\\" at checkout.\", \"vi\": \"Để tải xuống vé điện tử, quý vị vui lòng truy cập www.frecostakickers.com/tickets và nhập mã giảm giá “FPTS OFFER” khi thanh toán.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"This code will allow you to access one free ticket.\", \"vi\": \"Mã này sẽ giúp quý vị nhận được một vé miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"You may also purchase up to five guest tickets for family and friends at $7 each.\", \"vi\": \"Quý vị cũng có thể mua tối đa năm vé dành cho khách mời dành cho người thân và bạn bè với giá 7 đô la mỗi vé.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Please join us in the stadium clubhouse at 1:00 P.M. for a light snack before the game.\", \"vi\": \"Kính mời quý vị đến phòng tiếp khách của sân vận động vào lúc 1 giờ chiều để dùng một bữa ăn nhẹ trước trận đấu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"(Note: For transit employees and their guests only.)\", \"vi\": \"(Lưu ý: Chỉ dành cho nhân viên ngành giao thông công cộng và khách mời của họ.)\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '4243c54d-4a69-4381-be3f-e7d481b21c3b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dear Visitors:\", \"vi\": \"Kính gửi quý khách tham quan:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Heylin Park is a rugged wilderness site.\", \"vi\": \"Công viên Heylin là một khu vực hoang dã với địa hình hiểm trở.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Our trails are grassy and unpaved, and many contain protruding tree roots, rocks, and stumps.\", \"vi\": \"Các con đường mòn của chúng tôi được phủ cỏ và chưa được lát đá, đồng thời nhiều đoạn có rễ cây nhô lên, đá và gốc cây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Licensed park rangers will remove fallen debris if a trail becomes impassable, but in order to maintain a healthy habitat for wildlife, the land is otherwise kept in its natural state.\", \"vi\": \"Các nhân viên kiểm lâm được cấp phép sẽ dọn dẹp các mảnh vụn rơi rải rác nếu con đường mòn trở nên không thể đi qua được; tuy nhiên, nhằm duy trì một môi trường sống lành mạnh cho động vật hoang dã, khu vực này vẫn được giữ nguyên trạng tự nhiên trong các trường hợp khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"To support our efforts, we ask that you please take nothing home with you aside from photographs and memories.\", \"vi\": \"Để ủng hộ những nỗ lực của chúng tôi, chúng tôi kính mong quý vị vui lòng không mang bất cứ thứ gì về nhà, ngoại trừ những bức ảnh và những kỷ niệm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Please allow the flowers to grow wild and leave sticks and stones where they are.\", \"vi\": \"Xin hãy để những bông hoa tự do nở rộ và đừng di chuyển những cành cây hay hòn đá khỏi vị trí ban đầu của chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"If you would like to learn about the different trees, shrubs, and flowers growing in our park, you can join a free ranger-guided hike.\", \"vi\": \"Nếu quý vị muốn tìm hiểu về các loài cây, cây bụi và hoa khác nhau đang mọc trong công viên của chúng tôi, quý vị có thể tham gia chuyến đi bộ miễn phí do nhân viên kiểm lâm hướng dẫn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"These are held every Saturday from 2:00 p.m. to 3:30 p.m. Just add your name to the sign-up sheet at the check-in kiosk, located near the park entrance.\", \"vi\": \"Các hoạt động này được tổ chức vào mỗi thứ Bảy, từ 2 giờ chiều đến 3 giờ 30 chiều. Quý vị chỉ cần ghi tên vào bảng đăng ký tại quầy tiếp tân, nằm gần lối vào công viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Thank you and enjoy your hike!\", \"vi\": \"Xin cảm ơn và chúc quý vị có một chuyến đi bộ đường dài thật thú vị!\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Heylin Park Management\", \"vi\": \"Ban Quản lý Công viên Heylin\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '4253882c-41ed-45af-be6b-310932b5eb24';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Attention: Oxton Science Museum Visitors\", \"vi\": \"Kính gửi quý khách tham quan Bảo tàng Khoa học Oxton\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Gartner Wing of the museum is currently closed.\", \"vi\": \"Khu trưng bày Gartner của bảo tàng hiện đang đóng cửa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We apologize for the inconvenience.\", \"vi\": \"Chúng tôi xin lỗi vì sự bất tiện này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Please be patient as we prepare the space for our next exhibit, The Power of Light.\", \"vi\": \"Kính mong quý vị vui lòng kiên nhẫn chờ đợi trong khi chúng tôi đang chuẩn bị không gian cho triển lãm tiếp theo của chúng tôi, “Sức mạnh của Ánh sáng”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Designed by curator Sachiko Morishita, it explores innovations that will affect the future, particularly in the world of lasers and optics.\", \"vi\": \"Được thiết kế bởi nhà giám tuyển Sachiko Morishita, triển lãm này khám phá những đột phá công nghệ sẽ tác động đến tương lai, đặc biệt là trong lĩnh vực laser và quang học.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The exhibit will be open to members and private group tours starting August 15 and to the general public starting September 2.\", \"vi\": \"Triển lãm sẽ mở cửa cho các hội viên và các đoàn tham quan riêng từ ngày 15 tháng 8, và mở cửa cho công chúng từ ngày 2 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To: Summer Interns <interns@renmarksolutions.com>\", \"vi\": \"Gửi: Các thực tập sinh mùa hè <interns@renmarksolutions.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"From: Tae-Ho Mun <thmun@renmarksolutions.com>\", \"vi\": \"Từ: Tae-Ho Mun <thmun@renmarksolutions.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Date: July 7\", \"vi\": \"Ngày: 7 tháng 7\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Subject: August trip\", \"vi\": \"Chủ đề: Chuyến đi tháng Tám\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"9:00 A.M. - Meet in the company lobby (The bus departs at 9:15 A.M.)\", \"vi\": \"9 giờ sáng – Tập trung tại sảnh công ty (Xe buýt khởi hành lúc 9 giờ 15 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"10:00 A.M. to noon - Private group tour\", \"vi\": \"Từ 10 giờ sáng đến trưa - Chuyến tham quan theo nhóm riêng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Noon to 1:00 P.M. - Lunch in the museum restaurant\", \"vi\": \"Từ 12 giờ trưa đến 1 giờ chiều – Ăn trưa tại nhà hàng của bảo tàng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"1:45 to 2:00 P.M. - Meet in room 203\", \"vi\": \"1 giờ 45 phút đến 2 giờ chiều – Hẹn gặp tại phòng 203\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"3:15 P.M. - Bus leaves for the return to Renmark Solutions offices\", \"vi\": \"15 giờ 15 phút – Xe buýt khởi hành để trở về văn phòng của Renmark Solutions\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Good morning, team,\", \"vi\": \"Chào buổi sáng, các thành viên trong nhóm,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Interns and their mentors are invited to take a trip to the Oxton Science Museum on Friday, August 19.\", \"vi\": \"Các thực tập sinh và các cố vấn của họ được mời tham gia chuyến tham quan Bảo tàng Khoa học Oxton vào thứ Sáu, ngày 19 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Many of you have been on previous Renmark Solutions trips, so you know they are always educational and exciting.\", \"vi\": \"Nhiều quý vị trong số các vị đã từng tham gia các chuyến đi trước đây do Renmark Solutions tổ chức, nên chắc hẳn quý vị đều biết rằng những chuyến đi này luôn mang tính giáo dục và đầy thú vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Participants will get a look at the science and technology that drives our company and customers.\", \"vi\": \"Các đại biểu sẽ có cơ hội tìm hiểu về những thành tựu khoa học và công nghệ đang thúc đẩy sự phát triển của công ty chúng tôi cũng như của quý khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"We will see The Power of Light exhibit as part of our group tour.\", \"vi\": \"Chúng ta sẽ tham quan triển lãm “Sức mạnh của Ánh sáng” trong khuôn khổ chuyến tham quan theo đoàn của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Vouchers will be handed out for lunch at the museum\'s restaurant.\", \"vi\": \"Các phiếu ăn trưa sẽ được phát tại nhà hàng của bảo tàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Our schedule is as follows.\", \"vi\": \"Lịch trình của chúng tôi như sau.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Yours,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Tae-Ho Mun\", \"vi\": \"Mun Tae-Ho\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Research and Development Manager\", \"vi\": \"Trưởng phòng Nghiên cứu và Phát triển\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Time - Event Title - Event Description\", \"vi\": \"Thời gian - Tên sự kiện - Mô tả sự kiện\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"9:45 A.M. - \\\"Optical Systems and Applied Observation\\\" - Lecture by Professor Kaori Okada of Oxton University\", \"vi\": \"9 giờ 45 phút sáng - “Hệ thống quang học và quan sát ứng dụng” - Bài giảng của Giáo sư Kaori Okada, Đại học Oxton\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"10:30 A.M. - \\\"Quantum Optics\\\" - Presentation by Oxton Science Museum curator Wallace McCabe\", \"vi\": \"10 giờ 30 sáng - “Quang học lượng tử” - Buổi thuyết trình do ông Wallace McCabe, Giám tuyển của Bảo tàng Khoa học Oxton, trình bày\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"1:00 P.M. - \\\"Increasing the Use of Lasers\\\" - Presentation by Jee-Min Hahm of Solfis University\", \"vi\": \"13 giờ 00 – “Mở rộng việc ứng dụng công nghệ laser” – Bài thuyết trình của ông Jee-Min Hahm, Đại học Solfis\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"1:45 P.M. - Mirrors, Lenses, and Prisms - Short film by FK Institute of Technology\", \"vi\": \"13 giờ 45 phút – Gương, Thấu kính và Lăng kính – Phim ngắn của Viện Công nghệ FK\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"2:45 P.M. - \\\"New Platforms, New Products\\\" - Product demonstrations by Bigham Industries\", \"vi\": \"14 giờ 45 phút - “Nền tảng mới, sản phẩm mới” - Buổi trình diễn sản phẩm do Bigham Industries thực hiện\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Oxton Science Museum\", \"vi\": \"Bảo tàng Khoa học Oxton\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Viewing Room Schedule (Room 203)—August 19\", \"vi\": \"Lịch trình tham quan phòng (Phòng 203) — Ngày 19 tháng 8\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '42638126-f686-4b2f-ac04-12bc3b4cbcb0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Waypave Hardscapes\", \"vi\": \"Waypave – Công trình kiến trúc cảnh quan cứng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Finest in Residential Driveways, Walls, and Patios\", \"vi\": \"Các giải pháp hàng đầu về lối vào nhà, tường rào và sân hiên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"ESTIMATE: #20987\", \"vi\": \"BÁO GIÁ: Số 20987\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"DATE: 09/28\", \"vi\": \"NGÀY: 28/09\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"TOTAL AMOUNT: $4,000\", \"vi\": \"TỔNG SỐ TIỀN: 4.000 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"PREPARED FOR\", \"vi\": \"CHUẨN BỊ CHO\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Lurene Toyo\", \"vi\": \"Lurene Toyo\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"23000 S Henry Street\", \"vi\": \"23.000 S Henry Street\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Fairville, GA 30013\", \"vi\": \"Fairville, GA 30013\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"MATERIALS - RATE - QUANTITY - AMOUNT\", \"vi\": \"VẬT LIỆU - ĐƠN GIÁ - SỐ LƯỢNG - TỔNG GIÁ TRỊ\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Cement - $50 per bag - 5 - $250\", \"vi\": \"Xi măng - 50 đô la mỗi bao - 5 bao - 250 đô la\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Tropical Sunset tiles - $3 each - 500 - $1,500\", \"vi\": \"Gạch Tropical Sunset - 3 USD/viên - 500 viên - 1.500 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Delivery of materials - $350\", \"vi\": \"Chi phí vận chuyển vật liệu - 350 đô la\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Disposal of debris - $150\", \"vi\": \"Việc xử lý phế thải - 150 đô la\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Labor - $1,750\", \"vi\": \"Công việc - 1.750 đô la\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"TOTAL - $4,000\", \"vi\": \"TỔNG CỘNG - 4.000 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"JOB DESCRIPTION\", \"vi\": \"MÔ TẢ CÔNG VIỆC\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Remove grass and old concrete patio behind the house.\", \"vi\": \"Xin vui lòng dọn sạch cỏ và sân bê tông cũ phía sau ngôi nhà.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Lay a cement foundation for the new patio.\", \"vi\": \"Xây nền bê tông cho sân hiên mới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Install Tropical Sunset tiles per client\'s approved plan.\", \"vi\": \"Lắp đặt gạch Tropical Sunset theo bản vẽ đã được khách hàng phê duyệt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"TERMS\", \"vi\": \"ĐIỀU KHOẢN\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"$2,000 due upon signing of contract\", \"vi\": \"Phải thanh toán 2.000 USD khi ký hợp đồng\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"$2,000 due upon completion of project\", \"vi\": \"Số tiền 2.000 đô la sẽ được thanh toán khi dự án hoàn thành\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Payable by credit card, check, or bank transfer\", \"vi\": \"Quý khách có thể thanh toán bằng thẻ tín dụng, séc hoặc chuyển khoản ngân hàng\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"This estimate serves as your contract.\", \"vi\": \"Bản dự toán này sẽ đóng vai trò là hợp đồng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Please sign and return this document to estimates@waypavehardscapes.com.\", \"vi\": \"Kính mong Quý vị ký tên và gửi lại tài liệu này về địa chỉ estimates@waypavehardscapes.com.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '4265f883-632e-475a-bf5f-dfd7652e435f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Description - Full Page - Half Page - Quarter Page\", \"vi\": \"Mô tả - Trang toàn bộ - Nửa trang - Một phần tư trang\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Full year (12 months) - $4,165 - $2,200 - $1,700\", \"vi\": \"Cả năm (12 tháng) - 4.165 USD - 2.200 USD - 1.700 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Half year (6 months) - $2,550 - $1,120 - $780\", \"vi\": \"Nửa năm (6 tháng) - 2.550 USD - 1.120 USD - 780 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Quarter year (3 months) - $1,330 - $760 - $440\", \"vi\": \"Một quý (3 tháng) - 1.330 đô la - 760 đô la - 440 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"One-time advertisement - $440 - $300 - $150\", \"vi\": \"Quảng cáo một lần - 440 đô la - 300 đô la - 150 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Advertise with Lanark Theater!\", \"vi\": \"Hãy quảng cáo cùng Nhà hát Lanark!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"https://www.lanarktheater.org/advertise\", \"vi\": \"https://www.lanarktheater.org/advertise\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"When you place an advertisement in our printed programs, your business will be seen by thousands of our patrons.\", \"vi\": \"Khi quý vị đăng quảng cáo trên các ấn phẩm in của chúng tôi, doanh nghiệp của quý vị sẽ được hàng nghìn khách hàng của chúng tôi biết đến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Our upcoming season has just been announced, and we have an exciting lineup of theater, music, and dance groups that will perform throughout the year.\", \"vi\": \"Chương trình biểu diễn của mùa tới vừa được công bố, và chúng tôi hân hạnh giới thiệu một danh sách các đoàn kịch, âm nhạc và múa đầy hấp dẫn sẽ biểu diễn trong suốt cả năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You can feature your business in our programs for a full year or a partial year and also choose the size of your advertisement.\", \"vi\": \"Quý vị có thể quảng bá doanh nghiệp của mình trên các chương trình của chúng tôi trong cả năm hoặc một phần năm, đồng thời có thể lựa chọn kích thước quảng cáo phù hợp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The basic advertising options are as follows.\", \"vi\": \"Các tùy chọn quảng cáo cơ bản như sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Keep in mind that full-year advertisers receive a special discount card that is good for 15% off tickets for any Lanark Theater event for the duration of the advertising contract!\", \"vi\": \"Xin lưu ý rằng các nhà quảng cáo ký hợp đồng cả năm sẽ nhận được thẻ giảm giá đặc biệt, cho phép giảm 15% giá vé cho bất kỳ sự kiện nào tại Nhà hát Lanark trong suốt thời gian hiệu lực của hợp đồng quảng cáo!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To get started, submit an advertisement request form.\", \"vi\": \"Để bắt đầu, xin vui lòng gửi mẫu đơn yêu cầu đăng quảng cáo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We will contact you to help you select the most suitable advertising package.\", \"vi\": \"Chúng tôi sẽ liên hệ với quý vị để hỗ trợ quý vị lựa chọn gói quảng cáo phù hợp nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The request form can be found at www.lanarktheater.org/advertisement-request.\", \"vi\": \"Quý vị có thể truy cập vào địa chỉ www.lanarktheater.org/advertisement-request để tìm thấy mẫu đơn yêu cầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Lanark Theater\", \"vi\": \"Nhà hát Lanark\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Advertisement Request Form\", \"vi\": \"Mẫu đơn yêu cầu quảng cáo\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Name: Louise Sanderson\", \"vi\": \"Họ và tên: Louise Sanderson\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"E-mail: l.sanderson@stanmorebistro.com\", \"vi\": \"Email: l.sanderson@stanmorebistro.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Phone: 716-555-0145\", \"vi\": \"Điện thoại: 716-555-0145\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Company: Stanmore Bistro\", \"vi\": \"Công ty: Stanmore Bistro\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Have you advertised with us before? No\", \"vi\": \"Quý vị đã từng quảng cáo trên trang web của chúng tôi chưa? Chưa\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"How did you learn about this advertising opportunity?\", \"vi\": \"Quý vị đã biết đến cơ hội quảng cáo này qua đâu?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I frequently see performances at Lanark Theater.\", \"vi\": \"Tôi thường xuyên đến xem các buổi biểu diễn tại Nhà hát Lanark.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Not too long ago, I noticed that a friend\'s business is being advertised in your programs.\", \"vi\": \"Cách đây không lâu, tôi nhận thấy doanh nghiệp của một người bạn đang được quảng cáo trên các chương trình của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"He is the owner of Braedale Apparel, and he has highly recommended that I advertise my own business in your program as well.\", \"vi\": \"Ông là chủ sở hữu của Braedale Apparel, và ông đã nhiệt tình khuyến nghị tôi nên quảng cáo doanh nghiệp của mình trên chương trình của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I certainly think that Lanark Theater patrons would enjoy dining at my bistro!\", \"vi\": \"Tôi tin chắc rằng quý vị khán giả của Nhà hát Lanark sẽ rất thích dùng bữa tại quán ăn nhỏ của tôi!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"What type of advertisement are you interested in?\", \"vi\": \"Quý vị quan tâm đến loại hình quảng cáo nào?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Full year ___ Half year X Quarter year ___ One-time ___ Not sure ___\", \"vi\": \"Cả năm ___ Nửa năm X Quý ___ Một lần ___ Không chắc chắn ___\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"What is your maximum budget?\", \"vi\": \"Ngân sách tối đa của quý vị là bao nhiêu?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"$850\", \"vi\": \"850 đô la\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"To: Maciej Ritchie <m.ritchie@braedaleapparel.com>\", \"vi\": \"Người gửi: Maciej Ritchie <m.ritchie@braedaleapparel.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"From: Rosa Chokphel <rosa.chokphel@lanarktheater.org>\", \"vi\": \"Từ: Rosa Chokphel <rosa.chokphel@lanarktheater.org>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Subject: Advertisement renewal\", \"vi\": \"Chủ đề: Gia hạn quảng cáo\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Date: December 13\", \"vi\": \"Ngày: 13 tháng 12\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Dear Mr. Ritchie,\", \"vi\": \"Kính gửi ông Ritchie,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Thank you for renewing Braedale Apparel\'s advertisement package for the upcoming season.\", \"vi\": \"Xin chân thành cảm ơn Quý khách đã gia hạn gói quảng cáo của Braedale Apparel cho mùa tới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"You are once again confirmed for a quarter-page advertisement for the full year.\", \"vi\": \"Chúng tôi xin xác nhận lại rằng quý vị đã được phê duyệt đặt quảng cáo một phần tư trang cho cả năm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"We at Lanark Theater could not fulfill our mission of offering the community rich and thought-provoking artistic performances without the help of local businesses like yours!\", \"vi\": \"Chúng tôi tại Nhà hát Lanark sẽ không thể hoàn thành sứ mệnh mang đến cho cộng đồng những buổi biểu diễn nghệ thuật phong phú và khơi gợi suy ngẫm nếu thiếu sự hỗ trợ từ các doanh nghiệp địa phương như quý vị!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"We also want to thank you for your recent referral.\", \"vi\": \"Chúng tôi cũng xin gửi lời cảm ơn quý vị về việc giới thiệu khách hàng gần đây.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Because of your recommendation, Louise Sanderson will be advertising in our programs.\", \"vi\": \"Nhờ sự giới thiệu của quý vị, Louise Sanderson sẽ đăng quảng cáo trên các chương trình của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Your support is greatly appreciated!\", \"vi\": \"Chúng tôi vô cùng trân trọng sự ủng hộ của quý vị!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"All the best,\", \"vi\": \"Chúc quý vị mọi điều tốt đẹp nhất,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Rosa Chokphel\", \"vi\": \"Hoa hồng sa mạc\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"Marketing Associate, Lanark Theater\", \"vi\": \"Chuyên viên Tiếp thị, Nhà hát Lanark\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}]' WHERE `id` = '42882990-3091-44c2-be8c-46c39e47e9b9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Omar Balaji <obalaji@darbourycompany.com>\", \"vi\": \"Người gửi: Omar Balaji <obalaji@darbourycompany.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Juanita Pereira <jpereira@bunbunbooks.com>\", \"vi\": \"Từ: Juanita Pereira <jpereira@bunbunbooks.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 10\", \"vi\": \"Ngày: 10 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Notebook inquiry\", \"vi\": \"Chủ đề: Yêu cầu thông tin về máy tính xách tay\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Cover Design Name - Central Image - Background Color\", \"vi\": \"Tên thiết kế bìa - Hình ảnh chính - Màu nền\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Great Thoughts - Lightbulb, lightning bolt, and star icons - Blue\", \"vi\": \"Những ý tưởng tuyệt vời - Biểu tượng bóng đèn, tia chớp và ngôi sao - Màu xanh dương\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"World Suitcase - Suitcase with country name travel stickers - Black\", \"vi\": \"World Suitcase - Vali có dán nhãn du lịch in tên các quốc gia - Màu đen\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Lavender Bouquet - Large bunch of lavender on tall, pale green stems - Yellow\", \"vi\": \"Bó hoa oải hương - Bó hoa oải hương lớn với những cành cao màu xanh nhạt - Màu vàng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Sail Away - Sun setting in the sky above a sailboat on a lake - White\", \"vi\": \"Sail Away - Hoàng hôn buông xuống trên bầu trời phía trên một chiếc thuyền buồm trên hồ - Màu trắng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Dear Mr. Balaji,\", \"vi\": \"Kính gửi ông Balaji,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We are expanding our office supply section at Bun Bun Books and would like to offer a selection of blank notebooks with lined pages.\", \"vi\": \"Chúng tôi đang mở rộng khu vực đồ dùng văn phòng tại Bun Bun Books và mong muốn giới thiệu đến quý khách một số mẫu sổ tay trống có trang kẻ dòng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We would like your help creating the following cover designs.\", \"vi\": \"Chúng tôi mong nhận được sự hỗ trợ của quý vị trong việc thiết kế các mẫu bìa sau đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We need to have notebooks in stock in time for our annual sale starting August 1.\", \"vi\": \"Chúng ta cần phải chuẩn bị sẵn sổ tay trong kho để kịp cho đợt giảm giá hàng năm bắt đầu từ ngày 1 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"After approving the sample covers, when would we need to place our order?\", \"vi\": \"Sau khi phê duyệt các mẫu bìa, chúng ta sẽ cần đặt hàng vào thời điểm nào?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Juanita Pereira\", \"vi\": \"Juanita Pereira\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"To: Juanita Pereira <jpereira@bunbunbooks.com>\", \"vi\": \"Gửi tới: Juanita Pereira <jpereira@bunbunbooks.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"From: Omar Balaji <obalaji@darbourycompany.com>\", \"vi\": \"Từ: Omar Balaji <obalaji@darbourycompany.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Date: May 25\", \"vi\": \"Ngày: 25 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Subject: Re: Notebook inquiry\", \"vi\": \"Chủ đề: Trả lời: Yêu cầu thông tin về máy tính xách tay\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Item code - Product Description - Cover Design - Amount\", \"vi\": \"Mã sản phẩm - Mô tả sản phẩm - Thiết kế bìa - Số lượng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"N3-GT - Standard-size spiral notebook - Great Thoughts - 200\", \"vi\": \"N3-GT - Sổ tay xoắn ốc cỡ tiêu chuẩn - Great Thoughts - 200\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"N3-WS - Standard-size spiral notebook - World Suitcase - 200\", \"vi\": \"N3-WS - Sổ tay xoắn ốc cỡ tiêu chuẩn - World Suitcase - 200\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"H3-LB - Small hardbound journal notebook - Lavender Bouquet - 150\", \"vi\": \"H3-LB - Sổ tay nhỏ bìa cứng - Bó hoa oải hương - 150\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"H3-SA - Small hardbound journal notebook - Sail Away - 150\", \"vi\": \"H3-SA - Sổ tay nhỏ bìa cứng - Sail Away - 150\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"D1 - Large metal display rack\\n(holds standard-size spiral notebooks) - — - 1\", \"vi\": \"D1 - Kệ trưng bày kim loại cỡ lớn\\n(dùng để trưng bày sổ tay xoắn ốc cỡ tiêu chuẩn) - — - 1\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Darboury Company\", \"vi\": \"Công ty Darboury\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Order Form\", \"vi\": \"Mẫu đơn đặt hàng\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Hello, Ms. Pereira,\", \"vi\": \"Xin chào, bà Pereira,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I have shipped some sample notebook covers for your inspection.\", \"vi\": \"Tôi đã gửi một số mẫu bìa sổ tay để quý vị xem xét.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Unfortunately, I was not able to include one of the designs for your approval because it needed a late-stage change to the background color.\", \"vi\": \"Rất tiếc, tôi không thể gửi kèm một trong các bản thiết kế để quý vị xem xét vì bản thiết kế đó cần điều chỉnh màu nền ở giai đoạn cuối.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"The sticker art did not show up well against the original black background.\", \"vi\": \"Hình ảnh trên nhãn dán không nổi bật lắm trên nền đen ban đầu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"We are testing a light-beige color, and I will send the updated sample cover to you after it has been approved internally.\", \"vi\": \"Chúng tôi đang thử nghiệm màu be nhạt, và tôi sẽ gửi mẫu bìa cập nhật cho quý vị sau khi mẫu này được phê duyệt nội bộ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"I should have the last sample to you by the end of this week.\", \"vi\": \"Tôi sẽ gửi mẫu cuối cùng cho quý vị trước cuối tuần này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"As long as you send your approval of all covers by June 11, we will be able to ship your entire order of bound notebooks before July 20.\", \"vi\": \"Miễn là quý vị gửi xác nhận chấp thuận tất cả các mẫu bìa trước ngày 11 tháng 6, chúng tôi sẽ có thể giao toàn bộ đơn hàng sổ tay đóng gáy của quý vị trước ngày 20 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"You will have everything before your sale that begins on August 1.\", \"vi\": \"Quý vị sẽ có đầy đủ mọi thứ trước khi đợt bán hàng bắt đầu vào ngày 1 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Please contact me if you have any questions.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào, xin vui lòng liên hệ với tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Omar Balaji, Darboury Company\", \"vi\": \"Ông Omar Balaji, Công ty Darboury\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Customer: Bun Bun Books\", \"vi\": \"Khách hàng: Bun Bun Books\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Ship by: July 15\", \"vi\": \"Giao hàng trước ngày: 15 tháng 7\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Shipping method: Standard\", \"vi\": \"Phương thức vận chuyển: Tiêu chuẩn\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Requested delivery date: July 20\", \"vi\": \"Ngày giao hàng dự kiến: 20 tháng 7\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}]' WHERE `id` = '428e81cd-4331-4327-a918-8f9304b92538';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.kennonhotel.co.uk\", \"vi\": \"http://www.kennonhotel.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"An Announcement from Rosalie Willis, CEO of Kennon Hotel\", \"vi\": \"Thông báo từ bà Rosalie Willis, Tổng Giám đốc Khách sạn Kennon\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Helpline: 1-800-555-9056\", \"vi\": \"Đường dây hỗ trợ: 1-800-555-9056\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Many of our valued customers have been affected by the computer glitch that caused rooms at our hotel to be double-booked.\", \"vi\": \"Nhiều quý khách hàng thân thiết của chúng tôi đã bị ảnh hưởng bởi sự cố kỹ thuật khiến các phòng tại khách sạn của chúng tôi bị đặt trùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We assure you that we are doing everything we can to minimize the negative effects of the situation.\", \"vi\": \"Chúng tôi xin cam đoan với quý vị rằng chúng tôi đang nỗ lực hết sức để giảm thiểu những tác động tiêu cực của tình hình này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Customers whom we are not able to accommodate at our site will be booked at nearby hotels in rooms of equivalent or greater size and quality, still paying only the originally quoted rate.\", \"vi\": \"Những khách hàng mà chúng tôi không thể sắp xếp chỗ ở tại cơ sở của mình sẽ được đặt phòng tại các khách sạn lân cận với các phòng có diện tích và chất lượng tương đương hoặc cao hơn, đồng thời vẫn chỉ phải thanh toán mức giá đã báo ban đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In addition, customers usually must cancel at least 48 hours before their scheduled check-in time to avoid being charged for the first night\'s stay.\", \"vi\": \"Ngoài ra, quý khách thường phải hủy đặt phòng ít nhất 48 giờ trước thời gian nhận phòng đã định để tránh bị tính phí cho đêm lưu trú đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"For the next three weeks, this will be changed to 24 hours.\", \"vi\": \"Trong ba tuần tới, thời gian này sẽ được điều chỉnh thành 24 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '4313e453-1dba-465e-95ee-5057a54a021f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Quick Fix Workshops\", \"vi\": \"Các buổi hội thảo “Giải pháp nhanh”\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Join Hagerstown residents at the community center on January 15 for our Quick Fix workshop series.\", \"vi\": \"Kính mời quý vị cùng tham gia với cư dân Hagerstown tại trung tâm cộng đồng vào ngày 15 tháng 1 để tham dự chuỗi hội thảo “Quick Fix” của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"There is sure to be at least one topic that will interest you.\", \"vi\": \"Chắc chắn sẽ có ít nhất một chủ đề khiến quý vị cảm thấy hứng thú.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"For example, you might learn how to economize financially without inhibiting your lifestyle or to discover ways of reducing your impact on the environment by living smarter.\", \"vi\": \"Ví dụ, quý vị có thể học cách tiết kiệm chi tiêu mà không phải hy sinh lối sống của mình, hoặc khám phá những cách thức giảm thiểu tác động của bản thân đối với môi trường thông qua lối sống thông minh hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Alternatively, by attending a workshop, you may find inspiration for improving the health and well-being of your family.\", \"vi\": \"Ngoài ra, thông qua việc tham dự một hội thảo, quý vị có thể tìm thấy nguồn cảm hứng để cải thiện sức khỏe và chất lượng cuộc sống cho gia đình mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our own Grant Cardwell, prominent and long-time Hagerstown resident, will be leading a session on weatherizing your home.\", \"vi\": \"Ông Grant Cardwell, một cư dân nổi tiếng và đã sinh sống lâu năm tại Hagerstown, sẽ chủ trì một buổi chia sẻ về việc cách nhiệt cho ngôi nhà của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Arrive early to secure a seat for that one since nearly everyone is eager to learn how to trim their heating and cooling bills.\", \"vi\": \"Hãy đến sớm để đảm bảo có chỗ ngồi tham dự buổi hội thảo này, bởi hầu như ai cũng rất mong muốn tìm hiểu cách cắt giảm hóa đơn tiền điện cho hệ thống sưởi ấm và làm mát.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Registration is not required, although we will record attendance.\", \"vi\": \"Quý vị không cần phải đăng ký trước, tuy nhiên chúng tôi sẽ ghi nhận số lượng người tham dự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"For questions, contact Mike Greenly at m.greenly@hagerstown.gov.\", \"vi\": \"Nếu có thắc mắc, xin vui lòng liên hệ với ông Mike Greenly qua địa chỉ email m.greenly@hagerstown.gov.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Time - Workshop\", \"vi\": \"Thời gian - Buổi hội thảo\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"10:00 A.M. - Weatherization – Make your home more energy efficient by learning from an expert from the Marion County Regional Weatherization Initiative (MCRWI).\\nSave Water and Your Wallet – Find out about the Hagerstown water supply and get tips for limiting consumption and reducing your monthly water utility bills.\", \"vi\": \"10:00 sáng – Cách nhiệt – Hãy giúp ngôi nhà của quý vị tiết kiệm năng lượng hơn bằng cách học hỏi từ chuyên gia thuộc Sáng kiến Cách nhiệt Khu vực Hạt Marion (MCRWI).\\nTiết kiệm nước và chi phí – Tìm hiểu về hệ thống cấp nước của Hagerstown và nhận các mẹo để hạn chế lượng nước tiêu thụ cũng như giảm hóa đơn tiền nước hàng tháng của quý vị.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"11:00 A.M. - DIY Personal Care Products – Make your own everyday personal care products, such as deodorant, soap, and skin moisturizer.\", \"vi\": \"11 giờ sáng – Tự làm các sản phẩm chăm sóc cá nhân – Hãy tự tay làm các sản phẩm chăm sóc cá nhân dùng hàng ngày, chẳng hạn như chất khử mùi, xà phòng và kem dưỡng ẩm cho da.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"1:00 P.M. - Creating Natural Spaces – Grow native plants and learn about nurturing the local ecosystem. Help build a naturally sustainable habitat right in your own garden or yard.\", \"vi\": \"13h00 – Tạo dựng không gian tự nhiên – Trồng các loài cây bản địa và tìm hiểu cách chăm sóc hệ sinh thái địa phương. Hãy cùng góp phần xây dựng một môi trường sống bền vững theo tự nhiên ngay trong khu vườn hoặc sân nhà của quý vị.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"2:00 P.M. - A New Year, a Healthier You – See demonstrations on creating delicious and healthy meals for your family. Samples will be provided.\\nEssential Maintenance – Keep your vehicle in top driving condition despite harsh winter weather.\", \"vi\": \"14:00 – Năm mới, một bạn khỏe mạnh hơn – Hãy tham gia các buổi trình diễn về cách chế biến những bữa ăn ngon miệng và tốt cho sức khỏe dành cho gia đình quý vị. Sẽ có phần nếm thử miễn phí.\\nBảo dưỡng thiết yếu – Giữ cho chiếc xe của quý vị luôn ở trạng thái vận hành tốt nhất dù thời tiết mùa đông khắc nghiệt.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Quick Fix Workshop Series - Schedule\", \"vi\": \"Chuỗi hội thảo “Quick Fix” - Lịch trình\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To: Mike Greenly\", \"vi\": \"Kính gửi: Mike Greenly\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"From: Antonio Perkins\", \"vi\": \"Từ: Antonio Perkins\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date: January 12\", \"vi\": \"Ngày: 12 tháng 1\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Subject: Inquiry\", \"vi\": \"Chủ đề: Yêu cầu thông tin\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Dear Mr. Greenly,\", \"vi\": \"Kính gửi ông Greenly,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I recently moved to Hagerstown, and I am interested in learning about the native vegetation in the area.\", \"vi\": \"Gần đây tôi vừa chuyển đến Hagerstown, và tôi rất quan tâm đến việc tìm hiểu về hệ thực vật bản địa trong khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I have a lot of experience growing trees and plants in my former hometown, but the varieties that grow here are completely different.\", \"vi\": \"Tôi có rất nhiều kinh nghiệm trồng cây cối và thực vật tại quê hương cũ của mình, nhưng các giống cây mọc ở đây lại hoàn toàn khác biệt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"A neighbor mentioned that there would be a session related to gardening, but do any of the workshops address my specific interest in learning about the native flora and fauna?\", \"vi\": \"Một người hàng xóm có nhắc đến việc sẽ có một buổi thảo luận liên quan đến làm vườn, nhưng liệu có buổi hội thảo nào đề cập đến sở thích cụ thể của tôi là tìm hiểu về hệ thực vật và động vật bản địa không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Antonio Perkins\", \"vi\": \"Antonio Perkins\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '43617e28-4cce-4cc9-a39b-a20c3e0029f9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Clean House Janitorial Services\", \"vi\": \"Dịch vụ vệ sinh Clean House\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Copper County\'s trustworthy and efficient cleaning solution since 1972\", \"vi\": \"Giải pháp vệ sinh đáng tin cậy và hiệu quả tại Hạt Copper kể từ năm 1972\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"NEW CUSTOMER PROMOTION\", \"vi\": \"CHƯƠNG TRÌNH KHUYẾN MÃI DÀNH CHO KHÁCH HÀNG MỚI\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"*Copper County residents ONLY\", \"vi\": \"*CHỈ dành cho cư dân Hạt Copper*\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Save 15%\", \"vi\": \"Tiết kiệm 15%\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"on your first year of home cleanings!\", \"vi\": \"dành cho năm đầu tiên quý khách sử dụng dịch vụ dọn dẹp nhà cửa!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"*Carpet-cleaning service NOT included\", \"vi\": \"*Dịch vụ giặt thảm KHÔNG bao gồm trong gói\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Call 916-555-0137 today for details and to schedule your first service.\", \"vi\": \"Hãy gọi ngay số 916-555-0137 hôm nay để biết thêm chi tiết và đặt lịch cho lần sử dụng dịch vụ đầu tiên của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Offer valid through December 31\", \"vi\": \"Chương trình khuyến mãi có hiệu lực đến hết ngày 31 tháng 12\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '43988666-b12b-496f-b732-7a87e2006dd6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Alan Porto <aporto@silverwing.ky>\", \"vi\": \"Đến: Alan Porto <aporto@silverwing.ky>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Tuchman\'s Billing <billing@tuchmans.ky>\", \"vi\": \"Từ: Bộ phận Thanh toán Tuchman\'s <billing@tuchmans.ky>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Autopay\", \"vi\": \"Chủ đề: Thanh toán tự động\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 19 February\", \"vi\": \"Ngày: 19 tháng Hai\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Porto:\", \"vi\": \"Kính gửi ông Porto:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Congratulations on your recent ______[139] in Tuchman\'s Autopay system.\", \"vi\": \"Chúc mừng bạn đã ______[139] gần đây trong hệ thống Thanh toán tự động của Tuchman.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [139]}, {\"en\": \"Thank you for signing up for this convenient billing system.\", \"vi\": \"Cảm ơn bạn đã đăng ký sử dụng hệ thống thanh toán tiện lợi này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Your automatic payments will begin with the next billing cycle on 1 March.\", \"vi\": \"Các khoản thanh toán tự động của bạn sẽ bắt đầu vào kỳ thanh toán tiếp theo vào ngày 1 tháng Ba.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[140].\", \"vi\": \"______[140].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [140]}, {\"en\": \"Your statements will come to you electronically and your payment will be deducted from your designated bank account.\", \"vi\": \"Bảng sao kê của bạn sẽ được gửi qua đường điện tử và khoản thanh toán sẽ được trừ vào tài khoản ngân hàng chỉ định của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"You may ______[141] the account from which the funds are withdrawn.\", \"vi\": \"Bạn có thể ______[141] tài khoản mà từ đó tiền được rút ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [141]}, {\"en\": \"Simply log in to the My Account section on our Web site https://www.tuchmans.ky, select Autopay, and follow the instructions to enter the alternate account information.\", \"vi\": \"Chỉ cần đăng nhập vào mục Tài khoản của tôi trên trang web https://www.tuchmans.ky, chọn Thanh toán tự động, và làm theo hướng dẫn để nhập thông tin tài khoản thay thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Please contact customer service if you have ______[142] using Tuchman\'s Autopay.\", \"vi\": \"Vui lòng liên hệ với bộ phận dịch vụ khách hàng nếu bạn gặp ______[142] khi sử dụng tính năng Thanh toán tự động của Tuchman.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [142]}, {\"en\": \"Tuchman\'s Billing Department\", \"vi\": \"Bộ phận Thanh toán Tuchman\'s\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '439ead46-1ed2-4553-bac2-8a4597e003a8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"City - OTP\", \"vi\": \"City - OTP\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Kelton Falls - 52%\", \"vi\": \"Kelton Falls - 52%\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Grangerton - 68%\", \"vi\": \"Grangerton - 68%\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Satcherville - 79%\", \"vi\": \"Satcherville - 79%\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Barbour City - 64%\", \"vi\": \"Barbour City - 64%\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Zealandia Airlines Fact Sheet for Fiscal Year Ending 30 June\", \"vi\": \"Tờ thông tin về Hãng hàng không Zealandia cho năm tài chính kết thúc vào ngày 30 tháng 6\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Service Levels and Capacity: Zealandia Airlines provides regional service among four cities.\", \"vi\": \"Mức độ dịch vụ và công suất: Hãng hàng không Zealandia cung cấp dịch vụ bay nội địa giữa bốn thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In each case, average flight capacity exceeded the company goal of 85 percent.\", \"vi\": \"Trong từng trường hợp, công suất trung bình của các chuyến bay đều vượt quá mục tiêu 85% mà công ty đề ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"On-Time Performance (OTP): For the purpose of measuring OTP, flights are considered “on time” when they reach their destination within fifteen minutes of the scheduled arrival time.\", \"vi\": \"Tỷ lệ đúng giờ (OTP): Để đo lường chỉ số OTP, các chuyến bay được coi là “đúng giờ” khi đến điểm đến trong vòng mười lăm phút so với giờ đến dự kiến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Regional airlines are subject to fines when OTP drops below 50 percent.\", \"vi\": \"Các hãng hàng không khu vực sẽ bị phạt nếu tỷ lệ đúng giờ (OTP) giảm xuống dưới 50%.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The following chart shows Zealandia’s commendable OTP rates for the recent fiscal year.\", \"vi\": \"Biểu đồ dưới đây cho thấy tỷ lệ OTP đáng khen ngợi của Zealandia trong năm tài chính vừa qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Proposed Expansion: Zealandia Airlines provides regional passenger air service and is seeking to expand its fleet to begin providing commercial airfreight delivery.\", \"vi\": \"Kế hoạch mở rộng: Hãng hàng không Zealandia chuyên cung cấp dịch vụ vận chuyển hành khách nội địa và hiện đang có kế hoạch mở rộng đội bay để bắt đầu cung cấp dịch vụ vận chuyển hàng hóa thương mại bằng đường hàng không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Establishing this service is a component of the airline’s growth plan and corporate vision.\", \"vi\": \"Việc triển khai dịch vụ này là một phần trong kế hoạch phát triển và tầm nhìn chiến lược của hãng hàng không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The airline is currently in negotiations with aviation authorities to explore options.\", \"vi\": \"Hiện tại, hãng hàng không này đang tiến hành đàm phán với các cơ quan quản lý hàng không nhằm xem xét các phương án khả thi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Terminal and Service Improvements: Zealandia Airlines is participating in discussions with airport management about comprehensive renovations to its passenger lounge and café and has offered to commit $5 million from its budget to the project.\", \"vi\": \"Các cải tiến về nhà ga và dịch vụ: Hãng hàng không Zealandia Airlines đang tham gia các cuộc thảo luận với ban quản lý sân bay về việc cải tạo toàn diện khu vực phòng chờ hành khách và quán cà phê của hãng, đồng thời đã đề xuất dành 5 triệu đô la từ ngân sách của mình cho dự án này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Company executives have also finalized a plan and committed funds to overhaul its rewards program.\", \"vi\": \"Ban lãnh đạo công ty cũng đã hoàn tất kế hoạch và cam kết dành nguồn kinh phí để cải tổ chương trình khen thưởng của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The initiative supports the aim to be a leading service provider among similar airlines and capture an increasing percentage of the market share.\", \"vi\": \"Sáng kiến này nhằm hỗ trợ mục tiêu trở thành nhà cung cấp dịch vụ hàng đầu trong số các hãng hàng không cùng loại và giành được tỷ lệ thị phần ngày càng cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '439f3faf-f563-4534-9ee6-480a700ab69f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Welinaras Corporation to Move R&D Division\", \"vi\": \"Tập đoàn Welinaras sẽ chuyển bộ phận Nghiên cứu và Phát triển\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"PUNE (12 March)—Welinaras Corporation, the health technology company headquartered in Pune, announced today that its Research and Development (R&D) Division will be based in Mumbai effective 1 May.\", \"vi\": \"PUNE (ngày 12 tháng 3) — Công ty Welinaras Corporation, một doanh nghiệp công nghệ y tế có trụ sở chính tại Pune, hôm nay đã thông báo rằng Bộ phận Nghiên cứu và Phát triển (R&D) của công ty sẽ chuyển trụ sở đến Mumbai, có hiệu lực từ ngày 1 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"\\\"Mumbai has the business climate, facilities, and creative talent we need to help push our production forward,\\\" said Mr. Ram Jadhav, who became the company\'s third president last month.\", \"vi\": \"\\\"Mumbai sở hữu môi trường kinh doanh, cơ sở vật chất và nguồn nhân lực sáng tạo mà chúng tôi cần để thúc đẩy hoạt động sản xuất của mình,\\\" ông Ram Jadhav, người vừa được bổ nhiệm làm Chủ tịch thứ ba của công ty vào tháng trước, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Currently, the company has offices in two other Indian cities, namely New Delhi and Hyderabad.\", \"vi\": \"Hiện tại, công ty có văn phòng tại hai thành phố khác của Ấn Độ, cụ thể là New Delhi và Hyderabad.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Welinaras Corporation is the manufacturer of high-quality technological equipment.\", \"vi\": \"Tập đoàn Welinaras là nhà sản xuất các thiết bị công nghệ chất lượng cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Its product that is most in demand and, thus, profitable, is called Vigilant.\", \"vi\": \"Sản phẩm có nhu cầu cao nhất và do đó mang lại lợi nhuận lớn nhất của công ty này có tên là Vigilant.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Invented by Mr. Jadhav, and available across India, the device is intended for people with health problems.\", \"vi\": \"Thiết bị này do ông Jadhav phát minh ra và hiện đã có mặt trên khắp Ấn Độ, được thiết kế dành cho những người gặp vấn đề về sức khỏe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"A key feature is its ability to regularly gather and update data about the patient\'s condition, information that might be crucial in emergencies.\", \"vi\": \"Một tính năng quan trọng của hệ thống này là khả năng thu thập và cập nhật thường xuyên dữ liệu về tình trạng của bệnh nhân – những thông tin này có thể đóng vai trò quyết định trong các tình huống khẩn cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Welinaras Corporation\", \"vi\": \"Tập đoàn Welinaras\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Job title: Senior Research and Development Engineer\", \"vi\": \"Chức danh: Kỹ sư Nghiên cứu và Phát triển Cấp cao\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Listing date: 23 March\", \"vi\": \"Ngày niêm yết: 23 tháng 3\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Apply by: 25 April\", \"vi\": \"Hạn chót nộp hồ sơ: ngày 25 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Responsible for designing and testing wearable health-monitoring devices.\", \"vi\": \"Chịu trách nhiệm thiết kế và thử nghiệm các thiết bị đeo được dùng để theo dõi sức khỏe.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"EDUCATION AND SKILLS:\", \"vi\": \"TRÌNH ĐỘ HỌC VẤN VÀ KỸ NĂNG:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Graduate degree in biomedical engineering\", \"vi\": \"Bằng thạc sĩ ngành kỹ thuật y sinh\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Minimum of five years\' experience developing medical devices and conducting clinical trials\", \"vi\": \"Có ít nhất năm năm kinh nghiệm trong lĩnh vực phát triển thiết bị y tế và thực hiện các thử nghiệm lâm sàng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Minimum of three years\' experience in managing research teams\", \"vi\": \"Có ít nhất ba năm kinh nghiệm trong việc quản lý các nhóm nghiên cứu\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Excellent written and oral communication skills\", \"vi\": \"Kỹ năng giao tiếp bằng văn bản và bằng lời nói xuất sắc\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Ability to work collaboratively in a global, multicultural environment\", \"vi\": \"Khả năng làm việc hợp tác trong một môi trường toàn cầu và đa văn hóa\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Candidate must attend a preliminary training course on 25 May, prior to starting work on 8 June.\", \"vi\": \"Ứng viên phải tham dự khóa đào tạo sơ bộ vào ngày 25 tháng 5, trước khi bắt đầu làm việc vào ngày 8 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '43bfa802-d324-43cd-8b68-4cc382bcc5ab';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dine Out Darville Is Back!\", \"vi\": \"Chương trình “Dine Out Darville” đã trở lại!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dine Out Darville, which runs this year from June 22 to 28, is the perfect chance to try a restaurant in Darville for the first time or revisit one of your favorite restaurants in town.\", \"vi\": \"Sự kiện “Dine Out Darville”, diễn ra từ ngày 22 đến ngày 28 tháng 6 năm nay, là cơ hội lý tưởng để quý vị lần đầu tiên ghé thăm một nhà hàng tại Darville hoặc quay lại một trong những nhà hàng yêu thích của quý vị trong thị trấn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"You might even visit multiple restaurants during the weeklong event!\", \"vi\": \"Thậm chí, quý vị còn có thể ghé thăm nhiều nhà hàng khác nhau trong suốt sự kiện kéo dài một tuần này!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Twelve popular restaurants will offer special four-course dinners—including a cup of soup, a salad, a main course, and a dessert—all for a reduced price of $30.\", \"vi\": \"Mười hai nhà hàng nổi tiếng sẽ phục vụ thực đơn bữa tối đặc biệt gồm bốn món — bao gồm một chén súp, một phần salad, một món chính và một món tráng miệng — tất cả với mức giá ưu đãi là 30 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Reservations are highly recommended.\", \"vi\": \"Chúng tôi khuyến nghị quý vị nên đặt chỗ trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dine Out Darville welcomes hundreds of locals and tourists each year, and you do not want to miss your opportunity to get a great meal at a great price.\", \"vi\": \"Sự kiện “Dine Out Darville” chào đón hàng trăm người dân địa phương và du khách mỗi năm, và quý vị chắc chắn không muốn bỏ lỡ cơ hội thưởng thức một bữa ăn ngon với mức giá hợp lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Visit www.darvillebusinesscouncil.org/dineout for a list of participating restaurants.\", \"vi\": \"Vui lòng truy cập trang web www.darvillebusinesscouncil.org/dineout để xem danh sách các nhà hàng tham gia chương trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '43f0f314-e4f8-4392-bd03-7d5f42456371';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Carol Barger (10:45 A.M.)\", \"vi\": \"Carol Barger (10 giờ 45 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hello, Ms. Seang.\", \"vi\": \"Xin chào, bà Seang.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Leakhena Seang (10:55 A.M.)\", \"vi\": \"Leakhena Seang (10 giờ 55 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Good morning!\", \"vi\": \"Chào buổi sáng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Carol Barger (11:15 A.M.)\", \"vi\": \"Carol Barger (11 giờ 15 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We have fifteen participants enrolled in your mosaic workshop tomorrow.\", \"vi\": \"Chúng tôi có mười lăm học viên đã đăng ký tham gia lớp học nghệ thuật khảm của quý vị vào ngày mai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"That is five more than last summer.\", \"vi\": \"Con số đó cao hơn năm ngoái năm người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Your workshops get more popular every year!\", \"vi\": \"Các khóa học thực hành của quý vị ngày càng trở nên phổ biến hơn mỗi năm!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Do you have enough materials on hand for that many participants?\", \"vi\": \"Quý vị có đủ vật liệu sẵn có để phục vụ cho số lượng người tham gia đông như vậy không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Leakhena Seang (11:23 A.M.)\", \"vi\": \"Leakhena Seang (11 giờ 23 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I have plenty to go around.\", \"vi\": \"Tôi có rất nhiều để chia sẻ cho mọi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We’ll be creating mosaic designs using bits of sea glass I collected on my vacation last summer.\", \"vi\": \"Chúng tôi sẽ tạo ra các tác phẩm khảm bằng những mảnh thủy tinh biển mà tôi đã thu thập được trong kỳ nghỉ hè năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"They are pieces of brown, green, and blue bottles that have washed up on the beach.\", \"vi\": \"Đó là những mảnh vỡ của các chai màu nâu, xanh lá cây và xanh dương bị sóng đánh dạt vào bãi biển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The sand has smoothed all the sharp edges, so they’re perfectly safe for everyone to use.\", \"vi\": \"Cát đã làm mịn tất cả các góc cạnh sắc nhọn, do đó chúng hoàn toàn an toàn để mọi người sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Carol Barger (11:30 A.M.)\", \"vi\": \"Carol Barger (11 giờ 30 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sounds good.\", \"vi\": \"Nghe có vẻ hay đấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"See you tomorrow at breakfast.\", \"vi\": \"Hẹn gặp quý vị vào bữa sáng ngày mai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '44042b04-b2c7-4d37-949f-41596b4f2341';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Protection & Conservation\", \"vi\": \"Bảo vệ & Bảo tồn\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Garner Museum of Art (GMA) ensures the preservation of its collection by carefully ______[139] the lighting of its galleries.\", \"vi\": \"Bảo tàng Nghệ thuật Garner (GMA) đảm bảo việc gìn giữ bộ sưu tập của mình bằng cách ______[139] cẩn thận hệ thống chiếu sáng tại các phòng trưng bày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [139]}, {\"en\": \"Certain artifacts—many of which are thousands of years old—are particularly sensitive to light.\", \"vi\": \"Một số cổ vật—nhiều món trong số đó đã có niên đại hàng nghìn năm—đặc biệt nhạy cảm với ánh sáng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"______[140], the museum does not showcase any of its pieces in areas with windows.\", \"vi\": \"______[140], bảo tàng không trưng bày bất kỳ hiện vật nào của mình ở các khu vực có cửa sổ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [140]}, {\"en\": \"Nor does it keep artwork in areas with certain kinds of ______[141], potentially harmful bulbs.\", \"vi\": \"Bảo tàng cũng không giữ các tác phẩm nghệ thuật ở những khu vực có một số loại bóng đèn ______[141], có khả năng gây hại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [141]}, {\"en\": \"______[142].\", \"vi\": \"______[142].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [142]}, {\"en\": \"By taking such measures, the GMA hopes that its collection will be enjoyed for generations to come.\", \"vi\": \"Bằng cách thực hiện các biện pháp như vậy, GMA hy vọng rằng bộ sưu tập của mình sẽ được thưởng thức bởi các thế hệ mai sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '44225a62-b51a-4d5c-a561-8b38d26d19a0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"TO: All employees\", \"vi\": \"Gửi: Toàn thể nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"FROM: Sirisha Rao\", \"vi\": \"Từ: Sirisha Rao\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"DATE: 7 May\", \"vi\": \"NGÀY: 7 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"SUBJECT: Event photographs\", \"vi\": \"CHỦ ĐỀ: Ảnh sự kiện\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"ATTACHMENT: Order form\", \"vi\": \"TÀI LIỆU KÈM THEO: Phiếu đặt hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Employees:\", \"vi\": \"Kính gửi các nhân viên:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Photographs from Nitin Kumar\'s retirement party on 3 April are now available.\", \"vi\": \"Các bức ảnh từ tiệc chia tay nghỉ hưu của ông Nitin Kumar vào ngày 3 tháng 4 hiện đã được đăng tải.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To see the album, visit Happy Moon Photography\'s Web site at happymoonphotography.co.in and enter our company name and ID number (933704).\", \"vi\": \"Để xem album, quý vị vui lòng truy cập trang web của Happy Moon Photography tại địa chỉ happymoonphotography.co.in và nhập tên công ty cùng số đăng ký (933704) của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"You may order individual prints for ₹400 each, or choose from one of the four packages listed below.\", \"vi\": \"Quý vị có thể đặt mua từng bản in với giá ₹400 mỗi bản, hoặc lựa chọn một trong bốn gói dịch vụ được liệt kê dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"• Basic (₹1270): Four 10x15 prints\", \"vi\": \"• Gói Cơ bản (₹1270): Bốn tấm ảnh kích thước 10x15\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"• Basic Plus (₹2150): Four 10x15 prints and two 13x18 prints\", \"vi\": \"• Gói Basic Plus (₹2.150): Bốn ảnh in kích thước 10x15 và hai ảnh in kích thước 13x18\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"• To Share (₹4120): Eight 10x15 prints and four 13x18 prints\", \"vi\": \"• Gói “To Share” (₹4120): Tám tấm ảnh kích thước 10x15 và bốn tấm ảnh kích thước 13x18\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"• For Everyone (₹7930): Sixteen 10x15 prints and eight 13x18 prints\", \"vi\": \"• Gói dành cho mọi người (₹7930): Mười sáu tấm ảnh cỡ 10x15 và tám tấm ảnh cỡ 13x18\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Enter discount code 10 PERCENT in the coupon field at checkout when you order online and receive free shipping and a 10 percent discount.\", \"vi\": \"Khi đặt hàng trực tuyến, vui lòng nhập mã giảm giá 10 PERCENT vào ô mã giảm giá tại bước thanh toán để được miễn phí vận chuyển và giảm giá 10 phần trăm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Alternatively, you may complete the order form attached to this e-mail and return it to me.\", \"vi\": \"Ngoài ra, quý vị có thể điền vào mẫu đơn đặt hàng đính kèm trong email này và gửi lại cho tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Photographs are available online for 30 days.\", \"vi\": \"Các bức ảnh sẽ được đăng tải trên mạng trong vòng 30 ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"For purchases after that time, please call Happy Moon\'s customer support line at 11 2679 5004.\", \"vi\": \"Đối với các đơn hàng được thực hiện sau thời điểm đó, xin vui lòng liên hệ với bộ phận hỗ trợ khách hàng của Happy Moon qua số điện thoại 11 2679 5004.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Sirisha Rao, Special Events Coordinator\", \"vi\": \"Bà Sirisha Rao, Điều phối viên các sự kiện đặc biệt\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"TO: Gurunath Pandit <gpandit@akrzindustries.co.in>\", \"vi\": \"Gửi: Gurunath Pandit <gpandit@akrzindustries.co.in>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"FROM: <service@happymoonphotography.co.in>\", \"vi\": \"TỪ: <service@happymoonphotography.co.in>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"DATE: 10 May\", \"vi\": \"NGÀY: 10 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"SUBJECT: Order number 38919\", \"vi\": \"CHỦ ĐỀ: Số đơn đặt hàng 38919\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Dear Mr. Pandit,\", \"vi\": \"Kính gửi ông Pandit,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Thank you for ordering from Happy Moon Photography!\", \"vi\": \"Xin chân thành cảm ơn quý khách đã đặt hàng tại Happy Moon Photography!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Please review your completed purchase below.\", \"vi\": \"Kính mời quý khách kiểm tra thông tin đơn hàng đã hoàn tất dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Your photographs should arrive in the mail no later than 23 May.\", \"vi\": \"Các bức ảnh của quý vị cần phải được gửi qua đường bưu điện chậm nhất là vào ngày 23 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Event: Nitin Kumar Retirement Party, AKRZ Industries\", \"vi\": \"Sự kiện: Tiệc chia tay nghỉ hưu của ông Nitin Kumar, Công ty AKRZ Industries\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Four 10x15 photographs of image 204: ₹1270\", \"vi\": \"Bốn tấm ảnh kích thước 10x15 của hình ảnh số 204: ₹1.270\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Discount 10 percent: –₹127\", \"vi\": \"Giảm giá 10 phần trăm: –₹127\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Total: ₹1143\", \"vi\": \"Tổng cộng: ₹1143\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Planning an event?\", \"vi\": \"Quý vị đang lên kế hoạch tổ chức một sự kiện?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Book one of our photographers before 15 June and receive a 20 percent discount.\", \"vi\": \"Hãy đặt lịch với một trong các nhiếp ảnh gia của chúng tôi trước ngày 15 tháng 6 để được hưởng mức giảm giá 20%.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '4462e8b5-3bdd-4867-b585-2ff3d8e6c0d6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Flavor - Percent\", \"vi\": \"Hương vị - Tỷ lệ phần trăm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Chocolate - 22\", \"vi\": \"Sô-cô-la - 22\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Vanilla - 18\", \"vi\": \"Vanilla - 18\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Strawberry - 11\", \"vi\": \"Dâu tây - 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Cookies and cream - 8\", \"vi\": \"Bánh quy và kem - 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Butter pecan - 8\", \"vi\": \"Bơ hạt hồ đào - 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Mint chocolate chip - 7\", \"vi\": \"Sô-cô-la vụn bạc hà - 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"All others - 26\", \"vi\": \"Tất cả các trường hợp khác - 26\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Margot\'s House of Ice Cream\", \"vi\": \"Quán kem Margot\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Flavor Purchases by Percentage of Sales\", \"vi\": \"Doanh số bán các loại hương vị theo tỷ lệ phần trăm trên tổng doanh thu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"July\", \"vi\": \"tháng Bảy\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"MEMO\", \"vi\": \"BẢN GHI NHỚ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To: All Store Managers\", \"vi\": \"Kính gửi: Tất cả các Quản lý cửa hàng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"From: June Willcox, CEO, Margot\'s House of Ice Cream\", \"vi\": \"Từ: June Willcox, Tổng Giám đốc, Margot\'s House of Ice Cream\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Subject: New Stores\", \"vi\": \"Chủ đề: Các cửa hàng mới\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Date: October 5\", \"vi\": \"Ngày: 5 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Store Number - Location - Opening Date - Manager\", \"vi\": \"Số cửa hàng - Địa điểm - Ngày khai trương - Quản lý\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"66 - Framingham, Massachusetts, United States - September 1 - Inga Slavin\", \"vi\": \"66 - Framingham, Massachusetts, Hoa Kỳ - Ngày 1 tháng 9 - Inga Slavin\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"67 - Appleton, Wisconsin, United States - September 7 - Zheng Tong\", \"vi\": \"67 - Appleton, Wisconsin, Hoa Kỳ - Ngày 7 tháng 9 - Zheng Tong\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"68 - Wollongong, New South Wales, Australia - September 14 - Geoffrey Pratt\", \"vi\": \"68 - Wollongong, New South Wales, Úc - Ngày 14 tháng 9 - Geoffrey Pratt\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"69 - Rotorua, New Zealand - September 15 - Kehinde Ilogu\", \"vi\": \"69 - Rotorua, New Zealand - Ngày 15 tháng 9 - Kehinde Ilogu\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"70 - Greater Sudbury, Ontario, Canada - September 29 - Hallie Strafford\", \"vi\": \"70 - Greater Sudbury, Ontario, Canada - Ngày 29 tháng 9 - Hallie Strafford\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Margot\'s House of Ice Cream is proud to welcome the following new stores.\", \"vi\": \"Margot\'s House of Ice Cream hân hạnh chào đón các cửa hàng mới sau đây.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"For the next six months, we will be supporting these stores with advertisements in their local media markets.\", \"vi\": \"Trong sáu tháng tới, chúng tôi sẽ hỗ trợ các cửa hàng này bằng các chiến dịch quảng cáo trên các phương tiện truyền thông địa phương.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"In December, we plan to open stores in Italy and Switzerland.\", \"vi\": \"Vào tháng 12, chúng tôi dự kiến sẽ khai trương các cửa hàng tại Ý và Thụy Sĩ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Demand for our quality product is higher than ever, our market share is increasing, and we are not finished expanding!\", \"vi\": \"Nhu cầu đối với sản phẩm chất lượng của chúng tôi đang ở mức cao nhất từ trước đến nay, thị phần của chúng tôi đang ngày càng gia tăng, và chúng tôi vẫn chưa dừng lại ở đó trong việc mở rộng quy mô!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Stay tuned for more information!\", \"vi\": \"Hãy tiếp tục theo dõi để biết thêm thông tin!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Popular Ice Cream Purveyor Comes to New Zealand\", \"vi\": \"Thương hiệu kem nổi tiếng chính thức có mặt tại New Zealand\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"By Ysai Mendez\", \"vi\": \"Tác giả: Ysai Mendez\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"ROTORUA (2 November)—Residents of Rotorua have been flocking to Cargill Street, where Margot’s House of Ice Cream has opened its first store in New Zealand.\", \"vi\": \"ROTORUA (ngày 2 tháng 11) — Người dân Rotorua đang đổ xô đến đường Cargill, nơi cửa hàng Margot’s House of Ice Cream đã khai trương chi nhánh đầu tiên tại New Zealand.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"“I don’t know what their secret is, but their ice cream really is something special,” said Jeremy Frank, a schoolteacher who was enjoying ice cream cones with his family on a recent afternoon.\", \"vi\": \"“Tôi không biết bí quyết của họ là gì, nhưng kem của họ thực sự rất đặc biệt,” ông Jeremy Frank, một giáo viên đang cùng gia đình thưởng thức kem ốc quế vào một buổi chiều gần đây, chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"“We’ve been here several times already since they opened.\", \"vi\": \"“Chúng tôi đã đến đây vài lần rồi kể từ khi nơi này khai trương.”\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I think we’ll be regulars.”\", \"vi\": \"“Tôi nghĩ chúng ta sẽ trở thành những vị khách quen.”\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"“I love strawberry, and their strawberry is the best I ever had,” added his daughter, Olivia Frank, age 10.\", \"vi\": \"“Con rất thích dâu tây, và dâu tây ở đây là loại ngon nhất mà con từng được ăn,” cô con gái của ông, Olivia Frank, 10 tuổi, nói thêm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Margot’s House of Ice Cream was founded five years ago in San Francisco by Margot Summers, a former chemistry major.\", \"vi\": \"Cửa hàng kem Margot’s House of Ice Cream được thành lập cách đây năm năm tại San Francisco bởi Margot Summers, một cựu sinh viên chuyên ngành hóa học.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Its ice cream contains at least 11 percent milk fat.\", \"vi\": \"Kem của hãng này chứa ít nhất 11 phần trăm chất béo sữa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Milk used in production, according to company CEO June Willcox, is sourced locally or regionally whenever possible.\", \"vi\": \"Theo bà June Willcox, Giám đốc điều hành của công ty, sữa được sử dụng trong quá trình sản xuất được thu mua từ các nguồn địa phương hoặc trong khu vực bất cứ khi nào có thể.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Kehinde Ilogu, the manager of the Rotorua store, says that the number of visitors has been rising steadily.\", \"vi\": \"Ông Kehinde Ilogu, quản lý cửa hàng tại Rotorua, cho biết lượng khách tham quan đã không ngừng tăng lên.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"“We plan to keep the momentum going by having special events once a month,” he said.\", \"vi\": \"“Chúng tôi dự định sẽ duy trì đà phát triển này bằng cách tổ chức các sự kiện đặc biệt mỗi tháng một lần,” ông nói.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"“Next up is the strawberry festival.\", \"vi\": \"“Tiếp theo là lễ hội dâu tây.”\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"New Zealand’s strawberry season will be getting started.\", \"vi\": \"Mùa dâu tây tại New Zealand sắp bắt đầu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"In addition to our superb ice cream, we’ll offer strawberries dipped in chocolate, strawberry cupcakes, and strawberry milkshakes.\", \"vi\": \"Bên cạnh món kem hảo hạng của chúng tôi, chúng tôi còn phục vụ dâu tây nhúng sô-cô-la, bánh cupcake dâu tây và sinh tố dâu tây.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"We look forward to a great future in Rotorua.”\", \"vi\": \"Chúng tôi rất mong chờ một tương lai tươi sáng tại Rotorua.”\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}]' WHERE `id` = '446d302b-0612-4059-806c-6a51b691031e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dear Ms. Rogers,\", \"vi\": \"Kính gửi cô Rogers,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Thank you for your interest in booking a private tour of our chocolate factory for your work colleagues.\", \"vi\": \"Cảm ơn bạn đã quan tâm đến việc đặt một chuyến tham quan riêng nhà máy sô-cô-la của chúng tôi cho các đồng nghiệp của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Please note that certain sections of the production line are not available to the public.\", \"vi\": \"Xin lưu ý rằng một số khu vực nhất định của dây chuyền sản xuất không mở cửa cho công chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"______[131].\", \"vi\": \"______[131].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [131]}, {\"en\": \"However, there is still a lot to see.\", \"vi\": \"Tuy nhiên, vẫn có rất nhiều thứ để khám phá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We show all tour participants an ______[132] video.\", \"vi\": \"Chúng tôi cho tất cả những người tham gia chuyến tham quan xem một đoạn video ______[132].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [132]}, {\"en\": \"It will teach you about the history of our company.\", \"vi\": \"Nó sẽ cung cấp cho bạn kiến thức về lịch sử của công ty chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This ______[133] lasts approximately twenty minutes and can be at the beginning or the end of the tour.\", \"vi\": \"Phần ______[133] này kéo dài khoảng hai mươi phút và có thể diễn ra vào đầu hoặc cuối chuyến tham quan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [133]}, {\"en\": \"Please let ______[134] know what date you plan to attend and how many people will be in your group.\", \"vi\": \"Vui lòng cho ______[134] biết ngày bạn dự định tham gia và số lượng người trong nhóm của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [134]}, {\"en\": \"We hope you will have an enjoyable time!\", \"vi\": \"Chúng tôi hy vọng bạn sẽ có một khoảng thời gian thú vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Warmest regards,\", \"vi\": \"Trân trọng nhất,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Clayton Pemberton, Administrator\", \"vi\": \"Clayton Pemberton, Quản trị viên\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Bylee Chocolate Factory\", \"vi\": \"Nhà máy sô-cô-la Bylee\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '4475c290-ae83-49e1-ab1b-f1e99d6f261e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Important Information\", \"vi\": \"Thông tin quan trọng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"At the Freehling Company, we take great pride in our high-quality, easy-to-assemble furniture, and we want you to be completely satisfied with your purchase.\", \"vi\": \"Tại Công ty Freehling, chúng tôi vô cùng tự hào về những sản phẩm nội thất chất lượng cao, dễ lắp ráp của mình, và chúng tôi mong muốn quý khách hoàn toàn hài lòng với sản phẩm đã mua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Before beginning to assemble the product, check the parts list to make sure that all parts have been included in the box.\", \"vi\": \"Trước khi bắt đầu lắp ráp sản phẩm, quý vị hãy kiểm tra danh sách các bộ phận để đảm bảo rằng tất cả các bộ phận đều đã có trong hộp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"If your item is missing parts or assembly hardware, or if it has been damaged during shipping, do not return the product to the store from which you purchased it; stores do not stock replacement parts.\", \"vi\": \"Nếu sản phẩm của quý khách thiếu các bộ phận hoặc phụ kiện lắp ráp, hoặc nếu sản phẩm bị hư hỏng trong quá trình vận chuyển, xin đừng trả lại sản phẩm cho cửa hàng mà quý khách đã mua; các cửa hàng không có sẵn các bộ phận thay thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Rather, contact us directly and we will send you the item(s) required free of charge.\", \"vi\": \"Thay vào đó, xin vui lòng liên hệ trực tiếp với chúng tôi và chúng tôi sẽ gửi miễn phí cho quý vị (các) mặt hàng mà quý vị cần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"You can reach us by\", \"vi\": \"Quý vị có thể liên hệ với chúng tôi qua\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"visiting us at www.froehlingco.com to order replacement parts online;\", \"vi\": \"truy cập trang web của chúng tôi tại www.froehlingco.com để đặt mua phụ tùng thay thế trực tuyến;\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"sending us an e-mail at parts@froehlingco.com; or\", \"vi\": \"gửi email cho chúng tôi theo địa chỉ parts@froehlingco.com; hoặc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"calling us anytime at 555-0128.\", \"vi\": \"Quý vị có thể gọi cho chúng tôi bất cứ lúc nào theo số 555-0128.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '44fce9f6-082c-4d91-9a99-8576145a2109';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Derek Marshall [8:19 A.M.]\", \"vi\": \"Derek Marshall [8 giờ 19 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, everyone.\", \"vi\": \"Xin chào quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I wanted to give an update on our merger with Ridgewood, Inc., and see if you have had any meetings.\", \"vi\": \"Tôi muốn cập nhật thông tin về việc sáp nhập của chúng tôi với Công ty Ridgewood, Inc., và xin hỏi xem quý vị đã có bất kỳ cuộc họp nào chưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Mai Chung [8:20 A.M.]\", \"vi\": \"Mai Chung [8:20 A.M.]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Have we worked out which of our Derek Boutique locations will stay open?\", \"vi\": \"Chúng ta đã xác định được chi nhánh nào của Derek Boutique sẽ tiếp tục hoạt động chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Derek Marshall [8:21 A.M.]\", \"vi\": \"Derek Marshall [8 giờ 21 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Yes, Derek Boutique will keep 35 stores open with the full line of clothing.\", \"vi\": \"Đúng vậy, Derek Boutique sẽ duy trì hoạt động của 35 cửa hàng với đầy đủ các dòng sản phẩm thời trang.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The other 12 will move their inventory to the Ridgewood, Inc., locations.\", \"vi\": \"12 cửa hàng còn lại sẽ chuyển hàng tồn kho sang các cơ sở của Ridgewood, Inc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Nikita Tamboli [8:22 A.M.]\", \"vi\": \"Nikita Tamboli [8 giờ 22 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"When should the moves be scheduled?\", \"vi\": \"Nên lên lịch cho các đợt di dời vào thời điểm nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"This month?\", \"vi\": \"Tháng này chăng?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Derek Marshall [8:23 A.M.]\", \"vi\": \"Derek Marshall [8 giờ 23 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"No, the 12 locations don\'t need to be vacated until the end of next month.\", \"vi\": \"Không, 12 địa điểm này không cần phải dọn ra cho đến cuối tháng sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Could you schedule this for five weeks from now?\", \"vi\": \"Quý vị có thể sắp xếp lịch cho việc này vào 5 tuần nữa được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Anthony Rossi [8:24 A.M.]\", \"vi\": \"Anthony Rossi [8 giờ 24 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I met over lunch with my managers earlier this week, including the two that I just hired.\", \"vi\": \"Đầu tuần này, tôi đã có buổi gặp gỡ trong bữa trưa với các quản lý của mình, trong đó có hai người mà tôi vừa mới tuyển dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Nikita Tamboli [8:25 A.M.]\", \"vi\": \"Nikita Tamboli [8 giờ 25 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"That would work.\", \"vi\": \"Cách đó sẽ hiệu quả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Mai Chung [8:27 A.M.]\", \"vi\": \"Mai Chung [8:27 A.M.]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I\'ll be meeting with the managers on my staff, too, to review the transition plan.\", \"vi\": \"Tôi cũng sẽ có cuộc họp với các quản lý trong đội ngũ của mình để rà soát kế hoạch chuyển giao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Derek Marshall [8:28 A.M.]\", \"vi\": \"Derek Marshall [8 giờ 28 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"This is good work, everyone.\", \"vi\": \"Mọi người đã làm rất tốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Anthony Rossi [8:29 A.M.]\", \"vi\": \"Anthony Rossi [8 giờ 29 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"When will the whole process be complete?\", \"vi\": \"Khi nào thì toàn bộ quá trình này sẽ hoàn tất?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Derek Marshall [8:30 A.M.]\", \"vi\": \"Derek Marshall [8 giờ 30 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Within about 6 months.\", \"vi\": \"Trong vòng khoảng 6 tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"⎯ □ ✕\", \"vi\": \"⎯ □ ✕\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '45311d27-5719-4632-8d88-ba841db211b9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Eun-Sook Yoo\", \"vi\": \"Đến: Eun-Sook Yoo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Earl Fowler\", \"vi\": \"Từ: Earl Fowler\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Notice\", \"vi\": \"Chủ đề: Thông báo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: August 23\", \"vi\": \"Ngày: 23 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Dr. Yoo,\", \"vi\": \"Kính gửi Tiến sĩ Yoo,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am writing to give you official notice that I am resigning from my position as Hillside Clinic\'s office manager.\", \"vi\": \"Tôi viết thư này để thông báo chính thức rằng tôi sẽ từ chức khỏi vị trí quản lý văn phòng của Phòng khám Hillside.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"My final day will be Friday, September 21.\", \"vi\": \"Ngày làm việc cuối cùng của tôi sẽ là thứ Sáu, ngày 21 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I hope this will allow you plenty of time to find my ______[139].\", \"vi\": \"Tôi hy vọng điều này sẽ cho bạn có đủ thời gian để tìm người thay thế ______[139] của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [139]}, {\"en\": \"If you are able to hire him or her before I go, I would be happy to handle the training.\", \"vi\": \"Nếu bạn có thể tuyển dụng được nhân sự đó trước khi tôi rời đi, tôi rất sẵn lòng hướng dẫn công việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"______[140], I will create detailed documentation about my work processes and make it available to everyone on the shared network.\", \"vi\": \"______[140], tôi sẽ lập tài liệu chi tiết về các quy trình làm việc của mình và cung cấp cho tất cả mọi người trên mạng chia sẻ chung.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [140]}, {\"en\": \"______[141].\", \"vi\": \"______[141].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [141]}, {\"en\": \"Finally, I would like to express my gratitude to you for providing such ______[142] support and leadership over the last five years.\", \"vi\": \"Cuối cùng, tôi muốn bày tỏ lòng biết ơn đến bạn vì đã cung cấp sự hỗ trợ và lãnh đạo vô cùng ______[142] trong suốt năm năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [142]}, {\"en\": \"It was a pleasure to act as your office manager.\", \"vi\": \"Thật là một vinh hạnh khi được làm quản lý văn phòng của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I wish you and Hillside Clinic the best in the future.\", \"vi\": \"Tôi chúc bạn và Phòng khám Hillside gặt hái được nhiều thành công tốt đẹp trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Earl Fowler\", \"vi\": \"Earl Fowler\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '45328d68-8358-4391-b0ba-6e4bbcb583ef';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: osullivan@nortech.com\", \"vi\": \"Nguồn: osullivan@nortech.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: inquiries@haywoodhub.com\", \"vi\": \"Gửi tới: inquiries@haywoodhub.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Office space inquiry\", \"vi\": \"Chủ đề: Yêu cầu thông tin về mặt bằng văn phòng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: Thursday, February 2, 10:08 A.M.\", \"vi\": \"Ngày: Thứ Năm, ngày 2 tháng 2, 10 giờ 08 phút sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Xin chào\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am contacting your business by e-mail because I cannot seem to reach you via phone; each time I call the number listed on your Web site, a message says it is \\\"unavailable.\\\"\", \"vi\": \"Tôi liên hệ với công ty quý vị qua email vì dường như tôi không thể liên lạc được với quý vị qua điện thoại; mỗi khi tôi gọi đến số điện thoại được đăng trên trang web của quý vị, một thông báo lại cho biết số đó “không thể liên lạc được”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am seeking a coworking business in Haywood from which I can work remotely for a few weeks while dealing with a family matter.\", \"vi\": \"Tôi đang tìm kiếm một không gian làm việc chung tại Haywood để có thể làm việc từ xa trong vài tuần, trong thời gian giải quyết một vấn đề gia đình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I would need a private office and the use of two large computer monitors, and my budget limit is $100 per week.\", \"vi\": \"Tôi cần một văn phòng riêng và được sử dụng hai màn hình máy tính cỡ lớn; mức ngân sách tối đa của tôi là 100 đô la mỗi tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Does Haywood Hub have what I am looking for?\", \"vi\": \"Haywood Hub có những gì tôi đang tìm kiếm không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Also, I see from your Web site that you offer parking.\", \"vi\": \"Ngoài ra, tôi thấy trên trang web của quý vị có đề cập đến dịch vụ đỗ xe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Could you let me know how much you charge for it, and also whether the parking area is enclosed?\", \"vi\": \"Xin quý vị vui lòng cho tôi biết mức phí cho dịch vụ này là bao nhiêu, và khu vực đỗ xe có được rào chắn lại không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I hope to hear from you very soon.\", \"vi\": \"Tôi hy vọng sẽ sớm nhận được phản hồi từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Olive Sullivan\", \"vi\": \"Olive Sullivan\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"From: edchisholm@haywoodhub.com\", \"vi\": \"Nguồn: edchisholm@haywoodhub.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To: osullivan@nortech.com\", \"vi\": \"Gửi tới: osullivan@nortech.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Subject: Re: Office space inquiry\", \"vi\": \"Chủ đề: Trả lời: Yêu cầu thông tin về mặt bằng văn phòng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date: Thursday, February 2, 11:42 A.M.\", \"vi\": \"Ngày: Thứ Năm, ngày 2 tháng 2, 11 giờ 42 phút sáng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Dear Ms. Sullivan,\", \"vi\": \"Kính gửi bà Sullivan,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I apologize for the difficulty you experienced while calling us.\", \"vi\": \"Tôi xin lỗi vì những khó khăn mà quý vị đã gặp phải khi gọi điện cho chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"There was a phone service outage across our area this morning due to a tree branch having fallen on a phone line.\", \"vi\": \"Sáng nay, khu vực của chúng tôi đã xảy ra sự cố gián đoạn dịch vụ điện thoại do một cành cây rơi trúng đường dây điện thoại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Luckily, the issue was handled quickly.\", \"vi\": \"May mắn thay, vấn đề đã được giải quyết nhanh chóng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"As for your inquiries, I am pleased to tell you that we currently have suitable spaces open on our second floor for $96 per week, inclusive of the charge for the computer accessories you require.\", \"vi\": \"Về các thắc mắc của quý vị, tôi vui mừng thông báo rằng hiện tại chúng tôi có các không gian phù hợp đang trống tại tầng hai với mức giá 96 đô la mỗi tuần, đã bao gồm chi phí cho các phụ kiện máy tính mà quý vị cần.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"The parking fee will be waived if you pay by the week or month, and though our parking area is not enclosed, most of the spaces are covered by shade canopies.\", \"vi\": \"Phí đỗ xe sẽ được miễn nếu quý vị thanh toán theo tuần hoặc theo tháng; và mặc dù khu vực đỗ xe của chúng tôi không được bao quanh, nhưng hầu hết các chỗ đỗ đều được che mát bởi các mái che.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"While we do allow walk-ins, it is best to book a space ahead of time to ensure that one will be available.\", \"vi\": \"Mặc dù chúng tôi vẫn chấp nhận khách đến trực tiếp mà không cần đặt chỗ trước, nhưng quý vị nên đặt chỗ trước để đảm bảo chắc chắn có chỗ trống.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"You can respond to this e-mail or call me directly at extension 3 from our main line in order to do this.\", \"vi\": \"Để thực hiện việc này, quý vị có thể trả lời email này hoặc gọi trực tiếp cho tôi theo số máy lẻ 3 từ đường dây chính của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I am also happy to answer any further questions you might have.\", \"vi\": \"Tôi cũng rất sẵn lòng giải đáp bất kỳ thắc mắc nào khác mà quý vị có thể có.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Ed Chisholm, Service Manager\", \"vi\": \"Ông Ed Chisholm, Trưởng phòng Dịch vụ\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Haywood Hub\", \"vi\": \"Trung tâm Haywood\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = '454ed760-e98b-4dc5-9392-dffa09019af9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ed Singh (9:46 A.M.)\", \"vi\": \"Ed Singh (9 giờ 46 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi Marisa, has David Yuen stopped by your office?\", \"vi\": \"Xin chào Marisa, không biết David Yuen có ghé qua văn phòng của quý vị chưa?\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Marisa Viteli (9:48 A.M.)\", \"vi\": \"Marisa Viteli (9 giờ 48 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Not that I know of.\", \"vi\": \"Theo tôi được biết thì không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I just got here.\", \"vi\": \"Tôi vừa mới đến đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Ed Singh (9:49 A.M.)\", \"vi\": \"Ed Singh (9 giờ 49 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"He\'s having a hard time debugging a program and I told him to ask you to look at it.\", \"vi\": \"Anh ấy đang gặp khó khăn trong việc gỡ lỗi một chương trình và tôi đã bảo anh ấy nhờ quý vị xem giúp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I hope you don\'t mind.\", \"vi\": \"Tôi hy vọng quý vị không phiền.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Marisa Viteli (9:50 A.M.)\", \"vi\": \"Marisa Viteli (9 giờ 50 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Not at all.\", \"vi\": \"Không hề.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"He\'s on the Zandos project, right?\", \"vi\": \"Anh ấy đang tham gia dự án Zandos, phải không ạ?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Ed Singh (9:51 A.M.)\", \"vi\": \"Ed Singh (9 giờ 51 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Yes, they\'re building an order-tracking system and it has to be delivered in a few weeks.\", \"vi\": \"Đúng vậy, họ đang xây dựng một hệ thống theo dõi đơn hàng và hệ thống này phải được bàn giao trong vài tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Marisa Viteli (9:52 A.M.)\", \"vi\": \"Marisa Viteli (9 giờ 52 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Ah, that\'s a huge program.\", \"vi\": \"À, đó quả là một chương trình quy mô rất lớn.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I can see why he\'s having coding problems.\", \"vi\": \"Tôi có thể hiểu tại sao anh ấy lại gặp khó khăn trong việc lập trình.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '4595b3db-3e4e-4257-8f23-493cf0b17128';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.rivieracarrental.co.uk/598270 ▶\", \"vi\": \"https://www.rivieracarrental.co.uk/598270 ▶\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Thank you, Mr. Gregersen!\", \"vi\": \"Xin cảm ơn ông Gregersen!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Your Riviera Car Rental booking is now complete.\", \"vi\": \"Đặt xe tại Riviera Car Rental của quý khách hiện đã hoàn tất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Today\'s date: 3 June\", \"vi\": \"Ngày hôm nay: 3 tháng 6\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Duration: 7 days\", \"vi\": \"Thời gian: 7 ngày\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Pickup: 14 June in Bristol\", \"vi\": \"Thời gian nhận hàng: Ngày 14 tháng 6 tại Bristol\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Return: 20 June in Cambridge\", \"vi\": \"Ngày trở lại: 20 tháng 6 tại Cambridge\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Credit card: XXXX-XXXX-XXXX-2891\", \"vi\": \"Thẻ tín dụng: XXXX-XXXX-XXXX-2891\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Amount: £310.00\", \"vi\": \"Số tiền: 310,00 bảng Anh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You have opted to prepay your rental, but your credit card will not be charged until 12 June.\", \"vi\": \"Quý khách đã chọn thanh toán trước tiền thuê, nhưng thẻ tín dụng của quý khách sẽ không bị trừ tiền cho đến ngày 12 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Until then you may cancel your booking at no charge.\", \"vi\": \"Cho đến thời điểm đó, quý vị có thể hủy đặt phòng mà không phải trả bất kỳ khoản phí nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Should you cancel after that date, a fee will be charged.\", \"vi\": \"Nếu quý vị hủy sau ngày đó, quý vị sẽ phải trả một khoản phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Also, if you fail to pick up your car (no-show), you will be charged in full, and the amount is nonrefundable.\", \"vi\": \"Ngoài ra, nếu quý khách không đến nhận xe (không xuất hiện), quý khách sẽ phải thanh toán toàn bộ số tiền và khoản tiền này sẽ không được hoàn lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '45c486f8-232f-4753-92ff-456ee9f1dcbc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Yummy Good Foods\", \"vi\": \"Những món ăn ngon miệng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.yummygoodfoods.com\", \"vi\": \"http://www.yummygoodfoods.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Is nutrition important to you?\", \"vi\": \"Chế độ dinh dưỡng có quan trọng đối với quý vị không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Do you like high-quality, natural products?\", \"vi\": \"Quý vị có thích các sản phẩm tự nhiên, chất lượng cao không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Are you short on time?\", \"vi\": \"Quý vị có đang thiếu thời gian không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Then consider our healthy, nutritional meals shipped right to your door!\", \"vi\": \"Vậy thì hãy cân nhắc các bữa ăn lành mạnh và giàu dinh dưỡng của chúng tôi, được giao tận nhà quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Yummy Good Foods is having a special one-time offer.\", \"vi\": \"Yummy Good Foods đang có chương trình khuyến mãi đặc biệt chỉ diễn ra một lần duy nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We will send your first week of delicious meals from our Healthy Meal menu with complimentary shipping!\", \"vi\": \"Chúng tôi sẽ gửi đến quý vị các bữa ăn ngon miệng trong tuần đầu tiên từ thực đơn “Bữa ăn Lành mạnh” của chúng tôi, kèm theo dịch vụ giao hàng miễn phí!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Go to www.yummygoodfoods.com and enter code: BetterHealth4Me.\", \"vi\": \"Vui lòng truy cập trang www.yummygoodfoods.com và nhập mã: BetterHealth4Me.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Offer valid through June with your first monthly purchase.\", \"vi\": \"Ưu đãi có hiệu lực đến hết tháng 6 khi quý khách thực hiện giao dịch mua hàng hàng tháng đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '46451c3e-78ca-4b7f-af18-671ca402729d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Alan Grady <agrady@st.pro.com>\", \"vi\": \"Từ: Alan Grady <agrady@st.pro.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Jaco Neves <owner@neveslocal.com>\", \"vi\": \"Gửi tới: Jaco Neves <owner@neveslocal.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: Monday, August 7, 9:31 A.M.\", \"vi\": \"Ngày: Thứ Hai, ngày 7 tháng 8, 9 giờ 31 phút sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Contract addendum\", \"vi\": \"Chủ đề: Phụ lục hợp đồng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Mr. Neves,\", \"vi\": \"Thưa ông Neves,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thanks for calling to discuss your progress on the house construction.\", \"vi\": \"Xin cảm ơn quý vị đã gọi điện để trao đổi về tiến độ thi công ngôi nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To summarize our conversation, even with the delay until September 22, the house should be ready for me to move into before my apartment lease expires on October 10.\", \"vi\": \"Tóm lại nội dung cuộc trò chuyện của chúng ta, dù có sự chậm trễ đến ngày 22 tháng 9, ngôi nhà vẫn sẽ sẵn sàng để tôi dọn vào trước khi hợp đồng thuê căn hộ của tôi hết hạn vào ngày 10 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I\'ve thought more about the status reports we discussed, and twice a week would be best.\", \"vi\": \"Tôi đã suy nghĩ kỹ hơn về các báo cáo tình hình mà chúng ta đã thảo luận, và tần suất hai lần một tuần sẽ là phù hợp nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"My understanding is that you will now document these changes to the contract so that I can sign off on them this week.\", \"vi\": \"Theo tôi được biết, quý vị sẽ tiến hành ghi chép lại những thay đổi này vào hợp đồng để tôi có thể ký xác nhận trong tuần này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Thanks, as always, for your careful attention to this project.\", \"vi\": \"Xin chân thành cảm ơn quý vị, như mọi khi, vì sự quan tâm chu đáo dành cho dự án này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Alan Grady\", \"vi\": \"Alan Grady\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"From: Jaco Neves <owner@neveslocal.com>\", \"vi\": \"Từ: Jaco Neves <owner@neveslocal.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To: Alan Grady <agrady@st.pro.com>\", \"vi\": \"Gửi tới: Alan Grady <agrady@st.pro.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: Monday, August 7, 4:16 P.M.\", \"vi\": \"Ngày: Thứ Hai, ngày 7 tháng 8, 4 giờ 16 phút chiều.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Subject: RE: Contract addendum\", \"vi\": \"Chủ đề: RE: Phụ lục hợp đồng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Attachment: Addendum\", \"vi\": \"Tài liệu đính kèm: Phụ lục\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Mr. Grady,\", \"vi\": \"Thưa ông Grady,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I have drawn up the revisions we discussed to the June 5 contract and attached it to this message.\", \"vi\": \"Tôi đã soạn thảo các nội dung sửa đổi mà chúng ta đã thảo luận đối với hợp đồng ngày 5 tháng 6 và đính kèm tài liệu đó vào thư này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The recent bad weather set us back, but not by much.\", \"vi\": \"Thời tiết xấu gần đây đã khiến chúng tôi gặp một chút trở ngại, nhưng cũng không đáng kể.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"As we near the end of the project, many pieces will need to come together at once.\", \"vi\": \"Khi dự án sắp đi đến hồi kết, sẽ có rất nhiều công việc cần phải được hoàn tất cùng một lúc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I will keep you informed to the best of my ability, but as always, my first priority will be to make sure the work itself is done.\", \"vi\": \"Tôi sẽ cố gắng hết sức để cập nhật thông tin cho quý vị, nhưng như mọi khi, ưu tiên hàng đầu của tôi vẫn là đảm bảo công việc được hoàn thành.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"If the document looks acceptable to you, sign and return a copy to me.\", \"vi\": \"Nếu quý vị thấy tài liệu này phù hợp, xin vui lòng ký tên và gửi lại một bản sao cho tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Please don\'t hesitate to contact me or Evan Baurkot with any questions or concerns about how our business can serve you.\", \"vi\": \"Xin đừng ngần ngại liên hệ với tôi hoặc ông Evan Baurkot nếu quý vị có bất kỳ thắc mắc hay lo ngại nào về cách doanh nghiệp của chúng tôi có thể phục vụ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Jaco Neves\", \"vi\": \"Jaco Neves\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"CONTRACT ADDENDUM\", \"vi\": \"PHỤ LỤC HỢP ĐỒNG\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Because of work that could not be performed due to unavoidable circumstances from July 24 to July 28, the completion date for all construction will be moved from September 17 to September 22.\", \"vi\": \"Do một số công việc không thể thực hiện được vì những tình huống bất khả kháng trong khoảng thời gian từ ngày 24 tháng 7 đến ngày 28 tháng 7, nên ngày hoàn thành toàn bộ công trình sẽ được lùi từ ngày 17 tháng 9 sang ngày 22 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"The Client will not be charged any additional labor costs as a result of this change.\", \"vi\": \"Khách hàng sẽ không phải chịu bất kỳ chi phí nhân công bổ sung nào do sự thay đổi này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Any charges resulting from an extension of building permits will be paid by the Contractor.\", \"vi\": \"Mọi khoản phí phát sinh do việc gia hạn giấy phép xây dựng sẽ do Nhà thầu chi trả.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Effective immediately, the Contractor will submit a report of all work completed (including any delays incurred or anticipated) once every week, beginning on Monday, August 12.\", \"vi\": \"Có hiệu lực ngay lập tức, Nhà thầu sẽ nộp báo cáo về toàn bộ công việc đã hoàn thành (bao gồm mọi sự chậm trễ đã xảy ra hoặc dự kiến sẽ xảy ra) mỗi tuần một lần, bắt đầu từ thứ Hai, ngày 12 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}]' WHERE `id` = '46dc716a-db0e-4224-8921-1592eddefbe2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Attention, Library Members\", \"vi\": \"Kính gửi các thành viên Thư viện\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Westwood Library is excited to announce the start of a book club, which is open to all library members.\", \"vi\": \"Thư viện Westwood hân hạnh thông báo về việc thành lập một câu lạc bộ sách, mở cửa chào đón tất cả các thành viên của thư viện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The club will meet on the last Thursday of each month, from 7:00 to 9:00 P.M. in the Harrison Meeting Room, to discuss a book chosen by one of our professional staff.\", \"vi\": \"Câu lạc bộ sẽ tổ chức buổi họp vào thứ Năm cuối cùng của mỗi tháng, từ 7 giờ đến 9 giờ tối tại Phòng Họp Harrison, để thảo luận về một cuốn sách do một trong các nhân viên chuyên môn của chúng tôi lựa chọn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"From January to June, we will read recently published nonfiction works, and from July to December, we will focus on contemporary fiction titles.\", \"vi\": \"Từ tháng 1 đến tháng 6, chúng ta sẽ đọc các tác phẩm phi hư cấu mới xuất bản, và từ tháng 7 đến tháng 12, chúng ta sẽ tập trung vào các tác phẩm tiểu thuyết đương đại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"For more information, visit www.westwoodlibrary.org or speak with the staff at the circulation desk.\", \"vi\": \"Để biết thêm thông tin, quý vị vui lòng truy cập trang web www.westwoodlibrary.org hoặc liên hệ với nhân viên tại quầy mượn sách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"https://www.westwoodlibrary.org/bookclub\", \"vi\": \"https://www.westwoodlibrary.org/bookclub\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We hope you will join us for the book club on the last Thursday of each month at 7:00 P.M.! Below are the titles selected for the first half of the year.\", \"vi\": \"Chúng tôi hy vọng quý vị sẽ tham gia câu lạc bộ sách cùng chúng tôi vào thứ Năm cuối cùng của mỗi tháng, lúc 7 giờ tối! Dưới đây là danh sách các đầu sách đã được lựa chọn cho nửa đầu năm nay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"January: Wild Open Range by Jaxon McDonald\", \"vi\": \"Tháng Giêng: “Wild Open Range” của Jaxon McDonald\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"February: The Journey of a Song by Lucy Xi\", \"vi\": \"Tháng Hai: Hành trình của một bài hát – Tác giả: Lucy Xi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"March: Due North: Adventures in Alaska\'s Northern Territory by Isabel Beck\", \"vi\": \"Tháng Ba: “Due North: Những cuộc phiêu lưu tại vùng lãnh thổ phía Bắc Alaska” của Isabel Beck\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"April: The Art of Mindful Carpentry by Peter Landers\", \"vi\": \"Tháng Tư: “Nghệ thuật mộc với tâm chánh niệm” của Peter Landers\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"May: Mary Swan: A Legend Before Her Time by Kai Noble\", \"vi\": \"Tháng 5: Mary Swan: Một huyền thoại vượt thời đại, tác giả Kai Noble\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"June: To Be Announced\", \"vi\": \"Tháng 6: Sẽ được công bố sau\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To: Lisa Calle <lcalle@worldmail.com>\", \"vi\": \"Gửi tới: Lisa Calle <lcalle@worldmail.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"From: Gail Frey <gfrey@myemail.com>\", \"vi\": \"Từ: Gail Frey <gfrey@myemail.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Date: March 27\", \"vi\": \"Ngày: 27 tháng 3\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Subject: Book club\", \"vi\": \"Chủ đề: Câu lạc bộ sách\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Dear Ms. Calle,\", \"vi\": \"Kính gửi bà Calle,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"It was delightful to see you leading the book club yesterday evening.\", \"vi\": \"Thật vui khi được thấy quý vị chủ trì buổi họp câu lạc bộ sách vào tối hôm qua.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Ms. Beck\'s Due North is lengthy, and it was a challenge to finish it before the meeting.\", \"vi\": \"Cuốn sách *Due North* của bà Beck khá dày, và việc đọc xong cuốn sách này trước cuộc họp thực sự là một thách thức.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"However, I have to thank you for choosing that book because it revived my childhood interest in traveling to Alaska.\", \"vi\": \"Tuy nhiên, tôi xin chân thành cảm ơn quý vị vì đã chọn cuốn sách đó, bởi nó đã khơi dậy lại niềm đam mê du lịch đến Alaska mà tôi từng có từ thuở nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"In fact, I\'ve already looked up some tours!\", \"vi\": \"Thực ra, tôi đã tìm hiểu sẵn một số tour du lịch rồi!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"The club meeting was packed, and I hardly got to talk to you.\", \"vi\": \"Buổi họp câu lạc bộ đông nghịt người, nên tôi hầu như không có cơ hội trò chuyện với quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"We should catch up sometime soon.\", \"vi\": \"Chúng ta nên gặp nhau vào một dịp nào đó trong thời gian tới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Perhaps we might try the new French restaurant on Looper Street.\", \"vi\": \"Có lẽ chúng ta nên thử nhà hàng Pháp mới mở trên đường Looper.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I hear it is amazing and reasonably priced.\", \"vi\": \"Tôi nghe nói nơi đó rất tuyệt vời và giá cả cũng phải chăng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Gail Frey\", \"vi\": \"Gail Frey\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '46eac516-8906-40c0-aeb9-c4c57d16e0ad';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Let me disclose up front that I received a free Tipti PX200 digital camera in exchange for this post.\", \"vi\": \"Tôi xin thông báo trước rằng tôi đã nhận được một máy ảnh kỹ thuật số Tipti PX200 miễn phí để đổi lấy bài đánh giá này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"------- (143), I never hesitate to share my candid opinion, even when I receive free cameras and equipment.\", \"vi\": \"------- (143), tôi không bao giờ ngần ngại chia sẻ ý kiến thật lòng của mình, ngay cả khi tôi nhận được máy ảnh và thiết bị miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [143]}, {\"en\": \"------- (144).\", \"vi\": \"------- (144).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [144]}, {\"en\": \"The Tipti PX200 is intended for video bloggers and online content creators, but it is unsuitable for filmmakers needing a greater range of features.\", \"vi\": \"Máy ảnh Tipti PX200 được thiết kế dành cho các vlogger và người sáng tạo nội dung trực tuyến, nhưng nó không phù hợp cho các nhà làm phim cần nhiều tính năng hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"This is an important ------- (145).\", \"vi\": \"Đây là một ------- (145) quan trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [145]}, {\"en\": \"If you are looking for a compact camera that makes it ------- (146) to post short videos online, this is an excellent option for the price.\", \"vi\": \"Nếu bạn đang tìm kiếm một chiếc máy ảnh nhỏ gọn giúp bạn ------- (146) việc đăng các video ngắn lên mạng, thì đây là một lựa chọn tuyệt vời với mức giá này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [146]}, {\"en\": \"—Sonja Stanberry\", \"vi\": \"—Sonja Stanberry\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '4703b232-ae49-4789-9764-0b9661253aec';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Clareton Business Digest\", \"vi\": \"Tổng hợp tin tức kinh doanh Clareton\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"(February 8)—Many companies, especially those that sell mid-priced apparel brands, have embraced an interesting strategy.\", \"vi\": \"(Ngày 8 tháng 2) — Nhiều doanh nghiệp, đặc biệt là những doanh nghiệp kinh doanh các thương hiệu thời trang tầm trung, đã áp dụng một chiến lược thú vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Instead of focusing on local and regional markets for their products, they purposely diversify their retail locations.\", \"vi\": \"Thay vì tập trung vào các thị trường địa phương và khu vực cho các sản phẩm của mình, họ đã chủ động đa dạng hóa mạng lưới các điểm bán lẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"For example, instead of opening ten stores across East Asia, the companies may opt to limit locations in East Asia to only a few, while adding new ones in Latin America or the Middle East.\", \"vi\": \"Ví dụ, thay vì mở mười cửa hàng trên khắp khu vực Đông Á, các công ty có thể quyết định giới hạn số lượng cửa hàng tại khu vực này xuống chỉ còn vài cửa hàng, đồng thời mở thêm các cửa hàng mới tại khu vực Mỹ Latinh hoặc Trung Đông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"As Chester Mau, a marketing consultant, explained, \\\"This approach serves as a buffer against economic downturns or periods of slower growth in any one geographical area.\\\"\", \"vi\": \"Như ông Chester Mau, một chuyên gia tư vấn tiếp thị, đã giải thích: “Cách tiếp cận này đóng vai trò như một lớp đệm giúp giảm thiểu tác động của các đợt suy thoái kinh tế hoặc những giai đoạn tăng trưởng chậm lại tại bất kỳ khu vực địa lý nào.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Some of the companies already pursuing this strategy include Charisma Fashions and The Baby\'s Closet.\", \"vi\": \"Một số công ty hiện đã và đang áp dụng chiến lược này bao gồm Charisma Fashions và The Baby\'s Closet.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"With its planned April move into the Latin American market, Lolo Sportswear will follow suit.\", \"vi\": \"Với kế hoạch thâm nhập thị trường Mỹ Latinh vào tháng 4, Lolo Sportswear cũng sẽ làm theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"FOR IMMEDIATE RELEASE\", \"vi\": \"THÔNG CÁO BÁO CHÍ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"June 13\", \"vi\": \"Ngày 13 tháng 6\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Contact: Maura Keele, mkeele@lolosportswear.com\", \"vi\": \"Liên hệ: Maura Keele, mkeele@lolosportswear.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"(Clareton)—Lolo Sportswear announced today that Joseph Chakata will become its new chief executive officer.\", \"vi\": \"(Clareton)—Hôm nay, Lolo Sportswear đã thông báo rằng ông Joseph Chakata sẽ đảm nhận cương vị Giám đốc điều hành mới của công ty.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Mr. Chakata will assume responsibilities in July.\", \"vi\": \"Ông Chakata sẽ chính thức đảm nhận chức vụ vào tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"He previously served as CEO for eight years at the leading fashion design firm Colorspright, Inc.\", \"vi\": \"Trước đó, ông đã đảm nhiệm chức vụ Giám đốc điều hành trong tám năm tại công ty thiết kế thời trang hàng đầu Colorspright, Inc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Mr. Chakata will replace Shirley Alden, who founded Lolo Sportswear and then served as its CEO for eighteen years.\", \"vi\": \"Ông Chakata sẽ thay thế bà Shirley Alden, người đã thành lập Lolo Sportswear và sau đó giữ chức vụ Giám đốc điều hành của công ty này trong mười tám năm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Remarked Ms. Alden, \\\"I am pleased to be leaving Lolo Sportswear in such capable hands.\", \"vi\": \"Bà Alden nhận xét: “Tôi rất vui khi được giao lại Lolo Sportswear cho những người có năng lực như vậy.”\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The company is ready for its next big chapter.\\\"\", \"vi\": \"\\\"Công ty đã sẵn sàng bước vào chương mới đầy quan trọng của mình.\\\"\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The leadership transition comes after the successful launch in April of the company\'s first overseas stores.\", \"vi\": \"Sự chuyển giao vị trí lãnh đạo diễn ra sau khi công ty đã khai trương thành công các cửa hàng đầu tiên tại thị trường nước ngoài vào tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"An additional expansion is planned for the end of the year.\", \"vi\": \"Một đợt mở rộng nữa dự kiến sẽ được triển khai vào cuối năm nay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To: Shirley Alden <salden@mailenvoy.com>\", \"vi\": \"Gửi tới: Shirley Alden <salden@mailenvoy.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: Joseph Chakata <jchakata@lolosportswear.com>\", \"vi\": \"Từ: Joseph Chakata <jchakata@lolosportswear.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date: September 10\", \"vi\": \"Ngày: 10 tháng 9\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Re: News\", \"vi\": \"Trả lời: Tin tức\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Dear Ms. Alden,\", \"vi\": \"Kính gửi Bà Alden,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I recently learned from our mutual friend Chester Mau that you are ready to begin another commercial venture, this time in the furniture industry.\", \"vi\": \"Gần đây, tôi được biết từ người bạn chung của chúng ta là ông Chester Mau rằng quý vị đã sẵn sàng bắt tay vào một dự án kinh doanh mới, lần này là trong lĩnh vực nội thất.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I am sure that it will be a huge success.\", \"vi\": \"Tôi tin chắc rằng sự kiện này sẽ gặt hái được thành công rực rỡ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Please accept my congratulations.\", \"vi\": \"Kính xin gửi lời chúc mừng đến quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Best wishes,\", \"vi\": \"Xin gửi lời chúc tốt đẹp nhất,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Joseph Chakata\", \"vi\": \"Joseph Chakata\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '4707488e-0273-4ee7-9b2d-e8e9d2262924';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"HJ6 Miniprojector by Collierpro\", \"vi\": \"Máy chiếu mini HJ6 của Collierpro\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"https://www.buyforbusiness.com/projectors0102\", \"vi\": \"https://www.buyforbusiness.com/projectors0102\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Buy for Business Reviews Miniprojectors\", \"vi\": \"Mua sắm dành cho doanh nghiệp: Đánh giá các mẫu máy chiếu mini\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The HJ6 is a top-of-the-line miniprojector, which is no surprise to those familiar with Collierpro.\", \"vi\": \"HJ6 là một mẫu máy chiếu mini cao cấp nhất, điều này không có gì đáng ngạc nhiên đối với những ai đã quen thuộc với thương hiệu Collierpro.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"As usual, the company spared no expense in making sure this projector is easy to take almost anywhere: it is lightweight and comes with its own carrying case, which includes a remote control and a tripod.\", \"vi\": \"Như thường lệ, công ty đã không tiếc chi phí để đảm bảo chiếc máy chiếu này có thể dễ dàng mang theo đến hầu hết mọi nơi: sản phẩm có trọng lượng nhẹ và đi kèm với túi đựng riêng, trong đó có điều khiển từ xa và chân máy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Its internal lamp is much brighter than that of other projectors its size.\", \"vi\": \"Đèn chiếu bên trong của sản phẩm này sáng hơn nhiều so với các máy chiếu khác có cùng kích thước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Due to its brightness, the HJ6 was able to project the sharpest picture of all the miniprojectors that we tested.\", \"vi\": \"Nhờ độ sáng cao, mẫu HJ6 đã cho ra hình ảnh sắc nét nhất so với tất cả các mẫu máy chiếu mini mà chúng tôi đã thử nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The major weakness of the HJ6 is its speakers.\", \"vi\": \"Điểm yếu lớn nhất của HJ6 chính là hệ thống loa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"They are not nearly as loud as one would expect, given the superiority of all the other features.\", \"vi\": \"So với những tính năng vượt trội khác, mức độ ồn của chúng thực sự không cao như người ta tưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You can easily plug in different speakers.\", \"vi\": \"Quý vị có thể dễ dàng kết nối các loa khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"It is a miniprojector, however, and its small size means it is not the best choice for giving presentations in lecture halls or large conference rooms.\", \"vi\": \"Tuy nhiên, đây là một chiếc máy chiếu mini, và do kích thước nhỏ nên nó không phải là lựa chọn tối ưu để trình chiếu trong các giảng đường hay phòng hội nghị lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Overall, this is a fantastic projector for travelers, and we recommend it.\", \"vi\": \"Nhìn chung, đây là một chiếc máy chiếu tuyệt vời dành cho những người hay đi du lịch, và chúng tôi xin giới thiệu sản phẩm này đến quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"This is a new model, though, and the sticker price is quite high.\", \"vi\": \"Tuy nhiên, đây là một mẫu xe mới và giá niêm yết khá cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"It may be best to hold off making a purchase right away.\", \"vi\": \"Có lẽ tốt nhất là quý vị nên tạm hoãn việc mua hàng ngay lúc này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Projectopro will introduce the Pico P17 projector next month, so the HJ6\'s price may drop in order to remain competitive.\", \"vi\": \"Projectopro sẽ ra mắt máy chiếu Pico P17 vào tháng tới, do đó giá của mẫu HJ6 có thể sẽ giảm để duy trì khả năng cạnh tranh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The Pocket Mini C by Excellentronics\", \"vi\": \"Sản phẩm Pocket Mini C của Excellentronics\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"https://www.buyforbusiness.com/projectors0103\", \"vi\": \"https://www.buyforbusiness.com/projectors0103\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Buy for Business Reviews Miniprojectors\", \"vi\": \"Mua sắm dành cho doanh nghiệp: Đánh giá các mẫu máy chiếu mini\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The Pocket Mini C is a reliable projector and a good buy for those who aren\'t interested in spending a lot of money.\", \"vi\": \"Pocket Mini C là một chiếc máy chiếu đáng tin cậy và là lựa chọn đáng giá dành cho những ai không muốn chi quá nhiều tiền.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Like its competitors, it is lightweight and compact.\", \"vi\": \"Giống như các sản phẩm cùng phân khúc, sản phẩm này có trọng lượng nhẹ và thiết kế nhỏ gọn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"The feature we were most impressed with is its battery: it can run for up to six hours, which is much longer than the other battery-powered projectors that we tested.\", \"vi\": \"Tính năng khiến chúng tôi ấn tượng nhất chính là pin của thiết bị này: nó có thể hoạt động liên tục lên đến sáu giờ, thời lượng này dài hơn rất nhiều so với các mẫu máy chiếu chạy bằng pin khác mà chúng tôi đã thử nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"There are a few downsides, as could be expected from a budget projector.\", \"vi\": \"Cũng có một số nhược điểm, điều này cũng dễ hiểu đối với một chiếc máy chiếu giá rẻ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"The ports are in awkward locations and the menu organization is confusing, so setting up the projector is not straightforward.\", \"vi\": \"Các cổng kết nối được bố trí ở những vị trí không thuận tiện và cách sắp xếp menu khá khó hiểu, do đó việc thiết lập máy chiếu không hề đơn giản.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"The audio capabilities are also limited; when the volume is turned up, the audio can sound muffled.\", \"vi\": \"Các tính năng âm thanh cũng còn hạn chế; khi tăng âm lượng, âm thanh có thể nghe bị bóp nghẹt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"But overall, it\'s a decent miniprojector for a reasonable price.\", \"vi\": \"Tuy nhiên, nhìn chung, đây là một chiếc máy chiếu mini khá tốt với mức giá hợp lý.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '4713d947-acc2-44bd-afdb-643a8578097e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Bellevue Transport\\nAdult off-peak value ticket*\\nThe bearer of this ticket is entitled to unlimited round-trip passage between destinations on the date of issue.\\nPlease retain this ticket until completing your travel, as it may be inspected by crew members on the ferry.\\n*Off-peak value tickets are valid for travel Monday to Thursday, 9:00 A.M. to 4:00 P.M. only. Passengers who wish to travel at other times may upgrade to a regular fare ticket for $5.00. - Between Bellevue Beach\\nand Kipsky Island\\n✦\", \"vi\": \"Bellevue Transport\\nVé ưu đãi dành cho người lớn ngoài giờ cao điểm*\\nNgười mang vé này được quyền đi lại không giới hạn theo hình thức khứ hồi giữa các điểm đến vào ngày phát hành vé.\\nXin vui lòng giữ lại vé này cho đến khi kết thúc chuyến đi, vì nhân viên trên phà có thể yêu cầu kiểm tra vé.\\n*Vé ưu đãi ngoài giờ cao điểm chỉ có giá trị cho các chuyến đi từ Thứ Hai đến Thứ Năm, trong khung giờ từ 9:00 sáng đến 4:00 chiều. Hành khách có nhu cầu đi lại vào các khung giờ khác có thể nâng cấp lên vé giá thông thường với mức phụ phí 5,00 đô la. - Giữa Bellevue Beach\\nvà Đảo Kipsky\\n✦\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Between Bellevue Beach\", \"vi\": \"Giữa bãi biển Bellevue\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"and Port Canary\", \"vi\": \"và Port Canary\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}]' WHERE `id` = '473d0b38-9f8a-4ce3-b3bb-2827f07e82a9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Requesting a Building Permit\", \"vi\": \"Xin cấp giấy phép xây dựng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"A city-issued building permit may be required before initiating construction work within Morrisville city limits.\", \"vi\": \"Có thể cần phải có giấy phép xây dựng do thành phố cấp trước khi bắt đầu các công việc xây dựng trong phạm vi thành phố Morrisville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"No city permit is required for work on a building’s interior systems, such as plumbing, electrical, or heating and cooling.\", \"vi\": \"Không cần phải xin giấy phép của thành phố đối với các công việc liên quan đến hệ thống bên trong tòa nhà, chẳng hạn như hệ thống cấp thoát nước, hệ thống điện hoặc hệ thống sưởi ấm và làm mát.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"A permit will be needed for adding to or expanding the size of a building, for changing the exterior appearance of a building, or for any brand-new construction project.\", \"vi\": \"Sẽ cần phải có giấy phép trong các trường hợp sau: khi muốn xây thêm hoặc mở rộng diện tích của công trình; khi thay đổi diện mạo bên ngoài của công trình; hoặc đối với bất kỳ dự án xây dựng mới nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Below are the steps for obtaining a permit and for ensuring full compliance with city policies.\", \"vi\": \"Dưới đây là các bước để xin giấy phép và đảm bảo tuân thủ đầy đủ các quy định của thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Check that the building is appropriately registered.\", \"vi\": \"Xin vui lòng kiểm tra xem tòa nhà đã được đăng ký đúng quy định hay chưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"See the Registration and Land Use page for more information.\", \"vi\": \"Vui lòng tham khảo trang “Đăng ký và Sử dụng đất” để biết thêm thông tin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Submit an application for a building permit.\", \"vi\": \"Nộp đơn xin giấy phép xây dựng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please contact Ronald Abioye at the City Planning Office if you need assistance completing this application.\", \"vi\": \"Nếu quý vị cần sự hỗ trợ trong việc hoàn tất đơn đăng ký này, xin vui lòng liên hệ với ông Ronald Abioye tại Văn phòng Quy hoạch Thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You will receive a letter, and if your application is approved, your official building permit will be enclosed.\", \"vi\": \"Quý vị sẽ nhận được một lá thư, và nếu đơn xin của quý vị được chấp thuận, giấy phép xây dựng chính thức sẽ được đính kèm trong thư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Work may commence once the permit is received and then posted in an easily visible location at the main entrance of the construction site.\", \"vi\": \"Công việc có thể bắt đầu ngay sau khi nhận được giấy phép và sau đó giấy phép này phải được treo tại một vị trí dễ thấy ở lối vào chính của công trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"https://www.morrisville.gov.za/cityplanning/buildingpermits\", \"vi\": \"https://www.morrisville.gov.za/cityplanning/buildingpermits\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '4756d85f-34bc-4c3c-8c02-4f3f36a9ed32';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ticket Type - Price - Provides\", \"vi\": \"Loại vé - Giá - Bao gồm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Basic - £15.00 - Access to the museum\'s permanent exhibits\", \"vi\": \"Gói cơ bản - 15,00 bảng Anh - Quyền tham quan các triển lãm thường trực của bảo tàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Basic Plus - £20.00 - Basic access AND access to the Van Zandt Planetarium Show\", \"vi\": \"Gói Basic Plus - 20,00 Bảng Anh - Quyền truy cập cơ bản VÀ quyền tham dự chương trình tại Nhà thiên văn Van Zandt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Super Saver - £25.00 - Basic Plus access AND access to the Geology Lab\", \"vi\": \"Gói Siêu Tiết Kiệm - 25,00 Bảng Anh - Quyền truy cập gói Basic Plus VÀ quyền truy cập Phòng Thí nghiệm Địa chất\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Full Access - £30.00 - Super Saver access AND access to special exhibits\", \"vi\": \"Vé Truy cập Toàn phần - 30,00 Bảng Anh - Bao gồm cả quyền truy cập theo gói Siêu Tiết kiệm VÀ quyền tham quan các triển lãm đặc biệt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Morlen Museum Visitor Information\", \"vi\": \"Thông tin dành cho du khách tại Bảo tàng Morlen\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Admission:\", \"vi\": \"Điều kiện nhập học:\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Special Exhibits:\", \"vi\": \"Các triển lãm đặc biệt:\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Welcome!\", \"vi\": \"Xin chào mừng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Located just minutes from High Street Station in Richford\'s shopping district, the Morlen Museum offers visitors a chance to explore scientific topics in engaging, hands-on exhibits.\", \"vi\": \"Tọa lạc chỉ cách ga High Street vài phút trong khu mua sắm của Richford, Bảo tàng Morlen mang đến cho du khách cơ hội khám phá các chủ đề khoa học thông qua các triển lãm tương tác, hấp dẫn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Tours can be arranged for those seeking even more detailed information.\", \"vi\": \"Các tour tham quan có thể được tổ chức dành cho những ai mong muốn tìm hiểu thông tin chi tiết hơn nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Parking is available in a nearby city garage.\", \"vi\": \"Quý vị có thể đỗ xe tại một bãi đỗ xe công cộng gần đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"And don\'t forget to visit the museum shop with its wide range of unique and interesting items.\", \"vi\": \"Và xin đừng quên ghé thăm cửa hàng của bảo tàng, nơi có rất nhiều mặt hàng độc đáo và thú vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sports: The Way We Move (1 January–31 March)\", \"vi\": \"Thể thao: Cách chúng ta vận động (từ ngày 1 tháng 1 đến ngày 31 tháng 3)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Butterflies: Color in Motion (1 April–30 June)\", \"vi\": \"Bướm: Màu sắc trong chuyển động (từ ngày 1 tháng 4 đến ngày 30 tháng 6)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Mathematical Beauty: How Numbers Shape Our World (1 July–30 September)\", \"vi\": \"Vẻ đẹp của toán học: Cách các con số định hình thế giới của chúng ta (từ ngày 1 tháng 7 đến ngày 30 tháng 9)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Earth, Fire, Water, Wind: Future Power Sources (1 October–31 December)\", \"vi\": \"Đất, Lửa, Nước, Gió: Các nguồn năng lượng của tương lai (từ ngày 1 tháng 10 đến ngày 31 tháng 12)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"To: tlin@morlenmuseum.org\", \"vi\": \"Gửi tới: tlin@morlenmuseum.org\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"From: acordell@talvix.com\", \"vi\": \"Từ: acordell@talvix.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Date: 2 October\", \"vi\": \"Ngày: 2 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Subject: Upcoming excursion\", \"vi\": \"Chủ đề: Chuyến dã ngoại sắp tới\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Dear Ms. Lin,\", \"vi\": \"Kính gửi bà Lin,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I\'m writing on behalf of the Talvix Energy Professionals Partnership (TEPP).\", \"vi\": \"Tôi viết thư này thay mặt cho Hiệp hội Chuyên gia Năng lượng Talvix (TEPP).\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"The TEPP pairs young adults considering careers in the energy sector with engineers and executives from Talvix.\", \"vi\": \"Chương trình TEPP kết nối các bạn trẻ đang cân nhắc theo đuổi sự nghiệp trong lĩnh vực năng lượng với các kỹ sư và lãnh đạo cấp cao của Talvix.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Each quarter we arrange an educational trip for the program participants.\", \"vi\": \"Mỗi quý, chúng tôi tổ chức một chuyến tham quan học tập dành cho các học viên tham gia chương trình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"On 12 October we are planning for a group of six mentors and twelve mentees to visit the Morlen Museum.\", \"vi\": \"Vào ngày 12 tháng 10, chúng tôi dự kiến sẽ tổ chức cho một nhóm gồm sáu người hướng dẫn và mười hai học viên đến tham quan Bảo tàng Morlen.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"We plan to visit the Geology Lab to examine the origins of fossil fuels.\", \"vi\": \"Chúng tôi dự định sẽ đến thăm Phòng thí nghiệm Địa chất để tìm hiểu về nguồn gốc của các loại nhiên liệu hóa thạch.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"We believe an in-depth tour would be quite beneficial to the mentees.\", \"vi\": \"Chúng tôi tin rằng một chuyến tham quan chi tiết sẽ mang lại nhiều lợi ích cho các học viên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Would you be able to provide us with a tour of the lab?\", \"vi\": \"Quý vị có thể dẫn chúng tôi tham quan phòng thí nghiệm được không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"If so, what would be the cost in addition to the ticket price?\", \"vi\": \"Nếu vậy, ngoài giá vé ra thì sẽ phải trả thêm chi phí nào?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"We also want to spend time at the special exhibit.\", \"vi\": \"Chúng tôi cũng muốn dành thời gian tham quan triển lãm đặc biệt này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Thank you in advance for your assistance.\", \"vi\": \"Xin chân thành cảm ơn sự hỗ trợ của quý vị ngay từ trước.\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Alton Cordell\", \"vi\": \"Alton Cordell\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Director, TEPP\", \"vi\": \"Giám đốc, TEPP\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '47846538-7648-4ff1-9ccf-6190033abb4f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Maria Cleary\", \"vi\": \"Maria Cleary\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"2289 Coolidge Street\", \"vi\": \"Số 2289, đường Coolidge\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Great Falls, MT 59401\", \"vi\": \"Great Falls, MT 59401\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Paul Donnell\", \"vi\": \"Paul Donnell\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"5267 Cotton Vale\", \"vi\": \"5267 Cotton Vale\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Helena, MT 59624\", \"vi\": \"Helena, MT 59624\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Mr. Donnell,\", \"vi\": \"Kính gửi ông Donnell,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"After searching through Lewis and Clark County\'s public property tax records online, I discovered that you are the owner of the building that was once a general store on the corner of Waller Avenue and Main Street.\", \"vi\": \"Sau khi tra cứu trực tuyến hồ sơ thuế tài sản công của Hạt Lewis và Clark, tôi phát hiện ra rằng quý vị là chủ sở hữu của tòa nhà từng là một cửa hàng tạp hóa tọa lạc tại góc đường Waller Avenue và Main Street.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As far as I can tell, the building has been boarded up and unoccupied for quite a few years.\", \"vi\": \"Theo những gì tôi được biết, tòa nhà này đã bị đóng cửa và bỏ trống từ khá nhiều năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I would like to know if you would be interested in selling it.\", \"vi\": \"Tôi muốn biết liệu quý vị có quan tâm đến việc bán món đồ này hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I have been planning to open a café in the area, and I believe that with some modest improvements, your building could be the perfect location.\", \"vi\": \"Tôi đã có ý định mở một quán cà phê tại khu vực này, và tôi tin rằng chỉ cần một vài cải tạo nhỏ, tòa nhà của quý vị có thể trở thành địa điểm lý tưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I would want to keep as much of the original structure intact as possible.\", \"vi\": \"Tôi mong muốn giữ nguyên cấu trúc ban đầu càng nhiều càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Any modifications would be minor.\", \"vi\": \"Bất kỳ sự điều chỉnh nào cũng chỉ mang tính chất nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I realize there are other buildings for sale in the business district, but they do not have the same connection to the community.\", \"vi\": \"Tôi nhận thấy rằng có những tòa nhà khác đang được rao bán trong khu thương mại, nhưng chúng không có mối liên hệ chặt chẽ như vậy với cộng đồng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I have spoken with many Helena residents who have fond memories of your building, and they would like to see it transformed into a usable structure again.\", \"vi\": \"Tôi đã trò chuyện với nhiều cư dân thành phố Helena, những người vẫn còn lưu giữ những kỷ niệm đẹp về tòa nhà của quý vị, và họ mong muốn thấy tòa nhà này một lần nữa được biến thành một công trình có thể đưa vào sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I am confident that my plan would be welcomed by the community.\", \"vi\": \"Tôi tin tưởng rằng kế hoạch của tôi sẽ được cộng đồng hoan nghênh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Thank you for considering my offer.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã xem xét đề nghị của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"If you would like to discuss details, I can be reached at 406-555-0181.\", \"vi\": \"Nếu quý vị muốn trao đổi chi tiết, xin vui lòng liên hệ với tôi theo số 406-555-0181.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Maria Cleary\", \"vi\": \"Maria Cleary\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Maria Cleary\", \"vi\": \"Maria Cleary\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '47adf739-d9b5-424a-ba9a-baf5e0690b95';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Residents\", \"vi\": \"Kính gửi: Tất cả các cư dân\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Dan Madsen\", \"vi\": \"Từ: Dan Madsen\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 20 September\", \"vi\": \"Ngày: 20 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Georgetown Marathon\", \"vi\": \"Chủ đề: Giải marathon Georgetown\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"To all Thompson Towers residents:\", \"vi\": \"Kính gửi toàn thể cư dân Thompson Towers:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The 25th annual Georgetown Marathon will be held next Saturday.\", \"vi\": \"Giải Marathon Georgetown lần thứ 25 sẽ diễn ra vào thứ Bảy tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This year, for the first time, the race will turn off of River Street and proceed onto Elmont Avenue.\", \"vi\": \"Năm nay, lần đầu tiên, đường đua sẽ rẽ khỏi đường River Street và tiếp tục đi vào đại lộ Elmont.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"So on Saturday, there will be nearly 5,000 registered contestants running along the stretch of road that provides the only access to our Thompson Towers parking garage entrance.\", \"vi\": \"Vì vậy, vào thứ Bảy tới, sẽ có gần 5.000 thí sinh đã đăng ký tham gia chạy dọc theo đoạn đường là lối vào duy nhất dẫn đến bãi đỗ xe của tòa nhà Thompson Towers.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Unsurprisingly, Elmont Avenue will be closed to all vehicle traffic between 7:00 A.M. and 10:45 A.M. This means that residents\' cars will not be able to enter or exit our parking garage during this event.\", \"vi\": \"Không có gì ngạc nhiên khi Đại lộ Elmont sẽ bị cấm lưu thông đối với mọi phương tiện giao thông trong khoảng thời gian từ 7 giờ sáng đến 10 giờ 45 phút sáng. Điều này có nghĩa là các phương tiện của cư dân sẽ không thể ra vào bãi đỗ xe của chúng tôi trong thời gian diễn ra sự kiện này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"If you know that you will need to use your car during this period, we recommend that you make arrangements ahead of time for either leaving early or parking elsewhere.\", \"vi\": \"Nếu quý vị biết rằng mình sẽ cần sử dụng xe ô tô trong khoảng thời gian này, chúng tôi khuyên quý vị nên sắp xếp trước để ra về sớm hoặc đỗ xe ở nơi khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"For more information about the race, including maps, registration guidelines, and alternative parking locations, please go to www.georgetownmarathon.co.uk.\", \"vi\": \"Để biết thêm thông tin về cuộc đua, bao gồm bản đồ, hướng dẫn đăng ký và các địa điểm đỗ xe thay thế, vui lòng truy cập trang web www.georgetownmarathon.co.uk.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Sincerely yours,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Dan Madsen\", \"vi\": \"Dan Madsen\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Property Manager, Thompson Towers\", \"vi\": \"Quản lý Bất động sản, Thompson Towers\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '47cbb47b-09fb-439f-ae3d-84bdd72af7d4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: daiju.hasegawa@dhasegawa.com\", \"vi\": \"Nguồn: daiju.hasegawa@dhasegawa.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To: r.alvarado@shermanderm.com\", \"vi\": \"Gửi tới: r.alvarado@shermanderm.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Notice\", \"vi\": \"Chủ đề: Thông báo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Date: August 1\", \"vi\": \"Ngày: 1 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Alvarado,\", \"vi\": \"Kính gửi bà Alvarado,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Effective September 1, I will be charging $45 per hour for my graphic design services instead of my current fee of $40 per hour.\", \"vi\": \"Kể từ ngày 1 tháng 9, tôi sẽ tính phí 45 đô la mỗi giờ cho các dịch vụ thiết kế đồ họa của mình, thay vì mức phí hiện tại là 40 đô la mỗi giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This change is necessary to cover the recent rise in the cost of living in our area.\", \"vi\": \"Sự thay đổi này là cần thiết nhằm bù đắp cho mức tăng gần đây của chi phí sinh hoạt tại khu vực của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I hope that it will not be prohibitive to your medical clinic continuing to send projects my way, given your satisfaction with the template I created for your new e-mail newsletters and other work I have done.\", \"vi\": \"Tôi hy vọng rằng việc phòng khám của quý vị tiếp tục giao các dự án cho tôi sẽ không gặp trở ngại nào, bởi quý vị đã rất hài lòng với mẫu tôi thiết kế cho bản tin điện tử mới của quý vị cũng như các công việc khác mà tôi đã thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"If you do have any concerns about this change, please let me know.\", \"vi\": \"Nếu quý vị có bất kỳ lo ngại nào về sự thay đổi này, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Daiju Hasegawa\", \"vi\": \"Daiju Hasegawa\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '4898a717-b94c-47c7-ba01-ae509612f59a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Construction Projects Planned\", \"vi\": \"Các dự án xây dựng dự kiến\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"HILLSDALE (July 7)—To accommodate Hillsdale\'s ever-growing population, the town council announced on Thursday that two major construction projects are planned.\", \"vi\": \"HILLSDALE (ngày 7 tháng 7) — Nhằm đáp ứng nhu cầu của dân số ngày càng gia tăng tại Hillsdale, hội đồng thị trấn đã thông báo vào thứ Năm rằng hai dự án xây dựng quy mô lớn đang được lên kế hoạch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The first project is the construction of a new commercial area at the south end of town, since the downtown commercial district has no room to expand.\", \"vi\": \"Dự án đầu tiên là việc xây dựng một khu thương mại mới ở phía nam thị trấn, do khu thương mại trung tâm hiện không còn diện tích để mở rộng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"One section of the area will be dedicated exclusively to restaurants and small stores, while the other will be reserved for office space.\", \"vi\": \"Một phần của khu vực này sẽ được dành riêng cho các nhà hàng và cửa hàng nhỏ, trong khi phần còn lại sẽ được dành cho không gian văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The second project will build residential housing on a large empty lot at the south end.\", \"vi\": \"Dự án thứ hai sẽ xây dựng khu nhà ở trên một khu đất trống rộng lớn ở phía nam.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The new residential area and the new commercial area will be connected by a park with paved pathways.\", \"vi\": \"Khu dân cư mới và khu thương mại mới sẽ được kết nối với nhau bằng một công viên có các lối đi được lát đá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"City planners hope both projects will begin within the next month, with businesses and residents moving in late next year.\", \"vi\": \"Các nhà quy hoạch đô thị hy vọng cả hai dự án sẽ được khởi công trong vòng một tháng tới, và các doanh nghiệp cùng cư dân sẽ chuyển đến vào cuối năm sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '48c4834e-22f2-46f5-8479-59924232ecfe';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Estella Guitar Lessons: Play with the Best\", \"vi\": \"Các lớp học đàn guitar Estella: Chơi cùng những người xuất sắc nhất\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Whether you play acoustic guitar ___131___ electric, taking lessons with an Estella Guitar teacher is the best way to improve your ability.\", \"vi\": \"Cho dù bạn chơi guitar mộc ___131___ guitar điện, việc tham gia các bài học với giáo viên của Estella Guitar là cách tốt nhất để nâng cao kỹ năng của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"With years of experience crafting playing techniques, ___132___ qualified instructors can tailor lessons to focus on the skills you want to fine-tune.\", \"vi\": \"Với nhiều năm kinh nghiệm trau dồi kỹ thuật biểu diễn, các giảng viên đủ trình độ ___132___ có thể điều chỉnh các bài học để tập trung vào những kỹ năng bạn muốn hoàn thiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132]}, {\"en\": \"Receive a customized learning plan to set goals and overcome the challenges that cause many players to get discouraged.\", \"vi\": \"Nhận một kế hoạch học tập tùy chỉnh để đặt ra các mục tiêu và vượt qua những thử thách khiến nhiều người chơi cảm thấy nản lòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"___133___ .\", \"vi\": \"___133___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [133]}, {\"en\": \"An Estella Guitar teacher will help boost your confidence.\", \"vi\": \"Một giáo viên của Estella Guitar sẽ giúp nâng cao sự tự tin của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"At Estella Guitar, we believe that playing music is a way of expressing yourself.\", \"vi\": \"Tại Estella Guitar, chúng tôi tin rằng việc chơi nhạc là một cách thể hiện bản thân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"___134___ , we will help you go beyond the familiar chords and riffs to develop your own identity as a musician.\", \"vi\": \"___134___ , chúng tôi sẽ giúp bạn vượt qua những hợp âm và đoạn riff quen thuộc để phát triển bản sắc riêng của bạn với tư cách là một nhạc sĩ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [134]}, {\"en\": \"Ready to get started?\", \"vi\": \"Bạn đã sẵn sàng để bắt đầu chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Visit www.estellaguitar.com/lessons to get matched with the right instructor for you!\", \"vi\": \"Hãy truy cập www.estellaguitar.com/lessons để được ghép đôi với giảng viên phù hợp nhất với bạn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '4900ef26-0100-40c3-bacc-896bbe5422f6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Emi Mizuno <emizuno@purpleworks.com>\", \"vi\": \"Gửi tới: Emi Mizuno <emizuno@purpleworks.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Robert Callaway <rcallaway@hartwelltheater.com>\", \"vi\": \"Từ: Robert Callaway <rcallaway@hartwelltheater.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: October 10\", \"vi\": \"Ngày: 10 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Season tickets\", \"vi\": \"Chủ đề: Vé mùa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Season Ticket Holder:\", \"vi\": \"Kính gửi Quý khách hàng sở hữu vé mùa:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for purchasing your subscription to the upcoming season of plays at the Hartwell Theater.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã đăng ký mua vé cho mùa diễn sắp tới tại Nhà hát Hartwell.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"You should have already received your packet of tickets.\", \"vi\": \"Chắc hẳn quý vị đã nhận được gói vé của mình rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please contact us immediately if you have not.\", \"vi\": \"Nếu quý vị chưa làm như vậy, xin vui lòng liên hệ với chúng tôi ngay lập tức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Do you have a conflict for any of the performance dates?\", \"vi\": \"Quý vị có lịch trình trùng với bất kỳ ngày biểu diễn nào không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Only season subscribers have the benefit of exchanging tickets for another performance.\", \"vi\": \"Chỉ những người đăng ký vé theo mùa mới được hưởng quyền lợi đổi vé sang một buổi biểu diễn khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Exchanges must be made at least one week prior to the original performance date and are subject to availability.\", \"vi\": \"Việc đổi vé phải được thực hiện ít nhất một tuần trước ngày biểu diễn ban đầu và tùy thuộc vào tình trạng còn vé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"If exchanging for a higher priced performance or seating location, the price difference will be charged to your account.\", \"vi\": \"Nếu quý khách đổi sang hạng vé có giá cao hơn hoặc vị trí chỗ ngồi tốt hơn, khoản chênh lệch giá sẽ được tính vào tài khoản của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Exchanges can be requested online by filling out a ticket exchange form at www.hartwelltheater.com/ticket-exchange or by calling 555-0105 Monday–Friday from 1-5 P.M. Please note that the first time you choose to exchange tickets for a performance, you will not be charged a fee.\", \"vi\": \"Quý vị có thể yêu cầu đổi vé trực tuyến bằng cách điền vào mẫu đơn đổi vé tại địa chỉ www.hartwelltheater.com/ticket-exchange hoặc gọi đến số 555-0105 từ thứ Hai đến thứ Sáu, từ 1 giờ chiều đến 5 giờ chiều. Xin lưu ý rằng lần đầu tiên quý vị chọn đổi vé cho một buổi biểu diễn, quý vị sẽ không phải trả phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"However, any subsequent exchanges will incur a $6.25 per ticket fee.\", \"vi\": \"Tuy nhiên, bất kỳ lần đổi vé nào sau đó sẽ phải chịu phí 6,25 đô la cho mỗi vé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We look forward to seeing you at the shows.\", \"vi\": \"Chúng tôi rất mong được gặp quý vị tại các buổi biểu diễn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Robert Callaway, Subscription Manager\", \"vi\": \"Robert Callaway, Giám đốc phụ trách đăng ký\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Name: Emi Mizuno - E-mail: emizuno@purpleworks.com\", \"vi\": \"Họ tên: Emi Mizuno - Email: emizuno@purpleworks.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Subscription Number: 3698389 - Show: The Mountain Calls\", \"vi\": \"Số đăng ký: 3698389 - Chương trình: Tiếng gọi từ núi\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Performance Date: January 14, 7:30 P.M. - Seat Locations: Row V, Seats 4, 5\", \"vi\": \"Thời gian biểu diễn: Ngày 14 tháng 1, 7 giờ 30 phút tối - Vị trí ghế ngồi: Hàng V, ghế số 4, 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"1. Date: January 15, 7:30 P.M. ▼ - Seat Locations: Row D, Seats 1, 2 ▼\", \"vi\": \"1. Ngày: 15 tháng 1, 7 giờ 30 tối ▼ - Vị trí ghế: Hàng D, ghế số 1, 2 ▼\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"2. Date: January 16, 7:30 P.M. ▼ - Seat Locations: Row F, Seats 6, 7 ▼\", \"vi\": \"2. Ngày: 16 tháng 1, 7 giờ 30 phút tối ▼ - Vị trí ghế ngồi: Hàng F, ghế số 6, 7 ▼\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"3. Date: January 18, 7:30 P.M. ▼ - Seat Locations: Row T, Seats 9, 10 ▼\", \"vi\": \"3. Ngày: 18 tháng 1, 7 giờ 30 phút tối ▼ - Vị trí ghế: Hàng T, Ghế số 9, 10 ▼\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"4. Date: January 20, 2:00 P.M. ▼ - Seat Locations: Row B, Seats 15, 16 ▼\", \"vi\": \"4. Ngày: 20 tháng 1, 2 giờ chiều ▼ - Vị trí ghế: Hàng B, ghế số 15, 16 ▼\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Ticket Exchange Form\", \"vi\": \"Mẫu đơn đổi vé\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"https://www.hartwelltheater.com/ticket-exchange ▶\", \"vi\": \"https://www.hartwelltheater.com/ticket-exchange ▶\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Indicate your top four choices for alternate performances:\", \"vi\": \"Vui lòng cho biết bốn lựa chọn ưu tiên hàng đầu của quý vị cho các buổi biểu diễn dự phòng:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"You will receive an e-mail confirmation within 24 hours of submitting this form.\", \"vi\": \"Quý vị sẽ nhận được email xác nhận trong vòng 24 giờ kể từ khi gửi biểu mẫu này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"To: Emi Mizuno <emizuno@purpleworks.com>\", \"vi\": \"Gửi tới: Emi Mizuno <emizuno@purpleworks.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"From: Robert Callaway <rcallaway@hartwelltheater.com>\", \"vi\": \"Từ: Robert Callaway <rcallaway@hartwelltheater.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Date: January 6\", \"vi\": \"Ngày: 6 tháng 1\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Subject: Ticket exchange\", \"vi\": \"Chủ đề: Đổi vé\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Tickets\", \"vi\": \"Tệp đính kèm: 📎 Vé\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Dear Ms. Mizuno:\", \"vi\": \"Kính gửi bà Mizuno:\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"We have received your ticket exchange form for the upcoming play, The Mountain Calls.\", \"vi\": \"Chúng tôi đã nhận được đơn đổi vé của quý vị cho vở kịch sắp tới, *The Mountain Calls*.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"I am happy to confirm that tickets for your second choice were still available.\", \"vi\": \"Tôi rất vui được xác nhận rằng vé cho lựa chọn thứ hai của quý vị vẫn còn sẵn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Your new tickets are attached to this e-mail.\", \"vi\": \"Vé mới của quý vị đã được đính kèm trong email này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Please print them at home and present them on the evening of the performance.\", \"vi\": \"Kính mong quý vị in các tài liệu này tại nhà và mang theo khi đến tham dự buổi biểu diễn vào tối hôm đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Your old tickets are no longer valid and cannot be used.\", \"vi\": \"Các vé cũ của quý vị hiện đã hết hiệu lực và không thể sử dụng được nữa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Because you have selected a comparable seating location, there is no price difference.\", \"vi\": \"Vì quý vị đã chọn một vị trí chỗ ngồi tương đương, nên không có sự chênh lệch về giá.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"However, we will be charging your account the $6.25 per ticket exchange fee.\", \"vi\": \"Tuy nhiên, chúng tôi sẽ tính vào tài khoản của quý khách khoản phí đổi vé là 6,25 USD cho mỗi vé.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"You may log in to your account to view the charges.\", \"vi\": \"Quý vị có thể đăng nhập vào tài khoản của mình để xem các khoản phí.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Thank you for being a season ticket holder.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã là chủ thẻ vé mùa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"We look forward to seeing you at the show.\", \"vi\": \"Chúng tôi rất mong được gặp quý vị tại triển lãm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"Robert Callaway, Subscription Manager\", \"vi\": \"Robert Callaway, Trưởng phòng Quản lý Đăng ký\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 46, \"question_numbers\": []}, {\"en\": \"Hartwell Theater\", \"vi\": \"Nhà hát Hartwell\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 47, \"question_numbers\": []}]' WHERE `id` = '4993cf10-c6b8-48a4-bd95-d4beb34bacb1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"NOTICE\", \"vi\": \"THÔNG BÁO\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"On Monday, 23 September, Constellation Internet Service will install a new, state-of-the-art system here at Bluestone Tower.\", \"vi\": \"Vào thứ Hai, ngày 23 tháng 9, Công ty Dịch vụ Internet Constellation sẽ tiến hành lắp đặt một hệ thống mới, hiện đại nhất tại tòa nhà Bluestone Tower.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Internet service will be down for much of the day.\", \"vi\": \"Dịch vụ Internet sẽ bị gián đoạn trong phần lớn thời gian trong ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"This means that residents will not be able to access the building\'s wireless network, nor will it be possible for them to contact our management or maintenance staff by e-mail.\", \"vi\": \"Điều này có nghĩa là các cư dân sẽ không thể truy cập mạng không dây của tòa nhà, cũng như không thể liên hệ với ban quản lý hoặc nhân viên bảo trì của chúng tôi qua email.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Those who require access to the Internet between 9:00 A.M. and 5:00 P.M. on 23 September will need to make other arrangements.\", \"vi\": \"Những ai có nhu cầu truy cập Internet trong khoảng thời gian từ 9 giờ sáng đến 5 giờ chiều ngày 23 tháng 9 sẽ cần phải có phương án thay thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I apologize for the inconvenience.\", \"vi\": \"Tôi xin lỗi vì đã gây ra sự bất tiện này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Claire Cho\", \"vi\": \"Claire Cho\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Property Manager, Bluestone Tower\", \"vi\": \"Quản lý tòa nhà, Bluestone Tower\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '49a96db9-db1b-4ca6-9a5b-2e030941a426';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"FOR IMMEDIATE RELEASE\", \"vi\": \"THÔNG CÁO BÁO CHÍ NGAY LẬP TỨC\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Contact: Kevin Oessenich, kevin.o@albertandannies.com.au\", \"vi\": \"Liên hệ: Kevin Oessenich, kevin.o@albertandannies.com.au\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"GOOLWA (2 November)—Yesterday, Albert and Annie\'s, a leading maker of gourmet frozen desserts, unveiled several new treats: Triple Time Chocolate ice cream, a waltz of light and dark chocolate with a chocolate crumb swirl; Toffee Spree, a vanilla and toffee ice cream with sweet biscuit infusions; and a raspberry sorbet, featuring bits of real fruit.\", \"vi\": \"GOOLWA (ngày 2 tháng 11) — Hôm qua, Albert and Annie’s, một trong những nhà sản xuất hàng đầu về các món tráng miệng đông lạnh cao cấp, đã ra mắt một số sản phẩm mới: Kem sô-cô-la Triple Time, sự hòa quyện giữa sô-cô-la trắng và sô-cô-la đen cùng những vân vụn sô-cô-la; Toffee Spree, một loại kem vani và kẹo bơ cứng với hương vị bánh quy ngọt ngào; và kem sorbet mâm xôi, có chứa những miếng trái cây tươi thực sự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The new products are expected to be in Australian stores by mid-November.\", \"vi\": \"Các sản phẩm mới dự kiến sẽ có mặt tại các cửa hàng ở Úc vào khoảng giữa tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The company was founded 25 years ago by Albert and Annie Grundon, president and CEO, respectively.\", \"vi\": \"Công ty được thành lập cách đây 25 năm bởi ông Albert và bà Annie Grundon, lần lượt là Chủ tịch và Giám đốc Điều hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Earlier this year, they announced the opening of a South African division.\", \"vi\": \"Đầu năm nay, họ đã công bố việc thành lập chi nhánh tại Nam Phi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"South African retailers will get access to a number of Albert and Annie\'s products in mid-December.\", \"vi\": \"Các nhà bán lẻ Nam Phi sẽ có thể tiếp cận một số sản phẩm của thương hiệu Albert and Annie vào giữa tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To: Kevin Oessenich <kevin.o@albertandannies.com.au>\", \"vi\": \"Gửi tới: Kevin Oessenich <kevin.o@albertandannies.com.au>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"From: Skye Botha <sbotha@westerncapeeats.co.za>\", \"vi\": \"Từ: Skye Botha <sbotha@westerncapeeats.co.za>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Date: 3 November\", \"vi\": \"Ngày: 3 tháng 11\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Subject: Interview request\", \"vi\": \"Chủ đề: Yêu cầu phỏng vấn\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Dear Mr. Oessenich,\", \"vi\": \"Kính gửi ông Oessenich,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I am a reporter for Western Cape Eats, a news site for food lovers in the Cape Town area.\", \"vi\": \"Tôi là phóng viên của Western Cape Eats, một trang tin tức dành cho những người yêu thích ẩm thực tại khu vực Cape Town.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I would very much like to interview one or both of your company’s founders about your products and to find out which products will be available here in South Africa.\", \"vi\": \"Tôi rất mong được phỏng vấn một hoặc cả hai nhà sáng lập của công ty quý vị về các sản phẩm của quý vị, đồng thời tìm hiểu xem những sản phẩm nào sẽ được phân phối tại Nam Phi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"My readers are eager to know what to expect.\", \"vi\": \"Các độc giả của tôi đang rất háo hức muốn biết điều gì sẽ xảy ra.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Readers would also like to know if Albert and Annie’s will be promoting itself at this year’s Wooden Sailboat Festival.\", \"vi\": \"Quý độc giả cũng muốn biết liệu Albert và Annie’s có tham gia quảng bá tại Lễ hội Thuyền buồm Gỗ năm nay hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Most local businesses rent booths there as it is a major event.\", \"vi\": \"Hầu hết các doanh nghiệp địa phương đều thuê gian hàng tại đây vì đây là một sự kiện lớn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The interview can be conducted by phone or video chat.\", \"vi\": \"Buổi phỏng vấn có thể được tiến hành qua điện thoại hoặc trò chuyện video.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I look forward to your reply.\", \"vi\": \"Tôi mong nhận được phản hồi từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Skye Botha\", \"vi\": \"Skye Botha\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"https://www.westerncapeeats.co.za/reviews\", \"vi\": \"https://www.westerncapeeats.co.za/reviews\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"About - News - Events - Reviews\", \"vi\": \"Giới thiệu - Tin tức - Sự kiện - Đánh giá\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Jim Sato, 31 December\", \"vi\": \"Jim Sato, ngày 31 tháng 12\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Your article informing me about Albert and Annie’s, an ice-cream company that just came to South Africa, gave me one more reason to attend the annual Wooden Sailboat Festival.\", \"vi\": \"Bài báo của quý vị giới thiệu về Albert and Annie’s, một công ty kem vừa mới có mặt tại Nam Phi, đã mang đến cho tôi thêm một lý do nữa để tham dự Lễ hội Thuyền buồm Gỗ thường niên.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I got to sample some sensational ice creams at Albert and Annie’s booth.\", \"vi\": \"Tôi đã có cơ hội được nếm thử một số món kem cực kỳ ngon tại gian hàng của Albert và Annie.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"The booth offered three amazing flavours: Coffee Truffle, Fudge Mint, and Chocolate Pretzel Delight.\", \"vi\": \"Gian hàng này giới thiệu ba hương vị tuyệt vời: Truffle cà phê, Fudge bạc hà và Chocolate Pretzel Delight.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"In your article, Mr. Oessenich stated that these would be the first flavours to be rolled out to grocery outlets in South Africa and that more will become available over time.\", \"vi\": \"Trong bài viết của mình, ông Oessenich cho biết đây sẽ là những hương vị đầu tiên được đưa ra thị trường tại các cửa hàng tạp hóa ở Nam Phi và sẽ có thêm nhiều hương vị khác được ra mắt trong thời gian tới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I can’t wait!\", \"vi\": \"Tôi thật sự rất háo hức!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}]' WHERE `id` = '49b2a14f-ed48-4e7e-89eb-23d6795c19ca';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Audition for a TV Baking Show\", \"vi\": \"Vòng tuyển chọn cho một chương trình truyền hình về làm bánh\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"DUNMORE, PA—Think you have what it takes to be the next baking star?\", \"vi\": \"DUNMORE, PA — Quý vị có nghĩ rằng mình có đủ tố chất để trở thành ngôi sao làm bánh tiếp theo không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Get your cake pans and pastry brushes ready because the popular baking competition show, Toni\'s Baking Ace, has just scheduled auditions for its fifth season!\", \"vi\": \"Hãy chuẩn bị sẵn các khuôn bánh và cọ phết bánh của quý vị, bởi chương trình thi nấu ăn nổi tiếng “Toni\'s Baking Ace” vừa công bố lịch tuyển chọn thí sinh cho mùa thứ năm!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Toni\'s Baking Ace has become a huge TV hit since it premiered five years ago.\", \"vi\": \"Chương trình “Toni’s Baking Ace” đã trở thành một hiện tượng truyền hình cực kỳ ăn khách kể từ khi lên sóng lần đầu cách đây năm năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The show is named for its celebrated host, pastry chef Adrianna Toni.\", \"vi\": \"Chương trình được đặt tên theo người dẫn chương trình nổi tiếng của nó, đầu bếp bánh ngọt Adrianna Toni.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Long before becoming a TV celebrity, she founded multinational bakery chain TKL Creations and published Dolce Dancing, a dessert cookbook that has become a classic.\", \"vi\": \"Rất lâu trước khi trở thành một ngôi sao truyền hình, bà đã thành lập chuỗi tiệm bánh đa quốc gia TKL Creations và xuất bản cuốn sách nấu ăn về món tráng miệng mang tên *Dolce Dancing*, một tác phẩm đã trở thành kinh điển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"If you are an amateur baker, that is, if you have never baked as part of a business, you stand a chance of appearing on Toni\'s Baking Ace.\", \"vi\": \"Nếu quý vị là một người làm bánh nghiệp dư, tức là nếu quý vị chưa từng tham gia làm bánh trong khuôn khổ hoạt động kinh doanh, quý vị sẽ có cơ hội xuất hiện trong chương trình “Toni\'s Baking Ace”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The first step is to complete an online application.\", \"vi\": \"Bước đầu tiên là hoàn tất đơn đăng ký trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The show\'s producers will select about 50 promising candidates and send each an invitation for an in-person interview.\", \"vi\": \"Ban tổ chức chương trình sẽ lựa chọn khoảng 50 ứng viên tiềm năng và gửi thư mời từng người đến tham gia buổi phỏng vấn trực tiếp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Those who make it through this first round will attend an intensive two-day baking audition in front of the TV judges.\", \"vi\": \"Những thí sinh vượt qua vòng sơ tuyển đầu tiên này sẽ tham gia một buổi thi thực hành làm bánh chuyên sâu kéo dài hai ngày trước sự chứng kiến của ban giám khảo truyền hình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"From this audition, sixteen lucky finalists will be selected as participants to compete for the Baking Ace title!\", \"vi\": \"Từ vòng thử giọng này, mười sáu thí sinh may mắn lọt vào vòng chung kết sẽ được chọn tham gia tranh tài để giành danh hiệu “Baking Ace”!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Have your baked goods always impressed your family and friends?\", \"vi\": \"Các món bánh do quý vị làm ra có phải luôn khiến gia đình và bạn bè của quý vị phải trầm trồ không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Do not hesitate to submit your application—and get baking!\", \"vi\": \"Xin đừng ngần ngại gửi đơn đăng ký của quý vị — và hãy bắt tay vào làm bánh ngay thôi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"http://www.tonisbakingace.com\", \"vi\": \"http://www.tonisbakingace.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Name: Dennis Farah\", \"vi\": \"Họ và tên: Dennis Farah\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Phone: 414-555-0112\", \"vi\": \"Điện thoại: 414-555-0112\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"E-mail: dfarah@chemail.com\", \"vi\": \"Email: dfarah@chemail.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"• Current Occupation:\", \"vi\": \"• Nghề nghiệp hiện tại:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I have been working as a high school chemistry teacher for the past nine years.\", \"vi\": \"Trong chín năm qua, tôi đã làm việc với tư cách là giáo viên hóa học cấp trung học phổ thông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"• When did you begin to bake, and how did you learn?\", \"vi\": \"• Quý vị bắt đầu làm bánh từ khi nào, và quý vị đã học được cách làm như thế nào?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I started baking with my father when I was five years old.\", \"vi\": \"Tôi bắt đầu làm bánh cùng cha từ khi mới năm tuổi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"He loved to bake for family and friends, and I became his kitchen assistant.\", \"vi\": \"Anh ấy rất thích nướng bánh cho gia đình và bạn bè, còn tôi thì trở thành trợ lý bếp của anh ấy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I can remember researching cooking techniques, watching baking shows, and developing some of my own recipes.\", \"vi\": \"Tôi còn nhớ mình đã từng tìm hiểu các kỹ thuật nấu ăn, xem các chương trình làm bánh và tự sáng tạo ra một số công thức nấu ăn của riêng mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"• Do you have a specialty item?\", \"vi\": \"• Quý vị có mặt hàng đặc biệt nào không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Pies, especially because I like to experiment with new pie filling.\", \"vi\": \"Bánh nướng, đặc biệt là vì tôi thích thử nghiệm các loại nhân bánh mới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"• Why do you want to be on the show?\", \"vi\": \"• Tại sao quý vị muốn tham gia chương trình này?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I am passionate about baking.\", \"vi\": \"Tôi rất đam mê làm bánh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I have been watching Toni\'s Baking Ace since it first aired, and it has greatly increased my own skills, as I have tried out many top recipes that I\'ve seen on the show.\", \"vi\": \"Tôi đã theo dõi chương trình “Toni’s Baking Ace” kể từ khi chương trình này lên sóng lần đầu tiên, và điều đó đã giúp tôi nâng cao đáng kể kỹ năng nấu nướng của bản thân, bởi tôi đã thử thực hiện rất nhiều công thức nấu ăn hàng đầu mà tôi đã xem được trong chương trình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Last week a friend heard about this audition, and she persuaded me to submit an application.\", \"vi\": \"Tuần trước, một người bạn nghe nói về buổi thử giọng này và đã thuyết phục tôi nộp đơn đăng ký.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"• Have you ever marketed and sold any baked goods?\", \"vi\": \"• Quý vị đã từng tiếp thị và bán bất kỳ loại bánh nướng nào chưa?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"My formal baking experience amounts to donating cupcakes to be sold at our school\'s annual Christmas sale to support the school\'s sports programs.\", \"vi\": \"Kinh nghiệm làm bánh chính thức của tôi chỉ gói gọn trong việc quyên góp những chiếc bánh cupcake để bán tại hội chợ Giáng sinh thường niên của trường, nhằm ủng hộ các chương trình thể thao của trường.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Please upload a 60-second video introducing yourself and showing a baked creation of yours.\", \"vi\": \"Kính mong quý vị tải lên một đoạn video dài 60 giây để giới thiệu về bản thân và giới thiệu một tác phẩm nướng do chính quý vị thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Go to the Video tab to upload your video.\", \"vi\": \"Vui lòng chuyển đến tab “Video” để tải lên video của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Recipes\", \"vi\": \"Công thức nấu ăn\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Video\", \"vi\": \"Video\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Audition Application\", \"vi\": \"Buổi thử giọng cho ứng dụng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}]' WHERE `id` = '49fda3f6-901e-4705-ba78-b91b9a4d8205';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: bgosnell@bvb.org\", \"vi\": \"Đến: bgosnell@bvb.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: sluu@luumarketing.com\", \"vi\": \"Từ: sluu@luumarketing.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Online marketing research\", \"vi\": \"Chủ đề: Nghiên cứu tiếp thị trực tuyến\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: April 3\", \"vi\": \"Ngày: Ngày 3 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Gosnell,\", \"vi\": \"Kính gửi ông Gosnell,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Below are some preliminary conclusions and recommendations based on our analysis of the design of the Brookside Visitors Bureau Web site.\", \"vi\": \"Dưới đây là một số kết luận và khuyến nghị sơ bộ dựa trên phân tích của chúng tôi về thiết kế trang web của Cục Du lịch Brookside.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"First, the site is not as ______[143] as it should be.\", \"vi\": \"Thứ nhất, trang web này chưa được ______[143] như mong đợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [143]}, {\"en\": \"We recommend updating its appearance and adding information that meets the demands of today\'s tourists.\", \"vi\": \"Chúng tôi khuyên bạn nên cập nhật giao diện và bổ sung thêm thông tin đáp ứng nhu cầu của du khách ngày nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Note also that your organization\'s logo is not used consistently ______[144] your Web site.\", \"vi\": \"Cũng xin lưu ý rằng logo của tổ chức bạn chưa được sử dụng nhất quán ______[144] trên trang Web của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [144]}, {\"en\": \"You should also consider supplementing the imagery used to promote the city.\", \"vi\": \"Bạn cũng nên xem xét bổ sung các hình ảnh được sử dụng để quảng bá cho thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"______[145].\", \"vi\": \"______[145].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [145]}, {\"en\": \"We therefore recommend uploading some professionally made videos featuring the various attractions Brookside has to offer.\", \"vi\": \"Do đó, chúng tôi khuyên bạn nên tải lên một số video được sản xuất chuyên nghiệp giới thiệu các điểm tham quan khác nhau mà Brookside có.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"______[146], we suggest adding a page to the Web site that allows residents and visitors to upload their own photos and videos of city attractions.\", \"vi\": \"______[146], chúng tôi đề xuất thêm một trang vào trang web cho phép cư dân và du khách tải lên những hình ảnh và video của riêng họ về các điểm tham quan của thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [146]}, {\"en\": \"Please contact me at your earliest convenience to discuss the next steps.\", \"vi\": \"Vui lòng liên hệ với tôi vào thời gian sớm nhất có thể để thảo luận về các bước tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Shelly Luu\", \"vi\": \"Shelly Luu\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Luu Marketing\", \"vi\": \"Luu Marketing\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '4a555b09-0d85-4dc4-af81-e0faad978f72';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: jdixon@milkalenterprises.com\", \"vi\": \"Gửi tới: jdixon@milkalenterprises.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: humanresources@milkalenterprises.com\", \"vi\": \"Nguồn: humanresources@milkalenterprises.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: April 28\", \"vi\": \"Ngày: 28 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Employee survey responses\", \"vi\": \"Chủ đề: Các phản hồi từ cuộc khảo sát nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Dixon,\", \"vi\": \"Kính gửi Bà Dixon,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I read through all the responses to the semiannual employee survey, and I want to highlight a few points that were repeatedly raised.\", \"vi\": \"Tôi đã đọc kỹ tất cả các ý kiến phản hồi trong cuộc khảo sát nhân viên định kỳ sáu tháng một lần, và tôi muốn nêu bật một số điểm đã được đề cập nhiều lần.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We can use this list of suggestions to help determine our priorities.\", \"vi\": \"Chúng ta có thể sử dụng danh sách các đề xuất này để giúp xác định các ưu tiên của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Suggestion 1.\", \"vi\": \"Đề xuất 1.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"A more flexible policy for working from home\", \"vi\": \"Một chính sách linh hoạt hơn về việc làm việc tại nhà\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Suggestion 2.\", \"vi\": \"Đề xuất số 2.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"An expanded in-office recycling strategy\", \"vi\": \"Chiến lược tái chế mở rộng tại văn phòng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Suggestion 3.\", \"vi\": \"Đề xuất số 3.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"More financial rewards for excellent work\", \"vi\": \"Nhiều phần thưởng tài chính hơn cho những thành tích xuất sắc\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Suggestion 4.\", \"vi\": \"Đề xuất số 4.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"More opportunities for technical training\", \"vi\": \"Nhiều cơ hội hơn cho việc đào tạo kỹ thuật\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Also, if you approve, I would like to simplify the survey form before we administer it again.\", \"vi\": \"Ngoài ra, nếu quý vị đồng ý, tôi mong muốn đơn giản hóa mẫu phiếu khảo sát trước khi chúng ta tiến hành khảo sát lần nữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The open-ended questions make the data difficult to analyze.\", \"vi\": \"Các câu hỏi mở khiến việc phân tích dữ liệu trở nên khó khăn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I propose incorporating more yes-no questions or rating scales to determine how much a colleague agrees or disagrees with a statement.\", \"vi\": \"Tôi đề xuất bổ sung thêm các câu hỏi dạng “có” hoặc “không” hoặc thang điểm đánh giá để xác định mức độ đồng tình hay không đồng tình của đồng nghiệp đối với một nhận định nào đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Judith Hathaway, Human Resources\", \"vi\": \"Judith Hathaway, Phòng Nhân sự\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"MEMO\", \"vi\": \"BẢN GHI NHỚ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"To: All Staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"From: Jenna Dixon, General Manager\", \"vi\": \"Từ: Jenna Dixon, Tổng Giám đốc\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Date: May 8\", \"vi\": \"Ngày: 8 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Subject: Volunteers needed\", \"vi\": \"Chủ đề: Cần tuyển tình nguyện viên\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I am seeking volunteers to form a committee that will launch an office recycling program.\", \"vi\": \"Tôi đang tìm kiếm các tình nguyện viên để thành lập một ủy ban nhằm triển khai chương trình tái chế tại văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Having such a program was one of the most frequently identified needs mentioned on the recent employee survey.\", \"vi\": \"Việc có một chương trình như vậy là một trong những nhu cầu được đề cập nhiều nhất trong cuộc khảo sát nhân viên gần đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"This program will prevent recyclables, including plastics, glass, metal, paper, and cardboard, from ending up in landfills.\", \"vi\": \"Chương trình này sẽ giúp ngăn chặn các vật liệu có thể tái chế, bao gồm nhựa, thủy tinh, kim loại, giấy và bìa cứng, không bị đưa vào các bãi chôn lấp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Also, we need a volunteer to be the coordinator of this committee.\", \"vi\": \"Ngoài ra, chúng tôi cần một tình nguyện viên đảm nhận vai trò điều phối viên của ủy ban này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I will be happy to meet with this coordinator to discuss first steps.\", \"vi\": \"Tôi rất hân hạnh được gặp gỡ vị điều phối viên này để thảo luận về những bước đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Note that time spent on coordination tasks would be in addition to your regular work duties.\", \"vi\": \"Xin lưu ý rằng thời gian dành cho các nhiệm vụ điều phối sẽ là thời gian ngoài các nhiệm vụ công việc thường ngày của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"A small amount of funds will be made available to be spent on program setup costs.\", \"vi\": \"Một khoản kinh phí nhỏ sẽ được cấp để chi trả cho các chi phí thiết lập chương trình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"MEMO\", \"vi\": \"BẢN GHI NHỚ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"To: All Staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"From: Mohammad Asghari\", \"vi\": \"Từ: Mohammad Asghari\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Date: June 13\", \"vi\": \"Ngày: 13 tháng 6\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Subject: Bins are here\", \"vi\": \"Tiêu đề: Các thùng rác đã được chuyển đến\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"As chairperson of the In-office Recycling Committee, I am happy to report that we now have recycling bins in the kitchen for glass bottles, soda cans, and cardboard and paper.\", \"vi\": \"Với tư cách là Chủ tịch Ủy ban Tái chế tại Văn phòng, tôi vui mừng thông báo rằng hiện nay chúng tôi đã có các thùng tái chế đặt tại khu vực bếp dành cho chai thủy tinh, lon nước ngọt, cũng như các loại thùng carton và giấy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"It took us some time to get this program started because finding containers narrow enough to squeeze three between the door and the refrigerator proved challenging.\", \"vi\": \"Chúng tôi đã mất một khoảng thời gian để triển khai chương trình này vì việc tìm kiếm những chiếc thùng đủ hẹp để nhét vừa ba chiếc vào khoảng trống giữa cửa ra vào và tủ lạnh thực sự là một thách thức.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"But I was finally able to purchase some.\", \"vi\": \"Tuy nhiên, cuối cùng tôi cũng đã mua được một ít.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Please note that the recycling facility we are working with has stringent guidelines on what they accept, so I am creating illustrated instructions to hang above each bin.\", \"vi\": \"Xin lưu ý rằng cơ sở tái chế mà chúng tôi đang hợp tác có những quy định rất nghiêm ngặt về các loại rác được thu nhận, vì vậy tôi đang soạn thảo hướng dẫn kèm hình minh họa để treo phía trên mỗi thùng rác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Those will be up tomorrow, and committee members will be monitoring our collection system to make sure the program is going smoothly.\", \"vi\": \"Những thông tin đó sẽ được đăng tải vào ngày mai, và các thành viên ủy ban sẽ theo dõi hệ thống thu thập dữ liệu của chúng ta để đảm bảo chương trình diễn ra suôn sẻ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Please contact me with any questions, concerns, or feedback.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc, lo ngại hoặc ý kiến đóng góp nào, xin vui lòng liên hệ với tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 43, \"question_numbers\": []}]' WHERE `id` = '4a5abd39-6fbf-4ca1-8cf2-afaeaf734118';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear Bridget,\", \"vi\": \"Kính gửi Bridget,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"As you requested, this is your reminder that I’m starting my two-week medical leave on Monday.\", \"vi\": \"Theo yêu cầu của quý vị, đây là thông báo nhắc nhở rằng tôi sẽ bắt đầu kỳ nghỉ ốm kéo dài hai tuần vào thứ Hai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attached you’ll find the list of marketing campaigns that I’m currently working on, with details about the status of each.\", \"vi\": \"Trong tệp đính kèm, quý vị sẽ tìm thấy danh sách các chiến dịch tiếp thị mà tôi hiện đang phụ trách, kèm theo thông tin chi tiết về tình trạng của từng chiến dịch.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I’ve also notified the other employees involved in each campaign about my absence.\", \"vi\": \"Tôi cũng đã thông báo cho các nhân viên khác tham gia vào từng chiến dịch về việc tôi sẽ vắng mặt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In most cases, it will not be difficult for one of them to take over my duties for those two weeks.\", \"vi\": \"Trong hầu hết các trường hợp, việc một trong số họ đảm nhận các nhiệm vụ của tôi trong hai tuần đó sẽ không gặp nhiều khó khăn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The only task left is to meet with Jonathan to hand over the digital promotion plans for the launch of Yancey Cosmetic’s new nail polish line.\", \"vi\": \"Nhiệm vụ duy nhất còn lại là gặp gỡ ông Jonathan để bàn giao các kế hoạch quảng bá trực tuyến cho sự kiện ra mắt dòng sơn móng tay mới của Yancey Cosmetic.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I haven’t been able to do that yet because I needed to make some last-minute changes that the client requested.\", \"vi\": \"Tôi vẫn chưa thể thực hiện việc đó vì cần phải thực hiện một số thay đổi vào phút chót theo yêu cầu của khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I’ll make sure Jonathan is ready to update Yancey’s social media accounts at the appropriate times with the posts I’ve created.\", \"vi\": \"Tôi sẽ đảm bảo rằng Jonathan sẽ sẵn sàng cập nhật các tài khoản mạng xã hội của Yancey vào những thời điểm thích hợp bằng các bài đăng mà tôi đã soạn sẵn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Finally, while I’ll be unavailable during the first week of my leave, please feel free to contact me if necessary during the second.\", \"vi\": \"Cuối cùng, mặc dù tôi sẽ không thể liên lạc được trong tuần đầu tiên của kỳ nghỉ, nhưng nếu cần thiết, xin quý vị đừng ngần ngại liên hệ với tôi trong tuần thứ hai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Candice Holt\", \"vi\": \"Candice Holt\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '4a841d47-61be-4e19-842b-ece14d587c0e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear Ms. Muyiwa,\", \"vi\": \"Kính gửi bà Muyiwa,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Thank you for writing to express your interest in the RRVK care system.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã gửi thư bày tỏ sự quan tâm đến hệ thống chăm sóc RRVK.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"As you requested, I have attached our brochure detailing the product’s features, specifications, and pricing.\", \"vi\": \"Theo yêu cầu của quý vị, tôi đã đính kèm tài liệu giới thiệu của chúng tôi, trong đó nêu chi tiết các tính năng, thông số kỹ thuật và giá cả của sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"You mention that your hospital’s management wants you to streamline the facility’s operations.\", \"vi\": \"Quý vị có đề cập rằng ban lãnh đạo bệnh viện của quý vị mong muốn quý vị tối ưu hóa hoạt động của cơ sở này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The RRVK care system consists of kiosks loaded with specialized software designed to do just that.\", \"vi\": \"Hệ thống chăm sóc RRVK bao gồm các ki-ốt được cài đặt phần mềm chuyên dụng, được thiết kế nhằm thực hiện chính chức năng đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Your patients can use the system to check themselves in for appointments instead of waiting in line at the hospital’s front desk.\", \"vi\": \"Bệnh nhân của quý vị có thể sử dụng hệ thống này để tự làm thủ tục đăng ký khám thay vì phải xếp hàng chờ đợi tại quầy lễ tân của bệnh viện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This allows your staff to focus on more complex tasks.\", \"vi\": \"Điều này giúp đội ngũ nhân viên của quý vị tập trung vào các nhiệm vụ phức tạp hơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"If you are interested, I would be happy to give a demonstration of the system at our office.\", \"vi\": \"Nếu quý vị quan tâm, tôi rất hân hạnh được trình diễn hệ thống này tại văn phòng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Simply let me know when you are available.\", \"vi\": \"Xin vui lòng cho tôi biết khi nào quý vị rảnh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Rosemary Wolfe\", \"vi\": \"Rosemary Wolfe\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '4adeb83b-4096-4482-92dc-4e6f4a09ea9f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Garden Shade Tree Landscaping\", \"vi\": \"Dịch vụ Cảnh quan Cây bóng mát Garden Shade\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Garden Shade creates tree landscapes and hedges to suit every garden, no matter the size.\", \"vi\": \"Garden Shade tạo ra các cảnh quan cây xanh và hàng rào phù hợp với mọi khu vườn, bất kể kích thước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Our designs have ______[131] small urban gardens as well as large-scale projects commissioned by architects and property developers.\", \"vi\": \"Các thiết kế của chúng tôi đã ______[131] các khu vườn đô thị nhỏ cũng như các dự án quy mô lớn do các kiến trúc sư và nhà phát triển bất động sản ủy quyền.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [131]}, {\"en\": \"______[132].\", \"vi\": \"______[132].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [132]}, {\"en\": \"However, no single nursery can offer trees of all species and sizes.\", \"vi\": \"Tuy nhiên, không có vườn ươm duy nhất nào có thể cung cấp cây với tất cả các loài và kích cỡ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"That is why Garden Shade has developed close relationships with many specialist growers ______[133] to provide us with the trees we need.\", \"vi\": \"Đó là lý do tại sao Garden Shade đã phát triển mối quan hệ chặt chẽ với nhiều nhà trồng cây chuyên môn ______[133] để cung cấp cho chúng tôi những loại cây chúng tôi cần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [133]}, {\"en\": \"Such resources give us the variety necessary to complete any ______[134].\", \"vi\": \"Những nguồn lực như vậy mang lại cho chúng tôi sự đa dạng cần thiết để hoàn thành bất kỳ ______[134] nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [134]}, {\"en\": \"In other words, whatever your landscape design dream, we can make it happen.\", \"vi\": \"Nói cách khác, dù ước mơ thiết kế cảnh quan của bạn là gì, chúng tôi đều có thể hiện thực hóa nó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '4b61b2cf-f5e8-4949-8890-50a81db328aa';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: nora.simmons@heltlx.edu\", \"vi\": \"Gửi tới: nora.simmons@heltlx.edu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: e.agbayani@periodicalquest.com\", \"vi\": \"Nguồn: e.agbayani@periodicalquest.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: February 28\", \"vi\": \"Ngày: 28 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Periodical Quest\", \"vi\": \"Chủ đề: Cuộc tìm kiếm định kỳ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Simmons,\", \"vi\": \"Kính gửi bà Simmons,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This is a courtesy message to inform you that your monthly Periodical Quest membership fee for March could not be processed due to an expired credit card.\", \"vi\": \"Đây là thông báo nhằm trân trọng thông báo đến quý vị rằng khoản phí thành viên hàng tháng của quý vị tại Periodical Quest cho tháng 3 đã không thể được xử lý do thẻ tín dụng của quý vị đã hết hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To avoid any service disruptions, please visit periodicalquest.com/useraccount and update your billing information.\", \"vi\": \"Để tránh mọi sự gián đoạn dịch vụ, xin vui lòng truy cập trang web periodicalquest.com/useraccount và cập nhật thông tin thanh toán của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If you have any difficulties, I will be happy to take you through the process.\", \"vi\": \"Nếu quý vị gặp bất kỳ khó khăn nào, tôi sẽ rất hân hạnh được hướng dẫn quý vị thực hiện quy trình này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Incidentally, while reviewing your account I noticed that you are not using our full range of services.\", \"vi\": \"Nhân tiện, trong quá trình rà soát tài khoản của quý khách, tôi nhận thấy rằng quý khách chưa sử dụng đầy đủ các dịch vụ của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"As a member, you have unlimited online access to our library of over 3,000 journals, newspapers, and magazines.\", \"vi\": \"Với tư cách là thành viên, quý vị được quyền truy cập trực tuyến không giới hạn vào thư viện của chúng tôi, bao gồm hơn 3.000 đầu báo, tạp chí và ấn phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Additionally, as a professor you can also benefit from our resources for teaching and research purposes.\", \"vi\": \"Ngoài ra, với tư cách là giáo sư, quý vị cũng có thể tận dụng các nguồn lực của chúng tôi cho mục đích giảng dạy và nghiên cứu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It would seem that you did not complete your member profile when you signed up for our service four months ago.\", \"vi\": \"Có vẻ như quý vị chưa hoàn tất việc điền thông tin hồ sơ thành viên khi đăng ký sử dụng dịch vụ của chúng tôi cách đây bốn tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Please take a moment to review your member preferences.\", \"vi\": \"Kính mong quý vị dành một chút thời gian để xem lại các tùy chọn dành cho thành viên của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We want to make sure that you are taking advantage of all that Periodical Quest has to offer.\", \"vi\": \"Chúng tôi mong muốn đảm bảo rằng quý vị đang tận dụng tối đa tất cả những gì Periodical Quest mang lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Feel free to contact me if you have any questions regarding your account.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào liên quan đến tài khoản của mình, xin vui lòng liên hệ với tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"If you wish to cancel your membership, no further action is required.\", \"vi\": \"Nếu quý vị muốn hủy tư cách thành viên, quý vị không cần thực hiện thêm bất kỳ thao tác nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Elena Agbayani\", \"vi\": \"Elena Agbayani\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Periodical Quest\", \"vi\": \"Hành trình tìm kiếm các ấn phẩm định kỳ\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '4b6d6cfd-a9c4-4f5f-9d4a-0afc60ab45cb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"TAYLORSVILLE (October 4)—Mayor Bo Crandell of the town of Taylorsville announced plans for a bicycle-share program this week.\", \"vi\": \"TAYLORSVILLE (Ngày 4 tháng 10)—Thị trưởng Bo Crandell của thị trấn Taylorsville đã công bố kế hoạch cho một chương trình chia sẻ xe đạp trong tuần này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Past efforts to encourage the use of bicycles for transportation failed because there were no convenient areas to park bicycles downtown.\", \"vi\": \"Những nỗ lực trước đây nhằm khuyến khích sử dụng xe đạp làm phương tiện giao thông đã thất bại vì không có khu vực thuận tiện để đỗ xe đạp ở trung tâm thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Additionally, cyclists ______[139] to share narrow streets with cars and trucks, raising safety concerns.\", \"vi\": \"Ngoài ra, người đi xe đạp ______[139] phải đi chung các con đường chật hẹp với ô tô và xe tải, làm dấy lên những lo ngại về an toàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [139]}, {\"en\": \"With the new bicycle-share initiative, bicycle stations will be placed ______[140] at eight locations around Taylorsville.\", \"vi\": \"Với Sáng kiến chia sẻ xe đạp mới, các trạm xe đạp sẽ được đặt ______[140] tại tám địa điểm quanh Taylorsville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [140]}, {\"en\": \"One important purpose of the initiative is to ease the limited vehicle parking in the downtown area.\", \"vi\": \"Một mục đích quan trọng của sáng kiến này là làm giảm bớt tình trạng hạn chế đỗ xe cơ giới tại khu vực trung tâm thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"\\\"______[141], I want to encourage local residents to spend more time outdoors and enjoy our beautiful town,\\\" added the mayor at the end of his remarks.\", \"vi\": \"\\\"______[141], tôi muốn khuyến khích người dân địa phương dành nhiều thời gian hơn ở ngoài trời và tận hưởng thị trấn xinh đẹp của chúng ta,\\\" thị trưởng cho biết thêm vào cuối bài phát biểu của ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [141]}, {\"en\": \"______[142].\", \"vi\": \"______[142].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [142]}]' WHERE `id` = '4c59c881-d12c-4eb8-8eda-9a2b82fa072e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Customer Service <customerservice@kishintech.com>\", \"vi\": \"Gửi tới: Bộ phận Dịch vụ Khách hàng <customerservice@kishintech.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Dmytro Petrov <d.petrov@silkmail.com>\", \"vi\": \"Từ: Dmytro Petrov <d.petrov@silkmail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: November 5\", \"vi\": \"Ngày: 5 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Assistance with Kishin XT20 digital recorder\", \"vi\": \"Chủ đề: Hỗ trợ về máy ghi âm kỹ thuật số Kishin XT20\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"To Whom It May Concern:\", \"vi\": \"Kính gửi quý vị có liên quan:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I purchased the Kishin XT20 digital recorder to record several days\' worth of conference presentations.\", \"vi\": \"Tôi đã mua máy ghi âm kỹ thuật số Kishin XT20 để ghi lại các bài thuyết trình tại hội nghị trong vài ngày.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Now, after my first day at the event, I am trying to transfer the audio files to my laptop, but I am not having any luck.\", \"vi\": \"Hiện tại, sau ngày đầu tiên tham dự sự kiện, tôi đang cố gắng chuyển các tệp âm thanh sang máy tính xách tay của mình, nhưng vẫn chưa thành công.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I have followed all the instructions in the user manual as well as the tips found in the FAQ section of the product\'s Web page.\", \"vi\": \"Tôi đã tuân thủ tất cả các hướng dẫn trong sách hướng dẫn sử dụng cũng như các lời khuyên được nêu trong phần Câu hỏi thường gặp (FAQ) trên trang web của sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I have even tried alternative cords and the laptops in the hotel\'s business center, so I do not believe computer hardware to be the issue.\", \"vi\": \"Tôi thậm chí đã thử sử dụng các loại dây cáp khác và các máy tính xách tay tại trung tâm kinh doanh của khách sạn, nên tôi không cho rằng vấn đề nằm ở phần cứng máy tính.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I am supposed to cover the remaining two days of this conference for work.\", \"vi\": \"Theo kế hoạch, tôi sẽ phải đảm nhận việc đưa tin về hai ngày còn lại của hội nghị này trong khuôn khổ công việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"My business partners expect me to return with as much information as I can.\", \"vi\": \"Các đối tác kinh doanh của tôi mong muốn tôi thu thập được càng nhiều thông tin càng tốt khi trở về.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The Kishin XT20 digital recorder is of no use to me if I cannot properly share the files.\", \"vi\": \"Máy ghi âm kỹ thuật số Kishin XT20 sẽ không có ích gì đối với tôi nếu tôi không thể chia sẻ các tệp tin một cách đúng đắn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Can you please help?\", \"vi\": \"Xin quý vị vui lòng giúp đỡ được không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dmytro Petrov\", \"vi\": \"Dmytro Petrov\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '4c5bebcc-bd70-4bd5-befc-a32bb4e9dea8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: jroux@xmail.com\\nFrom: josephbelle@perilleuxrealestate.com\\nDate: March 2\\nSubject: Your job inquiry\", \"vi\": \"Đến: jroux@xmail.com\\nTừ: josephbelle@perilleuxrealestate.com\\nNgày: Ngày 2 tháng 3\\nChủ đề: Thư hỏi việc của bạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear Ms. Roux:\", \"vi\": \"Kính gửi Bà Roux:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Your résumé ______[139] to me by a colleague.\", \"vi\": \"Sơ yếu lý lịch của bạn ______[139] cho tôi bởi một đồng nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [139]}, {\"en\": \"______[140].\", \"vi\": \"______[140].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [140]}, {\"en\": \"We appreciate your interest in Perilleux Real Estate and will keep your ______[141] on file in case a full-time position opens up in the future.\", \"vi\": \"Chúng tôi đánh giá cao sự quan tâm của bạn đến Perilleux Real Estate và sẽ lưu hồ sơ của bạn ______[141] trong trường hợp có vị trí toàn thời gian trống trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [141]}, {\"en\": \"______[142], would you consider working for us part-time on a special project?\", \"vi\": \"______[142], bạn có cân nhắc làm việc bán thời gian cho chúng tôi trong một dự án đặc biệt không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [142]}, {\"en\": \"Our CEO needs administrative support on an ambitious advertising campaign.\", \"vi\": \"Giám đốc điều hành của chúng tôi cần sự hỗ trợ hành chính cho một chiến dịch quảng cáo đầy tham vọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The project should last until the end of July.\", \"vi\": \"Dự án dự kiến kéo dài cho đến hết tháng Bảy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Kindly let me know if this opportunity interests you.\", \"vi\": \"Vui lòng cho tôi biết nếu cơ hội này làm bạn quan tâm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Joseph Belle, Vice President\", \"vi\": \"Joseph Belle, Phó Chủ tịch\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Human Resources\", \"vi\": \"Phòng Nhân sự\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '4c5e5ce2-f6bd-49c2-a12c-64149ca7529e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Bradley Watkins\", \"vi\": \"Kính gửi: Bradley Watkins\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Aiko Yamashita\", \"vi\": \"Từ: Aiko Yamashita\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: New software\", \"vi\": \"Chủ đề: Phần mềm mới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: April 4\", \"vi\": \"Ngày: 4 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Bradley, I\'ve come across a new software program that I think will be very useful for creating checklists to organize our projects.\", \"vi\": \"Bradley ạ, tôi vừa phát hiện ra một phần mềm mới mà tôi nghĩ sẽ rất hữu ích trong việc lập danh sách kiểm tra để sắp xếp các dự án của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It\'s called Close Project, and it seems fairly easy to work with.\", \"vi\": \"Tính năng này có tên là “Close Project”, và dường như khá dễ sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Users log in to view a list of items that need to be completed for each project they are working on.\", \"vi\": \"Người dùng đăng nhập để xem danh sách các nhiệm vụ cần hoàn thành cho từng dự án mà họ đang thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"This helps to keep better track of the progress of each project.\", \"vi\": \"Điều này giúp theo dõi tiến độ của từng dự án một cách hiệu quả hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"There\'s even a mobile application that allows users to take photographs to show an actual problem, such as a broken pipe.\", \"vi\": \"Thậm chí còn có một ứng dụng di động cho phép người dùng chụp ảnh để ghi lại tình trạng sự cố thực tế, chẳng hạn như đường ống bị vỡ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I\'ve downloaded a sample program.\", \"vi\": \"Tôi đã tải xuống một chương trình mẫu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Would you be interested in coming to my office this afternoon to go through it with me?\", \"vi\": \"Quý vị có muốn ghé qua văn phòng của tôi vào chiều nay để cùng tôi xem xét vấn đề này không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Let me know.\", \"vi\": \"Xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Aiko\", \"vi\": \"Tôi là\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '4c8ecf59-445e-4a91-9779-8b23ad6251f6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dear Customers,\", \"vi\": \"Kính gửi quý khách hàng,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"After 45 years in business, Ghearey Garden Goods locked its doors for the final time on Saturday, January 10.\", \"vi\": \"Sau 45 năm hoạt động, cửa hàng Ghearey Garden Goods đã chính thức đóng cửa vĩnh viễn vào thứ Bảy, ngày 10 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"As many of you know, I purchased a farmhouse in the country several years ago, and I had been driving three hours a day to get to the store and back.\", \"vi\": \"Như nhiều quý vị đã biết, cách đây vài năm, tôi đã mua một ngôi nhà kiểu nông trại ở vùng quê, và từ đó đến nay, tôi phải lái xe ba giờ mỗi ngày để đi đến cửa hàng rồi quay về.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"While I am saddened to walk away from this business, it is just no longer sustainable for me to spend so much time in transit.\", \"vi\": \"Dù tôi cảm thấy buồn khi phải rời bỏ công việc kinh doanh này, nhưng việc phải dành quá nhiều thời gian di chuyển thực sự không còn phù hợp với tôi nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"My grandfather, Timothy Ghearey, who built the business nearly 60 years ago before handing it off to me, always said that his favorite part about running a retail store was serving the needs of his community.\", \"vi\": \"Ông nội tôi, Timothy Ghearey, người đã xây dựng nên doanh nghiệp này cách đây gần 60 năm trước khi chuyển giao lại cho tôi, luôn nói rằng điều ông yêu thích nhất khi điều hành một cửa hàng bán lẻ chính là được phục vụ nhu cầu của cộng đồng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I echo this sentiment.\", \"vi\": \"Tôi cũng đồng tình với quan điểm này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Words cannot express how much joy I have received from interacting with all of you, and I want you to know how much I value your dedicated support over all these years.\", \"vi\": \"Không lời nào có thể diễn tả hết niềm vui mà tôi đã nhận được từ việc giao lưu với tất cả quý vị, và tôi muốn quý vị biết rằng tôi trân trọng sự ủng hộ tận tâm của quý vị trong suốt những năm qua đến nhường nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Thank you for understanding what a truly difficult decision this was.\", \"vi\": \"Xin cảm ơn quý vị đã thấu hiểu rằng đây thực sự là một quyết định vô cùng khó khăn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"But while the physical Ghearey Garden Goods location is closing, ghearygardengoods.com will remain a resource for home gardeners through our Web site.\", \"vi\": \"Tuy nhiên, mặc dù cửa hàng Ghearey Garden Goods sẽ đóng cửa, trang web ghearygardengoods.com sẽ tiếp tục là nguồn thông tin hữu ích dành cho những người yêu thích làm vườn tại nhà thông qua nền tảng trực tuyến của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I will keep adding educational blog posts and articles as I have time.\", \"vi\": \"Tôi sẽ tiếp tục đăng tải các bài viết và bài báo mang tính giáo dục trên blog mỗi khi có thời gian.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Thank you for your support!\", \"vi\": \"Xin chân thành cảm ơn sự ủng hộ của quý vị!\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Jerry Sanderson\", \"vi\": \"Jerry Sanderson\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Jerry Sanderson\", \"vi\": \"Jerry Sanderson\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Ghearey Garden Goods\", \"vi\": \"Các sản phẩm làm vườn Ghearey\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '4cbb1b41-0b7b-486a-b323-ddb866e0a04c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Foxtail Airlines\", \"vi\": \"Hãng hàng không Foxtail\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"July 30\", \"vi\": \"Ngày 30 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Ms. Gina Carracia\", \"vi\": \"Bà Gina Carracia\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"General Manager\", \"vi\": \"Tổng Giám đốc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Obsidian Villa\", \"vi\": \"Biệt thự Obsidian\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"1121 Marine Boulevard\", \"vi\": \"1121 Marine Boulevard\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Seattle, WA 98101\", \"vi\": \"Seattle, WA 98101\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Dear Ms. Carracia:\", \"vi\": \"Kính gửi bà Carracia:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"My name is Isaac Bolton, and I am Director of Marketing at Foxtail Airlines.\", \"vi\": \"Tên tôi là Isaac Bolton, và tôi hiện là Giám đốc Tiếp thị tại Hãng hàng không Foxtail.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I am writing to share a marketing idea with you that would be beneficial for both our companies.\", \"vi\": \"Tôi viết thư này để chia sẻ với quý vị một ý tưởng tiếp thị mà tôi tin rằng sẽ mang lại lợi ích cho cả hai công ty chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Our crew members who fly into Seattle have stayed at Obsidian Villa several times in the past.\", \"vi\": \"Các thành viên phi hành đoàn của chúng tôi khi bay đến Seattle đã từng lưu trú tại Obsidian Villa nhiều lần trong quá khứ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"They report that the rooms are consistently comfortable and clean and that the staff is friendly and efficient.\", \"vi\": \"Họ cho biết các phòng luôn thoải mái và sạch sẽ, đồng thời đội ngũ nhân viên rất thân thiện và làm việc hiệu quả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"However, there is often no vacancy at your excellent establishment, and so our crews must stay elsewhere.\", \"vi\": \"Tuy nhiên, thường thì tại cơ sở tuyệt vời của quý vị không có phòng trống, do đó các đội của chúng tôi buộc phải lưu trú ở nơi khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We have arrangements with hotels in several cities around the world in which rooms are reserved for our crews in advance.\", \"vi\": \"Chúng tôi đã ký kết thỏa thuận với các khách sạn tại nhiều thành phố trên thế giới, theo đó các phòng sẽ được đặt trước dành riêng cho đội ngũ nhân viên của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Foxtail Airlines advertises for these hotels in our in-flight magazine at a significant discount.\", \"vi\": \"Hãng hàng không Foxtail Airlines đang quảng cáo các khách sạn này trên tạp chí trên máy bay của chúng tôi với mức giảm giá đáng kể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We would like to develop a similar partnership with Obsidian Villa.\", \"vi\": \"Chúng tôi mong muốn thiết lập một mối quan hệ hợp tác tương tự với Obsidian Villa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"To give you an idea of the advertising possibilities we offer, our graphic design team has created four potential advertisements.\", \"vi\": \"Để quý vị có cái nhìn tổng quan về các giải pháp quảng cáo mà chúng tôi cung cấp, đội ngũ thiết kế đồ họa của chúng tôi đã thiết kế bốn mẫu quảng cáo tiềm năng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"They are enclosed with this letter.\", \"vi\": \"Các tài liệu này được đính kèm theo thư này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I hope these samples demonstrate how enthusiastic we are about promoting Obsidian Villa to the over three million passengers who fly with us every year.\", \"vi\": \"Tôi hy vọng những mẫu quảng cáo này sẽ thể hiện được sự nhiệt tình của chúng tôi trong việc quảng bá Obsidian Villa đến hơn ba triệu hành khách bay cùng chúng tôi mỗi năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"If you are interested in exploring this idea further, please contact me by phone at 546-555-0182 or by e-mail at i.r.bolton@foxtailairlines.com.\", \"vi\": \"Nếu quý vị quan tâm đến việc tìm hiểu sâu hơn về ý tưởng này, xin vui lòng liên hệ với tôi qua số điện thoại 546-555-0182 hoặc qua email tại địa chỉ i.r.bolton@foxtailairlines.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I hope to have the opportunity to work with you.\", \"vi\": \"Tôi hy vọng sẽ có cơ hội được hợp tác với quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Isaac Bolton\", \"vi\": \"Isaac Bolton\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Isaac Bolton, Director of Marketing\", \"vi\": \"Ông Isaac Bolton, Giám đốc Tiếp thị\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Foxtail Airlines\", \"vi\": \"Hãng hàng không Foxtail\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Enclosures\", \"vi\": \"Phụ lục\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 30, \"question_numbers\": []}]' WHERE `id` = '4d0138ec-b33d-4249-b0aa-32e1fa91f5a0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Name: Arturo Rami - Address: 10 Beamish Street, Werribee, VIC 3030\", \"vi\": \"Họ tên: Arturo Rami - Địa chỉ: 10 Beamish Street, Werribee, VIC 3030\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"E-mail: arturo.rami@amail.com.au - Telephone: 03 9555 3744\", \"vi\": \"Email: arturo.rami@amail.com.au - Điện thoại: 03 9555 3744\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Desired position - Assistant Store Manager\", \"vi\": \"Vị trí ứng tuyển - Trợ lý Quản lý Cửa hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Available start date - 20 September\", \"vi\": \"Ngày bắt đầu dự kiến - 20 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Preferred location - ☐ Seaholme    ☑ Werribee    ☐ Port Melbourne\", \"vi\": \"Địa điểm ưu tiên - ☐ Seaholme    ☑ Werribee    ☐ Port Melbourne\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Preferred status - ☑ Full-time    ☐ Part-time    ☐ Temporary\", \"vi\": \"Loại hình công việc ưu tiên - ☑ Toàn thời gian    ☐ Bán thời gian    ☐ Tạm thời\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Educational Institution - Diploma/Certificate/Degree Earned\", \"vi\": \"Cơ sở giáo dục - Bằng tốt nghiệp/Chứng chỉ/Bằng cấp đã đạt được\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"South Bank High School - High school diploma\", \"vi\": \"Trường Trung học South Bank - Bằng tốt nghiệp trung học phổ thông\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Dymocks University - Bachelor\'s degree\", \"vi\": \"Đại học Dymocks - Bằng Cử nhân\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Employer - Position - Duration\", \"vi\": \"Tên đơn vị tuyển dụng - Vị trí công việc - Thời gian làm việc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The Garment Barn - Sales associate - 2 years\", \"vi\": \"The Garment Barn - Nhân viên bán hàng - 2 năm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Altona Marketing - Assistant manager - 3 years\", \"vi\": \"Altona Marketing - Trợ lý quản lý - 3 năm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Page Turner Booksellers\", \"vi\": \"Hiệu sách Page Turner\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Employment Application Form\", \"vi\": \"Mẫu đơn xin việc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date of Application: 1 September\", \"vi\": \"Ngày nộp đơn: 1 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"PERSONAL DATA\", \"vi\": \"DỮ LIỆU CÁ NHÂN\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"EMPLOYMENT DESIRED\", \"vi\": \"TÌM VIỆC LÀM\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"EDUCATION\", \"vi\": \"GIÁO DỤC\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"EMPLOYMENT HISTORY\", \"vi\": \"LỊCH SỬ CÔNG TÁC\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"EXPLANATION OF INTEREST IN THE POSITION\", \"vi\": \"LÝ DO QUAN TÂM ĐẾN VỊ TRÍ NÀY\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I flourish in a fast-paced and demanding work environment, which my most recent employers are known for.\", \"vi\": \"Tôi phát huy được khả năng của mình trong môi trường làm việc nhịp độ nhanh và đòi hỏi cao, vốn là điểm nổi bật của các đơn vị mà tôi từng làm việc gần đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I expect the same is true of Page Turner Booksellers, which tends to be quite busy.\", \"vi\": \"Tôi cho rằng điều này cũng đúng với hiệu sách Page Turner Booksellers, nơi thường khá đông khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Moreover, with my bachelor\'s degree in retail management, I believe I am well suited for the position.\", \"vi\": \"Hơn nữa, với bằng cử nhân về quản trị bán lẻ, tôi tin rằng mình hoàn toàn phù hợp với vị trí này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '4d3b5dca-8ece-4c84-8183-d5dffc6ec001';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Look to Riessler Landscaping for your Garden Needs\", \"vi\": \"Hãy đến với Riessler Landscaping để đáp ứng mọi nhu cầu về khu vườn của bạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Riessler Landscaping has everything you need to create your dream garden.\", \"vi\": \"Riessler Landscaping có mọi thứ bạn cần để tạo nên khu vườn trong mơ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We will listen to your ideas and offer suggestions that match your gardening desires.\", \"vi\": \"Chúng tôi sẽ lắng nghe ý tưởng của bạn và đưa ra những gợi ý phù hợp với sở thích làm vườn của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"------- (131).\", \"vi\": \"------- (131).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [131]}, {\"en\": \"The nursery here at Riessler Landscaping includes plants of many varieties and sizes that burst with eye-catching colors year-round.\", \"vi\": \"Khu vườn ươm tại Riessler Landscaping bao gồm nhiều loại và kích cỡ cây trồng khác nhau luôn nở rộ những màu sắc bắt mắt quanh năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"You are guaranteed to find something that will add ------- (132) to your garden.\", \"vi\": \"Bạn chắc chắn sẽ tìm thấy thứ gì đó giúp tăng thêm ------- (132) cho khu vườn của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [132]}, {\"en\": \"We are ------- (133) equipped to construct small ponds or other water features.\", \"vi\": \"Chúng tôi ------- (133) được trang bị đầy đủ để thi công các hồ nước nhỏ hoặc các tiểu cảnh nước khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [133]}, {\"en\": \"And as our name suggests, we can take on more ambitious landscaping projects—whatever you need!\", \"vi\": \"Và đúng như tên gọi của chúng tôi, chúng tôi có thể đảm nhận các dự án cảnh quan đầy tham vọng hơn—bất cứ điều gì bạn cần!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"With more than 40 years in the landscape-design business, ------- (134) expertise is unmatched.\", \"vi\": \"Với hơn 40 năm hoạt động trong lĩnh vực thiết kế cảnh quan, ------- (134) chuyên môn là không gì sánh bằng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [134]}]' WHERE `id` = '4d838179-03dc-445b-81ce-71bd6d13620a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Delroy Gerew (1:29 P.M.):\", \"vi\": \"Delroy Gerew (1 giờ 29 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Ms. Chichester, we\'d like to order another 10 shirts, featuring the company\'s name, Magnalook, and its logo.\", \"vi\": \"Xin chào, thưa bà Chichester, chúng tôi muốn đặt thêm 10 chiếc áo thun có in tên công ty là Magnalook cùng với logo của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We need four small, two medium, and four large sizes.\", \"vi\": \"Chúng tôi cần bốn chiếc cỡ nhỏ, hai chiếc cỡ vừa và bốn chiếc cỡ lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Could you fill the order by Friday?\", \"vi\": \"Quý vị có thể hoàn tất đơn hàng trước thứ Sáu được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Nina Chichester (1:32 P.M.):\", \"vi\": \"Nina Chichester (13 giờ 32 phút):\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"That\'s two days from today, so a $75 rush-order fee will be added.\", \"vi\": \"Đó là hai ngày kể từ hôm nay, do đó sẽ có thêm khoản phí xử lý đơn hàng khẩn cấp trị giá 75 đô la.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Delroy Gerew (1:34 P.M.):\", \"vi\": \"Delroy Gerew (1 giờ 34 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"How can we avoid the fee?\", \"vi\": \"Làm thế nào để chúng ta có thể tránh phải trả khoản phí này?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Nina Chichester (1:36 P.M.):\", \"vi\": \"Nina Chichester (1 giờ 36 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"By choosing the standard 5-day production option.\", \"vi\": \"Bằng cách lựa chọn phương án sản xuất tiêu chuẩn trong 5 ngày.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Your order would be ready Monday of next week.\", \"vi\": \"Đơn hàng của quý khách sẽ được hoàn tất vào thứ Hai tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Delroy Gerew (1:38 P.M.):\", \"vi\": \"Delroy Gerew (1 giờ 38 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I guess it can\'t be helped.\", \"vi\": \"Tôi nghĩ rằng cũng chẳng thể làm gì khác được.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Since we have employees starting this Friday and you open at 8:00 A.M., can I pick up the shirts at that time?\", \"vi\": \"Vì chúng tôi có nhân viên bắt đầu làm việc vào thứ Sáu tuần này và quý công ty mở cửa lúc 8 giờ sáng, vậy tôi có thể đến nhận áo vào thời gian đó được không ạ?\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Nina Chichester (1:39 P.M.):\", \"vi\": \"Nina Chichester (1 giờ 39 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Pick-up time is normally after 1:00 P.M., but I\'ll see to it they\'re ready by 8:00 A.M.\", \"vi\": \"Thời gian nhận hàng thường là sau 1 giờ chiều, nhưng tôi sẽ đảm bảo rằng hàng sẽ sẵn sàng trước 8 giờ sáng.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Delroy Gerew (1:41 P.M.):\", \"vi\": \"Delroy Gerew (1 giờ 41 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Xin cảm ơn.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Actually, my assistant will be picking them up.\", \"vi\": \"Thực ra, trợ lý của tôi sẽ đến nhận chúng.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Nina Chichester (1:42 P.M.):\", \"vi\": \"Nina Chichester (1 giờ 42 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 7, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"That\'s fine.\", \"vi\": \"Không sao cả.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Could you please e-mail me your logo again?\", \"vi\": \"Xin quý vị vui lòng gửi lại logo của quý vị cho tôi qua email được không?\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"The computer on which I had it stored crashed the other day and is awaiting repair.\", \"vi\": \"Chiếc máy tính mà tôi đã lưu trữ dữ liệu đó đã bị hỏng cách đây vài ngày và hiện đang chờ sửa chữa.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Delroy Gerew (1:44 P.M.):\", \"vi\": \"Delroy Gerew (1 giờ 44 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 8, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Will do.\", \"vi\": \"Vâng, tôi sẽ làm ngay.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Thanks, and please charge the credit card you have on file for us.\", \"vi\": \"Xin cảm ơn, và xin vui lòng thanh toán qua thẻ tín dụng mà quý khách đã đăng ký với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '4da47750-2d6e-4959-a61c-85b865ad594a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Larisa M. Lee\", \"vi\": \"Kính gửi: Bà Larisa M. Lee\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Minnich Furniture\", \"vi\": \"Từ: Minnich Furniture\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Furniture Sale Ends Friday\", \"vi\": \"Chủ đề: Chương trình khuyến mãi đồ nội thất sẽ kết thúc vào thứ Sáu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: Wednesday, 28 August\", \"vi\": \"Ngày: Thứ Tư, ngày 28 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Minnich Furniture Seasonal Sale!\", \"vi\": \"Chương trình khuyến mãi theo mùa của Minnich Furniture!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Last three days for up to 50% savings.\", \"vi\": \"Chỉ còn ba ngày nữa để được giảm giá lên đến 50%.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Shop for:\", \"vi\": \"Mua sắm các sản phẩm:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Sectionals - Lamps - Sofas - Bedroom sets\", \"vi\": \"Bộ ghế sofa ghép - Đèn - Ghế sofa - Bộ đồ nội thất phòng ngủ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Over 1,000 items on sale.\", \"vi\": \"Hơn 1.000 mặt hàng đang được giảm giá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Hurry!\", \"vi\": \"Nhanh lên!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Inventory is going fast!\", \"vi\": \"Hàng tồn kho đang cạn dần!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Shop online at www.minnichfurniture.com\", \"vi\": \"Mua sắm trực tuyến tại www.minnichfurniture.com\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Limited quantities of certain items are available.\", \"vi\": \"Một số mặt hàng hiện chỉ có sẵn với số lượng hạn chế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Limit 2 sale items per customer.\", \"vi\": \"Mỗi khách hàng chỉ được mua tối đa 2 mặt hàng đang khuyến mãi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Offer applies to Internet orders only.\", \"vi\": \"Ưu đãi này chỉ áp dụng cho các đơn hàng đặt qua Internet.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Additional cost for shipping.\", \"vi\": \"Phí vận chuyển sẽ được tính thêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Returns must be initiated within 30 days.\", \"vi\": \"Quý khách phải tiến hành thủ tục trả hàng trong vòng 30 ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"See Web site for full details and photos of all offerings.\", \"vi\": \"Vui lòng truy cập trang web để xem thông tin chi tiết đầy đủ và hình ảnh về tất cả các sản phẩm được cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '4dd98e2c-90f2-4d9a-9626-d222b44610bc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Dennis Maki\", \"vi\": \"Kính gửi: Dennis Maki\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Nigella Smith\", \"vi\": \"Từ: Nigella Smith\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: Thursday, November 8, 2:15 P.M.\", \"vi\": \"Ngày: Thứ Năm, ngày 8 tháng 11, 2 giờ 15 phút chiều\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Update\", \"vi\": \"Chủ đề: Cập nhật\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dennis:\", \"vi\": \"Dennis:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The heads of accounting and sales have chosen the finalists for the job openings in their departments here at Plumsted Aynes.\", \"vi\": \"Các trưởng phòng Kế toán và Kinh doanh đã chọn ra các ứng viên lọt vào vòng chung kết cho các vị trí tuyển dụng tại các phòng ban của mình tại Plumsted Aynes.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Susan Tsai would like to invite Marco Garcia and Danielle Jenkins to return for second interviews for the accounting position, and Rajesh Kapoor wants to invite Melanie Yu for a second interview for the medical sales position.\", \"vi\": \"Bà Susan Tsai xin mời ông Marco Garcia và bà Danielle Jenkins quay lại tham dự vòng phỏng vấn thứ hai cho vị trí kế toán, còn ông Rajesh Kapoor muốn mời bà Melanie Yu tham dự vòng phỏng vấn thứ hai cho vị trí nhân viên kinh doanh dược phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I would like you to call the finalists, schedule interviews with them, and then make lunch arrangements accordingly.\", \"vi\": \"Tôi mong quý vị vui lòng liên hệ với các ứng viên lọt vào vòng chung kết, sắp xếp lịch phỏng vấn với họ, và sau đó chuẩn bị bữa trưa phù hợp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Keep in mind that Susan will be out of the office next week for a conference.\", \"vi\": \"Xin lưu ý rằng tuần tới, Susan sẽ vắng mặt tại văn phòng để tham dự một hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Thank you for your assistance with this search so far.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã hỗ trợ cho công việc tìm kiếm này cho đến nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I\'m especially grateful that you were able to work on a short deadline when I asked you to set up the initial interviews.\", \"vi\": \"Tôi đặc biệt cảm kích vì quý vị đã có thể hoàn thành công việc trong thời hạn rất gấp khi tôi nhờ quý vị sắp xếp các cuộc phỏng vấn ban đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Nigella Smith\", \"vi\": \"Nigella Smith\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Human Resources Director\", \"vi\": \"Giám đốc Nhân sự\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To: Nigella Smith\", \"vi\": \"Kính gửi: Bà Nigella Smith\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From: Dennis Maki\", \"vi\": \"Từ: Dennis Maki\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Date: Thursday, November 8, 3:52 P.M.\", \"vi\": \"Ngày: Thứ Năm, ngày 8 tháng 11, 3 giờ 52 phút chiều\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Subject: RE: Update\", \"vi\": \"Chủ đề: RE: Thông tin cập nhật\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Nigella:\", \"vi\": \"Nigella:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I called the three finalists.\", \"vi\": \"Tôi đã gọi điện cho ba ứng viên lọt vào vòng chung kết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"As it turns out, this afternoon Melanie Yu accepted a job offer with another pharmaceutical firm—our competitor Granquist.\", \"vi\": \"Hóa ra, chiều nay, Melanie Yu đã chấp nhận lời mời làm việc từ một công ty dược phẩm khác — đó chính là Granquist, đối thủ cạnh tranh của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I informed Rajesh about this development and he said he hopes to find a suitable replacement.\", \"vi\": \"Tôi đã thông báo cho Rajesh về diễn biến này và anh ấy cho biết hy vọng sẽ tìm được người thay thế phù hợp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I have confirmed an interview for Mr. Garcia on Tuesday, November 20.\", \"vi\": \"Tôi đã xác nhận lịch phỏng vấn cho ông Garcia vào thứ Ba, ngày 20 tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I also made arrangements with our regular catering company for lunch here.\", \"vi\": \"Tôi cũng đã liên hệ với công ty cung cấp dịch vụ ăn uống thường xuyên của chúng tôi để chuẩn bị bữa trưa tại đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Unfortunately, Ms. Jenkins was recently hospitalized, so I\'m leaving any further decision about her interview with you.\", \"vi\": \"Rất tiếc, bà Jenkins vừa phải nhập viện, vì vậy tôi xin để quý vị tự quyết định về việc phỏng vấn bà ấy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Dennis Maki\", \"vi\": \"Dennis Maki\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Administrative Associate\", \"vi\": \"Chuyên viên Hành chính\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '4e042fb9-d225-4ea2-a6ef-393b096a6598';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Roger Wall <rogerwall@openemail.com>\", \"vi\": \"Đến: Roger Wall <rogerwall@openemail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Guillermo Torres <gtorres@supplyflow.com>\", \"vi\": \"Từ: Guillermo Torres <gtorres@supplyflow.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 2\", \"vi\": \"Ngày: 2 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: RE: Missing delivery\", \"vi\": \"Chủ đề: V/v: Giao hàng bị thiếu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Wall,\", \"vi\": \"Kính gửi ông Wall,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This is in response to your ___131___ e-mail notifying us that you did not receive your April shipment of office supplies.\", \"vi\": \"Thư này phản hồi lại email ___131___ của ông thông báo rằng ông chưa nhận được lô hàng văn phòng phẩm tháng Tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [131]}, {\"en\": \"We verified that your annual subscription is up-to-date and that everything is in order on your side.\", \"vi\": \"Chúng tôi đã xác minh rằng gói đăng ký hàng năm của ông vẫn còn hiệu lực và mọi thứ đều ổn thỏa ở phía ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This error is, therefore, an oversight on ___132___ part.\", \"vi\": \"Do đó, lỗi này là sự sơ suất từ phía ___132___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [132]}, {\"en\": \"We have transitioned to new shipping software, and some customer information was not transferred correctly.\", \"vi\": \"Chúng tôi đã chuyển đổi sang phần mềm vận chuyển mới, và một số thông tin khách hàng đã không được chuyển sang chính xác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Rest assured that this has been fixed and that the error will not ___133___ again.\", \"vi\": \"Hãy yên tâm rằng điều này đã được khắc phục và lỗi đó sẽ không ___133___ lần nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [133]}, {\"en\": \"We sent your box of office supplies today using an overnight shipping service.\", \"vi\": \"Chúng tôi đã gửi hộp văn phòng phẩm của ông vào hôm nay bằng dịch vụ chuyển phát nhanh qua đêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"___134___ .\", \"vi\": \"___134___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [134]}, {\"en\": \"Inside the box, you will also find a complimentary token of appreciation for your patience.\", \"vi\": \"Bên trong hộp, ông cũng sẽ tìm thấy một món quà nhỏ thay lời cảm ơn vì sự kiên nhẫn của ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"If you have further questions or concerns, do not hesitate to contact me directly.\", \"vi\": \"Nếu ông có thêm câu hỏi hoặc thắc mắc nào, xin đừng ngần ngại liên hệ trực tiếp với tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Guillermo Torres, Customer Assistant, Supply Flow, Inc.\", \"vi\": \"Guillermo Torres, Trợ lý Khách hàng, Công ty Supply Flow\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '4e083b84-777c-48ee-b2d2-73840140102d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"For months, Yi Zhang, owner of Zhang Office Supplies, had been searching for a way to increase ______[139].\", \"vi\": \"Trong nhiều tháng, Yi Zhang, chủ của cửa hàng Văn phòng phẩm Zhang, đã tìm kiếm một cách để gia tăng ______[139].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [139]}, {\"en\": \"Then, by sheer chance, he heard about an approach called Voice of the Customer (VOC).\", \"vi\": \"Sau đó, một cách hoàn toàn tình cờ, anh ấy đã nghe về một phương pháp có tên là Tiếng nói Khách hàng (VOC).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"\\\"When I called Hsing Market Research I was really intrigued as the method was presented to me.\", \"vi\": \"\\\"Khi tôi gọi cho Công ty Nghiên cứu Thị trường Hsing, tôi thực sự bị cuốn hút bởi cách phương pháp này được giới thiệu với tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The representative I spoke with convinced me to give ______[140] a try.\\\"\", \"vi\": \"Đại diện mà tôi đã nói chuyện cùng đã thuyết phục tôi dùng thử ______[140].\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [140]}, {\"en\": \"Mr. Zhang learned that VOC uses market research as an aid to designing targeted advertisements.\", \"vi\": \"Ông Zhang đã biết được rằng VOC sử dụng nghiên cứu thị trường như một công cụ hỗ trợ để thiết kế các quảng cáo có mục tiêu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Using the method, he first determined ______[141] what potential customers are concerned about and what they want when shopping for office supplies.\", \"vi\": \"Sử dụng phương pháp này, đầu tiên ông xác định ______[141] những gì khách hàng tiềm năng quan tâm và những gì họ muốn khi mua sắm các thiết bị văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [141]}, {\"en\": \"Then he used candid quotes from the people who participated in his market research to create advertisements for his Web site.\", \"vi\": \"Sau đó, ông đã sử dụng những câu nói chân thực từ những người tham gia nghiên cứu thị trường của mình để tạo quảng cáo cho trang web của ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"______[142].\", \"vi\": \"______[142].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [142]}, {\"en\": \"\\\"Thanks to VOC,\\\" he says, smiling, \\\"my customer base has expanded like never before.\\\"\", \"vi\": \"\\\"Nhờ có VOC,\\\" ông nói và mỉm cười, \\\"tệp khách hàng của tôi đã mở rộng chưa từng có.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '4e32fa62-fa5c-40af-90d4-8c521b9abfb3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Venley Foods Responsive to Changing Consumers\", \"vi\": \"Venley Foods đáp ứng nhu cầu thay đổi của người tiêu dùng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Who cares where the tomatoes in your salad actually came from?\", \"vi\": \"Ai lại quan tâm những quả cà chua trong đĩa salad của bạn thực sự đến từ đâu chứ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"______[139], an increasing number of people do, according to a study conducted by the Consumer Group.\", \"vi\": \"______[139], ngày càng có nhiều người quan tâm đến điều đó, theo một nghiên cứu được thực hiện bởi Nhóm Người tiêu dùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [139]}, {\"en\": \"In fact, the study shows that many consumers would pay an average of 10 percent more when given the exact source of a fresh food product.\", \"vi\": \"Trên thực tế, nghiên cứu cho thấy rằng nhiều người tiêu dùng sẵn sàng trả trung bình nhiều hơn 10 phần trăm khi được cung cấp nguồn gốc chính xác của một sản phẩm thực phẩm tươi sống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"______[140].\", \"vi\": \"______[140].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [140]}, {\"en\": \"Some grocery stores, such as Venley Foods in Boston, have taken advantage of the trend and used it to implement ______[141] branding and marketing.\", \"vi\": \"Một số cửa hàng tạp hóa, chẳng hạn như Venley Foods ở Boston, đã tận dụng xu hướng này và sử dụng nó để thực hiện hoạt động xây dựng thương hiệu và tiếp thị ______[141].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [141]}, {\"en\": \"\\\"If we can tell a story about our product,\\\" says Venley Foods CEO Minji Kim, \\\"then we\'ve added ______[142] in the minds of consumers.\\\"\", \"vi\": \"\\\"Nếu chúng tôi có thể kể một câu chuyện về sản phẩm của mình,\\\" Giám đốc điều hành Venley Foods Minji Kim cho biết, \\\"thì chúng tôi đã gia tăng ______[142] trong tâm trí người tiêu dùng.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [142]}]' WHERE `id` = '4e504852-6e33-4bba-a72d-eb8a7bdef07b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Sales Lunch Workshop\", \"vi\": \"Hội thảo kết hợp bữa trưa dành cho nhân viên kinh doanh\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Attention sales associates!\", \"vi\": \"Kính gửi các nhân viên bán hàng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Are you new to CMG Direct Retail?\", \"vi\": \"Quý vị có phải là khách hàng mới của CMG Direct Retail không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Is your sales sheet looking a little short?\", \"vi\": \"Bảng doanh số của quý vị có vẻ hơi khiêm tốn phải không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Do you want to increase your commissions but can\'t seem to find new clients?\", \"vi\": \"Quý vị có muốn tăng hoa hồng của mình nhưng dường như không thể tìm được khách hàng mới không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Come to this month\'s lunch workshop, where Senior Sales Manager Chad Avakian will share his secrets for locating, securing, and expanding new accounts!\", \"vi\": \"Hãy tham dự buổi hội thảo kết hợp bữa trưa trong tháng này, nơi Giám đốc Kinh doanh Cấp cao Chad Avakian sẽ chia sẻ những bí quyết của mình trong việc tìm kiếm, ký kết và mở rộng các khách hàng mới!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Lunch is not provided, so be sure to pack something for yourself.\", \"vi\": \"Bữa trưa không được cung cấp, vì vậy xin quý vị nhớ chuẩn bị đồ ăn trưa cho riêng mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"After the meeting, a digital recording of the full presentation will be made available on the company\'s training Web site, so there\'s no need to bring a laptop for notes.\", \"vi\": \"Sau buổi họp, bản ghi hình kỹ thuật số toàn bộ buổi thuyết trình sẽ được đăng tải trên trang web đào tạo của công ty, do đó quý vị không cần phải mang theo máy tính xách tay để ghi chép.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please RSVP to the training department at events@cmgdr.com to reserve your space.\", \"vi\": \"Kính mong quý vị vui lòng xác nhận tham dự với bộ phận đào tạo qua địa chỉ email events@cmgdr.com để đăng ký chỗ ngồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '4e5748fe-226b-4994-946a-f07b78ab2551';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"For a limited time, the Uppercut Clothing Hanger Company is selling its highest quality hangers at huge discounts on wholesale orders.\", \"vi\": \"Trong thời gian có hạn, Công ty Móc treo Quần áo Uppercut đang bán các loại móc treo chất lượng cao nhất với mức giảm giá lớn cho các đơn hàng sỉ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"This special ______[139] is perfect for hotels, retailers, or anywhere hangers are used extensively.\", \"vi\": \"Ưu đãi đặc biệt ______[139] này rất hoàn hảo cho các khách sạn, nhà bán lẻ, hoặc bất kỳ nơi nào sử dụng móc treo với số lượng lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [139]}, {\"en\": \"______[140] of lacquered walnut wood, these hangers are not only durable, but also safe for the environment.\", \"vi\": \"______[140] được làm từ gỗ óc chó đánh véc-ni, những chiếc móc treo này không chỉ bền mà còn thân thiện với môi trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [140]}, {\"en\": \"______[141] are strong enough to hold up to ten pounds.\", \"vi\": \"______[141] đủ chắc chắn để chịu được trọng lượng lên đến mười pa-ao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [141]}, {\"en\": \"To order, visit www.uppercuthangerco.ca.\", \"vi\": \"Để đặt hàng, hãy truy cập www.uppercuthangerco.ca.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Note that all orders require a 20 percent deposit.\", \"vi\": \"Lưu ý rằng tất cả các đơn hàng đều yêu cầu đặt cọc 20 phần trăm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[142].\", \"vi\": \"______[142].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [142]}, {\"en\": \"Uppercut will cover all shipping and insurance costs.\", \"vi\": \"Uppercut sẽ đài thọ mọi chi phí vận chuyển và bảo hiểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '4e5dd591-c686-45fd-9ed2-2c9b4cdca66e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Deftlee\", \"vi\": \"Deftlee\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"More than a decade of helping start-ups take flight\", \"vi\": \"Hơn một thập kỷ đồng hành cùng các công ty khởi nghiệp trên hành trình vươn lên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"What we offer:\", \"vi\": \"Những gì chúng tôi cung cấp:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Convenient outsourcing of human resources tasks\", \"vi\": \"Việc thuê ngoài các công việc liên quan đến nguồn nhân lực một cách thuận tiện\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Project-based consulting on personnel issues\", \"vi\": \"Dịch vụ tư vấn theo dự án về các vấn đề nhân sự\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Full-service HR technology platform for long-term clients\", \"vi\": \"Nền tảng công nghệ nhân sự toàn diện dành cho các khách hàng lâu năm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Areas of expertise include recruiting, training, payroll, and much more.\", \"vi\": \"Các lĩnh vực chuyên môn bao gồm tuyển dụng, đào tạo, quản lý tiền lương và nhiều lĩnh vực khác nữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Visit www.deftlee.com to schedule a consultation.\", \"vi\": \"Vui lòng truy cập www.deftlee.com để đặt lịch tư vấn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Client testimonials:\", \"vi\": \"Lời chia sẻ từ khách hàng:\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"“I highly recommend Deftlee.\", \"vi\": \"“Tôi xin nhiệt liệt giới thiệu Deftlee.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Their HR platform alone is worth the prices they charge.\", \"vi\": \"Chỉ riêng nền tảng quản lý nhân sự của họ đã xứng đáng với mức giá mà họ đưa ra.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Our managers love how it has simplified tasks like tracking time off and performance evaluations.”\", \"vi\": \"“Các nhà quản lý của chúng tôi rất hài lòng vì hệ thống này đã giúp đơn giản hóa các công việc như theo dõi thời gian nghỉ phép và đánh giá hiệu suất làm việc.”\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"—Ryan Maas, Aurora Logistics\", \"vi\": \"—Ryan Maas, Aurora Logistics\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"“My business has grown from four employees to more than 50, and Deftlee has been there every step of the way.\", \"vi\": \"“Doanh nghiệp của tôi đã phát triển từ bốn nhân viên lên hơn 50 người, và Deftlee luôn đồng hành cùng chúng tôi trong từng chặng đường.”\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I’m always impressed by their ability to adapt to our changing needs.”\", \"vi\": \"“Tôi luôn ấn tượng trước khả năng thích ứng của họ với những nhu cầu luôn thay đổi của chúng tôi.”\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"—Kasumi Tanaka, TBR Solutions\", \"vi\": \"—Kasumi Tanaka, TBR Solutions\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '4e914e4b-6d01-464a-ae46-0544b404e771';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.trehospitalityassociation.com/discussion/tunisia\", \"vi\": \"https://www.trehospitalityassociation.com/discussion/tunisia\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I have been a member of the TRE Hospitality Association for many years, but until now, I have posted messages only on the Greece and Egypt forums.\", \"vi\": \"Tôi đã là thành viên của Hiệp hội Du lịch và Khách sạn TRE trong nhiều năm qua, nhưng cho đến nay, tôi mới chỉ đăng bài trên các diễn đàn về Hy Lạp và Ai Cập.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"This is my first post on the Tunisia forum.\", \"vi\": \"Đây là bài đăng đầu tiên của tôi trên diễn đàn Tunisia.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I am looking for recommendations for a janitorial service on the island of Djerba.\", \"vi\": \"Tôi đang tìm kiếm các gợi ý về dịch vụ vệ sinh trên đảo Djerba.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"My company is opening a hotel there.\", \"vi\": \"Công ty của tôi đang mở một khách sạn tại đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our hotel will offer 80 rooms with two restaurants on-site.\", \"vi\": \"Khách sạn của chúng tôi sẽ có 80 phòng cùng hai nhà hàng ngay trong khuôn viên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I would like to contract with a company that can provide about four full-time custodial workers and housekeepers, plus an additional five workers on an as-needed basis for large events on our property.\", \"vi\": \"Tôi mong muốn ký hợp đồng với một công ty có thể cung cấp khoảng bốn nhân viên bảo vệ và nhân viên dọn dẹp làm việc toàn thời gian, cùng với năm nhân viên bổ sung theo nhu cầu để phục vụ các sự kiện quy mô lớn diễn ra tại khuôn viên của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I may have met some of you previously at one of our hospitality conferences.\", \"vi\": \"Có thể trước đây tôi đã từng gặp một số quý vị tại một trong những hội nghị về ngành khách sạn của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"If so, please remind me.\", \"vi\": \"Nếu vậy, xin vui lòng nhắc nhở tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"In fact, I attended the most recent one in Rabat.\", \"vi\": \"Thực tế, tôi đã tham dự sự kiện gần đây nhất được tổ chức tại Rabat.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I would like to reconnect!\", \"vi\": \"Tôi rất mong được kết nối lại!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"John Karikas, Director of Development\", \"vi\": \"Ông John Karikas, Giám đốc Phát triển\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Synecdoche Hotel Group\", \"vi\": \"Tập đoàn Khách sạn Synecdoche\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '4e961b2f-20d2-498c-9bf2-1cf95b52c9ce';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"How to Pitch Your Start-up to a Potential Investor\", \"vi\": \"Cách Thuyết Trình Dự Án Khởi Nghiệp Của Bạn Cho Nhà Đầu Tư Tiềm Năng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"When planning a presentation for potential investors, do not keep them in suspense.\", \"vi\": \"Khi lên kế hoạch thuyết trình cho các nhà đầu tư tiềm năng, đừng giữ họ trong tình trạng hồi hộp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"------- (139).\", \"vi\": \"------- (139).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [139]}, {\"en\": \"This has the added benefit of grabbing investors\' attention.\", \"vi\": \"Điều này có thêm lợi ích là thu hút sự chú ý của các nhà đầu tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Your company\'s young, dynamic team may be its greatest asset.\", \"vi\": \"Đội ngũ trẻ trung và năng động của công ty bạn có thể là tài sản lớn nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"On the other hand, if your team has years of valuable experience together and this is ------- (140) to the product or service you offer, mention that early as well.\", \"vi\": \"Mặt khác, nếu đội ngũ của bạn có nhiều năm kinh nghiệm quý báu làm việc cùng nhau và điều này ------- (140) với sản phẩm hoặc dịch vụ bạn cung cấp, hãy đề cập đến điều đó từ sớm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [140]}, {\"en\": \"Finally, if ------- (141) sets your company apart is its unique vision, make it your leading statement.\", \"vi\": \"Cuối cùng, nếu ------- (141) làm cho công ty bạn nổi bật chính là tầm nhìn độc đáo của nó, hãy biến điều đó thành tuyên bố chủ đạo của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [141]}, {\"en\": \"If you can convince your audience that your company\'s product or service is destined for success, you will likely acquire the ------- (142) you seek.\", \"vi\": \"Nếu bạn có thể thuyết phục khán giả rằng sản phẩm hoặc dịch vụ của công ty bạn chắc chắn sẽ thành công, bạn rất có thể sẽ nhận được ------- (142) mà bạn tìm kiếm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [142]}]' WHERE `id` = '4ebd1f5a-b55c-4faa-a1da-04eb4cf31e7e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"FOR IMMEDIATE RELEASE\", \"vi\": \"THÔNG CÁO BÁO CHÍ NGAY LẬP TỨC\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Contact: Roberto Barboza\", \"vi\": \"Liên hệ: Roberto Barboza\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"351 922 555 965\", \"vi\": \"351 922 555 965\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"LISBON (18 June)—This year’s International Candy Conference will be held in Lisbon, Portugal, at the Vil de Maitros Convention Center near the Bibb Bubblegum factory.\", \"vi\": \"LISBON (ngày 18 tháng 6) — Hội nghị Quốc tế về Kẹo năm nay sẽ được tổ chức tại Lisbon, Bồ Đào Nha, tại Trung tâm Hội nghị Vil de Maitros, gần nhà máy kẹo cao su Bibb.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Thousands of candy industry specialists from around the world are expected to attend the event on 8–10 September.\", \"vi\": \"Dự kiến sẽ có hàng nghìn chuyên gia trong ngành kẹo từ khắp nơi trên thế giới tham dự sự kiện này vào các ngày 8–10 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Amanda Bibb, CEO of Bibb Bubblegum, takes the chewing gum industry very seriously.\", \"vi\": \"Bà Amanda Bibb, Giám đốc điều hành của Bibb Bubblegum, rất coi trọng ngành công nghiệp kẹo cao su.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As the company’s fourth-generation CEO, she proudly shares, “My family is excited to sponsor this event and thrilled to be the first chewing gum company ever to host the International Candy Conference!”\", \"vi\": \"Với tư cách là Giám đốc điều hành thế hệ thứ tư của công ty, bà tự hào chia sẻ: “Gia đình tôi rất hào hứng khi được tài trợ cho sự kiện này và vô cùng vinh dự khi trở thành công ty sản xuất kẹo cao su đầu tiên trong lịch sử tổ chức Hội nghị Quốc tế về Kẹo!”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Ms. Bibb is also especially pleased that the candy conference will be in Portugal this year.\", \"vi\": \"Bà Bibb cũng đặc biệt vui mừng vì hội nghị về kẹo năm nay sẽ được tổ chức tại Bồ Đào Nha.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"“Bibb Bubblegum started with a tiny shop near Lisbon.\", \"vi\": \"“Bibb Bubblegum khởi đầu từ một cửa hàng nhỏ xíu gần Lisbon.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"While our main factory is local, we now sell our gum in seven countries.\", \"vi\": \"Mặc dù nhà máy chính của chúng tôi nằm tại địa phương, nhưng hiện nay chúng tôi đã phân phối kẹo cao su của mình tại bảy quốc gia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We hope this event will bring attention and revenue to our community as well as to the international bubblegum market.”\", \"vi\": \"Chúng tôi hy vọng sự kiện này sẽ thu hút sự chú ý và mang lại nguồn thu cho cộng đồng của chúng tôi cũng như cho thị trường kẹo cao su quốc tế.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"For more information about the International Candy Conference and for tours of the Bibb Bubblegum factory, contact Roberto Barboza at 351 922 555 965 or visit www.BibbBubblegum.com.\", \"vi\": \"Để biết thêm thông tin về Hội nghị Kẹo Quốc tế cũng như các tour tham quan nhà máy kẹo cao su Bibb Bubblegum, quý vị vui lòng liên hệ với ông Roberto Barboza theo số điện thoại 351 922 555 965 hoặc truy cập trang web www.BibbBubblegum.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '4f184358-b180-4443-abae-fca8e2269cee';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"About Leafi Cloth\", \"vi\": \"Giới thiệu về Vải Leafi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Tropick Textiles recently expanded the ___143___ of fabrics available on the market.\", \"vi\": \"Tropick Textiles gần đây đã mở rộng ___143___ các loại vải có sẵn trên thị trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [143]}, {\"en\": \"In its quest to introduce environmentally friendly alternatives to cotton and other traditional fibers, the company ___144___ a new fiber made from materials that are typically discarded.\", \"vi\": \"Trong nỗ lực giới thiệu các giải pháp thay thế thân thiện với môi trường cho bông và các loại sợi truyền thống khác, công ty đã ___144___ một loại sợi mới làm từ các vật liệu thường bị vứt bỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [144]}, {\"en\": \"Tropick Textiles takes banana and pineapple leaves and combines them with bamboo fibers to create Leafi Cloth.\", \"vi\": \"Tropick Textiles lấy lá cây chuối và lá dứa, kết hợp chúng với sợi tre để tạo ra Vải Leafi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The plants\' leaves are ordinarily disposed of ___145___ the fruit is harvested.\", \"vi\": \"Lá của các loại cây này thông thường bị vứt đi ___145___ trái cây được thu hoạch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [145]}, {\"en\": \"Tropick Textiles\' process prevents many leaves from entering a landfill, converting them instead into usable material.\", \"vi\": \"Quy trình của Tropick Textiles ngăn chặn nhiều chiếc lá đi vào bãi rác, thay vào đó chuyển đổi chúng thành vật liệu có thể sử dụng được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"___146___.\", \"vi\": \"___146___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [146]}]' WHERE `id` = '4f3895b2-0f67-4a03-8540-15f32e986d38';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Michael Kaelo <mkaelo@hawthorneclinic.bw>\", \"vi\": \"Gửi tới: Michael Kaelo <mkaelo@hawthorneclinic.bw>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Sophie Thabado <sthabado@gaboronestar.bw>\", \"vi\": \"Từ: Sophie Thabado <sthabado@gaboronestar.bw>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 20 February\", \"vi\": \"Ngày: 20 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: RE: Event\", \"vi\": \"Chủ đề: RE: Sự kiện\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Dinner and lunch menu options\", \"vi\": \"Tài liệu đính kèm: Các lựa chọn thực đơn bữa tối và bữa trưa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Kaelo,\", \"vi\": \"Kính gửi ông Kaelo,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for considering the Gaborone Star Hotel for your event.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã cân nhắc lựa chọn Khách sạn Gaborone Star để tổ chức sự kiện của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Regarding your question about ballrooms that accommodate large groups, we have four: Jupiter, Saturn, Neptune, and Venus.\", \"vi\": \"Về câu hỏi của quý vị liên quan đến các sảnh tiệc có thể phục vụ các nhóm khách đông người, chúng tôi có bốn sảnh: Jupiter, Saturn, Neptune và Venus.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"They seat 400, 300, 200, and 100 guests respectively.\", \"vi\": \"Các phòng này lần lượt có sức chứa 400, 300, 200 và 100 khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I\'ve attached some lunch and dinner menu options, but we are happy to work with you regarding specific requests.\", \"vi\": \"Tôi đã đính kèm một số lựa chọn thực đơn cho bữa trưa và bữa tối, nhưng chúng tôi rất sẵn lòng phối hợp với quý vị để đáp ứng các yêu cầu cụ thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We can arrange a sit-down meal or buffet-style service.\", \"vi\": \"Chúng tôi có thể sắp xếp bữa ăn ngồi tại bàn hoặc phục vụ theo hình thức tiệc tự chọn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We also provide audiovisual equipment for business presentations or celebrations.\", \"vi\": \"Chúng tôi cũng cung cấp thiết bị nghe nhìn phục vụ cho các buổi thuyết trình kinh doanh hoặc các sự kiện lễ kỷ niệm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Please let me know if you need any additional information.\", \"vi\": \"Nếu quý vị cần thêm thông tin nào, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sophie Thabado, Director of Events\", \"vi\": \"Bà Sophie Thabado, Giám đốc phụ trách các sự kiện\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Gaborone Times\", \"vi\": \"Báo Gaborone Times\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"20 May\", \"vi\": \"ngày 20 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Local Happenings\", \"vi\": \"Các sự kiện tại địa phương\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"On 15 May, family members, friends, and colleagues of Dr. Patrick Matambo gathered at the Gaborone Star Hotel to celebrate his retirement, which will take effect on 1 June.\", \"vi\": \"Vào ngày 15 tháng 5, các thành viên gia đình, bạn bè và đồng nghiệp của Tiến sĩ Patrick Matambo đã tụ họp tại Khách sạn Gaborone Star để tổ chức lễ kỷ niệm ngày ông nghỉ hưu, dự kiến có hiệu lực từ ngày 1 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"For twenty years, Dr. Matambo has been the director of the Hawthorne Clinic, located near Hawthorne City University.\", \"vi\": \"Trong suốt hai mươi năm qua, Tiến sĩ Matambo đã đảm nhiệm chức vụ Giám đốc Phòng khám Hawthorne, tọa lạc gần Đại học Thành phố Hawthorne.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Among the nearly 180 well-wishers in attendance were also some former patients who attested to the honoree\'s kindness and professionalism.\", \"vi\": \"Trong số gần 180 vị khách đến chúc mừng có cả một số cựu bệnh nhân, những người đã chia sẻ về lòng tốt và sự chuyên nghiệp của nhân vật được vinh danh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Dr. Matambo has also been a familiar face at local charity events, and in particular, he has helped to raise money for many area schools.\", \"vi\": \"Bác sĩ Matambo cũng là một gương mặt quen thuộc tại các sự kiện từ thiện địa phương, và đặc biệt, ông đã góp phần gây quỹ cho nhiều trường học trong khu vực.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"His immediate plans are to take a month-long vacation on a cruise ship with his wife, Alicia Matambo.\", \"vi\": \"Kế hoạch trước mắt của ông là đi nghỉ mát trong một tháng trên du thuyền cùng vợ, bà Alicia Matambo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Although Dr. Matambo is retiring, he will remain involved with the clinic as a consultant.\", \"vi\": \"Mặc dù Bác sĩ Matambo sắp nghỉ hưu, ông vẫn sẽ tiếp tục tham gia hoạt động tại phòng khám với tư cách là chuyên gia tư vấn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"A new director has been approved by the Hawthorne Clinic\'s board of trustees and is expected to be announced later this week.\", \"vi\": \"Một giám đốc mới đã được Hội đồng quản trị của Phòng khám Hawthorne thông qua và dự kiến sẽ được công bố vào cuối tuần này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '4f3b4efa-151b-4558-acd3-6e55446218a8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Broome Library Staff\", \"vi\": \"Đến: Nhân viên Thư viện Broome\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Ainsley Mason\", \"vi\": \"Từ: Ainsley Mason\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Re: Community Rooms\", \"vi\": \"Chủ đề: Các phòng cộng đồng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: April 20\", \"vi\": \"Ngày: 20 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I am pleased to report that construction of our new community rooms will be complete by the end of this month.\", \"vi\": \"Tôi rất vui mừng thông báo rằng việc xây dựng các phòng cộng đồng mới của chúng ta sẽ hoàn thành vào cuối tháng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The four rooms will be ______[139] from the main lobby.\", \"vi\": \"Bốn phòng này sẽ nằm ______[139] sảnh chính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [139]}, {\"en\": \"The new rooms range in occupancy from 10 to 25 people and are intended for meetings and study groups.\", \"vi\": \"Các phòng mới có sức chứa từ 10 đến 25 người và dành cho các cuộc họp cũng như nhóm học tập.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"______[140].\", \"vi\": \"______[140].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [140]}, {\"en\": \"Ms. Sundquist will be temporarily responsible for reserving the spaces until the end of March.\", \"vi\": \"Cô Sundquist sẽ tạm thời chịu trách nhiệm đặt chỗ cho các không gian này cho đến hết tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"______[141], she will return to her role as Library Information Specialist.\", \"vi\": \"______[141], cô ấy sẽ trở lại vai trò Chuyên viên Thông tin Thư viện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [141]}, {\"en\": \"An advertisement will be posted soon for a permanent Community Liaison.\", \"vi\": \"Một thông báo tuyển dụng sẽ sớm được đăng tải để tìm kiếm Nhân viên Liên lạc Cộng đồng làm việc lâu dài.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"This individual will be in charge of ______[142] bookings for the new rooms.\", \"vi\": \"Cá nhân này sẽ phụ trách việc ______[142] đặt phòng cho các phòng mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [142]}]' WHERE `id` = '4f45ec54-01a0-46be-ba7e-6cfdd705f4cd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MEMO\", \"vi\": \"BẢN GHI NHỚ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear Staff,\", \"vi\": \"Kính gửi quý đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The holiday season is approaching!\", \"vi\": \"Mùa lễ hội đang đến gần!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"To get into the spirit and hopefully boost sales, I want to offer a temporary menu of holiday-themed drinks to Coffee Max customers.\", \"vi\": \"Để hòa mình vào không khí lễ hội và hy vọng sẽ thúc đẩy doanh số, tôi muốn giới thiệu đến quý khách hàng của Coffee Max một thực đơn đồ uống theo chủ đề lễ hội có thời hạn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Please help with this project by using the café’s slow periods to try to come up with a delicious and unique coffee drink.\", \"vi\": \"Kính mong quý vị hỗ trợ dự án này bằng cách tận dụng những khoảng thời gian vắng khách tại quán cà phê để sáng tạo ra một thức uống cà phê ngon miệng và độc đáo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"If you succeed, send me an e-mail outlining the ingredients and how to make it.\", \"vi\": \"Nếu quý vị làm được, xin vui lòng gửi cho tôi một email nêu rõ các nguyên liệu và cách chế biến món ăn đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I will choose three drinks for our special menu.\", \"vi\": \"Tôi sẽ chọn ba loại đồ uống cho thực đơn đặc biệt của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If yours is chosen, you will receive a $50 gift certificate to Eva Department Store, so you can shop right across the street before or after work.\", \"vi\": \"Nếu bài dự thi của quý vị được chọn, quý vị sẽ nhận được một phiếu quà tặng trị giá 50 đô la tại Cửa hàng Bách hóa Eva, để quý vị có thể ghé mua sắm ngay bên kia đường trước hoặc sau giờ làm việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The deadline for submissions is the end of the day on Sunday, October 30, and there are a few extra considerations to keep in mind.\", \"vi\": \"Hạn chót nộp bài là hết ngày Chủ nhật, ngày 30 tháng 10, và có một số điểm cần lưu ý thêm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The drinks should not use too many costly ingredients, and if there are any ingredients that might be dangerous for customers with food allergies, include suggestions for substitutions.\", \"vi\": \"Các loại đồ uống không nên sử dụng quá nhiều nguyên liệu đắt tiền; đồng thời, nếu có bất kỳ nguyên liệu nào có thể gây nguy hiểm cho khách hàng bị dị ứng thực phẩm, xin vui lòng đưa ra các đề xuất về nguyên liệu thay thế.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"In addition, our staff must be able to make each drink quickly.\", \"vi\": \"Bên cạnh đó, đội ngũ nhân viên của chúng tôi phải có khả năng pha chế từng ly đồ uống một cách nhanh chóng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Thank you!\", \"vi\": \"Xin cảm ơn!\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Adriana\", \"vi\": \"Adriana\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '4f4aed29-f9d1-4126-948f-aae6455648ec';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"May 15\", \"vi\": \"Ngày 15 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Mr. Roger Lang, Executive Director\", \"vi\": \"Ông Roger Lang, Giám đốc Điều hành\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Parker Solutions Foundation\", \"vi\": \"Quỹ Parker Solutions\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"40 Northside Drive, Suite 500\", \"vi\": \"40 Northside Drive, Phòng 500\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Portland, OR 97215\", \"vi\": \"Portland, OR 97215\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Lang:\", \"vi\": \"Kính gửi ông Lang:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The purpose of this letter is to invite you, on behalf of the board of directors, to be the keynote speaker at the International Green Solutions Research Institute (IGSRI) Conference.\", \"vi\": \"Mục đích của bức thư này là thay mặt Hội đồng quản trị, kính mời quý vị đảm nhận vai trò diễn giả chính tại Hội nghị của Viện Nghiên cứu Giải pháp Xanh Quốc tế (IGSRI).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"It will be held at the Fairview Conference Center in Saint Louis, Missouri, from December 3 to 5.\", \"vi\": \"Sự kiện này sẽ diễn ra tại Trung tâm Hội nghị Fairview ở Saint Louis, Missouri, từ ngày 3 đến ngày 5 tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You were recommended by a number of my colleagues.\", \"vi\": \"Quý vị đã được một số đồng nghiệp của tôi giới thiệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Professor Suzanne Benedetto will deliver the opening speech on the morning of December 3.\", \"vi\": \"Giáo sư Suzanne Benedetto sẽ phát biểu khai mạc vào sáng ngày 3 tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"A draft program will be sent to you in two weeks to give you an idea of the topics that will be highlighted at the conference.\", \"vi\": \"Bản dự thảo chương trình sẽ được gửi đến quý vị trong hai tuần tới để quý vị có thể hình dung về các chủ đề sẽ được đề cập tại hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We expect attendance this year to be the highest ever, around 2,500 delegates and 40 speakers.\", \"vi\": \"Chúng tôi dự kiến số lượng người tham dự năm nay sẽ đạt mức cao nhất từ trước đến nay, với khoảng 2.500 đại biểu và 40 diễn giả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"This includes a large contingent from our newest chapter in Geneva.\", \"vi\": \"Trong số này có một đoàn đại biểu đông đảo đến từ chi hội mới nhất của chúng tôi tại Geneva.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I hope to contact you in a week to follow up and answer any questions you may have.\", \"vi\": \"Tôi hy vọng sẽ liên hệ lại với quý vị trong một tuần nữa để cập nhật thông tin và giải đáp bất kỳ thắc mắc nào của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Yours sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Brian Morgan\", \"vi\": \"Brian Morgan\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Brian Morgan\", \"vi\": \"Brian Morgan\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '50072207-8ed5-4ba8-b81c-d3e27b8c65d0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Now that spring has arrived, many people are giving their houses or apartments a deep cleaning.\", \"vi\": \"Nhân dịp mùa xuân đã đến, nhiều người đang tiến hành dọn dẹp kỹ lưỡng ngôi nhà hoặc căn hộ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"But what if you don\'t have time to get rid of winter dust and grime yourself?\", \"vi\": \"Nhưng nếu quý vị không có thời gian để tự tay dọn dẹp bụi bẩn và cặn bám tích tụ suốt mùa đông thì sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Aspire Cleaners\' dedicated staff will scrub every corner of your home from floor to ceiling—or, just the areas you ask us to handle.\", \"vi\": \"Đội ngũ nhân viên tận tâm của Aspire Cleaners sẽ chà rửa từng ngóc ngách trong ngôi nhà của quý khách, từ sàn nhà đến trần nhà — hoặc chỉ những khu vực mà quý khách yêu cầu chúng tôi xử lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Call us at 555-0164 today.\", \"vi\": \"Hãy gọi cho chúng tôi theo số 555-0164 ngay hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}]' WHERE `id` = '5011ec52-573d-4991-b9ed-01eaadf3b7c9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"February 1\", \"vi\": \"Ngày 1 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"SOFTWARE TESTING REPORT\", \"vi\": \"BÁO CÁO KIỂM THỬ PHẦN MỀM\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Version of Software Program: Konserted 2.5\", \"vi\": \"Phiên bản phần mềm: Konserted 2.5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Testing Dates: January 10–12\", \"vi\": \"Thời gian thi: Từ ngày 10 đến ngày 12 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Number of Participants: 8\", \"vi\": \"Số lượng người tham gia: 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Software Testing Overview: Participants were asked to complete a series of tasks testing the functionality of the revised Konserted interface.\", \"vi\": \"Tổng quan về kiểm thử phần mềm: Các học viên được yêu cầu hoàn thành một loạt nhiệm vụ nhằm kiểm tra tính năng của giao diện Konserted đã được sửa đổi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In task number 1, participants searched for a concert in a designated area.\", \"vi\": \"Trong nhiệm vụ số 1, các người tham gia đã tìm kiếm một buổi hòa nhạc tại một khu vực được chỉ định.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In task number 2, participants searched for new friends on the site.\", \"vi\": \"Trong nhiệm vụ số 2, các người tham gia đã tìm kiếm những người bạn mới trên trang web.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In task number 3, participants invited friends to a concert.\", \"vi\": \"Trong bài tập số 3, các học viên đã mời bạn bè đến dự một buổi hòa nhạc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In task number 4, participants posted concert reviews, photos, and videos.\", \"vi\": \"Trong bài tập số 4, các thành viên đã đăng tải các bài đánh giá về buổi hòa nhạc, hình ảnh và video.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Initial Findings: Task number 3 proved the most challenging, with three participants unable to complete it in under two minutes.\", \"vi\": \"Kết quả ban đầu: Bài tập số 3 được đánh giá là khó nhất, với ba người tham gia không thể hoàn thành bài tập này trong vòng dưới hai phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"A potential cause for this difficulty may be the choice of icons in the menu bar.\", \"vi\": \"Một nguyên nhân có thể dẫn đến khó khăn này có thể là do việc lựa chọn các biểu tượng trên thanh menu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Clearer, more intuitive icons could make this task easier to complete for participants.\", \"vi\": \"Các biểu tượng rõ ràng và trực quan hơn có thể giúp người tham gia hoàn thành nhiệm vụ này một cách dễ dàng hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '506549a4-310e-4e5e-b45e-6b7dbc5bab47';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Bo Xiao\", \"vi\": \"Kính gửi: Bo Xiao\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: David Morisseau\", \"vi\": \"Từ: David Morisseau\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 16\", \"vi\": \"Ngày: 16 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Re: Order # 3A556\", \"vi\": \"Trả lời: Đơn hàng số 3A556\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Xiao,\", \"vi\": \"Kính gửi ông Xiao,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you very much for your recent purchase from Yippee.com!\", \"vi\": \"Xin chân thành cảm ơn quý khách đã mua hàng tại Yippee.com trong thời gian vừa qua!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We are grateful for your business.\", \"vi\": \"Chúng tôi xin chân thành cảm ơn quý khách đã tin dùng dịch vụ của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We are proud to sell only high-quality products that we believe in and use ourselves.\", \"vi\": \"Chúng tôi tự hào chỉ kinh doanh những sản phẩm chất lượng cao mà chúng tôi tin tưởng và chính bản thân chúng tôi cũng sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We also take pride in providing you with the best customer service possible.\", \"vi\": \"Chúng tôi cũng tự hào mang đến cho quý khách dịch vụ chăm sóc khách hàng tốt nhất có thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To say thank you for your purchase, we would like to offer you 15% off your next order as well as free shipping.\", \"vi\": \"Để tri ân quý khách đã ủng hộ, chúng tôi xin dành tặng quý khách ưu đãi giảm giá 15% cho đơn hàng tiếp theo cùng với dịch vụ giao hàng miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Visit our Web site at www.yippee.com to place your order.\", \"vi\": \"Vui lòng truy cập trang web của chúng tôi tại địa chỉ www.yippee.com để đặt hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"This offer expires 60 days from the date of this e-mail.\", \"vi\": \"Ưu đãi này sẽ hết hạn sau 60 ngày kể từ ngày gửi email này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"As part of our ongoing efforts to provide the best service available, Yippee.com routinely asks our customers for their feedback.\", \"vi\": \"Nhằm tiếp tục nỗ lực mang đến dịch vụ tốt nhất có thể, Yippee.com thường xuyên thu thập ý kiến phản hồi từ quý khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Therefore, we invite you to visit www.yippee.com/survey to complete our customer-satisfaction survey.\", \"vi\": \"Do đó, chúng tôi kính mời quý vị truy cập trang web www.yippee.com/survey để tham gia cuộc khảo sát mức độ hài lòng của khách hàng do chúng tôi tổ chức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thank you again,\", \"vi\": \"Một lần nữa, xin chân thành cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"David Morisseau\", \"vi\": \"David Morisseau\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Vice President of Customer Service\", \"vi\": \"Phó Tổng Giám đốc phụ trách Dịch vụ Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Yippee.com\", \"vi\": \"Yippee.com\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '5098584d-7107-4a91-953b-69f96b47c1f6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: tvargas@sandelleinn.com\", \"vi\": \"Đến: tvargas@sandelleinn.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: moira@petalsaplenty.com\", \"vi\": \"Từ: moira@petalsaplenty.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: November 2\", \"vi\": \"Ngày: Ngày 2 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Floral arrangement\", \"vi\": \"Chủ đề: Cắm hoa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Vargas,\", \"vi\": \"Kính gửi Cô Vargas,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I left a complimentary floral arrangement with your receptionist today, and she suggested that I contact you directly.\", \"vi\": \"Tôi đã để lại một lẵng hoa miễn phí tại quầy lễ tân của quý khách vào hôm nay, và cô ấy đã gợi ý tôi nên liên hệ trực tiếp với cô.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I specialize in floral design.\", \"vi\": \"Tôi chuyên về thiết kế nghệ thuật cắm hoa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I created this bouquet for you, using bold colors that match the inn\'s lobby, to give you an idea of how I ------- (143) my work.\", \"vi\": \"Tôi đã tạo ra bó hoa này dành cho cô, sử dụng các màu sắc nổi bật phù hợp với sảnh của nhà nghỉ, nhằm giúp cô hình dung cách tôi ------- (143) công việc của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [143]}, {\"en\": \"I was told that you do not currently have a budget for décor.\", \"vi\": \"Tôi được biết rằng hiện tại cô không có ngân sách dành cho việc trang trí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"------- (144), perhaps we could still partner in some way.\", \"vi\": \"------- (144), có lẽ chúng ta vẫn có thể hợp tác theo một cách nào đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [144]}, {\"en\": \"I see that you host small events, and your Web site has links to local DJs, caterers, and other service providers that you recommend.\", \"vi\": \"Tôi thấy rằng cô thường tổ chức các sự kiện nhỏ, và trang web của cô có các liên kết đến các DJ, nhà cung cấp dịch vụ ăn uống và các nhà cung cấp dịch vụ khác tại địa phương mà cô giới thiệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Would you consider including my company, Petals Aplenty, on your list of ------- (145)?\", \"vi\": \"Cô có cân nhắc đưa công ty của tôi, Petals Aplenty, vào danh sách ------- (145) của cô không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [145]}, {\"en\": \"I would be happy to reciprocate by promoting your inn on my own Web site.\", \"vi\": \"Tôi rất sẵn lòng đáp lại bằng cách quảng bá cho nhà nghỉ của cô trên trang web của riêng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"------- (146).\", \"vi\": \"------- (146).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": [146]}, {\"en\": \"I look forward to hearing from you.\", \"vi\": \"Tôi rất mong nhận được phản hồi từ cô.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Moira Voss, Owner, Petals Aplenty\", \"vi\": \"Moira Voss, Chủ sở hữu, Petals Aplenty\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '50d98a3c-5060-43d2-9459-9af49289a7f5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"New Italian Food Shop Opening Soon\", \"vi\": \"Cửa hàng thực phẩm Ý mới sắp khai trương\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"CALGARY (28 March) - This Saturday marks the grand opening of Calgary\'s latest Italian specialty food shop.\", \"vi\": \"CALGARY (28 tháng 3) - Thứ Bảy tuần này đánh dấu lễ khai trương cửa hàng chuyên doanh thực phẩm Ý mới nhất tại Calgary.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Salerno\'s Italian Food will sell its own brand of fresh pastas and sauces ___139___ imported goods.\", \"vi\": \"Cửa hàng thực phẩm Ý Salerno\'s sẽ bán thương hiệu mì ống và sốt tươi của riêng mình ___139___ các mặt hàng nhập khẩu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [139]}, {\"en\": \"The shop is located on the corner of Macall Avenue and Arnhem Street.\", \"vi\": \"Cửa hàng nằm ở góc đường Macall Avenue và phố Arnhem.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"___140___.\", \"vi\": \"___140___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [140]}, {\"en\": \"This small part of Calgary is becoming a very popular place to go for gourmet food.\", \"vi\": \"Khu vực nhỏ này của Calgary đang trở thành một địa điểm rất nổi tiếng để tìm mua các loại thực phẩm cao cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Leo Sarri, the store\'s owner, was ___141___ the chef at Milano\'s.\", \"vi\": \"Leo Sarri, chủ cửa hàng, từng là ___141___ đầu bếp tại Milano\'s.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [141]}, {\"en\": \"He is looking forward to Saturday and says he is thrilled to be entering the ___142___ world for the first time.\", \"vi\": \"Ông rất mong đợi ngày thứ Bảy và cho biết ông rất hào hứng khi lần đầu tiên bước chân vào thế giới ___142___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [142]}]' WHERE `id` = '50ddb25b-b98c-4c3c-adb7-7687caa09958';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.greenroofplus.com\", \"vi\": \"https://www.greenroofplus.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Basics Photos Resources News\", \"vi\": \"Kiến thức cơ bản | Hình ảnh | Tài nguyên | Tin tức\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"What Are Green Roofs?\", \"vi\": \"Mái xanh là gì?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Green roofs are an energy-saving option for office buildings and homes.\", \"vi\": \"Mái xanh là một giải pháp tiết kiệm năng lượng dành cho các tòa nhà văn phòng và nhà ở.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"A green roof is one that\'s covered with grasses, flowers, or other plants.\", \"vi\": \"Mái xanh là loại mái được phủ bằng cỏ, hoa hoặc các loại thực vật khác.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"It lowers heating and cooling costs while increasing a structure\'s aesthetic appeal.\", \"vi\": \"Giải pháp này giúp giảm chi phí sưởi ấm và làm mát, đồng thời nâng cao giá trị thẩm mỹ của công trình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This Web site is designed for sharing ideas, photos, and resources to create and maintain a green roof.\", \"vi\": \"Trang web này được thiết kế nhằm chia sẻ các ý tưởng, hình ảnh và tài liệu tham khảo để xây dựng và bảo dưỡng mái xanh.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Planting a rooftop garden is a rewarding do-it-yourself project, but special waterproofing and other preparations require the services of an experienced contractor.\", \"vi\": \"Việc trồng vườn trên mái là một dự án tự làm mang lại nhiều niềm vui, song các công đoạn chống thấm đặc biệt cùng những công tác chuẩn bị khác đòi hỏi phải có sự hỗ trợ của một nhà thầu giàu kinh nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Costs vary widely by region, roof size, and complexity of the garden you want to create.\", \"vi\": \"Chi phí có sự chênh lệch đáng kể tùy theo khu vực, diện tích mái nhà và mức độ phức tạp của khu vườn mà quý vị mong muốn tạo dựng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Be sure to get estimates from at least two contractors.\", \"vi\": \"Hãy nhớ yêu cầu báo giá từ ít nhất hai nhà thầu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"If your contractor determines that your roof can handle the extra weight of soil, plants, and irrigation, ask about the project\'s timeline.\", \"vi\": \"Nếu nhà thầu của quý vị xác định rằng mái nhà của quý vị có thể chịu được trọng lượng thêm từ đất, cây trồng và hệ thống tưới tiêu, xin vui lòng hỏi về tiến độ thực hiện dự án.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Small, simple rooftop gardens may take only one week to complete.\", \"vi\": \"Những khu vườn trên mái nhỏ và đơn giản có thể chỉ mất một tuần để hoàn thành.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '50e5f8ac-3565-4fc9-b614-a50539d5c04a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Peake Painting Ltd. • 375 Fox Road • Toronto, ON M5B 2C1 • 416-555-0101\", \"vi\": \"Công ty TNHH Peake Painting • 375 Fox Road • Toronto, ON M5B 2C1 • 416-555-0101\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"8 June\", \"vi\": \"ngày 8 tháng 6\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Ms. Priti Parekh, Manager\", \"vi\": \"Bà Priti Parekh, Quản lý\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Eagle Point Apartments\", \"vi\": \"Khu căn hộ Eagle Point\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"23 Concordia Lane\", \"vi\": \"23 Concordia Lane\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Toronto, ON M5H 1A1\", \"vi\": \"Toronto, ON M5H 1A1\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Ms. Parekh:\", \"vi\": \"Kính gửi bà Parekh:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This letter is a follow-up to our telephone conversation of 6 June.\", \"vi\": \"Thư này là để tiếp nối cuộc trò chuyện qua điện thoại của chúng ta vào ngày 6 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As I mentioned then, we have been successfully serving many apartment complexes in the Toronto area for the past fifteen years.\", \"vi\": \"Như tôi đã đề cập trước đây, trong mười lăm năm qua, chúng tôi đã cung cấp dịch vụ thành công cho nhiều khu chung cư tại khu vực Toronto.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I would be happy to supply references.\", \"vi\": \"Tôi rất sẵn lòng cung cấp các tài liệu tham khảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I also discussed with you the various benefits our service agreement offers.\", \"vi\": \"Tôi cũng đã trao đổi với quý vị về những lợi ích đa dạng mà hợp đồng dịch vụ của chúng tôi mang lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"These include priority scheduling, preventive maintenance, service discounts, and advice from our expert painters.\", \"vi\": \"Trong số đó có việc sắp xếp lịch ưu tiên, bảo trì phòng ngừa, các chương trình ưu đãi dịch vụ và lời khuyên từ đội ngũ thợ sơn chuyên nghiệp của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Our service agreement also covers the repainting of apartments vacated by tenants and a one-year guarantee on paint and labour.\", \"vi\": \"Hợp đồng dịch vụ của chúng tôi cũng bao gồm việc sơn lại các căn hộ mà người thuê đã dọn ra và bảo hành một năm cho cả sơn lẫn chi phí nhân công.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Enclosed is a copy of our standard contract, which can be adjusted to your specific needs and requirements.\", \"vi\": \"Kèm theo đây là bản sao hợp đồng mẫu của chúng tôi, có thể được điều chỉnh cho phù hợp với các nhu cầu và yêu cầu cụ thể của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Please let me know if you need any further information.\", \"vi\": \"Nếu quý vị cần thêm thông tin, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I look forward to hearing from you soon.\", \"vi\": \"Tôi mong sớm nhận được phản hồi từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Nuruddin Abdullahi\", \"vi\": \"Nuruddin Abdullahi\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Nuruddin Abdullahi, Owner\", \"vi\": \"Nuruddin Abdullahi, Chủ sở hữu\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Peake Painting Ltd.\", \"vi\": \"Công ty TNHH Peake Painting\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Enclosure\", \"vi\": \"Phụ lục\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '513b0176-8ddf-4c58-b5a3-1985a112b176';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: ababin@babinassociates.co.nz\", \"vi\": \"Gửi tới: ababin@babinassociates.co.nz\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: f_zhong@zhong.co.nz\", \"vi\": \"Nguồn: f_zhong@zhong.co.nz\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 5 March\", \"vi\": \"Ngày: 5 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Order #45368\", \"vi\": \"Chủ đề: Đơn hàng số 45368\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"E-Mail Message\", \"vi\": \"Thông điệp email\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Babin,\", \"vi\": \"Kính gửi bà Babin,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I\'m writing to inform you of several problems regarding my recent order.\", \"vi\": \"Tôi viết thư này để thông báo cho quý vị về một số vấn đề liên quan đến đơn hàng gần đây của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I have been buying items from your company for years, and my previous orders have never had an error.\", \"vi\": \"Tôi đã mua hàng từ công ty quý vị trong nhiều năm qua, và các đơn hàng trước đây của tôi chưa bao giờ gặp sự cố nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Therefore, I was very surprised when my latest order arrived.\", \"vi\": \"Do đó, tôi đã vô cùng ngạc nhiên khi nhận được đơn hàng mới nhất của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"First, the shipment contained only two packs of T-shirts, which is not the amount listed on the invoice.\", \"vi\": \"Thứ nhất, lô hàng chỉ chứa hai gói áo thun, không đúng với số lượng được ghi trên hóa đơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I saw the note about the long-sleeved shirts, but there was no note about the T-shirts.\", \"vi\": \"Tôi đã đọc thông báo về áo sơ mi dài tay, nhưng không thấy có thông báo nào về áo thun cả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Additionally, the price for item number 61 is listed in your catalog and on your Web site as $50 per pack, but that was not what I was charged.\", \"vi\": \"Ngoài ra, giá của mặt hàng số 61 được niêm yết trong danh mục sản phẩm và trên trang web của quý công ty là 50 đô la mỗi gói, nhưng số tiền tôi phải thanh toán lại không phải như vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Can you please look into this matter and give me a call?\", \"vi\": \"Xin quý vị vui lòng xem xét vấn đề này và gọi điện cho tôi được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"You can reach me at +64 04 455 5212.\", \"vi\": \"Quý vị có thể liên hệ với tôi theo số +64 04 455 5212.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Thanks in advance,\", \"vi\": \"Xin chân thành cảm ơn trước,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Fai Zhong\", \"vi\": \"Fai Zhong\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"From:\\nBabin and Associates\\n25 Caledonia Street, Strathmore\\nWellington 6022 To:\\nFai Zhong\\nZhong Restaurant and Catering\\n76 Romeo Street, Thorndon\\nWellington 6011\", \"vi\": \"Từ:\\nBabin and Associates\\n25 Caledonia Street, Strathmore\\nWellington 6022 Gửi tới:\\nFai Zhong\\nNhà hàng và Dịch vụ Ẩm thực Zhong\\n76 Romeo Street, Thorndon\\nWellington 6011\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Item Number - Item Description - Amount Ordered - Price per Pack - Total Price\", \"vi\": \"Mã hàng - Mô tả sản phẩm - Số lượng đặt hàng - Giá mỗi gói - Tổng giá\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"32A - T-shirts, white with logo, assorted sizes - 3 packs - $125.00 - $375.00\", \"vi\": \"32A - Áo thun màu trắng có in logo, các cỡ khác nhau - Gói 3 chiếc - 125,00 USD - 375,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"32B*\\nSee note below - Long-sleeved shirts, white with logo, assorted sizes - 3 packs - $175.00 - $525.00\", \"vi\": \"32B*\\nXin xem chú thích bên dưới – Áo sơ mi tay dài, màu trắng có in logo, các cỡ khác nhau – Gói 3 chiếc – 175,00 USD – 525,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"61 - Black aprons, limited edition, knee-length - 5 packs - $60.00 - $300.00\", \"vi\": \"61 - Tạp dề màu đen, phiên bản giới hạn, dài đến đầu gối - Gói 5 chiếc - 60,00 USD - 300,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"118 - Black trousers, assorted sizes - 2 packs - $200.00 - $400.00\", \"vi\": \"118 - Quần dài màu đen, các cỡ khác nhau - 2 gói - 200,00 USD - 400,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"TOTAL - GST Inclusive - $1,600.00\", \"vi\": \"TỔNG CỘNG – Đã bao gồm thuế GST – 1.600,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"PAYMENT IS DUE UPON RECEIPT OF INVOICE\", \"vi\": \"Vui lòng thanh toán ngay khi nhận được hóa đơn\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Order #45368\", \"vi\": \"Đơn hàng số 45368\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"* We had only one pack of long-sleeved shirts in stock.\", \"vi\": \"* Chúng tôi chỉ còn một gói áo sơ mi dài tay trong kho.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"We included it with this shipment and will send the others in 7–10 business days.\", \"vi\": \"Chúng tôi đã gửi kèm mặt hàng này trong lô hàng lần này và sẽ gửi các mặt hàng còn lại trong vòng 7–10 ngày làm việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"There will be no additional shipping charge for these items.\", \"vi\": \"Các mặt hàng này sẽ không bị tính thêm phí vận chuyển.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '51426101-7dc1-444d-a3c8-352b110025d6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Cardiff Daily Times\", \"vi\": \"Báo Cardiff Daily Times\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"In Brief—20 March\", \"vi\": \"Tóm tắt — Ngày 20 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"As reported earlier this year, Gold Kettle Grocery is opening an additional regional distribution centre in Cardiff.\", \"vi\": \"Như đã đưa tin hồi đầu năm nay, Gold Kettle Grocery sẽ khai trương thêm một trung tâm phân phối khu vực tại Cardiff.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Construction was postponed for a time because of an unanticipated problem related to the ground conditions on the site.\", \"vi\": \"Công trình đã bị hoãn lại một thời gian do một vấn đề không lường trước được liên quan đến điều kiện địa chất tại khu vực công trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"However, the problem has been resolved, and the 40,000-square-metre centre should be fully operational in June.\", \"vi\": \"Tuy nhiên, vấn đề này đã được giải quyết, và trung tâm có diện tích 40.000 mét vuông này dự kiến sẽ đi vào hoạt động đầy đủ vào tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The grand opening is planned for the fourth of June.\", \"vi\": \"Lễ khai trương dự kiến sẽ diễn ra vào ngày 4 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The warehouse has a special area with state-of-the-art equipment to store foods that need to be kept frozen or cool.\", \"vi\": \"Kho hàng có một khu vực chuyên dụng được trang bị các thiết bị hiện đại nhất để bảo quản các loại thực phẩm cần được giữ đông lạnh hoặc làm mát.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The site will also include loading bays and offices.\", \"vi\": \"Khu vực này cũng sẽ bao gồm các bãi xếp dỡ hàng hóa và các văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The distribution centre is expected to create more than 400 new jobs, according to Myles Simler, vice president of operations.\", \"vi\": \"Theo ông Myles Simler, Phó Chủ tịch phụ trách hoạt động, trung tâm phân phối này dự kiến sẽ tạo ra hơn 400 việc làm mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Because of the size and scope of the project, a variety of jobs will be needed, from warehouse loaders and drivers to clerical positions.\", \"vi\": \"Do quy mô và phạm vi của dự án, sẽ cần đến nhiều vị trí công việc khác nhau, từ nhân viên bốc xếp kho và tài xế cho đến các vị trí hành chính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To: Myles Simler <msimler@goldkettle.co.uk>\", \"vi\": \"Gửi: Myles Simler <msimler@goldkettle.co.uk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"From: Raadhika Baral <rbaral@goldkettle.co.uk>\", \"vi\": \"Từ: Raadhika Baral <rbaral@goldkettle.co.uk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: 26 June\", \"vi\": \"Ngày: 26 tháng 6\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Attachment: Notification comparison\", \"vi\": \"Tệp đính kèm: So sánh các thông báo\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dear Myles:\", \"vi\": \"Kính gửi anh Myles:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thanks for giving me a lift to the grand opening earlier this month.\", \"vi\": \"Xin cảm ơn quý vị đã cho tôi đi nhờ xe đến buổi lễ khai trương vào đầu tháng này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I do not believe I have ever seen such a well-planned event.\", \"vi\": \"Tôi không nghĩ rằng mình từng được chứng kiến một sự kiện nào được tổ chức chu đáo đến vậy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We should send Ping Chen something to show him our appreciation for organising it.\", \"vi\": \"Chúng ta nên gửi cho anh Ping Chen một món quà nào đó để bày tỏ lòng biết ơn vì anh ấy đã tổ chức sự kiện này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Now that the centre in Cardiff has been open for a few weeks, I think we should consider hiring a company that forwards automatic notifications to employees\' mobile phones.\", \"vi\": \"Vì trung tâm tại Cardiff đã đi vào hoạt động được vài tuần, tôi cho rằng chúng ta nên xem xét việc thuê một công ty chuyên gửi thông báo tự động đến điện thoại di động của nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Such a service would allow us to get messages to them quickly and also prevent mistakes with shipments.\", \"vi\": \"Dịch vụ như vậy sẽ giúp chúng tôi truyền tải thông tin đến quý vị một cách nhanh chóng và đồng thời ngăn ngừa các sai sót trong quá trình vận chuyển.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I have a contact who has worked in customer service at Calls For You.\", \"vi\": \"Tôi có một người quen từng làm việc trong bộ phận dịch vụ khách hàng tại Calls For You.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I think it\'s a good company, but Raven Notifications also looks good, and their rates are lower.\", \"vi\": \"Tôi cho rằng đây là một công ty tốt, nhưng Raven Notifications cũng có vẻ đáng tin cậy, và mức phí của họ lại thấp hơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I have attached information about both companies to help you decide which one we might use.\", \"vi\": \"Tôi đã đính kèm thông tin về cả hai công ty để giúp quý vị quyết định xem chúng ta nên hợp tác với công ty nào.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Let me know what you think.\", \"vi\": \"Xin vui lòng cho tôi biết ý kiến của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Raadhika Baral\", \"vi\": \"Con gái của Radha\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Raven Notifications 11:43 A.M.\", \"vi\": \"Thông báo từ Raven lúc 11 giờ 43 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"To Gold Kettle Employees—The frozen-goods shipment scheduled to arrive on Tuesday will not arrive until Wednesday.\", \"vi\": \"Kính gửi các nhân viên của Gold Kettle — Lô hàng thực phẩm đông lạnh dự kiến sẽ đến vào thứ Ba sẽ phải lùi lại đến thứ Tư.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Employees who had volunteered to work additional hours on Tuesday night at the Cardiff distribution centre will not be needed.\", \"vi\": \"Các nhân viên đã tình nguyện làm thêm giờ vào tối thứ Ba tại trung tâm phân phối Cardiff sẽ không cần phải làm việc nữa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"However, we will need additional help for the overnight shift on Wednesday night.\", \"vi\": \"Tuy nhiên, chúng tôi sẽ cần thêm nhân lực cho ca làm việc ban đêm vào tối thứ Tư.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"If you are interested in working additional hours at that time, please contact Becca Johnston in Human Resources.\", \"vi\": \"Nếu quý vị quan tâm đến việc làm thêm giờ vào thời điểm đó, xin vui lòng liên hệ với bà Becca Johnston tại Phòng Nhân sự.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}]' WHERE `id` = '517f6091-76ba-4dcd-b1ca-1bd32eb92149';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All Staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Ken Harrise\", \"vi\": \"Từ: Ken Harrise\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: February 8\", \"vi\": \"Ngày: 8 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Professional development\", \"vi\": \"Chủ đề: Phát triển chuyên môn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Xin chào\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This spring, I would like to encourage all employees to take up to two full work days to attend professional development workshops.\", \"vi\": \"Vào mùa xuân này, tôi xin khuyến khích tất cả các nhân viên dành tối đa hai ngày làm việc đầy đủ để tham dự các hội thảo phát triển chuyên môn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"At the conclusion of each workshop, I would like participants to prepare a brief presentation for their department colleagues about what they learned.\", \"vi\": \"Vào cuối mỗi buổi hội thảo, tôi mong các học viên sẽ chuẩn bị một bài trình bày ngắn gọn dành cho các đồng nghiệp trong phòng ban của mình về những điều mà các vị đã học được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Each department will receive a customized list of pertinent workshops for consideration.\", \"vi\": \"Mỗi phòng ban sẽ nhận được một danh sách các hội thảo phù hợp, được thiết kế riêng để tham khảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please contact your department manager if you would like to pursue an opportunity for professional development that is not on the list.\", \"vi\": \"Nếu quý vị mong muốn tham gia một cơ hội phát triển nghề nghiệp không có trong danh sách, xin vui lòng liên hệ với trưởng bộ phận của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We will do our best to support all requests.\", \"vi\": \"Chúng tôi sẽ nỗ lực hết sức để đáp ứng mọi yêu cầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Xin cảm ơn.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Ken Harrise\", \"vi\": \"Ken Harris\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Approved workshops for Harrise Systems\' Information Technology (IT) Department\\nManager: Nancy Welker\", \"vi\": \"Các khóa đào tạo đã được phê duyệt dành cho Phòng Công nghệ Thông tin (IT) của Harrise Systems\\nTrưởng phòng: Nancy Welker\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Title - Facilitator - Date - Description\", \"vi\": \"Tiêu đề - Người điều phối - Ngày - Mô tả\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Developments in Data Security - Leslie Mehra - March 5 - Strategies and exercises for protecting your company\'s data\", \"vi\": \"Những tiến triển mới trong lĩnh vực bảo mật dữ liệu - Leslie Mehra - Ngày 5 tháng 3 - Các chiến lược và bài tập thực hành nhằm bảo vệ dữ liệu của công ty quý vị\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Managing Big Data - Janet Sabol - March 8 - Overview of software systems used to manage data efficiently\", \"vi\": \"Quản lý Dữ liệu Lớn - Janet Sabol - Ngày 8 tháng 3 - Tổng quan về các hệ thống phần mềm được sử dụng để quản lý dữ liệu một cách hiệu quả\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Our Online Presence and Social Media - Terrence Brewster - April 2 - The role of IT departments in educating and managing staff regarding workplace computer use\", \"vi\": \"Sự hiện diện trực tuyến và các nền tảng mạng xã hội của chúng tôi - Terrence Brewster - Ngày 2 tháng 4 - Vai trò của các phòng ban Công nghệ Thông tin trong việc đào tạo và quản lý nhân viên về việc sử dụng máy tính tại nơi làm việc\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"IT Administration - Dan Michaels - April 18 - The expanding duties of an IT administrator\", \"vi\": \"Quản trị CNTT - Dan Michaels - Ngày 18 tháng 4 - Nhiệm vụ ngày càng mở rộng của một quản trị viên CNTT\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"To: Nancy Welker\", \"vi\": \"Kính gửi: Bà Nancy Welker\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"From: Paul Cheung\", \"vi\": \"Từ: Paul Cheung\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Date: April 20\", \"vi\": \"Ngày: 20 tháng 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Subject: Workshop completion\", \"vi\": \"Chủ đề: Hoàn thành khóa đào tạo\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Dear Nancy,\", \"vi\": \"Kính gửi bà Nancy,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"As per Mr. Harrise\'s suggestion, I attended the workshop \\\"Our Online Presence and Social Media.\\\"\", \"vi\": \"Theo đề xuất của ông Harrise, tôi đã tham dự hội thảo với chủ đề “Sự hiện diện trực tuyến và mạng xã hội của chúng ta”.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I learned about the guidance we can offer employees who use social media, and I am prepared to present a report highlighting the workshop\'s content.\", \"vi\": \"Tôi đã tìm hiểu về những hướng dẫn mà chúng ta có thể cung cấp cho các nhân viên khi sử dụng mạng xã hội, và tôi đã sẵn sàng trình bày một báo cáo nêu rõ nội dung của buổi hội thảo.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Please let me know a convenient day and time for this activity, and I will schedule one of the conference rooms for our IT team.\", \"vi\": \"Xin vui lòng cho tôi biết ngày và giờ nào thuận tiện để tổ chức hoạt động này; tôi sẽ sắp xếp một phòng hội nghị cho đội ngũ CNTT của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I have some printed material to distribute as well.\", \"vi\": \"Tôi cũng có một số tài liệu in sẵn để phát cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Paul\", \"vi\": \"Paul\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = '51fcc4e5-80dd-4234-b343-e751a3472b54';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Curtis Dawson   [11:31 A.M.]\", \"vi\": \"Curtis Dawson   [11 giờ 31 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Misako, our van has broken down in Kloss, and the mechanic says the repairs will take at least four hours.\", \"vi\": \"Misako ạ, chiếc xe tải của chúng ta đã bị hỏng ở Kloss, và thợ sửa xe cho biết việc sửa chữa sẽ mất ít nhất bốn giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Misako Endo   [11:33 A.M.]\", \"vi\": \"Những câu chuyện của Endo [11 giờ 33 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Oh no!\", \"vi\": \"Ôi không!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Well, we need to make sure our customers still get the experience they’ve paid for.\", \"vi\": \"Vâng, chúng ta cần đảm bảo rằng khách hàng của chúng ta vẫn nhận được trải nghiệm mà họ đã chi trả.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"You’re taking six people to Galvin Falls for the afternoon, right?\", \"vi\": \"Chiều nay quý vị sẽ đưa sáu người đến thác Galvin, phải không ạ?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Curtis Dawson   [11:34 A.M.]\", \"vi\": \"Curtis Dawson   [11 giờ 34 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"That’s right.\", \"vi\": \"Đúng vậy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"And we’re supposed to have lunch in Medford.\", \"vi\": \"Và chúng tôi dự định sẽ dùng bữa trưa tại Medford.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Misako Endo   [11:35 A.M.]\", \"vi\": \"Những câu chuyện của Endo [11 giờ 35 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Do you think you could find a place to eat in Kloss instead?\", \"vi\": \"Quý vị có nghĩ rằng mình có thể tìm được một nơi để ăn uống ở Kloss thay thế không?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"While you were doing that, I could rent another van from a local agency and have it driven over to you.\", \"vi\": \"Trong khi quý vị đang làm việc đó, tôi có thể thuê một chiếc xe tải khác từ một đại lý địa phương và sắp xếp để xe được đưa đến chỗ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Curtis Dawson   [11:36 A.M.]\", \"vi\": \"Curtis Dawson   [11 giờ 36 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Oh, we’re right near Kloss Shopping Center.\", \"vi\": \"À, chúng tôi đang ở ngay gần Trung tâm thương mại Kloss.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thanks, Misako!\", \"vi\": \"Cảm ơn, Misako!\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I’ll text you the exact address once we get settled.\", \"vi\": \"Khi chúng tôi ổn định xong, tôi sẽ nhắn tin cho quý vị địa chỉ chính xác.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '520e0856-e05c-41a6-92dd-3e4c97a4a7c4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Veronica Hale <vhale@castillosouthwest.com>\", \"vi\": \"Gửi tới: Veronica Hale <vhale@castillosouthwest.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Natalie Lewin <natalie@biz-builder.com>\", \"vi\": \"Từ: Natalie Lewin <natalie@biz-builder.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: August 12\", \"vi\": \"Ngày: 12 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Workshop and books\", \"vi\": \"Chủ đề: Hội thảo và sách\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Title - Price - Discounted Price - Subtotal\", \"vi\": \"Tên sản phẩm - Giá - Giá sau khi giảm - Tổng phụ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Corporate and Social Responsibility x 1 - $16.00 - $12.80 - $12.80\", \"vi\": \"Trách nhiệm xã hội và doanh nghiệp x 1 - 16,00 USD - 12,80 USD - 12,80 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Writing Effective Press Releases x 1 - $25.00 - $20.00 - $20.00\", \"vi\": \"Viết thông cáo báo chí hiệu quả x 1 - 25,00 USD - 20,00 USD - 20,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Crisis Management in Public Relations x 1 - $26.00 - $20.80 - $20.80\", \"vi\": \"Quản lý khủng hoảng trong quan hệ công chúng x 1 - 26,00 USD - 20,80 USD - 20,80 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Clarifying Communications Objectives x 1 - $21.00 - $16.80 - $16.80\", \"vi\": \"Làm rõ các mục tiêu truyền thông × 1 - 21,00 USD - 16,80 USD - 16,80 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Total charge of $70.40 to credit card ending in -8405.\", \"vi\": \"Tổng số tiền 70,40 USD sẽ được tính vào thẻ tín dụng có số kết thúc bằng -8405.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Dear Ms. Hale,\", \"vi\": \"Kính gửi bà Hale,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Your registration for Ganesh Kamal\'s workshop on September 3 has been confirmed.\", \"vi\": \"Việc đăng ký tham gia buổi hội thảo của ông Ganesh Kamal vào ngày 3 tháng 9 của quý vị đã được xác nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"As you have registered for the in-person workshop, rather than the online workshop, please let us know if you have any dietary restrictions.\", \"vi\": \"Vì quý vị đã đăng ký tham gia hội thảo trực tiếp thay vì hội thảo trực tuyến, xin vui lòng thông báo cho chúng tôi biết nếu quý vị có bất kỳ hạn chế nào về chế độ ăn uống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"This will help us prepare the refreshments for the breaks.\", \"vi\": \"Điều này sẽ giúp chúng tôi chuẩn bị đồ ăn nhẹ cho các giờ giải lao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We have also processed your payment for Mr. Kamal\'s books below, which are eligible for a 20% discount, as they are relevant to the workshop\'s sessions.\", \"vi\": \"Chúng tôi cũng đã xử lý khoản thanh toán của quý vị cho các cuốn sách của ông Kamal được liệt kê dưới đây; các cuốn sách này được hưởng mức giảm giá 20% do có liên quan đến các buổi học của hội thảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We look forward to seeing you at the event!\", \"vi\": \"Chúng tôi rất mong được gặp quý vị tại sự kiện này!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Natalie Lewin\", \"vi\": \"Natalie Lewin\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Administrator, Biz-Builder\", \"vi\": \"Quản trị viên, Biz-Builder\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Notice to Workshop Participants:\", \"vi\": \"Thông báo dành cho các học viên tham gia hội thảo:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Unfortunately, our question-and-answer page is not working, and it may not be fixed by September 3.\", \"vi\": \"Rất tiếc, trang hỏi đáp của chúng tôi hiện đang gặp sự cố và có thể sẽ không được khắc phục trước ngày 3 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Online participants can still submit questions to natalie@biz-builder.com during the event, and we will pass them along to Ganesh Kamal in a timely manner.\", \"vi\": \"Các đại biểu tham gia trực tuyến vẫn có thể gửi câu hỏi đến địa chỉ natalie@biz-builder.com trong suốt thời gian diễn ra sự kiện, và chúng tôi sẽ chuyển tiếp các câu hỏi đó đến ông Ganesh Kamal một cách kịp thời.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Please also note that online participants will receive their books by express shipping, no later than September 1, and everyone else can collect their orders from the registration table.\", \"vi\": \"Xin lưu ý thêm rằng những người tham dự trực tuyến sẽ nhận được sách qua dịch vụ chuyển phát nhanh, chậm nhất là vào ngày 1 tháng 9, còn những người còn lại có thể đến quầy đăng ký để nhận đơn hàng của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"To: Larry Wooster <lwooster@castillosouthwest.com>\", \"vi\": \"Gửi tới: Larry Wooster <lwooster@castillosouthwest.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"From: Veronica Hale <vhale@castillosouthwest.com>\", \"vi\": \"Từ: Veronica Hale <vhale@castillosouthwest.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Date: September 16\", \"vi\": \"Ngày: 16 tháng 9\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Subject: Ganesh Kamal\'s book\", \"vi\": \"Chủ đề: Cuốn sách của ông Ganesh Kamal\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Dear Larry,\", \"vi\": \"Kính gửi ông Larry,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Thank you for the file you sent regarding the launch of our new service.\", \"vi\": \"Xin cảm ơn quý vị đã gửi tệp tin liên quan đến việc ra mắt dịch vụ mới của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I\'d like to meet to discuss it further, as I think we can improve the way the announcement is phrased.\", \"vi\": \"Tôi mong được gặp quý vị để thảo luận thêm về vấn đề này, vì tôi cho rằng chúng ta có thể cải thiện cách diễn đạt của thông báo này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I\'m wondering if you\'ve had time to read the Ganesh Kamal book I gave you.\", \"vi\": \"Tôi không biết liệu quý vị đã có thời gian đọc cuốn sách của Ganesh Kamal mà tôi đã tặng quý vị chưa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I believe its contents will be very helpful when preparing and sending official statements to the media.\", \"vi\": \"Tôi tin rằng nội dung của tài liệu này sẽ rất hữu ích trong quá trình soạn thảo và gửi các tuyên bố chính thức tới các cơ quan truyền thông.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Veronica\", \"vi\": \"Veronica\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '52559bc5-a0c7-4a02-9ee6-3c61e7f6d8cb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"George\'s Orchard Farm\", \"vi\": \"Trang trại Vườn cây ăn quả George\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"2232 Alpine Lane\", \"vi\": \"2232 Alpine Lane\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Pick your own!\", \"vi\": \"Hãy tự tay chọn nhé!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Select from five varieties of juicy peaches in our orchard!\", \"vi\": \"Hãy lựa chọn trong số năm loại đào ngon ngọt tại vườn cây ăn quả của chúng tôi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Buckets provided at no cost.\", \"vi\": \"Các xô được cung cấp miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Stop by our market to purchase jams, pies, and sauces made from farm-fresh fruit.\", \"vi\": \"Hãy ghé qua chợ của chúng tôi để mua mứt, bánh nướng và nước sốt được chế biến từ trái cây tươi ngon vừa hái từ trang trại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We sell lunches to enjoy in our picnic area.\", \"vi\": \"Chúng tôi bán các suất ăn trưa để quý khách có thể thưởng thức tại khu vực dã ngoại của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Follow the signs ahead for designated parking areas.\", \"vi\": \"Xin vui lòng làm theo các biển chỉ dẫn phía trước để đến các khu vực đỗ xe được quy định.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Wednesday to Friday, 12 noon to 5:00 P.M.\", \"vi\": \"Từ thứ Tư đến thứ Sáu, từ 12 giờ trưa đến 5 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Saturday and Sunday, 10:00 A.M. to 6:00 P.M.\", \"vi\": \"Thứ Bảy và Chủ Nhật, từ 10 giờ sáng đến 6 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '5264d692-4077-42a1-9108-2e4ee993b9af';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All CFA Staff\", \"vi\": \"Kính gửi: Toàn thể nhân viên CFA\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Yung-Chien Chou\", \"vi\": \"Từ: Yung-Chien Chou\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 16 October\", \"vi\": \"Ngày: 16 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Plans\", \"vi\": \"Chủ đề: Các kế hoạch\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Agenda\", \"vi\": \"Tài liệu đính kèm: Chương trình làm việc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Colleagues,\", \"vi\": \"Kính gửi các đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Hagit Caspi will be visiting for a couple of days next week to interview for the position of executive vice president here at Cliff Feiring Associates (CFA).\", \"vi\": \"Tuần tới, bà Hagit Caspi sẽ đến thăm công ty trong vài ngày để tham gia phỏng vấn cho vị trí Phó Chủ tịch Điều hành tại Cliff Feiring Associates (CFA).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"She is highly qualified, and her background in international finance makes her particularly well suited for this role.\", \"vi\": \"Bà là một chuyên gia có trình độ cao, và nền tảng kiến thức về tài chính quốc tế của bà khiến bà đặc biệt phù hợp với vị trí này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please make every effort to welcome her.\", \"vi\": \"Kính mong quý vị hãy nỗ lực hết sức để chào đón cô ấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"It is important to the CFA leadership that everyone has the opportunity to get to know Ms. Caspi.\", \"vi\": \"Đối với ban lãnh đạo CFA, điều quan trọng là mọi người đều có cơ hội làm quen với bà Caspi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"As such, I am asking all of you to attend certain events with her.\", \"vi\": \"Vì vậy, tôi xin đề nghị quý vị cùng cô ấy tham dự một số sự kiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please see the attached agenda, and add the events marked CFA to your calendar.\", \"vi\": \"Kính mời quý vị xem chương trình nghị sự đính kèm và thêm các sự kiện được đánh dấu CFA vào lịch của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"More details will follow.\", \"vi\": \"Thông tin chi tiết sẽ được cập nhật sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Yung-Chien Chou\", \"vi\": \"Chou Yung-Chien\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"CEO, Cliff Feiring Associates\", \"vi\": \"Giám đốc Điều hành, Cliff Feiring Associates\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Agenda for Hagit Caspi\'s Visit\", \"vi\": \"Chương trình làm việc trong chuyến thăm của bà Hagit Caspi\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date - Time - Event - Invitees\", \"vi\": \"Ngày - Giờ - Sự kiện - Danh sách khách mời\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"23 October - 9:00 A.M. - Breakfast at La Brunch - Board members\", \"vi\": \"Ngày 23 tháng 10 - 9 giờ sáng - Bữa sáng tại La Brunch - Các thành viên Hội đồng quản trị\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"23 October - 12:30 P.M. - Lunch in office - Department heads\", \"vi\": \"Ngày 23 tháng 10 – 12 giờ 30 phút trưa – Ăn trưa tại văn phòng – Các trưởng phòng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"23 October - 3:00 P.M. - Question-and-answer session - CFA\", \"vi\": \"Ngày 23 tháng 10 - 15 giờ - Buổi hỏi đáp - CFA\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"23 October - 7:00 P.M. - Dinner at Medium Hills Bistro - Board members\", \"vi\": \"Ngày 23 tháng 10 – 7 giờ tối – Bữa tối tại Medium Hills Bistro – Các thành viên Hội đồng quản trị\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"24 October - 9:00 A.M. - Breakfast in office - CFA\", \"vi\": \"Ngày 24 tháng 10 - 9 giờ sáng - Ăn sáng tại văn phòng - CFA\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"To: Yung-Chien Chou <chou@clifffeiring.ca>\", \"vi\": \"Gửi tới: Yung-Chien Chou <chou@clifffeiring.ca>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"From: Hagit Caspi <hagit.caspi@volumel.co.il>\", \"vi\": \"Từ: Hagit Caspi <hagit.caspi@volumel.co.il>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Date: 27 October\", \"vi\": \"Ngày: 27 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Subject: Follow-up\", \"vi\": \"Chủ đề: Theo dõi\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Dear Mr. Chou,\", \"vi\": \"Kính gửi ông Chou,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Many thanks for hosting me last week.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã tiếp đón tôi vào tuần trước.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I truly enjoyed meeting everyone.\", \"vi\": \"Tôi thực sự rất vui khi được gặp tất cả quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I particularly appreciated my conversation with Mr. Georgopoulos at Medium Hills Bistro.\", \"vi\": \"Tôi đặc biệt đánh giá cao cuộc trò chuyện của mình với ông Georgopoulos tại nhà hàng Medium Hills Bistro.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"He told me some amazing stories about CFA\'s history.\", \"vi\": \"Ông ấy đã kể cho tôi nghe một số câu chuyện thú vị về lịch sử của CFA.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Again, I am sorry for not attending the event on the 24th.\", \"vi\": \"Một lần nữa, tôi xin lỗi vì đã không thể tham dự sự kiện vào ngày 24.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"The weather was worrying, and I did not want to miss my flight to Tel Aviv.\", \"vi\": \"Thời tiết khiến tôi lo lắng, và tôi không muốn lỡ chuyến bay đến Tel Aviv.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Last but certainly not least, thank you for your offer, which I received this morning.\", \"vi\": \"Cuối cùng nhưng không kém phần quan trọng, xin chân thành cảm ơn quý vị về đề nghị mà tôi đã nhận được sáng nay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"I would be honoured to take on the role of executive vice president of CFA starting in January.\", \"vi\": \"Tôi sẽ vô cùng vinh dự được đảm nhận cương vị Phó Chủ tịch Điều hành của CFA kể từ tháng Giêng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"The job description covers everything we discussed.\", \"vi\": \"Mô tả công việc này đã bao quát tất cả những nội dung mà chúng ta đã thảo luận.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"The hours you noted for the position seem appropriate, and I am very pleased with the benefits.\", \"vi\": \"Thời gian làm việc mà quý vị đã nêu cho vị trí này có vẻ phù hợp, và tôi rất hài lòng với các chế độ phúc lợi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"I look forward to working closely with you.\", \"vi\": \"Tôi rất mong được hợp tác chặt chẽ với quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Most sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Hagit Caspi\", \"vi\": \"Thử thách Caspi\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}]' WHERE `id` = '52f90ae9-a5b6-484a-a811-838516636dbe';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MEMO\", \"vi\": \"BẢN GHI NHỚ\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All Staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Shondra Brown, Director of Benefits\", \"vi\": \"Từ: Shondra Brown, Giám đốc phụ trách chế độ phúc lợi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: August 4\", \"vi\": \"Ngày: 4 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Re: Wellness Classes\", \"vi\": \"Trả lời: Các lớp học về sức khỏe\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"In the interest of promoting a healthy and productive workforce, Lellar Manufacturing will begin offering monthly wellness classes.\", \"vi\": \"Với mục đích thúc đẩy một lực lượng lao động khỏe mạnh và năng suất cao, Công ty Lellar Manufacturing sẽ bắt đầu tổ chức các lớp học về sức khỏe hàng tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"While participation is not required, we do hope that everyone will take advantage of our community.\", \"vi\": \"Mặc dù việc tham gia không phải là bắt buộc, nhưng chúng tôi thực sự hy vọng rằng mọi người sẽ tận dụng những lợi ích mà cộng đồng của chúng tôi mang lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Part- and full-time regular employees are eligible for these classes at no cost.\", \"vi\": \"Các nhân viên chính thức làm việc bán thời gian và toàn thời gian đều đủ điều kiện tham gia các khóa học này miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"All other workers and trainees will be required to pay a small enrollment fee.\", \"vi\": \"Tất cả các nhân viên và học viên còn lại sẽ phải nộp một khoản lệ phí đăng ký nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Local nurses from Union City Hospital will run the classes on-site, so you do not have to travel anywhere.\", \"vi\": \"Các điều dưỡng viên địa phương thuộc Bệnh viện Union City sẽ trực tiếp giảng dạy các lớp học ngay tại chỗ, do đó quý vị không cần phải đi đâu cả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Classes will be held the first Friday morning of each month, and the class topics will change each month.\", \"vi\": \"Các buổi học sẽ diễn ra vào sáng thứ Sáu đầu tiên của mỗi tháng, và chủ đề của các buổi học sẽ thay đổi theo từng tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The class topics in order, starting in September and going through December, will be as follows: Easy Stretching, Good Food Choices, Tips for Better Sleep, and Starting an Exercise Group.\", \"vi\": \"Các chủ đề của khóa học, theo thứ tự từ tháng 9 đến hết tháng 12, sẽ bao gồm: Các bài tập giãn cơ đơn giản, Lựa chọn thực phẩm lành mạnh, Mẹo để có giấc ngủ ngon hơn và Thành lập nhóm tập thể dục.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Supervisor approval is necessary.\", \"vi\": \"Cần có sự chấp thuận của người giám sát.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The first step is to complete a class request form and send it to the Benefits Department.\", \"vi\": \"Bước đầu tiên là điền vào mẫu đơn đăng ký khóa học và gửi đến Phòng Phúc lợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If you have any questions, contact our benefits counselors Don Herrell at ext. 249 or Leah Katzen at ext. 199.\", \"vi\": \"Nếu Quý vị có bất kỳ thắc mắc nào, xin vui lòng liên hệ với các chuyên viên tư vấn phúc lợi của chúng tôi là ông Don Herrell (số máy lẻ 249) hoặc bà Leah Katzen (số máy lẻ 199).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Name: Alfredo De Santos\", \"vi\": \"Họ và tên: Alfredo De Santos\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Title: Production Trainee\", \"vi\": \"Chức danh: Thực tập sinh bộ phận Sản xuất\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Name/Title of Immediate Supervisor: Galen Sanders, Production Manager\", \"vi\": \"Họ tên/Chức danh của người giám sát trực tiếp: Galen Sanders, Giám đốc sản xuất\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Requested Class Date: September 2\", \"vi\": \"Ngày dự kiến tổ chức lớp học: Ngày 2 tháng 9\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Enrollment Fee Paid: ☑\", \"vi\": \"Đã nộp phí đăng ký: ☑\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Received by Benefits Counselor: Leah Katzen\", \"vi\": \"Người tiếp nhận: Chuyên viên tư vấn phúc lợi: Leah Katzen\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Lellar Manufacturing\", \"vi\": \"Công ty Sản xuất Lellar\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"WELLNESS CLASS REQUEST FORM\", \"vi\": \"MẪU ĐƠN ĐĂNG KÝ LỚP HỌC CHĂM SÓC SỨC KHỎE\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '53114a76-94e1-438b-a92a-d0da73816a71';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Linda Hanshu\", \"vi\": \"Gửi: Linda Hanshu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Cliff Merson\", \"vi\": \"Từ: Cliff Merson\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Lighting Issue\", \"vi\": \"Chủ đề: Vấn đề về hệ thống chiếu sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Date: September 4, 10:12 A.M.\", \"vi\": \"Ngày: 4 tháng 9, 10 giờ 12 phút sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Hi, Ms. Hanshu:\", \"vi\": \"Xin chào, bà Hanshu:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I want to check on the issue we discussed about lighting in the latest chapter of Titan Adventure.\", \"vi\": \"Tôi muốn làm rõ vấn đề mà chúng ta đã thảo luận về ánh sáng trong chương mới nhất của “Titan Adventure”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In past versions of the game, getting the reflections and lighting in green and blue areas correct has been a particular challenge, and it was a problem that kept arising.\", \"vi\": \"Trong các phiên bản trước của trò chơi, việc xử lý chính xác các hiệu ứng phản chiếu và ánh sáng ở các khu vực màu xanh lá và màu xanh dương luôn là một thách thức đặc biệt, và đây là vấn đề liên tục tái diễn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As the new release, Neptune’s Voyage, is primarily an underwater adventure, addressing this problem is crucial.\", \"vi\": \"Vì tựa game mới ra mắt, “Neptune’s Voyage”, chủ yếu là một cuộc phiêu lưu dưới nước, nên việc giải quyết vấn đề này là vô cùng quan trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You said you would take charge of this, and I hope to hear that you have found a solution to the problem.\", \"vi\": \"Quý vị đã nói rằng sẽ chịu trách nhiệm giải quyết vấn đề này, và tôi hy vọng sẽ được biết rằng quý vị đã tìm ra giải pháp cho vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The team was hoping to have one last rendering of the lighting for the game by October 10 for a preliminary run-through.\", \"vi\": \"Nhóm phát triển hy vọng sẽ có được bản dựng hình ảnh ánh sáng cuối cùng cho trò chơi trước ngày 10 tháng 10 để tiến hành một đợt chạy thử sơ bộ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Will the final version of the lighting be ready by then?\", \"vi\": \"Liệu bản thiết kế chiếu sáng cuối cùng có sẵn sàng vào thời điểm đó không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"All other aspects of the game are on schedule.\", \"vi\": \"Tất cả các khía cạnh khác của trò chơi đều đang diễn ra đúng tiến độ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please send me an update about the lighting at your earliest convenience.\", \"vi\": \"Kính mong quý vị vui lòng gửi cho tôi thông tin cập nhật về hệ thống chiếu sáng ngay khi có thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Cliff Merson\", \"vi\": \"Cliff Merson\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Project Manager, Rimerko Games\", \"vi\": \"Quản lý dự án, Rimerko Games\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Review of Titan Adventure: Neptune’s Voyage\", \"vi\": \"Đánh giá về Titan Adventure: Hành trình của Neptune\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"By Leo Weber, April 1\", \"vi\": \"Tác giả: Leo Weber, ngày 1 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"This new installment of Titan Adventure will surprise and delight both new players and old aficionados long familiar with the series.\", \"vi\": \"Phiên bản mới nhất của Titan Adventure này hứa hẹn sẽ mang đến những bất ngờ thú vị và niềm vui cho cả những người chơi mới lẫn những người hâm mộ lâu năm đã quá quen thuộc với loạt game này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Though open-world formats have been widespread in recent years, Neptune’s Voyage brings something new to the format.\", \"vi\": \"Mặc dù thể loại thế giới mở đã trở nên phổ biến trong những năm gần đây, Neptune’s Voyage vẫn mang đến một làn gió mới cho thể loại này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"By stripping down instructional guides, the game gives users the opportunity to discover new areas and devices.\", \"vi\": \"Bằng cách loại bỏ các hướng dẫn chi tiết, trò chơi mang đến cho người chơi cơ hội khám phá những khu vực và thiết bị mới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"In Neptune’s Voyage, you wake up as Thetis, a dolphin that is tasked with rescuing Neptune from an underwater cave.\", \"vi\": \"Trong trò chơi “Neptune’s Voyage”, quý vị sẽ hóa thân thành Thetis, một chú cá heo được giao nhiệm vụ giải cứu Neptune khỏi một hang động dưới nước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Users then climb, run, ride, sail, and fly through the world of the game, encountering new towns, ruins, and other creatures along the way.\", \"vi\": \"Sau đó, người chơi sẽ leo trèo, chạy nhảy, cưỡi ngựa, chèo thuyền và bay lượn khắp thế giới trong trò chơi, đồng thời khám phá những thị trấn mới, những di tích cổ và gặp gỡ các sinh vật khác trên hành trình của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Some of these creatures will be familiar to longtime fans, but there is plenty of novelty as well.\", \"vi\": \"Một số sinh vật trong số này sẽ rất quen thuộc với những người hâm mộ lâu năm, nhưng cũng có không ít điều mới mẻ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"This newest version also corrects the green and blue image rendering that was sometimes a problem in earlier installments of Titan Adventure.\", \"vi\": \"Phiên bản mới nhất này cũng khắc phục lỗi hiển thị màu xanh lá và xanh dương, vốn đôi khi gây ra vấn đề trong các phiên bản trước của Titan Adventure.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Neptune’s Voyage launches May 5 on Rimerko Clutch and FS5.\", \"vi\": \"Neptune’s Voyage sẽ chính thức ra mắt vào ngày 5 tháng 5 trên Rimerko Clutch và FS5.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"It is available in English, Korean, Japanese, French, and Spanish.\", \"vi\": \"Tài liệu này có sẵn bằng tiếng Anh, tiếng Hàn, tiếng Nhật, tiếng Pháp và tiếng Tây Ban Nha.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '53874a65-5c4f-4c1b-9526-f0f23f7671a6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"AKBAR STORAGE COMPANY\\n227 Wexham Road, Bridgetown\\nPhone: 246-555-0147\", \"vi\": \"CÔNG TY LƯU TRỮ AKBAR\\n227 Wexham Road, Bridgetown\\nĐiện thoại: 246-555-0147\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Satisfying storage needs in Barbados for 30 years!\", \"vi\": \"Đáp ứng nhu cầu lưu trữ tại Barbados trong suốt 30 năm qua!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Units are available in small, standard, and premium sizes to fit your storage needs.\", \"vi\": \"Các kho có các kích cỡ nhỏ, tiêu chuẩn và cao cấp để đáp ứng nhu cầu lưu trữ của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Your clean, dry storage unit is available to you around the clock.\", \"vi\": \"Kho chứa hàng sạch sẽ và khô ráo của quý vị luôn sẵn sàng phục vụ quý vị 24/7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Our storage facility is monitored by high-quality security cameras, and each customer is given a pass code.\", \"vi\": \"Khu kho của chúng tôi được giám sát bằng hệ thống camera an ninh chất lượng cao, và mỗi khách hàng đều được cấp một mã truy cập.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our secure electronic gate can be released only by entering this code.\", \"vi\": \"Cổng điện tử an toàn của chúng tôi chỉ có thể được mở bằng cách nhập mã này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our business office is open 9 A.M. to 6 P.M., Monday to Friday, and 9 A.M. to 2 P.M. on Saturday.\", \"vi\": \"Văn phòng kinh doanh của chúng tôi mở cửa từ 9 giờ sáng đến 6 giờ chiều, từ thứ Hai đến thứ Sáu, và từ 9 giờ sáng đến 2 giờ chiều vào thứ Bảy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Stop in to speak with one of our representatives.\", \"vi\": \"Xin mời ghé qua để trao đổi với một trong các đại diện của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"And now, get 20 percent off with a twelve-month rental of our largest type of unit!\", \"vi\": \"Và ngay bây giờ, quý khách sẽ được giảm giá 20% khi thuê loại căn hộ lớn nhất của chúng tôi trong thời hạn 12 tháng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '53aaeb98-4a9d-4b1d-87e4-f9571fc25c25';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dover Water Supply\", \"vi\": \"Hệ thống cấp nước Dover\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"7400 Rodney Boulevard, Dover, DE 19904\", \"vi\": \"7400 Rodney Boulevard, Dover, DE 19904\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"March 12\", \"vi\": \"Ngày 12 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Ms. Na-Ri Cam\", \"vi\": \"Bà Na-Ri Cam\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"361 Farming Avenue\", \"vi\": \"361 Đại lộ Farming\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dover, DE 19902\", \"vi\": \"Dover, DE 19902\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Ms. Cam,\", \"vi\": \"Kính gửi bà Cam,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This letter is to confirm that Dover Water Supply will begin service at your address on Wednesday, April 6.\", \"vi\": \"Thư này nhằm xác nhận rằng Công ty Cấp nước Dover sẽ bắt đầu cung cấp dịch vụ tại địa chỉ của quý vị vào thứ Tư, ngày 6 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Your customer account number, which is the same as your water meter number, is DWS4289.\", \"vi\": \"Số tài khoản khách hàng của quý vị, cũng chính là số đồng hồ nước của quý vị, là DWS4289.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Billing is monthly, and payment is due on the fifteenth of each month.\", \"vi\": \"Việc lập hóa đơn được thực hiện hàng tháng, và hạn thanh toán là ngày mười lăm của mỗi tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Bills can be paid by mailing a check to our main address or by entering your account number and payment information on our secure page at www.doverwatersupply.com/billing.\", \"vi\": \"Quý vị có thể thanh toán hóa đơn bằng cách gửi séc qua đường bưu điện đến địa chỉ chính của chúng tôi hoặc bằng cách nhập số tài khoản và thông tin thanh toán của quý vị trên trang web bảo mật của chúng tôi tại địa chỉ www.doverwatersupply.com/billing.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We will be performing a system flush of the pipes in your area on Monday, April 4.\", \"vi\": \"Vào thứ Hai, ngày 4 tháng 4, chúng tôi sẽ tiến hành xả sạch hệ thống đường ống tại khu vực của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Customers may temporarily see discoloration or sediment in their water around that time.\", \"vi\": \"Vào khoảng thời gian đó, quý khách có thể tạm thời nhận thấy nước có hiện tượng đổi màu hoặc xuất hiện cặn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please visit our Web site for more information.\", \"vi\": \"Kính mời quý vị truy cập trang web của chúng tôi để biết thêm thông tin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"You can also contact Customer Support at questions@doverwatersupply.com or call us at (302) 555-0135.\", \"vi\": \"Quý vị cũng có thể liên hệ với Bộ phận Hỗ trợ Khách hàng qua địa chỉ email questions@doverwatersupply.com hoặc gọi cho chúng tôi theo số (302) 555-0135.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Matthew Ensign\", \"vi\": \"Matthew Ensign\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Matthew Ensign\", \"vi\": \"Matthew Ensign\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Account Representative, Dover Water Supply\", \"vi\": \"Chuyên viên phụ trách khách hàng, Công ty Cấp nước Dover\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"To: questions@doverwatersupply.com\", \"vi\": \"Gửi tới: questions@doverwatersupply.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"From: Na-Ri Cam\", \"vi\": \"Từ: Na-Ri Cam\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Date: March 17\", \"vi\": \"Ngày: 17 tháng 3\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Subject: Account number DWS4289\", \"vi\": \"Chủ đề: Số tài khoản DWS4289\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Xin chào\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I am in the process of moving to my new home in Dover.\", \"vi\": \"Hiện tại, tôi đang trong quá trình chuyển đến ngôi nhà mới của mình tại Dover.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I received a letter stating that my water service will start on April 6.\", \"vi\": \"Tôi đã nhận được một lá thư thông báo rằng dịch vụ cấp nước của tôi sẽ bắt đầu từ ngày 6 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"It also said something about pipes being flushed on April 4.\", \"vi\": \"Ngoài ra, thông báo này còn đề cập đến việc xả nước trong hệ thống ống dẫn vào ngày 4 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Should I expect to see discoloration when I start using my water?\", \"vi\": \"Khi bắt đầu sử dụng nước này, tôi có nên chuẩn bị tinh thần rằng nước sẽ bị đổi màu không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Are there any steps I should take?\", \"vi\": \"Có bước nào mà tôi nên thực hiện không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Also, I tried to use your secure page, but it gave me an error message saying that my account number was not valid.\", \"vi\": \"Ngoài ra, tôi đã thử truy cập trang bảo mật của quý vị, nhưng hệ thống đã hiển thị thông báo lỗi cho biết số tài khoản của tôi không hợp lệ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I will need your help in getting online access by the May 15 due date.\", \"vi\": \"Tôi cần sự giúp đỡ của quý vị để có thể truy cập trực tuyến trước hạn chót là ngày 15 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Thank you for any information you can provide.\", \"vi\": \"Xin chân thành cảm ơn quý vị về bất kỳ thông tin nào quý vị có thể cung cấp.\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Na-Ri Cam\", \"vi\": \"Hãy thưởng thức Cam\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"To: Na-Ri Cam\", \"vi\": \"Gửi: Na-Ri Cam\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"From: Customer Support\", \"vi\": \"Từ: Bộ phận Hỗ trợ Khách hàng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Date: March 18\", \"vi\": \"Ngày: 18 tháng 3\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Subject: RE: Account number DWS4289\", \"vi\": \"Chủ đề: RE: Số tài khoản DWS4289\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"E-Mail Message\", \"vi\": \"Thông điệp email\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Dear Ms. Cam,\", \"vi\": \"Kính gửi bà Cam,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Thank you for your message.\", \"vi\": \"Xin cảm ơn quý vị đã gửi tin nhắn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Your water might look cloudy on April 6 when you first turn on your faucets.\", \"vi\": \"Vào ngày 6 tháng 4, khi quý vị mở vòi nước lần đầu tiên, nước có thể trông đục.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"We recommend that you keep the water running until it is clear before you use it.\", \"vi\": \"Chúng tôi khuyên quý vị nên để nước chảy cho đến khi nước trong suốt rồi mới sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"I assure you that the water is not harmful in any way.\", \"vi\": \"Tôi xin cam đoan với quý vị rằng nước này hoàn toàn không gây hại dưới bất kỳ hình thức nào.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"The minerals that cause the discoloration occur naturally, and our latest water analysis showed very high quality.\", \"vi\": \"Các khoáng chất gây ra hiện tượng đổi màu này có nguồn gốc tự nhiên, và kết quả phân tích nước mới nhất của chúng tôi cho thấy chất lượng nước rất cao.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"I apologize for the problem you described.\", \"vi\": \"Tôi xin lỗi về sự cố mà quý vị đã mô tả.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 46, \"question_numbers\": []}, {\"en\": \"I have fixed it, so you should not have any further trouble.\", \"vi\": \"Tôi đã khắc phục xong vấn đề này, nên quý vị sẽ không còn gặp phải bất kỳ sự cố nào nữa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 47, \"question_numbers\": []}, {\"en\": \"If you have any other questions, please don’t hesitate to reach out to us again.\", \"vi\": \"Nếu quý vị còn bất kỳ thắc mắc nào khác, xin đừng ngần ngại liên hệ lại với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 48, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 49, \"question_numbers\": []}, {\"en\": \"Ramona Hizon\", \"vi\": \"Ramona Hizon\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 50, \"question_numbers\": []}, {\"en\": \"Customer Support, Dover Water Supply\", \"vi\": \"Bộ phận Hỗ trợ Khách hàng, Công ty Cấp nước Dover\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 51, \"question_numbers\": []}]' WHERE `id` = '54243e11-e0b8-4518-bf14-775576d5002b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Bethenie Industries guarantees that its products will function as ______[135] for at least one year from date of purchase.\", \"vi\": \"Bethenie Industries đảm bảo rằng các sản phẩm của mình sẽ hoạt động như ______[135] trong ít nhất một năm kể từ ngày mua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [135]}, {\"en\": \"______[136].\", \"vi\": \"______[136].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [136]}, {\"en\": \"This ______[137] applies only to products sold at Bethenie Industries stores and other licensed distributors.\", \"vi\": \"______[137] này chỉ áp dụng cho các sản phẩm được bán tại các cửa hàng của Bethenie Industries và các nhà phân phối được ủy quyền khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [137]}, {\"en\": \"Products that are found to be defective may be shipped to our address for repair or exchange.\", \"vi\": \"Những sản phẩm được phát hiện là bị lỗi có thể được gửi đến địa chỉ của chúng tôi để sửa chữa hoặc đổi mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Please note that products that are being returned because of damage should be shipped back to us, whenever possible, in their ______[138] packaging.\", \"vi\": \"Xin lưu ý rằng các sản phẩm đang được trả lại do bị hư hỏng nên được gửi trả lại cho chúng tôi, bất cứ khi nào có thể, trong bao bì ______[138] của chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [138]}]' WHERE `id` = '5425d58a-fca0-4fc8-b3ea-806230a38b5b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"July 11\", \"vi\": \"Ngày 11 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear Mr. Wong:\", \"vi\": \"Kính gửi ông Wong:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"It was good to speak with you today about the opening in the accounts receivable department at Riedeberg Realty.\", \"vi\": \"Thật tuyệt khi được trò chuyện với ông ngày hôm nay về vị trí còn trống trong bộ phận phải thu của công ty Riedeberg Realty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"______[135].\", \"vi\": \"______[135].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [135]}, {\"en\": \"My prior experience has prepared me particularly well for this ______[136].\", \"vi\": \"Kinh nghiệm trước đây của tôi đã giúp tôi chuẩn bị rất tốt cho ______[136] này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [136]}, {\"en\": \"Strong writing skills, assertiveness, and accuracy ______[137] in my last two jobs.\", \"vi\": \"Kỹ năng viết tốt, tính quyết đoán và sự chính xác ______[137] trong hai công việc gần đây nhất của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [137]}, {\"en\": \"I am also able to work effectively with coworkers, especially in a fast-paced environment.\", \"vi\": \"Tôi cũng có khả năng làm việc hiệu quả với các đồng nghiệp, đặc biệt là trong một môi trường có nhịp độ nhanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I appreciate the time you took to ______[138] me.\", \"vi\": \"Tôi đánh giá cao thời gian ông đã dành để ______[138] tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [138]}, {\"en\": \"I look forward to hearing from you when you make your final hiring decision.\", \"vi\": \"Tôi mong sớm nhận được phản hồi từ ông khi ông đưa ra quyết định tuyển dụng cuối cùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Jon Troughman\", \"vi\": \"Jon Troughman\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '542e14a5-ef20-4a44-b064-e81208dd87ee';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.nozawamotors.ca/newsroom\", \"vi\": \"http://www.nozawamotors.ca/newsroom\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The new Nozawa 10 is finally here!\", \"vi\": \"Mẫu Nozawa 10 mới cuối cùng cũng đã ra mắt!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We have made our dashboard navigation system fully voice enabled.\", \"vi\": \"Chúng tôi đã tích hợp đầy đủ tính năng điều khiển bằng giọng nói cho hệ thống điều hướng trên bảng điều khiển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"With our Nozawa Navigation Interface (NNI), drivers can stay focused on the road.\", \"vi\": \"Với Giao diện điều hướng Nozawa (NNI) của chúng tôi, các tài xế có thể tập trung hoàn toàn vào việc lái xe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We have also added cupholders between the front seats, enhanced the back-seat speakers, and expanded the cargo area by 29 liters.\", \"vi\": \"Chúng tôi cũng đã trang bị thêm các giá để cốc giữa hai ghế trước, nâng cấp hệ thống loa ở hàng ghế sau và mở rộng khoang chứa hành lý thêm 29 lít.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Check out our new model at your Nozawa Motors dealer, and let us know what you think!\", \"vi\": \"Hãy ghé thăm đại lý Nozawa Motors gần nhất để chiêm ngưỡng mẫu xe mới của chúng tôi và chia sẻ ý kiến của quý vị với chúng tôi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"About Nozawa\", \"vi\": \"Giới thiệu về Nozawa\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Newsroom\", \"vi\": \"Phòng Tin tức\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Forums\", \"vi\": \"Diễn đàn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Driver Stories\", \"vi\": \"Câu chuyện của các tài xế\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Do you have any comments, questions, or concerns?\", \"vi\": \"Quý vị có ý kiến, thắc mắc hay lo ngại nào không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I\'ve been a Nozawa customer for more than a decade, and I recently got a new Nozawa 10.\", \"vi\": \"Tôi đã là khách hàng của Nozawa hơn một thập kỷ nay, và gần đây tôi đã mua một chiếc Nozawa 10 mới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Overall, I am happy with my purchase, but I am not pleased with the new position of the cupholders.\", \"vi\": \"Nhìn chung, tôi hài lòng với món hàng mình đã mua, nhưng tôi không hài lòng với vị trí mới của các giá để cốc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Some air vents could have been placed there instead, and it would have made the heating and cooling system more efficient.\", \"vi\": \"Thay vào đó, lẽ ra có thể bố trí một số lỗ thông gió tại vị trí đó, và điều này sẽ giúp hệ thống sưởi ấm và làm mát hoạt động hiệu quả hơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Like other drivers, I too have had some problems with the NNI system.\", \"vi\": \"Cũng giống như các tài xế khác, tôi cũng đã gặp một số vấn đề với hệ thống NNI.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I do, however, really like being able to fit more in the trunk, and this model\'s acceleration power seems to have improved compared with previous models.\", \"vi\": \"Tuy nhiên, tôi thực sự thích việc có thể chứa được nhiều đồ hơn trong cốp xe, và khả năng tăng tốc của mẫu xe này dường như đã được cải thiện so với các mẫu xe trước đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"If you would like to receive a personal reply to your survey response, please enter your contact information.\", \"vi\": \"Nếu quý vị mong muốn nhận được phản hồi cá nhân về câu trả lời khảo sát của mình, xin vui lòng cung cấp thông tin liên hệ của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Name: Michelle Herrera E-mail address: mherrera@notezip.com\", \"vi\": \"Họ tên: Michelle Herrera Địa chỉ email: mherrera@notezip.com\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Memo\", \"vi\": \"Bộ nhớ\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: Tabitha Marks\", \"vi\": \"Từ: Tabitha Marks\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"To: Nozawa Service Center Managers\", \"vi\": \"Kính gửi: Các Trưởng Trung tâm Dịch vụ Nozawa\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subject: New release\", \"vi\": \"Chủ đề: Phiên bản mới\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"We received negative customer feedback about the new Nozawa 10 model\'s NNI system.\", \"vi\": \"Chúng tôi đã nhận được những phản hồi tiêu cực từ khách hàng về hệ thống NNI trên mẫu Nozawa 10 mới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"In response we have just released a new NNI software update that fixes the bugs.\", \"vi\": \"Để giải quyết vấn đề này, chúng tôi vừa phát hành bản cập nhật phần mềm NNI mới nhằm khắc phục các lỗi trên.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Please begin installing this update immediately to all current year Nozawa 10s that are brought to your shops for servicing.\", \"vi\": \"Kính mong quý vị bắt đầu cài đặt bản cập nhật này ngay lập tức cho tất cả các mẫu Nozawa 10 của năm nay được mang đến cửa hàng của quý vị để bảo dưỡng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"You can expect an increase in Nozawa 10s being brought in for service as we will be notifying all owners that this update is available.\", \"vi\": \"Quý vị có thể dự kiến số lượng xe Nozawa 10 được mang đến bảo dưỡng sẽ tăng lên, bởi chúng tôi sẽ thông báo cho tất cả các chủ sở hữu về việc bản cập nhật này đã có sẵn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '54e4a6c7-9029-4025-96e5-5b5b3f645fc5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Popular TV Show Returns for Third Season\", \"vi\": \"Chương trình truyền hình nổi tiếng trở lại với mùa thứ ba\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Sunday marks the start of the third season of the award-winning TV series King of the Meer.\", \"vi\": \"Chủ nhật đánh dấu sự khởi đầu của mùa thứ ba của bộ phim truyền hình đoạt giải thưởng King of the Meer.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This political thriller ------- (135) on the book Whispered Illusions by Noriaki Arishima.\", \"vi\": \"Bộ phim giật gân chính trị này ------- (135) dựa trên cuốn sách Whispered Illusions của tác giả Noriaki Arishima.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"Some reviewers of the television series believe that the third season might be even better than the previous ones.\", \"vi\": \"Một số nhà phê bình của series truyền hình tin rằng mùa thứ ba có thể thậm chí còn hay hơn các mùa trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"------- (136), other reviewers argue that the series might lose its appeal with the introduction of so many new characters, resulting in a complicated and confusing plotline.\", \"vi\": \"------- (136), các nhà phê bình khác lại lập luận rằng series có thể mất đi sức hút khi giới thiệu quá nhiều nhân vật mới, dẫn đến cốt truyện phức tạp và khó hiểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [136]}, {\"en\": \"Director Amber Randolph has responded to that ------- (137).\", \"vi\": \"Đạo diễn Amber Randolph đã phản hồi về ------- (137) đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [137]}, {\"en\": \"\\\"The abundance of new characters can make the story challenging to follow,\\\" she said.\", \"vi\": \"Bà cho biết: \\\"Sự xuất hiện quá nhiều nhân vật mới có thể khiến câu chuyện trở nên khó theo dõi.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"\\\"------- (138).\", \"vi\": \"------- (138).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [138]}, {\"en\": \"We\'ll see what the fans of the show think.\\\"\", \"vi\": \"Chúng ta hãy chờ xem người hâm mộ chương trình nghĩ gì.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '54e69fd9-20f3-4eab-accc-3495a4dfafe9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Michael Hong <mhong73@mailcrate.co.uk>\", \"vi\": \"Gửi tới: Michael Hong <mhong73@mailcrate.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Customer Support <support@toppmanagement.co.uk>\", \"vi\": \"Từ: Bộ phận Hỗ trợ Khách hàng <support@toppmanagement.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 20 June\", \"vi\": \"Ngày: 20 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Your account access\", \"vi\": \"Chủ đề: Quyền truy cập tài khoản của quý vị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Topp Management User Guidelines\", \"vi\": \"Tài liệu đính kèm: Hướng dẫn sử dụng dành cho Ban Lãnh đạo Cấp cao\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Hong:\", \"vi\": \"Kính gửi ông Hồng:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It appears you have not logged in to your Topp Management online app recently.\", \"vi\": \"Có vẻ như quý vị đã lâu không đăng nhập vào ứng dụng trực tuyến Topp Management của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"After six months of inactivity, user accounts are automatically closed.\", \"vi\": \"Sau sáu tháng không hoạt động, các tài khoản người dùng sẽ tự động bị đóng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"To avoid account deactivation on 20 July, simply sign in to the app before that date.\", \"vi\": \"Để tránh việc tài khoản bị vô hiệu hóa vào ngày 20 tháng 7, quý vị chỉ cần đăng nhập vào ứng dụng trước ngày đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"If you have forgotten your password or are having difficulty accessing your account, please see the attached Topp Management User Guidelines.\", \"vi\": \"Nếu quý vị quên mật khẩu hoặc gặp khó khăn khi truy cập tài khoản của mình, xin vui lòng tham khảo “Hướng dẫn sử dụng Topp Management” đính kèm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Thousands use our award-winning Topp Management app for managing their project workflows.\", \"vi\": \"Hàng nghìn người đang sử dụng ứng dụng Topp Management từng đoạt giải thưởng của chúng tôi để quản lý quy trình làm việc trong các dự án của họ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We trust you will continue as a valued user.\", \"vi\": \"Chúng tôi tin tưởng rằng quý vị sẽ tiếp tục là một người dùng quý báu của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Feel free to contact our customer support team if there is any way we can serve you.\", \"vi\": \"Nếu có bất kỳ điều gì chúng tôi có thể hỗ trợ quý khách, xin vui lòng liên hệ với đội ngũ chăm sóc khách hàng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The Topp Management Support Team\", \"vi\": \"Đội ngũ Hỗ trợ Quản lý Cấp cao của Topp\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '54f4548c-7a05-4a1b-848e-95d7a80eeada';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Kele Tso <k.tso@faeberelectric.com>\", \"vi\": \"Gửi tới: Kele Tso <k.tso@faeberelectric.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Connie Watkins <c.watkins@faeberelectric.com>\", \"vi\": \"Từ: Connie Watkins <c.watkins@faeberelectric.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 13\", \"vi\": \"Ngày: 13 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: RE: Employee handbook\", \"vi\": \"Chủ đề: RE: Sổ tay nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"This e-mail is being sent to all employees who have not yet signed the Faeber Electric Employee Handbook acceptance page.\", \"vi\": \"Thư điện tử này được gửi đến tất cả các nhân viên chưa ký vào trang xác nhận đã đọc và chấp nhận Sổ tay Nhân viên của Faeber Electric.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Acceptance of the terms is required of all employees and was requested in an e-mail I sent on May 1.\", \"vi\": \"Tất cả nhân viên đều phải chấp nhận các điều khoản này, và tôi đã yêu cầu điều đó trong một email mà tôi đã gửi vào ngày 1 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Failure to sign the form may result in delayed salary payments.\", \"vi\": \"Việc không ký vào mẫu đơn này có thể dẫn đến việc chậm trễ trong việc chi trả lương.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The Faeber Electric Employee Handbook and the signature page are available at faeberelectric.com/handbook.\", \"vi\": \"Sổ tay Nhân viên của Faeber Electric và trang ký tên có thể được truy cập tại địa chỉ faeberelectric.com/handbook.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"A chart summarizing the key points in the handbook is also available on that site.\", \"vi\": \"Trên trang web đó cũng có sẵn một biểu đồ tóm tắt những điểm chính trong cuốn cẩm nang.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"If you have any questions, please contact your manager or reach out directly to me.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào, xin vui lòng liên hệ với người quản lý của quý vị hoặc liên hệ trực tiếp với tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Connie Watkins\", \"vi\": \"Connie Watkins\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Human Resources Officer\", \"vi\": \"Chuyên viên Nhân sự\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '54f5bd33-e9e2-44ad-b2bf-8d4d0a37caf2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Merenville Regional Bus Authority\\nNotice to the Public\", \"vi\": \"Cơ quan Quản lý Xe buýt Khu vực Merenville\\nThông báo đến công chúng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"In response to its recently conducted passenger survey, the Merenville Regional Bus Authority (MRBA) will be adjusting its Saturday and Sunday service between Merenville Central Station (MCS) and Louberg.\", \"vi\": \"Dựa trên kết quả cuộc khảo sát hành khách vừa được tiến hành gần đây, Cơ quan Vận tải Xe buýt Khu vực Merenville (MRBA) sẽ điều chỉnh lịch trình phục vụ vào thứ Bảy và Chủ Nhật trên tuyến giữa Trạm Trung tâm Merenville (MCS) và Louberg.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The following schedule changes will be in effect as of May 1.\", \"vi\": \"Các thay đổi về lịch trình sau đây sẽ có hiệu lực kể từ ngày 1 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Bus 36, in service on Saturdays only, will be departing MCS every hour on the hour, with the first departure scheduled for 6:00 A.M. and the last to take place at midnight.\", \"vi\": \"Xe buýt số 36, chỉ hoạt động vào các ngày thứ Bảy, sẽ khởi hành từ MCS mỗi giờ một chuyến vào đúng giờ, với chuyến đầu tiên dự kiến khởi hành lúc 6 giờ sáng và chuyến cuối cùng vào lúc nửa đêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"This adjustment is intended to provide passengers with more departure options.\", \"vi\": \"Sự điều chỉnh này nhằm mang đến cho hành khách nhiều lựa chọn khởi hành hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Bus 47, which runs on both days, will now be departing MCS at 7:00 A.M. in addition to its regularly scheduled departure times of 12:15 P.M. and 6:15 P.M.\", \"vi\": \"Tuyến xe buýt số 47, hoạt động vào cả hai ngày, giờ đây sẽ khởi hành từ MCS lúc 7 giờ sáng, bên cạnh các khung giờ khởi hành theo lịch trình thường lệ là 12 giờ 15 phút trưa và 6 giờ 15 phút chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Bus 51, which runs on both days, will continue to have three departures from MCS.\", \"vi\": \"Tuyến xe buýt số 51, hoạt động trong cả hai ngày, sẽ tiếp tục có ba chuyến khởi hành từ MCS.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"However, they are now scheduled to take place at 7:30 A.M., 1:30 P.M., and 4:30 P.M.\", \"vi\": \"Tuy nhiên, hiện tại các buổi này dự kiến sẽ diễn ra vào lúc 7 giờ 30 sáng, 1 giờ 30 chiều và 4 giờ 30 chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Bus 65, in service on Sundays only, will now be departing MCS at 10:00 A.M. instead of 8:00 A.M. Departures scheduled for 1:00 P.M., 3:00 P.M., and 5:00 P.M. remain unchanged.\", \"vi\": \"Tuyến xe buýt số 65, chỉ hoạt động vào các ngày Chủ nhật, từ nay sẽ khởi hành từ MCS vào lúc 10 giờ sáng thay vì 8 giờ sáng. Các chuyến xe dự kiến khởi hành vào lúc 1 giờ chiều, 1 giờ chiều và 5 giờ chiều vẫn giữ nguyên như cũ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To: Adriano Martinez <amartinez@mrba.com>\", \"vi\": \"Gửi tới: Adriano Martinez <amartinez@mrba.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"From: Claire Brunkhorst <cbrunkhorst@mrba.com>\", \"vi\": \"Từ: Claire Brunkhorst <cbrunkhorst@mrba.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Date: May 14\", \"vi\": \"Ngày: 14 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Re: Switch shift request\", \"vi\": \"Trả lời: Yêu cầu đổi ca\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Hi Adriano,\", \"vi\": \"Xin chào Adriano,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Regarding your request, I can take over your late-night bus driving shift on Saturday, May 22.\", \"vi\": \"Về yêu cầu của quý vị, tôi có thể thay quý vị đảm nhận ca lái xe buýt đêm vào thứ Bảy, ngày 22 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I realize that I’ll have to be alert, so I’ll make sure to get plenty of rest.\", \"vi\": \"Tôi nhận thức được rằng mình sẽ phải luôn tỉnh táo, vì vậy tôi sẽ đảm bảo nghỉ ngơi đầy đủ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"In return, could you possibly take over my day shift on Tuesday, May 25?\", \"vi\": \"Đổi lại, liệu anh/chị có thể thay tôi làm ca ngày vào thứ Ba, ngày 25 tháng 5 được không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"A friend of mine, who works for the same Chicago-based company that I used to work for, will be visiting me that day.\", \"vi\": \"Một người bạn của tôi, hiện đang làm việc tại cùng công ty có trụ sở tại Chicago mà tôi từng làm việc, sẽ đến thăm tôi vào ngày hôm đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thanks in advance for your assistance.\", \"vi\": \"Xin chân thành cảm ơn sự hỗ trợ của quý vị ngay từ trước.\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Claire Brunkhorst, MRBA Associate\", \"vi\": \"Bà Claire Brunkhorst, Chuyên viên MRBA\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '54f669ee-9bdd-4b70-9e96-8606ba85c43f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Kamini Das <k.das@armail.net>\", \"vi\": \"Gửi tới: Kamini Das <k.das@armail.net>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Customer Service <customerservice@sandringsuites.com.au>\", \"vi\": \"Từ: Bộ phận Dịch vụ Khách hàng <customerservice@sandringsuites.com.au>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 7 February\", \"vi\": \"Ngày: 7 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Regarding your visit\", \"vi\": \"Chủ đề: Liên quan đến chuyến thăm của quý vị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Das,\", \"vi\": \"Kính gửi bà Das,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for your recent stay with us at Sandring Suites.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã lựa chọn lưu trú tại Sandring Suites trong thời gian vừa qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our top priority is to provide our guests with an exceptional experience.\", \"vi\": \"Ưu tiên hàng đầu của chúng tôi là mang đến cho quý khách một trải nghiệm tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We ask that you complete a three-minute survey to rate your time with us.\", \"vi\": \"Chúng tôi kính mong quý vị dành ba phút để hoàn thành bản khảo sát nhằm đánh giá trải nghiệm của quý vị khi sử dụng dịch vụ của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please visit www.sandringsuites.com.au and click the survey link in the top right corner of the Web page.\", \"vi\": \"Kính mời quý vị truy cập trang www.sandringsuites.com.au và nhấp vào liên kết khảo sát ở góc trên bên phải của trang web.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Use code SAN5341 to complete the survey.\", \"vi\": \"Vui lòng sử dụng mã SAN5341 để hoàn thành bản khảo sát.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To thank you for participating, we will enter your name in our monthly raffle to win a complimentary two-night stay at one of our hotels.\", \"vi\": \"Để tri ân sự tham gia của quý khách, chúng tôi sẽ đưa tên quý khách vào danh sách bốc thăm hàng tháng để có cơ hội trúng thưởng một kỳ nghỉ miễn phí hai đêm tại một trong các khách sạn của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Silvia Monier\", \"vi\": \"Silvia Monier\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Customer Service, Sandring Suites\", \"vi\": \"Bộ phận Dịch vụ Khách hàng, Sandring Suites\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '55a94562-9299-4a05-9bc1-ac9d2de390c1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"We are delighted that you are joining us for today\'s event.\", \"vi\": \"Chúng tôi rất vui mừng khi quý vị tham dự sự kiện hôm nay cùng chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"— [1] — We ask that you adhere to the following guidelines to ensure that all attendees have an enjoyable experience.\", \"vi\": \"— [1] — Chúng tôi mong quý vị tuân thủ các hướng dẫn sau đây để đảm bảo tất cả các đại biểu đều có một trải nghiệm thú vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Upon entering the venue, please put any and all electronic devices in silent mode.\", \"vi\": \"Khi vào địa điểm tổ chức, xin vui lòng chuyển tất cả các thiết bị điện tử sang chế độ im lặng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Ringtones and lit screens are very distracting to both the performers and your fellow audience members.\", \"vi\": \"Tiếng chuông điện thoại và màn hình sáng gây mất tập trung rất nhiều cho cả các nghệ sĩ biểu diễn lẫn những khán giả khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [2] — Moreover, audience members are not allowed to make an audio or visual recording of the performance.\", \"vi\": \"— [2] — Hơn nữa, khán giả không được phép ghi âm hoặc ghi hình buổi biểu diễn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Bags and other items in the aisles pose a safety concern.\", \"vi\": \"Các túi xách và các vật dụng khác để trong lối đi gây ra những lo ngại về an toàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [3] — If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2.\", \"vi\": \"— [3] — Nếu hành lý của quý vị quá lớn để đặt vừa dưới ghế, quý vị nên cân nhắc gửi nó vào tủ khóa với mức phí chỉ 2 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [4] — One of our attendants will gladly assist you with that.\", \"vi\": \"— [4] — Một trong các nhân viên phục vụ của chúng tôi sẽ rất hân hạnh được hỗ trợ quý khách trong việc này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Thank you for your cooperation.\", \"vi\": \"Xin chân thành cảm ơn sự hợp tác của quý vị.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '55bd6bd3-a79c-45da-9536-6460674e4bc1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://carinasolutions.com/home\", \"vi\": \"https://carinasolutions.com/home\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Home - Services - Contact Us - Reviews\", \"vi\": \"Trang chủ - Dịch vụ - Liên hệ với chúng tôi - Đánh giá\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Carina Solutions\", \"vi\": \"Carina Solutions\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The Best Software Option for Hotel Management\", \"vi\": \"Giải pháp phần mềm tối ưu nhất cho quản lý khách sạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We will help you manage all aspects of your hotel.\", \"vi\": \"Chúng tôi sẽ hỗ trợ quý vị quản lý mọi khía cạnh hoạt động của khách sạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Whether you need help with your reservation system, managing staff, or improving your advertising and online presence, our software will work for you!\", \"vi\": \"Dù quý vị cần hỗ trợ về hệ thống đặt chỗ, quản lý nhân viên hay cải thiện chiến lược quảng cáo và sự hiện diện trực tuyến, phần mềm của chúng tôi sẽ đáp ứng mọi nhu cầu của quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Here are just a few of the tasks our software can do.\", \"vi\": \"Dưới đây là một số tác vụ mà phần mềm của chúng tôi có thể thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Manage online bookings and payments\", \"vi\": \"Quản lý các đặt chỗ và thanh toán trực tuyến\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Track staff hours and vacation time\", \"vi\": \"Theo dõi số giờ làm việc và thời gian nghỉ phép của nhân viên\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Promote your hotel on top booking Web sites\", \"vi\": \"Quảng bá khách sạn của quý vị trên các trang web đặt phòng hàng đầu\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Manage property maintenance\", \"vi\": \"Quản lý công tác bảo trì bất động sản\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Contact us today to begin using the trial version of our software completely free for three months.\", \"vi\": \"Hãy liên hệ với chúng tôi ngay hôm nay để bắt đầu sử dụng phiên bản dùng thử phần mềm của chúng tôi hoàn toàn miễn phí trong ba tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"More information about the pricing and features of the Premier software version can be found on the Services page of our Web site.\", \"vi\": \"Quý vị có thể tìm thêm thông tin về giá cả và các tính năng của phiên bản phần mềm Premier tại trang Dịch vụ trên trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"https://carinasolutions.com/reviews\", \"vi\": \"https://carinasolutions.com/reviews\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Home - Services - Contact Us - Reviews\", \"vi\": \"Trang chủ - Dịch vụ - Liên hệ với chúng tôi - Đánh giá\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"My trial version of the Carina Solutions hotel management software expires tomorrow, and I have to decide whether to purchase the Premier version or search for something better.\", \"vi\": \"Phiên bản dùng thử phần mềm quản lý khách sạn Carina Solutions của tôi sẽ hết hạn vào ngày mai, và tôi phải quyết định xem nên mua phiên bản Premier hay tìm kiếm một giải pháp tốt hơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I have two main concerns.\", \"vi\": \"Tôi có hai vấn đề chính cần quan tâm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The reservations module does not allow you to keep information about repeat guests on file.\", \"vi\": \"Mô-đun đặt phòng không cho phép quý vị lưu trữ thông tin về những khách quen trong hệ thống.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"This forces staff to reenter repeat customers’ information manually, which wastes time.\", \"vi\": \"Điều này buộc nhân viên phải nhập lại thông tin của khách hàng thân thiết bằng tay, dẫn đến lãng phí thời gian.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"The software offers full functionality only when accessed on a desktop computer, which is unfortunate because I do almost everything on my mobile phone.\", \"vi\": \"Phần mềm này chỉ cung cấp đầy đủ các tính năng khi được truy cập trên máy tính để bàn, điều này thật đáng tiếc vì tôi thực hiện hầu hết mọi việc trên điện thoại di động của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"The interface should be the same no matter what device you use.\", \"vi\": \"Giao diện sẽ giống nhau bất kể quý vị sử dụng thiết bị nào.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"—Submitted by Susan Yan\", \"vi\": \"—Được gửi bởi Susan Yan\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"https://carinasolutions.com/reviews_response\", \"vi\": \"https://carinasolutions.com/reviews_response\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Home - Services - Contact Us - Reviews\", \"vi\": \"Trang chủ - Dịch vụ - Liên hệ với chúng tôi - Đánh giá\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Dear Ms. Yan,\", \"vi\": \"Kính gửi bà Yan,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Good news!\", \"vi\": \"Tin vui!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"We have updated some features of Carina Solutions since you began your trial subscription.\", \"vi\": \"Kể từ khi quý vị bắt đầu sử dụng gói đăng ký dùng thử, chúng tôi đã cập nhật một số tính năng của Carina Solutions.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"There is now an automatic rebooking feature that you can use to register repeat guests, cutting down on manual data entry.\", \"vi\": \"Hiện nay đã có tính năng đặt lại phòng tự động mà quý vị có thể sử dụng để đăng ký cho những khách quen, giúp giảm bớt công việc nhập liệu thủ công.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Additionally, you should know that one of the differences between the trial version and the Premier version is that the interfaces are the same across all devices.\", \"vi\": \"Ngoài ra, quý vị cần lưu ý rằng một trong những điểm khác biệt giữa phiên bản dùng thử và phiên bản Premier là giao diện được thiết kế thống nhất trên tất cả các thiết bị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Remember, Carina Solutions hotel management software is more than just a booking tool.\", \"vi\": \"Xin lưu ý rằng, phần mềm quản lý khách sạn Carina Solutions không chỉ đơn thuần là một công cụ đặt phòng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Learning about all the features in the Premier version can help you fill your hotel with happy customers.\", \"vi\": \"Việc tìm hiểu về tất cả các tính năng trong phiên bản Premier có thể giúp quý vị thu hút nhiều khách hàng hài lòng đến với khách sạn của mình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Make sure to visit carinasolutions.com to see our instructional videos.\", \"vi\": \"Xin vui lòng truy cập trang web carinasolutions.com để xem các video hướng dẫn của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Marcus Feldman\", \"vi\": \"Marcus Feldman\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Carina Solutions representative\", \"vi\": \"Đại diện của Carina Solutions\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '55f8355c-3cfd-48ba-8b41-819bf8ce4e1e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Film Festival Returns to Wales\", \"vi\": \"Liên hoan phim trở lại xứ Wales\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"SWANSEA (24 May)—The Penglais Film Festival returns to town with a full slate of exciting new films.\", \"vi\": \"SWANSEA (ngày 24 tháng 5) — Liên hoan phim Penglais trở lại thành phố với một danh sách đầy đủ các bộ phim mới hấp dẫn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The festival has gained international recognition for the talent it has attracted over the years.\", \"vi\": \"Lễ hội này đã nhận được sự công nhận quốc tế nhờ những tài năng mà nó đã thu hút được trong suốt nhiều năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"It also boasts of having launched the careers of a growing number of celebrity filmmakers.\", \"vi\": \"Nơi đây còn tự hào vì đã góp phần mở đường cho sự nghiệp của ngày càng nhiều nhà làm phim nổi tiếng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The week-long festival will run from 9 to 15 August and will feature animated, documentary, and feature films.\", \"vi\": \"Lễ hội kéo dài một tuần này sẽ diễn ra từ ngày 9 đến ngày 15 tháng 8 và sẽ trình chiếu các bộ phim hoạt hình, phim tài liệu và phim truyện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The festival is open to the public, with the exception of the closing event on 15 August, which is by invitation only.\", \"vi\": \"Lễ hội mở cửa cho công chúng tham dự, ngoại trừ sự kiện bế mạc vào ngày 15 tháng 8, chỉ dành cho những khách mời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Tickets for all public events must be purchased in advance and are expected to sell out quickly.\", \"vi\": \"Vé tham dự tất cả các sự kiện dành cho công chúng đều phải được mua trước và dự kiến sẽ nhanh chóng được bán hết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Ticket sales will begin at 10 a.m. on 3 June.\", \"vi\": \"Việc bán vé sẽ bắt đầu vào lúc 10 giờ sáng ngày 3 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please note that tickets for individual film showings must be purchased separately.\", \"vi\": \"Xin lưu ý rằng vé cho từng buổi chiếu phim phải được mua riêng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"A full schedule of screenings is now available on the festival\'s Web site at www.penglaisfest.co.uk.\", \"vi\": \"Lịch chiếu chi tiết hiện đã được đăng tải trên trang web của liên hoan phim tại địa chỉ www.penglaisfest.co.uk.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To: Desmond Griffith <d_griffith@docsnow.co.uk>\", \"vi\": \"Gửi tới: Desmond Griffith <d_griffith@docsnow.co.uk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"From: Ioan Driscoll <ioan.driscoll@penglaisfest.co.uk>\", \"vi\": \"Từ: Ioan Driscoll <ioan.driscoll@penglaisfest.co.uk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Subject: Re: Penglais Award Ceremony\", \"vi\": \"Chủ đề: Trả lời: Lễ trao giải Penglais\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: 28 May\", \"vi\": \"Ngày: 28 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Dear Mr. Griffith,\", \"vi\": \"Kính gửi ông Griffith,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I am excited and honoured to hear that you will be able to accept your prize in person at this year\'s Penglais Award Ceremony.\", \"vi\": \"Tôi rất vui mừng và vinh dự khi được biết quý vị sẽ có thể trực tiếp nhận giải thưởng tại Lễ trao giải Penglais năm nay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The ceremony will take place at the Wynford Blue Hotel at 5 P.M. on Friday, 15 August.\", \"vi\": \"Buổi lễ sẽ diễn ra tại Khách sạn Wynford Blue vào lúc 5 giờ chiều thứ Sáu, ngày 15 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"You will be introduced by the festival\'s president, Ms. Sarah Wu, and you will have the opportunity to give a speech.\", \"vi\": \"Quý vị sẽ được Chủ tịch Liên hoan, bà Sarah Wu, giới thiệu và sẽ có cơ hội phát biểu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We kindly request that you limit this speech to no more than 10 minutes.\", \"vi\": \"Chúng tôi kính mong quý vị giới hạn thời lượng bài phát biểu này không quá 10 phút.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Please provide me with the e-mail addresses of up to five guests you would like to invite to the ceremony.\", \"vi\": \"Kính mong quý vị cung cấp cho tôi địa chỉ email của tối đa năm vị khách mà quý vị muốn mời tham dự buổi lễ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I will be sure to send them each a link to download their ticket electronically within ten days of the event.\", \"vi\": \"Tôi sẽ đảm bảo gửi cho từng người một liên kết để tải vé điện tử trong vòng mười ngày kể từ ngày diễn ra sự kiện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Congratulations,\", \"vi\": \"Xin chúc mừng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Ioan Driscoll\", \"vi\": \"Ioan Driscoll\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"5:00 P.M. - Doors open\", \"vi\": \"17 giờ - Mở cửa\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"5:30 P.M. - Dinner service begins\", \"vi\": \"17 giờ 30 – Bắt đầu phục vụ bữa tối\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"6:00 P.M. - Performance by Shirley Finch, accompanied by Dom Lucas on piano\", \"vi\": \"18 giờ - Buổi biểu diễn của Shirley Finch, với phần đệm piano của Dom Lucas\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"6:15 P.M. - Presentation of Excellence in Acting awards\", \"vi\": \"18 giờ 15 phút – Lễ trao giải “Diễn xuất xuất sắc”\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"6:30 P.M. - Presentation of Achievement in Direction awards\", \"vi\": \"18 giờ 30 – Lễ trao giải Thành tựu trong lĩnh vực Đạo diễn\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"6:45 P.M. - Presentation of Best Cinematography award\", \"vi\": \"18 giờ 45 phút – Lễ trao giải “Quay phim xuất sắc nhất”\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"7:00 P.M. - Introduction of Lifetime Achievement Award by Ms. Sarah Wu\", \"vi\": \"19 giờ 00 – Bà Sarah Wu giới thiệu Giải thưởng Thành tựu Trọn đời\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"7:10 P.M. - Speech by Lifetime Achievement Award Recipient\", \"vi\": \"19 giờ 10 - Bài phát biểu của người nhận Giải thưởng Thành tựu Trọn đời\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"7:20 P.M. - Closing remarks\", \"vi\": \"19 giờ 20 - Phát biểu bế mạc\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"7:30 P.M. - Final performance by Shirley Finch, solo\", \"vi\": \"19 giờ 30 – Buổi biểu diễn cuối cùng của Shirley Finch, phần trình diễn độc tấu\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"The 25th Annual Penglais Film Festival Awards Ceremony\\nEvent Program\", \"vi\": \"Lễ trao giải Liên hoan phim Penglais lần thứ 25\\nChương trình sự kiện\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '5600b580-e1a1-499a-9c73-7010b92e0a53';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Oak Lane Fashion cashiers\", \"vi\": \"Kính gửi: Các nhân viên thu ngân của Oak Lane Fashion\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Jane Benson\", \"vi\": \"Từ: Jane Benson\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: July 8\", \"vi\": \"Ngày: 8 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Update\", \"vi\": \"Chủ đề: Cập nhật\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Beginning August 1, Oak Lane Fashion will only accept returns or exchanges of unworn and undamaged clothing that has the original receipt.\", \"vi\": \"Kể từ ngày 1 tháng 8, Oak Lane Fashion sẽ chỉ chấp nhận trả hàng hoặc đổi hàng đối với các sản phẩm quần áo chưa qua sử dụng, còn nguyên vẹn và có hóa đơn gốc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This information will be posted at all checkout counters by next week.\", \"vi\": \"Thông tin này sẽ được niêm yết tại tất cả các quầy thanh toán vào tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We will also send an e-mail to our existing customers so that they are aware of the new rule.\", \"vi\": \"Chúng tôi cũng sẽ gửi email đến các khách hàng hiện tại để quý vị được biết về quy định mới này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If a customer wishes to make a return without a receipt, please call the manager on duty for assistance.\", \"vi\": \"Nếu quý khách muốn đổi trả hàng mà không có hóa đơn, xin vui lòng liên hệ với quản lý trực ca để được hỗ trợ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Thanks for your help.\", \"vi\": \"Xin cảm ơn sự giúp đỡ của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Jane Benson\", \"vi\": \"Jane Benson\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Director of Operations\", \"vi\": \"Giám đốc Điều hành\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '5610b9d4-e585-4762-bcb1-b3f9039fc37d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Department Managers <managementteam@a-qualityelectronics.com>\", \"vi\": \"Kính gửi: Các Trưởng phòng <managementteam@a-qualityelectronics.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Eileen Wrenn <ewrenn@a-qualityelectronics.com>\", \"vi\": \"Từ: Eileen Wrenn <ewrenn@a-qualityelectronics.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: October 7\", \"vi\": \"Ngày: 7 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Upcoming visit with Kenji Tanaka\", \"vi\": \"Chủ đề: Chuyến thăm sắp tới với ông Kenji Tanaka\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Draft schedule\", \"vi\": \"Tài liệu đính kèm: 📎 Dự thảo lịch trình\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Good morning,\", \"vi\": \"Xin chào buổi sáng,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Mr. Harlington has asked me to let all department managers know that Kenji Tanaka, the chief operating officer of our Japanese subsidiary Kanazawa Electronics, will be visiting our corporate headquarters next week.\", \"vi\": \"Ông Harlington đã nhờ tôi thông báo đến tất cả các trưởng phòng rằng ông Kenji Tanaka, Giám đốc điều hành của công ty con tại Nhật Bản của chúng ta là Kanazawa Electronics, sẽ đến thăm trụ sở chính của công ty vào tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please let me know as soon as possible whether you will be able to attend the afternoon meeting and dinner on October 14 so I can make the appropriate arrangements.\", \"vi\": \"Xin vui lòng cho tôi biết càng sớm càng tốt liệu quý vị có thể tham dự cuộc họp buổi chiều và bữa tối vào ngày 14 tháng 10 hay không, để tôi có thể tiến hành các công tác chuẩn bị phù hợp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"A draft schedule is attached to this e-mail.\", \"vi\": \"Bản dự thảo lịch trình được đính kèm trong email này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Mr. Tanaka will take the distinguished visitor slot, which Mr. Harlington created last quarter in an effort to reinvigorate our corporate culture.\", \"vi\": \"Ông Tanaka sẽ đảm nhận vị trí “Khách mời danh dự” — vị trí mà ông Harlington đã thiết lập vào quý trước nhằm thổi luồng sinh khí mới vào văn hóa doanh nghiệp của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Departmental reports will begin promptly at 3:00 P.M., following the presentations by Mr. Harlington and Mr. Tanaka, respectively.\", \"vi\": \"Các báo cáo của các phòng ban sẽ bắt đầu đúng 3 giờ chiều, ngay sau phần trình bày của ông Harlington và ông Tanaka.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Details will be announced soon regarding the information that department managers will present in their status reports.\", \"vi\": \"Thông tin chi tiết về nội dung mà các trưởng phòng sẽ trình bày trong các báo cáo tình hình sẽ được công bố trong thời gian tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Eileen Wrenn, Executive Assistant\", \"vi\": \"Bà Eileen Wrenn, Trợ lý điều hành\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"12:00–1:00 P.M. - All staff - Catered lunch\", \"vi\": \"12:00–13:00 – Toàn thể nhân viên – Bữa trưa do nhà hàng phục vụ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"1:00–2:00 P.M. - President - Discussion of company goals and performance objectives; status of joint projects\", \"vi\": \"13:00–14:00 - Chủ tịch - Thảo luận về các mục tiêu của công ty và chỉ tiêu hiệu quả hoạt động; tình hình triển khai các dự án hợp tác\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"2:00–3:00 P.M. - Distinguished visitor - Update on Kanazawa Electronics: operational successes and challenges faced by the subsidiary in the third quarter\", \"vi\": \"14:00–15:00 - Khách mời danh dự - Báo cáo cập nhật về Kanazawa Electronics: những thành công trong hoạt động và những thách thức mà công ty con phải đối mặt trong quý III\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"3:00–5:00 P.M. - Department managers - Departmental reports: agenda to be determined\", \"vi\": \"15:00–17:00 – Các trưởng phòng – Báo cáo của các phòng ban: chương trình nghị sự sẽ được xác định sau\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"6:00–9:00 P.M. - All staff - Dinner at Mapleton Grill, downtown Mapleton\", \"vi\": \"18:00–21:00 – Toàn thể nhân viên – Bữa tối tại Mapleton Grill, trung tâm thành phố Mapleton\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"DRAFT SCHEDULE\", \"vi\": \"DỰ THẢO LỊCH TRÌNH\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"A-Quality Electronics Quarterly Meeting\", \"vi\": \"Cuộc họp quý của Công ty A-Quality Electronics\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Monday, October 14\", \"vi\": \"Thứ Hai, ngày 14 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"To: Eileen Wrenn <ewrenn@a-qualityelectronics.com>\", \"vi\": \"Gửi: Eileen Wrenn <ewrenn@a-qualityelectronics.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"From: Deborah Powell <dpowell@a-qualityelectronics.com>\", \"vi\": \"Từ: Deborah Powell <dpowell@a-qualityelectronics.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Date: October 7\", \"vi\": \"Ngày: 7 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Subject: Re: Upcoming visit with Kenji Tanaka\", \"vi\": \"Chủ đề: Trả lời: Chuyến thăm sắp tới với ông Kenji Tanaka\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Hi Eileen,\", \"vi\": \"Xin chào Eileen,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I\'m confirming my availability for the meeting with Kenji Tanaka.\", \"vi\": \"Tôi xin xác nhận rằng tôi có thể tham dự cuộc họp với ông Kenji Tanaka.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I plan to update the executives on the marketing team\'s activities for the third quarter.\", \"vi\": \"Tôi dự định sẽ báo cáo với các lãnh đạo về các hoạt động của đội ngũ tiếp thị trong quý thứ ba.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Question: do you think Mr. Tanaka might like to go to a baseball game after dinner?\", \"vi\": \"Câu hỏi: Quý vị có nghĩ rằng ông Tanaka có thể muốn đi xem một trận bóng chày sau bữa tối không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"He enjoyed seeing the Mapleton Ospreys play after he attended the second quarter meeting in July.\", \"vi\": \"Sau khi tham dự cuộc họp quý II vào tháng 7, ông rất hào hứng được xem đội Mapleton Ospreys thi đấu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"The only problem is that all games in October begin at 8:00 P.M., so we would need to begin dinner at around 5:00 P.M. That would give us enough time to get to the stadium before the game starts.\", \"vi\": \"Vấn đề duy nhất là tất cả các trận đấu trong tháng 10 đều bắt đầu lúc 8 giờ tối, vì vậy chúng ta sẽ cần bắt đầu bữa tối vào khoảng 5 giờ chiều. Như vậy, chúng ta sẽ có đủ thời gian để đến sân vận động trước khi trận đấu bắt đầu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I know this is a lot to ask for, but I think it is worth considering, knowing how much our distinguished visitor enjoyed the Ospreys game and how important he is to the company.\", \"vi\": \"Tôi biết đây là một yêu cầu khá lớn, nhưng tôi cho rằng điều này đáng để cân nhắc, nhất là khi biết vị khách quý của chúng ta đã rất thích trận đấu của đội Ospreys và ông ấy có vai trò quan trọng như thế nào đối với công ty.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Let me know what you think so I can secure tickets before his visit.\", \"vi\": \"Xin vui lòng cho tôi biết ý kiến của quý vị để tôi có thể đặt vé trước khi anh ấy đến thăm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Thanks!\", \"vi\": \"Cảm ơn!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Deborah Powell\", \"vi\": \"Deborah Powell\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}]' WHERE `id` = '56405713-c440-46a6-8c94-5034d9ff5734';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Request for Proposal\", \"vi\": \"Yêu cầu đề xuất\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Purpose\", \"vi\": \"Mục đích\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The City of New Langston is seeking proposals for the manufacture and installation of electronic signage at bus stops throughout the city.\", \"vi\": \"Thành phố New Langston đang kêu gọi các đề xuất về việc sản xuất và lắp đặt bảng hiệu điện tử tại các trạm xe buýt trên toàn thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"New Langston plans to deploy new electronic signs that display real-time arrival information to bus riders.\", \"vi\": \"New Langston có kế hoạch lắp đặt các bảng hiệu điện tử mới nhằm hiển thị thông tin về thời gian đến của xe buýt theo thời gian thực cho hành khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Background\", \"vi\": \"Bối cảnh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Currently, New Langston\'s bus stops are marked by simple metal signs displaying only the location of the stop and the lines that stop at the location.\", \"vi\": \"Hiện nay, các trạm xe buýt tại New Langston được đánh dấu bằng những biển báo kim loại đơn giản, chỉ ghi rõ vị trí của trạm và các tuyến xe buýt dừng tại địa điểm đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Cities around the world have begun to incorporate real-time arrival information into bus stop signage.\", \"vi\": \"Các thành phố trên khắp thế giới đã bắt đầu tích hợp thông tin về thời gian đến của xe buýt theo thời gian thực vào bảng hiệu tại các trạm xe buýt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Electronic signs are proving to be very popular with riders, and studies show that the introduction of such signage has contributed to increased ridership in numerous cities.\", \"vi\": \"Các bảng hiệu điện tử đang ngày càng được người đi xe ưa chuộng, và các nghiên cứu cho thấy việc triển khai các bảng hiệu này đã góp phần làm tăng lượng hành khách tại nhiều thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Project Description\", \"vi\": \"Mô tả dự án\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The successful bidder will provide New Langston with up to 350 electronic signs.\", \"vi\": \"Đơn vị trúng thầu sẽ cung cấp cho New Langston tối đa 350 bảng hiệu điện tử.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The signs must be powered by solar energy and have a battery backup allowing them to operate at night, on cloudy days, and in all weather conditions.\", \"vi\": \"Các biển báo phải được cấp điện bằng năng lượng mặt trời và được trang bị pin dự phòng để có thể hoạt động vào ban đêm, vào những ngày nhiều mây cũng như trong mọi điều kiện thời tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The signs must have a reliability factor of at least 99 percent.\", \"vi\": \"Các biển báo phải có hệ số tin cậy ít nhất là 99 phần trăm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The signs must display at least three and no more than five lines of text, and be connected to the Internet in order to provide real-time information to bus riders.\", \"vi\": \"Các biển báo phải hiển thị ít nhất ba dòng và không quá năm dòng văn bản, đồng thời phải được kết nối với Internet để cung cấp thông tin theo thời gian thực cho hành khách đi xe buýt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please submit detailed bids outlining costs by 11:59 p.m. on May 31 to the City of New Langston Regional Council at regionalcouncil@cityofnewlangston.gov.\", \"vi\": \"Kính đề nghị quý vị gửi hồ sơ dự thầu chi tiết, trong đó nêu rõ các khoản chi phí, trước 23 giờ 59 phút ngày 31 tháng 5 tới Hội đồng Khu vực Thành phố New Langston theo địa chỉ email regionalcouncil@cityofnewlangston.gov.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '56482bab-7076-4b27-b2d5-4ff85ec703dd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mirei Hair Care\", \"vi\": \"Mirei Chăm sóc tóc\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"a Japanese subsidiary of Khalinde Global Cosmetics, Inc.\", \"vi\": \"một công ty con tại Nhật Bản của Khalinde Global Cosmetics, Inc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Option - Estimated Cost - Main Benefit\", \"vi\": \"Phương án - Chi phí dự kiến - Lợi ích chính\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"1. Construct bigger manufacturing facility - ¥418 million - Larger production capacity\", \"vi\": \"1. Xây dựng nhà máy sản xuất quy mô lớn hơn – 418 triệu yên – Nâng cao năng lực sản xuất\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"2. Increase advertising budget - ¥210 million - Better brand awareness\", \"vi\": \"2. Tăng ngân sách quảng cáo – 210 triệu yên – Nâng cao nhận thức về thương hiệu\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"3. Buy out leading competitor - ¥180 million - Reduced competition\", \"vi\": \"3. Mua lại đối thủ cạnh tranh hàng đầu – 180 triệu yên – Giảm bớt sự cạnh tranh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"4. Expand distribution - ¥148 million - Increased sales\", \"vi\": \"4. Mở rộng mạng lưới phân phối – 148 triệu yên – Doanh số tăng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"5. Redesign packaging - ¥129 million - Lower per-item cost\", \"vi\": \"5. Thiết kế lại bao bì – 129 triệu yên – Giảm chi phí trên mỗi sản phẩm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Investment Options for Mirei Hair Care\", \"vi\": \"Các phương án đầu tư dành cho thương hiệu Mirei Hair Care\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '569f5d4e-e102-475b-94c0-8990a578dc60';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"CALLA DANCE STUDIO IS NOW OPEN!\", \"vi\": \"TRUNG TÂM MÚA CALLA ĐÃ CHÍNH THỨC KHAI TRƯƠNG!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Come to our beautiful, spacious studio in Hopkins Bay for our grand opening on Saturday, March 5, and Sunday, March 6, from noon to 5:00 P.M.\", \"vi\": \"Hãy đến tham dự lễ khai trương hoành tráng của chúng tôi tại studio xinh đẹp và rộng rãi ở Hopkins Bay vào thứ Bảy, ngày 5 tháng 3 và Chủ nhật, ngày 6 tháng 3, từ trưa đến 5 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"During the celebration, you can\", \"vi\": \"Trong buổi lễ kỷ niệm, quý vị có thể\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"mingle and chat with our highly trained instructors;\", \"vi\": \"giao lưu và trò chuyện cùng đội ngũ giảng viên được đào tạo chuyên sâu của chúng tôi;\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"enjoy fun, free, easygoing dance classes; and\", \"vi\": \"tham gia các lớp học khiêu vũ vui vẻ, miễn phí và thoải mái; và\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"receive a 10 percent discount on one of our dance lesson packages.\", \"vi\": \"Quý vị sẽ được giảm giá 10% khi đăng ký một trong các gói khóa học khiêu vũ của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We believe that everyone can benefit from dancing, so whether you are a beginner or an expert, we have a class for you!\", \"vi\": \"Chúng tôi tin rằng ai cũng có thể hưởng lợi từ việc khiêu vũ, vì vậy dù quý vị là người mới bắt đầu hay đã thành thạo, chúng tôi đều có lớp học phù hợp dành cho quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Visit us online at www.calladancestudio.com for class descriptions, instructor profiles, directions to the studio, and more.\", \"vi\": \"Hãy truy cập trang web của chúng tôi tại www.calladancestudio.com để xem thông tin chi tiết về các lớp học, hồ sơ giảng viên, hướng dẫn đường đi đến phòng tập và nhiều thông tin hữu ích khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '56c46c27-bf88-4fd1-9d80-bdf9ed610b55';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Millsberg Summer Festival\", \"vi\": \"Lễ hội Mùa hè Millsberg\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Millsberg’s annual Summer Festival returns this June for its sixtieth year!\", \"vi\": \"Lễ hội Mùa hè thường niên của Millsberg sẽ trở lại vào tháng 6 năm nay, đánh dấu năm thứ 60!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Opening Parade\", \"vi\": \"Lễ diễu hành khai mạc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"June 20, 10:00 A.M.\", \"vi\": \"Ngày 20 tháng 6, 10 giờ sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"This is the Summer Festival’s oldest and best-known event.\", \"vi\": \"Đây là sự kiện lâu đời nhất và nổi tiếng nhất trong khuôn khổ Lễ hội Mùa Hè.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The parade marks the official start of the festival and features elaborate floats and marching bands.\", \"vi\": \"Cuộc diễu hành đánh dấu sự khởi đầu chính thức của lễ hội và có sự góp mặt của các xe hoa được trang trí công phu cùng các ban nhạc diễu hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Children’s Fun Fair\", \"vi\": \"Lễ hội vui chơi dành cho trẻ em\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"June 20–26, noon–8:00 P.M.\", \"vi\": \"Từ ngày 20 đến ngày 26 tháng 6, từ trưa đến 8 giờ tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Carnival rides and entertainment at Millsberg Park\", \"vi\": \"Các trò chơi hội chợ và các hoạt động giải trí tại Công viên Millsberg\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Outdoor Concert Series\", \"vi\": \"Chuỗi buổi hòa nhạc ngoài trời\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"June 20–26, 7:00 P.M.\", \"vi\": \"Từ ngày 20 đến ngày 26 tháng 6, lúc 7 giờ tối\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Live music, including folk, jazz, and classical, at Greenrow Park\", \"vi\": \"Các buổi biểu diễn nhạc sống, bao gồm nhạc dân gian, nhạc jazz và nhạc cổ điển, tại Công viên Greenrow\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Wood-fired pizza and other snacks will be available for purchase.\", \"vi\": \"Quý vị có thể mua pizza nướng bằng lò củi cùng các món ăn nhẹ khác tại đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Open-Air Art Studio\", \"vi\": \"Xưởng nghệ thuật ngoài trời\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"June 26, 3:00 P.M.–9:00 P.M.\", \"vi\": \"Ngày 26 tháng 6, từ 3 giờ chiều đến 9 giờ tối\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"On the final day of the festival, local painters, photographers, and potters welcome the public to view their works at the park in front of the Riverside Art Complex.\", \"vi\": \"Vào ngày cuối cùng của lễ hội, các họa sĩ, nhiếp ảnh gia và nghệ nhân gốm địa phương trân trọng mời quý vị đến chiêm ngưỡng các tác phẩm của họ tại công viên phía trước Trung tâm Nghệ thuật Riverside.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '56f4fafd-234c-46c7-b99b-71a462840ecf';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Muelker Shipyard Undergoes Transformation\", \"vi\": \"Xưởng đóng tàu Muelker đang trải qua quá trình chuyển đổi\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"May 2—The Muelker Shipyard, a once-bustling ship manufacturing center, is being given a new role.\", \"vi\": \"Ngày 2 tháng 5 — Xưởng đóng tàu Muelker, nơi từng là một trung tâm đóng tàu nhộn nhịp, hiện đang được giao một vai trò mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"A team of engineers is working to turn it into an open-air pedestrian mall with restaurants, a dozen retail businesses, and an outdoor patio that will feature live music performances.\", \"vi\": \"Một nhóm kỹ sư hiện đang nỗ lực biến nơi đây thành một khu phố đi bộ ngoài trời với các nhà hàng, khoảng một chục cửa hàng bán lẻ và một sân hiên ngoài trời sẽ tổ chức các buổi biểu diễn nhạc sống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Until June of last year, the city had planned to demolish the shipyard—a decision that caused a strong reaction from community members, especially former shipbuilders who viewed the site as a treasured industrial landmark.\", \"vi\": \"Cho đến tháng 6 năm ngoái, thành phố đã có kế hoạch phá dỡ xưởng đóng tàu — một quyết định đã gây ra phản ứng mạnh mẽ từ các thành viên cộng đồng, đặc biệt là những cựu thợ đóng tàu, những người coi địa điểm này là một di tích công nghiệp quý giá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Wanting their labor to be remembered by future generations, many shipbuilders had etched their names on a wall near the entrance.\", \"vi\": \"Với mong muốn công lao của mình được các thế hệ mai sau ghi nhớ, nhiều thợ đóng tàu đã khắc tên mình lên một bức tường gần lối vào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"“In the peak of production, shipyard workers produced a naval ship in just a year,” said lead engineer, Barney Enyart.\", \"vi\": \"“Vào thời điểm sản xuất đạt đỉnh cao, các công nhân tại xưởng đóng tàu đã hoàn thành một chiếc tàu hải quân chỉ trong vòng một năm,” kỹ sư trưởng Barney Enyart cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"“Then production gradually slowed, and the shipyard eventually closed.\", \"vi\": \"“Sau đó, hoạt động sản xuất dần dần chậm lại, và cuối cùng xưởng đóng tàu đã phải đóng cửa.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"When this project is complete, the new complex will be enjoyed throughout the year, serving as a place for employment opportunities and recreation while the legacy of the site’s past will endure.”\", \"vi\": \"“Khi dự án này hoàn thành, khu phức hợp mới sẽ là điểm đến lý tưởng quanh năm, vừa là nơi tạo ra cơ hội việc làm, vừa là địa điểm giải trí, đồng thời di sản lịch sử của khu vực này sẽ được lưu giữ mãi mãi.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '575ccd37-4a30-4b8d-a95b-8fa2a8eca713';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Hapkell Industries Pairs Up with E&T Recycling Center\", \"vi\": \"Công ty Hapkell Industries hợp tác với Trung tâm Tái chế E&T\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"June 19—The computer technology company Hapkell Industries just announced it will begin working with E&T Recycling Centers.\", \"vi\": \"Ngày 19 tháng 6 — Công ty công nghệ máy tính Hapkell Industries vừa thông báo rằng họ sẽ bắt đầu hợp tác với E&T Recycling Centers.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This partnership will enable consumers to responsibly recycle computer equipment, at no personal cost, simply by taking it to a collection center.\", \"vi\": \"Sự hợp tác này sẽ giúp người tiêu dùng có thể tái chế thiết bị máy tính một cách có trách nhiệm, mà không tốn bất kỳ chi phí cá nhân nào, chỉ cần mang chúng đến trung tâm thu gom là được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"\\\"Used computers make up a rapidly growing waste source,\\\" said CEO Indira Kapoor.\", \"vi\": \"\\\"Máy tính đã qua sử dụng đang trở thành một nguồn rác thải tăng trưởng nhanh chóng,\\\" Giám đốc điều hành Indira Kapoor cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"As a major producer of computer products, we believe it is our obligation to reuse what we can and keep heavy metals out of the landfills.\", \"vi\": \"\\\"Với tư cách là một nhà sản xuất hàng đầu trong lĩnh vực sản phẩm máy tính, chúng tôi tin rằng chúng tôi có nghĩa vụ phải tái sử dụng những gì có thể và ngăn chặn việc các kim loại nặng thải ra các bãi rác.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This is what prompted us to go forward with this initiative.\\\"\", \"vi\": \"Đây chính là điều đã thúc đẩy chúng tôi quyết định triển khai sáng kiến này.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Hapkell Industries originally sponsored two pilot E&T collection sites and, given their success, aims to add ten more sites by year\'s end.\", \"vi\": \"Ban đầu, Hapkell Industries đã tài trợ cho hai điểm thu gom E&T thí điểm và, nhờ vào thành công của các điểm này, công ty đặt mục tiêu sẽ bổ sung thêm mười điểm nữa trước cuối năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To learn more about the initiative and for a map of current and proposed collection sites, visit ETrecyclingcenter.com.\", \"vi\": \"Để tìm hiểu thêm về sáng kiến này cũng như xem bản đồ các điểm thu gom hiện tại và dự kiến, quý vị vui lòng truy cập trang web ETrecyclingcenter.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '5766c3cc-78f1-4d09-841a-3fbba2fa7584';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dear High View Apartments Resident,\", \"vi\": \"Kính gửi quý cư dân khu căn hộ High View,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Riverside Paving Company is coming to High View Apartments on May 3 and 4 to resurface the parking area.\", \"vi\": \"Công ty Riverside Paving sẽ có mặt tại Khu căn hộ High View vào ngày 3 và 4 tháng 5 để tiến hành lát lại mặt đường khu vực bãi đỗ xe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"All vehicles must be removed by 8 A.M. on May 3 for the work to commence.\", \"vi\": \"Tất cả các phương tiện phải được di dời trước 8 giờ sáng ngày 3 tháng 5 để công việc có thể bắt đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Residents may use the parking area again starting on May 5 at 8 A.M. We realize that trying to find another place to park is inconvenient, but it is necessary for the job to be completed in the two days scheduled.\", \"vi\": \"Các cư dân có thể sử dụng lại khu vực đỗ xe kể từ 8 giờ sáng ngày 5 tháng 5. Chúng tôi hiểu rằng việc phải tìm một nơi đỗ xe khác sẽ gây bất tiện, nhưng đây là điều cần thiết để công việc được hoàn thành trong vòng hai ngày theo kế hoạch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Note that all parking spaces will be widened, and some spaces could be moved during the work.\", \"vi\": \"Xin lưu ý rằng tất cả các chỗ đỗ xe sẽ được mở rộng, và một số chỗ đỗ xe có thể sẽ được di dời trong thời gian thi công.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"You will receive an e-mail if your parking space is moved more than 20 meters from your previous one.\", \"vi\": \"Quý vị sẽ nhận được một email nếu chỗ đỗ xe của quý vị được chuyển đi xa hơn 20 mét so với vị trí trước đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for your cooperation,\", \"vi\": \"Xin chân thành cảm ơn sự hợp tác của quý vị,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Judith Alvarez, Property Manager\", \"vi\": \"Judith Alvarez, Quản lý Bất động sản\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '57863889-edbf-4fe8-8621-720c4f7a69b9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Vayu Dhebar <dhebarv@quincy-inc.com>\", \"vi\": \"Gửi tới: Vayu Dhebar <dhebarv@quincy-inc.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Andre Longoria <andre1@wilmarrentals.com>\", \"vi\": \"Từ: Andre Longoria <andre1@wilmarrentals.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: April 13\", \"vi\": \"Ngày: 13 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Vehicle rental\", \"vi\": \"Chủ đề: Dịch vụ cho thuê xe\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Dhebar,\", \"vi\": \"Kính gửi bà Dhebar,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for choosing Wilmar Rentals for your recent vehicle rental needs.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã lựa chọn Wilmar Rentals để đáp ứng nhu cầu thuê xe gần đây của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To help us improve our customer service, we ask that you fill out a brief questionnaire to provide honest feedback about your experience.\", \"vi\": \"Để giúp chúng tôi nâng cao chất lượng dịch vụ khách hàng, chúng tôi kính mong quý vị dành thời gian điền vào bảng câu hỏi ngắn này nhằm chia sẻ những ý kiến phản hồi chân thành về trải nghiệm của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Simply click here and complete the online form.\", \"vi\": \"Quý vị chỉ cần nhấp vào đây và điền vào biểu mẫu trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"To show our appreciation for your participation, I will e-mail you a voucher that will allow you to extend your next rental by three days at no extra charge.\", \"vi\": \"Để bày tỏ lòng biết ơn đối với sự tham gia của quý khách, tôi sẽ gửi qua email cho quý khách một phiếu ưu đãi, giúp quý khách có thể gia hạn thời gian thuê lần tiếp theo thêm ba ngày mà không phải trả thêm phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This can be used anytime in the next 12 months.\", \"vi\": \"Quý vị có thể sử dụng ưu đãi này bất cứ lúc nào trong vòng 12 tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Thank you for your patronage!\", \"vi\": \"Xin chân thành cảm ơn quý khách đã ủng hộ!\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Andre Longoria\", \"vi\": \"Andre Longoria\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Customer Service, Wilmar Rentals\", \"vi\": \"Bộ phận Dịch vụ Khách hàng, Wilmar Rentals\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"*E-Mail*\", \"vi\": \"*Email*\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '578f7179-ce97-4fc9-a25b-2f662577a941';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"HALVERTON (June 8)—The National Postal Service (NPS) unveiled a set of 42 electric delivery trucks today.\", \"vi\": \"HALVERTON (Ngày 8 tháng 6) — Dịch vụ Bưu chính Quốc gia (NPS) đã ra mắt bộ sưu xe tải giao hàng chạy bằng điện gồm 42 chiếc vào ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The vehicles ______[139] the first step in the organization\'s plan to electrify part of its fleet.\", \"vi\": \"Các phương tiện này ______[139] bước đầu tiên trong kế hoạch điện khí hóa một phần đội xe của tổ chức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [139]}, {\"en\": \"They will enable mail ______[140] to make their deliveries with a smaller carbon footprint.\", \"vi\": \"Chúng sẽ cho phép những người giao thư ______[140] thực hiện việc giao hàng với lượng khí thải carbon nhỏ hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [140]}, {\"en\": \"The NPS has also begun outfitting some of its branches with electric vehicle charging stations.\", \"vi\": \"NPS cũng đã bắt đầu trang bị các trạm sạc xe điện cho một số chi nhánh của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Unfortunately, many small local post offices do not have the electrical infrastructure to support the stations.\", \"vi\": \"Thật không may, nhiều bưu cục địa phương nhỏ không có cơ sở hạ tầng điện để hỗ trợ các trạm sạc này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[141], the organization will mainly employ electric trucks at its larger regional hubs.\", \"vi\": \"______[141], tổ chức này sẽ chủ yếu sử dụng xe tải điện tại các trung tâm khu vực lớn hơn của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [141]}, {\"en\": \"______[142].\", \"vi\": \"______[142].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [142]}]' WHERE `id` = '57c636d8-3cb5-49ea-a4f6-8730f2229abc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Humini Hardware\", \"vi\": \"Chào mừng quý vị đến với phần Phần cứng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Notice to Customers\", \"vi\": \"Thông báo gửi quý khách hàng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Following the expansion of our store, and prompted by requests from customers for more products, many of the items between aisles 2 and 20 will now be relocated.\", \"vi\": \"Sau khi cửa hàng của chúng tôi được mở rộng, đồng thời nhằm đáp ứng yêu cầu của quý khách hàng về việc bổ sung thêm các mặt hàng, nhiều sản phẩm hiện đang được bày bán tại các lối đi từ số 2 đến số 20 sẽ được chuyển sang vị trí mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Reshelving will occur during the period of April 16 to May 2, at which time we will have additional staff on hand to help you find the products you need.\", \"vi\": \"Việc sắp xếp lại kệ hàng sẽ diễn ra trong khoảng thời gian từ ngày 16 tháng 4 đến ngày 2 tháng 5; trong thời gian này, chúng tôi sẽ bố trí thêm nhân viên tại chỗ để hỗ trợ quý khách tìm kiếm các sản phẩm mà quý khách cần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We are confident you will find the new store layout an improvement over the old one.\", \"vi\": \"Chúng tôi tin chắc rằng quý vị sẽ thấy cách bài trí mới của cửa hàng này là một sự cải tiến so với cách bài trí cũ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for your patience.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã kiên nhẫn chờ đợi.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Management, Humini Hardware\", \"vi\": \"Ban lãnh đạo, Humini Hardware\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '57caee09-5135-4c50-b106-d3704cf790c4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: staff@rindersbusiness.co.ke\", \"vi\": \"Gửi tới: staff@rindersbusiness.co.ke\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: dcloeten@rindersbusiness.co.ke\", \"vi\": \"Nguồn: dcloeten@rindersbusiness.co.ke\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 25 October\", \"vi\": \"Ngày: 25 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Rinders Staff:\", \"vi\": \"Kính gửi quý nhân viên Rinders:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our company is growing, and I am pleased to welcome new staff members!\", \"vi\": \"Công ty chúng tôi đang trên đà phát triển, và tôi rất vui mừng được chào đón các thành viên mới gia nhập đội ngũ!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Those in our Nairobi office will get to know Mary Gichuki very well.\", \"vi\": \"Những người làm việc tại văn phòng Nairobi của chúng tôi sẽ có cơ hội làm quen rất thân thiết với bà Mary Gichuki.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"She will be the new office manager there, beginning on 1 November.\", \"vi\": \"Bà sẽ đảm nhận chức vụ Trưởng phòng hành chính mới tại đó, bắt đầu từ ngày 1 tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Some of you met her last week when she visited the office.\", \"vi\": \"Một số quý vị đã gặp cô ấy vào tuần trước khi cô ấy đến thăm văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"She will be replacing David Alberts.\", \"vi\": \"Bà sẽ thay thế ông David Alberts.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Anila Pillai will also be a new face in our Nairobi office.\", \"vi\": \"Bà Anila Pillai cũng sẽ là một gương mặt mới tại văn phòng của chúng tôi ở Nairobi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Ms. Pillai will be an administrative assistant, and she will greet visitors, answer the phone, and perform office duties.\", \"vi\": \"Bà Pillai sẽ đảm nhận vị trí trợ lý hành chính, đồng thời có nhiệm vụ tiếp đón khách, trả lời điện thoại và thực hiện các công việc văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"She will work on Wednesdays, Thursdays, and Fridays from 10:00 A.M. to 3:00 P.M.\", \"vi\": \"Cô ấy sẽ làm việc vào các ngày thứ Tư, thứ Năm và thứ Sáu, từ 10 giờ sáng đến 3 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Mark Karunga, who has worked in the Nairobi office for the past fifteen years, is being promoted to senior accountant and will work in our new Mombasa office beginning on 15 November.\", \"vi\": \"Ông Mark Karunga, người đã công tác tại văn phòng Nairobi trong mười lăm năm qua, sẽ được thăng chức lên vị trí kế toán viên cao cấp và sẽ bắt đầu làm việc tại văn phòng mới của chúng tôi ở Mombasa kể từ ngày 15 tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I will soon be sending another e-mail alerting you to more new faces in our offices since we are still hiring personnel for the Mombasa location.\", \"vi\": \"Tôi sẽ sớm gửi một email khác để thông báo cho quý vị về những gương mặt mới tại các văn phòng của chúng tôi, vì hiện tại chúng tôi vẫn đang tuyển dụng nhân sự cho chi nhánh tại Mombasa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We hope to have all positions filled there before the grand opening in November.\", \"vi\": \"Chúng tôi hy vọng sẽ tuyển đủ nhân sự cho tất cả các vị trí tại đó trước khi khai trương chính thức vào tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Deborah Cloeten\", \"vi\": \"Deborah Cloeten\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Vice President\", \"vi\": \"Phó Chủ tịch\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Rinders Business Systems\", \"vi\": \"Hệ thống kinh doanh Rinders\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '57cba083-a8a8-410c-abb5-909227dcaae9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"New Look for Rhee Poultry\", \"vi\": \"Hình ảnh mới của Rhee Poultry\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"LEEDS (17 February)—Rhee Poultry, suppliers of fresh and frozen poultry, announced on Monday a change to its packaging practices.\", \"vi\": \"LEEDS (ngày 17 tháng 2) — Công ty Rhee Poultry, nhà cung cấp các sản phẩm gia cầm tươi và đông lạnh, đã thông báo vào thứ Hai về việc thay đổi quy trình đóng gói của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Starting on 31 October, every package of chicken, duck, goose, and turkey sold at retail will be labeled with the city and country where the meat was sourced.\", \"vi\": \"Kể từ ngày 31 tháng 10, mỗi gói thịt gà, vịt, ngỗng và gà tây được bán tại các cửa hàng bán lẻ sẽ được dán nhãn ghi rõ thành phố và quốc gia nơi nguồn gốc của thịt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"According to company spokesperson Insook Kim, Rhee will make modifications to its production, packing, and shipping facilities that will cost an estimated £400,000 over a transition period of eight months.\", \"vi\": \"Theo bà Insook Kim, người phát ngôn của công ty, Rhee sẽ tiến hành điều chỉnh các cơ sở sản xuất, đóng gói và vận chuyển, với chi phí ước tính khoảng 400.000 bảng Anh trong giai đoạn chuyển đổi kéo dài tám tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"The high price tag is more than worth it to maintain the trust our customers have always had in Rhee Poultry products,\\\" added Ms. Kim.\", \"vi\": \"\\\"Mức giá cao này hoàn toàn xứng đáng để duy trì niềm tin mà quý khách hàng luôn dành cho các sản phẩm của Rhee Poultry,\\\" bà Kim nhấn mạnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Rhee\'s announcement was made following criticism regarding transparency in sourcing practices leveled at other meat-packaging conglomerates that sell in the United Kingdom, such as Supragood and Char Bo Lynn, Inc.\", \"vi\": \"Thông báo của ông Rhee được đưa ra sau khi các tập đoàn chế biến thịt khác đang kinh doanh tại Vương quốc Anh, như Supragood và Char Bo Lynn, Inc., phải hứng chịu những chỉ trích liên quan đến tính minh bạch trong các hoạt động thu mua nguyên liệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"\\\"We felt it was in the best interests of our customers to be proactive in this matter,\\\" said Ms. Kim.\", \"vi\": \"\\\"Chúng tôi cho rằng việc chủ động xử lý vấn đề này là vì lợi ích tốt nhất của quý khách hàng,\\\" bà Kim phát biểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"RHEE POULTRY\", \"vi\": \"RHEE POULTRY\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Boneless Duck Breasts\", \"vi\": \"Ức vịt không xương\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"1.5 kg\", \"vi\": \"1,5 kg\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Raised in Rzeszow, Poland\", \"vi\": \"Lớn lên tại Rzeszów, Ba Lan\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Packed in Krakow, Poland\", \"vi\": \"Được đóng gói tại Kraków, Ba Lan\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Only and always the best in poultry!\", \"vi\": \"Chỉ và luôn luôn là những sản phẩm gia cầm tốt nhất!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Notice something different about our packaging?\", \"vi\": \"Quý vị có nhận thấy điều gì khác biệt ở bao bì sản phẩm của chúng tôi không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Go to our Web site, www.rhee.co.uk, to read about our recent changes.\", \"vi\": \"Vui lòng truy cập trang web của chúng tôi tại địa chỉ www.rhee.co.uk để tìm hiểu về những thay đổi gần đây của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '57fa0768-c76c-46fa-8efa-031b3e6c5b45';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.hilgravehistoricalcommission.org/contact_us\", \"vi\": \"https://www.hilgravehistoricalcommission.org/contact_us\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Contact the Hilgrave Historical Commission\", \"vi\": \"Vui lòng liên hệ với Ủy ban Lịch sử Hilgrave\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Name: Roger Witmondt\", \"vi\": \"Họ và tên: Roger Witmondt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"E-mail: roger@witmondtlocations.com\", \"vi\": \"Email: roger@witmondtlocations.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Comment:\", \"vi\": \"Cách thực hiện:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I work as a movie location scout.\", \"vi\": \"Tôi làm công việc tìm kiếm địa điểm quay phim.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"At this time, I need to find a location for a client\'s short film.\", \"vi\": \"Hiện tại, tôi cần tìm một địa điểm để quay phim ngắn cho một khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The film will be set in the early 1930s, and I understand that Hilgrave has some interesting architecture from that era.\", \"vi\": \"Bộ phim sẽ lấy bối cảnh vào đầu những năm 1930, và theo tôi được biết, Hilgrave có một số công trình kiến trúc thú vị từ thời kỳ đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Could you suggest places I should visit when I am in Hilgrave next month?\", \"vi\": \"Xin quý vị có thể gợi ý cho tôi những địa điểm mà tôi nên ghé thăm khi đến Hilgrave vào tháng tới không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Specifically, I am looking for a vacant building with an old-fashioned storefront that has distinctive details like stripe-patterned awnings and framed display windows.\", \"vi\": \"Cụ thể, tôi đang tìm kiếm một tòa nhà trống có mặt tiền theo phong cách cổ điển, với những chi tiết đặc trưng như mái hiên kẻ sọc và các cửa sổ trưng bày có khung.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"While having easy access to electricity would be ideal, it is not critical; my client has a generator that can be used if necessary.\", \"vi\": \"Mặc dù việc có thể tiếp cận nguồn điện một cách thuận tiện là điều lý tưởng, nhưng điều này không phải là yếu tố then chốt; khách hàng của tôi có một máy phát điện có thể sử dụng khi cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"My client\'s aesthetic requirements are the most important consideration.\", \"vi\": \"Yêu cầu về mặt thẩm mỹ của khách hàng là yếu tố quan trọng hàng đầu cần được xem xét.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you for your assistance.\", \"vi\": \"Xin chân thành cảm ơn sự hỗ trợ của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To: roger@witmondtlocations.com\", \"vi\": \"Gửi tới: roger@witmondtlocations.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"From: brandi_schaertl@hilgravehistoricalcommission.org\", \"vi\": \"Nguồn: brandi_schaertl@hilgravehistoricalcommission.org\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Date: 28 September\", \"vi\": \"Ngày: 28 tháng 9\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Subject: The information you requested\", \"vi\": \"Chủ đề: Thông tin mà quý vị đã yêu cầu\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Hilgrave Sites\", \"vi\": \"Tệp đính kèm: 📎 Các địa điểm tại Hilgrave\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Dear Mr. Witmondt,\", \"vi\": \"Kính gửi ông Witmondt,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Thank you for reaching out to the Hilgrave Historical Commission.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã liên hệ với Ủy ban Lịch sử Hilgrave.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"The attached brochure lists the main areas of historical interest in Hilgrave.\", \"vi\": \"Tài liệu giới thiệu kèm theo đây liệt kê các địa điểm lịch sử chính tại Hilgrave.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Some buildings may not meet all your requirements, but they might be worth considering.\", \"vi\": \"Một số tòa nhà có thể không đáp ứng được tất cả các yêu cầu của quý vị, nhưng chúng vẫn đáng để quý vị cân nhắc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"One building that is not on the attached list is the old record store at 188 Main Street.\", \"vi\": \"Một tòa nhà không có trong danh sách đính kèm là cửa hàng đĩa nhạc cũ tọa lạc tại số 188 Main Street.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"It has been closed to business for the past ten years or so, but it seems to meet your criteria.\", \"vi\": \"Nơi này đã ngừng hoạt động kinh doanh trong khoảng mười năm qua, nhưng có vẻ như nó đáp ứng được các tiêu chí của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"The owner, Luke Nylund, is currently using it for storage; I would be happy to put you in touch with him.\", \"vi\": \"Chủ sở hữu, ông Luke Nylund, hiện đang sử dụng nơi này làm kho chứa hàng; tôi rất sẵn lòng giới thiệu quý vị liên hệ với ông ấy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I doubt you will have trouble getting permission from him to use the space.\", \"vi\": \"Tôi không nghĩ rằng quý vị sẽ gặp khó khăn trong việc xin phép ông ấy để sử dụng không gian đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"While Hilgrave was once a bustling town, these days there are fewer businesses in operation.\", \"vi\": \"Mặc dù Hilgrave từng là một thị trấn nhộn nhịp, nhưng hiện nay số lượng các cơ sở kinh doanh đang hoạt động đã giảm đi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Many of the town\'s residents would appreciate the attention a short film might bring to the area.\", \"vi\": \"Nhiều người dân trong thị trấn sẽ đánh giá cao sự chú ý mà một bộ phim ngắn có thể mang lại cho khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Brandi Schaertl\", \"vi\": \"Brandi Schaertl\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}]' WHERE `id` = '580ccd51-b28e-440e-a834-d258c126f9cf';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Leila Hedlund\", \"vi\": \"Từ: Leila Hedlund\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: November software training\", \"vi\": \"Chủ đề: Khóa đào tạo phần mềm tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: October 30\", \"vi\": \"Ngày: 30 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Software Training Schedule\", \"vi\": \"Tài liệu đính kèm: Lịch trình đào tạo phần mềm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Staff,\", \"vi\": \"Kính gửi quý đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Throughout November, we will be holding mandatory training sessions for two of our major software products.\", \"vi\": \"Trong suốt tháng 11, chúng tôi sẽ tổ chức các buổi đào tạo bắt buộc dành cho hai sản phẩm phần mềm chủ lực của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Training in the Abacus Deepthink software will be required for all staff members and can be completed in a single online session.\", \"vi\": \"Tất cả các nhân viên đều phải tham gia khóa đào tạo về phần mềm Abacus Deepthink; khóa đào tạo này có thể hoàn thành chỉ trong một buổi học trực tuyến duy nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Several possible session times are available.\", \"vi\": \"Có sẵn một số khung giờ buổi học để quý vị lựa chọn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The software has gone through several changes recently, so even longtime users must attend.\", \"vi\": \"Phần mềm này gần đây đã trải qua một số thay đổi, do đó ngay cả những người dùng lâu năm cũng cần tham dự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The Optisafe software training will be offered in person and is a requirement only for Drug Safety department members.\", \"vi\": \"Khóa đào tạo phần mềm Optisafe sẽ được tổ chức trực tiếp và chỉ là yêu cầu bắt buộc đối với các thành viên của Phòng An toàn Dược phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"This past year, major upgrades have been made to the software, and all department staff will need to learn how to use its new capabilities.\", \"vi\": \"Trong năm vừa qua, phần mềm đã được nâng cấp đáng kể, và toàn thể nhân viên trong phòng ban sẽ cần phải làm quen với cách sử dụng các tính năng mới của phần mềm này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please look over the attached schedule and go to the company training Web site to sign up.\", \"vi\": \"Kính mong quý vị xem qua lịch trình đính kèm và truy cập trang web đào tạo của công ty để đăng ký.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Leila Hedlund\", \"vi\": \"Leila Hedlund\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Kodarex Pharmaceuticals\", \"vi\": \"Công ty Dược phẩm Kodarex\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date - Title - Time - Location\", \"vi\": \"Ngày - Tiêu đề - Thời gian - Địa điểm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"November 6 - Abacus Deepthink - 9 A.M.–11 A.M. - Online\", \"vi\": \"Ngày 6 tháng 11 – Abacus Deepthink – 9 giờ sáng – 11 giờ sáng – Trực tuyến\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"November 9 - Optisafe - 9 A.M.–1 P.M. - Building C, Room 822\", \"vi\": \"Ngày 9 tháng 11 - Optisafe - 9 giờ sáng – 1 giờ chiều - Tòa nhà C, Phòng 822\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"November 14 - Abacus Deepthink - 1 P.M.–3 P.M. - Online\", \"vi\": \"Ngày 14 tháng 11 - Abacus Deepthink - 13 giờ – 15 giờ - Trực tuyến\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"November 17 - Abacus Deepthink - 10 A.M.–12 P.M. - Online\", \"vi\": \"Ngày 17 tháng 11 - Abacus Deepthink - 10 giờ sáng – 12 giờ trưa - Trực tuyến\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"November 22 - Optisafe - 1 P.M.–5 P.M. - Building C, Room 822\", \"vi\": \"Ngày 22 tháng 11 - Optisafe - 13 giờ – 17 giờ - Tòa nhà C, Phòng 822\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"November 27 - Abacus Deepthink - 3 P.M.–5 P.M. - Online\", \"vi\": \"Ngày 27 tháng 11 - Abacus Deepthink - 15h00–17h00 - Trực tuyến\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"The online lessons can be accessed at https://www.abacusdeepthink.com\", \"vi\": \"Quý vị có thể truy cập các bài học trực tuyến tại địa chỉ https://www.abacusdeepthink.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Software Training Schedule\", \"vi\": \"Lịch trình đào tạo phần mềm\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"To: Leila Hedlund\", \"vi\": \"Gửi: Leila Hedlund\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"From: Diego Ramos-Toro\", \"vi\": \"Từ: Diego Ramos-Toro\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Re: November software training\", \"vi\": \"Trả lời: Khóa đào tạo phần mềm tháng 11\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Date: October 31\", \"vi\": \"Ngày: 31 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Dear Leila,\", \"vi\": \"Kính gửi Leila,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I need to attend both software trainings, but I had planned to take off work from November 6 through November 18.\", \"vi\": \"Tôi cần tham dự cả hai khóa đào tạo về phần mềm, nhưng tôi đã dự định xin nghỉ làm từ ngày 6 tháng 11 đến ngày 18 tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Also, I must attend an all-day client meeting on November 22 that we cannot reschedule.\", \"vi\": \"Ngoài ra, tôi phải tham dự một cuộc họp với khách hàng kéo dài cả ngày vào ngày 22 tháng 11, và cuộc họp này không thể dời lịch được.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Will there be any alternative sessions for the Optisafe training that I could attend?\", \"vi\": \"Liệu có bất kỳ khóa học thay thế nào cho khóa đào tạo Optisafe mà tôi có thể tham dự không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Diego Ramos-Toro\", \"vi\": \"Diego Ramos-Toro\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}]' WHERE `id` = '583e92a0-d6bd-47cc-ab5c-b69b2136eda1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Mara Renaldo <mrenaldo@viyamail.com>\", \"vi\": \"Gửi tới: Mara Renaldo <mrenaldo@viyamail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Lisa Yang <lyang@staffordsvillefair.org>\", \"vi\": \"Từ: Lisa Yang <lyang@staffordsvillefair.org>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 28\", \"vi\": \"Ngày: 28 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: RE: Staffordsville Craft Fair\", \"vi\": \"Chủ đề: RE: Hội chợ thủ công mỹ nghệ Staffordsville\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Renaldo,\", \"vi\": \"Kính gửi bà Renaldo,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for your interest in selling your handcrafted items at the annual Staffordsville Craft Fair.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã quan tâm đến việc bày bán các sản phẩm thủ công của mình tại Hội chợ Thủ công mỹ nghệ thường niên Staffordsville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Please note that all applicants must submit a $25 application fee, whether or not they want to share a space with another applicant.\", \"vi\": \"Xin lưu ý rằng tất cả các ứng viên đều phải nộp lệ phí đăng ký 25 đô la, bất kể họ có muốn chia sẻ chỗ ở với ứng viên khác hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Moreover, all applicants must submit a minimum of four photographs of their work in order to be considered as a vendor.\", \"vi\": \"Hơn nữa, tất cả các ứng viên phải nộp tối thiểu bốn bức ảnh về tác phẩm của mình để được xem xét trở thành nhà cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In addition to photographs, we ask that you submit a rough sketch showing how you would display your work.\", \"vi\": \"Ngoài các bức ảnh, chúng tôi mong quý vị vui lòng gửi kèm một bản phác thảo sơ bộ thể hiện cách quý vị dự định trưng bày tác phẩm của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Since you propose to share a space with a friend, local potter Julia Berens, it would be helpful if your sketch could indicate how you are planning to use the space jointly.\", \"vi\": \"Vì quý vị đề xuất sẽ chia sẻ không gian với một người bạn, đó là nghệ nhân gốm địa phương Julia Berens, nên sẽ rất hữu ích nếu bản phác thảo của quý vị có thể nêu rõ quý vị dự định sử dụng không gian đó chung như thế nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Also, because we hold the fair rain or shine, all vendors must supply their own tenting to protect themselves and their wares from the possibility of rain.\", \"vi\": \"Ngoài ra, do hội chợ vẫn diễn ra bất kể thời tiết như thế nào, tất cả các gian hàng phải tự chuẩn bị lều bạt để bảo vệ bản thân và hàng hóa khỏi khả năng có mưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Finally, please be aware that every year we receive far more applications from jewelry makers than we can accept.\", \"vi\": \"Cuối cùng, xin quý vị lưu ý rằng hàng năm, chúng tôi nhận được số lượng đơn đăng ký từ các nghệ nhân chế tác trang sức nhiều hơn rất nhiều so với số lượng mà chúng tôi có thể chấp nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We hope that you will not be too discouraged if your work is not accepted this year, as you are applying for the first time.\", \"vi\": \"Chúng tôi hy vọng quý vị sẽ không quá nản lòng nếu tác phẩm của quý vị không được chọn trong năm nay, vì đây là lần đầu tiên quý vị nộp đơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Thanks again, and best of luck with your application,\", \"vi\": \"Một lần nữa xin cảm ơn, và chúc quý vị may mắn trong quá trình nộp hồ sơ,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Lisa Yang\", \"vi\": \"Lisa Yang\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '5849994e-34db-4cd2-b3d5-0c9d3b8ddee5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Construction Superintendent\", \"vi\": \"Trưởng ban giám sát công trình\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Jones-Richmond Construction (JRC)\", \"vi\": \"Công ty Xây dựng Jones-Richmond (JRC)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Founded 25 years ago, JRC is a full-service general contractor serving clients throughout Winnipeg and the surrounding area.\", \"vi\": \"Được thành lập cách đây 25 năm, JRC là một nhà thầu tổng hợp cung cấp dịch vụ trọn gói, phục vụ khách hàng trên toàn thành phố Winnipeg và các khu vực lân cận.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Responsibilities:\", \"vi\": \"Nhiệm vụ:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Report to senior project manager\", \"vi\": \"Báo cáo cho Trưởng phòng Quản lý Dự án\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Manage on-site construction activities\", \"vi\": \"Quản lý các hoạt động thi công tại công trường\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Ensure compliance with safety regulations\", \"vi\": \"Đảm bảo tuân thủ các quy định về an toàn\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Negotiate purchases and contracts\", \"vi\": \"Đàm phán về các giao dịch mua sắm và hợp đồng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Establish construction schedules\", \"vi\": \"Xây dựng lịch trình thi công\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Qualifications:\", \"vi\": \"Yêu cầu về trình độ:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Minimum five years of commercial construction experience\", \"vi\": \"Có ít nhất năm năm kinh nghiệm trong lĩnh vực xây dựng thương mại\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Willingness to travel to job sites daily (usually within a 50-kilometre radius)\", \"vi\": \"Sẵn sàng di chuyển đến các công trường hàng ngày (thường trong phạm vi bán kính 50 kilômét)\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Strong written communication skills\", \"vi\": \"Kỹ năng giao tiếp bằng văn bản xuất sắc\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To apply, submit a résumé and cover letter through www.jrc.ca/apply.\", \"vi\": \"Để nộp đơn ứng tuyển, xin vui lòng gửi sơ yếu lý lịch và thư giới thiệu qua địa chỉ email www.jrc.ca/apply.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '586410b2-dfc6-43b9-8624-fe84625ff15b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Urias Data Staff\", \"vi\": \"Đến: Tất cả nhân viên Urias Data\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Gabriella Shaw\", \"vi\": \"Từ: Gabriella Shaw\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Staff appreciation\", \"vi\": \"Chủ đề: Tri ân nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: April 15\", \"vi\": \"Ngày: 15 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"For Urias Data\'s annual staff appreciation event, we will take a group hike at Walpole National Park during business hours on Friday, April 25.\", \"vi\": \"Đối với sự kiện tri ân nhân viên thường niên của Urias Data, chúng ta sẽ tổ chức một chuyến đi bộ đường dài tập thể tại Công viên Quốc gia Walpole trong giờ làm việc vào thứ Sáu, ngày 25 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We hope everyone will come out to enjoy a fun day of ______[131] and getting to know each other better.\", \"vi\": \"Chúng tôi hy vọng tất cả mọi người sẽ tham gia để tận hưởng một ngày vui vẻ ______[131] và tìm hiểu rõ hơn về nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [131]}, {\"en\": \"Veronica Erikson is organizing a carpool so that employees ______[132] rides to the site.\", \"vi\": \"Veronica Erikson đang tổ chức việc đi chung xe để nhân viên ______[132] chuyến đi đến địa điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [132]}, {\"en\": \"If you are one of the drivers, you will be reimbursed for the fuel that you use.\", \"vi\": \"Nếu bạn là một trong những tài xế, bạn sẽ được hoàn lại chi phí nhiên liệu đã sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We know that some of you have heavy workloads right now.\", \"vi\": \"Chúng tôi biết rằng một số bạn đang có khối lượng công việc nặng nề vào lúc này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"______[133] you should not assume that this means you will be unable to attend the event.\", \"vi\": \"______[133] bạn không nên cho rằng điều này có nghĩa là bạn sẽ không thể tham gia sự kiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [133]}, {\"en\": \"______[134].\", \"vi\": \"______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [134]}, {\"en\": \"If you have concerns in this area, please bring them to your supervisor.\", \"vi\": \"Nếu bạn có lo lắng về vấn đề này, vui lòng trao đổi với người quản lý trực tiếp của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '58ac35bc-5dc8-4557-ac08-ac7fc30fa7f8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mount Slagle Aerial Tour\", \"vi\": \"Chuyến tham quan từ trên cao ngọn núi Slagle\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"https://www.larosetours.com/msat\", \"vi\": \"https://www.larosetours.com/msat\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Let Larose Tours take you on a helicopter adventure!\", \"vi\": \"Hãy để Larose Tours dẫn quý vị tham gia một chuyến phiêu lưu bằng trực thăng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"This one-hour flight first passes over historic downtown Larose on its way to the main attraction: a stunning overhead view of Mount Slagle, an active volcano.\", \"vi\": \"Chuyến bay kéo dài một giờ này sẽ bay qua khu trung tâm lịch sử của Larose trước khi đến điểm tham quan chính: một khung cảnh từ trên cao tuyệt đẹp của Núi Slagle, một ngọn núi lửa đang hoạt động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Returning over the surrounding rainforest, passengers will also spot waterfalls so remote that they can only be observed from the air.\", \"vi\": \"Khi bay trở lại qua khu rừng nhiệt đới xung quanh, quý khách cũng sẽ được chiêm ngưỡng những thác nước hẻo lánh đến mức chỉ có thể quan sát được từ trên không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"A guide is on hand throughout to provide interesting commentary and answer questions.\", \"vi\": \"Một hướng dẫn viên sẽ luôn túc trực để cung cấp những lời bình luận thú vị và giải đáp thắc mắc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The Mount Slagle Aerial Tour begins and ends at Larose Airport.\", \"vi\": \"Chuyến tham quan bằng đường hàng không ngắm núi Slagle bắt đầu và kết thúc tại Sân bay Larose.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It departs at 10 A.M., 1 P.M., and 3 P.M., Monday through Friday.\", \"vi\": \"Chuyến xe khởi hành vào lúc 10 giờ sáng, 1 giờ chiều và 3 giờ chiều, từ thứ Hai đến thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We are also available for custom individual and group helicopter tours of the mountain; for more information, visit this page.\", \"vi\": \"Chúng tôi cũng cung cấp các tour tham quan bằng trực thăng theo yêu cầu dành cho cá nhân và nhóm tại ngọn núi này; để biết thêm thông tin, vui lòng truy cập trang này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Mount Slagle Aerial Tour, April 27 at 10 A.M.\\n2 adults, 2 children - $1,540.00\", \"vi\": \"Chuyến tham quan từ trên cao ngọn núi Slagle, ngày 27 tháng 4 lúc 10 giờ sáng\\n2 người lớn, 2 trẻ em - 1.540,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Myrick Cave Tour, April 28 at 9 A.M.\\n2 adults, 2 children - $192.00\", \"vi\": \"Chuyến tham quan hang động Myrick, ngày 28 tháng 4 lúc 9 giờ sáng\\n2 người lớn, 2 trẻ em - 192,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Total - $1,732.00\", \"vi\": \"Tổng cộng - 1.732,00 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Larose Tours\", \"vi\": \"Larose Tours\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"https://www.larosetours.com/confirmation\", \"vi\": \"https://www.larosetours.com/confirmation\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Thank you for reserving the following tours.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã đặt trước các tour du lịch sau đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"In addition to the reservation details, please ensure that your contact information below is correct so that Larose will be able to provide you with instructions or updates about your tours.\", \"vi\": \"Ngoài các thông tin chi tiết về đặt chỗ, xin vui lòng đảm bảo rằng thông tin liên lạc của quý khách dưới đây là chính xác để Larose có thể cung cấp cho quý khách các hướng dẫn hoặc thông tin cập nhật về các tour du lịch của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Reservation Confirmation No.: 984533\", \"vi\": \"Số xác nhận đặt chỗ: 984533\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Customer Information\", \"vi\": \"Thông tin khách hàng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Name: Devin Rice\", \"vi\": \"Họ tên: Devin Rice\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Phone: (707) 555-0149\", \"vi\": \"Điện thoại: (707) 555-0149\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"E-mail: devin.rice@obymail.com\", \"vi\": \"Email: devin.rice@obymail.com\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Reservation Details\", \"vi\": \"Chi tiết đặt chỗ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Payment Completed (Credit card ending in 4308)\", \"vi\": \"Thanh toán đã hoàn tất (Thẻ tín dụng có bốn chữ số cuối là 4308)\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"From: customerservice@larosetours.com\", \"vi\": \"Nguồn: customerservice@larosetours.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"To: devin.rice@obymail.com\", \"vi\": \"Gửi tới: devin.rice@obymail.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Subject: Tour cancellation\", \"vi\": \"Chủ đề: Hủy chuyến tham quan\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date: April 26\", \"vi\": \"Ngày: 26 tháng 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Dear Mr. Rice,\", \"vi\": \"Kính gửi ông Rice,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Larose Tours is sorry to inform you that the Mount Slagle Aerial Tour scheduled for 10 A.M. tomorrow has been canceled.\", \"vi\": \"Larose Tours xin thông báo rằng chuyến tham quan ngắm cảnh từ trên cao tại Núi Slagle dự kiến diễn ra vào lúc 10 giờ sáng ngày mai đã bị hủy bỏ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"The weather forecast is predicting strong winds and rain through the afternoon, and helicopter flight is unsafe in those conditions.\", \"vi\": \"Dự báo thời tiết cho biết sẽ có gió mạnh và mưa kéo dài suốt buổi chiều, và việc bay bằng trực thăng trong điều kiện như vậy là không an toàn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Since the inclement weather is not expected to last long, though, we encourage you to rebook the tour.\", \"vi\": \"Tuy nhiên, do thời tiết xấu được dự báo sẽ không kéo dài, chúng tôi khuyến khích quý vị đặt lại tour.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"We just had a customer cancellation that left an opening large enough for your party at 1 P.M. on April 29.\", \"vi\": \"Vừa có một khách hàng hủy đặt chỗ, do đó hiện còn một chỗ trống đủ lớn để đón đoàn quý vị vào lúc 1 giờ chiều ngày 29 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Please call us at (808) 555-0173 if you would like to claim those spots.\", \"vi\": \"Nếu quý vị muốn đăng ký các chỗ này, xin vui lòng gọi cho chúng tôi theo số (808) 555-0173.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Otherwise, we are happy to provide you with a full refund via your original payment method.\", \"vi\": \"Nếu không, chúng tôi sẵn lòng hoàn trả toàn bộ số tiền cho quý khách thông qua phương thức thanh toán ban đầu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"You can initiate the process by responding to this e-mail or dropping in our office when you come for your cave tour.\", \"vi\": \"Quý vị có thể bắt đầu thủ tục bằng cách trả lời email này hoặc ghé qua văn phòng của chúng tôi khi quý vị đến tham gia tour tham quan hang động.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Hana Inoue, Customer Service Specialist\", \"vi\": \"Hana Inoue, Chuyên viên Dịch vụ Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Larose Tours\", \"vi\": \"Larose Tours\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}]' WHERE `id` = '58be65f4-498d-4329-a7e1-424924e38cda';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Gabriel Li (9:10 A.M.)\", \"vi\": \"Gabriel Li (9 giờ 10 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Good morning, everyone.\", \"vi\": \"Xin chào buổi sáng, thưa quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I want to remind you that Larkin Landscaping will be here at Derryco tomorrow morning to remove the trees from the front parking area.\", \"vi\": \"Tôi xin nhắc lại với quý vị rằng công ty Larkin Landscaping sẽ có mặt tại Derryco vào sáng mai để tiến hành chặt bỏ các cây xanh tại khu vực bãi đỗ xe phía trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"My workers will block off the area before the contractor arrives, so you and your staff should plan to find parking elsewhere or use public transit.\", \"vi\": \"Các nhân viên của tôi sẽ phong tỏa khu vực này trước khi nhà thầu đến, vì vậy quý vị và các nhân viên của quý vị nên sắp xếp tìm chỗ đỗ xe ở nơi khác hoặc sử dụng phương tiện giao thông công cộng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Ava Abberton (9:11 A.M.)\", \"vi\": \"Ava Abberton (9 giờ 11 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I have a client, Jan McGonagle, who will be driving in from Belfast to meet with me at 10:00 A.M. What should I tell her?\", \"vi\": \"Tôi có một khách hàng tên là Jan McGonagle, người sẽ lái xe từ Belfast đến để gặp tôi vào lúc 10 giờ sáng. Tôi nên nói gì với cô ấy đây?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Can she contact the facilities department?\", \"vi\": \"Cô ấy có thể liên hệ với phòng Quản lý cơ sở vật chất được không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Martin Beattie (9:12 A.M.)\", \"vi\": \"Martin Beattie (9 giờ 12 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"There\'s heavy rain in the forecast.\", \"vi\": \"Dự báo thời tiết cho biết sẽ có mưa lớn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Are you sure the tree work will go forward?\", \"vi\": \"Quý vị có chắc chắn rằng công việc chăm sóc cây cối sẽ được tiến hành không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Gabriel Li (9:13 A.M.)\", \"vi\": \"Gabriel Li (9 giờ 13 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Yes, give Ms. McGonagle my mobile phone number and have her call me when she arrives.\", \"vi\": \"Vâng, xin vui lòng cho cô McGonagle số điện thoại di động của tôi và bảo cô ấy gọi cho tôi khi cô ấy đến.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I will direct her around the back.\", \"vi\": \"Tôi sẽ dẫn cô ấy ra phía sau.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The spots there will be reserved for visitors only.\", \"vi\": \"Các chỗ đỗ xe tại đó sẽ được dành riêng cho khách tham quan.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Gabriel Li (9:14 A.M.)\", \"vi\": \"Gabriel Li (9 giờ 14 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"And yes, Larkin assured me the crew comes out rain or shine.\", \"vi\": \"Và đúng vậy, ông Larkin đã đảm bảo với tôi rằng đội ngũ nhân viên sẽ vẫn ra làm việc dù trời mưa hay nắng.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Daniel Deegan (9:15 A.M.)\", \"vi\": \"Daniel Deegan (9 giờ 15 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Remember, too, that we can approve team members to work from home tomorrow.\", \"vi\": \"Xin hãy lưu ý thêm rằng chúng ta có thể phê duyệt cho các thành viên trong nhóm làm việc tại nhà vào ngày mai.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Just make sure that all conference calls are listed on the master schedule on the intranet.\", \"vi\": \"Xin vui lòng đảm bảo rằng tất cả các cuộc họp qua điện thoại đều được liệt kê trong lịch trình tổng thể trên mạng nội bộ.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Gabriel Li (9:16 A.M.)\", \"vi\": \"Gabriel Li (9 giờ 16 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Right.\", \"vi\": \"Đúng vậy.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Thank you, all.\", \"vi\": \"Xin cảm ơn tất cả quý vị.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '591b489b-1a8e-4bbf-801e-3aa7b529dcd9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Steel Wheels Vehicle Insurance\", \"vi\": \"Bảo hiểm xe cơ giới Steel Wheels\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"With a top-of-the-line car, you should have top-of-the-line protection.\", \"vi\": \"Với một chiếc xe thuộc phân khúc cao cấp, quý vị xứng đáng được hưởng mức độ bảo vệ cao cấp nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Choose whichever plan best suits your needs.\", \"vi\": \"Hãy lựa chọn gói dịch vụ phù hợp nhất với nhu cầu của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Client: Ming Xiong\\nInsurance: Steel Wheels - Date: 13 December\", \"vi\": \"Khách hàng: Ming Xiong\\nCông ty bảo hiểm: Steel Wheels - Ngày: 13 tháng 12\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Service Received - Covered by Insurance - Billable to Customer\", \"vi\": \"Đã nhận dịch vụ - Được bảo hiểm chi trả - Có thể lập hóa đơn cho khách hàng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Replaced split radiator hose and clamps - $120 - $0\", \"vi\": \"Đã thay ống tản nhiệt bị nứt và các kẹp - 120 đô la - 0 đô la\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"New floor mats - $0 - $250\", \"vi\": \"Thảm lót sàn mới - 0 - 250 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Total - $120 - $250\", \"vi\": \"Tổng cộng - 120 USD - 250 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Lum Motors Sales and Service\", \"vi\": \"Bộ phận Bán hàng và Dịch vụ của Lum Motors\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Auto Forum\", \"vi\": \"Diễn đàn Ô tô\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Maintenance Plan: Includes an annual inspection, testing, and monthly oil changes\", \"vi\": \"Kế hoạch bảo dưỡng: Bao gồm kiểm tra, thử nghiệm hàng năm và thay dầu hàng tháng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Repair Plan: Covers repairs needed to the engine and other major systems, including electrical, exhaust, and cooling.\", \"vi\": \"Gói bảo dưỡng: Bao gồm các hạng mục sửa chữa cần thiết cho động cơ và các hệ thống chính khác, bao gồm hệ thống điện, hệ thống xả và hệ thống làm mát.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Includes all replacement parts\", \"vi\": \"Bao gồm tất cả các bộ phận thay thế\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Cleaning Plan: Complete interior and exterior cleaning every three months, including replacement of floor mats when necessary\", \"vi\": \"Kế hoạch vệ sinh: Tiến hành vệ sinh toàn diện cả bên trong và bên ngoài xe mỗi ba tháng một lần, bao gồm việc thay thế thảm sàn khi cần thiết\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Combination Plan: Includes benefits of all three plans\", \"vi\": \"Gói kết hợp: Bao gồm các quyền lợi của cả ba gói\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Monthly fees vary by vehicle model.\", \"vi\": \"Phí hàng tháng sẽ khác nhau tùy theo mẫu xe.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"E-mail us at planinfo@steelwheelsins.com for specific cost and plan information.\", \"vi\": \"Vui lòng gửi email cho chúng tôi theo địa chỉ planinfo@steelwheelsins.com để biết thông tin chi tiết về chi phí và các gói dịch vụ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"If you wish to examine or keep any parts that have been replaced, please ask to speak to the mechanic when you pick up your vehicle.\", \"vi\": \"Nếu quý khách muốn kiểm tra hoặc giữ lại bất kỳ bộ phận nào đã được thay thế, xin vui lòng yêu cầu được gặp thợ cơ khí khi quý khách đến nhận xe.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Parts will not be kept after the service date.\", \"vi\": \"Các bộ phận sẽ không được lưu giữ sau ngày bảo dưỡng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Recommended products:\", \"vi\": \"Các sản phẩm được đề xuất:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Goldings synthetic oil for smoother engine functioning\", \"vi\": \"Dầu tổng hợp Goldings giúp động cơ vận hành êm ái hơn\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Harmon air filters to protect your engine\", \"vi\": \"Bộ lọc không khí Harmon giúp bảo vệ động cơ của quý vị\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Lift-brite fabric treatment to protect cloth seat upholstery\", \"vi\": \"Chất xử lý vải Lift-brite nhằm bảo vệ lớp bọc ghế bằng vải\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Eversweet spray to keep your interior smelling fresh\", \"vi\": \"Chai xịt Eversweet giúp không gian nội thất của quý vị luôn thơm mát\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"www.jkarcare.com/forum/auto-maintenence/interior ▶\", \"vi\": \"www.jkarcare.com/forum/auto-maintenence/interior ▶\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Great product\", \"vi\": \"Sản phẩm tuyệt vời\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"by Ming Xiong/29 December 7:43 PM\", \"vi\": \"bởi Ming Xiong/29 tháng 12, 7 giờ 43 phút tối\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I can\'t recall the name, but I bought this product based on a recommendation from my car dealer\'s service department, and it works very well.\", \"vi\": \"Tôi không nhớ tên sản phẩm này, nhưng tôi đã mua nó theo lời giới thiệu từ bộ phận dịch vụ của đại lý ô tô, và sản phẩm này hoạt động rất hiệu quả.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"The liquid comes in a blue bottle with yellow lettering.\", \"vi\": \"Chất lỏng này được đựng trong một chai màu xanh dương có chữ màu vàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"As a father of three, I have a hard time keeping the interior of my car clean.\", \"vi\": \"Là một người cha có ba con, tôi gặp không ít khó khăn trong việc giữ cho nội thất chiếc xe của mình luôn sạch sẽ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Many products claim to protect against stains, but this one actually works.\", \"vi\": \"Có rất nhiều sản phẩm tự quảng cáo là có khả năng chống bám bẩn, nhưng sản phẩm này mới thực sự hiệu quả.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"All our spills wipe right off.\", \"vi\": \"Tất cả các vết bẩn do chất lỏng tràn ra đều có thể lau sạch ngay lập tức.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Even more impressive is the price.\", \"vi\": \"Điều còn ấn tượng hơn nữa chính là mức giá.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"It costs about the same as other brands but works much better.\", \"vi\": \"Giá của sản phẩm này tương đương với các thương hiệu khác nhưng hiệu quả lại tốt hơn hẳn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '59415e15-92f8-488e-a897-13e3d475760b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Claro Vision\", \"vi\": \"Claro Vision\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The difference is clear.\", \"vi\": \"Sự khác biệt là rất rõ ràng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Take advantage of our limited-time offer:\", \"vi\": \"Hãy tận dụng ưu đãi có thời hạn của chúng tôi:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"50% off all eyeglass frames through 30 September\", \"vi\": \"Giảm giá 50% cho tất cả các loại gọng kính đến hết ngày 30 tháng 9\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Other advantages available today and every day:\", \"vi\": \"Các lợi ích khác hiện có ngay hôm nay và mỗi ngày:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"- Free eyeglass fittings and adjustments\", \"vi\": \"- Dịch vụ đo và điều chỉnh kính miễn phí\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"- Money-back guarantee if you are not completely satisfied\", \"vi\": \"- Đảm bảo hoàn tiền nếu quý vị không hoàn toàn hài lòng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"- More than 500 locations in shopping malls throughout Canada\", \"vi\": \"- Hơn 500 cửa hàng tại các trung tâm thương mại trên khắp Canada\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"- Low-cost vision checkups by licensed opticians\", \"vi\": \"- Dịch vụ khám mắt với chi phí hợp lý do các chuyên viên khúc xạ có giấy phép hành nghề thực hiện\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To find a store near you, visit www.clarovision.ca/locations, or call 416-555-0122 today!\", \"vi\": \"Để tìm cửa hàng gần quý vị, vui lòng truy cập www.clarovision.ca/locations hoặc gọi số 416-555-0122 ngay hôm nay!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '594e04a4-da67-4e26-8fd2-72291b02c569';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"(May 19)—Meat substitutes, which are plant-based foods with meat-like tastes and textures, are currently enjoying a boom nationwide.\", \"vi\": \"(Ngày 19 tháng 5)—Các sản phẩm thay thế thịt, vốn là thực phẩm có nguồn gốc từ thực vật với hương vị và kết cấu giống thịt, hiện đang bùng nổ trên toàn quốc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The market for such products grew nearly 50% in the past year, and they can now be found in a ______[131] range of settings, from supermarket shelves to fast-food restaurants.\", \"vi\": \"Thị trường cho các sản phẩm như vậy đã tăng trưởng gần 50% trong năm qua, và giờ đây chúng có thể được tìm thấy ở một phạm vi ______[131] các địa điểm, từ kệ siêu thị cho đến các nhà hàng thức ăn nhanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"A major reason for this trend is changing consumer ______[132] affected by concern about the environmental impact of livestock farming.\", \"vi\": \"Một lý do chính cho xu hướng này là sự thay đổi trong sở thích của người tiêu dùng ______[132] bị ảnh hưởng bởi mối lo ngại về tác động môi trường của việc chăn nuôi gia súc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132]}, {\"en\": \"According to Ivan Ortega, spokesperson for the Plant Based Food Association, the lower prices and better taste of newer meat substitutes have contributed ______[133].\", \"vi\": \"Theo Ivan Ortega, phát ngôn viên của Hiệp hội Thực phẩm Gốc Thực vật, giá cả thấp hơn và hương vị ngon hơn của các sản phẩm thay thế thịt mới hơn đã đóng góp ______[133].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [133]}, {\"en\": \"Mr. Ortega believes that this sector of the industry will only continue to grow in the future.\", \"vi\": \"Ông Ortega tin rằng lĩnh vực này của ngành công nghiệp sẽ chỉ tiếp tục phát triển trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[134].\", \"vi\": \"______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [134]}]' WHERE `id` = '5956bc2b-9652-44b2-9fc9-62c890fe44f9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: rogelio.garza@gerimail.net\", \"vi\": \"Gửi tới: rogelio.garza@gerimail.net\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: sasha_lombardo@onyxmail.com\", \"vi\": \"Nguồn: sasha_lombardo@onyxmail.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: January 18\", \"vi\": \"Ngày: 18 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: My cookbook\", \"vi\": \"Chủ đề: Cuốn sách nấu ăn của tôi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Draft manuscript\", \"vi\": \"Tệp đính kèm: Bản thảo bài viết\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Rogelio,\", \"vi\": \"Rogelio,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Here is the latest draft of the cookbook I will be self-publishing.\", \"vi\": \"Dưới đây là bản thảo mới nhất của cuốn sách nấu ăn mà tôi sẽ tự xuất bản.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Thank you for reviewing my recipes to ensure they are easy to follow.\", \"vi\": \"Xin cảm ơn quý vị đã xem xét các công thức nấu ăn của tôi để đảm bảo chúng dễ thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Your input is much appreciated.\", \"vi\": \"Chúng tôi rất trân trọng ý kiến đóng góp của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"This project has taken a lot of my energy over the past few years, and I am thrilled it is finally coming together.\", \"vi\": \"Dự án này đã tiêu tốn rất nhiều sức lực của tôi trong vài năm qua, và tôi vô cùng phấn khởi khi cuối cùng mọi thứ cũng đang dần đi vào quỹ đạo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I already received feedback from a few others and was told that the instructions in some places were confusingly worded.\", \"vi\": \"Tôi đã nhận được ý kiến phản hồi từ một số người khác và được cho biết rằng cách diễn đạt của hướng dẫn ở một số chỗ còn gây nhầm lẫn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I am interested to know if you think so as well.\", \"vi\": \"Tôi rất muốn biết liệu quý vị có cùng quan điểm như vậy hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I do have one request—when you respond, can you please include your comments in the margins so they are all in this one document?\", \"vi\": \"Tôi có một yêu cầu—khi quý vị trả lời, xin vui lòng ghi các ý kiến của quý vị vào lề trang để tất cả đều được tập hợp trong tài liệu này, được không ạ?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"You\'ll also notice that some pages have special boxes marked with a big red X. You can ignore those.\", \"vi\": \"Quý vị cũng sẽ nhận thấy rằng một số trang có các ô đặc biệt được đánh dấu bằng một chữ X màu đỏ lớn. Quý vị có thể bỏ qua những ô đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I did not take great pictures of certain steps, so the Xs are reminders to take better ones to insert later.\", \"vi\": \"Tôi chưa chụp được những bức ảnh đẹp cho một số bước nhất định, vì vậy các ký hiệu X ở đây nhằm nhắc nhở tôi phải chụp những bức ảnh đẹp hơn để chèn vào sau này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Thanks again!\", \"vi\": \"Một lần nữa xin cảm ơn!\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Sasha\", \"vi\": \"Sasha\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '5976053a-dbc0-43e8-b9fb-5e3620aa9f8f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Brightman Heating and Cooling\", \"vi\": \"Brightman Heating and Cooling\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"16 Primrose Way\", \"vi\": \"16 Primrose Way\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Sydney NSW 2146\", \"vi\": \"Sydney NSW 2146\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"(02) 5550 8899\", \"vi\": \"(02) 5550 8899\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"www.brightmanheatingandcooling.com.au\", \"vi\": \"www.brightmanheatingandcooling.com.au\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"15 May\", \"vi\": \"Ngày 15 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Alia Bajpa\", \"vi\": \"Alia Bajpa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"422 Hudson St.\", \"vi\": \"422 Hudson St.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Sydney NSW 2000\", \"vi\": \"Sydney NSW 2000\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Dear Ms. Bajpa:\", \"vi\": \"Kính gửi bà Bajpa:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We have some important news to share with you.\", \"vi\": \"Chúng tôi có một số thông tin quan trọng muốn chia sẻ với quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We ______[143] to retire and close the company after 40 years in the business.\", \"vi\": \"Chúng tôi ______[143] nghỉ hưu và đóng cửa công ty sau 40 năm hoạt động trong ngành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [143]}, {\"en\": \"______[144], we want to make sure that you do not experience any disruption to your service.\", \"vi\": \"______[144], chúng tôi muốn đảm bảo rằng quý khách không gặp phải bất kỳ sự gián đoạn dịch vụ nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [144]}, {\"en\": \"For that reason, we have arranged for Kondo\'s Heating and Air to begin providing service to you effective on 1 June.\", \"vi\": \"Vì lý do đó, chúng tôi đã sắp xếp để công ty Kondo\'s Heating and Air bắt đầu cung cấp dịch vụ cho quý khách có hiệu lực từ ngày 1 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I\'m certain you will be pleased with ______[145] service.\", \"vi\": \"Tôi chắc chắn rằng quý khách sẽ hài lòng với dịch vụ ______[145].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": [145]}, {\"en\": \"Kondo\'s is a wonderful company with experienced, highly skilled technicians.\", \"vi\": \"Kondo\'s là một công ty tuyệt vời với đội ngũ kỹ thuật viên giàu kinh nghiệm và tay nghề cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"______[146].\", \"vi\": \"______[146].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": [146]}, {\"en\": \"If you have any questions, please do not hesitate to call.\", \"vi\": \"Nếu quý khách có bất kỳ câu hỏi nào, xin vui lòng gọi điện thoại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Nathaniel and Constance Brightman\", \"vi\": \"Nathaniel và Constance Brightman\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '5985c3b3-242d-4eb0-861c-dc1508b8d200';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Mary Lim <mlim412@mailhouz.com>\", \"vi\": \"Gửi tới: Mary Lim <mlim412@mailhouz.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: George Siskos <gsiskos@crehcorp.com>\", \"vi\": \"Từ: George Siskos <gsiskos@crehcorp.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: September 24\", \"vi\": \"Ngày: 24 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Referral from Joe Argento\", \"vi\": \"Chủ đề: Thư giới thiệu từ ông Joe Argento\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Information\", \"vi\": \"Tài liệu đính kèm: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Hello Ms. Lim,\", \"vi\": \"Xin chào bà Lim,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am George Siskos, Recruiting Manager at Crehcorp Ltd. We are currently looking to hire an accounting clerk, and Joe Argento recommended you.\", \"vi\": \"Tôi là George Siskos, Trưởng phòng Tuyển dụng tại Công ty Crehcorp Ltd. Hiện tại, chúng tôi đang có nhu cầu tuyển dụng một nhân viên kế toán, và ông Joe Argento đã giới thiệu quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"From what Joe told me, your background makes you a good fit for the role (posting attached).\", \"vi\": \"Theo những gì Joe đã chia sẻ với tôi, kinh nghiệm của quý vị khiến quý vị rất phù hợp với vị trí này (thông tin tuyển dụng đính kèm).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"If you are interested in learning more about Crehcorp and the position, I will be happy to provide further information.\", \"vi\": \"Nếu quý vị quan tâm và muốn tìm hiểu thêm về Crehcorp cũng như vị trí công việc này, tôi rất sẵn lòng cung cấp thêm thông tin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Let me know when you are available to talk, and I will give you a call.\", \"vi\": \"Xin vui lòng cho tôi biết khi nào quý vị rảnh để trao đổi, và tôi sẽ gọi điện cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I look forward to hearing back from you!\", \"vi\": \"Tôi rất mong nhận được phản hồi từ quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"George Siskos\", \"vi\": \"George Siskos\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '59a40edf-b116-4a94-bdf1-5a3a04762eb0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"April 2\", \"vi\": \"Ngày 2 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear TP&G Customer,\", \"vi\": \"Kính gửi Khách hàng của TP&G,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Takoradi Power & Gas (TP&G) is committed to providing every customer with dependable electricity service.\", \"vi\": \"Takoradi Power & Gas (TP&G) cam kết cung cấp cho mọi khách hàng dịch vụ điện năng đáng tin cậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"To this end, we need to make some improvements to our ___139___ .\", \"vi\": \"Vì mục đích này, chúng tôi cần thực hiện một số cải tiến đối với ___139___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [139]}, {\"en\": \"A maintenance crew will be upgrading transformers in your neighbourhood on or about 22 April, beginning at 10 A.M. ___140___ , we will need to shut off the electricity to residences in your area from approximately 10 A.M. to 1 P.M. on that day.\", \"vi\": \"Một đội ngũ bảo trì sẽ tiến hành nâng cấp các máy biến áp tại khu1 vực lân cận của quý vị vào hoặc khoảng ngày 22 tháng 4, bắt đầu lúc 10 giờ sáng. ___140___ , chúng tôi sẽ cần ngắt điện các khu dân cư trong khu vực của quý vị từ khoảng 10 giờ sáng đến 1 giờ chiều vào ngày hôm đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [140]}, {\"en\": \"___141___ .\", \"vi\": \"___141___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [141]}, {\"en\": \"We hope that by ___142___ this notice, any disruptions caused by the planned outage will be minimized.\", \"vi\": \"Chúng tôi hy vọng rằng bằng việc ___142___ thông báo này, mọi sự gián đoạn do đợt cúp điện có kế hoạch sẽ được giảm thiểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [142]}]' WHERE `id` = '59cc8cf2-bc9b-4b7f-b5cc-ec224b543c44';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Aisa Ito [10:08 A.M.] I\'m so glad I found this forum for users of Canomatik products!\", \"vi\": \"Aisa Ito [10:08 sáng] Tôi thực sự rất vui vì đã tìm thấy diễn đàn dành cho người dùng các sản phẩm của Canomatik này!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Has anyone tried the S20 can opener?\", \"vi\": \"Có ai đã từng dùng dụng cụ mở hộp S20 chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The electric can opener I\'ve had for years finally broke.\", \"vi\": \"Chiếc máy mở hộp điện mà tôi đã dùng suốt nhiều năm qua cuối cùng cũng hỏng rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Tanveer Kumar [10:10 A.M.] I bought one several years ago, but I don\'t think it was worth the money I spent.\", \"vi\": \"Tanveer Kumar [10 giờ 10 phút sáng] Tôi đã mua một chiếc cách đây vài năm, nhưng tôi không nghĩ rằng nó xứng đáng với số tiền tôi đã bỏ ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Ingrid Vogel [11:15 A.M.] I like mine.\", \"vi\": \"Ingrid Vogel [11 giờ 15 phút sáng] Tôi rất thích những món của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I used to struggle opening cans.\", \"vi\": \"Trước đây, tôi thường gặp khó khăn khi mở hộp thiếc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This one makes it easier to open cans of all sizes.\", \"vi\": \"Sản phẩm này giúp quý vị mở các lon có mọi kích cỡ một cách dễ dàng hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Laurie Jacobs [2:12 P.M.] The commercial version is expensive, but there is also a consumer version that costs less.\", \"vi\": \"Laurie Jacobs [2 giờ 12 phút chiều] Phiên bản thương mại có giá khá cao, nhưng cũng có một phiên bản dành cho người tiêu dùng với mức giá thấp hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"John Burwood [2:14 P.M.] I ordered mine online, and it was defective.\", \"vi\": \"John Burwood [14 giờ 14 phút] Tôi đã đặt mua sản phẩm của mình qua mạng, nhưng sản phẩm đó lại bị lỗi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I contacted the company\'s customer service department, and they sent me a new one that works just fine.\", \"vi\": \"Tôi đã liên hệ với bộ phận chăm sóc khách hàng của công ty, và họ đã gửi cho tôi một chiếc mới, hoạt động hoàn toàn bình thường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Laurie Jacobs [2:16 P.M.] I used to be a cook at a restaurant years ago, and we had a commercial-grade Canomatik can opener back then.\", \"vi\": \"Laurie Jacobs [2 giờ 16 phút chiều] Cách đây nhiều năm, tôi từng làm đầu bếp tại một nhà hàng, và hồi đó chúng tôi có một chiếc máy mở hộp Canomatik dành cho mục đích thương mại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I\'ve been using the consumer version at home for nearly a decade.\", \"vi\": \"Tôi đã sử dụng phiên bản dành cho người tiêu dùng tại nhà được gần một thập kỷ nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"It opens cans safely and easily.\", \"vi\": \"Sản phẩm này giúp mở nắp lon một cách an toàn và dễ dàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Aisa Ito [5:15 P.M.] Thanks, everyone.\", \"vi\": \"Aisa Ito [17 giờ 15 phút] Cảm ơn quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I\'ll give it a try.\", \"vi\": \"Tôi sẽ thử xem sao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '5a296782-d6ad-4282-89a7-50866dc99958';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"DIVERSIFY MUSEUM\", \"vi\": \"BẢO TÀNG ĐA DẠNG\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.diversifymuseum.org\", \"vi\": \"http://www.diversifymuseum.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"A Museum of Cross-Cultural History and Artifacts\", \"vi\": \"Bảo tàng Lịch sử và Di vật Liên văn hóa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We are proud to announce our newest exhibit: South American Art.\", \"vi\": \"Chúng tôi hân hạnh thông báo về triển lãm mới nhất của chúng tôi: Nghệ thuật Nam Mỹ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The exhibit will open on 7 June as part of the museum\'s ongoing Arts Around the World programme.\", \"vi\": \"Triển lãm sẽ khai mạc vào ngày 7 tháng 6, nằm trong khuôn khổ chương trình “Nghệ thuật khắp thế giới” đang được bảo tàng tổ chức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"All museum patrons who have paid the museum entrance fee may view the exhibit.\", \"vi\": \"Tất cả quý khách tham quan đã mua vé vào cửa bảo tàng đều có thể tham quan triển lãm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It will feature historical and contemporary artwork displays from renowned South American artists.\", \"vi\": \"Triển lãm này sẽ trưng bày các tác phẩm nghệ thuật lịch sử và đương đại của các nghệ sĩ nổi tiếng đến từ Nam Mỹ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The curator of the six-week exhibition, Julio Carrera, will bring his vast expertise to the museum.\", \"vi\": \"Ông Julio Carrera, người phụ trách triển lãm kéo dài sáu tuần này, sẽ mang đến cho bảo tàng những kiến thức chuyên môn sâu rộng của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Before joining the museum\'s management in March of this year, Mr. Carrera was the curator for the Brazilian Institute of the Arts for six years and spent three years studying ancient artifacts for the Centro de la Historia del Arte, an art preservation centre in Venezuela.\", \"vi\": \"Trước khi gia nhập ban quản lý bảo tàng vào tháng 3 năm nay, ông Carrera đã từng giữ chức vụ giám tuyển tại Viện Nghệ thuật Brazil trong sáu năm và dành ba năm để nghiên cứu các hiện vật cổ tại Centro de la Historia del Arte, một trung tâm bảo tồn nghệ thuật ở Venezuela.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The South American Art exhibit will include paintings, sculptures, crafting tools, clothing, jewellery, murals, and clay pottery from six South American countries.\", \"vi\": \"Triển lãm Nghệ thuật Nam Mỹ sẽ trưng bày các tác phẩm hội họa, điêu khắc, dụng cụ thủ công, trang phục, trang sức, tranh tường và đồ gốm từ sáu quốc gia Nam Mỹ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Visiting artists from these countries will provide art workshops on select dates in July.\", \"vi\": \"Các nghệ sĩ khách mời đến từ các quốc gia này sẽ tổ chức các buổi hội thảo nghệ thuật vào một số ngày nhất định trong tháng Bảy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The cost for each workshop is £10 in addition to the regular admission fee and includes basic art supplies.\", \"vi\": \"Chi phí cho mỗi buổi hội thảo là 10 bảng Anh, chưa bao gồm phí vào cửa thông thường, và đã bao gồm các vật liệu mỹ thuật cơ bản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '5a426c91-9d7e-4162-8594-f2a8284f6a57';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Quynh La Tran <tqla@tevanto.vn>\", \"vi\": \"To: Quynh La Tran <tqla@tevanto.vn>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Customercare@shoppedesjeans.fr\", \"vi\": \"Nguồn: Customercare@shoppedesjeans.fr\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: September 22\", \"vi\": \"Ngày: 22 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Re: Order #93887\", \"vi\": \"Trả lời: Đơn hàng số 93887\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Tran:\", \"vi\": \"Kính gửi bà Trần,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for contacting Shoppe des Jeans Customer Care about order #93887.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã liên hệ với Bộ phận Chăm sóc Khách hàng của Shoppe des Jeans về đơn hàng số 93887.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am sorry you are not happy with your purchase.\", \"vi\": \"Tôi rất tiếc vì quý khách không hài lòng với sản phẩm đã mua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The product you ordered, Women\'s Stretch Jeans size 36 in midnight blue, is one of our best-selling women\'s styles.\", \"vi\": \"Sản phẩm quý khách đã đặt hàng, quần jean co giãn dành cho nữ cỡ 36 màu xanh đêm, là một trong những mẫu quần jean nữ bán chạy nhất của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In order to get the dark blue color that makes these jeans such a standout, the fabric is dyed twice to deepen the color of the denim.\", \"vi\": \"Để tạo ra màu xanh đậm khiến chiếc quần jean này trở nên thật nổi bật, vải được nhuộm hai lần nhằm làm cho màu denim trở nên đậm hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The item\'s label clearly states that some dye may rub off on light-colored fabric or upholstery until the product has been washed several times.\", \"vi\": \"Nhãn mác của sản phẩm ghi rõ rằng một lượng nhỏ thuốc nhuộm có thể bị phai ra trên vải hoặc vải bọc có màu sáng cho đến khi sản phẩm được giặt vài lần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"It also suggests washing the jeans with dark colors only, as the dye may run in the wash.\", \"vi\": \"Ngoài ra, hướng dẫn này cũng khuyến nghị chỉ nên giặt quần jean cùng với các loại quần áo màu tối, vì thuốc nhuộm có thể bị phai khi giặt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"It is unfortunate that you did not see these warnings and that your sofa has become discolored as a result.\", \"vi\": \"Thật đáng tiếc là quý khách đã không để ý đến những cảnh báo này và do đó, chiếc ghế sofa của quý khách đã bị phai màu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Our goal at Shoppe des Jeans is 100% customer satisfaction with every purchase.\", \"vi\": \"Mục tiêu của chúng tôi tại Shoppe des Jeans là mang lại sự hài lòng 100% cho quý khách hàng trong mỗi lần mua sắm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"This kind of situation, however, is not covered under our customer service guarantee, since the issue with the dye is addressed on the product\'s label.\", \"vi\": \"Tuy nhiên, trường hợp này không nằm trong phạm vi bảo đảm dịch vụ khách hàng của chúng tôi, vì vấn đề liên quan đến chất nhuộm đã được nêu rõ trên nhãn sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I suggest you try treating the sofa with baking soda, followed by upholstery cleaner.\", \"vi\": \"Tôi đề nghị quý vị thử làm sạch ghế sofa bằng baking soda, sau đó dùng chất tẩy rửa chuyên dụng cho vải bọc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Bertine Olivier\", \"vi\": \"Bertine Olivier\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Customer Care Representative, Shoppe des Jeans\", \"vi\": \"Nhân viên Chăm sóc Khách hàng, Shoppe des Jeans\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '5a4c57e9-8707-4c5c-a0dd-675abd372bdc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Imogen Chambers <ichambers@championos.com>\", \"vi\": \"Gửi tới: Imogen Chambers <ichambers@championos.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Reginald Lee <rlee@cooperandcolsonlaw.org>\", \"vi\": \"Từ: Reginald Lee <rlee@cooperandcolsonlaw.org>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Re: Office supplies order\", \"vi\": \"Trả lời: Đơn đặt hàng văn phòng phẩm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: March 20\", \"vi\": \"Ngày: 20 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Chambers,\", \"vi\": \"Kính gửi bà Chambers,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We have a standing order filled by Champion Office Supply, with automatic delivery to us on the first day of each month.\", \"vi\": \"Chúng tôi có một đơn đặt hàng định kỳ do Champion Office Supply thực hiện, với dịch vụ giao hàng tự động đến cho chúng tôi vào ngày đầu tiên của mỗi tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am writing because we would like to modify our usual order for the upcoming month as outlined on the attached form.\", \"vi\": \"Tôi viết thư này vì chúng tôi mong muốn điều chỉnh đơn đặt hàng thông thường của chúng tôi cho tháng tới theo nội dung được nêu trong biểu mẫu đính kèm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please note that we would like the ink toner that we have ordered in the past to be replaced by a different brand as indicated.\", \"vi\": \"Xin lưu ý rằng chúng tôi mong muốn loại mực in mà chúng tôi đã đặt hàng trước đây sẽ được thay thế bằng một thương hiệu khác như đã nêu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Furthermore, we would like to add item WB918 to the order only this month, as we have recently hired new attorneys and we are preparing additional office spaces for them.\", \"vi\": \"Hơn nữa, chúng tôi mong muốn bổ sung mặt hàng WB918 vào đơn đặt hàng chỉ trong tháng này, bởi vì gần đây chúng tôi đã tuyển dụng thêm các luật sư mới và đang chuẩn bị thêm không gian văn phòng dành cho họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please use our credit card account that you have on file.\", \"vi\": \"Kính mong Quý khách vui lòng sử dụng thông tin tài khoản thẻ tín dụng mà Quý khách đã đăng ký với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We continue to be pleased with the quality of your merchandise, especially the recycled stationery products with our firm\'s logo.\", \"vi\": \"Chúng tôi vẫn luôn hài lòng với chất lượng hàng hóa của quý công ty, đặc biệt là các sản phẩm văn phòng phẩm làm từ nguyên liệu tái chế có in logo của công ty chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Xin cảm ơn.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Reginald Lee, Office Manager\", \"vi\": \"Ông Reginald Lee, Trưởng phòng Hành chính\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Cooper and Colson Law\", \"vi\": \"Văn phòng Luật sư Cooper và Colson\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Item Description - Item Number - Quantity - Price Per Unit - Itemized Total\", \"vi\": \"Mô tả mặt hàng - Mã hàng - Số lượng - Giá mỗi đơn vị - Tổng giá từng mặt hàng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Printed letterhead - LH228 - 10 Reams - 54.00 - 540.00\", \"vi\": \"Giấy tiêu đề in sẵn - LH228 - 10 rìu - 54,00 - 540,00\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Whiteboard pens - WP263 - 10 Packages of 4 - 4.99 - 49.90\", \"vi\": \"Bút viết bảng trắng - WP263 - 10 gói, mỗi gói 4 cây - 4,99 - 49,90\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Cytronics ink toner cartridge - CP576 - 8 - 42.00 - 336.00\", \"vi\": \"Hộp mực in Cytronics - CP576 - 8 - 42,00 - 336,00\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Witeglow Magnetic Whiteboard (50\\\" x 35\\\") - WB918 - 4 - 79.99 - 319.96\", \"vi\": \"Bảng trắng từ tính Witeglow (50\\\" x 35\\\") - WB918 - 4 - 79,99 - 319,96\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"TAX: 74.75\", \"vi\": \"Thuế: 74,75\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"TOTAL: $1320.61\", \"vi\": \"Tổng cộng: 1.320,61 USD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Order for: Cooper and Colson Law     Delivery date: April 1\", \"vi\": \"Đơn đặt hàng dành cho: Văn phòng Luật sư Cooper và Colson     Ngày giao hàng: 1 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Contact: Reginald Lee\", \"vi\": \"Liên hệ: Reginald Lee\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Champion Office Supply\", \"vi\": \"Champion - Cung cấp văn phòng phẩm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"To: Reginald Lee <rlee@cooperandcolsonlaw.org>\", \"vi\": \"Gửi tới: Reginald Lee <rlee@cooperandcolsonlaw.org>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"From: Imogen Chambers <ichambers@championos.com>\", \"vi\": \"Từ: Imogen Chambers <ichambers@championos.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Re: Office supplies order\", \"vi\": \"Trả lời: Đơn đặt hàng văn phòng phẩm\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Date: March 21\", \"vi\": \"Ngày: 21 tháng 3\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Dear Mr. Lee,\", \"vi\": \"Kính gửi ông Lee,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"We would be happy to accommodate your requests as outlined on your order form.\", \"vi\": \"Chúng tôi rất sẵn lòng đáp ứng các yêu cầu của quý khách như đã nêu trong phiếu đặt hàng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Unfortunately, however, we are currently out of the Witeglow brand whiteboards.\", \"vi\": \"Tuy nhiên, thật đáng tiếc là hiện tại chúng tôi đã hết hàng bảng trắng thương hiệu Witeglow.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I can recommend another brand of magnetic whiteboard that has been well liked by other customers, called Stellar Whiteboards.\", \"vi\": \"Tôi xin giới thiệu một thương hiệu bảng trắng từ tính khác đã nhận được nhiều phản hồi tích cực từ các khách hàng khác, đó là Stellar Whiteboards.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"They are considered the best on the market.\", \"vi\": \"Chúng được đánh giá là những sản phẩm tốt nhất trên thị trường.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"They are typically $85 each, but I am willing to provide four at the same cost of the Witeglow brand, if you would like to give them a try.\", \"vi\": \"Thông thường, mỗi chiếc có giá 85 đô la, nhưng nếu quý vị muốn dùng thử, tôi sẵn sàng cung cấp bốn chiếc với mức giá tương đương với thương hiệu Witeglow.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Just let me know.\", \"vi\": \"Xin chỉ cần cho tôi biết là được.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Xin cảm ơn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Imogen Chambers\", \"vi\": \"Imogen Chambers\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}]' WHERE `id` = '5a793aae-3a39-48a5-a802-7afb942cb9ba';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Manuel Cabrera [9:18 A.M.]\", \"vi\": \"Manuel Cabrera [9:18 sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hello, Sara.\", \"vi\": \"Xin chào, Sara.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Our client Mr. Forsyth is changing his mind about the color scheme for his kitchen.\", \"vi\": \"Khách hàng của chúng tôi, ông Forsyth, đang thay đổi ý định về cách phối màu cho căn bếp của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Can you send me the photos from the Maroney project we completed last autumn?\", \"vi\": \"Xin vui lòng gửi cho tôi những bức ảnh về dự án Maroney mà chúng ta đã hoàn thành vào mùa thu năm ngoái được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Sara Baird [9:20 A.M.]\", \"vi\": \"Sara Baird [9 giờ 20 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Sure.\", \"vi\": \"Được ạ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Do you want me to send just the kitchen pictures?\", \"vi\": \"Quý vị có muốn tôi chỉ gửi những bức ảnh về nhà bếp không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Manuel Cabrera [9:21 A.M.]\", \"vi\": \"Manuel Cabrera [9 giờ 21 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Send those of the kitchen and living room, please.\", \"vi\": \"Xin vui lòng gửi những bức ảnh chụp phòng bếp và phòng khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Sara Baird [9:22 A.M.]\", \"vi\": \"Sara Baird [9 giờ 22 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"They are on their way.\", \"vi\": \"Họ đang trên đường đến đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I have also included pictures of the Thackers\' kitchen from a couple of years ago.\", \"vi\": \"Tôi cũng đã đính kèm một số hình ảnh về nhà bếp của gia đình Thacker chụp cách đây vài năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We created a similar style for them.\", \"vi\": \"Chúng tôi đã thiết kế một phong cách tương tự cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Manuel Cabrera [9:23 A.M.]\", \"vi\": \"Manuel Cabrera [9 giờ 23 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Good thinking.\", \"vi\": \"Ý kiến hay đấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thank you!\", \"vi\": \"Xin cảm ơn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '5a9cf85a-b6ac-49e5-8da6-b688d63754f4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"PAGA\'s Seventeenth Annual Botanical and Horticultural Expo, July 10–13\", \"vi\": \"Triển lãm Thực vật và Trồng trọt Thường niên lần thứ 17 của PAGA, từ ngày 10 đến ngày 13 tháng 7\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Starkey Convention Center, Pittsburgh, Pennsylvania\", \"vi\": \"Trung tâm Hội nghị Starkey, Pittsburgh, Pennsylvania\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The Pittsburgh Area Garden Association (PAGA) invites companies to support its garden exhibition, which last year was attended by nearly 40,000 visitors.\", \"vi\": \"Hiệp hội Vườn khu vực Pittsburgh (PAGA) kính mời các doanh nghiệp hỗ trợ triển lãm vườn của hiệp hội, sự kiện này năm ngoái đã thu hút gần 40.000 khách tham quan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"This is a cost-effective means of reaching home gardeners and outdoor enthusiasts and enhances your firm\'s commercial performance.\", \"vi\": \"Đây là một phương thức hiệu quả về mặt chi phí để tiếp cận những người yêu thích làm vườn tại nhà và những người đam mê các hoạt động ngoài trời, đồng thời góp phần nâng cao hiệu quả kinh doanh của công ty quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"PAGA is pleased to offer the following levels of corporate sponsorship with corresponding benefits.\", \"vi\": \"PAGA hân hạnh giới thiệu các mức tài trợ doanh nghiệp sau đây cùng với các quyền lợi tương ứng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"(For inquiries, contact Ms. Carita Aragon, PAGA\'s Event Coordinator, at 925-555-0142.\", \"vi\": \"(Mọi thắc mắc, xin vui lòng liên hệ với bà Carita Aragon, Điều phối viên Sự kiện của PAGA, theo số điện thoại 925-555-0142.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To register, e-mail sponsors@paga.org.)\", \"vi\": \"Để đăng ký, vui lòng gửi email đến địa chỉ sponsors@paga.org.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Workshop Patron—$1,250\", \"vi\": \"Nhà tài trợ cho hội thảo — 1.250 đô la\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"A representative of your company will have the honor of introducing the presenter(s) of a workshop, to be conducted on the second day of the event.\", \"vi\": \"Một đại diện của quý công ty sẽ có vinh dự giới thiệu (các) diễn giả của hội thảo, dự kiến diễn ra vào ngày thứ hai của sự kiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Charging Station Patron—$2,000\", \"vi\": \"Nhà tài trợ Trạm sạc — 2.000 đô la\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"There will be eight mobile-device charging stations in the exhibition hall, each with a sponsor sign next to it.\", \"vi\": \"Sẽ có tám trạm sạc dành cho thiết bị di động tại hội trường triển lãm, mỗi trạm đều có biển hiệu của nhà tài trợ đặt bên cạnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Bag Patron—$3,500\", \"vi\": \"Nhà tài trợ hạng Bag — 3.500 đô la\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Your company\'s emblem will be on all fabric tote bags, to be distributed to every visitor.\", \"vi\": \"Logo của công ty quý vị sẽ được in trên tất cả các túi vải, để phát cho từng khách tham quan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"General Program Patron—$5,000\", \"vi\": \"Nhà tài trợ chung cho chương trình — 5.000 đô la\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Two executives of your company will attend the PAGA Gala Banquet on the opening night of the expo.\", \"vi\": \"Hai vị lãnh đạo của công ty quý vị sẽ tham dự Dạ tiệc PAGA vào đêm khai mạc triển lãm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From: caragon@paga.org\", \"vi\": \"Nguồn: caragon@paga.org\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"To: mkee@wimosol.com\", \"vi\": \"Gửi tới: mkee@wimosol.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date: May 15\", \"vi\": \"Ngày: 15 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Subject: Thank you\", \"vi\": \"Tiêu đề: Lời cảm ơn\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Dear Mr. Kee:\", \"vi\": \"Kính gửi ông Kee:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Thank you for registering Wireless Monitoring Solutions as a sponsor of the Pittsburgh Area Garden Association (PAGA) Expo.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã đăng ký cho Wireless Monitoring Solutions trở thành nhà tài trợ của Triển lãm Hiệp hội Vườn khu vực Pittsburgh (PAGA).\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Your sponsorship not only helps to make this year\'s event possible, but also to generate interest in gardening.\", \"vi\": \"Sự tài trợ của quý vị không chỉ góp phần giúp sự kiện năm nay được tổ chức thành công, mà còn khơi dậy sự quan tâm đến việc làm vườn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Your contribution of $2,000 has been processed.\", \"vi\": \"Khoản đóng góp trị giá 2.000 đô la của quý vị đã được xử lý.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Additionally, we are offering you sponsorship of our expo bags at no additional cost.\", \"vi\": \"Ngoài ra, chúng tôi xin đề xuất quý vị tài trợ cho các túi triển lãm của chúng tôi mà không phát sinh chi phí bổ sung.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"This offer is a token of our appreciation for the long-standing support of PAGA and its programs.\", \"vi\": \"Ưu đãi này là lời tri ân của chúng tôi dành cho sự ủng hộ lâu dài dành cho PAGA và các chương trình của tổ chức này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"To finalize the promotional materials, please send us the artwork of your company\'s logo.\", \"vi\": \"Để hoàn thiện các tài liệu quảng cáo, xin vui lòng gửi cho chúng tôi bản thiết kế logo của quý công ty.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Carita Aragon, PAGA Event Coordinator\", \"vi\": \"Bà Carita Aragon, Điều phối viên Sự kiện của PAGA\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '5b005cb8-a6c2-4bbe-ba02-b4579951a175';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Marlys Barry (10:17 A.M.)\", \"vi\": \"Marlys Barry (10 giờ 17 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"This is Ms. Barry from the data analysis department.\", \"vi\": \"Đây là bà Barry, thuộc phòng phân tích dữ liệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I have included my colleague, Ms. Choi.\", \"vi\": \"Tôi đã mời đồng nghiệp của tôi, bà Choi, tham gia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We’re contacting you about your data request for the e-mail addresses of all account holders, sorted by age.\", \"vi\": \"Chúng tôi liên hệ với quý vị về yêu cầu cung cấp dữ liệu liên quan đến địa chỉ email của tất cả chủ tài khoản, được sắp xếp theo độ tuổi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Alexander Kubelski (10:17 A.M.)\", \"vi\": \"Alexander Kubelski (10 giờ 17 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Yes, how soon can you complete the request?\", \"vi\": \"Vâng, quý vị có thể hoàn tất yêu cầu này trong bao lâu?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Marlys Barry (10:18 A.M.)\", \"vi\": \"Marlys Barry (10 giờ 18 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I have a question for you first.\", \"vi\": \"Trước tiên, tôi có một câu hỏi muốn hỏi quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Do you really need the e-mail addresses of all account holders?\", \"vi\": \"Quý vị có thực sự cần địa chỉ email của tất cả các chủ tài khoản không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"That would be a huge file.\", \"vi\": \"Đó sẽ là một tệp tin có dung lượng rất lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Or do you need the e-mail addresses of account holders only within a certain age-group?\", \"vi\": \"Hay quý vị chỉ cần địa chỉ email của những chủ tài khoản thuộc một nhóm tuổi nhất định?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Alexander Kubelski (10:19 A.M.)\", \"vi\": \"Alexander Kubelski (10 giờ 19 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I see what you mean.\", \"vi\": \"Tôi hiểu ý của quý vị rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I want to e-mail account holders aged 55 to 65 to invite them to meet with a retirement planning expert.\", \"vi\": \"Tôi muốn gửi email cho các chủ tài khoản trong độ tuổi từ 55 đến 65 để mời họ đến gặp chuyên gia tư vấn kế hoạch hưu trí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Do I have to submit a new project request form?\", \"vi\": \"Tôi có cần phải nộp một mẫu đơn đề nghị dự án mới không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Bora Choi (10:21 A.M.)\", \"vi\": \"Bora Choi (10 giờ 21 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"That’s not necessary, Mr. Kubelski.\", \"vi\": \"Không cần thiết đâu, thưa ông Kubelski.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We can update your current request form for you.\", \"vi\": \"Chúng tôi có thể cập nhật mẫu đơn yêu cầu hiện tại của quý vị giúp quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"You do not want to lose your place in the queue.\", \"vi\": \"Quý vị chắc hẳn không muốn mất thứ tự của mình trong hàng đợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Alexander Kubelski (10:21 A.M.)\", \"vi\": \"Alexander Kubelski (10 giờ 21 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Great, thank you!\", \"vi\": \"Tuyệt quá, cảm ơn quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Is it possible for you to get me that list right away?\", \"vi\": \"Xin hỏi quý vị có thể gửi cho tôi danh sách đó ngay lập tức được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Marlys Barry (10:22 A.M.)\", \"vi\": \"Marlys Barry (10 giờ 22 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"There are several projects ahead of yours.\", \"vi\": \"Có một số dự án đang được triển khai trước dự án của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Alexander Kubelski (10:23 A.M.)\", \"vi\": \"Alexander Kubelski (10 giờ 23 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I was hoping to send out the e-mail invitations tomorrow.\", \"vi\": \"Tôi dự định sẽ gửi các thư mời qua email vào ngày mai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Marlys Barry (10:24 A.M.)\", \"vi\": \"Marlys Barry (10 giờ 24 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"We will get to it as soon as we can.\", \"vi\": \"Chúng tôi sẽ xử lý việc này ngay khi có thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '5b16a09d-4c11-44bb-a1e9-f4b34c91efbf';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Megagroome\", \"vi\": \"Chăm sóc\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Congratulations on purchasing Megagroome, the world\'s finest rechargeable shaver!\", \"vi\": \"Xin chúc mừng quý khách đã mua Megagroome, chiếc máy cạo râu sạc lại được tốt nhất thế giới!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To keep your shaver in top condition, clean your shaver weekly by running it under hot water.\", \"vi\": \"Để giữ cho máy cạo râu của quý vị luôn ở trạng thái tốt nhất, xin vui lòng vệ sinh máy cạo râu hàng tuần bằng cách rửa dưới vòi nước nóng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Once a month, disassemble the shaver and clean the internal portion thoroughly as shown in the owner\'s manual.\", \"vi\": \"Mỗi tháng một lần, quý vị hãy tháo rời máy cạo râu và vệ sinh kỹ lưỡng các bộ phận bên trong theo hướng dẫn trong sách hướng dẫn sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The shaving heads should be replaced every year with the replacement parts listed in the manual.\", \"vi\": \"Quý vị nên thay thế các đầu cạo râu hàng năm bằng các phụ tùng thay thế được liệt kê trong hướng dẫn sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The Megagroome shaver has a lithium ion battery that should last for several years.\", \"vi\": \"Máy cạo râu Megagroome được trang bị pin lithium-ion, có thời lượng sử dụng dự kiến lên đến vài năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Please charge the shaver as often as needed.\", \"vi\": \"Xin vui lòng sạc máy cạo râu bất cứ khi nào cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It is not necessary to fully discharge the battery before recharging it.\", \"vi\": \"Không nhất thiết phải xả cạn pin trước khi sạc lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Use only the included charger, because use of any other charger may void the warranty.\", \"vi\": \"Vui lòng chỉ sử dụng bộ sạc đi kèm, vì việc sử dụng bất kỳ bộ sạc nào khác có thể làm mất hiệu lực bảo hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Complete instructions and details can be found in the owner\'s manual.\", \"vi\": \"Quý vị có thể tham khảo hướng dẫn và thông tin chi tiết đầy đủ trong sổ tay hướng dẫn sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '5b2ee690-f5a0-4982-b54e-40cee36a51a6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: jsantos@coloniamenor.com\", \"vi\": \"Gửi tới: jsantos@coloniamenor.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: markash@amtrcorp.com\", \"vi\": \"Nguồn: markash@amtrcorp.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: September 4\", \"vi\": \"Ngày: 4 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Job tip\", \"vi\": \"Chủ đề: Lời khuyên về việc làm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hello, Juan,\", \"vi\": \"Xin chào, Juan,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"It was nice to see you again at the Tech Writers\' Conference in Mexico City.\", \"vi\": \"Thật vui khi được gặp lại quý vị tại Hội nghị các nhà văn kỹ thuật ở Thành phố Mexico.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"You mentioned that your cousin Carlos Cruz wants to find a product design job here in Dallas.\", \"vi\": \"Quý vị có đề cập rằng anh họ của quý vị, ông Carlos Cruz, đang muốn tìm một công việc trong lĩnh vực thiết kế sản phẩm tại Dallas.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Well, the company I work for, AMTR Corporation, is about to post a job for a junior industrial designer, which might interest him.\", \"vi\": \"À, công ty mà tôi đang làm việc, AMTR Corporation, sắp đăng tuyển vị trí thiết kế công nghiệp cấp cơ sở, có lẽ anh ấy sẽ quan tâm đến vị trí này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"So far, the company has announced the opening only to current employees, but next week it will appear on the company Web site.\", \"vi\": \"Cho đến nay, công ty mới chỉ thông báo về đợt tuyển dụng này dành riêng cho các nhân viên hiện tại, nhưng vào tuần tới, thông tin này sẽ được đăng tải trên trang web của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The salary is good, and there may not be any qualified candidates in-house.\", \"vi\": \"Mức lương khá hấp dẫn, và có thể trong nội bộ công ty hiện không có ứng viên nào đáp ứng đủ tiêu chuẩn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Please let him know about this opportunity.\", \"vi\": \"Xin vui lòng thông báo cho anh ấy về cơ hội này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Heide Markas\", \"vi\": \"Heide Markas\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Current Opportunities\", \"vi\": \"Các cơ hội việc làm hiện tại\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"https://www.amtrcorp.com\", \"vi\": \"https://www.amtrcorp.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Junior Industrial Designer: This is a full-time position developing and improving the full range of products manufactured by AMTR Corporation in Dallas, Texas.\", \"vi\": \"Chuyên viên Thiết kế Công nghiệp Cấp dưới: Đây là vị trí toàn thời gian, chịu trách nhiệm phát triển và cải tiến toàn bộ dòng sản phẩm do Công ty AMTR sản xuất tại Dallas, Texas.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sample Job Duties:\", \"vi\": \"Ví dụ về các nhiệm vụ công việc:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Design consumer and office supply products, including personal computers, tablets, copiers, and printers\", \"vi\": \"Thiết kế các sản phẩm tiêu dùng và văn phòng phẩm, bao gồm máy tính cá nhân, máy tính bảng, máy photocopy và máy in\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Collaborate with design team and colleagues from engineering, marketing, and manufacturing departments to develop new products\", \"vi\": \"Phối hợp với đội ngũ thiết kế cũng như các đồng nghiệp thuộc các phòng ban kỹ thuật, tiếp thị và sản xuất để phát triển các sản phẩm mới\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Improve sustainability efforts by promoting the use of recycled, recyclable, and reusable materials\", \"vi\": \"Nâng cao các nỗ lực hướng tới sự bền vững thông qua việc khuyến khích sử dụng các vật liệu đã qua tái chế, có thể tái chế và có thể tái sử dụng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Qualifications:\", \"vi\": \"Yêu cầu về trình độ:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Understanding of design principles, theories, and concepts\", \"vi\": \"Sự hiểu biết về các nguyên tắc, lý thuyết và khái niệm thiết kế\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Ability to analyze and apply customer feedback\", \"vi\": \"Khả năng phân tích và áp dụng ý kiến phản hồi của khách hàng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Proven analytical and problem-solving skills\", \"vi\": \"Có kỹ năng phân tích và giải quyết vấn đề đã được chứng minh\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Experience in creating sketches, storyboards, models, and prototypes\", \"vi\": \"Có kinh nghiệm trong việc tạo bản phác thảo, kịch bản hình ảnh, mô hình và mẫu thử\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Bachelor\'s or master\'s degree in industrial design\", \"vi\": \"Bằng cử nhân hoặc thạc sĩ chuyên ngành thiết kế công nghiệp\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"AMTR\", \"vi\": \"American Medical Response\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"CorporationHOME ABOUT CAREERS CONTACT BLOG\", \"vi\": \"Tập đoàn TRANG CHỦ GIỚI THIỆU CƠ HỘI NGHỀ NGHIỆP LIÊN HỆ BLOG\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"To: Carlos Cruz <ccruz@bmail.com>\", \"vi\": \"Gửi: Carlos Cruz <ccruz@bmail.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"From: Pamela Wang <wangp@amtrcorp.com>\", \"vi\": \"Từ: Pamela Wang <wangp@amtrcorp.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Date: November 11\", \"vi\": \"Ngày: 11 tháng 11\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Subject: Job Application\", \"vi\": \"Chủ đề: Đơn xin việc\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Dear Mr. Cruz,\", \"vi\": \"Kính gửi ông Cruz,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Thank you for submitting your application for junior industrial designer to AMTR Corporation.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã nộp hồ sơ ứng tuyển vào vị trí thiết kế viên công nghiệp cấp dưới tại Công ty AMTR.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Our hiring committee has reviewed your application and determined that you meet the qualifications for the position.\", \"vi\": \"Ủy ban tuyển dụng của chúng tôi đã xem xét hồ sơ ứng tuyển của quý vị và xác định rằng quý vị đáp ứng các tiêu chuẩn cho vị trí này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"We will contact you shortly to schedule an initial interview.\", \"vi\": \"Chúng tôi sẽ liên hệ với quý vị trong thời gian sớm nhất để sắp xếp buổi phỏng vấn đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Interviews will be held on-site at our Dallas headquarters during the first two weeks of December.\", \"vi\": \"Các buổi phỏng vấn sẽ được tổ chức trực tiếp tại trụ sở chính của chúng tôi ở Dallas trong hai tuần đầu tiên của tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"In the meantime, you will receive a request for professional references via e-mail.\", \"vi\": \"Trong thời gian chờ đợi, quý vị sẽ nhận được yêu cầu cung cấp thư giới thiệu từ các đồng nghiệp qua email.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Please respond to the request as soon as you receive it.\", \"vi\": \"Kính mong quý vị phản hồi yêu cầu này ngay khi nhận được.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Cordially,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Pamela Wang\", \"vi\": \"Pamela Wang\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Human Resources Specialist\", \"vi\": \"Chuyên viên Nhân sự\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"AMTR Corporation\", \"vi\": \"Tập đoàn AMTR\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}]' WHERE `id` = '5b37f7c9-ee29-483c-a678-97d31b33a105';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"History\", \"vi\": \"Lịch sử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Welcome to the historic H. G. Walsh Building and North Riverview Restaurant!\", \"vi\": \"Kính chào quý vị đến với Tòa nhà H. G. Walsh mang đậm dấu ấn lịch sử và Nhà hàng North Riverview!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Constructed by H. G. Walsh in 1897, the building served as Astoria\'s post office until 1942.\", \"vi\": \"Tòa nhà này do H. G. Walsh xây dựng vào năm 1897 và từng là bưu điện của Astoria cho đến năm 1942.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"It has subsequently been a general store, a boutique, and a family-run restaurant serving up fresh seafood.\", \"vi\": \"Sau đó, nơi đây đã lần lượt trở thành một cửa hàng tạp hóa, một cửa hàng thời trang và một nhà hàng do gia đình quản lý, chuyên phục vụ các món hải sản tươi sống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Over the past century, the building\'s second floor has been used for private parties, such as birthdays and weddings.\", \"vi\": \"Trong suốt một thế kỷ qua, tầng hai của tòa nhà này đã được sử dụng để tổ chức các bữa tiệc riêng tư, chẳng hạn như tiệc sinh nhật và đám cưới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Facing a potential demolition in the late 1970s, the building was purchased by its current owners, Henry and Juana Thomason, in 1981.\", \"vi\": \"Vào cuối những năm 1970, khi tòa nhà này đứng trước nguy cơ bị phá dỡ, nó đã được các chủ sở hữu hiện tại là ông Henry và bà Juana Thomason mua lại vào năm 1981.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Subsequent investment and extensive renovation helped save the H. G. Walsh Building, and in 1996 it gained status on the National Register of Historic Places.\", \"vi\": \"Những khoản đầu tư tiếp theo cùng với quá trình trùng tu quy mô lớn đã góp phần cứu vãn Tòa nhà H. G. Walsh, và vào năm 1996, công trình này đã được ghi danh vào Sổ đăng ký Di tích Lịch sử Quốc gia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"With its stunning views of the Columbia River and an extensive seasonal menu, the H. G. Walsh Building has become a prime destination for visitors to Oregon\'s Pacific coast.\", \"vi\": \"Với khung cảnh tuyệt đẹp hướng ra sông Columbia cùng thực đơn phong phú theo mùa, Tòa nhà H. G. Walsh đã trở thành một điểm đến hàng đầu dành cho du khách đến thăm bờ biển Thái Bình Dương của bang Oregon.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Fall Menu\", \"vi\": \"Thực đơn mùa thu\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Seafood chowder | Cup: $5, Bowl: $8\", \"vi\": \"Súp hải sản | Cốc: 5 USD, Bát: 8 USD\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Cream-based with clams, shrimp, and mussels\", \"vi\": \"Súp kem với nghêu, tôm và vẹm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Fish and chips | Cod: $12, Halibut: $15\", \"vi\": \"Cá và khoai tây chiên | Cá tuyết: 12 đô la, Cá bơn: 15 đô la\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Three pieces breaded in a buttermilk batter\", \"vi\": \"Ba miếng tẩm bột chiên trong hỗn hợp bột sữa chua\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Grilled salmon | $20\", \"vi\": \"Cá hồi nướng | 20 đô la\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Served with lemon-garlic sauce and a side salad\", \"vi\": \"Được phục vụ kèm nước sốt chanh tỏi và một đĩa salad ăn kèm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Bok choy | $12\", \"vi\": \"Cải thìa | 12 đô la\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Pan-seared in a garlic-ginger oyster sauce and served over rice noodles\", \"vi\": \"Được xào trên chảo với nước sốt hàu tỏi gừng và dọn kèm mì gạo\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Chef\'s salad | $11\", \"vi\": \"Salad của đầu bếp | 11 đô la\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Mixed greens tossed with toasted almonds, blue cheese dressing, and avocado\", \"vi\": \"Salad rau xanh hỗn hợp trộn với hạnh nhân rang, sốt phô mai xanh và quả bơ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '5b4838a6-e9be-40f7-9b3a-7ebb0e43b372';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"TRIVESS (1 February)—Alacritum, Inc., has announced plans to build charging stations for electric vehicles along Highway 1.\", \"vi\": \"TRIVESS (ngày 1 tháng 2) — Công ty Alacritum, Inc. đã công bố kế hoạch xây dựng các trạm sạc dành cho xe điện dọc theo Quốc lộ 1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"With over 400 stations across Asia already, Alacritum brings a wealth of experience to this large-scale undertaking.\", \"vi\": \"Với hơn 400 trạm đã được triển khai trên khắp châu Á, Alacritum mang đến một bề dày kinh nghiệm cho dự án quy mô lớn này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The Highway 1 stations, known as PRO stations, will provide vehicles with up to 200 kilowatts of power, achieving an 80 percent charge in 30 minutes.\", \"vi\": \"Các trạm sạc trên Quốc lộ 1, được gọi là trạm PRO, sẽ cung cấp công suất lên tới 200 kilowatt cho các phương tiện, giúp sạc được 80% dung lượng pin trong vòng 30 phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The system will periodically notify waiting drivers of the status of their battery charge by sending texts to their cell phones or other mobile devices.\", \"vi\": \"Hệ thống sẽ định kỳ thông báo cho các tài xế đang chờ về tình trạng sạc pin của họ bằng cách gửi tin nhắn văn bản đến điện thoại di động hoặc các thiết bị di động khác của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The company promises to provide motorists with clean, comfortable, brightly lit waiting facilities.\", \"vi\": \"Công ty cam kết cung cấp cho các tài xế những khu vực chờ sạch sẽ, thoải mái và được chiếu sáng đầy đủ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"A testing location will open at the beginning of next month in Logred.\", \"vi\": \"Một điểm xét nghiệm sẽ đi vào hoạt động vào đầu tháng tới tại Logred.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"PRO Stations: Proposed Distribution\", \"vi\": \"Các trạm PRO: Đề xuất phân bổ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Region - Number of Stations - Customers per Day\", \"vi\": \"Khu vực - Số lượng trạm - Số lượng khách hàng mỗi ngày\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Elondell - 26 - 9,220\", \"vi\": \"Elondell - 26 - 9.220\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Southern Borelvia - 14 - 4,970\", \"vi\": \"Borelvia miền Nam - 14 - 4.970\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Western Borelvia - 20 - 6,390\", \"vi\": \"Western Borelvia - 20 - 6.390\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"North Shore - 10 - 3,560\", \"vi\": \"North Shore - 10 - 3.560\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To: lhsiao@alacritum.com\", \"vi\": \"Gửi tới: lhsiao@alacritum.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"From: ctrigg@alacritum.com\", \"vi\": \"Nguồn: ctrigg@alacritum.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date: 15 March\", \"vi\": \"Ngày: 15 tháng 3\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Subject: Meeting\", \"vi\": \"Chủ đề: Cuộc họp\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Dear Mr. Hsiao,\", \"vi\": \"Kính gửi ông Hsiao,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Following the meeting with our community partners in Western Borelvia this week, I suggest adding air-conditioning to the waiting areas in that region because of the desert conditions there.\", \"vi\": \"Sau cuộc họp với các đối tác cộng đồng của chúng ta tại miền Tây Borelvia trong tuần này, tôi đề xuất lắp đặt hệ thống điều hòa không khí tại các khu vực chờ ở khu vực đó do điều kiện khí hậu sa mạc tại đây.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Although the addition entails higher costs, it will ensure the comfort and safety of the customers.\", \"vi\": \"Mặc dù việc bổ sung này sẽ dẫn đến chi phí cao hơn, nhưng nó sẽ đảm bảo sự thoải mái và an toàn cho quý khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I have also learned firsthand that poor cell service along Highway 1 will make the wireless networks at most PRO stations unreliable, so we will need a technological solution for that as well.\", \"vi\": \"Tôi cũng đã trực tiếp nhận thấy rằng chất lượng sóng di động kém dọc theo Quốc lộ 1 sẽ khiến các mạng không dây tại hầu hết các trạm PRO trở nên không ổn định, do đó chúng ta cũng sẽ cần một giải pháp công nghệ để khắc phục vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I will send a full report by the end of the week.\", \"vi\": \"Tôi sẽ gửi báo cáo đầy đủ trước cuối tuần này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Chuck Trigg\", \"vi\": \"Chuck Trigg\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '5b4d117b-9bc9-4add-854c-f65067488468';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Royal Indigo to Give Brae Airlines a New Look\", \"vi\": \"Royal Indigo sẽ mang đến diện mạo mới cho Brae Airlines\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"SYDNEY (17 February)—Brae Airlines has hired fashion house Royal Indigo to create new uniforms for the airline\'s cabin crew.\", \"vi\": \"SYDNEY (ngày 17 tháng 2) — Hãng hàng không Brae Airlines đã hợp tác với nhà mốt Royal Indigo để thiết kế bộ đồng phục mới cho đội ngũ tiếp viên hàng không của hãng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The designs are expected to be approved in March, and from that point, it will take about three months before passengers see the new style on board.\", \"vi\": \"Các thiết kế dự kiến sẽ được phê duyệt vào tháng 3, và kể từ thời điểm đó, sẽ mất khoảng ba tháng trước khi hành khách có thể chiêm ngưỡng phong cách mới trên máy bay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Senior brand manager Teija Raita said the uniforms have remained the same for a decade and the change is part of the company\'s brand redesign.\", \"vi\": \"Bà Teija Raita, Giám đốc thương hiệu cấp cao, cho biết trang phục làm việc đã không thay đổi trong suốt một thập kỷ qua và sự thay đổi này là một phần trong kế hoạch tái thiết kế thương hiệu của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"We\'re certain that Royal Indigo\'s creativity will produce an iconic uniform that makes our brand memorable and gives us a fresh look,\\\" said Ms. Raita.\", \"vi\": \"\\\"Chúng tôi tin chắc rằng sự sáng tạo của Royal Indigo sẽ mang đến một bộ đồng phục mang tính biểu tượng, giúp thương hiệu của chúng tôi trở nên đáng nhớ và mang đến một diện mạo mới mẻ,\\\" bà Raita phát biểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"\\\"Until now, we have not had high-end brands supply our uniforms, so we are excited about this collaboration.\\\"\", \"vi\": \"\\\"Cho đến nay, chúng tôi vẫn chưa có thương hiệu cao cấp nào cung cấp đồng phục cho chúng tôi, vì vậy chúng tôi rất hào hứng với sự hợp tác này.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Ms. Raita has been with the company for less than a year, taking over from Ava Holloway last November and immediately seeing to renovating and improving Brae\'s airport lounges in Sydney and Singapore.\", \"vi\": \"Bà Raita đã làm việc tại công ty chưa đầy một năm, tiếp quản vị trí từ bà Ava Holloway vào tháng 11 năm ngoái và ngay lập tức triển khai việc cải tạo và nâng cấp các phòng chờ sân bay của Brae tại Sydney và Singapore.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"She has also streamlined the company\'s social media posts and commissioned a new logo, and she is now looking into working with nonprofit organizations related to travel.\", \"vi\": \"Bà cũng đã tối ưu hóa các bài đăng trên mạng xã hội của công ty và đặt thiết kế một logo mới; hiện tại, bà đang xem xét việc hợp tác với các tổ chức phi lợi nhuận trong lĩnh vực du lịch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '5b9aca4b-73ed-4710-b900-d27ee1cd9d8a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Public Works Challenge\", \"vi\": \"Thách thức trong lĩnh vực công trình công cộng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"CARBERRY (April 15)—From its inception, the Carberry Public Works Building has met with little appreciation from the public.\", \"vi\": \"CARBERRY (ngày 15 tháng 4) — Kể từ khi đi vào hoạt động, Tòa nhà Công trình Công cộng Carberry hầu như không nhận được sự đánh giá cao từ phía công chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"When architects unveiled the blueprints for the structure, longtime residents argued that its bright colors and angular shapes did not blend well with Carberry\'s distinctive redbrick buildings.\", \"vi\": \"Khi các kiến trúc sư công bố bản thiết kế của công trình này, những cư dân đã sinh sống tại đây từ lâu đã cho rằng màu sắc rực rỡ và hình dáng góc cạnh của nó không hài hòa với những tòa nhà gạch đỏ đặc trưng của Carberry.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Local concerns even sparked the creation of a social media group, whose members urged residents to voice their opinions at town council meetings and in other public forums.\", \"vi\": \"Những lo ngại của người dân địa phương thậm chí còn dẫn đến việc thành lập một nhóm trên mạng xã hội, trong đó các thành viên kêu gọi cư dân bày tỏ ý kiến của mình tại các cuộc họp hội đồng thị trấn cũng như trong các diễn đàn công khai khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"In the end, a more conservative version of the original building design was drafted and the grand opening was planned for April 28.\", \"vi\": \"Cuối cùng, một bản thiết kế kiến trúc bảo thủ hơn so với bản gốc đã được soạn thảo và lễ khánh thành dự kiến sẽ diễn ra vào ngày 28 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"However, the owners of nearby buildings started to report drainage issues caused by significant water runoff.\", \"vi\": \"Tuy nhiên, các chủ sở hữu của các tòa nhà lân cận đã bắt đầu phản ánh về các vấn đề thoát nước do lượng nước chảy tràn đáng kể gây ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"When the property was an open field with grass and trees, excess rainwater was quickly absorbed into the ground,\\\" explains Trudy Molina, owner of the Axios Office Building.\", \"vi\": \"\\\"Khi khu đất này còn là một cánh đồng trống với cỏ và cây cối, lượng nước mưa dư thừa đã nhanh chóng được đất hấp thụ,\\\" bà Trudy Molina, chủ sở hữu Tòa nhà Văn phòng Axios, giải thích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"\\\"Now water pools up and floods adjacent parking areas during heavy rains.\\\"\", \"vi\": \"\\\"Hiện nay, mỗi khi mưa lớn, nước đọng lại và tràn vào các khu vực đỗ xe lân cận.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"According to town manager Bert Montiel, the unfortunate result of the building project was unforeseen, and construction engineers are working swiftly to correct the issue before the Public Works Building opens.\", \"vi\": \"Theo ông Bert Montiel, Quản lý thị trấn, kết quả đáng tiếc của dự án xây dựng này là điều không lường trước được, và các kỹ sư xây dựng đang khẩn trương khắc phục sự cố trước khi Tòa nhà Công trình Công cộng đi vào hoạt động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"A team has begun the installation of additional gutters and connecting drains to divert the water to the neighborhood\'s underground sewer system.\", \"vi\": \"Một đội thi công đã bắt đầu lắp đặt thêm các máng xối và hệ thống cống nối để dẫn nước vào hệ thống cống ngầm của khu dân cư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The work should be completed in time to celebrate the building\'s opening in late May.\", \"vi\": \"Công trình cần phải hoàn thành đúng tiến độ để kịp tổ chức lễ khánh thành tòa nhà vào cuối tháng Năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '5ba9fc4c-acfd-432d-be96-b67472f7e68c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: gsasaki@vanhornpublishing.com\", \"vi\": \"Nguồn: gsasaki@vanhornpublishing.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: jmyers@jig-mail.com\", \"vi\": \"Gửi tới: jmyers@jig-mail.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Delicious Portugal assignment\", \"vi\": \"Chủ đề: Bài tập về Bồ Đào Nha xinh đẹp\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: June 30\", \"vi\": \"Ngày: 30 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Delicious Portugal\", \"vi\": \"Tệp đính kèm: 📎 Bồ Đào Nha ngon miệng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Ms. Myers,\", \"vi\": \"Kính gửi bà Myers,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Attached you will find the manuscript for Danilo Costa\'s Delicious Portugal.\", \"vi\": \"Kèm theo đây là bản thảo cuốn sách *Delicious Portugal* của Danilo Costa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As we discussed, I need you to try out three of the recipes yourself and write a short report on the clarity and completeness of their instructions.\", \"vi\": \"Như chúng ta đã thảo luận, tôi mong quý vị tự mình thử làm ba công thức nấu ăn này và viết một báo cáo ngắn về mức độ rõ ràng và đầy đủ của các hướng dẫn trong đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Mr. Costa has assured me that all of his recipes were tested by non-professional cooks as required in his contract, but it\'s important that an independent tester confirm their quality before we proceed with publication.\", \"vi\": \"Ông Costa đã đảm bảo với tôi rằng tất cả các công thức nấu ăn của ông đều đã được những người nấu ăn không chuyên thử nghiệm theo yêu cầu trong hợp đồng, nhưng điều quan trọng là phải có một người thử nghiệm độc lập xác nhận chất lượng của chúng trước khi chúng ta tiến hành xuất bản.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Please include the recipe for custard tarts, on page 290, among those you test.\", \"vi\": \"Kính mong quý vị vui lòng đưa công thức làm bánh tart kem trứng ở trang 290 vào danh sách các công thức mà quý vị sẽ thử nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"As the introductory paragraph to that recipe explains, these have been one of Portugal\'s most famous foods for centuries.\", \"vi\": \"Như đoạn mở đầu của công thức nấu ăn đó đã giải thích, đây là một trong những món ăn nổi tiếng nhất của Bồ Đào Nha trong nhiều thế kỷ qua.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Reviewers will be paying special attention to it.\", \"vi\": \"Các nhà phê bình sẽ đặc biệt chú ý đến vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please complete this assignment by the end of the day on Sunday, July 5, and don\'t forget to provide images of your receipts for any ingredient purchases.\", \"vi\": \"Xin vui lòng hoàn thành bài tập này trước cuối ngày Chủ nhật, ngày 5 tháng 7, và đừng quên đính kèm ảnh chụp hóa đơn mua các nguyên liệu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"A check for your $300 fee plus reimbursement for expenses will then be sent out within 14 days.\", \"vi\": \"Sau đó, một tấm séc trị giá 300 đô la để thanh toán khoản phí của quý vị cùng với khoản hoàn trả chi phí sẽ được gửi đi trong vòng 14 ngày.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Ginji Sasaki\", \"vi\": \"Ginji Sasaki\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '5bc5a315-d4fd-404e-b16e-2cc8f5ebff90';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Sumner Auto Supply\", \"vi\": \"Công ty Cung cấp Phụ tùng Ô tô Sumner\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Service Special\", \"vi\": \"Chương trình ưu đãi dịch vụ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"$29.95\", \"vi\": \"29,95 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Service includes:\", \"vi\": \"Dịch vụ bao gồm:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Conventional oil change\", \"vi\": \"Thay dầu theo phương pháp truyền thống\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Premium oil filter change\", \"vi\": \"Dịch vụ thay lọc dầu cao cấp\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Complimentary car inspection\", \"vi\": \"Dịch vụ kiểm tra xe miễn phí\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This offer is valid only at our Smithville and Parkertown locations through August 31.\", \"vi\": \"Ưu đãi này chỉ có hiệu lực tại các chi nhánh Smithville và Parkertown của chúng tôi cho đến hết ngày 31 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Customers must present this coupon at the time of service.\", \"vi\": \"Quý khách phải xuất trình phiếu giảm giá này tại thời điểm sử dụng dịch vụ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Limit one coupon per customer.\", \"vi\": \"Mỗi khách hàng chỉ được sử dụng một phiếu giảm giá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '5bf0c998-41f8-469d-a67c-ab6cdad84797';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Adnan\'s Auto Garage\", \"vi\": \"Xưởng sửa chữa ô tô Adnan\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"5 Warner Place\", \"vi\": \"Số 5 Warner Place\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Serving Manchester for 20 years!\", \"vi\": \"Phục vụ thành phố Manchester trong suốt 20 năm qua!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Open Monday to Friday, 8 A.M. to 5 P.M.; Saturday, 9 A.M. to 1 P.M.\", \"vi\": \"Mở cửa từ thứ Hai đến thứ Sáu, từ 8 giờ sáng đến 5 giờ chiều; thứ Bảy, từ 9 giờ sáng đến 1 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Adnan\'s Auto Garage is a full-service repair shop where customer service is our top priority!\", \"vi\": \"Xưởng sửa chữa ô tô Adnan là một cơ sở sửa chữa toàn diện, nơi dịch vụ khách hàng luôn là ưu tiên hàng đầu của chúng tôi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our founder, Adnan Haddad, learned his skills as the head technician for a racing team.\", \"vi\": \"Người sáng lập của chúng tôi, ông Adnan Haddad, đã trau dồi kỹ năng của mình trong vai trò kỹ thuật viên trưởng của một đội đua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"He and his staff of professional mechanics now service all makes and models of cars and trucks, both foreign and domestic.\", \"vi\": \"Hiện nay, ông cùng đội ngũ thợ cơ khí chuyên nghiệp của mình đang cung cấp dịch vụ bảo dưỡng cho tất cả các nhãn hiệu và mẫu xe ô tô cũng như xe tải, bao gồm cả xe nhập khẩu và xe trong nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We\'ll keep your vehicle on the road!\", \"vi\": \"Chúng tôi sẽ đảm bảo chiếc xe của quý vị luôn vận hành trơn tru trên đường!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We also sell used cars at competitive prices.\", \"vi\": \"Chúng tôi cũng kinh doanh xe ô tô đã qua sử dụng với mức giá cạnh tranh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Interested in selling your car?\", \"vi\": \"Quý vị có quan tâm đến việc bán xe của mình không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Call us now!\", \"vi\": \"Hãy gọi cho chúng tôi ngay bây giờ!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"0161 496 0437\", \"vi\": \"0161 496 0437\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '5c1fb980-6f2b-4e07-a286-299fe2e41bcf';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Please note that the south lobby of the building will be closed from 7:00 P.M. this evening to 7:00 A.M. tomorrow morning.\", \"vi\": \"Xin lưu ý rằng sảnh phía nam của tòa nhà sẽ đóng cửa từ 7:00 tối nay đến 7:00 sáng mai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Routine ______[135] will be performed on the heating and cooling systems.\", \"vi\": \"Công tác bảo trì định kỳ ______[135] sẽ được tiến hành đối với hệ thống sưởi và làm mát.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [135]}, {\"en\": \"______[136], the central air conditioning will be turned off between these hours.\", \"vi\": \"______[136], hệ thống điều hòa không khí trung tâm sẽ bị tắt trong khoảng thời gian này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [136]}, {\"en\": \"We have scheduled any necessary ______[137] to take place outside of regular business hours.\", \"vi\": \"Chúng tôi đã lên lịch để mọi hoạt động ______[137] cần thiết diễn ra ngoài giờ làm việc thông thường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [137]}, {\"en\": \"______[138].\", \"vi\": \"______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [138]}, {\"en\": \"If you need access to the building during these hours, please use the north lobby or the basement-level entrances.\", \"vi\": \"Nếu bạn cần ra vào tòa nhà trong những giờ này, vui lòng sử dụng sảnh phía bắc hoặc các lối vào ở tầng hầm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"They will be unlocked and extra lighting will be provided in these two areas.\", \"vi\": \"Chúng sẽ được mở khóa và hệ thống chiếu sáng bổ sung sẽ được cung cấp tại hai khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Thank you, Building Management\", \"vi\": \"Trân trọng, Ban quản lý tòa nhà\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '5c3b58f8-2d43-4722-b0c4-9427a76d1f5a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Digital Chicory is a monthly magazine that provides resources and tutorials for Web designers.\", \"vi\": \"Digital Chicory là một tạp chí hàng tháng cung cấp các tài nguyên và hướng dẫn dành cho các nhà thiết kế web.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Digital Chicory accepts informative and well-written articles of 800 to 1,200 words.\", \"vi\": \"Digital Chicory nhận các bài viết mang tính thông tin cao và được viết tốt từ 800 đến 1.200 từ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"------- (143).\", \"vi\": \"------- (143).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [143]}, {\"en\": \"If you have an idea for an article, please send your pitch to writer@digitalchicory.org.\", \"vi\": \"Nếu bạn có ý tưởng cho một bài báo, vui lòng gửi bản tóm tắt ý tưởng của bạn đến writer@digitalchicory.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"------- (144), be sure to spend some time reading our publication so that you can develop an understanding of our audience and general writing style.\", \"vi\": \"------- (144), hãy chắc chắn dành thời gian đọc ấn phẩm của chúng tôi để bạn có thể hiểu rõ hơn về đối tượng độc giả và phong cách viết chung của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [144]}, {\"en\": \"------- (145) respond promptly to article proposals, which should be submitted as single-page outlines.\", \"vi\": \"------- (145) phản hồi kịp thời các đề xuất bài viết, các đề xuất này nên được nộp dưới dạng dàn ý một trang.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [145]}, {\"en\": \"Full-length ------- (146) are typically discouraged at the proposal stage.\", \"vi\": \"Các ------- (146) hoàn chỉnh thường không được khuyến khích ở giai đoạn đề xuất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [146]}, {\"en\": \"However, if you are a new writer for our magazine, please include samples of previously published writing.\", \"vi\": \"Tuy nhiên, nếu bạn là một cây bút mới của tạp chí chúng tôi, vui lòng gửi kèm các mẫu bài viết đã từng được xuất bản trước đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '5c5e005b-92ca-4562-ab20-182c49a5853e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Welcome to \\\"Distributing Your Savings.\\\"\", \"vi\": \"Chào mừng quý vị đến với \\\"Phân bổ khoản tiết kiệm của bạn.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"This slide ___139___ is the third of a twelve-segment educational series called \\\"Preparing for Retirement.\\\"\", \"vi\": \"Slide ___139___ này là phần thứ ba trong chuỗi chương trình giáo dục gồm mười hai phần mang tên \\\"Chuẩn bị cho tuổi nghỉ hưu.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [139]}, {\"en\": \"___140___.\", \"vi\": \"___140___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [140]}, {\"en\": \"This series provides only ___141___ advice.\", \"vi\": \"Chuỗi chương trình này chỉ cung cấp lời khuyên ___141___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [141]}, {\"en\": \"It should not replace the guidance of your investment planner.\", \"vi\": \"Nó không nên thay thế sự hướng dẫn từ nhà hoạch định đầu tư của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The series has been developed as background material to help you ask key questions when ___142___ with your investment planner.\", \"vi\": \"Chuỗi chương trình này đã được phát triển như tài liệu nền tảng giúp bạn đặt ra các câu hỏi quan trọng khi ___142___ với nhà hoạch định đầu tư của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [142]}, {\"en\": \"We hope you find this information helpful.\", \"vi\": \"Chúng tôi hy vọng bạn thấy thông tin này hữu ích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Swainson-Gray Investments\", \"vi\": \"Swainson-Gray Investments\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '5cfdf94b-45ec-462e-b5f0-58445d783e19';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Zone Catering provides food trucks at film and television production sites throughout California.\", \"vi\": \"Zone Catering cung cấp dịch vụ xe bán đồ ăn tại các địa điểm quay phim và truyền hình trên khắp bang California.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Just let us know where you need a food truck and how many people you need to feed.\", \"vi\": \"Chỉ cần cho chúng tôi biết quý vị cần xe bán đồ ăn ở đâu và số lượng người cần phục vụ là bao nhiêu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We can serve your entire cast and crew.\", \"vi\": \"Chúng tôi có thể phục vụ toàn bộ dàn diễn viên và ê-kíp của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Our trucks also move with you and your team if you are shooting scenes in various locations.\", \"vi\": \"Ngoài ra, các xe tải của chúng tôi cũng sẵn sàng di chuyển cùng quý vị và đội ngũ của quý vị nếu quý vị quay các cảnh phim tại nhiều địa điểm khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"At Zone Catering, we offer a wide variety of cuisines.\", \"vi\": \"Tại Zone Catering, chúng tôi cung cấp đa dạng các món ăn thuộc nhiều nền ẩm thực khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"All the fruits and vegetables we use in our menus are grown here in California.\", \"vi\": \"Tất cả các loại trái cây và rau củ mà chúng tôi sử dụng trong thực đơn đều được trồng ngay tại California.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our menus are easily adapted to accommodate dietary restrictions.\", \"vi\": \"Thực đơn của chúng tôi có thể dễ dàng điều chỉnh để phù hợp với các yêu cầu về chế độ ăn uống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"For convenience, our food trucks offer both full meals and individual items.\", \"vi\": \"Để thuận tiện cho quý khách, các xe bán đồ ăn di động của chúng tôi cung cấp cả các suất ăn đầy đủ lẫn các món ăn riêng lẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We can serve meals buffet-style, or people can order directly from the truck.\", \"vi\": \"Chúng tôi có thể phục vụ các bữa ăn theo hình thức tự chọn, hoặc quý khách có thể đặt món trực tiếp tại xe bán hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Let us take care of the catering for your production.\", \"vi\": \"Hãy để chúng tôi lo liệu việc phục vụ ẩm thực cho chương trình sản xuất của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"You will find our food delicious, and you will find our service friendly and convenient.\", \"vi\": \"Quý vị sẽ thấy món ăn của chúng tôi rất ngon, đồng thời dịch vụ của chúng tôi cũng rất thân thiện và thuận tiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We even offer 24-hour support in case any issues arise while we are at your location.\", \"vi\": \"Chúng tôi thậm chí còn cung cấp dịch vụ hỗ trợ 24 giờ trong trường hợp phát sinh bất kỳ sự cố nào trong thời gian chúng tôi có mặt tại địa điểm của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We hope to serve you soon!\", \"vi\": \"Chúng tôi hy vọng sẽ sớm được phục vụ quý khách!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"https://www.zonecatering.com/home\", \"vi\": \"https://www.zonecatering.com/home\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Menus\", \"vi\": \"Thực đơn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Testimonials\", \"vi\": \"Lời chia sẻ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Film - Shooting Location - Contact Person\", \"vi\": \"Phim - Địa điểm quay phim - Người liên hệ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Trappings - Harpin Lot - Erin Begg\", \"vi\": \"Trappings - Khu đất Harpin - Erin Begg\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Make the Meeting - 192 Laredo Street - Mark Lillo\", \"vi\": \"Hãy tham dự cuộc họp - Số 192 đường Laredo - Ông Mark Lillo\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Tutors and Tuxedos - Tandor Fields - Jun-Seo Kil\", \"vi\": \"Các gia sư và những bộ tuxedo - Tandor Fields - Jun-Seo Kil\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Jatem and the Storm - Spectrum Hall - Donna Gawason\", \"vi\": \"Jatem và Cơn bão - Spectrum Hall - Donna Gawason\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Zone Catering Food Trucks\", \"vi\": \"Zone Catering – Xe bán đồ ăn lưu động\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Schedule Date: June 10\", \"vi\": \"Ngày tổ chức: 10 tháng 6\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"June 10—I have been in the acting business for over 25 years and am sometimes disappointed by the food trucks on film production sites.\", \"vi\": \"Ngày 10 tháng 6 — Tôi đã hoạt động trong lĩnh vực diễn xuất được hơn 25 năm và thỉnh thoảng cảm thấy thất vọng với các xe bán đồ ăn tại các phim trường.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"That was not the case today when we were filming Make the Meeting.\", \"vi\": \"Tuy nhiên, hôm nay, khi chúng tôi đang quay chương trình “Make the Meeting”, tình hình lại không diễn ra như vậy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"The food truck had excellent coffee, and the strawberries in the large fruit salad were so fresh and tasty!\", \"vi\": \"Xe bán đồ ăn di động này có cà phê rất ngon, và những quả dâu tây trong món salad trái cây lớn cũng tươi ngon vô cùng!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Even though there was a long line of customers on an extremely hot and uncomfortable day, the server was able to get everyone’s food ready quickly.\", \"vi\": \"Mặc dù hôm đó trời nóng bức và oi bức đến mức khó chịu, lại còn có một hàng dài thực khách, nhưng nhân viên phục vụ vẫn có thể chuẩn bị đồ ăn cho tất cả mọi người một cách nhanh chóng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"She was friendly and easygoing, too!\", \"vi\": \"Cô ấy còn rất thân thiện và dễ gần nữa!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Even the food truck was pleasant-looking—the mural painted on the side of the truck was beautiful!\", \"vi\": \"Ngay cả chiếc xe bán đồ ăn di động cũng trông rất bắt mắt — bức tranh tường vẽ trên thân xe thật tuyệt đẹp!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I hope to see Zone Catering food trucks at future film shooting locations.\", \"vi\": \"Tôi hy vọng sẽ được thấy các xe bán đồ ăn của Zone Catering tại các địa điểm quay phim trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"—Robert Chiodo\", \"vi\": \"—Robert Chiodo\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"https://www.zonecatering.com/testimonials\", \"vi\": \"https://www.zonecatering.com/testimonials\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Menus\", \"vi\": \"Thực đơn\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Testimonials\", \"vi\": \"Lời chia sẻ\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}]' WHERE `id` = '5d87cf46-b3ee-4749-89f5-af42a8470bf8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dear Director Yoshida,\", \"vi\": \"Kính gửi Giám đốc Yoshida,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Thank you for your school\'s interest in visiting our farm next month.\", \"vi\": \"Cảm ơn sự quan tâm của trường quý vị đối với việc đến thăm trang trại của chúng tôi vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Please note that children must be at least six years old to visit and tour the farm.\", \"vi\": \"Xin lưu ý rằng trẻ em phải từ sáu tuổi trở lên mới được tham quan và khám phá trang trại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"______[139].\", \"vi\": \"______[139].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [139]}, {\"en\": \"I have enclosed a list of the ______[140] activities available for our young visitors.\", \"vi\": \"Tôi đã đính kèm một danh sách các hoạt động ______[140] dành cho các du khách nhỏ tuổi của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [140]}, {\"en\": \"Two of these ______[141] must be scheduled in advance.\", \"vi\": \"Hai trong số những ______[141] này phải được lên lịch trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [141]}, {\"en\": \"They are a cheese-making class and an introduction to beekeeping.\", \"vi\": \"Đó là lớp học làm phô mai và buổi giới thiệu về nghề nuôi ong.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Both are very popular with our visitors.\", \"vi\": \"Cả hai hoạt động này đều rất được du khách yêu thích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please let ______[142] know your selection by early next week.\", \"vi\": \"Vui lòng cho ______[142] biết lựa chọn của quý vị trước đầu tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [142]}, {\"en\": \"I look forward to welcoming your group soon!\", \"vi\": \"Tôi rất mong được sớm chào đón đoàn của quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Annabel Romero, Coordinator\", \"vi\": \"Annabel Romero, Điều phối viên\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Merrytree Family Farm\", \"vi\": \"Trang trại gia đình Merrytree\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '5db126e9-2e0b-4fa6-8838-74d22e78a4bf';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Marcella Wairimu <m.wairimu@theushindigroup.co.ke>\", \"vi\": \"Gửi tới: Marcella Wairimu <m.wairimu@theushindigroup.co.ke>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Henry Bunyasi <h.bunyasi@theushindigroup.co.ke>\", \"vi\": \"Từ: Henry Bunyasi <h.bunyasi@theushindigroup.co.ke>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 3 February\", \"vi\": \"Ngày: 3 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Survey\", \"vi\": \"Chủ đề: Khảo sát\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Wairimu,\", \"vi\": \"Kính gửi Bà Wairimu,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The management team has asked us to find out how satisfied our clients are with our digital marketing services.\", \"vi\": \"Ban lãnh đạo đã yêu cầu chúng tôi tiến hành khảo sát mức độ hài lòng của khách hàng đối với các dịch vụ tiếp thị kỹ thuật số của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To that end, we will conduct a survey during the month of April.\", \"vi\": \"Với mục đích đó, chúng tôi sẽ tiến hành một cuộc khảo sát trong tháng Tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Given your expertise in survey design and analysis, I would like you to develop a customer satisfaction survey that includes an evaluation of the digital marketing services we advertise on our Web site.\", \"vi\": \"Với kinh nghiệm chuyên môn của quý vị trong lĩnh vực thiết kế và phân tích khảo sát, tôi mong quý vị sẽ xây dựng một bản khảo sát mức độ hài lòng của khách hàng, trong đó bao gồm phần đánh giá các dịch vụ tiếp thị kỹ thuật số mà chúng tôi quảng bá trên trang web của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"It will be sent to each of our longtime clients here in Kenya.\", \"vi\": \"Thư này sẽ được gửi đến từng khách hàng lâu năm của chúng tôi tại Kenya.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please have a draft ready by 17 February and distribute it to the members of the management team for their review.\", \"vi\": \"Kính mong quý vị chuẩn bị sẵn bản thảo trước ngày 17 tháng 2 và gửi bản thảo này cho các thành viên trong ban lãnh đạo để họ xem xét.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"You and I will present the draft at the management team’s meeting on 23 February at 2:00 P.M.\", \"vi\": \"Chúng ta sẽ trình bày bản dự thảo tại cuộc họp của ban lãnh đạo vào lúc 2 giờ chiều ngày 23 tháng 2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Henry Bunyasi\", \"vi\": \"Henry Bunyasi\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"https://www.theushindigroup.co.ke/services_survey\", \"vi\": \"https://www.theushindigroup.co.ke/services_survey\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"About Us Services Plans and Pricing Company News\", \"vi\": \"Giới thiệu về chúng tôi Dịch vụ Các gói dịch vụ và bảng giá Tin tức công ty\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Satisfaction Survey\", \"vi\": \"Khảo sát mức độ hài lòng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"1 May\", \"vi\": \"Ngày 1 tháng 5\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"At The Ushindi Group, we strive to provide you with top-quality marketing services.\", \"vi\": \"Tại Tập đoàn Ushindi, chúng tôi luôn nỗ lực mang đến cho quý vị những dịch vụ tiếp thị chất lượng hàng đầu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"That is why we are asking our longtime clients to complete this short survey about our digital marketing services.\", \"vi\": \"Chính vì vậy, chúng tôi kính mong quý khách hàng lâu năm của chúng tôi dành thời gian hoàn thành bản khảo sát ngắn này về các dịch vụ tiếp thị kỹ thuật số của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"With the information you provide, we can identify areas for improvement.\", \"vi\": \"Dựa trên thông tin quý vị cung cấp, chúng tôi có thể xác định những lĩnh vực cần cải thiện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Please submit your responses on or before 19 May.\", \"vi\": \"Kính mong quý vị gửi phản hồi trước hoặc vào ngày 19 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Thank you for helping us to serve you better.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã giúp chúng tôi phục vụ quý khách tốt hơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Please type one of the following values into the appropriate box for each service:\", \"vi\": \"Vui lòng nhập một trong các giá trị sau vào ô tương ứng cho từng dịch vụ:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"1 = very dissatisfied, 2 = dissatisfied, 3 = no opinion, 4 = satisfied, 5 = very satisfied\", \"vi\": \"1 = rất không hài lòng, 2 = không hài lòng, 3 = không có ý kiến, 4 = hài lòng, 5 = rất hài lòng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Digital Marketing Services\", \"vi\": \"Dịch vụ Tiếp thị Kỹ thuật số\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"A. Advertising on social media ☐\", \"vi\": \"A. Quảng cáo trên mạng xã hội ☐\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"B. Content creation, including written content, photos, and videos ☐\", \"vi\": \"B. Tạo nội dung, bao gồm nội dung văn bản, ảnh và video ☐\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"C. E-mail marketing to existing and potential customers ☐\", \"vi\": \"C. Tiếp thị qua email dành cho khách hàng hiện tại và khách hàng tiềm năng ☐\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"D. Web and mobile app development and design ☐\", \"vi\": \"D. Thiết kế và phát triển ứng dụng web và di động ☐\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Client name (optional): _______________________________________\", \"vi\": \"Tên khách hàng (không bắt buộc): _______________________________________\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"https://www.theushindigroup.co.ke/companynews\", \"vi\": \"https://www.theushindigroup.co.ke/companynews\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"About Us - Services - Plans and Pricing - Company News\", \"vi\": \"Giới thiệu về chúng tôi - Dịch vụ - Các gói dịch vụ và bảng giá - Tin tức công ty\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Improvements to Our Services\", \"vi\": \"Những cải tiến đối với các dịch vụ của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"In response to customer feedback, The Ushindi Group will introduce a new e-mail marketing strategy on 15 July.\", \"vi\": \"Để đáp ứng ý kiến phản hồi của quý khách hàng, Tập đoàn Ushindi sẽ triển khai một chiến lược tiếp thị qua email mới vào ngày 15 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Our new focus will be on triggered e-mails.\", \"vi\": \"Trọng tâm mới của chúng tôi sẽ là các email được gửi tự động.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Triggered e-mails are sent out automatically based on customer behaviour and have a much higher response rate than traditional marketing e-mails.\", \"vi\": \"Các email tự động được gửi đi dựa trên hành vi của khách hàng và có tỷ lệ phản hồi cao hơn rất nhiều so với các email tiếp thị truyền thống.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Triggered e-mails help companies turn casual buyers into loyal customers.\", \"vi\": \"Các email tự động gửi theo sự kiện giúp các doanh nghiệp biến những người mua hàng ngẫu nhiên thành khách hàng trung thành.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"We anticipate that this change will result in a noticeable increase in repeat customers for our clients.\", \"vi\": \"Chúng tôi dự đoán rằng sự thay đổi này sẽ dẫn đến sự gia tăng đáng kể số lượng khách hàng quay lại đối với các khách hàng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"The price of our services will remain the same.\", \"vi\": \"Giá dịch vụ của chúng tôi sẽ vẫn giữ nguyên.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"For more information, you may contact your marketing account manager directly, call The Ushindi Group at 0800 205 555, or send an e-mail to info@theushindigroup.co.ke.\", \"vi\": \"Để biết thêm thông tin, quý vị có thể liên hệ trực tiếp với người quản lý tài khoản tiếp thị của mình, gọi điện đến The Ushindi Group theo số 0800 205 555, hoặc gửi email đến địa chỉ info@theushindigroup.co.ke.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}]' WHERE `id` = '5db3e2b1-7372-409e-af77-46af597ed641';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Selene Hong\", \"vi\": \"Từ: Selene Hong\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 25\", \"vi\": \"Ngày: 25 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Reminder\", \"vi\": \"Chủ đề: Thông báo nhắc nhở\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Staff,\", \"vi\": \"Kính gửi quý đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I would like to draw your attention to several new procedures regarding business trip expense reports.\", \"vi\": \"Tôi xin được lưu ý quý vị về một số quy trình mới liên quan đến báo cáo chi phí công tác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Beginning next month, business-related dining receipts must be accompanied by a listing of each dinner attendee.\", \"vi\": \"Kể từ tháng tới, các hóa đơn ăn uống liên quan đến công việc phải kèm theo danh sách từng người tham dự bữa tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Also, please make sure that you do not include receipts for any non-work-related items or activities with your report.\", \"vi\": \"Ngoài ra, xin vui lòng đảm bảo rằng quý vị không đính kèm các hóa đơn liên quan đến các mặt hàng hoặc hoạt động không liên quan đến công việc vào báo cáo của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Finally, note that our accounting software will now automatically calculate for you the total to be reimbursed.\", \"vi\": \"Cuối cùng, xin lưu ý rằng phần mềm kế toán của chúng tôi giờ đây sẽ tự động tính toán giúp quý vị tổng số tiền cần được hoàn trả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You need only to upload images of your receipts for the software to do this.\", \"vi\": \"Quý vị chỉ cần tải lên hình ảnh các hóa đơn của mình là phần mềm sẽ tự động thực hiện việc này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I will be happy to respond to your questions.\", \"vi\": \"Tôi rất sẵn lòng giải đáp các thắc mắc của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"However, I will be flying to Tokyo this Friday to meet clients, so I will not be checking e-mail that day.\", \"vi\": \"Tuy nhiên, vào thứ Sáu tuần này, tôi sẽ bay đến Tokyo để gặp gỡ khách hàng, vì vậy tôi sẽ không kiểm tra email vào ngày đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Selene Hong\", \"vi\": \"Selene Hong\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Assistant Director, Human Resources Department\", \"vi\": \"Phó Giám đốc, Phòng Nhân sự\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Datoric Systems\", \"vi\": \"Hệ thống Datorec\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '5e1caabd-8d6c-40a6-b385-9e98bde8ff1d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.centraluniversity.edu/nutrition/newsletter\", \"vi\": \"https://www.centraluniversity.edu/nutrition/newsletter\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Home - Customer Service - Subscribe - Account - Log in\", \"vi\": \"Trang chủ - Dịch vụ khách hàng - Đăng ký - Tài khoản - Đăng nhập\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Central University Health Newsletter—Your Guide to Nutrition and Well-Being\", \"vi\": \"Bản tin Sức khỏe của Đại học Central — Cẩm nang về Dinh dưỡng và Sức khỏe Toàn diện dành cho quý vị\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Tips on healthful eating are available almost everywhere—from TV shows to online cooking forums.\", \"vi\": \"Các lời khuyên về chế độ ăn uống lành mạnh có thể tìm thấy ở hầu hết mọi nơi — từ các chương trình truyền hình cho đến các diễn đàn nấu ăn trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"It\'s often difficult to know whether the advice you encounter is based on scientific evidence.\", \"vi\": \"Thường rất khó để biết liệu những lời khuyên mà quý vị tiếp nhận có dựa trên bằng chứng khoa học hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"That\'s why the Central University Health Newsletter is indispensable.\", \"vi\": \"Đó chính là lý do tại sao Bản tin Sức khỏe của Đại học Trung ương là không thể thiếu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Each month, it delivers informative, easy-to-understand articles that summarize findings by researchers at the Central University School of Nutrition.\", \"vi\": \"Hàng tháng, ấn phẩm này đăng tải các bài viết giàu thông tin và dễ hiểu, tóm tắt những kết quả nghiên cứu của các nhà nghiên cứu tại Trường Dinh dưỡng thuộc Đại học Trung ương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"For example, last April\'s issue evaluated nutritional supplements that are sold in supermarkets.\", \"vi\": \"Ví dụ, số báo tháng Tư vừa qua đã đánh giá các sản phẩm bổ sung dinh dưỡng được bày bán tại các siêu thị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The back page features our Ask an Expert column, in which the director of the School of Nutrition answers readers\' questions.\", \"vi\": \"Trang cuối giới thiệu chuyên mục “Hỏi chuyên gia” của chúng tôi, trong đó Viện trưởng Trường Dinh dưỡng sẽ giải đáp các thắc mắc của quý độc giả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"A one-year subscription is $20 and includes online access to all previous issues.\", \"vi\": \"Gói đăng ký một năm có giá 20 đô la và bao gồm quyền truy cập trực tuyến vào tất cả các số báo trước đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We also offer a 10 percent discount on your first subscription renewal.\", \"vi\": \"Chúng tôi cũng áp dụng mức giảm giá 10% cho lần gia hạn đăng ký đầu tiên của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"What\'s more, subscribers receive our free weekly \\\"Healthy Living\\\" e-mail update, which includes special reports plus links to videos and podcasts.\", \"vi\": \"Hơn nữa, các độc giả đăng ký sẽ nhận được bản tin điện tử miễn phí hàng tuần “Sống khỏe” của chúng tôi, trong đó bao gồm các bài báo đặc biệt cùng các liên kết đến video và podcast.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To get started, simply go to our Subscribe page and follow the instructions.\", \"vi\": \"Để bắt đầu, quý vị chỉ cần truy cập trang Đăng ký của chúng tôi và làm theo hướng dẫn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"https://www.centraluniversity.edu/nutrition/newsletter/reviews\", \"vi\": \"https://www.centraluniversity.edu/nutrition/newsletter/reviews\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Publication: Central University Health Newsletter\", \"vi\": \"Tạp chí: Bản tin Y tế của Đại học Trung ương\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"✮✮✮✮✮\", \"vi\": \"✮✮✮✮✮\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Reviewed by: Ari Kipp\", \"vi\": \"Người đánh giá: Ari Kipp\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date posted: August 4\", \"vi\": \"Ngày đăng: 4 tháng 8\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"This is my second year subscribing to the Central University Health Newsletter, which I read cover to cover.\", \"vi\": \"Đây là năm thứ hai tôi đăng ký nhận Bản tin Sức khỏe của Đại học Trung ương, và tôi luôn đọc kỹ từ đầu đến cuối.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I\'m particularly impressed with the Ask an Expert column, and I always learn something new.\", \"vi\": \"Tôi đặc biệt ấn tượng với chuyên mục “Hỏi chuyên gia”, và tôi luôn học hỏi được điều mới mẻ từ đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"This month, for instance, Dr. Stella Booth gives a surprising answer to the question of which pasta is most nutritious.\", \"vi\": \"Chẳng hạn, trong tháng này, Tiến sĩ Stella Booth đã đưa ra một câu trả lời bất ngờ cho câu hỏi loại mì ống nào có giá trị dinh dưỡng cao nhất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I didn\'t know that bean-based pasta even existed, much less how much fiber it contains.\", \"vi\": \"Tôi thậm chí còn không biết rằng có loại mì làm từ đậu, huống chi là nó chứa bao nhiêu chất xơ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I tried it and will never go back to regular pasta.\", \"vi\": \"Tôi đã thử món này và sẽ không bao giờ quay lại dùng mì ống thông thường nữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"My sole complaint is that the newsletter is only twelve pages long!\", \"vi\": \"Điều duy nhất tôi cảm thấy tiếc là bản tin này chỉ có vỏn vẹn mười hai trang!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}]' WHERE `id` = '5e222701-9f48-4434-8db0-ec849c91d755';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Bonnie Ruiz 2:40 P.M.\", \"vi\": \"Bonnie Ruiz, 2 giờ 40 phút chiều\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Good morning; welcome to Ship With Us.\", \"vi\": \"Xin chào buổi sáng; chào mừng quý khách đến với Ship With Us.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Nick Portier 2:41 P.M.\", \"vi\": \"Nick Portier 2 giờ 41 phút chiều\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Hi.\", \"vi\": \"Xin chào\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I\'m Nick, and I\'m having trouble getting into my account.\", \"vi\": \"Tôi là Nick, và tôi đang gặp khó khăn khi đăng nhập vào tài khoản của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Bonnie Ruiz 2:42 P.M.\", \"vi\": \"Bonnie Ruiz, 2 giờ 42 phút chiều\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Hi, Nick.\", \"vi\": \"Xin chào, Nick.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I\'m happy to help.\", \"vi\": \"Tôi rất vui được giúp đỡ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Have you tried resetting your password?\", \"vi\": \"Quý vị đã thử đặt lại mật khẩu chưa?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Nick Portier 2:43 P.M.\", \"vi\": \"Nick Portier 2 giờ 43 phút chiều\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I have, and I\'m still not able to get in.\", \"vi\": \"Tôi đã thử rồi, nhưng vẫn không thể truy cập được.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I need to send a large shipment of brochures and catalogs in the next 15 minutes, and I\'m a little anxious.\", \"vi\": \"Tôi cần gửi một lô hàng lớn gồm các tờ rơi và catalogue trong vòng 15 phút tới, và tôi đang cảm thấy hơi lo lắng.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Bonnie Ruiz 2:44 P.M.\", \"vi\": \"Bonnie Ruiz 2 giờ 44 phút chiều\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Don\'t worry.\", \"vi\": \"Xin đừng lo lắng.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I\'m here to help!\", \"vi\": \"Tôi sẵn sàng giúp đỡ quý vị!\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Your account number is X58292J, right?\", \"vi\": \"Số tài khoản của quý vị là X58292J, phải không ạ?\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I can reset your account on my end.\", \"vi\": \"Tôi có thể thực hiện việc khôi phục cài đặt ban đầu cho tài khoản của quý vị từ phía tôi.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Nick Portier 2:45 P.M.\", \"vi\": \"Nick Portier 2 giờ 45 phút chiều\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"That\'s it.\", \"vi\": \"Vậy là xong.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Bonnie Ruiz 2:46 P.M.\", \"vi\": \"Bonnie Ruiz 2 giờ 46 phút chiều\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Great.\", \"vi\": \"Tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I\'ve sent a new password to the e-mail address associated with that account number, and you should receive it within the next two minutes.\", \"vi\": \"Tôi đã gửi mật khẩu mới đến địa chỉ email được liên kết với số tài khoản đó, và quý vị sẽ nhận được mật khẩu này trong vòng hai phút tới.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I\'ll stay available until I\'ve heard from you to make sure that you\'ve accessed your account.\", \"vi\": \"Tôi sẽ luôn sẵn sàng hỗ trợ cho đến khi nhận được phản hồi từ quý vị để đảm bảo rằng quý vị đã đăng nhập vào tài khoản của mình.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Nick Portier 2:46 P.M.\", \"vi\": \"Nick Portier 2 giờ 46 phút chiều\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Wonderful.\", \"vi\": \"Thật tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Thanks!\", \"vi\": \"Cảm ơn!\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '5e405868-fcbf-46b6-85af-b243cbd98310';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"May 14\", \"vi\": \"Ngày 14 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Matthias Holtzmann\", \"vi\": \"Matthias Holtzmann\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Augsburger Strasse 15\", \"vi\": \"Số 15, đường Augsburger\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"57580 Elben\", \"vi\": \"57580 Elben\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Holtzmann,\", \"vi\": \"Kính gửi ông Holtzmann,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"On behalf of the Youth Music Program (YMP), I would like to express our appreciation for your volunteering for our organization.\", \"vi\": \"Thay mặt Chương trình Âm nhạc Thanh thiếu niên (YMP), tôi xin gửi lời cảm ơn chân thành đến quý vị vì đã tình nguyện tham gia hoạt động tại tổ chức của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Without the dedication and hard work of people like you, we could not achieve our common goals and have such a profound positive effect on communities throughout Germany.\", \"vi\": \"Nếu không có sự cống hiến và nỗ lực của những người như quý vị, chúng tôi sẽ không thể đạt được những mục tiêu chung và tạo ra tác động tích cực sâu sắc đến các cộng đồng trên khắp nước Đức như vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"YMP helps young people cultivate a lifelong love of music, and share the joy of music with others, enhancing well-being and social cohesion.\", \"vi\": \"YMP giúp giới trẻ nuôi dưỡng tình yêu âm nhạc suốt đời và chia sẻ niềm vui từ âm nhạc với những người xung quanh, từ đó góp phần nâng cao chất lượng cuộc sống và tăng cường sự gắn kết xã hội.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In just two years, we have expanded the number of program centers to twenty-three.\", \"vi\": \"Chỉ trong vòng hai năm, chúng tôi đã mở rộng số lượng trung tâm chương trình lên con số hai mươi ba.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Guided by our new executive director, Wayne Kastner, we expect this trend to continue.\", \"vi\": \"Dưới sự dẫn dắt của Giám đốc điều hành mới của chúng tôi, ông Wayne Kastner, chúng tôi kỳ vọng xu hướng này sẽ tiếp tục duy trì.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Among the many exciting changes on the horizon, we are delighted to partner with Himmel Music, the country\'s largest supplier of musical instruments.\", \"vi\": \"Trong số rất nhiều thay đổi đầy hứa hẹn sắp diễn ra, chúng tôi vô cùng vinh dự được hợp tác với Himmel Music, nhà cung cấp nhạc cụ lớn nhất cả nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Himmel Music will donate instruments to our organization as well as assist in our quarterly fundraising events.\", \"vi\": \"Himmel Music sẽ tặng các nhạc cụ cho tổ chức của chúng tôi cũng như hỗ trợ các sự kiện gây quỹ hàng quý của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To celebrate working with Himmel Music, we are holding a contest to create a slogan to represent the joint efforts of this new relationship.\", \"vi\": \"Nhằm kỷ niệm sự hợp tác với Himmel Music, chúng tôi xin tổ chức một cuộc thi sáng tác khẩu hiệu nhằm thể hiện những nỗ lực chung trong mối quan hệ hợp tác mới này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"All YMP participants, staff, and volunteers are urged to share their ideas.\", \"vi\": \"Tất cả các thành viên tham gia chương trình YMP, nhân viên và tình nguyện viên đều được khuyến khích chia sẻ ý tưởng của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The best one will be selected by a committee, and the winner will receive a $250 Himmel Music gift certificate.\", \"vi\": \"Tác phẩm xuất sắc nhất sẽ được một hội đồng giám khảo lựa chọn, và người chiến thắng sẽ nhận được một phiếu quà tặng trị giá 250 đô la của Himmel Music.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"More information about the contest will be included in our monthly newsletter, so be sure to watch for it.\", \"vi\": \"Thông tin chi tiết hơn về cuộc thi sẽ được đăng tải trong bản tin hàng tháng của chúng tôi, vì vậy xin quý vị đừng bỏ lỡ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Warmest regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Gabriele Reinhardt\", \"vi\": \"Gabriele Reinhardt\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Gabriele Reinhardt\", \"vi\": \"Gabriele Reinhardt\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Development Coordinator\", \"vi\": \"Điều phối viên Phát triển\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Youth Music Program\", \"vi\": \"Chương trình Âm nhạc dành cho Thanh thiếu niên\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '5e48c7d0-c249-4aee-9bc8-64e4c8f49196';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Directions to the Carrill Laboratory\", \"vi\": \"Chỉ đường đến Phòng thí nghiệm Carrill\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Enter through the main door at 3017 Bowman Street and sign in with the ------- (131) guard.\", \"vi\": \"Đi vào qua cửa chính ở số 3017 phố Bowman và đăng ký với nhân viên bảo vệ ------- (131).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"Take the elevator to the second floor.\", \"vi\": \"Đi thang máy lên tầng hai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"------- (132), you may use the stairs to the left of the elevator.\", \"vi\": \"------- (132), bạn có thể sử dụng cầu thang ở bên trái thang máy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [132]}, {\"en\": \"Once you reach the second floor, turn left ------- (133), then continue straight until you reach the double doors.\", \"vi\": \"Khi bạn lên đến tầng hai, rẽ trái ------- (133), sau đó đi thẳng cho đến khi bạn đến cửa đôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [133]}, {\"en\": \"Proceed through the doors and pass the visitors\' lounge.\", \"vi\": \"Đi qua cửa và đi qua phòng chờ dành cho khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"------- (134).\", \"vi\": \"------- (134).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [134]}]' WHERE `id` = '5ecd95f5-09dc-4004-8944-afabb39d799e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Rashida Willis <rwillis@pintaur.net>\", \"vi\": \"Đến: Rashida Willis <rwillis@pintaur.net>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Customer Accounts <accounts@stauntonnaturalgas.com>\", \"vi\": \"Từ: Tài khoản Khách hàng <accounts@stauntonnaturalgas.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: August 4\", \"vi\": \"Ngày: Ngày 4 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Paperless billing\", \"vi\": \"Chủ đề: Thanh toán trực tuyến không dùng giấy tờ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Willis,\", \"vi\": \"Kính gửi Cô Willis,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for selecting the paperless billing ______[135] for your Staunton Natural Gas account.\", \"vi\": \"Cảm ơn bạn đã chọn hình thức thanh toán không dùng giấy tờ ______[135] cho tài khoản Staunton Natural Gas của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [135]}, {\"en\": \"______[136] on August 20, you will receive your monthly statement electronically.\", \"vi\": \"______[136] vào ngày 20 tháng 8, bạn sẽ nhận được bảng sao kê hàng tháng qua đường điện tử.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [136]}, {\"en\": \"To ensure receipt of your bill, please add our e-mail address to your list of contacts.\", \"vi\": \"Để đảm bảo nhận được hóa đơn, vui lòng thêm địa chỉ email của chúng tôi vào danh sách liên hệ của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"At any time you may ______[137] to traditional paper billing by selecting it in your account settings.\", \"vi\": \"Vào bất kỳ lúc nào, bạn có thể ______[137] chuyển sang hình thức thanh toán bằng giấy truyền thống bằng cách chọn tính năng đó trong phần cài đặt tài khoản của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [137]}, {\"en\": \"______[138].\", \"vi\": \"______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [138]}, {\"en\": \"Your bill will still be due on the first of each month.\", \"vi\": \"Hóa đơn của bạn vẫn sẽ đến hạn thanh toán vào ngày mùng một hàng tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Staunton Natural Gas\", \"vi\": \"Staunton Natural Gas\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '5f203426-151b-413f-a96c-3c3c53d28118';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Time - Description - Venue\", \"vi\": \"Thời gian - Mô tả - Địa điểm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"7:00 A.M. to 8:00 A.M. - Morning Social: Complimentary omelets, pastries, coffee, tea - Mezzanine\", \"vi\": \"Từ 7 giờ sáng đến 8 giờ sáng – Buổi giao lưu buổi sáng: Miễn phí món trứng tráng, bánh ngọt, cà phê, trà – Tầng lửng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"8:30 A.M. to 10:00 A.M. - Marcos Secada, founder and CEO, Grindstone Marketing Group - Room 2\", \"vi\": \"Từ 8 giờ 30 đến 10 giờ sáng – Ông Marcos Secada, Nhà sáng lập kiêm Giám đốc Điều hành (CEO) của Grindstone Marketing Group – Phòng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"10:30 A.M. to noon - Claire Song, business columnist and best-selling author - Room 10\", \"vi\": \"Từ 10 giờ 30 sáng đến trưa – Claire Song, nhà bình luận kinh doanh và tác giả của những cuốn sách bán chạy nhất – Phòng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"12:30 P.M. to 2:00 P.M. - Lunch (ticket purchase required) - Alexander Ballroom\", \"vi\": \"12 giờ 30 phút đến 2 giờ chiều – Bữa trưa (cần mua vé) – Phòng khiêu vũ Alexander\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Fifth Annual International Marketing Society Conference\", \"vi\": \"Hội nghị thường niên lần thứ năm của Hiệp hội Tiếp thị Quốc tế\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"23–25 October, Grant Hotel and Conference Centre, London\", \"vi\": \"Ngày 23–25 tháng 10, Khách sạn và Trung tâm Hội nghị Grant, London\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Day 1:\", \"vi\": \"Ngày 1:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"M\", \"vi\": \"Tôi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To: Nadir Kalwar <kalwar.n@kdbuildingconcepts.com>\", \"vi\": \"Gửi tới: Nadir Kalwar <kalwar.n@kdbuildingconcepts.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"From: Olek Dzik <odzik.k@kdbuildingconcepts.com>\", \"vi\": \"Từ: Olek Dzik <odzik.k@kdbuildingconcepts.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Date: 12 May\", \"vi\": \"Ngày: 12 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Subject: Upcoming marketing campaign\", \"vi\": \"Chủ đề: Chiến dịch tiếp thị sắp tới\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Link to video\", \"vi\": \"Tệp đính kèm: 📎 Liên kết đến video\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Nadir,\", \"vi\": \"Nadir,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thanks for your help with the corporate marketing plan.\", \"vi\": \"Xin cảm ơn sự hỗ trợ của quý vị trong việc xây dựng kế hoạch tiếp thị doanh nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Attached is a link to the video created for us by Grindstone Marketing Group.\", \"vi\": \"Kèm theo đây là liên kết đến đoạn video do Grindstone Marketing Group thực hiện cho chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"It shows our 3-D printing equipment pouring fast-setting concrete, layer by layer.\", \"vi\": \"Hình ảnh này cho thấy thiết bị in 3D của chúng tôi đang đổ bê tông đông cứng nhanh, từng lớp một.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I think it looks great as is, and I believe it will be the most compelling aspect of our 1 June launch, especially if the Sheffield house is sold by then.\", \"vi\": \"Tôi nghĩ rằng nó trông rất tuyệt vời như hiện tại, và tôi tin rằng đây sẽ là điểm thu hút nhất trong sự kiện ra mắt vào ngày 1 tháng 6 của chúng ta, đặc biệt là nếu căn nhà ở Sheffield đã được bán vào thời điểm đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"In case you haven\'t heard, our next construction project will be a home just a couple of kilometres from your office building!\", \"vi\": \"Nếu quý vị chưa biết, dự án xây dựng tiếp theo của chúng tôi sẽ là một ngôi nhà chỉ cách tòa nhà văn phòng của quý vị vài kilômét thôi!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Olek\", \"vi\": \"Trạng thái\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"House Constructed Using 3-D Technology For Sale\", \"vi\": \"Căn nhà được xây dựng bằng công nghệ 3D đang được rao bán\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"SHEFFIELD (15 May)—An international construction firm specializing in innovative building technologies has completed one of Britain\'s first 3-D printed houses.\", \"vi\": \"SHEFFIELD (ngày 15 tháng 5) — Một công ty xây dựng quốc tế chuyên về các công nghệ xây dựng tiên tiến đã hoàn thành một trong những ngôi nhà in 3D đầu tiên tại Anh.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"The new structure is located on Morgan Road in Sheffield.\", \"vi\": \"Công trình mới này tọa lạc trên đường Morgan, thành phố Sheffield.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"KD Building Concepts took less than two weeks to execute the first phase of the project, which entailed printing the concrete walls and installing the electrical and plumbing systems, according to company president Olek Dzik.\", \"vi\": \"Theo ông Olek Dzik, Chủ tịch công ty, KD Building Concepts đã hoàn thành giai đoạn đầu tiên của dự án – bao gồm việc đổ bê tông cho các bức tường và lắp đặt hệ thống điện cùng hệ thống cấp thoát nước – trong vòng chưa đầy hai tuần.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"In just two months, the fully landscaped house with two bedrooms and two bathrooms was ready for market.\", \"vi\": \"Chỉ trong vòng hai tháng, căn nhà đã được hoàn thiện toàn bộ cảnh quan, với hai phòng ngủ và hai phòng tắm, đã sẵn sàng để đưa ra thị trường.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"\\\"Labour costs were cut in half thanks to 3-D printing technology,\\\" said Mr. Dzik, whose company has offices in France and Germany, as well as in Sheffield.\", \"vi\": \"\\\"Chi phí nhân công đã giảm một nửa nhờ công nghệ in 3D,\\\" ông Dzik, người có công ty đặt trụ sở tại Pháp, Đức và Sheffield, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"\\\"At KD Building Concepts, we are committed to building homes that are both affordable and luxurious.\\\"\", \"vi\": \"\\\"Tại KD Building Concepts, chúng tôi cam kết xây dựng những ngôi nhà vừa có giá cả phải chăng vừa sang trọng.\\\"\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"The house was listed for sale this week by a local real estate broker.\", \"vi\": \"Ngôi nhà này đã được một công ty môi giới bất động sản địa phương rao bán trong tuần này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"The asking price is £150,000.\", \"vi\": \"Giá chào bán là 150.000 bảng Anh.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Next on the horizon for KD Building Concepts is the construction of a home in Hamburg, Germany.\", \"vi\": \"Dự án tiếp theo của KD Building Concepts là việc xây dựng một ngôi nhà tại Hamburg, Đức.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = '5f2acdce-e31e-4637-b578-8ea50d3fd025';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Film crew\", \"vi\": \"Đến: Đoàn làm phim\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Sandeep Goswami\", \"vi\": \"Từ: Sandeep Goswami\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: Monday, October 2\", \"vi\": \"Ngày: Thứ Hai, ngày 2 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Barn scene retake\", \"vi\": \"Chủ đề: Quay lại cảnh nhà kho\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Crew,\", \"vi\": \"Kính gửi đoàn làm phim,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This is a reminder that on Saturday we will be doing a retake of the advertisement featuring the horses at Willow Stables.\", \"vi\": \"Đây là lời nhắc rằng vào thứ Bảy, chúng ta sẽ quay lại quảng cáo có sự xuất hiện của những con ngựa tại Trang trại Willow.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Filming with animals can be unpredictable, and last week we were not able to get the footage we needed.\", \"vi\": \"Việc quay phim với động vật có thể rất khó lường, và tuần trước chúng ta đã không thể lấy được đoạn phim mà chúng ta cần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"______[143], I would like to begin promptly at 8:00 A.M. so that we can film from a number of angles before lunch.\", \"vi\": \"______[143], tôi muốn chúng ta bắt đầu đúng 8 giờ sáng để có thể quay từ nhiều góc độ trước bữa trưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [143]}, {\"en\": \"As long as everyone is punctual and everything goes well, we should get the footage we need by then.\", \"vi\": \"Miễn là mọi người đến đúng giờ và mọi việc diễn ra suôn sẻ, chúng ta sẽ thu được thước phim cần thiết vào thời điểm đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"______[144].\", \"vi\": \"______[144].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [144]}, {\"en\": \"I also want to ______[145] the fact that the set is closed to all who are not absolutely essential to the filming of the scene.\", \"vi\": \"Tôi cũng muốn ______[145] thực tế rằng phim trường sẽ đóng cửa đối với tất cả những ai không thực sự thiết yếu cho việc quay cảnh này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [145]}, {\"en\": \"Anyone else will be too much of a ______[146].\", \"vi\": \"Bất kỳ ai khác sẽ là một sự ______[146] quá lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [146]}, {\"en\": \"Sandeep Goswami\", \"vi\": \"Sandeep Goswami\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Monarda Productions\", \"vi\": \"Monarda Productions\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '5f91f7f2-640e-41a8-b920-454995b9d260';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Priya Begani [9:02 A.M.]\", \"vi\": \"Priya Begani [9 giờ 02 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Jared.\", \"vi\": \"Xin chào, Jared.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Could you tell me the date of the management skills workshop you\'re leading?\", \"vi\": \"Xin vui lòng cho tôi biết ngày diễn ra buổi hội thảo về kỹ năng quản lý mà quý vị sẽ chủ trì?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Jared Oxley [9:03 A.M.]\", \"vi\": \"Jared Oxley [9 giờ 03 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Thursday, September 4.\", \"vi\": \"Thứ Năm, ngày 4 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"It will take up most of the day.\", \"vi\": \"Việc này sẽ chiếm phần lớn thời gian trong ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Are you still planning to come?\", \"vi\": \"Quý vị vẫn có ý định đến chứ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Priya Begani [9:05 A.M.]\", \"vi\": \"Priya Begani [9 giờ 05 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I wouldn\'t miss it!\", \"vi\": \"Tôi sẽ không bỏ lỡ sự kiện này đâu!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I only asked because I\'m trying to decide when to schedule an accounting department meeting during that week, and the only days I\'ll be in the office are September 2, 3, and 4.\", \"vi\": \"Tôi chỉ hỏi vì hiện tôi đang cân nhắc xem nên sắp xếp cuộc họp của phòng kế toán vào thời điểm nào trong tuần đó, và những ngày duy nhất tôi có mặt tại văn phòng là ngày 2, 3 và 4 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"After that, I won\'t be back until September 15, which would be too late.\", \"vi\": \"Sau đó, tôi sẽ không quay lại cho đến ngày 15 tháng 9, và như vậy thì sẽ quá muộn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Jared Oxley [9:06 A.M.]\", \"vi\": \"Jared Oxley [9 giờ 06 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Don\'t forget that the office will be closed on the morning of September 2 for maintenance work.\", \"vi\": \"Xin đừng quên rằng văn phòng sẽ đóng cửa vào buổi sáng ngày 2 tháng 9 để tiến hành công tác bảo trì.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The crew is supposed to be finished by noon, but you never know.\", \"vi\": \"Đội thi được dự kiến sẽ hoàn thành công việc trước buổi trưa, nhưng ai mà biết được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Priya Begani [9:07 A.M.]\", \"vi\": \"Priya Begani [9 giờ 07 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Oh, right.\", \"vi\": \"À, đúng rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The last time they did maintenance work, the office ended up being closed all day.\", \"vi\": \"Lần gần đây nhất khi họ tiến hành công tác bảo trì, văn phòng đã phải đóng cửa suốt cả ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"That leaves only one sure date for that accounting meeting then.\", \"vi\": \"Như vậy, chỉ còn lại một ngày chắc chắn duy nhất để tổ chức cuộc họp về kế toán đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thanks for reminding me.\", \"vi\": \"Cảm ơn quý vị đã nhắc nhở tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Jared Oxley [9:08 A.M.]\", \"vi\": \"Jared Oxley [9 giờ 08 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"No problem.\", \"vi\": \"Không sao đâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"By the way, a few of us are getting together at Ayala\'s Bistro after work today.\", \"vi\": \"Nhân tiện, hôm nay sau giờ làm việc, một vài người trong chúng tôi sẽ tụ tập tại Ayala\'s Bistro.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Would you like to join us?\", \"vi\": \"Quý vị có muốn tham gia cùng chúng tôi không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Priya Begani [9:09 A.M.]\", \"vi\": \"Priya Begani [9 giờ 09 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I can\'t—I have a doctor\'s appointment after work.\", \"vi\": \"Tôi không thể được — tôi có lịch hẹn với bác sĩ sau giờ làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I\'ll go next time!\", \"vi\": \"Lần sau tôi sẽ đi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '5fb84412-62a8-4d14-8bd7-f750fb68af23';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: maria_bellandini@pweb.net\", \"vi\": \"Gửi tới: maria_bellandini@pweb.net\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: thomas.mclaren@delicatessenmag.com\", \"vi\": \"Nguồn: thomas.mclaren@delicatessenmag.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: Tuesday, October 2\", \"vi\": \"Ngày: Thứ Ba, ngày 2 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Food Photography Article\", \"vi\": \"Chủ đề: Bài viết về nhiếp ảnh ẩm thực\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Bellandini:\", \"vi\": \"Kính gửi Bà Bellandini:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I have some news regarding your article that is scheduled to be published in the next issue of Delicatessen Magazine.\", \"vi\": \"Tôi có một số thông tin liên quan đến bài viết của quý vị dự kiến sẽ được đăng trên số tiếp theo của Tạp chí Delicatessen.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Yesterday, we learned that a major advertiser canceled their contract with us, and as a result, we will have to reduce the number of pages in our upcoming issue.\", \"vi\": \"Hôm qua, chúng tôi được biết một nhà quảng cáo lớn đã hủy hợp đồng với chúng tôi, và do đó, chúng tôi sẽ phải cắt giảm số trang trong số báo sắp tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This is extremely unfortunate, but we just do not have enough money without these ads to publish the magazine in its current format.\", \"vi\": \"Điều này thực sự rất đáng tiếc, nhưng nếu không có những quảng cáo này, chúng tôi đơn giản là không có đủ kinh phí để xuất bản tạp chí theo định dạng hiện tại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We know that readers have enjoyed reading about your experiences in Italy.\", \"vi\": \"Chúng tôi biết rằng quý độc giả đã rất hào hứng khi được đọc về những trải nghiệm của quý vị tại Ý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"While your eight-page story about working as a food photographer is excellent, in order to fit in the slimmer issue, it will need to be cut by about thirty percent.\", \"vi\": \"Mặc dù bài viết dài tám trang của quý vị về công việc của một nhiếp ảnh gia ẩm thực rất xuất sắc, nhưng để phù hợp với số báo có số trang ít hơn này, bài viết sẽ cần phải được cắt bớt khoảng ba mươi phần trăm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Although I sincerely hope you agree to having your article published in our upcoming issue, I will understand if you would rather have the article published in full at a later time.\", \"vi\": \"Mặc dù tôi chân thành hy vọng quý vị sẽ đồng ý cho bài viết của mình được đăng trên số báo sắp tới của chúng tôi, nhưng tôi cũng sẽ thông cảm nếu quý vị muốn bài viết được đăng đầy đủ vào một thời điểm khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"However, I have to let you know that the magazine industry is not always the most stable business, and for this reason, I do not know if there will be space for your story in the future.\", \"vi\": \"Tuy nhiên, tôi phải thông báo với quý vị rằng ngành xuất bản tạp chí không phải lúc nào cũng là lĩnh vực kinh doanh ổn định nhất, và vì lý do này, tôi không chắc liệu trong tương lai có còn chỗ dành cho bài viết của quý vị hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Please let me know as soon as possible what you would like to do.\", \"vi\": \"Xin vui lòng cho tôi biết sớm nhất có thể về quyết định của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Should you agree to edit the story, I will need the new version by Monday.\", \"vi\": \"Nếu quý vị đồng ý chỉnh sửa bài viết, tôi sẽ cần bản mới vào thứ Hai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Thomas McLaren, Editor-in-Chief\", \"vi\": \"Thomas McLaren, Tổng biên tập\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '5fbc0bee-25b8-4271-a87e-2df0f4ba1250';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Priyanka Kapoor [9:41 A.M.]\", \"vi\": \"Priyanka Kapoor [9 giờ 41 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"We need to talk about the upcoming family physicians conference in London.\", \"vi\": \"Chúng ta cần thảo luận về hội nghị các bác sĩ gia đình sắp diễn ra tại London.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Where do we stand?\", \"vi\": \"Hiện tại, tình hình của chúng ta ra sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Alonso Gonzalez [9:44 A.M.]\", \"vi\": \"Alonso Gonzalez [9 giờ 44 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I’ve already purchased airline tickets for all of us.\", \"vi\": \"Tôi đã mua vé máy bay cho tất cả chúng ta rồi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Priyanka Kapoor [9:47 A.M.]\", \"vi\": \"Priyanka Kapoor [9 giờ 47 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Great.\", \"vi\": \"Tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Scott Harris will arrange our shuttle from the London airport to the conference venue.\", \"vi\": \"Ông Scott Harris sẽ sắp xếp dịch vụ đưa đón của chúng ta từ sân bay London đến địa điểm tổ chức hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Will our mobile phones be functional outside of the Wi-Fi zones?\", \"vi\": \"Liệu điện thoại di động của chúng ta có thể hoạt động được bên ngoài các vùng phủ sóng Wi-Fi hay không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Alonso Gonzalez [9:50 A.M.]\", \"vi\": \"Alonso Gonzalez [9 giờ 50 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I’ve researched our mobile phone provider’s international plan.\", \"vi\": \"Tôi đã tìm hiểu về gói cước quốc tế của nhà mạng di động của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It offers the ability to call and text but provides limited data options with slow download speeds.\", \"vi\": \"Dịch vụ này cho phép quý vị thực hiện cuộc gọi và gửi tin nhắn, nhưng các gói dữ liệu lại khá hạn chế và tốc độ tải xuống chậm.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Brian Kim [9:53 A.M.]\", \"vi\": \"Brian Kim [9 giờ 53 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Let’s buy international SIM cards before we leave.\", \"vi\": \"Chúng ta hãy mua thẻ SIM quốc tế trước khi khởi hành.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We can get the prepaid cards with high-speed data and unlimited calling and texting.\", \"vi\": \"Chúng ta có thể mua các thẻ trả trước có gói dữ liệu tốc độ cao cùng với dịch vụ gọi điện và nhắn tin không giới hạn.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We won’t have to worry about being connected to Wi-Fi.\", \"vi\": \"Chúng ta sẽ không phải lo lắng về việc kết nối Wi-Fi nữa.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Priyanka Kapoor [9:57 A.M.]\", \"vi\": \"Priyanka Kapoor [9 giờ 57 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"That will solve the problem.\", \"vi\": \"Điều đó sẽ giải quyết được vấn đề.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Alonso Gonzalez [9:57 A.M.]\", \"vi\": \"Alonso Gonzalez [9 giờ 57 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Good idea, Brian.\", \"vi\": \"Ý tưởng hay đấy, Brian.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Thanks.\", \"vi\": \"Cảm ơn.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Now let’s discuss meeting up for our meals.\", \"vi\": \"Bây giờ chúng ta hãy bàn về việc hẹn nhau đi ăn nhé.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Priyanka Kapoor [9:59 A.M.]\", \"vi\": \"Priyanka Kapoor [9 giờ 59 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 7, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Each day of the conference begins with a continental breakfast in the lobby.\", \"vi\": \"Mỗi ngày của hội nghị đều bắt đầu bằng bữa sáng kiểu châu Âu tại sảnh khách sạn.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Let’s meet there in the morning.\", \"vi\": \"Chúng ta hãy hẹn gặp nhau tại đó vào buổi sáng nhé.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I know of a great place for dinner, so let’s plan on 6:00 P.M. the first evening.\", \"vi\": \"Tôi biết một nơi rất tuyệt để dùng bữa tối, vậy nên chúng ta hãy hẹn nhau vào lúc 6 giờ chiều ngày đầu tiên nhé.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"We’ll decide about the other meals later.\", \"vi\": \"Chúng ta sẽ quyết định về các bữa ăn còn lại sau.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '5fe884f0-5b73-4e84-8c95-3b79abf2d01a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Westhauser Laboratories Staff\", \"vi\": \"Kính gửi: Toàn thể nhân viên Phòng thí nghiệm Westhauser\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Area manager\", \"vi\": \"Từ: Quản lý khu vực\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 22\", \"vi\": \"Ngày: 22 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Re: Break-time beverages\", \"vi\": \"Trả lời: Đồ uống trong giờ giải lao\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Beginning immediately, staff members are asked to contribute toward the cost of hot beverages available in our kitchenette.\", \"vi\": \"Kể từ ngay bây giờ, các nhân viên được đề nghị đóng góp một phần chi phí cho các loại đồ uống nóng được phục vụ tại khu bếp nhỏ của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"For each cup of coffee or tea you pour for yourself, we are requesting that you leave fifty cents.\", \"vi\": \"Với mỗi tách cà phê hoặc trà mà quý vị tự rót cho mình, chúng tôi xin đề nghị quý vị đóng góp năm mươi xu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Please note that this amount is still far less than what you would pay at the cafe next to our building.\", \"vi\": \"Xin lưu ý rằng số tiền này vẫn thấp hơn rất nhiều so với mức giá quý vị phải trả tại quán cà phê bên cạnh tòa nhà của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Each time you prepare a beverage, just place your payment in the marked can on the counter next to the sink.\", \"vi\": \"Mỗi khi quý vị pha chế đồ uống, xin vui lòng bỏ tiền thanh toán vào chiếc lon đã được đánh dấu trên quầy bên cạnh bồn rửa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As in the past, a variety of high-quality tea and coffee supplies will be made available, and products will be restocked monthly.\", \"vi\": \"Cũng như trước đây, chúng tôi sẽ cung cấp đa dạng các loại trà và cà phê chất lượng cao, đồng thời các sản phẩm sẽ được bổ sung hàng tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Your understanding is appreciated so that everyone can continue to enjoy conveniently located hot beverages throughout the workday.\", \"vi\": \"Chúng tôi rất cảm ơn sự thông cảm của quý vị để mọi người có thể tiếp tục thưởng thức các loại đồ uống nóng tại những địa điểm thuận tiện trong suốt ngày làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '5fe9a2e1-e6c4-4a82-aa19-c8bed4a84fe0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Muffin Lady Muffins\", \"vi\": \"Bánh Muffin Muffin Lady\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"One day nearly 160 years ago, Arianna Sweeney brought some of her homemade muffins to the local town square to give to her friends.\", \"vi\": \"Một ngày gần 160 năm trước, Arianna Sweeney đã mang một số chiếc bánh muffin tự làm của cô đến quảng trường thị trấn địa phương để tặng cho bạn bè của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Everyone loved them!\", \"vi\": \"Mọi người đều rất thích chúng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"------- (131), Ms. Sweeney started sharing muffins with anyone who wanted one.\", \"vi\": \"------- (131), cô Sweeney bắt đầu chia sẻ bánh muffin với bất kỳ ai muốn có một chiếc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [131]}, {\"en\": \"------- (132).\", \"vi\": \"------- (132).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [132]}, {\"en\": \"After a few months, she became known around town as the Muffin Lady.\", \"vi\": \"Sau vài tháng, cô ấy trở nên nổi tiếng khắp thị trấn với biệt danh Quý cô Muffin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Today, Muffin Lady Muffins are made by hand ------- (133) the same original recipes developed by Arianna Sweeney.\", \"vi\": \"Ngày nay, bánh muffin của Muffin Lady được làm thủ công ------- (133) theo đúng các công thức nguyên bản do Arianna Sweeney phát triển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [133]}, {\"en\": \"We are committed to baking Muffin Lady Muffins authentically with only the finest ingredients.\", \"vi\": \"Chúng tôi cam kết nướng bánh muffin Muffin Lady một cách chân thực chỉ với những nguyên liệu tốt nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We hope you enjoy our delicious ------- (134)!\", \"vi\": \"Chúng tôi hy vọng bạn thưởng thức những món ------- (134) ngon miệng của chúng tôi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [134]}]' WHERE `id` = '5fef0f69-6df8-4a31-87cf-94529deb7ead';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Hillside House Is Ready for Business\", \"vi\": \"Hillside House đã sẵn sàng đi vào hoạt động\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"AUCKLAND (2 April)—Hillside House, Auckland’s newest and most spectacular event space, is now open.\", \"vi\": \"AUCKLAND (ngày 2 tháng 4) — Hillside House, không gian tổ chức sự kiện mới nhất và hoành tráng nhất tại Auckland, hiện đã chính thức đi vào hoạt động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This unique venue is a secluded haven only minutes away from the city centre.\", \"vi\": \"Địa điểm độc đáo này là một chốn nghỉ ngơi yên tĩnh, chỉ cách trung tâm thành phố vài phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Its glass walls give guests an enchanted view of green gardens and bright flowers, while multiple windows in the ceiling make the sky part of the interior decoration.\", \"vi\": \"Các bức tường kính của nơi này mang đến cho quý khách khung cảnh mê hoặc với những khu vườn xanh mát và những bông hoa rực rỡ, trong khi những ô cửa sổ trên trần nhà khiến bầu trời trở thành một phần của không gian trang trí nội thất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hillside House is the perfect setting for weddings and other social gatherings, as well as corporate events.\", \"vi\": \"Hillside House là địa điểm lý tưởng để tổ chức các đám cưới và các buổi tiệc xã hội khác, cũng như các sự kiện doanh nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The kitchen is under the direction of Chef Bashu Malik, a two-time Franklin Heard Foundation winner.\", \"vi\": \"Bếp được điều hành bởi Bếp trưởng Bashu Malik, người đã hai lần giành giải thưởng của Quỹ Franklin Heard.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Chef Malik oversees Hillside House’s menus, whether the event hosts choose eclectic small plates, a family-style dinner, or a buffet brunch.\", \"vi\": \"Đầu bếp Malik chịu trách nhiệm giám sát thực đơn của Hillside House, bất kể ban tổ chức sự kiện lựa chọn các món ăn nhẹ đa dạng, bữa tối theo phong cách gia đình hay bữa sáng tự chọn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"“Choosing the right venue is the key to success,” says Hillside House Managing Director Russell Isley.\", \"vi\": \"“Việc lựa chọn địa điểm phù hợp chính là chìa khóa dẫn đến thành công,” ông Russell Isley, Giám đốc Điều hành của Hillside House, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"“We offer everything—a beautiful setting, an experienced staff, and great food.\", \"vi\": \"“Chúng tôi mang đến tất cả mọi thứ — một khung cảnh tuyệt đẹp, đội ngũ nhân viên giàu kinh nghiệm và những món ăn ngon miệng.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Our events coordinator will work with you to make your wedding or corporate function an occasion to remember.”\", \"vi\": \"“Chuyên viên điều phối sự kiện của chúng tôi sẽ hợp tác cùng quý vị để biến đám cưới hoặc sự kiện doanh nghiệp của quý vị thành một dịp đáng nhớ.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To: Hayley Colling <hcolling@kitchendesigns.co.nz>\", \"vi\": \"Gửi tới: Hayley Colling <hcolling@kitchendesigns.co.nz>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"From: Reka Taimona <rtaimona@hillsidehouse.co.nz>\", \"vi\": \"Từ: Reka Taimona <rtaimona@hillsidehouse.co.nz>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Date: 10 May\", \"vi\": \"Ngày: 10 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Attachment: Hillside House options\", \"vi\": \"Tệp đính kèm: Các phương án thiết kế cho Hillside House\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dear Ms. Colling:\", \"vi\": \"Kính gửi bà Colling:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thank you for reaching out to Hillside House about your upcoming product launch!\", \"vi\": \"Xin chân thành cảm ơn quý vị đã liên hệ với Hillside House về sự kiện ra mắt sản phẩm sắp tới của quý vị!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Yes, 16 June is available; your Kitchen Designs corporate celebration is now on our schedule.\", \"vi\": \"Vâng, ngày 16 tháng 6 vẫn còn trống; sự kiện kỷ niệm của công ty Kitchen Designs hiện đã được đưa vào lịch trình của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"In preparation for the event, please note that we offer several unique branding opportunities.\", \"vi\": \"Để chuẩn bị cho sự kiện này, xin lưu ý rằng chúng tôi cung cấp một số cơ hội quảng bá thương hiệu độc đáo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"For example, we can display your company’s logo in neon lights and hang up banners.\", \"vi\": \"Ví dụ, chúng tôi có thể trưng bày logo của quý công ty bằng đèn neon và treo các biểu ngữ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Chef Malik and his staff can also work with you to include logos on food items or a cake.\", \"vi\": \"Đầu bếp Malik cùng đội ngũ nhân viên của ông cũng có thể phối hợp với quý vị để in logo lên các món ăn hoặc bánh kem.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I am attaching information about the menu options and pricing.\", \"vi\": \"Tôi xin đính kèm thông tin về các lựa chọn trong thực đơn và bảng giá.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"We have a state-of-the-art sound system and audiovisual equipment for speeches and presentations.\", \"vi\": \"Chúng tôi sở hữu hệ thống âm thanh và thiết bị nghe nhìn hiện đại nhất dành cho các bài phát biểu và buổi thuyết trình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"If you would like entertainment for your event, I can also supply you with a list of bands and musicians.\", \"vi\": \"Nếu quý vị có nhu cầu về chương trình giải trí cho sự kiện của mình, tôi cũng có thể cung cấp cho quý vị danh sách các ban nhạc và nghệ sĩ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Please let me know if you have any other questions.\", \"vi\": \"Nếu quý vị còn thắc mắc gì khác, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"We at Hillside House look forward to hosting your event.\", \"vi\": \"Chúng tôi tại Hillside House rất hân hạnh được đón tiếp quý vị và tổ chức sự kiện của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Reka Taimona, Events Coordinator\", \"vi\": \"Reka Taimona, Điều phối viên Sự kiện\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Hillside House\", \"vi\": \"Ngôi nhà trên sườn đồi\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}]' WHERE `id` = '603b7ec8-42a4-40e1-85e6-aff2ab9db579';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Multinational Voice Magazine\", \"vi\": \"Tạp chí Multinational Voice\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"PO Box 17999\", \"vi\": \"Hộp thư số 17999\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Greenlane\", \"vi\": \"Greenlane\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Auckland 1546\", \"vi\": \"Auckland 1546\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Tuata Wehi\", \"vi\": \"Con đường đầy sợ hãi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"16 Page Street\", \"vi\": \"Số 16 đường Page\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Wellington 6023\", \"vi\": \"Wellington 6023\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Dear Mr. Wehi,\", \"vi\": \"Kính gửi ông Wehi,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"On 25 March, your three-month trial subscription to Multinational Voice Magazine will expire.\", \"vi\": \"Vào ngày 25 tháng 3, gói đăng ký dùng thử ba tháng của quý vị dành cho Tạp chí Multinational Voice sẽ hết hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To continue to receive this vital news resource, please fill out the postage-paid renewal card included with this letter and mail it in before the end of this month.\", \"vi\": \"Để tiếp tục nhận được nguồn tin tức quan trọng này, xin vui lòng điền vào phiếu gia hạn đã bao gồm cước bưu chính kèm theo thư này và gửi lại trước khi kết thúc tháng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"You may select from a three-month, six-month, one-year, or two-year subscription.\", \"vi\": \"Quý vị có thể lựa chọn gói đăng ký có thời hạn ba tháng, sáu tháng, một năm hoặc hai năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Do note that our two-year offer is by far the most economical.\", \"vi\": \"Xin lưu ý rằng gói dịch vụ hai năm của chúng tôi là lựa chọn tiết kiệm nhất hiện nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Also, the one- and two-year options include the \\\"Notable People of the Year\\\" special edition.\", \"vi\": \"Ngoài ra, các gói đăng ký một năm và hai năm còn bao gồm ấn bản đặc biệt “Những nhân vật nổi bật của năm”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Thank you once again for choosing Multinational Voice Magazine.\", \"vi\": \"Một lần nữa, xin chân thành cảm ơn quý độc giả đã lựa chọn Tạp chí Multinational Voice.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We continually strive to provide the best commentary on global affairs from a New Zealand perspective.\", \"vi\": \"Chúng tôi không ngừng nỗ lực nhằm mang đến những bài bình luận chất lượng nhất về các vấn đề quốc tế dưới góc nhìn của New Zealand.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To provide your feedback, please visit www.mvmagazine.co.nz and fill out our online comment form.\", \"vi\": \"Để gửi ý kiến phản hồi, xin vui lòng truy cập trang web www.mvmagazine.co.nz và điền vào biểu mẫu góp ý trực tuyến của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Estelle Pearson, Customer Service Representative\", \"vi\": \"Estelle Pearson, Nhân viên Dịch vụ Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '60d49c93-cc75-469b-a7cb-2256a2092486';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ideal for a new business!\", \"vi\": \"Rất lý tưởng cho một doanh nghiệp mới!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"This recently constructed property contains nearly 2,000 square metres of office space, with an additional 1,000 square metres of storage space and a 3,000-square-metre car garage.\", \"vi\": \"Tòa nhà mới được xây dựng này có diện tích văn phòng gần 2.000 mét vuông, cùng với 1.000 mét vuông diện tích kho chứa và một bãi đỗ xe rộng 3.000 mét vuông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Easily accessible from downtown Cloverdale, the property is within 500 metres of several restaurants and a brand-new shopping centre.\", \"vi\": \"Có thể dễ dàng tiếp cận từ trung tâm thành phố Cloverdale, bất động sản này nằm trong phạm vi 500 mét so với một số nhà hàng và một trung tâm thương mại hoàn toàn mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The sleek, modern design features floor-to-ceiling windows that provide an abundance of natural light.\", \"vi\": \"Thiết kế sang trọng và hiện đại với những ô cửa kính từ sàn đến trần, mang lại nguồn ánh sáng tự nhiên dồi dào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The standard lease is for twelve months with monthly payments and a security deposit.\", \"vi\": \"Hợp đồng thuê tiêu chuẩn có thời hạn mười hai tháng, với các khoản thanh toán hàng tháng và một khoản tiền đặt cọc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"For a lease application or to view the property in person, call Danna Pulley at (519) 555-0139.\", \"vi\": \"Để nộp đơn xin thuê hoặc đến xem trực tiếp bất động sản, xin vui lòng liên hệ với bà Danna Pulley theo số (519) 555-0139.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '610961a3-1e68-4833-b1d6-339de15e5a15';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"April 7\", \"vi\": \"Ngày 7 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Naomi Burwell\", \"vi\": \"Naomi Burwell\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"43 Waymire Road\", \"vi\": \"43 Đường Waymire\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"South Portland, ME 04109\", \"vi\": \"South Portland, ME 04109\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Burwell,\", \"vi\": \"Kính gửi bà Burwell,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am Omar Ridha, the manager of Droplight Studio.\", \"vi\": \"Tôi là Omar Ridha, quản lý của Droplight Studio.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"____143____.\", \"vi\": \"____143____.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [143]}, {\"en\": \"We offer a full range of photography services for real estate professionals like you.\", \"vi\": \"Chúng tôi cung cấp đầy đủ các dịch vụ chụp ảnh dành cho các chuyên gia bất động sản như bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We take pride in composing interior and exterior shots that make a property look its best.\", \"vi\": \"Chúng tôi tự hào trong việc bố trí các góc chụp nội thất và ngoại thất giúp bất động sản trông đẹp nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Droplight Studio spares no effort in ____144____ superior digital images.\", \"vi\": \"Droplight Studio nỗ lực hết mình trong việc ____144____ các hình ảnh kỹ thuật số chất lượng cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [144]}, {\"en\": \"____145____, our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property.\", \"vi\": \"____145____, trang thiết bị, ánh sáng và các kỹ thuật dàn dựng đạt chuẩn chuyên nghiệp của chúng tôi cho phép chúng tôi làm nổi bật những đặc điểm tốt nhất của một bất động sản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [145]}, {\"en\": \"And once the photo shoot is over, every image ____146____ expert editing.\", \"vi\": \"Và sau khi buổi chụp hình kết thúc, mọi bức ảnh đều ____146____ được chỉnh sửa chuyên nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [146]}, {\"en\": \"All these services come standard in every package.\", \"vi\": \"Tất cả các dịch vụ này đều được bao gồm tiêu chuẩn trong mọi gói dịch vụ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please visit our Web site to view our work as well as our pricing and scheduling information.\", \"vi\": \"Vui lòng truy cập trang web của chúng tôi để xem các tác phẩm cũng như thông tin về giá cả và lịch trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We are happy to work with you to customize orders.\", \"vi\": \"Chúng tôi rất sẵn lòng hợp tác với bà để tùy chỉnh các đơn hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Omar Ridha, Droplight Studio\", \"vi\": \"Omar Ridha, Droplight Studio\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '610b95a8-dee4-4344-9421-b0181cfca6d4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"EMPLOYMENT CENTER\", \"vi\": \"TRUNG TÂM GIỚI THIỆU VIỆC LÀM\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Management Assistant, Property Development Division\", \"vi\": \"Trợ lý Quản lý, Phòng Phát triển Bất động sản\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Fuhr Realty Ltd. has a need for a full-time management assistant to provide customer service, data entry, and general administrative support associated with our Property Development Division.\", \"vi\": \"Công ty Fuhr Realty Ltd. đang có nhu cầu tuyển dụng một trợ lý quản lý toàn thời gian để đảm nhận các công việc liên quan đến dịch vụ khách hàng, nhập liệu và hỗ trợ hành chính chung cho Bộ phận Phát triển Bất động sản của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The individual will respond to requests for information from the public, research and track permits, and assist with maintaining department records.\", \"vi\": \"Người này sẽ giải đáp các yêu cầu cung cấp thông tin từ công chúng, tra cứu và theo dõi các giấy phép, đồng thời hỗ trợ việc quản lý hồ sơ của phòng ban.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The position requires a minimum of a bachelor\'s degree and two years of related office experience.\", \"vi\": \"Vị trí này yêu cầu ứng viên phải có ít nhất bằng cử nhân và hai năm kinh nghiệm làm việc liên quan trong môi trường văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Strong computer literacy and excellent written and spoken communication skills are a must.\", \"vi\": \"Ứng viên bắt buộc phải có kiến thức vững vàng về máy tính cùng với kỹ năng giao tiếp bằng văn bản và lời nói xuất sắc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Applications will be accepted through March 30.\", \"vi\": \"Hồ sơ đăng ký sẽ được tiếp nhận đến hết ngày 30 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Find a Job\", \"vi\": \"Tìm việc làm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Apply\", \"vi\": \"Nộp đơn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '61601045-dac9-41b3-ac9e-a07359f18da1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.marilisprofessionalcoaching.com\", \"vi\": \"http://www.marilisprofessionalcoaching.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Marilis Professional Coaching: January Events\", \"vi\": \"Marilis Professional Coaching: Các sự kiện tháng 1\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"January 15 at 4:30 P.M.—Job Search Support\", \"vi\": \"Ngày 15 tháng 1 lúc 4 giờ 30 chiều — Hỗ trợ tìm kiếm việc làm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Learn about the latest tools and techniques to help you find a rewarding entry-level job.\", \"vi\": \"Hãy tìm hiểu về các công cụ và kỹ thuật mới nhất để giúp quý vị tìm được một công việc khởi đầu đầy ý nghĩa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Topics include the best Web sites for job announcements and how to use professional organizations to get job leads.\", \"vi\": \"Các chủ đề bao gồm các trang web tốt nhất để tìm thông báo tuyển dụng và cách tận dụng các tổ chức nghề nghiệp để tìm kiếm cơ hội việc làm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"January 16 at 4:30 P.M.—How to Market Yourself\", \"vi\": \"Ngày 16 tháng 1 lúc 4 giờ 30 chiều — Cách quảng bá bản thân\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To set yourself apart from other job candidates, you have to effectively communicate the value you’ll bring to the company.\", \"vi\": \"Để tạo sự khác biệt so với các ứng viên khác, quý vị cần truyền đạt một cách hiệu quả những giá trị mà quý vị sẽ mang lại cho công ty.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This session will help you successfully promote yourself to potential employers, both in person and through social media.\", \"vi\": \"Buổi học này sẽ giúp quý vị quảng bá bản thân một cách hiệu quả đến các nhà tuyển dụng tiềm năng, cả trực tiếp lẫn qua các nền tảng mạng xã hội.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"January 17 at 4:30 P.M.—Interview Strategies\", \"vi\": \"Ngày 17 tháng 1 lúc 4 giờ 30 chiều — Các chiến lược phỏng vấn\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Get tips on interview rules, common questions, and the process for what you need to do before, during, and after a job interview.\", \"vi\": \"Hãy tham khảo các lời khuyên về các quy tắc phỏng vấn, những câu hỏi thường gặp, cũng như quy trình những việc quý vị cần thực hiện trước, trong và sau buổi phỏng vấn xin việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"This session will be interactive, featuring mock interviews with attendees.\", \"vi\": \"Buổi hội thảo này sẽ mang tính tương tác cao, với phần thực hành phỏng vấn thử dành cho quý vị tham dự.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Go to www.marilisprofessionalcoaching.com/register to sign up for any of these low-cost events.\", \"vi\": \"Vui lòng truy cập trang web www.marilisprofessionalcoaching.com/register để đăng ký tham gia bất kỳ sự kiện nào trong số các sự kiện có chi phí thấp này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Note that all January events are virtual.\", \"vi\": \"Xin lưu ý rằng tất cả các sự kiện trong tháng Giêng đều được tổ chức trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '61684f76-93b8-4556-85b5-eb8f308047fb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"New Dean Appointed at Institute\", \"vi\": \"Viện đã bổ nhiệm Hiệu trưởng mới\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"YORK (17 January)—The Callard Eye Institute announced on Tuesday that Jennifer Robbins, M.D., has accepted the position of dean, effective immediately.\", \"vi\": \"YORK (ngày 17 tháng 1) — Viện Mắt Callard đã thông báo vào thứ Ba rằng Bác sĩ Jennifer Robbins đã nhận chức vụ Hiệu trưởng, có hiệu lực ngay lập tức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Dr. Robbins, who grew up in York, earned her medical degree at Labato School of Medicine and completed a postdoctoral residency at Petersen Medical Center.\", \"vi\": \"Bác sĩ Robbins, người lớn lên tại York, đã tốt nghiệp bác sĩ y khoa tại Trường Y Labato và hoàn thành chương trình nội trú sau tiến sĩ tại Trung tâm Y tế Petersen.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Before she arrived at the institute, Dr. Robbins was the founder and director of the ophthalmology clinic at Morseville Hospital.\", \"vi\": \"Trước khi gia nhập viện, Tiến sĩ Robbins từng là người sáng lập kiêm giám đốc phòng khám nhãn khoa tại Bệnh viện Morseville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Her innovations in treating eye diseases have benefited thousands of patients worldwide.\", \"vi\": \"Những đóng góp sáng tạo của bà trong lĩnh vực điều trị các bệnh về mắt đã mang lại lợi ích cho hàng nghìn bệnh nhân trên toàn thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"On April 17, Dr. Robbins will be in Berlin to receive the Kramer Medal for Medical Excellence at this year\'s conference of the International Center for Vision Advancement.\", \"vi\": \"Vào ngày 17 tháng 4, Tiến sĩ Robbins sẽ có mặt tại Berlin để nhận Huy chương Kramer vinh danh những thành tựu xuất sắc trong lĩnh vực y khoa tại hội nghị năm nay của Trung tâm Quốc tế về Phát triển Thị giác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"8:00–10:00 A.M. - Breakfast - Maiwald Lounge\", \"vi\": \"8:00–10:00 sáng - Bữa sáng - Maiwald Lounge\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"10:00–11:00 A.M. - Welcome and keynote address - Jahn Conference Hall\", \"vi\": \"10:00–11:00 sáng - Lễ khai mạc và bài phát biểu chính - Hội trường Jahn\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"11:15 A.M.–1:15 P.M. - Session 1: New Technologies - Breakout rooms, as assigned\", \"vi\": \"11 giờ 15 phút sáng – 1 giờ 15 phút chiều - Phiên 1: Công nghệ mới - Các phòng thảo luận nhỏ, theo phân công\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"1:30–3:30 P.M. - Lunch group seminar - Edwards Room\", \"vi\": \"13h30–15h30 – Buổi hội thảo nhóm trong giờ ăn trưa – Phòng Edwards\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"3:45–5:45 P.M. - Session 2: Quality Eye Care - Breakout rooms, as assigned\", \"vi\": \"15:45–17:45 – Phiên 2: Chăm sóc mắt chất lượng – Các phòng thảo luận nhỏ, theo sự phân công\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"6:00–7:30 P.M. - Free period - ---\", \"vi\": \"18:00–19:30 - Giờ tự do - ---\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"7:30–9:00 P.M. - Dinner - Regal Ballroom\", \"vi\": \"19:30–21:00 – Bữa tối – Phòng khiêu vũ Regal\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"9:00–9:30 P.M. - Dessert and awards ceremony - Regal Ballroom\", \"vi\": \"21:00–21:30 - Món tráng miệng và lễ trao giải - Phòng khiêu vũ Regal\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"International Center for Vision Advancement (ICVA) Conference\", \"vi\": \"Hội nghị của Trung tâm Quốc tế về Phát triển Thị giác (ICVA)\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"JT Pepper Convention Hall (17–19 April)\", \"vi\": \"Trung tâm Hội nghị JT Pepper (từ ngày 17 đến ngày 19 tháng 4)\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Rosenthaler Strasse 65, Berlin, Germany 25627\", \"vi\": \"Số 65 đường Rosenthaler, Berlin, Đức 25627\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Day 1 Schedule: Monday, 17 April\", \"vi\": \"Lịch trình ngày 1: Thứ Hai, ngày 17 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To: Dae-Ho Sohn\", \"vi\": \"Kính gửi: Ông Dae-Ho Sohn\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: Paulina Raskin\", \"vi\": \"Từ: Paulina Raskin\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Subject: Your presentation\", \"vi\": \"Chủ đề: Bài thuyết trình của quý vị\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Date: 22 April\", \"vi\": \"Ngày: 22 tháng 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Dear Dr. Sohn,\", \"vi\": \"Kính gửi Tiến sĩ Sohn,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I just wanted to thank you again for speaking at the ICVA conference in Berlin last week.\", \"vi\": \"Tôi chỉ muốn một lần nữa gửi lời cảm ơn quý vị vì đã phát biểu tại hội nghị ICVA ở Berlin vào tuần trước.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I am sure I am not alone in saying that the highlight of the conference was your keynote address.\", \"vi\": \"Tôi tin chắc rằng không chỉ riêng tôi mới cho rằng điểm nhấn của hội nghị chính là bài phát biểu khai mạc của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Your insights into recent advancements in eye-surgery techniques captured the attention of everyone in the room.\", \"vi\": \"Những nhận định của quý vị về những tiến bộ gần đây trong kỹ thuật phẫu thuật mắt đã thu hút sự chú ý của tất cả mọi người có mặt trong phòng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"We were grateful that you could join us and even more appreciative of all the help and guidance you have provided in the past as an active member of the ICVA Board of Directors.\", \"vi\": \"Chúng tôi rất biết ơn vì quý vị đã có thể tham gia cùng chúng tôi và càng trân trọng hơn nữa tất cả sự giúp đỡ và hướng dẫn mà quý vị đã dành cho chúng tôi trong thời gian qua với tư cách là một thành viên tích cực của Hội đồng Quản trị ICVA.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Paulina Raskin\", \"vi\": \"Paulina Raskin\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"President, International Center for Vision Advancement\", \"vi\": \"Chủ tịch, Trung tâm Quốc tế về Phát triển Thị giác\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}]' WHERE `id` = '619d43ba-a380-4e50-b8f6-fd334ca3f300';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Red Division Sales Team Members\", \"vi\": \"Đến: Các thành viên Đội ngũ Kinh doanh Phân khu Đỏ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Matias Gama, Director\", \"vi\": \"Từ: Matias Gama, Giám đốc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 22 November\", \"vi\": \"Ngày: 22 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Third-quarter results\", \"vi\": \"Đính kèm: Kết quả kinh doanh quý ba\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Let me commend all of you on your outstanding work this past quarter!\", \"vi\": \"Tôi xin biểu dương tất cả các bạn vì công việc xuất sắc trong quý vừa qua!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"See for yourselves in the attached report, which provides all the details.\", \"vi\": \"Hãy tự mình kiểm chứng trong báo cáo đính kèm, nơi cung cấp tất cả các chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"______[139], there\'s always room for growth.\", \"vi\": \"______[139], luôn có dư địa để phát triển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [139]}, {\"en\": \"That\'s why we\'re launching a new ______[140] program.\", \"vi\": \"Đó là lý do tại sao chúng tôi đang khởi động một chương trình ______[140] mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [140]}, {\"en\": \"It will be provided by an outside agency that has carefully ______[141] our needs.\", \"vi\": \"Chương trình này sẽ do một cơ quan bên ngoài cung cấp, đơn vị đã nghiên cứu kỹ lưỡng ______[141] các nhu cầu của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [141]}, {\"en\": \"Although the learning modules will be offered across the organization, they are scheduled to begin in our division.\", \"vi\": \"Mặc dù các học phần đào tạo sẽ được cung cấp trên toàn bộ tổ chức, nhưng chúng được lên lịch bắt đầu tại phân khu của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"______[142].\", \"vi\": \"______[142].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [142]}, {\"en\": \"In the meantime, please carry on with your good work.\", \"vi\": \"Trong thời gian này, xin hãy tiếp tục phát huy công việc tốt đẹp của các bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '61b4b2f7-5c6f-4788-968d-72c9c236f52a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"7:30 A.M.–9:00 A.M. - Conference Registration\", \"vi\": \"7 giờ 30 sáng – 9 giờ sáng - Đăng ký tham dự hội nghị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"9:00 A.M.–9:10 A.M. - Welcome and Opening Remarks: Yasmin Al Gaood, Conference Chair\", \"vi\": \"9:00 sáng – 9:10 sáng - Lời chào mừng và phát biểu khai mạc: Bà Yasmin Al Gaood, Chủ tịch Hội nghị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"9:15 A.M.–10:00 A.M. - Opening Keynote Address: Ayumi Murakami, STI President\", \"vi\": \"9 giờ 15 phút sáng – 10 giờ 00 phút sáng – Bài phát biểu khai mạc: Bà Ayumi Murakami, Chủ tịch STI\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"10:05 A.M.–10:50 A.M. - Title of presentation unknown: representative to be selected, Yaoundé College of Agriculture, Cameroon\", \"vi\": \"10 giờ 05 phút sáng – 10 giờ 50 phút sáng – Tên bài thuyết trình chưa rõ: đại diện sẽ được lựa chọn, Trường Cao đẳng Nông nghiệp Yaoundé, Cameroon\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"10:55 A.M.–11:40 A.M. - Innovative Online Resources: Chia Po Cheng, Taipei Business Management Institute, Taiwan\", \"vi\": \"10 giờ 55 phút sáng – 11 giờ 40 phút sáng - Các nguồn tài nguyên trực tuyến sáng tạo: Chia Po Cheng, Viện Quản trị Kinh doanh Đài Bắc, Đài Loan\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"11:45 A.M.–1:20 P.M. - Lunch (Turquoise Center, central campus)\", \"vi\": \"11 giờ 45 phút sáng – 1 giờ 20 phút chiều – Bữa trưa (Trung tâm Turquoise, khuôn viên chính)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"1:30 P.M.–2:15 P.M. - Distance Education in the Film Industry: representative from Scotland to be selected\", \"vi\": \"13h30–14h15 – Giáo dục từ xa trong ngành điện ảnh: Đại diện từ Scotland sẽ được lựa chọn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"2:20 P.M.–3:05 P.M. - Improving Course Content Quality: Andrei Durchenko, Moscow Journalism Academy, Russia\", \"vi\": \"14 giờ 20 – 15 giờ 05 – Nâng cao chất lượng nội dung khóa học: Andrei Durchenko, Học viện Báo chí Moscow, Nga\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"3:10 P.M.–4:00 P.M. - Learner Support Systems: Marcel Peralta, School of Pediatric Dentistry, Asunción, Paraguay\", \"vi\": \"15 giờ 10 – 16 giờ 00 - Hệ thống hỗ trợ người học: Marcel Peralta, Khoa Nha khoa Nhi, Asunción, Paraguay\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Society for Trade and Industry (STI)\", \"vi\": \"Hiệp hội Thương mại và Công nghiệp (STI)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"\\\"The Role of Distance Education in Professional Training\\\"\", \"vi\": \"\\\"Vai trò của giáo dục từ xa trong đào tạo chuyên môn\\\"\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"City University of Abu Dhabi, 11–13 October\", \"vi\": \"Đại học Thành phố Abu Dhabi, từ ngày 11 đến ngày 13 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"DRAFT: Schedule for Wednesday, 11 October\", \"vi\": \"BẢN DỰ THẢO: Lịch trình cho ngày thứ Tư, 11 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"From: Ayumi Murakami <amurakami@sti.org>\", \"vi\": \"Từ: Ayumi Murakami <amurakami@sti.org>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To: Yasmin Al Gaood <yasmin.algaood@cuad.ac.ae>\", \"vi\": \"Gửi: Yasmin Al Gaood <yasmin.algaood@cuad.ac.ae>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Subject: Re: Draft conference schedule for Wednesday\", \"vi\": \"Chủ đề: Trả lời: Dự thảo lịch trình hội nghị cho ngày thứ Tư\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Date: 25 August\", \"vi\": \"Ngày: 25 tháng 8\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Hello, Yasmin,\", \"vi\": \"Xin chào, Yasmin,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"As per your request, I have filled the slots that were listed as still available on the tentative conference schedule for Wednesday.\", \"vi\": \"Theo yêu cầu của quý vị, tôi đã sắp xếp các khung giờ còn trống được liệt kê trong lịch trình dự kiến của hội nghị vào thứ Tư.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Dr. Alban Buchanan in Scotland says that he is eager to talk about distance education as it is practiced within the film academies in his country.\", \"vi\": \"Tiến sĩ Alban Buchanan tại Scotland cho biết ông rất mong muốn được chia sẻ về hình thức giáo dục từ xa đang được áp dụng tại các học viện điện ảnh ở đất nước ông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Also, my contact in Yaoundé wrote to let me know that Ms. Marie-Thérèse Tchangou will be the school\'s representative.\", \"vi\": \"Ngoài ra, người liên hệ của tôi tại Yaoundé đã gửi thư thông báo rằng bà Marie-Thérèse Tchangou sẽ là đại diện của trường.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Mr. Andrei Durchenko has informed me that he is withdrawing from the conference.\", \"vi\": \"Ông Andrei Durchenko đã thông báo với tôi rằng ông sẽ không tham dự hội nghị nữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"His replacement from the same school, Ms. Melina Vakhitova, will submit the title of her presentation shortly.\", \"vi\": \"Người thay thế ông, cũng đến từ trường này, bà Melina Vakhitova, sẽ sớm gửi tên bài thuyết trình của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I also wanted to add that I will be arriving in Abu Dhabi at 6:00 A.M. on Wednesday.\", \"vi\": \"Tôi cũng muốn cho biết thêm rằng tôi sẽ đến Abu Dhabi vào lúc 6 giờ sáng thứ Tư.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"That should give me plenty of time to set up for my presentation.\", \"vi\": \"Điều đó sẽ giúp tôi có đủ thời gian để chuẩn bị cho phần trình bày của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Ayumi\", \"vi\": \"Ayumi\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '61f14a4e-f9ed-4065-8b1c-776051ef00a5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Research Findings Presented\", \"vi\": \"Công bố kết quả nghiên cứu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"GALWAY (1 July)—Eva Urban and her research team at the Ireland Agronomy Association presented their findings to the Galway Department of Transportation on Thursday.\", \"vi\": \"GALWAY (ngày 1 tháng 7) — Eva Urban cùng nhóm nghiên cứu của bà thuộc Hiệp hội Nông học Ireland đã trình bày kết quả nghiên cứu của mình trước Sở Giao thông Vận tải Galway vào thứ Năm vừa qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"During their three-year study, the team was tasked with researching ways to improve the success of tree and shrub plantings along roadways.\", \"vi\": \"Trong suốt quá trình nghiên cứu kéo dài ba năm, nhóm nghiên cứu được giao nhiệm vụ tìm tòi các phương pháp nhằm nâng cao hiệu quả của việc trồng cây gỗ và cây bụi dọc theo các tuyến đường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —\", \"vi\": \"— [1] —\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"“The ground next to newly paved roads is often compacted by heavy machinery associated with construction,” Ms. Urban said.\", \"vi\": \"“Mặt đất bên cạnh những con đường mới được trải nhựa thường bị nén chặt bởi các loại máy móc hạng nặng phục vụ công trình xây dựng,” bà Urban cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"“As a result, the soil can’t absorb water or nutrients well, which makes it difficult for new growth to establish itself.\", \"vi\": \"“Do đó, đất không thể hấp thụ nước hay chất dinh dưỡng một cách hiệu quả, khiến cho các chồi non khó có thể phát triển vững chắc.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] — My team set up different experimental plots alongside highways and tried various combinations of planting, tilling, and amending soils to determine what worked.”\", \"vi\": \"— [2] — Nhóm của tôi đã thiết lập các ô thí nghiệm khác nhau dọc theo các tuyến đường cao tốc và thử nghiệm nhiều phương án kết hợp khác nhau giữa việc trồng trọt, xới đất và bón phân để xác định phương án nào mang lại hiệu quả.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The final results of the government-sponsored research project were compiled into a 50-page handbook.\", \"vi\": \"Kết quả cuối cùng của dự án nghiên cứu do chính phủ tài trợ đã được tổng hợp thành một cuốn cẩm nang dày 50 trang.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Although the handbook was written specifically for the Galway Department of Transportation, its recommendations can be applied by municipal agencies throughout the country.\", \"vi\": \"Mặc dù cuốn cẩm nang này được biên soạn dành riêng cho Sở Giao thông Vận tải Galway, nhưng các khuyến nghị trong đó có thể được các cơ quan hành chính địa phương trên toàn quốc áp dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [3] —\", \"vi\": \"— [3] —\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"“Each chapter explores one of the ten best practices identified by the team,” said Ms. Urban.\", \"vi\": \"“Mỗi chương sẽ đi sâu vào một trong mười phương pháp thực hành tốt nhất mà nhóm nghiên cứu đã xác định,” bà Urban cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"“These basic techniques are relevant regardless of where they are implemented.\", \"vi\": \"“Những kỹ thuật cơ bản này đều có giá trị bất kể được áp dụng ở đâu.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The only site-specific variable is plant selection, as that will depend upon the particular geographic region.”\", \"vi\": \"“Yếu tố duy nhất phụ thuộc vào điều kiện cụ thể của từng địa điểm là việc lựa chọn loài cây, bởi điều này sẽ phụ thuộc vào từng khu vực địa lý cụ thể.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Another point conveyed by the study is that successful plant establishment requires an integrated approach.\", \"vi\": \"Một điểm khác mà nghiên cứu này nêu ra là việc trồng cây thành công đòi hỏi phải có một phương pháp tiếp cận tổng hợp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Improving roadside planting requires a thorough assessment of a site’s existing conditions as well as a wide variety of management practices to address the specific issues involved.\", \"vi\": \"Việc cải thiện việc trồng cây ven đường đòi hỏi phải tiến hành đánh giá kỹ lưỡng các điều kiện hiện có của khu vực, cũng như áp dụng nhiều biện pháp quản lý đa dạng nhằm giải quyết các vấn đề cụ thể liên quan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '621e8239-7822-4781-a023-d8896ddd349c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Kooper\'s Vision is seeking an optician for its eyewear department.\", \"vi\": \"Kooper\'s Vision đang tuyển dụng một chuyên viên kính mắt cho bộ phận kính mắt của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Must have a valid Massachusetts optician license and at least three years of relevant experience.\", \"vi\": \"Phải có giấy phép hành nghề kỹ thuật viên kính mắt hợp lệ do bang Massachusetts cấp và có ít nhất ba năm kinh nghiệm trong lĩnh vực này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The position requires excellent customer service skills and a strong awareness of current fashion trends in the industry.\", \"vi\": \"Vị trí này đòi hỏi kỹ năng chăm sóc khách hàng xuất sắc và sự am hiểu sâu sắc về các xu hướng thời trang hiện nay trong ngành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Responsibilities include helping clients choose frames, ordering eyeglasses, and filing insurance claims.\", \"vi\": \"Các nhiệm vụ bao gồm hỗ trợ khách hàng lựa chọn gọng kính, đặt hàng kính mắt và hoàn tất thủ tục yêu cầu bồi thường bảo hiểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"This full-time position is available at Kooper\'s Vision at Danvers Mall.\", \"vi\": \"Vị trí làm việc toàn thời gian này đang được tuyển dụng tại Kooper\'s Vision, thuộc Trung tâm thương mại Danvers Mall.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Contact store manager Tanisha Mosley at 978-555-0101.\", \"vi\": \"Vui lòng liên hệ với bà Tanisha Mosley, Quản lý cửa hàng, theo số điện thoại 978-555-0101.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Must be available to start during the last week of August.\", \"vi\": \"Phải sẵn sàng bắt đầu làm việc trong tuần cuối cùng của tháng Tám.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"https://www.koopersvision.com\", \"vi\": \"https://www.koopersvision.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Kooper\'s Vision at Danvers Mall\", \"vi\": \"Tầm nhìn của Kooper tại Danvers Mall\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Hours:\", \"vi\": \"Giờ làm việc:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Monday 10 A.M.–7 P.M.\", \"vi\": \"Thứ Hai, từ 10 giờ sáng đến 7 giờ tối\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Tuesday 10 A.M.–7 P.M.\", \"vi\": \"Thứ Ba, từ 10 giờ sáng đến 7 giờ tối\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Wednesday 10 A.M.–7 P.M.\", \"vi\": \"Thứ Tư, từ 10 giờ sáng đến 7 giờ tối\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Thursday 10 A.M.–7 P.M.\", \"vi\": \"Thứ Năm, từ 10 giờ sáng đến 7 giờ tối\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Friday 10 A.M.–7 P.M.\", \"vi\": \"Thứ Sáu, từ 10 giờ sáng đến 7 giờ tối\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Saturday 10 A.M.–6 P.M.\", \"vi\": \"Thứ Bảy, từ 10 giờ sáng đến 6 giờ chiều\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sunday 10 A.M.–4 P.M.\", \"vi\": \"Chủ nhật, từ 10 giờ sáng đến 4 giờ chiều\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"During the month of August, enjoy 50% off the second pair of eyeglasses.\", \"vi\": \"Trong tháng 8, quý khách sẽ được hưởng ưu đãi giảm giá 50% cho cặp kính thứ hai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Kooper\'s Vision is your local optical center for all your eye-care needs in Danvers, Massachusetts.\", \"vi\": \"Kooper’s Vision là trung tâm nhãn khoa tại địa phương, sẵn sàng đáp ứng mọi nhu cầu chăm sóc mắt của quý vị tại Danvers, Massachusetts.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"We are located on the upper level of the Danvers Mall next to Eight Days Sporting Goods.\", \"vi\": \"Chúng tôi tọa lạc tại tầng trên của Trung tâm thương mại Danvers, ngay bên cạnh cửa hàng Eight Days Sporting Goods.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Call 978-555-0101 today to schedule your annual eye exam.\", \"vi\": \"Hãy gọi ngay số 978-555-0101 hôm nay để đặt lịch khám mắt hàng năm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Exams by appointment only.\", \"vi\": \"Chỉ tiến hành khám theo lịch hẹn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Optical Centers Reviews\", \"vi\": \"Các đánh giá về Trung tâm Kính mắt\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Rating: 5 stars ★★★★★\", \"vi\": \"Đánh giá: 5 sao ★★★★★\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I have been wearing eyeglasses since I was ten years old.\", \"vi\": \"Tôi đã đeo kính từ khi mười tuổi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I now have five children, and four of them wear glasses, so I have visited many opticians over the years.\", \"vi\": \"Hiện tại tôi có năm người con, và bốn trong số đó phải đeo kính, vì vậy trong suốt những năm qua, tôi đã đến thăm rất nhiều tiệm kính.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"My recent visit to Kooper\'s Vision on August 31 was, by far, the best.\", \"vi\": \"Chuyến thăm gần đây nhất của tôi đến Kooper\'s Vision vào ngày 31 tháng 8 quả thực là chuyến thăm tuyệt vời nhất từ trước đến nay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Ms. Palmer offered her help when she saw that I was overwhelmed by the eyeglass selection at Kooper\'s Vision.\", \"vi\": \"Khi thấy tôi bối rối trước quá nhiều lựa chọn kính mắt tại Kooper\'s Vision, bà Palmer đã đề nghị giúp đỡ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"She looked at the shape of my face and steered me toward a few pairs of glasses that were perfect for me!\", \"vi\": \"Cô ấy quan sát hình dáng khuôn mặt của tôi và chỉ cho tôi một vài cặp kính rất phù hợp với tôi!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"She knew exactly what looked best on me and advised me about the size, color, quality, and cost of the frames I considered.\", \"vi\": \"Cô ấy biết rõ điều gì sẽ phù hợp nhất với tôi và đã tư vấn cho tôi về kích cỡ, màu sắc, chất lượng cũng như giá cả của những chiếc gọng kính mà tôi đang cân nhắc.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Ms. Palmer also explained the different types of lenses and lens coatings available.\", \"vi\": \"Bà Palmer cũng đã giải thích về các loại tròng kính và lớp phủ tròng kính hiện có trên thị trường.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I could not decide which was my favorite pair of eyeglasses, so I bought two pairs!\", \"vi\": \"Tôi không thể quyết định được cặp kính nào là cặp tôi thích nhất, nên tôi đã mua hẳn hai cặp!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I was incredulous when she told me it was her first day working at the store—she was the best optician I have ever had!\", \"vi\": \"Tôi thực sự không thể tin nổi khi cô ấy nói với tôi rằng đó là ngày đầu tiên cô ấy làm việc tại cửa hàng — cô ấy quả thực là chuyên viên kính mắt giỏi nhất mà tôi từng gặp!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Melvin Drake\", \"vi\": \"Melvin Drake\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '621fdb41-0021-49ae-ae11-c3fbebe2bb93';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Kyung-Jin Sohn\", \"vi\": \"Gửi: Kyung-Jin Sohn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Darius Jackson\", \"vi\": \"Từ: Darius Jackson\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: November 8\", \"vi\": \"Ngày: 8 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Solutions to a problem\", \"vi\": \"Chủ đề: Các giải pháp cho một vấn đề\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Sohn,\", \"vi\": \"Kính gửi Bà Sohn,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As you know, competition for use of the printers has been causing a great deal of delay for members of the legal department.\", \"vi\": \"Như quý vị đã biết, tình trạng tranh giành việc sử dụng máy in đã gây ra không ít sự chậm trễ cho các thành viên của phòng pháp chế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Everyone has had to wait to print documents at some point.\", \"vi\": \"Chắc hẳn ai cũng đã từng phải chờ đợi để in tài liệu vào một thời điểm nào đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Some of us have had to start coming to work earlier, and others are staying late.\", \"vi\": \"Một số người trong chúng ta đã phải đi làm sớm hơn, trong khi những người khác thì ở lại làm muộn hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This is having a negative impact on our productivity and morale.\", \"vi\": \"Điều này đang gây ra tác động tiêu cực đến năng suất lao động và tinh thần làm việc của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We could improve the situation for the remainder of the year by posting a sign-up sheet next to the printers.\", \"vi\": \"Chúng ta có thể cải thiện tình hình trong thời gian còn lại của năm bằng cách treo một bảng đăng ký bên cạnh các máy in.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To be fair, each employee should sign up for only two fifteen-minute blocks per day.\", \"vi\": \"Để công bằng, mỗi nhân viên chỉ nên đăng ký tối đa hai khung giờ, mỗi khung giờ kéo dài mười lăm phút mỗi ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We could also reserve the lunch hour for unscheduled printing.\", \"vi\": \"Chúng ta cũng có thể dành giờ ăn trưa để in ấn ngoài lịch trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"And we should consider discontinuing the use of color printers until the situation is under control—color printing is up to five times as expensive as black-and-white printing.\", \"vi\": \"Và chúng ta nên xem xét việc ngừng sử dụng máy in màu cho đến khi tình hình được kiểm soát — chi phí in màu đắt gấp tới năm lần so với in đen trắng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Let me know what you think.\", \"vi\": \"Xin vui lòng cho tôi biết ý kiến của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Darius Jackson\", \"vi\": \"Darius Jackson\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Legal Administrator, Reeder and Kelter, Inc.\", \"vi\": \"Chuyên viên Hành chính Pháp lý, Công ty Reeder and Kelter, Inc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"MEMO\", \"vi\": \"BẢN GHI NHỚ\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To: All Reeder and Kelter, Inc., Staff\", \"vi\": \"Kính gửi: Toàn thể nhân viên Công ty Reeder and Kelter, Inc.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: Kyung-Jin Sohn, Support Manager\", \"vi\": \"Từ: Kyung-Jin Sohn, Trưởng phòng Hỗ trợ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date: November 24\", \"vi\": \"Ngày: 24 tháng 11\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subject: Printer use\", \"vi\": \"Chủ đề: Việc sử dụng máy in\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"We have purchased two new printers, a multicolor UX212 and a black-and-white UY120 Truzynx.\", \"vi\": \"Chúng tôi đã mua hai máy in mới, bao gồm một máy in đa màu UX212 và một máy in đen trắng UY120 Truzynx.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Unfortunately, they will not be arriving until December 18.\", \"vi\": \"Thật không may, họ sẽ không đến được cho đến ngày 18 tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"In the meantime, please continue to schedule your printer-use times using the online link I e-mailed you on November 10.\", \"vi\": \"Trong thời gian này, xin quý vị vui lòng tiếp tục đặt lịch sử dụng máy in thông qua liên kết trực tuyến mà tôi đã gửi qua email cho quý vị vào ngày 10 tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Using this document, you may reserve up to two fifteen-minute printing periods per day.\", \"vi\": \"Dựa trên tài liệu này, quý vị có thể đặt trước tối đa hai khung giờ in ấn, mỗi khung giờ kéo dài mười lăm phút, mỗi ngày.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Please do not schedule consecutive sessions, and remember that we have set aside time both in the morning and in the afternoon for emergency printing.\", \"vi\": \"Xin vui lòng không đặt lịch các buổi in liên tiếp nhau, và xin lưu ý rằng chúng tôi đã dành riêng thời gian vào cả buổi sáng lẫn buổi chiều để phục vụ các trường hợp in ấn khẩn cấp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Also, please use the color printers only when absolutely necessary.\", \"vi\": \"Ngoài ra, xin vui lòng chỉ sử dụng máy in màu khi thực sự cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"We have been purchasing more color ink than usual because staff members are using the color printers for scanning and printing when the black-and-white printers are in use.\", \"vi\": \"Chúng tôi đã phải mua mực in màu nhiều hơn bình thường vì các nhân viên đang sử dụng máy in màu để quét và in khi các máy in đen trắng đang được sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"To: kjsohn@reederandkelter.com\", \"vi\": \"Gửi tới: kjsohn@reederandkelter.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"From: lsullivan@truzynx.com\", \"vi\": \"Nguồn: lsullivan@truzynx.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Date: December 22\", \"vi\": \"Ngày: 22 tháng 12\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Subject: Truzynx purchase\", \"vi\": \"Chủ đề: Việc mua sản phẩm Truzynx\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Dear Ms. Sohn,\", \"vi\": \"Kính gửi bà Sohn,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Thank you for your recent purchase of two Truzynx printers for your company.\", \"vi\": \"Xin chân thành cảm ơn Quý công ty đã mua hai máy in Truzynx trong thời gian vừa qua.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Your purchase includes two years of free maintenance for each machine.\", \"vi\": \"Khi mua sản phẩm, quý khách sẽ được hưởng hai năm bảo trì miễn phí cho mỗi máy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Your first regularly scheduled servicing date will be one month from delivery.\", \"vi\": \"Lần bảo dưỡng định kỳ đầu tiên của quý khách sẽ diễn ra sau một tháng kể từ ngày nhận xe.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"We also offer discounted prices on our extended maintenance plans within 60 days of equipment purchase.\", \"vi\": \"Chúng tôi cũng áp dụng mức giá ưu đãi cho các gói bảo trì mở rộng trong vòng 60 ngày kể từ ngày mua thiết bị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Please let me know if you are interested in these plans for your new printers.\", \"vi\": \"Nếu quý vị quan tâm đến các bản thiết kế này cho các máy in mới của mình, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Are you looking to improve your efficiency?\", \"vi\": \"Quý vị có đang tìm cách nâng cao hiệu quả công việc của mình không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"We also have Truzplan.\", \"vi\": \"Chúng tôi còn có Truzplan.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"With this affordable remote-printing service, we can securely print your scanned documents and bring them to your office when you need them.\", \"vi\": \"Với dịch vụ in ấn từ xa với chi phí hợp lý này, chúng tôi có thể in một cách an toàn các tài liệu đã được quét của quý vị và chuyển đến văn phòng của quý vị khi quý vị cần.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Please let me know if you would like more information.\", \"vi\": \"Nếu quý vị cần thêm thông tin, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"Leilani Sullivan\", \"vi\": \"Leilani Sullivan\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"Sales Representative\", \"vi\": \"Nhân viên kinh doanh\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 46, \"question_numbers\": []}]' WHERE `id` = '622ada75-57bf-4f64-86fa-5d48cd0a013d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"HRTA Project On Track for Summer\", \"vi\": \"Dự án HRTA đang tiến triển đúng tiến độ để hoàn thành vào mùa hè\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hitchert Regional Transit Agency (HRTA) has reached another milestone in the process of adding enhanced-accessibility trains to its light-rail fleet.\", \"vi\": \"Cơ quan Giao thông Vùng Hitchert (HRTA) đã đạt được một cột mốc quan trọng nữa trong quá trình bổ sung các đoàn tàu có khả năng tiếp cận nâng cao vào đội tàu điện nhẹ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"On January 7, HRTA staff began trial operation of the trains on the Gold and Green lines in order to discover and eliminate any issues before their deployment at the start of summer.\", \"vi\": \"Vào ngày 7 tháng 1, các nhân viên của HRTA đã bắt đầu vận hành thử nghiệm các đoàn tàu trên các tuyến Gold và Green nhằm phát hiện và khắc phục mọi sự cố trước khi đưa vào khai thác chính thức vào đầu mùa hè.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"To minimize inconvenience to transport users, the trains are being run only between the hours of 8 P.M. and 4 A.M. and are marked with large “Test Train” stickers to prevent people from boarding.\", \"vi\": \"Để giảm thiểu sự bất tiện cho hành khách, các chuyến tàu hiện chỉ được vận hành trong khung giờ từ 8 giờ tối đến 4 giờ sáng và được dán nhãn “Tàu thử nghiệm” cỡ lớn để ngăn người dân lên tàu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Spreading rapidly to metropolitan areas across the country following their debut in Fonseca, the trains boast low, stair-free entrances, automatically-controlled ramps, and other features that make them more accessible to passengers with disabilities.\", \"vi\": \"Sau khi ra mắt tại Fonseca, các đoàn tàu này đã nhanh chóng lan rộng đến các khu vực đô thị trên khắp cả nước; chúng được trang bị lối vào thấp, không có bậc thang, các đường dốc điều khiển tự động cùng nhiều tính năng khác, giúp tạo điều kiện thuận lợi hơn cho hành khách khuyết tật khi sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}]' WHERE `id` = '6272eceb-21ab-4c82-a9ea-2e91271a2cd4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"PROPOSAL\", \"vi\": \"ĐỀ XUẤT\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Project For: Sethi Technologies\", \"vi\": \"Dự án dành cho: Sethi Technologies\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"34 Carnaby Street\", \"vi\": \"Số 34 Carnaby Street\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"San Francisco, CA 94129\", \"vi\": \"San Francisco, CA 94129\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Contractor Information:\", \"vi\": \"Thông tin về nhà thầu:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Geo Carpet Care\", \"vi\": \"Dịch vụ chăm sóc thảm Geo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"541 Grantham Avenue\", \"vi\": \"541 Đại lộ Grantham\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"San Francisco, CA 94128\", \"vi\": \"San Francisco, CA 94128\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Scope of Work\", \"vi\": \"Phạm vi công việc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Cleaning of all carpets and upholstered furniture in common areas and personal work spaces.\", \"vi\": \"Vệ sinh toàn bộ thảm và đồ nội thất bọc nệm tại các khu vực chung cũng như không gian làm việc cá nhân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Includes furniture moving as needed.\", \"vi\": \"Bao gồm dịch vụ di chuyển đồ đạc khi cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Temporary floor protector pads provided.\", \"vi\": \"Có cung cấp các miếng lót bảo vệ sàn tạm thời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Spot removal included.\", \"vi\": \"Đã bao gồm dịch vụ tẩy vết bẩn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"*Note: We use all-natural, odorless cleaning products.\", \"vi\": \"*Lưu ý: Chúng tôi sử dụng các sản phẩm tẩy rửa hoàn toàn tự nhiên và không mùi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Company Proposal\", \"vi\": \"Đề xuất của Công ty\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We, Geo Carpet Care, propose the above scope of work for the amount of $2,650 plus tax.\", \"vi\": \"Chúng tôi, Geo Carpet Care, xin đề xuất phạm vi công việc nêu trên với mức giá 2.650 đô la, chưa bao gồm thuế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Price includes a 10% discount for first-time customers.\", \"vi\": \"Giá đã bao gồm mức giảm giá 10% dành cho khách hàng lần đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"50% due at acceptance; balance due upon completion.\", \"vi\": \"Thanh toán 50% khi nhận hàng; số tiền còn lại sẽ được thanh toán khi hoàn thành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Price remains valid for 30 days after proposal submission.\", \"vi\": \"Giá này vẫn có hiệu lực trong vòng 30 ngày kể từ ngày nộp đề xuất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Submitted by: Martin Acosta Customer Approval: ______________\", \"vi\": \"Người gửi: Martin Acosta Sự chấp thuận của khách hàng: ______________\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date: June 1             Date: ______________\", \"vi\": \"Ngày: 1 tháng 6             Ngày: ______________\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"FRESHEN CARPETS: PROPOSAL\", \"vi\": \"LÀM SẠCH THẢM: ĐỀ XUẤT\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"8423 Golden Way\", \"vi\": \"8423 Golden Way\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"San Francisco, CA 94124\", \"vi\": \"San Francisco, CA 94124\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Customer: Sethi Technologies\", \"vi\": \"Khách hàng: Sethi Technologies\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Address: 34 Carnaby Street, San Francisco, CA 94129\", \"vi\": \"Địa chỉ: 34 Carnaby Street, San Francisco, CA 94129\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date: June 5\", \"vi\": \"Ngày: 5 tháng 6\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Freshen Carpets proposes to clean the entire carpeted area of customer\'s premises and clean all upholstered furniture.\", \"vi\": \"Freshen Carpets đề xuất tiến hành vệ sinh toàn bộ khu vực trải thảm tại cơ sở của quý khách hàng cũng như làm sạch tất cả các đồ nội thất bọc nệm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Clearing of floor space to be completed by customer.\", \"vi\": \"Việc dọn dẹp không gian sàn do quý khách chịu trách nhiệm hoàn tất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Spot removal extra.\", \"vi\": \"Dịch vụ tẩy vết bẩn tính phí thêm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Cost: $1,900 + tax (reflects the standard reduced price for new customers)\", \"vi\": \"Giá: 1.900 USD + thuế (đã bao gồm mức giá ưu đãi tiêu chuẩn dành cho khách hàng mới)\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Payment due to representative upon completion of service.\", \"vi\": \"Phải thanh toán cho đại diện ngay sau khi hoàn tất dịch vụ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"This proposal is good for 30 days.\", \"vi\": \"Đề xuất này có hiệu lực trong vòng 30 ngày.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Prepared by: Richard White\", \"vi\": \"Soạn thảo bởi: Richard White\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Purchaser Acceptance: ______________\", \"vi\": \"Sự chấp thuận của người mua: ______________\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Date: ______________\", \"vi\": \"Ngày: ______________\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"To: All Sethi Technologies Employees\", \"vi\": \"Kính gửi: Toàn thể nhân viên Công ty Sethi Technologies\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"From: Joe Tierney, Facilities Department\", \"vi\": \"Từ: Joe Tierney, Phòng Quản lý Cơ sở Vật chất\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Subject: Carpet Cleaning\", \"vi\": \"Chủ đề: Vệ sinh thảm\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Date: June 25\", \"vi\": \"Ngày: 25 tháng 6\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"On Saturday morning, all of the carpets and upholstered furniture will be cleaned.\", \"vi\": \"Vào sáng thứ Bảy, tất cả các tấm thảm và đồ nội thất bọc nệm sẽ được làm sạch.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"In preparation for the work, some of our facilities staff members will be moving furniture as necessary on Friday evening so that the cleaning crew can access the areas on Saturday.\", \"vi\": \"Để chuẩn bị cho công việc này, một số nhân viên phụ trách cơ sở vật chất của chúng tôi sẽ di chuyển đồ đạc khi cần thiết vào tối thứ Sáu, nhằm tạo điều kiện cho đội vệ sinh tiếp cận các khu vực này vào thứ Bảy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"In addition, we ask that before you leave on Friday, you remove any fragile or valuable personal items from your work space.\", \"vi\": \"Ngoài ra, chúng tôi xin đề nghị quý vị trước khi ra về vào thứ Sáu, vui lòng dọn dẹp tất cả các vật dụng cá nhân dễ vỡ hoặc có giá trị ra khỏi khu vực làm việc của mình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Please do not leave any confidential work material in plain view.\", \"vi\": \"Xin vui lòng không để bất kỳ tài liệu công việc mang tính bảo mật nào ở nơi dễ nhìn thấy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"The carpets and furniture will be dry by Monday.\", \"vi\": \"Thảm và đồ nội thất sẽ khô vào thứ Hai.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"Do not come in over the weekend; work at home if necessary.\", \"vi\": \"Xin đừng đến văn phòng vào cuối tuần; nếu cần, hãy làm việc tại nhà.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 46, \"question_numbers\": []}]' WHERE `id` = '62784141-d296-442f-8bcc-8a3ca6ae0b64';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Marcus Gollancz (3:18 P.M.)\", \"vi\": \"Marcus Gollancz (3 giờ 18 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Jennifer, can you be at the Browns\' house at 7:00 A.M. tomorrow to remove the furnace ductwork?\", \"vi\": \"Jennifer, ngày mai quý vị có thể đến nhà gia đình Browns vào lúc 7 giờ sáng để tháo dỡ hệ thống ống dẫn của lò sưởi được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Arthur\'s foundation-repair crew will need to access that area of the crawl space under the house.\", \"vi\": \"Đội thi công sửa chữa móng của Arthur sẽ cần tiếp cận khu vực đó của khoảng trống dưới sàn nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Jennifer Kaluza (3:20 P.M.)\", \"vi\": \"Jennifer Kaluza (3 giờ 20 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"OK, it should take me about an hour.\", \"vi\": \"Được rồi, việc này chắc sẽ mất khoảng một giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"That\'s 210 Leon Drive, right?\", \"vi\": \"Đó là số 210 đường Leon Drive, phải không ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Marcus Gollancz (3:20 P.M.)\", \"vi\": \"Marcus Gollancz (3 giờ 20 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"That\'s right.\", \"vi\": \"Đúng vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Arthur Gruyter (3:21 P.M.)\", \"vi\": \"Arthur Gruyter (3 giờ 21 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"My crew will be there to start work shortly after 8:00 A.M. tomorrow.\", \"vi\": \"Đội thợ của tôi sẽ có mặt tại đó để bắt đầu công việc ngay sau 8 giờ sáng ngày mai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Our work patching and waterproofing the foundation will likely take three or four days.\", \"vi\": \"Công việc sửa chữa và chống thấm móng của chúng tôi dự kiến sẽ mất khoảng ba hoặc bốn ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It\'s an unusually large job.\", \"vi\": \"Đây là một công việc có quy mô lớn bất thường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Jennifer Kaluza (3:22 P.M.)\", \"vi\": \"Jennifer Kaluza (3 giờ 22 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"So, when would you like me to come back to reinstall the ductwork?\", \"vi\": \"Vậy, quý vị muốn tôi quay lại để lắp đặt lại hệ thống ống dẫn vào lúc nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Marcus Gollancz (3:23 P.M.)\", \"vi\": \"Marcus Gollancz (3 giờ 23 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The Browns are away on vacation, so I think Friday afternoon should be fine.\", \"vi\": \"Gia đình nhà Browns đang đi nghỉ mát, nên tôi nghĩ chiều thứ Sáu sẽ rất thuận tiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Jennifer Kaluza (3:23 P.M.)\", \"vi\": \"Jennifer Kaluza (3 giờ 23 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I\'m scheduled to work at Mr. Amadi\'s apartment on Friday—can the Browns\' ductwork wait until Monday?\", \"vi\": \"Tôi có lịch làm việc tại căn hộ của ông Amadi vào thứ Sáu — liệu việc lắp đặt hệ thống ống dẫn của gia đình Browns có thể hoãn lại đến thứ Hai được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Marcus Gollancz (3:24 P.M.)\", \"vi\": \"Marcus Gollancz (3 giờ 24 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Sure.\", \"vi\": \"Được ạ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Early on Monday would work.\", \"vi\": \"Sáng sớm thứ Hai sẽ được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Jennifer Kaluza (3:25 P.M.)\", \"vi\": \"Jennifer Kaluza (3 giờ 25 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"You got it, Marcus.\", \"vi\": \"Đúng rồi, Marcus.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '62d619d4-92e4-48d9-bfb6-5595afcc1b82';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Jessica Perry\", \"vi\": \"Từ: Jessica Perry\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Conference\", \"vi\": \"Chủ đề: Hội nghị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 19 July\", \"vi\": \"Ngày: 19 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Workshop application\", \"vi\": \"Tệp đính kèm: 📎 Đơn đăng ký tham gia hội thảo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Hello everyone,\", \"vi\": \"Xin chào quý vị,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The fourth annual Australian National Sales and Marketing Conference (ANSMC) will take place from 18 to 22 November here in Perth.\", \"vi\": \"Hội nghị Bán hàng và Tiếp thị Toàn quốc Úc (ANSMC) lần thứ tư sẽ diễn ra từ ngày 18 đến ngày 22 tháng 11 tại Perth.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Conference organizers have asked local marketing specialists to help out by giving a keynote speech, leading a workshop, or working in the exhibition hall.\", \"vi\": \"Ban tổ chức hội nghị đã đề nghị các chuyên gia tiếp thị địa phương hỗ trợ bằng cách trình bày bài phát biểu chính, dẫn dắt hội thảo hoặc tham gia làm việc tại khu triển lãm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Our chief executive officer, Martin Hughes, wants us to take advantage of this excellent opportunity for Hughes Australia Marketing to achieve visibility on a national stage.\", \"vi\": \"Giám đốc điều hành của chúng tôi, ông Martin Hughes, mong muốn chúng ta tận dụng cơ hội tuyệt vời này để Hughes Australia Marketing có thể khẳng định vị thế trên phạm vi toàn quốc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"It is sure to help us to expand our client base.\", \"vi\": \"Điều này chắc chắn sẽ giúp chúng tôi mở rộng cơ sở khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Mr. Hughes has already agreed to give a keynote speech about using survey results to create successful marketing campaigns.\", \"vi\": \"Ông Hughes đã đồng ý phát biểu khai mạc về việc ứng dụng kết quả khảo sát để xây dựng các chiến dịch tiếp thị thành công.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I am designing our company\'s booth for the exhibition hall.\", \"vi\": \"Tôi đang thiết kế gian hàng của công ty chúng tôi tại khu triển lãm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If you would like to help, please come to Room C556 at 2:00 P.M. next Tuesday, 23 July, for a planning meeting.\", \"vi\": \"Nếu quý vị muốn góp sức, xin vui lòng đến Phòng C556 vào lúc 2 giờ chiều Thứ Ba tuần tới, ngày 23 tháng 7, để tham dự cuộc họp lập kế hoạch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"If you would like to lead a workshop, please complete the attached proposal form and return it to me by 26 July.\", \"vi\": \"Nếu quý vị có mong muốn dẫn dắt một buổi hội thảo, xin vui lòng điền vào mẫu đề xuất đính kèm và gửi lại cho tôi trước ngày 26 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"You may present alone or with a partner.\", \"vi\": \"Quý vị có thể trình bày một mình hoặc cùng với một đối tác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Workshop ideas will be discussed and approved at a managers\' meeting on 29 July.\", \"vi\": \"Các ý tưởng về hội thảo sẽ được thảo luận và thông qua tại cuộc họp các nhà quản lý vào ngày 29 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Jessica\", \"vi\": \"Jessica\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '62e13eaf-785f-49e3-827d-8dd637cdaf5b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Friends of the Chesterton Public Library\\nBook Sale\", \"vi\": \"Hội Bạn bè Thư viện Công cộng Chesterton\\nChương trình bán sách\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Chesterton Public Library will host its annual book sale this weekend on the library’s second floor.\", \"vi\": \"Thư viện Công cộng Chesterton sẽ tổ chức đợt bán sách thường niên vào cuối tuần này tại tầng hai của thư viện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The hours are Saturday, November 16, 9:00 A.M. to 5:00 P.M., and Sunday, November 17, 12:00 noon to 5:00 P.M. A special preview sale for the Friends of Chesterton Public Library (FCPL), the library’s volunteer support group, will be held on Friday, November 15, from 4:00 P.M. to 8:00 P.M.\", \"vi\": \"Thời gian diễn ra sự kiện là từ 9 giờ sáng đến 5 giờ chiều Thứ Bảy, ngày 16 tháng 11, và từ 12 giờ trưa đến 5 giờ chiều Chủ Nhật, ngày 17 tháng 11. Một đợt bán hàng trước dành riêng cho Hội Bạn bè Thư viện Công cộng Chesterton (FCPL) – nhóm tình nguyện viên hỗ trợ thư viện – sẽ được tổ chức vào Thứ Sáu, ngày 15 tháng 11, từ 4:00 chiều đến 8:00 tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The sale will include books that the library no longer lends, as well as books donated by the public.\", \"vi\": \"Chương trình bán sách này sẽ bao gồm những cuốn sách mà thư viện không còn cho mượn nữa, cũng như những cuốn sách do công chúng quyên góp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Proceeds will be used to develop a children’s reading room.\", \"vi\": \"Số tiền thu được sẽ được sử dụng để xây dựng một phòng đọc sách dành cho trẻ em.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We welcome donations of books for all ages, in all genres, in both paperback and hardcover.\", \"vi\": \"Chúng tôi hoan nghênh quý vị đóng góp các cuốn sách dành cho mọi lứa tuổi, thuộc mọi thể loại, dưới dạng bìa mềm lẫn bìa cứng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Please, note, however, that books that are torn or otherwise defaced will be rejected.\", \"vi\": \"Tuy nhiên, xin lưu ý rằng những cuốn sách bị rách hoặc bị hư hỏng dưới bất kỳ hình thức nào sẽ không được chấp nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Sorry, no magazines or journals, please.\", \"vi\": \"Xin lỗi, xin vui lòng không mang theo tạp chí hay ấn phẩm chuyên ngành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Donations for this event will be accepted through Friday, November 8, and can be dropped off at the front desk during the following times:\", \"vi\": \"Các khoản đóng góp cho sự kiện này sẽ được tiếp nhận đến hết thứ Sáu, ngày 8 tháng 11, và quý vị có thể mang đến quầy lễ tân trong các khung giờ sau đây:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Monday to Thursday: 9:00 A.M. to 11:00 A.M.\", \"vi\": \"Từ thứ Hai đến thứ Năm: 9 giờ sáng đến 11 giờ sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Wednesday: 1:00 P.M. to 8:00 P.M.\", \"vi\": \"Thứ Tư: từ 1 giờ chiều đến 8 giờ tối\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Friday: 9:00 A.M. to 3:00 P.M.\", \"vi\": \"Thứ Sáu: Từ 9 giờ sáng đến 3 giờ chiều\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you for your support!\", \"vi\": \"Xin chân thành cảm ơn sự ủng hộ của quý vị!\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '6318f36f-f6b7-43cf-ad1d-a7b11003633d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Osawa Corporate Team Building\", \"vi\": \"Hoạt động xây dựng tinh thần đồng đội của Công ty Osawa\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Bring your team together to promote cooperation while having fun!\", \"vi\": \"Hãy tập hợp đội ngũ của quý vị lại để thúc đẩy tinh thần hợp tác trong không khí vui vẻ!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Our activities increase job satisfaction and engagement.\", \"vi\": \"Các hoạt động của chúng tôi giúp nâng cao sự hài lòng trong công việc và mức độ gắn bó của nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We do all the planning so you can relax.\", \"vi\": \"Chúng tôi sẽ lo liệu mọi việc để quý vị có thể hoàn toàn thư giãn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Simply choose the event that is right for your team.\", \"vi\": \"Quý vị chỉ cần chọn sự kiện phù hợp với đội ngũ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Scavenger Hunt—An outdoor game in which teams are given a list of objects to find and photograph with their phone or camera.\", \"vi\": \"Trò chơi săn tìm kho báu — Một trò chơi ngoài trời, trong đó các đội sẽ nhận được một danh sách các vật phẩm cần tìm và chụp ảnh lại bằng điện thoại hoặc máy ảnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Group size: 10–50 people.\", \"vi\": \"Quy mô nhóm: 10–50 người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Time: 3 hours.\", \"vi\": \"Thời gian: 3 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Game Day—This is a high-energy game day with fun team activities.\", \"vi\": \"Ngày thi đấu — Đây là một ngày thi đấu sôi động với nhiều hoạt động tập thể thú vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This event builds team strength, communication, and problem-solving skills.\", \"vi\": \"Sự kiện này giúp nâng cao sức mạnh tập thể, khả năng giao tiếp và kỹ năng giải quyết vấn đề.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Group size: 20–500 people.\", \"vi\": \"Quy mô nhóm: 20–500 người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Time: 2 hours.\", \"vi\": \"Thời gian: 2 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Team Painting—Each team member creates a painting outdoors based on a predetermined theme.\", \"vi\": \"Hoạt động vẽ tranh theo nhóm — Mỗi thành viên trong nhóm sẽ sáng tác một bức tranh ngoài trời dựa trên một chủ đề đã được xác định trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The paintings are linked together at the end.\", \"vi\": \"Các bức tranh được nối liền với nhau ở phần cuối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Group size: 6–30 people.\", \"vi\": \"Quy mô nhóm: 6–30 người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Time: 1–2 hours.\", \"vi\": \"Thời gian: 1–2 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Robot Building—Your group will be broken into teams.\", \"vi\": \"Lắp ráp robot — Nhóm của quý vị sẽ được chia thành các đội.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Each team builds a robot to be used in challenges against the others.\", \"vi\": \"Mỗi đội sẽ chế tạo một con robot để tham gia các thử thách đối đầu với các đội khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Group size: 10–30 people.\", \"vi\": \"Quy mô nhóm: 10–30 người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Time: 2–3 hours.\", \"vi\": \"Thời gian: 2–3 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"All Chocolate—Your group will have the chance to use engineering skills to build a tower of chocolate.\", \"vi\": \"Toàn bộ bằng sô-cô-la — Nhóm của quý vị sẽ có cơ hội vận dụng các kỹ năng kỹ thuật để xây dựng một tòa tháp bằng sô-cô-la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Then you learn how to make chocolate from a local chocolatier.\", \"vi\": \"Sau đó, quý vị sẽ được học cách làm sô-cô-la từ một nghệ nhân sô-cô-la địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Group size: 8–150 people.\", \"vi\": \"Quy mô nhóm: 8–150 người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Time: 2 hours.\", \"vi\": \"Thời gian: 2 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Book an event in October and receive 15 percent off.\", \"vi\": \"Đặt lịch tổ chức sự kiện vào tháng 10 để được giảm giá 15 phần trăm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"https://www.osawacorporateteambuilding.com/home\", \"vi\": \"https://www.osawacorporateteambuilding.com/home\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Requests\", \"vi\": \"Yêu cầu\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Reviews\", \"vi\": \"Các bài đánh giá\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Name - Alexandra Peterson\", \"vi\": \"Họ và tên - Alexandra Peterson\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Company name - Whitten Tech\", \"vi\": \"Tên công ty - Whitten Tech\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"E-mail address - apeterson@whittentech.com\", \"vi\": \"Địa chỉ email - apeterson@whittentech.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Phone - 617-555-0123\", \"vi\": \"Điện thoại - 617-555-0123\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Location and date of event Downtown Boston, October 15\", \"vi\": \"Địa điểm và ngày diễn ra sự kiện: Trung tâm thành phố Boston, ngày 15 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"What events are you interested in?\", \"vi\": \"Quý vị quan tâm đến những sự kiện nào?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Choose your top three.\", \"vi\": \"Hãy chọn ba lựa chọn hàng đầu của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"1 Game Day 2 Scavenger Hunt 3 Team Painting\", \"vi\": \"1 Ngày thi đấu 2 Trò chơi tìm kiếm đồ vật 3 Hoạt động vẽ tranh theo nhóm\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Number of participants 28 people\", \"vi\": \"Số lượng người tham gia: 28 người\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Additional information\", \"vi\": \"Thông tin bổ sung\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"We are interested in a fun activity for our sales team before the busy selling season begins.\", \"vi\": \"Chúng tôi đang tìm kiếm một hoạt động thú vị dành cho đội ngũ bán hàng của mình trước khi mùa bán hàng cao điểm bắt đầu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"We spend a lot of time in the office, so we want an outdoor event.\", \"vi\": \"Chúng tôi dành rất nhiều thời gian tại văn phòng, vì vậy chúng tôi muốn tổ chức một sự kiện ngoài trời.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"We will contact you within three business days with a quote and confirmation.\", \"vi\": \"Chúng tôi sẽ liên hệ với quý vị trong vòng ba ngày làm việc để gửi báo giá và xác nhận.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"https://www.osawacorporateteambuilding.com/requests\", \"vi\": \"https://www.osawacorporateteambuilding.com/requests\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"Requests\", \"vi\": \"Yêu cầu\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 46, \"question_numbers\": []}, {\"en\": \"Reviews\", \"vi\": \"Các đánh giá\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 47, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 48, \"question_numbers\": []}, {\"en\": \"What Our Customers Are Saying\", \"vi\": \"Ý kiến của quý khách hàng\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 49, \"question_numbers\": []}, {\"en\": \"Posted by Whitten Tech on October 20\", \"vi\": \"Được đăng bởi Whitten Tech vào ngày 20 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 50, \"question_numbers\": []}, {\"en\": \"Our team hired Osawa Corporate Team Building to lead an activity for the sales staff at Whitten Tech.\", \"vi\": \"Đội ngũ của chúng tôi đã thuê công ty Osawa Corporate Team Building để tổ chức một hoạt động dành cho đội ngũ nhân viên kinh doanh tại Whitten Tech.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 51, \"question_numbers\": []}, {\"en\": \"The facilitator of the Scavenger Hunt, Lorenzo Benford, was excellent.\", \"vi\": \"Người điều phối trò chơi “Scavenger Hunt”, ông Lorenzo Benford, đã thể hiện rất xuất sắc.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 52, \"question_numbers\": []}, {\"en\": \"The 28 members of our sales team all had positive feedback.\", \"vi\": \"Tất cả 28 thành viên trong đội ngũ bán hàng của chúng tôi đều nhận được những phản hồi tích cực.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 53, \"question_numbers\": []}, {\"en\": \"They reported that they loved exploring the city, learning about its history, and finding new local attractions, even on a cold and cloudy day.\", \"vi\": \"Họ chia sẻ rằng họ rất thích khám phá thành phố, tìm hiểu về lịch sử của nơi đây và khám phá những điểm tham quan mới tại địa phương, ngay cả trong một ngày trời lạnh và nhiều mây.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 54, \"question_numbers\": []}, {\"en\": \"I highly recommend this activity.\", \"vi\": \"Tôi xin nhiệt liệt khuyến nghị hoạt động này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 55, \"question_numbers\": []}, {\"en\": \"The only downside was that we did not realize how far we would be walking.\", \"vi\": \"Điểm trừ duy nhất là chúng tôi đã không lường trước được quãng đường đi bộ sẽ dài đến mức nào.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 56, \"question_numbers\": []}, {\"en\": \"It would have been helpful to have an idea of the walking distances so we could have been fully prepared.\", \"vi\": \"Nếu biết trước khoảng cách đi bộ thì sẽ rất hữu ích, nhờ đó chúng tôi có thể chuẩn bị thật chu đáo.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 57, \"question_numbers\": []}, {\"en\": \"https://www.osawacorporateteambuilding.com/reviews\", \"vi\": \"https://www.osawacorporateteambuilding.com/reviews\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 58, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 59, \"question_numbers\": []}, {\"en\": \"Requests\", \"vi\": \"Yêu cầu\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 60, \"question_numbers\": []}, {\"en\": \"Reviews\", \"vi\": \"Các đánh giá\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 61, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 62, \"question_numbers\": []}]' WHERE `id` = '63224699-8fb6-4a94-9803-1674e5d6bb33';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Order cost with tax - Overnight shipping (1 day) - Express shipping (3 days) - Standard (6–8 days)\", \"vi\": \"Tổng chi phí đơn hàng (đã bao gồm thuế) - Giao hàng trong ngày (1 ngày) - Giao hàng nhanh (3 ngày) - Giao hàng tiêu chuẩn (6–8 ngày)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Under $25 - $8 - $5 - $3\", \"vi\": \"Dưới 25 đô la - 8 đô la - 5 đô la - 3 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"$25 to $100 - $13 - $7 - $5\", \"vi\": \"25 đến 100 đô la - 13 đô la - 7 đô la - 5 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Over $100 - $18 - $15 - FREE\", \"vi\": \"Trên 100 đô la - 18 đô la - 15 đô la - MIỄN PHÍ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Mountain and Forest Company\", \"vi\": \"Công ty Núi và Rừng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"http://www.mountainandforest.ca/custserv/shippinginfo\", \"vi\": \"http://www.mountainandforest.ca/custserv/shippinginfo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The Leader in Quality Camping and Hiking Gear\", \"vi\": \"Nhà cung cấp hàng đầu về thiết bị cắm trại và đi bộ đường dài chất lượng cao\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please note that most regular electronic or phone orders can be processed and made ready for shipping almost immediately.\", \"vi\": \"Xin lưu ý rằng hầu hết các đơn hàng thông thường đặt qua kênh điện tử hoặc điện thoại đều có thể được xử lý và chuẩn bị sẵn sàng để giao hàng gần như ngay lập tức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Custom and personalized orders may take up to five days for processing before they are shipped.\", \"vi\": \"Các đơn hàng đặt làm riêng và cá nhân hóa có thể mất tối đa năm ngày để xử lý trước khi được giao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please direct any questions or concerns to our customer service department at service@mountainandforest.ca.\", \"vi\": \"Mọi thắc mắc hoặc ý kiến đóng góp, xin vui lòng liên hệ với bộ phận dịch vụ khách hàng của chúng tôi qua địa chỉ email service@mountainandforest.ca.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We will respond within 24 hours.\", \"vi\": \"Chúng tôi sẽ phản hồi trong vòng 24 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Our shipping rates:\", \"vi\": \"Mức phí vận chuyển của chúng tôi:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Clothing\", \"vi\": \"Quần áo\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Gear\", \"vi\": \"Dao cắt\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Customer Service\", \"vi\": \"Dịch vụ khách hàng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"About Us\", \"vi\": \"Giới thiệu về chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"To: service@mountainandforest.ca\", \"vi\": \"Gửi tới: service@mountainandforest.ca\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"From: jinheeshin@sharemail.ca\", \"vi\": \"Nguồn: jinheeshin@sharemail.ca\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Date: 10 January\", \"vi\": \"Ngày: 10 tháng 1\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Subject: Order B75022\", \"vi\": \"Chủ đề: Đơn đặt hàng số B75022\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I recently placed an order for $135 for hiking boots and a thermal jacket intended for a camping trip this weekend.\", \"vi\": \"Gần đây, tôi đã đặt một đơn hàng trị giá 135 đô la để mua một đôi giày leo núi và một chiếc áo khoác giữ nhiệt nhằm chuẩn bị cho chuyến cắm trại vào cuối tuần này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"According to the confirmation I received at the time of my purchase, my order should have arrived yesterday.\", \"vi\": \"Theo thông báo xác nhận mà tôi nhận được tại thời điểm đặt hàng, đơn hàng của tôi lẽ ra đã phải được giao vào ngày hôm qua.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Since I paid an additional fee for three-day shipping, I was expecting that my order would arrive in a timely fashion.\", \"vi\": \"Vì tôi đã trả thêm phí để được giao hàng trong vòng ba ngày, nên tôi đã mong rằng đơn hàng của mình sẽ được giao đúng hẹn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"As it has not, I am requesting a refund of the shipping cost.\", \"vi\": \"Vì điều đó chưa xảy ra, tôi xin yêu cầu hoàn lại chi phí vận chuyển.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Additionally, if my order has not been delivered by tomorrow, please cancel my order as I will have to purchase similar items at a local shop.\", \"vi\": \"Ngoài ra, nếu đơn hàng của tôi chưa được giao trước ngày mai, xin vui lòng hủy đơn hàng này vì tôi sẽ phải mua những mặt hàng tương tự tại một cửa hàng địa phương.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Jin-Hee Shin\", \"vi\": \"Shin Jin-Hee\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '6338a271-537a-469f-966e-1aaadd22df45';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Washington State Gets Fit\", \"vi\": \"Tiểu bang Washington hướng tới lối sống lành mạnh\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"April 7—Throughout its 25 years in business, Fitness National, Inc., which owns and operates gyms throughout the northeastern United States, has never extended its presence to the west coast.\", \"vi\": \"Ngày 7 tháng 4 — Trong suốt 25 năm hoạt động, Công ty Fitness National, Inc. — đơn vị sở hữu và điều hành các phòng tập thể dục trên khắp khu vực Đông Bắc Hoa Kỳ — chưa bao giờ mở rộng phạm vi hoạt động sang bờ Tây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"That will change next month when it opens two new gyms: one in Tacoma and one in Spokane.\", \"vi\": \"Tình hình này sẽ thay đổi vào tháng tới khi công ty khai trương hai phòng tập thể dục mới: một ở Tacoma và một ở Spokane.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"\\\"We\'re excited to move into this territory,\\\" says Fitness National\'s CEO, Lisa Tran.\", \"vi\": \"\\\"Chúng tôi rất hào hứng khi mở rộng hoạt động sang thị trường này,\\\" bà Lisa Trần, Giám đốc Điều hành của Fitness National, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"If we are successful in these two cities, then we will continue to grow our business throughout Washington and into Oregon.\\\"\", \"vi\": \"\\\"Nếu chúng tôi gặt hái được thành công tại hai thành phố này, thì chúng tôi sẽ tiếp tục mở rộng hoạt động kinh doanh trên toàn bang Washington và sang cả bang Oregon.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Both gyms will feature studios for group fitness classes, state-of-the-art fitness machines, and indoor pools.\", \"vi\": \"Cả hai phòng tập thể dục này đều sẽ được trang bị các phòng tập dành cho các lớp thể dục nhóm, các thiết bị tập thể dục hiện đại nhất và bể bơi trong nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Both locations will be holding on-site job fairs for prospective employees on Saturday, April 14.\", \"vi\": \"Cả hai địa điểm này đều sẽ tổ chức các hội chợ việc làm trực tiếp dành cho các ứng viên vào thứ Bảy, ngày 14 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Grand opening events are planned for both gyms on May 12.\", \"vi\": \"Các sự kiện khai trương chính thức dự kiến sẽ được tổ chức tại cả hai phòng tập thể dục vào ngày 12 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Fitness National, Inc.\\nApplication for Employment\", \"vi\": \"Fitness National, Inc.\\nĐơn xin việc\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Name: Bernadette Okoye      Date: April 14\", \"vi\": \"Họ tên: Bernadette Okoye      Ngày: 14 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"E-mail Address: b.okoye@chjmail.com Telephone Number: (253) 555-0173\", \"vi\": \"Địa chỉ email: b.okoye@chjmail.com Số điện thoại: (253) 555-0173\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"For what position are you applying?\", \"vi\": \"Quý vị đang ứng tuyển vào vị trí nào?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Group Fitness Instructor\", \"vi\": \"Huấn luyện viên thể dục nhóm\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"At which location would you like to work?\", \"vi\": \"Quý vị mong muốn làm việc tại địa điểm nào?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"☒ Tacoma ☐ Spokane\", \"vi\": \"☒ Tacoma ☐ Spokane\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Describe your reason for applying:\", \"vi\": \"Xin vui lòng nêu lý do quý vị nộp đơn ứng tuyển:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"A friend of mine who works at an older Fitness National location told me she really enjoys working there.\", \"vi\": \"Một người bạn của tôi, hiện đang làm việc tại một chi nhánh lâu đời của Fitness National, đã chia sẻ với tôi rằng cô ấy thực sự rất thích làm việc ở đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I am currently employed part-time at a dance studio and would like to add a few more instructor hours into my schedule.\", \"vi\": \"Hiện tại, tôi đang làm việc bán thời gian tại một phòng tập khiêu vũ và mong muốn bổ sung thêm một vài giờ giảng dạy vào lịch làm việc của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Describe your relevant experience:\", \"vi\": \"Hãy mô tả kinh nghiệm liên quan của quý vị:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I have taught beginner, intermediate, and advanced ballet classes at Veloa Dance School for the past three years.\", \"vi\": \"Trong ba năm qua, tôi đã giảng dạy các lớp múa ba lê dành cho người mới bắt đầu, trình độ trung cấp và nâng cao tại Trường Múa Veloa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Prior to this I taught group dance workouts at Cadia Gym for two years.\", \"vi\": \"Trước đó, tôi đã giảng dạy các lớp tập thể dục nhịp điệu theo nhóm tại phòng tập Cadia Gym trong hai năm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I also worked at Cadia\'s front desk, so I have customer service experience.\", \"vi\": \"Tôi cũng từng làm việc tại quầy lễ tân của Cadia, nên tôi có kinh nghiệm trong lĩnh vực dịch vụ khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Please attach a résumé and reference list and submit to management at a Fitness National location.\", \"vi\": \"Kính mong quý vị đính kèm sơ yếu lý lịch và danh sách người giới thiệu, sau đó nộp cho ban quản lý tại một cơ sở của Fitness National.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Fitness National Group Fitness Classes\", \"vi\": \"Các lớp tập thể dục nhóm toàn quốc\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Exercise is more fun in a group!\", \"vi\": \"Tập thể dục cùng nhóm sẽ vui hơn nhiều!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Our classes are open to members at all levels of fitness and experience.\", \"vi\": \"Các lớp học của chúng tôi dành cho các thành viên ở mọi trình độ thể lực và kinh nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"You will find these and other classes taught at all of our locations across the United States.\", \"vi\": \"Quý vị sẽ tìm thấy các khóa học này cùng nhiều khóa học khác được giảng dạy tại tất cả các cơ sở của chúng tôi trên khắp Hoa Kỳ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"For a complete listing of classes, see your local Fitness National gym\'s Web page.\", \"vi\": \"Để xem danh sách đầy đủ các lớp học, xin vui lòng truy cập trang web của phòng tập Fitness National tại địa phương quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Basic Weights—Build strength through this guided weightlifting workout.\", \"vi\": \"Tập tạ cơ bản — Tăng cường sức mạnh thông qua bài tập nâng tạ có hướng dẫn này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Groove and Move—Get a cardio workout while dancing to your favorite music.\", \"vi\": \"Groove and Move — Tập luyện tim mạch trong khi nhảy theo những bản nhạc yêu thích của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Quick Cycle—Follow your instructor on a challenging ride on a stationary bicycle.\", \"vi\": \"Chương trình “Quick Cycle” — Hãy cùng huấn luyện viên tham gia một buổi đạp xe đầy thử thách trên xe đạp tập.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Splash for Strength—Tone your muscles safely with a low-impact workout in the pool.\", \"vi\": \"Splash for Strength — Tạo dáng cơ bắp một cách an toàn nhờ bài tập có tác động nhẹ trong bể bơi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}]' WHERE `id` = '635bdd8d-3f37-481f-baf3-043273166172';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"*E-mail*\", \"vi\": \"*Địa chỉ email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: lkhoury@britelyauto.co.uk\", \"vi\": \"Gửi tới: lkhoury@britelyauto.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: khagel@qualiview.co.uk\", \"vi\": \"Nguồn: khagel@qualiview.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 14 April\", \"vi\": \"Ngày: 14 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Your proposed changes\", \"vi\": \"Chủ đề: Các đề xuất thay đổi của quý vị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Khoury,\", \"vi\": \"Kính gửi Bà Khoury,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for forwarding your proposed revisions to the contract for Qualiview Ltd. to be your wholesale supplier of automotive window glass.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã chuyển tiếp các đề xuất sửa đổi đối với hợp đồng liên quan đến việc Qualiview Ltd. trở thành nhà cung cấp sỉ kính cửa sổ ô tô cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"First, we will gladly agree to an extension of the contract term from one to three years.\", \"vi\": \"Trước hết, chúng tôi sẵn lòng đồng ý gia hạn thời hạn hợp đồng từ một năm lên ba năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Secondly, I am not sure what more we can do to address your concerns about packaging materials.\", \"vi\": \"Thứ hai, tôi không chắc chúng tôi còn có thể làm gì thêm để giải quyết những lo ngại của quý vị về vật liệu đóng gói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We use custom-built crates and innovative packaging to reduce the risk of breakage during shipping.\", \"vi\": \"Chúng tôi sử dụng các thùng gỗ được thiết kế riêng và phương pháp đóng gói sáng tạo nhằm giảm thiểu nguy cơ hàng hóa bị vỡ trong quá trình vận chuyển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"While we will replace any goods that may be damaged in transit, we do not agree to pay an additional penalty fee in the event of such damage.\", \"vi\": \"Mặc dù chúng tôi sẽ thay thế bất kỳ hàng hóa nào có thể bị hư hỏng trong quá trình vận chuyển, nhưng chúng tôi không đồng ý chi trả khoản phí phạt bổ sung trong trường hợp xảy ra hư hỏng như vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I would like to discuss this further with you next week; however, I will be out of the office through Tuesday afternoon.\", \"vi\": \"Tôi mong được thảo luận thêm về vấn đề này với quý vị vào tuần tới; tuy nhiên, tôi sẽ vắng mặt tại văn phòng cho đến chiều thứ Ba.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Would you be available to meet before 11:00 A.M. on either Wednesday or Thursday?\", \"vi\": \"Quý vị có thể sắp xếp thời gian để gặp mặt trước 11 giờ sáng vào thứ Tư hoặc thứ Năm được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Friday is also possible.\", \"vi\": \"Thứ Sáu cũng là một lựa chọn khả thi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Please let me know a convenient date and time for you.\", \"vi\": \"Xin vui lòng cho tôi biết ngày và giờ nào thuận tiện với quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Karl Hagel\", \"vi\": \"Karl Hagel\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Qualiview Ltd.\", \"vi\": \"Công ty TNHH Qualiview\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '638b3fcb-93e4-42ac-9977-55e5ca10a967';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"1. Trucks deliver materials to MI plant. Nonrecyclable items are removed; recyclables are put on a conveyor belt. Discarded items are transferred to trucks for landfill disposal.\", \"vi\": \"1. Các xe tải vận chuyển nguyên liệu đến nhà máy MI. Các vật phẩm không thể tái chế sẽ được loại bỏ; các vật phẩm có thể tái chế được đưa lên băng tải. Các vật phẩm thải bỏ sau đó được chuyển lên xe tải để chôn lấp tại bãi rác.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"2. Rotating discs lift out cardboard. Smaller items pass through the screen. Boxes are cleaned and flattened.\", \"vi\": \"2. Các đĩa quay sẽ nâng các mảnh bìa cứng ra ngoài. Các vật phẩm nhỏ hơn sẽ lọt qua lưới lọc. Các thùng carton được làm sạch và ép phẳng.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"3. Paper passes under a low barrier to a holding area, while other objects continue on. Paper items are shredded.\", \"vi\": \"3. Giấy được đưa qua một thanh chắn thấp vào khu vực chứa, trong khi các vật thể khác tiếp tục di chuyển. Các mảnh giấy sẽ được băm nhỏ.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"4. A magnet removes metal objects from the conveyor belt. Metal objects are automatically sorted by type and crushed.\", \"vi\": \"4. Một nam châm sẽ loại bỏ các vật thể kim loại khỏi băng tải. Các vật thể kim loại này sẽ được phân loại tự động theo loại và sau đó được nghiền nát.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"5. Glass items are manually removed from the belt. Glass objects are shattered.\", \"vi\": \"5. Các vật phẩm bằng thủy tinh được lấy ra khỏi băng chuyền bằng tay. Các vật phẩm bằng thủy tinh bị vỡ vụn.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"6. An optical scanner separates plastics by type using a printed-on code. All processed items are sent to manufacturers as raw materials.\", \"vi\": \"6. Một máy quét quang học phân loại nhựa theo từng loại dựa trên mã in trên sản phẩm. Tất cả các mặt hàng đã qua xử lý đều được chuyển đến các nhà sản xuất dưới dạng nguyên liệu thô.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Mergystic Industries (MI) Plant Operations Workflow\", \"vi\": \"Quy trình vận hành nhà máy của Mergystic Industries (MI)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '63bd273c-2731-4278-9cfd-1ff6e8177249';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"New and Notable in Tarryville\", \"vi\": \"Những điều mới mẻ và đáng chú ý tại Tarryville\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Many in our small city thought we would never have a restaurant-delivery service.\", \"vi\": \"Nhiều người trong thành phố nhỏ của chúng tôi từng nghĩ rằng chúng tôi sẽ không bao giờ có dịch vụ giao đồ ăn từ nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"But thanks to two enterprising young people, we now have TVL Delivers!\", \"vi\": \"Tuy nhiên, nhờ có hai bạn trẻ đầy tinh thần khởi nghiệp, giờ đây chúng ta đã có dịch vụ TVL Delivers!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Alicia Kazarian and Theresa Cho were in their final year at the local university when they came up with their plan last May.\", \"vi\": \"Alicia Kazarian và Theresa Cho đang học năm cuối tại một trường đại học trong khu vực khi hai cô nảy ra ý tưởng này vào tháng 5 năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"\\\"We were studying for exams one night and wanted to avoid going out for dinner.\", \"vi\": \"\\\"Một buổi tối nọ, chúng tôi đang ôn thi và muốn tránh phải ra ngoài ăn tối.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We were frustrated by the limited options available in Tarryville for food delivery.\", \"vi\": \"Chúng tôi cảm thấy thất vọng vì các lựa chọn dịch vụ giao đồ ăn tại Tarryville còn khá hạn chế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We wanted an easy way to find, order, and pay for our meals.\", \"vi\": \"Chúng tôi mong muốn có một cách đơn giản để tìm kiếm, đặt hàng và thanh toán các bữa ăn của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"But no such service existed here,\\\" said Ms. Cho.\", \"vi\": \"“Tuy nhiên, tại đây không có dịch vụ nào như vậy cả,” bà Cho cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"In an effort to fill the food-delivery gap in Tarryville, TVL Delivers connects diners and restaurants on an online platform that serves each of their needs.\", \"vi\": \"Nhằm giải quyết tình trạng thiếu hụt dịch vụ giao đồ ăn tại Tarryville, TVL Delivers kết nối thực khách và các nhà hàng thông qua một nền tảng trực tuyến đáp ứng đầy đủ nhu cầu của cả hai bên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Restaurants can reach a broader clientele, and customers can choose from an impressively diverse list of vendors, select and order their food, and pay through one of a number of online payment methods, all from the convenience of their home or office.\", \"vi\": \"Các nhà hàng có thể tiếp cận được đối tượng khách hàng rộng lớn hơn, còn khách hàng có thể lựa chọn từ danh sách các nhà cung cấp vô cùng đa dạng, chọn và đặt món ăn, đồng thời thanh toán thông qua một trong nhiều phương thức thanh toán trực tuyến, tất cả đều được thực hiện một cách thuận tiện ngay tại nhà hoặc văn phòng của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The restaurants partnering with TVL Delivers are spread across most of Tarryville\'s neighborhoods and offer food options to suit any budget.\", \"vi\": \"Các nhà hàng hợp tác với TVL Delivers nằm rải rác trên hầu hết các khu dân cư của Tarryville và cung cấp các lựa chọn ẩm thực phù hợp với mọi mức chi tiêu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"\\\"We think we\'re off to a good start, but we already have improvements in mind,\\\" said Ms. Kazarian.\", \"vi\": \"\\\"Chúng tôi cho rằng chúng tôi đã có một khởi đầu tốt, nhưng chúng tôi đã có những ý tưởng cải tiến trong đầu,\\\" bà Kazarian cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"\\\"Some food-delivery services promise that orders will be delivered in as little as 30 minutes.\", \"vi\": \"\\\"Một số dịch vụ giao đồ ăn cam kết sẽ giao hàng chỉ trong vòng 30 phút.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We hope eventually to deliver within a specified time, but we need to ensure that all aspects of our service are working properly before officially making that promise.\\\"\", \"vi\": \"Chúng tôi hy vọng cuối cùng sẽ giao hàng đúng thời hạn đã quy định, nhưng trước khi chính thức đưa ra cam kết đó, chúng tôi cần đảm bảo rằng mọi khía cạnh của dịch vụ đều đang hoạt động bình thường.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The head of the Tarryville Business Council, Barry Porter, expressed enthusiasm for the new business.\", \"vi\": \"Ông Barry Porter, Chủ tịch Hội đồng Doanh nghiệp Tarryville, đã bày tỏ sự nhiệt tình đối với doanh nghiệp mới này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"\\\"Of course, I am always excited for a new business to open here in Tarryville.\", \"vi\": \"\\\"Tất nhiên, tôi luôn hào hứng khi có một doanh nghiệp mới khai trương tại Tarryville.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"But this is a business that local residents have long wished for.\", \"vi\": \"Tuy nhiên, đây là một dự án kinh doanh mà người dân địa phương đã mong đợi từ lâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"And, with the recent opening of Crisley Office Park on the south side of the city, I am sure TVL Delivers will be a success.\\\"\", \"vi\": \"Và, với việc Khu văn phòng Crisley Office Park vừa được khánh thành tại phía nam thành phố, tôi tin chắc rằng TVL Delivers sẽ gặt hái thành công.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '63d01d38-90f5-4872-9f30-85e4fe2e7528';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dennis Beck (2:52 P.M.)\", \"vi\": \"Dennis Beck (2 giờ 52 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Corinne.\", \"vi\": \"Xin chào, Corinne.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I just want to be sure that you saw the document I sent you.\", \"vi\": \"Tôi chỉ muốn chắc chắn rằng quý vị đã xem tài liệu mà tôi đã gửi cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"It\'s the combined market analysis and advertising proposal for the Keyes Elegant Home group.\", \"vi\": \"Đây là báo cáo kết hợp giữa phân tích thị trường và đề xuất quảng cáo dành cho Tập đoàn Keyes Elegant Home.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We\'re preparing it for tomorrow\'s presentation to the client.\", \"vi\": \"Chúng tôi đang chuẩn bị tài liệu này để trình bày cho khách hàng vào ngày mai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Corinne McCall (2:53 P.M.)\", \"vi\": \"Corinne McCall (14 giờ 53 phút)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Yes.\", \"vi\": \"Vâng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I have just downloaded it.\", \"vi\": \"Tôi vừa mới tải xuống rồi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Is this about their new line of tableware?\", \"vi\": \"Đây có phải là về dòng sản phẩm bộ đồ ăn mới của họ không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Dennis Beck (2:54 P.M.)\", \"vi\": \"Dennis Beck (14 giờ 54 phút)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Yes.\", \"vi\": \"Vâng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I\'d like you to read it over.\", \"vi\": \"Tôi mong quý vị vui lòng đọc lại một lần.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Corinne McCall (3:01 P.M.)\", \"vi\": \"Corinne McCall (3 giờ 01 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"No problem.\", \"vi\": \"Không sao đâu.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Would you like me to revise anything, or do you want me to just check that it is all clear?\", \"vi\": \"Quý vị có muốn tôi chỉnh sửa lại phần nào không, hay chỉ cần tôi kiểm tra xem nội dung đã rõ ràng chưa?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dennis Beck (3:02 P.M.)\", \"vi\": \"Dennis Beck (3 giờ 02 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Feel free to add information to the section \\\"Advertising Strategies,\\\" since that is your area of expertise.\", \"vi\": \"Xin vui lòng bổ sung thông tin vào mục “Chiến lược quảng cáo”, vì đây là lĩnh vực chuyên môn của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Corinne McCall (3:03 P.M.)\", \"vi\": \"Corinne McCall (3 giờ 03 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Will do.\", \"vi\": \"Vâng, tôi sẽ làm như vậy.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I\'ll get it back to you before the end of the day.\", \"vi\": \"Tôi sẽ gửi lại cho quý vị trước khi kết thúc ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '63e2262f-9d61-46e0-ae43-85df57661fe5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MARKETING BASICS\", \"vi\": \"NHỮNG KIẾN THỨC CƠ BẢN VỀ TIẾP THỊ\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.moorecountylibrary.gov/seminars\", \"vi\": \"http://www.moorecountylibrary.gov/seminars\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"April 15, 6 P.M.\", \"vi\": \"Ngày 15 tháng 4, 6 giờ chiều\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Moore County Library System, Newburg Branch\", \"vi\": \"Hệ thống Thư viện Hạt Moore, Chi nhánh Newburg\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Presenter: Sal Quatrochi\", \"vi\": \"Người trình bày: Sal Quatrochi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Do you want to learn how to effectively market your business?\", \"vi\": \"Quý vị có muốn tìm hiểu cách tiếp thị doanh nghiệp của mình một cách hiệu quả không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Come join us for this informative class, where you will learn how to:\", \"vi\": \"Hãy tham gia cùng chúng tôi trong buổi học đầy bổ ích này, nơi quý vị sẽ được học cách:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Determine your target customers and what motivates them to buy\", \"vi\": \"Xác định đối tượng khách hàng mục tiêu của quý vị và những yếu tố thúc đẩy họ mua hàng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Choose the best ways to reach your customers\", \"vi\": \"Hãy lựa chọn những cách thức hiệu quả nhất để tiếp cận khách hàng của quý vị\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Identify your competitors and stand out from them\", \"vi\": \"Xác định các đối thủ cạnh tranh của quý vị và tạo sự khác biệt so với họ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Get the most out of your limited marketing budget\", \"vi\": \"Hãy tận dụng tối đa ngân sách tiếp thị hạn hẹp của quý vị\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The class is free, but registration is required and begins on March 1.\", \"vi\": \"Khóa học này miễn phí, nhưng quý vị cần phải đăng ký trước và thời gian đăng ký bắt đầu từ ngày 1 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Marketing Basics is part of Moore County Library\'s new ongoing series, Marketing for Small Businesses.\", \"vi\": \"“Những kiến thức cơ bản về tiếp thị” là một phần của chuỗi chương trình mới đang được triển khai liên tục của Thư viện Hạt Moore, mang tên “Tiếp thị cho các doanh nghiệp nhỏ”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Join us for our next class, Digital Strategy, on May 6 at the Lancaster Branch.\", \"vi\": \"Kính mời quý vị tham gia lớp học tiếp theo của chúng tôi, với chủ đề “Chiến lược Kỹ thuật số”, vào ngày 6 tháng 5 tại Chi nhánh Lancaster.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Registration will open April 5.\", \"vi\": \"Việc đăng ký sẽ bắt đầu vào ngày 5 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"About Us\", \"vi\": \"Giới thiệu về chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Seminars\", \"vi\": \"Các hội thảo\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '63f1aa09-b676-498c-9b9b-74706a941061';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"River Advocates\", \"vi\": \"Những người bảo vệ dòng sông\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.crfoundation.org/volunteer\", \"vi\": \"http://www.crfoundation.org/volunteer\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The Central River Foundation coordinates water-monitoring operations at various sites along the Central River and its tributaries.\", \"vi\": \"Quỹ Sông Trung tâm điều phối các hoạt động giám sát chất lượng nước tại nhiều điểm dọc theo sông Trung tâm và các nhánh sông của nó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The foundation would like to train individuals in area communities to conduct periodic water-quality tests.\", \"vi\": \"Quỹ mong muốn đào tạo các cá nhân trong các cộng đồng địa phương để thực hiện việc kiểm tra chất lượng nước định kỳ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"If interested in becoming a river advocate, contact us at www.crfoundation.org.\", \"vi\": \"Nếu quý vị quan tâm đến việc trở thành một nhà vận động bảo vệ sông, xin vui lòng liên hệ với chúng tôi qua địa chỉ email www.crfoundation.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Requirements:\", \"vi\": \"Yêu cầu:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Reliable transportation is essential; we work in relatively remote areas.\", \"vi\": \"Phương tiện giao thông đáng tin cậy là điều không thể thiếu; chúng tôi làm việc tại những khu vực tương đối hẻo lánh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Attention to detail and the ability to take precise measurements\", \"vi\": \"Sự chú ý đến từng chi tiết và khả năng thực hiện các phép đo chính xác\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Availability to conduct testing at least once every four weeks to detect any changes in water quality\", \"vi\": \"Có khả năng tiến hành lấy mẫu kiểm tra ít nhất một lần trong bốn tuần để phát hiện bất kỳ sự thay đổi nào về chất lượng nước\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To: Janis Gutierrez, Mitch Gregory, Mary Connors, Ross Howard\", \"vi\": \"Kính gửi: Janis Gutierrez, Mitch Gregory, Mary Connors, Ross Howard\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"From: Clare Schroeder <cschroeder@crfoundation.org>\", \"vi\": \"Từ: Clare Schroeder <cschroeder@crfoundation.org>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Subject: Training\", \"vi\": \"Chủ đề: Đào tạo\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Date: May 5\", \"vi\": \"Ngày: 5 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Water Testing Site - Volunteer\", \"vi\": \"Điểm kiểm tra chất lượng nước - Tình nguyện viên\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sutton Bridge - Janis Gutierrez\", \"vi\": \"Cầu Sutton - Janis Gutierrez\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Bradford Bend - Mitch Gregory\", \"vi\": \"Bradford Bend - Mitch Gregory\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Alderwick Cove - Mary Connors\", \"vi\": \"Vịnh Alderwick - Mary Connors\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Tanner Park - Ross Howard\", \"vi\": \"Công viên Tanner - Ross Howard\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thank you for your interest in participating as a river advocate for the Central River Foundation.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã quan tâm đến việc tham gia với tư cách là người ủng hộ bảo vệ sông cho Quỹ Central River.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"A training session has been scheduled at Clifford Park on Saturday, May 8, from 9:00 A.M. to 12 noon.\", \"vi\": \"Một buổi tập huấn đã được lên lịch tổ chức tại Công viên Clifford vào thứ Bảy, ngày 8 tháng 5, từ 9 giờ sáng đến 12 giờ trưa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"During the training you will practice using the sample kits and be introduced to your mentors.\", \"vi\": \"Trong quá trình đào tạo, quý vị sẽ thực hành sử dụng các bộ dụng cụ mẫu và được giới thiệu với các cố vấn của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"You will leave with your first assignments and a certificate of completion.\", \"vi\": \"Khi kết thúc khóa học, quý vị sẽ nhận được các bài tập đầu tiên cùng với chứng chỉ hoàn thành khóa học.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Then your mentor will accompany you on your first one-hour assignment.\", \"vi\": \"Sau đó, người hướng dẫn của quý vị sẽ đồng hành cùng quý vị trong nhiệm vụ đầu tiên kéo dài một giờ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"This will prepare you to work independently afterwards.\", \"vi\": \"Điều này sẽ giúp quý vị sẵn sàng để làm việc độc lập sau này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Although we will be training at Clifford Park, you will usually be working at other sites.\", \"vi\": \"Mặc dù chúng ta sẽ được đào tạo tại Clifford Park, nhưng thông thường quý vị sẽ làm việc tại các địa điểm khác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Please see your individual testing sites below.\", \"vi\": \"Xin vui lòng tham khảo các địa điểm thi cụ thể của quý vị dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I look forward to seeing you all on Saturday!\", \"vi\": \"Tôi rất mong được gặp tất cả quý vị vào thứ Bảy!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Clare Schroeder\", \"vi\": \"Clare Schroeder\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"To: Susan Lim\", \"vi\": \"Kính gửi: Bà Susan Lim\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"From: Mary Connors\", \"vi\": \"Từ: Mary Connors\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Date: May 13\", \"vi\": \"Ngày: 13 tháng 5\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Subject: Site visit\", \"vi\": \"Chủ đề: Thăm thực địa\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Hi Susan,\", \"vi\": \"Xin chào Susan,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"I\'m supposed to complete my first water testing on May 20.\", \"vi\": \"Theo kế hoạch, tôi sẽ hoàn tất lần kiểm tra chất lượng nước đầu tiên vào ngày 20 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Are you available to meet me there to help me do it correctly?\", \"vi\": \"Quý vị có thể đến gặp tôi tại đó để giúp tôi thực hiện việc này một cách chính xác được không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"I\'m available any time between 3:00 P.M. and 6:00 P.M. I looked up the site online, and it looks like we will have to park about half a kilometer away from the river and then walk to the site.\", \"vi\": \"Tôi có thể sắp xếp thời gian bất cứ lúc nào trong khoảng từ 3 giờ chiều đến 6 giờ chiều. Tôi đã tra cứu thông tin về địa điểm này trên mạng, và có vẻ như chúng ta sẽ phải đỗ xe cách sông khoảng nửa kilômét rồi đi bộ đến đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Ms. Schroeder mentioned that it will add about 30 minutes to our trip.\", \"vi\": \"Bà Schroeder cho biết điều này sẽ khiến chuyến đi của chúng ta kéo dài thêm khoảng 30 phút.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Also, do you have an extra water-testing kit?\", \"vi\": \"Ngoài ra, quý vị có bộ dụng cụ kiểm tra chất lượng nước dự phòng nào không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"It looks like mine is missing a few pieces.\", \"vi\": \"Có vẻ như bộ của tôi thiếu một vài chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Can we use one of yours until I can get my supplies replaced?\", \"vi\": \"Chúng tôi có thể mượn một chiếc của quý vị cho đến khi tôi có thể thay thế các vật tư của mình được không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Mary\", \"vi\": \"Mary\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}]' WHERE `id` = '63fb12d1-ae3e-4705-8712-3454e6d983ff';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.softwareopinion.com ▶\", \"vi\": \"http://www.softwareopinion.com ▶\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"S-Tor Application\", \"vi\": \"Ứng dụng S-Tor\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"★★☆☆☆\", \"vi\": \"★★☆☆☆\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"\\\"I was disappointed with the customer service I received.\\\"\", \"vi\": \"\\\"Tôi cảm thấy thất vọng với chất lượng dịch vụ khách hàng mà tôi đã nhận được.\\\"\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"My job involves coordinating large-scale corporate events like trade shows and conventions.\", \"vi\": \"Công việc của tôi là phụ trách điều phối các sự kiện doanh nghiệp quy mô lớn như hội chợ thương mại và hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Because I am on the road a lot, I have found S-Tor to be perfect for storing vendor lists, program schedules, and other important documents that I need to access digitally wherever I happen to be.\", \"vi\": \"Vì tôi thường xuyên phải đi công tác, nên tôi nhận thấy S-Tor là giải pháp hoàn hảo để lưu trữ danh sách nhà cung cấp, lịch trình chương trình và các tài liệu quan trọng khác mà tôi cần truy cập dưới dạng kỹ thuật số bất kể tôi đang ở đâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In fact, I became so reliant on S-Tor that I never stopped to consider what I would do if I couldn\'t access it one day.\", \"vi\": \"Thực ra, tôi đã trở nên phụ thuộc vào S-Tor đến mức chưa bao giờ dừng lại để suy nghĩ xem mình sẽ làm gì nếu một ngày nào đó không thể truy cập được ứng dụng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"That day finally came, though, and I was disappointed with the customer service I received.\", \"vi\": \"Tuy nhiên, ngày đó cuối cùng cũng đã đến, và tôi đã cảm thấy thất vọng với chất lượng dịch vụ khách hàng mà tôi nhận được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"When I contacted the help desk to report that I was unable to log in, I was transferred from representative to representative, each one walking me through the same troubleshooting procedure.\", \"vi\": \"Khi tôi liên hệ với bộ phận hỗ trợ để báo cáo rằng tôi không thể đăng nhập, tôi đã bị chuyển từ nhân viên này sang nhân viên khác, và mỗi người đều hướng dẫn tôi thực hiện cùng một quy trình khắc phục sự cố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I was eventually able to get back into the application, but only after much trial and error.\", \"vi\": \"Cuối cùng, tôi cũng đã có thể truy cập lại vào ứng dụng, nhưng chỉ sau rất nhiều lần thử và sai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Nonetheless, everyone I spoke with was nice and polite.\", \"vi\": \"Dù vậy, tất cả những người mà tôi đã trò chuyện đều rất thân thiện và lịch sự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"In short, I love the S-Tor application, but I have to be certain that I can quickly get it running again if something goes wrong.\", \"vi\": \"Nói tóm lại, tôi rất thích ứng dụng S-Tor, nhưng tôi cần phải chắc chắn rằng mình có thể nhanh chóng khôi phục hoạt động của ứng dụng này nếu xảy ra sự cố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"After this experience with S-Tor\'s help desk, I have decided to look at similar products to see how they compare.\", \"vi\": \"Sau trải nghiệm này với bộ phận hỗ trợ khách hàng của S-Tor, tôi đã quyết định tìm hiểu các sản phẩm tương tự để so sánh xem chúng có gì khác biệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"—Adele Mohlmann\", \"vi\": \"—Adele Mohlmann\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Reviews\", \"vi\": \"Các đánh giá\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '6435ced8-d5a7-4c0d-9eb5-f4e0f51486eb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: mnandy@gmantcs.com\", \"vi\": \"Đến: mnandy@gmantcs.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: jblaire@blaireaccounting.ca\", \"vi\": \"Từ: jblaire@blaireaccounting.ca\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Re: AUTOMATIC REPLY\", \"vi\": \"V/v: TRẢ LỜI TỰ ĐỘNG\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 9 January, 10:34 AM\", \"vi\": \"Ngày: 9 tháng 1, 10:34 Sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hello, and thank you for contacting Blaire Accounting.\", \"vi\": \"Xin chào, và cảm ơn bạn đã liên hệ với Blaire Accounting.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I will be out of the office until 31 January.\", \"vi\": \"Tôi sẽ vắng mặt ở văn phòng cho đến ngày 31 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I will respond to your message when I ___131___ .\", \"vi\": \"Tôi sẽ phản hồi tin nhắn của bạn khi tôi ___131___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [131]}, {\"en\": \"If you need ___132___ assistance, please contact Susan Lewis, my administrative assistant, at slewis@blaireaccounting.ca.\", \"vi\": \"Nếu bạn cần sự hỗ trợ ___132___ , vui lòng liên hệ với Susan Lewis, trợ lý hành chính của tôi, tại địa chỉ slewis@blaireaccounting.ca.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [132]}, {\"en\": \"You can ___133___ call her directly at 416-555-0193.\", \"vi\": \"Bạn cũng có thể ___133___ gọi trực tiếp cho cô ấy theo số 416-555-0193.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [133]}, {\"en\": \"___134___ .\", \"vi\": \"___134___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [134]}, {\"en\": \"Jean Blaire, President\", \"vi\": \"Jean Blaire, Giám đốc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '6447698e-0002-4cfd-acbb-9295bafba88d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ae-Cha Kim (9:16 A.M.)\", \"vi\": \"Ae-Cha Kim (9:16 A.M.)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Good morning.\", \"vi\": \"Chào buổi sáng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I have an issue with an order I placed on the Winter Wear Web site.\", \"vi\": \"Tôi đang gặp vấn đề với một đơn hàng mà tôi đã đặt trên trang web Winter Wear.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Kelvin Long (9:18 A.M.)\", \"vi\": \"Kelvin Long (9 giờ 18 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Good morning.\", \"vi\": \"Chào buổi sáng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"How can I help you?\", \"vi\": \"Tôi có thể giúp gì cho quý vị?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Ae-Cha Kim (9:20 A.M.)\", \"vi\": \"Ae-Cha Kim (9:20 A.M.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Well, I ordered some gloves two weeks ago, and they still haven\'t arrived.\", \"vi\": \"Thật ra, tôi đã đặt mua một số đôi găng tay cách đây hai tuần, nhưng đến nay chúng vẫn chưa được giao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Kelvin Long (9:21 A.M.)\", \"vi\": \"Kelvin Long (9 giờ 21 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I\'m sorry to hear that.\", \"vi\": \"Tôi rất tiếc khi nghe tin đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Did you get an order number?\", \"vi\": \"Quý vị đã nhận được số đơn hàng chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Ae-Cha Kim (9:22 A.M.)\", \"vi\": \"Ae-Cha Kim (9:22 A.M.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"It\'s ADF193.\", \"vi\": \"Đó là ADF193.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Kelvin Long (9:23 A.M.)\", \"vi\": \"Kelvin Long (9 giờ 23 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Thanks.\", \"vi\": \"Cảm ơn.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Kelvin Long (9:26 A.M.)\", \"vi\": \"Kelvin Long (9 giờ 26 phút sáng)\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"This is very unusual.\", \"vi\": \"Điều này thật sự rất bất thường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The system is showing that the order was fulfilled.\", \"vi\": \"Hệ thống đang hiển thị rằng đơn hàng đã được xử lý xong.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I\'m not sure why it hasn\'t left the warehouse yet.\", \"vi\": \"Tôi không rõ tại sao hàng vẫn chưa được chuyển ra khỏi kho.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I can have another pair of gloves sent to you with rush shipping, at no extra charge.\", \"vi\": \"Tôi có thể gửi thêm một đôi găng tay khác cho quý vị bằng dịch vụ chuyển phát nhanh, mà không tính thêm phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Ae-Cha Kim (9:27 A.M.)\", \"vi\": \"Ae-Cha Kim (9:27 A.M.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"That would be great!\", \"vi\": \"Điều đó thật tuyệt vời!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Thanks!\", \"vi\": \"Cảm ơn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '6451be2a-93e9-4728-a0c5-2158fc2731fd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Daniel Mather (9:38 A.M.)\", \"vi\": \"Daniel Mather (9 giờ 38 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi Sue, are you working at home today?\", \"vi\": \"Xin chào Sue, hôm nay cô có làm việc tại nhà không ạ?\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Susan Maldini (9:39 A.M.)\", \"vi\": \"Susan Maldini (9 giờ 39 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"No, but I\'m at an off-site meeting.\", \"vi\": \"Không, nhưng tôi đang tham dự một cuộc họp ngoài trụ sở.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"What\'s up?\", \"vi\": \"Có chuyện gì vậy?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Daniel Mather (9:41 A.M.)\", \"vi\": \"Daniel Mather (9 giờ 41 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The manager asked me to make hard copies of some contract agreements for our records.\", \"vi\": \"Quản lý đã yêu cầu tôi in ra một số bản hợp đồng để lưu vào hồ sơ của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I forgot my printer card at home.\", \"vi\": \"Tôi đã để quên thẻ in ở nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Could I borrow yours?\", \"vi\": \"Tôi có thể mượn của quý vị được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Susan Maldini (9:42 A.M.)\", \"vi\": \"Susan Maldini (9 giờ 42 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Sure thing.\", \"vi\": \"Chắc chắn rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It\'s in the business card holder on my desk.\", \"vi\": \"Nó nằm trong hộp đựng danh thiếp trên bàn làm việc của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Daniel Mather (9:55 A.M.)\", \"vi\": \"Daniel Mather (9 giờ 55 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Okay, done.\", \"vi\": \"Được rồi, xong rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Thank you!\", \"vi\": \"Xin cảm ơn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I put it back on your desk.\", \"vi\": \"Tôi đã đặt nó trở lại trên bàn làm việc của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '64812b5e-f75b-4ec5-b7ee-9535f8eaa2f9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Alan Rogerson <arogerson@rogersoncorp.ca>\", \"vi\": \"Gửi tới: Alan Rogerson <arogerson@rogersoncorp.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Yoshi Takeda <ytakeda@dskt.co.jp>\", \"vi\": \"Từ: Yoshi Takeda <ytakeda@dskt.co.jp>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Greenhouse system\", \"vi\": \"Chủ đề: Hệ thống nhà kính\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 18 November\", \"vi\": \"Ngày: 18 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 DSKTgs\", \"vi\": \"Tệp đính kèm: 📎 DSKTgs\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Rogerson,\", \"vi\": \"Kính gửi ông Rogerson,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am glad we got a chance to talk at the agricultural technology trade show in Dublin last week.\", \"vi\": \"Tôi rất vui vì chúng ta đã có cơ hội trò chuyện tại triển lãm công nghệ nông nghiệp ở Dublin vào tuần trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Per your request, I have attached an electronic version of our booklet on the DSKT greenhouse system.\", \"vi\": \"Theo yêu cầu của quý vị, tôi đã đính kèm bản điện tử của cuốn cẩm nang về hệ thống nhà kính DSKT.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I am aware that your greenhouses are located some distance from one another.\", \"vi\": \"Tôi được biết các nhà kính của quý vị nằm cách nhau một khoảng cách nhất định.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Using our environmental monitoring system, you could check the temperature, humidity, and air quality of each greenhouse remotely.\", \"vi\": \"Với hệ thống giám sát môi trường của chúng tôi, quý vị có thể kiểm tra từ xa nhiệt độ, độ ẩm và chất lượng không khí của từng nhà kính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"You would no longer need to be on-site to make observations every night.\", \"vi\": \"Quý vị sẽ không còn cần phải có mặt tại hiện trường để tiến hành quan sát vào mỗi đêm nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"DSKT sends the readings to your smartphone or computer.\", \"vi\": \"DSKT sẽ gửi các số liệu đo được đến điện thoại thông minh hoặc máy tính của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"You might also be interested in our crop irrigation systems.\", \"vi\": \"Quý vị cũng có thể quan tâm đến các hệ thống tưới tiêu cho cây trồng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Let me know if you would like more information; I will be happy to answer questions about any of our products.\", \"vi\": \"Nếu quý vị cần thêm thông tin, xin vui lòng cho tôi biết; tôi rất sẵn lòng giải đáp mọi thắc mắc liên quan đến các sản phẩm của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Yoshi Takeda\", \"vi\": \"Yoshi Takeda\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '649b7ece-3d8a-4b4f-9ee7-c7334917987c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"I recently found some old photographs that belonged to my grandmother, and I wanted to get them restored as ______[143] as possible to the original shots.\", \"vi\": \"Gần đây tôi tìm thấy một số bức ảnh cũ của bà tôi, và tôi muốn phục chế chúng giống với các bức ảnh gốc nhất có thể ______[143].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [143]}, {\"en\": \"A colleague of mine suggested Clover Photos in the Greenwood neighborhood.\", \"vi\": \"Một đồng nghiệp của tôi đã gợi ý tiệm Clover Photos ở khu Greenwood.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Carlene, the shop\'s owner, was helpful in explaining my options and assisting me with choosing the level of service that was right for me.\", \"vi\": \"Carlene, chủ cửa hàng, rất nhiệt tình trong việc giải thích các lựa chọn của tôi và hỗ trợ tôi chọn mức độ dịch vụ phù hợp nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"She completed the restoration and framing in just three days ______[144] it is the busy season.\", \"vi\": \"Cô ấy đã hoàn thành việc phục chế và đóng khung chỉ trong ba ngày ______[144] đó là mùa cao điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [144]}, {\"en\": \"The pictures look fantastic.\", \"vi\": \"Những bức ảnh trông tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[145]\", \"vi\": \"______[145]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [145]}, {\"en\": \"Carlene is highly experienced.\", \"vi\": \"Carlene là người có tay nghề rất cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"She is a ______[146] photo editor.\", \"vi\": \"Cô ấy là một biên tập viên ảnh ______[146].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [146]}, {\"en\": \"I cannot recommend her highly enough.\", \"vi\": \"Tôi không biết phải ca ngợi cô ấy thế nào cho đủ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Ida Briggs, Bristol\", \"vi\": \"Ida Briggs, Bristol\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '64b428be-5e0d-401a-aa94-adbf78a1b454';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"As a Hanson-Roves employee, you are entitled to sick absences, during which you will be paid for time off work for health ______[135].\", \"vi\": \"Là một nhân viên của Hanson-Roves, bạn được hưởng quyền nghỉ ốm, trong thời gian đó bạn sẽ được trả lương cho thời gian nghỉ làm vì lý do sức khỏe ______[135].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [135]}, {\"en\": \"To avoid deductions to your pay, you ______[136] to provide a physician-signed note as documentation of your illness.\", \"vi\": \"Để tránh bị trừ lương, bạn ______[136] phải cung cấp giấy xác nhận do bác sĩ ký để làm tài liệu chứng minh bệnh tình của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [136]}, {\"en\": \"______[137] should include the date you were seen by the doctor, a statement certifying that you are unable to perform the duties of your position, and your expected date of return.\", \"vi\": \"______[137] phải bao gồm ngày bạn được bác sĩ khám, tuyên bố xác nhận rằng bạn không thể thực hiện các nhiệm vụ trong vị trí của mình, và ngày dự kiến bạn có thể đi làm lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [137]}, {\"en\": \"Your supervisor will then forward the documentation to Human Resources.\", \"vi\": \"Người quản lý trực tiếp của bạn sau đó sẽ chuyển tài liệu này đến bộ phận Nhân sự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"______[138].\", \"vi\": \"______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [138]}, {\"en\": \"Employee health records can be accessed only by those with a valid business reason for reviewing them.\", \"vi\": \"Hồ sơ sức khỏe của nhân viên chỉ có thể được truy cập bởi những người có lý do công việc hợp lệ để xem xét chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '64e4e5b8-398b-4137-8b47-962abd3abd0f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Evergreen Mountains Scenic Railway\", \"vi\": \"Đường sắt Thắng cảnh Núi Evergreen\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Evergreen Mountains Scenic Railway has reopened after a yearlong renovation project.\", \"vi\": \"Đường sắt Thắng cảnh Núi Evergreen đã mở cửa trở lại sau dự án cải tạo kéo dài một năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"First built over a century ago, the railway is one of the oldest in the nation.\", \"vi\": \"Được xây dựng lần đầu tiên hơn một thế kỷ trước, tuyến đường sắt này là một trong những tuyến lâu đời nhất trong cả nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The recent closure was necessary to make extensive upgrades to the aging tracks and train cars.\", \"vi\": \"Việc đóng cửa gần đây là cần thiết để thực hiện nâng cấp toàn diện các đường ray và toa tàu đã cũ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"___131____, renovations were made to the historic station.\", \"vi\": \"___131____, các công việc cải tạo cũng đã được thực hiện đối với nhà ga lịch sử.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [131]}, {\"en\": \"Sightseers on the railway will enjoy a trip through the Evergreen Forest as they ___132____ to the top of Walden Mountain.\", \"vi\": \"Du khách tham quan trên tuyến đường sắt sẽ tận hưởng chuyến đi xuyên qua Khu rừng Evergreen khi họ ___132____ lên đỉnh Núi Walden.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [132]}, {\"en\": \"Here the train will make an hour-long stop for visitors to tour the new visitor center or ___133____ enjoy the views from the highest mountain in the region.\", \"vi\": \"Tại đây, tàu sẽ dừng lại trong một giờ để du khách tham quan trung tâm đón tiếp khách mới hoặc ___133____ thưởng ngoạn phong cảnh từ ngọn núi cao nhất trong vùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [133]}, {\"en\": \"The return trip takes a different route back to the station.\", \"vi\": \"Chuyến đi về sẽ theo một tuyến đường khác để quay trở lại nhà ga.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"___134___.\", \"vi\": \"___134___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [134]}, {\"en\": \"Tickets for this amazing journey are available online.\", \"vi\": \"Vé cho hành trình tuyệt vời này hiện đã được bán trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '65218b77-7c8d-4118-b11b-a8f1a23dce80';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MEMO\", \"vi\": \"BẢN GHI NHỚ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All Avisomark Employees\", \"vi\": \"Kính gửi: Toàn thể nhân viên Avisomark\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Eugenia Bajorek, Assistant Communications Director\", \"vi\": \"Từ: Eugenia Bajorek, Phó Giám đốc Truyền thông\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: January 30\", \"vi\": \"Ngày: 30 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Re: Our company newsletter\", \"vi\": \"Trả lời: Bản tin nội bộ của công ty chúng tôi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As part of a company-wide effort to reduce waste, we will be discontinuing the print version of our weekly company newsletter, effective March 1.\", \"vi\": \"Trong khuôn khổ nỗ lực giảm thiểu rác thải trên toàn công ty, chúng tôi sẽ ngừng phát hành bản in của bản tin nội bộ hàng tuần, có hiệu lực từ ngày 1 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"From that date forward, the newsletter will be published in its online format only.\", \"vi\": \"Kể từ ngày đó trở đi, bản tin sẽ chỉ được phát hành dưới dạng trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In addition, beginning in March, the submission deadline for the Employee News section of the newsletter will be changed from the third Friday of each month to the second Friday of each month.\", \"vi\": \"Ngoài ra, kể từ tháng 3, thời hạn nộp bài cho chuyên mục “Tin tức Nhân viên” của bản tin sẽ được điều chỉnh từ thứ Sáu tuần thứ ba của mỗi tháng sang thứ Sáu tuần thứ hai của mỗi tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This change will give Markus Quimby the time he needs to process and edit submissions.\", \"vi\": \"Sự thay đổi này sẽ giúp Markus Quimby có đủ thời gian cần thiết để xem xét và chỉnh sửa các bài gửi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The submission process remains the same: simply e-mail Markus directly at mquimby@avisomark.com.\", \"vi\": \"Quy trình gửi bài vẫn giữ nguyên như trước: quý vị chỉ cần gửi email trực tiếp cho ông Markus theo địa chỉ mquimby@avisomark.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '652ccfeb-fdce-40e9-a990-4d747aa6c754';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Change of Work Order\", \"vi\": \"Thay đổi lệnh công việc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"General Contractor:\", \"vi\": \"Nhà thầu chính:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Howard Kleiber, Mercrest Construction\", \"vi\": \"Howard Kleiber, Công ty Xây dựng Mercrest\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"106 Pickens Way, Columbus, OH 43211\", \"vi\": \"106 Pickens Way, Columbus, OH 43211\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Property Owner: Oscar Copeland, 866 Andell Road, Columbus, OH 43215\", \"vi\": \"Chủ sở hữu bất động sản: Oscar Copeland, 866 Andell Road, Columbus, OH 43215\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Project Start Date: July 10\", \"vi\": \"Ngày khởi động dự án: 10 tháng 7\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Project End Date: July 15\", \"vi\": \"Ngày kết thúc dự án: 15 tháng 7\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The contractor is hereby instructed to make the following changes to the contract documents:\", \"vi\": \"Theo đây, nhà thầu được yêu cầu thực hiện các thay đổi sau đây đối với các tài liệu hợp đồng:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Description of Work Added/Deleted:\", \"vi\": \"Mô tả công việc đã được bổ sung/loại bỏ:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Client will now be supplying the countertops and faucet in addition to the kitchen cabinets.\", \"vi\": \"Ngoài tủ bếp, khách hàng sẽ cung cấp cả mặt bàn và vòi nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Therefore, the total project cost will be adjusted to only include the cost of installation.\", \"vi\": \"Do đó, tổng chi phí dự án sẽ được điều chỉnh để chỉ bao gồm chi phí lắp đặt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Original Contract Price: $3,496\", \"vi\": \"Giá hợp đồng ban đầu: 3.496 đô la\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Net Reduction from Previous Contract: -$2,412\", \"vi\": \"Số tiền giảm ròng so với hợp đồng trước đó: -2.412 USD\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Total Project Cost with Approved Changes: $1,084\", \"vi\": \"Tổng chi phí dự án bao gồm các thay đổi đã được phê duyệt: 1.084 đô la\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Revised Payment Schedule:\", \"vi\": \"Lịch thanh toán đã điều chỉnh:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"15% of total project cost ($162) is due upfront to secure contractor, $222 is due on project start date, and the remainder ($700) is due upon project completion.\", \"vi\": \"15% tổng chi phí dự án (162 USD) phải thanh toán trước để đảm bảo nhà thầu tham gia, 222 USD phải thanh toán vào ngày khởi công dự án, và số tiền còn lại (700 USD) phải thanh toán khi dự án hoàn thành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Accepted by:\", \"vi\": \"Được chấp thuận bởi:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Contractor: Howard Kleiber\", \"vi\": \"Nhà thầu: Howard Kleiber\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Property Owner: Oscar Copeland\", \"vi\": \"Chủ sở hữu bất động sản: Oscar Copeland\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '65946610-585d-4c00-9db2-73629f1b4d99';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Mason Wu <mwu@wustudios.co.nz>\", \"vi\": \"Đến: Mason Wu <mwu@wustudios.co.nz>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Trent Tuiloma <ttuiloma@canterburyairport.co.nz>\", \"vi\": \"Từ: Trent Tuiloma <ttuiloma@canterburyairport.co.nz>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Canterbury Airport project\", \"vi\": \"Chủ đề: Dự án Sân bay Canterbury\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: Monday, 2 July\", \"vi\": \"Ngày: Thứ Hai, ngày 2 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Wu,\", \"vi\": \"Ông Wu thân mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for agreeing to consult on the Canterbury Airport redesign project.\", \"vi\": \"Cảm ơn ông đã đồng ý tư vấn cho dự án thiết kế lại Sân bay Canterbury.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[139].\", \"vi\": \"______[139].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [139]}, {\"en\": \"As a result, I am particularly eager to hear your ideas about upgrading our main terminal.\", \"vi\": \"Do đó, tôi đặc biệt mong muốn được lắng nghe các ý tưởng của ông về việc nâng cấp nhà ga chính của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Can we meet this week?\", \"vi\": \"Chúng ta có thể gặp nhau trong tuần này chứ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"There are a number of ______[140] restaurants near my office.\", \"vi\": \"Có một số nhà hàng ______[140] ở gần văn phòng của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [140]}, {\"en\": \"If you are available this Friday, we could meet at Celia\'s Café on Cumberland Street.\", \"vi\": \"Nếu ông rảnh vào thứ Sáu này, chúng ta có thể gặp nhau tại Quán cà phê Celia trên Phố Cumberland.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I would also like a few of my colleagues to ______[141] us.\", \"vi\": \"Tôi cũng muốn một vài đồng nghiệp của mình ______[141] chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [141]}, {\"en\": \"They would appreciate ______[142] ways to enhance the airport user\'s experience.\", \"vi\": \"Họ sẽ đánh giá cao ______[142] các cách để nâng cao trải nghiệm của người sử dụng sân bay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [142]}, {\"en\": \"I look forward to hearing from you soon.\", \"vi\": \"Tôi rất mong sớm nhận được hồi âm từ ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Trent Tuiloma\", \"vi\": \"Trent Tuiloma\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Chairman, Canterbury Airport Redesign Team\", \"vi\": \"Chủ tịch, Nhóm Thiết kế lại Sân bay Canterbury\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '65b2e8ff-655e-4573-a814-dbecd1a17f00';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Customer name - Maureen Shibata\", \"vi\": \"Tên khách hàng - Maureen Shibata\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Company - Gardendale Neighborhood Association (GNA)\", \"vi\": \"Tổ chức - Hiệp hội Khu dân cư Gardendale (GNA)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Address - 4069 Strother Street, Gardendale, PA 19061\", \"vi\": \"Địa chỉ - 4069 Đường Strother, Gardendale, PA 19061\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Phone number - 484-555-0152    E-mail    mshibata@gardendalena.org\", \"vi\": \"Số điện thoại - 484-555-0152    E-mail    mshibata@gardendalena.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Event date - December 15        Balance due date    December 13\", \"vi\": \"Ngày diễn ra sự kiện - 15 tháng 12        Ngày đến hạn thanh toán số dư    13 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Description - Quantity - Price\", \"vi\": \"Mô tả - Số lượng - Giá\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Platter of assorted raw vegetables with dips - 5 - $125.00\", \"vi\": \"Đĩa rau sống tổng hợp kèm nước chấm - 5 - 125,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Grilled chicken skewers (tray) - 5 - $150.00\", \"vi\": \"Xiên gà nướng (khay) - 5 xiên - 150,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Quiche tarts (tray) - 5 - $175.00\", \"vi\": \"Bánh quiche (khay) - 5 chiếc - 175,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Small chocolate cakes (custom decorated) - 50 - $250.00\", \"vi\": \"Bánh sô-cô-la nhỏ (trang trí theo yêu cầu) - 50 chiếc - 250,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"SUBTOTAL - $700.00\", \"vi\": \"TỔNG PHẦN - 700,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Deposit (received November 25) - -$200.00\", \"vi\": \"Khoản đặt cọc (nhận được vào ngày 25 tháng 11) - -200,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"BALANCE DUE - $500.00\", \"vi\": \"SỐ TIỀN CÒN PHẢI THANH TOÁN - 500,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Comments or special instructions:\", \"vi\": \"Ghi chú hoặc hướng dẫn đặc biệt:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"See November 30 e-mail from Ms. Shibata about cake design. This will be for the GNA\'s annual reception.\", \"vi\": \"Xin vui lòng tham khảo email ngày 30 tháng 11 của bà Shibata về thiết kế bánh. Chiếc bánh này sẽ được dùng cho buổi tiệc chiêu đãi thường niên của GNA.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dawn Sky Catering\", \"vi\": \"Dịch vụ Ẩm thực Dawn Sky\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"525 Horseshoe Lane\", \"vi\": \"525 Horseshoe Lane\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Gardendale, PA 19061\", \"vi\": \"Gardendale, PA 19061\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Invoice date: December 6        Invoice number: 5688\", \"vi\": \"Ngày lập hóa đơn: 6 tháng 12        Số hóa đơn: 5688\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"GARDENDALE (December 20)—The Gardendale Neighborhood Association (GNA) honored Mayor Karla Fugate at its annual reception last Saturday.\", \"vi\": \"GARDENDALE (ngày 20 tháng 12) — Hiệp hội Khu dân cư Gardendale (GNA) đã vinh danh Thị trưởng Karla Fugate tại buổi tiệc chiêu đãi thường niên diễn ra vào thứ Bảy tuần trước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Mayor Fugate had been asked to give a short speech about the city\'s plans to build a new recreational center, after which she was presented with a special plaque to thank her for her role in the Westside Park project.\", \"vi\": \"Thị trưởng Fugate đã được mời phát biểu ngắn gọn về kế hoạch xây dựng một trung tâm giải trí mới của thành phố; sau đó, bà đã được trao tặng một tấm bảng kỷ niệm đặc biệt để tri ân những đóng góp của bà trong dự án Công viên Westside.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"According to GNA president Manuel Yuen, \\\"Mayor Fugate was instrumental in making last year\'s fund-raising festival for the park a huge success.\\\"\", \"vi\": \"Theo ông Manuel Yuen, Chủ tịch GNA, “Thị trưởng Fugate đã đóng vai trò quan trọng trong việc giúp lễ hội gây quỹ cho công viên năm ngoái đạt được thành công rực rỡ.”\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"The festival raised thousands of dollars more than the GNA expected.\", \"vi\": \"Lễ hội này đã quyên góp được số tiền cao hơn hàng nghìn đô la so với dự kiến của GNA.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"\\\"It was a delightful surprise,\\\" said Mayor Fugate.\", \"vi\": \"\\\"Đó quả là một bất ngờ thú vị,\\\" Thị trưởng Fugate phát biểu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"\\\"We set ourselves a difficult mission with the park project, but everybody in the GNA and the community at large came through admirably,\\\" the mayor continued.\", \"vi\": \"\\\"Chúng tôi đã đặt ra cho mình một nhiệm vụ đầy thách thức với dự án công viên này, nhưng tất cả mọi người trong GNA cũng như toàn thể cộng đồng đã hoàn thành xuất sắc,\\\" thị trưởng tiếp tục.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"The GNA reception was held in the Gardendale Botanical Garden, which offered a beautiful setting.\", \"vi\": \"Buổi tiệc chiêu đãi của GNA đã được tổ chức tại Vườn Bách thảo Gardendale, nơi mang đến một khung cảnh tuyệt đẹp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"The food was provided by Dawn Sky Catering, which included an individual chocolate cake for each guest decorated with the GNA logo.\", \"vi\": \"Thực phẩm do công ty Dawn Sky Catering cung cấp, trong đó có một chiếc bánh sô-cô-la riêng cho từng khách mời, được trang trí bằng biểu tượng của GNA.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '65cf4a88-516b-4f3b-b3a5-b88bb35a5c6c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Treks Auto\", \"vi\": \"Treks Auto\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Keeping your vehicle running smoothly demands getting the job done right.\", \"vi\": \"Để đảm bảo chiếc xe của quý vị luôn vận hành trơn tru, việc thực hiện công việc một cách đúng đắn là điều cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Leave yours in the hands of the professionals at Treks Auto, and always be sure you\'re getting exactly what you need and nothing that you don\'t.\", \"vi\": \"Hãy giao phó chiếc xe của quý vị cho đội ngũ chuyên gia tại Treks Auto, và quý vị có thể hoàn toàn yên tâm rằng mình sẽ nhận được chính xác những gì mình cần, mà không có bất kỳ thứ gì không cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Our repair shop has been based in Leeds ever since Tony Reker opened his first garage in 1963.\", \"vi\": \"Xưởng sửa chữa của chúng tôi đã có trụ sở tại Leeds kể từ khi ông Tony Reker khai trương xưởng sửa chữa đầu tiên vào năm 1963.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"For three generations, our family-run business has been proud to serve the West Yorkshire community with fair pricing and a commitment to honest service.\", \"vi\": \"Trong suốt ba thế hệ qua, doanh nghiệp do gia đình chúng tôi điều hành luôn tự hào được phục vụ cộng đồng West Yorkshire với mức giá hợp lý và cam kết mang đến dịch vụ trung thực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Treks Auto offers a variety of oil-change packages.\", \"vi\": \"Treks Auto cung cấp nhiều gói dịch vụ thay dầu khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Each package includes a complimentary tyre-pressure check, tyre rotation, fluid fill-up, standard oil filter, five-litre oil change, and brake inspection.\", \"vi\": \"Mỗi gói dịch vụ bao gồm kiểm tra áp suất lốp miễn phí, xoay lốp, bổ sung các chất lỏng, thay bộ lọc dầu tiêu chuẩn, thay 5 lít dầu và kiểm tra hệ thống phanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Choose from the oil options listed below.\", \"vi\": \"Vui lòng lựa chọn một trong các loại dầu được liệt kê dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Synthetic Blend - £25\", \"vi\": \"Hỗn hợp tổng hợp - 25 bảng Anh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Recommended for vehicles with fewer than 125,000 miles or under ten years old.\", \"vi\": \"Được khuyến nghị dành cho các phương tiện có quãng đường di chuyển dưới 125.000 dặm hoặc tuổi thọ dưới mười năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"High Mileage - £40\", \"vi\": \"Số dặm đã chạy cao - 40 bảng Anh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Best for vehicles with more than 125,000 miles or over ten years old.\", \"vi\": \"Phù hợp nhất với các phương tiện đã chạy hơn 125.000 dặm hoặc đã sử dụng trên mười năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Full Synthetic - £50\", \"vi\": \"Dầu tổng hợp hoàn toàn - 50 bảng Anh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Ideal for vehicles with more than 125,000 miles and with special manufacturer- recommended maintenance needs.\", \"vi\": \"Rất phù hợp cho các phương tiện đã chạy hơn 125.000 dặm và có các yêu cầu bảo dưỡng đặc biệt do nhà sản xuất khuyến nghị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '663843b7-0976-48dc-be64-a2af9b0b3c0a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Scott Rabin (11:14 A.M.)\", \"vi\": \"Scott Rabin (11 giờ 14 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Tanya.\", \"vi\": \"Xin chào, Tanya.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I\'m in the storage room, clearing out space as Anita requested.\", \"vi\": \"Tôi đang ở trong phòng chứa đồ, dọn dẹp để nhường chỗ theo yêu cầu của Anita.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"There are some boxes marked \\\"Accounting\\\" in here.\", \"vi\": \"Trong đây có một số hộp được ghi là “Kế toán”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Are they yours?\", \"vi\": \"Đó có phải là của quý vị không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Tanya Greene (11:18 A.M.)\", \"vi\": \"Tanya Greene (11 giờ 18 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Yes, they have some of my old files in them.\", \"vi\": \"Vâng, trong đó có một số tệp tin cũ của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Most of them can be shredded, but there are a few that we may need to keep.\", \"vi\": \"Hầu hết trong số đó đều có thể được hủy, nhưng cũng có một số tài liệu mà chúng ta có thể cần phải giữ lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Do you want me to come have a look?\", \"vi\": \"Quý vị có muốn tôi đến xem qua một chút không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I have about 15 minutes until my next meeting.\", \"vi\": \"Tôi còn khoảng 15 phút nữa là đến cuộc họp tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Scott Rabin (11:20 A.M.)\", \"vi\": \"Scott Rabin (11 giờ 20 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It\'s up to you.\", \"vi\": \"Điều đó tùy thuộc vào quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I can just leave them here until you have more time.\", \"vi\": \"Tôi có thể để chúng ở đây cho đến khi quý vị rảnh rỗi hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Tanya Greene (11:21 A.M.)\", \"vi\": \"Tanya Greene (11 giờ 21 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"That would be great.\", \"vi\": \"Điều đó thật tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I\'ll set aside some time on Wednesday to sort through them.\", \"vi\": \"Tôi sẽ dành ra một chút thời gian vào thứ Tư để xem xét kỹ lưỡng những thứ đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '66a22b9f-7536-4cb6-a4f0-82febd32729e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Greg Pfaff (1:17 P.M.)\", \"vi\": \"Greg Pfaff (13 giờ 17 phút)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi Jessa.\", \"vi\": \"Xin chào Jessa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I\'m running a bit late for our 2:00 P.M. appointment to troubleshoot the problem with your desktop computer.\", \"vi\": \"Tôi sẽ đến muộn một chút so với cuộc hẹn lúc 2 giờ chiều để khắc phục sự cố với máy tính để bàn của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I should arrive around 2:20 P.M.\", \"vi\": \"Tôi dự kiến sẽ đến vào khoảng 2 giờ 20 phút chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Jessa Kim (1:18 P.M.)\", \"vi\": \"Jessa Kim (1:18 P.M.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"That\'s fine.\", \"vi\": \"Không sao cả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I hope you can fix it.\", \"vi\": \"Tôi hy vọng quý vị có thể khắc phục được vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I depend on that desktop for my online craft supply business.\", \"vi\": \"Tôi phụ thuộc vào chiếc máy tính để bàn đó để điều hành công việc kinh doanh vật liệu thủ công trực tuyến của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Greg Pfaff (1:19 P.M.)\", \"vi\": \"Greg Pfaff (13 giờ 19 phút)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I know.\", \"vi\": \"Tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"It may just need a tune-up.\", \"vi\": \"Có lẽ nó chỉ cần được bảo dưỡng một chút thôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"My assistant, Kevin Mulford, will be with me too.\", \"vi\": \"Trợ lý của tôi, ông Kevin Mulford, cũng sẽ đi cùng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"He may help you out in the future while I work on a maintenance project at a local data center.\", \"vi\": \"Trong thời gian tới, khi tôi đang tham gia một dự án bảo trì tại một trung tâm dữ liệu trong khu vực, anh ấy có thể sẽ giúp đỡ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Jessa Kim (1:20 P.M.)\", \"vi\": \"Jessa Kim (1:20 P.M.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"That\'s good to know.\", \"vi\": \"Thật tốt khi biết được điều đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Greg Pfaff (1:21 P.M.)\", \"vi\": \"Greg Pfaff (1 giờ 21 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Good.\", \"vi\": \"Tốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"That\'s it, then.\", \"vi\": \"Vậy là xong rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Jessa Kim (1:22 P.M.)\", \"vi\": \"Jessa Kim (1:22 P.M.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"All right.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"See you when you get here.\", \"vi\": \"Hẹn gặp quý vị khi quý vị đến nơi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '66b60ba8-e0da-407d-844e-c227825ef4ac';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"My first impression of McVay Accountants was positive.\", \"vi\": \"Ấn tượng đầu tiên của tôi về công ty kế toán McVay là rất tích cực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"A representative responded quickly after I filled out a contact form requesting help with my small business\'s taxes.\", \"vi\": \"Một đại diện đã phản hồi nhanh chóng sau khi tôi điền vào mẫu liên hệ yêu cầu trợ giúp về thuế cho doanh nghiệp nhỏ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Nevertheless, I ______[135] an appointment with the firm again.\", \"vi\": \"Tuy nhiên, tôi sẽ ______[135] đặt lịch hẹn với công ty này một lần nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"My experience was that they do not show enough concern for ______[136].\", \"vi\": \"Trải nghiệm của tôi là họ không thể hiện đủ sự quan tâm đến ______[136].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"I found no fewer than three errors in the tax return my accountant prepared for me.\", \"vi\": \"Tôi đã tìm thấy không dưới ba lỗi trong bản quyết toán thuế mà kế toán của tôi đã chuẩn bị cho tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[137] What is more, it took several rounds of discussion and resending of documents before he figured out the sources of the issues and fixed them.\", \"vi\": \"______[137] Hơn nữa, phải mất vài vòng thảo luận và gửi lại tài liệu thì anh ấy mới tìm ra nguồn gốc của các vấn đề và khắc phục chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [137]}, {\"en\": \"In the future, I plan to ______[138] a firm based on a recommendation from a friend or associate.\", \"vi\": \"Trong tương lai, tôi dự định sẽ ______[138] một công ty dựa trên giới thiệu từ bạn bè hoặc đồng nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [138]}]' WHERE `id` = '66d5c1e3-49b2-42d1-90ab-3ee1a1424151';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Bryson Business Development Network Expands Its Learning Program\", \"vi\": \"Mạng lưới Phát triển Kinh doanh Bryson mở rộng chương trình đào tạo của mình\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"(March 14)—Last summer, after offering on-site courses for over ten years, Calgary-based Bryson Business Development Network began offering a different set of workshops for people who have recently started a business.\", \"vi\": \"(Ngày 14 tháng 3) — Vào mùa hè năm ngoái, sau hơn mười năm tổ chức các khóa học trực tiếp, Mạng lưới Phát triển Kinh doanh Bryson có trụ sở tại Calgary đã bắt đầu triển khai một loạt các hội thảo mới dành cho những người mới thành lập doanh nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Hundreds of new business owners signed up for the online sessions, which focused on topics such as Web site development, marketing, and advertising.\", \"vi\": \"Hàng trăm chủ doanh nghiệp mới đã đăng ký tham gia các buổi học trực tuyến, tập trung vào các chủ đề như phát triển trang web, tiếp thị và quảng cáo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"This summer, the company will introduce some new learning opportunities.\", \"vi\": \"Vào mùa hè này, công ty sẽ giới thiệu một số cơ hội học tập mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"We are excited to announce the launch of a wide variety of in-depth courses led by experts in the field,\\\" director Rosa Gonzales said.\", \"vi\": \"\\\"Chúng tôi rất hân hoan thông báo về việc ra mắt một loạt các khóa học chuyên sâu và đa dạng do các chuyên gia hàng đầu trong lĩnh vực này giảng dạy,\\\" Giám đốc Rosa Gonzales cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"\\\"To enable everyone to learn more about the courses, we have created a brief video highlighting the main points that will be covered in each course.\", \"vi\": \"\\\"Để giúp quý vị tìm hiểu thêm về các khóa học, chúng tôi đã thực hiện một đoạn video ngắn nêu bật những nội dung chính sẽ được đề cập trong từng khóa học.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Customers are invited to view this introductory presentation free of charge on our Web site to help them decide which of our offerings best meet their needs.\\\"\", \"vi\": \"Chúng tôi trân trọng mời quý khách hàng truy cập trang web của chúng tôi để xem bản trình bày giới thiệu này hoàn toàn miễn phí, nhằm giúp quý vị quyết định xem sản phẩm nào của chúng tôi phù hợp nhất với nhu cầu của quý vị.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Registration and more information are available at www.brysonbdn.ca.\", \"vi\": \"Quý vị có thể đăng ký và tìm hiểu thêm thông tin tại địa chỉ www.brysonbdn.ca.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '66dccb07-0cca-4d12-b92d-c0b73192cd87';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Green City Screenwriters’ Workshop\", \"vi\": \"Hội thảo dành cho các nhà biên kịch “Thành phố Xanh”\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.greencityscreenwriters.org/workshopseries\", \"vi\": \"http://www.greencityscreenwriters.org/workshopseries\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Green City Screenwriters’ Workshop (GCSW) provides aspiring and practicing screenwriters a place for interaction and exchange of ideas.\", \"vi\": \"Hội thảo Biên kịch Thành phố Xanh (GCSW) mang đến cho các nhà biên kịch trẻ và những người đang hoạt động trong lĩnh vực này một không gian để giao lưu và trao đổi ý tưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"For the last 25 years, GCSW has helped writers from all over the country develop creative projects.\", \"vi\": \"Trong suốt 25 năm qua, GCSW đã hỗ trợ các nhà văn trên khắp cả nước phát triển các dự án sáng tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Are you working on a movie script?\", \"vi\": \"Quý vị có đang viết kịch bản phim không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Or do you have an idea for the next blockbuster film?\", \"vi\": \"Hay quý vị có ý tưởng nào cho bộ phim bom tấn tiếp theo không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Consider applying for the next series of classes at GCSW.\", \"vi\": \"Quý vị hãy cân nhắc đăng ký tham gia khóa học tiếp theo tại GCSW.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We offer writing groups, staged readings, and seminars with guest speakers.\", \"vi\": \"Chúng tôi tổ chức các nhóm viết văn, các buổi đọc thử kịch và các buổi hội thảo với sự tham gia của các diễn giả khách mời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The six class sessions begin on January 10 and are held every other Thursday.\", \"vi\": \"Sáu buổi học sẽ bắt đầu vào ngày 10 tháng 1 và được tổ chức vào các thứ Năm cách tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Each class meets from 7 P.M. to 9 P.M. at Green City Foundation for the Arts.\", \"vi\": \"Mỗi buổi học diễn ra từ 7 giờ tối đến 9 giờ tối tại Quỹ Nghệ thuật Green City.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Tuition is $500 in total and due by January 1.\", \"vi\": \"Tổng học phí là 500 đô la và phải nộp trước ngày 1 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"A limited amount of financial aid is available to those who qualify.\", \"vi\": \"Sẽ có một khoản hỗ trợ tài chính với số lượng hạn chế dành cho những người đáp ứng các điều kiện quy định.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Classes are capped at ten students.\", \"vi\": \"Số lượng học sinh trong mỗi lớp được giới hạn tối đa là mười em.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"TO APPLY:\", \"vi\": \"ĐỂ NỘP ĐƠN:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Please send a 20-page writing sample (this can be from any genre of writing) and a 200-word autobiographical statement to apply@greencityscreenwriters.org.\", \"vi\": \"Kính mong quý vị gửi một bài viết mẫu dài 20 trang (có thể thuộc bất kỳ thể loại nào) cùng với một bài tự thuật dài 200 từ đến địa chỉ email apply@greencityscreenwriters.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"An instructor will respond to your inquiry if you are accepted.\", \"vi\": \"Nếu quý vị được chấp nhận, giảng viên sẽ trả lời câu hỏi của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"From: Joshua Hartzog <jzog.2@greencityscreenwriters.org>\", \"vi\": \"Từ: Joshua Hartzog <jzog.2@greencityscreenwriters.org>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"To: Terry Hampton <hampton100@webcentral.com>\", \"vi\": \"Gửi: Terry Hampton <hampton100@webcentral.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Date: December 10\", \"vi\": \"Ngày: 10 tháng 12\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Subject: Upcoming screenwriting class series\", \"vi\": \"Chủ đề: Chuỗi lớp học viết kịch bản sắp tới\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Attachment: NSI form\", \"vi\": \"Tài liệu đính kèm: Mẫu đơn NSI\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Dear Mr. Hampton:\", \"vi\": \"Kính gửi ông Hampton:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"My name is Joshua Hartzog, and I am one of the instructors at Green City Screenwriters’ Workshop.\", \"vi\": \"Tên tôi là Joshua Hartzog, và tôi là một trong những giảng viên tại Lớp học Viết kịch bản Green City.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I am pleased to inform you of your acceptance to our next series of classes.\", \"vi\": \"Tôi rất vui mừng được thông báo với quý vị rằng quý vị đã được chấp nhận tham gia khóa học sắp tới của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Our committee was impressed with your writing sample.\", \"vi\": \"Hội đồng của chúng tôi đã rất ấn tượng với bài viết mẫu của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Here is a little about me: I have been a teacher at GCSW since it started.\", \"vi\": \"Dưới đây là một vài thông tin về bản thân tôi: Tôi đã công tác với tư cách là giáo viên tại GCSW kể từ khi trường này thành lập.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Additionally, I have written eight film scripts, including An Incredible Summer and Toast of the Town, both of which won National Writers’ Groups awards.\", \"vi\": \"Bên cạnh đó, tôi đã viết tám kịch bản phim, trong đó có *An Incredible Summer* và *Toast of the Town*, cả hai tác phẩm này đều đã giành được giải thưởng của Hiệp hội Các nhà văn Quốc gia.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Please fill out the attached New Student Information form and return it to me either via e-mail or in person at the Green City Foundation for the Arts by January 1.\", \"vi\": \"Kính mong quý vị điền vào mẫu “Thông tin sinh viên mới” đính kèm và gửi lại cho tôi qua email hoặc nộp trực tiếp tại Quỹ Nghệ thuật Green City trước ngày 1 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I look forward to seeing you for our first class on January 10.\", \"vi\": \"Tôi rất mong được gặp quý vị trong buổi học đầu tiên vào ngày 10 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Please pay attention to your inbox for your first assignment, which will be due by our first class meeting.\", \"vi\": \"Kính mong quý vị theo dõi hộp thư đến để nhận bài tập đầu tiên; bài tập này cần phải nộp trước buổi học đầu tiên của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Joshua Hartzog\", \"vi\": \"Joshua Hartzog\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}]' WHERE `id` = '6704a69c-9b2b-49d9-80e6-9963e4d8e068';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"A New Rail Line for Salvador\", \"vi\": \"Một tuyến đường sắt mới cho thành phố Salvador\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"By Leonel Menendez\", \"vi\": \"Tác giả: Leonel Menendez\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"(14 November)—The government of the state of Bahia has finally arrived at a decision about who will take charge of the railway project between Salvador and Paripe.\", \"vi\": \"(Ngày 14 tháng 11) — Chính quyền bang Bahia cuối cùng đã đưa ra quyết định về việc ai sẽ phụ trách dự án đường sắt nối giữa Salvador và Paripe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"After an unexpectedly long selection process, the Secretariat for Urban Development announced last week that a proposal had finally been selected.\", \"vi\": \"Sau một quá trình xét duyệt kéo dài hơn dự kiến, Ban Thư ký Phát triển Đô thị đã thông báo vào tuần trước rằng một đề xuất cuối cùng đã được lựa chọn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"A joint venture between SOA International and ROOV Project Management was chosen to receive the contract.\", \"vi\": \"Một liên doanh giữa SOA International và ROOV Project Management đã được lựa chọn để nhận hợp đồng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The Secretariat had insisted that a Brazilian firm be included in the contract.\", \"vi\": \"Ban Thư ký đã kiên quyết yêu cầu phải đưa một công ty của Brazil vào hợp đồng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"SOA International has long been involved in rail projects throughout Brazil, Spain, and the Middle East.\", \"vi\": \"SOA International từ lâu đã tham gia vào các dự án đường sắt trên khắp Brazil, Tây Ban Nha và Trung Đông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The Swiss company, ROOV Project Management, was recently selected as Project Management Company of the Year by the International Project Management Institute.\", \"vi\": \"Công ty ROOV Project Management của Thụy Sĩ vừa được Viện Quản lý Dự án Quốc tế (IPMI) vinh danh là “Công ty Quản lý Dự án của Năm”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The line will be constructed in two phases.\", \"vi\": \"Tuyến đường này sẽ được xây dựng theo hai giai đoạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The first phase will make use of an existing rail line that runs from Salvador to Plataforma, but the track will be replaced to accommodate the light-rail cars that SOA will build.\", \"vi\": \"Giai đoạn đầu tiên sẽ tận dụng tuyến đường sắt hiện có nối từ Salvador đến Plataforma, tuy nhiên, đường ray sẽ được thay thế để phù hợp với các toa tàu điện nhẹ do SOA chế tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The second phase will continue with the construction of a new track from Plataforma to Paripe.\", \"vi\": \"Giai đoạn thứ hai sẽ tiếp tục với việc xây dựng một tuyến đường sắt mới từ Plataforma đến Paripe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The long delay in settling on a vendor has caused the Secretariat to offer incentives for the project to be completed in 30 months.\", \"vi\": \"Việc chậm trễ kéo dài trong việc lựa chọn nhà thầu đã khiến Ban Thư ký phải đưa ra các biện pháp khuyến khích nhằm đảm bảo dự án được hoàn thành trong vòng 30 tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"However, Spokesperson David Rios of ROOV has said that 36 months would be the minimum reasonable time to complete the project because of unpredictable weather, labor, and supplies.\", \"vi\": \"Tuy nhiên, ông David Rios, Người phát ngôn của ROOV, đã cho biết rằng 36 tháng sẽ là khoảng thời gian tối thiểu hợp lý để hoàn thành dự án do những yếu tố khó lường như thời tiết, nguồn nhân lực và nguồn cung ứng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '67256e46-2652-4f79-a5e3-837a6e915899';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Fabien Vahle (8:43 A.M.)\", \"vi\": \"Fabien Vahle (8 giờ 43 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Sita, are you still at the warehouse?\", \"vi\": \"Sita ơi, cô vẫn còn ở kho hàng chứ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Sita Singh (8:46 A.M.)\", \"vi\": \"Sita Singh (8 giờ 46 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Yes.\", \"vi\": \"Vâng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Do you need something?\", \"vi\": \"Quý vị có cần gì không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Fabien Vahle (8:47 A.M.)\", \"vi\": \"Fabien Vahle (8 giờ 47 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Could you bring over some medium-sized cardboard gift boxes?\", \"vi\": \"Xin quý vị có thể mang sang cho tôi một vài chiếc hộp quà bằng bìa cứng cỡ vừa được không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You can put them in the closet on the second floor.\", \"vi\": \"Quý vị có thể cất chúng vào tủ quần áo ở tầng hai.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Sita Singh (8:48 A.M.)\", \"vi\": \"Sita Singh (8 giờ 48 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"How many?\", \"vi\": \"Có bao nhiêu?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Fabien Vahle (8:49 A.M.)\", \"vi\": \"Fabien Vahle (8 giờ 49 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"A dozen or so.\", \"vi\": \"Khoảng một chục.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sita Singh (8:52 A.M.)\", \"vi\": \"Sita Singh (8 giờ 52 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"That\'s about how many are left here.\", \"vi\": \"Đó cũng là số lượng còn lại ở đây.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Fabien Vahle (8:54 A.M.)\", \"vi\": \"Fabien Vahle (8 giờ 54 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I guess it\'s time to replenish the inventory.\", \"vi\": \"Tôi nghĩ đã đến lúc phải bổ sung hàng tồn kho rồi.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I\'ll send out an e-mail.\", \"vi\": \"Tôi sẽ gửi một email.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '6773b6f0-8a23-4ca8-9fb7-09bdd5492a5a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Lindsey Galloway\", \"vi\": \"Gửi tới: Lindsey Galloway\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Samuel Bains\", \"vi\": \"Từ: Samuel Bains\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: August 16\", \"vi\": \"Ngày: 16 tháng 8\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Exertreks boots for winter activities\", \"vi\": \"Chủ đề: Giày Exertreks dành cho các hoạt động mùa đông\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Hello Ms. Galloway,\", \"vi\": \"Kính gửi bà Galloway,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am sorry I missed your call this morning.\", \"vi\": \"Tôi rất tiếc vì đã không nghe được cuộc gọi của quý vị sáng nay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The answers to your questions are given below.\", \"vi\": \"Các câu trả lời cho các câu hỏi của quý vị được trình bày dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We here at Exertreks have recently completed the development of our Winter Hikers.\", \"vi\": \"Chúng tôi tại Exertreks vừa hoàn tất việc phát triển dòng sản phẩm Winter Hikers.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Like our other models, they are waterproof, but the Winter Hikers are most appropriate for use in extreme cold.\", \"vi\": \"Cũng giống như các mẫu giày khác của chúng tôi, những đôi giày này có khả năng chống thấm nước, nhưng dòng Winter Hikers là sự lựa chọn phù hợp nhất để sử dụng trong điều kiện thời tiết cực lạnh.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The boots are lined with a proprietary material that is highly effective at retaining body heat.\", \"vi\": \"Đôi ủng này được lót bằng một loại vật liệu độc quyền có khả năng giữ nhiệt cơ thể rất hiệu quả.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"They are also durable, light, and comfortable.\", \"vi\": \"Chúng còn có độ bền cao, nhẹ và mang lại cảm giác thoải mái.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"For orders of 50 pairs or more of the Winter Hikers, the wholesale price per pair is $65.\", \"vi\": \"Đối với các đơn hàng từ 50 đôi trở lên của dòng giày Winter Hikers, giá bán buôn cho mỗi đôi là 65 đô la.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The recommended retail price is $89.\", \"vi\": \"Giá bán lẻ đề xuất là 89 đô la.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We can deliver your order in two weeks.\", \"vi\": \"Chúng tôi có thể giao đơn hàng của quý khách trong vòng hai tuần.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Presale reviews of the boots by experts in outdoor sports have been enthusiastic.\", \"vi\": \"Các đánh giá trước khi ra mắt về đôi giày này từ các chuyên gia trong lĩnh vực thể thao ngoài trời đều rất nhiệt tình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"You can expect the Winter Hikers to be a big hit with your customers this year.\", \"vi\": \"Quý vị có thể kỳ vọng rằng bộ sưu tập “Winter Hikers” sẽ trở thành sản phẩm được khách hàng của quý vị ưa chuộng nhất trong năm nay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I look forward to hearing from you soon to answer any other questions and to help you with your first order.\", \"vi\": \"Tôi rất mong sớm nhận được phản hồi từ quý khách để giải đáp bất kỳ thắc mắc nào khác và hỗ trợ quý khách thực hiện đơn hàng đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Samuel Bains\", \"vi\": \"Samuel Bains\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '67f2f81a-56a1-4e67-a8bf-f3929ef4b256';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Westmouth Financial Services\", \"vi\": \"Công ty Dịch vụ Tài chính Westmouth\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"1311 Paul Street\", \"vi\": \"1311 Phố Paul\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Exeter EX8 9YJ, United Kingdom\", \"vi\": \"Exeter EX8 9YJ, Vương quốc Anh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"14 July\", \"vi\": \"Ngày 14 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Tartal,\", \"vi\": \"Kính gửi bà Tartal,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am writing to notify you of some upcoming changes regarding your retirement investment account at Westmouth Financial.\", \"vi\": \"Tôi viết thư này để thông báo cho quý vị về một số thay đổi sắp tới liên quan đến tài khoản đầu tư hưu trí của quý vị tại Westmouth Financial.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Firstly, as you may already know, your primary financial services advisor, Felix Reardon, is retiring next month.\", \"vi\": \"Trước hết, như quý vị có thể đã biết, cố vấn dịch vụ tài chính chính của quý vị, ông Felix Reardon, sẽ nghỉ hưu vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I have over fifteen years of experience working in personal finance and have worked at Westmouth Financial for three of those years, helping over 25 clients meet their retirement goals through savvy financial planning.\", \"vi\": \"Tôi có hơn mười lăm năm kinh nghiệm làm việc trong lĩnh vực tài chính cá nhân và đã công tác tại Westmouth Financial trong ba năm qua, giúp hơn 25 khách hàng đạt được mục tiêu hưu trí thông qua việc lập kế hoạch tài chính khôn ngoan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I am excited to help you continue this journey.\", \"vi\": \"Tôi rất hân hoan được đồng hành cùng quý vị trên chặng đường tiếp theo này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Secondly, I would like to schedule a time to meet or talk with you about your current portfolio.\", \"vi\": \"Thứ hai, tôi xin được sắp xếp một thời gian để gặp gỡ hoặc trao đổi với quý vị về danh mục đầu tư hiện tại của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We could meet in person or just have a simple phone or video chat, but it would be good for us to touch base to plan your investment strategy for the next ten years as you are nearing your retirement.\", \"vi\": \"Chúng ta có thể gặp mặt trực tiếp hoặc chỉ cần trao đổi qua điện thoại hay cuộc gọi video đơn giản, nhưng sẽ rất tốt nếu chúng ta liên lạc với nhau để lên kế hoạch chiến lược đầu tư cho mười năm tới, bởi vì quý vị đang dần đến tuổi nghỉ hưu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Along those lines, I specifically wanted to see if you were interested in shifting some of your funds into more stable assets like bonds and annuities.\", \"vi\": \"Theo hướng đó, tôi đặc biệt muốn biết liệu quý vị có quan tâm đến việc chuyển một phần nguồn vốn của mình sang các tài sản ổn định hơn như trái phiếu và hợp đồng niên kim hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I usually recommend shifting into these safer options as you get closer to retirement.\", \"vi\": \"Tôi thường khuyên quý vị nên chuyển sang các lựa chọn an toàn hơn này khi ngày nghỉ hưu đang đến gần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Please feel free to call me or send an e-mail so we can arrange a time to talk.\", \"vi\": \"Xin vui lòng gọi điện hoặc gửi email cho tôi để chúng ta có thể sắp xếp thời gian trao đổi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thanks, and I look forward to speaking more.\", \"vi\": \"Xin cảm ơn, và tôi rất mong được trao đổi thêm với quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Rita Hidayat\", \"vi\": \"Rita Hidayat\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Rita Hidayat, Account Manager\", \"vi\": \"Rita Hidayat, Quản lý khách hàng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '67fb6965-cec0-493f-9249-8f69f83ed154';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Anton Building\", \"vi\": \"Tòa nhà Anton\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Clanton (12 October)—The planned renovation of the historic Anton Building by Jantuni Property Developers (JPD) is facing new delays.\", \"vi\": \"Clanton (ngày 12 tháng 10) — Dự án cải tạo Tòa nhà Anton mang tính lịch sử do Công ty Phát triển Bất động sản Jantuni (JPD) thực hiện đang phải đối mặt với những sự chậm trễ mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"A JPD spokesperson says their negotiations with the city regarding a package of subsidies and tax incentives are ongoing and are proving somewhat contentious.\", \"vi\": \"Một phát ngôn viên của JPD cho biết các cuộc đàm phán của họ với thành phố về gói trợ cấp và ưu đãi thuế hiện đang diễn ra và đang bộc lộ một số điểm gây tranh cãi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"According to the renovation plan, JPD must protect the historical integrity of the Anton Building while it creates a mixed-use interior, offering both office space and lower-level retail space.\", \"vi\": \"Theo kế hoạch cải tạo, JPD phải bảo tồn tính toàn vẹn lịch sử của Tòa nhà Anton đồng thời tạo ra một không gian nội thất đa chức năng, bao gồm cả khu văn phòng và khu bán lẻ ở các tầng dưới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"However, JPD\'s city permit to do the project is on hold pending the current negotiations.\", \"vi\": \"Tuy nhiên, giấy phép thực hiện dự án do thành phố cấp cho JPD hiện đang bị tạm hoãn trong khi chờ kết quả các cuộc đàm phán hiện tại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This is making city revitalization advocates increasingly anxious.\", \"vi\": \"Điều này đang khiến những người ủng hộ việc phục hồi đô thị ngày càng lo lắng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Aditi Yadav comments, \\\"This plan to create useful space out of an empty decaying building will go a long way to restoring vibrancy to that area of the city.\", \"vi\": \"Bà Aditi Yadav nhận định: “Kế hoạch biến một tòa nhà bỏ hoang và xuống cấp thành không gian hữu ích này sẽ góp phần không nhỏ vào việc khôi phục sự sôi động cho khu vực đó của thành phố.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I sincerely hope that JPD does not back out.\", \"vi\": \"Tôi chân thành hy vọng rằng JPD sẽ không rút lui.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In creating their offer, the City Council should consider JPD\'s excellent record of beautifully restoring and maintaining several other historic buildings in Clanton.\\\"\", \"vi\": \"Khi xây dựng đề xuất của mình, Hội đồng Thành phố nên xem xét thành tích xuất sắc của JPD trong việc trùng tu và bảo trì một cách tuyệt vời một số công trình lịch sử khác tại Clanton.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"From: anabautista@lenoiva-health.com\", \"vi\": \"Nguồn: anabautista@lenoiva-health.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To: t.rowell@jantunipropertydevelopers.com\", \"vi\": \"Gửi tới: t.rowell@jantunipropertydevelopers.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Date: 20 February\", \"vi\": \"Ngày: 20 tháng 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Subject: Lease inquiry\", \"vi\": \"Chủ đề: Yêu cầu thông tin về hợp đồng thuê\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Dear Mr. Rowell,\", \"vi\": \"Kính gửi ông Rowell,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I am the owner of Lenoiva, a health-care technology company.\", \"vi\": \"Tôi là chủ sở hữu của Lenoiva, một công ty công nghệ trong lĩnh vực chăm sóc sức khỏe.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We plan to expand our operations and we need new office space.\", \"vi\": \"Chúng tôi có kế hoạch mở rộng hoạt động và đang cần thêm mặt bằng văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The Anton Building is one of the locations in Clanton that we are considering.\", \"vi\": \"Tòa nhà Anton là một trong những địa điểm tại Clanton mà chúng tôi đang xem xét.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We have been informed that your restoration project of this building will be finished sometime this spring, which is good timing for us.\", \"vi\": \"Chúng tôi được biết rằng dự án trùng tu tòa nhà này của quý vị sẽ hoàn thành vào một thời điểm nào đó trong mùa xuân năm nay, đây là thời điểm rất thuận lợi đối với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We are particularly attracted by the easy access to public transportation services that your building offers.\", \"vi\": \"Chúng tôi đặc biệt ấn tượng với việc tòa nhà của quý vị mang lại sự thuận tiện trong việc tiếp cận các dịch vụ giao thông công cộng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Do you still have spaces available for rent?\", \"vi\": \"Quý vị hiện vẫn còn chỗ trống để cho thuê không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We anticipate needing a space at least 300 square metres in size.\", \"vi\": \"Chúng tôi dự kiến sẽ cần một không gian có diện tích ít nhất 300 mét vuông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Would there be any reserved parking for our employees if we rented there?\", \"vi\": \"Nếu chúng tôi thuê mặt bằng tại đó, liệu có chỗ đỗ xe dành riêng cho nhân viên của chúng tôi không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"We would appreciate any information you can provide.\", \"vi\": \"Chúng tôi rất mong nhận được bất kỳ thông tin nào mà quý vị có thể cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Thank you in advance,\", \"vi\": \"Xin chân thành cảm ơn quý vị trước,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Ana Bautista\", \"vi\": \"Ana, người rửa tội\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Unit 2A\\n350 m²\\nT&M Accountancy - Unit 2B\\n150 m²\\nAvailable - Unit 2C\\n100 m²\\nAvailable\", \"vi\": \"Căn 2A\\n350 m²\\nCông ty Kế toán T&M - Căn 2B\\n150 m²\\nCòn trống - Căn 2C\\n100 m²\\nCòn trống\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Unit 2D\\n250 m²\\nAvailable - Unit 2E\\n375 m²\\nAvailable\", \"vi\": \"Căn hộ 2D\\n250 m²\\nCòn trống - Căn hộ 2E\\n375 m²\\nCòn trống\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"One Anton Place – 2nd Floor Plan (office space)\", \"vi\": \"One Anton Place – Bản vẽ mặt bằng tầng 2 (khu vực văn phòng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '68327d6d-2f04-4f5b-b921-6caa774cfc34';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"STOP!\", \"vi\": \"DỪNG LẠI!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"PLEASE READ FIRST.\", \"vi\": \"XIN VUI LÒNG ĐỌC TRƯỚC.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Thank you for purchasing this item.\", \"vi\": \"Xin chân thành cảm ơn Quý khách đã mua sản phẩm này.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"As you do the unpacking, please verify that all components are included and place them in a safe area to avoid loss or damage.\", \"vi\": \"Trong quá trình mở hộp, xin vui lòng kiểm tra xem tất cả các bộ phận có đầy đủ hay không và đặt chúng ở nơi an toàn để tránh bị thất lạc hoặc hư hỏng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Assemble the item on a soft surface or on the flattened empty box.\", \"vi\": \"Xin vui lòng lắp ráp sản phẩm trên một bề mặt mềm hoặc trên chiếc hộp rỗng đã được dẹp phẳng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Follow the pictures and begin the assembly by placing the main part on its side.\", \"vi\": \"Hãy làm theo các hình minh họa và bắt đầu quá trình lắp ráp bằng cách đặt bộ phận chính nằm nghiêng sang một bên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Never overtighten any screws or bolts, or you may damage the wood or cushioning.\", \"vi\": \"Không bao giờ vặn quá chặt bất kỳ ốc vít hay bu-lông nào, nếu không quý vị có thể làm hỏng gỗ hoặc lớp đệm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please visit our Web site to obtain maintenance tips and register your product for warranty coverage: www.indoordelight.com\", \"vi\": \"Kính mời quý vị truy cập trang web của chúng tôi để tham khảo các mẹo bảo trì và đăng ký sản phẩm của quý vị để được hưởng chế độ bảo hành: www.indoordelight.com\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '683791d6-4286-4b76-9bdd-ee6459762a00';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Miranda Noonan\", \"vi\": \"Từ: Miranda Noonan\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: June 26\", \"vi\": \"Ngày: 26 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Art auction\", \"vi\": \"Chủ đề: Buổi đấu giá tác phẩm nghệ thuật\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Donations\", \"vi\": \"Tệp đính kèm: Các khoản quyên góp\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Name - Name of piece and medium - Dimensions\", \"vi\": \"Tên - Tên tác phẩm và chất liệu - Kích thước\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Brian Healey - Surface of the Moon (photograph) - 45 cm x 76 cm\", \"vi\": \"Brian Healey - Bề mặt Mặt Trăng (ảnh) - 45 cm x 76 cm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Michaela Green - Streetlight (sculpture) - 90 cm\", \"vi\": \"Michaela Green - Đèn đường (tác phẩm điêu khắc) - 90 cm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Shinji Hasegawa - Shuki—Artist’s Dog (drawing) - 30 cm x 45 cm\", \"vi\": \"Shinji Hasegawa - Shuki — Chú chó của họa sĩ (bức vẽ) - 30 cm x 45 cm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Kim Cheung - Cornfield Sunrise (painting) - 40 cm x 70 cm\", \"vi\": \"Kim Cheung - Bình minh trên cánh đồng ngô (bức tranh) - 40 cm x 70 cm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To: Miranda Noonan\", \"vi\": \"Kính gửi: Miranda Noonan\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"From: Omonuwa Orou\", \"vi\": \"Từ: Omonuwa Orou\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Date: June 29\", \"vi\": \"Ngày: 29 tháng 6\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Subject: Re: Art auction\", \"vi\": \"Chủ đề: Trả lời: Buổi đấu giá tác phẩm nghệ thuật\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Ogunsanya and Bolden Art Auction: Local Artist Donations\", \"vi\": \"Phiên đấu giá nghệ thuật Ogunsanya và Bolden: Các tác phẩm do các nghệ sĩ địa phương quyên góp\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dear Employees,\", \"vi\": \"Kính gửi các nhân viên,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Ogunsanya and Bolden Law Firm is hosting our annual art auction, with all proceeds going to building a community garden.\", \"vi\": \"Văn phòng Luật sư Ogunsanya và Bolden đang tổ chức buổi đấu giá nghệ thuật thường niên của chúng tôi, với toàn bộ số tiền thu được sẽ được dành để xây dựng một khu vườn cộng đồng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Many local artists plan to donate pieces for our auction, and as always, we encourage all amateur artists in our firm to donate work as well.\", \"vi\": \"Nhiều nghệ sĩ địa phương dự định sẽ đóng góp các tác phẩm cho buổi đấu giá của chúng tôi, và như thường lệ, chúng tôi khuyến khích tất cả các nghệ sĩ nghiệp dư trong công ty chúng tôi cũng đóng góp tác phẩm của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Get out those paintbrushes and pencils and unleash your creativity.\", \"vi\": \"Hãy lấy những chiếc cọ vẽ và bút chì ra và thỏa sức phát huy sự sáng tạo của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"It is always a treat to see our colleagues’ art hanging alongside pieces by professional artists!\", \"vi\": \"Thật là một niềm vui lớn khi được chiêm ngưỡng các tác phẩm nghệ thuật của các đồng nghiệp được trưng bày bên cạnh những tác phẩm của các nghệ sĩ chuyên nghiệp!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"This year’s auction will be at Seven Gates Hotel and Restaurant on Friday, July 27, at 7:00 P.M. Our event will be held in the hotel restaurant, which has excellent lighting for our purposes.\", \"vi\": \"Buổi đấu giá năm nay sẽ diễn ra tại Khách sạn và Nhà hàng Seven Gates vào thứ Sáu, ngày 27 tháng 7, lúc 7 giờ tối. Sự kiện của chúng tôi sẽ được tổ chức tại nhà hàng của khách sạn, nơi có hệ thống chiếu sáng rất phù hợp với mục đích của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I have attached a chart listing the professional art that has been donated so far.\", \"vi\": \"Tôi đã đính kèm một bảng liệt kê các tác phẩm nghệ thuật chuyên nghiệp đã được quyên góp cho đến nay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"If you are interested in contributing this year, please e-mail me the details about your submission.\", \"vi\": \"Nếu quý vị quan tâm đến việc đóng góp trong năm nay, xin vui lòng gửi email cho tôi để cung cấp thông tin chi tiết về bài viết của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Keep in mind that photographs, paintings, and drawings are the most popular mediums.\", \"vi\": \"Xin lưu ý rằng ảnh chụp, tranh vẽ và bản vẽ là những hình thức nghệ thuật được ưa chuộng nhất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"However, one local artist donated a large sculpture, which will be the auction’s centerpiece.\", \"vi\": \"Tuy nhiên, một nghệ sĩ địa phương đã tặng một tác phẩm điêu khắc cỡ lớn, và đây sẽ là tác phẩm nổi bật nhất của buổi đấu giá.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Apart from that piece, we will only accept sculptures under 50 centimeters tall.\", \"vi\": \"Ngoài tác phẩm đó ra, chúng tôi chỉ chấp nhận các tác phẩm điêu khắc có chiều cao dưới 50 centimet.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Miranda Noonan, Auction Chairperson\", \"vi\": \"Bà Miranda Noonan, Chủ tịch Ban tổ chức buổi đấu giá\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Hello, Ms. Noonan,\", \"vi\": \"Xin chào, bà Noonan.\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I am planning to contribute a piece of art again this year, but I’ve noticed its subject is very similar to that of another piece listed in your e-mail attachment.\", \"vi\": \"Năm nay tôi dự định sẽ đóng góp một tác phẩm nghệ thuật một lần nữa, nhưng tôi nhận thấy chủ đề của tác phẩm này rất giống với chủ đề của một tác phẩm khác được đính kèm trong email của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I’ve painted an orchard near my parents’ house as it looks just when the sun is rising above it.\", \"vi\": \"Tôi đã vẽ một vườn cây ăn quả gần nhà bố mẹ tôi, với khung cảnh đúng vào lúc mặt trời vừa ló rạng phía trên vườn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Could I ask that my painting be placed away from the similar artwork?\", \"vi\": \"Tôi có thể đề nghị treo bức tranh của tôi ở vị trí cách xa các tác phẩm nghệ thuật tương tự được không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Omonuwa Orou\", \"vi\": \"Omonuwa Orou\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '684487fb-1cce-4f48-8bf6-703cd3b2739a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: <amelia.jackson@atmosrecords.com>\", \"vi\": \"Từ: <amelia.jackson@atmosrecords.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: <marcus.hawkins@mhawkinsartist.com>\", \"vi\": \"Gửi tới: <marcus.hawkins@mhawkinsartist.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Album artwork opportunity\", \"vi\": \"Chủ đề: Cơ hội thiết kế bìa album\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: August 14\", \"vi\": \"Ngày: 14 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Hawkins,\", \"vi\": \"Kính gửi ông Hawkins,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am the art director for Atmos Records, and I am writing to ask whether you would consider creating the cover art for an album we are producing.\", \"vi\": \"Tôi là giám đốc nghệ thuật của Atmos Records, và tôi viết thư này để hỏi xem quý vị có thể xem xét việc thiết kế bìa cho một album mà chúng tôi đang sản xuất hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It is Chris Embry\'s follow-up to Rain Tomorrow, which you may be aware was one of the top-selling albums of last year.\", \"vi\": \"Đây là album tiếp theo của Chris Embry sau Rain Tomorrow – như quý vị có thể đã biết, đây là một trong những album bán chạy nhất năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The new album does not yet have a title, but it deals with themes of youth and friendship.\", \"vi\": \"Album mới này hiện vẫn chưa có tên, nhưng nội dung xoay quanh các chủ đề về tuổi trẻ và tình bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I remembered that your photographs also explore these subjects, so I showed Chris the gallery page on your Web site.\", \"vi\": \"Tôi nhớ rằng các bức ảnh của anh cũng khai thác những chủ đề này, nên tôi đã cho Chris xem trang thư viện ảnh trên trang web của anh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"He loved your work and was very excited about the idea of collaborating.\", \"vi\": \"Ông ấy rất thích tác phẩm của quý vị và tỏ ra vô cùng hào hứng với ý tưởng hợp tác này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We are particularly interested in the possibility of recreating your Dawn Fields series of photos.\", \"vi\": \"Chúng tôi đặc biệt quan tâm đến khả năng tái hiện lại loạt ảnh “Dawn Fields” của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If you would like to become involved in this project or just want to know more, please get in touch.\", \"vi\": \"Nếu quý vị mong muốn tham gia vào dự án này hoặc chỉ đơn giản là muốn tìm hiểu thêm, xin vui lòng liên hệ với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"We hope to hear from you.\", \"vi\": \"Chúng tôi mong nhận được phản hồi từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Amelia Jackson\", \"vi\": \"Amelia Jackson\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Atmos Records\", \"vi\": \"Atmos Records\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"(310) 555-0174\", \"vi\": \"(310) 555-0174\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '69001348-5850-4a85-87d9-248e7008aa1e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To:          Emi Tokuda\", \"vi\": \"Kính gửi: Emi Tokuda\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From:      Paul Soderman\", \"vi\": \"Từ:      Paul Soderman\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date:       January 25\", \"vi\": \"Ngày:       25 tháng 1\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject:   Our discussion\", \"vi\": \"Chủ đề:   Cuộc thảo luận của chúng ta\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Tokuda,\", \"vi\": \"Kính gửi bà Tokuda,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I\'m writing to confirm the details of our telephone conversation earlier today.\", \"vi\": \"Tôi viết thư này để xác nhận lại các chi tiết trong cuộc trò chuyện qua điện thoại của chúng ta hồi sáng nay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As we discussed, Galahad Industrial Machinery will install and maintain one self-service checkout kiosk in each of the four locations operated by Paterra Department Stores in Haddonfield.\", \"vi\": \"Như chúng ta đã thảo luận, Công ty Máy móc Công nghiệp Galahad sẽ lắp đặt và bảo trì một kiosk thanh toán tự phục vụ tại mỗi một trong bốn địa điểm do Hệ thống Cửa hàng Bách hóa Paterra vận hành tại Haddonfield.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The installation charge for each kiosk will be $2,000 per unit.\", \"vi\": \"Phí lắp đặt cho mỗi ki-ốt sẽ là 2.000 đô la cho mỗi chiếc.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Installation will be scheduled at a mutually agreed-upon day and time.\", \"vi\": \"Việc lắp đặt sẽ được lên lịch vào ngày và giờ mà hai bên đã thống nhất.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Our maintenance fee, covering all four kiosks, is $120 per month.\", \"vi\": \"Phí bảo trì của chúng tôi, bao gồm cả bốn ki-ốt, là 120 đô la mỗi tháng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Our technicians will be available 24 hours a day, 7 days a week, to service the kiosks.\", \"vi\": \"Các kỹ thuật viên của chúng tôi sẽ túc trực 24 giờ mỗi ngày, 7 ngày mỗi tuần để bảo trì các ki-ốt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"All equipment will meet or exceed international quality standards, and all our work is guaranteed.\", \"vi\": \"Tất cả các thiết bị đều sẽ đáp ứng hoặc vượt qua các tiêu chuẩn chất lượng quốc tế, và mọi công trình của chúng tôi đều được bảo hành.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"A formal written agreement will be sent to you by registered mail.\", \"vi\": \"Một văn bản thỏa thuận chính thức sẽ được gửi đến quý vị qua đường bưu điện có xác nhận.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We look forward to working with you.\", \"vi\": \"Chúng tôi rất mong được hợp tác với quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Paul Soderman, Managing Director\", \"vi\": \"Ông Paul Soderman, Giám đốc điều hành\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Galahad Industrial Machinery\", \"vi\": \"Công ty Máy móc Công nghiệp Galahad\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To:          Paul Soderman\", \"vi\": \"Gửi:          Paul Soderman\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From:      Emi Tokuda\", \"vi\": \"Từ: Emi Tokuda\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date:       April 2\", \"vi\": \"Ngày:       2 tháng 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subject:   Equipment removal and reinstallation\", \"vi\": \"Chủ đề:   Tháo dỡ và lắp đặt lại thiết bị\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Dear Mr. Soderman,\", \"vi\": \"Kính gửi ông Soderman,\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Please be advised that we have decided to close our store at 1506 Maple Street.\", \"vi\": \"Kính xin thông báo rằng chúng tôi đã quyết định đóng cửa cửa hàng tại số 1506 Maple Street.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"We plan to transfer the inventory and all equipment to our new location at 3300 Town Square Plaza.\", \"vi\": \"Chúng tôi dự kiến sẽ chuyển toàn bộ hàng tồn kho và tất cả các thiết bị sang địa điểm mới tại số 3300 Town Square Plaza.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"The transfer is planned for mid-June, but we have not yet set a date.\", \"vi\": \"Việc chuyển nhượng dự kiến sẽ diễn ra vào giữa tháng 6, nhưng chúng tôi vẫn chưa ấn định ngày cụ thể.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I will contact you next month to confirm the date and arrange a convenient time for your work crew to install the self-service kiosk.\", \"vi\": \"Tôi sẽ liên hệ với quý vị vào tháng tới để xác nhận ngày và sắp xếp một thời gian thuận tiện để đội thi công của quý vị tiến hành lắp đặt ki-ốt tự phục vụ.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I understand that, per our agreement dated January 25, your charge for the reinstallation will be the same as for the initial installation at the Maple Street store.\", \"vi\": \"Tôi hiểu rằng, theo thỏa thuận của chúng ta ngày 25 tháng 1, phí dịch vụ lắp đặt lại của quý công ty sẽ bằng với mức phí lắp đặt ban đầu tại cửa hàng trên đường Maple Street.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Yours truly,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 3, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Emi Tokuda, Managing Director\", \"vi\": \"Bà Emi Tokuda, Giám đốc Điều hành\", \"type\": \"sign_off\", \"doc_index\": 3, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Paterra Department Stores\", \"vi\": \"Hệ thống cửa hàng bách hóa Paterra\", \"type\": \"sign_off\", \"doc_index\": 3, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"MEMO\", \"vi\": \"BẢN GHI NHỚ\", \"type\": \"sign_off\", \"doc_index\": 3, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"To:        All Paterra Staff\", \"vi\": \"Gửi:        Toàn thể nhân viên Paterra\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"From:    Eleanor Bianchi, Branch Manager\", \"vi\": \"Từ:    Eleanor Bianchi, Giám đốc Chi nhánh\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Date:    June 5\", \"vi\": \"Ngày:    5 tháng 6\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Re:        Move update\", \"vi\": \"Trả lời:        Cập nhật về việc chuyển địa điểm\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Thanks to your hard work, our new store in the Town Square Plaza is on track to open on June 15.\", \"vi\": \"Nhờ sự nỗ lực của quý vị, cửa hàng mới của chúng tôi tại Town Square Plaza đang tiến triển đúng kế hoạch và dự kiến sẽ khai trương vào ngày 15 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"One of the problems with the store we are currently working out of is that it is not on a bus line.\", \"vi\": \"Một trong những vấn đề của cửa hàng mà chúng tôi hiện đang hoạt động là nơi đây không nằm trên tuyến xe buýt.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"By contrast, the location we will be moving to is served by bus number 689, so we expect to have a larger number of customers at that location.\", \"vi\": \"Ngược lại, địa điểm mà chúng tôi sắp chuyển đến có tuyến xe buýt số 689 đi qua, do đó chúng tôi kỳ vọng sẽ có số lượng khách hàng đông hơn tại địa điểm đó.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"We are only waiting for the last of our display shelves to be delivered from our warehouse so that we can finish the display in the gardening department.\", \"vi\": \"Chúng tôi hiện chỉ đang chờ lô kệ trưng bày cuối cùng được chuyển đến từ kho hàng để có thể hoàn tất việc trưng bày tại khu vực bán đồ làm vườn.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"In appreciation of your efforts, I\'ve brought pastries from Aniqa\'s Bakery.\", \"vi\": \"Để tri ân những nỗ lực của quý vị, tôi đã mang theo một số loại bánh ngọt từ tiệm bánh Aniqa’s Bakery.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"I\'ve put these treats on the break-room counter.\", \"vi\": \"Tôi đã đặt những món ăn vặt này lên quầy trong phòng nghỉ.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Enjoy!\", \"vi\": \"Chúc quý vị thưởng thức!\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 43, \"question_numbers\": []}]' WHERE `id` = '690e13a7-32cd-4f94-b5fb-9a514804551d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Live Chat\", \"vi\": \"Trò chuyện trực tuyến\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Satoru Hashimoto (10:42 A.M.) I just logged in to my guest loyalty program account and noticed that the nights I stayed at the Grand Jurong Hotel last month haven\'t been credited.\", \"vi\": \"Satoru Hashimoto (10 giờ 42 phút sáng) Tôi vừa đăng nhập vào tài khoản chương trình khách hàng thân thiết của mình và nhận thấy rằng số đêm tôi đã lưu trú tại Khách sạn Grand Jurong vào tháng trước vẫn chưa được tính vào tài khoản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Are my loyalty points being processed?\", \"vi\": \"Điểm thưởng của tôi hiện đang được xử lý phải không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Franca Russo (10:44 A.M.) Thank you for contacting the Customer Care Centre.\", \"vi\": \"Franca Russo (10 giờ 44 phút sáng) Xin cảm ơn quý khách đã liên hệ với Trung tâm Chăm sóc Khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I\'m looking at your account and see that the loyalty points are not there at the moment.\", \"vi\": \"Tôi đang xem xét tài khoản của quý khách và nhận thấy rằng hiện tại chưa có điểm thưởng nào trong tài khoản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Points are good for one year after the check-out date.\", \"vi\": \"Điểm thưởng có giá trị trong vòng một năm kể từ ngày làm thủ tục trả phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am adding Mr. Han Sai Wong from the Grand Jurong to this chat to confirm your stay at the hotel.\", \"vi\": \"Tôi xin mời ông Han Sai Wong từ khách sạn Grand Jurong tham gia cuộc trò chuyện này để xác nhận việc quý vị lưu trú tại khách sạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"What were the dates of your stay so that he can look up the reservation?\", \"vi\": \"Quý vị đã lưu trú trong khoảng thời gian nào để anh ấy có thể tra cứu thông tin đặt phòng?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Han Sai Wong (10:46 A.M.) Already got it.\", \"vi\": \"Han Sai Wong (10 giờ 46 phút sáng) Tôi đã nhận được rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I can confirm Mr. Hashimoto stayed four nights with a check-in date of March 7.\", \"vi\": \"Tôi xin xác nhận rằng ông Hashimoto đã lưu trú bốn đêm, với ngày nhận phòng là ngày 7 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Satoru Hashimoto (10:47 A.M.) March 7 through March 11.\", \"vi\": \"Satoru Hashimoto (10 giờ 47 phút sáng) từ ngày 7 tháng 3 đến ngày 11 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Franca Russo (10:50 A.M.) Mr. Hashimoto, I have added the points to your account.\", \"vi\": \"Franca Russo (10 giờ 50 phút sáng) Thưa ông Hashimoto, tôi đã cộng số điểm đó vào tài khoản của ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"With your new points, you are eligible to either upgrade your room for the stay you reserved next month, or you may apply the points toward one free night on a future booking.\", \"vi\": \"Với số điểm mới này, quý khách có thể lựa chọn nâng cấp hạng phòng cho kỳ lưu trú đã đặt vào tháng tới, hoặc sử dụng số điểm này để đổi lấy một đêm lưu trú miễn phí cho một lần đặt phòng trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"May I assist you in upgrading your current reservation or in completing a booking for a future stay?\", \"vi\": \"Tôi có thể hỗ trợ quý khách nâng cấp đặt phòng hiện tại hoặc hoàn tất việc đặt phòng cho kỳ lưu trú sắp tới được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Satoru Hashimoto (10:51 A.M.) Not at this time.\", \"vi\": \"Satoru Hashimoto (10 giờ 51 phút sáng) Hiện tại thì chưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thank you for your help!\", \"vi\": \"Xin chân thành cảm ơn sự giúp đỡ của quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '69834589-5686-4303-9731-6e409f78f06f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Hae-won Jeong\", \"vi\": \"Kính gửi: Hae-won Jeong\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Julia Laurent\", \"vi\": \"Từ: Julia Laurent\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: July 28\", \"vi\": \"Ngày: 28 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Dallas hotels\", \"vi\": \"Chủ đề: Các khách sạn tại Dallas\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: List of downtown accommodations\", \"vi\": \"Tài liệu đính kèm: Danh sách các cơ sở lưu trú tại khu trung tâm thành phố\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Hae-won,\", \"vi\": \"Kính gửi Hae-won,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I plan to attend the National Digital Marketing Conference in October.\", \"vi\": \"Tôi dự định sẽ tham dự Hội nghị Tiếp thị Kỹ thuật số Toàn quốc vào tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I know you have traveled to this conference in Dallas many times.\", \"vi\": \"Tôi biết quý vị đã nhiều lần đến tham dự hội nghị này tại Dallas.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This will be my first time attending, and I\'m not sure which hotel to book.\", \"vi\": \"Đây sẽ là lần đầu tiên tôi tham dự sự kiện này, và tôi chưa biết nên đặt phòng tại khách sạn nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I have attached a list of accommodations that are near the convention center.\", \"vi\": \"Tôi đã đính kèm danh sách các cơ sở lưu trú nằm gần trung tâm hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Right now, I am leaning toward the Bonita Suites Hotel, but I would like to know which property you would recommend.\", \"vi\": \"Hiện tại, tôi đang nghiêng về khách sạn Bonita Suites, nhưng tôi muốn biết quý vị sẽ giới thiệu khách sạn nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I hope you have settled into your new position with the digital marketing department.\", \"vi\": \"Tôi hy vọng quý vị đã ổn định công việc tại vị trí mới trong phòng tiếp thị kỹ thuật số.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I am looking forward to the conference and hope to see you again there.\", \"vi\": \"Tôi rất mong chờ hội nghị này và hy vọng sẽ được gặp lại quý vị tại đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Julia Laurent\", \"vi\": \"Julia Laurent\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"E-mail Marketing Specialist\", \"vi\": \"Chuyên viên Tiếp thị qua email\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The 3R Marketing Firm\", \"vi\": \"Công ty Tư vấn Tiếp thị 3R\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Hotel - Rate - Description\", \"vi\": \"Khách sạn - Giá phòng - Mô tả\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The Oaktree Hotel - $204/night - Luxury hotel in the heart of downtown\\nClose to the convention center\\nOutdoor pool, three on-site restaurants\\nClose to shopping\", \"vi\": \"Khách sạn Oaktree - 204 USD/đêm - Khách sạn sang trọng tọa lạc ngay trung tâm thành phố\\nGần trung tâm hội nghị\\nCó hồ bơi ngoài trời và ba nhà hàng ngay trong khuôn viên khách sạn\\nGần các khu mua sắm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Alessi Dallas Hotel - $155/night - Quaint boutique hotel in downtown Dallas\\nLobby restaurant for breakfast and dinner\\nNear convention center and history museum\", \"vi\": \"Khách sạn Alessi Dallas - 155 USD/đêm - Khách sạn boutique xinh xắn nằm tại trung tâm thành phố Dallas\\nNhà hàng tại sảnh phục vụ bữa sáng và bữa tối\\nGần trung tâm hội nghị và bảo tàng lịch sử\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Bonita Suites Hotel - $125/night - New hotel in downtown convention center area\\nOffice and kitchen in each suite\\nComputer center with printers located in lobby\\nMeeting space available for groups\\nFree on-site parking available\", \"vi\": \"Khách sạn Bonita Suites - 125 USD/đêm - Khách sạn mới tọa lạc tại khu vực trung tâm hội nghị ở trung tâm thành phố\\nMỗi phòng suite đều có phòng làm việc và bếp\\nTrung tâm máy tính kèm máy in đặt tại sảnh\\nCó không gian hội nghị dành cho các nhóm\\nCó bãi đỗ xe miễn phí tại chỗ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"List of Downtown Accommodations (from www.topbusinesshotels.com/search/Dallashotels)\", \"vi\": \"Danh sách các cơ sở lưu trú tại khu trung tâm (trích từ www.topbusinesshotels.com/search/Dallashotels)\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"To: Julia Laurent\", \"vi\": \"Kính gửi: Julia Laurent\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"From: Hae-won Jeong\", \"vi\": \"Từ: Hae-won Jeong\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Date: July 29\", \"vi\": \"Ngày: 29 tháng 7\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Subject: RE: Dallas hotels\", \"vi\": \"Chủ đề: Trả lời: Các khách sạn tại Dallas\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Dear Julia,\", \"vi\": \"Kính gửi Julia,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I will be attending the National Digital Marketing Conference this year as well!\", \"vi\": \"Năm nay, tôi cũng sẽ tham dự Hội nghị Tiếp thị Kỹ thuật số Toàn quốc!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I love traveling to Dallas every year for this conference because it is a great networking opportunity.\", \"vi\": \"Tôi rất thích được đến Dallas hàng năm để tham dự hội nghị này vì đây là một cơ hội tuyệt vời để mở rộng mạng lưới quan hệ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Since this is your first time attending, I recommend you go to the newcomers\' reception on the first night.\", \"vi\": \"Vì đây là lần đầu tiên quý vị tham dự, tôi khuyên quý vị nên tham gia buổi tiệc chào đón những người mới vào tối đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"The conference executive planning committee is putting it on, and it could be an excellent occasion to socialize with other conference goers.\", \"vi\": \"Ban tổ chức điều hành hội nghị đang phụ trách việc tổ chức sự kiện này, và đây có thể là một cơ hội tuyệt vời để giao lưu với các đại biểu khác tham dự hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I will be staying at the Alessi Dallas Hotel.\", \"vi\": \"Tôi sẽ lưu trú tại Khách sạn Alessi Dallas.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"It is the closest to the convention center, and the rooms are comfortable.\", \"vi\": \"Đây là nơi gần trung tâm hội nghị nhất, và các phòng ở đây rất thoải mái.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"For you, I would suggest the one you already seem to prefer.\", \"vi\": \"Đối với quý vị, tôi xin đề xuất sản phẩm mà quý vị dường như đã ưa chuộng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"It so happens that the newcomers\' reception will be held in one of the event rooms there.\", \"vi\": \"Thật trùng hợp là buổi tiệc chào đón các thành viên mới sẽ được tổ chức tại một trong các phòng sự kiện ở đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"It is a little farther away but still convenient.\", \"vi\": \"Nơi đó cách đây xa hơn một chút nhưng vẫn thuận tiện.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"As a friendly reminder, we are advised not to book hotels with rates that exceed our company\'s limit of $175/night.\", \"vi\": \"Xin nhắc nhở quý vị rằng, chúng tôi được khuyến cáo không nên đặt phòng khách sạn với mức giá vượt quá giới hạn 175 USD/đêm do công ty quy định.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"I look forward to seeing you in October.\", \"vi\": \"Tôi rất mong được gặp quý vị vào tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"It will be lovely to catch up.\", \"vi\": \"Thật tuyệt vời khi có cơ hội gặp lại quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Hae-won Jeong\", \"vi\": \"Jeong, người đã giành chiến thắng trên sân nhà\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Digital Marketing Director\", \"vi\": \"Giám đốc Tiếp thị Kỹ thuật số\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"The 3R Marketing Firm\", \"vi\": \"Công ty Tư vấn Tiếp thị 3R\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}]' WHERE `id` = '69f38e55-cbdc-41c9-ad20-a5148da74509';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Janine Farber\", \"vi\": \"Từ: Janine Farber\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Barker Marketing Group employees\", \"vi\": \"Đến: Nhân viên của Barker Marketing Group\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: September 25\", \"vi\": \"Ngày: 25 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Entryway improvements\", \"vi\": \"Chủ đề: Cải tạo lối vào\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"As many of you have noticed, the main entrance of our building is in ______[131] condition.\", \"vi\": \"Như nhiều người trong số các bạn đã nhận thấy, lối vào chính của tòa nhà chúng ta đang ở trong tình trạng ______[131].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [131]}, {\"en\": \"It is in desperate need of attention.\", \"vi\": \"Nó đang rất cần được tu sửa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Therefore, beginning at 6 P.M. on Friday, the main entrance ______[132] for approximately one month as it is renovated.\", \"vi\": \"Do đó, bắt đầu từ 6 giờ chiều vào thứ Sáu, lối vào chính ______[132] trong khoảng một tháng khi được cải tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [132]}, {\"en\": \"The changes will give the entryway a more streamlined and contemporary appearance.\", \"vi\": \"Những thay đổi này sẽ mang lại cho khu vực lối vào một diện mạo gọn gàng và hiện đại hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[133] the main entrance is closed, employees and visitors may use the side entrances to gain access to the building.\", \"vi\": \"______[133] lối vào chính đóng cửa, nhân viên và khách tham quan có thể sử dụng các lối vào phụ để vào tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [133]}, {\"en\": \"______[134].\", \"vi\": \"______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [134]}]' WHERE `id` = '6a14c4e6-7030-4c0a-acea-aa62545e3478';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Lakeview Railway Onboard Bicycle Policy\", \"vi\": \"Chính sách mang xe đạp lên tàu của Đường sắt Lakeview\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Would you like to use your bicycle to explore the Lakeview Corridor Scenic Area?\", \"vi\": \"Bạn có muốn sử dụng xe đạp của mình để khám phá Khu thắng cảnh Hành lang Lakeview không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Our trains have the ______[131] you need to safely transport your bike.\", \"vi\": \"Các chuyến tàu của chúng tôi có ______[131] mà bạn cần để vận chuyển xe đạp của mình một cách an toàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [131]}, {\"en\": \"When booking your ticket, just remember that reservations ______[132] for both you and your bicycle.\", \"vi\": \"Khi đặt vé, hãy nhớ rằng các chỗ ngồi ______[132] cho cả bạn và xe đạp của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [132]}, {\"en\": \"Reserve your bicycle spot ______[133].\", \"vi\": \"Hãy đặt chỗ cho xe đạp của bạn ______[133].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [133]}, {\"en\": \"There are a limited number of storage racks on each train.\", \"vi\": \"Có số lượng hạn chế các giá để đồ trên mỗi chuyến tàu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"You are responsible for stowing your bike securely.\", \"vi\": \"Bạn chịu trách nhiệm cất giữ xe đạp của mình một cách an toàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"______[134].\", \"vi\": \"______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [134]}, {\"en\": \"Lakeview Railway does not take responsibility for bicycles lost or damaged aboard our trains.\", \"vi\": \"Đường sắt Lakeview không chịu trách nhiệm đối với các trường hợp xe đạp bị mất hoặc hư hỏng trên các chuyến tàu của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '6a2213c5-3003-4170-be7a-170907ab1d59';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"ALPHA LANDSCAPING SERVICES\", \"vi\": \"DỊCH VỤ THIẾT KẾ CẢNH QUAN ALPHA\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"www.alpha-landscaping.net\", \"vi\": \"www.alpha-landscaping.net\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Alpha Landscaping Services can help you make the most of your outdoor space as well as add value to your property.\", \"vi\": \"Công ty Dịch vụ Thiết kế Cảnh quan Alpha có thể giúp quý vị tận dụng tối đa không gian ngoài trời cũng như gia tăng giá trị cho bất động sản của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Make a great outdoor space your family can enjoy or update the appearance of your commercial site.\", \"vi\": \"Hãy tạo nên một không gian ngoài trời tuyệt vời để cả gia đình cùng tận hưởng hoặc làm mới diện mạo cho cơ sở kinh doanh của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Our services are outlined below.\", \"vi\": \"Các dịch vụ của chúng tôi được trình bày như sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"All of our staff members must pass a rigorous safety course, much stricter than the industry standards, so you can be confident about working with us.\", \"vi\": \"Tất cả các nhân viên của chúng tôi đều phải hoàn thành một khóa đào tạo an toàn nghiêm ngặt, với các yêu cầu khắt khe hơn nhiều so với tiêu chuẩn của ngành, do đó quý vị có thể hoàn toàn yên tâm khi hợp tác với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Contact us at info@alpha-landscaping.net for a price quote.\", \"vi\": \"Vui lòng liên hệ với chúng tôi qua địa chỉ email info@alpha-landscaping.net để nhận báo giá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"MAINTENANCE\", \"vi\": \"BẢO TRÌ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We can keep your garden looking its best with regular visits throughout the entire year.\", \"vi\": \"Chúng tôi có thể giúp khu vườn của quý vị luôn giữ được vẻ đẹp rực rỡ nhất thông qua các đợt thăm khám định kỳ trong suốt cả năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This includes mowing, trimming bushes and trees, and weeding.\", \"vi\": \"Công việc này bao gồm cắt cỏ, tỉa cành bụi và cây, cũng như nhổ cỏ dại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We are busiest from April to September, so book ahead to avoid disappointment.\", \"vi\": \"Thời gian từ tháng 4 đến tháng 9 là cao điểm nhất của chúng tôi, vì vậy quý vị nên đặt chỗ trước để tránh trường hợp không có chỗ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You can select from weekly, bi-weekly, or monthly visits.\", \"vi\": \"Quý vị có thể lựa chọn tần suất thăm khám hàng tuần, hai tuần một lần hoặc hàng tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"DESIGN\", \"vi\": \"THIẾT KẾ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Let one of our landscape artists design the garden of your dreams, no matter what your budget is.\", \"vi\": \"Hãy để một trong những chuyên gia thiết kế cảnh quan của chúng tôi thiết kế khu vườn trong mơ của quý vị, bất kể ngân sách của quý vị là bao nhiêu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We’ll keep adjusting the plan until it’s just right.\", \"vi\": \"Chúng tôi sẽ tiếp tục điều chỉnh kế hoạch cho đến khi nó đạt được mức hoàn hảo nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From lights and fountains to simple flower beds, we can make it happen.\", \"vi\": \"Từ hệ thống đèn chiếu sáng và đài phun nước cho đến những bồn hoa đơn giản, chúng tôi đều có thể biến điều đó thành hiện thực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"No garden is too big or too small for us to handle.\", \"vi\": \"Không có khu vườn nào là quá lớn hay quá nhỏ đến mức chúng tôi không thể đảm nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"RESET\", \"vi\": \"ĐẶT LẠI\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Book a one-time visit to tackle a neglected garden and get it back into shape for you to care for easily.\", \"vi\": \"Hãy đặt lịch một lần duy nhất để khắc phục tình trạng khu vườn bị bỏ bê và đưa nó trở lại trạng thái gọn gàng, giúp quý vị dễ dàng chăm sóc hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"If your outdoor space is getting out of control, we can help you return it to its original condition.\", \"vi\": \"Nếu không gian ngoài trời của quý vị đang trở nên lộn xộn, chúng tôi có thể giúp quý vị khôi phục lại trạng thái ban đầu cho khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"RENTAL\", \"vi\": \"CHO THUÊ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Unlike other businesses, we allow customers to rent our garden equipment without having one of our employees hired to use it.\", \"vi\": \"Khác với các doanh nghiệp khác, chúng tôi cho phép khách hàng thuê thiết bị làm vườn của chúng tôi mà không cần phải thuê nhân viên của chúng tôi để vận hành thiết bị đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"That means you can do the work yourself and save money.\", \"vi\": \"Điều đó có nghĩa là quý vị có thể tự mình thực hiện công việc và tiết kiệm chi phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Each piece of machinery comes with a clear user manual.\", \"vi\": \"Mỗi thiết bị đều đi kèm với một cuốn hướng dẫn sử dụng rõ ràng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"To: info@alpha-landscaping.net\", \"vi\": \"Gửi tới: info@alpha-landscaping.net\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"From: loriroth@thehomeinbox.com\", \"vi\": \"Nguồn: loriroth@thehomeinbox.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date: April 19\", \"vi\": \"Ngày: 19 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Subject: Services\", \"vi\": \"Chủ đề: Dịch vụ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"To Whom It May Concern:\", \"vi\": \"Kính gửi quý vị có liên quan,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I’ve recently purchased a home in the Longmont neighborhood.\", \"vi\": \"Gần đây, tôi đã mua một căn nhà tại khu vực Longmont.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Although I really enjoy gardening, this garden is too much for me to deal with initially.\", \"vi\": \"Mặc dù tôi thực sự rất thích làm vườn, nhưng ban đầu khu vườn này quả thực quá sức đối với tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"It hasn’t had any care in several years, so I’d like to have your crew visit once to help get everything in order.\", \"vi\": \"Nơi này đã không được chăm sóc trong vài năm qua, vì vậy tôi mong đội ngũ của quý vị có thể đến đây một lần để giúp sắp xếp mọi thứ cho gọn gàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I already have the standard tools and equipment that you would need.\", \"vi\": \"Tôi đã có sẵn các dụng cụ và thiết bị tiêu chuẩn mà quý vị sẽ cần.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"The sooner you can visit, the better.\", \"vi\": \"Quý vị đến thăm càng sớm thì càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"My colleague at Seltice Enterprises, Alex Brooks, used your services at his home and recommended you highly.\", \"vi\": \"Đồng nghiệp của tôi tại Seltice Enterprises, ông Alex Brooks, đã sử dụng dịch vụ của quý công ty tại nhà riêng và đã nhiệt tình giới thiệu quý công ty.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Lori Roth\", \"vi\": \"Lori Roth\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 38, \"question_numbers\": []}]' WHERE `id` = '6a27b00d-b463-4520-81d0-8bed361d8bbe';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"45-cm trencher - 60-cm trencher\", \"vi\": \"Máy đào rãnh 45 cm - Máy đào rãnh 60 cm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"4-hour rental - $166 - $194\", \"vi\": \"Thuê trong 4 giờ - 166–194 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"24-hour rental - $237 - $275\", \"vi\": \"Thuê trong 24 giờ - 237–275 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"https://www.zoliorentals.ca\", \"vi\": \"https://www.zoliorentals.ca\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Zolio Rentals Ltd. has a large inventory of heavy machines and construction tools available for hourly or daily rental.\", \"vi\": \"Công ty Zolio Rentals Ltd. sở hữu một kho máy móc hạng nặng và dụng cụ xây dựng phong phú, sẵn sàng cho thuê theo giờ hoặc theo ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"No matter what your task is, we likely have what you need to tackle it.\", \"vi\": \"Dù nhiệm vụ của quý vị là gì đi chăng nữa, chúng tôi rất có thể cũng có những gì quý vị cần để hoàn thành nhiệm vụ đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We have more than 50 locations throughout Canada, with limited delivery available in some locations.\", \"vi\": \"Chúng tôi có hơn 50 chi nhánh trên khắp Canada, với dịch vụ giao hàng có giới hạn tại một số địa điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If you require assistance, please call us at 604-555-0129 or e-mail us at info@zoliorentals.ca.\", \"vi\": \"Nếu quý vị cần hỗ trợ, vui lòng gọi cho chúng tôi theo số 604-555-0129 hoặc gửi email đến địa chỉ info@zoliorentals.ca.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Search:\", \"vi\": \"Tìm kiếm:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Results:\", \"vi\": \"Kết quả:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Machine for trench digging\", \"vi\": \"Máy đào rãnh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: Sharla Stanton <sharla@stantonacres.ca>\", \"vi\": \"Gửi tới: Sharla Stanton <sharla@stantonacres.ca>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From: Ralph Fitzpatrick <rfitzpatrick@fitzgreenways.ca>\", \"vi\": \"Từ: Ralph Fitzpatrick <rfitzpatrick@fitzgreenways.ca>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: 6 April\", \"vi\": \"Ngày: 6 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Subject: Trencher machine\", \"vi\": \"Chủ đề: Máy đào rãnh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Hi Sharla,\", \"vi\": \"Xin chào Sharla,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"You had mentioned the other day that you anticipate needing to dig an irrigation trench on your property, just as I do.\", \"vi\": \"Hôm nọ, quý vị đã đề cập rằng quý vị dự kiến sẽ phải đào một rãnh tưới trên khu đất của mình, giống như tôi vậy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I wanted to let you know that I did some searching on the Zolio Rentals Web site, and I have decided that tomorrow I am going to rent the smallest trencher that is available.\", \"vi\": \"Tôi muốn thông báo với quý vị rằng tôi đã tìm hiểu trên trang web Zolio Rentals và đã quyết định rằng ngày mai tôi sẽ thuê chiếc máy đào rãnh nhỏ nhất hiện có.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I will need the machine only for a couple of hours, but since the closest rental location is 45 minutes away in Durham, and it will take time to load it onto my truck both for the trip home and back to Durham again, I have decided to rent the machine for a full day.\", \"vi\": \"Tôi chỉ cần chiếc máy này trong vài giờ thôi, nhưng vì địa điểm cho thuê gần nhất cách đây 45 phút lái xe tại Durham, và việc chất máy lên xe tải của tôi sẽ mất thời gian, cả cho chuyến về nhà lẫn chuyến quay lại Durham, nên tôi đã quyết định thuê chiếc máy này trong cả ngày.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Would you want to use the machine while I have it?\", \"vi\": \"Trong thời gian tôi đang mượn chiếc máy này, quý vị có muốn sử dụng nó không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"If so, we can coordinate our schedules, and I can bring it to you after I finish.\", \"vi\": \"Nếu vậy, chúng ta có thể sắp xếp thời gian cho phù hợp, và tôi sẽ mang nó đến cho quý vị sau khi hoàn thành.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Then I can return the trencher to Zolio Rentals the next morning.\", \"vi\": \"Vậy thì sáng hôm sau tôi có thể trả lại máy đào rãnh cho công ty Zolio Rentals.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I will gladly cover the entire rental fee.\", \"vi\": \"Tôi rất sẵn lòng chi trả toàn bộ phí thuê.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"It is my way of returning the favour for your help with my lawn mower last autumn.\", \"vi\": \"Đây là cách tôi muốn đáp lại ân tình của quý vị khi đã giúp tôi sửa máy cắt cỏ vào mùa thu năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Please let me know.\", \"vi\": \"Xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Ralph\", \"vi\": \"Ralph\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '6a3225b6-0506-419f-a6b4-0ef7ddcc4268';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear Mr. Reilly,\", \"vi\": \"Kính gửi ông Reilly,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We received your request to let your sister use your excess frequent-flyer miles.\", \"vi\": \"Chúng tôi đã nhận được yêu cầu của quý khách về việc cho phép em gái quý khách sử dụng số dặm tích lũy bay dư thừa của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"This is only possible after connecting your Emerald Club accounts, which must be done through our Web site.\", \"vi\": \"Điều này chỉ có thể thực hiện được sau khi quý vị liên kết các tài khoản Emerald Club của mình; việc này bắt buộc phải được thực hiện thông qua trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Please follow these steps.\", \"vi\": \"Xin vui lòng thực hiện theo các bước sau đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Log in to your Emerald Club member page.\", \"vi\": \"Vui lòng đăng nhập vào trang thành viên Emerald Club của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Select “Add a Family Member” from the sidebar.\", \"vi\": \"Vui lòng chọn “Thêm thành viên gia đình” từ thanh bên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Enter the requested information about your relative.\", \"vi\": \"Vui lòng nhập các thông tin được yêu cầu về người thân của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"After reviewing the guidelines on documents that we will accept as proof of your relationship, upload eligible documents.\", \"vi\": \"Sau khi xem xét các hướng dẫn về các loại giấy tờ mà chúng tôi chấp nhận làm bằng chứng về mối quan hệ của quý vị, vui lòng tải lên các giấy tờ hợp lệ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Click “Submit” at the bottom of the page.\", \"vi\": \"Vui lòng nhấp vào nút “Gửi” ở cuối trang.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Within five business days, you will receive an e-mail confirming the connection or requesting additional documentation.\", \"vi\": \"Trong vòng năm ngày làm việc, quý vị sẽ nhận được một email xác nhận việc kết nối hoặc yêu cầu cung cấp thêm tài liệu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please let us know if you encounter difficulties with this process.\", \"vi\": \"Nếu quý vị gặp khó khăn trong quá trình này, xin vui lòng thông báo cho chúng tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Orla Collins\", \"vi\": \"Orla Collins\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Irish Air Customer Service\", \"vi\": \"Dịch vụ khách hàng của Irish Air\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '6a3229b9-734e-490f-a964-60fe54ba1a0e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Advertising with Mix 92 Radio\", \"vi\": \"Quảng cáo trên Đài phát thanh Mix 92\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"https://www.forum.askaway.com.au\", \"vi\": \"https://www.forum.askaway.com.au\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Marilyn Nguyen, 13 August\", \"vi\": \"Marilyn Nguyễn, ngày 13 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Has anyone advertised with Mix 92 Radio?\", \"vi\": \"Có ai đã từng quảng cáo trên Đài Mix 92 chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"James Defort, 15 August\", \"vi\": \"James Defort, ngày 15 tháng 8\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I have had advertisements running on Mix 92 Radio since last March.\", \"vi\": \"Tôi đã cho phát sóng các quảng cáo trên Đài phát thanh Mix 92 kể từ tháng 3 năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It has proved to be a smart choice: in recent months I have seen a significant increase in the number of customers visiting my business, Defort Automotive.\", \"vi\": \"Điều này đã chứng tỏ là một lựa chọn sáng suốt: trong những tháng gần đây, tôi đã chứng kiến số lượng khách hàng ghé thăm doanh nghiệp của tôi, Defort Automotive, tăng lên đáng kể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Many tell me it was the radio advertisement that brought them in.\", \"vi\": \"Nhiều người nói với tôi rằng chính quảng cáo trên đài phát thanh đã thu hút họ đến đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"When I signed a contract with the station, there was a problem with some unexpected charges.\", \"vi\": \"Khi tôi ký hợp đồng với đài truyền hình, đã xảy ra một vấn đề liên quan đến một số khoản phí phát sinh ngoài dự kiến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"However, Ms. Jager from the advertising department brought my concerns to her supervisor, and the matter was quickly resolved.\", \"vi\": \"Tuy nhiên, bà Jager thuộc phòng quảng cáo đã trình bày những lo ngại của tôi với cấp trên của bà ấy, và vấn đề đã nhanh chóng được giải quyết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Ms. Jager even checked back with me a week later to ensure I was pleased with the outcome.\", \"vi\": \"Bà Jager thậm chí còn liên hệ lại với tôi một tuần sau đó để đảm bảo rằng tôi hài lòng với kết quả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To: All staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"From: Kathrin Jager\", \"vi\": \"Từ: Kathrin Jager\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date: 29 September\", \"vi\": \"Ngày: 29 tháng 9\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Subject: Final broadcast\", \"vi\": \"Chủ đề: Chương trình phát sóng cuối cùng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Dear All,\", \"vi\": \"Kính gửi quý vị,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"As my internship at Mix 92 Radio draws to a close, please know that working here has been a wonderful experience for me.\", \"vi\": \"Khi kỳ thực tập của tôi tại Đài phát thanh Mix 92 sắp kết thúc, xin được chia sẻ rằng việc làm việc tại đây đã là một trải nghiệm tuyệt vời đối với tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I am grateful for the training and advice I have received over the past twelve months.\", \"vi\": \"Tôi xin bày tỏ lòng biết ơn đối với những khóa đào tạo và lời khuyên mà tôi đã nhận được trong mười hai tháng qua.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I especially want to thank my boss and mentor, Alison Alvey, from whom I have not only learned the fundamentals of radio advertising, but also how to meet customers\' needs.\", \"vi\": \"Tôi đặc biệt muốn gửi lời cảm ơn đến sếp và người hướng dẫn của tôi, bà Alison Alvey, người không chỉ giúp tôi nắm vững những kiến thức cơ bản về quảng cáo trên đài phát thanh, mà còn dạy tôi cách đáp ứng nhu cầu của khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Her nomination for this year\'s Australis Trophy speaks volumes about her dedication to her clients and staff.\", \"vi\": \"Việc cô được đề cử cho Giải thưởng Australis năm nay đã nói lên rất nhiều điều về sự tận tâm của cô đối với khách hàng và đội ngũ nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I also appreciate the video recording you presented to me, showing me at work and at play here.\", \"vi\": \"Tôi cũng rất cảm kích về đoạn video mà quý vị đã gửi cho tôi, trong đó ghi lại hình ảnh tôi đang làm việc và vui chơi tại đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I will miss joining many of you for lunches at the Hot Spot Café.\", \"vi\": \"Tôi sẽ rất nhớ những bữa trưa cùng nhiều quý vị tại quán Hot Spot Café.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Best wishes,\", \"vi\": \"Xin gửi lời chúc tốt đẹp nhất,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Kathrin Jager\", \"vi\": \"Kathrin Jager\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Australis Small Business Trophy Winners\\nAdvertising and Social Media Category\", \"vi\": \"Các đơn vị đoạt giải Australis Small Business Trophy\\nHạng mục Quảng cáo và Mạng xã hội\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"https://www.cba.com.au/aawinners/advertising_and_social_media\", \"vi\": \"https://www.cba.com.au/aawinners/advertising_and_social_media\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Platinum: Ravi Vedantam, Social Media Technology, Mix 92 Radio\", \"vi\": \"Giải Bạch kim: Ravi Vedantam, Công nghệ truyền thông xã hội, Đài phát thanh Mix 92\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Gold: Zixuan Li, Marketing, Streiler\'s Clothing Stores\", \"vi\": \"Huy chương Vàng: Li Zixuan, Bộ phận Tiếp thị, Hệ thống Cửa hàng Thời trang Streiler\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Silver: Jorge Beltran, Beltran Publicity Company\", \"vi\": \"Giải Bạc: Jorge Beltran, Công ty Truyền thông Beltran\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Bronze: Alison Alvey, Advertising, Mix 92 Radio\", \"vi\": \"Giải Đồng: Alison Alvey, Bộ phận Quảng cáo, Đài phát thanh Mix 92\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Winners were selected from over 50 nominations.\", \"vi\": \"Các cá nhân đoạt giải đã được lựa chọn từ hơn 50 đề cử.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"The recipient of the Platinum Australis Trophy will be profiled in the December issue of Canberra Business Today.\", \"vi\": \"Người được trao giải Platinum Australis Trophy sẽ được giới thiệu trên số tháng 12 của tạp chí Canberra Business Today.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Awards will be presented by the Canberra Business Association at a gala event in the banquet hall of the Fourth Street Hotel on 12 October.\", \"vi\": \"Các giải thưởng sẽ được Hiệp hội Doanh nghiệp Canberra trao tặng tại một buổi lễ long trọng diễn ra tại phòng tiệc của khách sạn Fourth Street vào ngày 12 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '6a3bfc6f-6780-46df-8710-69561bc07eaa';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"YOU\'RE INVITED!\", \"vi\": \"XIN MỜI QUÝ VỊ!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Corozal Digital\'s\", \"vi\": \"Của Corozal Digital\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Tenth Anniversary\", \"vi\": \"Kỷ niệm 10 năm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Join us to celebrate your hard work and dedication that got us to this milestone!\", \"vi\": \"Hãy cùng chúng tôi kỷ niệm những nỗ lực và sự cống hiến của quý vị, chính nhờ đó mà chúng ta đã đạt được cột mốc quan trọng này!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Saturday, June 15\", \"vi\": \"Thứ Bảy, ngày 15 tháng 6\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"6:00 P.M. Appetizers and Music\", \"vi\": \"18:00 Món khai vị và chương trình âm nhạc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"7:00 P.M. Dinner\", \"vi\": \"7 giờ tối. Bữa tối\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Bayshore Hotel\", \"vi\": \"Khách sạn Bayshore\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"22 Atlantic Avenue\", \"vi\": \"22 Đại lộ Atlantic\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"RSVP by June 1 to j.bovel@corozaldigital.com.\", \"vi\": \"Xin vui lòng xác nhận tham dự trước ngày 1 tháng 6 qua địa chỉ email j.bovel@corozaldigital.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '6a596df6-de19-4ddd-a421-8b770793e6ce';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Nelsign\", \"vi\": \"Nelsign\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Your signature has been captured.\", \"vi\": \"Chữ ký của bạn đã được ghi nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The document is waiting for four more signatures.\", \"vi\": \"Tài liệu đang chờ thêm bốn chữ ký nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Once all parties have signed the Nelsign document, you will ------- (143) by e-mail.\", \"vi\": \"Một khi tất cả các bên đã ký tài liệu Nelsign, bạn sẽ ------- (143) qua thư điện tử.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [143]}, {\"en\": \"At that time, the sender will also receive an alert that all necessary signatures on the contract have been acquired.\", \"vi\": \"Vào thời điểm đó, người gửi cũng sẽ nhận được thông báo rằng tất cả các chữ ký cần thiết trên hợp đồng đã được thu thập.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Upon ------- (144), all signers may access and save the document.\", \"vi\": \"Sau khi ------- (144), tất cả những người ký có thể truy cập và lưu tài liệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [144]}, {\"en\": \"If you have a Nelsign account, this contract and any other documents you have previously signed electronically with Nelsign will be saved in your profile.\", \"vi\": \"Nếu bạn có tài khoản Nelsign, hợp đồng này và bất kỳ tài liệu nào khác mà bạn đã ký điện tử trước đó với Nelsign sẽ được lưu trong hồ sơ của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"------- (145).\", \"vi\": \"------- (145).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [145]}, {\"en\": \"For any questions ------- (146) the signing process, contact our customer support center at inquiries@nelsign.com.\", \"vi\": \"Đối với bất kỳ câu hỏi nào ------- (146) quá trình ký kết, hãy liên hệ với trung tâm hỗ trợ khách hàng của chúng tôi tại inquiries@nelsign.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [146]}]' WHERE `id` = '6acd2e00-2e17-4a9f-8e93-1f0a40877198';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Fetler Airlines Tarmac Delay Contingency Plan\", \"vi\": \"Kế hoạch ứng phó với tình huống chậm trễ trên sân đỗ của Hãng hàng không Fetler\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Onboard departure delays are situations we do our best to avoid.\", \"vi\": \"Việc chậm trễ khi khởi hành sau khi hành khách đã lên máy bay là những tình huống mà chúng tôi luôn nỗ lực hết sức để tránh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"On rare occasions, weather, visibility, airport conditions, or other circumstances cause unavoidable ground delays.\", \"vi\": \"Trong một số trường hợp hiếm hoi, thời tiết, tầm nhìn, điều kiện tại sân bay hoặc các yếu tố khác có thể dẫn đến việc chậm trễ trên mặt đất không thể tránh khỏi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"In these cases, if the delay lasts more than 60 minutes, we will provide complimentary snacks and beverages.\", \"vi\": \"Trong những trường hợp này, nếu thời gian chậm trễ kéo dài hơn 60 phút, chúng tôi sẽ cung cấp đồ ăn nhẹ và đồ uống miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"If the delay continues for more than two hours (for domestic flights) or three hours (for international flights), the aircraft will return to the gate, and passengers can get off the plane.\", \"vi\": \"Nếu tình trạng chậm trễ kéo dài hơn hai giờ (đối với các chuyến bay nội địa) hoặc ba giờ (đối với các chuyến bay quốc tế), máy bay sẽ quay trở lại cửa ra vào và hành khách có thể xuống máy bay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Passengers will receive notifications at the gate every 30 minutes regarding the status of the delay.\", \"vi\": \"Hành khách sẽ nhận được thông báo tại cửa lên máy bay cứ sau 30 phút về tình hình chậm trễ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"These notifications will include the reasons for the delay and whether further amenities will be available such as meal or hotel vouchers.\", \"vi\": \"Các thông báo này sẽ nêu rõ lý do gây ra sự chậm trễ và liệu quý vị có được hưởng các tiện ích bổ sung như phiếu ăn hoặc phiếu lưu trú tại khách sạn hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '6ad3d963-d201-4ddb-96a6-bc2eaf3380a8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.hurnhamhistoricalsociety.org/news\", \"vi\": \"https://www.hurnhamhistoricalsociety.org/news\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Tuesday Evening Lecture Series\", \"vi\": \"Chuỗi bài giảng vào tối thứ Ba\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We are pleased to announce that our third annual lecture series will be hosted by the Hurnham Heritage Museum on Tuesday evenings over the next six weeks.\", \"vi\": \"Chúng tôi hân hạnh thông báo rằng chuỗi bài giảng thường niên lần thứ ba của chúng tôi sẽ được Bảo tàng Di sản Hurnham tổ chức vào các tối thứ Ba trong sáu tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Each guest speaker will focus on objects from the museum\'s permanent collection.\", \"vi\": \"Mỗi diễn giả khách mời sẽ tập trung trình bày về các hiện vật thuộc bộ sưu tập thường trực của bảo tàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The first lecture, on June 15 at 7:00 P.M., features Georgia Hinds, head curator of the Knowles Art Gallery.\", \"vi\": \"Buổi thuyết trình đầu tiên, diễn ra vào lúc 7 giờ tối ngày 15 tháng 6, sẽ có sự tham gia của bà Georgia Hinds, Trưởng ban bảo tàng của Phòng trưng bày Nghệ thuật Knowles.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Ms. Hinds will use a writing desk, a chest, and a household table to discuss what furniture can reveal to us about the lives of the first Hurnham residents over 200 years ago.\", \"vi\": \"Bà Hinds sẽ lấy bàn viết, tủ đựng đồ và bàn ăn trong nhà làm ví dụ để phân tích những thông tin mà đồ nội thất có thể tiết lộ cho chúng ta về cuộc sống của những cư dân đầu tiên tại Hurnham cách đây hơn 200 năm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The lecture series is open to the public and includes free admission to the Hurnham Heritage Museum.\", \"vi\": \"Chuỗi bài giảng này mở cửa cho công chúng và bao gồm vé vào cửa miễn phí tại Bảo tàng Di sản Hurnham.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The Fasseller Café, next door to the museum, will stay open late on Tuesdays to accommodate lecture attendees and the general public.\", \"vi\": \"Quán cà phê Fasseller, nằm ngay bên cạnh bảo tàng, sẽ mở cửa muộn vào các ngày thứ Ba để phục vụ những người tham dự buổi thuyết trình cũng như công chúng nói chung.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Posted on June 8\", \"vi\": \"Đăng ngày 8 tháng 6\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '6ae02987-4cbb-4e1e-82e1-aa11bc6a7f8d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"FOR IMMEDIATE RELEASE\", \"vi\": \"THÔNG CÁO BÁO CHÍ NGAY LẬP TỨC\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Contact: Alberto Gutierrez, a.gutierrez@viga.com\", \"vi\": \"Liên hệ: Alberto Gutierrez, a.gutierrez@viga.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"VANCOUVER (13 July)—VIGA is proud to announce the purchase of eight Noonan N250 airplanes.\", \"vi\": \"VANCOUVER (ngày 13 tháng 7) — VIGA hân hạnh thông báo về việc mua tám máy bay Noonan N250.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The planes\' delivery in approximately two years will bring the company\'s total fleet size to 156 aircraft, the third largest among Canadian carriers.\", \"vi\": \"Việc bàn giao các máy bay này trong khoảng hai năm tới sẽ nâng tổng số máy bay trong đội bay của công ty lên 156 chiếc, đứng thứ ba trong số các hãng hàng không Canada.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The deal is the latest in VIGA\'s long and successful relationship with Noonan.\", \"vi\": \"Thỏa thuận này là bước phát triển mới nhất trong mối quan hệ lâu dài và thành công giữa VIGA và ông Noonan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"At the same time, it marks the addition of a new and exciting model to the carrier\'s fleet, as well as a step towards its sustainability goals.\", \"vi\": \"Đồng thời, sự kiện này cũng đánh dấu việc bổ sung một mẫu máy bay mới và đầy hứa hẹn vào đội bay của hãng hàng không, đồng thời là một bước tiến hướng tới các mục tiêu phát triển bền vững của hãng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The Noonan N250 features the sophisticated TF8 turbofan engine, which provides excellent fuel efficiency and emits little carbon dioxide.\", \"vi\": \"Máy bay Noonan N250 được trang bị động cơ phản lực TF8 hiện đại, mang lại hiệu suất tiêu thụ nhiên liệu tuyệt vời và lượng khí thải carbon dioxide rất thấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The TF8 also has a lower noise footprint than other engines, affording travelers a peaceful in-cabin experience.\", \"vi\": \"Động cơ TF8 cũng có mức độ tiếng ồn thấp hơn so với các động cơ khác, mang đến cho hành khách trải nghiệm yên tĩnh trong khoang máy bay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"A single-aisle plane, each N250 can carry a total of 130 passengers.\", \"vi\": \"Là loại máy bay một lối đi, mỗi chiếc N250 có thể chở tổng cộng 130 hành khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"VIGA intends to use the planes to add new international service routes between its hub in Vancouver and airports in the United States.\", \"vi\": \"VIGA dự kiến sẽ sử dụng các máy bay này để mở thêm các tuyến bay quốc tế mới giữa trung tâm hoạt động tại Vancouver và các sân bay ở Hoa Kỳ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Depending on demand, it may also increase the frequency of existing flights.\", \"vi\": \"Tùy thuộc vào nhu cầu, hãng cũng có thể tăng tần suất các chuyến bay hiện có.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '6aefc73f-8dee-4660-a979-3074a2c6356c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.branxleycycles.com.my/about\", \"vi\": \"https://www.branxleycycles.com.my/about\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Home     About     Shop     Contact\", \"vi\": \"Trang chủ     Giới thiệu     Cửa hàng     Liên hệ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"About Our Products\", \"vi\": \"Giới thiệu về các sản phẩm của chúng tôi\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We make three-wheeled cargo bicycles for commercial and personal use.\", \"vi\": \"Chúng tôi sản xuất xe đạp chở hàng ba bánh dành cho mục đích thương mại và cá nhân.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"All our bicycles are made by hand in our production facility in Kuala Lumpur with parts made by local craftspeople.\", \"vi\": \"Tất cả các chiếc xe đạp của chúng tôi đều được chế tác thủ công tại cơ sở sản xuất của chúng tôi ở Kuala Lumpur, với các bộ phận do các nghệ nhân địa phương chế tạo.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"For more than 40 years, we have been building high-quality, eco-friendly bicycles that are good for the health of both people and the planet.\", \"vi\": \"Trong hơn 40 năm qua, chúng tôi đã không ngừng sản xuất những chiếc xe đạp chất lượng cao, thân thiện với môi trường, góp phần mang lại lợi ích cho sức khỏe của con người cũng như của hành tinh.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We are proud of our products, and we invite our customers to take photos of their Branxley bicycles in action and share the images via social media.\", \"vi\": \"Chúng tôi tự hào về các sản phẩm của mình, và xin mời quý khách hàng chụp ảnh những chiếc xe đạp Branxley của mình khi đang sử dụng và chia sẻ những hình ảnh đó trên mạng xã hội.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Update—30 August\", \"vi\": \"Cập nhật — ngày 30 tháng 8\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We have experienced a dramatic surge in orders.\", \"vi\": \"Chúng tôi đã chứng kiến sự gia tăng đột biến về số lượng đơn đặt hàng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Even with our staff working overtime to catch up, it may take longer than usual for customers to receive their bicycles.\", \"vi\": \"Dù đội ngũ nhân viên của chúng tôi đang làm thêm giờ để hoàn thành công việc, quý khách có thể sẽ phải chờ lâu hơn bình thường để nhận được xe đạp của mình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Currently, we are expecting a delivery time of 10 to 12 weeks for all bicycles ordered on or after August 15.\", \"vi\": \"Hiện tại, chúng tôi dự kiến thời gian giao hàng từ 10 đến 12 tuần đối với tất cả các đơn đặt hàng xe đạp được đặt từ ngày 15 tháng 8 trở đi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We appreciate your understanding in this matter.\", \"vi\": \"Chúng tôi xin chân thành cảm ơn sự thông cảm của quý vị về vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"https://www.consumerreviewsplus.com.my\", \"vi\": \"https://www.consumerreviewsplus.com.my\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Review of Branxley Cycles\", \"vi\": \"Đánh giá về Branxley Cycles\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I have been a cycling enthusiast most of my life.\", \"vi\": \"Suốt phần lớn cuộc đời, tôi luôn là một người đam mê đạp xe.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Recently, I decided I needed a bicycle to bring bulky items home from stores.\", \"vi\": \"Gần đây, tôi nhận thấy mình cần một chiếc xe đạp để chở những món đồ cồng kềnh từ các cửa hàng về nhà.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I searched online and inquired at local shops, but no one had quite what I wanted.\", \"vi\": \"Tôi đã tìm kiếm trên mạng và hỏi thăm tại các cửa hàng trong khu vực, nhưng không nơi nào có đúng thứ tôi cần.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"After talking with a coworker, I learned about Branxley Cycles.\", \"vi\": \"Sau khi trò chuyện với một đồng nghiệp, tôi đã biết đến Branxley Cycles.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I contacted the company via e-mail, and all my questions were answered promptly and thoroughly.\", \"vi\": \"Tôi đã liên hệ với công ty qua email, và tất cả các thắc mắc của tôi đều được giải đáp kịp thời và chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I ordered a three-wheeled cargo bicycle from them on August 20 that was delivered in only two weeks.\", \"vi\": \"Tôi đã đặt mua một chiếc xe đạp chở hàng ba bánh từ công ty này vào ngày 20 tháng 8 và chiếc xe đã được giao chỉ sau hai tuần.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Branxley Cycles cargo bicycles have become very popular with area businesses; I see them everywhere now.\", \"vi\": \"Những chiếc xe đạp chở hàng của Branxley Cycles đã trở nên rất phổ biến trong giới doanh nghiệp tại khu vực này; giờ đây tôi thấy chúng ở khắp mọi nơi.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"It is hard to believe the company can meet the demand, but they manage to do it.\", \"vi\": \"Thật khó tin rằng công ty có thể đáp ứng được nhu cầu, nhưng họ vẫn làm được điều đó.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I am very happy with my Branxley Cycles purchase, and I recommend it to everybody that comments on it as I ride it around town.\", \"vi\": \"Tôi rất hài lòng với chiếc xe đạp Branxley Cycles mà mình đã mua, và tôi xin giới thiệu sản phẩm này đến tất cả những ai có ý kiến về nó mỗi khi tôi đạp xe quanh thành phố.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"—Jason Stewart, September 20\", \"vi\": \"—Jason Stewart, ngày 20 tháng 9\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 24, \"question_numbers\": []}]' WHERE `id` = '6b1f492b-b906-4f8b-b342-d4b21aa48171';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Hien Pham <hpham@ngoc.com>\", \"vi\": \"Gửi tới: Hien Pham <hpham@ngoc.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Theresa Griffin <tgriffin@throngsoftware.com>\", \"vi\": \"Từ: Theresa Griffin <tgriffin@throngsoftware.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: September 20\", \"vi\": \"Ngày: 20 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Pham:\", \"vi\": \"Kính gửi ông Phạm,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Welcome to Throng Software.\", \"vi\": \"Chào mừng quý vị đến với Throng Software.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We are pleased that you are joining the company.\", \"vi\": \"Chúng tôi rất vui mừng chào đón quý vị gia nhập công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"On your first day of work, Monday, October 3, please report to building 14 at 8:45 A.M. You can check in at the front desk, where you will be given a temporary ID badge.\", \"vi\": \"Vào ngày làm việc đầu tiên của quý vị, thứ Hai, ngày 3 tháng 10, xin vui lòng có mặt tại tòa nhà số 14 vào lúc 8 giờ 45 phút sáng. Quý vị có thể làm thủ tục đăng ký tại quầy lễ tân, nơi quý vị sẽ được cấp thẻ nhận dạng tạm thời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I will meet you there, show you to your office, and then take you on a tour of the building to introduce you to your colleagues.\", \"vi\": \"Tôi sẽ đón quý vị tại đó, dẫn quý vị đến văn phòng của mình, sau đó đưa quý vị đi tham quan tòa nhà để giới thiệu quý vị với các đồng nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You will then go to Information Technology (IT) to receive your laptop, passwords, and security information.\", \"vi\": \"Sau đó, quý vị sẽ đến Phòng Công nghệ Thông tin (IT) để nhận máy tính xách tay, mật khẩu và các thông tin bảo mật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"When you are finished, someone will guide you to Human Resources in building 12 so you can fill out payroll and benefits forms.\", \"vi\": \"Khi quý vị hoàn tất thủ tục, sẽ có người hướng dẫn quý vị đến Phòng Nhân sự tại tòa nhà số 12 để quý vị điền vào các mẫu đơn liên quan đến tiền lương và phúc lợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please join me and several colleagues at 11:30 A.M. We will take you to one of our favorite restaurants near the office.\", \"vi\": \"Kính mời quý vị cùng tôi và một số đồng nghiệp vào lúc 11 giờ 30 sáng. Chúng tôi sẽ đưa quý vị đến một trong những nhà hàng yêu thích của chúng tôi gần văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The rest of the afternoon will be free for you to get settled into your office and review the information you receive during the day.\", \"vi\": \"Phần còn lại của buổi chiều, quý vị sẽ có thời gian rảnh để ổn định công việc tại văn phòng và xem lại các thông tin đã nhận được trong ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I will stop by your office later in the day to make sure you know where all the office equipment is.\", \"vi\": \"Chiều nay tôi sẽ ghé qua văn phòng của quý vị để đảm bảo rằng quý vị biết rõ vị trí của tất cả các thiết bị văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I look forward to seeing you then.\", \"vi\": \"Tôi rất mong được gặp quý vị vào lúc đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Theresa Griffin\", \"vi\": \"Theresa Griffin\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Human Resources, Throng Software\", \"vi\": \"Phòng Nhân sự, Throng Software\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '6b295a89-70ba-4195-a7c0-5aa023b3e716';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Maria Zuccarini 5:30 P.M. Hi.\", \"vi\": \"Maria Zuccarini 5 giờ 30 chiều. Xin chào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"This is my first time using the Dubonville community chat room.\", \"vi\": \"Đây là lần đầu tiên tôi sử dụng phòng trò chuyện cộng đồng Dubonville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Do any neighbors have experience laying a ceramic tile floor?\", \"vi\": \"Có ai trong số các vị hàng xóm đã từng có kinh nghiệm lát sàn gạch men chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Yuqiu Wang 5:35 P.M. Hi, Maria.\", \"vi\": \"Yuqiu Wang 5 giờ 35 phút chiều. Xin chào, Maria.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Are you looking to do it yourself?\", \"vi\": \"Quý vị có muốn tự tay thực hiện không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I put in a tile floor in my kitchen last year and did all the work myself.\", \"vi\": \"Năm ngoái, tôi đã lát sàn gạch trong nhà bếp và tự tay thực hiện toàn bộ công việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I regret my decision, though.\", \"vi\": \"Tuy nhiên, tôi rất hối hận về quyết định của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Maria Zuccarini 5:37 P.M. I want to save money, so I\'d rather not hire a professional.\", \"vi\": \"Maria Zuccarini, 5 giờ 37 phút chiều. Tôi muốn tiết kiệm tiền, nên tôi thà không thuê chuyên gia.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"But I\'ve never done a project like this on my own before.\", \"vi\": \"Tuy nhiên, trước đây tôi chưa từng tự mình thực hiện một dự án như thế này bao giờ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Dennis Gurka 5:41 P.M. People who are comfortable with home repairs can lay tile flooring if they watch videos or attend a class.\", \"vi\": \"Dennis Gurka, 5 giờ 41 phút chiều. Những ai đã quen với việc sửa chữa nhà cửa có thể tự lát sàn gạch nếu xem các video hướng dẫn hoặc tham gia một khóa học.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"But it does take effort, time, and precision.\", \"vi\": \"Tuy nhiên, điều này thực sự đòi hỏi sự nỗ lực, thời gian và sự chính xác.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Yuqiu Wang 5:44 P.M. In my case, I had helped a friend with a tiling project prior to working on my own kitchen.\", \"vi\": \"Yuqiu Wang, 5 giờ 44 phút chiều. Riêng tôi, trước khi bắt tay vào lát gạch cho căn bếp của mình, tôi đã từng giúp một người bạn thực hiện một dự án lát gạch.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I also watched several videos on myhomefix.com before getting started.\", \"vi\": \"Trước khi bắt tay vào làm, tôi cũng đã xem một số video trên trang myhomefix.com.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"In the future, I\'d get professional help, though.\", \"vi\": \"Tuy nhiên, trong tương lai, tôi sẽ tìm đến sự trợ giúp của các chuyên gia.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Yuqiu Wang 5:45 P.M. Dennis, do you have experience in this area?\", \"vi\": \"Yuqiu Wang 5 giờ 45 phút chiều. Dennis, ông có kinh nghiệm trong lĩnh vực này không?\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Do you think Maria could tackle this project without a professional?\", \"vi\": \"Quý vị có nghĩ rằng Maria có thể đảm nhận dự án này mà không cần sự hỗ trợ của một chuyên gia không?\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Maria Zuccarini 5:51 P.M. Interesting.\", \"vi\": \"Maria Zuccarini 5 giờ 51 phút chiều. Thật thú vị.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Thanks for sharing your experience.\", \"vi\": \"Xin cảm ơn quý vị đã chia sẻ kinh nghiệm của mình.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Dennis Gurka 5:58 P.M. I have my own flooring business.\", \"vi\": \"Dennis Gurka, 5 giờ 58 phút chiều. Tôi đang kinh doanh lĩnh vực lát sàn.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Whether she can depends on several factors.\", \"vi\": \"Việc cô ấy có thể làm được hay không phụ thuộc vào một số yếu tố.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Maria, will you need to cut the tile, install a drain, or flatten an uneven floor?\", \"vi\": \"Maria ạ, quý vị có cần phải cắt gạch, lắp đặt cống thoát nước hay san phẳng sàn nhà không bằng phẳng không?\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Maria Zuccarini 6:06 P.M. I just need to replace a few broken tiles, but I suspect this is not a job for an amateur.\", \"vi\": \"Maria Zuccarini, 6 giờ 06 phút chiều. Tôi chỉ cần thay một vài viên gạch bị vỡ, nhưng tôi e rằng đây không phải là công việc dành cho người không chuyên.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Dennis, is the business in Dubonville?\", \"vi\": \"Dennis ạ, công ty đó có trụ sở tại Dubonville không ạ?\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Could you send me your contact information?\", \"vi\": \"Xin quý vị vui lòng gửi cho tôi thông tin liên lạc của quý vị được không?\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Dennis Gurka 6:07 P.M. It\'s just outside the city limits.\", \"vi\": \"Dennis Gurka, 6 giờ 07 phút chiều. Nơi này nằm ngay bên ngoài ranh giới thành phố.\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"It\'s called Floors Forever.\", \"vi\": \"Tên của nó là “Floors Forever”.\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"The phone is 642-555-0143.\", \"vi\": \"Số điện thoại là 642-555-0143.\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '6b6c9390-1679-47f5-a01f-4a558e10e625';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Takeshi Ishiguro\", \"vi\": \"Từ: Takeshi Ishiguro\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All Sevastya employees\", \"vi\": \"Kính gửi: Toàn thể nhân viên công ty Sevastya\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Update\", \"vi\": \"Chủ đề: Cập nhật\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: December 13\", \"vi\": \"Ngày: 13 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Sevastya employees,\", \"vi\": \"Kính gửi quý nhân viên Sevastya,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am writing to give you an update on this year\'s sales so far.\", \"vi\": \"Tôi viết thư này để cập nhật cho quý vị về tình hình doanh số bán hàng từ đầu năm đến nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I am happy to report that currently our sales volume is up 20% from last year.\", \"vi\": \"Tôi vui mừng thông báo rằng hiện tại, khối lượng bán hàng của chúng tôi đã tăng 20% so với năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This is due in part to the fact that we have been very successful in expanding our international reach.\", \"vi\": \"Điều này một phần là do chúng tôi đã đạt được nhiều thành công trong việc mở rộng phạm vi hoạt động quốc tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"In Brazil, sales increased 57%, which can be attributed to the Rio de Janeiro Fashion Show where our evening wear was featured.\", \"vi\": \"Tại Brazil, doanh số bán hàng đã tăng 57%, điều này có thể được cho là nhờ Tuần lễ Thời trang Rio de Janeiro, nơi các mẫu trang phục dạ hội của chúng tôi đã được giới thiệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"A similar trend emerged in Russia, where sales were up by 32%.\", \"vi\": \"Một xu hướng tương tự cũng đã xuất hiện tại Nga, nơi doanh số bán hàng tăng 32%.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"There we anticipate sustained growth for the rest of the year, especially in our winter apparel line.\", \"vi\": \"Tại mảng này, chúng tôi dự báo sẽ duy trì đà tăng trưởng trong phần còn lại của năm, đặc biệt là đối với dòng sản phẩm quần áo mùa đông của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We also saw sales growth in the United Arab Emirates (UAE), but growth was a modest 10% due to fierce competition.\", \"vi\": \"Chúng tôi cũng ghi nhận sự tăng trưởng về doanh số tại Các Tiểu vương quốc Ả Rập Thống nhất (UAE), tuy nhiên mức tăng trưởng này chỉ ở mức khiêm tốn 10% do sự cạnh tranh gay gắt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"That said, in this market, sign-ups for our credit card were strong.\", \"vi\": \"Dù vậy, trên thị trường này, số lượng khách hàng đăng ký thẻ tín dụng của chúng tôi vẫn rất khả quan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Finally, in Korea, where we have had our most successful international market launch thus far, favorable news articles about our products drove very strong sales.\", \"vi\": \"Cuối cùng, tại Hàn Quốc – nơi chúng tôi đã có đợt ra mắt thị trường quốc tế thành công nhất từ trước đến nay – các bài báo tích cực về sản phẩm của chúng tôi đã thúc đẩy doanh số bán hàng tăng rất mạnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thus, overall, it\'s been an excellent year so far.\", \"vi\": \"Như vậy, nhìn chung, cho đến nay đây là một năm rất thành công.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I am confident that our new program, which offers discounts to customers who invite others to shop with us, will begin to boost sales growth at all locations.\", \"vi\": \"Tôi tin tưởng rằng chương trình mới của chúng tôi, với chính sách giảm giá dành cho những khách hàng giới thiệu người khác đến mua sắm tại cửa hàng, sẽ bắt đầu thúc đẩy tăng trưởng doanh số tại tất cả các chi nhánh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Takeshi Ishiguro\", \"vi\": \"Takeshi Ishiguro\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Vice President of Sales\", \"vi\": \"Phó Tổng giám đốc phụ trách kinh doanh\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '6b88899b-49fa-4453-a8f0-b1bb65ed8066';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: jliu@lle.com\", \"vi\": \"Đến: jliu@lle.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: customersupport@gerdenbank.com\", \"vi\": \"Từ: customersupport@gerdenbank.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Service Fee\", \"vi\": \"Chủ đề: Phí dịch vụ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 27 May, 10:34 Α.Μ.\", \"vi\": \"Ngày: 27 tháng 5, 10:34 sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Liu,\", \"vi\": \"Kính gửi bà Liu,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"____143____ an error in our internal computer processing system, a service fee was incorrectly deducted from your savings account on 23 May.\", \"vi\": \"____143____ một lỗi trong hệ thống xử lý máy tính nội bộ của chúng tôi, một khoản phí dịch vụ đã bị trừ nhầm khỏi tài khoản tiết kiệm của quý khách vào ngày 23 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [143]}, {\"en\": \"This error has been fixed, and a refund was posted to your account on 25 May.\", \"vi\": \"Lỗi này đã được khắc phục và một khoản hoàn tiền đã được chuyển vào tài khoản của quý khách vào ngày 25 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You ___144____ this deposit on your next statement under the description \\\"Fee adjustment.\\\"\", \"vi\": \"Quý khách ___144____ khoản tiền gửi này trong bảng sao kê tiếp theo với phần mô tả \\\"Điều chỉnh phí.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [144]}, {\"en\": \"We apologize if this has resulted in any ___145____ .\", \"vi\": \"Chúng tôi thành thật xin lỗi nếu sự việc này gây ra bất kỳ ___145____ nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [145]}, {\"en\": \"Please contact us if you have any concerns regarding this issue.\", \"vi\": \"Vui lòng liên hệ với chúng tôi nếu quý khách có bất kỳ bận tâm nào liên quan đến vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"___146____ .\", \"vi\": \"___146____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [146]}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Jennifer Ayers\", \"vi\": \"Jennifer Ayers\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Customer Support\", \"vi\": \"Bộ phận Hỗ trợ Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Gerden Bank\", \"vi\": \"Ngân hàng Gerden\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '6ba6265e-10e0-4d0a-9d2c-8cc6786832b9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Jang-Ho Kwon <jkwon@newart.nz>\", \"vi\": \"Đến: Jang-Ho Kwon <jkwon@newart.nz>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Kenneth Okim <k.okim@okimjewelry.nz>\", \"vi\": \"Từ: Kenneth Okim <k.okim@okimjewelry.nz>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Good news\", \"vi\": \"Chủ đề: Tin vui\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 30 August\", \"vi\": \"Ngày: 30 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Jang-Ho,\", \"vi\": \"Jang-Ho thân mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for the shipment last month of 80 units of your jewelry pieces.\", \"vi\": \"Cảm ơn lô hàng gồm 80 sản phẩm trang sức của bạn vào tháng trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am happy to report that they have been selling very well in my shop.\", \"vi\": \"Tôi rất vui khi thông báo rằng chúng đang bán rất chạy tại cửa hàng của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"My _____143_____ love the colourful designs as well as the quality of your workmanship.\", \"vi\": \"_____143_____ của tôi rất thích các thiết kế đầy màu sắc cũng như chất lượng chế tác của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [143]}, {\"en\": \"_____144_____ .\", \"vi\": \"_____144_____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [144]}, {\"en\": \"I would like to increase the number of units I order from you.\", \"vi\": \"Tôi muốn tăng số lượng sản phẩm đặt hàng từ bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Would you be able to _____145_____ my order for the September shipment?\", \"vi\": \"Bạn có thể _____145_____ đơn hàng của tôi cho đợt giao hàng vào tháng 9 không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [145]}, {\"en\": \"Finally, I would like to discuss the possibility of featuring your work exclusively in my store.\", \"vi\": \"Cuối cùng, tôi muốn thảo luận về khả năng trưng bày độc quyền các tác phẩm của bạn tại cửa hàng của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I believe that I could reach your target audience best and that the agreement would serve _____146_____ both very well.\", \"vi\": \"Tôi tin rằng tôi có thể tiếp cận đối tượng mục tiêu của bạn tốt nhất và thỏa thuận này sẽ mang lại lợi ích cho cả hai chúng ta _____146_____.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [146]}, {\"en\": \"I look forward to hearing from you.\", \"vi\": \"Tôi mong sớm nhận được phản hồi từ bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Kenneth Okim\", \"vi\": \"Kenneth Okim\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Okim Jewelry\", \"vi\": \"Okim Jewelry\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '6c002f5b-30c1-4503-9671-da1aeb50ee66';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: hhollander@helensplace.com\", \"vi\": \"Gửi tới: hhollander@helensplace.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: customerservice@eaterysource.com\", \"vi\": \"Nguồn: customerservice@eaterysource.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: January 16\", \"vi\": \"Ngày: 16 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Order confirmation\", \"vi\": \"Chủ đề: Xác nhận đơn hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Hollander:\", \"vi\": \"Kính gửi bà Hollander:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for shopping with us!\", \"vi\": \"Xin chân thành cảm ơn quý khách đã mua sắm tại cửa hàng của chúng tôi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This e-mail confirms that we have received your order from eaterysource.com.\", \"vi\": \"Thư điện tử này xác nhận rằng chúng tôi đã nhận được đơn đặt hàng của quý khách từ eaterysource.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We are proud to be an international supplier of equipment to restaurants worldwide.\", \"vi\": \"Chúng tôi tự hào là nhà cung cấp thiết bị quốc tế cho các nhà hàng trên toàn thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Your order is currently being processed.\", \"vi\": \"Đơn hàng của quý khách hiện đang được xử lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Orders are typically processed and sent out to our warehouses within two business days.\", \"vi\": \"Các đơn hàng thường được xử lý và chuyển đến các kho hàng của chúng tôi trong vòng hai ngày làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Our staff will then begin to prepare your order for shipping.\", \"vi\": \"Sau đó, đội ngũ nhân viên của chúng tôi sẽ bắt đầu chuẩn bị đơn hàng của quý khách để giao hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You will receive another e-mail once your order has shipped, updating you with its current tracking information.\", \"vi\": \"Khi đơn hàng của quý khách đã được gửi đi, quý khách sẽ nhận được một email khác để cập nhật thông tin theo dõi hiện tại của đơn hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you for your business.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã tin tưởng và sử dụng dịch vụ của chúng tôi.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The Eatery Source Team\", \"vi\": \"Đội ngũ Eatery Source\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Order Number: #19998056\", \"vi\": \"Số đơn hàng: #19998056\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Order Date: January 16\", \"vi\": \"Ngày đặt hàng: 16 tháng 1\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '6c01d864-8551-4789-85f6-fb38ee56f96f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Parsons Road Distribution List\", \"vi\": \"Gửi tới: Danh sách phân phối Parsons Road\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Alfredo Moreno\", \"vi\": \"Từ: Alfredo Moreno\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: October 12\", \"vi\": \"Ngày: 12 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Parsons Road\", \"vi\": \"Chủ đề: Đường Parsons\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Parsons Road Businesses:\", \"vi\": \"Kính gửi các doanh nghiệp trên đường Parsons:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Beginning in March, Parsons Road will be widened between Memorial Boulevard and Hallam Road.\", \"vi\": \"Bắt đầu từ tháng 3, đường Parsons sẽ được mở rộng trên đoạn từ đại lộ Memorial đến đường Hallam.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The project will add a center turn lane, bicycle paths, pedestrian paths, and streetlights.\", \"vi\": \"Dự án sẽ bổ sung một làn đường rẽ giữa, các làn đường dành cho xe đạp, lối đi dành cho người đi bộ và đèn đường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In addition, a side gutter will be added to improve water flow.\", \"vi\": \"Ngoài ra, một máng xối bên hông sẽ được lắp đặt để cải thiện lưu lượng nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The Parsons Road project ties into work completed between Hallam Road and Ingraham Avenue earlier this year.\", \"vi\": \"Dự án đường Parsons Road nối tiếp các công trình đã hoàn thành trên đoạn từ đường Hallam Road đến đại lộ Ingraham vào đầu năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"This work will improve access to your businesses and increase pedestrian safety on Parsons Road, which can be quite busy.\", \"vi\": \"Công trình này sẽ giúp cải thiện khả năng tiếp cận các cơ sở kinh doanh của quý vị và tăng cường an toàn cho người đi bộ trên đường Parsons, nơi thường có lưu lượng giao thông khá đông đúc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The roadwork is expected to take three months to complete.\", \"vi\": \"Dự kiến công trình sửa chữa đường sẽ mất ba tháng để hoàn thành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Please visit www.yorkcity.gov/parsonsroadproject for more information.\", \"vi\": \"Vui lòng truy cập trang web www.yorkcity.gov/parsonsroadproject để biết thêm thông tin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Alfredo Moreno\", \"vi\": \"Alfredo Moreno\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Community Relations Manager\", \"vi\": \"Trưởng phòng Quan hệ Cộng đồng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Bethany Construction and Engineering\", \"vi\": \"Công ty Xây dựng và Kỹ thuật Bethany\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '6c726eba-a730-44a1-b814-a9cbbc9b2d9e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"FOR IMMEDIATE RELEASE\", \"vi\": \"THÔNG CÁO BÁO CHÍ NGAY LẬP TỨC\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Contact: Lily Kwan, lkwan@itamitheater.com\", \"vi\": \"Liên hệ: Lily Kwan, lkwan@itamitheater.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"SEATTLE (April 10)—Following the recent announcement that Artistic Director Lucas Freeland has stepped down, the Itami Theater Board of Directors has appointed Xu Li as the interim artistic director.\", \"vi\": \"SEATTLE (ngày 10 tháng 4) — Sau thông báo gần đây về việc Giám đốc nghệ thuật Lucas Freeland đã từ chức, Hội đồng Quản trị Nhà hát Itami đã bổ nhiệm ông Xu Li làm Giám đốc nghệ thuật lâm thời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Ms. Li has been at Itami for ten years, serving as director of new play development.\", \"vi\": \"Bà Li đã công tác tại Itami được mười năm, đảm nhiệm chức vụ giám đốc phụ trách phát triển vở kịch mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Ms. Li has been pivotal in Itami\'s artistic direction.\", \"vi\": \"Bà Li đã đóng vai trò then chốt trong định hướng nghệ thuật của Itami.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"She will continue to guide the play selection for next season.\", \"vi\": \"Bà sẽ tiếp tục chỉ đạo công tác lựa chọn vở diễn cho mùa diễn tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"I am honored that the board trusts me to carry forward the work that the entire team at Itami Theater has established,\\\" said Ms. Li.\", \"vi\": \"\\\"Tôi rất vinh dự khi Hội đồng quản trị tin tưởng giao cho tôi nhiệm vụ tiếp tục phát huy những thành quả mà toàn thể đội ngũ tại Nhà hát Itami đã gầy dựng nên,\\\" bà Li phát biểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"\\\"I am excited to work with our dedicated staff, everyone from stagehands to costume designers, to build a thrilling season next year.\\\"\", \"vi\": \"\\\"Tôi rất hào hứng được hợp tác cùng đội ngũ nhân viên tận tụy của chúng tôi, từ các nhân viên hậu trường cho đến các nhà thiết kế trang phục, để cùng xây dựng một mùa diễn đầy hấp dẫn vào năm tới.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"In addition to overseeing the development of new plays for the theater, Ms. Li is a director.\", \"vi\": \"Bên cạnh việc giám sát quá trình phát triển các vở kịch mới cho nhà hát, bà Li còn là một đạo diễn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Later this season, she will direct Forest Creatures, written by the award-winning playwright May Nunes.\", \"vi\": \"Vào cuối mùa diễn này, bà sẽ đảm nhận vai trò đạo diễn vở kịch *Forest Creatures*, do nhà viết kịch từng đoạt giải thưởng May Nunes chắp bút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"\\\"Ms. Li is a wise choice to serve as Itami\'s interim artistic director,\\\" says Executive Director John Stojanowski.\", \"vi\": \"“Bà Li là một sự lựa chọn sáng suốt cho vị trí Giám đốc nghệ thuật lâm thời của Itami,” ông John Stojanowski, Giám đốc Điều hành, phát biểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"\\\"Her deep theatrical knowledge will help Itami Theater continue its artistic endeavors after the departure of Mr. Freeland and during the search for a permanent artistic director.\\\"\", \"vi\": \"\\\"Kiến thức sâu rộng về nghệ thuật sân khấu của bà sẽ giúp Nhà hát Itami tiếp tục các hoạt động nghệ thuật sau khi ông Freeland rời đi và trong thời gian tìm kiếm một giám đốc nghệ thuật chính thức.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The board of directors is committed to taking its time in its search for a permanent artistic director.\", \"vi\": \"Hội đồng quản trị cam kết sẽ dành thời gian cần thiết để tiến hành quá trình tuyển chọn giám đốc nghệ thuật chính thức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The board is pursuing candidates from across the country and expects the hiring process to take six to nine months.\", \"vi\": \"Hội đồng quản trị đang tìm kiếm các ứng viên trên khắp cả nước và dự kiến quá trình tuyển dụng sẽ kéo dài từ sáu đến chín tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '6c7edc5e-797a-4c06-825f-7f4a0f3365a0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Maria Jacinto [10:24 A.M.]:\", \"vi\": \"Maria Jacinto [10:24 sáng]:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Good morning, everyone.\", \"vi\": \"Xin chào buổi sáng, thưa quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I want to welcome Aika Okura to the chat.\", \"vi\": \"Tôi xin chào mừng cô Aika Okura tham gia cuộc trò chuyện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Aika Okura [10:24 A.M.]:\", \"vi\": \"Gửi Okura [10 giờ 24 phút sáng]:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hi!\", \"vi\": \"Xin chào!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I\'m glad that my bookstore is able to cosponsor the writers\' conference this year.\", \"vi\": \"Tôi rất vui vì hiệu sách của tôi có thể đồng tổ chức hội nghị các nhà văn năm nay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It is a great new opportunity for us.\", \"vi\": \"Đây là một cơ hội mới tuyệt vời dành cho chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Maria Jacinto [10:25 A.M.]:\", \"vi\": \"Maria Jacinto [10 giờ 25 phút sáng]:\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We are, too.\", \"vi\": \"Chúng tôi cũng vậy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We have expanded the conference to two days, so the additional sponsorship is a huge help.\", \"vi\": \"Chúng tôi đã kéo dài thời gian diễn ra hội nghị lên hai ngày, do đó, khoản tài trợ bổ sung này thực sự là một sự hỗ trợ to lớn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"A larger conference means more sessions and additional hotel arrangements.\", \"vi\": \"Một hội nghị quy mô lớn hơn đồng nghĩa với việc sẽ có nhiều phiên họp hơn và cần phải sắp xếp thêm chỗ ở tại khách sạn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Arthur Rufo [10:26 A.M.]:\", \"vi\": \"Arthur Rufo [10 giờ 26 phút sáng]:\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Speaking of the hotels...\", \"vi\": \"Nói đến các khách sạn thì...\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The Rowtown Hotel was great last year, but it is booked for the dates we need this time around.\", \"vi\": \"Khách sạn Rowtown năm ngoái rất tuyệt, nhưng hiện tại các ngày chúng tôi cần lần này đã được đặt kín rồi.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The Fairmount at Clark has availability for October 17 and 18, though.\", \"vi\": \"Tuy nhiên, khách sạn Fairmount at Clark vẫn còn phòng trống vào ngày 17 và 18 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"It might be better since they have a larger meeting space and more options for the buffet.\", \"vi\": \"Có lẽ nơi đó sẽ phù hợp hơn vì họ có không gian hội nghị rộng rãi hơn và nhiều lựa chọn hơn cho tiệc tự chọn.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Maria Jacinto [10:28 A.M.]:\", \"vi\": \"Maria Jacinto [10 giờ 28 phút sáng]:\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"That sounds good.\", \"vi\": \"Nghe có vẻ hay đấy.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Can you send us the pricing details?\", \"vi\": \"Quý vị có thể gửi cho chúng tôi chi tiết về giá cả được không?\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Arthur Rufo [10:29 A.M.]:\", \"vi\": \"Arthur Rufo [10 giờ 29 phút sáng]:\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"They can offer a special room rate for conference attendees, too.\", \"vi\": \"Họ cũng có thể áp dụng mức giá phòng ưu đãi dành riêng cho những người tham dự hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"As soon as I have the details, I\'ll e-mail everyone.\", \"vi\": \"Ngay khi có thông tin chi tiết, tôi sẽ gửi email cho tất cả quý vị.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Maria Jacinto [10:30 A.M.]:\", \"vi\": \"Maria Jacinto [10 giờ 30 phút sáng]:\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Great.\", \"vi\": \"Tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"How are we doing with the keynote speaker?\", \"vi\": \"Việc mời diễn giả chính hiện đang tiến triển như thế nào?\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Aika Okura [10:31 A.M.]:\", \"vi\": \"Gửi Okura [10 giờ 31 phút sáng]:\", \"type\": \"metadata\", \"doc_index\": 7, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Delara Lette has tentatively agreed.\", \"vi\": \"Bà Delara Lette đã đồng ý sơ bộ.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Arthur Rufo [10:32 A.M.]:\", \"vi\": \"Arthur Rufo [10 giờ 32 phút sáng]:\", \"type\": \"metadata\", \"doc_index\": 8, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Oh.\", \"vi\": \"Ồ.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I loved her latest mystery!\", \"vi\": \"Tôi rất thích cuốn tiểu thuyết trinh thám mới nhất của bà ấy!\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I can see why it became a best seller so quickly.\", \"vi\": \"Tôi có thể hiểu tại sao cuốn sách này lại nhanh chóng trở thành cuốn sách bán chạy nhất như vậy.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Aika Okura [10:33 A.M.]:\", \"vi\": \"Gửi Okura [10 giờ 33 phút sáng]:\", \"type\": \"metadata\", \"doc_index\": 9, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Yes, she\'s great, and I\'ve heard she\'s also a wonderful speaker.\", \"vi\": \"Vâng, cô ấy thật tuyệt vời, và tôi nghe nói cô ấy còn là một diễn giả xuất sắc nữa.\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"She has another engagement in October in London, and she wants to make certain she can do both events.\", \"vi\": \"Cô ấy còn có một sự kiện khác vào tháng 10 tại London, và cô ấy muốn đảm bảo rằng mình có thể tham dự cả hai sự kiện này.\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"She will confirm by the end of the week.\", \"vi\": \"Cô ấy sẽ xác nhận vào cuối tuần này.\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Maria Jacinto [10:34 A.M.]:\", \"vi\": \"Maria Jacinto [10 giờ 34 phút sáng]:\", \"type\": \"metadata\", \"doc_index\": 10, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"It sounds like things are coming together.\", \"vi\": \"Có vẻ như mọi việc đang dần đi vào quỹ đạo.\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"I\'ll check in again on Friday.\", \"vi\": \"Tôi sẽ liên hệ lại vào thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 39, \"question_numbers\": []}]' WHERE `id` = '6ca71094-c647-4ae7-83ef-64c5576c13e9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Rudolf Crowley\", \"vi\": \"Đến: Rudolf Crowley\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Dafina Ndashe\", \"vi\": \"Từ: Dafina Ndashe\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Decision on proposal\", \"vi\": \"Chủ đề: Quyết định về bản đề xuất\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 12 August\", \"vi\": \"Ngày: 12 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Crowley:\", \"vi\": \"Ông Crowley thân mến:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am pleased to inform you that at the Tuesday night meeting the city council approved your proposal to build an inn at 17 Dickinson Street.\", \"vi\": \"Tôi rất vui được thông báo với ông rằng tại cuộc họp tối thứ Ba, hội đồng thành phố đã phê duyệt đề xuất xây dựng một quán trọ tại số 17 phố Dickinson của ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"You ---143--- a formal letter of approval this week.\", \"vi\": \"Ông sẽ ---143--- một thư phê duyệt chính thức trong tuần này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [143]}, {\"en\": \"---144---.\", \"vi\": \"---144---.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [144]}, {\"en\": \"Specifically, they were concerned about noise and on-street parking.\", \"vi\": \"Cụ thể, họ lo ngại về tiếng ồn và việc đỗ xe trên đường phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"However, your ---145--- that the inn would only serve breakfast to guests and would not have a restaurant open to the general public helped to persuade them.\", \"vi\": \"Tuy nhiên, việc ---145--- của ông rằng quán trọ sẽ chỉ phục vụ bữa sáng cho khách và sẽ không có nhà hàng mở cửa cho công chúng nói chung đã giúp thuyết phục họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [145]}, {\"en\": \"---146---, they were pleased that the small parking area is tucked into the back of the property, so curbside parking along the street should not be affected.\", \"vi\": \"---146---, họ hài lòng rằng khu vực đỗ xe nhỏ được bố trí ở phía sau khuôn viên, vì vậy việc đỗ xe sát lề dọc theo đường phố sẽ không bị ảnh hưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [146]}, {\"en\": \"Please let me know if you have any questions.\", \"vi\": \"Vui lòng cho tôi biết nếu ông có bất kỳ câu hỏi nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sincerely, Dafina Ndashe, Clerk, Millview City Council\", \"vi\": \"Trân trọng, Dafina Ndashe, Thư ký, Hội đồng Thành phố Millview\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '6cef81ff-d29b-4f99-9bbe-3c15b5ae3348';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Alexandria\'s Restaurant Showcase\", \"vi\": \"Triển lãm các nhà hàng tại Alexandria\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"June 5 — Alexandria\'s Restaurant Showcase is back!\", \"vi\": \"Ngày 5 tháng 6 — Sự kiện Trình diễn Ẩm thực Alexandria đã trở lại!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From July 8 to July 25, participating restaurants in the Alexandria area will offer set menus at discounted prices.\", \"vi\": \"Từ ngày 8 tháng 7 đến ngày 25 tháng 7, các nhà hàng tham gia chương trình tại khu vực Alexandria sẽ phục vụ các thực đơn cố định với mức giá ưu đãi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"As in past years, restaurants can offer a two-course lunch menu for $15, a two-course dinner menu for $20, or a three-course dinner menu for $30.\", \"vi\": \"Cũng như những năm trước, các nhà hàng có thể phục vụ thực đơn bữa trưa gồm hai món với giá 15 đô la, thực đơn bữa tối gồm hai món với giá 20 đô la, hoặc thực đơn bữa tối gồm ba món với giá 30 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Both customers and restaurant owners love the showcase.\", \"vi\": \"Cả khách hàng lẫn chủ nhà hàng đều rất ưa chuộng tủ trưng bày này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Food enthusiasts try new options at a lower cost, and restaurants report it\'s the time of year when dining areas are at their fullest.\", \"vi\": \"Những người đam mê ẩm thực có cơ hội thử những món ăn mới với chi phí thấp hơn, và các nhà hàng cho biết đây là thời điểm trong năm mà các khu vực ăn uống luôn chật kín khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Alexandria had its first restaurant showcase 15 years ago.\", \"vi\": \"Cách đây 15 năm, thành phố Alexandria đã tổ chức sự kiện giới thiệu các nhà hàng lần đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It was modeled on a similar showcase in the beach town of Willmar.\", \"vi\": \"Dự án này được lấy cảm hứng từ một mô hình trưng bày tương tự tại thị trấn ven biển Willmar.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Originally, only eight restaurants participated.\", \"vi\": \"Ban đầu, chỉ có tám nhà hàng tham gia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Since then, the showcase has grown, adding more restaurants and extending the number of days each year.\", \"vi\": \"Kể từ đó, sự kiện này đã ngày càng phát triển, thu hút thêm nhiều nhà hàng tham gia và kéo dài thời gian tổ chức mỗi năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"This year, there will be 40 participating restaurants—about 70 percent of all the restaurants in Alexandria.\", \"vi\": \"Năm nay, sẽ có 40 nhà hàng tham gia — chiếm khoảng 70 phần trăm tổng số nhà hàng tại Alexandria.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Those looking to book a table should act fast.\", \"vi\": \"Những ai có ý định đặt bàn nên nhanh tay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Some restaurants require reservations, and the most popular places book up quickly.\", \"vi\": \"Một số nhà hàng yêu cầu đặt chỗ trước, và những địa điểm nổi tiếng nhất thường hết chỗ rất nhanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To see the list of participating restaurants and make a reservation, visit www.alexandriarestaurants.com/showcase.\", \"vi\": \"Để xem danh sách các nhà hàng tham gia chương trình và đặt chỗ, vui lòng truy cập trang web www.alexandriarestaurants.com/showcase.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"https://www.alexandriarestaurants.com/showcase/reservations\", \"vi\": \"https://www.alexandriarestaurants.com/showcase/reservations\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Showing search results for: Center City Neighborhood\", \"vi\": \"Hiển thị kết quả tìm kiếm cho: Khu dân cư Center City\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Claire\'s\", \"vi\": \"Claire\'s\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"French food\", \"vi\": \"Ẩm thực Pháp\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Serving lunch and 3-course dinner\", \"vi\": \"Phục vụ bữa trưa và bữa tối gồm 3 món\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Open Tuesday–Sunday\", \"vi\": \"Mở cửa từ Thứ Ba đến Chủ Nhật\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Call (703) 555-0102 to make a reservation.\", \"vi\": \"Vui lòng gọi số (703) 555-0102 để đặt chỗ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Fresh Fish Grill\", \"vi\": \"Nhà hàng Cá Tươi Nướng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Seafood\", \"vi\": \"Hải sản\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Serving lunch and 3-course dinner\", \"vi\": \"Phục vụ bữa trưa và bữa tối gồm 3 món\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Open Monday–Sunday\", \"vi\": \"Mở cửa từ Thứ Hai đến Chủ Nhật\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Call (703) 555-0195 to make a reservation.\", \"vi\": \"Vui lòng gọi số (703) 555-0195 để đặt chỗ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Jin-Yi\'s House\", \"vi\": \"Ngôi nhà của Jin-Yi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Korean food\", \"vi\": \"Ẩm thực Hàn Quốc\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Serving 2-course dinner\", \"vi\": \"Bữa tối gồm 2 món\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Open Wednesday–Saturday\", \"vi\": \"Mở cửa từ Thứ Tư đến Thứ Bảy\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Call (703) 555-0198 to make a reservation.\", \"vi\": \"Vui lòng gọi số (703) 555-0198 để đặt chỗ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Roberto\'s Pizzeria\", \"vi\": \"Quán pizza Roberto\'s\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Italian food\", \"vi\": \"Ẩm thực Ý\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Serving lunch only\", \"vi\": \"Chỉ phục vụ bữa trưa\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Open Tuesday–Sunday\", \"vi\": \"Mở cửa từ thứ Ba đến Chủ Nhật\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"No reservations necessary\", \"vi\": \"Không cần đặt chỗ trước\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"https://www.foodreviews.com/alexandria/freshfishgrill\", \"vi\": \"https://www.foodreviews.com/alexandria/freshfishgrill\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Nori Sato\", \"vi\": \"Nori Sato\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"I highly recommend Fresh Fish Grill.\", \"vi\": \"Tôi xin nhiệt liệt giới thiệu nhà hàng Fresh Fish Grill.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"It was my first time eating there, and not only was the food excellent, but the staff was welcoming and efficient.\", \"vi\": \"Đây là lần đầu tiên tôi dùng bữa tại đó, và không chỉ món ăn rất ngon mà đội ngũ nhân viên còn rất thân thiện và làm việc hiệu quả.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"I had some clients in town and was lucky enough to get a reservation on the last day of the restaurant showcase.\", \"vi\": \"Tôi có một số khách hàng đến thăm thành phố và may mắn được đặt chỗ vào ngày cuối cùng của sự kiện giới thiệu các nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"We all really enjoyed the experience.\", \"vi\": \"Tất cả chúng tôi đều thực sự rất thích trải nghiệm này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"I would gladly take clients there again.\", \"vi\": \"Tôi rất sẵn lòng đưa khách hàng đến đó một lần nữa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}]' WHERE `id` = '6cf7c775-a6f5-453a-8eaa-144ee0361fc2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Luke Orlan [8:30 A.M.]\", \"vi\": \"Luke Orlan [8 giờ 30 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Good morning, everyone.\", \"vi\": \"Xin chào buổi sáng, thưa quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I would like an update on the grand opening at the Carter Street Mall.\", \"vi\": \"Tôi mong được cập nhật thông tin về lễ khai trương tại Trung tâm thương mại Carter Street.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Pamela Cooke [8:31 A.M.]\", \"vi\": \"Pamela Cooke [8 giờ 31 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The opening went well.\", \"vi\": \"Buổi khai mạc đã diễn ra suôn sẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The shops and restaurants got a lot of pedestrian traffic and the customers seemed happy.\", \"vi\": \"Các cửa hàng và nhà hàng đón nhận lượng khách đi bộ rất đông, và các vị khách trông có vẻ hài lòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We are still compiling the customer-satisfaction surveys.\", \"vi\": \"Chúng tôi hiện vẫn đang tổng hợp các bản khảo sát mức độ hài lòng của khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The Red Moon Restaurant was popular.\", \"vi\": \"Nhà hàng Red Moon rất được ưa chuộng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Luke Orlan [8:32 A.M.]\", \"vi\": \"Luke Orlan [8 giờ 32 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please send me that data once you have it.\", \"vi\": \"Xin vui lòng gửi cho tôi dữ liệu đó ngay khi quý vị có được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Anything else I need to know?\", \"vi\": \"Còn điều gì khác mà tôi cần biết không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Alena Santiago [8:33 A.M.]\", \"vi\": \"Alena Santiago [8 giờ 33 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Well, there were some issues with the parking area during the grand opening.\", \"vi\": \"Thực ra, đã xảy ra một số vấn đề liên quan đến khu vực đỗ xe trong buổi lễ khai trương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The lighting did not work right.\", \"vi\": \"Hệ thống chiếu sáng không hoạt động đúng cách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"It didn\'t function as it should have when it got dark.\", \"vi\": \"Khi trời tối, thiết bị này đã không hoạt động như mong đợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Luke Orlan [8:34 A.M.]\", \"vi\": \"Luke Orlan [8 giờ 34 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Oh?\", \"vi\": \"Ồ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Alena Santiago [8:34 A.M.]\", \"vi\": \"Alena Santiago [8 giờ 34 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We discovered that a timer was not set correctly.\", \"vi\": \"Chúng tôi phát hiện ra rằng bộ hẹn giờ đã không được cài đặt chính xác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Luke Orlan [8:35 A.M.]\", \"vi\": \"Luke Orlan [8 giờ 35 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I\'m glad that was easily resolved.\", \"vi\": \"Tôi rất vui vì vấn đề đó đã được giải quyết một cách dễ dàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"What about maintenance in general?\", \"vi\": \"Vậy còn vấn đề bảo trì nói chung thì sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Marcus Afolayan [8:35 A.M.]\", \"vi\": \"Marcus Afolayan [8 giờ 35 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"We want to make sure that management works closely with the Maintenance Department.\", \"vi\": \"Chúng tôi mong muốn đảm bảo rằng ban lãnh đạo sẽ phối hợp chặt chẽ với Phòng Bảo trì.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"We have staff on-site for routine housekeeping, and we have outside contractors taking care of the landscaping and maintenance of the escalators.\", \"vi\": \"Chúng tôi có đội ngũ nhân viên làm việc tại chỗ để đảm nhận các công việc dọn dẹp thường xuyên, đồng thời có các nhà thầu bên ngoài phụ trách công tác chăm sóc cảnh quan và bảo trì thang cuốn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Luke Orlan [8:36 A.M.]\", \"vi\": \"Luke Orlan [8 giờ 36 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Everything seems to be running smoothly.\", \"vi\": \"Mọi việc dường như đang diễn ra suôn sẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Let\'s continue these online meetings weekly.\", \"vi\": \"Chúng ta hãy tiếp tục tổ chức các cuộc họp trực tuyến này hàng tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I hope to travel there in February to see everything firsthand.\", \"vi\": \"Tôi hy vọng sẽ có dịp đến đó vào tháng Hai để tận mắt chiêm ngưỡng mọi thứ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Thanks.\", \"vi\": \"Cảm ơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 30, \"question_numbers\": []}]' WHERE `id` = '6d02b15f-3f34-4a1e-920c-865cd43f2941';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Blendora Coffee\", \"vi\": \"Cà phê Blendora\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Item 16: Creamy Vanilla Blendelicious\", \"vi\": \"Mục 16: Kem vani Blendelicious\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Steps\", \"vi\": \"Các bước\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"1.\", \"vi\": \"1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Pour espresso: Use dark roast or decaf.\", \"vi\": \"Để pha cà phê espresso: Hãy sử dụng cà phê rang đậm hoặc cà phê không chứa caffeine.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"For small drinks, add 1 shot.\", \"vi\": \"Đối với các loại đồ uống có dung tích nhỏ, hãy thêm 1 shot.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"For medium drinks, add 2 shots.\", \"vi\": \"Đối với các loại đồ uống cỡ trung bình, xin vui lòng thêm 2 shot.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"For large drinks, add 3 shots.\", \"vi\": \"Đối với các ly đồ uống cỡ lớn, hãy thêm 3 shot.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"2.\", \"vi\": \"2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Pour milk: For regular drinks, use whole milk.\", \"vi\": \"Đổ sữa: Đối với các loại đồ uống thông thường, hãy sử dụng sữa nguyên kem.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"When customers request a light drink, use nonfat milk.\", \"vi\": \"Khi khách hàng yêu cầu một thức uống ít béo, xin vui lòng sử dụng sữa tách béo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"3.\", \"vi\": \"3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Add flavor: Use vanilla powder.\", \"vi\": \"Tăng hương vị: Hãy sử dụng bột vani.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"For small drinks, add 2 scoops.\", \"vi\": \"Đối với các loại đồ uống có dung tích nhỏ, xin vui lòng cho vào 2 muỗng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"For medium drinks, add 3 scoops.\", \"vi\": \"Đối với các loại đồ uống cỡ trung bình, hãy cho vào 3 muỗng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"For large drinks, add 4 scoops.\", \"vi\": \"Đối với các loại đồ uống có dung tích lớn, xin vui lòng thêm 4 muỗng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"4.\", \"vi\": \"4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Add ice: Use the markings on the ice scoop for small, medium, and large drinks.\", \"vi\": \"Cho đá vào: Hãy tham khảo các vạch chia trên muỗng múc đá để định lượng cho các loại đồ uống cỡ nhỏ, vừa và lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"5.\", \"vi\": \"5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Blend: Press the orange button on the blender.\", \"vi\": \"Xay: Nhấn nút màu cam trên máy xay sinh tố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"The texture should be creamy.\", \"vi\": \"Kết cấu phải mịn màng như kem.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"6.\", \"vi\": \"6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Finish and serve: Pour into a plastic cup.\", \"vi\": \"Hoàn tất và dọn ra: Đổ vào cốc nhựa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"For regular drinks, top with whipped cream and use a domed lid.\", \"vi\": \"Đối với các loại đồ uống thông thường, quý vị nên trang trí bằng kem tươi và đậy nắp vòm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"For light drinks, do not top with whipped cream and use a flat lid.\", \"vi\": \"Đối với các loại đồ uống nhẹ, xin vui lòng không phủ kem tươi lên trên và hãy sử dụng nắp phẳng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"7.\", \"vi\": \"7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Clean up: Rinse blender cover and metal blender cup.\", \"vi\": \"Vệ sinh: Rửa sạch nắp máy xay và cốc xay bằng kim loại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Wipe the counter.\", \"vi\": \"Hãy lau sạch mặt bàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Blendora Coffee Barista Training\", \"vi\": \"Khóa đào tạo Barista của Blendora Coffee\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Trainee: Matt Molinelli\", \"vi\": \"Thực tập sinh: Matt Molinelli\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Trainer: Kuniko Osawa\", \"vi\": \"Huấn luyện viên: Kuniko Osawa\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Date: June 17\", \"vi\": \"Ngày: 17 tháng 6\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Drink: Creamy Vanilla Blendelicious (Light)\", \"vi\": \"Thức uống: Creamy Vanilla Blendelicious (Loại nhẹ)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Size: ☐ Small ☑ Medium ☐ Large\", \"vi\": \"Kích cỡ: ☐ Nhỏ ☑ Trung bình ☐ Lớn\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Rate the quality of the finished beverage.\", \"vi\": \"Hãy đánh giá chất lượng của thức uống sau khi hoàn thành.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"☐ Perfect ☐ Very Good ☑ Good ☐ Acceptable ☐ Unacceptable\", \"vi\": \"☐ Hoàn hảo ☐ Rất tốt ☑ Tốt ☐ Chấp nhận được ☐ Không chấp nhận được\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"What errors did the trainee make?\", \"vi\": \"Học viên đã mắc những sai lầm nào?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Mr. Molinelli measured correctly for a medium beverage, and he used nonfat milk.\", \"vi\": \"Ông Molinelli đã đo đúng lượng cho một ly đồ uống cỡ trung bình và sử dụng sữa tách béo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"However, he did everything else according to the regular recipe, not the light one.\", \"vi\": \"Tuy nhiên, ông đã thực hiện tất cả các bước còn lại theo công thức thông thường, chứ không phải công thức ít calo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Comments: Mr. Molinelli was adept at using his hands, and he kept a smile on his face.\", \"vi\": \"Nhận xét: Ông Molinelli rất khéo léo trong việc sử dụng đôi tay và luôn nở nụ cười trên môi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Once he memorizes the recipes, he will be an excellent barista.\", \"vi\": \"Một khi anh ấy đã thuộc lòng các công thức pha chế, anh ấy sẽ trở thành một barista xuất sắc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 41, \"question_numbers\": []}]' WHERE `id` = '6d104f20-8e79-43e1-94f2-284f84fc303c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Urban Family Camping\", \"vi\": \"Cắm trại gia đình thành phố\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.ncgovparks.org/ufc\", \"vi\": \"http://www.ncgovparks.org/ufc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The Nieves City Parks Department organizes urban family camping events so that local children can experience the fun of camping ______[131] in their own city.\", \"vi\": \"Sở Công viên Thành phố Nieves tổ chức các sự kiện cắm trại gia đình trong thành phố để trẻ em địa phương có thể trải nghiệm niềm vui cắm trại ______[131] ngay tại thành phố của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [131]}, {\"en\": \"At each campout, park rangers host a limited number of families for an overnight stay in one of Nieves\'s beautiful parks.\", \"vi\": \"Tại mỗi buổi cắm trại, các kiểm lâm viên sẽ đón tiếp một số lượng gia đình có hạn để lưu trú qua đêm tại một trong những công viên đẹp của Nieves.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"There is also usually an extra activity, such as a barbecue dinner, a ranger-led evening hike, or a session of storytelling around the campfire.\", \"vi\": \"Ngoài ra, thường có thêm một hoạt động phụ, chẳng hạn như bữa tối tiệc nướng BBQ, chuyến đi bộ buổi tối do kiểm lâm hướng dẫn, hoặc một buổi kể chuyện quanh đống lửa trại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"To make participation widely accessible, the Parks Department even provides the tents and most other necessary items.\", \"vi\": \"Để tạo điều kiện cho mọi người tham gia rộng rãi, Sở Công viên thậm chí còn cung cấp lều và hầu hết các vật dụng cần thiết khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[132].\", \"vi\": \"______[132].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [132]}, {\"en\": \"The urban family camping ______[133] is extremely popular.\", \"vi\": \"Chương trình cắm trại gia đình thành phố ______[133] cực kỳ phổ biến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [133]}, {\"en\": \"______[134] families are advised to sign up for their desired campout as soon as registration opens each spring.\", \"vi\": \"______[134] các gia đình được khuyên nên đăng ký chuyến cắm trại mong muốn ngay khi cổng đăng ký mở vào mỗi mùa xuân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [134]}]' WHERE `id` = '6d2b8313-6382-466b-a440-ecf136f85368';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Corporate Resource Team\", \"vi\": \"Kính gửi: Nhóm Nguồn lực Doanh nghiệp\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Junko Shigeno, Team Lead\", \"vi\": \"Từ: Junko Shigeno, Trưởng nhóm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: January 27\", \"vi\": \"Ngày: 27 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Support issues\", \"vi\": \"Chủ đề: Các vấn đề liên quan đến hỗ trợ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hi, Team,\", \"vi\": \"Xin chào, các thành viên trong nhóm,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"At next week\'s strategy session, we will address the specific needs of our company representatives working at our new overseas retail locations.\", \"vi\": \"Tại cuộc họp chiến lược vào tuần tới, chúng tôi sẽ thảo luận về những nhu cầu cụ thể của các đại diện công ty đang làm việc tại các điểm bán lẻ mới ở nước ngoài của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our goal is to have each employee fully trained in marketing our products and in client retention.\", \"vi\": \"Mục tiêu của chúng tôi là đảm bảo mỗi nhân viên đều được đào tạo đầy đủ về việc tiếp thị sản phẩm và duy trì mối quan hệ với khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I\'m requesting that each of you be ready to present two ideas on the best way to provide them with training and logistical support at levels comparable to their domestic counterparts.\", \"vi\": \"Tôi xin đề nghị mỗi quý vị hãy chuẩn bị trình bày hai ý tưởng về cách thức tốt nhất để cung cấp cho họ các khóa đào tạo và hỗ trợ hậu cần ở mức độ tương đương với các đồng nghiệp trong nước của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Junko Shigeno\", \"vi\": \"Junko Shigeno\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Team Lead, Integra Optics\", \"vi\": \"Trưởng nhóm, Integra Optics\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '6d33e062-4ad2-4f0f-b98e-4fc88cf9d38d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Local Museum Goes Interactive\", \"vi\": \"Bảo tàng địa phương chuyển sang hình thức tương tác\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"DERRY (April 7)—The Regional History Museum (RHM) has upgraded many of its exhibits to include interactive technologies.\", \"vi\": \"DERRY (ngày 7 tháng 4) — Bảo tàng Lịch sử Khu vực (RHM) đã nâng cấp nhiều hiện vật trưng bày của mình để tích hợp các công nghệ tương tác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The enhanced exhibitions opened on Monday, one week before the scheduled completion date.\", \"vi\": \"Các triển lãm được nâng cấp đã khai mạc vào thứ Hai, một tuần trước ngày hoàn thành theo kế hoạch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The museum remained open during the installation, although some offerings were unavailable during the process of upgrading.\", \"vi\": \"Bảo tàng vẫn mở cửa trong suốt quá trình lắp đặt, mặc dù một số dịch vụ không thể cung cấp trong thời gian nâng cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The enhancements were funded by Arnsby Metal Manufacturing, a major industrial firm in the area.\", \"vi\": \"Các hạng mục nâng cấp này được tài trợ bởi Arnsby Metal Manufacturing, một tập đoàn công nghiệp lớn trong khu vực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"According to RHM director Ann Wert, interactive technology allows exhibits to present information and engage users through various audio and visual media.\", \"vi\": \"Theo bà Ann Wert, Giám đốc RHM, công nghệ tương tác cho phép các triển lãm trình bày thông tin và thu hút người tham quan thông qua các phương tiện nghe nhìn đa dạng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"“Visitors can now learn the region’s history in an immersive way,” said Ms. Wert.\", \"vi\": \"“Giờ đây, du khách có thể tìm hiểu lịch sử của khu vực này một cách sinh động,” bà Wert cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The director’s persistent efforts helped to determine the priorities for the project.\", \"vi\": \"Những nỗ lực không ngừng nghỉ của vị giám đốc đã góp phần xác định các ưu tiên cho dự án.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"“Every week in the museum lobby, I interview patrons and record their opinions,” said Ms. Wert.\", \"vi\": \"“Hàng tuần, tại sảnh bảo tàng, tôi tiến hành phỏng vấn các khách tham quan và ghi lại ý kiến của họ,” bà Wert cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"“The changes reflect their wishes and ideas.”\", \"vi\": \"“Những thay đổi này phản ánh mong muốn và ý tưởng của họ.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The improved RHM exhibits also give the user control over the experience.\", \"vi\": \"Các phiên bản RHM được cải tiến này còn cho phép người dùng chủ động điều khiển trải nghiệm của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"A touchscreen allows visitors to communicate electronically with an exhibit’s unique database and target their interests.\", \"vi\": \"Màn hình cảm ứng cho phép khách tham quan tương tác điện tử với cơ sở dữ liệu riêng của từng triển lãm và tìm kiếm các nội dung phù hợp với sở thích của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The museum now features 26 interactive exhibits that play audio narratives and informative videos.\", \"vi\": \"Hiện nay, bảo tàng trưng bày 26 hiện vật tương tác, trong đó có các bản ghi âm kể chuyện và các video giới thiệu thông tin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Ms. Wert suggests that guests stroll around the city’s adjoining heritage district and admire its vintage architecture after they visit the museum.\", \"vi\": \"Bà Wert gợi ý rằng sau khi tham quan bảo tàng, quý khách nên dạo bước quanh khu di sản liền kề của thành phố và chiêm ngưỡng kiến trúc cổ kính nơi đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Guide maps of the district are available in the museum’s lobby.\", \"vi\": \"Các bản đồ hướng dẫn về quận này được bày sẵn tại sảnh của bảo tàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '6d7fd88b-9d82-4275-a872-a36a3c05fc11';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Leasing Opportunities\", \"vi\": \"Các cơ hội cho thuê\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"La Gardina Mall offers a unique shopping experience in a beautiful setting of landscaped gardens, courtyards, and fountains.\", \"vi\": \"Trung tâm thương mại La Gardina mang đến trải nghiệm mua sắm độc đáo trong khung cảnh tuyệt đẹp với những khu vườn được thiết kế công phu, các sân trong và đài phun nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The mall features retail shops that range from well-known chain stores to one-of-a-kind boutiques, as well as a large variety of restaurants and cafés.\", \"vi\": \"Trung tâm thương mại này quy tụ các cửa hàng bán lẻ, từ những chuỗi cửa hàng nổi tiếng đến các cửa hàng thời trang độc đáo, bên cạnh đó còn có rất nhiều nhà hàng và quán cà phê đa dạng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"With 300,000 square meters of pedestrian-only retail space, La Gardina Mall attracts more than four million visitors per year.\", \"vi\": \"Với diện tích khu vực bán lẻ dành riêng cho người đi bộ lên tới 300.000 mét vuông, Trung tâm thương mại La Gardina thu hút hơn bốn triệu lượt khách mỗi năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"It is a shopping and dining destination for local Bay Shore residents and tourists alike.\", \"vi\": \"Đây là điểm đến mua sắm và ẩm thực dành cho cả cư dân địa phương tại Bay Shore lẫn du khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"If you would like more information about leasing retail or restaurant space at La Gardina, please contact Cecilia Goncalves, our Leasing Administrator, at cgoncalves@lagardina.com.\", \"vi\": \"Nếu quý vị muốn biết thêm thông tin về việc thuê mặt bằng bán lẻ hoặc nhà hàng tại La Gardina, vui lòng liên hệ với bà Cecilia Goncalves, Chuyên viên Quản lý Cho thuê của chúng tôi, qua địa chỉ email cgoncalves@lagardina.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"While most of our space is occupied by long-term lessees, a limited number of seasonal contracts (four months minimum) are available.\", \"vi\": \"Mặc dù phần lớn diện tích của chúng tôi đã được các khách thuê dài hạn chiếm dụng, nhưng vẫn còn một số lượng hạn chế các hợp đồng thuê theo mùa (thời hạn tối thiểu bốn tháng) đang sẵn có.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To: Cecilia Goncalves <cgoncalves@lagardina.com>\", \"vi\": \"Gửi tới: Cecilia Goncalves <cgoncalves@lagardina.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"From: Marco Sabatini <msabatini@sabatinileather.com>\", \"vi\": \"Từ: Marco Sabatini <msabatini@sabatinileather.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Date: 25 March\", \"vi\": \"Ngày: 25 tháng 3\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Subject: Retail space\", \"vi\": \"Chủ đề: Diện tích mặt bằng bán lẻ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 List of products\", \"vi\": \"Tệp đính kèm: 📎 Danh sách sản phẩm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Dear Ms. Goncalves:\", \"vi\": \"Kính gửi Bà Goncalves:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"As owner of Sabatini Leather Goods, I would like to express interest in a short-term leasing opportunity at La Gardina Mall.\", \"vi\": \"Với tư cách là chủ sở hữu của Sabatini Leather Goods, tôi xin bày tỏ sự quan tâm đến cơ hội thuê mặt bằng ngắn hạn tại Trung tâm thương mại La Gardina.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sabatini Leather Goods is a small company that manufactures and sells souvenir handbags and wallets.\", \"vi\": \"Sabatini Leather Goods là một công ty quy mô nhỏ chuyên sản xuất và kinh doanh túi xách và ví làm quà lưu niệm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Our high-quality leather products are imprinted with the name of the tourist destination where they are sold.\", \"vi\": \"Các sản phẩm da chất lượng cao của chúng tôi đều được in nổi tên của điểm du lịch nơi chúng được bày bán.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I have attached some images of our best-selling items from our most recent temporary shop in Glastonbury, where we had our best sales performance in the company\'s history.\", \"vi\": \"Tôi xin đính kèm một số hình ảnh về các mặt hàng bán chạy nhất tại cửa hàng tạm thời gần đây nhất của chúng tôi ở Glastonbury, nơi chúng tôi đã đạt được kết quả kinh doanh tốt nhất trong lịch sử công ty.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We have sold our products in 24 different locations so far, all with great success.\", \"vi\": \"Cho đến nay, chúng tôi đã bán sản phẩm của mình tại 24 địa điểm khác nhau, và tất cả đều gặt hái được thành công rực rỡ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We have been looking for a place in Bay Shore for a while, and La Gardina Mall seems to be a good fit.\", \"vi\": \"Chúng tôi đã tìm kiếm một địa điểm tại Bay Shore được một thời gian, và Trung tâm thương mại La Gardina dường như là một lựa chọn phù hợp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"We would like a space of about 150 square meters for a three-month period over the summer tourism season.\", \"vi\": \"Chúng tôi mong muốn thuê một không gian rộng khoảng 150 mét vuông trong thời gian ba tháng vào mùa du lịch hè.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Could you please call me at 555-0125 so that we can discuss this matter further?\", \"vi\": \"Xin quý vị vui lòng gọi cho tôi theo số 555-0125 để chúng ta có thể thảo luận thêm về vấn đề này được không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Respectfully,\", \"vi\": \"Kính gửi,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Marco Sabatini\", \"vi\": \"Marco Sabatini\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '6da2a889-3f46-406c-82bd-e4ee246d4861';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Anton Grier\", \"vi\": \"Từ: Anton Grier\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Lindsay Pickard\", \"vi\": \"Đến: Lindsay Pickard\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 29\", \"vi\": \"Ngày: 29 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Thank you note\", \"vi\": \"Chủ đề: Thư cảm ơn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hello Lindsay,\", \"vi\": \"Lindsay thân mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I just wanted to reach out and express my appreciation for your department\'s help with the search for my executive assistant.\", \"vi\": \"Tôi muốn liên hệ và bày tỏ sự đánh giá cao đối với sự giúp đỡ của bộ phận bạn trong quá trình tìm kiếm trợ lý điều hành của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"While everyone I interacted with did fine work, I especially want to single out Karl Schmidt for making an invaluable contribution to the process.\", \"vi\": \"Mặc dù tất cả những người tôi tiếp xúc đều làm việc rất tốt, tôi đặc biệt muốn tuyên dương Karl Schmidt vì đã đóng góp vô giá vào quá trình này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"______[135], he discovered a specialized job board for administrative professionals.\", \"vi\": \"______[135], anh ấy đã tìm ra một trang tuyển dụng chuyên biệt dành cho các chuyên gia hành chính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [135]}, {\"en\": \"Without that ______[136] I wouldn\'t have had so many great candidates to choose from.\", \"vi\": \"Nếu không có ______[136] đó, tôi đã không có nhiều ứng viên xuất sắc để lựa chọn như vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [136]}, {\"en\": \"As this was my first time hiring someone here at Carylon Health, I wasn\'t sure what ______[137] from the process, but I certainly couldn\'t have imagined that it would be so simple and collaborative.\", \"vi\": \"Vì đây là lần đầu tiên tôi tuyển dụng nhân sự tại Carylon Health, tôi không chắc chắn điều gì ______[137] từ quy trình này, nhưng tôi chắc chắn không thể tưởng tượng rằng nó lại đơn giản và mang tính hợp tác cao đến vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [137]}, {\"en\": \"You have put together an excellent team.\", \"vi\": \"Bạn đã xây dựng được một đội ngũ tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"______[138].\", \"vi\": \"______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [138]}, {\"en\": \"I hope you will pass on my thanks to everyone.\", \"vi\": \"Tôi hy vọng bạn sẽ chuyển lời cảm ơn của tôi đến tất cả mọi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Anton Grier\", \"vi\": \"Anton Grier\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Vice President of Digital Healthcare Innovations\", \"vi\": \"Phó Chủ tịch phụ trách Đổi mới Y tế Kỹ thuật số\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Carylon Health\", \"vi\": \"Carylon Health\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '6ddf8f9d-b55e-4b93-881c-508c2fc8a3d1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Eva Linn, Lundtalk Industries\", \"vi\": \"Đến: Eva Linn, Công ty Lundtalk Industries\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Technical Services\", \"vi\": \"Từ: Bộ phận Dịch vụ Kỹ thuật\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: January 15\", \"vi\": \"Ngày: Ngày 15 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Technical query\", \"vi\": \"Chủ đề: Thắc mắc kỹ thuật\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Linn,\", \"vi\": \"Kính gửi bà Linn,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for contacting our technical department ______[135] your query.\", \"vi\": \"Cảm ơn bà đã liên hệ với bộ phận kỹ thuật của chúng tôi ______[135] thắc mắc của bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [135]}, {\"en\": \"______[136], our call got disconnected when we were trying to reboot your system from our remote location.\", \"vi\": \"______[136], cuộc gọi của chúng tôi đã bị ngắt kết nối khi chúng tôi đang cố gắng khởi động lại hệ thống của bà từ xa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [136]}, {\"en\": \"______[137].\", \"vi\": \"______[137].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [137]}, {\"en\": \"Therefore, please call us at your earliest convenience and refer to conversation ID #TECH12-2020A to complete the system repair.\", \"vi\": \"Do đó, vui lòng gọi cho chúng tôi vào thời gian sớm nhất có thể và đề cập đến mã số hội thoại #TECH12-2020A để hoàn tất việc sửa chữa hệ thống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We have prioritized your inquiry and look forward to helping you ______[138] your computer to its full capabilities.\", \"vi\": \"Chúng tôi đã ưu tiên thắc mắc của bà và rất mong được giúp bà ______[138] máy tính của bà hoạt động hết công suất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [138]}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Arthur Feldt\", \"vi\": \"Arthur Feldt\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Technical Service Facilitator\", \"vi\": \"Điều phối viên Dịch vụ Kỹ thuật\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '6e00ed5e-d439-427d-8836-5552ef34f9b4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Eston Development Worth a Look\", \"vi\": \"Dự án Eston Development rất đáng để quý vị quan tâm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"by Marcus Watanabe\", \"vi\": \"của Marcus Watanabe\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"“Ideal residential developments combine twenty-first-century convenience with small-town charm.”\", \"vi\": \"“Các dự án nhà ở lý tưởng là sự kết hợp giữa sự tiện nghi của thế kỷ XXI với nét duyên dáng của một thị trấn nhỏ.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"That is the philosophy found in the brochure of the Homestead at Eston, a recently completed housing development just outside the town of Eston.\", \"vi\": \"Đó chính là triết lý được nêu trong tập tài liệu giới thiệu về dự án Homestead at Eston, một khu dân cư vừa mới hoàn thành nằm ngay ngoại ô thị trấn Eston.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The community has wide streets, sidewalks, and three small parks surrounding a central square.\", \"vi\": \"Khu dân cư này có những con đường rộng rãi, vỉa hè và ba công viên nhỏ bao quanh một quảng trường trung tâm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The square features a café, a restaurant, and several shops.\", \"vi\": \"Quảng trường này có một quán cà phê, một nhà hàng và một số cửa hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In the northeast corner of the development, there is an activity complex that includes a gym, theater, and swimming pool.\", \"vi\": \"Tại góc đông bắc của khu đô thị, có một khu phức hợp giải trí bao gồm phòng tập thể dục, rạp hát và bể bơi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"“This means you never have to leave the community unless you want to,” said Marjorie Solomon, sales director.\", \"vi\": \"“Điều này có nghĩa là quý vị sẽ không bao giờ phải rời khỏi cộng đồng trừ khi quý vị muốn,” bà Marjorie Solomon, Giám đốc kinh doanh, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"“Once you visit, you’ll realize why so many people are purchasing homes here.”\", \"vi\": \"“Chỉ cần quý vị đến thăm một lần, quý vị sẽ hiểu tại sao lại có rất nhiều người chọn mua nhà tại đây.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"While never leaving your development struck me as an odd idea, the Homestead planners deserve praise for creating a very attractive place to live.\", \"vi\": \"Mặc dù việc không bao giờ rời khỏi khu dân cư của quý vị khiến tôi cảm thấy đó là một ý tưởng kỳ lạ, nhưng các nhà quy hoạch của Homestead xứng đáng được khen ngợi vì đã tạo ra một nơi sinh sống vô cùng hấp dẫn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The planners have obviously prioritized the environment.\", \"vi\": \"Rõ ràng là các nhà quy hoạch đã đặt vấn đề môi trường lên hàng đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Natural habitats have been carefully preserved, and homes and other structures have been designed to conserve water and energy.\", \"vi\": \"Các môi trường sống tự nhiên đã được bảo tồn một cách cẩn trọng, đồng thời các ngôi nhà và công trình khác cũng được thiết kế nhằm tiết kiệm nước và năng lượng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Model homes are currently available for tours.\", \"vi\": \"Hiện tại, quý vị có thể tham quan các căn nhà mẫu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Open houses take place 12:30–4:00 P.M. Saturdays and Sundays.\", \"vi\": \"Các buổi mở cửa chào đón khách tham quan diễn ra từ 12 giờ 30 đến 4 giờ chiều vào các ngày thứ Bảy và Chủ Nhật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Alternatively, appointments can be made by calling 856-555-0129.\", \"vi\": \"Ngoài ra, quý vị cũng có thể đặt lịch hẹn bằng cách gọi đến số 856-555-0129.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '6e10ae26-5471-4503-9bec-1b918bcbf1ab';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Wayne Rental Available\", \"vi\": \"Có dịch vụ cho thuê tại Wayne\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"A sparkling two-bedroom, one-bath apartment is available in the village of Wayne, fifteen miles from the center of Bowling Green.\", \"vi\": \"Một căn hộ hai phòng ngủ, một phòng tắm với không gian sáng sủa và thoáng đãng hiện đang được rao bán tại làng Wayne, cách trung tâm thành phố Bowling Green mười lăm dặm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Situated in a mid-rise building that is ten years old, the apartment is convenient to shops and cafés and within walking distance of the train station.\", \"vi\": \"Nằm trong một tòa nhà trung tầng đã được xây dựng cách đây mười năm, căn hộ này nằm gần các cửa hàng và quán cà phê, đồng thời chỉ cách ga tàu hỏa một quãng đường đi bộ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The oven and dishwasher have just been replaced, and a fresh tile countertop has been installed in the kitchen.\", \"vi\": \"Lò nướng và máy rửa chén vừa được thay mới, đồng thời mặt bàn bếp bằng gạch men mới cũng đã được lắp đặt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"A new washer and dryer set is next to the pantry.\", \"vi\": \"Bộ máy giặt và máy sấy mới được đặt ngay bên cạnh phòng chứa thực phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The monthly rent is $950, including utilities.\", \"vi\": \"Tiền thuê hàng tháng là 950 đô la, đã bao gồm các khoản phí tiện ích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Sign a one-year lease and you can move in as early as August 1.\", \"vi\": \"Hãy ký hợp đồng thuê nhà có thời hạn một năm và quý vị có thể dọn vào ở sớm nhất là vào ngày 1 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Call (419) 555-0145 to arrange a tour.\", \"vi\": \"Vui lòng gọi số (419) 555-0145 để đặt lịch tham quan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '6e23e627-6a4a-43d8-b539-9ef32e6b4cdb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Kolkata XYZ Bamboo Tableware\", \"vi\": \"Bộ đồ dùng ăn uống bằng tre XYZ tại Kolkata\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"For over 15 years, Kolkata XYZ has used bamboo grown right here in West Bengal to make plates, cups, utensils, and other dining necessities.\", \"vi\": \"Trong hơn 15 năm qua, công ty Kolkata XYZ đã sử dụng tre được trồng ngay tại bang Tây Bengal để sản xuất đĩa, cốc, dụng cụ ăn uống và các vật dụng cần thiết khác cho bữa ăn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Read on to learn just a few of the many beneficial characteristics of bamboo tableware.\", \"vi\": \"Hãy tiếp tục đọc để tìm hiểu một vài trong số rất nhiều đặc tính hữu ích của bộ đồ ăn bằng tre.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Sustainable – Bamboo is very environmentally friendly.\", \"vi\": \"Bền vững – Tre là một vật liệu rất thân thiện với môi trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Bamboo plants are a renewable resource, and when your bamboo tableware is no longer useable, it can be recycled or composted.\", \"vi\": \"Cây tre là một nguồn tài nguyên tái tạo, và khi bộ đồ dùng ăn uống bằng tre của quý vị không còn sử dụng được nữa, chúng có thể được tái chế hoặc ủ làm phân hữu cơ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Chemical-Free – Bamboo plants require no pesticides to grow, and the manufacturing process for our tableware involves heat and pressure, not artificial chemicals.\", \"vi\": \"Không chứa hóa chất – Cây tre không cần sử dụng thuốc trừ sâu để phát triển, và quy trình sản xuất bộ đồ ăn của chúng tôi sử dụng nhiệt và áp suất, chứ không sử dụng hóa chất nhân tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Durable – Bamboo tableware is difficult to break and, though some care must be taken, it can be heated in the microwave, stored in the freezer, and washed in the dishwasher without damage.\", \"vi\": \"Bền bỉ – Đồ dùng ăn uống bằng tre rất khó vỡ và, mặc dù cần chú ý một chút, nhưng vẫn có thể hâm nóng trong lò vi sóng, bảo quản trong tủ đông và rửa trong máy rửa chén mà không bị hư hỏng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Lightweight – Bamboo is lighter than most tableware materials, making it an excellent choice for families with young children.\", \"vi\": \"Nhẹ – Tre nhẹ hơn hầu hết các chất liệu làm đồ dùng ăn uống, do đó đây là lựa chọn tuyệt vời dành cho các gia đình có trẻ nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This also means that our products are very affordable to ship.\", \"vi\": \"Điều này cũng có nghĩa là chi phí vận chuyển các sản phẩm của chúng tôi rất hợp lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Versatile Style – Bamboo’s neutral wood tones, which we highlight in simple, clean shapes, serve as an elegant complement to a wide range of color and design schemes.\", \"vi\": \"Phong cách đa năng – Tông màu gỗ trung tính của tre, được chúng tôi làm nổi bật qua những đường nét đơn giản và gọn gàng, trở thành điểm nhấn thanh lịch, hài hòa với đa dạng các gam màu và phong cách thiết kế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"◀▶\", \"vi\": \"◀▶\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"http://www.kolkataxyz.in/bambootableware\", \"vi\": \"http://www.kolkataxyz.in/bambootableware\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"≡\", \"vi\": \"≡\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To: Deepa Sanyal\", \"vi\": \"Kính gửi: Deepa Sanyal\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"From: Sikha Lahiri\", \"vi\": \"Từ: Sikha Lahiri\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Date: 7 October\", \"vi\": \"Ngày: 7 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Subject: Bamboo utensils\", \"vi\": \"Chủ đề: Đồ dùng bằng tre\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Dear Ms. Sanyal,\", \"vi\": \"Kính gửi bà Sanyal,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"It was a pleasure to speak with you at last week’s trade show.\", \"vi\": \"Thật là một niềm vui được trò chuyện với quý vị tại triển lãm thương mại tuần trước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I found your points about the environmental advantages of your company’s bamboo tableware very persuasive.\", \"vi\": \"Tôi thấy những lập luận của quý vị về những lợi ích môi trường của bộ đồ dùng ăn uống bằng tre do công ty quý vị sản xuất rất thuyết phục.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"So, I have decided that your travel utensil set will make an excellent thank-you gift for the Gir Society’s donors, who care deeply about the Earth.\", \"vi\": \"Vì vậy, tôi đã quyết định rằng bộ dụng cụ ăn uống du lịch của quý công ty sẽ là một món quà tri ân tuyệt vời dành cho các nhà tài trợ của Hiệp hội Gir, những người luôn dành sự quan tâm sâu sắc đến Trái Đất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"You mentioned that there are several options for the set’s carrying case.\", \"vi\": \"Quý vị đã đề cập rằng có một số lựa chọn về hộp đựng cho bộ sản phẩm này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Could you provide me with details about them?\", \"vi\": \"Xin quý vị có thể cung cấp cho tôi thông tin chi tiết về những điều đó được không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I am particularly interested in comparing their prices (as I prefer an affordable option) and finding the one that causes the least damage to our planet.\", \"vi\": \"Tôi đặc biệt quan tâm đến việc so sánh giá cả của các sản phẩm này (vì tôi ưu tiên lựa chọn có giá cả phải chăng) và tìm ra sản phẩm gây tác động tiêu cực ít nhất đến hành tinh của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Sikha Lahiri\", \"vi\": \"Sikha Lahiri\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"The Gir Society\", \"vi\": \"Hội Gir\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"To: Sikha Lahiri\", \"vi\": \"Kính gửi: Sikha Lahiri\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"From: Deepa Sanyal\", \"vi\": \"Từ: Deepa Sanyal\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Date: 8 October\", \"vi\": \"Ngày: 8 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Subject: Re: Bamboo utensils\", \"vi\": \"Chủ đề: Trả lời: Đồ dùng bằng tre\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Case - Unit price - Environmental harm\", \"vi\": \"Trường hợp - Giá đơn vị - Tác hại đối với môi trường\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Hard plastic case with snap-lock closure - $1.45 - High\", \"vi\": \"Hộp nhựa cứng có nắp đóng bằng chốt bấm - 1,45 USD - Chất lượng cao\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Cotton pouch with snap buttons - $1.70 - Low\", \"vi\": \"Túi vải bông có nút bấm - 1,70 USD - Giá rẻ\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Nylon zippered case - $2.10 - Medium\", \"vi\": \"Túi đựng bằng nylon có khóa kéo - 2,10 USD - Cỡ trung bình\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Canvas roll-up bag with tie straps - $2.95 - Low\", \"vi\": \"Túi vải canvas cuộn có dây buộc - 2,95 USD - Giá thấp\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Dear Ms. Lahiri,\", \"vi\": \"Kính gửi bà Lahiri,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Thank you for your e-mail.\", \"vi\": \"Xin cảm ơn quý vị đã gửi email.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Below is a comparison of the available types of carrying cases for the travel utensil set.\", \"vi\": \"Dưới đây là bảng so sánh các loại túi đựng hiện có dành cho bộ đồ dùng ăn uống du lịch.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Please note that a minimum order of 50 units is required.\", \"vi\": \"Xin lưu ý rằng quý khách phải đặt hàng tối thiểu 50 đơn vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Also, whichever type of case you choose, we would be happy to add your organization’s logo and some lettering, such as a thank-you message to your donors, though this will involve an additional fee.\", \"vi\": \"Ngoài ra, bất kể quý vị chọn loại hộp đựng nào, chúng tôi cũng rất hân hạnh được in logo của tổ chức quý vị cùng một số dòng chữ, chẳng hạn như lời cảm ơn gửi đến các nhà tài trợ, mặc dù việc này sẽ phát sinh một khoản phí bổ sung.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"I hope to hear from you again soon.\", \"vi\": \"Tôi hy vọng sẽ sớm nhận được tin từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Deepa Sanyal\", \"vi\": \"Deepa Sanyal\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"Kolkata XYZ\", \"vi\": \"Kolkata XYZ\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}]' WHERE `id` = '6e2e42c9-e950-43f4-bb5e-373b3816113e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Naomi Richter <naomirichter@mailcurrent.com>\", \"vi\": \"Đến: Naomi Richter <naomirichter@mailcurrent.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Watanu Sakamoto <wsakamoto@RHNimports.com>\", \"vi\": \"Từ: Watanu Sakamoto <wsakamoto@RHNimports.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 23 November\", \"vi\": \"Ngày: 23 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Follow-up\", \"vi\": \"Chủ đề: Thư trao đổi tiếp theo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Logistics coordinator description\", \"vi\": \"Tệp đính kèm: Mô tả công việc điều phối viên hậu cần\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Richter,\", \"vi\": \"Kính gửi bà Richter,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for coming to our office to interview for the assistant import manager position last week.\", \"vi\": \"Cảm ơn bà đã đến văn phòng của chúng tôi để phỏng vấn cho vị trí trợ lý quản lý nhập khẩu vào tuần trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We were impressed with your credentials and enthusiasm.\", \"vi\": \"Chúng tôi rất ấn tượng với năng lực và sự nhiệt huyết của bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"___131___ we are moving ahead with another candidate, we would like to offer you a different position that just became available: logistics coordinator.\", \"vi\": \"___131___ chúng tôi đang tiếp tục tiến trình tuyển dụng với một ứng viên khác, chúng tôi muốn đề xuất cho bà một vị trí khác vừa mới trống: điều phối viên hậu cần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [131]}, {\"en\": \"___132___.\", \"vi\": \"___132___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [132]}, {\"en\": \"The attached document contains the detailed job description and pay rate.\", \"vi\": \"Tài liệu đính kèm bao gồm mô tả công việc chi tiết và mức lương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"This ___133___ has not yet been posted publicly.\", \"vi\": \"Vị trí này ___133___ vẫn chưa được đăng tuyển công khai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [133]}, {\"en\": \"If you are ___134___, please let me know by the end of this week.\", \"vi\": \"Nếu bà ___134___, vui lòng cho tôi biết trước cuối tuần này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [134]}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Watanu Sakamoto\", \"vi\": \"Watanu Sakamoto\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Human Resource Manager, RHN Imports\", \"vi\": \"Trưởng phòng Nhân sự, RHN Imports\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '6e49d0ad-2ee0-453d-af9b-bc563a4516ac';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Managers\", \"vi\": \"Đến: Tất cả các Trưởng phòng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Bert Pizarro\", \"vi\": \"Từ: Bert Pizarro\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: October 10\", \"vi\": \"Ngày: 10 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Staff banquet\", \"vi\": \"Chủ đề: Tiệc chiêu đãi nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Managers,\", \"vi\": \"Kính gửi các Trưởng phòng,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"December is quickly approaching, and the Human Resources team is working out the details for this year\'s staff banquet.\", \"vi\": \"Tháng Mười Hai đang đến rất nhanh, và đội ngũ Nhân sự đang hoàn thiện các chi tiết cho buổi tiệc chiêu đãi nhân viên của năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As you know, this ______[143] event is an opportunity for us to thank our entire staff for their service and to reflect on the past twelve months.\", \"vi\": \"Như bạn đã biết, sự kiện ______[143] này là cơ hội để chúng ta cảm ơn toàn thể nhân viên vì sự cống hiến của họ và nhìn lại mười hai tháng qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [143]}, {\"en\": \"In addition, it will provide everyone with the opportunity ______[144] time with their colleagues in a relaxed social setting.\", \"vi\": \"Ngoài ra, nó sẽ mang lại cho mọi người cơ hội ______[144] thời gian bên các đồng nghiệp trong một không gian giao lưu thoải mái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [144]}, {\"en\": \"We know that the distance to last year\'s banquet in Riverdale made it difficult for several employees to attend the event.\", \"vi\": \"Chúng tôi biết rằng khoảng cách đến bữa tiệc năm ngoái ở Riverdale đã khiến một số nhân viên gặp khó khăn khi tham dự sự kiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To make it easier for everyone to participate in this celebration, we are looking for a ______[145] that is closer to our office building.\", \"vi\": \"Để mọi người tham gia lễ kỷ niệm này dễ dàng hơn, chúng tôi đang tìm kiếm một ______[145] gần tòa nhà văn phòng của chúng ta hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [145]}, {\"en\": \"______[146].\", \"vi\": \"______[146].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [146]}, {\"en\": \"We plan to send out further details soon.\", \"vi\": \"Chúng tôi dự định sẽ sớm gửi thêm chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Bert Pizarro\", \"vi\": \"Bert Pizarro\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Human Resources Manager\", \"vi\": \"Trưởng phòng Nhân sự\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '6e4e1b8d-38eb-46ef-b16a-6e9b578f7e7c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mandi Garafelli (3:32 P.M.):\", \"vi\": \"Mandi Garafelli (3 giờ 32 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hello.\", \"vi\": \"Xin chào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Thanks for contacting Picturos Camera customer service.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã liên hệ với bộ phận chăm sóc khách hàng của Picturos Camera.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"How can I help you today?\", \"vi\": \"Hôm nay tôi có thể giúp gì cho quý vị?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Theo Ubari (3:33 P.M.):\", \"vi\": \"Theo Ubari (3:33 P.M.):\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Hi.\", \"vi\": \"Xin chào\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I recently bought the Picturos 3000.\", \"vi\": \"Gần đây, tôi đã mua chiếc Picturos 3000.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I\'m having trouble downloading photos from the camera to my computer.\", \"vi\": \"Tôi đang gặp khó khăn khi tải ảnh từ máy ảnh xuống máy tính của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Mandi Garafelli (3:35 P.M.):\", \"vi\": \"Mandi Garafelli (3 giờ 35 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Have you done these steps?\", \"vi\": \"Quý vị đã thực hiện các bước này chưa?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"1.\", \"vi\": \"1.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Check the connection between the camera and the computer.\", \"vi\": \"Vui lòng kiểm tra kết nối giữa máy ảnh và máy tính.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"2.\", \"vi\": \"2.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Turn the camera off and on again.\", \"vi\": \"Hãy tắt máy ảnh đi rồi bật lại.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"3.\", \"vi\": \"3.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Reboot the computer with the camera connected.\", \"vi\": \"Hãy khởi động lại máy tính trong khi camera vẫn được kết nối.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Theo Ubari (3:38 P.M.):\", \"vi\": \"Theo Ubari (3:38 P.M.):\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I tried steps 1 and 2.\", \"vi\": \"Tôi đã thực hiện các bước 1 và 2.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Nothing improved.\", \"vi\": \"Không có gì được cải thiện.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Mandi Garafelli (3:41 P.M.):\", \"vi\": \"Mandi Garafelli (3 giờ 41 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Before you try step 3, go into your \\\"applications\\\" folder and look for an icon that says \\\"Picturos 3000.\\\"\", \"vi\": \"Trước khi thực hiện bước 3, xin vui lòng truy cập vào thư mục “Ứng dụng” và tìm biểu tượng có tên “Picturos 3000”.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Do you see it?\", \"vi\": \"Quý vị có thấy không?\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Theo Ubari (3:42 P.M.):\", \"vi\": \"Theo Ubari (3:42 P.M.):\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Yes, it\'s there.\", \"vi\": \"Vâng, nó có ở đó.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Mandi Garafelli (3:43 P.M.):\", \"vi\": \"Mandi Garafelli (3 giờ 43 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Double click it.\", \"vi\": \"Hãy nhấp đúp vào nó.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Your pictures should automatically appear.\", \"vi\": \"Các hình ảnh của quý vị sẽ tự động hiển thị.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Theo Ubari (3:44 P.M.):\", \"vi\": \"Theo Ubari (3:44 P.M.):\", \"type\": \"metadata\", \"doc_index\": 7, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"That worked!\", \"vi\": \"Thế là thành công rồi!\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Thanks for your help!\", \"vi\": \"Xin cảm ơn sự giúp đỡ của quý vị!\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Mandi Garafelli (3:45 P.M.):\", \"vi\": \"Mandi Garafelli (3 giờ 45 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 8, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Sure thing.\", \"vi\": \"Chắc chắn rồi.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '6f1cf16c-c0b4-41cd-bc26-0ded2f2a2a16';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: pmendoza@factmail.co\", \"vi\": \"Đến: pmendoza@factmail.co\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: recruiting@analystassoc.org\", \"vi\": \"Từ: recruiting@analystassoc.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 2\", \"vi\": \"Ngày: Ngày 2 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Joining ASA\", \"vi\": \"Chủ đề: Tham gia ASA\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Mendoza,\", \"vi\": \"Kính gửi ông Mendoza,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for expressing your interest in our organization during the recent ______[131].\", \"vi\": \"Cảm ơn ông vì đã bày tỏ sự quan tâm đến tổ chức của chúng tôi trong ______[131] gần đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [131]}, {\"en\": \"It was a pleasure meeting you at the ASA booth during the Weber Information Systems Convention.\", \"vi\": \"Thật là vinh hạnh khi được gặp ông tại gian hàng của ASA trong Hội nghị Hệ thống Thông tin Weber.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As you may recall from our conversation, we discussed how ASA membership ______[132] your career through networking opportunities as well as the industry insights offered in our monthly newsletter.\", \"vi\": \"Như ông có thể nhớ lại từ cuộc trò chuyện của chúng ta, chúng tôi đã thảo luận về việc tư cách thành viên ASA ______[132] sự nghiệp của ông thông qua các cơ hội kết nối cũng như những thông tin chi tiết về ngành được cung cấp trong bản tin hàng tháng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [132]}, {\"en\": \"The normal fee for members is just $120 a year; however, we are currently offering a new-member discount.\", \"vi\": \"Mức phí thông thường dành cho hội viên chỉ là 120 đô la một năm; tuy nhiên, hiện tại chúng tôi đang cung cấp chương trình giảm giá cho hội viên mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"______[133].\", \"vi\": \"______[133].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [133]}, {\"en\": \"If you are still interested in joining, please reply to ______[134] with your mailing address.\", \"vi\": \"Nếu ông vẫn quan tâm đến việc tham gia, vui lòng phản hồi lại cho ______[134] kèm theo địa chỉ nhận thư của ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [134]}, {\"en\": \"I will then forward you an application packet.\", \"vi\": \"Sau đó, tôi sẽ chuyển tiếp cho ông một bộ hồ sơ đăng ký.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Ashlee Loren, President\", \"vi\": \"Ashlee Loren, Chủ tịch\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Association of Systems Analysts\", \"vi\": \"Hiệp hội Các nhà Phân tích Hệ thống\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '6f1ede9f-7a60-4595-9a4f-2a8c43106ccd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"November 23\", \"vi\": \"Ngày 23 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Matteo Fernandez\", \"vi\": \"Matteo Fernandez\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"5196 Revol St.\", \"vi\": \"5196 Đường Revol\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Laketon, CA 97999\", \"vi\": \"Laketon, CA 97999\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Fernandez,\", \"vi\": \"Kính gửi ông Fernandez,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We are writing to notify you that your license as described below will expire at the end of the year.\", \"vi\": \"Chúng tôi viết thư này để thông báo cho quý vị biết rằng giấy phép của quý vị, như được mô tả dưới đây, sẽ hết hạn vào cuối năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"License Type: Motorcycle\", \"vi\": \"Loại giấy phép: Xe máy\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"License Number: 297461\", \"vi\": \"Số giấy phép: 297461\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Expiration: December 31\", \"vi\": \"Hạn sử dụng: 31 tháng 12\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"State law requires all motor vehicle licenses to be renewed periodically.\", \"vi\": \"Luật tiểu bang quy định tất cả các giấy phép xe cơ giới phải được gia hạn định kỳ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The fees are $20 for boat and snowmobile licenses, $30 for motorcycle licenses, $40 for car licenses, and $50 for truck licenses.\", \"vi\": \"Mức lệ phí như sau: 20 đô la cho giấy phép điều khiển thuyền và xe trượt tuyết, 30 đô la cho giấy phép điều khiển xe máy, 40 đô la cho giấy phép điều khiển ô tô và 50 đô la cho giấy phép điều khiển xe tải.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Check our Web site regarding further requirements for truck licenses, as well as fees for other types of vehicle licenses: www.motorvehiclelicense.net.\", \"vi\": \"Quý vị vui lòng truy cập trang web của chúng tôi để tìm hiểu thêm về các yêu cầu đối với giấy phép lái xe tải, cũng như mức lệ phí cho các loại giấy phép lái xe khác: www.motorvehiclelicense.net.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"It is quick and easy to renew online.\", \"vi\": \"Việc gia hạn trực tuyến rất nhanh chóng và đơn giản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"You can also renew by mail.\", \"vi\": \"Quý vị cũng có thể gia hạn qua đường bưu điện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"If you choose this option, please send a copy of this notice along with payment to your local Motor Vehicle License office.\", \"vi\": \"Nếu quý vị chọn phương án này, xin vui lòng gửi bản sao thông báo này kèm theo khoản thanh toán đến Văn phòng Cấp giấy phép Phương tiện Cơ giới tại địa phương của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Betty Tsai\", \"vi\": \"Betty Tsai\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Betty Tsai\", \"vi\": \"Betty Tsai\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Administrator, Motor Vehicle Licenses\", \"vi\": \"Quản trị viên, Giấy phép phương tiện cơ giới\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '6f289585-1341-4314-a900-6068e3c1df49';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"ADMINISTRATIVE ASSISTANT\", \"vi\": \"TRỢ LÝ HÀNH CHÍNH\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Position Summary:\", \"vi\": \"Tóm tắt về vị trí công việc:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Naidu Rai Electronics, one of the world\'s leading manufacturers in the telecommunications industry, is seeking a full-time administrative assistant in our Jaipur office.\", \"vi\": \"Naidu Rai Electronics, một trong những nhà sản xuất hàng đầu thế giới trong ngành viễn thông, đang tìm kiếm một trợ lý hành chính làm việc toàn thời gian tại văn phòng của chúng tôi ở Jaipur.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Responsibilities:\", \"vi\": \"Nhiệm vụ:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Provide administrative support for members of the product design team, including travel and expense reports\", \"vi\": \"Cung cấp hỗ trợ hành chính cho các thành viên trong nhóm thiết kế sản phẩm, bao gồm việc lập báo cáo công tác và chi phí\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Schedule appointments with prospective clients and designers\", \"vi\": \"Lên lịch hẹn với các khách hàng tiềm năng và các nhà thiết kế\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Maintain files, process documents, and compile reports\", \"vi\": \"Quản lý hồ sơ, xử lý tài liệu và lập báo cáo\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Required Qualifications/Education:\", \"vi\": \"Yêu cầu về trình độ và bằng cấp:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Senior school certificate mandatory; business school certification preferred\", \"vi\": \"Bằng tốt nghiệp trung học phổ thông là điều kiện bắt buộc; ưu tiên ứng viên có chứng chỉ của trường kinh doanh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Skills:\", \"vi\": \"Kỹ năng:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Strong interpersonal skills\", \"vi\": \"Kỹ năng giao tiếp giữa các cá nhân xuất sắc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Strong organizational and planning skills\", \"vi\": \"Có kỹ năng tổ chức và lập kế hoạch vững vàng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Software proficiency\", \"vi\": \"Trình độ sử dụng phần mềm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To be considered, e-mail your résumé and cover letter to s.mohta@naiduraielec.in; candidates selected for an interview will be required to take a basic software proficiency test.\", \"vi\": \"Để được xem xét, xin vui lòng gửi sơ yếu lý lịch và thư xin việc qua email đến địa chỉ s.mohta@naiduraielec.in; các ứng viên được chọn tham gia phỏng vấn sẽ phải thực hiện bài kiểm tra trình độ sử dụng phần mềm cơ bản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '6f4507ca-18dc-402b-8d14-709089ac7e2a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Houkcomm Eyes Downtown Roseville\", \"vi\": \"Houkcomm Nhắm Đến Khu Vực Trung Tâm Roseville\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"(April 22)—Houkcomm, one of the state\'s leading telecommunications companies, will likely establish operations in Roseville.\", \"vi\": \"(Ngày 22 tháng 4)—Houkcomm, một trong những công ty viễn thông hàng đầu của bang, có khả năng sẽ thiết lập hoạt động tại Roseville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Houkcomm is reportedly looking to open a Roseville office as part of a new venture for the company: an expansion into the digital media industry.\", \"vi\": \"Houkcomm được cho là đang tìm cách mở một văn phòng tại Roseville như một phần trong dự án kinh doanh mới của công ty: mở rộng sang ngành công nghiệp truyền thông số.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Houkcomm spokespeople have not offered any details on the plan, but two architects involved with the project confirmed that one proposed office building design would accommodate over 100 workers.\", \"vi\": \"Những người phát ngôn của Houkcomm chưa đưa ra bất kỳ chi tiết nào về kế hoạch này, nhưng hai kiến trúc sư tham gia vào dự án đã xác nhận rằng một thiết kế tòa nhà văn phòng được đề xuất sẽ có sức chứa hơn 100 nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The likely location for this soon-to-be constructed building, according to these sources, is a property adjacent to Behr Square in central Roseville.\", \"vi\": \"Vị trí có khả năng cao cho tòa nhà sắp được xây dựng này, theo các nguồn tin trên, là một khu đất nằm cạnh Quảng trường Behr ở trung tâm Roseville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}]' WHERE `id` = '6f4bb1b7-fa5e-4b40-9b6a-165d70f89125';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Be Green Aware in Misford\", \"vi\": \"Hãy nâng cao nhận thức về bảo vệ môi trường tại Misford\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"March 26—The village of Misford will celebrate its annual Green Awareness Week in April.\", \"vi\": \"Ngày 26 tháng 3 — Làng Misford sẽ tổ chức Tuần lễ Nâng cao Nhận thức về Môi trường thường niên vào tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This event is coordinated by the village\'s Green Earth Committee and is part of a long-term effort to keep Misford green and clean.\", \"vi\": \"Sự kiện này do Ủy ban Trái đất Xanh của làng phối hợp tổ chức và là một phần trong nỗ lực lâu dài nhằm duy trì cảnh quan xanh tươi và sạch đẹp cho Misford.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The activities will start on Sunday, April 1, with a cleanup of the Misford Stream trails.\", \"vi\": \"Các hoạt động sẽ bắt đầu vào Chủ nhật, ngày 1 tháng 4, với đợt dọn dẹp các con đường mòn dọc suối Misford.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Two teams of volunteers will work on either side of the stream to pick up any rubbish and clear the paths of fallen branches.\", \"vi\": \"Hai đội tình nguyện viên sẽ làm việc ở hai bên con suối để thu gom rác thải và dọn dẹp các cành cây gãy trên lối đi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"On Monday, residents are encouraged to walk along the trails and take photographs.\", \"vi\": \"Vào thứ Hai, người dân được khuyến khích đi dạo dọc theo các con đường mòn và chụp ảnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The Green Earth Committee is accepting digital images and will select the ten best to post to the village Web site.\", \"vi\": \"Ủy ban Trái Đất Xanh hiện đang tiếp nhận các hình ảnh kỹ thuật số và sẽ chọn ra mười bức ảnh xuất sắc nhất để đăng tải lên trang web của làng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"On Tuesday and Wednesday, residents who come to the village hall can pick up cloth bags to replace single-use plastic shopping bags, the sale of which will be banned in our county starting next month.\", \"vi\": \"Vào thứ Ba và thứ Tư, các cư dân đến trụ sở xã có thể nhận túi vải để thay thế cho túi nhựa dùng một lần, loại túi này sẽ bị cấm bán tại huyện chúng ta kể từ tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"On Thursday, the Misford Library will host a panel on ways to conserve energy and reduce and recycle waste.\", \"vi\": \"Vào thứ Năm, Thư viện Misford sẽ tổ chức một buổi thảo luận bàn tròn về các biện pháp tiết kiệm năng lượng, giảm thiểu và tái chế rác thải.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"These are fundamental goals of the village and its Green Earth Committee.\", \"vi\": \"Đây là những mục tiêu cơ bản của làng và Ủy ban Trái đất Xanh của làng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Children are welcome to attend with an adult.\", \"vi\": \"Trẻ em được chào đón tham dự cùng người lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Finally, on Saturday, 500 tree saplings will be offered to residents free of charge.\", \"vi\": \"Cuối cùng, vào thứ Bảy, 500 cây con sẽ được tặng miễn phí cho người dân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The trees are native to the region and can be planted in private gardens or in some public areas.\", \"vi\": \"Những cây này là loài bản địa của khu vực và có thể được trồng trong các khu vườn tư nhân hoặc tại một số khu vực công cộng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '6f66c2ed-8773-48d3-8ba4-349686267228';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"7:00–8:00 A.M. - Registration (main auditorium, ground floor)\", \"vi\": \"7:00–8:00 sáng - Đăng ký (hội trường chính, tầng trệt)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"8:00–9:15 A.M. - Software Solutions\\nLearn about the latest and best software systems for keeping track of fleets and product shipments and for facilitating communication between drivers and dispatchers.\\nInstructor: Nicklas Massen\", \"vi\": \"8:00–9:15 sáng - Giải pháp phần mềm\\nTìm hiểu về các hệ thống phần mềm mới nhất và hiệu quả nhất nhằm theo dõi đội xe và lô hàng, đồng thời hỗ trợ việc liên lạc giữa các tài xế và điều phối viên.\\nGiảng viên: Nicklas Massen\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"9:30–10:30 A.M. - Air Cargo Units\\nExplore new insights into air cargo operations in the areas of domestic and overseas transport, calculating rates and charges, safeguarding valuable items, and troubleshooting possible complications.\\nInstructor: Ezinne Chioke\", \"vi\": \"9:30–10:30 sáng - Các đơn vị vận chuyển hàng hóa bằng đường hàng không\\nKhám phá những hiểu biết mới về hoạt động vận chuyển hàng hóa bằng đường hàng không trong các lĩnh vực vận chuyển nội địa và quốc tế, tính toán cước phí và các khoản phụ thu, bảo vệ hàng hóa có giá trị, cũng như xử lý các sự cố có thể phát sinh.\\nGiảng viên: Ezinne Chioke\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"10:45–11:45 A.M. - Effective Driver Training\\nIt\'s the law! The National Transportation Council holds employers responsible for ensuring that all drivers are familiar with government laws and requirements. The latest rule updates will be addressed as will tips on how to organize an effective training program.\\nInstructor: Ching-Lien Wu\", \"vi\": \"10:45–11:45 sáng - Đào tạo lái xe hiệu quả\\nĐây là quy định của pháp luật! Hội đồng Giao thông Vận tải Quốc gia quy định các nhà tuyển dụng phải chịu trách nhiệm đảm bảo rằng tất cả các tài xế đều nắm rõ các quy định và yêu cầu của chính phủ. Buổi hội thảo sẽ đề cập đến những cập nhật mới nhất về quy định cũng như các lời khuyên về cách tổ chức một chương trình đào tạo hiệu quả.\\nGiảng viên: Ching-Lien Wu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"12:00–1:00 P.M. - Maintaining Vehicle Fleets\\nExamine recent trends in managing fleets of vehicles (cars, buses, trucks, and delivery equipment), which include anticipating and controlling the costs associated with vehicles, mechanics, drivers, vendors, and fuel consumption.\\nInstructor: Nicklas Massen\", \"vi\": \"12:00–13:00 – Quản lý đội xe\\nPhân tích các xu hướng gần đây trong việc quản lý đội xe (ô tô, xe buýt, xe tải và phương tiện vận chuyển hàng hóa), bao gồm việc dự báo và kiểm soát các chi phí liên quan đến phương tiện, thợ cơ khí, tài xế, nhà cung cấp và mức tiêu thụ nhiên liệu.\\nGiảng viên: Nicklas Massen\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Conference Schedule for May 25\", \"vi\": \"Lịch trình hội nghị ngày 25 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"All sessions will be held in the Geneva Conference Room on the fourth floor, except the 12 P.M. session, which will be held in the Harkness Conference Room on the second floor.\", \"vi\": \"Tất cả các phiên họp sẽ diễn ra tại Phòng Hội nghị Geneva ở tầng 4, ngoại trừ phiên họp lúc 12 giờ trưa, sẽ diễn ra tại Phòng Hội nghị Harkness ở tầng 2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Presenters who need help setting up should see Facilities staff in room G14.\", \"vi\": \"Các diễn giả cần hỗ trợ trong việc chuẩn bị thiết bị xin vui lòng liên hệ với nhân viên phụ trách cơ sở vật chất tại phòng G14.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '7015ea6e-c714-49ab-a257-bfc9df747295';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Fishing Village to Become Bustling Port\", \"vi\": \"Làng chài sắp trở thành cảng biển sầm uất\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"DODOMA (14 April)—The unassuming town of Kikole, on the Tanzanian coast, is set to become a fully equipped port after an increase in ______[135] in the region.\", \"vi\": \"DODOMA (14 tháng 4)—Thị trấn nhỏ bé Kikole thuộc bờ biển Tanzania chuẩn bị trở thành một cảng biển đầy đủ trang thiết bị sau sự gia tăng của ______[135] trong khu vực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [135]}, {\"en\": \"The government has recently designated the area as a business district.\", \"vi\": \"Chính phủ gần đây đã chỉ định khu vực này là một khu kinh doanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"This ______[136] attract new businesses and further spur economic growth.\", \"vi\": \"Điều này ______[136] thu hút các doanh nghiệp mới và thúc đẩy hơn nữa tăng trưởng kinh tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"One firm, Marina International Shipping, has already announced plans to open a hub there.\", \"vi\": \"Một công ty, Marina International Shipping, đã công bố kế hoạch mở một trung tâm tại đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[137].\", \"vi\": \"______[137].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [137]}, {\"en\": \"A number of government officials have recently expressed opposition to the plan.\", \"vi\": \"Một số quan chức chính phủ gần đây đã bày tỏ sự phản đối đối với kế hoạch này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"______[138], with the needed finances already secured, it seems certain that the project will move forward.\", \"vi\": \"______[138], với nguồn tài chính cần thiết đã được bảo đảm, có vẻ chắc chắn rằng dự án sẽ được tiến hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [138]}]' WHERE `id` = '706b44ec-6b18-4502-bfbf-a82c91b2674a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Coming Soon: The Best of PBQ Radio\", \"vi\": \"Sắp ra mắt: Những chương trình hay nhất của PBQ Radio\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"During the week of April 21-27, PBQ Radio will be hosting a best-of-the-decade program.\", \"vi\": \"Trong tuần từ ngày 21 đến 27 tháng 4, Đài phát thanh PBQ sẽ tổ chức một chương trình tổng hợp những tác phẩm xuất sắc nhất thập kỷ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The most popular tunes by recording artists from the past decade will be played all day long.\", \"vi\": \"Các ca khúc nổi tiếng nhất của các nghệ sĩ thu âm trong thập kỷ qua sẽ được phát suốt cả ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Both well-known and lesser-known recording artists will be featured.\", \"vi\": \"Chương trình sẽ giới thiệu cả những nghệ sĩ thu âm nổi tiếng lẫn những nghệ sĩ ít được biết đến hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We plan to showcase each artist\'s top works.\", \"vi\": \"Chúng tôi dự định sẽ trưng bày những tác phẩm xuất sắc nhất của từng nghệ sĩ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"In addition to featuring the best music of the decade, we would like to highlight our region\'s businesses.\", \"vi\": \"Bên cạnh việc giới thiệu những bản nhạc hay nhất của thập kỷ này, chúng tôi cũng mong muốn giới thiệu các doanh nghiệp trong khu vực của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Advertising time is available for purchase.\", \"vi\": \"Quý vị có thể mua thời lượng quảng cáo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Let our listeners know that your business is one of the best in the community!\", \"vi\": \"Hãy cho thính giả của chúng tôi biết rằng doanh nghiệp của quý vị là một trong những doanh nghiệp xuất sắc nhất trong cộng đồng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"You can request a shout-out for your company from a program host, or our professional marketing team can write and record a 30-second advertisement.\", \"vi\": \"Quý vị có thể đề nghị người dẫn chương trình giới thiệu về công ty của mình, hoặc đội ngũ tiếp thị chuyên nghiệp của chúng tôi có thể soạn thảo và thu âm một quảng cáo dài 30 giây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Visit www.pbqradio.com/advertise for details and pricing.\", \"vi\": \"Vui lòng truy cập www.pbqradio.com/advertise để biết thêm chi tiết và thông tin về giá cả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '7083ca07-81cf-49eb-ad80-91bd3a753f74';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"NOTICE\", \"vi\": \"THÔNG BÁO\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To continue providing the highest level of ______[131] to our corporate tenants, we have scheduled the south lobby restrooms for maintenance this weekend, May 13 and May 14.\", \"vi\": \"Để tiếp tục cung cấp mức độ ______[131] cao nhất cho các khách thuê doanh nghiệp của chúng tôi, chúng tôi đã lên lịch bảo trì nhà vệ sinh ở sảnh phía nam vào cuối tuần này, ngày 13 tháng 5 và ngày 14 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"______[132] this time, the restrooms will be out of order, so tenants and their guests should instead use the facilities in the north lobby.\", \"vi\": \"______[132] thời gian này, nhà vệ sinh sẽ không hoạt động, vì vậy khách thuê và khách của họ nên sử dụng các phòng vệ sinh ở sảnh phía bắc thay thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132]}, {\"en\": \"We ______[133] for any inconvenience this might cause.\", \"vi\": \"Chúng tôi ______[133] vì bất kỳ sự bất tiện nào mà điều này có thể gây ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [133]}, {\"en\": \"______[134].\", \"vi\": \"______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [134]}, {\"en\": \"Denville Property Management Partners\", \"vi\": \"Công ty Quản lý Bất động sản Denville Property Management Partners\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '7084775e-3076-4252-aa11-a97dfb372d55';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Medillo Shoes Celebrates Twenty Years in Cape Town!\", \"vi\": \"Medillo Shoes kỷ niệm 20 năm hoạt động tại Cape Town!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"246 Breda Place, Wynberg, Cape Town 7800\", \"vi\": \"246 Breda Place, Wynberg, Cape Town 7800\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"021 555 0149 | www.medilloshoes.co.za\", \"vi\": \"021 555 0149 | www.medilloshoes.co.za\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Does your job require you to stand all day long?\", \"vi\": \"Công việc của quý vị có đòi hỏi quý vị phải đứng suốt cả ngày không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Get the support you need!\", \"vi\": \"Hãy nhận sự hỗ trợ mà quý vị cần!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"At Medillo Shoes, we specialise in comfortable, supportive footwear that is stylish and suitable for any business or medical setting.\", \"vi\": \"Tại Medillo Shoes, chúng tôi chuyên cung cấp các dòng giày dép vừa thoải mái, vừa mang lại sự hỗ trợ tốt, đồng thời vẫn thời trang và phù hợp với mọi môi trường làm việc trong lĩnh vực kinh doanh hoặc y tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Visit us on 10 May to receive 20 percent off your purchase of one or more pairs of shoes during this anniversary event.\", \"vi\": \"Hãy ghé thăm chúng tôi vào ngày 10 tháng 5 để được giảm giá 20% khi mua một hoặc nhiều đôi giày trong khuôn khổ sự kiện kỷ niệm này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Should you need assistance finding the best shoes for your professional needs, our footwear specialists will be on hand to help.\", \"vi\": \"Nếu quý vị cần sự hỗ trợ trong việc tìm kiếm đôi giày phù hợp nhất cho nhu cầu công việc của mình, các chuyên gia về giày dép của chúng tôi sẽ luôn sẵn sàng hỗ trợ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Schedule a free consultation at www.medilloshoes.co.za to avoid a long wait.\", \"vi\": \"Hãy đặt lịch tư vấn miễn phí tại www.medilloshoes.co.za để tránh phải chờ đợi lâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '70af71c2-be92-4622-b734-4062cd438f4c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"31 July\", \"vi\": \"31 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Akwasi Dombo\", \"vi\": \"Akwasi Dombo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Fourth Avenue\", \"vi\": \"Đại lộ Fourth\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"GA 105\", \"vi\": \"GA 105\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Accra, Ghana\", \"vi\": \"Accra, Ghana\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Dombo,\", \"vi\": \"Ông Dombo kính mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for your ____135____ support in helping me to plan the opening gala for Tokyo\'s fashion week.\", \"vi\": \"Cảm ơn sự hỗ trợ ____135____ của ông trong việc giúp tôi lên kế hoạch cho buổi dạ tiệc khai mạc tuần lễ thời trang Tokyo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [135]}, {\"en\": \"The event was a huge success, and I was honored to work with you.\", \"vi\": \"Sự kiện đã thành công rực rỡ và tôi rất vinh dự được làm việc với ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I know that our attendees follow your work closely, and they loved the designs you contributed for this event.\", \"vi\": \"Tôi biết rằng những người tham dự sự kiện của chúng tôi rất theo dõi sát sao các tác phẩm của ông, và họ rất yêu thích các mẫu thiết kế mà ông đã đóng góp cho sự kiện này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Your designs received a lot of ____136____ on social media.\", \"vi\": \"Các thiết kế của ông đã nhận được rất nhiều sự ____136____ trên mạng xã hội.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [136]}, {\"en\": \"Shows like this will keep Tokyo on the map as a premier fashion centre.\", \"vi\": \"Những buổi biểu diễn như thế này sẽ giữ vững vị thế của Tokyo như một trung tâm thời trang hàng đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"____137____.\", \"vi\": \"____137____.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [137]}, {\"en\": \"I realize that the multiple delays made the planning no easy task.\", \"vi\": \"Tôi nhận ra rằng việc liên tục bị hoãn lại đã khiến công tác lập kế hoạch không hề dễ dàng chút nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The auction ____138____ our Young Designers Award program is coming up soon and I look forward to working with you on that as well.\", \"vi\": \"Buổi đấu giá ____138____ chương trình Giải thưởng Nhà thiết kế trẻ của chúng tôi sắp diễn ra và tôi rất mong được hợp tác với ông trong chương trình đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": [138]}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Asahi Ishioka\", \"vi\": \"Asahi Ishioka\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Director, Japanese Guild of Fashion Designers\", \"vi\": \"Giám đốc, Hiệp hội Nhà thiết kế Thời trang Nhật Bản\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '70f79276-d512-4151-b1de-9e076cef2639';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"HJP Transport Solutions, Ltd.\", \"vi\": \"Công ty TNHH HJP Transport Solutions\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Powell Internship Programme\", \"vi\": \"Chương trình Thực tập Powell\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"HJP Transport Solutions, Ltd., headquartered in London, seeks university students to fill ten intern positions in its Powell Internship Programme (PIP).\", \"vi\": \"Công ty TNHH HJP Transport Solutions, có trụ sở chính tại London, đang tìm kiếm sinh viên đại học để tuyển dụng vào mười vị trí thực tập trong Chương trình Thực tập Powell (PIP) của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Interns will be placed in one of HJP\'s three regional offices: Birmingham, Manchester, or Bristol.\", \"vi\": \"Các thực tập sinh sẽ được phân công làm việc tại một trong ba văn phòng khu vực của HJP: Birmingham, Manchester hoặc Bristol.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Applicants should email a statement of interest and résumé to pip@hjp.co.uk by 31 March.\", \"vi\": \"Các ứng viên vui lòng gửi thư bày tỏ nguyện vọng và sơ yếu lý lịch qua email đến địa chỉ pip@hjp.co.uk trước ngày 31 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Successful candidates will have the honour of being the first recipients of the Powell Internship.\", \"vi\": \"Các ứng viên trúng tuyển sẽ vinh dự trở thành những người đầu tiên nhận được Chương trình Thực tập Powell.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Background:\", \"vi\": \"Bối cảnh:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"PIP is the initiative of Tristan Powell, who wanted to honour the ingenuity of Henry J. Powell, the founder of HJP Transport Solutions, Ltd. The programme seeks to inspire young engineering students to follow in Henry J. Powell\'s footsteps and propose and develop innovative solutions to shipping and transport problems.\", \"vi\": \"PIP là sáng kiến của ông Tristan Powell, người mong muốn tôn vinh sự sáng tạo của ông Henry J. Powell, nhà sáng lập Công ty HJP Transport Solutions, Ltd. Chương trình này nhằm truyền cảm hứng cho các sinh viên ngành kỹ thuật trẻ noi gương ông Henry J. Powell, đồng thời đề xuất và phát triển các giải pháp sáng tạo nhằm giải quyết các vấn đề trong lĩnh vực vận tải biển và vận tải.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Having earned his doctorate degree in engineering, Henry J. Powell went on to found HJP Transport Solutions, Ltd. Over time, he built the company into a successful, internationally renowned business.\", \"vi\": \"Sau khi nhận bằng tiến sĩ ngành kỹ thuật, ông Henry J. Powell đã thành lập công ty HJP Transport Solutions, Ltd. Qua thời gian, ông đã xây dựng công ty này trở thành một doanh nghiệp thành công và nổi tiếng trên toàn cầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Having served four decades as company president, he retired last year and was succeeded by his son, Tristan.\", \"vi\": \"Sau bốn thập kỷ đảm nhiệm cương vị Chủ tịch công ty, ông đã nghỉ hưu vào năm ngoái và người kế nhiệm ông là con trai ông, ông Tristan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To: Joseph Chen <jchen@sunnydale.ac.uk>\", \"vi\": \"Gửi tới: Joseph Chen <jchen@sunnydale.ac.uk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"From: Padma Vithana <pvithana@hjp.co.uk>\", \"vi\": \"Từ: Padma Vithana <pvithana@hjp.co.uk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Date: 25 April\", \"vi\": \"Ngày: 25 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Dear Mr. Chen,\", \"vi\": \"Kính gửi ông Chen,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thank you for promptly returning the paperwork relevant to your internship.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã nhanh chóng gửi lại các hồ sơ liên quan đến kỳ thực tập của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"You will receive your intern packet within a week.\", \"vi\": \"Quý vị sẽ nhận được bộ tài liệu dành cho thực tập sinh trong vòng một tuần.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"As for your inquiry about housing, I appreciate your concern that the two-hour train ride from London to your assigned location makes for an arduous daily commute.\", \"vi\": \"Về thắc mắc của quý vị liên quan đến vấn đề nhà ở, tôi hoàn toàn thấu hiểu lo ngại của quý vị rằng việc phải di chuyển bằng tàu hỏa trong hai giờ từ London đến địa điểm được phân công sẽ khiến quãng đường đi làm hàng ngày trở nên vất vả.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Regrettably, HJP does not provide accommodations for interns.\", \"vi\": \"Rất tiếc, HJP không cung cấp chỗ ở cho các thực tập sinh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I suggest that you contact Mr. Daniel Anders who is in charge of the mentorship program in our Bristol office.\", \"vi\": \"Tôi đề nghị quý vị liên hệ với ông Daniel Anders, người phụ trách chương trình cố vấn tại văn phòng Bristol của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"He has lived in the city for many years and presumably will have some advice about housing options there.\", \"vi\": \"Ông ấy đã sinh sống tại thành phố này nhiều năm và có lẽ sẽ có một số lời khuyên về các lựa chọn chỗ ở tại đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Good luck, and I hope you will enjoy working at HJP.\", \"vi\": \"Chúc quý vị may mắn, và tôi hy vọng quý vị sẽ cảm thấy hài lòng khi làm việc tại HJP.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Padma Vithana\", \"vi\": \"Padma Vithana\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Director of Recruiting, HJP Transport Solutions, Ltd.\", \"vi\": \"Giám đốc Bộ phận Tuyển dụng, Công ty TNHH HJP Transport Solutions\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '71276b3c-b12d-4df6-9b86-fd40f68cdacd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"CITY OF BRYANTON\", \"vi\": \"THÀNH PHỐ BRYANTON\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Building Permit Office\", \"vi\": \"Văn phòng Cấp phép Xây dựng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Notice for residents and contractors working in Bryanton\", \"vi\": \"Thông báo dành cho cư dân và các nhà thầu đang làm việc tại Bryanton\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Beginning on Monday, July 1, the City of Bryanton\'s Building Permit Office, located at 912 Fir Avenue, will be open from Monday to Thursday, 9:00 A.M. to 5:00 P.M. Applications for permits will no longer be accepted on Fridays or Saturdays.\", \"vi\": \"Kể từ thứ Hai, ngày 1 tháng 7, Văn phòng Cấp phép Xây dựng của Thành phố Bryanton, tọa lạc tại số 912 Fir Avenue, sẽ mở cửa từ thứ Hai đến thứ Năm, từ 9 giờ sáng đến 5 giờ chiều. Các đơn xin cấp phép sẽ không còn được tiếp nhận vào các ngày thứ Sáu và thứ Bảy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The average processing time for permit applications will remain three business days.\", \"vi\": \"Thời gian xử lý trung bình đối với các hồ sơ xin giấy phép sẽ vẫn là ba ngày làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"With this change, the city will lower its operating costs while maintaining its high standards of service for residents.\", \"vi\": \"Với sự thay đổi này, thành phố sẽ giảm chi phí hoạt động đồng thời vẫn duy trì các tiêu chuẩn dịch vụ cao dành cho người dân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '7174aef6-3843-49cc-a130-538dd9c5de3e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Seul-Gi Ma - [9:08 a.m.] - Good morning, Devin. Have you seen the e-mail that the museum\'s main account received yesterday evening?\", \"vi\": \"Ma Seul-Gi - [9 giờ 08 phút sáng] - Chào buổi sáng, Devin. Anh đã xem email mà tài khoản chính của bảo tàng nhận được vào tối qua chưa?\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Devin Stewart - [9:09 a.m.] - I\'ll check.\", \"vi\": \"Devin Stewart - [9 giờ 09 phút sáng] - Tôi sẽ kiểm tra xem.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Seul-Gi Ma - [9:10 a.m.] - The sender\'s name is Veronica Gunn. She says she took one of Pramrod\'s tours yesterday.\", \"vi\": \"Seul-Gi Ma - [9 giờ 10 phút sáng] - Tên người gửi là Veronica Gunn. Cô ấy cho biết hôm qua cô ấy đã tham gia một chuyến tham quan do Pramrod tổ chức.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Devin Stewart - [9:12 a.m.] - And she believes that the plaid dress in the nineteenth-century American fashion exhibition is probably from a later decade than what our label says?\", \"vi\": \"Devin Stewart - [9 giờ 12 phút sáng] - Và cô ấy cho rằng chiếc váy kẻ caro trong triển lãm thời trang Mỹ thế kỷ XIX có lẽ thuộc thập kỷ muộn hơn so với những gì nhãn mác ghi?\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Seul-Gi Ma - [9:13 a.m.] - Yes, because of the design of the sleeves. I think we should look into it. She seems quite knowledgeable.\", \"vi\": \"Ma Seul-Gi - [9 giờ 13 phút sáng] - Vâng, đó là do kiểu dáng của phần tay áo. Tôi nghĩ chúng ta nên xem xét kỹ vấn đề này. Cô ấy có vẻ rất am hiểu về lĩnh vực này.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Devin Stewart - [9:13 a.m.] - I agree. I\'ll bring Celia into the chat.\", \"vi\": \"Devin Stewart - [9 giờ 13 phút sáng] - Tôi đồng ý. Tôi sẽ mời Celia tham gia cuộc trò chuyện.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Devin Stewart - [9:14 a.m.] - Celia, I\'m forwarding you an e-mail we\'ve received about our new exhibition. Can you look over it and then get an opinion from the fashion history professor you met at Hemphill University?\", \"vi\": \"Devin Stewart - [9 giờ 14 phút sáng] - Celia, tôi xin chuyển tiếp cho cô một email mà chúng tôi vừa nhận được về triển lãm mới của chúng ta. Cô có thể xem qua và sau đó xin ý kiến từ vị giáo sư lịch sử thời trang mà cô đã gặp tại Đại học Hemphill được không?\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Celia Ball - [9:16 a.m.] - Sure. How pressing is this issue? Sometimes he takes a few days to respond to e-mails.\", \"vi\": \"Celia Ball - [9 giờ 16 phút sáng] - Vâng. Vấn đề này cấp bách đến mức nào? Đôi khi anh ấy mất vài ngày mới trả lời email.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Devin Stewart - [9:17 a.m.] - I\'d like to get it figured out by the end of the day.\", \"vi\": \"Devin Stewart - [9 giờ 17 phút sáng] - Tôi mong muốn giải quyết xong vấn đề này trước khi kết thúc ngày hôm nay.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Celia Ball - [9:18 a.m.] - Got it. I\'ll call him and let you know what I find out.\", \"vi\": \"Celia Ball - [9 giờ 18 phút sáng] - Rõ rồi. Tôi sẽ gọi cho anh ấy và thông báo cho quý vị biết những thông tin tôi thu thập được.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"💬 👤\", \"vi\": \"💬 👤\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '719da437-4415-4827-a0df-92df9b2a3706';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Linton Business Alliance members\", \"vi\": \"Kính gửi: Các thành viên của Liên minh Doanh nghiệp Linton\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Robin Fowler\", \"vi\": \"Từ: Robin Fowler\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: June 12\", \"vi\": \"Ngày: 12 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Organizational meeting\", \"vi\": \"Chủ đề: Cuộc họp tổ chức\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Proposed agenda\", \"vi\": \"Tài liệu đính kèm: 📎 Dự thảo chương trình làm việc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Hello everyone,\", \"vi\": \"Xin chào quý vị,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am reaching out to you to determine when we can meet.\", \"vi\": \"Tôi liên hệ với quý vị để thống nhất thời gian chúng ta có thể gặp nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Since news about the creation of our Business Alliance is generating interest within the community, it is time to create some written materials to promote ourselves.\", \"vi\": \"Vì tin tức về việc thành lập Liên minh Doanh nghiệp của chúng ta đang thu hút sự quan tâm trong cộng đồng, đã đến lúc chúng ta cần chuẩn bị một số tài liệu bằng văn bản để quảng bá về mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I would like to spend time at our meeting formulating an action plan for soliciting members.\", \"vi\": \"Tôi mong muốn dành thời gian trong cuộc họp của chúng ta để xây dựng một kế hoạch hành động nhằm thu hút thành viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I have attached a draft agenda.\", \"vi\": \"Tôi đã đính kèm bản dự thảo chương trình làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"It should not take long to coordinate our assignments for speaking to local business owners, but we could probably save meeting time by doing this online before the meeting.\", \"vi\": \"Việc phân công nhiệm vụ để trao đổi với các chủ doanh nghiệp địa phương có lẽ sẽ không mất nhiều thời gian, nhưng có lẽ chúng ta có thể tiết kiệm thời gian họp bằng cách thực hiện việc này trực tuyến trước khi họp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please send me an e-mail with your availability for the next few weeks.\", \"vi\": \"Kính mong quý vị gửi cho tôi một email nêu rõ thời gian rảnh của quý vị trong vài tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I understand that Sasha Zimmer is out of town until early July, but I still hope we can find a meeting date and time that will work for everyone.\", \"vi\": \"Tôi được biết rằng cô Sasha Zimmer sẽ vắng mặt cho đến đầu tháng Bảy, nhưng tôi vẫn hy vọng chúng ta có thể tìm được một ngày và giờ họp phù hợp với tất cả mọi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Robin Fowler\", \"vi\": \"Robin Fowler\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"10:00 A.M. - Introductions\", \"vi\": \"10 giờ sáng – Phần giới thiệu\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"10:15 A.M. - Item 1—Discussion to define mission statement and identify three initiatives for the year\", \"vi\": \"10 giờ 15 phút sáng – Mục 1 — Thảo luận nhằm xác định tuyên bố sứ mệnh và xác định ba sáng kiến cho năm nay\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"11:00 A.M. - Item 2—Media training workshop with Brandon Clark *\", \"vi\": \"11 giờ sáng – Mục 2 — Hội thảo đào tạo về truyền thông với ông Brandon Clark *\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"12:00 noon - Item 3—Assign tasks for creation of Alliance communications: press release, letter to local business owners, brochure, and a Web page highlighting membership\", \"vi\": \"12 giờ trưa – Mục 3 — Phân công nhiệm vụ để xây dựng các tài liệu truyền thông của Liên minh: thông cáo báo chí, thư gửi các chủ doanh nghiệp địa phương, tờ rơi và một trang web giới thiệu về tư cách thành viên\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"12:30 P.M. - Item 4—Assign Alliance members to speak with business owners\", \"vi\": \"12 giờ 30 phút trưa – Mục 4 — Chỉ định các thành viên của Liên minh đến trao đổi với các chủ doanh nghiệp\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"12:45 P.M. - Adjourn\", \"vi\": \"12 giờ 45 phút chiều – Kết thúc phiên họp\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Organizational meeting—Proposed agenda\", \"vi\": \"Cuộc họp tổ chức — Dự thảo chương trình nghị sự\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"* Brandon Clark, a news anchor at the Ulani News Network, has offered to lead a workshop about interacting with the media.\", \"vi\": \"* Ông Brandon Clark, người dẫn chương trình tin tức tại Mạng lưới Tin tức Ulani, đã đề nghị chủ trì một buổi hội thảo về cách tương tác với giới truyền thông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"He will emphasize the importance of preparing talking points and staying on message.\", \"vi\": \"Ông sẽ nhấn mạnh tầm quan trọng của việc chuẩn bị các nội dung chính cần trình bày và tuân thủ chặt chẽ thông điệp đã đề ra.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"To: Linton Business Alliance members\", \"vi\": \"Kính gửi: Các thành viên của Liên minh Doanh nghiệp Linton\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"From: Robin Fowler\", \"vi\": \"Từ: Robin Fowler\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Date: June 22\", \"vi\": \"Ngày: 22 tháng 6\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Subject: Finalized organizational meeting\", \"vi\": \"Chủ đề: Cuộc họp tổ chức đã được hoàn tất\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Final agenda\", \"vi\": \"Tài liệu đính kèm: 📎 Chương trình làm việc cuối cùng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Thanks to everyone for your feedback.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã đóng góp ý kiến.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"The final agenda is attached.\", \"vi\": \"Chương trình nghị sự cuối cùng được đính kèm dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"We have confirmed the workshop for June 28 at the Linton Community Library.\", \"vi\": \"Chúng tôi đã xác nhận buổi hội thảo sẽ diễn ra vào ngày 28 tháng 6 tại Thư viện Cộng đồng Linton.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"The library opens at 10:00 A.M. and staff will be on hand to help set up the room.\", \"vi\": \"Thư viện mở cửa lúc 10 giờ sáng và các nhân viên sẽ có mặt tại chỗ để hỗ trợ việc sắp xếp phòng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I\'d like to stress the importance of sticking to the agenda because our time together is limited.\", \"vi\": \"Tôi xin nhấn mạnh tầm quan trọng của việc tuân thủ chương trình làm việc, bởi vì thời gian chúng ta dành cho nhau là có hạn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Those meeting participants who would like to discuss any topics further can perhaps enjoy some lunch after the meeting.\", \"vi\": \"Những người tham dự cuộc họp nào muốn thảo luận sâu hơn về bất kỳ chủ đề nào cũng có thể cùng dùng bữa trưa sau cuộc họp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"I will plan to go to Devon\'s Sandwich Shop, which is just one block south of the library.\", \"vi\": \"Tôi dự định sẽ ghé qua tiệm bánh mì Devon\'s Sandwich Shop, nằm chỉ cách thư viện một dãy nhà về phía nam.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"All are welcome to join me.\", \"vi\": \"Mọi người đều được chào đón tham gia cùng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Robin Fowler\", \"vi\": \"Robin Fowler\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}]' WHERE `id` = '71d82d86-7e98-416c-b550-065e1f571289';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dora County Department of Transportation\", \"vi\": \"Sở Giao thông Vận tải Hạt Dora\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Division of Administrative Services\", \"vi\": \"Phòng Dịch vụ Hành chính\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"HIGHWAY SUPERVISOR\", \"vi\": \"GIÁM SÁT VIÊN ĐƯỜNG CAO TỐC\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The highway supervisor oversees all tasks related to the construction and maintenance of road-related structures throughout Dora County, including creating work objectives for all emergency program activities.\", \"vi\": \"Giám sát viên đường cao tốc chịu trách nhiệm giám sát tất cả các công việc liên quan đến việc xây dựng và bảo trì các công trình giao thông trên toàn Hạt Dora, bao gồm việc đề ra các mục tiêu công việc cho tất cả các hoạt động thuộc chương trình ứng phó khẩn cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Key responsibilities include the organization of all snow-removal operations and construction projects.\", \"vi\": \"Các nhiệm vụ chính bao gồm việc tổ chức tất cả các hoạt động dọn tuyết và các dự án xây dựng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Therefore, the supervisor must also be able to perform construction and maintenance work as needed and possess an appropriate level of skill in operating the relevant equipment.\", \"vi\": \"Do đó, người giám sát cũng phải có khả năng thực hiện các công việc thi công và bảo trì khi cần thiết, đồng thời phải có trình độ kỹ năng phù hợp trong việc vận hành các thiết bị liên quan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The supervisor assists in the hiring and training of subordinates and works with division leaders to conduct evaluations and yearly performance reviews of crew members.\", \"vi\": \"Người giám sát hỗ trợ công tác tuyển dụng và đào tạo cấp dưới, đồng thời phối hợp với các trưởng bộ phận để tiến hành đánh giá và thẩm định hiệu suất công việc hàng năm của các thành viên trong đội ngũ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Crucially, the supervisor instructs crew members in safety procedures and monitors the safety of works in progress.\", \"vi\": \"Điều quan trọng là, người giám sát hướng dẫn các thành viên trong đội về các quy trình an toàn và giám sát việc đảm bảo an toàn cho các công việc đang được tiến hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The supervisor informs the division director of major personnel problems; the director will recommend an appropriate course of action in all instances.\", \"vi\": \"Người giám sát sẽ báo cáo với giám đốc phòng về các vấn đề nhân sự nghiêm trọng; giám đốc sẽ đề xuất phương án xử lý phù hợp trong mọi trường hợp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Significant concerns raised by employees are brought to the attention of division leaders by the supervisor, who functions as a liaison between crew members and the Division of Administrative Services.\", \"vi\": \"Các vấn đề đáng quan ngại do nhân viên nêu ra sẽ được người giám sát chuyển đến các lãnh đạo phòng ban; người giám sát đóng vai trò là cầu nối giữa các thành viên trong đội ngũ và Phòng Dịch vụ Hành chính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Managing the division\'s designated budget is a critical aspect of the position.\", \"vi\": \"Việc quản lý ngân sách được phân bổ cho bộ phận là một khía cạnh quan trọng của vị trí này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The supervisor shows proficiency in the use of computers to keep track of the budget each month.\", \"vi\": \"Người giám sát thể hiện sự thành thạo trong việc sử dụng máy tính để theo dõi ngân sách hàng tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The supervisor prepares expenditure reports and time sheets as well as statistical and narrative reports related to maintenance and repair activities, being sure to record the amount of time, number of employees, and materials used for each activity.\", \"vi\": \"Người giám sát chịu trách nhiệm lập các báo cáo chi tiêu và bảng chấm công, cũng như các báo cáo thống kê và báo cáo tường thuật liên quan đến các hoạt động bảo trì và sửa chữa, đồng thời đảm bảo ghi chép đầy đủ thời gian, số lượng nhân viên và vật tư được sử dụng cho từng hoạt động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '721e6f6c-ba9a-47c4-bb27-bc992b6165b8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Wonder Ridge Radio Broadcast Schedule, Monday–Friday\", \"vi\": \"Lịch phát sóng của Đài phát thanh Wonder Ridge, từ Thứ Hai đến Thứ Sáu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"6 A.M.–Noon - Noon–4 P.M. - 4 P.M.–7 P.M. - 7 P.M.–10 P.M.\", \"vi\": \"6 giờ sáng – 12 giờ trưa - 12 giờ trưa – 4 giờ chiều - 4 giờ chiều – 7 giờ tối - 7 giờ tối – 10 giờ tối\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"COFFEE BREAK - AFTERNOON JAZZ - FOLK FRENZY - JOSIE\'S JOINT\", \"vi\": \"GIỜ NGHỈ UỐNG CÀ PHÊ - NHẠC JAZZ BUỔI CHIỀU - CUỘC SÔI NỔI CỦA NHẠC DÂN GIAN - QUÁN CỦA JOSIE\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Local news and interviews with community members - Music from traditional jazz to jazz fusion - Folk music from around the world - Modern sounds selected by our station\'s own music director\", \"vi\": \"Tin tức địa phương và các cuộc phỏng vấn với các thành viên trong cộng đồng - Âm nhạc từ jazz truyền thống đến jazz fusion - Âm nhạc dân gian từ khắp nơi trên thế giới - Những bản nhạc hiện đại do chính giám đốc âm nhạc của đài chúng tôi tuyển chọn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Host: Felice Finney - Host: Malachi Mzee - Host: Penny Ariza - Host: Josie Jones\", \"vi\": \"Người dẫn chương trình: Felice Finney - Người dẫn chương trình: Malachi Mzee - Người dẫn chương trình: Penny Ariza - Người dẫn chương trình: Josie Jones\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"To: feedback@wonderridgeradio.org\", \"vi\": \"Gửi tới: feedback@wonderridgeradio.org\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"From: pfabre@sendmail.net\", \"vi\": \"Nguồn: pfabre@sendmail.net\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Subject: My new radio station!\", \"vi\": \"Chủ đề: Đài phát thanh mới của tôi!\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Date: October 22\", \"vi\": \"Ngày: 22 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To the folks at Wonder Ridge Radio:\", \"vi\": \"Gửi quý vị tại Đài phát thanh Wonder Ridge:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"As I was driving last week, I got tired of listening to sports talk and turned the dial.\", \"vi\": \"Tuần trước, khi đang lái xe, tôi cảm thấy chán nghe chương trình bàn luận về thể thao nên đã chuyển kênh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Suddenly, my car was filled with a song that I hadn\'t heard in many years.\", \"vi\": \"Bỗng dưng, trong xe tôi vang lên một bài hát mà tôi đã không nghe thấy từ nhiều năm nay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"It was traditional music from France, where my grandmother was born.\", \"vi\": \"Đó là nhạc truyền thống của Pháp, nơi bà tôi sinh ra.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"She used to play that song when I was a child.\", \"vi\": \"Hồi tôi còn nhỏ, bà thường hay bật bài hát đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I never expected to hear it on the radio here in Wonder Ridge.\", \"vi\": \"Tôi thật sự không ngờ lại được nghe bài hát đó trên đài phát thanh tại Wonder Ridge này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thanks for this experience and for all your great programs.\", \"vi\": \"Xin cảm ơn quý vị vì trải nghiệm này cũng như tất cả các chương trình tuyệt vời của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Your new fan,\", \"vi\": \"Một người hâm mộ mới của quý vị,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Pierre Fabre\", \"vi\": \"Pierre Fabre\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Wonder Ridge Radio Job Opening: Programming Assistant\", \"vi\": \"Thông báo tuyển dụng tại Đài phát thanh Wonder Ridge: Trợ lý chương trình\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Posted November 2\", \"vi\": \"Đăng ngày 2 tháng 11\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Job Description\", \"vi\": \"Mô tả công việc\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"The programming assistant reports to the director of programming and supports the radio station by performing a variety of research and communication functions.\", \"vi\": \"Trợ lý chương trình trực thuộc Giám đốc chương trình và hỗ trợ đài phát thanh bằng cách thực hiện các nhiệm vụ đa dạng liên quan đến nghiên cứu và truyền thông.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"This role is an entry-level, part-time position.\", \"vi\": \"Vị trí này là một vị trí bán thời gian dành cho người mới bắt đầu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Responsibilities\", \"vi\": \"Nhiệm vụ\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Conducting background research on interviewees\", \"vi\": \"Tiến hành nghiên cứu sơ bộ về các đối tượng được phỏng vấn\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Keeping up-to-date on news and news makers in order to suggest potential topics and guests for on-air interviews\", \"vi\": \"Luôn cập nhật tin tức và các nhân vật nổi bật nhằm đề xuất các chủ đề tiềm năng cũng như khách mời cho các cuộc phỏng vấn trên sóng\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Updating the station\'s Web site and program host biography pages\", \"vi\": \"Cập nhật trang web của đài phát thanh và các trang tiểu sử của người dẫn chương trình\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Using scheduling software to update the broadcast schedule\", \"vi\": \"Sử dụng phần mềm lập lịch để cập nhật lịch phát sóng\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Communicating with listeners, especially via e-mail and social media\", \"vi\": \"Giao tiếp với thính giả, đặc biệt là qua email và các nền tảng mạng xã hội\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"To apply, e-mail a résumé and cover letter to hiring@wonderridgeradio.org.\", \"vi\": \"Để nộp đơn, vui lòng gửi sơ yếu lý lịch và thư xin việc qua email đến địa chỉ hiring@wonderridgeradio.org.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}]' WHERE `id` = '7225dffe-2f9b-40b0-adae-8ec522976221';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"29 July\", \"vi\": \"Ngày 29 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Shari MacCauley\", \"vi\": \"Shari MacCauley\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"103 Easton Lane\", \"vi\": \"103 Easton Lane\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Tomintoul, Ballindalloch AB37 9EX\", \"vi\": \"Tomintoul, Ballindalloch AB37 9EX\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. MacCauley,\", \"vi\": \"Kính gửi bà MacCauley,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"It was a privilege to stay in your home during the week of 22 July as part of the Scottish Connections home exchange program.\", \"vi\": \"Thật là một vinh dự khi được lưu trú tại nhà quý vị trong tuần từ ngày 22 tháng 7, trong khuôn khổ chương trình trao đổi nhà ở Scottish Connections.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The location was the perfect setting for our family gathering.\", \"vi\": \"Địa điểm này thực sự là khung cảnh lý tưởng cho buổi họp mặt gia đình của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"My daughter and son-in-law relished the peace and quiet of the village, while their children enjoyed playing in the wide-open space behind your home.\", \"vi\": \"Con gái và con rể tôi rất thích sự yên bình và tĩnh lặng của ngôi làng, trong khi các cháu của họ thì thích thú vui đùa trong khoảng sân rộng rãi phía sau nhà quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"And my husband was quite pleased with the large-screen television set in the living room.\", \"vi\": \"Và chồng tôi cũng rất hài lòng với chiếc tivi màn hình lớn trong phòng khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"It was very thoughtful of you to provide so many extra blankets.\", \"vi\": \"Quý vị thật chu đáo khi chuẩn bị sẵn rất nhiều chăn dự phòng như vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We did not expect it to be so cold at night in July.\", \"vi\": \"Chúng tôi không ngờ rằng vào ban đêm tháng Bảy lại lạnh đến vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"As I said in the note I left on your dining room table on 25 July, the day of my wedding anniversary party, the lid of your food processor cracked as we were preparing our meal.\", \"vi\": \"Như tôi đã đề cập trong mảnh giấy tôi để lại trên bàn ăn trong phòng khách của quý vị vào ngày 25 tháng 7, cũng là ngày tổ chức tiệc kỷ niệm ngày cưới của tôi, nắp máy xay thực phẩm của quý vị đã bị nứt khi chúng tôi đang chuẩn bị bữa ăn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We ordered a replacement lid that same day, which should be delivered to your home soon, assuming it hasn’t been already.\", \"vi\": \"Chúng tôi đã đặt mua một nắp thay thế ngay trong ngày hôm đó, và sản phẩm này sẽ sớm được giao đến nhà quý khách, trừ khi quý khách đã nhận được rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I sincerely apologize for the mishap.\", \"vi\": \"Tôi xin chân thành xin lỗi về sự cố này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I hope that you and your friends enjoyed our apartment here in Aberdeen just as much as we enjoyed your mountain home.\", \"vi\": \"Tôi hy vọng rằng quý vị và các bạn của quý vị đã tận hưởng căn hộ của chúng tôi tại Aberdeen ở đây một cách trọn vẹn, giống như cách chúng tôi đã tận hưởng ngôi nhà trên núi của quý vị vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"If so, we hope you will be willing to exchange homes with us again in the future.\", \"vi\": \"Nếu vậy, chúng tôi hy vọng quý vị sẽ sẵn lòng trao đổi nhà ở với chúng tôi một lần nữa trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Clara Brinwall\", \"vi\": \"Clara Brinwall\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Clara Brinwall\", \"vi\": \"Clara Brinwall\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '72dfd5a0-6185-486c-ac6a-50396923eefc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Patton Henry <p.henry@xmail.com>\", \"vi\": \"Đến: Patton Henry <p.henry@xmail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Joanna Kanarak <jkanarak@kanarakrealty.com>\", \"vi\": \"Từ: Joanna Kanarak <jkanarak@kanarakrealty.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: December 29\", \"vi\": \"Ngày: 29 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Lease renewal\", \"vi\": \"Chủ đề: Gia hạn hợp đồng thuê nhà\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Henry,\", \"vi\": \"Kính gửi ông Henry,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"My records indicate that your lease is due to expire on March 31.\", \"vi\": \"Hồ sơ của tôi cho thấy hợp đồng thuê nhà của ông sẽ hết hạn vào ngày 31 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"If you wish to renew your ------- (135), please let me know before January 31.\", \"vi\": \"Nếu ông muốn gia hạn ------- (135) của mình, vui lòng cho tôi biết trước ngày 31 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [135]}, {\"en\": \"If you do not reply to this e-mail, ------- (136) will assume that you do not wish to continue living in the 22 Fister Road property.\", \"vi\": \"Nếu ông không trả lời email này, ------- (136) sẽ mặc định rằng ông không muốn tiếp tục sống tại bất động sản 22 Fister Road.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [136]}, {\"en\": \"------- (137), it will be listed as a rental available to a new tenant on April 1.\", \"vi\": \"------- (137), căn hộ này sẽ được đăng quảng cáo cho thuê đối với khách thuê mới vào ngày 1 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [137]}, {\"en\": \"If you want to move to an apartment larger or smaller than your current one, just let me know.\", \"vi\": \"Nếu ông muốn chuyển đến một căn hộ lớn hơn hoặc nhỏ hơn căn hộ hiện tại của mình, cứ cho tôi biết nhé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"------- (138).\", \"vi\": \"------- (138).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [138]}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Joanna Kanarak, Kanarak Realty\", \"vi\": \"Joanna Kanarak, Công ty Bất động sản Kanarak\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '72f7c09a-2679-4e84-9f99-e60b2d4e9930';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Hemel Bookstore is seeking temporary store associates ______[131] the upcoming holiday season.\", \"vi\": \"Hiệu sách Hemel đang tìm kiếm nhân viên cửa hàng thời vụ ______[131] cho mùa lễ hội sắp tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [131]}, {\"en\": \"Duties will include greeting customers and answering questions.\", \"vi\": \"Nhiệm vụ sẽ bao gồm chào đón khách hàng và trả lời các thắc mắc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"______[132].\", \"vi\": \"______[132].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132]}, {\"en\": \"In addition, associates will shelve, clean, and organize merchandise.\", \"vi\": \"Ngoài ra, nhân viên sẽ sắp xếp sách lên kệ, dọn dẹp và tổ chức lại hàng hóa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We want to hire friendly and ______[133] candidates.\", \"vi\": \"Chúng tôi muốn tuyển dụng những ứng viên thân thiện và ______[133].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [133]}, {\"en\": \"To apply, please fill out an online job application at www.hemelbookstore.com/application.\", \"vi\": \"Để ứng tuyển, vui lòng điền vào đơn xin việc trực tuyến tại www.hemelbookstore.com/application.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The ______[134] is October 21.\", \"vi\": \"______[134] là ngày 21 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [134]}]' WHERE `id` = '732ee5d4-aa0e-458f-89a3-b54f9f8f3e67';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Subway Sound to be Upgraded\", \"vi\": \"Hệ thống âm thanh trong tàu điện ngầm sẽ được nâng cấp\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"BOSTON (April 1)—The public address systems at selected subway stations are scheduled to be refurbished, the Transit Authority announced this week.\", \"vi\": \"BOSTON (ngày 1 tháng 4) — Cơ quan Giao thông Công cộng đã thông báo trong tuần này rằng hệ thống loa phát thanh tại một số ga tàu điện ngầm sẽ được tiến hành cải tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The systems are used to make announcements to commuters both on the platforms and in the stations.\", \"vi\": \"Các hệ thống này được sử dụng để phát thông báo cho hành khách cả trên sân ga lẫn trong các nhà ga.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Local commuters welcomed the news, although for some it was long overdue.\", \"vi\": \"Những người đi làm trong khu vực đã hoan nghênh tin tức này, dù đối với một số người, điều này lẽ ra đã phải được thực hiện từ lâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"It can be pretty difficult to understand the announcements at some of the stations I use most frequently,\\\" said Ian Miller, who has taken the subway to work nearly every week for the past eighteen years.\", \"vi\": \"\\\"Việc hiểu các thông báo tại một số ga mà tôi thường xuyên sử dụng nhất có thể khá khó khăn,” ông Ian Miller, người đã đi tàu điện ngầm đi làm gần như mỗi tuần trong suốt mười tám năm qua, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"\\\"I had heard the reports about it on TV, and all I can say is that it is about time!\\\"\", \"vi\": \"\\\"Tôi đã nghe các bản tin về chuyện đó trên truyền hình, và tất cả những gì tôi có thể nói là: Đã đến lúc rồi!\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Some of the systems currently in use are more than 30 years old.\", \"vi\": \"Một số hệ thống hiện đang được sử dụng đã có tuổi đời hơn 30 năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Worn-out speakers, wiring, microphones, and amplifiers will be replaced with new, more reliable devices.\", \"vi\": \"Các loa, hệ thống dây dẫn, micro và bộ khuếch đại đã cũ sẽ được thay thế bằng các thiết bị mới, đáng tin cậy hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The work should be completed in October and cost more than $11 million.\", \"vi\": \"Công trình dự kiến sẽ hoàn thành vào tháng 10 và có tổng chi phí vượt quá 11 triệu đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Boston\'s subway system came together in stages over the course of several years.\", \"vi\": \"Hệ thống tàu điện ngầm của Boston đã được hình thành theo từng giai đoạn trong suốt nhiều năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The foundational component of the system\'s Green Line first opened on Tremont Street in the late 1890s.\", \"vi\": \"Thành phần nền tảng của Tuyến Xanh thuộc hệ thống này lần đầu tiên được đưa vào hoạt động trên đường Tremont vào cuối những năm 1890.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It was the first of its kind in the United States.\", \"vi\": \"Đây là trường hợp đầu tiên thuộc loại này tại Hoa Kỳ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '732f4307-16a0-4f60-81c8-618f8f952054';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Joanna Markian\", \"vi\": \"Từ: Joanna Markian\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All management staff\", \"vi\": \"Đến: Toàn thể nhân viên quản lý\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Meeting with Adacorp leadership\", \"vi\": \"Chủ đề: Cuộc họp với ban lãnh đạo Adacorp\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 11 January\", \"vi\": \"Ngày: 11 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Credulux colleagues,\", \"vi\": \"Gửi các đồng nghiệp tại Credulux,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Please be advised that our Wednesday Board of Directors meeting will focus on the ______[143] company merger with Adacorp Ltd. We will be joined by Adacorp\'s CEO and several managers as well as members of both companies\' legal teams.\", \"vi\": \"Xin lưu ý rằng cuộc họp Hội đồng Quản trị vào thứ Tư của chúng ta sẽ tập trung vào việc sáp nhập công ty ______[143] với Adacorp Ltd. Chúng ta sẽ có sự tham gia của Giám đốc điều hành Adacorp, một số nhà quản lý cũng như các thành viên từ đội ngũ pháp lý của cả hai công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [143]}, {\"en\": \"______[144].\", \"vi\": \"______[144].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [144]}, {\"en\": \"The purpose of this meeting is to clarify the timeline of the merger process.\", \"vi\": \"Mục đích của cuộc họp này là làm rõ mốc thời gian của quá trình sáp nhập.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[145] with questions for our Board of Directors will be given ample time to ask them.\", \"vi\": \"______[145] có các câu hỏi dành cho Hội đồng Quản trị của chúng ta sẽ được dành nhiều thời gian để đặt câu hỏi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [145]}, {\"en\": \"______[146], I would like to request that all nonurgent agenda items be saved for our management team meeting in early February.\", \"vi\": \"______[146], tôi muốn yêu cầu rằng tất cả các nội dung chương trình không khẩn cấp nên được để dành cho cuộc họp nhóm quản lý vào đầu tháng Hai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [146]}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Joanna Markian\", \"vi\": \"Joanna Markian\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '733f5e1d-9652-4d5f-9595-c48b14b48e0b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Beatrix Meijer\", \"vi\": \"Từ: Beatrix Meijer\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To: Andrew Dunham\", \"vi\": \"Kính gửi: Andrew Dunham\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: RE: Kitchen membership\", \"vi\": \"Chủ đề: RE: Tư cách thành viên câu lạc bộ nấu ăn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Date: March 30\", \"vi\": \"Ngày: 30 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Dunham,\", \"vi\": \"Kính gửi ông Dunham,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for your inquiry about restarting your membership in Kelso Kitchen.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã liên hệ để tìm hiểu về việc tiếp tục sử dụng tư cách thành viên tại Kelso Kitchen.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Yes, I remember that you used to use our kitchen space to prepare ingredients for your food truck.\", \"vi\": \"Vâng, tôi nhớ là trước đây anh từng sử dụng khu bếp của chúng tôi để sơ chế nguyên liệu cho xe bán đồ ăn của anh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I am glad to hear that you have opened a restaurant and it is doing well.\", \"vi\": \"Tôi rất vui khi biết rằng quý vị đã mở một nhà hàng và việc kinh doanh đang rất thuận lợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Kelso Kitchen can certainly provide you with space to develop new recipes.\", \"vi\": \"Kelso Kitchen chắc chắn có thể mang đến cho quý vị không gian để sáng tạo những công thức nấu ăn mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The monthly membership fee is now $400.\", \"vi\": \"Phí thành viên hàng tháng hiện nay là 400 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"This entitles you to use one of our fully equipped shared kitchens for up to 30 hours.\", \"vi\": \"Điều này cho phép quý vị sử dụng một trong những nhà bếp chung được trang bị đầy đủ của chúng tôi trong tối đa 30 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Reservations are required and must be made through our online system.\", \"vi\": \"Quý vị cần phải đặt chỗ trước và việc đặt chỗ phải được thực hiện thông qua hệ thống trực tuyến của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Members are allotted two lockable cages for storing their ingredients in, one of which can be kept in our walk-in refrigerator.\", \"vi\": \"Mỗi thành viên sẽ được cấp hai chiếc lồng có khóa để bảo quản nguyên liệu, trong đó một chiếc có thể được đặt trong phòng lạnh của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Remember that you will be expected to clean up your space and wash any cooking implements you have used before your scheduled time ends.\", \"vi\": \"Xin lưu ý rằng quý vị cần dọn dẹp khu vực của mình và rửa sạch tất cả các dụng cụ nấu nướng đã sử dụng trước khi thời gian đã định kết thúc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Since the food you prepare in our facility will not be sold to customers, the only documentation we need from you is proof of liability insurance.\", \"vi\": \"Vì thực phẩm mà quý vị chế biến tại cơ sở của chúng tôi sẽ không được bán cho khách hàng, nên tài liệu duy nhất mà chúng tôi cần quý vị cung cấp là giấy chứng nhận bảo hiểm trách nhiệm dân sự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"You can bring that to our office anytime from 9 a.m. to 5 p.m., Tuesday through Saturday, to begin the process of restarting your membership.\", \"vi\": \"Quý vị có thể mang tài liệu đó đến văn phòng của chúng tôi bất cứ lúc nào trong khung giờ từ 9 giờ sáng đến 5 giờ chiều, từ thứ Ba đến thứ Bảy, để bắt đầu thủ tục khôi phục tư cách thành viên của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Beatrix Meijer\", \"vi\": \"Beatrix Meijer\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '738b1aea-32dc-467f-855e-5a6bc919a983';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Clarence Tibbetts\", \"vi\": \"Từ: Clarence Tibbetts\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Banuelos Financial staff\", \"vi\": \"Đến: Nhân viên tài chính Banuelos\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 8\", \"vi\": \"Ngày: Ngày 8 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Carpeting work\", \"vi\": \"Chủ đề: Công việc trải thảm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"As you all have probably noticed, the carpet in our reception area is quite ______[135].\", \"vi\": \"Như tất cả các bạn có lẽ đã nhận thấy, tấm thảm ở khu vực lễ tân của chúng ta đã khá ______[135].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [135]}, {\"en\": \"It no longer makes a good impression on visitors.\", \"vi\": \"Nó không còn tạo được ấn tượng tốt với khách đến thăm nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"So, I am happy to announce that the office ______[136] on Friday, March 17 as that section of carpet is replaced.\", \"vi\": \"Vì vậy, tôi vui mừng thông báo rằng văn phòng sẽ ______[136] vào thứ Sáu, ngày 17 tháng 3 khi phần thảm đó được thay mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [136]}, {\"en\": \"I have found new carpeting of the same color but made of a more durable material and have hired a contractor to perform the removal and installation.\", \"vi\": \"Tôi đã tìm được loại thảm mới cùng màu nhưng làm bằng chất liệu bền hơn và đã thuê một nhà thầu để thực hiện việc tháo dỡ và lắp đặt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[137] the office is closed, all Banuelos Financial employees must either work from home or use a paid vacation day.\", \"vi\": \"______[137] văn phòng đóng cửa, tất cả nhân viên của Banuelos Financial phải làm việc tại nhà hoặc sử dụng một ngày nghỉ có lương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [137]}, {\"en\": \"______[138].\", \"vi\": \"______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [138]}, {\"en\": \"If you have any questions or concerns about this situation, you may raise them at Monday\'s staff meeting.\", \"vi\": \"Nếu bạn có bất kỳ câu hỏi hoặc thắc mắc nào về tình hình này, bạn có thể nêu chúng ra tại cuộc họp nhân viên vào thứ Hai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '73ec56d4-b67a-4ad0-9ce6-5233bf2a0b18';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Rambling River Festival\", \"vi\": \"Lễ hội Sông Rambling\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Schedule of Musical Events\", \"vi\": \"Lịch trình các sự kiện âm nhạc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Friday, September 8\", \"vi\": \"Thứ Sáu, ngày 8 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"• 3:30 P.M. Johanna Greenblatt\", \"vi\": \"• 3 giờ 30 chiều. Johanna Greenblatt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"• 8:00 P.M. Bethesda Radio Show featuring the Blass Brothers Band (to be recorded at the Bramley Theater)\", \"vi\": \"• 8 giờ tối: Chương trình phát thanh Bethesda với sự góp mặt của ban nhạc Blass Brothers (sẽ được ghi hình tại Nhà hát Bramley)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Saturday, September 9\", \"vi\": \"Thứ Bảy, ngày 9 tháng 9\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"• 6:30 P.M. The Rolling Dozen\", \"vi\": \"• 18 giờ 30. Chương trình “The Rolling Dozen”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"• 7:45 P.M. Jefferson Cage\", \"vi\": \"• 19 giờ 45 phút. Sân Jefferson Cage\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"All events take place at the Bethesda Park Open-Air Stage unless otherwise noted.\", \"vi\": \"Trừ khi có ghi chú khác, tất cả các sự kiện đều diễn ra tại Sân khấu ngoài trời Công viên Bethesda.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Feel free to bring picnic blankets.\", \"vi\": \"Quý vị có thể mang theo chăn dã ngoại nếu muốn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"From Rambling River Festival, Sep 8, 9:14 A.M.\", \"vi\": \"Từ Lễ hội Rambling River, ngày 8 tháng 9, 9 giờ 14 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"This afternoon\'s performance will take place in Cole Hall in anticipation of inclement weather.\", \"vi\": \"Do dự báo thời tiết xấu, buổi biểu diễn chiều nay sẽ diễn ra tại Cole Hall.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Bulky items are not allowed, but coat-check service will be available.\", \"vi\": \"Không được mang theo các vật dụng cồng kềnh, tuy nhiên sẽ có dịch vụ giữ áo khoác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"This evening\'s performance is being pushed to 2:30 P.M. tomorrow; local band Kirschau will perform during the original time slot instead.\", \"vi\": \"Buổi biểu diễn tối nay sẽ được dời sang lúc 2 giờ 30 chiều ngày mai; thay vào đó, ban nhạc địa phương Kirschau sẽ biểu diễn trong khung giờ ban đầu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We expect our full Saturday program to take place at the Bethesda Park Open-Air Stage.\", \"vi\": \"Chúng tôi dự kiến toàn bộ chương trình vào thứ Bảy sẽ diễn ra tại Sân khấu ngoài trời Công viên Bethesda.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '74332c4f-cef6-407c-9bc5-eed2dbca9ba4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Great Dishwasher!\", \"vi\": \"Máy rửa chén thật tuyệt vời!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I never had a dishwasher before.\", \"vi\": \"Trước đây tôi chưa từng có máy rửa chén.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"After remodeling my kitchen, I finally had room for a compact dishwasher.\", \"vi\": \"Sau khi cải tạo lại căn bếp, cuối cùng tôi cũng có đủ không gian để đặt một chiếc máy rửa chén cỡ nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I did a lot of research, and the Dish Magic 300 seemed to be the best choice.\", \"vi\": \"Tôi đã tìm hiểu rất kỹ, và Dish Magic 300 dường như là sự lựa chọn tốt nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"It was pricier than other models, but all of the reviews were excellent.\", \"vi\": \"Mặc dù giá cao hơn so với các mẫu khác, nhưng tất cả các đánh giá đều rất tích cực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"So, I decided to spend the extra money.\", \"vi\": \"Vì vậy, tôi đã quyết định chi thêm số tiền đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I have had the dishwasher for one month now, and I could not be happier with my decision.\", \"vi\": \"Đến nay, tôi đã sử dụng máy rửa chén được một tháng và tôi thực sự rất hài lòng với quyết định của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Most importantly, the dishes come out sparkling clean, no matter how dirty they were going in.\", \"vi\": \"Điều quan trọng nhất là, dù ban đầu bát đĩa có bẩn đến mức nào đi chăng nữa, sau khi rửa xong chúng cũng trở nên sáng bóng như mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Also, the machine is so quiet, you do not even know it is running.\", \"vi\": \"Hơn nữa, chiếc máy này hoạt động rất êm, đến nỗi quý vị thậm chí còn không nhận ra rằng nó đang chạy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Lastly, it is designed to use water efficiently, which is very important to me.\", \"vi\": \"Cuối cùng, sản phẩm này được thiết kế để sử dụng nước một cách hiệu quả, điều này rất quan trọng đối với tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Overall, I am very pleased with this dishwasher.\", \"vi\": \"Nhìn chung, tôi rất hài lòng với chiếc máy rửa chén này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"- Anna Yakovleva\", \"vi\": \"Anna Yakovleva\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '745d6bea-4976-4910-833f-9317571291f8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Managers\", \"vi\": \"Kính gửi: Quý vị các Trưởng phòng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Charlotte Black\", \"vi\": \"Từ: Charlotte Black\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: August 16\", \"vi\": \"Ngày: 16 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Employee of the month\", \"vi\": \"Chủ đề: Nhân viên xuất sắc nhất tháng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Managers,\", \"vi\": \"Kính gửi các Quản lý,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"It is time to vote for the Wilson Autos Employee of the Month for September.\", \"vi\": \"Đã đến lúc bỏ phiếu bình chọn “Nhân viên xuất sắc nhất tháng” của Wilson Autos cho tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Here are the nominees.\", \"vi\": \"Dưới đây là danh sách các ứng viên được đề cử.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Erica Boyd has been with us for only a few months but has already shown great promise and is eager to learn new things.\", \"vi\": \"Erica Boyd mới gia nhập công ty chúng tôi được vài tháng nhưng đã bộc lộ nhiều tiềm năng đáng kỳ vọng và luôn hăng hái học hỏi những điều mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Lauren Almahdi is very proactive.\", \"vi\": \"Lauren Almahdi là một người rất chủ động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"If something needs to be done, she will point it out to a manager and volunteer to take care of it herself.\", \"vi\": \"Nếu có việc gì cần làm, cô ấy sẽ báo cho người quản lý biết và tự nguyện đứng ra giải quyết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Nick Salehi found a glitch in our computer system and stopped us from incorrectly ordering unnecessary inventory (thus saving us money).\", \"vi\": \"Ông Nick Salehi đã phát hiện ra một lỗi trong hệ thống máy tính của chúng tôi và giúp chúng tôi tránh được việc đặt hàng sai lầm những mặt hàng không cần thiết (nhờ đó giúp chúng tôi tiết kiệm được chi phí).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Max Rhodes has been especially helpful with training new hires.\", \"vi\": \"Ông Max Rhodes đã đóng góp rất nhiều trong việc đào tạo các nhân viên mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"He is calm and patient and explains our procedures well.\", \"vi\": \"Ông ấy rất điềm tĩnh và kiên nhẫn, đồng thời giải thích rõ ràng về các quy trình của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please respond to this e-mail by Friday with your vote.\", \"vi\": \"Kính mong quý vị trả lời email này trước thứ Sáu và gửi phiếu bầu của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The winner must receive at least three votes.\", \"vi\": \"Người chiến thắng phải nhận được ít nhất ba phiếu bầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The winner will be posted at our front desk and on our Web site next Monday.\", \"vi\": \"Tên người chiến thắng sẽ được công bố tại quầy lễ tân và trên trang web của chúng tôi vào thứ Hai tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Charlotte Black\", \"vi\": \"Charlotte Black\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"General Manager, Wilson Autos\", \"vi\": \"Tổng Giám đốc, Wilson Autos\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Wilson Autos (Westchester)\", \"vi\": \"Wilson Autos (Westchester)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"★★★★★\", \"vi\": \"★★★★★\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"My wife and I just bought a new Excelera truck at the Wilson Autos Westchester location with the help of Erica Boyd.\", \"vi\": \"Vợ chồng tôi vừa mua một chiếc xe tải Excelera mới tại chi nhánh Wilson Autos ở Westchester với sự hỗ trợ của cô Erica Boyd.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Even though she was new, she was very knowledgeable about all the trucks on the lot that we wanted to test drive.\", \"vi\": \"Dù mới vào làm, cô ấy lại rất am hiểu về tất cả các chiếc xe tải tại bãi xe mà chúng tôi muốn lái thử.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"The few questions she was unable to answer were quickly addressed by her mentor, Max.\", \"vi\": \"Một vài câu hỏi mà cô không thể trả lời đã nhanh chóng được người hướng dẫn của cô, ông Max, giải đáp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"We were very pleased with the customer service and even more delighted when the general manager agreed to sell us the Excelera for the same price that a competing dealership was advertising.\", \"vi\": \"Chúng tôi rất hài lòng với dịch vụ chăm sóc khách hàng và còn vui mừng hơn nữa khi tổng giám đốc đồng ý bán cho chúng tôi chiếc Excelera với mức giá tương đương mức giá mà một đại lý đối thủ đang quảng cáo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I highly recommend Wilson Autos if you are in the market for a new vehicle!\", \"vi\": \"Nếu quý vị đang có ý định mua một chiếc xe mới, tôi xin nhiệt liệt giới thiệu Wilson Autos!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"—Henry Riggs, August 22\", \"vi\": \"—Henry Riggs, ngày 22 tháng 8\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"https://www.westchesterreviews.com\", \"vi\": \"https://www.westchesterreviews.com\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"The employee of the month for September is ERICA BOYD!\", \"vi\": \"Nhân viên xuất sắc nhất tháng 9 là ERICA BOYD!\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"In her three months at Wilson Autos, Erica has picked up new skills quickly and is always trying to learn more.\", \"vi\": \"Trong ba tháng làm việc tại Wilson Autos, Erica đã nhanh chóng tiếp thu được những kỹ năng mới và luôn nỗ lực học hỏi thêm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"She has become very knowledgeable about our inventory and is able to share her knowledge with customers to complete sales.\", \"vi\": \"Cô ấy đã nắm rất rõ về hàng tồn kho của chúng tôi và có thể chia sẻ kiến thức của mình với khách hàng để chốt đơn hàng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"She has also been instrumental in encouraging satisfied customers to post comments on our social media pages.\", \"vi\": \"Cô ấy cũng đã đóng vai trò quan trọng trong việc khuyến khích những khách hàng hài lòng đăng bình luận trên các trang mạng xã hội của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"We received more great reviews in the past month than we did in the four previous months combined!\", \"vi\": \"Trong tháng vừa qua, chúng tôi đã nhận được nhiều đánh giá tích cực hơn so với tổng số đánh giá tích cực trong bốn tháng trước đó cộng lại!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Erica has received a $50 gift card to Alonzo’s Restaurant as a thank-you for her excellent work.\", \"vi\": \"Erica đã nhận được một thẻ quà tặng trị giá 50 đô la tại Nhà hàng Alonzo’s như một lời cảm ơn dành cho những đóng góp xuất sắc của cô.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Congratulations, Erica!\", \"vi\": \"Xin chúc mừng, Erica!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '746eac99-7cf3-46e4-b096-c533edf9d23c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"FOR IMMEDIATE RELEASE Contact: Sherylin Stevens, sstevens@tearsoncorp.ca\", \"vi\": \"THÔNG CÁO BÁO CHÍ PHÁT HÀNH NGAY LẬP TỨC. Liên hệ: Sherylin Stevens, sstevens@tearsoncorp.ca\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"CALGARY (2 November)—Yves Vernier, the Chief Information Officer of the Tearson Corporation, announced on Monday that 200 robots will soon appear in Tearson\'s grocery stores.\", \"vi\": \"CALGARY (ngày 2 tháng 11) — Ông Yves Vernier, Giám đốc Công nghệ Thông tin của Tập đoàn Tearson, đã thông báo vào thứ Hai rằng 200 con robot sẽ sớm được đưa vào hoạt động tại các siêu thị của Tearson.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The robots, which are all named Bailey, will be used to locate areas where boxes or bottles have fallen and broken, spilling cereal, juice, or other substances onto the floor.\", \"vi\": \"Các robot này, tất cả đều được đặt tên là Bailey, sẽ được sử dụng để xác định các khu vực nơi các hộp hoặc chai lọ đã rơi xuống và vỡ, làm đổ ngũ cốc, nước ép hoặc các chất lỏng khác ra sàn nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The robots will report the spills so that the locations can be cleaned by store employees before they become safety hazards.\", \"vi\": \"Các robot sẽ báo cáo các vụ tràn chất lỏng để nhân viên cửa hàng có thể tiến hành vệ sinh các khu vực đó trước khi chúng trở thành mối nguy hiểm về an toàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The robots were tested in Calgary, where Tearson\'s head office is located.\", \"vi\": \"Các robot này đã được thử nghiệm tại Calgary, nơi đặt trụ sở chính của Tearson.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"During the eighteen-month pilot programme, store managers consistently gave the robots high marks.\", \"vi\": \"Trong suốt chương trình thí điểm kéo dài mười tám tháng, các quản lý cửa hàng đã liên tục dành những đánh giá cao cho các robot.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Although the robots have been used in the company\'s warehouses for several years, this will be their first time working in stores and interacting with customers.\", \"vi\": \"Mặc dù các robot này đã được sử dụng trong các kho hàng của công ty trong vài năm qua, nhưng đây sẽ là lần đầu tiên chúng làm việc tại các cửa hàng và tương tác với khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"All Tearson stores should have the robots by the beginning of December.\", \"vi\": \"Tất cả các cửa hàng Tearson dự kiến sẽ có sẵn các robot này vào đầu tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"For more information, visit Tearson Corporation at www.tearsoncorporation.ca.\", \"vi\": \"Để biết thêm thông tin, quý vị vui lòng truy cập trang web của Tearson Corporation tại địa chỉ www.tearsoncorporation.ca.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '7477574a-c80f-444c-8e69-7bb8380fd8d0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Get ready to take your business skills to the next level with a full day of workshops hosted by Build Business Best (BBB)!\", \"vi\": \"Hãy sẵn sàng nâng tầm kỹ năng kinh doanh của quý vị lên một tầm cao mới với chuỗi hội thảo kéo dài cả ngày do Build Business Best (BBB) tổ chức!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Our next workshop series will take place at the Oakridge Conference Center on Wednesday, April 22.\", \"vi\": \"Chuỗi hội thảo tiếp theo của chúng tôi sẽ diễn ra tại Trung tâm Hội nghị Oakridge vào thứ Tư, ngày 22 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"All of our instructors are BBB members as well as experienced professionals.\", \"vi\": \"Tất cả các giảng viên của chúng tôi đều là thành viên của BBB đồng thời là những chuyên gia giàu kinh nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Hubert Wong is back with our most popular workshop on how to create a business plan, either for a new business or as an expansion of your existing business.\", \"vi\": \"Hubert Wong đã trở lại với khóa học được ưa chuộng nhất của chúng tôi về cách lập kế hoạch kinh doanh, dành cho cả doanh nghiệp mới thành lập lẫn việc mở rộng quy mô doanh nghiệp hiện tại của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We’ll also have workshops by Claire Ladner, Isaac Tineo, and Mei Han.\", \"vi\": \"Chúng tôi cũng sẽ tổ chức các buổi hội thảo do Claire Ladner, Isaac Tineo và Mei Han dẫn dắt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Those will be followed by the last session, in which you’ll learn about conflict resolution through role-playing in small groups.\", \"vi\": \"Tiếp theo đó sẽ là buổi học cuối cùng, trong đó quý vị sẽ tìm hiểu về cách giải quyết xung đột thông qua hoạt động đóng vai theo nhóm nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The fee for the entire day of workshops is $85, and this includes an on-site catered lunch.\", \"vi\": \"Phí tham dự các buổi hội thảo trong cả ngày là 85 đô la, bao gồm bữa trưa được phục vụ tại chỗ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If you have any special dietary needs, please let us know in advance.\", \"vi\": \"Nếu quý khách có bất kỳ yêu cầu đặc biệt nào về chế độ ăn uống, xin vui lòng thông báo cho chúng tôi biết trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Registration for BBB members opens on March 3 and for the general public on March 10.\", \"vi\": \"Việc đăng ký dành cho các thành viên BBB sẽ bắt đầu vào ngày 3 tháng 3 và dành cho công chúng vào ngày 10 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"A link will be added to this page as well as the home page when registration is open.\", \"vi\": \"Khi đợt đăng ký bắt đầu, một liên kết sẽ được thêm vào trang này cũng như trang chủ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"▶\", \"vi\": \"▶\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"◀\", \"vi\": \"◀\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"http://www.buildbusinessbest.com/workshops\", \"vi\": \"http://www.buildbusinessbest.com/workshops\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"▲\", \"vi\": \"▲\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"HOME\", \"vi\": \"TRANG CHỦ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"OUR MISSION\", \"vi\": \"SỨ MỆNH CỦA CHÚNG TÔI\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"WORKSHOP\", \"vi\": \"HỘI THẢO\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"MEMBERSHIP\", \"vi\": \"THÀNH VIÊN\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"CONTACT\", \"vi\": \"LIÊN HỆ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"To: Isaac Tineo <i.tineo@wdmail.com>\", \"vi\": \"Gửi tới: Isaac Tineo <i.tineo@wdmail.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"From: Darlene Mendoza <mendozad@buildbusinessbest.com>\", \"vi\": \"Từ: Darlene Mendoza <mendozad@buildbusinessbest.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Date: April 25\", \"vi\": \"Ngày: 25 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Subject: Survey response\", \"vi\": \"Chủ đề: Phản hồi khảo sát\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Dear Mr. Tineo,\", \"vi\": \"Kính gửi ông Tineo,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I’d like to thank you once again for agreeing to teach in our most recent workshop series.\", \"vi\": \"Tôi xin được một lần nữa gửi lời cảm ơn quý vị vì đã đồng ý giảng dạy trong chuỗi hội thảo gần đây nhất của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"We hope you will be able to contribute to one of our events again.\", \"vi\": \"Chúng tôi hy vọng quý vị sẽ có thể tiếp tục đóng góp cho một trong các sự kiện của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I’ve attached a survey response for your reference.\", \"vi\": \"Tôi đã đính kèm bản trả lời khảo sát để quý vị tham khảo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Many other students had similar remarks about your session on how to manage work-related stress in the workplace.\", \"vi\": \"Nhiều sinh viên khác cũng có những nhận xét tương tự về buổi chia sẻ của quý vị về cách quản lý căng thẳng liên quan đến công việc tại nơi làm việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"As young professionals make up the majority of our participants, providing key skills to support their career success is very important.\", \"vi\": \"Vì các chuyên gia trẻ chiếm phần lớn số lượng người tham gia của chúng tôi, nên việc trang bị cho họ những kỹ năng thiết yếu để hỗ trợ sự thành công trong sự nghiệp là vô cùng quan trọng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I am happy to send more comments once I have everything organized.\", \"vi\": \"Tôi rất sẵn lòng gửi thêm ý kiến sau khi đã sắp xếp xong mọi việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"All the best,\", \"vi\": \"Chúc quý vị mọi điều tốt đẹp nhất,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Darlene Mendoza\", \"vi\": \"Darlene Mendoza\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Activity Coordinator, Build Business Best\", \"vi\": \"Điều phối viên Hoạt động, Build Business Best\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"☐\", \"vi\": \"☐\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"*E-Mail*\", \"vi\": \"*Email*\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"□\", \"vi\": \"□\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"BBB Workshop Series Feedback Survey\", \"vi\": \"Khảo sát ý kiến phản hồi về Chuỗi hội thảo BBB\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Name: Felix Roland\", \"vi\": \"Họ và tên: Felix Roland\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Attendance Date: April 22\", \"vi\": \"Ngày tham dự: 22 tháng 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"How likely are you to recommend BBB Workshops to others?\", \"vi\": \"Quý vị có khả năng giới thiệu các khóa học của BBB cho người khác ở mức độ nào?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"☒ Very Likely ☐ Somewhat Likely ☐ Not Likely\", \"vi\": \"☒ Rất có khả năng ☐ Khá có khả năng ☐ Không có khả năng\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"On a scale of 1 (Not Satisfied) to 5 (Very Satisfied), how would you rate the following categories?\", \"vi\": \"Trên thang điểm từ 1 (Không hài lòng) đến 5 (Rất hài lòng), quý vị sẽ đánh giá các hạng mục sau đây như thế nào?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Sign-Up Process: 4\", \"vi\": \"Quy trình đăng ký: 4\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Handouts: 4\", \"vi\": \"Tài liệu phát tay: 4\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"Classroom Atmosphere: 2\", \"vi\": \"Bầu không khí trong lớp học: 2\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"Instructors’ Knowledge: 5\", \"vi\": \"Kiến thức của giảng viên: 5\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 46, \"question_numbers\": []}, {\"en\": \"Workshop Timing: 5\", \"vi\": \"Thời gian tổ chức hội thảo: 5\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 47, \"question_numbers\": []}, {\"en\": \"Lunch: 5\", \"vi\": \"Bữa trưa: 5\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 48, \"question_numbers\": []}, {\"en\": \"Comments:\", \"vi\": \"Bình luận:\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 49, \"question_numbers\": []}, {\"en\": \"Overall, I believe I learned a lot from these sessions, though I had to miss the last session due to being called away on an urgent work matter.\", \"vi\": \"Nhìn chung, tôi tin rằng mình đã học hỏi được rất nhiều từ các buổi học này, mặc dù tôi đã phải vắng mặt trong buổi học cuối cùng do phải giải quyết một công việc khẩn cấp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 50, \"question_numbers\": []}, {\"en\": \"I thought the workshop on managing stress related to work was the most helpful one.\", \"vi\": \"Tôi cho rằng buổi hội thảo về cách quản lý căng thẳng liên quan đến công việc là buổi hữu ích nhất.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 51, \"question_numbers\": []}, {\"en\": \"My only complaint was that the classroom was very hot.\", \"vi\": \"Điều duy nhất tôi cảm thấy không hài lòng là trong lớp học rất nóng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 52, \"question_numbers\": []}, {\"en\": \"This was somewhat distracting at times.\", \"vi\": \"Điều này đôi khi khiến người ta hơi mất tập trung.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 53, \"question_numbers\": []}]' WHERE `id` = '747920dd-7e4d-4586-ae7a-1cb1a337519f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Color - Product Number\", \"vi\": \"Màu sắc - Mã sản phẩm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Lawnwood Blue - (#302)\", \"vi\": \"Lawnwood Blue - (#302)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Charcoal Bliss - (#702)\", \"vi\": \"Charcoal Bliss - (#702)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Foxwood Gray - (#704)\", \"vi\": \"Foxwood Gray - (#704)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Mission Gray - (#707)\", \"vi\": \"Nhiệm vụ Gray - (#707)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Cedarwood - (#203)\", \"vi\": \"Gỗ tuyết tùng - (#203)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Hickory Nut - (#209)\", \"vi\": \"Hickory Nut - (#209)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Brick Red - (#505)\", \"vi\": \"Màu đỏ gạch - (#505)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Shingle Town Roofing\", \"vi\": \"Công ty Lợp mái Shingle Town\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Color Options\", \"vi\": \"Các tùy chọn màu sắc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Choose from our many colors of high-quality, affordable shingles for a long-lasting, beautiful roof.\", \"vi\": \"Hãy lựa chọn trong số nhiều màu sắc đa dạng của các tấm lợp chất lượng cao, giá cả phải chăng của chúng tôi để có được một mái nhà bền đẹp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Joanne Westley\", \"vi\": \"Joanne Westley\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"8021 Daffodil Lane\", \"vi\": \"8021 Đường Daffodil\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Herndon, Virginia 22090\", \"vi\": \"Herndon, Virginia 22090\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Dear Ms. Westley,\", \"vi\": \"Kính gửi bà Westley,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"This is to confirm our agreement to replace your roof in Herndon, Virginia, on August 4.\", \"vi\": \"Thư này nhằm xác nhận thỏa thuận của chúng tôi về việc thay mới mái nhà của quý vị tại Herndon, Virginia, vào ngày 4 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"As discussed, we will be using our exclusive Prime Technology System with Hickory Nut color shingles.\", \"vi\": \"Như đã thảo luận, chúng tôi sẽ sử dụng Hệ thống Công nghệ Prime độc quyền của mình kết hợp với các tấm lợp màu Hickory Nut.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The Prime Technology System is guaranteed to keep your house dry and has a ten-year warranty for labor and materials.\", \"vi\": \"Hệ thống Prime Technology đảm bảo sẽ giữ cho ngôi nhà của quý vị luôn khô ráo và đi kèm với chế độ bảo hành 10 năm cho cả nhân công và vật liệu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Our crew will arrive at 8:30 A.M. We have received your deposit and signed contract.\", \"vi\": \"Đội ngũ nhân viên của chúng tôi sẽ có mặt vào lúc 8 giờ 30 sáng. Chúng tôi đã nhận được khoản đặt cọc và bản hợp đồng đã được ký kết của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"The remainder of the charge is due upon completion of the job.\", \"vi\": \"Số tiền còn lại sẽ phải thanh toán khi công việc hoàn tất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Please contact us if you have any questions.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào, xin vui lòng liên hệ với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Martin Sage\", \"vi\": \"Martin Sage\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Martin Sage, customer service representative\", \"vi\": \"Ông Martin Sage, nhân viên dịch vụ khách hàng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Shingle Town Roofing\", \"vi\": \"Công ty Lợp mái Shingle Town\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Shingle Town Roofing: Installation Schedule for August 1–7\\nNote to installation crew: Be sure to confirm the job location and the required materials.\", \"vi\": \"Shingle Town Roofing: Lịch thi công từ ngày 1 đến ngày 7 tháng 8\\nLưu ý dành cho đội thi công: Vui lòng xác nhận kỹ địa điểm thi công và các vật liệu cần thiết.\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Sunday - Monday - Tuesday - Wednesday - Thursday - Friday - Saturday\", \"vi\": \"Chủ nhật - Thứ Hai - Thứ Ba - Thứ Tư - Thứ Năm - Thứ Sáu - Thứ Bảy\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"1 - 2\\nHarris residence (#702) - 3\\nLandsford Apartments E-3 (#505) - 4\\nWestley residence (#209) - 5\\nKendelwood Motel (#302) - 6\\nHopewell Gardens (#704) - 7\\nHopewell Gardens (#704)\", \"vi\": \"1 - 2\\nNhà riêng của gia đình Harris (số 702) - 3\\nKhu căn hộ Landsford E-3 (số 505) - 4\\nNhà riêng Westley (phòng số 209) - 5\\nNhà nghỉ Kendelwood (phòng số 302) - 6\\nHopewell Gardens (phòng số 704) - 7\\nHopewell Gardens (phòng số 704)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '748e37ba-798a-4ad7-b5d7-867bc53ab1b7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Marketing Department, Tavola Foods Distributors\", \"vi\": \"Đến: Phòng Tiếp thị, Công ty Phân phối Thực phẩm Tavola\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Victor Cotillo\", \"vi\": \"Từ: Victor Cotillo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 4\", \"vi\": \"Ngày: Ngày 4 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Please look at the proposed survey that was just added to our team folder.\", \"vi\": \"Vui lòng xem bản khảo sát đề xuất vừa được thêm vào thư mục nhóm của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The first section asks ___135___ to rate their favorite vegetables.\", \"vi\": \"Phần đầu tiên yêu cầu ___135___ đánh giá các loại rau củ yêu thích của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [135]}, {\"en\": \"We felt shoppers might prefer a particular vegetable only if it is fresh and in season.\", \"vi\": \"Chúng tôi cho rằng người mua sắm có thể thích một loại rau cụ thể chỉ khi nó tươi và đúng mùa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"___136___ , we also ask what frozen vegetables they buy most frequently and why.\", \"vi\": \"___136___ , chúng tôi cũng hỏi họ mua loại rau đông lạnh nào thường xuyên nhất và tại sao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [136]}, {\"en\": \"In addition, we ___137___ a series of questions about food preparation and convenience.\", \"vi\": \"Ngoài ra, chúng tôi ___137___ một loạt câu hỏi về cách chế biến món ăn và sự tiện lợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [137]}, {\"en\": \"We feel this survey will give us a better picture of what our customers want.\", \"vi\": \"Chúng tôi cảm thấy bản khảo sát này sẽ mang lại cho chúng ta cái nhìn rõ ràng hơn về những gì khách hàng muốn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Please look over everything and quickly respond with any thoughts.\", \"vi\": \"Vui lòng xem xét mọi thứ và nhanh chóng phản hồi nếu có bất kỳ ý kiến nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"___138___ .\", \"vi\": \"___138___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [138]}]' WHERE `id` = '749b6862-5440-4aa9-bab5-222a54aed409';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"ZELL\", \"vi\": \"Hãy xem\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Exteriors\", \"vi\": \"Ngoại thất\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Zell Exteriors\' metal roofing products offer many advantages over traditional roofing materials.\", \"vi\": \"Các sản phẩm mái lợp kim loại của Zell Exteriors mang lại nhiều ưu điểm so với các vật liệu lợp mái truyền thống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Benefit 1–Weather resistance:\", \"vi\": \"Ưu điểm 1 – Khả năng chống chịu thời tiết:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Technology that provides greater protection from hail, wind, and rain\", \"vi\": \"Công nghệ mang lại khả năng bảo vệ tốt hơn trước mưa đá, gió và mưa\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Benefit 2–Wide selection:\", \"vi\": \"Lợi ích 2 – Sự lựa chọn đa dạng:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Large selection of panel types, trim options, and paint colors to choose from\", \"vi\": \"Có rất nhiều loại tấm ốp, tùy chọn viền trang trí và màu sơn để quý vị lựa chọn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Benefit 3–Satisfaction guarantee:\", \"vi\": \"Lợi ích 3 – Đảm bảo sự hài lòng:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"30-year warranty for added peace of mind\", \"vi\": \"Bảo hành 30 năm để quý vị thêm yên tâm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Benefit 4–Established reputation: Quality roofing from a trusted company\", \"vi\": \"Lợi ích 4 – Danh tiếng đã được khẳng định: Hệ thống mái nhà chất lượng cao từ một công ty đáng tin cậy\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"For questions about specific products or to request a quote from our sales staff, complete our online contact form.\", \"vi\": \"Nếu quý vị có thắc mắc về các sản phẩm cụ thể hoặc muốn yêu cầu báo giá từ đội ngũ nhân viên kinh doanh của chúng tôi, xin vui lòng điền vào biểu mẫu liên hệ trực tuyến của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"All our roofing panels are fabricated at one of our regional manufacturing facilities, precut to the necessary dimensions for your roof, and shipped to a branch near you.\", \"vi\": \"Tất cả các tấm lợp của chúng tôi đều được sản xuất tại một trong các nhà máy sản xuất khu vực của chúng tôi, được cắt sẵn theo kích thước phù hợp với mái nhà của quý vị, và sau đó được vận chuyển đến chi nhánh gần quý vị nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Our professional installers will then take it from there.\", \"vi\": \"Sau đó, đội ngũ kỹ thuật viên lắp đặt chuyên nghiệp của chúng tôi sẽ tiếp quản công việc từ đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Name:   Gus Keenan\", \"vi\": \"Họ tên:   Gus Keenan\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"E-mail:   g.keenan@autoewrite.net\", \"vi\": \"Email:   g.keenan@autoewrite.net\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Phone:   555-0188\", \"vi\": \"Điện thoại:   555-0188\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Comments:\", \"vi\": \"Bình luận:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I have been looking at various roofing materials, and the wide range of paint options makes your company my top choice.\", \"vi\": \"Tôi đã tìm hiểu về nhiều loại vật liệu lợp mái khác nhau, và với sự đa dạng về các lựa chọn màu sơn, công ty của quý vị đã trở thành sự lựa chọn hàng đầu của tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"My shed building is an odd shade of purple, and I want to find a color that complements it.\", \"vi\": \"Căn nhà kho của tôi có một tông màu tím khá lạ mắt, và tôi muốn tìm một màu sắc phù hợp với nó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"But I have a question.\", \"vi\": \"Tuy nhiên, tôi có một câu hỏi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I would like the new metal roof to be placed on top of the old shingle roof I have.\", \"vi\": \"Tôi mong muốn mái tôn mới được lắp đặt lên trên lớp mái lợp ngói cũ hiện có của tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"This would save money on time, labor, and disposal.\", \"vi\": \"Điều này sẽ giúp tiết kiệm chi phí về thời gian, nhân công và xử lý chất thải.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Is that something you recommend?\", \"vi\": \"Đó có phải là điều mà quý vị khuyên nên làm không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I have spent a lot of time reading online forums for professional contractors, and there are mixed opinions about this.\", \"vi\": \"Tôi đã dành rất nhiều thời gian để đọc các diễn đàn trực tuyến dành cho các nhà thầu chuyên nghiệp, và có nhiều ý kiến trái chiều về vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"To: g.keenan@autoewrite.net\", \"vi\": \"Gửi tới: g.keenan@autoewrite.net\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"From: nshertz@zellexteriors.com\", \"vi\": \"Nguồn: nshertz@zellexteriors.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date: May 20\", \"vi\": \"Ngày: 20 tháng 5\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Subject: Roofing Inquiry\", \"vi\": \"Chủ đề: Yêu cầu tư vấn về lợp mái\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Zell Exteriors catalog\", \"vi\": \"Tệp đính kèm: 📎 Sổ tay sản phẩm Zell Exteriors\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Dear Mr. Keenan,\", \"vi\": \"Kính gửi ông Keenan,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"A sales representative will contact you by phone within 48 hours, but first please look over the attached product catalog.\", \"vi\": \"Một nhân viên kinh doanh sẽ liên hệ với quý vị qua điện thoại trong vòng 48 giờ, nhưng trước tiên, xin quý vị vui lòng xem qua danh mục sản phẩm đính kèm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Here are the four basic roofing types that we offer:\", \"vi\": \"Dưới đây là bốn loại mái nhà cơ bản mà chúng tôi cung cấp:\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"SLP Snap Lock – Steel panels with a locking feature that enables rapid installation.\", \"vi\": \"SLP Snap Lock – Các tấm thép có cơ chế khóa giúp lắp đặt nhanh chóng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"XM Panel – Aluminum panels with superior corrosion resistance.\", \"vi\": \"XM Panel – Tấm nhôm có khả năng chống ăn mòn vượt trội.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Ideal for wet climates.\", \"vi\": \"Rất phù hợp với khí hậu ẩm ướt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"QR Rigid – Low-cost panels that can be installed directly on top of an existing roof.\", \"vi\": \"QR Rigid – Các tấm lợp giá thành thấp có thể lắp đặt trực tiếp lên trên mái nhà hiện có.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"WT Panel – Our most durable commercial-grade steel.\", \"vi\": \"Tấm WT – Loại thép cấp thương mại có độ bền cao nhất của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Available only in white and gray.\", \"vi\": \"Chỉ có sẵn hai màu trắng và xám.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Nicola Shertz, Administrative Assistant, Zell Exteriors\", \"vi\": \"Nicola Shertz, Trợ lý Hành chính, Zell Exteriors\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}]' WHERE `id` = '74a3398f-f6ba-4427-8c7b-3e531aedf034';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Improvements to Bellamy Parkway Scheduled\", \"vi\": \"Kế hoạch cải tạo Đại lộ Bellamy đã được lên lịch\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"(March 10)—Over the next several weeks, the Grovert Department of Transportation will oversee improvements to some of Bellamy Parkway\'s major intersections between Colwell Street and Hines Creek Drive.\", \"vi\": \"(Ngày 10 tháng 3) — Trong vài tuần tới, Sở Giao thông Vận tải Grovert sẽ giám sát việc cải tạo một số nút giao thông chính trên đường Bellamy Parkway, nằm giữa đường Colwell và đường Hines Creek Drive.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The parkway will be widened around each intersection to create turn lanes for both left and right turns, and dedicated stoplights will be added to control the left-turn lanes.\", \"vi\": \"Đoạn đường công viên sẽ được mở rộng tại khu vực xung quanh mỗi ngã tư nhằm tạo ra các làn đường rẽ cả sang trái lẫn sang phải, đồng thời sẽ lắp đặt thêm các đèn tín hiệu giao thông riêng biệt để điều tiết các làn đường rẽ trái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"\\\"Separate turn lanes will allow traffic to flow smoothly instead of building up behind cars that are waiting to make a turn,\\\" explained Rod Thornton, the department\'s director.\", \"vi\": \"\\\"Các làn đường rẽ riêng biệt sẽ giúp giao thông lưu thông thông suốt thay vì ùn ứ phía sau những chiếc xe đang chờ rẽ,\\\" ông Rod Thornton, Giám đốc Sở, giải thích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"As the city\'s population has grown, this has become a problem, particularly during rush hour and near Rock Hills Elementary School.\\\"\", \"vi\": \"\\\"Khi dân số thành phố ngày càng gia tăng, vấn đề này đã trở nên nghiêm trọng, đặc biệt là vào giờ cao điểm và khu vực gần Trường Tiểu học Rock Hills.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Frustrated Grovert voters approved a short-term increase in the city\'s property taxes to pay for the $1.8 million project.\", \"vi\": \"Các cử tri tại Grovert, trong tâm trạng thất vọng, đã thông qua việc tăng thuế bất động sản của thành phố trong ngắn hạn nhằm tài trợ cho dự án trị giá 1,8 triệu đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"During the improvements to each intersection, two of the parkway\'s four lanes will be closed to traffic to provide space for work crews and equipment.\", \"vi\": \"Trong quá trình cải tạo từng nút giao thông, hai trong số bốn làn đường của tuyến đường công viên sẽ bị đóng cửa để nhường chỗ cho đội thi công và thiết bị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Drivers who take Bellamy Parkway frequently should visit the Department of Transportation\'s Web site to check the roadwork schedule.\", \"vi\": \"Các tài xế thường xuyên lưu thông trên đường Bellamy Parkway nên truy cập trang web của Sở Giao thông Vận tải để kiểm tra lịch trình thi công.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"BELLAMY PARKWAY IMPROVEMENTS SCHEDULE\", \"vi\": \"LỊCH TRÌNH CẢI TẠO ĐƯỜNG BELLAMY PARKWAY\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"March 14–March 25: Colwell Street intersection\", \"vi\": \"Từ ngày 14 tháng 3 đến ngày 25 tháng 3: Ngã tư đường Colwell\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"March 28–April 8: Hines Creek Drive intersection\", \"vi\": \"Từ ngày 28 tháng 3 đến ngày 8 tháng 4: Ngã tư Hines Creek Drive\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"April 11–April 22: Newton Street intersection\", \"vi\": \"Từ ngày 11 tháng 4 đến ngày 22 tháng 4: Ngã tư đường Newton\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"April 25–May 6: Silva Boulevard intersection\", \"vi\": \"Từ ngày 25 tháng 4 đến ngày 6 tháng 5: Ngã tư Silva Boulevard\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Delays or other changes to this schedule will be announced on the homepage of the Department of Transportation\'s Web site.\", \"vi\": \"Mọi sự chậm trễ hoặc thay đổi khác liên quan đến lịch trình này sẽ được thông báo trên trang chủ của trang web Bộ Giao thông Vận tải.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To: Lillian Magano\", \"vi\": \"Kính gửi: Bà Lillian Magano\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From: Yuriko Fujita\", \"vi\": \"Từ: Yuriko Fujita\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Date: April 7\", \"vi\": \"Ngày: 7 tháng 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Subject: Roadwork reminder\", \"vi\": \"Chủ đề: Thông báo nhắc nhở về công trình sửa chữa đường bộ\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Hi Lillian,\", \"vi\": \"Xin chào Lillian,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I was just looking over the school calendar and noticed that the roadwork on the turnoff to our street starts next Monday, the eleventh.\", \"vi\": \"Tôi vừa xem qua lịch học của trường và nhận thấy rằng công trình sửa chữa đường tại ngã rẽ vào con phố của chúng ta sẽ bắt đầu vào thứ Hai tuần tới, ngày mười một.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Before you leave work today, could you send out an additional reminder to parents about it?\", \"vi\": \"Trước khi quý vị tan sở hôm nay, quý vị có thể gửi thêm một thông báo nhắc nhở đến các bậc phụ huynh về vấn đề này được không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Since it will be taking place so close by, I think it will cause more inconvenience to the school than the upgrades to other sections of the parkway have.\", \"vi\": \"Vì công trình này sẽ được triển khai ngay gần đây, tôi cho rằng nó sẽ gây ra nhiều bất tiện hơn cho nhà trường so với các dự án nâng cấp tại các khu vực khác của đại lộ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"We should warn the parents that school buses may be a little behind schedule in the afternoons, and that those who drive may see delays during pick-up and drop-off.\", \"vi\": \"Chúng ta nên thông báo cho quý phụ huynh biết rằng xe buýt học sinh có thể sẽ chạy chậm hơn lịch trình một chút vào buổi chiều, và những ai đi xe riêng có thể gặp phải tình trạng ùn tắc khi đón và trả học sinh.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Yuriko Fujita\", \"vi\": \"Yuriko Fujita\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Vice Principal\", \"vi\": \"Phó Hiệu trưởng\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '74ee96e1-718b-4115-a46e-10dd3b2ff2a6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Vincent Benedict (9:45 A.M.) Hello.\", \"vi\": \"Vincent Benedict (9 giờ 45 phút sáng) Xin chào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I was given your contact information by my neighbor, Ms. Ryan.\", \"vi\": \"Tôi đã được người hàng xóm của tôi, bà Ryan, cung cấp thông tin liên lạc của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"You did some work in her home yesterday.\", \"vi\": \"Hôm qua, quý vị đã thực hiện một số công việc tại nhà của bà ấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I was wondering if you would be able to move a power outlet in my house.\", \"vi\": \"Tôi đang thắc mắc không biết quý vị có thể di chuyển một ổ cắm điện trong nhà tôi được không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Matt Clayton (9:55 A.M.) We can help with that.\", \"vi\": \"Matt Clayton (9 giờ 55 phút sáng) Chúng tôi có thể hỗ trợ quý vị trong việc này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Where is the outlet?\", \"vi\": \"Ổ cắm ở đâu vậy?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"By the way, I\'m adding my business partner, Denise Bosworth, to this message.\", \"vi\": \"Nhân tiện, tôi xin thêm đối tác kinh doanh của tôi, bà Denise Bosworth, vào danh sách nhận tin nhắn này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Vincent Benedict (9:57 A.M.) It\'s in my living room, near the floor.\", \"vi\": \"Vincent Benedict (9 giờ 57 phút sáng) Nó nằm trong phòng khách của tôi, gần sàn nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I want to move it up.\", \"vi\": \"Tôi muốn đẩy nó lên trên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I am going to have a television screen mounted on my wall, and it will look ugly if there are cords hanging down to the outlet.\", \"vi\": \"Tôi định lắp một chiếc tivi lên tường, và trông sẽ rất mất thẩm mỹ nếu có dây điện thõng xuống ổ cắm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Matt Clayton (10:00 A.M.) OK.\", \"vi\": \"Matt Clayton (10 giờ sáng). Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We can do this type of work for you.\", \"vi\": \"Chúng tôi có thể đảm nhận loại công việc này cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Vincent Benedict (10:02 A.M.) How much would something like that cost?\", \"vi\": \"Vincent Benedict (10 giờ 02 phút sáng) Một thứ như vậy sẽ có giá bao nhiêu?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Matt Clayton (10:03 A.M.) That will probably be between one and two hours of labor.\", \"vi\": \"Matt Clayton (10 giờ 03 phút sáng) Thời gian lao động dự kiến sẽ kéo dài từ một đến hai giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We charge $50 per hour.\", \"vi\": \"Chúng tôi tính phí 50 đô la mỗi giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Denise Bosworth (10:05 A.M.) However, we might find pipes, insulation, or other wiring in the wall once we open it.\", \"vi\": \"Denise Bosworth (10 giờ 05 phút sáng). Tuy nhiên, khi mở tường ra, chúng ta có thể phát hiện thấy các đường ống, lớp cách nhiệt hoặc hệ thống dây điện khác bên trong tường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Vincent Benedict (10:08 A.M.) I understand.\", \"vi\": \"Vincent Benedict (10 giờ 08 phút sáng) Tôi hiểu rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Thank you for the information.\", \"vi\": \"Xin cảm ơn quý vị đã cung cấp thông tin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Are you available to come out and see what needs to be done?\", \"vi\": \"Quý vị có thể đến tận nơi để xem cần phải làm những việc gì không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Matt Clayton (10:12 A.M.) I will have someone from our office get in touch with you by phone to schedule a visit.\", \"vi\": \"Matt Clayton (10 giờ 12 phút sáng) Tôi sẽ nhờ một đồng nghiệp tại văn phòng chúng tôi liên hệ với quý vị qua điện thoại để sắp xếp lịch hẹn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '74f02a28-d636-4ab0-aa6e-296904a69233';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Skyler Airlines employs more than 20,000 people from all over the world.\", \"vi\": \"Hãng hàng không Skyler Airlines hiện có hơn 20.000 nhân viên đến từ khắp nơi trên thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"We\'re growing fast and have many positions available.\", \"vi\": \"Chúng tôi đang phát triển nhanh chóng và có rất nhiều vị trí tuyển dụng đang mở.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] — So regardless of your background, there\'s probably a place for you on our team.\", \"vi\": \"— [1] — Vì vậy, bất kể quý vị có xuất thân như thế nào, chắc chắn sẽ có một vị trí phù hợp dành cho quý vị trong đội ngũ của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Skyler employees enjoy many perks.\", \"vi\": \"Các nhân viên của Skyler được hưởng nhiều quyền lợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [2] — For example, our discount program enables them to fly to any of our destinations for a fraction of the average ticket price.\", \"vi\": \"— [2] — Chẳng hạn, chương trình giảm giá của chúng tôi cho phép quý vị bay đến bất kỳ điểm đến nào trong mạng lưới của chúng tôi với mức giá chỉ bằng một phần nhỏ so với giá vé trung bình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [3] — We offer upward and global mobility, tuition reimbursement, a mentorship program, and a generous compensation package.\", \"vi\": \"— [3] — Chúng tôi mang đến cơ hội thăng tiến và phát triển sự nghiệp trên phạm vi toàn cầu, chính sách hoàn trả học phí, chương trình cố vấn, cùng gói đãi ngộ hấp dẫn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [4]—.\", \"vi\": \"— [4]—.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Annual paid vacations enable a comfortable work-life balance.\", \"vi\": \"Chế độ nghỉ phép hàng năm có lương giúp duy trì sự cân bằng thoải mái giữa công việc và cuộc sống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"It\'s no wonder that Skyler Airlines was named “Best Airline to Work For” by Travel Vista Journal three years in a row.\", \"vi\": \"Không có gì ngạc nhiên khi Hãng hàng không Skyler được Tạp chí Travel Vista vinh danh là “Hãng hàng không có môi trường làm việc tốt nhất” trong ba năm liên tiếp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '754cfc9e-da21-4783-8c1b-9ebe0472f981';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Introduction to Project Management\", \"vi\": \"Giới thiệu về Quản lý dự án\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Online Webinar\", \"vi\": \"Hội thảo trực tuyến\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"18 January, 9 A.M.–2 P.M.\", \"vi\": \"Ngày 18 tháng 1, từ 9 giờ sáng đến 2 giờ chiều\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Presenter: Shrijana Patel\", \"vi\": \"Người trình bày: Shrijana Patel\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Cost: €45\", \"vi\": \"Giá: 45 €\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"(Register by 10 January and receive a 10% discount!)\", \"vi\": \"(Quý vị hãy đăng ký trước ngày 10 tháng 1 để được giảm giá 10%!)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This live webinar offers attendees a better understanding of how to improve the role that project management plays in their organizations.\", \"vi\": \"Hội thảo trực tuyến này giúp quý vị tham dự hiểu rõ hơn về cách nâng cao vai trò của công tác quản lý dự án trong tổ chức của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The presentation will provide the basics of managing projects and workers.\", \"vi\": \"Buổi thuyết trình sẽ trình bày những kiến thức cơ bản về quản lý dự án và nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Participants will learn strategies and best practices to effectively oversee their projects and foster buy-in from key players.\", \"vi\": \"Các học viên sẽ được tìm hiểu các chiến lược và phương pháp hay nhất nhằm giám sát hiệu quả các dự án của mình cũng như thúc đẩy sự ủng hộ từ các bên liên quan chủ chốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Participants will explore a simple step-by-step process for managing projects and learn how to use tools and documents such as scope statements and communication plans.\", \"vi\": \"Các học viên sẽ tìm hiểu một quy trình đơn giản, từng bước một để quản lý dự án và học cách sử dụng các công cụ cũng như tài liệu như bản mô tả phạm vi công việc và kế hoạch truyền thông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The presenter will also cover topics such as developing a project’s business case and facilitating productive team meetings.\", \"vi\": \"Người trình bày cũng sẽ đề cập đến các chủ đề như xây dựng bản phân tích khả thi của dự án và điều phối các cuộc họp nhóm mang lại hiệu quả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To:          Maya Liu\", \"vi\": \"Kính gửi: Maya Liu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From:      Leonard Chung\", \"vi\": \"From:      Leonard Chung\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Subject:   Webinar\", \"vi\": \"Chủ đề:   Hội thảo trực tuyến\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date:       2 January\", \"vi\": \"Ngày:       2 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dear Ms. Liu:\", \"vi\": \"Kính gửi bà Liu:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thank you for sending me the webinar announcement.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã gửi cho tôi thông báo về hội thảo trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"As a novice supervisor, I need to get all the training I can, but I\'m not sure whether I will be able to take advantage of this particular offering.\", \"vi\": \"Với tư cách là một người mới đảm nhận vai trò quản lý, tôi cần tham gia tất cả các khóa đào tạo có thể, nhưng tôi chưa chắc liệu mình có thể tận dụng được chương trình đào tạo cụ thể này hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I am scheduled to present a detailed project update at my company\'s quarterly division meeting on the same day, and I don\'t think anyone else on the team would be able to take my place.\", \"vi\": \"Tôi đã được phân công trình bày bản cập nhật chi tiết về dự án tại cuộc họp quý của bộ phận trong công ty vào cùng ngày đó, và tôi không nghĩ rằng có ai khác trong nhóm có thể thay thế tôi được.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Do you know whether the webinar will be recorded or whether there will be a similar webinar at a later date?\", \"vi\": \"Quý vị có biết liệu buổi hội thảo trực tuyến này có được ghi hình lại hay không, hay liệu sẽ có một buổi hội thảo trực tuyến tương tự được tổ chức vào một thời điểm sau này hay không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I have no schedule conflicts after 29 January.\", \"vi\": \"Sau ngày 29 tháng 1, tôi không có lịch trình nào trùng lặp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Leonard Chung\", \"vi\": \"Leonard Chung\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '75922223-b02d-45e4-98db-fdb90a48a6d6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Staff <staff@kelseytech.co.uk>\", \"vi\": \"Đến: Tất cả nhân viên <staff@kelseytech.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Kosei Masutani <kmasutani@kelseytech.co.uk>\", \"vi\": \"Từ: Kosei Masutani <kmasutani@kelseytech.co.uk>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 26 January\", \"vi\": \"Ngày: 26 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Some of you may have felt a bit ___135____ while sitting at your desk this morning.\", \"vi\": \"Một số bạn có thể cảm thấy hơi ___135____ khi ngồi tại bàn làm việc vào sáng nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [135]}, {\"en\": \"That\'s because one of the heating units in our building is broken.\", \"vi\": \"Đó là bởi vì một trong các thiết bị sưởi trong tòa nhà của chúng ta bị hỏng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Unfortunately, the repair crew cannot come to fix the problem until Thursday.\", \"vi\": \"Đáng tiếc là đội ngũ sửa chữa không thể đến khắc phục vấn đề cho đến tận thứ Năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The open office space on the lower level is the most affected area, with only some heat.\", \"vi\": \"Khu vực văn phòng mở ở tầng dưới là nơi chịu ảnh hưởng nhiều nhất, với chỉ một ít hơi ấm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Our interns are ___136____ there, so they will be assigned temporary office spaces on other floors.\", \"vi\": \"Các thực tập sinh của chúng ta đang ___136____ ở đó, vì vậy họ sẽ được phân công không gian làm việc tạm thời ở các tầng khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [136]}, {\"en\": \"___137____ , upon arrival tomorrow morning, interns will need to check in with Ms. Connor to receive their alternative work-space assignments.\", \"vi\": \"___137____ , khi đến nơi vào sáng mai, các thực tập sinh sẽ cần phải đăng ký với cô Connor để nhận phân công không gian làm việc thay thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [137]}, {\"en\": \"___138____ .\", \"vi\": \"___138____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [138]}, {\"en\": \"In the meantime, be assured we will ensure everyone\'s safety and resolve this quickly.\", \"vi\": \"Trong thời gian này, hãy yên tâm rằng chúng tôi sẽ đảm bảo an toàn cho mọi người và giải quyết việc này nhanh chóng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Kosei Masutani, Facilities Manager\", \"vi\": \"Kosei Masutani, Trưởng phòng Quản lý Cơ sở vật chất\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '75a42ff6-3609-46c3-8037-8f2c5db0ea16';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.summitresort.ca/reviews\", \"vi\": \"https://www.summitresort.ca/reviews\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Recent Guest Reviews of Summit Resort\", \"vi\": \"Các đánh giá gần đây của khách về Khu nghỉ dưỡng Summit\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Some friends and I visited Summit Resort for a long weekend in January, and I expect it will be the first of many trips to this lovely place.\", \"vi\": \"Vào tháng Giêng vừa qua, tôi cùng một số người bạn đã đến khu nghỉ dưỡng Summit để tận hưởng một kỳ nghỉ cuối tuần dài, và tôi tin rằng đây sẽ là chuyến đi đầu tiên trong số rất nhiều chuyến đi tới nơi tuyệt vời này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The best thing about the resort is its location right on Walker Mountain.\", \"vi\": \"Điểm nổi bật nhất của khu nghỉ dưỡng chính là vị trí tọa lạc ngay trên núi Walker.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The view from any room is stunning, and we could ski or snowboard straight out onto the slopes from the resort\'s back entrance.\", \"vi\": \"Khung cảnh nhìn từ bất kỳ phòng nào cũng vô cùng tuyệt đẹp, và chúng tôi có thể trượt tuyết hoặc trượt ván tuyết thẳng ra các dốc trượt ngay từ lối vào phía sau của khu nghỉ dưỡng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Walker Mountain has slopes for all skill levels, and the chairlifts are reliable.\", \"vi\": \"Núi Walker có các dốc trượt phù hợp với mọi trình độ, và hệ thống cáp treo hoạt động rất đáng tin cậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In the evenings, we had dinner at the resort\'s Highland Grill or took the shuttle to the nearby village.\", \"vi\": \"Vào buổi tối, chúng tôi dùng bữa tối tại nhà hàng Highland Grill của khu nghỉ dưỡng hoặc đi xe đưa đón đến ngôi làng gần đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"On the last day, some of us decided to pay the extra fee to visit the onsite spa, and it was very nice to rest our tired muscles in its sauna before going home.\", \"vi\": \"Vào ngày cuối cùng, một số người trong chúng tôi đã quyết định chi thêm một khoản phí để trải nghiệm dịch vụ spa tại chỗ, và thật tuyệt vời khi được thư giãn các cơ bắp mệt mỏi trong phòng xông hơi của spa trước khi trở về nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Overall, we had a wonderful time and heartily recommend Summit Resort to others.\", \"vi\": \"Nhìn chung, chúng tôi đã có một kỳ nghỉ tuyệt vời và xin chân thành giới thiệu Khu nghỉ dưỡng Summit tới quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"—Laverne Reese, February 10\", \"vi\": \"—Laverne Reese, ngày 10 tháng 2\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '75a8ae50-6aa7-4e3f-be91-29567bb32a58';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Melnyk Corporation employees\", \"vi\": \"Đến: Tất cả nhân viên của Tập đoàn Melnyk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Ivan Melnyk\", \"vi\": \"Từ: Ivan Melnyk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Re: Important visit\", \"vi\": \"V/v: Chuyến thăm quan trọng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: September 25\", \"vi\": \"Ngày: 25 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Next Tuesday, a Parham Monthly correspondent will visit Melnyk Corporation in preparation for writing a profile of me for the magazine.\", \"vi\": \"Vào thứ Ba tuần tới, một phóng viên của tạp chí Parham Monthly sẽ đến thăm Tập đoàn Melnyk để chuẩn bị viết một bài giới thiệu về tôi cho tạp chí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"In addition to ______[143] me, she will take a tour of our office to learn about our operations.\", \"vi\": \"Ngoài việc ______[143] tôi, cô ấy sẽ đi tham quan văn phòng của chúng ta để tìm hiểu về các hoạt động của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [143]}, {\"en\": \"A flattering article could really help the business, so I hope ______[144] will make an effort to ensure she comes away with a good impression of us.\", \"vi\": \"Một bài báo tích cực có thể thực sự giúp ích cho việc kinh doanh, vì vậy tôi hy vọng ______[144] sẽ nỗ lực để đảm bảo cô ấy ra về với ấn tượng tốt về chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [144]}, {\"en\": \"______[145].\", \"vi\": \"______[145].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [145]}, {\"en\": \"If you end up speaking with the ______[146], try to avoid making negative comments about anything—even our competitors.\", \"vi\": \"Nếu bạn vô tình trò chuyện với ______[146], hãy cố gắng tránh đưa ra những nhận xét tiêu cực về bất kỳ điều gì—thậm chí là đối thủ cạnh tranh của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [146]}, {\"en\": \"You should also politely refuse to answer any questions about subjects outside of your area.\", \"vi\": \"Bạn cũng nên lịch sự từ chối trả lời bất kỳ câu hỏi nào về các chủ đề nằm ngoài lĩnh vực của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Thank you in advance for your cooperation in making this visit a success.\", \"vi\": \"Cảm ơn sự hợp tác của các bạn trước để giúp chuyến thăm này thành công tốt đẹp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '75f9ebae-421d-4b31-bbec-a4d8c7c643f2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Aguni Plumbing Supply Returns\", \"vi\": \"Chính sách đổi trả của Aguni Plumbing Supply\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Beginning March 1 at all Aguni Plumbing Supply locations, customers will be able to come to our stores to return purchases made online.\", \"vi\": \"Kể từ ngày 1 tháng 3, tại tất cả các chi nhánh của Aguni Plumbing Supply, quý khách hàng sẽ có thể đến các cửa hàng của chúng tôi để trả lại các sản phẩm đã mua trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"For a complete refund, the return must be made within 30 days of purchase and must be accompanied by a receipt.\", \"vi\": \"Để được hoàn tiền đầy đủ, quý khách phải thực hiện việc trả hàng trong vòng 30 ngày kể từ ngày mua và phải xuất trình hóa đơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"In addition, the merchandise must be returned in the original packaging, and all components must be included.\", \"vi\": \"Ngoài ra, hàng hóa phải được trả lại trong bao bì gốc và phải bao gồm đầy đủ tất cả các bộ phận đi kèm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"After 30 days, refunds will be limited to in-store credit only.\", \"vi\": \"Sau 30 ngày, việc hoàn tiền sẽ chỉ được thực hiện dưới hình thức tín dụng tại cửa hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Defective items may be exchanged for the same item only.\", \"vi\": \"Các sản phẩm bị lỗi chỉ có thể được đổi lấy sản phẩm cùng loại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '762a71a9-6ef5-4f37-94ae-1f510cd58823';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Are you ready to work hard as part of a team of like-minded individuals?\", \"vi\": \"Quý vị đã sẵn sàng cống hiến hết mình trong một tập thể gồm những người có cùng chí hướng chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Are you willing to put your education, your experience, and your imagination to great use?\", \"vi\": \"Quý vị có sẵn sàng phát huy tối đa trình độ học vấn, kinh nghiệm và trí tưởng tượng của mình hay không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"If so, then we have the job for you.\", \"vi\": \"Nếu vậy, chúng tôi có một công việc phù hợp dành cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Karning Creative Designs is expanding, and with our success comes your opportunity.\", \"vi\": \"Karning Creative Designs đang trên đà phát triển, và cùng với thành công của chúng tôi là cơ hội dành cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Karning Creative Designs began ten years ago as a two-person operation set up in the home of our current CEO and founder Shirin Navani.\", \"vi\": \"Karning Creative Designs ra đời cách đây mười năm dưới hình thức một doanh nghiệp do hai người điều hành, được thành lập tại chính ngôi nhà của Giám đốc Điều hành kiêm Nhà sáng lập hiện tại của chúng tôi, bà Shirin Navani.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Now located in a beautiful loft in downtown Hollinson, our firm currently employs 25 full-time staff members.\", \"vi\": \"Hiện nay, với trụ sở tọa lạc tại một căn hộ gác xép tuyệt đẹp ở trung tâm thành phố Hollinson, công ty chúng tôi đang có 25 nhân viên làm việc toàn thời gian.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"At Karning, we design paper-based brochures, catalogs, ads, and posters for our clients.\", \"vi\": \"Tại Karning, chúng tôi thiết kế các tài liệu quảng cáo in trên giấy như tờ rơi, catalogue, quảng cáo và áp phích cho quý khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We are currently seeking qualified designers and artists who will shine in a fast-paced, collaborative environment.\", \"vi\": \"Hiện tại, chúng tôi đang tìm kiếm các nhà thiết kế và nghệ sĩ có năng lực, những người sẽ phát huy được thế mạnh của mình trong một môi trường làm việc năng động và đề cao tinh thần hợp tác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The ideal candidate\", \"vi\": \"Ứng viên lý tưởng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Holds a degree in design, advertising, or graphic art—although several years of direct experience may substitute for a degree\", \"vi\": \"Có bằng cấp về thiết kế, quảng cáo hoặc nghệ thuật đồ họa — mặc dù kinh nghiệm thực tế trực tiếp trong vài năm có thể thay thế cho bằng cấp\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Demonstrates a strong ability to work closely with colleagues\", \"vi\": \"Thể hiện khả năng hợp tác chặt chẽ với đồng nghiệp một cách xuất sắc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Maintains a critical eye for detail and precision\", \"vi\": \"Luôn duy trì sự chú ý tỉ mỉ đến từng chi tiết và tính chính xác\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Consistently meets deadlines and can flourish under pressure\", \"vi\": \"Luôn tuân thủ đúng thời hạn và có khả năng làm việc hiệu quả ngay cả khi phải đối mặt với áp lực\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Graphic design or related experience is a plus but not strictly necessary.\", \"vi\": \"Có kinh nghiệm về thiết kế đồ họa hoặc các lĩnh vực liên quan sẽ là một lợi thế, nhưng không phải là điều kiện bắt buộc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If you are ready to join our team, we want to meet you!\", \"vi\": \"Nếu quý vị đã sẵn sàng gia nhập đội ngũ của chúng tôi, chúng tôi rất mong được gặp quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Contact Salvador Tomassin at 608-555-0144 for further details.\", \"vi\": \"Vui lòng liên hệ với ông Salvador Tomassin theo số 608-555-0144 để biết thêm chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"All applications must be received by March 31.\", \"vi\": \"Tất cả các hồ sơ đăng ký phải được nộp trước ngày 31 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '76380eea-c341-4ded-841f-0064fb8d8309';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Lynda McCann (1:08 P.M.) Hello, Bernadette and Harrison.\", \"vi\": \"Lynda McCann (1 giờ 08 phút chiều) Xin chào, Bernadette và Harrison.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"We urgently need to schedule a team meeting, so we can get working on our project.\", \"vi\": \"Chúng ta cần khẩn trương lên lịch một cuộc họp nhóm để có thể bắt tay vào thực hiện dự án của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Bernadette Ecco (1:10 P.M.) Sure.\", \"vi\": \"Bernadette Ecco (1 giờ 10 phút chiều) Được ạ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Are you wanting an all-marketing-staff meeting?\", \"vi\": \"Quý vị có muốn tổ chức một cuộc họp với toàn bộ nhân viên bộ phận tiếp thị không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Let me know if I can assist.\", \"vi\": \"Nếu tôi có thể giúp gì được, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Lynda McCann (1:12 P.M.) No, I was thinking of the O\'Neil project, so only the three of us who are on that team need to meet.\", \"vi\": \"Lynda McCann (1 giờ 12 phút chiều): Không, tôi đang nghĩ đến dự án O\'Neil, nên chỉ cần ba người chúng tôi trong nhóm đó gặp nhau là được.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Bernadette Ecco (1:14 P.M.) Okay.\", \"vi\": \"Bernadette Ecco (1 giờ 14 phút chiều) Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I\'m free either this Wednesday or Friday during the early afternoon.\", \"vi\": \"Tôi rảnh vào chiều sớm ngày thứ Tư hoặc thứ Sáu tuần này.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Harrison Miller (1:15 P.M.) I thought I had been reassigned to the McMillan project instead.\", \"vi\": \"Harrison Miller (1 giờ 15 phút chiều) Tôi tưởng mình đã được điều chuyển sang dự án McMillan rồi.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Bernadette Ecco (1:17 P.M.) No, the final slot on that team was filled by Jacob Aikens, since he\'s worked on similar projects in the past, like the Greller project and the Allford project.\", \"vi\": \"Bernadette Ecco (13 giờ 17 phút) Không, vị trí cuối cùng trong đội đó đã được giao cho Jacob Aikens, bởi vì anh ấy đã từng tham gia các dự án tương tự trước đây, như dự án Greller và dự án Allford.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Harrison Miller (1:18 P.M.) Okay, I see.\", \"vi\": \"Harrison Miller (1 giờ 18 phút chiều) Vâng, tôi hiểu rồi.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Lynda McCann (1:19 P.M.) I\'m available on Wednesday and Friday as well, but only before 3 P.M.; I\'ll be meeting with the sales team on Wednesday at 3 P.M. and the research team on Friday at 3:30 P.M.\", \"vi\": \"Lynda McCann (1 giờ 19 phút chiều) Tôi cũng rảnh vào thứ Tư và thứ Sáu, nhưng chỉ trước 3 giờ chiều thôi; tôi sẽ có cuộc họp với đội ngũ bán hàng vào thứ Tư lúc 3 giờ chiều và với đội ngũ nghiên cứu vào thứ Sáu lúc 3 giờ 30 chiều.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Harrison Miller (1:21 P.M.) Wednesday won\'t work for me, but I could do Friday at 1 P.M.\", \"vi\": \"Harrison Miller (1 giờ 21 phút chiều), thứ Tư thì tôi không rảnh, nhưng thứ Sáu lúc 1 giờ chiều thì tôi có thể sắp xếp được.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Lynda McCann (1:23 P.M.) Sounds good!\", \"vi\": \"Lynda McCann (1 giờ 23 phút chiều) Nghe hay đấy!\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Bernadette?\", \"vi\": \"Bernadette ạ?\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Bernadette Ecco (1:23 P.M.) Perfect!\", \"vi\": \"Bernadette Ecco (1 giờ 23 phút chiều) Tuyệt vời!\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I\'ll reserve the small conference room for us.\", \"vi\": \"Tôi sẽ đặt trước phòng họp nhỏ cho chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '766e33ae-c2ba-4275-843d-9919228020b2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Valued Guests of Adler Hotel:\", \"vi\": \"Kính gửi Quý khách hàng của Khách sạn Adler:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Please be advised that we will begin refurbishing the hotel swimming pool from 27 November.\", \"vi\": \"Xin lưu ý rằng chúng tôi sẽ bắt đầu tân trang hồ bơi của khách sạn từ ngày 27 tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"After being ______[139] drained, it will be resurfaced and repainted.\", \"vi\": \"Sau khi được rút hết nước ______[139], hồ bơi sẽ được làm mới bề mặt và sơn lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [139]}, {\"en\": \"______[140] Any activities that may cause loud noise will be confined to the hours between 10 a.m. and 5 p.m. However, the pool and poolside areas will be completely off-limits to guests at all times during this project.\", \"vi\": \"______[140] Mọi hoạt động có thể gây tiếng ồn lớn sẽ chỉ diễn ra trong khoảng thời gian từ 10 giờ sáng đến 5 giờ chiều. Tuy nhiên, khu vực hồ bơi và xung quanh hồ bơi sẽ hoàn toàn bị cấm đối với khách trong suốt thời gian diễn ra dự án này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [140]}, {\"en\": \"The reopening of these facilities ______[141] for 8 December.\", \"vi\": \"Việc mở cửa trở lại các tiện ích này ______[141] vào ngày 8 tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [141]}, {\"en\": \"______[142] guests may use the swimming pool at Adler Plaza, our sister property at Logsdon Point.\", \"vi\": \"______[142] quý khách có thể sử dụng hồ bơi tại Adler Plaza, khách sạn liên kết của chúng tôi tại Logsdon Point.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [142]}, {\"en\": \"Please visit the concierge desk for details.\", \"vi\": \"Vui lòng đến quầy lễ tân để biết thêm chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '7703188c-1907-434c-a39b-efb5d9d92a29';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mayor Lizette Set to Deliver State of the City Address\", \"vi\": \"Thị trưởng Lizette chuẩn bị phát biểu về tình hình thành phố\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"FALCON HEIGHTS (21 April)-Mayor Loretta Lizette will deliver her fifth State of the City address at Falcon Heights City Hall, Room 101, on Wednesday, 30 April, beginning at 7:00 P.M. The event is open to the public, but seating is first come, first served.\", \"vi\": \"FALCON HEIGHTS (ngày 21 tháng 4) – Thị trưởng Loretta Lizette sẽ trình bày bài phát biểu “Tình hình Thành phố” lần thứ năm tại Tòa thị chính Falcon Heights, Phòng 101, vào thứ Tư, ngày 30 tháng 4, bắt đầu lúc 7 giờ tối. Sự kiện này mở cửa cho công chúng tham dự, tuy nhiên chỗ ngồi sẽ được sắp xếp theo thứ tự đến trước, phục vụ trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Mayor Lizette, who was reelected to her second four-year term last month, will discuss her vision for the future of the city.\", \"vi\": \"Bà Lizette, Thị trưởng vừa được tái cử vào nhiệm kỳ thứ hai kéo dài bốn năm vào tháng trước, sẽ trình bày tầm nhìn của bà về tương lai của thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"One issue on her agenda is the controversial application by Panhandle Eatery, a fast-food restaurant, to open a location on historic Hedgerow Boulevard.\", \"vi\": \"Một trong những vấn đề nằm trong chương trình làm việc của bà là đơn xin gây tranh cãi của Panhandle Eatery, một nhà hàng thức ăn nhanh, nhằm mở một chi nhánh trên đại lộ Hedgerow Boulevard mang tính lịch sử.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The speech will be followed by a question-and-answer period.\", \"vi\": \"Sau bài phát biểu sẽ là phần hỏi đáp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Doors open at 6:30 Ρ.Μ.\", \"vi\": \"Cửa mở lúc 6 giờ 30 phút chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '7723cb97-fd66-4478-9124-f88e331179b8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Reggie Norris [11:06 A.M.]\", \"vi\": \"Reggie Norris [11 giờ 06 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Sarah.\", \"vi\": \"Xin chào, Sarah.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I finally got an appointment to see a very busy doctor this Friday, so I\'m looking for someone to take my shift at the store that day.\", \"vi\": \"Cuối cùng thì tôi cũng đã đặt được lịch hẹn với một bác sĩ rất bận rộn vào thứ Sáu tuần này, nên tôi đang tìm người thay ca cho tôi tại cửa hàng vào ngày đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Could you come in that afternoon?\", \"vi\": \"Chiều hôm đó, quý vị có thể ghé qua được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Sarah Klein [11:07 A.M.]\", \"vi\": \"Sarah Klein [11 giờ 07 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I\'ll have to check my calendar.\", \"vi\": \"Tôi sẽ phải xem lại lịch của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Hold on.\", \"vi\": \"Xin chờ một chút.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Sarah Klein [11:09 A.M.]\", \"vi\": \"Sarah Klein [11 giờ 09 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"OK, I thought I was supposed to meet a friend for coffee then, but it turns out that\'s next Friday.\", \"vi\": \"Được rồi, tôi tưởng là lúc đó tôi sẽ hẹn gặp một người bạn để uống cà phê, nhưng hóa ra là vào thứ Sáu tuần sau.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"But I\'ve never worked hours that aren\'t on my schedule before—do we need to get Ms. Evans\'s approval?\", \"vi\": \"Tuy nhiên, trước đây tôi chưa bao giờ làm việc ngoài giờ đã được sắp xếp trong lịch trình của mình — liệu chúng ta có cần xin sự chấp thuận của bà Evans không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Reggie Norris [11:10 A.M.]\", \"vi\": \"Reggie Norris [11 giờ 10 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I\'ll call her now.\", \"vi\": \"Tôi sẽ gọi cho cô ấy ngay bây giờ.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you so much, Sarah!\", \"vi\": \"Xin chân thành cảm ơn cô, Sarah!\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sarah Klein [11:11 A.M.]\", \"vi\": \"Sarah Klein [11 giờ 11 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"No problem!\", \"vi\": \"Không sao cả!\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '773356f3-26d6-4344-b9e7-1e836c545d19';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"CHAT X\", \"vi\": \"Mèo X\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Lily Park (4:03 P.M.)\", \"vi\": \"Công viên Lily (4 giờ 03 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Hello, everyone.\", \"vi\": \"Xin chào quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I just want to check in with you before the weekend.\", \"vi\": \"Tôi chỉ muốn liên hệ với quý vị một chút trước khi bước vào cuối tuần.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Kaz, how did your meeting with Blumfield Associates go?\", \"vi\": \"Kaz ạ, cuộc họp của anh với Blumfield Associates diễn ra thế nào rồi?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Kaz Fedorowitz (4:10 P.M.)\", \"vi\": \"Kaz Fedorowitz (4 giờ 10 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It could not have been better.\", \"vi\": \"Không thể nào tuyệt vời hơn được nữa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"They are purchasing 40 new laptops with a service agreement.\", \"vi\": \"Họ đang mua 40 chiếc máy tính xách tay mới kèm theo hợp đồng bảo trì.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I’ve got the signed contract in hand.\", \"vi\": \"Tôi đang cầm trên tay bản hợp đồng đã được ký kết.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Lily Park (4:11 P.M.)\", \"vi\": \"Công viên Lily (4 giờ 11 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Outstanding!\", \"vi\": \"Thật xuất sắc!\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Nice way to wrap up the week.\", \"vi\": \"Thật là một cách tuyệt vời để khép lại tuần làm việc.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"David Esposito (4:12 P.M.)\", \"vi\": \"David Esposito (4 giờ 12 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Congratulations!\", \"vi\": \"Xin chúc mừng!\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"This one puts you over the top.\", \"vi\": \"Điều này sẽ giúp quý vị vươn lên dẫn đầu.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"You are now the top salesperson for the third month in a row.\", \"vi\": \"Đây là tháng thứ ba liên tiếp quý vị trở thành nhân viên bán hàng xuất sắc nhất.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Danielle Becker (4:13 P.M.)\", \"vi\": \"Danielle Becker (4 giờ 13 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"That’s great news, Kaz.\", \"vi\": \"Đó quả là một tin vui, Kaz.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"By the way, if you can get all your receipts to me as soon as you are back in the office, you will get your travel reimbursement check early the following week.\", \"vi\": \"Nhân tiện, nếu quý vị có thể chuyển toàn bộ các hóa đơn cho tôi ngay khi trở lại văn phòng, quý vị sẽ nhận được séc hoàn trả chi phí đi lại vào đầu tuần sau.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Kaz Fedorowitz (4:14 P.M.)\", \"vi\": \"Kaz Fedorowitz (4 giờ 14 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Are you sure about that?\", \"vi\": \"Quý vị có chắc chắn về điều đó không?\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Didn’t Michael Lim just land a big sale?\", \"vi\": \"Chẳng phải Michael Lim vừa chốt được một hợp đồng lớn sao?\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Lily Park (4:15 P.M.)\", \"vi\": \"Công viên Lily (4 giờ 15 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 7, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Unfortunately, Michael’s customers backed out at the last minute.\", \"vi\": \"Thật không may, các khách hàng của Michael đã hủy hợp đồng vào phút chót.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"They decided to lease computers and printers from another firm rather than purchase new equipment.\", \"vi\": \"Họ đã quyết định thuê máy tính và máy in từ một công ty khác thay vì mua thiết bị mới.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Kaz Fedorowitz (4:17 P.M.)\", \"vi\": \"Kaz Fedorowitz (4 giờ 17 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 8, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"That’s too bad.\", \"vi\": \"Thật đáng tiếc.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"And thanks for taking care of that, Danielle.\", \"vi\": \"Và xin cảm ơn cô đã lo liệu việc đó, Danielle.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Danielle Becker (4:18 P.M.)\", \"vi\": \"Danielle Becker (16 giờ 18 phút)\", \"type\": \"metadata\", \"doc_index\": 9, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"My pleasure!\", \"vi\": \"Rất hân hạnh!\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Lily Park (4:19 P.M.)\", \"vi\": \"Công viên Lily (4 giờ 19 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 10, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Have a wonderful weekend, everyone.\", \"vi\": \"Chúc mọi người có một cuối tuần thật tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 32, \"question_numbers\": []}]' WHERE `id` = '774ee1ce-5667-417e-84b6-14c52d5f70a6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Kira Takamatsu\", \"vi\": \"Từ: Kira Takamatsu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Eric Sutherland\", \"vi\": \"Gửi: Eric Sutherland\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Meeting follow-up\", \"vi\": \"Chủ đề: Theo dõi sau cuộc họp\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: March 8\", \"vi\": \"Ngày: 8 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Eric,\", \"vi\": \"Kính gửi anh Eric,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for sharing your concerns about your workload.\", \"vi\": \"Xin cảm ơn quý vị đã chia sẻ những lo ngại của mình về khối lượng công việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We do our best to distribute projects so that employees can complete them during the regular workweek.\", \"vi\": \"Chúng tôi luôn nỗ lực phân công các dự án sao cho nhân viên có thể hoàn thành chúng trong khung thời gian làm việc thông thường của tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Since we recently added book-cover design to your already full list of responsibilities, we have decided to assign an assistant to you, a new team member named Hugo Rynkowski.\", \"vi\": \"Vì gần đây chúng tôi đã bổ sung công việc thiết kế bìa sách vào danh sách nhiệm vụ vốn đã rất bận rộn của quý vị, nên chúng tôi đã quyết định phân công một trợ lý cho quý vị, đó là thành viên mới của đội ngũ mang tên Hugo Rynkowski.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You will oversee his work, including all poster, logo, and catalog layout projects.\", \"vi\": \"Quý vị sẽ chịu trách nhiệm giám sát công việc của anh ấy, bao gồm tất cả các dự án thiết kế bố cục áp phích, logo và catalogue.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"When Mr. Rynkowski arrives next Monday, you will need to share with him all of your clients\' information, including general descriptions and specific requirements.\", \"vi\": \"Khi ông Rynkowski đến vào thứ Hai tới, quý vị sẽ cần cung cấp cho ông ấy toàn bộ thông tin về các khách hàng của quý vị, bao gồm các mô tả chung và các yêu cầu cụ thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"You will be responsible for instructing him on our design software as well as all other systems that you are using.\", \"vi\": \"Quý vị sẽ có trách nhiệm hướng dẫn anh ấy cách sử dụng phần mềm thiết kế của chúng tôi cũng như tất cả các hệ thống khác mà quý vị đang sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If you have any other concerns, please do not hesitate to share them with me.\", \"vi\": \"Nếu quý vị còn bất kỳ thắc mắc nào khác, xin đừng ngần ngại chia sẻ với tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Kira Takamatsu\", \"vi\": \"Kira Takamatsu\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '780bb41c-a5c3-4193-9e30-bec10649ddcb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Alamito Botanical Society\", \"vi\": \"Hội Thực vật học Alamito\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Submit your home garden to be one of several stops on this year\'s Gorgeous Gardens Tour, scheduled for July 3!\", \"vi\": \"Hãy đăng ký khu vườn tại nhà của quý vị để trở thành một trong những điểm dừng chân của Chương trình Tham quan Những Khu Vườn Tuyệt Đẹp năm nay, dự kiến diễn ra vào ngày 3 tháng 7!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This year\'s tour theme is Winged Paradise, with a focus on flowering plants favored by regional birds and butterflies, including the lesser goldfinch and the ringlet butterfly.\", \"vi\": \"Chủ đề của chuyến tham quan năm nay là “Thiên đường có cánh”, tập trung vào các loài thực vật có hoa được các loài chim và bướm trong khu vực ưa chuộng, bao gồm chim hoàng yến nhỏ và loài bướm Ringlet.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"All proceeds from ticket sales for this year\'s tour will go toward replanting the cottonwood forest in Presidio County Park.\", \"vi\": \"Toàn bộ số tiền thu được từ việc bán vé cho chuyến lưu diễn năm nay sẽ được dùng để trồng lại khu rừng cây bông gòn tại Công viên Hạt Presidio.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hosting a tour garden is free for members of the Alamito Botanical Society.\", \"vi\": \"Việc tổ chức một chuyến tham quan vườn là miễn phí dành cho các thành viên của Hiệp hội Thực vật học Alamito.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Simply complete the form at www.alamitobotanicalsociety.org/gorgeousgardens and submit it with digital photos of your garden by May 20.\", \"vi\": \"Quý vị chỉ cần điền vào biểu mẫu tại địa chỉ www.alamitobotanicalsociety.org/gorgeousgardens và gửi kèm theo các bức ảnh kỹ thuật số về khu vườn của quý vị trước ngày 20 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Gardens selected to participate in the tour must be within Presidio County and include only plants native to the region.\", \"vi\": \"Các khu vườn được lựa chọn tham gia chuyến tham quan phải nằm trong phạm vi Hạt Presidio và chỉ trồng các loài thực vật bản địa của khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If you have questions regarding participating as a tour stop, please send an e-mail to info@alamitobotanicalsociety.org.\", \"vi\": \"Nếu quý vị có thắc mắc về việc tham gia với tư cách là điểm dừng chân trong chuyến tham quan, xin vui lòng gửi email đến địa chỉ info@alamitobotanicalsociety.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To: info@alamitobotanicalsociety.org\", \"vi\": \"Gửi tới: info@alamitobotanicalsociety.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"From: rebeccaolton@mailhost.com\", \"vi\": \"Nguồn: rebeccaolton@mailhost.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Date: May 1\", \"vi\": \"Ngày: 1 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Subject: Question about garden tour\", \"vi\": \"Chủ đề: Thắc mắc về chuyến tham quan khu vườn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Xin chào\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I became a member of the Alamito Botanical Society last year shortly after moving to Presidio County.\", \"vi\": \"Năm ngoái, ngay sau khi chuyển đến Hạt Presidio, tôi đã trở thành hội viên của Hội Thực vật học Alamito.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The society\'s Web site, resources, and educational lectures have been helpful regarding my ambitious project: to cover five acres of my land with various native plants that will attract birds and other animals.\", \"vi\": \"Trang web, các tài liệu tham khảo và các buổi thuyết trình giáo dục của hiệp hội này đã mang lại nhiều lợi ích cho dự án đầy tham vọng của tôi: phủ xanh năm mẫu đất của tôi bằng nhiều loại cây bản địa khác nhau nhằm thu hút chim chóc và các loài động vật khác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"About one and a half acres of soil have been cultivated so far.\", \"vi\": \"Cho đến nay, đã có khoảng một mẫu rưỡi đất được canh tác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"It would be a privilege to show my work to the public and to meet more people who value gardens as we members of the society do.\", \"vi\": \"Được giới thiệu tác phẩm của mình đến công chúng và có cơ hội gặp gỡ thêm nhiều người cũng trân trọng những khu vườn như chúng tôi, những thành viên của hội này, sẽ là một vinh dự lớn lao.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thus, I am writing to ask if I may participate in the Gorgeous Gardens Tour.\", \"vi\": \"Vì vậy, tôi viết thư này để xin được tham gia Chương trình Tham quan Những Khu Vườn Tuyệt Đẹp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I must admit that beautiful lavender bushes that are not native to the area were already growing on the property before I purchased it.\", \"vi\": \"Tôi phải thừa nhận rằng những bụi hoa oải hương xinh đẹp – vốn không phải là loài bản địa của khu vực này – đã mọc sẵn trên mảnh đất này từ trước khi tôi mua lại nó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"However, lavender is not on the invasive-species list, and I continue to let them grow because the butterflies, bees, and other wildlife love the blooms.\", \"vi\": \"Tuy nhiên, hoa oải hương không nằm trong danh sách các loài xâm lấn, và tôi vẫn tiếp tục để chúng mọc tự nhiên vì bướm, ong và các loài động vật hoang dã khác rất ưa thích những bông hoa này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Rebecca Olton\", \"vi\": \"Rebecca Olton\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"https://www.alamitobotanicalsociety.org/education/lectures\", \"vi\": \"https://www.alamitobotanicalsociety.org/education/lectures\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"The leaders and members of the Alamito Botanical Society cordially invite the public to attend its educational lectures, held at the horticultural department of Marfa Community College.\", \"vi\": \"Ban lãnh đạo và các thành viên của Hội Thực vật học Alamito trân trọng kính mời quý vị tham dự các buổi thuyết trình giáo dục do Hội tổ chức tại khoa làm vườn của Trường Cao đẳng Cộng đồng Marfa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"All lectures occur on the third Wednesday of the month at 7:00 P.M. Advance registration is not required.\", \"vi\": \"Tất cả các buổi giảng đều diễn ra vào thứ Tư thứ ba của tháng, lúc 7 giờ tối. Quý vị không cần đăng ký trước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"February: Schedule Your Salad – Get tips for establishing a planting timetable and for selecting delicious vegetables to grow.\", \"vi\": \"Tháng Hai: Lên kế hoạch trồng rau salad – Hãy tham khảo những lời khuyên về cách lập lịch trình trồng trọt và cách chọn các loại rau ngon để trồng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"March: Nourish the Neighbors – Understand how to use plants native to our region to create landscapes that are inviting to wildlife.\", \"vi\": \"Tháng 3: Chăm sóc những người hàng xóm – Tìm hiểu cách sử dụng các loài thực vật bản địa của khu vực chúng ta để tạo nên những không gian cảnh quan thu hút động vật hoang dã.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"April: Pest Deterrence – Learn natural, pesticide-free techniques that can prevent harmful insects from eating your fruits and vegetables.\", \"vi\": \"Tháng 4: Phòng trừ sâu bệnh – Tìm hiểu các phương pháp tự nhiên, không sử dụng thuốc trừ sâu, giúp ngăn chặn côn trùng gây hại ăn trái cây và rau củ của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"May: Pollen Transportation – No butterflies or bees visiting your garden?\", \"vi\": \"Tháng Năm: Quá trình thụ phấn – Không có bướm hay ong nào ghé thăm khu vườn của quý vị sao?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"No worries.\", \"vi\": \"Không sao đâu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Humans can pollinate certain plants using simple techniques.\", \"vi\": \"Con người có thể thụ phấn cho một số loài thực vật bằng các kỹ thuật đơn giản.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}]' WHERE `id` = '780c5be2-74b9-44a3-9807-b313bd0d974f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Skylight Gardens\", \"vi\": \"Khu vườn Skylight\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Plant Care Tips\", \"vi\": \"Một số mẹo chăm sóc cây cảnh\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Your Neighborhood Garden Center\", \"vi\": \"Trung tâm Vườn tược trong khu vực của quý vị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Effective plant care starts with choosing the right pot for your houseplant.\", \"vi\": \"Việc chăm sóc cây hiệu quả bắt đầu từ việc lựa chọn chậu phù hợp cho cây cảnh trong nhà của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Make sure that there are holes in the bottom of the pot to let water flow out.\", \"vi\": \"Hãy đảm bảo rằng đáy chậu có lỗ để nước có thể chảy ra ngoài.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Next, purchase soil from your local garden center.\", \"vi\": \"Tiếp theo, quý vị hãy mua đất tại trung tâm làm vườn gần nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Store-bought potting soil typically contains fertilizer to help indoor plants grow.\", \"vi\": \"Đất trồng cây bán sẵn trên thị trường thường có chứa phân bón để giúp cây trồng trong nhà phát triển tốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Using dirt from your own outdoor garden is risky.\", \"vi\": \"Việc sử dụng đất lấy từ khu vườn ngoài trời của chính quý vị tiềm ẩn nhiều rủi ro.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This dirt can be filled with insects, disease, and weeds, all of which can be harmful to indoor plants.\", \"vi\": \"Loại đất này có thể chứa đầy côn trùng, mầm bệnh và cỏ dại, tất cả những yếu tố này đều có thể gây hại cho cây trồng trong nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"After potting, pour water on the soil and flowers of your plant.\", \"vi\": \"Sau khi trồng vào chậu, xin vui lòng tưới nước lên đất và hoa của cây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Always check the soil before watering.\", \"vi\": \"Luôn kiểm tra độ ẩm của đất trước khi tưới nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"If the soil is still moist, there is no need for more water.\", \"vi\": \"Nếu đất vẫn còn ẩm, thì không cần tưới thêm nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To maintain a healthy plant, pinch or cut off parts of the plant that have turned brown or withered.\", \"vi\": \"Để cây luôn khỏe mạnh, quý vị nên ngắt hoặc cắt bỏ những phần cây đã chuyển sang màu nâu hoặc héo úa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Doing so helps to facilitate new growth.\", \"vi\": \"Việc làm như vậy sẽ góp phần thúc đẩy sự phát triển mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Each spring, repot your plant in a larger pot to allow room for the root system to grow.\", \"vi\": \"Mỗi mùa xuân, quý vị hãy chuyển cây sang một chậu lớn hơn để tạo không gian cho hệ thống rễ phát triển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '78266c21-9f11-4442-869d-7757b3b8632b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"COLLINSVALE (28 March)—Over the last decade, instability in the pricing of raw materials has become the biggest concern for manufacturers.\", \"vi\": \"COLLINSVALE (ngày 28 tháng 3) — Trong thập kỷ qua, sự biến động về giá nguyên liệu thô đã trở thành mối lo ngại lớn nhất đối với các nhà sản xuất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The issue now surpasses recruitment and technology, which had previously been ranked by businesses as the top two concerns respectively.\", \"vi\": \"Vấn đề hiện nay đã vượt ra ngoài phạm vi tuyển dụng và công nghệ – hai lĩnh vực trước đây được các doanh nghiệp xếp hạng lần lượt là hai mối quan tâm hàng đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The reasons are not difficult to understand.\", \"vi\": \"Các lý do này không khó để hiểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"For electronics manufacturers, materials typically represent 20 percent of all expenses, while makers of processed food can spend anywhere between 40 and 60 percent on materials.\", \"vi\": \"Đối với các nhà sản xuất thiết bị điện tử, chi phí nguyên vật liệu thường chiếm 20 phần trăm tổng chi phí, trong khi các nhà sản xuất thực phẩm chế biến có thể chi từ 40 đến 60 phần trăm cho nguyên vật liệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Thus, even a 10 percent rise in the cost of sugar can dramatically affect a factory’s bottom line.\", \"vi\": \"Do đó, ngay cả khi giá đường tăng 10 phần trăm cũng có thể tác động đáng kể đến lợi nhuận ròng của nhà máy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Companies that can predict rising costs may be able to temper the effects of market volatility, but even the best forecasting cannot anticipate every change in the marketplace.\", \"vi\": \"Các doanh nghiệp có khả năng dự báo được xu hướng tăng chi phí có thể giảm thiểu tác động của sự biến động thị trường; tuy nhiên, ngay cả những dự báo chính xác nhất cũng không thể lường trước được mọi thay đổi trên thị trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '785672db-44f9-410a-839f-3c65ea4f16ca';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"New Fleet for Northeast Railways\", \"vi\": \"Đội tàu mới của Đường sắt Đông Bắc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Northeast Railways expects to spend $5.6 billion to replace its fleet of 65 passenger trains, many of which are more than 40 years old.\", \"vi\": \"Tổng công ty Đường sắt Đông Bắc dự kiến sẽ chi 5,6 tỷ USD để thay thế đội tàu khách gồm 65 đoàn tàu, trong đó nhiều đoàn tàu đã có tuổi thọ trên 40 năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The company has entered into a contract with Logiens Transport for a new fleet of trains that will operate on electrified tracks when those track systems are available and on diesel fuel at all other times.\", \"vi\": \"Công ty đã ký kết hợp đồng với Logiens Transport để đưa vào vận hành một đội tàu mới, đội tàu này sẽ chạy trên các tuyến đường sắt được điện khí hóa khi các hệ thống đường ray đó sẵn sàng và sử dụng nhiên liệu diesel trong mọi trường hợp còn lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The trains will be capable of traveling at speeds of up to 130 kilometers per hour and will produce far less pollution than the current fleet does.\", \"vi\": \"Các đoàn tàu này sẽ có khả năng di chuyển với tốc độ lên tới 130 kilômét mỗi giờ và sẽ thải ra lượng chất ô nhiễm ít hơn rất nhiều so với đội tàu hiện tại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Logiens also promises an enhanced passenger experience.\", \"vi\": \"Logiens cũng cam kết mang đến trải nghiệm tốt hơn cho hành khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The train cars will have panoramic windows, improved ventilation, and wider aisles.\", \"vi\": \"Các toa tàu sẽ được trang bị cửa sổ toàn cảnh, hệ thống thông gió được cải thiện và lối đi rộng hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Northeast’s contract with Logiens also includes equipment and replacement parts and provides a long-term service agreement.\", \"vi\": \"Hợp đồng giữa Northeast và Logiens còn bao gồm thiết bị và phụ tùng thay thế, đồng thời quy định một thỏa thuận dịch vụ dài hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '78ae5ca0-60c2-46e7-abdb-402ccd68c45f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Morton Talbert (7:32 P.M.)\", \"vi\": \"Morton Talbert (7 giờ 32 phút tối)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Has anyone used the Internet device Bam Booster?\", \"vi\": \"Có ai đã từng sử dụng thiết bị kết nối Internet Bam Booster chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Chaya Leven (7:37 P.M.)\", \"vi\": \"Chaya Leven (7 giờ 37 phút tối)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I have used other brands in the past, but now I have the Bam Booster 10, and I love it.\", \"vi\": \"Trước đây tôi đã từng sử dụng các thương hiệu khác, nhưng hiện tại tôi đang dùng Bam Booster 10 và tôi rất ưng ý sản phẩm này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Laria Jones (7:38 P.M.)\", \"vi\": \"Laria Jones (19 giờ 38 phút)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I have a poor connection to the Internet in my basement.\", \"vi\": \"Tầng hầm nhà tôi có kết nối Internet không được tốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I have tried several Internet boosters, but they haven\'t helped at all.\", \"vi\": \"Tôi đã thử dùng một số thiết bị tăng cường tín hiệu Internet, nhưng chúng hoàn toàn không mang lại hiệu quả gì cả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"They\'re just not worth the money.\", \"vi\": \"Chúng thực sự không đáng với số tiền bỏ ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Morton Talbert (7:40 P.M.)\", \"vi\": \"Morton Talbert (7 giờ 40 phút tối)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I am looking for a reliable booster that\'s easy to set up.\", \"vi\": \"Tôi đang tìm kiếm một bộ khuếch đại tín hiệu đáng tin cậy và dễ lắp đặt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Chaya Leven (7:41 P.M.)\", \"vi\": \"Chaya Leven (7 giờ 41 phút tối)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"That one is the best.\", \"vi\": \"Cái đó là hay nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Leonard Keff (7:48 P.M.)\", \"vi\": \"Leonard Keff (7 giờ 48 phút tối)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I have the Bam Booster 7.\", \"vi\": \"Tôi đang sở hữu chiếc Bam Booster 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"It works fine and was easy to set up, but I\'ve heard their newer Bam Booster 10 model is better.\", \"vi\": \"Sản phẩm này hoạt động tốt và rất dễ cài đặt, nhưng tôi nghe nói mẫu Bam Booster 10 mới hơn của họ còn tốt hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Danyelle Walken (7:52 P.M.)\", \"vi\": \"Danyelle Walken (7 giờ 52 phút tối)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I have the Zeertox Signal Booster and it\'s somewhat big and unsightly.\", \"vi\": \"Tôi đang sử dụng bộ khuếch đại tín hiệu Zeertox, và thiết bị này có kích thước khá lớn và trông không được thẩm mỹ cho lắm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"On the positive side, it\'s inexpensive and it works.\", \"vi\": \"Mặt tích cực là sản phẩm này có giá cả phải chăng và mang lại hiệu quả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Chaya Leven (7:58 P.M.)\", \"vi\": \"Chaya Leven (7 giờ 58 phút tối)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"The Bam Booster 10 is much smaller.\", \"vi\": \"Mẫu Bam Booster 10 có kích thước nhỏ gọn hơn nhiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"It does cost more than other brands, though.\", \"vi\": \"Tuy nhiên, giá của sản phẩm này thực sự cao hơn so với các thương hiệu khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Morton Talbert (8:02 P.M.)\", \"vi\": \"Morton Talbert (20 giờ 02 phút)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I didn\'t realize there was more than one Bam Booster model.\", \"vi\": \"Tôi không biết rằng có nhiều hơn một mẫu Bam Booster.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Thanks, everybody!\", \"vi\": \"Xin cảm ơn quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Now I know what to get.\", \"vi\": \"Giờ thì tôi đã biết nên mua gì rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '78e2c598-64db-424d-b2ce-af3eb64b4d82';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Help Wanted\", \"vi\": \"Tuyển dụng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Zestful Cuisine is looking for a server to join our restaurant’s team!\", \"vi\": \"Zestful Cuisine đang tìm kiếm một nhân viên phục vụ để gia nhập đội ngũ của nhà hàng chúng tôi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We specialize in French and Spanish food.\", \"vi\": \"Chúng tôi chuyên phục vụ các món ăn Pháp và Tây Ban Nha.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"This is a full-time or part-time position.\", \"vi\": \"Đây là vị trí làm việc toàn thời gian hoặc bán thời gian.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Days and nights are available.\", \"vi\": \"Có cả ca ngày và ca đêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Candidate must have a positive attitude, excellent customer service skills, and the ability to multitask in a fast-paced environment.\", \"vi\": \"Ứng viên phải có thái độ tích cực, kỹ năng chăm sóc khách hàng xuất sắc và khả năng xử lý nhiều công việc cùng lúc trong môi trường làm việc nhịp độ nhanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Zestful Cuisine offers competitive pay rates based on job experience.\", \"vi\": \"Zestful Cuisine đưa ra mức lương cạnh tranh dựa trên kinh nghiệm làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"All servers receive one meal during each shift.\", \"vi\": \"Tất cả các nhân viên phục vụ đều được nhận một bữa ăn trong mỗi ca làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We provide a career path with promotion and increased pay.\", \"vi\": \"Chúng tôi mang đến một lộ trình phát triển nghề nghiệp với cơ hội thăng tiến và mức lương ngày càng cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Applications are available on our Web site, www.zestfulcuisine.com.\", \"vi\": \"Quý vị có thể tải mẫu đơn đăng ký tại trang web của chúng tôi, www.zestfulcuisine.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '790f1cad-8778-4ab3-a3cf-0d80544d2ff6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Hong Kong Office Staff\", \"vi\": \"Đến: Nhân viên Văn phòng Hong Kong\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Wai-Lun Yeung\", \"vi\": \"Từ: Wai-Lun Yeung\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: Monday, 4 January\", \"vi\": \"Ngày: Thứ Hai, ngày 4 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Interns\", \"vi\": \"Chủ đề: Thực tập sinh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Colleagues,\", \"vi\": \"Kính gửi các đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am writing ---135--- you that two university students will be arriving next week and beginning their six-week internships in the Hong Kong office.\", \"vi\": \"Tôi viết thư này để ---135--- bạn rằng hai sinh viên đại học sẽ đến vào tuần tới và bắt đầu kỳ thực tập sáu tuần của họ tại văn phòng Hong Kong.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [135]}, {\"en\": \"Their duties will ---136--- consist of helping the Corporate Social Responsibility team organise their plans for the coming year.\", \"vi\": \"Nhiệm vụ của họ sẽ ---136--- bao gồm việc giúp đỡ đội ngũ Trách nhiệm Xã hội của Doanh nghiệp tổ chức các kế hoạch của họ cho năm tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [136]}, {\"en\": \"Both interns have strong backgrounds in responsible business practices.\", \"vi\": \"Cả hai thực tập sinh đều có nền tảng vững chắc về thực tiễn kinh doanh có trách nhiệm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As such, they will be well suited to their ---137---.\", \"vi\": \"Do đó, họ sẽ rất phù hợp với ---137--- của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [137]}, {\"en\": \"The interns will be using the vacant office in the east wing.\", \"vi\": \"Các thực tập sinh sẽ sử dụng văn phòng còn trống ở cánh phía đông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"---138---.\", \"vi\": \"---138---.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [138]}, {\"en\": \"Please let me know if you have any questions or concerns.\", \"vi\": \"Vui lòng cho tôi biết nếu bạn có bất kỳ câu hỏi hoặc thắc mắc nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"All best, Wai-Lun Yeung\", \"vi\": \"Trân trọng, Wai-Lun Yeung\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '792a5cba-49ab-4ec3-986c-38e3a5f40819';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"5 February\", \"vi\": \"Ngày 5 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Lou Spellman\", \"vi\": \"Lou Spellman\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Senior Project Manager\", \"vi\": \"Trưởng phòng Quản lý Dự án\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"North Perth Developers\", \"vi\": \"North Perth Developers\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"349 Doyle Street\", \"vi\": \"349 Phố Doyle\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"North Perth WA 6006\", \"vi\": \"North Perth WA 6006\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Mr. Spellman,\", \"vi\": \"Kính gửi Ông Spellman,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Thank you for your invitation to bid for the contract for Stonefield Apartments.\", \"vi\": \"Cảm ơn ông vì lời mời tham gia đấu thầu hợp đồng cho dự án Căn hộ Stonefield.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Enclosed you will find our bid, which ______[135] the price for which we could install the desired plumbing and a prospective timeline.\", \"vi\": \"Đính kèm đây là bản hồ sơ dự thầu của chúng tôi, trong đó ______[135] mức giá mà chúng tôi có thể lắp đặt hệ thống ống nước theo yêu cầu cùng với tiến độ dự kiến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [135]}, {\"en\": \"I believe you will find it to be a very attractive ______[136].\", \"vi\": \"Tôi tin rằng ông sẽ thấy đây là một ______[136] rất hấp dẫn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [136]}, {\"en\": \"______[137].\", \"vi\": \"______[137].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [137]}, {\"en\": \"We are currently finishing up the installation of all plumbing in the four-story Nowlin Hotel on schedule and under budget.\", \"vi\": \"Chúng tôi hiện đang hoàn tất việc lắp đặt toàn bộ hệ thống ống nước cho Khách sạn Nowlin bốn tầng đúng tiến độ và tiết kiệm hơn ngân sách dự kiến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"______[138] that, we equipped all 32 restrooms of the Rishley Center with reliable touchless sinks and toilets.\", \"vi\": \"______[138] việc đó, chúng tôi đã trang bị cho tất cả 32 phòng vệ sinh của Trung tâm Rishley các bồn rửa và bồn cầu cảm ứng đáng tin cậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [138]}, {\"en\": \"It would be my pleasure to speak with you about our bid or the Packard & Bowers crew.\", \"vi\": \"Tôi rất hân hạnh được trao đổi với ông về hồ sơ dự thầu của chúng tôi hoặc về đội ngũ nhân viên của Packard & Bowers.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I can be reached at 9291 4998.\", \"vi\": \"Tôi có thể được liên hệ qua số 9291 4998.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Bella Packard\", \"vi\": \"Bella Packard\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Packard & Bowers Plumbing\", \"vi\": \"Dịch vụ Hệ thống Ống nước Packard & Bowers\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Encl.\", \"vi\": \"Tài liệu đính kèm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '79374973-41bb-4d1b-865e-fd857ea148b7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Date of Request: April 2 - Type of Problem:\", \"vi\": \"Ngày gửi yêu cầu: 2 tháng 4 - Loại vấn đề:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Tenant: Lerner and Randall, LLC - Structural ☑\", \"vi\": \"Đơn vị thuê: Lerner and Randall, LLC - Kết cấu ☑\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Office: Suite B, Third floor - Electrical ☐\", \"vi\": \"Văn phòng: Phòng B, Tầng 3 - Điện ☐\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Tenant Contact Name: Amy Randall - Plumbing ☐\", \"vi\": \"Tên người liên hệ của người thuê nhà: Amy Randall - Hệ thống ống nước ☐\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Date Received: April 3 - Approved: Yes ☑ No ☐\", \"vi\": \"Ngày nhận: 3 tháng 4 - Đã được phê duyệt: Có ☑ Không ☐\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Assigned to: In-Su Kim - Approved by: Judy Blanch\", \"vi\": \"Giao cho: In-Su Kim - Phê duyệt bởi: Judy Blanch\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Pinecrest Office Park\", \"vi\": \"Khu văn phòng Pinecrest\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Request Form\", \"vi\": \"Mẫu đơn yêu cầu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Judy Blanch, Office Manager\", \"vi\": \"Judy Blanch, Trưởng phòng Hành chính\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"215.555.0118, extension 2\", \"vi\": \"215.555.0118, máy lẻ 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Brief Description of Work Needed:\", \"vi\": \"Mô tả tóm tắt về công việc cần thực hiện:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The ceiling over the window has developed a water leak, and the wall is beginning to discolor.\", \"vi\": \"Trần nhà phía trên cửa sổ đã xuất hiện vết rò rỉ nước, và bức tường đang bắt đầu bị đổi màu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Additional Instructions:\", \"vi\": \"Hướng dẫn bổ sung:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Before coming over, please call my office at 215.555.0127.\", \"vi\": \"Trước khi đến, xin vui lòng gọi điện đến văn phòng của tôi theo số 215.555.0127.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"My partner, Zach Lerner, and I would like to be present when the building staff is there.\", \"vi\": \"Tôi và đối tác của tôi, ông Zach Lerner, mong muốn được có mặt tại đó khi nhân viên tòa nhà đang làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"There is very expensive office equipment directly under that part of the ceiling.\", \"vi\": \"Ngay dưới phần trần nhà đó có những thiết bị văn phòng rất đắt tiền.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"We will need to move it before any repairs are made.\", \"vi\": \"Chúng tôi sẽ cần phải di dời nó trước khi tiến hành bất kỳ công việc sửa chữa nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"To Be Filled Out by Pinecrest Management:\", \"vi\": \"Phần này do Ban Quản lý Pinecrest điền vào:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Notes:\", \"vi\": \"Ghi chú:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Please investigate this problem early tomorrow morning after you call Ms. Randall.\", \"vi\": \"Kính mong quý vị tiến hành điều tra vấn đề này vào sáng sớm mai, sau khi quý vị đã gọi điện cho bà Randall.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"If roofing repairs are needed, e-mail John Roper (Roper Roofers – john@roperroofers.com), and set up an appointment for an estimate.\", \"vi\": \"Nếu cần sửa chữa mái nhà, xin vui lòng gửi email cho ông John Roper (Roper Roofers – john@roperroofers.com) và đặt lịch hẹn để được báo giá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '793aaad3-2e47-4f4b-81da-1c7353a875ff';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Caring for Your Rice Cooker\", \"vi\": \"Cách chăm sóc nồi cơm điện của bạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Before cleaning your rice cooker, detach the power cord from the electrical outlet.\", \"vi\": \"Trước khi vệ sinh nồi cơm điện, hãy tháo dây nguồn ra khỏi ổ cắm điện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Make sure all ------- (135) are completely cooled down.\", \"vi\": \"Đảm bảo rằng tất cả các ------- (135) đã nguội hẳn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"Next, remove the detachable pot and hand-wash it in warm, soapy water, along with the lid and rice paddle.\", \"vi\": \"Tiếp theo, hãy lấy nồi có thể tháo rời ra và rửa bằng tay trong nước ấm pha xà phòng, cùng với nắp và muỗng xới cơm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Note that the pot is not dishwasher safe.\", \"vi\": \"Lưu ý rằng nồi không dùng được trong máy rửa chén.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Note also that its nonstick surface ------- (136) damaged by abrasive cleaners.\", \"vi\": \"Cũng lưu ý rằng bề mặt chống dính của nó ------- (136) bị hỏng bởi các chất tẩy rửa có tính mài mòn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [136]}, {\"en\": \"Rather than scrape off any tough residue, soak the pot in warm, soapy water for ten minutes.\", \"vi\": \"Thay vì cạo sạch các cặn bẩn cứng đầu, hãy ngâm nồi trong nước ấm pha xà phòng trong mười phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"------- (137).\", \"vi\": \"------- (137).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [137]}, {\"en\": \"The exterior of the rice cooker should never be submerged in water.\", \"vi\": \"Không bao giờ được nhúng phần thân bên ngoài của nồi cơm điện vào trong nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"------- (138), gently wipe it down with a damp cloth.\", \"vi\": \"------- (138), hãy lau nhẹ nhàng bằng khăn ẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [138]}]' WHERE `id` = '79457ae2-65f5-431a-afd1-e4eeb5f6ddfa';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Samantha Vanetten <samantha@vanettenconsulting.com>\", \"vi\": \"Đến: Samantha Vanetten <samantha@vanettenconsulting.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Phillip Lee <plee@monroe-solutions.com>\", \"vi\": \"Từ: Phillip Lee <plee@monroe-solutions.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Inquiry\", \"vi\": \"Chủ đề: Yêu cầu thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: March 2\", \"vi\": \"Ngày: Ngày 2 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Monroe_Solutions\", \"vi\": \"Đính kèm: Monroe_Solutions\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Vanetten,\", \"vi\": \"Kính gửi bà Vanetten,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I recently received a ______[139] from my company for your seminar on establishing relationships with clients.\", \"vi\": \"Gần đây tôi đã nhận được một ______[139] từ công ty mình về hội thảo của bà về việc thiết lập mối quan hệ với khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [139]}, {\"en\": \"I was initially hesitant about the event.\", \"vi\": \"Ban đầu tôi đã do dự về sự kiện này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This is because the content of other seminars I\'ve attended has been either too basic or too technical.\", \"vi\": \"Điều này là do nội dung của các hội thảo khác mà tôi từng tham dự hoặc là quá cơ bản hoặc là quá chuyên kỹ thuật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"______[140] your talk was perfect for someone of my experience level.\", \"vi\": \"______[140] bài thuyết trình của bà lại hoàn hảo đối với người có mức độ kinh nghiệm như tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [140]}, {\"en\": \"Our firm is interested in hiring you for a private session at our company.\", \"vi\": \"Công ty chúng tôi rất quan tâm đến việc thuê bà tổ chức một buổi chia sẻ riêng tại công ty chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"______[141].\", \"vi\": \"______[141].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [141]}, {\"en\": \"Please let me know if you are available.\", \"vi\": \"Vui lòng cho tôi biết nếu bà có thời gian rảnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I have attached a brochure ______[142] our company\'s services.\", \"vi\": \"Tôi đã đính kèm một tập μάu quảng cáo ______[142] các dịch vụ của công ty chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": [142]}, {\"en\": \"Warmest regards,\", \"vi\": \"Trân trọng nhất,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Phillip Lee\", \"vi\": \"Phillip Lee\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '7962bf33-a3d5-4509-80df-e71a65efa640';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Date - Description - Cost\", \"vi\": \"Ngày - Mô tả - Chi phí\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"28/1 - Travel to meeting - £3\", \"vi\": \"28/1 - Chi phí đi lại để tham dự cuộc họp - 3 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"28/1 - Lunch with Yannick Le Mignon, Mazzira Group - £55\", \"vi\": \"28/1 - Bữa trưa cùng ông Yannick Le Mignon, Tập đoàn Mazzira - 55 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"28/1 - Return travel to office - £3\", \"vi\": \"28/1 - Chi phí đi lại trở lại văn phòng - 3 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Total reimbursement - £61\", \"vi\": \"Tổng số tiền được hoàn trả - 61 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Lorene Industries\", \"vi\": \"Lorene Industries\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Reimbursement Request Form\", \"vi\": \"Mẫu đơn yêu cầu hoàn trả chi phí\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Name: Timothy Oswell     Supervisor\'s name: Laura Cho\", \"vi\": \"Họ tên: Timothy Oswell     Tên người hướng dẫn: Laura Cho\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Department: Advertising     ID: 8123976\", \"vi\": \"Bộ phận: Quảng cáo     Mã số: 8123976\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Position: Project manager\", \"vi\": \"Chức danh: Quản lý dự án\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Itemized expenses:\", \"vi\": \"Chi tiết các khoản chi phí:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Funds will not be issued to employees without itemized receipts.\", \"vi\": \"Tiền sẽ không được chi trả cho nhân viên nếu không có hóa đơn chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Credits for claimed reimbursements will be added to the employee\'s regular biweekly paycheck.\", \"vi\": \"Số tiền được hoàn trả theo yêu cầu sẽ được cộng vào khoản lương hai tuần một lần thông thường của nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Amounts over £100 will not be processed during the current pay period.\", \"vi\": \"Các khoản tiền vượt quá 100 bảng Anh sẽ không được xử lý trong kỳ trả lương hiện tại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Instead, they will be reimbursed at the end of the following quarter.\", \"vi\": \"Thay vào đó, họ sẽ được hoàn trả vào cuối quý tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Employee signature: Timothy Oswell\", \"vi\": \"Chữ ký của nhân viên: Timothy Oswell\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Supervisor signature: Laura Cho\", \"vi\": \"Chữ ký của người giám sát: Laura Cho\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Form received date: 30/1 Receipts attached?\", \"vi\": \"Ngày nhận được mẫu đơn: 30/1. Đã đính kèm biên lai chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Yes\", \"vi\": \"Vâng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Finance department reimbursement officer approval: Tia Jegerfalk\", \"vi\": \"Sự phê duyệt của cán bộ phụ trách hoàn trả chi phí thuộc Phòng Tài chính: Tia Jegerfalk\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '797195a1-2ea4-470f-a255-be0461fa8e30';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Lanie McGinnis (7:16 A.M.)\", \"vi\": \"Lanie McGinnis (7 giờ 16 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Good morning, Kelly and Matthieu.\", \"vi\": \"Chào buổi sáng, Kelly và Matthieu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I removed the Funfair preregistration signs from the park entrances, but I think I forgot one at the north gate.\", \"vi\": \"Tôi đã tháo các biển báo đăng ký trước sự kiện Funfair tại các lối vào công viên, nhưng tôi nghĩ mình đã bỏ sót một biển báo ở cổng phía bắc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Could one of you check to see if it is still there?\", \"vi\": \"Có ai trong số các vị có thể kiểm tra xem nó còn ở đó không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Kelly Sen (7:18 A.M.)\", \"vi\": \"Kelly Sen (7 giờ 18 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Hi, Lanie.\", \"vi\": \"Xin chào, Lanie.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I rode my bike to the park earlier this morning to help put pamphlets and other materials on the welcome table in the main tent.\", \"vi\": \"Sáng nay, tôi đã đạp xe đến công viên để giúp sắp xếp các tờ rơi và các tài liệu khác lên bàn tiếp đón trong lều chính.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"But I could head over to that entrance now since there are other volunteers here who can finish up.\", \"vi\": \"Tuy nhiên, tôi có thể sang lối vào đó ngay bây giờ vì ở đây còn có các tình nguyện viên khác có thể lo nốt phần việc còn lại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Lanie McGinnis (7:19 A.M.)\", \"vi\": \"Lanie McGinnis (7 giờ 19 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"That would be great, since I\'m going to be on the other side of the park at the south entrance for a while.\", \"vi\": \"Điều đó thật tuyệt, vì tôi sẽ ở phía bên kia công viên, tại cổng phía nam, trong một thời gian.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I\'m meeting some representatives from the city parks department.\", \"vi\": \"Tôi sẽ có cuộc gặp với một số đại diện của Sở Công viên thành phố.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Matthieu Herman (7:21 A.M.)\", \"vi\": \"Matthieu Herman (7 giờ 21 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I\'ve got it, Kelly.\", \"vi\": \"Tôi hiểu rồi, Kelly.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I just arrived at the north entrance and will take down the sign we hung here.\", \"vi\": \"Tôi vừa đến cổng phía bắc và sẽ tháo tấm biển mà chúng tôi đã treo ở đây xuống.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Lanie, what would you like me to do with it?\", \"vi\": \"Lanie ạ, cô muốn tôi xử lý nó thế nào đây?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Lanie McGinnis (7:22 A.M.)\", \"vi\": \"Lanie McGinnis (7 giờ 22 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Perfect!\", \"vi\": \"Tuyệt vời!\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Can you put it with the others behind the welcome table in the main tent?\", \"vi\": \"Xin quý vị vui lòng đặt nó cùng với những thứ khác phía sau bàn tiếp đón trong lều chính được không?\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I will pick them up later today.\", \"vi\": \"Tôi sẽ đến lấy chúng vào cuối ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"We can change the dates and use them again next year.\", \"vi\": \"Chúng ta có thể thay đổi các ngày này và sử dụng lại vào năm sau.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Matthieu Herman (7:23 A.M.)\", \"vi\": \"Matthieu Herman (7 giờ 23 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Will do.\", \"vi\": \"Tôi sẽ làm như vậy.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Here\'s to a successful fair!\", \"vi\": \"Chúc hội chợ diễn ra thành công tốt đẹp!\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '79deb1f6-3501-4bae-84ac-8b1958afe5fc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Sparkle Pro Enterprises Opens American Factory\", \"vi\": \"Sparkle Pro Enterprises Mở Nhà Máy Tại Mỹ\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Worldwide News\", \"vi\": \"Tin Tức Toàn Cầu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"MANCHESTER (10 April)—Sparkle Pro Enterprises, a leading Belgium-based ______[143] of cleaning products, is expanding its territory.\", \"vi\": \"MANCHESTER (Ngày 10 tháng 4)—Sparkle Pro Enterprises, một ______[143] hàng đầu có trụ sở tại Bỉ chuyên về các sản phẩm làm sạch, đang mở rộng thị trường của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [143]}, {\"en\": \"The company has just opened its first plant in the United States, in Indianapolis.\", \"vi\": \"Công ty vừa mới mở nhà máy đầu tiên tại Hoa Kỳ, ở Indianapolis.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"For more than forty years, Sparkle Pro has been making and distributing household and industrial cleaners to a wide range of vendors, including retail outlets and hotel chains, throughout Europe.\", \"vi\": \"Trong hơn bốn mươi năm qua, Sparkle Pro đã sản xuất và phân phối các chất tẩy rửa gia dụng và công nghiệp cho rất nhiều nhà cung cấp, bao gồm các cửa hàng bán lẻ và chuỗi khách sạn, trên khắp châu Âu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[144].\", \"vi\": \"______[144].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [144]}, {\"en\": \"The Indianapolis facility will require the company to hire 300 additional employees ______[145] the end of this year in order for it to achieve full capacity.\", \"vi\": \"Nhà máy tại Indianapolis sẽ đòi hỏi công ty phải tuyển dụng thêm 300 nhân viên trước ______[145] cuối năm nay để có thể đạt công suất hoạt động tối đa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [145]}, {\"en\": \"According to Egan Bretz, the new director of North American operations, Sparkle Pro is confident that it will be able to train a large number of personnel quickly.\", \"vi\": \"Theo ông Egan Bretz, giám đốc mới của bộ phận kinh doanh tại Bắc Mỹ, Sparkle Pro tự tin rằng họ sẽ có thể đào tạo một lượng lớn nhân sự một cách nhanh chóng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Mr. Bretz expects no significant ______[146] in meeting these needs.\", \"vi\": \"Ông Bretz không kỳ vọng sẽ gặp phải ______[146] đáng kể nào trong việc đáp ứng những nhu cầu này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [146]}]' WHERE `id` = '7a93e364-8539-4fbe-a6e7-4356db7aced9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Sledgehammer Gym Staff\", \"vi\": \"Gửi: Toàn thể nhân viên Phòng tập Sledgehammer\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Lucas Sledge\", \"vi\": \"Từ: Lucas Sledge\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: September 15\", \"vi\": \"Ngày: 15 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Payroll changes\", \"vi\": \"Chủ đề: Những thay đổi liên quan đến bảng lương\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment:  Form\", \"vi\": \"Tệp đính kèm:  Mẫu đơn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Staff,\", \"vi\": \"Kính gửi quý đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thanks to your dedicated work, word of our little gym has spread.\", \"vi\": \"Nhờ sự cống hiến của quý vị, tin tức về phòng tập nhỏ của chúng tôi đã được lan truyền rộng rãi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Over the past twelve months, enrollment has significantly increased and so has our teaching staff.\", \"vi\": \"Trong mười hai tháng qua, số lượng học sinh đăng ký nhập học đã tăng đáng kể và đội ngũ giảng viên của chúng tôi cũng tăng theo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Although this growth is wonderful, having to process the payroll by myself has become rather burdensome.\", \"vi\": \"Mặc dù sự phát triển này thật đáng mừng, nhưng việc phải tự mình xử lý bảng lương đã trở nên khá nặng nề.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Therefore, I have contracted Trumbull and Company to provide direct deposit of your wages into your bank accounts.\", \"vi\": \"Do đó, tôi đã ký hợp đồng với Công ty Trumbull để thực hiện việc chuyển khoản trực tiếp tiền lương của quý vị vào tài khoản ngân hàng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Consequently, you no longer need to deposit your paycheck yourself.\", \"vi\": \"Do đó, quý vị sẽ không còn phải tự mình gửi tiền lương vào tài khoản nữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Also, you will now be able to get your pay stubs and tax information online.\", \"vi\": \"Ngoài ra, từ nay quý vị sẽ có thể tra cứu phiếu lương và thông tin thuế của mình trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To allow for these changes, I am asking everyone to provide me with the necessary banking details.\", \"vi\": \"Để thực hiện những thay đổi này, tôi xin đề nghị quý vị vui lòng cung cấp cho tôi các thông tin tài khoản ngân hàng cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Please complete the attached form and bring it to the office with a voided check no later than September 25.\", \"vi\": \"Kính mong quý vị điền đầy đủ vào mẫu đơn đính kèm và mang đến văn phòng kèm theo một tấm séc đã hủy chậm nhất là vào ngày 25 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The new process will take effect in October.\", \"vi\": \"Quy trình mới sẽ có hiệu lực vào tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Please let me know if you have any questions.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Take care,\", \"vi\": \"Xin hãy giữ gìn sức khỏe,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Lucas\", \"vi\": \"Luke\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '7b315617-ae6d-452e-b85c-768e59df8ab6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Annual Citrus Production in Yuma County\", \"vi\": \"Sản lượng cam quýt hàng năm tại Hạt Yuma\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"82 tons of citrus fruit\", \"vi\": \"82 tấn trái cây họ cam quýt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Over 120,000 boxes of lemons\", \"vi\": \"Hơn 120.000 thùng chanh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"15,000 boxes of oranges\", \"vi\": \"15.000 thùng cam\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"9,000 boxes of grapefruit\", \"vi\": \"9.000 thùng bưởi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"$190 million in revenue\", \"vi\": \"Doanh thu đạt 190 triệu đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Employing close to 3,000 workers and contributing nearly $2 million in taxes to fund public services for the county\", \"vi\": \"Doanh nghiệp này hiện có gần 3.000 lao động và đóng góp gần 2 triệu đô la tiền thuế để tài trợ cho các dịch vụ công của quận\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"—Arizona Agriculture Division\", \"vi\": \"—Cục Nông nghiệp bang Arizona\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"City West Bank\", \"vi\": \"Thành phố West Bank\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"455 Canyon Avenue\", \"vi\": \"455 Đại lộ Canyon\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Phoenix, Arizona 85007\", \"vi\": \"Phoenix, Arizona 85007\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"March 21\", \"vi\": \"Ngày 21 tháng 3\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Domingo Ramirez, Director\", \"vi\": \"Domingo Ramirez, Giám đốc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Arizona Agriculture Division\", \"vi\": \"Cục Nông nghiệp bang Arizona\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"55 Sixth Avenue\", \"vi\": \"Số 55, Đại lộ Sixth\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Yuma, Arizona 85364\", \"vi\": \"Yuma, Arizona 85364\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Dear Mr. Ramirez,\", \"vi\": \"Kính gửi ông Ramirez,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I read the recent report from the Arizona Agriculture Division summarizing Yuma County\'s success in the citrus industry.\", \"vi\": \"Tôi đã đọc báo cáo gần đây của Cục Nông nghiệp bang Arizona, trong đó tóm tắt những thành công của Hạt Yuma trong ngành công nghiệp cây có múi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"City West Bank wants to help the Arizona Agriculture Division you lead by expanding this industry further.\", \"vi\": \"Thành phố West Bank mong muốn hỗ trợ Sở Nông nghiệp bang Arizona do quý vị đứng đầu bằng cách thúc đẩy sự phát triển hơn nữa của ngành này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"We offer low-interest loans and provide expert advice through our connections to area chambers of commerce and to agricultural researchers at Arizona\'s state universities.\", \"vi\": \"Chúng tôi cung cấp các khoản vay với lãi suất thấp và tư vấn chuyên môn thông qua mối quan hệ hợp tác với các phòng thương mại trong khu vực cũng như các nhà nghiên cứu nông nghiệp tại các trường đại học công lập của bang Arizona.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We recognize that agritourism in southwest Arizona is growing as a result of the popularity of farm tours, bird-watching, and scenic country lodging, but tourism is unlikely to surpass the strength of this region\'s agriculture production.\", \"vi\": \"Chúng tôi nhận thấy rằng du lịch nông nghiệp tại vùng Tây Nam Arizona đang ngày càng phát triển nhờ sự phổ biến của các tour tham quan trang trại, hoạt động ngắm chim và các dịch vụ lưu trú tại vùng nông thôn với khung cảnh thơ mộng; tuy nhiên, ngành du lịch khó có thể vượt qua sức mạnh của ngành sản xuất nông nghiệp tại khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"We support farmers in many counties in Arizona and are poised to help the citrus growers in Yuma County.\", \"vi\": \"Chúng tôi hỗ trợ nông dân tại nhiều quận ở Arizona và sẵn sàng hỗ trợ những người trồng cam quýt tại Quận Yuma.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Together, we can accomplish great things.\", \"vi\": \"Khi cùng nhau, chúng ta có thể đạt được những thành tựu vĩ đại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Cordially,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Bianca Schreiber\", \"vi\": \"Bianca Schreiber\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Bianca Schreiber\", \"vi\": \"Bianca Schreiber\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Industry Investment Programs\", \"vi\": \"Các chương trình đầu tư vào ngành\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Schreiber Named Vice President of National Investment Strategies\", \"vi\": \"Ông Schreiber được bổ nhiệm làm Phó Chủ tịch phụ trách Chiến lược Đầu tư Quốc gia\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"PHOENIX (January 19)—City West Bank announced today that Ms. Bianca Schreiber will be promoted to vice president of National Investment Strategies effective February 1.\", \"vi\": \"PHOENIX (ngày 19 tháng 1) — Ngân hàng City West Bank hôm nay thông báo rằng bà Bianca Schreiber sẽ được thăng chức lên vị trí Phó Chủ tịch phụ trách Chiến lược Đầu tư Toàn quốc, có hiệu lực từ ngày 1 tháng 2.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Ms. Schreiber currently oversees City West Bank\'s Industry Investment Programs, serving businesses throughout Arizona.\", \"vi\": \"Hiện tại, bà Schreiber đang phụ trách các Chương trình Đầu tư Ngành của Ngân hàng City West, phục vụ các doanh nghiệp trên toàn bang Arizona.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Bank President William Dolle cited Ms. Schreiber\'s record of successful investment in the agricultural sector.\", \"vi\": \"Chủ tịch Ngân hàng William Dolle đã nêu bật thành tích đầu tư thành công của bà Schreiber trong lĩnh vực nông nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"\\\"Ms. Schreiber\'s efforts in working with the director of the Arizona Agriculture Division have significantly boosted citrus production.\", \"vi\": \"\\\"Những nỗ lực của bà Schreiber trong việc hợp tác với Giám đốc Sở Nông nghiệp bang Arizona đã góp phần thúc đẩy đáng kể sản lượng cam quýt.\\\"\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Yuma County now produces as many grapefruit as it does oranges.\", \"vi\": \"Hiện nay, sản lượng bưởi của Hạt Yuma đã ngang bằng với sản lượng cam.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Ms. Schreiber\'s keen insight will make her even more valuable to us in her new role,\\\" remarked Mr. Dolle.\", \"vi\": \"“Sự nhạy bén của bà Schreiber sẽ khiến bà trở nên quý giá hơn nữa đối với chúng tôi trong vai trò mới của mình,” ông Dolle nhận xét.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '7b71e592-ecec-4f91-98a5-94ac948988f7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"RHC Continues to Impress\", \"vi\": \"RHC tiếp tục gây ấn tượng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"FOR IMMEDIATE RELEASE\", \"vi\": \"THÔNG CÁO BÁO CHÍ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Contact: Dora Su, +65 0555 1294\", \"vi\": \"Liên hệ: Dora Su, +65 0555 1294\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"SINGAPORE (3 August)—In operation for five years, Rayder Holdings Corporation (RHC) is announcing the completion of its sixth renovation project, Bay Commons.\", \"vi\": \"SINGAPORE (ngày 3 tháng 8) — Sau năm năm đi vào hoạt động, Tập đoàn Rayder Holdings (RHC) xin thông báo về việc hoàn thành dự án cải tạo thứ sáu của mình, đó là Bay Commons.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The company, founded by real estate agents Rayna Wong and Derrick Lim, specializes in converting industrial buildings into apartment complexes.\", \"vi\": \"Công ty này, do hai chuyên viên môi giới bất động sản Rayna Wong và Derrick Lim thành lập, chuyên chuyển đổi các tòa nhà công nghiệp thành các khu chung cư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"“Turning commercial buildings into residential spaces has its challenges,” Ms. Wong said.\", \"vi\": \"“Việc chuyển đổi các tòa nhà thương mại thành không gian cư trú cũng gặp không ít thách thức,” bà Wong cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"“However, we are committed to repurposing buildings instead of constructing new ones.”\", \"vi\": \"“Tuy nhiên, chúng tôi cam kết tái sử dụng các tòa nhà thay vì xây dựng các công trình mới.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This commitment was recently cited in a speech by Yamina Badawi, Singapore’s minister of Housing and Urban Development, who applauded RHC’s contribution to the nation’s housing supply.\", \"vi\": \"Cam kết này gần đây đã được bà Yamina Badawi, Bộ trưởng Bộ Nhà ở và Phát triển Đô thị Singapore, nhắc đến trong một bài phát biểu, trong đó bà đã ghi nhận những đóng góp của RHC đối với nguồn cung nhà ở của đất nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"RHC completed its first conversion project four years ago—the Kallang Overlook apartment complex.\", \"vi\": \"RHC đã hoàn thành dự án cải tạo đầu tiên của mình cách đây bốn năm — khu chung cư Kallang Overlook.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Since then, RHC has completed five more projects: Aston Estates, Tampines Tower, Lakeside Manor, Yishun Terrace, and now Bay Commons.\", \"vi\": \"Kể từ đó, RHC đã hoàn thành thêm năm dự án nữa: Aston Estates, Tampines Tower, Lakeside Manor, Yishun Terrace và hiện nay là Bay Commons.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"“Bay Commons represents a departure from our previous projects,” Ms. Wong noted.\", \"vi\": \"“Dự án Bay Commons đánh dấu một bước chuyển mình so với các dự án trước đây của chúng tôi,” bà Wong nhấn mạnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"“This housing complex is designed primarily for students at the nearby Changi Technological Institute.”\", \"vi\": \"“Khu nhà ở này được thiết kế chủ yếu dành cho sinh viên của Học viện Công nghệ Changi nằm gần đó.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Units at Bay Commons are now available for rent or purchase, she added.\", \"vi\": \"Bà cho biết thêm, các căn hộ tại Bay Commons hiện đã sẵn sàng để cho thuê hoặc mua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"https://www.rayderholdingscorporation.com.sg/current-listings\", \"vi\": \"https://www.rayderholdingscorporation.com.sg/current-listings\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"About Us - Current Listings - News - Careers\", \"vi\": \"Giới thiệu về chúng tôi - Danh sách hiện tại - Tin tức - Cơ hội nghề nghiệp\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Rayder Holdings Corporation turns vacant commercial properties into pleasant residential buildings.\", \"vi\": \"Tập đoàn Rayder Holdings chuyên biến các bất động sản thương mại bỏ trống thành những tòa nhà dân cư tiện nghi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Below are our current offerings in alphabetical order.\", \"vi\": \"Dưới đây là các sản phẩm hiện có của chúng tôi, được sắp xếp theo thứ tự bảng chữ cái.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Aston Estates: 14-unit building with pool, fitness centre, and car park\", \"vi\": \"Aston Estates: Tòa nhà gồm 14 căn hộ, có hồ bơi, trung tâm thể dục thể thao và bãi đỗ xe\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Bay Commons: 60 studio apartments with shared kitchen areas and other common rooms\", \"vi\": \"Bay Commons: 60 căn hộ studio với khu bếp chung và các phòng sinh hoạt chung khác\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Kallang Overlook: 40-unit apartment complex situated on the Kallang River\", \"vi\": \"Kallang Overlook: Khu chung cư gồm 40 căn hộ tọa lạc bên sông Kallang\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Lakeside Manor: 28-unit building with indoor pool, outdoor tennis and basketball courts, playground, and on-site cafeteria\", \"vi\": \"Lakeside Manor: Tòa nhà gồm 28 căn hộ, có bể bơi trong nhà, sân tennis và sân bóng rổ ngoài trời, khu vui chơi cho trẻ em, cùng nhà ăn ngay trong khuôn viên\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Tampines Tower: 36-unit apartment complex with pool and fitness room\", \"vi\": \"Tampines Tower: Khu chung cư gồm 36 căn hộ, có hồ bơi và phòng tập thể dục\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Yishun Terrace: 55-unit apartment with outdoor sports facilities (tennis, basketball, football), indoor swimming pool, catch-and release fishing pond, and picnic area\", \"vi\": \"Yishun Terrace: Khu chung cư gồm 55 căn hộ, được trang bị các cơ sở thể thao ngoài trời (quần vợt, bóng rổ, bóng đá), bể bơi trong nhà, ao câu cá theo hình thức “câu và thả” cùng khu vực dã ngoại\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"For details and other queries, contact info@rayderholdingscorporation.com.sg.\", \"vi\": \"Để biết thêm chi tiết hoặc có bất kỳ thắc mắc nào khác, xin vui lòng liên hệ qua địa chỉ email info@rayderholdingscorporation.com.sg.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Today 9:53 A.M.\", \"vi\": \"Hôm nay, 9 giờ 53 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Hello, Mr. Goh.\", \"vi\": \"Xin chào, ông Goh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"A fellow resident found your wallet on the cafeteria counter and dropped it off here at the RHC leasing office.\", \"vi\": \"Một cư dân khác đã tìm thấy ví của quý vị trên quầy của căng-tin và mang đến đây, tại văn phòng cho thuê RHC.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Please stop by to pick it up.\", \"vi\": \"Xin quý vị vui lòng ghé qua để nhận món đồ này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"We are open until 6:00 P.M. For after-hours service, call 0904 6802, and someone will assist you.\", \"vi\": \"Chúng tôi mở cửa đến 6 giờ chiều. Để được hỗ trợ ngoài giờ làm việc, xin vui lòng gọi số 0904 6802, và sẽ có nhân viên hỗ trợ quý khách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Alicia Rajani, Office Manager\", \"vi\": \"Alicia Rajani, Trưởng phòng Hành chính\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}]' WHERE `id` = '7bdcd04d-e765-4518-8896-5d6734a6fd47';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Cherville Simplifies Local Tourism\", \"vi\": \"Cherville Đơn Giản Hóa Ngành Du Lịch Địa Phương\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"10 May - The city of Cherville boasts charming architecture and a breathtaking countryside that has long been appreciated by residents.\", \"vi\": \"Ngày 10 tháng 5 - Thành phố Cherville tự hào với kiến trúc quyến rũ và vùng nông thôn đẹp ngoạn mục từ lâu đã được cư dân trân trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Thanks to the recent introduction of a train service, tourists are now able to ______[135] the city as well.\", \"vi\": \"Nhờ vào việc gần đây đưa vào hoạt động một tuyến tàu hỏa, khách du lịch giờ đây cũng có thể ______[135] thành phố này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"As a result of Cherville\'s rise in popularity, existing tourism-related businesses are booming.\", \"vi\": \"Do mức độ phổ biến ngày càng tăng của Cherville, các doanh nghiệp liên quan đến du lịch hiện tại đang bùng nổ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"______[136].\", \"vi\": \"______[136].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [136]}, {\"en\": \"To help tourists and businesses, the Cherville Commerce Bureau has debuted the Citycard.\", \"vi\": \"Để hỗ trợ khách du lịch và các doanh nghiệp, Cục Thương mại Cherville đã cho ra mắt thẻ Citycard.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"When swiped, the card automatically applies ______[137] at local businesses and attractions.\", \"vi\": \"Khi được quẹt, chiếc thẻ này sẽ tự động áp dụng ______[137] tại các doanh nghiệp và điểm tham quan địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [137]}, {\"en\": \"The Bureau believes that the Citycard will please tourists, who will benefit from lower prices.\", \"vi\": \"Cục tin rằng thẻ Citycard sẽ làm hài lòng khách du lịch, những người sẽ được hưởng lợi từ mức giá thấp hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[138], the card should encourage retail traffic, leading to increased profits for businesses.\", \"vi\": \"______[138], chiếc thẻ này sẽ thúc đẩy lượng khách mua sắm, dẫn đến lợi nhuận tăng cho các doanh nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [138]}]' WHERE `id` = '7c0a9623-f2c1-4a97-a99a-b5d7da529804';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Small Business News\", \"vi\": \"Tin tức về doanh nghiệp nhỏ\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"By Anna Fortin\", \"vi\": \"Tác giả: Anna Fortin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"PRESTON (29 August)—The town\'s small business boom continues, creating new jobs and strengthening local markets.\", \"vi\": \"PRESTON (ngày 29 tháng 8) — Sự phát triển mạnh mẽ của các doanh nghiệp nhỏ tại thị trấn này vẫn tiếp diễn, tạo ra nhiều việc làm mới và củng cố thị trường địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"In fact, Preston\'s small businesses employed 4,300 people last year, equaling 25 percent of the local labor force.\", \"vi\": \"Thực tế, các doanh nghiệp nhỏ tại Preston đã tạo việc làm cho 4.300 người trong năm ngoái, chiếm 25 phần trăm lực lượng lao động địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"Small businesses are definitely a key economic driver,\\\" explains Dr. Henry Belanger, who teaches finance at Lackland University.\", \"vi\": \"\\\"Các doanh nghiệp nhỏ chắc chắn là một động lực kinh tế quan trọng,\\\" Tiến sĩ Henry Belanger, giảng viên bộ môn tài chính tại Đại học Lackland, giải thích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"\\\"Start-up businesses are a significant engine for job creation.\\\"\", \"vi\": \"\\\"Các doanh nghiệp khởi nghiệp là động lực quan trọng trong việc tạo ra việc làm.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"According to Belanger, Preston is part of a province-wide trend.\", \"vi\": \"Theo ông Belanger, Preston là một phần của xu hướng đang diễn ra trên toàn tỉnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"\\\"Last year, the province saw job expansion above the national average, adding more than 19,000 jobs overall,\\\" adds more than 19,000 jobs overall,\\\" Dr. Belanger said.\", \"vi\": \"\\\"Năm ngoái, tỉnh này đã ghi nhận mức tăng trưởng việc làm cao hơn mức trung bình toàn quốc, với tổng số việc làm mới được tạo ra vượt quá 19.000,\\\" Tiến sĩ Belanger cho biết thêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"About 17 percent were in small businesses.\", \"vi\": \"\\\"Khoảng 17 phần trăm làm việc tại các doanh nghiệp nhỏ.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Moreover, thanks to the personal income generated by small companies, larger, established businesses benefited too.\\\"\", \"vi\": \"Hơn nữa, nhờ vào thu nhập cá nhân do các doanh nghiệp nhỏ tạo ra, các doanh nghiệp lớn và đã có chỗ đứng trên thị trường cũng được hưởng lợi.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Parties interested in starting a business can access the government\'s Provincial Small Business Center for help in creating a business plan, finding capital, and learning marketing strategies.\", \"vi\": \"Các bên quan tâm đến việc khởi nghiệp có thể liên hệ với Trung tâm Doanh nghiệp Nhỏ cấp tỉnh của chính phủ để được hỗ trợ trong việc lập kế hoạch kinh doanh, tìm kiếm nguồn vốn và tìm hiểu các chiến lược tiếp thị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '7c1cf3e1-3e1e-4fa7-88ed-d15739788cf2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Smith County Transportation Department\\nCurrent Postings\", \"vi\": \"Sở Giao thông Vận tải Hạt Smith\\nCác thông báo tuyển dụng hiện tại\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Bridge Inspector (BI9253)—Take your career to new heights as a bridge inspector in beautiful Smith County, known for its spectacular and varied landscape!\", \"vi\": \"Thanh tra cầu đường (BI9253) — Hãy đưa sự nghiệp của quý vị vươn lên những tầm cao mới với vai trò thanh tra cầu đường tại Hạt Smith xinh đẹp, nơi nổi tiếng với cảnh quan hùng vĩ và đa dạng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The geography of our county is large and hilly, necessitating the use of our many bridges and tunnels by residents and tourists alike.\", \"vi\": \"Địa hình của huyện chúng tôi rộng lớn và đồi núi, do đó cả người dân lẫn du khách đều phải đi qua rất nhiều cây cầu và đường hầm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The position involves assessing the condition of existing bridges, tunnels, culverts, and related road signs as well as proposing and overseeing repairs.\", \"vi\": \"Vị trí công việc này bao gồm việc đánh giá tình trạng của các cây cầu, đường hầm, cống thoát nước hiện có và các biển báo giao thông liên quan, cũng như đề xuất và giám sát các công tác sửa chữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We offer competitive salaries with excellent benefits.\", \"vi\": \"Chúng tôi cung cấp mức lương cạnh tranh cùng với các chế độ phúc lợi tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"For details on requirements and how to apply, please visit www.smithcounty.gov/jobs.\", \"vi\": \"Để biết thêm chi tiết về các yêu cầu và cách thức nộp đơn, vui lòng truy cập trang web www.smithcounty.gov/jobs.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The deadline is January 15.\", \"vi\": \"Hạn chót là ngày 15 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '7c55cc66-663b-4e1d-bac9-e6ddb1c546bb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"16 October\", \"vi\": \"Ngày 16 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Daniel McGill\", \"vi\": \"Daniel McGill\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Page by Page Bookshop\", \"vi\": \"Hiệu sách Page by Page\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"477 Armory Street\", \"vi\": \"477 Phố Armory\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Rochester, NY 14604\", \"vi\": \"Rochester, NY 14604\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. McGill,\", \"vi\": \"Kính gửi ông McGill,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Grantham Publishing is seeking independent retailers to carry our latest work, Beneath the Surface.\", \"vi\": \"Nhà xuất bản Grantham đang tìm kiếm các nhà bán lẻ độc lập để phân phối tác phẩm mới nhất của chúng tôi, *Beneath the Surface*.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Having received rave reviews from literary critics, the novel brings its readers a unique combination of drama and science.\", \"vi\": \"Đã nhận được những lời khen ngợi nồng nhiệt từ các nhà phê bình văn học, cuốn tiểu thuyết này mang đến cho độc giả sự kết hợp độc đáo giữa yếu tố kịch tính và khoa học.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Beneath the Surface examines what happens to broken and outdated computers and smartphones once they are no longer in use.\", \"vi\": \"Tác phẩm “Beneath the Surface” tìm hiểu xem những chiếc máy tính và điện thoại thông minh bị hỏng hoặc đã lỗi thời sẽ ra sao sau khi không còn được sử dụng nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Although it is a fictional account of a small town negatively affected by soil contamination at its local landfill, it contains factual information based on the latest research.\", \"vi\": \"Mặc dù đây là một câu chuyện hư cấu về một thị trấn nhỏ phải hứng chịu những tác động tiêu cực do ô nhiễm đất tại bãi rác địa phương, nhưng tác phẩm này vẫn chứa đựng những thông tin thực tế dựa trên các nghiên cứu mới nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The two authors of Beneath the Surface are Nathaniel Lee, an environmental scientist, and Dr. Cecelia Sandoval, an ecology professor at Wilford University.\", \"vi\": \"Hai tác giả của cuốn sách *Beneath the Surface* là ông Nathaniel Lee, một nhà khoa học môi trường, và Tiến sĩ Cecelia Sandoval, giáo sư sinh thái học tại Đại học Wilford.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Mr. Lee has been awarded the prestigious Caldwell Prize, and Dr. Sandoval is acclaimed for consulting for an online educational program.\", \"vi\": \"Ông Lee đã vinh dự được trao Giải thưởng Caldwell danh giá, còn Tiến sĩ Sandoval được đánh giá cao nhờ vai trò cố vấn cho một chương trình giáo dục trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"They are making their publishing debut with Beneath the Surface and would be happy to sign some of the copies being sent to your store.\", \"vi\": \"Đây là lần đầu tiên họ ra mắt tác phẩm với cuốn *Beneath the Surface* và họ rất hân hạnh được ký tặng một số bản sách sẽ được gửi đến cửa hàng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I can provide you with further details about Beneath the Surface anytime.\", \"vi\": \"Tôi có thể cung cấp cho quý vị thêm thông tin chi tiết về cuốn sách “Beneath the Surface” bất cứ lúc nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I look forward to hearing from you.\", \"vi\": \"Tôi rất mong nhận được phản hồi từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"All the best,\", \"vi\": \"Chúc quý vị mọi điều tốt đẹp nhất,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Zachary Wesley\", \"vi\": \"Zachary Wesley\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '7c59e878-a510-416c-a844-66592c66f040';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Greg Skagen (8:58 A.M.) Hi, Brenda.\", \"vi\": \"Greg Skagen (8 giờ 58 phút sáng) Xin chào, Brenda.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I\'m here in the warehouse.\", \"vi\": \"Tôi đang ở trong kho.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"All of my trainees have arrived, but I noticed the power door at Loading Dock B is acting up.\", \"vi\": \"Tất cả các học viên của tôi đã đến nơi, nhưng tôi nhận thấy cửa tự động tại Bến bốc dỡ B đang gặp trục trặc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Brenda Sadauskas (8:59 A.M.) Again?\", \"vi\": \"Brenda Sadauskas (8 giờ 59 phút sáng) Lại nữa sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Greg Skagen (8:59 A.M.) When I push the button to open it, it raises all the way up but then drops back down to the closed position after about 30 seconds.\", \"vi\": \"Greg Skagen (8 giờ 59 phút sáng) Khi tôi nhấn nút để mở, nó nâng lên hết cỡ nhưng sau đó lại hạ xuống vị trí đóng sau khoảng 30 giây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Brenda Sadauskas (9:00 A.M.) I\'ll come down with the maintenance technicians.\", \"vi\": \"Brenda Sadauskas (9 giờ sáng) Tôi sẽ xuống cùng các kỹ thuật viên bảo trì.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Why don\'t you bring your trainees to my area?\", \"vi\": \"Sao quý vị không đưa các học viên của mình đến khu vực của tôi nhỉ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You can teach them how to create shipping labels and then have them pack and label this morning\'s shipments.\", \"vi\": \"Quý vị có thể hướng dẫn họ cách tạo nhãn vận chuyển, sau đó giao cho họ việc đóng gói và dán nhãn cho các lô hàng của sáng nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Greg Skagen (9:02 A.M.) Yes, that works.\", \"vi\": \"Greg Skagen (9 giờ 02 phút sáng) Vâng, như vậy được rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Brenda Sadauskas (9:03 A.M.) Thanks.\", \"vi\": \"Brenda Sadauskas (9 giờ 03 phút sáng). Cảm ơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Then you could show them the loading dock operations in the afternoon.\", \"vi\": \"Vậy thì vào buổi chiều, quý vị có thể cho họ xem các hoạt động tại bến bốc dỡ hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '7c7621f9-4476-4dbb-925e-0f6ef6b9d47f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Marta Prigarina <mprigarina@ymw.co.za>\", \"vi\": \"Gửi tới: Marta Prigarina <mprigarina@ymw.co.za>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Barry Winters <bwinters@kerwinecs.co.za>\", \"vi\": \"Từ: Barry Winters <bwinters@kerwinecs.co.za>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 23 October\", \"vi\": \"Ngày: 23 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Office cleaning\", \"vi\": \"Chủ đề: Vệ sinh văn phòng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Prigarina,\", \"vi\": \"Kính gửi bà Prigarina,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We are glad you have chosen Kerwine Cleaning Services for your office cleaning needs.\", \"vi\": \"Chúng tôi rất vui mừng vì quý khách đã lựa chọn Dịch vụ Vệ sinh Kerwine để đáp ứng nhu cầu vệ sinh văn phòng của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our janitors will arrive at your facility with the commercial-grade equipment, tools, and products needed to complete all cleaning tasks quickly and effectively.\", \"vi\": \"Đội ngũ nhân viên vệ sinh của chúng tôi sẽ có mặt tại cơ sở của quý vị cùng với các thiết bị, dụng cụ và sản phẩm chuyên dụng dành cho môi trường thương mại, cần thiết để hoàn thành tất cả các công việc vệ sinh một cách nhanh chóng và hiệu quả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You have already confirmed a starting date of 30 October.\", \"vi\": \"Quý vị đã xác nhận ngày bắt đầu là ngày 30 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"However, you have not yet confirmed whether you will use our services weekly or biweekly.\", \"vi\": \"Tuy nhiên, quý vị vẫn chưa xác nhận liệu quý vị sẽ sử dụng dịch vụ của chúng tôi hàng tuần hay hai tuần một lần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"As soon as you let us know, we will draw up a contract for you.\", \"vi\": \"Ngay khi quý vị thông báo cho chúng tôi, chúng tôi sẽ soạn thảo hợp đồng cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Please note that we are currently running a special promotion.\", \"vi\": \"Xin lưu ý rằng hiện tại chúng tôi đang triển khai một chương trình khuyến mãi đặc biệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"If you sign up for six months of service by 31 October, your first two cleanings are free.\", \"vi\": \"Nếu quý vị đăng ký gói dịch vụ sáu tháng trước ngày 31 tháng 10, hai lần vệ sinh đầu tiên sẽ được miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Barry Winters\", \"vi\": \"Barry Winters\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Kerwine Cleaning Services\", \"vi\": \"Dịch vụ Vệ sinh Kerwine\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '7cc054c3-dedf-43b4-ace1-92147778ab48';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mapleshades Medical Center authorizes certain employees to purchase goods and services for\", \"vi\": \"Trung tâm Y tế Mapleshades ủy quyền cho một số nhân viên nhất định mua sắm hàng hóa và dịch vụ cho\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"company-related business.\", \"vi\": \"công việc liên quan đến công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To purchase a______[135] item or service, fill out the online request form.\", \"vi\": \"Để mua một mặt hàng hoặc dịch vụ ______[135], hãy điền vào mẫu yêu cầu trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"Use the form to ______[136] a description of the item needed.\", \"vi\": \"Sử dụng mẫu này để ______[136] mô tả về mặt hàng cần mua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"Also, briefly explain why the purchase is necessary.\", \"vi\": \"Ngoài ra, hãy giải thích ngắn gọn lý do tại sao việc mua sắm này là cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Note that your ______[137] may affect subsequent decisions.\", \"vi\": \"Xin lưu ý rằng ______[137] của bạn có thể ảnh hưởng đến các quyết định tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [137]}, {\"en\": \".\", \"vi\": \".\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If the request entails replacing a device that is out of order, bring the matter to the attention of Mr. Rowen, head of the Maintenance Division, before submitting the request ______[138] ..\", \"vi\": \"Nếu yêu cầu liên quan đến việc thay thế một thiết bị bị hỏng, hãy báo cáo vấn đề cho ông Rowen, trưởng Bộ phận Bảo trì, trước khi gửi yêu cầu ______[138] ..\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [138]}, {\"en\": \"Please direct any questions you may have related to the purchase of office supplies and equipment to the Purchasing Department.\", \"vi\": \"Vui lòng chuyển mọi thắc mắc của bạn liên quan đến việc mua sắm văn phòng phẩm và thiết bị đến Phòng Mua hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '7cd90159-b690-4096-89de-0bbf1e3e7bb6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Milford Janitorial Service\", \"vi\": \"Dịch vụ vệ sinh Milford\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.milfordjanitorialservice.com\", \"vi\": \"http://www.milfordjanitorialservice.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"956 Meadowvale Road, Milford, Connecticut 06460\", \"vi\": \"956 Đường Meadowvale, Milford, Connecticut 06460\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Let Milford Janitorial Service (MJS) help you showcase your workplace in its best light.\", \"vi\": \"Hãy để Milford Janitorial Service (MJS) giúp quý vị làm nổi bật nơi làm việc của mình một cách ấn tượng nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Using top-rated cleaning products, MJS serves large and small businesses based on their specific needs and schedule.\", \"vi\": \"Sử dụng các sản phẩm vệ sinh được đánh giá cao nhất, MJS cung cấp dịch vụ cho các doanh nghiệp lớn và nhỏ dựa trên nhu cầu cụ thể và lịch trình của từng đơn vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our professionally certified staff delivers quality, stress-free cleaning services seven days a week.\", \"vi\": \"Đội ngũ nhân viên được chứng nhận chuyên nghiệp của chúng tôi cung cấp các dịch vụ vệ sinh chất lượng cao, giúp quý khách hoàn toàn yên tâm, hoạt động bảy ngày một tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Interested?\", \"vi\": \"Quý vị có quan tâm không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Here is the process.\", \"vi\": \"Dưới đây là quy trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Contact MJS with your request, describing how we can best serve you.\", \"vi\": \"Vui lòng liên hệ với MJS và nêu rõ yêu cầu của quý vị, đồng thời mô tả cách thức để chúng tôi có thể phục vụ quý vị một cách tốt nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We will visit your place of business for a free consultation.\", \"vi\": \"Chúng tôi sẽ đến thăm cơ sở kinh doanh của quý vị để tư vấn miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We contact you with recommendations and a cost estimate within 72 hours.\", \"vi\": \"Chúng tôi sẽ liên hệ với quý vị để đưa ra các đề xuất và báo giá trong vòng 72 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You review our estimate and if satisfied, you sign our contract.\", \"vi\": \"Quý vị vui lòng xem xét bản dự toán của chúng tôi và nếu cảm thấy hài lòng, xin vui lòng ký vào hợp đồng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Location - Details - Team\", \"vi\": \"Địa điểm - Thông tin chi tiết - Đội ngũ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Hallender Office Supply - Dusting and vacuuming - Silver Team\", \"vi\": \"Hallender Office Supply - Lau bụi và hút bụi - Đội Silver\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Shoreside Bank - Window cleaning - Blue Team*\", \"vi\": \"Ngân hàng Shoreside - Dịch vụ lau kính - Đội Xanh*\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Larimar Café - Restroom cleaning - Green Team\", \"vi\": \"Quán cà phê Larimar - Vệ sinh nhà vệ sinh - Nhóm Xanh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Powder\'s Laundromat - Floor cleaning and polishing - Gold Team*\", \"vi\": \"Powder\'s Laundromat - Dịch vụ lau chùi và đánh bóng sàn - Đội Gold*\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"J. Mallery Accounting - Dusting and vacuuming - Silver Team\", \"vi\": \"Công ty Kế toán J. Mallery - Lau bụi và hút bụi - Đội Silver\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Milford Janitorial Service (MJS)\", \"vi\": \"Dịch vụ Vệ sinh Milford (MJS)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Assignment schedule for the evening of Monday, June 10\", \"vi\": \"Lịch phân công công việc cho buổi tối Thứ Hai, ngày 10 tháng 6\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"*Note that beginning next month, the Blue Team and the Gold Team will switch cleaning roles.\", \"vi\": \"*Xin lưu ý rằng bắt đầu từ tháng tới, Đội Xanh và Đội Vàng sẽ hoán đổi nhiệm vụ dọn dẹp cho nhau.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Irene\'s Formal Wear • 1800 Canopy Lane • Milford, Connecticut 06461\", \"vi\": \"Irene\'s Formal Wear • 1800 Canopy Lane • Milford, Connecticut 06461\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"June 17\", \"vi\": \"Ngày 17 tháng 6\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Milford Janitorial Service\", \"vi\": \"Dịch vụ vệ sinh Milford\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"956 Meadowvale Road\", \"vi\": \"956 Đường Meadowvale\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Milford, Connecticut 06460\", \"vi\": \"Milford, Connecticut 06460\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Xin chào,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Your company was referred to me by a customer of mine.\", \"vi\": \"Công ty của quý vị đã được một khách hàng của tôi giới thiệu cho tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I have a specific need, requiring professional floor cleaning and polishing in the large lobby of my business.\", \"vi\": \"Tôi có một nhu cầu cụ thể, đó là cần dịch vụ làm sạch và đánh bóng sàn chuyên nghiệp tại sảnh lớn của công ty tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"It is important that the lobby is always sparkling.\", \"vi\": \"Điều quan trọng là sảnh phải luôn sáng bóng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I would like this service provided weekly, beginning on July 1.\", \"vi\": \"Tôi mong muốn dịch vụ này được cung cấp hàng tuần, bắt đầu từ ngày 1 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Looking forward to hearing from you soon.\", \"vi\": \"Rất mong sớm nhận được phản hồi từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Irene Nogueira\", \"vi\": \"Irene Nogueira\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Irene Nogueira\", \"vi\": \"Irene Nogueira\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Irene\'s Formal Wear\", \"vi\": \"Thời trang dạ hội của Irene\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}]' WHERE `id` = '7cff4978-74a1-4aba-a5d5-6d245b199944';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Trust Gernack Home with Your Next Remodeling Project!\", \"vi\": \"Hãy tin tưởng Gernack Home trong dự án cải tạo tiếp theo của quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Gernack Home has proudly provided customized home-renovation solutions in the Nashville area for 30 years.\", \"vi\": \"Trong suốt 30 năm qua, Gernack Home luôn tự hào cung cấp các giải pháp cải tạo nhà ở theo yêu cầu tại khu vực Nashville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We work with clients on projects of all kinds, no matter how large or small.\", \"vi\": \"Chúng tôi hợp tác với quý khách hàng trong các dự án thuộc mọi lĩnh vực, bất kể quy mô lớn hay nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Our specialties are renovating kitchens and bathrooms, converting basements and garages into recreation rooms or home offices, and building home additions.\", \"vi\": \"Chúng tôi chuyên về cải tạo nhà bếp và phòng tắm, chuyển đổi tầng hầm và nhà để xe thành phòng giải trí hoặc văn phòng tại nhà, cũng như xây dựng các phần mở rộng cho ngôi nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We can assure you that Gernack Home installs only products of the highest quality.\", \"vi\": \"Chúng tôi xin cam đoan với quý vị rằng Gernack Home chỉ lắp đặt những sản phẩm có chất lượng cao nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"You will surely join our list of satisfied customers once you see the work done by our team of expert installers.\", \"vi\": \"Chắc chắn quý vị sẽ gia nhập danh sách những khách hàng hài lòng của chúng tôi ngay khi được chiêm ngưỡng thành quả công việc do đội ngũ thợ lắp đặt chuyên nghiệp của chúng tôi thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Call (615) 555-0118 to schedule a visit for a free consultation.\", \"vi\": \"Vui lòng gọi số (615) 555-0118 để đặt lịch hẹn tham vấn miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Or visit the showroom on our Web site at www.gernackhome.com.\", \"vi\": \"Hoặc quý vị có thể ghé thăm phòng trưng bày trên trang web của chúng tôi tại địa chỉ www.gernackhome.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"While there, take advantage of our latest feature: a virtual home renovation assistant.\", \"vi\": \"Khi truy cập trang web, xin hãy tận dụng tính năng mới nhất của chúng tôi: trợ lý cải tạo nhà ảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Our online assistants can help you build a virtual room so that you can take a first look at the renovation of your dreams.\", \"vi\": \"Các trợ lý trực tuyến của chúng tôi có thể hỗ trợ quý vị thiết kế một căn phòng ảo để quý vị có thể có cái nhìn sơ bộ về dự án cải tạo trong mơ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '7d015c42-8729-4ce1-9225-1f63375cd194';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Greenfell Landscaping\", \"vi\": \"Greenfell Landscaping\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Make sure your company\'s natural features look their best.\", \"vi\": \"Hãy đảm bảo rằng các yếu tố thiên nhiên của công ty quý vị được thể hiện một cách đẹp nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"A tidy first impression is important.\", \"vi\": \"Một ấn tượng ban đầu gọn gàng là điều rất quan trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Greenfell Landscaping can help you keep your company\'s greenery green!\", \"vi\": \"Greenfell Landscaping có thể giúp quý vị duy trì màu xanh tươi tốt cho khuôn viên công ty!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We have multiple tiers of service designed especially for our commercial clients.\", \"vi\": \"Chúng tôi có nhiều gói dịch vụ được thiết kế riêng dành cho các khách hàng doanh nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"– Eco Keeper Standard: weekly lawn mowing with detailed grass trimming by walkways and buildings\", \"vi\": \"– Gói dịch vụ Eco Keeper Standard: cắt cỏ hàng tuần, kèm theo việc tỉa cỏ tỉ mỉ dọc theo lối đi và xung quanh các tòa nhà\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"– Eco Keeper Plus: weekly mowing and trimming, organic fertilizer application, and weed removal.\", \"vi\": \"– Eco Keeper Plus: cắt cỏ và tỉa cành hàng tuần, bón phân hữu cơ và nhổ cỏ dại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Our most popular service.\", \"vi\": \"Dịch vụ được ưa chuộng nhất của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"– Master Green Gold: all the lawn-care services of our Eco Keeper Plus plan with the added benefit of seasonal flower plantings and flower bed maintenance\", \"vi\": \"– Gói Master Green Gold: bao gồm tất cả các dịch vụ chăm sóc thảm cỏ trong gói Eco Keeper Plus của chúng tôi, kèm theo lợi ích bổ sung là dịch vụ trồng hoa theo mùa và bảo dưỡng bồn hoa\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"– Master Green Platinum: all the services of our Master Green Gold plan but with care for your small trees and shrubs included.\", \"vi\": \"– Gói Master Green Platinum: bao gồm tất cả các dịch vụ của gói Master Green Gold, đồng thời có thêm dịch vụ chăm sóc cây nhỏ và cây bụi của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Twice-yearly pruning and trimming.\", \"vi\": \"Cắt tỉa hai lần mỗi năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Insect control.\", \"vi\": \"Kiểm soát côn trùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We can even bring ornamental potted trees to brighten your entryways.\", \"vi\": \"Chúng tôi thậm chí còn có thể mang đến những chậu cây cảnh để làm bừng sáng khu vực lối vào của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Contact service@greenfell.com to request an estimate.\", \"vi\": \"Vui lòng liên hệ với service@greenfell.com để yêu cầu báo giá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Costs are based on plan, lawn size, and type of plantings.\", \"vi\": \"Chi phí phụ thuộc vào phương án thiết kế, diện tích bãi cỏ và loại cây trồng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"🌿\", \"vi\": \"🌿\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"From: Daphne Mizuno <d.mizuno@pamaturn.com>\", \"vi\": \"Từ: Daphne Mizuno <d.mizuno@pamaturn.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"To: Greenfell Landscaping Service <service@greenfell.com>\", \"vi\": \"Gửi tới: Dịch vụ Thiết kế Cảnh quan Greenfell <service@greenfell.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Date: June 10\", \"vi\": \"Ngày: 10 tháng 6\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Subject: Inquiry\", \"vi\": \"Chủ đề: Yêu cầu thông tin\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Xin chào\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"My company has recently decided to outsource the lawn care at both our work sites, and I have been asked to solicit bids for a contract to do the work.\", \"vi\": \"Công ty tôi vừa quyết định thuê bên ngoài thực hiện công tác chăm sóc thảm cỏ tại cả hai cơ sở làm việc, và tôi đã được giao nhiệm vụ mời thầu để ký kết hợp đồng thực hiện công việc này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I saw your Greenfell Landscaping flyer and wanted to reach out to you, as we would prefer to work with a locally owned company rather than a large franchise.\", \"vi\": \"Tôi đã xem tờ rơi của công ty Greenfell Landscaping và muốn liên hệ với quý công ty, bởi chúng tôi mong muốn hợp tác với một công ty do người địa phương làm chủ hơn là một chuỗi nhượng quyền quy mô lớn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"We have two properties with large lawns.\", \"vi\": \"Chúng tôi có hai căn nhà với những bãi cỏ rộng lớn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Our main offices are on Langley Boulevard, near the Crossroads Shopping Plaza, and our shipping warehouse is five kilometers from the main offices, on Kempton Road.\", \"vi\": \"Trụ sở chính của chúng tôi tọa lạc trên đại lộ Langley, gần Trung tâm thương mại Crossroads, còn kho hàng của chúng tôi nằm cách trụ sở chính năm kilômét, trên đường Kempton.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Our needs are fairly simple.\", \"vi\": \"Những nhu cầu của chúng tôi khá đơn giản.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"We only require that the grass be kept short for a low but fair cost.\", \"vi\": \"Chúng tôi chỉ yêu cầu quý vị duy trì cỏ ở độ cao ngắn với một mức chi phí thấp nhưng hợp lý.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"We do not have any flower gardens or hedges, so the mowing is very straightforward.\", \"vi\": \"Chúng tôi không có vườn hoa hay hàng rào cây bụi nào, nên việc cắt cỏ rất đơn giản.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"If you are interested in submitting a bid, please let me know.\", \"vi\": \"Nếu quý vị quan tâm đến việc nộp hồ sơ dự thầu, xin vui lòng thông báo cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Daphne Mizuno, Facilities Manager\", \"vi\": \"Bà Daphne Mizuno, Quản lý Cơ sở vật chất\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Pamaturn Products, LLC\", \"vi\": \"Công ty TNHH Pamaturn Products\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"From: Greenfell Landscaping Service <service@greenfell.com>\", \"vi\": \"Từ: Dịch vụ Thiết kế Cảnh quan Greenfell <service@greenfell.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"To: Daphne Mizuno <d.mizuno@pamaturn.com>\", \"vi\": \"Gửi tới: Daphne Mizuno <d.mizuno@pamaturn.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Date: June 11\", \"vi\": \"Ngày: 11 tháng 6\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Subject: RE: Inquiry\", \"vi\": \"Chủ đề: RE: Yêu cầu thông tin\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Reference\", \"vi\": \"Tài liệu đính kèm: 📎 Tài liệu tham khảo\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Dear Ms. Mizuno,\", \"vi\": \"Kính gửi bà Mizuno,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Thank you for contacting Greenfell Landscaping about this opportunity.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã liên hệ với Greenfell Landscaping về cơ hội này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"We would like to bid on this work.\", \"vi\": \"Chúng tôi mong muốn được tham gia đấu thầu công trình này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Please forward the specifications, and I will begin working up the bid.\", \"vi\": \"Kính mong quý vị vui lòng chuyển tiếp bản thông số kỹ thuật, và tôi sẽ bắt đầu lập hồ sơ dự thầu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"If you need references as part of your process, you can contact Mr. Fred Stolz, the owner of Dynamo Machine Shop, which is located just down the street from your warehouse.\", \"vi\": \"Nếu quý vị cần các tài liệu tham khảo trong quá trình làm việc, quý vị có thể liên hệ với ông Fred Stolz, chủ sở hữu của xưởng cơ khí Dynamo Machine Shop, nằm ngay gần kho hàng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Fred has been a Greenfell Landscaping customer for over eight years.\", \"vi\": \"Ông Fred đã là khách hàng của Greenfell Landscaping trong hơn tám năm qua.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"His details are attached.\", \"vi\": \"Thông tin chi tiết về ông ấy được đính kèm dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"Greenfell Landscaping is fully licensed and insured.\", \"vi\": \"Công ty Greenfell Landscaping đã được cấp giấy phép đầy đủ và có bảo hiểm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"You can count on us to provide excellent, reliable service.\", \"vi\": \"Quý vị có thể hoàn toàn tin tưởng rằng chúng tôi sẽ cung cấp dịch vụ xuất sắc và đáng tin cậy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 46, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 47, \"question_numbers\": []}, {\"en\": \"Brian Karpyak, Owner\", \"vi\": \"Brian Karpyak, Chủ sở hữu\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 48, \"question_numbers\": []}, {\"en\": \"Greenfell Landscaping\", \"vi\": \"Greenfell Landscaping\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 49, \"question_numbers\": []}]' WHERE `id` = '7d05ac24-bea0-490c-b48f-0d79e53e41d4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"LOWELL (March 3)—Just one year after opening, Viggo\'s Sweet Shop on Park Street has become the place to go for residents wishing to satisfy their sugary cravings.\", \"vi\": \"LOWELL (Ngày 3 tháng 3)—Chỉ đúng một năm sau khi khai trương, tiệm bánh ngọt Viggo\'s Sweet Shop trên đường Park Street đã trở thành điểm đến quen thuộc của cư dân muốn thỏa mãn cơn thèm đồ ngọt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Says owner Viggo Magnusson, \\\"\\\"Returning customers bring friends and relatives with them, so the shop is always ______[139].\\\"\\\" Mr. Magnusson credits the success of his business to the recipes he inherited from his grandmother about a decade ago.\", \"vi\": \"Chủ tiệm, ông Viggo Magnusson, cho biết: \\\"Những khách hàng quen quay lại thường dẫn theo bạn bè và người thân, vì vậy cửa hàng luôn ______[139].\\\" Ông Magnusson cho rằng sự thành công của doanh nghiệp là nhờ vào các công thức nấu ăn mà ông thừa kế từ người bà của mình khoảng một thập kỷ trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [139]}, {\"en\": \"______[140].\", \"vi\": \"______[140].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [140]}, {\"en\": \"But the popularity of the pastry shop ______[141] Mr. Magnusson with an unanticipated problem: lack of store space.\", \"vi\": \"Nhưng sự nổi tiếng của cửa hàng bánh ______[141] ông Magnusson một vấn đề không lường trước được: thiếu không gian cửa hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [141]}, {\"en\": \"So when the shoe store next door went out of business recently, he purchased the property to allow for the ______[142] of his shop.\", \"vi\": \"Vì vậy, khi cửa hàng giày bên cạnh ngừng kinh doanh gần đây, ông đã mua lại bất động sản này để cho phép việc ______[142] của cửa hàng mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [142]}, {\"en\": \"Renovations will start in April.\", \"vi\": \"Công việc cải tạo sẽ bắt đầu vào tháng Tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '7d0f2c2d-ea20-44f9-a754-8e86e19196ce';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"💻 👤                                    — ☐ ✕\", \"vi\": \"💻 👤                                    — ☐ ✕\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"▼   ▷\", \"vi\": \"▼   ▷\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}]' WHERE `id` = '7d14ce3e-7cb7-4098-b458-f9ff16c7050b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Thanda Peterson <thandapeterson@thandapeterson.com>\", \"vi\": \"Gửi tới: Thanda Peterson <thandapeterson@thandapeterson.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Milos Adamek <milosa@wistartravel.org>\", \"vi\": \"Từ: Milos Adamek <milosa@wistartravel.org>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Travel arrangements\", \"vi\": \"Chủ đề: Các thủ tục đi lại\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: April 17\", \"vi\": \"Ngày: 17 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hello Thanda,\", \"vi\": \"Xin chào Thanda,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I hope you are well.\", \"vi\": \"Tôi hy vọng quý vị vẫn khỏe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I looked into available flights from Concord to Sumneyfeld for your writers\' conference and discovered that discount carrier Alterr Airlines offers daily direct service on that route.\", \"vi\": \"Tôi đã tìm hiểu về các chuyến bay hiện có từ Concord đến Sumneyfeld để phục vụ hội nghị các nhà văn của quý vị và phát hiện ra rằng hãng hàng không giá rẻ Alterr Airlines cung cấp dịch vụ bay thẳng hàng ngày trên tuyến đường này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The tentative itinerary would be:\", \"vi\": \"Lịch trình dự kiến sẽ như sau:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Concord depart: Friday, May 8, 8:50 A.M.\", \"vi\": \"Khởi hành từ Concord: Thứ Sáu, ngày 8 tháng 5, lúc 8 giờ 50 sáng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Sumneyfeld arrive: Friday, May 8, 11:05 A.M.\", \"vi\": \"Sumneyfeld đến vào lúc: 11 giờ 05 phút sáng Thứ Sáu, ngày 8 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Sumneyfeld depart: Monday, May 11, 1:20 P.M.\", \"vi\": \"Thời gian khởi hành từ Sumneyfeld: Thứ Hai, ngày 11 tháng 5, lúc 1 giờ 20 phút chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Concord arrive: Monday, May 11, 3:35 P.M.\", \"vi\": \"Tàu Concord đến vào lúc: 15 giờ 35 phút, Thứ Hai, ngày 11 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I will book this as soon as you confirm.\", \"vi\": \"Tôi sẽ tiến hành đặt chỗ ngay sau khi quý vị xác nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Keep in mind on your return trip that the Sumneyfeld Airport is advising passengers to arrive a full two hours before departure because of extensive renovations being done there.\", \"vi\": \"Trong chuyến bay trở về, xin quý vị lưu ý rằng Sân bay Sumneyfeld khuyến cáo hành khách nên có mặt tại sân bay trước giờ khởi hành ít nhất hai giờ do hiện đang tiến hành các công trình cải tạo quy mô lớn tại đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"By the way, you might be interested in an excellent Peruvian lunch place near the Sumneyfeld Airport.\", \"vi\": \"Nhân tiện, có lẽ quý vị sẽ quan tâm đến một quán ăn trưa Peru rất ngon gần Sân bay Sumneyfeld.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Just let me know and I will give you the name.\", \"vi\": \"Chỉ cần quý vị cho tôi biết, tôi sẽ cung cấp tên cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Milos\", \"vi\": \"Milos\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To: Milos Adamek <milosa@wistartravel.org>\", \"vi\": \"Gửi tới: Milos Adamek <milosa@wistartravel.org>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: Thanda Peterson <thandapeterson@thandapeterson.com>\", \"vi\": \"Từ: Thanda Peterson <thandapeterson@thandapeterson.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Subject: Re: Travel arrangements\", \"vi\": \"Chủ đề: Trả lời: Các thủ tục đi lại\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Date: April 18\", \"vi\": \"Ngày: 18 tháng 4\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Milos,\", \"vi\": \"Milos,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Quick update before you book.\", \"vi\": \"Một vài thông tin cập nhật nhanh trước khi quý vị đặt chỗ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I will need a few days to consider whether I should depart for Sumneyfeld on May 8 or leave one day earlier.\", \"vi\": \"Tôi sẽ cần vài ngày để cân nhắc xem liệu tôi nên khởi hành đến Sumneyfeld vào ngày 8 tháng 5 hay lên đường sớm hơn một ngày.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"There is an early conference workshop the evening of May 7 that I might attend.\", \"vi\": \"Vào tối ngày 7 tháng 5 có một buổi hội thảo diễn ra sớm trong khuôn khổ hội nghị mà tôi có thể sẽ tham dự.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Actually, a publisher representative with whom I would like to talk regarding my latest manuscript may be in attendance!\", \"vi\": \"Thực ra, có thể sẽ có mặt tại đây một đại diện của nhà xuất bản mà tôi rất mong được trao đổi về bản thảo mới nhất của mình!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I will let you know shortly.\", \"vi\": \"Tôi sẽ thông báo cho quý vị trong thời gian sớm nhất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Thanks so much for your help, as always.\", \"vi\": \"Xin chân thành cảm ơn sự giúp đỡ của quý vị, như mọi khi.\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Thanda\", \"vi\": \"Tình yêu\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Date: May 7\", \"vi\": \"Ngày: 7 tháng 5\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"From: Sumneyfeld Airport\", \"vi\": \"Từ: Sân bay Sumneyfeld\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"To: Peru Dreaming Café, 98 Treetop Avenue\", \"vi\": \"Gửi tới: Peru Dreaming Café, số 98 Đại lộ Treetop\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Pickup: 11:55 A.M.\", \"vi\": \"Thời gian đón: 11 giờ 55 phút sáng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Drop off: 12:04 P.M.\", \"vi\": \"Thời gian trả khách: 12 giờ 04 phút trưa.\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Distance: 1.2 miles\", \"vi\": \"Khoảng cách: 1,2 dặm\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Total: $8.00\", \"vi\": \"Tổng cộng: 8,00 đô la\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Payment type: ☑ credit card   ☐ cash\", \"vi\": \"Hình thức thanh toán: ☑ thẻ tín dụng   ☐ tiền mặt\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Name on Credit Card: Thanda Peterson\", \"vi\": \"Tên trên thẻ tín dụng: Thanda Peterson\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Credit Card Number: xxxx xxxx xxxx 5523\", \"vi\": \"Số thẻ tín dụng: xxxx xxxx xxxx 5523\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Sumneyfeld Quick Taxi\", \"vi\": \"Dịch vụ taxi nhanh Sumneyfeld\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"555–0194\", \"vi\": \"555–0194\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}]' WHERE `id` = '7d5c15d1-6af7-4fc0-bda5-e3343b538458';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"WELCOME TO RICHMOND SUPERMARKET!\", \"vi\": \"CHÀO MỪNG QUÝ KHÁCH ĐẾN VỚI SIÊU THỊ RICHMOND!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"DID YOU KNOW?\", \"vi\": \"QUÝ VỊ CÓ BIẾT KHÔNG?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Richmond Supermarket is now offering cooking classes in our own state-of-the-art kitchen, the same kitchen where we create flavourful soups, salads, and entrées for our prepared foods department.\", \"vi\": \"Siêu thị Richmond hiện đang tổ chức các lớp học nấu ăn tại chính nhà bếp hiện đại bậc nhất của chúng tôi – cũng chính là nơi chúng tôi chế biến các món súp, salad và món chính thơm ngon cho bộ phận thực phẩm chế biến sẵn của siêu thị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Every Monday evening from 7:00 P.M. to 8:30 P.M. we turn our kitchen over to a guest chef from one of Richmond\'s many fine restaurants.\", \"vi\": \"Vào mỗi tối thứ Hai, từ 7 giờ tối đến 8 giờ 30 tối, chúng tôi dành riêng nhà bếp của mình cho một đầu bếp khách mời đến từ một trong số rất nhiều nhà hàng cao cấp tại Richmond.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Participants learn to prepare a different dish each week.\", \"vi\": \"Các học viên sẽ học cách chế biến một món ăn khác nhau mỗi tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Learn new techniques you can bring home to delight your friends and family!\", \"vi\": \"Hãy học những kỹ thuật mới để áp dụng tại nhà, mang đến niềm vui cho bạn bè và gia đình của quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"All classes use ingredients you can find right here in the store.\", \"vi\": \"Tất cả các lớp học đều sử dụng các nguyên liệu mà quý vị có thể tìm thấy ngay tại cửa hàng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This month\'s classes are as follows:\", \"vi\": \"Các lớp học trong tháng này như sau:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"2 August Butter Chicken (India)\", \"vi\": \"Ngày 2 tháng 8: Gà sốt bơ (Ấn Độ)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"9 August Pad Thai (Thailand)\", \"vi\": \"Ngày 9 tháng 8: Món Pad Thai (Thái Lan)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"16 August Fish Tacos (Mexico)\", \"vi\": \"Ngày 16 tháng 8: Bánh taco cá (Mexico)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"23 August Roast Vegetable Lasagna (Italy)\", \"vi\": \"Ngày 23 tháng 8: Món Lasagna rau củ nướng (Ý)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The fee for each class is $55.00.\", \"vi\": \"Học phí cho mỗi lớp là 55,00 USD.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To register, please call us at 604-555-0175 or visit www.richmondsupermarket.ca.\", \"vi\": \"Để đăng ký, xin vui lòng gọi cho chúng tôi theo số 604-555-0175 hoặc truy cập trang web www.richmondsupermarket.ca.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"There is a limit of 15 students per class.\", \"vi\": \"Mỗi lớp có tối đa 15 học sinh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Classes sell out quickly, so reserve your spot today.\", \"vi\": \"Các lớp học thường hết chỗ rất nhanh, vì vậy xin quý vị hãy đăng ký ngay hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Online Shopping - Contact Us - Reviews - Cooking Classes\", \"vi\": \"Mua sắm trực tuyến - Liên hệ với chúng tôi - Đánh giá - Lớp học nấu ăn\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"https://www.richmondsupermarket.ca/reviews\", \"vi\": \"https://www.richmondsupermarket.ca/reviews\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thanks to Richmond Supermarket\'s new cooking classes, community members can take lessons from some of the best chefs in the area.\", \"vi\": \"Nhờ các lớp học nấu ăn mới của Siêu thị Richmond, các thành viên trong cộng đồng có cơ hội được học hỏi từ một số đầu bếp giỏi nhất trong khu vực.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Last week I learned how to prepare fish tacos with Mateo Bernal, head chef at Bernal\'s Restaurant.\", \"vi\": \"Tuần trước, tôi đã được học cách chế biến món tacos cá cùng ông Mateo Bernal, bếp trưởng tại Nhà hàng Bernal’s.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We made every component of the tacos from scratch, including the corn tortillas, grilled tilapia, and tomatillo salsa.\", \"vi\": \"Chúng tôi đã tự tay chế biến từng thành phần của món taco từ đầu, bao gồm cả bánh tortilla ngô, cá rô phi nướng và sốt tomatillo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Before leaving, each attendee received a small notebook containing the recipe we made that day as well as a few of Mr. Bernal\'s other favourite recipes.\", \"vi\": \"Trước khi ra về, mỗi người tham dự đã nhận được một cuốn sổ tay nhỏ ghi lại công thức món ăn mà chúng tôi đã thực hiện trong ngày hôm đó, cùng với một số công thức nấu ăn yêu thích khác của ông Bernal.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I\'m going to clear my Monday evenings so I can go back again and again!\", \"vi\": \"Tôi sẽ dành trống các buổi tối thứ Hai để có thể quay lại đó nhiều lần nữa!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"—Astrid Klein\", \"vi\": \"—Astrid Klein\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}]' WHERE `id` = '7dcbc8f8-4c36-459f-b360-a5a42a835c3d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Sales Team\", \"vi\": \"Gửi: Đội ngũ Bán hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Neil Cullen\", \"vi\": \"Từ: Neil Cullen\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 10 April\", \"vi\": \"Ngày: 10 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: My schedule next week\", \"vi\": \"Chủ đề: Lịch trình của tôi trong tuần tới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Team,\", \"vi\": \"Kính gửi toàn thể đội ngũ,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I will be out of the office next week, from 15 to 19 April, attending the conference of the National Technology Alliance in Glasgow.\", \"vi\": \"Tuần tới, từ ngày 15 đến ngày 19 tháng 4, tôi sẽ vắng mặt tại văn phòng để tham dự hội nghị của Liên minh Công nghệ Quốc gia tại Glasgow.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"While away, I will check e-mail and voice mail infrequently.\", \"vi\": \"Trong thời gian vắng mặt, tôi sẽ ít khi kiểm tra email và thư thoại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"For any urgent matters, please contact my assistant, Christina Choo.\", \"vi\": \"Đối với bất kỳ vấn đề khẩn cấp nào, xin vui lòng liên hệ với trợ lý của tôi, bà Christina Choo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"If you have a specific question about the Ezenx Industries account, please e-mail Mya Soroka.\", \"vi\": \"Nếu quý vị có thắc mắc cụ thể nào về tài khoản của Ezenx Industries, xin vui lòng gửi email cho bà Mya Soroka.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I will be back in the office on 22 April and will see all of you then.\", \"vi\": \"Tôi sẽ trở lại văn phòng vào ngày 22 tháng 4 và sẽ gặp lại tất cả quý vị vào lúc đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Neil Cullen, Director of Sales and Marketing\", \"vi\": \"Ông Neil Cullen, Giám đốc Kinh doanh và Tiếp thị\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Shallok Technology\", \"vi\": \"Công ty Công nghệ Shallok\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '7e00957a-f7d5-4efd-95ea-1ff49d70cbaf';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Signs Press Plus is the region\'s oldest and most trusted sign ___131____ .\", \"vi\": \"Signs Press Plus là công ty làm bảng hiệu lâu đời nhất và đáng tin cậy nhất trong khu vực ___131____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [131]}, {\"en\": \"Our company creates signs in many sizes and forms—banners, storefront signs, and even vehicle wraps.\", \"vi\": \"Công ty chúng tôi tạo ra các bảng hiệu với nhiều kích thước và hình thức khác nhau—băng rôn, biển hiệu cửa hàng và thậm chí cả decal dán xe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"____132___ .\", \"vi\": \"____132___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132]}, {\"en\": \"We use our ___133____ experience to design signs that allow our customers\' enterprises to stand out from the competition.\", \"vi\": \"Chúng tôi tận dụng bề dày kinh nghiệm ___133____ của mình để thiết kế những tấm biển giúp doanh nghiệp của khách hàng nổi bật trước đối thủ cạnh tranh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [133]}, {\"en\": \"We can help you get your business noticed!\", \"vi\": \"Chúng tôi có thể giúp doanh nghiệp của bạn được chú ý!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Call 575-555-0161 to ___134____ a consultation.\", \"vi\": \"Hãy gọi số 575-555-0161 để ___134____ một buổi tư vấn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [134]}]' WHERE `id` = '7e3ec6ac-adc8-4a2b-b288-15b0389f6ffd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Pearson Theater cordially invites you and one guest to the premiere of\", \"vi\": \"Nhà hát Pearson trân trọng kính mời quý vị cùng một vị khách tham dự buổi công chiếu vở\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"A Bright Line, the latest original play by Ella Neal.\", \"vi\": \"“A Bright Line”, vở kịch gốc mới nhất của Ella Neal.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Thursday, March 2, 7:00 p.m.\", \"vi\": \"Thứ Năm, ngày 2 tháng 3, 19 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Set in 1950s New York, A Bright Line tells the story of an art professor who inspires her students by sharing her unusual outlook on art and life.\", \"vi\": \"Lấy bối cảnh tại New York những năm 1950, bộ phim *A Bright Line* kể về câu chuyện của một giáo sư mỹ thuật, người đã truyền cảm hứng cho các sinh viên của mình bằng cách chia sẻ góc nhìn độc đáo của bà về nghệ thuật và cuộc sống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"As a Platinum-tier Pearson Theater supporter, you are also encouraged to stay for a post-show meet-and-greet with the cast and creative team.\", \"vi\": \"Với tư cách là nhà tài trợ cấp Bạch kim của Nhà hát Pearson, quý vị cũng được khuyến khích ở lại tham gia buổi gặp gỡ và giao lưu với dàn diễn viên cùng đội ngũ sáng tạo sau buổi diễn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Refreshments will be provided.\", \"vi\": \"Sẽ có đồ ăn nhẹ phục vụ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Please call 555-0148 to RSVP for both events by February 24.\", \"vi\": \"Kính mời quý vị gọi đến số 555-0148 để đăng ký tham dự cả hai sự kiện trước ngày 24 tháng 2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '7ecf74f4-0bfc-4d7a-979f-16a774f2bc70';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Accept Invitation - Ignore Invitation - Reply to Don\", \"vi\": \"Chấp nhận lời mời - Bỏ qua lời mời - Trả lời Don\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Unetcon – Message Center\", \"vi\": \"Unetcon – Trung tâm tin nhắn\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Pending Invitations\", \"vi\": \"Các lời mời đang chờ xử lý\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"From: Don Fitzpatrick\", \"vi\": \"Từ: Don Fitzpatrick\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Branch Manager, Wilsonville Financial\", \"vi\": \"Giám đốc Chi nhánh, Wilsonville Financial\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"To: Audrey Smith\", \"vi\": \"Kính gửi: Audrey Smith\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Audrey,\", \"vi\": \"Kính gửi Audrey,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please accept this invitation to connect professionally on Unetcon.\", \"vi\": \"Kính mời quý vị chấp nhận lời mời này để kết nối chuyên nghiệp trên Unetcon.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I am a fellow Stonerook University graduate and am always looking to expand my network.\", \"vi\": \"Tôi cũng là cựu sinh viên của Đại học Stonerook và luôn mong muốn mở rộng mạng lưới quan hệ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In this case, I am also reaching out to see if you would be interested in joining the private Stonerook alumni group page to stay current with everything that our fellow graduates are up to.\", \"vi\": \"Trong trường hợp này, tôi cũng xin liên hệ để hỏi xem quý vị có quan tâm đến việc tham gia trang nhóm riêng dành cho cựu sinh viên Stonerook hay không, nhằm cập nhật những thông tin mới nhất về hoạt động của các bạn cùng khóa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"https://www.unetcon.org/private/stonerookugrads.\", \"vi\": \"https://www.unetcon.org/private/stonerookugrads.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Don Fitzpatrick\", \"vi\": \"Don Fitzpatrick\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"https://www.unetcon.org/messages_audreysmith80\", \"vi\": \"https://www.unetcon.org/messages_audreysmith80\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Current\\n\\nDirector,\\nAlbright School of Business\\n\\nFounder and Director,\\nClear Path\\n\\nContact\\nPhone: 843-555-0139\\nE-mail: jhilliard@mccleese.edu\\nOffice: 403 Cordon Hall\\n   530 N Kensington St.\\n   Charleston, SC 29425 - Education\\n\\nMaster of Business Administration – Turnbull University\\n\\nBachelor of Arts in Education Studies – Stonerook University - Professional\\n\\nMr. Hilliard has led the Albright School of Business since 2017. Between 2007 and 2017, he carried out extensive research on emerging markets in West Africa while teaching business management in Lagos, Nigeria. Two years ago, he founded Clear Path, a business that advises students from around the globe who wish to pursue studies in the United States.\", \"vi\": \"Hiện tại\\n\\nGiám đốc,\\nTrường Kinh doanh Albright\\n\\nNgười sáng lập kiêm Giám đốc,\\nClear Path\\n\\nLiên hệ\\nĐiện thoại: 843-555-0139\\nEmail: jhilliard@mccleese.edu\\nVăn phòng: Phòng 403, Tòa nhà Cordon Hall\\n   530 N Kensington St.\\n   Charleston, SC 29425 - Học vấn\\n\\nThạc sĩ Quản trị Kinh doanh – Đại học Turnbull\\n\\nCử nhân Nghệ thuật chuyên ngành Nghiên cứu Giáo dục – Đại học Stonerook - Hoạt động nghề nghiệp\\n\\nÔng Hilliard đã lãnh đạo Trường Kinh doanh Albright kể từ năm 2017. Trong giai đoạn từ năm 2007 đến năm 2017, ông đã tiến hành nhiều nghiên cứu sâu rộng về các thị trường mới nổi ở Tây Phi đồng thời giảng dạy môn quản trị kinh doanh tại Lagos, Nigeria. Hai năm trước, ông đã thành lập Clear Path, một công ty tư vấn cho sinh viên từ khắp nơi trên thế giới có nguyện vọng theo học tại Hoa Kỳ.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Stonerook University Graduates\", \"vi\": \"Các tân cử nhân của Đại học Stonerook\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Check out the continued success and latest updates from Stonerook graduate Jonah Hilliard.\", \"vi\": \"Mời quý vị cùng theo dõi những thành công tiếp nối cũng như những thông tin cập nhật mới nhất về Jonah Hilliard, cựu học viên của Stonerook.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"https://www.unetcon.org/private/stonerookugrads\", \"vi\": \"https://www.unetcon.org/private/stonerookugrads\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"From: Audrey Smith <audrey_smith80@rapidonet.co.uk>\", \"vi\": \"Từ: Audrey Smith <audrey_smith80@rapidonet.co.uk>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"To: Jonah Hilliard <jhilliard@mccleese.edu>\", \"vi\": \"Gửi tới: Jonah Hilliard <jhilliard@mccleese.edu>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date: 19 September\", \"vi\": \"Ngày: 19 tháng 9\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subject: Referral\", \"vi\": \"Chủ đề: Giới thiệu\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Dear Jonah,\", \"vi\": \"Kính gửi Jonah,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"It has been a long time since we last talked.\", \"vi\": \"Đã lâu rồi kể từ lần cuối cùng chúng ta nói chuyện với nhau.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I recently came across your profile on Unetcon and saw that you are now leading the business school at McCleese!\", \"vi\": \"Gần đây, tôi tình cờ xem được hồ sơ của quý vị trên Unetcon và thấy rằng hiện nay quý vị đang đảm nhiệm vai trò lãnh đạo trường kinh doanh tại McCleese!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"My research in Lagos ended last year, when I accepted a position as lead consultant at Pryor and Martell.\", \"vi\": \"Công tác nghiên cứu của tôi tại Lagos đã kết thúc vào năm ngoái, khi tôi nhận lời đảm nhận vị trí chuyên gia tư vấn trưởng tại Pryor and Martell.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I have been based here in Manchester ever since.\", \"vi\": \"Từ đó đến nay, tôi vẫn sinh sống tại Manchester.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Congratulations to you on your most recent business venture—Clear Path already has quite an impressive reputation!\", \"vi\": \"Xin chúc mừng quý vị về dự án kinh doanh mới nhất của quý vị — Clear Path đã có được danh tiếng thực sự ấn tượng rồi!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I have a nephew who is interested in pursuing a degree in management information systems in the United States, and I was hoping I could put you both in touch so that he can take advantage of your new company\'s expertise in this area.\", \"vi\": \"Tôi có một cháu trai đang quan tâm đến việc theo học ngành Hệ thống thông tin quản lý tại Hoa Kỳ, và tôi hy vọng có thể giới thiệu hai bên với nhau để cháu ấy có thể tận dụng được chuyên môn của công ty mới của quý vị trong lĩnh vực này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Audrey Smith\", \"vi\": \"Audrey Smith\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}]' WHERE `id` = '7f13242d-d20c-4486-929b-39ca0ed24bed';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Personnel\", \"vi\": \"Đến: Toàn thể nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Harkfield Capital\", \"vi\": \"Từ: Harkfield Capital\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Half day\", \"vi\": \"Chủ đề: Nghỉ nửa ngày\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: November 10\", \"vi\": \"Ngày: 10 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"On Friday, November 19, beginning at 2:00 p.m., the parking garage will be power washed and the lines will be repainted.\", \"vi\": \"Vào thứ Sáu, ngày 19 tháng 11, bắt đầu từ 2:00 chiều, nhà xe sẽ được xịt rửa áp lực cao và các vạch kẻ đường sẽ được sơn lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Before the workers can ____143____ , the garage needs to be empty.\", \"vi\": \"Trước khi công nhân có thể ____143____ , nhà xe cần phải được để trống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [143]}, {\"en\": \"Therefore, all employees will receive a paid half day off from work.\", \"vi\": \"Do đó, tất cả nhân viên sẽ được nghỉ nửa ngày làm việc có lương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"____144____ .\", \"vi\": \"____144____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [144]}, {\"en\": \"Those who begin at 9:00 A.M. will finish at 1:00 P.M. No lunch hours will be taken.\", \"vi\": \"Những ai bắt đầu lúc 9:00 sáng sẽ kết thúc lúc 1:00 chiều. Sẽ không có giờ nghỉ ăn trưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Employees must ____145____ the garage immediately after completing their shifts.\", \"vi\": \"Nhân viên phải ____145____ nhà xe ngay sau khi hoàn thành ca làm việc của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [145]}, {\"en\": \"The garage will remain ____146____ all weekend.\", \"vi\": \"Nhà xe sẽ tiếp tục đóng cửa ____146____ trong suốt cuối tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [146]}, {\"en\": \"Employees who work on the weekend must park on the street or in a paid lot.\", \"vi\": \"Nhân viên làm việc vào cuối tuần phải đậu xe trên đường hoặc tại bãi đậu xe có thu phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We hope you will enjoy this extra time off.\", \"vi\": \"Chúng tôi hy vọng bạn sẽ tận hưởng khoảng thời gian nghỉ ngơi bổ sung này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '7f2c20cb-b31f-4cfc-a665-54936795f09c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.akikohirota.co.jp/english ▶\", \"vi\": \"https://www.akikohirota.co.jp/english ▶\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Born and raised in Chiba Prefecture, Akiko Hirota started writing short stories in English in high school.\", \"vi\": \"Sinh ra và lớn lên tại tỉnh Chiba, Akiko Hirota bắt đầu sáng tác truyện ngắn bằng tiếng Anh từ thời trung học.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"She continued writing short fiction while completing her degree in English literature at the Chiba Institute of Linguistics.\", \"vi\": \"Cô tiếp tục sáng tác truyện ngắn trong khi hoàn tất chương trình cử nhân văn học Anh tại Viện Ngôn ngữ học Chiba.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Two years ago Ms. Hirota won the \\\"Best Short Story\\\" prize at the 5th Annual New York Writers Gala for her short story entitled, Dreaming of Maringá.\", \"vi\": \"Hai năm trước, bà Hirota đã giành giải “Truyện ngắn hay nhất” tại Lễ trao giải thường niên lần thứ 5 dành cho các nhà văn New York nhờ tác phẩm truyện ngắn mang tên *Dreaming of Maringá*.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"She has participated in over 30 writers\' workshops, a number of which she has led, and has been a regular guest speaker at the Writers United Forum.\", \"vi\": \"Bà đã tham gia hơn 30 hội thảo dành cho các nhà văn, trong đó có một số hội thảo do chính bà chủ trì, đồng thời thường xuyên là diễn giả khách mời tại Diễn đàn Writers United.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"A collection of her short stories written thus far, including Dreaming of Maringá, has been published by Jenson Publishing.\", \"vi\": \"Một tuyển tập các truyện ngắn của bà được sáng tác cho đến nay, trong đó có tác phẩm “Dreaming of Maringá”, đã được Nhà xuất bản Jenson phát hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Lives Ensnared, Ms. Hirota\'s first full-length novel, is inspired by her upbringing as the daughter of two marine biologists.\", \"vi\": \"“Lives Ensnared”, tiểu thuyết dài đầu tay của bà Hirota, lấy cảm hứng từ quãng thời gian trưởng thành của bà với tư cách là con gái của hai nhà sinh vật học biển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It tells the story of a group of amateur divers whose lives were turned upside down following their discovery of a hitherto unknown species of shark.\", \"vi\": \"Bộ phim kể về câu chuyện của một nhóm thợ lặn nghiệp dư, cuộc sống của họ đã bị đảo lộn hoàn toàn sau khi phát hiện ra một loài cá mập chưa từng được biết đến trước đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Scheduled for release by mid-September, the novel is sure to appeal to a wide audience.\", \"vi\": \"Dự kiến ra mắt vào giữa tháng 9, cuốn tiểu thuyết này chắc chắn sẽ thu hút được đông đảo độc giả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Biography\", \"vi\": \"Tiểu sử\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Books\", \"vi\": \"Sách\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Blog\", \"vi\": \"Blog\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Events\", \"vi\": \"Các sự kiện\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"https://www.zantreebooks.com ▶\", \"vi\": \"https://www.zantreebooks.com ▶\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"\\\"From the depths of the ocean comes a novel of mystery and suspense!\\\"\", \"vi\": \"\\\"Từ đáy đại dương, một cuốn tiểu thuyết trinh thám và hồi hộp đã ra đời!\\\"\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"—Diayu Ling, Sun National Times\", \"vi\": \"—Diayu Ling, Báo Sun National Times\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Altered Existence is the first novel by Japanese author Akiko Hirota.\", \"vi\": \"“Altered Existence” là tiểu thuyết đầu tay của tác giả người Nhật Bản Akiko Hirota.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"When Hiroko Jitsukawa and her friends learned that they had discovered a new shark species, they were quite excited, fully expecting fame and fortune.\", \"vi\": \"Khi Hiroko Jitsukawa và các bạn của cô biết rằng họ đã phát hiện ra một loài cá mập mới, họ vô cùng phấn khích và hoàn toàn kỳ vọng sẽ đạt được danh tiếng và sự giàu có.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"What they got instead was a sea of trouble that would completely upend their lives.\", \"vi\": \"Thay vào đó, họ lại phải đối mặt với một biển rắc rối, thứ sẽ làm đảo lộn hoàn toàn cuộc sống của họ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Release date: September 15\", \"vi\": \"Ngày phát hành: 15 tháng 9\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"$25.95.\", \"vi\": \"25,95 đô la.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"287 pages, hardcover\", \"vi\": \"287 trang, bìa cứng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Pre-order this title or purchase any other of Zantree Books offerings at www.zantreebooks.com\", \"vi\": \"Quý vị có thể đặt mua trước cuốn sách này hoặc mua bất kỳ đầu sách nào khác của Zantree Books tại www.zantreebooks.com\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '7f677241-7092-4530-b350-c4c293cd8567';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Dorota Kucharski <dkucharski@internationaltechnologicalsociety.org>\", \"vi\": \"Gửi tới: Dorota Kucharski <dkucharski@internationaltechnologicalsociety.org>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Luciano Moretti <lmoretti@internationaltechnologicalsociety.org>\", \"vi\": \"Từ: Luciano Moretti <lmoretti@internationaltechnologicalsociety.org>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 8 August\", \"vi\": \"Ngày: 8 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Research results\", \"vi\": \"Chủ đề: Kết quả nghiên cứu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Ms. Kucharski,\", \"vi\": \"Bà Kucharski,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The following is a summary of what I have learned in my research about where to hold our next annual technology conference in June of next year.\", \"vi\": \"Dưới đây là bản tóm tắt những điều tôi đã tìm hiểu được trong quá trình nghiên cứu về địa điểm tổ chức hội nghị công nghệ thường niên tiếp theo của chúng ta vào tháng 6 năm sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In Rome, the best option I have found is Hotel al Ponte.\", \"vi\": \"Tại Rome, lựa chọn tốt nhất mà tôi đã tìm được là Khách sạn al Ponte.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The total cost for conference events there would be €31,500.\", \"vi\": \"Tổng chi phí cho các hoạt động hội nghị tại đó sẽ là 31.500 euro.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [1] — Individual hotel rooms would cost €80 per night for participants.\", \"vi\": \"— [1] — Giá phòng khách sạn riêng dành cho các đại biểu là 80 € mỗi đêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In the event that attendance is high, we could also house participants in the nearby Hotel Milvio at €120 per night.\", \"vi\": \"Trong trường hợp số lượng người tham dự đông, chúng tôi cũng có thể sắp xếp chỗ ở cho các đại biểu tại Khách sạn Milvio gần đó với mức giá 120 € mỗi đêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I also looked into hotels in Genoa and Florence, but I could not find any that would be much cheaper in overall conference costs.\", \"vi\": \"Tôi cũng đã tìm hiểu về các khách sạn ở Genoa và Florence, nhưng không tìm thấy nơi nào có thể giúp giảm đáng kể tổng chi phí tham dự hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"More importantly, I am concerned that the greater cost of flights to those smaller cities could discourage some attendees.\", \"vi\": \"Quan trọng hơn, tôi lo ngại rằng chi phí vé máy bay cao hơn khi bay đến các thành phố nhỏ hơn này có thể khiến một số người tham dự nản lòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Rome, on the other hand, has affordable direct flights from most European cities.\", \"vi\": \"Ngược lại, Rome có các chuyến bay thẳng với giá cả phải chăng từ hầu hết các thành phố châu Âu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"It will also be more affordable for our colleagues coming from Buenos Aires.\", \"vi\": \"Điều này cũng sẽ giúp chi phí trở nên hợp lý hơn đối với các đồng nghiệp của chúng ta đến từ Buenos Aires.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"If you would like to pursue the Hotel al Ponte option, I will provide a detailed write-up of the anticipated costs and of the amenities offered by the hotel.\", \"vi\": \"Nếu quý vị muốn xem xét phương án lựa chọn Khách sạn al Ponte, tôi sẽ cung cấp một bản tóm tắt chi tiết về các chi phí dự kiến cũng như các tiện nghi mà khách sạn này cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Luciano Moretti\", \"vi\": \"Luciano Moretti\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Secretary, International Technological Society\", \"vi\": \"Thư ký, Hiệp hội Công nghệ Quốc tế\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '7f6d75b5-387f-4bff-a72d-8b7f629a6e40';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.firststreetcinema.com/classic_film\", \"vi\": \"https://www.firststreetcinema.com/classic_film\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Season Program - News - Tickets - Contact\", \"vi\": \"Chương trình mùa diễn - Tin tức - Vé - Liên hệ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Classic Film Festival\", \"vi\": \"Liên hoan Phim Cổ điển\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The new First Street Cinema is celebrating its opening in June by welcoming filmgoers with these free screenings for fans of classic films.\", \"vi\": \"Rạp chiếu phim First Street Cinema mới đang tổ chức lễ khai trương vào tháng 6 bằng cách chào đón khán giả với các buổi chiếu phim miễn phí dành cho những người yêu thích phim kinh điển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The films will start at 7:00 P.M. Seating is limited, and guests are asked to reserve tickets on our Web site, as tickets will not be offered on-site.\", \"vi\": \"Các buổi chiếu phim sẽ bắt đầu lúc 7 giờ tối. Số lượng chỗ ngồi có hạn, vì vậy kính mong quý vị đặt vé trước trên trang web của chúng tôi, vì sẽ không bán vé tại chỗ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The Hillside Farm - Saturday, June 2\", \"vi\": \"Trang trại Hillside - Thứ Bảy, ngày 2 tháng 6\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The story features a mysterious farm on a hill and three generations of the family living there.\", \"vi\": \"Câu chuyện xoay quanh một trang trại bí ẩn nằm trên ngọn đồi và ba thế hệ của gia đình đang sinh sống tại đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Just Two Wheels - Saturday, June 9\", \"vi\": \"Chỉ hai bánh xe - Thứ Bảy, ngày 9 tháng 6\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"A young cyclist spends years preparing for an elite race.\", \"vi\": \"Một vận động viên đua xe đạp trẻ đã dành nhiều năm để chuẩn bị cho một cuộc đua cấp cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This is a heartwarming story of overcoming adversity.\", \"vi\": \"Đây là một câu chuyện cảm động về việc vượt qua nghịch cảnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The Missing Papers - Saturday, June 16\", \"vi\": \"Những tài liệu bị thất lạc - Thứ Bảy, ngày 16 tháng 6\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The puzzling theft of a writer\'s manuscript causes a search for the culprit.\", \"vi\": \"Vụ trộm bản thảo của một nhà văn đầy bí ẩn đã dẫn đến cuộc truy tìm thủ phạm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"A Rambling Homecoming - Saturday, June 23\", \"vi\": \"Một chuyến trở về quê hương đầy ngẫu hứng – Thứ Bảy, ngày 23 tháng 6\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The Khan\'s family reunion celebration is marked by a series of comical incidents and misunderstandings.\", \"vi\": \"Buổi lễ đoàn tụ gia đình của gia đình Khan diễn ra với hàng loạt tình huống hài hước và những hiểu lầm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If you need a good laugh, this is the film for you.\", \"vi\": \"Nếu quý vị muốn có những tràng cười sảng khoái, đây chính là bộ phim dành cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '7ff934bb-e2fc-418f-bb5d-82367cc024a6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mason Nguyen [10:27 A.M.]\", \"vi\": \"Mason Nguyễn [10 giờ 27 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Eva.\", \"vi\": \"Xin chào, Eva.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I\'ve just e-mailed you the presentation slides for our meeting with Lyndon Enterprises.\", \"vi\": \"Tôi vừa gửi email cho quý vị các trang trình chiếu cho cuộc họp của chúng ta với Lyndon Enterprises.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"It outlines how we can help them manage regulations when selling their goods abroad.\", \"vi\": \"Tài liệu này nêu rõ cách thức chúng tôi có thể hỗ trợ quý vị tuân thủ các quy định khi xuất khẩu hàng hóa ra nước ngoài.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Did you receive it?\", \"vi\": \"Quý vị đã nhận được chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Eva Salazar [10:28 A.M.]\", \"vi\": \"Eva Salazar [10 giờ 28 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I\'m just opening it now.\", \"vi\": \"Tôi mới mở nó ra đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Is this the finished version?\", \"vi\": \"Đây có phải là phiên bản hoàn chỉnh không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Mason Nguyen [10:29 A.M.]\", \"vi\": \"Mason Nguyễn [10 giờ 29 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"No. I was wondering if you could put in some statistics on slides 4 through 6.\", \"vi\": \"Không. Tôi đang tự hỏi liệu quý vị có thể bổ sung một số số liệu thống kê vào các trang chiếu từ 4 đến 6 được không.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Eva Salazar [10:30 A.M.]\", \"vi\": \"Eva Salazar [10 giờ 30 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Sure thing.\", \"vi\": \"Chắc chắn rồi.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Do you need me to prepare anything else for it?\", \"vi\": \"Quý vị có cần tôi chuẩn bị thêm gì cho việc đó không?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Mason Nguyen [10:31 A.M.]\", \"vi\": \"Mason Nguyễn [10 giờ 31 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Maybe we should include information about the steps for port registration, as Lyndon Enterprises plans to bring goods into the country as well.\", \"vi\": \"Có lẽ chúng ta nên bổ sung thông tin về các bước đăng ký cảng, vì Lyndon Enterprises cũng có kế hoạch nhập hàng hóa vào nước này.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Eva Salazar [10:33 A.M.]\", \"vi\": \"Eva Salazar [10 giờ 33 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"That might be a good idea.\", \"vi\": \"Đó có lẽ là một ý tưởng hay.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Let me check what you have and get back to you.\", \"vi\": \"Để tôi kiểm tra xem quý vị có những gì và sẽ liên hệ lại với quý vị.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '8069f440-d97b-44f7-b467-92a926e5bfe1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"David Tham [8:04 A.M.]\", \"vi\": \"David Tham [8 giờ 04 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hello, Kelly and Jonathan.\", \"vi\": \"Xin chào, Kelly và Jonathan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Have we confirmed who will be arriving from Hong Kong next week?\", \"vi\": \"Chúng ta đã xác nhận được ai sẽ đến từ Hồng Kông vào tuần tới chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Kelly Cromwell [8:05 A.M.]\", \"vi\": \"Kelly Cromwell [8 giờ 05 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The Hong Kong office is sending Sara Wang and Neha Agarwal.\", \"vi\": \"Văn phòng Hồng Kông sẽ cử bà Sara Wang và bà Neha Agarwal tham dự.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Others can call in if needed.\", \"vi\": \"Nếu cần, những người khác có thể gọi điện đến.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"David Tham [8:07 A.M.]\", \"vi\": \"David Tham [8 giờ 07 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Where will Sara and Neha be working when they arrive?\", \"vi\": \"Khi đến nơi, Sara và Neha sẽ làm việc ở đâu?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Kelly Cromwell [8:09 A.M.]\", \"vi\": \"Kelly Cromwell [8 giờ 09 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"They\'ll be set up in conference room B. Otherwise, they can use the empty desks located near Michael Klein in Human Resources.\", \"vi\": \"Họ sẽ được bố trí tại phòng họp B. Nếu không, họ có thể sử dụng các bàn làm việc trống nằm gần chỗ của ông Michael Klein tại Phòng Nhân sự.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Jonathan Li [8:11 A.M.]\", \"vi\": \"Jonathan Li [8 giờ 11 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Hold on.\", \"vi\": \"Xin chờ một lát.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Actually, there are going to be three.\", \"vi\": \"Thực ra, sẽ có ba người.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Lillian Zhang is coming, too.\", \"vi\": \"Lillian Zhang cũng sẽ tham dự.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"David Tham [8:12 A.M.]\", \"vi\": \"David Tham [8 giờ 12 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We will need another work space then.\", \"vi\": \"Vậy thì chúng ta sẽ cần thêm một không gian làm việc nữa.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I\'d like to keep them together.\", \"vi\": \"Tôi muốn giữ chúng lại với nhau.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Maybe there\'s a spare office in Accounting?\", \"vi\": \"Có lẽ ở phòng Kế toán có một văn phòng trống chăng?\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Kelly Cromwell [8:13 A.M.]\", \"vi\": \"Kelly Cromwell [8 giờ 13 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Why is Ms. Zhang coming?\", \"vi\": \"Tại sao bà Trương lại đến đây?\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I thought it was just the marketing team.\", \"vi\": \"Tôi cứ tưởng đó chỉ là đội ngũ tiếp thị thôi.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Jonathan Li [8:14 A.M.]\", \"vi\": \"Jonathan Li [8 giờ 14 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 7, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"The packaging designers have been working closely with Marketing on this project.\", \"vi\": \"Các nhà thiết kế bao bì đã hợp tác chặt chẽ với bộ phận Tiếp thị trong dự án này.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Kelly Cromwell [8:17 A.M.]\", \"vi\": \"Kelly Cromwell [8 giờ 17 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 8, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Got it.\", \"vi\": \"Tôi hiểu rồi.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I\'ll take care of it.\", \"vi\": \"Tôi sẽ lo việc này.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I\'ll send a final schedule to you before lunch.\", \"vi\": \"Tôi sẽ gửi cho quý vị lịch trình cuối cùng trước giờ ăn trưa.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Jonathan, please update the list of call-in participants\' names and numbers and send it to all of us.\", \"vi\": \"Jonathan, xin vui lòng cập nhật danh sách tên và số điện thoại của những người tham gia qua điện thoại, sau đó gửi cho tất cả chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '8073e2b3-4788-4aea-b637-05f4d9680085';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"WS Dental is pleased to announce that our practice is ______[135].\", \"vi\": \"Nha khoa WS vui mừng thông báo rằng phòng khám của chúng tôi đang ______[135].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [135]}, {\"en\": \"Our second office is now open at 242 Union Street in Lambton, offering greater ______[136] for patients living on the north side of the city.\", \"vi\": \"Chi nhánh thứ hai của chúng tôi nay đã mở cửa tại số 242 phố Union ở Lambton, mang lại sự ______[136] thuận tiện hơn cho các bệnh nhân sống ở phía bắc thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [136]}, {\"en\": \"Our original clinic will continue to operate at 12 Finn Place.\", \"vi\": \"Phòng khám ban đầu của chúng tôi sẽ tiếp tục hoạt động tại số 12 phố Finn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Dr. Walbeck and Dr. Steiner are committed to providing ______[137] care at both locations.\", \"vi\": \"Bác sĩ Walbeck và Bác sĩ Steiner cam kết cung cấp dịch vụ chăm sóc ______[137] tại cả hai địa điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [137]}, {\"en\": \"WS Dental provides a full range of dental services at both offices.\", \"vi\": \"Nha khoa WS cung cấp đầy đủ các dịch vụ nha khoa tại cả hai phòng khám.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"They are both open from 8 A.M. to 5 P.M., Monday through Friday.\", \"vi\": \"Cả hai đều mở cửa từ 8 giờ sáng đến 5 giờ chiều, từ Thứ Hai đến Thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[138].\", \"vi\": \"______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [138]}, {\"en\": \"Extended evening hours will be considered in the coming season.\", \"vi\": \"Thời gian hoạt động kéo dài vào buổi tối sẽ được xem xét trong mùa tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '80788274-2432-4dd3-873e-49e73c928eb3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: team@comlor.com\", \"vi\": \"Gửi tới: team@comlor.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: theo_shanner@comlor.com\", \"vi\": \"Nguồn: theo_shanner@comlor.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: Saturday, July 9\", \"vi\": \"Ngày: Thứ Bảy, ngày 9 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Flooring Update\", \"vi\": \"Chủ đề: Cập nhật về sàn nhà\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Document_1\", \"vi\": \"Tệp đính kèm: Tài liệu_1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Staff,\", \"vi\": \"Kính gửi quý đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Please note that the office will be closed again on Monday because the contractor needs more time than initially anticipated to complete the floor installation.\", \"vi\": \"Kính xin lưu ý rằng văn phòng sẽ tiếp tục đóng cửa vào thứ Hai do nhà thầu cần thêm thời gian so với dự kiến ban đầu để hoàn tất việc lắp đặt sàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I will update you on the progress of the project as details become available.\", \"vi\": \"Tôi sẽ cập nhật cho quý vị về tiến độ của dự án ngay khi có thông tin chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"While at home, though, continue to follow up on project leads and to support your customer accounts.\", \"vi\": \"Tuy nhiên, trong thời gian làm việc tại nhà, quý vị vẫn cần tiếp tục theo dõi các cơ hội dự án và hỗ trợ các tài khoản khách hàng của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Obviously, we will have to postpone the meeting scheduled for Monday until later in the week.\", \"vi\": \"Rõ ràng, chúng ta sẽ phải hoãn cuộc họp dự kiến diễn ra vào thứ Hai sang một thời điểm muộn hơn trong tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"On that occasion we will go over our earnings and revenue of the previous quarter.\", \"vi\": \"Trong dịp đó, chúng tôi sẽ điểm lại kết quả kinh doanh và doanh thu của quý trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I have attached the relevant information so that you can review it ahead of time.\", \"vi\": \"Tôi đã đính kèm các thông tin liên quan để quý vị có thể xem xét trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Additionally, we will be looking at some recent trends in sustainable building design and construction.\", \"vi\": \"Bên cạnh đó, chúng ta sẽ cùng tìm hiểu một số xu hướng gần đây trong thiết kế và thi công công trình bền vững.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Finally, I apologize for the disruption this renovation project has caused.\", \"vi\": \"Cuối cùng, tôi xin chân thành xin lỗi vì những bất tiện mà dự án cải tạo này đã gây ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Then again, I hope you have been seizing this opportunity to find new ways to work effectively and to enjoy work-life balance.\", \"vi\": \"Tuy nhiên, tôi hy vọng quý vị đã tận dụng cơ hội này để tìm ra những phương pháp mới nhằm làm việc hiệu quả hơn và tận hưởng sự cân bằng giữa công việc và cuộc sống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Theo Shanner\", \"vi\": \"Theo Shanner\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Comlor Ltd.\", \"vi\": \"Comlor Ltd.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '808d52a9-9d7c-4325-bb69-fee9beaf7b3b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"💬 👤\", \"vi\": \"💬 👤\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"— □ ✕\", \"vi\": \"— □ ✕\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Yuvraj Bedi - 5:10 P.M. - Thanks for doing this check-in over chat, everyone. My duties at the Abbotsford site made it impossible to get to the office today. Miriam, how\'s the Web site upgrade coming along?\", \"vi\": \"Yuvraj Bedi - 17 giờ 10 phút - Xin cảm ơn quý vị đã tham gia buổi báo cáo tình hình qua trò chuyện trực tuyến hôm nay. Do công việc tại cơ sở Abbotsford nên hôm nay tôi không thể đến văn phòng được. Miriam, việc nâng cấp trang web đang tiến triển thế nào rồi?\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Miriam Thornton - 5:14 P.M. - Very well. Today I called all of our clients from the past year to ask if they\'d be willing to write testimonials for the site. Five of them agreed, including Norman Limited.\", \"vi\": \"Miriam Thornton - 5 giờ 14 phút chiều - Rất tốt. Hôm nay tôi đã gọi điện cho tất cả các khách hàng của chúng ta trong năm qua để hỏi xem họ có sẵn lòng viết lời chứng thực cho trang web hay không. Có năm khách hàng đã đồng ý, trong đó có Norman Limited.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Yuvraj Bedi - 5:15 P.M. - That\'s great. Cody, is there any news about prospective new projects?\", \"vi\": \"Yuvraj Bedi - 5 giờ 15 phút chiều - Thật tuyệt vời. Cody, có tin tức gì về các dự án mới tiềm năng không?\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Cody Haynes - 5:17 P.M. - Yes, there is. The owner of a clothing store just called about building a set of dressing rooms in one of its back corners. I\'m putting together a quote for her. Also, do you remember Glen Webster, who designed the Griffin family\'s house? He recommended us to another residential client. Marvin is going to meet with both of them tomorrow. Oh, and Asami noticed a government project that we might be a good fit for. Asami?\", \"vi\": \"Cody Haynes - 5 giờ 17 phút chiều - Vâng, có thật. Chủ một cửa hàng quần áo vừa gọi điện đến để thảo luận về việc xây dựng một khu phòng thử đồ ở một góc phía sau cửa hàng. Tôi đang soạn bản báo giá cho bà ấy. Ngoài ra, anh có còn nhớ Glen Webster, người đã thiết kế ngôi nhà cho gia đình Griffin không? Ông ấy đã giới thiệu chúng ta cho một khách hàng dân dụng khác. Marvin sẽ gặp cả hai người họ vào ngày mai. À, và Asami đã phát hiện ra một dự án của chính phủ mà chúng ta có thể phù hợp. Asami à?\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Asami Yoshida - 5:20 P.M. - Thanks, Cody. The Vancouver Parks Department announced that it\'s accepting bids for a new storage facility at Hastings Park. I\'m looking into the requirements for city contractors now, and I think we can meet them with a little effort.\", \"vi\": \"Asami Yoshida - 5 giờ 20 phút chiều - Cảm ơn anh, Cody. Sở Công viên Vancouver đã thông báo rằng họ đang tiếp nhận hồ sơ dự thầu cho một cơ sở kho bãi mới tại Công viên Hastings. Hiện tại tôi đang tìm hiểu các yêu cầu đối với các nhà thầu của thành phố, và tôi nghĩ rằng với một chút nỗ lực, chúng ta có thể đáp ứng được những yêu cầu đó.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Yuvraj Bedi - 5:21 P.M. - OK, keep me updated on that. I\'ll wrap up here since we all need to head home soon. Have a good evening, everyone.\", \"vi\": \"Yuvraj Bedi - 5 giờ 21 phút chiều - Được rồi, xin hãy cập nhật thông tin về việc đó cho tôi. Tôi sẽ kết thúc cuộc họp tại đây vì tất cả chúng ta đều cần về nhà sớm. Chúc mọi người một buổi tối tốt lành.\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '80b15058-f478-4253-9079-852d516e588d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Martino Technical has been providing live sound-mixing services for more than 30 years.\", \"vi\": \"Martino Technical đã cung cấp dịch vụ điều khiển âm thanh trực tiếp trong hơn 30 năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"We use the latest technology to produce the best sound.\", \"vi\": \"Chúng tôi áp dụng công nghệ tiên tiến nhất để tạo ra chất lượng âm thanh tốt nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The majority of our clients are heavy-metal and classic-rock musicians.\", \"vi\": \"Phần lớn khách hàng của chúng tôi là các nghệ sĩ nhạc heavy metal và rock cổ điển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Before they go on tour, we rehearse with them to ensure that the sounds are perfectly blended and balanced.\", \"vi\": \"Trước khi họ lên đường lưu diễn, chúng tôi sẽ cùng họ tập luyện để đảm bảo âm thanh được hòa quyện và cân bằng một cách hoàn hảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"In addition, we create recordings for them that they can post on social media to promote their shows.\", \"vi\": \"Bên cạnh đó, chúng tôi còn thực hiện các đoạn video cho họ để họ có thể đăng tải lên mạng xã hội nhằm quảng bá cho các chương trình của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our sound-mixing engineers are known for their experience and professionalism and have an impressive track record working on tours worldwide.\", \"vi\": \"Các kỹ sư trộn âm thanh của chúng tôi được biết đến nhờ kinh nghiệm và sự chuyên nghiệp, đồng thời sở hữu thành tích ấn tượng khi tham gia các chuyến lưu diễn trên toàn thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"They have worked with many popular music groups, including The Peakes, Firebrand, and Cellar Cats, and make bands sound just as good during live performances as they do on their records.\", \"vi\": \"Họ đã hợp tác với nhiều nhóm nhạc nổi tiếng, bao gồm The Peakes, Firebrand và Cellar Cats, đồng thời giúp các ban nhạc thể hiện trên sân khấu trực tiếp hay không kém gì so với trong các bản thu âm của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Contact us by e-mailing information@martinotechnical.ie.\", \"vi\": \"Vui lòng liên hệ với chúng tôi qua email tại địa chỉ information@martinotechnical.ie.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '80c2a3c3-5b8d-4580-af27-c1542693b459';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Hibiscus Supply to Run Its Own\", \"vi\": \"Hibiscus Supply sẽ tự vận hành\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Container Ship\", \"vi\": \"Tàu chở container\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"BUSAN (15 October)—As international shipping continues to increase, companies that transport goods between continents have found themselves competing for expensive space on container ships.\", \"vi\": \"BUSAN (ngày 15 tháng 10) — Trong bối cảnh vận tải biển quốc tế tiếp tục gia tăng, các công ty chuyên vận chuyển hàng hóa giữa các lục địa đang phải cạnh tranh để giành lấy những chỗ chứa đắt đỏ trên các tàu container.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Delays in getting goods to factories and into stores have become more common.\", \"vi\": \"Tình trạng chậm trễ trong việc vận chuyển hàng hóa đến các nhà máy và các cửa hàng đã trở nên phổ biến hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As one of the biggest exporters of home building supplies in the country, Hibiscus Supply is particularly vulnerable to these issues.\", \"vi\": \"Với tư cách là một trong những nhà xuất khẩu vật liệu xây dựng nhà ở lớn nhất cả nước, Hibiscus Supply đặc biệt dễ bị ảnh hưởng bởi những vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"To avoid potential shipping problems, Hibiscus Supply has decided to operate its own container ship to export products overseas.\", \"vi\": \"Để tránh những rủi ro có thể xảy ra trong quá trình vận chuyển, Hibiscus Supply đã quyết định vận hành tàu container riêng để xuất khẩu sản phẩm ra nước ngoài.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"According to Hibiscus Supply president James Koh, operating the company’s own ship should improve efficiency at ports and decrease overall shipping costs.\", \"vi\": \"Theo ông James Koh, Chủ tịch Công ty Hibiscus Supply, việc vận hành tàu riêng của công ty sẽ giúp nâng cao hiệu quả hoạt động tại các cảng và giảm chi phí vận chuyển tổng thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Says Mr. Koh, “The cost to ship with freight companies has doubled in the past year.\", \"vi\": \"Ông Koh cho biết: “Chi phí vận chuyển qua các công ty vận tải đã tăng gấp đôi trong năm qua.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"By shipping our products ourselves, we’ll be able to avoid passing shipping-related price increases on to our customers.”\", \"vi\": \"“Bằng cách tự mình vận chuyển sản phẩm, chúng tôi sẽ có thể tránh việc chuyển các khoản tăng giá liên quan đến vận chuyển sang cho khách hàng.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '815cf478-98c8-46ee-92f9-5d212a060d17';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Sanberg Industries: Big Angle Television Wall Mount\", \"vi\": \"Sanberg Industries: Giá treo tường TV góc rộng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Big Angle Television Wall Mount is perfect for mounting televisions from 40 inches to 75 inches in size as measured diagonally across the screen.\", \"vi\": \"Giá treo tường TV góc rộng rất hoàn hảo để lắp đặt các dòng ti-vi có kích thước từ 40 inch đến 75 inch được đo theo đường chéo qua màn hình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The mount connects easily to your wall, ___131____ freeing your tabletops and saving space.\", \"vi\": \"Giá treo dễ dàng kết nối với tường nhà bạn, ___131____ giúp giải phóng không gian bàn và tiết kiệm diện tích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [131]}, {\"en\": \"The ___132____ mount comes with a 25-inch arm that bends in multiple directions so you can enjoy watching television from anywhere in the room.\", \"vi\": \"Bộ giá treo ___132____ đi kèm với một cánh tay dài 25 inch có thể uốn cong theo nhiều hướng để bạn có thể thưởng thức các chương trình truyền hình từ bất kỳ vị trí nào trong phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [132]}, {\"en\": \"Plus, it has vertical and horizontal tilt capabilities, so your television can be placed ___133____ in the position you like.\", \"vi\": \"Thêm vào đó, sản phẩm này có tính năng nghiêng theo cả chiều dọc và chiều ngang, nhờ vậy ti-vi của bạn có thể được đặt ___133____ ở vị trí mà bạn ưa thích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [133]}, {\"en\": \"___134____ .\", \"vi\": \"___134____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [134]}]' WHERE `id` = '816e6559-662a-446f-aed2-8e21a94da67e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ella Glatt (11:34 A.M.)\", \"vi\": \"Ella Glatt (11 giờ 34 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi.\", \"vi\": \"Xin chào\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I know this is a busy day, but I wanted to know whether anyone from the finance team could come to the marketing meeting.\", \"vi\": \"Tôi biết hôm nay là một ngày bận rộn, nhưng tôi muốn hỏi xem có ai trong bộ phận tài chính có thể tham dự cuộc họp tiếp thị không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Stef Goldberg (11:35 A.M.)\", \"vi\": \"Stef Goldberg (11 giờ 35 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hi, Ella.\", \"vi\": \"Xin chào, Ella.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I wish I could, but it starts at 2:00.\", \"vi\": \"Tôi ước gì mình có thể, nhưng chương trình bắt đầu lúc 2 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I need to be at a different meeting at 2:30.\", \"vi\": \"Tôi cần phải có mặt tại một cuộc họp khác vào lúc 2 giờ 30.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Ella Glatt (11:36 A.M.)\", \"vi\": \"Ella Glatt (11 giờ 36 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Oh, right.\", \"vi\": \"À, đúng rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I forgot you were going to the executive board meeting.\", \"vi\": \"Tôi đã quên rằng quý vị định tham dự cuộc họp của Hội đồng quản trị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Daniel Seidal (11:36 A.M.)\", \"vi\": \"Daniel Seidal (11 giờ 36 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I\'m also supposed to go to the 2:30 meeting.\", \"vi\": \"Tôi cũng dự kiến sẽ tham dự cuộc họp lúc 2 giờ 30.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Is it essential that one of us attend the marketing meeting?\", \"vi\": \"Liệu có nhất thiết phải có một người trong số chúng ta tham dự cuộc họp tiếp thị hay không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Ella Glatt (11:37 A.M.)\", \"vi\": \"Ella Glatt (11 giờ 37 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Well, it would be helpful to have someone from the finance department there, at least for 15 minutes or so.\", \"vi\": \"Thật ra, sẽ rất hữu ích nếu có một người nào đó từ phòng tài chính có mặt tại đó, ít nhất khoảng 15 phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Bill Iverman (11:38 A.M.)\", \"vi\": \"Bill Iverman (11 giờ 38 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The quarterly reports just came in, and Daniel, Stef, and I need to review them by the end of the day.\", \"vi\": \"Các báo cáo quý vừa được gửi đến, và Daniel, Stef cùng tôi cần phải xem xét chúng trước khi kết thúc ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Ella Glatt (11:39 A.M.)\", \"vi\": \"Ella Glatt (11 giờ 39 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"You all have plenty to do.\", \"vi\": \"Tất cả quý vị đều có rất nhiều việc phải làm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Daniel Seidal (11:41 A.M.)\", \"vi\": \"Daniel Seidal (11 giờ 41 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"That\'s true!\", \"vi\": \"Điều đó đúng thật!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"But I could come from 2:00 to 2:15.\", \"vi\": \"Tuy nhiên, tôi có thể đến từ 2 giờ đến 2 giờ 15 phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"That\'s all I can commit to.\", \"vi\": \"Đó là tất cả những gì tôi có thể cam kết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Ella Glatt (11:43 A.M.)\", \"vi\": \"Ella Glatt (11 giờ 43 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Sounds great.\", \"vi\": \"Nghe thật tuyệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"We just need one of you to clarify a few quick points about the budget for the next advertising campaign.\", \"vi\": \"Chúng tôi chỉ cần một trong số quý vị làm rõ một vài điểm ngắn gọn về ngân sách cho chiến dịch quảng cáo sắp tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '817ca96d-0949-4141-a794-66a42d55e9c8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Finance Director\", \"vi\": \"Giám đốc Tài chính\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Palliz Foundation seeks a finance director to be a member of our senior leadership team.\", \"vi\": \"Quỹ Palliz đang tìm kiếm một giám đốc tài chính để trở thành thành viên của đội ngũ lãnh đạo cấp cao của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This is a supervisory position reporting directly to the foundation president.\", \"vi\": \"Đây là một vị trí quản lý trực thuộc trực tiếp Chủ tịch Quỹ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The finance director manages the seven-member finance department, including the payroll manager and accounting director.\", \"vi\": \"Giám đốc tài chính phụ trách bộ phận tài chính gồm bảy thành viên, trong đó có Trưởng phòng tính lương và Giám đốc kế toán.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The finance director is responsible for the oversight and maintenance of accounting and purchasing systems.\", \"vi\": \"Giám đốc tài chính chịu trách nhiệm giám sát và duy trì các hệ thống kế toán và mua sắm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The person in this position monitors internal control procedures and ensures compliance with legal obligations.\", \"vi\": \"Người đảm nhiệm vị trí này có nhiệm vụ giám sát các quy trình kiểm soát nội bộ và đảm bảo tuân thủ các nghĩa vụ pháp lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Additional responsibilities include disbursement, investment, and management of all company funds, development of financial policies and practices, budget preparation, and creation of reports for the board of directors.\", \"vi\": \"Các trách nhiệm khác bao gồm việc chi trả, đầu tư và quản lý toàn bộ nguồn vốn của công ty, xây dựng các chính sách và quy trình tài chính, lập dự toán ngân sách, cũng như soạn thảo các báo cáo trình Hội đồng quản trị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Preference will be given to current employees.\", \"vi\": \"Các ứng viên hiện đang làm việc tại công ty sẽ được ưu tiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Interested parties should submit a résumé listing their qualifications to the human resources department at humanresources@pallizfoundation.org no later than 4:30 P.M. on Friday, April 23.\", \"vi\": \"Các ứng viên quan tâm vui lòng gửi sơ yếu lý lịch nêu rõ các bằng cấp và kinh nghiệm của mình đến Phòng Nhân sự qua địa chỉ email humanresources@pallizfoundation.org chậm nhất là 4 giờ 30 chiều Thứ Sáu, ngày 23 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '818cfcb5-28a0-4b03-866a-5752ada819a8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Kristen Coetzee <kcoetzee@rhyta.co.za>\", \"vi\": \"Gửi tới: Kristen Coetzee <kcoetzee@rhyta.co.za>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Anita Ngubane <angubane@clubfreshenup.co.za>\", \"vi\": \"Từ: Anita Ngubane <angubane@clubfreshenup.co.za>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Welcome to Club Freshen-Up\", \"vi\": \"Chủ đề: Chào mừng quý vị đến với Câu lạc bộ Freshen-Up\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Date: 12 January\", \"vi\": \"Ngày: 12 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Coetzee,\", \"vi\": \"Kính gửi bà Coetzee,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for joining Club Freshen-Up.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã gia nhập Câu lạc bộ Freshen-Up.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We are delighted to be a part of your continuing journey to well-being for the next twelve months.\", \"vi\": \"Chúng tôi rất hân hạnh được đồng hành cùng quý vị trên hành trình hướng tới sức khỏe và hạnh phúc trong mười hai tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Your membership in Club Freshen-Up entitles you to a monthly delivery of six essential health-care and beauty products.\", \"vi\": \"Với tư cách là thành viên của Club Freshen-Up, quý vị sẽ được nhận một gói giao hàng hàng tháng gồm sáu sản phẩm chăm sóc sức khỏe và làm đẹp thiết yếu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Each shipment will contain a variety of individually packaged items in attractive and reusable containers.\", \"vi\": \"Mỗi lô hàng sẽ bao gồm nhiều mặt hàng khác nhau, được đóng gói riêng lẻ trong các bao bì bắt mắt và có thể tái sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Accompanying every shipment will be an itemised receipt listing product numbers.\", \"vi\": \"Mỗi lô hàng sẽ được kèm theo một biên lai chi tiết liệt kê các mã sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please refer to these numbers when contacting us with questions about a product.\", \"vi\": \"Khi liên hệ với chúng tôi để hỏi về sản phẩm, xin vui lòng tham khảo các số điện thoại này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Everything from vitamins to lotions to cosmetics will be chosen just for you based on the eight answers you provided in the personal-preferences questionnaire.\", \"vi\": \"Tất cả mọi thứ, từ vitamin đến kem dưỡng da và mỹ phẩm, sẽ được lựa chọn riêng cho quý vị dựa trên tám câu trả lời mà quý vị đã cung cấp trong bảng câu hỏi về sở thích cá nhân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Every item you receive is guaranteed for one full year from the date of shipment.\", \"vi\": \"Mỗi sản phẩm quý vị nhận được đều được bảo hành trong vòng một năm kể từ ngày giao hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If you wish to return an item, simply send us the unused portion along with a short note describing the reason for your dissatisfaction.\", \"vi\": \"Nếu quý khách muốn trả lại sản phẩm, xin vui lòng gửi lại cho chúng tôi phần sản phẩm chưa qua sử dụng kèm theo một lời nhắn ngắn giải thích lý do khiến quý khách không hài lòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Upon receipt, we will send you an alternative of equal value.\", \"vi\": \"Ngay sau khi nhận được hàng, chúng tôi sẽ gửi cho quý vị một sản phẩm thay thế có giá trị tương đương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Anita Ngubane\", \"vi\": \"Anita Ngubane\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Member Services Specialist, Club Freshen-Up\", \"vi\": \"Chuyên viên Dịch vụ Thành viên, Chương trình Cải thiện Câu lạc bộ\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '81cf40c8-9604-4a88-96cb-da5ab1447d76';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Management Team\", \"vi\": \"Kính gửi: Ban Lãnh đạo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Fiona Watson\", \"vi\": \"Từ: Fiona Watson\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 19\", \"vi\": \"Ngày: 19 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Spring meeting\", \"vi\": \"Chủ đề: Cuộc họp mùa xuân\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Final Agenda\", \"vi\": \"Tài liệu đính kèm: 📎 Chương trình làm việc chính thức\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Colleagues,\", \"vi\": \"Kính gửi các đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This is a reminder that Contiera Corporation\'s spring management meeting is scheduled for 9 A.M. tomorrow.\", \"vi\": \"Xin nhắc lại rằng cuộc họp quản lý mùa xuân của Tập đoàn Contiera dự kiến sẽ diễn ra vào lúc 9 giờ sáng ngày mai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The final agenda is attached.\", \"vi\": \"Chương trình nghị sự cuối cùng được đính kèm dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please note that I have added an item to the original meeting agenda.\", \"vi\": \"Xin lưu ý rằng tôi đã bổ sung một nội dung vào chương trình nghị sự ban đầu của cuộc họp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Mai Tran, our publications supervisor, wants to update everyone on this season\'s product line.\", \"vi\": \"Bà Mai Trần, Trưởng bộ phận Xuất bản của chúng tôi, muốn cập nhật cho quý vị về dòng sản phẩm của mùa này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"She should not take more than twenty minutes.\", \"vi\": \"Cô ấy không nên mất quá hai mươi phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To prepare for the meeting, please review our most recent marketing plan so that we all have a clear idea of our goals for the quarter.\", \"vi\": \"Để chuẩn bị cho cuộc họp, xin quý vị vui lòng xem lại kế hoạch tiếp thị mới nhất của chúng ta để tất cả chúng ta đều có cái nhìn rõ ràng về các mục tiêu của quý này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"It would also help if each of you brought copies of your latest budget report and projected cost estimates for next quarter.\", \"vi\": \"Sẽ rất hữu ích nếu mỗi quý vị mang theo bản sao báo cáo ngân sách mới nhất và dự toán chi phí cho quý tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I look forward to seeing you tomorrow.\", \"vi\": \"Tôi rất mong được gặp quý vị vào ngày mai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Fiona Watson\", \"vi\": \"Fiona Watson\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Topic - Description - Leader\", \"vi\": \"Chủ đề - Mô tả - Người dẫn dắt\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Community events - – Learn about local outreach opportunities - Paul Ranier, president of the Arborville Business Association\", \"vi\": \"Các sự kiện cộng đồng – Tìm hiểu về các cơ hội tham gia hoạt động cộng đồng tại địa phương – Ông Paul Ranier, Chủ tịch Hiệp hội Doanh nghiệp Arborville\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Budget review - – Discuss department budgets - Fiona Watson\", \"vi\": \"Rà soát ngân sách – Thảo luận về ngân sách các phòng ban – Fiona Watson\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Online advertising - – Review cost of Web ads\\n– Analyze areas for growth - Marcia Dover\", \"vi\": \"Quảng cáo trực tuyến - – Đánh giá chi phí quảng cáo trên web\\n– Phân tích các lĩnh vực có tiềm năng tăng trưởng - Marcia Dover\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Web site updates - – Present recent changes to ski-apparel page\\n– Demonstrate new content management software - Barry Callahan\", \"vi\": \"Cập nhật trang web - – Giới thiệu những thay đổi gần đây trên trang trang phục trượt tuyết\\n– Trình diễn phần mềm quản lý nội dung mới - Barry Callahan\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Print publications - – Review final changes to spring sportswear catalog - Mai Tran\", \"vi\": \"Ấn phẩm in – – Rà soát các chỉnh sửa cuối cùng cho catalogue trang phục thể thao mùa xuân – Mai Trần\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Spring Management Meeting—Final Agenda\", \"vi\": \"Hội nghị Quản lý Mùa Xuân — Chương trình làm việc cuối cùng\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Date and Time: March 20, 9 A.M.\", \"vi\": \"Ngày và giờ: 20 tháng 3, 9 giờ sáng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Location: Conference Room 2\", \"vi\": \"Địa điểm: Phòng hội nghị số 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}]' WHERE `id` = '820697bf-4bb1-4a28-910c-861933252fcc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Hollydale Medical Center\", \"vi\": \"Trung tâm Y tế Hollydale\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To All Office Staff:\", \"vi\": \"Gửi Tất cả Nhân viên Văn phòng:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The move to our new medical center building will take place this weekend.\", \"vi\": \"Việc chuyển đến tòa nhà trung tâm y tế mới của chúng ta sẽ diễn ra vào cuối tuần này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"______[131], all items in your desks must be packed before the end of the day on Friday.\", \"vi\": \"______[131], tất cả các vật dụng trên bàn làm việc của bạn phải được đóng gói trước khi kết thúc ngày thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [131]}, {\"en\": \"The empty boxes ______[132] to you by 8:00 A.M. on Thursday.\", \"vi\": \"Các hộp trống ______[132] cho bạn trước 8:00 sáng vào thứ Năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [132]}, {\"en\": \"When you arrive at our new location on Monday morning, your boxes should already be in your new office.\", \"vi\": \"Khi bạn đến địa điểm mới vào sáng thứ Hai, các hộp của bạn đã phải ở sẵn trong văn phòng mới của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[133].\", \"vi\": \"______[133].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [133]}, {\"en\": \"If you will be out of the office this Thursday or Friday, notify me immediately so we can make other arrangements.\", \"vi\": \"Nếu bạn vắng mặt ở văn phòng vào thứ Năm hoặc thứ Sáu tuần này, hãy thông báo cho tôi ngay lập tức để chúng tôi có thể sắp xếp phương án khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We appreciate your cooperation in helping to make this transition to our new location go as ______[134] as possible.\", \"vi\": \"Chúng tôi đánh giá cao sự hợp tác của bạn trong việc giúp cho quá trình chuyển đến địa điểm mới này diễn ra ______[134] nhất có thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [134]}, {\"en\": \"Jian Tang, Office Manager\", \"vi\": \"Jian Tang, Quản lý Văn phòng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '82381778-49f1-404e-9889-8fcdadab345c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Sally Witham (4:47 P.M.)\", \"vi\": \"Sally Witham (4 giờ 47 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi Wakiko.\", \"vi\": \"Quý vị khỏe không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I just finished up here at the Kyoto store.\", \"vi\": \"Tôi vừa hoàn tất công việc tại cửa hàng ở Kyoto.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I\'ll be on the train that arrives in Tokyo at 11:35 tomorrow morning.\", \"vi\": \"Ngày mai vào buổi sáng, tôi sẽ đi trên chuyến tàu đến Tokyo lúc 11 giờ 35.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"How should I get to your location?\", \"vi\": \"Tôi nên đi như thế nào để đến địa điểm của quý vị?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Wakiko Ohara (4:48 P.M.)\", \"vi\": \"Wakiko Ohara (4 giờ 48 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I\'ll have an associate pick you up at the station.\", \"vi\": \"Tôi sẽ nhờ một đồng nghiệp đến đón quý vị tại ga.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"How do things look in Kyoto?\", \"vi\": \"Tình hình ở Kyoto hiện nay ra sao?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Sally Witham (4:49 P.M.)\", \"vi\": \"Sally Witham (4 giờ 49 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The Kyoto store is doing a great job.\", \"vi\": \"Cửa hàng tại Kyoto đang hoạt động rất tốt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"It has everything that we at the home office are looking for.\", \"vi\": \"Nó có đầy đủ mọi yếu tố mà chúng tôi tại trụ sở chính đang tìm kiếm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Athletic shoes and sandals are displayed according to specifications, and sales associates are friendly and knowledgeable.\", \"vi\": \"Giày thể thao và dép xăng-đan được trưng bày theo từng loại sản phẩm, và các nhân viên bán hàng rất thân thiện và am hiểu sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Wakiko Ohara (4:51 P.M.)\", \"vi\": \"Wakiko Ohara (4 giờ 51 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"You should like things here, too.\", \"vi\": \"Chắc hẳn quý vị cũng sẽ thích nơi này.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Do you want to begin your visit after lunch, say at 2:00?\", \"vi\": \"Quý vị có muốn bắt đầu chuyến tham quan sau bữa trưa, chẳng hạn vào lúc 2 giờ không?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sally Witham (4:52 P.M.)\", \"vi\": \"Sally Witham (4 giờ 52 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sounds good.\", \"vi\": \"Nghe có vẻ hay đấy.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"See you tomorrow.\", \"vi\": \"Hẹn gặp lại quý vị vào ngày mai.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '8249b03a-3de8-4a90-b943-d91f312467d1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Optieris Office of Parking and Transportation\", \"vi\": \"Từ: Văn phòng Quản lý Bãi đỗ xe và Giao thông của Optieris\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All Optieris staff\", \"vi\": \"Kính gửi: Toàn thể nhân viên Optieris\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: December 20\", \"vi\": \"Ngày: 20 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Upcoming enhancements to our shuttle bus system\", \"vi\": \"Chủ đề: Những cải tiến sắp tới đối với hệ thống xe buýt đưa đón của chúng tôi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"In direct response to your helpful feedback, we would like to announce a number of improvements to the shuttle system that connects the Optieris campus with the Morbrook and Nesse train stations.\", \"vi\": \"Để trực tiếp đáp ứng những ý kiến đóng góp hữu ích của quý vị, chúng tôi xin thông báo về một số cải tiến đối với hệ thống xe đưa đón kết nối khuôn viên Optieris với các ga tàu Morbrook và Nesse.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The following changes will go into effect on January 2:\", \"vi\": \"Các thay đổi sau đây sẽ có hiệu lực vào ngày 2 tháng 1:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"(1) A third bus will be added to our fleet to increase service frequency as well as capacity in case one bus is ever down for maintenance.\", \"vi\": \"(1) Một chiếc xe buýt thứ ba sẽ được bổ sung vào đội xe của chúng tôi nhằm tăng tần suất phục vụ cũng như nâng cao công suất vận chuyển trong trường hợp có một chiếc xe buýt phải ngừng hoạt động để bảo dưỡng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Buses will now run every 15 minutes instead of 30 minutes.\", \"vi\": \"Từ nay, các chuyến xe buýt sẽ chạy cách nhau 15 phút thay vì 30 phút như trước đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"(2) A second campus stop will be added.\", \"vi\": \"(2) Một điểm dừng thứ hai tại khuôn viên trường sẽ được bổ sung.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Besides the current stop at the main administration building on the east side of the Optieris campus, there will be a second stop to better accommodate all our staff.\", \"vi\": \"Bên cạnh trạm dừng hiện tại tại tòa nhà hành chính chính ở phía đông khuôn viên Optieris, sẽ có thêm một trạm dừng thứ hai nhằm tạo điều kiện thuận lợi hơn cho toàn thể nhân viên của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"(3) A service will be added in the evening.\", \"vi\": \"(3) Buổi tối sẽ có thêm một chuyến xe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It will depart the Optieris campus 30 minutes later than the current last service of the day.\", \"vi\": \"Chuyến xe này sẽ khởi hành từ khuôn viên Optieris muộn hơn 30 phút so với chuyến cuối cùng hiện tại trong ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thanks again for your input.\", \"vi\": \"Một lần nữa, xin cảm ơn ý kiến đóng góp của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"For the sake of our environment, we are proud to facilitate your use of public transportation by making our shuttle bus service more convenient than ever.\", \"vi\": \"Vì lợi ích của môi trường, chúng tôi tự hào được tạo điều kiện thuận lợi cho quý vị sử dụng phương tiện giao thông công cộng bằng cách nâng cao sự tiện lợi của dịch vụ xe buýt đưa đón lên mức cao nhất từ trước đến nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Morbrook\\nStation - → Nesse\\nStation - → East\\nCampus - → West\\nCampus\", \"vi\": \"Morbrook\\nGa - → Nesse\\nGa - → Khuôn viên phía Đông\\n- → Khuôn viên phía Tây\\nKhuôn viên\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"7:15 - 7:21 - 7:39 - 7:42\", \"vi\": \"7 giờ 15 - 7 giờ 21 - 7 giờ 39 - 7 giờ 42\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"7:30 - 7:36 - 7:54 - 7:57\", \"vi\": \"7:30 – 7:36 – 7:54 – 7:57\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"7:45 - 7:51 - 8:09 - 8:12\", \"vi\": \"7:45 - 7:51 - 8:09 - 8:12\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"8:00 - 8:06 - 8:24 - 8:27\", \"vi\": \"8:00 - 8:06 - 8:24 - 8:27\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"8:15 - 8:21 - 8:39 - 8:42\", \"vi\": \"8:15 – 8:21 – 8:39 – 8:42\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"8:30 - 8:36 - 8:54 - 8:57\", \"vi\": \"8:30 - 8:36 - 8:54 - 8:57\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Shuttle Bus Schedule—Weekday Mornings\", \"vi\": \"Lịch trình xe buýt đưa đón — Buổi sáng các ngày trong tuần\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"(Updated January 2)\", \"vi\": \"(Cập nhật ngày 2 tháng 1)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"From: Sofia Edgren <sofiaedgren@lekmail.com>\", \"vi\": \"Từ: Sofia Edgren <sofiaedgren@lekmail.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"To: Sharani Khamis <s.khamis@optieris.com>\", \"vi\": \"Gửi: Sharani Khamis <s.khamis@optieris.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Subject: Applicant interview at Optieris\", \"vi\": \"Chủ đề: Buổi phỏng vấn ứng viên tại Optieris\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date: January 25\", \"vi\": \"Ngày: 25 tháng 1\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Dear Ms. Khamis,\", \"vi\": \"Kính gửi Bà Khamis,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Thanks for inviting me to an interview with Mr. Rochon next week on the Optieris campus.\", \"vi\": \"Xin cảm ơn quý vị đã mời tôi tham gia buổi phỏng vấn với ông Rochon vào tuần tới tại khuôn viên Optieris.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I am certainly excited to be a finalist for this position in quality control.\", \"vi\": \"Tôi thực sự rất hào hứng khi được lọt vào vòng chung kết cho vị trí kiểm soát chất lượng này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I also appreciate your sending me the company shuttle bus schedule.\", \"vi\": \"Tôi cũng xin chân thành cảm ơn quý vị đã gửi cho tôi lịch trình xe buýt đưa đón của công ty.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I will take a train arriving at Nesse Station at 7:55 A.M. and then your shuttle bus upon arrival, which should get me to your West Campus at a reasonable time.\", \"vi\": \"Tôi sẽ đi chuyến tàu đến ga Nesse lúc 7 giờ 55 phút sáng, và sau đó sẽ lên xe buýt đưa đón của quý vị ngay khi đến nơi; như vậy, tôi sẽ đến được Khuôn viên Tây của quý vị vào một thời điểm hợp lý.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Sofia Edgren\", \"vi\": \"Sofia Edgren\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '8250328a-d84d-4e00-9414-f8b4fa6849c8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Lynette Walter (4:45 P.M.)\", \"vi\": \"Lynette Walter (4 giờ 45 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Can the three of us get together for lunch tomorrow before the sales meeting?\", \"vi\": \"Ngày mai, trước cuộc họp bán hàng, ba chúng ta có thể gặp nhau ăn trưa được không ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Tripp Hines (4:46 P.M.)\", \"vi\": \"Tripp Hines (4 giờ 46 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Sure, Lynette.\", \"vi\": \"Được thôi, Lynette.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Is there something specific you would like to talk about?\", \"vi\": \"Có chủ đề cụ thể nào mà quý vị muốn thảo luận không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Lynette Walter (4:47 P.M.)\", \"vi\": \"Lynette Walter (4 giờ 47 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I just want to make sure that we\'re on the same page about the new marketing campaign.\", \"vi\": \"Tôi chỉ muốn đảm bảo rằng chúng ta có cùng quan điểm về chiến dịch tiếp thị mới này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Tripp Hines (4:48 P.M.)\", \"vi\": \"Tripp Hines (4 giờ 48 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The one for the line of summer shoes?\", \"vi\": \"Mẫu dành cho dòng giày mùa hè phải không ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Lynette Walter (4:49 P.M.)\", \"vi\": \"Lynette Walter (4 giờ 49 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Yes.\", \"vi\": \"Vâng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I need to catch up on what I missed while I was away in Boston, both the text and the graphics being developed.\", \"vi\": \"Tôi cần cập nhật những nội dung mình đã bỏ lỡ trong thời gian công tác tại Boston, bao gồm cả phần nội dung văn bản lẫn các hình ảnh đang được phát triển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"April Au (4:50 P.M.)\", \"vi\": \"April Au (4 giờ 50 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sorry, when and where is the sales meeting?\", \"vi\": \"Xin lỗi, cuộc họp bán hàng sẽ diễn ra vào lúc nào và ở đâu vậy?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I checked my calendar, and I could not find that meeting.\", \"vi\": \"Tôi đã kiểm tra lịch của mình nhưng không tìm thấy cuộc họp đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Tripp Hines (4:51 P.M.)\", \"vi\": \"Tripp Hines (4 giờ 51 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"It starts at 3:00 in the boardroom.\", \"vi\": \"Cuộc họp sẽ bắt đầu lúc 3 giờ tại phòng họp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"You don\'t need to be there.\", \"vi\": \"Quý vị không cần phải có mặt ở đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"It\'s only for people involved in the graphics.\", \"vi\": \"Điều này chỉ dành cho những người làm việc trong lĩnh vực đồ họa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"April Au (4:52 P.M.)\", \"vi\": \"April Au (4 giờ 52 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"What a relief!\", \"vi\": \"Thật là nhẹ nhõm!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"And yes, I can go to lunch with you, Lynette, and provide an update on the language being considered.\", \"vi\": \"Và vâng, tôi có thể đi ăn trưa cùng cô, Lynette, và cập nhật thông tin mới nhất về nội dung đang được xem xét.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Lynette Walter (4:53 P.M.)\", \"vi\": \"Lynette Walter (4 giờ 53 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Wonderful.\", \"vi\": \"Thật tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I\'ll see you both tomorrow at 1:30 in the lobby.\", \"vi\": \"Tôi sẽ gặp cả hai quý vị vào lúc 1 giờ 30 phút ngày mai tại sảnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"We can decide where to eat then.\", \"vi\": \"Vậy thì chúng ta có thể quyết định ăn ở đâu sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '82711bdd-a57d-430d-b323-394116496aaa';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Franklin Planetarium to Move Downtown\", \"vi\": \"Cung thiên văn Franklin chuyển về trung tâm thành phố\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"(June 3)—After 48 years in its present location on Mayfield\'s south side, the Franklin Planetarium is moving to a new home.\", \"vi\": \"(Ngày 3 tháng 6)—Sau 48 năm ở địa điểm hiện tại ở phía nam Mayfield, Cung thiên văn Franklin đang chuyển đến một cơ sở mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Construction is underway on the downtown facility, part of a complex that includes the new Natural History Museum.\", \"vi\": \"Công tác xây dựng đang được tiến hành tại cơ sở ở trung tâm thành phố, là một phần của khu phức hợp bao gồm Bảo tàng Lịch sử Tự nhiên mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Both ___143___ are expected to open to the public next September.\", \"vi\": \"Cả hai ___143___ dự kiến sẽ mở cửa đón công chúng vào tháng 9 tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [143]}, {\"en\": \"The current planetarium’s main attraction is a 300-seat theater, where visitors can view projections of stars and planets on the dome above.\", \"vi\": \"Điểm thu hút chính của cung thiên văn hiện tại là một rạp chiếu phim 300 chỗ ngồi, nơi du khách có thể xem các hình chiếu các ngôi sao và hành tinh trên mái vòm phía trên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"___144___ a larger theater, the new planetarium will feature an upgraded digital projection system.\", \"vi\": \"___144___ một rạp chiếu phim lớn hơn, cung thiên văn mới sẽ có hệ thống chiếu kỹ thuật số được nâng cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [144]}, {\"en\": \"___145___ .\", \"vi\": \"___145___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [145]}, {\"en\": \"Visitors will be able ___146___ the night sky more clearly and explore other planets and galaxies through new, interactive displays.\", \"vi\": \"Du khách sẽ có thể ___146___ bầu trời đêm rõ ràng hơn và khám phá các hành tinh và thiên hà khác thông qua các màn hình tương tác mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [146]}]' WHERE `id` = '82795fd6-a947-4099-96e0-e4d086c07a16';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Notice\", \"vi\": \"Thông báo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The sidewalk along Crestview Boulevard is scheduled to be repaired next week.\", \"vi\": \"Vỉa hè dọc theo Đại lộ Crestview dự kiến sẽ được sửa chữa vào tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Due to safety concerns, the front door of the Queenstown Financial Services (QFS) building will be inaccessible from Monday, 15 January, to Wednesday, 17 January.\", \"vi\": \"Vì lý do an toàn, cửa chính của tòa nhà Queenstown Financial Services (QFS) sẽ không thể ra vào được từ thứ Hai, ngày 15 tháng 1, đến thứ Tư, ngày 17 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"QFS employees and customers are advised to use the north entrance on Sycamore Avenue.\", \"vi\": \"Các nhân viên và khách hàng của QFS được khuyến cáo nên sử dụng lối vào phía bắc trên Đại lộ Sycamore.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"To get to the receptionist on the second floor, take either the staircase or the elevator, both of which can be found near the north entrance.\", \"vi\": \"Để đến gặp nhân viên lễ tân ở tầng hai, quý vị có thể đi cầu thang bộ hoặc thang máy; cả hai đều nằm gần lối vào phía bắc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}]' WHERE `id` = '82889958-b899-418c-8cf7-8df5a6284a34';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Yi-Seul Kwak (1:16 P.M.)\", \"vi\": \"Yi-Seul Kwak (1 giờ 16 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Stacy, are you back from lunch yet?\", \"vi\": \"Stacy ơi, cô đã ăn trưa xong và trở lại chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Stacy Ulrich (1:17 P.M.)\", \"vi\": \"Stacy Ulrich (1 giờ 17 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Yes, I\'m at my desk.\", \"vi\": \"Vâng, tôi đang ngồi tại bàn làm việc của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"What\'s up?\", \"vi\": \"Có chuyện gì vậy?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Yi-Seul Kwak (1:18 P.M.)\", \"vi\": \"Đó là Seul Kwak (1 giờ 18 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I\'m at the store picking up supplies for the office, and I need a favor.\", \"vi\": \"Tôi đang ở cửa hàng để mua một số vật dụng cho văn phòng, và tôi cần anh/chị giúp một việc.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You know those yellow notepads that the lawyers like to use?\", \"vi\": \"Quý vị có biết những cuốn sổ ghi chú màu vàng mà các luật sư thường hay sử dụng không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I just realized I\'m not sure how many of them we have left.\", \"vi\": \"Tôi vừa mới nhận ra rằng mình không chắc chúng ta còn lại bao nhiêu cái nữa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Stacy Ulrich (1:19 P.M.)\", \"vi\": \"Stacy Ulrich (1 giờ 19 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"OK, I\'ll find out.\", \"vi\": \"Được rồi, tôi sẽ tìm hiểu xem sao.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Where should I look?\", \"vi\": \"Tôi nên tìm ở đâu?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Yi-Seul Kwak (1:20 P.M.)\", \"vi\": \"Yi-Seul Kwak (1 giờ 20 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"They\'re in a box in the supply room.\", \"vi\": \"Chúng đang được đựng trong một chiếc hộp ở phòng kho.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Stacy Ulrich (1:22 P.M.)\", \"vi\": \"Stacy Ulrich (1 giờ 22 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The supply room is full of boxes.\", \"vi\": \"Phòng chứa vật tư chật kín các thùng hàng.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Yi-Seul Kwak (1:23 P.M.)\", \"vi\": \"Đó là Seul Kwak (1 giờ 23 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Oh, right.\", \"vi\": \"À, đúng rồi.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"It\'s on a bottom shelf near the door, and \\\"Bynum, Inc.\\\" is printed on the sides.\", \"vi\": \"Nó nằm trên kệ dưới cùng gần cửa, và trên các mặt bên có in dòng chữ “Bynum, Inc.”.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Stacy Ulrich (1:24 P.M.)\", \"vi\": \"Stacy Ulrich (1 giờ 24 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 7, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I found it.\", \"vi\": \"Tôi đã tìm thấy nó rồi.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"There\'s only one notepad in here.\", \"vi\": \"Trong này chỉ có một cuốn sổ ghi chép mà thôi.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Yi-Seul Kwak (1:25 P.M.)\", \"vi\": \"Yi-Seul Kwak (13 giờ 25 phút)\", \"type\": \"metadata\", \"doc_index\": 8, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"That\'s definitely not enough!\", \"vi\": \"Điều đó chắc chắn là chưa đủ!\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I\'m glad I checked.\", \"vi\": \"Tôi rất mừng vì đã kiểm tra.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Thank you, Stacy!\", \"vi\": \"Xin cảm ơn, Stacy!\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = '82893461-b15f-4ed0-b7be-8d78a7471b22';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Rainy To Move Headquarters\", \"vi\": \"Rainy sẽ chuyển trụ sở chính\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"DADE (July 11)—Rainy LLC announced yesterday that it is moving its headquarters to Dade.\", \"vi\": \"DADE (ngày 11 tháng 7) — Công ty Rainy LLC hôm qua đã thông báo rằng họ sẽ chuyển trụ sở chính đến Dade.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"A data storage and analytics firm currently based in Salt Creek, Rainy has clients that include some of the country\'s largest credit card companies, online retailers, and software providers.\", \"vi\": \"Rainy, một công ty chuyên về lưu trữ và phân tích dữ liệu hiện có trụ sở tại Salt Creek, có danh sách khách hàng bao gồm một số công ty thẻ tín dụng, nhà bán lẻ trực tuyến và nhà cung cấp phần mềm lớn nhất cả nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Rainy helps these businesses manage and understand their customer data.\", \"vi\": \"Rainy hỗ trợ các doanh nghiệp này quản lý và nắm bắt dữ liệu khách hàng của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Rainy is not planning to close its current offices in Salt Creek.\", \"vi\": \"Rainy hiện không có kế hoạch đóng cửa các văn phòng hiện tại của mình tại Salt Creek.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"However, the Dade location will become its new base of operations, as several members of its executive team will work there.\", \"vi\": \"Tuy nhiên, văn phòng tại Dade sẽ trở thành trụ sở hoạt động mới của công ty, do một số thành viên trong ban lãnh đạo sẽ làm việc tại đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The company\'s chief executive officer and chief financial officer will relocate to Dade along with approximately 50 percent of the company\'s workforce.\", \"vi\": \"Giám đốc điều hành và Giám đốc tài chính của công ty sẽ chuyển đến Dade cùng với khoảng 50% lực lượng lao động của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The office of Rainy\'s chief technology officer will remain in Salt Creek, as will the account management team.\", \"vi\": \"Văn phòng của Giám đốc Công nghệ tại Rainy sẽ vẫn đặt tại Salt Creek, cũng như đội ngũ quản lý khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The company\'s new Dade offices are located at 12 Glacier Parkway.\", \"vi\": \"Văn phòng mới của công ty tại Dade tọa lạc tại số 12 Glacier Parkway.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '82c2c501-8b4c-4930-aca7-9978fbc8f997';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"SALINAS (3 March)—Atwell Power has finalized the sites for a large-scale renewable energy project in the region that would provide electricity to thousands of homes and businesses.\", \"vi\": \"SALINAS (ngày 3 tháng 3) — Công ty Atwell Power đã chốt danh sách các địa điểm cho một dự án năng lượng tái tạo quy mô lớn tại khu vực này, dự kiến sẽ cung cấp điện cho hàng nghìn hộ gia đình và doanh nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The project will involve the installation of wind turbines at four locations.\", \"vi\": \"Dự án này sẽ bao gồm việc lắp đặt các tuabin gió tại bốn địa điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"These sites have already been inspected for environmental considerations and have received the necessary permits from the state and federal governments.\", \"vi\": \"Các địa điểm này đã được kiểm tra về các khía cạnh môi trường và đã nhận được các giấy phép cần thiết từ chính quyền tiểu bang và liên bang.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Atwell Power will construct the turbines and substations themselves, but construction of the transmission lines linking the electricity output to the distribution grid will be handled by a third party.\", \"vi\": \"Công ty Atwell Power sẽ tự tiến hành xây dựng các tuabin và trạm biến áp, tuy nhiên, việc xây dựng các đường dây truyền tải kết nối nguồn điện sản xuất được với lưới phân phối sẽ do một đơn vị thứ ba đảm nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"A spokesperson said that Atwell Power\'s project will create numerous jobs for highly skilled workers in the area, and it will begin advertising for these positions from early next month.\", \"vi\": \"Một phát ngôn viên cho biết dự án của Atwell Power sẽ tạo ra rất nhiều việc làm cho những lao động có tay nghề cao trong khu vực, và công ty sẽ bắt đầu đăng tuyển các vị trí này từ đầu tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Site - Number of Turbines - Annual Generation (per turbine)\", \"vi\": \"Địa điểm - Số lượng tuabin - Sản lượng điện hàng năm (trên mỗi tuabin)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Brunswick - 80 - 5.8 million kilowatt-hours\", \"vi\": \"Brunswick - 80 - 5,8 triệu kilowatt-giờ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Crafton - 60 - 5.6 million kilowatt-hours\", \"vi\": \"Crafton - 60 - 5,6 triệu kilowatt-giờ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Ruckman Valley - 45 - 5.9 million kilowatt-hours\", \"vi\": \"Thung lũng Ruckman - 45 - 5,9 triệu kilowatt-giờ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Valdosta - 75 - 6.1 million kilowatt-hours\", \"vi\": \"Valdosta - 75 - 6,1 triệu kilowatt-giờ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To: Alison Huber <a.huber@atwellpower.com>\", \"vi\": \"Gửi tới: Alison Huber <a.huber@atwellpower.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"From: Guillermo Miranda <g.miranda@atwellpower.com>\", \"vi\": \"Từ: Guillermo Miranda <g.miranda@atwellpower.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Date: May 7\", \"vi\": \"Ngày: 7 tháng 5\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Subject: Wind turbine project\", \"vi\": \"Chủ đề: Dự án tuabin gió\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Dear Ms. Huber,\", \"vi\": \"Kính gửi bà Huber,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I\'d like to follow up on the issue we discussed at last week\'s meeting regarding the Crafton site.\", \"vi\": \"Tôi xin được tiếp tục làm rõ vấn đề mà chúng ta đã thảo luận tại cuộc họp tuần trước liên quan đến khu đất Crafton.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"As the public roadways are not suitable for the transportation of our equipment, we will need to construct a temporary access road off of Highway 162.\", \"vi\": \"Do các tuyến đường công cộng không phù hợp để vận chuyển thiết bị của chúng tôi, chúng tôi sẽ cần phải xây dựng một con đường tiếp cận tạm thời nối với Quốc lộ 162.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Please note that due to the ground composition there, stability checks will need to be carried out once every three months rather than twice a year.\", \"vi\": \"Xin lưu ý rằng do đặc điểm thành phần đất tại khu vực đó, việc kiểm tra độ ổn định sẽ cần được thực hiện mỗi ba tháng một lần thay vì hai lần mỗi năm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"As for the outside contractor portion of the project, we have accepted a bid from Bassell Inc., and I will work on the contract this week.\", \"vi\": \"Về phần dự án do nhà thầu bên ngoài thực hiện, chúng tôi đã chấp nhận đề xuất thầu từ Công ty Bassell Inc., và tôi sẽ tiến hành soạn thảo hợp đồng trong tuần này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I will update you again soon,\", \"vi\": \"Tôi sẽ sớm cập nhật thông tin cho quý vị một lần nữa,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Guillermo Miranda\", \"vi\": \"Guillermo Miranda\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '83082208-ca7d-441f-a6b6-284c3095701e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"April 5\", \"vi\": \"Ngày 5 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"SOIL CONTAMINATION REPORT\", \"vi\": \"BÁO CÁO VỀ Ô NHIỄM ĐẤT\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Client: Gould Manufacturing\", \"vi\": \"Khách hàng: Gould Manufacturing\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Testing Performed By: Soil-Check Solutions\", \"vi\": \"Thử nghiệm được thực hiện bởi: Soil-Check Solutions\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Testing Dates: March 3, May 5, July 2, September 5\", \"vi\": \"Các ngày thi: ngày 3 tháng 3, ngày 5 tháng 5, ngày 2 tháng 7, ngày 5 tháng 9\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Process: Samples were collected from various points at Site 1 (Lancaster), Site 2 (Canton), and Site 3 (Brockway) at a depth of 6 cm and 10 cm.\", \"vi\": \"Quy trình: Các mẫu được thu thập từ nhiều điểm khác nhau tại Địa điểm 1 (Lancaster), Địa điểm 2 (Canton) và Địa điểm 3 (Brockway) ở độ sâu 6 cm và 10 cm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The soil was tested for contaminants, and the levels were compared to assess changes over time.\", \"vi\": \"Mẫu đất đã được kiểm tra để xác định các chất gây ô nhiễm, và các mức độ ô nhiễm này đã được so sánh nhằm đánh giá những thay đổi theo thời gian.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Following the initial test, micro-organisms were introduced at all sites.\", \"vi\": \"Sau đợt thử nghiệm ban đầu, các vi sinh vật đã được đưa vào tại tất cả các địa điểm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Preliminary Findings and Recommended Actions: Contamination levels at Site 1 dropped significantly.\", \"vi\": \"Kết quả sơ bộ và các biện pháp được đề xuất: Mức độ ô nhiễm tại Địa điểm 1 đã giảm đáng kể.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"No further action is needed.\", \"vi\": \"Không cần thực hiện thêm bất kỳ hành động nào.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"At Site 2, a soil stabilization formula should be injected into the ground.\", \"vi\": \"Tại Địa điểm 2, cần bơm hỗn hợp ổn định đất vào lòng đất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"This will dry into a hardened solid, which can then be removed by specialized equipment.\", \"vi\": \"Chất này sẽ khô lại thành một chất rắn cứng, sau đó có thể được loại bỏ bằng thiết bị chuyên dụng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Micro-organisms should be reapplied.\", \"vi\": \"Cần bón lại các vi sinh vật.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"At Site 3, the grass and shrubs should be pulled from the soil, and micro-organisms should be reapplied.\", \"vi\": \"Tại Vị trí 3, cần nhổ sạch cỏ và cây bụi khỏi đất, đồng thời bón lại vi sinh vật.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '8319d80d-ad20-4c91-88df-4de095d714f3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"January 17\", \"vi\": \"Ngày 17 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Kenji Davis\", \"vi\": \"Kenji Davis\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"26 Peartree Lane\", \"vi\": \"26 Peartree Lane\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Baltimore, MD 21205\", \"vi\": \"Baltimore, MD 21205\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Davis,\", \"vi\": \"Ông Davis kính mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"It was a pleasure to talk with you at the Annual Model Train Show in Baltimore earlier this month.\", \"vi\": \"Thật là một vinh hạnh khi được trò chuyện với ông tại Triển lãm Tàu mô hình Thường niên ở Baltimore vào đầu tháng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I ____139____ by the high quality of the antique trains that you had on display.\", \"vi\": \"Tôi ____139____ bởi chất lượng cao của những đoàn tàu cổ mà ông trưng bày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [139]}, {\"en\": \"You mentioned that you might want to sell several sets of antique trains.\", \"vi\": \"Ông đã đề cập rằng ông có thể muốn bán một số bộ tàu cổ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Faremount Antique Auctions would be an ideal ____140____ for you.\", \"vi\": \"Công ty Đấu giá Đồ cổ Faremount sẽ là một ____140____ lý tưởng dành cho ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [140]}, {\"en\": \"Twice a year we hold an online auction of antique toys that attracts bids from model train collectors from around the world.\", \"vi\": \"Hai lần một năm, chúng tôi tổ chức một phiên đấu giá trực tuyến đồ chơi cổ thu hút các giá thầu từ những nhà sưu tập tàu mô hình trên khắp thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Our most recent auction was in November.\", \"vi\": \"Phiên đấu giá gần đây nhất của chúng tôi diễn ra vào tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"____141____.\", \"vi\": \"____141____.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [141]}, {\"en\": \"I believe you will find that items in our auction sold for higher prices ____142____ similar items did at other sites.\", \"vi\": \"Tôi tin rằng ông sẽ thấy các mặt hàng trong phiên đấu giá của chúng tôi được bán với giá cao hơn ____142____ các mặt hàng tương tự tại các trang web khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [142]}, {\"en\": \"Our next auction will be held May 21–22.\", \"vi\": \"Phiên đấu giá tiếp theo của chúng tôi sẽ được tổ chức vào ngày 21–22 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Let me know if you are interested in participating.\", \"vi\": \"Hãy cho tôi biết nếu ông quan tâm đến việc tham gia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Justine Garcia, Faremount Antique Auctions\", \"vi\": \"Justine Garcia, Công ty Đấu giá Đồ cổ Faremount\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '833ed21b-3b44-41e5-9d33-073d2550f35c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Community Project to Showcase Pottersville Artists\", \"vi\": \"Dự án cộng đồng nhằm giới thiệu các nghệ sĩ tại Pottersville\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"By Laurence du Bois\", \"vi\": \"Tác giả: Laurence du Bois\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"POTTERSVILLE (May 21)—At the opening of this year\'s Small Business Fair in Pottersville Central Park yesterday, the Pottersville Chamber of Commerce announced Images of Success, a community initiative that seeks to promote Pottersville businesses by way of public art.\", \"vi\": \"POTTERSVILLE (ngày 21 tháng 5) — Tại lễ khai mạc Hội chợ Doanh nghiệp Nhỏ năm nay diễn ra hôm qua tại Công viên Trung tâm Pottersville, Phòng Thương mại Pottersville đã công bố sáng kiến cộng đồng mang tên “Hình ảnh Thành công” (Images of Success), nhằm quảng bá các doanh nghiệp tại Pottersville thông qua nghệ thuật công cộng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Through the project, local artists will work with area business owners to create original murals on storefronts throughout the city.\", \"vi\": \"Thông qua dự án này, các nghệ sĩ địa phương sẽ hợp tác với các chủ doanh nghiệp trong khu vực để sáng tạo những bức tranh tường độc đáo trên các mặt tiền cửa hàng khắp thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"To apply, business owners must submit a description of their business\'s role in the community and document that their business has been in its current location for at least two years.\", \"vi\": \"Để nộp đơn, các chủ doanh nghiệp phải cung cấp bản mô tả về vai trò của doanh nghiệp mình trong cộng đồng và chứng minh rằng doanh nghiệp đã hoạt động tại địa điểm hiện tại ít nhất hai năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Artists interested in participating must complete an application in which they describe their connection to Pottersville and submit samples of their own original artwork.\", \"vi\": \"Các nghệ sĩ quan tâm đến việc tham gia cần điền vào đơn đăng ký, trong đó nêu rõ mối liên hệ của mình với Pottersville và gửi kèm các mẫu tác phẩm nghệ thuật gốc do chính họ sáng tác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Both business owners and artists should submit applications to Timothy Freel at tfreel@pottersvillecoc.gov by June 15.\", \"vi\": \"Cả các chủ doanh nghiệp lẫn các nghệ sĩ đều cần gửi đơn đăng ký đến ông Timothy Freel qua địa chỉ email tfreel@pottersvillecoc.gov trước ngày 15 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The city will reimburse artists for approved supplies up to a limit of $150.\", \"vi\": \"Thành phố sẽ hoàn trả chi phí cho các nghệ sĩ đối với các vật tư đã được phê duyệt, với mức tối đa là 150 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"To: Timothy Freel\", \"vi\": \"Kính gửi: Timothy Freel\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"From: Haruka Goto\", \"vi\": \"Từ: Haruka Goto\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Date: June 24\", \"vi\": \"Ngày: 24 tháng 6\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Subject: Images of Success inquiry\", \"vi\": \"Chủ đề: Yêu cầu cung cấp thông tin về “Hình ảnh của sự thành công”\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Draft #2\", \"vi\": \"Tệp đính kèm: 📎 Bản nháp số 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Dear Mr. Freel,\", \"vi\": \"Kính gửi ông Freel,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"It was a pleasure meeting with you earlier this week at Jam Café to talk about the design for the Images of Success mural project.\", \"vi\": \"Thật là một niềm vui khi được gặp quý vị vào đầu tuần này tại Jam Café để trao đổi về thiết kế cho dự án tranh tường “Hình ảnh Thành công”.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I hadn\'t been to Jam Café since it reopened, and it was great to see the finished renovations.\", \"vi\": \"Tôi chưa từng ghé thăm Jam Café kể từ khi quán này mở cửa trở lại, và thật tuyệt vời khi được chiêm ngưỡng kết quả sau khi hoàn tất việc cải tạo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"In fact, the owner of the café recently bought one of my paintings to display in the café.\", \"vi\": \"Thực ra, chủ quán cà phê gần đây đã mua một trong những bức tranh của tôi để trưng bày tại quán.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"As you suggested, I have adjusted the color scheme to include only the colors from Jam Café\'s interior.\", \"vi\": \"Theo đề xuất của quý vị, tôi đã điều chỉnh bảng màu để chỉ bao gồm các màu có trong nội thất của Jam Café.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Please let me know as soon as possible whether you would like me to make additional changes.\", \"vi\": \"Xin vui lòng cho tôi biết càng sớm càng tốt xem quý vị có muốn tôi thực hiện thêm những thay đổi nào khác hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Haruka Goto\", \"vi\": \"Haruka Goto\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Product - Unit Price - Quantity - Total Price\", \"vi\": \"Sản phẩm - Giá đơn vị - Số lượng - Tổng giá\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Soft green spray paint, 18 oz. can - $11.99 - 2 - $23.98\", \"vi\": \"Sơn xịt màu xanh nhạt, lon 18 oz. - 11,99 USD - 2 lon - 23,98 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Emerald green paint, ½ gallon - $18.99 - 1 - $18.99\", \"vi\": \"Sơn màu xanh ngọc lục bảo, ½ gallon - 18,99 USD - 1 - 18,99 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Forest green paint, 1 gallon - $34.99 - 1 - $34.99\", \"vi\": \"Sơn màu xanh lá rừng, 1 gallon - 34,99 USD - 1 - 34,99 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Set of paintbrushes - $24.99 - 1 - $24.99\", \"vi\": \"Bộ cọ vẽ - 24,99 USD - 1 - 24,99 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Total (including tax) - $111.14\", \"vi\": \"Tổng cộng (đã bao gồm thuế) - 111,14 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Approved by: T. Freel - Approval Date: July 3\", \"vi\": \"Được phê duyệt bởi: T. Freel - Ngày phê duyệt: 3 tháng 7\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Pottersville Chamber of Commerce Reimbursement Form\", \"vi\": \"Mẫu đơn xin hoàn trả chi phí của Phòng Thương mại Pottersville\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Complete the entire form and attach a record of the purchase.\", \"vi\": \"Xin vui lòng điền đầy đủ thông tin vào mẫu đơn và đính kèm chứng từ mua hàng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Allow two weeks for processing.\", \"vi\": \"Quý vị vui lòng dành hai tuần để hoàn tất thủ tục.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Name: Haruka Goto\", \"vi\": \"Họ tên: Haruka Goto\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Date: June 25\", \"vi\": \"Ngày: 25 tháng 6\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Event: Images of Success\", \"vi\": \"Sự kiện: Những hình ảnh về thành công\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Description:\", \"vi\": \"Mô tả:\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Supplies purchased at Pottersville Art Supply for Images of Success mural project.\", \"vi\": \"Các vật tư được mua tại cửa hàng Pottersville Art Supply phục vụ cho dự án tranh tường “Images of Success”.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Copy of receipt dated June 24 attached.\", \"vi\": \"Kèm theo đây là bản sao biên lai có ngày 24 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}]' WHERE `id` = '8345c770-6836-407d-8a12-954a2c25f988';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: John Fukiyama <john.fukiyama6775@xmail.ca>\", \"vi\": \"Gửi tới: John Fukiyama <john.fukiyama6775@xmail.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Stephanie Acro <sacro@salvadorfashionassociates.ca>\", \"vi\": \"Từ: Stephanie Acro <sacro@salvadorfashionassociates.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 18 November\", \"vi\": \"Ngày: 18 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Search committee\", \"vi\": \"Chủ đề: Ủy ban tuyển chọn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Confidentiality Agreement\", \"vi\": \"Tài liệu đính kèm: Thỏa thuận bảo mật\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Fukiyama:\", \"vi\": \"Kính gửi ông Fukiyama:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am writing to gauge your interest in becoming a part of a search committee for the newly vacated Senior Director of Graphic Design position here at Salvador Fashion Associates.\", \"vi\": \"Tôi viết thư này nhằm tìm hiểu xem quý vị có quan tâm đến việc tham gia vào ủy ban tuyển dụng cho vị trí Giám đốc cấp cao phụ trách Thiết kế Đồ họa vừa có chỗ trống tại Salvador Fashion Associates hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As you may have heard, Jake Harris left our company last month to start his own business, leaving us without anyone to head our Graphic Design department.\", \"vi\": \"Có lẽ quý vị đã nghe nói, tháng trước, Jake Harris đã rời công ty chúng tôi để thành lập doanh nghiệp riêng, khiến chúng tôi hiện không còn ai đảm nhiệm vị trí Trưởng phòng Thiết kế Đồ họa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As someone who held this role prior to your retirement four years ago, you know exactly what knowledge and skills are needed for this position, making you an ideal candidate for our search committee.\", \"vi\": \"Với tư cách là người từng đảm nhiệm chức vụ này trước khi quý vị nghỉ hưu cách đây bốn năm, quý vị hiểu rõ những kiến thức và kỹ năng cần thiết cho vị trí này, điều này khiến quý vị trở thành ứng viên lý tưởng cho ủy ban tuyển chọn của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Sheila Mendez, our Executive Director of Marketing, and I will also be part of the committee conducting this search.\", \"vi\": \"Bà Sheila Mendez, Giám đốc Điều hành Bộ phận Tiếp thị của chúng tôi, và tôi cũng sẽ tham gia vào ủy ban phụ trách quá trình tuyển dụng này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"If you agree to be a part of the committee, please sign and return the attached confidentiality agreement.\", \"vi\": \"Nếu quý vị đồng ý tham gia vào ban tổ chức, xin vui lòng ký tên và gửi lại bản thỏa thuận bảo mật đính kèm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"At that point, I will send you the applications with their respective résumés and a timeline for the hiring process.\", \"vi\": \"Khi đó, tôi sẽ gửi cho quý vị hồ sơ ứng tuyển kèm theo sơ yếu lý lịch của từng ứng viên cùng với lịch trình của quy trình tuyển dụng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"For your time and effort, we will compensate you at the standard rate for external consultants.\", \"vi\": \"Để đền đáp cho thời gian và công sức của quý vị, chúng tôi sẽ chi trả theo mức thù lao tiêu chuẩn dành cho các chuyên gia tư vấn bên ngoài.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please let me know your answer as soon as possible.\", \"vi\": \"Xin vui lòng cho tôi biết câu trả lời của quý vị càng sớm càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"It would be great to work with you again.\", \"vi\": \"Thật tuyệt vời nếu có cơ hội được hợp tác cùng quý vị một lần nữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Stephanie Acro\", \"vi\": \"Stephanie Acro\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Director of Human Resources\", \"vi\": \"Giám đốc Nhân sự\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Salvador Fashion Associates, Toronto\", \"vi\": \"Salvador Fashion Associates, Toronto\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '83a05fcc-e89e-4103-ba68-2992e7f235b8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Lado Shopping Center\", \"vi\": \"Trung tâm thương mại Lado\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Property Highlights\", \"vi\": \"Điểm nổi bật của bất động sản\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Area Attractions\", \"vi\": \"Các điểm tham quan trong khu vực\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Rebbly Development is pleased to announce the approval of a new project, the Lado Shopping Center in Springfield.\", \"vi\": \"Công ty Rebbly Development hân hạnh thông báo về việc dự án mới, Trung tâm thương mại Lado tại Springfield, đã được phê duyệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"This rapidly expanding city is conveniently located near the capital, and Lado Shopping Center is set to deliver an excellent shopping experience for all.\", \"vi\": \"Thành phố đang phát triển nhanh chóng này tọa lạc tại vị trí thuận tiện gần thủ đô, và Trung tâm thương mại Lado hứa hẹn sẽ mang đến trải nghiệm mua sắm tuyệt vời cho tất cả mọi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We expect to finish construction next year.\", \"vi\": \"Chúng tôi dự kiến sẽ hoàn thành công trình vào năm tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"150,000 square feet of retail and office space\", \"vi\": \"150.000 feet vuông diện tích dành cho bán lẻ và văn phòng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"$25 per square foot (ground floor)\", \"vi\": \"25 đô la mỗi foot vuông (tầng trệt)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"$20 per square foot (upper floors)\", \"vi\": \"20 đô la mỗi foot vuông (các tầng trên)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Space available for lease or rent\", \"vi\": \"Có mặt bằng cho thuê\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Space can be custom-built in consultation with Rebbly Development\", \"vi\": \"Không gian có thể được thiết kế theo yêu cầu sau khi tham vấn với Rebbly Development\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Located near the aquarium, several parks, and the river\", \"vi\": \"Nằm gần thủy cung, một số công viên và con sông\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Two major access roads: Hemley Boulevard and Route 82, with additional connection to Highway 35 to be completed in five years\", \"vi\": \"Hai tuyến đường chính dẫn vào khu vực: Đại lộ Hemley và Quốc lộ 82, cùng với tuyến đường nối thêm với Đường cao tốc 35 dự kiến sẽ hoàn thành trong vòng năm năm tới\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"4,000 new homes to be built in Springfield within three years\", \"vi\": \"4.000 căn nhà mới sẽ được xây dựng tại Springfield trong vòng ba năm tới\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Nearby parking structure with ports for electric vehicles to be completed within two years\", \"vi\": \"Công trình bãi đỗ xe gần đó, được trang bị các trạm sạc dành cho xe điện, dự kiến sẽ hoàn thành trong vòng hai năm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Movie theaters, amusement park, and other attractions nearby\", \"vi\": \"Các rạp chiếu phim, công viên giải trí và các điểm tham quan khác trong khu vực lân cận\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '83c0db4c-b61b-4983-9f23-ba2a1a0048d7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mini-pure: Portable Air Purifier\", \"vi\": \"Mini-pure: Máy lọc không khí cầm tay\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Mountain Clear Air, a leader in air purifying devices, introduces Mini-pure, the first portable air purifier of its kind.\", \"vi\": \"Mountain Clear Air, một trong những thương hiệu hàng đầu trong lĩnh vực thiết bị lọc không khí, xin giới thiệu Mini-pure – máy lọc không khí cầm tay đầu tiên thuộc loại này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Developed by leading environmentalists and engineers, Mini-pure cleans air by using negative ions!\", \"vi\": \"Được phát triển bởi các chuyên gia môi trường và kỹ sư hàng đầu, Mini-pure làm sạch không khí bằng cách sử dụng các ion âm!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Plus, it\'s small and convenient, so you can take it with you wherever you go.\", \"vi\": \"Hơn nữa, sản phẩm này nhỏ gọn và tiện lợi, nên quý vị có thể mang theo bên mình bất cứ nơi đâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Environmentally friendly and effective\", \"vi\": \"Thân thiện với môi trường và hiệu quả\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Fits easily into a purse or briefcase\", \"vi\": \"Dễ dàng bỏ vừa vào túi xách hoặc cặp tài liệu\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Reduces pollutants and allergens\", \"vi\": \"Giúp giảm thiểu các chất ô nhiễm và các tác nhân gây dị ứng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Charges quickly with any standard phone charger\", \"vi\": \"Sạc nhanh bằng bất kỳ bộ sạc điện thoại tiêu chuẩn nào\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"For use at home, in the office, or anywhere\", \"vi\": \"Dùng tại nhà, tại văn phòng hoặc ở bất cứ đâu\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Find out more at Minipureairclean.com.\", \"vi\": \"Vui lòng truy cập Minipureairclean.com để tìm hiểu thêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '83c19a42-03c0-4f12-af79-288f4f9adb55';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Name - Size (cm) - Shipping Weight - Quantity Available (today) - Quantity Available (in 30 days) - Quantity Available (in 60 days)\", \"vi\": \"Tên - Kích thước (cm) - Trọng lượng vận chuyển - Số lượng còn hàng (hôm nay) - Số lượng còn hàng (trong 30 ngày) - Số lượng còn hàng (trong 60 ngày)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Artemis - 190 x 280 - 13 kg - 30 - 60 - 0\", \"vi\": \"Artemis - 190 x 280 - 13 kg - 30 - 60 - 0\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Hera - 190 x 280 - 14 kg - 16 - 20 - 0\", \"vi\": \"Hera - 190 x 280 - 14 kg - 16 - 20 - 0\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Janus - 160 x 230 - 11 kg - 0 - 0 - 20\", \"vi\": \"Janus - 160 x 230 - 11 kg - 0 - 0 - 20\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Iris - 120 x 170 - 9 kg - 10 - 15 - 15\", \"vi\": \"Iris - 120 x 170 - 9 kg - 10 - 15 - 15\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"TYCHE FINE CARPETS—Pleiades Collection\", \"vi\": \"TYCHE FINE CARPETS — Bộ sưu tập Pleiades\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Product Availability (updated daily)\", \"vi\": \"Tình trạng hàng hóa (cập nhật hàng ngày)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To: Frieda Zuckerman\", \"vi\": \"Kính gửi: Bà Frieda Zuckerman\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"From: Miles Sorrell\", \"vi\": \"Từ: Miles Sorrell\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Date: February 5\", \"vi\": \"Ngày: 5 tháng 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Subject: Logistical arrangements\", \"vi\": \"Chủ đề: Các công tác hậu cần\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Photos\", \"vi\": \"Tệp đính kèm: 📎 Hình ảnh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Dear Ms. Zuckerman:\", \"vi\": \"Kính gửi Bà Zuckerman:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I regret to inform you that Tyche Fine Carpets, the supplier we selected for the carpets in The Pavel Hotel\'s lobby and lounge areas, will not have our chosen pattern available until after the hotel\'s anticipated opening date of March 1.\", \"vi\": \"Tôi rất tiếc phải thông báo với quý vị rằng Tyche Fine Carpets, nhà cung cấp mà chúng tôi đã lựa chọn để cung cấp thảm cho sảnh và khu vực phòng khách của Khách sạn The Pavel, sẽ không thể cung cấp mẫu thảm mà chúng tôi đã chọn cho đến sau ngày khai trương dự kiến của khách sạn là ngày 1 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Attached are photographs of several alternative selections that I believe will work well with the décor.\", \"vi\": \"Kèm theo đây là một số bức ảnh về các lựa chọn thay thế mà tôi tin rằng sẽ rất phù hợp với phong cách trang trí.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"They are all made of the same material as the previous selection, and the prices are comparable.\", \"vi\": \"Tất cả các sản phẩm này đều được làm từ cùng loại chất liệu với các sản phẩm đã giới thiệu trước đó, và mức giá cũng tương đương.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"With the grand opening less than a month away, I need a decision from you as soon as possible.\", \"vi\": \"Chỉ còn chưa đầy một tháng nữa là đến ngày khai trương, tôi cần quý vị đưa ra quyết định càng sớm càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Even with this last-minute change, I am certain that The Pavel Hotel will provide the ambience we have set out to create.\", \"vi\": \"Dù có sự thay đổi vào phút chót này, tôi vẫn tin chắc rằng Khách sạn Pavel sẽ mang đến bầu không khí mà chúng tôi đã định hướng xây dựng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Miles Sorrell\", \"vi\": \"Miles Sorrell\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Pavel Hotel Open\", \"vi\": \"Khách sạn Pavel Open\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"by Lavonne Coe\", \"vi\": \"của Lavonne Coe\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"(Centerville—March 2) Former city court judge Mildred Simpson joined owner Patrice Snell yesterday to celebrate the opening of The Pavel Hotel in downtown Centerville, between the library and the visitors center.\", \"vi\": \"(Centerville — ngày 2 tháng 3) Hôm qua, cựu thẩm phán tòa án thành phố Mildred Simpson đã cùng chủ sở hữu Patrice Snell tham dự lễ khai trương Khách sạn The Pavel tại trung tâm thành phố Centerville, nằm giữa thư viện và trung tâm du khách.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Once the city\'s courthouse and Ms. Simpson\'s workplace, the existing structure had been vacant for the past nine years.\", \"vi\": \"Từng là tòa án thành phố và nơi làm việc của bà Simpson, công trình hiện tại đã bị bỏ trống trong suốt chín năm qua.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Now the space boasts 34 elegant rooms, an inviting lounge with a fireplace, and a gorgeous lobby.\", \"vi\": \"Hiện nay, nơi đây tự hào sở hữu 34 phòng nghỉ trang nhã, một phòng khách ấm cúng có lò sưởi và một sảnh đón khách lộng lẫy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"An on-site café is expected to open next month.\", \"vi\": \"Một quán cà phê ngay trong khuôn viên dự kiến sẽ khai trương vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"The interior, designed by Miles Sorrell, retains the old features of the building, such as expansive windows and high ceilings, while creating a warm and inviting space.\", \"vi\": \"Khu vực nội thất, do Miles Sorrell thiết kế, vẫn giữ nguyên những nét đặc trưng vốn có của tòa nhà, chẳng hạn như các ô cửa sổ rộng mở và trần nhà cao, đồng thời tạo nên một không gian ấm cúng và thân thiện.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '83cbebb7-e671-474f-bd53-44d244fa0eed';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Regal Properties\", \"vi\": \"Regal Properties\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"34 Weston Road, Halifax NS B3J 3P4\", \"vi\": \"34 Weston Road, Halifax, Nova Scotia, B3J 3P4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"January 3\", \"vi\": \"Ngày 3 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Dear District Council Members,\", \"vi\": \"Kính gửi các thành viên Hội đồng Quận,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"My firm is interested in purchasing the building at 1210 Prince Street.\", \"vi\": \"Công ty của tôi đang quan tâm đến việc mua lại tòa nhà tọa lạc tại số 1210 đường Prince.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Since this property has been on the market for almost five years, it has fallen into disrepair.\", \"vi\": \"Do bất động sản này đã được rao bán trên thị trường gần năm năm nay, nên hiện tại nó đã xuống cấp nghiêm trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Regal Properties is willing to invest what is necessary to update the building.\", \"vi\": \"Regal Properties sẵn sàng đầu tư mọi khoản cần thiết để cải tạo tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In addition, we would like to convert three of the apartment units on the ground floor facing the street into space for businesses.\", \"vi\": \"Bên cạnh đó, chúng tôi mong muốn chuyển đổi ba căn hộ ở tầng trệt, hướng ra đường, thành không gian dành cho các hoạt động kinh doanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"However, the property is zoned only for residential use.\", \"vi\": \"Tuy nhiên, khu đất này chỉ được quy hoạch dành cho mục đích nhà ở.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Would you consider rezoning the property to allow for mixed residential and business use?\", \"vi\": \"Quý vị có cân nhắc việc điều chỉnh quy hoạch khu đất này để cho phép sử dụng kết hợp giữa mục đích dân cư và thương mại hay không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"John Stone\", \"vi\": \"John Stone\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"John Stone, Owner\", \"vi\": \"John Stone, Chủ sở hữu\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"District Council of Halifax\\nMeeting Minutes of January 21\", \"vi\": \"Hội đồng Quận Halifax\\nBiên bản cuộc họp ngày 21 tháng 1\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"In attendance: Mayor Stuart Kaplan and all council members\", \"vi\": \"Các đại biểu có mặt: Thị trưởng Stuart Kaplan và toàn thể các thành viên Hội đồng thành phố\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Old business\", \"vi\": \"Các vấn đề còn tồn đọng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"➤ Council member Amanda Mueller reported satisfactory progress on the Wells Park cleanup project.\", \"vi\": \"➤ Bà Amanda Mueller, thành viên Hội đồng, đã báo cáo về những tiến triển khả quan trong dự án dọn dẹp Công viên Wells.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"➤ Council member Harold Glass submitted a final version of next year\'s budget.\", \"vi\": \"➤ Ông Harold Glass, thành viên Hội đồng, đã đệ trình bản dự thảo cuối cùng của ngân sách cho năm tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The proposed budget was unanimously approved.\", \"vi\": \"Dự toán ngân sách đã được thông qua với sự nhất trí của tất cả các thành viên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"New business\", \"vi\": \"Hoạt động kinh doanh mới\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Community resident and building manager Carla Phillips spoke to express opposition to the rezoning of 1210 Prince Street under consideration by the council.\", \"vi\": \"Bà Carla Phillips, một cư dân trong cộng đồng kiêm quản lý tòa nhà, đã phát biểu bày tỏ sự phản đối đối với việc điều chỉnh quy hoạch khu đất số 1210 Prince Street hiện đang được Hội đồng xem xét.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Ms. Phillips is concerned that the increased pedestrian and vehicular traffic will make the street too crowded.\", \"vi\": \"Bà Phillips lo ngại rằng việc gia tăng lưu lượng người đi bộ và phương tiện giao thông sẽ khiến con đường trở nên quá đông đúc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"She thinks it will also be difficult for residents of her building, Lighthouse Apartments, located at 1208 Prince Street, to park in the neighborhood.\", \"vi\": \"Bà cho rằng cư dân của tòa nhà nơi bà sinh sống, Lighthouse Apartments, tọa lạc tại số 1208 đường Prince, cũng sẽ gặp khó khăn khi tìm chỗ đỗ xe trong khu vực lân cận.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"The council agreed to consider the zoning issue at their February monthly meeting to give additional residents on Prince Street an opportunity to voice their opinions.\", \"vi\": \"Hội đồng đã nhất trí xem xét vấn đề quy hoạch sử dụng đất tại cuộc họp thường kỳ tháng Hai nhằm tạo cơ hội cho thêm nhiều cư dân trên đường Prince Street bày tỏ ý kiến của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"You can have it all!\", \"vi\": \"Quý vị hoàn toàn có thể có được tất cả!\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Newly renovated apartments with one or two bedrooms\", \"vi\": \"Các căn hộ vừa được cải tạo lại, có một hoặc hai phòng ngủ\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Contemporary upscale kitchens\", \"vi\": \"Những căn bếp cao cấp theo phong cách hiện đại\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Triple-pane insulated windows\", \"vi\": \"Cửa sổ cách nhiệt ba lớp kính\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Coffee shop, dry cleaners, and convenience store on street level\", \"vi\": \"Quán cà phê, tiệm giặt khô và cửa hàng tiện lợi ở tầng trệt\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Expanded parking area exclusively for residents of 1208 and 1210 Prince Street starting in December\", \"vi\": \"Khu vực đỗ xe được mở rộng dành riêng cho cư dân tại các số 1208 và 1210 Prince Street sẽ bắt đầu được áp dụng từ tháng 12\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Enjoy a wonderful lifestyle at 1210 Prince Street!\", \"vi\": \"Hãy tận hưởng một phong cách sống tuyệt vời tại số 1210 Prince Street!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Visit www.lifeonprincestreet.com or call 866-555-0122 for more information.\", \"vi\": \"Vui lòng truy cập www.lifeonprincestreet.com hoặc gọi số 866-555-0122 để biết thêm thông tin.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}]' WHERE `id` = '83d5fa66-7174-4f1b-8cb7-ea021572f8fc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Customers\' Corner\", \"vi\": \"Góc khách hàng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Customers\' Corner is a recurring feature in Atlas Financial Review (AFR) about customer-centric trends in Africa\'s banking industry.\", \"vi\": \"“Góc Khách hàng” là chuyên mục định kỳ trên tạp chí Atlas Financial Review (AFR), tập trung vào các xu hướng lấy khách hàng làm trung tâm trong ngành ngân hàng châu Phi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This installment of the series discusses Sonfaya Mutual\'s business advantage savings account (BASA).\", \"vi\": \"Phần này của loạt bài sẽ đề cập đến tài khoản tiết kiệm mang lại lợi thế kinh doanh (BASA) của Sonfaya Mutual.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Sonfaya Mutual\'s BASA has an annual percentage yield of 2.2 percent, which is 1.6 percent higher than the yield of the business savings account offered by its nearest competitor.\", \"vi\": \"Tài khoản BASA của Sonfaya Mutual có tỷ suất sinh lời hàng năm là 2,2%, cao hơn 1,6% so với tỷ suất sinh lời của tài khoản tiết kiệm doanh nghiệp do đối thủ cạnh tranh gần nhất cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Moreover, it comes with a range of customer privileges, including yearly tax preparation with a certified tax accountant, one-on-one consultations with a dedicated account manager, and financial education programmes, both in-person and online.\", \"vi\": \"Hơn nữa, dịch vụ này còn đi kèm với một loạt các đặc quyền dành cho khách hàng, bao gồm dịch vụ lập hồ sơ khai thuế hàng năm với sự hỗ trợ của kế toán viên thuế được chứng nhận, các buổi tư vấn trực tiếp với chuyên viên quản lý tài khoản riêng, cùng các chương trình giáo dục tài chính, cả trực tiếp lẫn trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Except for the assistance with tax paperwork, these offerings are provided at no expense to BASA holders.\", \"vi\": \"Ngoại trừ dịch vụ hỗ trợ thủ tục thuế, các dịch vụ này được cung cấp miễn phí cho các chủ thẻ BASA.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"A minimum deposit of FRW 100,000 is required to open a BASA, while a monthly administration fee of FRW 1,500 is charged.\", \"vi\": \"Để mở tài khoản BASA, quý khách cần có số tiền gửi tối thiểu là 100.000 FRW; đồng thời, quý khách sẽ phải trả phí quản lý hàng tháng là 1.500 FRW.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"For new BASA holders, the monthly cost is waived for the first six months.\", \"vi\": \"Đối với những người mới sở hữu thẻ BASA, phí hàng tháng sẽ được miễn trong sáu tháng đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"For more details, go to www.sonfayamutual.com/basa.\", \"vi\": \"Để biết thêm chi tiết, quý vị vui lòng truy cập trang web www.sonfayamutual.com/basa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Sonfaya Mutual is headquartered in Kigali, Rwanda, with offices in the countries of Tanzania, Uganda, and Zambia.\", \"vi\": \"Sonfaya Mutual có trụ sở chính tại Kigali, Rwanda, và có các văn phòng tại các quốc gia Tanzania, Uganda và Zambia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"An in-depth article about Sonfaya Mutual\'s origins, growth, and milestones was published in AFR\'s January issue.\", \"vi\": \"Một bài báo phân tích sâu về nguồn gốc, quá trình phát triển và các cột mốc quan trọng của Sonfaya Mutual đã được đăng tải trên số tháng 1 của tạp chí AFR.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Previous issues are at www.atlasfinancialreview.com/archives.\", \"vi\": \"Các số trước đây có tại địa chỉ www.atlasfinancialreview.com/archives.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Send questions about archived matters to archivist@atlasfinancialreview.com.\", \"vi\": \"Vui lòng gửi các câu hỏi liên quan đến các vấn đề đã được lưu trữ đến địa chỉ archivist@atlasfinancialreview.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To: archivist@atlasfinancialreview.com\", \"vi\": \"Gửi tới: archivist@atlasfinancialreview.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"From: ochabinga@mesuradobankofliberia.com.lr\", \"vi\": \"Nguồn: ochabinga@mesuradobankofliberia.com.lr\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Date: 1 November\", \"vi\": \"Ngày: 1 tháng 11\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Subject: Missing AFR issue\", \"vi\": \"Chủ đề: Vấn đề liên quan đến việc thiếu dữ liệu tỷ lệ không khí-nhiên liệu (AFR)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"To Whom It May Concern:\", \"vi\": \"Kính gửi quý vị có liên quan:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I read the article on Sonfaya Mutual\'s BASA in the most recent issue of AFR with interest.\", \"vi\": \"Tôi đã đọc với sự quan tâm bài báo về chương trình BASA của Sonfaya Mutual trên số mới nhất của tạp chí AFR.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Subsequently, I visited your Web site, looking for the previous AFR issue referenced in the article.\", \"vi\": \"Sau đó, tôi đã truy cập trang web của quý vị để tìm số tạp chí AFR trước đó được đề cập trong bài viết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Unfortunately, I could not locate it on the archival page.\", \"vi\": \"Rất tiếc, tôi không thể tìm thấy nó trên trang lưu trữ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Please advise on how I can obtain that back issue.\", \"vi\": \"Kính mong quý vị hướng dẫn cho tôi cách để có thể nhận được số báo cũ đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Odette Chabinga\", \"vi\": \"Odette Chabinga\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Vice President, Mesurado Bank of Liberia\", \"vi\": \"Phó Chủ tịch, Ngân hàng Mesurado của Liberia\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"23 November\", \"vi\": \"Ngày 23 tháng 11\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Ms. Julienne Nirere\", \"vi\": \"Bà Julienne Nirere\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"B.P. 2581\", \"vi\": \"B.P. 2581\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"KIGALI\", \"vi\": \"Kigali\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Dear Ms. Nirere,\", \"vi\": \"Kính gửi bà Nirere,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Thank you for being a valued checking account holder with Sonfaya Mutual for fifteen years.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã là chủ tài khoản thanh toán đáng quý của Sonfaya Mutual trong suốt mười lăm năm qua.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"We are, furthermore, pleased that you strengthened your relationship with us by opening a business advantage savings account (BASA).\", \"vi\": \"Hơn nữa, chúng tôi rất vui mừng khi quý vị đã củng cố mối quan hệ với chúng tôi bằng việc mở tài khoản tiết kiệm ưu đãi dành cho doanh nghiệp (BASA).\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Your checking and savings accounts are now joined, enabling you to transfer money from one account to the other online.\", \"vi\": \"Tài khoản thanh toán và tài khoản tiết kiệm của quý vị hiện đã được liên kết với nhau, giúp quý vị có thể chuyển tiền từ tài khoản này sang tài khoản kia qua mạng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Moreover, if you wish to withdraw funds from your BASA, you can use your debit card at any of our ATMs.\", \"vi\": \"Hơn nữa, nếu quý khách muốn rút tiền từ tài khoản BASA của mình, quý khách có thể sử dụng thẻ ghi nợ tại bất kỳ máy ATM nào của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Finally, our recently launched online stock-trading platform, available to you at no charge, is excellent for allowing investors to manage their finances at their own pace.\", \"vi\": \"Cuối cùng, nền tảng giao dịch chứng khoán trực tuyến mà chúng tôi vừa ra mắt gần đây, được cung cấp miễn phí cho quý vị, là một công cụ tuyệt vời giúp các nhà đầu tư quản lý tài chính theo nhịp độ của riêng mình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Contact our Wealth Management Department for details.\", \"vi\": \"Vui lòng liên hệ với Bộ phận Quản lý Tài sản của chúng tôi để biết thêm chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Philbert Akamanzi\", \"vi\": \"Philbert Akamanzi\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Philbert Akamanzi, Senior Accounts Manager\", \"vi\": \"Philbert Akamanzi, Quản lý Tài khoản Cấp cao\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}]' WHERE `id` = '842ef646-2183-4df2-984b-df5699ff48cd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Clemente Street Lot\", \"vi\": \"Khu đất trên đường Clemente\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"HAYWARD (March 2)—The Hayward City Council is exploring various options for the future of a 5-acre city-owned lot located on Clemente Street.\", \"vi\": \"HAYWARD (ngày 2 tháng 3) — Hội đồng Thành phố Hayward đang xem xét các phương án khác nhau liên quan đến tương lai của một khu đất rộng 5 acre thuộc sở hữu của thành phố, tọa lạc trên đường Clemente.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Bids and proposals are being accepted at this time, with the Greenway Collaborative, a local environmental group, advocating for leaving the lot empty and in the city’s possession.\", \"vi\": \"Hiện tại, các hồ sơ dự thầu và đề xuất đang được tiếp nhận; trong đó, Greenway Collaborative – một tổ chức bảo vệ môi trường địa phương – đang kêu gọi giữ nguyên khu đất trống và để thành phố tiếp tục quản lý khu đất này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Hillview Property Development is interested in purchasing the lot.\", \"vi\": \"Công ty Phát triển Bất động sản Hillview đang quan tâm đến việc mua lô đất này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"It intends to build Marshall Plaza, a small building with space for retail business, and establish a courtyard and a small green area with trees, benches, and flower gardens that would be designated for public use.\", \"vi\": \"Dự án này dự kiến sẽ xây dựng Marshall Plaza – một tòa nhà nhỏ với không gian dành cho các hoạt động kinh doanh bán lẻ – đồng thời quy hoạch một khu sân trong và một khu vực xanh nhỏ với cây cối, ghế đá và vườn hoa, được dành riêng cho công chúng sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"“Our planned combination of retail units and green space is a viable solution for this neighborhood, which is in critical need of revitalization,” said Luoyang Meng, a Hillview Property Development representative.\", \"vi\": \"“Kế hoạch kết hợp các đơn vị bán lẻ với không gian xanh của chúng tôi là một giải pháp khả thi cho khu dân cư này, nơi đang rất cần được phục hồi,” ông Luoyang Meng, đại diện của Công ty Phát triển Bất động sản Hillview, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"“Our company has the resources to create an attractive and thriving retail center as well as the expertise to minimize disruptions to wildlife habitats.\", \"vi\": \"“Công ty chúng tôi có đủ nguồn lực để xây dựng một trung tâm bán lẻ hấp dẫn và sôi động, đồng thời sở hữu chuyên môn cần thiết để giảm thiểu tác động tiêu cực đến môi trường sống của động vật hoang dã.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We hope to have the opportunity to showcase our skills.”\", \"vi\": \"Chúng tôi hy vọng sẽ có cơ hội được thể hiện năng lực của mình.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"From: Clifford Mullen <clifford@busybbakery.com>\", \"vi\": \"Từ: Clifford Mullen <clifford@busybbakery.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To: Racquel Shaw <r_shaw@hillviewprop.com>\", \"vi\": \"Gửi: Racquel Shaw <r_shaw@hillviewprop.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Date: November 18\", \"vi\": \"Ngày: 18 tháng 11\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Subject: Rental inquiry\", \"vi\": \"Chủ đề: Yêu cầu thông tin về việc thuê nhà\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Dear Ms. Shaw,\", \"vi\": \"Kính gửi Bà Shaw,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I own the Busy Bee Bakery downtown, and I am interested in renting a second location to sell my baked goods.\", \"vi\": \"Tôi là chủ tiệm bánh Busy Bee Bakery ở trung tâm thành phố, và tôi đang có ý định thuê một địa điểm thứ hai để bán các sản phẩm bánh ngọt của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Marshall Plaza would be ideal for my business because of the anticipated foot traffic.\", \"vi\": \"Marshall Plaza sẽ là địa điểm lý tưởng cho doanh nghiệp của tôi nhờ lượng khách qua lại dự kiến sẽ rất đông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I am also drawn to the convenience of the easy access to public transportation and the unloading area in the back.\", \"vi\": \"Tôi cũng rất ấn tượng với sự tiện lợi khi dễ dàng tiếp cận các phương tiện giao thông công cộng cũng như khu vực bốc dỡ hàng hóa ở phía sau.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I need at least three hundred square meters of space, but I do not want cooking facilities, as our staff will bake at our main site and just deliver the goods to the secondary site.\", \"vi\": \"Tôi cần ít nhất ba trăm mét vuông diện tích, nhưng tôi không muốn có khu vực nấu nướng, vì nhân viên của chúng tôi sẽ nướng bánh tại cơ sở chính và chỉ vận chuyển sản phẩm đến cơ sở phụ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I’m also wondering if you could tell me the average rates for water, electricity, and gas.\", \"vi\": \"Tôi cũng muốn hỏi xem quý vị có thể cho tôi biết mức giá trung bình của nước, điện và gas không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I know that these are not included in the monthly rental fee.\", \"vi\": \"Tôi biết rằng những khoản này không được tính vào phí thuê hàng tháng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Thanks for the information,\", \"vi\": \"Xin cảm ơn quý vị đã cung cấp thông tin,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Clifford Mullen\", \"vi\": \"Clifford Mullen\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Unit 102\\n\\n            320 m²\\n\\n            Available - Unit 103\\n\\n            270 m²\\n\\n            Available - Unit 104\\n\\n            350 m²\\n\\n            Benny’s Sweet Shop\", \"vi\": \"Căn hộ 102\\n\\n            320 m²\\n\\n            Còn trống - Căn hộ 103\\n\\n            270 m²\\n\\n            Còn trống - Căn hộ 104\\n\\n            350 m²\\n\\n            Cửa hàng bánh kẹo Benny’s\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Unit 101\\n\\n            225 m²\\n\\n            Available - Courtyard - Unit 105\\n\\n            315 m²\\n\\n            Available\\n\\n            Includes kitchen\", \"vi\": \"Căn hộ 101\\n\\n            225 m²\\n\\n            Còn trống - Sân trong - Căn hộ 105\\n\\n            315 m²\\n\\n            Còn trống\\n\\n            Bao gồm phòng bếp\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Marshall Plaza Retail Units\", \"vi\": \"Các đơn vị bán lẻ tại Marshall Plaza\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '8480aade-890c-430a-a7d7-d1c60e3cc4ff';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Jane Hughes <jhughes@keating-cs.com>\", \"vi\": \"Từ: Jane Hughes <jhughes@keating-cs.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Santosh Prasad <sprasad@who-mail.com>\", \"vi\": \"Gửi tới: Santosh Prasad <sprasad@who-mail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 1\", \"vi\": \"Ngày: 1 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Reply from Keating Capital Solutions\", \"vi\": \"Chủ đề: Thư trả lời từ Keating Capital Solutions\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Prasad,\", \"vi\": \"Kính gửi ông Prasad,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We are pleased that you have agreed to join Keating Capital Solutions as a network security engineer.\", \"vi\": \"Chúng tôi rất vui mừng khi quý vị đã đồng ý gia nhập Keating Capital Solutions với tư cách là kỹ sư an ninh mạng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It is clear from your interviews, skills test results, and references that you will make a valuable addition to the information technology team.\", \"vi\": \"Qua các buổi phỏng vấn, kết quả bài kiểm tra kỹ năng và các thư giới thiệu của quý vị, có thể thấy rõ rằng quý vị sẽ là một thành viên có giá trị trong đội ngũ công nghệ thông tin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As such, I am happy to accommodate your request to postpone your start date so that you can go on your previously planned vacation.\", \"vi\": \"Vì vậy, tôi rất vui lòng đáp ứng yêu cầu của quý vị về việc hoãn ngày bắt đầu công việc để quý vị có thể thực hiện kỳ nghỉ đã lên kế hoạch từ trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We will therefore plan to see you at our office at 9 A.M. on Monday, March 27.\", \"vi\": \"Do đó, chúng tôi dự kiến sẽ tiếp quý vị tại văn phòng của chúng tôi vào lúc 9 giờ sáng Thứ Hai, ngày 27 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Please bring photo identification and information about your bank account so that you can fill out the necessary tax and payroll forms.\", \"vi\": \"Kính mong quý vị mang theo giấy tờ tùy thân có ảnh và thông tin về tài khoản ngân hàng của mình để có thể điền vào các mẫu đơn cần thiết liên quan đến thuế và tiền lương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Kelly Moss, one of our human resources generalists, will walk you through this paperwork in the morning.\", \"vi\": \"Bà Kelly Moss, một trong những chuyên viên nhân sự đa năng của chúng tôi, sẽ hướng dẫn quý vị hoàn tất các thủ tục giấy tờ này vào buổi sáng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Ms. Moss will also familiarize you with our workplace policies and resources for employees.\", \"vi\": \"Bà Moss cũng sẽ giúp quý vị làm quen với các chính sách tại nơi làm việc cũng như các nguồn lực dành cho nhân viên của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"When she is done, I will begin your position-specific training.\", \"vi\": \"Khi cô ấy hoàn tất, tôi sẽ bắt đầu chương trình huấn luyện chuyên biệt cho vị trí của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Please reply to confirm that you have received this message.\", \"vi\": \"Kính mong Quý vị vui lòng trả lời để xác nhận rằng Quý vị đã nhận được tin nhắn này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I am also happy to answer any questions you may have.\", \"vi\": \"Tôi cũng rất sẵn lòng giải đáp bất kỳ thắc mắc nào của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Jane Hughes, Director of Information Technology\", \"vi\": \"Bà Jane Hughes, Giám đốc Công nghệ Thông tin\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '849dc66f-a3d5-4ffd-9b0c-91cd85b42426';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"7:30 A.M. - Breakfast - East Ballroom\", \"vi\": \"7 giờ 30 phút sáng – Bữa sáng – Phòng khiêu vũ phía Đông\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"9:00 A.M. - Keynote Address\\nCEO Katsuhiko Nakamuro - South Ballroom\", \"vi\": \"9 giờ sáng – Bài phát biểu khai mạc\\nÔng Katsuhiko Nakamuro, Tổng Giám đốc Điều hành – Phòng tiệc South Ballroom\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"10:30 A.M. - Kuraki Business Outlook\\nVice President Jiro Higa - South Ballroom\", \"vi\": \"10 giờ 30 sáng - Triển vọng kinh doanh của Kuraki\\nPhó Chủ tịch Jiro Higa - Phòng khiêu vũ phía Nam\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Noon - Lunch - East Ballroom\", \"vi\": \"Trưa - Bữa trưa - Phòng khiêu vũ phía Đông\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"1:30 P.M. - New Product Debuts\\nChief Designer Yuna Yamashita - South Ballroom\", \"vi\": \"13 giờ 30 – Ra mắt sản phẩm mới\\nTrưởng nhóm thiết kế Yuna Yamashita – Phòng khiêu vũ phía Nam\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"4:00 P.M. - Dealer-Led Seminars:\\nThe Modern Dealership\\nDigital Campaigns - Mara Room\\nFlora Room\", \"vi\": \"16:00 – Các buổi hội thảo do các đại lý chủ trì:\\nĐại lý ô tô hiện đại\\nCác chiến dịch kỹ thuật số – Phòng Mara\\nPhòng Flora\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"6:00 P.M. - Dinner - East Ballroom\", \"vi\": \"18 giờ - Bữa tối - Phòng khiêu vũ phía Đông\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Kuraki Motors Canadian Dealer Annual Meeting\", \"vi\": \"Hội nghị thường niên các đại lý của Kuraki Motors tại Canada\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Schedule for Friday, June 8\", \"vi\": \"Lịch trình cho ngày thứ Sáu, 8 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Canadian Dealer Meeting\", \"vi\": \"Hội nghị các đại lý tại Canada\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"By Josie Hopkins, Kuraki Now Staff Writer\", \"vi\": \"Tác giả: Josie Hopkins, Phóng viên của Kuraki Now\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Executives from Kuraki Motors returned to Toronto for an annual meeting of the nearly 1,000 Canadian representatives of the brand.\", \"vi\": \"Các lãnh đạo cấp cao của Kuraki Motors đã trở lại Toronto để tham dự cuộc họp thường niên với gần 1.000 đại diện của thương hiệu này tại Canada.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The two-day event kicked off on Friday morning with CEO Katsuhiko Nakamuro, who gave a keynote address highlighting progress on the company\'s new manufacturing plant in Toronto.\", \"vi\": \"Sự kiện kéo dài hai ngày đã chính thức khai mạc vào sáng thứ Sáu với bài phát biểu khai mạc của Giám đốc điều hành Katsuhiko Nakamuro, trong đó ông đã nêu bật những tiến triển liên quan đến nhà máy sản xuất mới của công ty tại Toronto.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"He was followed by Vice President Jiro Higa detailing increased production levels and expected growth.\", \"vi\": \"Tiếp theo là Phó Chủ tịch Jiro Higa, người đã trình bày chi tiết về mức sản lượng gia tăng và triển vọng tăng trưởng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Attendees then had the opportunity to attend two days of seminars.\", \"vi\": \"Sau đó, các đại biểu đã có cơ hội tham dự hai ngày hội thảo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"But the highlight of the event was the unveiling of two new models, the sleek Daino sedan and Kuraki\'s new hybrid, the Pura.\", \"vi\": \"Tuy nhiên, điểm nhấn của sự kiện này chính là lễ ra mắt hai mẫu xe mới, đó là mẫu sedan Daino với thiết kế thanh lịch và mẫu xe hybrid mới của Kuraki, Pura.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The models will be rolling into dealerships in August.\", \"vi\": \"Các mẫu xe này sẽ lần lượt được đưa về các đại lý vào tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Seminars - Rating\", \"vi\": \"Hội thảo - Đánh giá\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The Modern Dealership - 4\", \"vi\": \"Đại lý ô tô hiện đại - 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Digital Campaigns - n/a\", \"vi\": \"Chiến dịch kỹ thuật số - không áp dụng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Proven Methods to Attract Salespeople - 4\", \"vi\": \"Các phương pháp đã được chứng minh để thu hút nhân viên bán hàng - 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Internet Sales Success - n/a\", \"vi\": \"Thành công trong bán hàng trực tuyến - không áp dụng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"The Business Model of the Future - n/a\", \"vi\": \"Mô hình kinh doanh của tương lai - không áp dụng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Standing Out from the Competition - 4\", \"vi\": \"Nổi bật so với các đối thủ cạnh tranh - 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Kuraki Motors Canadian Dealer Annual Meeting—Survey Form\", \"vi\": \"Hội nghị thường niên các đại lý của Kuraki Motors tại Canada — Phiếu khảo sát\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Thank you for attending this year\'s dealer meeting.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã tham dự hội nghị đại lý năm nay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"We would appreciate your feedback.\", \"vi\": \"Chúng tôi rất mong nhận được ý kiến phản hồi từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Please use the following rating scale to rate each of the seminars you attended.\", \"vi\": \"Kính mong quý vị sử dụng thang điểm đánh giá sau đây để đánh giá từng buổi hội thảo mà quý vị đã tham dự.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Rating Scale: 4 = excellent; 3 = very good; 2 = satisfactory; 1 = poor\", \"vi\": \"Thang điểm: 4 = xuất sắc; 3 = rất tốt; 2 = đạt yêu cầu; 1 = kém\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Comments:\", \"vi\": \"Bình luận:\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"The seminars on both days were informative as always.\", \"vi\": \"Các buổi hội thảo trong cả hai ngày đều mang lại nhiều thông tin hữu ích như mọi khi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I wish that some were not scheduled at the same time and that more were offered before lunch on Saturday.\", \"vi\": \"Tôi mong rằng một số buổi không được xếp lịch trùng giờ với nhau và có thêm nhiều buổi được tổ chức trước giờ ăn trưa vào thứ Bảy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Some of my colleagues were unable to stay for the afternoon sessions.\", \"vi\": \"Một số đồng nghiệp của tôi không thể ở lại tham dự các phiên họp buổi chiều.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Name: Howard Gellman\", \"vi\": \"Họ tên: Howard Gellman\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '84cfeafc-f741-4ad5-bec9-bababaabb3aa';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Article title\", \"vi\": \"Tiêu đề bài báo\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Article\", \"vi\": \"Bài báo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"COPENHAGEN (25 May)—Odense Media announced today that initial sales of the latest version of its tablet, Virtusonic, have — [131] — the company\'s expectations.\", \"vi\": \"COPENHAGEN (25 tháng 5)—Odense Media hôm nay thông báo rằng doanh số ban đầu của phiên bản máy tính bảng mới nhất của hãng, Virtusonic, đã — [131] — mong đợi của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [131]}, {\"en\": \"Company spokesperson Kerstin Vestergaard attributes the — [132] — sales to a number of factors.\", \"vi\": \"Người phát ngôn công ty Kerstin Vestergaard quy doanh số — [132] — cho một số yếu tố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [132]}, {\"en\": \"First, there is the tablet\'s high-quality case.\", \"vi\": \"Đầu tiên là lớp vỏ chất lượng cao của máy tính bảng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [133] —.\", \"vi\": \"— [133] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [133]}, {\"en\": \"In addition, the Virtusonic has an adaptive screen brightness feature.\", \"vi\": \"Ngoài ra, Virtusonic còn có tính năng điều chỉnh độ sáng màn hình thích ứng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This allows it to adjust automatically to less-than-ideal — [134] — conditions.\", \"vi\": \"Tính năng này cho phép máy tự động điều chỉnh phù hợp với các điều kiện — [134] — không được lý tưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [134]}, {\"en\": \"Vestergaard believes that these characteristics make the Virtusonic a must-have for consumers.\", \"vi\": \"Vestergaard tin rằng những đặc điểm này khiến Virtusonic trở thành một thiết bị không thể thiếu đối với người tiêu dùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '8506fdcd-ef86-4810-be0f-d85343f0a1d7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.officenature.com\", \"vi\": \"http://www.officenature.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Want to boost the health and morale of your employees?\", \"vi\": \"Quý vị có muốn nâng cao sức khỏe và tinh thần làm việc của nhân viên không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Office Nature delivers a box filled with delicious food right to your break room.\", \"vi\": \"Office Nature sẽ giao một hộp đầy ắp những món ăn ngon ngay đến phòng nghỉ của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We focus on the following.\", \"vi\": \"Chúng tôi tập trung vào những nội dung sau đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"providing natural treats such as nuts, granola, and dried fruit\", \"vi\": \"cung cấp các món ăn vặt tự nhiên như các loại hạt, granola và trái cây sấy khô\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"working with local farmers to provide the freshest options\", \"vi\": \"hợp tác với các nông dân địa phương để cung cấp những sản phẩm tươi ngon nhất\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"reducing impact on the environment\", \"vi\": \"giảm thiểu tác động đến môi trường\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"offering foods at reasonable prices\", \"vi\": \"cung cấp các món ăn với mức giá hợp lý\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Just choose your selections and delivery day, and a fresh box of healthy food items will be brought automatically each week.\", \"vi\": \"Quý vị chỉ cần chọn các mặt hàng mong muốn và ngày giao hàng, và mỗi tuần, một hộp thực phẩm tươi ngon, tốt cho sức khỏe sẽ được tự động giao đến tận nơi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"First-time customers receive 10% off their order with code YUM.\", \"vi\": \"Khách hàng lần đầu tiên đặt hàng sẽ được giảm giá 10% cho đơn hàng của mình khi sử dụng mã YUM.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '8508bb5c-fcd5-4deb-9995-fe794f8492c2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Hyo-Jung Cho\", \"vi\": \"To: Hyo-Jung Cho\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Julian Katz\", \"vi\": \"Từ: Julian Katz\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 14 June\", \"vi\": \"Ngày: 14 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Cho,\", \"vi\": \"Dear Ms. Cho,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Since you were away last week, you might not yet know all the details of the situation with the Web site.\", \"vi\": \"Vì tuần trước quý vị vắng mặt, có thể quý vị vẫn chưa nắm rõ tất cả các chi tiết về tình hình liên quan đến trang web.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Shannon Gehring, our Web designer, was in the middle of revising the site when a severe thunderstorm hit our area.\", \"vi\": \"Shannon Gehring, nhà thiết kế web của chúng tôi, đang trong quá trình chỉnh sửa trang web thì một cơn giông bão dữ dội ập đến khu vực của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Our servers were struck by lightning and sustained some damage.\", \"vi\": \"Các máy chủ của chúng tôi đã bị sét đánh và bị hư hỏng một phần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"While they were being repaired, the museum\'s Web site was down for two days.\", \"vi\": \"Trong thời gian tiến hành sửa chữa, trang web của bảo tàng đã ngừng hoạt động trong hai ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I know you are planning to send an e-mail to members today, asking them to help us meet a fund-raising goal by 30 June, the end of our fiscal year.\", \"vi\": \"Tôi biết hôm nay quý vị dự định gửi một email đến các thành viên, đề nghị họ hỗ trợ chúng ta đạt được mục tiêu gây quỹ trước ngày 30 tháng 6, tức là vào cuối năm tài chính của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Our site is back online now, and includes a new comment page that can be used for this fund-raising event.\", \"vi\": \"Trang web của chúng tôi hiện đã hoạt động trở lại và đã được bổ sung một trang bình luận mới dành riêng cho sự kiện gây quỹ này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please let me know if you need additional information.\", \"vi\": \"Nếu quý vị cần thêm thông tin, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Julian Katz\", \"vi\": \"Julian Katz\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"IT Coordinator\", \"vi\": \"Điều phối viên Công nghệ Thông tin\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Knight Museum of Art\", \"vi\": \"Bảo tàng Nghệ thuật Knight\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"http://www.knightmuseumofart.ca/comments\", \"vi\": \"http://www.knightmuseumofart.ca/comments\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"14 June\", \"vi\": \"Ngày 14 tháng 6\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I am such a big fan of the Knight Museum!\", \"vi\": \"Tôi thực sự là một người hâm mộ cuồng nhiệt của Bảo tàng Knight!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I have been taking advantage of some of the museum\'s wonderful programs.\", \"vi\": \"Tôi đã có cơ hội tham gia một số chương trình tuyệt vời của bảo tàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"The recent series of watercolor painting classes with local artist Leroy Davis was terrific.\", \"vi\": \"Chuỗi lớp học vẽ tranh màu nước gần đây do họa sĩ địa phương Leroy Davis giảng dạy thật sự rất tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"This experience with watercolors will help me appreciate the museum\'s current exhibition of Japanese watercolor paintings even more; I\'m looking forward to taking a tour of the exhibition next week.\", \"vi\": \"Trải nghiệm với tranh màu nước lần này sẽ giúp tôi càng thêm trân trọng triển lãm tranh màu nước Nhật Bản hiện đang diễn ra tại bảo tàng; tôi rất mong chờ được tham quan triển lãm vào tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I already contribute as a museum member, but I just made an additional donation online today after I received a fund-raising e-mail from the museum\'s director.\", \"vi\": \"Tôi vốn đã đóng góp với tư cách là thành viên của bảo tàng, nhưng hôm nay tôi vừa thực hiện một khoản đóng góp bổ sung qua mạng sau khi nhận được email kêu gọi quyên góp từ giám đốc bảo tàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"It was easy to access the Web site, although I had trouble last week.\", \"vi\": \"Việc truy cập trang web rất dễ dàng, mặc dù tuần trước tôi đã gặp một số khó khăn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I hope others will support the museum by contributing before the 30 June deadline.\", \"vi\": \"Tôi hy vọng mọi người sẽ ủng hộ bảo tàng bằng cách đóng góp trước thời hạn ngày 30 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"The Knight Museum\'s programming is worth it.\", \"vi\": \"Các chương trình của Bảo tàng Knight thực sự rất đáng tham dự.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"—Brenda Sanz\", \"vi\": \"—Brenda Sanz\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '85135d7d-0e6e-461b-9a4d-dd241a29fedf';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mario Lizzardi (11:09 A.M.) - Team, sorry to bring this up early on a Monday, but the due date to submit our end-of-year report is coming up. We should aim to have each of our sections done by Wednesday so we can put everything together before the Friday deadline. I am almost done with the information for the technology section.\", \"vi\": \"Mario Lizzardi (11 giờ 09 phút sáng) - Thưa các thành viên trong nhóm, xin lỗi vì phải đề cập đến vấn đề này ngay từ đầu ngày thứ Hai, nhưng thời hạn nộp báo cáo cuối năm của chúng ta đang đến gần. Chúng ta nên đặt mục tiêu hoàn thành từng phần công việc trước thứ Tư để có thể tổng hợp toàn bộ nội dung trước thời hạn vào thứ Sáu. Tôi đã gần hoàn tất phần thông tin cho mục công nghệ rồi.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Karthik Durav (11:14 A.M.) - I have already written up descriptions of the program\'s major accomplishments. I just need to add the number of participants and organizers involved in each. It won\'t take very long.\", \"vi\": \"Karthik Durav (11 giờ 14 phút sáng) – Tôi đã soạn thảo xong phần mô tả về những thành tựu chính của chương trình. Tôi chỉ cần bổ sung số lượng người tham gia và ban tổ chức liên quan đến từng thành tựu đó. Việc này sẽ không mất nhiều thời gian đâu.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Paola Rossi (11:15 A.M.) - I have finished the Future Goals section. I still need to finish the Predicted Budget Needs section, but I\'d like to consult with some of you first.\", \"vi\": \"Paola Rossi (11 giờ 15 phút sáng) - Tôi đã hoàn thành phần “Mục tiêu trong tương lai”. Tôi vẫn còn phải hoàn thành phần “Dự kiến nhu cầu ngân sách”, nhưng trước tiên tôi muốn tham khảo ý kiến của một số quý vị.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Mario Lizzardi (11:15 A.M.) - I can\'t help you with that. I don\'t have access to that information—only you and Human Resources have access to the participant lists.\", \"vi\": \"Mario Lizzardi (11 giờ 15 phút sáng) – Tôi không thể giúp quý vị về vấn đề này. Tôi không có quyền truy cập vào thông tin đó — chỉ có quý vị và Phòng Nhân sự mới có quyền truy cập vào danh sách người tham gia.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Karthik Durav (11:17 A.M.) - Don\'t worry, Mario. Paola, I could help to outline budget needs with you tomorrow. Anything else?\", \"vi\": \"Karthik Durav (11 giờ 17 phút sáng) - Đừng lo, Mario. Paola, ngày mai tôi có thể cùng cô phác thảo các nhu cầu về ngân sách. Còn gì nữa không?\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Paola Rossi: (11:18 A.M.) - That\'s it. Depending on how much we finish, we could develop a timeline for finalizing the report this week.\", \"vi\": \"Paola Rossi: (11 giờ 18 phút sáng) - Vậy là xong rồi. Tùy thuộc vào mức độ hoàn thành công việc, chúng ta có thể lên kế hoạch thời gian để hoàn tất báo cáo trong tuần này.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"①②③\", \"vi\": \"①②③\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '854f613c-330b-4629-a516-ffa39808226f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Dahlia Pawar <dpawar@bronsonco.ca>\", \"vi\": \"Gửi tới: Dahlia Pawar <dpawar@bronsonco.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Anna Bondell <abondell@noaaa.com>\", \"vi\": \"Từ: Anna Bondell <abondell@noaaa.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: August 25\", \"vi\": \"Ngày: 25 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Pawar:\", \"vi\": \"Kính gửi Bà Pawar:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for your continued membership in the North American Architects Association.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã tiếp tục là thành viên của Hiệp hội Kiến trúc sư Bắc Mỹ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I\'m writing to remind you that preregistration for the annual conference closes on September 15.\", \"vi\": \"Tôi viết thư này để nhắc nhở quý vị rằng thời hạn đăng ký trước cho hội nghị thường niên sẽ kết thúc vào ngày 15 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"- [1] - .\", \"vi\": \"- [1] - .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This year\'s conference features more than 100 sessions, an exhibit hall, and special workshops.\", \"vi\": \"Hội nghị năm nay bao gồm hơn 100 phiên họp, một khu triển lãm và các hội thảo chuyên đề.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"- [2] - .\", \"vi\": \"- [2] - .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Preregistration will save you $30 off the regular registration fee.\", \"vi\": \"Việc đăng ký trước sẽ giúp quý vị tiết kiệm được 30 đô la so với mức phí đăng ký thông thường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"- [3] -.\", \"vi\": \"- [3] -.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"At the same time, you\'ll be able to sign up in advance for a group tour of the city and for the VIP Banquet, which always fills up quickly.\", \"vi\": \"Đồng thời, quý vị sẽ có thể đăng ký trước để tham gia tour tham quan thành phố theo nhóm cũng như dự tiệc VIP – sự kiện luôn được đặt chỗ hết rất nhanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Visit our Web site to register online.\", \"vi\": \"Vui lòng truy cập trang web của chúng tôi để đăng ký trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"- [4] - .\", \"vi\": \"- [4] - .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"If you prefer to register by telephone, contact us at 1-249-555-0177.\", \"vi\": \"Nếu quý vị muốn đăng ký qua điện thoại, vui lòng liên hệ với chúng tôi theo số 1-249-555-0177.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Please have your membership number available.\", \"vi\": \"Xin vui lòng chuẩn bị sẵn số thẻ thành viên của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Looking forward to seeing you in Mexico City!\", \"vi\": \"Rất mong được gặp quý vị tại Thành phố Mexico!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Anna Bondell\", \"vi\": \"Anna Bondell\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Membership Coordinator\", \"vi\": \"Điều phối viên phụ trách thành viên\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '858b52a7-14a8-4a24-9d6c-dd61e9cb8f22';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Melina Ramos Sandoval\", \"vi\": \"Đến: Melina Ramos Sandoval\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: welcome@sourcework.ca\", \"vi\": \"Từ: welcome@sourcework.ca\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 25 October\", \"vi\": \"Ngày: 25 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Registration complete\", \"vi\": \"Chủ đề: Hoàn tất đăng ký\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Sandoval,\", \"vi\": \"Kính gửi Bà Sandoval,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Welcome to the Source Work jobs network, the leading online career matching service.\", \"vi\": \"Chào mừng bạn đến với mạng lưới việc làm Source Work, dịch vụ kết nối nghề nghiệp trực tuyến hàng đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Your e-mail address, work experience, and preferences ______[135] in our database.\", \"vi\": \"Địa chỉ email, kinh nghiệm làm việc và sở thích của bạn ______[135] trong cơ sở dữ liệu của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [135]}, {\"en\": \"This information will be used to identify employers who are seeking job candidates just like ______[136].\", \"vi\": \"Thông tin này sẽ được sử dụng để xác định các nhà tuyển dụng đang tìm kiếm các ứng viên việc làm giống như ______[136].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [136]}, {\"en\": \"In the future, you will receive periodic notifications about open positions in your area.\", \"vi\": \"Trong tương lai, bạn sẽ nhận được các thông báo định kỳ về các vị trí tuyển dụng trong khu vực của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"______[137].\", \"vi\": \"______[137].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [137]}, {\"en\": \"Therefore, we will not share your name or address with anyone.\", \"vi\": \"Do đó, chúng tôi sẽ không chia sẻ tên hoặc địa chỉ của bạn với bất kỳ ai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"At any point, you can select the link at the bottom of any e-mail you receive from us to unsubscribe or change your e-mail preferences.\", \"vi\": \"Vào bất kỳ lúc nào, bạn có thể chọn liên kết ở cuối bất kỳ email nào bạn nhận được từ chúng tôi để hủy đăng ký hoặc thay đổi tùy chọn email của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you for ______[138].\", \"vi\": \"Cảm ơn bạn đã ______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [138]}, {\"en\": \"If you have any questions or comments, feel free to contact us.\", \"vi\": \"Nếu bạn có bất kỳ câu hỏi hoặc góp ý nào, xin vui lòng liên hệ với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The Source Work team\", \"vi\": \"Đội ngũ Source Work\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '85f2cb3b-7a97-40a7-acae-a05cfb0fb4ab';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: amartin@netforceevents.com\", \"vi\": \"Nguồn: amartin@netforceevents.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: mpresser@gerenukofficedesign.com\", \"vi\": \"Gửi tới: mpresser@gerenukofficedesign.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: September 3\", \"vi\": \"Ngày: 3 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Chairs (Item #10405)\", \"vi\": \"Chủ đề: Ghế (Mã sản phẩm #10405)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Presser,\", \"vi\": \"Kính gửi ông Presser,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As a result of our company\'s expansion last spring, we moved into a larger facility and needed new furniture.\", \"vi\": \"Do công ty chúng tôi mở rộng quy mô vào mùa xuân năm ngoái, chúng tôi đã chuyển đến một cơ sở rộng rãi hơn và cần trang bị nội thất mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"At that time we ordered 22 office chairs from Gerenuk Office Design (Item #10405–Blue).\", \"vi\": \"Vào thời điểm đó, chúng tôi đã đặt hàng 22 chiếc ghế văn phòng từ Gerenuk Office Design (Mã sản phẩm #10405 – Màu xanh).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Within two months, many of the chairs were broken and unusable.\", \"vi\": \"Chỉ trong vòng hai tháng, rất nhiều chiếc ghế đã bị hỏng và không thể sử dụng được nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We were initially happy with the replacement chairs that you delivered free of charge, but some of those have now broken as well.\", \"vi\": \"Ban đầu, chúng tôi rất hài lòng với những chiếc ghế thay thế mà quý công ty đã giao miễn phí, nhưng hiện nay một số chiếc trong số đó cũng đã bị hỏng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I am hereby requesting that you replace all 22 with chairs from your new Executive line (Item #10612) at no extra charge—assuming that they are better quality.\", \"vi\": \"Tôi xin đề nghị quý công ty thay thế toàn bộ 22 chiếc ghế này bằng các mẫu ghế thuộc dòng Executive mới của quý công ty (Mã sản phẩm #10612) mà không tính thêm phí — với giả định rằng các sản phẩm này có chất lượng tốt hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"These are comparable in price to the original model we purchased.\", \"vi\": \"Giá của những sản phẩm này tương đương với mẫu ban đầu mà chúng tôi đã mua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"If you are unable to do this, we will be forced to look elsewhere for our furnishing needs.\", \"vi\": \"Nếu quý vị không thể thực hiện điều này, chúng tôi sẽ buộc phải tìm đến nơi khác để đáp ứng nhu cầu về nội thất của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Alexandra Martin, Office Administrator\", \"vi\": \"Alexandra Martin, Quản trị viên văn phòng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Netforce Events\", \"vi\": \"Các sự kiện của Netforce\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Home - Products - Customer Help - About Us\", \"vi\": \"Trang chủ - Sản phẩm - Hỗ trợ khách hàng - Giới thiệu về chúng tôi\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Ergonomic Task Chair\\n\\n\\n                  The Ergonomic Task Chair is our best-selling swivel model. It is specially designed to promote good posture and avoid discomfort, and therefore it is perfect for those long workdays at the office. Best of all, it is built to last and comes with a lifetime warranty. The model is available in four attractive colors.\\n\\n\\n$159 per unit\\n\\n\\n                  • Black, Item Code 429BL\\n\\n                  • Blue, Item Code 469BB\\n\\n                  • Green, Item Code 490GN\\n\\n                  • Red, Item Code 459RD - Ergonomic Task Chair\\n\\n\\n                  The Ergonomic Task Chair is our best-selling swivel model. It is specially designed to promote good posture and avoid discomfort, and therefore it is perfect for those long workdays at the office. Best of all, it is built to last and comes with a lifetime warranty. The model is available in four attractive colors.\\n\\n\\n$159 per unit - • Black, Item Code 429BL\\n\\n                  • Blue, Item Code 469BB\\n\\n                  • Green, Item Code 490GN\\n\\n                  • Red, Item Code 459RD\", \"vi\": \"Ghế làm việc công thái học\\n\\n\\n                  Ghế làm việc công thái học là mẫu ghế xoay bán chạy nhất của chúng tôi. Sản phẩm được thiết kế đặc biệt nhằm giúp duy trì tư thế ngồi đúng và tránh cảm giác khó chịu, do đó rất phù hợp cho những ngày làm việc dài tại văn phòng. Đặc biệt, sản phẩm được chế tạo để sử dụng lâu dài và đi kèm với chế độ bảo hành trọn đời. Mẫu ghế này có sẵn bốn màu sắc bắt mắt.\\n\\n\\n159 USD/chiếc\\n\\n\\n                  • Màu Đen, Mã sản phẩm 429BL\\n\\n                  • Màu Xanh dương, Mã sản phẩm 469BB\\n\\n                  • Màu Xanh lá, Mã sản phẩm 490GN\\n\\n                  • Màu Đỏ, Mã sản phẩm 459RD - Ghế làm việc công thái học\\n\\n\\n                  Ghế làm việc công thái học là mẫu ghế xoay bán chạy nhất của chúng tôi. Sản phẩm được thiết kế đặc biệt để duy trì tư thế ngồi đúng và tránh cảm giác khó chịu, do đó rất lý tưởng cho những ngày làm việc dài tại văn phòng. Đặc biệt, sản phẩm được chế tạo bền bỉ và đi kèm với chế độ bảo hành trọn đời. Mẫu ghế này có sẵn bốn màu sắc bắt mắt.\\n\\n\\n159 USD/chiếc - • Màu Đen, Mã sản phẩm 429BL\\n\\n                  • Màu Xanh dương, Mã sản phẩm 469BB\\n\\n                  • Màu Xanh lá, Mã sản phẩm 490GN\\n\\n                  • Màu Đỏ, Mã sản phẩm 459RD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Ergonomic Task Chair\\n\\n\\n                  The Ergonomic Task Chair is our best-selling swivel model. It is specially designed to promote good posture and avoid discomfort, and therefore it is perfect for those long workdays at the office. Best of all, it is built to last and comes with a lifetime warranty. The model is available in four attractive colors.\\n\\n\\n$159 per unit - • Black, Item Code 429BL\\n\\n                  • Blue, Item Code 469BB\\n\\n                  • Green, Item Code 490GN\\n\\n                  • Red, Item Code 459RD\", \"vi\": \"Ghế làm việc công thái học\\n\\n\\n                  Ghế làm việc công thái học là mẫu ghế xoay bán chạy nhất của chúng tôi. Sản phẩm được thiết kế đặc biệt nhằm giúp duy trì tư thế ngồi đúng và tránh cảm giác khó chịu, do đó rất lý tưởng cho những ngày làm việc dài tại văn phòng. Đặc biệt, sản phẩm được chế tạo để có độ bền cao và đi kèm với chế độ bảo hành trọn đời. Mẫu ghế này có sẵn bốn màu sắc bắt mắt.\\n\\n\\n159 USD/chiếc - • Màu Đen, Mã sản phẩm 429BL\\n\\n                  • Màu Xanh dương, Mã sản phẩm 469BB\\n\\n                  • Màu Xanh lá, Mã sản phẩm 490GN\\n\\n                  • Màu Đỏ, Mã sản phẩm 459RD\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"http://www.hansons-office.com/ergonomic-task-chair\", \"vi\": \"http://www.hansons-office.com/ergonomic-task-chair\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"HANSON\'S: YOUR ONE-STOP SHOP FOR OFFICE SUPPLIES\", \"vi\": \"HANSON\'S: ĐỊA CHỈ MỘT ĐIỂM DỪNG DUY NHẤT CHO CÁC VẬT DỤNG VĂN PHÒNG CỦA QUÝ VỊ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Item - Quantity - Unit Price - Total\", \"vi\": \"Mặt hàng - Số lượng - Giá đơn vị - Tổng cộng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Ergonomic Task Chair,\\nItem 490GN - 22 - $159.00 - $3,498.00\", \"vi\": \"Ghế làm việc công thái học,\\nMã sản phẩm 490GN - 22 - 159,00 USD - 3.498,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subtotal   $3,498.00\\n\\n            Discount for first-time customers   –$159.00\\n\\nTotal   $3,339.00\", \"vi\": \"Tổng phụ   3.498,00 USD\\n\\n            Giảm giá dành cho khách hàng lần đầu   –159,00 USD\\n\\nTổng cộng   3.339,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"HANSON\'S: YOUR ONE-STOP SHOP FOR OFFICE SUPPLIES\", \"vi\": \"HANSON\'S: ĐỊA CHỈ MỘT ĐIỂM DỪNG DUY NHẤT CHO CÁC LOẠI VẬT DỤNG VĂN PHÒNG\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"INVOICE\", \"vi\": \"HÓA ĐƠN\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Client:   Netforce Events\", \"vi\": \"Khách hàng:   Netforce Events\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Address: 342 Collard Boulevard, Hampton, ME\", \"vi\": \"Địa chỉ: 342 Collard Boulevard, Hampton, ME\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date:   September 10\", \"vi\": \"Ngày:   10 tháng 9\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Please contact customerhelp@hansons-office.com if you have any questions.\", \"vi\": \"Nếu Quý vị có bất kỳ thắc mắc nào, xin vui lòng liên hệ qua địa chỉ email customerhelp@hansons-office.com.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '860ee0a2-8ee2-41f7-9099-700a93397186';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Alberto Ovando [11:15 A.M.] When we met last week, production was nearly finished on the boxes and other packaging for Redmond\'s.\", \"vi\": \"Alberto Ovando [11 giờ 15 phút sáng] Khi chúng ta gặp nhau vào tuần trước, việc sản xuất các hộp và các loại bao bì khác cho Redmond\'s đã gần hoàn tất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Rani, where are we now?\", \"vi\": \"Rani ơi, hiện tại chúng ta đang ở đâu vậy?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Rani Verma [11:16 A.M.] The refrigerator and dishwasher boxes were supposed to arrive at Redmond\'s warehouse on Wednesday, but the snowstorm really backed up our delivery schedule.\", \"vi\": \"Rani Verma [11 giờ 16 phút sáng] Các thùng carton đựng tủ lạnh và máy rửa chén lẽ ra phải được chuyển đến kho hàng của Redmond vào thứ Tư, nhưng cơn bão tuyết đã khiến lịch trình giao hàng của chúng tôi bị chậm trễ đáng kể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Alberto Ovando [11:17 A.M.] Have you told them this?\", \"vi\": \"Alberto Ovando [11 giờ 17 phút sáng] Quý vị đã thông báo điều này cho họ chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Stacy Pfeiffer [11:18 A.M.] I will, but I was waiting to hear from the drivers.\", \"vi\": \"Stacy Pfeiffer [11 giờ 18 phút sáng] Tôi sẽ làm vậy, nhưng tôi đang chờ tin từ các tài xế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"George, can you help?\", \"vi\": \"George, anh có thể giúp được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"George Kellerman [11:19 A.M.] I spoke with them ten minutes ago.\", \"vi\": \"George Kellerman [11 giờ 19 phút sáng] Tôi vừa nói chuyện với họ cách đây mười phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"They\'re back on the road now, so they only lost a day.\", \"vi\": \"Hiện tại họ đã tiếp tục lên đường, nên họ chỉ mất có một ngày mà thôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"They should have everything before the end of the week.\", \"vi\": \"Họ sẽ có đủ mọi thứ trước khi kết thúc tuần này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Stacy Pfeiffer [11:21 A.M.] OK.\", \"vi\": \"Stacy Pfeiffer [11 giờ 21 phút sáng] Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I\'ll tell them to expect delivery by Friday at the very latest.\", \"vi\": \"Tôi sẽ thông báo với quý vị rằng hàng sẽ được giao chậm nhất là vào thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Rani Verma [11:22 A.M.] At least the packaging materials for the smaller appliances shipped before the storm; only the larger boxes are affected.\", \"vi\": \"Rani Verma [11 giờ 22 phút sáng] Ít nhất thì các vật liệu đóng gói dành cho các thiết bị gia dụng cỡ nhỏ đã được vận chuyển đi trước khi cơn bão ập đến; chỉ có các thùng hàng cỡ lớn mới bị ảnh hưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Alberto Ovando [11:23 A.M.] The contract is for us to provide packaging materials for all of Redmond\'s products, not just the smaller ones.\", \"vi\": \"Alberto Ovando [11 giờ 23 phút sáng] Hợp đồng này quy định rằng chúng tôi sẽ cung cấp vật liệu đóng gói cho tất cả các sản phẩm của Redmond, chứ không chỉ những sản phẩm có kích thước nhỏ hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Let\'s make sure we stay on the revised schedule.\", \"vi\": \"Chúng ta hãy đảm bảo tuân thủ đúng lịch trình đã điều chỉnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '86144c4d-afd4-417c-a22d-62af8ae35016';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Harriet Trimble <htrimble@decobusinessdesign.com>\", \"vi\": \"Gửi tới: Harriet Trimble <htrimble@decobusinessdesign.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Karl Vinton <karl.vinton@vintapparel.com>\", \"vi\": \"Từ: Karl Vinton <karl.vinton@vintapparel.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 26\", \"vi\": \"Ngày: 26 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Layout for Vint Apparel store\", \"vi\": \"Chủ đề: Bản thiết kế mặt bằng cho cửa hàng Vint Apparel\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Store layout\", \"vi\": \"Tệp đính kèm: Sơ đồ bố trí cửa hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Hello, Harriet,\", \"vi\": \"Xin chào, Harriet,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am delighted you are available for this latest project; we were very pleased with your previous work.\", \"vi\": \"Tôi rất vui mừng khi biết quý vị có thể tham gia dự án mới nhất này; chúng tôi đã rất hài lòng với những thành quả trước đây của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Here are some general instructions to start.\", \"vi\": \"Dưới đây là một số hướng dẫn chung để quý vị bắt đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"On the back wall, hang the Vint Apparel neon sign high enough to be seen over other furniture in the store.\", \"vi\": \"Trên bức tường phía sau, xin treo bảng hiệu đèn neon của Vint Apparel ở độ cao đủ để có thể nhìn thấy rõ hơn so với các đồ nội thất khác trong cửa hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The sign has already shipped and should be delivered next Monday.\", \"vi\": \"Biển hiệu đã được vận chuyển và dự kiến sẽ được giao vào thứ Hai tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The rectangular light fixtures will also arrive on Monday.\", \"vi\": \"Các thiết bị chiếu sáng hình chữ nhật cũng sẽ được giao vào thứ Hai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"There should be four—two for each of the side walls.\", \"vi\": \"Phải có bốn cái — mỗi vách bên một cái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The racks and shelving to display clothing are already there.\", \"vi\": \"Các giá treo và kệ trưng bày quần áo đã được lắp đặt sẵn tại đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please place the three circular racks in the center of the store and put the two shelving units along the left side as you enter the store.\", \"vi\": \"Xin vui lòng đặt ba giá tròn vào chính giữa cửa hàng và đặt hai dãy kệ dọc theo phía bên trái khi quý vị bước vào cửa hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Finally, place the cashier station to the right as you enter the store.\", \"vi\": \"Cuối cùng, xin vui lòng bố trí quầy thu ngân ở phía bên phải khi quý vị bước vào cửa hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I have attached a drawing of the layout that includes more detail.\", \"vi\": \"Tôi đã đính kèm bản vẽ sơ đồ bố trí với các chi tiết cụ thể hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Karl Vinton, Owner\", \"vi\": \"Karl Vinton, Chủ sở hữu\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Harriet Trimble [8:05 A.M.]\", \"vi\": \"Harriet Trimble [8 giờ 05 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I stopped by the Vint Apparel job site.\", \"vi\": \"Tôi đã ghé qua công trường của Vint Apparel.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We will have to put everything in place by June 15 because the grand opening is fast approaching.\", \"vi\": \"Chúng tôi sẽ phải hoàn tất mọi việc trước ngày 15 tháng 6 vì lễ khai trương đang đến rất gần.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Mr. Vinton stressed that they need to start stocking merchandise the week of June 20 to be ready for the official event on July 1.\", \"vi\": \"Ông Vinton nhấn mạnh rằng họ cần bắt đầu nhập hàng vào tuần từ ngày 20 tháng 6 để sẵn sàng cho sự kiện chính thức diễn ra vào ngày 1 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Jackson Ortega [8:06 A.M.]\", \"vi\": \"Jackson Ortega [8 giờ 06 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"We can do that.\", \"vi\": \"Chúng tôi có thể làm được điều đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Harriet Trimble [8:07 A.M.]\", \"vi\": \"Harriet Trimble [8 giờ 07 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Also, there has been a change to the layout drawing.\", \"vi\": \"Ngoài ra, bản vẽ bố trí cũng đã có một số thay đổi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Now we are to install a mannequin display where the two shelving units were and then move the shelving units to the side walls.\", \"vi\": \"Bây giờ, chúng ta sẽ lắp đặt một mô hình trưng bày tại vị trí trước đây đặt hai dãy kệ, sau đó di chuyển các dãy kệ này sang các bức tường bên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I will bring an updated copy for you when I come over this afternoon.\", \"vi\": \"Chiều nay khi tôi ghé qua, tôi sẽ mang theo một bản cập nhật cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = '86382c2a-cc84-4d42-b4b9-32cf996bb287';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Thank you for shopping with Danforth Fashions online.\", \"vi\": \"Cảm ơn bạn vì đã mua sắm trực tuyến tại Danforth Fashions.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Our quality-control team carefully inspects all products ______[131] packaging to ensure customer satisfaction.\", \"vi\": \"Đội ngũ kiểm soát chất lượng của chúng tôi cẩn thận kiểm tra tất cả các sản phẩm ______[131] đóng gói để đảm bảo sự hài lòng của khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"______[132].\", \"vi\": \"______[132].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132]}, {\"en\": \"If not, we make exchanges or returns easy.\", \"vi\": \"Nếu không, chúng tôi làm cho việc đổi hoặc trả hàng trở nên dễ dàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Simply contact us at service@danforthfashions.com if you need a different size, color, or pattern—or if you are dissatisfied for any reason.\", \"vi\": \"Chỉ cần liên hệ với chúng tôi tại service@danforthfashions.com nếu bạn cần một kích cỡ, màu sắc hoặc họa tiết khác—hoặc nếu bạn không hài lòng vì bất kỳ lý do gì.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Your exchange ______[133] right away.\", \"vi\": \"Việc đổi hàng của bạn ______[133] ngay lập tức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [133]}, {\"en\": \"To return an item for a refund, use the prepaid return shipping label included with your order and send it back to us in its original packaging unused and undamaged.\", \"vi\": \"Để trả lại một mặt hàng để được hoàn tiền, hãy sử dụng nhãn vận chuyển trả trước được đính kèm cùng đơn hàng của bạn và gửi lại cho chúng tôi trong bao bì ban đầu ở trạng thái chưa qua sử dụng và không bị hư hỏng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We issue refunds to the original method of payment, ______[134] the return shipping fee.\", \"vi\": \"Chúng tôi hoàn tiền theo phương thức thanh toán ban đầu, ______[134] phí vận chuyển trả hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [134]}]' WHERE `id` = '866b2e86-f137-4c82-b63f-08a7f04917e8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Helen Dietrich <hdietrich@morphospublishing.ca>\", \"vi\": \"Từ: Helen Dietrich <hdietrich@morphospublishing.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Alia Cervantes <alia.cervantes@gotomail.ca>\", \"vi\": \"Gửi: Alia Cervantes <alia.cervantes@gotomail.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 3 March\", \"vi\": \"Ngày: 3 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Practical Gardening\", \"vi\": \"Chủ đề: Làm vườn thực hành\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Cervantes:\", \"vi\": \"Kính gửi bà Cervantes:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am sorry to report that next month\'s issue of Practical Gardening will be our last.\", \"vi\": \"Tôi rất tiếc phải thông báo rằng số tạp chí “Practical Gardening” ra mắt vào tháng tới sẽ là số cuối cùng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"After 62 years of monthly issues, we at Morphos Publishing have decided that Practical Gardening will be among the periodicals that we must discontinue.\", \"vi\": \"Sau 62 năm xuất bản hàng tháng, chúng tôi tại Nhà xuất bản Morphos đã quyết định rằng tạp chí Practical Gardening sẽ nằm trong số các ấn phẩm định kỳ mà chúng tôi buộc phải ngừng phát hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We plan to redirect the resources gained through cost-cutting toward growing our book publishing and instructional video production businesses.\", \"vi\": \"Chúng tôi dự định sẽ chuyển hướng các nguồn lực thu được từ việc cắt giảm chi phí sang việc phát triển các mảng kinh doanh xuất bản sách và sản xuất video giáo dục.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We are grateful for your support as a longtime subscriber to Practical Gardening.\", \"vi\": \"Chúng tôi xin chân thành cảm ơn sự ủng hộ của quý vị với tư cách là độc giả lâu năm của tạp chí Practical Gardening.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"For the remainder of your subscription term, we hope you will allow us to instead send you Flora Discovery, our popular publication about wild plants.\", \"vi\": \"Trong thời gian còn lại của kỳ đăng ký, chúng tôi hy vọng quý vị sẽ cho phép chúng tôi gửi đến quý vị tạp chí “Flora Discovery” – ấn phẩm nổi tiếng của chúng tôi về các loài thực vật hoang dã – thay thế cho ấn phẩm hiện tại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"However, if you would rather have the balance of your subscription account refunded to you, please contact us at (822) 555-0127.\", \"vi\": \"Tuy nhiên, nếu quý vị muốn được hoàn lại số dư trong tài khoản đăng ký của mình, xin vui lòng liên hệ với chúng tôi theo số (822) 555-0127.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Helen Dietrich\", \"vi\": \"Helen Dietrich\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Subscription Manager, Morphos Publishing\", \"vi\": \"Trưởng bộ phận Quản lý Đăng ký, Nhà xuất bản Morphos\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '8697fe8e-4f21-459a-b9fd-31678a134e35';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Everlast Hospital Nursing Staff\", \"vi\": \"Kính gửi: Đội ngũ điều dưỡng Bệnh viện Everlast\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Gretchen Robertson\", \"vi\": \"Từ: Gretchen Robertson\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: February 3\", \"vi\": \"Ngày: 3 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Deonardo pilot testing\", \"vi\": \"Chủ đề: Thử nghiệm thí điểm Deonardo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Thank you for agreeing to work with the team at Cybernetic Robotics as they tested their new robot, Deonardo, in our hospital.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã đồng ý hợp tác cùng đội ngũ của Cybernetic Robotics trong quá trình họ thử nghiệm robot mới mang tên Deonardo tại bệnh viện của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As you know, Deonardo was developed to allow you, our nursing staff, more time to focus on patients.\", \"vi\": \"Như quý vị đã biết, Deonardo được phát triển nhằm giúp quý vị – đội ngũ nhân viên điều dưỡng của chúng tôi – có thêm thời gian để tập trung vào bệnh nhân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This is exciting work.\", \"vi\": \"Đây là một công việc đầy hứng khởi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It has been a month, and Cybernetic Robotics would like to hear about your experiences with Deonardo.\", \"vi\": \"Đã tròn một tháng trôi qua, và Cybernetic Robotics rất mong được lắng nghe những trải nghiệm của quý vị khi sử dụng Deonardo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please use the following link to complete an online survey.\", \"vi\": \"Kính mời quý vị sử dụng liên kết dưới đây để hoàn thành bản khảo sát trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The team especially wants to know about your experiences with Deonardo during the state reviewers\' inspection on January 28.\", \"vi\": \"Nhóm chúng tôi đặc biệt mong muốn được biết về những trải nghiệm của quý vị với Deonardo trong đợt thanh tra của các chuyên gia đánh giá cấp tiểu bang vào ngày 28 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"At the end of the survey, you may leave any additional comments you have about the robot.\", \"vi\": \"Khi kết thúc cuộc khảo sát, quý vị có thể để lại bất kỳ ý kiến bổ sung nào về con robot.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"www.cyberneticrobotics.com/survey/everlast/\", \"vi\": \"www.cyberneticrobotics.com/survey/everlast/\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Gretchen Robertson\", \"vi\": \"Gretchen Robertson\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Director, Everlast Hospital\", \"vi\": \"Giám đốc Bệnh viện Everlast\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"https://www.cyberneticrobotics.com/survey/everlast/01282\", \"vi\": \"https://www.cyberneticrobotics.com/survey/everlast/01282\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Deonardo is easy to work with.\", \"vi\": \"Deonardo là người rất dễ hợp tác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I like that I don\'t have to tell Deonardo directly what to do.\", \"vi\": \"Tôi thấy thích vì không cần phải trực tiếp chỉ bảo Deonardo phải làm gì.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"When I update patient information in our system, Deonardo\'s tasks are updated as well.\", \"vi\": \"Khi tôi cập nhật thông tin bệnh nhân trong hệ thống của chúng tôi, các nhiệm vụ của Deonardo cũng được cập nhật theo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I have been better able to concentrate on my patients because I know Deonardo takes care of little things that used to take up so much of my time.\", \"vi\": \"Tôi đã có thể tập trung hơn vào các bệnh nhân của mình vì biết rằng Deonardo sẽ lo liệu những việc lặt vặt vốn trước đây đã chiếm mất rất nhiều thời gian của tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Deonardo was particularly helpful during a recent state review because it delivered patients\' medications for all the nurses so that we didn\'t have to, and we were able to focus on patient care.\", \"vi\": \"Deonardo đã thể hiện sự hỗ trợ đặc biệt hữu ích trong đợt kiểm tra của cơ quan nhà nước gần đây, bởi hệ thống này đã đảm nhận việc phân phát thuốc cho bệnh nhân thay cho toàn bộ đội ngũ y tá, nhờ đó chúng tôi không phải lo việc này và có thể tập trung vào việc chăm sóc bệnh nhân.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I believe Deonardo helped us receive positive comments from the inspectors.\", \"vi\": \"Tôi tin rằng Deonardo đã giúp chúng tôi nhận được những nhận xét tích cực từ các thanh tra viên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I do wish Deonardo could respond to voice commands.\", \"vi\": \"Tôi thực sự mong Deonardo có thể phản hồi các lệnh bằng giọng nói.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"And occasionally, its wheels squeak as it moves around.\", \"vi\": \"Và thỉnh thoảng, bánh xe của nó phát ra tiếng kêu cót két khi di chuyển.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"But patients like watching it work, and everyone wants to take pictures with it.\", \"vi\": \"Tuy nhiên, các bệnh nhân rất thích được chứng kiến thiết bị này hoạt động, và ai cũng muốn chụp ảnh cùng nó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I wonder if you could get Deonardo to stand still for pictures?\", \"vi\": \"Tôi không biết liệu quý vị có thể nhờ Deonardo đứng yên để chụp ảnh được không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Lan Duy, BSN\", \"vi\": \"Lan Duy, BSN\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"To: Everlast Hospital Nursing Staff\", \"vi\": \"Kính gửi: Đội ngũ điều dưỡng Bệnh viện Everlast\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"From: Gretchen Robertson\", \"vi\": \"Từ: Gretchen Robertson\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Date: February 13\", \"vi\": \"Ngày: 13 tháng 2\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Subject: Deonardo in-house pilot\", \"vi\": \"Chủ đề: Chương trình thí điểm nội bộ Deonardo\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Thank you all for your help with Deonardo, our nursing robot.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã giúp đỡ Deonardo, chú robot điều dưỡng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I\'m glad that our staff has been able to take part in such groundbreaking work.\", \"vi\": \"Tôi rất vui vì đội ngũ nhân viên của chúng tôi đã có cơ hội tham gia vào công việc mang tính đột phá như vậy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Those of you who work directly with Deonardo can expect it to behave a bit differently in the coming week.\", \"vi\": \"Những ai đang làm việc trực tiếp với Deonardo có thể sẽ nhận thấy hệ thống này hoạt động hơi khác một chút trong tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"It will be programmed to perform some new tasks.\", \"vi\": \"Nó sẽ được lập trình để thực hiện một số nhiệm vụ mới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Previously, it waited at the nurse\'s station between tasks.\", \"vi\": \"Trước đây, nó thường chờ tại phòng y tá trong thời gian rảnh giữa các công việc.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Now, it will spend some of this time interacting with patients who may want to pose for pictures with it.\", \"vi\": \"Giờ đây, nó sẽ dành một phần thời gian này để tương tác với những bệnh nhân có thể muốn chụp ảnh cùng nó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"When Deonardo is in this socializing mode, the eyes on its LED face will be heart-shaped instead of the round eyes that indicate that it is in work mode.\", \"vi\": \"Khi Deonardo ở chế độ giao tiếp này, đôi mắt trên khuôn mặt LED của nó sẽ có hình trái tim thay vì đôi mắt tròn vốn cho thấy rằng nó đang ở chế độ làm việc.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Finally, the hospital will be purchasing two additional robots in the next few months to work in other areas of the hospital.\", \"vi\": \"Cuối cùng, bệnh viện sẽ mua thêm hai robot nữa trong vài tháng tới để triển khai hoạt động tại các khu vực khác của bệnh viện.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"I appreciate your willingness to work with this new technology.\", \"vi\": \"Tôi rất cảm kích trước sự sẵn lòng của quý vị trong việc áp dụng công nghệ mới này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"We look forward to learning how robots can further improve employee and patient experiences.\", \"vi\": \"Chúng tôi rất mong được tìm hiểu xem robot có thể góp phần nâng cao trải nghiệm của nhân viên và bệnh nhân như thế nào.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Gretchen Robertson\", \"vi\": \"Gretchen Robertson\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Director, Everlast Hospital\", \"vi\": \"Giám đốc Bệnh viện Everlast\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}]' WHERE `id` = '86a9299d-76d6-426c-9163-302bcaaddb2d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Langdale Exterior Solutions • 39 Alderson Road • Highfield, Sheffield S2 4UA\", \"vi\": \"Langdale Exterior Solutions • 39 Alderson Road • Highfield, Sheffield S2 4UA\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"17 September\", \"vi\": \"Ngày 17 tháng 9\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Mr. Atharv Chatterjee\", \"vi\": \"Ông Atharv Chatterjee\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"7 Croft Road\", \"vi\": \"7 Đường Croft\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Brinsworth, Rotherham S60 5AP\", \"vi\": \"Brinsworth, Rotherham S60 5AP\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Hello, Mr. Chatterjee,\", \"vi\": \"Xin chào, thưa ông Chatterjee,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Congratulations on the purchase of your new home!\", \"vi\": \"Xin chúc mừng quý vị đã mua được ngôi nhà mới!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I\'d like to introduce Langdale Exterior Solutions.\", \"vi\": \"Tôi xin được giới thiệu công ty Langdale Exterior Solutions.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We have worked with clients in the Sheffield area for over 30 years.\", \"vi\": \"Chúng tôi đã hợp tác với các khách hàng tại khu vực Sheffield trong hơn 30 năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Our team of experienced professionals makes us the most trusted landscape company in the area.\", \"vi\": \"Đội ngũ chuyên gia giàu kinh nghiệm của chúng tôi đã giúp công ty chúng tôi trở thành công ty thiết kế cảnh quan đáng tin cậy nhất trong khu vực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We can assist you in finding optimal solutions for your outdoor spaces at reasonable prices.\", \"vi\": \"Chúng tôi sẵn sàng hỗ trợ quý vị tìm ra những giải pháp tối ưu cho không gian ngoài trời của quý vị với mức giá hợp lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We perform services from lawn maintenance to tree and shrub care.\", \"vi\": \"Chúng tôi cung cấp các dịch vụ từ bảo dưỡng sân cỏ đến chăm sóc cây cối và cây bụi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"If you are interested in hardscape features such as brick pathways or rustic stone walls, we will provide recommendations on materials and styles that suit your tastes.\", \"vi\": \"Nếu quý vị quan tâm đến các yếu tố kiến trúc cảnh quan cứng như lối đi lát gạch hay những bức tường đá mộc mạc, chúng tôi sẽ đưa ra các đề xuất về vật liệu và phong cách phù hợp với sở thích của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We will even bring samples directly to you to help you make your design selections.\", \"vi\": \"Chúng tôi thậm chí còn mang mẫu trực tiếp đến tận nơi cho quý vị để hỗ trợ quý vị lựa chọn các phương án thiết kế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Call us today at 0114 496 0101 to schedule a free initial consultation.\", \"vi\": \"Hãy gọi cho chúng tôi ngay hôm nay theo số 0114 496 0101 để đặt lịch hẹn tư vấn ban đầu miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Tabatha Meyers\", \"vi\": \"Tabatha Meyers\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Tabatha Meyers, Owner, Langdale Exterior Solutions\", \"vi\": \"Bà Tabatha Meyers, Chủ sở hữu, Công ty Langdale Exterior Solutions\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '86b501c3-3a59-499e-a27a-9da17102d2bc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Name  LAURA CONSTANTINI - Division  CUSTOMER SUPPORT\", \"vi\": \"Họ tên: LAURA CONSTANTINI - Bộ phận: HỖ TRỢ KHÁCH HÀNG\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Employee No.  2378 - Employed at Lastico since  FEB 10\", \"vi\": \"Nhân viên số 2378 – Làm việc tại Lastico kể từ ngày 10 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Submitted  AUG 2 - Signed  Constantini\", \"vi\": \"Được đệ trình vào ngày 2 tháng 8 – Ký tên: Constantini\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Lastico Employee Badge\", \"vi\": \"Thẻ nhân viên Lastico\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Application Form\", \"vi\": \"Mẫu đơn đăng ký\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"To receive a new Lastico employee badge, please fill out the following form.\", \"vi\": \"Để nhận thẻ nhân viên mới của Lastico, xin vui lòng điền vào mẫu đơn sau đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Write in pen only.\", \"vi\": \"Chỉ được viết bằng bút mực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please PRINT clearly.\", \"vi\": \"Xin vui lòng viết CHỮ IN HOA rõ ràng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"My previous badge ☒ expired ☐ was lost ☐ was damaged\", \"vi\": \"Thẻ của tôi trước đây ☒ đã hết hạn ☐ bị mất ☐ bị hư hỏng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"(Leave blank if you are applying for the first time)\", \"vi\": \"(Vui lòng để trống nếu đây là lần đầu tiên quý vị nộp đơn)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '86f9ab08-44f2-4a8a-9e81-1acedbf0edc4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: noreply@electrimaxstores.com\", \"vi\": \"Nguồn: noreply@electrimaxstores.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: wtarnowski@mailzm.com\", \"vi\": \"Địa chỉ email: wtarnowski@mailzm.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: February 2\", \"vi\": \"Ngày: 2 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Repair request #2989231\", \"vi\": \"Chủ đề: Yêu cầu sửa chữa số #2989231\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Tarnowski,\", \"vi\": \"Kính gửi ông Tarnowski,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We are sorry to hear you are having trouble with the washing machine you purchased at an Electrimax store.\", \"vi\": \"Chúng tôi rất tiếc khi biết quý khách đang gặp sự cố với chiếc máy giặt mà quý khách đã mua tại cửa hàng Electrimax.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Your repair request has been received.\", \"vi\": \"Yêu cầu sửa chữa của quý khách đã được tiếp nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Within the next 24 hours, we will call you to set up a service appointment in your home.\", \"vi\": \"Trong vòng 24 giờ tới, chúng tôi sẽ gọi điện cho quý khách để sắp xếp một cuộc hẹn bảo trì tại nhà quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Note that at the time of service, our technician will ask to see the original receipt given to you when you purchased the machine.\", \"vi\": \"Xin lưu ý rằng tại thời điểm thực hiện dịch vụ, kỹ thuật viên của chúng tôi sẽ yêu cầu quý khách xuất trình hóa đơn gốc đã được cấp khi quý khách mua máy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please have it available.\", \"vi\": \"Xin vui lòng chuẩn bị sẵn tài liệu này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Thank you for using our online communication form.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã sử dụng biểu mẫu liên lạc trực tuyến của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We look forward to serving you.\", \"vi\": \"Chúng tôi rất mong được phục vụ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Electrimax Customer Service Team\", \"vi\": \"Đội ngũ Dịch vụ Khách hàng của Electrimax\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '871bca36-569f-4a11-a5d8-ef6d17584a1f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Call for Entries: Annual Sustainability Competition\", \"vi\": \"Thông báo mời tham gia: Cuộc thi Bền vững thường niên\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Sponsored by the League of New Zealand Builders\", \"vi\": \"Được tài trợ bởi Hiệp hội các nhà thầu xây dựng New Zealand\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"PURPOSE: The League of New Zealand Builders (LNZB) wants to recognize an individual whose contribution to a new construction features design innovations that are environmentally friendly.\", \"vi\": \"MỤC ĐÍCH: Liên đoàn các nhà thầu xây dựng New Zealand (LNZB) mong muốn vinh danh một cá nhân có đóng góp cho công trình xây dựng mới thông qua những sáng tạo trong thiết kế thân thiện với môi trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The winner will be featured at an on-site celebration and show guests and journalists around the finished building, explaining its environmental highlights.\", \"vi\": \"Người chiến thắng sẽ được vinh danh tại buổi lễ kỷ niệm diễn ra ngay tại công trình và sẽ dẫn các khách mời cùng các nhà báo tham quan tòa nhà đã hoàn thiện, đồng thời giải thích về những điểm nổi bật về mặt môi trường của công trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"ENTRANTS: Priority consideration will be given to members of the LNZB, but any professional builder who completes a project in New Zealand before 15 December of this year may apply.\", \"vi\": \"ĐỐI TƯỢNG THAM GIA: Các thành viên của LNZB sẽ được ưu tiên xem xét, tuy nhiên bất kỳ nhà thầu chuyên nghiệp nào hoàn thành một dự án tại New Zealand trước ngày 15 tháng 12 năm nay đều có thể nộp đơn tham gia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Go to the LNZB Web site for the submission form.\", \"vi\": \"Vui lòng truy cập trang web của LNZB để tải mẫu đơn đăng ký.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"DUE DATE: All submissions are due by 15 December.\", \"vi\": \"HẠN CHÓT: Tất cả các bài nộp phải được gửi trước ngày 15 tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"JUDGING PROCESS: The application and vetting process includes several steps.\", \"vi\": \"QUY TRÌNH ĐÁNH GIÁ: Quy trình nộp đơn và thẩm định bao gồm một số bước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"After screening the candidates, judges will choose semifinalists.\", \"vi\": \"Sau khi xem xét các ứng viên, ban giám khảo sẽ chọn ra những thí sinh lọt vào vòng bán kết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Then a special panel will choose this year\'s recipient.\", \"vi\": \"Sau đó, một hội đồng chuyên trách sẽ lựa chọn người được vinh danh trong năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"FOR MORE INFORMATION: Visit www.leagueofnewzealandbuilders.org.nz to learn more about the LNZB and past winners.\", \"vi\": \"ĐỂ BIẾT THÊM THÔNG TIN: Quý vị vui lòng truy cập trang web www.leagueofnewzealandbuilders.org.nz để tìm hiểu thêm về Giải thưởng LNZB và các cá nhân đã từng đoạt giải.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Rahotu Wins LNZB Prize\", \"vi\": \"Ông Rahotu giành giải thưởng LNZB\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"(17 March)-The League of New Zealand Builders (LNZB) yesterday announced that Maia Rahotu won this year\'s Sustainability Competition.\", \"vi\": \"(Ngày 17 tháng 3) – Hiệp hội Các nhà thầu Xây dựng New Zealand (LNZB) hôm qua đã công bố rằng bà Maia Rahotu đã giành chiến thắng trong Cuộc thi Bền vững năm nay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Ms. Rahotu, whose work on building designs throughout New Zealand goes back many years, won the award for her design of the Rowan Community Centre.\", \"vi\": \"Bà Rahotu, người đã có nhiều năm kinh nghiệm trong lĩnh vực thiết kế công trình trên khắp New Zealand, đã giành được giải thưởng nhờ thiết kế Trung tâm Cộng đồng Rowan.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The centre utilized renewable and recycled materials throughout its construction.\", \"vi\": \"Trong suốt quá trình xây dựng, trung tâm này đã sử dụng các vật liệu tái tạo và tái chế.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"In April, Ms. Rahotu will be formally presented with the award during the ceremony at the centre; details will be announced soon.\", \"vi\": \"Vào tháng 4, bà Rahotu sẽ chính thức được trao giải thưởng trong buổi lễ diễn ra tại trung tâm; thông tin chi tiết sẽ được công bố trong thời gian tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"\\\"It was a tough decision this year,\\\" said LNZB\'s director, Thomas Young.\", \"vi\": \"\\\"Đây là một quyết định khó khăn trong năm nay,\\\" ông Thomas Young, Giám đốc của LNZB, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"\\\"All applicants chose materials that minimize environmental impact.\", \"vi\": \"\\\"Tất cả các ứng viên đều lựa chọn các vật liệu giúp giảm thiểu tác động đến môi trường.\\\"\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"But we were able to narrow the candidates to three top choices, each of whom was interviewed by our panel of experts.\\\"\", \"vi\": \"“Tuy nhiên, chúng tôi đã có thể thu hẹp danh sách ứng viên xuống còn ba ứng viên hàng đầu, và mỗi người trong số họ đều đã được ban giám khảo gồm các chuyên gia của chúng tôi phỏng vấn.”\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Building components in the Rowan project were thoughtfully selected by Ms. Rahotu to minimize environmental impact, Young added.\", \"vi\": \"Ông Young cho biết thêm, các vật liệu xây dựng trong dự án Rowan đã được bà Rahotu lựa chọn một cách cẩn trọng nhằm giảm thiểu tác động đến môi trường.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"\\\"However, what is exceptional about Ms. Rahotu\'s design is how well it harvests solar energy.\\\"\", \"vi\": \"\\\"Tuy nhiên, điều đặc biệt trong thiết kế của bà Rahotu chính là khả năng khai thác năng lượng mặt trời một cách hiệu quả.\\\"\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"According to experts at LNZB, her solar design generates a high surplus of electricity beyond the building\'s requirements.\", \"vi\": \"Theo các chuyên gia tại LNZB, hệ thống năng lượng mặt trời do bà thiết kế tạo ra lượng điện dư thừa rất lớn, vượt xa nhu cầu sử dụng của tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"This surplus is transmitted to the region\'s power grid-in effect reducing strain on local energy production.\", \"vi\": \"Lượng điện dư thừa này được truyền vào lưới điện của khu vực – qua đó giúp giảm bớt áp lực lên hoạt động sản xuất năng lượng tại địa phương.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '871d0001-8990-4ce7-b354-03e055da6291';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.orvalenaturalhistorymuseum.org/upcomingevents\", \"vi\": \"https://www.orvalenaturalhistorymuseum.org/upcomingevents\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Orvale Natural History Museum\'s monthly lecture series will continue on October 18 with a lecture by resident archaeologist Dr. Maria Fiallo.\", \"vi\": \"Chuỗi bài giảng hàng tháng của Bảo tàng Lịch sử Tự nhiên Orvale sẽ tiếp tục vào ngày 18 tháng 10 với bài giảng của Tiến sĩ Maria Fiallo, nhà khảo cổ học thường trú tại bảo tàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The lecture, titled \\\"Earthenware Relics from the Central Prairie,\\\" will take place at 7:00 P.M. in the Chovey Community Room near the north entrance of the museum.\", \"vi\": \"Buổi thuyết trình mang tên “Các di vật gốm từ vùng đồng cỏ miền Trung” sẽ diễn ra vào lúc 7 giờ tối tại Phòng sinh hoạt cộng đồng Chovey, gần lối vào phía bắc của bảo tàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Dr. Fiallo will discuss last month\'s unearthing of several pottery pieces in the Central Prairie region, marking the first find of its kind in this area.\", \"vi\": \"Tiến sĩ Fiallo sẽ trình bày về việc khai quật được một số mảnh gốm tại khu vực Đồng cỏ Trung tâm vào tháng trước, đánh dấu lần phát hiện đầu tiên thuộc loại này tại khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"Surprisingly,\\\" said Dr. Fiallo, \\\"the site was literally stumbled upon by a farmer digging a well on his land.\", \"vi\": \"\\\"Điều đáng ngạc nhiên là,\\\" Tiến sĩ Fiallo nói, \\\"khu di tích này thực sự được một người nông dân tình cờ phát hiện khi đang đào giếng trên mảnh đất của mình.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thankfully, he alerted our museum\'s research team as soon as he spotted the pieces.\\\"\", \"vi\": \"May mắn thay, ngay khi phát hiện ra những hiện vật này, ông đã thông báo ngay cho nhóm nghiên cứu của bảo tàng chúng tôi.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Audiences will get to see some of the earthenware up close at the event, as well as other types of everyday objects.\", \"vi\": \"Tại sự kiện này, quý vị sẽ có cơ hội chiêm ngưỡng cận cảnh một số đồ gốm, cũng như các loại đồ dùng sinh hoạt hàng ngày khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"However, many of the pieces will be shown in photographs, as they are too delicate to be moved around.\", \"vi\": \"Tuy nhiên, nhiều tác phẩm sẽ được trưng bày dưới dạng ảnh, do chúng quá mỏng manh nên không thể di chuyển được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Dr. Fiallo says she is looking forward to sharing this latest discovery.\", \"vi\": \"Tiến sĩ Fiallo cho biết bà rất mong được chia sẻ phát hiện mới nhất này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"\\\"The findings give us a glimpse into how people went about their daily lives over 800 years ago,\\\" she said.\", \"vi\": \"\\\"Những phát hiện này giúp chúng ta phần nào hình dung được cuộc sống hàng ngày của con người cách đây hơn 800 năm,\\\" bà nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The lecture is free and open to the public.\", \"vi\": \"Buổi thuyết trình này miễn phí và mở cửa cho công chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"HomeExhibitsUpcoming EventsContact Us\", \"vi\": \"Trang chủ | Triển lãm | Các sự kiện sắp tới | Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To: Richard Choi\", \"vi\": \"Kính gửi: Richard Choi\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"From: Deborah Voll\", \"vi\": \"Từ: Deborah Voll\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date: October 11\", \"vi\": \"Ngày: 11 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Subject: Lecture series\", \"vi\": \"Chủ đề: Chuỗi bài giảng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Hi, Richard,\", \"vi\": \"Xin chào, Richard,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I was just contacted by Professor Allen Whitford from Orvale University\'s archaeology department.\", \"vi\": \"Tôi vừa nhận được liên hệ từ Giáo sư Allen Whitford thuộc Khoa Khảo cổ học của Đại học Orvale.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"He would like to bring two of his classes to Dr. Fiallo\'s lecture on October 18.\", \"vi\": \"Ông mong muốn dẫn hai lớp học của mình đến tham dự buổi thuyết trình của Tiến sĩ Fiallo vào ngày 18 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Both classes are studying how to identify and analyze historical artifacts, so he was very happy with the topic of our lecture this month.\", \"vi\": \"Cả hai lớp đều đang học cách nhận diện và phân tích các hiện vật lịch sử, vì vậy anh ấy rất hài lòng với chủ đề bài giảng của chúng tôi trong tháng này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"What\'s more, Professor Whitford is a former research colleague of Dr. Fiallo.\", \"vi\": \"Hơn nữa, Giáo sư Whitford từng là đồng nghiệp nghiên cứu của Tiến sĩ Fiallo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I am inclined to indicate my support, but I just want to make sure we can accommodate the approximately 30 students he is planning to bring—in addition, of course, to members of the public who want to attend.\", \"vi\": \"Tôi có ý định bày tỏ sự ủng hộ, nhưng tôi chỉ muốn đảm bảo rằng chúng ta có thể tiếp đón khoảng 30 học sinh mà anh ấy dự định đưa đến — ngoài ra, tất nhiên, còn có những người dân muốn tham dự.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"We will need more than 75 seats, so let\'s discuss moving the lecture to another location in the museum.\", \"vi\": \"Chúng ta sẽ cần hơn 75 chỗ ngồi, vì vậy chúng ta hãy thảo luận về việc chuyển buổi thuyết trình sang một địa điểm khác trong bảo tàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"There are a couple of alternative spaces, right?\", \"vi\": \"Có một vài không gian thay thế, phải không ạ?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I would like to reply to Professor Whitford as soon as possible.\", \"vi\": \"Tôi mong muốn được trả lời Giáo sư Whitford càng sớm càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Thanks!\", \"vi\": \"Cảm ơn!\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Deb\", \"vi\": \"Deb\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"To: Maria Fiallo <mfiallo@orvalenaturalhistorymuseum.org>\", \"vi\": \"Gửi tới: Maria Fiallo <mfiallo@orvalenaturalhistorymuseum.org>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"From: Allen Whitford <awhitford@orvaleuniversity.edu>\", \"vi\": \"Từ: Allen Whitford <awhitford@orvaleuniversity.edu>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Date: October 19\", \"vi\": \"Ngày: 19 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Subject: Lecture\", \"vi\": \"Chủ đề: Buổi giảng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Dear Dr. Fiallo,\", \"vi\": \"Kính gửi Tiến sĩ Fiallo,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Thanks so much for your informative lecture yesterday evening.\", \"vi\": \"Xin chân thành cảm ơn quý vị về bài giảng đầy thông tin vào tối hôm qua.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"My students were thrilled to see some of the pottery up close on the display table.\", \"vi\": \"Các học sinh của tôi đã vô cùng phấn khích khi được chiêm ngưỡng một số tác phẩm gốm sứ trên bàn trưng bày từ khoảng cách gần.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"They were especially impressed by the stone tools included among the items.\", \"vi\": \"Họ đặc biệt ấn tượng với những dụng cụ bằng đá có trong số các hiện vật này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"That these artifacts were so close by all this time was truly amazing for my students to contemplate.\", \"vi\": \"Việc những hiện vật này lại nằm ngay gần đây suốt thời gian qua thực sự là điều đáng kinh ngạc đối với các học sinh của tôi khi suy ngẫm về điều đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"I am so glad the pieces are safe at the Orvale Natural History Museum, which I know to be a good steward of such treasures.\", \"vi\": \"Tôi thực sự rất vui mừng khi các hiện vật này đang được bảo quản an toàn tại Bảo tàng Lịch sử Tự nhiên Orvale, nơi mà tôi biết là đơn vị biết trân trọng và bảo quản những báu vật như vậy một cách chu đáo.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"I hope you will consider my invitation to collaborate with my team and me here at Orvale University on some exciting research projects we have planned.\", \"vi\": \"Tôi hy vọng quý vị sẽ cân nhắc lời mời của tôi để hợp tác cùng tôi và nhóm nghiên cứu của tôi tại Đại học Orvale trong một số dự án nghiên cứu đầy hứa hẹn mà chúng tôi đã lên kế hoạch.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Let me know if you are interested, and I will forward the details.\", \"vi\": \"Nếu quý vị quan tâm, xin vui lòng cho tôi biết, và tôi sẽ gửi thông tin chi tiết cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Allen Whitford\", \"vi\": \"Allen Whitford\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}]' WHERE `id` = '876f6bcc-6ba5-4293-a7ac-0ea859a04336';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Cavalina Hotel\", \"vi\": \"Khách sạn Cavalina\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Blue Globe Magazine\'s \\\"Best Hotel\\\" Award Winner!\", \"vi\": \"Đơn vị đoạt giải “Khách sạn xuất sắc nhất” do Tạp chí Blue Globe bình chọn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Cavalina Hotel is a breathtaking sanctuary where guests can escape the hectic bustle of city life.\", \"vi\": \"Khách sạn Cavalina là một chốn nghỉ dưỡng tuyệt đẹp, nơi quý khách có thể tạm rời xa nhịp sống hối hả của thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Located 50 kilometers from the international airport in Jeel City, the hotel faces the beautiful Sea Mariner Bay.\", \"vi\": \"Nằm cách sân bay quốc tế thành phố Jeel 50 kilômét, khách sạn tọa lạc ngay bên vịnh Sea Mariner xinh đẹp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Windsurfing, paddleboarding, and several hiking and biking trails are all a short walk from our front door.\", \"vi\": \"Các hoạt động như lướt ván buồm, chèo ván đứng cùng nhiều tuyến đường đi bộ và đạp xe đều nằm cách cửa nhà chúng tôi chỉ một quãng đường ngắn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our knowledgeable staff are happy to arrange a kayaking excursion or a fishing trip to one of the nearby lakes.\", \"vi\": \"Đội ngũ nhân viên giàu kinh nghiệm của chúng tôi rất hân hạnh được sắp xếp cho quý vị một chuyến tham quan bằng thuyền kayak hoặc một chuyến câu cá tại một trong những hồ nước lân cận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"After a good night\'s sleep in one of our comfortable rooms, you\'ll be eager to explore the region right after breakfast!\", \"vi\": \"Sau một giấc ngủ ngon trong một trong những phòng nghỉ tiện nghi của chúng tôi, quý khách sẽ háo hức khám phá khu vực này ngay sau bữa sáng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Property Amenities: free parking, swimming pool, bicycle rental, fitness center, two restaurants\", \"vi\": \"Các tiện ích của khu căn hộ: bãi đỗ xe miễn phí, hồ bơi, dịch vụ cho thuê xe đạp, trung tâm thể dục thể hình, hai nhà hàng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Room Types: single room, two-room suite with balcony, two-room suite with kitchen\", \"vi\": \"Các loại phòng: phòng đơn, phòng suite hai phòng có ban công, phòng suite hai phòng có bếp\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '88176e46-9309-4eb9-81eb-2c7393baea9e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Maria Andreou (9:06 A.M.)\", \"vi\": \"Maria Andreou (9 giờ 06 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Good morning, Jakob and Sandra.\", \"vi\": \"Chào buổi sáng, Jakob và Sandra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I need help with the focus group with the photographers that is taking place on Thursday morning.\", \"vi\": \"Tôi cần sự hỗ trợ cho buổi thảo luận nhóm với các nhiếp ảnh gia sẽ diễn ra vào sáng thứ Năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I\'m no longer available to lead it.\", \"vi\": \"Tôi không còn có thể đảm nhận vai trò lãnh đạo dự án này nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Jakob Wendt (9:09 A.M.)\", \"vi\": \"Jakob Wendt (9 giờ 09 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"That\'s unfortunate.\", \"vi\": \"Thật đáng tiếc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We need to follow up with that meeting to advise our client about what is important to potential customers.\", \"vi\": \"Chúng ta cần có những bước tiếp theo sau cuộc họp đó để tư vấn cho khách hàng của chúng ta về những yếu tố quan trọng đối với khách hàng tiềm năng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Maria Andreou (9:10 A.M.)\", \"vi\": \"Maria Andreou (9 giờ 10 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Exactly.\", \"vi\": \"Chính xác.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"So I would rather not have to reschedule.\", \"vi\": \"Vì vậy, tôi thực sự không muốn phải dời lịch.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The client is expecting our report early next week.\", \"vi\": \"Khách hàng đang mong đợi báo cáo của chúng tôi vào đầu tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Would either of you be able to conduct the group instead of me?\", \"vi\": \"Có ai trong hai vị có thể dẫn dắt nhóm thay cho tôi không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sandra Liu (9:12 A.M.)\", \"vi\": \"Sandra Liu (9 giờ 12 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sorry, Maria.\", \"vi\": \"Xin lỗi, Maria.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I\'m traveling out of town tomorrow for the marketing conference, and won\'t be back until Friday.\", \"vi\": \"Ngày mai tôi sẽ đi công tác xa để tham dự hội nghị tiếp thị, và sẽ không trở về cho đến thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Jakob Wendt (9:15 A.M.)\", \"vi\": \"Jakob Wendt (9 giờ 15 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I\'ve never led a focus group before, but I\'m happy to do it.\", \"vi\": \"Tôi chưa từng chủ trì một nhóm thảo luận trước đây, nhưng tôi rất sẵn lòng đảm nhận việc này.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Maria Andreou (9:17 A.M.)\", \"vi\": \"Maria Andreou (9 giờ 17 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Great.\", \"vi\": \"Tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I\'ll send you the participant consent form by e-mail.\", \"vi\": \"Tôi sẽ gửi cho quý vị mẫu đơn đồng ý tham gia qua email.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Remember that at the start of the group session, each participant will need to sign a copy.\", \"vi\": \"Xin lưu ý rằng vào đầu buổi họp nhóm, mỗi người tham gia sẽ cần ký vào một bản sao.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Jakob Wendt (9:18 A.M.)\", \"vi\": \"Jakob Wendt (9 giờ 18 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"How many copies will be needed?\", \"vi\": \"Sẽ cần bao nhiêu bản?\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Sandra Liu (9:19 A.M.)\", \"vi\": \"Sandra Liu (9 giờ 19 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 7, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Actually, there\'s no need.\", \"vi\": \"Thực ra, không cần thiết đâu.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I have copies left over from another group I ran last Tuesday.\", \"vi\": \"Tôi còn một số bản sao dư lại từ một nhóm khác mà tôi đã tổ chức vào thứ Ba tuần trước.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"They\'re still on my desk.\", \"vi\": \"Chúng vẫn còn nằm trên bàn làm việc của tôi.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Jakob Wendt (9:20 A.M.)\", \"vi\": \"Jakob Wendt (9 giờ 20 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 8, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I\'ll stop by and pick them up later today.\", \"vi\": \"Tôi sẽ ghé qua và lấy chúng vào cuối ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Maria Andreou (9:21 A.M)\", \"vi\": \"Maria Andreou (9 giờ 21 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 9, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Thank you both.\", \"vi\": \"Xin cảm ơn cả hai quý vị.\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"This means we can meet and work on the advertising report for the client next Monday.\", \"vi\": \"Điều này có nghĩa là chúng ta có thể gặp nhau và cùng hoàn thiện báo cáo quảng cáo cho khách hàng vào thứ Hai tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '882c8c6f-4ac8-464c-a8af-be3933c5b068';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Zevk Black Tea\", \"vi\": \"Trà đen Zevk\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Turkey boasts some of the best premium black tea blends in the world.\", \"vi\": \"Thổ Nhĩ Kỳ tự hào sở hữu một số loại trà đen pha trộn cao cấp hàng đầu thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Zevk (the Turkish word for \\\"delight\\\") is no exception—and has fifty years of commercial success to prove it.\", \"vi\": \"Zevk (từ tiếng Thổ Nhĩ Kỳ có nghĩa là “niềm vui”) cũng không phải là ngoại lệ — và đã có 50 năm thành công trên thị trường để chứng minh điều đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"To be truly hospitable to your guests Turkish style, serve it in tall clear glasses so that they can admire the changing colors of Zevk tea as it brews.\", \"vi\": \"Để thể hiện sự hiếu khách theo phong cách Thổ Nhĩ Kỳ một cách trọn vẹn, xin hãy phục vụ trà Zevk trong những chiếc ly cao và trong suốt, để quý khách có thể chiêm ngưỡng sắc màu biến đổi của trà Zevk trong quá trình pha chế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Accompany with biscuits or sweets.\", \"vi\": \"Hãy dùng kèm với bánh quy hoặc kẹo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Directions: Fill a pouch with Zevk tea and put it in a glass.\", \"vi\": \"Hướng dẫn sử dụng: Cho một túi trà Zevk vào cốc thủy tinh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Pour in boiling water and let steep.\", \"vi\": \"Đổ nước sôi vào và để ngâm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Sweeten to taste.\", \"vi\": \"Hãy cho đường vào cho vừa miệng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Product of Turkey\", \"vi\": \"Sản phẩm của Thổ Nhĩ Kỳ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Net Weight 250 g.\", \"vi\": \"Trọng lượng tịnh: 250 g.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Packaged exclusively for ABD Exports.\", \"vi\": \"Được đóng gói dành riêng cho ABD Exports.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Use within six months of package date for best taste.\", \"vi\": \"Để có hương vị ngon nhất, xin vui lòng sử dụng trong vòng sáu tháng kể từ ngày đóng gói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '88384280-efb8-41be-95b9-49af79e8b878';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.projectelements.com\", \"vi\": \"http://www.projectelements.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"All of your project management needs—All in one place—All online.\", \"vi\": \"Tất cả các nhu cầu về quản lý dự án của quý vị — Tất cả đều tập trung tại một nơi — Hoàn toàn trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Project Elements LLC develops project management software for use in companies both small and large.\", \"vi\": \"Công ty Project Elements LLC phát triển phần mềm quản lý dự án dành cho các doanh nghiệp, từ quy mô nhỏ đến quy mô lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Our proprietary software will serve you from start to finish, helping your teams to communicate, schedule, and manage information.\", \"vi\": \"Phần mềm độc quyền của chúng tôi sẽ đồng hành cùng quý vị từ đầu đến cuối, hỗ trợ các đội ngũ của quý vị trong việc giao tiếp, lập lịch trình và quản lý thông tin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Team Basic\", \"vi\": \"Đội Cơ bản\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Get your team of five started with our Basic solution.\", \"vi\": \"Hãy bắt đầu với đội ngũ gồm năm thành viên của quý vị bằng giải pháp Cơ bản của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Task management, file sharing, and mobile accessibility will be at your fingertips.\", \"vi\": \"Quản lý công việc, chia sẻ tệp tin và khả năng truy cập trên thiết bị di động sẽ nằm ngay trong tầm tay quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Add 100 GB of online data storage space in the cloud for a small additional fee.\", \"vi\": \"Chỉ với một khoản phí bổ sung nhỏ, quý vị sẽ được bổ sung 100 GB dung lượng lưu trữ dữ liệu trực tuyến trên đám mây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Team Creative\", \"vi\": \"Đội ngũ Sáng tạo\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This option is the best solution for small teams of up to 35 creative professionals.\", \"vi\": \"Tùy chọn này là giải pháp tối ưu dành cho các nhóm nhỏ có tối đa 35 chuyên gia sáng tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"In addition to all the Team Basic features, get video editing tools, graphic design software, and 300 GB of cloud storage for all of your design needs.\", \"vi\": \"Ngoài tất cả các tính năng của gói Team Basic, quý vị còn được sử dụng các công cụ chỉnh sửa video, phần mềm thiết kế đồ họa và 300 GB dung lượng lưu trữ đám mây để đáp ứng mọi nhu cầu thiết kế của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Team Player\", \"vi\": \"Người biết hợp tác\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Teams of up to 50 excel with this enhanced service.\", \"vi\": \"Các nhóm có tối đa 50 thành viên sẽ phát huy tối đa hiệu quả nhờ dịch vụ được nâng cấp này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Get all the features of Team Basic, plus timelines, advanced integration with second-party platforms, and up to 400 GB of cloud space for your team.\", \"vi\": \"Quý vị sẽ được sử dụng tất cả các tính năng của gói Team Basic, cùng với các dòng thời gian, khả năng tích hợp nâng cao với các nền tảng bên thứ hai và dung lượng lưu trữ đám mây lên đến 400 GB dành cho nhóm của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Team Leader\", \"vi\": \"Trưởng nhóm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"This option is best for teams of up to 100.\", \"vi\": \"Tùy chọn này phù hợp nhất cho các nhóm có tối đa 100 thành viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Get all of the features of Team Player, plus enhanced options for personalization, resource tracking, time tracking, 500 GB of cloud space, and fast video uploads for a seamless team experience.\", \"vi\": \"Hãy tận hưởng tất cả các tính năng của Team Player, cùng với các tùy chọn nâng cao về cá nhân hóa, theo dõi tài nguyên, theo dõi thời gian, 500 GB dung lượng lưu trữ trên đám mây và tính năng tải lên video nhanh chóng, nhằm mang lại trải nghiệm làm việc nhóm mượt mà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Need more convincing?\", \"vi\": \"Còn cần thêm lý do thuyết phục không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We were recognized for our software quality with the Gold Star Start-Up Awards by Work Winner Magazine two years in a row.\", \"vi\": \"Chúng tôi đã được Tạp chí Work Winner vinh danh về chất lượng phần mềm thông qua Giải thưởng Gold Star Start-Up trong hai năm liên tiếp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"To hear more about Project Elements success stories, check out our client testimonials in the About Us tab.\", \"vi\": \"Để tìm hiểu thêm về những câu chuyện thành công của Project Elements, xin mời quý vị tham khảo các lời chứng thực từ khách hàng của chúng tôi tại mục “Giới thiệu về chúng tôi”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Team Plans\", \"vi\": \"Kế hoạch của đội\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"About Us\", \"vi\": \"Giới thiệu về chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Resources\", \"vi\": \"Tài nguyên\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"FAQ\", \"vi\": \"Các câu hỏi thường gặp\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"To: ebennis@projectelements.com\", \"vi\": \"Gửi tới: ebennis@projectelements.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"From: jasbury@clarelcommunications.com\", \"vi\": \"Nguồn: jasbury@clarelcommunications.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Subject: Project Elements Upgrade\", \"vi\": \"Chủ đề: Nâng cấp các thành phần dự án\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Date: December 5\", \"vi\": \"Ngày: 5 tháng 12\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Dear Mr. Bennis,\", \"vi\": \"Kính gửi ông Bennis,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I am the new director of digital advertising for Clarel Communications.\", \"vi\": \"Tôi là Giám đốc mới phụ trách mảng quảng cáo kỹ thuật số tại Clarel Communications.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Robert Roust, the former director, told me how valuable the Project Elements platform has been, and I want to explore with you a potential change in Clarel\'s current plan.\", \"vi\": \"Ông Robert Roust, cựu giám đốc, đã chia sẻ với tôi về giá trị to lớn của nền tảng Project Elements, và tôi mong muốn cùng quý vị thảo luận về một sự điều chỉnh tiềm năng trong kế hoạch hiện tại của Clarel.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"We are presently a team of 45 but anticipate growing to 55 members over the next year.\", \"vi\": \"Hiện tại, chúng tôi là một đội ngũ gồm 45 thành viên, nhưng dự kiến sẽ tăng lên 55 thành viên trong năm tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"The team likes the storage feature, but they would be interested in a plan with more than 400 GB and better personalization options.\", \"vi\": \"Nhóm rất ưng ý với tính năng lưu trữ, nhưng họ mong muốn có một gói dịch vụ cung cấp dung lượng lớn hơn 400 GB và các tùy chọn cá nhân hóa tốt hơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Is there a plan that will fit our needs?\", \"vi\": \"Có gói dịch vụ nào phù hợp với nhu cầu của chúng tôi không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Looking forward to hearing from you,\", \"vi\": \"Rất mong nhận được phản hồi từ quý vị,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Julia Asbury\", \"vi\": \"Julia Asbury\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Director of Digital Advertising\", \"vi\": \"Giám đốc Bộ phận Quảng cáo Kỹ thuật số\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Clarel Communications\", \"vi\": \"Clarel Communications\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 38, \"question_numbers\": []}]' WHERE `id` = '884f260a-8fb3-4739-85cc-b139d56a6996';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Sanaa Rahija <srahija@wilmawindows.co.nz>\", \"vi\": \"Gửi: Sanaa Rahija <srahija@wilmawindows.co.nz>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Zack Makoare <zmakoare@croydonconstruction.co.nz>\", \"vi\": \"Từ: Zack Makoare <zmakoare@croydonconstruction.co.nz>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 15 August\", \"vi\": \"Ngày: 15 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Shipment overdue\", \"vi\": \"Chủ đề: Lô hàng quá hạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"https://www.croydonconstruction.co.nz/news\", \"vi\": \"https://www.croydonconstruction.co.nz/news\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Home | News | Jobs | Contact Us\", \"vi\": \"Trang chủ | Tin tức | Tuyển dụng | Liên hệ với chúng tôi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In December, Croydon Construction will mark 25 years in business on the South Island of New Zealand.\", \"vi\": \"Vào tháng 12, Công ty Xây dựng Croydon sẽ kỷ niệm 25 năm hoạt động tại Đảo Nam của New Zealand.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We take great pride in the many buildings we have built here in Christchurch, where our headquarters are located, and in other locations along the South Island\'s east coast.\", \"vi\": \"Chúng tôi vô cùng tự hào về rất nhiều công trình mà chúng tôi đã xây dựng tại Christchurch – nơi đặt trụ sở chính của công ty – cũng như tại các địa điểm khác dọc theo bờ biển phía đông của Đảo Nam.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We have been busy recently with some exciting projects.\", \"vi\": \"Gần đây, chúng tôi đã rất bận rộn với một số dự án thú vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In Christchurch, we are building the Willoughby Medical Clinic on Grove Road, with a grand opening date of 1 November, and we are expanding the Blakefield Community Centre on Springdale Avenue.\", \"vi\": \"Tại Christchurch, chúng tôi đang xây dựng Phòng khám Y tế Willoughby trên đường Grove, dự kiến khai trương vào ngày 1 tháng 11, đồng thời chúng tôi cũng đang mở rộng Trung tâm Cộng đồng Blakefield trên đại lộ Springdale.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"In Ashburton, we have nearly finished a 107-unit apartment complex on Passerine Way and have just broken ground on the new wing of the Dismus School on Sixth Street.\", \"vi\": \"Tại Ashburton, chúng tôi đã gần hoàn thành một khu chung cư gồm 107 căn hộ trên đường Passerine Way và vừa khởi công xây dựng khu nhà mới của Trường Dismus trên đường Sixth Street.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Steve Kogler is our new chief site engineer.\", \"vi\": \"Ông Steve Kogler là Kỹ sư trưởng công trường mới của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Are you interested in employment with Croydon Construction?\", \"vi\": \"Quý vị có quan tâm đến cơ hội việc làm tại Croydon Construction không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We\'re hiring for both office and jobsite positions.\", \"vi\": \"Chúng tôi đang tuyển dụng cho cả các vị trí làm việc tại văn phòng lẫn tại công trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Go to our Jobs page to view open positions and to apply.\", \"vi\": \"Vui lòng truy cập trang Tuyển dụng của chúng tôi để xem các vị trí đang tuyển dụng và nộp đơn ứng tuyển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dear Ms. Rahija:\", \"vi\": \"Kính gửi bà Rahija:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I am writing to check on the status of order 47992, which should have arrived here by 31 July and is now two weeks overdue.\", \"vi\": \"Tôi viết thư này để hỏi về tình trạng đơn hàng số 47992, vốn lẽ ra phải được giao đến đây trước ngày 31 tháng 7 nhưng hiện đã trễ hạn hai tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We are extremely concerned.\", \"vi\": \"Chúng tôi vô cùng lo ngại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The building\'s completion date cannot be postponed.\", \"vi\": \"Thời hạn hoàn thành công trình không thể được hoãn lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Please let me know when we can expect our windows to arrive.\", \"vi\": \"Xin vui lòng cho tôi biết khi nào chúng ta có thể nhận được các cửa sổ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We shall withhold the balance of payment until the items have been received.\", \"vi\": \"Chúng tôi sẽ tạm giữ phần còn lại của khoản thanh toán cho đến khi nhận được các mặt hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Wilma Windows has been our supplier for many years, and this is the first time a problem like this has occurred.\", \"vi\": \"Wilma Windows đã là nhà cung cấp của chúng tôi trong nhiều năm qua, và đây là lần đầu tiên xảy ra một sự cố như thế này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Thank you for your prompt attention to this matter.\", \"vi\": \"Xin chân thành cảm ơn Quý vị đã quan tâm và xử lý kịp thời vấn đề này.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Zack Makoare\", \"vi\": \"Zack Makoare\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Construction Manager, Croydon Construction\", \"vi\": \"Giám đốc Công trình, Công ty Xây dựng Croydon\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"To: Zack Makoare <zmakoare@croydonconstruction.co.nz>\", \"vi\": \"Gửi: Zack Makoare <zmakoare@croydonconstruction.co.nz>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"From: Sanaa Rahija <srahija@wilmawindows.co.nz>\", \"vi\": \"Từ: Sanaa Rahija <srahija@wilmawindows.co.nz>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Date: 16 August\", \"vi\": \"Ngày: 16 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Subject: RE: Shipment overdue\", \"vi\": \"Chủ đề: RE: Lô hàng quá hạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"E-Mail Message\", \"vi\": \"Thông điệp email\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Dear Mr. Makoare:\", \"vi\": \"Kính gửi ông Makoare,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Please accept my apologies for the lateness of order 47992.\", \"vi\": \"Kính xin quý vị thông cảm về sự chậm trễ trong việc giao đơn hàng số 47992.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"A machine in our factory malfunctioned, creating flaws in the window glass.\", \"vi\": \"Một chiếc máy trong nhà máy của chúng tôi đã gặp sự cố, dẫn đến việc kính cửa sổ bị lỗi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"The machine has been repaired, and the factory is back to its usual production schedule.\", \"vi\": \"Máy móc đã được sửa chữa xong, và nhà máy đã trở lại lịch trình sản xuất bình thường.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"We are expediting your order and will ship it tomorrow.\", \"vi\": \"Chúng tôi đang khẩn trương xử lý đơn hàng của quý khách và sẽ tiến hành giao hàng vào ngày mai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"It will arrive at your medical clinic construction site on 20 August.\", \"vi\": \"Công trình này sẽ được vận chuyển đến công trường xây dựng phòng khám y tế của quý vị vào ngày 20 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"As a goodwill gesture, we will refund your entire shipping fee.\", \"vi\": \"Như một cử chỉ thiện chí, chúng tôi sẽ hoàn trả toàn bộ phí vận chuyển cho quý khách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Sanaa Rahija\", \"vi\": \"Từ “Rahija”\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"bre\", \"vi\": \"thư\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 41, \"question_numbers\": []}]' WHERE `id` = '8868aa81-a1b1-473e-8330-58721ed2ab26';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Labor cost - AED 330.00\", \"vi\": \"Chi phí xét nghiệm - 330,00 AED\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Paper tray - AED 50.00\", \"vi\": \"Khay đựng giấy - 50,00 AED\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Bulb - AED 30.00\", \"vi\": \"Bóng đèn - 30,00 AED\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Copy ink - AED 220.00\", \"vi\": \"Mực in - 220,00 AED\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Total - AED 630.00\", \"vi\": \"Tổng cộng - 630,00 AED\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Invoice 3987\", \"vi\": \"Hóa đơn số 3987\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Shawqi Office Services, Dubai, UAE\", \"vi\": \"Shawqi Office Services, Dubai, Các Tiểu vương quốc Ả Rập Thống nhất\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Report requested in English\", \"vi\": \"Yêu cầu báo cáo bằng tiếng Anh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"18 October\", \"vi\": \"Ngày 18 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Jenkins Press\", \"vi\": \"Nhà xuất bản Jenkins\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"P.O. Box 2291\", \"vi\": \"Hộp thư số 2291\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Dubai, UAE\", \"vi\": \"Dubai, Các Tiểu vương quốc Ả Rập Thống nhất\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Service\", \"vi\": \"Dịch vụ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"On 14 October, replaced bulb and repaired paper tray on copier per call received on 12 October.\", \"vi\": \"Vào ngày 14 tháng 10, chúng tôi đã thay bóng đèn và sửa chữa khay đựng giấy trên máy photocopy theo yêu cầu nhận được vào ngày 12 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Replaced copy ink in two machines.\", \"vi\": \"Đã thay mực in cho hai máy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Performed routine yearly maintenance on five copiers per existing service contract.\", \"vi\": \"Đã tiến hành bảo trì định kỳ hàng năm cho năm máy photocopy theo hợp đồng dịch vụ hiện hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Total amount must be received by 31 October.\", \"vi\": \"Tổng số tiền phải được chuyển đến trước ngày 31 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Thank you for your business!\", \"vi\": \"Xin chân thành cảm ơn quý khách đã tin dùng sản phẩm của chúng tôi!\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '887220ab-05bf-4c97-a998-8e2071017396';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"VACANCY\", \"vi\": \"VỊ TRÍ TUYỂN DỤNG\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"★★★★★★★★\", \"vi\": \"★★★★★★★★\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The Golden Lagoon has been serving Montego Bay for 18 years.\", \"vi\": \"Golden Lagoon đã phục vụ khách hàng tại Montego Bay trong suốt 18 năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We are an award-winning restaurant with a reputation that spans the Caribbean.\", \"vi\": \"Chúng tôi là một nhà hàng từng đoạt nhiều giải thưởng, với danh tiếng lan tỏa khắp vùng Caribe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Currently we have vacancies for the position of waitstaff.\", \"vi\": \"Hiện tại, chúng tôi đang có các vị trí tuyển dụng cho chức danh nhân viên phục vụ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Duties include taking customers\' orders, serving food and beverages, preparing itemized bills, and accepting payments.\", \"vi\": \"Các nhiệm vụ bao gồm nhận đơn đặt hàng của khách hàng, phục vụ đồ ăn và đồ uống, lập hóa đơn chi tiết và thu tiền.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Experience is preferred but not required.\", \"vi\": \"Ưu tiên ứng viên có kinh nghiệm, nhưng đây không phải là yêu cầu bắt buộc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We offer an excellent hourly rate and flexible work schedule.\", \"vi\": \"Chúng tôi cung cấp mức lương theo giờ rất hấp dẫn cùng lịch làm việc linh hoạt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Apply in person, supplying a résumé and three employment references.\", \"vi\": \"Quý vị vui lòng nộp hồ sơ trực tiếp, kèm theo sơ yếu lý lịch và ba thư giới thiệu từ nơi làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The Golden Lagoon\", \"vi\": \"Đầm Vàng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Shahine Kincaid, Manager\", \"vi\": \"Shahine Kincaid, Trưởng phòng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"135 Concertina Dr.\", \"vi\": \"135 Đường Concertina\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Montego Bay, Jamaica\", \"vi\": \"Montego Bay, Jamaica\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Business hours: Monday–Friday, 11:00 A.M.–11:00 P.M.\", \"vi\": \"Giờ làm việc: Thứ Hai – Thứ Sáu, từ 11 giờ sáng đến 11 giờ tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Saturday and Sunday, noon–10:00 P.M.\", \"vi\": \"Thứ Bảy và Chủ Nhật, từ trưa đến 10 giờ tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"★★★★★★★★\", \"vi\": \"★★★★★★★★\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '88736129-6b2a-4bf4-8d18-7df14c63319e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Learn to play guitar at Alexis Instruments!\", \"vi\": \"Hãy đến Alexis Instruments để học chơi guitar!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Alexis Instruments will offer group and individual guitar instruction beginning April 2.\", \"vi\": \"Alexis Instruments sẽ tổ chức các lớp học guitar theo nhóm và cá nhân bắt đầu từ ngày 2 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Each of our locations has been updated with newly constructed classrooms and practice rooms.\", \"vi\": \"Mỗi cơ sở của chúng tôi đều đã được nâng cấp với các phòng học và phòng thực hành mới được xây dựng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Our instructors have years of experience teaching and playing as professional musicians.\", \"vi\": \"Các giảng viên của chúng tôi có nhiều năm kinh nghiệm trong việc giảng dạy và biểu diễn với tư cách là các nhạc sĩ chuyên nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Call an Alexis Instruments store today for availability and pricing.\", \"vi\": \"Hãy liên hệ với cửa hàng Alexis Instruments ngay hôm nay để biết thông tin về tình trạng hàng và giá cả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"To: Lucia Rivera\", \"vi\": \"Kính gửi: Bà Lucia Rivera\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"From: Krista Towers\", \"vi\": \"Từ: Krista Towers\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Date: April 26, 8:30 A.M.\", \"vi\": \"Ngày: 26 tháng 4, 8 giờ 30 sáng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Subject: Order TS1058293\", \"vi\": \"Chủ đề: Đơn đặt hàng số TS1058293\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Dear Ms. Rivera,\", \"vi\": \"Kính gửi bà Rivera,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I am following up on the order you placed with us on April 23.\", \"vi\": \"Tôi xin liên hệ lại về đơn hàng mà quý khách đã đặt với chúng tôi vào ngày 23 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We have only one guitar of the model you want in stock.\", \"vi\": \"Chúng tôi hiện chỉ còn một cây guitar thuộc mẫu mà quý vị mong muốn trong kho.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"It was used as a display sample on the floor of our salesroom here in Santa Barbara.\", \"vi\": \"Sản phẩm này từng được trưng bày làm mẫu tại khu vực bán hàng của chúng tôi ở Santa Barbara.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"This means it is out of the box and has been played by customers browsing the store.\", \"vi\": \"Điều này có nghĩa là sản phẩm này đã được mở hộp và đã từng được khách hàng dùng thử khi tham quan cửa hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Our in-house luthier has thoroughly inspected the guitar, and it is still in excellent condition.\", \"vi\": \"Chuyên gia chế tác đàn nội bộ của chúng tôi đã kiểm tra kỹ lưỡng cây đàn guitar này, và nó vẫn đang ở trong tình trạng tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"There are no scratches, scuffs, or dents on it whatsoever.\", \"vi\": \"Trên sản phẩm này hoàn toàn không có bất kỳ vết xước, vết trầy hay vết lõm nào.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Because you purchased the instrument on the understanding that it was brand new, we want to offer you two options:\", \"vi\": \"Vì quý vị đã mua nhạc cụ này với sự hiểu biết rằng đây là sản phẩm hoàn toàn mới, chúng tôi xin đề xuất với quý vị hai phương án sau:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"If you do not want the floor model, you may cancel the order and receive an immediate full refund.\", \"vi\": \"Nếu quý vị không muốn mua mẫu trưng bày, quý vị có thể hủy đơn hàng và sẽ được hoàn lại toàn bộ số tiền ngay lập tức.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"If you would like the floor model, we will ship it immediately and offer you a 10 percent discount off the original retail price.\", \"vi\": \"Nếu quý khách muốn mua mẫu trưng bày, chúng tôi sẽ giao hàng ngay lập tức và giảm giá 10% so với giá bán lẻ ban đầu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"If you choose the latter, we will make sure the guitar is delivered to your local store in time for your first lesson there tomorrow.\", \"vi\": \"Nếu quý vị chọn phương án thứ hai, chúng tôi sẽ đảm bảo cây đàn guitar sẽ được giao đến cửa hàng gần nơi quý vị sinh sống kịp thời để quý vị có thể tham gia buổi học đầu tiên tại đó vào ngày mai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We apologize for the inconvenience.\", \"vi\": \"Chúng tôi xin lỗi vì sự bất tiện này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Krista Towers\", \"vi\": \"Krista Towers\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Alexis Instruments\", \"vi\": \"Alexis Instruments\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Description - Price\", \"vi\": \"Mô tả - Giá cả\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Domingo 313 full-body acoustic guitar - $450.00\", \"vi\": \"Đàn guitar acoustic toàn thân Domingo 313 - 450,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"10% discount on guitar - -$45.00\", \"vi\": \"Giảm giá 10% khi mua guitar - -$45,00\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Three-year repair and maintenance plan, good at any Alexis Instruments location - $75.00\", \"vi\": \"Gói bảo trì và sửa chữa trong ba năm, có hiệu lực tại bất kỳ chi nhánh nào của Alexis Instruments - 75,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Sales tax - $34.80\", \"vi\": \"Thuế bán hàng - 34,80 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Total - $514.80\", \"vi\": \"Tổng cộng - 514,80 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Ship To - Bill To\", \"vi\": \"Địa chỉ nhận hàng - Địa chỉ thanh toán\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Alexis Instruments, store #23\\n\\n          3914 Joseph Drive\\n\\n          Chico, CA 95926 - Lucia Rivera\\n\\n          11437 Shady Grove Lane\\n\\n          Chico, CA 95926\", \"vi\": \"Alexis Instruments, cửa hàng số 23\\n\\n          3914 Joseph Drive\\n\\n          Chico, CA 95926 - Lucia Rivera\\n\\n          11437 Shady Grove Lane\\n\\n          Chico, CA 95926\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Alexis Instruments\", \"vi\": \"Alexis Instruments\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Order number: TS1058293\", \"vi\": \"Số đơn đặt hàng: TS1058293\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Date: April 26\", \"vi\": \"Ngày: 26 tháng 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '887b14b5-b488-48a6-bbd0-a0dfae9a42d8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.zabokahaiti.ht\", \"vi\": \"http://www.zabokahaiti.ht\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"French | English\", \"vi\": \"Tiếng Pháp | Tiếng Anh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The Zaboka Guesthouse, situated in the hills above Haiti\'s capital city of Port-au-Prince, occupies the top four floors of a gorgeous building in a historic district.\", \"vi\": \"Nhà nghỉ Zaboka, tọa lạc trên những ngọn đồi phía trên thủ đô Port-au-Prince của Haiti, chiếm bốn tầng trên cùng của một tòa nhà tuyệt đẹp nằm trong khu phố lịch sử.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Our guesthouse is centrally located and just a short walk to markets, restaurants, art galleries, and nightclubs.\", \"vi\": \"Nhà nghỉ của chúng tôi tọa lạc tại vị trí trung tâm và chỉ cách các khu chợ, nhà hàng, phòng trưng bày nghệ thuật và câu lạc bộ đêm một quãng đường đi bộ ngắn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Details:\", \"vi\": \"Chi tiết:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Amenities include wireless Internet, kitchen facilities, and luggage storage.\", \"vi\": \"Các tiện nghi bao gồm Internet không dây, thiết bị nhà bếp và dịch vụ giữ hành lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"All guests are also entitled to a free Haitian-style breakfast including locally grown coffee.\", \"vi\": \"Tất cả quý khách cũng được thưởng thức bữa sáng miễn phí theo phong cách Haiti, bao gồm cà phê được trồng tại địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The room rate is $45 per night per guest ($15 is charged up front to secure each reservation; the remainder must be paid upon arrival).\", \"vi\": \"Giá phòng là 45 đô la mỗi đêm cho mỗi khách (phải thanh toán trước 15 đô la để xác nhận mỗi đặt phòng; số tiền còn lại phải thanh toán khi quý khách đến nơi).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Check-in starts at 1:00 P.M.; checkout is no later than 11:30 A.M.\", \"vi\": \"Thời gian nhận phòng bắt đầu từ 1 giờ chiều; thời gian trả phòng muộn nhất là 11 giờ 30 sáng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"A minimum stay of two nights is required.\", \"vi\": \"Quý khách phải lưu trú tối thiểu hai đêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Parties arriving after 7:00 P.M. will be charged a late-night check-in fee of $5.00 per reservation.\", \"vi\": \"Các nhóm khách đến sau 7 giờ tối sẽ phải trả phí nhận phòng muộn vào ban đêm là 5,00 USD cho mỗi đặt phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Zaboka Guesthouse\", \"vi\": \"Nhà nghỉ Zaboka\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"99 rue Hibbert, Pétion-Ville, Haiti\", \"vi\": \"Số 99 đường Hibbert, Pétion-Ville, Haiti\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"http://www.travelfair.com\", \"vi\": \"http://www.travelfair.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Pétion-Ville, Haiti: Zaboka Guesthouse\", \"vi\": \"Pétion-Ville, Haiti: Nhà nghỉ Zaboka\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Posted by Wilford Gaines on October 7\", \"vi\": \"Được đăng bởi Wilford Gaines vào ngày 7 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I stayed at the Zaboka Guesthouse for three nights in April.\", \"vi\": \"Vào tháng Tư, tôi đã lưu trú tại Nhà nghỉ Zaboka trong ba đêm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"There are several other hotels in the area, but in my view, this is certainly the nicest option within the price range.\", \"vi\": \"Trong khu vực này còn có một số khách sạn khác, nhưng theo quan điểm của tôi, đây chắc chắn là lựa chọn tốt nhất trong tầm giá này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The lively courtyard and huge communal kitchen both present a great environment for meeting other guests.\", \"vi\": \"Khu sân trong nhộn nhịp cùng nhà bếp chung rộng lớn đều tạo nên một không gian lý tưởng để quý khách có cơ hội gặp gỡ những vị khách khác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"That was without a doubt my favorite aspect.\", \"vi\": \"Đó chắc chắn là điều tôi thích nhất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"If you plan to arrive in the evening, make sure you get the code to enter into the electronic keypad at the door, as the street level entrance is locked after 7 P.M. This isn\'t something I was made aware of, so I had to wait a short while to be let in.\", \"vi\": \"Nếu quý vị dự định đến vào buổi tối, xin vui lòng đảm bảo rằng quý vị đã có mã số để nhập vào bàn phím điện tử tại cửa, vì lối vào ở tầng trệt sẽ bị khóa sau 7 giờ tối. Tôi không được thông báo trước về điều này, nên đã phải chờ một lúc mới được vào trong.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Other than that, I really enjoyed my stay!\", \"vi\": \"Ngoài điều đó ra, tôi thực sự rất hài lòng với kỳ nghỉ của mình!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"http://www.zabokahaiti.ht/receipt167642\", \"vi\": \"http://www.zabokahaiti.ht/receipt167642\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Thank you for your reservation!\", \"vi\": \"Xin chân thành cảm ơn quý khách đã đặt chỗ!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Please print a copy of these details for your records.\", \"vi\": \"Kính mong quý vị in một bản sao các thông tin này để lưu giữ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Guest Name: Melinda Le\", \"vi\": \"Tên khách mời: Melinda Le\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Number of Guests: 1\", \"vi\": \"Số lượng khách: 1\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Booking Reference Number: 167642\", \"vi\": \"Số tham chiếu đặt chỗ: 167642\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Date and Time of Check-in: 2 June at 8:00 P.M.\", \"vi\": \"Ngày và giờ làm thủ tục nhận phòng: Ngày 2 tháng 6 lúc 8 giờ tối.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Date and Time of Checkout: 3 June at 11:00 A.M.\", \"vi\": \"Ngày và giờ trả phòng: Ngày 3 tháng 6 lúc 11 giờ sáng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Amount Paid: $15.00 deposit\", \"vi\": \"Số tiền đã thanh toán: $15,00 tiền đặt cọc\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"+ $5.00 late-night check-in fee\", \"vi\": \"+ Phí làm thủ tục nhận phòng muộn 5,00 USD\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"= $20.00 total paid via card ending in -8990\", \"vi\": \"= Tổng số tiền 20,00 USD đã thanh toán bằng thẻ có số cuối là -8990\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Amount Due on Arrival: $30.00\", \"vi\": \"Số tiền phải thanh toán khi nhận phòng: 30,00 USD\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Total: $50.00\", \"vi\": \"Tổng cộng: 50,00 USD\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Send a message to reception@zabokahaiti.ht or call + 509 2555 0161 if you have any questions prior to your arrival.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào trước khi đến, vui lòng gửi email đến địa chỉ reception@zabokahaiti.ht hoặc gọi số +509 2555 0161.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"We look forward to hosting you!\", \"vi\": \"Chúng tôi rất mong được đón tiếp quý vị!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}]' WHERE `id` = '8884a6b7-f1d6-4fff-9b65-53d5ac7859ea';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Eun-Mi Park\", \"vi\": \"Từ: Eun-Mi Park\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All Employees at the New Korea Financial Group (NKFG)\", \"vi\": \"Đến: Tất cả nhân viên tại Tập đoàn Tài chính New Korea (NKFG)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Workplace Improvements\", \"vi\": \"Chủ đề: Cải thiện nơi làm việc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: March 12\", \"vi\": \"Ngày: 12 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"As part of our commitment to providing a comfortable environment for our employees, maintenance work will begin this week with the goal of ___139___ individual work spaces.\", \"vi\": \"Là một phần trong cam kết mang lại môi trường thoải mái cho nhân viên, công việc bảo trì sẽ bắt đầu vào tuần này với mục tiêu ___139___ các không gian làm việc cá nhân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [139]}, {\"en\": \"The work will proceed in stages.\", \"vi\": \"Công việc sẽ được tiến hành theo từng giai đoạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"First, new carpeting will be installed tomorrow in each office and cubicle.\", \"vi\": \"Đầu tiên, thảm mới sẽ được lắp đặt vào ngày mai trong mỗi văn phòng và ô làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To help ensure that this project ___140___ smoothly, please remove all personal items from the floor in your work area before you leave today.\", \"vi\": \"Để giúp đảm bảo rằng dự án này ___140___ suôn sẻ, vui lòng dọn sạch tất cả vật dụng cá nhân khỏi sàn nhà trong khu vực làm việc của bạn trước khi ra về hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [140]}, {\"en\": \"___141___ , open metal bookcases will be replaced later in the week with state-of-the-art, high-density plastic bookshelves with sliding doors.\", \"vi\": \"___141___ , các kệ sách bằng kim loại mở sẽ được thay thế vào cuối tuần bằng các giá sách bằng nhựa mật độ cao, hiện đại có cửa lùa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [141]}, {\"en\": \"We are confident that these initiatives will improve the appearance of work spaces throughout the company.\", \"vi\": \"Chúng tôi tự tin rằng những Sáng kiến này sẽ cải thiện diện mạo của các không gian làm việc trong toàn công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"___142___ .\", \"vi\": \"___142___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [142]}, {\"en\": \"Thank you in advance for your understanding and cooperation.\", \"vi\": \"Cảm ơn bạn trước vì sự thấu hiểu và hợp tác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '889ba6f6-4f54-472e-a20a-7e1b18554010';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ready, Set—Jamboree!\", \"vi\": \"Chuẩn bị, sẵn sàng — Jamboree!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"NASSAU (20 June)—Every other year, Nassau is overrun by lovers of Afrobeat, a music style that fuses rhythms of the African dance tradition with jazz and funk music.\", \"vi\": \"NASSAU (ngày 20 tháng 6) — Cứ hai năm một lần, thành phố Nassau lại chào đón đông đảo những người yêu thích thể loại Afrobeat — một phong cách âm nhạc kết hợp nhịp điệu của truyền thống khiêu vũ châu Phi với nhạc jazz và funk.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The Fourth Biennial Afrobeat Jamboree, better known as \\\"Afrojam,\\\" will run between 18 July and 22 July.\", \"vi\": \"Lễ hội Afrobeat Jamboree lần thứ tư, được tổ chức hai năm một lần và thường được gọi tắt là “Afrojam”, sẽ diễn ra từ ngày 18 tháng 7 đến ngày 22 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Afrojam will feature musicians from around the globe, including Nigeria, the United Kingdom, and, of course, the Bahamas.\", \"vi\": \"Afrojam sẽ quy tụ các nghệ sĩ đến từ khắp nơi trên thế giới, bao gồm Nigeria, Vương quốc Anh và tất nhiên là cả Bahamas.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Recent ticket sales indicate that this year\'s Afrojam will draw an even bigger crowd than it did two years ago, which explains the move to the Ashanti Amphitheatre.\", \"vi\": \"Tình hình bán vé gần đây cho thấy lễ hội Afrojam năm nay sẽ thu hút lượng khán giả đông đảo hơn so với hai năm trước, và đây chính là lý do giải thích cho việc chuyển địa điểm sang Nhà hát ngoài trời Ashanti.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Additional details about the event are available at www.afrojam.org.bs.\", \"vi\": \"Quý vị có thể tham khảo thêm thông tin chi tiết về sự kiện này tại địa chỉ www.afrojam.org.bs.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Visitors to afrojam.org.bs can also enjoy video clips featuring some of the greatest moments of the past, such as the surprise appearance of the world-famous Strawberry Jam, a favourite with many city residents.\", \"vi\": \"Quý vị truy cập trang afrojam.org.bs cũng có thể thưởng thức các đoạn video ghi lại những khoảnh khắc đáng nhớ nhất trong quá khứ, chẳng hạn như sự xuất hiện bất ngờ của ban nhạc Strawberry Jam nổi tiếng toàn cầu – một nhóm nhạc được rất nhiều cư dân thành phố yêu mến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"This year\'s event offers a new feature: discounts on meals.\", \"vi\": \"Sự kiện năm nay mang đến một điểm mới: chương trình giảm giá các bữa ăn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Festival attendees need only to present their ticket stubs at participating restaurants to receive 10 percent off their bill.\", \"vi\": \"Quý vị tham dự lễ hội chỉ cần xuất trình cuống vé tại các nhà hàng tham gia chương trình để được giảm 10% trên tổng hóa đơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The discount is only good on concert evenings.\", \"vi\": \"Ưu đãi này chỉ áp dụng vào các buổi tối có buổi hòa nhạc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The organizers encourage local restaurateurs from across Nassau to consider getting involved.\", \"vi\": \"Ban tổ chức khuyến khích các chủ nhà hàng địa phương trên khắp Nassau cân nhắc tham gia sự kiện này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Those interested can call 555-0171 or complete an application at www.afrojam.org.bs/sponsors.\", \"vi\": \"Quý vị quan tâm có thể gọi đến số 555-0171 hoặc điền đơn đăng ký tại địa chỉ www.afrojam.org.bs/sponsors.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '88bc9c9b-73f1-41ed-890f-792f9ab39c78';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"BROUWER MARINE\", \"vi\": \"BROUWER MARINE\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"eLogbook Digital Logbook\", \"vi\": \"eLogbook – Sổ nhật ký điện tử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Brouwer Marine\'s eLogbook software program offers a convenient way to store required information about a ship\'s activities.\", \"vi\": \"Phần mềm eLogbook của Brouwer Marine mang đến một phương thức thuận tiện để lưu trữ các thông tin cần thiết về các hoạt động của tàu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"It replaces traditional paper logbooks for recording details of crew actions, oil discharges, compass observations, and more.\", \"vi\": \"Hệ thống này thay thế cho các sổ nhật ký giấy truyền thống dùng để ghi chép chi tiết về các hoạt động của thủy thủ đoàn, việc xả dầu, các quan sát la bàn và nhiều nội dung khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"eLogbook does not require Internet access to work, and it can be run on a single computer or made available at multiple user terminals connected to a server.\", \"vi\": \"eLogbook không cần kết nối Internet để hoạt động, và phần mềm này có thể được chạy trên một máy tính duy nhất hoặc được cung cấp trên nhiều thiết bị đầu cuối của người dùng kết nối với máy chủ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Each user has unique log-in credentials to ensure that the right personnel are making and approving entries.\", \"vi\": \"Mỗi người dùng đều có thông tin đăng nhập riêng biệt nhằm đảm bảo rằng chỉ những nhân viên có thẩm quyền mới thực hiện và phê duyệt các mục nhập.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"A PIN can be set to make logging in easier.\", \"vi\": \"Quý vị có thể thiết lập mã PIN để việc đăng nhập trở nên thuận tiện hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Authorized users can also send digital copies of logbook records to port management.\", \"vi\": \"Người dùng được ủy quyền cũng có thể gửi bản sao điện tử của các ghi chép trong sổ nhật ký đến cơ quan quản lý cảng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '88c983bd-d154-4d20-88b2-2a2be07fb375';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Johan\'s Power Washing\", \"vi\": \"Dịch vụ rửa áp lực của Johan\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Serving the Meadowbrook community for over 25 years!\", \"vi\": \"Đã phục vụ cộng đồng Meadowbrook trong hơn 25 năm qua!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Power washing beautifies your home and helps maintain the integrity of your structure!\", \"vi\": \"Việc rửa áp lực không chỉ giúp ngôi nhà của quý vị trở nên đẹp hơn mà còn góp phần duy trì tính toàn vẹn của kết cấu công trình!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The services we offer include:\", \"vi\": \"Các dịch vụ mà chúng tôi cung cấp bao gồm:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Power washing of siding, porches, decks, and more\", \"vi\": \"Rửa áp lực cao cho vách ngoài, hiên nhà, sàn gỗ ngoài trời và các khu vực khác\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Gutter cleaning and brightening\", \"vi\": \"Vệ sinh và làm sáng máng xối\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Concrete scrubbing and sealing\", \"vi\": \"Chà rửa và phủ lớp bảo vệ bê tông\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Window washing\", \"vi\": \"Rửa cửa sổ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Johan G. Matey\", \"vi\": \"John G. Matey\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"506-555-0193\", \"vi\": \"506-555-0193\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"www.johanspowerwashing.ca\", \"vi\": \"www.johanspowerwashing.ca\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Call now for a free estimate or to schedule a cleaning.\", \"vi\": \"Hãy gọi ngay để nhận báo giá miễn phí hoặc đặt lịch vệ sinh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '88d2232e-d852-4587-8d58-d43b4f386dcf';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Twin Lakes\", \"vi\": \"Hai hồ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The best place to live in Tielersburg!\", \"vi\": \"Đây chính là nơi lý tưởng nhất để sinh sống tại Tielersburg!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Please join the staff of Twin Lakes for our monthly resident information meeting.\", \"vi\": \"Kính mời quý vị tham dự buổi họp thông tin dành cho cư dân hàng tháng do đội ngũ nhân viên của Twin Lakes tổ chức.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date and time: Tuesday, March 21, 7:00 P.M.–8:30 P.M.\", \"vi\": \"Ngày và giờ: Thứ Ba, ngày 21 tháng 3, từ 7 giờ tối đến 8 giờ 30 tối.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Location: Community Center conference room (across the hall from the rental office)\", \"vi\": \"Địa điểm: Phòng hội nghị của Trung tâm Cộng đồng (nằm ngay đối diện văn phòng cho thuê)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Agenda items and presenters:\", \"vi\": \"Các nội dung trong chương trình nghị sự và người trình bày:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Property enhancements: overview of plans for fence repair and new landscaping in the pool area—Mr.\", \"vi\": \"Các hạng mục cải tạo bất động sản: tổng quan về kế hoạch sửa chữa hàng rào và cải tạo cảnh quan mới tại khu vực hồ bơi — Ông\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Abgarian, groundskeeping and maintenance supervisor\", \"vi\": \"Ông Abgarian, Trưởng bộ phận quản lý sân vườn và bảo trì\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Community garden: details for garden plot sign-up and annual biggest tomato contest—Ms.\", \"vi\": \"Vườn cộng đồng: Thông tin chi tiết về việc đăng ký lô vườn và cuộc thi “Quả cà chua to nhất” hàng năm — Bà\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Kantor, events and activities coordinator\", \"vi\": \"Ông Kantor, điều phối viên các sự kiện và hoạt động\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Water main work on Huron Street: progress update—Mr.\", \"vi\": \"Công trình lắp đặt đường ống cấp nước chính trên đường Huron: Báo cáo tiến độ — Ông\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Carter, Department of Public Works, City of Tielersburg\", \"vi\": \"Ông Carter, Sở Công trình Công cộng, Thành phố Tielersburg\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Utility rates: discussion about the rise in quarterly utility fees charged to Twin Lakes property management by the city—Mr.\", \"vi\": \"Mức phí dịch vụ công ích: cuộc thảo luận về việc tăng mức phí dịch vụ công ích hàng quý mà thành phố áp dụng đối với đơn vị quản lý bất động sản Twin Lakes — Ông\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Underwood, general manager\", \"vi\": \"Ông Underwood, Tổng giám đốc\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"New business: creation of Resident Advisory Board—Ms.\", \"vi\": \"Vấn đề mới: Thành lập Hội đồng Tư vấn Cư dân — Bà\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Davis, leasing and resident relations manager\", \"vi\": \"Ông Davis, Trưởng phòng Quản lý Hợp đồng Thuê và Quan hệ với Cư dân\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Questions and comments\", \"vi\": \"Các câu hỏi và ý kiến\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Adjournment\", \"vi\": \"Tạm hoãn phiên họp\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '88d784a7-2593-4c64-8b75-ff38b78aad93';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Local Businesses Thriving\", \"vi\": \"Các doanh nghiệp địa phương đang phát triển mạnh mẽ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"GREENWOOD (July 6)—Why a particular business succeeds is often a mystery, but a couple of local shops appear to have learned the secret.\", \"vi\": \"GREENWOOD (ngày 6 tháng 7) — Lý do tại sao một doanh nghiệp cụ thể lại thành công thường là một bí ẩn, nhưng có vẻ như một vài cửa hàng địa phương đã nắm được bí quyết đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Two years after opening their doors, A Thousand Stories and Rosier\'s Garden Center are flourishing.\", \"vi\": \"Hai năm sau khi chính thức đi vào hoạt động, A Thousand Stories và Rosier’s Garden Center đang phát triển mạnh mẽ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"“There was a lot of trial and error at the outset, but we finally figured it out,” said Liz Ohtani, who, together with Sandra Rivera, owns A Thousand Stories.\", \"vi\": \"“Ban đầu chúng tôi đã phải trải qua rất nhiều lần thử nghiệm và mắc sai lầm, nhưng cuối cùng thì chúng tôi cũng đã tìm ra cách,” Liz Ohtani – người đồng sở hữu cửa hàng A Thousand Stories cùng với Sandra Rivera – chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"“I manage the stock, and Sandra handles the public-facing part, including special events with authors.”\", \"vi\": \"“Tôi phụ trách quản lý hàng tồn kho, còn Sandra đảm nhận mảng tiếp xúc với công chúng, bao gồm cả các sự kiện đặc biệt với các tác giả.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Ms. Rivera added, “We make a fantastic team.\", \"vi\": \"Bà Rivera nói thêm: “Chúng tôi là một đội ngũ tuyệt vời.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"But I think our strongest asset is our supportive neighborhood.\", \"vi\": \"Tuy nhiên, tôi cho rằng thế mạnh lớn nhất của chúng tôi chính là cộng đồng láng giềng luôn sẵn lòng hỗ trợ lẫn nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"People here love books and reading, and they visit us regularly.\", \"vi\": \"Mọi người ở đây rất yêu thích sách và việc đọc, và họ thường xuyên ghé thăm chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We also have an active social media presence, and that helps too.”\", \"vi\": \"“Chúng tôi cũng có sự hiện diện tích cực trên các nền tảng mạng xã hội, và điều đó cũng góp phần không nhỏ.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Louie Rosier, owner of Rosier\'s Garden Center, agreed that getting a business up and running takes effort and patience.\", \"vi\": \"Ông Louie Rosier, chủ sở hữu của Trung tâm Vườn Rosier, cũng đồng tình rằng việc khởi sự và vận hành một doanh nghiệp đòi hỏi sự nỗ lực và kiên nhẫn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Mr. Rosier, whose store specializes in native plants and flowers, admitted that his first year with the garden center was tough.\", \"vi\": \"Ông Rosier, chủ cửa hàng chuyên kinh doanh các loại cây và hoa bản địa, thừa nhận rằng năm đầu tiên ông làm việc tại trung tâm vườn ươm này thực sự rất vất vả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"He recalled, “It took a long time to turn a profit.\", \"vi\": \"Ông nhớ lại: “Phải mất một thời gian dài mới có thể thu được lợi nhuận.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sometimes I considered shutting it all down and going back to my former job.”\", \"vi\": \"“Đôi khi tôi đã từng nghĩ đến việc từ bỏ tất cả và quay trở lại công việc cũ của mình.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Despite the difficult start, Mr. Rosier persevered.\", \"vi\": \"Dù khởi đầu gặp nhiều khó khăn, ông Rosier vẫn kiên trì.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Now that the business is doing well, he is exploring opening another store.\", \"vi\": \"Vì hiện tại công việc kinh doanh đang phát triển thuận lợi, ông đang xem xét việc mở thêm một cửa hàng nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"“I\'d like to reach customers beyond the Greenwood area,” he said.\", \"vi\": \"“Tôi mong muốn tiếp cận được những khách hàng ngoài khu vực Greenwood,” ông nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"“I\'m currently looking at Morganville to see if that would be the best location for a second store.”\", \"vi\": \"“Hiện tại, tôi đang xem xét Morganville để đánh giá liệu đây có phải là địa điểm lý tưởng nhất để mở cửa hàng thứ hai hay không.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '88e1097f-4dfa-46da-b904-4b5284487593';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MEMO\", \"vi\": \"BẢN GHI NHỚ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All Staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Jun Heo, Associate Director, Human Resources\", \"vi\": \"Từ: Jun Heo, Phó Giám đốc, Phòng Nhân sự\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: March 31\", \"vi\": \"Ngày: 31 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Re: New business cards\", \"vi\": \"Trả lời: Danh thiếp mới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As a result of our merger with Frantum Corporation, printed business cards for all Ketola Enterprises employees will be replaced.\", \"vi\": \"Do việc sáp nhập với Tập đoàn Frantum, danh thiếp in sẵn của toàn bộ nhân viên Ketola Enterprises sẽ được thay thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"All employees should receive the new business cards by May 1.\", \"vi\": \"Tất cả nhân viên sẽ nhận được danh thiếp mới trước ngày 1 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please stop distributing the old business cards when the new cards are delivered.\", \"vi\": \"Khi nhận được danh thiếp mới, xin vui lòng ngừng sử dụng các danh thiếp cũ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The new cards will feature the new corporate name (yet to be revealed) and our exciting new logo.\", \"vi\": \"Các thẻ mới sẽ in tên công ty mới (vẫn chưa được công bố) cùng với logo mới đầy ấn tượng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The new cards will be printed on a higher-quality paper stock, as many of you requested.\", \"vi\": \"Theo yêu cầu của nhiều quý vị, các thẻ mới sẽ được in trên loại giấy có chất lượng cao hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"If your new business cards are not delivered to your desk by May 1, please contact me directly at extension 2933.\", \"vi\": \"Nếu danh thiếp mới của quý vị chưa được chuyển đến bàn làm việc của quý vị trước ngày 1 tháng 5, xin vui lòng liên hệ trực tiếp với tôi theo số máy lẻ 2933.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '88e8865c-db3b-4c8b-8806-82f6a411486f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Please Note\", \"vi\": \"Xin lưu ý\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The views expressed by the speakers shown in this documentary film are their own and do not necessarily reflect the opinions of the filmmakers.\", \"vi\": \"Các quan điểm được các diễn giả trình bày trong bộ phim tài liệu này là quan điểm cá nhân của họ và không nhất thiết phản ánh quan điểm của các nhà làm phim.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The filmmakers\' goal was to present the topic from diverse points of view.\", \"vi\": \"Mục tiêu của các nhà làm phim là trình bày chủ đề này từ nhiều góc nhìn khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The inclusion of the speakers does not constitute an endorsement of their perspectives, nor does it imply the filmmakers\' support for any organization that those speakers may represent.\", \"vi\": \"Việc mời các diễn giả tham gia không có nghĩa là tán thành quan điểm của họ, cũng như không ngụ ý rằng các nhà làm phim ủng hộ bất kỳ tổ chức nào mà các diễn giả đó có thể đại diện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}]' WHERE `id` = '890aee4f-f865-4643-9090-e3c676d61d89';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"15th Annual Innovations in Horticulture and Agriculture Conference\", \"vi\": \"Hội nghị thường niên lần thứ 15 về những đổi mới trong lĩnh vực làm vườn và nông nghiệp\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"At the renovated Blane Hotel and Conference Centre, London, UK\", \"vi\": \"Tại Khách sạn và Trung tâm Hội nghị Blane vừa được cải tạo, London, Vương quốc Anh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"10-12 November\", \"vi\": \"Ngày 10–12 tháng 11\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"innovationsinhorticulture.org.uk\", \"vi\": \"innovationsinhorticulture.org.uk\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Featured Speakers:\", \"vi\": \"Các diễn giả tiêu biểu:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"- Chen Wan, China\", \"vi\": \"- Chen Wan, Trung Quốc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"- Hope O\'Brian, United Kingdom\", \"vi\": \"- Hope O\'Brian, Vương quốc Anh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"- Piet Bax, Netherlands\", \"vi\": \"- Piet Bax, Hà Lan\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"- Emil Savoy, Bulgaria\", \"vi\": \"- Emil Savoy, Bulgaria\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"For more information and to register, visit the Innovations in Horticulture and Agriculture Web site.\", \"vi\": \"Để biết thêm thông tin và đăng ký, quý vị vui lòng truy cập trang web “Các sáng kiến trong lĩnh vực làm vườn và nông nghiệp”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Student discounts available with ID.\", \"vi\": \"Có áp dụng ưu đãi dành cho sinh viên khi xuất trình thẻ sinh viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"A limited number of hotel rooms are available at the conference site.\", \"vi\": \"Tại địa điểm tổ chức hội nghị hiện chỉ còn một số lượng hạn chế phòng khách sạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"There is a complimentary bus service for attendees staying at nearby hotels.\", \"vi\": \"Có dịch vụ xe buýt miễn phí dành cho các đại biểu lưu trú tại các khách sạn lân cận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To: Piet Bax\", \"vi\": \"Gửi: Piet Bax\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"From: Jacob Brewster\", \"vi\": \"Từ: Jacob Brewster\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Subject: Lighting Information\", \"vi\": \"Chủ đề: Thông tin về hệ thống chiếu sáng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Date: 18 December\", \"vi\": \"Ngày: 18 tháng 12\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Dear Mr. Bax:\", \"vi\": \"Kính gửi ông Bax:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"It was wonderful meeting you in London last month.\", \"vi\": \"Thật tuyệt vời khi được gặp quý vị tại London vào tháng trước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Thank you for taking the time to talk to me after your speech and for agreeing to the video meeting on 5 January.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã dành thời gian trò chuyện với tôi sau bài phát biểu của quý vị và đã đồng ý tham gia cuộc họp trực tuyến vào ngày 5 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I\'m going to ask my project manager, Ms. Woo-Jin Ko, to join us.\", \"vi\": \"Tôi sẽ mời trưởng dự án của tôi, bà Woo-Jin Ko, tham gia cùng chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Among other things, Ms. Ko has some questions about lighting for my greenhouses.\", \"vi\": \"Ngoài ra, bà Ko còn có một số thắc mắc liên quan đến hệ thống chiếu sáng cho các nhà kính của tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I think she has some questions about the products offered by the Brillante Luxlight company.\", \"vi\": \"Tôi nghĩ rằng cô ấy có một số thắc mắc về các sản phẩm do công ty Brillante Luxlight cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I understand you helped design some of their products, so perhaps you can offer some advice.\", \"vi\": \"Tôi được biết quý vị đã tham gia thiết kế một số sản phẩm của họ, vì vậy có lẽ quý vị có thể đưa ra một số lời khuyên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I know we\'ll both have many other questions, so I do appreciate this opportunity.\", \"vi\": \"Tôi biết cả hai chúng ta sẽ còn nhiều câu hỏi khác nữa, vì vậy tôi thực sự trân trọng cơ hội này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I also hope I will be able to visit sometime in the spring and get an in-person look at your greenhouses.\", \"vi\": \"Tôi cũng hy vọng sẽ có cơ hội ghé thăm vào một thời điểm nào đó trong mùa xuân để tận mắt chiêm ngưỡng các nhà kính của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Jacob Brewster\", \"vi\": \"Jacob Brewster\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"To: Jacob Brewster\", \"vi\": \"Kính gửi: Jacob Brewster\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"From: Juana Galvez\", \"vi\": \"Từ: Juana Galvez\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Subject: Agreement\", \"vi\": \"Chủ đề: Thỏa thuận\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Date: 30 January\", \"vi\": \"Ngày: 30 tháng 1\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Dear Mr. Brewster:\", \"vi\": \"Kính gửi ông Brewster,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"We received the request and the design specifications from you.\", \"vi\": \"Chúng tôi đã nhận được yêu cầu và các thông số kỹ thuật thiết kế từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Unfortunately, the recent inclement weather has delayed the shipments of some materials we need to begin production.\", \"vi\": \"Thật không may, thời tiết xấu gần đây đã khiến việc vận chuyển một số nguyên vật liệu mà chúng tôi cần để bắt đầu sản xuất bị trì hoãn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"However, once these materials arrive, we will fast-track your order and begin production immediately.\", \"vi\": \"Tuy nhiên, ngay khi các nguyên liệu này được chuyển đến, chúng tôi sẽ ưu tiên xử lý đơn hàng của quý khách và bắt đầu sản xuất ngay lập tức.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Juana Galvez\", \"vi\": \"Juana Galvez\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}]' WHERE `id` = '890e8a11-4f71-445b-8a5c-97dbdaef7aa5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Sales Associates\", \"vi\": \"Đến: Tất cả Nhân viên Bán hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Dean Verdoorn\", \"vi\": \"Từ: Dean Verdoorn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: June 27\", \"vi\": \"Ngày: 27 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Store improvement\", \"vi\": \"Chủ đề: Cải thiện cửa hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"It is very important to us at V and J Camping Supplies that we work together as a unit.\", \"vi\": \"Đối với chúng tôi tại V and J Camping Supplies, việc cùng nhau làm việc như một tập thể là vô cùng quan trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Teamwork not only improves productivity but also leads to increased satisfaction for customers and employees.\", \"vi\": \"Tinh thần đồng đội không chỉ nâng cao năng suất mà còn mang lại sự hài lòng lớn hơn cho cả khách hàng lẫn nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[135], we will be combining a team-building exercise with an in-store improvement plan that we believe will make employees, management, and customers happy.\", \"vi\": \"______[135], chúng tôi sẽ kết hợp một hoạt động xây dựng đội ngũ với kế hoạch cải tiến cửa hàng mà chúng tôi tin rằng sẽ làm hài lòng nhân viên, ban quản lý và khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [135]}, {\"en\": \"We will be redesigning the walls in our stores to look like trees with hollow spaces ______[136] products can be displayed.\", \"vi\": \"Chúng tôi sẽ thiết kế lại các bức tường trong cửa hàng của mình trông giống như những cái cây với các hốc trống ______[136] sản phẩm có thể được trưng bày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [136]}, {\"en\": \"These outdoor-themed shelves are actually easy-to-assemble modular wall units.\", \"vi\": \"Những chiếc kệ theo chủ đề ngoài trời này thực chất là các khối tường lắp ráp dạng mô-đun dễ dàng lắp đặt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Associates ______[137] the task to work cooperatively in teams to assemble them.\", \"vi\": \"Các nhân viên ______[137] nhiệm vụ làm việc cùng nhau theo nhóm để lắp ráp chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [137]}, {\"en\": \"______[138].\", \"vi\": \"______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [138]}, {\"en\": \"When it is completed, we will stock the shelves and have a fun grand reopening event for customers.\", \"vi\": \"Khi hoàn thành, chúng tôi sẽ chất đầy hàng lên kệ và tổ chức một sự kiện mở cửa trở lại vui nhộn dành cho khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"More information will be forthcoming.\", \"vi\": \"Thêm thông tin sẽ được cung cấp trong thời gian tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Dean Verdoorn\", \"vi\": \"Dean Verdoorn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Buildings Director\", \"vi\": \"Giám đốc Cơ sở vật chất\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '89142e0d-a7ba-4dcc-ba92-0efa53572ebb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: jgonzalez@centralavemarketing.com\", \"vi\": \"Gửi tới: jgonzalez@centralavemarketing.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: pamison@dantonpubliclibrary.org\", \"vi\": \"Nguồn: pamison@dantonpubliclibrary.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Library update\", \"vi\": \"Chủ đề: Thông tin mới nhất về thư viện\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: May 10\", \"vi\": \"Ngày: 10 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Volunteer opportunities\", \"vi\": \"Tệp đính kèm: Các cơ hội tình nguyện\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Gonzalez,\", \"vi\": \"Kính gửi Bà Gonzalez,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for your generosity in donating to the Danton Public Library once again last year.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã một lần nữa hào phóng đóng góp cho Thư viện Công cộng Danton trong năm vừa qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Because of donations from you and others, we were able to purchase twenty new computers for our patrons\' use.\", \"vi\": \"Nhờ sự đóng góp từ quý vị và những người khác, chúng tôi đã có thể mua được hai mươi máy tính mới để phục vụ quý độc giả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We also acquired a new collection of nonfiction books for our children\'s room.\", \"vi\": \"Chúng tôi cũng đã bổ sung một bộ sưu tập sách phi hư cấu mới cho phòng đọc dành cho thiếu nhi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"At this time, I would like to tell you about another project we hope to complete with additional funds: converting many of our old, worn-out books into electronic files to help preserve their content for future use.\", \"vi\": \"Lúc này, tôi xin được chia sẻ với quý vị về một dự án khác mà chúng tôi hy vọng sẽ hoàn thành nhờ nguồn kinh phí bổ sung: chuyển đổi nhiều cuốn sách cũ, đã xuống cấp của chúng tôi thành các tệp tin điện tử nhằm giúp bảo tồn nội dung của chúng để phục vụ cho việc sử dụng trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"This is a costly endeavor.\", \"vi\": \"Đây là một công việc tốn kém.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"If you are able to contribute even a small amount toward this new goal, it would be greatly appreciated.\", \"vi\": \"Nếu quý vị có thể đóng góp dù chỉ một khoản nhỏ cho mục tiêu mới này, chúng tôi sẽ vô cùng biết ơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If you are unable to make another monetary donation, please consider helping us complete some small renovation projects that we have scheduled for this year.\", \"vi\": \"Nếu quý vị không thể đóng góp thêm bằng tiền mặt, xin vui lòng cân nhắc hỗ trợ chúng tôi hoàn thành một số dự án cải tạo nhỏ mà chúng tôi đã lên kế hoạch thực hiện trong năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"A list of those projects is attached.\", \"vi\": \"Danh sách các dự án đó được đính kèm dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We hope you will find one that interests you.\", \"vi\": \"Chúng tôi hy vọng quý vị sẽ tìm thấy một chủ đề mà quý vị quan tâm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"We look forward to working alongside enthusiastic and engaged community members like yourself to ensure the library\'s future success.\", \"vi\": \"Chúng tôi rất mong được hợp tác cùng các thành viên cộng đồng đầy nhiệt huyết và tích cực như quý vị để đảm bảo sự thành công trong tương lai của thư viện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Peter Amison, Community Outreach Coordinator\", \"vi\": \"Peter Amison, Điều phối viên phụ trách quan hệ cộng đồng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Danton Public Library\", \"vi\": \"Thư viện Công cộng Danton\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '893196b8-8ff4-4271-bd3c-b9810a56d913';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Keri Mohan (12:40 P.M.)\", \"vi\": \"Keri Mohan (12 giờ 40 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I\'m nearly done readying the jewelry orders for shipment.\", \"vi\": \"Tôi sắp hoàn tất việc chuẩn bị các đơn hàng trang sức để giao hàng rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I\'ve inserted a packing slip and business card in each box.\", \"vi\": \"Tôi đã đặt một phiếu đóng gói và một tấm danh thiếp vào mỗi hộp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Should anything else be included before I seal them up and drop them off at the post office?\", \"vi\": \"Có cần phải chuẩn bị thêm gì nữa không trước khi tôi đóng gói và mang chúng đến bưu điện?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Sujay Rishi (12:42 P.M.)\", \"vi\": \"Sujay Rishi (12 giờ 42 phút trưa)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Can you put a Rishi Gemstones magnet in each box?\", \"vi\": \"Xin quý vị vui lòng đặt một miếng nam châm Rishi Gemstones vào mỗi hộp được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Keri Mohan (12:43 P.M.)\", \"vi\": \"Keri Mohan (12 giờ 43 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Certainly!\", \"vi\": \"Chắc chắn rồi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I\'ll do that right away.\", \"vi\": \"Tôi sẽ làm ngay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Keri Mohan (12:50 P.M.)\", \"vi\": \"Keri Mohan (12 giờ 50 phút trưa)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Also, we\'re running low on shipping labels.\", \"vi\": \"Ngoài ra, chúng tôi sắp hết nhãn vận chuyển rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I can order some more.\", \"vi\": \"Tôi có thể đặt mua thêm một ít.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sujay Rishi (12:54 P.M.)\", \"vi\": \"Sujay Rishi (12 giờ 54 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Actually, we have an entire bin of them.\", \"vi\": \"Thực ra, chúng tôi có cả một thùng đầy những thứ đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Check the supply closet.\", \"vi\": \"Xin vui lòng kiểm tra tủ đựng vật tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Let me know if you can\'t find them.\", \"vi\": \"Nếu quý vị không tìm thấy chúng, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '8957bf37-71d6-405c-8c4e-f8686047a5c9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dear PGD Account Holder,\", \"vi\": \"Kính gửi Chủ tài khoản PGD,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"PGD Bank strives ______[131] the highest levels of client security and service.\", \"vi\": \"Ngân hàng PGD luôn nỗ lực ______[131] mức độ bảo mật và dịch vụ khách hàng cao nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"This applies not only to online- and telephone-based services, but also to our brick-and-mortar locations.\", \"vi\": \"Điều này không chỉ áp dụng cho các dịch vụ trực tuyến và qua điện thoại, mà còn cho các chi nhánh truyền thống của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Our three branch offices have proudly been a part of the community ______[132] a combined total of 40 years.\", \"vi\": \"Ba chi nhánh của chúng tôi đã tự hào là một phần của cộng đồng trong tổng cộng ______[132] 40 năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [132]}, {\"en\": \"To assist you even better in the future, our Smithville branch will be temporarily closed for renovations July 8–22.\", \"vi\": \"Để hỗ trợ quý khách tốt hơn nữa trong tương lai, chi nhánh Smithville của chúng tôi sẽ tạm thời đóng cửa để cải tạo từ ngày 8 đến ngày 22 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[133].\", \"vi\": \"______[133].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [133]}, {\"en\": \"In the meantime, our other two regional branches in Pine Grove and Bradford will maintain normal business ______[134].\", \"vi\": \"Trong thời gian này, hai chi nhánh khác trong khu vực của chúng tôi tại Pine Grove và Bradford sẽ duy trì hoạt động kinh doanh bình thường ______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [134]}, {\"en\": \"We value your feedback and will respond to any concerns that you may have as soon as possible.\", \"vi\": \"Chúng tôi rất trân trọng ý kiến đóng góp của quý khách và sẽ giải đáp mọi thắc mắc của quý khách trong thời gian sớm nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Edwin Chen, Operations Manager\", \"vi\": \"Edwin Chen, Trưởng phòng Vận hành\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"PGD Bank\", \"vi\": \"Ngân hàng PGD\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '896f08f5-9657-4dd1-b824-14cef09ed803';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ride-Away Vehicles Summer Special 🚗\", \"vi\": \"Chương trình khuyến mãi mùa hè dành cho các dòng xe Ride-Away 🚗\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: yayoiadachi@jrengineering.co.jp\", \"vi\": \"Gửi tới: yayoiadachi@jrengineering.co.jp\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: info@rideawayvehicles.co.ie\", \"vi\": \"Nguồn: info@rideawayvehicles.co.ie\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 14 July\", \"vi\": \"Ngày: 14 tháng 7\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Reservation confirmation - #122055\", \"vi\": \"Chủ đề: Xác nhận đặt chỗ - #122055\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Driver Name: Yayoi Adachi - Date/Time of Return: 29 July, 4:40 P.M.\", \"vi\": \"Tên tài xế: Yayoi Adachi - Ngày/giờ trở về: 29 tháng 7, 4 giờ 40 phút chiều\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Model/Number Plate:\\nColaba Seasider, 161-C-45329 - Condition of Vehicle: No damage\", \"vi\": \"Mẫu xe/Biển số:\\nColaba Seasider, 161-C-45329 - Tình trạng xe: Không có hư hỏng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Gas Tank: Half full - Odometer Reading:\\n33,763 kilometers\", \"vi\": \"Bình xăng: Còn một nửa - Số km hiển thị trên đồng hồ đo quãng đường:\\n33.763 km\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Dear Ms. Adachi,\", \"vi\": \"Kính gửi bà Adachi,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Your car rental reservation is confirmed.\", \"vi\": \"Đặt xe của quý khách đã được xác nhận.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Here are the details per the terms of your rental:\", \"vi\": \"Dưới đây là các chi tiết theo các điều khoản của hợp đồng thuê của quý vị:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Pickup: 21 July, 9:00 A.M. at Ride-Away Vehicles, Shannon Airport, Shannon, Ireland\", \"vi\": \"Thời gian nhận xe: 21 tháng 7, lúc 9 giờ sáng tại Ride-Away Vehicles, Sân bay Shannon, Shannon, Ireland\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Drop-Off: 29 July, 5:00 P.M. at Ride-Away Vehicles, Cork City Centre, Cork City, Ireland\", \"vi\": \"Thời gian nhận xe: Ngày 29 tháng 7, lúc 5 giờ chiều tại Ride-Away Vehicles, Trung tâm thành phố Cork, Thành phố Cork, Ireland\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Rate: €21/day X 8 days = €168 (includes unlimited mileage and navigational system/GPS)\", \"vi\": \"Giá thuê: 21 €/ngày × 8 ngày = 168 € (đã bao gồm số dặm không giới hạn và hệ thống định vị/GPS)\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Model: Colaba Seasider or similar\", \"vi\": \"Mẫu: Colaba Seasider hoặc các mẫu tương tự\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Important Information: The driver must present a valid driving licence at pickup.\", \"vi\": \"Thông tin quan trọng: Người lái xe phải xuất trình giấy phép lái xe còn hiệu lực khi nhận xe.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Additional charges may apply for any changes to the reservation, including changes to the pickup or drop-off date, time, or location.\", \"vi\": \"Quý khách có thể phải chịu các khoản phí bổ sung đối với bất kỳ thay đổi nào đối với đặt chỗ, bao gồm cả việc thay đổi ngày, giờ hoặc địa điểm nhận hoặc trả xe.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"A €25 service fee will be assessed for vehicles returned without a full tank of petrol in addition to the cost of fuel.\", \"vi\": \"Đối với các phương tiện được trả lại mà bình xăng không đầy, quý khách sẽ phải trả phí dịch vụ 25 € ngoài chi phí nhiên liệu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thank you for choosing Ride-Away Vehicles.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã lựa chọn Ride-Away Vehicles.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Please call 020 917 1212 with any questions.\", \"vi\": \"Nếu có bất kỳ thắc mắc nào, xin vui lòng gọi đến số 020 917 1212.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Save 15 percent off our rates* during the month of July for travel within Ireland.\", \"vi\": \"Trong tháng 7, quý khách sẽ được giảm 15% so với mức giá thông thường* khi du lịch trong phạm vi Ireland.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Compact Car €21\", \"vi\": \"Xe cỡ nhỏ: 21 €\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Standard Car €32\", \"vi\": \"Xe tiêu chuẩn: 32 €\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Full-Size Sedan €46\", \"vi\": \"Xe sedan cỡ lớn 46 €\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Van €52\", \"vi\": \"Từ 52 €\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Call 020 917 1212 or book online at www.ride-awayvehicles.co.ie.\", \"vi\": \"Vui lòng gọi số 020 917 1212 hoặc đặt chỗ trực tuyến tại www.ride-awayvehicles.co.ie.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"*Price advertised is the daily rate for eligible drivers, inclusive of value-added tax (VAT) and the basic protection plan.\", \"vi\": \"*Giá được công bố là mức giá hàng ngày dành cho các tài xế đủ điều kiện, đã bao gồm thuế giá trị gia tăng (VAT) và gói bảo hiểm cơ bản.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Additional fees may apply.\", \"vi\": \"Có thể sẽ có các khoản phí bổ sung.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Please contact a Ride-Away Vehicles representative for more information.\", \"vi\": \"Vui lòng liên hệ với đại diện của Ride-Away Vehicles để biết thêm thông tin.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Ride-Away Vehicles Return Form\", \"vi\": \"Mẫu đơn trả lại phương tiện Ride-Away\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Completed By: Henry Riordan, Assistant Manager, Cork City Centre location\", \"vi\": \"Người thực hiện: Henry Riordan, Phó Giám đốc, Chi nhánh Trung tâm Thành phố Cork\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Yayoi Adachi\", \"vi\": \"Yayoi Adachi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Driver\'s Signature\", \"vi\": \"Chữ ký của người lái xe\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '899b1057-ee8c-461e-bb21-4990aef7413d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Jane Equi [10:41 A.M.]\", \"vi\": \"Jane Equi [10 giờ 41 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi Mateo.\", \"vi\": \"Xin chào Mateo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Brian Jaffers just called to cancel tomorrow\'s walk-through at 721 Union Street.\", \"vi\": \"Brian Jaffers vừa gọi điện để hủy buổi tham quan vào ngày mai tại số 721 Union Street.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Mateo Rodriguez [10:42 A.M.]\", \"vi\": \"Mateo Rodriguez [10:42 sáng]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"That\'s too bad.\", \"vi\": \"Thật đáng tiếc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"That apartment is just right for him.\", \"vi\": \"Căn hộ đó quả thực rất phù hợp với anh ấy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Did you reschedule?\", \"vi\": \"Quý vị đã sắp xếp lại lịch chưa?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Jane Equi [10:44 A.M.]\", \"vi\": \"Jane Equi [10 giờ 44 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Yes, for Thursday, just before you show the Rockledge Place property to the Kim family.\", \"vi\": \"Vâng, vào thứ Năm, ngay trước khi quý vị dẫn gia đình Kim đi xem căn nhà tại Rockledge Place.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The two sites are very close to each other.\", \"vi\": \"Hai địa điểm này nằm rất gần nhau.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Mateo Rodriguez [10:45 A.M.]\", \"vi\": \"Mateo Rodriguez [10 giờ 45 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Great.\", \"vi\": \"Tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Could you please confirm the time with Ms. Kim today?\", \"vi\": \"Xin quý vị vui lòng xác nhận lại thời gian với bà Kim trong ngày hôm nay được không?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Jane Equi [10:47 A.M.]\", \"vi\": \"Jane Equi [10 giờ 47 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sure.\", \"vi\": \"Được ạ.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '899fb48a-2e4e-4b75-8748-6160fd3aa9c1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Donna Witt <d.witt@seemail.net>; Jack Witt <j.witt@seemail.net>\", \"vi\": \"Gửi tới: Donna Witt <d.witt@seemail.net>; Jack Witt <j.witt@seemail.net>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: David Paltz <dpaltz@emeraldglen.com>\", \"vi\": \"Từ: David Paltz <dpaltz@emeraldglen.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: August 5\", \"vi\": \"Ngày: 5 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Barkley Drive patio project\", \"vi\": \"Chủ đề: Dự án sân hiên tại Barkley Drive\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hello, Donna and Jack,\", \"vi\": \"Xin chào, Donna và Jack,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am just checking in as I finalize my schedule for the upcoming months.\", \"vi\": \"Tôi chỉ muốn liên hệ với quý vị để thông báo rằng tôi đang hoàn tất lịch trình cho những tháng sắp tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I would like to schedule a time to revisit your property and discuss your landscaping project in more detail.\", \"vi\": \"Tôi mong muốn sắp xếp một thời gian để quay lại thăm quan khu đất của quý vị và thảo luận chi tiết hơn về dự án thiết kế cảnh quan của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To get started, it would be helpful if the two of you could brainstorm some of your design expectations and overall vision for the project.\", \"vi\": \"Để bắt đầu, sẽ rất hữu ích nếu hai vị cùng nhau thảo luận và đưa ra một số kỳ vọng về thiết kế cũng như tầm nhìn tổng thể cho dự án.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Your ideas will help me better determine the materials and time needed.\", \"vi\": \"Những ý kiến của quý vị sẽ giúp tôi xác định chính xác hơn về nguyên liệu và thời gian cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I can then give a more accurate price estimate.\", \"vi\": \"Khi đó, tôi có thể đưa ra mức giá dự kiến chính xác hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"David Paltz\", \"vi\": \"David Paltz\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Emerald Glen Landscaping\", \"vi\": \"Công ty Thiết kế Cảnh quan Emerald Glen\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '89aba1ff-722c-4f20-8e75-606e59efc91f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dialed-In: The Web Site for Professional Connections\", \"vi\": \"Dialed-In: Trang web dành cho các mối quan hệ nghề nghiệp\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Quentin Rines\", \"vi\": \"Quentin Rines\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Dialed-In Code number: 04404782\", \"vi\": \"Số mã đã được thiết lập: 04404782\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Position wanted: Director of Commercial Lending\", \"vi\": \"Tuyển dụng vị trí: Giám đốc Cho vay Thương mại\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Experience:\", \"vi\": \"Kinh nghiệm:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Assistant Manager, Commercial Lending\", \"vi\": \"Phó Giám đốc, Bộ phận Cho vay Thương mại\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"First Bank of Barbados\", \"vi\": \"Ngân hàng First Bank of Barbados\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Three years, three months (present position)\", \"vi\": \"Ba năm, ba tháng (vị trí hiện tại)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Loan Officer\", \"vi\": \"Chuyên viên tín dụng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"First Bank of Barbados\", \"vi\": \"Ngân hàng First Bank of Barbados\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Three years, eight months\", \"vi\": \"Ba năm, tám tháng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Teller\", \"vi\": \"Teller\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"First Bank of Barbados\", \"vi\": \"Ngân hàng First Bank of Barbados\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"1 year, two months\", \"vi\": \"1 năm, 2 tháng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To: Quentin Rines <qrines@islandlink.bb>\", \"vi\": \"Gửi tới: Quentin Rines <qrines@islandlink.bb>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From: Rozella Huy <rozella.huy@ventana.com>\", \"vi\": \"From: Rozella Huy <rozella.huy@ventana.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Date: 14 November\", \"vi\": \"Ngày: 14 tháng 11\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Subject: Job offer\", \"vi\": \"Chủ đề: Thư mời làm việc\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Dear Mr. Rines:\", \"vi\": \"Kính gửi ông Rines,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"On behalf of all staff here at Ventana Bank, I want to say how pleased we were to meet you last week.\", \"vi\": \"Thay mặt toàn thể nhân viên tại Ngân hàng Ventana, tôi xin bày tỏ sự vui mừng của chúng tôi khi được gặp quý vị vào tuần trước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"We appreciate that you were able to spend so much time with us discussing your background and plans for the future.\", \"vi\": \"Chúng tôi rất trân trọng việc quý vị đã dành nhiều thời gian như vậy để cùng chúng tôi trao đổi về quá trình phát triển của quý vị cũng như những kế hoạch trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"We are pleased to offer you the position of director of commercial lending.\", \"vi\": \"Chúng tôi hân hạnh đề nghị quý vị đảm nhận vị trí Giám đốc phụ trách cho vay thương mại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"The position will be based in our George Town location on the Cayman Islands.\", \"vi\": \"Vị trí công việc này sẽ làm việc tại văn phòng của chúng tôi ở George Town, thuộc Quần đảo Cayman.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Should you accept the position, you will receive the pay and benefits described during the interview process, as well as a relocation reimbursement of USD $1,000.\", \"vi\": \"Nếu quý vị chấp nhận vị trí này, quý vị sẽ nhận được mức lương và các quyền lợi đã được trình bày trong quá trình phỏng vấn, cũng như khoản trợ cấp di chuyển trị giá 1.000 USD.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Please let us know whether you accept the offer by 29 November and inform us of your preferred start date.\", \"vi\": \"Kính mong quý vị vui lòng thông báo cho chúng tôi biết quý vị có chấp nhận đề nghị này hay không trước ngày 29 tháng 11 và cho chúng tôi biết ngày bắt đầu công việc mà quý vị mong muốn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"We hope to have the position filled by mid-December.\", \"vi\": \"Chúng tôi hy vọng sẽ tuyển dụng được ứng viên cho vị trí này trước giữa tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Congratulations on being selected.\", \"vi\": \"Xin chúc mừng quý vị đã được lựa chọn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"We look forward to welcoming you to our team.\", \"vi\": \"Chúng tôi rất mong được chào đón quý vị gia nhập đội ngũ của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Rozella Huy\", \"vi\": \"Rozella Huy\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"President, Ventana Bank\", \"vi\": \"Chủ tịch Ngân hàng Ventana\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"To: Tomas Melville <tmelville@homenetwork.bb>\", \"vi\": \"Gửi tới: Tomas Melville <tmelville@homenetwork.bb>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"From: Quentin Rines <qrines@islandlink.bb>\", \"vi\": \"Từ: Quentin Rines <qrines@islandlink.bb>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Date: 14 November\", \"vi\": \"Ngày: 14 tháng 11\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Subject: New position\", \"vi\": \"Chủ đề: Vị trí công việc mới\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Mr. Melville,\", \"vi\": \"Thưa ông Melville,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"I just received the job offer from Ventana Bank that we discussed on Monday.\", \"vi\": \"Tôi vừa nhận được thư mời làm việc từ Ngân hàng Ventana mà chúng ta đã thảo luận vào thứ Hai.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"They are meeting my salary request and offering me money for relocating too.\", \"vi\": \"Họ đã đồng ý với mức lương mà tôi đề xuất và còn đề nghị hỗ trợ chi phí chuyển chỗ ở cho tôi nữa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"This has been my goal ever since you hired me as a teller, right out of college.\", \"vi\": \"Đây luôn là mục tiêu của tôi kể từ khi quý vị tuyển dụng tôi vào vị trí nhân viên quầy giao dịch, ngay sau khi tôi tốt nghiệp đại học.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"But now that I have been offered my dream job, I am having doubts.\", \"vi\": \"Tuy nhiên, giờ đây khi đã được đề nghị nhận công việc mơ ước, tôi lại bắt đầu nảy sinh những nghi ngờ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"The new location seems so far away.\", \"vi\": \"Địa điểm mới có vẻ rất xa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"I would rarely get to see my parents and my siblings.\", \"vi\": \"Tôi hiếm khi có cơ hội được gặp cha mẹ và các anh chị em của mình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"I would welcome your help in this matter.\", \"vi\": \"Tôi rất mong nhận được sự giúp đỡ của quý vị trong vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"Could we get together in the next few days for lunch or coffee?\", \"vi\": \"Chúng ta có thể hẹn gặp nhau trong vài ngày tới để dùng bữa trưa hoặc uống cà phê được không ạ?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"As you know, I have always valued your input, and I have missed our lunchtime conversations since you retired.\", \"vi\": \"Như quý vị đã biết, tôi luôn coi trọng ý kiến đóng góp của quý vị, và tôi rất nhớ những cuộc trò chuyện vào giờ ăn trưa của chúng ta kể từ khi quý vị nghỉ hưu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 46, \"question_numbers\": []}, {\"en\": \"Quentin\", \"vi\": \"Quentin\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 47, \"question_numbers\": []}]' WHERE `id` = '8a08f54e-23ce-488e-8e91-68d39f4ab877';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Arthur Rhodes <arhodes@birchadvisors.com>\", \"vi\": \"Từ: Arthur Rhodes <arhodes@birchadvisors.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: contact@caldwellresortrentals.com\", \"vi\": \"Gửi tới: contact@caldwellresortrentals.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Inquiry about group rental\", \"vi\": \"Chủ đề: Yêu cầu tư vấn về dịch vụ cho thuê theo nhóm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 10 November, 9:21 A.M.\", \"vi\": \"Ngày: 10 tháng 11, 9 giờ 21 phút sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Caldwell Resort Rentals (CRR),\", \"vi\": \"Kính gửi Caldwell Resort Rentals (CRR),\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"In December, my work team will take a skiing trip as a team-building activity.\", \"vi\": \"Vào tháng 12, nhóm làm việc của tôi sẽ tổ chức một chuyến đi trượt tuyết như một hoạt động gắn kết tập thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"My family and I visited Caldwell Resort last year, and everyone had a great time.\", \"vi\": \"Năm ngoái, gia đình tôi và tôi đã đến khu nghỉ dưỡng Caldwell, và mọi người đều đã có một khoảng thời gian thật tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We never used your rental service, but one of my team members said he was impressed with the quality of your items.\", \"vi\": \"Chúng tôi chưa từng sử dụng dịch vụ cho thuê của quý công ty, nhưng một thành viên trong nhóm của tôi cho biết anh ấy rất ấn tượng với chất lượng của các sản phẩm của quý công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"For our visit, skis, poles, and boots are needed.\", \"vi\": \"Để tham gia chuyến đi này, quý vị cần chuẩn bị ván trượt, gậy trượt và giày trượt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To comply with our company\'s safety guidelines, protective headgear must also be worn.\", \"vi\": \"Để tuân thủ các hướng dẫn về an toàn của công ty chúng tôi, quý vị cũng phải đội mũ bảo hộ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Please let me know your rates at your earliest convenience.\", \"vi\": \"Xin vui lòng cho tôi biết mức giá của quý vị ngay khi quý vị có thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Arthur Rhodes\", \"vi\": \"Arthur Rhodes\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"From: contact@caldwellresortrentals.com\", \"vi\": \"Nguồn: contact@caldwellresortrentals.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To: Arthur Rhodes <arhodes@birchadvisors.com>\", \"vi\": \"Gửi tới: Arthur Rhodes <arhodes@birchadvisors.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Subject: RE: Inquiry about group rental\", \"vi\": \"Chủ đề: RE: Yêu cầu thông tin về dịch vụ cho thuê theo nhóm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date: 10 November, 3:58 P.M.\", \"vi\": \"Ngày: 10 tháng 11, 3 giờ 58 phút chiều\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 CRR_Price_List\", \"vi\": \"Tệp đính kèm: 📎 CRR_Bảng giá\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Dear Mr. Rhodes,\", \"vi\": \"Kính gửi ông Rhodes,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Thank you for your interest in CRR\'s services.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã quan tâm đến các dịch vụ của CRR.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Please find attached the price list for the upcoming season.\", \"vi\": \"Kính gửi quý vị, xin vui lòng xem bảng giá cho mùa tới được đính kèm dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Due to high customer demand, we are offering snowboard rentals for the first time.\", \"vi\": \"Do nhu cầu của quý khách hàng rất cao, chúng tôi lần đầu tiên cung cấp dịch vụ cho thuê ván trượt tuyết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Our staff is available to help with selecting boot sizes to ensure a proper fit.\", \"vi\": \"Đội ngũ nhân viên của chúng tôi luôn sẵn sàng hỗ trợ quý khách lựa chọn cỡ giày để đảm bảo vừa vặn nhất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Should you have any questions, please feel free to contact me at this address or by phone at (940) 555-4802.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào, xin vui lòng liên hệ với tôi theo địa chỉ này hoặc qua số điện thoại (940) 555-4802.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I hope you and your group members have a wonderful time enjoying the slopes here at Caldwell Resort.\", \"vi\": \"Tôi hy vọng quý vị và các thành viên trong nhóm sẽ có những giây phút tuyệt vời khi trượt tuyết tại khu nghỉ dưỡng Caldwell.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"All the best,\", \"vi\": \"Chúc quý vị mọi điều tốt đẹp nhất,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Allison Millard\", \"vi\": \"Allison Millard\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Package - One-Day Rate - Two-Day Rate\", \"vi\": \"Gói dịch vụ - Giá một ngày - Giá hai ngày\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Package 1: Skis only - £22.00 - £35.00\", \"vi\": \"Gói 1: Chỉ bao gồm ván trượt tuyết - 22,00 Bảng Anh - 35,00 Bảng Anh\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Package 2: Skis, poles, & boots - £30.00 - £48.00\", \"vi\": \"Gói 2: Ván trượt tuyết, gậy trượt tuyết và giày trượt tuyết - 30,00 £ - 48,00 £\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Package 3: Skis, poles, boots, & helmet - £32.00 - £50.00\", \"vi\": \"Gói 3: Ván trượt tuyết, gậy trượt tuyết, giày trượt tuyết và mũ bảo hiểm - 32,00 £ - 50,00 £\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Package 4: Snowboard only - £25.00 - £40.00\", \"vi\": \"Gói 4: Chỉ bao gồm ván trượt tuyết - 25,00 £ - 40,00 £\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Package 5: Ski jacket, ski pants, & gloves - £22.00 - £35.00\", \"vi\": \"Gói 5: Áo khoác trượt tuyết, quần trượt tuyết và găng tay - 22,00 £ - 35,00 £\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Caldwell Resort Rentals Price List\", \"vi\": \"Bảng giá dịch vụ cho thuê tại Caldwell Resort\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"We are open from mid-November to mid-February, depending on the weather.\", \"vi\": \"Chúng tôi mở cửa từ giữa tháng 11 đến giữa tháng 2, tùy thuộc vào thời tiết.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Items must be returned by 4:30 P.M. or you will be charged for another day.\", \"vi\": \"Quý vị phải trả lại các mặt hàng trước 4 giờ 30 chiều, nếu không quý vị sẽ bị tính phí thêm một ngày.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Items are offered on a first-come, first-served basis, so reserving items in advance is strongly advised.\", \"vi\": \"Các mặt hàng được cung cấp theo nguyên tắc “ai đến trước, được phục vụ trước”, do đó, quý vị nên đặt trước các mặt hàng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"All rental charges include insurance against breakage but not against loss.\", \"vi\": \"Tất cả các khoản phí thuê đều đã bao gồm bảo hiểm đối với hư hỏng nhưng không bao gồm bảo hiểm đối với mất mát.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"We can accommodate nearly every size, from children aged 5+ up to XL adults.\", \"vi\": \"Chúng tôi có thể đáp ứng hầu hết mọi kích cỡ, từ trẻ em từ 5 tuổi trở lên cho đến người lớn cỡ XL.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}]' WHERE `id` = '8a3476fe-1dbd-46a8-bc90-1e86b380438e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: New Employees\", \"vi\": \"Kính gửi: Các nhân viên mới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Hemi Amos <hamos@motmanmotors.com>\", \"vi\": \"Từ: Hemi Amos <hamos@motmanmotors.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: June 8\", \"vi\": \"Ngày: 8 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Welcome to Motman Motors\", \"vi\": \"Chủ đề: Chào mừng quý vị đến với Motman Motors\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Information\", \"vi\": \"Tệp đính kèm: 📎 Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear New Employees,\", \"vi\": \"Kính gửi các nhân viên mới,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Welcome!\", \"vi\": \"Xin chào mừng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We are thrilled that all of you are joining Motman Motors.\", \"vi\": \"Chúng tôi vô cùng hân hoan khi tất cả quý vị đã gia nhập Motman Motors.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"New-employee orientation for all is on June 10 from 9:00 A.M. to 12:00 noon.\", \"vi\": \"Buổi hướng dẫn dành cho tất cả nhân viên mới sẽ diễn ra vào ngày 10 tháng 6, từ 9 giờ sáng đến 12 giờ trưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please report to the proper room in the Pimzler Building on our campus as indicated below.\", \"vi\": \"Kính mời quý vị đến phòng được chỉ định tại Tòa nhà Pimzler trong khuôn viên trường của chúng tôi, như được nêu dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I will come around to each room to meet the new employees briefly.\", \"vi\": \"Tôi sẽ lần lượt ghé qua từng phòng để gặp gỡ các nhân viên mới trong một thời gian ngắn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"• Marketing and Customer Service: both groups report to room 320.\", \"vi\": \"• Bộ phận Tiếp thị và Dịch vụ Khách hàng: cả hai bộ phận này đều trực thuộc phòng 320.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"• Engineering: report to room 215.\", \"vi\": \"• Khoa Kỹ thuật: xin vui lòng đến phòng 215.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"• Technology Services: report to room 158.\", \"vi\": \"• Bộ phận Dịch vụ Công nghệ: xin vui lòng đến phòng 158.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I can confirm that the employee paperwork has been finalized for most of you, so at this point we just need to ensure that your Motman Motors portal account is set up using the employee identification number recently sent to you and that your bank account information is entered there.\", \"vi\": \"Tôi xin xác nhận rằng thủ tục giấy tờ liên quan đến nhân viên đã được hoàn tất đối với hầu hết quý vị; do đó, tại thời điểm này, chúng tôi chỉ cần đảm bảo rằng tài khoản cổng thông tin Motman Motors của quý vị đã được thiết lập bằng số nhận dạng nhân viên vừa được gửi đến quý vị, đồng thời thông tin tài khoản ngân hàng của quý vị cũng đã được nhập vào hệ thống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Please follow the attached instructions to complete this final step.\", \"vi\": \"Kính mong quý vị làm theo hướng dẫn đính kèm để hoàn tất bước cuối cùng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"It should not take any more than fifteen minutes, and I ask that you do this by June 17.\", \"vi\": \"Việc này sẽ không mất quá mười lăm phút, và tôi mong quý vị hoàn thành trước ngày 17 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Don\'t hesitate to reach out if you have any questions.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào, xin đừng ngần ngại liên hệ với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Welcome aboard!\", \"vi\": \"Chào mừng quý vị đã lên tàu!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Hemi Amos\", \"vi\": \"Tôi là Amos\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Human Resources, Motman Motors\", \"vi\": \"Phòng Nhân sự, Motman Motors\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Please follow these steps to create and activate your new Motman Motors portal account.\", \"vi\": \"Vui lòng làm theo các bước sau đây để tạo và kích hoạt tài khoản cổng thông tin Motman Motors mới của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Go to https://motmanmotors.com/portal/activation to begin.\", \"vi\": \"Vui lòng truy cập https://motmanmotors.com/portal/activation để bắt đầu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Go to the \\\"New User Registration\\\" page and enter your employee ID number.\", \"vi\": \"Vui lòng truy cập trang “Đăng ký người dùng mới” và nhập số thẻ nhân viên của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Your name and address will appear.\", \"vi\": \"Tên và địa chỉ của quý vị sẽ được hiển thị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Confirm that this information is correct.\", \"vi\": \"Xin vui lòng xác nhận xem thông tin này có chính xác hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"A new screen titled \\\"Bank Account\\\" will appear.\", \"vi\": \"Một màn hình mới có tiêu đề “Tài khoản ngân hàng” sẽ xuất hiện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Fill in your bank account information.\", \"vi\": \"Vui lòng điền thông tin tài khoản ngân hàng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Finally, you will be asked to select two security questions and provide the answers.\", \"vi\": \"Cuối cùng, quý vị sẽ được yêu cầu chọn hai câu hỏi bảo mật và cung cấp câu trả lời.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Once you have created your account, your account will become active, the payroll department will be alerted, and your payment schedule will be set.\", \"vi\": \"Sau khi quý vị đã tạo tài khoản, tài khoản của quý vị sẽ được kích hoạt, bộ phận tính lương sẽ nhận được thông báo và lịch thanh toán của quý vị sẽ được thiết lập.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Please e-mail Mr. Hemi Amos at hamos@motmanmotors.com if you have any difficulties or questions.\", \"vi\": \"Nếu quý vị gặp bất kỳ khó khăn hoặc thắc mắc nào, xin vui lòng gửi email cho ông Hemi Amos theo địa chỉ hamos@motmanmotors.com.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"To: Hemi Amos <hamos@motmanmotors.com>\", \"vi\": \"Gửi tới: Hemi Amos <hamos@motmanmotors.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"From: Karuna Dimaano <kdimaano@motmanmotors.com>\", \"vi\": \"Từ: Karuna Dimaano <kdimaano@motmanmotors.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Date: June 9\", \"vi\": \"Ngày: 9 tháng 6\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Subject: Trouble with Motman Motors portal\", \"vi\": \"Chủ đề: Sự cố với cổng thông tin Motman Motors\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Dear Mr. Amos,\", \"vi\": \"Kính gửi ông Amos,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Thank you for the kind welcome e-mail yesterday.\", \"vi\": \"Xin chân thành cảm ơn quý vị về email chào đón nồng nhiệt ngày hôm qua.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"I am trying to set up my Motman Motors portal account, but I seem to be having trouble with my employee ID number.\", \"vi\": \"Tôi đang cố gắng thiết lập tài khoản trên cổng thông tin Motman Motors, nhưng dường như tôi đang gặp vấn đề với số ID nhân viên của mình.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Each time I put the information into the system, I get an error message.\", \"vi\": \"Mỗi khi tôi nhập thông tin vào hệ thống, tôi lại nhận được một thông báo lỗi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"I might not have the right number.\", \"vi\": \"Có thể tôi đã nhầm số.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Can you please advise me on how to address this?\", \"vi\": \"Xin quý vị vui lòng cho tôi biết cách giải quyết vấn đề này như thế nào?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"I also have another question.\", \"vi\": \"Tôi còn có một câu hỏi nữa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Will the orientation include any information for newcomers to San Antonio?\", \"vi\": \"Buổi giới thiệu có cung cấp bất kỳ thông tin nào dành cho những người mới đến San Antonio không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"I am excited to start exploring everything here that this great city offers.\", \"vi\": \"Tôi rất háo hức được bắt đầu khám phá tất cả những điều mà thành phố tuyệt vời này mang lại.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"I look forward to meeting you tomorrow in room 215 in the Pimzler Building.\", \"vi\": \"Tôi rất mong được gặp quý vị vào ngày mai tại phòng 215, Tòa nhà Pimzler.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 46, \"question_numbers\": []}, {\"en\": \"Karuna Dimaano\", \"vi\": \"Món bánh quỷ\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 47, \"question_numbers\": []}]' WHERE `id` = '8a65dd77-733a-4e00-a949-7b899d355e27';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Posted: November 25\", \"vi\": \"Ngày đăng: 25 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Position title and codes: Director of Operations, TL0015\\nMarketing Director, TL0023\\nQuality Control Director, TL0027\\nDirector of Category Management, TL0045\", \"vi\": \"Chức danh và mã vị trí: Giám đốc Vận hành, TL0015\\nGiám đốc Tiếp thị, TL0023\\nGiám đốc Kiểm soát Chất lượng, TL0027\\nGiám đốc Quản lý Danh mục Sản phẩm, TL0045\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To apply: Send your résumé to mdoro@cryngroup.ca.com with posting number 2098 in the subject line.\", \"vi\": \"Để nộp đơn: Vui lòng gửi sơ yếu lý lịch của quý vị đến địa chỉ mdoro@cryngroup.ca.com và ghi số thông báo tuyển dụng 2098 vào dòng tiêu đề.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"CRYN Group: We find the best employees for your company.\", \"vi\": \"Tập đoàn CRYN: Chúng tôi sẽ tìm kiếm những nhân viên xuất sắc nhất cho công ty của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Company:\", \"vi\": \"Công ty:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our client plans to chart an aggressive growth path in Latin America, where it plans to start operations next year.\", \"vi\": \"Khách hàng của chúng tôi dự định vạch ra một lộ trình tăng trưởng mạnh mẽ tại khu vực Mỹ Latinh, nơi công ty dự kiến sẽ bắt đầu hoạt động vào năm tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It is a well-established company widely known for marketing consumer-health products in North America, and more recently in Europe and Asia.\", \"vi\": \"Đây là một công ty có uy tín lâu năm, được biết đến rộng rãi nhờ hoạt động tiếp thị các sản phẩm chăm sóc sức khỏe dành cho người tiêu dùng tại Bắc Mỹ, và gần đây là tại châu Âu và châu Á.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Qualifications:\", \"vi\": \"Yêu cầu về trình độ:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Candidates must have a formal business degree and a proven management record in at least one international setting.\", \"vi\": \"Ứng viên phải có bằng cấp chính quy về kinh doanh và có thành tích quản lý đã được chứng minh trong ít nhất một môi trường quốc tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Experience with online sales and marketing preferred.\", \"vi\": \"Ưu tiên ứng viên có kinh nghiệm trong lĩnh vực bán hàng và tiếp thị trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To: Sven Arvidson <sarvidson@barkent.de.com>\", \"vi\": \"Gửi tới: Sven Arvidson <sarvidson@barkent.de.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"From: Maria Doro <mdoro@cryngroup.ca.com>\", \"vi\": \"Từ: Maria Doro <mdoro@cryngroup.ca.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Re: Posting number 2098\", \"vi\": \"Trả lời: Bài đăng số 2098\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: December 10\", \"vi\": \"Ngày: 10 tháng 12\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Dear Mr. Arvidson,\", \"vi\": \"Kính gửi ông Arvidson,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thank you for submitting your résumé.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã gửi hồ sơ xin việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I\'d like to schedule a preliminary telephone conversation with you as soon as possible to determine whether you would be a good choice for our client.\", \"vi\": \"Tôi mong muốn sắp xếp một cuộc trò chuyện sơ bộ qua điện thoại với quý vị trong thời gian sớm nhất có thể để đánh giá xem liệu quý vị có phải là ứng viên phù hợp với khách hàng của chúng tôi hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I would particularly like to discuss whether you would be prepared to work at our client\'s new facility overseas.\", \"vi\": \"Tôi đặc biệt muốn trao đổi xem quý vị có sẵn sàng làm việc tại cơ sở mới của khách hàng chúng tôi ở nước ngoài hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Let me know if you are available for a 30-minute phone call sometime between 10:00 A.M. and 2:00 P.M. EST on Monday or Tuesday of next week.\", \"vi\": \"Xin vui lòng cho tôi biết liệu quý vị có thể dành thời gian cho một cuộc gọi điện thoại kéo dài 30 phút vào khoảng thời gian từ 10 giờ sáng đến 2 giờ chiều theo giờ EST vào thứ Hai hoặc thứ Ba tuần tới hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Please respond to me by e-mail at your earliest convenience.\", \"vi\": \"Kính mong quý vị vui lòng trả lời tôi qua email ngay khi có thể.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Maria Doro\", \"vi\": \"Maria Doro\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"CRYN Group\", \"vi\": \"Tập đoàn CRYN\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"For immediate release - For further information, contact Julie Dryden at 416-555-0103\", \"vi\": \"Để công bố ngay lập tức – Để biết thêm thông tin, xin vui lòng liên hệ với bà Julie Dryden theo số 416-555-0103\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Tayerson Ltd. Names New Director\", \"vi\": \"Công ty TNHH Tayerson bổ nhiệm Giám đốc mới\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Toronto, April 5—Tayerson Ltd. continues to staff its new international outpost, which opens one month from today.\", \"vi\": \"Toronto, ngày 5 tháng 4 — Công ty Tayerson Ltd. tiếp tục tuyển dụng nhân sự cho cơ sở quốc tế mới của mình, dự kiến sẽ chính thức đi vào hoạt động sau một tháng kể từ hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"In this case, the lucky candidate is Sven Arvidson.\", \"vi\": \"Trong trường hợp này, ứng viên may mắn chính là ông Sven Arvidson.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"\\\"Category Management is a relatively new area—and one that I\'m sure I\'ll enjoy exploring and developing as director,\\\" Mr. Arvidson said.\", \"vi\": \"\\\"Quản lý danh mục là một lĩnh vực tương đối mới — và tôi tin chắc rằng mình sẽ rất hứng thú khi được khám phá và phát triển lĩnh vực này với tư cách là giám đốc,\\\" ông Arvidson phát biểu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"\\\"As a major online marketer of nutritional supplements, Tayerson is poised to lead the way toward better living while becoming a more vibrant, more profitable corporation.\\\"\", \"vi\": \"\\\"Với tư cách là một trong những đơn vị hàng đầu trong lĩnh vực tiếp thị trực tuyến các sản phẩm bổ sung dinh dưỡng, Tayerson đang sẵn sàng dẫn đầu xu hướng hướng tới một cuộc sống tốt đẹp hơn, đồng thời trở thành một tập đoàn phát triển mạnh mẽ và sinh lời hơn.\\\"\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Mr. Arvidson has held several key management positions throughout his career, most recently at Barkent Pharmaceuticals in Germany.\", \"vi\": \"Trong suốt sự nghiệp của mình, ông Arvidson đã đảm nhiệm nhiều vị trí quản lý chủ chốt, gần đây nhất là tại Công ty Dược phẩm Barkent ở Đức.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"He was also a partner at MSZ Consulting Group, where he provided marketing guidance to leading consumer-product companies in Canada and China.\", \"vi\": \"Ông cũng từng là đối tác tại MSZ Consulting Group, nơi ông đã cung cấp các tư vấn về tiếp thị cho các công ty hàng đầu trong lĩnh vực sản phẩm tiêu dùng tại Canada và Trung Quốc.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}]' WHERE `id` = '8a6e55aa-65b8-4588-b3db-5e825602f99d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Two Swan Press\", \"vi\": \"Nhà xuất bản Two Swan\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"72 Holywell Road, Edinburgh EH8 8PJ\", \"vi\": \"72 Holywell Road, Edinburgh EH8 8PJ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"4 December\", \"vi\": \"Ngày 4 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Mr. Albert Morello\", \"vi\": \"Ông Albert Morello\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"17 Peyton Avenue\", \"vi\": \"17 Đại lộ Peyton\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Kingston 5\", \"vi\": \"Kingston 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Jamaica, W.I.\", \"vi\": \"Jamaica, Tây Ấn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Dear Mr. Morello:\", \"vi\": \"Kính gửi ông Morello:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Enclosed please find your royalty payment for Understanding Our Oceans.\", \"vi\": \"Kính gửi quý vị, xin vui lòng xem kèm theo đây khoản thanh toán tiền bản quyền cho cuốn sách “Understanding Our Oceans”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You should have recently received an e-mail that listed the sales figures and the royalties due to you for the print and electronic versions of your book.\", \"vi\": \"Gần đây, quý vị hẳn đã nhận được một email nêu rõ số liệu doanh thu và số tiền bản quyền mà quý vị sẽ được nhận từ các phiên bản in và điện tử của cuốn sách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We are proud to announce that Two Swan Press was given the Publisher of the Year Award by the UK Book Industry in October.\", \"vi\": \"Chúng tôi tự hào thông báo rằng vào tháng 10 vừa qua, Two Swan Press đã vinh dự được ngành công nghiệp xuất bản Vương quốc Anh trao tặng Giải thưởng Nhà xuất bản của năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We thank the authors who have worked with us since our founding five years ago.\", \"vi\": \"Chúng tôi xin gửi lời cảm ơn đến các tác giả đã đồng hành cùng chúng tôi kể từ khi thành lập cách đây năm năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"All Two Swan Press authors are entitled to an author discount of 40 percent off any title on our Web site.\", \"vi\": \"Tất cả các tác giả của Two Swan Press đều được hưởng mức chiết khấu dành cho tác giả là 40 phần trăm khi mua bất kỳ đầu sách nào trên trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Simply use the code AUX1417 for your discount.\", \"vi\": \"Quý vị chỉ cần nhập mã AUX1417 để được giảm giá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If you have any questions at all, please do not hesitate to contact me.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào, xin đừng ngần ngại liên hệ với tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sarah Wicklin\", \"vi\": \"Sarah Wicklin\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Sarah Wicklin\", \"vi\": \"Sarah Wicklin\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Encl.\", \"vi\": \"Phụ lục.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Name: Duncan Booth\", \"vi\": \"Họ và tên: Duncan Booth\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"E-mail: mbooth@silvertech.co.uk\", \"vi\": \"Email: mbooth@silvertech.co.uk\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Date of purchase: 12 December\", \"vi\": \"Ngày mua hàng: 12 tháng 12\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Ship to: Duncan Booth\\n321 Maslin St.\\nCoatbridge ML5 1LZ, Scotland, UK\", \"vi\": \"Gửi đến: Duncan Booth\\n321 Maslin St.\\nCoatbridge ML5 1LZ, Scotland, Vương quốc Anh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"1   Business in Our Lives by Elaine Schuyler - £75.00\", \"vi\": \"1   Cuốn sách “Kinh doanh trong cuộc sống của chúng ta” của tác giả Elaine Schuyler - 75,00 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Discount Applied (AUX1417) - –30.00\", \"vi\": \"Đã áp dụng mức giảm giá (AUX1417) - –30,00\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Balance Due - £45.00\", \"vi\": \"Số tiền còn phải thanh toán - 45,00 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Paid by Credit Card ****5732\", \"vi\": \"Thanh toán bằng thẻ tín dụng ****5732\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"https://www.twoswanpress.co.uk/orderconfirmation\", \"vi\": \"https://www.twoswanpress.co.uk/orderconfirmation\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"THANK YOU FOR YOUR ORDER!\", \"vi\": \"XIN CẢM ƠN QUÝ KHÁCH ĐÃ ĐẶT HÀNG!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Special December Offer—free shipping on all orders over £35\", \"vi\": \"Ưu đãi đặc biệt tháng 12 — miễn phí vận chuyển cho tất cả các đơn hàng có giá trị từ 35 bảng trở lên\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Items from multiple orders may be combined in the same package.\", \"vi\": \"Các mặt hàng từ nhiều đơn hàng khác nhau có thể được gộp chung vào cùng một gói hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"We will notify you when your order has shipped.\", \"vi\": \"Chúng tôi sẽ thông báo cho quý khách khi đơn hàng của quý khách đã được gửi đi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}]' WHERE `id` = '8aa41992-0c70-475d-846a-af144ef21d6e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Position: Assistant EditorDate Posted: March 15\", \"vi\": \"Vị trí: Trợ lý biên tập Ngày đăng tin: 15 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Description\", \"vi\": \"Mô tả\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Goldhorse Press, an independent book publishing company focusing on North American gardening, has provided gardening advice for home gardeners for over 50 years.\", \"vi\": \"Goldhorse Press, một nhà xuất bản sách độc lập chuyên về lĩnh vực làm vườn ở Bắc Mỹ, đã cung cấp các lời khuyên về làm vườn cho những người yêu thích làm vườn tại nhà trong hơn 50 năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We are currently seeking an assistant editor to join our expanding team in Charlotte, North Carolina.\", \"vi\": \"Hiện tại, chúng tôi đang tìm kiếm một trợ lý biên tập để gia nhập đội ngũ đang ngày càng mở rộng của chúng tôi tại Charlotte, Bắc Carolina.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We offer an excellent benefits package that includes medical and dental insurance.\", \"vi\": \"Chúng tôi cung cấp một gói phúc lợi hấp dẫn, bao gồm bảo hiểm y tế và nha khoa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Responsibilities\", \"vi\": \"Nhiệm vụ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Assist editors in the acquisition of titles with mainstream appeal; develop manuscripts, collaborate with outside support, and work closely with two managing editors.\", \"vi\": \"Hỗ trợ các biên tập viên trong việc tìm kiếm các đầu sách có sức hút rộng rãi; phát triển bản thảo, phối hợp với các đối tác bên ngoài và làm việc chặt chẽ với hai biên tập viên điều hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Requirements/Qualifications\", \"vi\": \"Yêu cầu/Tiêu chuẩn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Bachelor\'s degree in a related field\", \"vi\": \"Bằng Cử nhân trong một lĩnh vực liên quan\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Minimum of one year of experience in the publishing industry\", \"vi\": \"Có ít nhất một năm kinh nghiệm trong ngành xuất bản\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Ability to pay close attention to detail\", \"vi\": \"Khả năng chú ý kỹ lưỡng đến từng chi tiết\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Comfortable working as a team member\", \"vi\": \"Có khả năng làm việc hiệu quả trong vai trò thành viên của nhóm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Some experience in gardening preferred\", \"vi\": \"Ưu tiên ứng viên có một số kinh nghiệm trong lĩnh vực làm vườn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Immediate availability\", \"vi\": \"Có sẵn ngay lập tức\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"E-mail résumé and salary requirements to humanresources@goldhorsepress.com.\", \"vi\": \"Vui lòng gửi sơ yếu lý lịch và mức lương mong muốn qua email đến địa chỉ humanresources@goldhorsepress.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '8b0c122c-56f9-4208-bfa8-69c1b237786c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Saying Yes to Financial Success\", \"vi\": \"Hãy nói “Có” với thành công tài chính\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"EDINBURGH (3 April)—Yolanda Abascal had intended to study fashion design when she first entered university in Manchester 30 years ago.\", \"vi\": \"EDINBURGH (ngày 3 tháng 4) — Yolanda Abascal đã dự định theo học ngành thiết kế thời trang khi cô lần đầu tiên nhập học tại một trường đại học ở Manchester cách đây 30 năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"But while working one summer at a small clothing boutique, she discovered a love for retail.\", \"vi\": \"Tuy nhiên, trong một mùa hè khi làm việc tại một cửa hàng thời trang nhỏ, cô đã khám phá ra niềm đam mê với lĩnh vực bán lẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"To pursue her new dream, she earned a business degree instead and opened a small store in her hometown of Edinburgh called Say Yes To Yolanda.\", \"vi\": \"Để theo đuổi ước mơ mới của mình, cô đã quyết định theo học chuyên ngành kinh doanh và mở một cửa hàng nhỏ tại quê nhà Edinburgh với tên gọi “Say Yes To Yolanda”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Fast-forward to today, and Ms. Abascal\'s small store has expanded to a successful enterprise that earns millions of pounds each year.\", \"vi\": \"Đến ngày nay, cửa hàng nhỏ của bà Abascal đã phát triển thành một doanh nghiệp thành công, mang lại doanh thu hàng triệu bảng mỗi năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This success is in part due to the magic of Vihaan Kulkarni, whom Ms. Abascal hired four years ago to develop a parallel virtual store, YesYolanda.com.\", \"vi\": \"Thành công này một phần là nhờ vào tài năng xuất sắc của ông Vihaan Kulkarni, người mà bà Abascal đã tuyển dụng cách đây bốn năm để phát triển một cửa hàng ảo song song mang tên YesYolanda.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"It was Mr. Kulkarni\'s idea to rename the flagship store Yes Yolanda to match its digital identity.\", \"vi\": \"Ý tưởng đổi tên cửa hàng flagship thành “Yes Yolanda” để phù hợp với bản sắc kỹ thuật số của cửa hàng này là của ông Kulkarni.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Ms. Abascal is a strong proponent of personal interaction, and she loves engaging with her customers.\", \"vi\": \"Bà Abascal là người rất ủng hộ việc tương tác trực tiếp và bà rất thích giao lưu với khách hàng của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"However, she realizes that an online presence is important.\", \"vi\": \"Tuy nhiên, cô nhận ra rằng sự hiện diện trên mạng là điều quan trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Yes Yolanda expects earnings from online sales alone to rise to more than £140 million this year.\", \"vi\": \"Đúng vậy, bà Yolanda dự kiến doanh thu chỉ từ mảng bán hàng trực tuyến sẽ tăng lên hơn 140 triệu bảng Anh trong năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Nearly two-thirds of these sales will come from outside Scotland, mainly the United States, Singapore, and Australia.\", \"vi\": \"Gần hai phần ba doanh số này sẽ đến từ các thị trường bên ngoài Scotland, chủ yếu là Hoa Kỳ, Singapore và Úc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Yes Yolanda\'s workforce has expanded accordingly.\", \"vi\": \"Đúng vậy, đội ngũ nhân viên của Yolanda đã được mở rộng tương ứng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Besides hiring people with technical skills to update and run the Web site, the company has just added an in-house photography studio.\", \"vi\": \"Bên cạnh việc tuyển dụng những nhân viên có kỹ năng chuyên môn để cập nhật và vận hành trang web, công ty vừa mới thành lập một studio chụp ảnh ngay tại trụ sở.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"\\\"The studio ensures that items are photographed in a timely fashion for online display,\\\" said Ms. Abascal.\", \"vi\": \"\\\"Xưởng chụp ảnh đảm bảo các sản phẩm được chụp ảnh kịp thời để trưng bày trực tuyến,\\\" bà Abascal cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"\\\"This is a necessity, since new products are added every week.\\\"\", \"vi\": \"\\\"Điều này là cần thiết, bởi vì mỗi tuần đều có sản phẩm mới được bổ sung.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Although Ms. Abascal says she does not know what the future holds, it would seem that the only direction for Yes Yolanda is up.\", \"vi\": \"Mặc dù bà Abascal cho biết bà không biết tương lai sẽ ra sao, nhưng có vẻ như con đường duy nhất dành cho Yes Yolanda là tiếp tục phát triển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '8b213570-328d-4403-a293-190f2169fc9f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Thompson and Groves\", \"vi\": \"Thompson và Groves\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The law firm of Thompson and Groves is seeking a dedicated assistant to join our established environmental litigation team.\", \"vi\": \"Văn phòng luật sư Thompson and Groves đang tìm kiếm một trợ lý tận tâm để gia nhập đội ngũ chuyên về tranh tụng môi trường đã có uy tín của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This assistant will work on a wide range of legal services, such as\", \"vi\": \"Trợ lý này sẽ đảm nhận nhiều loại hình dịch vụ pháp lý khác nhau, chẳng hạn như\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"investigating evidence related to cases being prepared for court;\", \"vi\": \"xem xét các chứng cứ liên quan đến các vụ án đang được chuẩn bị đưa ra tòa;\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"preparing exhibits, charts, and diagrams to display information; and\", \"vi\": \"chuẩn bị các vật trưng bày, biểu đồ và sơ đồ để trình bày thông tin; và\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"communicating with clients and keeping files updated.\", \"vi\": \"liên lạc với khách hàng và cập nhật hồ sơ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The best candidate for this position\", \"vi\": \"Ứng viên phù hợp nhất cho vị trí này\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"is self-directed, responsible, and capable of juggling many projects at once; and\", \"vi\": \"là người có khả năng tự chủ, có tinh thần trách nhiệm và có khả năng xử lý đồng thời nhiều dự án; và\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"has strong communication, organization, and computer skills.\", \"vi\": \"có kỹ năng giao tiếp, tổ chức công việc và sử dụng máy tính rất tốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To apply, e-mail your résumé to Julia Powell (in human resources), julia.powell@thompsonandgroves.com, by May 25.\", \"vi\": \"Để nộp đơn, vui lòng gửi sơ yếu lý lịch của quý vị qua email đến bà Julia Powell (phòng Nhân sự), địa chỉ julia.powell@thompsonandgroves.com, trước ngày 25 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Interviews will be conducted at the beginning of June, and our selection will be made in early July.\", \"vi\": \"Các buổi phỏng vấn sẽ được tổ chức vào đầu tháng 6, và quá trình tuyển chọn sẽ được tiến hành vào đầu tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: julia.powell@thompsonandgroves.com\", \"vi\": \"Gửi tới: julia.powell@thompsonandgroves.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From: jonas_ivanov@sidmail.com\", \"vi\": \"Nguồn: jonas_ivanov@sidmail.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: July 12\", \"vi\": \"Ngày: 12 tháng 7\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Subject: Re: Legal assistant position\", \"vi\": \"Chủ đề: Trả lời: Vị trí trợ lý pháp lý\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dear Ms. Powell,\", \"vi\": \"Kính gửi Bà Powell,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I was pleased to read your letter offering me the position of legal assistant.\", \"vi\": \"Tôi rất vui khi nhận được thư của quý vị đề nghị tôi đảm nhận vị trí trợ lý pháp lý.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"However, after much consideration, I have decided that now is not the best time to leave Wilson Law.\", \"vi\": \"Tuy nhiên, sau khi cân nhắc kỹ lưỡng, tôi đã quyết định rằng hiện tại chưa phải là thời điểm thích hợp nhất để rời khỏi Công ty Luật Wilson.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I did not realize how deeply I am invested in working on my projects here until I was faced with the possibility of leaving the company.\", \"vi\": \"Tôi đã không nhận ra rằng mình đã dành nhiều tâm huyết đến mức nào cho các dự án tại đây cho đến khi phải đối mặt với khả năng rời khỏi công ty.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"While I was thrilled by the idea of working for an illustrious law firm that has won so many high-profile environmental cases, now is not the time for me to make a change.\", \"vi\": \"Dù tôi vô cùng hào hứng trước viễn cảnh được làm việc tại một công ty luật danh tiếng đã giành chiến thắng trong rất nhiều vụ kiện môi trường được dư luận quan tâm, nhưng hiện tại chưa phải là thời điểm thích hợp để tôi thực hiện sự thay đổi này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"It was a pleasure meeting you and your colleagues, and I hope we cross paths in the future.\", \"vi\": \"Thật vui khi được gặp quý vị và các đồng nghiệp của quý vị, và tôi hy vọng chúng ta sẽ có dịp gặp lại nhau trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Jonas Ivanov\", \"vi\": \"Jonas Ivanov\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '8b8acd88-618e-46c4-834c-0716797cff7d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"City of Altamesa seeks election workers\", \"vi\": \"Thành phố Altamesa đang tuyển dụng nhân viên phục vụ công tác bầu cử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Who is qualified to be an election worker?\", \"vi\": \"Ai đủ điều kiện để trở thành nhân viên bầu cử?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Almost anyone, including homemakers and professionals, as well as those who are unemployed, self-employed, or retired.\", \"vi\": \"Hầu như bất kỳ ai, bao gồm cả các bà nội trợ và các chuyên gia, cũng như những người đang thất nghiệp, làm việc tự do hoặc đã nghỉ hưu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Requirements:\", \"vi\": \"Yêu cầu:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Available 6 A.M. to 1 P.M. or 1 P.M. to 8 P.M. on March 5, June 7, and November 1\", \"vi\": \"Có sẵn từ 6 giờ sáng đến 1 giờ chiều hoặc từ 1 giờ chiều đến 8 giờ tối vào các ngày 5 tháng 3, 7 tháng 6 và 1 tháng 11\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Is not a politician and does not live with or work for a politician\", \"vi\": \"Không phải là một chính trị gia và cũng không sống chung hay làm việc cho một chính trị gia\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Is 18 years of age or older\", \"vi\": \"Đủ 18 tuổi trở lên\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Is comfortable interacting with the public\", \"vi\": \"Cảm thấy thoải mái khi giao tiếp với công chúng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Is organized and detail-oriented\", \"vi\": \"Có tính tổ chức và chú trọng đến từng chi tiết\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Workers must attend a four-hour pre-election training workshop on March 4 and will be compensated based on their title:\", \"vi\": \"Các nhân viên phải tham dự một buổi tập huấn trước bầu cử kéo dài bốn giờ vào ngày 4 tháng 3 và sẽ được trả thù lao tùy theo chức danh của mình:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Election Assistant, $18/hour\", \"vi\": \"Trợ lý bầu cử, 18 USD/giờ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Election Clerk, $20/hour\", \"vi\": \"Nhân viên phụ trách bầu cử, 20 đô la/giờ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Election Chief, $22/hour\", \"vi\": \"Trưởng ban bầu cử, 22 đô la/giờ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"For details or to apply, visit www.altamesaelections.gov/apply.\", \"vi\": \"Để biết thêm chi tiết hoặc nộp đơn, vui lòng truy cập trang web www.altamesaelections.gov/apply.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '8ba2b842-37e1-431b-b919-f46a1730fc8e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.collingswoodglobal.com/about\", \"vi\": \"https://www.collingswoodglobal.com/about\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The international trade business can be complicated, especially if you are unfamiliar with the steps and documentation involved.\", \"vi\": \"Hoạt động thương mại quốc tế có thể khá phức tạp, đặc biệt là nếu quý vị chưa quen thuộc với các bước thực hiện và các loại giấy tờ liên quan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Guidelines vary from country to country, and special licenses and permits may be needed.\", \"vi\": \"Các quy định có sự khác biệt giữa các quốc gia, và có thể cần phải có các giấy phép và chứng nhận đặc biệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Let the experienced consultants at Collingswood Global help!\", \"vi\": \"Hãy để các chuyên gia tư vấn giàu kinh nghiệm tại Collingswood Global hỗ trợ quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"First, you will complete our short questionnaire about your business.\", \"vi\": \"Trước tiên, quý vị sẽ điền vào bảng câu hỏi ngắn của chúng tôi về doanh nghiệp của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Once we assess your needs, we will match you with one of our team members, listed below.\", \"vi\": \"Sau khi đánh giá nhu cầu của quý vị, chúng tôi sẽ giới thiệu quý vị đến một trong các thành viên trong đội ngũ của chúng tôi, được liệt kê dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"• Margaret Giordano: agricultural products\", \"vi\": \"• Margaret Giordano: các sản phẩm nông nghiệp\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"• Jonah Woodrow: household appliances\", \"vi\": \"• Jonah Woodrow: các thiết bị gia dụng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"• Felicity Wong: precious stones\", \"vi\": \"• Felicity Wong: đá quý\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"• Malik Fadel: automotive parts\", \"vi\": \"• Malik Fadel: phụ tùng ô tô\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We offer a single introductory session for $329 per hour.\", \"vi\": \"Chúng tôi cung cấp một buổi giới thiệu duy nhất với mức phí 329 đô la mỗi giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Your consultant will determine the rates for any subsequent sessions based on your needs.\", \"vi\": \"Chuyên viên tư vấn của quý vị sẽ xác định mức phí cho các buổi tư vấn tiếp theo dựa trên nhu cầu của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"If you would like to receive guidance regularly, you would pay a monthly retainer at a cost to be negotiated during the introductory session.\", \"vi\": \"Nếu quý vị mong muốn nhận được sự tư vấn thường xuyên, quý vị sẽ phải thanh toán một khoản phí cố định hàng tháng với mức chi phí sẽ được thỏa thuận trong buổi gặp gỡ ban đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"HomeAboutServicesContact Us\", \"vi\": \"Trang chủGiới thiệuDịch vụLiên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To: contact@collingswoodglobal.com\", \"vi\": \"Gửi tới: contact@collingswoodglobal.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From: Sanjeev Yadav <sanjeev.yadav@isvaraniltd.com>\", \"vi\": \"Từ: Sanjeev Yadav <sanjeev.yadav@isvaraniltd.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Date: December 12\", \"vi\": \"Ngày: 12 tháng 12\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Subject: Preconsultation questionnaire follow-up\", \"vi\": \"Chủ đề: Theo dõi kết quả bảng câu hỏi tham vấn sơ bộ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To Whom It May Concern:\", \"vi\": \"Kính gửi quý vị có liên quan,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I filled out the questionnaire on your Web page, but I am not sure that my form went through.\", \"vi\": \"Tôi đã điền vào bảng câu hỏi trên trang web của quý vị, nhưng tôi không chắc liệu biểu mẫu của tôi đã được gửi đi thành công hay chưa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I never got a confirmation e-mail.\", \"vi\": \"Tôi chưa bao giờ nhận được email xác nhận.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"As I mentioned in the form, we are a five-year-old company specializing in high-end washers and dryers.\", \"vi\": \"Như tôi đã đề cập trong mẫu đơn, chúng tôi là một công ty đã hoạt động được năm năm, chuyên về các dòng máy giặt và máy sấy cao cấp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"We sell our machines to stores all along the East Coast of the United States and are well-informed about domestic cargo procedures.\", \"vi\": \"Chúng tôi cung cấp máy móc cho các cửa hàng dọc theo toàn bộ Bờ Đông của Hoa Kỳ và am hiểu sâu sắc về các thủ tục vận chuyển hàng hóa nội địa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"However, we want to venture into international trade, particularly throughout Europe, and we would like ongoing support in this endeavor.\", \"vi\": \"Tuy nhiên, chúng tôi mong muốn mở rộng hoạt động sang lĩnh vực thương mại quốc tế, đặc biệt là trên khắp châu Âu, và chúng tôi rất mong nhận được sự hỗ trợ liên tục trong nỗ lực này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Please contact me to discuss Isvarani Ltd.\'s needs in more detail.\", \"vi\": \"Kính mong quý vị liên hệ với tôi để thảo luận chi tiết hơn về các nhu cầu của Công ty Isvarani Ltd.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Many thanks,\", \"vi\": \"Xin chân thành cảm ơn,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Sanjeev Yadav, Owner, Isvarani Ltd.\", \"vi\": \"Ông Sanjeev Yadav, Chủ sở hữu Công ty TNHH Isvarani\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = '8baba712-7b55-47d6-a0ff-870725dc2626';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ichiro Watanabe (9:30 A.M.)\", \"vi\": \"Ichiro Watanabe (9 giờ 30 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Does anyone have ideas before the Friday department meeting for improving the inspection process for dental offices?\", \"vi\": \"Có ai có ý kiến nào trước cuộc họp bộ phận vào thứ Sáu nhằm cải thiện quy trình kiểm tra các phòng khám nha khoa không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Suzanne Parrin (9:31 A.M.)\", \"vi\": \"Suzanne Parrin (9 giờ 31 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"There is too much paperwork.\", \"vi\": \"Có quá nhiều thủ tục giấy tờ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Perhaps inspectors could complete forms electronically.\", \"vi\": \"Có lẽ các thanh tra viên có thể điền các biểu mẫu dưới dạng điện tử.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Zachary Qian (9:32 A.M.)\", \"vi\": \"Zachary Qian (9 giờ 32 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Great idea.\", \"vi\": \"Ý tưởng thật tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"That would eliminate paper completely.\", \"vi\": \"Điều đó sẽ giúp loại bỏ hoàn toàn việc sử dụng giấy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Ichiro Watanabe (9:33 A.M.)\", \"vi\": \"Ichiro Watanabe (9 giờ 33 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"That\'s an effective way for us to save time and money, but how do we transition from using the current forms to electronic ones?\", \"vi\": \"Đó là một cách hiệu quả giúp chúng ta tiết kiệm thời gian và tiền bạc, nhưng làm thế nào để chúng ta chuyển từ việc sử dụng các mẫu đơn hiện tại sang các mẫu đơn điện tử?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"How would inspectors be trained?\", \"vi\": \"Các thanh tra viên sẽ được đào tạo như thế nào?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Suzanne Parrin (9:35 A.M.)\", \"vi\": \"Suzanne Parrin (9 giờ 35 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"What if inspectors continue to use paper forms while they\'re learning how to use the new electronic version?\", \"vi\": \"Nếu các thanh tra viên tiếp tục sử dụng biểu mẫu giấy trong quá trình làm quen với phiên bản điện tử mới thì sao?\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Zachary Qian (9:36 A.M.)\", \"vi\": \"Zachary Qian (9 giờ 36 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"That way, they would gain some experience with the electronic forms.\", \"vi\": \"Như vậy, quý vị sẽ có cơ hội tích lũy một số kinh nghiệm trong việc sử dụng các biểu mẫu điện tử.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"And maybe we could hire instructors to train our inspectors so they\'re ready for the transition.\", \"vi\": \"Và có lẽ chúng ta có thể thuê các giảng viên để đào tạo đội ngũ thanh tra viên của chúng ta, nhằm giúp họ sẵn sàng cho quá trình chuyển đổi này.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Suzanne Parrin (9:38 A.M.)\", \"vi\": \"Suzanne Parrin (9 giờ 38 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Exactly.\", \"vi\": \"Chính xác là vậy.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We could hold the training sessions here at the labor Department.\", \"vi\": \"Chúng ta có thể tổ chức các buổi tập huấn ngay tại Sở Lao động này.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Ichiro Watanabe (9:40 A.M.)\", \"vi\": \"Ichiro Watanabe (9 giờ 40 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 7, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Great.\", \"vi\": \"Tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I\'ll propose these ideas at the meeting.\", \"vi\": \"Tôi sẽ trình bày những ý tưởng này tại cuộc họp.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '8be16619-6bde-4385-96e4-1aca90b7d125';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"💻 👤                          — ☐ ✕\", \"vi\": \"💻 👤                          — ☐ ✕\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"▼   ▷\", \"vi\": \"▼   ▷\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}]' WHERE `id` = '8c10df7c-399f-4ef1-ae05-c7be692b8204';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Date of service - Description - Price\", \"vi\": \"Ngày cung cấp dịch vụ - Mô tả - Giá cả\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"6 September - Office cleaning - $80\", \"vi\": \"Ngày 6 tháng 9 - Dọn dẹp văn phòng - 80 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"13 September - Office cleaning\\nRug cleaning - $80\\n$135\", \"vi\": \"Ngày 13 tháng 9 - Dọn dẹp văn phòng\\nGiặt thảm - 80 đô la\\n135 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"20 September - Office cleaning - $80\", \"vi\": \"Ngày 20 tháng 9 – Dọn dẹp văn phòng – 80 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"27 September - Office cleaning\\nWindow washing - $80\\n$115\", \"vi\": \"Ngày 27 tháng 9 - Dọn dẹp văn phòng\\nRửa cửa sổ - 80 đô la\\n115 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Preferred customer discount (10%): –$57\", \"vi\": \"Giảm giá dành cho khách hàng thân thiết (10%): –57 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Balance due: $513\", \"vi\": \"Số tiền còn phải thanh toán: 513 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Gleelan Commercial Cleaning\", \"vi\": \"Dịch vụ Vệ sinh Thương mại Gleelan\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"632 Oakland St., Halifax, NS B3J 3J5\", \"vi\": \"632 Oakland St., Halifax, NS B3J 3J5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"www.gleelancleaning.com.ca\", \"vi\": \"www.gleelancleaning.com.ca\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Phone: 902-555-0111\", \"vi\": \"Điện thoại: 902-555-0111\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Invoice:  705526\", \"vi\": \"Hóa đơn: 705526\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Bill to:  Endora Gellis\", \"vi\": \"Hóa đơn gửi tới: Endora Gellis\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Jant Advertising\", \"vi\": \"Công ty Quảng cáo Jant\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"1900 Barrington St., Suite 230\", \"vi\": \"1900 Barrington St., Phòng 230\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Halifax, NS B3J 1P2\", \"vi\": \"Halifax, NS B3J 1P2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Date:     1 October\", \"vi\": \"Ngày:     1 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Account: 30056JA\", \"vi\": \"Tài khoản: 30056JA\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"For billing questions, please contact our billing manager at billing@gleelancleaning.com.ca.\", \"vi\": \"Đối với các thắc mắc liên quan đến thanh toán, xin vui lòng liên hệ với Trưởng phòng Thanh toán của chúng tôi qua địa chỉ email billing@gleelancleaning.com.ca.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: Endora Gellis <egellis@jantad.com.ca>\", \"vi\": \"Từ: Endora Gellis <egellis@jantad.com.ca>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"To: Gleelan Commercial Cleaning <billing@gleelancleaning.com.ca>\", \"vi\": \"Gửi tới: Công ty Vệ sinh Thương mại Gleelan <billing@gleelancleaning.com.ca>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subject: Billing question\", \"vi\": \"Chủ đề: Thắc mắc về hóa đơn\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Date: 2 October\", \"vi\": \"Ngày: 2 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Xin chào\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I am writing concerning the invoice we received at Jant Advertising yesterday.\", \"vi\": \"Tôi viết thư này liên quan đến hóa đơn mà chúng tôi đã nhận được tại Công ty Quảng cáo Jant vào ngày hôm qua.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"It appears there has been a mistake.\", \"vi\": \"Có vẻ như đã xảy ra một sai sót.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"We had requested that the windows be washed at the end of last month, but you had to cancel that particular service.\", \"vi\": \"Chúng tôi đã yêu cầu lau cửa sổ vào cuối tháng trước, nhưng quý vị đã phải hủy dịch vụ đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"However, a charge for it is included on the invoice.\", \"vi\": \"Tuy nhiên, khoản phí này đã được ghi rõ trên hóa đơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"We would like to schedule the window washing for early this month, if possible, before the weather gets too cold.\", \"vi\": \"Chúng tôi mong muốn sắp xếp lịch lau cửa sổ vào đầu tháng này, nếu có thể, trước khi thời tiết trở nên quá lạnh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"In the meantime, could you please send us a corrected invoice?\", \"vi\": \"Trong thời gian chờ đợi, xin quý vị vui lòng gửi cho chúng tôi hóa đơn đã được điều chỉnh được không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Endora Gellis\", \"vi\": \"Endora Gellis\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Jant Advertising\", \"vi\": \"Công ty Quảng cáo Jant\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"E-Mail Message\", \"vi\": \"Thông điệp email\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"From: Burt Radke <bradke@gleelancleaning.com.ca>\", \"vi\": \"Từ: Burt Radke <bradke@gleelancleaning.com.ca>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"To: Endora Gellis <egellis@jantad.com.ca>\", \"vi\": \"Gửi tới: Endora Gellis <egellis@jantad.com.ca>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Subject: RE: Billing question\", \"vi\": \"Chủ đề: RE: Thắc mắc về hóa đơn\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Date: 3 October\", \"vi\": \"Ngày: 3 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Dear Ms. Gellis,\", \"vi\": \"Kính gửi bà Gellis,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Thank you for contacting us regarding your September services.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã liên hệ với chúng tôi về các dịch vụ trong tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"On behalf of our Billing Department, I would like to apologize for the mistake.\", \"vi\": \"Thay mặt cho Phòng Kế toán của chúng tôi, tôi xin gửi lời xin lỗi về sai sót này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"You are correct that we canceled the window washing that was scheduled.\", \"vi\": \"Quý vị nói đúng, chúng tôi đã hủy dịch vụ lau cửa sổ đã được lên lịch trước đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"There was a rainstorm on that day.\", \"vi\": \"Hôm đó có một cơn mưa giông.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"We will remove the charge and send you a corrected invoice today.\", \"vi\": \"Chúng tôi sẽ hủy khoản phí này và gửi cho quý vị hóa đơn đã được điều chỉnh trong ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"And because it was our error, please note that we will still provide the full discount that was listed on the invoice for September.\", \"vi\": \"Và vì đây là lỗi từ phía chúng tôi, xin quý vị lưu ý rằng chúng tôi vẫn sẽ áp dụng mức chiết khấu đầy đủ như đã ghi trên hóa đơn tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"I have checked with the scheduling department, and they can reschedule your window washing for 11 October to coincide with your regular office cleaning.\", \"vi\": \"Tôi đã liên hệ với bộ phận lập lịch và được biết họ có thể sắp xếp lại lịch lau cửa sổ của quý vị vào ngày 11 tháng 10 để trùng với lịch dọn dẹp văn phòng thường xuyên của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 46, \"question_numbers\": []}, {\"en\": \"Please confirm if this is suitable for Jant Advertising.\", \"vi\": \"Kính mong Quý vị xác nhận xem nội dung này có phù hợp với Jant Advertising hay không.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 47, \"question_numbers\": []}, {\"en\": \"Thank you for your continued business with us.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã luôn tin tưởng và ủng hộ chúng tôi.\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 48, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 49, \"question_numbers\": []}, {\"en\": \"Burt Radke\", \"vi\": \"Burt Radke\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 50, \"question_numbers\": []}, {\"en\": \"Gleelan Commercial Cleaning\", \"vi\": \"Dịch vụ Vệ sinh Thương mại Gleelan\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 51, \"question_numbers\": []}]' WHERE `id` = '8c5fac92-1ee6-4b07-ba17-effeff6a99a8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Bulletin boards at Quenten Advertising\", \"vi\": \"Bảng thông báo tại Công ty Quảng cáo Quenten\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The physical bulletin boards in our facilities are overseen by the administrative assistant in the Human Resources Department.\", \"vi\": \"Các bảng thông báo tại cơ sở của chúng tôi do trợ lý hành chính thuộc Phòng Nhân sự phụ trách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The bulletin boards are in locked glass cabinets, and the administrative assistant is responsible for the cabinet keys and for ensuring that all postings are kept current.\", \"vi\": \"Các bảng thông báo được đặt trong tủ kính có khóa, và trợ lý hành chính có trách nhiệm quản lý chìa khóa tủ cũng như đảm bảo rằng tất cả các thông báo được cập nhật kịp thời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The bulletin board by the elevator is used to convey general information to all employees, such as important company news or reminders.\", \"vi\": \"Bảng thông báo đặt cạnh thang máy được sử dụng để truyền đạt các thông tin chung đến toàn thể nhân viên, chẳng hạn như các tin tức quan trọng của công ty hoặc các lời nhắc nhở.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The bulletin board outside the conference rooms is used solely for information relating to upcoming meetings and events scheduled for those rooms.\", \"vi\": \"Bảng thông báo bên ngoài các phòng hội nghị chỉ được sử dụng để đăng tải thông tin liên quan đến các cuộc họp và sự kiện sắp diễn ra tại các phòng đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The staff lounge bulletin board may be used for announcements not sponsored by Quenten Advertising that may be of general interest to coworkers, such as personal items for sale, local festivals, and other community events.\", \"vi\": \"Bảng thông báo tại phòng nghỉ nhân viên có thể được sử dụng để đăng các thông báo không do Công ty Quảng cáo Quenten tài trợ nhưng có thể thu hút sự quan tâm chung của các đồng nghiệp, chẳng hạn như các mặt hàng cá nhân rao bán, các lễ hội địa phương và các sự kiện cộng đồng khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To post these notices, staff must first submit a request to Human Resources and include contact information as well as a photocopy of the posting.\", \"vi\": \"Để đăng các thông báo này, nhân viên trước tiên phải gửi yêu cầu đến Phòng Nhân sự và đính kèm thông tin liên hệ cũng như bản sao của thông báo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"These announcements cannot be posted more than two weeks before the event date.\", \"vi\": \"Các thông báo này không được đăng sớm hơn hai tuần so với ngày diễn ra sự kiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"All bulletin boards will be checked regularly to ensure compliance with their intended purposes.\", \"vi\": \"Tất cả các bảng thông báo sẽ được kiểm tra thường xuyên để đảm bảo việc sử dụng đúng mục đích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '8c62f3ba-d72e-45c6-bceb-f12b4cea126d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"STATON GRILL CORPORATE HEADQUARTERS\", \"vi\": \"TRỤ SỞ CHÍNH CỦA TẬP ĐOÀN STATON GRILL\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"UPCOMING WEBINAR\", \"vi\": \"HỘI THẢO TRỰC TUYẾN SẮP DIỄN RA\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Topic: Customer Satisfaction\", \"vi\": \"Chủ đề: Mức độ hài lòng của khách hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Speaker: Manuel Rios, founder of Rios Restaurant Consulting and author of Front of House: The Importance of Hospitality in Restaurants\", \"vi\": \"Diễn giả: Manuel Rios, người sáng lập Công ty Tư vấn Nhà hàng Rios và là tác giả cuốn sách *Front of House: Tầm quan trọng của sự hiếu khách trong các nhà hàng*\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Date: 19 September, 10:00 A.M.\", \"vi\": \"Ngày: 19 tháng 9, 10 giờ sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Venue: www.v-meet.co.uk (Event ID: 093 657 893)\", \"vi\": \"Địa điểm: www.v-meet.co.uk (Mã sự kiện: 093 657 893)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This Webinar is mandatory for Staton Grill employees who interact directly with patrons.\", \"vi\": \"Buổi hội thảo trực tuyến này là bắt buộc đối với các nhân viên của Staton Grill có tiếp xúc trực tiếp với khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Computer access is required.\", \"vi\": \"Cần có máy tính để truy cập.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please join by 9:55 to prevent delays.\", \"vi\": \"Kính mong quý vị tham gia trước 9 giờ 55 để tránh tình trạng chậm trễ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '8c660f6b-99f0-4f1c-875f-28be057c4acd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Rebecca Whipple\", \"vi\": \"Từ: Rebecca Whipple\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Thomas Morgan\", \"vi\": \"Kính gửi: Thomas Morgan\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Re: Inquiry\", \"vi\": \"Chủ đề: Trả lời: Yêu cầu thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: January 11\", \"vi\": \"Ngày: 11 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Tuition Assistance Program Form\", \"vi\": \"Tài liệu đính kèm: 📎 Mẫu đơn Chương trình Hỗ trợ Học phí\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Mr. Morgan,\", \"vi\": \"Kính gửi ông Morgan,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Thank you for your inquiry about Brennan Insurance\'s tuition assistance for employees who enroll at Esquivel University.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã liên hệ để tìm hiểu về chương trình hỗ trợ học phí của Brennan Insurance dành cho các nhân viên đăng ký theo học tại Đại học Esquivel.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Having completed your first year of employment, you do indeed qualify for this benefit.\", \"vi\": \"Sau khi hoàn thành năm làm việc đầu tiên, quý vị thực sự đủ điều kiện để được hưởng quyền lợi này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Before taking any other steps, please speak to your department head, Ms. Yoshida, to check that she will provide you with the managerial recommendation required as part of the program application.\", \"vi\": \"Trước khi thực hiện bất kỳ bước nào khác, xin vui lòng trao đổi với Trưởng phòng của quý vị, bà Yoshida, để xác nhận rằng bà sẽ cấp cho quý vị thư giới thiệu từ cấp quản lý – đây là một trong những yêu cầu bắt buộc trong hồ sơ đăng ký chương trình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Next, visit this page to request an advising session with an enrollment counselor at Esquivel to design your educational path.\", \"vi\": \"Tiếp theo, vui lòng truy cập trang này để đăng ký một buổi tư vấn với chuyên viên tư vấn tuyển sinh tại Esquivel nhằm xây dựng lộ trình học tập cho bản thân.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The university offers two associate degrees and more than 50 bachelor\'s degrees, most of which can be pursued part-time.\", \"vi\": \"Trường đại học này cung cấp hai chương trình cấp bằng cao đẳng và hơn 50 chương trình cấp bằng cử nhân, trong đó phần lớn có thể theo học theo hình thức bán thời gian.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Before your advising session, it is recommended that you prepare details about any college or university credits you already possess so that the counselor can determine whether they can be used toward your desired degree at Esquivel.\", \"vi\": \"Trước buổi tư vấn, quý vị nên chuẩn bị thông tin chi tiết về các tín chỉ đại học hoặc cao đẳng mà quý vị đã có để chuyên viên tư vấn có thể xác định liệu những tín chỉ đó có thể được tính vào chương trình cấp bằng mà quý vị mong muốn theo học tại Esquivel hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Once you are ready, you may apply to our program by completing the attached form.\", \"vi\": \"Khi quý vị đã sẵn sàng, quý vị có thể nộp đơn đăng ký tham gia chương trình của chúng tôi bằng cách điền vào mẫu đơn đính kèm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Rebecca Whipple\", \"vi\": \"Rebecca Whipple\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Employee Benefits Counselor, Brennan Insurance\", \"vi\": \"Chuyên viên tư vấn phúc lợi nhân viên, Công ty Bảo hiểm Brennan\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '8ca21855-9702-4b90-8cfd-107fb22527ca';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Hartridge University School of Business\", \"vi\": \"Trường Kinh doanh thuộc Đại học Hartridge\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear Ms. Wu:\", \"vi\": \"Kính gửi Bà Wu:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"As the Hartridge University School of Business prepares the 100th-anniversary edition of the Alumni Directory, we are reviewing the information we have on file for all graduates of our programs.\", \"vi\": \"Trong bối cảnh Trường Kinh doanh thuộc Đại học Hartridge đang chuẩn bị ấn bản kỷ niệm 100 năm của Danh bạ Cựu sinh viên, chúng tôi đang rà soát lại thông tin hiện có trong hồ sơ về tất cả các cựu sinh viên đã tốt nghiệp các chương trình đào tạo của trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We need your assistance in checking the accuracy of the records we have for you.\", \"vi\": \"Chúng tôi cần sự hỗ trợ của quý vị trong việc kiểm tra tính chính xác của các hồ sơ mà chúng tôi đang lưu giữ về quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We want to be certain that your biography, career summary, and contact information are up-to-date.\", \"vi\": \"Chúng tôi mong muốn đảm bảo rằng tiểu sử, tóm tắt sự nghiệp và thông tin liên hệ của quý vị luôn được cập nhật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Please call us at 207-555-0125 between 9 A.M. and 9 P.M. Monday through Friday.\", \"vi\": \"Xin vui lòng gọi cho chúng tôi theo số 207-555-0125 từ 9 giờ sáng đến 9 giờ tối, từ thứ Hai đến thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"At the voice prompt, enter this unique number: 293883.\", \"vi\": \"Khi nghe lời nhắc bằng giọng nói, xin vui lòng nhập số duy nhất sau đây: 293883.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"A representative will then go over your file with you and record any corrections or updates that you give.\", \"vi\": \"Sau đó, một đại diện sẽ cùng quý vị xem xét hồ sơ và ghi lại mọi chỉnh sửa hoặc cập nhật mà quý vị cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Note that we need to hear from you by March 31.\", \"vi\": \"Xin lưu ý rằng chúng tôi cần nhận được phản hồi từ quý vị trước ngày 31 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Thank you for your time and attention.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã dành thời gian và sự quan tâm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Jutta Verhoeven\", \"vi\": \"Jutta Verhoeven\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Director of Alumni Relations\", \"vi\": \"Giám đốc phụ trách quan hệ cựu sinh viên\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '8cf669a6-6fc0-4f2b-849d-6a925b0d4d86';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: hemrich@midlandmail.com\", \"vi\": \"Từ: hemrich@midlandmail.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: ltoscani@napoliballetschool.com\", \"vi\": \"Đến: ltoscani@napoliballetschool.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: September 26\", \"vi\": \"Ngày: Ngày 26 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Job opening\", \"vi\": \"Chủ đề: Tuyển dụng việc làm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Résumé_emrich\", \"vi\": \"Đính kèm: Résumé_emrich\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Toscani,\", \"vi\": \"Kính gửi bà Toscani,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am contacting you with regard to the job advertisement you posted in the most recent issue of the Napoli Ballet School newsletter.\", \"vi\": \"Tôi liên hệ với bà liên quan đến thông báo tuyển dụng mà bà đã đăng trên số mới nhất của bản tin Trường Ba-lê Napoli.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I have a great deal of respect for your ______[131], and many of my friends and acquaintances have taken lessons there.\", \"vi\": \"Tôi rất tôn trọng ______[131] của bà, và nhiều bạn bè cũng như người quen của tôi đã từng theo học ở đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [131]}, {\"en\": \"I would be ______[132] to contribute to the site as a dance instructor.\", \"vi\": \"Tôi rất ______[132] được đóng góp cho trung tâm với tư cách là một giáo viên dạy múa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [132]}, {\"en\": \"I have worked with dancers of a wide range of ages and ability levels.\", \"vi\": \"Tôi đã từng làm việc với các vũ công ở nhiều độ tuổi và trình độ khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"______[133], I would be able to adjust my teaching style to perfectly suit students\' individual needs.\", \"vi\": \"______[133], tôi có thể điều chỉnh phong cách giảng dạy của mình để phù hợp hoàn hảo với nhu cầu cá nhân của học viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [133]}, {\"en\": \"Please find attached a copy of my résumé, which outlines my training and work history.\", \"vi\": \"Vui lòng xem bản lý lịch đính kèm của tôi, trong đó phác thảo quá trình đào tạo và lịch sử công việc của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"______[134].\", \"vi\": \"______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [134]}, {\"en\": \"Should you have any questions, you can reach me at this address or at 555-3966.\", \"vi\": \"Nếu bà có bất kỳ câu hỏi nào, bà có thể liên hệ với tôi qua địa chỉ email này hoặc số điện thoại 555-3966.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I hope to hear from you soon.\", \"vi\": \"Tôi mong sớm nhận được hồi âm từ bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"All the best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Heather Emrich\", \"vi\": \"Heather Emrich\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '8d714de8-76e0-4c96-aacf-d7967aa1e8f4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Attention!\", \"vi\": \"Xin lưu ý!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Some park visitors have been intentionally stacking piles of rocks as an art form or for amusement.\", \"vi\": \"Một số du khách đến công viên đã cố ý xếp những đống đá nhằm tạo nên một tác phẩm nghệ thuật hoặc chỉ để giải trí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Please refrain from doing this on park grounds, as these unofficial rock stacks can disrupt sensitive habitats and affect the area\'s natural beauty.\", \"vi\": \"Kính mong quý vị không thực hiện hành động này trong khuôn viên công viên, vì những đống đá xếp không theo quy định này có thể làm xáo trộn các môi trường sống nhạy cảm và ảnh hưởng đến vẻ đẹp tự nhiên của khu vực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"New rock piles can also endanger hikers who traditionally rely on stacked rock markers as navigational tools.\", \"vi\": \"Những đống đá mới cũng có thể gây nguy hiểm cho những người đi bộ đường dài, những người từ xưa đến nay vẫn dựa vào các cột mốc bằng đá xếp chồng lên nhau làm phương tiện định hướng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Park officials are the only ones who should be stacking rocks, and they do so strategically on trails where the path may be unclear.\", \"vi\": \"Chỉ có các nhân viên quản lý công viên mới được phép xếp đá, và họ thực hiện việc này một cách có chiến lược trên những con đường mòn mà lối đi có thể chưa rõ ràng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"If you see rocks that have been stacked, please leave them alone, and do not create confusion by making your own stack.\", \"vi\": \"Nếu quý vị thấy những tảng đá đã được xếp chồng lên nhau, xin vui lòng đừng động vào chúng và đừng gây nhầm lẫn bằng cách tự ý xếp thêm thành đống mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '8d832b5e-05e3-4a25-97fb-6d4a2a7983f2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Personnel Department\", \"vi\": \"Từ: Phòng Nhân sự\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: June 20\", \"vi\": \"Ngày: 20 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Mentoring Program\", \"vi\": \"Chủ đề: Chương trình cố vấn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Application\", \"vi\": \"Tệp đính kèm: 📎 Đơn đăng ký\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Employees who have been with Broadside Electronics for less than eighteen months are invited to apply to participate in a new mentoring program that will match a maximum of ten junior employees with long-term company veterans.\", \"vi\": \"Các nhân viên đã làm việc tại Broadside Electronics dưới mười tám tháng được mời nộp đơn đăng ký tham gia một chương trình cố vấn mới, trong đó tối đa mười nhân viên cấp dưới sẽ được ghép đôi với các nhân viên kỳ cựu đã gắn bó lâu năm với công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The goal is that junior employees will sharpen corporate skills, better understand company culture, and develop a more focused career path.\", \"vi\": \"Mục tiêu là để các nhân viên trẻ trau dồi các kỹ năng làm việc trong môi trường doanh nghiệp, hiểu rõ hơn về văn hóa công ty và vạch ra một lộ trình nghề nghiệp rõ ràng hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Mentees will be assigned to a mentor based strictly on their work assignment and professional interests.\", \"vi\": \"Các học viên sẽ được phân công cho một người hướng dẫn dựa hoàn toàn vào nhiệm vụ công việc và sở thích nghề nghiệp của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The pairs will meet at mutually convenient times throughout the year, from three to five hours per month.\", \"vi\": \"Các cặp đôi sẽ gặp gỡ vào những thời điểm thuận tiện cho cả hai bên trong suốt cả năm, với thời lượng từ ba đến năm giờ mỗi tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To be considered for participation in this initiative, complete the attached application and return to Mentoring Program Director Tim Wrigley at t.wrigley@broadsideelec.com by July 1.\", \"vi\": \"Để được xem xét tham gia sáng kiến này, quý vị vui lòng điền đầy đủ vào đơn đăng ký đính kèm và gửi lại cho Giám đốc Chương trình Cố vấn Tim Wrigley qua địa chỉ email t.wrigley@broadsideelec.com trước ngày 1 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Mr. Wrigley will send notification of his selections by July 15.\", \"vi\": \"Ông Wrigley sẽ gửi thông báo về danh sách những người được ông lựa chọn trước ngày 15 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Name: Cora Drummond - Extension: 144\", \"vi\": \"Họ tên: Cora Drummond - Số máy lẻ: 144\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"MENTORING PROGRAM APPLICATION\", \"vi\": \"ĐƠN ĐĂNG KÝ CHƯƠNG TRÌNH TƯ VẤN\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Division: Sales\", \"vi\": \"Phòng: Kinh doanh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Professional areas of interest:\", \"vi\": \"Các lĩnh vực chuyên môn quan tâm:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I am most interested in learning about our markets abroad and developing my sales-presentation abilities for these international markets.\", \"vi\": \"Tôi đặc biệt quan tâm đến việc tìm hiểu về các thị trường nước ngoài của chúng ta và phát triển kỹ năng thuyết trình bán hàng nhằm phục vụ các thị trường quốc tế này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I am also interested in general career guidance.\", \"vi\": \"Tôi cũng quan tâm đến việc tư vấn định hướng nghề nghiệp nói chung.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Best workdays and times for meeting:\", \"vi\": \"Các ngày làm việc và khung giờ thích hợp nhất để tổ chức cuộc họp:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Any weekday morning except Monday.\", \"vi\": \"Bất kỳ buổi sáng nào trong tuần, trừ thứ Hai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Mentoring Program Sees Results\", \"vi\": \"Chương trình cố vấn đã mang lại kết quả\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"The Broadside Company Newsletter\", \"vi\": \"Bản tin của Công ty Broadside\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Long-time employee and Vice President of Sales Alena Russo was intrigued when a Personnel Department director approached her about mentoring a less experienced employee under a program that began last year.\", \"vi\": \"Bà Alena Russo, một nhân viên lâu năm kiêm Phó Chủ tịch phụ trách Kinh doanh, đã cảm thấy hứng thú khi Giám đốc Phòng Nhân sự đề nghị bà đảm nhận vai trò cố vấn cho một nhân viên còn ít kinh nghiệm trong khuôn khổ một chương trình được triển khai từ năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"She is glad to have accepted the assignment.\", \"vi\": \"Cô ấy rất vui vì đã nhận nhiệm vụ này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"\\\"After working with Ms. Drummond, I am more satisfied with my own duties, because I know I have helped a professional who is just getting started.\", \"vi\": \"\\\"Sau khi làm việc cùng bà Drummond, tôi cảm thấy hài lòng hơn với công việc của mình, bởi vì tôi biết rằng mình đã góp phần hỗ trợ một chuyên gia mới bắt đầu sự nghiệp.\\\"\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I only wish that I had had someone looking out for me in my early years,\\\" remarked Ms. Russo.\", \"vi\": \"“Tôi chỉ ước gì hồi còn nhỏ đã có ai đó quan tâm, chăm sóc cho tôi,” bà Russo chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Ms. Drummond explains that she \\\"needed pointers on how to make better sales pitches.\\\"\", \"vi\": \"Bà Drummond giải thích rằng bà “cần những lời khuyên về cách thực hiện các bài thuyết trình bán hàng hiệu quả hơn.”\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"She reports that her sales are up by 20 percent now.\", \"vi\": \"Cô cho biết doanh số bán hàng của cô hiện đã tăng 20 phần trăm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"She better understands the opportunities Broadside Electronics has to offer and what is required to become a manager.\", \"vi\": \"Cô ấy hiểu rõ hơn về những cơ hội mà Broadside Electronics mang lại cũng như những yêu cầu cần thiết để trở thành một nhà quản lý.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"\\\"Thanks to Ms. Russo, I have been able to define my career goals, and I am a happier person when I arrive to work every day.\\\"\", \"vi\": \"\\\"Nhờ có bà Russo, tôi đã có thể xác định được mục tiêu nghề nghiệp của mình, và tôi cảm thấy hạnh phúc hơn mỗi khi đến nơi làm việc hàng ngày.\\\"\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"New mentorship pairs are now being formed.\", \"vi\": \"Hiện tại, các cặp cố vấn - học viên mới đang được thành lập.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Interested parties should contact Tim Wrigley in the Personnel Department.\", \"vi\": \"Các bên quan tâm vui lòng liên hệ với ông Tim Wrigley tại Phòng Nhân sự.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = '8d8f8403-a98f-4000-97b6-f744a5df9d28';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: management_team@pfi.co.uk\", \"vi\": \"Gửi tới: management_team@pfi.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: schakravarty@pfi.co.uk\", \"vi\": \"Nguồn: schakravarty@pfi.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: R&D Director Search\", \"vi\": \"Chủ đề: Tuyển dụng Giám đốc Nghiên cứu và Phát triển\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Date: 24 July\", \"vi\": \"Ngày: 24 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Attachment: Files.txt\", \"vi\": \"Tệp đính kèm: Files.txt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Management Team Members,\", \"vi\": \"Kính gửi các thành viên Ban Lãnh đạo,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"On behalf of the hiring committee, I am pleased to report that the search for a new research and development director is nearing completion.\", \"vi\": \"Thay mặt Ban tuyển dụng, tôi vui mừng thông báo rằng quá trình tìm kiếm Giám đốc Nghiên cứu và Phát triển mới đang đi vào giai đoạn hoàn tất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Given the key selection criteria the suitable candidate must meet—a demonstrated ability to improve product offerings, a keen awareness of consumers’ tastes, and in-depth knowledge of nutritional science—we have narrowed the applicant pool to Alex Mooring and Inez Fuentes.\", \"vi\": \"Xét các tiêu chí tuyển chọn chính mà ứng viên phù hợp phải đáp ứng — khả năng đã được chứng minh trong việc cải thiện danh mục sản phẩm, sự am hiểu sâu sắc về thị hiếu của người tiêu dùng, cùng kiến thức chuyên sâu về khoa học dinh dưỡng — chúng tôi đã thu hẹp danh sách ứng viên xuống còn ông Alex Mooring và bà Inez Fuentes.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"While either makes for an excellent choice, I believe that Ms. Fuentes is better suited to the role.\", \"vi\": \"Mặc dù cả hai đều là những lựa chọn xuất sắc, tôi tin rằng bà Fuentes phù hợp hơn với vai trò này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Though somewhat less experienced than Mr. Mooring, she has innovative ideas that are in line with our company’s needs.\", \"vi\": \"Mặc dù kinh nghiệm còn ít hơn ông Mooring một chút, nhưng cô ấy có những ý tưởng sáng tạo phù hợp với nhu cầu của công ty chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Attached are the résumés and references of the two candidates.\", \"vi\": \"Kèm theo đây là sơ yếu lý lịch và thư giới thiệu của hai ứng viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The dates, times, and location of their final interviews will be forthcoming in another e-mail when that information is finalized.\", \"vi\": \"Ngày, giờ và địa điểm của các buổi phỏng vấn cuối cùng sẽ được thông báo trong một email khác khi thông tin này được xác định chính thức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We look forward to your participation in these meetings as well as your final hiring decision.\", \"vi\": \"Chúng tôi rất mong nhận được sự tham gia của quý vị trong các buổi phỏng vấn này cũng như quyết định tuyển dụng cuối cùng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Supriya Chakravarty, Chair, Hiring Committee\", \"vi\": \"Bà Supriya Chakravarty, Chủ tịch Ủy ban Tuyển dụng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Primidian Food Industries\", \"vi\": \"Công ty Cổ phần Công nghiệp Thực phẩm Primidian\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Upcoming Events at Primidian Food Industries\", \"vi\": \"Các sự kiện sắp tới tại Primidian Food Industries\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"On 7 October at 10 A.M., Ms. Inez Fuentes, director of research and development at Primidian Food Industries (PFI), will facilitate a workshop titled Food Innovation for the Future.\", \"vi\": \"Vào lúc 10 giờ sáng ngày 7 tháng 10, bà Inez Fuentes, Giám đốc bộ phận Nghiên cứu và Phát triển của Công ty Primidian Food Industries (PFI), sẽ chủ trì một hội thảo mang tên “Đổi mới trong lĩnh vực thực phẩm hướng tới tương lai”.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Among other things, she will explain why PFI recently reformulated its pasta products and demonstrate how they can be prepared in novel, tasty ways.\", \"vi\": \"Trong số những nội dung khác, bà sẽ giải thích lý do tại sao PFI gần đây đã điều chỉnh lại công thức các sản phẩm mì ống của mình và hướng dẫn cách chế biến chúng theo những phương pháp mới mẻ, thơm ngon.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Ms. Fuentes is a certified nutritionist with a degree in food science from Mexico City\'s Academy of Science and Technology.\", \"vi\": \"Bà Fuentes là một chuyên gia dinh dưỡng được cấp chứng chỉ, có bằng cử nhân khoa học thực phẩm của Học viện Khoa học và Công nghệ Thành phố Mexico.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Upon graduation, she accepted a two-year internship at Italy\'s prestigious Rome Institute of Culinary Arts.\", \"vi\": \"Sau khi tốt nghiệp, cô đã nhận lời tham gia chương trình thực tập kéo dài hai năm tại Viện Nghệ thuật Ẩm thực Rome danh tiếng của Ý.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Before joining PFI\'s executive team, she served for five years as lead product development manager at Zesty Meals, based in Montreal, Canada.\", \"vi\": \"Trước khi gia nhập đội ngũ lãnh đạo của PFI, bà đã đảm nhiệm vị trí Giám đốc phát triển sản phẩm chính tại Zesty Meals, có trụ sở tại Montreal, Canada, trong vòng năm năm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Register for this free event at www.pfi.co.uk/events/register, specifying whether you will attend online or in person at our corporate headquarters in Birmingham.\", \"vi\": \"Vui lòng đăng ký tham gia sự kiện miễn phí này tại www.pfi.co.uk/events/register, đồng thời cho biết quý vị sẽ tham dự trực tuyến hay trực tiếp tại trụ sở chính của công ty chúng tôi ở Birmingham.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Please complete the form below so someone from our team can contact you.\", \"vi\": \"Kính mong quý vị điền đầy đủ thông tin vào biểu mẫu dưới đây để một thành viên trong đội ngũ của chúng tôi có thể liên hệ với quý vị.\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"https://www.pfi.co.uk/contact-us\", \"vi\": \"https://www.pfi.co.uk/contact-us\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Who We Are - Our Brands - News and Events - Contact Us\", \"vi\": \"Giới thiệu về chúng tôi - Các thương hiệu của chúng tôi - Tin tức và sự kiện - Liên hệ với chúng tôi\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Name: Chaim Auerbach\", \"vi\": \"Họ tên: Chaim Auerbach\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"E-mail: chaim_auerbach@equisend.net.uk\", \"vi\": \"Email: chaim_auerbach@equisend.net.uk\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Your Message:\", \"vi\": \"Thông điệp của quý vị:\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I thoroughly enjoyed the Food Innovation for the Future workshop led by Ms. Fuentes on 28 October.\", \"vi\": \"Tôi đã thực sự rất thích buổi hội thảo “Đổi mới Ẩm thực vì Tương lai” do bà Fuentes chủ trì vào ngày 28 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I almost missed it, though.\", \"vi\": \"Tuy nhiên, suýt nữa thì tôi đã bỏ lỡ nó rồi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Apparently, when details about the workshop were updated, including that it would be an online-only event, my registration—and, I learned, that of some other participants—was not transferred over.\", \"vi\": \"Rõ ràng là khi các thông tin chi tiết về hội thảo được cập nhật, bao gồm cả việc sự kiện này sẽ chỉ diễn ra trực tuyến, đăng ký của tôi — và theo như tôi được biết, cả của một số người tham gia khác nữa — đã không được chuyển sang hệ thống mới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Luckily, a staffer charged with online registration was able to quickly reregister me.\", \"vi\": \"May mắn thay, một nhân viên phụ trách việc đăng ký trực tuyến đã nhanh chóng giúp tôi đăng ký lại.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"PFI may want to analyse its electronic registration system and make improvements where necessary so that this problem does not reoccur.\", \"vi\": \"PFI có thể cần phân tích hệ thống đăng ký điện tử của mình và thực hiện các cải tiến khi cần thiết để vấn đề này không tái diễn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '8d942057-526e-4c48-a4ca-59849e8e072e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"LONDON (2 June)—Locke and Jeeves, the owner of Fernsby Shoes and Athletic Footwear, announced today the acquisition of Shipley Designs for an ------- (143) amount.\", \"vi\": \"LONDON (Ngày 2 tháng 6)—Locke and Jeeves, công ty sở hữu Fernsby Shoes và Athletic Footwear, hôm nay đã thông báo về việc mua lại Shipley Designs với một khoản tiền ------- (143).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [143]}, {\"en\": \"The ------- (144) comes as no surprise to shoe industry insiders, who have speculated for some time about Shipley\'s financial challenges.\", \"vi\": \"Sự việc ------- (144) không có gì bất ngờ đối với những người trong ngành giày dép, những người đã phỏng đoán từ lâu về các vấn đề tài chính của Shipley.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [144]}, {\"en\": \"Five of the six Shipley stores will be part of the Locke and Jeeves deal, including the flagship store here in London.\", \"vi\": \"Năm trong số sáu cửa hàng của Shipley sẽ là một phần trong thỏa thuận với Locke and Jeeves, bao gồm cả cửa hàng chủ lực ở đây tại London.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"------- (145).\", \"vi\": \"------- (145).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [145]}, {\"en\": \"Locke and Jeeves CEO Zachary Thayne has expressed enthusiasm about the deal.\", \"vi\": \"Giám đốc điều hành Locke and Jeeves, ông Zachary Thayne, đã bày tỏ sự nhiệt tình đối với thỏa thuận này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"\\\"Shipley is an iconic design house that ------- (146) much to the Locke and Jeeves portfolio in the area of reliably traditional footwear,\\\" said Mr. Thayne.\", \"vi\": \"\\\"Shipley là một thương hiệu thiết kế mang tính biểu tượng, cái mà ------- (146) rất nhiều cho danh mục đầu tư của Locke and Jeeves trong lĩnh vực giày dép mang phong cách truyền thống đáng tin cậy,\\\" ông Thayne cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [146]}]' WHERE `id` = '8dd456cd-c197-4aef-9fa4-d207e9e6459a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Carmen Avila <c.avila@keenmaninc.com>\", \"vi\": \"Từ: Carmen Avila <c.avila@keenmaninc.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Andrew Foster <a.foster@keenmaninc.com>\", \"vi\": \"Gửi tới: Andrew Foster <a.foster@keenmaninc.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Hardeston trip\", \"vi\": \"Chủ đề: Chuyến đi đến Hardeston\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: September 9\", \"vi\": \"Ngày: 9 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"From: Andrew Foster <a.foster@keenmaninc.com>\", \"vi\": \"Từ: Andrew Foster <a.foster@keenmaninc.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"To: Carmen Avila <c.avila@keenmaninc.com>\", \"vi\": \"Gửi tới: Carmen Avila <c.avila@keenmaninc.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Subject: Re: Hardeston trip\", \"vi\": \"Chủ đề: Trả lời: Chuyến đi đến Hardeston\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Date: September 10\", \"vi\": \"Ngày: 10 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"MATTOX\", \"vi\": \"MATTOX\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Hello Andrew,\", \"vi\": \"Xin chào Andrew,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I\'ve finished researching travel options for your visit to the Hardeston factory next month, and I\'m happy to say that there are Rubin Air flights departing quite close to your desired times for both parts of the trip.\", \"vi\": \"Tôi đã hoàn tất việc tìm hiểu các phương án đi lại cho chuyến thăm nhà máy Hardeston của quý vị vào tháng tới, và tôi vui mừng thông báo rằng có các chuyến bay của Rubin Air khởi hành vào thời gian khá gần với khung giờ quý vị mong muốn cho cả hai chặng của chuyến đi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"How does this itinerary sound?\", \"vi\": \"Lịch trình này nghe có vẻ thế nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Monday, October 11\", \"vi\": \"Thứ Hai, ngày 11 tháng 10\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Depart Colburn: 9:20 A.M.\", \"vi\": \"Khởi hành từ Colburn: 9 giờ 20 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Arrive in Hardeston: 12:15 P.M.\", \"vi\": \"Đến Hardeston lúc: 12 giờ 15 phút trưa\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thursday, October 14\", \"vi\": \"Thứ Năm, ngày 14 tháng 10\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Depart Hardeston: 4:00 P.M.\", \"vi\": \"Khởi hành từ Hardeston: 4 giờ chiều\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Arrive Colburn: 6:45 P.M.\", \"vi\": \"Đến Colburn: 6 giờ 45 phút chiều\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Please note that both flights use Hardeston Regional Airport, as it\'s much closer than Hardeston-Molkis International to the company\'s preferred hotel, the Mezzine Suites in eastern Hardeston.\", \"vi\": \"Xin lưu ý rằng cả hai chuyến bay đều khởi hành từ Sân bay Khu vực Hardeston, vì sân bay này nằm gần khách sạn mà công ty lựa chọn – Mezzine Suites ở phía đông Hardeston – hơn so với Sân bay Quốc tế Hardeston-Molkis.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"If these flights are acceptable, I will finalize the bookings immediately, using the same frequent flyer account information you provided to me before your trip in July.\", \"vi\": \"Nếu các chuyến bay này phù hợp, tôi sẽ tiến hành hoàn tất việc đặt vé ngay lập tức, bằng cách sử dụng thông tin tài khoản khách hàng thường xuyên mà quý vị đã cung cấp cho tôi trước chuyến đi vào tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Also, you might want a rental car to get around in because taxi service in the area is unreliable and ride-sharing apps were recently banned.\", \"vi\": \"Ngoài ra, quý vị có thể sẽ cần thuê một chiếc xe ô tô để di chuyển vì dịch vụ taxi trong khu vực này không đáng tin cậy và các ứng dụng gọi xe chung gần đây đã bị cấm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Let me know if you\'d like me to reserve one.\", \"vi\": \"Nếu quý vị muốn tôi đặt trước một suất, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Carmen\", \"vi\": \"Carmen\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Hi Carmen,\", \"vi\": \"Xin chào Carmen,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Thank you for the information and advice, but can you hold off on making any bookings for a few days?\", \"vi\": \"Xin cảm ơn quý vị về thông tin và lời khuyên, nhưng liệu quý vị có thể hoãn việc đặt chỗ lại trong vài ngày được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I\'m considering whether to invite a colleague along on the trip.\", \"vi\": \"Tôi đang cân nhắc xem có nên mời một đồng nghiệp đi cùng trong chuyến đi này hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"He\'s the new product manager for our handheld vacuum cleaner, and it may be helpful to show him where it\'s made and introduce him to the manufacturing team.\", \"vi\": \"Ông ấy là giám đốc sản phẩm mới phụ trách dòng máy hút bụi cầm tay của chúng ta, và có lẽ sẽ rất hữu ích nếu chúng ta cho ông ấy xem nơi sản xuất sản phẩm này cũng như giới thiệu ông ấy với đội ngũ sản xuất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I\'ll update you once the matter has been settled.\", \"vi\": \"Tôi sẽ thông báo cho quý vị ngay khi vấn đề này được giải quyết xong.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"—Andrew\", \"vi\": \"—Andrew\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Reservation Number: 2023944\", \"vi\": \"Số đặt chỗ: 2023944\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"*E-Mail*\", \"vi\": \"*Email*\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"*E-Mail*\", \"vi\": \"*Email*\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Vehicle: Mireles Lyrica Sedan\", \"vi\": \"Loại xe: Mireles Lyrica Sedan\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Pickup: Monday, October 11, 12:45 P.M.\\nHardeston Regional Airport Branch\", \"vi\": \"Thời gian nhận hàng: Thứ Hai, ngày 11 tháng 10, 12 giờ 45 phút trưa\\nChi nhánh Sân bay Khu vực Hardeston\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Return: Thursday, October 14, 3:00 P.M.\\nHardeston Regional Airport Branch\", \"vi\": \"Thời gian trả hàng: Thứ Năm, ngày 14 tháng 10, lúc 3 giờ chiều\\nChi nhánh Sân bay Khu vực Hardeston\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Booking Details\", \"vi\": \"Chi tiết đặt chỗ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Name: Andrew Foster\", \"vi\": \"Họ tên: Andrew Foster\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Contact: 555-0184 (mobile)\", \"vi\": \"Liên hệ: 555-0184 (điện thoại di động)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Additional Authorized Driver: Rajesh Banik\", \"vi\": \"Tài xế được ủy quyền bổ sung: Rajesh Banik\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Driver Information\", \"vi\": \"Thông tin về người lái xe\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Corporate Account Number: 45587 (Keenman Incorporated)\", \"vi\": \"Số tài khoản doanh nghiệp: 45587 (Keenman Incorporated)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Additional Information\", \"vi\": \"Thông tin bổ sung\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 43, \"question_numbers\": []}]' WHERE `id` = '8e0655ae-5dcb-41f8-9372-41d3631ca42e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Customer name: Ana Arellano\", \"vi\": \"Tên khách hàng: Ana Arellano\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Customer phone number: 215-555-0193\", \"vi\": \"Số điện thoại của khách hàng: 215-555-0193\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Work site: 4 Market Street, Philadelphia, PA\", \"vi\": \"Địa điểm thi công: 4 Market Street, Philadelphia, PA\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Type of project: Home garden\", \"vi\": \"Loại dự án: Vườn nhà\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Project date: May 9\", \"vi\": \"Ngày thực hiện dự án: 9 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Arrival time: 9:00 A.M.\", \"vi\": \"Thời gian đến: 9 giờ sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Anticipated time of completion: 12:00 Noon\", \"vi\": \"Thời gian dự kiến hoàn thành: 12 giờ trưa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Service - Price\", \"vi\": \"Dịch vụ - Giá cả\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Monthly lawn maintenance (May) - $39.95\", \"vi\": \"Dịch vụ bảo dưỡng sân cỏ hàng tháng (tháng 5) - 39,95 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Fertilization of garden soil - $150.00\", \"vi\": \"Bón phân cho đất vườn - 150,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Delivery and planting of flowers - $395.00\", \"vi\": \"Dịch vụ giao hàng và trồng hoa - 395,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Project total: $584.95\", \"vi\": \"Tổng chi phí dự án: 584,95 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Deposit (Paid, May 1): $200.00\", \"vi\": \"Tiền đặt cọc (Đã thanh toán, ngày 1 tháng 5): 200,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Balance due upon completion: $384.95\", \"vi\": \"Số tiền còn phải thanh toán khi hoàn tất: 384,95 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"WORK AGREEMENT\", \"vi\": \"HỢP ĐỒNG LAO ĐỘNG\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"MORITZ-CONNELLY LANDSCAPERS\", \"vi\": \"CÔNG TY THI CÔNG CẢNH QUAN MORITZ-CONNELLY\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"E-mail: info@moritzconnelly.com\", \"vi\": \"Email: info@moritzconnelly.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Web site: www.moritzconnelly.com\", \"vi\": \"Trang web: www.moritzconnelly.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Phone: 215-555-0128\", \"vi\": \"Điện thoại: 215-555-0128\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '8e5c02e0-c13c-467f-b1be-2f6a7d7d860b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Rafael Vargas\", \"vi\": \"Kính gửi: Rafael Vargas\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Bon-Hwa Oh\", \"vi\": \"Từ: Bon-Hwa Oh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 1 October\", \"vi\": \"Ngày: 1 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Rafael:\", \"vi\": \"Kính gửi anh Rafael:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The opening at the new airport office here is now set for Monday, 3 November, because of a delay caused by some unexpected construction in Terminal A. I will e-mail you more details later this week, along with a request that you join us here.\", \"vi\": \"Lễ khai trương văn phòng sân bay mới tại đây hiện đã được ấn định vào thứ Hai, ngày 3 tháng 11, do sự chậm trễ phát sinh từ một số công việc xây dựng bất ngờ tại Nhà ga A. Tôi sẽ gửi email cho quý vị để cung cấp thêm chi tiết vào cuối tuần này, đồng thời kính mời quý vị tham dự sự kiện này cùng chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It would be great to have someone attend from the corporate office.\", \"vi\": \"Sẽ thật tuyệt vời nếu có đại diện từ trụ sở chính tham dự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As I have planned, we will celebrate our relocation with a month of special deals on all car rentals.\", \"vi\": \"Theo kế hoạch của tôi, chúng tôi sẽ tổ chức lễ kỷ niệm việc chuyển địa điểm bằng một tháng ưu đãi đặc biệt dành cho tất cả các dịch vụ cho thuê xe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I have also arranged for us to partner with Moonray Airways for special flight and car travel packages.\", \"vi\": \"Tôi cũng đã thu xếp để chúng ta hợp tác với Hãng hàng không Moonray nhằm cung cấp các gói du lịch đặc biệt kết hợp giữa chuyến bay và dịch vụ xe ô tô.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Although we expect many of our customers will continue to be business travelers, we hope to attract tourists, too.\", \"vi\": \"Mặc dù chúng tôi dự kiến nhiều khách hàng của chúng tôi sẽ vẫn là những người đi công tác, song chúng tôi cũng hy vọng sẽ thu hút được cả khách du lịch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I hope to see you next month.\", \"vi\": \"Tôi hy vọng sẽ được gặp quý vị vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Bon-Hwa Oh\", \"vi\": \"Chào buổi sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '8e68cd8f-c3a8-4423-8461-68cd6ef024bf';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.lelandskilledstaffing.com\", \"vi\": \"http://www.lelandskilledstaffing.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Do you need skilled residential or commercial plumbers for your next job?\", \"vi\": \"Quý vị có cần thợ ống nước lành nghề chuyên về nhà ở hoặc thương mại cho dự án tiếp theo của mình không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Many businesses are having difficulty finding the licensed plumbers they need.\", \"vi\": \"Nhiều doanh nghiệp đang gặp khó khăn trong việc tìm kiếm các thợ ống nước có giấy phép hành nghề mà họ cần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"According to a recent survey, the demand for licensed plumbers will increase by 20 percent in the next ten years.\", \"vi\": \"Theo một cuộc khảo sát gần đây, nhu cầu về thợ ống nước có giấy phép sẽ tăng 20 phần trăm trong mười năm tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Leland Skilled Staffing can help you find a certified plumber, saving you time and money in recruitment.\", \"vi\": \"Leland Skilled Staffing có thể giúp quý vị tìm được một thợ ống nước có chứng chỉ, giúp quý vị tiết kiệm thời gian và chi phí trong quá trình tuyển dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Whether your project is long-term or you need workers to handle an emergency plumbing situation, we provide on-demand skilled workers with a range of expertise.\", \"vi\": \"Dù dự án của quý vị là dự án dài hạn hay quý vị cần nhân công để xử lý tình huống khẩn cấp về hệ thống ống nước, chúng tôi đều cung cấp đội ngũ nhân công lành nghề theo yêu cầu với nhiều lĩnh vực chuyên môn khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We confirm the background and experience of the workers, so you can focus on your business.\", \"vi\": \"Chúng tôi sẽ xác minh lý lịch và kinh nghiệm của các nhân viên, để quý vị có thể tập trung vào hoạt động kinh doanh của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Contact us today so we can help meet your staffing needs.\", \"vi\": \"Hãy liên hệ với chúng tôi ngay hôm nay để chúng tôi có thể hỗ trợ quý vị đáp ứng nhu cầu về nhân sự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"LICENSED PLUMBER\\nHuang Services\\nJob Title: Residential Plumber\", \"vi\": \"THỢ ỐNG NƯỚC CÓ GIẤY PHÉP\\nHuang Services\\nChức danh: Thợ ống nước dân dụng\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Position Summary: Full-time position available at newest location in Springfield.\", \"vi\": \"Tóm tắt vị trí: Hiện có vị trí làm việc toàn thời gian tại cơ sở mới nhất ở Springfield.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Perform work in both new construction and existing homes, which includes servicing, repairing, and replacing plumbing, fixtures, and gas pipes.\", \"vi\": \"Thực hiện các công việc tại cả các công trình xây dựng mới và các ngôi nhà hiện hữu, bao gồm bảo trì, sửa chữa và thay thế hệ thống ống nước, thiết bị vệ sinh và đường ống dẫn khí.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Position Requirements: Plumbing license; 3 years\' experience; driver\'s license; ability to use modern technology.\", \"vi\": \"Yêu cầu đối với vị trí: Có giấy phép hành nghề thợ ống nước; 3 năm kinh nghiệm; có giấy phép lái xe; có khả năng sử dụng công nghệ hiện đại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Pay Scale: $50,000–$90,000, depending on experience.\", \"vi\": \"Mức lương: 50.000–90.000 đô la, tùy theo kinh nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Paid time off.\", \"vi\": \"Thời gian nghỉ phép có lương.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Work Hours: Vary according to seasonal needs.\", \"vi\": \"Giờ làm việc: Thay đổi tùy theo nhu cầu theo mùa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Some evening work required.\", \"vi\": \"Sẽ phải làm việc vào một số buổi tối.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Send résumé to s.huang@huangservices.com.\", \"vi\": \"Vui lòng gửi sơ yếu lý lịch đến địa chỉ email s.huang@huangservices.com.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We will contact those who pass a thorough background check to schedule an interview.\", \"vi\": \"Chúng tôi sẽ liên hệ với những ứng viên vượt qua quá trình kiểm tra lý lịch kỹ lưỡng để sắp xếp lịch phỏng vấn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To: info@lelandskilledstaffing.com\", \"vi\": \"Gửi tới: info@lelandskilledstaffing.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: s.huang@huangservices.com\", \"vi\": \"Nguồn: s.huang@huangservices.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date: April 15\", \"vi\": \"Ngày: 15 tháng 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subject: Staff needed\", \"vi\": \"Chủ đề: Tuyển dụng nhân viên\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"To Whom It May Concern,\", \"vi\": \"Kính gửi quý vị có liên quan,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I am writing because I am seeking a residential plumber for my business.\", \"vi\": \"Tôi viết thư này vì đang tìm kiếm một thợ sửa ống nước chuyên về nhà ở cho doanh nghiệp của tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I have had a job advertisement posted for a while now but have not had success in finding the right candidate.\", \"vi\": \"Tôi đã đăng tin tuyển dụng được một thời gian rồi nhưng vẫn chưa tìm được ứng viên phù hợp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"We require that the candidate have a plumbing license and will accept two years of experience.\", \"vi\": \"Chúng tôi yêu cầu ứng viên phải có giấy phép hành nghề thợ ống nước và sẽ chấp nhận ứng viên có hai năm kinh nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"The candidate will also need a driver\'s license and be available to occasionally work evening hours.\", \"vi\": \"Ứng viên cũng cần phải có bằng lái xe và sẵn sàng làm việc vào buổi tối trong một số trường hợp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Could you please send me a list of people who would be able to start on Monday, May 5?\", \"vi\": \"Xin quý vị vui lòng gửi cho tôi danh sách những người có thể bắt đầu làm việc vào thứ Hai, ngày 5 tháng 5 được không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"My business will begin installing the plumbing in a new housing development in the area on that day.\", \"vi\": \"Vào ngày đó, công ty của tôi sẽ bắt đầu thi công hệ thống ống nước tại một dự án khu dân cư mới trong khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Stephanie Huang\", \"vi\": \"Stephanie Huang\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = '8e6a9f11-85b0-42c5-b1ad-d33da8d60dff';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Themeification Service Center\", \"vi\": \"Trung tâm Dịch vụ Tùy biến Giao diện\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Status Report\", \"vi\": \"Báo cáo tình hình\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Issue:\", \"vi\": \"Vấn đề:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Clients using our e-commerce Web site design themes have reported a problem with the shopping cart feature.\", \"vi\": \"Các khách hàng đang sử dụng các mẫu thiết kế trang web thương mại điện tử của chúng tôi đã phản ánh về một sự cố liên quan đến tính năng giỏ hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The shopping cart icon is displaying a \\\"1\\\" to their site\'s visitors even when the visitor\'s cart is actually empty.\", \"vi\": \"Biểu tượng giỏ hàng đang hiển thị số “1” cho người truy cập trang web của họ, ngay cả khi giỏ hàng của người truy cập thực tế đang trống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This is only happening to visitors using the Champona Web browser.\", \"vi\": \"Tình trạng này chỉ xảy ra với những người truy cập sử dụng trình duyệt web Champona.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Ticket filed with Themeification Service Center:\", \"vi\": \"Yêu cầu hỗ trợ đã được gửi đến Trung tâm Dịch vụ Themeification:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"August 20, 5:48 P.M.\", \"vi\": \"Ngày 20 tháng 8, 5 giờ 48 phút chiều\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Current status:\", \"vi\": \"Tình trạng hiện tại:\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We determined that the issue is caused by Realtail, a necessary software plugin used in the affected design themes.\", \"vi\": \"Chúng tôi đã xác định rằng sự cố này do Realtail gây ra — một tiện ích phần mềm cần thiết được sử dụng trong các chủ đề thiết kế bị ảnh hưởng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We notified the maker of Realtail on August 21 at 9:12 A.M. and asked to be updated when the issue was resolved.\", \"vi\": \"Chúng tôi đã thông báo cho nhà sản xuất Realtail vào lúc 9 giờ 12 phút sáng ngày 21 tháng 8 và đề nghị được cập nhật thông tin khi sự cố được khắc phục.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Recommendation to affected Themeification clients:\", \"vi\": \"Khuyến nghị dành cho các khách hàng của Themeification bị ảnh hưởng:\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Advise dissatisfied visitors to use a different browser when accessing your Web site.\", \"vi\": \"Hãy khuyên những khách truy cập không hài lòng nên sử dụng trình duyệt khác khi truy cập trang web của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '8e790198-44b2-4b66-9f8f-fd942b95fd96';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Paper Arts\", \"vi\": \"Nghệ thuật giấy\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Serving Medila since 1998\", \"vi\": \"Phục vụ Medila từ năm 1998\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"• 285 Keener Street • 555-0193\", \"vi\": \"• Số 285 đường Keener • 555-0193\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Express Yourself Beautifully\", \"vi\": \"Hãy thể hiện bản thân một cách đầy tinh tế\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Whether you\'re writing a poem, a birthday greeting, or a grocery list, do it in style with unique paper products and writing tools from Paper Arts.\", \"vi\": \"Dù quý vị đang viết một bài thơ, một lời chúc sinh nhật hay một danh sách mua sắm, hãy thể hiện phong cách của mình với các sản phẩm giấy và dụng cụ viết độc đáo từ Paper Arts.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"On our shelves you will find:\", \"vi\": \"Trên các kệ hàng của chúng tôi, quý vị sẽ tìm thấy:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"➤ Paper in a rich variety of sizes, weights, and colors\", \"vi\": \"➤ Giấy với sự đa dạng phong phú về kích thước, độ dày và màu sắc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"➤ High-quality pens, pencils, and markers\", \"vi\": \"➤ Bút mực, bút chì và bút dạ chất lượng cao\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"➤ Greeting cards for all seasons and occasions\", \"vi\": \"➤ Thiệp chúc mừng cho mọi mùa và mọi dịp\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"➤ Elegant planners, journals, notepads, and more\", \"vi\": \"➤ Những cuốn sổ kế hoạch, nhật ký, sổ ghi chú thanh lịch và nhiều sản phẩm khác\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Drop by and see what\'s in store!\", \"vi\": \"Hãy ghé qua và khám phá những sản phẩm mới nhất tại cửa hàng của chúng tôi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '8e868020-2cb6-440c-92f4-54cf26662758';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From the Shadows to the Limelight\", \"vi\": \"Từ bóng tối bước ra ánh đèn sân khấu\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"By Calum Ellwood\", \"vi\": \"Tác giả: Calum Ellwood\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Dr. Esther Nujoma, an agricultural biotechnologist with the Namibia Institute of Applied Sciences, is the author of several books on the practical applications of biotechnology.\", \"vi\": \"Tiến sĩ Esther Nujoma, một nhà công nghệ sinh học nông nghiệp thuộc Viện Khoa học Ứng dụng Namibia, là tác giả của nhiều cuốn sách về các ứng dụng thực tiễn của công nghệ sinh học.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"According to book critic Paige Kinnock of the London Daily Register, \\\"Dr. Nujoma has increased the public\'s awareness of the role of biotechnology in daily life through her ability to translate highly complex scientific material into simple language.\\\"\", \"vi\": \"Theo nhà phê bình sách Paige Kinnock của tờ London Daily Register, “Tiến sĩ Nujoma đã nâng cao nhận thức của công chúng về vai trò của công nghệ sinh học trong cuộc sống hàng ngày nhờ khả năng chuyển tải những nội dung khoa học vô cùng phức tạp thành ngôn ngữ dễ hiểu.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Her latest work, Shining Behind Shadows, marks a departure from her usual subject matter.\", \"vi\": \"Tác phẩm mới nhất của bà, *Shining Behind Shadows*, đánh dấu một bước chuyển hướng so với chủ đề sáng tác thường thấy của bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Rather, the book highlights the lives and careers of twelve of her peers from Africa and Asia.\", \"vi\": \"Thay vào đó, cuốn sách này tập trung nêu bật cuộc đời và sự nghiệp của mười hai đồng nghiệp của bà đến từ châu Phi và châu Á.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The idea came to her three years ago at a conference in Chile.\", \"vi\": \"Ý tưởng này nảy ra trong đầu bà cách đây ba năm tại một hội nghị ở Chile.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"As Dr. Nujoma recalls, \\\"Listening to one speaker after another, I realized that many of my colleagues are from regions of the world, such as Africa and Asia, that were underrepresented.\\\"\", \"vi\": \"Như Tiến sĩ Nujoma hồi tưởng: “Khi lắng nghe các diễn giả lần lượt phát biểu, tôi nhận ra rằng nhiều đồng nghiệp của tôi đến từ các khu vực trên thế giới, chẳng hạn như châu Phi và châu Á, vốn chưa được đại diện đầy đủ.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The book is quite compelling.\", \"vi\": \"Cuốn sách này thực sự rất cuốn hút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Dr. Nujoma brings to life the stories of how her peers were drawn to the profession and the effort they pour into their work.\", \"vi\": \"Tiến sĩ Nujoma đã kể lại một cách sinh động những câu chuyện về cách các đồng nghiệp của bà bị thu hút bởi nghề nghiệp này cũng như những nỗ lực mà họ dành cho công việc của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The book does, however, fall short in one respect: it provides insights only into the lives and careers of those working in the field of agricultural biotechnology.\", \"vi\": \"Tuy nhiên, cuốn sách vẫn còn một điểm hạn chế: nó chỉ cung cấp những góc nhìn sâu sắc về cuộc sống và sự nghiệp của những người làm việc trong lĩnh vực công nghệ sinh học nông nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I would have welcomed the stories of those specializing in animal, marine, or medical biotechnology, too.\", \"vi\": \"Tôi cũng rất mong được nghe những câu chuyện từ những người chuyên về công nghệ sinh học động vật, công nghệ sinh học biển hoặc công nghệ sinh học y tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Even so, Dr. Nujoma has again succeeded in creating a work that speaks to experts and laypeople alike.\", \"vi\": \"Dù vậy, Tiến sĩ Nujoma một lần nữa đã thành công trong việc tạo ra một tác phẩm có sức thu hút đối với cả các chuyên gia lẫn độc giả không chuyên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '8eb186df-4502-4466-a775-fac5c0e90954';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Monica Blanco (10:43 A.M.)\", \"vi\": \"Monica Blanco (10 giờ 43 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Carrie.\", \"vi\": \"Xin chào, Carrie.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Are you working this Friday?\", \"vi\": \"Thứ Sáu này quý vị có đi làm không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I\'m working a half shift, and I was wondering if you could cover it.\", \"vi\": \"Tôi đang làm ca nửa ngày, và tôi không biết liệu quý vị có thể thay tôi làm ca đó được không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"My brother\'s birthday party is that day.\", \"vi\": \"Hôm đó là tiệc sinh nhật của anh trai tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Carrie Morgan (11:25 A.M.)\", \"vi\": \"Carrie Morgan (11 giờ 25 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I\'m working a half shift too.\", \"vi\": \"Tôi cũng đang làm ca nửa ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"What time are you scheduled?\", \"vi\": \"Quý vị có lịch hẹn vào lúc mấy giờ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Monica Blanco (11:37 A.M.)\", \"vi\": \"Monica Blanco (11 giờ 37 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"8 A.M. to noon.\", \"vi\": \"Từ 8 giờ sáng đến trưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Carrie Morgan (11:39 A.M.)\", \"vi\": \"Carrie Morgan (11 giờ 39 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I might be able to.\", \"vi\": \"Có lẽ tôi có thể làm được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I could do a full day, actually.\", \"vi\": \"Thực ra, tôi có thể làm việc cả ngày cũng được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I\'m scheduled after you.\", \"vi\": \"Tôi được sắp lịch sau quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Monica Blanco (11:40 A.M.)\", \"vi\": \"Monica Blanco (11 giờ 40 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Carrie Morgan (11:41 A.M.)\", \"vi\": \"Carrie Morgan (11 giờ 41 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I\'m at work right now.\", \"vi\": \"Hiện tại tôi đang ở nơi làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"When I see Mr. Cho, I\'ll ask him if it is OK to do your shift as well as mine.\", \"vi\": \"Khi gặp ông Cho, tôi sẽ hỏi ông ấy xem liệu tôi có thể đảm nhận cả ca làm việc của anh cũng như ca của tôi hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Monica Blanco (11:50 A.M.)\", \"vi\": \"Monica Blanco (11 giờ 50 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Thank you! I appreciate it.\", \"vi\": \"Cảm ơn quý vị! Tôi rất biết ơn điều đó.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '8ef093c8-181b-4cd1-9ea6-e6033180f0f0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Wu Investment Services employees\", \"vi\": \"Đến: Nhân viên Wu Investment Services\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Eileen Suen, Office Manager\", \"vi\": \"Từ: Eileen Suen, Quản lý Văn phòng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Re: Jacob Wu\", \"vi\": \"V/v: Jacob Wu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 15 August\", \"vi\": \"Ngày: 15 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"To All Staff,\", \"vi\": \"Gửi toàn thể nhân viên,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As many of you are aware, Jacob Wu, our long-standing Chief Executive Officer, ______[139] on 1 October.\", \"vi\": \"Như nhiều người trong số các bạn đã biết, Jacob Wu, Giám đốc Điều hành lâu năm của chúng ta, ______[139] vào ngày 1 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [139]}, {\"en\": \"Twenty years ago, Mr. Wu set out to create a Hong Kong-based services firm with an international scope.\", \"vi\": \"Hai mươi năm trước, ông Wu đã bắt tay vào việc thành lập một công ty dịch vụ có trụ sở tại Hồng Kông với tầm vóc quốc tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"______[140].\", \"vi\": \"______[140].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [140]}, {\"en\": \"Wu Investment Services currently serves clients in seventeen countries, 95 percent of whom have chosen to invest with us for the long term.\", \"vi\": \"Wu Investment Services hiện đang phục vụ khách hàng tại mười bảy quốc gia, trong đó 95 phần trăm khách hàng đã chọn đầu tư lâu dài cùng chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Mr. Wu will be ______[141] by Thomas Wu, his son, who has served as Vice President of Wu Investment Services for the past four years.\", \"vi\": \"Ông Wu sẽ được ______[141] bởi Thomas Wu, con trai ông, người đã giữ chức vụ Phó Chủ tịch của Wu Investment Services trong bốn năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [141]}, {\"en\": \"A gathering will be held on 28 September to celebrate Mr. Wu\'s ______[142] career.\", \"vi\": \"Một buổi họp mặt sẽ được tổ chức vào ngày 28 tháng 9 để kỷ niệm sự nghiệp ______[142] của ông Wu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [142]}, {\"en\": \"I will send further information about the event closer to the date.\", \"vi\": \"Tôi sẽ gửi thêm thông tin chi tiết về sự kiện này khi gần đến ngày diễn ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Cảm ơn bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Eileen\", \"vi\": \"Eileen\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '8f6a57b6-0e4c-47c1-a8fb-569ce5ee41ee';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Sean Bellinger <sbellinger@zmail.ca>\", \"vi\": \"Từ: Sean Bellinger <sbellinger@zmail.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Leo Wright <wright_l@kamet.ca>, Rosa Perez <perez_r@kamet.ca>\", \"vi\": \"Gửi: Leo Wright <wright_l@kamet.ca>, Rosa Perez <perez_r@kamet.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 14, 4:25 p.m.\", \"vi\": \"Ngày: 14 tháng 5, 4 giờ 25 phút chiều.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: A few points\", \"vi\": \"Chủ đề: Một số điểm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Kamet press release\", \"vi\": \"Tài liệu đính kèm: 📎 Thông cáo báo chí của Kamet\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Wright and Ms. Perez,\", \"vi\": \"Kính gửi ông Wright và bà Perez,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I plan to add the information from your press release (attached) to the About Us page of your new Web site, so I wanted to make sure that everything is correct, including the contact information.\", \"vi\": \"Tôi dự định sẽ bổ sung thông tin từ thông cáo báo chí của quý vị (đính kèm) vào trang “Giới thiệu về chúng tôi” trên trang web mới của quý vị, vì vậy tôi muốn đảm bảo rằng mọi thông tin đều chính xác, bao gồm cả thông tin liên hệ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Since you will launch an extensive advertising campaign for your business, it would be sensible to check the text before the site has a high volume of traffic.\", \"vi\": \"Vì quý vị sắp triển khai một chiến dịch quảng cáo quy mô lớn cho doanh nghiệp của mình, nên việc kiểm tra nội dung trước khi trang web có lượng truy cập lớn là điều hợp lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As we discussed over the phone, the homepage is still loading slowly.\", \"vi\": \"Như chúng ta đã trao đổi qua điện thoại, trang chủ vẫn đang tải chậm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I believe this is due to the animated clips on that page, which I think should be replaced with static images.\", \"vi\": \"Tôi cho rằng nguyên nhân là do các đoạn video động trên trang đó; theo tôi, chúng nên được thay thế bằng các hình ảnh tĩnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"You also requested that I show someone from your company how to use the credit card processing system.\", \"vi\": \"Quý vị cũng đã yêu cầu tôi hướng dẫn một nhân viên của công ty quý vị cách sử dụng hệ thống xử lý thẻ tín dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I can do that by video conference any afternoon this week at your convenience.\", \"vi\": \"Tôi có thể thực hiện việc đó qua hội nghị truyền hình vào bất kỳ buổi chiều nào trong tuần này, tùy theo thời gian thuận tiện của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sean Bellinger\", \"vi\": \"Sean Bellinger\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Press Release\", \"vi\": \"Thông cáo báo chí\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Contact: Nancy Rollins, 555-9275\", \"vi\": \"Liên hệ: Nancy Rollins, số 555-9275\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Kamet, located on Cambridge Street opposite the Middleville Mall, is pleased to announce its grand opening on June 1.\", \"vi\": \"Kamet, tọa lạc trên đường Cambridge, đối diện Trung tâm thương mại Middleville, hân hạnh thông báo lễ khai trương vào ngày 1 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Kamet was founded by Lawrence Holt, who used to work in accounting but spent all of his free time outdoors, especially going on nature tours and climbing the world\'s tallest peaks.\", \"vi\": \"Kamet được thành lập bởi ông Lawrence Holt, người từng làm việc trong lĩnh vực kế toán nhưng lại dành toàn bộ thời gian rảnh rỗi của mình cho các hoạt động ngoài trời, đặc biệt là tham gia các chuyến tham quan thiên nhiên và chinh phục những đỉnh núi cao nhất thế giới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"He wanted to provide people like him with the best tents, backpacks, sleeping bags, and more, all at affordable prices.\", \"vi\": \"Ông mong muốn mang đến cho những người giống như mình những chiếc lều, ba lô, túi ngủ và nhiều sản phẩm khác chất lượng tốt nhất, tất cả đều với mức giá phải chăng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Kamet brings you modern styles from designer Kenny Becerra, a law school graduate and former practicing attorney who had a career change later in life.\", \"vi\": \"Kamet mang đến cho quý vị những phong cách thời trang hiện đại từ nhà thiết kế Kenny Becerra – một cựu sinh viên tốt nghiệp trường luật và từng là luật sư hành nghề, người đã quyết định chuyển hướng sự nghiệp ở giai đoạn sau của cuộc đời.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"The opening day will feature complimentary refreshments, prize drawings, and product demonstrations.\", \"vi\": \"Trong ngày khai mạc sẽ có các món ăn nhẹ miễn phí, chương trình bốc thăm trúng thưởng và các buổi trình diễn sản phẩm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Summer is here, so stop in and stock up to make your time in the great outdoors comfortable and safe!\", \"vi\": \"Mùa hè đã đến, vậy nên hãy ghé qua và sắm sẵn đồ dùng để những khoảnh khắc của quý vị giữa thiên nhiên rộng lớn trở nên thoải mái và an toàn!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"From: Leo Wright <wright_l@kamet.ca>\", \"vi\": \"Từ: Leo Wright <wright_l@kamet.ca>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"To: Sean Bellinger <sbellinger@zmail.ca>\", \"vi\": \"Gửi tới: Sean Bellinger <sbellinger@zmail.ca>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Cc: Rosa Perez <perez_r@kamet.ca>\", \"vi\": \"Cc: Rosa Perez <perez_r@kamet.ca>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date: May 15, 9:21 a.m.\", \"vi\": \"Ngày: 15 tháng 5, 9 giờ 21 phút sáng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Subject: RE: A few points\", \"vi\": \"Chủ đề: RE: Một vài điểm\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Hi Mr. Bellinger,\", \"vi\": \"Kính gửi ông Bellinger,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I\'m glad you double-checked the text, as it looks like you are actually working from an earlier version of the press release.\", \"vi\": \"Tôi rất vui vì quý vị đã kiểm tra lại nội dung một lần nữa, vì có vẻ như quý vị đang dựa trên một phiên bản cũ hơn của thông cáo báo chí.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"There was an error in that document because the career backgrounds of Lawrence Holt and Kenny Becerra were accidentally swapped.\", \"vi\": \"Tài liệu đó có một sai sót do thông tin về quá trình làm việc của ông Lawrence Holt và ông Kenny Becerra đã vô tình bị hoán đổi cho nhau.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Ms. Perez will write new content for the About Us page based on the updated copy of the press release and send it to you later today.\", \"vi\": \"Bà Perez sẽ soạn thảo nội dung mới cho trang “Giới thiệu về chúng tôi” dựa trên bản cập nhật của thông cáo báo chí và sẽ gửi cho quý vị vào cuối ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Additionally, Joanne Ramsey can attend the video conference you suggested at 2 P.M. on June 9.\", \"vi\": \"Ngoài ra, bà Joanne Ramsey có thể tham dự cuộc họp trực tuyến mà quý vị đã đề xuất vào lúc 2 giờ chiều ngày 9 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"She has worked with similar systems before, so I don\'t think it will take long for her to familiarize herself with all of the features.\", \"vi\": \"Cô ấy đã từng làm việc với các hệ thống tương tự trước đây, nên tôi nghĩ cô ấy sẽ không mất nhiều thời gian để làm quen với tất cả các tính năng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"And we appreciate that you will continue to be available to address any queries we may have after the site is live.\", \"vi\": \"Chúng tôi rất cảm kích vì quý vị sẽ tiếp tục sẵn sàng giải đáp mọi thắc mắc của chúng tôi sau khi trang web chính thức đi vào hoạt động.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Warmest regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Leo Wright\", \"vi\": \"Leo Wright\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}]' WHERE `id` = '8f72d6ac-2fad-42d4-ba72-00972121e6ad';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Chatter Customer Service\", \"vi\": \"Từ: Dịch vụ Khách hàng Chatter\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Melissa Ramsey\", \"vi\": \"Đến: Melissa Ramsey\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Password reset\", \"vi\": \"Chủ đề: Đặt lại mật khẩu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: December 19\", \"vi\": \"Ngày: 19 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Ramsey,\", \"vi\": \"Kính gửi chị Ramsey,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We have become aware of a security issue with the log-in credentials for your Chatter account.\", \"vi\": \"Chúng tôi nhận thấy có vấn đề bảo mật liên quan đến thông tin đăng nhập tài khoản Chatter của chị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[131] identical to an e-mail address and password recently exposed by a data breach of another online service.\", \"vi\": \"______[131] giống hệt với địa chỉ email và mật khẩu gần đây đã bị lộ do vụ rò rỉ dữ liệu của một dịch vụ trực tuyến khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [131]}, {\"en\": \"We have no reason at present to believe that your Chatter account has ______[132] been accessed by anyone else.\", \"vi\": \"Hiện tại chúng tôi không có lý do gì để tin rằng tài khoản Chatter của chị đã ______[132] bị bất kỳ ai khác truy cập.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [132]}, {\"en\": \"However, reusing log-in credentials like this makes a future account breach more likely.\", \"vi\": \"Tuy nhiên, việc sử dụng lại thông tin đăng nhập như thế này làm tăng khả năng tài khoản bị xâm phạm trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In a proactive effort to protect the security of your Chatter account, we have blocked access to it by resetting your password.\", \"vi\": \"Trong nỗ lực chủ động nhằm bảo vệ tính bảo mật cho tài khoản Chatter của chị, chúng tôi đã chặn quyền truy cập vào tài khoản bằng cách đặt lại mật khẩu của chị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We apologize for the ______[133].\", \"vi\": \"Chúng tôi thành thật xin lỗi vì sự ______[133].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [133]}, {\"en\": \"Please click on the link below to set a new password.\", \"vi\": \"Vui lòng nhấp vào liên kết bên dưới để thiết lập mật khẩu mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"______[134].\", \"vi\": \"______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [134]}, {\"en\": \"We also recommend enabling two-factor authentication for all of your online accounts.\", \"vi\": \"Chúng tôi cũng khuyên chị nên bật tính năng xác thực hai yếu tố cho tất cả các tài khoản trực tuyến của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"—The Chatter Team\", \"vi\": \"—Đội ngũ Chatter\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '8f9fb7e8-04be-4b8d-a27e-83f92b945f29';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Rescue your device with Phone Tune-Up\", \"vi\": \"Cứu lấy thiết bị của bạn với Phone Tune-Up\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Is your smartphone screen scratched or cracked?\", \"vi\": \"Màn hình điện thoại thông minh của bạn bị trầy xước hoặc nứt vỡ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"___135___?\", \"vi\": \"___135___?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"Do your apps freeze or crash?\", \"vi\": \"Các ứng dụng của bạn có bị đơ hoặc lỗi không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The experts at Phone Tune-Up can help!\", \"vi\": \"Các chuyên gia tại Phone Tune-Up có thể giúp bạn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We use nothing but the best quality parts to ___136___ your mobile phone.\", \"vi\": \"Chúng tôi chỉ sử dụng các linh kiện chất lượng tốt nhất để ___136___ điện thoại di động của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [136]}, {\"en\": \"Let our certified technicians save you the time and expense involved in replacing your phone with a new one.\", \"vi\": \"Hãy để các kỹ thuật viên được chứng nhận của chúng tôi giúp bạn tiết kiệm thời gian và chi phí liên quan đến việc thay thế điện thoại của bạn bằng một chiếc mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"When we are ___137___, you will think your old phone is brand new.\", \"vi\": \"Khi chúng tôi ___137___, bạn sẽ nghĩ chiếc điện thoại cũ của mình hoàn toàn mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [137]}, {\"en\": \"To make an appointment, call 604-555-0198 or visit www.phonetuneup.com.\", \"vi\": \"Để đặt lịch hẹn, hãy gọi số 604-555-0198 hoặc truy cập www.phonetuneup.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Same-day service is often available ___138___ needed parts are in stock.\", \"vi\": \"Dịch vụ lấy ngay trong ngày thường có sẵn ___138___ các linh kiện cần thiết có sẵn trong kho.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [138]}]' WHERE `id` = '8fb5c465-ad66-4adb-b295-049862b9b5b3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Kelli Wethers [2:15 P.M.]\", \"vi\": \"Kelli Wethers [14 giờ 15]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Mr. Easton.\", \"vi\": \"Xin chào, ông Easton.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I want to remind you about the dinner meeting with your client, Mr. Kasai, at the Magnolia Grill this evening.\", \"vi\": \"Tôi xin nhắc lại với quý vị về buổi tiệc tối với khách hàng của quý vị, ông Kasai, tại nhà hàng Magnolia Grill vào tối nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Mr. Kasai will be coming directly from the airport.\", \"vi\": \"Ông Kasai sẽ đến thẳng từ sân bay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Anna Kwon from our marketing department will be joining both of you.\", \"vi\": \"Chị Anna Kwon, thuộc phòng Marketing của chúng tôi, sẽ tham gia cùng hai vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Adam Easton [2:31 P.M.]\", \"vi\": \"Adam Easton [14 giờ 31 phút]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thanks, Ms. Wethers.\", \"vi\": \"Xin cảm ơn bà Wethers.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It occurs to me, if he is coming straight from the airport, what will he do with his luggage?\", \"vi\": \"Tôi chợt nghĩ, nếu anh ấy đi thẳng từ sân bay về, thì anh ấy sẽ xử lý hành lý của mình thế nào đây?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Kelli Wethers [2:33 P.M.]\", \"vi\": \"Kelli Wethers [2 giờ 33 phút chiều]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Don’t worry.\", \"vi\": \"Xin đừng lo lắng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Kyle Friedman is picking Mr. Kasai up at the airport and dropping the bags off at the hotel.\", \"vi\": \"Ông Kyle Friedman sẽ đón ông Kasai tại sân bay và mang hành lý đến khách sạn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I’m adding Kyle to this message now in case you two need to communicate.\", \"vi\": \"Tôi xin thêm Kyle vào cuộc trò chuyện này ngay bây giờ, phòng trường hợp hai vị cần trao đổi với nhau.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Adam Easton [2:34 P.M.]\", \"vi\": \"Adam Easton [14 giờ 34 phút]\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sounds great.\", \"vi\": \"Nghe có vẻ tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I can drive Mr. Kasai back to his hotel following our meeting.\", \"vi\": \"Sau cuộc họp, tôi có thể chở ông Kasai về khách sạn của ông ấy.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"It would be a nice gesture for such a key client.\", \"vi\": \"Đó sẽ là một cử chỉ lịch thiệp dành cho một khách hàng quan trọng như vậy.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Kyle Friedman [2:36 P.M.]\", \"vi\": \"Kyle Friedman [2 giờ 36 phút chiều]\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Heading to the airport soon, Ms. Wethers.\", \"vi\": \"Sắp đến sân bay rồi, thưa bà Wethers.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Just text me later if I need to know anything more.\", \"vi\": \"Nếu cần biết thêm thông tin gì, xin vui lòng nhắn tin cho tôi sau nhé.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Kelli Wethers [2:40 P.M.]\", \"vi\": \"Kelli Wethers [14 giờ 40 phút]\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Good idea, Mr. Easton.\", \"vi\": \"Ý kiến hay, thưa ông Easton.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"A taxi for after the dinner will not be necessary then.\", \"vi\": \"Vậy thì sẽ không cần gọi taxi sau bữa tối nữa.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '8fe1aefa-acd4-4b0d-8969-e78e0cb951d5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"The Finnerton Theater\", \"vi\": \"Nhà hát Finnerton\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.finnertontheater.com/aboutus\", \"vi\": \"http://www.finnertontheater.com/aboutus\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The Finnerton Theater is Grenville’s premier cinema for independent movies, documentaries, and film classics.\", \"vi\": \"Rạp chiếu phim Finnerton là rạp chiếu phim hàng đầu tại Grenville chuyên trình chiếu các bộ phim độc lập, phim tài liệu và các tác phẩm điện ảnh kinh điển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Locally owned and operated for over 50 years, the theater retains its strong connection to the city.\", \"vi\": \"Được sở hữu và điều hành bởi người dân địa phương trong hơn 50 năm qua, rạp chiếu phim này vẫn duy trì mối liên hệ bền chặt với thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Once a top entertainment destination, it later persisted through years of economic stagnation and urban decline.\", \"vi\": \"Từng là một điểm đến giải trí hàng đầu, nơi đây sau đó vẫn tồn tại qua nhiều năm suy thoái kinh tế và sự suy tàn của đô thị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"An anchor for neighborhood revitalization and growth, the Finnerton Theater now serves as the backbone of the city’s thriving Riverside Arts District.\", \"vi\": \"Là điểm tựa cho sự phục hồi và phát triển của khu vực lân cận, Nhà hát Finnerton hiện đang đóng vai trò là trụ cột của Khu nghệ thuật Riverside đang phát triển mạnh mẽ của thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In the last half century, the Finnerton Theater has become a destination for film lovers from throughout the region.\", \"vi\": \"Trong nửa thế kỷ qua, Rạp chiếu phim Finnerton đã trở thành điểm đến thu hút những người yêu điện ảnh từ khắp khu vực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Attendees from cities as far away as Nesterport and Belmere come regularly to enjoy the theater’s unique ambiance.\", \"vi\": \"Khán giả từ những thành phố xa xôi như Nesterport và Belmere thường xuyên ghé thăm để thưởng thức bầu không khí độc đáo tại nhà hát này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Over the theater’s history, more than 1,000 movies have been screened and dozens of others have premiered.\", \"vi\": \"Trong suốt lịch sử hoạt động của rạp chiếu phim này, đã có hơn 1.000 bộ phim được công chiếu và hàng chục bộ phim khác đã ra mắt tại đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The Finnerton Theater has hosted events with critically acclaimed directors and served as the stage for renowned public speakers.\", \"vi\": \"Nhà hát Finnerton đã tổ chức các sự kiện với sự tham gia của những đạo diễn được giới phê bình đánh giá cao và là nơi diễn ra các buổi diễn thuyết của những diễn giả nổi tiếng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"In the past decade, it has served as the host for the Greater Cincinnati Film Festival, the Midwest Documentary Fest, and the annual Clearacre Conference, which is sponsored by the city’s largest employer, Clearacre Tech.\", \"vi\": \"Trong thập kỷ qua, nơi đây đã là địa điểm tổ chức Liên hoan Phim Greater Cincinnati, Liên hoan Phim Tài liệu Trung Tây và Hội nghị Clearacre thường niên – sự kiện được tài trợ bởi Clearacre Tech, đơn vị sử dụng lao động lớn nhất của thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Five years ago, the theater was added to the state’s register of historic places.\", \"vi\": \"Cách đây năm năm, nhà hát này đã được đưa vào danh sách các di tích lịch sử của bang.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To this day, filmgoers continue to frequent the Finnerton Theater whenever film releases are screened.\", \"vi\": \"Cho đến ngày nay, các khán giả vẫn thường xuyên lui tới Rạp chiếu phim Finnerton mỗi khi có phim mới được công chiếu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"And despite the ever-increasing popularity of online film-streaming services, ticket sales at the Finnerton Theater have risen continuously since its listing in the state’s register.\", \"vi\": \"Và mặc dù các dịch vụ phát trực tuyến phim ngày càng trở nên phổ biến, doanh thu bán vé tại Rạp chiếu phim Finnerton vẫn không ngừng tăng lên kể từ khi rạp này được đưa vào danh sách đăng ký của tiểu bang.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"It is a true cultural gem and a source of civic pride for local residents.\", \"vi\": \"Đây thực sự là một báu vật văn hóa và là niềm tự hào của người dân địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '8fe6f348-2ead-47e7-875b-16abbb796b90';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Olinawe is a Fusion of Flavours\", \"vi\": \"Olinawe là sự hòa quyện của các hương vị\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"DONCASTER (21 March)—After many years of hard work, chef Amina Ikegami is opening her own restaurant in downtown Doncaster.\", \"vi\": \"DONCASTER (ngày 21 tháng 3) — Sau nhiều năm miệt mài làm việc, đầu bếp Amina Ikegami sẽ khai trương nhà hàng của riêng mình tại trung tâm thành phố Doncaster.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Ms. Ikegami trained at Chesterfield Culinary Academy and worked as a junior sous chef at the Sisra Bistro for three years.\", \"vi\": \"Bà Ikegami đã theo học tại Học viện Ẩm thực Chesterfield và làm việc với tư cách là phó bếp trưởng phụ trách các công việc phụ tại nhà hàng Sisra Bistro trong ba năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"She spent the last twelve years on staff at Delmourel\'s, where she held the title of executive chef for the past four years.\", \"vi\": \"Trong mười hai năm qua, bà đã làm việc tại Delmourel\'s, nơi bà đảm nhiệm chức vụ bếp trưởng điều hành trong bốn năm gần đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Ms. Ikegami has won several awards, including the UK Innovative Chef Award.\", \"vi\": \"Bà Ikegami đã giành được nhiều giải thưởng, trong đó có Giải thưởng Đầu bếp Sáng tạo của Vương quốc Anh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Although she is sad to leave Delmourel\'s, she is thrilled to fulfill her longtime dream of owning her own restaurant.\", \"vi\": \"Dù cảm thấy buồn khi phải rời khỏi Delmourel’s, cô vẫn vô cùng phấn khởi khi có thể thực hiện ước mơ bấy lâu nay là sở hữu một nhà hàng của riêng mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Ms. Ikegami\'s new restaurant, Olinawe, features a menu influenced by the many varied flavours of her childhood.\", \"vi\": \"Nhà hàng mới của bà Ikegami, Olinawe, mang đến thực đơn được lấy cảm hứng từ những hương vị đa dạng của thời thơ ấu bà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"She was raised in England in a family with French, Senegalese, and Japanese heritage.\", \"vi\": \"Cô lớn lên tại Anh trong một gia đình có nguồn gốc từ Pháp, Senegal và Nhật Bản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Being exposed to so many different food traditions is what inspired her to become a chef.\", \"vi\": \"Chính việc được tiếp xúc với rất nhiều truyền thống ẩm thực đa dạng đã truyền cảm hứng cho cô theo đuổi con đường trở thành một đầu bếp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"\\\"My mother and father are great cooks themselves,\\\" says Ms. Ikegami.\", \"vi\": \"\\\"Bố mẹ tôi vốn là những người nấu ăn rất giỏi,\\\" bà Ikegami chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"\\\"I loved having all these cuisines in one house, and I always strive to bring that fusion of cultures into my cooking.\\\"\", \"vi\": \"\\\"Tôi rất thích việc có thể thưởng thức tất cả các món ăn đa dạng này trong cùng một ngôi nhà, và tôi luôn nỗ lực mang sự hòa quyện giữa các nền văn hóa đó vào các món ăn của mình.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Olinawe opens officially on 25 April and will serve lunch and dinner Tuesdays through Sundays.\", \"vi\": \"Olinawe sẽ chính thức khai trương vào ngày 25 tháng 4 và sẽ phục vụ bữa trưa và bữa tối từ thứ Ba đến Chủ Nhật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"❧\", \"vi\": \"❧\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Join Us!\", \"vi\": \"Hãy tham gia cùng chúng tôi!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Enjoy delicious fusion cuisine at\", \"vi\": \"Hãy thưởng thức những món ăn kết hợp độc đáo và ngon miệng tại\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Olinawe\", \"vi\": \"Olinawe\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"a new restaurant from\", \"vi\": \"một nhà hàng mới của\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Chef Amina Ikegami\", \"vi\": \"Đầu bếp Amina Ikegami\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Saturday, 2 April\", \"vi\": \"Thứ Bảy, ngày 2 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"7:00 P.M.–11:00 P.M.\", \"vi\": \"19 giờ – 23 giờ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"All food and drinks are included.\", \"vi\": \"Tất cả các món ăn và đồ uống đều đã được bao gồm trong giá.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"This is an invitation-only event.\", \"vi\": \"Đây là sự kiện chỉ dành cho những người được mời.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Please bring this invitation with you.\", \"vi\": \"Xin vui lòng mang theo thư mời này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"To: Amina Ikegami <amina.ikegami@scomail.co.uk>\", \"vi\": \"Gửi tới: Amina Ikegami <amina.ikegami@scomail.co.uk>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"From: Julien Aupry <jaupry@enukmail.co.uk>\", \"vi\": \"Từ: Julien Aupry <jaupry@enukmail.co.uk>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Subject: Olinawe\", \"vi\": \"Chủ đề: Olinawe\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date: 26 March\", \"vi\": \"Ngày: 26 tháng 3\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Dear Amina,\", \"vi\": \"Kính gửi Amina,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I just heard about Olinawe, and I received your invitation to the celebratory event.\", \"vi\": \"Tôi vừa mới nghe nói về Olinawe, và tôi đã nhận được thư mời của quý vị tham dự sự kiện kỷ niệm này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"This is such wonderful news!\", \"vi\": \"Đây quả là một tin tuyệt vời!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"At school, I remember that you often talked about opening your own restaurant, and I am thrilled that it is finally happening!\", \"vi\": \"Hồi còn đi học, tôi nhớ là anh thường nói về việc mở một nhà hàng của riêng mình, và tôi thực sự rất vui mừng khi điều đó cuối cùng cũng trở thành hiện thực!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Unfortunately, I will not be able to attend this event.\", \"vi\": \"Rất tiếc, tôi sẽ không thể tham dự sự kiện này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I will be in France that weekend teaching a class on making pastries.\", \"vi\": \"Cuối tuần đó, tôi sẽ có mặt tại Pháp để giảng dạy một khóa học về cách làm bánh ngọt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"But once I am back, I will definitely be coming by for dinner.\", \"vi\": \"Tuy nhiên, một khi tôi trở lại, tôi chắc chắn sẽ ghé qua dùng bữa tối.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"All the best,\", \"vi\": \"Chúc quý vị mọi điều tốt đẹp nhất,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Julien\", \"vi\": \"Julien\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}]' WHERE `id` = '8ffb921d-1cba-4a36-ab2e-8e2298789cd9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Sen Chai (6:51 P.M.):\", \"vi\": \"Sen Chai (6 giờ 51 phút chiều):\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"We\'re on a dinner break from the negotiation meeting.\", \"vi\": \"Chúng tôi đang tạm nghỉ để dùng bữa tối trong khuôn khổ cuộc họp đàm phán.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Mr. Geraci did not accept our offer.\", \"vi\": \"Ông Geraci đã không chấp nhận đề nghị của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Mateo Michelacci (6:52 P.M.):\", \"vi\": \"Mateo Michelacci (6 giờ 52 phút chiều):\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"That\'s frustrating.\", \"vi\": \"Điều đó thật khiến người ta bực mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Do you think if we offered another €10,000 he would sell?\", \"vi\": \"Quý vị có nghĩ rằng nếu chúng ta đề nghị thêm 10.000 euro thì ông ấy sẽ đồng ý bán không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"You and I have agreed that this is the right facility: it\'s in a convenient location for customers, the access from the highway is perfect for incoming and outgoing deliveries, and potential tenants have already expressed interest.\", \"vi\": \"Chúng ta đã thống nhất rằng đây là cơ sở phù hợp: vị trí thuận tiện cho khách hàng, lối vào từ đường cao tốc rất thuận lợi cho việc giao nhận hàng hóa, và các khách thuê tiềm năng đã bày tỏ sự quan tâm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Sen Chai (6:53 P.M.):\", \"vi\": \"Sen Chai (6 giờ 53 phút chiều):\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I can\'t see that happening.\", \"vi\": \"Tôi không nghĩ điều đó sẽ xảy ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"But I\'ll try again.\", \"vi\": \"Tuy nhiên, tôi sẽ thử lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"How high can I go?\", \"vi\": \"Tôi có thể leo lên cao đến mức nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Mateo Michelacci (6:54 P.M.):\", \"vi\": \"Mateo Michelacci (6 giờ 54 phút chiều):\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The bank approved us for another €20,000.\", \"vi\": \"Ngân hàng đã chấp thuận cho chúng tôi khoản vay thêm 20.000 euro.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Offer Mr. Geraci €10,000 more, plus we will fix any building code violations at our expense.\", \"vi\": \"Hãy đề nghị ông Geraci thêm 10.000 euro, đồng thời chúng tôi sẽ khắc phục mọi vi phạm quy định xây dựng bằng kinh phí của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Go up to the full €20,000 only if necessary.\", \"vi\": \"Chỉ nên tăng lên mức tối đa 20.000 € khi thực sự cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sen Chai (6:55 P.M.):\", \"vi\": \"Sen Chai (6 giờ 55 phút chiều):\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I\'ll do my best.\", \"vi\": \"Tôi sẽ cố gắng hết sức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '901cc2ef-29fe-4770-bd0e-66b8a7fb8c42';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear Resident,\", \"vi\": \"Kính gửi quý cư dân,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Water service to the Tisdale Apartments building will be shut off on Tuesday, May 18.\", \"vi\": \"Dịch vụ cấp nước cho tòa nhà Tisdale Apartments sẽ bị ngừng cung cấp vào thứ Ba, ngày 18 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"All units will be without access to hot or cold water from 9:00 A.M. until as late as 6:00 P.M. on that day.\", \"vi\": \"Tất cả các căn hộ sẽ không có nước nóng hoặc nước lạnh từ 9 giờ sáng cho đến 6 giờ chiều cùng ngày.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The shut-off is necessary so that plumbers can inspect the building\'s main water supply and pressure regulators to identify the cause of the water pressure issues that residents have reported.\", \"vi\": \"Việc ngắt nước là cần thiết để các thợ ống nước có thể kiểm tra hệ thống cấp nước chính và các bộ điều chỉnh áp suất của tòa nhà, nhằm xác định nguyên nhân gây ra các sự cố về áp lực nước mà cư dân đã phản ánh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Future shut-offs may be necessary in order to facilitate repairs.\", \"vi\": \"Trong tương lai, có thể sẽ phải tiến hành ngắt nguồn để tạo điều kiện thuận lợi cho việc sửa chữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please keep the following in mind before and on the day in question.\", \"vi\": \"Kính mong quý vị lưu ý những điều sau đây trước và trong ngày diễn ra sự kiện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The sinks, showers, baths, and toilets in all apartments will be out of operation.\", \"vi\": \"Các bồn rửa, vòi sen, bồn tắm và nhà vệ sinh trong tất cả các căn hộ sẽ tạm thời ngừng hoạt động.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"If you anticipate needing water for drinking or cooking, fill up containers beforehand.\", \"vi\": \"Nếu quý vị dự kiến sẽ cần nước để uống hoặc nấu ăn, xin vui lòng đổ đầy nước vào các thùng chứa từ trước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Your heater or air conditioner may be connected to the water lines.\", \"vi\": \"Thiết bị sưởi hoặc điều hòa không khí của quý vị có thể được kết nối với hệ thống ống nước.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Avoid turning them on in order to prevent any issues.\", \"vi\": \"Xin vui lòng không bật các thiết bị này để tránh xảy ra bất kỳ sự cố nào.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Please contact me at e.reynolds@tisdaleapt.com if you have any questions.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào, xin vui lòng liên hệ với tôi qua địa chỉ email e.reynolds@tisdaleapt.com.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Xin cảm ơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '901edc74-9f88-4897-880d-cc31ac6611bb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Peter Harrer [9:30 A.M.] Hi, everyone.\", \"vi\": \"Peter Harrer [9 giờ 30 phút sáng] Xin chào quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I\'ll make this brief as I know you\'re all busy reading the manuscripts for the editorial meeting on Friday.\", \"vi\": \"Tôi sẽ nói ngắn gọn thôi vì tôi biết quý vị đều đang bận rộn đọc các bản thảo để chuẩn bị cho cuộc họp ban biên tập vào thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Cora Grant [9:31 A.M.] Did we change the time for that?\", \"vi\": \"Cora Grant [9 giờ 31 phút sáng] Chúng ta đã thay đổi thời gian cho việc đó chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Peter Harrer [9:32 A.M.] It\'s still at 2:00, right?\", \"vi\": \"Peter Harrer [9 giờ 32 phút sáng] Vẫn là lúc 2 giờ, phải không ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Meili Shu [9:32 A.M.] Yes.\", \"vi\": \"Meili Shu [9 giờ 32 phút sáng] Vâng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"At first we talked about having it in the morning, but I have an appointment at 10:00.\", \"vi\": \"Ban đầu chúng tôi đã bàn về việc tổ chức vào buổi sáng, nhưng tôi có một cuộc hẹn lúc 10 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Peter Harrer [9:33 A.M.] OK, I\'m glad we got that sorted out.\", \"vi\": \"Peter Harrer [9 giờ 33 phút sáng] Được rồi, tôi rất vui vì chúng ta đã giải quyết xong vấn đề đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I\'d like to share Kwang\'s idea.\", \"vi\": \"Tôi xin chia sẻ ý tưởng của Kwang.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Kwang, do you want to explain it?\", \"vi\": \"Kwang ạ, anh có muốn giải thích điều đó không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Kwang Chun [9:35 A.M.] Sure.\", \"vi\": \"Kwang Chun [9 giờ 35 phút sáng] Được ạ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"What if we encourage our customers to sign up to receive a newsletter each month by e-mail?\", \"vi\": \"Nếu chúng ta khuyến khích khách hàng đăng ký nhận bản tin hàng tháng qua email thì sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We would include information about our special promotions or book giveaway contests.\", \"vi\": \"Chúng tôi sẽ đăng tải thông tin về các chương trình khuyến mãi đặc biệt hoặc các cuộc thi tặng sách của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We could even have some of our authors write occasional articles.\", \"vi\": \"Chúng tôi thậm chí có thể mời một số tác giả của mình viết bài thỉnh thoảng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Cora Grant [9:36 A.M.] Yes, they could give insights into their work or maybe discuss a favorite book.\", \"vi\": \"Cora Grant [9 giờ 36 phút sáng] Vâng, họ có thể chia sẻ những góc nhìn sâu sắc về công việc của mình hoặc có thể thảo luận về một cuốn sách yêu thích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Meili Shu [9:37 A.M.] It\'s a great idea!\", \"vi\": \"Meili Shu [9 giờ 37 phút sáng] Đó là một ý tưởng tuyệt vời!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"This kind of thing is getting more popular in business these days.\", \"vi\": \"Ngày nay, những điều như thế này đang ngày càng trở nên phổ biến trong giới kinh doanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"And people always like a chance to win free books.\", \"vi\": \"Và mọi người luôn thích có cơ hội nhận được những cuốn sách miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Peter Harrer [9:38 A.M.] Well, keep in mind we are a small press with a small budget.\", \"vi\": \"Peter Harrer [9 giờ 38 phút sáng] Vâng, xin quý vị lưu ý rằng chúng tôi là một nhà xuất bản nhỏ với ngân sách hạn hẹp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Would one of you like to get this idea off the ground?\", \"vi\": \"Có ai trong quý vị muốn biến ý tưởng này thành hiện thực không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Kwang Chun [9:39 A.M.] I suppose I should, since I\'m proposing it.\", \"vi\": \"Kwang Chun [9 giờ 39 phút sáng] Tôi nghĩ mình nên làm vậy, vì chính tôi là người đề xuất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Maybe Meili would help?\", \"vi\": \"Có lẽ Meili sẽ giúp được chăng?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Meili Shu [9:40 A.M.] Of course.\", \"vi\": \"Meili Shu [9 giờ 40 phút sáng] Tất nhiên rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Peter Harrer [9:41 A.M.] OK, thanks everyone.\", \"vi\": \"Peter Harrer [9 giờ 41 phút sáng] Được rồi, xin cảm ơn quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"See you all on Friday.\", \"vi\": \"Hẹn gặp lại quý vị vào thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}]' WHERE `id` = '903a3686-9d25-4700-b4a8-3f5693901e7f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: claimscenter@cheapsure.com\", \"vi\": \"Đến: claimscenter@cheapsure.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: lgreenberg@cheapsure.com\", \"vi\": \"Từ: lgreenberg@cheapsure.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: November 15\", \"vi\": \"Ngày: 15 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Re: Updates to Office Layout\", \"vi\": \"V/v: Cập nhật bố cục văn phòng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Claims Specialists:\", \"vi\": \"Gửi các Chuyên viên Giải quyết Yêu cầu Bồi thường:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"On January 1, Cheapsure will begin offering homeowners insurance as well as automobile insurance.\", \"vi\": \"Vào ngày 1 tháng 1, Cheapsure sẽ bắt đầu cung cấp bảo hiểm nhà ở cũng như bảo hiểm ô tô.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This exciting ______[135] will require a surge in hiring and adjustments to the layout of our office space.\", \"vi\": \"Sự mở rộng đầy hứng khởi này ______[135] sẽ đòi hỏi sự gia tăng về tuyển dụng và các điều chỉnh đối với bố cục không gian văn phòng của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [135]}, {\"en\": \"Tomorrow, I will hold a meeting at 2:00 P.M. in the main conference room to discuss the ______[136] changes.\", \"vi\": \"Vào ngày mai, tôi sẽ tổ chức một cuộc họp lúc 2:00 chiều tại phòng họp chính để thảo luận về các thay đổi ______[136].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [136]}, {\"en\": \"We have ______[137] flexibility with the floor plan and would like your input.\", \"vi\": \"Chúng ta có ______[137] sự linh hoạt với sơ đồ mặt bằng và rất mong nhận được ý kiến đóng góp của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [137]}, {\"en\": \"______[138].\", \"vi\": \"______[138].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [138]}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Lee Greenberg\", \"vi\": \"Lee Greenberg\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Facilities Administrator\", \"vi\": \"Quản trị viên Cơ sở vật chất\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '90a8cff9-62ac-4d35-8224-bd1cc39a1a86';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Posted by Padma Pradhan on Friday, September 23, at 12:34 P.M.\", \"vi\": \"Được đăng bởi Padma Pradhan vào thứ Sáu, ngày 23 tháng 9, lúc 12 giờ 34 phút trưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I took my mobile phone to the Vivi\'s Tech Fix location on Rivas Boulevard and 23rd Street for help with a cracked screen.\", \"vi\": \"Tôi đã mang điện thoại di động của mình đến cửa hàng Vivi\'s Tech Fix tọa lạc tại Đại lộ Rivas và Phố 23 để nhờ hỗ trợ khắc phục sự cố màn hình bị nứt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I dropped off the phone on a Tuesday afternoon, and by Wednesday morning I had received a quote by e-mail letting me know the cost to fix it.\", \"vi\": \"Tôi đã mang chiếc điện thoại đi sửa vào chiều thứ Ba, và đến sáng thứ Tư, tôi đã nhận được báo giá qua email thông báo chi phí sửa chữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I called to accept the quote and give my credit card number, and I was able to pick up the mobile the next day on my way home from work—as good as new.\", \"vi\": \"Tôi đã gọi điện để đồng ý với báo giá và cung cấp số thẻ tín dụng của mình, và ngày hôm sau trên đường về nhà sau giờ làm việc, tôi đã có thể nhận lại chiếc điện thoại di động — nó vẫn còn mới như ban đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"If you are looking for responsible professionals, Vivi\'s Tech Fix is the right place.\", \"vi\": \"Nếu quý vị đang tìm kiếm những chuyên gia có tinh thần trách nhiệm, Vivi\'s Tech Fix chính là địa chỉ phù hợp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"While I was in the store picking up my mobile, another customer came in.\", \"vi\": \"Trong lúc tôi đang ở trong cửa hàng để nhận điện thoại di động của mình, thì có một khách hàng khác bước vào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"She was also picking up a damaged mobile; however, the technicians had informed her that the device could not be fixed because of severe water damage, so she owed them nothing.\", \"vi\": \"Cô ấy cũng đang đến nhận lại chiếc điện thoại di động bị hỏng; tuy nhiên, các kỹ thuật viên đã thông báo với cô rằng thiết bị này không thể sửa chữa được do bị hư hỏng nghiêm trọng do nước, vì vậy cô không phải trả bất kỳ khoản phí nào cho họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I was impressed that customers can get a free diagnostic from the technicians and don\'t need to pay anything if a device is beyond repair.\", \"vi\": \"Tôi rất ấn tượng khi biết rằng khách hàng có thể được các kỹ thuật viên kiểm tra miễn phí và không phải trả bất kỳ khoản phí nào nếu thiết bị không thể sửa chữa được nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '91091d42-38da-411a-9a1c-537709bee78b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MASON BROTHERS MAKES MAJOR ORGANIZATIONAL CHANGE\", \"vi\": \"MASON BROTHERS THỰC HIỆN THAY ĐỔI LỚN VỀ CƠ CẤU TỔ CHỨC\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"We at Mason Brothers, Inc., are making a significant change to our corporate operations.\", \"vi\": \"Chúng tôi tại Mason Brothers, Inc., đang thực hiện một sự thay đổi đáng kể đối với hoạt động doanh nghiệp của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To improve our focus on our customers\' needs, we have adopted an organizational system that employs regional offices.\", \"vi\": \"Để nâng cao sự tập trung vào nhu cầu của khách hàng, chúng tôi đã áp dụng một hệ thống tổ chức sử dụng các văn phòng khu vực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"This new system will allow us to analyze the demands of our customers based on their ______[143].\", \"vi\": \"Hệ thống mới này sẽ cho phép chúng tôi phân tích các nhu cầu của khách hàng dựa trên ______[143] của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [143]}, {\"en\": \"Consequently, we ______[144] able to more quickly supply building and maintenance items in the regions of the country where they are most in demand.\", \"vi\": \"Do đó, chúng tôi ______[144] có thể cung cấp nhanh chóng hơn các mặt hàng xây dựng và bảo trì tại các khu vực trong nước nơi chúng có nhu cầu cao nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [144]}, {\"en\": \"This change will also help us to better support our managers as they work to improve the operations of the individual stores they oversee.\", \"vi\": \"Thay đổi này cũng sẽ giúp chúng tôi hỗ trợ tốt hơn cho các nhà quản lý của mình trong khi họ làm việc để cải thiện hoạt động của các cửa hàng cá nhân mà họ giám sát.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am confident that ______[145] of our business plan will lead to greater customer satisfaction.\", \"vi\": \"Tôi tự tin rằng ______[145] của kế hoạch kinh doanh của chúng tôi sẽ dẫn đến sự hài lòng lớn hơn của khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [145]}, {\"en\": \"For over 30 years, listening to our customers has been an integral component of our corporate strategy.\", \"vi\": \"Trong hơn 30 năm qua, việc lắng nghe khách hàng đã là một thành phần không thể thiếu trong chiến lược doanh nghiệp của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[146].\", \"vi\": \"______[146].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [146]}, {\"en\": \"— Max Mason, President and CEO\", \"vi\": \"— Max Mason, Chủ tịch kiêm Tổng Giám đốc Điều hành\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '911042c6-a993-4013-b4fa-2c1d76f843d6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Pechon Hotel: The Preferred Choice Among Business Travelers\", \"vi\": \"Khách sạn Pechon: Sự lựa chọn hàng đầu của các khách du lịch công tác\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Pechon Hotel has been providing executives from all over the world with a comfortable place to stay in Jamaica for more than 25 years.\", \"vi\": \"Trong hơn 25 năm qua, Khách sạn Pechon đã không ngừng mang đến cho các nhà quản lý đến từ khắp nơi trên thế giới một nơi lưu trú thoải mái tại Jamaica.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Our location in downtown Kingston is within walking distance of the Ministry of Foreign Trade and the Harbour Conference Centre.\", \"vi\": \"Vị trí của chúng tôi tại trung tâm thành phố Kingston nằm trong phạm vi có thể đi bộ đến Bộ Ngoại thương và Trung tâm Hội nghị Harbour.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"All of the rooms and suites at Pechon Hotel feature air-conditioning, cable television, a mini-fridge, a coffeemaker, a safe, and free Wi-Fi.\", \"vi\": \"Tất cả các phòng và dãy phòng tại Khách sạn Pechon đều được trang bị điều hòa không khí, truyền hình cáp, tủ lạnh mini, máy pha cà phê, két an toàn và Wi-Fi miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We also have an outdoor swimming pool with a poolside café, as well as a fitness room and business centre.\", \"vi\": \"Chúng tôi còn có một hồ bơi ngoài trời kèm theo quán cà phê bên hồ, cũng như phòng tập thể dục và trung tâm dịch vụ doanh nhân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Continental breakfast is available every morning for a small fee.\", \"vi\": \"Bữa sáng kiểu Âu được phục vụ vào mỗi buổi sáng với một khoản phí nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The single rooms with a double bed that make up our West Wing are available for 26,000 JMD per night.\", \"vi\": \"Các phòng đơn có giường đôi thuộc Cánh Tây của chúng tôi có giá 26.000 JMD mỗi đêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The suites in our East Wing, which additionally include a living room with a writing desk and a furnished balcony, can be reserved for 40,000 JMD per night.\", \"vi\": \"Các phòng suite tại Cánh Đông của chúng tôi, ngoài ra còn có phòng khách với bàn làm việc và ban công được trang bị đầy đủ nội thất, có thể được đặt với mức giá 40.000 JMD mỗi đêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Both wings overlook Kingston Harbour.\", \"vi\": \"Cả hai cánh đều nhìn ra Vịnh Kingston.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Visit www.pechonhotel.com.jm to reserve your stay today.\", \"vi\": \"Hãy truy cập www.pechonhotel.com.jm để đặt phòng ngay hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To: Glenda Douglas <g.douglas@jenkinsassociates.com>\", \"vi\": \"Gửi tới: Glenda Douglas <g.douglas@jenkinsassociates.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"From: Emiliano Andres <e.andres@jenkinsassociates.com>\", \"vi\": \"Từ: Emiliano Andres <e.andres@jenkinsassociates.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Subject: RE: Upcoming trip\", \"vi\": \"Chủ đề: Trả lời: Chuyến đi sắp tới\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: 8 November\", \"vi\": \"Ngày: 8 tháng 11\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Dear Glenda,\", \"vi\": \"Kính gửi Glenda,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thank you for asking before making plans to bring your husband and child on your trip to Kingston next month for the Caribbean Travel Forum.\", \"vi\": \"Xin cảm ơn quý vị đã hỏi ý kiến trước khi lên kế hoạch đưa chồng và con đi cùng trong chuyến đi tới Kingston vào tháng tới để tham dự Diễn đàn Du lịch vùng Caribê.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Jenkins Associates does indeed allow employees to bring family along on work trips at their own expense.\", \"vi\": \"Công ty Jenkins Associates thực sự cho phép nhân viên đưa gia đình đi cùng trong các chuyến công tác, với chi phí do chính họ tự chi trả.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We will still pay for your airfare, the cost of a single room for two nights, and three days\' meal allowance, but you must cover any other expenses.\", \"vi\": \"Chúng tôi vẫn sẽ chi trả chi phí vé máy bay, chi phí phòng đơn cho hai đêm và khoản trợ cấp ăn uống trong ba ngày cho quý vị, tuy nhiên quý vị phải tự chi trả mọi chi phí khác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"You should contact Pechon Hotel directly to arrange your upgrade to a suite and the extension of your stay through Saturday night.\", \"vi\": \"Quý khách nên liên hệ trực tiếp với Khách sạn Pechon để sắp xếp việc nâng hạng phòng lên phòng suite và gia hạn thời gian lưu trú đến hết đêm thứ Bảy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Please also keep in mind that you will be expected to attend all conference events as usual, including evening ones.\", \"vi\": \"Xin quý vị cũng lưu ý rằng quý vị sẽ được yêu cầu tham dự tất cả các sự kiện của hội nghị như thường lệ, bao gồm cả các sự kiện vào buổi tối.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Let me know if you have any other questions.\", \"vi\": \"Nếu quý vị còn thắc mắc gì khác, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Emiliano Andres, Human Resources Specialist\", \"vi\": \"Emiliano Andres, Chuyên viên Nhân sự\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"9–9:30 A.M. - Registration\", \"vi\": \"9 giờ – 9 giờ 30 sáng - Đăng ký\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"9:30–10 A.M. - Opening Remarks (Jalissa Vargas, President of the Caribbean Tourism Association)\", \"vi\": \"9 giờ 30 – 10 giờ sáng – Phát biểu khai mạc (bà Jalissa Vargas, Chủ tịch Hiệp hội Du lịch vùng Caribê)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"10 A.M.–12 P.M. - Keynote Address: Integrating Technology into Caribbean Tourism (Irene Summers, CEO of TravelZap)\", \"vi\": \"10 giờ sáng – 12 giờ trưa - Bài phát biểu chính: Tích hợp công nghệ vào ngành du lịch vùng Caribê (Irene Summers, Giám đốc điều hành của TravelZap)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"12–1 P.M. - Lunch\", \"vi\": \"12 giờ – 1 giờ chiều - Bữa trưa\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"1:30–3 P.M. - Seminar: Public Policy Challenges (Eric Perry, Professor at Bridgetown College)\", \"vi\": \"13h30–15h00 – Hội thảo: Những thách thức trong chính sách công (Eric Perry, Giáo sư tại Trường Cao đẳng Bridgetown)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"3:30–5 P.M. - Panel: Achieving Environmentally Sustainable Tourism (Various experts)\", \"vi\": \"15h30–17h00 – Phiên thảo luận: Hướng tới du lịch bền vững về mặt môi trường (Với sự tham gia của các chuyên gia)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"6:30 P.M. - Networking Dinner\", \"vi\": \"18 giờ 30 - Bữa tối giao lưu\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Caribbean Travel Forum\", \"vi\": \"Diễn đàn Du lịch vùng Caribe\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Friday, 4 December Harbour Conference Center Kingston, Jamaica\", \"vi\": \"Thứ Sáu, ngày 4 tháng 12 – Trung tâm Hội nghị Harbour, Kingston, Jamaica\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}]' WHERE `id` = '91a366c7-41a8-4108-8a35-5e7fac4e593e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Item - Item Name - Quantity - Price Each - Amount\", \"vi\": \"Mặt hàng - Tên mặt hàng - Số lượng - Giá mỗi chiếc - Tổng số tiền\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"14L - 3 m table linens, cream - 4 - $26.00 - $104.00\", \"vi\": \"14L - Khăn trải bàn 3 m, màu kem - 4 chiếc - 26,00 USD - 104,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"17P - 25 cm dinner plates, pale blue - 40 - $4.40 - $176.00\", \"vi\": \"17P - Đĩa ăn tối đường kính 25 cm, màu xanh nhạt - 40 chiếc - 4,40 USD - 176,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"18S - 50 cm serving dishes, white - 20 - $7.95 - $159.00\", \"vi\": \"Đĩa phục vụ 18S - 50 cm, màu trắng - 20 chiếc - 7,95 USD - 159,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"21G - 350 ml water goblets, amber - 40 - $3.25 - $130.00\", \"vi\": \"21G - Cốc nước 350 ml, màu hổ phách - 40 chiếc - 3,25 USD - 130,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Subtotal - $569.00\", \"vi\": \"Tổng phụ - 569,00 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Tax (HST) - $73.97\", \"vi\": \"Thuế (HST) - 73,97 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Shipping - $30.00\", \"vi\": \"Phí vận chuyển - 30,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Total - $672.97\", \"vi\": \"Tổng cộng - 672,97 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"McGivern Wholesale\", \"vi\": \"McGivern Bán buôn\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"1486 Beden Trail, Brampton ON L6R 2K7\", \"vi\": \"1486 Beden Trail, Brampton, ON L6R 2K7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"905-555-0158 • www.mcgivernwholesale.ca\", \"vi\": \"905-555-0158 • www.mcgivernwholesale.ca\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Ordered By: Deshauna\'s Creations\", \"vi\": \"Đơn hàng do: Deshauna\'s Creations đặt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Order Date: October 12\", \"vi\": \"Ngày đặt hàng: 12 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Payment is due upon receipt.\", \"vi\": \"Quý vị vui lòng thanh toán ngay khi nhận được hóa đơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To: Pete McGivern <pete.mcgivern@mcgivernwholesale.ca>\", \"vi\": \"Gửi tới: Pete McGivern <pete.mcgivern@mcgivernwholesale.ca>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"From: Deshauna Jacques <deshaunajacques@deshaunascreations.ca>\", \"vi\": \"Từ: Deshauna Jacques <deshaunajacques@deshaunascreations.ca>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Subject: October order\", \"vi\": \"Chủ đề: Đơn hàng tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Date: October 17\", \"vi\": \"Ngày: 17 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Dear Mr. McGivern,\", \"vi\": \"Kính gửi ông McGivern,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I received my October order, but there were some errors.\", \"vi\": \"Tôi đã nhận được đơn hàng tháng 10, nhưng có một số sai sót.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I received 20 dinner plates instead of 40, and seven water goblets arrived with cracks in the glass.\", \"vi\": \"Tôi đã nhận được 20 chiếc đĩa ăn thay vì 40 chiếc, và bảy chiếc ly nước có vết nứt trên thân ly.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Have you switched shipping carriers recently?\", \"vi\": \"Gần đây quý vị có thay đổi đơn vị vận chuyển không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I have been a loyal customer since you opened five years ago, and never before have I experienced problems with an order.\", \"vi\": \"Tôi đã là khách hàng trung thành của quý công ty kể từ khi quý công ty khai trương cách đây năm năm, và cho đến nay tôi chưa từng gặp phải bất kỳ vấn đề nào liên quan đến đơn hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Incidentally, you might like to know that I spoke this morning with Ed Salek, owner of nearby Salek\'s Café.\", \"vi\": \"Nhân tiện, có lẽ quý vị sẽ muốn biết rằng sáng nay tôi đã nói chuyện với ông Ed Salek, chủ quán Salek’s Café ở gần đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"He mentioned that his last delivery from you had some mistakes too.\", \"vi\": \"Ông ấy có đề cập rằng lô hàng gần đây nhất mà quý công ty gửi cho ông ấy cũng có một số sai sót.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"How soon can you fix my order?\", \"vi\": \"Quý vị có thể xử lý đơn hàng của tôi trong bao lâu?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I have three parties coming up next week, so I need these items quickly.\", \"vi\": \"Tuần tới tôi có ba bữa tiệc sắp diễn ra, nên tôi cần những món đồ này càng sớm càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Deshauna Jacques\", \"vi\": \"Deshauna Jacques\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"To: Deshauna Jacques <deshaunajacques@deshaunascreations.ca>\", \"vi\": \"Gửi tới: Deshauna Jacques <deshaunajacques@deshaunascreations.ca>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"From: Pete McGivern <pete.mcgivern@mcgivernwholesale.ca>\", \"vi\": \"Từ: Pete McGivern <pete.mcgivern@mcgivernwholesale.ca>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Subject: Re: October order\", \"vi\": \"Chủ đề: Trả lời: Đơn hàng tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Date: October 17\", \"vi\": \"Ngày: 17 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Dear Ms. Jacques,\", \"vi\": \"Kính gửi bà Jacques,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"I was very sorry to learn about your order, and about Mr. Salek\'s as well; I will extend my apology to him today.\", \"vi\": \"Tôi vô cùng lấy làm tiếc khi biết về đơn đặt hàng của quý vị, cũng như về đơn đặt hàng của ông Salek; hôm nay tôi sẽ chuyển lời xin lỗi đến ông ấy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"You are a valued customer, and I am embarrassed that you received such a poor shipment.\", \"vi\": \"Quý khách là một khách hàng quý báu, và tôi thực sự cảm thấy xấu hổ vì quý khách đã nhận được một lô hàng kém chất lượng như vậy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"We are in the middle of moving to a new warehouse, and it has not gone as smoothly as I had hoped.\", \"vi\": \"Hiện tại, chúng tôi đang trong quá trình chuyển sang một kho hàng mới, và mọi việc diễn ra không suôn sẻ như tôi mong đợi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Regardless, I want to make amends as soon as possible.\", \"vi\": \"Dù sao đi nữa, tôi cũng muốn sửa sai càng sớm càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"I have put in an order to correct the mistakes, and I hope you will accept a 15 percent discount on your next shipment.\", \"vi\": \"Tôi đã ra lệnh khắc phục những sai sót này và hy vọng quý vị sẽ chấp nhận mức chiết khấu 15 phần trăm cho lô hàng tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Just use code 15D when placing your order.\", \"vi\": \"Chỉ cần sử dụng mã 15D khi quý vị đặt hàng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Please let me know if there is anything else I can do to correct this.\", \"vi\": \"Xin vui lòng cho tôi biết nếu còn điều gì khác mà tôi có thể làm để khắc phục vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Yours sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Pete McGivern\", \"vi\": \"Pete McGivern\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}]' WHERE `id` = '91ca45a0-eae8-48a3-b46d-ebe9352e95c7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Susan Rollins (10:12 A.M.)\", \"vi\": \"Susan Rollins (10 giờ 12 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I just looked through your preliminary design plans for the Miller house on Greenwood Lane.\", \"vi\": \"Tôi vừa xem qua các bản thiết kế sơ bộ của quý vị cho ngôi nhà của gia đình Miller trên đường Greenwood Lane.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Everything looks great, especially the kitchen and main living area.\", \"vi\": \"Mọi thứ trông đều rất đẹp, đặc biệt là nhà bếp và khu vực sinh hoạt chính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"My only concern is the practicality of the glass sunroom.\", \"vi\": \"Mối quan ngại duy nhất của tôi là tính thực tiễn của phòng kính hướng nắng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Glass rooms often run over budget.\", \"vi\": \"Các phòng kính thường vượt quá ngân sách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Myles Hart (10:15 A.M.)\", \"vi\": \"Myles Hart (10 giờ 15 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The clients insisted I include the sunroom.\", \"vi\": \"Các khách hàng đã nhất quyết yêu cầu tôi đưa phòng hướng nắng vào thiết kế.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"They\'re going to try to find a way to finance it.\", \"vi\": \"Họ sẽ cố gắng tìm cách huy động vốn cho dự án này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Susan Rollins (10:17 A.M.)\", \"vi\": \"Susan Rollins (10 giờ 17 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We\'ll need to make sure that\'s arranged before we finalize these plans.\", \"vi\": \"Chúng ta cần đảm bảo rằng việc đó đã được sắp xếp xong trước khi hoàn tất các kế hoạch này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"In the meantime, can you come up with a new design that leaves off this addition?\", \"vi\": \"Trong thời gian này, quý vị có thể đề xuất một thiết kế mới mà không bao gồm phần bổ sung này được không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Myles Hart (10:18 A.M.)\", \"vi\": \"Myles Hart (10 giờ 18 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Shouldn\'t be a problem.\", \"vi\": \"Chắc sẽ không có vấn đề gì đâu.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I\'ll work on it now.\", \"vi\": \"Tôi sẽ bắt tay vào làm ngay bây giờ.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I\'d planned to talk to the Millers later today, so I can discuss the budget with them then.\", \"vi\": \"Tôi đã dự định sẽ liên hệ với gia đình Miller vào cuối ngày hôm nay, để khi đó tôi có thể thảo luận về ngân sách với họ.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '91d32e6b-fa88-489c-988c-8c91297e6aed';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Greatford Curtains\", \"vi\": \"Rèm cửa Greatford\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"137 Chapel Way, Birmingham B8 3HU\", \"vi\": \"137 Chapel Way, Birmingham B8 3HU\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"0121 496 0608\", \"vi\": \"0121 496 0608\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Fabric Samples - Number - Price\", \"vi\": \"Mẫu vải - Số hiệu - Giá\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Cambridge - x1 - £ 8.00\", \"vi\": \"Cambridge - 1 cuốn - 8,00 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Manchester - x1 - £ 8.00\", \"vi\": \"Manchester - x1 - 8,00 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Oxford - x1 - £ 8.00\", \"vi\": \"Oxford - 1 bản - 8,00 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Windsor - x1 - £ 8.00\", \"vi\": \"Windsor - x1 - 8,00 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Shipping - £ 4.25\", \"vi\": \"Phí vận chuyển - 4,25 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Subtotal - £36.25\", \"vi\": \"Tổng phụ - 36,25 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"VAT - £ 7.25\", \"vi\": \"Thuế GTGT - 7,25 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Total - £43.50\", \"vi\": \"Tổng cộng - 43,50 bảng Anh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you for your order and for supporting our family\'s small business.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã đặt hàng và ủng hộ doanh nghiệp nhỏ của gia đình chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To show our appreciation, we are offering you 10 percent off your next order of £200 or more.\", \"vi\": \"Để bày tỏ lòng biết ơn, chúng tôi xin dành tặng quý khách ưu đãi giảm giá 10% cho đơn hàng tiếp theo có giá trị từ 200 bảng trở lên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Use coupon code NEWCURTAINS.\", \"vi\": \"Vui lòng sử dụng mã giảm giá NEWCURTAINS.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Customer Information\", \"vi\": \"Thông tin khách hàng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Nicolla Grant\", \"vi\": \"Nicolla Grant\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"17 Durst Place\", \"vi\": \"17 Durst Place\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Whitstable CT5 1AH\", \"vi\": \"Whitstable CT5 1AH\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Date: 23 July\", \"vi\": \"Ngày: 23 tháng 7\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Order Number: 19842\", \"vi\": \"Số đơn đặt hàng: 19842\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"To: Greatford Curtains <customerservice@greatfordcurtains.co.uk>\", \"vi\": \"Gửi tới: Greatford Curtains <customerservice@greatfordcurtains.co.uk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"From: Nicolla Grant <ngrant@sapphiremail.co.uk>\", \"vi\": \"Từ: Nicolla Grant <ngrant@sapphiremail.co.uk>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Date: 27 July\", \"vi\": \"Ngày: 27 tháng 7\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Subject: Order #19842\", \"vi\": \"Chủ đề: Đơn hàng số 19842\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Good afternoon,\", \"vi\": \"Xin chào buổi chiều,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I received my fabric samples today, and they are beautiful!\", \"vi\": \"Hôm nay tôi đã nhận được các mẫu vải, và chúng thật đẹp!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I would like to get a quote for custom curtains for my dining room using the Manchester fabric.\", \"vi\": \"Tôi xin được nhận báo giá cho bộ rèm cửa đặt may riêng cho phòng ăn của tôi bằng loại vải Manchester.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I need four panels, 117 cm x 228 cm each, made in your box pleat style.\", \"vi\": \"Tôi cần bốn tấm vải, mỗi tấm có kích thước 117 cm × 228 cm, được may theo kiểu nếp gấp hộp của quý công ty.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Please let me know how much that will cost and when I can expect to receive them.\", \"vi\": \"Xin vui lòng cho tôi biết chi phí cho việc đó là bao nhiêu và khi nào tôi có thể nhận được chúng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"As a reminder, I have a coupon code for 10 percent off.\", \"vi\": \"Xin nhắc lại, tôi có một mã giảm giá 10 phần trăm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I am also interested in curtains for my living room, but the shades of blue in all the samples I received do not work well in that space.\", \"vi\": \"Tôi cũng quan tâm đến rèm cửa cho phòng khách của mình, nhưng các sắc thái màu xanh trong tất cả các mẫu mà tôi nhận được đều không phù hợp với không gian đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Could you please send me samples of your Edinburgh and Norwich fabrics?\", \"vi\": \"Xin quý vị vui lòng gửi cho tôi một số mẫu vải Edinburgh và Norwich của quý vị được không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"I understand that they come in shades of green.\", \"vi\": \"Tôi hiểu rằng chúng có nhiều sắc thái màu xanh lá cây khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Feel free to charge the credit card I saved to my online profile during my last order on 23 July.\", \"vi\": \"Xin vui lòng tiến hành thanh toán bằng thẻ tín dụng mà tôi đã lưu trong hồ sơ trực tuyến của mình trong lần đặt hàng gần đây nhất vào ngày 23 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Nicolla Grant\", \"vi\": \"Nicolla Grant\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}]' WHERE `id` = '91e25fab-c099-4209-85c0-53d081e22b93';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Berestoff Ltd. ---131--- a professional procurement officer to oversee bidding and procurement processes in all company departments.\", \"vi\": \"Berestoff Ltd. ---131--- một nhân viên thu mua chuyên nghiệp để giám sát các quy trình đấu thầu và thu mua ở tất cả các phòng ban của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [131]}, {\"en\": \"This employee will draft advertisements, prepare contract documents, process bids, ---132--- provide training on policy and procedures to company personnel.\", \"vi\": \"Nhân viên này sẽ soạn thảo quảng cáo, chuẩn bị các tài liệu hợp đồng, xử lý hồ sơ dự thầu, ---132--- cung cấp đào tạo về chính sách và thủ tục cho nhân sự công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [132]}, {\"en\": \"The position requires a two-year degree in business administration or a related field.\", \"vi\": \"Vị trí này yêu cầu bằng cao đẳng hai năm về quản trị kinh doanh hoặc một lĩnh vực liên quan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The ---133--- must have a minimum of three years experience as an office manager in a corporate environment, including recent experience in procurement.\", \"vi\": \"Ứng viên ---133--- phải có tối thiểu ba năm kinh nghiệm làm quản lý văn phòng trong môi trường doanh nghiệp, bao gồm cả kinh nghiệm gần đây về thu mua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [133]}, {\"en\": \"---134---.\", \"vi\": \"---134---.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [134]}]' WHERE `id` = '921f0c60-04b7-41f9-bb45-31b9cd5dbefe';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Save Money with Zipply Split\", \"vi\": \"Tiết kiệm chi phí cùng Zipply Split\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Millions of people across the country have come to depend on the Zipply app to quickly find rides for trips within their city.\", \"vi\": \"Hàng triệu người trên khắp cả nước hiện đã tin dùng ứng dụng Zipply để nhanh chóng tìm phương tiện di chuyển cho các chuyến đi trong thành phố của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Now, Zipply is proud to begin offering similar convenience at even more affordable rates through Zipply Split.\", \"vi\": \"Hiện nay, Zipply tự hào được bắt đầu cung cấp những tiện ích tương tự với mức giá còn hợp lý hơn nữa thông qua dịch vụ Zipply Split.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Zipply Split lets you receive up to 20% off your trip by simply sharing your ride with another Zipply user heading in a similar direction.\", \"vi\": \"Zipply Split cho phép quý vị được giảm giá tới 20% cho chuyến đi của mình chỉ bằng cách chia sẻ chuyến đi với một người dùng Zipply khác đang di chuyển theo hướng tương tự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Details:\", \"vi\": \"Chi tiết:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Use Zipply Split by selecting it from among the ride options that appear once you input your destination.\", \"vi\": \"Để sử dụng Zipply Split, quý vị hãy chọn dịch vụ này trong số các tùy chọn đi lại sẽ hiển thị sau khi quý vị nhập điểm đến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The discount percentage is calculated based on the time and distance traveled with your co-rider.\", \"vi\": \"Tỷ lệ chiết khấu được tính dựa trên thời gian và quãng đường di chuyển cùng với hành khách đi chung của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Any required changes to your route will add no more than ten minutes to your trip.\", \"vi\": \"Bất kỳ thay đổi nào cần thiết đối với lộ trình của quý khách sẽ chỉ làm thời gian di chuyển của quý khách tăng thêm tối đa mười phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This service is not yet available in all cities in which Zipply is active.\", \"vi\": \"Dịch vụ này hiện vẫn chưa được cung cấp tại tất cả các thành phố mà Zipply đang hoạt động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Try Zipply Split for your next ride and see how much you save!\", \"vi\": \"Hãy thử sử dụng Zipply Split trong chuyến đi tiếp theo của quý vị và xem quý vị sẽ tiết kiệm được bao nhiêu!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '924031a8-3f0f-4567-a841-bbedc4d796d9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"URL: http://www.midwestartisanalcheeseguild.org\", \"vi\": \"URL: http://www.midwestartisanalcheeseguild.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Midwest Artisanal Cheese Guild (MACG) organizes trade shows and conducts educational seminars ______[135] the cheese-crafting trade within the midwestern United States.\", \"vi\": \"Hiệp hội Phô mai Thủ công Trung Tây (MACG) tổ chức các triển lãm thương mại và tiến hành các hội thảo giáo dục ______[135] ngành nghề làm phô mai tại khu vực Trung Tây Hoa Kỳ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [135]}, {\"en\": \"Cheeses from this region are recognized internationally.\", \"vi\": \"Phô mai từ khu vực này được công nhận trên trường quốc tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Many of ______[136] cheeses are used by chefs at restaurants around the world.\", \"vi\": \"Nhiều loại trong số ______[136] loại phô mai này được sử dụng bởi các đầu bếp tại các nhà hàng trên khắp thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"The MACG puts on the region\'s largest cheese-maker exposition, held each year in April.\", \"vi\": \"MACG tổ chức triển lãm nhà sản xuất phô mai lớn nhất của khu vực, được tổ chức vào tháng Tư hàng năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The prestigious Wizard of Cheese contest is held at this event.\", \"vi\": \"Cuộc thi Phù thủy Phô mai danh giá được tổ chức tại sự kiện này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[137].\", \"vi\": \"______[137].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [137]}, {\"en\": \"Dan Travella was last year\'s ______[138].\", \"vi\": \"Dan Travella là ______[138] của năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [138]}, {\"en\": \"His aged cheddar cheese received a winning score of 98.7 out of 100.\", \"vi\": \"Món phô mai cheddar ủ lâu năm của ông đã nhận được số điểm chiến thắng là 98,7 trên 100.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '924c43a4-adce-4f75-8bd9-0c40ee60544b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Fastest Fleet\", \"vi\": \"Đội tàu nhanh nhất\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"RATE OUR SERVICES AND WIN FREE TRAVEL!\", \"vi\": \"HÃY ĐÁNH GIÁ DỊCH VỤ CỦA CHÚNG TÔI VÀ CÓ CƠ HỘI NHẬN CHUYẾN DU LỊCH MIỄN PHÍ!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Visit our Web site at www.fastestfleet.com/feedback and fill out the 5-minute questionnaire.\", \"vi\": \"Hãy truy cập trang web của chúng tôi tại địa chỉ www.fastestfleet.com/feedback và điền vào bảng câu hỏi chỉ mất 5 phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"You could win one of 10 FREE round-trip bus trips to any destination within the continental United States!\", \"vi\": \"Quý vị có cơ hội trúng thưởng một trong 10 chuyến đi khứ hồi MIỄN PHÍ bằng xe buýt đến bất kỳ điểm đến nào trong lãnh thổ Hoa Kỳ!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"You must be 18 or older to participate.\", \"vi\": \"Quý vị phải từ 18 tuổi trở lên mới được tham gia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Only customers who have previously traveled with Fastest Fleet are eligible to enter.\", \"vi\": \"Chỉ những khách hàng đã từng sử dụng dịch vụ của Fastest Fleet mới đủ điều kiện tham gia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '92c6a691-79c0-4553-a6b9-b8d08a1458b1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Free Bus Rides to Newgrange County Fair\", \"vi\": \"Chuyến xe buýt miễn phí đến Hội chợ Hạt Newgrange\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To help reduce traffic congestion and make parking easier, Newgrange Township will provide free bus rides to and from this year\'s Newgrange County Fair.\", \"vi\": \"Để góp phần giảm thiểu tình trạng ùn tắc giao thông và giúp việc đỗ xe trở nên dễ dàng hơn, Thị trấn Newgrange sẽ cung cấp các chuyến xe buýt miễn phí khứ hồi đến Hội chợ Hạt Newgrange năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"______[143] will be available from Friday, June 5, to Sunday, June 7.\", \"vi\": \"______[143] sẽ có sẵn từ Thứ Sáu, ngày 5 tháng 6, đến Chủ Nhật, ngày 7 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [143]}, {\"en\": \"Planned pickup locations include the Rhinesberg Elementary School on Route 38 and the Newgrange Municipal Building on Main Street.\", \"vi\": \"Các địa điểm đón khách dự kiến bao gồm Trường Tiểu học Rhinesberg trên Quốc lộ 38 và Tòa nhà Hành chính Newgrange trên Phố Main.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Buses going to the fair will depart from these locations hourly from 8 A.M. to 5 P.M. Buses ______[144] the fairgrounds on the half hour, from 8:30 A.M. to 7:30 P.M. Please note that children under the age of 16 must be accompanied by an adult.\", \"vi\": \"Xe buýt đến hội chợ sẽ khởi hành từ các địa điểm này hàng giờ từ 8 giờ sáng đến 5 giờ chiều. Xe buýt ______[144] khu vực hội chợ vào phút thứ ba mươi của mỗi giờ, từ 8:30 sáng đến 7:30 tối. Xin lưu ý rằng trẻ em dưới 16 tuổi phải có người lớn đi kèm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [144]}, {\"en\": \"______[145].\", \"vi\": \"______[145].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [145]}, {\"en\": \"The Newgrange County Fair Committee thanks our generous sponsors for providing buses and ______[146] this year.\", \"vi\": \"Ban tổ chức Hội chợ Hạt Newgrange xin gửi lời cảm ơn đến các nhà tài trợ hào phóng vì đã cung cấp xe buýt và ______[146] năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [146]}, {\"en\": \"We hope you will join us at the Newgrange County Fair!\", \"vi\": \"Chúng tôi hy vọng bạn sẽ tham gia cùng chúng tôi tại Hội chợ Hạt Newgrange!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = '92caffc7-696d-4156-abb0-336c16d45e7a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"13 March\", \"vi\": \"Ngày 13 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dennis Carrera\", \"vi\": \"Dennis Carrera\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Lejos Plumbing and Heating\", \"vi\": \"Lejos Plumbing and Heating\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"San Antonio, Texas\", \"vi\": \"San Antonio, Texas\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Carrera:\", \"vi\": \"Kính gửi ông Carrera:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Congratulations!\", \"vi\": \"Chúc mừng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Mallorca Construction ______[143] the bid of Lejos Plumbing and Heating to provide enhancements to the County Courthouse.\", \"vi\": \"Mallorca Construction ______[143] hồ sơ dự thầu của Lejos Plumbing and Heating để cung cấp các dịch vụ cải tạo cho Tòa án Quận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [143]}, {\"en\": \"Your workers will have access to the ______[144] on May 5.\", \"vi\": \"Công nhân của quý công ty sẽ có quyền tiếp cận ______[144] vào ngày 5 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [144]}, {\"en\": \"As specified by the district building code, Lejos Plumbing and Heating will be responsible for securing the required permits.\", \"vi\": \"Theo quy định của quy chuẩn xây dựng quận, Lejos Plumbing and Heating sẽ chịu trách nhiệm xin các giấy phép cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The enclosed plan outlines the scope of the project.\", \"vi\": \"Bản kế hoạch đính kèm phác thảo phạm vi của dự án.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"______[145], the document lists the other contractors we are partnering with, and it reveals how your firm\'s work fits into the overall project.\", \"vi\": \"______[145], tài liệu này liệt kê các nhà thầu khác mà chúng tôi đang hợp tác, đồng thời tiết lộ cách thức công việc của công ty ông đóng góp vào toàn bộ dự án.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [145]}, {\"en\": \"We are requesting no significant adjustments to the blueprints and specifications you submitted with your proposal.\", \"vi\": \"Chúng tôi yêu cầu không có sự điều chỉnh đáng kể nào đối với bản vẽ kỹ thuật và thông số kỹ thuật mà ông đã nộp cùng với hồ sơ đề xuất của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Please contact my office if you need additional information.\", \"vi\": \"Vui lòng liên hệ với văn phòng của tôi nếu ông cần thêm thông tin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"______[146].\", \"vi\": \"______[146].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": [146]}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Petra Rojas, Manager\", \"vi\": \"Petra Rojas, Quản lý\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Mallorca Construction Ltd.\", \"vi\": \"Công ty TNHH Xây dựng Mallorca\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Enclosure\", \"vi\": \"Tài liệu đính kèm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '92cc3745-d833-4d3a-87f9-526ea9e6c07b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Sam Heinz\", \"vi\": \"Đến: Sam Heinz\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Northways Professional Development\", \"vi\": \"Từ: Northways Professional Development\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Sent: April 20\", \"vi\": \"Đã gửi: Ngày 20 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Workshop 4/28–4/30\", \"vi\": \"Chủ đề: Hội thảo 28/4–30/4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Workshop Participants,\", \"vi\": \"Kính gửi các tham dự viên hội thảo,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We look forward to seeing you at the digital storytelling workshop.\", \"vi\": \"Chúng tôi rất mong được gặp quý vị tại buổi hội thảo kể chuyện kỹ thuật số.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"On the first day, when you enter the Albin College campus, attendants will ______[135] you to lot 43 and the Toteman Building.\", \"vi\": \"Vào ngày đầu tiên, khi bạn bước vào khuôn viên Cao đẳng Albin, nhân viên phục vụ sẽ ______[135] bạn đến bãi đậu xe 43 và Tòa nhà Toteman.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [135]}, {\"en\": \"We will begin each day in conference room 9.\", \"vi\": \"Chúng ta sẽ bắt đầu mỗi ngày tại phòng họp 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Coffee, tea, snacks, and fruit ______[136] in the mornings.\", \"vi\": \"Cà phê, trà, đồ ăn nhẹ và trái cây ______[136] vào các buổi sáng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [136]}, {\"en\": \"Lunch will be sandwiches and salads from Black Horse Restaurant.\", \"vi\": \"Bữa trưa sẽ gồm bánh mì kẹp và các món salad từ Nhà hàng Black Horse.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"______[137].\", \"vi\": \"______[137].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [137]}, {\"en\": \"In the afternoons, we will be working in the computer lab.\", \"vi\": \"Vào buổi chiều, chúng ta sẽ làm việc tại phòng thí nghiệm máy tính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We suggest that you assemble some images that you would like to use for your project.\", \"vi\": \"Chúng tôi đề xuất bạn chuẩn bị sẵn một số hình ảnh mà bạn muốn sử dụng cho dự án của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"It will be ______[138] for you to have them saved on a digital storage device beforehand.\", \"vi\": \"Sẽ thật ______[138] nếu bạn lưu trữ sẵn chúng trên một thiết bị lưu trữ kỹ thuật số từ trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": [138]}, {\"en\": \"If you have any questions, please e-mail us.\", \"vi\": \"Nếu bạn có bất kỳ câu hỏi nào, vui lòng gửi email cho chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Very Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Gina Kapuski\", \"vi\": \"Gina Kapuski\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '9307a1d0-2593-4dc4-ba60-755fe466b123';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Department Managers\", \"vi\": \"Kính gửi: Các Trưởng phòng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Margaret Langley\", \"vi\": \"Từ: Margaret Langley\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: December 27\", \"vi\": \"Ngày: 27 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Extended-absence greeting\", \"vi\": \"Chủ đề: Lời chào khi vắng mặt trong thời gian dài\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Sample message #5\", \"vi\": \"Tệp đính kèm: Mẫu tin nhắn số 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Managers,\", \"vi\": \"Kính gửi các Quản lý,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In preparation for the upcoming holiday when offices will be closed, I\'d like to remind you that company policy requires each of our departments to replace the traditional greeting on their voice messaging systems with an extended-absence greeting that will play next week when callers are diverted to voice mail.\", \"vi\": \"Để chuẩn bị cho kỳ nghỉ sắp tới khi các văn phòng sẽ đóng cửa, tôi xin nhắc nhở quý vị rằng theo quy định của công ty, mỗi phòng ban cần thay thế lời chào thông thường trên hệ thống thư thoại của mình bằng lời chào thông báo vắng mặt dài ngày; lời chào này sẽ được phát vào tuần tới khi các cuộc gọi được chuyển hướng sang hộp thư thoại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This will involve making a new recording, saving it to the system, and programming the system to activate the recording at the close of our business day on Friday.\", \"vi\": \"Quá trình này bao gồm việc thực hiện một bản ghi âm mới, lưu bản ghi âm đó vào hệ thống và lập trình hệ thống để kích hoạt bản ghi âm vào cuối ngày làm việc thứ Sáu của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Once you activate the extended-absence greeting, it will override the traditional greeting through the holiday.\", \"vi\": \"Khi quý vị kích hoạt lời chào vắng mặt dài ngày, lời chào này sẽ thay thế lời chào thông thường trong suốt kỳ nghỉ lễ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The attached document contains the text of the greeting you should record.\", \"vi\": \"Tài liệu đính kèm chứa nội dung lời chào mà quý vị cần thu âm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"This is the same text we have used in the past, but as usual, the dates have been changed to reflect the current closure.\", \"vi\": \"Đây là đoạn văn bản mà chúng tôi đã sử dụng trước đây, nhưng như thường lệ, các mốc thời gian đã được điều chỉnh để phản ánh tình trạng đóng cửa hiện tại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please use this document to record your holiday greeting.\", \"vi\": \"Kính mong quý vị sử dụng tài liệu này để ghi lại lời chúc mừng ngày lễ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Make sure you activate it before you leave for the day on Friday.\", \"vi\": \"Xin vui lòng đảm bảo rằng quý vị đã kích hoạt tính năng này trước khi kết thúc ngày làm việc vào thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '93107748-99ff-4068-b073-0e31f2b20c43';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Won Ho Kim\", \"vi\": \"Từ: Won Ho Kim\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Management Team\", \"vi\": \"Kính gửi: Ban Lãnh đạo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 12 August\", \"vi\": \"Ngày: 12 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Improving employee satisfaction\", \"vi\": \"Chủ đề: Nâng cao mức độ hài lòng của nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Management Team:\", \"vi\": \"Đội ngũ lãnh đạo:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Over the next few months, the Human Resources department will be engaging with the Management Team in a variety of conversations about increasing productivity and employee satisfaction.\", \"vi\": \"Trong vài tháng tới, Phòng Nhân sự sẽ phối hợp với Ban Lãnh đạo để tiến hành nhiều cuộc thảo luận khác nhau về việc nâng cao năng suất lao động và mức độ hài lòng của nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Telecommuting, in which employees are permitted to work from home all or part of the time, is an approach that many companies are using because it allows employees to work on tasks that may be difficult to complete in an office full of disruptions.\", \"vi\": \"Làm việc từ xa — hình thức cho phép nhân viên làm việc tại nhà toàn bộ hoặc một phần thời gian — là phương thức mà nhiều doanh nghiệp đang áp dụng, bởi nó giúp nhân viên tập trung hoàn thành các nhiệm vụ vốn khó thực hiện trong môi trường văn phòng đầy những yếu tố gây xao nhãng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"With the building reconfiguration project coming up in January, we would like to take the opportunity to consider whether telecommuting would be a good solution for our company.\", \"vi\": \"Với dự án tái cấu trúc tòa nhà sắp được triển khai vào tháng 1, chúng tôi mong muốn nhân cơ hội này để xem xét liệu hình thức làm việc từ xa có phải là một giải pháp phù hợp cho công ty chúng tôi hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Our final decision on this matter will influence the way in which the work space is reorganized.\", \"vi\": \"Quyết định cuối cùng của chúng tôi về vấn đề này sẽ tác động đến cách thức sắp xếp lại không gian làm việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I am writing to ask for your feedback.\", \"vi\": \"Tôi viết thư này để xin ý kiến phản hồi của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"At this point, Human Resources is simply gathering information.\", \"vi\": \"Hiện tại, Phòng Nhân sự chỉ đang thu thập thông tin mà thôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Please complete the telecommuting survey, which is found on the Human Resources Web site.\", \"vi\": \"Kính mong quý vị hoàn thành bản khảo sát về làm việc từ xa, được đăng tải trên trang web của Phòng Nhân sự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Just look for the link on the left side of the home page.\", \"vi\": \"Quý vị chỉ cần tìm liên kết ở phía bên trái của trang chủ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Thank you in advance, and please let me know if you have any questions.\", \"vi\": \"Xin chân thành cảm ơn quý vị trước, và xin vui lòng cho tôi biết nếu quý vị có bất kỳ thắc mắc nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Won Ho Kim\", \"vi\": \"Kim Won Ho\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Human Resources Manager\", \"vi\": \"Trưởng phòng Nhân sự\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"GHTY Engineering, Inc.\", \"vi\": \"Công ty TNHH GHTY Engineering\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '936c1fc0-4eba-4e2c-9160-69806debd7ce';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Stan Anyati\", \"vi\": \"Kính gửi: Stan Anyati\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Stella Gerraldi\", \"vi\": \"Từ: Stella Gerraldi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 1\", \"vi\": \"Ngày: 1 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Café Marti\", \"vi\": \"Chủ đề: Quán cà phê Marti\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Stan,\", \"vi\": \"Kính gửi ông Stan,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I called your shop yesterday and spoke with Andre about my vintage espresso maker.\", \"vi\": \"Hôm qua tôi đã gọi điện đến cửa hàng của quý vị và trao đổi với anh Andre về chiếc máy pha cà phê espresso cổ điển của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I was surprised that he was able to find replacement parts for such an old machine.\", \"vi\": \"Tôi rất ngạc nhiên khi thấy anh ấy có thể tìm được các bộ phận thay thế cho một chiếc máy cũ như vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"He also re-created some parts that are no longer made.\", \"vi\": \"Ông cũng đã tái chế tạo một số bộ phận hiện đã ngừng sản xuất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Apparently, there is a brass holder for the manufacturer\'s nameplate that has not yet arrived from Italy.\", \"vi\": \"Có vẻ như chiếc khung bằng đồng dùng để gắn bảng tên nhà sản xuất vẫn chưa được chuyển đến từ Ý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Once that arrives, the restoration can be completed.\", \"vi\": \"Khi món đồ đó được chuyển đến, công tác phục hồi sẽ có thể hoàn tất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"As we discussed earlier, I need the machine delivered by May 7.\", \"vi\": \"Như chúng ta đã thảo luận trước đó, tôi cần máy được giao trước ngày 7 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"On May 8 we will celebrate the tenth anniversary of the café\'s opening.\", \"vi\": \"Vào ngày 8 tháng 5, chúng tôi sẽ tổ chức lễ kỷ niệm 10 năm ngày khai trương quán cà phê.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The espresso machine has always been our centerpiece.\", \"vi\": \"Máy pha cà phê espresso luôn là điểm nhấn chính của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"We use it on all our advertising.\", \"vi\": \"Chúng tôi sử dụng nó trong tất cả các chiến dịch quảng cáo của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Even without the nameplate, I need to have this vintage machine working for our celebrations.\", \"vi\": \"Dù không có bảng tên, tôi vẫn cần chiếc máy cổ điển này phải hoạt động tốt để phục vụ cho các buổi lễ kỷ niệm của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Stella\", \"vi\": \"Stella\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '937cfc37-2335-43af-ba20-0ee22dd000a7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"TBC Platinum Plan\\nAll live games, commercial-free - TBC Gold Plan\\nMost live games, commercial-free - TBC Silver Plan\\nMost live games played by a team of your choice - TBC Copper Plan\\nTBC game highlights\", \"vi\": \"Gói TBC Platinum\\nTất cả các trận đấu trực tiếp, không có quảng cáo - Gói TBC Gold\\nHầu hết các trận đấu trực tiếp, không có quảng cáo - Gói TBC Silver\\nHầu hết các trận đấu trực tiếp của đội bóng mà quý vị lựa chọn - Gói TBC Copper\\nNhững pha nổi bật của các trận đấu TBC\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Stream all games and commentary\\nWatch on up to three devices\\nIncludes nationally televised games\\n$29/month or $149/year - Stream games for any team\\nWatch on up to three devices\\nExcludes nationally televised games\\n$19/month or $99/year - Stream games played by your favorite TBC team\\nWatch on up to two devices\\nIncludes commercials\\nExcludes nationally televised games\\n$9/month or $49/year - Weekly replays of game highlights\\nWatch or download commentary shows\\nIncludes commercials\\nWatch on one device\\n$5/month or $29/year\", \"vi\": \"Xem trực tuyến tất cả các trận đấu và phần bình luận\\nXem trên tối đa ba thiết bị\\nBao gồm các trận đấu được phát sóng trên toàn quốc\\n29 USD/tháng hoặc 149 USD/năm – Xem trực tuyến các trận đấu của bất kỳ đội bóng nào\\nXem trên tối đa ba thiết bị\\nKhông bao gồm các trận đấu được phát sóng trên truyền hình toàn quốc\\n19 USD/tháng hoặc 99 USD/năm – Xem trực tuyến các trận đấu của đội TBC yêu thích của quý vị\\nXem trên tối đa hai thiết bị\\nBao gồm quảng cáo\\nKhông bao gồm các trận đấu được phát sóng trên truyền hình quốc gia\\n9 USD/tháng hoặc 49 USD/năm - Xem lại các pha nổi bật của trận đấu hàng tuần\\nXem hoặc tải xuống các chương trình bình luận\\nBao gồm quảng cáo\\nXem trên một thiết bị\\n5 USD/tháng hoặc 29 USD/năm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Watch the game you love for the price that’s right!\", \"vi\": \"Hãy thưởng thức trận đấu mà quý vị yêu thích với mức giá hợp lý!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Stream exciting, insightful content from the Total Basketball Channel (TBC) on your smartphone, tablet, or smart TV by subscribing to a TBC Plan!\", \"vi\": \"Hãy đăng ký gói dịch vụ TBC để thưởng thức những nội dung hấp dẫn và đầy ý nghĩa từ Kênh Total Basketball (TBC) trên điện thoại thông minh, máy tính bảng hoặc TV thông minh của quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Download the TBC app or visit www.totalbasketballchannel.com to sign up for one of the following subscription options.\", \"vi\": \"Hãy tải xuống ứng dụng TBC hoặc truy cập trang web www.totalbasketballchannel.com để đăng ký một trong các gói đăng ký sau đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}]' WHERE `id` = '9428c674-e4b7-43a1-b0f9-d3cb4b9f4c10';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Orinti Explains Web Site Updates\", \"vi\": \"Orinti giải thích về các bản cập nhật trang web\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"SAN DIEGO (May 2)—Orinti, Inc., one of North America\'s largest purveyors of tea, recently added a page to its Web site, listing the sources of all the tea leaves that end up in its final products.\", \"vi\": \"SAN DIEGO (ngày 2 tháng 5) — Orinti, Inc., một trong những nhà cung cấp trà lớn nhất Bắc Mỹ, gần đây đã bổ sung một trang trên trang web của mình, trong đó liệt kê nguồn gốc của tất cả các loại lá trà được sử dụng trong các sản phẩm cuối cùng của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The page was created in response to recent public scrutiny over whether the company is justified in claiming that its tea is pesticide-free.\", \"vi\": \"Trang này được tạo ra nhằm phản hồi trước những ý kiến giám sát gần đây của dư luận về việc liệu công ty có cơ sở để khẳng định rằng trà của họ không chứa thuốc trừ sâu hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"“The rumors being circulated do not reflect reality,” Orinti CEO Giovanni Shaw said in a public statement issued on Tuesday.\", \"vi\": \"“Những tin đồn đang lan truyền không phản ánh thực tế,” ông Giovanni Shaw, Giám đốc điều hành của Orinti, cho biết trong một tuyên bố công khai được phát đi vào thứ Ba.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"“We procure tea leaves only from producers who meet our strict quality standards.\", \"vi\": \"“Chúng tôi chỉ thu mua lá trà từ những nhà sản xuất đáp ứng các tiêu chuẩn chất lượng nghiêm ngặt của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We never settle for anything less.”\", \"vi\": \"“Chúng tôi không bao giờ chấp nhận những điều kém hơn thế.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"According to Mr. Shaw, the company also utilizes software that tracks the producer, the processing date, and other pertinent data for each batch of tea leaves.\", \"vi\": \"Theo ông Shaw, công ty còn sử dụng phần mềm để theo dõi nhà sản xuất, ngày chế biến và các dữ liệu liên quan khác đối với từng lô lá trà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"“This level of detail is not displayed on our packaging for the simple reason that we do not have the space for it,” said Mr. Shaw.\", \"vi\": \"“Mức độ chi tiết này không được thể hiện trên bao bì sản phẩm của chúng tôi vì một lý do đơn giản là chúng tôi không có đủ không gian để trình bày,” ông Shaw cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"“As we are committed to transparency, this information can be viewed on our Web site.”\", \"vi\": \"“Vì chúng tôi luôn cam kết đảm bảo tính minh bạch, quý vị có thể tra cứu thông tin này trên trang web của chúng tôi.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The popular blog foodnews.org was the first to call into question Orinti\'s assertion that its tea leaves are grown without the use of pesticides.\", \"vi\": \"Blog nổi tiếng foodnews.org là trang đầu tiên đặt ra nghi vấn về tuyên bố của Orinti rằng lá trà của công ty này được trồng mà không sử dụng thuốc trừ sâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The issue has since attracted national attention.\", \"vi\": \"Kể từ đó, vấn đề này đã thu hút sự chú ý trên toàn quốc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = '94394177-67f7-422b-939d-0e3ab694429f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Welcome to Dining-Ticket, the online service that delivers high-quality, delicious meals to your ______[131].\", \"vi\": \"Chào mừng bạn đến với Dining-Ticket, dịch vụ trực tuyến cung cấp các bữa ăn ngon, chất lượng cao đến ______[131] của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [131]}, {\"en\": \"To start ______[132] Dining-Ticket, simply enter your location to view your local delivery options.\", \"vi\": \"Để bắt đầu ______[132] Dining-Ticket, chỉ cần nhập vị trí của bạn để xem các tùy chọn giao hàng tại địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [132]}, {\"en\": \"Next, filter the information by your desired price range, cuisine type, or by the restaurant name.\", \"vi\": \"Tiếp theo, hãy lọc thông tin theo mức giá mong muốn, loại ẩm thực hoặc theo tên nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Then, track your order as it is transported by a Dining-Ticket delivery person.\", \"vi\": \"Sau đó, theo dõi đơn hàng của bạn khi nó được vận chuyển bởi nhân viên giao hàng của Dining-Ticket.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"______[133].\", \"vi\": \"______[133].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [133]}, {\"en\": \"To enjoy your favorite restaurant fare from the ______[134] of your own home, try Dining-Ticket today!\", \"vi\": \"Để thưởng thức các món ăn nhà hàng yêu thích từ sự ______[134] của chính ngôi nhà bạn, hãy dùng thử Dining-Ticket ngay hôm nay!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [134]}]' WHERE `id` = '9440a044-9f2c-4927-b97f-2a17edc20434';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Attention, Penny\'s Grill staff:\", \"vi\": \"Toàn thể nhân viên nhà hàng Penny\'s Grill chú ý:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The restaurant will be getting a new point-of-sale and order management system next week.\", \"vi\": \"Nhà hàng sẽ tiếp nhận hệ thống quản lý đơn hàng và điểm bán hàng mới vào tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Technicians will come on our weekly day off, Monday, to do the installation and ______[139] our managers how to use the system.\", \"vi\": \"Các kỹ thuật viên sẽ đến vào ngày nghỉ hàng tuần của chúng ta, tức thứ Hai, để tiến hành lắp đặt và ______[139] các quản lý của chúng ta cách sử dụng hệ thống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [139]}, {\"en\": \"Dana and Ivan will then lead simultaneous training sessions for all dining room and kitchen staff on Tuesday morning.\", \"vi\": \"Sau đó, Dana và Ivan sẽ chủ trì các buổi đào tạo đồng thời cho toàn bộ nhân viên phòng ăn và nhà bếp vào sáng thứ Ba.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"______[140].\", \"vi\": \"______[140].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [140]}, {\"en\": \"We need to get started that early in order to ensure that employees working normal shifts on Tuesday are fully prepared by the time lunch service ______[141] at 11.\", \"vi\": \"Chúng ta cần bắt đầu sớm như vậy để đảm bảo rằng các nhân viên làm ca thông thường vào thứ Ba được chuẩn bị đầy đủ vào thời điểm dịch vụ ăn trưa ______[141] lúc 11 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [141]}, {\"en\": \"Please let Dana know promptly if you are unavailable on Tuesday morning.\", \"vi\": \"Vui lòng thông báo ngay cho Dana biết nếu bạn không thể tham gia vào sáng thứ Ba.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We may arrange ______[142] training sessions if necessary.\", \"vi\": \"Chúng ta có thể sắp xếp ______[142] các buổi đào tạo nếu cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [142]}]' WHERE `id` = '94439c38-f65f-4bc2-9589-77f64fb07ee7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dalston Opera News\", \"vi\": \"Tin tức về Nhà hát Dalston\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Season Tickets Now Available\", \"vi\": \"Vé mùa hiện đã có sẵn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Purchase your season tickets now at www.dalstonopera.com/seasontickets.\", \"vi\": \"Hãy mua vé mùa ngay hôm nay tại www.dalstonopera.com/seasontickets.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"May 4–12: Sigrun (2 hours with 1 intermission)\", \"vi\": \"Ngày 4–12 tháng 5: Sigrun (2 giờ, bao gồm 1 lần giải lao)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"July 6–14: Le Lapin (3 hours with 2 intermissions)\", \"vi\": \"Ngày 6–14 tháng 7: Le Lapin (3 giờ, gồm 2 lần nghỉ giữa giờ)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"September 14–22: The Shipmaster\'s Garden (90 minutes with no intermission)\", \"vi\": \"Ngày 14–22 tháng 9: Vườn của Thuyền trưởng (90 phút, không có giờ nghỉ giữa giờ)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"November 30–December 8: Orkestia (4 hours with 3 intermissions)\", \"vi\": \"30 tháng 11 – 8 tháng 12: Orkestia (4 giờ, bao gồm 3 lần nghỉ giải lao)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Performances will take place at the Saloudi Auditorium beginning promptly at 8:00 P.M.\", \"vi\": \"Các buổi biểu diễn sẽ diễn ra tại Hội trường Saloudi và bắt đầu đúng 8 giờ tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Artist-in-Residence Series\", \"vi\": \"Chuỗi chương trình Nghệ sĩ lưu trú\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Our rotating artist-in-residence program aims to bring new voices into the performances of our regular cast.\", \"vi\": \"Chương trình nghệ sĩ lưu trú luân phiên của chúng tôi nhằm mục đích mang đến những giọng ca mới cho các buổi biểu diễn của dàn diễn viên thường trực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Join us for a special series of noon matinee performances by these artists and help us celebrate the next generation of talent coming into the field of opera from around the globe.\", \"vi\": \"Hãy cùng chúng tôi tham dự chuỗi buổi biểu diễn đặc biệt vào buổi trưa do các nghệ sĩ này trình diễn và cùng chúng tôi tôn vinh thế hệ tài năng mới đang gia nhập lĩnh vực opera từ khắp nơi trên thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Each performance will feature a medley of opera favorites selected and performed by one of our artists-in-residence.\", \"vi\": \"Mỗi buổi biểu diễn sẽ bao gồm một liên khúc các tác phẩm opera được yêu thích nhất, do một trong những nghệ sĩ thường trú của chúng tôi lựa chọn và trình diễn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"May 4: Diane Shimoda\", \"vi\": \"Ngày 4 tháng 5: Diane Shimoda\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"July 6: Kalim Patton\", \"vi\": \"Ngày 6 tháng 7: Kalim Patton\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"September 14: Claudia Godin\", \"vi\": \"Ngày 14 tháng 9: Claudia Godin\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"November 30: Nicolai Souza\", \"vi\": \"Ngày 30 tháng 11: Nicolai Souza\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '946ad803-fdd1-42f6-a13a-bc417189411f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"(May 2)—Automotive-manufacturing company Lybera, Inc., today announced that Harvey Ramirez has been appointed as the new chairperson of its board of directors.\", \"vi\": \"(Ngày 2 tháng 5)—Công ty sản xuất ô tô Lybera, Inc., hôm nay thông báo rằng Harvey Ramirez đã được bổ nhiệm làm chủ tịch hội đồng quản trị mới của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"He ______[135] Helen McGavick, who has resigned in order to pursue a new business venture.\", \"vi\": \"Ông ______[135] Helen McGavick, người đã từ chức để theo đuổi một dự án kinh doanh mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [135]}, {\"en\": \"\\\"We thank Ms. McGavick for her service and wish her success in her ______[136] endeavors,\\\" said Fen Wang, Lybera\'s president and CEO.\", \"vi\": \"\\\"Chúng tôi cảm ơn bà McGavick vì sự cống hiến của bà và chúc bà thành công trong các nỗ lực ______[136] của mình,\\\" Fen Wang, chủ tịch kiêm giám đốc điều hành của Lybera, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [136]}, {\"en\": \"Mr. Ramirez has spent ten years as CEO of aerospace-engineering firm Elia Aviation.\", \"vi\": \"Ông Ramirez đã có mười năm làm giám đốc điều hành của hãng kỹ thuật hàng không vũ trụ Elia Aviation.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"______[137], he held a variety of senior management roles across public and private sectors.\", \"vi\": \"______[137], ông từng nắm giữ nhiều vai trò quản lý cấp cao khác nhau trong cả khu vực công và tư nhân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [137]}, {\"en\": \"\\\"Mr. Ramirez\'s familiarity with sophisticated technology, combined with his leadership experience, makes him well suited to lead our company,\\\" said Mr. Wang.\", \"vi\": \"\\\"Sự am hiểu của ông Ramirez về công nghệ tiên tiến, kết hợp với kinh nghiệm lãnh đạo của ông, khiến ông rất phù hợp để dẫn dắt công ty chúng tôi,\\\" ông Wang cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"\\\"______[138].\\\"\", \"vi\": \"\\\"______[138].\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [138]}]' WHERE `id` = '9476cdb2-29dc-4f16-9bbe-95bf14a58f4e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Hannah Ward [2:01 P.M.] Before we begin our discussion about the upcoming meeting with Coral City government officials, I have some exciting news to report: one of our most recent designs, Chatillion House, will be featured in next month\'s issue of Residential Life.\", \"vi\": \"Hannah Ward [2 giờ 01 phút chiều] Trước khi chúng ta bắt đầu cuộc thảo luận về cuộc họp sắp tới với các quan chức chính quyền thành phố Coral City, tôi có một tin vui muốn chia sẻ: một trong những thiết kế mới nhất của chúng ta, Chatillion House, sẽ được giới thiệu trên số báo Residential Life tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Mahdi Naser [2:02 P.M.] Wow, that\'s excellent news!\", \"vi\": \"Mahdi Naser [2 giờ 02 phút chiều] Ôi, đó quả là một tin tuyệt vời!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I really enjoyed working on that assignment.\", \"vi\": \"Tôi thực sự rất thích thực hiện bài tập đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Elaine Lau [2:02 P.M.] Fantastic!\", \"vi\": \"Elaine Lau [2 giờ 02 phút chiều] Tuyệt vời!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"This will mean increased exposure for the firm.\", \"vi\": \"Điều này sẽ giúp công ty được biết đến rộng rãi hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Mahdi Naser [2:03 P.M.] My thoughts exactly.\", \"vi\": \"Mahdi Naser [2 giờ 03 phút chiều] Tôi cũng nghĩ y như vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The magazine has a readership that spans many countries.\", \"vi\": \"Tạp chí này có độc giả trải rộng trên nhiều quốc gia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Hannah Ward [2:04 P.M.] Let\'s not forget the magnificent job that the people from Vistarama did.\", \"vi\": \"Hannah Ward [2 giờ 04 phút chiều] Xin đừng quên thành quả tuyệt vời mà đội ngũ Vistarama đã đạt được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Elaine Lau [2:05 P.M.] That company has become vital to our work.\", \"vi\": \"Elaine Lau [2 giờ 05 phút chiều] Công ty đó đã trở thành một phần không thể thiếu trong công việc của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Hannah Ward [2:07 P.M.] Particularly since we wanted the house to blend in with the greenery that adorns the neighborhood.\", \"vi\": \"Hannah Ward [2 giờ 07 phút chiều] Đặc biệt là vì chúng tôi mong muốn ngôi nhà hòa nhập với khung cảnh cây cối xanh tươi tô điểm cho khu phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Using a variety of plants, trees, and flowers, the crew from Vistarama created a scenery that is absolutely stunning.\", \"vi\": \"Bằng cách sử dụng nhiều loại cây cối, cây cảnh và hoa khác nhau, đội ngũ của Vistarama đã tạo nên một khung cảnh thực sự tuyệt đẹp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Mahdi Naser [2:08 P.M.] Yes, the area that surrounds the house looks absolutely fabulous.\", \"vi\": \"Mahdi Naser [2 giờ 08 phút chiều] Vâng, khu vực xung quanh ngôi nhà trông thực sự tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Hannah Ward [2:08 P.M.] OK, let\'s move on.\", \"vi\": \"Hannah Ward [2 giờ 08 phút chiều] Được rồi, chúng ta hãy tiếp tục.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Elaine, any new information about the requirements for Coral City\'s new courthouse?\", \"vi\": \"Thưa bà Elaine, có thông tin mới nào về các yêu cầu đối với tòa án mới của thành phố Coral City không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Elaine Lau [2:09 P.M.] Yes, there is.\", \"vi\": \"Elaine Lau [2 giờ 09 phút chiều] Vâng, có đấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"This morning I discussed them with Jerica Ogilvie, a city official.\", \"vi\": \"Sáng nay, tôi đã trao đổi về những vấn đề này với bà Jerica Ogilvie, một quan chức thành phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I\'ll go over them with you right away.\", \"vi\": \"Tôi sẽ cùng quý vị xem xét ngay những nội dung đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '94996dcc-83fa-4668-beec-d50762ac0725';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: a.raman@bgi.co.in\", \"vi\": \"Gửi tới: a.raman@bgi.co.in\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: s.kapoor@imail.co.in\", \"vi\": \"Nguồn: s.kapoor@imail.co.in\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 15 April\", \"vi\": \"Ngày: 15 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Thank-you note\", \"vi\": \"Chủ đề: Thư cảm ơn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Raman,\", \"vi\": \"Kính gửi ông Raman,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thanks for encouraging me to apply for the position at Neela Advertising and for writing such a glowing referral on my behalf.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã động viên tôi nộp đơn ứng tuyển vào vị trí tại Công ty Quảng cáo Neela và đã viết thư giới thiệu hết lời khen ngợi cho tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Mr. Nirmal, Neela\'s chief recruiting officer, expressed his admiration for the television commercials I produced for Delhi Works, but he explained that his company in fact needs someone who can also create Web content and applications.\", \"vi\": \"Ông Nirmal, Giám đốc Tuyển dụng của Neela, đã bày tỏ sự ngưỡng mộ đối với các quảng cáo truyền hình mà tôi đã sản xuất cho Delhi Works, nhưng ông giải thích rằng trên thực tế, công ty của ông cần một người có thể vừa sáng tạo nội dung web vừa phát triển ứng dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I was therefore not offered the position.\", \"vi\": \"Do đó, tôi đã không được đề nghị nhận vị trí này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Kindly let me know if you happen to hear of any other positions that might be a good fit for me.\", \"vi\": \"Nếu quý vị tình cờ nghe nói về bất kỳ vị trí nào khác có thể phù hợp với tôi, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Thank you in advance.\", \"vi\": \"Xin chân thành cảm ơn trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Shreya\", \"vi\": \"Shreya\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"17 May\", \"vi\": \"Ngày 17 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Shreya Kapoor\", \"vi\": \"Shreya Kapoor\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"21 Hammam Street\", \"vi\": \"Số 21, đường Hammam\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Mumbai\", \"vi\": \"Mumbai\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Dear Ms. Kapoor,\", \"vi\": \"Kính gửi bà Kapoor,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I am pleased that you will be joining Mumbai Canning Ltd. on 1 June.\", \"vi\": \"Tôi rất vui mừng khi biết quý vị sẽ gia nhập Công ty Mumbai Canning Ltd. vào ngày 1 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I was impressed with the knowledge you displayed at the time you interviewed at our offices.\", \"vi\": \"Tôi đã rất ấn tượng với kiến thức mà quý vị đã thể hiện trong buổi phỏng vấn tại văn phòng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Your specific experience at Delhi Works, Inc., will be of tremendous value here.\", \"vi\": \"Kinh nghiệm cụ thể của quý vị tại Delhi Works, Inc. sẽ có giá trị vô cùng to lớn tại đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I am enclosing some documents that you should complete, sign, and bring with you when you report to Human Resources at 9:30 A.M. on your first day.\", \"vi\": \"Tôi xin gửi kèm theo đây một số tài liệu mà quý vị cần điền đầy đủ thông tin, ký tên và mang theo khi đến trình diện tại Phòng Nhân sự vào lúc 9 giờ 30 sáng trong ngày làm việc đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"You will receive a brief administrative orientation at that time.\", \"vi\": \"Vào thời điểm đó, quý vị sẽ được tham gia một buổi hướng dẫn ngắn gọn về các thủ tục hành chính.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Your assigned mentor, Ms. Meera Sethi, will meet you there at 10:30 to escort you to your department, where she will review your training plan and the projects the team is currently working on.\", \"vi\": \"Người hướng dẫn được chỉ định cho quý vị, bà Meera Sethi, sẽ gặp quý vị tại đó vào lúc 10 giờ 30 để dẫn quý vị đến phòng ban của quý vị; tại đó, bà sẽ xem xét kế hoạch đào tạo của quý vị cũng như các dự án mà nhóm đang thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"At noon she will be taking you to our cafeteria for lunch in the company of some of your colleagues.\", \"vi\": \"Vào buổi trưa, cô ấy sẽ đưa quý vị đến căng-tin của chúng tôi để dùng bữa trưa cùng một số đồng nghiệp của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I hope to join you there as well.\", \"vi\": \"Tôi cũng hy vọng sẽ được tham gia cùng quý vị tại đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Welcome to Mumbai Canning Ltd.!\", \"vi\": \"Chào mừng quý vị đến với Công ty TNHH Mumbai Canning!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Zara Mehta\", \"vi\": \"Zara Mehta\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Zara Mehta\", \"vi\": \"Zara Mehta\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Mumbai Canning Ltd.\", \"vi\": \"Công ty TNHH Mumbai Canning\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"To: a.raman@bgi.co.in\", \"vi\": \"Gửi tới: a.raman@bgi.co.in\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"From: s.kapoor@imail.co.in\", \"vi\": \"Nguồn: s.kapoor@imail.co.in\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Date: 20 May\", \"vi\": \"Ngày: 20 tháng 5\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Subject: Good news\", \"vi\": \"Chủ đề: Tin vui\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Dear Mr. Raman,\", \"vi\": \"Kính gửi ông Raman,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Thank you for your last referral.\", \"vi\": \"Xin chân thành cảm ơn quý vị về lời giới thiệu gần đây nhất.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"The director offered me the position during our interview, and I will be starting on 1 June.\", \"vi\": \"Giám đốc đã đề nghị tôi nhận vị trí này trong buổi phỏng vấn, và tôi sẽ bắt đầu công việc vào ngày 1 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"I will be happy to provide you with details about my duties once I get settled.\", \"vi\": \"Tôi sẽ rất hân hạnh được cung cấp cho quý vị thông tin chi tiết về các nhiệm vụ của tôi ngay khi tôi đã ổn định công việc.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Shreya\", \"vi\": \"Shreya\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}]' WHERE `id` = '9535b3b7-d003-4805-ac3f-38c09ac0e799';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business.\", \"vi\": \"Hãy đến Trung tâm Làm vườn Maxley Heights và học cách tạo ra một khu vườn đẹp, thân thiện với môi trường cho ngôi nhà hoặc doanh nghiệp của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"____131____.\", \"vi\": \"____131____.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"We will teach you how to plant a rain garden, which is simply a shallow sunken garden ____132____ a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops.\", \"vi\": \"Chúng tôi sẽ hướng dẫn bạn cách trồng một khu vườn mưa, vốn đơn giản là một khu vườn trũng nông ____132____ một hỗn hợp đất đặc biệt để lọc các chất ô nhiễm từ nước mưa chảy từ các con đường và mái nhà gần đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132]}, {\"en\": \"These gardens can be landscaped with native plants and flowers.\", \"vi\": \"Những khu vườn này có thể được tạo cảnh bằng các loại cây và hoa bản địa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"____133____ , rain gardens are always beneficial to the local environment.\", \"vi\": \"____133____ , vườn mưa luôn mang lại lợi ích cho môi trường địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [133]}, {\"en\": \"Among other things, ____134____ improve drainage and protect rivers and streams.\", \"vi\": \"Trong số những lợi ích khác, ____134____ cải thiện khả năng thoát nước và bảo vệ các con sông và suối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [134]}, {\"en\": \"To register, visit www.maxley-horticulture.org.\", \"vi\": \"Để đăng ký, hãy truy cập www.maxley-horticulture.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '9539bdc1-c088-4e12-bc2a-0a745422bb4d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Commbolt is for Everyone!\", \"vi\": \"Commbolt dành cho tất cả mọi người!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"As a Commbolt customer, you\'ve come to expect the best in reliable high-speed Internet, straightforward pricing options, and top-notch customer service from friendly professionals who are responsive to your every need.\", \"vi\": \"Với tư cách là khách hàng của Commbolt, quý vị đã quen với việc được hưởng dịch vụ Internet tốc độ cao đáng tin cậy hàng đầu, các gói cước đơn giản và minh bạch, cùng dịch vụ chăm sóc khách hàng đẳng cấp từ đội ngũ chuyên viên thân thiện, luôn sẵn sàng đáp ứng mọi nhu cầu của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Unlike the competition, we promise to never lock you into inflexible contracts or suddenly raise your monthly bill without notice.\", \"vi\": \"Khác với các đối thủ cạnh tranh, chúng tôi cam kết sẽ không bao giờ buộc quý khách phải ký kết các hợp đồng cứng nhắc hay đột ngột tăng cước phí hàng tháng mà không có thông báo trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"At Commbolt, we know you have options when it comes to choosing an Internet service provider.\", \"vi\": \"Tại Commbolt, chúng tôi hiểu rằng quý vị có nhiều sự lựa chọn khi quyết định chọn nhà cung cấp dịch vụ Internet.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To show our gratitude for your loyalty, we are offering a special limited-time referral bonus.\", \"vi\": \"Để bày tỏ lòng biết ơn đối với sự trung thành của quý khách, chúng tôi xin dành tặng chương trình thưởng giới thiệu đặc biệt có thời hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The way it works is simple.\", \"vi\": \"Cách thức hoạt động của nó rất đơn giản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You can use e-mail, social media, or even text messages to tell everyone about Commbolt.\", \"vi\": \"Quý vị có thể sử dụng email, mạng xã hội hoặc thậm chí là tin nhắn văn bản để giới thiệu Commbolt đến mọi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"When a new user signs up using your code, each of you will receive a monetary credit.\", \"vi\": \"Khi một người dùng mới đăng ký bằng mã giới thiệu của quý vị, cả hai bên sẽ đều nhận được một khoản tín dụng tiền mặt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Receive $10 when new referrals sign up for a monthly plan at $45, and receive $20 for a plan costing $60 per month.\", \"vi\": \"Quý vị sẽ nhận được 10 đô la khi những người được giới thiệu mới đăng ký gói cước hàng tháng với mức phí 45 đô la, và nhận được 20 đô la khi họ đăng ký gói cước có mức phí 60 đô la mỗi tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The best news?\", \"vi\": \"Tin vui nhất là gì?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"There is no limit to the credits; the more people you sign up, the more money you get.\", \"vi\": \"Không có giới hạn về số điểm thưởng; quý vị giới thiệu được càng nhiều người đăng ký, quý vị sẽ nhận được càng nhiều tiền.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Your unique code is XA4R177.\", \"vi\": \"Mã duy nhất của quý vị là XA4R177.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '95481c31-f535-43d6-b0e5-43cea7cf8037';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"LOS ANGELES (May 3)—Connection Studios has hired Australian Lucas Pearce to direct its upcoming film Black Door.\", \"vi\": \"LOS ANGELES (ngày 3 tháng 5) — Connection Studios đã mời ông Lucas Pearce, người Úc, đảm nhận vai trò đạo diễn cho bộ phim sắp ra mắt của hãng mang tên *Black Door*.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Mr. Pearce gained widespread attention this spring with his debut feature, The Farm, a terrifying ghost tale that received glowing reviews.\", \"vi\": \"Mùa xuân năm nay, ông Pearce đã thu hút sự chú ý rộng rãi nhờ bộ phim điện ảnh đầu tay của mình, *The Farm* — một câu chuyện ma rùng rợn đã nhận được những lời khen ngợi nồng nhiệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Black Door, which will star Tamara Burns, is a psychological thriller set in a hospital.\", \"vi\": \"Bộ phim “Black Door”, với sự tham gia của nữ diễn viên Tamara Burns, là một bộ phim kinh dị tâm lý lấy bối cảnh tại một bệnh viện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"With a budget of $8 million, it represents a significant increase in scale for Mr. Pearce, as The Farm reportedly cost just $700,000 to make.\", \"vi\": \"Với ngân sách 8 triệu đô la, bộ phim này đánh dấu một bước nhảy vọt đáng kể về quy mô đối với ông Pearce, bởi theo báo cáo, chi phí sản xuất bộ phim *The Farm* chỉ vỏn vẹn 700.000 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"According to the press release issued by Connection, Black Door will begin shooting in November and is scheduled to arrive in theaters in October of next year.\", \"vi\": \"Theo thông cáo báo chí do Connection phát hành, bộ phim “Black Door” sẽ bắt đầu quay vào tháng 11 và dự kiến sẽ ra rạp vào tháng 10 năm sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The studio also indicated plans to screen the film a few months earlier at the Fleming Film Festival that summer, presumably hoping that positive reviews from attendees will build anticipation among audiences.\", \"vi\": \"Hãng phim này cũng cho biết có kế hoạch công chiếu bộ phim sớm hơn vài tháng tại Liên hoan phim Fleming vào mùa hè năm đó, có lẽ với hy vọng rằng những đánh giá tích cực từ khán giả tham dự sự kiện sẽ góp phần khơi dậy sự mong đợi trong lòng công chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To: lucas.pearce@sno-mail.com\", \"vi\": \"Gửi tới: lucas.pearce@sno-mail.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"From: gloria.ingram@connectionstudios.com\", \"vi\": \"Nguồn: gloria.ingram@connectionstudios.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Date: August 29\", \"vi\": \"Ngày: 29 tháng 8\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Subject: Black Door\", \"vi\": \"Chủ đề: Cánh cửa màu đen\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Feedback\", \"vi\": \"Tệp đính kèm: 📎 Phản hồi\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Dear Lucas,\", \"vi\": \"Kính gửi Lucas,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"My assistant has compiled the attached feedback on Black Door from those who attended its premiere screening at the Sutton Film Festival.\", \"vi\": \"Trợ lý của tôi đã tổng hợp các ý kiến phản hồi kèm theo đây về bộ phim *Black Door* từ những người đã tham dự buổi chiếu ra mắt tại Liên hoan phim Sutton.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"It includes official reviews as well as social media reactions from influential members of the industry.\", \"vi\": \"Nội dung này bao gồm các bài đánh giá chính thức cũng như những phản hồi trên mạng xã hội từ các nhân vật có ảnh hưởng trong ngành.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"As you may already know, there was a lot of praise for the movie\'s sense of atmosphere, but also widespread agreement that its pace is sluggish.\", \"vi\": \"Như quý vị có lẽ đã biết, bộ phim đã nhận được rất nhiều lời khen ngợi về bầu không khí mà nó tạo ra, song cũng có sự đồng thuận rộng rãi rằng nhịp độ của bộ phim khá chậm chạp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Several people mentioned that the scenes about the main character\'s son, in particular, take up a lot of time without being relevant to the plot.\", \"vi\": \"Một số người đã đề cập rằng các phân cảnh liên quan đến con trai của nhân vật chính, đặc biệt là những phân cảnh này, chiếm khá nhiều thời lượng mà lại không liên quan đến cốt truyện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Given this response, we would like you to work with the editor to cut as many of those scenes as possible.\", \"vi\": \"Trước phản hồi này, chúng tôi mong quý vị phối hợp với biên tập viên để cắt bớt càng nhiều cảnh đó càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"When you\'re finished, I\'ll arrange a test screening for the other producers and studio executives.\", \"vi\": \"Khi quý vị hoàn tất, tôi sẽ sắp xếp một buổi chiếu thử cho các nhà sản xuất khác và các lãnh đạo hãng phim.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I hope that you\'ll be able to work quickly and that no additional filming will be necessary.\", \"vi\": \"Tôi hy vọng quý vị sẽ có thể hoàn thành công việc một cách nhanh chóng và không cần phải quay bổ sung thêm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"We want to keep our scheduled release date of October 7 so that Black Door will have a full week in theaters before Artifact comes out, as there are rumors that it will be stiff competition for us.\", \"vi\": \"Chúng tôi mong muốn duy trì ngày công chiếu dự kiến là ngày 7 tháng 10 để bộ phim *Black Door* có thể trình chiếu tại các rạp trong trọn vẹn một tuần trước khi bộ phim *Artifact* ra mắt, bởi có những tin đồn cho rằng bộ phim này sẽ là đối thủ cạnh tranh đáng gờm đối với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Gloria Ingram\", \"vi\": \"Vinh quang của Đức Chúa Trời\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Senior Vice President of Production, Connection Studios\", \"vi\": \"Phó Chủ tịch Cấp cao phụ trách Sản xuất, Connection Studios\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '956f3d43-fc4d-459a-82ce-ed77ebffc2d8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Item - Price\", \"vi\": \"Sản phẩm - Giá\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Garden soil, 33 cubic meters - $1,170.00\", \"vi\": \"Đất làm vườn, 33 mét khối - 1.170,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Crushed gravel, 30 metric tons - 1,710.00\", \"vi\": \"Sỏi nghiền, 30 tấn mét - 1.710,00\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Decorative stone, 20 metric tons - 1,140.00\", \"vi\": \"Đá trang trí, 20 tấn - 1.140,00\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"70 paving stones, .6 x .6 meters - 630.00\", \"vi\": \"70 viên đá lát, kích thước 0,6 x 0,6 mét - 630,00\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Subtotal - 4,650.00\", \"vi\": \"Tổng phụ - 4.650,00\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Discount (10%) - 465.00\", \"vi\": \"Giảm giá (10%) - 465,00\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Delivery charge - 350.00\", \"vi\": \"Phí vận chuyển - 350,00\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Grand Total - 4,535.00\", \"vi\": \"Tổng cộng - 4.535,00\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Orbys Distributors\", \"vi\": \"Các nhà phân phối của Orbys\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Client: Green Canyon     Date: June 10\", \"vi\": \"Khách hàng: Green Canyon     Ngày: 10 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Account: 4352-0\", \"vi\": \"Số tài khoản: 4352-0\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Please see the enclosed notice outlining important changes to your billing.\", \"vi\": \"Kính mời quý vị tham khảo thông báo đính kèm nêu rõ những thay đổi quan trọng liên quan đến việc thanh toán của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Orbys Distributors\", \"vi\": \"Các nhà phân phối của Orbys\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To our valued customers:\", \"vi\": \"Kính gửi quý khách hàng thân mến:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago.\", \"vi\": \"Hệ thống lập hóa đơn hiện tại của chúng tôi đã được đưa vào sử dụng kể từ khi Công ty Phân phối Orbys được thành lập cách đây hơn hai mươi năm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"As a much-needed upgrade, we are switching to electronic invoicing.\", \"vi\": \"Nhằm thực hiện một bước cải tiến rất cần thiết, chúng tôi sẽ chuyển sang sử dụng hóa đơn điện tử.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Starting August 1, invoices will be generated automatically each month and will be sent to the e-mail address associated with your company\'s account.\", \"vi\": \"Kể từ ngày 1 tháng 8, các hóa đơn sẽ được tạo tự động hàng tháng và được gửi đến địa chỉ email liên kết với tài khoản của công ty quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Rest assured that our long-standing incentives remain in place:\", \"vi\": \"Xin quý vị hãy yên tâm rằng các chính sách ưu đãi lâu dài của chúng tôi vẫn tiếp tục được duy trì:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"A 10% discount for orders of more than $4,000\", \"vi\": \"Giảm giá 10% cho các đơn hàng có giá trị trên 4.000 đô la\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"A 20% discount for charitable organizations\", \"vi\": \"Giảm giá 20% dành cho các tổ chức từ thiện\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Free deliveries to locations within 5 miles of one of our supply centers\", \"vi\": \"Miễn phí giao hàng đến các địa điểm nằm trong phạm vi 5 dặm tính từ một trong các trung tâm cung ứng của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Free samples for members of our Frequent Buyer Club\", \"vi\": \"Quà tặng mẫu miễn phí dành cho các thành viên của Câu lạc bộ Khách hàng Thường xuyên của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"More information about our transition to electronic invoicing is available on our Web site.\", \"vi\": \"Quý vị có thể tham khảo thêm thông tin về quá trình chuyển đổi sang hình thức hóa đơn điện tử của chúng tôi trên trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Thank you for your support.\", \"vi\": \"Xin chân thành cảm ơn sự ủng hộ của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Orbys Distributors appreciates your business.\", \"vi\": \"Công ty Orbys Distributors xin chân thành cảm ơn quý khách đã tin tưởng và ủng hộ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"To: Mary Peterson, Billing Department\", \"vi\": \"Kính gửi: Bà Mary Peterson, Phòng Kế toán\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"From: Tanvir Singh, Account Manager\", \"vi\": \"Từ: Tanvir Singh, Quản lý Tài khoản\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Date: September 12\", \"vi\": \"Ngày: 12 tháng 9\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Subject: Account 1012-4\", \"vi\": \"Chủ đề: Tài khoản 1012-4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Hello Mary,\", \"vi\": \"Xin chào Mary,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I received a query today from William Tesoriero at Tesoriero Remodeling.\", \"vi\": \"Hôm nay, tôi đã nhận được một yêu cầu từ ông William Tesoriero thuộc công ty Tesoriero Remodeling.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"His monthly invoice for August never arrived.\", \"vi\": \"Hóa đơn hàng tháng của ông ấy cho tháng Tám vẫn chưa được gửi đến.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"As you know, Mr. Tesoriero was one of our very first customers.\", \"vi\": \"Như quý vị đã biết, ông Tesoriero là một trong những khách hàng đầu tiên của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Since we first opened for business, he has made purchases from us on a regular basis.\", \"vi\": \"Kể từ khi chúng tôi chính thức đi vào hoạt động, ông ấy đã thường xuyên mua hàng tại cửa hàng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"He is also a member of the Frequent Buyer Club.\", \"vi\": \"Ông cũng là thành viên của Câu lạc bộ Khách hàng Thường xuyên.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"This is a customer we absolutely do not want to lose.\", \"vi\": \"Đây là một khách hàng mà chúng tôi tuyệt đối không muốn để mất.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again.\", \"vi\": \"Tôi đã giải thích với ông ấy rằng việc triển khai hệ thống hóa đơn điện tử của chúng tôi đã không diễn ra suôn sẻ như chúng tôi mong đợi và cam kết rằng điều này sẽ không xảy ra lần nữa.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.\", \"vi\": \"Tôi sẽ rất cảm kích nếu quý vị có thể khẩn trương làm rõ vấn đề này và gửi hóa đơn tháng 8 cho ông Tesoriero.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Tanvir\", \"vi\": \"Ánh sáng\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}]' WHERE `id` = '95f6afad-e3d4-4b21-b335-a17084e696ef';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: cbeker@yourworkstyle.net\", \"vi\": \"Nguồn: cbeker@yourworkstyle.net\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: lroytenberg@charlottes.com; ajordan@charlottes.com\", \"vi\": \"Gửi tới: lroytenberg@charlottes.com; ajordan@charlottes.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: January 27, 10:02 A.M.\", \"vi\": \"Ngày: 27 tháng 1, 10 giờ 02 phút sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: First draft of press release\", \"vi\": \"Chủ đề: Bản thảo đầu tiên của thông cáo báo chí\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Press release draft\", \"vi\": \"Tài liệu đính kèm: Bản dự thảo thông cáo báo chí\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Roytenberg and Ms. Jordan,\", \"vi\": \"Kính gửi ông Roytenberg và bà Jordan,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"My first draft of the press release is attached.\", \"vi\": \"Bản nháp đầu tiên của thông cáo báo chí được đính kèm dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As we previously discussed by phone, my contract includes one additional half-hour meeting to discuss the project and any changes you would like me to make before I submit the press release to my contacts at Pinetown Weekly.\", \"vi\": \"Như chúng ta đã trao đổi qua điện thoại trước đây, hợp đồng của tôi bao gồm một cuộc họp thêm kéo dài nửa giờ để thảo luận về dự án cũng như bất kỳ thay đổi nào mà quý vị mong muốn tôi thực hiện trước khi tôi gửi thông cáo báo chí đến các đối tác của tôi tại Pinetown Weekly.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please let me know if I can stop by this week.\", \"vi\": \"Xin vui lòng cho tôi biết liệu tôi có thể ghé qua trong tuần này hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I would like to take photos of the space.\", \"vi\": \"Tôi muốn chụp ảnh không gian này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I remember your mentioning that the historic architecture of the building would be a draw for customers.\", \"vi\": \"Tôi nhớ là quý vị đã đề cập rằng kiến trúc lịch sử của tòa nhà sẽ là một điểm thu hút khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"In addition, I will need to get a direct quotation from either of you or from Chef Vaux.\", \"vi\": \"Ngoài ra, tôi sẽ cần nhận được báo giá trực tiếp từ một trong hai quý vị hoặc từ Bếp trưởng Vaux.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I know from working with Pinetown Weekly in the past that they will not run a piece like this without at least one quotation.\", \"vi\": \"Dựa trên kinh nghiệm hợp tác với tờ Pinetown Weekly trong quá khứ, tôi biết rằng họ sẽ không đăng tải một bài viết như thế này nếu không có ít nhất một trích dẫn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Cathy Beker\", \"vi\": \"Cathy Beker\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"– DRAFT –\", \"vi\": \"– BẢN NHÁP –\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Charlotte\'s Opens for Business\", \"vi\": \"Charlotte\'s chính thức đi vào hoạt động\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Charlotte\'s, located at Avenue D and Oak Street, will open its doors on Friday, February 5.\", \"vi\": \"Charlotte\'s, tọa lạc tại giao lộ Avenue D và Oak Street, sẽ chính thức khai trương vào thứ Sáu, ngày 5 tháng 2.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Owners Levon Roytenberg and Aubree Jordan are excited to welcome patrons for an aromatic cup of coffee or steaming espresso, specialty pastries, and savory café fare.\", \"vi\": \"Hai chủ quán Levon Roytenberg và Aubree Jordan rất hân hoan chào đón quý khách đến thưởng thức một tách cà phê thơm lừng hay ly espresso nóng hổi, cùng các loại bánh ngọt đặc biệt và các món ăn nhẹ ngon miệng tại quán.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Their aim is for Charlotte\'s to be a gathering place that indulges all the senses, where guests will be met with comfort and hospitality.\", \"vi\": \"Mục tiêu của họ là biến Charlotte\'s trở thành một điểm hẹn mang đến những trải nghiệm trọn vẹn cho tất cả các giác quan, nơi quý khách sẽ được đón tiếp trong không gian thoải mái và đầy lòng hiếu khách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Award-winning executive chef Michel Vaux, most recently of Kahn\'s in Bloomington, has created an enticing menu featuring fresh-baked breads and grass-fed meats, with locally sourced vegetable dishes as accompaniments.\", \"vi\": \"Đầu bếp điều hành từng đoạt giải thưởng Michel Vaux, người gần đây nhất từng làm việc tại nhà hàng Kahn\'s ở Bloomington, đã sáng tạo ra một thực đơn hấp dẫn với các loại bánh mì mới ra lò và các món thịt từ gia súc được nuôi bằng cỏ, kèm theo các món rau củ có nguồn gốc từ địa phương.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Offerings will include breakfast and lunch selections.\", \"vi\": \"Các món ăn được phục vụ sẽ bao gồm các lựa chọn cho bữa sáng và bữa trưa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Chef Vaux will also bring to Charlotte\'s his elegant hot and cold beverages utilizing teas and herbal infusions.\", \"vi\": \"Đầu bếp Vaux cũng sẽ mang đến Charlotte’s những loại đồ uống nóng và lạnh sang trọng, được chế biến từ trà và các loại thảo mộc ngâm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"From: ajordan@charlottes.com\", \"vi\": \"Nguồn: ajordan@charlottes.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"To: cbeker@yourworkstyle.net\", \"vi\": \"Gửi tới: cbeker@yourworkstyle.net\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Cc: lroytenberg@charlottes.com\", \"vi\": \"Cc: lroytenberg@charlottes.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date: January 28, 8:34 A.M.\", \"vi\": \"Ngày: 28 tháng 1, 8 giờ 34 phút sáng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Subject: RE: First draft of press release\", \"vi\": \"Chủ đề: RE: Bản thảo đầu tiên của thông cáo báo chí\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Hi Ms. Beker,\", \"vi\": \"Kính gửi bà Beker,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Mr. Roytenberg is in Boston for the next several days, and he has asked me to take the lead on the press release.\", \"vi\": \"Ông Roytenberg sẽ có mặt tại Boston trong vài ngày tới, và ông đã đề nghị tôi chủ trì việc soạn thảo thông cáo báo chí.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I know you had asked to come by the site—are you available tomorrow, January 29, at 3:00 P.M.? I will be there all day decorating for the grand opening.\", \"vi\": \"Tôi biết quý vị đã đề nghị ghé qua địa điểm này — không biết ngày mai, 29 tháng 1, lúc 3 giờ chiều, quý vị có rảnh không? Tôi sẽ có mặt ở đó cả ngày để trang trí cho lễ khai trương.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"You have put together an excellent first draft.\", \"vi\": \"Quý vị đã soạn thảo được một bản nháp đầu tiên rất xuất sắc.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"The only major problem I see is that you have mixed up the location of our corporate office and the café.\", \"vi\": \"Vấn đề lớn duy nhất mà tôi nhận thấy là quý vị đã nhầm lẫn giữa địa điểm của văn phòng công ty chúng tôi với quán cà phê.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"The café is actually on the corner of Avenue C and Maple Street.\", \"vi\": \"Quán cà phê này thực ra nằm ở góc đường Avenue C và Maple Street.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Also, Mr. Roytenberg would like to include the operating hours, which are 8:00 A.M. to 4:00 P.M. daily.\", \"vi\": \"Ngoài ra, ông Roytenberg mong muốn bổ sung thông tin về giờ làm việc, cụ thể là từ 8 giờ sáng đến 4 giờ chiều hàng ngày.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Please call Chef Vaux at 952-555-0133 for a quotation about specialty items on the menu.\", \"vi\": \"Kính mời quý vị liên hệ với Bếp trưởng Vaux theo số 952-555-0133 để nhận báo giá về các món đặc biệt trong thực đơn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"All my best,\", \"vi\": \"Xin gửi lời chúc tốt đẹp nhất,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Aubree Jordan\", \"vi\": \"Aubree Jordan\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}]' WHERE `id` = '95f7eb9c-1e95-4534-a2ad-ca69a384e793';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"How to Connect Your New Apereta Modem\", \"vi\": \"Cách kết nối modem Apereta mới của quý vị\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Use this insert as a form to keep track of your installation information and progress.\", \"vi\": \"Xin vui lòng sử dụng tờ đính kèm này như một biểu mẫu để theo dõi thông tin và tiến độ lắp đặt của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"First, plug the black AC adaptor into a wall outlet and then connect it to the first port on your modem, labeled \\\"Power.\\\"\", \"vi\": \"Trước tiên, hãy cắm bộ chuyển đổi nguồn màu đen vào ổ cắm trên tường, sau đó kết nối nó với cổng đầu tiên trên modem của quý vị, có ghi \\\"Power\\\".\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Next, plug one end of the blue cable into a wall-mounted phone jack near your modem.\", \"vi\": \"Tiếp theo, hãy cắm một đầu của dây cáp màu xanh vào ổ cắm điện thoại gắn tường gần modem của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Plug the other end into the second port on your modem, labeled \\\"Service.\\\"\", \"vi\": \"Hãy cắm đầu còn lại vào cổng thứ hai trên modem của quý vị, có ghi chữ “Service”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Finally, plug the red cable into a USB port in your computer.\", \"vi\": \"Cuối cùng, hãy cắm dây màu đỏ vào cổng USB trên máy tính của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Then plug the other end into the third port on your modem, labeled \\\"Computer.\\\"\", \"vi\": \"Sau đó, hãy cắm đầu còn lại vào cổng thứ ba trên modem của quý vị, có nhãn “Computer.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Open an Internet browser.\", \"vi\": \"Mở trình duyệt Internet.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The Apereta home page should load automatically.\", \"vi\": \"Trang chủ của Apereta sẽ tự động tải.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Click the \\\"Agree\\\" button to be guided through the sign-up process.\", \"vi\": \"Vui lòng nhấp vào nút “Đồng ý” để được hướng dẫn thực hiện quy trình đăng ký.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"When you are finished, you will be e-mailed a Web link with your service password.\", \"vi\": \"Khi quý vị hoàn tất, quý vị sẽ nhận được một liên kết trang web kèm theo mật khẩu dịch vụ của mình qua email.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Note your password here: Rt17ya-52p\", \"vi\": \"Hãy ghi lại mật khẩu của quý vị tại đây: Rt17ya-52p\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To reset your service password, click the \\\"Reset\\\" button at the bottom of the sign-in page, then enter a password of your choice.\", \"vi\": \"Để đặt lại mật khẩu dịch vụ, quý vị hãy nhấp vào nút “Đặt lại” ở cuối trang đăng nhập, sau đó nhập mật khẩu mà quý vị muốn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Note your new password here: __________\", \"vi\": \"Vui lòng ghi lại mật khẩu mới của quý vị tại đây: __________\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '960a0bf9-fdf7-4723-b9d1-5969f5bf1591';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Castak Recruiting: What We Do\", \"vi\": \"Tuyển dụng Castak: Chúng tôi làm gì\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Since we started our operations more than ten years ago, we have helped countless job seekers find employment ___139____ our online listings of job openings.\", \"vi\": \"Kể từ khi bắt đầu hoạt động hơn mười năm trước, chúng tôi đã giúp vô số người tìm việc tìm được việc làm ___139____ danh sách việc làm trực tuyến của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [139]}, {\"en\": \"However, that is not all we ___140____ .\", \"vi\": \"Tuy nhiên, đó không phải là tất cả những gì chúng tôi ___140____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [140]}, {\"en\": \"We also help employers find the most qualified candidates to fill their vacant positions in the shortest amount of time possible.\", \"vi\": \"Chúng tôi cũng giúp các nhà tuyển dụng tìm được những ứng viên đủ điều kiện nhất để lấp đầy các vị trí còn trống trong thời gian ngắn nhất có thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Most human resources directors who use Castak Recruiting ___141____ hire new staff within two weeks of posting their job openings on our Web site.\", \"vi\": \"Hầu hết các giám đốc nhân sự sử dụng Dịch vụ tuyển dụng Castak ___141____ thuê nhân viên mới trong vòng hai tuần kể từ khi đăng tuyển việc làm trên trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [141]}, {\"en\": \"Castak Recruiting\'s service for companies is subscription based and provides numerous affordable and customizable plans.\", \"vi\": \"Dịch vụ dành cho các công ty của Castak Recruiting dựa trên đăng ký và cung cấp nhiều gói cước phải chăng và có thể tùy chỉnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"___142____ .\", \"vi\": \"___142____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [142]}]' WHERE `id` = '9644218c-950d-438a-a036-63bc3cfaf22c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Employee News\", \"vi\": \"Tin tức về nhân viên\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"We would like to extend our congratulations to Alicia Portalska, who will be our new Vice President of Marketing from January 1.\", \"vi\": \"Chúng tôi xin gửi lời chúc mừng đến bà Alicia Portalska, người sẽ đảm nhận chức vụ Phó Chủ tịch phụ trách Tiếp thị mới của công ty chúng tôi kể từ ngày 1 tháng 1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This follows last week\'s news of Vice President Louis Larson\'s retirement at the end of the year.\", \"vi\": \"Điều này diễn ra sau thông tin được đưa ra vào tuần trước về việc Phó Tổng thống Louis Larson sẽ nghỉ hưu vào cuối năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Ms. Portalska joined us as a trainee marketing assistant four years ago and was recently promoted to marketing director.\", \"vi\": \"Bà Portalska gia nhập công ty chúng tôi với tư cách là thực tập sinh trợ lý tiếp thị cách đây bốn năm và gần đây đã được thăng chức lên vị trí giám đốc tiếp thị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We would like to thank Ms. Portalska for her dedication and outstanding contribution to the marketing department.\", \"vi\": \"Chúng tôi xin gửi lời cảm ơn đến bà Portalska vì sự tận tâm và những đóng góp xuất sắc của bà cho bộ phận tiếp thị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Her work has had a significant impact on our sales figures.\", \"vi\": \"Công việc của cô ấy đã có tác động đáng kể đến doanh số bán hàng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It is in part thanks to her tireless efforts that we have exceeded our sales targets this year.\", \"vi\": \"Một phần nhờ vào những nỗ lực không mệt mỏi của cô ấy mà chúng ta đã vượt chỉ tiêu doanh số trong năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Congratulations, Ms. Portalska!\", \"vi\": \"Xin chúc mừng bà Portalska!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Your example is an inspiration to us all.\", \"vi\": \"Ví dụ của quý vị là nguồn cảm hứng cho tất cả chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '965113d9-da82-41df-b32d-b8edbda684ee';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Akihito Nakashima <a.nakashima@gilchristshipping.com>\", \"vi\": \"Từ: Akihito Nakashima <a.nakashima@gilchristshipping.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Fowler Office Supplies <support@fowlerofficesupplies.com>\", \"vi\": \"Gửi tới: Công ty Vật tư Văn phòng Fowler <support@fowlerofficesupplies.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Order B19849\", \"vi\": \"Chủ đề: Đơn đặt hàng số B19849\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: August 19\", \"vi\": \"Ngày: 19 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"To Whom It May Concern,\", \"vi\": \"Kính gửi quý vị có liên quan,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Yesterday, I purchased some office supplies on your Web site.\", \"vi\": \"Hôm qua, tôi đã mua một số vật dụng văn phòng trên trang web của quý công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I received an e-mail receipt, but the costs are not itemized on it.\", \"vi\": \"Tôi đã nhận được biên lai qua email, nhưng các khoản chi phí trong đó không được liệt kê chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To satisfy a new company policy, I must give my supervisor a receipt with the charges for each item listed separately.\", \"vi\": \"Để tuân thủ chính sách mới của công ty, tôi phải nộp cho cấp trên của mình một biên lai trong đó các khoản chi phí cho từng mặt hàng được liệt kê riêng biệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Could you e-mail me such a receipt?\", \"vi\": \"Xin quý vị vui lòng gửi cho tôi biên lai đó qua email được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"If not, is it possible for me to get this information myself from your Web site?\", \"vi\": \"Nếu không, liệu tôi có thể tự tìm hiểu thông tin này trên trang web của quý vị được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Finally, can confirmations for future orders possibly be sent to more than one e-mail address?\", \"vi\": \"Cuối cùng, liệu các thông báo xác nhận cho các đơn hàng trong tương lai có thể được gửi đến nhiều hơn một địa chỉ email hay không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It would be ideal for my supervisor to automatically receive one.\", \"vi\": \"Sẽ thật lý tưởng nếu người giám sát của tôi tự động nhận được một bản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Akihito Nakashima, Executive Assistant\", \"vi\": \"Akihito Nakashima, Trợ lý điều hành\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Gilchrist Shipping\", \"vi\": \"Công ty Vận tải Gilchrist\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From: Fowler Office Supplies <support@fowlerofficesupplies.com>\", \"vi\": \"Từ: Fowler Office Supplies <support@fowlerofficesupplies.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"To: Akihito Nakashima <a.nakashima@gilchristshipping.com>\", \"vi\": \"Gửi: Akihito Nakashima <a.nakashima@gilchristshipping.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Subject: RE: Order B19849\", \"vi\": \"Chủ đề: RE: Đơn hàng B19849\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Date: August 19\", \"vi\": \"Ngày: 19 tháng 8\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Attachment: B19849\", \"vi\": \"Tài liệu đính kèm: B19849\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Dear Mr. Nakashima,\", \"vi\": \"Kính gửi ông Nakashima,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Attached is the receipt you requested.\", \"vi\": \"Kèm theo đây là hóa đơn mà quý vị đã yêu cầu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"In apology for the inconvenience, we will provide you with 10 percent off the total price of your next order.\", \"vi\": \"Để xin lỗi về sự bất tiện này, chúng tôi sẽ giảm giá 10 phần trăm trên tổng giá trị đơn hàng tiếp theo của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"To view a full description of any previous order, first log in to your account on our Web site, go to the \\\"My Orders\\\" tab, and then click on any order number.\", \"vi\": \"Để xem thông tin chi tiết đầy đủ về bất kỳ đơn hàng nào trước đây, trước tiên quý khách vui lòng đăng nhập vào tài khoản của mình trên trang web của chúng tôi, chuyển đến tab “Đơn hàng của tôi”, sau đó nhấp vào bất kỳ số đơn hàng nào.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I noticed that included in each of your last few orders was an identical order for ten of a particular item.\", \"vi\": \"Tôi nhận thấy rằng trong mỗi đơn hàng gần đây nhất của quý vị đều có một đơn hàng giống hệt nhau, bao gồm mười sản phẩm cùng loại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"You should know that we will reduce the price for that item by 5 percent if you mark this as a recurring order.\", \"vi\": \"Xin quý khách lưu ý rằng chúng tôi sẽ giảm giá 5 phần trăm cho mặt hàng đó nếu quý khách chọn đặt hàng định kỳ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"To do this, simply check the \\\"Recurring Order\\\" box on the online order form.\", \"vi\": \"Để thực hiện việc này, quý khách chỉ cần đánh dấu vào ô “Đơn hàng định kỳ” trên biểu mẫu đặt hàng trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"As for your final query, this is not possible right now.\", \"vi\": \"Về câu hỏi cuối cùng của quý vị, hiện tại điều này vẫn chưa thể thực hiện được.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"However, I will share the idea with our technical team.\", \"vi\": \"Tuy nhiên, tôi sẽ trình bày ý tưởng này với đội ngũ kỹ thuật của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"All the best,\", \"vi\": \"Chúc quý vị mọi điều tốt đẹp nhất,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Cameron Higgins, Customer Relations\", \"vi\": \"Cameron Higgins, Bộ phận Quan hệ Khách hàng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Fowler Office Supplies\", \"vi\": \"Công ty Vật tư Văn phòng Fowler\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Item - Price - Quantity - Total\", \"vi\": \"Mặt hàng - Giá - Số lượng - Tổng cộng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Printer paper - $8.00/500 sheets - 10 - $80.00\", \"vi\": \"Giấy in - 8,00 USD/500 tờ - 10 gói - 80,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Toner (black) - $50.00/cartridge - 1 - $50.00\", \"vi\": \"Mực in (màu đen) - 50,00 USD/hộp mực - 1 - 50,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Gel pens (blue) - $5.00/8-pack - 3 - $15.00\", \"vi\": \"Bút gel (màu xanh) - 5,00 USD/gói 8 cây - 3 gói - 15,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Staples - $3.50/box - 2 - $7.00\", \"vi\": \"Kim bấm - 3,50 USD/hộp - 2 hộp - 7,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"GRAND TOTAL - $152.00\", \"vi\": \"TỔNG CỘNG - 152,00 USD\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Fowler Office Supplies\", \"vi\": \"Công ty Vật tư Văn phòng Fowler\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Receipt for Order: B19849\", \"vi\": \"Phiếu xác nhận đơn hàng: B19849\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Order Date: August 18\", \"vi\": \"Ngày đặt hàng: 18 tháng 8\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Return Policy: Unopened merchandise may be returned by mail or in one of our stores within 60 days of purchase.\", \"vi\": \"Chính sách đổi trả: Quý khách có thể đổi trả hàng hóa chưa mở niêm phong qua đường bưu điện hoặc tại một trong các cửa hàng của chúng tôi trong vòng 60 ngày kể từ ngày mua.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"For returns by mail, log in to your www.fowlerofficesupplies.com account to print a shipping label.\", \"vi\": \"Đối với việc trả hàng qua đường bưu điện, quý vị vui lòng đăng nhập vào tài khoản www.fowlerofficesupplies.com của mình để in nhãn vận chuyển.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"For in-store returns, bring the item and the order number to any Fowler Office Supplies location.\", \"vi\": \"Đối với trường hợp đổi trả tại cửa hàng, quý khách vui lòng mang theo sản phẩm và số đơn hàng đến bất kỳ chi nhánh nào của Fowler Office Supplies.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}]' WHERE `id` = '967f49b2-d9b9-4348-9345-e2cee8603ac8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Marina Tincheva 9:01 A.M.: Hi Luis.\", \"vi\": \"Marina Tincheva, 9 giờ 01 phút sáng: Đó là Luis.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I\'m at the restaurant.\", \"vi\": \"Tôi đang ở nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I need to start setting up the dessert tables for the wedding banquet this afternoon, but the door\'s locked and I left my key at home.\", \"vi\": \"Chiều nay tôi cần bắt đầu dọn dẹp bàn tráng miệng cho tiệc cưới, nhưng cửa lại bị khóa và tôi đã để chìa khóa ở nhà rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Luis Machado 9:03 A.M.: Ms. Howell isn\'t there?\", \"vi\": \"Luis Machado 9 giờ 03 phút sáng: Cô Howell không có ở đó sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"She usually shows up hours ahead of an event to get things ready.\", \"vi\": \"Cô ấy thường có mặt từ vài giờ trước khi sự kiện bắt đầu để chuẩn bị mọi thứ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Marina Tincheva 9:04 A.M.: I know.\", \"vi\": \"Marina Tincheva, 9 giờ 04 phút sáng: Tôi biết rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It doesn\'t make sense.\", \"vi\": \"Điều đó thật vô lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You\'ll be in late today, right?\", \"vi\": \"Hôm nay anh sẽ đi làm muộn, phải không ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Luis Machado 9:06 A.M.: Yes.\", \"vi\": \"Luis Machado 9 giờ 06 phút sáng: Vâng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Actually, I\'m on my way to a conference for managers, but I can be there in 10 minutes to let you in.\", \"vi\": \"Thực ra, tôi đang trên đường đến dự một hội nghị dành cho các nhà quản lý, nhưng tôi có thể có mặt tại đó trong 10 phút nữa để mở cửa cho quý vị vào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Marina Tincheva 9:07 A.M.: Thank you so much!\", \"vi\": \"Marina Tincheva, 9 giờ 07 phút sáng: Xin chân thành cảm ơn quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I\'ll wait at the cafe next door.\", \"vi\": \"Tôi sẽ đợi tại quán cà phê bên cạnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '968b443d-7733-47f5-b263-e2b4f0f4b937';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Tasty Treat in Kentron\", \"vi\": \"Món ngon tại Kentron\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Kentron\'s own Groovato Gelato was founded in 2010 when Luciano Algieri, an Italian immigrant to the United States, bought a ______[143] on Coverby Avenue.\", \"vi\": \"Thương hiệu kem Ý Groovato Gelato của riêng Kentron được thành lập vào năm 2010 khi Luciano Algieri, một người Ý nhập cư vào Hoa Kỳ, đã mua một ______[143] trên Đại lộ Coverby.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [143]}, {\"en\": \"The building had previously housed the Hopscotch Ice Cream Company, and Algieri was able to hire many former Hopscotch employees.\", \"vi\": \"Tòa nhà trước đây từng là trụ sở của Công ty Kem Hopscotch, và Algieri đã có thể thuê lại nhiều cựu nhân viên của Hopscotch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Teaching ______[144] ice-cream crafters to make gelato proved to be an easy task.\", \"vi\": \"Việc hướng dẫn những người thợ làm kem ______[144] chế biến món gelato hóa ra lại là một công việc dễ dàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [144]}, {\"en\": \"______[145] his product, Algieri started with an old family recipe.\", \"vi\": \"______[145] sản phẩm của mình, Algieri bắt đầu với một công thức gia truyền lâu đời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [145]}, {\"en\": \"He then enhanced the flavor with secret ingredients plus unusual combinations of fruits and nuts.\", \"vi\": \"Sau đó, ông đã nâng tầm hương vị bằng các nguyên liệu bí mật cùng với sự kết hợp độc đáo giữa các loại trái cây và các loại hạt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[146].\", \"vi\": \"______[146].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [146]}, {\"en\": \"There are now three store locations in the Kentron area.\", \"vi\": \"Hiện tại có ba cửa hàng tại khu vực Kentron.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Residents are lucky to have this gem!\", \"vi\": \"Cư dân thật may mắn khi có được viên ngọc quý này!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = '969dded4-9a3f-45d5-99ae-ba6bd5273dc7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Jin-Hwa Grill\", \"vi\": \"Nhà hàng Jin-Hwa Grill\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Serving the finest Korean cuisine in northern California for over 30 years\", \"vi\": \"Hơn 30 năm qua, chúng tôi luôn mang đến những món ăn Hàn Quốc hảo hạng nhất tại miền Bắc California\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Come celebrate the reopening of our newly remodeled restaurant on Lakeside Drive!\", \"vi\": \"Hãy đến chung vui cùng chúng tôi nhân dịp nhà hàng của chúng tôi trên đường Lakeside Drive, sau khi được tu sửa lại, chính thức mở cửa trở lại!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Purchase any two dinners and enjoy a complimentary appetizer platter during the entire month of May.\", \"vi\": \"Khi quý khách mua bất kỳ hai suất ăn tối nào, quý khách sẽ được thưởng thức một đĩa món khai vị miễn phí trong suốt tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Valid only at Jin-Hwa Grill, 4104 Lakeside Drive, Oakland, CA.\", \"vi\": \"Chỉ có giá trị tại nhà hàng Jin-Hwa Grill, địa chỉ 4104 Lakeside Drive, Oakland, CA.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Coupon does not apply to takeout orders.\", \"vi\": \"Phiếu giảm giá này không áp dụng cho các đơn hàng mang về.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Visit www.jin-hwagrill.com for a list of all our locations, hours of operation, and menus.\", \"vi\": \"Quý vị vui lòng truy cập www.jin-hwagrill.com để xem danh sách tất cả các chi nhánh, giờ mở cửa và thực đơn của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '96ea759c-0dd2-4067-99d0-5125152f2a79';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Major Expansion for Local Biotech Startup\", \"vi\": \"Mở rộng quy mô lớn cho công ty khởi nghiệp công nghệ sinh học địa phương\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Medicatenet, a leading biotechnology company, ____131____ yesterday that it has raised $200 million in venture capital from investors.\", \"vi\": \"Medicatenet, một công ty công nghệ sinh học hàng đầu, ____131____ ngày hôm qua rằng họ đã huy động được 200 triệu đô la vốn đầu tư mạo hiểm từ các nhà đầu tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"It plans to use those ____132____ to install cutting-edge technology involving machine learning to develop new medicines.\", \"vi\": \"Họ có kế hoạch sử dụng số ____132____ đó để lắp đặt công nghệ tiên tiến liên quan đến máy học nhằm phát triển các loại thuốc mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132]}, {\"en\": \"The investment will enable Medicatenet to triple its workforce ____133____ the next twelve months.\", \"vi\": \"Khoản đầu tư này sẽ cho phép Medicatenet tăng gấp ba lần lực lượng lao động của mình ____133____ trong mười hai tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [133]}, {\"en\": \"____134____.\", \"vi\": \"____134____.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [134]}]' WHERE `id` = '96f9723c-0f8d-4be5-85be-059407056d28';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Your Business Gets Noticed When You Advertise Here!\", \"vi\": \"Doanh nghiệp của quý vị sẽ thu hút sự chú ý khi quảng cáo tại đây!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Prime advertising space is available with sizes ranging from a quarter column to a full page.\", \"vi\": \"Chúng tôi hiện có sẵn các vị trí quảng cáo đắc địa với các kích thước đa dạng, từ một phần tư cột đến một trang đầy đủ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The Clearpoint Times reaches thousands of your neighbors each week.\", \"vi\": \"Tờ Clearpoint Times tiếp cận hàng nghìn người hàng xóm của quý vị mỗi tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Use the Clearpoint Times to spread the word about your business.\", \"vi\": \"Hãy tận dụng tờ Clearpoint Times để quảng bá doanh nghiệp của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"It works!\", \"vi\": \"Nó hoạt động rồi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"For rates and additional information, call us at 515-555-0130.\", \"vi\": \"Để biết thông tin về giá cả và các thông tin khác, xin vui lòng liên hệ với chúng tôi theo số 515-555-0130.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '970049f8-7609-4252-bea4-38f8fe7e4490';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"John Dakers [9:30 A.M.]\", \"vi\": \"John Dakers [9 giờ 30 sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hello.\", \"vi\": \"Xin chào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I have a furnace service appointment scheduled this morning.\", \"vi\": \"Sáng nay, tôi có một cuộc hẹn bảo trì lò sưởi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Is a technician on the way to my house yet?\", \"vi\": \"Kỹ thuật viên đã trên đường đến nhà tôi chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"HVAC Customer Service [9:31 A.M.]\", \"vi\": \"Dịch vụ khách hàng về hệ thống HVAC [9 giờ 31 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Let me check.\", \"vi\": \"Để tôi kiểm tra xem.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"HVAC Customer Service [9:32 A.M.]\", \"vi\": \"Dịch vụ khách hàng về hệ thống HVAC [9 giờ 32 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Our system shows that someone will be there today between 3:00 P.M. and 5:00 P.M.\", \"vi\": \"Hệ thống của chúng tôi cho thấy sẽ có người có mặt tại đó vào hôm nay, trong khoảng thời gian từ 3 giờ chiều đến 5 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"John Dakers [9:33 A.M.]\", \"vi\": \"John Dakers [9 giờ 33 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"My notes say 9:00 to 11:00 A.M. today.\", \"vi\": \"Theo ghi chú của tôi, hôm nay là từ 9 giờ đến 11 giờ sáng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I took time off from work.\", \"vi\": \"Tôi đã xin nghỉ làm một thời gian.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"HVAC Customer Service [9:34 A.M.]\", \"vi\": \"Dịch vụ khách hàng về hệ thống HVAC [9 giờ 34 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I am sorry for any miscommunication.\", \"vi\": \"Tôi xin lỗi vì bất kỳ sự hiểu lầm nào có thể đã xảy ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"A technician will be there later today.\", \"vi\": \"Một kỹ thuật viên sẽ có mặt tại đó vào cuối ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"John Dakers [9:36 A.M.]\", \"vi\": \"John Dakers [9 giờ 36 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"But I need to get to the office soon.\", \"vi\": \"Tuy nhiên, tôi cần phải đến văn phòng sớm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"HVAC Customer Service [9:37 A.M.]\", \"vi\": \"Dịch vụ khách hàng về hệ thống HVAC [9 giờ 37 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Our apologies, Mr. Dakers.\", \"vi\": \"Chúng tôi xin gửi lời xin lỗi đến ông Dakers.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I will see if we can make some schedule changes.\", \"vi\": \"Tôi sẽ xem xét liệu chúng ta có thể điều chỉnh lịch trình một chút hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"HVAC Customer Service [9:42 A.M.]\", \"vi\": \"Dịch vụ khách hàng về hệ thống HVAC [9 giờ 42 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Good news.\", \"vi\": \"Tin vui.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I reached your technician.\", \"vi\": \"Tôi đã liên hệ được với kỹ thuật viên của quý công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"She is finishing a job now and can be there within the hour.\", \"vi\": \"Hiện tại, cô ấy đang hoàn tất một công việc và có thể có mặt tại đó trong vòng một giờ nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"John Dakers [9:43 A.M.]\", \"vi\": \"John Dakers [9 giờ 43 phút sáng]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Thank you very much. I appreciate it.\", \"vi\": \"Xin chân thành cảm ơn. Tôi rất biết ơn điều đó.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '972c4258-688e-4835-b079-c5dd42134c64';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Student Activities Coordinator\", \"vi\": \"Điều phối viên các hoạt động sinh viên\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Rollervy University\", \"vi\": \"Đại học Rollervy\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Maynard, MA 01754\", \"vi\": \"Maynard, MA 01754\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Responsibilities:\", \"vi\": \"Nhiệm vụ:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Promotes involvement in campus extracurricular activities such as student government, arts, theater, cultural organizations, volunteer groups, and athletic club teams\", \"vi\": \"Khuyến khích sự tham gia vào các hoạt động ngoại khóa trong khuôn viên trường như hội sinh viên, nghệ thuật, sân khấu, các tổ chức văn hóa, các nhóm tình nguyện và các câu lạc bộ thể thao\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Updates the Rollervy University student activities Web site and manages all social media\", \"vi\": \"Cập nhật trang web về các hoạt động sinh viên của Đại học Rollervy và quản lý tất cả các nền tảng mạng xã hội\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Coordinates student outings to local sporting and cultural events in the Boston metropolitan area\", \"vi\": \"Tổ chức các chuyến tham quan cho sinh viên đến các sự kiện thể thao và văn hóa tại khu vực đô thị Boston\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Addresses inquiries by answering phones, responding to e-mails, and greeting walk-in visitors\", \"vi\": \"Tiếp nhận các yêu cầu bằng cách trả lời điện thoại, trả lời email và chào đón khách đến trực tiếp\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"To apply, write your cover letter in an e-mail, attach your résumé, and send it to the Human Resources Manager, at jobs@rollervy.edu.\", \"vi\": \"Để nộp đơn, quý vị vui lòng soạn thư xin việc trong email, đính kèm sơ yếu lý lịch và gửi đến Trưởng phòng Nhân sự theo địa chỉ jobs@rollervy.edu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please address the following:\", \"vi\": \"Kính đề nghị quý vị giải quyết các vấn đề sau đây:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"What relevant job experience do you have?\", \"vi\": \"Quý vị có những kinh nghiệm làm việc liên quan nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Why do you believe you are a good fit for the position?\", \"vi\": \"Tại sao quý vị cho rằng mình là ứng viên phù hợp với vị trí này?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"What are your professional strengths?\", \"vi\": \"Những thế mạnh nghề nghiệp của quý vị là gì?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"In which areas could you improve?\", \"vi\": \"Quý vị có thể cải thiện ở những khía cạnh nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To: Jobs <jobs@rollervy.edu>\", \"vi\": \"Gửi tới: Jobs <jobs@rollervy.edu>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From: Samantha Bradbury <sambradbury25@rapidonet.com>\", \"vi\": \"Từ: Samantha Bradbury <sambradbury25@rapidonet.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Date: September 10\", \"vi\": \"Ngày: 10 tháng 9\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Subject: Student Activities Coordinator\", \"vi\": \"Chủ đề: Điều phối viên các hoạt động sinh viên\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Attachment: Résumé\", \"vi\": \"Tệp đính kèm: Sơ yếu lý lịch\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"To Whom It May Concern,\", \"vi\": \"Kính gửi quý vị có liên quan,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Rollervy University is looking for someone to coordinate activities, promote student engagement, and provide professional customer service.\", \"vi\": \"Trường Đại học Rollervy đang tìm kiếm một ứng viên để điều phối các hoạt động, thúc đẩy sự tham gia của sinh viên và cung cấp dịch vụ khách hàng chuyên nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I did all three during my tenure as the Campus Recreation Manager at Parvaton College.\", \"vi\": \"Tôi đã đảm nhận cả ba công việc này trong thời gian giữ chức vụ Quản lý Hoạt động Giải trí trong khuôn viên trường tại Trường Cao đẳng Parvaton.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"At Parvaton, I increased participation in student activities by 37 percent.\", \"vi\": \"Tại Parvaton, tôi đã giúp tăng tỷ lệ tham gia các hoạt động sinh viên lên 37 phần trăm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I also created a running club and planned excursions off campus.\", \"vi\": \"Tôi cũng đã thành lập một câu lạc bộ chạy bộ và lên kế hoạch cho các chuyến dã ngoại ngoài khuôn viên trường.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I placed a great emphasis on volunteering, including a project to pair college tutors with local high school students who needed help with classwork.\", \"vi\": \"Tôi đã đặc biệt chú trọng đến hoạt động tình nguyện, trong đó có một dự án kết nối các gia sư đại học với các học sinh trung học phổ thông tại địa phương đang cần sự hỗ trợ trong việc học tập.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Overall, I believe I\'m an excellent fit for the available position.\", \"vi\": \"Nhìn chung, tôi tin rằng mình là ứng viên rất phù hợp với vị trí đang tuyển dụng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"I am punctual, detail oriented, and committed to increasing students\' connection to their academic institution.\", \"vi\": \"Tôi là người đúng giờ, chú trọng đến từng chi tiết và luôn nỗ lực nhằm tăng cường sự gắn kết của sinh viên với cơ sở giáo dục của họ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I look forward to hearing back about a potential interview.\", \"vi\": \"Tôi rất mong nhận được phản hồi về khả năng được tham gia buổi phỏng vấn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Samantha Bradbury\", \"vi\": \"Samantha Bradbury\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"To: Samantha Bradbury <sambradbury25@rapidonet.com>\", \"vi\": \"Gửi tới: Samantha Bradbury <sambradbury25@rapidonet.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"From: Lisa Cooper <jobs@rollervy.edu>\", \"vi\": \"Từ: Lisa Cooper <jobs@rollervy.edu>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Date: October 2\", \"vi\": \"Ngày: 2 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Subject: Interview\", \"vi\": \"Chủ đề: Buổi phỏng vấn\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Dear Samantha,\", \"vi\": \"Kính gửi Samantha,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"I am writing to check on your availability to interview for the Student Activities Coordinator position.\", \"vi\": \"Tôi viết thư này để hỏi xem quý vị có thể sắp xếp thời gian tham gia phỏng vấn cho vị trí Điều phối viên Hoạt động Sinh viên hay không.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Your preliminary interview would be conducted virtually.\", \"vi\": \"Buổi phỏng vấn sơ bộ của quý vị sẽ được tiến hành trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"If selected for the next round, your second interview would be in person at the Rollervy University main campus.\", \"vi\": \"Nếu được chọn vào vòng tiếp theo, buổi phỏng vấn thứ hai của quý vị sẽ diễn ra trực tiếp tại khuôn viên chính của Đại học Rollervy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"If you are still interested, please respond and let me know if you are free at 9 A.M. on either October 8 or October 9.\", \"vi\": \"Nếu quý vị vẫn quan tâm, xin vui lòng trả lời và cho tôi biết liệu quý vị có rảnh vào lúc 9 giờ sáng ngày 8 tháng 10 hoặc ngày 9 tháng 10 hay không.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Lisa Cooper\", \"vi\": \"Lisa Cooper\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}]' WHERE `id` = '97461ad0-3f4e-46d5-998c-f114c4c22be9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Michael Liu (9:43 A.M.)\", \"vi\": \"Michael Liu (9 giờ 43 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Jana.\", \"vi\": \"Xin chào, Jana.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I\'m at Biz Plus.\", \"vi\": \"Tôi đang ở Biz Plus.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The paper you need is out of stock until next week.\", \"vi\": \"Loại giấy mà quý vị cần hiện đã hết hàng và sẽ có lại vào tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Will another color work?\", \"vi\": \"Có màu nào khác phù hợp không ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Jana Bhat (9:45 A.M.)\", \"vi\": \"Jana Bhat (9 giờ 45 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"What are the options?\", \"vi\": \"Có những lựa chọn nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Michael Liu (9:46 A.M.)\", \"vi\": \"Michael Liu (9 giờ 46 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"They have yellow, green, and pink in the brand that you prefer.\", \"vi\": \"Thương hiệu mà quý vị ưa thích có các màu vàng, xanh lá cây và hồng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Jana Bhat (9:47 A.M.)\", \"vi\": \"Jana Bhat (9 giờ 47 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I really need blue.\", \"vi\": \"Tôi thực sự cần màu xanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Are there other brands of blue printer paper?\", \"vi\": \"Có những nhãn hiệu giấy in màu xanh khác không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Michael Liu (9:48 A.M.)\", \"vi\": \"Michael Liu (9 giờ 48 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Yes, but they\'re all a darker blue.\", \"vi\": \"Đúng vậy, nhưng tất cả đều có màu xanh dương đậm hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"They also cost more.\", \"vi\": \"Chúng cũng có giá cao hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Jana Bhat (9:49 A.M.)\", \"vi\": \"Jana Bhat (9 giờ 49 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"OK, forget it.\", \"vi\": \"Được rồi, thôi bỏ đi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I\'ll place an order online.\", \"vi\": \"Tôi sẽ đặt hàng trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '97841de8-8f96-4208-a56f-7cf4bde3b3e7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Director Rubio Celebrated\", \"vi\": \"Giám đốc Rubio được vinh danh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"MERRINGTON (July 20)—Although Pedro Rubio retired from directing ten years ago, his award-winning films still influence today\'s cinema.\", \"vi\": \"MERRINGTON (ngày 20 tháng 7) — Mặc dù Pedro Rubio đã nghỉ hưu khỏi nghề đạo diễn cách đây mười năm, những bộ phim từng đoạt giải thưởng của ông vẫn tiếp tục có ảnh hưởng đến nền điện ảnh ngày nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Rubio’s childhood home was near a movie house, where he fell in love with the art form.\", \"vi\": \"Ngôi nhà thời thơ ấu của ông Rubio nằm gần một rạp chiếu phim, nơi ông đã say mê nghệ thuật điện ảnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"He saw several movies a week, sometimes watching the same movie multiple times.\", \"vi\": \"Ông ấy xem vài bộ phim mỗi tuần, đôi khi còn xem đi xem lại cùng một bộ phim nhiều lần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"His extensive familiarity with a range of genres is apparent in his work.\", \"vi\": \"Sự am hiểu sâu rộng của ông về nhiều thể loại khác nhau thể hiện rõ qua các tác phẩm của ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Titles range from the romantic Send Me Some Roses to the horror classic That House.\", \"vi\": \"Các tác phẩm bao gồm từ bộ phim lãng mạn *Send Me Some Roses* cho đến tác phẩm kinh dị kinh điển *That House*.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Rubio retired from filmmaking at age 65 after almost 40 years of directing, but he has kept busy.\", \"vi\": \"Ông Rubio đã từ giã nghề làm phim ở tuổi 65 sau gần 40 năm làm đạo diễn, nhưng ông vẫn luôn bận rộn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Most recently, he has been working as a guest lecturer at the nearby Weberton Film School.\", \"vi\": \"Gần đây nhất, ông đã đảm nhận vai trò giảng viên khách mời tại Trường Điện ảnh Weberton gần đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Readers will be pleased to hear that our own Merrington Cinema will be showing Rubio’s films throughout August.\", \"vi\": \"Quý độc giả hẳn sẽ rất vui mừng khi biết rằng Rạp chiếu phim Merrington của chúng ta sẽ trình chiếu các bộ phim của Rubio trong suốt tháng Tám.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Whether you are a longtime fan or have never seen a Rubio film, you will surely enjoy this offering at Merrington Cinema.\", \"vi\": \"Dù quý vị là người hâm mộ lâu năm hay chưa từng xem bất kỳ bộ phim nào của Rubio, quý vị chắc chắn sẽ thích thú với tác phẩm này tại Rạp chiếu phim Merrington.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"https://www.merringtoncinema.com\", \"vi\": \"https://www.merringtoncinema.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Home - Schedule - Reviews - Contact Us\", \"vi\": \"Trang chủ - Lịch trình - Đánh giá - Liên hệ với chúng tôi\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Choose Your Own Double Feature\", \"vi\": \"Hãy tự chọn bộ đôi phim yêu thích của quý vị\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"In August, we will celebrate the acclaimed director Pedro Rubio’s birthday by showing many of his movies.\", \"vi\": \"Vào tháng 8, chúng tôi sẽ tổ chức kỷ niệm sinh nhật của đạo diễn nổi tiếng Pedro Rubio bằng cách chiếu nhiều bộ phim của ông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"And you can purchase tickets to two movies for the price of one!\", \"vi\": \"Và quý vị có thể mua vé xem hai bộ phim với giá chỉ bằng một vé!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Rubio made the films listed below at the beginning of his directing career.\", \"vi\": \"Rubio đã thực hiện các bộ phim được liệt kê dưới đây vào những ngày đầu của sự nghiệp đạo diễn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"See the Schedule page for the complete list of films and their weekly viewing times.\", \"vi\": \"Quý vị vui lòng tham khảo trang Lịch chiếu để xem danh sách đầy đủ các bộ phim cùng thời gian chiếu hàng tuần.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Put a Roof on It, Comedy, 102 minutes\", \"vi\": \"“Hãy Lắp Mái Nhà Cho Nó”, Phim hài, 102 phút\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Construction workers do their best to build a wealthy man’s dream home while his brother tries to take over the project.\", \"vi\": \"Các công nhân xây dựng đang nỗ lực hết mình để xây dựng ngôi nhà trong mơ của một người đàn ông giàu có, trong khi anh trai của ông ta lại tìm cách chiếm quyền điều hành dự án.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Through a Diamond Rain, Science Fiction, 124 minutes\", \"vi\": \"“Through a Diamond Rain”, Phim khoa học viễn tưởng, 124 phút\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Two teams of researchers travel to Neptune and try to send their findings back to Earth.\", \"vi\": \"Hai nhóm nhà nghiên cứu đã lên đường tới sao Hải Vương và cố gắng gửi những phát hiện của họ về Trái Đất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Weekends and Memories, Drama, 115 minutes\", \"vi\": \"Những ngày cuối tuần và ký ức, Phim chính kịch, 115 phút\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"A group of old friends gather at a country house and discover that much has changed since they were last together.\", \"vi\": \"Một nhóm bạn cũ tụ họp tại một ngôi nhà ở vùng quê và nhận ra rằng đã có nhiều thay đổi kể từ lần cuối cùng họ gặp nhau.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"This film won the Gold Dreamer Award.\", \"vi\": \"Bộ phim này đã giành được Giải thưởng Gold Dreamer.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"The Strange Drive, Western, 107 minutes\", \"vi\": \"The Strange Drive, Phim miền Tây, 107 phút\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Cowboys on a cattle drive encounter a series of interesting and unusual strangers.\", \"vi\": \"Những người chăn bò trong chuyến lùa bò đã gặp phải một loạt những người lạ mặt thú vị và khác thường.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"https://www.merringtoncinema.com/reviews\", \"vi\": \"https://www.merringtoncinema.com/reviews\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Home - Schedule - Reviews - Contact Us\", \"vi\": \"Trang chủ - Lịch trình - Đánh giá - Liên hệ với chúng tôi\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I recently read a great article about director Pedro Rubio.\", \"vi\": \"Gần đây, tôi đã đọc được một bài viết rất hay về đạo diễn Pedro Rubio.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"It contained a lot of information about his work and life, including some surprising information about what he has been doing since he retired from filmmaking.\", \"vi\": \"Cuốn sách này chứa đựng rất nhiều thông tin về sự nghiệp và cuộc đời của ông, bao gồm cả một số thông tin đáng ngạc nhiên về những hoạt động của ông kể từ khi ông từ giã nghề làm phim.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"The article also mentioned that Merrington Cinema would be showing his films.\", \"vi\": \"Bài báo cũng đề cập rằng Rạp chiếu phim Merrington sẽ chiếu các bộ phim của ông.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"So I went to the cinema’s Web site and saw the two-for-one deal.\", \"vi\": \"Vì vậy, tôi đã truy cập trang web của rạp chiếu phim và thấy chương trình khuyến mãi “mua một tặng một”.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I thought this would be an excellent way to spend a Saturday, so I went!\", \"vi\": \"Tôi nghĩ đây sẽ là một cách tuyệt vời để tận hưởng ngày thứ Bảy, nên tôi đã đi luôn!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"I saw two wonderful movies.\", \"vi\": \"Tôi đã xem hai bộ phim rất hay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"One of the films I saw was new to me: it was about scientists on a mission in space!\", \"vi\": \"Một trong những bộ phim mà tôi đã xem là bộ phim mà tôi chưa từng xem trước đây: bộ phim kể về các nhà khoa học trong một sứ mệnh thám hiểm không gian!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"I loved it!\", \"vi\": \"Tôi rất thích nó!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"For a movie fan like me, Merrington Cinema’s promotion was perfect.\", \"vi\": \"Đối với một người yêu điện ảnh như tôi, chương trình khuyến mãi của Rạp chiếu phim Merrington thực sự là một lựa chọn hoàn hảo.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"I understand there will be a similar promotion for Meredeth Bui’s films in October.\", \"vi\": \"Tôi được biết vào tháng 10 sẽ có một chương trình quảng bá tương tự dành cho các bộ phim của Meredeth Bui.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"I’ll be sure to take advantage of great offers like this again.\", \"vi\": \"Tôi chắc chắn sẽ tiếp tục tận dụng những ưu đãi hấp dẫn như thế này trong tương lai.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"—Talia Pak\", \"vi\": \"—Talia Pak\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}]' WHERE `id` = '978e3b2d-fac8-4fc5-a8ed-0256c26bcba8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: tbogosian@sardhasconvention.com\", \"vi\": \"Nguồn: tbogosian@sardhasconvention.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: pradalaily@dmcv.com\", \"vi\": \"Gửi tới: pradalaily@dmcv.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 22 March\", \"vi\": \"Ngày: 22 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Your reservation\", \"vi\": \"Chủ đề: Đặt chỗ của quý khách\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Prada party\", \"vi\": \"Tệp đính kèm: 📎 Bữa tiệc của Prada\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"E-Mail Message\", \"vi\": \"Thông điệp email\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Ms. Prada,\", \"vi\": \"Kính gửi bà Prada,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Thank you for choosing Sardha\'s Banquet Hall to host your event on 30 August.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã lựa chọn Trung tâm tiệc Sardha để tổ chức sự kiện của quý khách vào ngày 30 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Unfortunately, West Hall will be under renovation in August, and we will be unable to accommodate your group in that room.\", \"vi\": \"Rất tiếc, West Hall sẽ được cải tạo vào tháng 8, và chúng tôi sẽ không thể sắp xếp để nhóm của quý vị sử dụng phòng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"However, your party will fit comfortably in East Hall.\", \"vi\": \"Tuy nhiên, buổi tiệc của quý vị sẽ diễn ra một cách thoải mái tại East Hall.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"This room features floor-to-ceiling windows and a full view of the river.\", \"vi\": \"Căn phòng này có cửa sổ kính từ sàn đến trần và tầm nhìn toàn cảnh ra dòng sông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The 15 percent deposit we have received will hold the reservation.\", \"vi\": \"Khoản đặt cọc 15% mà chúng tôi đã nhận được sẽ giúp quý vị giữ chỗ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"As indicated when you completed your request through our Web site, your total price of $1,600 includes a full-course meal that includes appetizers, soup or salad, main course, and dessert.\", \"vi\": \"Như đã nêu khi quý vị hoàn tất yêu cầu qua trang web của chúng tôi, tổng giá trị 1.600 đô la của quý vị đã bao gồm một bữa ăn trọn bộ với các món khai vị, súp hoặc salad, món chính và món tráng miệng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Attached to this e-mail please find a copy of the menu presented to guests with options for appetizer and main course.\", \"vi\": \"Kèm theo email này là bản sao thực đơn được trình bày cho quý khách, trong đó có các lựa chọn về món khai vị và món chính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Tomas Bogosian\", \"vi\": \"Thomas Bogosian\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"General Manager\", \"vi\": \"Tổng Giám đốc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '97c42cf4-c650-48d5-b2e5-03ee956caf78';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Instructors\", \"vi\": \"Kính gửi: Tất cả các giảng viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Jee-Young Choi\", \"vi\": \"Từ: Jee-Young Choi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: New fee schedule\", \"vi\": \"Chủ đề: Bảng phí mới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: August 15\", \"vi\": \"Ngày: 15 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Category - Description - Duration - Fee\", \"vi\": \"Loại hình - Mô tả - Thời lượng - Phí tham gia\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Tour - Lead group tour - 60 minutes - $50\", \"vi\": \"Chuyến tham quan - Chuyến tham quan theo nhóm có hướng dẫn viên - 60 phút - 50 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Tour - Lead group tour - 90 minutes - $75\", \"vi\": \"Chuyến tham quan - Chuyến tham quan theo đoàn có hướng dẫn viên - 90 phút - 75 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Class - Teach art class - 75 minutes - $65\", \"vi\": \"Buổi học - Dạy lớp mỹ thuật - 75 phút - 65 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Class - Teach art class - 120 minutes - $110\", \"vi\": \"Lớp học – Dạy lớp mỹ thuật – 120 phút – 110 đô la\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Development - Plan new course content - Varies - $200\", \"vi\": \"Phát triển - Lập kế hoạch nội dung khóa học mới - Tùy theo từng trường hợp - 200 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Training - Instruct museum staff on a specialized topic - Varies - $25/hour\", \"vi\": \"Đào tạo - Hướng dẫn nhân viên bảo tàng về một chủ đề chuyên sâu - Mức thù lao thay đổi - 25 USD/giờ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Dear Teachers,\", \"vi\": \"Kính gửi quý thầy cô,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you for lending your skills as artists and educators to the Mirabel Museum of Art.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã đóng góp tài năng của mình với tư cách là các nghệ sĩ và nhà giáo dục cho Bảo tàng Mỹ thuật Mirabel.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please use the updated fee schedule below when creating your monthly invoices.\", \"vi\": \"Kính mong Quý vị sử dụng biểu phí cập nhật dưới đây khi lập hóa đơn hàng tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Electronic payments should be available ten business days after invoice submission.\", \"vi\": \"Dịch vụ thanh toán điện tử sẽ được mở sau mười ngày làm việc kể từ khi gửi hóa đơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Jee-Young Choi, Education Coordinator\", \"vi\": \"Bà Jee-Young Choi, Điều phối viên Giáo dục\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Date - Description - Fee\", \"vi\": \"Ngày - Mô tả - Phí\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"September 22 - Tour: Special exhibit - $50\", \"vi\": \"Ngày 22 tháng 9 – Chương trình tham quan: Triển lãm đặc biệt – 50 đô la\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"September 22 - Class: Drawing for Beginners - $65\", \"vi\": \"Ngày 22 tháng 9 - Lớp học: Vẽ dành cho người mới bắt đầu - 65 đô la\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"September 25 - Class: Sculpting with Clay - $110\", \"vi\": \"Ngày 25 tháng 9 - Lớp học: Tạo hình bằng đất sét - 110 đô la\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Total - $225\", \"vi\": \"Tổng cộng - 225 đô la\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Devonte Merriweather\", \"vi\": \"Devonte Merriweather\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"d.merriweather@camail.ca\", \"vi\": \"d.merriweather@camail.ca\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Invoice #00278\", \"vi\": \"Hóa đơn số 00278\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"For: Services at the Mirabel Museum of Art\", \"vi\": \"Dành cho: Các dịch vụ tại Bảo tàng Mỹ thuật Mirabel\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Sent: September 30\", \"vi\": \"Ngày gửi: 30 tháng 9\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"To: Devonte Merriweather\", \"vi\": \"Gửi: Devonte Merriweather\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"From: Jee-Young Choi\", \"vi\": \"Từ: Jee-Young Choi\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Subject: Payment\", \"vi\": \"Chủ đề: Thanh toán\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Date: October 6\", \"vi\": \"Ngày: 6 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Dear Mr. Merriweather,\", \"vi\": \"Kính gửi ông Merriweather,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Thank you for submitting your September invoice.\", \"vi\": \"Xin cảm ơn quý vị đã gửi hóa đơn tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I noticed that you neglected to charge us for developing the curriculum for your sculpting class, which you taught for the first time on September 25.\", \"vi\": \"Tôi nhận thấy rằng quý vị đã quên tính phí cho chúng tôi về việc xây dựng chương trình giảng dạy cho lớp điêu khắc mà quý vị đã giảng dạy lần đầu tiên vào ngày 25 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"I checked with Carol Swann, and she said that because invoice #00278 has already been paid, it would be best if you submitted a second invoice for the development.\", \"vi\": \"Tôi đã liên hệ với bà Carol Swann, và bà cho biết do hóa đơn số 00278 đã được thanh toán, nên tốt nhất là quý vị nên gửi một hóa đơn thứ hai cho dự án phát triển này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"I will ask her to process it quickly when I receive it.\", \"vi\": \"Khi nhận được tài liệu đó, tôi sẽ đề nghị cô ấy xử lý nhanh chóng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"You will be happy to know that the feedback from your students was very positive.\", \"vi\": \"Chắc hẳn quý vị sẽ rất vui khi biết rằng phản hồi từ các học sinh của quý vị rất tích cực.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"I will e-mail scans of their feedback forms later today.\", \"vi\": \"Tôi sẽ gửi bản scan các biểu mẫu phản hồi của quý vị qua email vào cuối ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Jee-Young Choi, Education Coordinator\", \"vi\": \"Bà Jee-Young Choi, Điều phối viên Giáo dục\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}]' WHERE `id` = '97cebffe-756f-4691-81f9-6ed61eb1ebaf';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Susan Gowan 9:16 A.M.\", \"vi\": \"Susan Gowan, 9 giờ 16 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Good morning.\", \"vi\": \"Chào buổi sáng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores.\", \"vi\": \"Các slide trình chiếu về dòng tai nghe mới đã gần như sẵn sàng để phân phối tới các cửa hàng đối tác của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We are on track to send them out next Monday.\", \"vi\": \"Chúng tôi đang tiến hành đúng tiến độ để gửi các sản phẩm này vào thứ Hai tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Maggie Lorenz 9:17 A.M.\", \"vi\": \"Maggie Lorenz 9 giờ 17 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"How do they look?\", \"vi\": \"Chúng trông thế nào ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Susan Gowan 9:20 A.M.\", \"vi\": \"Susan Gowan, 9 giờ 20 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"There are still some missing elements.\", \"vi\": \"Vẫn còn một số yếu tố chưa có.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Alan Woodson 9:21 A.M.\", \"vi\": \"Alan Woodson, 9 giờ 21 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We mainly need the information from the user studies that reviewed the headphones for sport use.\", \"vi\": \"Chúng tôi chủ yếu cần thông tin từ các nghiên cứu người dùng đã đánh giá các mẫu tai nghe dành cho hoạt động thể thao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We should have that report from the research and development office by Wednesday.\", \"vi\": \"Chúng ta sẽ nhận được bản báo cáo đó từ phòng Nghiên cứu và Phát triển vào thứ Tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Maggie Lorenz 9:22 A.M.\", \"vi\": \"Maggie Lorenz 9 giờ 22 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Yes, let\'s not overlook that.\", \"vi\": \"Vâng, chúng ta đừng bỏ qua điều đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"And if you\'re concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.\", \"vi\": \"Và nếu quý vị lo ngại rằng báo cáo sẽ không kịp đến trước thứ Tư, xin vui lòng liên hệ với ông Matt Harven và nhắc nhở ông ấy gửi bản tóm tắt cho chúng tôi càng sớm càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Susan Gowan 9:23 A.M.\", \"vi\": \"Susan Gowan, 9 giờ 23 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday?\", \"vi\": \"Giả sử chúng ta nhận được bản tóm tắt đó sớm đủ để đưa các kết quả vào các trang trình chiếu, liệu ba chúng ta có nên lên lịch để diễn tập bài thuyết trình vào thứ Năm hoặc thứ Sáu không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Maggie Lorenz 9:24 A.M.\", \"vi\": \"Maggie Lorenz 9 giờ 24 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Let\'s try for Thursday afternoon.\", \"vi\": \"Chúng ta hãy thử sắp xếp vào chiều thứ Năm xem sao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Then we will still have Friday to make any necessary changes.\", \"vi\": \"Như vậy, chúng ta vẫn còn ngày thứ Sáu để thực hiện bất kỳ thay đổi cần thiết nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Alan Woodson 9:25 A.M.\", \"vi\": \"Alan Woodson, 9 giờ 25 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Fine by me.\", \"vi\": \"Tôi thấy không sao cả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I\'m free after 2 P.M.\", \"vi\": \"Tôi rảnh sau 2 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '97f2a7be-29ec-402d-a699-7e9359a19850';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Sandra Barga <sbarga97@hjmail.ca>\", \"vi\": \"Đến: Sandra Barga <sbarga97@hjmail.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Artie Romanche <service@northwestbags.ca>\", \"vi\": \"Từ: Artie Romanche <service@northwestbags.ca>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 12 July\", \"vi\": \"Ngày: 12 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Order number 71280\", \"vi\": \"Chủ đề: Đơn hàng số 71280\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Barga:\", \"vi\": \"Kính gửi bà Barga,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We received your recent order asking for your name to be stitched on a Klamath Kool handbag.\", \"vi\": \"Chúng tôi đã nhận được đơn hàng gần đây của quý khách yêu cầu thêu tên của quý khách lên một chiếc túi xách Klamath Kool.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We are, ___139___, eager to complete your order.\", \"vi\": \"Chúng tôi, ___139___, rất mong muốn được hoàn thành đơn hàng của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [139]}, {\"en\": \"Unfortunately, our seamstress who fulfills personalisation requirements will be on leave for the next three days.\", \"vi\": \"Thật không may, thợ may của chúng tôi, người đáp ứng các yêu cầu cá nhân hóa, sẽ nghỉ phép trong ba ngày tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We wanted to let you know that her ___140___ will cause a delay in shipping your bag.\", \"vi\": \"Chúng tôi muốn thông báo cho quý khách biết rằng sự ___140___ của cô ấy sẽ gây ra sự chậm trễ trong việc vận chuyển chiếc túi của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [140]}, {\"en\": \"___141___ for the wait, we would like to offer you a 10 percent discount on your current order.\", \"vi\": \"___141___ cho thời gian chờ đợi, chúng tôi muốn dành tặng quý khách mức giảm giá 10 phần trăm cho đơn hàng hiện tại của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [141]}, {\"en\": \"Or, if you prefer, you can opt for free personalisation on your next order.\", \"vi\": \"Hoặc, nếu quý khách thích hơn, quý khách có thể chọn dịch vụ cá nhân hóa miễn phí cho đơn hàng tiếp theo của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"___142___.\", \"vi\": \"___142___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [142]}, {\"en\": \"At Northwest Bags, we strive for 100 percent customer satisfaction!\", \"vi\": \"Tại Northwest Bags, chúng tôi phấn đấu vì sự hài lòng 100 phần trăm của khách hàng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Artie Romanche\", \"vi\": \"Artie Romanche\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Customer Service Representative, Northwest Bags\", \"vi\": \"Nhân viên Dịch vụ Khách hàng, Northwest Bags\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '97f636bf-3a60-4e1b-bf69-d3fa323b5ec8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All staff\", \"vi\": \"Đến: Tất cả nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Management\", \"vi\": \"Từ: Ban quản lý\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: October 10\", \"vi\": \"Ngày: Ngày 10 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Re: Move to new office\", \"vi\": \"V/v: Chuyển đến văn phòng mới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Preparations for the move to our new office are scheduled to take place on Thursday and Friday of next week.\", \"vi\": \"Công tác chuẩn bị cho việc chuyển đến văn phòng mới của chúng ta dự kiến sẽ diễn ra vào thứ Năm và thứ Sáu tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"---139--- for this are going to be distributed to each employee\'s cubicle in advance.\", \"vi\": \"---139--- cho việc này sẽ được phân phát trước đến bàn làm việc của từng nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [139]}, {\"en\": \"Boxes, tape, and markers ---140--- on Wednesday afternoon.\", \"vi\": \"Hộp các-tông, băng keo và bút đánh dấu ---140--- vào chiều thứ Tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [140]}, {\"en\": \"As you pack your belongings, please write your name and employee number on the top and sides of each box.\", \"vi\": \"Khi bạn đóng gói đồ đạc của mình, vui lòng viết tên và mã số nhân viên của bạn lên mặt trên và các cạnh của mỗi chiếc hộp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"---141---.\", \"vi\": \"---141---.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [141]}, {\"en\": \"A human resources employee will come around and record this number to ensure that all of your boxes are returned to you.\", \"vi\": \"Một nhân viên phòng nhân sự sẽ đi một vòng và ghi lại số này để đảm bảo rằng tất cả các hộp của bạn đều được gửi trả lại cho bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Please take any valuables home with you by Wednesday.\", \"vi\": \"Vui lòng mang theo bất kỳ vật có giá trị nào về nhà trước ngày thứ Tư.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The company will not be responsible for the loss of any items during the move.\", \"vi\": \"Công ty sẽ không chịu trách nhiệm đối với việc mất mát bất kỳ món đồ nào trong quá trình chuyển văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"No open food items may be packed.\", \"vi\": \"Không được đóng gói các loại thực phẩm đã mở nắp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"---142---, unopened packaged food, such as candy and crackers, may be boxed.\", \"vi\": \"---142---, thực phẩm đóng gói chưa mở, chẳng hạn như kẹo và bánh quy, có thể được đóng hộp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": [142]}, {\"en\": \"Thank you for your cooperation.\", \"vi\": \"Cảm ơn sự hợp tác của các bạn.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '98db8bf4-2c0c-4f78-aee0-e8b4b38a7647';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: riedewald@parasur.net.sr\", \"vi\": \"Gửi tới: riedewald@parasur.net.sr\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: client_services@mhf.ca\", \"vi\": \"Nguồn: client_services@mhf.ca\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: April 2, 12:21 P.M.\", \"vi\": \"Ngày: 2 tháng 4, 12 giờ 21 phút chiều\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Your feedback\", \"vi\": \"Chủ đề: Ý kiến phản hồi của quý vị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Riedewald,\", \"vi\": \"Kính gửi ông Riedewald,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for filling out the McMann Home Furnishings (MHF) survey.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã dành thời gian điền vào bản khảo sát của McMann Home Furnishings (MHF).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To show our appreciation, we have added reward points to your account.\", \"vi\": \"Để bày tỏ lòng biết ơn, chúng tôi đã cộng điểm thưởng vào tài khoản của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"They can be applied to the purchase of products offered online as well as those offered in our retail stores.\", \"vi\": \"Các ưu đãi này có thể được áp dụng cho việc mua các sản phẩm được bán trực tuyến cũng như các sản phẩm được bày bán tại các cửa hàng bán lẻ của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Clearance items and those priced $15.00 and above may not be purchased using credits.\", \"vi\": \"Các mặt hàng thanh lý và những mặt hàng có giá từ 15,00 USD trở lên không được phép thanh toán bằng điểm thưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To use your reward points for an online purchase, select the items you would like to purchase and then check out.\", \"vi\": \"Để sử dụng điểm thưởng của quý khách cho một giao dịch mua hàng trực tuyến, vui lòng chọn các mặt hàng quý khách muốn mua và sau đó tiến hành thanh toán.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"At the bottom of the page, select \\\"Apply credits.\\\"\", \"vi\": \"Ở cuối trang, quý vị hãy chọn “Áp dụng tín dụng.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The value of the applied credits will appear on your order receipt as a special discount.\", \"vi\": \"Giá trị của các khoản tín dụng đã được áp dụng sẽ được hiển thị trên biên lai đặt hàng của quý vị dưới dạng một khoản giảm giá đặc biệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"If you would prefer to use reward points at one of our retail locations, you can do so by logging in to your account on our Web site.\", \"vi\": \"Nếu Quý khách muốn sử dụng điểm thưởng tại một trong các cửa hàng bán lẻ của chúng tôi, Quý khách có thể thực hiện điều này bằng cách đăng nhập vào tài khoản của mình trên trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Go to the My Rewards page, and then select \\\"Print as a coupon.\\\"\", \"vi\": \"Vui lòng truy cập trang “My Rewards”, sau đó chọn “In dưới dạng phiếu giảm giá”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The coupon will have a bar code that can be scanned at the store\'s checkout counter.\", \"vi\": \"Phiếu giảm giá sẽ có mã vạch có thể được quét tại quầy thanh toán của cửa hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Client Services, McMann Home Furnishings\", \"vi\": \"Bộ phận Dịch vụ Khách hàng, McMann Home Furnishings\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Online Order #1157\", \"vi\": \"Đơn hàng trực tuyến số 1157\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"McMann Home Furnishings Store\", \"vi\": \"Cửa hàng nội thất McMann\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"March 19, 11:31 A.M.\", \"vi\": \"Ngày 19 tháng 3, 11 giờ 31 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Hand-Painted Picture Frame\", \"vi\": \"Khung ảnh vẽ tay\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Quantity: 1\", \"vi\": \"Số lượng: 1\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Price: 10.00\", \"vi\": \"Giá: 10,00\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Special Discount: -10.00\", \"vi\": \"Ưu đãi đặc biệt: -10,00\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Sailboat Ceramic Mug\", \"vi\": \"Cốc gốm hình thuyền buồm\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Quantity: 4\", \"vi\": \"Số lượng: 4\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Price: 40.00\", \"vi\": \"Giá: 40,00\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Clearance Discount: -20.00\", \"vi\": \"Giảm giá thanh lý: -20,00\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Floral Blanket\", \"vi\": \"Chăn hoa\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Quantity: 1\", \"vi\": \"Số lượng: 1\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Price: 25.00\", \"vi\": \"Giá: 25,00\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Photo Album\", \"vi\": \"Album ảnh\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Quantity: 1\", \"vi\": \"Số lượng: 1\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Price: 34.00\", \"vi\": \"Giá: 34,00\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Seasonal Item Discount: -17.00\", \"vi\": \"Giảm giá sản phẩm theo mùa: -17,00\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Item total: 62.00\", \"vi\": \"Tổng số mặt hàng: 62,00\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Shipping: Free\", \"vi\": \"Phí vận chuyển: Miễn phí\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Total: 62.00\", \"vi\": \"Tổng cộng: 62,00\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 38, \"question_numbers\": []}]' WHERE `id` = '991ac2f3-35f6-44f4-a6fc-66a5126d371d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: efeehan@rossfieldhotels.ie\", \"vi\": \"Nguồn: efeehan@rossfieldhotels.ie\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: customerservice@parleganispublishing.com\", \"vi\": \"Gửi tới: customerservice@parleganispublishing.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 15 December\", \"vi\": \"Ngày: 15 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Sent: Course books\", \"vi\": \"Đã gửi: Sách giáo trình\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Customer Service Representative:\", \"vi\": \"Kính gửi Quý nhân viên bộ phận Chăm sóc khách hàng:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"In October my company ordered 60 paperback copies of the Food Safety Course Book for our employees so they could study for their mandatory food safety certification.\", \"vi\": \"Vào tháng 10, công ty tôi đã đặt mua 60 cuốn sách bìa mềm thuộc bộ “Sách khóa học An toàn thực phẩm” dành cho các nhân viên, nhằm giúp họ ôn tập để thi lấy chứng chỉ an toàn thực phẩm bắt buộc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I just learned from one of our managers that you offer this course book in languages other than English.\", \"vi\": \"Tôi vừa được biết từ một trong các quản lý của chúng tôi rằng quý vị có cung cấp cuốn sách giáo trình này bằng các ngôn ngữ khác ngoài tiếng Anh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"May I send back twenty of the English language versions and get ten Polish and ten Portuguese books instead?\", \"vi\": \"Tôi có thể gửi trả lại hai mươi cuốn bản tiếng Anh và đổi lấy mười cuốn tiếng Ba Lan cùng mười cuốn tiếng Bồ Đào Nha được không ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Some of our new employees said they would really appreciate being able to read the crucial information in their first language.\", \"vi\": \"Một số nhân viên mới của chúng tôi cho biết họ sẽ thực sự đánh giá cao việc có thể đọc những thông tin quan trọng bằng ngôn ngữ mẹ đẻ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The books I wish to return are still in their original packaging.\", \"vi\": \"Những cuốn sách mà tôi muốn trả lại vẫn còn nguyên trong bao bì ban đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I can have them boxed and shipped quickly, but I will wait for your acknowledgement and instructions regarding paperwork.\", \"vi\": \"Tôi có thể đóng gói và gửi hàng ngay lập tức, nhưng tôi sẽ chờ nhận được xác nhận và hướng dẫn của quý vị về các thủ tục giấy tờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Ella Feehan\", \"vi\": \"Ella Feehan\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Food Services Director\", \"vi\": \"Giám đốc Dịch vụ Ẩm thực\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Rossfield Hotels Ltd.\", \"vi\": \"Công ty TNHH Rossfield Hotels\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Parleganis Publishing\", \"vi\": \"Nhà xuất bản Parleganis\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Returns and Exchanges Policy\", \"vi\": \"Chính sách đổi trả hàng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"We accept products under the following conditions.\", \"vi\": \"Chúng tôi chấp nhận các sản phẩm theo các điều kiện sau đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Unmarked, unused materials may be returned or exchanged within 90 days of purchase.\", \"vi\": \"Các sản phẩm chưa có dấu hiệu sử dụng và chưa qua sử dụng có thể được trả lại hoặc đổi trong vòng 90 ngày kể từ ngày mua.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Items returned or exchanged more than 30 days after purchase are subject to a restocking fee equal to 20% of the cover price.\", \"vi\": \"Các mặt hàng được trả lại hoặc đổi sau hơn 30 ngày kể từ ngày mua sẽ phải chịu phí nhập kho bằng 20% giá bìa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Paperback books come in plastic-wrapped bundles of ten.\", \"vi\": \"Sách bìa mềm được đóng gói thành từng bó mười cuốn, mỗi bó được bọc bằng màng nhựa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Unopened bundles may be returned for full credit.\", \"vi\": \"Các gói hàng chưa mở có thể được trả lại để nhận lại toàn bộ số tiền.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Individual paperback books will receive partial credit.\", \"vi\": \"Mỗi cuốn sách bìa mềm sẽ được tính một phần điểm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Software products and subscription fees are not refundable.\", \"vi\": \"Các sản phẩm phần mềm và phí đăng ký không được hoàn lại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"No credit will be issued for damaged or out-of-print books.\", \"vi\": \"Sách bị hư hỏng hoặc đã ngừng xuất bản sẽ không được hoàn tiền.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = '996fc425-ec77-4e86-b3c0-52e7907946b4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.sagemontservices.com\", \"vi\": \"https://www.sagemontservices.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Home | About Us | IT Services | Client Testimonials\", \"vi\": \"Trang chủ | Giới thiệu | Dịch vụ CNTT | Lời chứng thực từ khách hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"At Sagemont Services, we offer custom-tailored information technology solutions to clients in various industries.\", \"vi\": \"Tại Sagemont Services, chúng tôi cung cấp các giải pháp công nghệ thông tin được thiết kế riêng cho khách hàng thuộc nhiều ngành nghề khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Founded over twenty years ago, Sagemont Services began as a start-up competing with larger businesses in a crowded field.\", \"vi\": \"Được thành lập cách đây hơn hai mươi năm, Sagemont Services khởi đầu là một công ty khởi nghiệp phải cạnh tranh với các doanh nghiệp quy mô lớn hơn trong một lĩnh vực có sự cạnh tranh gay gắt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Subsequently, we have become a leader in the industry.\", \"vi\": \"Từ đó, chúng tôi đã trở thành một trong những doanh nghiệp dẫn đầu trong ngành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our expert staff members are cross-trained in every aspect of our services.\", \"vi\": \"Đội ngũ nhân viên chuyên môn của chúng tôi đã được đào tạo đa năng về mọi khía cạnh của các dịch vụ mà chúng tôi cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We have helped several businesses complete technology projects on tight deadlines in the past few months.\", \"vi\": \"Trong vài tháng qua, chúng tôi đã hỗ trợ nhiều doanh nghiệp hoàn thành các dự án công nghệ trong thời hạn rất gấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"For example, with the online retailer Clothing Discounters rapidly expanding, we assisted the company in increasing its call-center capability.\", \"vi\": \"Chẳng hạn, trước bối cảnh nhà bán lẻ trực tuyến Clothing Discounters đang mở rộng quy mô nhanh chóng, chúng tôi đã hỗ trợ công ty này nâng cao năng lực của trung tâm chăm sóc khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Specifically, in just two days, we provided the company with all the equipment and connections needed for newly hired customer-service agents to handle calls from home.\", \"vi\": \"Cụ thể, chỉ trong vòng hai ngày, chúng tôi đã cung cấp cho công ty toàn bộ thiết bị và các kết nối cần thiết để các nhân viên chăm sóc khách hàng mới được tuyển dụng có thể xử lý các cuộc gọi từ nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To learn more about how we meet the needs of our customers, please visit the Client Testimonials page.\", \"vi\": \"Để tìm hiểu thêm về cách chúng tôi đáp ứng nhu cầu của khách hàng, xin vui lòng truy cập trang “Lời chia sẻ của khách hàng”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = '997d3962-d83f-44fd-95a3-2e308647228c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Elvinna\'s\", \"vi\": \"Của Elvinna\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Located just outside of Nassau, the capital city of The Bahamas, Elvinna\'s is the ideal venue for your reception, banquet, or business meeting.\", \"vi\": \"Tọa lạc ngay ngoại ô Nassau, thủ đô của Bahamas, Elvinna\'s là địa điểm lý tưởng cho tiệc chiêu đãi, tiệc chiêu đãi hoặc cuộc họp kinh doanh của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Away from the hustle and bustle of the city, it is surrounded by lush gardens featuring a variety of beautiful sculptures.\", \"vi\": \"Nằm cách xa sự nhộn nhịp của thành phố, nơi đây được bao quanh bởi những khu vườn xanh mát với nhiều tác phẩm điêu khắc tuyệt đẹp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The Alameda Room seats between 100 and 250 people comfortably, and our largest space, the Bougainvillea Room, is perfect for up to 300 guests.\", \"vi\": \"Phòng Alameda có thể chứa từ 100 đến 250 người một cách thoải mái, còn không gian lớn nhất của chúng tôi, Phòng Bougainvillea, là lựa chọn lý tưởng cho các sự kiện có tối đa 300 khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"For business meetings, the Tamarind Room can accommodate up to 50 guests, while the Waterfall Room, slightly larger, seats up to 80 people.\", \"vi\": \"Đối với các cuộc họp kinh doanh, phòng Tamarind có thể tiếp đón tối đa 50 khách, trong khi phòng Waterfall, rộng hơn một chút, có sức chứa tối đa 80 người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our two business meeting spaces are outfitted with the latest technology to support productive and efficient meetings.\", \"vi\": \"Hai không gian tổ chức hội nghị của chúng tôi được trang bị công nghệ tiên tiến nhất nhằm hỗ trợ các cuộc họp diễn ra hiệu quả và mang lại kết quả cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our elegant restaurant, the Candlewood Tree, offers an ample menu that takes into account many dietary restrictions and preferences.\", \"vi\": \"Nhà hàng sang trọng của chúng tôi, Candlewood Tree, mang đến thực đơn phong phú, đáp ứng nhiều yêu cầu và sở thích về chế độ ăn uống khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Plan ahead to join us on July 10 when we offer a special Independence Day dinner menu!\", \"vi\": \"Hãy lên kế hoạch trước để cùng chúng tôi đón ngày 10 tháng 7, khi chúng tôi sẽ giới thiệu thực đơn bữa tối đặc biệt nhân dịp Ngày Độc lập!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"To book an event, visit elvinnas.bs.\", \"vi\": \"Để đặt chỗ cho một sự kiện, vui lòng truy cập elvinnas.bs.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"First-time reservations for select days receive a 15 percent discount.\", \"vi\": \"Các đơn đặt chỗ lần đầu tiên vào những ngày được chọn sẽ được hưởng mức giảm giá 15%.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"For further information call 242-555-0135.\", \"vi\": \"Để biết thêm thông tin, xin vui lòng gọi số 242-555-0135.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: Tanika Nichols\", \"vi\": \"Kính gửi: Tanika Nichols\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From: Brian Darville\", \"vi\": \"Từ: Brian Darville\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: 18 February\", \"vi\": \"Ngày: 18 tháng 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Subject: Anniversary planning\", \"vi\": \"Chủ đề: Lập kế hoạch kỷ niệm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Hello, Tanika,\", \"vi\": \"Xin chào, Tanika,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I visited Elvinna\'s and looked at the space that you suggested might be right for our company\'s anniversary celebration.\", \"vi\": \"Tôi đã ghé thăm Elvinna\'s và xem xét địa điểm mà quý vị đã đề xuất, cho rằng có thể phù hợp để tổ chức lễ kỷ niệm thành lập công ty chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Their catering menu would suit the various preferences of our expected guests, now numbering over 250.\", \"vi\": \"Thực đơn tiệc của họ sẽ phù hợp với các sở thích đa dạng của các vị khách dự kiến tham dự, hiện đã lên tới hơn 250 người.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Currently the room is available on two Saturdays, 15 July and 5 August; it is also available on Wednesday, 23 August.\", \"vi\": \"Hiện tại, phòng này còn trống vào hai ngày thứ Bảy, ngày 15 tháng 7 và ngày 5 tháng 8; ngoài ra, phòng cũng còn trống vào thứ Tư, ngày 23 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Note that this last date would qualify for a nice discount.\", \"vi\": \"Xin lưu ý rằng ngày cuối cùng này sẽ được hưởng một mức giảm giá hấp dẫn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Let me know if I have your approval to book this room.\", \"vi\": \"Xin vui lòng cho tôi biết liệu tôi có được sự đồng ý của quý vị để đặt phòng này hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"We need to make a decision quickly before other parties reserve those dates.\", \"vi\": \"Chúng ta cần phải đưa ra quyết định càng sớm càng tốt trước khi các bên khác đặt trước những ngày đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I\'ll be in touch soon about rescheduling the awards ceremony in May.\", \"vi\": \"Tôi sẽ sớm liên hệ với quý vị để bàn về việc điều chỉnh lịch tổ chức lễ trao giải vào tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Brian\", \"vi\": \"Brian\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"To: Brian Darville\", \"vi\": \"Kính gửi: Ông Brian Darville\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"From: Tanika Nichols\", \"vi\": \"Từ: Tanika Nichols\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date: 18 February\", \"vi\": \"Ngày: 18 tháng 2\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Subject: Anniversary planning\", \"vi\": \"Chủ đề: Kế hoạch tổ chức kỷ niệm\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Hello, Brian,\", \"vi\": \"Xin chào, Brian,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Thank you for the information about Elvinna\'s.\", \"vi\": \"Xin cảm ơn quý vị đã cung cấp thông tin về Elvinna\'s.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Let\'s take advantage of that discount date they are offering.\", \"vi\": \"Chúng ta hãy tận dụng đợt giảm giá mà họ đang triển khai.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"It may help us stay within our budget.\", \"vi\": \"Điều này có thể giúp chúng ta không vượt quá ngân sách.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Please contact them to make the reservation.\", \"vi\": \"Xin vui lòng liên hệ với họ để đặt chỗ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Tanika Nichols, Senior Vice President\", \"vi\": \"Bà Tanika Nichols, Phó Chủ tịch Cấp cao\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Nassau Telecommunications\", \"vi\": \"Công ty Viễn thông Nassau\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '99aa4d2c-6260-44de-92ac-b106f2facac1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Customer Service <customerservice@takembootcompany.com>\", \"vi\": \"Gửi: Bộ phận Chăm sóc Khách hàng <customerservice@takembootcompany.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Bella Meyers <b.meyers@leadmail.com>\", \"vi\": \"Từ: Bella Meyers <b.meyers@leadmail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 15 August\", \"vi\": \"Ngày: 15 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Order 13783\", \"vi\": \"Chủ đề: Lệnh số 13783\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"To: Bella Meyers <b.meyers@leadmail.com>\", \"vi\": \"Gửi: Bella Meyers <b.meyers@leadmail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"From: Customer Service <customerservice@takembootcompany.com>\", \"vi\": \"Từ: Bộ phận Dịch vụ Khách hàng <customerservice@takembootcompany.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Date: 16 August\", \"vi\": \"Ngày: 16 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Subject: RE: Order 13783\", \"vi\": \"Chủ đề: RE: Lệnh số 13783\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Xin chào,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I recently ordered a pair of your Western boots in style Erin, size 40, in the chocolate colour.\", \"vi\": \"Gần đây, tôi đã đặt mua một đôi giày bốt phong cách miền Tây của quý công ty, mẫu Erin, cỡ 40, màu sô-cô-la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The boots arrived yesterday, but unfortunately, their actual colour is different from the colour pictured on your Web site.\", \"vi\": \"Đôi bốt đã được giao đến hôm qua, nhưng rất tiếc, màu sắc thực tế của chúng lại khác với màu được hiển thị trên trang web của quý công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I had been hoping to wear the boots to a special event next month, but they are much darker than expected and do not match my planned outfit.\", \"vi\": \"Tôi đã hy vọng sẽ mang đôi bốt này đến một sự kiện đặc biệt vào tháng tới, nhưng màu của chúng sẫm hơn nhiều so với dự kiến và không hợp với bộ trang phục mà tôi đã lên kế hoạch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I would like to exchange the boots for another pair of the same style and size but in the terracotta colour.\", \"vi\": \"Tôi muốn đổi đôi bốt này lấy một đôi khác cùng kiểu dáng và cỡ nhưng có màu đất nung.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please let me know how to proceed.\", \"vi\": \"Xin vui lòng cho tôi biết nên tiến hành như thế nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I have purchased several pairs of boots from your company in the past and have always been pleased with their durability and comfort.\", \"vi\": \"Trước đây, tôi đã mua vài đôi ủng từ công ty quý vị và luôn cảm thấy hài lòng về độ bền cũng như sự thoải mái của chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Bella Meyers\", \"vi\": \"Meyer xinh đẹp\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Dear Ms. Meyers,\", \"vi\": \"Kính gửi bà Meyers,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Thank you for your e-mail.\", \"vi\": \"Xin cảm ơn quý vị đã gửi email.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I am sorry you were disappointed with your order.\", \"vi\": \"Tôi rất tiếc vì quý khách đã cảm thấy thất vọng với đơn hàng của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"We are happy to arrange an exchange as long as the boots you wish to return have not been worn.\", \"vi\": \"Chúng tôi rất sẵn lòng hỗ trợ quý khách đổi hàng, miễn là đôi bốt quý khách muốn trả lại chưa từng được mang.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"At the moment, boots in the size, style, and colour you are requesting are out of stock.\", \"vi\": \"Hiện tại, những đôi bốt có kích cỡ, kiểu dáng và màu sắc mà quý khách yêu cầu đã hết hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Because we are a small company, our inventory is not always fully available.\", \"vi\": \"Do chúng tôi là một công ty quy mô nhỏ, nên hàng tồn kho của chúng tôi không phải lúc nào cũng có sẵn đầy đủ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Other than what you have purchased, we currently have the Erin boots of your size in the following colours: sand and forest.\", \"vi\": \"Ngoài những sản phẩm quý khách đã mua, hiện tại chúng tôi còn có mẫu giày bốt Erin đúng cỡ của quý khách với các màu sau: màu cát và màu rừng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Since you are interested in a paler colour, I recommend sand.\", \"vi\": \"Vì quý vị quan tâm đến một màu nhạt hơn, tôi xin đề xuất màu cát.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"It is a warm shade and very versatile.\", \"vi\": \"Đây là một tông màu ấm và rất linh hoạt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Additionally, we have other styles available in your preferred colour, including Viola boots, our most popular style.\", \"vi\": \"Ngoài ra, chúng tôi còn có các mẫu giày khác với màu sắc mà quý khách ưa thích, bao gồm cả mẫu giày bốt Viola – mẫu giày được ưa chuộng nhất của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Please let me know if you would like to exchange your boots for any of the above options.\", \"vi\": \"Nếu quý vị muốn đổi đôi ủng của mình lấy bất kỳ lựa chọn nào trong số các lựa chọn nêu trên, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"If so, I can send you a postage-paid return label via e-mail for you to print at home.\", \"vi\": \"Nếu vậy, tôi có thể gửi cho quý vị một nhãn trả hàng đã thanh toán cước phí qua email để quý vị có thể in tại nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Thank you for your business.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã tin dùng sản phẩm của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"If you have not signed up for our newsletter yet, I suggest you do.\", \"vi\": \"Nếu quý vị chưa đăng ký nhận bản tin của chúng tôi, tôi khuyên quý vị nên đăng ký.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"We offer discounts on discontinued styles.\", \"vi\": \"Chúng tôi áp dụng mức giảm giá cho các mẫu sản phẩm đã ngừng kinh doanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Brendan Stephens, Customer Service Representative\", \"vi\": \"Brendan Stephens, Nhân viên Dịch vụ Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Takem Boot Company\", \"vi\": \"Công ty Takem Boot\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = '99e12c48-ebbd-4303-ad3b-e0a54dd101e7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ben\'s Nonprofit Burst—Resources for those who work in the nonprofit sector\", \"vi\": \"Chuyên mục “Nonprofit Burst” của Ben — Các nguồn tài nguyên dành cho những người làm việc trong lĩnh vực phi lợi nhuận\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Getting Grants\", \"vi\": \"Xin tài trợ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Posted on August 18 by Ben Fineman\", \"vi\": \"Được đăng vào ngày 18 tháng 8 bởi Ben Fineman\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Grant writing is the art of completing applications for financial aid offered by government agencies, schools, corporations, or other entities.\", \"vi\": \"Viết đề xuất xin tài trợ là nghệ thuật hoàn thiện các hồ sơ xin hỗ trợ tài chính do các cơ quan chính phủ, trường học, tập đoàn hoặc các tổ chức khác cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"There is huge competition for grants and no room for mediocrity in grant writing.\", \"vi\": \"Sự cạnh tranh trong việc xin tài trợ là vô cùng gay gắt và không có chỗ cho sự tầm thường trong việc soạn thảo hồ sơ xin tài trợ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"To improve your grant-writing skills, consider taking an online course taught by Kristina Gilliam of Meadow Park University.\", \"vi\": \"Để nâng cao kỹ năng soạn thảo hồ sơ xin tài trợ, quý vị hãy cân nhắc tham gia một khóa học trực tuyến do bà Kristina Gilliam của Đại học Meadow Park giảng dạy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Her Writing Great Grants course is divided into four 90-minute interactive sessions.\", \"vi\": \"Khóa học “Viết Đơn Xin Tài Trợ Hiệu Quả” của bà được chia thành bốn buổi học tương tác, mỗi buổi kéo dài 90 phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It is designed for people with some basic knowledge of grant writing.\", \"vi\": \"Khóa học này được thiết kế dành cho những người đã có một số kiến thức cơ bản về việc soạn thảo hồ sơ xin tài trợ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"These Monday evening classes run from November 15 to December 6.\", \"vi\": \"Các lớp học vào tối thứ Hai này sẽ diễn ra từ ngày 15 tháng 11 đến ngày 6 tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"For details and registration, visit www.kristinagilliam.ca/course.\", \"vi\": \"Để biết thêm chi tiết và đăng ký, vui lòng truy cập trang web www.kristinagilliam.ca/course.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Use the promo code NPBURST at checkout to get 15 percent off the $350 tuition.\", \"vi\": \"Hãy sử dụng mã khuyến mãi NPBURST khi thanh toán để được giảm 15% học phí trị giá 350 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"This code expires on September 30.\", \"vi\": \"Mã này sẽ hết hạn vào ngày 30 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"On October 1, only full-price registration will be available until the final registration day, November 1.\", \"vi\": \"Từ ngày 1 tháng 10, chỉ còn hình thức đăng ký với mức phí đầy đủ cho đến ngày cuối cùng nhận đăng ký là ngày 1 tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"www.kristinagilliam.ca/feedback\", \"vi\": \"www.kristinagilliam.ca/feedback\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Thank you for participating in my Writing Great Grants course.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã tham gia khóa học “Viết Đề Xuất Tài Trợ Xuất Sắc” của tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Please take a moment to tell me about your experience by filling out the form below.\", \"vi\": \"Xin quý vị vui lòng dành một chút thời gian để chia sẻ trải nghiệm của mình bằng cách điền vào biểu mẫu dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Name: Natalie Ballard\", \"vi\": \"Họ và tên: Natalie Ballard\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Location: Winnipeg\", \"vi\": \"Địa điểm: Winnipeg\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Comment: Relatively short compared to other writing courses I\'ve taken, Writing Great Grants provided a decent overview.\", \"vi\": \"Nhận xét: Mặc dù thời lượng tương đối ngắn so với các khóa học viết khác mà tôi đã tham gia, khóa học “Writing Great Grants” đã mang đến một cái nhìn tổng quan khá đầy đủ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I was impressed to learn that the instructor helped companies get millions of dollars in grants during her career, and I\'m glad to now have her as a resource if I ever get hired as a grant writer.\", \"vi\": \"Tôi thực sự ấn tượng khi biết rằng trong suốt sự nghiệp của mình, giảng viên này đã giúp các công ty nhận được hàng triệu đô la tiền tài trợ, và tôi rất vui vì giờ đây có thể xem bà như một nguồn tham khảo quý báu nếu như tôi được tuyển dụng vào vị trí chuyên viên soạn thảo hồ sơ xin tài trợ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Fortunately, I used Ben\'s Nonprofit Burst\'s promo code when I registered.\", \"vi\": \"May mắn thay, tôi đã sử dụng mã khuyến mãi của Ben’s Nonprofit Burst khi đăng ký.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Otherwise, I\'d have considered the tuition too high.\", \"vi\": \"Nếu không, tôi đã cho rằng học phí quá cao rồi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"The Web site gave me the impression that Ms. Gilliam would include more specifics about the actual writing process than she did.\", \"vi\": \"Trang web này khiến tôi có ấn tượng rằng bà Gilliam sẽ đề cập cụ thể hơn về quá trình viết thực tế so với những gì bà đã trình bày.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"www.kristinagilliam.ca/feedback\", \"vi\": \"www.kristinagilliam.ca/feedback\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Thank you for participating in my Writing Great Grants course.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã tham gia khóa học “Viết Đề Xuất Tài Trợ Xuất Sắc” của tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Please take a moment to tell me about your experience by filling out the form below.\", \"vi\": \"Xin quý vị vui lòng dành một chút thời gian để chia sẻ trải nghiệm của mình bằng cách điền vào biểu mẫu dưới đây.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Name: Paul Voigt\", \"vi\": \"Họ tên: Paul Voigt\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Location: Toronto\", \"vi\": \"Địa điểm: Toronto\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Comment: This was a great course overall.\", \"vi\": \"Nhận xét: Nhìn chung, đây là một khóa học rất hay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"The instructor shared a wealth of valuable insights, including her experiences as the founder of Orden International.\", \"vi\": \"Giảng viên đã chia sẻ rất nhiều kiến thức quý báu, trong đó có những trải nghiệm của bà với tư cách là người sáng lập Orden International.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I never realized that grant-writing firms even existed!\", \"vi\": \"Tôi chưa bao giờ ngờ rằng lại có những công ty chuyên soạn thảo hồ sơ xin tài trợ như vậy!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I might start one of my own if I ever leave my current grant-writing job.\", \"vi\": \"Nếu một ngày nào đó tôi rời bỏ công việc soạn thảo đề xuất tài trợ hiện tại, có lẽ tôi sẽ tự mình thành lập một tổ chức riêng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"The course focused mainly on researching grant opportunities and analyzing samples of successful grant applications.\", \"vi\": \"Khóa học chủ yếu tập trung vào việc tìm kiếm các cơ hội nhận tài trợ và phân tích các mẫu đơn xin tài trợ đã thành công.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"When several of us asked for specific writing tips during the final session, Ms. Gilliam simply referred us to other resources.\", \"vi\": \"Khi một số người trong chúng tôi đề nghị được chia sẻ những lời khuyên cụ thể về kỹ năng viết trong buổi học cuối cùng, cô Gilliam chỉ đơn giản là giới thiệu cho chúng tôi tham khảo các nguồn tài liệu khác.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"The course description on her Web site was a bit misleading in that regard.\", \"vi\": \"Mô tả khóa học trên trang web của cô ấy có phần gây hiểu lầm về mặt này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '9a38a887-aebc-4f8d-b9ca-8867286c15c0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Customer Service Team\", \"vi\": \"Kính gửi: Đội ngũ Dịch vụ Khách hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Scott Davis, Director of Customer Service\", \"vi\": \"Từ: Scott Davis, Giám đốc Dịch vụ Khách hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: July 22\", \"vi\": \"Ngày: 22 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Today kicks off Harkness Clothiers’ Customer Service Appreciation Week.\", \"vi\": \"Hôm nay là ngày khởi động Tuần lễ Tri ân Khách hàng của Harkness Clothiers.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I want to take this opportunity to thank you for your dedication and professionalism this year.\", \"vi\": \"Tôi xin nhân dịp này gửi lời cảm ơn đến quý vị vì sự tận tâm và tinh thần chuyên nghiệp mà quý vị đã thể hiện trong năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Each one of you has delivered exceptional customer service.\", \"vi\": \"Mỗi người trong số quý vị đều đã cung cấp dịch vụ khách hàng xuất sắc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Management is proud of what you have achieved as a team.\", \"vi\": \"Ban lãnh đạo rất tự hào về những thành tựu mà quý vị đã đạt được với tư cách là một tập thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We understand that last year’s merger with Sporting Clothes, Inc., was confusing and difficult at times.\", \"vi\": \"Chúng tôi hiểu rằng việc sáp nhập với Công ty Sporting Clothes, Inc. vào năm ngoái đôi khi đã gây ra sự bối rối và khó khăn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Your service stayed steady throughout the process and you provided a seamless transition for our clients.\", \"vi\": \"Dịch vụ của quý vị đã duy trì sự ổn định trong suốt quá trình và quý vị đã đảm bảo sự chuyển giao suôn sẻ cho các khách hàng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"What a great accomplishment!\", \"vi\": \"Thật là một thành tựu tuyệt vời!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"On Tuesday, starting at 8 A.M., everyone will be treated to a breakfast served with coffee, pastries, and fruit.\", \"vi\": \"Vào thứ Ba, bắt đầu từ 8 giờ sáng, quý vị sẽ được thưởng thức bữa sáng gồm cà phê, bánh ngọt và trái cây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"On Wednesday, we will have a potluck lunch in the afternoon.\", \"vi\": \"Vào thứ Tư, chúng ta sẽ có một bữa trưa mang theo đồ ăn chung vào buổi chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"On Thursday, we will host a team dinner at Mo’s Bistro after work.\", \"vi\": \"Vào thứ Năm, sau giờ làm việc, chúng tôi sẽ tổ chức một bữa tối dành cho toàn đội tại Mo’s Bistro.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"On Friday, there will be contests after lunch where you can win prizes.\", \"vi\": \"Vào thứ Sáu, sau bữa trưa sẽ có các cuộc thi mà quý vị có thể tham gia để giành giải thưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I am excited about this week and hope you enjoy it.\", \"vi\": \"Tôi rất háo hức đón chờ tuần này và hy vọng quý vị sẽ có những giây phút thú vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '9ac40e2c-f301-4754-9b9c-544bb56e5029';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Regina\'s Art World Blog\", \"vi\": \"Blog Thế giới nghệ thuật của Regina\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"As regular readers of my blog know, over the past few weeks, I have concentrated on the revitalization of the Brentler Heights waterfront district by developer and former architect David Greeley.\", \"vi\": \"Như các độc giả thường xuyên theo dõi blog của tôi đã biết, trong vài tuần qua, tôi đã tập trung vào dự án tái phát triển khu vực ven sông Brentler Heights do nhà phát triển bất động sản kiêm cựu kiến trúc sư David Greeley thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"By far, the most impressive result of this program is the renovation of a former industrial building on Paxton Street.\", \"vi\": \"Cho đến nay, kết quả ấn tượng nhất của chương trình này chính là việc cải tạo một tòa nhà công nghiệp cũ trên đường Paxton.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The building’s first floor now houses a popular coffee shop and bookstore, and its beautifully landscaped gardens include creative metal sculptures.\", \"vi\": \"Tầng trệt của tòa nhà hiện là nơi tọa lạc của một quán cà phê và hiệu sách rất được ưa chuộng, còn những khu vườn được thiết kế cảnh quan tuyệt đẹp của tòa nhà còn có những tác phẩm điêu khắc kim loại đầy sáng tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am pleased to report that the second floor will be occupied by the Brentler Heights Gallery.\", \"vi\": \"Tôi xin vui mừng thông báo rằng tầng hai sẽ là nơi đặt Phòng trưng bày Brentler Heights.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The gallery will be run by Francine Skandar, a Brentler Heights artist I met years ago at a jewelry-making workshop.\", \"vi\": \"Phòng trưng bày này sẽ do bà Francine Skandar, một nghệ sĩ đến từ Brentler Heights mà tôi đã gặp cách đây nhiều năm tại một hội thảo chế tác trang sức, phụ trách điều hành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I always admired her work, and I obtained many of her creations to sell at my shop.\", \"vi\": \"Tôi luôn ngưỡng mộ những tác phẩm của cô ấy, và tôi đã thu mua rất nhiều tác phẩm của cô ấy để bày bán tại cửa hàng của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I was delighted to learn that she will be managing this high-profile gallery.\", \"vi\": \"Tôi vô cùng vui mừng khi biết rằng cô ấy sẽ đảm nhận vai trò quản lý phòng trưng bày danh tiếng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"On a media tour, Ms. Skandar highlighted how Mr. Greeley retained nearly all of the Paxton Street building’s original features to give it a vintage character.\", \"vi\": \"Trong chuyến tham quan dành cho giới truyền thông, bà Skandar đã nhấn mạnh cách ông Greeley đã giữ lại gần như toàn bộ các đặc điểm ban đầu của tòa nhà trên đường Paxton để tạo nên nét cổ kính cho công trình này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"This makes it an ideal backdrop for all types of art.\", \"vi\": \"Điều này khiến nơi đây trở thành bối cảnh lý tưởng cho mọi thể loại nghệ thuật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The gallery’s inaugural exhibit will showcase Ms. Skandar’s work.\", \"vi\": \"Triển lãm khai mạc của phòng tranh sẽ trưng bày các tác phẩm của bà Skandar.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The grand opening will occur on June 8 and 9 from 2:00 P.M. to 7:00 P.M. For more information, visit www.brentlerheightsgallery.org.\", \"vi\": \"Lễ khai trương sẽ diễn ra vào ngày 8 và 9 tháng 6, từ 2 giờ chiều đến 7 giờ tối. Để biết thêm thông tin, vui lòng truy cập trang web www.brentlerheightsgallery.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"—Regina Nguyen, May 2\", \"vi\": \"—Regina Nguyễn, ngày 2 tháng 5\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '9adb864e-e940-4090-898e-b323e9d4e67f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Liza Chu, IT Department\", \"vi\": \"Từ: Liza Chu, Phòng Công nghệ Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: June 8, 1:13 P.M.\", \"vi\": \"Ngày: 8 tháng 6, 1 giờ 13 phút chiều\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Network issues\", \"vi\": \"Chủ đề: Các sự cố mạng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Good afternoon everyone.\", \"vi\": \"Xin chào buổi chiều quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"At 10:00 this morning, the Information Technology team did some network maintenance, resulting in a series of issues across the building.\", \"vi\": \"Vào lúc 10 giờ sáng nay, đội ngũ Công nghệ Thông tin đã tiến hành một số công tác bảo trì mạng, dẫn đến một loạt sự cố xảy ra trên toàn tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We quickly received reports of printer malfunctions, missing network drives, difficulty loading e-mail messages, and other problems.\", \"vi\": \"Chúng tôi nhanh chóng nhận được các báo cáo về sự cố máy in, ổ đĩa mạng bị mất, khó khăn khi tải các thư điện tử, cùng một số vấn đề khác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We have now stabilized the situation, but if you should still encounter these or similar issues, please attempt first to address them by restarting your computer.\", \"vi\": \"Hiện tại, chúng tôi đã khắc phục được sự cố, tuy nhiên, nếu quý vị vẫn gặp phải những vấn đề này hoặc các vấn đề tương tự, xin vui lòng thử khắc phục bằng cách khởi động lại máy tính trước tiên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '9b03c8ad-e53c-443e-a33f-d1bf9fcb5eec';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Demarco Hines\", \"vi\": \"Kính gửi: Demarco Hines\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Soon Yi Park\", \"vi\": \"Từ: Soon Yi Park\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Item F208 (canvas overnight bag)\", \"vi\": \"Chủ đề: Mặt hàng F208 (túi du lịch qua đêm bằng vải bạt)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 19 June\", \"vi\": \"Ngày: 19 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Hines,\", \"vi\": \"Kính gửi ông Hines,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The Best Bags canvas overnight bag you ordered is not currently available in the colour you requested.\", \"vi\": \"Chiếc túi du lịch bằng vải canvas của thương hiệu Best Bags mà quý khách đã đặt hàng hiện không có sẵn với màu sắc mà quý khách yêu cầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"There are several options available to you.\", \"vi\": \"Quý vị có thể lựa chọn trong số một số phương án sau đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"1.\", \"vi\": \"1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Cancel your order, and we will gladly refund your money in full.\", \"vi\": \"Vui lòng hủy đơn hàng của quý khách, và chúng tôi sẽ sẵn lòng hoàn lại toàn bộ số tiền cho quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"2.\", \"vi\": \"2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Select a different colour.\", \"vi\": \"Vui lòng chọn một màu khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"That item is currently available in light blue, dark green, and dark gray.\", \"vi\": \"Hiện tại, sản phẩm này có sẵn các màu xanh nhạt, xanh đậm và xám đậm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"3.\", \"vi\": \"3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Choose an item of equal value from our Web site or catalogue.\", \"vi\": \"Quý khách vui lòng chọn một sản phẩm có giá trị tương đương trên trang web hoặc trong danh mục sản phẩm của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"4.\", \"vi\": \"4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Wait until the item you ordered is back in stock in light gray.\", \"vi\": \"Xin vui lòng chờ cho đến khi sản phẩm quý vị đã đặt hàng có sẵn trở lại với màu xám nhạt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Allow three to five weeks.\", \"vi\": \"Xin vui lòng dự kiến thời gian từ ba đến năm tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Please let us know which option you prefer.\", \"vi\": \"Xin vui lòng cho chúng tôi biết quý vị ưa thích phương án nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We apologize for any inconvenience.\", \"vi\": \"Chúng tôi xin lỗi vì những bất tiện này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Soon Yi Park, Customer Service Agent\", \"vi\": \"Bà Soon Yi Park, Nhân viên Dịch vụ Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '9b7fbc36-ea6d-42d9-a3d6-74363d09152d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Lucy O\'Malley (1:36 P.M.)\", \"vi\": \"Lucy O\'Malley (1 giờ 36 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"I am at the office, but I can\'t find the Miller file anywhere.\", \"vi\": \"Tôi đang ở văn phòng, nhưng tôi không thể tìm thấy tập hồ sơ của Miller ở đâu cả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Stanley Hamstead (1:37 P.M.)\", \"vi\": \"Stanley Hamstead (1 giờ 37 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Did you check in the future projects file cabinet?\", \"vi\": \"Quý vị đã kiểm tra trong tủ hồ sơ các dự án trong tương lai chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Lucy O\'Malley (1:39 P.M.)\", \"vi\": \"Lucy O\'Malley (1 giờ 39 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"No luck.\", \"vi\": \"Không may mắn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Any other ideas?\", \"vi\": \"Còn ý kiến nào khác không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Stanley Hamstead (1:40 P.M.)\", \"vi\": \"Stanley Hamstead (1 giờ 40 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I bet it is in Charles Wada\'s office.\", \"vi\": \"Tôi cá là nó đang ở trong văn phòng của ông Charles Wada.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Check on his desk and let me know.\", \"vi\": \"Xin vui lòng kiểm tra trên bàn làm việc của anh ấy và thông báo lại cho tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Lucy O\'Malley (1:47 P.M.)\", \"vi\": \"Lucy O\'Malley (1 giờ 47 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Got it!\", \"vi\": \"Hiểu rồi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"How would you like me to get this to you?\", \"vi\": \"Quý vị muốn tôi gửi món này cho quý vị bằng cách nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Stanley Hamstead (1:48 P.M.)\", \"vi\": \"Stanley Hamstead (1 giờ 48 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Would it be too much to ask you to deliver it?\", \"vi\": \"Xin quý vị giúp chuyển món hàng này có phải là yêu cầu quá đáng không ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We need the original documents with signatures.\", \"vi\": \"Chúng tôi cần các bản gốc có chữ ký.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Please get here as soon as you can.\", \"vi\": \"Xin quý vị hãy đến đây càng sớm càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Lucy O\'Malley (1:50 P.M.)\", \"vi\": \"Lucy O\'Malley (1 giờ 50 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Not a problem.\", \"vi\": \"Không có vấn đề gì cả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I\'ll take a taxi.\", \"vi\": \"Tôi sẽ đi taxi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '9bae37ee-bd45-432c-9d2b-5f5876e98499';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Alexa Balog (4:02 P.M.) I\'m on lifeguard duty today at Rosemoor Park.\", \"vi\": \"Alexa Balog (4 giờ 02 phút chiều) Hôm nay tôi đang làm nhiệm vụ cứu hộ tại Công viên Rosemoor.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Jamie Kerr asked me to fill in for him.\", \"vi\": \"Jamie Kerr đã nhờ tôi thay thế anh ấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Just letting you know that I\'ve had to close the pool several times because of the bad weather.\", \"vi\": \"Tôi chỉ muốn thông báo với quý vị rằng tôi đã phải đóng cửa bể bơi vài lần do thời tiết xấu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Maxwell Diego (4:03 P.M.) Is the weather bad right now?\", \"vi\": \"Maxwell Diego (4 giờ 03 phút chiều) Hiện tại thời tiết có xấu không ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Alexa Balog (4:03 P.M.) No, but it was raining heavily about 20 minutes ago.\", \"vi\": \"Alexa Balog (4 giờ 03 phút chiều) Không, nhưng khoảng 20 phút trước trời mưa rất to.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Maxwell Diego (4:04 P.M.) Then you\'ll have to wait ten more minutes before reopening.\", \"vi\": \"Maxwell Diego (4 giờ 04 phút chiều) Vậy thì quý vị sẽ phải đợi thêm mười phút nữa trước khi mở cửa trở lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As you know, the rule for Pool Guardian lifeguards is to wait for 30 minutes after bad weather passes.\", \"vi\": \"Như quý vị đã biết, quy định dành cho các nhân viên cứu hộ của Pool Guardian là phải chờ 30 phút sau khi thời tiết xấu đã qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Alexa Balog (4:06 P.M.) Yes, I understand.\", \"vi\": \"Alexa Balog (4 giờ 06 phút chiều) Vâng, tôi hiểu rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"But no one has been here since 2:30.\", \"vi\": \"Tuy nhiên, từ 2 giờ 30 phút đến nay vẫn chưa có ai ghé qua đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Can I close the pool now?\", \"vi\": \"Bây giờ tôi có thể đóng bể bơi được chưa ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Maxwell Diego (4:07 P.M.) That would make sense.\", \"vi\": \"Maxwell Diego (4 giờ 07 phút chiều) Điều đó nghe có vẻ hợp lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"What\'s our policy on that, Mr. Nolan?\", \"vi\": \"Chính sách của chúng ta về vấn đề này là như thế nào, thưa ông Nolan?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Wade Nolan (4:08 P.M.) Sorry, but we can\'t.\", \"vi\": \"Wade Nolan (4 giờ 08 phút chiều) Rất tiếc, nhưng chúng tôi không thể làm được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Our contract says we must supply Rosemoor Park with a lifeguard until 5 P.M. on Thursdays.\", \"vi\": \"Theo hợp đồng của chúng tôi, chúng tôi phải bố trí một nhân viên cứu hộ tại Rosemoor Park cho đến 5 giờ chiều các ngày thứ Năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"So Alexa needs to stay.\", \"vi\": \"Vì vậy, Alexa cần phải ở lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Alexa Balog (4:09 P.M.) OK.\", \"vi\": \"Alexa Balog (4:09 chiều) Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I\'m in the equipment shed.\", \"vi\": \"Tôi đang ở trong nhà kho chứa thiết bị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I\'ve been cleaning it up and straightening up the pool supplies here.\", \"vi\": \"Tôi đang dọn dẹp và sắp xếp lại các vật dụng bể bơi ở đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Wade Nolan (4:10 P.M.) But if there\'s heavy rain again after 4:30, just go ahead and close things up, Alexa.\", \"vi\": \"Wade Nolan (4 giờ 10 phút chiều). Tuy nhiên, nếu sau 4 giờ 30 phút lại có mưa to, thì xin hãy tiến hành đóng cửa mọi thứ lại, Alexa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Maxwell Diego (4:10 P.M.) It must be spotless now.\", \"vi\": \"Maxwell Diego (4 giờ 10 phút chiều) Chắc hẳn bây giờ nơi đây đã sạch bong rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Alexa Balog (4:11 P.M.) It has never looked so good.\", \"vi\": \"Alexa Balog (4 giờ 11 phút chiều) Chưa bao giờ trông đẹp đến thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"And thanks, Mr. Nolan.\", \"vi\": \"Và xin cảm ơn ông Nolan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = '9bcee2ec-6532-4b2a-a301-86263121b23a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"BAKERSVILLE (August 13)—As confirmed by today\'s vote, the city\'s building code is getting a shake-up.\", \"vi\": \"BAKERSVILLE (ngày 13 tháng 8) — Như kết quả bỏ phiếu hôm nay đã xác nhận, quy chuẩn xây dựng của thành phố đang trải qua những thay đổi đáng kể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Among the changes to go into effect on November 3 are stricter fire safety standards for both commercial and residential buildings, enhanced insulation requirements, and, most notably, a requirement that 25 percent of newly constructed residential homes be equipped with solar panels.\", \"vi\": \"Trong số các thay đổi sẽ có hiệu lực vào ngày 3 tháng 11 có các tiêu chuẩn an toàn phòng cháy chữa cháy nghiêm ngặt hơn đối với cả các tòa nhà thương mại và nhà ở, các yêu cầu về cách nhiệt được nâng cao, và đáng chú ý nhất là quy định yêu cầu 25 phần trăm số nhà ở mới xây dựng phải được lắp đặt tấm pin mặt trời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The solar initiative has been met with broad support among voters, lawmakers, and home builders.\", \"vi\": \"Sáng kiến về năng lượng mặt trời đã nhận được sự ủng hộ rộng rãi từ phía cử tri, các nhà lập pháp và các nhà thầu xây dựng nhà ở.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The new rule will increase the total amount of green energy produced and reduce dependency on fossil fuels.\", \"vi\": \"Quy định mới này sẽ làm tăng tổng sản lượng năng lượng xanh và giảm sự phụ thuộc vào nhiên liệu hóa thạch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Supporters also say that increasing demand for solar panels and hardware will drive prices down, so that this technology will be increasingly affordable.\", \"vi\": \"Những người ủng hộ cũng cho rằng nhu cầu ngày càng tăng đối với các tấm pin mặt trời và thiết bị liên quan sẽ thúc đẩy giá cả giảm xuống, nhờ đó công nghệ này sẽ ngày càng trở nên dễ tiếp cận hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Finally, though the building phase will be more costly than usual, homeowners will save on electricity bills in the long term.\", \"vi\": \"Cuối cùng, mặc dù giai đoạn xây dựng sẽ tốn kém hơn bình thường, nhưng về lâu dài, các chủ nhà sẽ tiết kiệm được chi phí tiền điện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The state will open a phone hotline to answer questions from builders, property owners, contractors, and other affected parties beginning on October 15 and continuing through the end of the year.\", \"vi\": \"Chính quyền sẽ mở đường dây nóng để giải đáp thắc mắc của các nhà xây dựng, chủ sở hữu bất động sản, nhà thầu và các bên liên quan khác, bắt đầu từ ngày 15 tháng 10 và kéo dài đến hết năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = '9bd27b59-783c-49c3-a800-69c48f1000a3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MEMO\", \"vi\": \"THÔNG BÁO\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Marketing Team\", \"vi\": \"Đến: Nhóm Tiếp thị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Alyssa Jacobs, Project Manager\", \"vi\": \"Từ: Alyssa Jacobs, Trưởng phòng Dự án\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 27 September\", \"vi\": \"Ngày: 27 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Meeting wrap-up\", \"vi\": \"Chủ đề: Tổng kết cuộc họp\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you again to all of you for your fine work on the upcoming marketing campaign for the Turbo Omega 2 smartphone.\", \"vi\": \"Xin cảm ơn tất cả các bạn một lần nữa vì công việc tuyệt vời của các bạn trong chiến dịch tiếp thị sắp tới cho điện thoại thông minh Turbo Omega 2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As ___135___ during yesterday\'s meeting, our goal is to launch the television, radio, and social media advertisements on 1 November.\", \"vi\": \"Như ___135___ trong cuộc họp ngày hôm qua, mục tiêu của chúng ta là ra mắt các quảng cáo trên truyền hình, phát thanh và mạng xã hội vào ngày 1 tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [135]}, {\"en\": \"The phone itself will be in stores by 1 December.\", \"vi\": \"Bản thân chiếc điện thoại này sẽ có mặt tại các cửa hàng trước ngày 1 tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"___136___ .\", \"vi\": \"___136___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [136]}, {\"en\": \"___137___ , Gary Carollo will draft the press release and post it on our shared drive, where all of you will be able to read it.\", \"vi\": \"___137___ , Gary Carollo sẽ phác thảo thông cáo báo chí và đăng tải lên ổ đĩa chung của chúng ta, nơi tất cả các bạn có thể đọc được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [137]}, {\"en\": \"Please e-mail any ___138___ for changes to Gary within one week.\", \"vi\": \"Vui lòng gửi email mọi ___138___ chỉnh sửa cho Gary trong vòng một tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [138]}, {\"en\": \"He will present his final draft at our next regular meeting.\", \"vi\": \"Anh ấy sẽ trình bày bản thảo cuối cùng của mình tại cuộc họp thường kỳ tiếp theo của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"We will also tie up any loose ends at that time.\", \"vi\": \"Chúng ta cũng sẽ giải quyết mọi công việc còn dang dở vào thời điểm đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '9bdb160b-e47e-4d8a-b8fe-e4b0b14f359d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Central Art Museum\", \"vi\": \"Bảo tàng Mỹ thuật Trung ương\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Upcoming Special Exhibits\", \"vi\": \"Các triển lãm đặc biệt sắp tới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Worldwide Fashion\", \"vi\": \"Thời trang toàn cầu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"November 1–28\", \"vi\": \"Ngày 1–28 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Discover how clothing and accessories have changed throughout time in various parts of the world.\", \"vi\": \"Hãy cùng khám phá sự thay đổi của trang phục và phụ kiện theo thời gian tại các khu vực khác nhau trên thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"See clothing samples, historical items, and sketches.\", \"vi\": \"Xin mời quý vị chiêm ngưỡng các mẫu trang phục, hiện vật lịch sử và các bản phác thảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Jeffrey Lamb: Naturalist\", \"vi\": \"Jeffrey Lamb: Nhà tự nhiên học\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"December 1–29\", \"vi\": \"Từ ngày 1 đến ngày 29 tháng 12\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Scientist Jeffrey Lamb spent his life studying and taking pictures of wildlife on six continents.\", \"vi\": \"Nhà khoa học Jeffrey Lamb đã dành cả cuộc đời để nghiên cứu và chụp ảnh động vật hoang dã trên sáu châu lục.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"See photos of animals and landscapes from the researcher’s personal collection, taken during his forty-year career.\", \"vi\": \"Mời quý vị chiêm ngưỡng những bức ảnh về động vật và phong cảnh từ bộ sưu tập cá nhân của nhà nghiên cứu, được chụp trong suốt bốn mươi năm sự nghiệp của ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Humans in Art\", \"vi\": \"Con người trong nghệ thuật\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"January 1–29\", \"vi\": \"Ngày 1–29 tháng 1\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"This collection of paintings and sculptures from dozens of artists, past and present, shows us the many ways artists can depict a human subject.\", \"vi\": \"Bộ sưu tập các tác phẩm hội họa và điêu khắc của hàng chục nghệ sĩ, cả trong quá khứ lẫn hiện tại, cho chúng ta thấy những cách thức đa dạng mà các nghệ sĩ có thể khắc họa hình tượng con người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Works from both famous and relatively unknown artists are included here.\", \"vi\": \"Tại đây có trưng bày các tác phẩm của cả những nghệ sĩ nổi tiếng lẫn những nghệ sĩ còn ít được biết đến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Everyday Art\", \"vi\": \"Nghệ thuật trong cuộc sống hàng ngày\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"February 1–26\", \"vi\": \"Ngày 1–26 tháng Hai\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"A variety of handmade items are on display in this exhibit showing art in everyday life.\", \"vi\": \"Triển lãm này trưng bày nhiều mặt hàng thủ công đa dạng, thể hiện nghệ thuật trong cuộc sống hàng ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"From handmade quilts to furniture, see these household items in a whole new way.\", \"vi\": \"Từ những chiếc chăn bông làm thủ công cho đến đồ nội thất, hãy chiêm ngưỡng những vật dụng gia đình này dưới một góc nhìn hoàn toàn mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Review of Central Art Museum\", \"vi\": \"Bài đánh giá về Bảo tàng Mỹ thuật Trung ương\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Reviewer: Mary Walsh\", \"vi\": \"Người đánh giá: Mary Walsh\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Stars: ★★★★★\", \"vi\": \"Đánh giá: ★★★★★\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I recommend the Central Art Museum to anyone interested in not only art but history as well.\", \"vi\": \"Tôi xin giới thiệu Bảo tàng Mỹ thuật Trung ương đến tất cả những ai không chỉ quan tâm đến nghệ thuật mà còn cả lịch sử.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I’ve made two trips to the museum recently.\", \"vi\": \"Gần đây, tôi đã có hai lần ghé thăm bảo tàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"My first trip was with my school’s photography club.\", \"vi\": \"Chuyến đi đầu tiên của tôi là cùng câu lạc bộ nhiếp ảnh của trường.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"We only saw the special exhibit featuring photography, but I left wanting to see the rest of the museum.\", \"vi\": \"Chúng tôi chỉ có dịp tham quan triển lãm đặc biệt về nhiếp ảnh, nhưng khi ra về, tôi vẫn mong muốn được khám phá phần còn lại của bảo tàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I returned a few days later and had the chance to walk through the entire museum.\", \"vi\": \"Vài ngày sau, tôi quay lại và có cơ hội tham quan toàn bộ bảo tàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Each exhibit was different but full of interesting pieces.\", \"vi\": \"Mỗi triển lãm đều có nét riêng biệt nhưng đều trưng bày rất nhiều tác phẩm thú vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Be sure to stop at the interactive room near the gift shop for a hands-on experience.\", \"vi\": \"Xin hãy nhớ ghé qua phòng trải nghiệm tương tác gần cửa hàng quà tặng để có cơ hội tự tay trải nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"During my first trip, the room had cameras with fun backgrounds.\", \"vi\": \"Trong chuyến đi đầu tiên của tôi, trong phòng có những chiếc máy ảnh với các phông nền vui nhộn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Visitors took pictures of themselves, and for a small fee, I got a printout of myself as if I were holding a flag on the moon!\", \"vi\": \"Các du khách đã tự chụp ảnh, và chỉ với một khoản phí nhỏ, tôi đã nhận được một bức ảnh in ra, trong đó tôi trông như đang cầm lá cờ trên Mặt Trăng vậy!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Like the special exhibits, the activities at the interactive room change every month, so you will always find something new and interesting to do.\", \"vi\": \"Cũng giống như các triển lãm đặc biệt, các hoạt động tại phòng tương tác được thay đổi hàng tháng, vì vậy quý vị sẽ luôn tìm thấy những điều mới mẻ và thú vị để trải nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = '9be91c4f-d0d3-4970-9097-1cc98aa93c75';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: ztaheri@larabeemail.com\", \"vi\": \"Gửi tới: ztaheri@larabeemail.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: parksoomin@civilengconf.com\", \"vi\": \"Từ: parksoomin@civilengconf.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: August 3\", \"vi\": \"Ngày: 3 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Civil Engineering Conference\", \"vi\": \"Chủ đề: Hội nghị về Kỹ thuật Xây dựng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Taheri,\", \"vi\": \"Kính gửi ông Taheri,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"It was wonderful to speak with you today, and I am pleased that you have accepted our invitation to attend the 50th Annual Civil Engineering Conference, which takes place from November 5 to 8 in Atlanta.\", \"vi\": \"Thật tuyệt vời khi được trò chuyện với quý vị hôm nay, và tôi rất vui mừng khi quý vị đã nhận lời mời của chúng tôi tham dự Hội nghị Thường niên lần thứ 50 về Kỹ thuật Xây dựng, diễn ra từ ngày 5 đến ngày 8 tháng 11 tại Atlanta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We were greatly disappointed that you were unable to share your expertise in your presentation last year, as the events on the final day of the conference were called off due to severe weather.\", \"vi\": \"Chúng tôi vô cùng tiếc nuối vì quý vị đã không thể chia sẻ kiến thức chuyên môn của mình trong bài thuyết trình vào năm ngoái, do các sự kiện trong ngày cuối cùng của hội nghị đã phải hủy bỏ vì thời tiết xấu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Our attendance is up by nearly 100 compared to last year, so we are using the largest room, Navarro Hall.\", \"vi\": \"Số lượng người tham dự của chúng tôi đã tăng thêm gần 100 người so với năm ngoái, vì vậy chúng tôi đang sử dụng phòng lớn nhất, đó là Navarro Hall.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"It has a capacity of 250, and we expect it to be full.\", \"vi\": \"Nơi này có sức chứa 250 người, và chúng tôi dự kiến sẽ kín chỗ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We have you booked for the morning of the second day.\", \"vi\": \"Chúng tôi đã đặt chỗ cho quý vị vào buổi sáng của ngày thứ hai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"As you make your preparations, please keep in mind that the talk should be a maximum of 120 minutes.\", \"vi\": \"Trong quá trình chuẩn bị, xin quý vị lưu ý rằng thời lượng bài thuyết trình không được vượt quá 120 phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You will have standard presentation equipment at your disposal, but if you require anything else, please let me know.\", \"vi\": \"Quý vị sẽ được cung cấp đầy đủ các thiết bị trình chiếu tiêu chuẩn; tuy nhiên, nếu quý vị cần bất kỳ thứ gì khác, xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Soomin Park\", \"vi\": \"Soomin Park\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Event Coordinator, Civil Engineering Conference\", \"vi\": \"Điều phối viên sự kiện, Hội nghị Kỹ thuật Xây dựng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = '9c2ec9f9-d835-4221-9b53-a607c06b59c6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"GALWAY (4 March)—Adelle Rosier, a third-generation soap maker, opened her shop in Galway eight years ago.\", \"vi\": \"GALWAY (ngày 4 tháng 3) — Adelle Rosier, một nghệ nhân làm xà phòng thuộc thế hệ thứ ba, đã khai trương cửa hàng của mình tại Galway cách đây tám năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Nestled behind Eglinton Gourmet Market on Raven Terrace, her business, Rosier and Finch, is booming.\", \"vi\": \"Tọa lạc ngay phía sau Eglinton Gourmet Market trên Raven Terrace, cửa hàng của cô, Rosier and Finch, đang phát triển mạnh mẽ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Ms. Rosier credits the success to her commitment to lifelong learning.\", \"vi\": \"Bà Rosier cho rằng thành công của mình là nhờ sự cam kết với việc học tập suốt đời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"“Yes, my handcrafted soaps, shampoos, and lotions are luxurious,” she said.\", \"vi\": \"“Đúng vậy, các loại xà phòng, dầu gội đầu và kem dưỡng da do chính tay tôi làm đều rất sang trọng,” cô nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"“But there are a lot of high-quality skin-care products out there.\", \"vi\": \"“Tuy nhiên, trên thị trường hiện nay có rất nhiều sản phẩm chăm sóc da chất lượng cao.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"So after learning the trade from my family, I have increased my sales knowledge by taking online courses in business-to-business (B2B) marketing.”\", \"vi\": \"“Vì vậy, sau khi học hỏi nghề nghiệp từ gia đình, tôi đã trau dồi thêm kiến thức về bán hàng bằng cách tham gia các khóa học trực tuyến về tiếp thị giữa doanh nghiệp với doanh nghiệp (B2B).”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Ms. Rosier adds that those courses built her confidence in selling her products directly to hotels.\", \"vi\": \"Bà Rosier cho biết thêm rằng những khóa học đó đã giúp bà tự tin hơn trong việc bán sản phẩm trực tiếp cho các khách sạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"“Thanks to what I learned in my B2B strategies courses, I managed to persuade a number of boutique hotels in Europe to try my products.”\", \"vi\": \"“Nhờ những kiến thức tôi đã học được từ các khóa học về chiến lược B2B, tôi đã thuyết phục được một số khách sạn boutique ở châu Âu thử sử dụng sản phẩm của mình.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"And so Rosier and Finch skin-care products are available in guest rooms at, for instance, the Bruadair Hotel in Galway, the Florinda Grand in Lisbon, Portugal, and the Zerra Inn in Reykjavik, Iceland.\", \"vi\": \"Vì vậy, các sản phẩm chăm sóc da của Rosier và Finch hiện được cung cấp trong các phòng khách tại, ví dụ như, Khách sạn Bruadair ở Galway, Khách sạn Florinda Grand ở Lisbon, Bồ Đào Nha, và Nhà trọ Zerra ở Reykjavik, Iceland.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Ms. Rosier further points out that many of her customers first learn of her products during a hotel stay.\", \"vi\": \"Bà Rosier còn chỉ ra rằng nhiều khách hàng của bà lần đầu tiên biết đến các sản phẩm của bà trong thời gian lưu trú tại khách sạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Afterward, they visit the shop in person or go online to purchase the items for themselves.\", \"vi\": \"Sau đó, quý vị sẽ trực tiếp đến cửa hàng hoặc truy cập trực tuyến để mua các mặt hàng này cho bản thân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Rosier and Finch is located at 12 Raven Terrace and can be found online at www.rosierandfinch.co.ie.\", \"vi\": \"Rosier and Finch tọa lạc tại số 12 Raven Terrace và quý vị có thể truy cập trang web của công ty tại địa chỉ www.rosierandfinch.co.ie.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"https://www.florindagrand.pt/en/guest_reviews\", \"vi\": \"https://www.florindagrand.pt/en/guest_reviews\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I had to arrange a last-minute business trip to my company\'s Portugal office, and the usual hotel I book was completely full.\", \"vi\": \"Tôi đã phải sắp xếp một chuyến công tác gấp đến văn phòng của công ty tôi tại Bồ Đào Nha, và khách sạn mà tôi thường đặt đã kín phòng hoàn toàn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Based on some online recommendations, I decided to stay at Florinda Grand.\", \"vi\": \"Dựa trên một số lời khuyên trên mạng, tôi đã quyết định lưu trú tại Florinda Grand.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"While this charming hotel is much smaller than the usual places I stay, it has every comfort one would want during a business trip.\", \"vi\": \"Mặc dù khách sạn duyên dáng này có quy mô nhỏ hơn nhiều so với những nơi tôi thường lưu trú, nhưng nơi đây vẫn đáp ứng đầy đủ mọi tiện nghi mà bất kỳ ai cũng mong muốn trong một chuyến công tác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"In addition to a tastefully decorated and comfortable room, there were gourmet treats on my pillowcase and the finest soap, shampoo, and other toiletries available for me to enjoy.\", \"vi\": \"Bên cạnh căn phòng được trang trí trang nhã và tiện nghi, trên gối của tôi còn có những món ăn ngon miệng cùng với xà phòng, dầu gội đầu và các vật dụng vệ sinh cá nhân cao cấp nhất để tôi có thể tận hưởng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"My only regret is that I was in Lisbon for just three days.\", \"vi\": \"Điều duy nhất khiến tôi nuối tiếc là tôi chỉ có mặt tại Lisbon trong ba ngày.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Next time I visit the Lisbon office, I will stay longer and book a room at the Florinda Grand.\", \"vi\": \"Lần tới khi tôi đến thăm văn phòng tại Lisbon, tôi sẽ ở lại lâu hơn và đặt phòng tại khách sạn Florinda Grand.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"—posted by Ashton Wu, 7 June\", \"vi\": \"—đăng bởi Ashton Wu, ngày 7 tháng 6\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '9caed889-563d-4c90-bba7-3bc798fe31fa';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Paul Cho (9:47 A.M.)\", \"vi\": \"Paul Cho (9:47 A.M.)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Marisol.\", \"vi\": \"Xin chào, Marisol.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I wanted to let you know that I was talking to the director of Yadav Digital Marketing, Elise Mayer.\", \"vi\": \"Tôi muốn thông báo với quý vị rằng tôi vừa có cuộc trao đổi với bà Elise Mayer, Giám đốc Công ty Tiếp thị Kỹ thuật số Yadav.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"There\'s an open position there, and I mentioned you.\", \"vi\": \"Hiện tại có một vị trí tuyển dụng tại đó, và tôi đã đề cập đến quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"She says you should definitely apply.\", \"vi\": \"Cô ấy nói rằng quý vị nhất định nên nộp đơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Marisol Rosetti (9:49 A.M.)\", \"vi\": \"Marisol Rosetti (9 giờ 49 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"That\'s wonderful to hear!\", \"vi\": \"Thật vui khi được nghe tin đó!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Thanks for passing my name along.\", \"vi\": \"Xin cảm ơn quý vị đã giới thiệu tên tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Paul Cho (9:50 A.M.)\", \"vi\": \"Paul Cho (9:50 A.M.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I know you\'d be a great fit.\", \"vi\": \"Tôi biết quý vị sẽ là ứng viên rất phù hợp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"You check all the boxes.\", \"vi\": \"Quý vị đáp ứng đầy đủ mọi tiêu chí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Marisol Rosetti (9:51 A.M.)\", \"vi\": \"Marisol Rosetti (9 giờ 51 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Do you think Ms. Mayer would want to see a cover letter in addition to my résumé?\", \"vi\": \"Quý vị có nghĩ rằng bà Mayer sẽ muốn xem một lá thư xin việc bên cạnh bản lý lịch của tôi không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Paul Cho (9:52 A.M.)\", \"vi\": \"Paul Cho (9:52 A.M.)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I wouldn\'t bother.\", \"vi\": \"Tôi sẽ không bận tâm đến chuyện đó đâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Elise and I have been friends for years.\", \"vi\": \"Elise và tôi đã là bạn của nhau từ nhiều năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Just make sure your résumé is up to date and reflects your relevant experience.\", \"vi\": \"Hãy đảm bảo rằng sơ yếu lý lịch của quý vị luôn được cập nhật và phản ánh đầy đủ kinh nghiệm liên quan của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Marisol Rosetti (9:53 A.M.)\", \"vi\": \"Marisol Rosetti (9 giờ 53 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I\'ll do that.\", \"vi\": \"Tôi sẽ làm như vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Thank you so much, Paul.\", \"vi\": \"Xin chân thành cảm ơn anh, Paul.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I really appreciate it!\", \"vi\": \"Tôi thực sự rất cảm kích!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = '9cf4b6b7-55e1-48ed-b028-fb6eccb189e1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Sales Team\", \"vi\": \"Gửi: Đội ngũ Kinh doanh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Laura Correa\", \"vi\": \"Từ: Laura Correa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 5 October\", \"vi\": \"Ngày: 5 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Updates\", \"vi\": \"Chủ đề: Các thông tin cập nhật\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Team,\", \"vi\": \"Kính gửi toàn thể đội ngũ,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As announced in the Brighter Sails September newsletter, our performance has been consistently strong this year.\", \"vi\": \"Như đã thông báo trong bản tin tháng 9 của Brighter Sails, kết quả hoạt động của chúng tôi trong năm nay luôn duy trì ở mức ấn tượng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This is an accomplishment we can all be proud of.\", \"vi\": \"Đây là một thành tựu mà tất cả chúng ta đều có thể tự hào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please take a moment to congratulate each other.\", \"vi\": \"Xin quý vị hãy dành một chút thời gian để chúc mừng lẫn nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We will continue to dream up new and exciting plans for the future!\", \"vi\": \"Chúng tôi sẽ tiếp tục ấp ủ những kế hoạch mới mẻ và đầy hứng khởi cho tương lai!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In other news, Jasen Norton will transfer to our Kingston headquarters next month.\", \"vi\": \"Trong một tin khác, ông Jasen Norton sẽ chuyển công tác đến trụ sở chính của chúng tôi tại Kingston vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We are sad to lose Mr. Norton, but we gratefully acknowledge his excellent work and wish him continued success in his new role.\", \"vi\": \"Chúng tôi rất tiếc khi phải chia tay ông Norton, song chúng tôi xin bày tỏ lòng biết ơn sâu sắc trước những đóng góp xuất sắc của ông và chúc ông tiếp tục gặt hái thành công trong cương vị mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"There will be a farewell luncheon for Mr. Norton on 28 October at 1:00 P.M. in the second-floor conference room.\", \"vi\": \"Buổi tiệc trưa chia tay dành cho ông Norton sẽ được tổ chức vào ngày 28 tháng 10 lúc 1 giờ chiều tại phòng hội nghị ở tầng hai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Bring your good cheer and perhaps a story to share.\", \"vi\": \"Hãy mang theo tinh thần vui vẻ và có thể là một câu chuyện nào đó để chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The company will supply lunch, a cake, and decorations.\", \"vi\": \"Công ty sẽ chuẩn bị bữa trưa, một chiếc bánh và các vật dụng trang trí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Let me know by 12 October whether you will be able to attend.\", \"vi\": \"Xin vui lòng cho tôi biết trước ngày 12 tháng 10 xem quý vị có thể tham dự được hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Laura Correa, Sales Manager\", \"vi\": \"Bà Laura Correa, Giám đốc Kinh doanh\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Brighter Sails Ltd.\", \"vi\": \"Công ty TNHH Brighter Sails\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '9d1192d0-16f0-4c5b-981d-29d0bc5762a0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"“The Sounds of Brilliance”\", \"vi\": \"“Những âm thanh của sự xuất sắc”\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Wednesday, May 28\", \"vi\": \"Thứ Tư, ngày 28 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"4:30 P.M.–9:00 P.M.\", \"vi\": \"16 giờ 30 – 21 giờ 00\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The Rendon University Department of Music invites all members of the campus and local community to attend its yearly recital celebrating excellence among our students.\", \"vi\": \"Khoa Âm nhạc của Đại học Rendon trân trọng kính mời toàn thể thành viên trong khuôn viên trường và cộng đồng địa phương tham dự buổi biểu diễn thường niên nhằm vinh danh những thành tích xuất sắc của sinh viên chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Join us in Steen Music Center’s Cho Recital Hall for an afternoon and evening of superb vocal, piano, cello, saxophone, and violin music.\", \"vi\": \"Hãy cùng chúng tôi đến với Phòng hòa nhạc Cho thuộc Trung tâm Âm nhạc Steen để thưởng thức một buổi chiều và buổi tối tràn ngập những bản nhạc tuyệt vời dành cho giọng hát, piano, cello, saxophone và violin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"All performers on the program are winners of the department’s performance awards.\", \"vi\": \"Tất cả các nghệ sĩ tham gia chương trình đều là những người đã đoạt giải thưởng biểu diễn do khoa trao tặng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Among the honorees this year is Felicia Logan, who recently reached the semifinal round of the popular singing competition TV show Top Vocalist.\", \"vi\": \"Trong số những người được vinh danh năm nay có bà Felicia Logan, người vừa lọt vào vòng bán kết của chương trình truyền hình thi hát nổi tiếng “Top Vocalist”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The full recital program, with details about the performers and pieces, is available at www.rendon.edu/music/soe.\", \"vi\": \"Chương trình biểu diễn đầy đủ, kèm theo thông tin chi tiết về các nghệ sĩ và các tác phẩm, có thể xem tại địa chỉ www.rendon.edu/music/soe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The program will run from 4:30 P.M. to 6:00 P.M. and 7:30 P.M. to 9:00 P.M. There is no fee for admission, and seating is first-come, first-served.\", \"vi\": \"Chương trình sẽ diễn ra từ 4 giờ 30 chiều đến 6 giờ chiều và từ 7 giờ 30 tối đến 9 giờ tối. Vé vào cửa miễn phí và chỗ ngồi được sắp xếp theo thứ tự đến trước được phục vụ trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please note that seats cannot be saved during the intermission.\", \"vi\": \"Xin lưu ý rằng quý vị không thể giữ chỗ trong giờ giải lao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Steen Music Center is located at 640 Millard Avenue.\", \"vi\": \"Trung tâm Âm nhạc Steen tọa lạc tại số 640 Đại lộ Millard.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Street parking on campus is free after 4:00 P.M., and paid parking is available in the Camacho Lot directly west of the music center.\", \"vi\": \"Việc đỗ xe trên đường trong khuôn viên trường là miễn phí sau 4 giờ chiều, và quý vị có thể sử dụng bãi đỗ xe Camacho nằm ngay phía tây của trung tâm âm nhạc với mức phí tương ứng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = '9d15aa63-4816-4bf1-b54e-d63f0198f03d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Attention Travelers:\", \"vi\": \"Kính gửi quý hành khách:\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Was your luggage damaged while in transit?\", \"vi\": \"Hành lý của quý vị có bị hư hỏng trong quá trình vận chuyển không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"If so, ______[135] it to the Cloud Express Airlines baggage office as soon as possible after arrival.\", \"vi\": \"Nếu có, ______[135] nó cho văn phòng hành lý của hãng hàng không Cloud Express ngay khi có thể sau khi đến nơi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"Domestic travelers are asked to report damage within 24 hours of reaching their destination, and international travelers must submit a report within five days of an incident.\", \"vi\": \"Hành khách nội địa được yêu cầu báo cáo hư hỏng trong vòng 24 giờ kể từ khi đến điểm đến, và hành khách quốc tế phải nộp báo cáo trong vòng năm ngày kể từ khi xảy ra sự cố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"______[136].\", \"vi\": \"______[136].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [136]}, {\"en\": \"Office personnel will review and evaluate all ______[137].\", \"vi\": \"Nhân viên văn phòng sẽ xem xét và đánh giá tất cả ______[137].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [137]}, {\"en\": \"Be advised that Cloud Express Airlines is not responsible for preexisting conditions or broken zippers or buckles related to overpacking or ______[138] wear.\", \"vi\": \"Xin lưu ý rằng hãng hàng không Cloud Express không chịu trách nhiệm đối với các tình trạng có sẵn từ trước hoặc khóa kéo hoặc khóa cài bị hỏng liên quan đến việc đóng gói quá đầy hoặc ______[138] sự hao mòn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [138]}]' WHERE `id` = '9d21241c-1fac-4a92-a2e0-2f5e6eddc90a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.barbadosairlines.com/baggage\", \"vi\": \"https://www.barbadosairlines.com/baggage\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Barbados Airlines Baggage Policies\", \"vi\": \"Chính sách hành lý của Hãng hàng không Barbados\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"All Barbados Airlines passengers may bring one personal item (for example, a handbag or laptop bag) into the cabin with them.\", \"vi\": \"Tất cả hành khách của Hãng hàng không Barbados đều được phép mang theo một vật dụng cá nhân (ví dụ như túi xách tay hoặc túi đựng máy tính xách tay) vào khoang hành khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Personal items must fit under the seat; therefore, they cannot be larger than 45 x 35 x 20 centimetres.\", \"vi\": \"Các vật dụng cá nhân phải để vừa dưới ghế; do đó, kích thước của chúng không được vượt quá 45 x 35 x 20 centimet.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Child safety seats do not count toward a passenger\'s personal item allowance.\", \"vi\": \"Ghế an toàn cho trẻ em không được tính vào hạn mức hành lý cá nhân của hành khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"For a fee of €20, a passenger may take on board a carry-on item such as a suitcase or duffel bag.\", \"vi\": \"Với mức phí 20 €, hành khách được phép mang theo một kiện hành lý xách tay lên máy bay, chẳng hạn như vali hoặc túi duffel.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"To fit in the overhead storage compartment, carry-on items must not exceed 56 x 36 x 23 centimetres, including handles, straps, and wheels.\", \"vi\": \"Để có thể đặt vừa vào khoang hành lý trên đầu, kích thước của hành lý xách tay không được vượt quá 56 x 36 x 23 centimet, bao gồm cả tay cầm, dây đeo và bánh xe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Any carry-on item larger than these dimensions will be checked into the baggage hold and will incur a fee of €50.\", \"vi\": \"Bất kỳ hành lý xách tay nào có kích thước lớn hơn các thông số này sẽ được làm thủ tục ký gửi vào khoang hành lý và sẽ phải chịu phí 50 €.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"With special permission, oversized items like sporting equipment and musical instruments can be taken into the cabin as carry-on items.\", \"vi\": \"Với sự cho phép đặc biệt, các vật dụng có kích thước lớn như dụng cụ thể thao và nhạc cụ có thể được mang vào khoang hành khách dưới dạng hành lý xách tay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '9d470dd1-f7f3-4af5-9d7f-61c8f694e8b3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Bruce Holt\", \"vi\": \"Gửi: Bruce Holt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Shamonica Walker\", \"vi\": \"Từ: Shamonica Walker\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: April 9\", \"vi\": \"Ngày: 9 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Immediate and confidential\", \"vi\": \"Chủ đề: Khẩn cấp và bảo mật\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Bruce,\", \"vi\": \"Kính gửi ông Bruce,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Beginning with the new fiscal year, a change in retirement benefits will be applied for all full-time employees here at Blanen Industries.\", \"vi\": \"Kể từ năm tài chính mới, chính sách về quyền lợi hưu trí sẽ có sự điều chỉnh đối với toàn bộ nhân viên làm việc toàn thời gian tại Blanen Industries.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"They will no longer be given their matching retirement funds in the form of cash.\", \"vi\": \"Họ sẽ không còn được nhận khoản đóng góp tương ứng từ quỹ hưu trí dưới dạng tiền mặt nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Instead, their retirement funds will be provided in the form of company stock to be deposited in their retirement portfolios.\", \"vi\": \"Thay vào đó, quỹ hưu trí của họ sẽ được cấp dưới dạng cổ phiếu công ty và được chuyển vào danh mục đầu tư hưu trí của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Our current retirement management firm, Proxave Futures, has been informed of this change in retirement benefits.\", \"vi\": \"Công ty quản lý quỹ hưu trí hiện tại của chúng tôi, Proxave Futures, đã được thông báo về sự thay đổi này liên quan đến các quyền lợi hưu trí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The firm will manage the transition and will continue to provide customer support to Blanen Industries employees.\", \"vi\": \"Công ty sẽ phụ trách quá trình chuyển giao và sẽ tiếp tục cung cấp dịch vụ hỗ trợ khách hàng cho các nhân viên của Blanen Industries.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Questions should be directed to Pierre Dehaene at Proxave Futures rather than our human resources department.\", \"vi\": \"Mọi thắc mắc xin vui lòng liên hệ trực tiếp với ông Pierre Dehaene tại Proxave Futures thay vì gửi đến phòng nhân sự của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please work with Yua Suzuki, head of human resources, to provide her with the information she should include in her all-staff communication about this important change in employee benefits.\", \"vi\": \"Kính mong quý vị phối hợp với bà Yua Suzuki, Trưởng phòng Nhân sự, để cung cấp cho bà những thông tin cần thiết nhằm đưa vào thông báo gửi toàn thể nhân viên về sự thay đổi quan trọng này liên quan đến chế độ phúc lợi của người lao động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Our president notified me that he would like to receive all reports related to this transition.\", \"vi\": \"Chủ tịch của chúng tôi đã thông báo với tôi rằng ngài mong muốn nhận được tất cả các báo cáo liên quan đến quá trình chuyển giao này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Also, please continue to send me daily financial reports.\", \"vi\": \"Ngoài ra, xin vui lòng tiếp tục gửi cho tôi các báo cáo tài chính hàng ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Shamonica Walker, CFO\", \"vi\": \"Bà Shamonica Walker, Giám đốc Tài chính (CFO)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Blanen Industries\", \"vi\": \"Blanen Industries\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = '9e0d4f1b-ce0f-43d5-ae92-58d05a3cf1fb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Date: 11 January\", \"vi\": \"Ngày: 11 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Mitchell Parker <mparker@allmail.co.za>\", \"vi\": \"Đến: Mitchell Parker <mparker@allmail.co.za>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Inez Lofaro <ilofaro@daqtex.co.za>\", \"vi\": \"Từ: Inez Lofaro <ilofaro@daqtex.co.za>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Product recall\", \"vi\": \"Chủ đề: Thu hồi sản phẩm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Parker,\", \"vi\": \"Ông Parker kính mến,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for your recent ______[143] of the Daqtex Mini-V camera.\", \"vi\": \"Cảm ơn bạn vì ______[143] máy ảnh Daqtex Mini-V gần đây của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [143]}, {\"en\": \"We are contacting everyone who has recently bought this product to inform them that certain models are being recalled for repair.\", \"vi\": \"Chúng tôi đang liên hệ với tất cả những ai vừa mua sản phẩm này để thông báo rằng một số mẫu máy nhất định đang được thu hồi để sửa chữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In these models, the electronic chip that enables the digital conversion of light is faulty.\", \"vi\": \"Ở các mẫu máy này, con chip điện tử cho phép chuyển đổi tín hiệu ánh sáng kỹ thuật số bị lỗi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[144].\", \"vi\": \"______[144].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [144]}, {\"en\": \"Please ______[145] whether your camera has this problem by checking the serial number on the bottom of the camera.\", \"vi\": \"Vui lòng ______[145] xem máy ảnh của bạn có gặp vấn đề này hay không bằng cách kiểm tra số sê-ri ở mặt dưới của máy ảnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [145]}, {\"en\": \"If it ends with the letters TVX, a repair will be required.\", \"vi\": \"Nếu số sê-ri kết thúc bằng các chữ cái TVX, việc sửa chữa sẽ là bắt buộc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Daqtex will pay all shipping costs for sending your Mini-V back to us.\", \"vi\": \"Daqtex sẽ chi trả toàn bộ chi phí vận chuyển khi bạn gửi trả máy ảnh Mini-V của mình cho chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"In addition, we will repair ______[146] free of charge.\", \"vi\": \"Ngoài ra, chúng tôi sẽ sửa chữa ______[146] hoàn toàn miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [146]}, {\"en\": \"Thank you,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Inez Lofaro, Customer Service Manager\", \"vi\": \"Inez Lofaro, Trưởng phòng Dịch vụ Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Daqtex Industries\", \"vi\": \"Công ty TNHH Công nghiệp Daqtex\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = '9e0d5c0f-3591-4a1b-8f8d-fc6f8a523336';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: m_castillo@rapidonct.com.ph\", \"vi\": \"Gửi tới: m_castillo@rapidonct.com.ph\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: no-reply@rapidonct.com.ph\", \"vi\": \"Nguồn: no-reply@rapidonct.com.ph\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 19 June\", \"vi\": \"Ngày: 19 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Rapido Net\", \"vi\": \"Chủ đề: Rapido Net\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We have noticed some activity on your account.\", \"vi\": \"Chúng tôi đã phát hiện một số hoạt động trên tài khoản của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Your secret-question option for password recovery was updated at 3:16 P.M. today.\", \"vi\": \"Tùy chọn câu hỏi bí mật để khôi phục mật khẩu của quý vị đã được cập nhật vào lúc 3 giờ 16 phút chiều hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"If you initiated this update, no further action is necessary.\", \"vi\": \"Nếu quý vị là người đã khởi tạo bản cập nhật này, thì quý vị không cần thực hiện thêm bất kỳ thao tác nào nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If not, we can help you secure your account.\", \"vi\": \"Nếu không, chúng tôi có thể hỗ trợ quý vị bảo mật tài khoản của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Call 919-555-1066 to speak to an account representative.\", \"vi\": \"Vui lòng gọi số 919-555-1066 để liên hệ với nhân viên phụ trách tài khoản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"If you would like to remove the secret-question password recovery option, you may use a verified e-mail address or phone number to access your account instead.\", \"vi\": \"Nếu quý vị muốn hủy bỏ tùy chọn khôi phục mật khẩu bằng câu hỏi bí mật, quý vị có thể sử dụng địa chỉ email hoặc số điện thoại đã được xác minh để truy cập tài khoản của mình thay thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Make the process even more secure by setting up two-step verification.\", \"vi\": \"Hãy tăng cường tính bảo mật cho quy trình này bằng cách thiết lập xác thực hai bước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Just ask our representative how.\", \"vi\": \"Xin vui lòng hỏi đại diện của chúng tôi để biết thêm chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you for trusting Rapido Net as your Internet service provider.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã tin tưởng lựa chọn Rapido Net làm nhà cung cấp dịch vụ Internet của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '9e427926-a326-4fed-8ccd-0c9d2f86d6f8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.masterint.co.uk ▶\", \"vi\": \"http://www.masterint.co.uk ▶\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Master International offers internships to university students and recent graduates who are passionate about the software industry and would like to gain real-world experience in coding, product development, marketing, and security.\", \"vi\": \"Master International cung cấp các chương trình thực tập dành cho sinh viên đại học và những người mới tốt nghiệp, những người có niềm đam mê với ngành công nghệ phần mềm và mong muốn tích lũy kinh nghiệm thực tế trong các lĩnh vực lập trình, phát triển sản phẩm, tiếp thị và bảo mật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Our products are used by businesses worldwide.\", \"vi\": \"Các sản phẩm của chúng tôi được các doanh nghiệp trên toàn thế giới sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Each unpaid internship position lasts for a period of four months and requires an on-site commitment of at least three full days per week.\", \"vi\": \"Mỗi vị trí thực tập không lương có thời hạn bốn tháng và yêu cầu thực tập sinh phải có mặt tại cơ sở ít nhất ba ngày làm việc đầy đủ mỗi tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Applications must be received by 1 November (for the spring program), 1 April (for summer), or 1 July (for autumn).\", \"vi\": \"Hồ sơ đăng ký phải được nhận trước ngày 1 tháng 11 (đối với chương trình mùa xuân), ngày 1 tháng 4 (đối với chương trình mùa hè) hoặc ngày 1 tháng 7 (đối với chương trình mùa thu).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Current university students are encouraged to check with their academic institution to determine whether course credits may be granted.\", \"vi\": \"Các sinh viên đại học hiện tại được khuyến khích liên hệ với cơ sở giáo dục của mình để xác định xem liệu có được công nhận tín chỉ cho các khóa học này hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Although a few interns may subsequently be offered permanent full-time employment, a job offer is not guaranteed.\", \"vi\": \"Mặc dù sau đó một số thực tập sinh có thể được đề nghị nhận vào làm việc chính thức toàn thời gian, nhưng việc nhận được đề nghị tuyển dụng không được đảm bảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Master International receives hundreds of internship applications throughout the year.\", \"vi\": \"Master International nhận được hàng trăm đơn xin thực tập trong suốt cả năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"After an initial review, a select few will be contacted in advance of each four-month cycle for an in-person or telephone interview.\", \"vi\": \"Sau vòng xét duyệt ban đầu, một số ứng viên được lựa chọn sẽ được liên hệ trước mỗi chu kỳ bốn tháng để tham gia phỏng vấn trực tiếp hoặc qua điện thoại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"HOW TO APPLY\", \"vi\": \"CÁCH NỘP ĐƠN\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To get started, we require the following:\", \"vi\": \"Để bắt đầu, chúng tôi yêu cầu những điều sau đây:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"• A completed employment application (located in the Forms tab)\", \"vi\": \"• Đơn xin việc đã điền đầy đủ thông tin (có trong tab “Mẫu đơn”)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"• A letter indicating area of interest and relevant coursework\", \"vi\": \"• Một lá thư nêu rõ lĩnh vực quan tâm và các môn học liên quan\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"• Two letters of recommendation\", \"vi\": \"• Hai thư giới thiệu\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Submit all documents to:\", \"vi\": \"Vui lòng nộp toàn bộ hồ sơ đến:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Master International\", \"vi\": \"Chương trình Thạc sĩ Quốc tế\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Personnel Department\", \"vi\": \"Phòng Nhân sự\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"34 Crawley Square\", \"vi\": \"Số 34 Quảng trường Crawley\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"London, England SE7 9BQ\", \"vi\": \"London, Anh SE7 9BQ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"HOME\", \"vi\": \"TRANG CHỦ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"ABOUT\", \"vi\": \"GIỚI THIỆU\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"FORMS\", \"vi\": \"BIỂU MẪU\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"INTERNSHIPS\", \"vi\": \"CHƯƠNG TRÌNH THỰC TẬP\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = '9e5d6c95-e531-4fe8-b57f-58d086cbb5af';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Carmont Media\'s Culture\", \"vi\": \"Văn hóa của Carmont Media\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"https://www.carmontmedia.co.tt\", \"vi\": \"https://www.carmontmedia.co.tt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"At Carmont Media, our work culture is mission driven.\", \"vi\": \"Tại Carmont Media, văn hóa làm việc của chúng tôi luôn lấy sứ mệnh làm kim chỉ nam.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We hire people who share a common goal of enriching listeners\' minds through engaging and truthful news stories.\", \"vi\": \"Chúng tôi tuyển dụng những người cùng chia sẻ mục tiêu chung là làm giàu tri thức cho thính giả thông qua những bản tin hấp dẫn và trung thực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We also actively recruit a diverse staff to reflect our Trinidadian and Tobagonian audiences.\", \"vi\": \"Chúng tôi cũng tích cực tuyển dụng đội ngũ nhân viên đa dạng nhằm phản ánh đúng đặc điểm của khán giả Trinidad và Tobago.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Carmont Media\'s diversity contributes to its Star teams.\", \"vi\": \"Sự đa dạng tại Carmont Media góp phần tạo nên các đội ngũ xuất sắc của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"These teams, composed of workers from all levels of the organization, meet regularly to hold brainstorming sessions aimed at improving efficiency and productivity.\", \"vi\": \"Các nhóm này, bao gồm các nhân viên từ mọi cấp bậc trong tổ chức, thường xuyên họp mặt để tổ chức các buổi thảo luận nhằm nâng cao hiệu quả và năng suất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Carmont Media offers opportunities for professional advancement and encourages work-life balance.\", \"vi\": \"Carmont Media mang đến những cơ hội thăng tiến nghề nghiệp và khuyến khích sự cân bằng giữa công việc và cuộc sống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Programs\", \"vi\": \"Các chương trình\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Services\", \"vi\": \"Dịch vụ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"About Us\", \"vi\": \"Giới thiệu về chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = '9eb89a22-afe3-4737-9515-1b122d151455';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Specialty Foods\\n• Blue Bay Bakeries\\n• Berry Delectable\\n• Over-the-Moon Teas - Apparel\\n• Sakurai Sportswear\\n• Urban Activewear Company\\n• Chic Wraps - Technology\\n• Craftspace\\n• Gingi Tech\\n• New Teams Office Systems\\n• Surefire Learning Ltd.\", \"vi\": \"Thực phẩm đặc sản\\n• Blue Bay Bakeries\\n• Berry Delectable\\n• Over-the-Moon Teas - Thời trang\\n• Sakurai Sportswear\\n• Urban Activewear Company\\n• Chic Wraps - Công nghệ\\n• Craftspace\\n• Gingi Tech\\n• New Teams Office Systems\\n• Surefire Learning Ltd.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.ohayonmarketing.com/clients ▶\", \"vi\": \"http://www.ohayonmarketing.com/clients ▶\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Over the past five years we have provided marketing solutions to an ever-growing client portfolio:\", \"vi\": \"Trong năm năm qua, chúng tôi đã cung cấp các giải pháp tiếp thị cho danh mục khách hàng ngày càng mở rộng:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Our Clients\", \"vi\": \"Các khách hàng của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Work Samples\", \"vi\": \"Các mẫu tác phẩm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Contact\", \"vi\": \"Liên hệ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To: Sunil Mehta <sunil.mehta@gomail.co.in>\", \"vi\": \"Gửi tới: Sunil Mehta <sunil.mehta@gomail.co.in>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"From: Marc Ohayon <mohayon@ohayonmarketing.com>\", \"vi\": \"Từ: Marc Ohayon <mohayon@ohayonmarketing.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Date: May 3\", \"vi\": \"Ngày: 3 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Subject: Hello\", \"vi\": \"Tiêu đề: Xin chào\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Dear Sunil,\", \"vi\": \"Kính gửi anh Sunil,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I hope this message finds you well.\", \"vi\": \"Tôi hy vọng khi nhận được tin nhắn này, quý vị vẫn đang khỏe mạnh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"You may have heard the news that my family and I are preparing to move from New York to Marrakesh in the fall.\", \"vi\": \"Có lẽ quý vị đã nghe tin rằng gia đình tôi và tôi đang chuẩn bị chuyển từ New York đến Marrakesh vào mùa thu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"In the process, I am hoping to move my marketing firm, Ohayon Marketing, to the area as well.\", \"vi\": \"Trong quá trình này, tôi hy vọng cũng có thể chuyển công ty tiếp thị của mình, Ohayon Marketing, đến khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"You may remember that after I left Sharp Smart—and moved out of New Delhi—I freelanced for Craftspace, which went on to become my company\'s first client.\", \"vi\": \"Có lẽ quý vị còn nhớ rằng sau khi tôi rời Sharp Smart — và chuyển khỏi New Delhi — tôi đã làm việc tự do cho Craftspace, công ty sau này đã trở thành khách hàng đầu tiên của công ty tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"In more recent years, my company has branched out to consult for a large number of businesses in unrelated industries.\", \"vi\": \"Trong những năm gần đây, công ty của tôi đã mở rộng hoạt động sang lĩnh vực tư vấn cho rất nhiều doanh nghiệp thuộc các ngành không liên quan.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I would like to continue with this work by establishing a client base in Marrakesh.\", \"vi\": \"Tôi mong muốn tiếp tục công việc này bằng cách xây dựng một cơ sở khách hàng tại Marrakesh.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I am reaching out to you because of your contacts in the business community there.\", \"vi\": \"Tôi liên hệ với quý vị vì quý vị có các mối quan hệ trong giới doanh nghiệp tại đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"If you know anyone who might be interested in the services I offer, would you be so kind as to let me know?\", \"vi\": \"Nếu quý vị biết ai đó có thể quan tâm đến các dịch vụ mà tôi cung cấp, xin quý vị vui lòng cho tôi biết được không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Best wishes,\", \"vi\": \"Xin gửi lời chúc tốt đẹp nhất,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Marc\", \"vi\": \"Marc\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"To: Marc Ohayon <mohayon@ohayonmarketing.com>\", \"vi\": \"Gửi tới: Marc Ohayon <mohayon@ohayonmarketing.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"From: Sunil Mehta <sunil.mehta@gomail.co.in>\", \"vi\": \"Từ: Sunil Mehta <sunil.mehta@gomail.co.in>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Date: May 6\", \"vi\": \"Ngày: 6 tháng 5\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Subject: Marrakesh contact\", \"vi\": \"Chủ đề: Người liên hệ tại Marrakesh\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Hello, Marc,\", \"vi\": \"Xin chào, Marc,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"It was a pleasure to hear from you.\", \"vi\": \"Thật vui khi nhận được thư của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"You remember correctly; I do have contacts in Marrakesh.\", \"vi\": \"Quý vị nhớ đúng rồi; tôi thực sự có những người quen ở Marrakesh.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Before we worked together at Sharp Smart, I worked for a company that had an office in Marrakesh, and I traveled there frequently.\", \"vi\": \"Trước khi chúng tôi cùng làm việc tại Sharp Smart, tôi từng làm việc cho một công ty có văn phòng tại Marrakesh, và tôi thường xuyên phải đi công tác đến đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I can also recommend several hotels, restaurants, and even travel agencies if you would like.\", \"vi\": \"Nếu quý vị muốn, tôi cũng có thể giới thiệu một số khách sạn, nhà hàng và thậm chí cả các công ty du lịch.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"In response to your inquiry, I will introduce you by e-mail to Ms. Salma Kader.\", \"vi\": \"Để trả lời câu hỏi của quý vị, tôi sẽ giới thiệu quý vị với bà Salma Kader qua email.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"She is quite knowledgeable in the region, and I have no doubt that she will be helpful to you.\", \"vi\": \"Cô ấy rất am hiểu về khu vực này, và tôi tin chắc rằng cô ấy sẽ giúp ích được cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Warm regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Sunil\", \"vi\": \"Sunil\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '9ed08ea2-abe6-41b9-9b8e-007ddb64aa34';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"http://www.mazullospizza.com\", \"vi\": \"http://www.mazullospizza.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Mazullo\'s Deep-Dish Pizza\", \"vi\": \"Pizza đế dày của Mazullo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Get a taste of the best pizza in Chicago!\", \"vi\": \"Hãy thưởng thức món pizza ngon nhất tại Chicago!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We have been serving authentic deep-dish Chicago-style pizza since Tonia Mazullo opened the original restaurant in a humble shop in Bridgeport.\", \"vi\": \"Chúng tôi đã phục vụ món pizza đế dày kiểu Chicago chính thống kể từ khi bà Tonia Mazullo khai trương nhà hàng đầu tiên tại một cửa hàng nhỏ khiêm tốn ở Bridgeport.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Thirty-five years later, her children and grandchildren continue to craft delectable pizzas using traditional Mazullo-family dough and tomato sauce recipes.\", \"vi\": \"Ba mươi lăm năm sau, các con và cháu của bà vẫn tiếp tục chế biến những chiếc pizza thơm ngon bằng công thức làm bột và nước sốt cà chua truyền thống của gia đình Mazullo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We offer dine-in, carryout, and delivery service within three miles of our locations.\", \"vi\": \"Chúng tôi cung cấp dịch vụ dùng bữa tại chỗ, mua mang về và giao hàng tận nơi trong phạm vi ba dặm tính từ các chi nhánh của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"All pizzas are made fresh to order and include your choice of three toppings.\", \"vi\": \"Tất cả các chiếc pizza đều được chế biến tươi ngon ngay khi quý khách đặt hàng và bao gồm ba loại nhân theo sự lựa chọn của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Every pizza is served with a large beverage and our famous garlic rolls.\", \"vi\": \"Mỗi chiếc pizza đều được phục vụ kèm theo một ly nước uống cỡ lớn và món bánh cuộn tỏi nổi tiếng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"A variety of salads and pastas make optional side dishes.\", \"vi\": \"Các món salad và mì Ý đa dạng có thể được dùng làm món ăn kèm tùy chọn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"All vegetable toppings are local, organic, and farm-to-table.\", \"vi\": \"Tất cả các loại rau dùng làm nhân đều là sản phẩm địa phương, hữu cơ và được đưa trực tiếp từ trang trại lên bàn ăn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Click on a location to get directions, phone numbers, and restaurant hours.\", \"vi\": \"Vui lòng nhấp vào một địa điểm để xem chỉ đường, số điện thoại và giờ mở cửa của nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Bridgeport |\", \"vi\": \"Bridgeport |\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Lincoln Park |\", \"vi\": \"Lincoln Park |\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Edgewater |\", \"vi\": \"Edgewater |\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Avondale\", \"vi\": \"Avondale\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"About\", \"vi\": \"Giới thiệu\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Our Ingredients\", \"vi\": \"Các thành phần của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Order Online\", \"vi\": \"Đặt hàng trực tuyến\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = '9ee10cfd-fcf9-4535-b6bb-cbf9734f7ebd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Product Delivery\", \"vi\": \"Giao hàng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"https://www.hamptonlandscaping.com/productdelivery\", \"vi\": \"https://www.hamptonlandscaping.com/productdelivery\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Hampton Landscaping offers customers the option of having landscaping products delivered to their residences or businesses.\", \"vi\": \"Hampton Landscaping cung cấp cho quý khách hàng dịch vụ giao các sản phẩm cảnh quan đến tận nơi ở hoặc cơ sở kinh doanh của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"This includes topsoil, compost, gravel, bark dust, firewood, and planting mixes.\", \"vi\": \"Trong đó bao gồm đất mặt, phân hữu cơ, sỏi, bột vỏ cây, củi và hỗn hợp đất trồng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"For your convenience, we offer large- and small-volume deliveries Monday through Saturday.\", \"vi\": \"Để tạo sự thuận tiện cho quý khách, chúng tôi cung cấp dịch vụ giao hàng với số lượng lớn và nhỏ từ thứ Hai đến thứ Bảy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Delivery rates vary based on volume, product, and location.\", \"vi\": \"Phí vận chuyển thay đổi tùy theo khối lượng, loại sản phẩm và địa điểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Please call us at 904-555-0132 for detailed pricing.\", \"vi\": \"Vui lòng liên hệ với chúng tôi qua số điện thoại 904-555-0132 để biết thông tin chi tiết về giá cả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You do not need to be home for delivery.\", \"vi\": \"Quý vị không cần phải có mặt tại nhà khi nhận hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please note that the requested delivery area must be accessible for our trucks.\", \"vi\": \"Xin lưu ý rằng khu vực giao hàng quý khách yêu cầu phải đảm bảo xe tải của chúng tôi có thể tiếp cận được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In the event that this requirement is not met, a $50 restocking fee will be charged.\", \"vi\": \"Trong trường hợp không đáp ứng được yêu cầu này, quý khách sẽ phải trả phí hoàn trả hàng trị giá 50 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = '9f095655-5b8a-468c-b7ea-f7d8a9244c71';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"AFEC Offers Pathway to Success\", \"vi\": \"AFEC mở ra con đường dẫn đến thành công\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"By Pauline Weston\", \"vi\": \"Tác giả: Pauline Weston\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"BRIDGETOWN (29 October)—From 14 to 16 November, the Association of Female Entrepreneurs of the Caribbean (AFEC) will be hosting its fourth biennial forum at the Centre for Labour Force Development in Bridgetown, Barbados.\", \"vi\": \"BRIDGETOWN (ngày 29 tháng 10) — Từ ngày 14 đến ngày 16 tháng 11, Hiệp hội Nữ doanh nhân vùng Caribe (AFEC) sẽ tổ chức Diễn đàn hai năm một lần lần thứ tư tại Trung tâm Phát triển Lực lượng Lao động ở Bridgetown, Barbados.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"This year\'s theme, \\\"From Aspiration to Sensation,\\\" is centered on the essential skills and tools needed to start, run, and grow a successful business.\", \"vi\": \"Chủ đề của năm nay, “Từ Ước mơ đến Thành công”, tập trung vào những kỹ năng và công cụ thiết yếu cần có để khởi nghiệp, điều hành và phát triển một doanh nghiệp thành công.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"About 350 women will be interacting with some of the region\'s most successful women business leaders through a series of presentations.\", \"vi\": \"Khoảng 350 phụ nữ sẽ có cơ hội giao lưu với một số nữ doanh nhân thành đạt nhất trong khu vực thông qua một chuỗi các buổi thuyết trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"One presenter will be Serena Telting, owner of Suriname-based children\'s clothing manufacturer Serenatee.\", \"vi\": \"Một trong những diễn giả sẽ là bà Serena Telting, chủ sở hữu của Serenatee – công ty sản xuất quần áo trẻ em có trụ sở tại Suriname.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"She welcomes the opportunity to share her experience with conference goers.\", \"vi\": \"Bà rất vui mừng khi có cơ hội chia sẻ kinh nghiệm của mình với các đại biểu tham dự hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"\\\"Specifically,\\\" she says, \\\"I will be promoting a set of sound practices that I have adopted over my fifteen years in the apparel industry.\", \"vi\": \"\\\"Cụ thể,\\\" cô nói, \\\"tôi sẽ quảng bá một bộ các phương pháp thực hành hiệu quả mà tôi đã áp dụng trong suốt mười lăm năm làm việc trong ngành may mặc.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Those might shield emerging entrepreneurs from the challenges I faced early on in my career.\", \"vi\": \"Những điều đó có thể giúp các doanh nhân trẻ tránh được những thách thức mà tôi đã phải đối mặt trong giai đoạn đầu sự nghiệp của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Because I lacked adequate advice when I started my business, I made some mistakes that nearly ruined it.\\\"\", \"vi\": \"“Vì khi mới bắt đầu kinh doanh, tôi không nhận được những lời khuyên thích hợp nên đã mắc phải một số sai lầm suýt nữa đã khiến công việc kinh doanh của tôi sụp đổ.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Attendees are keen on engaging with their established peers.\", \"vi\": \"Các đại biểu rất mong muốn được giao lưu với các đồng nghiệp có uy tín trong ngành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Madelon Picard, a native of Martinique who plans to open a nursery school on the island, says, \\\"I am eager to learn how my role models dealt with challenges and accomplished their achievements.\\\"\", \"vi\": \"Bà Madelon Picard, một người gốc Martinique và đang có kế hoạch mở một trường mầm non trên hòn đảo này, chia sẻ: “Tôi rất mong muốn tìm hiểu cách những tấm gương mà tôi ngưỡng mộ đã vượt qua những thách thức và gặt hái được những thành tựu của họ như thế nào.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Ms. Picard also referenced the assistance she has received from the Martinique Business Society (MBS), of which she is a member.\", \"vi\": \"Bà Picard cũng đề cập đến sự hỗ trợ mà bà đã nhận được từ Hiệp hội Doanh nghiệp Martinique (MBS), nơi bà là một thành viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"\\\"The MBS is fully funding my participation in the AFEC forum, from hotel accommodation and airfare to meals and local transport.\\\"\", \"vi\": \"\\\"Chương trình MBS đang tài trợ toàn bộ chi phí cho việc tôi tham gia diễn đàn AFEC, từ chỗ ở tại khách sạn và vé máy bay cho đến các bữa ăn và phương tiện đi lại tại địa phương.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"She is far from the exception.\", \"vi\": \"Cô ấy hoàn toàn không phải là trường hợp ngoại lệ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Organisers say they have seen a significant increase in financial support for attendees since the first AFEC forum.\", \"vi\": \"Ban tổ chức cho biết họ đã ghi nhận sự gia tăng đáng kể về mức hỗ trợ tài chính dành cho các đại biểu kể từ diễn đàn AFEC lần đầu tiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = '9f1e7e07-b235-4667-96fa-bf4c0c242adc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Scrap Saver\", \"vi\": \"Scrap Saver\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Tired of dealing with your business’s food waste?\", \"vi\": \"Quý vị đã cảm thấy mệt mỏi khi phải giải quyết vấn đề chất thải thực phẩm tại doanh nghiệp của mình chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Whether you run a restaurant or a café, a hotel or a catering company, Scrap Saver has the solution to your problem.\", \"vi\": \"Dù quý vị đang điều hành một nhà hàng hay một quán cà phê, một khách sạn hay một công ty cung cấp dịch vụ ăn uống, Scrap Saver đều có giải pháp cho vấn đề của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Since the separate disposal of commercial food waste became mandated by law last year, a growing number of businesses have turned to us for disposal of their cooking scraps and leftover food products.\", \"vi\": \"Kể từ khi việc xử lý riêng rẽ chất thải thực phẩm thương mại được quy định bắt buộc theo luật vào năm ngoái, ngày càng có nhiều doanh nghiệp tìm đến chúng tôi để xử lý các loại phế phẩm nấu nướng và thực phẩm thừa của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We provide cheap, convenient pickup and transport of these materials to our facilities, where they are converted into alternative fuels and organic fertilizer.\", \"vi\": \"Chúng tôi cung cấp dịch vụ thu gom và vận chuyển các vật liệu này với chi phí hợp lý và thuận tiện đến các cơ sở của chúng tôi, nơi chúng được chuyển hóa thành nhiên liệu thay thế và phân bón hữu cơ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Clients simply collect the food waste in one of our free storage bins or their own until the designated pickup time, which can be scheduled as frequently as needed.\", \"vi\": \"Quý khách chỉ cần thu gom chất thải thực phẩm vào một trong những thùng chứa miễn phí của chúng tôi hoặc thùng chứa của riêng quý khách cho đến thời gian thu gom đã định, và tần suất thu gom có thể được sắp xếp tùy theo nhu cầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Scrap Saver offers removal of all types of food packaging for reasonable handling fees, and we can even provide bulk transportation services for business that create more than three tons of waste per week.\", \"vi\": \"Scrap Saver cung cấp dịch vụ thu gom tất cả các loại bao bì thực phẩm với mức phí xử lý hợp lý; đồng thời, chúng tôi còn có thể cung cấp dịch vụ vận chuyển số lượng lớn cho các doanh nghiệp tạo ra hơn ba tấn chất thải mỗi tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Visit www.scrapsaver.com to learn more!\", \"vi\": \"Hãy truy cập www.scrapsaver.com để tìm hiểu thêm!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"From: Margaret Ross <mross@scrapsaver.com>\", \"vi\": \"Từ: Margaret Ross <mross@scrapsaver.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"To: Jake Pierce <jake.pierce@babybudfood.com>\", \"vi\": \"Người gửi: Jake Pierce <jake.pierce@babybudfood.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Subject: Information about Scrap Saver\", \"vi\": \"Chủ đề: Thông tin về Scrap Saver\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Date: November 14\", \"vi\": \"Ngày: 14 tháng 11\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Dear Mr. Pierce,\", \"vi\": \"Kính gửi ông Pierce,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Thank you for contacting us on behalf of Babybud Food Corporation.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã liên hệ với chúng tôi thay mặt cho Công ty Cổ phần Thực phẩm Babybud.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"It’s my pleasure to answer the questions you asked in the online form you filled out.\", \"vi\": \"Tôi rất hân hạnh được trả lời các câu hỏi mà quý vị đã nêu trong biểu mẫu trực tuyến mà quý vị đã điền.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Our rate is $0.26 per liter of food waste, plus there’s a distance-based pickup fee that would be $11.00 per visit given your company’s location.\", \"vi\": \"Mức phí của chúng tôi là 0,26 USD cho mỗi lít chất thải thực phẩm; ngoài ra, còn có một khoản phí thu gom tính theo khoảng cách, cụ thể là 11,00 USD cho mỗi lần thu gom, tùy theo vị trí của công ty quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"You wouldn’t be charged handling fees, and there’s no additional cost for weekend pickups.\", \"vi\": \"Quý vị sẽ không phải trả phí xử lý, và cũng không có chi phí bổ sung nào cho việc nhận hàng vào cuối tuần.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Billing is done at the end of each calendar month.\", \"vi\": \"Việc lập hóa đơn được thực hiện vào cuối mỗi tháng dương lịch.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Please don’t hesitate to reply to this e-mail or call me at 555-0189 if you have additional questions or are ready to engage Scrap Saver’s services.\", \"vi\": \"Xin đừng ngần ngại trả lời email này hoặc gọi cho tôi theo số 555-0189 nếu quý vị có thêm thắc mắc hoặc đã sẵn sàng sử dụng dịch vụ của Scrap Saver.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Margaret Ross\", \"vi\": \"Margaret Ross\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Sales Representative\", \"vi\": \"Nhân viên kinh doanh\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Scrap Saver, Incorporated\", \"vi\": \"Công ty Cổ phần Scrap Saver\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}]' WHERE `id` = '9f364965-0f5f-4327-b1b2-f9c048a82363';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Vera Fernandez\", \"vi\": \"Từ: Vera Fernandez\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Carla Rosa\", \"vi\": \"Kính gửi: Carla Rosa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Sent: June 07, 12:47 P.M.\", \"vi\": \"Gửi vào: Ngày 07 tháng 6, 12 giờ 47 phút trưa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Initiatives for distance learning\", \"vi\": \"Chủ đề: Các sáng kiến về học tập từ xa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Rosa,\", \"vi\": \"Kính gửi bà Rosa,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am contacting you on behalf of the Dolina Foundation.\", \"vi\": \"Tôi liên hệ với quý vị thay mặt cho Quỹ Dolina.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our mission is to promote the use of distance-learning platforms in rural areas and communities that are isolated geographically.\", \"vi\": \"Sứ mệnh của chúng tôi là thúc đẩy việc sử dụng các nền tảng học tập từ xa tại các khu vực nông thôn và các cộng đồng bị cô lập về mặt địa lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We do so through a network of partners in the technology industry.\", \"vi\": \"Chúng tôi thực hiện điều này thông qua mạng lưới các đối tác trong ngành công nghệ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We would be honored to have your company join our network.\", \"vi\": \"Chúng tôi sẽ vô cùng vinh dự nếu quý công ty tham gia vào mạng lưới của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"At 2:00 P.M. on June 25, Dolina is sponsoring a presentation entitled “Distance Learning in Rural Libraries.”\", \"vi\": \"Vào lúc 2 giờ chiều ngày 25 tháng 6, Dolina sẽ tổ chức một buổi thuyết trình mang tên “Học tập từ xa tại các thư viện nông thôn.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The presentation will be given online as a webinar, using some of the technologies our partners have developed.\", \"vi\": \"Buổi thuyết trình sẽ được tổ chức trực tuyến dưới hình thức hội thảo trực tuyến, với sự hỗ trợ của một số công nghệ do các đối tác của chúng tôi phát triển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Jay Ralston, the foundation’s director of systems integration, will describe technologies being used to support academic and vocational education programs.\", \"vi\": \"Ông Jay Ralston, Giám đốc phụ trách tích hợp hệ thống của quỹ, sẽ trình bày về các công nghệ đang được sử dụng để hỗ trợ các chương trình giáo dục đại học và giáo dục nghề nghiệp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"In addition, five librarians will discuss how they offer a variety of education programs in their regions using technologies developed and delivered by our business partners.\", \"vi\": \"Bên cạnh đó, năm thư viện viên sẽ chia sẻ về cách họ triển khai các chương trình giáo dục đa dạng tại khu vực của mình thông qua việc ứng dụng các công nghệ do các đối tác kinh doanh của chúng tôi phát triển và cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To register for the webinar, and to learn more about our foundation’s projects, visit our Web site at www.dolinafoundation.org.\", \"vi\": \"Để đăng ký tham gia hội thảo trực tuyến và tìm hiểu thêm về các dự án của Quỹ chúng tôi, xin vui lòng truy cập trang web của chúng tôi tại địa chỉ www.dolinafoundation.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Feel free to contact me if you have any questions.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào, xin vui lòng liên hệ với tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We hope that you will consider our invitation.\", \"vi\": \"Chúng tôi hy vọng quý vị sẽ cân nhắc lời mời của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"With kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Vera Fernandez, Outreach Coordinator\", \"vi\": \"Bà Vera Fernandez, Điều phối viên phụ trách công tác tiếp cận cộng đồng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = '9f70515d-4597-4606-a2fb-723c3eb20385';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Things Are Happening with the Southeast Rail Line—Time to Get Involved!\", \"vi\": \"Dự án Tuyến đường sắt Đông Nam đang có những diễn biến mới — Đã đến lúc quý vị cùng tham gia!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Plans are moving forward with the renovations to the Southeast Rail Line.\", \"vi\": \"Các kế hoạch cải tạo Tuyến đường sắt Đông Nam đang được triển khai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The changes will create a faster, more convenient, more reliable alternative to traveling on the area’s congested roadways.\", \"vi\": \"Những thay đổi này sẽ mang lại một phương án thay thế nhanh hơn, thuận tiện hơn và đáng tin cậy hơn so với việc di chuyển trên các tuyến đường thường xuyên ùn tắc trong khu vực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Construction begins this September.\", \"vi\": \"Công trình sẽ được khởi công vào tháng 9 năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Public meetings to solicit comments regarding design options for the new stations are scheduled for June, July, and August.\", \"vi\": \"Các cuộc họp công khai nhằm thu thập ý kiến đóng góp về các phương án thiết kế cho các ga mới dự kiến sẽ diễn ra vào các tháng 6, 7 và 8.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Learn more about the meetings by visiting www.southeastrailproject.com/communityaffairs.\", \"vi\": \"Để tìm hiểu thêm về các cuộc họp, vui lòng truy cập trang web www.southeastrailproject.com/communityaffairs.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = '9f795027-c131-4aab-9b15-fba9728d6aa5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Planning a Tour of Your Facility\", \"vi\": \"Lên kế hoạch cho chuyến tham quan cơ sở của quý vị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"by Didiane Lessard\", \"vi\": \"của Didiane Lessard\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Plant tours are commonplace in many factories, but not all tours are as effective as they could be.\", \"vi\": \"Các chuyến tham quan nhà máy là hoạt động phổ biến tại nhiều nhà máy, song không phải chuyến tham quan nào cũng mang lại hiệu quả tối ưu như mong đợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Too many companies make the mistake of adopting a one-size-fits-all approach rather than tailoring tours to maximize their usefulness.\", \"vi\": \"Quá nhiều doanh nghiệp mắc sai lầm khi áp dụng phương pháp “một mô hình cho tất cả” thay vì thiết kế các chuyến tham quan sao cho phù hợp nhất nhằm tối đa hóa hiệu quả của chúng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"A potential investor and a casual tourist will probably not be impressed by the same things, so it is best to be clear about the tour’s purpose early on.\", \"vi\": \"Một nhà đầu tư tiềm năng và một du khách bình thường có lẽ sẽ không bị ấn tượng bởi những điều giống nhau, vì vậy tốt nhất là nên làm rõ mục đích của chuyến tham quan ngay từ đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Here are some guidelines to make each tour as effective as possible.\", \"vi\": \"Dưới đây là một số hướng dẫn nhằm giúp mỗi chuyến tham quan đạt hiệu quả cao nhất có thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Be selective.\", \"vi\": \"Hãy biết chọn lọc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Unless your tour is for a safety inspection, your guests do not need (or want) to see every part of your factory.\", \"vi\": \"Trừ khi chuyến tham quan của quý vị nhằm mục đích kiểm tra an toàn, khách của quý vị không cần (cũng như không muốn) được xem từng khu vực trong nhà máy của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Choose a few sections that will interest your guests and give them a better sense of your product.\", \"vi\": \"Hãy chọn một vài phần mà quý khách sẽ cảm thấy hứng thú và giúp họ hiểu rõ hơn về sản phẩm của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"For example, journalists will want to create a story about your plant, so show them the parts of the plant that have historical significance, such as a room with the company’s original production equipment.\", \"vi\": \"Ví dụ, các nhà báo sẽ muốn thực hiện một bài báo về nhà máy của quý vị; do đó, xin vui lòng giới thiệu cho họ những khu vực trong nhà máy có ý nghĩa lịch sử, chẳng hạn như một phòng trưng bày các thiết bị sản xuất nguyên bản của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Timing is everything.\", \"vi\": \"Thời điểm là yếu tố quyết định.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Always be mindful of the physical demands of the tour.\", \"vi\": \"Hãy luôn lưu ý đến những yêu cầu về thể lực của chuyến lưu diễn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Even the hardest guest will tire of standing or walking for long periods.\", \"vi\": \"Ngay cả vị khách khó tính nhất cũng sẽ cảm thấy mệt mỏi khi phải đứng hoặc đi bộ trong thời gian dài.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"It is a good idea to schedule breaks in tours lasting longer than an hour.\", \"vi\": \"Đối với các chuyến tham quan kéo dài hơn một giờ, quý vị nên lên lịch các khoảng nghỉ giữa chừng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The time spent in a single section matters also.\", \"vi\": \"Thời gian dành cho mỗi phần cũng rất quan trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"If you allow guests only five minutes in an area, they will soon forget it.\", \"vi\": \"Nếu quý vị chỉ cho phép khách ở lại một khu vực trong vòng năm phút, họ sẽ nhanh chóng quên mất nơi đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"On the other hand, even the most impressive room gets boring after half an hour.\", \"vi\": \"Mặt khác, ngay cả căn phòng ấn tượng nhất cũng sẽ trở nên nhàm chán sau nửa giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Personality is NOT everything.\", \"vi\": \"Tính cách KHÔNG phải là tất cả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"While having a personable and friendly tour guide is essential, your guests are coming to see what goes into making your product.\", \"vi\": \"Mặc dù việc có một hướng dẫn viên du lịch cởi mở và thân thiện là điều không thể thiếu, nhưng quý vị khách đến đây là để tìm hiểu quy trình sản xuất sản phẩm của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Tour guides get asked a variety of questions, some unexpected, so a comprehensive knowledge of the production processes is important (and absolutely vital during inspections).\", \"vi\": \"Các hướng dẫn viên du lịch thường nhận được nhiều câu hỏi khác nhau, trong đó có những câu hỏi bất ngờ, do đó, việc nắm vững kiến thức toàn diện về các quy trình sản xuất là rất quan trọng (và hoàn toàn thiết yếu trong các đợt kiểm tra).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"You also want someone who will keep the tour moving—visitors will appreciate a tour that begins and ends on time.\", \"vi\": \"Quý vị cũng cần một người có thể đảm bảo chuyến tham quan diễn ra suôn sẻ — du khách sẽ đánh giá cao một chuyến tham quan bắt đầu và kết thúc đúng giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"To: Masumi Toda <mt978@vidatechsystems.com>\", \"vi\": \"Gửi: Masumi Toda <mt978@vidatechsystems.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"From: Ana Miftaroski <am680@vidatechsystems.com>\", \"vi\": \"Từ: Ana Miftaroski <am680@vidatechsystems.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Date: May 1\", \"vi\": \"Ngày: 1 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Subject: Upcoming plant tour\", \"vi\": \"Chủ đề: Chuyến tham quan nhà máy sắp tới\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Attachment: Lessard_article\", \"vi\": \"Tệp đính kèm: Bài báo của Lessard\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Hi, Masumi,\", \"vi\": \"Xin chào, Masumi,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I have attached an April 15 article by Didiane Lessard to help you plan the tour we will be giving later this month.\", \"vi\": \"Tôi đã đính kèm bài báo ngày 15 tháng 4 của tác giả Didiane Lessard để giúp quý vị lên kế hoạch cho chuyến tham quan mà chúng ta sẽ tổ chức vào cuối tháng này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"I especially agree with the section on timing.\", \"vi\": \"Tôi đặc biệt đồng tình với phần nói về thời điểm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Since the tour, by necessity, will have to cover the entire plant, it must be conducted as efficiently as possible.\", \"vi\": \"Vì chuyến tham quan, do tính chất công việc, sẽ phải bao quát toàn bộ nhà máy, nên cần phải tiến hành một cách hiệu quả nhất có thể.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"As for a guide, I would have recommended Nathan Zarate, but he will be traveling on May 21.\", \"vi\": \"Về phần hướng dẫn viên, tôi lẽ ra đã đề xuất ông Nathan Zarate, nhưng ông ấy sẽ đi công tác vào ngày 21 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Perhaps Maja Clausen could do it.\", \"vi\": \"Có lẽ Maja Clausen có thể làm được điều đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"She has also worked here for several years; she is very knowledgeable about our facility, processes, policies, and procedures.\", \"vi\": \"Bà ấy cũng đã làm việc tại đây được vài năm; bà ấy rất am hiểu về cơ sở vật chất, các quy trình, chính sách và thủ tục của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"I am confident that she will be able to handle any questions the visitors might ask.\", \"vi\": \"Tôi tin chắc rằng cô ấy sẽ có thể giải đáp bất kỳ câu hỏi nào mà quý khách có thể đặt ra.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Ana Miftaroski, Vice President of Operations\", \"vi\": \"Bà Ana Miftaroski, Phó Chủ tịch phụ trách Hoạt động\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = '9fec005b-bf60-4c12-9395-ca0a4ffa0478';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Botswana Mining Staff\", \"vi\": \"Đến: Nhân viên Botswana Mining\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Phildah Ramogapi, Human Resources Director\", \"vi\": \"Từ: Phildah Ramogapi, Giám đốc Nhân sự\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 4 April\", \"vi\": \"Ngày: 4 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Payroll portal upgrade\", \"vi\": \"Chủ đề: Nâng cấp cổng thông tin bảng lương\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Good morning,\", \"vi\": \"Kính gửi,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Botswana Mining\'s online payroll portal will be unavailable between 8 and 12 April to allow for a software upgrade.\", \"vi\": \"Cổng thông tin bảng lương trực tuyến của Botswana Mining sẽ tạm ngưng hoạt động từ ngày 8 đến ngày 12 tháng 4 để tiến hành nâng cấp phần mềm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Please refrain from accessing the ------- (143) over these five days.\", \"vi\": \"Vui lòng không truy cập vào ------- (143) trong năm ngày này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [143]}, {\"en\": \"The updated site ------- (144) users to perform advanced operations, including setting up and managing direct deposit preferences and accessing tax documents.\", \"vi\": \"Trang web được cập nhật sẽ ------- (144) người dùng thực hiện các thao tác nâng cao, bao gồm thiết lập và quản lý tùy chọn chuyển khoản trực tiếp cũng như truy cập các tài liệu thuế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [144]}, {\"en\": \"It will also feature a live-chat function so that users can directly contact a human resources team member when needed.\", \"vi\": \"Nó cũng sẽ có tính năng trò chuyện trực tiếp để người dùng có thể liên hệ trực tiếp với một thành viên của đội ngũ nhân sự khi cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"------- (145).\", \"vi\": \"------- (145).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [145]}, {\"en\": \"If you need to access your payroll and benefits details ------- (146) the period mentioned above, please send an e-mail to hr@botswanamining.co.bw or visit our office in room 107 of the Ujima Tower.\", \"vi\": \"Nếu bạn cần truy cập thông tin chi tiết về bảng lương và phúc lợi của mình ------- (146) khoảng thời gian nói trên, vui lòng gửi email tới hr@botswanamining.co.bw hoặc đến văn phòng của chúng tôi tại phòng 107 của Tòa nhà Ujima.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [146]}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Phildah Ramogapi, Human Resources Director\", \"vi\": \"Phildah Ramogapi, Giám đốc Nhân sự\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = 'a070a0ed-0b0a-4df7-97e3-c57b9f7d5e13';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: a.thompson@pepperfam.com\", \"vi\": \"Gửi tới: a.thompson@pepperfam.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: customerservice@dixons_clothing.com\", \"vi\": \"Nguồn: customerservice@dixons_clothing.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: November 4, 11:31 A.M.\", \"vi\": \"Ngày: 4 tháng 11, 11 giờ 31 phút sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Your recent order\", \"vi\": \"Chủ đề: Đơn hàng gần đây của quý khách\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Item: Canvas Rain-Resistant Jacket (Men\'s): $ 85.00\", \"vi\": \"Sản phẩm: Áo khoác vải bạt chống mưa (dành cho nam): 85,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Shipping Fee: $  4.50\", \"vi\": \"Phí vận chuyển: $  4,50\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Total: $ 89.50\", \"vi\": \"Tổng cộng: 89,50 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Dear Mr. Thompson,\", \"vi\": \"Kính gửi ông Thompson,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Our records show that your Dixon\'s Clothing order number 5409281 has been delivered.\", \"vi\": \"Theo hồ sơ của chúng tôi, đơn hàng số 5409281 của quý khách tại Dixon\'s Clothing đã được giao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"It\'s important to us to know that you\'re happy with your item.\", \"vi\": \"Điều quan trọng đối với chúng tôi là được biết quý khách hài lòng với sản phẩm của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Therefore, if you have any questions, comments, or concerns about it, call us at 555-0142, Monday through Friday between 8:00 A.M. and 7:00 P.M., and Saturday and Sunday between 10:00 A.M. and 5:00 P.M. You can also e-mail us at customerservice@dixons_clothing.com.\", \"vi\": \"Do đó, nếu quý vị có bất kỳ câu hỏi, ý kiến đóng góp hoặc thắc mắc nào về vấn đề này, xin vui lòng gọi cho chúng tôi theo số 555-0142, từ thứ Hai đến thứ Sáu, từ 8 giờ sáng đến 7 giờ tối, và thứ Bảy, Chủ Nhật từ 10 giờ sáng đến 5 giờ chiều. Quý vị cũng có thể gửi email cho chúng tôi theo địa chỉ customerservice@dixons_clothing.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We look forward to serving you again.\", \"vi\": \"Chúng tôi rất mong được phục vụ quý khách một lần nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Customer Service Department\", \"vi\": \"Phòng Dịch vụ Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Dixon\'s Clothing\", \"vi\": \"Thương hiệu thời trang Dixon\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = 'a0762a16-100c-4aa5-9474-3f096433ecfe';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"April 14 - 09:23 a.m. - Dine-in\", \"vi\": \"Ngày 14 tháng 4 - 09:23 sáng - Ăn tại nhà hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Order: 55234 - Server: Antonio K.\", \"vi\": \"Số đơn hàng: 55234 - Nhân viên phục vụ: Antonio K.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"1 Medium Coffee - $2.25\", \"vi\": \"1 ly cà phê cỡ vừa - 2,25 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"No sugar\", \"vi\": \"Không đường\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"No milk\", \"vi\": \"Không có sữa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"1 Large Coffee - $2.75\", \"vi\": \"1 ly cà phê cỡ lớn - 2,75 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"3 sugars\", \"vi\": \"3 loại đường\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"No milk\", \"vi\": \"Không có sữa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"2 Croissants - $4.00\", \"vi\": \"2 chiếc bánh sừng bò - 4,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Subtotal - $9.00\", \"vi\": \"Tổng cộng (trước thuế) - 9,00 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"HST 13% - $1.17\", \"vi\": \"HST 13% - 1,17 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Total - $10.17\", \"vi\": \"Tổng cộng - 10,17 USD\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Siobhan\'s Toronto, Ontario\", \"vi\": \"Siobhan\'s, Toronto, Ontario\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"**********************************************\", \"vi\": \"**********************************************\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Tell us how we did today and get a free medium coffee!\", \"vi\": \"Hãy chia sẻ với chúng tôi về trải nghiệm của quý vị hôm nay và nhận ngay một ly cà phê cỡ trung miễn phí!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Just fill out our online survey at www.siobhans.ca/survey.\", \"vi\": \"Quý vị chỉ cần điền vào bản khảo sát trực tuyến của chúng tôi tại địa chỉ www.siobhans.ca/survey.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"You will be given a code to receive a free medium coffee when you buy any regular-priced pastry.\", \"vi\": \"Khi quý khách mua bất kỳ loại bánh ngọt nào có giá niêm yết, quý khách sẽ nhận được một mã để đổi lấy một ly cà phê cỡ trung miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = 'a09a0fd7-ba42-418a-af18-c346429d4e49';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"March 29\", \"vi\": \"Ngày 29 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dr. Maritza Geerlings\", \"vi\": \"Tiến sĩ Maritza Geerlings\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Poseidonstraat 392\", \"vi\": \"Số 392, đường Poseidonstraat\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Paramaribo\", \"vi\": \"Paramaribo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Suriname\", \"vi\": \"Suriname\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Dr. Geerlings,\", \"vi\": \"Kính gửi Tiến sĩ Geerlings,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I am writing to thank you for your years of service on the faculty of the Jamaican Agricultural Training Academy (JATA) and to let you know about some exciting developments.\", \"vi\": \"Tôi viết thư này để bày tỏ lòng biết ơn đối với những năm tháng cống hiến của quý vị trong đội ngũ giảng viên của Học viện Đào tạo Nông nghiệp Jamaica (JATA), đồng thời thông báo đến quý vị về một số bước phát triển đầy hứa hẹn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As you know, JATA was originally established as a vocational school for agriculture but now offers courses in a varied array of disciplines, including cybersecurity, electrical engineering, and health information management.\", \"vi\": \"Như quý vị đã biết, JATA ban đầu được thành lập với tư cách là một trường dạy nghề về nông nghiệp, nhưng hiện nay trường đã mở rộng chương trình đào tạo sang nhiều lĩnh vực đa dạng, bao gồm an ninh mạng, kỹ thuật điện và quản lý thông tin y tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Our student body, which for the first ten years consisted almost exclusively of locals, is now culturally diverse, with students from across the Americas and Europe.\", \"vi\": \"Đội ngũ sinh viên của chúng tôi, vốn trong mười năm đầu tiên hầu như chỉ bao gồm những người dân địa phương, hiện nay đã trở nên đa dạng về văn hóa, với sinh viên đến từ khắp châu Mỹ và châu Âu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Today\'s students work with sophisticated equipment, much of which did not exist in our early days.\", \"vi\": \"Các sinh viên ngày nay được làm việc với những thiết bị hiện đại, phần lớn trong số đó chưa từng tồn tại vào thời kỳ đầu của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To reflect these and other significant changes that JATA has undergone over time, the Board of Trustees has approved a proposal by the Faculty Senate to rename the institution the Caribbean Academy of Science and Technology.\", \"vi\": \"Để phản ánh những thay đổi này cũng như những thay đổi quan trọng khác mà JATA đã trải qua theo thời gian, Hội đồng Quản trị đã thông qua đề xuất của Hội đồng Giảng viên về việc đổi tên cơ sở giáo dục này thành Học viện Khoa học và Công nghệ Caribê.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"As a result, a new institutional logo will be adopted.\", \"vi\": \"Do đó, một biểu tượng mới của tổ chức sẽ được chính thức đưa vào sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"All students and faculty members, both current and former, are invited to participate in a logo design contest.\", \"vi\": \"Tất cả các sinh viên và giảng viên, bao gồm cả những người hiện đang công tác và những người đã từng công tác, đều được mời tham gia cuộc thi thiết kế logo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Information about the contest will be forthcoming.\", \"vi\": \"Thông tin về cuộc thi sẽ được công bố trong thời gian tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The renaming ceremony and the introduction of the new logo will take place at 11 A.M. on 1 June, the twentieth anniversary of the institution.\", \"vi\": \"Lễ đổi tên và ra mắt logo mới sẽ diễn ra vào lúc 11 giờ sáng ngày 1 tháng 6, nhân dịp kỷ niệm 20 năm thành lập tổ chức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"We hope you will be able to join us.\", \"vi\": \"Chúng tôi hy vọng quý vị sẽ có thể tham gia cùng chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Audley Bartlett\", \"vi\": \"Audley Bartlett\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Audley Bartlett\", \"vi\": \"Audley Bartlett\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Vice President for Academic Affairs,\", \"vi\": \"Phó Hiệu trưởng phụ trách công tác học vụ,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Jamaican Agricultural Training Academy\", \"vi\": \"Học viện Đào tạo Nông nghiệp Jamaica\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = 'a0bb54e6-56be-4649-9d38-646a22242624';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Important Information Regarding Employee Safety\", \"vi\": \"Thông tin quan trọng liên quan đến an toàn của nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"All employees are expected to follow the guidelines in the employee manual as well as posted safety rules.\", \"vi\": \"Tất cả nhân viên đều phải tuân thủ các hướng dẫn trong cẩm nang nhân viên cũng như các quy tắc an toàn đã được niêm yết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Certain jobs require employees to follow the additional safety guidelines provided by their supervisors.\", \"vi\": \"Một số công việc yêu cầu người lao động phải tuân thủ các hướng dẫn an toàn bổ sung do cấp trên đưa ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Because we take safety seriously, we urge any employee who becomes aware of a breach of these protocols to contact a supervisor or the safety coordinator.\", \"vi\": \"Vì chúng tôi luôn coi trọng vấn đề an toàn, chúng tôi khuyến khích bất kỳ nhân viên nào phát hiện có vi phạm các quy trình này hãy liên hệ với người quản lý hoặc điều phối viên an toàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Further, any employee who has concerns about these protocols or would like to propose additional measures should contact the safety coordinator directly.\", \"vi\": \"Hơn nữa, bất kỳ nhân viên nào có thắc mắc về các quy trình này hoặc muốn đề xuất các biện pháp bổ sung, xin vui lòng liên hệ trực tiếp với điều phối viên an toàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Additionally, contact information for employees who are trained in first aid can be found in the employee manual.\", \"vi\": \"Ngoài ra, quý vị có thể tra cứu thông tin liên hệ của các nhân viên đã được đào tạo về sơ cứu trong cẩm nang nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Free first aid training and certification are available twice yearly to all employees.\", \"vi\": \"Chương trình đào tạo và cấp chứng chỉ sơ cứu miễn phí được tổ chức hai lần mỗi năm dành cho tất cả nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"For more information about when trainings are held, please contact Lynn Schneider at lschneider@rinckindustry.com.\", \"vi\": \"Để biết thêm thông tin về thời gian tổ chức các khóa đào tạo, xin vui lòng liên hệ với bà Lynn Schneider qua địa chỉ email lschneider@rinckindustry.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = 'a0cfa2b8-06aa-485e-b531-fa353be36d4d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Ezgi Inan\", \"vi\": \"Đến: Ezgi Inan\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Tina Yun\", \"vi\": \"Từ: Tina Yun\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 15 April\", \"vi\": \"Ngày: 15 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Event Confirmation\", \"vi\": \"Chủ đề: Xác nhận sự kiện\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Inan,\", \"vi\": \"Kính gửi chị Inan,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"It was a pleasure ___139____ with you today.\", \"vi\": \"Tôi rất vui được ___139____ với chị ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [139]}, {\"en\": \"Thank you for booking your 21 May team-building event at Bonner Trampoline Park.\", \"vi\": \"Cảm ơn chị đã đặt sự kiện xây dựng đội ngũ ngày 21 tháng 5 tại Công viên Nhún nhảy Bonner.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As I mentioned, Bonner offers a variety of lunch packages.\", \"vi\": \"Như tôi đã đề cập, Bonner cung cấp nhiều gói suất ăn trưa khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I have put you down for the basic option.\", \"vi\": \"Tôi đã ghi nhận chị chọn gói cơ bản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This ____140___ one slice of pizza, one can of lemonade, and one small bag of crisps for £8 per person.\", \"vi\": \"Gói này ____140___ một miếng bánh pizza, một lon nước chanh và một gói khoai tây chiên nhỏ với giá 8 bảng Anh mỗi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [140]}, {\"en\": \"You may upgrade your package to add a fruit or vegetable tray for £35.\", \"vi\": \"Chị có thể nâng cấp gói của mình để thêm một khay trái cây hoặc rau củ với giá 35 bảng Anh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Bonner can also provide a sheet cake for an additional £30.\", \"vi\": \"Bonner cũng có thể cung cấp một chiếc bánh kem lớn với phụ phí 30 bảng Anh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"___141____ , you may bring your own cake or another dessert.\", \"vi\": \"___141____ , chị có thể mang theo bánh kem của riêng mình hoặc món tráng miệng khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [141]}, {\"en\": \"___142____ .\", \"vi\": \"___142____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": [142]}, {\"en\": \"Food orders can be changed up to 48 hours prior to your event.\", \"vi\": \"Đơn đặt đồ ăn có thể được thay đổi tối đa 48 giờ trước sự kiện của chị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Tina Yun\", \"vi\": \"Tina Yun\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Events Manager, Bonner Trampoline Park\", \"vi\": \"Quản lý Sự kiện, Công viên Nhún nhảy Bonner\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = 'a0eace60-7c38-4047-a316-59ae5a4f3d88';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"(5:34 P.M.) Daniel Haney\", \"vi\": \"(17 giờ 34 phút) Daniel Haney\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Abdul, are you still in the office?\", \"vi\": \"Abdul, anh vẫn còn ở văn phòng chứ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"(5:35 P.M.) Abdul Ahmed\", \"vi\": \"(17 giờ 35 phút) Abdul Ahmed\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Yes.\", \"vi\": \"Vâng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Getting ready to leave soon.\", \"vi\": \"Sắp chuẩn bị ra về rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Why?\", \"vi\": \"Tại sao vậy?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"(5:36 P.M.) Daniel Haney\", \"vi\": \"(5 giờ 36 phút chiều) Daniel Haney\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I can\'t remember my new password to the remote computer system.\", \"vi\": \"Tôi không thể nhớ mật khẩu mới của mình để đăng nhập vào hệ thống máy tính từ xa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Why does the company make us change it so often!\", \"vi\": \"Tại sao công ty lại bắt chúng ta phải thay đổi nó thường xuyên như vậy chứ!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"(5:37 P.M.) Abdul Ahmed\", \"vi\": \"(17 giờ 37 phút) Abdul Ahmed\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Do you have it written down somewhere?\", \"vi\": \"Quý vị có ghi lại điều đó ở đâu đó không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"(5:38 P.M.) Daniel Haney\", \"vi\": \"(17 giờ 38 phút) Daniel Haney\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Yes.\", \"vi\": \"Vâng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"On a piece of paper on my desk.\", \"vi\": \"Trên một tờ giấy đặt trên bàn làm việc của tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"(5:40 P.M.) Abdul Ahmed\", \"vi\": \"(17 giờ 40 phút) Abdul Ahmed\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"There\'s a lot of paper on your desk.\", \"vi\": \"Trên bàn làm việc của quý vị có rất nhiều giấy tờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"(5:41 P.M.) Daniel Haney\", \"vi\": \"(17 giờ 41 phút) Daniel Haney\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Sorry!\", \"vi\": \"Xin lỗi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"It\'s a little yellow piece.\", \"vi\": \"Đó là một mảnh nhỏ màu vàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Look all the way at the bottom-left corner.\", \"vi\": \"Xin hãy nhìn vào góc dưới cùng bên trái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"(5:43 P.M.) Abdul Ahmed\", \"vi\": \"(17 giờ 43 phút) Abdul Ahmed\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I think I\'ve got it: RV5cc.\", \"vi\": \"Tôi nghĩ là tôi đã tìm ra rồi: RV5cc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Is that what you\'re looking for?\", \"vi\": \"Đó có phải là điều quý vị đang tìm kiếm không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"(5:44 P.M.) Daniel Haney\", \"vi\": \"(17 giờ 44 phút) Daniel Haney\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Yes.\", \"vi\": \"Vâng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Thanks so much, Abdul.\", \"vi\": \"Xin chân thành cảm ơn, Abdul.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"You\'re a lifesaver!\", \"vi\": \"Quý vị thật là vị cứu tinh!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = 'a0eebc51-2ed5-4f57-9851-4332c6d9b349';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Patton Advertising Is Hiring Now!\", \"vi\": \"Công ty Quảng cáo Patton hiện đang tuyển dụng!\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Our Work\", \"vi\": \"Các dự án của chúng tôi\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Some Employee Comments\", \"vi\": \"Một số ý kiến của nhân viên\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"We are seeking motivated, enthusiastic individuals to join us in our design, finance, and IT departments.\", \"vi\": \"Chúng tôi đang tìm kiếm những ứng viên năng động và nhiệt huyết để gia nhập các bộ phận Thiết kế, Tài chính và Công nghệ thông tin của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Previous experience in the advertising sector is useful but not required.\", \"vi\": \"Kinh nghiệm làm việc trong lĩnh vực quảng cáo là một lợi thế nhưng không phải là yêu cầu bắt buộc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Here at Patton, we\'ve designed advertisements and created marketing strategies for a wide range of clients.\", \"vi\": \"Tại Patton, chúng tôi đã thiết kế các quảng cáo và xây dựng các chiến lược tiếp thị cho nhiều đối tượng khách hàng khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"This work has included designing logos and Web sites, as well as creating ads for local radio and a national billboard.\", \"vi\": \"Công việc này bao gồm thiết kế logo và trang web, cũng như sáng tạo các quảng cáo cho đài phát thanh địa phương và một bảng quảng cáo quy mô toàn quốc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Under the leadership of CEO Amie Adesina, we\'re looking to expand in new directions and tackle even more exciting projects.\", \"vi\": \"Dưới sự lãnh đạo của Giám đốc Điều hành Amie Adesina, chúng tôi đang hướng tới việc mở rộng sang những hướng đi mới và thực hiện những dự án còn thú vị hơn nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"In my first six months as a designer at Patton, I\'ve already had the chance to work with several clients and even lead my own team.\", \"vi\": \"\\\"Trong sáu tháng đầu tiên làm việc với tư cách là nhà thiết kế tại Patton, tôi đã có cơ hội hợp tác với nhiều khách hàng và thậm chí còn được dẫn dắt đội ngũ của riêng mình.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The work isn\'t always easy, but if you enjoy a fast-paced, challenging environment, you\'ll really thrive here.\\\"\", \"vi\": \"Công việc không phải lúc nào cũng dễ dàng, nhưng nếu quý vị thích một môi trường làm việc nhịp độ nhanh và đầy thách thức, quý vị sẽ thực sự phát huy được khả năng của mình tại đây.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Thomas Kuti\", \"vi\": \"Thomas Kuti\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"\\\"I\'ve been working as a legal consultant at Patton for just under a year now, and I\'ve enjoyed every moment.\", \"vi\": \"\\\"Tôi đã làm việc với tư cách là chuyên viên tư vấn pháp lý tại Patton được gần một năm nay, và tôi đã tận hưởng từng khoảnh khắc trong thời gian đó.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"There\'s a fantastic working culture, with generous employee benefits including a gym membership and paid time off for volunteering.\", \"vi\": \"Tại đây có một văn hóa làm việc tuyệt vời, cùng với các chế độ phúc lợi hào phóng dành cho nhân viên, bao gồm thẻ thành viên phòng tập thể dục và thời gian nghỉ có lương để tham gia các hoạt động tình nguyện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"It\'s the best company I\'ve ever worked for.\\\"\", \"vi\": \"\\\"Đây là công ty tuyệt vời nhất mà tôi từng làm việc.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sabina Hussain\", \"vi\": \"Sabina Hussain\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Visit our Web site www.pattonads.com/careers to see vacancies and apply for jobs.\", \"vi\": \"Hãy truy cập trang web của chúng tôi tại www.pattonads.com/careers để xem các vị trí tuyển dụng và nộp đơn ứng tuyển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = 'a10b0839-8c5c-4dcf-a398-738f20969880';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Celeste O\'Brien\", \"vi\": \"Gửi: Celeste O\'Brien\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Monica Cheung\", \"vi\": \"Từ: Monica Cheung\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: October 15\", \"vi\": \"Ngày: 15 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Mobile phone reimbursement policy\", \"vi\": \"Chủ đề: Chính sách hoàn trả chi phí điện thoại di động\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. O\'Brien,\", \"vi\": \"Kính gửi Bà O\'Brien,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As the Assistant Director of Accounting, I am writing about the policy regarding mobile phone expenses.\", \"vi\": \"Với tư cách là Phó Giám đốc Phòng Kế toán, tôi xin gửi thư này để trình bày về chính sách liên quan đến chi phí sử dụng điện thoại di động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Many Ferd Data Services employees use their personal mobile phones for business calls.\", \"vi\": \"Nhiều nhân viên của Ferd Data Services sử dụng điện thoại di động cá nhân để thực hiện các cuộc gọi công việc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To get reimbursed, they must submit a form every month.\", \"vi\": \"Để được hoàn trả chi phí, quý vị phải nộp một mẫu đơn hàng tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Ferd then pays up to 30 percent of the phone bill.\", \"vi\": \"Sau đó, Ferd sẽ thanh toán tối đa 30 phần trăm hóa đơn điện thoại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"My department confirms each employee\'s calculations and then schedules payments that vary every month.\", \"vi\": \"Phòng ban của tôi sẽ kiểm tra lại các số liệu tính toán của từng nhân viên, sau đó lập lịch thanh toán với số tiền thay đổi theo từng tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Some companies have moved to a flat-rate model, whereby all employees who qualify receive a fixed amount each month (e.g., $20).\", \"vi\": \"Một số công ty đã chuyển sang mô hình trả theo mức cố định, theo đó tất cả nhân viên đáp ứng điều kiện sẽ nhận được một khoản tiền cố định hàng tháng (ví dụ: 20 đô la).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"No staff time is required for monthly processing; the allowance is automatically included in each paycheck.\", \"vi\": \"Việc xử lý hàng tháng không đòi hỏi nhân viên phải dành thời gian; khoản phụ cấp này sẽ tự động được tính vào mỗi kỳ lương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I hope that, as head of Human Resources, you will consider adopting a policy like this.\", \"vi\": \"Tôi hy vọng rằng, với tư cách là Trưởng phòng Nhân sự, quý vị sẽ xem xét việc áp dụng một chính sách như thế này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Monica Cheung\", \"vi\": \"Monica Cheung\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Ferd Data Services\", \"vi\": \"Dịch vụ Dữ liệu Ferd\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"MEETING AGENDA\", \"vi\": \"CHƯƠNG TRÌNH HỌP\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Location: Online\", \"vi\": \"Địa điểm: Trực tuyến\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Date: October 24\", \"vi\": \"Ngày: 24 tháng 10\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Time: 3:00 P.M.\", \"vi\": \"Thời gian: 3 giờ chiều\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Host: Celeste O\'Brien, Vice President, Human Resources\", \"vi\": \"Người dẫn chương trình: Bà Celeste O\'Brien, Phó Chủ tịch, Bộ phận Nhân sự\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Attendees: Human Resources Managers; Finance Managers; Department Heads\", \"vi\": \"Những người tham dự: Các Trưởng phòng Nhân sự; Các Trưởng phòng Tài chính; Các Trưởng bộ phận\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"OBJECTIVES:\", \"vi\": \"MỤC TIÊU:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Consider issues with the current mobile phone reimbursement program\", \"vi\": \"Xin xem xét các vấn đề liên quan đến chương trình hoàn trả chi phí điện thoại di động hiện hành\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Review other options along with advantages and disadvantages\", \"vi\": \"Xem xét các phương án khác cùng với những ưu điểm và nhược điểm của chúng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Select a new reimbursement model, if appropriate\", \"vi\": \"Vui lòng lựa chọn một mô hình hoàn trả chi phí mới, nếu phù hợp\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"OPTIONS:\", \"vi\": \"CÁC LỰA CHỌN:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Continue to reimburse employees for up to 30 percent of their business mobile phone use\", \"vi\": \"Tiếp tục chi trả cho nhân viên tối đa 30 phần trăm chi phí sử dụng điện thoại di động phục vụ công việc\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Provide a flat monthly amount to employees who qualify; employees with high costs can submit requests for additional compensation\", \"vi\": \"Cung cấp một khoản trợ cấp cố định hàng tháng cho những nhân viên đủ điều kiện; những nhân viên có chi phí cao có thể nộp đơn đề nghị được hỗ trợ thêm\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Provide qualified employees with mobile phones for business use\", \"vi\": \"Cung cấp điện thoại di động cho các nhân viên đủ tiêu chuẩn để sử dụng trong công việc\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Ferd Data Services Employee Policies\", \"vi\": \"Các chính sách dành cho nhân viên của Ferd Data Services\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Mobile Phone Reimbursement Policy\", \"vi\": \"Chính sách hoàn trả chi phí điện thoại di động\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Revised October 30\", \"vi\": \"Cập nhật ngày 30 tháng 10\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Employees who work remotely and/or travel for business purposes should be reimbursed for business use of mobile phones.\", \"vi\": \"Các nhân viên làm việc từ xa và/hoặc đi công tác nên được hoàn trả chi phí sử dụng điện thoại di động cho mục đích công việc.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Three options are available:\", \"vi\": \"Có ba lựa chọn như sau:\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Employees who qualify will receive a mobile phone allowance of $20 per month, regardless of actual expenses.\", \"vi\": \"Những nhân viên đáp ứng điều kiện sẽ được hưởng khoản trợ cấp điện thoại di động trị giá 20 đô la mỗi tháng, bất kể chi phí thực tế là bao nhiêu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"To enroll in the program, employees must submit a Mobile Phone Allowance form with their supervisor\'s signature.\", \"vi\": \"Để đăng ký tham gia chương trình, nhân viên phải nộp mẫu đơn “Trợ cấp điện thoại di động” có chữ ký của người quản lý trực tiếp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"The $20 allowance will be applied to each month\'s paycheck.\", \"vi\": \"Khoản phụ cấp 20 đô la sẽ được trích trực tiếp vào tiền lương hàng tháng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Employees with large charges may submit actual expenses to receive additional reimbursement.\", \"vi\": \"Những nhân viên có khoản chi phí lớn có thể nộp chứng từ chi tiêu thực tế để được hoàn trả thêm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Managers and executives may opt for a company mobile phone, which is for business use only.\", \"vi\": \"Các quản lý và cán bộ điều hành có thể lựa chọn sử dụng điện thoại di động do công ty cấp, loại điện thoại này chỉ dành cho mục đích công việc.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}]' WHERE `id` = 'a1125702-735b-4517-a107-06dd27e70e55';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: board@sunnervalleyalliance.org\", \"vi\": \"Gửi tới: board@sunnervalleyalliance.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: kathleen.huff@sunnervalleyalliance.org\", \"vi\": \"Nguồn: kathleen.huff@sunnervalleyalliance.org\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: Tuesday, August 17\", \"vi\": \"Ngày: Thứ Ba, ngày 17 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Sunner Planning Commission meeting\", \"vi\": \"Chủ đề: Phiên họp của Ủy ban Quy hoạch Sunner\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Board Members,\", \"vi\": \"Kính gửi các thành viên Hội đồng quản trị,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am preparing to speak at the upcoming Sunner Planning Commission meeting and will be creating a slideshow to accompany my presentation.\", \"vi\": \"Tôi đang chuẩn bị phát biểu tại cuộc họp sắp tới của Ủy ban Quy hoạch Sunner và sẽ soạn một bản trình chiếu để hỗ trợ cho bài trình bày của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I have some great data to reinforce my points, but I think it will be easier for people to understand if the information is presented visually.\", \"vi\": \"Tôi có một số dữ liệu rất thuyết phục để củng cố các luận điểm của mình, nhưng tôi nghĩ mọi người sẽ dễ hiểu hơn nếu thông tin được trình bày dưới dạng trực quan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Is anybody interested in helping me develop the visual component of my presentation?\", \"vi\": \"Có ai quan tâm đến việc giúp tôi phát triển phần hình ảnh trong bài thuyết trình của tôi không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Some pie charts and diagrams would make a big impact in the slideshow.\", \"vi\": \"Một số biểu đồ hình tròn và sơ đồ sẽ góp phần tạo nên ấn tượng mạnh mẽ trong bản trình chiếu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The goal is to present the advantages and disadvantages of the three proposals for using the Holt property in northeast Sunner Valley.\", \"vi\": \"Mục tiêu là trình bày những ưu điểm và nhược điểm của ba đề xuất về việc sử dụng khu đất Holt ở phía đông bắc Thung lũng Sunner.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I am hoping that the commission accepts Ken Jansen\'s offer to buy the property, which is next to his land.\", \"vi\": \"Tôi hy vọng Ủy ban sẽ chấp nhận đề nghị mua lại bất động sản này – nằm ngay cạnh mảnh đất của ông ấy – từ phía ông Ken Jansen.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"He would expand his orchard and this would help maintain the rural nature of northern Sunner Valley.\", \"vi\": \"Ông sẽ mở rộng vườn cây ăn quả của mình và điều này sẽ góp phần duy trì bản sắc nông thôn của vùng phía bắc Thung lũng Sunner.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The speaker sign-up guidelines state that I will need to submit my presentation materials before the agenda gets posted online, but they do not specify when this will happen.\", \"vi\": \"Theo hướng dẫn đăng ký tham gia với tư cách diễn giả, tôi cần phải nộp tài liệu thuyết trình trước khi chương trình nghị sự được đăng tải trên mạng, nhưng hướng dẫn này không nêu rõ thời điểm cụ thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I will call today to find out more details.\", \"vi\": \"Hôm nay tôi sẽ gọi điện để tìm hiểu thêm chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Kathleen Huff\", \"vi\": \"Kathleen Huff\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = 'a14a82ae-24ff-4ba5-a02a-61ddda00e139';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Bulk of Difficult Sewer Improvement Project Finished\", \"vi\": \"Phần lớn công trình cải tạo hệ thống cống thoát nước phức tạp đã hoàn thành\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"STENDHAM (September 25)—Yesterday, the city of Stendham announced the conclusion of the first phase of the Lundgate Shore project.\", \"vi\": \"STENDHAM (ngày 25 tháng 9) — Hôm qua, thành phố Stendham đã công bố việc hoàn tất giai đoạn đầu tiên của dự án Lundgate Shore.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Located on the west bank of the Garmine River, the shore is named for nearby Lundgate Bridge.\", \"vi\": \"Nằm trên bờ tây của sông Garmine, khu vực bờ sông này được đặt tên theo cầu Lundgate gần đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The covered waterways that now sit there will stop excess sewage from spilling into the river by redirecting it into Clearway, Stendham’s enormous “sewage highway”.\", \"vi\": \"Các tuyến đường thủy được che phủ hiện đang nằm tại khu vực này sẽ ngăn chặn nước thải dư thừa tràn ra sông bằng cách chuyển hướng dòng chảy vào Clearway – “đường cao tốc nước thải” khổng lồ của Stendham.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The smooth completion of the phase is remarkable given the complex feats of engineering that were involved.\", \"vi\": \"Việc hoàn thành suôn sẻ giai đoạn này là một thành tựu đáng chú ý, đặc biệt khi xét đến những thách thức kỹ thuật phức tạp liên quan đến dự án.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The most challenging part was the installation of the 3,700-tonne main channel.\", \"vi\": \"Phần khó khăn nhất là việc lắp đặt kênh chính nặng 3.700 tấn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The Lundgate Shore is in a tidal area, and the river covers it completely at high tide.\", \"vi\": \"Bờ biển Lundgate nằm trong khu vực chịu ảnh hưởng của thủy triều, và khi thủy triều dâng cao, dòng sông sẽ ngập tràn toàn bộ khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Bauright Group, the company responsible for Phase 1, decided to make use of this feature and float the pre-built channel into place.\", \"vi\": \"Tập đoàn Bauright, đơn vị phụ trách Giai đoạn 1, đã quyết định tận dụng tính năng này và đưa kênh đã được lắp ráp sẵn vào vị trí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"“We had successfully used tidewater to move structures in other Clearway projects,” Bauright chief engineer Nancy Majors explained.\", \"vi\": \"“Chúng tôi đã từng sử dụng thành công dòng nước triều để di dời các công trình trong các dự án Clearway khác,” bà Nancy Majors, Kỹ sư trưởng của Bauright, giải thích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Still, the method required precise timing.\", \"vi\": \"Tuy nhiên, phương pháp này đòi hỏi phải tính toán thời gian một cách chính xác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The channel had to pass under Lundgate Bridge, so it could not be moved during high tide.\", \"vi\": \"Kênh này phải đi qua dưới cầu Lundgate, do đó không thể di dời trong thời gian thủy triều dâng cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"On the other hand, if the move was done when the water level was too low, the channel might not float all the way to its correct position.\", \"vi\": \"Mặt khác, nếu việc di chuyển được thực hiện khi mực nước quá thấp, kênh dẫn có thể sẽ không nổi được đến tận vị trí chính xác của nó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Ms. Majors said her team completed the difficult task without incident thanks to “extremely careful planning.”\", \"vi\": \"Bà Majors cho biết nhóm của bà đã hoàn thành nhiệm vụ khó khăn này mà không gặp sự cố nào nhờ vào “sự lên kế hoạch vô cùng cẩn thận.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Yesterday’s announcement also revealed that the simpler second phase of the project, which will be handled by Perriott, LLC, will end in November.\", \"vi\": \"Thông báo ngày hôm qua cũng cho biết rằng giai đoạn thứ hai của dự án – vốn đơn giản hơn và sẽ do công ty Perriott, LLC phụ trách – sẽ kết thúc vào tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Perriott will add a walking path, benches, and greenery to the public land above the new sewer structures.\", \"vi\": \"Perriott sẽ xây dựng thêm một lối đi dạo, các ghế ngồi và khu vực cây xanh trên khu đất công cộng nằm phía trên các công trình hệ thống thoát nước mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = 'a15ae66e-5c4c-4d50-851c-0d95c6ca93d9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Zovtech\", \"vi\": \"Zovtech\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Zovtech customers are most satisfied when they fully understand how to use their products and get the most out of them.\", \"vi\": \"Khách hàng của Zovtech sẽ cảm thấy hài lòng nhất khi họ hiểu rõ cách sử dụng sản phẩm và khai thác tối đa hiệu quả của chúng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Because Zovtech\'s products offer many innovative technology features, such as auto-timers on washing machines and variable light settings on microwave ovens, it is important to list and explain these features clearly in the user manuals.\", \"vi\": \"Do các sản phẩm của Zovtech sở hữu nhiều tính năng công nghệ tiên tiến, chẳng hạn như bộ hẹn giờ tự động trên máy giặt và các chế độ điều chỉnh độ sáng trên lò vi sóng, nên việc liệt kê và giải thích rõ ràng các tính năng này trong hướng dẫn sử dụng là điều rất quan trọng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"When writing the text for a manual, try to put yourself in the user\'s position and consider which features might need a more detailed explanation.\", \"vi\": \"Khi soạn thảo nội dung cho một cuốn hướng dẫn, quý vị hãy cố gắng đặt mình vào vị trí của người dùng và xem xét những tính năng nào có thể cần được giải thích chi tiết hơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Visual aids such as diagrams or photographs can be especially useful in outlining a process, and they can also serve to minimize the length and complexity of verbal instructions.\", \"vi\": \"Các phương tiện trực quan như sơ đồ hay hình ảnh có thể đặc biệt hữu ích trong việc phác thảo một quy trình, đồng thời chúng còn giúp giảm thiểu độ dài và mức độ phức tạp của các hướng dẫn bằng lời.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Including specific examples can also help users grasp complex concepts more quickly as well as determine early in the process if something is not working properly.\", \"vi\": \"Việc đưa ra các ví dụ cụ thể cũng có thể giúp người dùng nắm bắt các khái niệm phức tạp một cách nhanh chóng hơn, đồng thời xác định được ngay từ sớm trong quá trình thực hiện nếu có điều gì đó không hoạt động đúng cách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = 'a1b29bb0-dbd2-4991-a074-969c6f2ba824';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Outthinking Public Opinion - 12:00 noon–1:00 P.M., Salon A\", \"vi\": \"Nhìn xa trông rộng hơn dư luận - 12 giờ trưa – 1 giờ chiều, Phòng A\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Touring to promote his latest book, Outthinking Public Opinion, author Damian Schnauz makes a stop at the Uppsala International Book Fair to discuss his latest subject, take questions, and sign his books.\", \"vi\": \"Trong chuyến lưu diễn quảng bá cuốn sách mới nhất của mình, *Outthinking Public Opinion*, tác giả Damian Schnauz đã ghé thăm Hội chợ Sách Quốc tế Uppsala để trao đổi về chủ đề mới nhất trong tác phẩm, trả lời các câu hỏi và ký tặng sách.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Introductory Course in Graphic Design - 1:30–2:30 P.M., Visual Media Centre\", \"vi\": \"Khóa học cơ bản về Thiết kế đồ họa - 1:30–2:30 chiều, Trung tâm Truyền thông Hình ảnh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Professional digital designers Allen Doubek and Ivanette Lacasse will present useful techniques and provide attendees with hands-on practice opportunities.\", \"vi\": \"Các nhà thiết kế kỹ thuật số chuyên nghiệp Allen Doubek và Ivanette Lacasse sẽ giới thiệu những kỹ thuật hữu ích và tạo cơ hội thực hành trực tiếp cho quý vị tham dự.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Seminar on Online Publishing - 3:00–4:30 P.M., Lindqvist Auditorium\", \"vi\": \"Hội thảo về Xuất bản Trực tuyến - 3:00–4:30 chiều, Hội trường Lindqvist\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Releasing and promoting e-books and audiobooks on the Internet. Speakers: Kenneth Pulaski, editor-in-chief of Vendler Publishing, and Tina Savona, marketing manager at Vendler Publishing. All accompanying materials will be sold at the venue immediately before and after the seminar.\", \"vi\": \"Phát hành và quảng bá sách điện tử và sách nói trên Internet. Diễn giả: Ông Kenneth Pulaski, Tổng biên tập của Nhà xuất bản Vendler, và bà Tina Savona, Giám đốc tiếp thị tại Nhà xuất bản Vendler. Tất cả các tài liệu liên quan sẽ được bán tại địa điểm tổ chức ngay trước và sau buổi hội thảo.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Readership in the Digital Age - 5:00–6:30 P.M., Room 210\", \"vi\": \"Thói quen đọc sách trong thời đại số - 5:00–6:30 chiều, Phòng 210\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Is literacy promoted or inhibited by digital media? Debate moderated by Greg Gunnarson.\", \"vi\": \"Phương tiện truyền thông kỹ thuật số có thúc đẩy hay cản trở việc nâng cao trình độ đọc viết? Buổi thảo luận do ông Greg Gunnarson điều phối.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The Uppsala International Book Fair\", \"vi\": \"Hội chợ Sách Quốc tế Uppsala\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"22–24 September • Berglund Conference Hall • Uppsala, Sweden\", \"vi\": \"22–24 tháng 9 • Hội trường Berglund • Uppsala, Thụy Điển\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Schedule for Friday, 22 September\", \"vi\": \"Lịch trình cho ngày thứ Sáu, 22 tháng 9\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"• To attend these or any other sessions, purchase a daily admission ticket for 100 kr.\", \"vi\": \"• Để tham dự các buổi này hoặc bất kỳ buổi nào khác, quý vị vui lòng mua vé vào cửa hàng ngày với giá 100 kr.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"• Note that reservations are not required for any session, but seating is limited, so please arrive a few minutes before the scheduled time to ensure a seat.\", \"vi\": \"• Xin lưu ý rằng quý vị không cần đặt chỗ trước cho bất kỳ buổi nào, tuy nhiên số lượng chỗ ngồi có hạn, vì vậy xin vui lòng đến sớm vài phút trước giờ dự kiến để đảm bảo có chỗ ngồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Also note that while photos are permitted, no video recordings may be made of any presentation.\", \"vi\": \"Xin lưu ý thêm rằng mặc dù được phép chụp ảnh, nhưng tuyệt đối không được quay video bất kỳ bài thuyết trình nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"• Meals are available for purchase at locations throughout Berglund Conference Hall.\", \"vi\": \"• Quý vị có thể mua các bữa ăn tại các điểm phục vụ trên toàn bộ khuôn viên Hội trường Berglund.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Information about accommodations may be obtained on our Web site at uibf.se/hotels.\", \"vi\": \"Quý vị có thể tra cứu thông tin về các loại hình lưu trú trên trang web của chúng tôi tại địa chỉ uibf.se/hotels.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = 'a1f18fac-16c1-43dc-bea2-9bea3bf1cb3b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Angela Jenkins\", \"vi\": \"Kính gửi: Angela Jenkins\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Marcus Keller\", \"vi\": \"Từ: Marcus Keller\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: Friday, 2 November\", \"vi\": \"Ngày: Thứ Sáu, ngày 2 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Postpone call\", \"vi\": \"Chủ đề: Hoãn cuộc gọi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Angela,\", \"vi\": \"Angel,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Unfortunately, I have to cancel our planned afternoon phone call at the last minute—I hope you get this e-mail in time.\", \"vi\": \"Rất tiếc, tôi buộc phải hủy cuộc gọi điện thoại vào buổi chiều mà chúng ta đã hẹn vào phút chót — tôi hy vọng quý vị sẽ nhận được email này kịp thời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Could we please reschedule?\", \"vi\": \"Chúng ta có thể sắp xếp lại lịch được không ạ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This was my mistake, as I somehow double-booked our appointment time.\", \"vi\": \"Đây là lỗi của tôi, vì không hiểu sao tôi lại đặt trùng giờ hẹn của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In fact, I am on my way out the door right now to keep the other appointment—a meeting with a high-priority client.\", \"vi\": \"Thực ra, hiện tại tôi đang chuẩn bị ra khỏi cửa để đến cuộc hẹn còn lại — một cuộc họp với một khách hàng quan trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I apologize.\", \"vi\": \"Tôi xin lỗi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Would teleconferencing on Monday at noon work for you?\", \"vi\": \"Cuộc họp trực tuyến vào trưa thứ Hai có phù hợp với quý vị không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Also, prior to our meeting, could you look further into any grant opportunities that might be available for the current project?\", \"vi\": \"Ngoài ra, trước khi chúng ta gặp nhau, quý vị có thể tìm hiểu thêm về các cơ hội nhận tài trợ có thể áp dụng cho dự án hiện tại được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Meanwhile, I will ask Leona to calculate more accurate budgets for some future initiatives that will need funding.\", \"vi\": \"Trong khi đó, tôi sẽ đề nghị Leona lập các dự toán ngân sách chính xác hơn cho một số sáng kiến trong tương lai sẽ cần nguồn kinh phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"That will allow us to be more productive when we meet next week.\", \"vi\": \"Điều đó sẽ giúp chúng ta làm việc hiệu quả hơn trong cuộc họp vào tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Marcus Keller\", \"vi\": \"Marcus Keller\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"O’Connor Small Business Foundation\", \"vi\": \"Quỹ Hỗ trợ Doanh nghiệp Nhỏ O’Connor\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = 'a20b5a17-3772-4e60-8f68-d2656edc0dfb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Corbissin Corporation\", \"vi\": \"Tập đoàn Corbissin\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Minutes of Quarterly Finance Team Meeting\", \"vi\": \"Biên bản cuộc họp quý của Nhóm Tài chính\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Thursday, 18 October\", \"vi\": \"Thứ Năm, ngày 18 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Present: Lorenzo Abeyta (Chair), Dolores Tengco, Perla Buenaflor, Omar Mayuga, and Cora Odevilas\", \"vi\": \"Các thành viên có mặt: Lorenzo Abeyta (Chủ tịch), Dolores Tengco, Perla Buenaflor, Omar Mayuga và Cora Odevilas\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Absent: Juan Carlos Serapio (attending International Technology Conference)\", \"vi\": \"Vắng mặt: Juan Carlos Serapio (đang tham dự Hội nghị Công nghệ Quốc tế)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The meeting was called to order at 10:30 A.M. by Lorenzo Abeyta.\", \"vi\": \"Cuộc họp được ông Lorenzo Abeyta khai mạc vào lúc 10 giờ 30 phút sáng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The minutes from the 20 June meeting were approved unanimously.\", \"vi\": \"Biên bản cuộc họp ngày 20 tháng 6 đã được thông qua với sự nhất trí của toàn thể các thành viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Financial Summary (presented by Omar Mayuga)\", \"vi\": \"Tóm tắt tài chính (do ông Omar Mayuga trình bày)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Revenue from the last quarter was up by 10 percent.\", \"vi\": \"Doanh thu của quý vừa qua đã tăng 10 phần trăm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The budget has been approved for the hiring of additional sales personnel and customer service associates.\", \"vi\": \"Ngân sách dành cho việc tuyển dụng thêm nhân viên bán hàng và nhân viên chăm sóc khách hàng đã được phê duyệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Discussion of the proposed internship program was postponed until more research has been done.\", \"vi\": \"Việc thảo luận về chương trình thực tập được đề xuất đã được hoãn lại cho đến khi có thêm các nghiên cứu được thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Perla Buenaflor will look into this proposal and present a report at the next meeting.\", \"vi\": \"Bà Perla Buenaflor sẽ xem xét đề xuất này và trình bày báo cáo tại cuộc họp tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The \\\"We All Tell a Story\\\" marketing campaign is under way.\", \"vi\": \"Chiến dịch tiếp thị “We All Tell a Story” hiện đang được triển khai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The project features testimonials from small-business owners whose office operations improved after installation of our products.\", \"vi\": \"Dự án này giới thiệu những lời chia sẻ từ các chủ doanh nghiệp nhỏ, những người đã thấy hoạt động văn phòng của mình được cải thiện sau khi lắp đặt các sản phẩm của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Announcements\", \"vi\": \"Thông báo\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dolores Tengco confirmed that the launch of our new line of printers and copiers is set for 10 November.\", \"vi\": \"Bà Dolores Tengco đã xác nhận rằng lễ ra mắt dòng sản phẩm máy in và máy photocopy mới của chúng tôi sẽ diễn ra vào ngày 10 tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"There will be commercials on TV and radio, online, and in print media.\", \"vi\": \"Sẽ có các quảng cáo trên truyền hình và đài phát thanh, trên mạng cũng như trên các phương tiện truyền thông in ấn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Stores in Mandaluyong and Taguig are planning full-day events.\", \"vi\": \"Các cửa hàng tại Mandaluyong và Taguig đang lên kế hoạch tổ chức các sự kiện kéo dài cả ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"More information on other sales events in stores will be released soon.\", \"vi\": \"Thông tin chi tiết về các chương trình khuyến mãi khác tại các cửa hàng sẽ được công bố trong thời gian tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"The meeting was adjourned at 11:30 A.M. by Lorenzo Abeyta.\", \"vi\": \"Cuộc họp đã được ông Lorenzo Abeyta tuyên bố tạm hoãn vào lúc 11 giờ 30 phút sáng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = 'a2539789-bc04-4c45-866d-a22737151f2d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Joanne Matos (11:45 A.M.)\", \"vi\": \"Joanne Matos (11 giờ 45 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Tuyet and Jim, do you know where I can find that big signboard—the one that we usually post at the entrance to advertise when we\'re having a sale inside?\", \"vi\": \"Tuyết và Jim, hai bạn có biết tôi có thể tìm tấm biển quảng cáo lớn đó ở đâu không — chính là tấm biển mà chúng ta thường treo ở lối vào để thông báo khi có chương trình giảm giá bên trong?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Tuyet Nguyen (11:58 A.M.)\", \"vi\": \"Tuyết Nguyễn (11 giờ 58 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I haven\'t seen it lately.\", \"vi\": \"Gần đây tôi chưa được xem nó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Why?\", \"vi\": \"Tại sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Joanne Matos (11:59 A.M.)\", \"vi\": \"Joanne Matos (11 giờ 59 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I\'m setting up for this afternoon\'s party under the tent out in the café courtyard, and I want to have seating information posted for people as they arrive.\", \"vi\": \"Tôi đang chuẩn bị cho bữa tiệc chiều nay dưới lều ở sân trong của quán cà phê, và tôi muốn treo thông tin về chỗ ngồi để mọi người có thể tham khảo khi đến nơi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Tuyet Nguyen (12:01 P.M.)\", \"vi\": \"Tuyết Nguyễn (12 giờ 01 phút trưa)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Jim likely has it.\", \"vi\": \"Có lẽ Jim đang giữ nó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"He usually sets things up for those sales.\", \"vi\": \"Thông thường, ông ấy là người chuẩn bị mọi thứ cho các đợt bán hàng đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"But I think he\'s gone for the day.\", \"vi\": \"Tuy nhiên, tôi nghĩ là anh ấy đã ra ngoài cả ngày rồi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Jim Thomas (12:02 P.M.)\", \"vi\": \"Jim Thomas (12 giờ 02 phút trưa)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"No, I\'m not!\", \"vi\": \"Không, tôi không phải đâu!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I\'m out making a delivery right now, but I\'ll be back soon.\", \"vi\": \"Hiện tại tôi đang đi giao hàng, nhưng tôi sẽ quay lại ngay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"You can find the signboard in the alcove just inside our building\'s delivery entrance.\", \"vi\": \"Quý vị có thể tìm thấy tấm biển ở hốc tường ngay bên trong lối vào dành cho giao hàng của tòa nhà chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Just put it back when you\'re done so that I can find it the next time I need it.\", \"vi\": \"Khi dùng xong, xin vui lòng đặt lại chỗ cũ để lần sau tôi cần thì có thể tìm thấy được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Joanne Matos (12:04 P.M.)\", \"vi\": \"Joanne Matos (12 giờ 04 phút chiều)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"No problem.\", \"vi\": \"Không sao đâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thanks!\", \"vi\": \"Cảm ơn!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = 'a257e648-fdcb-48f9-ab33-724be7705e22';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Livrou Farm\", \"vi\": \"Trang trại Livrou\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Fresh Organic Produce - From Our Farm to Your Home\", \"vi\": \"Nông sản hữu cơ tươi ngon – Từ trang trại của chúng tôi đến tận nhà quý khách\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Livrou Farm in Bromont, Quebec, invites you to participate in its community-supported agriculture program.\", \"vi\": \"Trang trại Livrou tại Bromont, Quebec, trân trọng kính mời quý vị tham gia chương trình nông nghiệp do cộng đồng hỗ trợ của trang trại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Members enjoy fresh farm produce during our growing season from June to November.\", \"vi\": \"Các thành viên được thưởng thức các sản phẩm nông sản tươi ngon trong mùa vụ của chúng tôi, từ tháng 6 đến tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Sign up for a farm share and receive these benefits:\", \"vi\": \"Hãy đăng ký tham gia chương trình chia sẻ sản phẩm nông trại để nhận được những lợi ích sau đây:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"More than 30 varieties of in-season vegetables, fruits, and herbs, harvested by our farm staff and prepared for you to pick up at our barn\", \"vi\": \"Hơn 30 loại rau, trái cây và thảo mộc đang vào mùa, được đội ngũ nhân viên trang trại của chúng tôi thu hoạch và chuẩn bị sẵn để quý vị đến nhận tại nhà kho của chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"A selection of pick-your-own strawberries, apples, and other fruits\", \"vi\": \"Một số loại dâu tây, táo và các loại trái cây khác dành cho quý vị tự hái\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Access to our member Web site with recipes, farm updates, and a farm newsletter\", \"vi\": \"Quyền truy cập vào trang web dành cho thành viên của chúng tôi với các công thức nấu ăn, thông tin cập nhật về trang trại và bản tin trang trại\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Discounts on events at the farm, such as the annual summer music festival.\", \"vi\": \"Các chương trình giảm giá dành cho các sự kiện tại trang trại, chẳng hạn như lễ hội âm nhạc mùa hè hàng năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Events typically cost $15, but members pay $10.\", \"vi\": \"Thông thường, phí tham gia các sự kiện là 15 đô la, nhưng các thành viên chỉ phải trả 10 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Members pick up their shares once a week at the farm.\", \"vi\": \"Các thành viên đến trang trại nhận phần sản phẩm của mình mỗi tuần một lần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"A full-size share is $700 per season, and a half-size share is $350.\", \"vi\": \"Một phần cổ phần đầy đủ có giá 700 đô la mỗi mùa, còn một phần cổ phần nửa mức có giá 350 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Half-size shareholders receive half the amount of produce each week.\", \"vi\": \"Các cổ đông có phần góp bằng một nửa sẽ nhận được một nửa số sản phẩm mỗi tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"All other benefits remain the same.\", \"vi\": \"Tất cả các quyền lợi khác vẫn giữ nguyên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Our farm produce is grown without the use of pesticides or herbicides, and we use only naturally occurring fertilizers.\", \"vi\": \"Các sản phẩm nông nghiệp của chúng tôi được trồng mà không sử dụng thuốc trừ sâu hay thuốc diệt cỏ, và chúng tôi chỉ sử dụng các loại phân bón có nguồn gốc tự nhiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"For more information or to register for a membership, please see our Web site at www.livroufarm.ca.\", \"vi\": \"Để biết thêm thông tin hoặc đăng ký trở thành hội viên, xin vui lòng truy cập trang web của chúng tôi tại địa chỉ www.livroufarm.ca.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Livrou Farm - Membership Form\", \"vi\": \"Trang trại Livrou - Mẫu đơn đăng ký thành viên\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"http://www.livroufarm.ca\", \"vi\": \"http://www.livroufarm.ca\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Livrou Farm | Membership | Home | Locations | Reviews |\", \"vi\": \"Trang trại Livrou | Chương trình thành viên | Trang chủ | Các địa điểm | Đánh giá |\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Name: Julien Bernard\", \"vi\": \"Họ tên: Julien Bernard\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Address: 78 Dorion Street, Bromont, QC J2L 2K7\", \"vi\": \"Địa chỉ: 78 Đường Dorion, Bromont, QC J2L 2K7\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"First choice pick-up day: Friday\", \"vi\": \"Ngày nhận hàng ưu tiên: Thứ Sáu\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Second choice pick-up day: Friday\", \"vi\": \"Ngày nhận hàng theo lựa chọn thứ hai: Thứ Sáu\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Size of share: Half\", \"vi\": \"Tỷ lệ sở hữu: Một nửa\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"NOTE: Pick-up is between 3 P.M. and 6 P.M.\", \"vi\": \"LƯU Ý: Thời gian nhận hàng là từ 3 giờ chiều đến 6 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Please provide the names of other individuals in your household.\", \"vi\": \"Xin vui lòng cung cấp tên của những người khác trong hộ gia đình của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"These are the only other individuals who will be permitted to pick up your weekly share.\", \"vi\": \"Đây là những người duy nhất khác được phép đến nhận phần hàng tuần của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Names: Margaux Bernard, Laurent Bernard\", \"vi\": \"Tên: Margaux Bernard, Laurent Bernard\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}]' WHERE `id` = 'a28959da-d939-4795-9247-e4bcdbee148a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Cheryl Futrel\", \"vi\": \"Kính gửi: Cheryl Futrel\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Lydia Matsuda\", \"vi\": \"Từ: Lydia Matsuda\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: June 9\", \"vi\": \"Ngày: 9 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Home decorating\", \"vi\": \"Chủ đề: Trang trí nội thất\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Futrel,\", \"vi\": \"Kính gửi bà Futrel,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for your interest in Candella Interior Design.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã quan tâm đến Công ty Thiết kế Nội thất Candella.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We are proud to claim that we are the oldest and most successful online design consulting company in the region.\", \"vi\": \"Chúng tôi tự hào khẳng định rằng mình là công ty tư vấn thiết kế trực tuyến lâu đời nhất và thành công nhất trong khu vực.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We welcome you as a new client.\", \"vi\": \"Chúng tôi xin chào đón quý khách với tư cách là khách hàng mới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"From modest country homes to urban apartments, we do it all.\", \"vi\": \"Từ những ngôi nhà nông thôn khiêm tốn cho đến các căn hộ đô thị, chúng tôi đều có thể thực hiện mọi công việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We understand from your original inquiry that you intend to sell your apartment soon and are primarily interested in how best to present it to prospective buyers.\", \"vi\": \"Theo nội dung yêu cầu ban đầu của quý vị, chúng tôi được biết quý vị có ý định bán căn hộ của mình trong thời gian tới và chủ yếu quan tâm đến cách thức trình bày căn hộ một cách ấn tượng nhất trước các khách hàng tiềm năng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Here’s how our design services work: the first step is completing an online questionnaire.\", \"vi\": \"Dưới đây là cách thức hoạt động của các dịch vụ thiết kế của chúng tôi: bước đầu tiên là điền vào một bảng câu hỏi trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Next, you will be matched with an online professional interior designer who can help you with all choices for paint colors, window treatments, and floor coverings.\", \"vi\": \"Tiếp theo, quý vị sẽ được kết nối với một nhà thiết kế nội thất chuyên nghiệp trực tuyến, người có thể hỗ trợ quý vị trong mọi quyết định liên quan đến màu sơn, rèm cửa và vật liệu lát sàn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"You will receive a room layout plan and a personalized list of ideas for furniture and accessories, with all products available for purchase online.\", \"vi\": \"Quý vị sẽ nhận được bản vẽ bố trí phòng cùng danh sách các gợi ý được cá nhân hóa về đồ nội thất và phụ kiện, với tất cả các sản phẩm đều có thể mua trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"As a special bonus, from now until July 1 our online retail partners have agreed to offer a 10 percent discount on products purchased through our links.\", \"vi\": \"Như một ưu đãi đặc biệt, từ nay đến ngày 1 tháng 7, các đối tác bán lẻ trực tuyến của chúng tôi đã đồng ý áp dụng mức giảm giá 10% cho các sản phẩm được mua qua các liên kết của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Finally, you will be glad to learn that we charge not by the hour but by the room for our design ideas, with the average price being about $275 per room.\", \"vi\": \"Cuối cùng, chắc hẳn quý vị sẽ rất vui khi biết rằng chúng tôi không tính phí theo giờ mà tính theo phòng đối với các ý tưởng thiết kế của mình, với mức giá trung bình khoảng 275 đô la cho mỗi phòng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"We look forward to hearing from you and working with you soon.\", \"vi\": \"Chúng tôi rất mong sớm nhận được phản hồi từ quý vị và có cơ hội hợp tác cùng quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Lydia Matsuda\", \"vi\": \"Lydia Matsuda\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = 'a29cb9f4-f3df-4e53-af69-b4f8c51b3662';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Help Wanted: Machinist\", \"vi\": \"Tuyển dụng: Thợ máy\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Camerley Corp. of Napier, New Zealand, has an opening for an experienced machinist to work in our 15,000-square-metre fabrication plant, which produces custom tools and machine parts for a variety of industries.\", \"vi\": \"Công ty Camerley Corp. có trụ sở tại Napier, New Zealand, hiện đang tuyển dụng một thợ gia công có kinh nghiệm để làm việc tại nhà máy gia công rộng 15.000 mét vuông của chúng tôi, nơi chuyên sản xuất các dụng cụ và linh kiện máy móc theo yêu cầu cho nhiều ngành công nghiệp khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Requirements for the position include:\", \"vi\": \"Các yêu cầu đối với vị trí này bao gồm:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Ability to collaborate with engineers to fabricate tools and machine parts\", \"vi\": \"Khả năng phối hợp với các kỹ sư để chế tạo dụng cụ và các bộ phận máy móc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Familiarity with specialised equipment\", \"vi\": \"Sự am hiểu về các thiết bị chuyên dụng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Skill with doing precision work based on technical drawings\", \"vi\": \"Có kỹ năng thực hiện các công việc đòi hỏi độ chính xác cao dựa trên bản vẽ kỹ thuật\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Comfort working with metal and various other materials, such as wood and plastics\", \"vi\": \"Có khả năng làm việc thành thạo với kim loại và các loại vật liệu khác, chẳng hạn như gỗ và nhựa\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Ability to work both independently and as part of a team\", \"vi\": \"Khả năng làm việc độc lập cũng như làm việc theo nhóm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"To apply, please send CV and two references to jobs@camerleycorp.co.nz.\", \"vi\": \"Để nộp đơn ứng tuyển, xin vui lòng gửi sơ yếu lý lịch cùng hai thư giới thiệu đến địa chỉ email jobs@camerleycorp.co.nz.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = 'a2b133a5-2cdd-445d-9e09-bb232196020b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Cindy Berry (11:24 a.m.)\", \"vi\": \"Cindy Berry (11 giờ 24 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Jonathan.\", \"vi\": \"Xin chào, Jonathan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I\'m processing your latest expense report, and I noticed that you entered the wrong amount for your lunch on August 7.\", \"vi\": \"Tôi đang xử lý bản báo cáo chi phí mới nhất của quý vị và nhận thấy rằng quý vị đã nhập sai số tiền cho bữa trưa vào ngày 7 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The restaurant receipt says $25.67, not $25.76.\", \"vi\": \"Hóa đơn nhà hàng ghi là 25,67 đô la, chứ không phải 25,76 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Could you fix that and the total amount and resubmit your report?\", \"vi\": \"Xin quý vị vui lòng điều chỉnh lại phần đó cũng như tổng số tiền, sau đó gửi lại báo cáo của quý vị được không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Jonathan Parks (11:26 a.m.)\", \"vi\": \"Jonathan Parks (11 giờ 26 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Ah, sorry for the mistake.\", \"vi\": \"À, xin lỗi vì sai sót này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Sure, I\'ll get that to you first thing tomorrow.\", \"vi\": \"Được rồi, tôi sẽ gửi cho quý vị ngay vào sáng sớm mai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Cindy Berry (11:27 a.m.)\", \"vi\": \"Cindy Berry (11 giờ 27 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The deadline is today.\", \"vi\": \"Hạn chót là hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Otherwise, you\'ll have to wait an extra month for reimbursement.\", \"vi\": \"Nếu không, quý vị sẽ phải chờ thêm một tháng nữa mới được hoàn trả chi phí.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Jonathan Parks (11:28 a.m.)\", \"vi\": \"Jonathan Parks (11 giờ 28 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Well, I\'m working from home today.\", \"vi\": \"À, hôm nay tôi làm việc tại nhà.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"And you don\'t accept reports over e-mail, right?\", \"vi\": \"Và quý vị không chấp nhận các báo cáo gửi qua email, phải không ạ?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Cindy Berry (11:29 a.m.)\", \"vi\": \"Cindy Berry (11 giờ 29 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Right—we need a signed paper copy.\", \"vi\": \"Đúng vậy — chúng tôi cần một bản giấy có chữ ký.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"OK, I\'ll see you tomorrow, then.\", \"vi\": \"Vậy thì được rồi, vậy ngày mai tôi sẽ gặp quý vị.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = 'a2bec5fd-d43a-4630-8ca8-c05a99fcf2e2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Lauri Woods <lauriwoods@coralmail.com>\", \"vi\": \"Gửi tới: Lauri Woods <lauriwoods@coralmail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Customer Service <customerservice@honeycanyonapparel.com>\", \"vi\": \"Từ: Bộ phận Dịch vụ Khách hàng <customerservice@honeycanyonapparel.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: October 4\", \"vi\": \"Ngày: 4 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Thank you\", \"vi\": \"Tiêu đề: Lời cảm ơn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Woods,\", \"vi\": \"Kính gửi bà Woods,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for your recent purchase!\", \"vi\": \"Xin chân thành cảm ơn quý khách đã mua hàng gần đây!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We hope you are enjoying your items.\", \"vi\": \"Chúng tôi hy vọng quý vị đang hài lòng với các sản phẩm của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We wanted to take the opportunity to suggest some other items you might like.\", \"vi\": \"Chúng tôi xin nhân dịp này đề xuất một số sản phẩm khác mà quý khách có thể quan tâm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Please visit honeycanyonapparel.com/wardrobe and enter code RN49X to see a list of suggestions curated especially for you.\", \"vi\": \"Kính mời quý vị truy cập trang honeycanyonapparel.com/wardrobe và nhập mã RN49X để xem danh sách các gợi ý được tuyển chọn riêng dành cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Among the selections, we have highlighted several sweaters that would look beautiful with the skirt you bought.\", \"vi\": \"Trong số các sản phẩm được lựa chọn, chúng tôi đã giới thiệu một số mẫu áo len sẽ rất hợp với chiếc váy mà quý vị vừa mua.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"And, to thank you for being a Honey Canyon customer for so many years, we are also offering you a 20 percent discount on your next order.\", \"vi\": \"Bên cạnh đó, để tri ân quý khách đã tin dùng sản phẩm của Honey Canyon trong suốt nhiều năm qua, chúng tôi xin dành tặng quý khách mức giảm giá 20% cho đơn hàng tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Simply place an order within one month to receive the discount.\", \"vi\": \"Quý khách chỉ cần đặt hàng trong vòng một tháng để được hưởng ưu đãi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"We look forward to helping you fill your closet with our latest styles!\", \"vi\": \"Chúng tôi rất mong được giúp quý vị làm phong phú thêm tủ quần áo của mình bằng những mẫu thiết kế mới nhất của chúng tôi!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Customer Service, Honey Canyon Apparel\", \"vi\": \"Bộ phận Chăm sóc Khách hàng, Honey Canyon Apparel\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = 'a2d3bb2b-0cc0-4410-b3d0-c1c5ebc85e09';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Harrod Automotive Manufacturing\", \"vi\": \"Công ty Sản xuất Ô tô Harrod\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Andrew Dunn, Director\", \"vi\": \"Andrew Dunn, Giám đốc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Laura Bradley, Site Manager\", \"vi\": \"Bà Laura Bradley, Quản lý công trường\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Welcome to Harrod Automotive Manufacturing!\", \"vi\": \"Chào mừng quý vị đến với Harrod Automotive Manufacturing!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We are serious about maintaining a safe workplace environment.\", \"vi\": \"Chúng tôi luôn coi trọng việc duy trì một môi trường làm việc an toàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We ask that the following rules be strictly observed while you are touring the assembly floor.\", \"vi\": \"Chúng tôi đề nghị quý vị tuân thủ nghiêm ngặt các quy định sau đây trong suốt thời gian tham quan khu vực dây chuyền lắp ráp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Anyone found in violation of these rules will be asked to leave the premises.\", \"vi\": \"Bất kỳ ai bị phát hiện vi phạm các quy định này sẽ bị yêu cầu rời khỏi khuôn viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"For concerns about compliance, please contact the site manager.\", \"vi\": \"Nếu có thắc mắc liên quan đến việc tuân thủ, xin vui lòng liên hệ với người quản lý cơ sở.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"ALWAYS:\", \"vi\": \"LUÔN LUÔN:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Stay with your tour guide.\", \"vi\": \"Xin quý vị hãy đi cùng hướng dẫn viên du lịch của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Wear safety glasses and helmet.\", \"vi\": \"Hãy đeo kính bảo hộ và mũ bảo hiểm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Respond to alarm signals and obey evacuation instructions.\", \"vi\": \"Hãy phản ứng kịp thời trước các tín hiệu báo động và tuân thủ các hướng dẫn sơ tán.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Request permission from your guide before taking photographs.\", \"vi\": \"Trước khi chụp ảnh, xin vui lòng xin phép hướng dẫn viên của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"NEVER:\", \"vi\": \"KHÔNG BAO GIỜ:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Leave your group.\", \"vi\": \"Xin hãy rời khỏi nhóm của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Enter areas marked \\\"Danger\\\" or \\\"Staff Only.\\\"\", \"vi\": \"Vui lòng không vào các khu vực có biển báo “Nguy hiểm” hoặc “Chỉ dành cho nhân viên.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Touch equipment.\", \"vi\": \"Thiết bị cảm ứng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = 'a2dbc024-4c81-45ad-b536-ab5ffa90380e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Multiple Recipients\", \"vi\": \"Đến: Nhiều Người Nhận\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Gold Star Bank <information@goldstarbank.co.in>\", \"vi\": \"Từ: Gold Star Bank <information@goldstarbank.co.in>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Gold Star Bank App\", \"vi\": \"Chủ đề: Ứng dụng Gold Star Bank\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 15 July\", \"vi\": \"Ngày: 15 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Customer:\", \"vi\": \"Kính gửi Quý khách hàng:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Here at Gold Star Bank, we take our customers and their needs seriously.\", \"vi\": \"Tại Gold Star Bank, chúng tôi luôn coi trọng khách hàng và các nhu cầu của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As some of you know, we ______[131] technical difficulties with our mobile app.\", \"vi\": \"Như một số quý vị đã biết, chúng tôi ______[131] các sự cố kỹ thuật với ứng dụng di động của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [131]}, {\"en\": \"______[132].\", \"vi\": \"______[132].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [132]}, {\"en\": \"The trouble started on 14 July when our system went down because of a software bug.\", \"vi\": \"Sự cố bắt đầu vào ngày 14 tháng 7 khi hệ thống của chúng tôi bị ngừng hoạt động do lỗi phần mềm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"We expect the app to be up and running ______[133] the next twenty-four hours.\", \"vi\": \"Chúng tôi kỳ vọng ứng dụng sẽ hoạt động trở lại ______[133] trong vòng 24 giờ tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [133]}, {\"en\": \"______[134] banking transactions can be done at any of our branch locations, and our automated cash machines are also working.\", \"vi\": \"______[134] các giao dịch ngân hàng có thể được thực hiện tại bất kỳ chi nhánh nào của chúng tôi, và các máy rút tiền tự động của chúng tôi cũng vẫn hoạt động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [134]}, {\"en\": \"We apologize for any inconvenience.\", \"vi\": \"Chúng tôi thành thật xin lỗi vì bất kỳ sự bất tiện nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Ravi Chadda\", \"vi\": \"Ravi Chadda\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Vice President of Customer Relations\", \"vi\": \"Phó Chủ tịch Quan hệ Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = 'a40cdbb0-ff53-428f-9c8d-80580eb21b15';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Kahoda Naidu\", \"vi\": \"Đến: Kahoda Naidu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: info@vistapharmacy.com\", \"vi\": \"Từ: info@vistapharmacy.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: April 24\", \"vi\": \"Ngày: 24 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: New Vista Pharmacy branch!\", \"vi\": \"Chủ đề: Chi nhánh mới của Vista Pharmacy!\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Naidu,\", \"vi\": \"Kính gửi ông Naidu,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The staff at Vista Pharmacy is ______[139] to announce that we will open a second branch to better serve our customers.\", \"vi\": \"Nhân viên tại Vista Pharmacy rất ______[139] thông báo rằng chúng tôi sẽ mở một chi nhánh thứ hai để phục vụ khách hàng tốt hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [139]}, {\"en\": \"The branch will be located at 905 Victoria Street.\", \"vi\": \"Chi nhánh này sẽ tọa lạc tại số 905 phố Victoria.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As with our original site, the new branch will offer a comprehensive list of services beyond filling prescriptions.\", \"vi\": \"Giống như cơ sở ban đầu của chúng tôi, chi nhánh mới sẽ cung cấp danh mục dịch vụ toàn diện ngoài việc cấp phát thuốc theo toa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[140]\", \"vi\": \"______[140]\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [140]}, {\"en\": \"The Victoria Street branch also has a drive-up window.\", \"vi\": \"Chi nhánh phố Victoria cũng có một ô cửa sổ phục vụ khách mua hàng từ ô tô.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"At the window or inside, you can stop by anytime during our business hours ______[141] your medicine.\", \"vi\": \"Tại ô cửa sổ đó hoặc bên trong, quý khách có thể ghé qua bất cứ lúc nào trong giờ làm việc của chúng tôi ______[141] thuốc của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [141]}, {\"en\": \"As always, we can answer any questions you may have about what your ______[142] prescribed to you.\", \"vi\": \"Như thường lệ, chúng tôi có thể giải đáp mọi thắc mắc của quý khách về những gì ______[142] của quý khách đã kê đơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [142]}, {\"en\": \"We look forward to serving you!\", \"vi\": \"Chúng tôi rất mong được phục vụ quý khách!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Warmest regards,\", \"vi\": \"Trân trọng nhất,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The Vista Pharmacy Team\", \"vi\": \"Đội ngũ Vista Pharmacy\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = 'a417475c-0f26-4d7c-be33-29e9d20ef6b8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Corporate Training News\", \"vi\": \"Tin tức Đào tạo Doanh nghiệp\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Multinational appliance manufacturer Crystal Technologies recently ------- (135) an innovative training program for workers.\", \"vi\": \"Nhà sản xuất thiết bị đa quốc gia Crystal Technologies gần đây đã ------- (135) một chương trình đào tạo đổi mới cho nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [135]}, {\"en\": \"The program uses what are called \\\"escape rooms\\\" to build teamwork and creative problem-solving skills.\", \"vi\": \"Chương trình sử dụng cái gọi là \\\"phòng thoát hiểm\\\" để xây dựng kỹ năng làm việc nhóm và giải quyết vấn đề sáng tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"A special facility has been built for this purpose within the company\'s headquarters in Inverness, Scotland.\", \"vi\": \"Một cơ sở đặc biệt đã được xây dựng cho mục đích này bên trong trụ sở chính của công ty tại Inverness, Scotland.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The facility consists of four rooms, ------- (136) of which is designed to represent a different geographic area that is part of Crystal\'s global operations.\", \"vi\": \"Cơ sở này bao gồm bốn phòng, ------- (136) trong số đó được thiết kế để đại diện cho một khu vực địa lý khác nhau là một phần trong các hoạt động toàn cầu của Crystal.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [136]}, {\"en\": \"Working in teams of five, employees must solve a business problem particular to that area to be able to unlock the door and enter the next room.\", \"vi\": \"Làm việc theo nhóm năm người, nhân viên phải giải quyết một vấn đề kinh doanh cụ thể của khu vực đó để có thể mở khóa cửa và bước vào phòng tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"------- (137).\", \"vi\": \"------- (137).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [137]}, {\"en\": \"Crystal plans to install escape rooms in its main production facilities outside of Europe ------- (138).\", \"vi\": \"Crystal có kế hoạch lắp đặt các phòng thoát hiểm tại các cơ sở sản xuất chính của mình bên ngoài châu Âu ------- (138).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [138]}]' WHERE `id` = 'a424c278-54b1-4c30-b484-fb47600e7fa8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"(18 April)—MKZ Foods, Inc., the region\'s largest exporter of pecans, expects its outgoing shipments to increase significantly over the next few months.\", \"vi\": \"(18 tháng 4)—MKZ Foods, Inc., nhà xuất khẩu quả hồ đào lớn nhất khu vực, kỳ vọng các lô hàng xuất khẩu của họ sẽ tăng lên đáng kể trong vài tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"This ______[143] is based on the fact that the region\'s pecan farmers expanded their land area by 20 percent last year.\", \"vi\": \"Điều này ______[143] dựa trên thực tế là các nông dân trồng quả hồ đào trong khu vực đã mở rộng diện tích đất của họ thêm 20 phần trăm vào năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [143]}, {\"en\": \"According to spokesperson Katharina Seiler, MKZ\'s exports could reach a colossal 50,000 metric tons this year.\", \"vi\": \"Theo phát ngôn viên Katharina Seiler, xuất khẩu của MKZ có thể đạt mức khổng lồ 50.000 tấn mét trong năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"______[144].\", \"vi\": \"______[144].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [144]}, {\"en\": \"MKZ buys most of the yield from the region\'s pecan farms and processes it ______[145] export throughout the world.\", \"vi\": \"MKZ mua phần lớn sản lượng từ các trang trại trồng quả hồ đào trong khu vực và chế biến nó ______[145] để xuất khẩu đi khắp thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [145]}, {\"en\": \"\\\"The availability of new land for ______[146] in the region is creating opportunities for growth,\\\" said Ms. Seiler.\", \"vi\": \"\\\"Sự sẵn có của đất mới cho ______[146] trong khu vực đang tạo ra các cơ hội tăng trưởng,\\\" bà Seiler cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [146]}, {\"en\": \"\\\"I believe MKZ is going to have a truly outstanding year.\\\"\", \"vi\": \"\\\"Tôi tin rằng MKZ sẽ có một năm thực sự nổi bật.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = 'a469095d-fa3d-421f-b083-06a79ada3349';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Riverdale Bike Safety Day\", \"vi\": \"Ngày An toàn khi đi xe đạp tại Riverdale\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Do you want to make sure your bicycle is safe to ride on the roads and trails?\", \"vi\": \"Quý vị có muốn đảm bảo rằng chiếc xe đạp của mình đủ an toàn để lưu thông trên đường phố và các con đường mòn không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Then don\'t miss Riverdale Bike Safety Day at Sunrise Park on July 20 from 10 A.M. to 4 P.M.\", \"vi\": \"Vậy thì đừng bỏ lỡ Ngày An toàn Khi Đi Xe Đạp Riverdale tại Công viên Sunrise vào ngày 20 tháng 7, từ 10 giờ sáng đến 4 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Certified bicycle repair technicians will be on site to check your bicycle at no cost to you.\", \"vi\": \"Các kỹ thuật viên sửa chữa xe đạp được chứng nhận sẽ có mặt tại chỗ để kiểm tra xe đạp của quý vị hoàn toàn miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"They can perform basic maintenance and repairs such as fixing or replacing chains, adjusting seat heights, patching and filling flat tires, and checking brake cables.\", \"vi\": \"Họ có thể thực hiện các công việc bảo dưỡng và sửa chữa cơ bản như sửa chữa hoặc thay thế xích, điều chỉnh độ cao yên xe, vá và bơm lốp bị xẹp, cũng như kiểm tra dây phanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To save time, you can book a time slot in advance at Tony\'s Bike Shop.\", \"vi\": \"Để tiết kiệm thời gian, quý vị có thể đặt trước khung giờ tại Cửa hàng Xe đạp Tony.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Riverdale Bike Safety Day is made possible by the Meadowland Grant and sponsorship from Tony\'s Bike Shop.\", \"vi\": \"Ngày An toàn khi đi xe đạp tại Riverdale được tổ chức nhờ Quỹ Meadowland và sự tài trợ từ Cửa hàng xe đạp Tony\'s.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"For more information, visit www.riverdalecommunity.org/bikesafety.\", \"vi\": \"Để biết thêm thông tin, vui lòng truy cập www.riverdalecommunity.org/bikesafety.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = 'a46e148a-368d-49ee-b42c-3d40ec1e82ae';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"https://www.heredia.com/appliances/cooktops/ec7030a\", \"vi\": \"https://www.heredia.com/appliances/cooktops/ec7030a\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Heredia Bright 30-inch Electric Cooktop (EC7030A)\", \"vi\": \"Bếp điện Heredia Bright 30 inch (EC7030A)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This cooktop offers cutting-edge convenience and precision.\", \"vi\": \"Bếp từ này mang đến sự tiện lợi và độ chính xác vượt trội.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Its four burners can be monitored and adjusted from your smartphone with the Heredia Bright app.\", \"vi\": \"Quý vị có thể theo dõi và điều chỉnh bốn đầu đốt của bếp này từ điện thoại thông minh của mình thông qua ứng dụng Heredia Bright.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Each burner can also be set to an exact degree temperature, making it easy to cook delicate dishes like sauces and candy.\", \"vi\": \"Mỗi đầu đốt cũng có thể được điều chỉnh đến nhiệt độ chính xác đến từng độ, giúp quý vị dễ dàng chế biến các món ăn đòi hỏi sự tinh tế như nước sốt và kẹo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Features:\", \"vi\": \"Các tính năng:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Completely smooth glass surface enables easy cleaning\", \"vi\": \"Bề mặt kính hoàn toàn nhẵn giúp việc vệ sinh trở nên dễ dàng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Includes one extra-powerful 3100-watt burner for quick boiling\", \"vi\": \"Đi kèm một đầu đốt cực mạnh 3100 watt giúp nước sôi nhanh chóng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Syncs wirelessly with Bright kitchen hoods; hood fan and lights automatically turn on when cooktop does\", \"vi\": \"Kết nối không dây với các loại máy hút mùi Bright; quạt và đèn của máy hút mùi sẽ tự động bật khi bếp từ được bật\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Hot surface indicator light and locking function ensure safety\", \"vi\": \"Đèn báo bề mặt nóng và chức năng khóa đảm bảo an toàn\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Model EC7030A is eligible for financing through the Tally payment platform.\", \"vi\": \"Mẫu EC7030A đủ điều kiện để được hỗ trợ tài chính thông qua nền tảng thanh toán Tally.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Click here to sign up for Tally before making your purchase.\", \"vi\": \"Vui lòng nhấp vào đây để đăng ký sử dụng Tally trước khi tiến hành mua hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Heredia\", \"vi\": \"Kế thừa\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Spring into Innovation Special\", \"vi\": \"Chương trình Đặc biệt “Bước vào mùa xuân của sự đổi mới”\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Let innovation bloom in your kitchen!\", \"vi\": \"Hãy để sự sáng tạo nở rộ trong căn bếp của quý vị!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"This spring, earn a generous rebate by purchasing at least three kitchen appliances from among Heredia\'s Bright line of smart home electronics.\", \"vi\": \"Vào mùa xuân này, quý khách sẽ nhận được khoản hoàn tiền hấp dẫn khi mua ít nhất ba thiết bị nhà bếp thuộc dòng sản phẩm điện tử thông minh Bright của Heredia.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The more you buy, the more you get back!\", \"vi\": \"Quý vị mua càng nhiều, quý vị càng được hoàn lại nhiều hơn!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"◇ Three appliances: $300\", \"vi\": \"◇ Ba thiết bị gia dụng: 300 đô la\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"◇ Four appliances: $550\", \"vi\": \"◇ Bốn thiết bị gia dụng: 550 đô la\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"◇ Five appliances: $800\", \"vi\": \"◇ Năm thiết bị gia dụng: 800 đô la\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"◇ Six or more appliances: $1,050\", \"vi\": \"◇ Sáu thiết bị trở lên: 1.050 đô la\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"All purchases must be made between April 1 and May 31 from our online store or an authorized retailer of Heredia appliances.\", \"vi\": \"Tất cả các giao dịch mua hàng phải được thực hiện trong khoảng thời gian từ ngày 1 tháng 4 đến ngày 31 tháng 5 tại cửa hàng trực tuyến của chúng tôi hoặc tại các đại lý ủy quyền của thương hiệu thiết bị gia dụng Heredia.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Visit www.heredia.com/promotions/siis to apply for the rebate online or print out a claim form that can be mailed in.\", \"vi\": \"Vui lòng truy cập www.heredia.com/promotions/siis để đăng ký nhận khoản hoàn tiền trực tuyến hoặc in mẫu đơn yêu cầu hoàn tiền để gửi qua đường bưu điện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Items - Quantity - Installation Required?\", \"vi\": \"Sản phẩm - Số lượng - Có cần lắp đặt không?\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Bright Ultra Fresh Dishwasher (DW7550S) - 1 - ✔\", \"vi\": \"Máy rửa chén Bright Ultra Fresh (DW7550S) - 1 - ✔\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Bright 30-inch Electric Cooktop (EC7030A) - 1 - ✔\", \"vi\": \"Bếp điện Bright 30 inch (EC7030A) - 1 - ✔\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Bright 28-cubic-feet Four-door Refrigerator (RF78233H) - 1 - ✔\", \"vi\": \"Tủ lạnh bốn cửa Bright dung tích 28 feet khối (RF78233H) - 1 - ✔\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Bright 1.1-cubic-feet Countertop Microwave Oven (MO74403M) - 1\", \"vi\": \"Lò vi sóng để bàn Bright dung tích 1,1 feet khối (MO74403M) - 1\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Heredia\", \"vi\": \"Kế thừa\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"www.heredia.com\", \"vi\": \"www.heredia.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"1-800-555-0164\", \"vi\": \"1-800-555-0164\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"DELIVERY CONFIRMATION\", \"vi\": \"XÁC NHẬN GIAO HÀNG\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Order No.: 56403\", \"vi\": \"Số đơn đặt hàng: 56403\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Order Date: April 9\", \"vi\": \"Ngày đặt hàng: 9 tháng 4\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Customer: Clark Eubanks, 710 Henry Drive, Shannett, RI 02809\", \"vi\": \"Khách hàng: Clark Eubanks, 710 Henry Drive, Shannett, RI 02809\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Delivery Date: April 18\", \"vi\": \"Ngày giao hàng: 18 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"The above items were delivered in good condition, and any required installations were performed satisfactorily.\", \"vi\": \"Các mặt hàng nêu trên đã được giao trong tình trạng tốt, và mọi công việc lắp đặt cần thiết đều đã được thực hiện một cách thỏa đáng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Clark Eubanks\", \"vi\": \"Clark Eubanks\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"(Signature of Customer or Designated Recipient)\", \"vi\": \"(Chữ ký của Quý khách hàng hoặc Người nhận được chỉ định)\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}]' WHERE `id` = 'a46f20f1-b01b-4b42-9b2c-2ef126ddde76';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"December 1\", \"vi\": \"Ngày 1 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Attention, All Employees:\", \"vi\": \"Kính gửi toàn thể nhân viên:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Beginning on January 1, Barkley-Stephens Corporation (BSC) will transition to a security system that uses integrated ID badges.\", \"vi\": \"Kể từ ngày 1 tháng 1, Công ty Barkley-Stephens (BSC) sẽ chuyển sang sử dụng hệ thống an ninh dựa trên thẻ nhận dạng tích hợp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Until now, BSC employees have used traditional identification cards that security personnel checked at entrances to the building.\", \"vi\": \"Cho đến nay, các nhân viên của BSC vẫn sử dụng thẻ nhận dạng truyền thống mà nhân viên an ninh kiểm tra tại các lối vào tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"They simply compared the badge photograph with the employee\'s appearance.\", \"vi\": \"Họ chỉ đơn giản là so sánh ảnh trên thẻ nhân viên với ngoại hình của người đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The new system will be more technologically advanced, integrating ID badge information with various access points around our facility.\", \"vi\": \"Hệ thống mới sẽ tiên tiến hơn về mặt công nghệ, tích hợp thông tin thẻ nhận dạng với các điểm kiểm soát ra vào khác nhau trong khuôn viên cơ sở của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Integrated ID badges allow employees entry only to areas of the building that are permitted to them.\", \"vi\": \"Thẻ nhận dạng tích hợp chỉ cho phép nhân viên ra vào những khu vực trong tòa nhà mà họ được phép tiếp cận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Moreover, the badges create an electronic record of who has entered which areas of the building and when.\", \"vi\": \"Hơn nữa, các thẻ này tạo ra một bản ghi điện tử về việc ai đã vào những khu vực nào của tòa nhà và vào thời điểm nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In the case of temporary employees, badges will be disabled when their tenure ends.\", \"vi\": \"Đối với nhân viên tạm thời, thẻ nhận diện sẽ bị vô hiệu hóa khi thời hạn làm việc của họ kết thúc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"New photographs of all staff will be taken in mid-December, when everyone will be asked to fill out a brief form to complete badge processing.\", \"vi\": \"Vào giữa tháng 12, toàn thể nhân viên sẽ được chụp ảnh mới; khi đó, mọi người sẽ được yêu cầu điền vào một mẫu đơn ngắn để hoàn tất thủ tục cấp thẻ nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = 'a478f18a-b0ed-4987-8158-be2ff2dc7c78';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Ferrese Hotel Employees\", \"vi\": \"Đến: Tất cả nhân viên Khách sạn Ferrese\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Sergio Prieto, Hotel Manager\", \"vi\": \"Từ: Sergio Prieto, Quản lý Khách sạn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: Monday, July 4\", \"vi\": \"Ngày: Thứ Hai, ngày 4 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Global Shipping Partners Conference\", \"vi\": \"Chủ đề: Hội nghị Đối tác Vận chuyển Toàn cầu\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The Ferrese Hotel will be hosting the Global Shipping Partners Conference next week, from Tuesday to Sunday.\", \"vi\": \"Khách sạn Ferrese sẽ đăng cai tổ chức Hội nghị Đối tác Vận chuyển Toàn cầu vào tuần tới, từ thứ Ba đến Chủ Nhật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"___139___, management expects to see many more customers in the hotel\'s restaurants and gift shops.\", \"vi\": \"___139___, ban quản lý dự kiến sẽ đón tiếp nhiều khách hàng hơn nữa tại các nhà hàng và cửa hàng lưu niệm của khách sạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [139]}, {\"en\": \"___140___.\", \"vi\": \"___140___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [140]}, {\"en\": \"I will be hiring temporary staff to ensure that ___141___ can meet these increased demands.\", \"vi\": \"Tôi sẽ thuê nhân viên thời vụ để đảm bảo rằng ___141___ có thể đáp ứng những nhu cầu gia tăng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [141]}, {\"en\": \"Please take the time to help them learn our ___142___ when they are here.\", \"vi\": \"Xin hãy dành thời gian giúp họ làm quen với ___142___ của chúng ta khi họ làm việc ở đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [142]}, {\"en\": \"Doing so will ensure that all operations run smoothly while the conference is taking place.\", \"vi\": \"Làm như vậy sẽ đảm bảo rằng mọi hoạt động diễn ra suôn sẻ trong suốt thời gian diễn ra hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = 'a4885287-e447-4513-a876-cb5aa14c0424';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ariana Jones (1:18 P.M.)\", \"vi\": \"Ariana Jones (1 giờ 18 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Renalto and Janice.\", \"vi\": \"Xin chào, Renalto và Janice.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"How are things coming along with those blogs I asked you to start?\", \"vi\": \"Việc viết những bài blog mà tôi đã nhờ quý vị bắt đầu tiến triển thế nào rồi?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Janice Canto (1:20 P.M.)\", \"vi\": \"Janice Canto (1 giờ 20 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I am thinking of profiling the members of our team of investment advisors.\", \"vi\": \"Tôi đang cân nhắc việc giới thiệu sơ lược về các thành viên trong đội ngũ cố vấn đầu tư của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Ariana Jones (1:22 P.M.)\", \"vi\": \"Ariana Jones (1 giờ 22 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Could you give me more details on that?\", \"vi\": \"Xin quý vị có thể cung cấp thêm thông tin chi tiết về vấn đề đó được không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Janice Canto (1:24 P.M.)\", \"vi\": \"Janice Canto (1 giờ 24 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Well, I want to feature an interview with a different team member every month.\", \"vi\": \"Vâng, tôi muốn giới thiệu một bài phỏng vấn với một thành viên khác trong nhóm mỗi tháng.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I could get a little personal and professional background information, and inquire about the member\'s views on investment strategies, that sort of thing.\", \"vi\": \"Tôi có thể tìm hiểu một chút về thông tin cá nhân và lý lịch nghề nghiệp của thành viên, đồng thời hỏi ý kiến của họ về các chiến lược đầu tư, những vấn đề như vậy.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Ariana Jones (1:25 P.M.)\", \"vi\": \"Ariana Jones (1 giờ 25 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Nice.\", \"vi\": \"Tốt lắm.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Our customers would really like that.\", \"vi\": \"Khách hàng của chúng tôi chắc chắn sẽ rất thích điều đó.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"What about you, Renalto?\", \"vi\": \"Còn anh thì sao, Renalto?\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Renalto Pereira (1:27 P.M.)\", \"vi\": \"Renalto Pereira (1 giờ 27 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"I\'m thinking of reporting on emerging stock market trends.\", \"vi\": \"Tôi đang cân nhắc việc viết bài phân tích về các xu hướng mới nổi trên thị trường chứng khoán.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I\'ve already collected a lot of material about this topic.\", \"vi\": \"Tôi đã thu thập được rất nhiều tài liệu về chủ đề này.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Janice Canto (1:27 P.M.)\", \"vi\": \"Janice Canto (1 giờ 27 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Sorry, I have to leave for a meeting in about five minutes.\", \"vi\": \"Xin lỗi, khoảng năm phút nữa tôi phải đi dự một cuộc họp.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Ariana Jones (1:28 P.M.)\", \"vi\": \"Ariana Jones (1 giờ 28 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 7, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Sounds interesting.\", \"vi\": \"Nghe có vẻ thú vị.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Do you need assistance with the research?\", \"vi\": \"Quý vị có cần sự hỗ trợ trong quá trình nghiên cứu không?\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Renalto Pereira (1:29 P.M.)\", \"vi\": \"Renalto Pereira (1 giờ 29 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 8, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Thanks, but I think I\'ve got it covered.\", \"vi\": \"Cảm ơn, nhưng tôi nghĩ là tôi đã lo liệu được rồi.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Ariana Jones (1:30 P.M.)\", \"vi\": \"Ariana Jones (1 giờ 30 phút chiều)\", \"type\": \"metadata\", \"doc_index\": 9, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"OK, I\'d like both of you to get back to me by Monday with your progress on these ideas.\", \"vi\": \"Được rồi, tôi mong hai vị sẽ báo cáo lại cho tôi trước thứ Hai về tiến độ thực hiện các ý tưởng này.\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = 'a50babdc-24d3-4d2f-840a-ec0b8bf6d202';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Laura Gonzales <lauragonzales@fig-mail.com>\", \"vi\": \"Gửi tới: Laura Gonzales <lauragonzales@fig-mail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Roy Chastain <rchastain@burgess.edu>\", \"vi\": \"Từ: Roy Chastain <rchastain@burgess.edu>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 18\", \"vi\": \"Ngày: 18 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Re: Invitation\", \"vi\": \"Chủ đề: Trả lời: Thư mời\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Gonzales,\", \"vi\": \"Kính gửi bà Gonzales,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The Diversity, Equity & Inclusion Committee is delighted that you have accepted our invitation to join other Burgess alumni next month to discuss your career experiences as a first-generation university graduate.\", \"vi\": \"Ủy ban Đa dạng, Công bằng và Hòa nhập rất vui mừng khi quý vị đã nhận lời mời của chúng tôi để cùng các cựu sinh viên Burgess khác vào tháng tới, nhằm chia sẻ những trải nghiệm nghề nghiệp của quý vị với tư cách là một sinh viên đại học thế hệ đầu tiên trong gia đình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As many of Burgess University\'s current first-generation students are education majors, we expect that they will be eager to hear your perspective as someone already working in the classroom.\", \"vi\": \"Vì nhiều sinh viên thế hệ đầu tiên hiện đang theo học tại Đại học Burgess đều theo chuyên ngành sư phạm, chúng tôi kỳ vọng rằng các em sẽ rất háo hức được lắng nghe quan điểm của quý vị với tư cách là người đã và đang công tác trực tiếp trong môi trường giảng dạy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We hope you will be able to stay for the catered reception after the discussion, as well, so that you have a chance to mingle with the students.\", \"vi\": \"Chúng tôi hy vọng quý vị cũng có thể ở lại tham dự tiệc chiêu đãi được chuẩn bị sẵn sau buổi thảo luận, để quý vị có cơ hội giao lưu với các sinh viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Regarding your question, we will not be able to reimburse you for transportation, unfortunately.\", \"vi\": \"Về câu hỏi của quý vị, rất tiếc là chúng tôi không thể hoàn trả chi phí đi lại cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The free campus shuttle bus to and from Burgess University Subway Station runs quite frequently now, so I recommend using that.\", \"vi\": \"Hiện nay, xe buýt đưa đón miễn phí trong khuôn viên trường đi và về từ Ga tàu điện ngầm Burgess University chạy khá thường xuyên, vì vậy tôi khuyên quý vị nên sử dụng phương tiện này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"As you can see from the attachment, the Sikes Building, our venue, is just across the street from the Central Library.\", \"vi\": \"Như quý vị có thể thấy trong tệp đính kèm, Tòa nhà Sikes – địa điểm tổ chức sự kiện của chúng tôi – nằm ngay bên kia đường so với Thư viện Trung tâm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please arrive there by 4:30 P.M. to allow ample time for preparations before the event begins at 5:00 P.M.\", \"vi\": \"Kính mong quý vị có mặt tại đó trước 4 giờ 30 chiều để có đủ thời gian chuẩn bị trước khi sự kiện bắt đầu vào lúc 5 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Roy Chastain\", \"vi\": \"Roy Chastain\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Burgess University Subway Station - North Gate - Central Library - College of Medicine - Shaw Dormitory\", \"vi\": \"Ga tàu điện ngầm Đại học Burgess - Cổng Bắc - Thư viện Trung tâm - Khoa Y - Ký túc xá Shaw\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"4:00 P.M. - 4:15 P.M. - 4:21 P.M. - 4:25 P.M. - 4:28 P.M.\", \"vi\": \"16 giờ 00 - 16 giờ 15 - 16 giờ 21 - 16 giờ 25 - 16 giờ 28\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"4:15 P.M. - 4:30 P.M. - 4:36 P.M. - 4:40 P.M. - 4:43 P.M.\", \"vi\": \"16 giờ 15 phút - 16 giờ 30 phút - 16 giờ 36 phút - 16 giờ 40 phút - 16 giờ 43 phút\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"4:30 P.M. - 4:45 P.M. - 4:51 P.M. - 4:55 P.M. - 4:58 P.M.\", \"vi\": \"16 giờ 30 - 16 giờ 45 - 16 giờ 51 - 16 giờ 55 - 16 giờ 58\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"4:45 P.M. - 5:00 P.M. - 5:06 P.M. - 5:10 P.M. - 5:13 P.M.\", \"vi\": \"16 giờ 45 phút - 17 giờ 00 phút - 17 giờ 06 phút - 17 giờ 10 phút - 17 giờ 13 phút\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Burgess University Campus Shuttle Bus\", \"vi\": \"Xe buýt đưa đón trong khuôn viên Đại học Burgess\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Direction: Burgess University Subway Station → Campus\", \"vi\": \"Hướng đi: Ga tàu điện ngầm Burgess University → Khuôn viên trường\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Stops and Departure Times\", \"vi\": \"Các điểm dừng và thời gian khởi hành\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"*Shuttle buses run less frequently during the summer and winter.\", \"vi\": \"*Tần suất chạy của các chuyến xe buýt đưa đón sẽ giảm trong mùa hè và mùa đông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Visit www.burgess.edu/campus/shuttle or download the iBurgess app for up-to-date schedules as well as information about service disruptions.\", \"vi\": \"Quý vị vui lòng truy cập www.burgess.edu/campus/shuttle hoặc tải xuống ứng dụng iBurgess để xem lịch trình cập nhật cũng như thông tin về các sự cố gián đoạn dịch vụ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}]' WHERE `id` = 'a522237a-976a-4144-a6ec-6bca0941ceb9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Cardinal Street Project-Update\", \"vi\": \"Dự án Đường Cardinal – Cập nhật\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Because of unusually wet and cold weather conditions, the road closure on Cardinal Street between Lee Drive and Petunia Lane will be extended until late spring.\", \"vi\": \"Do điều kiện thời tiết ẩm ướt và lạnh bất thường, việc đóng cửa đoạn đường trên phố Cardinal, nằm giữa đường Lee Drive và ngõ Petunia Lane, sẽ được gia hạn đến cuối mùa xuân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Construction will continue; however, final paving on Cardinal Street cannot occur until the weather conditions improve.\", \"vi\": \"Công trình sẽ tiếp tục được triển khai; tuy nhiên, việc trải lớp thảm cuối cùng trên đường Cardinal sẽ không thể tiến hành cho đến khi điều kiện thời tiết được cải thiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Workers will begin the pavement work once construction of the bridge on Cardinal Street has been completed.\", \"vi\": \"Các công nhân sẽ bắt đầu thi công mặt đường ngay sau khi việc xây dựng cây cầu trên đường Cardinal hoàn tất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"If you have questions or comments, please contact Vy Nguyen in the city planning office at 615-555-0184.\", \"vi\": \"Nếu quý vị có thắc mắc hoặc ý kiến đóng góp, xin vui lòng liên hệ với bà Vy Nguyễn tại Văn phòng Quy hoạch Đô thị theo số điện thoại 615-555-0184.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}]' WHERE `id` = 'a53e36ba-47bd-428b-bf7b-38abe871ac57';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Structure: Blaine River Drawbridge - Location: Ridgeline Highway, KM 147\", \"vi\": \"Cấu trúc: Cầu kéo trên sông Blaine - Vị trí: Đường cao tốc Ridgeline, km 147\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Main span material: Steel girder - Owner: State Highway Agency\", \"vi\": \"Vật liệu nhịp chính: Dầm thép - Chủ đầu tư: Cục Quản lý Đường bộ Nhà nước\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Age of structure: 30 years - Report completed by: Vivian Tulio\", \"vi\": \"Tuổi thọ của công trình: 30 năm - Báo cáo do bà Vivian Tulio thực hiện\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: October 17\", \"vi\": \"Ngày: 17 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Notes:\\nThe bridge is overall structurally sound. Inform Department of Transportation about small cracks in asphalt.\", \"vi\": \"Ghi chú:\\nNhìn chung, kết cấu của cây cầu vẫn vững chắc. Vui lòng thông báo cho Sở Giao thông Vận tải về các vết nứt nhỏ trên mặt đường nhựa.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Bridge component - Rating - Key to ratings\", \"vi\": \"Thành phần cầu - Hệ thống xếp hạng - Bảng giải thích các mức xếp hạng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Support elements - 4 - 1 Failed; immediate closure required\\n2 Deteriorated; may fail soon\\n3 Shows deterioration but still functions within acceptable parameters\\n4 Shows minor wear\\n5 New condition\\n6 Not applicable\", \"vi\": \"Các bộ phận chịu lực - 4 - 1: Hỏng hóc; cần phải ngừng hoạt động ngay lập tức\\n2: Bị hư hỏng; có thể hỏng hóc trong thời gian ngắn\\n3: Có dấu hiệu hư hỏng nhưng vẫn hoạt động trong phạm vi cho phép\\n4: Có dấu hiệu mòn nhẹ\\n5: Tình trạng như mới\\n6: Không áp dụng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Towers - 4\", \"vi\": \"Tháp - 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Road surface - 3\", \"vi\": \"Mặt đường - 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Drainage features - 4\", \"vi\": \"Các hệ thống thoát nước - 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Safety barriers - 5\", \"vi\": \"Hàng rào an toàn - 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Sidewalk or walkway - 6\", \"vi\": \"Vỉa hè hoặc lối đi bộ - 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = 'a549a8af-42f6-4ba4-b7db-0cdd28ef0e1d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: rwiest@lupinecityhall.com\", \"vi\": \"Gửi tới: rwiest@lupinecityhall.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: dbryant@arcospartners.com\", \"vi\": \"Từ: dbryant@arcospartners.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: April 12\", \"vi\": \"Ngày: 12 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Site Survey\", \"vi\": \"Chủ đề: Khảo sát hiện trường\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Survey\", \"vi\": \"Tệp đính kèm: 📎 Bản khảo sát\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Wiest,\", \"vi\": \"Kính gửi ông Wiest,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I e-mailed you the site survey document on Monday, so it\'s strange that you didn\'t see it.\", \"vi\": \"Tôi đã gửi cho quý vị bản báo cáo khảo sát hiện trường qua email vào thứ Hai, nên thật lạ là quý vị lại không nhận được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Perhaps because I sent it from my personal e-mail rather than my work e-mail, your server didn\'t recognize it and routed it to your junk-mail folder instead.\", \"vi\": \"Có lẽ do tôi đã gửi email từ địa chỉ email cá nhân thay vì địa chỉ email công việc, nên máy chủ của quý vị đã không nhận diện được và chuyển email đó vào thư mục thư rác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In any case, I will reattach the document here.\", \"vi\": \"Dù sao đi nữa, tôi sẽ đính kèm lại tài liệu tại đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"If the site is approved by next week, my team will expedite the completion of the final blueprints.\", \"vi\": \"Nếu địa điểm này được phê duyệt vào tuần tới, nhóm của tôi sẽ khẩn trương hoàn tất các bản vẽ thiết kế cuối cùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The property owner hopes to have the full building project approved before the end of the month so that the construction team can start laying the foundation in June.\", \"vi\": \"Chủ sở hữu bất động sản hy vọng dự án xây dựng sẽ được phê duyệt toàn bộ trước cuối tháng này để đội thi công có thể bắt đầu đổ móng vào tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Daniela Bryant\", \"vi\": \"Daniela Bryant\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = 'a587f6e2-9f65-4208-bd38-524b1183a5ad';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Quester Expands Marketplace\", \"vi\": \"Quester mở rộng nền tảng thương mại điện tử\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"DUBLIN (23 July)—Quester Ltd., the company that operates the groundbreaking Quester Web site for job seekers and employers, has announced that it will now include technology-related occupations in its marketplace.\", \"vi\": \"DUBLIN (ngày 23 tháng 7) — Quester Ltd., công ty vận hành trang web Quester tiên phong dành cho người tìm việc và nhà tuyển dụng, đã thông báo rằng họ sẽ chính thức đưa các ngành nghề liên quan đến công nghệ vào nền tảng kết nối việc làm của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Since its launch more than five years ago, Quester has focused solely on staffing for organisations in the health-care sector.\", \"vi\": \"Kể từ khi ra mắt cách đây hơn năm năm, Quester đã tập trung hoàn toàn vào việc cung ứng nhân sự cho các tổ chức trong lĩnh vực chăm sóc sức khỏe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Like health care, the technology sector is also struggling to find employees who have the right skills and who can help meet the demands created by high growth.\", \"vi\": \"Cũng giống như lĩnh vực chăm sóc sức khỏe, ngành công nghệ hiện cũng đang gặp khó khăn trong việc tìm kiếm những nhân viên có kỹ năng phù hợp và có thể góp phần đáp ứng nhu cầu phát sinh từ tốc độ tăng trưởng cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"The employment rate of technology professionals is already quite high, yet jobs in the industry are projected to grow significantly each year over the next decade,\\\" said Ladli Misra, a founding partner of Quester.\", \"vi\": \"\\\"Tỷ lệ việc làm của các chuyên gia công nghệ hiện đã ở mức khá cao, song số lượng việc làm trong ngành này được dự báo sẽ tăng trưởng đáng kể mỗi năm trong thập kỷ tới,\\\" ông Ladli Misra, một trong những đối tác sáng lập của Quester, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Quester works by bringing job seekers together with recruiters and hiring managers.\", \"vi\": \"Quester hoạt động bằng cách kết nối những người tìm việc với các nhà tuyển dụng và quản lý tuyển dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"When companies contract with Quester, job listings are created with details of the companies\' open positions.\", \"vi\": \"Khi các công ty ký hợp đồng với Quester, các thông báo tuyển dụng sẽ được tạo ra kèm theo thông tin chi tiết về các vị trí đang tuyển dụng của các công ty đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Job seekers create a skill-set profile and identify opportunities of interest to them.\", \"vi\": \"Người tìm việc lập hồ sơ về bộ kỹ năng của mình và xác định các cơ hội mà họ quan tâm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Candidates and employers interact, seeking links and bridges between skills and jobs listed on the Quester site.\", \"vi\": \"Ứng viên và nhà tuyển dụng tương tác với nhau, nhằm tìm kiếm sự kết nối và cầu nối giữa các kỹ năng và các vị trí việc làm được đăng tải trên trang web Quester.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Quester\'s proprietary algorithm matches employers and job seekers and then notifies both.\", \"vi\": \"Thuật toán độc quyền của Quester sẽ kết nối các nhà tuyển dụng với người tìm việc, sau đó gửi thông báo đến cả hai bên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Using a simple messaging-and-scheduling tool, job seekers can indicate their interest in a job opening and employers can send interview requests.\", \"vi\": \"Bằng cách sử dụng một công cụ nhắn tin và lên lịch đơn giản, người tìm việc có thể bày tỏ sự quan tâm của mình đối với một vị trí tuyển dụng, đồng thời nhà tuyển dụng có thể gửi lời mời phỏng vấn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Employers are assigned a personal guide to walk them through the process and to ensure the maximum benefit from the experience.\", \"vi\": \"Mỗi nhà tuyển dụng sẽ được chỉ định một hướng dẫn viên riêng để hỗ trợ họ trong suốt quá trình này và đảm bảo họ thu được lợi ích tối đa từ trải nghiệm này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"There is no cost to job seekers.\", \"vi\": \"Người tìm việc không phải chịu bất kỳ chi phí nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"\\\"It\'s great for both ends of the employment market,\\\" said Ms. Misra.\", \"vi\": \"\\\"Điều này mang lại lợi ích cho cả hai phía trên thị trường lao động,\\\" bà Misra phát biểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"\\\"Job seekers can easily find the most appropriate opportunities and employers get the information they need to efficiently acquire in-demand talent, usually in less than a month.\\\"\", \"vi\": \"\\\"Những người tìm việc có thể dễ dàng tìm thấy những cơ hội phù hợp nhất, còn các nhà tuyển dụng cũng có được thông tin cần thiết để thu hút hiệu quả những nhân tài đang được thị trường lao động săn đón, thường chỉ trong vòng chưa đầy một tháng.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = 'a6720d8c-baa8-46a2-9cec-cc4393be9549';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Owner\\nWalker Booksellers\\n4634 Goosetown Drive\\nArden, NC - General Contractor\\nMatthiesen Builders\\n4500 Smith Street\\nRaleigh, NC\", \"vi\": \"Chủ sở hữu\\nWalker Booksellers\\n4634 Goosetown Drive\\nArden, NC - Nhà thầu chính\\nMatthiesen Builders\\n4500 Smith Street\\nRaleigh, NC\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"WHAT\'S GOING ON HERE?\", \"vi\": \"CHUYỆN GÌ ĐANG XẢY RA Ở ĐÂY VẬY?\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Work in progress: Commercial\", \"vi\": \"Dự án đang triển khai: Thương mại\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Anticipated completion date: March 1\", \"vi\": \"Ngày dự kiến hoàn thành: 1 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"All work permits are on file with the Department of Planning.\", \"vi\": \"Tất cả các giấy phép xây dựng đều đã được lưu trữ tại Sở Kế hoạch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"To report a problem at this work site, call 919-555-0134.\", \"vi\": \"Để báo cáo sự cố tại công trường này, xin vui lòng gọi số 919-555-0134.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = 'a67adc95-408e-4923-97a6-dc6f1e7e521e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Submission Policy\", \"vi\": \"Chính sách gửi bài\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Undeniable is an ad-supported literary journal of short fiction and nonfiction by emerging writers.\", \"vi\": \"“Undeniable” là một tạp chí văn học chuyên đăng tải các tác phẩm truyện ngắn và phi hư cấu của các tác giả trẻ, được tài trợ bởi quảng cáo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We waive our $5 fee for first-time submitters.\", \"vi\": \"Chúng tôi miễn khoản phí 5 đô la cho những người gửi bài lần đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"• Stories must be between 250 and 1,000 words (no poetry, please).\", \"vi\": \"• Các truyện ngắn phải có độ dài từ 250 đến 1.000 từ (xin vui lòng không gửi thơ).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"• Do not include illustrations.\", \"vi\": \"• Xin vui lòng không đính kèm hình minh họa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"All illustrations are produced in-house.\", \"vi\": \"Tất cả các hình minh họa đều do chính công ty thực hiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"• Attach your story in an e-mail to: submissions@undeniable.com.\", \"vi\": \"• Vui lòng đính kèm câu chuyện của quý vị vào email và gửi đến địa chỉ: submissions@undeniable.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please include a brief synopsis of your piece, and tell us how you discovered Undeniable.\", \"vi\": \"Kính mong quý vị vui lòng đính kèm một bản tóm tắt ngắn gọn về tác phẩm của mình và chia sẻ với chúng tôi về cách quý vị đã biết đến Undeniable.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"• We pay a $50 honorarium upon acceptance for publication.\", \"vi\": \"• Chúng tôi sẽ chi trả khoản thù lao trị giá 50 đô la khi bài viết được chấp nhận đăng tải.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"• If we accept your story, we will send you a contract and a form to set up an electronic money transfer.\", \"vi\": \"• Nếu chúng tôi chấp nhận bài viết của quý vị, chúng tôi sẽ gửi cho quý vị hợp đồng cùng với mẫu đơn để thiết lập chuyển khoản điện tử.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: submissions@undeniable.com\", \"vi\": \"Gửi tới: submissions@undeniable.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From: len.sutherland@onyxmail.com\", \"vi\": \"Nguồn: len.sutherland@onyxmail.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: March 15\", \"vi\": \"Ngày: 15 tháng 3\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Subject: Cover letter and submission\", \"vi\": \"Chủ đề: Thư giới thiệu và hồ sơ dự thi\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Attachment: Ji\'s Journey\", \"vi\": \"Tài liệu đính kèm: Hành trình của Ji\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Greetings!\", \"vi\": \"Xin chào!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"My submission, \\\"Ji’s Journey,\\\" centers on a young dress designer, Toby Ji, who overcomes obstacles to realize her dreams in the fashion industry.\", \"vi\": \"Tác phẩm dự thi của tôi, “Hành trình của Ji”, xoay quanh Toby Ji – một nhà thiết kế thời trang trẻ, người đã vượt qua mọi trở ngại để hiện thực hóa ước mơ của mình trong ngành thời trang.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I was introduced to Undeniable last year by my writing instructor at the Artman Institute in Portland, Oregon, and have since become a subscriber.\", \"vi\": \"Năm ngoái, tôi đã được giảng viên môn viết văn tại Học viện Artman ở Portland, Oregon giới thiệu về tạp chí *Undeniable*, và từ đó đến nay tôi đã trở thành độc giả thường xuyên của tạp chí này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I particularly enjoy your Nonfiction Corner; one of my favorites was \\\"Waygone Beach,\\\" which inspired me to write \\\"Ji’s Journey.\\\"\", \"vi\": \"Tôi đặc biệt thích chuyên mục “Góc Văn học Phi hư cấu” của quý báo; một trong những tác phẩm tôi yêu thích nhất là “Waygone Beach”, tác phẩm này đã truyền cảm hứng cho tôi để viết nên “Hành trình của Ji”.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I believe it would be an ideal fit for this section.\", \"vi\": \"Tôi tin rằng đây sẽ là sự lựa chọn lý tưởng cho phần này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Like \\\"Waygone Beach,\\\" \\\"Ji’s Journey\\\" is a true story of hope and perseverance.\", \"vi\": \"Cũng giống như “Waygone Beach”, “Ji’s Journey” là một câu chuyện có thật về niềm hy vọng và sự kiên trì.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Thank you for your consideration and for creating a forum for new writers like me.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã quan tâm và đã tạo ra một diễn đàn dành cho những nhà văn mới như tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Len Sutherland\", \"vi\": \"Len Sutherland\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"To: len.sutherland@onyxmail.com\", \"vi\": \"Gửi tới: len.sutherland@onyxmail.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"From: jerrybuckman@undeniable.com\", \"vi\": \"Nguồn: jerrybuckman@undeniable.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Date: July 2\", \"vi\": \"Ngày: 2 tháng 7\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Subject: Your submission\", \"vi\": \"Chủ đề: Đơn đăng ký của quý vị\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Dear Mr. Sutherland,\", \"vi\": \"Kính gửi ông Sutherland,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Your story, \\\"Ji’s Journey,\\\" generated a great deal of positive feedback about the June issue.\", \"vi\": \"Truyện của quý vị, “Hành trình của Ji”, đã nhận được rất nhiều phản hồi tích cực trong số báo tháng Sáu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Congratulations!\", \"vi\": \"Xin chúc mừng!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"And your instincts were correct regarding your story’s placement.\", \"vi\": \"Và trực giác của quý vị về việc sắp xếp vị trí cho bài viết của mình là hoàn toàn chính xác.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"All this has us hoping you will submit more stories to Undeniable.\", \"vi\": \"Tất cả những điều này khiến chúng tôi hy vọng quý vị sẽ gửi thêm nhiều bài viết đến Undeniable.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"As an added incentive, we will be increasing our honorarium to $100 beginning next month.\", \"vi\": \"Để tạo thêm động lực, kể từ tháng tới, chúng tôi sẽ tăng mức thù lao lên 100 đô la.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"As a subscriber, you are likely familiar with Stacy Jordan’s question-and-answer column featuring a different writer each month.\", \"vi\": \"Với tư cách là độc giả đăng ký, chắc hẳn quý vị đã quen thuộc với chuyên mục hỏi đáp của Stacy Jordan, nơi mỗi tháng đều giới thiệu một tác giả khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Would you be willing to answer a few questions about your literary training, writing method, and how you find story ideas?\", \"vi\": \"Xin hỏi, quý vị có sẵn lòng trả lời một vài câu hỏi về quá trình đào tạo văn học, phương pháp sáng tác cũng như cách quý vị tìm ra ý tưởng cho các câu chuyện không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"If so, I will forward your e-mail address to Ms. Jordan, who will reach out to you in the near future.\", \"vi\": \"Nếu vậy, tôi sẽ chuyển địa chỉ email của quý vị cho bà Jordan, và bà ấy sẽ liên hệ với quý vị trong thời gian tới.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Jerry Buckman\", \"vi\": \"Jerry Buckman\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Associate Editor\", \"vi\": \"Phó Tổng biên tập\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}]' WHERE `id` = 'a6b25b49-046d-495c-b2b1-0578fe93a8a1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"★★★★☆\\n12 April\\nElena Patterson - My company recently held a banquet at the Calla Courtyard, and it was the perfect venue for our event. Initially, I was hesitant to book the space because it had only recently opened to the public and there were no customer reviews yet. — [1] —. I decided to give it a try anyway.\\nAlthough it was a little expensive, the setting was absolutely stunning. — [2] —. The Calla Courtyard has a magnificent view of the bay. The staff had arranged the seats in the hall so that the guests could view the sunset through the large glass windows.\\nOne thing to note is that while the facility does have a kitchen available for use, it is quite small and not well-stocked. — [3] —.\\nAll in all, I was pleased with my decision and would definitely consider this place again for future events. — [4] —.\", \"vi\": \"★★★★☆\\nNgày 12 tháng 4\\nElena Patterson - Công ty tôi vừa tổ chức một bữa tiệc tại Calla Courtyard, và đây thực sự là địa điểm hoàn hảo cho sự kiện của chúng tôi. Ban đầu, tôi còn do dự khi đặt chỗ vì nơi đây mới chỉ mở cửa đón khách được một thời gian ngắn và chưa có bất kỳ đánh giá nào từ khách hàng. — [1] —. Tuy nhiên, tôi vẫn quyết định thử một lần.\\nMặc dù giá hơi cao, nhưng khung cảnh tại đây thực sự tuyệt đẹp. — [2] —. Calla Courtyard sở hữu tầm nhìn tuyệt đẹp ra vịnh. Đội ngũ nhân viên đã sắp xếp chỗ ngồi trong hội trường sao cho các vị khách có thể ngắm hoàng hôn qua những ô cửa kính lớn.\\nMột điều cần lưu ý là mặc dù cơ sở này có bếp để sử dụng, nhưng bếp khá nhỏ và không được trang bị đầy đủ. — [3] —.\\nNhìn chung, tôi rất hài lòng với quyết định của mình và chắc chắn sẽ cân nhắc lựa chọn địa điểm này một lần nữa cho các sự kiện trong tương lai. — [4] —.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"← → ↻ 🏠 https://www.therightvenue.com.au/customer_reviews ⋮\", \"vi\": \"← → ↻ 🏠 https://www.therightvenue.com.au/customer_reviews ⋮\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Customer Reviews\", \"vi\": \"Đánh giá của khách hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}]' WHERE `id` = 'a6e0cc7f-28ee-4e2b-abfe-010f53a7d84a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Isabelle Porter (8:15 A.M.)\", \"vi\": \"Isabelle Porter (8 giờ 15 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi.\", \"vi\": \"Xin chào\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Our new intern, Mila Erben, arrives tomorrow.\", \"vi\": \"Thực tập sinh mới của chúng tôi, Mila Erben, sẽ đến vào ngày mai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Do you have any tasks for Mila to start on?\", \"vi\": \"Quý vị có nhiệm vụ nào để Mila bắt tay vào thực hiện không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Omar Shirani (8:16 A.M.)\", \"vi\": \"Omar Shirani (8 giờ 16 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I’m really sorry.\", \"vi\": \"Tôi thực sự xin lỗi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I was out of the office last week at the JNTD Convention.\", \"vi\": \"Tuần trước, tôi đã vắng mặt tại văn phòng để tham dự Hội nghị JNTD.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Can I get back to you later today?\", \"vi\": \"Tôi có thể liên hệ lại với quý vị vào cuối ngày hôm nay được không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Rico Alvarez (8:16 A.M.)\", \"vi\": \"Rico Alvarez (8 giờ 16 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I don’t have anything for Mila right now.\", \"vi\": \"Hiện tại tôi chưa có gì dành cho Mila cả.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Isabelle Porter (8:17 A.M.)\", \"vi\": \"Isabelle Porter (8 giờ 17 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I’m confused.\", \"vi\": \"Tôi cảm thấy bối rối.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Your department manager mentioned that your team would greatly benefit from having an intern.\", \"vi\": \"Trưởng phòng của quý vị đã đề cập rằng đội ngũ của quý vị sẽ được hưởng lợi rất nhiều nếu có một thực tập sinh.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Can you work together to find something for her to do?\", \"vi\": \"Các vị có thể cùng nhau tìm ra việc gì đó để cô ấy làm được không?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Omar Shirani (8:17 A.M.)\", \"vi\": \"Omar Shirani (8 giờ 17 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Can you remind us what she’s studying at the university?\", \"vi\": \"Quý vị có thể nhắc lại cho chúng tôi biết cô ấy đang theo học ngành gì tại trường đại học không?\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Isabelle Porter (8:18 A.M.)\", \"vi\": \"Isabelle Porter (8 giờ 18 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Accounting.\", \"vi\": \"Kế toán.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Her résumé says she’d like to become an auditor.\", \"vi\": \"Trong sơ yếu lý lịch của cô ấy có ghi rằng cô ấy mong muốn trở thành một kiểm toán viên.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Rico Alvarez (8:19 A.M.)\", \"vi\": \"Rico Alvarez (8 giờ 19 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Well, I might have a few tasks, although they may be a bit dull.\", \"vi\": \"À, có lẽ tôi sẽ có một vài công việc phải làm, dù chúng có thể hơi nhàm chán.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Isabelle Porter (8:20 A.M.)\", \"vi\": \"Isabelle Porter (8 giờ 20 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 7, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"That will do.\", \"vi\": \"Vậy là được rồi.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"And I might have some documents for her to copy.\", \"vi\": \"Và có lẽ tôi sẽ có một số tài liệu để cô ấy sao chép.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"That ought to be enough for Mila’s first week.\", \"vi\": \"Chắc là như vậy là đủ cho tuần đầu tiên của Mila rồi.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"But I’d appreciate it if you could meet with your team by Thursday and organize additional tasks for Mila for next week.\", \"vi\": \"Tuy nhiên, tôi sẽ rất cảm kích nếu quý vị có thể họp với nhóm của mình trước thứ Năm và phân công thêm các nhiệm vụ cho Mila trong tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = 'a6e35677-96bb-4bfe-b539-b5553f49f56d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Hiking Permits to Be Required for Upton Parks\", \"vi\": \"Sẽ bắt buộc phải có giấy phép đi bộ đường dài tại các công viên ở Upton\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"UPTON (January 8)—Starting on May 25, hikers will be required to obtain a permit for each day they hike on certain trails in Upton parks.\", \"vi\": \"UPTON (ngày 8 tháng 1) — Kể từ ngày 25 tháng 5, những người đi bộ đường dài sẽ phải xin giấy phép cho từng ngày họ đi bộ trên một số con đường mòn nhất định trong các công viên tại Upton.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The designated trails include some of the most popular hiking spots in the area.\", \"vi\": \"Các tuyến đường mòn được chỉ định này bao gồm một số điểm đi bộ đường dài nổi tiếng nhất trong khu vực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The permits are free of charge and require only that hikers register online at www.uptonparks.org or at any Upton Parks Department office.\", \"vi\": \"Các giấy phép này hoàn toàn miễn phí và chỉ yêu cầu những người đi bộ đường dài đăng ký trực tuyến tại địa chỉ www.uptonparks.org hoặc tại bất kỳ văn phòng nào thuộc Sở Công viên Upton.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Upon registering, hikers will receive a permit that they can print out or display on a mobile device.\", \"vi\": \"Sau khi đăng ký, những người đi bộ đường dài sẽ nhận được giấy phép mà quý vị có thể in ra hoặc hiển thị trên thiết bị di động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The move is part of an effort to reduce foot traffic on the most used trails, but some hikers are concerned.\", \"vi\": \"Động thái này là một phần trong nỗ lực nhằm giảm lượng người đi bộ trên những con đường mòn đông đúc nhất, song một số người đi bộ đường dài vẫn tỏ ra lo ngại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"“I might not be able to get a permit for my favorite trails if none are left when I want to go,” says Regina Faroni, an Upton parks hiker.\", \"vi\": \"“Có thể tôi sẽ không xin được giấy phép để đi trên những con đường mòn yêu thích của mình nếu đến lúc tôi muốn đi thì không còn con đường nào nữa,” bà Regina Faroni, một người đi bộ đường dài tại các công viên ở Upton, chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"“In addition, I often check the weather in the morning and then decide if it’s a good day to hike,” she says.\", \"vi\": \"“Ngoài ra, tôi thường kiểm tra dự báo thời tiết vào buổi sáng rồi mới quyết định xem hôm đó có phải là ngày thích hợp để đi bộ đường dài hay không,” cô nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Having to apply for a permit could prevent her from taking spontaneous hikes.\", \"vi\": \"Việc phải xin giấy phép có thể khiến cô ấy không thể thực hiện những chuyến đi bộ đường dài ngẫu hứng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"“On the other hand, it would reduce the number of hikers on certain trails,” Faroni admits.\", \"vi\": \"“Mặt khác, điều này sẽ làm giảm số lượng người đi bộ đường dài trên một số tuyến đường mòn,” ông Faroni thừa nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"—EJ Harjo, Upton Digest\", \"vi\": \"—EJ Harjo, Upton Digest\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From: Arlo Gomes\", \"vi\": \"Từ: Arlo Gomes\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To: Upton Parks Department\", \"vi\": \"Kính gửi: Sở Công viên Upton\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Subject: Hiking permits\", \"vi\": \"Chủ đề: Giấy phép đi bộ đường dài\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Date: January 22\", \"vi\": \"Ngày: 22 tháng 1\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"To Whom It May Concern,\", \"vi\": \"Kính gửi quý vị có liên quan,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I read in the Upton Digest that hikers soon will be required to register for permits to hike on certain trails.\", \"vi\": \"Tôi đã đọc trên tạp chí Upton Digest rằng những người đi bộ đường dài sẽ sớm phải đăng ký để xin giấy phép khi đi bộ trên một số tuyến đường mòn nhất định.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"As the organizer of the Upton Hiking Club, I would like more details on how this will affect our club.\", \"vi\": \"Với tư cách là người tổ chức Câu lạc bộ Đi bộ đường dài Upton, tôi mong muốn được biết thêm chi tiết về việc điều này sẽ ảnh hưởng như thế nào đến câu lạc bộ của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"For example, is there a list of hiking trails that will require permits?\", \"vi\": \"Ví dụ, có danh sách các tuyến đường đi bộ đường dài nào yêu cầu phải có giấy phép không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I checked your Web site and could not find one.\", \"vi\": \"Tôi đã truy cập trang web của quý vị nhưng không tìm thấy thông tin đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Is it also the case that the number of permits issued will vary from trail to trail?\", \"vi\": \"Liệu số lượng giấy phép được cấp có khác nhau tùy theo từng tuyến đường mòn hay không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"About seventeen to twenty club members participate in our group hikes.\", \"vi\": \"Có khoảng từ mười bảy đến hai mươi thành viên câu lạc bộ tham gia các chuyến đi bộ đường dài theo nhóm của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I\'m concerned that we may not get enough permits to hike together.\", \"vi\": \"Tôi lo ngại rằng chúng ta có thể không xin được đủ giấy phép để cùng nhau đi bộ đường dài.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Are there special considerations for large groups?\", \"vi\": \"Có những lưu ý đặc biệt nào dành cho các đoàn khách đông người không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Finally, I am concerned that the permit requirement will not allow our club members to get together for a hike on the spur of the moment.\", \"vi\": \"Cuối cùng, tôi lo ngại rằng quy định về giấy phép sẽ khiến các thành viên câu lạc bộ của chúng tôi không thể tụ họp với nhau để đi bộ đường dài một cách ngẫu hứng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"We often will take an unplanned hike if we find that several members have a free day.\", \"vi\": \"Nếu thấy có một số thành viên rảnh rỗi, chúng tôi thường sẽ tổ chức một chuyến đi bộ đường dài không có kế hoạch trước.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I hope you are able to respond soon, as we are already planning our spring and summer hikes.\", \"vi\": \"Tôi hy vọng quý vị có thể sớm phản hồi, vì chúng tôi đang lên kế hoạch cho các chuyến đi bộ đường dài vào mùa xuân và mùa hè.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Arlo Gomes\", \"vi\": \"Arlo Gomes\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Organizer, Upton Hiking Club\", \"vi\": \"Người tổ chức, Câu lạc bộ Đi bộ đường dài Upton\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"From: Upton Parks Department\", \"vi\": \"Từ: Sở Công viên Upton\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"To: Arlo Gomes\", \"vi\": \"Kính gửi: Arlo Gomes\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Subject: RE: Hiking permits\", \"vi\": \"Chủ đề: RE: Giấy phép đi bộ đường dài\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Date: January 23\", \"vi\": \"Ngày: 23 tháng 1\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Attachment: Permit_Information_DRAFT\", \"vi\": \"Tệp đính kèm: Thông tin về Giấy phép_Bản dự thảo\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Hello, Mr. Gomes,\", \"vi\": \"Xin chào, thưa ông Gomes,\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"Thank you for your e-mail.\", \"vi\": \"Xin cảm ơn quý vị đã gửi email.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"I apologize that our Web site has not yet been updated with the information you were searching for and that the article in the Upton Digest was not clear.\", \"vi\": \"Tôi xin lỗi vì trang web của chúng tôi vẫn chưa được cập nhật thông tin mà quý vị đang tìm kiếm và vì bài báo trên tạp chí Upton Digest đã không trình bày rõ ràng.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"I have attached a proposed list of the twelve trails that will require permits and the number of permits that will be issued per day for each trail.\", \"vi\": \"Tôi đã đính kèm danh sách đề xuất gồm mười hai tuyến đường mòn sẽ yêu cầu giấy phép, cùng với số lượng giấy phép được cấp mỗi ngày cho từng tuyến đường mòn.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"The list will be finalized next month.\", \"vi\": \"Danh sách này sẽ được hoàn tất vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Permits can be reserved up to two weeks in advance, and the number of permits available for most trails is substantially higher than the number of Upton Hiking Club members who join your group hikes.\", \"vi\": \"Quý vị có thể đặt trước giấy phép tối đa hai tuần trước ngày đi, và số lượng giấy phép có sẵn cho hầu hết các tuyến đường mòn cao hơn đáng kể so với số lượng thành viên Câu lạc bộ Đi bộ Upton tham gia các chuyến đi bộ theo nhóm của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Same-day permits can be obtained.\", \"vi\": \"Quý vị có thể xin giấy phép ngay trong ngày.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 44, \"question_numbers\": []}, {\"en\": \"If you have not already done so, you can sign up on our Web site for our weekly newsletter.\", \"vi\": \"Nếu quý vị chưa đăng ký, quý vị có thể đăng ký trên trang web của chúng tôi để nhận bản tin hàng tuần.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 45, \"question_numbers\": []}, {\"en\": \"Doing so will ensure that you get advance notice of any updates to our policies.\", \"vi\": \"Việc làm như vậy sẽ đảm bảo rằng quý vị sẽ được thông báo trước về bất kỳ cập nhật nào đối với các chính sách của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 46, \"question_numbers\": []}, {\"en\": \"Jenny Grieb, Public Relations, Upton Parks Department\", \"vi\": \"Bà Jenny Grieb, Phụ trách Quan hệ Công chúng, Sở Công viên Upton\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 47, \"question_numbers\": []}]' WHERE `id` = 'a716302d-2b34-4282-8741-63c72ed83598';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Jaya Pillay (9:04 A.M.)\", \"vi\": \"Jaya Pillay (9 giờ 04 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Paul and Kristen—are you two going to the meeting this morning?\", \"vi\": \"Paul và Kristen — hai người có dự định tham dự cuộc họp sáng nay không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I need a favor because I\'m running late.\", \"vi\": \"Tôi cần nhờ anh/chị một việc vì tôi đang bị trễ giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Paul Smythe (9:06 A.M.)\", \"vi\": \"Paul Smythe (9 giờ 06 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I am.\", \"vi\": \"Đúng vậy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"What do you need?\", \"vi\": \"Quý vị cần gì?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Jaya Pillay (9:07 A.M.)\", \"vi\": \"Jaya Pillay (9 giờ 07 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Could you say a few words about last weekend\'s film festival in Atlanta?\", \"vi\": \"Xin quý vị có thể chia sẻ vài lời về liên hoan phim diễn ra vào cuối tuần vừa qua tại Atlanta được không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Kristen Tervo (9:07 A.M.)\", \"vi\": \"Kristen Tervo (9 giờ 07 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Wait, what time is the meeting?\", \"vi\": \"Chờ đã, cuộc họp diễn ra vào mấy giờ vậy?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Jaya Pillay (9:08 A.M.)\", \"vi\": \"Jaya Pillay (9 giờ 08 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"10:30 A.M.\", \"vi\": \"10 giờ 30 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Paul Smythe (9:08 A.M.)\", \"vi\": \"Paul Smythe (9 giờ 08 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sure.\", \"vi\": \"Được thôi.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"What do you want me to say?\", \"vi\": \"Anh muốn tôi nói gì đây?\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Kristen Tervo (9:09 A.M.)\", \"vi\": \"Kristen Tervo (9 giờ 09 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 6, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Oh right.\", \"vi\": \"À đúng rồi.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I won\'t be there today.\", \"vi\": \"Hôm nay tôi sẽ không có mặt ở đó.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I\'m busy working on an issue for David in Finance.\", \"vi\": \"Tôi đang bận giải quyết một vấn đề cho anh David ở Phòng Tài chính.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Jaya Pillay (9:10 A.M.)\", \"vi\": \"Jaya Pillay (9 giờ 10 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 7, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Paul, just say something about how attendance was great, and the team should feel proud of themselves for their hard work.\", \"vi\": \"Paul ạ, xin ông hãy nói vài lời về việc số lượng khán giả đến xem rất đông, và đội bóng nên tự hào về bản thân vì những nỗ lực của mình.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Paul Smythe (9:11 A.M.)\", \"vi\": \"Paul Smythe (9 giờ 11 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 8, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Sure.\", \"vi\": \"Được ạ.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"When you arrive, will you be saying anything about the expansion into Florida next quarter?\", \"vi\": \"Khi quý vị đến, liệu quý vị có đề cập gì về kế hoạch mở rộng hoạt động sang bang Florida trong quý tới không?\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Jaya Pillay (9:12 A.M.)\", \"vi\": \"Jaya Pillay (9 giờ 12 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 9, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Yes, but most of the meeting will be about developing strategies to sell more tickets on opening weekends in our existing theaters.\", \"vi\": \"Đúng vậy, nhưng phần lớn nội dung cuộc họp sẽ tập trung vào việc xây dựng các chiến lược nhằm tăng doanh số bán vé trong các cuối tuần công chiếu tại các rạp chiếu phim hiện có của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Kristen Tervo (9:14 A.M.)\", \"vi\": \"Kristen Tervo (9 giờ 14 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 10, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"That\'s good to know.\", \"vi\": \"Thật tốt khi biết điều đó.\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I\'m meeting with the vice president of development tomorrow.\", \"vi\": \"Ngày mai tôi sẽ có cuộc gặp với Phó Chủ tịch phụ trách phát triển.\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I\'ll be sure to fill her in on what we\'ve been doing.\", \"vi\": \"Tôi sẽ nhất định thông báo cho cô ấy biết những việc chúng tôi đã làm.\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = 'a73159b4-90b1-45fa-a3a3-7482edf3ffc6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"E-Mail Message\", \"vi\": \"Thông điệp email\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Dexter Abbott\", \"vi\": \"Từ: Dexter Abbott\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To: Nina Sosa\", \"vi\": \"Kính gửi: Nina Sosa\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 20 August\", \"vi\": \"Ngày: 20 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Next steps\", \"vi\": \"Chủ đề: Các bước tiếp theo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Sosa,\", \"vi\": \"Kính gửi bà Sosa,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I have good news.\", \"vi\": \"Tôi có một tin vui.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The plans for the layout of the new Fountain Road office building have just been approved by Lanfei Chan at our corporate office.\", \"vi\": \"Bản thiết kế mặt bằng tòa nhà văn phòng mới tại Fountain Road vừa được bà Lanfei Chan tại trụ sở chính của công ty chúng tôi phê duyệt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We now need to start thinking about the artwork for the main open-plan office area on the third floor of the building.\", \"vi\": \"Hiện tại, chúng ta cần bắt đầu suy nghĩ về các tác phẩm nghệ thuật dành cho khu vực văn phòng mở chính tại tầng ba của tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This is one of our last tasks before the office opens in October.\", \"vi\": \"Đây là một trong những nhiệm vụ cuối cùng của chúng tôi trước khi văn phòng chính thức đi vào hoạt động vào tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I have heard that Red Starling Art has a good reputation for helping with office interiors.\", \"vi\": \"Tôi được biết rằng Red Starling Art có uy tín tốt trong lĩnh vực tư vấn thiết kế nội thất văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Could you look at the company\'s Web site today and find out if any of its services might be suitable for us?\", \"vi\": \"Quý vị có thể truy cập trang web của công ty hôm nay và tìm hiểu xem liệu có dịch vụ nào của họ phù hợp với chúng tôi không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I am wondering whether photography or paintings would look best in the space.\", \"vi\": \"Tôi đang băn khoăn không biết trong không gian này thì ảnh chụp hay tranh vẽ sẽ phù hợp hơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"What do you think?\", \"vi\": \"Quý vị nghĩ sao?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I am still waiting to hear back from Maxwell Willis in Finance about the budget for art, so please do not agree to anything with Red Starling Art until we know more.\", \"vi\": \"Tôi vẫn đang chờ phản hồi từ ông Maxwell Willis ở Phòng Tài chính về ngân sách dành cho nghệ thuật, vì vậy xin quý vị đừng đồng ý bất kỳ điều gì với Red Starling Art cho đến khi chúng ta có thêm thông tin.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Dexter Abbott, Facilities Manager\", \"vi\": \"Ông Dexter Abbott, Trưởng phòng Quản lý Cơ sở vật chất\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"KLX Accountancy\", \"vi\": \"Công ty Kế toán KLX\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"https://www.redstarlingart.co.uk/offices/\", \"vi\": \"https://www.redstarlingart.co.uk/offices/\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Red Starling Art offers a range of consultancy services for office buildings:\", \"vi\": \"Red Starling Art cung cấp một loạt các dịch vụ tư vấn dành cho các tòa nhà văn phòng:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Remake: For clients who want a complete redesign of the interior of their office, we work with you to create a layout and decoration scheme that meets your needs.\", \"vi\": \"Thiết kế lại: Đối với những khách hàng mong muốn thiết kế lại hoàn toàn nội thất văn phòng, chúng tôi sẽ phối hợp cùng quý vị để tạo ra phương án bố trí và trang trí phù hợp với nhu cầu của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Align: For clients looking to incorporate artwork into a new office, we help you find the right pieces (paintings, photographs, prints, or sculptures) for your space.\", \"vi\": \"Align: Đối với những khách hàng mong muốn kết hợp các tác phẩm nghệ thuật vào văn phòng mới, chúng tôi sẽ hỗ trợ quý vị tìm kiếm những tác phẩm phù hợp (tranh vẽ, ảnh chụp, bản in hoặc tác phẩm điêu khắc) cho không gian của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Connect: For clients who want to add a local touch to their offices, we collaborate with area artists and photographers to bring their unique perspective to you.\", \"vi\": \"Kết nối: Đối với những khách hàng mong muốn mang đến nét đặc trưng địa phương cho văn phòng của mình, chúng tôi hợp tác với các nghệ sĩ và nhiếp ảnh gia trong khu vực để mang đến cho quý vị những góc nhìn độc đáo của họ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Reframe: For clients who want to update but keep their existing artwork, we suggest new framing, new lighting, or new arrangements for a fresh look.\", \"vi\": \"Tái thiết kế khung tranh: Đối với những khách hàng mong muốn làm mới không gian nhưng vẫn muốn giữ lại các tác phẩm nghệ thuật hiện có, chúng tôi đề xuất các giải pháp như làm khung mới, thay đổi hệ thống chiếu sáng hoặc sắp xếp lại bố cục để mang đến một diện mạo tươi mới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Our work is always tailored to the specific needs of our clients, so we cannot provide fixed prices.\", \"vi\": \"Công việc của chúng tôi luôn được thiết kế phù hợp với nhu cầu cụ thể của từng khách hàng, do đó chúng tôi không thể đưa ra mức giá cố định.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Please e-mail Birgit Lowenbruck at blowenbruck@redstarlingart.co.uk to book a free consultation.\", \"vi\": \"Xin vui lòng gửi email cho bà Birgit Lowenbruck theo địa chỉ blowenbruck@redstarlingart.co.uk để đặt lịch tư vấn miễn phí.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"After the consultation, she will provide you with an estimate for the agreed-upon services.\", \"vi\": \"Sau buổi tư vấn, cô ấy sẽ cung cấp cho quý vị bản dự toán chi phí cho các dịch vụ đã thỏa thuận.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Home |\", \"vi\": \"Trang chủ |\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"About Us |\", \"vi\": \"Giới thiệu về chúng tôi |\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Services |\", \"vi\": \"Dịch vụ |\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = 'a757d300-6190-4d01-b2c0-16942af55277';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Foursquare Housing offers corporate housing with apartment units in the greater Miltonville area.\", \"vi\": \"Foursquare Housing cung cấp dịch vụ nhà ở dành cho doanh nghiệp với các căn hộ tại khu vực Miltonville và các vùng lân cận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The apartments are fully furnished and include wireless Internet service.\", \"vi\": \"Các căn hộ được trang bị đầy đủ nội thất và có dịch vụ Internet không dây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Floor plans and photos of apartment interiors can be viewed online.\", \"vi\": \"Quý vị có thể xem bản vẽ mặt bằng và hình ảnh nội thất căn hộ trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Center Tower\", \"vi\": \"Tòa tháp Trung tâm\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Located in downtown Miltonville, the ten-story building has shops on the ground level.\", \"vi\": \"Tọa lạc tại trung tâm thành phố Miltonville, tòa nhà cao mười tầng này có các cửa hàng ở tầng trệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Center Tower is on the southwest corner of Beeman Square, features a rooftop garden, and is close to public transportation.\", \"vi\": \"Tòa tháp Center Tower tọa lạc tại góc tây nam của Quảng trường Beeman, có khu vườn trên tầng thượng và nằm gần các tuyến giao thông công cộng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Angora Plaza\", \"vi\": \"Angora Plaza\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Located near downtown Miltonville, the building has a self-service laundromat and a large parking garage.\", \"vi\": \"Tọa lạc gần trung tâm thành phố Miltonville, tòa nhà này có một tiệm giặt là tự phục vụ và một bãi đỗ xe rộng lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"It is also close to two subway stations.\", \"vi\": \"Nơi đây cũng nằm gần hai ga tàu điện ngầm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Regent Apartments\", \"vi\": \"Căn hộ Regent\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Located approximately six miles outside of Miltonville, the building features an on-site business center and is within walking distance of public transportation.\", \"vi\": \"Tọa lạc cách Miltonville khoảng sáu dặm, tòa nhà này có trung tâm kinh doanh ngay trong khuôn viên và nằm trong phạm vi có thể đi bộ đến các điểm giao thông công cộng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Cityview Gardens\", \"vi\": \"Cityview Gardens\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Cityview Gardens is a complex of four two-story buildings located in Dayton, about a twenty-minute drive from downtown Miltonville.\", \"vi\": \"Cityview Gardens là một khu phức hợp gồm bốn tòa nhà hai tầng tọa lạc tại Dayton, cách trung tâm thành phố Miltonville khoảng hai mươi phút lái xe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The property boasts a fitness center and a swimming pool and is adjacent to a community park.\", \"vi\": \"Khu căn hộ này có trung tâm thể dục thể hình và hồ bơi, đồng thời nằm ngay cạnh một công viên cộng đồng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"A bus line operates a route through the neighborhood.\", \"vi\": \"Có một tuyến xe buýt chạy qua khu dân cư này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From: gsteuber@wardertechnology.com\", \"vi\": \"Nguồn: gsteuber@wardertechnology.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"To: info@foursquarehousing.com\", \"vi\": \"Gửi tới: info@foursquarehousing.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date: July 12\", \"vi\": \"Ngày: 12 tháng 7\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Subject: Inquiry\", \"vi\": \"Chủ đề: Yêu cầu thông tin\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Foursquare Housing,\", \"vi\": \"Foursquare Housing,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I work in the human resources office of Warder Technology\'s Miltonville division.\", \"vi\": \"Tôi đang làm việc tại phòng nhân sự của chi nhánh Miltonville thuộc Công ty Warder Technology.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"We are seeking an apartment that can be used by employees from outside the area who will work at our headquarters temporarily.\", \"vi\": \"Chúng tôi đang tìm kiếm một căn hộ để dành cho các nhân viên đến từ các khu vực khác, những người sẽ làm việc tạm thời tại trụ sở chính của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"We need an apartment for employees who will be in Miltonville for two months or more.\", \"vi\": \"Chúng tôi cần một căn hộ dành cho các nhân viên sẽ làm việc tại Miltonville trong thời gian từ hai tháng trở lên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"The apartment should have amenities like a gym and a pool.\", \"vi\": \"Căn hộ nên được trang bị các tiện ích như phòng tập thể dục và hồ bơi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Gina Steuber\", \"vi\": \"Gina Steuber\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"From: info@foursquarehousing.com\", \"vi\": \"Nguồn: info@foursquarehousing.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"To: gsteuber@wardertechnology.com\", \"vi\": \"Gửi tới: gsteuber@wardertechnology.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Date: July 12\", \"vi\": \"Ngày: 12 tháng 7\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Subject: Information you requested\", \"vi\": \"Chủ đề: Thông tin mà quý vị đã yêu cầu\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Attachment: Pricing_Leases.pdf\", \"vi\": \"Tệp đính kèm: Pricing_Leases.pdf\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Dear Ms. Steuber,\", \"vi\": \"Kính gửi bà Steuber,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Thank you for your interest in Foursquare Housing.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã quan tâm đến Foursquare Housing.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"We have a two-bedroom apartment that will be available on August 15 that should meet your requirements.\", \"vi\": \"Chúng tôi có một căn hộ hai phòng ngủ sẽ sẵn sàng cho thuê vào ngày 15 tháng 8, chắc chắn sẽ đáp ứng được các yêu cầu của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"I have attached a price list for this unit and our other apartments as well.\", \"vi\": \"Tôi đã đính kèm bảng giá cho căn hộ này cũng như các căn hộ khác của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"If you agree that this meets your needs, I can send a contract.\", \"vi\": \"Nếu quý vị đồng ý rằng điều này phù hợp với nhu cầu của quý vị, tôi có thể gửi hợp đồng cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"I should point out that your corporate headquarters in Beeman Square is next to apartments owned by Foursquare.\", \"vi\": \"Tôi xin được lưu ý rằng trụ sở chính của quý công ty tại Beeman Square nằm ngay bên cạnh các căn hộ thuộc sở hữu của Foursquare.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"One apartment here will also become available in August.\", \"vi\": \"Một căn hộ tại đây cũng sẽ có sẵn vào tháng Tám.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"This would be very convenient if you have short-term visitors.\", \"vi\": \"Điều này sẽ rất thuận tiện nếu quý vị có khách đến thăm trong thời gian ngắn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Sam Flannery\", \"vi\": \"Sam Flannery\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Leasing Agent\", \"vi\": \"Nhân viên môi giới cho thuê\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}]' WHERE `id` = 'a7ab2378-bd42-4c99-b2c5-875bb2020c2a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Louisa Santos 9:30 A.M.\", \"vi\": \"Louisa Santos 9 giờ 30 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Kenji, where are you?\", \"vi\": \"Kenji ơi, anh đang ở đâu vậy?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The job candidates are here.\", \"vi\": \"Các ứng viên đã có mặt tại đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Kenji Muro 9:31 A.M.\", \"vi\": \"Kenji Muro 9 giờ 31 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Sorry!\", \"vi\": \"Xin lỗi!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The bridge is closed.\", \"vi\": \"Cây cầu hiện đang đóng cửa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"My bus had to take a detour.\", \"vi\": \"Xe buýt của tôi đã phải đi đường vòng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I should be there in 30 minutes.\", \"vi\": \"Tôi sẽ có mặt tại đó trong 30 phút nữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please start without me.\", \"vi\": \"Xin quý vị hãy bắt đầu trước đi, không cần đợi tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Louisa Santos 9:34 A.M.\", \"vi\": \"Louisa Santos 9:34 sáng\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I\'m going to interview Elena Crenshaw first.\", \"vi\": \"Trước tiên, tôi sẽ phỏng vấn bà Elena Crenshaw.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Kenji Muro 9:34 A.M.\", \"vi\": \"Kenji Muro 9 giờ 34 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Good.\", \"vi\": \"Tốt.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"She\'s the one with experience at another T-shirt company.\", \"vi\": \"Cô ấy là người từng có kinh nghiệm làm việc tại một công ty sản xuất áo thun khác.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Louisa Santos 9:35 A.M.\", \"vi\": \"Louisa Santos 9 giờ 35 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Yes.\", \"vi\": \"Vâng.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Can you believe our small company has grown so much that we need to hire someone just to process orders?\", \"vi\": \"Quý vị có tin được không, công ty nhỏ bé của chúng tôi đã phát triển mạnh mẽ đến mức chúng tôi cần phải tuyển dụng một người chỉ để xử lý đơn hàng?\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Kenji Muro 9:36 A.M.\", \"vi\": \"Kenji Muro 9 giờ 36 phút sáng\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I know!\", \"vi\": \"Tôi biết rồi!\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"OK.\", \"vi\": \"Được rồi.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I\'ll see you soon.\", \"vi\": \"Tôi sẽ sớm gặp lại quý vị.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = 'a7afc585-c159-4491-a77b-ce8b0a33391a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Creating a Calming Waiting Room\", \"vi\": \"Tạo ra một phòng chờ mang lại cảm giác thư thái\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Attending a medical appointment provokes anxiety in many people.\", \"vi\": \"Việc đi khám bệnh khiến nhiều người cảm thấy lo lắng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Follow the tips below to combat this issue by creating a relaxing space for your patients.\", \"vi\": \"Hãy làm theo các lời khuyên dưới đây để khắc phục vấn đề này bằng cách tạo ra một không gian thư giãn cho bệnh nhân của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"This can foster a positive mindset in patients, easing built-up tension and making the appointment go more smoothly.\", \"vi\": \"Điều này có thể giúp bệnh nhân duy trì một tâm thế tích cực, xoa dịu những căng thẳng tích tụ và giúp buổi khám diễn ra suôn sẻ hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Color Choices and Wall Décor\", \"vi\": \"Các lựa chọn màu sắc và trang trí tường\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Use shades of blue or green to create a calming atmosphere.\", \"vi\": \"Hãy sử dụng các sắc thái màu xanh dương hoặc xanh lá cây để tạo ra một bầu không khí yên bình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Decorate the walls with paintings in complementary colors, especially those with nature scenes.\", \"vi\": \"Hãy trang trí các bức tường bằng những bức tranh có màu sắc hài hòa, đặc biệt là những bức tranh vẽ cảnh thiên nhiên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Restrict posters with medical information to those that are absolutely necessary.\", \"vi\": \"Chỉ nên treo các áp phích chứa thông tin y tế khi thực sự cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Layout and Furniture\", \"vi\": \"Bố cục và nội thất\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Make sure the chairs and sofas have a soft covering to create a cozy and home-like feeling.\", \"vi\": \"Hãy đảm bảo rằng ghế và ghế sofa được bọc bằng chất liệu mềm mại để tạo cảm giác ấm cúng và thân thuộc như ở nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Taller chairs are easy to get in and out of, which is useful for people with mobility issues.\", \"vi\": \"Những chiếc ghế cao hơn giúp người dùng dễ dàng ngồi xuống và đứng dậy, điều này rất hữu ích cho những người gặp khó khăn trong việc di chuyển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Use modular seating that can be moved into different configurations, as some people may visit alone and want privacy while others may come with family members and want to sit together.\", \"vi\": \"Hãy sử dụng hệ thống ghế ngồi theo mô-đun có thể sắp xếp thành nhiều kiểu bố trí khác nhau, bởi một số người có thể đến một mình và mong muốn sự riêng tư, trong khi những người khác có thể đến cùng các thành viên trong gia đình và muốn ngồi cùng nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sounds\", \"vi\": \"Âm thanh\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Background music or nature sounds should be played at a low volume.\", \"vi\": \"Nên phát nhạc nền hoặc âm thanh thiên nhiên ở mức âm lượng thấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Thick curtains can help to absorb sound and reduce echoes in a room.\", \"vi\": \"Rèm cửa dày có thể giúp hấp thụ âm thanh và giảm tiếng vang trong phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Valued readers, we hope you have found these tips helpful.\", \"vi\": \"Kính thưa quý độc giả, chúng tôi hy vọng những lời khuyên này sẽ hữu ích cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"What would you like to learn about in future issues?\", \"vi\": \"Trong các số tiếp theo, quý vị mong muốn tìm hiểu về chủ đề nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Medical World Magazine July Issue\", \"vi\": \"Tạp chí Medical World - Số tháng 7\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Medical World Magazine\", \"vi\": \"Tạp chí Thế giới Y học\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Letters to the Editor\", \"vi\": \"Thư gửi Ban biên tập\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I would like to offer a correction to some information you provided about creating calming waiting rooms.\", \"vi\": \"Tôi xin được đề xuất một số điều chỉnh đối với một số thông tin mà quý vị đã cung cấp về việc thiết kế các phòng chờ tạo cảm giác thư thái.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"While it is important for the furniture in a waiting room to be inviting and comfortable, this goal must not take precedence over health and safety considerations.\", \"vi\": \"Mặc dù việc đảm bảo đồ nội thất trong phòng chờ phải tạo cảm giác thân thiện và thoải mái là điều quan trọng, song mục tiêu này không được đặt lên trên các yếu tố liên quan đến sức khỏe và an toàn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Upholstery that is soft and cloth-like can absorb fluids into the underlying cushion, making it difficult to disinfect.\", \"vi\": \"Lớp bọc ghế mềm mại và có kết cấu giống vải có thể làm chất lỏng thấm vào lớp đệm bên dưới, khiến việc khử trùng trở nên khó khăn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"A better option is furniture that is covered in vinyl.\", \"vi\": \"Một lựa chọn tốt hơn là đồ nội thất được bọc bằng chất liệu vinyl.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"It is robust, lasting over ten years with heavy use, and can be wiped down quickly and easily to remove dirt and germs.\", \"vi\": \"Sản phẩm này rất bền, có tuổi thọ trên mười năm ngay cả khi sử dụng thường xuyên với tần suất cao, đồng thời có thể lau chùi nhanh chóng và dễ dàng để loại bỏ bụi bẩn và vi trùng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"The stylish and practical furniture made by my company, Free-Form Inc., uses vinyl with an antimicrobial surface, effectively reducing the spread of disease in medical settings.\", \"vi\": \"Các sản phẩm nội thất vừa thời trang vừa tiện dụng do công ty của tôi, Free-Form Inc., sản xuất được làm từ chất liệu vinyl có bề mặt kháng khuẩn, giúp giảm thiểu hiệu quả sự lây lan của dịch bệnh trong các cơ sở y tế.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Dominic McAlister\", \"vi\": \"Dominic McAlister\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = 'a7d3268d-745a-48f1-be3a-abef7c37a2a0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: <customerservice@office-loft.com>\", \"vi\": \"Từ: <customerservice@office-loft.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: <jahan.soltani@iux-mail.com>\", \"vi\": \"Đến: <jahan.soltani@iux-mail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Re: Order #7823\", \"vi\": \"Chủ đề: V/v Đơn hàng #7823\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: July 21\", \"vi\": \"Ngày: Ngày 21 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Coupon\", \"vi\": \"Đính kèm: Phiếu giảm giá\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Soltani,\", \"vi\": \"Kính gửi ông Soltani,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We are sorry to hear that Order #7823 arrived at your business after the promised date of July 14.\", \"vi\": \"Chúng tôi rất tiếc khi biết rằng Đơn hàng #7823 đã đến doanh nghiệp của ông sau ngày hẹn giao là ngày 14 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"It appears that the order ______[131] later than scheduled due to a problem with our shipping provider.\", \"vi\": \"Có vẻ như đơn hàng ______[131] muộn hơn dự kiến do một sự cố với bên vận chuyển của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [131]}, {\"en\": \"We will refund the shipping charge to your account.\", \"vi\": \"Chúng tôi sẽ hoàn lại phí vận chuyển vào tài khoản của ông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"In addition, please accept the attached coupon as compensation for the ______[132].\", \"vi\": \"Ngoài ra, xin ông vui lòng nhận phiếu giảm giá đính kèm như một sự bồi thường cho sự ______[132] này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [132]}, {\"en\": \"It will give you a 30% discount on your next order from our Web site.\", \"vi\": \"Nó sẽ mang lại cho ông mức giảm giá 30% cho đơn hàng tiếp theo từ trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"______[133].\", \"vi\": \"______[133].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [133]}, {\"en\": \"You may also print out the coupon and use it at ______[134] of our offline stores.\", \"vi\": \"Ông cũng có thể in phiếu giảm giá này ra và sử dụng nó tại ______[134] cửa hàng bán lẻ truyền thống của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": [134]}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Scott Conrad\", \"vi\": \"Scott Conrad\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Office Loft Customer Service\", \"vi\": \"Bộ phận Chăm sóc Khách hàng Office Loft\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = 'a7f3b0d4-66ba-4ddf-b951-513c951c9e90';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Time Slot - Room 3A (Capacity: 35) - Room 3B (Capacity: 50)\", \"vi\": \"Khung giờ - Phòng 3A (Sức chứa: 35 người) - Phòng 3B (Sức chứa: 50 người)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Morning 1\\n9:00–10:00 A.M. - Available - Sales Team\\n(Use Room 3A for dividing into project groups, if necessary.)\", \"vi\": \"Buổi sáng ngày 1\\n9:00–10:00 sáng - Chưa có lịch trình - Đội ngũ bán hàng\\n(Nếu cần, vui lòng sử dụng Phòng 3A để chia thành các nhóm dự án.)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Morning 2\\n10:30–11:45 A.M. - Human Resources - Summer Events Planning\", \"vi\": \"Buổi sáng ngày 2\\n10:30–11:45 sáng - Phòng Nhân sự - Lập kế hoạch các sự kiện mùa hè\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Afternoon 1\\n2:00–2:45 P.M. - Customer Service - Technology and Engineering\", \"vi\": \"Buổi chiều 1\\n14:00–14:45 – Dịch vụ khách hàng – Công nghệ và Kỹ thuật\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Afternoon 2\\n3:00–4:00 P.M. - Available - Marketing Group\", \"vi\": \"Buổi chiều 2\\n15:00–16:00 – Còn chỗ trống – Nhóm Tiếp thị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Brenton Solutions\", \"vi\": \"Brenton Solutions\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Building 3 Conference Room Calendar\", \"vi\": \"Lịch sử dụng phòng họp Tòa nhà 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Mondays in March\", \"vi\": \"Các ngày thứ Hai trong tháng Ba\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This schedule shows the meetings regularly scheduled in conference rooms on Mondays in the month of March.\", \"vi\": \"Lịch trình này trình bày các cuộc họp được lên lịch thường xuyên tại các phòng hội nghị vào các ngày thứ Hai trong tháng Ba.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Keep in mind that management may request a room with minimal advance notice.\", \"vi\": \"Xin lưu ý rằng ban quản lý có thể yêu cầu một phòng mà không cần thông báo trước quá lâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"If this occurs, you may contact Janet Marten at jmarten@brentonsolutions.com to inquire about rooms in other buildings on campus.\", \"vi\": \"Nếu trường hợp này xảy ra, quý vị có thể liên hệ với bà Janet Marten qua địa chỉ email jmarten@brentonsolutions.com để tìm hiểu về các phòng ở các tòa nhà khác trong khuôn viên trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: Team Leaders\", \"vi\": \"Kính gửi: Các Trưởng nhóm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From: Janet Marten\", \"vi\": \"Từ: Janet Marten\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Subject: Conference Room Calendars\", \"vi\": \"Chủ đề: Lịch sử dụng phòng hội nghị\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date: February 27\", \"vi\": \"Ngày: 27 tháng 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To All Team Leads:\", \"vi\": \"Kính gửi các Trưởng nhóm:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Please be informed that both Building 3 conference rooms will be unavailable throughout the day on Monday, March 12, as our division of Brenton Solutions will be hosting the Corporate Management team.\", \"vi\": \"Kính xin thông báo rằng cả hai phòng hội nghị tại Tòa nhà 3 sẽ không thể sử dụng trong suốt ngày thứ Hai, ngày 12 tháng 3, do bộ phận Brenton Solutions của chúng tôi sẽ tiếp đón Ban Lãnh đạo Công ty.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"These meetings are expected to begin promptly at 9:30 A.M. and to extend one full hour past the time that afternoon meetings usually end.\", \"vi\": \"Các cuộc họp này dự kiến sẽ bắt đầu đúng 9 giờ 30 phút sáng và kéo dài thêm một giờ so với thời gian kết thúc thông thường của các cuộc họp buổi chiều.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Any team leads in need of conference space on this date should send me their request no later than Friday by replying directly to this e-mail.\", \"vi\": \"Mọi trưởng nhóm nào có nhu cầu thuê phòng hội nghị vào ngày này vui lòng gửi yêu cầu cho tôi chậm nhất là vào thứ Sáu bằng cách trả lời trực tiếp email này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Space will be reserved on a first-come, first-served basis.\", \"vi\": \"Chỗ ngồi sẽ được đặt theo nguyên tắc “ai đến trước, được phục vụ trước”.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Thanks!\", \"vi\": \"Cảm ơn!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Janet Marten, Corporate Secretary\", \"vi\": \"Bà Janet Marten, Thư ký Công ty\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"To: All Employees\", \"vi\": \"Kính gửi: Toàn thể nhân viên\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"From: Janet Marten\", \"vi\": \"Từ: Janet Marten\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Subject: Monday Schedule Change\", \"vi\": \"Chủ đề: Thay đổi lịch trình vào thứ Hai\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Date: March 5\", \"vi\": \"Ngày: 5 tháng 3\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Please make note of the following changes to the meeting room schedule because of management meetings on March 12.\", \"vi\": \"Kính mong quý vị lưu ý những thay đổi sau đây đối với lịch sử dụng phòng họp do các cuộc họp của ban quản lý diễn ra vào ngày 12 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Temporary room assignments are:\", \"vi\": \"Danh sách phân công phòng tạm thời như sau:\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"-Morning 1 meetings will take place in rooms 5A and 5B.\", \"vi\": \"- Các cuộc họp vào buổi sáng ngày thứ nhất sẽ diễn ra tại phòng 5A và 5B.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Please divide the space as needed.\", \"vi\": \"Xin vui lòng phân chia không gian theo nhu cầu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"-The marketing group will be meeting in 4B in the Afternoon 1 time slot.\", \"vi\": \"- Nhóm tiếp thị sẽ họp tại phòng 4B vào khung giờ 1 buổi chiều.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Keep in mind that these rooms are both meeting spaces that have limited capacity, so please plan accordingly.\", \"vi\": \"Xin lưu ý rằng cả hai phòng này đều là không gian hội họp có sức chứa hạn chế, vì vậy xin quý vị hãy lên kế hoạch phù hợp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Meetings not addressed above are canceled.\", \"vi\": \"Các cuộc họp chưa được đề cập ở trên sẽ bị hủy bỏ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Any questions regarding meetings or cancellations should be directed to team leads.\", \"vi\": \"Mọi thắc mắc liên quan đến các cuộc họp hoặc việc hủy bỏ xin vui lòng liên hệ với các trưởng nhóm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Meeting notes will be posted electronically in the usual location for those who are unable to attend.\", \"vi\": \"Biên bản cuộc họp sẽ được đăng tải dưới dạng điện tử tại vị trí thông thường dành cho những ai không thể tham dự.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = 'a7f8443a-77cb-400b-9025-16b759049136';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"D-Zine Pop\", \"vi\": \"D-Zine Pop\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"D-Zine Pop is your source for information about the latest ___131___ in the world of fashion.\", \"vi\": \"D-Zine Pop là nguồn cung cấp thông tin cho bạn về những ___131___ mới nhất trong thế giới thời trang.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [131]}, {\"en\": \"What started as a social media experiment ___132___ into a content platform with subscribers in seventeen countries worldwide.\", \"vi\": \"Những gì bắt đầu như một thí nghiệm trên mạng xã hội đã ___132___ thành một nền tảng nội dung có lượng người đăng ký ở mười bảy quốc gia trên toàn thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [132]}, {\"en\": \"We are constantly adding features to improve our user experience and share what apparel and clothing accessories are popular right now.\", \"vi\": \"Chúng tôi liên tục bổ sung các tính năng để cải thiện trải nghiệm người dùng và chia sẻ những loại trang phục và phụ kiện quần áo nào đang thịnh hành ngay lúc này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We also make periodic updates to our terms of service.\", \"vi\": \"Chúng tôi cũng thực hiện các bản cập nhật định kỳ cho điều khoản dịch vụ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Subscribers\' ___133___ access to content is contingent upon consenting to these terms; therefore, we encourage you to review and accept them at dzinepop.com/privacy.\", \"vi\": \"Việc người đăng ký ___133___ tiếp tục truy cập vào nội dung phụ thuộc vào việc đồng ý với các điều khoản này; do đó, chúng tôi khuyến khích bạn xem xét và chấp nhận chúng tại dzinepop.com/privacy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [133]}, {\"en\": \"Contact our customer service team at support@dzinepop.com if you have any questions.\", \"vi\": \"Hãy liên hệ với đội ngũ dịch vụ khách hàng của chúng tôi theo địa chỉ support@dzinepop.com nếu bạn có bất kỳ câu hỏi nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"___134___.\", \"vi\": \"___134___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [134]}]' WHERE `id` = 'a8030d38-e4ef-4755-94e5-687a359db556';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MEMO\", \"vi\": \"BẢN GHI NHỚ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All employees\", \"vi\": \"Gửi: Toàn thể nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Loretta Hirano, Human Resources Director\", \"vi\": \"Từ: Loretta Hirano, Giám đốc Nhân sự\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: Friday, April 7, 9:03 A.M.\", \"vi\": \"Ngày: Thứ Sáu, ngày 7 tháng 4, 9 giờ 03 phút sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Summer work arrangements\", \"vi\": \"Chủ đề: Các thỏa thuận về công việc mùa hè\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear colleagues,\", \"vi\": \"Kính gửi các đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As you know, the period from June 1 through August 31 is ordinarily our busiest time.\", \"vi\": \"Như quý vị đã biết, khoảng thời gian từ ngày 1 tháng 6 đến ngày 31 tháng 8 thường là giai đoạn bận rộn nhất của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This summer promises to be even busier than usual, as business has increased by 15% since this time last year.\", \"vi\": \"Mùa hè năm nay hứa hẹn sẽ còn bận rộn hơn bình thường, khi doanh thu đã tăng 15% so với cùng kỳ năm ngoái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Management is also well aware that summer is the time when many of our employees like to take time off from work.\", \"vi\": \"Ban lãnh đạo cũng nhận thức rõ rằng mùa hè là thời điểm mà nhiều nhân viên của chúng tôi thường thích nghỉ phép.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Still, we must have sufficient staff on hand to deliver service of the highest quality, a policy for which Bellerson Financial is highly regarded by its customers.\", \"vi\": \"Dù vậy, chúng tôi vẫn phải đảm bảo có đủ nhân sự để cung cấp dịch vụ với chất lượng cao nhất — chính chính sách này đã giúp Bellerson Financial nhận được sự đánh giá cao từ phía khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Therefore, if you are planning to take a vacation between June 1 and August 31, kindly submit your request by Friday, April 28.\", \"vi\": \"Do đó, nếu quý vị có kế hoạch đi nghỉ trong khoảng thời gian từ ngày 1 tháng 6 đến ngày 31 tháng 8, xin vui lòng nộp đơn xin nghỉ trước thứ Sáu, ngày 28 tháng 4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You will receive a response as soon as possible but no later than Monday, May 8.\", \"vi\": \"Quý vị sẽ nhận được phản hồi sớm nhất có thể, nhưng chậm nhất là vào thứ Hai, ngày 8 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you for your assistance.\", \"vi\": \"Xin chân thành cảm ơn sự hỗ trợ của quý vị.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = 'a819847e-1046-4023-867a-d5b81ad2f8ff';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"For immediate release - Contact: Desmond Hawkes, Office of Public Relations\\nTelephone: (02) 5555 6506\\nE-mail: dhawkes@carlisle.org.au\", \"vi\": \"Để công bố ngay lập tức – Liên hệ: Desmond Hawkes, Văn phòng Quan hệ Công chúng\\nĐiện thoại: (02) 5555 6506\\nE-mail: dhawkes@carlisle.org.au\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"New Exhibition at Sydney\'s\", \"vi\": \"Triển lãm mới tại Sydney\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Carlisle Art Museum\", \"vi\": \"Bảo tàng Mỹ thuật Carlisle\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"SYDNEY (3 June)—The Carlisle Art Museum\'s latest exhibition, Deep Waters, will open on 15 June.\", \"vi\": \"SYDNEY (ngày 3 tháng 6) — Triển lãm mới nhất của Bảo tàng Nghệ thuật Carlisle, mang tên “Deep Waters”, sẽ khai mạc vào ngày 15 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The exhibition will feature 38 realist and abstract paintings portraying the beauty and vastness of the world\'s oceans.\", \"vi\": \"Triển lãm sẽ trưng bày 38 tác phẩm hội họa theo trường phái hiện thực và trừu tượng, khắc họa vẻ đẹp và sự bao la của các đại dương trên thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"All the works were created by Australian artists based in Sydney, and among them will be six by the critically acclaimed oil painter Harold Bernstein.\", \"vi\": \"Tất cả các tác phẩm đều do các nghệ sĩ người Úc đang sinh sống tại Sydney sáng tác, trong đó có sáu tác phẩm của họa sĩ sơn dầu Harold Bernstein – người đã nhận được nhiều lời khen ngợi từ giới phê bình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The exhibition will run until 15 July.\", \"vi\": \"Triển lãm sẽ diễn ra đến ngày 15 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Tickets are $10.\", \"vi\": \"Giá vé là 10 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Museum visitors may view the exhibition between 9 A.M. and 4 P.M. on Tuesdays, Wednesdays, and Thursdays, and between 2 P.M. and 9 P.M. on Fridays and Saturdays.\", \"vi\": \"Khách tham quan bảo tàng có thể đến xem triển lãm từ 9 giờ sáng đến 4 giờ chiều vào các ngày Thứ Ba, Thứ Tư và Thứ Năm, và từ 2 giờ chiều đến 9 giờ tối vào các ngày Thứ Sáu và Thứ Bảy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"On each day of the exhibition, at least one of the artists will be present and available to answer visitors\' questions about the creative process.\", \"vi\": \"Trong mỗi ngày diễn ra triển lãm, sẽ có ít nhất một nghệ sĩ có mặt và sẵn sàng giải đáp các thắc mắc của quý khách tham quan về quá trình sáng tạo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Mr. Bernstein will be available on 30 June only.\", \"vi\": \"Ông Bernstein sẽ chỉ có mặt vào ngày 30 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"On 23 July, the exhibition will open at the Muriel Art Gallery in Melbourne, where ocean-themed paintings from Melbourne artists will be added to the collection.\", \"vi\": \"Vào ngày 23 tháng 7, triển lãm sẽ chính thức khai mạc tại Phòng trưng bày Nghệ thuật Muriel ở Melbourne, nơi các tác phẩm hội họa lấy chủ đề đại dương của các họa sĩ Melbourne sẽ được bổ sung vào bộ sưu tập.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = 'a848631c-3a9b-49ae-9914-07b175221503';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Morlon Home Goods Set to Open\", \"vi\": \"Cửa hàng Đồ dùng Gia đình Morlon chuẩn bị khai trương\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Article\", \"vi\": \"Bài viết\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"TISDALE (2 April)—Morlon Home Goods will open this Friday in a 130 square meter space on Waverly Road that was formerly — [143] — by Binkley\'s Market.\", \"vi\": \"TISDALE (Ngày 2 tháng 4)—Cửa hàng Đồ dùng Gia đình Morlon sẽ khai trương vào thứ Sáu này tại không gian rộng 130 mét vuông trên đường Waverly, nơi trước đây từng — [143] — bởi Chợ Binkley\'s.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [143]}, {\"en\": \"The store features home décor items, such as lamps, wall art, and small furniture from around the globe, all at affordable prices.\", \"vi\": \"Cửa hàng cung cấp các mặt hàng trang trí nhà cửa, chẳng hạn như đèn, tranh treo tường và đồ nội thất nhỏ từ khắp nơi trên thế giới, tất cả đều với mức giá phải chăng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"Morlon has a great variety of attractive items for the modern home.\", \"vi\": \"\\\"Morlon có rất nhiều mặt hàng hấp dẫn dành cho ngôi nhà hiện đại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Our inventory changes — [144] —.\", \"vi\": \"Hàng hóa của chúng tôi thay đổi — [144] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [144]}, {\"en\": \"Patrons like to stop in often to see what is new,\\\" said Naoko Sasaki, the chain\'s marketing director.\", \"vi\": \"Khách hàng thường thích ghé vào thường xuyên để xem có gì mới,\\\" Naoko Sasaki, giám đốc tiếp thị của chuỗi cửa hàng cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This is the first Morlon in the local area.\", \"vi\": \"Đây là cửa hàng Morlon đầu tiên tại khu vực địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [145] —.\", \"vi\": \"— [145] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [145]}, {\"en\": \"A grand opening — [146] — featuring free food, giveaways, and discount coupons will be held on Saturday, 13 April from 10:00 A.M. to 6:00 P.M.\", \"vi\": \"Lễ khai trương lớn — [146] — bao gồm đồ ăn miễn phí, quà tặng và phiếu giảm giá sẽ được tổ chức vào thứ Bảy, ngày 13 tháng 4 từ 10:00 sáng đến 6:00 chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [146]}]' WHERE `id` = 'a8a59ce6-5565-49dc-9637-b70d4fe87411';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"FGJ\'s\", \"vi\": \"FGJ\'s\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"FGJ\'s Business Expert Series\", \"vi\": \"Chuỗi bài viết về Chuyên gia Kinh doanh của FGJ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Prospect Data Purchasing\", \"vi\": \"Việc mua dữ liệu khách hàng tiềm năng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"45-Minute Webinar\", \"vi\": \"Hội thảo trực tuyến kéo dài 45 phút\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"11 May, 2:30 P.M.\", \"vi\": \"Ngày 11 tháng 5, 2 giờ 30 chiều\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Every department in an organisation needs information to make business decisions.\", \"vi\": \"Mỗi bộ phận trong một tổ chức đều cần thông tin để đưa ra các quyết định kinh doanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Marketing professionals in particular rely on accurate data about potential customers to be successful.\", \"vi\": \"Đặc biệt, các chuyên gia tiếp thị cần dựa vào dữ liệu chính xác về khách hàng tiềm năng để đạt được thành công.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In this Webinar, Briana Carrera, chief financial officer of Pile One Market Data, explains how to avoid the pitfalls of acquiring incomplete data and provides tips on what to ask your prospective data provider to ensure that your next batch of data leads to the results you want.\", \"vi\": \"Trong buổi hội thảo trực tuyến này, bà Briana Carrera, Giám đốc Tài chính của Pile One Market Data, sẽ giải thích cách tránh những rủi ro khi thu thập dữ liệu không đầy đủ và đưa ra những lời khuyên về những câu hỏi cần đặt ra cho nhà cung cấp dữ liệu tiềm năng nhằm đảm bảo rằng đợt dữ liệu tiếp theo của quý vị sẽ mang lại kết quả như mong muốn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"To: Sandra Lescure\", \"vi\": \"Gửi: Sandra Lescure\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"From: Gino Stelleti\", \"vi\": \"Từ: Gino Stelleti\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Date: 12 May\", \"vi\": \"Ngày: 12 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Subject: FGJ\'s Webinar\", \"vi\": \"Chủ đề: Hội thảo trực tuyến của FGJ\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Dear Sandra,\", \"vi\": \"Kính gửi bà Sandra,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"You had asked me to give you a report on the Webinar I attended yesterday about acquiring data.\", \"vi\": \"Quý vị đã yêu cầu tôi trình bày báo cáo về buổi hội thảo trực tuyến mà tôi đã tham dự hôm qua, liên quan đến việc thu thập dữ liệu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To be honest, even though the facilitator was clearly knowledgeable, she did not tell me anything I didn\'t already know.\", \"vi\": \"Thành thật mà nói, mặc dù người điều phối rõ ràng là rất am hiểu về chủ đề này, nhưng cô ấy không chia sẻ với tôi bất kỳ thông tin nào mà tôi chưa biết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I was hoping that she would show us the differences between the many types of databases out there, but she never touched on that topic.\", \"vi\": \"Tôi đã hy vọng rằng cô ấy sẽ chỉ cho chúng tôi thấy sự khác biệt giữa các loại cơ sở dữ liệu hiện có, nhưng cô ấy lại không hề đề cập đến chủ đề đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I am not so sure all these Webinars are useful; in the end, they always seem to be steering us to purchase from one particular company or another—in this case it was Pile One.\", \"vi\": \"Tôi không chắc lắm rằng tất cả các buổi hội thảo trực tuyến này đều hữu ích; xét cho cùng, dường như chúng luôn hướng chúng ta đến việc mua hàng từ một công ty cụ thể nào đó — trong trường hợp này là Pile One.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Having said that, the new schedule just came out, and there is another Webinar coming up soon that I am hoping will provide the information I want about how to store and sort data.\", \"vi\": \"Dù vậy, lịch trình mới vừa được công bố, và sắp tới sẽ có một buổi hội thảo trực tuyến khác mà tôi hy vọng sẽ cung cấp những thông tin mà tôi cần về cách lưu trữ và sắp xếp dữ liệu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I have already signed up for it; I will keep you posted about what I learn.\", \"vi\": \"Tôi đã đăng ký tham gia chương trình này rồi; tôi sẽ thường xuyên cập nhật cho quý vị những điều tôi học được.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Gino\", \"vi\": \"Gino\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Basics of Market Research - 1 June, 9:30 A.M. - Ed Quinones - €12.00\", \"vi\": \"Những kiến thức cơ bản về nghiên cứu thị trường - Ngày 1 tháng 6, 9 giờ 30 sáng - Ed Quinones - 12,00 €\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Tips for Accelerating Sales - 12 June, 9:30 A.M. - Cameron Stone - €16.00\", \"vi\": \"Các bí quyết giúp thúc đẩy doanh số bán hàng - Ngày 12 tháng 6, 9 giờ 30 sáng - Cameron Stone - 16,00 €\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"What is Market Automation? - 5 July, 11:00 A.M. - Ed Quinones - €12.00\", \"vi\": \"Tự động hóa thị trường là gì? - Ngày 5 tháng 7, 11:00 sáng - Ed Quinones - 12,00 €\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Choosing the Right Database - 17 July, 2:00 P.M. - Selina Tucci - €12.00\", \"vi\": \"Lựa chọn cơ sở dữ liệu phù hợp - Ngày 17 tháng 7, 2 giờ chiều - Selina Tucci - 12,00 €\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"FGJ\'s\", \"vi\": \"FGJ\'s\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Upcoming 45-Minute Webinars in FGJ\'s Business Expert Series\", \"vi\": \"Các buổi hội thảo trực tuyến kéo dài 45 phút sắp diễn ra trong chuỗi chương trình “Chuyên gia kinh doanh” của FGJ\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"The Business Expert Series is organised by Tuyet Nguyen.\", \"vi\": \"Chuỗi sự kiện “Chuyên gia kinh doanh” do bà Tuyết Nguyễn tổ chức.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Please address any questions to her at tnguyen@fgj.org.\", \"vi\": \"Mọi thắc mắc xin vui lòng gửi đến cô ấy qua địa chỉ email tnguyen@fgj.org.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"To access Webinar content, attendance is required as Webinars are not recorded for later viewing.\", \"vi\": \"Để truy cập nội dung hội thảo trực tuyến, quý vị bắt buộc phải tham dự vì các hội thảo này sẽ không được ghi lại để xem lại sau này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}]' WHERE `id` = 'a8ae1643-b077-494f-9f17-dcba3deeb49e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Spotlight on Carl Ybor\", \"vi\": \"Giới thiệu về Carl Ybor\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"GORE, New Zealand (2 May)—Architect Carl Ybor has created a name for himself by helping clients turn their trash into treasure.\", \"vi\": \"GORE, New Zealand (ngày 2 tháng 5) — Kiến trúc sư Carl Ybor đã tạo dựng được danh tiếng nhờ giúp các khách hàng biến rác thải thành những món đồ quý giá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"He has built dozens of houses in Gore composed almost entirely of reclaimed, recovered, or found materials.\", \"vi\": \"Ông đã xây dựng hàng chục ngôi nhà tại Gore, hầu như hoàn toàn bằng các vật liệu tái chế, thu hồi hoặc nhặt được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"\\\"As much as possible, I like to use materials that are already available nearby,\\\" says Mr. Ybor.\", \"vi\": \"\\\"Tôi thích sử dụng những nguyên liệu sẵn có ở gần nhất có thể,\\\" ông Ybor chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"It just takes some creativity, but that way nothing is wasted and houses can be built for a fraction of the price.\", \"vi\": \"\\\"Chỉ cần một chút sáng tạo là đủ, nhưng nhờ vậy mà không có gì bị lãng phí và các ngôi nhà có thể được xây dựng với chi phí chỉ bằng một phần nhỏ so với thông thường.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Old fencing, discarded bottles, corks, mismatched bricks and tiles—nothing gets overlooked.\\\"\", \"vi\": \"Hàng rào cũ, chai lọ bỏ đi, nút chai, gạch và ngói không đồng bộ — không có thứ gì bị bỏ sót cả.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"While Mr. Ybor is fully responsible for creating the design plans for the houses he builds, he always involves homeowners in the building process.\", \"vi\": \"Mặc dù ông Ybor hoàn toàn chịu trách nhiệm về việc lập các bản thiết kế cho những ngôi nhà mà ông xây dựng, nhưng ông luôn tạo điều kiện để các chủ nhà tham gia vào quá trình xây dựng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"With a waiting list of at least a year, Mr. Ybor is able to carefully select his clients.\", \"vi\": \"Với danh sách chờ kéo dài ít nhất một năm, ông Ybor có thể lựa chọn khách hàng của mình một cách kỹ lưỡng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"He works solely with homeowners who already know how to operate power tools and are willing to do some of the hands-on work themselves.\", \"vi\": \"Ông chỉ làm việc với những chủ nhà đã biết cách sử dụng các dụng cụ điện và sẵn sàng tự tay thực hiện một số công việc thực tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Some of his houses have been featured in magazines, travel shows, and online carpentry demonstrations.\", \"vi\": \"Một số ngôi nhà do ông thiết kế đã được giới thiệu trên các tạp chí, chương trình du lịch và các video hướng dẫn nghề mộc trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Mr. Ybor\'s Web site, featuring photos of his projects, can be found at yborhabitats.co.nz.\", \"vi\": \"Trang web của ông Ybor, nơi giới thiệu các hình ảnh về các dự án của ông, có thể truy cập tại địa chỉ yborhabitats.co.nz.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To: contact@yborhabitats.co.nz\", \"vi\": \"Gửi tới: contact@yborhabitats.co.nz\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"From: c.holmes@hmail.net\", \"vi\": \"Nguồn: c.holmes@hmail.net\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Date: 4 May\", \"vi\": \"Ngày: 4 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Subject: Proposal\", \"vi\": \"Chủ đề: Đề xuất\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dear Mr. Ybor,\", \"vi\": \"Kính gửi ông Ybor,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I just read an article about you.\", \"vi\": \"Tôi vừa đọc một bài báo nói về quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I was excited to learn about your services and how you work with the owners to create unique spaces.\", \"vi\": \"Tôi rất hào hứng khi được tìm hiểu về các dịch vụ của quý công ty cũng như cách quý công ty hợp tác với các chủ nhà để tạo ra những không gian độc đáo.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I have two projects I want to work on:\", \"vi\": \"Tôi có hai dự án mà tôi muốn thực hiện:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I want to add an extension to my current house, incorporating leftover materials I have from the patio that I had built a few years ago.\", \"vi\": \"Tôi muốn mở rộng ngôi nhà hiện tại của mình, đồng thời tận dụng những vật liệu còn thừa từ khu sân hiên mà tôi đã cho xây dựng cách đây vài năm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"My roof needs to be replaced.\", \"vi\": \"Mái nhà của tôi cần phải được thay mới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I have researched ways to cut the cost, and one suggestion was to leave the existing roof intact and just install new metal sheeting on top.\", \"vi\": \"Tôi đã tìm hiểu các phương án nhằm cắt giảm chi phí, và một trong những đề xuất là giữ nguyên phần mái hiện có và chỉ lắp đặt tấm kim loại mới lên trên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I like this idea!\", \"vi\": \"Tôi rất thích ý tưởng này!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Are you available and interested in doing this work?\", \"vi\": \"Quý vị có thời gian và quan tâm đến công việc này không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I would like to start as early as next month.\", \"vi\": \"Tôi mong muốn có thể bắt đầu ngay từ tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"I can pay half the money up front by credit card to secure an appointment.\", \"vi\": \"Tôi có thể thanh toán trước một nửa số tiền bằng thẻ tín dụng để đảm bảo có được lịch hẹn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Cynthia Holmes\", \"vi\": \"Cynthia Holmes\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = 'a8cd0522-9bfb-4d46-903d-025e84e69811';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"DALLAS (July 28)—Zura Technology Solutions (ZTS) announced today that it has completed the ___143___ of an office building located at 425 Van Kirk Street here in Dallas.\", \"vi\": \"DALLAS (28 tháng 7)—Zura Technology Solutions (ZTS) hôm nay đã thông báo rằng họ đã hoàn tất việc ___143___ một tòa nhà văn phòng tọa lạc tại số 425 phố Van Kirk tại Dallas này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [143]}, {\"en\": \"The building, most recently the headquarters of Brickhall Insurance, will serve as ZTS\'s ___144___ base of operations.\", \"vi\": \"Tòa nhà này, trước đây gần đây nhất là trụ sở chính của Brickhall Insurance, sẽ đóng vai trò là cơ sở hoạt động ___144___ của ZTS.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [144]}, {\"en\": \"The company\'s relocation from Fort Worth is expected to be complete by the end of the calendar year.\", \"vi\": \"Việc dời trụ sở của công ty từ Fort Worth dự kiến sẽ hoàn tất trước khi kết thúc năm dương lịch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"___145___ .\", \"vi\": \"___145___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [145]}, {\"en\": \"\\\"Our decision to acquire the building reflects ZTS\'s ongoing commitment to the Dallas area and will enable us to better serve our customers, business partners, and stakeholders,\\\" said Gloria Rubirosa, ZTS\'s CEO.\", \"vi\": \"\\\"Quyết định mua lại tòa nhà này phản ánh cam kết lâu dài của ZTS đối với khu vực Dallas và sẽ cho phép chúng tôi phục vụ tốt hơn các khách hàng, đối tác kinh doanh và các bên liên quan của mình,\\\" Gloria Rubirosa, Giám đốc điều hành của ZTS, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"\\\"From our new home in Dallas, we ___146___ to work hard to meet the needs of each and every one of our customers around the world.\\\"\", \"vi\": \"\\\"Từ ngôi nhà mới của chúng tôi tại Dallas, chúng tôi ___146___ nỗ lực làm việc để đáp ứng nhu cầu của từng khách hàng của chúng tôi trên toàn thế giới.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [146]}]' WHERE `id` = 'a951d49b-cfbe-4747-9bbd-ba1c6d96a422';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ticket Types - Price - Provides\", \"vi\": \"Các loại vé - Giá vé - Dịch vụ cung cấp\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Saver - €5.00 - Provides access to the palace grounds\", \"vi\": \"Gói Saver - 5,00 € - Cho phép quý vị vào khuôn viên cung điện\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Standard - €12.00 - Provides Saver access AND audio tour of select first-floor rooms\", \"vi\": \"Gói Tiêu chuẩn - 12,00 € - Bao gồm quyền vào cửa theo chương trình Saver VÀ tour hướng dẫn bằng âm thanh tại một số phòng chọn lọc ở tầng một\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Plus - €20.00 - Provides Standard access AND admission to the special exhibitions hall\", \"vi\": \"Gói Plus - 20,00 € - Bao gồm quyền truy cập theo gói Standard VÀ vé vào cửa khu triển lãm đặc biệt\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Premium - €27.00 - Provides Plus access AND guided tour of select rooms on upper floors\", \"vi\": \"Gói Premium - 27,00 € - Bao gồm quyền truy cập gói Plus VÀ chuyến tham quan có hướng dẫn viên tại một số phòng được lựa chọn ở các tầng trên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"✢ Albrecht Palace\", \"vi\": \"✢ Cung điện Albrecht\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Information for Visitors\", \"vi\": \"Thông tin dành cho quý khách tham quan\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"An elegant example of seventeenth-century Saxony architecture surrounded by beautiful gardens, Albrecht Palace is open from 10 A.M. to 5 P.M. every day except Mondays and holidays.\", \"vi\": \"Là một ví dụ tiêu biểu về kiến trúc Saxony thế kỷ XVII, được bao quanh bởi những khu vườn tuyệt đẹp, Cung điện Albrecht mở cửa từ 10 giờ sáng đến 5 giờ chiều hàng ngày, trừ thứ Hai và các ngày lễ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"It is roughly twenty minutes from the city of Dresden by intercity bus.\", \"vi\": \"Từ thành phố Dresden đi bằng xe buýt liên tỉnh thì mất khoảng hai mươi phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Drivers should leave their cars in the nearby town of Possendorf and take the shuttle bus that leaves from Hotel Oelsa.\", \"vi\": \"Quý vị lái xe nên đỗ xe tại thị trấn Possendorf gần đó và đi xe buýt đưa đón khởi hành từ Khách sạn Oelsa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Upcoming Special Exhibitions:\", \"vi\": \"Các triển lãm đặc biệt sắp tới:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Saxon Style: Local Clothing over Time (1 April – 31 May)\", \"vi\": \"Phong cách Saxon: Trang phục địa phương qua các thời kỳ (1 tháng 4 – 31 tháng 5)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Royal Faces: Oil Portraits of Albrecht\'s Rulers (1 June – 31 July)\", \"vi\": \"Những gương mặt hoàng gia: Các bức chân dung sơn dầu về các vị quân vương của Albrecht (từ ngày 1 tháng 6 đến ngày 31 tháng 7)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"On the Table: 17th-Century Saxon Cuisine (1 August – 30 September)\", \"vi\": \"Trên bàn ăn: Ẩm thực Saxon thế kỷ 17 (từ ngày 1 tháng 8 đến ngày 30 tháng 9)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Hooved Friends: Horses at Albrecht (1 October – 30 November)\", \"vi\": \"Những người bạn có móng guốc: Những chú ngựa tại Albrecht (từ ngày 1 tháng 10 đến ngày 30 tháng 11)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"To: visitor.info@albrechtpalace.de\", \"vi\": \"Gửi tới: visitor.info@albrechtpalace.de\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"From: n.romero@etn.eu\", \"vi\": \"Nguồn: n.romero@etn.eu\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date: 4 January\", \"vi\": \"Ngày: 4 tháng 1\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Subject: Inquiry\", \"vi\": \"Chủ đề: Yêu cầu thông tin\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Hello,\", \"vi\": \"Xin chào\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"My name is Naomi Romero, and I work for the European Textile Network (ETN).\", \"vi\": \"Tên tôi là Naomi Romero, và tôi đang làm việc tại Mạng lưới Dệt may Châu Âu (ETN).\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"The ETN aims to advance the expertise of Europe\'s textile industry professionals by providing them with education and networking opportunities.\", \"vi\": \"ETN hướng đến mục tiêu nâng cao trình độ chuyên môn cho các chuyên gia trong ngành dệt may châu Âu thông qua việc cung cấp cho họ các cơ hội đào tạo và kết nối.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"This year, our annual conference will take place in Dresden on 21–24 May, and we hope to offer attendees an excursion to Albrecht Palace.\", \"vi\": \"Năm nay, hội nghị thường niên của chúng tôi sẽ diễn ra tại Dresden từ ngày 21 đến ngày 24 tháng 5, và chúng tôi hy vọng sẽ tổ chức một chuyến tham quan đến Cung điện Albrecht dành cho quý vị tham dự.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"They would enjoy the special exhibition that will be running then.\", \"vi\": \"Họ sẽ có dịp thưởng thức triển lãm đặc biệt sẽ diễn ra vào thời điểm đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"But—do you allow large groups to join the guided tours?\", \"vi\": \"Tuy nhiên—liệu quý vị có cho phép các đoàn khách đông người tham gia các tour du lịch có hướng dẫn viên không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"We would really like participants to be able to see the famous tapestries and bed coverings in the rooms on the upper floors.\", \"vi\": \"Chúng tôi thực sự mong muốn các vị tham dự có thể chiêm ngưỡng những tấm thảm dệt và khăn trải giường nổi tiếng trong các phòng ở các tầng trên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"We will limit the number of excursion participants, if necessary, to make this possible.\", \"vi\": \"Chúng tôi sẽ hạn chế số lượng người tham gia chuyến tham quan, nếu cần thiết, để đảm bảo việc này có thể diễn ra.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"I hope to hear from you soon.\", \"vi\": \"Tôi hy vọng sẽ sớm nhận được tin từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Naomi Romero\", \"vi\": \"Naomi Romero\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Coordinator, ETN\", \"vi\": \"Điều phối viên, ETN\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}]' WHERE `id` = 'a987d565-50ba-44c3-a8a7-6f1cab73446e';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Junior Project Manager\", \"vi\": \"Quản lý dự án cấp dưới\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Traskin Public Relations\", \"vi\": \"Công ty Quan hệ Công chúng Traskin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Seattle, WA\", \"vi\": \"Seattle, bang Washington\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Traskin Public Relations is a marketing and public relations firm focusing on the hospitality industry.\", \"vi\": \"Traskin Public Relations là một công ty chuyên về tiếp thị và quan hệ công chúng, tập trung vào lĩnh vực khách sạn và nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We are based in Seattle and have been in business for more than twenty years.\", \"vi\": \"Công ty chúng tôi có trụ sở tại Seattle và đã hoạt động trong lĩnh vực này hơn hai mươi năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"To keep up with our recent rapid expansion, Traskin is now seeking a new junior project manager.\", \"vi\": \"Để đáp ứng tốc độ mở rộng nhanh chóng gần đây của công ty, Traskin hiện đang tìm kiếm một quản lý dự án cấp dưới mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This is an opportunity to be trained in valuable strategic and creative processes.\", \"vi\": \"Đây là cơ hội để quý vị được đào tạo về các quy trình chiến lược và sáng tạo vô cùng quý giá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This training program served as the starting point for several of our current senior project managers.\", \"vi\": \"Chương trình đào tạo này đã trở thành bước khởi đầu cho nhiều quản lý dự án cấp cao hiện tại của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Traskin offers all employees competitive compensation and benefits.\", \"vi\": \"Traskin mang đến cho tất cả nhân viên chế độ đãi ngộ và phúc lợi cạnh tranh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Responsibilities include coordinating with managers and clients, scheduling meetings and presentations, and managing budgets.\", \"vi\": \"Các nhiệm vụ bao gồm phối hợp với các nhà quản lý và khách hàng, lên lịch các cuộc họp và buổi thuyết trình, cũng như quản lý ngân sách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Additionally, the successful applicant will create weekly e-mail updates for internal teammates and clients.\", \"vi\": \"Ngoài ra, ứng viên trúng tuyển sẽ soạn thảo các bản cập nhật qua email hàng tuần dành cho các đồng nghiệp trong nội bộ và khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Qualifications include a minimum of two years\' management experience at a similar agency, knowledge of project management software, and excellent organizational skills.\", \"vi\": \"Các yêu cầu về trình độ bao gồm ít nhất hai năm kinh nghiệm quản lý tại một cơ quan tương tự, có kiến thức về phần mềm quản lý dự án và kỹ năng tổ chức xuất sắc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Upload résumé and cover letter to careers@traskinpr.com.\", \"vi\": \"Vui lòng gửi sơ yếu lý lịch và thư xin việc đến địa chỉ careers@traskinpr.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}]' WHERE `id` = 'a9ad07d8-906e-45f4-8100-31519553f320';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Niran Chaiya\", \"vi\": \"Từ: Niran Chaiya\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Rebecca Briggs\", \"vi\": \"Kính gửi: Rebecca Briggs\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: January 25\", \"vi\": \"Ngày: 25 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: List\", \"vi\": \"Tài liệu đính kèm: Danh sách\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Briggs,\", \"vi\": \"Kính gửi bà Briggs,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As I promised in our phone conversation, attached you will find a list of available houses and apartments in Bangkok.\", \"vi\": \"Như tôi đã hứa trong cuộc trò chuyện qua điện thoại của chúng ta, xin gửi kèm theo đây danh sách các căn nhà và căn hộ hiện có sẵn tại Bangkok.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"All of the properties fit the criteria you provided and are priced within your company\'s rental allowance for relocated executives.\", \"vi\": \"Tất cả các bất động sản này đều đáp ứng các tiêu chí mà quý vị đã đưa ra và có mức giá nằm trong phạm vi khoản trợ cấp thuê nhà mà công ty quý vị quy định dành cho các cán bộ quản lý được điều chuyển công tác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I have included details such as square footage and amenities, as well as interior photos and neighborhood maps.\", \"vi\": \"Tôi đã cung cấp các thông tin chi tiết như diện tích tính theo đơn vị vuông và các tiện nghi, cũng như hình ảnh nội thất và bản đồ khu vực lân cận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please review the list and tell me which property you prefer so that I can begin preparing the necessary paperwork.\", \"vi\": \"Kính mong Quý vị xem xét danh sách và cho tôi biết Quý vị ưa thích bất động sản nào để tôi có thể bắt đầu chuẩn bị các thủ tục giấy tờ cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Some of these places are quite desirable, so I recommend acting quickly.\", \"vi\": \"Một số địa điểm trong số này thực sự rất hấp dẫn, vì vậy tôi khuyên quý vị nên hành động nhanh chóng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please call me if any questions come up.\", \"vi\": \"Nếu có bất kỳ thắc mắc nào, xin vui lòng gọi điện cho tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Niran Chaiya\", \"vi\": \"Họ là Chaiya\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Corporate Relocation Specialist\", \"vi\": \"Chuyên gia về di dời doanh nghiệp\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Chao Phraya Services\", \"vi\": \"Dịch vụ Chao Phraya\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = 'a9d7b320-5eef-45cc-b349-6e34eafc3a40';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Ronald Garrison\", \"vi\": \"Từ: Ronald Garrison\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: April 20\", \"vi\": \"Ngày: 20 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Update\", \"vi\": \"Chủ đề: Cập nhật\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Colleagues,\", \"vi\": \"Kính gửi các đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"It’s an exciting time here at Zikomo Solutions, and we have a lot to celebrate!\", \"vi\": \"Đây quả là một thời điểm đầy hứng khởi tại Zikomo Solutions, và chúng tôi có rất nhiều điều để ăn mừng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Our company has shown tremendous growth over the past year.\", \"vi\": \"Trong năm qua, công ty chúng tôi đã đạt được sự tăng trưởng vượt bậc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Just last month we exceeded our goals and conducted 25 customer service workshops for 18 different companies in the greater Groton area.\", \"vi\": \"Chỉ trong tháng vừa qua, chúng tôi đã vượt chỉ tiêu và tổ chức 25 hội thảo về dịch vụ khách hàng cho 18 công ty khác nhau tại khu vực Groton và các vùng lân cận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In response to our growth, we have added three new workshop presenters with significant customer service experience in their respective industries.\", \"vi\": \"Để đáp ứng sự phát triển của công ty, chúng tôi đã bổ sung ba giảng viên mới cho các khóa đào tạo, những người đều có kinh nghiệm dày dặn trong lĩnh vực dịch vụ khách hàng tại các ngành nghề tương ứng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Lisa Okoro will focus on the telemarketing industry.\", \"vi\": \"Bà Lisa Okoro sẽ tập trung vào ngành tiếp thị qua điện thoại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Caleb Patel will train those in fields related to medicine.\", \"vi\": \"Ông Caleb Patel sẽ đào tạo những người làm việc trong các lĩnh vực liên quan đến y học.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"And Alan Gorospe will specialize mainly in customer service for the technology industry.\", \"vi\": \"Và ông Alan Gorospe sẽ chủ yếu chuyên trách mảng dịch vụ khách hàng trong ngành công nghệ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"They will begin giving workshops during the first or second week of May.\", \"vi\": \"Họ sẽ bắt đầu tổ chức các buổi hội thảo vào tuần đầu tiên hoặc tuần thứ hai của tháng Năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please join me in welcoming these professionals to the Zikomo family.\", \"vi\": \"Kính mời quý vị cùng tôi chào đón các chuyên gia này gia nhập đại gia đình Zikomo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Ronald Garrison\", \"vi\": \"Ronald Garrison\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"CEO, Zikomo Solutions\", \"vi\": \"Giám đốc điều hành, Zikomo Solutions\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Course Name - Course Length - Date - Trainer - Location\", \"vi\": \"Tên khóa học - Thời lượng khóa học - Ngày - Giảng viên - Địa điểm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Telephone Skills - Half Day - May 2 - Lisa Okoro - Zikomo, Groton\", \"vi\": \"Kỹ năng giao tiếp qua điện thoại - Nửa ngày - Ngày 2 tháng 5 - Lisa Okoro - Zikomo, Groton\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Customer Service in a Digital World - Full Day - May 3 - Alan Gorospe - Zikomo, Groton\", \"vi\": \"Dịch vụ khách hàng trong thế giới số - Khóa học cả ngày - Ngày 3 tháng 5 - Alan Gorospe - Zikomo, Groton\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Patient Relations for Hospital Professionals - Full Day - May 4 - To Be Determined - Fitzer Medical Group, West Groton\", \"vi\": \"Khóa đào tạo về Quan hệ với bệnh nhân dành cho các chuyên gia y tế tại bệnh viện – Cả ngày – Ngày 4 tháng 5 – Thời gian cụ thể sẽ được thông báo sau – Fitzer Medical Group, West Groton\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Turn Tech Problems into Marketing Opportunities - Half Day - May 5 - Alan Gorospe - Callipher Technologies, Fayetteville\", \"vi\": \"Biến các vấn đề công nghệ thành cơ hội tiếp thị - Chương trình nửa ngày - Ngày 5 tháng 5 - Alan Gorospe - Callipher Technologies, Fayetteville\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Zikomo Solutions\", \"vi\": \"Zikomo Solutions\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Tentative training schedule\", \"vi\": \"Lịch tập luyện dự kiến\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Week of May 2\", \"vi\": \"Tuần từ ngày 2 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"To: Ronald Garrison <rgarrison@zikomosolutions.net>\", \"vi\": \"Gửi tới: Ronald Garrison <rgarrison@zikomosolutions.net>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"From: Jana Snyder <jsnyder@snyder.com>\", \"vi\": \"Từ: Jana Snyder <jsnyder@snyder.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date: May 8\", \"vi\": \"Ngày: 8 tháng 5\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Subject: Recent workshops\", \"vi\": \"Chủ đề: Các hội thảo gần đây\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Dear Mr. Garrison,\", \"vi\": \"Kính gửi ông Garrison,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Several of my employees from Snyder Goods attended Zikomo training sessions on May 2 and 3.\", \"vi\": \"Một số nhân viên của tôi tại Snyder Goods đã tham dự các buổi đào tạo của Zikomo vào ngày 2 và 3 tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I wanted to provide feedback and ask a question.\", \"vi\": \"Tôi muốn đóng góp ý kiến và đặt một câu hỏi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"I think the half-day session could be extended to a full day, considering the interesting topic and skill of the excellent presenter.\", \"vi\": \"Tôi cho rằng buổi hội thảo kéo dài nửa ngày này có thể được kéo dài thành một ngày đầy đủ, xét đến chủ đề thú vị và trình độ chuyên môn xuất sắc của diễn giả.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Conversely, the full day, while interesting, would be better condensed into a half day.\", \"vi\": \"Ngược lại, chương trình kéo dài cả ngày, dù rất thú vị, nhưng sẽ tốt hơn nếu được rút gọn lại thành nửa ngày.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Additionally, could you provide more parking options?\", \"vi\": \"Ngoài ra, quý vị có thể cung cấp thêm các lựa chọn đỗ xe được không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Spaces for participants were full, and a number of our Snyder Goods employees had to park in an expensive paid lot.\", \"vi\": \"Các chỗ đỗ xe dành cho người tham dự đã kín chỗ, và một số nhân viên của Snyder Goods đã phải đỗ xe tại một bãi đỗ xe thu phí đắt đỏ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Jana Snyder\", \"vi\": \"Jana Snyder\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Snyder Goods\", \"vi\": \"Sản phẩm Snyder\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}]' WHERE `id` = 'a9eae6e1-a33c-45f0-bb3c-3358feabcbb6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Sleepy Time Hotel <information@sleepytimehotel.com>\", \"vi\": \"Gửi tới: Khách sạn Sleepy Time <information@sleepytimehotel.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Jongwoo Cho <jongwoo.cho@onyxmail.com>\", \"vi\": \"From: Jongwoo Cho <jongwoo.cho@onyxmail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: August 15\", \"vi\": \"Ngày: 15 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: My hotel stay\", \"vi\": \"Chủ đề: Chuyến lưu trú tại khách sạn của tôi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Departs from Johnstown - Arrives in Charlesville\", \"vi\": \"Khởi hành từ Johnstown - Đến Charlesville\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"7:00 A.M. - 8:36 A.M.\", \"vi\": \"7 giờ sáng – 8 giờ 36 phút sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"10:05 A.M. - 11:41 A.M.\", \"vi\": \"10 giờ 05 phút sáng - 11 giờ 41 phút sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"1:00 P.M. - 2:36 P.M.\", \"vi\": \"13 giờ 00 – 14 giờ 36\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"4:05 P.M. - 5:41 P.M.\", \"vi\": \"16 giờ 05 phút - 17 giờ 41 phút\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"7:00 P.M. - 8:36 P.M.\", \"vi\": \"19 giờ 00 – 20 giờ 36\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Greetings!\", \"vi\": \"Xin chào!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I made an online booking for a two-night stay at your hotel for this upcoming Friday, August 19, but I cannot figure out how to get to the hotel once I\'m in Charlesville.\", \"vi\": \"Tôi đã đặt phòng trực tuyến để lưu trú hai đêm tại khách sạn của quý vị vào thứ Sáu tới, ngày 19 tháng 8, nhưng tôi không biết làm thế nào để đến được khách sạn sau khi đã đến Charlesville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I downloaded the City Link Line app as suggested on your Web site, but I am finding it difficult to navigate.\", \"vi\": \"Tôi đã tải xuống ứng dụng City Link Line theo gợi ý trên trang web của quý vị, nhưng tôi cảm thấy khó sử dụng ứng dụng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"No options are coming up for the Dalton light-rail station, which you specifically mention as the station where hotel guests should disembark.\", \"vi\": \"Hiện không có phương án nào được đề xuất cho ga tàu điện nhẹ Dalton, nơi mà quý vị đã đặc biệt đề cập là ga mà khách lưu trú tại khách sạn nên xuống tàu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Could you please clarify how best to get to the hotel?\", \"vi\": \"Xin quý vị vui lòng cho biết cách tốt nhất để đến khách sạn là như thế nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Judging from the pictures on the Web site, the hotel looks like a beautiful place to stay.\", \"vi\": \"Dựa vào những hình ảnh trên trang web, khách sạn này trông có vẻ là một nơi tuyệt đẹp để lưu trú.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I am looking forward to spending a couple of nights right by the beach.\", \"vi\": \"Tôi rất mong được dành vài đêm ngay bên bờ biển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Jongwoo Cho\", \"vi\": \"Jongwoo Cho\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"City Link Line\", \"vi\": \"Tuyến City Link\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Monday to Friday Schedule – Johnstown to Charlesville\", \"vi\": \"Lịch trình từ thứ Hai đến thứ Sáu – Tuyến Johnstown đến Charlesville\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"https://www.sleepytimehotel.com/reviews\", \"vi\": \"https://www.sleepytimehotel.com/reviews\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"My stay at the Sleepy Time Hotel was fantastic.\", \"vi\": \"Kỳ nghỉ của tôi tại Khách sạn Sleepy Time thật tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Initially, I was worried I could not get to the hotel easily from Johnstown, where I had just finished an exhilarating three-day professional conference.\", \"vi\": \"Ban đầu, tôi lo lắng rằng mình sẽ không thể di chuyển thuận tiện từ Johnstown – nơi tôi vừa kết thúc một hội nghị chuyên môn kéo dài ba ngày đầy hứng khởi – đến khách sạn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"The hotel Web site is not crystal clear about transportation options.\", \"vi\": \"Trang web của khách sạn không nêu rõ ràng về các phương án đi lại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Since I am not familiar with this part of the country, I e-mailed the hotel, and someone responded immediately.\", \"vi\": \"Vì tôi không quen thuộc với khu vực này của đất nước, nên tôi đã gửi email cho khách sạn, và ngay lập tức đã có người trả lời.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Ultimately, it was easy to get to Charlesville.\", \"vi\": \"Cuối cùng thì, việc đến Charlesville cũng không có gì khó khăn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"First, I took the 4:05 P.M. train out of Johnstown.\", \"vi\": \"Trước tiên, tôi đã đi chuyến tàu khởi hành lúc 4 giờ 05 phút chiều từ Johnstown.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Once I arrived at Charlesville Central Station, I rode the elevator to the basement, where the light-rail train platforms are located.\", \"vi\": \"Khi đến Ga Trung tâm Charlesville, tôi đi thang máy xuống tầng hầm, nơi có các sân ga của tuyến tàu điện nhẹ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I then boarded a light-rail train and rode it to the station directly across the street from the hotel.\", \"vi\": \"Sau đó, tôi lên một chuyến tàu điện nhẹ và đi đến ga nằm ngay bên kia đường so với khách sạn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Apparently, the Charlesville light-rail system is relatively new.\", \"vi\": \"Có vẻ như hệ thống tàu điện nhẹ Charlesville là một hệ thống tương đối mới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Keep in mind that there are no restaurants near the hotel, but there is a small grocery store around the corner.\", \"vi\": \"Xin lưu ý rằng không có nhà hàng nào gần khách sạn, nhưng có một cửa hàng tạp hóa nhỏ ngay góc phố.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"So I was able to purchase some food and have a picnic on the beach.\", \"vi\": \"Nhờ vậy, tôi đã có thể mua một ít thức ăn và tổ chức một buổi dã ngoại trên bãi biển.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Overall, this small hotel with lovely, bright rooms is a perfect escape from city life.\", \"vi\": \"Nhìn chung, khách sạn nhỏ này với những căn phòng xinh xắn và tràn ngập ánh sáng chính là nơi lý tưởng để quý vị tạm rời xa nhịp sống thành thị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"I felt so relaxed when I finally returned to my office and got back to work.\", \"vi\": \"Khi cuối cùng tôi cũng trở lại văn phòng và tiếp tục công việc, tôi cảm thấy vô cùng thoải mái.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Jongwoo Cho, posted on August 26\", \"vi\": \"Jongwoo Cho, đăng ngày 26 tháng 8\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}]' WHERE `id` = 'aa46154a-7f8a-48e8-a47e-80eb60ccaa71';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Most of the ______[139] to Zien Travel Quarterly are professional writers with whom we have an ongoing relationship.\", \"vi\": \"Hầu hết các ______[139] cho tạp chí Zien Travel Quarterly là những cây bút chuyên nghiệp mà chúng tôi có mối quan hệ hợp tác lâu dài.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": [139]}, {\"en\": \"______[140], we always like to encourage and support new talent.\", \"vi\": \"______[140], chúng tôi luôn muốn khuyến khích và hỗ trợ các tài năng mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [140]}, {\"en\": \"We try to include at least one article per issue from a new writer, but with just four issues a year, the opportunities for publication are quite limited.\", \"vi\": \"Chúng tôi cố gắng đưa vào ít nhất một bài viết mỗi số báo từ một tác giả mới, nhưng với chỉ bốn số mỗi năm, cơ hội được xuất bản là khá hạn chế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Before submitting an idea for publication, please read the guidelines at www.zientravel.com/writers, as they outline our specific areas of interest in detail.\", \"vi\": \"Trước khi gửi ý tưởng để xuất bản, vui lòng đọc các hướng dẫn tại www.zientravel.com/writers, vì chúng nêu chi tiết các lĩnh vực quan tâm cụ thể của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"______[141].\", \"vi\": \"______[141].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [141]}, {\"en\": \"Note that we aim to respond to all correspondence in a timely manner, but there may be times when we are slow to respond.\", \"vi\": \"Xin lưu ý rằng chúng tôi đặt mục tiêu phản hồi mọi thư từ một cách kịp thời, nhưng có thể có những lúc chúng tôi phản hồi chậm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"For this reason, we ask that you please be ______[142].\", \"vi\": \"Vì lý do này, chúng tôi mong bạn hãy ______[142].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [142]}]' WHERE `id` = 'aa48b532-c652-4f07-88cd-dc2f2445c014';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Creative Team\", \"vi\": \"Đến: Nhóm Sáng tạo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Camille Patel\", \"vi\": \"Từ: Camille Patel\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: December 9\", \"vi\": \"Ngày: 9 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Re: Colleague departure\", \"vi\": \"V/v: Đồng nghiệp nghỉ việc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Team Members,\", \"vi\": \"Kính gửi các thành viên trong nhóm,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As many of you have recently learned, Claudia Hoffman will end her tenure as art director on Monday, December 30.\", \"vi\": \"Như nhiều bạn đã biết gần đây, Claudia Hoffman sẽ kết thúc nhiệm kỳ giữ chức giám đốc nghệ thuật vào thứ Hai, ngày 30 tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"After ten years in this ------- (131), she will be taking on a new professional challenge in Paris.\", \"vi\": \"Sau mười năm ở vị trí ------- (131) này, cô ấy sẽ đảm nhận một thử thách nghề nghiệp mới tại Paris.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [131]}, {\"en\": \"------- (132), she will join the leadership team at a top advertising agency.\", \"vi\": \"------- (132), cô ấy sẽ gia nhập đội ngũ lãnh đạo tại một công ty quảng cáo hàng đầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [132]}, {\"en\": \"Marcos Molina from Spencer Design will become our new art director.\", \"vi\": \"Marcos Molina từ hãng Spencer Design sẽ trở thành giám đốc nghệ thuật mới của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"------- (133).\", \"vi\": \"------- (133).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [133]}, {\"en\": \"I would like to personally thank Ms. Hoffman for her tremendous leadership.\", \"vi\": \"Tôi muốn gửi lời cảm ơn cá nhân đến cô Hoffman vì sự lãnh đạo tuyệt vời của cô ấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"She ------- (134) a key factor in our agency\'s success.\", \"vi\": \"Cô ấy ------- (134) một nhân tố quan trọng trong thành công của công ty chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [134]}, {\"en\": \"Please join me in celebrating her achievements at a farewell dinner after work hours on Friday, December 27.\", \"vi\": \"Xin hãy cùng tôi chúc mừng những thành tựu của cô ấy tại một bữa tối chia tay sau giờ làm việc vào thứ Sáu, ngày 27 tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The details will be forthcoming.\", \"vi\": \"Chi tiết cụ thể sẽ được thông báo sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Camille Patel, Human Resources Officer\", \"vi\": \"Camille Patel, Cán bộ Nhân sự\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = 'aa58a01d-5793-41d0-8ce9-b940fb979cba';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"KINGSTON-GARNET ISLAND PASSENGER FERRY SERVICE\", \"vi\": \"DỊCH VỤ PHÀ CHỞ HÀNH KHÁCH GIỮA KINGSTON VÀ ĐẢO GARNET\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"General Information\", \"vi\": \"Thông tin chung\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Beginning on 15 May, the Kingston-Garnet Island Passenger Ferry Service will resume service for eight weeks during the summer season.\", \"vi\": \"Bắt đầu từ ngày 15 tháng 5, Dịch vụ phà chở khách Kingston-Garnet Island sẽ nối lại hoạt động trong vòng tám tuần trong mùa hè.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Ferries run daily every half hour from 7 a.m. to 8 p.m. The last ferry to Garnet Island will depart at 7:30 p.m. The last ferry from Garnet Island will leave at 8 p.m.\", \"vi\": \"Phà chạy hàng ngày, cứ nửa giờ một chuyến, từ 7 giờ sáng đến 8 giờ tối. Chuyến phà cuối cùng đi đến Đảo Garnet sẽ khởi hành lúc 7 giờ 30 phút tối. Chuyến phà cuối cùng từ Đảo Garnet sẽ khởi hành lúc 8 giờ tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Bicycles are permitted on the passenger ferries.\", \"vi\": \"Xe đạp được phép mang lên các chuyến phà chở khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Bicyclists should arrive 30 minutes prior to departure and wait in the special bicycle lane to be loaded first.\", \"vi\": \"Quý vị đi xe đạp nên có mặt trước giờ khởi hành 30 phút và chờ tại làn đường dành riêng cho xe đạp để được xếp lên xe trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"There are five racks that hold 50 bicycles on every passenger ferry.\", \"vi\": \"Trên mỗi chiếc phà chở khách đều có năm giá để xe, mỗi giá có thể chứa 50 chiếc xe đạp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"No motorized vehicles are permitted on Garnet Island.\", \"vi\": \"Không được phép lưu thông các phương tiện cơ giới trên Đảo Garnet.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Overnight parking is allowed in the main ferry terminal lot in Kingston.\", \"vi\": \"Việc đỗ xe qua đêm được phép tại bãi đỗ xe của bến phà chính ở Kingston.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Rates are $5 per hour for up to 4 hours and a flat fee of $25 for four to 24 hours.\", \"vi\": \"Mức phí là 5 đô la mỗi giờ cho thời gian sử dụng tối đa 4 giờ và mức phí cố định là 25 đô la cho thời gian từ 4 đến 24 giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Visit our Web site at www.kgferryservice.com for photographs of the ferry boats, a map of Garnet Island, lists of local attractions on the island, and information about peak-hour fare increases and group discounts.\", \"vi\": \"Quý vị vui lòng truy cập trang web của chúng tôi tại địa chỉ www.kgferryservice.com để xem hình ảnh các tàu phà, bản đồ đảo Garnet, danh sách các điểm tham quan địa phương trên đảo, cũng như thông tin về việc tăng giá vé vào giờ cao điểm và các chương trình giảm giá dành cho nhóm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = 'aabebef6-391b-4519-be10-2e7b3729054d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: j.parnthong@trottermail.co.uk\", \"vi\": \"Gửi tới: j.parnthong@trottermail.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: l.florinsmith@gaseau.co.uk\", \"vi\": \"Nguồn: l.florinsmith@gaseau.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 22 January\", \"vi\": \"Ngày: 22 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Your purchase\", \"vi\": \"Chủ đề: Đơn hàng của quý khách\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 recipes\", \"vi\": \"Tệp đính kèm: 📎 công thức nấu ăn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Ms. Parnthong,\", \"vi\": \"Kính gửi bà Parnthong,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for your recent purchase of four Gaseau bamboo cooking utensils.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã mua bốn dụng cụ nấu ăn bằng tre của thương hiệu Gaseau trong thời gian vừa qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As you know, all Gaseau products are made of 100 percent natural bamboo and are meant to last a lifetime.\", \"vi\": \"Như quý vị đã biết, tất cả các sản phẩm của Gaseau đều được làm từ 100% tre tự nhiên và được thiết kế để sử dụng suốt đời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"They are light, durable, and safe for use with nonstick cookware as well as metal pots and pans.\", \"vi\": \"Các sản phẩm này nhẹ, bền và an toàn khi sử dụng với các loại nồi chảo chống dính cũng như nồi chảo bằng kim loại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please remember to hand-wash your new utensils with mild soap and water.\", \"vi\": \"Xin quý vị lưu ý rửa tay các dụng cụ nhà bếp mới của mình bằng xà phòng nhẹ và nước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To thank you for your business, I have attached a few simple recipes that you can create using your new products.\", \"vi\": \"Để tri ân sự ủng hộ của quý khách, tôi đã đính kèm một số công thức nấu ăn đơn giản mà quý khách có thể thực hiện bằng các sản phẩm mới của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"If you have not already done so, please leave a review on our Web site concerning your experience with us.\", \"vi\": \"Nếu quý vị chưa thực hiện việc này, xin vui lòng để lại đánh giá trên trang web của chúng tôi về trải nghiệm của quý vị khi sử dụng dịch vụ của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"You can use this link: www.gaseau.co.uk/reviews.\", \"vi\": \"Quý vị có thể truy cập liên kết sau: www.gaseau.co.uk/reviews.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Liane Florin-Smith\", \"vi\": \"Liane Florin-Smith\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Customer Service Representative\", \"vi\": \"Nhân viên Dịch vụ Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = 'aaca29e2-dc91-4a8d-94f3-3f54b0a7c2e5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"The Design Present Conference is an annual event held in Melbourne for graphic-design professionals.\", \"vi\": \"Hội nghị Design Present là một sự kiện thường niên được tổ chức tại Melbourne dành cho các chuyên gia thiết kế đồ họa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The conference is steadily growing in popularity.\", \"vi\": \"Hội nghị đang ngày càng trở nên phổ biến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Last year, it ______[131] more than 3,000 attendees from Australia and around the world.\", \"vi\": \"Năm ngoái, sự kiện này ______[131] hơn 3.000 người tham dự đến từ Úc và khắp nơi trên thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [131]}, {\"en\": \"The next Design Present Conference, which will be held from 20 to 23 March, will offer more than 100 workshops, plus keynote speeches and plenary sessions.\", \"vi\": \"Hội nghị Design Present tiếp theo, sẽ được tổ chức từ ngày 20 đến ngày 23 tháng 3, sẽ cung cấp hơn 100 hội thảo, cùng với các bài phát biểu chính và các phiên họp toàn thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"This year, several opportunities for professional networking will be added.\", \"vi\": \"Năm nay, một số cơ hội kết nối chuyên nghiệp sẽ được bổ sung.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Attendees will have the chance to market ______[132] to firms in several different industries.\", \"vi\": \"Những người tham dự sẽ có cơ hội tiếp thị ______[132] với các công ty thuộc nhiều ngành nghề khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [132]}, {\"en\": \"Periods for networking will be included in the ______[133] each day.\", \"vi\": \"Thời gian dành cho việc kết nối sẽ được đưa vào ______[133] mỗi ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [133]}, {\"en\": \"Whether you are a design enthusiast, student, freelance designer, or business owner, Design Present has something for you.\", \"vi\": \"Cho dù bạn là người đam mê thiết kế, sinh viên, nhà thiết kế tự do hay chủ doanh nghiệp, Design Present đều có những điều phù hợp với bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[134].\", \"vi\": \"______[134].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [134]}]' WHERE `id` = 'aafa5219-dc66-49a7-a837-ef775001ca5c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Bennett Mobile: Reimbursement Request Form Instructions\", \"vi\": \"Bennett Mobile: Hướng dẫn điền Mẫu đơn yêu cầu hoàn trả chi phí\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Write your name and employee number at the top of the form.\", \"vi\": \"Vui lòng ghi tên và số nhân viên của quý vị ở phần trên cùng của mẫu đơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"For each listed item, write a brief note about the reason for the spending.\", \"vi\": \"Đối với từng khoản mục được liệt kê, xin vui lòng viết một vài dòng giải thích lý do chi tiêu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Staple the relevant receipts to the form.\", \"vi\": \"Xin vui lòng ghim các hóa đơn liên quan vào mẫu đơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Have your manager sign the form and sign it yourself as well.\", \"vi\": \"Xin vui lòng nhờ người quản lý của quý vị ký vào mẫu đơn này và quý vị cũng hãy ký tên vào đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Unsigned requests will not be processed.\", \"vi\": \"Các yêu cầu không có chữ ký sẽ không được xử lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To have the payment appear on your monthly paycheck on the 25th, submit the form by the 15th of the month.\", \"vi\": \"Để khoản thanh toán này được ghi vào phiếu lương hàng tháng của quý vị vào ngày 25, xin vui lòng nộp mẫu đơn trước ngày 15 của tháng đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If you make frequent purchases, you may be eligible to receive a credit card under Bennett Mobile’s account.\", \"vi\": \"Nếu quý vị thường xuyên thực hiện các giao dịch mua hàng, quý vị có thể đủ điều kiện để được cấp thẻ tín dụng dưới tên tài khoản của Bennett Mobile.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Speak to the finance team to request approval.\", \"vi\": \"Vui lòng liên hệ với bộ phận tài chính để xin phê duyệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = 'ab0d8225-528e-40f0-a910-2ae9098375dc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Laboratory staff\", \"vi\": \"Đến: Nhân viên phòng thí nghiệm\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Amal Khoury, Safety Director\", \"vi\": \"Từ: Amal Khoury, Giám đốc An toàn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: January 11\", \"vi\": \"Ngày: 11 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Safety reminder\", \"vi\": \"Chủ đề: Nhắc nhở về an toàn\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I am sending this memo to remind you all of some important safety ______[139].\", \"vi\": \"Tôi gửi bản ghi nhớ này để nhắc nhở tất cả các bạn về một số ______[139] an toàn quan trọng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [139]}, {\"en\": \"First, no employee may handle hazardous chemicals while alone in the laboratory.\", \"vi\": \"Đầu tiên, không nhân viên nào được phép xử lý hóa chất nguy hiểm khi ở một mình trong phòng thí nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"At least one other staff member who could provide aid in the event of a problem has to remain ______[140] sight or hearing at all times.\", \"vi\": \"Ít nhất một nhân viên khác có khả năng hỗ trợ trong trường hợp xảy ra sự cố phải luôn ở trong tầm ______[140] nhìn hoặc tầm nghe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [140]}, {\"en\": \"Employees may perform other types of laboratory tasks alone with prior permission from a director or manager.\", \"vi\": \"Nhân viên có thể thực hiện các loại công việc phòng thí nghiệm khác một mình nếu có sự cho phép trước từ giám đốc hoặc quản lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[141].\", \"vi\": \"______[141].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [141]}, {\"en\": \"The SAFEX compliance management system makes this process simple.\", \"vi\": \"Hệ thống quản lý tuân thủ SAFEX giúp quá trình này trở nên đơn giản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Finally, the SAFEX mobile app\'s \\\"Check-In\\\" feature ______[142] whenever an employee is working alone in the lab.\", \"vi\": \"Cuối cùng, tính năng \\\"Check-In\\\" (Điểm danh) của ứng dụng di động SAFEX ______[142] bất cứ khi nào nhân viên làm việc một mình trong phòng thí nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [142]}, {\"en\": \"The offsite colleague designated as the emergency contact for the feature should also be informed of that fact beforehand.\", \"vi\": \"Đồng nghiệp ở bên ngoài được chỉ định làm liên hệ khẩn cấp cho tính năng này cũng cần phải được thông báo trước về điều đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you for your compliance.\", \"vi\": \"Cảm ơn sự tuân thủ của các bạn.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = 'ab37ca55-13a2-4736-87e2-3ca9ab24003a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"STAR DESIGNS\", \"vi\": \"THIẾT KẾ STAR\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear Customers:\", \"vi\": \"Kính gửi Quý khách hàng:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"For many years, we at Star Designs have strived to offer quality apparel at competitive prices.\", \"vi\": \"Trong nhiều năm qua, chúng tôi tại Star Designs luôn nỗ lực mang đến những sản phẩm may mặc chất lượng với mức giá cạnh tranh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Unfortunately, as a quick glance at our online store shows, we have been forced to increase our prices recently.\", \"vi\": \"Thật không may, như quý vị có thể thấy ngay khi lướt qua cửa hàng trực tuyến của chúng tôi, gần đây chúng tôi đã buộc phải tăng giá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Every effort has been made to avoid this, but because of the growing costs of cotton and most fabrics that we use to sew our colorful shirts and formal wear, we could no longer afford to maintain our prices.\", \"vi\": \"Chúng tôi đã nỗ lực hết sức để tránh tình trạng này, nhưng do giá bông và hầu hết các loại vải mà chúng tôi sử dụng để may những chiếc áo sơ mi sặc sỡ và trang phục trang trọng ngày càng tăng, nên chúng tôi không còn đủ khả năng duy trì mức giá hiện tại nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"However, we will continue to provide the excellent quality and customer-oriented approach that you have come to appreciate with Star Designs.\", \"vi\": \"Tuy nhiên, chúng tôi sẽ tiếp tục mang đến chất lượng xuất sắc và phương châm lấy khách hàng làm trung tâm – những điều mà quý vị đã luôn đánh giá cao ở Star Designs.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thank you for your understanding and your continued loyalty!\", \"vi\": \"Xin chân thành cảm ơn sự thông cảm và lòng trung thành không ngừng của quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"★☆☆\", \"vi\": \"★☆☆\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = 'ab5edf95-7448-4779-9d45-7834da2a7bb5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"LONDON (2 February)—On Thursday, Tillford Press announced the launch of its new imprint, Tillford Exalt.\", \"vi\": \"LONDON (ngày 2 tháng 2) — Vào thứ Năm, Nhà xuất bản Tillford Press đã công bố việc ra mắt nhãn hiệu xuất bản mới của mình, Tillford Exalt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"This new line will feature books promoting healthy lifestyles, memoirs with uplifting messages, and volumes that provide guidance for special occasions such as birthdays and weddings.\", \"vi\": \"Dòng sản phẩm mới này sẽ bao gồm các cuốn sách khuyến khích lối sống lành mạnh, các cuốn hồi ký mang thông điệp truyền cảm hứng, cùng những cuốn sách cung cấp hướng dẫn cho các dịp đặc biệt như sinh nhật và đám cưới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Tillford Exalt will also publish calendars and greeting cards that complement the main products.\", \"vi\": \"Tillford Exalt cũng sẽ xuất bản lịch và thiệp chúc mừng nhằm bổ sung cho các sản phẩm chính.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Already contracted to write memoirs are the award-winning actress Alexia Leoz, London-based conductor and composer Seung-Hyun Bae, and celebrity cook Lain Lai.\", \"vi\": \"Hiện tại, những người đã ký hợp đồng viết hồi ký bao gồm nữ diễn viên từng đoạt giải thưởng Alexia Leoz, nhạc trưởng kiêm nhà soạn nhạc Seung-Hyun Bae đang sinh sống tại London, và đầu bếp nổi tiếng Lain Lai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Ms. Lai’s story of her life and career will be the first to be launched.\", \"vi\": \"Câu chuyện về cuộc đời và sự nghiệp của bà Lai sẽ là câu chuyện đầu tiên được ra mắt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"It is set for release in December.\", \"vi\": \"Tác phẩm dự kiến sẽ ra mắt vào tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Tillford vice president Frederick Bissett said the company saw a need for books that celebrated accomplishments and life events from multiple perspectives.\", \"vi\": \"Ông Frederick Bissett, Phó Chủ tịch công ty Tillford, cho biết công ty nhận thấy nhu cầu về những cuốn sách tôn vinh những thành tựu và các sự kiện quan trọng trong cuộc đời từ nhiều góc nhìn khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"“We wanted authors from a wide variety of cultural backgrounds, and we think we’re off to a great start,” he said.\", \"vi\": \"“Chúng tôi mong muốn có sự tham gia của các tác giả đến từ nhiều nền văn hóa đa dạng, và chúng tôi cho rằng chúng tôi đã có một khởi đầu rất tốt,” ông nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"He noted that Tillford Exalt’s authors were not always famous; the books will be exploring their beginnings, their everyday lives, their first jobs, their marriages and families—as well as their achievements.\", \"vi\": \"Ông lưu ý rằng các tác giả của Tillford Exalt không phải lúc nào cũng nổi tiếng; các cuốn sách này sẽ khám phá những bước khởi đầu của họ, cuộc sống hàng ngày, công việc đầu tiên, cuộc hôn nhân và gia đình của họ — cũng như những thành tựu mà họ đạt được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Tillford Press is based in Manchester.\", \"vi\": \"Nhà xuất bản Tillford Press có trụ sở tại Manchester.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"It has offices in New York, Toronto, and Sydney, but its publications are sold throughout the world.\", \"vi\": \"Công ty này có các văn phòng tại New York, Toronto và Sydney, nhưng các ấn phẩm của công ty được bán trên toàn thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = 'ab604e97-cc6a-4000-8457-0586496f0369';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Closing Early on Summer Fridays\", \"vi\": \"Đóng cửa sớm vào các ngày thứ Sáu trong mùa hè\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"HOUSTON (June 3)—Summer just became more relaxing for employees of Aftnax Software, where the company recently instituted a Summer Friday policy.\", \"vi\": \"HOUSTON (ngày 3 tháng 6) — Mùa hè vừa trở nên thoải mái hơn đối với các nhân viên của Aftnax Software, nơi công ty vừa áp dụng chính sách “Thứ Sáu Mùa Hè”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"From now until the first week in September, the office closes at 1 P.M. so employees can go home early.\", \"vi\": \"Từ nay cho đến tuần đầu tiên của tháng 9, văn phòng sẽ đóng cửa lúc 1 giờ chiều để các nhân viên có thể về nhà sớm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"It\'s great to have that 1 P.M. cutoff,\\\" says Clay Jackson, an Aftnax employee for the past decade.\", \"vi\": \"\\\"Thật tuyệt khi có thời hạn chót là 1 giờ chiều,” ông Clay Jackson, một nhân viên đã làm việc tại Aftnax trong suốt thập kỷ qua, chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"\\\"Some nights I can stay in the office until seven or eight if I have a project I need to finish.\", \"vi\": \"\\\"Có những đêm, nếu có dự án cần hoàn thành, tôi có thể ở lại văn phòng đến bảy hoặc tám giờ.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"But knowing that the office is closing its doors early on Friday frees me up to spend more time with my family.\\\"\", \"vi\": \"“Tuy nhiên, khi biết rằng văn phòng sẽ đóng cửa sớm vào thứ Sáu, tôi có thêm thời gian để dành cho gia đình.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In addition to boosting workers\' morale, studies have found that scheduled downtime actually increases productivity.\", \"vi\": \"Bên cạnh việc nâng cao tinh thần làm việc của người lao động, các nghiên cứu đã chỉ ra rằng thời gian ngừng hoạt động theo kế hoạch thực tế còn giúp tăng năng suất lao động.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The number of firms offering this perk has increased by 23 percent in the past five years.\", \"vi\": \"Số lượng doanh nghiệp cung cấp chế độ phúc lợi này đã tăng 23 phần trăm trong năm năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Remmor Tech, one of the first local companies to institute a similar policy, says that ever since it began offering time off on Fridays twelve years ago, it has seen a marked improvement in employee satisfaction.\", \"vi\": \"Remmor Tech, một trong những công ty trong nước đầu tiên áp dụng chính sách tương tự, cho biết kể từ khi bắt đầu thực hiện chế độ nghỉ làm vào thứ Sáu cách đây mười hai năm, mức độ hài lòng của nhân viên tại công ty đã có sự cải thiện rõ rệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"\\\"Our employees\' happiness is important to us,\\\" says Alexandra Odoms, the CEO of Remmor.\", \"vi\": \"\\\"Sự hạnh phúc của nhân viên là điều rất quan trọng đối với chúng tôi,\\\" bà Alexandra Odoms, Giám đốc Điều hành của Remmor, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"\\\"We know that if we care about our employees, then our employees will care about the work they do for us.\\\"\", \"vi\": \"\\\"Chúng tôi biết rằng nếu chúng tôi quan tâm đến nhân viên của mình, thì nhân viên của chúng tôi cũng sẽ quan tâm đến công việc mà họ thực hiện cho chúng tôi.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = 'ab66a5c5-0df3-45e0-b33d-40521fb51909';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Artist Spotlight: Lavanya Gulati\", \"vi\": \"Giới thiệu nghệ sĩ: Lavanya Gulati\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To: contact@gulatiart.ca\", \"vi\": \"Gửi tới: contact@gulatiart.ca\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"From: a_rankin@omail.ca\", \"vi\": \"Nguồn: a_rankin@omail.ca\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Date: 8 February\", \"vi\": \"Ngày: 8 tháng 2\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Subject: Inquiry\", \"vi\": \"Chủ đề: Yêu cầu thông tin\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"EDMONTON, Canada (5 February)—Painter Lavanya Gulati is grabbing the attention of the art world through her beautiful murals.\", \"vi\": \"EDMONTON, Canada (ngày 5 tháng 2) — Họa sĩ Lavanya Gulati đang thu hút sự chú ý của giới nghệ thuật nhờ những bức tranh tường tuyệt đẹp của cô.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"These large-scale works of art, most of which depict the natural world, can be seen from public streets throughout Edmonton and a few other cities across Canada.\", \"vi\": \"Những tác phẩm nghệ thuật quy mô lớn này, phần lớn miêu tả thế giới tự nhiên, có thể được chiêm ngưỡng từ các đường phố công cộng trên khắp Edmonton và một số thành phố khác trên khắp Canada.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"I love the process of turning something artificial, like a concrete wall, into an entirely new creation,\\\" says Ms. Gulati.\", \"vi\": \"\\\"Tôi rất yêu thích quá trình biến một vật thể nhân tạo, chẳng hạn như một bức tường bê tông, thành một tác phẩm hoàn toàn mới,\\\" bà Gulati chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"\\\"Despite living in urban areas, we can still find ways to stay connected to the environment.\", \"vi\": \"\\\"Dù sống ở các khu vực đô thị, chúng ta vẫn có thể tìm ra những cách để duy trì sự gắn kết với môi trường.\\\"\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I hope that my work reminds people about this.\\\"\", \"vi\": \"Tôi hy vọng rằng tác phẩm của tôi sẽ giúp mọi người nhớ lại điều này.\\\"\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Customer input is an essential part of the planning process, and Ms. Gulati requires a minimum of three weeks to finalize any design plan.\", \"vi\": \"Ý kiến đóng góp của khách hàng là một phần thiết yếu trong quy trình lập kế hoạch, và bà Gulati cần ít nhất ba tuần để hoàn thiện bất kỳ phương án thiết kế nào.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"She says that her painting can be completed quickly once she has a clear vision of the final result.\", \"vi\": \"Cô cho biết rằng một khi đã có hình dung rõ ràng về kết quả cuối cùng, bức tranh của cô có thể được hoàn thành một cách nhanh chóng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Surprisingly, Ms. Gulati\'s customers are expected to clean and treat the area where the mural is to be painted.\", \"vi\": \"Điều đáng ngạc nhiên là, các khách hàng của bà Gulati được yêu cầu phải dọn dẹp và xử lý khu vực nơi bức tranh tường sẽ được vẽ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Ms. Gulati says this not only cuts down on costs but also allows customers to be a part of the work.\", \"vi\": \"Bà Gulati cho biết điều này không chỉ giúp cắt giảm chi phí mà còn cho phép khách hàng tham gia vào quá trình thực hiện công việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"She advises on supplies for this task and has a video with comprehensive step-by-step instructions on her Web site, www.gulatiart.ca.\", \"vi\": \"Bà đưa ra lời khuyên về các vật dụng cần thiết cho công việc này và có đăng tải một đoạn video hướng dẫn chi tiết từng bước trên trang web của mình, www.gulatiart.ca.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Dear Ms. Gulati,\", \"vi\": \"Kính gửi Bà Gulati,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I read the recently published article about your work, and I was impressed with the photos of your murals that I found online.\", \"vi\": \"Tôi đã đọc bài báo vừa được đăng tải về tác phẩm của quý vị, và tôi rất ấn tượng với những bức ảnh về các bức tranh tường của quý vị mà tôi tìm thấy trên mạng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"My coffee shop is relocating, and we need two murals:\", \"vi\": \"Quán cà phê của tôi sắp chuyển địa điểm, và chúng tôi cần hai bức tranh tường:\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"On one side of the two-story building (852 Stockert Street, exterior wall), I would like a dramatic and eye-catching mural that potential customers will notice.\", \"vi\": \"Tại một bên của tòa nhà hai tầng (số 852 đường Stockert, mặt tiền), tôi mong muốn có một bức tranh tường ấn tượng và thu hút sự chú ý, để các khách hàng tiềm năng có thể nhận ra.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"In the main indoor seating area, I\'m trying to create a relaxing atmosphere with a forest scene.\", \"vi\": \"Tại khu vực chỗ ngồi chính trong nhà, tôi đang cố gắng tạo ra một bầu không khí thư giãn với khung cảnh rừng cây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I will save pieces of the wooden floor of our current site, which is to be torn down, and I would like those to be included somehow.\", \"vi\": \"Tôi sẽ giữ lại một số mảnh sàn gỗ từ công trình hiện tại của chúng tôi – nơi sắp bị phá dỡ – và tôi mong muốn những mảnh sàn đó có thể được đưa vào thiết kế bằng cách nào đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Would it be possible to meet this week to discuss the work and get sketches of your proposed designs by 18 February?\", \"vi\": \"Liệu chúng ta có thể gặp nhau trong tuần này để thảo luận về công việc và nhận được các bản phác thảo thiết kế mà quý vị đề xuất trước ngày 18 tháng 2 được không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I can provide a deposit by bank transfer as soon as we sign a contract.\", \"vi\": \"Tôi có thể chuyển khoản đặt cọc ngay sau khi chúng ta ký hợp đồng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Albert Rankin\", \"vi\": \"Albert Rankin\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = 'ab9a80b8-05f9-4d56-83e8-a1a3495decf4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All employees\", \"vi\": \"Gửi: Tất cả các nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Janice Capaldi\", \"vi\": \"Từ: Janice Capaldi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: October 23\", \"vi\": \"Ngày: 23 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Guests\", \"vi\": \"Chủ đề: Khách mời\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Good afternoon, everyone,\", \"vi\": \"Xin chào buổi chiều, thưa quý vị,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We will soon host a group of employees from Seongnam Electronics.\", \"vi\": \"Chúng tôi sẽ sớm đón tiếp một đoàn cán bộ, nhân viên đến từ Công ty Seongnam Electronics.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"They will arrive on November 10 and be with us for a week to observe our research and production methods.\", \"vi\": \"Họ sẽ đến vào ngày 10 tháng 11 và ở lại với chúng tôi trong một tuần để quan sát các phương pháp nghiên cứu và sản xuất của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We encourage everyone to interact with the visitors while they are here.\", \"vi\": \"Chúng tôi khuyến khích mọi người giao lưu với các vị khách trong thời gian họ có mặt tại đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The executives in the group are leaders in the field of electronics development and manufacturing.\", \"vi\": \"Các nhà điều hành trong tập đoàn này là những nhà lãnh đạo hàng đầu trong lĩnh vực phát triển và sản xuất thiết bị điện tử.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Dr. Sung-Hye Kim leads Research and Development.\", \"vi\": \"Tiến sĩ Sung-Hye Kim phụ trách mảng Nghiên cứu và Phát triển.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Her individual contributions have focused on how magnetic fields influence the efficiency of components within electrical devices.\", \"vi\": \"Các đóng góp cá nhân của bà tập trung vào việc tìm hiểu cách thức các từ trường tác động đến hiệu suất hoạt động của các linh kiện trong các thiết bị điện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"She has also been called on by other physicists and professors to write and edit texts that explain electromagnetic phenomena.\", \"vi\": \"Bà cũng đã được các nhà vật lý và giáo sư khác mời viết và biên tập các tài liệu giải thích các hiện tượng điện từ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Dr. Kim\'s work is influential throughout the international electronics industry.\", \"vi\": \"Các công trình nghiên cứu của Tiến sĩ Kim có ảnh hưởng sâu rộng trong toàn ngành công nghiệp điện tử quốc tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Also, Jin-Woong Lee, chief production officer at Seongnam Electronics, heads the team that designed the manufacturing processes at the plant near Seoul.\", \"vi\": \"Bên cạnh đó, ông Jin-Woong Lee, Giám đốc sản xuất của Seongnam Electronics, là người đứng đầu nhóm đã thiết kế các quy trình sản xuất tại nhà máy gần Seoul.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The award-winning techniques developed by Mr. Lee\'s team assure both cost-effectiveness and quality.\", \"vi\": \"Các kỹ thuật từng đoạt giải thưởng do đội ngũ của ông Lee phát triển đảm bảo cả tính hiệu quả về chi phí lẫn chất lượng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"On the afternoon of November 10, we will hold a reception in the conference room on the third floor to welcome our guests.\", \"vi\": \"Vào chiều ngày 10 tháng 11, chúng tôi sẽ tổ chức một buổi tiệc chiêu đãi tại phòng hội nghị ở tầng ba để đón tiếp quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Specifics will be sent to the entire staff in an e-mail from Stewart Lark, who is serving as the event\'s coordinator.\", \"vi\": \"Các thông tin chi tiết sẽ được gửi đến toàn thể nhân viên qua email do ông Stewart Lark, người đang đảm nhiệm vai trò điều phối viên của sự kiện này, soạn thảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Please plan on attending.\", \"vi\": \"Kính mong quý vị sắp xếp thời gian để tham dự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Contact Mr. Lark and me with any questions you may have.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào, xin vui lòng liên hệ với ông Lark và tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Janice Capaldi, Director of Operations, Dolesley Electronics, Inc.\", \"vi\": \"Bà Janice Capaldi, Giám đốc Điều hành, Công ty Dolesley Electronics, Inc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = 'ab9fa9ac-10fc-4e4c-95d8-2385863af892';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"CONOVER\'S\", \"vi\": \"Conover\'s\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear Customers:\", \"vi\": \"Kính gửi quý khách hàng:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Since our opening nearly 30 years ago, Conover’s has been proud to equip Mandeville residents for a wide range of indoor and outdoor sports.\", \"vi\": \"Kể từ khi khai trương cách đây gần 30 năm, Conover’s luôn tự hào được cung cấp trang thiết bị cho người dân Mandeville tham gia nhiều môn thể thao trong nhà và ngoài trời khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"However, we have recently made the difficult decision to remove fishing gear, supplies, and equipment from our inventory due to poor sales.\", \"vi\": \"Tuy nhiên, gần đây chúng tôi đã đưa ra quyết định khó khăn là loại bỏ các dụng cụ câu cá, vật tư và thiết bị khỏi danh mục hàng hóa của mình do doanh số bán hàng không đạt yêu cầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The floor space this stock used to occupy will instead be used to display additional workout apparel.\", \"vi\": \"Diện tích mà lô hàng này từng chiếm dụng sẽ được sử dụng để trưng bày thêm các sản phẩm quần áo tập luyện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This step will help Conover’s remain profitable so that we can continue supporting Mandeville’s athletes for many years to come.\", \"vi\": \"Bước đi này sẽ giúp Conover’s duy trì khả năng sinh lời, từ đó chúng tôi có thể tiếp tục hỗ trợ các vận động viên của Mandeville trong nhiều năm tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Still, we apologize for the inconvenience this will cause for the fishing enthusiasts among our customers.\", \"vi\": \"Tuy nhiên, chúng tôi xin chân thành xin lỗi vì những bất tiện mà điều này có thể gây ra cho các khách hàng yêu thích câu cá của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"—Conover’s Management\", \"vi\": \"—Ban Lãnh đạo Conover\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = 'abf89ccc-a0e0-42e2-838b-6dd72afb87be';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Katie Milerre (10:36 A.M.)\", \"vi\": \"Katie Miller (10 giờ 36 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Mr. del Mar, I\'m finalizing the catering order for next month\'s client-appreciation banquet.\", \"vi\": \"Thưa ông del Mar, tôi đang hoàn tất đơn đặt hàng dịch vụ tiệc cho buổi tiệc tri ân khách hàng vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We haven\'t received responses from our clients at Hartford and Mason Law Firm.\", \"vi\": \"Chúng tôi vẫn chưa nhận được phản hồi từ các khách hàng tại Văn phòng Luật sư Hartford và Mason.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Should I call to confirm with them?\", \"vi\": \"Tôi có nên gọi điện để xác nhận lại với họ không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Alberto del Mar (10:38 A.M.)\", \"vi\": \"Alberto del Mar (10 giờ 38 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"No, that\'s not necessary.\", \"vi\": \"Không, điều đó không cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I spoke with Mr. Hartford yesterday, and he told me they won\'t be able to make it.\", \"vi\": \"Hôm qua tôi đã nói chuyện với ông Hartford, và ông ấy cho biết họ sẽ không thể đến được.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"They\'ll be traveling out of state for an appointment that day.\", \"vi\": \"Họ sẽ phải đi ra khỏi tiểu bang để tham dự một cuộc hẹn vào ngày hôm đó.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Katie Milerre (10:39 A.M.)\", \"vi\": \"Katie Miller (10 giờ 39 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I see.\", \"vi\": \"Tôi hiểu rồi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Would you like me to have a gift basket sent to their office since they won\'t be attending?\", \"vi\": \"Vì họ sẽ không tham dự, vậy quý vị có muốn tôi gửi một giỏ quà đến văn phòng của họ không?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Alberto del Mar (10:41 A.M.)\", \"vi\": \"Alberto del Mar (10 giờ 41 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Yes.\", \"vi\": \"Vâng.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Please also include a gift card to the restaurant where the banquet is being held and an invitation to attend lunch with me there at a later date.\", \"vi\": \"Xin vui lòng kèm theo một thẻ quà tặng của nhà hàng nơi tổ chức tiệc và một lời mời để cùng tôi dùng bữa trưa tại đó vào một ngày khác.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Katie Milerre (10:42 A.M.)\", \"vi\": \"Katie Miller (10 giờ 42 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Certainly.\", \"vi\": \"Chắc chắn rồi.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I will bring the card to your office this afternoon for a signature.\", \"vi\": \"Chiều nay tôi sẽ mang thẻ đến văn phòng của quý vị để xin chữ ký.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Alberto del Mar (10:42 A.M.)\", \"vi\": \"Alberto del Mar (10 giờ 42 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Thank you, Katie.\", \"vi\": \"Cảm ơn cô, Katie.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = 'ac2bd56b-5205-4c5a-bcc5-1bff865243d5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Product Launch Delayed\", \"vi\": \"Việc ra mắt sản phẩm bị hoãn lại\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Covered Bridge Industries has delayed the launch of its new Balmy Breeze soft drink.\", \"vi\": \"Công ty Covered Bridge Industries đã hoãn việc ra mắt sản phẩm nước giải khát mới mang tên Balmy Breeze.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The company had planned to release the product in June to take advantage of the higher sales demand during the summer months.\", \"vi\": \"Công ty đã lên kế hoạch ra mắt sản phẩm vào tháng 6 để tận dụng nhu cầu tiêu thụ tăng cao trong những tháng mùa hè.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The company said the delay was caused by a shortage of one of the drink\'s main components, mango extract, which led to the postponement of quality testing until August.\", \"vi\": \"Công ty cho biết sự chậm trễ này là do tình trạng khan hiếm một trong những thành phần chính của thức uống, đó là chiết xuất xoài, dẫn đến việc phải hoãn các cuộc kiểm tra chất lượng cho đến tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Covered Bridge now hopes to complete all quality testing by November so that it can launch the product the following month.\", \"vi\": \"Hiện tại, Covered Bridge hy vọng sẽ hoàn tất tất cả các cuộc kiểm tra chất lượng trước tháng 11 để có thể ra mắt sản phẩm vào tháng sau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"While sales will likely be weaker than originally hoped, the company will promote Balmy Breeze as an excellent choice for winter holiday celebrations.\", \"vi\": \"Mặc dù doanh số bán hàng có thể sẽ thấp hơn so với kỳ vọng ban đầu, công ty sẽ quảng bá sản phẩm Balmy Breeze như một lựa chọn tuyệt vời cho các dịp lễ hội mùa đông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = 'ac303913-d507-46b5-ac28-eff4936581db';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"GRI Ready for Action\", \"vi\": \"GRI: Sẵn sàng hành động\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"By Antoine Williams\", \"vi\": \"Tác giả: Antoine Williams\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Although considered by many to be the running capital of Ontario, the city of Barrie is also home to several public swimming establishments, including the Galewood Recreation Institute (GRI).\", \"vi\": \"Mặc dù được nhiều người coi là “thủ phủ của môn chạy bộ” tại Ontario, thành phố Barrie cũng là nơi tọa lạc của một số cơ sở bơi lội công cộng, trong đó có Viện Thể thao Giải trí Galewood (GRI).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The institute boasts two indoor pools, one used for recreational swimming and the other reserved for special programmes, such as swimming lessons and lifeguard certification.\", \"vi\": \"Viện này tự hào có hai bể bơi trong nhà, một bể dành cho bơi lội giải trí và bể còn lại dành riêng cho các chương trình đặc biệt, chẳng hạn như các lớp học bơi và khóa đào tạo cấp chứng chỉ nhân viên cứu hộ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"This summer, the institute will add intensive swimming and safety certification classes.\", \"vi\": \"Mùa hè này, viện sẽ tổ chức thêm các khóa học bơi chuyên sâu và các khóa đào tạo cấp chứng chỉ an toàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"\\\"It is our high season,\\\" said Herbert Gagnon, institute director.\", \"vi\": \"\\\"Đây là mùa cao điểm của chúng tôi,\\\" ông Herbert Gagnon, Giám đốc Viện, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"\\\"Our pools are indoors, which allows for swimming all year, but in the summer people naturally have more time for recreation and new activities in general.\\\"\", \"vi\": \"\\\"Các bể bơi của chúng tôi là bể bơi trong nhà, nhờ đó quý vị có thể bơi lội quanh năm; tuy nhiên, vào mùa hè, mọi người thường có nhiều thời gian hơn để giải trí và tham gia các hoạt động mới nói chung.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Summer classes will be offered mornings, afternoons, and evenings.\", \"vi\": \"Các lớp học mùa hè sẽ được tổ chức vào buổi sáng, buổi chiều và buổi tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"We hope that we can accommodate everybody\'s schedule,\\\" continued Gagnon.\", \"vi\": \"\\\"Chúng tôi hy vọng có thể sắp xếp sao cho phù hợp với lịch trình của tất cả mọi người,\\\" ông Gagnon tiếp lời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"\\\"Our classes aim to serve not just children, but all age ranges and levels of experience.\\\"\", \"vi\": \"\\\"Các lớp học của chúng tôi không chỉ hướng đến trẻ em, mà còn dành cho mọi lứa tuổi và mọi trình độ.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"For additional information, please call 905-555-0142 or visit www.galewoodrec.org.\", \"vi\": \"Để biết thêm thông tin, xin vui lòng gọi số 905-555-0142 hoặc truy cập trang web www.galewoodrec.org.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"http://www.galewoodrec.org/employment\", \"vi\": \"http://www.galewoodrec.org/employment\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Employment Opportunities\", \"vi\": \"Cơ hội việc làm\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Job Title: Swimming Instructors\", \"vi\": \"Chức danh: Huấn luyện viên bơi lội\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date posted: March 20\", \"vi\": \"Ngày đăng: 20 tháng 3\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The Galewood Recreation Institute has an ongoing need for certified swimming instructors to work at one or both of our swimming pools.\", \"vi\": \"Viện Thể thao Galewood hiện đang có nhu cầu tuyển dụng các huấn luyện viên bơi lội có chứng chỉ để làm việc tại một hoặc cả hai bể bơi của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Instructors perform lifeguard duties, teach weekly swimming lessons, lead safety certification courses, and carry out other standard duties.\", \"vi\": \"Các huấn luyện viên thực hiện nhiệm vụ cứu hộ, giảng dạy các lớp học bơi hàng tuần, hướng dẫn các khóa học cấp chứng chỉ an toàn và thực hiện các nhiệm vụ thông thường khác.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The need for staff is especially acute during the busy summer months.\", \"vi\": \"Nhu cầu về nhân sự đặc biệt cấp thiết trong những tháng mùa hè cao điểm.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Institute staff are expected to provide top-quality service to patrons at all times, so applicants should be energetic and have strong interpersonal skills.\", \"vi\": \"Các nhân viên của Viện được kỳ vọng sẽ luôn cung cấp dịch vụ chất lượng cao nhất cho quý khách hàng; do đó, các ứng viên cần phải năng động và có kỹ năng giao tiếp tốt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"In addition to regular positions, we are looking to select two instructors interested in being part of a unique summer education programme for teenagers.\", \"vi\": \"Bên cạnh các vị trí công việc thường xuyên, chúng tôi đang tìm kiếm hai giảng viên quan tâm đến việc tham gia một chương trình giáo dục mùa hè độc đáo dành cho thanh thiếu niên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Along with having the same skills required by the regular position, these special instructors will be required to implement a curriculum designed and supervised by the Ontario Foundation for Teaching and Learning.\", \"vi\": \"Bên cạnh việc phải đáp ứng các yêu cầu về năng lực tương tự như vị trí thông thường, các giảng viên đặc biệt này sẽ phải triển khai chương trình giảng dạy do Quỹ Giáo dục và Học tập Ontario thiết kế và giám sát.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"The selected candidates will first complete a paid monthlong training course during May.\", \"vi\": \"Các ứng viên được tuyển chọn sẽ trước tiên tham gia một khóa đào tạo kéo dài một tháng với chế độ lương trong tháng 5.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"They must be available to work Tuesday evenings and Wednesday evenings from June 1 through the end of the summer.\", \"vi\": \"Họ phải sẵn sàng làm việc vào các buổi tối thứ Ba và thứ Tư, từ ngày 1 tháng 6 cho đến hết mùa hè.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Candidates must have a minimum of six months of teaching experience and hold current certification from an accredited training programme.\", \"vi\": \"Ứng viên phải có ít nhất sáu tháng kinh nghiệm giảng dạy và sở hữu chứng chỉ còn hiệu lực do một chương trình đào tạo được công nhận cấp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"When applying, please upload your certifications along with your résumé.\", \"vi\": \"Khi nộp hồ sơ, xin vui lòng tải lên các chứng chỉ của quý vị kèm theo sơ yếu lý lịch.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = 'ac5732e4-a9d3-4eab-baba-479674def4d3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"12 December\", \"vi\": \"Ngày 12 tháng 12\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Lenny Howe\", \"vi\": \"Lenny Howe\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"222 Easton Boulevard\", \"vi\": \"222 Easton Boulevard\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Port Douglas QLD 4877\", \"vi\": \"Port Douglas QLD 4877\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Howe,\", \"vi\": \"Kính gửi Ông Howe,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The Irwin Neighbourhood Association is proud to ______[143] a summer event called Park Fest, to be held at Fern Park on 10 January, from 1 P.M. to 8 P.M. Park Fest will feature numerous family-friendly activities and a delicious picnic dinner to be served at 6 P.M. A per person fee of ten dollars will be collected.\", \"vi\": \"Hiệp hội Khu dân cư Irwin tự hào ______[143] một sự kiện mùa hè có tên là Park Fest, được tổ chức tại Công viên Fern vào ngày 10 tháng 1, từ 1 giờ chiều đến 8 giờ tối. Park Fest sẽ có nhiều hoạt động thân thiện với gia đình và một bữa tối dã ngoại ngon miệng được phục vụ vào lúc 6 giờ chiều. Phí tham gia là mười đô la mỗi người sẽ được thu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [143]}, {\"en\": \"The proceeds will ______[144] go towards a park enhancement project.\", \"vi\": \"Số tiền thu được sẽ ______[144] đóng góp cho một dự án nâng cấp công viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [144]}, {\"en\": \"The plan is to hire a contractor to landscape the park grounds, while a smaller portion will be spent on an advertising campaign.\", \"vi\": \"Kế hoạch là thuê một nhà thầu để cảnh quan khuôn viên công viên, trong khi một phần nhỏ hơn sẽ được chi cho chiến dịch quảng cáo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This event ______[145] to be great fun.\", \"vi\": \"Sự kiện này ______[145] rất vui.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [145]}, {\"en\": \"______[146].\", \"vi\": \"______[146].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [146]}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Faye Mason-Jones\", \"vi\": \"Faye Mason-Jones\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Director, Irwin Neighbourhood Association\", \"vi\": \"Giám đốc, Hiệp hội Khu dân cư Irwin\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = 'ad13d26f-b70f-4a51-86de-6c8997717963';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Housing Prices on the Rise\", \"vi\": \"Giá nhà đất đang tăng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"By Yong-Joon Wang\", \"vi\": \"Tác giả: Yong-Joon Wang\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"DROSSER (May 6)—Housing prices in Drosser continue to increase, according to data from Turfle.com, the online real estate marketplace.\", \"vi\": \"DROSSER (ngày 6 tháng 5) — Theo số liệu từ Turfle.com, nền tảng giao dịch bất động sản trực tuyến, giá nhà ở tại Drosser vẫn tiếp tục tăng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The average home price for the area jumped 5.2% from last year to $392,500.\", \"vi\": \"Giá nhà trung bình tại khu vực này đã tăng 5,2% so với năm ngoái, lên mức 392.500 đô la.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"“Higher home values mean more revenue from property taxes,” commented Ada Ferrell, chair of the Drosser Housing Authority Board.\", \"vi\": \"“Giá trị nhà ở tăng cao đồng nghĩa với việc nguồn thu từ thuế bất động sản cũng tăng lên,” bà Ada Ferrell, Chủ tịch Hội đồng Quản trị Cơ quan Quản lý Nhà ở Drosser, nhận định.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"“The city will be able to generate extra funding for its social services.”\", \"vi\": \"“Thành phố sẽ có thể huy động thêm nguồn kinh phí cho các dịch vụ xã hội của mình.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"However, Ms. Ferrell pointed out that the trend also poses problems for individual households.\", \"vi\": \"Tuy nhiên, bà Ferrell đã chỉ ra rằng xu hướng này cũng gây ra những vấn đề cho từng hộ gia đình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"“Some homeowners will struggle to pay their higher property tax bill,” she said.\", \"vi\": \"“Một số chủ nhà sẽ gặp khó khăn trong việc thanh toán hóa đơn thuế bất động sản tăng cao,” bà nói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"“Moreover, we know that rent prices have risen correspondingly in the past year, increasing the burden on rental tenants.\", \"vi\": \"“Hơn nữa, chúng ta đều biết rằng giá thuê nhà đã tăng tương ứng trong năm qua, khiến gánh nặng tài chính đối với những người thuê nhà ngày càng nặng nề hơn.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Rent is becoming an increasingly large share of their living costs.”\", \"vi\": \"“Chi phí thuê nhà đang chiếm một tỷ trọng ngày càng lớn trong tổng chi phí sinh hoạt của họ.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Residents experiencing financial difficulties due to housing can find a variety of resources on the Drosser Housing Authority Board’s Web site, www.drossercity.org/dhab.\", \"vi\": \"Các cư dân đang gặp khó khăn về tài chính liên quan đến nhà ở có thể tìm thấy nhiều nguồn hỗ trợ khác nhau trên trang web của Hội đồng Quản lý Nhà ở Drosser, tại địa chỉ www.drossercity.org/dhab.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = 'ad518fcf-3753-41a3-805a-c85a9295a8f0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"The Right Candidates - Page 11\", \"vi\": \"Những ứng viên phù hợp - Trang 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Spot the applicant that will make a difference. Doug Tenor spoke with four managers about their approach to interviewing.\", \"vi\": \"Hãy tìm ra ứng viên có thể tạo nên sự khác biệt. Ông Doug Tenor đã trao đổi với bốn nhà quản lý về cách thức tiến hành phỏng vấn của họ.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The Right Questions - Page 27\", \"vi\": \"Những câu hỏi đúng đắn - Trang 27\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"How do the big international corporations look for new employees? Lilly Zimble visits three of the biggest HR departments in the world to see what goes into job postings and recruiting.\", \"vi\": \"Các tập đoàn quốc tế lớn tìm kiếm nhân viên mới như thế nào? Lilly Zimble đã đến thăm ba bộ phận nhân sự lớn nhất thế giới để tìm hiểu những yếu tố nào được đưa vào các thông báo tuyển dụng và quá trình tuyển dụng.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Being There - Page 38\", \"vi\": \"“Being There” - Trang 38\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Gina Pimentel looks at the strengths and weaknesses of virtual conferencing. What is the future for distance meetings, and is this what we want? While useful for brief meetings, will they ever excel for longer interactions? Surprisingly, some studies show that virtual conferencing has little effect on employee engagement.\", \"vi\": \"Bà Gina Pimentel phân tích những điểm mạnh và điểm yếu của hình thức hội nghị trực tuyến. Tương lai của các cuộc họp từ xa sẽ ra sao, và liệu đây có phải là điều chúng ta mong muốn? Mặc dù hữu ích cho các cuộc họp ngắn, liệu hình thức này có bao giờ thực sự phát huy hiệu quả trong các cuộc trao đổi kéo dài hơn không? Đáng ngạc nhiên là, một số nghiên cứu cho thấy hội nghị trực tuyến có tác động rất ít đến mức độ gắn kết của nhân viên.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Benefits of the Phrase Book - Page 44\", \"vi\": \"Lợi ích của cuốn Sổ tay hội thoại - Trang 44\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Melissa Dyson shares tips on communicating with locals when conducting business abroad. Clients warm to visitors who make the effort to learn some of their language.\", \"vi\": \"Bà Melissa Dyson chia sẻ những lời khuyên về cách giao tiếp với người dân địa phương khi tiến hành hoạt động kinh doanh ở nước ngoài. Khách hàng thường có thiện cảm với những vị khách du lịch nỗ lực học hỏi một số từ vựng trong ngôn ngữ của họ.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Extended Stay - Page 52\", \"vi\": \"Thời gian lưu trú kéo dài - Trang 52\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Greg McDaniel went to five hotels in five weeks to experience their extended-stay options. He details each hotel\'s pros and cons.\", \"vi\": \"Greg McDaniel đã ghé thăm năm khách sạn trong vòng năm tuần để trải nghiệm các gói lưu trú dài hạn của các nơi này. Ông đã phân tích chi tiết những ưu điểm và nhược điểm của từng khách sạn.\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Business Outlook Monthly\", \"vi\": \"Bản tin Triển vọng Kinh doanh Hàng tháng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Articles in the March Issue:\", \"vi\": \"Các bài viết trong số tháng Ba:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The Farol Grande Hotel—Updates\", \"vi\": \"Khách sạn Farol Grande — Thông tin cập nhật\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"http://www.farolgrandehotel.com/updates\", \"vi\": \"http://www.farolgrandehotel.com/updates\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We recently learned that we were reviewed in the March issue of Business Outlook Monthly magazine!\", \"vi\": \"Gần đây, chúng tôi được biết rằng công ty chúng tôi đã được giới thiệu trên số tháng 3 của tạp chí Business Outlook Monthly!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The review was performed by an \\\"undercover operation\\\"—the reporter used a fictional name, posed as a regular guest, and stayed with us for five nights—so we didn\'t know he was here until we saw the article!\", \"vi\": \"Bài đánh giá này được thực hiện thông qua một “chiến dịch thâm nhập” — phóng viên đã sử dụng tên giả, đóng vai một vị khách bình thường và lưu trú tại khách sạn của chúng tôi trong năm đêm — vì vậy chúng tôi hoàn toàn không biết anh ấy đã ở đây cho đến khi đọc được bài báo!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Access the magazine here to read the thorough analysis of our facilities: http://www.bom.com/currentissues/march.\", \"vi\": \"Quý vị có thể truy cập tạp chí tại đây để đọc bài phân tích chi tiết về các cơ sở của chúng tôi: http://www.bom.com/currentissues/march.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Business Outlook Monthly\", \"vi\": \"Báo cáo Triển vọng Kinh doanh Hàng tháng\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To the Editor:\", \"vi\": \"Kính gửi Ban Biên tập:\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I read with interest Gina Pimentel\'s take on the status of videoconferencing and other virtual meeting technologies.\", \"vi\": \"Tôi đã đọc với sự quan tâm bài phân tích của bà Gina Pimentel về tình hình hiện tại của hội nghị truyền hình và các công nghệ họp trực tuyến khác.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Although I sympathize with the author\'s sentiment that video and conference calls are no real alternative to meetings in person, it seems to be the trend of the future.\", \"vi\": \"Mặc dù tôi đồng cảm với quan điểm của tác giả rằng các cuộc gọi video và hội nghị trực tuyến không phải là giải pháp thay thế thực sự cho các cuộc họp trực tiếp, nhưng dường như đây chính là xu hướng của tương lai.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"But even with recent technological advances, in my experience, videoconferences are most effective for short meetings such as status checks.\", \"vi\": \"Tuy nhiên, theo kinh nghiệm của tôi, dù công nghệ đã có những bước tiến đáng kể gần đây, các cuộc họp trực tuyến vẫn phát huy hiệu quả nhất trong các cuộc họp ngắn, chẳng hạn như các buổi kiểm tra tiến độ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"When it comes to negotiations, however, there is nothing like face-to-face interactions.\", \"vi\": \"Tuy nhiên, khi nói đến việc đàm phán, không có gì có thể sánh bằng những cuộc trao đổi trực tiếp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"—Emre Osman\", \"vi\": \"—Emre Osman\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}]' WHERE `id` = 'ad69a829-abf4-4624-9ba5-4e97574b9b32';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Thank you for initiating the setup of your Paxton Mobile Banking account.\", \"vi\": \"Cảm ơn bạn đã bắt đầu thiết lập tài khoản Ngân hàng Di động Paxton của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"____143___ .\", \"vi\": \"____143___ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [143]}, {\"en\": \"Once your account is fully activated, you will receive notifications of any account activity, ___144____ deposits, withdrawals, and fund transfers.\", \"vi\": \"Khi tài khoản của bạn được kích hoạt hoàn toàn, bạn sẽ nhận được thông báo về bất kỳ hoạt động tài khoản nào, ___144____ tiền gửi, tiền rút và chuyển khoản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [144]}, {\"en\": \"You can ___145____ your notification settings on the \\\"My Account\\\" page on our mobile app or Web site.\", \"vi\": \"Bạn có thể ___145____ cài đặt thông báo của mình trên trang \\\"Tài khoản của tôi\\\" trên ứng dụng di động hoặc trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [145]}, {\"en\": \"For security purposes, you will be prompted to request a one-time ___146____ code before changing your settings.\", \"vi\": \"Vì lý do bảo mật, bạn sẽ được nhắc yêu cầu mã ___146____ một lần trước khi thay đổi cài đặt của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [146]}, {\"en\": \"If you have any questions, please visit www.paxtonmobilebanking.com/FAQ.\", \"vi\": \"Nếu bạn có bất kỳ câu hỏi nào, vui lòng truy cập www.paxtonmobilebanking.com/FAQ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = 'ad8a67ac-8421-4715-ae1c-7b9253510b20';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"STUDY BUSINESS IN SINGAPORE\", \"vi\": \"HỌC NGÀNH KINH DOANH TẠI SINGAPORE\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"The Singapore Business School (SBS) is located in the heart of Singapore\'s financial district.\", \"vi\": \"Trường Kinh doanh Singapore (SBS) tọa lạc tại trung tâm khu tài chính của Singapore.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We offer a range of high-quality courses aimed at preparing students for graduate school.\", \"vi\": \"Chúng tôi cung cấp một loạt các khóa học chất lượng cao nhằm giúp sinh viên chuẩn bị cho việc theo học bậc sau đại học.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Between classroom sessions you can explore the city and cultivate business connections.\", \"vi\": \"Trong thời gian nghỉ giữa các buổi học, quý vị có thể khám phá thành phố và mở rộng mạng lưới quan hệ kinh doanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We offer content-based classes, such as finance, economics, and international marketing, as well as classes on preparing graduate school applications, including developing CVs and writing personal statements.\", \"vi\": \"Chúng tôi cung cấp các khóa học chuyên sâu về nội dung, chẳng hạn như tài chính, kinh tế và tiếp thị quốc tế, cũng như các khóa học hướng dẫn chuẩn bị hồ sơ ứng tuyển vào các chương trình sau đại học, bao gồm cách xây dựng sơ yếu lý lịch và viết bản tự giới thiệu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We have helped thousands of students gain entry into graduate programmes around the world.\", \"vi\": \"Chúng tôi đã giúp hàng nghìn sinh viên trúng tuyển vào các chương trình sau đại học trên toàn thế giới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We boast a number of high-profile part-time instructors who are experts in their fields, including Diara Rhodes, chief financial officer of Auto Drive Korea, and Farah Wan, vice president of the Kuala Lumpur Union Lenders.\", \"vi\": \"Chúng tôi tự hào có đội ngũ giảng viên thỉnh giảng uy tín, là những chuyên gia hàng đầu trong lĩnh vực của mình, bao gồm bà Diara Rhodes, Giám đốc Tài chính của Auto Drive Korea, và bà Farah Wan, Phó Chủ tịch của Kuala Lumpur Union Lenders.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"For more information about our impressive faculty and course offerings, or to enroll online, visit our Web site at www.sbs.edu.sg.\", \"vi\": \"Để biết thêm thông tin về đội ngũ giảng viên xuất sắc và các chương trình đào tạo của chúng tôi, hoặc để đăng ký trực tuyến, quý vị vui lòng truy cập trang web của chúng tôi tại địa chỉ www.sbs.edu.sg.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"What Our Students Are Saying\", \"vi\": \"Những chia sẻ từ các học viên của chúng tôi\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"http://www.sbs.edu.sg/reviews\", \"vi\": \"http://www.sbs.edu.sg/reviews\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"3 June by Atsushi Koshi\", \"vi\": \"Ngày 3 tháng 6, tác giả: Atsushi Koshi\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I took a finance course at SBS.\", \"vi\": \"Tôi đã theo học một khóa học về tài chính tại SBS.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The school I am now attending in the United Kingdom had a prerequisite that I had not fulfilled while earning my Bachelor\'s degree, so the eight-week course was convenient.\", \"vi\": \"Trường mà tôi đang theo học tại Vương quốc Anh có một điều kiện tiên quyết mà tôi chưa đáp ứng được trong quá trình theo học chương trình Cử nhân, vì vậy khóa học kéo dài tám tuần này thực sự rất thuận tiện.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"However, I couldn\'t afford the high rent in the area, so I had to commute, and the traffic in that area is terrible.\", \"vi\": \"Tuy nhiên, tôi không đủ khả năng chi trả mức tiền thuê nhà cao ở khu vực đó, nên đành phải đi làm xa, trong khi tình trạng giao thông ở khu vực đó lại vô cùng tồi tệ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I wish SBS offered a dormitory for students at the school.\", \"vi\": \"Tôi mong rằng trường SBS sẽ cung cấp ký túc xá cho các em học sinh tại trường.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The quality of instruction was superb.\", \"vi\": \"Chất lượng giảng dạy thật sự xuất sắc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"My lecturer was Diara Rhodes.\", \"vi\": \"Giảng viên của tôi là bà Diara Rhodes.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Though she tended to rush through lectures, discussing a wide range of topics in a small amount of time, I did learn a lot from the reading and from her descriptions of real-world experiences.\", \"vi\": \"Mặc dù cô ấy có xu hướng giảng bài khá vội vàng, đề cập đến rất nhiều chủ đề khác nhau trong một khoảng thời gian ngắn, nhưng tôi thực sự đã học hỏi được rất nhiều từ các tài liệu đọc và từ những chia sẻ của cô ấy về những trải nghiệm thực tế.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"The way she solved business problems was a source of inspiration during my graduate school interview, and it is also helping me in my current classes.\", \"vi\": \"Cách cô ấy giải quyết các vấn đề kinh doanh đã trở thành nguồn cảm hứng cho tôi trong buổi phỏng vấn nhập học chương trình sau đại học, và điều đó cũng đang giúp ích cho tôi trong các môn học hiện tại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Home\", \"vi\": \"Trang chủ\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Classes\", \"vi\": \"Các lớp học\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Reviews\", \"vi\": \"Các đánh giá\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Contact Us\", \"vi\": \"Liên hệ với chúng tôi\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"To: atsushi.koshi@scholarmail.co.uk\", \"vi\": \"Gửi tới: atsushi.koshi@scholarmail.co.uk\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"From: lsommersell@sbs.edu.sg\", \"vi\": \"Nguồn: lsommersell@sbs.edu.sg\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Subject: Your review\", \"vi\": \"Chủ đề: Ý kiến đánh giá của quý vị\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date: 15 August\", \"vi\": \"Ngày: 15 tháng 8\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Dear Mr. Koshi,\", \"vi\": \"Kính gửi ông Koshi,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Thank you for your feedback.\", \"vi\": \"Xin chân thành cảm ơn ý kiến đóng góp của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"You\'re not the first person to voice this particular concern.\", \"vi\": \"Quý vị không phải là người đầu tiên nêu lên mối lo ngại cụ thể này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Just so you know, we plan on addressing it by following your recommendation.\", \"vi\": \"Xin thông báo với quý vị rằng, chúng tôi dự định sẽ giải quyết vấn đề này bằng cách thực hiện theo đề xuất của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Students who take classes with us starting as early as 1 January will be able to take advantage of this new benefit.\", \"vi\": \"Các học viên đăng ký học tại trung tâm của chúng tôi ngay từ ngày 1 tháng 1 sẽ có cơ hội được hưởng lợi ích mới này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Please be sure to mention this to anyone you know who is thinking about taking a class with us.\", \"vi\": \"Xin vui lòng nhớ đề cập điều này với bất kỳ ai mà quý vị biết đang có ý định tham gia một khóa học tại trung tâm của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Kind regards,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Lauri Sommersell\", \"vi\": \"Lauri Sommersell\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = 'ad9e418c-5d68-421f-80e3-2a194f84d3ed';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Tom Sanchez <tsanchez65@mailcurrent.net>\", \"vi\": \"Gửi tới: Tom Sanchez <tsanchez65@mailcurrent.net>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Jun Osman <josman@oregonartmuseum.org>\", \"vi\": \"Từ: Jun Osman <josman@oregonartmuseum.org>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: September 19\", \"vi\": \"Ngày: 19 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: New museum wing opening\", \"vi\": \"Chủ đề: Lễ khai trương khu mới của bảo tàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Sanchez:\", \"vi\": \"Kính gửi ông Sanchez:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Your presence is requested at the official opening of the Oregon Art Museum’s Prosner Wing.\", \"vi\": \"Kính mời quý vị tham dự lễ khai trương chính thức Cánh Prosner của Bảo tàng Nghệ thuật Oregon.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The ceremony will be held on November 3 at 6:00 P.M. Appetizers and drinks will be served.\", \"vi\": \"Buổi lễ sẽ diễn ra vào ngày 3 tháng 11 lúc 6 giờ chiều. Tại buổi lễ sẽ có phục vụ các món khai vị và đồ uống.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Our first featured artist, Taro Mifune, will be on hand to mingle with the crowd and discuss his exhibit, Oregonian Reflections.\", \"vi\": \"Nghệ sĩ đầu tiên được giới thiệu của chúng tôi, ông Taro Mifune, sẽ có mặt tại sự kiện để giao lưu với quý vị và chia sẻ về triển lãm của ông, mang tên “Oregonian Reflections”.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"This private celebration is limited to invaluable museum members like you.\", \"vi\": \"Buổi lễ kỷ niệm riêng tư này chỉ dành riêng cho các thành viên quý báu của bảo tàng như quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You may bring one guest to the event.\", \"vi\": \"Quý vị có thể mời một khách tham dự sự kiện này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To ensure we have an accurate count of attendees, please respond no later than October 20.\", \"vi\": \"Để đảm bảo chúng tôi có được con số chính xác về số lượng người tham dự, xin vui lòng trả lời chậm nhất vào ngày 20 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Jun Osman\", \"vi\": \"Jun Osman\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Director, Oregon Art Museum\", \"vi\": \"Giám đốc, Bảo tàng Mỹ thuật Oregon\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = 'adc0dd34-00d9-4c95-acc9-a11ac6686ca1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Electronics Plus Express Return Policy\", \"vi\": \"Chính sách đổi trả nhanh của Electronics Plus\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"https://www.electronicsplusexpress.com/returns\", \"vi\": \"https://www.electronicsplusexpress.com/returns\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"All returns require prior authorization.\", \"vi\": \"Tất cả các trường hợp trả hàng đều phải được chấp thuận trước.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Please call during business hours (Monday–Friday 9:00 A.M. to 7:00 P.M. and weekends 10:00 A.M. to 5:00 P.M.) or e-mail Customer Service with your return request to receive a return authorization code.\", \"vi\": \"Xin vui lòng gọi điện trong giờ làm việc (Thứ Hai–Thứ Sáu từ 9 giờ sáng đến 7 giờ tối và cuối tuần từ 10 giờ sáng đến 5 giờ chiều) hoặc gửi email đến Bộ phận Dịch vụ Khách hàng kèm theo yêu cầu trả hàng của quý khách để nhận mã ủy quyền trả hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Defective merchandise may be returned within 30 days of purchase date.\", \"vi\": \"Hàng hóa bị lỗi có thể được trả lại trong vòng 30 ngày kể từ ngày mua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Any new merchandise may be returned within 14 days of purchase date.\", \"vi\": \"Mọi mặt hàng mới đều có thể được trả lại trong vòng 14 ngày kể từ ngày mua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The original box and packaging materials must be included.\", \"vi\": \"Phải kèm theo hộp gốc và các vật liệu đóng gói.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"If you need to return the item by post, the store will issue and e-mail a postage-paid shipping label for you to print at home and attach to your parcel.\", \"vi\": \"Nếu quý khách cần trả lại hàng qua đường bưu điện, cửa hàng sẽ cấp và gửi qua email một nhãn vận chuyển đã thanh toán cước phí để quý khách in tại nhà và dán lên bưu kiện của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The cost of your item will be refunded once it has been received.\", \"vi\": \"Số tiền tương ứng với mặt hàng của quý khách sẽ được hoàn lại ngay sau khi chúng tôi nhận được hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Customer Service contact information is as follows:\", \"vi\": \"Thông tin liên hệ của Bộ phận Dịch vụ Khách hàng như sau:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Phone: 1-800-555-0176\", \"vi\": \"Điện thoại: 1-800-555-0176\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"E-mail: cs@electronicsplusexpress.com\", \"vi\": \"Email: cs@electronicsplusexpress.com\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = 'ae253c26-ae52-41ee-b80e-5c78165513d9';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Housing Specialist Needed\", \"vi\": \"Cần tuyển Chuyên viên Về Nhà ở\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Wallace & Prence Realty is currently seeking a housing specialist to work with our international clients.\", \"vi\": \"Công ty Bất động sản Wallace & Prence hiện đang tìm kiếm một chuyên viên về nhà ở để làm việc với các khách hàng quốc tế của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"We specialize in securing appropriate short-term housing for individuals ______[135] will be working in the Toronto area for only a short time.\", \"vi\": \"Chúng tôi chuyên cung cấp nhà ở ngắn hạn phù hợp cho các cá nhân ______[135] sẽ làm việc tại khu vực Toronto trong một thời gian ngắn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"As part of our client-relations department, the housing specialist ______[136] guidance to clients preparing for temporary relocation.\", \"vi\": \"Là một phần của bộ phận quan hệ khách hàng, chuyên viên về nhà ở ______[136] hướng dẫn cho khách hàng đang chuẩn bị tái định cư tạm thời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"______[137].\", \"vi\": \"______[137].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [137]}, {\"en\": \"The successful candidate must have knowledge of real estate and rental agencies in the Toronto area.\", \"vi\": \"Ứng viên trúng tuyển phải có kiến thức về các cơ quan bất động sản và cho thuê tại khu vực Toronto.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Also required are a minimum of two years of customer-service experience.\", \"vi\": \"Cũng yêu cầu tối thiểu hai năm kinh nghiệm dịch vụ khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Individuals with the necessary ______[138] are encouraged to contact us at recruitment@wallaceprence.ca.\", \"vi\": \"Những cá nhân có đầy đủ ______[138] cần thiết được khuyến khích liên hệ với chúng tôi qua email recruitment@wallaceprence.ca.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [138]}]' WHERE `id` = 'ae3a3804-4313-4bac-9fac-75f144122707';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Bingham Man Receives Award\", \"vi\": \"Một người đàn ông ở Bingham nhận giải thưởng\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"by Timur Kardos\", \"vi\": \"của Timur Kardos\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"9 October—A Bingham native received this year\'s Contributors Award from the Association for the Construction of Steel Bridges (ACSB), a trade organization.\", \"vi\": \"Ngày 9 tháng 10 — Một người con của thị trấn Bingham đã vinh dự nhận Giải thưởng Đóng góp của năm nay do Hiệp hội Xây dựng Cầu Thép (ACSB), một tổ chức ngành, trao tặng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Scott Moore, 66, was presented the award during yesterday\'s annual ACSB meeting in Norwalk.\", \"vi\": \"Ông Scott Moore, 66 tuổi, đã được trao giải thưởng này trong buổi họp thường niên của ACSB diễn ra ngày hôm qua tại Norwalk.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"According to an ACSB press release, the award is given every year to \\\"an individual who has contributed significantly to the betterment of the industry.\\\"\", \"vi\": \"Theo thông cáo báo chí của ACSB, giải thưởng này được trao hàng năm cho “một cá nhân đã có những đóng góp đáng kể vào sự phát triển của ngành.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"ACSB spokesperson Cora Schroeder said, \\\"Mr. Moore devotes his spare time to ensuring quality in our industry.\", \"vi\": \"Bà Cora Schroeder, người phát ngôn của ACSB, cho biết: “Ông Moore dành thời gian rảnh rỗi của mình để đảm bảo chất lượng trong ngành của chúng ta.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"For the past decade, he has dedicated himself to helping the ACSB monitor and refine steel-production standards and practices.\", \"vi\": \"Trong thập kỷ qua, ông đã cống hiến hết mình để hỗ trợ ACSB giám sát và hoàn thiện các tiêu chuẩn cũng như quy trình sản xuất thép.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"This year, he chaired a committee that created an improved set of standards for structural steel used in the construction of bridges.\\\"\", \"vi\": \"Năm nay, ông đã đảm nhiệm chức vụ Chủ tịch một ủy ban chuyên xây dựng bộ tiêu chuẩn hoàn thiện hơn dành cho thép kết cấu được sử dụng trong việc xây dựng cầu.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Mr. Moore was born and raised in Bingham and received his engineering degree from Bingham University.\", \"vi\": \"Ông Moore sinh ra và lớn lên tại Bingham, đồng thời tốt nghiệp ngành Kỹ thuật tại Đại học Bingham.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"After graduating, he worked as a construction steel manager during the building of Bingham\'s new city hall.\", \"vi\": \"Sau khi tốt nghiệp, ông đã đảm nhiệm chức vụ quản lý kết cấu thép trong quá trình xây dựng tòa thị chính mới của thành phố Bingham.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"He joined Marshall Steel 39 years ago as a building supervisor, ultimately rising to his current position of senior project engineer.\", \"vi\": \"Ông gia nhập Công ty Marshall Steel cách đây 39 năm với cương vị giám sát công trình, và sau đó đã thăng tiến lên vị trí hiện tại là kỹ sư dự án cấp cao.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = 'aec0edbc-0452-4bd0-8df5-e40ef6a0acd8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Noora Abadi\", \"vi\": \"Đến: Noora Abadi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Alexis Palmer\", \"vi\": \"Từ: Alexis Palmer\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Informational interview\", \"vi\": \"Chủ đề: Phỏng vấn tìm hiểu thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 4 February\", \"vi\": \"Ngày: 4 tháng 2\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Abadi:\", \"vi\": \"Gửi bà Abadi,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for taking the time to meet with me yesterday about careers in the aerospace industry.\", \"vi\": \"Cảm ơn bà đã dành thời gian gặp tôi vào ngày hôm qua để trao đổi về các cơ hội nghề nghiệp trong ngành hàng không vũ trụ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Your ______[139] were helpful and have inspired me to seek additional work experience in the field before I apply to graduate school.\", \"vi\": \"______[139] của bà rất hữu ích và đã truyền cảm hứng cho tôi tìm kiếm thêm kinh nghiệm làm việc trong lĩnh vực này trước khi nộp hồ sơ học cao học.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [139]}, {\"en\": \"I will consult the Web sites you recommended for job opportunities.\", \"vi\": \"Tôi sẽ tham khảo các trang web mà bà đã giới thiệu để tìm kiếm cơ hội việc làm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"As you also suggested, I will ______[140] a membership in the Eastern Aeronautics Professional Association.\", \"vi\": \"Đúng như bà đã gợi ý, tôi sẽ ______[140] tư cách thành viên của Hiệp hội Chuyên gia Hàng không miền Đông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [140]}, {\"en\": \"______[141].\", \"vi\": \"______[141].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [141]}, {\"en\": \"I appreciate the information you shared about the organization\'s conference at the end of the month.\", \"vi\": \"Tôi rất trân trọng những thông tin bà đã chia sẻ về hội nghị của tổ chức vào cuối tháng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Thank you again for your ______[142] assistance.\", \"vi\": \"Một lần nữa, xin cảm ơn sự hỗ trợ ______[142] của bà.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [142]}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Alexis Palmer\", \"vi\": \"Alexis Palmer\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = 'aed64d54-e300-4116-982e-c0ee8bdb2c54';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Baardsen Laundry Machine Series\", \"vi\": \"Dòng máy giặt Baardsen\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Model - Load Capacity - Loading Door Position - Automatic Detergent Dispenser - Pre-wash Cycle\", \"vi\": \"Mẫu máy - Khả năng chứa - Vị trí cửa nạp - Hộp đựng chất tẩy rửa tự động - Chương trình giặt sơ bộ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Lute - 9 kg - Front - Yes - No\", \"vi\": \"Lute - 9 kg - Mặt trước - Có - Không\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Xenon - 10 kg - Front - No - No\", \"vi\": \"Xenon - 10 kg - Phía trước - Không - Không\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Indium - 12 kg - Front - Yes - Yes\", \"vi\": \"Indium - 12 kg - Mặt trước - Có - Có\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Mercury - 14 kg - Front - Yes - Yes\", \"vi\": \"Thủy ngân - 14 kg - Phía trước - Có - Có\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Note: Baardsen washers with a load size greater than 10 kg are outfitted with Fluxstat water-saving technology.\", \"vi\": \"Lưu ý: Các máy giặt Baardsen có sức chứa trên 10 kg đều được trang bị công nghệ tiết kiệm nước Fluxstat.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Issue with Baardsen\", \"vi\": \"Vấn đề liên quan đến Baardsen\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Posted by: Patricia Canton\", \"vi\": \"Đăng bởi: Patricia Canton\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I bought my Baardsen washing machine five months ago for use at my bed and breakfast inn.\", \"vi\": \"Tôi đã mua chiếc máy giặt Baardsen cách đây năm tháng để sử dụng tại nhà trọ của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Overall, I have been satisfied with the appliance features.\", \"vi\": \"Nhìn chung, tôi cảm thấy hài lòng với các tính năng của thiết bị này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The extra rinse cycle is helpful for guests who are sensitive to chemicals or perfumes in laundry detergent.\", \"vi\": \"Chế độ xả thêm rất hữu ích cho những vị khách có làn da nhạy cảm với các chất hóa học hoặc hương liệu có trong bột giặt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I needed a washer with the largest capacity so it could handle my typical volume of bed linens and towels.\", \"vi\": \"Tôi cần một chiếc máy giặt có dung tích lớn nhất để có thể giặt được lượng khăn tắm và bộ chăn ga gối đệm mà tôi thường sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The main issue with my machine has been an annoying banging sound.\", \"vi\": \"Vấn đề chính của chiếc máy của tôi là tiếng va đập khó chịu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"It happens sometimes when the guests use the machine.\", \"vi\": \"Đôi khi tình trạng này xảy ra khi quý khách sử dụng máy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"It is a problem because the laundry room is situated just off the patio where guests often dine.\", \"vi\": \"Điều này gây ra vấn đề vì phòng giặt nằm ngay cạnh sân hiên, nơi khách thường dùng bữa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I sent a message to the company asking for help and they informed me that the load needs to be evenly distributed in the wash tub.\", \"vi\": \"Tôi đã gửi tin nhắn đến công ty để xin hỗ trợ và họ thông báo với tôi rằng cần phải phân bổ đều lượng đồ giặt trong thùng giặt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"But that didn\'t prove to be the source of the problem.\", \"vi\": \"Tuy nhiên, điều đó hóa ra lại không phải là nguyên nhân gốc rễ của vấn đề.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"How can I get rid of this noise?\", \"vi\": \"Làm thế nào để tôi có thể loại bỏ tiếng ồn này?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Patty\'s Bed and Breakfast Guest Services:\", \"vi\": \"Các dịch vụ dành cho khách tại Nhà nghỉ Patty\'s Bed and Breakfast:\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Kitchen:\", \"vi\": \"Nhà bếp:\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Enjoy the lovely spring weather by taking your breakfast, served between 8:00 and 9:30 A.M., on the patio.\", \"vi\": \"Hãy tận hưởng thời tiết mùa xuân tuyệt vời bằng cách dùng bữa sáng — được phục vụ từ 8:00 đến 9:30 sáng — tại sân hiên.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"We offer self-service for coffee and tea around the clock.\", \"vi\": \"Chúng tôi cung cấp dịch vụ tự phục vụ cà phê và trà suốt cả ngày đêm.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"The household coffeemaker and tea kettle are next to the stove, and supplies are stored in the cupboard nearby.\", \"vi\": \"Máy pha cà phê và ấm đun nước trong nhà được đặt bên cạnh bếp, còn các vật dụng thì được cất trong tủ gần đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Laundry Room:\", \"vi\": \"Phòng giặt ủi:\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Fresh towels are provided daily and bed linens are changed weekly.\", \"vi\": \"Khăn tắm sạch được cung cấp hàng ngày và bộ chăn ga gối được thay mới hàng tuần.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"If you would like to use the washing machine, please choose the eco-saving setting.\", \"vi\": \"Nếu quý vị muốn sử dụng máy giặt, xin vui lòng chọn chế độ tiết kiệm năng lượng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Select your preferred temperature and power setting.\", \"vi\": \"Vui lòng chọn mức nhiệt độ và công suất mong muốn.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"When adding detergent, make sure the detergent drawer is closed tightly before you start the machine.\", \"vi\": \"Khi cho bột giặt vào, xin vui lòng đảm bảo ngăn chứa bột giặt đã được đóng chặt trước khi khởi động máy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"If not properly secured, it may open during the rinse cycle and cause a bothersome noise.\", \"vi\": \"Nếu không được cố định đúng cách, nó có thể bị mở ra trong chu trình xả và gây ra tiếng ồn khó chịu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Also, the extra-rinse option is recommended if you have any sensitivity to laundry soap.\", \"vi\": \"Ngoài ra, quý vị nên sử dụng chế độ xả thêm nếu da quý vị nhạy cảm với bột giặt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Patricia Canton, Proprietor\", \"vi\": \"Bà Patricia Canton, Chủ sở hữu\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}]' WHERE `id` = 'aedfda26-e87f-49c0-a6cd-fab7590e3c5d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Mapleglen University\", \"vi\": \"Đại học Mapleglen\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Master of Business Administration\", \"vi\": \"Thạc sĩ Quản trị Kinh doanh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"At Mapleglen University, we understand that December is a ------- (135) time of year for undergraduates.\", \"vi\": \"Tại Đại học Mapleglen, chúng tôi hiểu rằng tháng 12 là một khoảng thời gian ------- (135) đối với các sinh viên đại học.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"That is why we are giving you extra time to submit your application for our Master of Business Administration (MBA) program.\", \"vi\": \"Đó là lý do tại sao chúng tôi dành cho bạn thêm thời gian để nộp đơn đăng ký vào chương trình Thạc sĩ Quản trị Kinh doanh (MBA) của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We have extended our initial deadline to December 31.\", \"vi\": \"Chúng tôi đã gia hạn thời hạn ban đầu đến ngày 31 tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"------- (136) for admission to the March semester, please ensure that we receive your official undergraduate transcripts by the same date.\", \"vi\": \"------- (136) để được tuyển sinh vào học kỳ tháng 3, vui lòng đảm bảo rằng chúng tôi nhận được bảng điểm đại học chính thức của bạn trước cùng ngày đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [136]}, {\"en\": \"Please contact our admissions department at apply@mapleglen.edu if you have any questions ------- (137) the MBA program requirements.\", \"vi\": \"Vui lòng liên hệ với bộ phận tuyển sinh của chúng tôi theo địa chỉ apply@mapleglen.edu nếu bạn có bất kỳ câu hỏi nào ------- (137) về các yêu cầu của chương trình MBA.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [137]}, {\"en\": \"------- (138).\", \"vi\": \"------- (138).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [138]}]' WHERE `id` = 'aef1dbe6-39f1-411b-9b25-137bf6f7d0d7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Fill-Your-Cup Day Returns\", \"vi\": \"Ngày hội Đầy Cốc Trở Lại\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"COLUMBUS (June 16)—Nationwide convenience store chain Abel\'s Market is announcing the return of a well-known promotion not seen in three years.\", \"vi\": \"COLUMBUS (Ngày 16 tháng 6)—Chuỗi cửa hàng tiện lợi toàn quốc Abel\'s Market đang thông báo sự trở lại của một chương trình khuyến mãi nổi tiếng đã vắng bóng trong ba năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"On June 22, customers ___135____ their own cups to participating Abel\'s Markets to receive half-price fountain drinks.\", \"vi\": \"Vào ngày 22 tháng 6, khách hàng ___135____ những chiếc cốc của riêng họ đến các cửa hàng Abel\'s Market tham gia chương trình để được giảm nửa giá đồ uống có ga.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"The retailer urges creativity when defining a cup and posted a picture of a flower vase filled with soda as an example on ___136____ social media account.\", \"vi\": \"Nhà bán lẻ này thúc đẩy sự sáng tạo khi định nghĩa thế nào là một chiếc cốc và đã đăng một bức ảnh chụp bình hoa đựng đầy nước ngọt làm ví dụ trên tài khoản mạng xã hội ___136____ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"___137____ .\", \"vi\": \"___137____ .\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [137]}, {\"en\": \"Abel\'s Market encourages customers to post pictures of their creative cups to their own social media accounts and to mention the company in their posts.\", \"vi\": \"Abel\'s Market khuyến khích khách hàng đăng ảnh những chiếc cốc sáng tạo của họ lên tài khoản mạng xã hội của chính họ và nhắc đến công ty trong các bài đăng của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Abel\'s Market has not stated whether Fill-Your-Cup Day will become an annual event as it ___138____ was.\", \"vi\": \"Abel\'s Market chưa cho biết liệu Ngày hội Đầy Cốc có trở thành một sự kiện hàng năm như trước đây nó ___138____ từng có hay không.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [138]}]' WHERE `id` = 'af156b93-430b-48ff-99ce-1f2cfcd159ec';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"GLEASON INTERNATIONAL AIRPORT (GIA)\", \"vi\": \"SÂN BAY QUỐC TẾ GLEASON (GIA)\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.gleason.com\", \"vi\": \"http://www.gleason.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Announcement Regarding Misplaced Baggage\", \"vi\": \"Thông báo về hành lý bị thất lạc\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"NEWS & NOTICES\", \"vi\": \"TIN TỨC & THÔNG BÁO\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Following the recent delay or cancellation of many flights due to winter weather, GIA has accumulated several hundred pieces of misplaced baggage.\", \"vi\": \"Do tình trạng nhiều chuyến bay gần đây bị hoãn hoặc hủy vì thời tiết mùa đông, GIA đã thu nhận được vài trăm kiện hành lý bị thất lạc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The baggage is currently being kept securely in a temporary enclosure on our second floor, near the Domestic Departures Information Desk.\", \"vi\": \"Hiện tại, hành lý đang được bảo quản an toàn tại một khu vực tạm thời ở tầng hai của chúng tôi, gần Quầy Thông tin Khởi hành Nội địa.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As the location and delivery of misplaced baggage is ultimately the airline\'s responsibility, owners of lost bags should begin by filing a report with their airline.\", \"vi\": \"Vì việc xác định vị trí và giao trả hành lý bị thất lạc cuối cùng là trách nhiệm của hãng hàng không, nên chủ sở hữu của những kiện hành lý bị thất lạc cần bắt đầu bằng việc làm thủ tục khai báo với hãng hàng không của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"However, in order to ensure that the baggage is dispersed in a timely fashion, we are also allowing people to search for their bags themselves.\", \"vi\": \"Tuy nhiên, nhằm đảm bảo hành lý được phân phát kịp thời, chúng tôi cũng cho phép quý khách tự tìm kiếm hành lý của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"To do so, bring your airline ticket and luggage tag, along with a valid form of identification, to the entrance of the enclosure.\", \"vi\": \"Để thực hiện việc này, quý vị vui lòng mang theo vé máy bay và thẻ hành lý, cùng với một loại giấy tờ tùy thân còn hiệu lực, đến cổng vào khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"A staff member will check your documentation and then escort you inside to search.\", \"vi\": \"Một nhân viên sẽ kiểm tra các giấy tờ của quý vị, sau đó sẽ dẫn quý vị vào trong để tiến hành kiểm tra.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"If you have questions about this process, please call our Customer Support Team at 555-0176.\", \"vi\": \"Nếu quý vị có thắc mắc về quy trình này, xin vui lòng liên hệ với Đội ngũ Hỗ trợ Khách hàng của chúng tôi theo số 555-0176.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = 'af4f691a-1305-4a71-8a66-8dd4e9c56a36';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Stay in Style!\", \"vi\": \"Hãy luôn sành điệu!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"QRN Airport invites travelers to experience our new Repose Lounge.\", \"vi\": \"Sân bay QRN trân trọng mời quý khách hàng đến trải nghiệm khu vực chờ Repose Lounge mới của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Just like Repose Lounges in other airports, it offers a peaceful, comfortable space where you can unwind if you have a long layover between flights, have arrived early for a flight, or are dealing with an unexpected delay.\", \"vi\": \"Cũng giống như các khu vực Repose Lounges tại các sân bay khác, nơi đây mang đến một không gian yên tĩnh và thoải mái, nơi quý vị có thể thư giãn nếu phải chờ đợi lâu giữa các chuyến bay, đến sân bay sớm trước giờ khởi hành hoặc đang phải đối mặt với tình huống chuyến bay bị hoãn ngoài dự kiến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The Repose Lounge is open daily between 5:00 A.M. and 8:30 P.M. and features the following amenities:\", \"vi\": \"Khu vực Repose Lounge mở cửa hàng ngày từ 5 giờ sáng đến 8 giờ 30 tối và cung cấp các tiện nghi sau đây:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"✓ A private conference room for meetings and calls\", \"vi\": \"✓ Một phòng hội nghị riêng dành cho các cuộc họp và các cuộc gọi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"✓ Printing and copying services\", \"vi\": \"✓ Dịch vụ in ấn và photocopy\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"✓ Wi-Fi and charging stations\", \"vi\": \"✓ Wi-Fi và trạm sạc\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"✓ Beverages, baked goods, and snacks\", \"vi\": \"✓ Đồ uống, các loại bánh và đồ ăn nhẹ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"✓ A selection of current newspapers and magazines\", \"vi\": \"✓ Một số ấn phẩm báo chí và tạp chí mới nhất\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Repose Lounge passes are available for $180 and are valid for one year from the date of purchase.\", \"vi\": \"Thẻ thành viên Repose Lounge có giá 180 đô la và có hiệu lực trong một năm kể từ ngày mua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To access a Repose Lounge, guests must present a government-issued photo ID and a same-day boarding pass.\", \"vi\": \"Để được vào khu vực Repose Lounge, quý khách phải xuất trình giấy tờ tùy thân có ảnh do cơ quan nhà nước cấp và thẻ lên máy bay của chuyến bay trong ngày hôm đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To celebrate the grand opening at QRN Airport, we are offering Repose Lounge passes at half price between March 15 and March 30.\", \"vi\": \"Nhân dịp lễ khai trương tại Sân bay QRN, chúng tôi xin trân trọng thông báo chương trình giảm giá 50% cho vé vào Repose Lounge trong khoảng thời gian từ ngày 15 đến ngày 30 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To obtain a pass or make a reservation, go to www.qrnairport.com/repose or visit the service desk just outside the lounge in terminal B.\", \"vi\": \"Để nhận thẻ vào cửa hoặc đặt chỗ, quý vị vui lòng truy cập trang web www.qrnairport.com/repose hoặc đến quầy dịch vụ ngay bên ngoài phòng chờ tại nhà ga B.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = 'afafddd0-6882-41de-92f4-3bfe66a7bf4c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: support@volunix.com\", \"vi\": \"Nguồn: support@volunix.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Amrita Das <adas@myfastmail.com>\", \"vi\": \"Gửi tới: Amrita Das <adas@myfastmail.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Sent: September 6\", \"vi\": \"Ngày gửi: 6 tháng 9\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Incident 030924\", \"vi\": \"Chủ đề: Sự cố 030924\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Valued Customer:\", \"vi\": \"Kính gửi Quý khách hàng thân mến:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for contacting Volunix Ltd., the online store for medical supplies.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã liên hệ với Volunix Ltd., cửa hàng trực tuyến chuyên cung cấp vật tư y tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"We apologize for the technical difficulty you are experiencing with your online purchase.\", \"vi\": \"Chúng tôi xin lỗi về sự cố kỹ thuật mà quý khách đang gặp phải trong quá trình mua hàng trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Your support ticket was submitted on Wednesday, September 6, at 10:12 p.m. You can track the status of your incident by using the \\\"case status\\\" feature.\", \"vi\": \"Yêu cầu hỗ trợ của quý vị đã được gửi vào thứ Tư, ngày 6 tháng 9, lúc 10 giờ 12 phút tối. Quý vị có thể theo dõi tình trạng sự cố của mình bằng cách sử dụng tính năng “tình trạng yêu cầu hỗ trợ”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"You can also use this feature to add information to the ticket at any time.\", \"vi\": \"Quý vị cũng có thể sử dụng tính năng này để bổ sung thông tin vào phiếu yêu cầu bất cứ lúc nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The Volunix team responds to support issues as quickly as possible.\", \"vi\": \"Đội ngũ Volunix sẽ giải quyết các vấn đề liên quan đến hỗ trợ trong thời gian sớm nhất có thể.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"During regular business hours (8 a.m. to 6 p.m., Monday through Friday), you can expect a response within one hour.\", \"vi\": \"Trong giờ làm việc thông thường (từ 8 giờ sáng đến 6 giờ chiều, từ thứ Hai đến thứ Sáu), quý vị sẽ nhận được phản hồi trong vòng một giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Tickets submitted after business hours and on weekends will be responded to before noon of the following business day.\", \"vi\": \"Các yêu cầu được gửi sau giờ làm việc và vào cuối tuần sẽ được giải đáp trước 12 giờ trưa của ngày làm việc tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin chân thành cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The Volunix Web Team\", \"vi\": \"Nhóm Web Volunix\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = 'afb31b70-9aa6-4f56-8d3b-2aed83403099';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Jacinto Business Institute (JBI)\", \"vi\": \"Viện Kinh doanh Jacinto (JBI)\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"http://www.jacintobusinessinstitute.com ▶\", \"vi\": \"http://www.jacintobusinessinstitute.com ▶\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Whether you are just starting out in the business world or looking for ways to expand your operations, JBI offers a variety of low-priced seminars taught by successful entrepreneurs from top businesses in the region.\", \"vi\": \"Dù quý vị mới bắt đầu bước chân vào thế giới kinh doanh hay đang tìm kiếm các phương án để mở rộng quy mô hoạt động, JBI đều cung cấp nhiều khóa hội thảo với mức phí hợp lý, do các doanh nhân thành đạt đến từ những doanh nghiệp hàng đầu trong khu vực trực tiếp giảng dạy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Check out our upcoming seminars that will meet weekly in February!\", \"vi\": \"Hãy tham khảo các buổi hội thảo sắp tới của chúng tôi, sẽ được tổ chức hàng tuần trong tháng Hai!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Basic Financing for Small Businesses\", \"vi\": \"Các hình thức tài chính cơ bản dành cho doanh nghiệp nhỏ\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This seminar will review traditional and practical ways to finance your business.\", \"vi\": \"Hội thảo này sẽ điểm qua các phương thức truyền thống và thiết thực để huy động vốn cho doanh nghiệp của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Saturdays, 12:30 P.M. to 3:00 P.M.\", \"vi\": \"Thứ Bảy, từ 12 giờ 30 phút trưa đến 3 giờ chiều\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Starting Out in Leadership\", \"vi\": \"Những bước đầu tiên trên con đường lãnh đạo\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"For those new to management, this seminar will examine essential techniques that focus on productivity and positive workforce motivation.\", \"vi\": \"Đối với những ai mới bước vào lĩnh vực quản lý, hội thảo này sẽ đi sâu tìm hiểu các kỹ thuật thiết yếu, tập trung vào năng suất lao động và việc khơi dậy động lực tích cực cho đội ngũ nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Tuesdays and Thursdays, 7:00 P.M. to 9:30 P.M.\", \"vi\": \"Thứ Ba và Thứ Năm, từ 7 giờ tối đến 9 giờ 30 tối.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Promoting Your Business\", \"vi\": \"Quảng bá doanh nghiệp của quý vị\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Explore strategies for effectively advertising and expanding your business.\", \"vi\": \"Hãy tìm hiểu các chiến lược nhằm quảng bá và mở rộng hoạt động kinh doanh của quý vị một cách hiệu quả.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Mondays, 6:00 P.M. to 9:00 P.M.\", \"vi\": \"Thứ Hai, từ 6 giờ chiều đến 9 giờ tối\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Planning a Successful Start-Up\", \"vi\": \"Lập kế hoạch cho một công ty khởi nghiệp thành công\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Before you open for business, prepare a detailed plan of your concept using time-honored strategies.\", \"vi\": \"Trước khi chính thức đi vào hoạt động, quý vị hãy lập một kế hoạch chi tiết về ý tưởng kinh doanh của mình bằng cách áp dụng các chiến lược đã được thời gian kiểm chứng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Tuesdays, 5:00 P.M. to 8:00 P.M.\", \"vi\": \"Thứ Ba, từ 5 giờ chiều đến 8 giờ tối\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Notice\", \"vi\": \"Thông báo\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Ting Yang to lead JBI seminar\", \"vi\": \"Ông Ting Yang sẽ chủ trì hội thảo của JBI\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"We are delighted to have Ms. Ting Yang joining us in February.\", \"vi\": \"Chúng tôi rất vui mừng chào đón bà Ting Yang gia nhập đội ngũ của chúng tôi vào tháng Hai.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"She earned a master\'s degree in marketing from Julem University and started out at Wister Point, Inc., where she rose to the position of marketing director.\", \"vi\": \"Bà đã tốt nghiệp thạc sĩ chuyên ngành tiếp thị tại Đại học Julem và bắt đầu sự nghiệp tại công ty Wister Point, Inc., nơi bà đã thăng tiến lên vị trí giám đốc tiếp thị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"The company\'s revenue increased greatly during Ms. Yang\'s tenure.\", \"vi\": \"Doanh thu của công ty đã tăng lên đáng kể trong thời gian bà Yang đảm nhiệm chức vụ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"After fifteen years at Wister Point, Ms. Yang joined the successful advertising consulting firm Marvin and Rhodes Advisers.\", \"vi\": \"Sau mười lăm năm làm việc tại Wister Point, bà Yang đã gia nhập công ty tư vấn quảng cáo thành công Marvin and Rhodes Advisers.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Take advantage of this opportunity to benefit from her considerable expertise and sign up for her seminar today!\", \"vi\": \"Hãy tận dụng cơ hội này để học hỏi từ những kiến thức chuyên môn sâu rộng của bà và đăng ký tham dự hội thảo của bà ngay hôm nay!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"To: Jacinto Business Institute <contactus@jacintobusinessinstitute.com>\", \"vi\": \"Gửi tới: Viện Kinh doanh Jacinto <contactus@jacintobusinessinstitute.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"From: Gabriela Torres <gtorres@flowersbygabriela.com>\", \"vi\": \"Từ: Gabriela Torres <gtorres@flowersbygabriela.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Date: March 3\", \"vi\": \"Ngày: 3 tháng 3\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Subject: February seminar\", \"vi\": \"Chủ đề: Hội thảo tháng Hai\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Greetings,\", \"vi\": \"Kính gửi,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"The seminar I attended proved valuable.\", \"vi\": \"Hội thảo mà tôi đã tham dự thực sự rất hữu ích.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I have long admired Ms. Yang.\", \"vi\": \"Tôi từ lâu đã rất ngưỡng mộ bà Yang.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"In fact, she was a department director at the same firm where I first worked after university.\", \"vi\": \"Thực ra, bà ấy từng là giám đốc bộ phận tại chính công ty mà tôi đã làm việc lần đầu tiên sau khi tốt nghiệp đại học.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Now that I am looking to grow the business I recently started, the chance to learn from her insights has been very helpful.\", \"vi\": \"Hiện tại, khi tôi đang tìm cách phát triển doanh nghiệp mà mình mới thành lập gần đây, cơ hội được học hỏi từ những kinh nghiệm quý báu của cô ấy đã mang lại cho tôi rất nhiều lợi ích.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I hope she will return to lead other seminars at your institute.\", \"vi\": \"Tôi hy vọng bà ấy sẽ quay lại để chủ trì các hội thảo khác tại viện của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"All the best,\", \"vi\": \"Chúc quý vị mọi điều tốt đẹp nhất,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Gabriela Torres\", \"vi\": \"Gabriela Torres\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}]' WHERE `id` = 'afb4530b-bdd8-4142-8a2c-ecd360668a0a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"NEW HAVEN (June 1)—Marco’s Italian Restaurant on Frontage Road will be reopening in late June.\", \"vi\": \"NEW HAVEN (ngày 1 tháng 6) — Nhà hàng Ý Marco’s trên đường Frontage Road sẽ mở cửa trở lại vào cuối tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"It closed three months ago after a water leak caused extensive damage to the kitchen.\", \"vi\": \"Nơi này đã đóng cửa cách đây ba tháng sau khi một vụ rò rỉ nước gây ra thiệt hại nghiêm trọng cho khu vực bếp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"A significant amount of work needed to be done in the kitchen and dining areas.\", \"vi\": \"Có rất nhiều việc cần phải thực hiện tại khu vực bếp và phòng ăn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The restaurant will accommodate larger parties when it reopens.\", \"vi\": \"Khi nhà hàng mở cửa trở lại, nơi đây sẽ có thể phục vụ các nhóm khách đông người hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"During the past three months, many of the restaurant’s employees were able to work at Marco’s Italian Market, which is located on the opposite side of the street.\", \"vi\": \"Trong ba tháng qua, nhiều nhân viên của nhà hàng đã có cơ hội làm việc tại Marco’s Italian Market, nằm ở phía đối diện của con phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"“The leak happened right before the market’s busy season started,” said Tom Marco, who owns both businesses.\", \"vi\": \"“Sự cố rò rỉ xảy ra ngay trước khi mùa cao điểm của thị trường bắt đầu,” ông Tom Marco, người sở hữu cả hai doanh nghiệp, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"“We needed to add staff there temporarily, and I was happy to keep my restaurant crew employed.”\", \"vi\": \"“Chúng tôi cần bổ sung nhân sự tạm thời tại đó, và tôi rất vui vì đã có thể giúp đội ngũ nhân viên nhà hàng của mình tiếp tục có việc làm.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Most of those employees have now returned to work in the restaurant.\", \"vi\": \"Hiện nay, phần lớn những nhân viên đó đã quay trở lại làm việc tại nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Mr. Marco has planned a grand reopening for June 25.\", \"vi\": \"Ông Marco đã lên kế hoạch tổ chức một buổi khai trương lại hoành tráng vào ngày 25 tháng 6.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Guests will enjoy live music and a new tasting menu.\", \"vi\": \"Quý khách sẽ được thưởng thức nhạc sống cùng thực đơn nếm thử mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Reservations are required for the day of the celebration and can be made by calling 203-555-0124.\", \"vi\": \"Quý vị cần đặt chỗ trước cho ngày diễn ra lễ kỷ niệm và có thể thực hiện việc này bằng cách gọi đến số 203-555-0124.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"“We are excited to be able to prepare our traditional dishes and welcome the community back again,” stated Mr. Marco.\", \"vi\": \"“Chúng tôi rất hân hoan khi có thể chuẩn bị những món ăn truyền thống của mình và một lần nữa được chào đón cộng đồng quay trở lại,” ông Marco phát biểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = 'afdda604-2c7e-49ed-b32e-6159e8994840';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Jun Kambayashi [10:12 A.M.]\", \"vi\": \"Jun Kambayashi [10 giờ 12 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Rachel, it looks as if Mr. Tanaka\'s flight will be arriving 30 minutes earlier this afternoon.\", \"vi\": \"Rachel ạ, có vẻ như chuyến bay của ông Tanaka sẽ hạ cánh sớm hơn 30 phút vào chiều nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I\'m on my way to pick him up.\", \"vi\": \"Tôi đang trên đường đi đón anh ấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Rachel Newman [10:13 A.M.]\", \"vi\": \"Rachel Newman [10 giờ 13 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"The staff are excited that he finally is going to be working with us here.\", \"vi\": \"Các nhân viên đều rất háo hức vì cuối cùng anh ấy cũng sẽ làm việc cùng chúng tôi tại đây.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Do you think the two of you have time to stop here in the office before the end of the workday?\", \"vi\": \"Theo anh/chị, hai người có thời gian ghé qua văn phòng này trước khi kết thúc giờ làm việc không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Jun Kambayashi [10:14 A.M.]\", \"vi\": \"Jun Kambayashi [10 giờ 14 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Probably.\", \"vi\": \"Có lẽ vậy.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"And I agree; Mr. Tanaka has done great work at our Chiba branch.\", \"vi\": \"Và tôi cũng đồng ý; ông Tanaka đã hoàn thành xuất sắc công việc tại chi nhánh Chiba của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Rachel Newman [10:15 A.M.]\", \"vi\": \"Rachel Newman [10 giờ 15 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"So I\'ve always heard.\", \"vi\": \"Tôi cũng đã nghe nói như vậy từ trước đến nay.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"It would be nice for him to get a quick tour of the lab and meet some members of the team before our welcome dinner.\", \"vi\": \"Sẽ thật tuyệt nếu anh ấy có thể tham quan nhanh phòng thí nghiệm và gặp gỡ một số thành viên trong nhóm trước bữa tối chào mừng của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Jun Kambayashi [10:16 A.M.]\", \"vi\": \"Jun Kambayashi [10 giờ 16 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sounds good.\", \"vi\": \"Nghe có vẻ hay đấy.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Since flight schedules can be unpredictable, I\'ll keep you posted as I arrive at the airport.\", \"vi\": \"Vì lịch bay có thể thay đổi bất ngờ, tôi sẽ thông báo cho quý vị ngay khi tôi đến sân bay.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Rachel Newman [10:17 A.M.]\", \"vi\": \"Rachel Newman [10 giờ 17 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Perfect.\", \"vi\": \"Hoàn hảo.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"See you later.\", \"vi\": \"Hẹn gặp lại sau.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = 'affa371c-1759-4110-aebc-806191dfa819';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Ment Hall to Host Piasek Cup Final\", \"vi\": \"Ment Hall sẽ là nơi tổ chức trận chung kết Piasek Cup\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Ment Hall, which is currently undergoing extensive renovation, will be ready to host the final game of the Piasek Cup Volleyball Championship to be held in Warsaw this June.\", \"vi\": \"Sân vận động Ment Hall, hiện đang được cải tạo quy mô lớn, sẽ sẵn sàng đón tiếp trận chung kết Giải vô địch bóng chuyền Piasek Cup dự kiến diễn ra tại Warsaw vào tháng 6 năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Although the project has been in the works for some time, it was the opportunity to host this championship that provided the economic incentive to push the project to its completion.\", \"vi\": \"Mặc dù dự án này đã được triển khai từ một thời gian, nhưng chính cơ hội được đăng cai giải vô địch này đã tạo ra động lực kinh tế để thúc đẩy dự án đi đến giai đoạn hoàn thành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"City officials have confirmed that the construction is progressing according to schedule and will be complete well before the finals of the championship.\", \"vi\": \"Các quan chức thành phố đã xác nhận rằng công trình đang được triển khai đúng tiến độ và sẽ hoàn thành trước khi diễn ra trận chung kết của giải vô địch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Since Ment Hall is the only major arena in the country that has never hosted a Piasek Cup event, the hall\'s owners were proud to have been chosen to host this year\'s finale.\", \"vi\": \"Vì Ment Hall là nhà thi đấu lớn duy nhất trong cả nước chưa từng tổ chức sự kiện Piasek Cup, nên ban quản lý nhà thi đấu này đã rất tự hào khi được chọn làm nơi đăng cai trận chung kết năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The final game will inaugurate the refurbished hall.\", \"vi\": \"Trận đấu cuối cùng sẽ đánh dấu lễ khánh thành hội trường vừa được tu sửa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The event is expected to draw thousands of volleyball fans, and the organizers are confident that Ment Hall will live up to the occasion.\", \"vi\": \"Sự kiện này dự kiến sẽ thu hút hàng nghìn người hâm mộ bóng chuyền, và ban tổ chức tin tưởng rằng Ment Hall sẽ đáp ứng được kỳ vọng của sự kiện này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Seating 19,000 spectators, Ment Hall will be double its previous size.\", \"vi\": \"Với sức chứa 19.000 khán giả, Ment Hall sẽ có quy mô gấp đôi so với trước đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Venezuela-Australia\\n10 June, 3:00 P.M.\\nLoave Arena, Bydgoszcz - Poland-France\\n10 June, 6:00 P.M.\\nTimpani Hall, Katowice - Brazil-USA\\n11 June, 3:00 P.M.\\nPolana Center, Cracow - Cuba-Egypt\\n11 June, 6:00 P.M.\\nMistrz Arena, Wroclaw\", \"vi\": \"Venezuela - Úc\\nNgày 10 tháng 6, 3 giờ chiều\\nSân vận động Loave, Bydgoszcz - Ba Lan - Pháp\\nNgày 10 tháng 6, 6 giờ chiều\\nNhà thi đấu Timpani, Katowice - Brazil - Hoa Kỳ\\nNgày 11 tháng 6, 3 giờ chiều\\nPolana Center, Kraków - Cuba - Ai Cập\\nNgày 11 tháng 6, 6 giờ chiều\\nMistrz Arena, Wrocław\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Winners of 10 June games\\n13 June, 3:00 P.M.\\nTimpani Hall, Katowice - Winners of 11 June games\\n13 June, 3:00 P.M.\\nPolana Center, Cracow\", \"vi\": \"Các đội chiến thắng trong các trận đấu ngày 10 tháng 6\\nNgày 13 tháng 6, 3 giờ chiều\\nTimpani Hall, Katowice - Các đội chiến thắng trong các trận đấu ngày 11 tháng 6\\nNgày 13 tháng 6, 3 giờ chiều\\nTrung tâm Polana, Kraków\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Piasek Cup Volleyball Championship\", \"vi\": \"Giải vô địch bóng chuyền Piasek Cup\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Quarterfinal Games\", \"vi\": \"Các trận đấu vòng tứ kết\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Semifinal Games\", \"vi\": \"Các trận bán kết\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Final Game\", \"vi\": \"Trận đấu cuối cùng\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"16 June, 6:00 P.M.\", \"vi\": \"Ngày 16 tháng 6, 6 giờ chiều\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Ment Hall, Warsaw\", \"vi\": \"Ment Hall, Warsaw\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"NOTE: Tickets for the final game are selling fast, so don\'t wait until after the semifinal games to order.\", \"vi\": \"LƯU Ý: Vé xem trận chung kết đang được bán rất nhanh, vì vậy xin đừng chờ đến sau khi các trận bán kết kết thúc mới đặt vé.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Reserved seating only, no general admission.\", \"vi\": \"Chỉ dành cho chỗ ngồi đã đặt trước, không có vé vào cửa tự do.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"No refunds.\", \"vi\": \"Không hoàn tiền.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"News Update\", \"vi\": \"Cập nhật tin tức\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"HALLAX RADIO 108.3 FM\", \"vi\": \"Đài phát thanh HALLAX 108.3 FM\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Sports - Volleyball, 10 June\", \"vi\": \"Thể thao - Bóng chuyền, ngày 10 tháng 6\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"At 3:00 P.M., Venezuela will take on Australia for qualification to the semifinals.\", \"vi\": \"Vào lúc 3 giờ chiều, Venezuela sẽ đối đầu với Australia trong trận đấu tranh vé vào bán kết.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Our guest announcer will be Vin Cote, retired coach of last year\'s winning team from Canada.\", \"vi\": \"Người dẫn chương trình khách mời của chúng tôi sẽ là ông Vin Cote, cựu huấn luyện viên của đội vô địch năm ngoái đến từ Canada.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"At 6:00 P.M., host team Poland will face off against France.\", \"vi\": \"Vào lúc 6 giờ chiều, đội chủ nhà Ba Lan sẽ đối đầu với Pháp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"The game will be covered live by Jeremy Bosko.\", \"vi\": \"Trận đấu sẽ được Jeremy Bosko tường thuật trực tiếp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}]' WHERE `id` = 'b0070b55-6826-4233-b2f8-d944619101e6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: allclients@yardleyriverdentalgroup.com\", \"vi\": \"Đến: allclients@yardleyriverdentalgroup.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: tliu@yardleyriverdentalgroup.com\", \"vi\": \"Từ: tliu@yardleyriverdentalgroup.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 7 January\", \"vi\": \"Ngày: 7 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Parking area\", \"vi\": \"Chủ đề: Khu vực đỗ xe\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Clients,\", \"vi\": \"Kính gửi Quý khách hàng,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Yardley River Dental Group will be closing our client parking area next week in order to ------- (139) some needed repairs.\", \"vi\": \"Yardley River Dental Group sẽ đóng cửa khu vực đỗ xe dành cho khách hàng vào tuần tới để ------- (139) một số việc sửa chữa cần thiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [139]}, {\"en\": \"------- (140).\", \"vi\": \"------- (140).\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [140]}, {\"en\": \"During this time, we request that you park your vehicles in the staff parking area, which is to the left of your usual area.\", \"vi\": \"Trong thời gian này, chúng tôi yêu cầu quý khách đỗ xe tại khu vực đỗ xe dành cho nhân viên, nằm ở bên trái khu vực thông thường của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"(Staff members will park at a specially arranged off-site location while the repairs are being conducted.) From the staff parking area, you will find a walkway that ------- (141) around the side of the building to our front entrance.\", \"vi\": \"(Các nhân viên sẽ đỗ xe tại một địa điểm ngoài khuôn viên đã được sắp xếp đặc biệt trong khi việc sửa chữa đang được tiến hành.) Từ khu vực đỗ xe của nhân viên, quý khách sẽ thấy một lối đi dẫn ------- (141) quanh hông tòa nhà đến lối vào phía trước của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [141]}, {\"en\": \"We apologize for the ------- (142) and thank you for your patience.\", \"vi\": \"Chúng tôi thành thật xin lỗi vì sự ------- (142) và cảm ơn sự kiên nhẫn của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [142]}, {\"en\": \"Tina Liu, Office Manager\", \"vi\": \"Tina Liu, Trưởng phòng Hành chính\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = 'b0d0de6a-938f-4d80-bd91-4f52116b17f3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Yum and Walk Food Tours Adding a New Destination\", \"vi\": \"Chương trình tham quan ẩm thực “Yum and Walk” bổ sung một điểm đến mới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"COLLEGE STATION (May 15)—On June 2, Yum and Walk Food Tours will add College Station to its statewide list of culinary destinations.\", \"vi\": \"COLLEGE STATION (ngày 15 tháng 5) — Vào ngày 2 tháng 6, Yum và Walk Food Tours sẽ bổ sung College Station vào danh sách các điểm đến ẩm thực trên toàn tiểu bang của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"“College Station has been overlooked as a culinary destination for too long,” said tour-company owner Ed Lopez.\", \"vi\": \"“College Station đã bị bỏ qua quá lâu với tư cách là một điểm đến ẩm thực,” ông Ed Lopez, chủ một công ty du lịch, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"A former chef, Lopez also once worked as a journalist and wrote about cuisine for the Texas Beacon.\", \"vi\": \"Là một cựu đầu bếp, ông Lopez trước đây cũng từng làm nhà báo và viết các bài về ẩm thực cho tờ Texas Beacon.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Yum and Walk Food Tours offers outings in nine other cities in Texas and brings visitors to restaurants, bakeries, and specialty stores to sample both sweet and savory treats.\", \"vi\": \"Yum and Walk Food Tours tổ chức các chuyến tham quan ẩm thực tại chín thành phố khác ở Texas và đưa du khách đến các nhà hàng, tiệm bánh và cửa hàng đặc sản để thưởng thức các món ngọt cũng như các món mặn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Visitors walk through the city with an experienced guide, who also shares information about each neighborhood\'s history.\", \"vi\": \"Du khách sẽ dạo quanh thành phố cùng một hướng dẫn viên giàu kinh nghiệm, người cũng sẽ chia sẻ thông tin về lịch sử của từng khu phố.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Mr. Lopez himself will serve as the tour guide in College Station, his home before working in San Antonio and then returning to the area.\", \"vi\": \"Chính ông Lopez sẽ đảm nhận vai trò hướng dẫn viên du lịch tại College Station – nơi ông từng sinh sống trước khi làm việc tại San Antonio và sau đó quay trở lại khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"“From the beginning, my goal has been to help people discover great food,” said Mr. Lopez.\", \"vi\": \"“Ngay từ đầu, mục tiêu của tôi là giúp mọi người khám phá những món ăn tuyệt vời,” ông Lopez chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The local itinerary includes five stops in a three-hour time span—Giuseppina\'s Trattoria, Yucatan Plate, Kerala Kebabs, Spice Rub Stop, and Delicious Doughnuts.\", \"vi\": \"Lịch trình tham quan tại địa phương bao gồm năm điểm dừng trong khoảng thời gian ba giờ — Giuseppina\'s Trattoria, Yucatan Plate, Kerala Kebabs, Spice Rub Stop và Delicious Doughnuts.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Customers can schedule private tours if they have any specific dietary preferences or requirements.\", \"vi\": \"Quý khách có thể đặt lịch tham quan riêng nếu có bất kỳ sở thích hoặc yêu cầu cụ thể nào về chế độ ăn uống.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Local officials are excited about the tour company\'s move into the area.\", \"vi\": \"Các quan chức địa phương rất phấn khởi trước việc công ty du lịch này mở rộng hoạt động sang khu vực này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"“We\'re thrilled to have Yum and Walk Food Tours add us to their list of destinations,” said College Station Mayor Maria Garcia.\", \"vi\": \"“Chúng tôi vô cùng vui mừng khi Yum và Walk Food Tours đã đưa chúng tôi vào danh sách các điểm đến của họ,” Thị trưởng Maria Garcia của thành phố College Station phát biểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"“Their presence is sure to have a positive impact on our area\'s dining establishments.”\", \"vi\": \"“Sự hiện diện của họ chắc chắn sẽ mang lại tác động tích cực cho các cơ sở ẩm thực trong khu vực của chúng ta.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Tickets are $50 each.\", \"vi\": \"Giá vé là 50 đô la mỗi vé.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The ten-week touring season begins on July 2 and lasts until September 3.\", \"vi\": \"Mùa lưu diễn kéo dài mười tuần sẽ bắt đầu vào ngày 2 tháng 7 và kết thúc vào ngày 3 tháng 9.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Tours take place on Sundays from 1 P.M. to 4 P.M.\", \"vi\": \"Các tour du lịch diễn ra vào Chủ nhật, từ 1 giờ chiều đến 4 giờ chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = 'b0f8d91b-4ba3-4056-a87a-5602d78094b3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All staff\", \"vi\": \"Gửi: Toàn thể cán bộ, nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Carol Yates\", \"vi\": \"Từ: Carol Yates\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: CCS Conference\", \"vi\": \"Chủ đề: Hội nghị CCS\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 1 June\", \"vi\": \"Ngày: 1 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: 📎 Conference schedule\", \"vi\": \"Tài liệu đính kèm: 📎 Lịch trình hội nghị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Staff,\", \"vi\": \"Kính gửi quý đồng nghiệp,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The 12th annual conference of the Caribbean Culinary Society (CCS) will take place here in Jamaica from 16 to 20 July.\", \"vi\": \"Hội nghị thường niên lần thứ 12 của Hiệp hội Ẩm thực vùng Caribê (CCS) sẽ diễn ra tại Jamaica từ ngày 16 đến ngày 20 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I have received a request from Chef Regina Tufton, chair of the organising committee, to conduct two workshops.\", \"vi\": \"Tôi đã nhận được đề nghị từ Bếp trưởng Regina Tufton, Chủ tịch Ban tổ chức, về việc tổ chức hai buổi hội thảo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"It is an honour to be invited by such an accomplished culinary expert, someone who is also the author of five cookbooks on Caribbean cuisine.\", \"vi\": \"Đây thực sự là một vinh dự khi được mời bởi một chuyên gia ẩm thực tài ba như vậy, người đồng thời cũng là tác giả của năm cuốn sách nấu ăn về ẩm thực vùng Caribe.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"More importantly, it is a wonderful opportunity for Yates Restaurant to showcase some of its award-winning delicacies.\", \"vi\": \"Quan trọng hơn cả, đây là một cơ hội tuyệt vời để Nhà hàng Yates giới thiệu một số món ngon từng đoạt giải thưởng của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The first workshop will focus on cooking techniques inspired by French cuisine.\", \"vi\": \"Buổi hội thảo đầu tiên sẽ tập trung vào các kỹ thuật nấu ăn lấy cảm hứng từ ẩm thực Pháp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"As Assistant Chef Duane Munroe has distinguished himself in this regard, I have asked him to help me with this presentation.\", \"vi\": \"Vì Phó Bếp trưởng Duane Munroe đã thể hiện rất xuất sắc trong lĩnh vực này, tôi đã đề nghị ông ấy hỗ trợ tôi trong phần trình bày này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The second workshop will address the challenges and rewards of running a food establishment.\", \"vi\": \"Hội thảo lần thứ hai sẽ đề cập đến những thách thức và lợi ích khi điều hành một cơ sở kinh doanh ẩm thực.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Since Zavia Pinnock has been doing an outstanding job of managing our restaurant, I have requested her input on the topic.\", \"vi\": \"Vì Zavia Pinnock đã hoàn thành xuất sắc công việc quản lý nhà hàng của chúng tôi, nên tôi đã đề nghị cô ấy đóng góp ý kiến về vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I encourage each of you to attend one or more conference sessions.\", \"vi\": \"Tôi khuyến khích mỗi quý vị tham dự ít nhất một phiên họp trong hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Of course, the restaurant must remain open and be well staffed during the conference period.\", \"vi\": \"Tất nhiên, nhà hàng phải tiếp tục hoạt động và đảm bảo có đủ nhân viên trong suốt thời gian diễn ra hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"So that I can be sure that we have enough staff on hand during the period of the conference, please let me know by 21 June the day(s) and time(s) of the session(s) you wish to attend.\", \"vi\": \"Để tôi có thể đảm bảo rằng chúng ta sẽ có đủ nhân viên túc trực trong thời gian diễn ra hội nghị, xin vui lòng thông báo cho tôi trước ngày 21 tháng 6 về ngày và giờ của các phiên họp mà quý vị mong muốn tham dự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"For your convenience, a copy of the conference schedule is attached.\", \"vi\": \"Để quý vị dễ theo dõi, chúng tôi xin đính kèm bản sao lịch trình hội nghị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Carol Yates\", \"vi\": \"Carol Yates\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = 'b111b27b-8719-4444-8284-012e2d68a0f3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Processing Plant Managers\", \"vi\": \"Kính gửi: Các Giám đốc Nhà máy Chế biến\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Sunlight Sugar Executive Board\", \"vi\": \"Từ: Ban Điều hành Công ty Sunlight Sugar\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: June 15\", \"vi\": \"Ngày: 15 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: News\", \"vi\": \"Chủ đề: Tin tức\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We are pleased to announce that, following our strongest quarter in over three years, we were ranked as the number-two sugar distributor in the region in the June 1 edition of Sugar Industry Times.\", \"vi\": \"Chúng tôi vui mừng thông báo rằng, sau quý kinh doanh thành công nhất trong hơn ba năm qua, công ty chúng tôi đã được xếp hạng là nhà phân phối đường đứng thứ hai trong khu vực trên ấn bản ngày 1 tháng 6 của tạp chí Sugar Industry Times.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We are extremely grateful to all our employees, who helped make this possible through their hard work and dedication.\", \"vi\": \"Chúng tôi vô cùng biết ơn toàn thể nhân viên của công ty, những người đã góp phần biến điều này thành hiện thực nhờ sự nỗ lực và cống hiến của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"To celebrate this achievement, we would like to recognize employees with a bonus to be added to their July 15 paycheck.\", \"vi\": \"Để kỷ niệm thành tựu này, chúng tôi xin vinh danh các nhân viên bằng một khoản tiền thưởng sẽ được cộng vào phiếu lương ngày 15 tháng 7 của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Plant managers at each location should inform staff at the next plant meeting on July 1.\", \"vi\": \"Các giám đốc nhà máy tại từng cơ sở cần thông báo cho nhân viên trong cuộc họp nhà máy tiếp theo vào ngày 1 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Thank you for helping us achieve our goals.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã giúp chúng tôi đạt được các mục tiêu của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = 'b1255d0b-0949-4a34-b716-a1ef318f2643';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: cbrandt@prebleevents.com\", \"vi\": \"Gửi tới: cbrandt@prebleevents.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: chsiao@yanvillefestival.com\", \"vi\": \"Nguồn: chsiao@yanvillefestival.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 15\", \"vi\": \"Ngày: 15 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Festival support\", \"vi\": \"Chủ đề: Hỗ trợ lễ hội\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Brandt,\", \"vi\": \"Kính gửi ông Brandt,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for contacting us regarding the Yanville Festival.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã liên hệ với chúng tôi về Lễ hội Yanville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [1] — We have already contracted with Breemer\'s Staging to provide lighting equipment for our main stages.\", \"vi\": \"— [1] — Chúng tôi đã ký hợp đồng với công ty Breemer\'s Staging để cung cấp thiết bị chiếu sáng cho các sân khấu chính của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] — Do you provide catering services?\", \"vi\": \"— [2] — Quý công ty có cung cấp dịch vụ tiệc không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [3] — We do not have anyone yet to manage the food for our actors and stage crews.\", \"vi\": \"— [3] — Hiện tại, chúng tôi vẫn chưa có ai phụ trách việc chuẩn bị bữa ăn cho các diễn viên và đội ngũ hậu trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Would you be interested in this work?\", \"vi\": \"Quý vị có quan tâm đến công việc này không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Please let me know.\", \"vi\": \"Xin vui lòng cho tôi biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"— [4] —\", \"vi\": \"— [4] —\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Cecily Hsiao\", \"vi\": \"Cecily Hsiao\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Vice-Chair, Yanville Festival\", \"vi\": \"Phó Chủ tịch, Lễ hội Yanville\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = 'b1758174-ba5a-4f7b-a48f-ad5810f406e2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Kristof Szasz <kszasz@budaceramics.com>\", \"vi\": \"Người gửi: Kristof Szasz <kszasz@budaceramics.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Anouk Ayala <aayala@ayala.net>\", \"vi\": \"Từ: Anouk Ayala <aayala@ayala.net>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Solar power options\", \"vi\": \"Chủ đề: Các phương án sử dụng năng lượng mặt trời\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: January 25\", \"vi\": \"Ngày: 25 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Szasz:\", \"vi\": \"Kính gửi ông Szasz:\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for your recent e-mail requesting recommendations for solar power options for your ceramics company.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã gửi email gần đây để đề nghị được tư vấn về các giải pháp năng lượng mặt trời cho công ty gốm sứ của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Before I make a recommendation for which company would best serve your needs, could you answer these questions?\", \"vi\": \"Trước khi tôi đưa ra đề xuất về công ty nào sẽ đáp ứng tốt nhất nhu cầu của quý vị, xin quý vị vui lòng trả lời những câu hỏi sau đây?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"1.\", \"vi\": \"1.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"How flexible is your budget for solar panel purchase and installation?\", \"vi\": \"Ngân sách của quý vị dành cho việc mua và lắp đặt tấm pin mặt trời có linh hoạt đến mức nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"2.\", \"vi\": \"2.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"What is your time frame?\", \"vi\": \"Quý vị dự kiến trong khoảng thời gian bao lâu?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The government plans to provide financial incentives toward the cost of installing solar power that will take effect in about two years.\", \"vi\": \"Chính phủ có kế hoạch áp dụng các chính sách khuyến khích tài chính nhằm hỗ trợ chi phí lắp đặt hệ thống điện mặt trời, dự kiến sẽ có hiệu lực trong khoảng hai năm nữa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"3.\", \"vi\": \"3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"What is the configuration of your property?\", \"vi\": \"Cấu trúc của bất động sản của quý vị như thế nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"If you have the space, you could choose to install solar panels in a parking area or on the ground.\", \"vi\": \"Nếu quý vị có đủ không gian, quý vị có thể cân nhắc lắp đặt các tấm pin mặt trời tại khu vực đỗ xe hoặc trên mặt đất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The first choice consists of canopies over your parking lot, while the second choice is great for large, unused areas.\", \"vi\": \"Lựa chọn thứ nhất là lắp đặt mái che cho bãi đỗ xe của quý vị, trong khi lựa chọn thứ hai rất phù hợp với những khu vực rộng lớn chưa được sử dụng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"4.\", \"vi\": \"4.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"What kind of roof do you have?\", \"vi\": \"Quý vị đang sử dụng loại mái nhà nào?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"A flat roof is not ideal.\", \"vi\": \"Mái bằng không phải là lựa chọn lý tưởng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Neither is a roof that has a lot of equipment on it, as there is not enough room for large solar panels.\", \"vi\": \"Một mái nhà có quá nhiều thiết bị lắp đặt trên đó cũng không phải là lựa chọn phù hợp, vì không có đủ không gian để lắp đặt các tấm pin mặt trời cỡ lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"5.\", \"vi\": \"5.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Are you planning on expanding your business in the future?\", \"vi\": \"Quý vị có dự định mở rộng quy mô kinh doanh trong tương lai không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I look forward to hearing back from you soon.\", \"vi\": \"Tôi rất mong sớm nhận được phản hồi từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Anouk Ayala\", \"vi\": \"Anouk Ayala\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"To: Anouk Ayala <aayala@ayala.net>\", \"vi\": \"Gửi tới: Anouk Ayala <aayala@ayala.net>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"From: Kristof Szasz <kszasz@budaceramics.com>\", \"vi\": \"Từ: Kristof Szasz <kszasz@budaceramics.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Subject: RE: Solar power options\", \"vi\": \"Chủ đề: Trả lời: Các phương án sử dụng năng lượng mặt trời\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Date: January 27\", \"vi\": \"Ngày: 27 tháng 1\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Dear Ms. Ayala:\", \"vi\": \"Kính gửi bà Ayala:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Our company headquarters is located outside of the capital city.\", \"vi\": \"Trụ sở chính của công ty chúng tôi tọa lạc ở ngoại ô thủ đô.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"The ceramics factory occupies approximately one-half of our property.\", \"vi\": \"Nhà máy gốm sứ chiếm khoảng một nửa diện tích khu đất của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"To ensure sufficient cooling, much of the roof space is taken up by industrial-sized air-conditioning units and venting silos for our ovens.\", \"vi\": \"Để đảm bảo khả năng làm mát đủ, phần lớn diện tích mái nhà được dành cho các hệ thống điều hòa không khí cỡ công nghiệp và các ống thông gió cho các lò nung của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"The rest of our property contains a sizeable parking lot, because there is no public transportation in the area, and our 150 employees must drive to work.\", \"vi\": \"Phần còn lại của khuôn viên công ty chúng tôi bao gồm một bãi đỗ xe khá rộng, bởi vì khu vực này không có phương tiện giao thông công cộng, và 150 nhân viên của chúng tôi buộc phải lái xe đến nơi làm việc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"The solar power business we choose should be well established.\", \"vi\": \"Doanh nghiệp trong lĩnh vực năng lượng mặt trời mà chúng ta lựa chọn cần phải có nền tảng vững chắc.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"We have an inflexible deadline for our current project, so I am willing to sacrifice money to get the panels installed as soon as possible.\", \"vi\": \"Dự án hiện tại của chúng tôi có thời hạn rất chặt chẽ, vì vậy tôi sẵn sàng chi thêm tiền để các tấm pin được lắp đặt càng sớm càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"I hope these answers help you with your recommendation.\", \"vi\": \"Tôi hy vọng những câu trả lời này sẽ giúp ích cho quý vị trong việc đưa ra lời khuyên.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Kristof Szasz\", \"vi\": \"Kristof Szasz\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Company - Specialty - Comments\", \"vi\": \"Công ty - Lĩnh vực chuyên môn - Nhận xét\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"AKX Solar - Rooftop - Very low cost; a very stable company\", \"vi\": \"AKX Solar - Lắp đặt trên mái nhà - Chi phí rất thấp; một công ty rất ổn định\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Sun365 - All types - Superior quality; very thorough; but a bit slow\", \"vi\": \"Sun365 - Mọi loại - Chất lượng vượt trội; rất kỹ lưỡng; nhưng hơi chậm\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Beranek Systems - Parking areas - Fast turnaround; but quite expensive\", \"vi\": \"Beranek Systems - Khu vực đỗ xe - Thời gian hoàn thành nhanh chóng; nhưng chi phí khá cao\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Plutosolar - Ground installation - Cannot begin until March\", \"vi\": \"Plutosolar - Lắp đặt trên mặt đất - Không thể bắt đầu trước tháng 3\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"http://www.solarinsider.com\", \"vi\": \"http://www.solarinsider.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}, {\"en\": \"Based on a recent customer survey, these four solar power companies in the capital city area are rated the most successful.\", \"vi\": \"Dựa trên kết quả một cuộc khảo sát khách hàng gần đây, bốn công ty năng lượng mặt trời tại khu vực thủ đô này được đánh giá là thành công nhất.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 44, \"question_numbers\": []}]' WHERE `id` = 'b17ec62c-212b-4bef-8956-c9e8195a2046';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Alcorn Photographers is proud to announce that we now offer aerial photography via drone.\", \"vi\": \"Alcorn Photographers hân hạnh thông báo rằng hiện nay chúng tôi đã cung cấp dịch vụ chụp ảnh từ trên cao bằng máy bay không người lái.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This technology is an excellent way to showcase your client’s home, apartment complex, or commercial space.\", \"vi\": \"Công nghệ này là một phương thức tuyệt vời để giới thiệu ngôi nhà, khu chung cư hoặc không gian thương mại của khách hàng quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Shooting the front, side, or rear of the building from a few dozen feet above the ground gives potential buyers a better sense of its scale and surroundings.\", \"vi\": \"Việc chụp ảnh mặt trước, mặt bên hoặc mặt sau của tòa nhà từ độ cao vài chục feet so với mặt đất sẽ giúp những người mua tiềm năng hình dung rõ hơn về quy mô cũng như môi trường xung quanh của tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As with our other outdoor services, Alcorn Photographers will not charge for aerial photography shoots that must be canceled due to poor weather.\", \"vi\": \"Cũng giống như các dịch vụ chụp ảnh ngoài trời khác của chúng tôi, Alcorn Photographers sẽ không tính phí đối với các buổi chụp ảnh từ trên cao buộc phải hủy bỏ do thời tiết xấu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We are also happy to schedule sessions at twilight to take advantage of the flattering lighting created by the setting sun.\", \"vi\": \"Chúng tôi cũng rất hân hạnh sắp xếp các buổi chụp vào lúc hoàng hôn để tận dụng ánh sáng tuyệt đẹp do mặt trời lặn tạo nên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Prices for aerial photography start at $200 for five images and increase with the number of photos desired.\", \"vi\": \"Giá dịch vụ chụp ảnh từ trên cao bắt đầu từ 200 đô la cho năm bức ảnh và sẽ tăng theo số lượng ảnh quý vị yêu cầu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"For more information or to book a shoot, please call us at 555-0162.\", \"vi\": \"Để biết thêm thông tin hoặc đặt lịch chụp ảnh, xin vui lòng liên hệ với chúng tôi theo số điện thoại 555-0162.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"http://www.alcornphotographers.com/news\", \"vi\": \"http://www.alcornphotographers.com/news\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"▶\", \"vi\": \"▶\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = 'b18b0c27-f9ca-4500-9678-cf4e61934325';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Spumoni App\", \"vi\": \"Ứng dụng Spumoni\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Thank you for downloading the Spumoni mobile phone app!\", \"vi\": \"Xin chân thành cảm ơn quý vị đã tải xuống ứng dụng Spumoni dành cho điện thoại di động!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"At your current basic membership level, your ability to save recipes is limited to five per day.\", \"vi\": \"Với cấp độ thành viên cơ bản hiện tại của quý vị, số lượng công thức nấu ăn mà quý vị có thể lưu mỗi ngày bị giới hạn ở mức năm công thức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"If you would like the freedom to save unlimited recipes daily, automatically generate shopping lists, create weekly meal plans, and track nutritional data, you can become a premium member for just $2.99 a month.\", \"vi\": \"Nếu quý vị mong muốn có quyền tự do lưu trữ không giới hạn các công thức nấu ăn hàng ngày, tự động tạo danh sách mua sắm, lập kế hoạch bữa ăn hàng tuần và theo dõi thông tin dinh dưỡng, quý vị có thể đăng ký trở thành thành viên cao cấp với mức phí chỉ 2,99 USD mỗi tháng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Many users find this small fee to be money well spent, as the premium features save them time and enable them to make healthier meal choices.\", \"vi\": \"Nhiều người dùng cho rằng khoản phí nhỏ này là khoản chi tiêu xứng đáng, bởi các tính năng cao cấp giúp họ tiết kiệm thời gian và cho phép họ lựa chọn các bữa ăn lành mạnh hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Visit our “PM Community” Web page to view real testimonials from our premium members.\", \"vi\": \"Hãy truy cập trang web “Cộng đồng PM” của chúng tôi để xem những lời chia sẻ thực tế từ các thành viên cao cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = 'b1af5865-2711-4d30-8822-cd366a918e1c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Nora O\'Byrne (9:36 A.M.) Ms. Klimek, I just purchased plane tickets to our presentation meeting with the Madrid retailer next week.\", \"vi\": \"Nora O\'Byrne (9 giờ 36 phút sáng) Thưa bà Klimek, tôi vừa mua vé máy bay để tham dự buổi họp trình bày với nhà bán lẻ tại Madrid vào tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Anna Klimek (9:37 A.M.) Great.\", \"vi\": \"Anna Klimek (9 giờ 37 phút sáng). Tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Did you manage to book a flight for Thursday?\", \"vi\": \"Quý vị đã đặt được vé máy bay cho thứ Năm chưa?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Nora O\'Byrne (9:37 A.M.) Yes, at 4:00 P.M. We\'ll arrive there in the evening, with enough time to rest before the Friday meeting.\", \"vi\": \"Nora O\'Byrne (9 giờ 37 phút sáng) Vâng, vào lúc 4 giờ chiều. Chúng tôi sẽ đến đó vào buổi tối, để có đủ thời gian nghỉ ngơi trước cuộc họp vào thứ Sáu.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Back to Dublin on Saturday, as planned.\", \"vi\": \"Thứ Bảy này, tôi sẽ trở lại Dublin như dự định.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Anna Klimek (9:38 A.M.) Perfect.\", \"vi\": \"Anna Klimek (9 giờ 38 phút sáng) Tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Could you also take care of travel insurance?\", \"vi\": \"Xin quý vị có thể giúp lo cả bảo hiểm du lịch được không?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Nora O\'Byrne (9:38 A.M.) To cover both health and merchandise examples?\", \"vi\": \"Nora O\'Byrne (9 giờ 38 phút sáng): Có nên đề cập đến cả các ví dụ về lĩnh vực y tế lẫn hàng hóa không?\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Anna Klimek (9:39 A.M.) Yes, we\'re taking fabrics, designs, and a few selections from our line.\", \"vi\": \"Anna Klimek (9 giờ 39 phút sáng) Vâng, chúng tôi đang mang theo các loại vải, mẫu thiết kế và một số sản phẩm được lựa chọn từ bộ sưu tập của mình.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Can you use the same insurance agent as last time?\", \"vi\": \"Quý vị có thể sử dụng cùng một đại lý bảo hiểm như lần trước không?\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Nora O\'Byrne (9:40 A.M.) Mr. Daly, could you prepare an insurance package for Ms. Klimek and me?\", \"vi\": \"Nora O\'Byrne (9 giờ 40 phút sáng) Thưa ông Daly, ông có thể chuẩn bị một gói bảo hiểm cho bà Klimek và tôi được không?\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"International travel, covering health and sample goods we will be bringing.\", \"vi\": \"Chuyến đi quốc tế, bao gồm các vấn đề về sức khỏe và các mẫu hàng hóa mà chúng tôi sẽ mang theo.\", \"type\": \"paragraph\", \"doc_index\": 6, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Fergal Daly (9:40 A.M.) With pleasure.\", \"vi\": \"Fergal Daly (9 giờ 40 phút sáng) Rất hân hạnh.\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Can I have your flight and baggage details?\", \"vi\": \"Xin vui lòng cung cấp cho tôi thông tin về chuyến bay và hành lý của quý vị được không?\", \"type\": \"paragraph\", \"doc_index\": 7, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Nora O\'Byrne (9:41 A.M.) Next Thursday to Saturday.\", \"vi\": \"Nora O\'Byrne (9 giờ 41 phút sáng) Từ thứ Năm tuần tới đến thứ Bảy.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Dublin to Madrid and return, on Air Conaway.\", \"vi\": \"Chuyến bay khứ hồi từ Dublin đến Madrid, do hãng hàng không Air Conaway khai thác.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Lightweight baggage, mainly apparel and fashion accessories.\", \"vi\": \"Hành lý nhẹ, chủ yếu là quần áo và phụ kiện thời trang.\", \"type\": \"paragraph\", \"doc_index\": 8, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Fergal Daly (9:59 A.M.) OK, I\'ve just forwarded you an electronic policy.\", \"vi\": \"Fergal Daly (9 giờ 59 phút sáng) Được rồi, tôi vừa chuyển tiếp bản chính sách điện tử cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 9, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Nora O\'Byrne (10:01 A.M.) Thank you!\", \"vi\": \"Nora O\'Byrne (10 giờ 01 phút sáng) Cảm ơn quý vị!\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I\'ve just provided my electronic signature.\", \"vi\": \"Tôi vừa hoàn tất việc ký điện tử.\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I\'ll wire the money now.\", \"vi\": \"Tôi sẽ chuyển khoản ngay bây giờ.\", \"type\": \"paragraph\", \"doc_index\": 10, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Fergal Daly (10:02 A.M.) Take your time.\", \"vi\": \"Fergal Daly (10 giờ 02 phút sáng) Xin hãy từ từ.\", \"type\": \"paragraph\", \"doc_index\": 11, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"The insurance company allows two days, so you have until Wednesday.\", \"vi\": \"Công ty bảo hiểm cho phép thời hạn hai ngày, do đó quý vị có thời gian đến hết thứ Tư.\", \"type\": \"paragraph\", \"doc_index\": 11, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = 'b1dc0dbc-785f-4223-9171-a6e81760fed1';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"CJOK Radio Show Welcomes New Staff\", \"vi\": \"Chương trình phát thanh CJOK chào đón nhân sự mới\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"QUEENSVILLE (7 July)—Local radio station CJOK announced Katherine Dees as the new producer of the popular show Out and About in Queensville.\", \"vi\": \"QUEENSVILLE (Ngày 7 tháng 7)—Đài phát thanh địa phương CJOK đã thông báo bổ nhiệm Katherine Dees làm nhà sản xuất mới của chương trình nổi tiếng Out and About in Queensville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Ms. Dees is now ___135___ for coordinating schedules, booking guests for the show, and managing media relations.\", \"vi\": \"Cô Dees hiện ___135___ việc điều phối lịch trình, đặt lịch khách mời cho chương trình và quản lý quan hệ truyền thông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [135]}, {\"en\": \"___136___, the station hired sound editor Virginia Thacker and production assistant Reggie Dietrich to support Ms. Dees in her new role.\", \"vi\": \"___136___, đài phát thanh đã tuyển dụng biên tập viên âm thanh Virginia Thacker và trợ lý sản xuất Reggie Dietrich để hỗ trợ cô Dees trong vai trò mới của cô ấy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [136]}, {\"en\": \"___137___.\", \"vi\": \"___137___.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [137]}, {\"en\": \"Out and About in Queensville, which has been airing for 30 years, is performed live weekly from September to May in the Orpheum Theater in downtown Queensville.\", \"vi\": \"Chương trình Out and About in Queensville, đã phát sóng được 30 năm, được biểu diễn trực tiếp hàng tuần từ tháng 9 đến tháng 5 tại Nhà hát Orpheum ở trung tâm Queensville.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The show ___138___ musical guests, writers, and storytellers for an hour of weekly programming.\", \"vi\": \"Chương trình ___138___ các khách mời âm nhạc, nhà văn và người kể chuyện cho một giờ phát sóng hàng tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [138]}]' WHERE `id` = 'b217c315-f062-4615-9ddd-181d297d8fe6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"MANCHESTER (14 August)—Local firm Centrality Partners announced today that it will begin providing its services to non-profit organisations at a discounted rate.\", \"vi\": \"MANCHESTER (ngày 14 tháng 8) — Công ty địa phương Centrality Partners hôm nay thông báo rằng họ sẽ bắt đầu cung cấp dịch vụ cho các tổ chức phi lợi nhuận với mức giá ưu đãi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Centrality possesses one of the city\'s largest collections of audiovisual equipment, ranging from sound systems to large digital displays and programmable lighting fixtures.\", \"vi\": \"Centrality sở hữu một trong những bộ sưu tập thiết bị nghe nhìn lớn nhất thành phố, bao gồm từ hệ thống âm thanh đến các màn hình kỹ thuật số cỡ lớn và hệ thống đèn chiếu sáng có thể lập trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"All of this is put at clients\' disposal in service of staging polished, impressive conferences, fund-raisers, awards banquets, and much more.\", \"vi\": \"Tất cả những điều này đều được cung cấp cho quý khách hàng nhằm phục vụ việc tổ chức các hội nghị, sự kiện gây quỹ, tiệc trao giải và nhiều sự kiện khác một cách chuyên nghiệp và ấn tượng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"No matter the occasion or audience, Centrality ensures that presenters\' messages are conveyed clearly.\", \"vi\": \"Dù trong bất kỳ hoàn cảnh hay trước bất kỳ đối tượng nào, Centrality cũng đảm bảo rằng thông điệp của người thuyết trình sẽ được truyền tải một cách rõ ràng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"A technical expert is present at every step of the process to minimise the possibility of distracting problems like distorted sound, incompatible presentation materials, and even unflattering lighting.\", \"vi\": \"Một chuyên gia kỹ thuật sẽ có mặt trong từng bước của quy trình nhằm giảm thiểu tối đa khả năng xảy ra các vấn đề gây xao nhãng như âm thanh bị méo, tài liệu trình chiếu không tương thích, và thậm chí là ánh sáng không thuận lợi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Recent Centrality successes include the annual conference of the UK\'s largest insurers\' association and the Manchester Book Festival.\", \"vi\": \"Trong số những thành công gần đây của Centrality có thể kể đến hội nghị thường niên của hiệp hội các công ty bảo hiểm lớn nhất Vương quốc Anh và Lễ hội Sách Manchester.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The discount that Centrality is offering non-profit clients will vary between 10% and 20% depending on the size of the organisation.\", \"vi\": \"Mức chiết khấu mà Centrality dành cho các khách hàng là tổ chức phi lợi nhuận sẽ dao động từ 10% đến 20%, tùy thuộc vào quy mô của tổ chức.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"To be eligible, organisations must be based within Greater Manchester.\", \"vi\": \"Để đủ điều kiện, các tổ chức phải có trụ sở tại khu vực Greater Manchester.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Details and contact information can be found on Centrality\'s Web site, www.centrality.co.uk.\", \"vi\": \"Quý vị có thể tham khảo thông tin chi tiết và thông tin liên hệ trên trang web của Centrality tại địa chỉ www.centrality.co.uk.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = 'b25398f6-6c68-4823-8545-515576a2a2ac';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: custserv@xanthusflowers.co.uk\", \"vi\": \"Gửi tới: custserv@xanthusflowers.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: mnair@nortraxpetrol.co.uk\", \"vi\": \"Nguồn: mnair@nortraxpetrol.co.uk\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 27 July\", \"vi\": \"Ngày: 27 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Order #9871\", \"vi\": \"Chủ đề: Đơn hàng số 9871\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Sir or Madam:\", \"vi\": \"Kính gửi Quý vị,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"On 24 July, I placed an online order for £180 for three arrangements of white roses and pink lilies on behalf of my company, Nortrax Petroleum.\", \"vi\": \"Vào ngày 24 tháng 7, tôi đã đặt hàng trực tuyến với tổng giá trị 180 bảng Anh cho ba bó hoa gồm hoa hồng trắng và hoa loa kèn hồng thay mặt cho công ty của tôi, Nortrax Petroleum.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The flowers were meant to be delivered by 10 A.M. the following day for a company banquet that evening.\", \"vi\": \"Những bông hoa này dự kiến sẽ được giao trước 10 giờ sáng ngày hôm sau để phục vụ cho bữa tiệc của công ty vào buổi tối cùng ngày.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Unfortunately, the flowers did not arrive until noon.\", \"vi\": \"Thật không may, những bông hoa đã không được giao đến cho đến tận trưa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Moreover, the bouquets consisted of pink and white carnations.\", \"vi\": \"Hơn nữa, những bó hoa này được cắm từ hoa cẩm chướng màu hồng và trắng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Worst of all, many of the flowers were either wilted or were shedding petals and thus could not be used to decorate the banquet room as planned.\", \"vi\": \"Điều tồi tệ nhất là, rất nhiều bông hoa đã héo úa hoặc đang rụng cánh, do đó không thể dùng để trang trí phòng tiệc như dự định.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I was surprised and disappointed to be let down by Xanthus Flowers, a company we at Nortrax Petroleum have come to trust and depend on over the last five years.\", \"vi\": \"Tôi đã vô cùng ngạc nhiên và thất vọng khi bị Xanthus Flowers làm cho thất vọng – một công ty mà chúng tôi tại Nortrax Petroleum đã tin tưởng và dựa vào trong suốt năm năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Since the flowers were for a one-time event, a replacement order is not really an option.\", \"vi\": \"Vì những bông hoa này dành cho một sự kiện chỉ diễn ra một lần, nên việc đặt hàng thay thế thực sự không phải là một lựa chọn khả thi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Consequently, I would like to receive a refund.\", \"vi\": \"Do đó, tôi mong được hoàn lại tiền.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Thank you for your attention to this matter.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã quan tâm đến vấn đề này.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Mindy Nair\", \"vi\": \"Mindy Nair\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Corporate Event Coordinator\", \"vi\": \"Điều phối viên sự kiện doanh nghiệp\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Nortrax Petroleum\", \"vi\": \"Nortrax Petroleum\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To: mnair@nortraxpetrol.co.uk\", \"vi\": \"Gửi tới: mnair@nortraxpetrol.co.uk\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: custserv@xanthusflowers.co.uk\", \"vi\": \"Nguồn: custserv@xanthusflowers.co.uk\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date: 28 July\", \"vi\": \"Ngày: 28 tháng 7\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subject: Order #9871\", \"vi\": \"Chủ đề: Đơn hàng số 9871\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Dear Ms. Nair,\", \"vi\": \"Kính gửi bà Nair,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"We sincerely apologize for the problems you recently experienced with your order.\", \"vi\": \"Chúng tôi xin chân thành xin lỗi về những sự cố mà quý khách đã gặp phải gần đây liên quan đến đơn hàng của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"We have recently transitioned to a larger facility and have experienced a few challenges as we adjust.\", \"vi\": \"Gần đây, chúng tôi đã chuyển sang một cơ sở rộng rãi hơn và đã gặp phải một số khó khăn trong quá trình thích nghi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"It is our goal to provide on-time delivery and high-quality flowers for every order.\", \"vi\": \"Mục tiêu của chúng tôi là đảm bảo giao hàng đúng hẹn và cung cấp những bó hoa chất lượng cao cho mọi đơn hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"We regret that this order did not live up to our high standards.\", \"vi\": \"Chúng tôi rất lấy làm tiếc vì đơn hàng này đã không đáp ứng được các tiêu chuẩn cao của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"A refund cheque in the amount of £180 has been issued to your company.\", \"vi\": \"Một tấm séc hoàn tiền với số tiền là 180 bảng Anh đã được phát hành cho công ty của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Because we are at fault, we would like to offer you a 20% discount plus free delivery on your next order.\", \"vi\": \"Do lỗi thuộc về phía chúng tôi, chúng tôi xin được dành tặng quý khách mức giảm giá 20% cùng với dịch vụ giao hàng miễn phí cho đơn hàng tiếp theo của quý khách.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Thank you for being a loyal customer.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã luôn ủng hộ chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"We look forward to serving you again in the near future.\", \"vi\": \"Chúng tôi rất mong được phục vụ quý khách một lần nữa trong thời gian tới.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Bill McCabe\", \"vi\": \"Bill McCabe\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Customer Service Manager\", \"vi\": \"Trưởng phòng Dịch vụ Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 34, \"question_numbers\": []}]' WHERE `id` = 'b2579f7d-c230-4334-ac42-f10c9d7dfe54';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Jobs Coming to Willettville\", \"vi\": \"Các cơ hội việc làm sắp xuất hiện tại Willettville\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"WILLETT VILLE (March 8)—Tanney\'s Discount Mart (TDM) announced today that it will hold a job fair in Willettville later this month.\", \"vi\": \"WILLETT VILLE (ngày 8 tháng 3) — Hôm nay, Tanney’s Discount Mart (TDM) đã thông báo rằng công ty sẽ tổ chức một hội chợ việc làm tại Willettville vào cuối tháng này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The company, headquartered in nearby Lyter City, is looking to fill 300 positions at its new distribution center, set to open here next month.\", \"vi\": \"Công ty này, có trụ sở chính tại thành phố Lyter lân cận, đang có nhu cầu tuyển dụng 300 nhân viên cho trung tâm phân phối mới của mình, dự kiến sẽ đi vào hoạt động tại đây vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"In addition to seeking technicians and supervisors, the company wants to fill positions in the processing, stock inspection, and maintenance departments.\", \"vi\": \"Bên cạnh việc tuyển dụng kỹ thuật viên và giám sát viên, công ty còn có nhu cầu tuyển dụng nhân sự cho các bộ phận chế biến, kiểm tra hàng tồn kho và bảo trì.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"“TDM’s distribution centers use modern automated systems, which creates a big need for qualified technical staff in particular,” Kent Siler, TDM’s president, said in a press release announcing the job fair.\", \"vi\": \"“Các trung tâm phân phối của TDM sử dụng các hệ thống tự động hóa hiện đại, điều này tạo ra nhu cầu lớn về nhân viên kỹ thuật có trình độ, đặc biệt là trong lĩnh vực này,” ông Kent Siler, Chủ tịch TDM, cho biết trong thông cáo báo chí công bố hội chợ việc làm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The event will be held from 9:30 A.M. to 6:30 P.M. on Thursday, March 20, in the ballroom of the Twin Ridges Hotel.\", \"vi\": \"Sự kiện này sẽ diễn ra từ 9 giờ 30 sáng đến 6 giờ 30 chiều vào thứ Năm, ngày 20 tháng 3, tại phòng khiêu vũ của Khách sạn Twin Ridges.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Details can be found by visiting tdm.com/careers.\", \"vi\": \"Quý vị có thể truy cập trang web tdm.com/careers để tìm hiểu thêm thông tin chi tiết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"“This recruiting event will help us find the staff we need to meet the anticipated growth in demand for our products,” said Mr. Siler.\", \"vi\": \"“Sự kiện tuyển dụng này sẽ giúp chúng tôi tìm được những nhân viên cần thiết để đáp ứng sự gia tăng dự kiến về nhu cầu đối với các sản phẩm của chúng tôi,” ông Siler phát biểu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"“TDM continues to expand its position in discount retail.\", \"vi\": \"“TDM tiếp tục củng cố vị thế của mình trong lĩnh vực bán lẻ giá rẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"So far this year, we have opened three stores, and we have five more slated to open by the end of next year.”\", \"vi\": \"“Tính đến thời điểm này trong năm nay, chúng tôi đã khai trương ba cửa hàng và dự kiến sẽ khai trương thêm năm cửa hàng nữa vào cuối năm sau.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Mr. Siler noted, moreover, that TDM offers competitive wages for full-time and part-time employment.\", \"vi\": \"Hơn nữa, ông Siler cũng nhấn mạnh rằng TDM đưa ra mức lương cạnh tranh cho cả các vị trí làm việc toàn thời gian và bán thời gian.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = 'b2b91db8-44d0-45de-9ff7-a4c22beaa78c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: jenkins@ourmarketfocus.au\", \"vi\": \"Nguồn: jenkins@ourmarketfocus.au\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: hardesty@gallusmail.au\", \"vi\": \"Gửi tới: hardesty@gallusmail.au\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 11 August\", \"vi\": \"Ngày: 11 tháng 8\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Workshop Notice\", \"vi\": \"Chủ đề: Thông báo về hội thảo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Hardesty,\", \"vi\": \"Kính gửi bà Hardesty,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This is to share an important change concerning the 18 August, 4 P.M. Marketing Skills Workshop.\", \"vi\": \"Thông báo này nhằm chia sẻ một thay đổi quan trọng liên quan đến Hội thảo Kỹ năng Tiếp thị diễn ra vào lúc 4 giờ chiều ngày 18 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Because many more attendees have signed up, we have changed the location of our event to\", \"vi\": \"Do số lượng người tham dự đăng ký đã tăng lên đáng kể, chúng tôi đã quyết định thay đổi địa điểm tổ chức sự kiện sang\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The Rill Inn; PERTH\", \"vi\": \"The Rill Inn; PERTH\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please acknowledge you are aware of the update.\", \"vi\": \"Kính mong quý vị xác nhận rằng quý vị đã biết về bản cập nhật này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I would appreciate it if you could treat this request as urgent and reply as soon as convenient.\", \"vi\": \"Tôi sẽ rất cảm kích nếu quý vị có thể xem xét yêu cầu này là khẩn cấp và trả lời ngay khi thuận tiện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Should you have any questions about participation, you can e-mail me.\", \"vi\": \"Nếu quý vị có bất kỳ thắc mắc nào liên quan đến việc tham gia, xin vui lòng gửi email cho tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Andrew Jenkins\", \"vi\": \"Andrew Jenkins\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Workshop Organizer\", \"vi\": \"Đơn vị tổ chức hội thảo\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = 'b2e0737f-1cd9-4130-a68e-4c9234bba6fb';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"COUPON\", \"vi\": \"Phiếu giảm giá\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"If you love the delicious cheese and crackers served at Truli Cafés, you can now enjoy this popular snack at home!\", \"vi\": \"Nếu quý vị yêu thích món phô mai và bánh quy giòn thơm ngon được phục vụ tại các quán Truli Café, thì giờ đây quý vị đã có thể thưởng thức món ăn vặt được ưa chuộng này ngay tại nhà rồi!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Truli crackers and cheese are now available at major supermarkets.\", \"vi\": \"Bánh quy Truli và phô mai hiện đã có mặt tại các siêu thị lớn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Save $2.00 on the purchase of ONE box of Truli crackers (any size) when you buy any TWO packages of Truli cheese.\", \"vi\": \"Quý khách sẽ được giảm $2.00 khi mua MỘT hộp bánh quy Truli (bất kỳ kích cỡ nào) khi mua BẤT KỲ HAI gói phô mai Truli nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Limit one coupon per customer.\", \"vi\": \"Mỗi khách hàng chỉ được sử dụng một phiếu giảm giá.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This coupon may not be combined with other special offers.\", \"vi\": \"Phiếu giảm giá này không được kết hợp với các chương trình khuyến mãi khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Expires July 31.\", \"vi\": \"Hạn chót là ngày 31 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}]' WHERE `id` = 'b3454267-59aa-4e3d-9870-8c589c1edfe5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: elvin.williams@gxtinvestments.com\", \"vi\": \"Gửi tới: elvin.williams@gxtinvestments.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: barry.robledo@gxtinvestments.com\", \"vi\": \"Nguồn: barry.robledo@gxtinvestments.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: May 17\", \"vi\": \"Ngày: 17 tháng 5\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: 301 N. Powell\", \"vi\": \"Chủ đề: 301 N. Powell\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Attachment: Photos\", \"vi\": \"Tệp đính kèm: Ảnh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Elvin,\", \"vi\": \"Elvin,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"I walked through the property at 301 N. Powell Avenue today.\", \"vi\": \"Hôm nay, tôi đã đi tham quan khu bất động sản tại số 301 N. Powell Avenue.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I was able to see the reception area, the offices, and the kitchen, but the utility closet in the west hallway was locked.\", \"vi\": \"Tôi đã có cơ hội tham quan khu vực lễ tân, các văn phòng và nhà bếp, nhưng tủ đựng đồ dùng ở hành lang phía tây thì bị khóa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I am sure an inspector will be able to verify that the furnace and electrical circuit board in that space are in good working order should we choose to proceed with a purchase.\", \"vi\": \"Tôi tin chắc rằng nếu chúng ta quyết định tiến hành giao dịch mua bán này, một chuyên viên kiểm tra sẽ có thể xác minh rằng lò sưởi và bảng mạch điện trong khu vực đó đang hoạt động bình thường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The building has all the space we need to accommodate our clients, including a large parking area.\", \"vi\": \"Tòa nhà này có đầy đủ không gian cần thiết để phục vụ quý khách hàng, bao gồm cả một khu đỗ xe rộng rãi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"However, there are some issues that we will need to address if we move forward: the carpet in the reception area is discolored; some floor tiles in the east hallway are cracked; and there is chipped paint in the conference room.\", \"vi\": \"Tuy nhiên, nếu chúng ta tiếp tục triển khai, sẽ có một số vấn đề cần được giải quyết: thảm ở khu vực tiếp tân đã bị phai màu; một số viên gạch lát sàn ở hành lang phía đông bị nứt; và lớp sơn trong phòng hội nghị có chỗ bị bong tróc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"The small water stain on the ceiling of the conference room may indicate a leak in the roof.\", \"vi\": \"Vết ố nước nhỏ trên trần phòng hội nghị có thể là dấu hiệu cho thấy mái nhà bị dột.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I have attached photographs of the problem areas.\", \"vi\": \"Tôi đã đính kèm các bức ảnh chụp những khu vực có vấn đề.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Given the low price of the property, I think we should consider this location.\", \"vi\": \"Xét thấy giá bất động sản này khá thấp, tôi cho rằng chúng ta nên xem xét vị trí này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We could update the space and still come in under budget.\", \"vi\": \"Chúng ta có thể cải tạo không gian này mà vẫn đảm bảo chi phí nằm trong phạm vi ngân sách.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Our current lease expires in three months, so we will need to make a decision quickly.\", \"vi\": \"Hợp đồng thuê hiện tại của chúng tôi sẽ hết hạn sau ba tháng, vì vậy chúng tôi cần phải đưa ra quyết định càng sớm càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Let me know what you think.\", \"vi\": \"Xin vui lòng cho tôi biết ý kiến của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Barry Robledo\", \"vi\": \"Barry Robledo\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = 'b383863a-51da-4a73-87ec-086c9939ca92';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Employees\", \"vi\": \"Đến: Tất cả nhân viên\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Subject: Server Maintenance Reminder\", \"vi\": \"Chủ đề: Nhắc nhở bảo trì máy chủ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: March 11\", \"vi\": \"Ngày: 11 tháng 3\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Please be advised it is time for the IT department to ______[131] mandatory server maintenance and updates.\", \"vi\": \"Xin lưu ý rằng đã đến lúc bộ phận CNTT ______[131] việc bảo trì và cập nhật máy chủ bắt buộc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [131]}, {\"en\": \"______[132].\", \"vi\": \"______[132].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [132]}, {\"en\": \"There will be no Internet service in the building from 7:00 P.M. Wednesday, March 12, until 9:00 A.M. Thursday, March 13.\", \"vi\": \"Sẽ không có dịch vụ internet trong tòa nhà từ 7:00 tối Thứ Tư, ngày 12 tháng 3, cho đến 9:00 sáng Thứ Năm, ngày 13 tháng 3.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In addition, please note there will be no remote access available.\", \"vi\": \"Ngoài ra, xin lưu ý sẽ không có quyền truy cập từ xa nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Therefore, you will not be able to log in to the server from outside the office.\", \"vi\": \"Do đó, bạn sẽ không thể đăng nhập vào máy chủ từ bên ngoài văn phòng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[133] this regularly scheduled maintenance, you will not have access to your e-mail, calendar, or contacts.\", \"vi\": \"______[133] việc bảo trì được lên lịch thường xuyên này, bạn sẽ không có quyền truy cập vào email, lịch hoặc danh bạ của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [133]}, {\"en\": \"Employees should plan accordingly.\", \"vi\": \"Nhân viên nên có kế hoạch phù hợp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We ______[134] any inconvenience this may cause.\", \"vi\": \"Chúng tôi ______[134] mọi bất tiện có thể gây ra.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [134]}]' WHERE `id` = 'b39d4c2e-edba-4d9f-a46d-6c0a32064ff4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Streamer Looks to the Past\", \"vi\": \"Người phát trực tiếp nhìn lại quá khứ\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"LOS ANGELES (July 30)—In recent months, subscription streaming service Cinematix has released or announced plans for several series based on previous films and television series.\", \"vi\": \"LOS ANGELES (ngày 30 tháng 7) — Trong những tháng gần đây, dịch vụ phát trực tuyến theo hình thức đăng ký Cinematix đã ra mắt hoặc công bố kế hoạch cho một số loạt phim dựa trên các bộ phim và loạt phim truyền hình trước đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The trend is believed to be an attempt by new CEO Irina Zaitseva to attract new subscribers from among fans of the original content.\", \"vi\": \"Người ta cho rằng xu hướng này là nỗ lực của Giám đốc điều hành mới Irina Zaitseva nhằm thu hút người đăng ký mới từ cộng đồng người hâm mộ nội dung gốc.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"One successful example has been Happier Home, the continuation of Happy Home, a family comedy that aired its final episode 30 years ago.\", \"vi\": \"Một ví dụ thành công là bộ phim “Happier Home”, phần tiếp theo của “Happy Home” – một bộ phim hài gia đình đã phát sóng tập cuối cùng cách đây 30 năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Many stars of the original show, including Joyce Schott, agreed to reprise their characters for Happier Home.\", \"vi\": \"Nhiều diễn viên chính của bộ phim gốc, trong đó có bà Joyce Schott, đã đồng ý tiếp tục đảm nhận vai diễn của mình trong bộ phim “Happier Home”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Ms. Zaitseva claimed that the series was Cinematix\'s most watched in June, the month of its premiere.\", \"vi\": \"Bà Zaitseva cho biết bộ phim này là tác phẩm được xem nhiều nhất của Cinematix trong tháng 6, tháng mà bộ phim này ra mắt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"However, the controversy over Cinematix\'s planned remake of Star Seekers demonstrates a downside of this programming approach.\", \"vi\": \"Tuy nhiên, tranh cãi xung quanh kế hoạch làm lại bộ phim *Star Seekers* của Cinematix đã bộc lộ một mặt trái của phương pháp lập trình này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Mark Simmons, the new series\' producer, declared in a recent interview that his version of this story of a spaceship exploring other planets would outdo the original show by featuring state-of-the-art special effects.\", \"vi\": \"Mark Simmons, nhà sản xuất của loạt phim mới, đã tuyên bố trong một cuộc phỏng vấn gần đây rằng phiên bản của ông về câu chuyện con tàu vũ trụ thám hiểm các hành tinh khác sẽ vượt trội hơn so với chương trình gốc nhờ việc sử dụng các hiệu ứng đặc biệt tiên tiến nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Outraged fans have responded that Mr. Simmons is misunderstanding what made the original so beloved.\", \"vi\": \"Các người hâm mộ vô cùng phẫn nộ đã phản hồi rằng ông Simmons đang hiểu lầm điều đã khiến tác phẩm gốc trở nên được yêu mến đến vậy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"“The 1980s Star Seekers was special because of its optimistic worldview, not fancy technology,” says Lily Colwell, moderator of the Web forum Star Seeker Alliance.\", \"vi\": \"“Bộ phim *Star Seekers* thập niên 1980 đặc biệt nhờ vào thế giới quan lạc quan của nó, chứ không phải nhờ công nghệ hiện đại,” bà Lily Colwell, người điều hành diễn đàn trực tuyến *Star Seeker Alliance*, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"“A lot of our members will cancel their Cinematix subscriptions if it harms that legacy.”\", \"vi\": \"“Rất nhiều thành viên của chúng tôi sẽ hủy đăng ký Cinematix nếu điều đó làm tổn hại đến di sản đó.”\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = 'b3a51d9e-375e-4d8a-889e-f8ffb5bc17c5';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"E-Mail Message\", \"vi\": \"Thông điệp email\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: Shaan Iqbal\", \"vi\": \"Kính gửi: Shaan Iqbal\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Maggie Rosen\", \"vi\": \"Từ: Maggie Rosen\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: July 12\", \"vi\": \"Ngày: 12 tháng 7\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Office celebration\", \"vi\": \"Chủ đề: Buổi tiệc tại văn phòng\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Shaan,\", \"vi\": \"Kính gửi Shaan,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As you know, we have planned an office party in honor of Walter Weber for July 28.\", \"vi\": \"Như quý vị đã biết, chúng tôi đã lên kế hoạch tổ chức một bữa tiệc tại văn phòng để vinh danh ông Walter Weber vào ngày 28 tháng 7.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I was pleased to learn from my assistant that you will be attending, and I was wondering if you would be willing to say a few words about Walter during the event.\", \"vi\": \"Tôi rất vui khi được trợ lý của mình thông báo rằng quý vị sẽ tham dự, và tôi tự hỏi liệu quý vị có sẵn lòng chia sẻ vài lời về Walter trong sự kiện này hay không.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"He founded this firm 25 years ago and has always been an integral part of it.\", \"vi\": \"Ông đã thành lập công ty này cách đây 25 năm và luôn là một phần không thể thiếu của công ty.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Since you work closely with him in the finance department, I thought you might be well positioned to talk about him as a mentor, worker, and leader.\", \"vi\": \"Vì quý vị làm việc sát cánh cùng anh ấy tại phòng tài chính, tôi nghĩ quý vị có thể là người thích hợp nhất để chia sẻ về anh ấy với tư cách là một người hướng dẫn, một nhân viên và một nhà lãnh đạo.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"The party will begin at 6 P.M. The speeches will start at 7:30 P.M. and continue for about an hour.\", \"vi\": \"Buổi tiệc sẽ bắt đầu vào lúc 6 giờ chiều. Các bài phát biểu sẽ bắt đầu vào lúc 7 giờ 30 phút tối và kéo dài khoảng một giờ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I am sure everyone, not just Walter, would love to hear from you!\", \"vi\": \"Tôi tin chắc rằng tất cả mọi người, không chỉ riêng Walter, đều rất mong nhận được tin từ quý vị!\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Please let me know as soon as possible.\", \"vi\": \"Xin vui lòng thông báo cho tôi biết càng sớm càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Many thanks,\", \"vi\": \"Xin chân thành cảm ơn,\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Maggie Rosen\", \"vi\": \"Maggie Rosen\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Director of Human Resources\", \"vi\": \"Giám đốc Nhân sự\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Weber Richter Associates\", \"vi\": \"Weber Richter Associates\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"E-Mail Message\", \"vi\": \"Thông điệp email\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To: Maggie Rosen\", \"vi\": \"Kính gửi: Bà Maggie Rosen\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"From: Shaan Iqbal\", \"vi\": \"Từ: Shaan Iqbal\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date: July 12\", \"vi\": \"Ngày: 12 tháng 7\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Subject: Re: Office celebration\", \"vi\": \"Chủ đề: Trả lời: Buổi tiệc tại văn phòng\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Dear Maggie,\", \"vi\": \"Kính gửi Maggie,\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Thanks for thinking of me!\", \"vi\": \"Cảm ơn quý vị đã quan tâm đến tôi!\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I have really been looking forward to Walter\'s party, and it would be a tremendous honor for me to speak about him.\", \"vi\": \"Tôi thực sự đã rất mong chờ bữa tiệc của Walter, và đối với tôi, được nói về anh ấy sẽ là một vinh dự vô cùng lớn lao.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Walter actually interviewed me when I first applied for a job with the company fifteen years ago.\", \"vi\": \"Thực ra, chính ông Walter là người đã phỏng vấn tôi khi tôi lần đầu tiên nộp đơn xin việc tại công ty này cách đây mười lăm năm.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"His guidance over the years has been invaluable.\", \"vi\": \"Sự hướng dẫn của ông trong suốt những năm qua thực sự là vô giá.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Please note that I have a meeting with the sales team scheduled for 5 P.M. that day, so I should arrive at the party just as the speeches begin.\", \"vi\": \"Xin lưu ý rằng tôi có cuộc họp với đội ngũ bán hàng được lên lịch vào lúc 5 giờ chiều ngày hôm đó, vì vậy tôi sẽ đến dự tiệc đúng lúc các bài phát biểu bắt đầu.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"If you schedule me to deliver one of the later speeches, there should be no problem.\", \"vi\": \"Nếu quý vị sắp xếp để tôi phát biểu vào một trong những phần sau, chắc chắn sẽ không có vấn đề gì.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 4, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Shaan Iqbal\", \"vi\": \"Shaan Iqbal\", \"type\": \"sign_off\", \"doc_index\": 4, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Weber Richter Associates\", \"vi\": \"Weber Richter Associates\", \"type\": \"sign_off\", \"doc_index\": 4, \"sentence_id\": 32, \"question_numbers\": []}]' WHERE `id` = 'b3a8609c-7d87-462b-ad9a-21e56ebeaefd';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Hathai Khwan\", \"vi\": \"Gửi: Mẹ của Mặt Trời\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Jim Frollo\", \"vi\": \"Từ: Jim Frollo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: July 15\", \"vi\": \"Ngày: 15 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Possible solution\", \"vi\": \"Chủ đề: Giải pháp khả thi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Khwan,\", \"vi\": \"Kính gửi bà Khwan,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for getting the team together so quickly to deal with the problem recently reported by passengers.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã nhanh chóng tập hợp đội ngũ để xử lý vấn đề mà hành khách vừa phản ánh gần đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The congestion in the departures area, particularly at check-in, has been an ongoing source of customer complaints.\", \"vi\": \"Tình trạng ùn tắc tại khu vực khởi hành, đặc biệt là tại quầy làm thủ tục, từ lâu đã là nguyên nhân thường xuyên dẫn đến các khiếu nại từ phía khách hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Some airlines, such as Sunleaf, have addressed similar problems at their gates by creating additional business-class lines for check-in.\", \"vi\": \"Một số hãng hàng không, chẳng hạn như Sunleaf, đã giải quyết những vấn đề tương tự tại các quầy làm thủ tục bằng cách thiết lập thêm các làn dành riêng cho hành khách hạng thương gia.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I suggest that instead we ask airlines to place more staff at their economy check-in lines.\", \"vi\": \"Tôi đề xuất rằng thay vào đó, chúng ta nên yêu cầu các hãng hàng không bố trí thêm nhân viên tại các quầy làm thủ tục hạng phổ thông.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"However, this would require more kiosks and counters.\", \"vi\": \"Tuy nhiên, điều này sẽ đòi hỏi phải có thêm các quầy tự phục vụ và quầy giao dịch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Without extensive remodeling, there just is not enough room here at Granite Springs Airport.\", \"vi\": \"Nếu không tiến hành cải tạo quy mô lớn, sân bay Granite Springs sẽ không có đủ diện tích.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"We need to put together a proposal for next month\'s budget meeting.\", \"vi\": \"Chúng ta cần soạn thảo một đề xuất cho cuộc họp về ngân sách vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I will let Ms. Pembroke know that we are working on a plan.\", \"vi\": \"Tôi sẽ thông báo với bà Pembroke rằng chúng tôi đang xây dựng một kế hoạch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"It can be added to this year\'s budget.\", \"vi\": \"Khoản này có thể được bổ sung vào ngân sách năm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The other issue we still need to discuss is adding more restaurants.\", \"vi\": \"Một vấn đề khác mà chúng ta vẫn cần thảo luận là việc bổ sung thêm các nhà hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Passengers continue to comment about that on surveys.\", \"vi\": \"Hành khách vẫn tiếp tục đưa ra ý kiến về vấn đề này trong các cuộc khảo sát.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Thanks,\", \"vi\": \"Cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Jim Frollo\", \"vi\": \"Jim Frollo\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"GSP Puts Travelers First\", \"vi\": \"GSP luôn đặt lợi ích của hành khách lên hàng đầu\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"By Katherine Herncane\", \"vi\": \"Tác giả: Katherine Herncane\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"(October 10)—Earlier this month, news circulated that the management of Granite Springs Airport (GSP) was considering a big change that would shorten the time passengers wait in line without affecting the price of their ticket.\", \"vi\": \"(Ngày 10 tháng 10) — Vào đầu tháng này, đã có thông tin lan truyền rằng ban quản lý Sân bay Granite Springs (GSP) đang xem xét một thay đổi lớn nhằm rút ngắn thời gian hành khách phải xếp hàng chờ đợi mà không làm ảnh hưởng đến giá vé của họ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"In a conversation with the Granite Springs Journal earlier this week, Airport Operations Chief Claire-Lise Pembroke confirmed that the airport will begin remodeling in the spring to expand the check-in counters for economy travelers.\", \"vi\": \"Trong cuộc phỏng vấn với tờ Granite Springs Journal vào đầu tuần này, Trưởng phòng Vận hành Sân bay Claire-Lise Pembroke đã xác nhận rằng sân bay sẽ bắt đầu công tác cải tạo vào mùa xuân nhằm mở rộng khu vực quầy làm thủ tục dành cho hành khách hạng phổ thông.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Her team is also planning upgrades to airport dining options.\", \"vi\": \"Đội ngũ của bà cũng đang lên kế hoạch nâng cấp các lựa chọn ẩm thực tại sân bay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"\\\"We are excited about the expansion, which will improve the experience for all of our passengers,\\\" Pembroke said.\", \"vi\": \"\\\"Chúng tôi rất hào hứng trước kế hoạch mở rộng này, vốn sẽ giúp nâng cao trải nghiệm cho tất cả hành khách của chúng tôi,\\\" ông Pembroke cho biết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"\\\"The renovations should be completed by the end of next year.\\\"\", \"vi\": \"\\\"Công tác cải tạo dự kiến sẽ hoàn tất vào cuối năm sau.\\\"\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = 'b3b6bfa6-c0bc-4dcc-a30f-d766c3601b4a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Demetri Owens\", \"vi\": \"Kính gửi: Demetri Owens\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Cc: Theodore Scott, Halina Kibera\", \"vi\": \"Gửi kèm: Theodore Scott, Halina Kibera\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"From: Janice Kovack\", \"vi\": \"Từ: Janice Kovack\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: January 10\", \"vi\": \"Ngày: 10 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Subject: Next interview\", \"vi\": \"Chủ đề: Buổi phỏng vấn tiếp theo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Dear Mr. Owens,\", \"vi\": \"Kính gửi ông Owens,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"It was great to speak to you about the security systems manager position.\", \"vi\": \"Thật là một niềm vui được trao đổi với quý vị về vị trí Quản lý hệ thống an ninh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I am pleased to report that I would like you to move on to the next level of interviews.\", \"vi\": \"Tôi rất vui mừng được thông báo rằng tôi mong quý vị sẽ tiến vào vòng phỏng vấn tiếp theo.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"You will speak with the director of security, Mr. Scott, and his assistant, Ms. Kibera.\", \"vi\": \"Quý vị sẽ có cuộc trao đổi với Giám đốc An ninh, ông Scott, và trợ lý của ông, bà Kibera.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I will send another e-mail before the meeting with instructions on how to join the virtual conference call.\", \"vi\": \"Tôi sẽ gửi một email khác trước cuộc họp, trong đó có hướng dẫn cách tham gia cuộc họp trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Meeting date/time: January 12 at 2:30 P.M. Eastern Standard Time\", \"vi\": \"Thời gian và ngày diễn ra cuộc họp: Ngày 12 tháng 1 lúc 2 giờ 30 chiều theo Giờ Chuẩn Miền Đông\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Please confirm that you can make the conference call.\", \"vi\": \"Kính mong Quý vị xác nhận rằng Quý vị có thể tham gia cuộc họp trực tuyến này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"J. Kovack\", \"vi\": \"J. Kovack\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Human Relations Agent\", \"vi\": \"Chuyên viên Quan hệ Nhân sự\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = 'b3c9544e-a9fd-40bf-9e67-aaf0dab8fad0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"VANCOUVER (3 February)—Poalesco unveiled its annual Plant Showcase today.\", \"vi\": \"VANCOUVER (Ngày 3 tháng 2)—Poalesco đã khai mạc Triển lãm Thực vật thường niên của mình vào ngày hôm nay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"According to Poalesco spokesman Nacio Roja, this ______[143] offering highlights the company\'s latest efforts in botanical research.\", \"vi\": \"Theo người phát ngôn của Poalesco, ông Nacio Roja, dòng sản phẩm ______[143] này làm nổi bật những nỗ lực mới nhất của công ty trong lĩnh vực nghiên cứu thực vật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [143]}, {\"en\": \"Many of these efforts result from customer surveys designed to gain an understanding of common challenges.\", \"vi\": \"Nhiều nỗ lực trong số này là kết quả từ các cuộc khảo sát khách hàng nhằm thấu hiểu các thử thách phổ biến.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"______[144].\", \"vi\": \"______[144].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [144]}, {\"en\": \"This year, the company\'s specialized nurseries have turned out drought-hardy breeds, such as the Goldtone Apple Tree.\", \"vi\": \"Năm nay, các vườn ươm chuyên biệt của công ty đã cho ra mắt các giống cây chịu hạn tốt, chẳng hạn như Cây Táo Goldtone.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"These varietals can withstand extended dry conditions without sustaining damage.\", \"vi\": \"Những giống cây này có thể chịu đựng điều kiện khô hạn kéo dài mà không bị tổn hại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"\\\"Gardeners in desert ______[145] will appreciate the Goldtones in particular,\\\" noted Roja.\", \"vi\": \"\\\"Những người làm vườn ở các ______[145] sa mạc sẽ đặc biệt đánh giá cao dòng cây Goldtone,\\\" ông Roja lưu ý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [145]}, {\"en\": \"\\\"And ______[146] might also be interested in our new Q7 rose bushes, which thrive in a similar climate.\\\"\", \"vi\": \"\\\"Và ______[146] cũng có thể quan tâm đến các bụi hoa hồng Q7 mới của chúng tôi, vốn phát triển mạnh trong khí hậu tương tự.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [146]}]' WHERE `id` = 'b3d219c1-c62d-4aee-8875-13157de40502';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Store Managers\", \"vi\": \"Đến: Các Quản lý Cửa hàng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Alain Mareau\", \"vi\": \"Từ: Alain Mareau\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 4 October\", \"vi\": \"Ngày: 4 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Recycling Initiative\", \"vi\": \"Chủ đề: Sáng kiến Tái chế\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hello All,\", \"vi\": \"Xin chào mọi người,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"As one of Australia\'s top electronics retailers, we always ______[143] to maintain our standing as an industry leader.\", \"vi\": \"Là một trong những nhà bán lẻ đồ điện tử hàng đầu của Úc, chúng tôi luôn ______[143] duy trì vị thế là công ty dẫn đầu ngành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [143]}, {\"en\": \"Earlier this year, we began testing a new program that allowed our customers to bring their used electronic devices to our stores for recycling.\", \"vi\": \"Đầu năm nay, chúng tôi đã bắt đầu thử nghiệm một chương trình mới cho phép khách hàng mang các thiết bị điện tử đã qua sử dụng đến cửa hàng của chúng tôi để tái chế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"In exchange they received discounts on their purchases.\", \"vi\": \"Đổi lại, họ nhận được giảm giá khi mua hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The initiative exceeded our expectations.\", \"vi\": \"Sáng kiến này đã vượt quá mong đợi của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"______[144].\", \"vi\": \"______[144].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [144]}, {\"en\": \"In late November, all store managers will be sent ______[145] instructions on how to collect items and send them to our recycling partner.\", \"vi\": \"Vào cuối tháng 11, tất cả các quản lý cửa hàng sẽ được gửi ______[145] hướng dẫn về cách thu gom các mặt hàng và gửi chúng cho đối tác tái chế của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [145]}, {\"en\": \"______[146], we will be announcing the program to the public via social media and print ads beginning in mid-November.\", \"vi\": \"______[146], chúng tôi sẽ thông báo chương trình này ra công chúng qua mạng xã hội và quảng cáo in ấn bắt đầu từ giữa tháng 11.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": [146]}, {\"en\": \"Please anticipate further updates and instructions on this exciting initiative.\", \"vi\": \"Vui lòng chờ đón các thông tin cập nhật và hướng dẫn tiếp theo về sáng kiến thú vị này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Alain Mareau\", \"vi\": \"Alain Mareau\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Vice President, Product Development\", \"vi\": \"Phó Chủ tịch Phụ trách Phát triển Sản phẩm\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}]' WHERE `id` = 'b42e6d18-5bd5-44f9-863d-4780656c4468';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"NOTICE\", \"vi\": \"THÔNG BÁO\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"As part of our routine maintenance of Selino Apartments, all public areas of our building will be painted according to the following schedule:\", \"vi\": \"Trong khuôn khổ công tác bảo trì định kỳ tại Khu căn hộ Selino, tất cả các khu vực công cộng trong tòa nhà của chúng tôi sẽ được sơn lại theo lịch trình như sau:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"• Stairwells, first and second floors: 12 April\", \"vi\": \"• Khu vực cầu thang, tầng 1 và tầng 2: ngày 12 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"• Hallways, first and second floors: 13 April\", \"vi\": \"• Các hành lang, tầng một và tầng hai: ngày 13 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"• Stairwells, third and fourth floors: 14 April\", \"vi\": \"• Khu vực cầu thang, tầng 3 và tầng 4: ngày 14 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"• Hallways, third and fourth floors: 15 April\", \"vi\": \"• Các hành lang, tầng ba và tầng bốn: ngày 15 tháng 4\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The elevators will be available during this time.\", \"vi\": \"Trong khoảng thời gian này, các thang máy sẽ vẫn hoạt động bình thường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Please use caution, and do not touch any wet paint.\", \"vi\": \"Xin quý vị hãy cẩn thận và không chạm vào bất kỳ lớp sơn còn ướt nào.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Management, Selino Apartments\", \"vi\": \"Ban Quản lý, Khu căn hộ Selino\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}]' WHERE `id` = 'b4412fe3-4c48-47ae-86ab-7b6434027bee';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Tottenton Community Online Message Board > General\", \"vi\": \"Diễn đàn trực tuyến Cộng đồng Tottenton > Chung\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Posted by Thalia Finley on Thursday, 14 September, at 11:41 A.M.:\", \"vi\": \"Được đăng bởi Thalia Finley vào thứ Năm, ngày 14 tháng 9, lúc 11 giờ 41 phút sáng:\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I am a documentary filmmaker working to tell the story of how Tottenton evolved from a decaying industrial town into a hub for environmentally responsible building initiatives and sustainable architectural design.\", \"vi\": \"Tôi là một nhà làm phim tài liệu, đang nỗ lực kể lại câu chuyện về quá trình Tottenton chuyển mình từ một thị trấn công nghiệp đang suy tàn thành một trung tâm của các sáng kiến xây dựng thân thiện với môi trường và thiết kế kiến trúc bền vững.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"I am seeking Tottenton residents at least 50 years of age who lived here during the period of transition and can tell me what it was like.\", \"vi\": \"Tôi đang tìm kiếm những cư dân Tottenton từ 50 tuổi trở lên, những người đã sinh sống tại đây trong giai đoạn chuyển tiếp và có thể chia sẻ với tôi về những trải nghiệm lúc bấy giờ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"If you are interested in participating, please call me at 020 7946 0532.\", \"vi\": \"Nếu quý vị quan tâm đến việc tham gia, xin vui lòng gọi cho tôi theo số 020 7946 0532.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I\'ll then send you a personal release form to fill out, and we can arrange to meet for a 30- to 45-minute interview.\", \"vi\": \"Sau đó, tôi sẽ gửi cho quý vị một mẫu đơn đồng ý cá nhân để quý vị điền vào, và chúng ta có thể sắp xếp một cuộc gặp để thực hiện buổi phỏng vấn kéo dài từ 30 đến 45 phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}]' WHERE `id` = 'b4a4fca0-e18a-4cb2-9a7f-5f5e7ca0bf77';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Minutes of the Special Meeting of the Arlford City Council\", \"vi\": \"Biên bản cuộc họp đặc biệt của Hội đồng Thành phố Arlford\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"14 January\", \"vi\": \"Ngày 14 tháng 1\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Winglite Airlines to Begin Service from Arlford Regional Airport\", \"vi\": \"Hãng hàng không Winglite sẽ bắt đầu khai thác các chuyến bay từ Sân bay Khu vực Arlford\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"1. Call to Order\", \"vi\": \"1. Mở đầu phiên họp\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Mayor Tremblay called the meeting to order at 6:30 P.M. All members were present.\", \"vi\": \"Thị trưởng Tremblay tuyên bố khai mạc cuộc họp vào lúc 6 giờ 30 phút chiều. Tất cả các thành viên đều có mặt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"2.\", \"vi\": \"2.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Vote Taken on Resolution No. 2023-167B\", \"vi\": \"Đã tiến hành bỏ phiếu về Nghị quyết số 2023-167B\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The council approved a resolution to earmark $1.5 million for costs related to establishing Winglite Airlines service at the Arlford Regional Airport.\", \"vi\": \"Hội đồng đã thông qua một nghị quyết dành riêng 1,5 triệu đô la để chi trả các chi phí liên quan đến việc thiết lập dịch vụ của Hãng hàng không Winglite tại Sân bay Khu vực Arlford.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The resolution, authorising an adjustment to the Airport Operating Fund, was passed by a vote of 7-0.\", \"vi\": \"Nghị quyết cho phép điều chỉnh Quỹ Vận hành Sân bay đã được thông qua với tỷ lệ phiếu bầu 7-0.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Winglite Airlines and the city will bear some costs equally.\", \"vi\": \"Hãng hàng không Winglite và thành phố sẽ chia sẻ một phần chi phí theo tỷ lệ ngang nhau.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Costs to be split include recruitment and training of additional security and emergency services workers.\", \"vi\": \"Các chi phí cần được chia sẻ bao gồm chi phí tuyển dụng và đào tạo thêm nhân viên an ninh và nhân viên dịch vụ khẩn cấp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Other expenses will be covered 100 percent by the city of Arlford.\", \"vi\": \"Các chi phí khác sẽ được thành phố Arlford chi trả 100%.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Chief among these is the construction of another lane on Aviation Boulevard to accommodate the expected increase in airport traffic.\", \"vi\": \"Trong số đó, việc xây dựng thêm một làn đường trên Đại lộ Hàng không nhằm đáp ứng sự gia tăng dự kiến của lưu lượng giao thông tại sân bay là ưu tiên hàng đầu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Work on the boulevard will start immediately so that it will be finished before the airline begins its service.\", \"vi\": \"Công việc thi công trên đại lộ sẽ được triển khai ngay lập tức để đảm bảo hoàn thành trước khi hãng hàng không bắt đầu khai thác các chuyến bay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"3.\", \"vi\": \"3.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Adjournment\", \"vi\": \"Tạm hoãn phiên họp\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The meeting was adjourned at 7:25 P.M.\", \"vi\": \"Cuộc họp đã kết thúc vào lúc 7 giờ 25 phút tối.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"ARLFORD (18 March)—Darwin-based carrier Winglite Airlines has announced plans to begin nonstop daily flights between Arlford Regional Airport and Cranton.\", \"vi\": \"ARLFORD (ngày 18 tháng 3) — Hãng hàng không Winglite Airlines có trụ sở tại Darwin đã công bố kế hoạch khai trương các chuyến bay thẳng hàng ngày giữa Sân bay Khu vực Arlford và Cranton.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Winglite Airlines is one of several recent start-ups specialising in flying to smaller markets in Australia that are not served by the main airlines.\", \"vi\": \"Hãng hàng không Winglite là một trong số các công ty khởi nghiệp mới thành lập gần đây, chuyên khai thác các chuyến bay đến các thị trường nhỏ hơn tại Úc mà các hãng hàng không lớn chưa phục vụ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"“We look forward to providing the region’s residents with affordable, convenient service to Cranton,” stated Savita Grewal, public relations director at Winglite Airlines.\", \"vi\": \"“Chúng tôi rất mong được cung cấp cho người dân trong khu vực dịch vụ di chuyển đến Cranton với chi phí hợp lý và thuận tiện,” bà Savita Grewal, Giám đốc Quan hệ Công chúng của Hãng hàng không Winglite, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"According to Ms. Grewal, the airline has scheduled its inaugural flight from Arlford Regional Airport for 1 August.\", \"vi\": \"Theo bà Grewal, hãng hàng không này đã lên lịch cho chuyến bay khai trương khởi hành từ Sân bay Khu vực Arlford vào ngày 1 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Initially, Winglite will offer two daily flights to Cranton.\", \"vi\": \"Ban đầu, Winglite sẽ khai thác hai chuyến bay mỗi ngày đến Cranton.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Additional destinations are being considered for the future, including Eider Bay and West Linport.\", \"vi\": \"Các điểm đến khác cũng đang được xem xét cho tương lai, bao gồm Vịnh Eider và West Linport.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"A decision regarding added routes is expected by 31 December.\", \"vi\": \"Dự kiến sẽ có quyết định về việc bổ sung các tuyến bay trước ngày 31 tháng 12.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"To: oliverp01@roommateroundup.com\", \"vi\": \"Gửi tới: oliverp01@roommateroundup.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"From: sgirard@emailcloud.com\", \"vi\": \"Nguồn: sgirard@emailcloud.com\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Date: 15 July\", \"vi\": \"Ngày: 15 tháng 7\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Subject: Room in downtown Arlford\", \"vi\": \"Chủ đề: Phòng trọ tại trung tâm thành phố Arlford\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Hello, Oliver,\", \"vi\": \"Xin chào, Oliver,\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"I am interested in sharing the apartment you listed on the Roommate Roundup Web site.\", \"vi\": \"Tôi quan tâm đến việc chia sẻ căn hộ mà quý vị đã đăng trên trang web Roommate Roundup.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"I’m looking for a fully furnished space with a private bathroom, and I see that yours has all that plus the bonus of reserved parking.\", \"vi\": \"Tôi đang tìm một căn hộ được trang bị đầy đủ nội thất và có phòng tắm riêng, và tôi thấy rằng căn hộ của quý vị không chỉ đáp ứng đầy đủ những tiêu chí đó mà còn có thêm ưu điểm là chỗ đỗ xe dành riêng.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"At $850, including utilities, the monthly rent is just within my budget.\", \"vi\": \"Với mức giá 850 đô la, đã bao gồm các khoản phí tiện ích, tiền thuê hàng tháng vừa vặn trong ngân sách của tôi.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"I agree to give you the required security deposit of one month’s rent in advance.\", \"vi\": \"Tôi đồng ý nộp trước cho quý vị khoản tiền đặt cọc bảo đảm theo quy định, tương đương một tháng tiền thuê nhà.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"I am quiet, easygoing, and reasonably neat.\", \"vi\": \"Tôi là người trầm tính, dễ tính và khá gọn gàng.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"I work as a flight attendant with Winglite Airlines.\", \"vi\": \"Tôi hiện đang làm việc với tư cách là tiếp viên hàng không tại Hãng hàng không Winglite.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"I have been assigned to the airline’s new route out of Arlford that begins next month.\", \"vi\": \"Tôi đã được phân công phụ trách chặng bay mới của hãng hàng không khởi hành từ Arlford, dự kiến sẽ bắt đầu vào tháng tới.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"I will be in Arlford only half the time and will stay in a hotel near my destination airport for the rest of the week.\", \"vi\": \"Tôi sẽ chỉ ở Arlford trong một nửa thời gian và sẽ lưu trú tại một khách sạn gần sân bay đích trong phần còn lại của tuần.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"That means you would have the apartment to yourself much of the time.\", \"vi\": \"Điều đó có nghĩa là quý vị sẽ có toàn bộ căn hộ cho riêng mình trong phần lớn thời gian.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"I’m currently in Eider Bay but will be back next week.\", \"vi\": \"Hiện tại tôi đang ở Vịnh Eider, nhưng sẽ trở lại vào tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Could we set a time when I can meet you and look at the apartment?\", \"vi\": \"Chúng ta có thể hẹn một thời gian để tôi có thể gặp quý vị và xem căn hộ được không ạ?\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Many thanks,\", \"vi\": \"Xin chân thành cảm ơn,\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Stuart Girard\", \"vi\": \"Stuart Girard\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 42, \"question_numbers\": []}]' WHERE `id` = 'b4cb2d18-3157-4d61-af16-8e7d93df96e3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"LONG ISLAND REGIONAL ENERGY AUTHORITY\", \"vi\": \"CƠ QUAN NĂNG LƯỢNG VÙNG LONG ISLAND\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Residential Audit\", \"vi\": \"Kiểm toán khu dân cư\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Prepared for customer: Darrah Henninger\", \"vi\": \"Chuẩn bị cho quý khách hàng: Darrah Henninger\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Property address: 337 Barrel Street, Hempstead, NY 11550\", \"vi\": \"Địa chỉ bất động sản: 337 Barrel Street, Hempstead, NY 11550\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Reason for audit request: The customer reported unusually high energy bills and an inefficient cooling system during the warmest months.\", \"vi\": \"Lý do yêu cầu kiểm toán: Khách hàng đã phản ánh hóa đơn tiền điện cao bất thường và hệ thống làm mát hoạt động kém hiệu quả trong những tháng nóng nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Date of visit: August 26\", \"vi\": \"Ngày thăm quan: 26 tháng 8\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Inspection summary: The building size is approximately 366 square meters, and there is an exterior air-conditioning unit on the west side of the structure.\", \"vi\": \"Tóm tắt kết quả kiểm tra: Diện tích tòa nhà khoảng 366 mét vuông và có một dàn lạnh ngoài trời ở phía tây của công trình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The unit was installed new and is six years old.\", \"vi\": \"Thiết bị này được lắp đặt mới và hiện đã được sáu năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The size of the cooling unit is more than sufficient for the building size.\", \"vi\": \"Kích thước của hệ thống làm mát là quá đủ so với quy mô của tòa nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"However, the return air flows through a vent that is too small.\", \"vi\": \"Tuy nhiên, luồng không khí hồi lưu lại đi qua một lỗ thông gió có kích thước quá nhỏ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Expanding the current vent size or creating an additional vent on an adjacent wall will correct this issue.\", \"vi\": \"Việc mở rộng kích thước lỗ thông gió hiện tại hoặc tạo thêm một lỗ thông gió trên bức tường liền kề sẽ khắc phục được vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"The building has a vaulted metal roof that is poorly insulated.\", \"vi\": \"Tòa nhà này có mái vòm bằng kim loại với khả năng cách nhiệt kém.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Reinsulating the roof is recommended.\", \"vi\": \"Chúng tôi khuyến nghị quý vị nên tiến hành cách nhiệt lại mái nhà.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The use of ceiling fans on the upper level should be avoided in the warm months.\", \"vi\": \"Trong những tháng nóng, nên tránh sử dụng quạt trần ở tầng trên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Because the roof is not insulated well, the fans use an excessive amount of energy to combat the heat transfer through the ceiling during the summer, and therefore the rooms cannot be adequately cooled.\", \"vi\": \"Do mái nhà không được cách nhiệt tốt, nên vào mùa hè, các quạt phải tiêu thụ một lượng năng lượng quá lớn để chống lại sự truyền nhiệt qua trần nhà, và do đó, các phòng không thể được làm mát một cách đầy đủ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"This audit has been performed by a certified energy auditor.\", \"vi\": \"Cuộc kiểm toán này đã được thực hiện bởi một chuyên gia kiểm toán năng lượng được chứng nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Audit prepared by: Kevin Anders\", \"vi\": \"Báo cáo kiểm toán do ông Kevin Anders lập\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}]' WHERE `id` = 'b50c26c5-38d7-4787-92fa-9fdf0b906de3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"PRODUCT DEMONSTRATORS NEEDED!\", \"vi\": \"CẦN TUYỂN NHÂN VIÊN GIỚI THIỆU SẢN PHẨM!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Are you outgoing and enthusiastic?\", \"vi\": \"Quý vị có tính cách cởi mở và nhiệt tình không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"— [1] — Do you enjoy talking to all types of people?\", \"vi\": \"— [1] — Quý vị có thích trò chuyện với mọi loại người không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Put your personality and communication skills to work!\", \"vi\": \"Hãy phát huy tính cách và kỹ năng giao tiếp của quý vị!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"BBD Staffing is seeking to hire in-store product demonstrators to promote our clients’ merchandise to shoppers.\", \"vi\": \"Công ty BBD Staffing đang tuyển dụng nhân viên trình diễn sản phẩm tại cửa hàng để quảng bá hàng hóa của các khách hàng của chúng tôi tới người mua sắm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"As a member of our team, you will demonstrate a wide range of small kitchen appliances and tools in grocery stores and other retail venues.\", \"vi\": \"Với tư cách là thành viên của đội ngũ chúng tôi, quý vị sẽ thực hiện việc giới thiệu và trình diễn đa dạng các loại thiết bị và dụng cụ nhà bếp cỡ nhỏ tại các cửa hàng tạp hóa cũng như các điểm bán lẻ khác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"For some products, you will be required to prepare simple recipes.\", \"vi\": \"Đối với một số sản phẩm, quý vị sẽ được yêu cầu chuẩn bị các công thức nấu ăn đơn giản.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"You will also need to answer shoppers’ questions.\", \"vi\": \"Quý vị cũng sẽ cần trả lời các câu hỏi của người mua hàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Thus, it is essential that you can become familiar with clients’ products and provide key information to consumers.\", \"vi\": \"Do đó, điều quan trọng là quý vị phải làm quen với các sản phẩm của khách hàng và cung cấp những thông tin quan trọng cho người tiêu dùng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Because many of the demonstrations require working with food, candidates must have a Professional Food Handler certificate.\", \"vi\": \"Do nhiều buổi trình diễn đòi hỏi phải tiếp xúc với thực phẩm, các ứng viên phải có Chứng chỉ Chuyên viên Xử lý Thực phẩm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"To apply, upload a video of no more than one minute in length telling us why you would be a successful product demonstrator at www.bbdstaffing.com/applications.\", \"vi\": \"Để nộp đơn ứng tuyển, vui lòng tải lên một đoạn video có thời lượng không quá một phút, trong đó giải thích lý do tại sao quý vị sẽ là một chuyên viên trình diễn sản phẩm xuất sắc tại địa chỉ www.bbdstaffing.com/applications.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = 'b510895b-e1ab-4477-89d5-061db50261ac';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"The Galindo CT7 is an 1150-watt countertop microwave oven with a rotating turntable that can accommodate dishes of up to 13 inches in diameter.\", \"vi\": \"Galindo CT7 là một lò vi sóng để bàn công suất 1.150 watt, được trang bị đĩa xoay có thể chứa các đĩa có đường kính lên đến 13 inch.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Its SmartCook technology can heat up five common foods like popcorn and chicken at pre-programmed power levels until its steam sensor determines that they are done, while the defrost feature makes it easy to thaw frozen foods.\", \"vi\": \"Công nghệ SmartCook của sản phẩm này có thể làm nóng năm loại thực phẩm phổ biến như bắp rang bơ và thịt gà ở các mức công suất đã được cài đặt sẵn cho đến khi cảm biến hơi nước xác định rằng chúng đã chín, trong khi tính năng rã đông giúp quý vị dễ dàng rã đông thực phẩm đông lạnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Reviewer: Kyla Townsend\", \"vi\": \"Người đánh giá: Kyla Townsend\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date posted: January 9\", \"vi\": \"Ngày đăng: 9 tháng 1\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"My parents gave me their four-year-old CT7 microwave when I moved into my first apartment a few months ago.\", \"vi\": \"Khi tôi dọn vào căn hộ đầu tiên của mình cách đây vài tháng, bố mẹ tôi đã tặng tôi chiếc lò vi sóng CT7 đã sử dụng được bốn năm của họ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I have been using it a lot, because I eat Hansen ReadyMeals—those plastic bowls of food you put straight into the microwave—a few times a week.\", \"vi\": \"Tôi đã sử dụng nó rất thường xuyên, bởi vì tôi ăn các món Hansen ReadyMeals — những hộp thức ăn bằng nhựa mà quý vị có thể cho thẳng vào lò vi sóng — vài lần mỗi tuần.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Then, last week, the turntable stopped rotating.\", \"vi\": \"Rồi, vào tuần trước, bàn xoay đã ngừng quay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The microwave has a five-year warranty, so I called the closest certified Galindo repair service and set up an appointment.\", \"vi\": \"Lò vi sóng này có chế độ bảo hành năm năm, vì vậy tôi đã gọi điện cho trung tâm bảo hành được ủy quyền của Galindo gần nhất và đặt lịch hẹn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The technician said the drive motor will need to be replaced and asked to see my warranty.\", \"vi\": \"Kỹ thuật viên cho biết động cơ truyền động sẽ cần phải được thay thế và yêu cầu tôi xuất trình giấy bảo hành.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"He then looked at the name on it and said the agreement is no longer valid because it can\'t be transferred between owners.\", \"vi\": \"Sau đó, ông nhìn vào tên ghi trên đó và cho biết thỏa thuận này không còn hiệu lực nữa vì không thể chuyển nhượng giữa các chủ sở hữu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Instead of being free, my repair will cost about $200, which is disappointing.\", \"vi\": \"Thay vì được miễn phí, chi phí sửa chữa của tôi sẽ vào khoảng 200 đô la, điều này thật đáng thất vọng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I am posting this review to warn others who might not be aware of this condition of the warranty agreement.\", \"vi\": \"Tôi đăng bài đánh giá này nhằm cảnh báo những người khác có thể chưa nắm rõ điều khoản này trong thỏa thuận bảo hành.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"http://www.galindo.com/reviews\", \"vi\": \"http://www.galindo.com/reviews\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"▼\", \"vi\": \"▼\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"To: Kyla Townsend <k.townsend@you-mail.com>\", \"vi\": \"Gửi tới: Kyla Townsend <k.townsend@you-mail.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"From: Grant Osborne <gosborne@galindo.com>\", \"vi\": \"Từ: Grant Osborne <gosborne@galindo.com>\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Subject: Galindo CT7\", \"vi\": \"Chủ đề: Galindo CT7\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Date: January 10\", \"vi\": \"Ngày: 10 tháng 1\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Dear Ms. Townsend,\", \"vi\": \"Kính gửi bà Townsend,\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"I am writing in regard to the review you posted on our Web site.\", \"vi\": \"Tôi viết thư này để đề cập đến bài đánh giá mà quý vị đã đăng trên trang web của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"As a member of the Galindo customer service team, I would like to clarify that the policy that warranties are non-transferable was introduced two years ago and does not apply to purchases made before then.\", \"vi\": \"Với tư cách là thành viên của đội ngũ dịch vụ khách hàng Galindo, tôi xin được làm rõ rằng chính sách quy định bảo hành không được chuyển nhượng đã được áp dụng từ hai năm trước và không áp dụng đối với các giao dịch mua hàng thực hiện trước thời điểm đó.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"I apologize for the difficulty you have experienced with your microwave\'s functioning and with the service provided by our certified repair partner.\", \"vi\": \"Tôi xin gửi lời xin lỗi về những khó khăn mà quý khách đã gặp phải liên quan đến hoạt động của lò vi sóng cũng như dịch vụ do đối tác sửa chữa được chứng nhận của chúng tôi cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Customer satisfaction is of utmost importance to Galindo, so I would like to offer my assistance with resolving this issue.\", \"vi\": \"Sự hài lòng của quý khách hàng là ưu tiên hàng đầu đối với Galindo, vì vậy tôi xin được hỗ trợ quý khách giải quyết vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"Please let me know the name of the company that you interacted with.\", \"vi\": \"Xin vui lòng cho tôi biết tên công ty mà quý vị đã liên hệ.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"I will reach out to its management and ensure that your repair is handled properly.\", \"vi\": \"Tôi sẽ liên hệ với ban quản lý của công ty đó và đảm bảo rằng việc sửa chữa của quý vị sẽ được xử lý một cách thỏa đáng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Grant Osborne\", \"vi\": \"Grant Osborne\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Customer Service Representative\", \"vi\": \"Nhân viên Dịch vụ Khách hàng\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"E-Mail message\", \"vi\": \"Thư điện tử\", \"type\": \"sign_off\", \"doc_index\": 2, \"sentence_id\": 29, \"question_numbers\": []}]' WHERE `id` = 'b526d951-9e25-4b83-9cad-0a9ed1732ce8';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"SLEEP SOUNDLY SOLUTIONS\", \"vi\": \"CÁC GIẢI PHÁP GIÚP NGỦ NGON GIẤC\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Thank you for choosing Sleep Soundly Solutions!\", \"vi\": \"Xin chân thành cảm ơn quý vị đã lựa chọn Sleep Soundly Solutions!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"The updated control panel is linked to an integrated system that allows you to activate and disable all security systems in your home, including your Sleep Soundly motion sensor as well as your fire, smoke, and carbon monoxide detectors.\", \"vi\": \"Bảng điều khiển được cập nhật này được kết nối với một hệ thống tích hợp, cho phép quý vị kích hoạt và tắt tất cả các hệ thống an ninh trong nhà, bao gồm cả cảm biến chuyển động Sleep Soundly cũng như các thiết bị báo cháy, báo khói và báo khí carbon monoxide.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"All Sleep Soundly residential alarm systems have been tested thoroughly to ensure the highest quality and sensitivity, so you can sleep soundly in the knowledge that your home is protected.\", \"vi\": \"Tất cả các hệ thống báo động dân dụng của Sleep Soundly đều đã được kiểm tra kỹ lưỡng để đảm bảo chất lượng và độ nhạy cao nhất, nhờ đó quý vị có thể yên tâm ngủ ngon giấc khi biết rằng ngôi nhà của mình đang được bảo vệ an toàn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We have also developed a new smartphone application that will notify you of any disturbances wherever you are.\", \"vi\": \"Chúng tôi cũng đã phát triển một ứng dụng điện thoại thông minh mới, giúp thông báo cho quý vị về bất kỳ sự cố nào, bất kể quý vị đang ở đâu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The app is available for download now.\", \"vi\": \"Ứng dụng hiện đã có sẵn để quý vị tải về.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Sleep Soundly control equipment is carefully manufactured for use with Sleep Soundly detectors and alarms.\", \"vi\": \"Thiết bị điều khiển Sleep Soundly được sản xuất một cách cẩn thận để sử dụng cùng với các thiết bị phát hiện và báo động Sleep Soundly.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Using products manufactured by other companies may result in an alarm system that does not meet safety requirements for residential buildings or comply with local laws.\", \"vi\": \"Việc sử dụng các sản phẩm do các công ty khác sản xuất có thể dẫn đến hệ thống báo động không đáp ứng các yêu cầu an toàn đối với các tòa nhà dân cư hoặc không tuân thủ các quy định pháp luật địa phương.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}]' WHERE `id` = 'b54e6346-812c-44e5-a642-b01b93ab81c4';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Brett Tennison (8:16 A.M.)\", \"vi\": \"Brett Tennison (8 giờ 16 phút sáng)\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Lianne and Shruthi.\", \"vi\": \"Xin chào, Lianne và Shruthi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Did you two get the e-mail I sent yesterday?\", \"vi\": \"Hai vị đã nhận được email mà tôi gửi hôm qua chưa?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Lianne Gammon (8:17 A.M.)\", \"vi\": \"Lianne Gammon (8 giờ 17 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"About the company video you want to make?\", \"vi\": \"Về video giới thiệu công ty mà quý vị muốn thực hiện?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Brett Tennison (8:18 A.M.)\", \"vi\": \"Brett Tennison (8 giờ 18 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Yes.\", \"vi\": \"Vâng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"People want to feel a personal connection to the companies they work with.\", \"vi\": \"Mọi người mong muốn cảm nhận được sự gắn kết cá nhân với các công ty mà họ hợp tác.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"A video could help potential clients relate better to our team and generate business.\", \"vi\": \"Một đoạn video có thể giúp các khách hàng tiềm năng cảm thấy gần gũi hơn với đội ngũ của chúng tôi và từ đó tạo ra cơ hội kinh doanh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Shruthi Mehta (8:19 A.M.)\", \"vi\": \"Shruthi Mehta (8 giờ 19 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"I drafted an e-mail in response, but I haven\'t sent it yet.\", \"vi\": \"Tôi đã soạn sẵn một email để trả lời, nhưng vẫn chưa gửi đi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I wanted to go over it in my mind before sharing.\", \"vi\": \"Tôi muốn suy ngẫm kỹ về vấn đề này trước khi chia sẻ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Lianne Gammon (8:20 A.M.)\", \"vi\": \"Lianne Gammon (8 giờ 20 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"I like the idea.\", \"vi\": \"Tôi thấy ý tưởng này hay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"We\'ll have to be creative to get people interested, though.\", \"vi\": \"Tuy nhiên, chúng ta sẽ phải sáng tạo một chút để thu hút sự quan tâm của mọi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Shruthi Mehta (8:21 A.M.)\", \"vi\": \"Shruthi Mehta (8 giờ 21 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I\'m not convinced that a video about us is a good idea.\", \"vi\": \"Tôi không chắc rằng việc quay một đoạn video về chúng ta là một ý tưởng hay.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"I just work at my computer all day.\", \"vi\": \"Tôi chỉ ngồi làm việc trước máy tính cả ngày thôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Who would want to watch that?\", \"vi\": \"Ai lại muốn xem cái đó chứ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Brett Tennison (8:22 A.M.)\", \"vi\": \"Brett Tennison (8 giờ 22 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"That\'s why I asked for input.\", \"vi\": \"Đó chính là lý do tại sao tôi đã xin ý kiến của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"We\'ll want the video to show our personalities as well as what it is that we do.\", \"vi\": \"Chúng tôi mong muốn đoạn video này không chỉ thể hiện công việc của chúng tôi mà còn phản ánh được tính cách của mỗi người.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"We can hire professionals to edit it.\", \"vi\": \"Chúng ta có thể thuê các chuyên gia để chỉnh sửa bản thảo này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"But let\'s first decide how we want it to be structured and then record it ourselves.\", \"vi\": \"Tuy nhiên, trước tiên chúng ta hãy quyết định xem muốn bố cục như thế nào, sau đó tự mình thu âm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Lianne Gammon (8:23 A.M.)\", \"vi\": \"Lianne Gammon (8 giờ 23 phút sáng)\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Why don\'t we make a few—so that we can reach different audiences?\", \"vi\": \"Sao chúng ta không tạo ra một vài phiên bản—để có thể tiếp cận các đối tượng khán giả khác nhau?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"How about a short one to use as a paid ad and a longer one to post on our Web site?\", \"vi\": \"Hay là chúng ta nên chuẩn bị một bài ngắn để dùng làm quảng cáo trả phí và một bài dài hơn để đăng trên trang web của chúng ta thì sao?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 27, \"question_numbers\": []}]' WHERE `id` = 'b551304e-5f6d-4f10-b2c5-522dc85d85db';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dear Ms. Lee:\", \"vi\": \"Kính gửi bà Lee:\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"You are now able to enroll in Front Street Bank’s new Voice Identification System (VIS).\", \"vi\": \"Quý vị hiện đã có thể đăng ký sử dụng Hệ thống Nhận dạng Giọng nói (VIS) mới của Ngân hàng Front Street.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"VIS is a fast, convenient, and secure way to access and control your bank accounts by phone.\", \"vi\": \"VIS là một phương thức nhanh chóng, tiện lợi và an toàn để truy cập và quản lý các tài khoản ngân hàng của quý vị qua điện thoại.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"For example, you can make a payment on a Front Street Bank loan by saying “loan payment.”\", \"vi\": \"Ví dụ, quý vị có thể thực hiện thanh toán khoản vay tại Ngân hàng Front Street bằng cách nói “thanh toán khoản vay”.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"You can check your credit-card transactions by saying “recent transactions.”\", \"vi\": \"Quý vị có thể kiểm tra các giao dịch thẻ tín dụng của mình bằng cách nói “các giao dịch gần đây”.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"You can even transfer money between accounts by saying “transfer.”\", \"vi\": \"Quý vị thậm chí còn có thể chuyển tiền giữa các tài khoản chỉ bằng cách nói “chuyển tiền”.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Discover all the ways VIS can simplify your banking life at www.frontstreetbank.com/VIS.\", \"vi\": \"Hãy khám phá tất cả những cách mà VIS có thể giúp đơn giản hóa cuộc sống ngân hàng của quý vị tại www.frontstreetbank.com/VIS.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Your voice identification is stored securely by Front Street Bank and can be used only with Front Street Bank.\", \"vi\": \"Thông tin nhận dạng giọng nói của quý vị được Ngân hàng Front Street lưu trữ một cách an toàn và chỉ có thể được sử dụng tại Ngân hàng Front Street.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Call 615-555-0189 to set up VIS for your accounts.\", \"vi\": \"Vui lòng gọi số 615-555-0189 để thiết lập dịch vụ VIS cho các tài khoản của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"If in the future you no longer wish to use VIS to access your account, simply call to have one of our customer-service representatives delete your identification file.\", \"vi\": \"Nếu trong tương lai quý vị không còn muốn sử dụng VIS để truy cập tài khoản của mình, quý vị chỉ cần gọi điện để yêu cầu một trong các nhân viên dịch vụ khách hàng của chúng tôi xóa hồ sơ nhận dạng của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Thank you for being a valued Front Street Bank customer.\", \"vi\": \"Xin chân thành cảm ơn quý khách đã là khách hàng quý báu của Ngân hàng Front Street.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Robert Wang, Branch Manager\", \"vi\": \"Ông Robert Wang, Giám đốc Chi nhánh\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = 'b563b96d-2004-43c7-b935-af2e92c47ac3';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"LONDON (20 May)—Narvalis, a marine-transport company based in Le Havre, France, announced last week that it has once again added to its cargo fleet.\", \"vi\": \"LONDON (ngày 20 tháng 5) — Narvalis, một công ty vận tải hàng hải có trụ sở tại Le Havre, Pháp, đã thông báo vào tuần trước rằng công ty này một lần nữa đã mở rộng đội tàu chở hàng của mình.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"A Danish vessel, dubbed the Epsilon, was purchased from a Copenhagen-based company to be Narvalis\' largest ship.\", \"vi\": \"Một tàu của Đan Mạch, có tên là Epsilon, đã được mua lại từ một công ty có trụ sở tại Copenhagen để trở thành con tàu lớn nhất của Narvalis.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"It will be docked in a separate location for cleaning and inspection before officially entering service out of Le Havre.\", \"vi\": \"Tàu sẽ được neo đậu tại một địa điểm riêng biệt để tiến hành vệ sinh và kiểm tra trước khi chính thức đi vào hoạt động tại cảng Le Havre.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Narvalis maintains a fleet of twenty medium- and large-sized vessels, transporting primarily grains and iron ore between international destinations.\", \"vi\": \"Narvalis vận hành một đội tàu gồm hai mươi chiếc tàu cỡ trung và lớn, chủ yếu chuyên chở ngũ cốc và quặng sắt giữa các cảng quốc tế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"\\\"Our board unanimously decided to invest in this secondhand vessel to expand our operations,\\\" said company president Emmanuel Brodeur.\", \"vi\": \"\\\"Hội đồng quản trị của chúng tôi đã nhất trí quyết định đầu tư vào con tàu đã qua sử dụng này nhằm mở rộng hoạt động kinh doanh,\\\" ông Emmanuel Brodeur, Chủ tịch công ty, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"\\\"We believe that the substantial scale of this vessel will allow us to deliver certain shipments more efficiently.\\\"\", \"vi\": \"\\\"Chúng tôi tin rằng quy mô lớn của con tàu này sẽ giúp chúng tôi vận chuyển một số lô hàng một cách hiệu quả hơn.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"From: zbernard@narvalis.fr\", \"vi\": \"Từ: zbernard@narvalis.fr\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To: asharma@daruunco.co.in\", \"vi\": \"Gửi tới: asharma@daruunco.co.in\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Date: 22 May\", \"vi\": \"Ngày: 22 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Subject: Your transport needs\", \"vi\": \"Chủ đề: Nhu cầu vận chuyển của quý vị\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Dear Mr. Sharma,\", \"vi\": \"Kính gửi ông Sharma,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Thank you for contacting me.\", \"vi\": \"Xin cảm ơn quý vị đã liên hệ với tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"I think that the Epsilon would be the best option for your company\'s needs.\", \"vi\": \"Tôi cho rằng Epsilon sẽ là lựa chọn phù hợp nhất với nhu cầu của công ty quý vị.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Given its size, it would take longer to arrive in Mumbai than our other vessels.\", \"vi\": \"Do kích thước của con tàu này, thời gian để nó cập cảng Mumbai sẽ lâu hơn so với các tàu khác của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"However, it provides unparalleled cargo space, which will allow for your goods to be transported as a single shipment.\", \"vi\": \"Tuy nhiên, phương tiện này mang lại không gian chứa hàng hóa vô song, giúp quý vị có thể vận chuyển hàng hóa của mình dưới dạng một lô hàng duy nhất.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"This will greatly simplify logistics on the receiving end.\", \"vi\": \"Điều này sẽ giúp đơn giản hóa đáng kể công tác hậu cần tại phía nhận hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Following its purchase in Copenhagen, the Epsilon was routed to Amsterdam in the Netherlands for several days.\", \"vi\": \"Sau khi được mua tại Copenhagen, chiếc Epsilon đã được chuyển đến Amsterdam, Hà Lan, và ở lại đó trong vài ngày.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The plan is that it will next head to our headquarters in Le Havre.\", \"vi\": \"Theo kế hoạch, tàu sẽ tiếp tục hành trình đến trụ sở chính của chúng tôi tại Le Havre.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"However, we can easily send it directly on to Bilbao, Spain, for loading.\", \"vi\": \"Tuy nhiên, chúng tôi có thể dễ dàng chuyển hàng trực tiếp đến Bilbao, Tây Ban Nha, để tiến hành xếp hàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Please let me know how you would like to proceed.\", \"vi\": \"Xin vui lòng cho tôi biết quý vị muốn tiến hành như thế nào.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Zacharie Bernard\", \"vi\": \"Zacharie Bernard\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Client Services, Narvalis\", \"vi\": \"Dịch vụ Khách hàng, Narvalis\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}]' WHERE `id` = 'b5b1f24b-ffbf-40d8-9f05-3216a7908ebc';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Report Reviewer\", \"vi\": \"Người thẩm định báo cáo\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Neveck Associates is looking to hire a report reviewer to join our New York regional team.\", \"vi\": \"Công ty Neveck Associates đang tìm kiếm một chuyên viên thẩm định báo cáo để gia nhập đội ngũ khu vực New York của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"This is a work-from-home position that involves collaborating with engineers to review and revise their technical reports.\", \"vi\": \"Đây là vị trí làm việc tại nhà, yêu cầu phối hợp với các kỹ sư để rà soát và chỉnh sửa các báo cáo kỹ thuật của họ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"The regular work hours for this full-time position are Monday through Friday, 9:00 A.M. to 5:00 P.M. Salary is commensurate with experience.\", \"vi\": \"Giờ làm việc thông thường của vị trí toàn thời gian này là từ thứ Hai đến thứ Sáu, từ 9 giờ sáng đến 5 giờ chiều. Mức lương sẽ được xác định dựa trên kinh nghiệm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"The job involves editing engineering reports to ensure they meet quality specifications and comply with industry standards.\", \"vi\": \"Công việc này bao gồm việc biên tập các báo cáo kỹ thuật để đảm bảo chúng đáp ứng các yêu cầu về chất lượng và tuân thủ các tiêu chuẩn ngành.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The report reviewer will also need to track edits and discuss feedback patterns with authors at internal weekly meetings.\", \"vi\": \"Người phản biện báo cáo cũng sẽ cần theo dõi các chỉnh sửa và thảo luận về các xu hướng phản hồi với các tác giả tại các cuộc họp nội bộ hàng tuần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Strong interpersonal skills and the ability to communicate across company departments are essential.\", \"vi\": \"Kỹ năng giao tiếp giữa các cá nhân tốt cùng khả năng liên lạc hiệu quả giữa các phòng ban trong công ty là những yếu tố không thể thiếu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Applicants must have a bachelor’s degree and at least two years of work experience in a relevant area.\", \"vi\": \"Ứng viên phải có bằng cử nhân và ít nhất hai năm kinh nghiệm làm việc trong lĩnh vực liên quan.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Formal training in technical writing would be a plus.\", \"vi\": \"Việc được đào tạo chính quy về viết kỹ thuật sẽ là một lợi thế.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Interested applicants should send a cover letter and résumé to hiringmanager@neveckassociates.com.\", \"vi\": \"Các ứng viên quan tâm vui lòng gửi thư xin việc và sơ yếu lý lịch đến địa chỉ hiringmanager@neveckassociates.com.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = 'b6007e8c-a2d3-41a6-9fbf-b37c20d4e9b0';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Sid Shepard\", \"vi\": \"Gửi: Sid Shepard\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Corporate Security\", \"vi\": \"Từ: Bộ phận An ninh Doanh nghiệp\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: July 2\", \"vi\": \"Ngày: 2 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Your ID badge\", \"vi\": \"Chủ đề: Thẻ nhận dạng của quý vị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Shepard:\", \"vi\": \"Kính gửi ông Shepard,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"We received your request this morning for assistance in acquiring a new physical identification badge.\", \"vi\": \"Sáng nay, chúng tôi đã nhận được yêu cầu của quý vị về việc hỗ trợ làm thẻ nhận dạng vật lý mới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"As your current badge was misplaced, it has been deactivated.\", \"vi\": \"Do thẻ hiện tại của quý vị đã bị thất lạc, nên thẻ này đã bị vô hiệu hóa.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"To receive a replacement, visit the corporate security office in Paulsen Hall between 7 a.m. and 5:30 p.m. You will be required to show a form of government-issued identification.\", \"vi\": \"Để nhận thẻ thay thế, quý vị vui lòng đến Văn phòng An ninh Doanh nghiệp tại tòa nhà Paulsen Hall trong khoảng thời gian từ 7 giờ sáng đến 5 giờ 30 chiều. Quý vị sẽ cần xuất trình một loại giấy tờ tùy thân do cơ quan nhà nước cấp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"In the meantime, you can take advantage of a new corporate initiative.\", \"vi\": \"Trong thời gian này, quý vị có thể tận dụng một sáng kiến mới của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"The company app installed on all employees\' mobile devices now includes a digital identification card that can be used to gain entry to the corporate parking garage and campus buildings.\", \"vi\": \"Ứng dụng của công ty được cài đặt trên tất cả các thiết bị di động của nhân viên hiện đã tích hợp thẻ nhận dạng điện tử, có thể được sử dụng để vào bãi đỗ xe của công ty và các tòa nhà trong khuôn viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"To access the digital ID card in the app, look for the “ID Card” tab.\", \"vi\": \"Để truy cập thẻ căn cước điện tử trong ứng dụng, quý vị hãy tìm đến tab “Thẻ căn cước”.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"You can then scan your digital ID to enter all secure areas.\", \"vi\": \"Sau đó, quý vị có thể quét thẻ căn cước điện tử của mình để vào tất cả các khu vực an ninh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"If you have questions or need additional help, please call corporate security at 863-555-0171.\", \"vi\": \"Nếu quý vị có thắc mắc hoặc cần hỗ trợ thêm, xin vui lòng liên hệ với bộ phận an ninh công ty theo số 863-555-0171.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Thank you,\", \"vi\": \"Xin cảm ơn,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Hopper Technology Corporate Security\", \"vi\": \"Bộ phận An ninh Doanh nghiệp của Công ty Công nghệ Hopper\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = 'b66a27a5-4d80-48ce-bc3e-1a11668f3c80';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Hye-Jin Lee\", \"vi\": \"Đến: Hye-Jin Lee\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Globiance Technologies\", \"vi\": \"Từ: Công ty Công nghệ Globiance\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Information\", \"vi\": \"Chủ đề: Thông tin\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 5 June\", \"vi\": \"Ngày: 5 tháng 6\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Ms. Lee,\", \"vi\": \"Kính gửi Cô Lee,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Thank you for ______[139] the Sciorama X200 social science database.\", \"vi\": \"Cảm ơn bạn vì đã ______[139] cơ sở dữ liệu khoa học xã hội Sciorama X200.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [139]}, {\"en\": \"Your selection is a preferred one among many researchers.\", \"vi\": \"Lựa chọn của bạn là sự ưu tiên của nhiều nhà nghiên cứu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"We would like to learn about your ______[140] with this database through a five-minute survey.\", \"vi\": \"Chúng tôi muốn tìm hiểu về ______[140] của bạn với cơ sở dữ liệu này thông qua một cuộc khảo sát năm phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [140]}, {\"en\": \"As a token of ______[141] appreciation, you will be automatically entered into a drawing to win a $100 gift card from Globiance Technologies.\", \"vi\": \"Như một món quà thể hiện sự đánh giá ______[141], bạn sẽ tự động được tham gia quay số trúng thưởng thẻ quà tặng trị giá 100 đô la từ Globiance Technologies.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [141]}, {\"en\": \"All of your responses will be kept confidential.\", \"vi\": \"Tất cả các câu trả lời của bạn sẽ được giữ bí mật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"______[142].\", \"vi\": \"______[142].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [142]}, {\"en\": \"The questionnaire is available at www.gt.org/scioramasurvey.\", \"vi\": \"Bảng câu hỏi có sẵn tại www.gt.org/scioramasurvey.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Thanks in advance for your feedback.\", \"vi\": \"Cảm ơn trước về những phản hồi của bạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"The Survey Team at Globiance Technologies\", \"vi\": \"Nhóm khảo sát tại Globiance Technologies\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}]' WHERE `id` = 'b6960381-0cd6-41f6-bc68-6603d29fc2f2';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"*E-mail*\", \"vi\": \"*Email*\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: eward@cornerbookshop.com\", \"vi\": \"Nguồn: eward@cornerbookshop.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To: jberte@bertebakery.com\", \"vi\": \"Gửi tới: jberte@bertebakery.com\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Your sign\", \"vi\": \"Chủ đề: Dấu hiệu của quý vị\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Date: July 30\", \"vi\": \"Ngày: 30 tháng 7\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Hi Jacques,\", \"vi\": \"Xin chào Jacques,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The new sign outside your bakery looks great.\", \"vi\": \"Bảng hiệu mới bên ngoài tiệm bánh của quý vị trông thật đẹp.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I love the natural look of the wood, and the gold lettering is beautiful.\", \"vi\": \"Tôi rất thích vẻ đẹp tự nhiên của gỗ, và những chữ viết màu vàng trông thật tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"The new sign, combined with the freshly painted storefront and new shutters, really makes Berte\'s Bakery stand out.\", \"vi\": \"Bảng hiệu mới, kết hợp với mặt tiền cửa hàng vừa được sơn lại và những tấm cửa chớp mới, thực sự khiến tiệm bánh Berte\'s Bakery trở nên nổi bật.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"I also plan to replace the sign above my shop door with a wooden sign.\", \"vi\": \"Tôi cũng dự định thay thế tấm biển treo trên cửa tiệm của mình bằng một tấm biển gỗ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Could you tell me where you had yours made?\", \"vi\": \"Xin hỏi quý vị có thể cho tôi biết quý vị đã đặt làm chiếc của mình ở đâu không?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I was considering using Studio 9, which was recommended to me by Devon at Q Apparel, but Studio 9\'s signs definitely have a more modern design.\", \"vi\": \"Tôi đang cân nhắc sử dụng Studio 9 – công ty mà Devon tại Q Apparel đã giới thiệu cho tôi – nhưng các biển hiệu của Studio 9 rõ ràng có thiết kế hiện đại hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"The rustic, vintage look of your sign would fit better with the aesthetics here at Corner Book Shop.\", \"vi\": \"Vẻ ngoài mộc mạc, mang phong cách cổ điển của tấm biển này sẽ phù hợp hơn với phong cách thẩm mỹ tại Corner Book Shop.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Thanks.\", \"vi\": \"Cảm ơn.\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Elias Ward\", \"vi\": \"Elias Ward\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Owner, Corner Book Shop\", \"vi\": \"Chủ cửa hàng, Corner Book Shop\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"E-Mail Message\", \"vi\": \"Thông điệp email\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"From: jberte@bertebakery.com\", \"vi\": \"Nguồn: jberte@bertebakery.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"To: eward@cornerbookshop.com\", \"vi\": \"Gửi tới: eward@cornerbookshop.com\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Subject: RE: Your Sign\", \"vi\": \"Chủ đề: TRẢ LỜI: Biển hiệu của quý vị\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"Date: July 31\", \"vi\": \"Ngày: 31 tháng 7\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Hi Elias,\", \"vi\": \"Xin chào Elias,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"Thanks for your comments on our sign.\", \"vi\": \"Xin cảm ơn quý vị đã đóng góp ý kiến về bảng hiệu của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"We used Hedgerow Graphics.\", \"vi\": \"Chúng tôi đã sử dụng Hedgerow Graphics.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"We also looked at Studio 9 because all of their products were much less expensive than anything Hedgerow offers.\", \"vi\": \"Chúng tôi cũng đã xem xét Studio 9 vì tất cả các sản phẩm của họ đều có giá rẻ hơn rất nhiều so với bất kỳ sản phẩm nào mà Hedgerow cung cấp.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"And they do offer wooden signs in various styles, some of which we liked.\", \"vi\": \"Và họ thực sự có bán các tấm biển bằng gỗ với nhiều kiểu dáng khác nhau, trong đó có một số mẫu mà chúng tôi rất ưng ý.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"But we ended up choosing Hedgerow because of its longer warranty period.\", \"vi\": \"Tuy nhiên, cuối cùng chúng tôi đã quyết định chọn Hedgerow vì thời hạn bảo hành của sản phẩm này dài hơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Although the wood used for any outdoor sign is treated with a protective, weather-resistant coating, we wanted to have that extra protection Hedgerow provides with its warranty.\", \"vi\": \"Mặc dù gỗ dùng để làm bất kỳ bảng hiệu ngoài trời nào đều đã được xử lý bằng một lớp phủ bảo vệ chống chịu thời tiết, chúng tôi vẫn mong muốn có thêm sự bảo vệ mà Hedgerow mang lại thông qua chính sách bảo hành của họ.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Good luck!\", \"vi\": \"Chúc may mắn!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"Jacques Berte\", \"vi\": \"Jacques Berte\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Studio 9\", \"vi\": \"Phòng 9\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Order Form\", \"vi\": \"Mẫu đơn đặt hàng\", \"type\": \"title\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"Customer: Elias Ward, Corner Book Shop, 8 Main St., Haywood Village\", \"vi\": \"Khách hàng: Elias Ward, Cửa hàng Sách Corner, số 8 đường Main, Làng Haywood\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"Order Date: August 1\", \"vi\": \"Ngày đặt hàng: 1 tháng 8\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Description of order:\", \"vi\": \"Mô tả đơn hàng:\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"One exterior sign.\", \"vi\": \"Một biển hiệu bên ngoài.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Oak wood treated with Everlast Coating.\", \"vi\": \"Gỗ sồi được xử lý bằng lớp phủ Everlast.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}, {\"en\": \"Mariner blue wood stain, gold lettering (text to read: Corner Book Shop).\", \"vi\": \"Sơn gỗ màu xanh Mariner, chữ màu vàng (nội dung ghi: Corner Book Shop).\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 38, \"question_numbers\": []}, {\"en\": \"152 centimeters wide by 45 centimeters high.\", \"vi\": \"Rộng 152 centimet, cao 45 centimet.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 39, \"question_numbers\": []}, {\"en\": \"Changes to the order must be made by 5:00 P.M. on August 10.\", \"vi\": \"Mọi thay đổi đối với đơn đặt hàng phải được thực hiện trước 17 giờ ngày 10 tháng 8.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 40, \"question_numbers\": []}, {\"en\": \"Price: $495 (Paid in full, August 5)\", \"vi\": \"Giá: 495 đô la (Đã thanh toán đầy đủ vào ngày 5 tháng 8)\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 41, \"question_numbers\": []}, {\"en\": \"Warranty: 1 year\", \"vi\": \"Bảo hành: 1 năm\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 42, \"question_numbers\": []}, {\"en\": \"Expected delivery: August 20\", \"vi\": \"Dự kiến giao hàng: ngày 20 tháng 8\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 43, \"question_numbers\": []}]' WHERE `id` = 'b6b595c4-f3e9-450c-9bfa-f797a2d81dd6';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"BERLIN (16 March)—Harbinger Studios has held HarCon, a convention centered on its online games, each November in Berlin for the past 16 years.\", \"vi\": \"BERLIN (16 tháng 3)—Harbinger Studios đã tổ chức HarCon, một hội nghị tập trung vào các trò chơi trực tuyến của hãng, vào tháng 1 hàng năm tại Berlin trong 16 năm qua.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"______[143] the event\'s continued popularity, the company has canceled this year\'s HarCon in favor of several smaller events in various cities.\", \"vi\": \"______[143] sự nổi tiếng tiếp tục của sự kiện, công ty đã hủy bỏ HarCon năm nay để đổi lấy một số sự kiện quy mô nhỏ hơn ở nhiều thành phố khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [143]}, {\"en\": \"A post on Harbinger\'s Web site explains that this format is better ______[144] to this momentous year for the company.\", \"vi\": \"Một bài đăng trên trang web của Harbinger giải thích rằng định dạng này phù hợp hơn ______[144] với năm quan trọng này của công ty.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [144]}, {\"en\": \"Two of its game franchises will mark major anniversaries of their initial releases, while a third is launching a widely anticipated expansion pack.\", \"vi\": \"Hai trong số các thương hiệu trò chơi của hãng sẽ đánh dấu các cột mốc kỷ niệm lớn kể từ khi phát hành ban đầu, trong khi trò chơi thứ ba đang ra mắt một gói mở rộng được mong đợi rộng rãi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"______[145].\", \"vi\": \"______[145].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [145]}, {\"en\": \"However, the post also emphasizes that HarCon will return next year, reassuring readers that \\\"Harbinger is well aware of how much this ______[146] means to our fans.\\\"\", \"vi\": \"Tuy nhiên, bài đăng cũng nhấn mạnh rằng HarCon sẽ trở lại vào năm tới, trấn an độc giả rằng \\\"Harbinger hoàn toàn nhận thức được ______[146] này có ý nghĩa như thế nào đối với người hâm mộ của chúng tôi.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [146]}]' WHERE `id` = 'b71586e9-d92f-462a-9876-80e3d52b195b';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Francis Chang [4:32 P.M.]\", \"vi\": \"Francis Chang [16 giờ 32 phút]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Hi, Connie.\", \"vi\": \"Xin chào, Connie.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"I\'m putting together the schedule for the summer.\", \"vi\": \"Tôi đang lên lịch trình cho mùa hè.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Will you still be able to teach the Friday afternoon workshops twice a month?\", \"vi\": \"Vậy quý vị vẫn có thể tiếp tục giảng dạy các buổi hội thảo vào chiều thứ Sáu hai lần mỗi tháng được chứ?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"We could take turns, and I would take the other two Fridays.\", \"vi\": \"Chúng ta có thể thay phiên nhau, và tôi sẽ đảm nhận hai ngày thứ Sáu còn lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Connie Kehoe [4:39 P.M.]\", \"vi\": \"Connie Kehoe [4 giờ 39 phút chiều]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Thanks for getting in touch, Francis.\", \"vi\": \"Cảm ơn anh Francis đã liên hệ với chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I\'d still like to be involved, but I\'ll be busier this summer.\", \"vi\": \"Tôi vẫn mong được tham gia, nhưng mùa hè này tôi sẽ bận rộn hơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"I\'m coordinating a volleyball league.\", \"vi\": \"Tôi đang phụ trách tổ chức một giải đấu bóng chuyền.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Francis Chang [4:40 P.M.]\", \"vi\": \"Francis Chang [4 giờ 40 phút chiều]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Well, OK.\", \"vi\": \"Vâng, được rồi.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I guess I could cover the workshops three Fridays a month.\", \"vi\": \"Tôi nghĩ mình có thể đảm nhận việc tổ chức các buổi hội thảo vào ba ngày thứ Sáu mỗi tháng.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Connie Kehoe [4:42 P.M.]\", \"vi\": \"Connie Kehoe [16 giờ 42 phút]\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"That would be perfect.\", \"vi\": \"Điều đó sẽ thật hoàn hảo.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"That will give me enough time for my other obligation.\", \"vi\": \"Điều đó sẽ giúp tôi có đủ thời gian để hoàn thành nghĩa vụ khác của mình.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Francis Chang [4:43 P.M.]\", \"vi\": \"Francis Chang [4 giờ 43 phút chiều]\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"The other thing is, this summer we want to focus on painting with watercolors, rather than basic drawing.\", \"vi\": \"Một điều nữa là, mùa hè này chúng tôi muốn tập trung vào vẽ tranh màu nước, thay vì vẽ cơ bản.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Connie Kehoe [4:44 P.M.]\", \"vi\": \"Connie Kehoe [4 giờ 44 phút chiều]\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I\'ll look over some old lesson plans, but that should be fine.\", \"vi\": \"Tôi sẽ xem lại một số giáo án cũ, nhưng chắc là sẽ ổn thôi.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Also, let\'s get together soon to work on a budget for the class materials.\", \"vi\": \"Ngoài ra, chúng ta hãy sớm gặp nhau để cùng lập kế hoạch ngân sách cho các tài liệu giảng dạy.\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 20, \"question_numbers\": []}]' WHERE `id` = 'b72d7abb-2c6d-47d8-abd1-1f85c526ba15';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Pierre Gitane\", \"vi\": \"Pierre Gitane\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"26 Bent Tree Lane\", \"vi\": \"26 Bent Tree Lane\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Charlotte, NC 28804\", \"vi\": \"Charlotte, Bắc Carolina 28804\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"April 15\", \"vi\": \"Ngày 15 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear Mr. Gitane,\", \"vi\": \"Kính gửi ông Gitane,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This letter is to inform you that you are due for your semiannual dental care visit.\", \"vi\": \"Thư này nhằm thông báo cho quý vị biết rằng đã đến thời gian quý vị cần đến khám răng định kỳ sáu tháng một lần.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Go to our Web site and fill out a form to request an appointment.\", \"vi\": \"Vui lòng truy cập trang web của chúng tôi và điền vào mẫu đơn để đặt lịch hẹn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Or if you prefer, call us at (704) 555-0138 to reach one of our receptionists.\", \"vi\": \"Hoặc nếu quý vị muốn, xin vui lòng gọi cho chúng tôi theo số (704) 555-0138 để liên hệ với một trong các nhân viên lễ tân của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"We are happy to announce that we now offer teeth whitening and invisible braces to improve your smile.\", \"vi\": \"Chúng tôi vui mừng thông báo rằng hiện nay chúng tôi đã cung cấp dịch vụ tẩy trắng răng và niềng răng trong suốt nhằm giúp quý vị có nụ cười rạng rỡ hơn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Please let us know if you are interested in one or both of these services.\", \"vi\": \"Xin vui lòng cho chúng tôi biết nếu quý vị quan tâm đến một trong hai dịch vụ này hoặc cả hai.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We look forward to hearing from you soon.\", \"vi\": \"Chúng tôi rất mong sớm nhận được phản hồi từ quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"All best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Sarah Hamadi\", \"vi\": \"Sarah Hamadi\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Office manager, Red Street Dental Care\", \"vi\": \"Quản lý văn phòng, Phòng khám Nha khoa Red Street\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}]' WHERE `id` = 'b73cac4b-2700-4f01-be24-9f7b0d60be26';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All employees <staff@TFF.com>\", \"vi\": \"Đến: Tất cả nhân viên <staff@TFF.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Walter C. Handy <wchandy@TFF.com>\", \"vi\": \"Từ: Walter C. Handy <wchandy@TFF.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Sales Incentive Program\", \"vi\": \"Chủ đề: Chương trình ưu đãi doanh số\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: 15 November\", \"vi\": \"Ngày: 15 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Dear TFF Sales Team,\", \"vi\": \"Kính gửi Đội ngũ Kinh doanh TFF,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am writing to introduce you to a new, double-incentive program for the fourth quarter of this year!\", \"vi\": \"Tôi viết thư này để giới thiệu với các bạn một chương trình ưu đãi kép hoàn toàn mới cho quý thứ tư của năm nay!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"In addition to our standard cash bonus plan, sales associates will now have the opportunity ______[131] tickets to concerts, sporting events, and theater performances.\", \"vi\": \"Ngoài kế hoạch thưởng tiền mặt tiêu chuẩn của chúng tôi, các nhân viên kinh doanh giờ đây sẽ có cơ hội ______[131] vé tham dự các buổi hòa nhạc, sự kiện thể thao và buổi biểu diễn sân khấu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [131]}, {\"en\": \"This extra incentive is designed to help make this our greatest sales year ever.\", \"vi\": \"Khoản ưu đãi bổ sung này được thiết kế nhằm giúp năm nay trở thành năm có doanh số bán hàng lớn nhất từ trước đến nay của chúng ta.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[132].\", \"vi\": \"______[132].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [132]}, {\"en\": \"More ______[133] will be provided in the next few days.\", \"vi\": \"Thêm ______[133] sẽ được cung cấp trong vài ngày tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": [133]}, {\"en\": \"______[134], if you have any questions about this program, contact the Human Resources Department.\", \"vi\": \"______[134], nếu bạn có bất kỳ câu hỏi nào về chương trình này, hãy liên hệ với Phòng Nhân sự.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": [134]}, {\"en\": \"To our continued success,\", \"vi\": \"Chúc chúng ta tiếp tục thành công,\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Walter C. Handy, CEO\", \"vi\": \"Walter C. Handy, Giám đốc điều hành\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = 'b7713a5b-085f-4de8-be3b-d1c7ae678d3c';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"TOFTLUND (10 June)—Row after row of electric cars in local parking areas seem to indicate that the city of Toftlund has begun to give up on gasoline-fueled cars.\", \"vi\": \"TOFTLUND (Ngày 10 tháng 6)—Hết hàng xe điện này đến hàng xe điện khác tại các khu vực đậu xe địa phương dường như cho thấy thành phố Toftlund đã bắt đầu từ bỏ xe chạy bằng xăng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"In fact, 20 percent of the cars on Toftlund city streets are electric, but this number is changing at a ______[143] pace.\", \"vi\": \"Trên thực tế, 20 phần trăm số ô tô trên đường phố Toftlund là xe điện, nhưng con số này đang thay đổi với một tốc độ ______[143].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": [143]}, {\"en\": \"To some extent, this is due to the city\'s generous tax ______[144] offered to electric car drivers.\", \"vi\": \"Ở một mức độ nào đó, điều này là do các chính sách ______[144] thuế hào phóng của thành phố dành cho tài xế xe điện.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [144]}, {\"en\": \"According to Anne Rasmussen, president of Toftlund Green Business, more attractive designs and longer-lasting batteries have ______[145] made a difference.\", \"vi\": \"Theo Anne Rasmussen, chủ tịch của Toftlund Green Business, các thiết kế bắt mắt hơn và pin có tuổi thọ cao hơn đã ______[145] tạo ra sự khác biệt.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [145]}, {\"en\": \"Ms. Rasmussen predicts the number of electric cars in Toftlund will more than double in the coming years.\", \"vi\": \"Bà Rasmussen dự đoán số lượng xe điện ở Toftlund sẽ tăng hơn gấp đôi trong những năm tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"______[146].\", \"vi\": \"______[146].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [146]}]' WHERE `id` = 'b7b21d62-5b73-42f6-945e-b52538498f6d';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Dr. Jatin Sachdeva Memorial Lecture\", \"vi\": \"Buổi thuyết trình tưởng niệm Tiến sĩ Jatin Sachdeva\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Dr. Seema Razdan\", \"vi\": \"Tiến sĩ Seema Razdan\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"You are cordially invited to the\", \"vi\": \"Kính mời quý vị tham dự sự kiện\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"delivered by\", \"vi\": \"được trình bày bởi\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Director, National Centre for Research and author of\", \"vi\": \"Giám đốc Trung tâm Nghiên cứu Quốc gia và là tác giả của\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Improving Your Bedside Manner: Essential Skills in Health Care\", \"vi\": \"Nâng cao kỹ năng giao tiếp với bệnh nhân: Những kỹ năng thiết yếu trong lĩnh vực chăm sóc sức khỏe\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Topic: Patient Care\", \"vi\": \"Chủ đề: Chăm sóc bệnh nhân\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Date: 15 May, 9:30–10:30 A.M.\", \"vi\": \"Ngày: 15 tháng 5, 9 giờ 30 – 10 giờ 30 sáng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Venue: Nadkarni Auditorium\", \"vi\": \"Địa điểm: Hội trường Nadkarni\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"This lecture is open only to Jalandhar Hospital medical personnel who interact daily with patients.\", \"vi\": \"Buổi giảng này chỉ dành riêng cho các nhân viên y tế của Bệnh viện Jalandhar, những người hàng ngày tiếp xúc trực tiếp với bệnh nhân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Seating is limited.\", \"vi\": \"Số lượng chỗ ngồi có hạn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"E-mail Mr. Arnav Gopal to hold your spot.\", \"vi\": \"Vui lòng gửi email cho ông Arnav Gopal để giữ chỗ cho quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}]' WHERE `id` = 'b813587f-949a-48a0-8da0-3352f1dc93ff';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"3 November\", \"vi\": \"Ngày 3 tháng 11\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Rhys Tomasen\", \"vi\": \"Rhys Tomasen\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Hiring Manager\", \"vi\": \"Trưởng phòng Tuyển dụng\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Slepoy Marketing Ltd.\", \"vi\": \"Công ty TNHH Slepoy Marketing\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Level 7, 500 Exeton Street\", \"vi\": \"Tầng 7, số 500 đường Exeton\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Sydney, NSW 2000\", \"vi\": \"Sydney, NSW 2000\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Dear Mr. Tomasen,\", \"vi\": \"Kính gửi ông Tomasen,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"I would like to thank you again for the opportunity to interview for the position of staff photographer with Slepoy Marketing.\", \"vi\": \"Tôi xin chân thành cảm ơn quý vị một lần nữa vì đã tạo cơ hội cho tôi tham gia buổi phỏng vấn cho vị trí nhiếp ảnh gia chính thức tại Slepoy Marketing.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Although I am disappointed that I was not chosen, I enjoyed meeting you and your staff.\", \"vi\": \"Mặc dù tôi cảm thấy thất vọng vì không được lựa chọn, nhưng tôi rất vui khi được gặp quý vị và các nhân viên của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Your decision to go with another candidate does not diminish my belief that your company is a first-rate marketing firm, which rightfully deserves the many awards it has won.\", \"vi\": \"Quyết định của quý công ty trong việc lựa chọn một ứng viên khác không làm suy giảm niềm tin của tôi rằng quý công ty là một công ty tiếp thị hàng đầu, hoàn toàn xứng đáng với những giải thưởng mà quý công ty đã giành được.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Incidentally, during our meeting you happened to mention your upcoming mountain-themed campaign as well as the fact that your company often hires freelance photographers.\", \"vi\": \"Nhân tiện, trong cuộc họp vừa qua, quý vị đã tình cờ đề cập đến chiến dịch quảng cáo sắp tới với chủ đề núi non, cũng như việc công ty quý vị thường xuyên thuê các nhiếp ảnh gia tự do.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"I will be traveling in Asia for the next three months, and plan to shoot landscape photographs that might be appropriate for this campaign.\", \"vi\": \"Trong ba tháng tới, tôi sẽ có chuyến du lịch khắp châu Á và dự định sẽ chụp những bức ảnh phong cảnh có thể phù hợp với chiến dịch này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Should you be interested, I would be happy to send you some of those pictures.\", \"vi\": \"Nếu quý vị quan tâm, tôi rất sẵn lòng gửi cho quý vị một số bức ảnh đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Thanks again for meeting with me.\", \"vi\": \"Một lần nữa, xin chân thành cảm ơn quý vị đã dành thời gian gặp gỡ tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"I hope to have another opportunity to speak with you at this year\'s Graphic Arts Conference in Brisbane.\", \"vi\": \"Tôi hy vọng sẽ có cơ hội được trò chuyện với quý vị một lần nữa tại Hội nghị Nghệ thuật Đồ họa năm nay diễn ra tại Brisbane.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Sincerely,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Ye-Eun Whang\", \"vi\": \"Ye-Eun Whang\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Ye-Eun Whang\", \"vi\": \"Ye-Eun Whang\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 18, \"question_numbers\": []}]' WHERE `id` = 'b8ad429e-962e-4fde-baa8-ae8f3dc32486';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: Nadja Burton <manager_publicaffairs@jaspertonintlairport.com>\", \"vi\": \"Gửi tới: Nadja Burton <manager_publicaffairs@jaspertonintlairport.com>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Ron Hylton <rhylton@cityofjasperton.gov>\", \"vi\": \"Từ: Ron Hylton <rhylton@cityofjasperton.gov>\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: October 3\", \"vi\": \"Ngày: 3 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Ribbon-cutting ceremony\", \"vi\": \"Chủ đề: Lễ cắt băng khánh thành\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hello, Ms. Burton,\", \"vi\": \"Xin chào, bà Burton,\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"I am sorry to tell you that, because of an unexpected scheduling conflict, Mayor Blau must cancel her appearance at next week\'s event.\", \"vi\": \"Tôi rất tiếc phải thông báo với quý vị rằng, do một sự trùng lặp lịch trình bất ngờ, Thị trưởng Blau buộc phải hủy bỏ việc tham dự sự kiện vào tuần tới.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"The mayor is proud to have played a part in negotiating a noise-reduction agreement between Jasperton International Airport and nearby homeowners, and she regrets that she will not be there to celebrate.\", \"vi\": \"Bà Thị trưởng rất tự hào vì đã góp phần vào việc đàm phán thỏa thuận giảm tiếng ồn giữa Sân bay Quốc tế Jasperton và các hộ dân lân cận, đồng thời bà cũng lấy làm tiếc vì không thể có mặt tại đó để tham dự lễ kỷ niệm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The city council chairperson will take her place.\", \"vi\": \"Chủ tịch Hội đồng thành phố sẽ đảm nhận chức vụ này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"By the way, we heard the good news about Arovion Air—congratulations!\", \"vi\": \"Nhân tiện, chúng tôi đã nghe tin vui về Arovion Air — xin gửi lời chúc mừng!\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"A lot of people traveling to East Asia on business will be happy to take advantage of this.\", \"vi\": \"Rất nhiều người đi công tác đến Đông Á sẽ rất vui khi được tận dụng cơ hội này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"Regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Ron Hylton, Communications Director\", \"vi\": \"Ông Ron Hylton, Giám đốc Truyền thông\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Office of the Mayor\", \"vi\": \"Văn phòng Thị trưởng\", \"type\": \"sign_off\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Airport and City Leaders to Celebrate Project Completion\", \"vi\": \"Lãnh đạo sân bay và thành phố sẽ tổ chức lễ kỷ niệm hoàn thành dự án\", \"type\": \"title\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"JASPERTON (October 5)—A ribbon-cutting ceremony will be held at Jasperton International Airport on October 12.\", \"vi\": \"JASPERTON (ngày 5 tháng 10) — Lễ cắt băng khánh thành sẽ được tổ chức tại Sân bay Quốc tế Jasperton vào ngày 12 tháng 10.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"The event will mark the completion of the extension of airport runway 15.\", \"vi\": \"Sự kiện này sẽ đánh dấu việc hoàn thành dự án mở rộng đường băng số 15 của sân bay.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"City council chairperson Rosalie Colman and airport director Norris Yuan will gather with other invited guests to cut the ribbon at 9:30 A.M.\", \"vi\": \"Chủ tịch Hội đồng thành phố Rosalie Colman và Giám đốc sân bay Norris Yuan sẽ cùng các vị khách mời khác tham dự lễ cắt băng khánh thành vào lúc 9 giờ 30 phút sáng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"The runway extension project, which began five months ago, was not without controversy.\", \"vi\": \"Dự án mở rộng đường băng, được khởi công cách đây năm tháng, đã vấp phải không ít tranh cãi.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Complaints by groups of homeowners concerned about noise pollution eventually led to the construction of concrete noise barriers that were not a part of the initial project plan.\", \"vi\": \"Những khiếu nại từ các nhóm chủ nhà lo ngại về ô nhiễm tiếng ồn cuối cùng đã dẫn đến việc xây dựng các hàng rào chống ồn bằng bê tông, vốn không nằm trong kế hoạch dự án ban đầu.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"The extension of runway 15 ushers in a new era for travel in the region.\", \"vi\": \"Việc mở rộng đường băng số 15 đã mở ra một kỷ nguyên mới cho ngành du lịch trong khu vực.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"The runway is now long enough to accommodate the wide-body aircraft that can travel lengthy international routes.\", \"vi\": \"Hiện nay, đường băng đã đủ dài để phục vụ các loại máy bay thân rộng có khả năng thực hiện các chặng bay quốc tế dài.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"At least one long-haul carrier is already preparing to fly nonstop from Jasperton to East Asia.\", \"vi\": \"Ít nhất một hãng hàng không đường dài hiện đã đang chuẩn bị khai thác các chuyến bay thẳng từ Jasperton đến Đông Á.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}]' WHERE `id` = 'b95694b1-0ed5-4fb4-a550-f09582691652';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Factory Staff: Break Times\", \"vi\": \"Nhân viên nhà máy: Thời gian nghỉ giải lao\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Full-time factory staff are entitled to three breaks daily and are encouraged to use them.\", \"vi\": \"Nhân viên nhà máy làm việc toàn thời gian được hưởng ba lần nghỉ giải lao mỗi ngày và được khuyến khích tận dụng các khoảng thời gian này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Please attend to any personal business during these break times.\", \"vi\": \"Kính mong quý vị dành thời gian giải quyết các công việc cá nhân trong các khoảng thời gian nghỉ này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"— [1] —.\", \"vi\": \"— [1] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Those who work a full eight-hour shift may take a fifteen-minute break in the morning and another fifteen-minute break in the afternoon.\", \"vi\": \"Những người làm ca làm việc đầy đủ 8 giờ có thể nghỉ giải lao 15 phút vào buổi sáng và 15 phút nữa vào buổi chiều.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Lunch breaks are 30 minutes long.\", \"vi\": \"Giờ nghỉ trưa kéo dài 30 phút.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"There is a break area on the ground level that includes a kitchen and a staff lounge.\", \"vi\": \"Tại tầng trệt có một khu vực nghỉ ngơi, bao gồm một nhà bếp và phòng nghỉ dành cho nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"— [2] —.\", \"vi\": \"— [2] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Please note that the refrigerator is cleaned out every Friday evening, so be sure to take home any leftover food that you want to save.\", \"vi\": \"Xin lưu ý rằng tủ lạnh sẽ được dọn dẹp vào mỗi tối thứ Sáu, vì vậy xin quý vị hãy nhớ mang về nhà bất kỳ thức ăn thừa nào mà quý vị muốn giữ lại.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"There are lockers in the staff lounge for storing personal items.\", \"vi\": \"Trong phòng nghỉ dành cho nhân viên có các tủ khóa để cất giữ đồ dùng cá nhân.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"— [3] —.\", \"vi\": \"— [3] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Employees are welcome to use the restrooms adjacent to the staff lounge.\", \"vi\": \"Các nhân viên có thể sử dụng nhà vệ sinh nằm ngay cạnh phòng nghỉ dành cho nhân viên.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"— [4] —.\", \"vi\": \"— [4] —.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 13, \"question_numbers\": []}]' WHERE `id` = 'b990200b-387b-414e-b4e6-185eb67b994f';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"From: Hong Kong Princess Center Administration\", \"vi\": \"Từ: Ban quản lý Trung tâm Hong Kong Princess\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"To: All Princess Center residents\", \"vi\": \"Đến: Tất cả cư dân Trung tâm Princess\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Date: 17 October\", \"vi\": \"Ngày: 17 tháng 10\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Subject: Higwam workers to maintain C-level elevators\", \"vi\": \"Chủ đề: Nhân viên Higwam bảo trì thang máy khu vực C\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"______[139] the past week you may have experienced increased wait times for our C-level elevators, which service floors 25 through 36.\", \"vi\": \"______[139] tuần qua, quý vị có thể đã gặp phải tình trạng thời gian chờ đợi thang máy khu vực C lâu hơn, phục vụ từ tầng 25 đến tầng 36.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": [139]}, {\"en\": \"We have contacted Higwam, our elevator maintenance contractor, who ______[140] repairs in the elevator shafts.\", \"vi\": \"Chúng tôi đã liên hệ với Higwam, nhà thầu bảo trì thang máy của chúng tôi, đơn vị ______[140] việc sửa chữa trong các giếng thang máy.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": [140]}, {\"en\": \"This is to alert all residents that beginning tomorrow and through the end of the week, you are likely to see Higwam technicians working in the lobby.\", \"vi\": \"Thông báo này nhằm nhắc nhở tất cả cư dân rằng bắt đầu từ ngày mai và kéo dài đến hết tuần, quý vị có thể sẽ thấy các kỹ thuật viên của Higwam làm việc tại sảnh.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"They are planning to work on one unit at a time in order to keep the others operational while repairs are in progress, so for the next few ______[141], there may continue to be prolonged wait times.\", \"vi\": \"Họ có kế hoạch làm việc trên từng thang một để giữ cho các thang khác hoạt động trong khi quá trình sửa chữa đang diễn ra, vì vậy trong vài ______[141] tới, tình trạng thời gian chờ đợi kéo dài có thể vẫn tiếp diễn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": [141]}, {\"en\": \"______[142].\", \"vi\": \"______[142].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [142]}, {\"en\": \"For any questions, please contact our office.\", \"vi\": \"Nếu có bất kỳ thắc mắc nào, vui lòng liên hệ với văn phòng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"We apologize for the inconvenience and appreciate your patience.\", \"vi\": \"Chúng tôi thành thật xin lỗi vì sự bất tiện này và rất mong nhận được sự kiên nhẫn của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}]' WHERE `id` = 'b9a91b30-f2de-4aea-9d43-f9543ea49823';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Rudra Agarwal [10:57 A.M.]\", \"vi\": \"Rudra Agarwal [10 giờ 57 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Marie, how\'s it going at Chicmode this morning?\", \"vi\": \"Marie ạ, sáng nay công việc tại Chicmode thế nào rồi?\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Marie Everett [11:03 A.M.]\", \"vi\": \"Marie Everett [11 giờ 03 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Very well!\", \"vi\": \"Rất tốt!\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"I\'ve just finished looking over drawings of some potential pieces for the line, and their design team\'s done a good job of capturing the essence of the Giga Cola brand.\", \"vi\": \"Tôi vừa xem xong bản vẽ của một số mẫu sản phẩm tiềm năng cho dòng sản phẩm này, và đội ngũ thiết kế của họ đã làm rất tốt trong việc thể hiện được bản sắc của thương hiệu Giga Cola.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Rudra Agarwal [11:04 A.M.]\", \"vi\": \"Rudra Agarwal [11 giờ 04 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Really?\", \"vi\": \"Thật vậy sao?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"How so?\", \"vi\": \"Tại sao lại như vậy?\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"Marie Everett [11:05 A.M.]\", \"vi\": \"Marie Everett [11 giờ 05 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 3, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Well, my favorite piece is a sweatshirt that displays our logo on a background of squares in different sizes and colors.\", \"vi\": \"À, món đồ tôi ưa thích nhất là một chiếc áo nỉ có in logo của chúng tôi trên nền là những ô vuông với nhiều kích cỡ và màu sắc khác nhau.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"It\'s very playful.\", \"vi\": \"Nó rất vui nhộn.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"And I think it will appeal to a lot of people, not just our customers.\", \"vi\": \"Và tôi tin rằng sản phẩm này sẽ thu hút được rất nhiều người, không chỉ riêng khách hàng của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 3, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Rudra Agarwal [11:07 A.M.]\", \"vi\": \"Rudra Agarwal [11 giờ 07 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 4, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"That\'s great.\", \"vi\": \"Thật tuyệt vời.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Actually, our social media team just sent a report on reactions to the announcement of the line, and it\'s very encouraging.\", \"vi\": \"Thực ra, đội ngũ phụ trách mạng xã hội của chúng tôi vừa gửi đến một báo cáo về phản ứng của công chúng đối với thông báo ra mắt dòng sản phẩm này, và kết quả rất đáng khích lệ.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Four out of five comments have been positive.\", \"vi\": \"Bốn trong số năm bình luận là những ý kiến tích cực.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"I\'m feeling really confident about our decision to collaborate with Chicmode.\", \"vi\": \"Tôi cảm thấy vô cùng tự tin về quyết định hợp tác với Chicmode của chúng tôi.\", \"type\": \"paragraph\", \"doc_index\": 4, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Marie Everett [11:08 A.M.]\", \"vi\": \"Marie Everett [11 giờ 08 phút sáng]\", \"type\": \"metadata\", \"doc_index\": 5, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"Yes, it\'s certainly looking good so far!\", \"vi\": \"Vâng, cho đến nay mọi việc quả thực đang diễn ra rất thuận lợi!\", \"type\": \"paragraph\", \"doc_index\": 5, \"sentence_id\": 19, \"question_numbers\": []}]' WHERE `id` = 'b9afae93-63c8-40c4-80a2-51d47b85bf91';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"To: All Branch Managers\", \"vi\": \"Kính gửi: Tất cả các Giám đốc chi nhánh\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"From: Fran Corliss\", \"vi\": \"Từ: Fran Corliss\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Subject: Survey results on mobile banking\", \"vi\": \"Chủ đề: Kết quả khảo sát về dịch vụ ngân hàng di động\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Date: April 7\", \"vi\": \"Ngày: 7 tháng 4\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Hello all,\", \"vi\": \"Xin chào quý vị,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Ogden Bank recently conducted a survey of its customers concerning mobile banking.\", \"vi\": \"Ngân hàng Ogden gần đây đã tiến hành một cuộc khảo sát đối với khách hàng của mình về dịch vụ ngân hàng di động.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"Here are some key takeaways.\", \"vi\": \"Dưới đây là một số điểm chính cần lưu ý.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"Over 95 percent of our customers own a mobile device.\", \"vi\": \"Hơn 95 phần trăm khách hàng của chúng tôi sở hữu một thiết bị di động.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"However, although interest in mobile banking is high, only 39 percent of our customers use our application.\", \"vi\": \"Tuy nhiên, mặc dù sự quan tâm đối với dịch vụ ngân hàng di động rất cao, nhưng chỉ có 39 phần trăm khách hàng của chúng tôi sử dụng ứng dụng này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"Some customers cite security concerns (23 percent), but a majority (78 percent) say that they simply do not think the app works well.\", \"vi\": \"Một số khách hàng nêu lên những lo ngại về vấn đề bảo mật (23%), nhưng phần lớn (78%) cho biết họ chỉ đơn giản là không nghĩ rằng ứng dụng này hoạt động tốt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"A mandatory meeting for all branch managers will be held at our headquarters on April 12 at 4:00 P.M. to brainstorm strategies for responding to this challenge.\", \"vi\": \"Một cuộc họp bắt buộc dành cho tất cả các giám đốc chi nhánh sẽ được tổ chức tại trụ sở chính của chúng tôi vào ngày 12 tháng 4 lúc 4 giờ chiều nhằm cùng nhau thảo luận và đề xuất các chiến lược ứng phó với thách thức này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"Best,\", \"vi\": \"Trân trọng,\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"Fran Corliss\", \"vi\": \"Fran Corliss\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"Director of Mobile Banking, Ogden Bank\", \"vi\": \"Giám đốc Bộ phận Ngân hàng Di động, Ngân hàng Ogden\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Boost for Mobile Banking\", \"vi\": \"Động lực thúc đẩy dịch vụ ngân hàng di động\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"By Edward Panzius\", \"vi\": \"Tác giả: Edward Panzius\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"FLEMINGTON (May 25)—Ogden Bank has rolled out major improvements to its mobile banking application.\", \"vi\": \"FLEMINGTON (ngày 25 tháng 5) — Ngân hàng Ogden đã triển khai những cải tiến đáng kể đối với ứng dụng ngân hàng di động của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"It has expanded the variety of tasks that can be accomplished through the app and made it much easier to use.\", \"vi\": \"Ứng dụng này đã mở rộng phạm vi các tác vụ có thể thực hiện thông qua ứng dụng và giúp việc sử dụng trở nên dễ dàng hơn rất nhiều.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"“Many of our account holders have been frustrated in the past by a clunky, limited app,” said Alys DeFreese, manager of the Flemington branch of Ogden Bank.\", \"vi\": \"“Trong quá khứ, nhiều khách hàng của chúng tôi đã cảm thấy bất tiện vì ứng dụng hoạt động chậm chạp và có nhiều hạn chế,” bà Alys DeFreese, Giám đốc chi nhánh Flemington của Ngân hàng Ogden, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"“They can now do just about any task with the app that they could over the phone or by visiting a branch in person.\", \"vi\": \"“Giờ đây, quý vị có thể thực hiện hầu như bất kỳ thao tác nào thông qua ứng dụng này, giống như khi thực hiện qua điện thoại hoặc khi trực tiếp đến chi nhánh.”\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"This is just another example of how we support our customers in any way we can.”\", \"vi\": \"“Đây chỉ là một ví dụ nữa cho thấy chúng tôi luôn hỗ trợ khách hàng bằng mọi cách có thể.”\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"According to Ms. DeFreese, in the few weeks since the upgrade, 20 percent of account holders have switched to depositing checks and paying bills online.\", \"vi\": \"Theo bà DeFreese, trong vài tuần kể từ khi thực hiện nâng cấp, 20 phần trăm chủ tài khoản đã chuyển sang hình thức gửi séc và thanh toán hóa đơn trực tuyến.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"She anticipates that number will rise as more customers learn about the easy-to-use app.\", \"vi\": \"Bà dự đoán con số này sẽ tăng lên khi ngày càng có nhiều khách hàng biết đến ứng dụng dễ sử dụng này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"“The convenience made a big difference for me,” said account holder Yair Baum.\", \"vi\": \"“Sự tiện lợi này đã mang lại sự khác biệt rất lớn đối với tôi,” ông Yair Baum, chủ tài khoản, cho biết.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"Another customer, Maria Reed, added, “I appreciate the flexibility of being able to do my banking whenever and wherever I want.”\", \"vi\": \"Một khách hàng khác, bà Maria Reed, chia sẻ thêm: “Tôi rất đánh giá cao sự linh hoạt khi có thể thực hiện các giao dịch ngân hàng bất cứ lúc nào và ở bất cứ đâu tôi muốn.”\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}]' WHERE `id` = 'b9b739d0-4fd7-4ded-b4d8-83414cf741b7';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"A Changing of the Guard at Rolidge Motors\", \"vi\": \"Sự thay đổi lãnh đạo tại Rolidge Motors\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"by Nathan Kekana\", \"vi\": \"của Nathan Kekana\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"DURBAN—Rolidge Motors has announced that Cara Walters will be the next CEO of the Durban-based company.\", \"vi\": \"DURBAN — Công ty Rolidge Motors đã thông báo rằng bà Cara Walters sẽ là Giám đốc điều hành (CEO) tiếp theo của công ty có trụ sở tại Durban này.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Ms. Walters succeeds Thomas Hsing, who has served in the role for fifteen years and is retiring.\", \"vi\": \"Bà Walters sẽ kế nhiệm ông Thomas Hsing, người đã đảm nhiệm chức vụ này trong mười lăm năm và sắp nghỉ hưu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Most recently, Ms. Walters was executive vice president for Cermak & Holden Ltd., which she helped to grow into one of the largest electronics firms in South Africa.\", \"vi\": \"Gần đây nhất, bà Walters từng giữ chức Phó Chủ tịch Điều hành tại Công ty Cermak & Holden Ltd., nơi bà đã góp phần đưa công ty này phát triển thành một trong những tập đoàn điện tử lớn nhất tại Nam Phi.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"This marks Ms. Walters\' return to Rolidge Motors, where she began her career after graduating from university.\", \"vi\": \"Điều này đánh dấu sự trở lại của bà Walters tại Rolidge Motors, nơi bà đã khởi đầu sự nghiệp sau khi tốt nghiệp đại học.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"She completed the Rolidge Leadership Programme and stayed for seven years before moving on to Cermak & Holden.\", \"vi\": \"Bà đã hoàn thành Chương trình Lãnh đạo Rolidge và làm việc tại đây trong bảy năm trước khi chuyển sang công ty Cermak & Holden.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"\\\"Ms. Walters has both the leadership experience and inside knowledge of Rolidge Motors to make her tenure here successful,\\\" remarked Mr. Hsing.\", \"vi\": \"\\\"Bà Walters vừa có kinh nghiệm lãnh đạo vừa am hiểu sâu sắc về Rolidge Motors, điều này sẽ giúp bà gặt hái thành công trong thời gian đảm nhiệm chức vụ tại đây,\\\" ông Hsing nhận định.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"\\\"We are excited to have Ms. Walters join us,\\\" added Matilde Bekwa, Rolidge Motors\' chairman of the board.\", \"vi\": \"\\\"Chúng tôi rất vui mừng khi bà Walters gia nhập công ty chúng tôi,\\\" bà Matilde Bekwa, Chủ tịch Hội đồng quản trị của Rolidge Motors, cho biết thêm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"\\\"Her work at Cermak & Holden has been remarkable, and we look forward to benefiting from her visionary leadership.\\\"\", \"vi\": \"\\\"Những đóng góp của bà tại Cermak & Holden thực sự rất đáng khen ngợi, và chúng tôi rất mong được hưởng lợi từ sự lãnh đạo có tầm nhìn xa trông rộng của bà.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}]' WHERE `id` = 'ba47ed93-68a6-443e-a833-9f7597c8a967';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Nylobe, Inc., Announces Newest Development Project\", \"vi\": \"Nylobe, Inc., Công Bố Dự Án Phát Triển Mới Nhất\", \"type\": \"title\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"SEATTLE (May 1)—Researchers at technology firm Nylobe, Inc., are working to develop a sensor capable of detecting corrosion caused by environmental exposure.\", \"vi\": \"SEATTLE (Ngày 1 tháng 5)—Các nhà nghiên cứu tại hãng công nghệ Nylobe, Inc., đang nỗ lực phát triển một loại cảm biến có khả năng phát hiện sự ăn mòn do tác động của môi trường.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"Corrosion is a major contributor to ______[143] losses in the aircraft industry each year.\", \"vi\": \"Sự ăn mòn là một nguyên nhân chính gây ra tổn thất ______[143] trong ngành hàng không mỗi năm.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": [143]}, {\"en\": \"\\\"This will be a major ______[144] for commercial airline fleets,\\\" says Mel Laveau, Nylobe\'s CEO.\", \"vi\": \"\\\"Đây sẽ là một ______[144] lớn cho các đội bay thương mại,\\\" Mel Laveau, Giám đốc điều hành của Nylobe cho biết.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": [144]}, {\"en\": \"\\\"The sensor will decrease both labor and maintenance costs without being too expensive.\\\"\", \"vi\": \"\\\"Cảm biến này sẽ làm giảm cả chi phí nhân công và bảo trì mà không quá đắt đỏ.\\\"\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"According to Ms. Laveau, the sensor will work by detecting corrosion in its early stages, when the problem can be corrected simply by removing the corroded material.\", \"vi\": \"Theo bà Laveau, cảm biến sẽ hoạt động bằng cách phát hiện sự ăn mòn ngay từ giai đoạn đầu, khi mà vấn đề có thể được khắc phục đơn giản bằng cách loại bỏ phần vật liệu bị ăn mòn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"______[145].\", \"vi\": \"______[145].\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": [145]}, {\"en\": \"In the structure of large aircraft, some critical joints can be particularly susceptible to corrosion.\", \"vi\": \"Trong cấu trúc của các máy bay lớn, một số mối nối quan trọng có thể đặc biệt dễ bị ăn mòn.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"______[146], the sensor can be used to inspect these areas and then target the most likely areas of concern.\", \"vi\": \"______[146], cảm biến có thể được sử dụng để kiểm tra các khu vực này và sau đó nhắm vào các vùng đáng lo ngại nhất.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": [146]}]' WHERE `id` = 'ba632d95-53e4-415a-b545-3a31019efa9a';
UPDATE `passages` SET `passage_sentence_pairs` = '[{\"en\": \"Instructions for Requesting Records\", \"vi\": \"Hướng dẫn về việc yêu cầu cung cấp hồ sơ\", \"type\": \"metadata\", \"doc_index\": 0, \"sentence_id\": 1, \"question_numbers\": []}, {\"en\": \"Thank you for your interest in official records and documents maintained by the City of Abilene.\", \"vi\": \"Xin chân thành cảm ơn quý vị đã quan tâm đến các hồ sơ và tài liệu chính thức do Thành phố Abilene quản lý.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 2, \"question_numbers\": []}, {\"en\": \"To file a request for public information, please follow these steps.\", \"vi\": \"Để nộp đơn yêu cầu cung cấp thông tin công khai, xin vui lòng thực hiện theo các bước sau đây.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 3, \"question_numbers\": []}, {\"en\": \"Create an account in the Records Center Web portal.\", \"vi\": \"Vui lòng tạo tài khoản trên cổng thông tin web của Trung tâm Lưu trữ.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 4, \"question_numbers\": []}, {\"en\": \"Currently, all requests must be made through the portal.\", \"vi\": \"Hiện tại, tất cả các yêu cầu đều phải được thực hiện thông qua cổng thông tin.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 5, \"question_numbers\": []}, {\"en\": \"Use the drop-down menu to locate the department from which you are seeking information and submit your request.\", \"vi\": \"Vui lòng sử dụng menu thả xuống để tìm bộ phận mà quý vị muốn tìm hiểu thông tin và gửi yêu cầu của quý vị.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 6, \"question_numbers\": []}, {\"en\": \"You will receive a confirmation e-mail with a reference number.\", \"vi\": \"Quý vị sẽ nhận được một email xác nhận kèm theo số tham chiếu.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 7, \"question_numbers\": []}, {\"en\": \"The department staff will locate the requested records and contact you when they are available.\", \"vi\": \"Nhân viên phòng ban sẽ tìm kiếm các hồ sơ theo yêu cầu và liên hệ với quý vị khi các hồ sơ này đã sẵn sàng.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 8, \"question_numbers\": []}, {\"en\": \"You can have the records delivered to you, or you can pick them up in person.\", \"vi\": \"Quý vị có thể yêu cầu gửi các hồ sơ đến tận nơi, hoặc có thể trực tiếp đến nhận.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 9, \"question_numbers\": []}, {\"en\": \"If you prefer to pick them up in person, you must make an appointment with the department staff.\", \"vi\": \"Nếu quý vị muốn trực tiếp đến nhận, quý vị phải đặt lịch hẹn trước với nhân viên của phòng ban.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 10, \"question_numbers\": []}, {\"en\": \"If there are any fees associated with your request, you will receive an itemized statement detailing the services provided and the charges for those specific services.\", \"vi\": \"Nếu có bất kỳ khoản phí nào liên quan đến yêu cầu của quý vị, quý vị sẽ nhận được một bảng kê chi tiết nêu rõ các dịch vụ đã được cung cấp cùng mức phí áp dụng cho từng dịch vụ cụ thể đó.\", \"type\": \"paragraph\", \"doc_index\": 0, \"sentence_id\": 11, \"question_numbers\": []}, {\"en\": \"E-Mail Message\", \"vi\": \"Thông điệp email\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 12, \"question_numbers\": []}, {\"en\": \"To: Joo-Hee Park <jhpark@coa.net>\", \"vi\": \"Gửi: Joo-Hee Park <jhpark@coa.net>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 13, \"question_numbers\": []}, {\"en\": \"From: Keith Brandenberg <kbrandenberg@mailcurrent.com>\", \"vi\": \"Từ: Keith Brandenberg <kbrandenberg@mailcurrent.com>\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 14, \"question_numbers\": []}, {\"en\": \"Date: May 3\", \"vi\": \"Ngày: 3 tháng 5\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 15, \"question_numbers\": []}, {\"en\": \"Subject: RE: Reference number W2486\", \"vi\": \"Chủ đề: TRẢ LỜI: Số tham chiếu W2486\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 16, \"question_numbers\": []}, {\"en\": \"Dear Ms. Park,\", \"vi\": \"Kính gửi bà Park,\", \"type\": \"metadata\", \"doc_index\": 1, \"sentence_id\": 17, \"question_numbers\": []}, {\"en\": \"Thank you for confirming that my documents are available.\", \"vi\": \"Xin cảm ơn quý vị đã xác nhận rằng các tài liệu của tôi đã sẵn sàng.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 18, \"question_numbers\": []}, {\"en\": \"I would like to pick them up in person as soon as possible.\", \"vi\": \"Tôi mong muốn được trực tiếp đến nhận những món hàng này càng sớm càng tốt.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 19, \"question_numbers\": []}, {\"en\": \"Do you have any appointments available this week?\", \"vi\": \"Tuần này quý vị có lịch hẹn nào trống không?\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 20, \"question_numbers\": []}, {\"en\": \"I have a question about the fee.\", \"vi\": \"Tôi có một câu hỏi liên quan đến khoản phí.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 21, \"question_numbers\": []}, {\"en\": \"Apparently, I am being charged $300 for my documents.\", \"vi\": \"Có vẻ như tôi đang bị tính phí 300 đô la cho các tài liệu của mình.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 22, \"question_numbers\": []}, {\"en\": \"I do not understand why the fee is so high, and there was no explanation included in your e-mail.\", \"vi\": \"Tôi không hiểu tại sao mức phí lại cao như vậy, và trong email của quý vị cũng không có bất kỳ lời giải thích nào về vấn đề này.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 23, \"question_numbers\": []}, {\"en\": \"I have requested records several times in the past in my role with RJ Environmental Engineering and have never paid such a high fee.\", \"vi\": \"Trước đây, trong thời gian đảm nhiệm chức vụ tại Công ty RJ Environmental Engineering, tôi đã nhiều lần yêu cầu cung cấp hồ sơ nhưng chưa bao giờ phải trả một khoản phí cao như vậy.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 24, \"question_numbers\": []}, {\"en\": \"In this case, I am only requesting two maps of the city\'s underground pipelines, which will inform our firm\'s current work advising the city on wastewater management.\", \"vi\": \"Trong trường hợp này, tôi chỉ xin hai bản đồ hệ thống đường ống ngầm của thành phố, nhằm làm cơ sở cho công việc hiện tại của công ty chúng tôi trong việc tư vấn cho thành phố về quản lý nước thải.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 25, \"question_numbers\": []}, {\"en\": \"Please clarify the fee for me, and let me know if I can pick up my documents this week.\", \"vi\": \"Xin vui lòng giải thích rõ về khoản phí này cho tôi và cho tôi biết liệu tôi có thể đến nhận các tài liệu của mình trong tuần này hay không.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 26, \"question_numbers\": []}, {\"en\": \"Thank you.\", \"vi\": \"Xin cảm ơn.\", \"type\": \"paragraph\", \"doc_index\": 1, \"sentence_id\": 27, \"question_numbers\": []}, {\"en\": \"Best regards,\", \"vi\": \"Trân trọng,\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 28, \"question_numbers\": []}, {\"en\": \"Keith Brandenberg\", \"vi\": \"Keith Brandenberg\", \"type\": \"sign_off\", \"doc_index\": 1, \"sentence_id\": 29, \"question_numbers\": []}, {\"en\": \"City of Abilene Administrative Building\", \"vi\": \"Tòa nhà Hành chính Thành phố Abilene\", \"type\": \"metadata\", \"doc_index\": 2, \"sentence_id\": 30, \"question_numbers\": []}, {\"en\": \"Visitors must sign in prior to entering this facility.\", \"vi\": \"Quý vị khách tham quan phải đăng ký trước khi vào cơ sở này.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 31, \"question_numbers\": []}, {\"en\": \"Please enter your name and the room you will visit in the logbook.\", \"vi\": \"Xin vui lòng ghi tên và phòng mà quý vị sẽ đến thăm vào sổ đăng ký.\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 32, \"question_numbers\": []}, {\"en\": \"First-Floor Directory:\", \"vi\": \"Danh mục các phòng ban tại tầng 1:\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 33, \"question_numbers\": []}, {\"en\": \"IT Services - Room 100\", \"vi\": \"Dịch vụ Công nghệ Thông tin - Phòng 100\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 34, \"question_numbers\": []}, {\"en\": \"Parks and Recreation - Room 101\", \"vi\": \"Công viên và Giải trí - Phòng 101\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 35, \"question_numbers\": []}, {\"en\": \"Transportation - Room 102\", \"vi\": \"Giao thông vận tải - Phòng 102\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 36, \"question_numbers\": []}, {\"en\": \"Wastewater - Room 103\", \"vi\": \"Nước thải - Phòng 103\", \"type\": \"paragraph\", \"doc_index\": 2, \"sentence_id\": 37, \"question_numbers\": []}]' WHERE `id` = 'ba91c8c4-7d3d-40e3-8793-ee23dd8034f9';
